readme|README.txt|388|12AFDFFDF16E3161AE7395A1C95ED48AF0362FD4C5488D75214BBF3908EF73EE|Documentation; validated, never copied
hold|aeeba2be4de91a71890bfb47347c8b4cf217c5aa.simms|67108952|5E119E1332A0A6E7634D3C9A56E5F3992B26867F1E23ECE19C5A62BCDA521B85|Not documented by the Game Notes; validated, never installed
'@
    $entries = New-Object System.Collections.Generic.List[object]
    foreach ($line in ($rows -split "`r?`n")) {
        if ([string]::IsNullOrWhiteSpace($line)) { continue }
        $field = $line.Split('|')
        $folder = 'cps3-install'
        if ($field[0] -ceq 'nvram') { $folder = 'nvram' } elseif ($field[0] -ceq 'readme') { $folder = '' }
        $relative = if ($folder) { 'TeknoCPS/{0}/{1}' -f $folder, $field[1] } else { $field[1] }
        [void]$entries.Add([pscustomobject]@{
            Kind = $field[0]; Name = $field[1]; Length = [int64]$field[2]; Sha256 = $field[3]
            Folder = $folder; RelativePath = $relative
        })
    }
    return $entries.ToArray()
}

# Maps a user-chosen location to a source: a .zip archive, or a folder that
# contains a TeknoCPS folder (the extracted set root). Read-only.
function Resolve-TpmCps3SupplementarySource {
    param([AllowEmptyString()][AllowNull()][string]$Path)
    $result = [pscustomobject]@{ Valid = $false; Kind = ''; Path = ''; Error = '' }
    $text = ([string]$Path).Trim().Trim('"')
    if ([string]::IsNullOrWhiteSpace($text)) { $result.Error = 'No location was chosen.'; return $result }
    try { $full = [System.IO.Path]::GetFullPath($text) } catch { $result.Error = 'That is not a valid path.'; return $result }
    if (Test-Path -LiteralPath $full -PathType Leaf) {
        if ([System.IO.Path]::GetExtension($full) -ine '.zip') { $result.Error = 'Choose a folder or a .zip archive.'; return $result }
        $result.Valid = $true; $result.Kind = 'Archive'; $result.Path = $full
        return $result
    }
    if (-not (Test-Path -LiteralPath $full -PathType Container)) { $result.Error = 'That location was not found.'; return $result }
    if (-not (Test-Path -LiteralPath (Join-Path $full 'TeknoCPS') -PathType Container)) {
        $result.Error = 'That folder has no TeknoCPS folder inside it.'
        return $result
    }
    $result.Valid = $true; $result.Kind = 'Folder'; $result.Path = $full
    return $result
}

# Hashes a stream and, when DestinationPath is given, also writes it to a NEW
# file. Returns $true only when length and SHA-256 both match; a written file
# is deleted unless it verified.
function Invoke-TpmCps3VerifiedStream {
    param(
        [Parameter(Mandatory)][System.IO.Stream]$Source,
        [string]$DestinationPath = '',
        [Parameter(Mandatory)][int64]$ExpectedLength,
        [Parameter(Mandatory)][string]$ExpectedSha256
    )
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $out = $null
    $ok = $false
    try {
        if ($DestinationPath) {
            $out = New-Object System.IO.FileStream($DestinationPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None, 1048576)
        }
        $buffer = New-Object byte[] 1048576
        [int64]$total = 0
        while (($read = $Source.Read($buffer, 0, $buffer.Length)) -gt 0) {
            [void]$sha.TransformBlock($buffer, 0, $read, $null, 0)
            if ($out) { $out.Write($buffer, 0, $read) }
            $total += $read
            if ($total -gt $ExpectedLength) { break }
        }
        [void]$sha.TransformFinalBlock($buffer, 0, 0)
        if ($out) { $out.Flush() }
        $hash = (-join ($sha.Hash | ForEach-Object { $_.ToString('x2') })).ToUpperInvariant()
        $ok = ($total -eq $ExpectedLength -and $hash -ieq $ExpectedSha256)
    } finally {
        if ($out) { $out.Dispose() }
        $sha.Dispose()
        if ($DestinationPath -and -not $ok -and (Test-Path -LiteralPath $DestinationPath)) { Remove-Item -LiteralPath $DestinationPath -Force -ErrorAction SilentlyContinue }
    }
    return $ok
}

# Free bytes on the TeknoParrot drive, or $null when it cannot be determined
# (for example a UNC path); callers then rely on the transaction failing closed.
function Get-TpmCps3FreeBytes {
    param([Parameter(Mandatory)][string]$Path)
    try {
        $root = [System.IO.Path]::GetPathRoot([System.IO.Path]::GetFullPath($Path))
        if ($root -notmatch '^[A-Za-z]:\\') { return $null }
        return [int64](New-Object System.IO.DriveInfo($root)).AvailableFreeSpace
    } catch { return $null }
}

# True when a source member name could escape or confuse a path: empty or
# empty/./.. segments, backslashes, drive colons, control characters, a
# leading slash, or a segment ending in space/dot.
function Test-TpmCps3UnsafeMemberName {
    param([AllowEmptyString()][string]$Name)
    if ([string]::IsNullOrEmpty($Name) -or $Name -match '[\x00-\x1f\\:]' -or $Name.StartsWith('/')) { return $true }
    foreach ($segment in $Name.Split('/')) {
        if ($segment -eq '' -or $segment -eq '.' -or $segment -eq '..' -or $segment.EndsWith(' ') -or $segment.EndsWith('.')) { return $true }
    }
    return $false
}

# Read-only inventory of a source against the FULL manifest (installable files
# plus README and the held-back member). Reports missing, unexpected, unsafe
# (traversal-like names, reparse points), duplicate/case-colliding and wrong-size
# members. Found maps lower-case relative path -> source reference (file path or
# ZipArchiveEntry) only for members that exist exactly once with the pinned size.
# A folder source is read only at its top level plus below TeknoCPS.
function Get-TpmCps3SourceInventory {
    param([Parameter(Mandatory)]$Source, [Parameter(Mandatory)][object[]]$Manifest, $Zip = $null)
    $inventory = [pscustomobject]@{
        Found = @{}
        Missing = New-Object System.Collections.Generic.List[string]
        Extra = New-Object System.Collections.Generic.List[string]
        Unsafe = New-Object System.Collections.Generic.List[string]
        Ambiguous = New-Object System.Collections.Generic.List[string]
        SizeMismatch = New-Object System.Collections.Generic.List[string]
    }
    $byKey = @{}
    foreach ($entry in $Manifest) { $byKey[$entry.RelativePath.ToLowerInvariant()] = $entry }
    $seen = @{}
    $addSeen = {
        param([string]$Relative, $Reference, [int64]$Length)
        $key = $Relative.ToLowerInvariant()
        if (-not $seen.ContainsKey($key)) { $seen[$key] = New-Object System.Collections.Generic.List[object] }
        [void]$seen[$key].Add([pscustomobject]@{ Relative = $Relative; Reference = $Reference; Length = $Length })
    }
    if ($Zip) {
        # get_Entries(): the property read hides a bad member name on Windows PowerShell 5.1 and the ZIP would look empty.
        $zipEntries = @($Zip.get_Entries())
        # A set zipped by Explorer has exactly one outer folder around everything; strip that one folder. The manifest paths must still match exactly below it.
        $wrapper = ''
        $zipFiles = @($zipEntries | Where-Object { -not ([string]$_.FullName).EndsWith('/') })
        if ($zipFiles.Count -gt 0 -and @($zipFiles | Where-Object { ([string]$_.FullName) -notmatch '/' }).Count -eq 0) {
            $firstFolders = @($zipFiles | ForEach-Object { ([string]$_.FullName).Split('/')[0] } | Sort-Object -Unique)
            if ($firstFolders.Count -eq 1 -and $firstFolders[0] -ine 'TeknoCPS' -and -not (Test-TpmCps3UnsafeMemberName -Name $firstFolders[0])) { $wrapper = $firstFolders[0] + '/' }
        }
        foreach ($zipEntry in $zipEntries) {
            $name = [string]$zipEntry.FullName
            if ($name.EndsWith('/') -and $zipEntry.Length -eq 0) { continue }
            if (Test-TpmCps3UnsafeMemberName -Name $name) { [void]$inventory.Unsafe.Add($name); continue }
            if ($wrapper) { $name = $name.Substring($wrapper.Length) }
            & $addSeen $name $zipEntry ([int64]$zipEntry.Length)
        }
    } else {
        $root = $Source.Path.TrimEnd('\', '/')
        # A drive root trims to 'E:', which Get-ChildItem reads as the drive's current directory; list it with its separator and use the trimmed form only for relative names.
        $listRoot = if ($root -match '^[A-Za-z]:$') { $root + '\' } else { $root }
        foreach ($top in @(Get-ChildItem -LiteralPath $listRoot -Force -ErrorAction Stop)) {
            # Windows' own hidden system items at a drive root ('System Volume Information', '$RECYCLE.BIN') are not part of the user's files.
            if (($top.Attributes -band 6) -eq 6) { continue }
            if (($top.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { [void]$inventory.Unsafe.Add($top.Name); continue }
            if ($top.PSIsContainer -and $top.Name -ieq 'TeknoCPS') {
                # Manual walk: a reparse directory is reported Unsafe and never entered (Get-ChildItem -Recurse follows junctions on PS 5.1).
                $pendingDirs = New-Object 'System.Collections.Generic.Stack[string]'
                $pendingDirs.Push($top.FullName)
                while ($pendingDirs.Count -gt 0) {
                    $currentDir = $pendingDirs.Pop()
                    foreach ($item in @(Get-ChildItem -LiteralPath $currentDir -Force -ErrorAction Stop)) {
                        $relative = $item.FullName.Substring($root.Length).TrimStart('\', '/').Replace('\', '/')
                        if (($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { [void]$inventory.Unsafe.Add($relative); continue }
                        if ($item.PSIsContainer) { $pendingDirs.Push($item.FullName); continue }
                        & $addSeen $relative $item.FullName ([int64]$item.Length)
                    }
                }
            } elseif ($top.PSIsContainer) {
                [void]$inventory.Extra.Add($top.Name + '/')
            } else {
                & $addSeen $top.Name $top.FullName ([int64]$top.Length)
            }
        }
    }
    foreach ($key in @($seen.Keys)) {
        $group = $seen[$key]
        if (-not $byKey.ContainsKey($key)) { foreach ($member in $group) { [void]$inventory.Extra.Add($member.Relative) }; continue }
        $entry = $byKey[$key]
        if ($group.Count -gt 1) { [void]$inventory.Ambiguous.Add($entry.Name); continue }
        if ($group[0].Length -ne [int64]$entry.Length) { [void]$inventory.SizeMismatch.Add($entry.Name); continue }
        $inventory.Found[$key] = $group[0].Reference
    }
    foreach ($entry in $Manifest) {
        if (-not $seen.ContainsKey($entry.RelativePath.ToLowerInvariant())) { [void]$inventory.Missing.Add($entry.Name) }
    }
    return $inventory
}

# Installs CPS3 files from a user-chosen folder or .zip into <TpRoot>\TeknoCPS.
# Fail closed: before ANY destination write the whole source must match the
# pinned manifest exactly - every member (installable files, README, and the
# held-back undocumented cache) present once, no extra/unsafe/duplicate
# members, and every size and SHA-256 equal. Any inventory failure refuses the
# whole batch. Only the manifest's installable members are then promoted
# (names come from the manifest, never from the source) through
# Invoke-TpmTransactionalFileBatch: stage on the target volume, backup,
# no-reparse checks, final hash verification, verified rollback. Existing
# targets are never overwritten: identical = no-op, different .nv = preserved,
# different .simms = conflict unless -ReplaceDifferingCache (explicit user
# confirmation). A destination conflict is reported and preserved; the result is
# then not Complete. Complete means every installable target is present and
# matches, or was deliberately preserved (an existing .nv); it is a statement about
# the destination, and is never true for SOURCE_HAS_NO_CPS3_FILES (nothing was
# validated or installed). -Manifest exists so tests can supply synthetic fixtures.
function Invoke-TpmCps3SupplementaryInstall {
    param(
        [Parameter(Mandatory)][string]$SourcePath,
        [Parameter(Mandatory)][string]$TpRoot,
        [object[]]$Manifest = @(),
        [switch]$ReplaceDifferingCache
    )
    $manifestEntries = @($Manifest)
    if ($manifestEntries.Count -eq 0) { $manifestEntries = @(Get-TpmCps3SupplementaryManifest) }
    $installable = @($manifestEntries | Where-Object { $_.Kind -ceq 'cache' -or $_.Kind -ceq 'nvram' })
    $lists = [ordered]@{
        Installed = New-Object System.Collections.Generic.List[string]
        Replaced = New-Object System.Collections.Generic.List[string]
        AlreadyPresent = New-Object System.Collections.Generic.List[string]
        PreservedExisting = New-Object System.Collections.Generic.List[string]
        Conflicts = New-Object System.Collections.Generic.List[string]
        Blocked = New-Object System.Collections.Generic.List[string]
        Missing = New-Object System.Collections.Generic.List[string]
        Extra = New-Object System.Collections.Generic.List[string]
        Unsafe = New-Object System.Collections.Generic.List[string]
        Ambiguous = New-Object System.Collections.Generic.List[string]
        Mismatched = New-Object System.Collections.Generic.List[string]
    }
    $finish = {
        param([string]$Outcome, [string]$Reason, [string]$Summary, $Transaction = $null)
        $out = [ordered]@{ PSTypeName = 'TPM.Cps3SupplementaryResult.v1'; Outcome = $Outcome; ReasonCode = $Reason; Summary = $Summary; Transaction = $Transaction }
        foreach ($key in $lists.Keys) { $out[$key] = @($lists[$key].ToArray()) }
        $out['Complete'] = ($Outcome -in @('SUCCEEDED', 'NO_OP') -and $Reason -ne 'SOURCE_HAS_NO_CPS3_FILES' -and $lists.Conflicts.Count -eq 0 -and $lists.Blocked.Count -eq 0)
        $counts = (@($lists.Keys | ForEach-Object { '{0}={1}' -f $_.ToLowerInvariant(), $lists[$_].Count }) -join ' ')
        try { Write-Log "CPS3 supplementary: outcome=$Outcome reason=$Reason $counts" } catch { }
        return [pscustomobject]$out
    }

    if ([string]::IsNullOrWhiteSpace($TpRoot) -or -not (Test-Path -LiteralPath $TpRoot -PathType Container)) {
        return (& $finish 'FAILED_BEFORE_MUTATION' 'TP_ROOT_INVALID' 'The TeknoParrot folder was not found. Nothing was changed.')
    }
    $tpFull = Get-TpmFullFolderPath -Path $TpRoot
    if (-not (Test-TpmNoReparsePath -Path $tpFull)) {
        return (& $finish 'FAILED_BEFORE_MUTATION' 'TP_ROOT_UNSAFE' 'The TeknoParrot folder path is not safe to write to. Nothing was changed.')
    }
    $cpsRoot = Join-Path $tpFull 'TeknoCPS'
    $source = Resolve-TpmCps3SupplementarySource -Path $SourcePath
    if (-not $source.Valid) {
        return (& $finish 'FAILED_BEFORE_MUTATION' 'SOURCE_UNUSABLE' ($source.Error + ' Nothing was changed.'))
    }
    $isArchive = ($source.Kind -eq 'Archive')

    $zip = $null
    $createdCpsRoot = $false
    $stageBase = Join-Path $cpsRoot '.tpm-cps3-stage'
    $extractDir = $null
    $cps3VerificationLabel = $null
    $cps3VerificationCloseState = 'Error'
    try {
        # 1. Classify every installable destination (hashing only same-size existing files).
        $needs = New-Object System.Collections.Generic.List[object]
        $preserveOps = New-Object System.Collections.Generic.List[object]
        $started = Get-Date
        $index = 0
        foreach ($entry in $installable) {
            $index++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'CPS3 file check' -Current $index -Total $installable.Count -StartedAt $started
            $destination = Join-Path (Join-Path $cpsRoot $entry.Folder) $entry.Name
            $operation = 'ADD'
            $preHash = $null
            $destinationLong = ConvertTo-TpmAutoSyncLongPath -Path $destination
            if (Test-Path -LiteralPath $destinationLong) {
                try { $existing = Get-Item -LiteralPath $destinationLong -Force -ErrorAction Stop } catch { [void]$lists.Blocked.Add($entry.Name); continue }
                if ($existing.PSIsContainer -or (($existing.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0)) { [void]$lists.Blocked.Add($entry.Name); continue }
                $isSame = $false
                if ([int64]$existing.Length -eq [int64]$entry.Length) {
                    try { $preHash = Get-TpmAutoSyncSha256 -Path $existing.FullName } catch { [void]$lists.Blocked.Add($entry.Name); continue }
                    $isSame = ($preHash -ieq $entry.Sha256)
                }
                if ($isSame) { [void]$lists.AlreadyPresent.Add($entry.Name); continue }
                if ($entry.Kind -ceq 'nvram') {
                    [void]$lists.PreservedExisting.Add($entry.Name)
                    [void]$preserveOps.Add([pscustomobject]@{ ItemId = $entry.Name; Operation = 'PRESERVE'; DestinationPath = $destination; RootPath = $tpFull })
                    continue
                }
                if (-not $ReplaceDifferingCache) { [void]$lists.Conflicts.Add($entry.Name); continue }
                if (-not $preHash) {
                    try { $preHash = Get-TpmAutoSyncSha256 -Path $existing.FullName } catch { [void]$lists.Blocked.Add($entry.Name); continue }
                }
                $operation = 'REPLACE'
            }
            [void]$needs.Add([pscustomobject]@{ Entry = $entry; Operation = $operation; Destination = $destination; PreHash = $preHash })
        }
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'CPS3 file check' -Current $installable.Count -Total $installable.Count -StartedAt $started -Complete
        if ($needs.Count -eq 0) {
            $leftAsIs = ($lists.Conflicts.Count + $lists.PreservedExisting.Count) -gt 0
            return (& $finish 'NO_OP' 'NO_CHANGES_NEEDED' $(if ($leftAsIs) { 'The CPS3 files that differ were left as they are. Nothing was changed.' } else { 'Nothing needed to be copied. Nothing was changed.' }))
        }

        # 2. Inventory the WHOLE source before any destination write.
        if ($isArchive) {
            try {
                Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction Stop
                $zip = [System.IO.Compression.ZipFile]::OpenRead($source.Path)
            } catch {
                return (& $finish 'FAILED_BEFORE_MUTATION' 'ARCHIVE_UNREADABLE' 'The archive could not be opened as a .zip. Nothing was changed.')
            }
        }
        try {
            $inventory = Get-TpmCps3SourceInventory -Source $source -Manifest $manifestEntries -Zip $zip
        } catch {
            try { Write-Log ("CPS3 supplementary: source could not be read: {0}" -f $_.Exception.Message) } catch { }
            return (& $finish 'FAILED_BEFORE_MUTATION' 'SOURCE_UNREADABLE' 'The chosen location could not be read completely. Nothing was changed.')
        }
        foreach ($name in $inventory.Missing) { [void]$lists.Missing.Add($name) }
        foreach ($name in $inventory.Extra) { [void]$lists.Extra.Add($name) }
        foreach ($name in $inventory.Unsafe) { [void]$lists.Unsafe.Add($name) }
        foreach ($name in $inventory.Ambiguous) { [void]$lists.Ambiguous.Add($name) }
        foreach ($name in $inventory.SizeMismatch) { [void]$lists.Mismatched.Add($name) }
        if ($inventory.Found.Count -eq 0 -and $lists.Extra.Count -eq 0 -and $lists.Unsafe.Count -eq 0 -and $lists.Ambiguous.Count -eq 0 -and $lists.Mismatched.Count -eq 0) {
            # Nothing in the location is a CPS3 file: report that plainly, not as 103 "missing" files of a refused set.
            $lists.Missing.Clear()
            return (& $finish 'NO_OP' 'SOURCE_HAS_NO_CPS3_FILES' 'No CPS3 files were found in that location. Nothing was changed.')
        }
        $problems = @()
        if ($lists.Missing.Count -gt 0) { $problems += ('{0} expected file(s) missing' -f $lists.Missing.Count) }
        if ($lists.Extra.Count -gt 0) { $problems += ('{0} unexpected item(s)' -f $lists.Extra.Count) }
        if ($lists.Unsafe.Count -gt 0) { $problems += ('{0} unsafe item(s)' -f $lists.Unsafe.Count) }
        if ($lists.Ambiguous.Count -gt 0) { $problems += ('{0} duplicated name(s)' -f $lists.Ambiguous.Count) }
        if ($lists.Mismatched.Count -gt 0) { $problems += ('{0} file(s) of the wrong size' -f $lists.Mismatched.Count) }
        if ($problems.Count -gt 0) {
            # Names go to the log only; the screen gets one plain sentence with the counts.
            try { Write-Log ('CPS3 supplementary: set refused. missing=[{0}] unexpected=[{1}] unsafe=[{2}] duplicated=[{3}] wrong size=[{4}]' -f ($lists.Missing -join ', '), ($lists.Extra -join ', '), ($lists.Unsafe -join ', '), ($lists.Ambiguous -join ', '), ($lists.Mismatched -join ', ')) } catch { }
            $why = if ($inventory.Found.Count -eq 0 -and $lists.Missing.Count -gt 0 -and $lists.Extra.Count -gt 0) {
                'The ZIP or folder probably has an extra outer folder or other files, so {0} expected file(s) are missing and {1} other item(s) were found.' -f $lists.Missing.Count, $lists.Extra.Count
            } else {
                'The set is not complete or has files that do not belong ({0}).' -f ($problems -join ', ')
            }
            return (& $finish 'FAILED_BEFORE_MUTATION' 'SOURCE_INVENTORY_INVALID' ($why + ' Nothing was changed.'))
        }

        # 3. Space check (stage + promote on the target volume; archives also extract once).
        [int64]$needed = 64MB
        foreach ($need in $needs) {
            $needed += [int64]$need.Entry.Length * $(if ($isArchive) { 2 } else { 1 })
            if ($need.Operation -eq 'REPLACE') { $needed += [int64]$need.Entry.Length }
        }
        $free = Get-TpmCps3FreeBytes -Path $tpFull
        if ($null -ne $free -and $free -lt $needed) {
            return (& $finish 'FAILED_BEFORE_MUTATION' 'INSUFFICIENT_SPACE' ('There is not enough free space on the TeknoParrot drive: about {0} MB needed, {1} MB free. Nothing was changed.' -f [Math]::Ceiling($needed / 1MB), [Math]::Floor($free / 1MB)))
        }

        # 4. Verify the hash of EVERY member (installable or not) before any destination write.
        if (-not (Test-TpmNoReparsePath -Path $stageBase)) {
            return (& $finish 'FAILED_BEFORE_MUTATION' 'STAGING_UNSAFE' 'The TeknoCPS folder path is not safe to write to. Nothing was changed.')
        }
        $createdCpsRoot = -not (Test-Path -LiteralPath $cpsRoot)
        [void][System.IO.Directory]::CreateDirectory($stageBase)
        if ($isArchive) {
            $extractDir = Join-Path $stageBase ('extract-' + [guid]::NewGuid().ToString('N'))
            [void][System.IO.Directory]::CreateDirectory($extractDir)
        }
        $needByKey = @{}
        foreach ($need in $needs) { $needByKey[$need.Entry.RelativePath.ToLowerInvariant()] = $need }
        $verifiedPath = @{}
        $started = Get-Date
        $index = 0
        $cps3VerificationLabel = if ($isArchive) { 'CPS3 extraction and verification' } else { 'CPS3 source verification' }
        foreach ($entry in $manifestEntries) {
            $index++
            Write-TpmCompactExtractionProgress -Phase Checking -Label $cps3VerificationLabel -Current $index -Total $manifestEntries.Count -StartedAt $started
            $key = $entry.RelativePath.ToLowerInvariant()
            $reference = $inventory.Found[$key]
            $need = $needByKey[$key]
            $good = $false
            $path = $null
            try {
                if ($isArchive) {
                    $stagePath = if ($need) { Join-Path $extractDir $entry.Name } else { '' }
                    $stream = $reference.Open()
                    try { $good = Invoke-TpmCps3VerifiedStream -Source $stream -DestinationPath $stagePath -ExpectedLength $entry.Length -ExpectedSha256 $entry.Sha256 }
                    finally { $stream.Dispose() }
                    if ($good -and $need) { $path = $stagePath }
                } else {
                    $good = ((Get-TpmAutoSyncSha256 -Path $reference) -ieq $entry.Sha256)
                    if ($good -and $need) { $path = $reference }
                }
            } catch {
                $good = $false
                try { Write-Log ("CPS3 supplementary: could not read {0}: {1}" -f $entry.Name, $_.Exception.Message) } catch { }
            }
            if (-not $good) { [void]$lists.Mismatched.Add($entry.Name); continue }
            if ($need) { $verifiedPath[$key] = $path }
        }
        Write-TpmCompactExtractionProgress -Phase Checking -Label $cps3VerificationLabel -Current $manifestEntries.Count -Total $manifestEntries.Count -StartedAt $started -Complete -Outcome $(if ($lists.Mismatched.Count -eq 0) { 'Final' } else { 'Error' })
        $cps3VerificationLabel = $null
        if ($lists.Mismatched.Count -gt 0) {
            return (& $finish 'FAILED_BEFORE_MUTATION' 'SOURCE_INVENTORY_INVALID' ('{0} file(s) did not match their expected checksum, so the set was refused. Nothing was changed.' -f $lists.Mismatched.Count))
        }

        # 5. Promote through the shared transaction primitive.
        $operations = New-Object System.Collections.Generic.List[object]
        foreach ($need in $needs) {
            $operation = [ordered]@{
                ItemId = $need.Entry.Name; Operation = $need.Operation; SourcePath = $verifiedPath[$need.Entry.RelativePath.ToLowerInvariant()]
                DestinationPath = $need.Destination; RootPath = $tpFull; ExpectedSourceHash = $need.Entry.Sha256; ExpectedFinalHash = $need.Entry.Sha256
            }
            if ($need.Operation -eq 'REPLACE') { $operation['ExpectedDestinationHash'] = $need.PreHash }
            [void]$operations.Add([pscustomobject]$operation)
        }
        foreach ($preserve in $preserveOps) { [void]$operations.Add($preserve) }
        $transaction = Invoke-TpmTransactionalFileBatch `
            -WorkflowKey 'Cps3Supplementary' -OperationKey 'InstallCacheFiles' `
            -Operations $operations.ToArray() -StagingDir $stageBase `
            -Summary 'The CPS3 files were not installed.' `
            -SuccessSummary 'The CPS3 files were copied and verified.' `
            -NoOpSummary 'Everything already matches. Nothing was changed.' `
            -ReasonCode 'CPS3_FILE_TRANSACTION_FAILED'
        if ([string]$transaction.Outcome -eq 'SUCCEEDED') {
            foreach ($operation in $operations) {
                if ($operation.Operation -eq 'ADD') { [void]$lists.Installed.Add($operation.ItemId) }
                elseif ($operation.Operation -eq 'REPLACE') { [void]$lists.Replaced.Add($operation.ItemId) }
            }
        }
        return (& $finish ([string]$transaction.Outcome) ([string]$transaction.ReasonCode) ([string]$transaction.Summary) $transaction)
    } catch [System.Management.Automation.PipelineStoppedException] {
        $cps3VerificationCloseState = 'Cancelled'
        throw
    } finally {
        if ($cps3VerificationLabel) {
            try { Write-TpmCompactExtractionProgress -Phase Checking -Label $cps3VerificationLabel -Current $index -Total $manifestEntries.Count -StartedAt $started -Complete -Outcome $cps3VerificationCloseState }
            catch { try { Write-Log "CPS3 verification progress close failed: $_" } catch {} }
        }
        if ($zip) { $zip.Dispose() }
        try {
            if ($extractDir -and (Test-Path -LiteralPath $extractDir)) { Remove-Item -LiteralPath $extractDir -Recurse -Force -ErrorAction Stop }
            if ((Test-Path -LiteralPath $stageBase) -and @(Get-ChildItem -LiteralPath $stageBase -Force -ErrorAction Stop).Count -eq 0) { Remove-Item -LiteralPath $stageBase -Force -ErrorAction Stop }
            if ($createdCpsRoot -and (Test-Path -LiteralPath $cpsRoot) -and @(Get-ChildItem -LiteralPath $cpsRoot -Force -ErrorAction Stop).Count -eq 0) { Remove-Item -LiteralPath $cpsRoot -Force -ErrorAction Stop }
        } catch {
            try { Write-Log ("CPS3 supplementary: staging cleanup incomplete: {0}" -f $_.Exception.Message) } catch { }
        }
    }
}

# Interactive optional step. Offered only when CPS3 (cps_*) profiles are
# registered. Asks the user to choose a folder/.zip they already have; never
# says where to get the files. Returns the install result, or $null when
# skipped.
function Invoke-TpmCps3SupplementaryOffer {
    param(
        [Parameter(Mandatory)][string]$TpRoot,
        [Parameter(Mandatory)][string]$UserProfilesDir
    )
    $cpsProfiles = @()
    if ($UserProfilesDir -and (Test-Path -LiteralPath $UserProfilesDir -PathType Container)) {
        $cpsProfiles = @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter 'cps_*.xml' -File -ErrorAction SilentlyContinue)
    }
    if ($cpsProfiles.Count -eq 0) { return $null }
    Write-Host ""
    Write-Host "============================================" -ForegroundColor DarkCyan
    Write-Host "   OPTIONAL: Capcom CPS3 first-boot files" -ForegroundColor DarkCyan
    Write-Host "============================================" -ForegroundColor DarkCyan
    Write-Host ""
    Write-Host "  You have CPS3 games registered (Street Fighter III, JoJo, Red Earth,"
    Write-Host "  or the CPS3 multi-game). TeknoParrot builds a cache file the first"
    Write-Host "  time each CPS3 disc image runs, so the first boot is slow."
    Write-Host ""
    Write-Host "  If you already have the matching TeknoCPS cache and NVRAM files,"
    Write-Host "  TeknoParrot Manager can copy them into your TeknoParrot folder. It does"
    Write-Host "  not provide, download, or point to these files, and it never overwrites"
    Write-Host "  an existing file without asking. The Eggman DAT and the Eggman Game"
    Write-Host "  Notes page (https://eggmansworld.github.io/TeknoParrot/) document them."
    Write-Host "  TeknoParrot Manager only accepts the complete, unmodified set (a folder"
    Write-Host "  that holds a TeknoCPS folder plus README.txt, or the .zip of that set)."
    Write-Host "  Anything missing, extra, or changed is refused and nothing is changed."
    Write-Host ""
    Write-Host "  Without them your games still work; the first boot is just slower." -ForegroundColor DarkCyan
    Write-Host ""
    $answer = Read-TpmYesNo -Prompt '  Copy CPS3 files you already have? (Y/N, default N)' -Default 'N'
    if ($answer -ne 'Y') {
        Write-Host "  Skipped. Nothing was changed. Your CPS3 games still work (slower first boot)." -ForegroundColor DarkGray
        Write-Log 'CPS3 supplementary: offer declined.'
        return $null
    }
    Write-Host ""
    Write-Host "  Where are the files?"
    Write-Host "    F) A folder (the extracted files)"
    Write-Host "    Z) A .zip archive"
    Write-Host "    C) Cancel"
    $where = Read-TpmChoice -Prompt '  Choose F, Z, or C' -Choices @('F', 'Z', 'C') -Default 'C'
    $chosen = ''
    if ($where -eq 'F') {
        $chosen = Read-PathWithBrowse -Prompt '  Folder that contains the TeknoCPS folder and README.txt' -Mode Folder
    } elseif ($where -eq 'Z') {
        $chosen = Read-PathWithBrowse -Prompt '  Path to the .zip archive' -Mode File -FileFilter 'Zip archives (*.zip)|*.zip|All files (*.*)|*.*'
    }
    if ([string]::IsNullOrWhiteSpace($chosen)) {
        Write-Host "  No location chosen. Nothing was changed. Your CPS3 games still work (slower first boot)." -ForegroundColor DarkGray
        Write-Log 'CPS3 supplementary: no source chosen.'
        return $null
    }
    $replace = $false
    $priorInstalled = 0
    $result = $null
    for ($pass = 1; $pass -le 2; $pass++) {
        try {
            $result = Invoke-TpmProgressGroup -Title 'CPS3 files' -Action { Invoke-TpmCps3SupplementaryInstall -SourcePath $chosen -TpRoot $TpRoot -ReplaceDifferingCache:$replace }
        } catch {
            Write-Host ("  The CPS3 step could not finish: {0}" -f $_.Exception.Message) -ForegroundColor Red
            Write-Log ("CPS3 supplementary: failed: {0}" -f $_.Exception.Message)
            return $null
        }
        if ($pass -eq 1 -and $result -and @($result.Conflicts).Count -gt 0 -and $result.Outcome -in @('NO_OP', 'SUCCEEDED')) {
            Write-Host ""
            Write-Host ("  {0} existing CPS3 cache file(s) differ from the expected ones and were left alone." -f @($result.Conflicts).Count) -ForegroundColor Yellow
            Write-Host "  They are regenerable caches. Replacing keeps a recovery copy until the new files verify."
            $again = Read-TpmYesNo -Prompt '  Replace them with the verified files from your location? (Y/N, default N)' -Default 'N'
            if ($again -eq 'Y') { $priorInstalled = @($result.Installed).Count; $replace = $true; continue }
        }
        break
    }
    Write-Host ""
    Write-Log ('CPS3 supplementary: outcome={0}.' -f $result.Outcome)
    if ($result.Outcome -eq 'SUCCEEDED') {
        Write-Host ("  Copied and verified {0} file(s)." -f ($priorInstalled + @($result.Installed).Count + @($result.Replaced).Count)) -ForegroundColor Green
    } elseif ($result.Outcome -eq 'NO_OP') {
        Write-Host ("  {0}" -f $result.Summary) -ForegroundColor DarkGray
    } elseif ($result.Outcome -in @('FAILED_BEFORE_MUTATION', 'ROLLED_BACK_VERIFIED')) {
        Write-Host ("  The CPS3 files were not installed. {0}" -f $result.Summary) -ForegroundColor Yellow
    } elseif ($result.Outcome -eq 'CLEANUP_RESIDUE') {
        Write-Host ("  The CPS3 step ended in a verified state, but cleanup was not finished. {0}" -f $result.Summary) -ForegroundColor Yellow
    } else {
        # ACTION_REQUIRED or anything else: rollback may be unverified, so some CPS3 files may be on disk. Never say "not installed" here.
        Write-Host ("  The CPS3 install stopped and TeknoParrot Manager could not verify the final state. Some CPS3 files may already be in the TeknoCPS folder. {0}" -f $result.Summary) -ForegroundColor Red
        $unverifiedNames = @()
        if ($result.Transaction -and $result.Transaction.Rollback) { $unverifiedNames = @($result.Transaction.Rollback.FailedItems) }
        if ($unverifiedNames.Count -gt 0) {
            $unverifiedText = (@($unverifiedNames | Select-Object -First 10) -join ', ')
            if ($unverifiedNames.Count -gt 10) { $unverifiedText += ', ...' }
            Write-Host ("  Not restored or not verified: {0}" -f $unverifiedText) -ForegroundColor Red
        }
    }
    if ($priorInstalled -gt 0 -and $result.Outcome -ne 'SUCCEEDED') { Write-Host ("  Earlier in this step, {0} file(s) were copied and verified." -f $priorInstalled) -ForegroundColor DarkGray }
    if (@($result.AlreadyPresent).Count -gt 0) { Write-Host ("  Already present and matching: {0}" -f @($result.AlreadyPresent).Count) -ForegroundColor DarkGray }
    if (@($result.PreservedExisting).Count -gt 0) { Write-Host ("  Your existing NVRAM files kept unchanged: {0}" -f @($result.PreservedExisting).Count) -ForegroundColor DarkGray }
    if (@($result.Conflicts).Count -gt 0 -and @($result.Replaced).Count -eq 0) { Write-Host ("  Existing cache files left unchanged: {0}" -f @($result.Conflicts).Count) -ForegroundColor Yellow }
    foreach ($problem in @(@('Missing', 'expected file(s) missing'), @('Extra', 'unexpected item(s) in the location'), @('Unsafe', 'unsafe item(s)'), @('Ambiguous', 'duplicated name(s)'), @('Mismatched', 'file(s) with the wrong size or checksum'))) {
        $found = @($result.($problem[0]))
        if ($found.Count -gt 0) { Write-Host ("  Refused set - {0}: {1}" -f $problem[1], $found.Count) -ForegroundColor Yellow }
    }
    if (@($result.Blocked).Count -gt 0) { Write-Host ("  Existing target could not be safely read and was left alone: {0}" -f @($result.Blocked).Count) -ForegroundColor Yellow }
    return $result
}

# Logs a SHA256 audit trail for a binary downloaded from a third-party
# source (GitHub Releases, a raw repo file, etc). None of the sources this
# script pulls from publish checksums to verify against, and most of the
# binaries are unsigned community builds, so there is no real trust anchor
# to enforce a pass/fail check against -- this does not block or validate
# anything. It exists so a user who wants to verify what was actually
# fetched (or diagnose a corrupted/tampered download after the fact) has a
# source URL + filename + hash + timestamp on record without having to
# reproduce the download themselves.
function Write-DownloadAudit {
    param([string]$Source, [string]$FileName, [string]$Path, [string]$Version = "")
    try {
        $hash = (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash
        $verPart = if ($Version) { " Version=$Version" } else { "" }
        Write-Log "DownloadAudit: File=$FileName$verPart SHA256=$hash Source=$Source"
    } catch {
        Write-Log "DownloadAudit: could not hash $FileName -- $_"
    }
}

# Splits a TeknoParrot <ExecutableName> value into its alternatives.
# The field can contain multiple candidates separated by ; or | (e.g.
# "apacheM_HD.elf;apacheM.elf" or "game|game.bin"). Returns all non-empty parts.
function Get-ExeAlternatives {
    param([string]$exeName)
    return @($exeName -split '[;|]' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' })
}

# Scans common install locations for TeknoParrotUi.exe and returns matching
# root folder paths. Used to suggest the path on first run so the user does
# not have to type it from memory. Checks LaunchBox emulator folders, drive
# roots, and standard Program Files locations on every mounted local drive.
function Find-TeknoParrotRoot {
    $candidates = New-Object System.Collections.ArrayList
    $up = $env:USERPROFILE
    if ($up) {
        [void]$candidates.Add((Join-Path $up "LaunchBox\Emulators\TeknoParrot"))
        [void]$candidates.Add((Join-Path $up "AppData\Roaming\LaunchBox\Emulators\TeknoParrot"))
    }
    # Fetch drive type info ONCE for this whole scan (issue #5) -- both for
    # the hard-timeout job-spawn cost and to avoid the pre-existing
    # inefficiency of re-running GetDrives() once per candidate drive letter.
    $localDriveInfo = Get-LocalDriveInfoSafe
    # Unreadable drive types (null) mean unknown, not "local" (see Test-IsNetworkPath): probing every drive could hang on an offline
    # mapped drive, so then only the profile folders above are checked. Only a drive proven local (-eq $false) is probed.
    $drives = @(Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue |
                Where-Object { $_.Root -and $null -ne $localDriveInfo -and (Test-IsNetworkPath $_.Root -Drives $localDriveInfo) -eq $false -and (Test-Path -LiteralPath $_.Root) } |
                ForEach-Object { $_.Root.TrimEnd('\') })
    foreach ($d in $drives) {
        [void]$candidates.Add("$d\TeknoParrot")
        [void]$candidates.Add("$d\Games\TeknoParrot")
        [void]$candidates.Add("$d\Emulators\TeknoParrot")
        [void]$candidates.Add("$d\Program Files\TeknoParrot")
        [void]$candidates.Add("$d\Program Files (x86)\TeknoParrot")
    }
    $found = New-Object System.Collections.ArrayList
    foreach ($path in $candidates) {
        if ((Test-Path -LiteralPath (Join-Path $path "TeknoParrotUi.exe")) -and
            $found -notcontains $path) {
            [void]$found.Add($path)
        }
    }
    return ,$found   # comma prevents PS 5.1 from unwrapping the ArrayList into individual strings
}

# Find-TeknoParrotRoot returns one ArrayList (so @() would wrap it). Callers that
# need a plain list of root paths use this: each detected path is its own item.
function Get-TpmDetectedRootList {
    foreach ($detectedRoot in (Find-TeknoParrotRoot)) { [string]$detectedRoot }
}

function Wait-TpmForProcessClose {
    param([Parameter(Mandatory)][string[]]$ProcessNames, [Parameter(Mandatory)][string]$FriendlyName)
    while ($true) {
        $running = @(foreach ($name in $ProcessNames) { Get-Process -Name $name -ErrorAction SilentlyContinue })
        if ($running.Count -eq 0) { return $true }
        Write-Host ("  {0} is still open. TeknoParrot Manager needs it closed before it can safely continue." -f $FriendlyName) -ForegroundColor Yellow
        Write-Host '  Save any work in that window. TeknoParrot Manager will not force-close it because unsaved work could be lost.' -ForegroundColor DarkGray
        if ((Read-HostSafe '  Close it, then press Enter to check again, or N to cancel').ToUpperInvariant() -eq 'N') { return $false }
        $deadline = (Get-Date).ToUniversalTime().AddSeconds(30)
        while ((Get-Date).ToUniversalTime() -lt $deadline) {
            $running = @(foreach ($name in $ProcessNames) { Get-Process -Name $name -ErrorAction SilentlyContinue })
            if ($running.Count -eq 0) { return $true }
            Start-Sleep -Milliseconds 250
        }
        Write-Host ("  TeknoParrot Manager still sees {0}. It will keep your selected operation ready while you finish closing it." -f $FriendlyName) -ForegroundColor Yellow
    }
}




# =============================================================================
# FUZZY FOLDER-NAME MATCHING  (Feature: NESiCAxLive / shared-exe games)
# =============================================================================
#
# Many platforms (NESiCAxLive, NESiCA, Sega RingEdge 2, etc.) share a single
# executable name (e.g. "game.exe") across dozens of titles. The script cannot
# distinguish them by exe name alone. This block lets it match the FOLDER NAME
# (e.g. "Akai Katana Shin (2012)[Taito NESiCAxLive][TP]") against the profile
# code (e.g. "AkaiKatanaShinNesica") using normalized bigram similarity.
#
# Games above $FuzzyAutoThreshold are registered automatically.
# Games below the threshold appear in ACTION REQUIRED with the best-guess
# profile shown so manual registration is easier.

# Normalizes a game name or profile code for fuzzy comparison. Strips years,
# bracketed and parenthesized metadata, non-alphanumeric characters, and
# lowercases the result. Also splits CamelCase profile codes into separate
# tokens so "AkaiKatanaShin" and "Akai Katana Shin" converge to the same form.
function Get-NormalizedGameKey {
    param([string]$s)
    # CamelCase split, two passes:
    #  Pass 1 -- standard boundary: lowercase -> uppercase ("AkaiKatana" -> "Akai Katana")
    $s = [regex]::Replace($s, '(?<=[a-z])(?=[A-Z])', ' ')
    #  Pass 2 -- acronym boundary: uppercase -> uppercase+lowercase ("NBANesica" -> "NBA Nesica")
    #  This handles profile codes that begin with an acronym followed by a word.
    $s = [regex]::Replace($s, '(?<=[A-Z])(?=[A-Z][a-z])', ' ')
    #  Known edge case: brand names with non-standard capitalization like "NESiCAxLive"
    #  split as "NESi CAx Live" on pass 1 (i->C boundary). This does not affect match
    #  accuracy because (a) both folder name and profile code go through the same
    #  normalization so Dice scores converge symmetrically, and (b) "NESiCAxLive"
    #  appears in square-bracket metadata ([Taito NESiCAxLive]) which is stripped
    #  by the bracket removal step BEFORE this function runs.
    # Remove year-in-parens like (2012)
    $s = $s -replace '\(\d{4}\)', ''
    # Remove square-bracket metadata [Taito NESiCAxLive][TP]
    $s = $s -replace '\[[^\]]*\]', ''
    # Remove full ISO date strings like (2015-12-28) (2007-02-15) used in Eggman dat names.
    # Must run before the decimal-version strip so (2015-12-28) is removed as a whole.
    $s = $s -replace '\(\d{4}-\d{2}-\d{2}\)', ''
    # Remove decimal version strings without ver/v prefix: (2.10.00) (1.00.48)
    $s = $s -replace '\(\d+\.\d[\d\.]*\)', ''
    # Remove known region/territory codes used in Eggman dat names.
    # Explicit list avoids accidentally stripping Roman numerals (II, III) or
    # meaningful abbreviations (SE) that could appear in game titles.
    # "World" is included here (not just JPN/USA/EUR/...) since it is also a
    # bare release-region descriptor in Eggman dat names, e.g. (World) -- see
    # issue #80 (Time Crisis 4). Anchored the same way as the rest of this
    # list, so it only strips a parenthetical that is exactly "(World)", never
    # compound title text like "(World Tour)".
    $s = $s -replace '\((JPN|USA|EUR|EXP|JP|US|KOR|AUS|ASI|INTL|ARC|UNK|World)\)', ''
    # Remove version strings like (ver 1.1) (rev 2) (v3) (v1.2b).
    # Meaningful parenthesized names such as (Special Edition) are intentionally
    # preserved -- they may be the only differentiator between two game titles.
    $s = $s -replace '\((ver\.?|rev\.?|v)\s*[\d\.]+[a-z]?\)', ''
    # Remove Namco-style board/revision-code tokens that precede a ver/rev/v
    # keyword, e.g. (TE51 Ver B), (TST1 Ver A), (B3900076A Ver 2.02J) -- see
    # issue #80. These carry no title information; older RomVault-derived
    # folder names include them while the current Eggman dat's canonical
    # names do not, so they block exact-match/fuzzy-match convergence.
    # The board-code prefix is REQUIRED (not optional): scope is deliberately
    # limited to "alphanumeric code + ver/rev/v + revision", not to bare
    # "(Rev C)" / "(Rev E)"-style tokens with no code prefix. A bare revision
    # marker is a weaker signal that it's board-revision noise rather than a
    # meaningful disambiguator, and real folder names in the wild (F-Zero AX
    # "(Rev E)", Wangan Midnight Maximum Tune "(Rev B)") already match
    # successfully today using that exact bare text -- stripping it would be
    # unscoped beyond what issue #80's four target titles need and was not
    # validated against those cases.
    $s = $s -replace '\([A-Za-z0-9]{1,10}\s+(?:ver\.?|rev\.?|v)\s*(?:[\d\.]+[a-z]?|[A-Z])\)', ''
    # Remove Namco-style hyphenated board-code tokens with no ver/rev/v
    # keyword, e.g. (TSF1002-NA-A) -- see issue #80 (Time Crisis 4). Anchored
    # to require the entire parenthetical to be uppercase letters, digits,
    # and hyphens only, with no spaces or lowercase -- natural-language title
    # or edition text essentially never matches this shape.
    $s = $s -replace '\([A-Z]{1,4}\d{2,6}(-[A-Z0-9]{1,4}){1,3}\)', ''
    # Remove parenthesized pure numbers like (2) (12) that carry no game-name info.
    $s = $s -replace '\(\d+\)', ''
    # Strip everything non-alphanumeric (spaces, hyphens, apostrophes, colons...).
    # \p{L} matches any Unicode letter so accented and non-Latin characters are
    # preserved instead of being silently dropped, keeping Dice scores valid.
    $s = $s -replace '[^\p{L}0-9]', ''
    return $s.ToLowerInvariant()
}

# Closed, stable set of English function words -- grammar, not game-naming
# convention, so unlike an edition-marker vocabulary this does not need
# ongoing curation as new titles/re-releases appear. See issue #84.
$script:TitleTokenStopWords = [System.Collections.Generic.HashSet[string]]::new(
    [string[]]@('the', 'of', 'a', 'an', 'and', 'vs', 'vs.', 'in', 'for', 'to'),
    [System.StringComparer]::OrdinalIgnoreCase)

# Extracts the "meaningful" words from a game title for Register-Games' Pass-2
# dat-name fuzzy-fallback guard (issue #84) -- a separate extraction path from
# Get-NormalizedGameKey, not a reuse of it: that function intentionally keeps
# some parenthetical content (e.g. "(Special Edition)") for its own bigram-key
# purposes, while this needs real word boundaries to do a word-SET comparison.
# Strips all parenthetical/bracket content wholesale rather than trying to
# classify "meaningful vs. noise" parenthetical text -- every confirmed real
# edition/variant marker (EX, Plus, Tuned, R, DX, Special, SIGN, Rev2, Climax,
# Dark Resurrection, Fated Retribution) appears as plain title text, never
# inside parens, so this scope is sufficient without solving that harder,
# separate problem. Excludes pure digits and roman numerals I-X (sequel
# numbering, already handled elsewhere by digit-preserving normalization) and
# the stop-word list above. Deliberately does NOT exclude short tokens --
# single-character markers like "R" are real, confirmed differentiators
# (e.g. "Virtua Fighter 5" vs "Virtua Fighter 5 R", both real dat entries).
function Get-MeaningfulTitleTokens {
    param([string]$title)
    $result = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    if (-not $title) { return $result }
    $stripped = $title -replace '\[[^\]]*\]', '' -replace '\([^\)]*\)', ''
    # I-X, not just II-X: no standalone "I" appears anywhere in the real
    # Eggman collection dat (confirmed by direct search, issue #84 review),
    # and roman-numeral sequel numbering is symmetrical -- there is no
    # evidence "I" specifically needs different treatment from "II"/"III"/etc.
    $romanNumerals = 'i', 'ii', 'iii', 'iv', 'v', 'vi', 'vii', 'viii', 'ix', 'x'
    foreach ($m in [regex]::Matches($stripped, '[\p{L}0-9]+')) {
        $w = $m.Value.ToLowerInvariant()
        if ($w -match '^\d+$') { continue }
        if ($romanNumerals -contains $w) { continue }
        if ($script:TitleTokenStopWords.Contains($w)) { continue }
        [void]$result.Add($w)
    }
    return $result
}

# Sorensen-Dice coefficient on character bigrams for two pre-normalized strings.
# Returns [0.0, 1.0]. Strings shorter than 2 chars cannot form bigrams -> 0.0.
function Get-DiceSimilarity {
    param([string]$a, [string]$b)
    if ($a.Length -lt 2 -or $b.Length -lt 2) { return 0.0 }
    $ba = @{}
    for ($i = 0; $i -lt $a.Length - 1; $i++) {
        $k = $a.Substring($i, 2)
        $ba[$k] = ($ba[$k] -as [int]) + 1   # -as [int]: null (missing key) becomes 0
    }
    $bb = @{}
    for ($i = 0; $i -lt $b.Length - 1; $i++) {
        $k = $b.Substring($i, 2)
        $bb[$k] = ($bb[$k] -as [int]) + 1
    }
    $inter = 0
    foreach ($k in $ba.Keys) { if ($bb.ContainsKey($k)) { $inter += [Math]::Min($ba[$k], $bb[$k]) } }
    $totalA = 0; foreach ($v in $ba.Values) { $totalA += $v }
    $totalB = 0; foreach ($v in $bb.Values) { $totalB += $v }
    if (($totalA + $totalB) -eq 0) { return 0.0 }
    return [double](2 * $inter) / ($totalA + $totalB)
}

# The normalized game title in a folder or ZIP name, without the notes that follow it in parentheses or brackets
# (for example "Raiden IV (1.03J)(Landscape,Bezel)[Taito NESiCAxLive]" gives the key of "Raiden IV").
# Returns '' when nothing is left. Used only as an extra score next to the full-name score, never in place of it.
function Get-TpmBaseTitleKey {
    param([AllowNull()][string]$Name)
    if ([string]::IsNullOrWhiteSpace($Name)) { return '' }
    $title = [regex]::Replace($Name, '\s*[\(\[].*$', '')
    if ([string]::IsNullOrWhiteSpace($title)) { return '' }
    return (Get-NormalizedGameKey $title)
}

# Minimum Dice similarity required to auto-register a fuzzy match. Anything at
# or above this score is registered automatically; anything below appears in
# ACTION REQUIRED with the best-guess profile name shown.
$FuzzyAutoThreshold = 0.72

# Minimum score gap required between the best and runner-up candidate for the
# best one to be trusted as an auto-register decision. Without this, two
# different profiles that both happen to score at or above
# $FuzzyAutoThreshold against the same folder name were resolved purely by
# which one the candidate loop iterated to last -- no actual signal preferred
# one over the other. Set to 0.1 (not a tighter value like 0.05) because the
# audit's own real near-miss example -- a folder one character off from the
# real title vs. one character over -- produced a gap of ~0.083, which a
# tighter margin would not have caught. See issue #15.
$FuzzyTieMargin = 0.1

# Resolves the best fuzzy-match candidate for $NormFolder among $MatchList
# (profiles that share one generic executable name, e.g. "game.exe"),
# applying the $RawThrillsAliases short-name fallback the same way the
# original inline Register-Games loop did. Tracks the runner-up score too, so
# a near-tie at/above $FuzzyAutoThreshold can be told apart from a clear,
# unambiguous winner -- IsConfidentMatch is false for both "below threshold"
# and "too close to call", and the caller already has a safe fallback path
# (dat lookup, then manual-registration ACTION REQUIRED) for both. See
# issue #15.
function Resolve-BestFuzzyMatch {
    param([string]$NormFolder, [array]$MatchList, [hashtable]$RawThrillsAliases, [string]$NormBaseTitle = '', [hashtable]$AlternateNames = $null)
    $best = $null; $bestScore = 0.0; $secondScore = 0.0; $bestIsExact = $false; $exactCount = 0
    foreach ($cand in $MatchList) {
        $normCode = Get-NormalizedGameKey $cand.Code
        $keys = @($normCode)
        # TeknoParrot's own name for the game (Metadata\<code>.json) is a second name for the same profile, for example
        # "Golden Tee Live 2023-2024" for GoldenTeeLive2023. It is only an extra key; the profile code is always scored too.
        if ($null -ne $AlternateNames -and $AlternateNames.ContainsKey($cand.Code)) {
            $normAltName = Get-NormalizedGameKey ([string]$AlternateNames[$cand.Code])
            if ($normAltName) { $keys += $normAltName }
        }
        $score = 0.0
        foreach ($key in $keys) {
            $keyScore = Get-DiceSimilarity $NormFolder $key
            # A folder name often carries notes in parentheses or brackets after the title, for example "(Landscape,Bezel)" or "(fixed video)".
            # They are not part of the game's name and pull the score down, so the title before the first note is scored as well.
            # The better of the two scores is used; the same tie rule below still applies.
            if ($NormBaseTitle) {
                $baseScore = Get-DiceSimilarity $NormBaseTitle $key
                if ($baseScore -gt $keyScore) { $keyScore = $baseScore }
            }
            if ($keyScore -gt $score) { $score = $keyScore }
        }
        if ($RawThrillsAliases.ContainsKey($cand.Code)) {
            $normAlias  = Get-NormalizedGameKey $RawThrillsAliases[$cand.Code].Suggested
            $aliasScore = Get-DiceSimilarity $NormFolder $normAlias
            if ($aliasScore -gt $score) { $score = $aliasScore }
        }
        $isExact = ($NormFolder.Length -gt 0 -and $keys -ccontains $NormFolder)
        if ($isExact) { $exactCount++ }
        if ($score -gt $bestScore) {
            $secondScore = $bestScore
            $bestScore   = $score
            $best        = $cand
            $bestIsExact = $isExact
        } elseif ($score -gt $secondScore) {
            $secondScore = $score
        }
    }
    # Two years of one game ("Golden Tee Live 2020" and "Golden Tee Live 2021") score within the tie margin of each other, so a folder
    # that names one of them exactly would never be trusted. When exactly one candidate has the folder's whole name and it also scores strictly higher than every other, it wins.
    $isTie = ($secondScore -gt 0) -and (($bestScore - $secondScore) -lt $FuzzyTieMargin) -and -not ($bestIsExact -and $exactCount -eq 1 -and $bestScore -gt $secondScore)
    return [pscustomobject]@{
        Best             = $best
        BestScore        = $bestScore
        SecondScore      = $secondScore
        IsConfidentMatch = ($null -ne $best) -and ($bestScore -ge $FuzzyAutoThreshold) -and -not $isTie
    }
}

# TeknoParrot's own game name (Metadata\<code>.json, a sibling of the GameProfiles folder) for each profile code that has one: code -> name.
# Read once per code and remembered for the run. A missing or unreadable file simply leaves the code out.
function Get-TpmTeknoParrotNamesForCodes {
    param([Parameter(Mandatory)][string]$GameProfilesDir, [string[]]$Codes = @())
    $names = @{}
    $tpRoot = Split-Path -Path $GameProfilesDir -Parent
    if ([string]::IsNullOrWhiteSpace($tpRoot)) { return $names }
    $cache = Get-Variable -Name TpmTeknoParrotNameCache -Scope Script -ValueOnly -ErrorAction SilentlyContinue
    if ($cache -isnot [hashtable]) { $cache = @{}; $script:TpmTeknoParrotNameCache = $cache }
    foreach ($code in $Codes) {
        $cacheKey = $tpRoot + '|' + $code
        if (-not $cache.ContainsKey($cacheKey)) { $cache[$cacheKey] = (Get-TpmTeknoParrotGameName -TpRoot $tpRoot -ProfileCode $code) }
        if (-not [string]::IsNullOrWhiteSpace([string]$cache[$cacheKey])) { $names[$code] = [string]$cache[$cacheKey] }
    }
    return $names
}

# Scans $folder recursively for files that TeknoParrot profiles use as their
# primary executable. This includes Windows EXE, Linux ELF, disc images (.iso,
# .gcm, .gcz), binary containers (.bin, .zip, .e4), Xbox binaries (.xbe for
# Sega Chihiro via cxbxr), Konami game DLLs (.dll), and extension-less Linux
# binaries (e.g. "game", "armyops-bin", "abc").
#
# Extension-less files are limited to 6 directory levels below $folder.
# Linux game executables are always at that depth or shallower; system files
# buried inside Lindbergh / Chihiro Linux filesystem images (e.g. X11 keyboard
# layout files like "tr") live 7-10 levels deep and are excluded by this limit.
# .dll files are included because some Konami arcade games (DDR, Steel Chronicle,
# Silent Scope, etc.) specify a game-specific DLL as their ExecutableName.
# .acgame files are the arcade games run by PCSX2x6: each of its profiles names one (for example NM00047.acgame), so without
# this extension those games were never found by name (issue #389).
# Silent Scope, etc.) specify a game-specific DLL as their ExecutableName.
function Get-GameFiles {
    param([string]$folder, [scriptblock]$ProgressScript = $null, [string[]]$ExtraExtensions = @())
    # The usual game file types, plus the file types the TeknoParrot profiles themselves name (Get-TpmProfileFileExtensions), so a game
    # whose file ends in something unusual (.exec, .chd) is still found without a change to this list.
    $exts       = @('.exe', '.elf', '.iso', '.gcm', '.gcz', '.bin', '.e4', '.zip', '.xbe', '.dll', '.acgame') + @($ExtraExtensions)
    $normalized = $folder -replace '/', '\'
    $baseDepth  = $normalized.TrimEnd('\').Split('\').Count
    $files = New-Object System.Collections.Generic.List[object]
    $progressState = $null
    if ($null -ne $ProgressScript) {
        $progressState = [pscustomobject]@{
            Seen = 0
            LastMilliseconds = -5000
            LastReportedCount = 0
            NextCount = 256
            Watch = [System.Diagnostics.Stopwatch]::StartNew()
        }
    }
    # Walk the folders ourselves: Get-ChildItem -Recurse follows junctions and links on Windows PowerShell 5.1,
    # which can leave the game folder or loop forever. Files of a folder come first, then its subfolders.
    $pendingFolders = New-Object System.Collections.Generic.Stack[string]
    $pendingFolders.Push($folder)
    while ($pendingFolders.Count -gt 0) {
      $currentFolder = $pendingFolders.Pop()
      $entries = @(Get-ChildItem -LiteralPath $currentFolder -ErrorAction SilentlyContinue)
      $subFolders = @($entries | Where-Object { $_.PSIsContainer -and -not ($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) })
      for ($subIndex = $subFolders.Count - 1; $subIndex -ge 0; $subIndex--) { $pendingFolders.Push([string]$subFolders[$subIndex].FullName) }
      foreach ($file in @($entries | Where-Object { -not $_.PSIsContainer })) {
        if ($null -ne $ProgressScript) {
            $progressState.Seen++
            $elapsedMilliseconds = $progressState.Watch.ElapsedMilliseconds
            if ($progressState.Seen -eq 1 -or $progressState.Seen -ge $progressState.NextCount -or
                (($elapsedMilliseconds - $progressState.LastMilliseconds) -ge 5000)) {
                $progressState.LastMilliseconds = $elapsedMilliseconds
                $progressState.NextCount = $progressState.Seen + 256
                $progressState.LastReportedCount = $progressState.Seen
                [void](& $ProgressScript $file $progressState.Seen)
            }
        }
        $ext = $file.Extension.ToLowerInvariant()
        $include = $exts -contains $ext
        if (-not $include -and $ext -eq '') {
            # Extension-less Linux binaries: allow up to 6 levels below the
            # games root. Some Lindbergh titles place executables 5-6 levels
            # deep inside their filesystem image. System files (X11 layouts,
            # shared libraries, etc.) live 7-10 levels deep and are excluded.
            $normFull = $file.FullName -replace '/', '\'
            $include = ($normFull.Split('\').Count - $baseDepth) -le 6
        }
        if ($include) { [void]$files.Add($file) }
      }
    }
    if ($null -ne $ProgressScript -and $progressState.Seen -gt $progressState.LastReportedCount) {
        # Null file denotes the final count-only notification after enumeration.
        [void](& $ProgressScript $null $progressState.Seen)
    }
    return $files.ToArray()
}
# Parses a number/range string (e.g. "1,3,5-7") into a sorted list of integers
# bounded to [1, $max]. Handles reversed ranges (e.g. "7-3" is treated as "3-7").
# Warns and returns empty if the string contains characters outside the valid set
# of digits, commas, hyphens, and whitespace -- this catches accidental letter
# commands (e.g. typing "N" where a number was expected).
function Expand-NumberList {
    param([string]$str, [int]$max)   # $str avoids shadowing the $input automatic variable
    $out = [System.Collections.Generic.List[int]]::new()

    # Short-circuit on empty or whitespace-only input -- nothing to parse.
    if ([string]::IsNullOrWhiteSpace($str)) { return ,@($out) }

    # Validate: anything other than digits, commas, hyphens, and whitespace is
    # not a valid number/range expression and almost certainly a typo.
    if ($str -match '[^0-9,\s\-]') {
        Write-Host ("  NOTE: '{0}' is not a valid selection -- use digits, commas, and hyphens only (e.g. 1,3,5-7)." -f $str) -ForegroundColor Yellow
        return ,@($out)
    }

    foreach ($part in ($str -split ',')) {
        $part = $part.Trim()
        if ($part -match '^(\d+)-(\d+)$') {
            # Guard against overflow: int32 max is 2,147,483,647 (10 digits).
            if ($Matches[1].Length -gt 9 -or $Matches[2].Length -gt 9) { continue }
            $from = [int]$Matches[1]; $to = [int]$Matches[2]
            if ($from -gt $to) { $tmp = $from; $from = $to; $to = $tmp }   # handle "7-3"
            $to = [Math]::Min($to, $max)   # clamp upper bound before looping
            for ($n = $from; $n -le $to; $n++) { if ($n -ge 1) { [void]$out.Add($n) } }
        } elseif ($part -match '^\d+$') {
            if ($part.Length -gt 9) { continue }   # overflow guard
            $n = [int]$part
            if ($n -ge 1 -and $n -le $max) { [void]$out.Add($n) }
        }
    }
    return ,@($out)
}

# Interactive game picker. Shows a menu with four modes:
#   A (All)    -- extract everything, no filter
#   L (Browse) -- paginated A-Z list, N/P to page, pick by number
#   S (Search) -- keyword filter, pick by number from results
#   D (Done)   -- finish and proceed with the current queue
# Browse and Search both feed into the same queue. Returns:
#   $null   -- D pressed with no games selected (skip extraction)
#   @()     -- A pressed; no filter (extract all)
#   @(...)  -- explicit whitelist of ZIP BaseName strings
function Get-TpmImmediateZipSubdirectorySummary {
    param([Parameter(Mandatory)][string]$ZipSource)
    $directoryCandidates = New-Object System.Collections.Generic.List[object]
    $directoryDiscoveryStarted = Get-Date
    $directoryDiscoveryCurrent = 0
    Write-TpmCompactExtractionProgress -Phase Scanning -Label 'ZIP source subfolder discovery' -Current $directoryDiscoveryCurrent -Total 0 -StartedAt $directoryDiscoveryStarted
    $directoryDiscoveryCurrentCompleted = $false
    try {
        Get-ChildItem -LiteralPath $ZipSource -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            [void]$directoryCandidates.Add($_)
            $directoryDiscoveryCurrent++
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'ZIP source subfolder discovery' -Current $directoryDiscoveryCurrent -Total 0 -StartedAt $directoryDiscoveryStarted
        }
        $directoryDiscoveryCurrentCompleted = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'ZIP source subfolder discovery' -Current $directoryDiscoveryCurrent -Total 0 -StartedAt $directoryDiscoveryStarted -Complete -Outcome $(if ($directoryDiscoveryCurrentCompleted) { 'Final' } else { 'Error' })
    }
    $directories = $directoryCandidates
    $started = Get-Date
    $current = 0
    $hits = New-Object System.Collections.Generic.List[object]
    $currentDone = $false
    try {
        foreach ($directory in $directories) {
            $current++
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'ZIP source subfolder scan' -Current $current -Total $directories.Count -StartedAt $started
            $count = 0
            $zipDiscoveryStarted = Get-Date
            $zipDiscoveryCurrent = 0
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'ZIP source subfolder ZIP discovery' -Current $zipDiscoveryCurrent -Total 0 -StartedAt $zipDiscoveryStarted
            $zipDiscoveryCurrentCompleted = $false
            try {
                Get-ChildItem -LiteralPath $directory.FullName -Filter '*.zip' -ErrorAction SilentlyContinue | ForEach-Object {
                    $count++
                    $zipDiscoveryCurrent++
                    Write-TpmCompactExtractionProgress -Phase Scanning -Label 'ZIP source subfolder ZIP discovery' -Current $zipDiscoveryCurrent -Total 0 -StartedAt $zipDiscoveryStarted
                }
                $zipDiscoveryCurrentCompleted = $true
            } finally {
                Write-TpmCompactExtractionProgress -Phase Scanning -Label 'ZIP source subfolder ZIP discovery' -Current $zipDiscoveryCurrent -Total 0 -StartedAt $zipDiscoveryStarted -Complete -Outcome $(if ($zipDiscoveryCurrentCompleted) { 'Final' } else { 'Error' })
            }
            if ($count -gt 0) { [void]$hits.Add([pscustomobject]@{ Path=$directory.FullName; Count=$count }) }
        }
        $currentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'ZIP source subfolder scan' -Current $(if ($currentDone) { $current } else { $current - 1 }) -Total $directories.Count -StartedAt $started -Complete -Outcome $(if ($currentDone) { 'Final' } else { 'Error' })
    }
    return $hits.ToArray()
}

function Get-TpmTopLevelZipSourceFiles {
    param(
        [Parameter(Mandatory)][string]$ZipSource,
        [Parameter(Mandatory)][string]$ProgressLabel,
        [switch]$ExcludeCollectionArchives,
        [switch]$SortByBaseName
    )
    $fileCandidates = New-Object System.Collections.Generic.List[object]
    $started = Get-Date
    $current = 0
    Write-TpmCompactExtractionProgress -Phase Scanning -Label $ProgressLabel -Current $current -Total 0 -StartedAt $started
    $currentCompleted = $false
    try {
        Get-ChildItem -LiteralPath $ZipSource -Filter *.zip -ErrorAction SilentlyContinue | ForEach-Object {
            $current++
            if (-not $ExcludeCollectionArchives -or $_.BaseName -notlike '!TeknoParrot Collection*') {
                [void]$fileCandidates.Add($_)
            }
            Write-TpmCompactExtractionProgress -Phase Scanning -Label $ProgressLabel -Current $current -Total 0 -StartedAt $started
        }
        $currentCompleted = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label $ProgressLabel -Current $current -Total 0 -StartedAt $started -Complete -Outcome $(if ($currentCompleted) { 'Final' } else { 'Error' })
    }
    $files = $fileCandidates.ToArray()
    if ($SortByBaseName) { $files = @($files | Sort-Object BaseName) }
    return $files
}

function Select-GamesInteractive {
    param([string]$zipSource, [string]$installFolder, [hashtable]$datIndex = $null, [string]$userProfilesDir = '', [switch]$SelectAll)

    if ([string]::IsNullOrWhiteSpace($zipSource) -or [string]::IsNullOrWhiteSpace($installFolder)) {
        Write-Log "Select-GamesInteractive: called with empty path -- skipping"
        return $null
    }
    $all = @(Get-TpmTopLevelZipSourceFiles -ZipSource $zipSource -ProgressLabel 'AutoSync picker source ZIP discovery' -ExcludeCollectionArchives -SortByBaseName)

    if ($all.Count -eq 0) {
        Write-Host "  No game ZIPs found directly in this ZIP folder." -ForegroundColor Yellow
        $subdirHits = @(Get-TpmImmediateZipSubdirectorySummary -ZipSource $zipSource)
        if ($subdirHits.Count -gt 0) {
            Write-Host "  Tip: these folders inside it contain ZIPs -- choose one of them as your game ZIP folder:" -ForegroundColor Cyan
            foreach ($sd in $subdirHits) {
                Write-Host "    $($sd.Path)  ($($sd.Count) ZIPs)" -ForegroundColor DarkCyan
            }
        }
        return ,@()   # comma forces real array semantics -- a bare "return @()" is
                      # unwrapped to $null by the pipeline, which the caller cannot
                      # then distinguish from its own "user skipped" $null case
    }

    # Build a folder map of what is already extracted in the destination,
    # using the same resolver as AutoSync.
    $normalizedFolderMap = Get-StagingFolderMap $installFolder

    # Split the ZIP list into already-extracted (non-empty folder exists) and
    # not-yet-extracted. The picker only shows the not-yet-extracted ones.
    $alreadyExtracted = @()
    $toExtract        = @()
    $classificationStarted = Get-Date
    $classificationCurrent = 0
    $classificationCurrentDone = $false
    try {
        foreach ($zip in $all) {
            $classificationCurrent++
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'AutoSync ZIP classification' -Current $classificationCurrent -Total $all.Count -StartedAt $classificationStarted
            $existingPath = Resolve-ExtractedGameFolder -RawZipName $zip.BaseName -InstallFolder $installFolder -FolderMap $normalizedFolderMap -DatIndex $datIndex -UserProfilesDir $userProfilesDir
            if ($existingPath) { $alreadyExtracted += $zip } else { $toExtract += $zip }
        }
        $classificationCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'source ZIPs' -Current $(if ($classificationCurrentDone) { $classificationCurrent } else { $classificationCurrent - 1 }) -Total $all.Count -StartedAt $classificationStarted -Complete -Outcome $(if ($classificationCurrentDone) { 'Final' } else { 'Error' })
    }

    Write-Host ""
    if ($alreadyExtracted.Count -gt 0) {
        Write-Host ("  {0} game(s) already extracted -- not shown." -f $alreadyExtracted.Count) -ForegroundColor DarkGray
    }
    if ($toExtract.Count -eq 0) {
        Write-Host "  All games in this ZIP folder are already extracted. Nothing left to extract." -ForegroundColor Green
        Write-Host "  To register games that are already extracted, choose Register only from the main menu." -ForegroundColor DarkCyan
        return $null   # nothing left: the caller processes no ZIP (an empty array would mean "extract everything")
    }
    Write-Host ("  {0} game(s) available to extract." -f $toExtract.Count) -ForegroundColor Cyan
    if ($SelectAll) { return ,@($toExtract | ForEach-Object { $_.BaseName }) }

    $all      = $toExtract   # picker operates only on unextracted games from here on
    $queue    = @()
    $pageSize = 20
    $done     = $false
    $cancelled = $false

    while (-not $done) {
        Write-Host ""
        Write-Host "  ============================================" -ForegroundColor Cyan
        $qLabel = if ($queue.Count -gt 0) { "  Queue: $($queue.Count) game(s) selected" } else { "  Queue: empty" }
        Write-Host $qLabel -ForegroundColor Cyan
        Write-Host "  ============================================" -ForegroundColor Cyan
        Write-Host "    A) All unextracted games ($($all.Count))"
        Write-Host "    L) Browse and select from list ($($all.Count) games, A-Z)"
        Write-Host "    S) Search by keyword"
        Write-Host "    D) Done -- continue with selected queue"
        Write-Host "    B) Back / cancel AutoSync selection"
        Write-Host ""
        $choice = (Read-HostSafe "  Enter A, L, S, D, or B").Trim().ToUpperInvariant()

        # -- ALL GAMES -------------------------------------------------------
        if ($choice -eq 'A') {
            Write-Host ""
            Write-Host "  All $($all.Count) unextracted affected game(s) will be extracted." -ForegroundColor Green
            return ,@($all | ForEach-Object { $_.BaseName })   # only the unextracted games listed above, never an empty "extract everything" array
        }

        # -- BROWSE ----------------------------------------------------------
        elseif ($choice -eq 'L') {
            $page       = 0
            $totalPages = [Math]::Ceiling($all.Count / $pageSize)
            $browsing   = $true

            while ($browsing) {
                $start     = $page * $pageSize
                $end       = [Math]::Min($start + $pageSize - 1, $all.Count - 1)
                $pageItems = if ($start -gt $end) { @() } else { @($all[$start..$end]) }

                Write-Host ""
                Write-Host ("  Page {0} of {1}  ({2} games total)" -f ($page+1), $totalPages, $all.Count) -ForegroundColor Cyan
                Write-Host "  (* = already in queue)" -ForegroundColor DarkCyan
                Write-Host ""
                for ($i = 0; $i -lt $pageItems.Count; $i++) {
                    $marker = if ($queue -contains $pageItems[$i].BaseName) { "*" } else { " " }
                    $num    = ($i + 1).ToString().PadLeft(3)
                    Write-Host "  [$marker$num] $($pageItems[$i].BaseName)"
                }
                Write-Host ""
                Write-Host "  Numbers (e.g. 1,3,5-7)  |  N = next  |  P = prev  |  B = back to menu  |  D = done" -ForegroundColor DarkCyan
                Write-Host ""
                $cmd = (Read-HostSafe "  >").ToUpperInvariant()

                if ($cmd -eq 'B') {
                    $browsing = $false
                } elseif ($cmd -eq 'D') {
                    $browsing = $false
                    $done     = $true
                } elseif ($cmd -eq 'N') {
                    $page = if ($page -lt ($totalPages - 1)) { $page + 1 } else { 0 }
                } elseif ($cmd -eq 'P') {
                    $page = if ($page -gt 0) { $page - 1 } else { $totalPages - 1 }
                } elseif ($cmd -ne '') {
                    $nums  = Expand-NumberList -str $cmd -max $pageItems.Count
                    $added = 0
                    foreach ($n in $nums) {
                        $name = $pageItems[$n - 1].BaseName
                        if ($queue -notcontains $name) { $queue += $name; $added++ }
                    }
                    if ($nums.Count -gt 0) {
                        Write-Host ("  Added {0} game(s). Queue: {1} total." -f $added, $queue.Count) -ForegroundColor Cyan
                    }
                }
            }
        }

        # -- SEARCH ----------------------------------------------------------
        elseif ($choice -eq 'S') {
            $searching = $true
            while ($searching) {
                Write-Host ""
                $term = (Read-HostSafe "  Search keyword (or 'back' / 'done')")
                if ($term -ieq 'back') { $searching = $false; continue }
                if ($term -ieq 'done') { $searching = $false; $done = $true; continue }
                if (-not $term) { continue }

                $results = @($all | Where-Object { $_.BaseName.IndexOf($term, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 })
                if ($results.Count -eq 0) {
                    Write-Host "  No matches for '$term'." -ForegroundColor Yellow
                    continue
                }

                $maxShow = 40
                $shown   = [Math]::Min($results.Count, $maxShow)
                Write-Host ""
                Write-Host ("  {0} match(es) for '{1}'{2}:" -f $results.Count, $term,
                    $(if ($results.Count -gt $maxShow) { " (showing first $maxShow)" } else { "" })) -ForegroundColor Cyan
                Write-Host "  (* = already in queue)" -ForegroundColor DarkCyan
                Write-Host ""
                for ($i = 0; $i -lt $shown; $i++) {
                    $marker = if ($queue -contains $results[$i].BaseName) { "*" } else { " " }
                    $num    = ($i + 1).ToString().PadLeft(3)
                    Write-Host "  [$marker$num] $($results[$i].BaseName)"
                }
                if ($results.Count -gt $maxShow) {
                    Write-Host "  ... narrow your search to see more." -ForegroundColor DarkCyan
                }
                Write-Host ""
                $pick = (Read-HostSafe "  Numbers to select (or Enter to search again)")
                if (-not $pick) { continue }

                $nums  = Expand-NumberList -str $pick -max $shown
                $added = 0
                foreach ($n in $nums) {
                    $name = $results[$n - 1].BaseName
                    if ($queue -notcontains $name) { $queue += $name; $added++ }
                }
                if ($nums.Count -gt 0) {
                    Write-Host ("  Added {0} game(s). Queue: {1} total." -f $added, $queue.Count) -ForegroundColor Cyan
                }
            }
        }

        elseif ($choice -eq 'D') {
            if ($queue.Count -eq 0) {
                Write-Host "  No games are queued. Choose A, L, S, or B." -ForegroundColor Yellow
                continue
            }
            $done = $true
        } elseif ($choice -eq 'B') {
            $cancelled = $true
            $done = $true
        } elseif ($choice -ne '') {
            Write-Host ("  I did not understand '{0}'. Choose A, L, S, D, or B." -f $choice) -ForegroundColor Yellow
        }
    }
    if ($cancelled) {
        Write-Host "  AutoSync selection canceled. Nothing was changed." -ForegroundColor DarkGray
        return $null
    }
    if ($queue.Count -gt 0) {
        Write-Host ""
        Write-Host "  Final queue ($($queue.Count) game(s)):" -ForegroundColor Green
        foreach ($g in $queue) { Write-Host "    + $g" -ForegroundColor Green }
        return ,$queue
    }
    Write-Host "  No games selected." -ForegroundColor Yellow
    return $null
}

# Combined game picker for AutoSync when both main and supplementary sources are configured.
# Scans both ZIP sources, merges the unextracted lists into one sorted display, and lets the
# user select from either library in a single A/L/S/D session. Supplementary entries are
# marked [+] so the user can tell the two libraries apart at a glance.
# Returns a PSCustomObject { Main; Supp }. Each property is:
#   $null   -- skip that source (nothing left to extract, or D pressed with nothing selected for it)
#   @(...)  -- explicit whitelist of ZIP BaseName strings to extract (A pressed: every unextracted game of that source)
function Select-GamesInteractiveCombined {
    param([string]$zipSourceMain, [string]$zipSourceSupp, [string]$installFolder, [hashtable]$datIndex = $null, [string]$userProfilesDir = '', [switch]$SelectAll)

    if ([string]::IsNullOrWhiteSpace($zipSourceMain) -or [string]::IsNullOrWhiteSpace($zipSourceSupp) -or [string]::IsNullOrWhiteSpace($installFolder)) {
        Write-Log "Select-GamesInteractiveCombined: called with empty path -- skipping"
        return [PSCustomObject]@{ Main = $null; Supp = $null }
    }
    $allMain = @(Get-TpmTopLevelZipSourceFiles -ZipSource $zipSourceMain -ProgressLabel 'AutoSync combined main ZIP discovery' -ExcludeCollectionArchives -SortByBaseName)
    $allSupp = @(Get-TpmTopLevelZipSourceFiles -ZipSource $zipSourceSupp -ProgressLabel 'AutoSync combined supplementary ZIP discovery' -ExcludeCollectionArchives -SortByBaseName)

    $normalizedFolderMap = Get-StagingFolderMap $installFolder

    # Split each source into already-extracted and available. Track which source owns each entry.
    $sourceMap   = @{}
    $alreadyMain = 0; $alreadySupp = 0
    $toExtractMain = @(); $toExtractSupp = @()
    $classificationTotal = $allMain.Count + $allSupp.Count
    $classificationCurrent = 0
    $classificationStarted = Get-Date
    $classificationCurrentDone = $false
    try {
        foreach ($zip in $allMain) {
            $classificationCurrent++
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'AutoSync main ZIP classification' -Current $classificationCurrent -Total $classificationTotal -StartedAt $classificationStarted
            $existing = Resolve-ExtractedGameFolder -RawZipName $zip.BaseName -InstallFolder $installFolder -FolderMap $normalizedFolderMap -DatIndex $datIndex -UserProfilesDir $userProfilesDir
            if ($existing) { $alreadyMain++ } else { $toExtractMain += $zip; $sourceMap[$zip.BaseName] = 'Main' }
        }
        # Supp iterates after Main -- if the same BaseName appears in both sources,
        # 'Supp' overwrites 'Main' in $sourceMap (supplementary takes precedence).
        foreach ($zip in $allSupp) {
            $classificationCurrent++
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'AutoSync supplementary ZIP classification' -Current $classificationCurrent -Total $classificationTotal -StartedAt $classificationStarted
            $existing = Resolve-ExtractedGameFolder -RawZipName $zip.BaseName -InstallFolder $installFolder -FolderMap $normalizedFolderMap -DatIndex $datIndex -UserProfilesDir $userProfilesDir
            if ($existing) { $alreadySupp++ } else { $toExtractSupp += $zip; $sourceMap[$zip.BaseName] = 'Supp' }
        }
        $classificationCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'source ZIPs' -Current $(if ($classificationCurrentDone) { $classificationCurrent } else { $classificationCurrent - 1 }) -Total $classificationTotal -StartedAt $classificationStarted -Complete -Outcome $(if ($classificationCurrentDone) { 'Final' } else { 'Error' })
    }
    # A game found in both sources is queued once, from the source $sourceMap chose; otherwise A and unattended runs extract it twice.
    $toExtractMain = @($toExtractMain | Where-Object { $sourceMap[$_.BaseName] -ne 'Supp' })

    $all = @($toExtractMain + $toExtractSupp | Sort-Object BaseName -Unique)
    $shownSupp = @($all | Where-Object { $sourceMap[$_.BaseName] -eq 'Supp' }).Count

    Write-Host ""
    if (($alreadyMain + $alreadySupp) -gt 0) {
        Write-Host ("  {0} game(s) already extracted -- not shown." -f ($alreadyMain + $alreadySupp)) -ForegroundColor DarkGray
    }
    if ($all.Count -eq 0) {
        Write-Host "  All games in these ZIP folders are already extracted. Nothing left to extract." -ForegroundColor Green
        Write-Host "  To register games that are already extracted, choose Register only from the main menu." -ForegroundColor DarkCyan
        return [PSCustomObject]@{ Main = $null; Supp = $null }   # nothing left: no ZIP is processed (an empty array would mean "extract everything")
    }
    Write-Host ("  {0} game(s) available to extract ({1} collection, {2} supplementary [+])." -f $all.Count, ($all.Count - $shownSupp), $shownSupp) -ForegroundColor Cyan
    # A (and unattended runs): every unextracted game of each source. An empty source is $null (skip), never an empty array.
    $allSelection = [PSCustomObject]@{
        Main = if ($toExtractMain.Count -gt 0) { ,@($toExtractMain | ForEach-Object { $_.BaseName }) } else { $null }
        Supp = if ($toExtractSupp.Count -gt 0) { ,@($toExtractSupp | ForEach-Object { $_.BaseName }) } else { $null }
    }
    if ($SelectAll) { return $allSelection }

    $queue    = @()
    $pageSize = 20
    $done     = $false
    $cancelled = $false

    while (-not $done) {
        Write-Host ""
        Write-Host "  ============================================" -ForegroundColor Cyan
        Write-Host $(if ($queue.Count -gt 0) { "  Queue: $($queue.Count) game(s) selected" } else { "  Queue: empty" }) -ForegroundColor Cyan
        Write-Host "  ============================================" -ForegroundColor Cyan
        Write-Host "    A) All unextracted games ($($all.Count))"
        Write-Host "    L) Browse and select from list ($($all.Count) games, A-Z)"
        Write-Host "    S) Search by keyword"
        Write-Host "    D) Done -- continue with selected queue"
        Write-Host "    B) Back / cancel AutoSync selection"
        Write-Host ""
        $choice = (Read-HostSafe "  Enter A, L, S, D, or B").Trim().ToUpperInvariant()

        if ($choice -eq 'A') {
            Write-Host ""
            Write-Host "  All $($all.Count) unextracted affected game(s) will be extracted." -ForegroundColor Green
            return $allSelection
        }
        elseif ($choice -eq 'L') {
            $page       = 0
            $totalPages = [Math]::Ceiling($all.Count / $pageSize)
            $browsing   = $true
            while ($browsing) {
                $start     = $page * $pageSize
                $end       = [Math]::Min($start + $pageSize - 1, $all.Count - 1)
                $pageItems = if ($start -gt $end) { @() } else { @($all[$start..$end]) }
                Write-Host ""
                Write-Host ("  Page {0} of {1}  ({2} games total)" -f ($page+1), $totalPages, $all.Count) -ForegroundColor Cyan
                Write-Host "  (* = in queue | [+] = supplementary)" -ForegroundColor DarkCyan
                Write-Host ""
                for ($i = 0; $i -lt $pageItems.Count; $i++) {
                    $inQ = if ($queue -contains $pageItems[$i].BaseName) { "*" } else { " " }
                    $src = if ($sourceMap[$pageItems[$i].BaseName] -eq 'Supp') { "[+]" } else { "   " }
                    Write-Host ("  [{0}{1}] {2} {3}" -f $inQ, ($i+1).ToString().PadLeft(3), $src, $pageItems[$i].BaseName)
                }
                Write-Host ""
                Write-Host "  Numbers (e.g. 1,3,5-7)  |  N=next  P=prev  B=back  D=done" -ForegroundColor DarkCyan
                Write-Host ""
                $cmd = (Read-HostSafe "  >").ToUpperInvariant()
                if     ($cmd -eq 'B') { $browsing = $false }
                elseif ($cmd -eq 'D') { $browsing = $false; $done = $true }
                elseif ($cmd -eq 'N') { $page = if ($page -lt ($totalPages - 1)) { $page + 1 } else { 0 } }
                elseif ($cmd -eq 'P') { $page = if ($page -gt 0) { $page - 1 } else { $totalPages - 1 } }
                elseif ($cmd -ne '') {
                    $nums = Expand-NumberList -str $cmd -max $pageItems.Count
                    $added = 0
                    foreach ($n in $nums) {
                        $name = $pageItems[$n-1].BaseName
                        if ($queue -notcontains $name) { $queue += $name; $added++ }
                    }
                    if ($nums.Count -gt 0) { Write-Host ("  Added {0} game(s). Queue: {1} total." -f $added, $queue.Count) -ForegroundColor Cyan }
                }
            }
        }
        elseif ($choice -eq 'S') {
            $searching = $true
            while ($searching) {
                Write-Host ""
                $term = (Read-HostSafe "  Search keyword (or 'back' / 'done')")
                if ($term -ieq 'back') { $searching = $false; continue }
                if ($term -ieq 'done') { $searching = $false; $done = $true; continue }
                if (-not $term) { continue }
                $results = @($all | Where-Object { $_.BaseName.IndexOf($term, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 })
                if ($results.Count -eq 0) { Write-Host "  No matches for '$term'." -ForegroundColor Yellow; continue }
                $maxShow = 40
                $shown   = [Math]::Min($results.Count, $maxShow)
                Write-Host ""
                Write-Host ("  {0} match(es) for '{1}'{2}:" -f $results.Count, $term,
                    $(if ($results.Count -gt $maxShow) { " (showing first $maxShow)" } else { "" })) -ForegroundColor Cyan
                Write-Host "  (* = in queue | [+] = supplementary)" -ForegroundColor DarkCyan
                Write-Host ""
                for ($i = 0; $i -lt $shown; $i++) {
                    $inQ = if ($queue -contains $results[$i].BaseName) { "*" } else { " " }
                    $src = if ($sourceMap[$results[$i].BaseName] -eq 'Supp') { "[+]" } else { "   " }
                    Write-Host ("  [{0}{1}] {2} {3}" -f $inQ, ($i+1).ToString().PadLeft(3), $src, $results[$i].BaseName)
                }
                if ($results.Count -gt $maxShow) { Write-Host "  ... narrow your search to see more." -ForegroundColor DarkCyan }
                Write-Host ""
                $pick = (Read-HostSafe "  Numbers to select (or Enter to search again)")
                if (-not $pick) { continue }
                $nums  = Expand-NumberList -str $pick -max $shown
                $added = 0
                foreach ($n in $nums) {
                    $name = $results[$n-1].BaseName
                    if ($queue -notcontains $name) { $queue += $name; $added++ }
                }
                if ($nums.Count -gt 0) { Write-Host ("  Added {0} game(s). Queue: {1} total." -f $added, $queue.Count) -ForegroundColor Cyan }
            }
        }
        elseif ($choice -eq 'D') {
            if ($queue.Count -eq 0) {
                Write-Host "  No games are queued. Choose A, L, S, or B." -ForegroundColor Yellow
                continue
            }
            $done = $true
        } elseif ($choice -eq 'B') {
            $cancelled = $true
            $done = $true
        } elseif ($choice -ne '') {
            Write-Host ("  I did not understand '{0}'. Choose A, L, S, D, or B." -f $choice) -ForegroundColor Yellow
        }
    }

    if ($cancelled) {
        Write-Host "  AutoSync selection canceled. Nothing was changed." -ForegroundColor DarkGray
        return [PSCustomObject]@{ Main = $null; Supp = $null }
    }
    if ($queue.Count -gt 0) {
        Write-Host ""
        Write-Host "  Final queue ($($queue.Count) game(s)):" -ForegroundColor Green
        foreach ($g in $queue) {
            $tag = if ($sourceMap[$g] -eq 'Supp') { "[+] " } else { "" }
            Write-Host "    + $tag$g" -ForegroundColor Green
        }
    } else {
        Write-Host "  No games selected." -ForegroundColor Yellow
    }

    $qMain = @($queue | Where-Object { $sourceMap[$_] -ne 'Supp' })
    $qSupp = @($queue | Where-Object { $sourceMap[$_] -eq  'Supp' })
    # $null = skip that source (D with no selection); @() = no filter = all (from A only).
    return [PSCustomObject]@{
        Main = if ($qMain.Count -gt 0) { $qMain } else { $null }
        Supp = if ($qSupp.Count -gt 0) { $qSupp } else { $null }
    }
}

# =============================================================================
# CROSSHAIR MANAGEMENT
# =============================================================================
# Scans the Crosshairs subfolder (next to the script) for valid PNG files,
# generates an HTML preview the user can browse in a browser, then lets them
# pick P1 and P2 by index number before deploying to every registered lightgun
# game. Lightgun games are identified by <GunGame>true</GunGame> in their
# UserProfile XML. ElfLdr2 games share a single folder in the TeknoParrot root;
# all others receive P1.png / P2.png in the individual game exe directory.

# Returns true if $Path begins with the PNG magic bytes (89 50 4E 47 0D 0A 1A 0A).
function Test-PngFile {
    param([string]$Path)
    try {
        $bytes = New-Object byte[] 8
        $fs    = [System.IO.File]::OpenRead($Path)
        try {
            $pos = 0
            while ($pos -lt 8) {
                $n = $fs.Read($bytes, $pos, 8 - $pos)
                if ($n -eq 0) { break }
                $pos += $n
            }
        } finally { $fs.Dispose() }
        return ($bytes[0] -eq 0x89 -and $bytes[1] -eq 0x50 -and
                $bytes[2] -eq 0x4E -and $bytes[3] -eq 0x47 -and
                $bytes[4] -eq 0x0D -and $bytes[5] -eq 0x0A -and
                $bytes[6] -eq 0x1A -and $bytes[7] -eq 0x0A)
    } catch { return $false }
}

function New-TpmCrosshairPreviewThumbnail {
    param([Parameter(Mandatory)][string]$Path)
    $source = $null
    $thumbnail = $null
    $graphics = $null
    try {
        $source = [System.Drawing.Image]::FromFile($Path)
        $thumbnail = [System.Drawing.Bitmap]::new(64, 64, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
        $graphics = [System.Drawing.Graphics]::FromImage($thumbnail)
        $graphics.Clear([System.Drawing.Color]::Transparent)
        $graphics.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::NearestNeighbor
        $graphics.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::Half
        $graphics.DrawImage($source, 0, 0, 64, 64)
        $result = $thumbnail
        $thumbnail = $null
        return $result
    } catch {
        try { Write-Log ("Crosshairs: preview thumbnail unavailable for '{0}' -- {1}" -f [System.IO.Path]::GetFileName($Path), $_.Exception.Message) } catch {}
        return $null
    } finally {
        if ($graphics) { try { $graphics.Dispose() } catch {} }
        if ($thumbnail) { try { $thumbnail.Dispose() } catch {} }
        if ($source) { try { $source.Dispose() } catch {} }
    }
}

function Set-TpmCrosshairPreviewSelection {
    param([Parameter(Mandatory)][object]$Session, [int]$Index)
    $paths = @($Session['Paths'])
    if ([bool]$Session['Closed'] -or $Index -lt 0 -or $Index -ge $paths.Count) {
        return [pscustomobject]@{ Accepted = $false; Player = ''; Index = $Index; Complete = $false }
    }
    if ($null -eq $Session['P1Index']) {
        $Session['P1Index'] = $Index
        return [pscustomobject]@{ Accepted = $true; Player = 'P1'; Index = $Index; Complete = $false }
    }
    if ($null -eq $Session['P2Index']) {
        $Session['P2Index'] = $Index
        return [pscustomobject]@{ Accepted = $true; Player = 'P2'; Index = $Index; Complete = $true }
    }
    return [pscustomobject]@{ Accepted = $false; Player = ''; Index = $Index; Complete = $true }
}

function Close-TpmCrosshairPreviewSession {
    param([object]$Session)
    if (-not $Session) { return [pscustomobject]@{ Closed = $true; AlreadyClosed = $true } }
    if ([bool]$Session['CleanupCompleted']) { return [pscustomobject]@{ Closed = $true; AlreadyClosed = $true } }
    $Session['CleanupCompleted'] = $true
    $Session['Closed'] = $true
    if ($Session['Timer']) {
        try { if ($Session['TimerHandler']) { $Session['Timer'].Remove_Tick($Session['TimerHandler']) } } catch {}
        try { $Session['Timer'].Stop() } catch {}
        try { $Session['Timer'].Dispose() } catch {}
        $Session['Timer'] = $null
        $Session['TimerHandler'] = $null
    }
    foreach ($entry in @($Session['ButtonHandlers'])) {
        try { if ($entry.Button -and $entry.Handler) { $entry.Button.Remove_Click($entry.Handler) } } catch {}
    }
    $form = $Session['Form']
    if ($form) {
        try { if (-not $form.IsDisposed) { $form.Close() } } catch {}
        try { $form.Dispose() } catch {}
        $Session['Form'] = $null
    }
    foreach ($image in @($Session['Images'])) { try { if ($image) { $image.Dispose() } } catch {} }
    try { if ($Session['Images']) { $Session['Images'].Clear() } } catch {}
    try { if ($Session['ButtonHandlers']) { $Session['ButtonHandlers'].Clear() } } catch {}
    return [pscustomobject]@{ Closed = $true; AlreadyClosed = $false }
}

function Invoke-TpmCrosshairPreviewWithCleanup {
    param([Parameter(Mandatory)][object]$Session, [Parameter(Mandatory)][scriptblock]$Action)
    try { return (& $Action $Session) }
    finally { [void](Close-TpmCrosshairPreviewSession -Session $Session) }
}

# Shows an owned, keyboard-accessible preview form. The returned session owns
# exactly this Form, its timer, click handlers, and image thumbnails.
function Show-TpmCrosshairPreviewWindow {
    param([Parameter(Mandatory)][string[]]$CrosshairPaths, [int]$TimeoutSeconds = 45)
    $session = [hashtable]::Synchronized(@{
        Form = $null
        Timer = $null
        TimerHandler = $null
        ButtonHandlers = [System.Collections.Generic.List[object]]::new()
        Images = [System.Collections.Generic.List[object]]::new()
        Paths = @($CrosshairPaths)
        P1Index = $null
        P2Index = $null
        Closed = $false
        TimedOut = $false
        CleanupCompleted = $false
    })
    $state = $session
    if ($CrosshairPaths.Count -eq 0) {
        return [pscustomobject]@{ Available = $false; Cancelled = $true; P1Index = $null; P2Index = $null; Reason = 'NO_CROSSHAIRS' }
    }
    try {
        if ([Threading.Thread]::CurrentThread.GetApartmentState() -ne [Threading.ApartmentState]::STA) { throw 'The owned crosshair preview requires a single-threaded PowerShell UI thread.' }
        Add-Type -AssemblyName System.Windows.Forms -ErrorAction Stop
        Add-Type -AssemblyName System.Drawing -ErrorAction Stop
        $form = New-Object Windows.Forms.Form
        $session['Form'] = $form
        $form.Text = 'TeknoParrot Crosshair Preview'
        $form.AutoScaleMode = [Windows.Forms.AutoScaleMode]::Dpi
        $form.StartPosition = 'CenterScreen'
        $form.ClientSize = [System.Drawing.Size]::new(960, 720)
        $form.MinimumSize = [System.Drawing.Size]::new(700, 520)
        $form.MaximizeBox = $true
        $form.MinimizeBox = $false
        $form.ShowInTaskbar = $true

        $instructions = New-Object Windows.Forms.Label
        $instructions.Location = [System.Drawing.Point]::new(12, 10)
        $instructions.Size = [System.Drawing.Size]::new(920, 46)
        $instructions.Anchor = [Windows.Forms.AnchorStyles]::Top -bor [Windows.Forms.AnchorStyles]::Left -bor [Windows.Forms.AnchorStyles]::Right
        $instructions.Text = 'Choose a design for P1, then choose a design for P2. Click a design or focus it and press Enter or Space. You may use the same design twice. Press Esc or close this window to type any missing numbers in TeknoParrot Manager.'
        $instructions.AccessibleName = 'Crosshair selection instructions'
        $instructions.AccessibleRole = [Windows.Forms.AccessibleRole]::StaticText

        $status = New-Object Windows.Forms.Label
        $status.Location = [System.Drawing.Point]::new(12, 60)
        $status.Size = [System.Drawing.Size]::new(920, 36)
        $status.Anchor = [Windows.Forms.AnchorStyles]::Top -bor [Windows.Forms.AnchorStyles]::Left -bor [Windows.Forms.AnchorStyles]::Right
        $status.Text = 'Ready. Choose a crosshair for P1.'
        $status.AccessibleName = 'Crosshair selection status'
        $status.AccessibleRole = [Windows.Forms.AccessibleRole]::StaticText

        $grid = New-Object Windows.Forms.FlowLayoutPanel
        $grid.Location = [System.Drawing.Point]::new(12, 102)
        $grid.Size = [System.Drawing.Size]::new(920, 550)
        $grid.Anchor = [Windows.Forms.AnchorStyles]::Top -bor [Windows.Forms.AnchorStyles]::Bottom -bor [Windows.Forms.AnchorStyles]::Left -bor [Windows.Forms.AnchorStyles]::Right
        $grid.AutoScroll = $true
        $grid.WrapContents = $true
        $grid.FlowDirection = [Windows.Forms.FlowDirection]::LeftToRight
        $grid.Padding = New-Object Windows.Forms.Padding(6)
        $grid.AccessibleName = 'Crosshair designs'
        $grid.AccessibleDescription = 'Use Tab and Shift+Tab to move through the crosshair buttons.'

        $cancelButton = New-Object Windows.Forms.Button
        $cancelButton.Location = [System.Drawing.Point]::new(12, 662)
        $cancelButton.Size = [System.Drawing.Size]::new(920, 38)
        $cancelButton.Anchor = [Windows.Forms.AnchorStyles]::Bottom -bor [Windows.Forms.AnchorStyles]::Left -bor [Windows.Forms.AnchorStyles]::Right
        $cancelButton.Text = 'Close preview and enter missing numbers in the console'
        $cancelButton.DialogResult = [Windows.Forms.DialogResult]::Cancel
        $cancelButton.AccessibleName = 'Close preview and return to number entry'
        $form.CancelButton = $cancelButton
        [void]$form.Controls.Add($instructions)
        [void]$form.Controls.Add($status)
        [void]$form.Controls.Add($grid)
        [void]$form.Controls.Add($cancelButton)

        for ($i = 0; $i -lt $CrosshairPaths.Count; $i++) {
            $path = [string]$CrosshairPaths[$i]
            $indexLabel = $i.ToString('000')
            $name = [System.IO.Path]::GetFileNameWithoutExtension($path)
            $button = New-Object Windows.Forms.Button
            $button.Name = 'Crosshair_{0}' -f $i
            $button.Tag = [int]$i
            $button.Size = [System.Drawing.Size]::new(116, 112)
            $button.Margin = New-Object Windows.Forms.Padding(5)
            $button.Padding = New-Object Windows.Forms.Padding(3)
            $button.Text = "{0}`r`n{1}" -f $indexLabel, $name
            $button.TextImageRelation = [Windows.Forms.TextImageRelation]::ImageAboveText
            $button.ImageAlign = [System.Drawing.ContentAlignment]::TopCenter
            $button.TextAlign = [System.Drawing.ContentAlignment]::BottomCenter
            $button.AutoEllipsis = $true
            $button.UseVisualStyleBackColor = $false
            $button.BackColor = [System.Drawing.Color]::FromArgb(32, 32, 32)
            $button.ForeColor = [System.Drawing.Color]::White
            $button.AccessibleRole = [Windows.Forms.AccessibleRole]::PushButton
            $button.AccessibleName = 'Crosshair {0}: {1}' -f $indexLabel, $name
            $button.AccessibleDescription = 'Press Enter or Space to select this design for the next player.'
            $thumbnail = New-TpmCrosshairPreviewThumbnail -Path $path
            if ($thumbnail) {
                [void]$session['Images'].Add($thumbnail)
                $button.Image = $thumbnail
            }
            $buttonHandler = {
                try {
                    $change = Set-TpmCrosshairPreviewSelection -Session $state -Index ([int]$button.Tag)
                    if (-not $change.Accepted) { return }
                    $selectedName = [System.IO.Path]::GetFileNameWithoutExtension([string]$state['Paths'][$change.Index])
                    if ($change.Player -eq 'P1') {
                        $button.BackColor = [System.Drawing.Color]::FromArgb(255, 212, 67)
                        $button.ForeColor = [System.Drawing.Color]::Black
                        $button.AccessibleDescription = 'Selected for Player 1. Choose a design for Player 2; the same design is allowed.'
                        $status.Text = ('P1 selected: {0}. Now choose a design for P2.' -f $selectedName)
                    } else {
                        $button.BackColor = [System.Drawing.Color]::FromArgb(95, 219, 138)
                        $button.ForeColor = [System.Drawing.Color]::Black
                        $button.AccessibleDescription = 'Selected for Player 2. The preview is closing.'
                        $p1Name = [System.IO.Path]::GetFileNameWithoutExtension([string]$state['Paths'][[int]$state['P1Index']])
                        $status.Text = ('P1: {0} / P2: {1} selected. Returning to TeknoParrot Manager.' -f $p1Name, $selectedName)
                        $form.DialogResult = [Windows.Forms.DialogResult]::OK
                        $form.Close()
                    }
                } catch {
                    try { Write-Log ("Crosshairs: preview selection event failed -- {0}" -f $_.Exception.Message) } catch {}
                }
            }.GetNewClosure()
            $button.Add_Click($buttonHandler)
            [void]$session['ButtonHandlers'].Add([pscustomobject]@{ Button = $button; Handler = $buttonHandler })
            [void]$grid.Controls.Add($button)
        }

        if ($TimeoutSeconds -gt 0) {
            $timer = New-Object Windows.Forms.Timer
            $timer.Interval = [int][Math]::Min([int]::MaxValue, [Math]::Max(1, $TimeoutSeconds) * 1000)
            $timerHandler = {
                $state['TimedOut'] = $true
                $status.Text = 'Preview time ended. Enter any missing player numbers in the console.'
                $form.Close()
            }.GetNewClosure()
            $timer.Add_Tick($timerHandler)
            $session['Timer'] = $timer
            $session['TimerHandler'] = $timerHandler
            $timer.Start()
        }
        $showAction = {
            param($ownedSession)
            [void]$ownedSession['Form'].ShowDialog()
            $cancelled = ($null -eq $ownedSession['P1Index'] -or $null -eq $ownedSession['P2Index'])
            $reason = if ($ownedSession['TimedOut']) { 'TIMED_OUT' } elseif ($cancelled) { 'CANCELLED' } else { '' }
            return [pscustomobject]@{
                Available = $true
                Cancelled = $cancelled
                P1Index = $ownedSession['P1Index']
                P2Index = $ownedSession['P2Index']
                Reason = $reason
            }
        }.GetNewClosure()
        return (Invoke-TpmCrosshairPreviewWithCleanup -Session $session -Action $showAction)
    } catch {
        $message = $_.Exception.Message
        [void](Close-TpmCrosshairPreviewSession -Session $session)
        try { Write-Log ("Crosshairs: owned preview window unavailable -- {0}" -f $message) } catch {}
        return [pscustomobject]@{ Available = $false; Cancelled = $true; P1Index = $session['P1Index']; P2Index = $session['P2Index']; Reason = 'PREVIEW_WINDOW_UNAVAILABLE'; Error = $message }
    }
}

# =============================================================================
# RESHADE HELPER FUNCTIONS
# =============================================================================

# Scans the first 2 MB of a game exe for graphics API imports.
# Returns the ReShade DLL name to deploy (e.g. "dxgi.dll"), or $null.
function Get-GameApiDll {
    param([string]$ExePath)
    try {
        $longExe = ConvertTo-TpmAutoSyncLongPath -Path $ExePath
        $readLen = [int][Math]::Min((Get-Item -LiteralPath $longExe).Length, 2097152)
        $buf     = New-Object byte[] $readLen
        $fs      = [System.IO.File]::OpenRead($longExe)
        try {
            $pos = 0
            while ($pos -lt $readLen) {
                $n = $fs.Read($buf, $pos, $readLen - $pos)
                if ($n -eq 0) { break }
                $pos += $n
            }
        } finally { $fs.Dispose() }
        $text = [System.Text.Encoding]::ASCII.GetString($buf, 0, $pos)
        # D3D12 checked first: a title that imports both d3d11 and d3d12 (e.g. UWP-wrapped)
        # should be hooked at the outer DX12 layer, not the inner DX11 layer.
        if ($text -match '(?i)d3d12\.dll')          { return 'd3d12.dll'    }
        if ($text -match '(?i)(?:d3d11|dxgi)\.dll') { return 'dxgi.dll'     }
        if ($text -match '(?i)d3d9\.dll')            { return 'd3d9.dll'     }
        if ($text -match '(?i)opengl32\.dll')        { return 'opengl32.dll' }
        return $null
    } catch { return $null }
}

# Scans the first 2 MB of a game executable for legacy DirectX/Glide imports.
# Returns a deterministic API list; inspection failures throw, never imply no APIs.
function Get-GameLegacyApi {
    param([string]$ExePath)
    try {
        $longExe = ConvertTo-TpmAutoSyncLongPath -Path $ExePath
        $readLen = [int][Math]::Min((Get-Item -LiteralPath $longExe -ErrorAction Stop).Length, 2097152)
        $buf = New-Object byte[] $readLen
        $fs = [System.IO.File]::OpenRead($longExe)
        try {
            $pos = 0
            while ($pos -lt $readLen) {
                $n = $fs.Read($buf, $pos, $readLen - $pos)
                if ($n -eq 0) { throw 'Executable changed or became unreadable during legacy API inspection.' }
                $pos += $n
            }
        } finally { $fs.Dispose() }
        $text = [System.Text.Encoding]::ASCII.GetString($buf, 0, $pos)
        $found = New-Object System.Collections.Generic.List[string]
        foreach ($entry in @(
            [pscustomobject]@{ Name = 'D3D8'; Pattern = '(?i)d3d8\.dll' }
            [pscustomobject]@{ Name = 'DDraw'; Pattern = '(?i)ddraw\.dll' }
            [pscustomobject]@{ Name = 'Glide2x'; Pattern = '(?i)glide2x\.dll' }
            [pscustomobject]@{ Name = 'Glide3x'; Pattern = '(?i)glide3x\.dll' }
        )) {
            if ($text -match $entry.Pattern) { [void]$found.Add($entry.Name) }
        }
        return $found.ToArray()
    } catch { throw "Legacy API inspection failed for '$ExePath': $($_.Exception.Message)" }
}

# True when the file starts with the Linux program marker (0x7F 'E' 'L' 'F'). Lindbergh and ElfLdr2 games point at such a file,
# not at a Windows .exe, so they are not "32-bit" or "64-bit" Windows programs and need their own plain wording.
function Test-TpmFileIsElf {
    param([string]$Path)
    try {
        if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $false }
        $fs = [System.IO.File]::OpenRead((ConvertTo-TpmAutoSyncLongPath -Path $Path))
        try {
            $buf = New-Object byte[] 4
            $read = $fs.Read($buf, 0, 4)
            return ($read -eq 4 -and $buf[0] -eq 0x7F -and $buf[1] -eq 0x45 -and $buf[2] -eq 0x4C -and $buf[3] -eq 0x46)
        } finally { $fs.Dispose() }
    } catch { return $false }
}

# Reads the PE Optional Header to determine whether an exe is 32-bit or 64-bit.
# Returns 'x86', 'x64', or $null on error or unrecognized format.
function Get-ExeArchitecture {
    param([string]$ExePath)
    try {
        $fs  = [System.IO.File]::OpenRead((ConvertTo-TpmAutoSyncLongPath -Path $ExePath))
        $buf = New-Object byte[] 4
        try {
            # Read 2-byte MZ signature; use a loop to guard against short reads.
            $pos = 0
            while ($pos -lt 2) {
                $n = $fs.Read($buf, $pos, 2 - $pos)
                if ($n -eq 0) { return $null }
                $pos += $n
            }
            if ($buf[0] -ne 0x4D -or $buf[1] -ne 0x5A) { return $null }
            # Read 4-byte PE header offset at 0x3C.
            [void]$fs.Seek(0x3C, [System.IO.SeekOrigin]::Begin)
            $pos = 0
            while ($pos -lt 4) {
                $n = $fs.Read($buf, $pos, 4 - $pos)
                if ($n -eq 0) { return $null }
                $pos += $n
            }
            $peOffset = [System.BitConverter]::ToInt32($buf, 0)
            # Machine word sits 4 bytes into the PE header (after the 'PE\0\0' signature).
            [void]$fs.Seek($peOffset + 4, [System.IO.SeekOrigin]::Begin)
            $pos = 0
            while ($pos -lt 2) {
                $n = $fs.Read($buf, $pos, 2 - $pos)
                if ($n -eq 0) { return $null }
                $pos += $n
            }
            $machine = [System.BitConverter]::ToUInt16($buf, 0)
            if ($machine -eq 0x014C) { return 'x86' }
            if ($machine -eq 0x8664) { return 'x64' }
            return $null
        } finally { $fs.Dispose() }
    } catch { return $null }
}

# Paginated picker over registered UserProfile XMLs.
# Returns an array of FileInfo objects for the user's selection.
function Select-RegisteredGamesInteractive {
    param([string]$UserProfilesDir, [System.IO.FileInfo[]]$Profiles = $null, [hashtable]$LabelSuffix = @{}, [switch]$DefaultAll)
    $fullBackupDir = Join-Path $UserProfilesDir "FullBackup"
    if ($null -eq $Profiles) {
        $profileCandidates = New-Object System.Collections.Generic.List[object]
        $profileDiscoveryStarted = Get-Date
        $profileDiscoveryCurrent = 0
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Registered-game picker profile discovery' -Current $profileDiscoveryCurrent -Total 0 -StartedAt $profileDiscoveryStarted
        $profileDiscoveryCurrentCompleted = $false
        try {
            Get-ChildItem -LiteralPath $UserProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue | ForEach-Object {
                $profileDiscoveryCurrent++
                if ($_.DirectoryName -ne $fullBackupDir) { [void]$profileCandidates.Add($_) }
                Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Registered-game picker profile discovery' -Current $profileDiscoveryCurrent -Total 0 -StartedAt $profileDiscoveryStarted
            }
            $profileDiscoveryCurrentCompleted = $true
        } finally {
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Registered-game picker profile discovery' -Current $profileDiscoveryCurrent -Total 0 -StartedAt $profileDiscoveryStarted -Complete -Outcome $(if ($profileDiscoveryCurrentCompleted) { 'Final' } else { 'Error' })
        }
        $Profiles = @($profileCandidates.ToArray() | Sort-Object BaseName)
    } else {
        $Profiles = @($Profiles | Where-Object { $_ -and $_.DirectoryName -ne $fullBackupDir } | Sort-Object BaseName)
    }
    $profiles = @($Profiles)
    if ($profiles.Count -eq 0) {
        Write-Host "  No registered games found in UserProfiles." -ForegroundColor Yellow
        return @()
    }
    Write-Host ""
    Write-Host "    A) All $($profiles.Count) registered game(s)" -ForegroundColor White
    Write-Host "    L) Browse and select specific games" -ForegroundColor White
    Write-Host ""
    $pick = Read-TpmChoice -Prompt $(if ($DefaultAll) { '    Enter A or L (Enter = A)' } else { '    Enter A or L' }) -Choices @('A', 'L') -Default $(if ($DefaultAll) { 'A' } else { '' })
    if ($pick -eq "A") { return $profiles }

    $pageSize = 20
    $pages    = [Math]::Ceiling($profiles.Count / $pageSize)
    $page     = 0
    $selected = [System.Collections.Generic.List[object]]::new()
    while ($true) {
        $start = $page * $pageSize
        $end   = [Math]::Min($start + $pageSize - 1, $profiles.Count - 1)
        Write-Host ""
        Write-Host ("    Page {0}/{1}   (games {2}-{3} of {4})   * = selected   Selected so far: {5}" -f `
            ($page + 1), $pages, ($start + 1), ($end + 1), $profiles.Count, $selected.Count) -ForegroundColor Cyan
        for ($i = $start; $i -le $end; $i++) {
            $mark = if ($selected -contains $profiles[$i]) { '*' } else { ' ' }
            Write-Host ("    {0,3}) {1} {2}{3}" -f ($i + 1), $mark, (Get-TpmGameDisplayLabel -ProfilePath $profiles[$i].FullName -Fallback $profiles[$i].BaseName), $(if ($LabelSuffix.ContainsKey($profiles[$i].FullName)) { [string]$LabelSuffix[$profiles[$i].FullName] } else { '' }))
        }
        Write-Host ""
        Write-Host "    Enter number(s) to toggle (e.g. 1,3,5-7) | N=next | P=prev | A=all | D=done" -ForegroundColor DarkCyan
        $inp = (Read-HostSafe "    >").ToUpperInvariant()
        if ($inp -eq "D") { break }
        if ($inp -eq "A") { return $profiles }
        if ($inp -eq "N") { $page = if ($page -lt ($pages - 1)) { $page + 1 } else { 0 }; continue }
        if ($inp -eq "P") { $page = if ($page -gt 0) { $page - 1 } else { $pages - 1 }; continue }
        $nums = Expand-NumberList -str $inp -max $profiles.Count
        foreach ($n in $nums) {
            $item = $profiles[$n - 1]
            if ($selected -contains $item) { [void]$selected.Remove($item) }
            else { [void]$selected.Add($item) }
        }
    }
    return @($selected)
}
# Narrow dgVoodoo2 advanced picker. Unlike the general registered-game picker,
# this never offers an all-games action after an empty detection result.
function Select-DgVoodoo2GamesInteractive {
    param([string]$UserProfilesDir)
    $fullBackupDir = Join-Path $UserProfilesDir "FullBackup"
    $profileCandidates = New-Object System.Collections.Generic.List[object]
    $profileDiscoveryStarted = Get-Date
    $profileDiscoveryCurrent = 0
    Write-TpmCompactExtractionProgress -Phase Scanning -Label 'dgVoodoo2 picker profile discovery' -Current $profileDiscoveryCurrent -Total 0 -StartedAt $profileDiscoveryStarted
    $profileDiscoveryCurrentCompleted = $false
    try {
        Get-ChildItem -LiteralPath $UserProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue | ForEach-Object {
            $profileDiscoveryCurrent++
            if ($_.DirectoryName -ne $fullBackupDir) { [void]$profileCandidates.Add($_) }
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'dgVoodoo2 picker profile discovery' -Current $profileDiscoveryCurrent -Total 0 -StartedAt $profileDiscoveryStarted
        }
        $profileDiscoveryCurrentCompleted = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'dgVoodoo2 picker profile discovery' -Current $profileDiscoveryCurrent -Total 0 -StartedAt $profileDiscoveryStarted -Complete -Outcome $(if ($profileDiscoveryCurrentCompleted) { 'Final' } else { 'Error' })
    }
    $profiles = @($profileCandidates.ToArray() | Sort-Object BaseName)
    if ($profiles.Count -eq 0) { return @() }
    $pageSize = 20
    $pages = [Math]::Ceiling($profiles.Count / $pageSize)
    $page = 0
    $selected = [System.Collections.Generic.List[object]]::new()
    while ($true) {
        $start = $page * $pageSize
        $end = [Math]::Min($start + $pageSize - 1, $profiles.Count - 1)
        Write-Host ""
        Write-Host ("  Advanced dgVoodoo2 selection -- page {0}/{1}" -f ($page + 1), $pages) -ForegroundColor Cyan
        for ($i = $start; $i -le $end; $i++) {
            $mark = if ($selected -contains $profiles[$i]) { '*' } else { ' ' }
            Write-Host ("    {0,3}) {1} {2}" -f ($i + 1), $mark, (Get-TpmGameDisplayLabel -ProfilePath $profiles[$i].FullName -Fallback $profiles[$i].BaseName))
        }
        Write-Host "  Enter number(s) to toggle | N=next | P=previous | D=done | B=back" -ForegroundColor DarkCyan
        $inp = (Read-HostSafe "  >").ToUpperInvariant()
        if ($inp -eq 'D') { return @($selected) }
        if ($inp -eq 'B') { return @() }
        if ($inp -eq 'N') { $page = if ($page -lt ($pages - 1)) { $page + 1 } else { 0 }; continue }
        if ($inp -eq 'P') { $page = if ($page -gt 0) { $page - 1 } else { $pages - 1 }; continue }
        foreach ($n in (Expand-NumberList -str $inp -max $profiles.Count)) {
            $item = $profiles[$n - 1]
            if ($selected -contains $item) { [void]$selected.Remove($item) } else { [void]$selected.Add($item) }
        }
    }
}


# Checks the Authenticode signature on a user-provided ReShade DLL. Unlike
# the BepInEx/FFBPlugin/Eggman-dat downloads (unsigned community builds with
# no published checksum to verify against), ReShade's own installer IS
# code-signed -- and that signature is embedded in the PE itself, so it
# survives extracting/renaming the DLL out of the installer into
# Scripts\ReShade\. This gives an actual trust anchor worth checking before
# deploying the file into every selected game's folder. Informational, not
# a hard gate -- an invalid/missing signature is surfaced loudly but does
# not block setup, since the user supplied this file themselves and a
# revocation-check failure on an offline machine looks identical to a
# tampered file.
function Test-ReShadeDllSignature {
    param([string]$Path)
    try {
        $sig        = Get-AuthenticodeSignature -LiteralPath $Path
        $signer     = if ($sig.SignerCertificate) { $sig.SignerCertificate.Subject } else { "(none)" }
        $thumbprint = if ($sig.SignerCertificate) { $sig.SignerCertificate.Thumbprint } else { "(none)" }
        # Thumbprint is additive -- every existing caller (informational-only
        # display for a user-supplied DLL) reads only .Status/.Signer, so
        # adding a field here does not change this function's existing
        # return contract or behavior for those callers.
        return [pscustomobject]@{ Status = $sig.Status.ToString(); Signer = $signer; Thumbprint = $thumbprint }
    } catch {
        return [pscustomobject]@{ Status = "Error"; Signer = "(none)"; Thumbprint = "(none)" }
    }
}

# Hard trust anchor for the ReShade installer's self-signed Authenticode
# certificate. This is the fingerprint the official reshade.me download
# page itself publishes for the currently-shipping certificate, and it
# matches what was independently observed by downloading and inspecting the
# live installer during this feature's design. See SECURITY.md for the full
# rationale and rotation procedure -- this value can ONLY be changed by a
# maintainer, sourced independently from the allowlisted reshade.me site
# itself, and shipped in a version bump with the change documented in
# SECURITY.md. TPM never auto-updates this value from a live response.
$Script:ReShadeTrustedCertThumbprint = '589690208A5E52FB96980C4A6698F50ACD47C49F'

# The ONLY Get-AuthenticodeSignature .Status value this script accepts as
# "genuinely the intact, legitimately self-signed ReShade installer."
# ReShade's certificate is self-signed with no independent CA trust anchor,
# so Windows can never report Status=Valid for it -- confirmed live by
# downloading and inspecting the real installer during this feature's
# design (and re-confirmed during the P1 #2 remediation pass): a genuine,
# untampered ReShade_Setup_<version>.exe reports Status=UnknownError. This
# is deliberately a single-entry allowlist (deny-by-default), not an
# "everything except the bad ones" denylist -- SECURITY.md documents this
# same rationale and the value must be updated there in the same change if
# it is ever revised.
$Script:ReShadeAcceptedSignatureStatuses = @('UnknownError')

# Fingerprint-gated, status-gated signature check for a downloaded ReShade
# Setup.exe, used ONLY by the auto-download path (Part 3b) -- never changes
# Test-ReShadeDllSignature's own return contract, which stays
# informational-only for user-supplied DLLs.
#
# Trust requires BOTH of the following (P1 #2 remediation: an earlier
# version of this function checked only the thumbprint and ignored
# .Status entirely, which let a HashMismatch -- a tampered or corrupted
# file -- pass as trusted whenever its signer certificate's Thumbprint
# field happened to still read as the pinned value; that is a real
# security bug, not a hypothetical one, and is fixed here):
#   1. Status is on the explicit accept-list ($Script:ReShadeAcceptedSignatureStatuses,
#      today just 'UnknownError' -- the one status a genuine self-signed
#      ReShade installer actually produces). Any other status --
#      HashMismatch (tampered/corrupted), NotSigned, NotTrusted,
#      NotSupportedFileFormat, Incompatible, the "Error" sentinel from an
#      exception, or any future/unrecognized status PowerShell might ever
#      report -- fails closed. This is deny-by-default: only the one
#      explicitly accepted status can ever pass, not "everything except a
#      known-bad list."
#   2. The signer certificate's Thumbprint exactly matches the pinned
#      constant ($Script:ReShadeTrustedCertThumbprint) -- the hard root of
#      trust for a self-signed certificate (a self-signed cert's Subject
#      string alone proves nothing -- anyone can mint a certificate with
#      any Subject text).
# Subject match is layered on top as a secondary sanity check only, never
# a substitute for either of the above. Fails closed (Trusted = $false) on
# any status/fingerprint mismatch, missing/invalid/unparseable signature,
# or exception -- no "proceed anyway" fallback and no auto-adoption of a
# changed fingerprint into config. Logs Status, Subject, and Thumbprint
# always, pass or fail, for audit trail.
function Test-ReShadeSetupTrustedSignature {
    param([string]$Path)
    $result = Test-ReShadeDllSignature -Path $Path
    $expectedSubject = 'CN=ReShade, E=info@reshade.me'
    $statusAccepted  = ($Script:ReShadeAcceptedSignatureStatuses -contains $result.Status)
    $thumbprintMatch = ($result.Thumbprint -and $result.Thumbprint -ieq $Script:ReShadeTrustedCertThumbprint)
    $subjectMatch    = ($result.Signer -eq $expectedSubject)
    # Both gates must pass. Neither alone is sufficient: a matching
    # thumbprint on a HashMismatch-status file (P1 #2) or an accepted
    # status with the wrong thumbprint (a different, untrusted signer)
    # must both fail closed.
    $trusted         = ($statusAccepted -and $thumbprintMatch)
    Write-Log ("ReShadeSetup signature: Status={0} StatusAccepted={1} Subject='{2}' Thumbprint={3} ExpectedThumbprint={4} ThumbprintMatch={5} SubjectMatch={6} Trusted={7}" -f `
        $result.Status, $statusAccepted, $result.Signer, $result.Thumbprint, $Script:ReShadeTrustedCertThumbprint, $thumbprintMatch, $subjectMatch, $trusted)
    return [pscustomobject]@{
        Trusted          = $trusted
        Status           = $result.Status
        StatusAccepted   = $statusAccepted
        Signer           = $result.Signer
        Thumbprint       = $result.Thumbprint
        ThumbprintMatch  = $thumbprintMatch
        SubjectMatch     = $subjectMatch
    }
}

# Invokes a web request without PowerShell's interactive progress renderer.
# Download progress is rendered by TPM's compact status functions instead.
function Invoke-TpmWebRequestSilently {
    param(
        [Parameter(Mandatory)][string]$Uri,
        [switch]$UseBasicParsing,
        [int]$TimeoutSec = 0,
        [hashtable]$Headers = $null,
        [string]$OutFile = '',
        [System.Management.Automation.ActionPreference]$RequestErrorAction = 'Stop'
    )
    $requestParameters = @{
        Uri = $Uri
        UseBasicParsing = $UseBasicParsing
        ErrorAction = $RequestErrorAction
    }
    if ($TimeoutSec -gt 0) { $requestParameters.TimeoutSec = $TimeoutSec }
    if ($Headers) { $requestParameters.Headers = $Headers }
    if ($OutFile) { $requestParameters.OutFile = $OutFile }
    $previousProgressPreference = $ProgressPreference
    $longWait = $false
    try {
        $ProgressPreference = 'SilentlyContinue'
        # A slow server or a whole transfer reports nothing while this call runs: the open bar reads "still working", never "stalled".
        if (Test-Path -LiteralPath 'Function:\Enter-TpmLongWait') { $longWait = Enter-TpmLongWait }
        return (Invoke-WebRequest @requestParameters)
    } finally {
        if ($longWait) { Exit-TpmLongWait }
        $ProgressPreference = $previousProgressPreference
    }
}

# Fetches the current ReShade version string from reshade.me.
# Returns e.g. "6.7.3", or $null if the site cannot be reached.
function Get-ReShadeLatestVersion {
    try {
        $resp = Invoke-TpmWebRequestSilently -Uri "https://reshade.me" -UseBasicParsing -TimeoutSec 10 -RequestErrorAction Stop
        if ($resp.Content -match 'ReShade_Setup_(\d+\.\d+\.\d+(?:\.\d+)?)') { return $Matches[1] }
    } catch {}
    return $null
}

# Constructs the direct download URL for the plain (non-Addon) ReShade
# installer for a given version string, then validates it against the same
# host-allowlist pattern used elsewhere in this script (scheme=https, host
# exactly reshade.me, no userinfo, path under /downloads/). Returns $null on
# an invalid version string or a URL that fails the allowlist -- callers
# must treat $null as "do not download."
function Get-ReShadeSetupDownloadUrl {
    param([string]$Version)
    if ([string]::IsNullOrWhiteSpace($Version) -or $Version -notmatch '^\d+\.\d+\.\d+(\.\d+)?$') { return $null }
    $url = "https://reshade.me/downloads/ReShade_Setup_$Version.exe"
    $parsedUri = $null
    $urlOk = [System.Uri]::TryCreate($url, [System.UriKind]::Absolute, [ref]$parsedUri) -and
             $parsedUri.Scheme -eq 'https' -and
             $parsedUri.Host -eq 'reshade.me' -and
             [string]::IsNullOrEmpty($parsedUri.UserInfo) -and
             $parsedUri.AbsolutePath.StartsWith('/downloads/', [System.StringComparison]::Ordinal)
    if (-not $urlOk) {
        Write-Log "ReShadeSetup: unexpected download URL format -- skipping."
        return $null
    }
    return $url
}

# ReShade_Setup_<version>.exe is a small C# WPF EXE stub with a standard ZIP
# archive appended to the end of the file (self-extracting-archive format).
# This replicates the verified block-scan-for-PK-signature logic from
# crosire/reshade's own published, open-source installer source
# (setup/MainWindow.xaml.cs, InstallStep_InstallReShadeModule): scan forward
# for the ZIP local-file-header signature (PK\x03\x04), open everything from
# that offset onward as a ZipArchive, and require an entry named exactly
# ReShade64.dll (ReShade32.dll is kept too when present, for 32-bit games). Narrowly scoped to this confirmed format
# -- not a generic "try to parse whatever" extractor.
#
# Transactional (P1 #1 remediation): everything is extracted into an
# isolated staging directory (New-TpmStagingDirectory) and fully validated
# there first; $DestDir is never touched until a complete, valid staged set
# exists. Promotion into $DestDir goes through Invoke-TpmTransactionalPromote,
# which is itself rollback-safe -- if promoting either file fails partway
# through and rollback completes, $DestDir is restored to exactly its
# pre-call state. On a recoverable failure (PK signature not found, no
# candidate archive contains the required entry, an extraction-time error
# on it, or a promotion-time error whose rollback completes),
# $DestDir ends up byte-for-byte unchanged from before this function was
# called. If an underlying filesystem mutation loses the original source
# before a valid backup is observable, exact restoration is impossible; the
# transaction instead reports an explicit ROLLBACK FAILED / INCONSISTENT
# condition and preserves recovery evidence. The staging directory is
# removed on ordinary success/failure when cleanup succeeds; it is
# preserved when transaction recovery, transaction cleanup, or ordinary
# staging cleanup fails so
# recovery evidence/residue remains available. Extracts ReShade64.dll into
# $DestDir.
function Expand-ReShadeSelfExtractingArchive {
    param([string]$SetupExePath, [string]$DestDir)

    $allBytes = [System.IO.File]::ReadAllBytes($SetupExePath)
    $pkSig    = [byte[]](0x50, 0x4B, 0x03, 0x04)   # "PK\x03\x04"
    $offsets  = New-Object System.Collections.Generic.List[int]
    $signatureScanTotal = [Math]::Max(0, $allBytes.Length - $pkSig.Length + 1)
    $signatureScanCurrent = 0
    $signatureScanCompleted = $false
    $signatureScanNextReport = 0
    $signatureScanStarted = Get-Date
    try {
        for ($i = 0; $i -lt $signatureScanTotal; $i++) {
            if ($i -ge $signatureScanNextReport) {
                $signatureScanCurrent = $i + 1
                Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade installer signature scan' -Current $signatureScanCurrent -Total $signatureScanTotal -StartedAt $signatureScanStarted
                $signatureScanNextReport = $i + 1048576
            }
            if ($allBytes[$i] -eq $pkSig[0] -and $allBytes[$i + 1] -eq $pkSig[1] -and
                $allBytes[$i + 2] -eq $pkSig[2] -and $allBytes[$i + 3] -eq $pkSig[3]) {
                [void]$offsets.Add($i)
            }
        }
        $signatureScanCompleted = $true
    } finally {
        if ($signatureScanCompleted) { $signatureScanCurrent = $signatureScanTotal }
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade installer signature scan' -Current $signatureScanCurrent -Total $signatureScanTotal -StartedAt $signatureScanStarted -Complete -Outcome $(if ($signatureScanCompleted) { 'Final' } else { 'Error' })
    }
    if ($offsets.Count -eq 0) {
        throw "ReShade installer: no embedded ZIP archive found (PK signature not present) -- format may have changed."
    }

    $required   = @('ReShade64.dll')
    # The official installer carries ReShade32.dll beside ReShade64.dll. The 64-bit file is required; the 32-bit file is kept when it is there,
    # so 32-bit games can use it (checked on the real 6.8.0 installer: both files are present).
    $optionalNames = @('ReShade32.dll')
    $stageNames    = @($required)
    $stagingDir = New-TpmStagingDirectory -Label 'ReShade'
    $rollbackFailurePreserved = $false
    $operationError = $null
    try {
        # The raw PE stub can legitimately contain earlier byte sequences
        # that happen to match the ZIP local-file-header signature without
        # being a real archive (confirmed live during this feature's
        # implementation: the real installer's own icon/resource data
        # produces exactly this -- a PK\x03\x04-prefixed region that
        # .NET's ZipArchive opens without error but reports zero entries).
        # Taking the first raw match unconditionally is therefore not
        # reliable. Instead, try every candidate offset in file order and
        # use the first one that both opens as a valid archive AND
        # contains both required entries -- narrowly scoped to "the
        # confirmed real archive," not a generic best-effort parse.
        $extracted = $false
        $candidateStarted = Get-Date
        $candidateCurrent = 0
        $candidateCurrentDone = $false
        try {
            foreach ($offset in $offsets) {
                $candidateCurrent++
                Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade embedded archive candidates' -Current $candidateCurrent -Total $offsets.Count -StartedAt $candidateStarted
                $zipBytes = New-Object byte[] ($allBytes.Length - $offset)
                [System.Array]::Copy($allBytes, $offset, $zipBytes, 0, $zipBytes.Length)
                $ms      = New-Object System.IO.MemoryStream(, $zipBytes)
                $archive = $null
                try {
                    $archive = [System.IO.Compression.ZipArchive]::new($ms, [System.IO.Compression.ZipArchiveMode]::Read)
                    $entries = @{}
                    $candidateEntries = $null
                    $entryTotal = 0
                    $entryCurrent = 0
                    $entryStarted = Get-Date
                    $entryCurrentDone = $false
                    $entryScanRejected = $false
                    try {
                        # PowerShell hides an exception thrown by a property getter (the result is $null), so a corrupt central directory
                        # would bypass the InvalidDataException catch below. GetEntry is a method call: it validates the central directory
                        # and lets the InvalidDataException surface to that catch.
                        [void]$archive.GetEntry($required[0])
                        $candidateEntries = @($archive.Entries)
                        $entryTotal = $candidateEntries.Count
                        foreach ($e in $candidateEntries) {
                            $entryCurrent++
                            Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade embedded archive entry scan' -Current $entryCurrent -Total $entryTotal -StartedAt $entryStarted
                            $entries[$e.Name] = $e
                        }
                        $entryCurrentDone = $true
                    } catch [System.IO.InvalidDataException] {
                        # FIX64: not an archive after all (the installer stub can hold bytes that only look like one). The candidate search moves on to the next
                        # offset, which is a normal step of the search, so it must not close the shared progress row as FAILED. FIX72: that holds only while no entry
                        # row has started; a bad archive that fails after entry rows began must still close its row (the finally below).
                        $entryScanRejected = ($entryCurrent -eq 0)
                        throw
                    } finally {
                        if (-not $entryScanRejected -and (-not $entryCurrentDone -or $entryTotal -gt 0)) {
                            Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade embedded archive entry scan' -Current $(if ($entryCurrentDone) { $entryCurrent } else { $entryCurrent - 1 }) -Total $entryTotal -StartedAt $entryStarted -Complete -Outcome $(if ($entryCurrentDone) { 'Final' } else { 'Error' })
                        }
                    }
                    $missing = @($required | Where-Object { -not $entries.ContainsKey($_) })
                    if ($missing.Count -gt 0) { continue }

                    # This candidate is the confirmed real archive -- copy both
                    # entries into the STAGING directory only, entirely inside
                    # this loop iteration, so nothing here is ever used after
                    # disposal. $DestDir is not touched at all in this phase.
                    $stageNames = @($required) + @($optionalNames | Where-Object { $entries.ContainsKey($_) })
                    foreach ($name in $stageNames) {
                        $stagePath = Join-Path $stagingDir $name
                        if (-not (Test-PathInside $stagePath $stagingDir)) {
                            throw "SECURITY: refused to stage ReShade entry outside staging folder ($name)."
                        }
                        Copy-TpmZipEntryToFile -Entry $entries[$name] -DestPath $stagePath
                    }
                    $extracted = $true
                } catch [System.IO.InvalidDataException] {
                    # Not a valid archive at this offset -- try the next candidate.
                } finally {
                    if ($archive) { $archive.Dispose() }
                    $ms.Dispose()
                }
                if ($extracted) { break }
            }
            $candidateCurrentDone = $true
        } finally {
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade embedded archive candidates' -Current $(if ($candidateCurrentDone) { $candidateCurrent } else { $candidateCurrent - 1 }) -Total $offsets.Count -StartedAt $candidateStarted -Complete -Outcome $(if ($candidateCurrentDone -and $extracted) { 'Final' } else { 'Error' })
        }
        if (-not $extracted) {
            throw "ReShade installer: expected entry (ReShade64.dll) not found in any embedded archive candidate -- format may have changed."
        }

        # Final validation of the staged set before promotion: both files
        # must actually exist in staging with non-zero length. A failure
        # here (e.g. Copy-TpmZipEntryToFile silently produced a truncated
        # file) fails closed before anything is promoted.
        foreach ($name in $stageNames) {
            $stagePath = Join-Path $stagingDir $name
            if (-not (Test-Path -LiteralPath $stagePath -PathType Leaf) -or (Get-Item -LiteralPath $stagePath).Length -le 0) {
                throw "ReShade installer: staged entry '$name' is missing or empty after extraction -- aborting before any destination change."
            }
        }

        # Only now, with a complete and valid staged set, touch the real
        # destination -- rollback-safe promotion.
        [void](Invoke-TpmTransactionalPromote -StagingDir $stagingDir -DestDir $DestDir -FileNames $stageNames)
    } catch {
        $operationError = $_
        # If Invoke-TpmTransactionalPromote reports a rollback or cleanup
        # failure, its backup copies live under
        # $stagingDir\.tpm-rollback-backup and are the remaining route to
        # manual recovery -- deleting $stagingDir here would destroy that
        # evidence right after creating it. Skip cleanup for either
        # transaction recovery failure mode.
        if ($_.Exception.Message -match 'ROLLBACK FAILED|CLEANUP FAILED') {
            $rollbackFailurePreserved = $true
            Write-Log "Expand-ReShadeSelfExtractingArchive: staging directory '$stagingDir' preserved for manual recovery after a transaction recovery failure."
        }
        throw
    } finally {
        if (-not $rollbackFailurePreserved -and (Test-Path -LiteralPath $stagingDir)) {
            try {
                Remove-Item -LiteralPath $stagingDir -Recurse -Force -ErrorAction Stop
            } catch {
                $cleanupMessage = "TPM STAGING CLEANUP FAILED$(if (-not $operationError) { ' AFTER VERIFIED PROMOTION' }) for '$stagingDir' -- destination state was left valid or restored, but ordinary staging cleanup failed; residue remains at '$stagingDir'. Cleanup error: $($_.Exception.Message)"
                if ($operationError) {
                    $cleanupMessage += " Original operation error: $($operationError.Exception.Message)"
                }
                Write-Log $cleanupMessage
                throw $cleanupMessage
            }
        }
    }
}

# ReShade comes as one DLL per game bit-ness: ReShade64.dll for 64-bit games and ReShade32.dll for 32-bit games. The setup keeps both
# in the same folder, so the 32-bit file is looked for next to the 64-bit one. Returns the DLL that matches the game, or $null when
# that DLL is not there or is not really a 32-bit file. The caller then skips the game and says why; nothing is guessed.
function Get-TpmReShadeSourceDllForArchitecture {
    param([string]$SourceDll, [Parameter(Mandatory)][string]$Architecture)
    if ([string]::IsNullOrWhiteSpace($SourceDll)) { return $null }
    if ($Architecture -eq 'x64') { return $SourceDll }
    if ($Architecture -ne 'x86') { return $null }
    $sourceFolder = [System.IO.Path]::GetDirectoryName($SourceDll)
    if ([string]::IsNullOrWhiteSpace($sourceFolder)) { return $null }
    $sibling = Join-Path $sourceFolder 'ReShade32.dll'
    if (-not (Test-Path -LiteralPath $sibling -PathType Leaf)) { return $null }
    if ((Get-ExeArchitecture -ExePath $sibling) -ne 'x86') { return $null }
    return $sibling
}

# An earlier version only kept ReShade64.dll. When the saved ReShade installer is still next to it, open it again (after the same
# signature check as a fresh download) so ReShade32.dll is there too. Nothing is downloaded and nothing else changes; if anything
# is off, the 32-bit games are simply skipped with a plain message.
function Add-TpmMissingReShade32FromSavedSetup {
    param([string]$SourceDll)
    if ([string]::IsNullOrWhiteSpace($SourceDll) -or -not (Test-Path -LiteralPath $SourceDll -PathType Leaf)) { return }
    if (Get-TpmReShadeSourceDllForArchitecture -SourceDll $SourceDll -Architecture 'x86') { return }
    try {
        $folder = [System.IO.Path]::GetDirectoryName($SourceDll)
        $setup = @(Get-ChildItem -LiteralPath $folder -Filter 'ReShade_Setup_*.exe' -File -ErrorAction Stop | Sort-Object LastWriteTime -Descending | Select-Object -First 1)
        if ($setup.Count -eq 0) { return }
        $signature = Test-ReShadeSetupTrustedSignature -Path $setup[0].FullName
        if (-not $signature.Trusted) { Write-Log 'ReShade 32-bit file: the saved installer did not pass the signature check; not used.'; return }
        try { Expand-ReShadeSelfExtractingArchive -SetupExePath $setup[0].FullName -DestDir $folder }
        catch { if ($_.Exception.Message -notmatch 'CLEANUP FAILED AFTER VERIFIED PROMOTION') { throw }; Write-Log "ReShade 32-bit file: files verified, temporary-file cleanup failed -- $($_.Exception.Message)" }
        Write-Log 'ReShade 32-bit file: added from the saved installer.'
    } catch {
        Write-Log ("ReShade 32-bit file: could not be added from the saved installer -- {0}" -f $_.Exception.Message)
    }
}

# Full ReShade install wizard: version check, preset choice, game picker, deploy.
# Resolves where ReShade would deploy for a given registered game (target
# folder + DLL name), without touching anything. Shared (read-only)
# between Invoke-ReShadeSetup and the Library health check's coverage
# stat, so the two can never disagree about where the DLL would land.
function Get-ReShadeTargetInfo {
    param([System.Xml.XmlDocument]$Doc, [string]$GamePath, [string]$ExeDir)

    $emuType = ""
    $etNode  = $Doc.GameProfile.SelectSingleNode("EmulatorType")
    if ($etNode) { $emuType = $etNode.InnerText.Trim() }

    # OpenParrot games: files go into the openparrot subfolder
    $targetDir = $ExeDir
    if ($emuType -imatch 'openparrot') {
        $opDir = Join-Path $ExeDir "openparrot"
        if ([System.IO.Directory]::Exists((ConvertTo-TpmAutoSyncLongPath -Path $opDir))) { $targetDir = $opDir }
    }

    # BudgieLoader games always use opengl32.dll; others: detect from exe
    $apiDetected = $true
    if ($emuType -imatch 'budgieloader') {
        $dllName = "opengl32.dll"
    } else {
        $detected = Get-GameApiDll -ExePath $GamePath
        if ($detected) { $dllName = $detected } else { $dllName = "dxgi.dll"; $apiDetected = $false }
    }
    return [pscustomobject]@{ TargetDir = $targetDir; DllName = $dllName; ApiDetected = $apiDetected }
}

# Beginner catalog groups, in display order (FIX46: CRT looks first, best first for arcade games). The labels are the owner-approved
# visible group names. The HDR group stays defined for the HDR display gate; no profile in the current catalog uses it.
function Get-TpmReShadeProfileGroups {
    return @(
        [pscustomobject]@{ Group = 'Crt'; Label = 'CRT Choices' }
        [pscustomobject]@{ Group = 'Main'; Label = 'Main Catalog' }
        [pscustomobject]@{ Group = 'Hdr'; Label = 'Actual HDR Setups Only' }
    )
}

function Get-TpmReShadeProfileGroupLabel {
    param([AllowEmptyString()][string]$Group = '')
    $match = Get-TpmReShadeProfileGroups | Where-Object { $_.Group -eq $Group } | Select-Object -First 1
    if ($match) { return [string]$match.Label }
    return ''
}

# Selector rows mirror the terminal's existing group order. Headings carry no ProfileId and are skipped by selection helpers.
function Get-TpmReShadeProfileSelectorRows {
    param([object[]]$Profiles = @())
    $rows = New-Object System.Collections.Generic.List[object]
    $lastGroup = ''
    foreach ($profileEntry in @($Profiles)) {
        if (-not $profileEntry) { continue }
        $group = Get-TpmReShadeProfileTextField -Entry $profileEntry -Name 'Group'
        if ($group -and $group -ne $lastGroup) {
            $groupLabel = Get-TpmReShadeProfileGroupLabel -Group $group
            if ($groupLabel) {
                [void]$rows.Add([pscustomobject]@{
                    RowKind = 'Header'; Selectable = $false; Group = $group
                    DisplayLabel = $groupLabel; ProfileId = ''; ProfileDefinition = $null
                })
            }
        }
        $lastGroup = $group
        [void]$rows.Add([pscustomobject]@{
            RowKind = 'Profile'; Selectable = $true; Group = $group
            DisplayLabel = [string]$profileEntry.DisplayLabel; ProfileId = [string]$profileEntry.ProfileId
            ProfileDefinition = $profileEntry
        })
    }
    return @($rows.ToArray())
}

function Get-TpmReShadeProfileSelectorIndex {
    param([object[]]$Rows = @(), [Parameter(Mandatory)][string]$ProfileId)
    for ($index = 0; $index -lt @($Rows).Count; $index++) {
        $row = @($Rows)[$index]
        if ($row.RowKind -eq 'Profile' -and [string]$row.ProfileId -ceq $ProfileId) { return $index }
    }
    return -1
}

function Get-TpmReShadeGallerySelectorRows {
    param([Parameter(Mandatory)]$Session)
    $rows = @()
    $storedRows = $null
    try { $storedRows = $Session['ProfileSelectorRows'] } catch {}
    if ($null -ne $storedRows) { $rows = @($storedRows) }
    if ($rows.Count -eq 0) {
        $rows = @(Get-TpmReShadeProfileSelectorRows -Profiles @($Session['Profiles']))
        try { $Session['ProfileSelectorRows'] = $rows } catch {}
    }
    return $rows
}

function Get-TpmReShadeProfileSelectorNextIndex {
    param([object[]]$Rows = @(), [int]$FromIndex = -1, [ValidateSet(-1, 1)][int]$Direction = 1)
    $items = @($Rows)
    if ($items.Count -eq 0) { return -1 }
    for ($index = $FromIndex + $Direction; $index -ge 0 -and $index -lt $items.Count; $index += $Direction) {
        if ($items[$index].RowKind -eq 'Profile' -and [bool]$items[$index].Selectable) { return $index }
    }
    $reverse = -1 * $Direction
    for ($index = $FromIndex + $reverse; $index -ge 0 -and $index -lt $items.Count; $index += $reverse) {
        if ($items[$index].RowKind -eq 'Profile' -and [bool]$items[$index].Selectable) { return $index }
    }
    return -1
}

# ---- Actual-HDR gate. The HDR choices (and their whole group) are shown only when the display evaluated for the game reports
# HDR-SPECIFIC support. Generic "advanced color enabled" is NOT used as HDR evidence: it is also true for wide-color-gamut SDR.
# Every display in the evidence carries a real identity (monitor device path, else adapter LUID + target id). A caller that knows
# the display a game will use passes -TargetDisplayId, which must match exactly one identity (even with a single display); an
# unknown, stale, duplicated or missing identity fails closed. With no target and several displays, EVERY display must qualify.
# Windows HDR being active shows only that Windows is composing in HDR on that display; it does not show that the game renders HDR.
function Initialize-TpmDisplayHdrNative {
    if ('TpmDisplayHdrNative' -as [type]) { return $true }
    if ([Environment]::OSVersion.Platform -ne [PlatformID]::Win32NT) { return $false }
    try {
        if (-not ('TpmDisplayHdrNative' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public static class TpmDisplayHdrNative {
    [DllImport("user32.dll")] static extern int GetDisplayConfigBufferSizes(uint flags, out uint numPaths, out uint numModes);
    [DllImport("user32.dll")] static extern int QueryDisplayConfig(uint flags, ref uint numPaths, IntPtr paths, ref uint numModes, IntPtr modes, IntPtr topology);
    [DllImport("user32.dll")] static extern int DisplayConfigGetDeviceInfo(IntPtr header);
    const uint QDC_ONLY_ACTIVE_PATHS = 2;
    const int PathSize = 72;
    const int ModeSize = 64;
    const int TypeGetTargetName = 2;
    const int TypeGetAdvancedColorInfo = 9;
    const int TypeGetAdvancedColorInfo2 = 15;   // DISPLAYCONFIG_DEVICE_INFO_GET_ADVANCED_COLOR_INFO_2 (sequential enum: 11 + 4)
    const int TargetNameSize = 420;
    const int AdvInfo1Size = 32;
    const int AdvInfo2Size = 36;
    static void Header(IntPtr buf, int type, int size, IntPtr path) {
        Marshal.WriteInt32(buf, 0, type);
        Marshal.WriteInt32(buf, 4, size);
        Marshal.WriteInt32(buf, 8, Marshal.ReadInt32(path, 20));
        Marshal.WriteInt32(buf, 12, Marshal.ReadInt32(path, 24));
        Marshal.WriteInt32(buf, 16, Marshal.ReadInt32(path, 28));
    }
    // One string per active display: id|primary|hdrSupported|hdrActive|policyLimited|genericAdvancedColor|activeColorMode
    // primary: 1/0/-1(unknown). The other fields are 1/0/? ('?' = the OS did not answer, which the gate treats as unknown).
    public static string[] Query() {
        List<string> result = new List<string>();
        uint numPaths, numModes;
        int rc = GetDisplayConfigBufferSizes(QDC_ONLY_ACTIVE_PATHS, out numPaths, out numModes);
        if (rc != 0) { result.Add("ERR:" + rc); return result.ToArray(); }
        IntPtr paths = Marshal.AllocHGlobal((int)numPaths * PathSize);
        IntPtr modes = Marshal.AllocHGlobal((int)Math.Max(1, numModes) * ModeSize);
        IntPtr buf = Marshal.AllocHGlobal(512);
        try {
            rc = QueryDisplayConfig(QDC_ONLY_ACTIVE_PATHS, ref numPaths, paths, ref numModes, modes, IntPtr.Zero);
            if (rc != 0) { result.Add("ERR:" + rc); return result.ToArray(); }
            result.Add("OK");
            for (int i = 0; i < (int)numPaths; i++) {
                IntPtr path = IntPtr.Add(paths, i * PathSize);
                int primary = -1;
                uint srcModeIdx = unchecked((uint)Marshal.ReadInt32(path, 12));
                if (srcModeIdx != 0xFFFFFFFF && srcModeIdx < numModes) {
                    IntPtr mode = IntPtr.Add(modes, (int)srcModeIdx * ModeSize);
                    if (Marshal.ReadInt32(mode, 0) == 1) primary = (Marshal.ReadInt32(mode, 28) == 0 && Marshal.ReadInt32(mode, 32) == 0) ? 1 : 0;
                }
                string id = string.Format("{0:x8}{1:x8}-{2}", Marshal.ReadInt32(path, 24), Marshal.ReadInt32(path, 20), Marshal.ReadInt32(path, 28));
                for (int z = 0; z < 512; z += 4) Marshal.WriteInt32(buf, z, 0);
                Header(buf, TypeGetTargetName, TargetNameSize, path);
                if (DisplayConfigGetDeviceInfo(buf) == 0) {
                    string devicePath = Marshal.PtrToStringUni(IntPtr.Add(buf, 164), 128);
                    int nul = devicePath.IndexOf('\0'); if (nul >= 0) devicePath = devicePath.Substring(0, nul);
                    if (devicePath.Length > 0) id = devicePath;
                }
                string generic = "?";
                Header(buf, TypeGetAdvancedColorInfo, AdvInfo1Size, path); Marshal.WriteInt32(buf, 20, 0);
                if (DisplayConfigGetDeviceInfo(buf) == 0) generic = ((Marshal.ReadInt32(buf, 20) >> 1) & 1).ToString();
                string supported = "?", active = "?", limited = "?", mode2 = "?";
                for (int z = 0; z < 512; z += 4) Marshal.WriteInt32(buf, z, 0);
                Header(buf, TypeGetAdvancedColorInfo2, AdvInfo2Size, path);
                if (DisplayConfigGetDeviceInfo(buf) == 0) {
                    int bits = Marshal.ReadInt32(buf, 20);
                    int colorMode = Marshal.ReadInt32(buf, 32);
                    supported = ((bits >> 4) & 1).ToString();   // highDynamicRangeSupported
                    limited = ((bits >> 3) & 1).ToString();     // advancedColorLimitedByPolicy
                    mode2 = colorMode.ToString();               // 0 SDR, 1 WCG, 2 HDR
                    active = (colorMode == 2) ? "1" : "0";      // HDR is ACTIVE only when the active color mode is HDR
                }
                result.Add(id + "|" + primary + "|" + supported + "|" + active + "|" + limited + "|" + generic + "|" + mode2);
            }
        } finally { Marshal.FreeHGlobal(paths); Marshal.FreeHGlobal(modes); Marshal.FreeHGlobal(buf); }
        return result.ToArray();
    }
}
'@
        }
        return [bool]('TpmDisplayHdrNative' -as [type])
    } catch { return $false }
}

# Raw evidence only: { Known; Reason; Displays = @({ Id; IsPrimary; HdrSupported; HdrActive; PolicyLimited; GenericAdvancedColor; ActiveColorMode }) }.
# Any failure or non-Windows host yields Known=$false (fail closed). Definition source: DISPLAYCONFIG_GET_ADVANCED_COLOR_INFO_2 (device
# info type 15), a 36-byte structure with the flag bits at offset 20 (highDynamicRangeSupported bit 4, advancedColorLimitedByPolicy bit 3)
# and the active color mode at offset 32 (0 SDR, 1 WCG, 2 HDR), as defined in the Windows SDK header wingdi.h:
# https://github.com/microsoft/win32metadata/blob/main/generation/WinSDK/RecompiledIdlHeaders/um/wingdi.h#L2983-L3016
# A reviewer verified these values against that header. What stays OPEN is real Windows detection on actual displays (the query has not
# been run on a real machine here) and whether a game itself renders HDR; a wrong or rejected query surfaces as an unknown answer, never as HDR.
function Get-TpmDisplayHdrEvidence {
    if (-not (Initialize-TpmDisplayHdrNative)) { return [pscustomobject]@{ Known = $false; Reason = 'HDR detection is available only on Windows.'; Displays = @() } }
    try { return (ConvertFrom-TpmDisplayHdrRows -Rows @([TpmDisplayHdrNative]::Query())) }
    catch { return [pscustomobject]@{ Known = $false; Reason = ('Display query failed: ' + $_.Exception.Message); Displays = @() } }
}

# Pure parser for the native rows ("OK" then id|primary|hdrSupported|hdrActive|policyLimited|genericAdvancedColor|activeColorMode).
function ConvertFrom-TpmDisplayHdrRows {
    param([string[]]$Rows = @())
    if (@($Rows).Count -eq 0 -or [string]$Rows[0] -ne 'OK') { return [pscustomobject]@{ Known = $false; Reason = ('Display query failed: ' + (@($Rows) -join ' ')); Displays = @() } }
    $flag = { param($v) if ($v -eq '1') { $true } elseif ($v -eq '0') { $false } else { $null } }
    $displays = New-Object System.Collections.Generic.List[object]
    foreach ($row in @($Rows | Select-Object -Skip 1)) {
        $f = [string]$row -split '\|'
        if ($f.Count -lt 7) { return [pscustomobject]@{ Known = $false; Reason = 'Display query returned a malformed record.'; Displays = @() } }
        [void]$displays.Add([pscustomobject]@{ Id = [string]$f[0]; IsPrimary = (& $flag $f[1]); HdrSupported = (& $flag $f[2]); HdrActive = (& $flag $f[3]); PolicyLimited = (& $flag $f[4]); GenericAdvancedColor = (& $flag $f[5]); ActiveColorMode = [string]$f[6] })
    }
    return [pscustomobject]@{ Known = $true; Reason = ''; Displays = @($displays.ToArray()) }
}

function Get-TpmReShadeHdrFingerprint {
    param([object[]]$Displays = @())
    $text = (@($Displays | ForEach-Object { '{0}|{1}|{2}' -f [string]$_.Id, [string]$_.HdrSupported, [string]$_.HdrActive } | Sort-Object) -join ';')
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($text))).Replace('-', '')).ToLowerInvariant() } finally { $sha.Dispose() }
}

# Pure classification of the evidence. State: HIDDEN (unknown, unsupported, unidentified, stale, ambiguous), VISIBLE_UNAVAILABLE (HDR
# supported, not active) or ENABLED (HDR-specific active state). Fails closed. The result names the evaluated display identities and a
# fingerprint of the evidence so a later guard can detect that the answer changed.
function Get-TpmReShadeHdrGate {
    param($Evidence = $null, [string]$TargetDisplayId = '')
    if ($null -eq $Evidence) { $Evidence = Get-TpmDisplayHdrEvidence }
    $hidden = { param($why, $ids = @()) [pscustomobject]@{ State = 'HIDDEN'; Visible = $false; Enabled = $false; Reason = $why; DisplayIds = @($ids); Fingerprint = ''; TargetDisplayId = $TargetDisplayId } }
    if (-not [bool]$Evidence.Known) { return (& $hidden ('HDR capability is unknown. ' + [string]$Evidence.Reason)) }
    $displays = @($Evidence.Displays)
    if ($displays.Count -eq 0) { return (& $hidden 'No active display was reported.') }
    $blankIds = @($displays | Where-Object { -not $_.PSObject.Properties['Id'] -or [string]::IsNullOrWhiteSpace([string]$_.Id) })
    if ($blankIds.Count -gt 0) { return (& $hidden 'A display was reported without an identity, so it cannot be evaluated.') }
    $idGroups = @($displays | Group-Object { ([string]$_.Id).ToLowerInvariant() })
    $duplicated = @($idGroups | Where-Object { $_.Count -gt 1 })
    if ($duplicated.Count -gt 0) { return (& $hidden 'Two displays share one identity, so the display cannot be identified.') }
    $candidates = @()
    if (-not [string]::IsNullOrWhiteSpace($TargetDisplayId)) {
        $candidates = @($displays | Where-Object { ([string]$_.Id).ToLowerInvariant() -eq $TargetDisplayId.ToLowerInvariant() })
        if ($candidates.Count -ne 1) { return (& $hidden 'The display the game will use is not among the active displays (unknown or stale identity).' @($displays | ForEach-Object { [string]$_.Id })) }
    } else {
        $candidates = $displays
    }
    $ids = @($candidates | ForEach-Object { [string]$_.Id })
    foreach ($d in $candidates) {
        if ($null -eq $d.HdrSupported -or $null -eq $d.HdrActive) { return (& $hidden 'The display did not give an HDR-specific answer.' $ids) }
        if (-not [bool]$d.HdrSupported) { return (& $hidden 'The display does not report HDR support.' $ids) }
        if ($d.PSObject.Properties['PolicyLimited'] -and $d.PolicyLimited -eq $true) { return (& $hidden 'Windows policy limits advanced color on this display.' $ids) }
    }
    $fingerprint = Get-TpmReShadeHdrFingerprint -Displays $candidates
    $scope = if ($candidates.Count -eq 1) { 'the evaluated display' } else { 'every active display (the game''s display is not identified)' }
    $allActive = (@($candidates | Where-Object { -not [bool]$_.HdrActive }).Count -eq 0)
    if (-not $allActive) {
        return [pscustomobject]@{ State = 'VISIBLE_UNAVAILABLE'; Visible = $true; Enabled = $false; Reason = ('HDR is supported but Windows HDR is not active on ' + $scope + '.'); DisplayIds = $ids; Fingerprint = $fingerprint; TargetDisplayId = $TargetDisplayId }
    }
    return [pscustomobject]@{ State = 'ENABLED'; Visible = $true; Enabled = $true; Reason = ('Windows reports HDR active on ' + $scope + '. This does not show that the game itself renders HDR.'); DisplayIds = $ids; Fingerprint = $fingerprint; TargetDisplayId = $TargetDisplayId }
}

# Profiles that may be listed for selection. HDR-only profiles are removed entirely (and the HDR group disappears with them)
# unless the gate is Visible. When Visible-but-unavailable they stay listed, flagged, so the chooser can show them without a number.
function Get-TpmReShadeVisibleProfiles {
    param($HdrGate = $null, [switch]$IncludeUnreviewed)
    if ($null -eq $HdrGate) { $HdrGate = Get-TpmReShadeHdrGate }
    $obligationComplete = @{}
    foreach ($effect in @(Get-TpmReShadeEffectCatalog)) {
        $status = Get-TpmReShadeEffectObligationStatus -Effect $effect
        $obligationComplete[[string]$effect.EffectId] = if ($IncludeUnreviewed) { [bool]$status.MetadataComplete } else { [bool]$status.Offerable }
    }
    # An effect whose metadata is incomplete OR whose obligations are not reviewed is never offered, whatever else is true of it.
    return @(Get-TpmReShadeProfiles | Where-Object {
        $entry = $_
        (-not (Test-TpmReShadeProfileRequiresHdr -Entry $entry) -or [bool]$HdrGate.Visible) -and
        (@($(if ($entry.PSObject.Properties['Effects']) { $entry.Effects }) | Where-Object { $null -ne $_ -and (-not $obligationComplete.ContainsKey([string]$_) -or -not $obligationComplete[[string]$_]) }).Count -eq 0)
    })
}

# Profile ids removed from the beginner catalog. A saved choice or an installed TPM-owned deployment that refers to one of
# these is reported, never silently remapped to another profile, and its installed files are never touched by that report.
# FIX46 (owner decision 2026-11-02): the sharpening-only, color-strength-only, no-visible-change and HDR-only profiles were
# removed from the offered list; their effects stay in the approved catalog so earlier installs are still recognized.
function Get-TpmReShadeRetiredProfiles {
    return @(
        [pscustomobject]@{ ProfileId = 'Cartoon'; FriendlyName = 'Cartoon' }
        [pscustomobject]@{ ProfileId = 'FilmGrain'; FriendlyName = 'Film Grain' }
        [pscustomobject]@{ ProfileId = 'Monochrome'; FriendlyName = 'Monochrome' }
        [pscustomobject]@{ ProfileId = 'Sepia'; FriendlyName = 'Sepia Tone' }
        [pscustomobject]@{ ProfileId = 'Vignette'; FriendlyName = 'Vignette' }
        [pscustomobject]@{ ProfileId = 'SmoothEdges'; FriendlyName = 'Smooth Edges' }
        [pscustomobject]@{ ProfileId = 'CleanSharp'; FriendlyName = 'Clean & Sharp' }
        [pscustomobject]@{ ProfileId = 'AdaptiveClarity'; FriendlyName = 'Adaptive Clarity' }
        [pscustomobject]@{ ProfileId = 'SmoothGradients'; FriendlyName = 'Smooth Gradients' }
        [pscustomobject]@{ ProfileId = 'Vivid'; FriendlyName = 'Vivid Arcade' }
        [pscustomobject]@{ ProfileId = 'ShadowMidtoneBalance'; FriendlyName = 'Shadow & Midtone Balance' }
        [pscustomobject]@{ ProfileId = 'ExposureTint'; FriendlyName = 'Exposure & Tint' }
        [pscustomobject]@{ ProfileId = 'ColorBalance'; FriendlyName = 'Color Balance' }
        [pscustomobject]@{ ProfileId = 'EnhancedArcade'; FriendlyName = 'Enhanced Arcade' }
        [pscustomobject]@{ ProfileId = 'DetailPreservingSharpen'; FriendlyName = 'Detail-Preserving Sharpen' }
        [pscustomobject]@{ ProfileId = 'FilmicSharpen'; FriendlyName = 'Filmic Sharpen' }
        [pscustomobject]@{ ProfileId = 'Colorfulness'; FriendlyName = 'Colorfulness' }
        [pscustomobject]@{ ProfileId = 'FastGameEnhancement'; FriendlyName = 'Fast Game Enhancement' }
        [pscustomobject]@{ ProfileId = 'HdrHighlightMapping'; FriendlyName = 'HDR Highlight Mapping' }
        [pscustomobject]@{ ProfileId = 'HdrBlackLevelFix'; FriendlyName = 'HDR Black-Level Fix' }
    )
}

function Get-TpmReShadeRetiredProfile {
    param([string]$ProfileId)
    return (Get-TpmReShadeRetiredProfiles | Where-Object { $_.ProfileId -eq $ProfileId } | Select-Object -First 1)
}

# Arcade catalog (FIX46 owner decision 2026-11-02: only effects that clearly do something valuable for arcade play, each with a visible
# preview difference, a one-line "what this does in a game" description and a rough cost; best first). FIX51 (GitHub issue 383) adds five
# CRT looks from the pinned RSRetroArch port (CRT-Geom, CRT-Aperture, CRT-Easymode, CRT-Hyllian, CRT-ZFast) and orders the list best first
# for arcade games. Original (reference/off, not an effect) plus sixteen profiles built only from approved effects: ten CRT looks alone or
# combined with glow or black/white points, glow alone, two 3D-game combinations with anti-aliasing, contrast alone and black/white points alone.
# PerformanceClass is a rough, unmeasured cost estimate (LOW/MEDIUM/HIGH shown as light/medium/heavy); the CRT Lottes and Curves
# classes follow their effect rows, the others are estimates for effects whose rows are UNMEASURED.
function Get-TpmReShadeProfiles {
    $new = {
        param([string]$Id, [string]$Friendly, [string]$Technical, [string]$Description, [string]$Group, [string[]]$Effects, [string[]]$Files, [string[]]$Techniques, [string]$Cost, [string]$Resolution = 'UNMEASURED', [string]$Fallback = 'Original', [string]$Note = '', [string]$PreviewNote = '', [hashtable]$Parameters = @{})
        [pscustomobject]@{
            ProfileId = $Id; FriendlyName = $Friendly; TechnicalName = $Technical; DisplayLabel = ('{0} [{1}]' -f $Friendly, $Technical); Description = $Description; Group = $Group
            Recommended = $false; MeasuredEvidence = $false; Effects = @($Effects); RequiredEffects = @($Files)
            TechniqueOrder = @($Techniques); Parameters = $Parameters; PerformanceClass = $Cost
            ResolutionSensitivity = $Resolution; CompatibilityState = 'ADVISORY_UNMEASURED'
            CompatibilityNote = $Note; RequiresHdr = $false; PreviewApproximation = 'APPROXIMATE'; PreviewNote = $PreviewNote
            ConflictsWith = @()
            FallbackProfileId = $Fallback; PreviewAsset = 'TPM-preview-landscape.png'; SchemaVersion = 2
        }
    }
    $smaaPreview = 'The edge smoothing works on the jagged edges of 3D game graphics; the still preview picture has none, so the preview shows only the {0} part.'
    # Per-effect preset values (FIX51). Every key is a uniform name taken from the pinned .fx file named in the section; values are strings so
    # the generated preset never depends on the culture's decimal separator. The size values (640x480, the usual arcade picture size) are set
    # equal for "screen" and "frame" as the shaders' own tooltips ask for non-emulator use; CRT-Geom needs interlace_toggle 5 so a 480-line
    # frame is not treated as interlaced (field flicker) and CRT-Easymode needs SCANLINE_CUTOFF 1000 because it switches scanlines off for
    # frames of SCANLINE_CUTOFF lines or more (its default 400 would remove them at 480 lines). The look on a real game is not measured.
    $geomParameters = @{ 'CRTGeom.fx' = ([ordered]@{ texture_sizeX = '640'; texture_sizeY = '480'; video_sizeX = '640'; video_sizeY = '480'; CURVATURE = '1'; cornersize = '0.05'; DOTMASK = '0.3'; scanline_weight = '0.3'; interlace_toggle = '5'; OVERSAMPLE = '1' }) }
    $apertureParameters = @{ 'CRTAperture.fx' = ([ordered]@{ resX = '640'; resY = '480'; video_sizeX = '640'; video_sizeY = '480'; SHARPNESS_IMAGE = '1'; SHARPNESS_EDGES = '3'; MASK_COLORS = '3'; MASK_STRENGTH = '0.4'; MASK_SIZE = '1'; GLOW_HALATION = '0.1'; BRIGHTNESS = '1.5' }) }
    $easymodeParameters = @{ 'CRTEasymode.fx' = ([ordered]@{ texture_sizeX = '640'; texture_sizeY = '480'; video_sizeX = '640'; video_sizeY = '480'; SHARPNESS_H = '0.5'; SHARPNESS_V = '1'; MASK_STRENGTH = '0.3'; SCANLINE_STRENGTH = '1'; SCANLINE_CUTOFF = '1000'; BRIGHT_BOOST = '1.2' }) }
    $hyllianParameters = @{ 'CRTHyllian.fx' = ([ordered]@{ CRT_MULRES_X = '1'; CRT_MULRES_Y = '1'; texture_sizeX = '640'; texture_sizeY = '480'; video_sizeX = '640'; video_sizeY = '480'; PHOSPHOR = '1'; SCANLINES_STRENGTH = '0.4'; COLOR_BOOST = '1.5'; BEAM_MIN_WIDTH = '0.86'; BEAM_MAX_WIDTH = '1'; CRT_ANTI_RINGING = '0.8' }) }
    $zfastParameters = @{ 'zfast_crt.fx' = ([ordered]@{ video_sizeX = '640'; video_sizeY = '480'; FINEMASK = '1'; BLACK_OUT_BORDER = '0'; BLURSCALEX = '0.3'; LOWLUMSCAN = '6'; HILUMSCAN = '8'; BRIGHTBOOST = '1.25'; MASK_DARK = '0.25'; MASK_FADE = '0.8' }) }
    $profiles = New-Object System.Collections.Generic.List[object]
    [void]$profiles.Add([pscustomobject]@{
        ProfileId = 'Original'; FriendlyName = 'Original'; TechnicalName = ''; DisplayLabel = 'Original'; Description = 'No visual processing.'; Group = ''
        Recommended = $false; MeasuredEvidence = $false; Effects = @(); RequiredEffects = @(); TechniqueOrder = @()
        Parameters = @{}; PerformanceClass = 'LOW'; ResolutionSensitivity = 'LOW'
        CompatibilityState = 'ADVISORY_UNMEASURED'; CompatibilityNote = ''; RequiresHdr = $false; PreviewApproximation = 'REFERENCE'; PreviewNote = ''
        ConflictsWith = @(); FallbackProfileId = 'Original'
        PreviewAsset = 'TPM-preview-landscape.png'; SchemaVersion = 2
    })
    # ---- CRT Choices
    [void]$profiles.Add((& $new -Id 'CurvedArcadeMonitor' -Friendly 'Curved Arcade Monitor' -Technical 'CRT-Geom' -Description 'Makes the game look like it is on a curved arcade cabinet monitor: bent screen edges, rounded corners, scanlines and a fine dot pattern.' -Group 'Crt' -Effects @('RSRetroArch.CRTGeom') -Files @('CRTGeom.fx') -Techniques @('GeomCRT') -Cost 'MEDIUM' -Fallback 'LightweightCrt' -Parameters $geomParameters -PreviewNote 'A curved-monitor look (bent screen edges, dark rounded corners, scanlines and a dot pattern). It is a TeknoParrot Manager approximation, not CRT-Geom executing.'))
    [void]$profiles.Add((& $new -Id 'ClassicCrt' -Friendly 'Classic Arcade CRT' -Technical 'CRT Lottes' -Description 'Makes the game look like a classic arcade CRT screen: visible scanlines and a soft shadow-mask pattern.' -Group 'Crt' -Effects @('FXShaders.CRT_Lottes') -Files @('CRT_Lottes.fx', 'CRT_Lottes.fxh') -Techniques @('CRT_Lottes') -Cost 'HIGH' -Resolution 'HIGH' -Fallback 'LightweightCrt'))
    [void]$profiles.Add((& $new -Id 'SharpApertureGrille' -Friendly 'Sharp Aperture Grille' -Technical 'CRT-Aperture' -Description 'A sharp, bright Trinitron-style picture: fine red, green and blue stripes, clear scanlines and a light glow; the screen stays flat.' -Group 'Crt' -Effects @('RSRetroArch.CRTAperture') -Files @('CRTAperture.fx') -Techniques @('ApertureCRT') -Cost 'MEDIUM' -Fallback 'LightweightCrt' -Parameters $apertureParameters -PreviewNote 'A sharp stripe-mask look with scanlines and a light glow. It is a TeknoParrot Manager approximation, not CRT-Aperture executing.'))
    [void]$profiles.Add((& $new -Id 'EasymodeCrt' -Friendly 'Balanced Flat CRT' -Technical 'CRT-Easymode' -Description 'A balanced flat CRT look: clear scanlines and a gentle color mask with sharp edges and no screen curve.' -Group 'Crt' -Effects @('RSRetroArch.CRTEasymode') -Files @('CRTEasymode.fx') -Techniques @('EasymodeCRT') -Cost 'MEDIUM' -Fallback 'LightweightCrt' -Parameters $easymodeParameters -PreviewNote 'A flat look with dark scanlines and a gentle color mask. It is a TeknoParrot Manager approximation, not CRT-Easymode executing.'))
    [void]$profiles.Add((& $new -Id 'HyllianCrt' -Friendly 'Sharp Phosphor CRT' -Technical 'CRT-Hyllian' -Description 'A sharp, vivid CRT look: crisp pixels, scanlines that fade between the lines and a fine phosphor dot pattern.' -Group 'Crt' -Effects @('RSRetroArch.CRTHyllian') -Files @('CRTHyllian.fx') -Techniques @('CRTHyllian') -Cost 'MEDIUM' -Fallback 'LightweightCrt' -Parameters $hyllianParameters -PreviewNote 'A vivid look with scanlines and a phosphor dot pattern. It is a TeknoParrot Manager approximation, not CRT-Hyllian executing.'))
    [void]$profiles.Add((& $new -Id 'CrtGlow' -Friendly 'Arcade CRT Glow' -Technical 'CRT Lottes + ArcaneBloom' -Description 'The classic arcade CRT look plus a soft glow around bright areas, like a bright cabinet screen.' -Group 'Crt' -Effects @('FXShaders.CRT_Lottes', 'FXShaders.ArcaneBloom') -Files @('CRT_Lottes.fx', 'CRT_Lottes.fxh', 'ArcaneBloom.fx', 'ArcaneBloom.fxh') -Techniques @('CRT_Lottes', 'ArcaneBloom') -Cost 'HIGH' -Resolution 'HIGH' -Fallback 'ScanlineGlow'))
    [void]$profiles.Add((& $new -Id 'DetailedCrt' -Friendly 'Detailed Arcade CRT' -Technical 'CRT-Royale' -Description 'The most detailed CRT look, with a fine phosphor mask and scanlines; it needs a strong graphics card.' -Group 'Crt' -Effects @('Akgunter.CRTRoyale') -Files @('crt-royale.fx') -Techniques @('CRT_Royale') -Cost 'HIGH' -Fallback 'ClassicCrt' -PreviewNote 'A generic arcade-monitor look (scanlines and a phosphor-style mask). It is a TeknoParrot Manager approximation, not CRT-Royale executing.'))
    [void]$profiles.Add((& $new -Id 'FastCrt' -Friendly 'Fast CRT' -Technical 'CRT-ZFast' -Description 'Scanlines and a light mask for a CRT look that costs very little speed, so it also runs well on slower PCs.' -Group 'Crt' -Effects @('RSRetroArch.CRTZFast') -Files @('zfast_crt.fx') -Techniques @('CRTZFast') -Cost 'LOW' -Parameters $zfastParameters -PreviewNote 'A simple scanline and mask look. It is a TeknoParrot Manager approximation, not CRT-ZFast executing.'))
    [void]$profiles.Add((& $new -Id 'LightweightCrt' -Friendly 'Lightweight CRT' -Technical 'CRT-Pi' -Description 'Simple scanlines for a retro arcade look that also runs well on slower PCs.' -Group 'Crt' -Effects @('RSRetroArch.CRTPi') -Files @('CRTPi.fx') -Techniques @('CRTPi') -Cost 'LOW' -PreviewNote 'A generic scanline look. It is a TeknoParrot Manager approximation, not CRT-Pi executing.'))
    [void]$profiles.Add((& $new -Id 'ScanlineGlow' -Friendly 'Scanline Glow' -Technical 'CRT-Pi + ArcaneBloom' -Description 'Simple scanlines plus a soft glow around bright areas, at a lower cost than the classic CRT look.' -Group 'Crt' -Effects @('RSRetroArch.CRTPi', 'FXShaders.ArcaneBloom') -Files @('CRTPi.fx', 'ArcaneBloom.fx', 'ArcaneBloom.fxh') -Techniques @('CRTPi', 'ArcaneBloom') -Cost 'MEDIUM' -Fallback 'LightweightCrt' -PreviewNote 'A generic scanline look with a soft glow. It is a TeknoParrot Manager approximation, not CRT-Pi and ArcaneBloom executing.'))
    [void]$profiles.Add((& $new -Id 'BrightScanlines' -Friendly 'Bright Scanlines' -Technical 'Levels + CRT-Pi' -Description 'Simple scanlines with deeper blacks and brighter whites, so the picture stays bright behind the scanlines.' -Group 'Crt' -Effects @('SweetFX.Levels', 'RSRetroArch.CRTPi') -Files @('Levels.fx', 'CRTPi.fx') -Techniques @('Levels', 'CRTPi') -Cost 'LOW' -Fallback 'LightweightCrt' -PreviewNote 'A generic scanline look with deeper blacks and brighter whites. It is a TeknoParrot Manager approximation, not Levels and CRT-Pi executing.'))
    # ---- Main Catalog
    [void]$profiles.Add((& $new -Id 'ArcadeGlow' -Friendly 'Arcade Glow' -Technical 'ArcaneBloom' -Description 'A soft glow around bright lights and effects, like a bright arcade cabinet screen.' -Group 'Main' -Effects @('FXShaders.ArcaneBloom') -Files @('ArcaneBloom.fx', 'ArcaneBloom.fxh') -Techniques @('ArcaneBloom') -Cost 'MEDIUM'))
    [void]$profiles.Add((& $new -Id 'Crisp3d' -Friendly 'Crisp 3D' -Technical 'SMAA + Curves + Levels' -Description 'Smooths jagged edges in 3D games and adds stronger contrast with deeper blacks.' -Group 'Main' -Effects @('SweetFX.SMAA', 'SweetFX.Curves', 'SweetFX.Levels') -Files @('SMAA.fx', 'SMAA.fxh', 'Curves.fx', 'Levels.fx') -Techniques @('SMAA', 'Curves', 'Levels') -Cost 'MEDIUM' -Resolution 'LOW' -PreviewNote ($smaaPreview -f 'contrast and black/white')))
    [void]$profiles.Add((& $new -Id 'Crisp3dGlow' -Friendly 'Crisp 3D Glow' -Technical 'SMAA + Levels + ArcaneBloom' -Description 'Smooths jagged edges in 3D games, deepens blacks and adds a soft glow around bright areas.' -Group 'Main' -Effects @('SweetFX.SMAA', 'SweetFX.Levels', 'FXShaders.ArcaneBloom') -Files @('SMAA.fx', 'SMAA.fxh', 'Levels.fx', 'ArcaneBloom.fx', 'ArcaneBloom.fxh') -Techniques @('SMAA', 'Levels', 'ArcaneBloom') -Cost 'MEDIUM' -Fallback 'Crisp3d' -PreviewNote ($smaaPreview -f 'black/white and glow')))
    [void]$profiles.Add((& $new -Id 'ContrastCurves' -Friendly 'Balanced Contrast' -Technical 'Curves' -Description 'Stronger contrast in the midtones, so a flat-looking game gets more depth.' -Group 'Main' -Effects @('SweetFX.Curves') -Files @('Curves.fx') -Techniques @('Curves') -Cost 'MEDIUM' -Resolution 'LOW'))
    [void]$profiles.Add((& $new -Id 'Levels' -Friendly 'Black/White Point Adjustment' -Technical 'Levels' -Description 'Deeper blacks and brighter whites for games that look washed out or gray.' -Group 'Main' -Effects @('SweetFX.Levels') -Files @('Levels.fx') -Techniques @('Levels') -Cost 'LOW' -Resolution 'LOW'))
    return @($profiles.ToArray())
}

