function Get-TpmReShadeObligationReviewRecord {
    param([Parameter(Mandatory)][string]$EffectId, $Effect = $null)
    $evidence = (Get-TpmReShadeLicenseEvidenceTable)[$EffectId]
    $items = New-Object System.Collections.Generic.List[string]
    if ($null -eq $evidence) {
        [void]$items.Add('NO_EVIDENCE_RECORD: no upstream verification (pinned bytes, in-file headers, license copies, include closure) is recorded for this effect')
    } else {
        $specs = $null
        if ($null -ne $Effect) {
            try {
                $specs = @(Get-TpmReShadeApprovedEffectFilesForEffect -Effect $Effect)
                if ([string]$evidence.PinDigest -ne (Get-TpmReShadeEffectPinDigest -Effect $Effect -Specs $specs)) {
                    [void]$items.Add('EVIDENCE_STALE: the acquisition/deployment specification (repositories, paths, hashes, lengths, dependencies and search paths, license basis and attribution, generated notice and include bytes) changed after the recorded verification; re-verify against upstream')
                }
            } catch { [void]$items.Add(('SPECIFICATION_INVALID: the acquisition specification could not be built ({0})' -f $_.Exception.Message)) }
        }
        if ([int]$evidence.PinnedRowsVerified -ne [int]$evidence.PinnedRows) {
            [void]$items.Add(('PINNED_BYTES_UNVERIFIED: {0} of {1} pinned files matched upstream on SHA-256 and byte length' -f $evidence.PinnedRowsVerified, $evidence.PinnedRows))
        }
        if ([int]$evidence.HeaderBasisVerified -ne [int]$evidence.HeaderBasisFiles) {
            [void]$items.Add(('FILE_NOTICE_UNVERIFIED: {0} of {1} files that rely on their own in-file license notice carry a matching notice' -f $evidence.HeaderBasisVerified, $evidence.HeaderBasisFiles))
        }
        if ([int]$evidence.RepositoryBasisFiles -gt 0 -and -not [bool]$evidence.RepositoryLicenseCopyVerified) {
            [void]$items.Add('REPOSITORY_LICENSE_COPY_UNVERIFIED: files rely on the repository license but no matching license text copy is verified')
        }
        if ([int]$evidence.IncludeStatementsResolved + @($evidence.InactiveIncludes).Count + @($evidence.ActiveUnresolvedIncludes).Count -ne [int]$evidence.IncludeStatementsChecked) {
            [void]$items.Add('INCLUDE_RECORD_INCONSISTENT: the recorded include statements are not fully accounted for as resolved, inactive or unresolved')
        }
        if (@($evidence.ActiveUnresolvedIncludes).Count -gt 0) {
            [void]$items.Add(('DEPENDENCY_UNRESOLVED: active include(s) that resolve to no deployed file: {0}' -f (@($evidence.ActiveUnresolvedIncludes) -join ', ')))
        }
        foreach ($inactive in @($evidence.InactiveIncludes)) {
            $conditionOk = (@($inactive.Conditions | Where-Object { [string]$_ -match '=> false' }).Count -gt 0)
            $sourceOk = $true
            if ($null -ne $specs) {
                $includer = @($specs | Where-Object { [string]$_.RelativePath -ieq [string]$inactive.IncludedBy } | Select-Object -First 1)
                $sourceOk = ($includer.Count -eq 1 -and ([string]$includer[0].SHA256).ToUpperInvariant() -eq ([string]$inactive.IncluderSha256).ToUpperInvariant())
            }
            if (-not $conditionOk -or -not $sourceOk) {
                [void]$items.Add(('INACTIVE_INCLUDE_RECORD_STALE: {0} (line {1} of {2}) is recorded as inactive but the recorded condition is not statically false or the including file is no longer the verified pinned file' -f $inactive.Include, $inactive.Line, $inactive.IncludedBy))
            }
        }
    }
    if ($items.Count -eq 0) {
        return [pscustomobject]@{ Status = 'REVIEWED'; ReviewedBy = [string]$evidence.Method; Reference = [string]$evidence.Reference; OutstandingItems = @(); Verified = @($evidence.Verified); NonDefects = @($evidence.NonDefects) }
    }
    return [pscustomobject]@{ Status = 'EVIDENCE_INCOMPLETE'; ReviewedBy = ''; Reference = ''; OutstandingItems = @($items.ToArray()); Verified = @(); NonDefects = @() }
}

# Structural check that an approved effect carries everything its license needs before it may be offered: a license statement, attribution,
# a stated source/notice obligation, a license basis for every file, and either an upstream license text copy or an in-file notice that
# is deployed unmodified. Gaps are listed; an effect with any gap is not offered.
function Get-TpmReShadeEffectObligationStatus {
    param([Parameter(Mandatory)]$Effect)
    $gaps = New-Object System.Collections.Generic.List[string]
    if ([string]::IsNullOrWhiteSpace([string]$Effect.License)) { [void]$gaps.Add('MISSING_LICENSE') }
    if ([string]::IsNullOrWhiteSpace([string]$Effect.Attribution)) { [void]$gaps.Add('MISSING_ATTRIBUTION') }
    if ([string]::IsNullOrWhiteSpace([string]$Effect.SourceObligations)) { [void]$gaps.Add('MISSING_OBLIGATIONS') }
    $fileCount = @($Effect.RelativeFiles).Count
    if (@($Effect.FileLicenses).Count -ne $fileCount) { [void]$gaps.Add('FILE_LICENSE_BASIS_INCOMPLETE') }
    if (@($Effect.SHA256).Count -ne $fileCount -or @($Effect.ByteLengths).Count -ne $fileCount) { [void]$gaps.Add('FILE_PIN_INCOMPLETE') }
    $needsRepositoryText = @($Effect.FileLicenses | Where-Object { [string]$_ -eq 'REPOSITORY-LICENSE' }).Count -gt 0
    if ($needsRepositoryText -and @($Effect.NoticeFiles).Count -eq 0) { [void]$gaps.Add('REPOSITORY_LICENSE_TEXT_NOT_COPIED') }
    $copyleft = [string]$Effect.License -match 'GPL|CC-BY-SA'
    if ($copyleft -and [string]$Effect.SourceObligations -notmatch '(?i)source|share|license') { [void]$gaps.Add('COPYLEFT_OBLIGATION_NOT_STATED') }
    # Metadata completeness is NOT reviewed completeness: Offerable (shown and deployable) additionally needs a REVIEWED record with nothing outstanding.
    $review = if ($Effect.PSObject.Properties['ObligationReview']) { $Effect.ObligationReview } else { $null }
    $outstanding = @()
    if ($review -and $review.PSObject.Properties['OutstandingItems']) { $outstanding = @($review.OutstandingItems | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }) }
    $reviewComplete = ($null -ne $review -and [string]$review.Status -eq 'REVIEWED' -and -not [string]::IsNullOrWhiteSpace([string]$review.ReviewedBy) -and -not [string]::IsNullOrWhiteSpace([string]$review.Reference) -and $outstanding.Count -eq 0)
    $metadataComplete = ($gaps.Count -eq 0)
    return [pscustomobject]@{ EffectId = [string]$Effect.EffectId; Complete = $metadataComplete; MetadataComplete = $metadataComplete; ReviewStatus = $(if ($review) { [string]$review.Status } else { 'NO_REVIEW_RECORD' }); ReviewComplete = $reviewComplete; Offerable = ($metadataComplete -and $reviewComplete); Gaps = @($gaps.ToArray()); OutstandingItems = @($outstanding) }
}

function Get-TpmReShadeEffectNoticeBytes {
    param([Parameter(Mandatory)]$Effect)
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add('TeknoParrot Manager - third-party ReShade effect notice')
    [void]$lines.Add('')
    [void]$lines.Add(('Effect      : {0} ({1})' -f $Effect.FriendlyName, $Effect.EffectId))
    [void]$lines.Add(('Source      : https://github.com/{0}/tree/{1}' -f $Effect.Repository, $Effect.PinnedCommit))
    [void]$lines.Add(('License     : {0}' -f $Effect.License))
    [void]$lines.Add(('Attribution : {0}' -f $Effect.Attribution))
    [void]$lines.Add(('Obligations : {0}' -f $Effect.SourceObligations))
    [void]$lines.Add('')
    [void]$lines.Add('Files below are verbatim copies fetched from the immutable commit above and accepted only on their exact')
    [void]$lines.Add('SHA-256 and byte length. TeknoParrot Manager does not modify them. Per-file license basis is listed after each path.')
    $files = @($Effect.RelativeFiles)
    $destinations = @($Effect.DestinationFiles)
    for ($i = 0; $i -lt $files.Count; $i++) {
        $basis = if (@($Effect.FileLicenses).Count -gt $i) { [string]$Effect.FileLicenses[$i] } else { 'REPOSITORY-LICENSE' }
        [void]$lines.Add(('  {0}  ->  {1}  [{2}]' -f $files[$i], $destinations[$i], $basis))
    }
    foreach ($notice in @($Effect.NoticeFiles)) { [void]$lines.Add(('License text copy: {0} (from {1} {2}, {3})' -f $notice.DestinationRelativePath, $notice.Repository, $notice.PinnedCommit, $notice.SourceRelativePath)) }
    [void]$lines.Add('')
    [void]$lines.Add('Where a file carries its own license notice, that notice governs that file. Where it carries none, the license text copy')
    [void]$lines.Add('above (the upstream repository LICENSE file) is the stated basis. This notice grants no additional rights.')
    return ,([Text.Encoding]::ASCII.GetBytes(($lines -join "`r`n") + "`r`n"))
}

function Get-TpmReShadeApprovedEffectFiles {
    param([Parameter(Mandatory)][string]$EffectId)
    $effect = @(Get-TpmReShadeEffectCatalog | Where-Object EffectId -eq $EffectId)[0]
    if (-not $effect) { throw "Effect is not approved: $EffectId" }
    return @(Get-TpmReShadeApprovedEffectFilesForEffect -Effect $effect)
}

# The acquisition/deployment specifications of ONE catalog row (effect files, textures, license copies, generated NOTICE and shared include
# bytes). It does not look the catalog up, so the license evidence record can be bound to these exact specifications while the catalog is
# still being built.
function Get-TpmReShadeApprovedEffectFilesForEffect {
    param([Parameter(Mandatory)]$Effect)
    $effect = $Effect
    $files = New-Object System.Collections.Generic.List[object]
    $safeEffectCache = $effect.EffectId -replace '[^A-Za-z0-9_.-]', '_'
    $destinationFiles = @(if ($effect.PSObject.Properties['DestinationFiles'] -and @($effect.DestinationFiles).Count -eq @($effect.RelativeFiles).Count) { $effect.DestinationFiles } else { $effect.RelativeFiles })
    $destinationNames = @($destinationFiles | ForEach-Object { [IO.Path]::GetFileName([string]$_) })
    for ($i = 0; $i -lt @($effect.RelativeFiles).Count; $i++) {
        $source = [string]$effect.RelativeFiles[$i]
        $relative = [string]$destinationFiles[$i]
        foreach ($candidatePath in @($source, $relative)) {
            if ($candidatePath -match '(^|/)\.\.?(/|$)' -or $candidatePath.StartsWith('/') -or $candidatePath -match '%2f|%5c|%2e|\\') { throw 'Approved effect path is unsafe.' }
        }
        # A cache name needs the sub-path only when two files of one effect share a file name.
        $cacheName = if (@($destinationNames | Where-Object { $_ -ieq $destinationNames[$i] }).Count -gt 1) { $relative } else { [IO.Path]::GetFileName($relative) }
        $role = if ([IO.Path]::GetExtension($relative) -ieq '.png') { 'EffectTexture' } else { 'EffectAsset' }
        $url = 'https://raw.githubusercontent.com/' + $effect.AllowedPathPrefix.Trim('/') + '/' + $source
        $uri = $null
        $validUri = [Uri]::TryCreate($url, [UriKind]::Absolute, [ref]$uri)
        if (-not $validUri -or $uri.Scheme -ne 'https' -or $uri.Host -notin $effect.AllowedHosts -or $uri.Query -or $uri.Fragment -or $uri.AbsolutePath -ne ('/' + $effect.AllowedPathPrefix.Trim('/') + '/' + $source) -or $uri.AbsolutePath -match '%2f|%5c|%2e' -or -not $uri.AbsolutePath.StartsWith($effect.AllowedPathPrefix, [StringComparison]::Ordinal)) { throw 'Approved effect URL failed allowlist validation.' }
        $length = if (@($effect.ByteLengths).Count -gt $i) { [int64]$effect.ByteLengths[$i] } else { $null }
        [void]$files.Add([pscustomobject]@{
            EffectId = $effect.EffectId; Role = $role; RelativePath = $relative; SourceRelativePath = $source
            CacheRelativePath = ($safeEffectCache + '/' + $cacheName); Url = $url
            SHA256 = $effect.SHA256[$i]; ByteLength = $length; PinnedRevision = $effect.PinnedCommit
            Repository = $effect.Repository; License = $effect.License; InlineBytes = $null
        })
    }
    # Upstream license text copies (each pinned by commit, SHA-256 and byte length) and the TPM-authored notice.
    foreach ($notice in @($effect.NoticeFiles)) {
        $noticeSource = [string]$notice.SourceRelativePath
        $noticeDestination = [string]$notice.DestinationRelativePath
        foreach ($candidatePath in @($noticeSource, $noticeDestination)) {
            if ($candidatePath -match '(^|/)\.\.?(/|$)' -or $candidatePath.StartsWith('/') -or $candidatePath -match '%2f|%5c|%2e|\\') { throw 'Approved effect notice path is unsafe.' }
        }
        $noticePrefix = '/{0}/{1}/' -f $notice.Repository, $notice.PinnedCommit
        $noticeUrl = 'https://raw.githubusercontent.com' + $noticePrefix + $noticeSource
        $noticeUri = $null
        if (-not [Uri]::TryCreate($noticeUrl, [UriKind]::Absolute, [ref]$noticeUri) -or $noticeUri.Scheme -ne 'https' -or $noticeUri.Host -ne 'raw.githubusercontent.com' -or $noticeUri.AbsolutePath -ne ($noticePrefix + $noticeSource) -or $noticeUri.Query -or $noticeUri.Fragment -or $noticeUri.AbsolutePath -match '%2f|%5c|%2e') { throw 'Approved effect notice URL failed allowlist validation.' }
        [void]$files.Add([pscustomobject]@{
            EffectId = $effect.EffectId; Role = 'LicenseNotice'; RelativePath = $noticeDestination; SourceRelativePath = $noticeSource
            CacheRelativePath = ($safeEffectCache + '/Notice-' + [IO.Path]::GetFileName($noticeDestination)); Url = $noticeUrl
            SHA256 = [string]$notice.SHA256; ByteLength = [int64]$notice.ByteLength; PinnedRevision = [string]$notice.PinnedCommit
            Repository = [string]$notice.Repository; License = $effect.License; InlineBytes = $null
        })
    }
    $noticeBytes = [byte[]](Get-TpmReShadeEffectNoticeBytes -Effect $effect)
    $noticeHasher = [Security.Cryptography.SHA256]::Create()
    try { $noticeHash = [BitConverter]::ToString($noticeHasher.ComputeHash($noticeBytes)).Replace('-', '') } finally { $noticeHasher.Dispose() }
    [void]$files.Add([pscustomobject]@{
        EffectId = $effect.EffectId; Role = 'LicenseNotice'; RelativePath = ('Shaders/TPM/Notices/{0}/NOTICE.txt' -f $effect.EffectId); SourceRelativePath = 'TPM-authored/NOTICE.txt'
        CacheRelativePath = ($safeEffectCache + '/NOTICE.txt'); Url = $null; SHA256 = $noticeHash; ByteLength = [int64]$noticeBytes.Length
        PinnedRevision = 'TPM'; Repository = 'TeknoParrot-Manager'; License = 'Project-authored'; InlineBytes = $noticeBytes
    })
    if (@($effect.RequiredIncludes) -contains 'ReShade.fxh') {
        $revision = 'fd0022170615ce0d8162d219bff07232fa6dd84f'
        $source = 'Shaders/ReShade.fxh'
        $pathPrefix = "/crosire/reshade-shaders/$revision/"
        $url = 'https://raw.githubusercontent.com' + $pathPrefix + $source
        $uri = $null
        if (-not [Uri]::TryCreate($url, [UriKind]::Absolute, [ref]$uri) -or $uri.Scheme -ne 'https' -or $uri.Host -ne 'raw.githubusercontent.com' -or $uri.AbsolutePath -ne ($pathPrefix + $source) -or $uri.Query -or $uri.Fragment) { throw 'Approved ReShade include URL failed allowlist validation.' }
        [void]$files.Add([pscustomobject]@{
            EffectId = $effect.EffectId; Role = 'RuntimeInclude'; RelativePath = 'Shaders/TPM/ReShade.fxh'; SourceRelativePath = $source
            CacheRelativePath = 'Shared/ReShade.fxh'; Url = $url; SHA256 = '6DABFBBAF968C3871905D2EA17F96572FF7B1CEC01310B5D0E5252B66B30174F'
            ByteLength = [int64]4250; PinnedRevision = $revision; Repository = 'crosire/reshade-shaders'
            License = 'CC0-1.0'; InlineBytes = $null
        })
    }
    if (@($effect.RequiredIncludes) -contains 'ReShadeUI.fxh') {
        $bytes = [byte[]](Get-TpmReShadeUICompatibilityBytes)
        $hasher = [Security.Cryptography.SHA256]::Create()
        try { $hash = [BitConverter]::ToString($hasher.ComputeHash($bytes)).Replace('-', '') } finally { $hasher.Dispose() }
        [void]$files.Add([pscustomobject]@{
            EffectId = $effect.EffectId; Role = 'RuntimeInclude'; RelativePath = 'Shaders/TPM/ReShadeUI.fxh'; SourceRelativePath = 'TPM-authored/ReShadeUI.fxh'
            CacheRelativePath = 'Shared/ReShadeUI.fxh'; Url = $null; SHA256 = $hash; ByteLength = [int64]$bytes.Length
            PinnedRevision = 'TPM'; Repository = 'TeknoParrot-Manager'; License = 'Project-authored'; InlineBytes = $bytes
        })
    }
    return $files.ToArray()
}

function Test-TpmReShadeApprovedEffectFile {
    param([Parameter(Mandatory)]$FileSpec, [Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $false }
    try {
        $item = Get-Item -LiteralPath $Path -ErrorAction Stop
        if ($FileSpec.PSObject.Properties['ByteLength'] -and $null -ne $FileSpec.ByteLength -and [int64]$item.Length -ne [int64]$FileSpec.ByteLength) { return $false }
        return ((Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash -ieq $FileSpec.SHA256)
    } catch { return $false }
}

function Acquire-TpmReShadeApprovedEffect {
    param([Parameter(Mandatory)][string]$EffectId, [Parameter(Mandatory)][string]$CacheRoot, [string]$StagingRoot = '')
    $specs = @(Get-TpmReShadeApprovedEffectFiles -EffectId $EffectId)
    $stage = if ($StagingRoot) { $StagingRoot } else { New-TpmStagingDirectory -Label 'ReShadeEffect' }
    if (-not (Test-Path -LiteralPath $stage -PathType Container)) { [void][IO.Directory]::CreateDirectory($stage) }
    $result = New-Object System.Collections.Generic.List[object]
    $progressStarted = Get-Date
    $progressCurrent = 0
    $progressCurrentDone = $false
    try {
        foreach ($spec in $specs) {
            $progressCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade effect acquisition' -Current $progressCurrent -Total $specs.Count -StartedAt $progressStarted
            $cacheRelative = if ($spec.CacheRelativePath) { [string]$spec.CacheRelativePath } else { ($EffectId -replace '[^A-Za-z0-9_.-]', '_') + '/' + [IO.Path]::GetFileName($spec.RelativePath) }
            if ($cacheRelative -match '(^|[\\/])\.\.?([\\/]|$)' -or [IO.Path]::IsPathRooted($cacheRelative)) { throw 'Approved effect cache path is unsafe.' }
            $cachePath = Join-Path $CacheRoot ($cacheRelative -replace '/', '\')
            $stagePath = Join-Path $stage ($spec.RelativePath -replace '/', '\')
            [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($cachePath))
            [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($stagePath))
            $source = $null
            if (Test-TpmReShadeApprovedEffectFile -FileSpec $spec -Path $cachePath) { $source = $cachePath }
            elseif ($spec.InlineBytes) {
                [IO.File]::WriteAllBytes($stagePath, [byte[]]$spec.InlineBytes)
                if (-not (Test-TpmReShadeApprovedEffectFile -FileSpec $spec -Path $stagePath)) { throw "Integrity validation failed for TPM include $($spec.RelativePath)." }
                Copy-Item -LiteralPath $stagePath -Destination $cachePath -Force -ErrorAction Stop
                $source = $stagePath
            } else {
                try {
                    Invoke-TpmDownloadWebRequest -DownloadUrl $spec.Url -TempPath $stagePath -Label 'ReShade effect asset'
                    if (-not (Test-TpmReShadeApprovedEffectFile -FileSpec $spec -Path $stagePath)) { throw "Hash or byte-length mismatch for $($spec.RelativePath)." }
                    Copy-Item -LiteralPath $stagePath -Destination $cachePath -Force -ErrorAction Stop
                    $source = $stagePath
                } catch { throw "Approved effect acquisition failed for $($spec.RelativePath): $($_.Exception.Message)" }
            }
            if ($source -ne $stagePath) { Copy-Item -LiteralPath $source -Destination $stagePath -Force -ErrorAction Stop }
            [void]$result.Add([pscustomobject]@{
                EffectId = $EffectId; Role = $spec.Role; RelativePath = $spec.RelativePath; SourceRelativePath = $spec.SourceRelativePath
                Path = $stagePath; SHA256 = $spec.SHA256; ByteLength = $spec.ByteLength; PinnedRevision = $spec.PinnedRevision
                Repository = $spec.Repository; License = $spec.License; FromCache = ($source -eq $cachePath)
            })
        }
        $progressCurrentDone = $true
    } finally {
        if ($specs.Count -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade effect acquisition' -Current $(if ($progressCurrentDone) { $progressCurrent } else { $progressCurrent - 1 }) -Total $specs.Count -StartedAt $progressStarted -Complete -Outcome $(if ($progressCurrentDone) { 'Final' } else { 'Error' }) }
    }
    return [pscustomobject]@{ EffectId = $EffectId; StagingRoot = $stage; Files = $result.ToArray() }
}

function Save-TpmReShadeOwnershipManifest {
    param([Parameter(Mandatory)]$Manifest, [Parameter(Mandatory)][string]$Path)
    $parent = [IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($Path))
    [void][IO.Directory]::CreateDirectory($parent)
    # Unique CreateNew temp + atomic replace (Write-TpmAtomicTextFile); never a predictable '.tmp' name that a
    # pre-existing file or link could redirect.
    Write-TpmAtomicTextFile -Path $Path -Text ($Manifest | ConvertTo-Json -Depth 8) -Operation 'temp-then-move final write (Save-TpmReShadeOwnershipManifest)' -Validate { param([string]$Written) $null = $Written | ConvertFrom-Json -ErrorAction Stop; $true }
}

function Read-TpmReShadeOwnershipManifest {
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $null }
    $manifest = Get-Content -LiteralPath $Path -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json
    if ($manifest.SchemaVersion -ne 1 -or -not $manifest.EffectId -or -not $manifest.Files) { throw 'Invalid ReShade ownership manifest.' }
    return $manifest
}
function Get-TpmReShadeOwnershipClassification {
    param(
        [Parameter(Mandatory)][string]$HookPath,
        [Parameter(Mandatory)][string]$TargetRoot,
        [Parameter(Mandatory)]$ProfileDefinition,
        [string]$CurrentRuntimeSHA256 = '',
        [string]$CurrentRuntimeVersion = '',
        [object]$Manifest = $null
    )
    $hookExists = Test-Path -LiteralPath $HookPath -PathType Leaf
    if (-not $hookExists -and -not $Manifest) {
        # A leftover ReShade.ini the user or an earlier install left behind is theirs: protect it like a hook, so Replace saves a copy first.
        if (Test-Path -LiteralPath (Join-Path $TargetRoot 'ReShade.ini') -PathType Leaf) {
            return [pscustomobject]@{ Status = 'UnknownUserOwnedConflict'; Detail = 'A ReShade.ini exists without a ReShade hook or verified TeknoParrot Manager ownership.' }
        }
        return [pscustomobject]@{ Status = 'NoReShadePresent'; Detail = 'No ReShade hook or ownership manifest was found.' }
    }
    if (-not $Manifest) {
        return [pscustomobject]@{ Status = 'UnknownUserOwnedConflict'; Detail = 'A ReShade hook exists without verified TeknoParrot Manager ownership.' }
    }
    $entries = @($Manifest.Files)
    if ($entries.Count -eq 0) {
        return [pscustomobject]@{ Status = 'MalformedNeedsReview'; Detail = 'Ownership metadata contains no file entries.' }
    }
    $allowedKinds = @('ReShadeDll', 'ReShadePreset', 'ApprovedEffect')
    $hasBundled = $false
    foreach ($entry in $entries) {
        $invalidEntry = [string]::IsNullOrWhiteSpace([string]$entry.DestinationPath) -or [string]::IsNullOrWhiteSpace([string]$entry.ExpectedSHA256) -or [string]$entry.ExpectedSHA256 -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$entry.Kind -notin $allowedKinds
        if ($invalidEntry) {
            return [pscustomobject]@{ Status = 'MalformedNeedsReview'; Detail = 'Ownership metadata contains an untrusted or incomplete file entry.' }
        }
        $unsafeEntryPath = (-not (Test-PathInside -child ([string]$entry.DestinationPath) -parent $TargetRoot)) -or (-not (Test-TpmNoReparsePath -Path $TargetRoot)) -or (-not (Test-TpmNoReparsePath -Path ([string]$entry.DestinationPath)))
        if ($unsafeEntryPath) {
            return [pscustomobject]@{ Status = 'MalformedNeedsReview'; Detail = 'Ownership metadata points outside a safe ReShade target folder.' }
        }
        if ($entry.TPMManaged -eq $false) { $hasBundled = $true; continue }
        if ($entry.TPMManaged -ne $true) {
            return [pscustomobject]@{ Status = 'MalformedNeedsReview'; Detail = 'Ownership metadata contains an untrusted ownership flag.' }
        }
    }
    if ($hasBundled) {
        return [pscustomobject]@{ Status = 'BundledPreinstalledProtected'; Detail = 'Ownership metadata identifies bundled or preinstalled content.' }
    }
    $runtimeEntry = @($entries | Where-Object { [string]$_.Kind -eq 'ReShadeDll' })[0]
    if (-not $runtimeEntry) {
        return [pscustomobject]@{ Status = 'MalformedNeedsReview'; Detail = 'Ownership metadata has no verified ReShade runtime entry.' }
    }
    $liveRuntimeHash = (Get-FileHash -LiteralPath $HookPath -Algorithm SHA256 -ErrorAction SilentlyContinue).Hash
    if (-not $liveRuntimeHash -or $liveRuntimeHash -ine [string]$runtimeEntry.ExpectedSHA256) {
        return [pscustomobject]@{ Status = 'TPMOwnedStaleOutdated'; Detail = 'TeknoParrot Manager-owned ReShade runtime hash differs from its recorded identity.' }
    }
    if ($CurrentRuntimeSHA256 -and [string]$runtimeEntry.ExpectedSHA256 -ine $CurrentRuntimeSHA256) {
        return [pscustomobject]@{ Status = 'TPMOwnedStaleOutdated'; Detail = ('TeknoParrot Manager runtime identity is outdated; current approved runtime hash is {0}.' -f $CurrentRuntimeSHA256) }
    }
    if ($CurrentRuntimeVersion -and $Manifest.PSObject.Properties['RuntimeVersion'] -and [string]$Manifest.RuntimeVersion -and [string]$Manifest.RuntimeVersion -ne $CurrentRuntimeVersion) {
        return [pscustomobject]@{ Status = 'TPMOwnedStaleOutdated'; Detail = ('TeknoParrot Manager runtime version {0} is outdated; current approved version is {1}.' -f $Manifest.RuntimeVersion, $CurrentRuntimeVersion) }
    }
    $manifestProfileId = ([string]$Manifest.EffectId -replace '^ReShadeProfile\.', '')
    if ([string]::IsNullOrWhiteSpace($manifestProfileId)) {
        return [pscustomobject]@{ Status = 'MalformedNeedsReview'; Detail = 'Ownership metadata has no approved profile identity.' }
    }
    if ($manifestProfileId -ine [string]$ProfileDefinition.ProfileId) {
        return [pscustomobject]@{ Status = 'TPMOwnedChangedProfile'; Detail = ('TeknoParrot Manager owns the current files under profile {0}; selected profile is {1}.' -f $manifestProfileId, $ProfileDefinition.ProfileId) }
    }
    $liveOwned = @($entries | Where-Object {
        (Test-Path -LiteralPath ([string]$_.DestinationPath) -PathType Leaf) -and
        ((Get-FileHash -LiteralPath ([string]$_.DestinationPath) -Algorithm SHA256 -ErrorAction SilentlyContinue).Hash -ieq [string]$_.ExpectedSHA256)
    })
    if ($liveOwned.Count -ne $entries.Count) {
        return [pscustomobject]@{ Status = 'TPMOwnedStaleOutdated'; Detail = 'TeknoParrot Manager ownership is recorded, but one or more managed files no longer match.' }
    }
    return [pscustomobject]@{ Status = 'TPMOwnedCurrent'; Detail = 'All recorded TeknoParrot Manager-managed files match their verified identities and profile.' }
}
function Test-TpmReShadeDeploymentVerified {
    param([Parameter(Mandatory)]$DeploymentResult)
    if (-not $DeploymentResult.Succeeded -or -not $DeploymentResult.Manifest) { return $false }
    $files = @($DeploymentResult.Manifest.Files)
    if ($files.Count -eq 0) { return $false }
    $runtimeEntry = @($files | Where-Object { [string]$_.Kind -eq 'ReShadeDll' })[0]
    if (-not $runtimeEntry -or
        -not $DeploymentResult.Manifest.PSObject.Properties['RuntimeSHA256'] -or
        [string]$DeploymentResult.Manifest.RuntimeSHA256 -ine [string]$runtimeEntry.ExpectedSHA256 -or
        -not $DeploymentResult.Manifest.PSObject.Properties['RuntimeVersion'] -or
        [string]::IsNullOrWhiteSpace([string]$DeploymentResult.Manifest.RuntimeVersion)) { return $false }
    foreach ($entry in $files) {
        if ($entry.TPMManaged -ne $true -or [string]::IsNullOrWhiteSpace([string]$entry.ExpectedSHA256) -or [string]$entry.ExpectedSHA256 -notmatch '^[0-9A-Fa-f]{64}$' -or -not (Test-Path -LiteralPath ([string]$entry.DestinationPath) -PathType Leaf)) { return $false }
        $actual = (Get-FileHash -LiteralPath ([string]$entry.DestinationPath) -Algorithm SHA256 -ErrorAction SilentlyContinue).Hash
        if (-not $actual -or $actual -ine [string]$entry.ExpectedSHA256) { return $false }
    }
    return $true
}
function Get-TpmReShadeResultActionModel {
    param([Parameter(Mandatory)]$Result)
    $protected = [int]$Result.Protected -gt 0
    $unsafe = $Result.PSObject.Properties['Unsafe'] -and [int]$Result.Unsafe -gt 0
    $missing = ([int]$Result.MissingPath -gt 0 -or [int]$Result.MissingDevice -gt 0)
    if ($protected) { return [pscustomobject]@{ Primary = 'ReShade' } }
    if ($unsafe) { return [pscustomobject]@{ Primary = 'Unsafe' } }
    if ($missing) { return [pscustomobject]@{ Primary = 'HealthCheck' } }
    return [pscustomobject]@{ Primary = 'Acknowledge' }
}

# =============================================================================
# RESULT SCREEN OF RESHADE SETUP (FIX72)
# =============================================================================
# After a ReShade run that did not change every game, the screen says in plain words what was done, what was left alone and why, and what
# the user can do. Every technical fact (reason codes, counts, the old table, per-game notes) is behind [D] Details and in the log.

# "1 game" / "3 games": the count text of every ReShade screen (the generic counter is Format-TpmCountNoun).
function Format-TpmGameCount {
    param([int]$Count)
    return (Format-TpmCountNoun -Count $Count -Singular 'game')
}

# True when the ReShade.ini in a game folder carries the header that TeknoParrot Manager itself writes into every preset it installs
# ("; TPM-managed approved ReShade profile: <id>", "; Generated by TeknoParrot Manager."). It only decides how a protected game is
# worded (the files come from an earlier version of TeknoParrot Manager); it never lets anything be replaced.
function Test-TpmReShadeOwnMarker {
    param([string]$TargetDir)
    if ([string]::IsNullOrWhiteSpace($TargetDir)) { return $false }
    try {
        $iniPath = Join-Path $TargetDir 'ReShade.ini'
        if (-not (Test-Path -LiteralPath $iniPath -PathType Leaf)) { return $false }
        if (-not (Test-TpmNoReparsePath -Path $iniPath)) { return $false }
        $reader = [System.IO.File]::OpenText($iniPath)
        try {
            for ($lineNumber = 0; $lineNumber -lt 20; $lineNumber++) {
                $line = $reader.ReadLine()
                if ($null -eq $line) { break }
                if ($line -match '^\s*;\s*(TPM-managed approved ReShade profile:|Generated by TeknoParrot Manager\.)') { return $true }
            }
        } finally {
            $reader.Dispose()
        }
    } catch {
        Write-Verbose ('ReShade marker check unavailable -- ' + $_.Exception.Message)
    }
    return $false
}

# Why a game is protected. The ownership record decides (see Get-TpmReShadeOwnershipClassification):
#   BundledPreinstalledProtected -> the record says the files came with the game or another package.
#   UnknownUserOwnedConflict     -> a ReShade DLL is in the game folder and there is no ownership record. When the ReShade.ini beside it
#                                   carries TeknoParrot Manager's own header the files were installed by an earlier version whose record
#                                   is gone; otherwise they are not ours.
#   -FileCollision               -> the record exists but a file the new files would replace is not in it.
function Get-TpmReShadeProtectedReasonCode {
    param([string]$Status = '', [string]$TargetDir = '', [switch]$FileCollision)
    if ($FileCollision) { return 'RESHADE_FILE_NOT_OWNED' }
    if ($Status -eq 'BundledPreinstalledProtected') { return 'RESHADE_PREINSTALLED' }
    if ($Status -eq 'UnknownUserOwnedConflict') {
        if (Test-TpmReShadeOwnMarker -TargetDir $TargetDir) { return 'RESHADE_EARLIER_VERSION' }
        return 'RESHADE_NOT_OWNED'
    }
    return 'RESHADE_OWNER_UNKNOWN'
}

# One plain sentence for a group of protected games with the same reason (the default view). The per-game sentence for Details comes from
# Get-TpmPlainReason.
function Get-TpmReShadeProtectedGroupText {
    param([string]$Code, [int]$Count)
    $games = Format-TpmGameCount -Count $Count
    $have = if ($Count -eq 1) { 'has' } else { 'have' }
    $their = if ($Count -eq 1) { 'its' } else { 'their' }
    switch ($Code) {
        'RESHADE_NOT_OWNED' { return ('{0} already {1} a ReShade that TeknoParrot Manager did not install.' -f $games, $have) }
        'RESHADE_EARLIER_VERSION' { return ('{0} {1} ReShade files from an earlier version of TeknoParrot Manager.' -f $games, $have) }
        'RESHADE_PREINSTALLED' { return ('{0} came with ReShade files of {1} own.' -f $games, $their) }
        'RESHADE_FILE_NOT_OWNED' { return ('{0} {1} a file in {2} folder that TeknoParrot Manager did not install.' -f $games, $have, $their) }
        default { return ('TeknoParrot Manager could not tell who installed the ReShade files in {0}.' -f $games) }
    }
}

# The one-line summary (log, Details and the failure message) of a run that did not change every game.
# The games whose profile may be damaged after a failed Turn-it-off are counted in UnverifiedItems too (so the run does not end as a success);
# FIX73 words them separately from ReShade files that could not be verified.
function Get-TpmReShadeResultSummaryText {
    param($Result)
    $nativeRestoreCount = @((Get-TpmTransactionField -Object $Result -Name 'NativeCrtNeedsRestoreItems' -Default @()) | Where-Object { $_ }).Count
    $unverifiedCount = [Math]::Max(0, (@((Get-TpmTransactionField -Object $Result -Name 'UnverifiedItems' -Default @()) | Where-Object { $_ }).Count - $nativeRestoreCount))
    $deployed = [int](Get-TpmTransactionField -Object $Result -Name 'Deployed' -Default 0)
    if ($unverifiedCount -gt 0 -or $nativeRestoreCount -gt 0) {
        $parts = New-Object System.Collections.Generic.List[string]
        if ($unverifiedCount -gt 0) { [void]$parts.Add(('ReShade files may have been written for {0} but the result could not be verified; check the FAILED lines above and the log before retrying.' -f (Format-TpmGameCount -Count $unverifiedCount))) }
        if ($nativeRestoreCount -gt 0) { [void]$parts.Add((Get-TpmReShadeNativeCrtDamagedText -Count $nativeRestoreCount)) }
        return ($parts -join ' ')
    }
    if ($deployed -gt 0) {
        $errorCount = [int](Get-TpmTransactionField -Object $Result -Name 'ErrorCount' -Default 0)
        $deviceSkips = [int](Get-TpmTransactionField -Object $Result -Name 'MissingDevice' -Default 0)
        return ('ReShade applied partially: {0} changed, {1}, {2}.' -f (Format-TpmGameCount -Count $deployed), (Format-TpmCountNoun -Count $errorCount -Singular 'error'), (Format-TpmCountNoun -Count $deviceSkips -Singular 'unavailable-device skip'))
    }
    return 'ReShade setup did not change any game files.'
}

# How the menu 5 workflow status ends when the run did not change every game. Nothing failed (no error, nothing unverified, the games were
# only left alone): the workflow finishes normally, returns $true, and no failure is raised. Otherwise the failure is raised and $false is
# returned (the caller acknowledges it).
function Set-TpmReShadeSetupWorkflowEnd {
    param([Parameter(Mandatory)]$Context, $Result, [Parameter(Mandatory)][string]$Summary)
    $errorCount = [int](Get-TpmTransactionField -Object $Result -Name 'ErrorCount' -Default 0)
    $unverifiedCount = @((Get-TpmTransactionField -Object $Result -Name 'UnverifiedItems' -Default @()) | Where-Object { $_ }).Count
    $reasonCode = [string](Get-TpmTransactionField -Object $Result -Name 'ReasonCode' -Default '')
    $nothingFailed = ($null -ne $Result -and $errorCount -eq 0 -and $unverifiedCount -eq 0 -and $reasonCode -eq 'SOME_GAMES_NOT_CHANGED')
    if (-not $nothingFailed) {
        [void](Set-TpmWorkflowFailure -Context $Context -FailureId 'reshade-incomplete' -Message $Summary -DataSafety 'TeknoParrot Manager did not claim success for every selected game; skipped and failed games were left unchanged.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
        return $false
    }
    $deployed = [int](Get-TpmTransactionField -Object $Result -Name 'Deployed' -Default 0)
    [void](Complete-TpmWorkflowStep -Context $Context -Outcome Fixed -Summary 'ReShade source verified' -NextStep 'Install into selected games')
    [void](Start-TpmWorkflowStep -Context $Context -StepId 'apply' -Activity 'Installing ReShade into selected games')
    if ($deployed -gt 0) {
        [void](Complete-TpmWorkflowStep -Context $Context -Outcome Fixed -Summary 'ReShade files installed' -NextStep 'Verify the result')
    } else {
        [void](Complete-TpmWorkflowStep -Context $Context -Outcome Skipped -Summary 'No game needed new ReShade files' -NextStep 'Verify the result')
    }
    [void](Start-TpmWorkflowStep -Context $Context -StepId 'verify' -Activity 'Verifying ReShade setup')
    [void](Complete-TpmWorkflowStep -Context $Context -Summary 'ReShade setup finished')
    [void](Complete-TpmWorkflowStatus -Context $Context -Summary 'ReShade setup finished; some games were left alone and need your choice')
    return $true
}

# The screen after a ReShade run (clean, partly done, or with errors). Default view: what was done, what was left alone and why (games with
# the same reason on ONE line, only non-zero counts), and the choice in plain words. [D] shows every fact: the old result table, one block
# per protected or unsafe game with its reason code, and the per-game notes. Returns the choice for the caller:
#   PendingApplyMode / PendingReShadeAction are set only when the user chose to run something next.
function Show-TpmReShadeSetupResult {
    param([Parameter(Mandatory)][AllowNull()]$Result)
    $missingPathCount = [int](Get-TpmTransactionField -Object $Result -Name 'MissingPath' -Default 0)
    $missingDeviceCount = [int](Get-TpmTransactionField -Object $Result -Name 'MissingDevice' -Default 0)
    $nativeRestoreCount = @((Get-TpmTransactionField -Object $Result -Name 'NativeCrtNeedsRestoreItems' -Default @()) | Where-Object { $_ }).Count
    $reShadeResult = [pscustomobject]@{
        Deployed = [int](Get-TpmTransactionField -Object $Result -Name 'Deployed' -Default 0)
        Protected = [int](Get-TpmTransactionField -Object $Result -Name 'Protected' -Default 0)
        Unsafe = [int](Get-TpmTransactionField -Object $Result -Name 'Unsafe' -Default 0)
        SourceFolder = @((Get-TpmTransactionField -Object $Result -Name 'SourceFolderItems' -Default @()) | Where-Object { $_ }).Count
        MissingPath = $missingPathCount
        MissingDevice = $missingDeviceCount
        Unsupported = [int](Get-TpmTransactionField -Object $Result -Name 'Unsupported' -Default 0)
        LinuxStyle = [int](Get-TpmTransactionField -Object $Result -Name 'LinuxStyle' -Default 0)
        KeptPrevious = [int](Get-TpmTransactionField -Object $Result -Name 'KeptPrevious' -Default 0)
        ErrorCount = [int](Get-TpmTransactionField -Object $Result -Name 'ErrorCount' -Default 0)
        UnverifiedCount = [Math]::Max(0, (@((Get-TpmTransactionField -Object $Result -Name 'UnverifiedItems' -Default @()) | Where-Object { $_ }).Count - $nativeRestoreCount))
        NativeRestoreCount = $nativeRestoreCount
    }
    $profileName = [string](Get-TpmTransactionField -Object $Result -Name 'SelectedProfileName' -Default '')
    if ([string]::IsNullOrWhiteSpace($profileName)) { $profileName = 'the new look' }
    $missingTotal = $reShadeResult.MissingPath + $reShadeResult.MissingDevice
    $notChangedTotal = $reShadeResult.Protected + $reShadeResult.Unsafe + $missingTotal + $reShadeResult.Unsupported + $reShadeResult.LinuxStyle + $reShadeResult.KeptPrevious
    $reShadeActionModel = Get-TpmReShadeResultActionModel -Result $reShadeResult
    $reShadePathIssue = $reShadeResult -and ($reShadeResult.MissingPath -gt 0 -or $reShadeResult.MissingDevice -gt 0)

    # Games with the same reason are counted together.
    $protectedRecords = @(Get-TpmTransactionField -Object $Result -Name 'ProtectedRecords' -Default @())
    $byCode = @{}
    foreach ($record in $protectedRecords) {
        $recordCode = [string](Get-TpmTransactionField -Object $record -Name 'Code' -Default 'RESHADE_OWNER_UNKNOWN')
        if (-not $byCode.ContainsKey($recordCode)) { $byCode[$recordCode] = 0 }
        $byCode[$recordCode] = [int]$byCode[$recordCode] + 1
    }
    if ($reShadeResult.Protected -gt $protectedRecords.Count) {
        $byCode['RESHADE_OWNER_UNKNOWN'] = [int]$byCode['RESHADE_OWNER_UNKNOWN'] + ($reShadeResult.Protected - $protectedRecords.Count)
    }
    $notChanged = New-Object System.Collections.Generic.List[string]
    foreach ($groupCode in @('RESHADE_NOT_OWNED', 'RESHADE_EARLIER_VERSION', 'RESHADE_PREINSTALLED', 'RESHADE_FILE_NOT_OWNED', 'RESHADE_OWNER_UNKNOWN')) {
        if ($byCode.ContainsKey($groupCode) -and [int]$byCode[$groupCode] -gt 0) {
            [void]$notChanged.Add((Get-TpmReShadeProtectedGroupText -Code $groupCode -Count ([int]$byCode[$groupCode])))
        }
    }
    $otherUnsafe = [Math]::Max(0, $reShadeResult.Unsafe - $reShadeResult.SourceFolder)
    if ($reShadeResult.SourceFolder -gt 0) { [void]$notChanged.Add(('{0} {1} inside your source folder (where your game collection is kept).' -f (Format-TpmGameCount -Count $reShadeResult.SourceFolder), $(if ($reShadeResult.SourceFolder -eq 1) { 'is' } else { 'are' }))) }
    if ($otherUnsafe -gt 0) { [void]$notChanged.Add(('{0} could not be checked safely.' -f (Format-TpmGameCount -Count $otherUnsafe))) }
    if ($missingTotal -gt 0) { [void]$notChanged.Add(('{0} could not be found. The game file is missing or its drive is not connected.' -f (Format-TpmGameCount -Count $missingTotal))) }
    if ($reShadeResult.Unsupported -gt 0) { [void]$notChanged.Add(('{0} {1} skipped. The 32-bit ReShade file was not found. Download ReShade again to get it.' -f (Format-TpmCountNoun -Count $reShadeResult.Unsupported -Singular 'game' -Modifier '32-bit'), $(if ($reShadeResult.Unsupported -eq 1) { 'was' } else { 'were' }))) }
    if ($reShadeResult.LinuxStyle -gt 0) { [void]$notChanged.Add(('{0} {1} skipped. {2} run through BudgieLoader, and ReShade is not set up for those games yet.' -f (Format-TpmCountNoun -Count $reShadeResult.LinuxStyle -Singular 'game' -Modifier 'Linux-style'), $(if ($reShadeResult.LinuxStyle -eq 1) { 'was' } else { 'were' }), $(if ($reShadeResult.LinuxStyle -eq 1) { 'It runs' } else { 'They' }))) }
    if ($reShadeResult.KeptPrevious -gt 0) { [void]$notChanged.Add(('{0} kept the look you chose before.' -f (Format-TpmGameCount -Count $reShadeResult.KeptPrevious))) }
    $leftAloneText = if ($reShadeResult.Protected -gt 0 -and $reShadeResult.Protected -eq $notChangedTotal) {
        if ($notChangedTotal -eq 1) { 'It was left alone to protect your own setup.' } else { 'They were left alone to protect your own setup.' }
    } else {
        if ($notChangedTotal -eq 1) { 'Nothing was changed in it.' } else { 'Nothing was changed in them.' }
    }

    # The facts for Details, and the log.
    $summaryText = Get-TpmReShadeResultSummaryText -Result $Result
    $blocks = New-Object System.Collections.Generic.List[object]
    [void]$blocks.Add(@{ Heading = 'What happened'; Lines = @(
        ('Summary: ' + $summaryText),
        ('Changed: {0}' -f (Format-TpmGameCount -Count $reShadeResult.Deployed)),
        ('Protected existing: {0}' -f (Format-TpmGameCount -Count $reShadeResult.Protected)),
        ('Missing paths: {0}' -f (Format-TpmGameCount -Count $missingTotal)),
        ('Failed: {0}' -f (Format-TpmGameCount -Count $reShadeResult.ErrorCount)),
        ('Unsafe/malformed: {0}' -f (Format-TpmGameCount -Count $reShadeResult.Unsafe))
    ) })
    $didLines = New-Object System.Collections.Generic.List[string]
    [void]$didLines.Add('Changed: verified ReShade deployments only.')
    [void]$didLines.Add('Not changed: protected, unsafe/malformed, unknown, or unavailable game folders.')
    if ($notChangedTotal -gt 0 -or $reShadeResult.ErrorCount -gt 0 -or $reShadeResult.UnverifiedCount -gt 0 -or $reShadeResult.NativeRestoreCount -gt 0) {
        [void]$didLines.Add('Data safety: TeknoParrot Manager did not claim success for every selected game; skipped and failed games were left unchanged.')
        [void]$didLines.Add('What to do next: review the games listed here, repair the listed issue, then run ReShade setup again.')
    }
    [void]$blocks.Add(@{ Heading = 'What TeknoParrot Manager did'; Lines = $didLines.ToArray() })
    foreach ($record in $protectedRecords) {
        $recordGame = [string](Get-TpmTransactionField -Object $record -Name 'Game' -Default '')
        $recordLabel = [string](Get-TpmTransactionField -Object $record -Name 'Label' -Default $recordGame)
        $recordCode = [string](Get-TpmTransactionField -Object $record -Name 'Code' -Default 'RESHADE_OWNER_UNKNOWN')
        $recordLines = New-Object System.Collections.Generic.List[string]
        [void]$recordLines.Add('What happened: ' + (Get-TpmPlainReason -Code $recordCode).Text)
        [void]$recordLines.Add('Reason code: ' + $recordCode)
        $recordDetail = [string](Get-TpmTransactionField -Object $record -Name 'Detail' -Default '')
        if (-not [string]::IsNullOrWhiteSpace($recordDetail)) { [void]$recordLines.Add('Technical detail: ' + $recordDetail) }
        [void]$blocks.Add(@{ Heading = $(if ($recordLabel) { $recordLabel } else { 'A protected game' }); Lines = $recordLines.ToArray(); Color = 'Yellow' })
    }
    foreach ($unsafeDetail in @(Get-TpmTransactionField -Object $Result -Name 'UnsafeDetails' -Default @())) {
        if ([string]::IsNullOrWhiteSpace([string]$unsafeDetail)) { continue }
        $unsafeMatch = [regex]::Match([string]$unsafeDetail, '^(?<game>[^:]{1,60}):\s+(?<text>.+)$')
        $unsafeHeading = if ($unsafeMatch.Success) { $unsafeMatch.Groups['game'].Value } else { 'An unsafe or damaged setup' }
        $unsafeText = if ($unsafeMatch.Success) { $unsafeMatch.Groups['text'].Value } else { [string]$unsafeDetail }
        [void]$blocks.Add(@{ Heading = $unsafeHeading; Lines = @(('What happened: ' + $unsafeText)); Color = 'Yellow' })
    }
    $techniques = [string](Get-TpmTransactionField -Object $Result -Name 'SelectedProfileTechniques' -Default '')
    if ($reShadeResult.Unsafe -gt 0 -and -not [string]::IsNullOrWhiteSpace($techniques)) {
        [void]$blocks.Add(@{ Heading = 'The look you chose'; Lines = @(('Selected profile techniques: ' + $techniques)) })
    }
    $summaryDetails = @(Get-TpmTransactionField -Object $Result -Name 'SummaryDetails' -Default @()) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }
    if (@($summaryDetails).Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Counts and notes from the run'; Lines = @($summaryDetails | ForEach-Object { [string]$_ }) }) }
    $detailNotes = @(Get-TpmTransactionField -Object $Result -Name 'DetailNotes' -Default @()) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }
    if (@($detailNotes).Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Notes for each game'; Lines = @($detailNotes | ForEach-Object { [string]$_ }) }) }
    # FIX68: the games whose change can be undone in ReShade > Undo ReShade changes, those whose undo copy could not be finished and
    # (FIX85) those a failed rollback left half changed: they are not called ready, they need a check before they are played.
    $undoReadyItems = @((Get-TpmTransactionField -Object $Result -Name 'UndoReceiptItems' -Default @()) | Where-Object { $_ })
    $undoMissingItems = @((Get-TpmTransactionField -Object $Result -Name 'UndoReceiptMissingItems' -Default @()) | Where-Object { $_ })
    $undoCheckItems = @((Get-TpmTransactionField -Object $Result -Name 'UndoReceiptCheckItems' -Default @()) | Where-Object { $_ })
    $hasUndoNote = (($undoReadyItems.Count + $undoMissingItems.Count + $undoCheckItems.Count) -gt 0)
    if ($hasUndoNote) {
        $undoLines = New-Object System.Collections.Generic.List[string]
        if ($undoReadyItems.Count -gt 0) { [void]$undoLines.Add('Saved for undo: ' + ($undoReadyItems -join ', ')) }
        if ($undoMissingItems.Count -gt 0) { [void]$undoLines.Add('Undo copy not finished: ' + ($undoMissingItems -join ', ')) }
        if ($undoCheckItems.Count -gt 0) { [void]$undoLines.Add('Check before you play (a failed rollback left it half changed): ' + ($undoCheckItems -join ', ')) }
        [void]$undoLines.Add('Where: ReShade > Undo ReShade changes')
        [void]$blocks.Add(@{ Heading = 'Undo'; Lines = $undoLines.ToArray() })
    }
    $detailsNote = if ($reShadeResult.Protected -gt 0) { 'Press A to replace protected ReShade files. TeknoParrot Manager saves a copy of the old files first, so you can undo it.' } else { '' }
    Write-Log ('ReShade result: changed={0} protected={1} unsafe={2} missing={3} unsupported={4} kept={5} failed={6} unverified={7} -- {8}' -f $reShadeResult.Deployed, $reShadeResult.Protected, $reShadeResult.Unsafe, $missingTotal, $reShadeResult.Unsupported, $reShadeResult.KeptPrevious, $reShadeResult.ErrorCount, $reShadeResult.UnverifiedCount, $summaryText)
    foreach ($block in $blocks) {
        foreach ($blockLine in @($block.Lines)) { Write-Log ('ReShade result detail [{0}]: {1}' -f $block.Heading, $blockLine) }
    }

    # The default view.
    Write-Host ''
    if ($reShadeResult.Deployed -gt 0) {
        Write-TpmText -Text ('Done: {0} applied to {1}.' -f $profileName, (Format-TpmGameCount -Count $reShadeResult.Deployed)) -Color Green -HangingIndent 6
        Write-TpmText -Text 'To turn the effect on or off, start a game and press the Home key.' -Color DarkGray
    } else {
        Write-TpmText -Text 'Nothing was changed.' -Color Yellow
    }
    if ($reShadeResult.ErrorCount -gt 0) {
        Write-TpmText -Text ('Problem: {0} could not be changed. See the FAILED lines above, or the log.' -f (Format-TpmGameCount -Count $reShadeResult.ErrorCount)) -Color Red -HangingIndent 9 -BlankBefore
    }
    if ($reShadeResult.UnverifiedCount -gt 0) {
        Write-TpmText -Text ('Problem: TeknoParrot Manager could not confirm the files in {0}. Check the log before you try again.' -f (Format-TpmGameCount -Count $reShadeResult.UnverifiedCount)) -Color Red -HangingIndent 9 -BlankBefore
    }
    if ($reShadeResult.NativeRestoreCount -gt 0) {
        Write-TpmText -Text (Get-TpmReShadeNativeCrtDamagedText -Count $reShadeResult.NativeRestoreCount) -Color Red -BlankBefore
    }
    if ($notChanged.Count -gt 0) {
        Write-Host ''
        if ($notChanged.Count -eq 1) {
            Write-TpmText -Text ('Not changed: {0} {1}' -f $notChanged[0], $leftAloneText) -Color Yellow -HangingIndent 4
        } else {
            Write-TpmText -Text 'Not changed:' -Color Yellow
            foreach ($notChangedLine in $notChanged) { Write-TpmText -Text ('- ' + $notChangedLine) -Color Yellow -Indent 4 -HangingIndent 2 }
            Write-TpmText -Text $leftAloneText -Color DarkGray
        }
    }
    if ($reShadeResult.SourceFolder -gt 0) {
        Write-TpmText -Text 'TeknoParrot Manager never changes your source folder. Move the game out of it, or fix the game folder in its profile.' -Color Yellow -BlankBefore -HangingIndent 4
    }
    if ($hasUndoNote) {
        Write-Host ''
        if ($undoCheckItems.Count -gt 0) { Write-TpmText -Text $(if ($undoCheckItems.Count -eq 1) { 'Check this game before you play it.' } else { ('Check these {0} games before you play them.' -f $undoCheckItems.Count) }) -Color Red -HangingIndent 4 }
        if ($undoReadyItems.Count -gt 0) { Write-TpmText -Text 'Next: You can undo this in ReShade > Undo ReShade changes.' -HangingIndent 6 }
        if ($undoMissingItems.Count -gt 0) { Write-TpmText -Text ('Undo copy not finished for {0}. The log has the reason.' -f (Format-TpmGameCount -Count $undoMissingItems.Count)) -Color Yellow -HangingIndent 4 }
    }

    # The choice, in plain words. Keys keep their meaning: A replaces, S chooses game by game, M shows missing games, B leaves, D shows details.
    $screen = [pscustomobject]@{ Choice = ''; PendingApplyMode = $null; PendingReShadeAction = $null }
    $primary = [string]$reShadeActionModel.Primary
    if ($primary -in @('ReShade', 'Unsafe', 'HealthCheck')) {
        $keys = switch ($primary) {
            'ReShade' { if ($reShadePathIssue) { @('A', 'S', 'M', 'B', 'D') } else { @('A', 'S', 'B', 'D') } }
            'Unsafe' { @('S', 'B', 'D') }
            default { @('M', 'B', 'D') }
        }
        $keyText = (@($keys[0..($keys.Count - 2)]) -join ', ') + ' or ' + $keys[$keys.Count - 1]
        $protectedWords = if ($reShadeResult.Protected -eq 1) { 'that game' } else { ('those {0} games' -f $reShadeResult.Protected) }
        do {
            Write-Host ''
            if ($keys -contains 'A') { Write-TpmText -Text ("[A] Replace {0} with TeknoParrot Manager's ReShade (you choose the look again; a copy of the old files is saved, so you can undo it)" -f $protectedWords) -Color White -HangingIndent 4 }
            if ($keys -contains 'S') { Write-TpmText -Text $(if ($primary -eq 'Unsafe') { '[S] Choose games one by one and try again' } else { '[S] Choose games one by one' }) -Color White -HangingIndent 4 }
            if ($keys -contains 'M') { Write-TpmText -Text '[M] Open the Library Health Check to see which games could not be found' -Color White -HangingIndent 4 }
            Write-TpmText -Text $(if ($primary -eq 'ReShade') { '[B] Leave them as they are' } else { '[B] Back to the main menu' }) -Color White -HangingIndent 4
            Write-TpmText -Text '[D] Details' -Color White -HangingIndent 4
            $choice = Read-TpmChoice -Prompt ('  Press {0}' -f $keyText) -Choices $keys -Default 'B'
            if ($choice -eq 'D') {
                Show-TpmDetailBlocks -Blocks $blocks.ToArray() -Note $detailsNote
            } elseif ($choice -eq 'M') {
                $screen.PendingApplyMode = 'HealthCheck'
                if ($primary -eq 'ReShade') { $screen.PendingReShadeAction = 'Select' }
            } elseif ($choice -eq 'S') {
                $screen.PendingApplyMode = 'ReShadeSetup'
                $screen.PendingReShadeAction = 'Select'
            } elseif ($choice -eq 'A') {
                $screen.PendingApplyMode = 'ReShadeSetup'
                $screen.PendingReShadeAction = 'Adopt'
            }
        } while ($choice -eq 'D')
        $screen.Choice = $choice
        return $screen
    }
    do {
        $answer = [string](Read-HostSafe '  Press D for details, or Enter to return to the menu')
        $showDetails = ($answer.Trim() -ieq 'D')
        if ($showDetails) { Show-TpmDetailBlocks -Blocks $blocks.ToArray() -Note $detailsNote }
    } while ($showDetails)
    return $screen
}


# Downloads (or finds in the cache) the files of one approved effect, checks every file's hash and returns where they are staged.
# It never writes into the game folder: the profile deployment copies the staged files.
function Install-TpmReShadeApprovedEffect {
    param([Parameter(Mandatory)][string]$EffectId, [Parameter(Mandatory)][string]$CacheRoot)
    $acquired = Acquire-TpmReShadeApprovedEffect -EffectId $EffectId -CacheRoot $CacheRoot
    foreach ($asset in @($acquired.Files)) {
        if (-not (Test-TpmReShadeApprovedEffectFile -FileSpec $asset -Path $asset.Path)) { throw "INTEGRITY: staged approved effect hash validation failed for $($asset.RelativePath)." }
    }
    return [pscustomobject]@{ Succeeded = $true; State = 'PREPARED'; StagingRoot = $acquired.StagingRoot; Files = @($acquired.Files) }
}

# The key of one game in the ReShade state folders: the SHA-256 of its id as lower case text. It names the ownership record of the game
# and the folder of its undo receipts, so the receipts of one game can be told from the receipts of any other game.
function Get-TpmReShadeGameKey {
    param([Parameter(Mandatory)][string]$GameId)
    $idBytes = [Text.Encoding]::UTF8.GetBytes($GameId)
    return (([BitConverter]::ToString(([Security.Cryptography.SHA256]::Create().ComputeHash($idBytes))) -replace '-', '').ToLowerInvariant())
}

function Get-TpmReShadeProfileOwnershipPath {
    param([Parameter(Mandatory)][string]$GameId, [string]$StateRoot = '')
    $paths = Get-TpmReShadeStatePath -StateRoot $StateRoot
    return (Join-Path (Join-Path $paths.Root 'Deployments') ((Get-TpmReShadeGameKey -GameId $GameId) + '.json'))
}

function Get-TpmReShadeRemovalScan {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [string]$StateRoot = '')
    $records = New-Object System.Collections.Generic.List[object]
    $profileFiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'ReShade removal profile discovery' -EnumerationErrorAction Stop | Sort-Object BaseName)
    $progressStarted = Get-Date
    $progressCurrent = 0
    $progressCurrentDone = $false
    try {
        foreach ($profileFile in $profileFiles) {
            $progressCurrent++
            if ($profileFiles.Count -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade removal scan' -Current $progressCurrent -Total $profileFiles.Count -StartedAt $progressStarted }
        $base = [ordered]@{ GameId=$profileFile.BaseName; ProfileFile=$profileFile; StateRoot=$StateRoot; Status=''; Detail=''; GamePath=''; EmulatorType=''; TargetDir=''; DllName=''; OwnershipPath=''; Manifest=$null; RemovableFiles=@(); ProtectedFiles=@(); ChangedFiles=@(); ProtectedCount=0; ChangedCount=0; Reviewable=$false }
        try {
            $doc = Read-Xml -Path $profileFile.FullName
            if (-not $doc.GameProfile) { $base.Status='MalformedMetadata'; $base.Detail='Profile has no GameProfile root.'; [void]$records.Add([pscustomobject]$base); continue }
            $gpNode = $doc.GameProfile.SelectSingleNode('GamePath')
            $gamePath = if ($gpNode) { $gpNode.InnerText.Trim() } else { '' }
            $base.GamePath = $gamePath
            $emulatorTypeNode = $doc.GameProfile.SelectSingleNode('EmulatorType')
            $base.EmulatorType = if ($emulatorTypeNode) { $emulatorTypeNode.InnerText.Trim() } else { '' }
            if ([string]::IsNullOrWhiteSpace($gamePath) -or -not (Test-Path -LiteralPath $gamePath -PathType Leaf)) {
                $base.Status='MissingPath'; $base.Detail='Saved GamePath is empty or unavailable.'; [void]$records.Add([pscustomobject]$base); continue
            }
            $exeDir = [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($gamePath))
            $targetInfo = if ($exeDir) { Get-ReShadeTargetInfo -Doc $doc -GamePath $gamePath -ExeDir $exeDir } else { $null }
            if (-not $targetInfo -or [string]::IsNullOrWhiteSpace($targetInfo.TargetDir) -or [string]::IsNullOrWhiteSpace($targetInfo.DllName) -or -not (Test-TpmNoReparsePath -Path $targetInfo.TargetDir)) {
                $base.Status='MalformedMetadata'; $base.Detail='ReShade target could not be resolved safely.'; [void]$records.Add([pscustomobject]$base); continue
            }
            $base.TargetDir = $targetInfo.TargetDir
            $base.DllName = $targetInfo.DllName
            $ownershipPath = Get-TpmReShadeProfileOwnershipPath -GameId $profileFile.BaseName -StateRoot $StateRoot
            $base.OwnershipPath = $ownershipPath
            $manifest = $null
            if (Test-Path -LiteralPath $ownershipPath -PathType Leaf) {
                try { $manifest = Read-TpmReShadeOwnershipManifest -Path $ownershipPath }
                catch { $base.Status='MalformedMetadata'; $base.Detail='ReShade ownership manifest is invalid.'; [void]$records.Add([pscustomobject]$base); continue }
            }
            $base.Manifest = $manifest
            $safe = New-Object System.Collections.Generic.List[object]
            $changed = New-Object System.Collections.Generic.List[object]
            $protectedBundled = New-Object System.Collections.Generic.List[object]
            $protectedAmbiguous = New-Object System.Collections.Generic.List[object]
            if ($manifest) {
            foreach ($entry in @($manifest.Files)) {
                $kind = if ($entry.PSObject.Properties['Kind']) { [string]$entry.Kind } else { '' }
                $path = [string]$entry.DestinationPath
                $managed = ($entry.TPMManaged -eq $true)
                $exists = -not [string]::IsNullOrWhiteSpace($path) -and (Test-Path -LiteralPath $path -PathType Leaf)
                $insideTarget = $exists -and (Test-PathInside -child $path -parent $targetInfo.TargetDir)
                if ($managed -and $kind -in @('ReShadeDll','ReShadePreset','ApprovedEffect') -and $exists -and $insideTarget) {
                    $actual = $null
                    try { $actual = (Get-FileHash -LiteralPath $path -Algorithm SHA256 -ErrorAction Stop).Hash } catch {}
                    if ($actual -and $actual -ieq [string]$entry.ExpectedSHA256 -and (Test-TpmNoReparsePath -Path $path)) {
                        [void]$safe.Add($entry)
                    } elseif ($actual) {
                        [void]$changed.Add($entry)
                    } else {
                        [void]$protectedAmbiguous.Add($entry)
                    }
                } elseif ($exists -and -not $insideTarget) {
                    [void]$protectedAmbiguous.Add($entry)
                } elseif ($exists -and -not $managed) {
                    [void]$protectedBundled.Add($entry)
                } elseif ($exists -and [string]::IsNullOrWhiteSpace($kind)) {
                    [void]$protectedAmbiguous.Add($entry)
                }
            }
            }
            $hookPath = Join-Path $targetInfo.TargetDir $targetInfo.DllName
            $trackedHook = @($safe.ToArray() + $protectedBundled.ToArray() + $protectedAmbiguous.ToArray() + $changed.ToArray() | Where-Object { $_.DestinationPath -and ([IO.Path]::GetFullPath([string]$_.DestinationPath) -ieq [IO.Path]::GetFullPath($hookPath)) })
            if ((Test-Path -LiteralPath $hookPath -PathType Leaf) -and $trackedHook.Count -eq 0) {
                [void]$protectedAmbiguous.Add([pscustomobject]@{ RelativeSource=$targetInfo.DllName; DestinationPath=$hookPath; Kind='ReShadeDll'; TPMManaged=$false; Reason='Unowned hook' })
            }
            $base.ProtectedFiles = @($protectedBundled.ToArray() + $protectedAmbiguous.ToArray())
            $base.ChangedFiles = $changed.ToArray()
            $base.ProtectedCount = @($base.ProtectedFiles).Count
            $base.ChangedCount = @($base.ChangedFiles).Count
            if ($safe.Count -gt 0) {
                $base.Status='Removable'; $base.Detail=('{0} verified TPM-managed file(s); {1} protected file(s) preserved.' -f $safe.Count, $base.ProtectedCount); $base.RemovableFiles=$safe.ToArray(); $base.Reviewable=$true
            } elseif ($protectedBundled.Count -gt 0) {
                $base.Status='ProtectedBundled'; $base.Detail=('{0} bundled or preinstalled ReShade file(s) preserved.' -f $protectedBundled.Count); $base.Reviewable=$true
            } elseif ($protectedAmbiguous.Count -gt 0) {
                $base.Status='ProtectedAmbiguous'; $base.Detail=('{0} unowned, ambiguous, or out-of-target ReShade file(s) preserved.' -f $protectedAmbiguous.Count); $base.Reviewable=$true
            } elseif ($changed.Count -gt 0) {
                $base.Status='Changed'; $base.Detail=('{0} TPM record(s) no longer match the live file.' -f $changed.Count); $base.Reviewable=$true
            } elseif (Test-Path -LiteralPath $hookPath -PathType Leaf) {
                $base.Status='ProtectedAmbiguous'; $base.Detail='Existing ReShade hook has no verified TPM ownership record.'; $base.Reviewable=$true
            } elseif ($manifest) {
                $base.Status='AlreadyClean'; $base.Detail='No removable ReShade files remain.'
            } else {
                $base.Status='AlreadyClean'; $base.Detail='No ReShade ownership or hook was detected.'
            }
            [void]$records.Add([pscustomobject]$base)
        } catch {
            $base.Status='MalformedMetadata'; $base.Detail=('ReShade metadata could not be inspected safely: ' + $_.Exception.Message + ' at ' + $_.InvocationInfo.PositionMessage); [void]$records.Add([pscustomobject]$base)
            Write-Log "ReShade removal scan skipped $($profileFile.BaseName) -- $_"
        }
    }
    $progressCurrentDone = $true
    } finally {
        if ($profileFiles.Count -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade removal scan' -Current $(if ($progressCurrentDone) { $progressCurrent } else { $progressCurrent - 1 }) -Total $profileFiles.Count -StartedAt $progressStarted -Complete -Outcome $(if ($progressCurrentDone) { 'Final' } else { 'Error' }) }
    }
    $reviewable = @($records | Where-Object Reviewable)
    return [pscustomobject]@{
        Records = $records.ToArray()
        Reviewable = $reviewable
    }
}

function Get-TpmReShadeValidatedRemovalEntry {
    param(
        [Parameter(Mandatory)]$Entry,
        [Parameter(Mandatory)][string]$ProfileRoot,
        [Parameter(Mandatory)][string]$TargetRoot
    )
    try {
        $path = [string]$Entry.DestinationPath
        $kind = [string]$Entry.Kind
        if ($Entry.TPMManaged -ne $true -or $kind -notin @('ReShadeDll','ReShadePreset','ApprovedEffect') -or [string]::IsNullOrWhiteSpace($path)) { return $null }
        $profileFull = [System.IO.Path]::GetFullPath($ProfileRoot)
        $targetFull = [System.IO.Path]::GetFullPath($TargetRoot)
        $pathFull = [System.IO.Path]::GetFullPath($path)
        if (Test-PathInside -child $pathFull -parent $profileFull) { return $null }
        if (-not (Test-PathInside -child $pathFull -parent $targetFull)) { return $null }
        if (-not (Test-Path -LiteralPath $targetFull -PathType Container) -or -not (Test-TpmNoReparsePath -Path $targetFull)) { return $null }
        if (-not (Test-Path -LiteralPath $pathFull -PathType Leaf) -or -not (Test-TpmNoReparsePath -Path $pathFull)) { return $null }
        $actual = (Get-FileHash -LiteralPath $pathFull -Algorithm SHA256 -ErrorAction Stop).Hash
        if (-not $actual -or $actual -ine [string]$Entry.ExpectedSHA256) { return $null }
        return [pscustomobject]@{ Path = $pathFull; ActualSHA256 = $actual }
    } catch {
        return $null
    }
}

function Get-TpmReShadeRemovalContext {
    param([Parameter(Mandatory)]$ProfileFile)
    try {
        $doc = Read-Xml -Path $ProfileFile.FullName
        if (-not $doc.GameProfile) { return $null }
        $gamePathNode = $doc.GameProfile.SelectSingleNode('GamePath')
        $gamePath = if ($gamePathNode) { $gamePathNode.InnerText.Trim() } else { '' }
        $emulatorTypeNode = $doc.GameProfile.SelectSingleNode('EmulatorType')
        $emulatorType = if ($emulatorTypeNode) { $emulatorTypeNode.InnerText.Trim() } else { '' }
        $exeDir = if ($gamePath) { [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($gamePath)) } else { $null }
        $targetInfo = if ($exeDir -and [System.IO.File]::Exists((ConvertTo-TpmAutoSyncLongPath -Path $gamePath))) { Get-ReShadeTargetInfo -Doc $doc -GamePath $gamePath -ExeDir $exeDir } else { $null }
        if (-not $targetInfo -or [string]::IsNullOrWhiteSpace($targetInfo.TargetDir) -or [string]::IsNullOrWhiteSpace($targetInfo.DllName)) { return $null }
        return [pscustomobject]@{ Document=$doc; GamePath=$gamePath; EmulatorType=$emulatorType; ExeDir=$exeDir; TargetInfo=$targetInfo }
    } catch {
        return $null
    }
}

function Assert-TpmReShadeRemovalContext {
    param(
        [Parameter(Mandatory)]$ScanRecord,
        [Parameter(Mandatory)]$Context,
        [Parameter(Mandatory)][string]$Phase
    )
    if (-not $Context) { throw "ReShade profile could not be re-read $Phase." }
    if ([string]$ScanRecord.GamePath) {
        if ([string]::IsNullOrWhiteSpace($Context.GamePath) -or [IO.Path]::GetFullPath($Context.GamePath) -ine [IO.Path]::GetFullPath([string]$ScanRecord.GamePath)) { throw "ReShade game path changed $Phase." }
    }
    if ($ScanRecord.PSObject.Properties['EmulatorType'] -and [string]$Context.EmulatorType -ine [string]$ScanRecord.EmulatorType) { throw "ReShade EmulatorType changed $Phase." }
    if ([string]$ScanRecord.TargetDir) {
        if ([string]::IsNullOrWhiteSpace($Context.TargetInfo.TargetDir) -or [IO.Path]::GetFullPath($Context.TargetInfo.TargetDir) -ine [IO.Path]::GetFullPath([string]$ScanRecord.TargetDir)) { throw "ReShade target directory changed $Phase." }
    }
    if ([string]$ScanRecord.DllName -and [string]$Context.TargetInfo.DllName -ine [string]$ScanRecord.DllName) { throw "ReShade hook name changed $Phase." }
}

# Deletes one ReShade file that was checked and saved: only the very file that was saved (same file identity) and only while its bytes
# are still the saved bytes. The check and the delete use the same open file, so a file that replaced it in between is never deleted.
# Returns 'Removed' or 'Absent'; throws, and leaves the file as it is, when it is not the saved file.
function Remove-TpmReShadeVerifiedFile {
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][string]$Identity, [Parameter(Mandatory)][string]$Sha256, [switch]$WasReadOnly)
    if ($WasReadOnly -and (Get-TpmFileIdentityString -Path $Path) -ceq $Identity) { Clear-TpmTreeReadOnly -Path $Path }
    return (Remove-TpmTreeOwnedFile -Path $Path -ExpectedIdentity $Identity -ExpectedSha256 $Sha256)
}

function Remove-TpmReShadeOwnedDeployment {
    param(
        [Parameter(Mandatory)]$ScanRecord,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][string]$BackupRoot,
        [string]$StateRoot = '',
        # FIX96: the configured source collection folders; a game folder inside one of them is refused before anything is saved or removed.
        [string[]]$ProtectedRoots = @(),
        [switch]$ConfirmRemoval
    )
    if (-not $ConfirmRemoval) {
        return [pscustomobject]@{ GameId=$ScanRecord.GameId; Status='ConfirmationRequired'; RemovedFiles=@(); Detail='Explicit removal confirmation was not supplied.' }
    }
    if ($ScanRecord.Status -notin @('Removable','ProtectedBundled','ProtectedAmbiguous','Changed') -or @($ScanRecord.RemovableFiles).Count -eq 0) {
        $state = if ($ScanRecord.Status -in @('ProtectedBundled','ProtectedAmbiguous')) { [string]$ScanRecord.Status } elseif ($ScanRecord.Status -eq 'Changed') { 'Changed' } else { [string]$ScanRecord.Status }
        return [pscustomobject]@{ GameId=$ScanRecord.GameId; Status=$state; RemovedFiles=@(); Detail=$ScanRecord.Detail }
    }
    $operationDir = $null
    $backups = New-Object System.Collections.Generic.List[object]
    $manifestBackup = $null
    $manifestBackupHash = $null
    $deletedBackups = New-Object System.Collections.Generic.List[object]
    $manifestMutationAttempted = $false
    $manifestConflictDetected = $false
    $deleteConflictPath = $null
    $activeProgressLabel = $null
    $activeProgressStarted = $null
    $activeProgressCurrent = 0
    $activeProgressTotal = 0
    $undo = $null
    try {
        $profileRoot = [System.IO.Path]::GetFullPath($UserProfilesDir)
        $removalContext = Get-TpmReShadeRemovalContext -ProfileFile $ScanRecord.ProfileFile
        Assert-TpmReShadeRemovalContext -ScanRecord $ScanRecord -Context $removalContext -Phase 'before removal'
        $targetInfo = $removalContext.TargetInfo
        $sourceRoot = Find-TpmProtectedSourceRoot -Path ([string]$targetInfo.TargetDir) -ProtectedRoots $ProtectedRoots
        if ($sourceRoot) {
            Write-Log ('ReShade removal: refused for {0} before any change; the game folder {1} is inside the source folder {2}.' -f $ScanRecord.GameId, $targetInfo.TargetDir, $sourceRoot)
            return [pscustomobject]@{ GameId=$ScanRecord.GameId; GameName=(Get-TpmReShadeGameLabel -ProfilePath ([string]$ScanRecord.ProfileFile.FullName) -Fallback ([string]$ScanRecord.GameId)); Status='SourceFolderRefused'; RemovedFiles=@(); BackupPath=''; Detail=('Nothing was changed, because the game folder is inside the source folder ' + $sourceRoot + '.') }
        }
        if (-not (Test-TpmNoReparsePath -Path $targetInfo.TargetDir)) { throw 'ReShade target could not be resolved safely before removal.' }
        $expectedOwnershipPath = Get-TpmReShadeProfileOwnershipPath -GameId ([string]$ScanRecord.GameId) -StateRoot $StateRoot
        if ([IO.Path]::GetFullPath([string]$ScanRecord.OwnershipPath) -ine [IO.Path]::GetFullPath($expectedOwnershipPath)) { throw 'ReShade ownership manifest path is not the expected TPM deployment path.' }
        $activeProgressLabel = 'ReShade removal validation'
        $activeProgressStarted = Get-Date
        $activeProgressCurrent = 0
        $activeProgressTotal = @($ScanRecord.RemovableFiles).Count
        foreach ($entry in @($ScanRecord.RemovableFiles)) {
            $activeProgressCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $activeProgressStarted
            $validated = Get-TpmReShadeValidatedRemovalEntry -Entry $entry -ProfileRoot $profileRoot -TargetRoot $targetInfo.TargetDir
            if (-not $validated) { throw "ReShade ownership validation rejected '$([string]$entry.DestinationPath)'." }
        }
        Write-TpmCompactExtractionProgress -Phase Checking -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $activeProgressStarted -Complete
        $activeProgressLabel = $null
        # FIX68: the undo receipt of this game is made and checked before anything is copied or removed; without it nothing is removed.
        $undoRequest = New-TpmReShadeUndoRequest -GameId ([string]$ScanRecord.GameId) -GameName (Get-TpmReShadeGameLabel -ProfilePath ([string]$ScanRecord.ProfileFile.FullName) -Fallback ([string]$ScanRecord.GameId)) -Operation 'Remove' -LookBefore ([string]$ScanRecord.Manifest.EffectId -replace '^ReShadeProfile\.', '') -LookAfter 'None' -OwnerBefore 'TeknoParrotManager' -StateRoot $StateRoot
        $undo = New-TpmReShadeUndoReceipt -Request $undoRequest -Paths @(@($ScanRecord.RemovableFiles | ForEach-Object { [string]$_.DestinationPath }) + @([string]$ScanRecord.OwnershipPath)) -Roots @([string]$targetInfo.TargetDir, [IO.Path]::GetDirectoryName([IO.Path]::GetFullPath([string]$ScanRecord.OwnershipPath)))
        if (-not $undo.Succeeded) {
            return [pscustomobject]@{ GameId=$ScanRecord.GameId; Status='ReceiptFailed'; RemovedFiles=@(); BackupPath=''; Detail=('No file was removed, because a copy for undo could not be saved: ' + $undo.Reason) }
        }

        [void][IO.Directory]::CreateDirectory($BackupRoot)
        if (-not (Test-TpmNoReparsePath -Path $BackupRoot)) { throw "ReShade backup path is unsafe: $BackupRoot" }
        $operationDir = Join-Path $BackupRoot ('ReShadeRemoval_' + (Get-Date).ToString('yyyyMMdd_HHmmss_fff', [System.Globalization.CultureInfo]::InvariantCulture) + '_' + ($ScanRecord.GameId -replace '[^A-Za-z0-9_.-]', '_'))
        [void][IO.Directory]::CreateDirectory($operationDir)
        if (-not (Test-TpmNoReparsePath -Path $operationDir)) { throw "ReShade backup operation path is unsafe." }
        $index = 0
        $activeProgressLabel = 'ReShade removal backup'
        $activeProgressStarted = Get-Date
        $activeProgressCurrent = 0
        $activeProgressTotal = @($ScanRecord.RemovableFiles).Count
        foreach ($entry in @($ScanRecord.RemovableFiles)) {
            $activeProgressCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $activeProgressStarted
            $currentContext = Get-TpmReShadeRemovalContext -ProfileFile $ScanRecord.ProfileFile
            Assert-TpmReShadeRemovalContext -ScanRecord $ScanRecord -Context $currentContext -Phase 'before backup'
            $validated = Get-TpmReShadeValidatedRemovalEntry -Entry $entry -ProfileRoot $profileRoot -TargetRoot $currentContext.TargetInfo.TargetDir
            if (-not $validated) { throw "ReShade ownership validation rejected before backup '$([string]$entry.DestinationPath)'." }
            $source = $validated.Path
            $backup = Join-Path $operationDir ('file_{0}_{1}' -f $index, [IO.Path]::GetFileName($source))
            # The identity of the file that is saved here; the delete below removes only this same file.
            $sourceIdentity = Get-TpmFileIdentityString -Path $source
            if ([string]::IsNullOrWhiteSpace($sourceIdentity)) { throw "ReShade file identity could not be read before backup for '$source'." }
            $sourceWasReadOnly = (([int][IO.File]::GetAttributes($source) -band 1) -ne 0)
            Copy-Item -LiteralPath $source -Destination $backup -Force -ErrorAction Stop
            $sourceHash = (Get-FileHash -LiteralPath $source -Algorithm SHA256 -ErrorAction Stop).Hash
            $backupHash = (Get-FileHash -LiteralPath $backup -Algorithm SHA256 -ErrorAction Stop).Hash
            if ($sourceHash -ine $backupHash -or $backupHash -ine [string]$entry.ExpectedSHA256) { throw "ReShade backup verification failed for '$source'." }
            [void]$backups.Add([pscustomobject]@{ Source=$source; Backup=$backup; Entry=$entry; Identity=$sourceIdentity; WasReadOnly=$sourceWasReadOnly })
            $index++
        }
        Write-TpmCompactExtractionProgress -Phase Checking -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $activeProgressStarted -Complete
        $activeProgressLabel = $null


        $manifestPath = [string]$ScanRecord.OwnershipPath
        if ($manifestPath -and (Test-Path -LiteralPath $manifestPath -PathType Leaf -ErrorAction Stop)) {
            $manifestBackup = Join-Path $operationDir 'ownership.json'
            Copy-Item -LiteralPath $manifestPath -Destination $manifestBackup -Force -ErrorAction Stop
            $manifestSourceHash = (Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256 -ErrorAction Stop).Hash
            $manifestBackupHash = (Get-FileHash -LiteralPath $manifestBackup -Algorithm SHA256 -ErrorAction Stop).Hash
            if ($manifestSourceHash -ine $manifestBackupHash) { throw 'ReShade ownership manifest backup verification failed.' }
        }
        $activeProgressLabel = 'ReShade removal'
        $activeProgressStarted = Get-Date
        $activeProgressCurrent = 0
        $activeProgressTotal = $backups.Count
        foreach ($backup in $backups.ToArray()) {
            $activeProgressCurrent++
            Write-TpmCompactExtractionProgress -Phase Repairing -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $activeProgressStarted
            $deleteContext = Get-TpmReShadeRemovalContext -ProfileFile $ScanRecord.ProfileFile
            Assert-TpmReShadeRemovalContext -ScanRecord $ScanRecord -Context $deleteContext -Phase 'immediately before deletion'
            $validated = Get-TpmReShadeValidatedRemovalEntry -Entry $backup.Entry -ProfileRoot $profileRoot -TargetRoot $deleteContext.TargetInfo.TargetDir
            if (-not $validated -or $validated.Path -ine $backup.Source -or $validated.ActualSHA256 -ine [string]$backup.Entry.ExpectedSHA256) {
                $deleteConflictPath = [string]$backup.Source
                throw "ReShade removal conflict: ownership/content could not be revalidated before deletion; entry left untouched: '$($backup.Source)'."
            }
            try {
                $removeOutcome = Remove-TpmReShadeVerifiedFile -Path $validated.Path -Identity ([string]$backup.Identity) -Sha256 ([string]$backup.Entry.ExpectedSHA256) -WasReadOnly:([bool]$backup.WasReadOnly)
            } catch {
                if ($_.Exception.Message -like '*held open*') {
                    Write-Log ("ReShade removal: '{0}' is in use ({1}); it was left untouched." -f $backup.Source, $_.Exception.Message)
                    throw "ReShade file is in use. Close the game and any program using it, then try again: '$($backup.Source)'."
                }
                $deleteConflictPath = [string]$backup.Source
                Write-Log ("ReShade removal: '{0}' is not the file that was saved ({1}); it was left untouched." -f $backup.Source, $_.Exception.Message)
                throw "ReShade removal conflict: the file is not the one that was checked and saved, so it was left untouched: '$($backup.Source)'."
            }
            if ($removeOutcome -ne 'Removed') { throw "ReShade file was already gone before it could be removed: '$($backup.Source)'." }
            [void]$deletedBackups.Add($backup)
        }
        Write-TpmCompactExtractionProgress -Phase Repairing -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $activeProgressStarted -Complete
        $activeProgressLabel = $null
        $manifest = $ScanRecord.Manifest
        if ($manifestPath -and $manifest) {
            $remaining = @($manifest.Files | Where-Object { $remove = $_; -not (@($ScanRecord.RemovableFiles) | Where-Object { $_.DestinationPath -eq $remove.DestinationPath -and $_.ExpectedSHA256 -eq $remove.ExpectedSHA256 -and $_.Kind -eq $remove.Kind }) })
            if (-not $manifestBackup -or [string]::IsNullOrWhiteSpace([string]$manifestBackupHash)) {
                $manifestConflictDetected = $true
                throw 'TeknoParrot Manager cannot update removal metadata without a verified ownership-manifest backup.'
            }
            try {
                $manifestCurrentHash = (Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256 -ErrorAction Stop).Hash
            } catch {
                $manifestConflictDetected = $true
                throw 'TeknoParrot Manager cannot verify ownership-manifest state before removal metadata update.'
            }
            if ($manifestCurrentHash -ine $manifestBackupHash) {
                $manifestConflictDetected = $true
                throw 'TeknoParrot Manager found a changed ownership manifest; it was left untouched.'
            }
            $manifestMutationAttempted = $true
            # A manifest with no ReShade runtime entry left is "malformed" to every later setup; the user-edited files it still listed stay on disk, unclaimed.
            if (@($remaining | Where-Object { [string]$_.Kind -eq 'ReShadeDll' }).Count -gt 0) {
                Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=$manifest.SchemaVersion; EffectId=$manifest.EffectId; PinnedRevision=$manifest.PinnedRevision; Files=$remaining }) -Path $manifestPath
            } else {
                Remove-Item -LiteralPath $manifestPath -Force -ErrorAction Stop
            }
        }
        $undoState = Complete-TpmReShadeUndoReceipt -Undo $undo
        return [pscustomobject]@{ GameId=$ScanRecord.GameId; Status='Removed'; RemovedFiles=@($backups | ForEach-Object Source); BackupPath=$operationDir; Detail=('{0} verified TPM-managed file(s) removed.' -f $backups.Count); UndoReady=($undoState -ceq 'Ready'); UndoMissing=($undoState -ceq 'Missing') }
    } catch {
        if ($activeProgressLabel -and $activeProgressStarted) { Write-TpmCompactExtractionProgress -Phase Checking -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $activeProgressStarted -Complete -Outcome Error; $activeProgressLabel = $null }
        $rollbackErrors = New-Object System.Collections.Generic.List[string]
        $conflicts = New-Object System.Collections.Generic.List[string]
        if ($deleteConflictPath) {
            [void]$conflicts.Add($deleteConflictPath)
            [void]$rollbackErrors.Add("Undeleted entry could not be revalidated and was left untouched: $deleteConflictPath")
        }
        $activeProgressLabel = 'ReShade removal rollback'
        $activeProgressStarted = Get-Date
        $activeProgressCurrent = 0
        $activeProgressTotal = $deletedBackups.Count
        foreach ($backup in $deletedBackups.ToArray()) {
            $activeProgressCurrent++
            Write-TpmCompactExtractionProgress -Phase Repairing -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $activeProgressStarted
            try {
                try {
                    Assert-TpmNoReparseWriteTarget -Path $backup.Source -Operation 'ReShade removal rollback inspection'
                    $destinationExists = Test-Path -LiteralPath $backup.Source -PathType Leaf -ErrorAction Stop
                } catch {
                    [void]$conflicts.Add([string]$backup.Source)
                    throw "TeknoParrot Manager could not inspect the rollback destination; it was left untouched: $($_.Exception.Message)"
                }
                if ($destinationExists) {
                    try {
                        $destinationHash = (Get-FileHash -LiteralPath $backup.Source -Algorithm SHA256 -ErrorAction Stop).Hash
                    } catch {
                        [void]$conflicts.Add([string]$backup.Source)
                        throw "TeknoParrot Manager could not verify the reappeared rollback destination; it was left untouched: $($_.Exception.Message)"
                    }
                    if ($destinationHash -ieq [string]$backup.Entry.ExpectedSHA256) { continue }
                    [void]$conflicts.Add([string]$backup.Source)
                    throw 'TeknoParrot Manager found changed content at a rollback destination; it was left in place.'
                }
                try {
                    Assert-TpmNoReparseWriteTarget -Path $backup.Source -Operation 'ReShade removal rollback parent creation'
                    [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($backup.Source))
                } catch {
                    [void]$conflicts.Add([string]$backup.Source)
                    throw "TeknoParrot Manager could not prepare the rollback destination; manual recovery is required: $($_.Exception.Message)"
                }
                try {
                    $verifiedBackupHash = (Get-FileHash -LiteralPath $backup.Backup -Algorithm SHA256 -ErrorAction Stop).Hash
                } catch {
                    [void]$conflicts.Add([string]$backup.Source)
                    throw "TeknoParrot Manager could not verify the preserved backup; automatic restoration stopped: $($_.Exception.Message)"
                }
                if ($verifiedBackupHash -ine [string]$backup.Entry.ExpectedSHA256) {
                    [void]$conflicts.Add([string]$backup.Source)
                    throw 'TeknoParrot Manager could not verify the preserved backup; automatic restoration stopped.'
                }
                $sourceStream = $null
                $destinationStream = $null
                try {
                    try {
                        $sourceStream = [IO.File]::OpenRead($backup.Backup)
                    } catch {
                        [void]$conflicts.Add([string]$backup.Source)
                        throw "TeknoParrot Manager could not open the verified backup for restoration: $($_.Exception.Message)"
                    }
                    try {
                        Assert-TpmNoReparseWriteTarget -Path $backup.Source -Operation 'ReShade removal rollback exclusive restore'
                        $destinationStream = [IO.File]::Open([string]$backup.Source, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
                    } catch {
                        [void]$conflicts.Add([string]$backup.Source)
                        throw "TeknoParrot Manager could not exclusively create the rollback destination; existing content was not overwritten: $($_.Exception.Message)"
                    }
                    try {
                        $sourceStream.CopyTo($destinationStream)
                        $destinationStream.Flush()
                    } catch {
                        [void]$conflicts.Add([string]$backup.Source)
                        throw "TeknoParrot Manager could not complete rollback restoration; the partial destination was left in place and the backup retained: $($_.Exception.Message)"
                    }
                } finally {
                    $streamCloseError = $null
                    if ($destinationStream) {
                        try { $destinationStream.Dispose() } catch { $streamCloseError = $_.Exception.Message }
                    }
                    if ($sourceStream) {
                        try {
                            $sourceStream.Dispose()
                        } catch {
                            if (-not $streamCloseError) { $streamCloseError = $_.Exception.Message }
                        }
                    }
                    if ($streamCloseError) {
                        [void]$conflicts.Add([string]$backup.Source)
                        throw "TeknoParrot Manager could not close rollback streams safely: $streamCloseError"
                    }
                }
                try {
                    $restoredHash = (Get-FileHash -LiteralPath $backup.Source -Algorithm SHA256 -ErrorAction Stop).Hash
                } catch {
                    [void]$conflicts.Add([string]$backup.Source)
                    throw 'TeknoParrot Manager could not verify the restored file; the destination was left in place and the backup retained.'
                }
                if ($restoredHash -ine [string]$backup.Entry.ExpectedSHA256) {
                    [void]$conflicts.Add([string]$backup.Source)
                    throw 'TeknoParrot Manager restored content did not match the verified backup; the destination was left in place.'
                }
            } catch { [void]$rollbackErrors.Add("$($backup.Source): $($_.Exception.Message)") }
        }
        if ($activeProgressTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase Repairing -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $activeProgressStarted -Complete -Outcome Error }
        $activeProgressLabel = $null
        if ($manifestConflictDetected -and $ScanRecord.OwnershipPath) {
            [void]$conflicts.Add([string]$ScanRecord.OwnershipPath)
            [void]$rollbackErrors.Add('ownership manifest changed or could not be verified before update; left untouched')
        }
        if ($manifestMutationAttempted -and $manifestBackup -and $ScanRecord.OwnershipPath) {
            try {
                if (-not (Test-Path -LiteralPath $ScanRecord.OwnershipPath -PathType Leaf -ErrorAction Stop)) {
                    throw 'ownership manifest is missing after the update attempt; backup retained and no automatic overwrite attempted'
                }
                $currentManifestHash = (Get-FileHash -LiteralPath $ScanRecord.OwnershipPath -Algorithm SHA256 -ErrorAction Stop).Hash
                if ($currentManifestHash -ine $manifestBackupHash) {
                    throw 'ownership manifest differs from its verified pre-operation state; left untouched and backup retained'
                }
            } catch {
                [void]$conflicts.Add([string]$ScanRecord.OwnershipPath)
                [void]$rollbackErrors.Add("ownership manifest: $($_.Exception.Message)")
            }
        }
        $state = if ($conflicts.Count -eq 0 -and $rollbackErrors.Count -eq 0) { 'RolledBack' } else { 'ManualRecoveryRequired' }
        # FIX68: a verified rollback left the game as it was, so its receipt holds nothing to undo. Any other outcome keeps the receipt.
        if ($state -eq 'RolledBack' -and $null -ne $undo -and $undo.Succeeded) { [void](Remove-TpmReShadeUndoReceiptFolder -Folder ([string]$undo.Folder)) }
        $detail = if ($conflicts.Count -gt 0) { "TeknoParrot Manager stopped ReShade removal. $($_.Exception.Message) Manual recovery is required: unresolved file/manifest state was not overwritten; the operation backup directory remains at $operationDir. Verify backup contents before using them. Recovery details: $($rollbackErrors -join '; ')" } else { "TeknoParrot Manager ReShade removal could not complete: $($_.Exception.Message)" }
        return [pscustomobject]@{ GameId=$ScanRecord.GameId; Status=$state; RemovedFiles=@(); BackupPath=$operationDir; Detail=$detail; RollbackError=($rollbackErrors -join '; ') }
    }
}
function Invoke-TpmReShadeRemoval {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [string]$StateRoot = '',
        [string]$BackupRoot = '',
        [string[]]$ProtectedRoots = @()
    )
    if ([string]::IsNullOrWhiteSpace($BackupRoot)) { $BackupRoot = Join-Path $UserProfilesDir 'FullBackup' }
    try {
        $scan = Get-TpmReShadeRemovalScan -UserProfilesDir $UserProfilesDir -StateRoot $StateRoot
    } catch {
        Write-Host ('  ReShade removal discovery failed; no files were changed: {0}' -f $_.Exception.Message) -ForegroundColor Red
        Write-Log ('ReShade removal: discovery failed; no files changed: {0}' -f $_.Exception.Message)
        return [pscustomobject]@{ Succeeded=$false; Cancelled=$false; Scan=$null; Results=@(); Reason='DISCOVERY_FAILED' }
    }
    foreach ($record in @($scan.Records)) {
        Write-Log ('ReShade removal scan: {0} -- {1} -- {2}' -f $record.GameId, $record.Status, $record.Detail)
        foreach ($entry in @($record.RemovableFiles)) { Write-Log ('ReShade removal preview REMOVE: {0} -- {1} -- {2}' -f $record.GameId, $entry.Kind, $entry.DestinationPath) }
        foreach ($entry in @($record.ProtectedFiles)) { Write-Log ('ReShade removal preview KEEP protected: {0} -- {1} -- {2}' -f $record.GameId, $entry.Kind, $entry.DestinationPath) }
        foreach ($entry in @($record.ChangedFiles)) { Write-Log ('ReShade removal preview KEEP changed: {0} -- {1} -- {2}' -f $record.GameId, $entry.Kind, $entry.DestinationPath) }
    }
    $statusLabels = [ordered]@{
        Removable = 'verified TPM-owned files'
        ProtectedBundled = 'bundled/preinstalled files protected'
        ProtectedAmbiguous = 'unowned/ambiguous files protected'
        Changed = 'changed TPM-owned files protected'
        MissingPath = 'missing saved path'
        MalformedMetadata = 'malformed metadata'
        AlreadyClean = 'already clean'
    }
    foreach ($label in $statusLabels.Keys) {
        $count = @($scan.Records | Where-Object Status -eq $label).Count
        if ($count -gt 0) { Write-Host ('    {0}: {1}' -f $statusLabels[$label], $count) -ForegroundColor DarkGray }
    }
    $reviewable = @($scan.Reviewable)
    if ($reviewable.Count -eq 0) {
        if (@($scan.Records | Where-Object { $_.Status -in @('MissingPath','MalformedMetadata') }).Count -gt 0) {
            Write-Host '  No ReShade files could be removed, but some games could not be checked. Fix their game path or profile, then run this again.' -ForegroundColor Yellow
        } else {
            Write-Host '  No ReShade games need review or safe removal.' -ForegroundColor Green
        }
        return [pscustomobject]@{ Succeeded=$true; Cancelled=$false; NoOp=$true; Scan=$scan; Results=@() }
    }
    Write-Host ''
    Write-Host '  The next chooser contains only games with removable or protected ReShade findings.' -ForegroundColor White
    Write-Host '  Protected bundled, preinstalled, changed, and ambiguous files will be preserved.' -ForegroundColor Yellow
    $selectedFiles = @(Select-RegisteredGamesInteractive -UserProfilesDir $UserProfilesDir -Profiles @($reviewable | ForEach-Object { $_.ProfileFile }))
    if ($selectedFiles.Count -eq 0) {
        Write-Host '  ReShade removal canceled. No files were changed.' -ForegroundColor Yellow
        Write-Log 'ReShade removal: canceled in game chooser; no files changed.'
        return [pscustomobject]@{ Succeeded=$true; Cancelled=$true; Scan=$scan; Results=@() }
    }
    $selected = New-Object System.Collections.Generic.List[object]
    foreach ($file in $selectedFiles) {
        $match = @($reviewable | Where-Object { $_.ProfileFile.FullName -ieq $file.FullName })[0]
        if ($match) { [void]$selected.Add($match) }
    }
    Write-Host ''
    Write-Host '  ReShade removal preview -- no changes have been made:' -ForegroundColor Cyan
    foreach ($record in $selected.ToArray()) {
        # The removal itself refuses a game inside the source folder, so the preview must say the game is left alone.
        $previewSourceRoot = Find-TpmProtectedSourceRoot -Path ([string]$record.TargetDir) -ProtectedRoots $ProtectedRoots
        if ($previewSourceRoot) {
            Write-Host ('    KEEP   {0}: the game is inside your source folder -- nothing will be changed' -f $record.GameId) -ForegroundColor Yellow
            Write-Log ('ReShade removal preview KEEP source folder: {0} -- {1}' -f $record.GameId, $previewSourceRoot)
            continue
        }
        if (@($record.RemovableFiles).Count -gt 0) {
            foreach ($entry in @($record.RemovableFiles)) {
                $name = if ($entry.RelativeSource) { [string]$entry.RelativeSource } else { [IO.Path]::GetFileName([string]$entry.DestinationPath) }
                Write-Host ('    REMOVE {0}: {1} [{2}]' -f $record.GameId, $name, $entry.Kind) -ForegroundColor White
            }
        }
        foreach ($entry in @($record.ProtectedFiles)) {
            $name = if ($entry.RelativeSource) { [string]$entry.RelativeSource } else { [IO.Path]::GetFileName([string]$entry.DestinationPath) }
            Write-Host ('    KEEP   {0}: {1} [{2}] -- protected' -f $record.GameId, $name, $entry.Kind) -ForegroundColor Yellow
        }
        foreach ($entry in @($record.ChangedFiles)) {
            $name = if ($entry.RelativeSource) { [string]$entry.RelativeSource } else { [IO.Path]::GetFileName([string]$entry.DestinationPath) }
            Write-Host ('    KEEP   {0}: {1} [{2}] -- changed hash' -f $record.GameId, $name, $entry.Kind) -ForegroundColor Yellow
        }
        if (@($record.RemovableFiles).Count -eq 0 -and @($record.ProtectedFiles).Count -eq 0 -and @($record.ChangedFiles).Count -eq 0) {
            Write-Host ('    KEEP   {0}: {1}' -f $record.GameId, $record.Detail) -ForegroundColor Yellow
        }
    }
    Write-Host ''
    $confirm = (Read-HostSafe '  Type REMOVE to back up and remove verified TeknoParrot Manager-owned files, or press Enter to cancel').Trim().ToUpperInvariant()
    if ($confirm -ne 'REMOVE') {
        Write-Host '  ReShade removal canceled. No files were changed.' -ForegroundColor Yellow
        Write-Log 'ReShade removal: confirmation declined; no files changed.'
        return [pscustomobject]@{ Succeeded=$true; Cancelled=$true; Scan=$scan; Results=@() }
    }
    $results = New-Object System.Collections.Generic.List[object]
    foreach ($record in $selected.ToArray()) {
        [void]$results.Add((Remove-TpmReShadeOwnedDeployment -ScanRecord $record -UserProfilesDir $UserProfilesDir -BackupRoot $BackupRoot -StateRoot $StateRoot -ProtectedRoots $ProtectedRoots -ConfirmRemoval))
    }
    $removed = @($results | Where-Object Status -eq 'Removed').Count
    $receiptFailed = @($results | Where-Object Status -eq 'ReceiptFailed').Count
    $sourceRefused = @($results | Where-Object Status -eq 'SourceFolderRefused')
    $undoReady = @($results | Where-Object { $_.Status -eq 'Removed' -and [bool](Get-TpmTransactionField -Object $_ -Name 'UndoReady' -Default $false) }).Count
    $undoMissing = @($results | Where-Object { $_.Status -eq 'Removed' -and [bool](Get-TpmTransactionField -Object $_ -Name 'UndoMissing' -Default $false) }).Count
    $rolledBack = @($results | Where-Object Status -eq 'RolledBack').Count
    $failed = @($results | Where-Object { $_.Status -eq 'ManualRecoveryRequired' }).Count
    $alreadyClean = @($scan.Records | Where-Object Status -eq 'AlreadyClean').Count
    $missing = @($scan.Records | Where-Object Status -eq 'MissingPath').Count
    $bundled = @($scan.Records | Where-Object Status -eq 'ProtectedBundled').Count
    $ambiguous = @($scan.Records | Where-Object Status -eq 'ProtectedAmbiguous').Count
    $changed = @($scan.Records | Where-Object Status -eq 'Changed').Count
    $malformed = @($scan.Records | Where-Object Status -eq 'MalformedMetadata').Count
    Write-Host ''
    Write-Host ('  Removed effects from             : {0} game(s)' -f $removed) -ForegroundColor Green
    Write-Host ('  Already clean                    : {0} game(s)' -f $alreadyClean) -ForegroundColor DarkGray
    Write-Host ('  Skipped missing path             : {0} game(s)' -f $missing) -ForegroundColor Yellow
    Write-Host ('  Protected bundled/preinstalled   : {0} game(s)' -f $bundled) -ForegroundColor Yellow
    Write-Host ('  Protected ambiguous/needs review: {0} game(s)' -f $ambiguous) -ForegroundColor Yellow
    Write-Host ('  Protected changed hash           : {0} game(s)' -f $changed) -ForegroundColor Yellow
    Write-Host ('  Malformed metadata               : {0} game(s)' -f $malformed) -ForegroundColor Yellow
    Write-Host ('  Rolled back safely               : {0} game(s)' -f $rolledBack) -ForegroundColor $(if ($rolledBack -gt 0) { 'Yellow' } else { 'DarkGray' })
    Write-Host ('  Failed                           : {0} game(s)' -f $failed) -ForegroundColor $(if ($failed -gt 0) { 'Red' } else { 'DarkGray' })
    if ($receiptFailed -gt 0) { Write-TpmText -Text ('{0} not changed, because a copy for undo could not be saved.' -f (Format-TpmGameCount -Count $receiptFailed)) -Color Yellow -BlankBefore -HangingIndent 4 }
    if ($sourceRefused.Count -gt 0) {
        $refusedNames = @($sourceRefused | ForEach-Object { [string]$_.GameName })
        Write-TpmText -Text ('Not removed: {0} {1} inside your source folder. Nothing was changed in {2}.' -f ($refusedNames -join ', '), $(if ($refusedNames.Count -eq 1) { 'is' } else { 'are' }), $(if ($refusedNames.Count -eq 1) { 'it' } else { 'them' })) -Color Yellow -BlankBefore -HangingIndent 4
        Write-TpmText -Text 'TeknoParrot Manager never changes your source folder. Move the game out of it, or fix the game folder in its profile.' -Color Yellow -HangingIndent 4
    }
    if ($undoReady -gt 0) { Write-TpmText -Text 'Next: You can undo this in ReShade > Undo ReShade changes.' -BlankBefore -HangingIndent 6 }
    if ($undoMissing -gt 0) { Write-TpmText -Text ('The files were removed for {0}, but the copy that lets you undo it could not be finished. The removed files are kept in the FullBackup folder inside UserProfiles. The log has the reason.' -f (Format-TpmGameCount -Count $undoMissing)) -Color Yellow -BlankBefore -HangingIndent 4 }
    foreach ($result in $results.ToArray()) {
        Write-Log ('ReShade removal result: {0} -- {1} -- {2}' -f $result.GameId, $result.Status, $result.Detail)
        if ($result.Status -eq 'ManualRecoveryRequired') {
            Write-Host ('  TeknoParrot Manager: manual recovery required for {0}. {1}' -f $result.GameId, $result.Detail) -ForegroundColor Red
        }
    }
    Write-Log ('ReShade removal summary: Removed={0} AlreadyClean={1} MissingPath={2} ProtectedBundled={3} ProtectedAmbiguous={4} Changed={5} MalformedMetadata={6} RolledBack={7} Failed={8} ReceiptFailed={9} UndoReady={10} UndoMissing={11} SourceFolderRefused={12}' -f $removed, $alreadyClean, $missing, $bundled, $ambiguous, $changed, $malformed, $rolledBack, $failed, $receiptFailed, $undoReady, $undoMissing, $sourceRefused.Count)
    return [pscustomobject]@{ Succeeded=($failed -eq 0 -and $rolledBack -eq 0 -and $receiptFailed -eq 0 -and $undoMissing -eq 0 -and $sourceRefused.Count -eq 0); Cancelled=$false; Scan=$scan; Results=$results.ToArray(); Removed=$removed; AlreadyClean=$alreadyClean; MissingPath=$missing; ProtectedBundled=$bundled; ProtectedAmbiguous=$ambiguous; Changed=$changed; MalformedMetadata=$malformed; RolledBack=$rolledBack; Failed=$failed; ReceiptFailed=$receiptFailed; UndoMissing=$undoMissing; SourceFolderRefused=$sourceRefused.Count }
}

# =============================================================================
# RESHADE UNDO RECEIPTS (FIX68)
# =============================================================================
# Every ReShade change TeknoParrot Manager makes to a game (install, switch the look, update, adopt/replace a ReShade it did not install,
# reapply, remove, and TeknoParrot's own CRT look turned off in the same run) gets ONE undo receipt for that game. It is made and checked
# BEFORE the first write; when that fails the game is not changed. A receipt is the folder
#   <ReShade state root>\UndoReceipts\<game key>\<UTC time>_<id>\   (payload\<n>.bin and receipt.json, schema TPM.ReShadeUndoReceipt.v1)
# with a byte copy and the SHA-256 of every file the change may replace or remove, the look and the owner before, the folders the change
# may touch (Roots: the game's own folder, the folder of its ownership record, the folder of a game profile) and, once the change is
# done (State Applied), the SHA-256 of every file as TeknoParrot Manager left it. Undo puts the copies back through the verified file
# transaction (Invoke-TpmTransactionalFileBatch, every operation with its root), and only while a file is still exactly as TeknoParrot
# Manager left it: a file that changed since is never overwritten (the others can be put back on their own, after a typed YES). A receipt
# is trusted only when it belongs to the game of its folder, every file lies inside its recorded Roots and no link is on a path
# (Get-TpmReShadeUndoReceiptProblem). The game key is the SHA-256 of the game id (Get-TpmReShadeGameKey). The newest 5 receipts of a
# game are kept; older ones are removed, except when one of them holds a ReShade TeknoParrot Manager did not install: then the whole
# chain is kept. An unfinished receipt older than the newest finished one is removed too (same exception).

function Get-TpmReShadeUndoRoot {
    param([string]$StateRoot = '')
    return (Join-Path (Get-TpmReShadeStatePath -StateRoot $StateRoot).Root 'UndoReceipts')
}

function Get-TpmReShadeUndoGameFolder {
    param([Parameter(Mandatory)][string]$GameId, [string]$StateRoot = '')
    return (Join-Path (Get-TpmReShadeUndoRoot -StateRoot $StateRoot) (Get-TpmReShadeGameKey -GameId $GameId))
}

# Receipt times are kept as yyyyMMddTHHmmssfffZ (UTC): plain text that every PowerShell version reads back unchanged and that sorts by time.
function Get-TpmReShadeUndoTimeText {
    param([datetime]$Time = (Get-Date))
    return $Time.ToUniversalTime().ToString("yyyyMMdd'T'HHmmssfff'Z'", [Globalization.CultureInfo]::InvariantCulture)
}

function ConvertFrom-TpmReShadeUndoTimeText {
    param([string]$Text = '')
    $parsed = [datetime]::MinValue
    $styles = [Globalization.DateTimeStyles]::AssumeUniversal -bor [Globalization.DateTimeStyles]::AdjustToUniversal
    if ([datetime]::TryParseExact($Text, "yyyyMMdd'T'HHmmssfff'Z'", [Globalization.CultureInfo]::InvariantCulture, $styles, [ref]$parsed)) { return $parsed.ToLocalTime() }
    return $null
}

# What one change is: the game, the look before and after (a ReShade profile id, 'None' for no ReShade, 'Other' for a ReShade that
# TeknoParrot Manager did not install) and who owned the ReShade files before. ExtraPaths are files besides the game's ReShade files
# that the same change may write (the game profile, when TeknoParrot's own CRT look is turned off in the same run).
function New-TpmReShadeUndoRequest {
    param(
        [Parameter(Mandatory)][string]$GameId,
        [string]$GameName = '',
        [Parameter(Mandatory)][ValidateSet('Install', 'Switch', 'Update', 'Adopt', 'Remove')][string]$Operation,
        [string]$LookBefore = 'None',
        [string]$LookAfter = 'None',
        [ValidateSet('None', 'TeknoParrotManager', 'Other')][string]$OwnerBefore = 'None',
        [string[]]$ExtraPaths = @(),
        [string]$StateRoot = ''
    )
    return [pscustomobject]@{
        GameId = $GameId
        GameName = $(if ([string]::IsNullOrWhiteSpace($GameName)) { $GameId } else { $GameName })
        Operation = $Operation
        LookBefore = $LookBefore
        LookAfter = $LookAfter
        OwnerBefore = $OwnerBefore
        ExtraPaths = @($ExtraPaths | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
        StateRoot = $StateRoot
    }
}

# The undo request of one ReShade setup change, from the ownership check that decided the change (Get-TpmReShadeOwnershipClassification)
# and the game's ownership record before the change.
function Get-TpmReShadeSetupUndoRequest {
    param([Parameter(Mandatory)][string]$GameId, [string]$GameName = '', [string]$Status = '', $Manifest = $null, [Parameter(Mandatory)][string]$ProfileId, [string[]]$ExtraPaths = @())
    $owner = 'None'
    if ($Status -in @('UnknownUserOwnedConflict', 'BundledPreinstalledProtected')) { $owner = 'Other' }
    elseif ($null -ne $Manifest) { $owner = 'TeknoParrotManager' }
    $lookBefore = 'None'
    if ($owner -eq 'Other') { $lookBefore = 'Other' }
    elseif ($owner -eq 'TeknoParrotManager') { $lookBefore = ([string]$Manifest.EffectId -replace '^ReShadeProfile\.', '') }
    $operation = if ($owner -eq 'Other') { 'Adopt' } elseif ($owner -eq 'None') { 'Install' } elseif ($lookBefore -cne $ProfileId) { 'Switch' } else { 'Update' }
    return (New-TpmReShadeUndoRequest -GameId $GameId -GameName $GameName -Operation $operation -LookBefore $lookBefore -LookAfter $ProfileId -OwnerBefore $owner -ExtraPaths $ExtraPaths)
}

# Writes receipt.json with the atomic writer; the written text must read back as the same receipt.
function Save-TpmReShadeUndoReceipt {
    param([Parameter(Mandatory)][string]$Folder, [Parameter(Mandatory)]$Receipt)
    $expectedId = [string]$Receipt.ReceiptId
    $expectedState = [string]$Receipt.State
    $expectedCount = @($Receipt.Files).Count
    $readsBack = {
        param([string]$Written)
        $back = $Written | ConvertFrom-Json -ErrorAction Stop
        return ([string]$back.Schema -ceq 'TPM.ReShadeUndoReceipt.v1' -and [string]$back.ReceiptId -ceq $expectedId -and [string]$back.State -ceq $expectedState -and @($back.Files).Count -eq $expectedCount)
    }.GetNewClosure()
    Write-TpmAtomicTextFile -Path (Join-Path $Folder 'receipt.json') -Text ($Receipt | ConvertTo-Json -Depth 6) -Operation 'ReShade undo receipt write' -Validate $readsBack
}

# The folder of $Roots that holds $Path, or '' when none does.
function Get-TpmReShadeUndoFileRoot {
    param([Parameter(Mandatory)][string]$Path, [string[]]$Roots = @())
    foreach ($root in @($Roots)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$root) -and (Test-PathInside -child $Path -parent ([string]$root))) { return [string]$root }
    }
    return ''
}

# Why a receipt must not be trusted, or '' when it can be. It must belong to the game whose folder it lies in (SHA-256 of the game id =
# the name of the game folder), record real folders (complete paths, not a whole drive, no link on the way) and list only files inside
# those folders with no link on any path. Never throws.
function Get-TpmReShadeUndoReceiptProblem {
    param([Parameter(Mandatory)]$Receipt, [Parameter(Mandatory)][string]$Folder)
    try {
        $gameKey = [IO.Path]::GetFileName([IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($Folder)))
        if ((Get-TpmReShadeGameKey -GameId ([string]$Receipt.GameId)) -ine $gameKey) { return 'the receipt belongs to another game' }
        $roots = @(@($Receipt.Roots) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
        if ($roots.Count -eq 0) { return 'the receipt records no folder for the game' }
        foreach ($root in $roots) {
            if (-not [IO.Path]::IsPathRooted($root)) { return ('a recorded folder is not a complete path: ' + $root) }
            $fullRoot = [IO.Path]::GetFullPath($root)
            if ($fullRoot.TrimEnd('\', '/') -ieq [IO.Path]::GetPathRoot($fullRoot).TrimEnd('\', '/')) { return ('a recorded folder is a whole drive: ' + $root) }
            if (-not (Test-TpmNoReparsePath -Path $fullRoot)) { return ('a recorded folder is a link or uses an unsafe path: ' + $root) }
        }
        foreach ($file in @($Receipt.Files)) {
            $filePath = [string]$file.Path
            if (-not [IO.Path]::IsPathRooted($filePath)) { return ('a file path is not complete: ' + $filePath) }
            if ((Get-TpmReShadeUndoFileRoot -Path $filePath -Roots $roots) -ceq '') { return ('a file is outside the folders the receipt recorded: ' + $filePath) }
            if (-not (Test-TpmNoReparsePath -Path $filePath)) { return ('a file path is a link or crosses one: ' + $filePath) }
        }
        return ''
    } catch {
        return ('the receipt could not be checked: ' + [string]$_.Exception.Message)
    }
}

# Reads one receipt folder. Valid when receipt.json is a receipt of this schema, names a game, lists its files, passes
# Get-TpmReShadeUndoReceiptProblem and every saved copy lies inside the folder; with -VerifyPayload every saved copy must also still have
# the SHA-256 it was saved with. A receipt that is not valid is only reported, never changed or removed. Never throws.
function Read-TpmReShadeUndoReceipt {
    param([Parameter(Mandatory)][string]$Folder, [switch]$VerifyPayload)
    $invalid = { param([string]$Why) [pscustomobject]@{ Valid = $false; Folder = $Folder; Receipt = $null; Reason = $Why } }
    try {
        $path = Join-Path $Folder 'receipt.json'
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return (& $invalid 'receipt.json is missing') }
        $text = [IO.File]::ReadAllText($path)
        if ([string]::IsNullOrWhiteSpace($text)) { return (& $invalid 'receipt.json is empty') }
        $receipt = $text | ConvertFrom-Json -ErrorAction Stop
        if ($receipt -isnot [pscustomobject]) { return (& $invalid 'receipt.json is not a receipt') }
        if ([string]$receipt.Schema -cne 'TPM.ReShadeUndoReceipt.v1' -or [string]::IsNullOrWhiteSpace([string]$receipt.GameId) -or [string]$receipt.State -cnotin @('Prepared', 'Applied')) { return (& $invalid 'the receipt has an unknown format') }
        $files = @($receipt.Files)
        if ($files.Count -eq 0) { return (& $invalid 'the receipt lists no files') }
        $problem = Get-TpmReShadeUndoReceiptProblem -Receipt $receipt -Folder $Folder
        if ($problem) { return (& $invalid $problem) }
        foreach ($file in $files) {
            if (-not [bool]$file.BeforeExists) { continue }
            $copy = Join-Path $Folder ([string]$file.Payload)
            if ([string]::IsNullOrWhiteSpace([string]$file.Payload) -or -not (Test-PathInside $copy $Folder)) { return (& $invalid ('a saved copy is outside the receipt: ' + [string]$file.Path)) }
            if (-not $VerifyPayload) { continue }
            $copyState = Get-TpmFileState -Path $copy
            if (-not $copyState.Exists -or [string]$copyState.Sha256 -ine [string]$file.BeforeSha256) { return (& $invalid ('a saved copy is missing or changed: ' + [string]$file.Path)) }
        }
        return [pscustomobject]@{ Valid = $true; Folder = $Folder; Receipt = $receipt; Reason = '' }
    } catch {
        return (& $invalid ([string]$_.Exception.Message))
    }
}

# Deletes one receipt folder, and only a receipt folder (<...>\UndoReceipts\<game key>\<UTC time>_<id>) with no link on its path or
# inside it. Returns $true when it is gone. Never throws.
function Remove-TpmReShadeUndoReceiptFolder {
    param([Parameter(Mandatory)][string]$Folder)
    try {
        $full = [IO.Path]::GetFullPath($Folder)
        $gameFolder = [IO.Path]::GetDirectoryName($full)
        if ([IO.Path]::GetFileName($full) -notmatch '^\d{8}T\d{9}Z_[0-9a-f]{8}$' -or [IO.Path]::GetFileName([IO.Path]::GetDirectoryName($gameFolder)) -cne 'UndoReceipts') { throw 'it is not an undo receipt folder' }
        if (-not (Test-Path -LiteralPath $full -PathType Container)) { return $true }
        if (-not (Test-TpmNoReparsePath -Path $full)) { throw 'the folder is a link or uses an unsafe path' }
        $links = @(Get-ChildItem -LiteralPath $full -Recurse -Force -ErrorAction Stop | Where-Object { ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0 })
        if ($links.Count -gt 0) { throw 'the folder contains a link' }
        Remove-Item -LiteralPath $full -Recurse -Force -ErrorAction Stop
        return $true
    } catch {
        Write-Log ('ReShade undo receipt folder was kept at {0}: {1}' -f $Folder, $_.Exception.Message)
        return $false
    }
}

# Makes and checks the receipt of one change before anything is written: a byte copy of every listed file that exists (checked against
# the file's SHA-256 and length), then receipt.json (State Prepared), read back with every copy checked again. Roots are the folders the
# change may touch (the game's folder and the folder of its ownership record); the folder of every extra path of the request (the game
# profile) is added. A file outside those folders, or behind a link, fails the receipt. Returns @{ Succeeded; Folder; Receipt; Reason }.
# Never throws; on failure only the folder it created is removed.
function New-TpmReShadeUndoReceipt {
    param([Parameter(Mandatory)]$Request, [string[]]$Paths = @(), [string[]]$Roots = @())
    $folder = $null
    try {
        $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
        $targets = New-Object System.Collections.Generic.List[string]
        foreach ($path in @(@($Paths) + @($Request.ExtraPaths))) {
            if ([string]::IsNullOrWhiteSpace([string]$path)) { continue }
            $fullPath = [IO.Path]::GetFullPath([string]$path)
            if ($seen.Add($fullPath)) { [void]$targets.Add($fullPath) }
        }
        if ($targets.Count -eq 0) { throw 'the change lists no files' }
        $rootList = New-Object System.Collections.Generic.List[string]
        foreach ($root in @(@($Roots) + @($Request.ExtraPaths | ForEach-Object { [IO.Path]::GetDirectoryName([IO.Path]::GetFullPath([string]$_)) }))) {
            if (-not [string]::IsNullOrWhiteSpace([string]$root)) { [void]$rootList.Add([IO.Path]::GetFullPath([string]$root)) }
        }
        if ($rootList.Count -eq 0) { throw 'the change names no folder for the game' }
        $gameFolder = Get-TpmReShadeUndoGameFolder -GameId ([string]$Request.GameId) -StateRoot ([string]$Request.StateRoot)
        Assert-TpmNoReparseWriteTarget -Path $gameFolder -Operation 'ReShade undo receipt folder'
        [void][IO.Directory]::CreateDirectory($gameFolder)
        $receiptId = [guid]::NewGuid().ToString('N')
        $created = Get-TpmReShadeUndoTimeText
        $folder = Join-Path $gameFolder ('{0}_{1}' -f $created, $receiptId.Substring(0, 8))
        [void][IO.Directory]::CreateDirectory((Join-Path $folder 'payload'))
        if (-not (Test-TpmNoReparsePath -Path (Join-Path $folder 'payload'))) { throw 'the receipt folder is a link or uses an unsafe path' }
        $files = New-Object System.Collections.Generic.List[object]
        foreach ($target in $targets) {
            if ((Get-TpmReShadeUndoFileRoot -Path $target -Roots $rootList.ToArray()) -ceq '') { throw "a file of the change is outside the folders of the game: $target" }
            if (-not (Test-TpmNoReparsePath -Path $target)) { throw "a file of the change is a link or uses an unsafe path: $target" }
            $before = Get-TpmFileState -Path $target
            if (-not $before.Readable) { throw "a file of the change could not be read: $target ($($before.Error))" }
            if ([bool]$before.Exists -and [bool]$before.IsDirectory) { throw "a folder is where a file of the change belongs: $target" }
            $payload = ''
            if ([bool]$before.Exists) {
                $payload = 'payload\{0}.bin' -f $files.Count
                $copy = Join-Path $folder $payload
                [IO.File]::Copy($target, $copy, $false)
                $copyState = Get-TpmFileState -Path $copy
                if (-not $copyState.Exists -or [string]$copyState.Sha256 -ine [string]$before.Sha256 -or [int64]$copyState.Length -ne [int64]$before.Length) { throw "the saved copy does not match the file: $target" }
            }
            [void]$files.Add([pscustomobject]@{
                Path = $target; BeforeExists = [bool]$before.Exists; BeforeSha256 = [string]$before.Sha256; BeforeLength = $(if ($before.Exists) { [int64]$before.Length } else { $null })
                Payload = $payload; AfterExists = $null; AfterSha256 = ''; AfterLength = $null
            })
        }
        $receipt = [pscustomobject]@{
            Schema = 'TPM.ReShadeUndoReceipt.v1'; ReceiptId = $receiptId; State = 'Prepared'
            GameId = [string]$Request.GameId; GameName = [string]$Request.GameName; Operation = [string]$Request.Operation
            LookBefore = [string]$Request.LookBefore; LookAfter = [string]$Request.LookAfter; OwnerBefore = [string]$Request.OwnerBefore
            HoldsOriginal = ([string]$Request.OwnerBefore -eq 'Other'); NeedsCheck = $false; CreatedUtc = $created; CompletedUtc = ''; NativeShader = $null
            Roots = $rootList.ToArray()
            Files = $files.ToArray()
        }
        Save-TpmReShadeUndoReceipt -Folder $folder -Receipt $receipt
        $check = Read-TpmReShadeUndoReceipt -Folder $folder -VerifyPayload
        if (-not $check.Valid) { throw ('the receipt did not pass its check: ' + $check.Reason) }
        Write-Log ('ReShade undo receipt made for {0} before the change ({1}, {2} file(s)): {3}' -f $Request.GameId, $Request.Operation, $files.Count, $folder)
        return [pscustomobject]@{ Succeeded = $true; Folder = $folder; Receipt = $check.Receipt; Reason = '' }
    } catch {
        $reason = [string]$_.Exception.Message
        Write-Log ('ReShade undo receipt for {0} could not be made, so the game is not changed: {1}' -f $Request.GameId, $reason)
        if ($folder -and (Test-Path -LiteralPath $folder -PathType Container)) { [void](Remove-TpmReShadeUndoReceiptFolder -Folder $folder) }
        return [pscustomobject]@{ Succeeded = $false; Folder = ''; Receipt = $null; Reason = $reason }
    }
}

# After the change: records every file as TeknoParrot Manager left it (and the CRT setting it turned off, when there is one), marks the
# receipt Applied and keeps the newest receipts of the game (Limit-TpmReShadeUndoReceipts). A change that left every file as it was has
# nothing to undo: its receipt is removed. -Mixed is for a game that a failed rollback left half changed: its receipt is still finished
# (it holds the only copy of the files as they were), but the game must be checked before it is played. Returns 'Ready' (Undo can use it),
# 'Check' (finished, but the game needs a check first), 'Missing' (a receipt was made but could not be finished; it stays on disk and the
# reason is logged) or 'None' (no receipt was made, or there was nothing to undo).
function Complete-TpmReShadeUndoReceipt {
    param($Undo = $null, $NativeShader = $null, [switch]$Mixed)
    if ($null -eq $Undo -or -not [bool]$Undo.Succeeded -or $null -eq $Undo.Receipt) { return 'None' }
    $receipt = $Undo.Receipt
    try {
        $anyChange = $false
        foreach ($file in @($receipt.Files)) {
            $after = Get-TpmFileState -Path ([string]$file.Path)
            if (-not $after.Readable -or [bool]$after.IsDirectory) { throw "a file could not be read after the change: $($file.Path)" }
            $file.AfterExists = [bool]$after.Exists
            $file.AfterSha256 = [string]$after.Sha256
            $file.AfterLength = if ($after.Exists) { [int64]$after.Length } else { $null }
            if ([bool]$after.Exists -ne [bool]$file.BeforeExists -or ([bool]$after.Exists -and [string]$after.Sha256 -ine [string]$file.BeforeSha256)) { $anyChange = $true }
        }
        if (-not $anyChange -and $null -eq $NativeShader -and -not $Mixed) {
            [void](Remove-TpmReShadeUndoReceiptFolder -Folder ([string]$Undo.Folder))
            Write-Log ('ReShade undo receipt for {0} removed: the change left every file as it was, so there is nothing to undo.' -f $receipt.GameId)
            return 'None'
        }
        if ($null -ne $NativeShader) { $receipt.NativeShader = [pscustomobject]@{ Field = [string]$NativeShader.Field; Before = [string]$NativeShader.OldValue; After = [string]$NativeShader.NewValue } }
        $receipt.NeedsCheck = [bool]$Mixed
        $receipt.State = 'Applied'
        $receipt.CompletedUtc = Get-TpmReShadeUndoTimeText
        Save-TpmReShadeUndoReceipt -Folder ([string]$Undo.Folder) -Receipt $receipt
    } catch {
        Write-Log ('ReShade undo receipt for {0} could not be finished; it was kept at {1}: {2}' -f $receipt.GameId, $Undo.Folder, $_.Exception.Message)
        return 'Missing'
    }
    Write-Log ('ReShade undo receipt ready for {0}: {1}' -f $receipt.GameId, $Undo.Folder)
    if ($Mixed) { Write-Log ('ReShade undo receipt for {0} records the files as a failed rollback left them (half changed). The game must be checked before it is played.' -f $receipt.GameId) }
    foreach ($file in @($receipt.Files)) {
        Write-Log ('ReShade undo receipt file: {0} before={1} after={2}' -f $file.Path, $(if ($file.BeforeExists) { $file.BeforeSha256 } else { 'absent' }), $(if ($file.AfterExists) { $file.AfterSha256 } else { 'absent' }))
    }
    $gameFolder = [IO.Path]::GetDirectoryName([string]$Undo.Folder)
    Remove-TpmReShadeUnfinishedUndoReceipts -GameFolder $gameFolder
    Limit-TpmReShadeUndoReceipts -GameFolder $gameFolder
    return $(if ($Mixed) { 'Check' } else { 'Ready' })
}

# Finishes the undo receipt of one game (Complete-TpmReShadeUndoReceipt) and files the game, in the lists of one setup run, under the
# word that returned: Ready, Check, Missing or None. Returns that word.
function Add-TpmReShadeUndoGameResult {
    param([Parameter(Mandatory)][hashtable]$Groups, [Parameter(Mandatory)][string]$Game, $Undo = $null, $NativeShader = $null, [switch]$Mixed)
    $state = Complete-TpmReShadeUndoReceipt -Undo $Undo -NativeShader $NativeShader -Mixed:$Mixed
    [void]$Groups[$state].Add($Game)
    return $state
}

# Every receipt folder of one game, newest first (a folder name starts with its UTC time). With -StopAtNewestApplied the folders are read
# one by one and the reading stops after the first valid finished receipt (the menu needs no more, and every read checks every file path).
function Get-TpmReShadeUndoReceipts {
    param([Parameter(Mandatory)][string]$GameFolder, [switch]$StopAtNewestApplied)
    if (-not (Test-Path -LiteralPath $GameFolder -PathType Container)) { return @() }
    $folders = @(Get-ChildItem -LiteralPath $GameFolder -Directory -Force -ErrorAction Stop | Where-Object { $_.Name -match '^\d{8}T\d{9}Z_[0-9a-f]{8}$' } | Sort-Object Name -Descending)
    $reads = New-Object System.Collections.Generic.List[object]
    foreach ($folder in $folders) {
        $read = Read-TpmReShadeUndoReceipt -Folder $folder.FullName
        [void]$reads.Add($read)
        if ($StopAtNewestApplied -and $read.Valid -and [string]$read.Receipt.State -ceq 'Applied') { break }
    }
    return $reads.ToArray()
}

# Keeps the newest $Keep finished receipts of one game and removes the older ones. When an older one holds a ReShade TeknoParrot Manager
# did not install (HoldsOriginal), nothing is removed: undo goes newest first, so the whole chain down to that receipt is needed to put
# the original files back. Unfinished or unreadable receipts are never touched here.
function Limit-TpmReShadeUndoReceipts {
    param([Parameter(Mandatory)][string]$GameFolder, [int]$Keep = 5)
    try {
        $applied = @(Get-TpmReShadeUndoReceipts -GameFolder $GameFolder | Where-Object { $_.Valid -and [string]$_.Receipt.State -ceq 'Applied' })
        if ($applied.Count -le $Keep) { return }
        $older = @($applied | Select-Object -Skip $Keep)
        if (@($older | Where-Object { [bool]$_.Receipt.HoldsOriginal }).Count -gt 0) {
            Write-Log ('ReShade undo receipts in {0}: {1} kept, because an older one holds the files TeknoParrot Manager did not install.' -f $GameFolder, $applied.Count)
            return
        }
        foreach ($entry in $older) {
            if (Remove-TpmReShadeUndoReceiptFolder -Folder ([string]$entry.Folder)) { Write-Log ('ReShade undo receipt removed (more than {0} for this game): {1}' -f $Keep, $entry.Folder) }
        }
    } catch {
        Write-Log ('ReShade undo receipts in {0} were not limited: {1}' -f $GameFolder, $_.Exception.Message)
    }
}

# Removes the unfinished (Prepared) receipts of one game that are older than its newest finished one: a change that began before a
# finished change and never finished has nothing left to undo. One that holds a ReShade TeknoParrot Manager did not install is kept,
# because its saved copies may be the only copy of those files. A receipt that cannot be read is never touched.
function Remove-TpmReShadeUnfinishedUndoReceipts {
    param([Parameter(Mandatory)][string]$GameFolder)
    try {
        $valid = @(Get-TpmReShadeUndoReceipts -GameFolder $GameFolder | Where-Object { $_.Valid })
        $newest = @($valid | Where-Object { [string]$_.Receipt.State -ceq 'Applied' } | Select-Object -First 1)
        if ($newest.Count -eq 0) { return }
        $newestName = [IO.Path]::GetFileName([string]$newest[0].Folder)
        foreach ($entry in @($valid | Where-Object { [string]$_.Receipt.State -ceq 'Prepared' })) {
            if ([string]::CompareOrdinal([IO.Path]::GetFileName([string]$entry.Folder), $newestName) -ge 0) { continue }
            if ([bool]$entry.Receipt.HoldsOriginal) {
                Write-Log ('ReShade unfinished undo receipt kept, because it holds the files TeknoParrot Manager did not install: {0}' -f $entry.Folder)
                continue
            }
            if (Remove-TpmReShadeUndoReceiptFolder -Folder ([string]$entry.Folder)) { Write-Log ('ReShade unfinished undo receipt removed (a newer change was finished): {0}' -f $entry.Folder) }
        }
    } catch {
        Write-Log ('ReShade unfinished undo receipts in {0} were not cleaned up: {1}' -f $GameFolder, $_.Exception.Message)
    }
}

# The newest finished receipt of every game, newest first: the rows of the Undo menu.
function Get-TpmReShadeUndoEntries {
    param([string]$StateRoot = '')
    $root = Get-TpmReShadeUndoRoot -StateRoot $StateRoot
    if (-not (Test-Path -LiteralPath $root -PathType Container)) { return @() }
    $entries = New-Object System.Collections.Generic.List[object]
    foreach ($gameFolder in @(Get-ChildItem -LiteralPath $root -Directory -Force -ErrorAction SilentlyContinue)) {
        try {
            $newest = @(Get-TpmReShadeUndoReceipts -GameFolder $gameFolder.FullName -StopAtNewestApplied | Where-Object { $_.Valid -and [string]$_.Receipt.State -ceq 'Applied' } | Select-Object -First 1)
        } catch {
            Write-Log ('ReShade undo receipts in {0} could not be read: {1}' -f $gameFolder.FullName, $_.Exception.Message)
            continue
        }
        if ($newest.Count -eq 0) { continue }
        $receipt = $newest[0].Receipt
        [void]$entries.Add([pscustomobject]@{
            GameId = [string]$receipt.GameId; GameName = $(if ([string]::IsNullOrWhiteSpace([string]$receipt.GameName)) { [string]$receipt.GameId } else { [string]$receipt.GameName })
            LookBefore = [string]$receipt.LookBefore; LookAfter = [string]$receipt.LookAfter; OwnerBefore = [string]$receipt.OwnerBefore
            When = (ConvertFrom-TpmReShadeUndoTimeText -Text ([string]$receipt.CompletedUtc)); SortKey = [string]$receipt.CompletedUtc
            Folder = [string]$newest[0].Folder; Receipt = $receipt
        })
    }
    return @($entries.ToArray() | Sort-Object SortKey -Descending)
}

# The plain name of a look in a receipt: the look's own name, "no ReShade", or "its own ReShade" (a ReShade TeknoParrot Manager did not install).
function Get-TpmReShadeLookName {
    param([string]$LookId = '')
    if ([string]::IsNullOrWhiteSpace($LookId) -or $LookId -ceq 'None') { return 'no ReShade' }
    if ($LookId -ceq 'Other') { return 'its own ReShade' }
    $lookProfile = Get-TpmReShadeProfile -ProfileId $LookId
    if ($lookProfile) { return [string]$lookProfile.FriendlyName }
    $retired = Get-TpmReShadeRetiredProfile -ProfileId $LookId
    if ($retired) { return [string]$retired.FriendlyName }
    return $LookId
}

# What kind of file a receipt lists, in the words a user knows: a ReShade settings file (.ini), a game profile (.xml) or other ReShade files.
function Get-TpmReShadeUndoFileKind {
    param([Parameter(Mandatory)][string]$Path)
    switch ([IO.Path]::GetExtension($Path).ToLowerInvariant()) {
        '.ini' { return 'ReShade settings file' }
        '.xml' { return 'game profile' }
        default { return 'ReShade files' }
    }
}

# Compares every file of a receipt with the disk now. A file is as it was before the change (nothing to do), exactly as TeknoParrot
# Manager left it (ToRestore), or Changed (anything else, also unreadable; with its kind and the state found, to check it again later).
# Undo of the whole game is possible only when nothing is Changed; the files in ToRestore can also be put back on their own.
function Get-TpmReShadeUndoCheck {
    param([Parameter(Mandatory)]$Receipt)
    $toRestore = New-Object System.Collections.Generic.List[object]
    $changed = New-Object System.Collections.Generic.List[object]
    foreach ($file in @($Receipt.Files)) {
        $now = Get-TpmFileState -Path ([string]$file.Path)
        $before = [pscustomobject]@{ Readable = $true; Exists = [bool]$file.BeforeExists; IsDirectory = $false; Length = $file.BeforeLength; Sha256 = [string]$file.BeforeSha256 }
        if (Test-TpmFileStateMatch -Expected $before -Actual $now -IgnoreMetadata) { continue }
        $left = [pscustomobject]@{ Readable = $true; Exists = [bool]$file.AfterExists; IsDirectory = $false; Length = $file.AfterLength; Sha256 = [string]$file.AfterSha256 }
        if (Test-TpmFileStateMatch -Expected $left -Actual $now -IgnoreMetadata) { [void]$toRestore.Add($file); continue }
        [void]$changed.Add([pscustomobject]@{ Path = [string]$file.Path; Kind = (Get-TpmReShadeUndoFileKind -Path ([string]$file.Path)); State = $now })
    }
    return [pscustomobject]@{ CanUndo = ($changed.Count -eq 0); NothingToDo = ($changed.Count -eq 0 -and $toRestore.Count -eq 0); ToRestore = $toRestore.ToArray(); Changed = $changed.ToArray() }
}

# The file transaction that puts the "before" bytes back: REPLACE a file TeknoParrot Manager changed, ADD a file it removed, REMOVE a
# file it added. Each operation names the hash the file must still have, so the transaction itself refuses a file changed meanwhile, and the
# folder of the receipt that holds the file (RootPath), so it also refuses a path that leaves that folder. A file outside every root throws.
function Get-TpmReShadeUndoOperations {
    param([Parameter(Mandatory)][string]$Folder, [object[]]$Files = @(), [string[]]$Roots = @())
    $operations = New-Object System.Collections.Generic.List[object]
    foreach ($file in @($Files)) {
        $root = Get-TpmReShadeUndoFileRoot -Path ([string]$file.Path) -Roots $Roots
        if ($root -ceq '') { throw ('a file is outside the folders the receipt recorded: ' + [string]$file.Path) }
        $kind = if (-not [bool]$file.BeforeExists) { 'REMOVE' } elseif ([bool]$file.AfterExists) { 'REPLACE' } else { 'ADD' }
        $operation = [pscustomobject]@{
            ItemId = ('file{0}' -f $operations.Count); Operation = $kind; DestinationPath = [string]$file.Path; RootPath = $root
            SourcePath = $(if ([bool]$file.BeforeExists) { Join-Path $Folder ([string]$file.Payload) } else { $null })
            ExpectedSourceHash = [string]$file.BeforeSha256
        }
        if ([bool]$file.AfterExists) { $operation | Add-Member -NotePropertyName ExpectedDestinationHash -NotePropertyValue ([string]$file.AfterSha256) }
        [void]$operations.Add($operation)
    }
    return $operations.ToArray()
}

# Runs the verified file transaction that puts the given files back and says how it ended: @{ Status; Code; Detail } (Status Undone,
# RolledBack, NotChanged or NeedsAttention, Code is the plain reason code).
function Invoke-TpmReShadeUndoBatch {
    param([Parameter(Mandatory)][string]$Folder, [object[]]$Files = @(), [string[]]$Roots = @())
    $batch = Invoke-TpmTransactionalFileBatch -WorkflowKey 'ReShade' -OperationKey 'UndoChanges' -Operations @(Get-TpmReShadeUndoOperations -Folder $Folder -Files $Files -Roots $Roots) -ReasonCode 'RESHADE_UNDO_FAILED'
    $outcome = [string]$batch.Outcome
    $underlying = [string](Get-TpmTransactionField -Object $batch -Name 'UnderlyingOutcome' -Default '')
    if ($outcome -eq 'CLEANUP_RESIDUE' -and $underlying) { $outcome = $underlying }
    $errorText = @(@($batch.Errors) + @(Get-TpmTransactionField -Object $batch.Rollback -Name 'Errors' -Default @()) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }) -join '; '
    $detail = $errorText -replace '\bTPM\b', 'TeknoParrot Manager'
    switch ($outcome) {
        'SUCCEEDED' { return [pscustomobject]@{ Status = 'Undone'; Code = 'UNDO_DONE'; Detail = $detail } }
        'ROLLED_BACK_VERIFIED' { return [pscustomobject]@{ Status = 'RolledBack'; Code = 'UNDO_ROLLED_BACK'; Detail = $detail } }
        'FAILED_BEFORE_MUTATION' { return [pscustomobject]@{ Status = 'NotChanged'; Code = 'UNDO_STOPPED_BEFORE_CHANGE'; Detail = $detail } }
        default { return [pscustomobject]@{ Status = 'NeedsAttention'; Code = 'UNDO_NOT_FINISHED'; Detail = $detail } }
    }
}

# Undoes the newest change of one game. Never throws. Returns @{ GameId; GameName; Status; Code; Detail; Changed; Folder; LookBefore;
# LookAfter }. Status: Undone, AlreadyUndone, PartlyUndone, ChangedSince, NotChanged, RolledBack, ReceiptDamaged (the receipt cannot be
# used: unreadable, unfinished, of another game or pointing outside the game's folders) or NeedsAttention (Code is the plain reason code).
# A file that changed after the receipt is never overwritten: without -RestoreUnchanged nothing is undone (ChangedSince); with it only the
# files that are still as TeknoParrot Manager left them are put back, and every file left alone is checked again (PartlyUndone). Changed
# lists the files left as they are. A finished undo removes its receipt (the explicit clean-up); every other outcome keeps it.
# A game whose saved files lie inside a configured source collection folder is never changed: NotChanged, UNDO_SOURCE_FOLDER.
function Invoke-TpmReShadeUndo {
    param([Parameter(Mandatory)]$Entry, [switch]$RestoreUnchanged, [string[]]$ProtectedRoots = @())
    $result = [pscustomobject]@{ GameId = [string]$Entry.GameId; GameName = [string]$Entry.GameName; Status = 'NotChanged'; Code = 'UNDO_STOPPED_BEFORE_CHANGE'; Detail = ''; Changed = @(); Folder = [string]$Entry.Folder; LookBefore = [string]$Entry.LookBefore; LookAfter = [string]$Entry.LookAfter }
    try {
        $read = Read-TpmReShadeUndoReceipt -Folder ([string]$Entry.Folder) -VerifyPayload
        if (-not $read.Valid -or [string]$read.Receipt.State -cne 'Applied') {
            $result.Status = 'ReceiptDamaged'; $result.Code = 'UNDO_RECEIPT_DAMAGED'
            $result.Detail = if ($read.Valid) { 'the receipt was never finished' } else { [string]$read.Reason }
            return $result
        }
        $heldPath = @($read.Receipt.Files | ForEach-Object { [string]$_.Path } | Where-Object { Find-TpmProtectedSourceRoot -Path $_ -ProtectedRoots $ProtectedRoots } | Select-Object -First 1)
        if ($heldPath.Count -gt 0) {
            $result.Code = 'UNDO_SOURCE_FOLDER'
            $result.Detail = ('nothing was changed; {0} is inside the source folder {1}' -f $heldPath[0], (Find-TpmProtectedSourceRoot -Path $heldPath[0] -ProtectedRoots $ProtectedRoots))
            return $result
        }
        $check = Get-TpmReShadeUndoCheck -Receipt $read.Receipt
        $result.Changed = @($check.Changed | ForEach-Object { $_.Path })
        if (-not $check.CanUndo -and -not ($RestoreUnchanged -and @($check.ToRestore).Count -gt 0)) {
            $result.Status = 'ChangedSince'; $result.Code = 'UNDO_CHANGED_SINCE'
            return $result
        }
        if ($check.NothingToDo) {
            $result.Status = 'AlreadyUndone'; $result.Code = 'UNDO_ALREADY_DONE'
            [void](Remove-TpmReShadeUndoReceiptFolder -Folder ([string]$Entry.Folder))
            return $result
        }
        $batch = Invoke-TpmReShadeUndoBatch -Folder ([string]$Entry.Folder) -Files $check.ToRestore -Roots @($read.Receipt.Roots)
        $result.Status = $batch.Status; $result.Code = $batch.Code; $result.Detail = $batch.Detail
        if ($batch.Status -cne 'Undone') { return $result }
        if ($check.CanUndo) {
            [void](Remove-TpmReShadeUndoReceiptFolder -Folder ([string]$Entry.Folder))
            return $result
        }
        $result.Status = 'PartlyUndone'; $result.Code = 'UNDO_PARTLY_DONE'
        $moved = @($check.Changed | Where-Object { -not (Test-TpmFileStateMatch -Expected $_.State -Actual (Get-TpmFileState -Path $_.Path) -IgnoreMetadata) })
        if ($moved.Count -gt 0) {
            $result.Status = 'NeedsAttention'; $result.Code = 'UNDO_NOT_FINISHED'
            $result.Detail = 'a file that was to stay as it is is not as it was: ' + (($moved | ForEach-Object { $_.Path }) -join '; ')
        }
    } catch {
        $result.Detail = [string]$_.Exception.Message
    } finally {
        Write-Log ('ReShade undo of {0}: {1} ({2}) {3} -- receipt {4}' -f $result.GameId, $result.Status, $result.Code, $result.Detail, $result.Folder)
        foreach ($changedPath in @($result.Changed)) { Write-Log ('ReShade undo of {0}: changed since the receipt, left as it is: {1}' -f $result.GameId, $changedPath) }
    }
    return $result
}

# One row of the Undo menu: "3) Daytona USA - no ReShade -> Fast CRT, 2026-11-03 14:05".
function Get-TpmReShadeUndoRowText {
    param([Parameter(Mandatory)]$Entry, [int]$Number = 0)
    $text = '{0} - {1} -> {2}' -f $Entry.GameName, (Get-TpmReShadeLookName -LookId ([string]$Entry.LookBefore)), (Get-TpmReShadeLookName -LookId ([string]$Entry.LookAfter))
    if ($null -ne $Entry.When) { $text = $text + ', ' + ([datetime]$Entry.When).ToString('yyyy-MM-dd HH:mm', [Globalization.CultureInfo]::InvariantCulture) }
    if ($Number -gt 0) { $text = ('{0}) {1}' -f $Number, $text) }
    return $text
}

# Which of three plain groups the files before a change belong to: 'None' (TeknoParrot Manager added the ReShade files), 'Other' (a
# ReShade it did not install) or 'Earlier' (an earlier look of TeknoParrot Manager).
function Get-TpmReShadeUndoOwnerGroup {
    param([string]$OwnerBefore = '')
    if ($OwnerBefore -ceq 'None' -or $OwnerBefore -ceq 'Other') { return $OwnerBefore }
    return 'Earlier'
}

# What undoing puts back for one group of games, in plain words: without a count the sentence for one game, with a count one line for
# that many games. The only place that words the three groups.
function Get-TpmReShadeUndoGroupText {
    param([Parameter(Mandatory)][string]$Group, [int]$Count = 0)
    $games = Format-TpmGameCount -Count $Count
    $one = ($Count -eq 1)
    switch ($Group) {
        'None' {
            if ($Count -eq 0) { return 'The ReShade files TeknoParrot Manager added are removed.' }
            return ('{0} {1} back to no ReShade.' -f $games, $(if ($one) { 'goes' } else { 'go' }))
        }
        'Other' {
            if ($Count -eq 0) { return 'Its own ReShade files are put back exactly as they were.' }
            return ('{0} {1} {2} own ReShade back.' -f $games, $(if ($one) { 'gets' } else { 'get' }), $(if ($one) { 'its' } else { 'their' }))
        }
        default {
            if ($Count -eq 0) { return 'Its ReShade files are put back exactly as they were.' }
            return ('{0} {1} back to the look {2} had before.' -f $games, $(if ($one) { 'goes' } else { 'go' }), $(if ($one) { 'it' } else { 'they' }))
        }
    }
}

# What undoing one game puts back, in plain sentences.
function Get-TpmReShadeUndoPlainLines {
    param([Parameter(Mandatory)]$Entry)
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add(('{0} goes back from {1} to {2}.' -f $Entry.GameName, (Get-TpmReShadeLookName -LookId ([string]$Entry.LookAfter)), (Get-TpmReShadeLookName -LookId ([string]$Entry.LookBefore))))
    [void]$lines.Add((Get-TpmReShadeUndoGroupText -Group (Get-TpmReShadeUndoOwnerGroup -OwnerBefore ([string]$Entry.OwnerBefore))))
    if ($null -ne $Entry.Receipt.NativeShader) { [void]$lines.Add("TeknoParrot's own CRT look is turned back on.") }
    return $lines.ToArray()
}

# What Undo all puts back: games with the same result on one line.
function Get-TpmReShadeUndoAllLines {
    param([object[]]$Entries = @())
    $lines = New-Object System.Collections.Generic.List[string]
    $groups = @($Entries | Group-Object -Property { Get-TpmReShadeUndoOwnerGroup -OwnerBefore ([string]$_.OwnerBefore) })
    foreach ($name in @('None', 'Other', 'Earlier')) {
        $group = @($groups | Where-Object { $_.Name -ceq $name })
        if ($group.Count -gt 0) { [void]$lines.Add((Get-TpmReShadeUndoGroupText -Group $name -Count $group[0].Count)) }
    }
    $crt = @($Entries | Where-Object { $null -ne $_.Receipt.NativeShader }).Count
    if ($crt -gt 0) { [void]$lines.Add(("{0} {1} TeknoParrot's own CRT look back." -f (Format-TpmGameCount -Count $crt), $(if ($crt -eq 1) { 'gets' } else { 'get' }))) }
    return $lines.ToArray()
}

# Details of the Undo menu: one block per game with labeled lines.
function Get-TpmReShadeUndoDetailBlocks {
    param([object[]]$Entries = @())
    $blocks = New-Object System.Collections.Generic.List[object]
    foreach ($entry in @($Entries)) {
        $receipt = $entry.Receipt
        $what = switch ([string]$receipt.Operation) {
            'Install' { 'ReShade was installed' }
            'Switch' { 'the look was changed' }
            'Update' { 'ReShade was updated' }
            'Adopt' { 'its own ReShade was replaced' }
            default { 'ReShade was removed' }
        }
        $lines = New-Object System.Collections.Generic.List[string]
        [void]$lines.Add('Change: ' + $what)
        [void]$lines.Add('Look before: ' + (Get-TpmReShadeLookName -LookId ([string]$entry.LookBefore)))
        [void]$lines.Add('Look now: ' + (Get-TpmReShadeLookName -LookId ([string]$entry.LookAfter)))
        if ($null -ne $entry.When) { [void]$lines.Add('Changed on: ' + ([datetime]$entry.When).ToString('yyyy-MM-dd HH:mm', [Globalization.CultureInfo]::InvariantCulture)) }
        if ([bool](Get-TpmTransactionField -Object $receipt -Name 'NeedsCheck' -Default $false)) { [void]$lines.Add('Check: Check this game before you play it. A failed rollback left it half changed.') }
        if ($null -ne $receipt.NativeShader) { [void]$lines.Add(('CRT setting: {0}: {1} -> {2}' -f $receipt.NativeShader.Field, $receipt.NativeShader.Before, $receipt.NativeShader.After)) }
        [void]$lines.Add(('Files saved: {0}' -f @($receipt.Files | Where-Object { [bool]$_.BeforeExists }).Count))
        [void]$lines.Add(('Files the change added: {0}' -f @($receipt.Files | Where-Object { -not [bool]$_.BeforeExists }).Count))
        [void]$lines.Add('Folders it may change: ' + (@($receipt.Roots) -join '; '))
        [void]$lines.Add('Saved copy: ' + [string]$entry.Folder)
        [void]$blocks.Add(@{ Heading = [string]$entry.GameName; Lines = $lines.ToArray() })
    }
    return $blocks.ToArray()
}

# The result of one or more undos: games with the same result on one line; one block per game under Details.
function Write-TpmReShadeUndoOutcome {
    param([object[]]$Results = @())
    $all = @($Results | Where-Object { $null -ne $_ })
    $undone = @($all | Where-Object { $_.Status -in @('Undone', 'AlreadyUndone') })
    $partly = @($all | Where-Object { $_.Status -eq 'PartlyUndone' })
    $changed = @($all | Where-Object { $_.Status -eq 'ChangedSince' })
    $notUndone = @($all | Where-Object { $_.Status -in @('NotChanged', 'RolledBack', 'ReceiptDamaged') })
    $attention = @($all | Where-Object { $_.Status -eq 'NeedsAttention' })
    $notChanged = New-Object System.Collections.Generic.List[string]
    if ($changed.Count -gt 0) {
        $one = ($changed.Count -eq 1)
        [void]$notChanged.Add(('{0} changed after TeknoParrot Manager changed {1}. {2} left as {3}.' -f (Format-TpmGameCount -Count $changed.Count), $(if ($one) { 'it' } else { 'them' }), $(if ($one) { 'It was' } else { 'They were' }), $(if ($one) { 'it is' } else { 'they are' })))
    }
    if ($notUndone.Count -gt 0) { [void]$notChanged.Add(('{0} could not be undone. Nothing was changed in {1}.' -f (Format-TpmGameCount -Count $notUndone.Count), $(if ($notUndone.Count -eq 1) { 'it' } else { 'them' }))) }
    $needs = @()
    if ($partly.Count -gt 0) { $needs = @(('{0} only partly undone. The files that changed were left as they are.' -f (Format-TpmGameCount -Count $partly.Count))) }
    $doneText = 'ReShade changes were undone for {0}.' -f (Format-TpmGameCount -Count $undone.Count)
    $status = 'Ok'
    $done = @()
    $next = ''
    if ($attention.Count -gt 0) {
        $status = 'Problem'
        $title = 'The undo of {0} did not finish and could not be put back.' -f (Format-TpmGameCount -Count $attention.Count)
        if ($undone.Count -gt 0) { $done = @($doneText) }
        $next = 'Press D to see the files to check before you play.'
    } elseif ($undone.Count -gt 0) {
        $title = $doneText
        $next = 'Start the game to check its look.'
    } elseif ($partly.Count -gt 0) {
        $title = 'ReShade changes were partly undone for {0}.' -f (Format-TpmGameCount -Count $partly.Count)
        $next = 'Start the game to check its look.'
    } else {
        $title = 'Nothing was undone.'
    }
    if ($status -ceq 'Ok' -and ($notChanged.Count -gt 0 -or $needs.Count -gt 0 -or ($undone.Count -eq 0 -and $partly.Count -eq 0))) { $status = 'Attention' }
    $blocks = New-Object System.Collections.Generic.List[object]
    foreach ($result in $all) {
        $lines = New-Object System.Collections.Generic.List[string]
        $resultWord = switch ([string]$result.Status) { 'Undone' { 'undone' } 'AlreadyUndone' { 'undone' } 'PartlyUndone' { 'partly undone' } 'ChangedSince' { 'left as it is' } 'NeedsAttention' { 'needs your attention' } default { 'not undone' } }
        [void]$lines.Add('Result: ' + $resultWord)
        [void]$lines.Add('What happened: ' + (Get-TpmPlainReason -Code ([string]$result.Code)).Text)
        if ($result.Status -in @('Undone', 'AlreadyUndone')) { [void]$lines.Add('Look now: ' + (Get-TpmReShadeLookName -LookId ([string]$result.LookBefore))) }
        foreach ($changedPath in @($result.Changed)) { [void]$lines.Add(('Changed file: {0} ({1})' -f [string]$changedPath, (Get-TpmReShadeUndoFileKind -Path ([string]$changedPath)))) }
        [void]$lines.Add('Reason code: ' + [string]$result.Code)
        if (-not [string]::IsNullOrWhiteSpace([string]$result.Detail)) { [void]$lines.Add('Technical detail: ' + [string]$result.Detail) }
        if ($result.Status -notin @('Undone', 'AlreadyUndone')) { [void]$lines.Add('Saved copy: ' + [string]$result.Folder) }
        $color = switch ([string]$result.Status) { 'NeedsAttention' { 'Red' } 'Undone' { 'DarkGray' } 'AlreadyUndone' { 'DarkGray' } default { 'Yellow' } }
        [void]$blocks.Add(@{ Heading = [string]$result.GameName; Lines = $lines.ToArray(); Color = $color })
    }
    Write-TpmOutcome -Title $title -Status $status -Done $done -NotChanged ($notChanged -join ' ') -Needs $needs -Next $next -DetailBlocks $blocks.ToArray() -DetailsNote 'Undo puts files back only while they are exactly as TeknoParrot Manager left them.'
}

# Asks for a typed word before anything is changed. True only for that word; any other answer says nothing was changed and is logged
# (LogText names who was asked about).
function Confirm-TpmReShadeUndoWord {
    param([Parameter(Mandatory)][string]$Word, [Parameter(Mandatory)][string]$Prompt, [Parameter(Mandatory)][string]$LogText)
    $answer = Read-TpmResetRestoreAnswer -Intro ('Any answer other than {0} cancels, and nothing is changed.' -f $Word) -Prompt $Prompt
    if ($answer.Trim().ToUpperInvariant() -ceq $Word) { return $true }
    Write-TpmText -Text 'Canceled. Nothing was changed.' -Color DarkGray
    Write-Log ('ReShade undo of {0}: canceled, nothing was changed.' -f $LogText)
    return $false
}

# Which kinds of file changed, one short line per kind and never a path.
function Get-TpmReShadeUndoChangedKindLines {
    param([object[]]$Changed = @())
    $words = [ordered]@{ 'ReShade settings file' = 'The ReShade settings file'; 'game profile' = 'The game profile'; 'ReShade files' = 'Some ReShade files' }
    $kinds = @($Changed | ForEach-Object { [string]$_.Kind })
    return @($words.Keys | Where-Object { $kinds -contains $_ } | ForEach-Object { $words[$_] })
}

# A game that changed after its receipt. Says which kinds of file changed and never touches them. When other files of the game can still
# be put back, U puts back only those (no second question: pressing U is the approval); D shows the changed files; C or Enter leaves everything as it is.
function Invoke-TpmReShadeUndoChangedChoice {
    param([Parameter(Mandatory)]$Entry, [Parameter(Mandatory)]$Check, [string[]]$ProtectedRoots = @())
    $canPart = (@($Check.ToRestore).Count -gt 0)
    Write-Log ('ReShade undo of {0}: changed since the receipt, left as it is ({1} file(s)); {2} file(s) can be put back on their own.' -f $Entry.GameId, @($Check.Changed).Count, @($Check.ToRestore).Count)
    Write-TpmText -Text ('{0} changed after TeknoParrot Manager changed it.' -f $Entry.GameName) -Color Yellow -BlankBefore
    Write-TpmText -Text 'These files are different now:' -Color Yellow
    foreach ($line in @(Get-TpmReShadeUndoChangedKindLines -Changed $Check.Changed)) { Write-TpmText -Text ('- ' + $line) -Color Yellow -Indent 4 -HangingIndent 2 }
    if ($canPart) { Write-TpmText -Text 'The other files can still be undone. The files that are different now are not touched.' -Color White -BlankBefore }
    else { Write-TpmText -Text 'To keep those later changes, nothing is undone.' -Color Yellow -BlankBefore }
    Write-Host ''
    $choices = @('D', 'C')
    if ($canPart) { $choices = @('U', 'D', 'C'); Write-TpmText -Text '[U] Undo only the files that did not change' -Color White }
    Write-TpmText -Text '[D] Details' -Color White
    Write-TpmText -Text '[C] Leave it as it is' -Color White
    do {
        $choice = Read-TpmChoice -Prompt '  Choice, default C' -Choices $choices -Default 'C'
        if ($choice -ceq 'D') {
            $lines = @($Check.Changed | ForEach-Object { 'Changed file: {0} ({1})' -f $_.Path, $_.Kind }) + @($Check.ToRestore | ForEach-Object { 'As it was left: ' + [string]$_.Path })
            Show-TpmDetailBlocks -Blocks @(@{ Heading = [string]$Entry.GameName; Color = 'Yellow'; Lines = $lines }) -Note 'A file that changed is never overwritten. Undo puts files back only while they are exactly as TeknoParrot Manager left them.'
        }
    } while ($choice -ceq 'D')
    if ($choice -cne 'U') { return }
    Write-TpmReShadeUndoOutcome -Results @(Invoke-TpmReShadeUndo -Entry $Entry -RestoreUnchanged -ProtectedRoots $ProtectedRoots)
}

# One game: a game changed since its receipt goes to Invoke-TpmReShadeUndoChangedChoice; otherwise what will be put back, a typed YES,
# the undo and its result.
function Invoke-TpmReShadeUndoGameChoice {
    param([Parameter(Mandatory)]$Entry, [string[]]$ProtectedRoots = @())
    $check = Get-TpmReShadeUndoCheck -Receipt $Entry.Receipt
    if (-not $check.CanUndo) {
        Invoke-TpmReShadeUndoChangedChoice -Entry $Entry -Check $check -ProtectedRoots $ProtectedRoots
        return
    }
    Write-Host ''
    foreach ($line in @(Get-TpmReShadeUndoPlainLines -Entry $Entry)) { Write-TpmText -Text $line -Color White }
    Write-Host ''
    if (-not (Confirm-TpmReShadeUndoWord -Word 'YES' -Prompt 'Type YES to undo it' -LogText ([string]$Entry.GameId))) { return }
    Write-TpmReShadeUndoOutcome -Results @(Invoke-TpmReShadeUndo -Entry $Entry -ProtectedRoots $ProtectedRoots)
}

# All games: what will be put back (games with the same result on one line), a typed ALL, then one undo per game and one result.
function Invoke-TpmReShadeUndoAllChoice {
    param([object[]]$Entries = @(), [string[]]$ProtectedRoots = @())
    Write-TpmText -Text ('This undoes the last ReShade change of {0}.' -f (Format-TpmGameCount -Count @($Entries).Count)) -Color White -BlankBefore
    foreach ($line in @(Get-TpmReShadeUndoAllLines -Entries $Entries)) { Write-TpmText -Text ('- ' + $line) -Color White -Indent 4 -HangingIndent 2 }
    Write-TpmText -Text 'A game that changed since then is left as it is.' -Color DarkGray
    Write-Host ''
    if (-not (Confirm-TpmReShadeUndoWord -Word 'ALL' -Prompt 'Type ALL to undo all of them' -LogText 'all games')) { return }
    $results = New-Object System.Collections.Generic.List[object]
    foreach ($entry in @($Entries)) { [void]$results.Add((Invoke-TpmReShadeUndo -Entry $entry -ProtectedRoots $ProtectedRoots)) }
    Write-TpmReShadeUndoOutcome -Results $results.ToArray()
}

# The rows of one page of the Undo menu (at most 4, so the page stays short) and its keys. Every row wraps under its own text; a blank
# line separates the rows, the "More" line and the keys.
function Write-TpmReShadeUndoList {
    param([object[]]$Visible = @(), [int]$Total = 0, [int]$PageCount = 1)
    Write-Host ''
    Write-TpmText -Text 'Undo ReShade changes' -Color Cyan
    Write-TpmText -Text 'TeknoParrot Manager changed the ReShade of these games. Newest first.' -Color DarkGray
    Write-Host ''
    for ($index = 0; $index -lt @($Visible).Count; $index++) {
        Write-TpmText -Text (Get-TpmReShadeUndoRowText -Entry $Visible[$index] -Number ($index + 1)) -HangingIndent 3
    }
    if ($PageCount -gt 1) {
        $rest = $Total - @($Visible).Count
        Write-TpmText -Text ('More: M ({0})' -f (Format-TpmCountNoun -Count $rest -Singular 'game' -Modifier 'more')) -Color DarkGray -BlankBefore
    }
    Write-Host ''
    Write-TpmText -Text $(if (@($Visible).Count -eq 1) { '[1] Undo this game' } else { ('[1-{0}] Undo one game' -f @($Visible).Count) }) -Color White
    Write-TpmText -Text ('[A] Undo all ({0})' -f (Format-TpmGameCount -Count $Total)) -Color White
    if ($PageCount -gt 1) { Write-TpmText -Text '[M] More games' -Color White }
    Write-TpmText -Text '[D] Details' -Color White
    Write-TpmText -Text '[B] Back' -Color White
}

# ReShade > Undo ReShade changes. The games TeknoParrot Manager changed, newest first, 4 per page. A number undoes that game, A undoes
# all of them, M shows more, D shows the details, B goes back. Nothing is changed without a typed YES (one game) or ALL (all games).
# Differs from Read-TpmNumberedListChoice: pages of 4 with its own keys (A undoes all games), and it runs the chosen undo itself.
function Show-TpmReShadeUndoMenu {
    param([string]$StateRoot = '', [string[]]$ProtectedRoots = @())
    $pageSize = 4
    $page = 0
    while ($true) {
        $entries = @(Get-TpmReShadeUndoEntries -StateRoot $StateRoot)
        if ($entries.Count -eq 0) {
            Write-TpmText -Text 'There is nothing to undo right now.' -Color DarkGray -BlankBefore
            Write-TpmText -Text 'TeknoParrot Manager saves a copy each time it changes the ReShade of a game.' -Color DarkGray -BlankAfter
            [void](Read-HostSafe '  Press Enter to return to the menu')
            return
        }
        $pageCount = [int][Math]::Ceiling($entries.Count / [double]$pageSize)
        if ($page -ge $pageCount) { $page = 0 }
        $visible = @($entries | Select-Object -Skip ($page * $pageSize) -First $pageSize)
        Write-TpmReShadeUndoList -Visible $visible -Total $entries.Count -PageCount $pageCount
        $choices = @(@(1..$visible.Count | ForEach-Object { [string]$_ }) + @('A', 'D', 'B'))
        if ($pageCount -gt 1) { $choices += 'M' }
        $choice = Read-TpmChoice -Prompt '  Choice, default B' -Choices $choices -Default 'B'
        switch ($choice) {
            'B' { return }
            'M' { $page++ }
            'D' { Show-TpmDetailBlocks -Blocks @(Get-TpmReShadeUndoDetailBlocks -Entries $visible) -Note 'Undo puts files back only while they are exactly as TeknoParrot Manager left them.' }
            'A' { Invoke-TpmReShadeUndoAllChoice -Entries $entries -ProtectedRoots $ProtectedRoots }
            default { Invoke-TpmReShadeUndoGameChoice -Entry $visible[[int]$choice - 1] -ProtectedRoots $ProtectedRoots }
        }
    }
}

# A game whose undo copy could not be saved is not changed; the setup says so in plain words (the reason is in the log).
function Write-TpmReShadeUndoReceiptFailedLine {
    param([Parameter(Mandatory)][string]$GameName)
    Write-TpmText -Text ('FAILED {0}: not changed, because a copy for undo could not be saved.' -f $GameName) -Color Red -Indent 4 -HangingIndent 2
}

# One game whose undo copy could not be saved: counts one error, lists the game as failed and says so in plain words and in the notes
# of the result. The one place that does this, for a reapply and for a new setup alike.
function Register-TpmReShadeUndoReceiptFailure {
    param([Parameter(Mandatory)][string]$Game, [Parameter(Mandatory)][string]$GameName, [Parameter(Mandatory)][ref]$ErrorCount, [Parameter(Mandatory)]$FailedGameIds, [Parameter(Mandatory)]$DetailNotes)
    $ErrorCount.Value++
    [void]$FailedGameIds.Add($Game)
    Write-TpmReShadeUndoReceiptFailedLine -GameName $GameName
    [void]$DetailNotes.Add(('{0}: no copy for undo could be saved -- unchanged' -f $Game))
}



function Install-TpmReShadeProfileDeployment {
    param(
        [Parameter(Mandatory)]$ProfileDefinition,
        [Parameter(Mandatory)][string]$GamePath,
        [Parameter(Mandatory)][System.Xml.XmlDocument]$Doc,
        [Parameter(Mandatory)][string]$SourceDll,
        [string]$PresetPath = '',
        [string]$PerGamePresetPath = '',
        [Parameter(Mandatory)][string]$CacheRoot,
        [Parameter(Mandatory)][string]$OwnershipPath,
        [string]$VariantId = 'Default',
        [string]$SourceVersion = '',
        [switch]$CanonicalPreset,
        [switch]$AllowUserOwnedOverwrite,
        [string]$HdrTargetDisplayId = '',
        [string]$ExpectedHdrFingerprint = '',
        # FIX68: an undo request (New-TpmReShadeUndoRequest). When given, a checked undo receipt of every file this deployment may
        # replace (and of the ownership record and the request's extra paths) is made before the first write; without it nothing is written.
        [object]$UndoReceipt = $null,
        # FIX96: the configured source collection folders; a game folder inside one of them is refused before anything is staged or written.
        [string[]]$ProtectedRoots = @(),
        [ValidateSet('None','BeforeCommit')][string]$FaultStage = 'None'
    )
    $staging = $null
    $undo = $null
    $preparedStages = New-Object System.Collections.Generic.List[string]
    $preserveStaging = $false
    $assetProgressLabel = $null
    $assetProgressStarted = $null
    $assetProgressCurrent = 0
    $assetProgressTotal = 0
    try {
        $approvedProfile = Get-TpmReShadeProfile -ProfileId $ProfileDefinition.ProfileId
        if (-not $approvedProfile -or [string]$approvedProfile.SchemaVersion -ne [string]$ProfileDefinition.SchemaVersion -or (@($approvedProfile.Effects) -join ',') -ne (@($ProfileDefinition.Effects) -join ',')) {
            return [pscustomobject]@{ Succeeded = $false; State = 'STALE_PROFILE_DEFINITION'; Reason = 'STALE_PROFILE_DEFINITION' }
        }
        # Deployment-time HDR guard (covers every caller, including restore): an HDR-only profile is refused unless real detection says
        # the relevant display has HDR active right now. Nothing is written when refused.
        if (Test-TpmReShadeProfileRequiresHdr -Entry $approvedProfile) {
            $liveHdrGate = Get-TpmReShadeHdrGate -TargetDisplayId $HdrTargetDisplayId
            if (-not [bool]$liveHdrGate.Enabled) {
                return [pscustomobject]@{ Succeeded = $false; State = 'HDR_UNAVAILABLE'; Reason = 'HDR_UNAVAILABLE' }
            }
            if (-not [string]::IsNullOrWhiteSpace($ExpectedHdrFingerprint) -and [string]$liveHdrGate.Fingerprint -ne $ExpectedHdrFingerprint) {
                return [pscustomobject]@{ Succeeded = $false; State = 'HDR_UNAVAILABLE'; Reason = 'HDR_EVIDENCE_CHANGED' }
            }
        }
        foreach ($approvedEffectId in @($approvedProfile.Effects)) {
            $approvedEffect = Get-TpmReShadeEffectCatalog | Where-Object { [string]$_.EffectId -eq [string]$approvedEffectId } | Select-Object -First 1
            $obligation = if ($approvedEffect) { Get-TpmReShadeEffectObligationStatus -Effect $approvedEffect } else { $null }
            if ($null -eq $obligation -or -not $obligation.MetadataComplete) {
                return [pscustomobject]@{ Succeeded = $false; State = 'LICENSE_OBLIGATIONS_INCOMPLETE'; Reason = 'LICENSE_OBLIGATIONS_INCOMPLETE' }
            }
            if (-not $obligation.Offerable) {
                return [pscustomobject]@{ Succeeded = $false; State = 'LICENSE_OBLIGATIONS_UNREVIEWED'; Reason = 'LICENSE_OBLIGATIONS_UNREVIEWED' }
            }
        }
        $variant = Resolve-TpmReShadeIntensityVariant -ProfileDefinition $approvedProfile -VariantId $VariantId
        # A game path over 259 characters is refused in plain words first: with Windows long paths off, the path calls below fail on it (Windows PowerShell 5.1) and would report a wrong reason.
        Assert-TpmWritePathsShortEnough -Paths @($GamePath)
        $exeDir = [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($GamePath))
        if ([string]::IsNullOrWhiteSpace($exeDir)) { return [pscustomobject]@{ Succeeded = $false; State = 'INVALID_GAME_PATH'; Reason = 'INVALID_GAME_PATH' } }
        $architecture = Get-ExeArchitecture -ExePath $GamePath
        # A 64-bit game gets ReShade64.dll and a 32-bit game gets ReShade32.dll. An unreadable or unrecognized executable is refused (guessing a DLL could install one that never loads).
        if ($architecture -ne 'x64' -and $architecture -ne 'x86') { return [pscustomobject]@{ Succeeded = $false; State = 'UNSUPPORTED_ARCHITECTURE'; Reason = 'UNSUPPORTED_ARCHITECTURE' } }
        $activeDll = Get-TpmReShadeSourceDllForArchitecture -SourceDll $SourceDll -Architecture $architecture
        if (-not $activeDll) { return [pscustomobject]@{ Succeeded = $false; State = 'DLL_32BIT_MISSING'; Reason = 'DLL_32BIT_MISSING' } }
        if (-not $activeDll -or -not (Test-Path -LiteralPath $activeDll -PathType Leaf) -or -not (Test-TpmNoReparsePath -Path $activeDll)) { return [pscustomobject]@{ Succeeded = $false; State = 'UNSAFE_PATH'; Reason = 'UNSAFE_PATH' } }
        $runtimeHash = (Get-FileHash -LiteralPath $activeDll -Algorithm SHA256 -ErrorAction Stop).Hash
        if (-not (Test-Path -LiteralPath $GamePath -PathType Leaf) -or -not (Test-TpmNoReparsePath -Path $GamePath)) { return [pscustomobject]@{ Succeeded = $false; State = 'INVALID_GAME_PATH'; Reason = 'INVALID_GAME_PATH' } }
        $targetInfo = Get-ReShadeTargetInfo -Doc $Doc -GamePath $GamePath -ExeDir $exeDir
        if (-not $targetInfo -or [string]::IsNullOrWhiteSpace($targetInfo.TargetDir) -or [string]::IsNullOrWhiteSpace($targetInfo.DllName) -or -not (Test-TpmNoReparsePath -Path $targetInfo.TargetDir)) { return [pscustomobject]@{ Succeeded = $false; State = 'UNSAFE_PATH'; Reason = 'UNSAFE_PATH' } }
        if ((Test-Path -LiteralPath $CacheRoot) -and -not (Test-TpmNoReparsePath -Path $CacheRoot)) { return [pscustomobject]@{ Succeeded = $false; State = 'UNSAFE_PATH'; Reason = 'UNSAFE_PATH' } }
        if (-not (Test-TpmNoReparsePath -Path $OwnershipPath)) { return [pscustomobject]@{ Succeeded = $false; State = 'UNSAFE_PATH'; Reason = 'UNSAFE_PATH' } }
        if (Find-TpmProtectedSourceRoot -Path ([string]$targetInfo.TargetDir) -ProtectedRoots $ProtectedRoots) { return [pscustomobject]@{ Succeeded = $false; State = 'SOURCE_COLLECTION'; Reason = 'SOURCE_COLLECTION' } }
        $prior = Read-TpmReShadeOwnershipManifest -Path $OwnershipPath
        $staging = New-TpmStagingDirectory -Label 'ReShadeProfile'
        $fileNames = New-Object System.Collections.Generic.List[string]
        $manifestFiles = New-Object System.Collections.Generic.List[object]
        $dllName = [System.IO.Path]::GetFileName($targetInfo.DllName)
        if ([string]::IsNullOrWhiteSpace($dllName) -or $dllName -ne $targetInfo.DllName) { return [pscustomobject]@{ Succeeded = $false; State = 'INVALID_TARGET'; Reason = 'INVALID_TARGET' } }
        $dllStage = Join-Path $staging $dllName
        Copy-Item -LiteralPath $activeDll -Destination $dllStage -Force -ErrorAction Stop
        if (-not (Test-Path -LiteralPath $dllStage -PathType Leaf)) { throw 'DLL staging failed.' }
        $dllHash = (Get-FileHash -LiteralPath $dllStage -Algorithm SHA256 -ErrorAction Stop).Hash
        [void]$fileNames.Add($dllName)
        [void]$manifestFiles.Add([pscustomobject]@{ RelativeSource = $dllName; DestinationPath = (Join-Path $targetInfo.TargetDir $dllName); ExpectedSHA256 = $dllHash; ActualSHA256 = $dllHash; TPMManaged = $true; Kind = 'ReShadeDll' })
        $effectivePreset = $null
        $presetSource = $null
        $presetContent = $null
        if ($PerGamePresetPath -and (Test-Path -LiteralPath $PerGamePresetPath -PathType Leaf)) { $effectivePreset = $PerGamePresetPath; $presetSource = 'per-game' }
        elseif ($PresetPath -and (Test-Path -LiteralPath $PresetPath -PathType Leaf)) { $effectivePreset = $PresetPath; $presetSource = 'global' }
        if ($effectivePreset) {
            if ([System.IO.Path]::GetExtension($effectivePreset) -ine '.ini') { return [pscustomobject]@{ Succeeded = $false; State = 'INVALID_PRESET'; Reason = 'INVALID_PRESET' } }
            $presetContent = [IO.File]::ReadAllText($effectivePreset)
        } elseif ($CanonicalPreset -or [string]$approvedProfile.ProfileId -ceq 'Original') {
            $presetSource = 'generated'
            $presetContent = New-TpmReShadePresetContent -ProfileDefinition $approvedProfile
        } else {
            $priorIni = if ($prior) { @($prior.Files | Where-Object { [string]$_.RelativeSource -ieq 'ReShade.ini' -and $_.TPMManaged -eq $true })[0] } else { $null }
            if ($priorIni -and (Test-Path -LiteralPath ([string]$priorIni.DestinationPath) -PathType Leaf)) {
                $presetSource = 'tutorial'
                $presetContent = [IO.File]::ReadAllText([string]$priorIni.DestinationPath)
            } else {
                $presetSource = 'tutorial'
                $presetContent = ''
            }
        }
        $presetContent = Update-TpmReShadeTutorialProgressText -Content $presetContent
        $presetName = 'ReShade.ini'
        $presetStage = Join-Path $staging $presetName
        try {
            [IO.File]::WriteAllText($presetStage, [string]$presetContent, (New-Object Text.UTF8Encoding($false)))
            $verifiedPreset = [IO.File]::ReadAllText($presetStage)
            if ($verifiedPreset -notmatch '(?ms)^\s*\[OVERLAY\]\s*$.*?^\s*TutorialProgress\s*=\s*4\s*$') { throw 'TutorialProgress=4 was not verified in staged ReShade.ini.' }
        } catch {
            throw ("TUTORIAL_PROGRESS_FAILED: ReShade.ini write/verification failed -- {0}" -f $_.Exception.Message)
        }
        $presetHash = (Get-FileHash -LiteralPath $presetStage -Algorithm SHA256 -ErrorAction Stop).Hash
        [void]$fileNames.Add($presetName)
        [void]$manifestFiles.Add([pscustomobject]@{ RelativeSource = $presetName; DestinationPath = (Join-Path $targetInfo.TargetDir $presetName); ExpectedSHA256 = $presetHash; ActualSHA256 = $presetHash; TPMManaged = $true; Kind = 'ReShadePreset' })
        foreach ($effectId in @($approvedProfile.Effects)) {
            $prepared = Install-TpmReShadeApprovedEffect -EffectId $effectId -CacheRoot $CacheRoot
            if (-not $prepared -or -not $prepared.Succeeded -or $prepared.State -ne 'PREPARED' -or [string]::IsNullOrWhiteSpace([string]$prepared.StagingRoot)) { throw "Approved effect preparation failed for $effectId." }
            [void]$preparedStages.Add([string]$prepared.StagingRoot)
            $assetFiles = @($prepared.Files)
            $assetProgressLabel = 'ReShade profile asset staging'
            $assetProgressStarted = Get-Date
            $assetProgressCurrent = 0
            $assetProgressTotal = $assetFiles.Count
            if ($assetProgressTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label $assetProgressLabel -Current $assetProgressCurrent -Total $assetProgressTotal -StartedAt $assetProgressStarted }
            foreach ($asset in $assetFiles) {
                $assetProgressCurrent++
                Write-TpmCompactExtractionProgress -Phase Extracting -Label $assetProgressLabel -Current $assetProgressCurrent -Total $assetProgressTotal -StartedAt $assetProgressStarted
                $rawRelative = [string]$asset.RelativePath
                $relative = ($rawRelative -replace '/', '\').TrimStart('\')
                $assetDestination = Join-Path $targetInfo.TargetDir $relative
                $assetStage = Join-Path $staging $relative
                if ([string]::IsNullOrWhiteSpace($rawRelative) -or [System.IO.Path]::IsPathRooted($rawRelative) -or $rawRelative.StartsWith('/') -or $rawRelative.StartsWith('\') -or $relative -match '(^|\\)\.\.(\\|$)' -or -not (Test-PathInside $assetStage $staging) -or -not (Test-PathInside ([string]$asset.Path) ([string]$prepared.StagingRoot))) { throw 'Approved effect path is unsafe.' }
                [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($assetStage))
                Copy-Item -LiteralPath $asset.Path -Destination $assetStage -Force -ErrorAction Stop
                if (-not (Test-TpmReShadeApprovedEffectFile -FileSpec $asset -Path $assetStage)) { throw "INTEGRITY: staged approved effect hash validation failed for $relative." }
                $assetHash = (Get-FileHash -LiteralPath $assetStage -Algorithm SHA256 -ErrorAction Stop).Hash
                if ($fileNames -contains $relative) {
                    $existingAsset = @($manifestFiles.ToArray() | Where-Object { [string]::Equals([string]$_.DestinationPath, [string]$assetDestination, [StringComparison]::OrdinalIgnoreCase) })[0]
                    $assetLength = [int64](Get-Item -LiteralPath $assetStage -ErrorAction Stop).Length
                    if (-not $existingAsset -or $existingAsset.Kind -ne 'ApprovedEffect' -or [string]$existingAsset.ExpectedSHA256 -ine $assetHash -or -not $existingAsset.PSObject.Properties['ByteLength'] -or [int64]$existingAsset.ByteLength -ne $assetLength) { throw "Conflicting approved assets target the same ReShade path: $relative" }
                    continue
                }
                [void]$fileNames.Add($relative)
                $assetLength = [int64](Get-Item -LiteralPath $assetStage -ErrorAction Stop).Length
                [void]$manifestFiles.Add([pscustomobject]@{ RelativeSource = [string]$asset.SourceRelativePath; DestinationPath = $assetDestination; ExpectedSHA256 = $assetHash; ActualSHA256 = $assetHash; ByteLength = $assetLength; TPMManaged = $true; Kind = 'ApprovedEffect' })
            }
            if ($assetProgressTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase Extracting -Label $assetProgressLabel -Current $assetProgressCurrent -Total $assetProgressTotal -StartedAt $assetProgressStarted -Complete }
            $assetProgressLabel = $null
        }
        foreach ($entry in $manifestFiles.ToArray()) {
            if (-not (Test-PathInside ([string]$entry.DestinationPath) ([string]$targetInfo.TargetDir))) { throw 'SECURITY: profile destination escaped target folder.' }
            if (Test-Path -LiteralPath $entry.DestinationPath) {
                $owned = $false
                if ($prior) { foreach ($oldEntry in @($prior.Files)) { if ([string]$oldEntry.DestinationPath -eq [string]$entry.DestinationPath -and [string]$oldEntry.TPMManaged -eq 'True') { $owned = $true; break } } }
                if (-not $owned -and -not $AllowUserOwnedOverwrite) { return [pscustomobject]@{ Succeeded = $false; State = 'COLLISION'; Reason = 'USER_OWNED_CONTENT_PRESERVED'; Error = "Existing file not managed by TeknoParrot Manager was preserved: $($entry.DestinationPath)" } }
            }
        }
        $retained = @()
        # Files the earlier look wrote and this look does not are carried forward only while they are still there and still the bytes
        # TeknoParrot Manager wrote. A deleted or changed file would fail the check after install on every later run; it is left alone and no longer listed.
        if ($prior) { $retained = @($prior.Files | Where-Object {
            $_.DestinationPath -notin @($manifestFiles.ToArray() | ForEach-Object DestinationPath) -and
            (Test-Path -LiteralPath ([string]$_.DestinationPath) -PathType Leaf) -and
            ((Get-FileHash -LiteralPath ([string]$_.DestinationPath) -Algorithm SHA256 -ErrorAction SilentlyContinue).Hash -ieq [string]$_.ExpectedSHA256)
        }) }
        $manifest = [pscustomobject]@{ SchemaVersion = 1; EffectId = 'ReShadeProfile.' + $approvedProfile.ProfileId; PinnedRevision = 'TPM-PROFILE'; RuntimeVersion = $SourceVersion; RuntimeSHA256 = $runtimeHash; Files = @($manifestFiles.ToArray() + $retained) }
        if ($null -ne $UndoReceipt) {
            $undoPaths = @(@($manifestFiles.ToArray() | ForEach-Object { [string]$_.DestinationPath }) + @($OwnershipPath))
            $undo = New-TpmReShadeUndoReceipt -Request $UndoReceipt -Paths $undoPaths -Roots @([string]$targetInfo.TargetDir, [IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($OwnershipPath)))
            if (-not $undo.Succeeded) { return [pscustomobject]@{ Succeeded = $false; State = 'RECEIPT_FAILED'; Reason = 'UNDO_RECEIPT_FAILED'; Error = [string]$undo.Reason } }
        }
        $commit = { if ($FaultStage -eq 'BeforeCommit') { throw 'TEST: forced profile commit failure.' }; Save-TpmReShadeOwnershipManifest -Manifest $manifest -Path $OwnershipPath | Out-Null }
        # The promotion and the commit are done once Invoke-TpmTransactionalPromote reaches its cleanup. A cleanup failure after that point
        # leaves the game files and the ownership manifest changed and correct, so it is a success with residue and the undo receipt stays.
        $cleanupResidue = ''
        try {
            [void](Invoke-TpmTransactionalPromote -StagingDir $staging -DestDir $targetInfo.TargetDir -FileNames $fileNames.ToArray() -CommitAction $commit)
        } catch {
            if ($_.Exception.Message -notmatch 'CLEANUP FAILED AFTER VERIFIED PROMOTION') { throw }
            $cleanupResidue = [string]$_.Exception.Message
            $preserveStaging = $true
            Write-Log ("ReShade: profile installed for {0}, but temporary-file cleanup failed; the undo receipt is kept -- {1}" -f $GamePath, $cleanupResidue)
        }
        return [pscustomobject]@{ Succeeded = $true; State = 'INSTALLED'; ProfileId = $approvedProfile.ProfileId; VariantId = $variant.VariantId; TargetDir = $targetInfo.TargetDir; DllName = $dllName; ApiDetected = $targetInfo.ApiDetected; RuntimeVersion = $SourceVersion; RuntimeSHA256 = $runtimeHash; PresetSource = $presetSource; PresetApplied = [bool]($effectivePreset -or $presetContent); Manifest = $manifest; UndoReceipt = $undo; CleanupResidue = $cleanupResidue }
    } catch {
        $message = $_.Exception.Message
        if ($message -match 'ROLLBACK FAILED|CLEANUP FAILED') { $preserveStaging = $true }
        # A verified rollback left the game as it was, so its receipt holds nothing to undo and is removed. After a failed rollback the
        # receipt is kept and returned: it holds the only checked copy of the files as they were.
        $undoKept = $null
        if ($null -ne $undo -and $undo.Succeeded) {
            if ($message -match 'ROLLBACK FAILED') { $undoKept = $undo } else { [void](Remove-TpmReShadeUndoReceiptFolder -Folder ([string]$undo.Folder)) }
        }
        return [pscustomobject]@{ Succeeded = $false; State = if ($message -match 'COLLISION') { 'COLLISION' } elseif ($message -match 'ROLLBACK FAILED') { 'ACTION_REQUIRED' } else { 'ROLLED_BACK' }; Reason = if ($message -match 'TUTORIAL_PROGRESS_FAILED') { 'TUTORIAL_PROGRESS_FAILED' } elseif ([string]$_.Exception.Data['TpmNoChange'] -ceq 'PATH_TOO_LONG') { 'PATH_TOO_LONG' } else { 'PROFILE_DEPLOYMENT_FAILED' }; Error = $message; RollbackVerified = ($message -notmatch 'ROLLBACK FAILED'); UndoReceipt = $undoKept }
    } finally {
        if ($assetProgressLabel -and $assetProgressStarted) { Write-TpmCompactExtractionProgress -Phase Extracting -Label $assetProgressLabel -Current $assetProgressCurrent -Total $assetProgressTotal -StartedAt $assetProgressStarted -Complete -Outcome Error; $assetProgressLabel = $null }
        foreach ($preparedStage in @($preparedStages.ToArray())) { if (Test-Path -LiteralPath $preparedStage) { Remove-Item -LiteralPath $preparedStage -Recurse -Force -ErrorAction SilentlyContinue } }
        if ($staging -and -not $preserveStaging -and (Test-Path -LiteralPath $staging)) { Remove-Item -LiteralPath $staging -Recurse -Force -ErrorAction SilentlyContinue }
    }
}
# Read-only look at which controller types are connected (contract: docs/architecture/CONTROLLER_EVIDENCE_CONTRACT.md).
# It only suggests: the Device Survey uses a clear match as the default answer and the user can always change it.
# It never writes a file, never keeps a serial number or device path, and any failure gives an empty "SourceUnavailable" result.
# With -Salt it also returns one fingerprint per arcade encoder it recognizes: a one-way hash of the salt, the maker/model numbers and
# a counter. The raw numbers and instance ids are read in memory only to count boards and build that hash; they are never returned.
function Get-TpmControllerEvidence {
    param([string]$Salt = '')
    $found = New-Object System.Collections.Generic.List[object]
    $fingerprints = New-Object System.Collections.Generic.List[object]
    $hash = { param([string]$Text) $sha = [System.Security.Cryptography.SHA256]::Create(); try { (@($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text)) | ForEach-Object { $_.ToString('x2') }) -join '') } finally { $sha.Dispose() } }
    $reasons = New-Object System.Collections.Generic.List[string]
    $add = { param($Class, $Confidence, $Basis, $Count) [void]$found.Add([pscustomobject][ordered]@{ DeviceClass = $Class; Confidence = $Confidence; Basis = $Basis; Count = [int]$Count; ReasonCodes = @() }) }
    $status = 'Observed'
    try {
        # Xbox-style pads: ask Windows which of the four XInput slots are in use.
        try {
            if (-not ('TpmXInputProbe' -as [type])) {
                Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public static class TpmXInputProbe { [DllImport("xinput1_4.dll")] static extern int XInputGetState(int i, byte[] s); public static int Count() { int c = 0; for (int i = 0; i < 4; i++) { if (XInputGetState(i, new byte[16]) == 0) c++; } return c; } }'
            }
            $xinputCount = [TpmXInputProbe]::Count()
            if ($xinputCount -gt 0) { & $add 'XboxStylePad' 'High' 'XInputSlotActive' $xinputCount }
        } catch { [void]$reasons.Add('XInputUnavailable') }
        # Everything else comes from Windows device names and classes. Only the type is kept, never the name.
        try {
            $devices = @(Get-CimInstance Win32_PnPEntity -Filter "PNPClass='HIDClass' OR PNPClass='Mouse'" -OperationTimeoutSec 3 -ErrorAction Stop)
            $hints = [ordered]@{ Wheel = 'wheel|steering|racing'; LightGun = 'gun|sinden|aimtrak'; ArcadeEncoder = 'i-pac|ipac|encoder|ultrastik|zero delay|xin-mo|brook'; PointerOrTrackball = 'trackball|spinner' }
            foreach ($class in $hints.Keys) {
                $n = @($devices | Where-Object { [string]$_.Name -match $hints[$class] }).Count
                if ($n -gt 0) { & $add $class 'Low' 'NameHint' $n }
            }
            # A small list of makers that only build arcade keyboard encoders. A match is Medium at most: it says a board of that maker is
            # plugged in, not what the buttons do. Boards of one model are counted by instance id: every interface of one board shows one
            # id, so the most ids any single interface shows is the number of boards. A different USB port changes the ids but not the count.
            $knownVendors = [ordered]@{ 'D209' = 'ArcadeEncoder' }
            foreach ($vendor in $knownVendors.Keys) {
                $interfaces = @{}
                foreach ($device in $devices) {
                    if ([string]$device.DeviceID -match ('^[^\\]*\\VID_' + $vendor + '&PID_([0-9A-F]{4})([^\\]*)\\(.+)$')) {
                        $slot = $Matches[1].ToUpperInvariant() + '|' + $Matches[2]
                        if (-not $interfaces.ContainsKey($slot)) { $interfaces[$slot] = New-Object 'System.Collections.Generic.HashSet[string]' }
                        [void]$interfaces[$slot].Add($Matches[3])
                    }
                }
                $perModel = @{}
                foreach ($slot in $interfaces.Keys) { $model = $slot.Split('|')[0]; $perModel[$model] = [Math]::Max([int]$perModel[$model], $interfaces[$slot].Count) }
                $boards = 0
                foreach ($model in @($perModel.Keys | Sort-Object)) {
                    $boards += [int]$perModel[$model]
                    if ($Salt) { for ($n = 1; $n -le [int]$perModel[$model]; $n++) { [void]$fingerprints.Add([pscustomobject][ordered]@{ DeviceClass = $knownVendors[$vendor]; Fingerprint = (& $hash ('TpmControllerFingerprint|1|{0}|{1}|VID_{2}&PID_{3}|{4}' -f $Salt, $knownVendors[$vendor], $vendor, $model, $n)) }) } }
                }
                if ($boards -gt 0) { & $add $knownVendors[$vendor] 'Medium' 'KnownVendor' $boards }
            }
            $pads = @($devices | Where-Object { [string]$_.Name -match 'game controller' -and [string]$_.DeviceID -notmatch 'IG_' -and [string]$_.Name -notmatch ($hints.Values -join '|') }).Count
            if ($pads -gt 0) { & $add 'OtherGamePad' 'Medium' 'WindowsDeviceClass' $pads }
        } catch { [void]$reasons.Add('DeviceListUnavailable') }
        if ($reasons.Count -eq 2) { $status = 'SourceUnavailable' }
    } catch {
        $found.Clear(); $status = 'SourceUnavailable'; [void]$reasons.Add('ProbeFailed')
    }
    $observations = @($found.ToArray() | Sort-Object DeviceClass, Basis)
    # $null = not checked (no salt, or the device list could not be read); an empty array = checked and none recognized.
    $prints = $null
    if ($Salt -and $status -eq 'Observed' -and $reasons -notcontains 'DeviceListUnavailable') { $prints = @($fingerprints.ToArray() | Sort-Object DeviceClass, Fingerprint) }
    $canonical = 'TpmLocalDetection|1|' + ((@($observations | ForEach-Object { '{0}/{1}/{2}/{3}' -f $_.DeviceClass, $_.Confidence, $_.Basis, $_.Count })) -join ';')
    $id = & $hash $canonical
    return [pscustomobject][ordered]@{
        ContractVersion = 'TpmControllerEvidence/v1'; EvidenceId = $id; EvidenceStatus = $status
        ProviderId = 'TpmLocalDetection'; ProviderVersion = '1'; SourceFamily = 'LocalWindowsDeviceClass'; EvidenceClass = 'LocalProbe'
        DeviceObservations = $observations; DeviceFingerprints = $prints
        ObservationTimeUtc = (Get-Date).ToUniversalTime().ToString('o'); InputArtifactFingerprint = $null
        ReasonCodes = @($reasons.ToArray()); RedactedFields = @(); SensitiveIdentifiersIncluded = $false; ReadOnly = $true
    }
}
# Read-only look at the key map LEDBlinky keeps for the arcade buttons (LEDBlinkyInputMap.xml): which key each control sends.
# It is a source of information only. It never writes, never starts LEDBlinky and never touches the lights. Any problem gives an
# empty result with a reason, and the player can still be asked instead.
function Get-TpmLedBlinkyKeyMap {
    param([string[]]$Root = @())
    $result = [ordered]@{ Found = $false; Reason = 'NotInstalled'; MapSHA256 = ''; Controls = @() }
    try {
        $mapPath = ''
        foreach ($folder in @(@($Root) + @('C:\LEDBlinky'))) {
            if ([string]::IsNullOrWhiteSpace($folder)) { continue }
            $candidate = Join-Path $folder 'LEDBlinkyInputMap.xml'
            if (Test-Path -LiteralPath $candidate -PathType Leaf) { $mapPath = $candidate; break }
        }
        if (-not $mapPath) { return [pscustomobject]$result }
        $settings = New-Object System.Xml.XmlReaderSettings
        $settings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
        $settings.XmlResolver = $null
        $reader = [System.Xml.XmlReader]::Create($mapPath, $settings)
        try { $xml = New-Object System.Xml.XmlDocument; $xml.XmlResolver = $null; $xml.Load($reader) } finally { $reader.Dispose() }
        $controls = New-Object System.Collections.Generic.List[object]
        $seen = @{}
        # A light is RGB (any color) when the map gives it red, green and blue ports; one port means a single-color light.
        $portTypes = @{}
        foreach ($port in @($xml.SelectNodes('//ledController/port'))) {
            $portLabel = [string]$port.GetAttribute('label')
            if (-not $portLabel) { continue }
            if (-not $portTypes.ContainsKey($portLabel)) { $portTypes[$portLabel] = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase) }
            [void]$portTypes[$portLabel].Add([string]$port.GetAttribute('type'))
        }
        foreach ($port in @($xml.SelectNodes('//ledController/port'))) {
            $label = [string]$port.GetAttribute('label')
            $codes = @(([string]$port.GetAttribute('inputCodes')).Split('|') | ForEach-Object { $_.Trim() } | Where-Object { $_ })
            if (-not $label -or $codes.Count -eq 0 -or $seen.ContainsKey($label)) { continue }
            $seen[$label] = $true
            $types = $portTypes[$label]
            $isRgb = ($types.Contains('R') -and $types.Contains('G') -and $types.Contains('B'))
            [void]$controls.Add([pscustomobject][ordered]@{ Control = $label; InputCodes = $codes; IsRgb = $isRgb })
        }
        $result.Found = ($controls.Count -gt 0)
        $result.Reason = if ($controls.Count -gt 0) { 'Read' } else { 'MapEmpty' }
        $result.MapSHA256 = (Get-FileHash -LiteralPath $mapPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant()
        $result.Controls = @($controls.ToArray())
    } catch {
        $result.Found = $false; $result.Reason = 'MapUnreadable'; $result.MapSHA256 = ''; $result.Controls = @()
    }
    return [pscustomobject]$result
}
function Get-TpmHardwareEnvironmentEvidence {
    param([switch]$RefreshDynamic, [string[]]$VolumePaths = @())
    $cpu = $null; $os = $null; $ram = $null; $gpus = @(); $battery = $null
    try { $cpu = Get-CimInstance Win32_Processor -ErrorAction Stop | Select-Object -First 1 } catch {}
    try { $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop } catch {}
    try { $ram = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop } catch {}
    try { $gpus = @(Get-CimInstance Win32_VideoController -ErrorAction Stop) } catch {}
    try { $battery = Get-CimInstance Win32_Battery -ErrorAction Stop | Select-Object -First 1 } catch {}
    $volumes = New-Object System.Collections.Generic.List[object]
    foreach ($path in $VolumePaths) {
        try {
            $root = [IO.Path]::GetPathRoot($path)
            $drive = Get-PSDrive -Name $root.TrimEnd('\').TrimEnd(':') -ErrorAction Stop
            [void]$volumes.Add([pscustomobject]@{ Path = $path; FreeBytes = [int64]$drive.Free; Confidence = 'KNOWN' })
        } catch {
            [void]$volumes.Add([pscustomobject]@{ Path = $path; FreeBytes = $null; Confidence = 'UNKNOWN' })
        }
    }
    return [pscustomobject]@{
        OSVersion = if ($os) { $os.Version } else { $null }; OSBuild = if ($os) { $os.BuildNumber } else { $null }; Architecture = $env:PROCESSOR_ARCHITECTURE
        CpuModel = if ($cpu) { $cpu.Name } else { $null }; PhysicalCoreCount = if ($cpu) { $cpu.NumberOfCores } else { $null }; LogicalProcessorCount = if ($cpu) { $cpu.NumberOfLogicalProcessors } else { $null }; CpuEvidenceConfidence = if ($cpu) { 'RELIABLE' } else { 'UNKNOWN' }
        Adapters = @($gpus | ForEach-Object { [pscustomobject]@{ AdapterIndex = $_.Index; Name = $_.Name; DriverVersion = $_.DriverVersion; DedicatedMemoryBytes = $_.AdapterRAM; Status = $_.Status } }); ActiveAdapterIndex = if ($gpus.Count -eq 1) { 0 } else { $null }; ActiveAdapterName = if ($gpus.Count -eq 1) { $gpus[0].Name } else { $null }; ActiveGpuConfidence = if ($gpus.Count -eq 1) { 'INFERRED' } else { 'UNKNOWN' }; ActiveGpuSelectionReason = if ($gpus.Count -eq 1) { 'only usable adapter enumerated' } else { 'target adapter cannot be established from shared evidence' }; MultiGpuAmbiguous = ($gpus.Count -gt 1)
        InstalledRamBytes = if ($ram) { [int64]$ram.TotalPhysicalMemory } else { $null }; AvailableRamBytes = if ($os) { [int64]$os.FreePhysicalMemory * 1KB } else { $null }; MemoryEvidenceConfidence = if ($ram -and $os) { 'RELIABLE' } else { 'UNKNOWN' }
        RenderWidth = if ($gpus.Count -eq 1) { $gpus[0].CurrentHorizontalResolution } else { $null }; RenderHeight = if ($gpus.Count -eq 1) { $gpus[0].CurrentVerticalResolution } else { $null }; ResolutionConfidence = if ($gpus.Count -eq 1 -and $gpus[0].CurrentHorizontalResolution) { 'INFERRED' } else { 'UNKNOWN' }; DisplayCount = $null; RefreshRate = if ($gpus.Count -eq 1) { $gpus[0].CurrentRefreshRate } else { $null }
        BatteryPowered = [bool]$battery; PowerSavingActive = if ($battery) { $battery.BatteryStatus -in @(1,4,5) } else { $null }; PowerEvidenceConfidence = if ($battery) { 'RELIABLE' } else { 'UNKNOWN' }
        Volumes = $volumes.ToArray()
        DynamicRefreshed = [bool]$RefreshDynamic; SensitiveIdentifiersIncluded = $false
    }
}

function Resolve-TpmReShadeEffectStack {
    param([string[]]$EffectIds)
    $requested = @($EffectIds | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    $catalog = @(Get-TpmReShadeEffectCatalog)
    $selected = New-Object System.Collections.Generic.List[object]
    $errors = New-Object System.Collections.Generic.List[string]
    foreach ($id in $requested) {
        $effectMatches = @($catalog | Where-Object EffectId -eq $id)
        if ($effectMatches.Count -eq 0) { [void]$errors.Add("Effect is not in the approved catalog: $id"); continue }
        $effect = $effectMatches[0]
        $selectedIds = @($selected | ForEach-Object { [string]$_.EffectId })
        if ($selectedIds -notcontains [string]$effect.EffectId) { [void]$selected.Add($effect) }
    }
    foreach ($effect in $selected) {
        foreach ($other in $selected) {
            if ($effect.EffectId -ne $other.EffectId -and ($effect.ConflictsWith -contains $other.EffectId)) {
                [void]$errors.Add("Effects conflict: $($effect.FriendlyName) and $($other.FriendlyName)")
            }
        }
    }
    $ordered = @($selected | Sort-Object { [array]::IndexOf($requested, $_.EffectId) })
    return [pscustomobject]@{
        Valid = ($errors.Count -eq 0)
        Effects = @($ordered)
        TechniqueOrder = @($ordered | ForEach-Object TechniqueName)
        Errors = @($errors | Sort-Object -Unique)
    }
}

function Resolve-ReShadeCustomPresetPath {
    param([string]$InputPath)
    if ([string]::IsNullOrWhiteSpace($InputPath)) { return $null }
    try {
        $candidate = $InputPath.Trim()
        if ([System.IO.Path]::GetExtension($candidate) -ine '.ini') { return $null }
        if (-not (Test-Path -LiteralPath $candidate -PathType Leaf)) { return $null }
        return $candidate
    } catch {
        return $null
    }
}

# A ReShade DLL the user placed by hand: the managed Assets\ReShade folder (where the tidy-up moves it) first,
# then the script folder (where it stays if the tidy-up was declined). Returns $null when neither has it.
function Get-TpmUserReShadeDll {
    param([Parameter(Mandatory)][string]$FileName)
    $dirs = @(Join-Path $PSScriptRoot 'ReShade')
    if ($script:TpmOwnedLayout) { $dirs = @((Join-Path $script:TpmOwnedLayout.Assets 'ReShade'), $dirs[0]) }
    foreach ($dir in $dirs) {
        $path = Join-Path $dir $FileName
        if (Test-Path -LiteralPath $path -PathType Leaf) { return $path }
    }
    return $null
}

function Invoke-ReShadeUpdateIfAvailable {
    param([string]$SourceDll, [string]$InstalledVersion)
    if ([string]::IsNullOrWhiteSpace($InstalledVersion)) { return [pscustomobject]@{ Updated = $false; SourceDll = $SourceDll } }
    $latest = Get-ReShadeLatestVersion
    if (-not $latest -or [version]$latest -le [version]$InstalledVersion) {
        return [pscustomobject]@{ Updated = $false; SourceDll = $SourceDll }
    }
    Write-Host '  ReShade update available' -ForegroundColor Yellow
    Write-Host ("  Installed: {0}" -f $InstalledVersion)
    Write-Host ("  Available: {0}" -f $latest)
    $choice = Read-TpmYesNo -Prompt '  [Y] Update now  [N] Keep current version  Choice, default Y' -Default 'Y'
    if ($choice -ne 'Y') { Write-Log ("ReShade update declined: installed={0}; available={1}" -f $InstalledVersion, $latest); return [pscustomobject]@{ Updated = $false; SourceDll = $SourceDll } }
    $url = Get-ReShadeSetupDownloadUrl -Version $latest
    if (-not $url) { Write-Host '  ReShade update could not be started safely; keeping the installed version.' -ForegroundColor Yellow; return [pscustomobject]@{ Updated = $false; SourceDll = $SourceDll } }
    $cacheDir = if($script:TpmOwnedLayout){Join-Path $script:TpmOwnedLayout.Assets 'ReShade'}else{Join-Path $PSScriptRoot 'ReShade'}
    $setupPath = Join-Path $cacheDir ("ReShade_Setup_{0}.exe" -f $latest)
    try {
        [void][IO.Directory]::CreateDirectory($cacheDir)
        if (-not (Invoke-TpmDownload -DownloadUrl $url -DestinationPath $setupPath -Label 'ReShadeSetup' -Version $latest)) { throw 'The official download did not complete.' }
        $signature = Test-ReShadeSetupTrustedSignature -Path $setupPath
        if (-not $signature.Trusted) { throw 'The downloaded installer did not pass the trusted ReShade signature check.' }
        try { Expand-ReShadeSelfExtractingArchive -SetupExePath $setupPath -DestDir $cacheDir }
        catch { if ($_.Exception.Message -notmatch 'CLEANUP FAILED AFTER VERIFIED PROMOTION') { throw }; Write-Log "ReShade update: files verified, temporary-file cleanup failed -- $($_.Exception.Message)" }
        $newDll = Join-Path $cacheDir 'ReShade64.dll'
        if (-not (Test-Path -LiteralPath $newDll -PathType Leaf)) { throw 'The updated 64-bit DLL was not found after extraction.' }
        Write-Host ("  ReShade {0} downloaded and verified." -f $latest) -ForegroundColor Green
        Write-Log ("ReShade update applied to setup source: installed={0}; available={1}" -f $InstalledVersion, $latest)
        return [pscustomobject]@{ Updated = $true; SourceDll = $newDll }
    } catch {
        Write-Host ("  ReShade update failed safely: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
        Write-Log ("ReShade update failed: {0}" -f $_.Exception.Message)
        return [pscustomobject]@{ Updated = $false; SourceDll = $SourceDll }
    }
}

function Resolve-ReShadeDllAcquisition {
    param(
        [string]$Choice,
        [string]$InputPath
    )

    if ($Choice -ne 'B') {
        return [pscustomobject]@{
            State  = 'Skipped'
            Path   = $null
            Reason = 'UserSkipped'
        }
    }
    if ([string]::IsNullOrWhiteSpace($InputPath)) {
        return [pscustomobject]@{
            State  = 'Invalid'
            Path   = $null
            Reason = 'FileMissing'
        }
    }
    # The folder that holds ReShade64.dll is as good as the file itself (typed paths may carry quotes).
    $InputPath = $InputPath.Trim().Trim('"')
    if (Test-Path -LiteralPath $InputPath -PathType Container) { $InputPath = Join-Path $InputPath 'ReShade64.dll' }
    if (-not (Test-Path -LiteralPath $InputPath -PathType Leaf)) {
        return [pscustomobject]@{
            State  = 'Invalid'
            Path   = $null
            Reason = 'FileMissing'
        }
    }
    if ([System.IO.Path]::GetExtension($InputPath).ToLowerInvariant() -ne '.dll') {
        return [pscustomobject]@{
            State  = 'Invalid'
            Path   = $null
            Reason = 'FileType'
        }
    }
    return [pscustomobject]@{
        State  = 'Acquired'
        Path   = $InputPath
        Reason = $null
    }
}

# The "get the ReShade DLL" step shared by the main-menu ReShade setup and the first-run ReShade offer: download it from
# reshade.me, or use a copy the user already has (the DLL, or the folder that holds ReShade64.dll). Returns State:
# Acquired (Path is set), Invalid (Reason FileType or FileMissing; the plain message is already on screen) or Cancelled
# (nothing was used or changed). The caller decides what happens next.
function Request-TpmReShadeSourceDll {
    $rsSourceDll = $null
    Write-Host "  ReShade 64-bit DLL not found." -ForegroundColor Yellow
    Write-Host "    D) Download automatically from reshade.me"
    Write-Host "    B) Browse for a file I already have"
    Write-Host "    N) Skip"
    $rsGetChoice = Read-TpmChoice -Prompt "  Choice (D/B/N)" -Choices @('D', 'B', 'N')
    $rsGotDll    = $false
    while (-not $rsGotDll -and $rsGetChoice -eq 'D') {
        Write-Host "  Checking reshade.me for the latest version..." -ForegroundColor Cyan
        $rsLatestVer = Get-ReShadeLatestVersion
        if (-not $rsLatestVer) {
            Write-Host "  TeknoParrot Manager could not reach reshade.me. Choose R to retry automatically, B for the advanced existing-file fallback, or N to cancel." -ForegroundColor Red
            Write-Log "ReShade auto-download: aborted -- could not determine latest version."
        } else {
            $rsSetupUrl = Get-ReShadeSetupDownloadUrl -Version $rsLatestVer
            if (-not $rsSetupUrl) {
                Write-Host "  Could not build a safe download URL -- aborted." -ForegroundColor Red
            } else {
                $rsCacheDir  = if ($script:TpmOwnedLayout) { Join-Path $script:TpmOwnedLayout.Assets 'ReShade' } else { Join-Path $PSScriptRoot 'ReShade' }
                [void][System.IO.Directory]::CreateDirectory($rsCacheDir)
                $rsSetupPath = Join-Path $rsCacheDir "ReShade_Setup_$rsLatestVer.exe"
                Write-Host "  Downloading ReShade $rsLatestVer installer..." -ForegroundColor Cyan
                if (Invoke-TpmDownload -DownloadUrl $rsSetupUrl -DestinationPath $rsSetupPath -Label 'ReShadeSetup' -Version $rsLatestVer) {
                    Write-Host ''
                    Write-Host "  Verifying installer signature..." -ForegroundColor Cyan
                    $rsSig = Test-ReShadeSetupTrustedSignature -Path $rsSetupPath
                    if (-not $rsSig.Trusted) {
                        Write-Host ("  Signer     : {0}" -f $rsSig.Signer) -ForegroundColor DarkGray
                        Write-Host ("  Thumbprint : {0}" -f $rsSig.Thumbprint) -ForegroundColor DarkGray
                        Write-Host "  SECURITY: Signature does not match the trusted ReShade certificate -- refusing to use this installer." -ForegroundColor Red
                        Write-Host "  The advanced existing-file fallback is available only if you already have a trusted official file." -ForegroundColor Yellow
                        Write-Log ("ReShade auto-download: SECURITY -- signature not trusted. Subject='{0}' Thumbprint={1}" -f $rsSig.Signer, $rsSig.Thumbprint)
                        try { Remove-Item -LiteralPath $rsSetupPath -Force -ErrorAction SilentlyContinue } catch {}
                    } else {
                        $script:TpmReShadeInstallerEvidence = [pscustomobject]@{ Signer = [string]$rsSig.Signer; Thumbprint = [string]$rsSig.Thumbprint }
                        Write-Host "  Signature trusted. Extracting ReShade64.dll..." -ForegroundColor Cyan
                        Write-Host ''
                        try {
                            # The files were promoted and verified; only a leftover temporary folder could not be removed.
                            try { Expand-ReShadeSelfExtractingArchive -SetupExePath $rsSetupPath -DestDir $rsCacheDir }
                            catch { if ($_.Exception.Message -notmatch 'CLEANUP FAILED AFTER VERIFIED PROMOTION') { throw }; Write-Log "ReShade auto-download: files verified, temporary-file cleanup failed -- $($_.Exception.Message)" }
                            $rsSourceDll = Join-Path $rsCacheDir "ReShade64.dll"
                            $rsGotDll    = $true
                            Write-Host ''
                            Write-Host "  Downloaded and extracted successfully." -ForegroundColor Green
                            Write-Log "ReShade auto-download: extracted $rsLatestVer to $rsCacheDir"
                        } catch {
                            Write-Host ("  Extraction failed: {0}" -f $_) -ForegroundColor Red
                            Write-Log "ReShade auto-download: extraction failed -- $_"
                        }
                    }
                } else {
                    Write-Host "  The automatic ReShade download did not finish. Choose R to retry, B for the advanced fallback, or N to cancel." -ForegroundColor Red
                }
            }
        }
        if (-not $rsGotDll) {
            Write-Host '  Automatic ReShade download did not finish.' -ForegroundColor Red
            $rsRetryChoice = Read-TpmChoice -Prompt '  R Retry automatic download / B Use an existing file (advanced) / N Cancel' -Choices @('R', 'B', 'N')
            if ($rsRetryChoice -eq 'R') { $rsGetChoice = 'D'; continue }
            $rsGetChoice = $rsRetryChoice
        }
    }
    if (-not $rsGotDll) {
        $inp = $null
        if ($rsGetChoice -eq 'B') {
            Write-Host ""
            Write-Host "    Type the full path to the DLL file, or to the folder that holds it:" -ForegroundColor White
            Write-Host ""
            $inp = Read-PathWithBrowse "  Path to ReShade64.dll or its folder (or press Enter to cancel)" -Mode File -FileFilter "DLL files (*.dll)|*.dll|All files (*.*)|*.*"
        }
        $rsAcquisition = Resolve-ReShadeDllAcquisition -Choice $rsGetChoice -InputPath $inp
        if ($rsAcquisition.State -eq 'Invalid') {
            if ($rsAcquisition.Reason -eq 'FileType') {
                Write-Host "  That file does not appear to be a DLL. Canceled." -ForegroundColor Red
                Write-Log "ReShade setup: aborted -- file is not a .dll."
            } else {
                Write-Host "  File not found. ReShade setup canceled." -ForegroundColor Red
                Write-Log "ReShade setup: aborted -- DLL not found."
            }
            return [pscustomobject]@{ State = 'Invalid'; Path = $null; Reason = [string]$rsAcquisition.Reason }
        }
        if ($rsAcquisition.State -eq 'Acquired') {
            $rsSourceDll = $rsAcquisition.Path
            $rsGotDll    = $true
        }
    }
    if ($rsGotDll) { return [pscustomobject]@{ State = 'Acquired'; Path = $rsSourceDll; Reason = $null } }
    return [pscustomobject]@{ State = 'Cancelled'; Path = $null; Reason = 'UserCancelledOrDownloadFailed' }
}

# The "get the dgVoodoo2 DLL folder" step shared by the main-menu dgVoodoo2 setup and the first-run dgVoodoo2 offer: download
# the official release, or use a folder the user already has. Returns State: Acquired (Path is the folder),
# CancelledAtFolder (the user left the folder prompt empty) or Cancelled (the download did not work and the user stopped).
function Request-TpmDgVoodoo2SourceDir {
    $dgSourceDir = $null
    Write-Host "  dgVoodoo2 DLL folder not found." -ForegroundColor Yellow
    Write-Host "    D) Download automatically from the official GitHub release"
    Write-Host "    B) Browse for a folder I already have"
    Write-Host "    N) Skip"
    $dgGetChoice = Read-TpmChoice -Prompt "  Choice (D/B/N)" -Choices @('D', 'B', 'N')
    $dgGotDir    = $false
    while (-not $dgGotDir -and $dgGetChoice -eq 'D') {
        Write-Host "  Checking the official GitHub release for the latest dgVoodoo2..." -ForegroundColor Cyan
        $dgRel = Get-DgVoodoo2LatestRelease
        if (-not $dgRel) {
            Write-Host "  TeknoParrot Manager could not reach the official dgVoodoo2 release. Choose R to retry automatically, B for the advanced existing-folder fallback, or N to cancel." -ForegroundColor Red
            Write-Log "dgVoodoo2 auto-download: aborted -- release query failed."
        } else {
            Write-Host ("  Found: {0}  ({1} MB)" -f $dgRel.FileName, ([Math]::Round($dgRel.SizeBytes / 1MB, 1))) -ForegroundColor Cyan
            $dgCacheDir = if ($script:TpmOwnedLayout) { Join-Path $script:TpmOwnedLayout.Assets 'dgVoodoo2' } else { Join-Path $PSScriptRoot "dgVoodoo2" }
            $dgZipPath  = Join-Path $env:TEMP $dgRel.FileName
            if (Invoke-TpmDownload -DownloadUrl $dgRel.DownloadUrl -DestinationPath $dgZipPath -ExpectedBytes $dgRel.SizeBytes -Label 'dgVoodoo2' -Version $dgRel.Version -ExpectedSha256 $dgRel.ExpectedSha256) {
                try {
                    # The files were promoted and verified; only a leftover temporary folder could not be removed.
                    try { Expand-DgVoodoo2Zip -ZipPath $dgZipPath -DestDir $dgCacheDir }
                    catch { if ($_.Exception.Message -notmatch 'CLEANUP FAILED AFTER VERIFIED PROMOTION') { throw }; Write-Log "dgVoodoo2 auto-download: files verified, temporary-file cleanup failed -- $($_.Exception.Message)" }
                    $dgSourceDir = $dgCacheDir
                    $dgGotDir    = $true
                    Write-Host "  Downloaded and extracted successfully." -ForegroundColor Green
                    Write-Log "dgVoodoo2 auto-download: extracted $($dgRel.Version) to $dgCacheDir"
                } catch {
                    Write-Host ("  Extraction failed: {0}" -f $_) -ForegroundColor Red
                    Write-Log "dgVoodoo2 auto-download: extraction failed -- $_"
                } finally {
                    try { Remove-Item -LiteralPath $dgZipPath -Force -ErrorAction SilentlyContinue } catch {}
                }
            } else {
                Write-Host "  The automatic dgVoodoo2 download did not finish. Choose R to retry, B for the advanced fallback, or N to cancel." -ForegroundColor Red
            }
        }
        if (-not $dgGotDir) {
            $dgRetryChoice = Read-TpmChoice -Prompt '  R Retry automatic download / B Use an existing folder (advanced) / N Cancel' -Choices @('R', 'B', 'N')
            if ($dgRetryChoice -eq 'R') { $dgGetChoice = 'D'; continue }
            $dgGetChoice = $dgRetryChoice
        }
    }
    if (-not $dgGotDir -and $dgGetChoice -eq 'B') {
        Write-Host ""
        Write-Host "    Enter the full path to a folder that already contains those files:" -ForegroundColor White
        Write-Host ""
        while (-not $dgGotDir) {
            $inp = Read-PathWithBrowse "  Path to dgVoodoo2 folder (or press Enter to cancel)"
            if ([string]::IsNullOrWhiteSpace($inp)) { break }
            $inp = $inp.Trim().Trim('"')
            if (Test-TpmDgVoodoo2SourceFolder -Path $inp) { $dgSourceDir = $inp; $dgGotDir = $true; break }
            Write-Host '  That folder was not found or contains none of D3D8.dll, DDraw.dll, D3DImm.dll, Glide2x.dll, Glide3x.dll. Enter another folder, or press Enter to cancel.' -ForegroundColor Yellow
            Write-Log ("dgVoodoo2 setup: rejected source folder '{0}' (missing or no dgVoodoo2 DLLs)." -f $inp)
        }
        if (-not $dgGotDir) { return [pscustomobject]@{ State = 'CancelledAtFolder'; Path = $null } }
    }
    if ($dgGotDir) { return [pscustomobject]@{ State = 'Acquired'; Path = $dgSourceDir } }
    return [pscustomobject]@{ State = 'Cancelled'; Path = $null }
}

# Thin console seams so the waiting input loop can be driven by tests without a real console.
function Test-TpmConsoleInputRedirected { return [Console]::IsInputRedirected }
function Test-TpmConsoleKeyAvailable { return [Console]::KeyAvailable }
function Read-TpmConsoleKey { return [Console]::ReadKey($true) }
# Differs from Write-TpmText: raw text with no wrapping, indent or line end, so the caller places every character itself.
function Write-TpmConsoleText {
    param([AllowEmptyString()][string]$Text, [string]$Color = '')
    if ($Color) { Write-Host $Text -NoNewline -ForegroundColor $Color } else { Write-Host $Text -NoNewline }
}

# Waits for a line of input. While waiting, DoEvents keeps the preview window responsive and -OnIdle (polled each cycle) may return a
# one-line notice, for example that the preview selection changed. The notice is printed on its own line and the prompt is redrawn
# with the partially typed text intact; the typed buffer and Enter handling are never altered by it.
function Read-TpmReShadeTerminalInput {
    param(
        [string]$Prompt,
        [bool]$PumpPreviewMessages,
        [bool]$PollConsoleResize = $false,
        [scriptblock]$OnIdle = $null,
        [scriptblock]$OnUpdate = $null,
        [scriptblock]$OnFallback = $null
    )
    if (-not $PumpPreviewMessages -and -not $PollConsoleResize) { return Read-HostSafe $Prompt }
    try {
        if (Test-TpmConsoleInputRedirected) { return Read-HostSafe $Prompt }
    } catch {
        return Read-HostSafe $Prompt
    }
    try {
        if (Get-Command -Name Suspend-TpmProgressLine -ErrorAction SilentlyContinue) { Suspend-TpmProgressLine }
    Write-TpmConsoleText ($Prompt + ': ')
    $buffer = New-Object System.Text.StringBuilder
    while ($true) {
        try {
            while (Test-TpmConsoleKeyAvailable) {
                $keyInfo = Read-TpmConsoleKey
                if ($keyInfo.Key -eq [ConsoleKey]::Enter) {
                    Write-TpmConsoleText "`n"
                    return $buffer.ToString()
                }
                if ($keyInfo.Key -eq [ConsoleKey]::Backspace) {
                    if ($buffer.Length -gt 0) {
                        [void]$buffer.Remove($buffer.Length - 1, 1)
                        Write-TpmConsoleText "`b `b"
                    }
                    continue
                }
                if (-not [char]::IsControl($keyInfo.KeyChar)) {
                    [void]$buffer.Append($keyInfo.KeyChar)
                    Write-TpmConsoleText ([string]$keyInfo.KeyChar)
                }
            }
        } catch {
            Write-TpmConsoleText "`n"
            return Read-HostSafe $Prompt
        }
        if ($PumpPreviewMessages) { try { [Windows.Forms.Application]::DoEvents() } catch {} }
        if ($OnIdle) {
            $change = $null
            try { $change = & $OnIdle } catch { Write-Log ("ReShade terminal idle poll failed -- {0}" -f $_.Exception.Message) }
            if ($null -ne $change) {
                $notice = if ($change -is [string]) { [string]$change } else { [string]$change.Notice }
                # 1) try to update the displayed values in place (no new lines) or, after a console resize, rebuild the layout; the callback restores the cursor to the end of the input
                $updated = $false
                if ($OnUpdate -and $change -isnot [string]) {
                    try { $updated = [bool](& $OnUpdate $change $Prompt $buffer.Length $buffer.ToString()) } catch { Write-Log ("ReShade terminal in-place update failed -- {0}" -f $_.Exception.Message); $updated = $false }
                }
                # 2) otherwise announce on its own line and redraw the prompt with the typed text intact
                if (-not $updated -and -not [string]::IsNullOrWhiteSpace($notice)) {
                    Clear-TpmReShadePromptRows -Prompt $Prompt -Length ($Prompt.Length + 2 + $buffer.Length)
                    Write-TpmConsoleText ($notice + "`n")
                    Write-TpmConsoleText ($Prompt + ': ' + $buffer.ToString())
                    if ($OnFallback) { try { & $OnFallback $notice } catch { Write-Log ("ReShade terminal fallback bookkeeping failed -- {0}" -f $_.Exception.Message) } }
                }
            }
        }
        Start-Sleep -Milliseconds 25
    }
    } finally {
        if (Get-Command -Name Resume-TpmProgressLine -ErrorAction SilentlyContinue) { Resume-TpmProgressLine }
    }
}

function Sync-TpmReShadeGallerySelection {
    param(
        [object]$Session,
        [Parameter(Mandatory)][string]$ProfileId
    )
    if (-not $Session) { return $false }
    $wasUpdating = [bool]$Session['ProfileSelectorUpdating']
    try {
        if (-not [bool]$Session['Initialized'] -or [bool]$Session['Closed'] -or -not [bool]$Session['PreviewEnabled']) { return $false }
        $canonicalProfile = @($Session['Profiles'] | Where-Object { [string]$_.ProfileId -eq $ProfileId })[0]
        if (-not $canonicalProfile) { throw ("Gallery profile '{0}' is not present." -f $ProfileId) }
        $Session['SelectedProfileId'] = [string]$canonicalProfile.ProfileId
        $selector = $Session['ProfileSelector']
        if ($selector) {
            $selectorRows = @(Get-TpmReShadeGallerySelectorRows -Session $Session)
            $selectorIndex = Get-TpmReShadeProfileSelectorIndex -Rows $selectorRows -ProfileId ([string]$canonicalProfile.ProfileId)
            if ($selectorIndex -lt 0) { throw ("Gallery selector does not contain profile '{0}'." -f $canonicalProfile.ProfileId) }
            # Suppress only the echo of this programmatic assignment. The guard
            # must not stay set across refresh/DoEvents or a queued user choice
            # would be dropped.
            $Session['ProfileSelectorUpdating'] = $true
            try { $selector.SelectedIndex = $selectorIndex }
            finally { $Session['ProfileSelectorUpdating'] = $wasUpdating }
            $Session['ProfileSelectorLastValidIndex'] = $selectorIndex
        }
        if (-not (Invoke-TpmReShadeGalleryRefreshSafe -State $Session -Refresh $Session['Refresh'] -Stage 'profile-selection-sync')) { return $false }
        try { [Windows.Forms.Application]::DoEvents() } catch {}
        return $true
    } catch {
        [void](Set-TpmReShadeGalleryPreviewFailed -State $Session -Stage 'profile-selection-sync' -ErrorRecord $_)
        return $false
    }
}

function Get-TpmGameDisplayLabel {
    param([Parameter(Mandatory)][string]$ProfilePath, [Parameter(Mandatory)][string]$Fallback)
    try {
        $doc = Read-Xml $ProfilePath
        $name = if ($doc.GameProfile -and $doc.GameProfile.GameName) { ([string]$doc.GameProfile.GameName).Trim() } else { '' }
        if (-not [string]::IsNullOrWhiteSpace($name)) { return $name }
    } catch {}
    return $Fallback
}

function Get-PostgresProfileDisplayMetadata {
    param([Parameter(Mandatory)][string]$ProfilePath)
    $profileKey = [System.IO.Path]::GetFileNameWithoutExtension($ProfilePath)
    $displayName = Get-TpmGameDisplayLabel -ProfilePath $ProfilePath -Fallback ' '
    if ([string]::IsNullOrWhiteSpace($displayName) -and -not [string]::IsNullOrWhiteSpace([string]$script:tpRoot)) {
        $canonicalProfile = Join-Path (Join-Path $script:tpRoot 'GameProfiles') ($profileKey + '.xml')
        if (Test-Path -LiteralPath $canonicalProfile -PathType Leaf) {
            $displayName = Get-TpmGameDisplayLabel -ProfilePath $canonicalProfile -Fallback ' '
        }
    }
    $datIndexVariable = Get-Variable -Name datIndex -Scope Script -ErrorAction SilentlyContinue
    if ([string]::IsNullOrWhiteSpace($displayName) -and $datIndexVariable -and $datIndexVariable.Value) {
        $datNames = @($datIndexVariable.Value.Values |
            Where-Object { [string]$_.ProfileCode -eq $profileKey -and -not [string]::IsNullOrWhiteSpace([string]$_.OriginalName) } |
            ForEach-Object { ([string]$_.OriginalName).Trim() } |
            Sort-Object -Unique)
        if ($datNames.Count -eq 1) { $displayName = [string]$datNames[0] }
    }
    $hasAuthoritativeTitle = -not [string]::IsNullOrWhiteSpace($displayName)
    if (-not $hasAuthoritativeTitle) { $displayName = 'Unknown game title -- see Details' }
    return [pscustomobject]@{
        DisplayName = $displayName
        ProfileKey = $profileKey
        HasAuthoritativeTitle = $hasAuthoritativeTitle
    }
}

function Get-TpmReShadeGameLabel {
    param([Parameter(Mandatory)][string]$ProfilePath, [string]$Fallback = '')
    try {
        $doc = Read-Xml $ProfilePath
        $name = if ($doc.GameProfile -and $doc.GameProfile.GameName) { ([string]$doc.GameProfile.GameName).Trim() } else { '' }
        if (-not [string]::IsNullOrWhiteSpace($name)) { return $name }
    } catch {}
    if (-not [string]::IsNullOrWhiteSpace($Fallback)) { return $Fallback }
    return [IO.Path]::GetFileNameWithoutExtension($ProfilePath)
}


function Get-TpmReShadeProfileTextField {
    param($Entry, [string]$Name)
    if ($null -ne $Entry -and $Entry.PSObject.Properties[$Name]) { return [string]$Entry.PSObject.Properties[$Name].Value }
    return ''
}

function Test-TpmReShadeProfileRequiresHdr {
    param($Entry)
    return ($null -ne $Entry -and $Entry.PSObject.Properties['RequiresHdr'] -and [bool]$Entry.RequiresHdr)
}

# "Friendly Name [Technical shader]"; Original and test fixtures without a technical name show the friendly name only.
function Get-TpmReShadeProfileDisplayLabel {
    param($Entry)
    $technical = Get-TpmReShadeProfileTextField -Entry $Entry -Name 'TechnicalName'
    if ([string]::IsNullOrWhiteSpace($technical)) { return [string]$Entry.FriendlyName }
    return ('{0} [{1}]' -f $Entry.FriendlyName, $technical)
}

# FIX64 (owner screenshot of menu 5): the ReShade setup screens ran together without spacing and said the same thing twice. The helpers
# below build the short plain screen text; every technical fact stays in the log and behind the chooser's [D] Details.

# Characters per row the ReShade screens wrap to: the live console width minus one, or 0 when the width cannot be read (one row, no wrapping).
function Get-TpmReShadeScreenTextWidth {
    try {
        $metrics = Get-TpmConsoleMetrics
        if ($metrics -and [int]$metrics.Width -gt 1) { return (Get-TpmReShadeConsoleTextWidth -Metrics $metrics) }
    } catch {
        Write-Verbose ('ReShade screen width unavailable -- ' + $_.Exception.Message)
    }
    return 0
}

# Word-wraps Text into rows of at most Width characters. FirstPrefix starts the first row and HangPrefix every later row (a hanging indent).
# A word longer than the room (a SHA-256, a path) is broken at the room instead of running past the console width. Width 0 (unknown) keeps
# one row with the text unchanged.
function Get-TpmReShadeHangingRows {
    param([AllowEmptyString()][string]$Text = '', [int]$Width = 0, [string]$FirstPrefix = '', [string]$HangPrefix = '')
    $rows = New-Object System.Collections.Generic.List[string]
    if ($Width -le 0) {
        [void]$rows.Add($FirstPrefix + $Text)
        return @($rows.ToArray())
    }
    $prefix = $FirstPrefix
    $room = [Math]::Max(8, $Width - $FirstPrefix.Length)
    $hangRoom = [Math]::Max(8, $Width - $HangPrefix.Length)
    $current = ''
    foreach ($word in @($Text -split '\s+' | Where-Object { $_ })) {
        if ($current.Length -gt 0 -and ($current.Length + 1 + $word.Length) -le $room) {
            $current = $current + ' ' + $word
            continue
        }
        if ($current.Length -gt 0) {
            [void]$rows.Add($prefix + $current)
            $prefix = $HangPrefix
            $room = $hangRoom
            $current = ''
        }
        while ($word.Length -gt $room) {
            [void]$rows.Add($prefix + $word.Substring(0, $room))
            $word = $word.Substring($room)
            $prefix = $HangPrefix
            $room = $hangRoom
        }
        $current = $word
    }
    if ($current.Length -gt 0 -or $rows.Count -eq 0) { [void]$rows.Add(($prefix + $current).TrimEnd()) }
    return @($rows.ToArray())
}

# One sentence on the ReShade screen, wrapped to the console width (Get-TpmReShadeScreenTextWidth) in one color.
# Differs from Write-TpmText: it uses the ReShade console metrics, which the chooser and its tests also use, and breaks a word that is too long.
function Write-TpmReShadeWrappedText {
    param([Parameter(Mandatory)][string]$Text, [Parameter(Mandatory)][string]$Color, [string]$FirstPrefix = '  ', [string]$HangPrefix = '  ')
    foreach ($row in @(Get-TpmReShadeHangingRows -Text $Text -Width (Get-TpmReShadeScreenTextWidth) -FirstPrefix $FirstPrefix -HangPrefix $HangPrefix)) { Write-Host $row -ForegroundColor $Color }
}

# Version, Authenticode signature status and SHA-256 of one ReShade DLL, logged the way the setup always logged them. A path that is empty
# or missing gives Present = $false.
function Get-TpmReShadeDllCheck {
    param([string]$Path, [Parameter(Mandatory)][string]$Label)
    $check = [pscustomobject]@{ Label = $Label; Present = $false; Version = ''; Status = ''; Signer = ''; Thumbprint = ''; Sha256 = '' }
    if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)) { return $check }
    $check.Present = $true
    try {
        $info = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($Path)
        $check.Version = "$($info.FileMajorPart).$($info.FileMinorPart).$($info.FileBuildPart)"
    } catch {
        $check.Version = ''
    }
    $signature = Test-ReShadeDllSignature -Path $Path
    $check.Status = [string]$signature.Status
    $check.Signer = Get-TpmReShadeProfileTextField -Entry $signature -Name 'Signer'
    $check.Thumbprint = Get-TpmReShadeProfileTextField -Entry $signature -Name 'Thumbprint'
    try {
        $check.Sha256 = [string](Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash
    } catch {
        $check.Sha256 = ''
    }
    Write-Log ("ReShade ({0}): signature={1} signer='{2}' thumbprint={3} sha256={4}" -f $Label, $check.Status, $check.Signer, $check.Thumbprint, $check.Sha256)
    return $check
}

# What the setup knows about the installer it downloaded in this run (signer and thumbprint of a verified signature), or $null.
function Get-TpmReShadeInstallerEvidence {
    $variable = Get-Variable -Name TpmReShadeInstallerEvidence -Scope Script -ErrorAction SilentlyContinue
    if ($variable) { return $variable.Value }
    return $null
}

# The short screen notice for the DLL: one sentence for the version and the signature, and a pointer to [D] Details. Line records
# (Text, Color), wrapped for TextWidth.
function Get-TpmReShadeDllNoticeLines {
    param([object[]]$Checks = @(), [int]$TextWidth = 0)
    $present = @($Checks | Where-Object { $_ -and $_.Present })
    if ($present.Count -eq 0) { return @() }
    $version = [string]$present[0].Version
    $ready = if ($version) { 'ReShade {0} is ready to use.' -f $version } else { 'ReShade is ready to use.' }
    $unverified = @($present | Where-Object { [string]$_.Status -ne 'Valid' })
    # UnknownError and NotSigned are what Windows reports for the ReShade DLL in the usual case (a publisher it does not know). Any other status
    # (for example HashMismatch or NotTrusted) can mean the file was changed, so it is shown by name and is not called common.
    $unusualStatuses = @($unverified | Where-Object { [string]$_.Status -notin @('UnknownError', 'NotSigned') } | ForEach-Object { if ([string]$_.Status) { [string]$_.Status } else { 'unknown' } } | Select-Object -Unique)
    if ($unverified.Count -eq 0) {
        $text = $ready + ' Windows confirmed the DLL signature.'
        $color = 'DarkGray'
    } elseif ($unusualStatuses.Count -gt 0) {
        $text = $ready + (' Windows found a problem with the DLL signature ({0}).' -f ($unusualStatuses -join ', '))
        $color = 'Yellow'
    } else {
        $text = $ready + ' Windows could not confirm who published the DLL, which is common for ReShade.'
        $color = 'Yellow'
    }
    $lines = New-Object System.Collections.Generic.List[object]
    foreach ($row in @(Get-TpmReShadeHangingRows -Text $text -Width $TextWidth -FirstPrefix '  ' -HangPrefix '  ')) {
        [void]$lines.Add([pscustomobject]@{ Text = [string]$row; Color = $color })
    }
    foreach ($row in @(Get-TpmReShadeHangingRows -Text 'Choose [D] below for the signature status, SHA-256 and thumbprint.' -Width $TextWidth -FirstPrefix '  ' -HangPrefix '  ')) {
        [void]$lines.Add([pscustomobject]@{ Text = [string]$row; Color = 'DarkGray' })
    }
    return @($lines.ToArray())
}

# The [D] Details block for the DLLs: one short block per DLL (heading with the version, then Signature / Signed by / Thumbprint / SHA-256),
# the installer's signer when it was downloaded in this run, and the common notes once at the bottom. Line records (Text, Color), wrapped for TextWidth.
function Get-TpmReShadeDllDetailLines {
    param([object[]]$Checks = @(), $Installer = $null, [int]$TextWidth = 0)
    $items = @($Checks | Where-Object { $_ })
    if ($items.Count -eq 0 -and -not $Installer) { return @() }
    $lines = New-Object System.Collections.Generic.List[object]
    $addRows = {
        param($text, $first, $hang, $color)
        foreach ($row in @(Get-TpmReShadeHangingRows -Text $text -Width $TextWidth -FirstPrefix $first -HangPrefix $hang)) {
            [void]$lines.Add([pscustomobject]@{ Text = [string]$row; Color = [string]$color })
        }
    }
    $addBlank = { [void]$lines.Add([pscustomobject]@{ Text = ''; Color = 'Gray' }) }
    $detailFirst = '      '
    $detailHang = '          '
    & $addRows 'ReShade files' '  ' '  ' 'Cyan'
    $anyUnverified = $false
    foreach ($check in $items) {
        & $addBlank
        if (-not [bool]$check.Present) {
            & $addRows ('{0} DLL' -f $check.Label) '    ' '        ' 'White'
            & $addRows 'Not found' $detailFirst $detailHang 'DarkGray'
            continue
        }
        & $addRows ('{0} DLL -- version {1}' -f $check.Label, $(if ($check.Version) { [string]$check.Version } else { 'unknown' })) '    ' '        ' 'White'
        if ([string]$check.Status -eq 'Valid') {
            & $addRows 'Signature: valid -- Windows confirmed it' $detailFirst $detailHang 'DarkGray'
        } else {
            $anyUnverified = $true
            & $addRows ('Signature: not verified by Windows (status {0})' -f $(if ($check.Status) { [string]$check.Status } else { 'unknown' })) $detailFirst $detailHang 'Yellow'
        }
        & $addRows ('Signed by: {0}' -f $(if ($check.Signer) { [string]$check.Signer } else { '(none)' })) $detailFirst $detailHang 'DarkGray'
        & $addRows ('Thumbprint: {0}' -f $(if ($check.Thumbprint) { [string]$check.Thumbprint } else { '(none)' })) $detailFirst $detailHang 'DarkGray'
        & $addRows ('SHA-256: {0}' -f $(if ($check.Sha256) { [string]$check.Sha256 } else { 'could not be calculated' })) $detailFirst $detailHang 'DarkGray'
    }
    if ($Installer) {
        & $addBlank
        & $addRows 'Installer download' '    ' '        ' 'White'
        & $addRows ('Signed by: {0}' -f [string]$Installer.Signer) $detailFirst $detailHang 'DarkGray'
        & $addRows ('Thumbprint: {0}' -f [string]$Installer.Thumbprint) $detailFirst $detailHang 'DarkGray'
        & $addRows 'Result: matches the trusted ReShade certificate' $detailFirst $detailHang 'DarkGray'
    }
    if ($items.Count -gt 0) {
        & $addBlank
        if ($anyUnverified) {
            & $addRows 'What it means: A signature Windows cannot verify does not automatically mean the file is broken; TeknoParrot Manager can continue with this user-supplied DLL.' '  ' '      ' 'DarkCyan'
            & $addRows 'What to do: Stop and replace the DLL if you do not trust where it came from or its SHA-256.' '  ' '      ' 'Yellow'
        } else {
            & $addRows 'What it means: Windows confirmed the signature. TeknoParrot Manager can use this supplied DLL.' '  ' '      ' 'DarkCyan'
        }
        & $addRows 'The same signature status and SHA-256 are recorded in the log.' '  ' '  ' 'DarkGray'
    }
    return @($lines.ToArray())
}

# Numbered menu with the four group headings and continuous numbering. HDR choices that the display cannot use right now are listed
# without a number so they can never be selected by number. The menu is produced as line records (text, color, owning profile) so the
# same records can be printed and later addressed for an in-place update of the selection marker. FIX64: one blank row separates the
# entries, and a text longer than the console wraps under its entry with a hanging indent (-TextWidth is the characters per row; 0 keeps
# one row per text). Only the first row of an entry's title is the Title record that carries the selection marker.
function Get-TpmReShadeTerminalMenuLines {
    param([object[]]$Selectable = @(), [object[]]$HdrUnavailable = @(), $Selected = $null, [string]$HdrReason = '', [int]$TextWidth = 0)
    $lines = New-Object System.Collections.Generic.List[object]
    $add = { param($text, $color, $profileId = '', $kind = 'Text') [void]$lines.Add([pscustomobject]@{ Text = [string]$text; Color = [string]$color; ProfileId = [string]$profileId; Kind = [string]$kind }) }
    $addWrapped = {
        param($text, $color, $first, $hang, $profileId = '', $kind = 'Text')
        $rowProfile = $profileId
        $rowKind = $kind
        foreach ($row in @(Get-TpmReShadeHangingRows -Text $text -Width $TextWidth -FirstPrefix $first -HangPrefix $hang)) {
            & $add $row $color $rowProfile $rowKind
            $rowProfile = ''
            $rowKind = 'Text'
        }
    }
    $number = 0
    $lastGroup = ''
    foreach ($entry in @($Selectable)) {
        $groupLabel = Get-TpmReShadeProfileGroupLabel -Group (Get-TpmReShadeProfileTextField -Entry $entry -Name 'Group')
        if ($groupLabel -and $groupLabel -ne $lastGroup) {
            & $add '' 'Gray'
            & $add ('  {0}' -f $groupLabel) 'Cyan'
            $lastGroup = $groupLabel
        } elseif ($number -gt 0) {
            & $add '' 'Gray'
        }
        $number++
        $marker = if ($Selected -and [string]$Selected.ProfileId -eq [string]$entry.ProfileId) { '*' } else { ' ' }
        $titlePrefix = Get-TpmReShadeMenuTitlePrefix -Number $number -Marker $marker
        & $addWrapped (Get-TpmReShadeProfileDisplayLabel -Entry $entry) $(if ($marker -eq '*') { 'Yellow' } else { 'White' }) $titlePrefix (' ' * $titlePrefix.Length) ([string]$entry.ProfileId) 'Title'
        $cost = Get-TpmReShadeProfileCostText -ProfileDefinition $entry
        $description = if ($cost) { '{0} Cost: {1}.' -f $entry.Description, $cost } else { [string]$entry.Description }
        & $addWrapped $description 'DarkGray' '      ' '      '
        $note = Get-TpmReShadeProfileTextField -Entry $entry -Name 'CompatibilityNote'
        if ($note) { & $addWrapped ('Note: {0}' -f $note) 'DarkYellow' '      ' '            ' }
    }
    if (@($HdrUnavailable).Count -gt 0) {
        & $add '' 'Gray'
        & $add ('  {0}' -f (Get-TpmReShadeProfileGroupLabel -Group 'Hdr')) 'Cyan'
        & $addWrapped ('Not available right now: {0}' -f $HdrReason) 'DarkYellow' '      ' '      '
        foreach ($entry in @($HdrUnavailable)) { & $addWrapped ('(unavailable) {0}' -f (Get-TpmReShadeProfileDisplayLabel -Entry $entry)) 'DarkGray' '      ' '      ' }
    }
    if ($lines.Count -gt 0) { & $add '' 'Gray' }
    return @($lines.ToArray())
}

# The "  [n] m " that starts a profile's title row: the number, then the selection marker (* or a space).
function Get-TpmReShadeMenuTitlePrefix {
    param([int]$Number, [string]$Marker)
    return ('  [{0}] {1} ' -f $Number, $Marker)
}

# FIX46 (owner S1): the chooser's option line is about 130 characters, so a 110-column window split it in the middle of an option
# ("[D] Details" alone on the next row). The options are wrapped at option boundaries for the text width instead; continuation rows are
# indented under the first option. TextWidth 0 (width unknown) keeps the single row.
function Get-TpmReShadeChooseLines {
    param([int]$LastNumber = 1, [int]$TextWidth = 0)
    $prefix = '  Choose: '
    $options = @(('[1-{0}] Select profile' -f [Math]::Max(1, $LastNumber)), '[U] Use selected profile', '[N] Skip ReShade -- no changes', '[R] Reopen preview', '[B] Back', '[D] Details')
    $indent = ' ' * $prefix.Length
    $rows = New-Object System.Collections.Generic.List[string]
    $current = $prefix + $options[0]
    for ($i = 1; $i -lt $options.Count; $i++) {
        $candidate = $current + '  ' + $options[$i]
        if ($TextWidth -gt 0 -and $candidate.Length -gt $TextWidth) {
            [void]$rows.Add($current)
            $current = $indent + $options[$i]
        } else {
            $current = $candidate
        }
    }
    [void]$rows.Add($current)
    return @($rows | ForEach-Object { [pscustomobject]@{ Text = [string]$_; Color = 'White'; ProfileId = ''; Kind = 'Choose' } })
}

# Writes line records cut into rows of at most width-1 characters. FIX52 (issue #384): the width is the LIVE window width,
# read again before every line; a caller's -Width is only an upper bound (the width its layout record was made for), so a
# window made narrower after the caller measured it never receives rows wider than width-1. A size change during the draw
# is then caught by the chooser's resize poll, which draws the whole screen again at the new size.
# Differs from Write-TpmText: it cuts rows by the live window width and moves the cursor itself, so the chooser can redraw in place.
function Write-TpmReShadeTerminalLines {
    param([object[]]$Lines = @(), [int]$Width = 0)
    $metrics = $null
    $cursor = $null
    try { $metrics = Get-TpmConsoleMetrics; $cursor = Get-TpmConsoleCursorPosition } catch {}
    if ($Width -gt 0 -and $metrics -and [int]$metrics.Width -gt $Width) { $metrics.Width = $Width }
    if (-not $metrics -or -not $cursor -or [int]$metrics.Width -le 1) {
        foreach ($line in @($Lines)) { Write-Host ([string]$line.Text) -ForegroundColor $line.Color }
        return
    }
    $textWidth = Get-TpmReShadeConsoleTextWidth -Metrics $metrics
    $left = [int]$metrics.Left
    foreach ($line in @($Lines)) {
        $text = [string]$line.Text
        if ($text.Length -eq 0) { Write-TpmConsoleText "`n"; continue }
        try {
            $liveMetrics = Get-TpmConsoleMetrics
            if ($liveMetrics -and [int]$liveMetrics.Width -gt 1) {
                $liveWidth = [int]$liveMetrics.Width
                if ($Width -gt 0 -and $liveWidth -gt $Width) { $liveWidth = $Width }
                $textWidth = [int][Math]::Max(1, $liveWidth - 1)
            }
        } catch {}
        for ($offset = 0; $offset -lt $text.Length; $offset += $textWidth) {
            $length = [Math]::Min($textWidth, $text.Length - $offset)
            $cursor = Get-TpmConsoleCursorPosition
            Set-TpmConsoleCursorPosition -Left $left -Top ([int]$cursor.Top)
            Write-TpmConsoleText $text.Substring($offset, $length) -Color $line.Color
            # Newline lets the host scroll a full buffer; an absolute next row may not exist.
            Write-TpmConsoleText "`n"
        }
    }
    $cursor = Get-TpmConsoleCursorPosition
    Set-TpmConsoleCursorPosition -Left $left -Top ([int]$cursor.Top)
}

# ---- Live selection display. Console access goes through thin seams so a scripted console can drive the real code.
function Get-TpmConsoleCursorPosition { return [pscustomobject]@{ Left = [Console]::CursorLeft; Top = [Console]::CursorTop } }
function Set-TpmConsoleCursorPosition { param([int]$Left, [int]$Top) [Console]::SetCursorPosition($Left, $Top) }
# Seam: the text of one console buffer row, Width cells from column Left (an empty cell reads as a space). Throws when the host cannot
# read its buffer; the caller then treats the screen as unverified.
function Read-TpmConsoleRowText {
    param([int]$Row, [int]$Left = 0, [int]$Width = 1)
    $cells = $Host.UI.RawUI.GetBufferContents([System.Management.Automation.Host.Rectangle]::new($Left, $Row, ($Left + $Width - 1), $Row))
    $builder = New-Object System.Text.StringBuilder $Width
    for ($x = 0; $x -lt $Width; $x++) {
        $ch = [char]$cells[0, $x].Character
        if ([int]$ch -eq 0) { $ch = [char]32 }
        [void]$builder.Append($ch)
    }
    return $builder.ToString()
}
function Get-TpmConsoleMetrics {
    return [pscustomobject]@{
        Width = [Console]::WindowWidth
        Left = [Console]::WindowLeft
        Top = [Console]::WindowTop
        Height = [Console]::WindowHeight
        BufferWidth = [Console]::BufferWidth
        BufferHeight = [Console]::BufferHeight
    }
}

function Get-TpmReShadeConsoleGeometrySnapshot {
    param([Parameter(Mandatory)]$Metrics)
    $width = [int]$Metrics.Width
    return [pscustomobject]@{
        Width = $width
        Left = if ($Metrics.PSObject.Properties['Left']) { [int]$Metrics.Left } else { 0 }
        Top = if ($Metrics.PSObject.Properties['Top']) { [int]$Metrics.Top } else { 0 }
        Height = if ($Metrics.PSObject.Properties['Height']) { [int]$Metrics.Height } else { 0 }
        BufferWidth = if ($Metrics.PSObject.Properties['BufferWidth']) { [int]$Metrics.BufferWidth } else { $width }
        BufferHeight = if ($Metrics.PSObject.Properties['BufferHeight']) { [int]$Metrics.BufferHeight } else { 0 }
    }
}

function Get-TpmReShadeConsoleTextWidth {
    param([Parameter(Mandatory)]$Metrics)
    return [int][Math]::Max(1, [int]$Metrics.Width - 1)
}

function Test-TpmReShadeConsoleGeometryChanged {
    param([object]$Before, [object]$After)
    if (-not $Before -or -not $After) { return $true }
    foreach ($name in @('Width', 'Left', 'Top', 'Height', 'BufferWidth', 'BufferHeight')) {
        if ([int]$Before.$name -ne [int]$After.$name) { return $true }
    }
    return $false
}

function New-TpmReShadeTerminalLayout {
    param([object[]]$Lines = @(), [int]$Width = 0, [object]$Metrics = $null)
    if (-not $Metrics) {
        try { $Metrics = Get-TpmConsoleMetrics } catch { $Metrics = [pscustomobject]@{ Width = $Width; Left = 0; Top = 0; Height = 0; BufferWidth = $Width; BufferHeight = 0 } }
    }
    $geometry = Get-TpmReShadeConsoleGeometrySnapshot -Metrics $Metrics
    if ($Width -gt 0) {
        $geometry.Width = $Width
        if ($geometry.BufferWidth -le 0) { $geometry.BufferWidth = $Width }
    }
    return @{ Lines = @($Lines); Width = [int]$geometry.Width; TextWidth = (Get-TpmReShadeConsoleTextWidth -Metrics $geometry); Geometry = $geometry; ExtraRows = 0 }
}

function Get-TpmConsoleRowCount {
    param([string]$Text, [int]$Width)
    if ($Width -le 0) { return 1 }
    return [int][Math]::Max(1, [Math]::Ceiling($Text.Length / [double]$Width))
}

# Rewrites, in place, the menu marker of the previously and newly selected profile and the "Current selection" line, then puts the cursor
# back where it was. Rows are computed relative to the live prompt row from the recorded line layout, so a console that scrolled since the
# menu was printed is still addressed correctly. Nothing is written unless every needed row is provably on screen, the layout is unchanged
# (same window width, same number of wrapped rows) AND the console still shows, on those rows, what the layout recorded: the prompt row,
# the Current selection row, the Choose rows and every marker row are read back first. FIX46: in the owner's Windows Terminal the rows
# the layout pointed at no longer held the menu (a progress bar had been drawn into the chooser area), and the in-place write left a black
# window showing only the rewritten Current selection line. After writing, the Current selection row and the prompt row are read back
# again. In every case that is not proven the function returns Updated = $false with a Reason (written nothing, or VERIFY_FAILED after a
# write that did not read back), and the caller redraws the whole menu block and the prompt. It never throws.
function Update-TpmReShadeTerminalSelectionInPlace {
    param([Parameter(Mandatory)]$Layout, [Parameter(Mandatory)]$NewProfile, [string]$Prompt, [int]$BufferLength)
    $fail = { param($why) [pscustomobject]@{ Updated = $false; CurrentUpdated = $false; MarkersUpdated = 0; Reason = $why } }
    $original = $null
    try {
        $metrics = Get-TpmConsoleMetrics
        $geometry = Get-TpmReShadeConsoleGeometrySnapshot -Metrics $metrics
        $width = [int]$geometry.Width
        if ($width -le 0 -or $width -ne [int]$Layout['Width']) { return (& $fail 'WIDTH_CHANGED') }
        if (Test-TpmReShadeConsoleGeometryChanged -Before $Layout['Geometry'] -After $geometry) { return (& $fail 'GEOMETRY_CHANGED') }
        $textWidth = Get-TpmReShadeConsoleTextWidth -Metrics $geometry
        $lines = @($Layout['Lines'])
        $currentIndex = -1
        for ($i = $lines.Count - 1; $i -ge 0; $i--) { if ($lines[$i].Kind -eq 'Current') { $currentIndex = $i; break } }
        if ($currentIndex -lt 0) { return (& $fail 'NO_CURRENT_LINE') }
        $original = Get-TpmConsoleCursorPosition
        $promptChars = $Prompt.Length + 2 + $BufferLength
        $promptTop = [int]$original.Top - [int][Math]::Floor($promptChars / [double]$width)
        # rows from each recorded line to the prompt's first row
        $rowsBelow = New-Object 'int[]' ($lines.Count + 1)
        $rowsBelow[$lines.Count] = [int]$Layout['ExtraRows']
        for ($i = $lines.Count - 1; $i -ge 0; $i--) { $rowsBelow[$i] = $rowsBelow[$i + 1] + (Get-TpmConsoleRowCount -Text $lines[$i].Text -Width $textWidth) }
        $rowOf = { param($index) $promptTop - $rowsBelow[$index] }
        $isVisible = { param($row) ($row -ge [int]$metrics.Top) -and ($row -ge 0) -and ($row -lt ([int]$metrics.Top + [int]$metrics.Height)) -and ($row -lt [int]$metrics.BufferHeight) }
        $newCurrentText = '  Current selection: {0}' -f $(if ($NewProfile) { Get-TpmReShadeProfileDisplayLabel -Entry $NewProfile } else { 'none -- choose a profile in the preview or terminal' })
        $oldCurrentText = [string]$lines[$currentIndex].Text
        if ((Get-TpmConsoleRowCount -Text $newCurrentText -Width $textWidth) -ne (Get-TpmConsoleRowCount -Text $oldCurrentText -Width $textWidth)) { return (& $fail 'CURRENT_LINE_WRAPS_DIFFERENTLY') }
        $currentRow = & $rowOf $currentIndex
        if (-not (& $isVisible $currentRow)) { return (& $fail 'CURRENT_LINE_NOT_VISIBLE') }
        # marker edits: clear the star where it is now, set it on the new profile
        $edits = New-Object System.Collections.Generic.List[object]
        for ($i = 0; $i -lt $lines.Count; $i++) {
            if ($lines[$i].Kind -ne 'Title') { continue }
            $wantStar = ([string]$lines[$i].ProfileId -eq [string]$NewProfile.ProfileId)
            $hasStar = ($lines[$i].Text -match '^\s*\[\d+\] \*')
            if ($wantStar -eq $hasStar) { continue }
            # the marker is one character wide, so the line keeps its length
            $newText = [regex]::Replace($lines[$i].Text, '^(\s*\[\d+\] )(.)', { param($m) $m.Groups[1].Value + $(if ($wantStar) { '*' } else { ' ' }) })
            $row = & $rowOf $i
            if (-not (& $isVisible $row)) { continue }
            if ((Get-TpmConsoleRowCount -Text $newText -Width $textWidth) -ne (Get-TpmConsoleRowCount -Text $lines[$i].Text -Width $textWidth)) { continue }
            [void]$edits.Add([pscustomobject]@{ Index = $i; Row = $row; Text = $newText; Color = $(if ($wantStar) { 'Yellow' } else { 'White' }) })
        }
        # Read back every row this update relies on before anything is written: the first row of a recorded line must show exactly that
        # line's text, and the prompt row must start with the prompt.
        $shownText = { param($row) ([string](Read-TpmConsoleRowText -Row $row -Left ([int]$geometry.Left) -Width $textWidth)).TrimEnd() }
        $firstRowText = { param($text) $t = [string]$text; if ($t.Length -gt $textWidth) { $t = $t.Substring(0, $textWidth) }; $t.TrimEnd() }
        $promptShown = { param($row) (& $shownText $row).StartsWith(($Prompt + ':'), [StringComparison]::Ordinal) }
        try {
            if (-not (& $promptShown $promptTop)) { return (& $fail 'SCREEN_MISMATCH') }
            if ((& $shownText $currentRow) -cne (& $firstRowText $oldCurrentText)) { return (& $fail 'SCREEN_MISMATCH') }
            for ($i = $currentIndex + 1; $i -lt $lines.Count; $i++) {
                $row = & $rowOf $i
                if ((& $isVisible $row) -and ((& $shownText $row) -cne (& $firstRowText $lines[$i].Text))) { return (& $fail 'SCREEN_MISMATCH') }
            }
            foreach ($edit in $edits) {
                if ((& $shownText $edit.Row) -cne (& $firstRowText $lines[$edit.Index].Text)) { return (& $fail 'SCREEN_MISMATCH') }
            }
        } catch {
            return (& $fail 'SCREEN_UNREADABLE')
        }
        # Clear the old line region without writing the final visible column. That column is avoided because a write there can wrap and
        # scroll some console hosts before the chooser can restore its cursor.
        $writeAt = {
            param($row, $text, $oldLength, $color)
            $regionRows = Get-TpmConsoleRowCount -Text ([string]::new('x', [Math]::Max($text.Length, $oldLength))) -Width $textWidth
            $padded = $text.PadRight($regionRows * $textWidth)
            for ($part = 0; $part -lt $regionRows; $part++) {
                Set-TpmConsoleCursorPosition -Left ([int]$geometry.Left) -Top ($row + $part)
                Write-TpmConsoleText $padded.Substring($part * $textWidth, $textWidth) -Color $color
            }
        }
        foreach ($edit in $edits) { & $writeAt $edit.Row $edit.Text $lines[$edit.Index].Text.Length $edit.Color }
        & $writeAt $currentRow $newCurrentText $oldCurrentText.Length 'Yellow'
        Set-TpmConsoleCursorPosition -Left ([int]$original.Left) -Top ([int]$original.Top)
        $verified = $false
        try { $verified = ((& $shownText $currentRow) -ceq (& $firstRowText $newCurrentText)) -and (& $promptShown $promptTop) } catch { $verified = $false }
        if (-not $verified) { return (& $fail 'VERIFY_FAILED') }
        # The layout record follows the screen only once the screen is proven to show it.
        $markersUpdated = 0
        foreach ($edit in $edits) {
            $lines[$edit.Index].Text = $edit.Text
            $lines[$edit.Index].Color = $edit.Color
            $markersUpdated++
        }
        $lines[$currentIndex].Text = $newCurrentText
        return [pscustomobject]@{ Updated = $true; CurrentUpdated = $true; MarkersUpdated = $markersUpdated; Reason = '' }
    } catch {
        try { if ($original) { Set-TpmConsoleCursorPosition -Left ([int]$original.Left) -Top ([int]$original.Top) } } catch {}
        try { Write-Log ('ReShade terminal in-place update failed -- {0}' -f $_.Exception.Message) } catch {}
        return [pscustomobject]@{ Updated = $false; CurrentUpdated = $false; MarkersUpdated = 0; Reason = 'EXCEPTION' }
    }
}

# FIX52 (issue #384): the chooser's intro lines as line records, so they are cut to the live width like the menu and are drawn again
# when a resize redraws the whole chooser screen.
function Get-TpmReShadeChooserIntroLines {
    return @(
        [pscustomobject]@{ Text = ''; Color = 'Gray'; ProfileId = ''; Kind = 'Intro' }
        [pscustomobject]@{ Text = '  Choose how your game should look. Nothing will be changed until you confirm.'; Color = 'Cyan'; ProfileId = ''; Kind = 'Intro' }
        [pscustomobject]@{ Text = '  The preview is only an approximation. Pick a profile in the preview window or below.'; Color = 'DarkCyan'; ProfileId = ''; Kind = 'Intro' }
    )
}

# Seam (FIX52, issue #384): clears the window before the chooser screen is drawn again after a resize, the way the menus redraw.
function Clear-TpmReShadeChooserScreen { Clear-ConsoleForFreshRender }

# FIX52 (issue #384): blanks the rows the prompt and the typed text take at the CURRENT width (after a resize they can wrap onto more than
# one row) and leaves the cursor at the start of the first of them, so a notice and the redrawn prompt leave no piece of the old prompt
# behind. Rows are touched only when the first one is read back and starts with the prompt; otherwise (unreadable console, prompt not
# where the cursor says) the current row is blanked from its start as before.
function Clear-TpmReShadePromptRows {
    param([string]$Prompt, [int]$Length)
    try {
        $metrics = Get-TpmConsoleMetrics
        $width = [int]$metrics.Width
        if ($width -gt 1) {
            $cursor = Get-TpmConsoleCursorPosition
            $left = [int]$metrics.Left
            # Counted from the cursor column, so a host that holds the cursor at the end of a full row (instead of wrapping it to the
            # next row) gives the same first row.
            $top = [int]$cursor.Top - [int][Math]::Floor(($Length - ([int]$cursor.Left - $left)) / [double]$width)
            $shown = if ($top -ge 0 -and $top -le [int]$cursor.Top) { [string](Read-TpmConsoleRowText -Row $top -Left $left -Width ([Math]::Min($width, $Prompt.Length + 1))) } else { '' }
            if ($shown.StartsWith(($Prompt + ':'), [System.StringComparison]::Ordinal)) {
                # A prompt row above the cursor row was filled to its last column (that is why it wrapped), so it is blanked in full; the
                # write may only wrap onto the next row, which exists. The cursor row keeps its last column free so nothing can scroll.
                for ($row = $top; $row -le [int]$cursor.Top; $row++) {
                    Set-TpmConsoleCursorPosition -Left $left -Top $row
                    Write-TpmConsoleText (' ' * $(if ($row -lt [int]$cursor.Top) { $width } else { $width - 1 }))
                }
                Set-TpmConsoleCursorPosition -Left $left -Top $top
                return
            }
        }
    } catch {}
    Write-TpmConsoleText ("`r" + (' ' * ($Length + 1)) + "`r")
}

# Full redraw of the chooser block. After a console resize the printed rows can no longer be addressed (the console reflowed them), and
# after a selection change that could not be shown in place they are not proven to hold the menu (FIX46), so the block is printed once more
# at the cursor: the menu with the marker on the new selection, the Current selection line and the Choose rows wrapped for the current
# width. The layout record is replaced with the new width and rows, and the prompt is redrawn with the typed text intact. Without
# -ClearScreen nothing earlier is erased, so the screen always ends with the complete block and the prompt. FIX52 (issue #384): after a
# console RESIZE the caller passes -ClearScreen and the intro lines: the window is cleared the way the menus redraw
# (Clear-TpmReShadeChooserScreen) and the whole chooser screen is laid out again at the new size, so nothing composed for the old size
# stays on screen. Input stays end-of-line only, so the cursor is left right after the typed text. It never throws; $false means nothing
# could be rebuilt (or the size changed again while drawing) and the caller announces instead.
function Update-TpmReShadeTerminalLayoutAfterResize {
    param([Parameter(Mandatory)]$Layout, [AllowNull()]$NewProfile, [object[]]$Selectable = @(), [object[]]$HdrUnavailable = @(), [string]$HdrReason = '', [string]$Prompt = '', [string]$InputText = '', [switch]$ClearScreen, [object[]]$IntroLines = @())
    try {
        $oldLines = @($Layout['Lines'])
        $currentLine = @($oldLines | Where-Object { $_.Kind -eq 'Current' } | Select-Object -Last 1)
        $chooseLine = @($oldLines | Where-Object { $_.Kind -eq 'Choose' } | Select-Object -Last 1)
        if ($currentLine.Count -eq 0 -or $chooseLine.Count -eq 0) { return $false }
        # FIX52: the window is cleared BEFORE its size is read, so the screen is composed for the size it is drawn into (the clear can
        # also move the window origin). A size change during the draw fails the after-draw check below and the next poll draws again.
        if ($ClearScreen) {
            # An unreadable size is refused before anything is cleared, so a failure never leaves a blank window.
            if ([int](Get-TpmConsoleMetrics).Width -le 0) { return $false }
            Clear-TpmReShadeChooserScreen
        }
        $metrics = Get-TpmConsoleMetrics
        $geometry = Get-TpmReShadeConsoleGeometrySnapshot -Metrics $metrics
        $width = [int]$geometry.Width
        if ($width -le 0) { return $false }
        $currentText = '  Current selection: {0}' -f $(if ($NewProfile) { Get-TpmReShadeProfileDisplayLabel -Entry $NewProfile } else { 'none -- choose a profile in the preview or terminal' })
        $newCurrent = [pscustomobject]@{ Text = $currentText; Color = 'Yellow'; ProfileId = ''; Kind = 'Current' }
        $chooseWidth = if ($width -gt 1) { Get-TpmReShadeConsoleTextWidth -Metrics $geometry } else { 0 }
        $menuLines = @(Get-TpmReShadeTerminalMenuLines -Selectable $Selectable -HdrUnavailable $HdrUnavailable -Selected $NewProfile -HdrReason $HdrReason -TextWidth $chooseWidth)
        $newLines = @($menuLines) + @($newCurrent) + @(Get-TpmReShadeChooseLines -LastNumber @($Selectable).Count -TextWidth $chooseWidth)
        if ($ClearScreen) {
            Write-TpmReShadeTerminalLines -Lines @($IntroLines) -Width $width
        } else {
            $cursor = Get-TpmConsoleCursorPosition
            Set-TpmConsoleCursorPosition -Left ([int]$geometry.Left) -Top ([int]$cursor.Top)
            Write-TpmConsoleText "`n"
        }
        Write-TpmReShadeTerminalLines -Lines $newLines -Width $width
        $Layout['Lines'] = @($newLines)
        $Layout['Width'] = $width
        $Layout['TextWidth'] = Get-TpmReShadeConsoleTextWidth -Metrics $geometry
        $Layout['Geometry'] = $geometry
        $Layout['ExtraRows'] = 0
        Write-TpmConsoleText ($Prompt + ': ' + $InputText)
        # Printing the rebuilt menu can scroll a short viewport. Store the
        # geometry after the draw so that this self-induced WindowTop change
        # is not mistaken for another external resize on the next idle poll.
        # If the viewport's actual layout changed while rendering, leave the
        # old snapshot in place; the next poll will rebuild once for that
        # real change instead of accepting a layout drawn at stale dimensions.
        $renderedGeometry = Get-TpmReShadeConsoleGeometrySnapshot -Metrics (Get-TpmConsoleMetrics)
        foreach ($name in @('Width', 'Left', 'Height', 'BufferWidth', 'BufferHeight')) {
            if ([int]$geometry.$name -ne [int]$renderedGeometry.$name) { return $false }
        }
        $Layout['Geometry'] = $renderedGeometry
        return $true
    } catch {
        try { Write-Log ('ReShade terminal layout rebuild failed -- {0}' -f $_.Exception.Message) } catch {}
        return $false
    }
}

function Read-TpmReShadeTerminalProfile {
    param(
        [Parameter(Mandatory)][object[]]$Profiles,
        [string]$DefaultProfileId = '',
        [object]$PreviewSession = $null,
        [object[]]$DllChecks = @()
    )
    $orderedIds = @($Profiles | ForEach-Object { [string]$_.ProfileId })
    $selectable = @($Profiles)
    $selected = $null
    if ($DefaultProfileId) { $selected = Get-TpmReShadeProfile -ProfileId $DefaultProfileId }
    # Snapshot a closed gallery once, then keep later terminal choices authoritative.
    $previewClosedSelectionImported = $false
    $originalPreviewSession = $PreviewSession
    try {
        while ($true) {
            # Re-evaluate the HDR gate on every pass: HDR choices appear only while real detection allows them.
            $hdrGate = Get-TpmReShadeHdrGate
            $selectable = @($Profiles | Where-Object { -not (Test-TpmReShadeProfileRequiresHdr -Entry $_) -or [bool]$hdrGate.Enabled })
            $hdrUnavailable = @($Profiles | Where-Object { (Test-TpmReShadeProfileRequiresHdr -Entry $_) -and [bool]$hdrGate.Visible -and -not [bool]$hdrGate.Enabled })
            $orderedIds = @($selectable | ForEach-Object { [string]$_.ProfileId })
            if ($selected -and [string]$selected.ProfileId -notin $orderedIds) {
                Write-Host ('  {0} is not available right now, so it is no longer selected.' -f $selected.FriendlyName) -ForegroundColor Yellow
                $selected = $null
            }
            if ($PreviewSession) {
                try { [Windows.Forms.Application]::DoEvents() } catch {}
                $previewSessionClosed = [bool]$PreviewSession['Closed']
                $canReadPreviewSelection = [bool]$PreviewSession['Initialized'] -and [bool]$PreviewSession['PreviewEnabled'] -and (-not $previewSessionClosed -or -not $previewClosedSelectionImported)
                if ($canReadPreviewSelection) {
                    $previewProfileId = [string]$PreviewSession['SelectedProfileId']
                    if (-not [string]::IsNullOrWhiteSpace($previewProfileId)) {
                        $previewSelection = @($selectable | Where-Object { [string]$_.ProfileId -eq $previewProfileId })[0]
                        if ($previewSelection) { $selected = $previewSelection }
                    }
                    if ($previewSessionClosed) { $previewClosedSelectionImported = $true }
                }
            }
            # FIX52 (#384): written like the menu block (rows cut to the live width) and drawn again by a resize redraw.
            $introLines = @(Get-TpmReShadeChooserIntroLines)
            Write-TpmReShadeTerminalLines -Lines $introLines
            $profileCount = $orderedIds.Count
            $lastProfileNumber = [Math]::Max(1, $profileCount)
            $currentSelectionText = '  Current selection: {0}' -f $(if ($selected) { Get-TpmReShadeProfileDisplayLabel -Entry $selected } else { 'none -- choose a profile in the preview or terminal' })
            # Retain the dimensions used for the draw; a resize during output must not bless a mixed-width layout.
            $layoutMetrics = [pscustomobject]@{ Width = 0; Left = 0; Top = 0; Height = 0; BufferWidth = 0; BufferHeight = 0 }
            try { $layoutMetrics = Get-TpmReShadeConsoleGeometrySnapshot -Metrics (Get-TpmConsoleMetrics) } catch {}
            $chooseWidth = if ([int]$layoutMetrics.Width -gt 1) { Get-TpmReShadeConsoleTextWidth -Metrics $layoutMetrics } else { 0 }
            $menuLines = @(Get-TpmReShadeTerminalMenuLines -Selectable $selectable -HdrUnavailable $hdrUnavailable -Selected $selected -HdrReason ([string]$hdrGate.Reason) -TextWidth $chooseWidth)
            $blockLines = @($menuLines) + @([pscustomobject]@{ Text = $currentSelectionText; Color = 'Yellow'; ProfileId = ''; Kind = 'Current' }) + @(Get-TpmReShadeChooseLines -LastNumber $lastProfileNumber -TextWidth $chooseWidth)
            Write-TpmReShadeTerminalLines -Lines $blockLines -Width ([int]$layoutMetrics.Width)
            # Natural scrolling changes only the viewport origin, not the dimensions that own the printed rows.
            try { $layoutMetrics.Top = [int](Get-TpmConsoleMetrics).Top } catch {}
            $layout = New-TpmReShadeTerminalLayout -Lines $blockLines -Metrics $layoutMetrics
            # While the prompt waits, follow the preview selector. A change is shown by rewriting the menu marker and the "Current
            # selection" line IN PLACE (no new menu is printed) when the console proves it still shows the recorded rows; otherwise the
            # whole block and the prompt are drawn again with the typed text intact (FIX46), and only if even that fails a one-line
            # announcement is printed. The callbacks are plain scriptblocks (not closures): they resolve the product functions and this
            # loop's variables dynamically.
            $shownSelection = @{ Id = $(if ($selected) { [string]$selected.ProfileId } else { '' }) }
            $observedGeometry = @{ Snapshot = $layout['Geometry'] }
            $resizeRetries = @{ Count = 0 }
            $idleSession = $PreviewSession
            $idleSelectable = $selectable
            $onIdle = {
                $liveProfile = $null
                $liveId = ''
                $selectionChanged = $false
                if ($idleSession -and [bool]$idleSession['Initialized'] -and [bool]$idleSession['PreviewEnabled'] -and -not [bool]$idleSession['Closed']) {
                    $liveId = [string]$idleSession['SelectedProfileId']
                    if (-not [string]::IsNullOrWhiteSpace($liveId) -and $liveId -ne $shownSelection.Id) {
                        $liveProfile = $idleSelectable | Where-Object { [string]$_.ProfileId -eq $liveId } | Select-Object -First 1
                        $selectionChanged = [bool]$liveProfile
                    }
                }
                try {
                    $currentGeometry = Get-TpmReShadeConsoleGeometrySnapshot -Metrics (Get-TpmConsoleMetrics)
                    if (Test-TpmReShadeConsoleGeometryChanged -Before $observedGeometry.Snapshot -After $currentGeometry) {
                        # FIX52: a $null snapshot is the retry of a size redraw that did not finish (see $onUpdate).
                        $retry = ($null -eq $observedGeometry.Snapshot)
                        $observedGeometry.Snapshot = $currentGeometry
                        if ($selectionChanged) { $shownSelection.Id = $liveId }
                        $number = if ($selectionChanged) { 1 + [Array]::IndexOf(@($idleSelectable | ForEach-Object { [string]$_.ProfileId }), $liveId) } else { 0 }
                        return [pscustomobject]@{ Kind = 'Resize'; ProfileId = $liveId; Profile = $liveProfile; Number = $number; Geometry = $currentGeometry; Retry = $retry; Notice = '  Console size changed; refreshing the selection display.' }
                    }
                } catch { Write-Log ("ReShade console geometry poll failed -- {0}" -f $_.Exception.Message) }
                if (-not $selectionChanged) { return $null }
                $shownSelection.Id = $liveId
                $liveNumber = 1 + [Array]::IndexOf(@($idleSelectable | ForEach-Object { [string]$_.ProfileId }), $liveId)
                return [pscustomobject]@{ Kind = 'Selection'; ProfileId = $liveId; Profile = $liveProfile; Number = $liveNumber; Notice = ('  Preview selection changed to [{0}] {1}. Type U to use it.' -f $liveNumber, (Get-TpmReShadeProfileDisplayLabel -Entry $liveProfile)) }
            }
            $idleHdrUnavailable = $hdrUnavailable
            $idleHdrReason = [string]$hdrGate.Reason
            $onUpdate = {
                param($change, $inputPrompt, $inputLength, $inputText)
                if ([string]$change.Kind -eq 'Resize') {
                    $selectedProfile = if ($change.Profile) { $change.Profile } else { $selected }
                    if (-not [bool]$change.Retry) { $resizeRetries.Count = 0 }
                    # FIX52 (#384): a SIZE change (width, height or buffer) clears the window and draws the whole chooser screen again at the
                    # new size, like the menus. A scrolled window (only its top moved) keeps the earlier output and gets the block below it.
                    $sizeChanged = $false
                    foreach ($name in @('Width', 'Height', 'BufferWidth', 'BufferHeight')) {
                        if (-not $change.Geometry -or [int]$change.Geometry.$name -ne [int]$layout['Geometry'].$name) { $sizeChanged = $true }
                    }
                    $rebuilt = Update-TpmReShadeTerminalLayoutAfterResize -Layout $layout -NewProfile $selectedProfile -Selectable $idleSelectable -HdrUnavailable $idleHdrUnavailable -HdrReason $idleHdrReason -Prompt $inputPrompt -InputText ([string]$inputText) -ClearScreen:$sizeChanged -IntroLines $introLines
                    if ($rebuilt) {
                        $observedGeometry.Snapshot = $layout['Geometry']
                        $resizeRetries.Count = 0
                    } elseif ($sizeChanged -and $resizeRetries.Count -lt 3) {
                        # FIX52: a size redraw that did not finish (the size changed again while drawing, or it failed after the window
                        # was cleared) is drawn again at the next poll, at most three times in a row, so the screen never stays partial.
                        $resizeRetries.Count++
                        $observedGeometry.Snapshot = $null
                    }
                    return [bool]$rebuilt
                }
                $inPlace = Update-TpmReShadeTerminalSelectionInPlace -Layout $layout -NewProfile $change.Profile -Prompt $inputPrompt -BufferLength $inputLength
                if ([bool]$inPlace.Updated) { return $true }
                # FIX46: whatever stopped the in-place update (a width or geometry change, a Current selection that now wraps to a different
                # number of rows, rows that are off screen or no longer show the recorded menu, a write that did not read back), the whole
                # block and the prompt are drawn again below the existing output, so the screen never ends without the menu and the prompt.
                try { Write-Log ("ReShade terminal selection redrawn in full ({0})." -f [string]$inPlace.Reason) } catch {}
                $rebuilt = Update-TpmReShadeTerminalLayoutAfterResize -Layout $layout -NewProfile $change.Profile -Selectable $idleSelectable -HdrUnavailable $idleHdrUnavailable -HdrReason $idleHdrReason -Prompt $inputPrompt -InputText ([string]$inputText)
                if ($rebuilt) { $observedGeometry.Snapshot = $layout['Geometry'] }
                return [bool]$rebuilt
            }
            $onFallback = { param($noticeText) $layout['ExtraRows'] = [int]$layout['ExtraRows'] + (Get-TpmConsoleRowCount -Text ([string]$noticeText) -Width ([int]$layout['TextWidth'])) }
            $choice = (Read-TpmReShadeTerminalInput -Prompt '  Choice' -PumpPreviewMessages ([bool]$PreviewSession) -PollConsoleResize $true -OnIdle $onIdle -OnUpdate $onUpdate -OnFallback $onFallback).Trim().ToUpperInvariant()
            if ($PreviewSession) {
                try { [Windows.Forms.Application]::DoEvents() } catch {}
                $previewSessionClosed = [bool]$PreviewSession['Closed']
                $canReadPreviewSelection = [bool]$PreviewSession['Initialized'] -and [bool]$PreviewSession['PreviewEnabled'] -and (-not $previewSessionClosed -or -not $previewClosedSelectionImported)
                if ($canReadPreviewSelection) {
                    $previewProfileId = [string]$PreviewSession['SelectedProfileId']
                    if (-not [string]::IsNullOrWhiteSpace($previewProfileId)) {
                        $previewSelection = @($selectable | Where-Object { [string]$_.ProfileId -eq $previewProfileId })[0]
                        if ($previewSelection) { $selected = $previewSelection }
                    }
                    if ($previewSessionClosed) { $previewClosedSelectionImported = $true }
                }
            }
            $selectedNumber = 0
            if ([int]::TryParse($choice, [ref]$selectedNumber) -and $selectedNumber -ge 1 -and $selectedNumber -le $profileCount) {
                $selectedProfileId = $orderedIds[$selectedNumber - 1]
                $selected = @($selectable | Where-Object { $_.ProfileId -eq $selectedProfileId })[0]
                if ($selected) {
                    if ($PreviewSession) {
                        [void](Sync-TpmReShadeGallerySelection -Session $PreviewSession -ProfileId ([string]$selected.ProfileId))
                    }
                    Write-Host ('  Preview selection changed to: {0}' -f (Get-TpmReShadeProfileDisplayLabel -Entry $selected)) -ForegroundColor Green
                }
                continue
            }
            if ($choice -eq 'D') {
                $detailsWidth = Get-TpmReShadeScreenTextWidth
                $say = {
                    param($text, $first, $hang, $color)
                    foreach ($row in @(Get-TpmReShadeHangingRows -Text $text -Width $detailsWidth -FirstPrefix $first -HangPrefix $hang)) { Write-Host $row -ForegroundColor $color }
                }
                $catalogVersion = ''
                try { $catalogVersion = [string](Get-ManagerDisplayVersion) } catch { $catalogVersion = '' }
                $catalogName = if ($catalogVersion) { 'the {0} beginner-friendly catalog' -f $catalogVersion } else { 'the beginner-friendly catalog' }
                $effectCount = @($Profiles | ForEach-Object { $_.Effects } | Sort-Object -Unique).Count
                Write-Host ''
                & $say 'About this list' '  ' '  ' 'Cyan'
                & $say 'Preview: TeknoParrot Manager shows a safe preview approximation using a bundled image. It does not run the game or execute ReShade shaders during preview. Actual in-game results may vary.' '    ' '        ' 'DarkCyan'
                & $say 'Preview window: compare Original/After or Split. Select a profile there or here in the terminal; the choice stays synchronized between the preview selector and the terminal list.' '    ' '        ' 'DarkCyan'
                & $say ('Catalog: {0}. This list has {1} profiles built from {2} pinned shader effects. Original is the untouched reference, not an effect.' -f $catalogName, @($Profiles).Count, $effectCount) '    ' '        ' 'DarkCyan'
                & $say 'Stacking: Alternatives that do the same kind of job are never stacked automatically.' '    ' '        ' 'DarkCyan'
                $dllDetailLines = @(Get-TpmReShadeDllDetailLines -Checks @($DllChecks) -Installer (Get-TpmReShadeInstallerEvidence) -TextWidth $detailsWidth)
                if ($dllDetailLines.Count -gt 0) {
                    Write-Host ''
                    foreach ($detailLine in $dllDetailLines) { Write-Host $detailLine.Text -ForegroundColor $detailLine.Color }
                }
                Write-Host ''
                & $say 'Profiles' '  ' '  ' 'Cyan'
                foreach ($id in $orderedIds) {
                    $profileEntry = @($selectable | Where-Object { $_.ProfileId -eq $id })[0]
                    if ($profileEntry) {
                        Write-Host ''
                        & $say (Get-TpmReShadeProfileDisplayLabel -Entry $profileEntry) '    ' '        ' 'White'
                        & $say ('What it does: {0}' -f $profileEntry.Description) '      ' '          ' 'DarkGray'
                        & $say ('Techniques: {0}' -f (Get-TpmReShadeProfileTechniqueDisplay -ProfileDefinition $profileEntry)) '      ' '          ' 'DarkCyan'
                        $previewKind = Get-TpmReShadeProfileTextField -Entry $profileEntry -Name 'PreviewApproximation'
                        $previewNote = Get-TpmReShadeProfileTextField -Entry $profileEntry -Name 'PreviewNote'
                        if ($previewKind -eq 'APPROXIMATE') { & $say 'Preview: approximation only, not the shader running.' '      ' '          ' 'DarkCyan' }
                        elseif ($previewNote) { & $say ('Preview: {0}' -f $previewNote) '      ' '          ' 'DarkCyan' }
                        $cost = Get-TpmReShadeProfileCostText -ProfileDefinition $profileEntry
                        if ($cost) { & $say ('Cost: {0} (rough estimate, not measured).' -f $cost) '      ' '          ' 'DarkCyan' }
                    }
                }
                continue
            }
            if ($choice -eq 'R') {
                if ($PreviewSession) {
                    try {
                        $reopenId = if ($selected) { [string]$selected.ProfileId } else { 'Original' }
                        $replacement = Show-TpmReShadeProfileGalleryWindow -Profiles $selectable -DefaultProfileId $reopenId -Show -NonModal
                        if (-not $replacement.Available -or -not $replacement.Session) {
                            throw ("fresh preview window was unavailable ({0})" -f $replacement.Reason)
                        }
                        $oldSession = $PreviewSession
                        $PreviewSession = $replacement.Session
                        $previewClosedSelectionImported = $false
                        Close-TpmReShadeProfileGallerySession -Session $oldSession
                        if ($selected) { [void](Sync-TpmReShadeGallerySelection -Session $PreviewSession -ProfileId ([string]$selected.ProfileId)) }
                        [void][Windows.Forms.Application]::DoEvents()
                        Write-Host ("  Preview window reopened. Your selected profile is still {0}." -f $(if ($selected) { $selected.FriendlyName } else { 'not selected' })) -ForegroundColor DarkCyan
                    } catch {
                        Write-Host ("  TeknoParrot Manager could not reopen the preview because: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
                        Write-Host '  You can still continue from the terminal.' -ForegroundColor Yellow
                        Write-Log ("ReShade profile chooser: preview reopen failed -- {0}" -f $_.Exception.Message)
                    }
                } else {
                    Write-Host '  TeknoParrot Manager could not reopen the preview because: no preview session was created.' -ForegroundColor Yellow
                    Write-Host '  You can still continue from the terminal.' -ForegroundColor Yellow
                    Write-Log 'ReShade profile chooser: preview reopen requested without a session.'
                }
                continue
            }
            if ($choice -eq 'N') {
                Write-Host '  ReShade setup skipped. No ReShade files were installed or changed.' -ForegroundColor DarkGray
                Write-Log 'ReShade profile chooser: skipped by user; no files changed.'
                return [pscustomobject]@{ SelectedProfile = $null; Cancelled = $true; Skipped = $true; PreviewSession = $PreviewSession }
            }
            if ($choice -eq 'B') {
                Write-Log 'ReShade profile chooser: canceled before confirmation.'
                return [pscustomobject]@{ SelectedProfile = $null; Cancelled = $true; PreviewSession = $PreviewSession }
            }
            if ($choice -eq 'U') {
                if ($selected -and [string]$selected.ProfileId -in $orderedIds) {
                    return [pscustomobject]@{ SelectedProfile = $selected; Cancelled = $false; PreviewSession = $PreviewSession }
                }
                Write-Host '  Choose a numbered profile before using it.' -ForegroundColor Yellow
                continue
            }
            Write-Host ('  Invalid choice. Use 1-{0}, U, N, R, B, or D.' -f $lastProfileNumber) -ForegroundColor Yellow
        }
    } catch {
        # A reopened preview is owned here until the caller receives it; the caller closes the original session.
        if ($PreviewSession -and -not [object]::ReferenceEquals($PreviewSession, $originalPreviewSession)) {
            try { Close-TpmReShadeProfileGallerySession -Session $PreviewSession } catch {}
        }
        throw
    }
}
# The ReShade search paths TPM writes into ReShade.ini. Includes and textures of an approved effect resolve against these (after the
# including file's own directory), so they are part of what the license evidence is bound to.
function Get-TpmReShadeSearchPathDeclaration {
    return [pscustomobject]@{ EffectSearchPaths = '.\Shaders,.\Shaders\SweetFX,.\Shaders\TPM'; TextureSearchPaths = '.\Textures,.\Textures\SweetFX' }
}

function Update-TpmReShadeTutorialProgressText {
    param([AllowEmptyString()][string]$Content)
    $lines = @(if ([string]::IsNullOrEmpty($Content)) { @() } else { [regex]::Split($Content, "`r`n|`n|`r") })
    $hasGeneral = $false
    foreach ($line in $lines) { if ($line -match '^\s*\[GENERAL\]\s*$') { $hasGeneral = $true; break } }
    if (-not $hasGeneral) {
        $insertIndex = $lines.Count
        for ($index = 0; $index -lt $lines.Count; $index++) {
            if ($lines[$index] -match '^\s*\[[^\]]+\]\s*$') { $insertIndex = $index; break }
        }
        $before = if ($insertIndex -gt 0) { @($lines[0..($insertIndex - 1)]) } else { @() }
        $after = if ($insertIndex -lt $lines.Count) { @($lines[$insertIndex..($lines.Count - 1)]) } else { @() }
        $lines = @($before + @('[GENERAL]') + $after)
    }
    $normalized = New-Object System.Collections.Generic.List[string]
    $currentSection = ''
    $generalSettingsInserted = $false
    foreach ($line in $lines) {
        if ($line -match '^\s*\[([^\]]+)\]\s*$') {
            $currentSection = $Matches[1].Trim()
            [void]$normalized.Add($line)
            if ($currentSection -ieq 'GENERAL') {
                if (-not $generalSettingsInserted) {
                    $searchPaths = Get-TpmReShadeSearchPathDeclaration
                    [void]$normalized.Add('EffectSearchPaths=' + $searchPaths.EffectSearchPaths)
                    [void]$normalized.Add('TextureSearchPaths=' + $searchPaths.TextureSearchPaths)
                    [void]$normalized.Add('PresetPath=.\ReShade.ini')
                    [void]$normalized.Add('StartupPresetPath=.\ReShade.ini')
                    $generalSettingsInserted = $true
                }
            }
            continue
        }
        if ($currentSection -ieq 'GENERAL' -and $line -match '^\s*(EffectSearchPaths|TextureSearchPaths|PresetPath|StartupPresetPath)\s*=') { continue }
        [void]$normalized.Add($line)
    }
    $lines = $normalized.ToArray()
    # The first-run tutorial is marked finished and the on-screen counters and messages are off (the documented ReShade [OVERLAY] settings).
    # The key that opens ReShade is not touched.
    $overlaySettings = @('TutorialProgress=4', 'ShowClock=0', 'ShowFPS=0', 'ShowFrameTime=0', 'ShowScreenshotMessage=0', 'ShowPresetTransitionMessage=0')
    $overlayKeyPattern = '^\s*(' + ((@($overlaySettings | ForEach-Object { $_.Split('=')[0] })) -join '|') + ')\s*='
    $overlayIndex = -1
    for ($index = 0; $index -lt $lines.Count; $index++) {
        if ($lines[$index] -match '^\s*\[OVERLAY\]\s*$') { $overlayIndex = $index; break }
    }
    if ($overlayIndex -lt 0) {
        $lines = @($lines + @('[OVERLAY]') + $overlaySettings)
    } else {
        $sectionEnd = $lines.Count
        for ($index = $overlayIndex + 1; $index -lt $lines.Count; $index++) {
            if ($lines[$index] -match '^\s*\[[^\]]+\]\s*$') { $sectionEnd = $index; break }
        }
        $kept = @(for ($index = $overlayIndex + 1; $index -lt $sectionEnd; $index++) { if ($lines[$index] -notmatch $overlayKeyPattern) { $lines[$index] } })
        $after = if ($sectionEnd -lt $lines.Count) { @($lines[$sectionEnd..($lines.Count - 1)]) } else { @() }
        $lines = @(@($lines[0..$overlayIndex]) + $overlaySettings + $kept + $after)
    }
    return (($lines -join "`r`n").TrimEnd("`r", "`n") + "`r`n")
}

# Read-only ReShade deployment accounting shown before any game folder is
# touched. The actual deployment loop repeats these safety checks at the
# mutation boundary because a path or ownership state can change meanwhile.
function Get-TpmReShadeApplyPreflight {
    param(
        [Parameter(Mandatory)][object[]]$SelectedGames,
        [Parameter(Mandatory)]$ProfileDefinition,
        [string]$SourceDll,
        # The configured source collection folders; a game inside one is counted as left alone, exactly as the deployment will treat it.
        [string[]]$ProtectedRoots = @()
    )
    $records = New-Object System.Collections.Generic.List[object]
    $ready = 0
    $protected = 0
    $missingPath = 0
    $unsafe = 0
    $progressStarted = Get-Date
    $progressCurrent = 0
    foreach ($pf in $SelectedGames) {
        $progressCurrent++
        if ($SelectedGames.Count -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade apply preflight' -Current $progressCurrent -Total $SelectedGames.Count -StartedAt $progressStarted }
        $gameLabel = Get-TpmReShadeGameLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName
        $record = [ordered]@{ Game = $gameLabel; Id = [string]$pf.BaseName; Status = 'Unsafe'; Detail = '' }
        try {
            $doc = Read-Xml $pf.FullName
            $pathNode = if ($doc.GameProfile) { $doc.GameProfile.SelectSingleNode('GamePath') } else { $null }
            $gamePath = if ($pathNode) { ([string]$pathNode.InnerText).Trim() } else { '' }
            $pathCheck = Test-TpmGameMutationPath -GamePath $gamePath -RequireLeaf -ProtectedRoots $ProtectedRoots
            if (-not $pathCheck.Valid) {
                if ([string]$pathCheck.ReasonCode -eq 'GAME_PATH_MISSING') {
                    $record.Status = 'MissingPath'
                    $missingPath++
                } else {
                    $record.Status = 'Unsafe'
                    $unsafe++
                }
                $record.Detail = [string]$pathCheck.Reason
                [void]$records.Add([pscustomobject]$record)
                continue
            }
            $resolvedPath = [string]$pathCheck.ResolvedPath
            $targetInfo = Get-ReShadeTargetInfo -Doc $doc -GamePath $resolvedPath -ExeDir ([string]$pathCheck.GameDirectory)
            if (-not $targetInfo -or [string]::IsNullOrWhiteSpace($targetInfo.TargetDir) -or [string]::IsNullOrWhiteSpace($targetInfo.DllName)) {
                $record.Detail = 'ReShade target could not be resolved safely.'
                $unsafe++
                [void]$records.Add([pscustomobject]$record)
                continue
            }
            $ownershipPath = Get-TpmReShadeProfileOwnershipPath -GameId $pf.BaseName
            $manifest = $null
            if (Test-Path -LiteralPath $ownershipPath -PathType Leaf) {
                try { $manifest = Read-TpmReShadeOwnershipManifest -Path $ownershipPath }
                catch {
                    $record.Detail = 'ReShade ownership metadata could not be trusted.'
                    $unsafe++
                    [void]$records.Add([pscustomobject]$record)
                    continue
                }
            }
            $architecture = Get-ExeArchitecture -ExePath $resolvedPath
            $has32BitDllForScan = ($architecture -eq 'x86') -and [bool](Get-TpmReShadeSourceDllForArchitecture -SourceDll $SourceDll -Architecture 'x86')
            if ($architecture -ne 'x64' -and -not $has32BitDllForScan) {
                # Installing refuses these games (32-bit file not available, or the bit-ness cannot be read), so they are not counted as ready.
                $record.Detail = if ($architecture -eq 'x86') { '32-bit game: the 32-bit ReShade file (ReShade32.dll) was not found.' } elseif (Test-TpmFileIsElf -Path $resolvedPath) { 'This game runs through BudgieLoader (a Linux-style game). TeknoParrot Manager does not set up ReShade for these games yet.' } else { 'TeknoParrot Manager could not tell whether this game is 32-bit or 64-bit.' }
                $unsafe++
                [void]$records.Add([pscustomobject]$record)
                continue
            }
            $runtimeSource = Get-TpmReShadeSourceDllForArchitecture -SourceDll $SourceDll -Architecture $architecture
            $currentRuntimeHash = if ($runtimeSource -and (Test-Path -LiteralPath $runtimeSource -PathType Leaf)) {
                (Get-FileHash -LiteralPath $runtimeSource -Algorithm SHA256 -ErrorAction SilentlyContinue).Hash
            } else { '' }
            $runtimeVersion = ''
            if ($runtimeSource -and (Test-Path -LiteralPath $runtimeSource -PathType Leaf)) {
                try {
                    $versionInfo = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($runtimeSource)
                    $runtimeVersion = '{0}.{1}.{2}' -f $versionInfo.FileMajorPart, $versionInfo.FileMinorPart, $versionInfo.FileBuildPart
                } catch {}
            }
            $classification = Get-TpmReShadeOwnershipClassification `
                -HookPath (Join-Path $targetInfo.TargetDir $targetInfo.DllName) `
                -TargetRoot $targetInfo.TargetDir `
                -ProfileDefinition $ProfileDefinition `
                -CurrentRuntimeSHA256 $currentRuntimeHash `
                -CurrentRuntimeVersion $runtimeVersion `
                -Manifest $manifest
            if ($classification.Status -in @('UnknownUserOwnedConflict', 'BundledPreinstalledProtected')) {
                $record.Status = 'Protected'
                $protected++
            } elseif ($classification.Status -eq 'MalformedNeedsReview') {
                $record.Status = 'Unsafe'
                $unsafe++
            } else {
                $record.Status = 'Ready'
                $ready++
            }
            $record.Detail = [string]$classification.Detail
        } catch {
            $record.Detail = [string]$_.Exception.Message
            $unsafe++
        }
        [void]$records.Add([pscustomobject]$record)
    }
    if ($SelectedGames.Count -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade apply preflight' -Current $progressCurrent -Total $SelectedGames.Count -StartedAt $progressStarted -Complete }
    return [pscustomobject]@{
        Ready = $ready
        Protected = $protected
        MissingPath = $missingPath
        Unsafe = $unsafe
        Records = @($records.ToArray())
    }
}
function Get-TpmReShadeApplyAccounting {
    param(
        [Parameter(Mandatory)][int]$Selected,
        [int]$Deployed = 0,
        [int]$Adopted = 0,
        [int]$Protected = 0,
        [int]$MissingPath = 0,
        [int]$MissingDevice = 0,
        [int]$Unsafe = 0,
        [int]$Failed = 0,
        [int]$KeptPrevious = 0,
        [int]$SkippedCancelled = 0
    )
    $adoptedCount = [Math]::Max(0, $Adopted)
    $changedCount = [Math]::Max(0, $Deployed - $adoptedCount)
    $missingCount = [Math]::Max(0, $MissingPath + $MissingDevice)
    $unsafeCount = [Math]::Max(0, $Unsafe)
    $failedCount = [Math]::Max(0, $Failed)
    $protectedCount = [Math]::Max(0, $Protected)
    $keptCount = [Math]::Max(0, $KeptPrevious)
    $skippedCount = [Math]::Max(0, $SkippedCancelled)
    $total = $changedCount + $adoptedCount + $protectedCount + $missingCount + $unsafeCount + $failedCount + $keptCount + $skippedCount
    return [pscustomobject]@{
        Selected = $Selected
        ChangedTpmManaged = $changedCount
        AdoptedReplaced = $adoptedCount
        ProtectedUnchanged = $protectedCount
        KeptPrevious = $keptCount
        MissingPath = $missingCount
        UnsafeOwnershipPath = $unsafeCount
        Failed = $failedCount
        SkippedCancelled = $skippedCount
        Total = $total
        Complete = ($total -eq $Selected)
    }
}


function Format-TpmReShadeSummaryDetailRows {
    param([Parameter(Mandatory)]$Result)
    $rows = New-Object 'System.Collections.Generic.List[string]'
    foreach ($entry in @(
        @('Protected item', 'ProtectedDetails'),
        @('Unsafe/malformed item', 'UnsafeDetails')
    )) {
        foreach ($detail in @(Get-TpmTransactionField -Object $Result -Name $entry[1] -Default @())) {
            $redacted = (Redact-TpmSupportText -Text ([string]$detail)).Text
            if (Test-TpmTransactionUserSafeSummary -Summary $redacted) {
                [void]$rows.Add(('{0}: {1}' -f $entry[0], $redacted))
            } else {
                [void]$rows.Add(('{0}: review the per-item ownership or path detail in Details/support evidence.' -f $entry[0]))
            }
        }
    }
    foreach ($warning in @(Get-TpmTransactionField -Object $Result -Name 'NativeShaderWarnings' -Default @())) {
        $game = Get-TpmTransactionPresentationItemLabel -Item ([pscustomobject]@{ Name = [string](Get-TpmTransactionField -Object $warning -Name 'Game' -Default 'Selected item') })
        $warningText = [string](Get-TpmTransactionField -Object $warning -Name 'Warning' -Default 'Native settings were preserved; display effects may stack.')
        $redactedWarning = (Redact-TpmSupportText -Text $warningText).Text
        if (-not (Test-TpmTransactionUserSafeSummary -Summary $redactedWarning)) {
            $redactedWarning = 'Native settings were preserved; display effects may stack.'
        }
        [void]$rows.Add(('Native settings preserved for {0}: {1}' -f $game, $redactedWarning))
    }
    return @($rows)
}

function Get-TpmDirectoryEntriesWithDiscoveryProgress {
    param(
        [Parameter(Mandatory)][string]$DirectoryPath,
        [Parameter(Mandatory)][string]$ProgressLabel,
        [string]$Filter = '*.xml',
        [ValidateSet('Continue', 'SilentlyContinue', 'Stop')][string]$EnumerationErrorAction = 'Continue',
        [switch]$IncludeDirectories,
        [switch]$Force,
        [switch]$DirectoriesOnly
    )
    $directoryOnly = [bool]$DirectoriesOnly
    $fileOnly = -not [bool]$IncludeDirectories -and -not $directoryOnly
    $entries = New-Object System.Collections.Generic.List[object]
    $discoveryStarted = Get-Date
    $discoveryCurrent = 0
    Write-TpmCompactExtractionProgress -Phase Scanning -Label $ProgressLabel -Current $discoveryCurrent -Total 0 -StartedAt $discoveryStarted
    $discoveryErrors=@()
    $discoveryCurrentCompleted = $false
    try {
        Get-ChildItem -LiteralPath $DirectoryPath -Filter $Filter -File:$fileOnly -Directory:$directoryOnly -Force:$Force -ErrorAction $EnumerationErrorAction -ErrorVariable discoveryErrors | ForEach-Object {
            $discoveryCurrent++
            [void]$entries.Add($_)
            Write-TpmCompactExtractionProgress -Phase Scanning -Label $ProgressLabel -Current $discoveryCurrent -Total 0 -StartedAt $discoveryStarted
        }
        $discoveryCurrentCompleted = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label $ProgressLabel -Current $discoveryCurrent -Total 0 -StartedAt $discoveryStarted -Complete -Outcome $(if ($discoveryCurrentCompleted) { 'Final' } else { 'Error' })
    }
    if (@($discoveryErrors).Count -gt 0) {
        Write-Host ("  WARNING: {0} enumeration incomplete -- {1} -- results may be missing." -f $ProgressLabel, $DirectoryPath) -ForegroundColor Yellow
        Write-Log "Discovery incomplete: $ProgressLabel at $DirectoryPath -- $(@($discoveryErrors)[0])"
    }
    return $entries.ToArray()
}

function Get-TpmRegisteredProfileFilesWithDiscoveryProgress {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][string]$ProgressLabel,
        [ValidateSet('SilentlyContinue', 'Stop')][string]$EnumerationErrorAction = 'Stop',
        [switch]$IncludeDirectories
    )
    return (Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $UserProfilesDir -ProgressLabel $ProgressLabel -Filter '*.xml' -EnumerationErrorAction $EnumerationErrorAction -IncludeDirectories:$IncludeDirectories)
}

function Get-TpmRegisteredProfileCodes {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$ProgressLabel)
    $profileCandidates = New-Object System.Collections.Generic.List[object]
    $profileDiscoveryLabel = "$ProgressLabel discovery"
    $profileDiscoveryStarted = Get-Date
    $profileDiscoveryCurrent = 0
    Write-TpmCompactExtractionProgress -Phase Scanning -Label $profileDiscoveryLabel -Current $profileDiscoveryCurrent -Total 0 -StartedAt $profileDiscoveryStarted
    $profileDiscoveryErrors=@()
    $profileDiscoveryCurrentCompleted = $false
    try {
        Get-ChildItem -LiteralPath $UserProfilesDir -Filter '*.xml' -File -ErrorAction SilentlyContinue -ErrorVariable profileDiscoveryErrors | ForEach-Object {
            $profileDiscoveryCurrent++
            [void]$profileCandidates.Add($_)
            Write-TpmCompactExtractionProgress -Phase Scanning -Label $profileDiscoveryLabel -Current $profileDiscoveryCurrent -Total 0 -StartedAt $profileDiscoveryStarted
        }
        $profileDiscoveryCurrentCompleted = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label $profileDiscoveryLabel -Current $profileDiscoveryCurrent -Total 0 -StartedAt $profileDiscoveryStarted -Complete -Outcome $(if ($profileDiscoveryCurrentCompleted) { 'Final' } else { 'Error' })
    }
    if (@($profileDiscoveryErrors).Count -gt 0) {
        Write-Host ("  WARNING: {0} enumeration incomplete -- {1} -- results may be missing." -f $profileDiscoveryLabel, $UserProfilesDir) -ForegroundColor Yellow
        Write-Log "Discovery incomplete: $profileDiscoveryLabel at $UserProfilesDir -- $(@($profileDiscoveryErrors)[0])"
    }
    $profiles = @($profileCandidates.ToArray() | Sort-Object BaseName)
    $codes = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $scanStarted = Get-Date
    $current = 0
    $currentDone = $false
    try {
        foreach ($profileFile in $profiles) {
            $current++
            Write-TpmCompactExtractionProgress -Phase 'Scanning' -Label $ProgressLabel -Current $current -Total $profiles.Count -StartedAt $scanStarted
            [void]$codes.Add($profileFile.BaseName)
        }
        $currentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase 'Scanning' -Label $ProgressLabel -Current $(if ($currentDone) { $profiles.Count } else { $current - 1 }) -Total $profiles.Count -Complete -Outcome $(if ($currentDone) { 'Final' } else { 'Error' })
    }
    return ,$codes
}

# FIX46 (owner S1): the ReShade setup runs inside one group progress bar ("ReShade setup"). Its interactive part -- the preview gallery,
# the profile chooser and the confirmation menus before installation -- must not share the console with that live bar: the owner saw the
# bar row "ReShade setup: Starting" drawn between the chooser's Choose line and its prompt, with the profile list gone, because the bar's
# redraws and the chooser's cursor-addressed output moved the same console cursor. The bar is suspended once for the whole interactive
# part (its row removed, its clock paused, never redrawn while the user decides) and resumed exactly once, when installation starts or
# the setup ends in any way. The hold counts like a prompt in the progress module, so prompts inside it keep their own pairing.
function Set-TpmReShadeSetupStage {
    param([Parameter(Mandatory)][string]$Stage)
    if (-not (Get-Command -Name Test-TpmProgressGroupOwned -ErrorAction SilentlyContinue)) { return }
    if (-not (Test-TpmProgressGroupOwned)) { return }
    Set-TpmProgressStage -Stage $Stage -StageOnly
}

function Enter-TpmReShadeInteractiveProgressHold {
    if ([bool](Get-Variable -Name TpmReShadeProgressHeld -Scope Script -ValueOnly -ErrorAction SilentlyContinue)) { return }
    if (-not (Get-Command -Name Suspend-TpmProgressLine -ErrorAction SilentlyContinue)) { return }
    if (-not (Get-Command -Name Test-TpmProgressActive -ErrorAction SilentlyContinue)) { return }
    if (-not (Test-TpmProgressActive)) { return }
    # Recorded before the call: the module counts the suspension before it erases the bar row, so even a failed erase is paired.
    $script:TpmReShadeProgressHeld = $true
    Suspend-TpmProgressLine
}

function Exit-TpmReShadeInteractiveProgressHold {
    param([string]$Stage = '')
    if (-not [bool](Get-Variable -Name TpmReShadeProgressHeld -Scope Script -ValueOnly -ErrorAction SilentlyContinue)) { return }
    $script:TpmReShadeProgressHeld = $false
    if ($Stage) { Set-TpmReShadeSetupStage -Stage $Stage }
    if (Get-Command -Name Resume-TpmProgressLine -ErrorAction SilentlyContinue) { Resume-TpmProgressLine }
}

function Invoke-ReShadeSetup {
    param(
        [ValidateSet('Select','Adopt')][string]$Action='Select',[string]$UserProfilesDir,[string]$SourceDll,
        [string]$ConfigPath,[string]$TpRoot,[string]$Mode,[string]$ZipSource,[string]$GamesInstallFolder,[bool]$RetroBat,[string]$ZipSourceSupplementary = ''
    )
    try {
        $legacy=Invoke-ReShadeSetupLegacy -Action $Action -UserProfilesDir $UserProfilesDir -SourceDll $SourceDll -ConfigPath $ConfigPath -TpRoot $TpRoot -Mode $Mode -ZipSource $ZipSource -GamesInstallFolder $GamesInstallFolder -RetroBat $RetroBat -ZipSourceSupplementary $ZipSourceSupplementary
    } finally {
        # An early return, a cancel or a failure inside the interactive part never leaves the setup's progress bar suspended.
        Exit-TpmReShadeInteractiveProgressHold
    }
    if ($null -eq $legacy) { $legacy=[pscustomobject]@{ Succeeded=$false; Cancelled=$true; Deployed=0; Errors=0; Reason='USER_CANCELLED' } }
    $items=@(Get-TpmTransactionField -Object $legacy -Name 'SelectedItems' -Default @())
    $changed=@(Get-TpmTransactionField -Object $legacy -Name 'ChangedItems' -Default @())
    $skipped=@(Get-TpmTransactionField -Object $legacy -Name 'SkippedItems' -Default @())
    $failed=@(Get-TpmTransactionField -Object $legacy -Name 'FailedItems' -Default @())
    $unverified=@(Get-TpmTransactionField -Object $legacy -Name 'UnverifiedItems' -Default @())
    $deployedCount=[int](Get-TpmTransactionField -Object $legacy -Name 'Deployed' -Default 0)
    $legacyErrors=Get-TpmTransactionField -Object $legacy -Name 'Errors' -Default 0
    $errorCount=if ($legacyErrors -is [ValueType]) { [int]$legacyErrors } else { @($legacyErrors).Count }
    $notApplied=$errorCount
    foreach($countName in 'Skipped','Protected','Unsafe','MissingPath','MissingDevice'){ $notApplied += [int](Get-TpmTransactionField -Object $legacy -Name $countName -Default 0) }
    $cancelled=[bool](Get-TpmTransactionField -Object $legacy -Name 'Cancelled' -Default $false)
    $completeRun=($null -ne (Get-TpmTransactionField -Object $legacy -Name 'Accounting'))
    $outcome=if($unverified.Count -gt 0){'ACTION_REQUIRED'}elseif($deployedCount -gt 0 -and $notApplied -gt 0){'PARTIAL_APPLIED'}elseif($deployedCount -gt 0){'SUCCEEDED'}elseif($cancelled -or ($completeRun -and $notApplied -eq 0)){'NO_OP'}else{'FAILED_BEFORE_MUTATION'}
    $nativeRestoreItems=@(Get-TpmTransactionField -Object $legacy -Name 'NativeCrtNeedsRestoreItems' -Default @())
    $summary=switch($outcome){
        'SUCCEEDED'{'ReShade profiles were applied and verified.'}
        'PARTIAL_APPLIED'{'ReShade profiles were applied to some selected games; the others were left unchanged.'}
        'ACTION_REQUIRED'{ if ($nativeRestoreItems.Count -gt 0 -and $nativeRestoreItems.Count -ge $unverified.Count) {'ReShade was installed, but at least one game profile may be damaged and has to be restored from the saved copy.'} else {'ReShade files were written for at least one game but the final state could not be verified.'} }
        'FAILED_BEFORE_MUTATION'{'ReShade setup did not apply any profile.'}
        default{'ReShade setup made no changes.'}
    }
    $reasonCode=switch($outcome){'SUCCEEDED'{'PROFILES_PROCESSED'}'PARTIAL_APPLIED'{'PROFILES_PARTIALLY_APPLIED'}'ACTION_REQUIRED'{'DEPLOYMENT_UNVERIFIED'}'FAILED_BEFORE_MUTATION'{'PROFILES_NOT_APPLIED'}default{'NO_CHANGES_NEEDED'}}
    # FIX72: games that were only left alone (protected, missing, unsafe) with no error and nothing unverified are a normal result that needs the
    # user's choice. The code tells the progress row and the workflow status that nothing failed.
    if ($errorCount -eq 0 -and $unverified.Count -eq 0 -and -not $cancelled -and $completeRun -and $notApplied -gt 0) { $reasonCode='SOME_GAMES_NOT_CHANGED' }
    return (ConvertTo-TpmLegacyTransactionResult -Legacy $legacy -WorkflowKey 'ReShade' -OperationKey 'DeployProfiles' -Items $items -ChangedItems $changed -CompletedItems $changed -FailedItems $failed -SkippedItems $skipped -Summary $summary -ReasonCode $reasonCode -Outcome $outcome -MutationStarted ($changed.Count -gt 0 -or $unverified.Count -gt 0) -FinalPassed ($unverified.Count -eq 0))
}
function Invoke-ReShadeSetupLegacy {
    param(
        [ValidateSet('Select','Adopt')][string]$Action = 'Select',
        [string]$UserProfilesDir,
        [string]$SourceDll,      # 64-bit DLL path (caller guarantees it exists)
        [string]$ConfigPath,
        [string]$TpRoot,
        [string]$Mode,
        [string]$ZipSource,
        [string]$GamesInstallFolder,
        [bool]$RetroBat,
        [string]$ZipSourceSupplementary = ''
    )
    $generatedPresetPath = $null
    $presetPath = $null
    # FIX96: the configured source collection folders (main and supplementary). A game inside one of them is never changed.
    $sourceCollectionRoots = @($ZipSource, $ZipSourceSupplementary)

    if ([string]::IsNullOrWhiteSpace($SourceDll) -or -not (Test-Path -LiteralPath $SourceDll -PathType Leaf)) {
        Write-Host '  ReShade setup stopped: a valid 64-bit ReShade source DLL was not found.' -ForegroundColor Yellow
        Write-Log 'ReShade setup blocked: SourceDll was empty or did not resolve to a file.'
        return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 0; Reason = 'SOURCE_DLL_UNAVAILABLE' }
    }
    # Initialize one validated cache before any game processing.
    $reShadeCacheRoot = if($script:TpmOwnedLayout){Join-Path $script:TpmOwnedLayout.Assets 'ReShade'}else{Join-Path $PSScriptRoot 'ReShade'}
    try {
        if ([string]::IsNullOrWhiteSpace($reShadeCacheRoot)) { throw 'The ReShade cache path resolved to an empty string.' }
        [void][IO.Directory]::CreateDirectory($reShadeCacheRoot)
        if (-not (Test-TpmNoReparsePath -Path $reShadeCacheRoot)) { throw 'The ReShade cache path is unavailable or uses a reparse point.' }
    } catch {
        Write-Host ("  ReShade setup stopped: its local cache is unavailable ({0}). No game files were changed." -f $_.Exception.Message) -ForegroundColor Yellow
        Write-Log ("ReShade setup blocked once before game processing: CACHE_UNAVAILABLE -- {0}" -f $_.Exception.Message)
        return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 0; Skipped = 0; Reason = 'CACHE_UNAVAILABLE' }
    }


    Set-TpmReShadeSetupStage -Stage 'Checking the ReShade files'
    # Version, Authenticode signature and SHA-256 of the DLL, checked before it is deployed anywhere. FIX64: the screen gets ONE short
    # notice; every fact stays in the log and behind the chooser's [D] Details.
    $dllChecks = @(Get-TpmReShadeDllCheck -Path $SourceDll -Label '64-bit')
    $bVer = $null
    if ($dllChecks[0].Version) { $bVer = $dllChecks[0].Version }
    Write-Host ''
    foreach ($noticeLine in @(Get-TpmReShadeDllNoticeLines -Checks $dllChecks -TextWidth (Get-TpmReShadeScreenTextWidth))) { Write-Host $noticeLine.Text -ForegroundColor $noticeLine.Color }
    $updateResult = Invoke-ReShadeUpdateIfAvailable -SourceDll $SourceDll -InstalledVersion $bVer
    if ($updateResult.Updated) {
        $SourceDll = $updateResult.SourceDll
        # The updated DLL is checked again, so the Details and the log describe the file that will be used.
        $dllChecks = @(Get-TpmReShadeDllCheck -Path $SourceDll -Label '64-bit')
        if ($dllChecks[0].Version) { $bVer = $dllChecks[0].Version }
    }

    Enter-TpmReShadeInteractiveProgressHold

    # The preview selector and terminal list update the same transient profile
    # selection. Keep the terminal path usable when WinForms is unavailable.
    # HDR choices (and their group) appear only when real display detection allows them; the preview selector lists only choices that
    # can be selected right now, while the terminal chooser also names HDR choices that are supported but currently unavailable.
    $startupHdrGate = Get-TpmReShadeHdrGate
    $galleryProfiles = @(Get-TpmReShadeVisibleProfiles -HdrGate $startupHdrGate)
    $selectableGalleryProfiles = @($galleryProfiles | Where-Object { -not (Test-TpmReShadeProfileRequiresHdr -Entry $_) -or [bool]$startupHdrGate.Enabled })
    $galleryResult = Show-TpmReShadeProfileGalleryWindow -Profiles $selectableGalleryProfiles -DefaultProfileId 'Original' -Show -NonModal
    $gallerySession = if ($galleryResult.Available) { $galleryResult.Session } else { $null }
    if (-not $galleryResult.Available) {
        Write-TpmReShadeWrappedText -Text 'ReShade visual gallery unavailable; choose a profile in the terminal.' -Color Yellow
        Write-Log ("ReShade visual gallery unavailable before terminal chooser: {0}" -f $galleryResult.Reason)
    }
    try {
        $chooserResult = Read-TpmReShadeTerminalProfile -Profiles $galleryProfiles -PreviewSession $gallerySession -DllChecks $dllChecks
        if ($chooserResult.PSObject.Properties['PreviewSession']) { $gallerySession = $chooserResult.PreviewSession }
    } finally {
        Close-TpmReShadeProfileGallerySession -Session $gallerySession
    }
    if ($chooserResult.Cancelled -or -not $chooserResult.SelectedProfile) {
        Write-TpmReShadeWrappedText -Text 'ReShade setup canceled. No files were changed.' -Color Yellow
        Write-Log 'ReShade setup: terminal profile chooser canceled before confirmation.'
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $true; Deployed = 0; Errors = 0; Reason = 'PROFILE_SELECTION_CANCELLED' }
    }
    $selectedProfile = $chooserResult.SelectedProfile
    Write-Log ("ReShade profile chooser: selected {0}; explicit confirmation still required." -f $selectedProfile.ProfileId)
    # An HDR-only choice is re-checked against live display evidence right now; the evidence fingerprint travels to the deployment guard
    # so a change between this moment and deployment is detected.
    $hdrExpectedFingerprint = ''
    if (Test-TpmReShadeProfileRequiresHdr -Entry $selectedProfile) {
        $selectionHdrGate = Get-TpmReShadeHdrGate
        if (-not [bool]$selectionHdrGate.Enabled) {
            Write-Host ('  {0} needs Windows HDR to be active, and it is not right now: {1}' -f $selectedProfile.FriendlyName, $selectionHdrGate.Reason) -ForegroundColor Yellow
            Write-Log ('ReShade setup: HDR profile refused at selection -- {0}' -f $selectionHdrGate.Reason)
            return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 0; Reason = 'HDR_UNAVAILABLE' }
        }
        $hdrExpectedFingerprint = [string]$selectionHdrGate.Fingerprint
    }
    $customPresetChoice = Read-TpmChoice -Prompt ("  Use the selected ReShade profile?`n  ({0} will be applied. Choose a custom ReShade .ini preset only if you already have one.)`n`n  [Y] Yes, use {0}  [S] Custom preset  [B] Back`n  Choice (default Y)" -f $selectedProfile.FriendlyName) -Choices @('Y', 'S', 'B') -Default 'Y'
    if ($customPresetChoice -eq 'S') {
        $pInp = Read-PathWithBrowse "  Path to your ReShade preset (.ini) file" -Mode File -FileFilter "ReShade preset (*.ini)|*.ini|All files (*.*)|*.*"
        $customPath = Resolve-ReShadeCustomPresetPath -InputPath $pInp
        if ($customPath) { $presetPath = $customPath; Write-Host "  Custom preset selected." -ForegroundColor DarkGray }
        else { Write-Host "  That preset could not be used (it must be an existing .ini file). The selected ReShade profile will be used instead." -ForegroundColor Yellow }
    } elseif ($customPresetChoice -eq 'B') {
        Write-Host '  ReShade setup canceled. No files were changed.' -ForegroundColor DarkGray
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $true; Deployed = 0; Errors = 0; Reason = 'USER_CANCELLED' }
    }

    # Per-game preset overrides: ReShadePresets\<ProfileCode>.ini always wins
    # over the global choice above for that one game. Same convention as
    # CustomThumbnails\<ProfileCode>.png (Invoke-ThumbnailDownload) -- file
    # name is the profile code, validated against registered profiles, with
    $reShadePresetsDir = if($script:TpmOwnedLayout){Join-Path $script:TpmOwnedLayout.Assets 'ReShadePresets'}else{Join-Path $PSScriptRoot "ReShadePresets"}
    if (Test-Path -LiteralPath $reShadePresetsDir) {
        try {
            $presetFiles = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $reShadePresetsDir -ProgressLabel 'ReShade preset file discovery' -Filter '*.ini' -EnumerationErrorAction Stop)
        } catch {
            Write-Host ('  ReShade preset discovery failed; setup stopped before any change: {0}' -f $_.Exception.Message) -ForegroundColor Red
            Write-Log ('ReShade setup: preset discovery failed; no changes made: {0}' -f $_.Exception.Message)
            return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 1; Reason = 'PRESET_DISCOVERY_FAILED' }
        }
        if ($presetFiles.Count -gt 0) {
            $knownPresetCodes = Get-TpmRegisteredProfileCodes -UserProfilesDir $UserProfilesDir -ProgressLabel 'ReShade preset profile-code scan'
            foreach ($pfile in $presetFiles) {
                $code = [System.IO.Path]::GetFileNameWithoutExtension($pfile.Name)
                if (-not $knownPresetCodes.Contains($code)) {
                    Write-Host ("  WRONG NAME: ReShadePresets\{0}" -f $pfile.Name) -ForegroundColor Yellow
                    Write-Host ("             '{0}' does not match any registered game profile code." -f $code) -ForegroundColor Yellow
                    Write-Host "             Check TeknoParrot-Manager-controls.txt for the correct" -ForegroundColor Yellow
                    Write-Host "             name, rename the file, then re-run. File will be ignored." -ForegroundColor Yellow
                    Write-Log "ReShade: per-game preset $($pfile.Name) -- no matching profile code, ignored."
                }
            }
        }
    }

    # Game selection
    Write-Host ""
    Write-Host "  Which games should get ReShade?" -ForegroundColor Cyan
    Write-Host "  You can run setup again later to add or change individual games." -ForegroundColor DarkCyan
    $selectedGames = @(Select-RegisteredGamesInteractive -UserProfilesDir $UserProfilesDir)
    if ($selectedGames.Count -eq 0) {
        Write-Host "  No games selected. ReShade setup canceled." -ForegroundColor Yellow
        Write-Log "ReShade setup: canceled -- no games selected."
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $true; Deployed = 0; Errors = 0; SelectedItems = @(); ChangedItems = @(); SkippedItems = @(); FailedItems = @(); Reason = 'NO_GAMES_SELECTED' }
    }
    $nativeShaderWarnings = New-Object System.Collections.Generic.List[object]
    $nativeScanStarted = Get-Date
    $nativeScanCurrent = 0
    foreach ($nativeProfile in $selectedGames) {
        $nativeScanCurrent++
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade native shader scan' -Current $nativeScanCurrent -Total $selectedGames.Count -StartedAt $nativeScanStarted
        try {
            $nativeDoc = Read-Xml $nativeProfile.FullName
            $nativeWarning = Get-TpmReShadeNativeShaderWarnings -Document $nativeDoc
            if ($nativeWarning.Detected) {
                [void]$nativeShaderWarnings.Add([pscustomobject]@{ Game = $nativeProfile.BaseName; Fields = @($nativeWarning.Fields); Warning = $nativeWarning.Warning })
            }
        } catch {
            Write-Log ("ReShade: native shader setting scan unavailable for {0} -- {1}" -f $nativeProfile.BaseName, $_.Exception.Message)
        }
    }
    if ($selectedGames.Count -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade native shader scan' -Current $nativeScanCurrent -Total $selectedGames.Count -StartedAt $nativeScanStarted -Complete }
    # FIX72: the facts that used to scroll past one game at a time are collected here. The result screen shows a short summary and keeps all
    # of them behind [D] Details; every one is also written to the log.
    $detailNotes = New-Object System.Collections.Generic.List[string]
    $protectedRecords = New-Object System.Collections.Generic.List[object]
    $appliedGames = New-Object System.Collections.Generic.List[string]
    $preflightSummary = Get-TpmReShadeApplyPreflight -SelectedGames $selectedGames -ProfileDefinition $selectedProfile -SourceDll $SourceDll -ProtectedRoots $sourceCollectionRoots
    $preflightLine = ("ReShade preflight: {0} ready, {1} protected, {2} missing executable, {3} unsafe or malformed." -f $preflightSummary.Ready, $preflightSummary.Protected, $preflightSummary.MissingPath, $preflightSummary.Unsafe)
    Write-Log $preflightLine
    [void]$detailNotes.Add($preflightLine)
    if ($preflightSummary.Protected -gt 0) {
        Write-Log 'ReShade preflight: protected installs remain unchanged unless the separate, explicit Adopt action is used.'
        [void]$detailNotes.Add('Protected installs remain unchanged unless the separate, explicit Adopt action is used.')
        if ($Action -eq 'Adopt') {
            Write-Host ''
            Write-TpmText -Text 'Some games already have ReShade files.' -Color Yellow
            Write-TpmText -Text 'TeknoParrot Manager left them alone to protect your own setup.' -Color Yellow
            Write-TpmText -Text 'You chose to replace them with TeknoParrot Manager''s ReShade.' -Color Yellow
            Write-TpmText -Text 'TeknoParrot Manager saves a copy of the old files first.' -Color Yellow
            Write-TpmText -Text 'To put them back later, use ReShade > Undo ReShade changes.' -Color Yellow
        }
    }
    # FIX73: TeknoParrot's own CRT shader. Short plain notice, a K/T choice only for a CRT look in an interactive run, game names and settings only
    # under Details and in the log. The choice is made here, the change happens later, per game, right after ReShade was installed on it.
    # Records is made with ::new(), not New-Object: @() over a New-Object List[object] throws 'Argument types do not match' (PowerShell #27558).
    $nativeCrtState = [pscustomobject]@{ Requested = $false; Items = @{}; NotOffered = @(); OtherLook = (New-Object 'System.Collections.Generic.List[string]'); BackupTried = $false; BackupOk = $false; BackupPath = ''; BackupReason = ''; Records = [System.Collections.Generic.List[object]]::new(); UndoReady = (New-Object 'System.Collections.Generic.List[string]') }
    $nativeCrtPlan = $null
    if ($nativeShaderWarnings.Count -gt 0) {
        foreach ($nativeWarning in $nativeShaderWarnings) {
            Write-Log ("ReShade: native display settings kept in {0}: {1}" -f $nativeWarning.Game, (($nativeWarning.Fields | ForEach-Object { '{0}={1}' -f $_.Field, $_.Value }) -join '; '))
        }
        $nativeCrtPlan = Get-TpmReShadeNativeCrtPlan -Warnings @($nativeShaderWarnings.ToArray()) -SelectedGames $selectedGames -Preflight $preflightSummary -ProfileDefinition $selectedProfile -Adopt:($Action -eq 'Adopt')
        $nativeCrtAllowed = Test-TpmReShadeNativeCrtChoiceAllowed
        if ($nativeCrtPlan.Offer -and $nativeCrtAllowed) {
            if ((Read-TpmReShadeNativeCrtChoice -Plan $nativeCrtPlan -SelectedCount $selectedGames.Count) -eq 'T') {
                $nativeCrtState.Requested = $true
                $nativeCrtState.NotOffered = @($nativeCrtPlan.NotOfferedItems | ForEach-Object { [string]$_.Game })
                foreach ($nativeItem in @($nativeCrtPlan.EligibleItems)) { $nativeCrtState.Items[[string]$nativeItem.Game] = $nativeItem }
                Write-Host ''
                Write-TpmText -Text 'OK. It will be turned off only in games that get ReShade now.' -Color Green
                Write-TpmText -Text 'A saved copy of your game profiles is made first.' -Color Green
                Write-Log ("ReShade: the user chose to turn off TeknoParrot's own CRT effect for up to {0} game(s)." -f $nativeCrtState.Items.Count)
            } else {
                Write-Log "ReShade: the user kept TeknoParrot's own CRT effect."
            }
        } else {
            Write-TpmReShadeNativeGeneralNotice -Plan $nativeCrtPlan -SelectedCount $selectedGames.Count -Interactive:($nativeCrtAllowed -and (Test-TpmInteractiveInput))
        }
    }
    $bulkApply = $false
    $deployed = 0; $installed = 0; $updated = 0; $reapplied = 0; $changedProfile = 0; $keptProfile = 0; $skipped = 0; $missingPath = 0; $missingDevice = 0; $unsupported = 0; $linuxStyle = 0; $protected = 0; $adopted = 0; $unsafe = 0; $errors = 0; $presetOverrides = 0; $tutorialProgressFixed = 0
    $changedGameIds = New-Object 'System.Collections.Generic.List[string]'
    $skippedGameIds = New-Object 'System.Collections.Generic.List[string]'
    $failedGameIds = New-Object 'System.Collections.Generic.List[string]'
    $unverifiedGameIds = New-Object 'System.Collections.Generic.List[string]'
    # FIX68: the games whose undo receipt is ready, and those whose receipt was made but could not be finished ('None': no receipt).
    # FIX85: 'Check' holds the games whose receipt is finished but that a failed rollback left half changed: they are not called ready.
    $undoGames = @{ Ready = (New-Object 'System.Collections.Generic.List[string]'); Check = (New-Object 'System.Collections.Generic.List[string]'); Missing = (New-Object 'System.Collections.Generic.List[string]'); None = (New-Object 'System.Collections.Generic.List[string]') }
    $rememberedSelections = @{}
    $keepSelections = @{}
    $restoreSelections = @{}
    $willChangeNow = if ($Action -eq 'Adopt') { [int]$preflightSummary.Ready + [int]$preflightSummary.Protected } else { [int]$preflightSummary.Ready }
    if ($selectedGames.Count -gt 1) {
        do {
            $leftAlone = $selectedGames.Count - $willChangeNow
            $canChangeText = if ($willChangeNow -eq 0) { 'None of them can be changed right now.' } else { ('{0} can be changed now.' -f $willChangeNow) }
            Write-Host ''
            Write-TpmText -Text ('You selected {0}. {1}' -f (Format-TpmGameCount -Count $selectedGames.Count), $canChangeText) -Color Cyan
            if ($leftAlone -gt 0 -and $willChangeNow -gt 0) { Write-TpmText -Text ('{0} will be left alone. Press D to see why.' -f $leftAlone) -Color Yellow }
            if ($willChangeNow -gt 0) { Write-TpmText -Text ('Apply {0} to {1}?' -f $selectedProfile.FriendlyName, (Format-TpmGameCount -Count $willChangeNow)) -Color Cyan -BlankBefore }
            Write-Host $(if ($willChangeNow -gt 0) { '  [Y] Yes' } else { '  [Y] Continue' })
            Write-Host '  [S] Select games one by one'
            Write-Host '  [B] Back'
            Write-Host '  [D] Details'
            $bulkChoice = Read-TpmChoice -Prompt '  Choice, default Y' -Choices @('Y', 'S', 'B', 'D') -Default 'Y'
            if ($bulkChoice -eq 'D') {
                Write-TpmText -Text ("Profile: {0} -- {1}" -f $selectedProfile.FriendlyName, $selectedProfile.Description) -Color DarkGray -BlankBefore
                Write-TpmText -Text $preflightLine -Color DarkGray
                foreach ($leftRecord in @($preflightSummary.Records | Where-Object { $_.Status -ne 'Ready' -and -not ($Action -eq 'Adopt' -and $_.Status -eq 'Protected') })) {
                    Write-TpmText -Text ('Left alone: {0} -- {1}' -f $leftRecord.Game, $(if ([string]::IsNullOrWhiteSpace([string]$leftRecord.Detail)) { 'it could not be checked safely' } else { [string]$leftRecord.Detail })) -Color DarkGray
                }
                if ($null -ne $nativeCrtPlan) { Show-TpmReShadeNativeDetails -Plan $nativeCrtPlan }
            }
        } while ($bulkChoice -eq 'D')
        if ($bulkChoice -eq 'B') { Write-Host '  ReShade setup canceled. No files were changed.' -ForegroundColor Yellow; Write-Log 'ReShade setup: canceled at the apply-scope menu.'; return [pscustomobject]@{ Succeeded = $false; Cancelled = $true; Deployed = 0; Errors = 0; Reason = 'USER_CANCELLED' } }
        $bulkApply = ($bulkChoice -eq 'Y')
    }
    $conflicts = @()
    if ($bulkApply) {
        $conflictScanStarted = Get-Date
        $conflictScanCurrent = 0
        $conflictScanCurrentDone = $false
        try {
            foreach ($pf in $selectedGames) {
                $conflictScanCurrent++
                Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'ReShade bulk conflict scan' -Current $conflictScanCurrent -Total $selectedGames.Count -StartedAt $conflictScanStarted
                $options = Get-TpmReShadeChooserOptions -GameId $pf.BaseName
                if ($options.Restore.Found -and $options.Restore.Valid -and $options.Restore.Profile.ProfileId -ne $selectedProfile.ProfileId) {
                    $conflicts += [pscustomobject]@{ Game = $pf; Previous = $options.Restore }
                } elseif ($options.Restore.Found -and -not $options.Restore.Valid -and [string]$options.Restore.Reason -eq 'RETIRED_PROFILE' -and $options.Restore.PSObject.Properties['RetiredProfileId']) {
                    # The game's installed preset came from a profile that is no longer offered: it is a conflict too, so the user can keep it with [K].
                    $retiredEntry = Get-TpmReShadeRetiredProfile -ProfileId ([string]$options.Restore.RetiredProfileId)
                    $retiredName = if ($retiredEntry) { [string]$retiredEntry.FriendlyName } else { [string]$options.Restore.RetiredProfileId }
                    $conflicts += [pscustomobject]@{ Game = $pf; Previous = [pscustomobject]@{ Found = $true; Valid = $false; Reason = 'RETIRED_PROFILE'; Profile = [pscustomobject]@{ ProfileId = [string]$options.Restore.RetiredProfileId; FriendlyName = ($retiredName + ' (no longer offered)') } } }
                }
            }
            $conflictScanCurrentDone = $true
        } finally {
            Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'ReShade bulk conflict scan' -Current $(if ($conflictScanCurrentDone) { $conflictScanCurrent } else { $conflictScanCurrent - 1 }) -Total $selectedGames.Count -StartedAt $conflictScanStarted -Complete -Outcome $(if ($conflictScanCurrentDone) { 'Final' } else { 'Error' })
        }
        if ($conflicts.Count -gt 0) {
            Write-Host ("  Previously TeknoParrot Manager-managed: {0} {1} a different profile." -f (Format-TpmGameCount -Count $conflicts.Count), $(if ($conflicts.Count -eq 1) { 'uses' } else { 'use' })) -ForegroundColor Yellow
            foreach ($conflict in $conflicts) {
                Write-Host ("    {0}: Previously TeknoParrot Manager-managed: {1}; Selected now: {2}" -f $conflict.Game.BaseName, $conflict.Previous.Profile.FriendlyName, $selectedProfile.FriendlyName) -ForegroundColor DarkCyan
            }
            do {
                Write-Host '  [A] Change these TeknoParrot Manager-managed games to the selected profile'
                Write-Host '  [K] Keep their current profiles'
                Write-Host '  [S] Select games manually'
                Write-Host '  [D] Details'
                Write-Host '  [B] Back'
                $conflictChoice = Read-TpmChoice -Prompt '  Choice, default A' -Choices @('A', 'K', 'S', 'B', 'D') -Default 'A'
                if ($conflictChoice -eq 'D') { Write-Host '  A changes only TeknoParrot Manager-owned profiles; K leaves those game folders untouched.' -ForegroundColor DarkGray }
            } while ($conflictChoice -eq 'D')
            if ($conflictChoice -eq 'B') { Write-Host '  ReShade setup canceled. No files were changed.' -ForegroundColor Yellow; Write-Log 'ReShade setup: canceled at the profile-conflict menu.'; return [pscustomobject]@{ Succeeded = $false; Cancelled = $true; Deployed = 0; Errors = 0; Reason = 'USER_CANCELLED' } }
            if ($conflictChoice -eq 'S') { $bulkApply = $false }
            if ($conflictChoice -eq 'K') { foreach ($conflict in $conflicts) { $keepSelections[$conflict.Game.BaseName] = $conflict.Previous } }
        }
    }
    $askableNames = $null
    if (-not $bulkApply) {
        if ($selectedGames.Count -gt 1) {
            # Ask only about games that can be changed now. ($askableNames holds the games that cannot be: it is a skip list.) The others stay in the list and are reported as left alone, as before.
            $askableNames = @{}
            foreach ($leftRecord in @($preflightSummary.Records)) {
                $isAskable = ($leftRecord.Status -eq 'Ready') -or ($Action -eq 'Adopt' -and $leftRecord.Status -eq 'Protected')
                if (-not $isAskable) { $askableNames[([string]$leftRecord.Game).ToLowerInvariant()] = $false }
            }
            $askGames = @($selectedGames | Where-Object { -not $askableNames.ContainsKey(([string]$_.BaseName).ToLowerInvariant()) })
            $notAskedGames = @($selectedGames | Where-Object { $askableNames.ContainsKey(([string]$_.BaseName).ToLowerInvariant()) })
            if ($notAskedGames.Count -gt 0) { Write-TpmText -Text ('Asking only about the {0} that can be changed. The other {1} will be left alone.' -f (Format-TpmGameCount -Count $askGames.Count), $notAskedGames.Count) -Color Yellow -BlankBefore }
            $answers = @{}
            $askIndex = 0
            $backedOut = $false
            while ($askIndex -lt $askGames.Count) {
                $pf = $askGames[$askIndex]
                $askAnswer = Read-TpmChoice -Prompt ("  Install for {0}? [Y] Yes  [N] No  [B] Back  (game {1} of {2}, default Y)" -f $pf.BaseName, ($askIndex + 1), $askGames.Count) -Choices @('Y', 'N', 'B') -Default 'Y'
                if ($askAnswer -eq 'B') {
                    if ($askIndex -eq 0) { $backedOut = $true; break }
                    $askIndex--
                    continue
                }
                $answers[$pf.BaseName] = ($askAnswer -eq 'Y')
                $askIndex++
            }
            if ($backedOut) { Write-Host '  ReShade setup canceled. No files were changed.' -ForegroundColor Yellow; Write-Log 'ReShade setup: canceled at the first one-by-one question.'; return [pscustomobject]@{ Succeeded = $false; Cancelled = $true; Deployed = 0; Errors = 0; Reason = 'USER_CANCELLED' } }
            $chosenGames = @($askGames | Where-Object { $answers[$_.BaseName] })
            if ($chosenGames.Count -eq 0) { Write-Host '  ReShade setup canceled. No files were changed.' -ForegroundColor Yellow; Write-Log 'ReShade setup: canceled -- no game was chosen one by one.'; return [pscustomobject]@{ Succeeded = $false; Cancelled = $true; Deployed = 0; Errors = 0; Reason = 'USER_CANCELLED' } }
            $selectedGames = @($chosenGames) + @($notAskedGames)
        }
        foreach ($pf in $selectedGames) {
            if ($null -ne $askableNames -and $askableNames.ContainsKey(([string]$pf.BaseName).ToLowerInvariant())) { continue }
            $options = Get-TpmReShadeChooserOptions -GameId $pf.BaseName
            if ($options.Restore.Found -and $options.Restore.Valid) {
                Write-Host ("  R) Reapply previous trusted profile for {0}: {1}" -f $pf.BaseName, $options.Restore.Profile.FriendlyName) -ForegroundColor DarkCyan
                $restoreAnswer = Read-TpmYesNo -Prompt ("  Reapply {0} for this game? (Y/N, default N)" -f $options.Restore.Profile.FriendlyName) -Default 'N'
                if ($restoreAnswer -match '^(Y|y)$') { $restoreSelections[$pf.BaseName] = $options.Restore }
            } elseif ($options.Restore.Found) {
                Write-Host (Get-TpmReShadePreviousProfileNotice -GameName $pf.BaseName -Reason ([string]$options.Restore.Reason)) -ForegroundColor Yellow
            }
            if ($options.Remembered.Found -and $options.Remembered.Valid -and -not $restoreSelections.ContainsKey($pf.BaseName)) {
                Write-Host ("  Remembered for {0}: {1}" -f $pf.BaseName, $options.Remembered.Profile.FriendlyName) -ForegroundColor DarkCyan
                $rememberAnswer = Read-TpmYesNo -Prompt ("  Use remembered {0} for this game? (Y/N, default N)" -f $options.Remembered.Profile.FriendlyName) -Default 'N'
                if ($rememberAnswer -match '^(Y|y)$') { $rememberedSelections[$pf.BaseName] = $options.Remembered }
            }
        }
    }
    if ($selectedProfile.ProfileId -ne 'Original' -and -not $presetPath) {
        $generatedPresetPath = Join-Path ([System.IO.Path]::GetTempPath()) ('TPM-ReShade-' + [guid]::NewGuid().ToString('N') + '.ini')
        try {
            [System.IO.File]::WriteAllText($generatedPresetPath, (New-TpmReShadePresetContent -ProfileDefinition $selectedProfile), (New-Object System.Text.UTF8Encoding $false))
            $presetPath = $generatedPresetPath
        } catch {
            Write-Log "ReShade: failed to generate selected profile preset -- $_"
            Write-Host "  Could not prepare the selected profile. No files were changed." -ForegroundColor Yellow
            return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 1; Reason = 'PRESET_GENERATION_FAILED' }
        }
    }

# Deploy only after the explicit profile confirmation above.
    Exit-TpmReShadeInteractiveProgressHold -Stage 'Installing the selected profile'
    Write-Host ""
    $readyNow = @(@($preflightSummary.Records) | Where-Object { $_.Status -eq 'Ready' -or ($Action -eq 'Adopt' -and $_.Status -eq 'Protected') }).Count
    if ($readyNow -gt 0 -and $readyNow -lt $selectedGames.Count) {
        Write-Host ("  Installing ReShade into {0}. The other {1} cannot be changed right now and will be left alone..." -f (Format-TpmGameCount -Count $readyNow), ($selectedGames.Count - $readyNow)) -ForegroundColor Cyan
    } else {
        Write-Host ("  Installing ReShade into {0}..." -f (Format-TpmGameCount -Count $selectedGames.Count)) -ForegroundColor Cyan
    }
    $deployed = 0; $installed = 0; $updated = 0; $reapplied = 0; $changedProfile = 0; $keptProfile = 0; $skipped = 0; $missingPath = 0; $missingDevice = 0; $unsupported = 0; $linuxStyle = 0; $protected = 0; $adopted = 0; $unsafe = 0; $errors = 0; $presetOverrides = 0; $tutorialProgressFixed = 0
    $protectedDetails = New-Object System.Collections.Generic.List[string]
    $unsafeDetails = New-Object System.Collections.Generic.List[string]
    $sourceFolderGames = New-Object System.Collections.Generic.List[string]
    $pathReasonCounts = @{}
    $preflightValid = 0
    $preflightReasonCounts = @{}
    $pathPreflightStarted = Get-Date
    $pathPreflightCurrent = 0
    foreach ($preflightProfile in $selectedGames) {
        $pathPreflightCurrent++
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade apply path preflight' -Current $pathPreflightCurrent -Total $selectedGames.Count -StartedAt $pathPreflightStarted
        try {
            $preflightDoc = Read-Xml $preflightProfile.FullName
            $preflightNode = if ($preflightDoc.GameProfile) { $preflightDoc.GameProfile.SelectSingleNode('GamePath') } else { $null }
            $preflightGamePath = if ($preflightNode) { [string]$preflightNode.InnerText } else { '' }
            $preflightCheck = Test-TpmGameMutationPath -GamePath $preflightGamePath -RequireLeaf -ProtectedRoots $sourceCollectionRoots
            if ($preflightCheck.Valid) {
                $preflightValid++
            } else {
                $preflightReason = [string]$preflightCheck.ReasonCode
                if (-not $preflightReasonCounts.ContainsKey($preflightReason)) { $preflightReasonCounts[$preflightReason] = 0 }
                $preflightReasonCounts[$preflightReason]++
            }
        } catch {
            if (-not $preflightReasonCounts.ContainsKey('PROFILE_READ_FAILED')) { $preflightReasonCounts['PROFILE_READ_FAILED'] = 0 }
            $preflightReasonCounts['PROFILE_READ_FAILED']++
        }
    }
    if ($selectedGames.Count -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'ReShade apply path preflight' -Current $pathPreflightCurrent -Total $selectedGames.Count -StartedAt $pathPreflightStarted -Complete }
    $pathPreflightLine = ("Path preflight: {0} valid, {1} skipped before transaction." -f $preflightValid, ($selectedGames.Count - $preflightValid))
    Write-Log ('ReShade ' + $pathPreflightLine)
    [void]$detailNotes.Add($pathPreflightLine)
    foreach ($preflightReason in ($preflightReasonCounts.Keys | Sort-Object)) {
        $preflightReasonLine = ("{0}: {1}" -f $preflightReason, $preflightReasonCounts[$preflightReason])
        Write-Log ('ReShade path preflight reason ' + $preflightReasonLine)
        [void]$detailNotes.Add(($preflightReasonLine + ' -- ' + (Get-TpmPlainReason -Code ([string]$preflightReason)).Text))
    }
    $deploymentStarted = Get-Date
    $deploymentCurrent = 0
    # The progress counts the games that are being changed (the ones the check above found ready), not the whole library. The
    # checking passes above count every game; they have their own plainly named stage.
    $changeableIds = @{}
    foreach ($changeableRecord in @($preflightSummary.Records)) {
        if ($changeableRecord.Status -eq 'Ready' -or ($Action -eq 'Adopt' -and $changeableRecord.Status -eq 'Protected')) { $changeableIds[([string]$changeableRecord.Id).ToLowerInvariant()] = $true }
    }
    $deploymentTotal = @($selectedGames | Where-Object { $changeableIds.ContainsKey(([string]$_.BaseName).ToLowerInvariant()) }).Count
    foreach ($pf in $selectedGames) {
        if ($changeableIds.ContainsKey(([string]$pf.BaseName).ToLowerInvariant())) {
            $deploymentCurrent++
            if ($deploymentCurrent -le $deploymentTotal) { Write-TpmCompactExtractionProgress -Phase Extracting -Label 'ReShade profile deployment' -Current $deploymentCurrent -Total $deploymentTotal -StartedAt $deploymentStarted }
        }
        # FIX85: the undo receipt of this game (from the deployment or the reapply), whether a failed rollback left the game half changed, and
        # the CRT setting turned off; the finally block below finishes the receipt whatever happens after the deployment.
        $gameUndo = $null; $undoMixed = $false; $undoNative = $null; $nativeCrtPlanned = $false
        try {
            $doc = Read-Xml $pf.FullName
            $gameLabel = Get-TpmReShadeGameLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName
            if (-not $doc.GameProfile) { $skipped++; [void]$skippedGameIds.Add($pf.BaseName); $unsafe++; [void]$unsafeDetails.Add(('{0}: malformed GameProfile XML.' -f $gameLabel)); [void]$detailNotes.Add(('{0}: game profile is invalid -- unsafe/malformed, unchanged' -f $gameLabel)); continue }

            $gpNode = $doc.GameProfile.SelectSingleNode("GamePath")
            if (-not $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { $skipped++; [void]$skippedGameIds.Add($pf.BaseName); $missingPath++; if (-not $pathReasonCounts.ContainsKey('GAME_PATH_MISSING')) { $pathReasonCounts['GAME_PATH_MISSING'] = 0 }; $pathReasonCounts['GAME_PATH_MISSING']++; [void]$detailNotes.Add(('{0}: saved game path was empty -- skipped' -f $gameLabel)); continue }

            $gamePath = $gpNode.InnerText.Trim()
            $pathCheck = Test-TpmGameMutationPath -GamePath $gamePath -RequireLeaf -ProtectedRoots $sourceCollectionRoots
            if (-not $pathCheck.Valid) {
                $reasonCode = [string]$pathCheck.ReasonCode
                if (-not $pathReasonCounts.ContainsKey($reasonCode)) { $pathReasonCounts[$reasonCode] = 0 }
                $pathReasonCounts[$reasonCode]++
                if ($reasonCode -eq 'DEVICE_UNAVAILABLE') {
                    $missingDevice++
                    [void]$detailNotes.Add(('{0}: device unavailable -- skipped before ReShade transaction' -f $pf.BaseName))
                } elseif ($reasonCode -eq 'GAME_PATH_MISSING') {
                    $missingPath++
                    [void]$detailNotes.Add(('{0}: saved game executable was not found -- skipped' -f $pf.BaseName))
                } elseif ($reasonCode -eq 'SOURCE_COLLECTION') {
                    $unsafe++
                    [void]$sourceFolderGames.Add([string]$pf.BaseName)
                    [void]$unsafeDetails.Add(('{0}: {1}' -f $gameLabel, [string]$pathCheck.Reason))
                    [void]$detailNotes.Add(('{0}: inside the source folder -- unchanged' -f $gameLabel))
                } else {
                    $unsafe++
                    [void]$unsafeDetails.Add(('{0}: {1}' -f $pf.BaseName, [string]$pathCheck.Reason))
                    [void]$detailNotes.Add(('{0}: path safety check failed ({1}) -- unsafe/malformed, unchanged' -f $pf.BaseName, $pathCheck.Reason))
                }
                $skipped++; [void]$skippedGameIds.Add($pf.BaseName)
                Write-Log ("ReShade: skipped {0} before transaction; path reason={1}; detail={2}" -f $pf.BaseName, $reasonCode, $pathCheck.Reason)
                continue
            }
            $gamePath = [string]$pathCheck.ResolvedPath
            $exeDir = [string]$pathCheck.GameDirectory
            # A 64-bit game uses ReShade64.dll and a 32-bit game uses ReShade32.dll. A 32-bit game is skipped (nothing in its folder changes) only when the 32-bit file is not available. A game whose bit-ness cannot be read is not changed either.
            $gameArchitecture = Get-ExeArchitecture -ExePath $gamePath
            $has32BitDll = ($gameArchitecture -eq 'x86') -and [bool](Get-TpmReShadeSourceDllForArchitecture -SourceDll $SourceDll -Architecture 'x86')
            if ($gameArchitecture -ne 'x64' -and -not $has32BitDll) {
                $skipped++; [void]$skippedGameIds.Add($pf.BaseName)
                if ($gameArchitecture -eq 'x86') {
                    $unsupported++
                    [void]$detailNotes.Add(('{0}: 32-bit game -- the 32-bit ReShade file (ReShade32.dll) was not found -- skipped' -f $gameLabel))
                    Write-Log ("ReShade: skipped {0}; 32-bit game and ReShade32.dll was not found next to ReShade64.dll" -f $pf.BaseName)
                } elseif (Test-TpmFileIsElf -Path $gamePath) {
                    $linuxStyle++
                    [void]$detailNotes.Add(('{0}: runs through BudgieLoader (a Linux-style game); ReShade is not set up for these games yet -- skipped' -f $gameLabel))
                    Write-Log ("ReShade: skipped {0}; Linux-style game that runs through BudgieLoader (not supported yet)" -f $pf.BaseName)
                } else {
                    $unsafe++
                    [void]$unsafeDetails.Add(('{0}: TeknoParrot Manager could not tell whether this game is 32-bit or 64-bit.' -f $gameLabel))
                    [void]$detailNotes.Add(('{0}: could not tell whether this game is 32-bit or 64-bit -- unsafe/malformed, unchanged' -f $gameLabel))
                    Write-Log ("ReShade: skipped {0}; could not tell whether this game is 32-bit or 64-bit" -f $pf.BaseName)
                }
                continue
            }
            $ownershipPath = Get-TpmReShadeProfileOwnershipPath -GameId $pf.BaseName
            $profileForGame = $selectedProfile
            $canonicalForGame = $false
            if ($rememberedSelections.ContainsKey($pf.BaseName)) {
                $profileForGame = $rememberedSelections[$pf.BaseName].Profile
                $canonicalForGame = $true
            } elseif ($restoreSelections.ContainsKey($pf.BaseName)) {
                $profileForGame = $restoreSelections[$pf.BaseName].Profile
            }
            $profileTargetInfo = Get-ReShadeTargetInfo -Doc $doc -GamePath $gamePath -ExeDir $exeDir
            if (-not $profileTargetInfo -or [string]::IsNullOrWhiteSpace($profileTargetInfo.TargetDir) -or [string]::IsNullOrWhiteSpace($profileTargetInfo.DllName)) {
                $skipped++; [void]$skippedGameIds.Add($pf.BaseName)
                $unsafe++
                [void]$unsafeDetails.Add(('{0}: ReShade target could not be resolved safely.' -f $pf.BaseName))
                [void]$detailNotes.Add(('{0}: ReShade target could not be resolved safely -- could not tell which ReShade file this game needs (the game is not damaged), left unchanged' -f $pf.BaseName))
                Write-Log ("ReShade: {0} classified MalformedNeedsReview; target resolution failed." -f $pf.BaseName)
                continue
            }
            $profileHookPath = Join-Path $profileTargetInfo.TargetDir $profileTargetInfo.DllName
            $existingOwnership = $null
            if (Test-Path -LiteralPath $ownershipPath -PathType Leaf) {
                try { $existingOwnership = Read-TpmReShadeOwnershipManifest -Path $ownershipPath }
                catch {
                    $skipped++; [void]$skippedGameIds.Add($pf.BaseName)
                    $unsafe++
                    [void]$unsafeDetails.Add(('{0}: malformed ReShade ownership metadata.' -f $pf.BaseName))
                    [void]$detailNotes.Add(('{0}: malformed ReShade ownership metadata -- unsafe/malformed, unchanged' -f $pf.BaseName))
                    Write-Log ("ReShade: {0} classified MalformedNeedsReview; ownership metadata was not trusted." -f $pf.BaseName)
                    continue
                }
            }
            $runtimeSource = $SourceDll
            $runtimeVersion = $bVer
            $currentRuntimeHash = if ($runtimeSource -and (Test-Path -LiteralPath $runtimeSource -PathType Leaf)) { (Get-FileHash -LiteralPath $runtimeSource -Algorithm SHA256 -ErrorAction SilentlyContinue).Hash } else { '' }
            $ownershipClassification = Get-TpmReShadeOwnershipClassification -HookPath $profileHookPath -TargetRoot $profileTargetInfo.TargetDir -ProfileDefinition $profileForGame -CurrentRuntimeSHA256 $currentRuntimeHash -CurrentRuntimeVersion $runtimeVersion -Manifest $existingOwnership
            if ($ownershipClassification.Status -eq 'MalformedNeedsReview') {
                $skipped++; [void]$skippedGameIds.Add($pf.BaseName)
                $unsafe++
                [void]$unsafeDetails.Add(('{0}: {1}' -f $pf.BaseName, $ownershipClassification.Detail))
                [void]$detailNotes.Add(('{0}: {1} -- unsafe/malformed, unchanged' -f $pf.BaseName, $ownershipClassification.Detail))
                continue
            }
            if (($ownershipClassification.Status -eq 'UnknownUserOwnedConflict' -or $ownershipClassification.Status -eq 'BundledPreinstalledProtected') -and $Action -ne 'Adopt') {
                $protected++; [void]$skippedGameIds.Add($pf.BaseName)
                [void]$protectedDetails.Add(('{0}: {1}' -f $pf.BaseName, $ownershipClassification.Detail))
                $protectedReasonCode = Get-TpmReShadeProtectedReasonCode -Status ([string]$ownershipClassification.Status) -TargetDir ([string]$profileTargetInfo.TargetDir)
                [void]$protectedRecords.Add([pscustomobject]@{ Game = [string]$pf.BaseName; Label = [string]$gameLabel; Code = $protectedReasonCode; Detail = [string]$ownershipClassification.Detail })
                Write-Log ('ReShade: protected {0} ({1}) -- {2} -- unchanged' -f $pf.BaseName, $protectedReasonCode, $ownershipClassification.Detail)
                continue
            }
            if ($keepSelections.ContainsKey($pf.BaseName)) {
                $keptProfile++
                [void]$detailNotes.Add(('{0}: kept previous TeknoParrot Manager-managed profile {1} -- unchanged' -f $pf.BaseName, $keepSelections[$pf.BaseName].Profile.FriendlyName))
                Write-Log ("ReShade: kept previous TPM-managed profile for {0}: {1}" -f $pf.BaseName, $keepSelections[$pf.BaseName].Profile.ProfileId)
                if ($nativeCrtState.Requested -and $nativeCrtState.Items.ContainsKey([string]$pf.BaseName)) { [void]$nativeCrtState.OtherLook.Add([string]$pf.BaseName) }
                continue
            }
            if ($restoreSelections.ContainsKey($pf.BaseName)) {
                $restoreUndo = Get-TpmReShadeSetupUndoRequest -GameId $pf.BaseName -GameName $gameLabel -Status ([string]$ownershipClassification.Status) -Manifest $existingOwnership -ProfileId ([string]$restoreSelections[$pf.BaseName].Profile.ProfileId)
                $restoreResult = Restore-TpmReShadeProfile -HistoryEntry $restoreSelections[$pf.BaseName].HistoryEntry -CacheRoot $reShadeCacheRoot -OwnershipRoot $ownershipPath -GamePath $gamePath -Doc $doc -SourceDll $SourceDll -SourceVersion $runtimeVersion -GameId $pf.BaseName -StateRoot '' -UndoReceipt $restoreUndo -ProtectedRoots $sourceCollectionRoots -PerGamePresetPath (Join-Path $reShadePresetsDir ($pf.BaseName + '.ini'))
                if ([string]$restoreResult.Reason -eq 'UNDO_RECEIPT_FAILED') { Register-TpmReShadeUndoReceiptFailure -Game ([string]$pf.BaseName) -GameName $gameLabel -ErrorCount ([ref]$errors) -FailedGameIds $failedGameIds -DetailNotes $detailNotes; continue }
                $gameUndo = Get-TpmTransactionField -Object $restoreResult -Name 'UndoReceipt' -Default $null
                $undoMixed = ([string](Get-TpmTransactionField -Object $restoreResult -Name 'State' -Default '') -ceq 'ACTION_REQUIRED')
                if (-not $restoreResult.Succeeded) { if ($restoreResult.PSObject.Properties['DeploymentSucceeded'] -and [bool]$restoreResult.DeploymentSucceeded) { [void]$unverifiedGameIds.Add($pf.BaseName) }; throw ("reapply rejected: {0}" -f $restoreResult.Reason) }
                $restoreSource = [string](Get-TpmTransactionField -Object $restoreResult -Name 'PresetSource' -Default '')
                if ($restoreSource -eq 'per-game') { $presetOverrides++ }
                $restoreNote = if ($restoreSource) { "  (preset: $restoreSource)" } else { '' }
                [void]$appliedGames.Add($pf.BaseName)
                [void]$detailNotes.Add(('{0}  [{1}]{2}  reapplied previous trusted profile' -f $pf.BaseName, $restoreResult.DllName, $restoreNote))
                Write-Log "ReShade: reapplied $($restoreResult.ProfileId) for $($pf.BaseName)$restoreNote -- verified deployment result."
                $reapplied++
                $deployed++
                [void]$changedGameIds.Add($pf.BaseName)
                if ($nativeCrtState.Requested -and $nativeCrtState.Items.ContainsKey([string]$pf.BaseName)) { [void]$nativeCrtState.OtherLook.Add([string]$pf.BaseName) }
                continue
            }
            $perGamePreset = Join-Path $reShadePresetsDir ($pf.BaseName + '.ini')
            $presetForGame = if ($canonicalForGame) { $null } else { $presetPath }
            $boundaryCheck = Test-TpmGameMutationPath -GamePath $gamePath -RequireLeaf -ProtectedRoots $sourceCollectionRoots
            if (-not $boundaryCheck.Valid) {
                $skipped++; [void]$skippedGameIds.Add($pf.BaseName)
                if ($boundaryCheck.ReasonCode -eq 'DEVICE_UNAVAILABLE') { $missingDevice++ }
                elseif ($boundaryCheck.ReasonCode -eq 'GAME_PATH_MISSING') { $missingPath++ }
                else { $unsafe++; [void]$unsafeDetails.Add(('{0}: {1}' -f $pf.BaseName, [string]$boundaryCheck.Reason)) }
                if (-not $pathReasonCounts.ContainsKey([string]$boundaryCheck.ReasonCode)) { $pathReasonCounts[[string]$boundaryCheck.ReasonCode] = 0 }
                $pathReasonCounts[[string]$boundaryCheck.ReasonCode]++
                [void]$detailNotes.Add(('{0}: mutation-boundary path check failed ({1}) -- unchanged' -f $pf.BaseName, $boundaryCheck.Reason))
                Write-Log ("ReShade: skipped {0} at mutation boundary; path reason={1}; detail={2}" -f $pf.BaseName, $boundaryCheck.ReasonCode, $boundaryCheck.Reason)
                continue
            }
            if ([string]$boundaryCheck.ResolvedPath -ine [string]$gamePath) {
                $skipped++; [void]$skippedGameIds.Add($pf.BaseName)
                $unsafe++
                [void]$unsafeDetails.Add(('{0}: game path changed before mutation.' -f $pf.BaseName))
                [void]$detailNotes.Add(('UNSAFE {0}: game path changed before mutation -- unchanged' -f $pf.BaseName))
                Write-Log "ReShade: mutation-boundary path changed for $($pf.BaseName)"
                continue
            }
            $gamePath = [string]$boundaryCheck.ResolvedPath
            $exeDir = [string]$boundaryCheck.GameDirectory
            $hadExistingProfile = Test-Path -LiteralPath $ownershipPath -PathType Leaf
            # FIX68: the undo receipt of this game is made inside the deployment, before its first write. When TeknoParrot's own CRT look
            # is turned off for this game too, its game profile is saved in the same receipt.
            $nativeCrtPlanned = ($nativeCrtState.Requested -and $nativeCrtState.Items.ContainsKey([string]$pf.BaseName) -and [string]$profileForGame.ProfileId -ceq [string]$selectedProfile.ProfileId)
            $undoExtraPaths = if ($nativeCrtPlanned) { @([string]$nativeCrtState.Items[[string]$pf.BaseName].ProfilePath) } else { @() }
            $undoRequest = Get-TpmReShadeSetupUndoRequest -GameId $pf.BaseName -GameName $gameLabel -Status ([string]$ownershipClassification.Status) -Manifest $existingOwnership -ProfileId ([string]$profileForGame.ProfileId) -ExtraPaths $undoExtraPaths
            $profileDeployment = Install-TpmReShadeProfileDeployment -ProfileDefinition $profileForGame -GamePath $gamePath -Doc $doc -SourceDll $SourceDll -PresetPath $presetForGame -PerGamePresetPath $perGamePreset -CacheRoot $reShadeCacheRoot -OwnershipPath $ownershipPath -SourceVersion $runtimeVersion -CanonicalPreset:$canonicalForGame -AllowUserOwnedOverwrite:($Action -eq 'Adopt' -and $ownershipClassification.Status -in @('UnknownUserOwnedConflict', 'BundledPreinstalledProtected')) -ExpectedHdrFingerprint $hdrExpectedFingerprint -UndoReceipt $undoRequest -ProtectedRoots $sourceCollectionRoots
            $gameUndo = Get-TpmTransactionField -Object $profileDeployment -Name 'UndoReceipt' -Default $null
            if ($profileDeployment.Succeeded -and -not (Test-TpmReShadeDeploymentVerified -DeploymentResult $profileDeployment)) {
                [void]$unverifiedGameIds.Add($pf.BaseName)
                throw 'Verified ReShade deployment identity did not match the committed files.'
            }
            if (-not $profileDeployment.Succeeded) {
                if ([string]$profileDeployment.Reason -eq 'UNDO_RECEIPT_FAILED') { Register-TpmReShadeUndoReceiptFailure -Game ([string]$pf.BaseName) -GameName $gameLabel -ErrorCount ([ref]$errors) -FailedGameIds $failedGameIds -DetailNotes $detailNotes; continue }
                if ($profileDeployment.Reason -eq 'USER_OWNED_CONTENT_PRESERVED') { $protected++; [void]$skippedGameIds.Add($pf.BaseName); [void]$protectedDetails.Add(('{0}: protected existing ReShade files' -f $pf.BaseName)); [void]$protectedRecords.Add([pscustomobject]@{ Game = [string]$pf.BaseName; Label = [string]$gameLabel; Code = (Get-TpmReShadeProtectedReasonCode -FileCollision); Detail = [string]$profileDeployment.Error }); Write-Log "ReShade: protected existing user-owned files for $($pf.BaseName)"; continue }
                if ($profileDeployment.Reason -eq 'TUTORIAL_PROGRESS_FAILED') { $errors++; [void]$failedGameIds.Add($pf.BaseName); Write-Host ("    {0}: ReShade first-run tutorial mitigation was not fixed -- {1}" -f $pf.BaseName, $profileDeployment.Error) -ForegroundColor Yellow; Write-Log ("ReShade: TutorialProgress mitigation failed for {0} -- {1}" -f $pf.BaseName, $profileDeployment.Error); continue }
                if ([string]$profileDeployment.State -eq 'ACTION_REQUIRED') {
                    [void]$unverifiedGameIds.Add($pf.BaseName)
                    Write-Host ("    {0}: rollback did not complete -- the game folder may be inconsistent; check TeknoParrot-Manager.log before retrying" -f $pf.BaseName) -ForegroundColor Red
                    Write-Log ("ReShade: rollback not verified for {0} -- {1}" -f $pf.BaseName, $profileDeployment.Error)
                    # The receipt still holds the files as they were before. The finally block finishes it, marked as needing a check.
                    $undoMixed = $true
                }
                if ([string]$profileDeployment.Reason -in @('HDR_UNAVAILABLE','HDR_EVIDENCE_CHANGED')) {
                    Write-Log ("ReShade: HDR look refused for {0} -- {1}" -f $pf.BaseName, $profileDeployment.Reason)
                    throw 'Windows HDR was turned off or changed after you picked this look, so nothing was changed. Pick the look again.'
                }
                if ([string]$profileDeployment.Reason -ceq 'PATH_TOO_LONG') { throw [string]$profileDeployment.Error }
                throw ("profile deployment rejected: {0}" -f $profileDeployment.Reason)
            }
            $tutorialProgressFixed++
            if (-not $profileDeployment.ApiDetected) { [void]$detailNotes.Add(('{0}: graphics API not detected, defaulting to dxgi.dll' -f $pf.BaseName)) }
            if (-not [string]::IsNullOrWhiteSpace([string](Get-TpmTransactionField -Object $profileDeployment -Name 'CleanupResidue' -Default ''))) { [void]$detailNotes.Add(('{0}: ReShade was installed, but TeknoParrot Manager could not delete some temporary files. Nothing is wrong with the game. Your undo copy was kept. Details are in TeknoParrot-Manager.log.' -f $pf.BaseName)) }
            $presetSource = $profileDeployment.PresetSource
            if ($presetSource -eq 'per-game') { $presetOverrides++ }
            $presetNote = if ($presetSource) { "  (preset: $presetSource)" } else { "" }
            [void]$appliedGames.Add($pf.BaseName)
            [void]$detailNotes.Add(('{0}  [{1}]{2}' -f $pf.BaseName, $profileDeployment.DllName, $presetNote))
            Write-Log "ReShade: $($pf.BaseName) -> $($profileDeployment.TargetDir) [$($profileDeployment.DllName)]$presetNote"
            if ($Action -eq 'Adopt' -and $ownershipClassification.Status -in @('UnknownUserOwnedConflict', 'BundledPreinstalledProtected')) {
                $adopted++
            }
            $deployed++
            [void]$changedGameIds.Add($pf.BaseName)
            if ($hadExistingProfile) { $updated++ } else { $installed++ }
            # A switch from another TeknoParrot Manager look to the chosen one, in bulk or game by game.
            if ([string]$undoRequest.Operation -ceq 'Switch' -and [string]$profileForGame.ProfileId -ceq [string]$selectedProfile.ProfileId) { $changedProfile++ }
            try { Add-TpmReShadeProfileHistory -GameId $pf.BaseName -ProfileDefinition $profileForGame -StateRoot '' | Out-Null } catch { Write-Log "ReShade: history record failed for $($pf.BaseName) -- $_" }
            $nativeRecord = $null
            if (-not $nativeCrtPlanned -and $nativeCrtState.Requested -and $nativeCrtState.Items.ContainsKey([string]$pf.BaseName)) { [void]$nativeCrtState.OtherLook.Add([string]$pf.BaseName) }
            if ($nativeCrtPlanned) {
                $nativeRecord = Invoke-TpmReShadeNativeCrtTurnOff -State $nativeCrtState -Game ([string]$pf.BaseName) -UserProfilesDir $UserProfilesDir
                # A profile that may be damaged keeps the run from ending as a success.
                if ($nativeRecord.NeedsRestore -and -not $unverifiedGameIds.Contains([string]$pf.BaseName)) { [void]$unverifiedGameIds.Add([string]$pf.BaseName) }
            }
            # FIX68: the receipt records every file as TeknoParrot Manager left it (and the CRT setting it turned off), so Undo can tell later
            # whether the game was changed since. FIX85: the finally block below finishes it.
            $undoNative = if ($null -ne $nativeRecord -and [string]$nativeRecord.Outcome -ceq 'TurnedOff') { $nativeRecord } else { $null }
        } catch {
            $failureCode = Get-TpmGameMutationFailureCode -ErrorRecord $_
            if ($failureCode -eq 'DEVICE_UNAVAILABLE' -or $failureCode -eq 'GAME_PATH_MISSING') {
                $skipped++; [void]$skippedGameIds.Add($pf.BaseName)
                if (-not $pathReasonCounts.ContainsKey($failureCode)) { $pathReasonCounts[$failureCode] = 0 }
                $pathReasonCounts[$failureCode]++
                if ($failureCode -eq 'DEVICE_UNAVAILABLE') { $missingDevice++ } else { $missingPath++ }
                [void]$detailNotes.Add(('SKIP {0}: mutation became unavailable ({1}) -- unchanged' -f $pf.BaseName, $failureCode))
                Write-Log ("ReShade: skipped {0} after mutation failure; path reason={1}; detail={2}" -f $pf.BaseName, $failureCode, $_)
            } else {
                Write-Host ("    FAILED {0}: {1}" -f $pf.BaseName, $_) -ForegroundColor Red
                Write-Log "ReShade: FAILED $($pf.BaseName) -- $_"
                $errors++
                [void]$failedGameIds.Add($pf.BaseName)
            }
        } finally {
            if ($null -ne $gameUndo) {
                $undoState = Add-TpmReShadeUndoGameResult -Groups $undoGames -Game ([string]$pf.BaseName) -Undo $gameUndo -NativeShader $undoNative -Mixed:$undoMixed
                if ($undoState -ceq 'Ready' -and $nativeCrtPlanned) { [void]$nativeCrtState.UndoReady.Add([string]$pf.BaseName) }
            }
        }
    }
    if ($deploymentTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase Extracting -Label 'ReShade profile deployment' -Current ([Math]::Min($deploymentCurrent, $deploymentTotal)) -Total $deploymentTotal -StartedAt $deploymentStarted -Complete }
    if ($nativeCrtState.Requested) { Write-TpmReShadeNativeCrtOutcome -State $nativeCrtState }
    $nativeTurnedOff = @($nativeCrtState.Records | Where-Object { $_.Succeeded } | ForEach-Object { [string]$_.Game })
    $nativeResultWarnings = @(foreach ($nativeWarning in $nativeShaderWarnings) {
        if ($nativeTurnedOff -contains [string]$nativeWarning.Game) {
            $nativeRemaining = @($nativeWarning.Fields | Where-Object { -not ($null -ne $_.PSObject.Properties['IsCrtShader'] -and [bool]$_.IsCrtShader) })
            if ($nativeRemaining.Count -gt 0) { [pscustomobject]@{ Game = $nativeWarning.Game; Fields = $nativeRemaining; Warning = $nativeWarning.Warning } }
        } else { $nativeWarning }
    })
    $skippedForAccounting = [Math]::Max(0, $skipped - $missingPath - $missingDevice - $unsafe)
    $accounting = Get-TpmReShadeApplyAccounting -Selected $selectedGames.Count -Deployed $deployed -Adopted $adopted -Protected $protected -MissingPath $missingPath -MissingDevice $missingDevice -Unsafe $unsafe -Failed $errors -KeptPrevious $keptProfile -SkippedCancelled $skippedForAccounting
    $changedTotal = $accounting.ChangedTpmManaged + $accounting.AdoptedReplaced
    $notChangedTotal = $accounting.ProtectedUnchanged + $accounting.KeptPrevious + $accounting.MissingPath + $accounting.UnsafeOwnershipPath + $accounting.SkippedCancelled
    $summaryDetails = New-Object System.Collections.Generic.List[string]
    [void]$summaryDetails.Add(('Result: {0} changed; {1} not changed; {2}.' -f $changedTotal, $notChangedTotal, $(if ([int]$accounting.Failed -eq 1) { '1 actual failure' } else { ('{0} actual failures' -f $accounting.Failed) })))
    if ($accounting.AdoptedReplaced -gt 0) { [void]$summaryDetails.Add(('Adopted/replaced existing ReShade: {0}' -f (Format-TpmGameCount -Count $accounting.AdoptedReplaced))) }
    if (-not $accounting.Complete) { throw 'ReShade accounting invariant failed: terminal outcomes did not equal selected games.' }
    Write-Log ("ReShade accounting: Selected={0} ChangedTpmManaged={1} AdoptedReplaced={2} ProtectedUnchanged={3} KeptPrevious={4} MissingPath={5} UnsafeOwnershipPath={6} Failed={7} SkippedCancelled={8}" -f $accounting.Selected, $accounting.ChangedTpmManaged, $accounting.AdoptedReplaced, $accounting.ProtectedUnchanged, $accounting.KeptPrevious, $accounting.MissingPath, $accounting.UnsafeOwnershipPath, $accounting.Failed, $accounting.SkippedCancelled)


    # FIX72: these counters used to be printed one per line, zeros included. The screen now shows a short summary (Show-TpmReShadeSetupResult).
    # Every counter that is not zero is kept here for [D] Details and is written to the log.
    if ($installed -gt 0) { [void]$summaryDetails.Add(('Installed new: {0}' -f (Format-TpmGameCount -Count $installed))) }
    if ($updated -gt 0) { [void]$summaryDetails.Add(('Updated: {0}' -f (Format-TpmGameCount -Count $updated))) }
    if ($changedProfile -gt 0) { [void]$summaryDetails.Add(('Changed TeknoParrot Manager profile: {0} -> {1}' -f (Format-TpmGameCount -Count $changedProfile), $selectedProfile.FriendlyName)) }
    if ($keptProfile -gt 0) { [void]$summaryDetails.Add(('Kept previous TeknoParrot Manager profile: {0}' -f (Format-TpmGameCount -Count $keptProfile))) }
    if ($reapplied -gt 0) { [void]$summaryDetails.Add(('Reapplied: {0}' -f (Format-TpmGameCount -Count $reapplied))) }
    if ($undoGames['Ready'].Count -gt 0) { [void]$summaryDetails.Add(('Saved for undo: {0}' -f (Format-TpmGameCount -Count $undoGames['Ready'].Count))) }
    if ($undoGames['Missing'].Count -gt 0) { [void]$summaryDetails.Add(('Undo copy not finished (see the log): {0}' -f (Format-TpmGameCount -Count $undoGames['Missing'].Count))) }
    if ($undoGames['Check'].Count -gt 0) { [void]$summaryDetails.Add(('Check before you play (undo saved, but a failed rollback left it half changed): {0}' -f (Format-TpmGameCount -Count $undoGames['Check'].Count))) }
    if ($presetOverrides -gt 0) { [void]$summaryDetails.Add(('Per-game presets applied: {0}' -f $presetOverrides)) }
    if ($missingDevice -gt 0) {
        [void]$summaryDetails.Add(('Skipped unavailable device: {0}' -f (Format-TpmGameCount -Count $missingDevice)))
        [void]$summaryDetails.Add('These games were not changed because their saved drive/device was unavailable.')
    }
    if ($missingPath -gt 0) {
        [void]$summaryDetails.Add(('Skipped missing executable: {0}' -f (Format-TpmGameCount -Count $missingPath)))
        [void]$summaryDetails.Add('Repair saved game paths, then run ReShade setup again.')
    }
    if ($unsafe -gt 0) {
        [void]$summaryDetails.Add(('Unsafe/malformed ownership or path: {0} -- unchanged' -f (Format-TpmGameCount -Count $unsafe)))
        foreach ($unsafeDetail in $unsafeDetails) { [void]$summaryDetails.Add([string]$unsafeDetail) }
        [void]$summaryDetails.Add('Review the listed ownership/path issue, then run ReShade setup again. TeknoParrot Manager did not guess or overwrite it.')
        [void]$summaryDetails.Add('Next safe action: repair the saved path or ownership metadata, use explicit Adopt only for protected installs, skip the game, or open Details/support for the exact path.')
    }
    if ($unsupported -gt 0) { [void]$summaryDetails.Add(('Skipped 32-bit games (the 32-bit ReShade file was not found): {0}' -f (Format-TpmGameCount -Count $unsupported))) }
    if ($linuxStyle -gt 0) { [void]$summaryDetails.Add(('Skipped Linux-style games that run through BudgieLoader (not supported yet): {0}' -f (Format-TpmGameCount -Count $linuxStyle))) }
    if ($protected -gt 0) { [void]$summaryDetails.Add(('Protected: {0} already had ReShade files, so TeknoParrot Manager left them unchanged.' -f (Format-TpmGameCount -Count $protected))) }
    if ($tutorialProgressFixed -gt 0) { [void]$summaryDetails.Add('TeknoParrot Manager marks the ReShade first-run tutorial as completed for manager-managed installs. ReShade may still show a brief normal startup/loading overlay.') }
    if ($errors -gt 0) { [void]$summaryDetails.Add(('Errors: {0} -- see TeknoParrot-Manager.log for details' -f $errors)) }
    foreach ($summaryLine in $summaryDetails) { Write-Log ('ReShade summary: {0}' -f $summaryLine) }
    Write-Log ("ReShade setup: InstalledNew={0} Updated={1} ChangedProfile={2} KeptPrevious={3} Reapplied={4} Protected={5} Adopted={6} MissingPath={7} MissingDevice={8} Unsupported={9} Errors={10} PresetOverrides={11}" -f $installed, $updated, $changedProfile, $keptProfile, $reapplied, $protected, $adopted, $missingPath, $missingDevice, $unsupported, $errors, $presetOverrides)
    if ($generatedPresetPath -and (Test-Path -LiteralPath $generatedPresetPath)) {
        Remove-Item -LiteralPath $generatedPresetPath -Force -ErrorAction SilentlyContinue
    }
    return [pscustomobject]@{
        Succeeded = ($deployed -gt 0 -and $errors -eq 0 -and $skipped -eq 0 -and $missingPath -eq 0 -and $missingDevice -eq 0 -and $unsupported -eq 0 -and $linuxStyle -eq 0 -and $protected -eq 0)
        Deployed = $deployed
        SelectedItems = @($selectedGames | ForEach-Object BaseName)
        ChangedItems = $changedGameIds.ToArray()
        SkippedItems = $skippedGameIds.ToArray()
        FailedItems = $failedGameIds.ToArray()
        Installed = $installed
        Updated = $updated
        Reapplied = $reapplied
        Unsafe = $unsafe
        UnsafeDetails = $unsafeDetails.ToArray()
        SourceFolderItems = $sourceFolderGames.ToArray()
        UnverifiedItems = $unverifiedGameIds.ToArray()
        Accounting = $accounting
        NativeShaderWarnings = $nativeResultWarnings
        NativeCrtRequested = [bool]$nativeCrtState.Requested
        NativeCrtTurnedOff = $nativeTurnedOff
        NativeCrtNotChanged = @($nativeCrtState.Records | Where-Object { -not $_.Succeeded } | ForEach-Object { [pscustomobject]@{ Game = [string]$_.Game; Outcome = [string]$_.Outcome; Reason = [string]$_.Reason; RolledBack = [bool]$_.RolledBack; NeedsRestore = [bool]$_.NeedsRestore } })
        NativeCrtNeedsRestoreItems = @($nativeCrtState.Records | Where-Object { $_.NeedsRestore } | ForEach-Object { [string]$_.Game })
        NativeCrtBackupPath = [string]$nativeCrtState.BackupPath
        SelectedProfileId = [string]$selectedProfile.ProfileId
        SelectedProfileTechniques = if ($selectedProfile.PSObject.Properties['TechniqueOrder']) { Get-TpmReShadeProfileTechniqueDisplay -ProfileDefinition $selectedProfile } else { '' }
        ChangedProfile = $changedProfile
        KeptPrevious = $keptProfile
        Adopted = $adopted
        Protected = $protected
        ProtectedDetails = $protectedDetails.ToArray()
        Skipped = $skipped
        MissingPath = $missingPath
        MissingDevice = $missingDevice
        Unsupported = $unsupported
        LinuxStyle = $linuxStyle
        Errors = $errors
        TutorialProgressFixed = $tutorialProgressFixed
        Reason = if ($errors) { 'DEPLOYMENT_ERRORS' } elseif ($deployed -eq 0) { 'NO_GAMES_DEPLOYED' } else { $null }
        PathReasonCounts = $pathReasonCounts
        SelectedProfileName = [string]$selectedProfile.FriendlyName
        ProtectedRecords = $protectedRecords.ToArray()
        SummaryDetails = $summaryDetails.ToArray()
        DetailNotes = $detailNotes.ToArray()
        AppliedGames = $appliedGames.ToArray()
        UndoReceiptItems = $undoGames['Ready'].ToArray()
        UndoReceiptMissingItems = $undoGames['Missing'].ToArray()
        UndoReceiptCheckItems = $undoGames['Check'].ToArray()
    }
}

# Pure, read-only check used by the Library health check's coverage
# report: given the legacy APIs an exe imports (from Get-GameLegacyApi)
# and its folder, decides whether dgVoodoo2 is already deployed there.
# Deliberately NOT shared with Invoke-DgVoodoo2Setup's own deploy logic --
# that logic also depends on which DLLs the user has actually bundled in
# their dgVoodoo2 source folder (falls back to deploying everything
# available if the ideal DLL is missing), which is a real, intentional
# difference from "does this game need dgVoodoo2 at all" -- a coverage
# report should answer the latter, independent of what's bundled.
function Test-DgVoodoo2UpToDate {
    param($Apis, [string]$ExeDir)

    if ($Apis.Count -eq 0) { return [pscustomobject]@{ Eligible = $false; UpToDate = $true } }
    $requiredDlls = @()
    if ($Apis -contains 'D3D8')    { $requiredDlls += 'D3D8.dll'    }
    if ($Apis -contains 'DDraw')   { $requiredDlls += 'DDraw.dll'   }
    if ($Apis -contains 'Glide2x') { $requiredDlls += 'Glide2x.dll' }
    if ($Apis -contains 'Glide3x') { $requiredDlls += 'Glide3x.dll' }
    $missing = @($requiredDlls | Where-Object { -not [System.IO.File]::Exists((ConvertTo-TpmAutoSyncLongPath -Path (Join-Path $ExeDir $_))) })
    return [pscustomobject]@{ Eligible = $true; UpToDate = ($missing.Count -eq 0) }
}

# =============================================================================
# dgVoodoo2 install wizard: auto-detect DX8/DDraw/Glide games, deploy DLLs.
# A dgVoodoo2 source folder is usable only when it actually contains at least one of the DLLs the setup deploys; an existing-but-empty folder (for example left behind by a failed download) must not suppress the download/browse offer.
function Test-TpmDgVoodoo2SourceFolder {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    try {
        if (-not (Test-Path -LiteralPath $Path -PathType Container -ErrorAction Stop)) { return $false }
        foreach ($name in @('D3D8.dll','DDraw.dll','D3DImm.dll','Glide2x.dll','Glide3x.dll')) {
            if (Test-Path -LiteralPath (Join-Path $Path $name) -PathType Leaf -ErrorAction Stop) { return $true }
        }
    } catch {}
    return $false
}

# dgVoodoo2 files TeknoParrot Manager downloaded live in the managed Assets folder (the program folder may not be writable);
# a folder the user put beside the script is still found.
function Get-TpmBundledDgVoodoo2Folder {
    if ($script:TpmOwnedLayout) {
        $managedFolder = Join-Path $script:TpmOwnedLayout.Assets 'dgVoodoo2'
        if (Test-TpmDgVoodoo2SourceFolder -Path $managedFolder) { return $managedFolder }
    }
    return (Join-Path $PSScriptRoot 'dgVoodoo2')
}

# One skip record for a game inside the source collection (owner rule R6). The plain screen text is printed once for all such games
# (Write-TpmSourceFolderRefusal); the saved path and the technical reason are in this record (Details) and in the log.
function New-TpmDgVoodoo2SourceFolderSkip {
    param([Parameter(Mandatory)][string]$Game, [string]$SavedPath, [Parameter(Mandatory)]$PathCheck)
    Write-Log ("dgVoodoo2: refused {0} before deployment; path reason=SOURCE_COLLECTION; detail={1}; saved path={2}" -f $Game, $PathCheck.Reason, $SavedPath)
    return [pscustomobject]@{
        Game = $Game; ReasonCode = 'SOURCE_COLLECTION'; Reason = (Get-TpmPlainReason -Code 'SOURCE_COLLECTION').Text
        SavedPath = $SavedPath; NextAction = 'Move the game out of your source folder, or fix the game folder in its profile.'; Technical = [string]$PathCheck.Reason
    }
}
function Invoke-DgVoodoo2Setup {
    param(
        [string]$UserProfilesDir,
        [string]$SourceDir,
        [string[]]$ProtectedRoots = @()
    )

    # Validate at least one expected DLL is present in the source folder.
    $allExpected = @('D3D8.dll', 'DDraw.dll', 'D3DImm.dll', 'Glide2x.dll', 'Glide3x.dll')
    try {
        $available = @($allExpected | Where-Object { Test-Path -LiteralPath (Join-Path $SourceDir $_) -ErrorAction Stop })
    } catch {
        $sourceError = [string]$_.Exception.Message
        Write-Host ("  dgVoodoo2 source inspection failed; no files were changed: {0}" -f $sourceError) -ForegroundColor Red
        Write-Log ("dgVoodoo2 setup: source inspection failed; no changes made: {0}" -f $sourceError)
        $transactionResult = New-TpmFileBatchResult `
            -WorkflowKey 'DgVoodoo2Setup' -OperationKey 'DirectDeployment' `
            -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' `
            -Summary 'dgVoodoo2 setup could not inspect its source files.' `
            -ReasonCode 'SOURCE_INSPECTION_FAILED' -Errors @($sourceError) `
            -TechnicalDetails ([pscustomobject]@{ Stage='Preflight'; Error=$sourceError })
        return [pscustomobject]@{
            Succeeded=$false; NoOp=$false; Deployed=0; Skipped=0; MissingDevice=0; MissingPath=0; Errors=1
            Reason='SOURCE_INSPECTION_FAILED'; DeploymentDetails=@(); SkipDetails=@()
            TransactionResult=$transactionResult
        }
    }
    if ($available.Count -eq 0) {
        Write-Host ("  ERROR: No dgVoodoo2 DLLs found in: {0}" -f $SourceDir) -ForegroundColor Red
        Write-Host ("  Expected one or more of: {0}" -f ($allExpected -join ', ')) -ForegroundColor Yellow
        Write-Log "dgVoodoo2 setup: aborted -- no DLLs in $SourceDir"
        return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 0; Reason = 'NO_SOURCE_FILES' }
    }
    Write-Host ("  Available DLLs : {0}" -f ($available -join ', ')) -ForegroundColor DarkGray
    $sourceManifestHashes = @{}
    foreach ($dllName in $available) {
        $sourceState = Get-TpmFileState -Path (Join-Path $SourceDir $dllName)
        if (-not $sourceState.Readable -or -not $sourceState.Exists -or $sourceState.IsDirectory) {
            $sourceError = "dgVoodoo2 source manifest is incomplete for '$dllName'."
            Write-Host ("  ERROR: {0} No files were changed." -f $sourceError) -ForegroundColor Red
            Write-Log "dgVoodoo2 setup: aborted -- $sourceError"
            $transactionResult = New-TpmFileBatchResult `
                -WorkflowKey 'DgVoodoo2Setup' -OperationKey 'DirectDeployment' `
                -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' `
                -Summary 'dgVoodoo2 setup could not verify its complete source manifest.' `
                -Items @($available) -ReasonCode 'SOURCE_MANIFEST_FAILED' `
                -TechnicalDetails ([pscustomobject]@{ Stage='Preflight'; Error=$sourceError })
            return [pscustomobject]@{
                Succeeded=$false; Deployed=0; Skipped=0; MissingDevice=0; MissingPath=0; Errors=1
                Reason='SOURCE_MANIFEST_FAILED'; DeploymentDetails=@(); SkipDetails=@()
                TransactionResult=$transactionResult
            }
        }
        $sourceManifestHashes[$dllName] = $sourceState.Sha256
    }

    # Per-game config overrides: dgVoodoo2Presets\<ProfileCode>.conf always
    # wins over the global dgVoodoo.conf in $SourceDir, which is added once to a game that has no dgVoodoo.conf yet.
    # Same convention as ReShadePresets\<ProfileCode>.ini (Invoke-ReShadeSetup)
    # and CustomThumbnails\<ProfileCode>.png (Invoke-ThumbnailDownload).
    $dgVoodoo2PresetsDir = if($script:TpmOwnedLayout){Join-Path $script:TpmOwnedLayout.Assets 'dgVoodoo2Presets'}else{Join-Path $PSScriptRoot "dgVoodoo2Presets"}
    try {
        $confFiles = @()
        if (Test-Path -LiteralPath $dgVoodoo2PresetsDir -ErrorAction Stop) {
            $confFiles = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $dgVoodoo2PresetsDir -ProgressLabel 'dgVoodoo2 preset file discovery' -Filter '*.conf' -EnumerationErrorAction Stop)
        }
        if ($confFiles.Count -gt 0) {
            $knownConfCodes = Get-TpmRegisteredProfileCodes -UserProfilesDir $UserProfilesDir -ProgressLabel 'dgVoodoo2 preset profile-code scan'
            foreach ($cfile in $confFiles) {
                $code = [System.IO.Path]::GetFileNameWithoutExtension($cfile.Name)
                if (-not $knownConfCodes.Contains($code)) {
                    Write-Host ("  WRONG NAME: dgVoodoo2Presets\{0}" -f $cfile.Name) -ForegroundColor Yellow
                    Write-Host ("             '{0}' does not match any registered game profile code." -f $code) -ForegroundColor Yellow
                    Write-Host "             Check TeknoParrot-Manager-controls.txt for the correct" -ForegroundColor Yellow
                    Write-Host "             name, rename the file, then re-run. File will be ignored." -ForegroundColor Yellow
                    Write-Log "dgVoodoo2: per-game config $($cfile.Name) -- no matching profile code, ignored."
                }
            }
        }
    } catch {
        Write-Host ('  dgVoodoo2 preset discovery failed; setup stopped before any change: {0}' -f $_.Exception.Message) -ForegroundColor Red
        Write-Log ('dgVoodoo2 setup: preset discovery failed; no changes made: {0}' -f $_.Exception.Message)
        return [pscustomobject]@{
            Succeeded=$false; NoOp=$false; Deployed=0; Skipped=0; MissingDevice=0; MissingPath=0; Errors=1
            Reason='PRESET_DISCOVERY_FAILED'; DeploymentDetails=@(); SkipDetails=@()
            TransactionResult=$null
        }
    }

    # Scan all registered games for legacy API usage and build a detection map.
    Write-Host ""
    Write-Host "  Scanning registered games for old DirectX / Glide usage..." -ForegroundColor Cyan
    try {
        $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'dgVoodoo2 profile discovery' -EnumerationErrorAction Stop | Sort-Object BaseName)
    } catch {
        Write-Host ('  dgVoodoo2 profile discovery failed; setup stopped before any change: {0}' -f $_.Exception.Message) -ForegroundColor Red
        Write-Log ('dgVoodoo2 setup: profile discovery failed; no changes made: {0}' -f $_.Exception.Message)
        return [pscustomobject]@{
            Succeeded=$false; Deployed=0; Skipped=0; MissingDevice=0; MissingPath=0; Errors=1
            Reason='PROFILE_DISCOVERY_FAILED'; DeploymentDetails=@(); SkipDetails=@()
            TransactionResult=$null
        }
    }
    if ($profiles.Count -eq 0) {
        Write-Host "  No registered games found." -ForegroundColor Yellow
        Write-Log "dgVoodoo2 setup: aborted -- no registered profiles."
        return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 0; Reason = 'NO_REGISTERED_PROFILES' }
    }

    $detectedMap = @{}   # BaseName -> API array
    $scanPathReasons = @{}
    $skipDetails = New-Object System.Collections.Generic.List[object]
    $scanStarted = Get-Date
    $scanCurrent = 0
    $scanCurrentDone = $false
    try {
        foreach ($pf in $profiles) {
            $scanCurrent++
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'dgVoodoo2 profile scan' -Current $scanCurrent -Total $profiles.Count -StartedAt $scanStarted
            try {
                $doc = Read-Xml $pf.FullName
                if (-not $doc.GameProfile) { throw 'Registered profile has no GameProfile element.' }
                $gpNode = $doc.GameProfile.SelectSingleNode("GamePath")
                if (-not $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) {
                    Write-Log ("dgVoodoo2 scan: skipped {0}; no game path is saved in the profile" -f $pf.BaseName)
                    continue
                }
                $gamePath = $gpNode.InnerText.Trim()
                $pathCheck = Test-TpmGameMutationPath -GamePath $gamePath -RequireLeaf
                if (-not $pathCheck.Valid) {
                    $reasonCode = [string]$pathCheck.ReasonCode
                    if (-not $scanPathReasons.ContainsKey($reasonCode)) { $scanPathReasons[$reasonCode] = 0 }
                    $scanPathReasons[$reasonCode]++
                    $skipReason = if ($reasonCode -eq 'DEVICE_UNAVAILABLE') { 'The saved game drive or device is unavailable.' } else { 'TeknoParrot Manager has a saved location for this game, but Windows cannot find the executable.' }
                    $nextAction = if ($reasonCode -eq 'DEVICE_UNAVAILABLE') { 'Reconnect the drive or device, then run dgVoodoo2 setup again.' } else { 'Return to the main menu and choose 13) Library Health Check to repair saved game paths.' }
                    [void]$skipDetails.Add([pscustomobject]@{ Game = $pf.BaseName; ReasonCode = $reasonCode; Reason = $skipReason; SavedPath = $gamePath; NextAction = $nextAction; Technical = [string]$pathCheck.Reason })
                    Write-Log ("dgVoodoo2 scan: skipped {0}; path reason={1}; detail={2}" -f $pf.BaseName, $reasonCode, $pathCheck.Reason)
                    continue
                }
                $gamePath = [string]$pathCheck.ResolvedPath
                $apis = @(Get-GameLegacyApi -ExePath $gamePath)
                if ($apis.Count -gt 0) { $detectedMap[$pf.BaseName] = $apis }
            } catch {
                Write-Log "dgVoodoo2 scan: error reading $($pf.BaseName) -- $_"
                $scanError = [string]$_.Exception.Message
                Write-Host ("  dgVoodoo2 detection failed for {0}; no files were changed: {1}" -f $pf.BaseName, $scanError) -ForegroundColor Red
                $transactionResult = New-TpmFileBatchResult `
                    -WorkflowKey 'DgVoodoo2Setup' -OperationKey 'DirectDeployment' `
                    -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' `
                    -Summary 'dgVoodoo2 setup could not complete legacy API detection.' `
                    -Items @($profiles | ForEach-Object { [string]$_.BaseName }) `
                    -FailedItems @([string]$pf.BaseName) -ReasonCode 'DETECTION_FAILED' `
                    -Errors @($scanError) `
                    -TechnicalDetails ([pscustomobject]@{ Stage='Detection'; Profile=[string]$pf.BaseName; Error=$scanError })
                return [pscustomobject]@{
                    Succeeded=$false; NoOp=$false; Deployed=0; Skipped=$skipDetails.Count
                    MissingDevice=if($scanPathReasons.ContainsKey('DEVICE_UNAVAILABLE')){$scanPathReasons['DEVICE_UNAVAILABLE']}else{0}
                    MissingPath=if($scanPathReasons.ContainsKey('GAME_PATH_MISSING')){$scanPathReasons['GAME_PATH_MISSING']}else{0}
                    Errors=1; Reason='DETECTION_FAILED'; DeploymentDetails=@(); SkipDetails=$skipDetails.ToArray()
                    TransactionResult=$transactionResult
                }
            }
        }
        $scanCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'dgVoodoo2 profile scan' -Current $(if ($scanCurrentDone) { $scanCurrent } else { $scanCurrent - 1 }) -Total $profiles.Count -StartedAt $scanStarted -Complete -Outcome $(if ($scanCurrentDone) { 'Final' } else { 'Error' })
    }
    foreach ($reasonCode in ($scanPathReasons.Keys | Sort-Object)) {
        Write-Host ("  Preflight skipped {0} game(s): {1}" -f $scanPathReasons[$reasonCode], (Get-TpmPlainReason -Code $reasonCode).Text) -ForegroundColor Yellow
    }

    $scanLeftOut = [int](($scanPathReasons.Values | Measure-Object -Sum).Sum)
    if ($scanLeftOut -gt 0 -and $scanLeftOut -lt $profiles.Count) {
        Write-Host ("  Checked {0} of {1} game(s). The other {2} were skipped (see above)." -f ($profiles.Count - $scanLeftOut), $profiles.Count, $scanLeftOut) -ForegroundColor DarkGray
    } else {
        Write-Host ("  Scanned {0} game(s)." -f $profiles.Count) -ForegroundColor DarkGray
    }
    if ($detectedMap.Count -gt 0) {
        Write-Host ("  Auto-detected {0} game(s) using legacy APIs:" -f $detectedMap.Count) -ForegroundColor Cyan
        foreach ($name in ($detectedMap.Keys | Sort-Object)) {
            Write-Host ("    {0}  [{1}]" -f $name, ($detectedMap[$name] -join ', '))
        }
    } else {
        if ($scanPathReasons.Count -gt 0) {
            Write-Host "  No dgVoodoo2 deployment was attempted because one or more game paths were unavailable." -ForegroundColor Yellow
            Write-Host "  Nothing was changed." -ForegroundColor Yellow
            if ($scanPathReasons.ContainsKey('DEVICE_UNAVAILABLE')) {
                Write-Host ("  Skipped unavailable device: {0}" -f (Format-TpmGameCount -Count ([int]$scanPathReasons['DEVICE_UNAVAILABLE']))) -ForegroundColor Yellow
            }
            if ($scanPathReasons.ContainsKey('GAME_PATH_MISSING')) {
                Write-Host ("  Skipped missing executable: {0}" -f (Format-TpmGameCount -Count ([int]$scanPathReasons['GAME_PATH_MISSING']))) -ForegroundColor Yellow
            }
            return [pscustomobject]@{
                Succeeded = $false
                Deployed = 0
                Skipped = [int](($scanPathReasons.Values | Measure-Object -Sum).Sum)
                MissingDevice = if ($scanPathReasons.ContainsKey('DEVICE_UNAVAILABLE')) { $scanPathReasons['DEVICE_UNAVAILABLE'] } else { 0 }
                MissingPath = if ($scanPathReasons.ContainsKey('GAME_PATH_MISSING')) { $scanPathReasons['GAME_PATH_MISSING'] } else { 0 }
                Errors = 0
                Reason = 'NO_ELIGIBLE_GAMES'
                PathReasonCounts = $scanPathReasons
                SkipDetails = $skipDetails.ToArray()
                DeploymentDetails = @()
            }
        }
        Write-Host ""
        Write-Host "  No dgVoodoo2 setup is needed right now." -ForegroundColor Green
        Write-Host "  TeknoParrot Manager checked your registered games and did not find any games that appear to need dgVoodoo2." -ForegroundColor Cyan
        Write-Host "  dgVoodoo2 is only used for select older games that need legacy DirectX, DirectDraw, or Glide compatibility." -ForegroundColor DarkGray
        Write-Host "  Nothing was changed." -ForegroundColor Green
        Write-Host ""
        Write-Host "  [D] Details  [Q] Back to menu"
        $selectionMode = Read-TpmChoice -Prompt "  Choice, default Q" -Choices @('D', 'Q') -Default 'Q'
        if ($selectionMode -eq 'D') {
            Write-Host ""
            Write-Host "  Details" -ForegroundColor Cyan
            Write-Host ("  Scanned game count: {0}" -f $profiles.Count) -ForegroundColor DarkGray
            Write-Host ("  Available DLLs: {0}" -f ($available -join ', ')) -ForegroundColor DarkGray
            Write-Host "  Detection checks executable imports for DirectX, DirectDraw, and Glide APIs." -ForegroundColor DarkGray
            Write-Host "  Advanced dgVoodoo2 selection is available for expert use:" -ForegroundColor Cyan
            Write-Host "  [M] Select specific games"
            Write-Host "  [Q] Back to menu"
            $selectionMode = Read-TpmChoice -Prompt "  Choice, default Q" -Choices @('M', 'Q') -Default 'Q'
        }
        if ($selectionMode -ne 'M') {
            Write-Log "dgVoodoo2 setup: no candidates detected; no changes made."
            return [pscustomobject]@{ Succeeded = $true; NoOp = $true; Deployed = 0; Errors = 0; Reason = 'NOT_NEEDED'; DeploymentDetails = @(); SkipDetails = @() }
        }
    }

    # FIX110 (S-9): before the user chooses games, say what setup does to files that already exist.
    Write-Host ""
    Write-Host "  Setup adds the DLL files a game folder is missing, and your dgVoodoo.conf if the game folder has none. DLL files that are already there are kept." -ForegroundColor DarkGray
    if ($confFiles.Count -gt 0) {
        Write-Host "  A game with its own preset file in dgVoodoo2Presets gets that file as its dgVoodoo.conf." -ForegroundColor Yellow
        Write-Host "  That REPLACES a dgVoodoo.conf that is already in the game folder." -ForegroundColor Yellow
    }

    # Game selection.
    if ($detectedMap.Count -gt 0) {
        Write-Host ""
        Write-Host "  Which games should get dgVoodoo2?" -ForegroundColor Cyan
        Write-Host "  A) Auto-detected games only ($($detectedMap.Count) game(s) listed above)"
        Write-Host "  M) Pick games manually from the full list"
        Write-Host "  Q) Cancel"
        $selectionMode = Read-TpmChoice -Prompt "  Enter A, M, or Q" -Choices @('A', 'M', 'Q') -Default 'Q'
    }

    $targetProfiles = @()
    if ($selectionMode -eq 'A') {
        $targetProfiles = @($profiles | Where-Object { $detectedMap.ContainsKey($_.BaseName) })
    } elseif ($selectionMode -eq 'M') {
        $targetProfiles = @(Select-DgVoodoo2GamesInteractive -UserProfilesDir $UserProfilesDir)
    } else {
        Write-Host "  dgVoodoo2 setup canceled." -ForegroundColor Yellow
        Write-Log "dgVoodoo2 setup: canceled."
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $true; Deployed = 0; Errors = 0; Reason = 'DECLINED' }
    }

    if ($targetProfiles.Count -eq 0) {
        Write-Host "  No games selected. dgVoodoo2 setup canceled." -ForegroundColor Yellow
        Write-Log "dgVoodoo2 setup: canceled -- no games selected."
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $true; Deployed = 0; Errors = 0; Reason = 'NO_GAMES_SELECTED' }
    }

# Build the complete direct-deployment plan before touching any game folder.
# Existing DLLs are intentionally omitted from the mutation plan so the
# transaction can preserve the historical "missing files only" behavior.
    Write-Host ""
    Write-Host ("  Preparing dgVoodoo2 compatibility files for {0} game folder(s)..." -f $targetProfiles.Count) -ForegroundColor Cyan
    $deployed = 0; $skipped = 0; $missingDevice = 0; $missingPath = 0; $errors = 0; $presetOverrides = 0
    $deploymentDetails = New-Object System.Collections.Generic.List[object]
    $deploymentOperations = New-Object System.Collections.Generic.List[object]
    # Two profiles of one game folder plan each destination once; a second ADD of the same file would roll the whole batch back.
    $plannedDestinations = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $plannedProfiles = New-Object System.Collections.Generic.List[object]
    # Games with their own preset are planned first: when two profiles share a game folder, the preset claims dgVoodoo.conf before a game without one can claim it with the shared config.
    $presetProfiles = @($targetProfiles | Where-Object { Test-Path -LiteralPath (Join-Path $dgVoodoo2PresetsDir ($_.BaseName + '.conf')) -PathType Leaf -ErrorAction SilentlyContinue })
    $targetProfiles = @($presetProfiles) + @($targetProfiles | Where-Object { $presetProfiles -notcontains $_ })
    # Every game picked is accounted for on the result screen: changed, already set up, skipped, failed or not finished.
    $pickedGames = @($targetProfiles | ForEach-Object { [string]$_.BaseName })
    $failedDetails = New-Object System.Collections.Generic.List[object]

    $preflightStarted = Get-Date
    $preflightCurrent = 0
    $preflightCurrentDone = $false
    try {
        foreach ($pf in $targetProfiles) {
            $preflightCurrent++
            Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'dgVoodoo2 deployment preflight' -Current $preflightCurrent -Total $targetProfiles.Count -StartedAt $preflightStarted
        $gamePath = ''
        try {
            $opCountBefore = $deploymentOperations.Count
            $addedDlls = New-Object System.Collections.Generic.List[string]
            $doc = Read-Xml $pf.FullName
            $gpNode = if ($doc.GameProfile) { $doc.GameProfile.SelectSingleNode("GamePath") } else { $null }
            if (-not $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) {
                $skipped++
                [void]$skipDetails.Add([pscustomobject]@{ Game=$pf.BaseName; ReasonCode='GAME_PATH_NOT_SAVED'; Reason='This game has no saved game file path yet.'; SavedPath=''; NextAction='Start the game once in TeknoParrot or register it again, then run dgVoodoo2 setup again.'; Technical='The profile has no GameProfile or GamePath value.' })
                Write-Host ("  SKIP  {0} -- no saved game file path." -f $pf.BaseName) -ForegroundColor Yellow
                Write-Log ("dgVoodoo2: skipped {0} before deployment; the profile has no GameProfile or GamePath value" -f $pf.BaseName)
                continue
            }
            $gamePath = $gpNode.InnerText.Trim()
            $pathCheck = Test-TpmGameMutationPath -GamePath $gamePath -RequireLeaf -ProtectedRoots $ProtectedRoots
            if (-not $pathCheck.Valid -and $pathCheck.ReasonCode -eq 'SOURCE_COLLECTION') {
                $skipped++
                [void]$skipDetails.Add((New-TpmDgVoodoo2SourceFolderSkip -Game ([string]$pf.BaseName) -SavedPath $gamePath -PathCheck $pathCheck))
                continue
            }
            if (-not $pathCheck.Valid) {
                if ($pathCheck.ReasonCode -eq 'DEVICE_UNAVAILABLE') {
                    $missingDevice++
                    Write-Host ("  SKIP  {0} -- saved device unavailable; no deployment attempted." -f $pf.BaseName) -ForegroundColor Yellow
                } elseif ($pathCheck.ReasonCode -eq 'GAME_PATH_MISSING') {
                    $missingPath++
                    Write-Host ("  SKIP  {0} -- exe not found." -f $pf.BaseName) -ForegroundColor Yellow
                } else {
                    Write-Host ("  SKIP  {0} -- path safety check failed: {1}" -f $pf.BaseName, $pathCheck.Reason) -ForegroundColor Yellow
                }
                $skipped++
                $skipReason = if ($pathCheck.ReasonCode -eq 'DEVICE_UNAVAILABLE') { 'The saved game drive or device is unavailable.' } else { 'TeknoParrot Manager could not find the saved game executable.' }
                $nextAction = if ($pathCheck.ReasonCode -eq 'DEVICE_UNAVAILABLE') { 'Reconnect the drive or device, then run dgVoodoo2 setup again.' } else { 'Return to the main menu and choose 13) Library Health Check to repair saved game paths.' }
                [void]$skipDetails.Add([pscustomobject]@{ Game=$pf.BaseName; ReasonCode=[string]$pathCheck.ReasonCode; Reason=$skipReason; SavedPath=$gamePath; NextAction=$nextAction; Technical=[string]$pathCheck.Reason })
                Write-Log ("dgVoodoo2: skipped {0} before deployment; path reason={1}; detail={2}" -f $pf.BaseName,$pathCheck.ReasonCode,$pathCheck.Reason)
                continue
            }
            $gamePath = [string]$pathCheck.ResolvedPath
            $exeDir = [string]$pathCheck.GameDirectory
            $apis = @(if ($detectedMap.ContainsKey($pf.BaseName)) { $detectedMap[$pf.BaseName] } else { Get-GameLegacyApi -ExePath $gamePath })
            $toDeploy = @()
            if ($apis.Count -eq 0) {
                $toDeploy = $available
            } else {
                if ($apis -contains 'D3D8')    { $toDeploy += @($available | Where-Object { $_ -in @('D3D8.dll','D3DImm.dll') }) }
                if ($apis -contains 'DDraw')   { $toDeploy += @($available | Where-Object { $_ -in @('DDraw.dll','D3DImm.dll') }) }
                if ($apis -contains 'Glide2x') { $toDeploy += @($available | Where-Object { $_ -eq 'Glide2x.dll' }) }
                if ($apis -contains 'Glide3x') { $toDeploy += @($available | Where-Object { $_ -eq 'Glide3x.dll' }) }
                $toDeploy = @($toDeploy | Select-Object -Unique)
                if ($toDeploy.Count -eq 0) {
                    Write-Host ("  WARN  {0}: detected [{1}] but none of those DLLs are in the source folder; deploying all available." -f $pf.BaseName,($apis -join ', ')) -ForegroundColor Yellow
                    Write-Log "dgVoodoo2: $($pf.BaseName) -- detected [$($apis -join ', ')] but no matching DLLs found; deploying all available."
                    $toDeploy = $available
                }
            }
            $boundaryCheck = Test-TpmGameMutationPath -GamePath $gamePath -RequireLeaf -ProtectedRoots $ProtectedRoots
            if (-not $boundaryCheck.Valid -and $boundaryCheck.ReasonCode -eq 'SOURCE_COLLECTION') {
                $skipped++
                [void]$skipDetails.Add((New-TpmDgVoodoo2SourceFolderSkip -Game ([string]$pf.BaseName) -SavedPath $gamePath -PathCheck $boundaryCheck))
                continue
            }
            if (-not $boundaryCheck.Valid -or [string]$boundaryCheck.ResolvedPath -ine [string]$gamePath) {
                $skipped++
                if ($boundaryCheck.ReasonCode -eq 'DEVICE_UNAVAILABLE') { $missingDevice++ }
                if ($boundaryCheck.ReasonCode -eq 'GAME_PATH_MISSING') { $missingPath++ }
                $boundaryReason = if ($boundaryCheck.Valid) { 'RESOLUTION_CHANGED' } else { $boundaryCheck.ReasonCode }
                $boundaryNextAction = if ($boundaryCheck.ReasonCode -eq 'DEVICE_UNAVAILABLE') { 'Reconnect the drive or device, then run dgVoodoo2 setup again.' } else { 'Return to the main menu and choose 13) Library Health Check to repair saved game paths.' }
                [void]$skipDetails.Add([pscustomobject]@{ Game=$pf.BaseName; ReasonCode=[string]$boundaryReason; Reason='The game path changed or became unavailable before the safe write.'; SavedPath=$gamePath; NextAction=$boundaryNextAction; Technical=[string]$boundaryCheck.Reason })
                Write-Host ("  SKIP  {0} -- mutation-boundary path check failed ({1}); unchanged." -f $pf.BaseName,$boundaryReason) -ForegroundColor Yellow
                Write-Log ("dgVoodoo2: skipped {0} at mutation boundary; path reason={1}; detail={2}" -f $pf.BaseName,$boundaryReason,$boundaryCheck.Reason)
                continue
            }
            $gamePath = [string]$boundaryCheck.ResolvedPath
            $exeDir = [string]$boundaryCheck.GameDirectory
            foreach ($dllName in $toDeploy) {
                $sourcePath = Join-Path $SourceDir $dllName
                $sourceState = Get-TpmFileState -Path $sourcePath
                if (-not $sourceState.Readable -or -not $sourceState.Exists -or $sourceState.IsDirectory) {
                    throw "dgVoodoo2 source manifest is incomplete for '$dllName'."
                }
                $dstDll = Join-Path $exeDir $dllName
                $destinationState = Get-TpmFileState -Path $dstDll
                if (-not $destinationState.Readable -or $destinationState.IsDirectory) {
                    throw "dgVoodoo2 destination is not a readable file or a verified absent path: $dstDll"
                }
                if (-not $destinationState.Exists -and $plannedDestinations.Add([System.IO.Path]::GetFullPath($dstDll))) {
                    [void]$addedDlls.Add([string]$dllName)
                    [void]$deploymentOperations.Add([pscustomobject]@{
                        ItemId=('DgVoodoo2:' + $pf.BaseName + ':' + $dllName)
                        Operation='ADD'
                        SourcePath=$sourcePath
                        DestinationPath=$dstDll
                        RootPath=$exeDir
                        ExpectedSourceHash=$sourceManifestHashes[$dllName]
                        ExpectedFinalHash=$sourceManifestHashes[$dllName]
                    })
                }
            }
            $perGameConf = Join-Path $dgVoodoo2PresetsDir ($pf.BaseName + ".conf")
            $confNote = ''
            if (Test-Path -LiteralPath $perGameConf -PathType Leaf -ErrorAction Stop) {
                $confState = Get-TpmFileState -Path $perGameConf
                if (-not $confState.Readable -or -not $confState.Exists -or $confState.IsDirectory) {
                    throw "dgVoodoo2 per-game configuration is not a readable file: $perGameConf"
                }
                $dstConf = Join-Path $exeDir "dgVoodoo.conf"
                # A game whose dgVoodoo.conf already matches is not counted or rewritten.
                $dstConfState = Get-TpmFileState -Path $dstConf
                $confAlreadyMatches = ($dstConfState.Readable -and $dstConfState.Exists -and -not $dstConfState.IsDirectory -and [string]$dstConfState.Sha256 -ieq [string]$confState.Sha256)
                if (-not $confAlreadyMatches -and $plannedDestinations.Add([System.IO.Path]::GetFullPath($dstConf))) { $presetOverrides++; $confNote = 'per-game config'; [void]$deploymentOperations.Add([pscustomobject]@{
                    ItemId=('DgVoodoo2:' + $pf.BaseName + ':dgVoodoo.conf')
                    Operation='REPLACE'
                    SourcePath=$perGameConf
                    DestinationPath=$dstConf
                    RootPath=$exeDir
                    ExpectedSourceHash=$confState.Sha256
                    ExpectedFinalHash=$confState.Sha256
                }) }
            } else {
                # No per-game preset: the global dgVoodoo.conf of the source folder is added once; a game's own dgVoodoo.conf is never replaced.
                $globalConf = Join-Path $SourceDir 'dgVoodoo.conf'
                if (Test-Path -LiteralPath $globalConf -PathType Leaf -ErrorAction Stop) {
                    $globalConfState = Get-TpmFileState -Path $globalConf
                    if (-not $globalConfState.Readable -or -not $globalConfState.Exists -or $globalConfState.IsDirectory) {
                        throw "dgVoodoo2 source configuration is not a readable file: $globalConf"
                    }
                    $dstConf = Join-Path $exeDir "dgVoodoo.conf"
                    $dstConfState = Get-TpmFileState -Path $dstConf
                    if (-not $dstConfState.Readable -or $dstConfState.IsDirectory) {
                        throw "dgVoodoo2 destination is not a readable file or a verified absent path: $dstConf"
                    }
                    if (-not $dstConfState.Exists -and $plannedDestinations.Add([System.IO.Path]::GetFullPath($dstConf))) { $confNote = 'global config'; [void]$deploymentOperations.Add([pscustomobject]@{
                        ItemId=('DgVoodoo2:' + $pf.BaseName + ':dgVoodoo.conf')
                        Operation='ADD'
                        SourcePath=$globalConf
                        DestinationPath=$dstConf
                        RootPath=$exeDir
                        ExpectedSourceHash=$globalConfState.Sha256
                        ExpectedFinalHash=$globalConfState.Sha256
                    }) }
                }
            }
            [void]$plannedProfiles.Add([pscustomobject]@{
                Game=$pf.BaseName
                LegacyApis=@($apis)
                Files=@($addedDlls.ToArray())
                Destination=$exeDir
                Config=if($confNote){$confNote}else{'no config copied'}
                ConfigApplied=[bool]$confNote
                Written=($deploymentOperations.Count -gt $opCountBefore)
            })
        } catch {
            $failureCode = Get-TpmGameMutationFailureCode -ErrorRecord $_
            if ($failureCode -eq 'DEVICE_UNAVAILABLE' -or $failureCode -eq 'GAME_PATH_MISSING') {
                $skipped++
                $nextAction = if ($failureCode -eq 'DEVICE_UNAVAILABLE') { 'Reconnect the drive or device, then run dgVoodoo2 setup again.' } else { 'Return to the main menu and choose 13) Library Health Check to repair saved game paths.' }
                [void]$skipDetails.Add([pscustomobject]@{ Game=$pf.BaseName; ReasonCode=$failureCode; Reason=if($failureCode -eq 'DEVICE_UNAVAILABLE'){'The saved game drive or device is unavailable.'}else{'The saved game executable could not be found.'}; SavedPath=$gamePath; NextAction=$nextAction; Technical=[string]$_.Exception.Message })
                if ($failureCode -eq 'DEVICE_UNAVAILABLE') { $missingDevice++ } else { $missingPath++ }
                Write-Host ("  SKIP  {0} -- mutation became unavailable ({1}); unchanged." -f $pf.BaseName,$failureCode) -ForegroundColor Yellow
                Write-Log ("dgVoodoo2: skipped {0} after preflight failure; path reason={1}; detail={2}" -f $pf.BaseName,$failureCode,$_)
            } else {
                Write-Host ("  ERROR {0} -- {1}" -f $pf.BaseName,$_) -ForegroundColor Red
                Write-Log "dgVoodoo2: preflight error on $($pf.BaseName) -- $_"
                [void]$failedDetails.Add([pscustomobject]@{ Game = [string]$pf.BaseName; Reason = 'Something went wrong while checking this game, so it was not changed.'; Technical = [string]$_.Exception.Message })
                $errors++
            }
        }
    }
    $preflightCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'dgVoodoo2 deployment preflight' -Current $(if ($preflightCurrentDone) { $preflightCurrent } else { $preflightCurrent - 1 }) -Total $targetProfiles.Count -StartedAt $preflightStarted -Complete -Outcome $(if ($preflightCurrentDone) { 'Final' } else { 'Error' })
    }
    $sourceFolderSkips = @($skipDetails | Where-Object { $_.ReasonCode -eq 'SOURCE_COLLECTION' })
    Write-TpmSourceFolderRefusal -Count $sourceFolderSkips.Count

    if ($errors -gt 0) {
        $transactionResult = New-TpmFileBatchResult `
            -WorkflowKey 'DgVoodoo2Setup' -OperationKey 'DirectDeployment' `
            -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' `
            -Summary 'dgVoodoo2 setup could not complete its deployment preflight.' `
            -Items @($deploymentOperations | ForEach-Object { $_.ItemId }) `
            -ReasonCode 'PREFLIGHT_FAILED' `
            -TechnicalDetails ([pscustomobject]@{ Stage='Preflight'; Error='One or more selected game deployments failed preflight.' })
    } elseif ($deploymentOperations.Count -eq 0 -and ($skipped -gt 0 -or $plannedProfiles.Count -eq 0)) {
        $transactionResult = New-TpmFileBatchResult `
            -WorkflowKey 'DgVoodoo2Setup' -OperationKey 'DirectDeployment' `
            -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' `
            -Summary 'dgVoodoo2 setup could not verify a complete deployment plan for the selected games.' `
            -Items @($targetProfiles | ForEach-Object { [string]$_.BaseName }) `
            -SkippedItems @($skipDetails | ForEach-Object { [string]$_.Game }) `
            -ReasonCode 'PREFLIGHT_INCOMPLETE' `
            -TechnicalDetails ([pscustomobject]@{ Stage='Preflight'; SelectedCount=$targetProfiles.Count; PlannedProfileCount=$plannedProfiles.Count; SkippedCount=$skipped; OperationCount=$deploymentOperations.Count }) `
            -Errors @('One or more selected games did not pass preflight, and no verified deployment operations were planned.') `
            -FinalChecks @('No deployment transaction was invoked because a complete operation plan was unavailable.')
    } else {
        $transactionResult = Invoke-TpmDgVoodoo2FileTransaction -Operations $deploymentOperations.ToArray()
    }
    $noOp = ($transactionResult.Outcome -eq 'NO_OP' -and $plannedProfiles.Count -gt 0 -and $errors -eq 0 -and $skipped -eq 0 -and $missingDevice -eq 0 -and $missingPath -eq 0)
    if ($transactionResult.Outcome -in @('SUCCEEDED','NO_OP')) {
        if ($noOp) {
            Write-Host '  No dgVoodoo2 file changes were needed.' -ForegroundColor DarkGray
        } elseif ($transactionResult.Outcome -ne 'NO_OP') {
            # Only a game that really gets a file is reported; a game that already had every file is left out.
            $writtenPlans = @($plannedProfiles | Where-Object { $_.Written })
            foreach ($plan in $writtenPlans) {
                $confText = if ($plan.ConfigApplied) { '  (config: ' + [string]$plan.Config + ')' } else { '' }
                Write-Log ("dgVoodoo2: verified deployment plan for {0} at {1}{2}" -f $plan.Game,$plan.Destination,$confText)
                [void]$deploymentDetails.Add([pscustomobject]@{
                    Game=$plan.Game; LegacyApis=@($plan.LegacyApis); Files=@($plan.Files)
                    Destination=$plan.Destination; Config=$plan.Config
                })
            }
            $deployed = $writtenPlans.Count
        }
    } else {
        $errors++
        foreach ($plan in @($plannedProfiles | Where-Object { $_.Written })) {
            [void]$failedDetails.Add([pscustomobject]@{ Game = [string]$plan.Game; Reason = 'The files could not be copied and checked. Details and the log say whether this game was changed.'; Technical = [string]$transactionResult.ReasonCode })
        }
        Write-Host ("  ERROR: dgVoodoo2 file transaction did not complete ({0}). Review Details before retrying." -f $transactionResult.Outcome) -ForegroundColor Red
        Write-Log ("dgVoodoo2: direct file transaction outcome={0} reason={1}" -f $transactionResult.Outcome,$transactionResult.ReasonCode)
    }

    Write-Log "dgVoodoo2 setup: TeknoParrot Manager does not remove an unowned dgVoodoo2 hook automatically. Existing or changed files must be removed by hand."
    Write-Log ("dgVoodoo2 setup: deployed={0} skipped={1} missingDevice={2} missingPath={3} errors={4} presetOverrides={5}" -f $deployed, $skipped, $missingDevice, $missingPath, $errors, $presetOverrides)
    $legacySucceeded = ($transactionResult.Outcome -in @('SUCCEEDED','NO_OP') -and $plannedProfiles.Count -gt 0 -and $errors -eq 0 -and $skipped -eq 0 -and $missingDevice -eq 0 -and $missingPath -eq 0)
    # Selected games that already had every file: named on the result screen so every selected game is accounted for.
    $alreadyConfiguredGames = @($plannedProfiles | Where-Object { -not $_.Written } | ForEach-Object { [string]$_.Game })
    return [pscustomobject]@{
        Succeeded = $legacySucceeded
        NoOp = [bool]$noOp
        AlreadyConfigured = $alreadyConfiguredGames
        Deployed = $deployed
        Skipped = $skipped
        MissingDevice = $missingDevice
        MissingPath = $missingPath
        Errors = $errors
        Reason = if ($errors) { if($transactionResult.Outcome -notin @('SUCCEEDED','NO_OP')){$transactionResult.ReasonCode}else{'DEPLOYMENT_ERRORS'} } elseif ($skipped -gt 0 -or $missingDevice -gt 0 -or $missingPath -gt 0) { 'PREFLIGHT_INCOMPLETE' } elseif ($noOp) { 'NO_CHANGES_NEEDED' } elseif ($deployed -eq 0) { 'NO_GAMES_DEPLOYED' } else { $null }
        DeploymentDetails = $deploymentDetails.ToArray()
        SkipDetails = $skipDetails.ToArray()
        PresetOverrides = [int]$presetOverrides
        PickedGames = @($pickedGames)
        FailedDetails = $failedDetails.ToArray()
        TransactionResult = $transactionResult
    }
}

function Get-DgVoodoo2FailureGuidance {
    param($Result)
    $missingDevice = $false
    $missingPath = $false
    if ($null -ne $Result) {
        $missingDevice = [int]$Result.MissingDevice -gt 0
        $missingPath = [int]$Result.MissingPath -gt 0
    }
    return [pscustomobject]@{
        DeviceMessage = if ($missingDevice) { 'The saved game drive or device is unavailable. Reconnect the game drive or device containing the affected games, then retry dgVoodoo2 setup.' } else { $null }
        MissingPathMessage = if ($missingPath) { 'Windows cannot find one or more saved game paths. Use 13) Library Health Check to repair them.' } else { $null }
        OfferHealthCheck = $missingPath
    }
}

# FIX82: the dgVoodoo2 result screen (menu 6): one result line, one "not changed" line and one next step. The full report (what was
# installed where, why, what was not changed, skipped games) is the Details view (key D) and the log. The cleanest result block of
# the older screens was the template: nothing is said twice.
# What happened to each game the user selected: @{ Game; Outcome = changed | already | skipped | failed | notfinished; Reason }.
# A selected game is in exactly one row, so the counts on the result screen add up to the games selected and no game disappears.
function Get-TpmDgVoodoo2GameOutcomes {
    param([Parameter(Mandatory)]$Result)
    $rows = New-Object System.Collections.Generic.List[object]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $picked = @(Get-TpmTransactionField -Object $Result -Name 'PickedGames' -Default @() | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
    $add = {
        param($Game, $Outcome, $Reason)
        $name = [string]$Game
        if ([string]::IsNullOrWhiteSpace($name)) { return }
        if ($picked.Count -gt 0 -and $name -notin $picked) { return }
        if ($seen.Add($name)) { [void]$rows.Add([pscustomobject]@{ Game = $name; Outcome = $Outcome; Reason = [string]$Reason }) }
    }
    foreach ($detail in @(Get-TpmTransactionField -Object $Result -Name 'FailedDetails' -Default @() | Where-Object { $null -ne $_ })) { & $add (Get-TpmTransactionField -Object $detail -Name 'Game' -Default '') 'failed' (Get-TpmTransactionField -Object $detail -Name 'Reason' -Default '') }
    foreach ($detail in @(Get-TpmTransactionField -Object $Result -Name 'DeploymentDetails' -Default @() | Where-Object { $null -ne $_ })) { & $add (Get-TpmTransactionField -Object $detail -Name 'Game' -Default '') 'changed' '' }
    foreach ($game in @(Get-TpmTransactionField -Object $Result -Name 'AlreadyConfigured' -Default @())) { & $add $game 'already' 'It already had every dgVoodoo2 file, so nothing was changed.' }
    foreach ($detail in @(Get-TpmTransactionField -Object $Result -Name 'SkipDetails' -Default @() | Where-Object { $null -ne $_ })) { & $add (Get-TpmTransactionField -Object $detail -Name 'Game' -Default '') 'skipped' (Get-TpmTransactionField -Object $detail -Name 'Reason' -Default '') }
    foreach ($game in $picked) { & $add $game 'notfinished' 'It was not reached, because the setup stopped before it got to this game.' }
    return $rows.ToArray()
}

function Get-TpmDgVoodoo2ResultView {
    param([Parameter(Mandatory)]$Result)
    $installed = @(Get-TpmTransactionField -Object $Result -Name 'DeploymentDetails' -Default @() | Where-Object { $null -ne $_ })
    $skippedGames = @(Get-TpmTransactionField -Object $Result -Name 'SkipDetails' -Default @() | Where-Object { $null -ne $_ })
    $outcomes = @(Get-TpmDgVoodoo2GameOutcomes -Result $Result)
    $changedRows = @($outcomes | Where-Object { $_.Outcome -eq 'changed' })
    $alreadyRows = @($outcomes | Where-Object { $_.Outcome -eq 'already' })
    $skippedRows = @($outcomes | Where-Object { $_.Outcome -eq 'skipped' })
    $failedRows = @($outcomes | Where-Object { $_.Outcome -eq 'failed' })
    $notFinishedRows = @($outcomes | Where-Object { $_.Outcome -eq 'notfinished' })
    $nothingInstalled = ([bool](Get-TpmTransactionField -Object $Result -Name 'NoOp' -Default $false) -or $installed.Count -eq 0)
    $noneAdded = 'No game needed a new dgVoodoo2 file. Nothing was changed.'
    if ($nothingInstalled -and ($failedRows.Count + $notFinishedRows.Count) -gt 0) { $noneAdded = 'dgVoodoo2 could not finish for every game you selected.' }
    $title = $noneAdded
    if (-not $nothingInstalled) { $title = ('dgVoodoo2 was added to {0}.' -f (Format-TpmGameCount -Count $installed.Count)) }
    $alreadyHad = @(Get-TpmTransactionField -Object $Result -Name 'AlreadyConfigured' -Default @() | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    if ($alreadyHad.Count -gt 0) {
        $alreadyText = ('{0} already had every dgVoodoo2 file, so nothing was changed there: {1}.' -f (Format-TpmGameCount -Count $alreadyHad.Count), ($alreadyHad -join ', '))
        if ($nothingInstalled) { $title = ($noneAdded + ' ' + $alreadyText) } else { $title = ($title + ' ' + $alreadyText) }
    }
    # One line per reason, with the names of the games it applies to, so no skipped or failed game is left out.
    $needs = New-Object System.Collections.Generic.List[string]
    $addNeeds = {
        param($Rows, [string]$Word)
        foreach ($group in @($Rows | Group-Object -Property Reason)) {
            [void]$needs.Add(('{0} {1} ({2}). {3}' -f (Format-TpmGameCount -Count $group.Count), $Word, (Format-TpmNameList -Names @($group.Group | ForEach-Object { $_.Game })), ([string]$group.Name).Trim()).Trim())
        }
    }
    & $addNeeds $failedRows 'failed'
    & $addNeeds $notFinishedRows 'not finished'
    & $addNeeds $skippedRows 'skipped'
    $skippedNames = @($skippedRows | ForEach-Object { $_.Game })
    $driveSkips = @($skippedGames | Where-Object { [string](Get-TpmTransactionField -Object $_ -Name 'ReasonCode' -Default '') -eq 'DEVICE_UNAVAILABLE' -and $skippedNames -contains [string](Get-TpmTransactionField -Object $_ -Name 'Game' -Default '') })
    $next = 'Try a game. If it looks wrong or crashes, send a support package and the log.'
    if ($nothingInstalled) { $next = 'Nothing else to do. Press B to go back.' }
    if ($driveSkips.Count -gt 0) { $next = Get-TpmDriveSkipNext }
    elseif (($failedRows.Count + $notFinishedRows.Count) -gt 0) { $next = 'Press D to see why, then run dgVoodoo2 setup again.' }
    # FIX110 (S-9): the DLLs are added only when missing, but a per-game dgVoodoo.conf preset replaces the one in the game folder.
    $notChanged = 'Existing dgVoodoo2 files were not replaced or removed.'
    $presetOverrides = [int](Get-TpmTransactionField -Object $Result -Name 'PresetOverrides' -Default 0)
    if (-not $nothingInstalled -and $presetOverrides -gt 0) {
        $notChanged = ('Existing dgVoodoo2 DLL files were not replaced or removed. The only exception is dgVoodoo.conf: it was replaced for {0} with a preset file of their own.' -f (Format-TpmGameCount -Count $presetOverrides))
    }
    $done = New-Object System.Collections.Generic.List[string]
    $countsLine = Get-TpmStepCountsLine -Picked @(Get-TpmTransactionField -Object $Result -Name 'PickedGames' -Default @()).Count -Changed $changedRows.Count -AlreadySetUp $alreadyRows.Count -Skipped $skippedRows.Count -Failed $failedRows.Count
    if ($countsLine) { [void]$done.Add($countsLine) }
    $backupLine = Get-TpmBackupFolderLine -Result $Result -What 'the files it replaced'
    if ($backupLine) { [void]$done.Add($backupLine) }
    return @{
        Title = $title
        Status = $(if (($failedRows.Count + $notFinishedRows.Count) -gt 0) { 'Problem' } elseif ($needs.Count -gt 0) { 'Attention' } else { 'Ok' })
        Done = $done.ToArray()
        NotChanged = $notChanged
        Needs = $needs
        Next = $next
        DetailBlocks = @(Get-TpmDgVoodoo2DetailBlocks -Result $Result)
    }
}

# Every fact the old result screen showed, as short blocks: one note block, one block per installed game, one per skipped game.
function Get-TpmDgVoodoo2DetailBlocks {
    param([Parameter(Mandatory)]$Result)
    $installed = @(Get-TpmTransactionField -Object $Result -Name 'DeploymentDetails' -Default @() | Where-Object { $null -ne $_ })
    $skippedGames = @(Get-TpmTransactionField -Object $Result -Name 'SkipDetails' -Default @() | Where-Object { $null -ne $_ })
    $overrides = [int](Get-TpmTransactionField -Object $Result -Name 'PresetOverrides' -Default 0)
    $about = New-Object System.Collections.Generic.List[string]
    if ($installed.Count -eq 0) { [void]$about.Add('Result: No game files needed a new dgVoodoo2 DLL.') }
    [void]$about.Add('Why: Older DirectX and Glide games may not display correctly on modern Windows. dgVoodoo2 helps translate those older graphics calls for modern Windows.')
    [void]$about.Add('Not changed: Existing dgVoodoo2 DLL files were not removed or replaced, including unowned or changed files.')
    [void]$about.Add('Also not changed: TeknoParrot Manager only added missing compatibility DLLs. Skipped missing-path games were not changed.')
    [void]$about.Add('Config file: a game with its own preset file in dgVoodoo2Presets gets that file as its dgVoodoo.conf. It replaces the dgVoodoo.conf that was in the game folder. Games without a preset file keep theirs.')
    [void]$about.Add('Note: TeknoParrot Manager does not remove an unowned dgVoodoo2 hook automatically. If you want existing or changed files gone, remove them by hand.')
    if ($overrides -gt 0) { [void]$about.Add(('Config overrides: {0} per-game config override(s) found' -f $overrides)) }
    $blocks = New-Object System.Collections.Generic.List[object]
    [void]$blocks.Add(@{ Heading = 'About this change'; Lines = $about.ToArray() })
    $everyGame = @(Get-TpmDgVoodoo2GameOutcomes -Result $Result)
    if ($everyGame.Count -gt 0) {
        $wording = @{ changed = 'Changed.'; already = 'Already set up.'; skipped = 'Skipped.'; failed = 'Failed.'; notfinished = 'Not finished.' }
        [void]$blocks.Add(@{ Heading = 'Every game you selected'; Lines = @($everyGame | ForEach-Object { ('{0}: {1} {2}' -f $_.Game, $wording[[string]$_.Outcome], $_.Reason).Trim() }) })
    }
    foreach ($detail in $installed) {
        $lines = New-Object System.Collections.Generic.List[string]
        $apis = @(Get-TpmTransactionField -Object $detail -Name 'LegacyApis' -Default @())
        Add-TpmDetailLine -Lines $lines -Label 'Legacy API' -Text $(if ($apis.Count -gt 0) { $apis -join ', ' } else { 'not detected (manual selection)' })
        Add-TpmDetailLine -Lines $lines -Label 'Destination' -Text ([string](Get-TpmTransactionField -Object $detail -Name 'Destination' -Default ''))
        Add-TpmDetailLine -Lines $lines -Label 'Files' -Text (@(Get-TpmTransactionField -Object $detail -Name 'Files' -Default @()) -join ', ')
        Add-TpmDetailLine -Lines $lines -Label 'Config' -Text ([string](Get-TpmTransactionField -Object $detail -Name 'Config' -Default ''))
        [void]$blocks.Add(@{ Heading = [string](Get-TpmTransactionField -Object $detail -Name 'Game' -Default ''); Lines = $lines.ToArray() })
    }
    foreach ($detail in $skippedGames) {
        $lines = New-Object System.Collections.Generic.List[string]
        Add-TpmDetailLine -Lines $lines -Label 'Saved path' -Text ([string](Get-TpmTransactionField -Object $detail -Name 'SavedPath' -Default ''))
        Add-TpmDetailLine -Lines $lines -Label 'Reason' -Text ([string](Get-TpmTransactionField -Object $detail -Name 'Technical' -Default ''))
        Add-TpmDetailLine -Lines $lines -Label 'Next action' -Text ([string](Get-TpmTransactionField -Object $detail -Name 'NextAction' -Default ''))
        [void]$blocks.Add(@{ Heading = ('Skipped game: ' + [string](Get-TpmTransactionField -Object $detail -Name 'Game' -Default '')); Color = 'Yellow'; Lines = $lines.ToArray() })
    }
    return $blocks.ToArray()
}

function Show-TpmDgVoodoo2Result {
    param([Parameter(Mandatory)]$Result)
    $view = Get-TpmDgVoodoo2ResultView -Result $Result
    # The menu under this screen has its own [D] Details key, so Write-TpmOutcome asks no Details question of its own.
    Write-TpmOutcome @view -Unattended
}

# =============================================================================
# XPath 1.0 has no escape for apostrophes in string literals; use concat()
# when the value contains one so the predicate always parses correctly.
function ConvertTo-XPathStringLiteral {
    param([string]$s)
    if ($s -notmatch "'") { return "'$s'" }
    $parts = $s.Split([char]39) | ForEach-Object { "'$_'" }
    return 'concat(' + ($parts -join ',"''",') + ')'
}

# Read-only, best-effort GPU vendor auto-detect via WMI -- no prompting.
# Returns [pscustomobject]@{ Vendor; Name } (Vendor may be $null if
# undetected). Shared by Invoke-GpuFixSetup (which falls back to an
# interactive prompt on failure) and the automatic compatibility check
# (which silently skips on failure, since it must not block an
# unattended-style run with a prompt).
function Get-DetectedGpuVendor {
    param([AllowNull()][object]$HardwareEvidence,[switch]$RequireUnambiguous)
    $gpuVendor = $null
    $gpuName = $null
    $state = 'UNKNOWN'
    $reason = ''
    if ($PSBoundParameters.ContainsKey('HardwareEvidence')) {
        if ($null -eq $HardwareEvidence) {
            $reason = 'No captured GPU evidence was supplied.'
        } else {
            $adapters = @($HardwareEvidence.Adapters)
            if ($RequireUnambiguous -and ([bool]$HardwareEvidence.MultiGpuAmbiguous -or $adapters.Count -gt 1)) {
                $state = 'AMBIGUOUS'
                $reason = 'More than one video adapter is present; the adapter used by this game is not established.'
            } elseif ($RequireUnambiguous -and
                ($adapters.Count -ne 1 -or [string]$HardwareEvidence.ActiveGpuConfidence -cne 'INFERRED' -or
                    $null -eq $HardwareEvidence.ActiveAdapterIndex -or [int]$HardwareEvidence.ActiveAdapterIndex -ne 0)) {
                $reason = 'The active game adapter is not established by the existing hardware evidence.'
            } elseif ($RequireUnambiguous -and
                ([string]::IsNullOrWhiteSpace([string]$HardwareEvidence.ActiveAdapterName) -or
                    [string]$HardwareEvidence.ActiveAdapterName -cne [string]$adapters[0].Name -or
                    [string]$adapters[0].Name -match '(?i)microsoft|virtual|remote')) {
                $reason = 'The single adapter evidence is missing, virtual, remote, or internally inconsistent.'
            } elseif ($adapters.Count -gt 0) {
                $gpuName = if ($RequireUnambiguous) { [string]$HardwareEvidence.ActiveAdapterName } else { [string]$adapters[0].Name }
                if     ($gpuName -imatch 'amd|radeon')             { $gpuVendor = 'AMD' }
                elseif ($gpuName -imatch 'nvidia|geforce|rtx|gtx') { $gpuVendor = 'NVIDIA' }
                elseif ($gpuName -imatch 'intel')                  { $gpuVendor = 'Intel' }
                if ($gpuVendor) { $state = 'KNOWN' } else { $reason = 'The adapter vendor is not recognized.' }
            } else {
                $reason = 'No video adapter was present in the captured evidence.'
            }
        }
    } else {
        try {
            # Preserve the legacy GPU setup behavior. Patch applicability passes captured
            # evidence and RequireUnambiguous, never this highest-memory selection.
            $adapters = @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop -OperationTimeoutSec 10 |
                Where-Object { $_.Name -notmatch '(?i)microsoft|virtual|remote' } |
                Sort-Object { if ($_.AdapterRAM) { [double]$_.AdapterRAM } else { 0.0 } } -Descending)
            if ($adapters.Count -gt 0) {
                $gpuName = [string]$adapters[0].Name
                if     ($gpuName -imatch 'amd|radeon')             { $gpuVendor = 'AMD' }
                elseif ($gpuName -imatch 'nvidia|geforce|rtx|gtx') { $gpuVendor = 'NVIDIA' }
                elseif ($gpuName -imatch 'intel')                  { $gpuVendor = 'Intel' }
                if ($gpuVendor) { $state = 'KNOWN' } else { $reason = 'The adapter vendor is not recognized.' }
            } else {
                $reason = 'No supported video adapter was detected.'
            }
        } catch {
            $reason = 'GPU detection failed.'
            Write-Log "Get-DetectedGpuVendor: WMI detection failed -- $_"
        }
    }
    return [pscustomobject]@{ Vendor=$gpuVendor; Name=$gpuName; State=$state; Reason=$reason }
}

# Discovers GPU fix field names by scanning TeknoParrot GameProfiles at
# runtime, so newly added games with new fix fields are covered
# automatically without a script update. Shared (read-only) between
# Invoke-GpuFixSetup and the Library health check's coverage report --
# extracting this avoids the two ever silently drifting apart.
function Get-GpuFixFieldNames {
    param([string]$TpRoot)

    $gpDir         = Join-Path $TpRoot "GameProfiles"
    $boolAmdFields = [System.Collections.Generic.HashSet[string]]::new(
                         [string[]]@('EnableAmdFix','AMDCrashFix','AMDFix'),
                         [System.StringComparer]::OrdinalIgnoreCase)
    $dropdownGpuFields = [System.Collections.Generic.HashSet[string]]::new(
                             [string[]]@('GPU Fix'),
                             [System.StringComparer]::OrdinalIgnoreCase)

    if (Test-Path -LiteralPath $gpDir) {
        $gpFiles = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $gpDir -ProgressLabel 'GPU Fix GameProfiles discovery' -Filter '*.xml' -EnumerationErrorAction Stop -IncludeDirectories)
        $scanStarted = Get-Date
        $scanCurrent = 0
        $scanCurrentDone = $false
        try {
            foreach ($gf in $gpFiles) {
                $scanCurrent++
                Write-TpmCompactExtractionProgress -Phase Scanning -Label 'TeknoParrot profile catalog scan' -Current $scanCurrent -Total $gpFiles.Count -StartedAt $scanStarted
                try {
                $gdoc = Read-Xml $gf.FullName
                $fnodes = $gdoc.SelectNodes("/GameProfile/ConfigValues/FieldInformation")
                foreach ($n in $fnodes) {
                    $fn = if ($n.FieldName) { $n.FieldName.Trim() } else { '' }
                    $ft = if ($n.FieldType)  { $n.FieldType.Trim()  } else { '' }
                    if (-not $fn) { continue }
                    if ($ft -eq 'Bool' -and $fn -imatch '\bamd\b|\bradeon\b|AMDFix|AMDCrash') {
                        [void]$boolAmdFields.Add($fn)
                    } elseif ($ft -eq 'Dropdown') {
                        $opts = @($n.SelectNodes("FieldOptions/string") | ForEach-Object { $_.InnerText.Trim() })
                        if ($opts | Where-Object { $_ -imatch '^amd$|^nvidia$|^intel$|^new amd' }) {
                            [void]$dropdownGpuFields.Add($fn)
                        }
                    }
                }
                } catch {
                    Write-Log ("GPU Fix: WARNING -- could not parse GameProfile '$($gf.BaseName)': $_")
                }
            }
            $scanCurrentDone = $true
        } finally {
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'GameProfiles' -Current $(if ($scanCurrentDone) { $scanCurrent } else { $scanCurrent - 1 }) -Total $gpFiles.Count -StartedAt $scanStarted -Complete -Outcome $(if ($scanCurrentDone) { 'Final' } else { 'Error' })
        }
    }
    return [pscustomobject]@{ BoolFields = $boolAmdFields; DropdownFields = $dropdownGpuFields; GameProfilesFound = (Test-Path -LiteralPath $gpDir) }
}

# Combines Get-GpuFixFieldNames and Get-FFBBlasterFieldNames into a single
# pass over GameProfiles. The Library health check needs both sets of
# fields in the same run, and calling the two functions separately means
# every GameProfile XML in the folder (TeknoParrot ships profiles for its
# entire supported-game catalog, not just the user's library, so this can
# be 1000+ files) gets parsed twice for no reason. Returns
# [pscustomobject]@{ Gpu = <same shape as Get-GpuFixFieldNames>; Ffb = <same shape as Get-FFBBlasterFieldNames> }
# -- the matching logic for each is identical to the two standalone
# functions, just evaluated in the same loop iteration. Invoke-GpuFixSetup and
# Invoke-FFBBlasterSetup continue to own their standalone mutation and backup
# contracts; only the health check's combined-need call site switches to this
# helper.
function Get-GpuAndFfbFieldNames {
    param([string]$TpRoot)

    $gpDir             = Join-Path $TpRoot "GameProfiles"
    # The same built-in field names as Get-GpuFixFieldNames, so both screens agree when GameProfiles is missing or one XML cannot be read.
    $boolAmdFields     = [System.Collections.Generic.HashSet[string]]::new([string[]]@('EnableAmdFix','AMDCrashFix','AMDFix'), [System.StringComparer]::OrdinalIgnoreCase)
    $dropdownGpuFields = [System.Collections.Generic.HashSet[string]]::new([string[]]@('GPU Fix'), [System.StringComparer]::OrdinalIgnoreCase)
    $ffbFields         = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $gpDirExists       = Test-Path -LiteralPath $gpDir

    if ($gpDirExists) {
        $gpFiles = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $gpDir -ProgressLabel 'GPU and FFB GameProfiles discovery' -Filter '*.xml' -EnumerationErrorAction Stop -IncludeDirectories)
        $scanStarted = Get-Date
        $scanCurrent = 0
        $scanCurrentDone = $false
        try {
            foreach ($gf in $gpFiles) {
                $scanCurrent++
                Write-TpmCompactExtractionProgress -Phase Scanning -Label 'TeknoParrot profile catalog scan' -Current $scanCurrent -Total $gpFiles.Count -StartedAt $scanStarted
                try {
                $gdoc = Read-Xml $gf.FullName
                $fnodes = $gdoc.SelectNodes("/GameProfile/ConfigValues/FieldInformation")
                foreach ($n in $fnodes) {
                    $cn = if ($n.CategoryName) { $n.CategoryName.Trim() } else { '' }
                    $fn = if ($n.FieldName)     { $n.FieldName.Trim()     } else { '' }
                    $ft = if ($n.FieldType)     { $n.FieldType.Trim()     } else { '' }
                    if ($ft -eq 'Bool') {
                        if ($fn -and $fn -imatch '\bamd\b|\bradeon\b|AMDFix|AMDCrash') {
                            [void]$boolAmdFields.Add($fn)
                        }
                        if ($cn -imatch 'ffb.*blaster|blaster.*ffb') {
                            [void]$ffbFields.Add($cn)
                        } elseif ($fn -and $fn -imatch 'ffb.*blaster|blaster.*ffb') {
                            [void]$ffbFields.Add($fn)
                        }
                    } elseif ($ft -eq 'Dropdown') {
                        $opts = @($n.SelectNodes("FieldOptions/string") | ForEach-Object { $_.InnerText.Trim() })
                        if ($opts | Where-Object { $_ -imatch '^amd$|^nvidia$|^intel$|^new amd' }) {
                            [void]$dropdownGpuFields.Add($fn)
                        }
                    }
                }
            } catch {
                Write-Log ("GpuAndFfbFieldScan: WARNING -- could not parse GameProfile '$($gf.BaseName)': $_")
            }
        }
        $scanCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'GameProfiles' -Current $(if ($scanCurrentDone) { $scanCurrent } else { $scanCurrent - 1 }) -Total $gpFiles.Count -StartedAt $scanStarted -Complete -Outcome $(if ($scanCurrentDone) { 'Final' } else { 'Error' })
    }
}

    return [pscustomobject]@{
        Gpu = [pscustomobject]@{ BoolFields = $boolAmdFields; DropdownFields = $dropdownGpuFields; GameProfilesFound = $gpDirExists }
        Ffb = $ffbFields
    }
}

# Pure decision function: for a given UserProfile XML and the field names
# discovered by Get-GpuFixFieldNames, determines whether the profile has
# any GPU fix field at all (Eligible) and, if so, whether every such
# field already matches the value expected for $Vendor (UpToDate). Also
# returns the exact node + new value for each field that needs changing,
# so Invoke-GpuFixSetup can apply them without re-deriving the same
# vendor-specific value logic a second time.
function Test-GpuFixUpToDate {
    param([System.Xml.XmlDocument]$Doc, $BoolFields, $DropdownFields, [string]$Vendor)

    $eligible = $false
    $changes  = New-Object System.Collections.Generic.List[object]

    foreach ($fieldName in $BoolFields) {
        $xpLit = ConvertTo-XPathStringLiteral $fieldName
        $fi = $Doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$xpLit]")
        if ($null -eq $fi) { continue }
        $fvNode = $fi.SelectSingleNode("FieldValue")
        if ($null -eq $fvNode) { continue }
        $eligible = $true
        $newVal = if ($Vendor -eq 'AMD') { '1' } else { '0' }
        if ($fvNode.InnerText -ne $newVal) {
            [void]$changes.Add([pscustomobject]@{ FieldName = $fieldName; Node = $fvNode; OldValue = $fvNode.InnerText; NewValue = $newVal })
        }
    }

    foreach ($fieldName in $DropdownFields) {
        $xpLit = ConvertTo-XPathStringLiteral $fieldName
        $fi = $Doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$xpLit]")
        if ($null -eq $fi) { continue }
        $fvNode = $fi.SelectSingleNode("FieldValue")
        $opts   = @($fi.SelectNodes("FieldOptions/string") | ForEach-Object { $_.InnerText.Trim() })
        if ($null -eq $fvNode -or $opts.Count -eq 0) { continue }
        $eligible = $true

        $newVal = 'None'
        if ($Vendor -eq 'AMD') {
            if     ($opts -contains 'New AMD Driver') { $newVal = 'New AMD Driver' }
            elseif ($opts -contains 'AMD')            { $newVal = 'AMD'            }
        } elseif ($Vendor -eq 'NVIDIA') {
            if ($opts -contains 'NVIDIA') { $newVal = 'NVIDIA' }
        } elseif ($Vendor -eq 'Intel') {
            if ($opts -contains 'INTEL') { $newVal = 'INTEL' }
        }

        if ($fvNode.InnerText -ne $newVal) {
            [void]$changes.Add([pscustomobject]@{ FieldName = $fieldName; Node = $fvNode; OldValue = $fvNode.InnerText; NewValue = $newVal })
        }
    }

    return [pscustomobject]@{ Eligible = $eligible; UpToDate = ($eligible -and $changes.Count -eq 0); Changes = $changes }
}

# =============================================================================
# POSTGRESQL DETECTION  (read-only helpers, shared by Postgres setup mode
# and the Library health check's coverage report)
# =============================================================================
# Every Incredible Technologies game with a database (all Golden Tee Live and
# PGA Tour years, Power Putt Live, Silver Strike Bowling Live, Target Toss Pro,
# Orange County Choppers Pinball: 31 profiles in the TeknoParrot install checked
# in November 2026) needs a local PostgreSQL 8.3 database. Their Postgres settings
# live inside ConfigValues/FieldInformation under CategoryName=Postgres --
# the same generic per-game-setting structure GPU Fix/FFB Blaster above
# already use. Field names are identical across every such profile (Path,
# Address, Port, DbName, User, Pass, and "Automatically create Database" on
# Golden Tee Live 2018 and newer), so unlike GPU Fix this never needs per-game
# field-name variant matching -- just the category existence check below. No
# game name or year is listed here on purpose: a new game of this kind works
# as soon as its profile has the category.

$script:PostgresInstallDir  = "C:\Program Files (x86)\PostgreSQL\8.3"
$script:PostgresBinDir      = Join-Path $script:PostgresInstallDir "bin"
$script:PostgresServiceName = "pgsql-8.3"

# Where a game keeps its database, from the profile's Database > Storage field (newer TeknoParrot profiles).
# Returns 'Internal', 'ExistingPostgreSQL', or $null when the field is missing, repeated or has another value
# (an older profile: it is treated exactly as before). TeknoParrot Manager only reads this field; it never writes it.
function Get-TpmGameDatabaseStorage {
    param([System.Xml.XmlDocument]$Doc)
    $nodes = $Doc.SelectNodes("/GameProfile/ConfigValues/FieldInformation[CategoryName='Database' and FieldName='Storage']")
    if ($nodes.Count -ne 1) { return $null }
    $value = $nodes[0].SelectSingleNode('FieldValue')
    if ($null -eq $value) { return $null }
    $text = ([string]$value.InnerText).Trim()
    if ($text -ieq 'Internal') { return 'Internal' }
    if ($text -ieq 'Existing PostgreSQL') { return 'ExistingPostgreSQL' }
    return $null
}

# Two plain sentences for every screen that talks about a game's database (the choice belongs to the user).
function Get-TpmDatabaseChoiceLines {
    return @(
        'Internal is the new default. The game keeps its own database, no database install is needed, and the game must be started once so it creates that database.',
        'Existing PostgreSQL is for keeping an existing PostgreSQL server and its saved progress. TeknoParrot Manager never switches a game from one to the other for you; you change it in the game''s TeknoParrot settings.'
    )
}

# Returns $true if this profile uses PostgreSQL: it has Postgres-category fields and its Storage is not Internal.
# A game set to Internal needs no PostgreSQL, so every PostgreSQL check, install prompt and setup step skips it.
function Test-GameNeedsPostgres {
    param([System.Xml.XmlDocument]$Doc)
    if ((Get-TpmGameDatabaseStorage -Doc $Doc) -eq 'Internal') { return $false }
    $node = $Doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[CategoryName='Postgres']")
    return ($null -ne $node)
}

# True when every Postgres setting a game needs is filled in (Library Health and the registration offer use the same rule).
function Test-TpmPostgresSettingsComplete {
    param([System.Xml.XmlDocument]$Doc)
    foreach ($fieldName in @('DbName','Path','Address','Port','User','Pass')) {
        if ([string]::IsNullOrWhiteSpace((Get-PostgresFieldValue $Doc $fieldName))) { return $false }
    }
    return $true
}

# After a registration (issue #131): offer the existing PostgreSQL setup when a game that was just registered needs
# PostgreSQL and has no settings yet. Returns $true only when the user says yes; the caller then opens PostgreSQL setup.
# Asks nothing in unattended or preview runs, and changes nothing itself.
function Invoke-TpmPostgresRegistrationOffer {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [string[]]$RegisteredCodes = @(), [switch]$Unattended, [switch]$DryRun)
    if ($Unattended -or $DryRun -or @($RegisteredCodes).Count -eq 0) { return $false }
    $newGames = New-Object System.Collections.Generic.List[string]
    $newInternal = New-Object System.Collections.Generic.List[string]
    $existingChosen = $false
    $otherCount = 0
    foreach ($pf in @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter '*.xml' -File -ErrorAction SilentlyContinue)) {
        try {
            $doc = Read-Xml $pf.FullName
            if ($doc.GameProfile -and $RegisteredCodes -contains $pf.BaseName -and (Get-TpmGameDatabaseStorage -Doc $doc) -eq 'Internal') { [void]$newInternal.Add((Get-TpmGameDisplayLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName)); continue }
            if (-not $doc.GameProfile -or -not (Test-GameNeedsPostgres $doc) -or (Test-TpmPostgresSettingsComplete -Doc $doc)) { continue }
            if ((Get-TpmGameDatabaseStorage -Doc $doc) -eq 'ExistingPostgreSQL') { $existingChosen = $true }
        } catch { continue }
        if ($RegisteredCodes -contains $pf.BaseName) { [void]$newGames.Add((Get-TpmGameDisplayLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName)) } else { $otherCount++ }
    }
    if ($newInternal.Count -gt 0) {
        Write-Host ''
        Write-Host ('  {0} you just added use{1} Internal storage: {2}.' -f $(if ($newInternal.Count -eq 1) { 'A game' } else { 'Games' }), $(if ($newInternal.Count -eq 1) { 's' } else { '' }), ($newInternal -join ', ')) -ForegroundColor Cyan
        foreach ($choiceLine in (Get-TpmDatabaseChoiceLines)) { Write-Host ('  ' + $choiceLine) -ForegroundColor DarkCyan }
        Write-Log ('Registration: {0} new game(s) use Internal database storage; no PostgreSQL is needed for them: {1}.' -f $newInternal.Count, ($newInternal -join ', '))
    }
    if ($newGames.Count -eq 0) { return $false }
    Write-Host ''
    Write-Host ('  {0} you just added need{1} PostgreSQL: {2}.' -f $(if ($newGames.Count -eq 1) { 'A game' } else { 'Games' }), $(if ($newGames.Count -eq 1) { 's' } else { '' }), ($newGames -join ', ')) -ForegroundColor Cyan
    Write-Host '  PostgreSQL is a small database program. These games keep their data in it' -ForegroundColor DarkCyan
    Write-Host '  and will not start without it.' -ForegroundColor DarkCyan
    if ($existingChosen) {
        Write-Host '  They are set to Existing PostgreSQL. The new default,' -ForegroundColor DarkCyan
        Write-Host '  Internal, needs no database install; nothing is switched for you.' -ForegroundColor DarkCyan
    }
    if (Test-PostgresInstalled) { Write-Host '  PostgreSQL is already on this PC.' -ForegroundColor DarkCyan; Write-Host '  TeknoParrot Manager can set up the game now.' -ForegroundColor DarkCyan }
    else { Write-Host '  PostgreSQL is not on this PC yet.' -ForegroundColor DarkCyan; Write-Host '  TeknoParrot Manager can install it and set up the game now.' -ForegroundColor DarkCyan }
    if ($otherCount -gt 0) { Write-Host ('  {0} other game(s) already registered also still need PostgreSQL settings.' -f $otherCount) -ForegroundColor DarkCyan }
    Write-Host '  Nothing changes unless you say yes.' -ForegroundColor DarkCyan
    $accepted = ((Read-TpmYesNo -Prompt '  Set up PostgreSQL now? (Y/N)') -eq 'Y')
    Write-Log ('Registration offer: PostgreSQL setup for {0} new game(s): {1}.' -f $newGames.Count, $(if ($accepted) { 'accepted' } else { 'declined' }))
    if (-not $accepted) {
        Write-Host '  Nothing was changed. These games will not start until PostgreSQL is set up.' -ForegroundColor Yellow
        Write-Host "  When you are ready, choose 'Postgres setup' in the main menu." -ForegroundColor DarkCyan
        Write-Host '  Library Health also lists games that still need it.' -ForegroundColor DarkCyan
    }
    return $accepted
}

function Get-TpmPostgresRequirementScan {
    param([Parameter(Mandatory)][AllowEmptyCollection()][System.IO.FileInfo[]]$ProfileFiles)
    $needCount = 0
    $internalCount = 0
    $scanBlocked = $false
    $scanStarted = Get-Date
    $scanCurrent = 0
    $scanCurrentDone = $false
    try {
        foreach ($profileFile in $ProfileFiles) {
            $scanCurrent++
            Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'PostgreSQL requirement profile scan' -Current $scanCurrent -Total $ProfileFiles.Count -StartedAt $scanStarted
            try {
                $doc = Read-Xml $profileFile.FullName
                if ($doc.GameProfile -and (Test-GameNeedsPostgres $doc)) { $needCount++ }
                elseif ($doc.GameProfile -and (Get-TpmGameDatabaseStorage -Doc $doc) -eq 'Internal') { $internalCount++ }
            } catch {
                $scanBlocked = $true
                Write-Log "Postgres setup: profile scan failed for $($profileFile.BaseName); recovery is blocked."
            }
        }
        $scanCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'PostgreSQL requirement profile scan' -Current $(if ($scanCurrentDone) { $scanCurrent } else { $scanCurrent - 1 }) -Total $ProfileFiles.Count -StartedAt $scanStarted -Complete -Outcome $(if ($scanCurrentDone -and -not $scanBlocked) { 'Final' } else { 'Error' })
    }
    return [pscustomobject]@{ NeedCount = $needCount; InternalCount = $internalCount; ScanBlocked = $scanBlocked }
}

# Reads one named field's current value from the Postgres category, or
# $null if the field is missing entirely (distinct from an empty string,
# which means the field exists but is blank -- callers care about this
# distinction: "Automatically create Database" being absent means an older
# GameProfileRevision that predates the feature, not that it's off).
function Get-PostgresFieldValue {
    param([System.Xml.XmlDocument]$Doc, [string]$FieldName)
    $xpLit = ConvertTo-XPathStringLiteral $FieldName
    $fi = $Doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[CategoryName='Postgres' and FieldName=$xpLit]")
    if ($null -eq $fi) { return $null }
    $fvNode = $fi.SelectSingleNode("FieldValue")
    if ($null -eq $fvNode) { return $null }
    return $fvNode.InnerText
}

# Only one explicit upstream 1/0 is evidence of capability; legacy, blank,
# malformed or duplicate fields are unknown, never an assertion of disabled.
function Get-PostgresAutoCreateCapability {
    param([System.Xml.XmlDocument]$Doc)
    $fields = $Doc.SelectNodes("/GameProfile/ConfigValues/FieldInformation[CategoryName='Postgres' and FieldName='Automatically create Database']")
    if ($fields.Count -ne 1) { return $null }
    $values = $fields[0].SelectNodes('FieldValue')
    if ($values.Count -ne 1 -or $values[0].SelectNodes('*').Count -ne 0) { return $null }
    if ($values[0].InnerText -ceq '1') { return $true }
    if ($values[0].InnerText -ceq '0') { return $false }
    return $null
}

# Sets one named field's value in the Postgres category. No-op (returns
# $false) if the field doesn't exist on this profile -- never creates a
# new field, since the schema is owned by TeknoParrot's own GameProfile
# definitions, not by this script.
function Set-PostgresFieldValue {
    param([System.Xml.XmlDocument]$Doc, [string]$FieldName, [string]$Value)
    $xpLit = ConvertTo-XPathStringLiteral $FieldName
    $fi = $Doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[CategoryName='Postgres' and FieldName=$xpLit]")
    if ($null -eq $fi) { return $false }
    $fvNode = $fi.SelectSingleNode("FieldValue")
    if ($null -eq $fvNode) { return $false }
    $fvNode.InnerText = $Value
    return $true
}

# Validates a database name is safe to interpolate into a SQL string/CLI
# argument before any Postgres operation touches it. DbName ultimately
# comes from a GameProfile XML field -- shipped by TeknoParrot, but this
# script treats it as semi-trusted rather than blindly safe in a SQL
# context, matching the project's "external-ish input into a command must
# be validated" convention used elsewhere (e.g. Test-PathInside for
# filesystem paths). Every real DbName observed (GameDB19, GAMEDBPP12,
# GameDBSSB, GameDBBags, etc.) is plain alphanumeric, so this is not a
# practical restriction -- just a guard against the unexpected.
function Test-SafePostgresDbName {
    param([string]$DbName)
    # \A..\z: '$' would also accept a trailing newline, and this name is interpolated into SQL and tool arguments.
    return ($DbName -match '\A[A-Za-z0-9_]+\z')
}

# FIX95 (S5): the postgres password reaches libpq through the PGPASSWORD
# environment variable of this process, set by Invoke-PostgresNativeCommand only
# around the one child call and put back in its finally. No password file is
# written, so a killed TeknoParrot Manager or a power cut leaves no password on
# disk: the variable ends with the process. Builds before FIX95 wrote a
# short-lived, owner-only PGPASSFILE instead (issue #3); that file was readable
# by the same Windows user just as the child's environment is, and it stayed on
# disk after a hard kill. The password is never put on a command line, in the
# log or in a result (callers pass it as a Secret for redaction). GameProfile
# Pass values remain a compatibility-required plaintext boundary for
# TeknoParrotUI; recovery backups are ACL-locked evidence.
function Set-PostgresPasswordEnvironment {
    param([Parameter(Mandatory)][string]$Password)
    $previous = [Environment]::GetEnvironmentVariable('PGPASSWORD', 'Process')
    [Environment]::SetEnvironmentVariable('PGPASSWORD', $Password, 'Process')
    return $previous
}

function Restore-PostgresPasswordEnvironment {
    # Untyped on purpose: a [string] parameter turns an originally-unset
    # variable ($null) into ''. Only a truly null prior value removes the
    # variable, via [NullString]::Value (PowerShell passes $null to a .NET
    # string argument as ''). An explicit empty prior value, which PowerShell 7
    # can hold, is restored as empty.
    param($PreviousValue)
    if ($null -eq $PreviousValue) {
        [Environment]::SetEnvironmentVariable('PGPASSWORD', [NullString]::Value, 'Process')
    } else {
        [Environment]::SetEnvironmentVariable('PGPASSWORD', [string]$PreviousValue, 'Process')
    }
}

# FIX110A B-1: builds before FIX95 wrote temporary credential files, and a hard
# kill skipped the finally that deleted them. Nothing proves that a file with such
# a name in the shared temp folder was made by TeknoParrot Manager (a name, an
# access list and a process id can all be copied or reused, and a delete by path
# cannot tell the file that was checked from one put there afterwards), so this
# only REPORTS how many files have the old name shape. It never opens, reads or
# deletes them. Never throws; returns the count and the folder.
function Get-PostgresLeftoverPgPassFiles {
    param([string]$Directory = '')
    $summary = [pscustomobject]@{ Found = 0; Directory = '' }
    try {
        if ([string]::IsNullOrWhiteSpace($Directory)) { $Directory = [System.IO.Path]::GetTempPath() }
        $summary.Directory = [System.IO.Path]::GetFullPath($Directory)
        $candidates = @([System.IO.Directory]::GetFiles($summary.Directory, 'tpm-pgpass-*.conf', [System.IO.SearchOption]::TopDirectoryOnly))
    } catch {
        Write-Log 'Postgres credential check: the temp folder could not be listed.'
        return $summary
    }
    foreach ($candidate in $candidates) {
        try {
            $name = [System.IO.Path]::GetFileName($candidate)
            $info = New-Object System.IO.FileInfo($candidate)
            if ($info.Exists -and ($info.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -eq 0 -and ($name -match '^tpm-pgpass-(\d{1,10}-)?[0-9a-f]{32}\.conf$')) { $summary.Found++ }
        } catch { Write-Log 'Postgres credential check: one file in the temp folder could not be checked.' }
    }
    if ($summary.Found -gt 0) {
        Write-Log ('Postgres credential check: {0} file(s) named tpm-pgpass-*.conf were found in the temp folder and were left in place (not read, not deleted).' -f $summary.Found)
    }
    return $summary
}

function Wait-PostgresServiceState {
    param([Parameter(Mandatory)][string]$DesiredStatus, [int]$TimeoutSeconds = 30)
    $service = Get-Service -Name $script:PostgresServiceName -ErrorAction Stop
    if ($service.PSObject.Methods.Name -contains 'WaitForStatus') {
        # Up to $TimeoutSeconds of silence while the service starts or stops: "still working", never "stalled".
        $longWait = $false
        if (Test-Path -LiteralPath 'Function:\Enter-TpmLongWait') { $longWait = Enter-TpmLongWait }
        try { $service.WaitForStatus($DesiredStatus, [TimeSpan]::FromSeconds($TimeoutSeconds)) }
        finally { if ($longWait) { Exit-TpmLongWait } }
    }
    $observed = Get-Service -Name $script:PostgresServiceName -ErrorAction Stop
    if ([string]$observed.Status -ne $DesiredStatus) {
        throw "PostgreSQL service did not reach the required state '$DesiredStatus'."
    }
    return $observed
}

function Test-PostgresInstalled {
    $svc = Get-Service -Name $script:PostgresServiceName -ErrorAction SilentlyContinue
    $psqlExists = Test-Path -LiteralPath (Join-Path $script:PostgresBinDir 'psql.exe')
    return (($null -ne $svc) -and $psqlExists)
}
# Collects read-only evidence for a failed protected PostgreSQL backup. This
# deliberately does not start/stop services, change credentials, or rewrite
# profiles: the caller must show the observed cause before offering another
# backup attempt.
function Get-PostgresDiagnosisCategoryLabel {
    param([string]$Category)
    switch ($Category) {
        'PasswordAuthenticationFailed' { return 'Password authentication' }
        'ServiceNotRunning' { return 'PostgreSQL service' }
        'DatabaseMissing' { return 'Missing PostgreSQL database' }
        'DatabaseCorrupt' { return 'PostgreSQL database integrity' }
        'ToolUnavailable' { return 'PostgreSQL client tools' }
        'PermissionOrElevation' { return 'PostgreSQL permissions' }
        'CannotConnect' { return 'PostgreSQL connection' }
        'CommandCompatibility' { return 'PostgreSQL command compatibility' }
        'InvalidDatabaseName' { return 'Game profile database name' }
        default { return 'PostgreSQL backup issue' }
    }
}
# Plain one-line reason for the screen. The category names above are for Details.
function Get-PostgresDiagnosisPlainProblem {
    param([string]$Category)
    switch ($Category) {
        'PasswordAuthenticationFailed' { return 'PostgreSQL did not accept the saved password.' }
        'ServiceNotRunning' { return 'PostgreSQL is not running.' }
        'DatabaseMissing' { return 'A game''s saved data could not be found.' }
        'DatabaseCorrupt' { return 'A game''s saved data looks damaged.' }
        'ToolUnavailable' { return 'The PostgreSQL tools could not be found.' }
        'PermissionOrElevation' { return 'Windows did not allow the access PostgreSQL needed.' }
        'CannotConnect' { return 'TeknoParrot Manager could not connect to PostgreSQL.' }
        'CommandCompatibility' { return 'The installed PostgreSQL tools did not understand a command.' }
        'InvalidDatabaseName' { return 'A game profile is missing a usable database name.' }
        default { return 'The safety backup failed and PostgreSQL did not say why.' }
    }
}
function Get-PostgresBackupRepairDiagnosis {
    param([Parameter(Mandatory)][object]$BackupResult)
    $technicalChecks = New-Object System.Collections.Generic.List[object]
    $normalChecks = New-Object System.Collections.Generic.List[object]
    $service = $null
    try {
        $service = Get-Service -Name $script:PostgresServiceName -ErrorAction Stop
        $serviceCheck = [pscustomobject]@{
            Name = 'PostgreSQL service'
            Status = 'Present'
            Detail = ('{0} ({1})' -f $script:PostgresServiceName, [string]$service.Status)
        }
    } catch {
        $serviceCheck = [pscustomobject]@{
            Name = 'PostgreSQL service'
            Status = 'Missing'
            Detail = ('Could not verify service {0}.' -f $script:PostgresServiceName)
        }
    }
    [void]$technicalChecks.Add($serviceCheck)
    [void]$normalChecks.Add([pscustomobject]@{
        Name = 'PostgreSQL service'
        Status = $serviceCheck.Status
    })

    $toolPaths = @(
        (Join-Path $script:PostgresBinDir 'psql.exe'),
        (Join-Path $script:PostgresBinDir 'pg_dump.exe')
    )
    $toolStates = New-Object System.Collections.Generic.List[object]
    foreach ($toolPath in $toolPaths) {
        $toolName = [System.IO.Path]::GetFileName($toolPath)
        $toolCheck = if (Test-Path -LiteralPath $toolPath -PathType Leaf) {
            [pscustomobject]@{
                Name = $toolName
                Status = 'Present'
                Detail = $toolPath
            }
        } else {
            [pscustomobject]@{
                Name = $toolName
                Status = 'Missing'
                Detail = $toolPath
            }
        }
        [void]$technicalChecks.Add($toolCheck)
        [void]$toolStates.Add($toolCheck)
    }
    $missingTools = @($toolStates | Where-Object { $_.Status -ne 'Present' }).Count
    [void]$normalChecks.Add([pscustomobject]@{
        Name = 'PostgreSQL client tools'
        Status = if ($missingTools -eq 0) { 'Present' } else { 'Missing' }
    })

    $pgDumpPath = Join-Path $script:PostgresBinDir 'pg_dump.exe'
    $versionCheck = $null
    if (Test-Path -LiteralPath $pgDumpPath -PathType Leaf) {
        try {
            $versionResult = Invoke-PostgresNativeCommand -FilePath $pgDumpPath -Arguments @('--version')
            $versionText = [string]$versionResult.Output
            $versionExitCode = [int]$versionResult.ExitCode
            if ($versionExitCode -eq 0 -and $versionText) {
                $versionCheck = [pscustomobject]@{
                    Name = 'pg_dump version'
                    Status = 'Reported'
                    Detail = $versionText
                }
            } else {
                $versionCheck = [pscustomobject]@{
                    Name = 'pg_dump version'
                    Status = 'Failed'
                    Detail = 'pg_dump did not report a version.'
                }
            }
        } catch {
            $versionCheck = [pscustomobject]@{
                Name = 'pg_dump version'
                Status = 'Failed'
                Detail = 'pg_dump could not be executed for a version check.'
            }
        }
        [void]$technicalChecks.Add($versionCheck)
        [void]$normalChecks.Add([pscustomobject]@{
            Name = 'PostgreSQL client version'
            Status = $versionCheck.Status
        })
    }

    foreach ($diagnosis in @($BackupResult.FailureDiagnoses)) {
        $pair = if ($diagnosis.GameLabel -and $diagnosis.Database) {
            '{0} / {1}' -f $diagnosis.GameLabel, $diagnosis.Database
        } elseif ($diagnosis.GameLabel) {
            [string]$diagnosis.GameLabel
        } else {
            [string]$diagnosis.Database
        }
        $profileKey = [string]$diagnosis.ProfileKey
        $technicalName = if ($profileKey) {
            'Backup failure: {0} (ProfileKey: {1})' -f $pair, $profileKey
        } else {
            'Backup failure: {0}' -f $pair
        }
        [void]$technicalChecks.Add([pscustomobject]@{
            Name = $technicalName
            Status = [string]$diagnosis.Category
            Detail = [string]$diagnosis.Detail
            ProfileKey = $profileKey
            Database = [string]$diagnosis.Database
        })
    }
    $detailCount = 0
    foreach ($detail in @($BackupResult.FailureDetails)) {
        if ($detail) {
            $detailCount++
            [void]$technicalChecks.Add([pscustomobject]@{
                Name = 'Backup detail'
                Status = 'Reported'
                Detail = [string]$detail
            })
        }
    }

    foreach ($group in @($BackupResult.FailureDiagnoses | Group-Object -Property Category | Sort-Object Name)) {
        $normalName = Get-PostgresDiagnosisCategoryLabel -Category ([string]$group.Name)
        $status = if ($group.Count -eq 1) { 'Reported' } else { 'Reported for {0} games' -f $group.Count }
        [void]$normalChecks.Add([pscustomobject]@{
            Name = $normalName
            Status = $status
        })
    }
    if ($detailCount -gt 0) {
        [void]$normalChecks.Add([pscustomobject]@{
            Name = 'Additional backup details'
            Status = '{0} more detail(s) are under Details' -f $detailCount
        })
    }

    $serviceRunning = ($null -ne $service -and [string]$service.Status -ne 'Stopped')
    $pgDumpPresent = Test-Path -LiteralPath $pgDumpPath -PathType Leaf
    $summary = if (-not $service) {
        'TeknoParrot Manager could not find the PostgreSQL service.'
    } elseif (-not $serviceRunning) {
        'PostgreSQL is not running.'
    } elseif (-not $pgDumpPresent) {
        'The PostgreSQL tools that make the safety backup are missing.'
    } elseif (@($BackupResult.FailureDiagnoses).Count -gt 0) {
        'The safety backup still failed for some games.'
    } else {
        'The safety backup failed and PostgreSQL did not say why.'
    }
    return [pscustomobject]@{
        Summary = $summary
        Checks = @($technicalChecks.ToArray())
        TechnicalChecks = @($technicalChecks.ToArray())
        NormalChecks = @($normalChecks.ToArray())
        ReadOnly = $true
    }
}


# Returns a verified tri-state result instead of collapsing a connection or
# query failure into "database absent". Creation is allowed only when
# Verified is true and Exists is false.
function Get-PostgresFailureDiagnosis {
    param([string]$GameLabel, [string]$DbName, [string]$Detail, [int]$ExitCode = 1, [string]$ProfileKey = '')
    $text = [string]$Detail
$category = 'UnknownQueryFailure'; $next = 'Review the PostgreSQL log details, then retry after correcting the reported condition.'
if ($text -match '(?i)(illegal|unknown|unrecognized)\s+option\s+(-{1,2}\s*w|-w)|option.*-{1,2}\s*w') { $category = 'CommandCompatibility'; $next = 'The installed PostgreSQL 8.3 tools reject TeknoParrot Manager''s password-suppression flag. Retry with the corrected PostgreSQL command compatibility path.' }
# FIX36B S8: only the server's own rejection (English text or SQLSTATE
# 28P01) is a password failure, whatever else the text mentions. Other login
# errors that mention a password (Ident, "no password supplied", localized text)
# are connection problems, never proof of a wrong password.
elseif (Test-PostgresPasswordRejectionText -Text $text) { $category = 'PasswordAuthenticationFailed'; $next = 'Enter a working postgres password, validate it with SELECT 1, save it securely, then retry.' }
elseif ($text -match '(?i)corrupt|corruption|malformed|inconsistent|invalid database') { $category = 'DatabaseCorrupt'; $next = 'Restore the affected database from a verified backup, then retry PostgreSQL setup.' }
elseif ($text -match 'not found|could not be verified|not recognized|cannot find path') { $category = 'ToolUnavailable'; $next = 'Install or repair the PostgreSQL client tools, then retry.' }
elseif ($text -match 'service|not running|stopped') { $category = 'ServiceNotRunning'; $next = 'Start the PostgreSQL service with administrator rights, then retry.' }
elseif ($text -match 'permission|access denied|administrator|elevation') { $category = 'PermissionOrElevation'; $next = 'Run TeknoParrot Manager as administrator or grant the PostgreSQL account access, then retry.' }
elseif ($text -match '(?i)\brole\b.*does not exist') { $category = 'CannotConnect'; $next = 'The PostgreSQL login user (role) does not exist on this server. Check the PostgreSQL installation and the user name in the game profile, then retry.' }
elseif ($text -match 'does not exist|database .* missing') { $category = 'DatabaseMissing'; $next = 'Verify the game database name and restore the database before retrying.' }
elseif ($text -match '(?i)authentication failed|no password supplied|password') { $category = 'CannotConnect'; $next = 'PostgreSQL did not accept the login, but it did not clearly say that the password is wrong. Check the PostgreSQL service and its pg_hba.conf entry for 127.0.0.1, then retry.' }
elseif ($text -match 'connect|connection|refused|server') { $category = 'CannotConnect'; $next = 'Verify the PostgreSQL service, host, port, and credentials, then retry.' }
    return [pscustomobject]@{ GameLabel=$GameLabel; ProfileKey=$ProfileKey; Database=$DbName; Category=$category; Detail=$text; NextAction=$next; ExitCode=$ExitCode }
}
# FIX50: a profile whose database name is missing or unsafe is a named, plain
# diagnosis, not an anonymous failure. The unsafe value is never echoed (it is
# not needed to fix the profile and could hold anything). A safe name whose
# database does not exist yet is NOT a problem: setup creates it.
function Get-PostgresDatabaseNameProblem {
    param([string]$DbName)
    if ([string]::IsNullOrWhiteSpace($DbName)) { return 'The database name is missing in the game profile.' }
    if (-not (Test-SafePostgresDbName $DbName)) { return 'The database name in the game profile contains characters that are not allowed (only letters, digits and underscore).' }
    return ''
}
function New-PostgresInvalidDatabaseNameDiagnosis {
    param([string]$GameLabel, [string]$ProfileKey = '', [Parameter(Mandatory)][string]$Problem)
    return [pscustomobject]@{
        GameLabel = $GameLabel; ProfileKey = $ProfileKey; Database = ''; Category = 'InvalidDatabaseName'; Detail = $Problem
        NextAction = 'Correct the database name in this game profile (letters, digits and underscore only), then retry. TeknoParrot Manager changes nothing until every game profile has a usable database name.'
        ExitCode = 0
    }
}
function Get-PostgresInvalidDatabaseNameReasonLines {
    param([object[]]$Diagnoses)
    return @($Diagnoses | Where-Object { $_ -and [string]$_.Category -ceq 'InvalidDatabaseName' } | ForEach-Object {
        # N18A: the profile name goes with the game title, so a profile whose title is unknown can still be found.
        if ([string]::IsNullOrWhiteSpace([string]$_.ProfileKey)) { '{0}: {1}' -f $_.GameLabel, $_.Detail } else { '{0} [{1}]: {2}' -f $_.GameLabel, $_.ProfileKey, $_.Detail }
    } | Sort-Object -Unique)
}
function Write-PostgresBackupFailureAffectedGames {
    param([object[]]$Diagnoses)
    Write-Host "  Affected games:" -ForegroundColor Yellow
    foreach ($label in @(Get-PostgresDiagnosisAffectedLabels -Diagnoses $Diagnoses)) {
        Write-Host ("    {0}" -f $label) -ForegroundColor Yellow
    }
    $databaseNameReasonLines = @(Get-PostgresInvalidDatabaseNameReasonLines -Diagnoses $Diagnoses)
    if ($databaseNameReasonLines.Count -gt 0) {
        Write-Host "  Game profiles with a database name problem:" -ForegroundColor Yellow
        foreach ($reasonLine in $databaseNameReasonLines) {
            Write-Host ("    {0}" -f $reasonLine) -ForegroundColor Yellow
        }
        Write-Host "  Correct the database name in each listed profile, then try again. Nothing was changed. Choose [D] to see which profile file each one is." -ForegroundColor Yellow
    }
}
function Get-TpmPostgresBackupFailureChoices {
    param([bool]$AuthFailure, [bool]$PasswordRejected, [bool]$EvidenceUnavailable)
    # While the safety copy of the profiles is unverified, only choices that do not change anything (or that rebuild from scratch) are allowed.
    $entries = @(
        @{ Key = 'P'; Show = ($AuthFailure -and -not $EvidenceUnavailable); Text = '[P] Enter and test a postgres password' }
        @{ Key = 'X'; Show = ($AuthFailure -and $PasswordRejected); Text = '[X] I do not know the password' }
        @{ Key = 'R'; Show = (-not $EvidenceUnavailable); Text = '[R] Check the problem and try the safety backup again' }
        @{ Key = 'I'; Show = $true; Text = '[I] Reinitialize PostgreSQL data for these games' }
        @{ Key = 'D'; Show = $true; Text = '[D] Show details' }
        @{ Key = 'O'; Show = $true; Text = '[O] Open logs/support guidance' }
        @{ Key = 'B'; Show = $true; Text = '[B] Back to main menu' }
    )
    $shown = @($entries | Where-Object { $_.Show })
    $default = if ($EvidenceUnavailable) { 'B' } else { 'R' }
    return [pscustomobject]@{
        Choices = @($shown | ForEach-Object { [string]$_.Key })
        Lines = @($shown | ForEach-Object { [string]$_.Text })
        Default = $default
        Prompt = ('  Choice, default {0}' -f $default)
        Notice = $(if ($EvidenceUnavailable) { 'TeknoParrot Manager could not make a checked safety copy of your game profiles, so it cannot try the backup again or test a password now. Close any program that may be using the profile files, then start this setup again.' } else { '' })
    }
}
function Get-PostgresDiagnosisAffectedPairs {
    param([object[]]$Diagnoses)
    return @($Diagnoses | ForEach-Object {
        $game = [string]$_.GameLabel
        if (-not [string]::IsNullOrWhiteSpace([string]$_.ProfileKey)) { $game = '{0} [{1}]' -f $game, $_.ProfileKey }
        $database = [string]$_.Database
        if ($game -and $database) { '{0} / {1}' -f $game, $database }
        elseif ($game) { $game } else { $database }
    } | Where-Object { $_ } | Sort-Object -Unique)
}
function Get-PostgresDiagnosisAffectedLabels {
    param([object[]]$Diagnoses)
    return @($Diagnoses | ForEach-Object { [string]$_.GameLabel } | Where-Object { $_ } | Sort-Object -Unique)
}
function ConvertTo-PostgresReinitializePlanJson {
    param([Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Plans)
    $ordered = @($Plans | ForEach-Object {
        [pscustomobject]@{
            GameLabel = [string]$_.GameLabel
            ProfileName = [string]$_.ProfileName
            Database = [string]$_.Database
            BackupFile = [string]$_.BackupFile
            Encoding = [string]$_.Encoding
        }
    } | Sort-Object GameLabel, ProfileName, Database)
    return ($ordered | ConvertTo-Json -Depth 4 -Compress)
}

function Get-PostgresReinitializePlanHash {
    param([Parameter(Mandatory)][string]$PlanJson)
    $bytes = [Text.Encoding]::UTF8.GetBytes($PlanJson)
    try {
        return ([Security.Cryptography.SHA256]::Create().ComputeHash($bytes) | ForEach-Object ToString x2) -join ''
    } finally {
        [Array]::Clear($bytes, 0, $bytes.Length)
    }
}

function Get-PostgresReinitializePlansFromProfiles {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [string[]]$OnlyDatabases = @())
    $plans = New-Object System.Collections.Generic.List[object]
    $profileFiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'PostgreSQL reinitialize profile discovery' -EnumerationErrorAction Stop | Sort-Object Name)
    $progressStarted = Get-Date
    $progressCurrent = 0
    $progressCurrentDone = $false
    try {
        foreach ($pf in $profileFiles) {
            $progressCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL reinitialize plan scan' -Current $progressCurrent -Total $profileFiles.Count -StartedAt $progressStarted
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile -or -not (Test-GameNeedsPostgres $doc)) { continue }
            $db = [string](Get-PostgresFieldValue $doc 'DbName')
            if ([string]::IsNullOrWhiteSpace($db) -or -not (Test-SafePostgresDbName $db)) { continue }
            if ($OnlyDatabases.Count -gt 0 -and $OnlyDatabases -notcontains $db) { continue }
            $metadata = Get-PostgresProfileDisplayMetadata -ProfilePath $pf.FullName
            $label = $metadata.DisplayName
            $gamePathNode = $doc.GameProfile.SelectSingleNode('GamePath')
            $gamePath = if ($gamePathNode) { [string]$gamePathNode.InnerText } else { '' }
            # FIX130 (S12) / N18B: a rebuild uses the same newest-file rule as setup, but never the alternate backups folder
            # (a rebuild replaces data, so it must not start from a file that is only a spare).
            $backupSelection = Get-PostgresBackupSelection -GamePath $gamePath
            $backupFile = [string]$backupSelection.Newest
            $encoding = Get-PostgresRestoreEncoding -DbName $db -BackupFile $backupFile
            $autoCreate = Get-PostgresAutoCreateCapability -Doc $doc
            [void]$plans.Add([pscustomobject]@{ GameLabel = $label; ProfileName = $metadata.ProfileKey; Database = $db; BackupFile = $backupFile; Encoding = $encoding; AutoCreate = $autoCreate; BackupCandidateCount = [int]$backupSelection.CandidateCount; BackupNewestHasTime = [bool]$backupSelection.NewestHasTime; BackupPathTooLong = [bool]$backupSelection.PathTooLong })
        }
        $progressCurrentDone = $true
    } finally {
        if ($profileFiles.Count -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL reinitialize plan scan' -Current $(if ($progressCurrentDone) { $progressCurrent } else { $progressCurrent - 1 }) -Total $profileFiles.Count -StartedAt $progressStarted -Complete -Outcome $(if ($progressCurrentDone) { 'Final' } else { 'Error' }) }
    }
    return @($plans | Sort-Object GameLabel, ProfileName, Database -Unique)
}

function Test-PostgresReinitializePlan {
    param(
        [Parameter(Mandatory)][string]$ExpectedPlanJson,
        [Parameter(Mandatory)][string]$ExpectedPlanHash,
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$CurrentPlans
    )
    if ([string]::IsNullOrWhiteSpace($ExpectedPlanJson) -or [string]::IsNullOrWhiteSpace($ExpectedPlanHash)) { return $false }
    $actualHash = Get-PostgresReinitializePlanHash -PlanJson $ExpectedPlanJson
    if ($actualHash -ne $ExpectedPlanHash) { return $false }
    $currentJson = ConvertTo-PostgresReinitializePlanJson -Plans $CurrentPlans
    return [string]::Equals($currentJson, $ExpectedPlanJson, [StringComparison]::Ordinal)
}
function Invoke-PostgresReinitializePlan {
    param(
        [Parameter(Mandatory)][string]$PlanJson,
        [Parameter(Mandatory)][string]$PlanHash,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][string]$SuperPasswordPlain,
        [Parameter(Mandatory)][AllowNull()][object]$RecoveryBackup
    )
    $planItems=@()
    $makeFailure = {
        param([string]$ReasonCode,[string]$Summary,[string]$Outcome='FAILED_BEFORE_MUTATION',[string]$ProductState='UNCHANGED',[bool]$FinalPassed=$true,[string[]]$Errors=@())
        return (New-TpmProfileTransactionResult -WorkflowKey 'PostgresRestore' -OperationKey 'ReinitializePlan' -Outcome $Outcome -ProductState $ProductState -Summary $Summary -Items $planItems -FailedItems $(if($planItems.Count -gt 0){$planItems}else{@('reinitialize-plan')}) -MutationStarted:($Outcome -ne 'FAILED_BEFORE_MUTATION') -Backup $RecoveryBackup -FinalPassed $FinalPassed -ReasonCode $ReasonCode -Errors $Errors -FinalChecks @('The selected PostgreSQL plan was validated before any database call.'))
    }
    if (-not $RecoveryBackup -or $RecoveryBackup.Verified -ne $true) { return (& $makeFailure 'RECOVERY_EVIDENCE_REQUIRED' 'The rebuild did not start because the safety copy could not be made. Nothing was changed.') }
    # The extra parentheses make Windows PowerShell 5.1 hand over one plan per database (5.1 otherwise returns the whole array as a single item).
    try { $plans = @(($PlanJson | ConvertFrom-Json)) } catch { return (& $makeFailure 'PLAN_INVALID' 'The rebuild did not start because the list of games could not be read. Nothing was changed.') }
    $planItems=@($plans | ForEach-Object { [string]$_.Database } | Sort-Object -Unique)
    # No verified single-source authority exists for destructive shared plans.
    # Keep every profile in the selection, but never reset its database twice.
    if ($planItems.Count -ne $plans.Count) { return (& $makeFailure 'SHARED_DATABASE_REINITIALIZE_UNVERIFIED' 'The rebuild did not start because several of the games share one database. Nothing was changed.') }
    if ($plans.Count -eq 0 -or -not (Test-PostgresReinitializePlan -ExpectedPlanJson $PlanJson -ExpectedPlanHash $PlanHash -CurrentPlans $plans)) { return (& $makeFailure 'PLAN_INVALID' 'The rebuild did not start because the list of games could not be checked. Nothing was changed.') }
    # Re-read only the selected databases, so an unrelated registered database cannot look like drift. Every profile sharing a selected database is still included.
    try {
        $current = @(Get-PostgresReinitializePlansFromProfiles -UserProfilesDir $UserProfilesDir -OnlyDatabases $planItems)
    } catch {
        Write-Log ('Postgres reinitialize: the game profiles could not be read before any database change: {0}' -f $_.Exception.Message)
        return (& $makeFailure 'PLAN_UNREADABLE' 'The rebuild did not start because your game profiles could not be read. Nothing was changed.')
    }
    if (-not (Test-PostgresReinitializePlan -ExpectedPlanJson $PlanJson -ExpectedPlanHash $PlanHash -CurrentPlans $current)) { return (& $makeFailure 'PLAN_CHANGED' 'The rebuild did not start because your games changed. Nothing was changed.') }
    # Check every rebuild input before the first database is touched, so a later bad input cannot strand earlier work.
    foreach ($plan in $plans) {
        $preflightBackupFile = [string]$plan.BackupFile
        if ([string]::IsNullOrWhiteSpace($preflightBackupFile) -or -not (Test-Path -LiteralPath $preflightBackupFile -PathType Leaf)) {
            return (& $makeFailure 'REBUILD_BACKUP_MISSING' 'The rebuild did not start because a game''s starting database file is missing. Nothing was changed.')
        }
        if ([string]::IsNullOrWhiteSpace([string]$plan.Encoding) -or -not (Test-SafePostgresDbName ([string]$plan.Database))) {
            return (& $makeFailure 'PLAN_INVALID' 'The rebuild did not start because the list of games could not be checked. Nothing was changed.')
        }
    }
    $results=New-Object System.Collections.Generic.List[object]
    $remaining=New-Object System.Collections.Generic.List[string]
    foreach ($plan in $plans) { [void]$remaining.Add([string]$plan.Database) }
    # Another TeknoParrot Manager window must not change PostgreSQL while this rebuild runs.
    if (-not [bool](Enter-PostgresRecoveryLock)) { return (& $makeFailure -ReasonCode 'POSTGRES_BUSY' -Summary 'The rebuild did not start because another TeknoParrot Manager window is changing PostgreSQL. Wait for it to finish, then try again. Nothing was changed.') }
    try {
    foreach ($plan in $plans) {
        # The nested reset checks its own rebuild source again, and its result is kept like any other result.
        $backupFile = [string]$plan.BackupFile
        try {
            $result = Reset-PostgresDatabaseFromBackup -DbName ([string]$plan.Database) -Encoding ([string]$plan.Encoding) -BackupFile $backupFile -SuperPasswordPlain $SuperPasswordPlain -RecoveryBackup $RecoveryBackup -Confirmed
        } catch {
            $redactedResetError = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
            Write-Log ("Postgres reinitialize: the reset of {0} stopped unexpectedly -- {1}" -f [string]$plan.Database, $redactedResetError)
            $result = [pscustomobject]@{ Outcome = 'ACTION_REQUIRED'; Items = @([string]$plan.Database) }
        }
        if ($result.PSObject.Properties.Name -notcontains 'Items') { $result | Add-Member -NotePropertyName Items -NotePropertyValue @([string]$plan.Database) -Force }
        [void]$results.Add($result)
        [void]$remaining.Remove([string]$plan.Database)
        $resultOutcome = if ($result.PSObject.Properties.Name -contains 'Outcome') { [string]$result.Outcome } else { 'ACTION_REQUIRED' }
        # A rebuild that finished (or was put back) but left a temporary folder behind is still a finished (or put-back) rebuild.
        $residueUnderlying = [string](Get-TpmTransactionField -Object $result -Name 'UnderlyingOutcome' -Default '')
        if ($resultOutcome -eq 'CLEANUP_RESIDUE' -and $residueUnderlying -in @('SUCCEEDED','ROLLED_BACK_VERIFIED')) { $resultOutcome = $residueUnderlying }
        $result | Add-Member -NotePropertyName NormalizedOutcome -NotePropertyValue $resultOutcome -Force
        if ($resultOutcome -ne 'SUCCEEDED') { break }
    }
    } finally { Exit-PostgresRecoveryLock }
    # The reason a database stopped is kept: it goes to the log and under Details, not away.
    $nestedErrors=@($results | ForEach-Object { @(Get-TpmTransactionField -Object $_ -Name 'Errors' -Default @()) } | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
    $residuePaths=@($results | ForEach-Object { @(Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $_ -Name 'Cleanup') -Name 'ResiduePaths' -Default @()) } | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
    $residueCleanup=if ($residuePaths.Count -gt 0) { [pscustomobject]@{ Attempted=$true; Completed=$false; ResiduePresent=$true; ResiduePaths=$residuePaths; ResidueItems=@(); Error='A temporary folder could not be removed.' } } else { $null }
    $changed=@($results | Where-Object { $_.NormalizedOutcome -eq 'SUCCEEDED' } | ForEach-Object Items)
    $completed=$changed
    $rolledBack=@($results | Where-Object { $_.NormalizedOutcome -eq 'ROLLED_BACK_VERIFIED' } | ForEach-Object Items)
    $failed=@($results | Where-Object { $_.NormalizedOutcome -ne 'SUCCEEDED' } | ForEach-Object Items) + @($remaining)
    if ($results.Count -eq $plans.Count -and $failed.Count -eq 0) {
        # FIX110 (S-7): the known limitations that a rebuild accepted stay in the aggregate result and its details.
        $limitationWarnings = @($results | ForEach-Object { @($_.Warnings) } | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
        $keptDatabaseBackups = @($results | ForEach-Object { [string](Get-TpmTransactionField -Object $_ -Name 'DatabaseBackup' -Default '') } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) -and (Test-Path -LiteralPath $_ -PathType Leaf) })
        $limitationDetails = [pscustomobject]@{ AcceptedRestoreLimitations = @($results | ForEach-Object { @((Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $_ -Name 'TechnicalDetails') -Name 'AcceptedRestoreLimitations' -Default @())) }); KeptDatabaseBackups = $keptDatabaseBackups }
        return (New-TpmProfileTransactionResult -WorkflowKey 'PostgresRestore' -OperationKey 'ReinitializePlan' -Outcome 'SUCCEEDED' -ProductState 'INTENDED' -Summary 'PostgreSQL reinitialize completed and was verified for the selected games.' -Items $planItems -ChangedItems $changed -CompletedItems $completed -MutationStarted $true -MutationCompleted $true -Backup $RecoveryBackup -Cleanup $residueCleanup -FinalChecks @('Every selected database returned a verified transaction result.') -ReasonCode 'REINITIALIZED' -TechnicalDetails $limitationDetails -Warnings $limitationWarnings)
    }
    $attention=@($results | Where-Object { $_.NormalizedOutcome -notin @('SUCCEEDED','ROLLED_BACK_VERIFIED','FAILED_BEFORE_MUTATION') })
    if ($attention.Count -gt 0) {
        return (New-TpmProfileTransactionResult -WorkflowKey 'PostgresRestore' -OperationKey 'ReinitializePlan' -Outcome 'ACTION_REQUIRED' -ProductState 'UNKNOWN' -Summary 'The rebuild did not finish, and TeknoParrot Manager could not check that your data is back as it was. Ask for help before you try again.' -Items $planItems -ChangedItems $changed -FailedItems $failed -MutationStarted $true -Backup $RecoveryBackup -FinalPassed $false -ReasonCode 'DATABASE_STATE_UNVERIFIED' -Errors $nestedErrors -FinalChecks @('Every completed database retained its nested transaction evidence.'))
    }
    $rollbackEvidence=if ($rolledBack.Count -gt 0) { [pscustomobject]@{ Attempted=$true; Completed=$true; Verified=$true; Items=$rolledBack; EvidenceRoot=$null; FailedItems=@(); Errors=@() } } else { $null }
    if ($changed.Count -gt 0) {
        return (New-TpmProfileTransactionResult -WorkflowKey 'PostgresRestore' -OperationKey 'ReinitializePlan' -Outcome 'PARTIAL_APPLIED' -ProductState 'PARTIAL_KNOWN' -Summary 'The rebuild worked for some of the games but not for all of them.' -Items $planItems -ChangedItems $changed -CompletedItems $completed -FailedItems $failed -MutationStarted $true -Backup $RecoveryBackup -Rollback $rollbackEvidence -Errors $nestedErrors -FinalChecks @('The aggregate result records completed, rolled-back and unattempted database items.'))
    }
    if ($rolledBack.Count -gt 0) {
        return (New-TpmProfileTransactionResult -WorkflowKey 'PostgresRestore' -OperationKey 'ReinitializePlan' -Outcome 'ROLLED_BACK_VERIFIED' -ProductState 'UNCHANGED' -Summary 'The rebuild did not finish. Your old data was put back and checked.' -Items $planItems -ChangedItems $rolledBack -FailedItems $failed -MutationStarted $true -Backup $RecoveryBackup -Rollback $rollbackEvidence -Errors $nestedErrors -FinalChecks @('The rebuilt database was restored to its captured state; the remaining databases were not attempted.') -ReasonCode 'REINITIALIZE_ROLLED_BACK')
    }
    return (& $makeFailure -ReasonCode 'DATABASE_REINITIALIZE_FAILED' -Summary 'The rebuild did not start. Nothing was changed.' -Errors $nestedErrors)
}
# B2: a successful restore or reinitialize keeps the saved copy of the data it replaced. Say so in plain words and show where it is.
function Write-PostgresKeptDatabaseBackupNotice {
    param([AllowNull()][object[]]$Paths = @())
    $folders = @(@($Paths) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [System.IO.Path]::GetDirectoryName([string]$_) } | Select-Object -Unique)
    if ($folders.Count -eq 0) { return }
    Write-Host '  Your old data was saved first, and TeknoParrot Manager has kept that saved copy. It does not delete it.' -ForegroundColor Green
    foreach ($folder in $folders) { Write-Host ('    Saved copy folder: {0}' -f $folder) -ForegroundColor DarkGray }
    Write-Host '  You can delete that folder yourself once you are sure you do not need your old data.' -ForegroundColor DarkGray
}
# FIX126: the Details view of a rebuild that skipped known harmless warnings. The technical notes (what was skipped, the
# constraint names) are shown here and are always in the log; the main screen only says it in plain words.
function Write-PostgresReinitializeDetails {
    param([AllowNull()][object]$Result)
    $blocks = New-Object System.Collections.Generic.List[object]
    $summary = [string](Get-TpmTransactionField -Object $Result -Name 'Summary' -Default '')
    if (-not [string]::IsNullOrWhiteSpace($summary)) { [void]$blocks.Add(@{ Heading = 'Summary'; Lines = @($summary) }) }
    $records = @(@(Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'TechnicalDetails') -Name 'AcceptedRestoreLimitations' -Default @()) | Where-Object { $null -ne $_ })
    foreach ($record in $records) {
        $lines = New-Object System.Collections.Generic.List[string]
        Add-TpmDetailLine -Lines $lines -Label 'What was skipped' -Text ([string](Get-TpmTransactionField -Object $record -Name 'Message' -Default ''))
        $names = @(@(Get-TpmTransactionField -Object $record -Name 'ConstraintNames' -Default @()) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
        if ($names.Count -gt 0) { Add-TpmDetailLine -Lines $lines -Label 'Names' -Text ($names -join ', ') }
        [void]$blocks.Add(@{ Heading = [string](Get-TpmTransactionField -Object $record -Name 'Database' -Default 'Game backup'); Lines = $lines.ToArray(); Color = 'Yellow' })
    }
    if ($records.Count -eq 0) {
        $notes = @(@(Get-TpmTransactionField -Object $Result -Name 'Warnings' -Default @()) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
        if ($notes.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'What was skipped'; Lines = $notes; Color = 'Yellow' }) }
    }
    $leftover = @(@(Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'Cleanup') -Name 'ResiduePaths' -Default @()) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
    if ($leftover.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Temporary folder that could not be removed'; Lines = $leftover; Color = 'Yellow' }) }
    Write-Host ''
    Write-TpmText -Text 'Details' -Color Cyan -Indent 2 -MaxWidth 0
    Show-TpmDetailBlocks -Blocks $blocks.ToArray()
}
# FIX126: the success screen of a rebuild. Known harmless warnings from the game's own backup are said in plain words here. The
# technical notes are in the Details view (key D, only when OfferDetails is set) and always in the log.
function Write-PostgresReinitializeSuccess {
    param([AllowNull()][object]$Result, [switch]$OfferDetails)
    $notes = @(@(Get-TpmTransactionField -Object $Result -Name 'Warnings' -Default @()) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    Write-Host '  PostgreSQL data was rebuilt and checked for the selected games.' -ForegroundColor Green
    $leftover = @(@(Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'Cleanup') -Name 'ResiduePaths' -Default @()) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
    if ($leftover.Count -gt 0) {
        foreach ($leftoverPath in $leftover) { Write-Log ('Postgres reinitialize: the rebuild finished, but a temporary folder could not be removed: {0}' -f $leftoverPath) }
        Write-Host '  The rebuild finished and was checked, but TeknoParrot Manager could not remove a temporary folder it made. You can delete that folder yourself.' -ForegroundColor Yellow
    }
    if ($notes.Count -gt 0) {
        foreach ($note in $notes) { Write-Log ('Postgres reinitialize: finished with a known limitation: {0}' -f $note) }
        foreach ($record in @(@(Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'TechnicalDetails') -Name 'AcceptedRestoreLimitations' -Default @()) | Where-Object { $null -ne $_ })) {
            Write-Log ('Postgres reinitialize: accepted a known limitation for database {0} (constraints: {1})' -f [string](Get-TpmTransactionField -Object $record -Name 'Database' -Default ''), (@(Get-TpmTransactionField -Object $record -Name 'ConstraintNames' -Default @()) -join ', '))
        }
        Write-Host '  A few harmless warnings from the game''s own backup were skipped.' -ForegroundColor Yellow
    }
    Write-PostgresKeptDatabaseBackupNotice -Paths @(Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'TechnicalDetails') -Name 'KeptDatabaseBackups' -Default @())
    if ($notes.Count -gt 0 -or $leftover.Count -gt 0) {
        if ($OfferDetails) {
            $detailsAnswer = [string](Read-HostSafe '  Press D to see more, or Enter to continue')
            if ($detailsAnswer.Trim().ToUpperInvariant() -eq 'D') { Write-PostgresReinitializeDetails -Result $Result }
        } else {
            Write-Host '  The log has more.' -ForegroundColor DarkGray
        }
    }
}
# FIX128: the screen of a rebuild ("reinitialize") that did not finish. The main screen says in plain words what happened to the
# data. The result, the reason code and the notes are under Details (key D, only when OfferDetails is set) and always in the log.
# A rebuild that stopped before it changed anything is not called "blocked", and a rebuild that was put back is not called a
# failure of the data. The protected resume window cannot prompt, so it offers no D and points to the log.
function Write-PostgresReinitializeFailure {
    param([Parameter(Mandatory)]$Result, [string]$SuperPasswordPlain = '', [switch]$OfferDetails)
    $secrets = @($SuperPasswordPlain)
    $outcome = [string](Get-TpmTransactionField -Object $Result -Name 'Outcome' -Default '')
    $reasonCode = [string](Get-TpmTransactionField -Object $Result -Name 'ReasonCode' -Default '')
    $summary = ConvertTo-PostgresRedactedText -Text ([string](Get-TpmTransactionField -Object $Result -Name 'Summary' -Default '')) -Secrets $secrets
    $errorLines = @(@(Get-TpmTransactionField -Object $Result -Name 'Errors' -Default @()) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { ConvertTo-PostgresRedactedText -Text ([string]$_) -Secrets $secrets })
    Write-Log ('Postgres reinitialize: did not finish; outcome={0}; reason={1}; summary={2}' -f $outcome, $reasonCode, $summary)
    foreach ($errorLine in $errorLines) { Write-Log ('Postgres reinitialize: reason: {0}' -f $errorLine) }
    if ($outcome -eq 'FAILED_BEFORE_MUTATION' -and -not [string]::IsNullOrWhiteSpace($summary)) {
        Write-Host ('  ' + $summary) -ForegroundColor Yellow
    } else {
        $headline = if ($outcome -eq 'PARTIAL_APPLIED') { 'The rebuild worked for some of the games but not for all of them.' } else { 'The rebuild did not finish.' }
        $color = if ($outcome -eq 'ROLLED_BACK_VERIFIED') { 'Yellow' } else { 'Red' }
        Write-Host ('  ' + $headline) -ForegroundColor $color
        Write-Host ('  ' + (Get-TpmPostgresDataSafetyText -Result $Result)) -ForegroundColor $color
    }
    if (-not $OfferDetails) {
        Write-Host '  The log has more.' -ForegroundColor DarkGray
        return
    }
    $answer = [string](Read-HostSafe '  Press D for details, or Enter to continue')
    if ($answer.Trim().ToUpperInvariant() -ne 'D') { return }
    $blocks = New-Object System.Collections.Generic.List[object]
    $resultLines = New-Object System.Collections.Generic.List[string]
    Add-TpmDetailLine -Lines $resultLines -Label 'Result' -Text $summary
    Add-TpmDetailLine -Lines $resultLines -Label 'Outcome' -Text $outcome
    Add-TpmDetailLine -Lines $resultLines -Label 'Reason code' -Text $reasonCode
    [void]$blocks.Add(@{ Heading = 'What happened'; Lines = $resultLines.ToArray() })
    if ($errorLines.Count -gt 0) {
        $why = New-Object System.Collections.Generic.List[string]
        foreach ($errorLine in $errorLines) { foreach ($piece in @($errorLine -split '\r?\n')) { if (-not [string]::IsNullOrWhiteSpace($piece)) { [void]$why.Add($piece.Trim()) } } }
        [void]$blocks.Add(@{ Heading = 'Why it stopped'; Lines = $why.ToArray(); Color = 'Yellow' })
    }
    Write-Host ''
    Write-TpmText -Text 'Details' -Color Cyan -Indent 2 -MaxWidth 0
    Show-TpmDetailBlocks -Blocks $blocks.ToArray()
}
function Invoke-PostgresReinitializeChoice {
    param(
        [Parameter(Mandatory)][object[]]$FailureDiagnoses,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][string]$ConfigPath,
        [Parameter(Mandatory)][string]$ScriptPath,
        [Parameter(Mandatory)][string]$TpRoot,
        [Parameter(Mandatory)][string]$SuperPasswordPlain,
        [Parameter(Mandatory)][AllowNull()][object]$RecoveryBackup
    )
    $affectedDbNames = @($FailureDiagnoses | ForEach-Object { [string]$_.Database } | Where-Object { $_ -and (Test-SafePostgresDbName $_) } | Sort-Object -Unique)
    if ($affectedDbNames.Count -eq 0) {
        # FIX50: an empty selection must never fall through to "every database" in plan discovery.
        Write-Host ''
        Write-Host '  TeknoParrot Manager could not tell exactly which games and databases to rebuild. Nothing was changed.' -ForegroundColor Red
        return [pscustomobject]@{ Outcome = 'Blocked'; Plans = @() }
    }
    try {
        $plans = @(Get-PostgresReinitializePlansFromProfiles -UserProfilesDir $UserProfilesDir -OnlyDatabases $affectedDbNames)
    } catch {
        # Plan discovery is read-only and runs before any database change; report Blocked, never Completed.
        Write-Log ('Postgres reinitialize: profile discovery failed before any change: {0}' -f $_.Exception.Message)
        Write-Host '  PostgreSQL rebuild stopped: TeknoParrot Manager could not read your game profiles. Nothing was changed. The log has the reason.' -ForegroundColor Red
        return [pscustomobject]@{ Outcome = 'Blocked'; Plans = @(); PlanJson = ''; PlanHash = ''; Error = 'PROFILE_DISCOVERY_FAILED' }
    }
    Write-Host ''
    Write-Host '  Reinitialize PostgreSQL data for these affected games:' -ForegroundColor Yellow
    foreach ($plan in $plans) {
        Write-Log ('Postgres reinitialize: plan {0} [{1}] / {2}' -f $plan.GameLabel, $plan.ProfileName, $plan.Database)
        Write-Host ("    {0}" -f $plan.GameLabel) -ForegroundColor Yellow
        # FIX130 (S12): the confirm screen names the file the rebuild will use (the file name only; the full path is in the log).
        if (-not [string]::IsNullOrWhiteSpace([string]$plan.BackupFile)) {
            Write-Host ("      It will use this file that came with the game: {0}" -f [System.IO.Path]::GetFileName([string]$plan.BackupFile)) -ForegroundColor Yellow
            if ([int]$plan.BackupCandidateCount -gt 1) {
                Write-Host $(if ($plan.BackupNewestHasTime) { ("      The game came with {0} such files; this is the newest one." -f [int]$plan.BackupCandidateCount) } else { ("      The game came with {0} such files and their names do not say which is newest; this one was picked by name." -f [int]$plan.BackupCandidateCount) }) -ForegroundColor Yellow
            }
            Write-Log ('Postgres reinitialize: {0} [{1}] / {2} would be rebuilt from {3}' -f $plan.GameLabel, $plan.ProfileName, $plan.Database, [string]$plan.BackupFile)
        }
    }
    if ($plans.Count -eq 0) {
        Write-Host '  TeknoParrot Manager could not tell exactly which games and databases to rebuild. Nothing was changed.' -ForegroundColor Red
        return [pscustomobject]@{ Outcome = 'Blocked'; Plans = @() }
    }
    if (@($plans | Group-Object -Property Database | Where-Object { $_.Count -gt 1 }).Count -gt 0) {
        Write-Host '  These games share one database, so TeknoParrot Manager cannot rebuild it safely. Nothing was changed.' -ForegroundColor Yellow
        return [pscustomobject]@{ Outcome = 'Blocked'; Plans = $plans; PlanJson = ''; PlanHash = ''; Error = 'SHARED_DATABASE_REINITIALIZE_UNVERIFIED' }
    }
    # A game without a bundled starting database cannot be reinitialized by TeknoParrot Manager. Say so before asking
    # for YES, and for a game whose profile says TeknoParrot creates its database, say that TeknoParrot owns that step.
    $noStartingDatabase = @($plans | Where-Object { [string]::IsNullOrWhiteSpace([string]$_.BackupFile) -or -not (Test-Path -LiteralPath ([string]$_.BackupFile) -PathType Leaf) })
    if ($noStartingDatabase.Count -gt 0) {
        foreach ($plan in $noStartingDatabase) {
            Write-Log ('Postgres reinitialize: no pg_backup file was found for {0} [{1}] / {2}.' -f $plan.GameLabel, $plan.ProfileName, $plan.Database)
            $pathTooLongProperty = $plan.PSObject.Properties['BackupPathTooLong']
            if ($pathTooLongProperty -and $pathTooLongProperty.Value -eq $true) {
                Write-Host ("  {0}: the game is in a folder path longer than 259 characters, so TeknoParrot Manager cannot read its starting database. Move the game to a shorter folder path, then try again." -f $plan.GameLabel) -ForegroundColor Yellow
            } else {
                Write-Host ("  {0}: no starting database was found with the game, so TeknoParrot Manager cannot rebuild it." -f $plan.GameLabel) -ForegroundColor Yellow
            }
            $autoCreateProperty = $plan.PSObject.Properties['AutoCreate']
            if ($autoCreateProperty -and $autoCreateProperty.Value -eq $true) {
                Write-Host '    This game''s profile tells TeknoParrot to create its database itself when it is missing, and TeknoParrot Manager does not replace that. If the saved data is damaged, restore a saved backup instead.' -ForegroundColor DarkGray
            }
        }
        Write-Host '  Nothing was changed.' -ForegroundColor Yellow
        return [pscustomobject]@{ Outcome = 'Blocked'; Plans = $plans; PlanJson = ''; PlanHash = ''; Error = 'REBUILD_BACKUP_MISSING' }
    }
    $planJson = ConvertTo-PostgresReinitializePlanJson -Plans $plans
    $planHash = Get-PostgresReinitializePlanHash -PlanJson $planJson
    # FIX36B N6: say plainly that current data is replaced, as the restore menu does.
    Write-Host '  WARNING: this REPLACES the current data in every database listed above with the game''s own starting database.' -ForegroundColor Yellow
    Write-Host '  TeknoParrot Manager first saves and checks a copy of the current data. If that copy fails, that database is not changed. After a good reinitialize it keeps that saved copy and does not delete it.' -ForegroundColor Yellow
    $confirm = (Read-HostSafe '  Type YES in all caps to confirm. Anything else cancels.').Trim()
    if ($confirm -cne 'YES') {
        Write-Host '  Reinitialize canceled because YES was not typed exactly. Nothing was changed.' -ForegroundColor DarkGray
        return [pscustomobject]@{ Outcome = 'Cancelled'; Plans = $plans; PlanJson = $planJson; PlanHash = $planHash }
    }
    if (-not $RecoveryBackup -or $RecoveryBackup.Verified -ne $true) {
        Write-Host '  The safety copy could not be made, so nothing was rebuilt. Nothing was changed.' -ForegroundColor Red
        return [pscustomobject]@{ Outcome = 'Blocked'; Plans = $plans; PlanJson = $planJson; PlanHash = $planHash }
    }
    if (-not (Test-RunningAsAdministrator)) {
        $handoffReport = $null
        Write-PostgresAdministratorGuidance -Operation Recovery
        $elevated = Start-PostgresRecoveryAsAdministrator -ConfigPath $ConfigPath -ScriptPath $ScriptPath -TpRoot $TpRoot `
            -UserProfilesDir $UserProfilesDir -Operation Reinitialize -PasswordPlain $SuperPasswordPlain `
            -SelectionPlanJson $planJson -SelectionPlanHash $planHash -HandoffReport ([ref]$handoffReport)
        # FIX39: Stopped means the administrator window reported its result and it was shown; setup returns to the main menu.
        $handoffOutcome = if ($elevated) { 'Elevated' } elseif ($handoffReport) { 'Stopped' } else { 'Blocked' }
        return [pscustomobject]@{ Outcome = $handoffOutcome; Plans = $plans; PlanJson = $planJson; PlanHash = $planHash }
    }
    $reinitResult = $null
    try {
        $reinitResult = Invoke-TpmProgressGroup -Title 'PostgreSQL reinitialize' -Action { Invoke-PostgresReinitializePlan -PlanJson $planJson -PlanHash $planHash -UserProfilesDir $UserProfilesDir -SuperPasswordPlain $SuperPasswordPlain -RecoveryBackup $RecoveryBackup }
    } catch {
        # The rebuild itself stopped in an unexpected way. It may have changed data, so the screen does not say that nothing changed.
        $safeError = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
        Write-Host '  The rebuild stopped in an unexpected way. Some of your data may have been changed. Open View Log, and ask for help before you try again.' -ForegroundColor Red
        Write-Log ('Postgres reinitialize: stopped unexpectedly (the password is not logged): {0}' -f $safeError)
        return [pscustomobject]@{ Outcome = 'Blocked'; Plans = $plans; PlanJson = $planJson; PlanHash = $planHash; Error = $safeError; DatabaseMayHaveChanged = $true }
    }
    if ([string]$reinitResult.Outcome -ne 'SUCCEEDED' -and -not ([string]$reinitResult.Outcome -eq 'CLEANUP_RESIDUE' -and [string]$reinitResult.UnderlyingOutcome -eq 'SUCCEEDED')) {
        $safeSummary = ConvertTo-PostgresRedactedText -Text ([string]$reinitResult.Summary) -Secrets @($SuperPasswordPlain)
        Write-PostgresReinitializeFailure -Result $reinitResult -SuperPasswordPlain $SuperPasswordPlain -OfferDetails
        Write-Log 'Postgres reinitialize: failure was reported without logging the password.'
        return [pscustomobject]@{ Outcome = 'Blocked'; Plans = $plans; PlanJson = $planJson; PlanHash = $planHash; Error = $safeSummary; DatabaseMayHaveChanged = ([string]$reinitResult.Outcome -ne 'FAILED_BEFORE_MUTATION') }
    }
    Write-PostgresReinitializeSuccess -Result $reinitResult -OfferDetails
    return [pscustomobject]@{ Outcome = 'Completed'; Plans = $plans; PlanJson = $planJson; PlanHash = $planHash; TransactionResult=$reinitResult }
}



# FIX129 (S1, S2): pure readers for what the psql catalog queries print on STANDARD OUTPUT. Invoke-PostgresNativeCommand hands
# them the RAW text in memory (-Interpret); the redacted text is only for logs and screens. Before FIX129 these checks parsed the
# redacted, merged stdout+stderr text: a short password such as "1" or "db" rewrote the answer, and any stray stderr line from
# psql made an existing database read as absent.
function Get-PostgresStdoutLines {
    param([AllowNull()][AllowEmptyString()][string]$StdOut)
    return @(([string]$StdOut -split '\r?\n') | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' })
}

# No row = absent, exactly the one row "1" = present, anything else is NOT recognized (never read as absent).
function Get-PostgresExistenceProbeResult {
    param([AllowNull()][AllowEmptyString()][string]$StdOut)
    $lines = @(Get-PostgresStdoutLines -StdOut $StdOut)
    if ($lines.Count -eq 0) { return [pscustomobject]@{ Recognized = $true; Exists = $false } }
    if ($lines.Count -eq 1 -and $lines[0] -ceq '1') { return [pscustomobject]@{ Recognized = $true; Exists = $true } }
    return [pscustomobject]@{ Recognized = $false; Exists = $false }
}

function Get-PostgresEncodingProbeResult {
    param([AllowNull()][AllowEmptyString()][string]$StdOut)
    $lines = @(Get-PostgresStdoutLines -StdOut $StdOut)
    $encoding = $null
    if ($lines.Count -eq 1 -and $lines[0] -cmatch '\A[A-Z][A-Z0-9_]*\z') { $encoding = [string]$lines[0] }
    return [pscustomobject]@{ Encoding = $encoding }
}

function Get-PostgresCaseVariantProbeResult {
    param([AllowNull()][AllowEmptyString()][string]$StdOut, [Parameter(Mandatory)][string]$DbName)
    $variants = @(Get-PostgresStdoutLines -StdOut $StdOut | Where-Object { $_ -ieq $DbName -and $_ -cne $DbName })
    return [pscustomobject]@{ Variants = $variants }
}

function Get-PostgresDatabaseState {
    param([Parameter(Mandatory)][string]$DbName, [Parameter(Mandatory)][string]$SuperPasswordPlain)
    if (-not (Test-SafePostgresDbName $DbName)) { throw 'Postgres: unsafe database name.' }
    $psqlExe = Join-Path $script:PostgresBinDir 'psql.exe'
    if (-not (Test-Path -LiteralPath $psqlExe -PathType Leaf)) { throw 'Postgres: psql.exe could not be verified.' }
    # The answer is judged from the raw standard output in memory (-Interpret); only the redacted text is shown or logged.
    $existenceInterpreter = { param($Raw) Get-PostgresExistenceProbeResult -StdOut ([string]$Raw.StdOut) }
    $queryResult = Invoke-PostgresNativeCommand -FilePath $psqlExe -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-d','postgres','-tAc',("SELECT 1 FROM pg_database WHERE datname='{0}'" -f $DbName)) -Secrets @($SuperPasswordPlain) -PasswordPlain $SuperPasswordPlain -Interpret $existenceInterpreter
    $queryOutput = [string]$queryResult.Output
    $queryExitCode = [int]$queryResult.ExitCode
    if ($queryExitCode -ne 0) {
        $detail = if ($queryOutput) { ConvertTo-PostgresRedactedText -Text $queryOutput -Secrets @($SuperPasswordPlain) } else { 'psql returned no diagnostic text.' }
        throw ("Postgres: database existence query failed (exit code {0}). Detail: {1}" -f $queryExitCode, $detail)
    }
    $existence = Get-TpmTransactionField -Object $queryResult -Name 'Interpretation' -Default $null
    if ($null -eq $existence -or -not [bool]$existence.Recognized) {
        throw 'Postgres: the database existence query answered with text that could not be read, so the database was not treated as absent.'
    }
    $exists = [bool]$existence.Exists
    $encoding = $null
    if ($exists) {
        # The database's own encoding, so a rollback can recreate it the way it was. Unreadable stays $null and is never guessed here.
        $encodingInterpreter = { param($Raw) Get-PostgresEncodingProbeResult -StdOut ([string]$Raw.StdOut) }
        $encodingResult = Invoke-PostgresNativeCommand -FilePath $psqlExe -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-d','postgres','-tAc',("SELECT pg_encoding_to_char(encoding) FROM pg_database WHERE datname='{0}'" -f $DbName)) -Secrets @($SuperPasswordPlain) -PasswordPlain $SuperPasswordPlain -Interpret $encodingInterpreter
        if ([int]$encodingResult.ExitCode -eq 0) {
            $encodingProbe = Get-TpmTransactionField -Object $encodingResult -Name 'Interpretation' -Default $null
            if ($null -ne $encodingProbe -and $null -ne $encodingProbe.Encoding) { $encoding = [string]$encodingProbe.Encoding }
        }
    }
    return [pscustomobject]@{ Exists = $exists; Verified = $true; Encoding = $encoding }
}

# FIX44: PostgreSQL database names are case-sensitive, but TeknoParrot Manager
# never creates a database whose name differs only by case from an existing one.
# Returns Verified=$false when the catalog query fails; callers fail closed.
function Get-PostgresDatabaseCaseVariantState {
    param([Parameter(Mandatory)][string]$DbName, [Parameter(Mandatory)][string]$SuperPasswordPlain)
    if (-not (Test-SafePostgresDbName $DbName)) { throw 'Postgres: unsafe database name.' }
    $query = ("SELECT datname FROM pg_database WHERE lower(datname)=lower('{0}')" -f $DbName)
    $variantInterpreter = { param($Raw, $Context) Get-PostgresCaseVariantProbeResult -StdOut ([string]$Raw.StdOut) -DbName ([string]$Context) }
    $command = Invoke-Postgres83RestoreCommand -ToolName 'psql.exe' -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-d','postgres','-tAc',$query) -SuperPasswordPlain $SuperPasswordPlain -Interpret $variantInterpreter -InterpretContext $DbName
    if (-not $command.Succeeded) {
        return [pscustomobject]@{ Verified = $false; Variants = @(); Error = ConvertTo-PostgresRedactedText -Text ([string]$command.Output) -Secrets @($SuperPasswordPlain) }
    }
    $variantProbe = Get-TpmTransactionField -Object $command -Name 'Interpretation' -Default $null
    if ($null -eq $variantProbe) {
        return [pscustomobject]@{ Verified = $false; Variants = @(); Error = 'The database names could not be read from the psql answer.' }
    }
    # The names were compared in memory on the raw text; the list that is kept is redacted.
    $variants = @(@($variantProbe.Variants) | ForEach-Object { ConvertTo-PostgresRedactedText -Text ([string]$_) -Secrets @($SuperPasswordPlain) })
    return [pscustomobject]@{ Verified = $true; Variants = @($variants); Error = $null }
}

# Server-side password rejection as printed by psql (FIX36 B1). Only the
# server's English message or SQLSTATE 28P01 counts. Localized, Ident,
# "no pg_hba.conf entry", connection and client-side "no password supplied"
# messages do not match, so they stay 'Unavailable' (never proof of a wrong
# password).
function Test-PostgresPasswordRejectionText {
    param([string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text)) { return $false }
    return [bool](($Text -match '(?i)password authentication failed for user') -or ($Text -cmatch '\b28P01\b'))
}

function Get-PostgresServiceStatusText {
    try {
        $service = Get-Service -Name $script:PostgresServiceName -ErrorAction Stop
        return [string]$service.Status
    } catch {
        return ''
    }
}

# Three-state PostgreSQL password probe (FIX36 B1, owner rule R2).
#   Authenticated - psql logged in with this password.
#   Rejected      - the Windows service is verified Running AND psql printed a
#                   server-side password rejection (see the text test above).
#   Unavailable   - everything else: client missing, service stopped or still
#                   starting, connection refused, no pg_hba.conf entry,
#                   unrecognized or localized message.
# A failed probe is never proof of a wrong password: callers must not offer a
# password reset unless State is 'Rejected'. Detail is psql output with the
# password already redacted by Invoke-PostgresNativeCommand.
function Get-PostgresPasswordProbe {
    param([Parameter(Mandatory)][string]$SuperPasswordPlain)
    $psqlExe = Join-Path $script:PostgresBinDir 'psql.exe'
    if (-not (Test-Path -LiteralPath $psqlExe -PathType Leaf)) {
        return [pscustomobject]@{ State = 'Unavailable'; Reason = 'ClientMissing'; ServiceStatus = (Get-PostgresServiceStatusText); Detail = 'psql.exe was not found.' }
    }
    # The rejection text is judged on the raw output in memory (-Interpret); a short password must not change the verdict.
    $rejectionInterpreter = { param($Raw) [pscustomobject]@{ Rejected = [bool](Test-PostgresPasswordRejectionText -Text ([string]$Raw.Output)) } }
    $probe = Invoke-PostgresNativeCommand -FilePath $psqlExe -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-d','postgres','-tAc','SELECT 1') -Secrets @($SuperPasswordPlain) -PasswordPlain $SuperPasswordPlain -Interpret $rejectionInterpreter
    if ($null -ne $probe -and $null -ne $probe.ExitCode -and [int]$probe.ExitCode -eq 0) {
        return [pscustomobject]@{ State = 'Authenticated'; Reason = 'LoginSucceeded'; ServiceStatus = $null; Detail = '' }
    }
    $detail = [string]$probe.Output
    $serviceStatus = Get-PostgresServiceStatusText
    if ($serviceStatus -ne 'Running') {
        return [pscustomobject]@{ State = 'Unavailable'; Reason = 'ServiceNotRunning'; ServiceStatus = $serviceStatus; Detail = $detail }
    }
    $verdict = Get-TpmTransactionField -Object $probe -Name 'Interpretation' -Default $null
    if ($null -ne $verdict -and [bool]$verdict.Rejected) {
        return [pscustomobject]@{ State = 'Rejected'; Reason = 'PasswordRejected'; ServiceStatus = $serviceStatus; Detail = $detail }
    }
    return [pscustomobject]@{ State = 'Unavailable'; Reason = 'NotRecognized'; ServiceStatus = $serviceStatus; Detail = $detail }
}

# Boolean gate kept for callers that only need "does this password log in
# right now" and fail closed otherwise (restore preflight, reset validation).
# It is $true only for 'Authenticated'.
function Test-PostgresPassword {
    param([Parameter(Mandatory)][string]$SuperPasswordPlain)
    return ((Get-PostgresPasswordProbe -SuperPasswordPlain $SuperPasswordPlain).State -eq 'Authenticated')
}

# Runs the probe for an interactive decision. A probe that throws (for
# example psql could not be started) is reported as 'Unavailable' so it can
# never be mistaken for a rejected password.
function Invoke-PostgresPasswordProbeSafely {
    param([Parameter(Mandatory)][string]$SuperPasswordPlain)
    try {
        return (Get-PostgresPasswordProbe -SuperPasswordPlain $SuperPasswordPlain)
    } catch {
        Write-Log 'Postgres password check: the check itself failed; treated as unavailable (no password decision was made).'
        return [pscustomobject]@{ State = 'Unavailable'; Reason = 'ProbeError'; ServiceStatus = (Get-PostgresServiceStatusText); Detail = '' }
    }
}

# Plain-language reason for a probe that did not authenticate.
function Get-PostgresProbeExplanation {
    param([Parameter(Mandatory)]$Probe)
    switch ([string]$Probe.Reason) {
        'PasswordRejected' { return 'PostgreSQL is running and it rejected the password.' }
        'ServiceNotRunning' {
            $statusText = if ([string]::IsNullOrWhiteSpace([string]$Probe.ServiceStatus)) { 'was not found' } else { 'is ' + [string]$Probe.ServiceStatus }
            return ("PostgreSQL is not running right now (the Windows service '{0}' {1}). TeknoParrot Manager cannot check any password until it runs." -f $script:PostgresServiceName, $statusText)
        }
        'ClientMissing' { return 'The PostgreSQL program psql.exe was not found, so TeknoParrot Manager cannot check the password.' }
        'ProbeError' { return 'TeknoParrot Manager could not run the password check on this PC.' }
    }
    return 'PostgreSQL did not accept the connection, and TeknoParrot Manager could not tell whether the password was the reason. This does not mean the password is wrong.'
}

# Reads the encrypted PostgreSQL credential from the settings file on disk
# (the same $configPath Save-Config writes). Read-only; $null when absent.
function Get-PostgresSavedCredentialFromConfig {
    try {
        if ([string]::IsNullOrWhiteSpace([string]$configPath) -or -not (Test-Path -LiteralPath $configPath -PathType Leaf)) { return $null }
        $parsed = Get-Content -LiteralPath $configPath -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        if ($null -eq $parsed) { return $null }
        $property = $parsed.PSObject.Properties['PostgresSuperPasswordEncrypted']
        if ($null -eq $property -or [string]::IsNullOrWhiteSpace([string]$property.Value)) { return $null }
        return [string]$property.Value
    } catch {
        return $null
    }
}

# FIX36 B3 / owner rule R4: saves a password PostgreSQL has just accepted
# (or that a verified reset just set), then reads the settings file back from
# disk and checks that it decrypts to exactly the same password. The
# in-memory value keeps the verified password even when saving fails, so a
# later Save-Config can still store it; it is never cleared here.
function Save-PostgresVerifiedCredential {
    param([Parameter(Mandatory)][string]$PasswordPlain, [string]$EncryptedValue = '')
    $secure = $null
    $readBackPlain = $null
    try {
        $script:postgresSuperPasswordEncrypted = if ([string]::IsNullOrEmpty($EncryptedValue)) { ConvertTo-PostgresEncryptedPassword $PasswordPlain } else { $EncryptedValue }
        if (-not (Save-Config)) {
            Write-Log 'Postgres credential: verified password could not be saved to the settings file.'
            return [pscustomobject]@{ Saved = $false; Reason = 'SaveFailed' }
        }
        $onDisk = Get-PostgresSavedCredentialFromConfig
        if ([string]::IsNullOrWhiteSpace($onDisk)) {
            Write-Log 'Postgres credential: read-after-write verification found no saved password.'
            return [pscustomobject]@{ Saved = $false; Reason = 'ReadBackMissing' }
        }
        if (-not [string]::IsNullOrEmpty($EncryptedValue)) {
            # The elevated child stores the parent's own encryption of the password;
            # the saved text must be exactly that value.
            if (-not [string]::Equals([string]$onDisk, $EncryptedValue, [System.StringComparison]::Ordinal)) {
                Write-Log 'Postgres credential: read-after-write verification did not match the saved value.'
                return [pscustomobject]@{ Saved = $false; Reason = 'ReadBackMismatch' }
            }
        } else {
            $secure = ConvertTo-SecureString -String $onDisk
            $readBackPlain = ConvertFrom-SecureStringPlain $secure
            if (-not [string]::Equals([string]$readBackPlain, $PasswordPlain, [System.StringComparison]::Ordinal)) {
                Write-Log 'Postgres credential: read-after-write verification did not match the verified password.'
                return [pscustomobject]@{ Saved = $false; Reason = 'ReadBackMismatch' }
            }
        }
        Write-Log 'Postgres credential: verified password saved and read back without logging the password.'
        return [pscustomobject]@{ Saved = $true; Reason = 'SavedAndReadBack' }
    } catch {
        Write-Log 'Postgres credential: verified password could not be saved and read back.'
        return [pscustomobject]@{ Saved = $false; Reason = 'ReadBackFailed' }
    } finally {
        $readBackPlain = $null
        $secure = $null
    }
}

# After an elevated PostgreSQL child returns, adopt the credential it may have
# saved, so a later Save-Config in this process cannot write an older value
# back over it. Never clears the in-memory value. Returns $true when the
# settings file now holds a different credential than this process had.
function Sync-PostgresSavedCredentialFromConfig {
    $onDisk = Get-PostgresSavedCredentialFromConfig
    if ([string]::IsNullOrWhiteSpace($onDisk)) { return $false }
    $changed = -not [string]::Equals([string]$script:postgresSuperPasswordEncrypted, $onDisk, [System.StringComparison]::Ordinal)
    $script:postgresSuperPasswordEncrypted = $onDisk
    return $changed
}

# FIX36B S6: rules for a NEW PostgreSQL password that TPM hands to the
# installer: 1 to 100 printable ASCII characters (space to ~). The password
# then has the same bytes in the installer, the PGPASSWORD variable and the
# server whatever the code page or server encoding, and fits libpq's limits.
# Returns $null when the password is safe, otherwise a plain sentence that
# never contains the password.
function Get-PostgresNewPasswordProblem {
    param([AllowNull()][AllowEmptyString()][string]$Password)
    $rule = 'Use 1 to 100 characters: English letters, digits, spaces and the symbols on a US keyboard.'
    if ([string]::IsNullOrEmpty($Password)) { return ('The password is empty. ' + $rule) }
    if ($Password.Length -gt 100) { return ('The password is longer than 100 characters. ' + $rule) }
    foreach ($character in $Password.ToCharArray()) {
        $code = [int]$character
        if ($code -lt 32 -or $code -gt 126) {
            return ('The password contains a character that PostgreSQL may store differently (for example an accented letter, another alphabet, an emoji or a tab). ' + $rule)
        }
    }
    return $null
}

# FIX129: ONE pass over the text. The secrets are replaced together (the longest first, each distinct secret once), so a secret that
# is part of the marker itself ("RED", "E") or that is listed twice never rewrites a "[REDACTED]" that was just written.
function ConvertTo-PostgresRedactedText {
    param([string]$Text, [string[]]$Secrets = @())
    $safe = if ($null -eq $Text) { '' } else { [string]$Text }
    $distinct = @(@($Secrets) | Where-Object { -not [string]::IsNullOrEmpty($_) } | Select-Object -Unique)
    if ($distinct.Count -eq 0) { return $safe }
    $longestFirst = @($distinct | Sort-Object -Property @{ Expression = { $_.Length }; Descending = $true })
    return [regex]::Replace($safe, (($longestFirst | ForEach-Object { [regex]::Escape([string]$_) }) -join '|'), '[REDACTED]')
}

function Test-PostgresToolExecutable {
    param([Parameter(Mandatory)][string]$FilePath)
    $stream = $null
    try {
        if (-not (Test-Path -LiteralPath $FilePath -PathType Leaf)) { return $false }
        $item = Get-Item -LiteralPath $FilePath -ErrorAction Stop
        if ($item.Length -lt 64) { return $false }
        $stream = [System.IO.File]::OpenRead($item.FullName)
        $header = New-Object byte[] 64
        if ($stream.Read($header, 0, 64) -ne 64) { return $false }
        if ($header[0] -ne 0x4D -or $header[1] -ne 0x5A) { return $false }
        $peOffset = [BitConverter]::ToInt32($header, 0x3C)
        if ($peOffset -lt 64 -or $peOffset -gt ($item.Length - 4)) { return $false }
        $stream.Position = $peOffset
        $signature = New-Object byte[] 4
        if ($stream.Read($signature, 0, 4) -ne 4) { return $false }
        return ($signature[0] -eq 0x50 -and $signature[1] -eq 0x45 -and $signature[2] -eq 0 -and $signature[3] -eq 0)
    } catch {
        return $false
    } finally {
        if ($stream) { $stream.Dispose() }
    }
}

# FIX56 / FIX129: the PostgreSQL tools are started as real child processes (System.Diagnostics.Process), so this function builds
# the command line itself. FIX56 found that Windows PowerShell 5.1 drops the double quotes inside a native-command argument, so
# ALTER DATABASE "GameDBPPL13" ... reached psql without them and the server folded the name to lowercase. Every argument is
# quoted the way the Windows command-line parser (CommandLineToArgvW) reads it back: an argument with a space, tab, newline or
# double quote goes inside quotes, every double quote inside it gets a backslash, and the backslashes in front of a quote (or of
# the closing quote) are doubled. A plain argument is passed as it is; an empty one becomes "".
function ConvertTo-PostgresNativeArgument {
    param([AllowEmptyString()][string]$Value)
    if ($Value.Length -gt 0 -and $Value.IndexOfAny([char[]]@([char]32, [char]9, [char]10, [char]11, [char]34)) -lt 0) { return $Value }
    $builder = New-Object System.Text.StringBuilder
    [void]$builder.Append([char]34)
    $backslashes = 0
    foreach ($character in $Value.ToCharArray()) {
        if ($character -eq [char]92) { $backslashes++; continue }
        if ($character -eq [char]34) {
            [void]$builder.Append([char]92, ($backslashes * 2 + 1))
            [void]$builder.Append([char]34)
        } else {
            if ($backslashes -gt 0) { [void]$builder.Append([char]92, $backslashes) }
            [void]$builder.Append($character)
        }
        $backslashes = 0
    }
    if ($backslashes -gt 0) { [void]$builder.Append([char]92, ($backslashes * 2)) }
    [void]$builder.Append([char]34)
    return $builder.ToString()
}

# FIX129 (S3): the restore checks read English text (Get-PostgresKnownConstraintRestoreWarnings, Test-PostgresPasswordRejectionText).
# The tools and the server translate their messages by the Windows or installer language, so every PostgreSQL tool is started
# with an English message locale: LC_ALL / LC_MESSAGES / LANG = C and LANGUAGE = en for the tool's own text, and
# PGOPTIONS "-c lc_messages=C" (added after any options already set) for the text the server sends back (ERROR / DETAIL lines).
# This only sets the message language of that one child process; the data, the database encoding and this process are untouched.
# If a tool still prints another language, the text is simply not recognized and the restore fails closed as before.
function Get-PostgresEnglishMessageEnvironment {
    param([AllowNull()][AllowEmptyString()][string]$ExistingOptions = '')
    $options = '-c lc_messages=C'
    if (-not [string]::IsNullOrWhiteSpace($ExistingOptions)) { $options = ($ExistingOptions.Trim() + ' ' + $options) }
    return [ordered]@{ LC_ALL = 'C'; LC_MESSAGES = 'C'; LANG = 'C'; LANGUAGE = 'en'; PGOPTIONS = $options }
}

# FIX129 (S4): how long ONE PostgreSQL tool call may run before TeknoParrot Manager stops it and counts it as failed.
# pg_restore and pg_dump (they move a whole database): 4 hours, more than three times a 60-minute restore of the largest bundled
# backup. Every other tool (psql, createdb, dropdb and the --version checks answer in seconds): 30 minutes.
function Get-PostgresToolTimeoutSeconds {
    param([Parameter(Mandatory)][string]$FilePath)
    $name = [System.IO.Path]::GetFileName($FilePath).ToLowerInvariant()
    if ($name -eq 'pg_restore.exe' -or $name -eq 'pg_dump.exe') { return 14400 }
    return 1800
}

# Stops a tool process and every process it started (taskkill /T asks Windows for the whole tree; Kill() is the fallback for the
# process itself). Returns $true only when the process is confirmed gone.
function Stop-PostgresToolProcessTree {
    param([Parameter(Mandatory)][System.Diagnostics.Process]$Process)
    try {
        $taskkill = Join-Path ([Environment]::SystemDirectory) 'taskkill.exe'
        if (Test-Path -LiteralPath $taskkill -PathType Leaf) { & $taskkill /PID $Process.Id /T /F 2>&1 | Out-Null }
    } catch { }
    try { if (-not $Process.HasExited) { $Process.Kill() } } catch { }
    try { [void]$Process.WaitForExit(10000) } catch { }
    try { return [bool]$Process.HasExited } catch { return $false }
}

# FIX129 (S4): runs one tool as a child process with a REAL time limit and returns the RAW result: nothing is redacted here, so the
# result must never be stored or logged as it is (Invoke-PostgresNativeCommand is the only caller and redacts what leaves it).
# Standard output and standard error are read apart (stdout is what the catalog queries are judged on). When the limit passes,
# the process and its children are stopped and TimedOut is set (ExitCode -1). The wait is done in short slices, so a stop request
# (Ctrl+C) still reaches this code, and the child is stopped in finally whenever it is still running.
function Invoke-PostgresToolProcess {
    param(
        [Parameter(Mandatory)][string]$FilePath,
        [string[]]$Arguments = @(),
        [Parameter(Mandatory)][int]$TimeoutSeconds,
        [System.Collections.IDictionary]$EnvironmentOverrides = $null
    )
    $outcome = [ordered]@{ Started = $false; ExitCode = 1; StdOut = ''; StdErr = ''; TimedOut = $false; Stopped = $true; Problem = '' }
    $process = $null
    try {
        $startInfo = New-Object System.Diagnostics.ProcessStartInfo
        $startInfo.FileName = $FilePath
        $startInfo.Arguments = (@($Arguments | ForEach-Object { ConvertTo-PostgresNativeArgument -Value ([string]$_) }) -join ' ')
        $startInfo.UseShellExecute = $false
        $startInfo.CreateNoWindow = $true
        $startInfo.RedirectStandardInput = $true
        $startInfo.RedirectStandardOutput = $true
        $startInfo.RedirectStandardError = $true
        # The same text decoding that a native command in this console used before.
        try { $startInfo.StandardOutputEncoding = [Console]::OutputEncoding; $startInfo.StandardErrorEncoding = [Console]::OutputEncoding } catch { }
        if ($null -ne $EnvironmentOverrides) {
            foreach ($key in @($EnvironmentOverrides.Keys)) { $startInfo.EnvironmentVariables[[string]$key] = [string]$EnvironmentOverrides[$key] }
        }
        try {
            $process = [System.Diagnostics.Process]::Start($startInfo)
        } catch {
            $outcome.Problem = ('PostgreSQL tool {0} could not be started: {1}' -f [System.IO.Path]::GetFileName($FilePath), $_.Exception.Message)
            return [pscustomobject]$outcome
        }
        $outcome.Started = $true
        try { $process.StandardInput.Close() } catch { }
        $stdOutTask = $process.StandardOutput.ReadToEndAsync()
        $stdErrTask = $process.StandardError.ReadToEndAsync()
        $deadline = [DateTime]::UtcNow.AddSeconds($TimeoutSeconds)
        $exited = $false
        while (-not $exited) {
            if ($process.WaitForExit(250)) { $exited = $true }
            elseif ([DateTime]::UtcNow -ge $deadline) { break }
        }
        if (-not $exited) {
            $outcome.TimedOut = $true
            $outcome.Stopped = Stop-PostgresToolProcessTree -Process $process
        }
        $pipesClosed = $false
        try { $pipesClosed = [System.Threading.Tasks.Task]::WaitAll([System.Threading.Tasks.Task[]]@($stdOutTask, $stdErrTask), $(if ($exited) { 30000 } else { 10000 })) } catch { $pipesClosed = $false }
        if (-not $pipesClosed -and $exited) {
            # The tool ended but something it started still holds its output open: the answer cannot be trusted as complete.
            $outcome.TimedOut = $true
            $outcome.Problem = 'The tool ended, but its output was not closed in time.'
        }
        if ($stdOutTask.IsCompleted -and -not $stdOutTask.IsFaulted) { $outcome.StdOut = [string]$stdOutTask.Result }
        if ($stdErrTask.IsCompleted -and -not $stdErrTask.IsFaulted) { $outcome.StdErr = [string]$stdErrTask.Result }
        $outcome.ExitCode = if ($outcome.TimedOut) { -1 } else { [int]$process.ExitCode }
    } finally {
        if ($null -ne $process) {
            try { if (-not $process.HasExited) { [void](Stop-PostgresToolProcessTree -Process $process) } } catch { }
            try { $process.Dispose() } catch { }
        }
    }
    return [pscustomobject]$outcome
}

# PasswordPlain (FIX95 S5) is handed to the PostgreSQL tool through PGPASSWORD,
# set only around this one call (Set-PostgresPasswordEnvironment) and always
# put back in finally. It is never an argument and is redacted from the output.
# FIX129: the returned Output is the redacted text for logs and screens. A caller that must DECIDE from the text passes
# -Interpret: a script block { param($Raw, $Context) } that receives the RAW result (ExitCode, TimedOut, StdOut, StdErr, Output)
# and -InterpretContext in memory and returns a small answer object; it lands in Interpretation. (A plain script block, not a
# closure: a closure could not see the script's own functions.) The block must not return the raw text or anything that holds a
# secret, because the result of this function can be logged or kept in a receipt. A block that throws leaves Interpretation
# empty (callers fail closed). The call has a real time limit (Get-PostgresToolTimeoutSeconds unless -TimeoutSeconds is given):
# see Invoke-PostgresToolProcess; a stopped tool returns TimedOut = $true and a non-zero ExitCode.
function Invoke-PostgresNativeCommand {
    param(
        [Parameter(Mandatory)][string]$FilePath,
        [string[]]$Arguments = @(),
        [string[]]$Secrets = @(),
        [AllowEmptyString()][string]$PasswordPlain = '',
        [int]$TimeoutSeconds = 0,
        [scriptblock]$Interpret = $null,
        [object]$InterpretContext = $null
    )
    if (-not (Test-PostgresToolExecutable -FilePath $FilePath)) {
        return [pscustomobject]@{ ExitCode = 1; Output = ('PostgreSQL tool {0} is not a verified Windows executable and was not started.' -f [System.IO.Path]::GetFileName($FilePath)); TimedOut = $false }
    }
    if ($TimeoutSeconds -le 0) { $TimeoutSeconds = Get-PostgresToolTimeoutSeconds -FilePath $FilePath }
    $passwordSet = $false
    $previousPassword = $null
    $longWait = $false
    $processResult = $null
    try {
        if (-not [string]::IsNullOrEmpty($PasswordPlain)) {
            $previousPassword = Set-PostgresPasswordEnvironment -Password $PasswordPlain
            $passwordSet = $true
        }
        # The tool reports nothing while it runs (a restore can take minutes): the open bar reads "still working", never "stalled".
        if (Test-Path -LiteralPath 'Function:\Enter-TpmLongWait') { $longWait = Enter-TpmLongWait }
        $messageEnvironment = Get-PostgresEnglishMessageEnvironment -ExistingOptions ([Environment]::GetEnvironmentVariable('PGOPTIONS'))
        $processResult = Invoke-PostgresToolProcess -FilePath $FilePath -Arguments @($Arguments) -TimeoutSeconds $TimeoutSeconds -EnvironmentOverrides $messageEnvironment
    } finally {
        if ($longWait) { Exit-TpmLongWait }
        if ($passwordSet) { Restore-PostgresPasswordEnvironment -PreviousValue $previousPassword }
    }
    $stdOutText = ([string]$processResult.StdOut).Trim()
    $stdErrText = ([string]$processResult.StdErr).Trim()
    $rawOutput = (@($stdOutText, $stdErrText) | Where-Object { $_ -ne '' }) -join "`r`n"
    $raw = [pscustomobject]@{
        ExitCode = [int]$processResult.ExitCode
        TimedOut = [bool]$processResult.TimedOut
        StdOut = [string]$processResult.StdOut
        StdErr = [string]$processResult.StdErr
        Output = $rawOutput
    }
    # Only the redacted text leaves this function. The notes below hold no secret.
    $shown = ConvertTo-PostgresRedactedText -Text $rawOutput -Secrets (@($Secrets) + @($PasswordPlain))
    $notes = New-Object System.Collections.Generic.List[string]
    if (-not [string]::IsNullOrWhiteSpace([string]$processResult.Problem)) { [void]$notes.Add((ConvertTo-PostgresRedactedText -Text ([string]$processResult.Problem) -Secrets (@($Secrets) + @($PasswordPlain)))) }
    if ($raw.TimedOut) {
        $stopText = if ([bool]$processResult.Stopped) { 'and was stopped' } else { 'and could not be confirmed stopped' }
        $limitText = if ($TimeoutSeconds -ge 120) { '{0} minutes' -f [int][Math]::Round($TimeoutSeconds / 60.0) } else { '{0} seconds' -f $TimeoutSeconds }
        [void]$notes.Add(('TeknoParrot Manager gave up on {0} after {1} because it did not finish {2}.' -f [System.IO.Path]::GetFileName($FilePath), $limitText, $stopText))
        try { Write-Log ('Postgres: {0} ran longer than {1} seconds {2}; it is counted as failed.' -f [System.IO.Path]::GetFileName($FilePath), $TimeoutSeconds, $stopText) } catch { }
    }
    if ($notes.Count -gt 0) { $shown = ((@($shown) + @($notes.ToArray())) | Where-Object { $_ -ne '' }) -join "`r`n" }
    $result = [ordered]@{ ExitCode = $raw.ExitCode; Output = $shown; TimedOut = $raw.TimedOut }
    if ($null -ne $Interpret) {
        $interpretation = $null
        try { $interpretation = & $Interpret $raw $InterpretContext } catch { $interpretation = $null }
        $result['Interpretation'] = $interpretation
    }
    return [pscustomobject]$result
}

function Copy-PostgresRecoveryEvidenceFile {
    param([Parameter(Mandatory)][string]$Source, [Parameter(Mandatory)][string]$Destination)
    if (-not (Test-Path -LiteralPath $Source -PathType Leaf)) { throw 'Postgres recovery evidence source is missing.' }
    Assert-TpmNoReparseWriteTarget -Path $Source -Operation 'read PostgreSQL recovery evidence'
    $destinationDirectory = [System.IO.Path]::GetDirectoryName($Destination)
    [void][System.IO.Directory]::CreateDirectory($destinationDirectory)
    Assert-TpmNoReparseWriteTarget -Path $Destination -Operation 'write PostgreSQL recovery evidence'
    [System.IO.File]::Copy($Source, $Destination, $false)
    Assert-TpmNoReparseWriteTarget -Path $Destination -Operation 'verify PostgreSQL recovery evidence path'
    Lock-PostgresRecoveryFile -Path $Destination
    $sourceItem = Get-Item -LiteralPath $Source -Force -ErrorAction Stop
    $destItem = Get-Item -LiteralPath $Destination -Force -ErrorAction Stop
    $sourceHash = (Get-FileHash -LiteralPath $Source -Algorithm SHA256 -ErrorAction Stop).Hash
    $destHash = (Get-FileHash -LiteralPath $Destination -Algorithm SHA256 -ErrorAction Stop).Hash
    if ($sourceItem.Length -ne $destItem.Length -or $sourceHash -ne $destHash) { throw 'Postgres recovery evidence hash verification failed.' }
    return [pscustomobject]@{ Source = $Source; Backup = $Destination; Sha256 = $destHash }
}

# FIX36B S2: TPM's private PostgreSQL files and folders (temporary credential
# files, recovery evidence, the trust-rule marker) are locked to the current
# Windows user by SID, never by account name: a name can fail to resolve, or
# resolve differently, for AzureAD, domain or non-ASCII accounts. Each step
# reports one of three outcomes and only 'Success' counts as locked:
#   Success - the access list holds only explicit Allow entries for the current
#             user's SID, plus optionally Administrators or SYSTEM, none inherited.
#   Failed  - the ACL tool reported an error, or the list grants another account,
#             holds a deny entry or inherits entries.
#   Unknown - the list could not be set, read or resolved, so TPM cannot tell.
# FAT, FAT32 and exFAT drives keep no file permissions, so "only the current user" cannot be set or checked there. Such a drive is
# treated as already restricted; refusing would stop every start-up for a TeknoParrot folder on one of these drives.
function Test-TpmVolumeHasNoFilePermissions {
    param([Parameter(Mandatory)][string]$Path, [string]$VolumeFormat = '')
    try {
        $root = [System.IO.Path]::GetPathRoot([System.IO.Path]::GetFullPath($Path))
        if ([string]::IsNullOrWhiteSpace($root) -or $root.StartsWith('\\')) { return $false }
        $format = if ([string]::IsNullOrWhiteSpace($VolumeFormat)) { [System.IO.DriveInfo]::new($root).DriveFormat } else { $VolumeFormat }
        return ($format -in @('FAT', 'FAT32', 'exFAT'))
    } catch { return $false }
}

function Get-PostgresOwnerOnlyAclState {
    param([Parameter(Mandatory)][string]$Path)
    if (Test-TpmVolumeHasNoFilePermissions -Path $Path) { return [pscustomobject]@{ Outcome = 'Success'; Detail = 'This drive keeps no file permissions, so there is nothing to restrict.' } }
    try {
        $currentSid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value
        $rules = @((Get-Acl -LiteralPath $Path -ErrorAction Stop).Access)
    } catch {
        return [pscustomobject]@{ Outcome = 'Unknown'; Detail = 'The access list could not be read.' }
    }
    $grantsCurrentUser = $false
    # Administrators and SYSTEM can always take over a file, so an explicit entry for them adds no exposure. Elevated or
    # Administrator accounts keep such an entry; refusing it would stop PostgreSQL setup, backups and migration for them.
    $alwaysTrustedSids = @('S-1-5-32-544', 'S-1-5-18')
    foreach ($rule in $rules) {
        if ($rule.IsInherited) { return [pscustomobject]@{ Outcome = 'Failed'; Detail = 'The access list still inherits entries.' } }
        $resolved = $null
        try { $resolved = $rule.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]).Value } catch { $resolved = $null }
        if ([string]::IsNullOrWhiteSpace($resolved)) { return [pscustomobject]@{ Outcome = 'Unknown'; Detail = 'An access entry could not be resolved to a Windows account.' } }
        if ($rule.AccessControlType -ne [System.Security.AccessControl.AccessControlType]::Allow) { return [pscustomobject]@{ Outcome = 'Failed'; Detail = 'The access list holds a deny entry.' } }
        if ($resolved -eq $currentSid) { $grantsCurrentUser = $true; continue }
        if ($resolved -notin $alwaysTrustedSids) { return [pscustomobject]@{ Outcome = 'Failed'; Detail = 'The access list grants another account.' } }
    }
    if (-not $grantsCurrentUser) { return [pscustomobject]@{ Outcome = 'Failed'; Detail = 'The access list does not grant the current user.' } }
    return [pscustomobject]@{ Outcome = 'Success'; Detail = '' }
}

function Set-PostgresOwnerOnlyAcl {
    param([Parameter(Mandatory)][string]$Path, [switch]$Directory)
    if (Test-TpmVolumeHasNoFilePermissions -Path $Path) { return [pscustomobject]@{ Outcome = 'Success'; Detail = 'This drive keeps no file permissions, so there is nothing to restrict.' } }
    $sid = $null
    try { $sid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value } catch { $sid = $null }
    if ([string]::IsNullOrWhiteSpace($sid)) { return [pscustomobject]@{ Outcome = 'Unknown'; Detail = 'The current Windows account SID could not be read.' } }
    $permission = if ($Directory) { '(OI)(CI)(F)' } else { '(F)' }
    $state = $null
    foreach ($attempt in 1, 2) {
        $exitCode = $null
        try {
            if ($attempt -eq 2) {
                # A folder whose parent has an old-style access list gets copies of the parent's entries (SYSTEM, Administrators, Users)
                # that Windows does not mark as inherited, so removing inheritance leaves them in place. Reset the list to the
                # inherited defaults once, then remove inheritance again.
                & icacls $Path /reset 1>$null 2>$null
                if ($LASTEXITCODE -ne 0) { return $state }
            }
            & icacls $Path /inheritance:r /grant:r ('*{0}:{1}' -f $sid, $permission) 1>$null 2>$null
            $exitCode = $LASTEXITCODE
        } catch {
            return [pscustomobject]@{ Outcome = 'Unknown'; Detail = 'The Windows ACL tool could not be run or reported an error.' }
        }
        if ($null -eq $exitCode) { return [pscustomobject]@{ Outcome = 'Unknown'; Detail = 'The Windows ACL tool returned no exit code.' } }
        if ([int]$exitCode -ne 0) { return [pscustomobject]@{ Outcome = 'Failed'; Detail = ('The Windows ACL tool reported exit code {0}.' -f $exitCode) } }
        $state = Get-PostgresOwnerOnlyAclState -Path $Path
        if ([string]$state.Outcome -ne 'Failed') { return $state }
    }
    return $state
}

function Assert-PostgresRecoveryDirectoryAcl {
    param([Parameter(Mandatory)][string]$Path)
    if ([string](Get-PostgresOwnerOnlyAclState -Path $Path).Outcome -ne 'Success') { throw 'Postgres recovery evidence ACL still grants access beyond the current user.' }
}

function Lock-PostgresRecoveryDirectory {
    param([Parameter(Mandatory)][string]$Path)
    $lock = Set-PostgresOwnerOnlyAcl -Path $Path -Directory
    if ([string]$lock.Outcome -ne 'Success') { throw ('Postgres recovery evidence ACL could not be verified. {0}' -f [string]$lock.Detail).TrimEnd() }
}

function Assert-PostgresRecoveryFileAcl {
    param([Parameter(Mandatory)][string]$Path)
    if ([string](Get-PostgresOwnerOnlyAclState -Path $Path).Outcome -ne 'Success') { throw 'Postgres recovery file ACL is not restricted to the current user.' }
}

function Lock-PostgresRecoveryFile {
    param([Parameter(Mandatory)][string]$Path)
    $lock = Set-PostgresOwnerOnlyAcl -Path $Path
    if ([string]$lock.Outcome -ne 'Success') { throw ('Postgres recovery file ACL could not be restricted. {0}' -f [string]$lock.Detail).TrimEnd() }
}

function Lock-TpmOwnedMigrationBackupTree {
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][datetime]$StartedAt)
    if (-not (Test-TpmNoReparsePath -Path $Path)) { throw 'Migration backup tree failed its path safety check.' }
    $rootItem = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    if (-not $rootItem.PSIsContainer) {
        Lock-PostgresRecoveryFile -Path $Path
        return
    }
    Lock-PostgresRecoveryDirectory -Path $Path
    $pending = New-Object System.Collections.Generic.List[string]
    [void]$pending.Add($Path)
    $processed = 0
    while ($pending.Count -gt 0) {
        $current = $pending[0]
        $pending.RemoveAt(0)
        if (-not (Test-TpmNoReparsePath -Path $current)) { throw 'Migration backup directory failed its path safety check.' }
        $directory = New-Object System.IO.DirectoryInfo($current)
        foreach ($child in $directory.EnumerateFileSystemInfos()) {
            $processed++
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'Owned-state backup ACL verification' -Current $processed -Total 0 -StartedAt $StartedAt
            if (($child.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0 -or
                -not (Test-TpmNoReparsePath -Path $child.FullName)) {
                throw 'Migration backup tree contains an unsafe path.'
            }
            if (($child.Attributes -band [System.IO.FileAttributes]::Directory) -ne 0) {
                Lock-PostgresRecoveryDirectory -Path $child.FullName
                [void]$pending.Add($child.FullName)
            } else {
                Lock-PostgresRecoveryFile -Path $child.FullName
            }
        }
    }
}

function Test-TpmRecoveryEvidenceEntry {
    param([Parameter(Mandatory)]$Entry)
    return ([string]$Entry.Item.Name -ceq 'PostgresRecoveryBackups' -and [bool]$Entry.Item.IsDirectory)
}

# Verifies (never changes) that every directory and file under Path is restricted to the current user.
function Assert-TpmPrivateRecoveryTree {
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-TpmNoReparsePath -Path $Path)) { throw 'Recovery evidence tree failed its path safety check.' }
    $rootItem = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    if (-not $rootItem.PSIsContainer) { Assert-PostgresRecoveryFileAcl -Path $Path; return }
    Assert-PostgresRecoveryDirectoryAcl -Path $Path
    $pending = New-Object 'System.Collections.Generic.Stack[string]'
    $pending.Push($Path)
    while ($pending.Count -gt 0) {
        $current = $pending.Pop()
        foreach ($child in (New-Object System.IO.DirectoryInfo($current)).EnumerateFileSystemInfos()) {
            if (($child.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'Recovery evidence tree contains an unsafe path.' }
            if (($child.Attributes -band [System.IO.FileAttributes]::Directory) -ne 0) {
                Assert-PostgresRecoveryDirectoryAcl -Path $child.FullName
                $pending.Push($child.FullName)
            } else {
                Assert-PostgresRecoveryFileAcl -Path $child.FullName
            }
        }
    }
}

function Test-TpmRecoveryResiduePrivate {
    param([Parameter(Mandatory)][string]$Path)
    try { Assert-TpmPrivateRecoveryTree -Path $Path; return $true } catch { return $false }
}

# Creates the destination tree with every directory exclusively created and locked
# to the current user before any child is written, so no recovery byte lands under
# an inherited or foreign ACL. Never uses Copy-Item/Move-Item ACL semantics.
function Copy-TpmProtectedRecoveryTree {
    param([Parameter(Mandatory)][string]$Source, [Parameter(Mandatory)][string]$Destination, [Parameter(Mandatory)][datetime]$StartedAt)
    if (-not (Test-TpmNoReparsePath -Path $Source)) { throw 'Recovery evidence source failed its path safety check.' }
    Assert-TpmNoReparseWriteTarget -Path $Destination -Operation 'protected recovery evidence copy'
    if (Test-Path -LiteralPath $Destination -ErrorAction Stop) { throw 'Protected recovery evidence destination already exists.' }
    $pending = New-Object 'System.Collections.Generic.Queue[object]'
    $pending.Enqueue([pscustomobject]@{ Source = $Source; Destination = $Destination })
    $processed = 0
    $processedCompleted = $false
    try {
        while ($pending.Count -gt 0) {
            $pair = $pending.Dequeue()
            if (-not (Test-TpmNoReparsePath -Path $pair.Source)) { throw 'Recovery evidence source directory failed its path safety check.' }
            [void][System.IO.Directory]::CreateDirectory($pair.Destination)
            Assert-TpmNoReparseWriteTarget -Path $pair.Destination -Operation 'protected recovery evidence directory'
            Lock-PostgresRecoveryDirectory -Path $pair.Destination
            if ($null -ne (Get-ChildItem -LiteralPath $pair.Destination -Force -ErrorAction Stop | Select-Object -First 1)) { throw 'Protected recovery evidence directory was not empty after creation.' }
            foreach ($child in (New-Object System.IO.DirectoryInfo($pair.Source)).EnumerateFileSystemInfos()) {
                $processed++
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'Recovery evidence protected copy' -Current $processed -Total 0 -StartedAt $StartedAt
                if (($child.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'Recovery evidence tree contains an unsafe path.' }
                $target = Join-Path $pair.Destination $child.Name
                if (($child.Attributes -band [System.IO.FileAttributes]::Directory) -ne 0) {
                    $pending.Enqueue([pscustomobject]@{ Source = $child.FullName; Destination = $target })
                    continue
                }
                $sourceStream = $null; $targetStream = $null
                try {
                    $sourceStream = New-Object System.IO.FileStream($child.FullName, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
                    $targetStream = New-Object System.IO.FileStream($target, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
                    $sourceStream.CopyTo($targetStream)
                    $targetStream.Flush($true)
                } finally {
                    if ($null -ne $targetStream) { $targetStream.Dispose() }
                    if ($null -ne $sourceStream) { $sourceStream.Dispose() }
                }
                Lock-PostgresRecoveryFile -Path $target
                [System.IO.File]::SetLastWriteTimeUtc($target, $child.LastWriteTimeUtc)
                $ordinary = [int]$child.Attributes -band 0x27
                [System.IO.File]::SetAttributes($target, $(if ($ordinary -eq 0) { [System.IO.FileAttributes]::Normal } else { [System.IO.FileAttributes]$ordinary }))
            }
        }
        $processedCompleted = $true
    } finally {
        if ($processed -gt 0) { Write-TpmCompactExtractionProgress -Phase Repairing -Label 'Recovery evidence protected copy' -Current $processed -Total 0 -StartedAt $StartedAt -Complete -Outcome $(if ($processedCompleted) { 'Final' } else { 'Error' }) }
    }
}

# Protected move: verify the source is private, copy into a locked tree, verify bytes
# and descendant ACLs, re-verify the SOURCE manifest, and only then remove the source.
# A source that changed after it was copied (anything written there was never copied)
# is not removed. Any failure leaves both trees in place (private) for the caller to
# report as residue; nothing is pruned.
function Move-TpmProtectedRecoveryTree {
    param(
        [Parameter(Mandatory)][string]$Source, [Parameter(Mandatory)][string]$Destination,
        [Parameter(Mandatory)][string]$ExpectedManifestHash, [Parameter(Mandatory)][datetime]$StartedAt
    )
    Assert-TpmPrivateRecoveryTree -Path $Source
    Copy-TpmProtectedRecoveryTree -Source $Source -Destination $Destination -StartedAt $StartedAt
    Assert-TpmPrivateRecoveryTree -Path $Destination
    $copied = Get-TpmDirectoryManifest -Path $Destination -ProgressLabel 'Recovery evidence copy verification'
    if (-not $copied.Readable -or -not $copied.Exists -or [string]$copied.ManifestHash -ine $ExpectedManifestHash) {
        throw 'Recovery evidence copy did not match its verified manifest; the source was not removed.'
    }
    # The source may have gained or changed files while it was copied and verified. Re-take its manifest immediately before deletion; deleting a tree that no longer matches would destroy evidence that was never copied.
    $sourceNow = Get-TpmDirectoryManifest -Path $Source -ProgressLabel 'Recovery evidence source re-verification'
    if (-not $sourceNow.Readable -or -not $sourceNow.Exists -or [string]$sourceNow.ManifestHash -ine $ExpectedManifestHash) {
        throw 'Recovery evidence source changed after it was copied; the source was not removed and both trees were kept.'
    }
    Remove-Item -LiteralPath $Source -Recurse -Force -ErrorAction Stop
    if (Test-Path -LiteralPath $Source) { throw 'Recovery evidence source remains after the protected move.' }
}

function New-PostgresRecoveryBackup {
    param([Parameter(Mandatory)][string]$UserProfilesDir)
    $timestamp = (Get-Date).ToString('yyyy-MM-dd_HH-mm-ss_fff', [System.Globalization.CultureInfo]::InvariantCulture)
    $backupParent = Get-PostgresRecoveryBackupRoot
    $backupRoot = Join-Path $backupParent ($timestamp + '_' + [guid]::NewGuid().ToString('N'))
    $configBackupRoot = Join-Path $backupRoot 'PostgreSQL'
    $profileBackupRoot = Join-Path $backupRoot 'Profiles'
    $profileBackups = New-Object System.Collections.Generic.List[object]
    $configBackups = New-Object System.Collections.Generic.List[object]
    $profileProgressStarted = $null
    $profileProgressCurrent = 0
    $profileProgressTotal = 0
    try {
        Assert-TpmNoReparseWriteTarget -Path $backupParent -Operation 'create PostgreSQL recovery backup root'
        [void][System.IO.Directory]::CreateDirectory($backupParent)
        Assert-TpmNoReparseWriteTarget -Path $backupParent -Operation 'secure PostgreSQL recovery backup root'
        Lock-PostgresRecoveryDirectory -Path $backupParent
        Assert-TpmNoReparseWriteTarget -Path $backupRoot -Operation 'create PostgreSQL recovery backup'
        [void][System.IO.Directory]::CreateDirectory($backupRoot)
        Assert-TpmNoReparseWriteTarget -Path $backupRoot -Operation 'secure PostgreSQL recovery backup'
        Lock-PostgresRecoveryDirectory -Path $backupRoot
        Assert-TpmNoReparseWriteTarget -Path $configBackupRoot -Operation 'create PostgreSQL config backup'
        [void][System.IO.Directory]::CreateDirectory($configBackupRoot)
        Assert-TpmNoReparseWriteTarget -Path $configBackupRoot -Operation 'secure PostgreSQL config backup'
        Lock-PostgresRecoveryDirectory -Path $configBackupRoot
        Assert-TpmNoReparseWriteTarget -Path $profileBackupRoot -Operation 'create PostgreSQL profile backup'
        [void][System.IO.Directory]::CreateDirectory($profileBackupRoot)
        Assert-TpmNoReparseWriteTarget -Path $profileBackupRoot -Operation 'secure PostgreSQL profile backup'
        Lock-PostgresRecoveryDirectory -Path $profileBackupRoot
        $dataDir = Join-Path $script:PostgresInstallDir 'data'
        if (-not (Test-Path -LiteralPath $dataDir -PathType Container)) { throw 'Postgres data directory is not present.' }
        foreach ($configName in @('pg_hba.conf', 'postgresql.conf')) {
            [void]$configBackups.Add((Copy-PostgresRecoveryEvidenceFile -Source (Join-Path $dataDir $configName) -Destination (Join-Path $configBackupRoot $configName)))
        }
        $configVariable = Get-Variable -Name configPath -Scope Script -ErrorAction SilentlyContinue
        if ($configVariable -and $configVariable.Value -and (Test-Path -LiteralPath $configVariable.Value -PathType Leaf)) {
            [void]$configBackups.Add((Copy-PostgresRecoveryEvidenceFile -Source $configVariable.Value -Destination (Join-Path $backupRoot 'TeknoParrot-Manager.config.json')))
        }
        if (-not (Test-Path -LiteralPath $UserProfilesDir -PathType Container)) { throw 'UserProfiles directory is not present.' }
        $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'PostgreSQL recovery profile discovery' -EnumerationErrorAction Stop | Sort-Object Name)
        $profileProgressTotal = $profiles.Count
        if ($profileProgressTotal -gt 0) { $profileProgressStarted = Get-Date }
        foreach ($profileFile in $profiles) {
            $profileProgressCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL recovery profile scan' -Current $profileProgressCurrent -Total $profileProgressTotal -StartedAt $profileProgressStarted
            $doc = Read-Xml $profileFile.FullName
            if ($doc.GameProfile -and (Test-GameNeedsPostgres $doc)) {
                [void]$profileBackups.Add((Copy-PostgresRecoveryEvidenceFile -Source $profileFile.FullName -Destination (Join-Path $profileBackupRoot $profileFile.Name)))
            }
        }
        if ($profileProgressTotal -gt 0) {
            # The scan visited every profile, but finding none to back up means no recovery copy was made: that is not a finished step.
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL recovery profile scan' -Current $profileProgressCurrent -Total $profileProgressTotal -StartedAt $profileProgressStarted -Complete -Outcome $(if ($profileBackups.Count -eq 0) { 'Error' } else { 'Final' })
            $profileProgressStarted = $null
        }
        if ($profileBackups.Count -eq 0) { throw 'No affected PostgreSQL profiles were identified.' }
        return [pscustomobject]@{ Path = $backupRoot; ConfigBackups = $configBackups.ToArray(); ProfileBackups = $profileBackups.ToArray(); Verified = $true }
    } catch {
        if ($profileProgressStarted -and $profileProgressTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL recovery profile scan' -Current $profileProgressCurrent -Total $profileProgressTotal -StartedAt $profileProgressStarted -Complete -Outcome Error }
        Write-Log "Postgres recovery backup: blocked; evidence remains at $backupRoot."
        return [pscustomobject]@{ Path = $backupRoot; ConfigBackups = $configBackups.ToArray(); ProfileBackups = $profileBackups.ToArray(); Verified = $false }
    }
}
function Get-PostgresRecoveryBackupState {
    param(
        [object]$RecoveryBackup,
        [Parameter(Mandatory)][bool]$Attempted
    )
    $backupPath = [string](Get-TpmTransactionField -Object $RecoveryBackup -Name 'Path' -Default $null)
    $created = $false
    if (-not [string]::IsNullOrWhiteSpace($backupPath)) {
        $created = [bool](Test-Path -LiteralPath $backupPath -PathType Container -ErrorAction SilentlyContinue)
    }
    return [pscustomobject]@{
        Attempted = [bool]$Attempted
        Created = $created
        Verified = [bool](Get-TpmTransactionField -Object $RecoveryBackup -Name 'Verified' -Default $false)
        Path = $backupPath
    }
}

function Get-PostgresRecoveryBackupRoot {
    return (Join-Path (Get-TpmOwnedBackupsRoot -BackupName 'PostgresRecoveryBackups') 'PostgresRecoveryBackups')
}

function Get-PostgresTrustRuleMarkerPath {
    return (Join-Path (Get-PostgresRecoveryBackupRoot) 'PostgresTrustRule.marker.json')
}

function Read-PostgresTrustRuleMarkerFile {
    param([Parameter(Mandatory)][string]$MarkerPath)
    Assert-TpmNoReparseWriteTarget -Path $MarkerPath -Operation 'PostgreSQL recovery marker read'
    Assert-PostgresRecoveryDirectoryAcl -Path ([System.IO.Path]::GetDirectoryName($MarkerPath))
    Assert-PostgresRecoveryFileAcl -Path $MarkerPath
    $text = [System.IO.File]::ReadAllText($MarkerPath, (New-Object System.Text.UTF8Encoding $false))
    $marker = $text | ConvertFrom-Json -ErrorAction Stop
    if ($null -eq $marker) { throw 'The PostgreSQL recovery marker is empty.' }
    if ([string]$marker.Schema -ne 'TPM.PostgresTrustRuleMarker.v1') { throw 'The PostgreSQL recovery marker schema is not recognized.' }
    foreach ($field in @('Guid', 'HbaPath', 'BackupHbaPath', 'OriginalSha256')) {
        if ([string]::IsNullOrWhiteSpace([string]$marker.$field)) { throw 'The PostgreSQL recovery marker is incomplete.' }
    }
    if ([string]$marker.OriginalSha256 -notmatch '^[0-9A-Fa-f]{64}$') { throw 'The PostgreSQL recovery marker hash is invalid.' }
    # TrustSha256 (FIX36 S5) is optional so markers from older TPM versions stay
    # readable; without it TPM never restores the file automatically.
    $trustHashProperty = $marker.PSObject.Properties['TrustSha256']
    if ($trustHashProperty -and -not [string]::IsNullOrWhiteSpace([string]$trustHashProperty.Value) -and [string]$trustHashProperty.Value -notmatch '^[0-9A-Fa-f]{64}$') { throw 'The PostgreSQL recovery marker trust-rule hash is invalid.' }
    [void][guid]([string]$marker.Guid)
    return $marker
}

function Remove-PostgresTrustRuleMarker {
    $markerPath = Get-PostgresTrustRuleMarkerPath
    try {
        Remove-Item -LiteralPath $markerPath -Force -ErrorAction Stop
    } catch [System.Management.Automation.ItemNotFoundException] {
        return
    }
    try {
        [void](Get-Item -LiteralPath $markerPath -Force -ErrorAction Stop)
    } catch [System.Management.Automation.ItemNotFoundException] {
        return
    }
    throw 'The PostgreSQL recovery marker is still present after removal.'
}

# -ReadOnly (FIX36 B4 startup check) reports the state without removing the
# marker or restoring any file. Without -ReadOnly, a Stopped service lets TPM
# clear a marker whose file is already original, or restore the original file
# only when the live file is exactly TPM's trust-rule version (FIX36 S5).
function Get-PostgresTrustRuleMarkerState {
    param([switch]$ReadOnly)
    $state = [pscustomobject]@{
        State = 'Error'
        MarkerPath = $null
        HbaPath = $null
        BackupHbaPath = $null
        OriginalSha256 = $null
        TrustSha256 = $null
        LiveState = $null
        Busy = $false
        Reason = 'The PostgreSQL recovery marker state could not be verified.'
    }
    $lockTaken = $false
    try {
        $markerPath = Get-PostgresTrustRuleMarkerPath
        $state.MarkerPath = $markerPath
        $recoveryRoot = [System.IO.Path]::GetFullPath((Get-PostgresRecoveryBackupRoot))
        $backupParent = [System.IO.Path]::GetDirectoryName($recoveryRoot)
        if ([string]::IsNullOrWhiteSpace($backupParent) -or -not (Test-Path -LiteralPath $backupParent -PathType Container -ErrorAction SilentlyContinue) -or -not (Test-TpmNoReparsePath -Path $backupParent)) {
            throw 'PostgreSQL recovery backup parent path is missing or failed its path-safety check.'
        }
        $recoveryRootItem = $null
        try {
            $recoveryRootItem = Get-Item -LiteralPath $recoveryRoot -Force -ErrorAction Stop
        } catch [System.Management.Automation.ItemNotFoundException] {}
        if ($null -ne $recoveryRootItem) {
            if (-not $recoveryRootItem.PSIsContainer -or ($recoveryRootItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) {
                throw 'PostgreSQL recovery backup root is not a safe directory.'
            }
            Assert-PostgresRecoveryDirectoryAcl -Path $recoveryRoot
        }

        # FIX36B S7: the automatic clear or restore below changes TPM's recovery
        # files, so it runs only while this TPM holds the PostgreSQL repair lock.
        # When another TPM window holds it, nothing is touched and PostgreSQL
        # work stops here.
        if (-not $ReadOnly) {
            $lockTaken = [bool](Enter-PostgresRecoveryLock)
            if (-not $lockTaken) {
                $state.State = 'Required'
                $state.Busy = $true
                $state.Reason = 'Another TeknoParrot Manager window is changing PostgreSQL right now.'
                return $state
            }
        }

        try {
            [void](Get-Item -LiteralPath $markerPath -Force -ErrorAction Stop)
        } catch [System.Management.Automation.ItemNotFoundException] {
            $state.State = 'None'
            $state.Reason = $null
            return $state
        }
        $marker = Read-PostgresTrustRuleMarkerFile -MarkerPath $markerPath
        $state.HbaPath = [string]$marker.HbaPath
        $state.BackupHbaPath = [string]$marker.BackupHbaPath
        $state.OriginalSha256 = ([string]$marker.OriginalSha256).ToUpperInvariant()
        $state.TrustSha256 = ([string]$marker.TrustSha256).ToUpperInvariant()
        $liveHash = (Get-FileHash -LiteralPath $state.HbaPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
        $state.LiveState = if ($liveHash -eq $state.OriginalSha256) { 'Original' } elseif (-not [string]::IsNullOrWhiteSpace($state.TrustSha256) -and $liveHash -eq $state.TrustSha256) { 'TemporaryTrust' } else { 'Changed' }
        $currentService = Get-Service -Name $script:PostgresServiceName -ErrorAction SilentlyContinue
        $serviceNowStopped = [bool]($currentService -and $currentService.Status -eq 'Stopped')
        if (-not $ReadOnly -and $state.LiveState -eq 'Original' -and $serviceNowStopped) {
            Remove-PostgresTrustRuleMarker
            $state.State = 'None'
            $state.Reason = $null
            return $state
        }
        if (-not $ReadOnly -and $state.LiveState -eq 'TemporaryTrust' -and $serviceNowStopped) {
            # Disk contents alone do not prove which policy a running server loaded.
            # Automatic recovery is allowed only after the service is observed stopped,
            # and only over TPM's own trust-rule version of the file: any later edit
            # (LiveState 'Changed') is left for the user to review.
            Assert-TpmNoReparseWriteTarget -Path $state.BackupHbaPath -Operation 'read PostgreSQL authentication recovery evidence'
            Assert-PostgresRecoveryFileAcl -Path $state.BackupHbaPath
            $backupHash = (Get-FileHash -LiteralPath $state.BackupHbaPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
            if ($backupHash -eq $state.OriginalSha256) {
                Restore-PostgresHbaFromBackup -HbaPath $state.HbaPath -BackupPath $state.BackupHbaPath -ExpectedSha256 $state.OriginalSha256
                Write-Log "Postgres recovery: restored original authentication policy from $($state.BackupHbaPath) while the service was stopped."
                Write-Host ("  TeknoParrot Manager restored the PostgreSQL file {0} from its safety copy {1}. It still had TeknoParrot Manager's temporary rule 'host all postgres 127.0.0.1/32 trust' from an unfinished password repair. PostgreSQL was stopped while TeknoParrot Manager did this." -f $state.HbaPath, $state.BackupHbaPath) -ForegroundColor Yellow
                Remove-PostgresTrustRuleMarker
                $state.State = 'None'
                $state.Reason = $null
                return $state
            }
        }
        $state.State = 'Required'
        $state.Reason = switch ($state.LiveState) {
            'TemporaryTrust' { 'The temporary PostgreSQL trust rule is still in the live authentication file.' }
            'Original' { 'The authentication file is back to its original content, but PostgreSQL has not been seen stopped since the unfinished repair.' }
            default { 'The authentication file was changed after the unfinished repair started, so TeknoParrot Manager will not overwrite it.' }
        }
    } catch {
        $state.State = 'Error'
        $state.Reason = 'The PostgreSQL recovery marker or authentication file could not be verified: ' + $_.Exception.Message
    } finally {
        if ($lockTaken) { Exit-PostgresRecoveryLock }
    }
    return $state
}

# Plain words for the screen. The exact file names, hashes and steps are in Get-PostgresManualRecoveryTechnicalDetail,
# which callers write to the log (View Log).
function Get-PostgresManualRecoveryDetail {
    $markerState = $script:PostgresTrustRuleMarkerState
    if ($markerState -and $markerState.PSObject.Properties['Busy'] -and $markerState.Busy -eq $true) {
        return 'Another TeknoParrot Manager window is changing PostgreSQL right now. Nothing was changed here. Finish or close the other window, then try again.'
    }
    if ($markerState -and $markerState.State -eq 'Required' -and $markerState.LiveState -eq 'Changed') {
        return 'The PostgreSQL login settings file was changed after an unfinished TeknoParrot Manager password repair started, so TeknoParrot Manager will not overwrite it. Stop PostgreSQL and undo the leftover change by hand. The exact file names and steps are in View Log.'
    }
    if ($markerState -and $markerState.State -eq 'Required') {
        return 'Stop the PostgreSQL service first. TeknoParrot Manager then puts the PostgreSQL login settings file back by itself. If that does not happen, the exact file names and steps are in View Log.'
    }
    if ($markerState -and $markerState.State -eq 'Error') {
        return 'TeknoParrot Manager could not trust the leftover note from an unfinished password repair, so it changed nothing. Do not try the repair again. Stop PostgreSQL and ask for help; the exact file names are in View Log.'
    }
    return 'PostgreSQL recovery is blocked because its durable marker state could not be verified.'
}

function Get-PostgresManualRecoveryTechnicalDetail {
    $markerState = $script:PostgresTrustRuleMarkerState
    if ($markerState -and $markerState.PSObject.Properties['Busy'] -and $markerState.Busy -eq $true) {
        return 'Another TeknoParrot Manager window is changing PostgreSQL right now. Nothing was changed here. Finish or close the other window, then try again.'
    }
    if ($markerState -and $markerState.State -eq 'Required' -and $markerState.LiveState -eq 'Changed') {
        return ('The PostgreSQL file ' + $markerState.HbaPath + ' was changed after an unfinished TeknoParrot Manager password repair started, so TeknoParrot Manager will not overwrite it. To fix it: stop PostgreSQL; open that file and remove the line "host all postgres 127.0.0.1/32 trust" if it is there, or restore the file from ' + $markerState.BackupHbaPath + ' (expected SHA-256 ' + $markerState.OriginalSha256 + '). If you restored that copy, open PostgreSQL setup again while PostgreSQL is stopped; TeknoParrot Manager then removes its recovery marker. If you kept your own changes, delete the recovery marker ' + $markerState.MarkerPath + ' yourself. Then start PostgreSQL again.')
    }
    if ($markerState -and $markerState.State -eq 'Required') {
        return ('Stop the PostgreSQL service first. TeknoParrot Manager clears or restores the authentication file automatically once the service is Stopped. If it is not restored, restore ' + $markerState.HbaPath + ' from ' + $markerState.BackupHbaPath + ' (expected SHA-256 ' + $markerState.OriginalSha256 + '), then check again. Recovery marker: ' + $markerState.MarkerPath + '.')
    }
    if ($markerState -and $markerState.State -eq 'Error') {
        $hbaPath = if ([string]::IsNullOrWhiteSpace([string]$script:PostgresInstallDir)) { 'the configured PostgreSQL data directory\pg_hba.conf' } else { Join-Path $script:PostgresInstallDir 'data\pg_hba.conf' }
        $backupRoot = 'the configured TeknoParrot Manager recovery-backup folder'
        try { $candidateBackupRoot = Get-PostgresRecoveryBackupRoot; if ($candidateBackupRoot) { $backupRoot = $candidateBackupRoot } } catch {}
        return ('TeknoParrot Manager refused to trust or use the PostgreSQL recovery marker ' + $markerState.MarkerPath + '. No automatic authentication-policy restore was attempted. Do not retry password recovery; stop PostgreSQL, manually verify ' + $hbaPath + ' against a trusted backup under ' + $backupRoot + ', then contact support. Detail: ' + $markerState.Reason)
    }
    return 'PostgreSQL recovery is blocked because its durable marker state could not be verified.'
}

function Test-PostgresManualRecoveryRequired {
    $script:PostgresTrustRuleMarkerState = Get-PostgresTrustRuleMarkerState
    $markerState = $script:PostgresTrustRuleMarkerState
    if ($markerState.State -eq 'Required') { return $true }
    if ($markerState.State -eq 'Error') {
        # Same rule as the startup check: with no marker file there is no unfinished password repair to protect, so an
        # unrelated read problem must not block setup or restore with a repair warning.
        $markerPresent = $false
        try { $markerPresent = (-not [string]::IsNullOrWhiteSpace([string]$markerState.MarkerPath)) -and (Test-Path -LiteralPath $markerState.MarkerPath -PathType Leaf) } catch { $markerPresent = $false }
        if ($markerPresent) { return $true }
        Write-Log ('Postgres recovery check: no repair marker exists, so a marker read problem does not block this step. ' + [string]$markerState.Reason)
    }
    return $false
}

# FIX36 B4: read-only startup check for an unfinished PostgreSQL password
# repair. It never removes the marker, restores a file or touches the service;
# it only tells the user plainly. Returns $true when it printed a warning. An
# 'Error' state is reported only when the marker file itself exists.
function Write-PostgresTrustRuleStartupWarning {
    $markerState = Get-PostgresTrustRuleMarkerState -ReadOnly
    $markerPresent = $false
    try { $markerPresent = (-not [string]::IsNullOrWhiteSpace([string]$markerState.MarkerPath)) -and (Test-Path -LiteralPath $markerState.MarkerPath -PathType Leaf) } catch { $markerPresent = $false }
    if ($markerState.State -eq 'None' -or ($markerState.State -eq 'Error' -and -not $markerPresent)) { return $false }
    $script:PostgresTrustRuleMarkerState = $markerState
    Write-Host ''
    Write-Host '  WARNING: an earlier PostgreSQL password repair by TeknoParrot Manager did not finish.' -ForegroundColor Red
    if ($markerState.LiveState -eq 'TemporaryTrust') {
        Write-Host ("  The file {0} still contains TeknoParrot Manager's temporary rule 'host all postgres 127.0.0.1/32 trust'." -f $markerState.HbaPath) -ForegroundColor Red
        Write-Host '  While PostgreSQL runs with that rule, any program on this PC can log in to PostgreSQL as postgres without a password.' -ForegroundColor Red
    }
    Write-Host ('  ' + (Get-PostgresManualRecoveryDetail)) -ForegroundColor Yellow
    Write-Log ('Postgres startup check: ' + (Get-PostgresManualRecoveryTechnicalDetail))
    Write-Host '  TeknoParrot Manager did not change any file, password or service during this check.' -ForegroundColor Yellow
    Write-Log ('Postgres startup check: unfinished password-repair marker found (read-only). State=' + [string]$markerState.State + '; LiveState=' + [string]$markerState.LiveState + '; Marker=' + [string]$markerState.MarkerPath)
    return $true
}

function Set-PostgresHbaPolicyAtomically {
    param([Parameter(Mandatory)][string]$HbaPath, [Parameter(Mandatory)][byte[]]$Bytes, [string]$ExpectedSha256 = '')
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { $bytesHash = [System.BitConverter]::ToString($sha.ComputeHash($Bytes)).Replace('-', '') } finally { $sha.Dispose() }
    if ($ExpectedSha256 -and $bytesHash -ne $ExpectedSha256.ToUpperInvariant()) { throw 'The PostgreSQL authentication policy bytes do not match the expected hash.' }
    Assert-TpmNoReparseWriteTarget -Path $HbaPath -Operation 'PostgreSQL authentication policy replacement'
    $targetAcl = Get-Acl -LiteralPath $HbaPath -ErrorAction Stop
    $directory = Split-Path -Parent $HbaPath
    $temporaryPath = Join-Path $directory ('.' + [System.IO.Path]::GetFileName($HbaPath) + '.' + [guid]::NewGuid().ToString('N') + '.restore.tmp')
    Assert-TpmNoReparseWriteTarget -Path $temporaryPath -Operation 'PostgreSQL authentication policy staging'
    $stream = $null
    try {
        $stream = [System.IO.File]::Open($temporaryPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        $stream.Dispose()
        $stream = $null
        Assert-TpmNoReparseWriteTarget -Path $temporaryPath -Operation 'PostgreSQL authentication policy ACL setup'
        Set-Acl -LiteralPath $temporaryPath -AclObject $targetAcl -ErrorAction Stop
        Assert-TpmNoReparseWriteTarget -Path $temporaryPath -Operation 'PostgreSQL authentication policy staging reopen'
        $stream = [System.IO.File]::Open($temporaryPath, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        $stream.Write($Bytes, 0, $Bytes.Length)
        $stream.Flush($true)
        $stream.Dispose()
        $stream = $null
        if ((Get-FileHash -LiteralPath $temporaryPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant() -ne $bytesHash) { throw 'The staged PostgreSQL authentication policy does not match its expected hash.' }
        Assert-TpmNoReparseWriteTarget -Path $temporaryPath -Operation 'PostgreSQL authentication policy promotion'
        Assert-TpmNoReparseWriteTarget -Path $HbaPath -Operation 'PostgreSQL authentication policy replacement'
        [System.IO.File]::Replace($temporaryPath, $HbaPath, [NullString]::Value)
        if ((Get-FileHash -LiteralPath $HbaPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant() -ne $bytesHash) { throw 'The replaced PostgreSQL authentication policy could not be verified.' }
    } finally {
        if ($stream) { $stream.Dispose() }
        if (Test-Path -LiteralPath $temporaryPath -PathType Leaf) { Remove-Item -LiteralPath $temporaryPath -Force -ErrorAction SilentlyContinue }
    }
}

function Restore-PostgresHbaFromBackup {
    param([Parameter(Mandatory)][string]$HbaPath, [Parameter(Mandatory)][string]$BackupPath, [Parameter(Mandatory)][string]$ExpectedSha256)
    if (-not (Test-Path -LiteralPath $BackupPath -PathType Leaf)) { throw 'The PostgreSQL authentication backup is missing.' }
    $expected = $ExpectedSha256.ToUpperInvariant()
    Assert-TpmNoReparseWriteTarget -Path $BackupPath -Operation 'read PostgreSQL authentication recovery evidence'
    Assert-PostgresRecoveryFileAcl -Path $BackupPath
    $backupBytes = [System.IO.File]::ReadAllBytes($BackupPath)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { $backupHash = [System.BitConverter]::ToString($sha.ComputeHash($backupBytes)).Replace('-', '') } finally { $sha.Dispose() }
    if ($backupHash -ne $expected) { throw 'The PostgreSQL authentication backup does not match its recorded hash.' }
    Set-PostgresHbaPolicyAtomically -HbaPath $HbaPath -Bytes $backupBytes -ExpectedSha256 $expected
}

function Restore-PostgresProfileBackups {
    param(
        [Parameter(Mandatory)]$RecoveryBackup,
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$ProfileSourcePaths
    )
    $requestedProfileSources = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($sourcePath in $ProfileSourcePaths) {
        if ([string]::IsNullOrWhiteSpace($sourcePath)) { throw 'PostgreSQL profile rollback source list contains an empty path.' }
        [void]$requestedProfileSources.Add([System.IO.Path]::GetFullPath($sourcePath))
    }
    $items = @($RecoveryBackup.ProfileBackups | Where-Object {
        $backupSource = [string]$_.Source
        if ([string]::IsNullOrWhiteSpace($backupSource)) { $false }
        else { $requestedProfileSources.Contains([System.IO.Path]::GetFullPath($backupSource)) }
    } | Sort-Object Source)
    if ($items.Count -ne $requestedProfileSources.Count) { throw 'PostgreSQL recovery evidence is missing an attempted profile backup.' }
    $started = Get-Date
    $current = 0
    $rollbackOutcome = 'Error'
    $rollbackSucceeded = $false
    try {
        $preflightCurrent = 0
        foreach ($item in $items) {
            $preflightCurrent++
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'PostgreSQL profile rollback preflight' -Current $preflightCurrent -Total $items.Count -StartedAt $started
            $backupPath = [string]$item.Backup
            $expectedHash = [string]$item.Sha256
            $sourcePath = [string]$item.Source
            if ([string]::IsNullOrWhiteSpace($expectedHash)) { throw 'PostgreSQL profile recovery evidence has no recorded hash.' }
            if ([string]::IsNullOrWhiteSpace($sourcePath)) { throw 'PostgreSQL profile recovery evidence has no destination path.' }
            Assert-TpmNoReparseWriteTarget -Path $backupPath -Operation 'read PostgreSQL profile recovery evidence'
            Assert-PostgresRecoveryFileAcl -Path $backupPath
            $backupHash = (Get-FileHash -LiteralPath $backupPath -Algorithm SHA256 -ErrorAction Stop).Hash
            if ($backupHash -ne $expectedHash) { throw 'Postgres profile recovery backup does not match its recorded hash.' }
            Assert-TpmNoReparseWriteTarget -Path $sourcePath -Operation 'write PostgreSQL profile rollback'
            if ((Test-Path -LiteralPath $sourcePath -ErrorAction Stop) -and
                -not (Test-Path -LiteralPath $sourcePath -PathType Leaf -ErrorAction Stop)) {
                throw 'PostgreSQL profile rollback destination is not a file.'
            }
        }
        $current = 0
        foreach ($item in $items) {
            $current++
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'PostgreSQL profile rollback' -Current $current -Total $items.Count -StartedAt $started
            $backupPath = [string]$item.Backup
            $expectedHash = [string]$item.Sha256
            $sourcePath = [string]$item.Source
            Assert-TpmNoReparseWriteTarget -Path $backupPath -Operation 'read PostgreSQL profile recovery evidence'
            Assert-PostgresRecoveryFileAcl -Path $backupPath
            $backupHash = (Get-FileHash -LiteralPath $backupPath -Algorithm SHA256 -ErrorAction Stop).Hash
            if ($backupHash -ne $expectedHash) { throw 'Postgres profile recovery backup does not match its recorded hash.' }
            Assert-TpmNoReparseWriteTarget -Path $sourcePath -Operation 'write PostgreSQL profile rollback'
            if ((Test-Path -LiteralPath $sourcePath -ErrorAction Stop) -and
                -not (Test-Path -LiteralPath $sourcePath -PathType Leaf -ErrorAction Stop)) {
                throw 'PostgreSQL profile rollback destination is not a file.'
            }
            Copy-Item -LiteralPath $backupPath -Destination $sourcePath -Force -ErrorAction Stop
            $sourceHash = (Get-FileHash -LiteralPath $sourcePath -Algorithm SHA256 -ErrorAction Stop).Hash
            if ($sourceHash -ne $expectedHash) { throw 'Postgres profile rollback hash verification failed.' }
        }
        $rollbackSucceeded = $true
    } catch {
        $caughtException = $_.Exception
        $pipelineStopped = $false
        while ($null -ne $caughtException) {
            if ($caughtException -is [System.Management.Automation.PipelineStoppedException]) { $pipelineStopped = $true; break }
            $caughtException = $caughtException.InnerException
        }
        if ($pipelineStopped) { $rollbackOutcome = 'Cancelled' }
        throw
    } finally {
        if ($items.Count -gt 0) {
            if ($rollbackSucceeded) { $rollbackOutcome = 'Final' }
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'PostgreSQL profile rollback' -Current $current -Total $items.Count -StartedAt $started -Complete -Outcome $rollbackOutcome
        }
    }
    return $true
}

# FIX36B S7: one machine-wide lock for the steps that change PostgreSQL's
# authentication file: the automatic marker clear or restore (and, in builds
# before FIX95, the password reset; the name is unchanged so an older window
# still shares it). A second TPM window (or elevated child) that finds the lock taken
# changes nothing and says so. The lock is re-entrant inside one TPM process. A lock left by a killed TPM is taken over;
# the trust-rule marker then decides what is safe. If the lock object cannot be
# opened (for example access denied because an elevated TPM holds it), TPM
# treats it as taken. The name is per PostgreSQL install folder (the
# pg_hba.conf it protects), so every TPM copy on this PC that manages the same
# PostgreSQL shares one lock. Tests can override it through
# $script:PostgresRecoveryLockName.
function Get-PostgresRecoveryLockName {
    $custom = Get-Variable -Name PostgresRecoveryLockName -Scope Script -ValueOnly -ErrorAction SilentlyContinue
    if (-not [string]::IsNullOrWhiteSpace([string]$custom)) { return [string]$custom }
    $baseName = 'Global\TeknoParrotManager.PostgresPasswordRepair'
    $installDir = [string]$script:PostgresInstallDir
    if ([string]::IsNullOrWhiteSpace($installDir)) { return $baseName }
    try {
        $key = [System.IO.Path]::GetFullPath($installDir).TrimEnd('\', '/').ToUpperInvariant()
        $sha = [System.Security.Cryptography.SHA256]::Create()
        try { $digest = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($key)) } finally { $sha.Dispose() }
        return ($baseName + '.' + [System.BitConverter]::ToString($digest, 0, 8).Replace('-', ''))
    } catch {
        return $baseName
    }
}

function Enter-PostgresRecoveryLock {
    $held = Get-Variable -Name PostgresRecoveryLockHeld -Scope Script -ValueOnly -ErrorAction SilentlyContinue
    if ($null -ne $held -and [int]$held.Depth -gt 0) {
        $held.Depth = [int]$held.Depth + 1
        return $true
    }
    $mutex = $null
    try {
        $mutex = New-Object System.Threading.Mutex($false, (Get-PostgresRecoveryLockName))
    } catch {
        Write-Log 'Postgres repair lock: the lock could not be opened; another TeknoParrot Manager process is probably changing PostgreSQL.'
        return $false
    }
    $acquired = $false
    try {
        $acquired = [bool]$mutex.WaitOne([TimeSpan]::FromSeconds(2))
    } catch {
        # A lock whose holder ended without releasing it is owned by this caller now.
        $exception = $_.Exception
        while ($null -ne $exception) {
            if ($exception -is [System.Threading.AbandonedMutexException]) { $acquired = $true; break }
            $exception = $exception.InnerException
        }
        if ($acquired) { Write-Log 'Postgres repair lock: an earlier TeknoParrot Manager process ended while holding the lock; this process took it over.' }
    }
    if (-not $acquired) {
        $mutex.Dispose()
        return $false
    }
    $script:PostgresRecoveryLockHeld = [pscustomobject]@{ Mutex = $mutex; Depth = 1 }
    return $true
}

function Exit-PostgresRecoveryLock {
    $held = Get-Variable -Name PostgresRecoveryLockHeld -Scope Script -ValueOnly -ErrorAction SilentlyContinue
    if ($null -eq $held -or [int]$held.Depth -le 0) { return }
    $held.Depth = [int]$held.Depth - 1
    if ([int]$held.Depth -gt 0) { return }
    $script:PostgresRecoveryLockHeld = $null
    try { $held.Mutex.ReleaseMutex() } catch { Write-Log 'Postgres repair lock: the lock could not be released cleanly; Windows releases it when TeknoParrot Manager exits.' } finally { $held.Mutex.Dispose() }
}

# FIX36 B4: never start PostgreSQL while a trust-rule marker exists (any
# state other than None, checked read-only so this gate itself changes no
# file). Since FIX95 no TeknoParrot Manager step writes that rule; the gate
# still covers a marker left by an older build's interrupted reset. Stopping is still
# allowed: it only reduces exposure.
function Restore-PostgresServiceState {
    param([object]$WasRunning)
    $script:PostgresServiceStartRefusedByMarker = $false
    if ($null -eq $WasRunning) { return $true }
    try {
        $service = Get-Service -Name $script:PostgresServiceName -ErrorAction Stop
        $running = ([string]$service.Status -ne 'Stopped')
        if ([bool]$WasRunning -and -not $running) {
            $startGateState = Get-PostgresTrustRuleMarkerState -ReadOnly
            if ([string]$startGateState.State -ne 'None') {
                $script:PostgresTrustRuleMarkerState = $startGateState
                $script:PostgresServiceStartRefusedByMarker = $true
                Write-Log 'Postgres recovery: PostgreSQL was not started because the temporary trust-rule marker shows an unfinished repair.'
                return $false
            }
            Start-Service -Name $script:PostgresServiceName -ErrorAction Stop
            Wait-PostgresServiceState -DesiredStatus 'Running' | Out-Null
        } elseif (-not [bool]$WasRunning -and $running) {
            Stop-Service -Name $script:PostgresServiceName -Force -ErrorAction Stop
            Wait-PostgresServiceState -DesiredStatus 'Stopped' | Out-Null
        }
        return $true
    } catch {
        Write-Log 'Postgres recovery: original service state could not be restored.'
        return $false
    }
}
# =============================================================================
# GPU Fix Setup: detect GPU vendor, scan TeknoParrot GameProfiles for fix
# fields (so newly added games are covered automatically), and apply the
# appropriate values to every registered UserProfile XML.
function Invoke-GpuFixSetup {
    param([string]$UserProfilesDir,[string]$TpRoot)
    $legacy=Invoke-GpuFixSetupLegacy -UserProfilesDir $UserProfilesDir -TpRoot $TpRoot
    $legacyCancelled = ($null -eq $legacy)
    if ($legacyCancelled) { $legacy=[pscustomobject]@{ Succeeded=$false; Cancelled=$true; Updated=0; Unchanged=0; Skipped=0; Errors=0; SkipDetails=@(); Reason='CANCELLED'; Backup=$null } }
    $legacyBackup=Get-TpmTransactionField -Object $legacy -Name 'Backup'
    $items=@(Get-TpmTransactionField -Object $legacy -Name 'SelectedItems' -Default @())
    $changed=@(Get-TpmTransactionField -Object $legacy -Name 'ChangedItems' -Default @() | Where-Object { $_ -in $items } | Select-Object -Unique)
    $skipped=@(Get-TpmTransactionField -Object $legacy -Name 'SkippedItems' -Default @() | Where-Object { $_ -in $items -and $_ -notin $changed } | Select-Object -Unique)
    $failed=@(Get-TpmTransactionField -Object $legacy -Name 'FailedItems' -Default @() | Where-Object { $_ -in $items -and $_ -notin $changed -and $_ -notin $skipped } | Select-Object -Unique)
    $unknown=@(Get-TpmTransactionField -Object $legacy -Name 'UnknownItems' -Default @() | Where-Object { $_ -in $items -and $_ -notin $changed -and $_ -notin $skipped -and $_ -notin $failed } | Select-Object -Unique)
    $completed=@(Get-TpmTransactionField -Object $legacy -Name 'CompletedItems' -Default @() | Where-Object { $_ -in $items -and $_ -notin $failed -and $_ -notin $skipped -and $_ -notin $unknown } | Select-Object -Unique)
    $unattempted=@(Get-TpmTransactionField -Object $legacy -Name 'UnattemptedItems' -Default @() | Where-Object { $_ -in $items -and $_ -notin $completed -and $_ -notin $failed -and $_ -notin $skipped -and $_ -notin $unknown } | Select-Object -Unique)
    $outcome=if($unknown.Count -gt 0){'ACTION_REQUIRED'}elseif($changed.Count -gt 0 -and ($failed.Count -gt 0 -or $skipped.Count -gt 0 -or $unattempted.Count -gt 0)){'PARTIAL_APPLIED'}elseif($changed.Count -gt 0){'SUCCEEDED'}elseif($failed.Count -gt 0 -or $skipped.Count -gt 0 -or [int]$legacy.Errors -gt 0){'FAILED_BEFORE_MUTATION'}else{'NO_OP'}
    $productState=switch($outcome){'SUCCEEDED'{'INTENDED'}'PARTIAL_APPLIED'{'PARTIAL_KNOWN'}'ACTION_REQUIRED'{'UNKNOWN'}default{'UNCHANGED'}}
    $legacyBackupVerified=[bool](Get-TpmTransactionField -Object $legacyBackup -Name 'Verified' -Default $false)
    $legacyReason=Get-TpmTransactionField -Object $legacy -Name 'Reason' -Default $null
    $cancelled=[bool]$legacyCancelled
    $reasonCode=if($cancelled){'USER_CANCELLED'}elseif($unknown.Count -gt 0){'PROFILE_WRITE_STATE_UNKNOWN'}elseif($outcome -eq 'NO_OP'){'NO_CHANGES_NEEDED'}elseif($outcome -eq 'FAILED_BEFORE_MUTATION' -and -not $legacyReason -and $failed.Count -eq 0 -and [int]$legacy.Errors -eq 0 -and $skipped.Count -gt 0){'SOME_GAMES_NOT_CHANGED'}elseif($outcome -eq 'FAILED_BEFORE_MUTATION' -and $legacyReason){[string]$legacyReason}elseif($outcome -eq 'FAILED_BEFORE_MUTATION' -and $legacyBackupVerified){'PROFILE_BACKUP_COMPLETED_NO_WRITE'}elseif($outcome -eq 'FAILED_BEFORE_MUTATION' -and $failed.Count -gt 0){'PROFILE_PROCESSING_FAILED'}elseif($outcome -eq 'FAILED_BEFORE_MUTATION'){'PROFILE_SKIPPED'}else{'GPU_FIELDS_PROCESSED'}
    $discoveryFailed=($legacyReason -in @('GAMEPROFILE_DISCOVERY_FAILED','PROFILE_DISCOVERY_FAILED'))
    $summary=if($cancelled){'GPU compatibility setup was canceled before profile changes.'}elseif($discoveryFailed){'GPU compatibility setup stopped before any profile was processed.'}else{'GPU compatibility fields were processed with per-game outcomes.'}
    $finalChecks=if($cancelled){@('GPU vendor selection was canceled before profile discovery; no profile mutation was attempted.')}elseif($discoveryFailed){@('Discovery failed before any profile was read; no profile mutation was attempted.')}else{@('Per-game write outcomes were recorded; unresolved writes remain unknown.')}
    $tx=New-TpmProfileTransactionResult -WorkflowKey 'GPUFix' -OperationKey 'ApplyProfileFields' -Outcome $outcome -ProductState $productState -Summary $summary -Items $items -ChangedItems $changed -CompletedItems $completed -FailedItems $failed -SkippedItems $skipped -UnknownItems $unknown -UnattemptedItems $unattempted -MutationStarted ($changed.Count -gt 0 -or $unknown.Count -gt 0) -MutationCompleted:($outcome -in @('SUCCEEDED','NO_OP')) -Backup $legacyBackup -FinalAttempted ($unknown.Count -eq 0) -FinalPassed ($unknown.Count -eq 0) -ReasonCode $reasonCode -FinalChecks $finalChecks -TechnicalDetails $legacy
    foreach($property in @($legacy.PSObject.Properties.Name)) {
        $legacyProperty=$legacy.PSObject.Properties[$property]
        if ($legacyProperty -and -not $tx.PSObject.Properties[$property]) { $tx | Add-Member -NotePropertyName $property -NotePropertyValue $legacyProperty.Value -Force }
    }
    $tx | Add-Member -NotePropertyName Succeeded -NotePropertyValue ($tx.Outcome -in @('SUCCEEDED','NO_OP')) -Force
    $tx | Add-Member -NotePropertyName BackupSucceeded -NotePropertyValue $legacyBackupVerified -Force
    $tx | Add-Member -NotePropertyName EnabledCodes -NotePropertyValue @($items) -Force
    $tx | Add-Member -NotePropertyName Reason -NotePropertyValue $reasonCode -Force
    $tx | Add-Member -NotePropertyName Errors -NotePropertyValue ([int]$legacy.Errors) -Force
    return $tx
}
function Invoke-GpuFixSetupLegacy {
    param(
        [string]$UserProfilesDir,
        [string]$TpRoot
    )

    # -- GPU detection ----------------------------------------------------------
    Write-Host ""
    Write-Host "  Detecting GPU..." -ForegroundColor DarkGray
    $detected  = Get-DetectedGpuVendor
    $gpuVendor = $detected.Vendor
    $gpuName   = $detected.Name

    if ($gpuVendor) {
        Write-Host ("  Detected : {0} ({1})" -f $gpuVendor, $gpuName) -ForegroundColor DarkGray
        Write-Log "GPU Fix: detected $gpuVendor ($gpuName)"
    } else {
        $gpuVendor = Read-TpmGpuVendorChoice -AdapterName $gpuName
        if (-not $gpuVendor) { return }
    }

    # -- Discover GPU fix field names from TeknoParrot GameProfiles -------------
    # Scans at runtime so newly added games with new fix fields are covered
    # automatically without requiring a script update.
    Write-Host "  Checking which games have a GPU fix..." -ForegroundColor DarkGray
    try {
        $gpuFields = Get-GpuFixFieldNames -TpRoot $TpRoot
    } catch {
        Write-Host ('  GPU Fix GameProfiles discovery failed; no changes made: {0}' -f $_.Exception.Message) -ForegroundColor Red
        Write-Log ('GPU Fix: GameProfiles discovery failed; no changes made: {0}' -f $_.Exception.Message)
        return [pscustomobject]@{ Succeeded=$false; Updated=0; Unchanged=0; Skipped=0; Errors=1; SkipDetails=@(); Reason='GAMEPROFILE_DISCOVERY_FAILED'; Backup=$null }
    }
    $boolAmdFields     = $gpuFields.BoolFields
    $dropdownGpuFields = $gpuFields.DropdownFields
    if ($gpuFields.GameProfilesFound) {
        Write-Log ("GPU Fix: discovered fields -- Bool AMD: [{0}]  Dropdown GPU: [{1}]" -f `
            ($boolAmdFields -join ', '), ($dropdownGpuFields -join ', '))
    } else {
        Write-Log "GPU Fix: GameProfiles not found -- using fallback field list."
    }

    # Candidate identity and its single authoritative file enumeration are fixed
    # before backup and mutation. Directories and FullBackup are never candidates.
    try {
        $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'GPU Fix profile discovery' -EnumerationErrorAction Stop)
    } catch {
        Write-Host ('  GPU Fix profile discovery failed; no changes made: {0}' -f $_.Exception.Message) -ForegroundColor Red
        Write-Log ('GPU Fix: profile discovery failed; no changes made: {0}' -f $_.Exception.Message)
        return [pscustomobject]@{ Succeeded=$false; Updated=0; Unchanged=0; Skipped=0; Errors=1; SkipDetails=@(); Reason='PROFILE_DISCOVERY_FAILED'; Backup=$null }
    }
    $selectedItems = @($profiles | ForEach-Object { [string]$_.BaseName })
    $changedItems = New-Object System.Collections.Generic.List[string]
    $completedItems = New-Object System.Collections.Generic.List[string]
    $failedItems = New-Object System.Collections.Generic.List[string]
    $skippedItems = New-Object System.Collections.Generic.List[string]
    $unknownItems = New-Object System.Collections.Generic.List[string]
    $failureRecords = New-Object System.Collections.Generic.List[object]
    $skipDetails = New-Object System.Collections.Generic.List[object]

    # Create and verify a backup immediately before the first actual XML write.
    # An already-correct run is a true NO_OP and must not mutate backup state.
    $backup = $null
    $backupPath = $null
    $backupAttempted = $false
    $backupVerified = $false
    $unattemptedItems = New-Object System.Collections.Generic.List[string]
    $reason = $null

    # -- Walk UserProfiles ------------------------------------------------------
    Write-Host ""
    Write-Host "  Applying the GPU fix to your games..." -ForegroundColor DarkGray
    $updated    = 0
    $unchanged  = 0
    $notApplicable = 0
    $notApplicableItems = New-Object System.Collections.Generic.List[string]
    $skipped    = 0
    $missingDevice = 0
    $missingPath = 0
    $errors     = 0
    $gpuProgressStarted = Get-Date
    $gpuProgressCurrent = 0
    foreach ($pf in $profiles) {
        $writeAttempted=$false
        $itemCompleted=$false
        $registeredGamePath=''
        try {
        $gpuProgressCurrent++
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'GPU Fix' -Current $gpuProgressCurrent -Total $profiles.Count -StartedAt $gpuProgressStarted
            $doc    = Read-Xml $pf.FullName
            $gpuPathNode = if ($doc.GameProfile) { $doc.GameProfile.SelectSingleNode('GamePath') } else { $null }
            $registeredGamePath = if ($gpuPathNode) { [string]$gpuPathNode.InnerText } else { '' }
            $gpuPathCheck = Test-TpmGameMutationPath -GamePath $registeredGamePath -RequireLeaf
            if (-not $gpuPathCheck.Valid) {
                $skipped++
                [void]$skippedItems.Add($pf.BaseName)
                if ($gpuPathCheck.ReasonCode -eq 'DEVICE_UNAVAILABLE') { $missingDevice++ }
                if ($gpuPathCheck.ReasonCode -eq 'GAME_PATH_MISSING') { $missingPath++ }
                $skipReason = switch ([string]$gpuPathCheck.ReasonCode) {
                    'DEVICE_UNAVAILABLE' { 'The saved game drive or device is unavailable.' }
                    'GAME_PATH_MISSING'  { 'TeknoParrot Manager has a saved location for this game, but Windows cannot find the game file right now.' }
                    'EMPTY_PATH'         { 'This game has no saved game location.' }
                    default              { 'TeknoParrot Manager cannot safely use the saved game location for this game.' }
                }
                $nextAction = if ($gpuPathCheck.ReasonCode -eq 'DEVICE_UNAVAILABLE') { 'Reconnect the drive or device, then choose 13) Library Health Check to repair saved game paths.' } else { 'Return to the main menu and choose 13) Library Health Check to repair saved game paths.' }
                [void]$skipDetails.Add([pscustomobject]@{ Game = $pf.BaseName; ReasonKey = $gpuPathCheck.ReasonCode; Reason = $skipReason; SavedPath = $registeredGamePath; NextAction = $nextAction; Technical = [string]$gpuPathCheck.Reason })
                Write-Log ("GPU Fix: skipped {0}; path reason={1}; detail={2}" -f $pf.BaseName, $gpuPathCheck.ReasonCode, $gpuPathCheck.Reason)
                continue
            }
            $result = Test-GpuFixUpToDate -Doc $doc -BoolFields $boolAmdFields -DropdownFields $dropdownGpuFields -Vendor $gpuVendor

            if ($result.Changes.Count -gt 0) {
                $boundaryCheck = Test-TpmGameMutationPath -GamePath ([string]$gpuPathCheck.ResolvedPath) -RequireLeaf
                if (-not $boundaryCheck.Valid -or [string]$boundaryCheck.ResolvedPath -ine [string]$gpuPathCheck.ResolvedPath) {
                    $skipped++
                    [void]$skippedItems.Add($pf.BaseName)
                    if ($boundaryCheck.ReasonCode -eq 'DEVICE_UNAVAILABLE') { $missingDevice++ }
                    [void]$skipDetails.Add([pscustomobject]@{ Game = $pf.BaseName; ReasonKey = $boundaryCheck.ReasonCode; Reason = 'The registered game path changed or became unavailable before the safe write.'; SavedPath = $registeredGamePath; NextAction = 'Return to the main menu and choose 13) Library Health Check to repair saved game paths.'; Technical = [string]$boundaryCheck.ReasonCode })
                    if ($boundaryCheck.ReasonCode -eq 'GAME_PATH_MISSING') { $missingPath++ }
                    Write-Log ("GPU Fix: mutation-boundary path check failed for {0}; reason={1}" -f $pf.BaseName, $boundaryCheck.ReasonCode)
                    continue
                }
                if (-not $backupAttempted) {
                    $backupAttempted = $true
                    # Retain an attempted-but-unverified record if the helper throws
                    # before returning its detailed backup result.
                    $backup = [pscustomobject]@{ Required=$true; Attempted=$true; Created=$false; Verified=$false; Path=$null; Reason=$null; Manifest=@() }
                    $backupResult = New-TpmVerifiedUserProfilesBackup -UserProfilesDir $UserProfilesDir -Label 'GpuFix'
                    if ($null -eq $backupResult) { throw 'The verified UserProfiles backup helper returned no result.' }
                    $backup = $backupResult
                    $backup | Add-Member -NotePropertyName Attempted -NotePropertyValue $true -Force
                    $backupPath = [string]$backup.Path
                    if ([string]::IsNullOrWhiteSpace($backupPath)) {
                        $backup | Add-Member -NotePropertyName Verified -NotePropertyValue $false -Force
                        $backup | Add-Member -NotePropertyName Succeeded -NotePropertyValue $false -Force
                        $backup | Add-Member -NotePropertyName Reason -NotePropertyValue 'Verified backup result did not include a recovery path.' -Force
                        throw 'The verified backup result did not include a recovery path.'
                    }
                    $backupVerified = [bool]$backup.Verified
                    if (-not $backupVerified) {
                        $backupReason = [string](Get-TpmTransactionField -Object $backup -Name 'Reason' -Default 'Backup verification failed.')
                        if ([string]::IsNullOrWhiteSpace($backupReason)) { $backupReason = 'Backup verification failed.' }
                        throw ("The safety backup could not be verified: {0}" -f $backupReason)
                    }
                    Write-Log "GPU Fix: verified backup at $backupPath"
                }
                $writeBoundaryCheck = Test-TpmGameMutationPath -GamePath ([string]$gpuPathCheck.ResolvedPath) -RequireLeaf
                if (-not $writeBoundaryCheck.Valid -or [string]$writeBoundaryCheck.ResolvedPath -ine [string]$gpuPathCheck.ResolvedPath) {
                    $skipped++
                    [void]$skippedItems.Add($pf.BaseName)
                    if ($writeBoundaryCheck.ReasonCode -eq 'DEVICE_UNAVAILABLE') { $missingDevice++ }
                    if ($writeBoundaryCheck.ReasonCode -eq 'GAME_PATH_MISSING') { $missingPath++ }
                    [void]$skipDetails.Add([pscustomobject]@{ Game = $pf.BaseName; ReasonKey = $writeBoundaryCheck.ReasonCode; Reason = 'The registered game path changed or became unavailable while the backup was being verified.'; SavedPath = $registeredGamePath; NextAction = 'Return to the main menu and choose 13) Library Health Check to repair saved game paths.'; Technical = [string]$writeBoundaryCheck.ReasonCode })
                    Write-Log ("GPU Fix: post-backup mutation-boundary path check failed for {0}; reason={1}" -f $pf.BaseName, $writeBoundaryCheck.ReasonCode)
                    continue
                }
                $doc = Read-Xml $pf.FullName
                $result = Test-GpuFixUpToDate -Doc $doc -BoolFields $boolAmdFields -DropdownFields $dropdownGpuFields -Vendor $gpuVendor
                if ($result.Changes.Count -eq 0) {
                    # Already correct is only true when the GPU settings are still there. If they vanished, an outside save changed the profile and that is a failure, for every game, not only the first.
                    if ($updated -eq 0 -or -not $result.Eligible) {
                        $errors++
                        $reason = 'PROFILE_CHANGED_DURING_BACKUP'
                        [void]$failedItems.Add($pf.BaseName)
                        $recheckDetail = if ($result.Eligible) { 'The profile no longer required a change after the verified backup was created.' } else { 'The profile no longer has the GPU settings after the verified backup was created.' }
                        [void]$failureRecords.Add([pscustomobject]@{ Game=$pf.BaseName; Operation='backup boundary recheck'; ReasonKey=$reason; Exception=$recheckDetail; EvidencePreserved=$true; BackupPath=$backupPath; NextAction='Review the current profile state and run GPU Fix again if a change is still needed.' })
                        Write-Log ("GPU Fix: profile {0} became current between preflight and the verified backup boundary." -f $pf.BaseName)
                    } else {
                        [void]$completedItems.Add($pf.BaseName)
                        $unchanged++
                        $itemCompleted = $true
                    }
                    continue
                }
                foreach ($c in $result.Changes) {
                    $c.Node.InnerText = $c.NewValue
                    Write-Log "GPU Fix: $($pf.BaseName) :: $($c.FieldName) $($c.OldValue) -> $($c.NewValue)"
                }
                if (-not $backupAttempted -or -not $backupVerified) { throw 'GPU Fix refused to write without a verified batch backup.' }
                $writeAttempted=$true
                Save-Xml $doc $pf.FullName
                [void]$changedItems.Add($pf.BaseName)
                [void]$completedItems.Add($pf.BaseName)
                $updated++
                $writeAttempted=$false
                $itemCompleted=$true
            } else {
                [void]$completedItems.Add($pf.BaseName)
                if ($result.Eligible) { $unchanged++ } else { $notApplicable++; [void]$notApplicableItems.Add($pf.BaseName) }
                $itemCompleted=$true
            }
        } catch {
            if ($backupAttempted -and -not $backupVerified) {
                # The backup gate is batch-wide. Mark outcomes before best-effort
                # reporting, then stop even if backup creation or logging threw.
                $reason = 'PROFILE_BACKUP_FAILED'
                $errors++
                if ($pf.BaseName -notin $completedItems -and $pf.BaseName -notin $failedItems -and $pf.BaseName -notin $skippedItems -and $pf.BaseName -notin $unknownItems -and $pf.BaseName -notin $unattemptedItems) {
                    [void]$failedItems.Add($pf.BaseName)
                }
                $backupDetail = [string]$_.Exception.Message
                try {
                    $reportedBackupReason = [string](Get-TpmTransactionField -Object $backup -Name 'Reason' -Default '')
                    if (-not [string]::IsNullOrWhiteSpace($reportedBackupReason)) { $backupDetail = $reportedBackupReason }
                } catch { }
                if ([string]::IsNullOrWhiteSpace($backupDetail)) { $backupDetail = 'Backup creation or verification failed before a verified result was available.' }
                [void]$failureRecords.Add([pscustomobject]@{ Game=$pf.BaseName; Operation='verified backup'; ReasonKey='PROFILE_BACKUP_FAILED'; Exception=$backupDetail; EvidencePreserved=$false; BackupPath=$backupPath; NextAction='Review the backup failure and retry GPU Fix only after a verified backup can be created.' })
                foreach ($remainingProfile in $profiles) {
                    $remainingCode = [string]$remainingProfile.BaseName
                    if ($remainingCode -ne [string]$pf.BaseName -and $remainingCode -notin $completedItems -and $remainingCode -notin $failedItems -and $remainingCode -notin $skippedItems -and $remainingCode -notin $unknownItems -and $remainingCode -notin $unattemptedItems) {
                        [void]$unattemptedItems.Add($remainingCode)
                    }
                }
                try { Write-Host '  ERROR: The safety backup could not be verified. GPU Fix stopped before writing any profile.' -ForegroundColor Red } catch { }
                try { Write-Log ("GPU Fix: verified backup failed -- {0}" -f $backupDetail) } catch { }
                break
            } elseif ($itemCompleted) {
                Write-Log ("GPU Fix: output failed after the profile result was recorded for {0}; result remains unchanged." -f $pf.BaseName)
            } elseif ($writeAttempted) {
                [void]$unknownItems.Add($pf.BaseName)
                $errors++
                $failureRecord=[pscustomobject]@{ Game=$pf.BaseName; Operation='profile write'; ReasonKey='WRITE_STATE_UNKNOWN'; Exception=[string]$_.Exception.Message; EvidencePreserved=[bool]$backup.Verified; BackupPath=$backupPath; NextAction='Restore this profile from the verified GPU Fix backup before retrying.' }
                [void]$failureRecords.Add($failureRecord)
                Write-Host ("    ACTION REQUIRED {0}: profile write state could not be verified; restore from the verified backup before retrying." -f $pf.BaseName) -ForegroundColor Yellow
                Write-Log ("GPU Fix: write state is unknown for {0}; verified backup={1}; detail={2}" -f $pf.BaseName, $backupPath, $_)
            } else {
                $failureCode = Get-TpmGameMutationFailureCode -ErrorRecord $_
                if ($failureCode -eq 'DEVICE_UNAVAILABLE' -or $failureCode -eq 'GAME_PATH_MISSING') {
                    $skipped++
                    [void]$skippedItems.Add($pf.BaseName)
                    if ($failureCode -eq 'DEVICE_UNAVAILABLE') { $missingDevice++ } else { $missingPath++ }
                    $catchReason = if ($failureCode -eq 'DEVICE_UNAVAILABLE') { 'The saved game drive or device is unavailable.' } else { 'TeknoParrot Manager could not find the saved game file.' }
                    [void]$skipDetails.Add([pscustomobject]@{ Game = $pf.BaseName; ReasonKey=$failureCode; Reason = $catchReason; SavedPath = $registeredGamePath; NextAction = 'Return to the main menu and choose 13) Library Health Check to repair saved game paths.'; Technical = [string]$_.Exception.Message })
                    Write-Log ("GPU Fix: skipped {0} after mutation failure; path reason={1}; detail={2}" -f $pf.BaseName, $failureCode, $_)
                } else {
                    [void]$failedItems.Add($pf.BaseName)
                    $errors++
                    $failureRecord=[pscustomobject]@{ Game=$pf.BaseName; Operation='profile processing'; ReasonKey='PROFILE_PROCESSING_FAILED'; Exception=[string]$_.Exception.Message; EvidencePreserved=[bool]$backup.Verified; BackupPath=$backupPath; NextAction='Review the failure details and verified backup before retrying.' }
                    [void]$failureRecords.Add($failureRecord)
                    Write-Host ("    FAILED {0}: the profile was not updated; see Details." -f $pf.BaseName) -ForegroundColor Red
                    Write-Log "GPU Fix: FAILED $($pf.BaseName) -- $_"
                }
            }
        }
    }
    Write-TpmCompactExtractionProgress -Phase Checking -Label 'GPU Fix' -Current $gpuProgressCurrent -Total $profiles.Count -StartedAt $gpuProgressStarted -Complete -Outcome $(if ($errors -gt 0) { 'Error' } else { 'Final' })
    Write-Log ("GPU Fix: complete. Vendor={0} Updated={1} Unchanged={2} Skipped={3} MissingDevice={4} MissingPath={5} Errors={6}" -f `
        $gpuVendor, $updated, $unchanged, $skipped, $missingDevice, $missingPath, $errors)
    return [pscustomobject]@{ Succeeded = ($errors -eq 0 -and $skipped -eq 0); GpuName = $gpuName; GpuVendor = $gpuVendor; Updated = $updated; Unchanged = $unchanged; NotApplicable = $notApplicable; NotApplicableItems = @($notApplicableItems.ToArray()); Skipped = $skipped; MissingDevice = $missingDevice; MissingPath = $missingPath; Errors = $errors; SkipDetails = $skipDetails.ToArray(); FailureRecords=@($failureRecords.ToArray()); Backup = $backup; Reason=$reason; SelectedItems=$selectedItems; ChangedItems=@($changedItems.ToArray()); CompletedItems=@($completedItems.ToArray()); FailedItems=@($failedItems.ToArray()); SkippedItems=@($skippedItems.ToArray()); UnattemptedItems=@($unattemptedItems.ToArray()); UnknownItems=@($unknownItems.ToArray()) }
}

# FIX82: GPU fix (menu 7). The question asked when the graphics card cannot be detected. The vendor must be typed (AMD, NVIDIA or
# Intel, as before): single letters are NOT accepted, because N means "No" everywhere else in the product. Enter or anything else
# cancels and nothing is changed. Returns 'AMD', 'NVIDIA' or 'Intel', or $null.
function Read-TpmGpuVendorChoice {
    param([string]$AdapterName = '')
    Write-Host ''
    Write-TpmText -Text 'TeknoParrot Manager could not tell which graphics card you have.' -Color Yellow
    if (-not [string]::IsNullOrWhiteSpace($AdapterName)) { Write-TpmText -Text ('Windows reports: ' + $AdapterName) -Color DarkGray }
    $answer = [string](Read-HostSafe '  Which graphics card do you have? Type AMD, NVIDIA or Intel (Enter to cancel)')
    if ([string]::IsNullOrWhiteSpace($answer)) {
        Write-TpmText -Text 'GPU fix canceled. No game was changed.' -Color DarkGray
        Write-Log 'GPU Fix: canceled -- vendor not detected and user did not enter one.'
        return $null
    }
    $vendor = $null
    if ($answer -imatch '^(amd|radeon)$') { $vendor = 'AMD' }
    elseif ($answer -imatch '^(nvidia|geforce)$') { $vendor = 'NVIDIA' }
    elseif ($answer -imatch '^intel$') { $vendor = 'Intel' }
    if (-not $vendor) {
        Write-TpmText -Text 'That was not AMD, NVIDIA or Intel. No game was changed.' -Color Red
        Write-Log ("GPU Fix: canceled -- unrecognized vendor '{0}'." -f $answer)
        return $null
    }
    Write-TpmText -Text ('Using the {0} fix.' -f $vendor) -Color DarkGray
    Write-Log "GPU Fix: user-specified vendor = $vendor"
    return $vendor
}

# The GPU fix result screen: a status line, only the non-zero counts, one line per kind of problem, one next step. Every fact the old
# screen showed (the full counts, saved paths, technical reasons, per-game steps, the game names and the safety copy folder) is in the
# Details view (key D) and the log.
function Get-TpmGpuFixResultView {
    param([Parameter(Mandatory)]$Result)
    $mutation = Get-TpmTransactionField -Object $Result -Name 'Mutation'
    $outcome = [string](Get-TpmTransactionField -Object $Result -Name 'Outcome' -Default '')
    $cancelled = [bool](Get-TpmTransactionField -Object $Result -Name 'Cancelled' -Default $false)
    $vendor = [string](Get-TpmTransactionField -Object $Result -Name 'GpuVendor' -Default '')
    if ([string]::IsNullOrWhiteSpace($vendor)) { $vendor = 'GPU' }
    $count = @{}
    foreach ($name in @('Updated', 'Unchanged', 'NotApplicable', 'Skipped', 'Errors', 'MissingPath', 'MissingDevice')) { $count[$name] = [int](Get-TpmTransactionField -Object $Result -Name $name -Default 0) }
    $failed = [int](Get-TpmTransactionField -Object $mutation -Name 'FailedItemCount' -Default 0)
    $unknown = [int](Get-TpmTransactionField -Object $mutation -Name 'UnknownItemCount' -Default 0)
    $unattempted = [int](Get-TpmTransactionField -Object $mutation -Name 'UnattemptedItemCount' -Default 0)
    $skipDetails = @(Get-TpmTransactionField -Object $Result -Name 'SkipDetails' -Default @() | Where-Object { $null -ne $_ })
    $needs = New-Object System.Collections.Generic.List[string]
    foreach ($group in @($skipDetails | Group-Object -Property { [string](Get-TpmTransactionField -Object $_ -Name 'Reason' -Default '') })) {
        # A drive that is not connected is a skip, not a failure: say which drive (from the saved paths) instead of a general sentence.
        $groupText = $group.Name
        $groupDrives = @($group.Group | Where-Object { [string](Get-TpmTransactionField -Object $_ -Name 'ReasonKey' -Default '') -eq 'DEVICE_UNAVAILABLE' } | ForEach-Object { if (([string](Get-TpmTransactionField -Object $_ -Name 'SavedPath' -Default '')) -match '^\s*([A-Za-z]:|\\\\[^\\]+\\[^\\]+)') { $Matches[1].ToUpperInvariant() } } | Sort-Object -Unique)
        if ($groupDrives.Count -gt 0 -and @($group.Group | Where-Object { [string](Get-TpmTransactionField -Object $_ -Name 'ReasonKey' -Default '') -ne 'DEVICE_UNAVAILABLE' }).Count -eq 0) {
            $groupText = if ($groupDrives.Count -eq 1) { ('Drive {0} is not connected.' -f $groupDrives[0]) } else { ('Drives {0} are not connected.' -f (Format-TpmNameList -Names $groupDrives)) }
        }
        [void]$needs.Add(('{0} skipped. {1}' -f (Format-TpmGameCount -Count $group.Count), $groupText))
    }
    if ($count.Skipped -gt $skipDetails.Count) { [void]$needs.Add(('{0} skipped.' -f (Format-TpmGameCount -Count ($count.Skipped - $skipDetails.Count)))) }
    if ($failed -gt 0) { [void]$needs.Add(('{0} could not be updated.' -f (Format-TpmGameCount -Count $failed))) }
    if ($unknown -gt 0) { [void]$needs.Add(('Could not check {0} after saving. Use Restore backup before you try again.' -f (Format-TpmGameCount -Count $unknown))) }
    if ($unattempted -gt 0) { [void]$needs.Add(('{0} not tried, because an earlier step stopped.' -f (Format-TpmGameCount -Count $unattempted))) }
    $isFinished = ($outcome -in @('SUCCEEDED', 'NO_OP', 'PARTIAL_APPLIED'))
    if (-not $cancelled -and -not $isFinished) { Add-TpmPlainReasonLine -Lines $needs -Code ([string](Get-TpmTransactionField -Object $Result -Name 'Reason' -Default '')) }
    $skippedOnly = ($failed -eq 0 -and $unknown -eq 0 -and $count.Skipped -gt 0)
    $title = 'The GPU fix could not finish.'
    if ($cancelled) { $title = 'GPU fix canceled. No game was changed.' }
    elseif ($outcome -eq 'SUCCEEDED') { $title = ('Applied the {0} fix to {1}.' -f $vendor, (Format-TpmGameCount -Count $count.Updated)) }
    elseif ($outcome -eq 'NO_OP') { $title = 'No game needed a GPU fix. Nothing was changed.' }
    elseif ($outcome -eq 'PARTIAL_APPLIED') { $title = ('Applied the {0} fix to {1}, but some games need attention.' -f $vendor, (Format-TpmGameCount -Count $count.Updated)) }
    elseif ($outcome -eq 'FAILED_BEFORE_MUTATION' -and $skippedOnly) { $title = 'Nothing was changed. Some games were skipped.' }
    $status = 'Problem'
    if ($cancelled -or $outcome -in @('SUCCEEDED', 'NO_OP')) { $status = 'Ok' }
    elseif ($outcome -eq 'PARTIAL_APPLIED' -or ($failed -eq 0 -and $unknown -eq 0 -and $count.Errors -eq 0)) { $status = 'Attention' }
    $done = New-Object System.Collections.Generic.List[string]
    $countsLine = Get-TpmResultCountsLine -Result $Result -Picked @(Get-TpmTransactionField -Object $Result -Name 'SelectedItems' -Default @()) -AlreadyWord 'already set up or needed no fix'
    if ($countsLine) { [void]$done.Add($countsLine) }
    $backupLine = Get-TpmBackupFolderLine -Result $Result -What 'your game settings'
    if ($backupLine) { [void]$done.Add($backupLine) }
    $next = 'Press B to go back.'
    if ($needs.Count -gt 0 -and $count.MissingPath -gt 0) { $next = 'Press H to fix the saved game paths, then press R to run it again.' }
    elseif ($needs.Count -gt 0 -and $count.MissingDevice -gt 0) { $next = 'Plug in the drive for the game, then press R to run it again. Or choose 13 (Library health check) in the main menu to repair these games.' }
    elseif ($needs.Count -gt 0) { $next = 'Press D to see why, or R to run it again.' }
    elseif ($outcome -eq 'SUCCEEDED') { $next = 'Start a game to try it. Press B to go back.' }
    return @{
        Title = $title
        Status = $status
        Done = $done.ToArray()
        Needs = $needs.ToArray()
        Next = $next
        DetailBlocks = @(Get-TpmGpuFixDetailBlocks -Result $Result)
        DetailsNote = 'GPU Fix changes saved compatibility fields only; TeknoParrot Manager does not verify game launch or display output.'
    }
}

function Get-TpmGpuFixDetailBlocks {
    param([Parameter(Mandatory)]$Result)
    $mutation = Get-TpmTransactionField -Object $Result -Name 'Mutation'
    $count = @{}
    foreach ($name in @('Updated', 'Unchanged', 'NotApplicable', 'Skipped', 'Errors')) { $count[$name] = [int](Get-TpmTransactionField -Object $Result -Name $name -Default 0) }
    $unattempted = [int](Get-TpmTransactionField -Object $mutation -Name 'UnattemptedItemCount' -Default 0)
    $gpuName = [string](Get-TpmTransactionField -Object $Result -Name 'GpuName' -Default '')
    if ([string]::IsNullOrWhiteSpace($gpuName)) { $gpuName = [string](Get-TpmTransactionField -Object $Result -Name 'GpuVendor' -Default '') }
    $totals = New-Object System.Collections.Generic.List[string]
    Add-TpmDetailLine -Lines $totals -Label 'GPU detected' -Text $gpuName
    [void]$totals.Add('Updated: ' + (Format-TpmGameCount -Count $count.Updated))
    [void]$totals.Add('Already correct: ' + (Format-TpmGameCount -Count $count.Unchanged))
    [void]$totals.Add('No GPU fix fields: ' + (Format-TpmGameCount -Count $count.NotApplicable))
    [void]$totals.Add('Skipped: ' + (Format-TpmGameCount -Count $count.Skipped))
    [void]$totals.Add('Not attempted: ' + (Format-TpmGameCount -Count $unattempted) + ' (stopped before writing)')
    [void]$totals.Add('Errors: ' + $count.Errors)
    $blocks = New-Object System.Collections.Generic.List[object]
    [void]$blocks.Add(@{ Heading = 'What was counted'; Lines = $totals.ToArray() })
    $backupFolder = [string](Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'Backup') -Name 'RootPath' -Default '')
    if (-not [string]::IsNullOrWhiteSpace($backupFolder)) { [void]$blocks.Add(@{ Heading = 'Safety copy of your game settings'; Lines = @('Folder: ' + $backupFolder) }) }
    foreach ($detail in @(Get-TpmTransactionField -Object $Result -Name 'SkipDetails' -Default @() | Where-Object { $null -ne $_ })) {
        $lines = New-Object System.Collections.Generic.List[string]
        Add-TpmDetailLine -Lines $lines -Label 'What happened' -Text ([string](Get-TpmTransactionField -Object $detail -Name 'Reason' -Default ''))
        Add-TpmDetailLine -Lines $lines -Label 'Saved path' -Text ([string](Get-TpmTransactionField -Object $detail -Name 'SavedPath' -Default ''))
        Add-TpmDetailLine -Lines $lines -Label 'What to do' -Text ([string](Get-TpmTransactionField -Object $detail -Name 'NextAction' -Default ''))
        Add-TpmDetailLine -Lines $lines -Label 'Technical' -Text ([string](Get-TpmTransactionField -Object $detail -Name 'Technical' -Default ''))
        Add-TpmDetailLine -Lines $lines -Label 'Reason code' -Text ([string](Get-TpmTransactionField -Object $detail -Name 'ReasonKey' -Default ''))
        [void]$blocks.Add(@{ Heading = [string](Get-TpmTransactionField -Object $detail -Name 'Game' -Default ''); Color = 'Yellow'; Lines = $lines.ToArray() })
    }
    foreach ($failure in @(Get-TpmTransactionField -Object $Result -Name 'FailureRecords' -Default @() | Where-Object { $null -ne $_ })) {
        $lines = New-Object System.Collections.Generic.List[string]
        Add-TpmDetailLine -Lines $lines -Label 'Step' -Text ([string](Get-TpmTransactionField -Object $failure -Name 'Operation' -Default ''))
        Add-TpmDetailLine -Lines $lines -Label 'Reason code' -Text ([string](Get-TpmTransactionField -Object $failure -Name 'ReasonKey' -Default ''))
        Add-TpmDetailLine -Lines $lines -Label 'Detail' -Text ([string](Get-TpmTransactionField -Object $failure -Name 'Exception' -Default ''))
        Add-TpmDetailLine -Lines $lines -Label 'Verified backup' -Text ([string](Get-TpmTransactionField -Object $failure -Name 'BackupPath' -Default ''))
        Add-TpmDetailLine -Lines $lines -Label 'What to do' -Text ([string](Get-TpmTransactionField -Object $failure -Name 'NextAction' -Default ''))
        [void]$blocks.Add(@{ Heading = [string](Get-TpmTransactionField -Object $failure -Name 'Game' -Default ''); Color = 'Yellow'; Lines = $lines.ToArray() })
    }
    foreach ($set in @(@('Changed', 'ChangedItems'), @('Failed', 'FailedItems'), @('Unknown', 'UnknownItems'), @('Skipped', 'SkippedItems'), @('Not attempted', 'UnattemptedItems'))) {
        $names = @(Get-TpmTransactionField -Object $mutation -Name $set[1] -Default @() | Where-Object { $_ })
        if ($names.Count -gt 0) { [void]$blocks.Add(@{ Heading = ('{0} ({1})' -f $set[0], $names.Count); Lines = @($names -join ', ') }) }
    }
    return $blocks.ToArray()
}

function Show-TpmGpuFixResult {
    param([Parameter(Mandatory)]$Result)
    $view = Get-TpmGpuFixResultView -Result $Result
    # The menu under this screen has its own [D] Details key, so Write-TpmOutcome asks no Details question of its own.
    Write-TpmOutcome @view -Unattended
}

# Locates the pcsx2x6 emulator folder under a TeknoParrot root: common
# names first, then any pcsx2-prefixed subfolder as a fallback. Returns
# $null if none is found (most installs don't have one -- it's specific to
# a handful of lightgun titles). Shared by Invoke-CrosshairSetup (issue #79
# crosshair deployment) and Get-CompatibilityWarnings (issue #85 BIOS
# detection) so both agree on what counts as "present" from one place, not
# two independently-maintained copies of the same candidate search.
function Resolve-Pcsx2Directory {
    param([Parameter(Mandatory)][string]$TeknoParrotRoot)
    foreach ($candidate in @("pcsx2x6","PCSX2x6","pcsx2","PCSX2")) {
        $try = Join-Path $TeknoParrotRoot $candidate
        if (Test-Path -LiteralPath $try) { return $try }
    }
    return Get-ChildItem -LiteralPath $TeknoParrotRoot -Directory -ErrorAction SilentlyContinue |
           Where-Object { $_.Name -imatch '^pcsx2' } | Select-Object -First 1 -ExpandProperty FullName
}

# Read-only, contract-backed required-component assessment shared by the
# compatibility warning surface. A warning is eligible only when exactly one
# valid ECVF contract matches the registered EmulatorType, the contract has a
# non-empty PathExists PresenceDetector, and the corresponding emulator folder
# already exists. Missing/invalid/ambiguous contracts, unsupported detector
# methods, and absent emulator folders remain Unknown/unclassified and produce
# no missing-component claim.
function Get-ContractBackedMissingComponents {
    param(
        [Parameter(Mandatory)][string]$EmulatorType,
        [Parameter(Mandatory)][string]$TeknoParrotRoot,
        [string[]]$AffectedProfiles = @(),
        [string]$ContractsRoot = ''
    )

    $unknown = [ordered]@{
        State             = 'Unknown'
        Reason            = $null
        ContractId        = $null
        EmulatorDirectory = $null
        Components        = @()
    }

    if ([string]::IsNullOrWhiteSpace($EmulatorType)) {
        $unknown.Reason = 'registered profile did not declare an emulator type'
        return [pscustomobject]$unknown
    }
    if ([string]::IsNullOrWhiteSpace($TeknoParrotRoot) -or
        -not (Test-Path -LiteralPath $TeknoParrotRoot -PathType Container)) {
        $unknown.Reason = 'TeknoParrot root was not available for component assessment'
        return [pscustomobject]$unknown
    }

    try {
        $ecvfContractsModule = Join-Path $PSScriptRoot "scripts\TPMCertification.Contracts.psm1"
        if (-not (Test-Path -LiteralPath $ecvfContractsModule -PathType Leaf)) {
            $unknown.Reason = 'the ECVF contracts framework was not available'
            return [pscustomobject]$unknown
        }
        Import-Module $ecvfContractsModule -Force -ErrorAction Stop

        $resolvedContractsRoot = if ([string]::IsNullOrWhiteSpace($ContractsRoot)) {
            Get-TPMContractsRootV1 -ValidationMode Runtime
        } else { $ContractsRoot }
        # Main is the packaged runtime consumer and never falls back to
        # maintainer source contracts when runtime resources are missing.
        $registeredContracts = Get-TPMRegisteredEmulatorContractsV1 -ValidationMode Runtime -ContractsRoot $resolvedContractsRoot
        $contractMatches = @($registeredContracts | Where-Object {
            [string]::Equals([string]$_.ContractId, $EmulatorType, [StringComparison]::OrdinalIgnoreCase)
        })
        if ($contractMatches.Count -ne 1) {
            $unknown.Reason = if ($contractMatches.Count -eq 0) {
                "no ECVF contract matched EmulatorType '$EmulatorType'"
            } else {
                "more than one ECVF contract matched EmulatorType '$EmulatorType'"
            }
            return [pscustomobject]$unknown
        }

        $contractEntry = $contractMatches[0]
        $contract = $contractEntry.Contract
        $contractId = [string]$contract.ContractId
        $unknown.ContractId = $contractId

        $emulatorDirectory = if ([string]::Equals($contractId, 'pcsx2x6', [StringComparison]::OrdinalIgnoreCase)) {
            # Preserve #254's established resolver, including its supported
            # casing and pcsx2-prefixed fallback names.
            Resolve-Pcsx2Directory -TeknoParrotRoot $TeknoParrotRoot
        } else {
            @(Get-ChildItem -LiteralPath $TeknoParrotRoot -Directory -ErrorAction SilentlyContinue |
                Where-Object { [string]::Equals($_.Name, $contractId, [StringComparison]::OrdinalIgnoreCase) } |
                Select-Object -First 1 -ExpandProperty FullName)
        }
        if ([string]::IsNullOrWhiteSpace([string]$emulatorDirectory) -or
            -not (Test-Path -LiteralPath $emulatorDirectory -PathType Container)) {
            $unknown.Reason = "the contract-matched emulator folder '$contractId' was not present"
            return [pscustomobject]$unknown
        }
        $unknown.EmulatorDirectory = $emulatorDirectory

        $capabilities = @($contract.EnvironmentCapabilities | Where-Object {
            $_.PresenceDetector -and
            $_.PresenceDetector.Method -eq 'PathExists' -and
            -not [string]::IsNullOrWhiteSpace([string]$_.PresenceDetector.Source)
        })
        if ($capabilities.Count -eq 0) {
            $unknown.Reason = "contract '$contractId' has no usable PathExists required-component detector"
            return [pscustomobject]$unknown
        }

        $affected = @($AffectedProfiles | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Sort-Object -Unique)
        $missing = New-Object System.Collections.Generic.List[object]
        foreach ($capability in $capabilities) {
            $detector = $capability.PresenceDetector
            $relativeSource = [string]$detector.Source
            if ([System.IO.Path]::IsPathRooted($relativeSource) -or
                $relativeSource -match '(^|[\\/])\.\.([\\/]|$)') {
                # A contract path that is not safely relative to its own
                # emulator folder cannot establish a trustworthy warning.
                continue
            }
            try {
                $expectedPath = Join-Path $emulatorDirectory $relativeSource
                $emulatorFull = [System.IO.Path]::GetFullPath($emulatorDirectory).TrimEnd([char]'\', [char]'/' )
                $expectedFull = [System.IO.Path]::GetFullPath($expectedPath)
                $withinEmulator = $expectedFull.StartsWith($emulatorFull + [System.IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase) -or
                                  [string]::Equals($expectedFull, $emulatorFull, [StringComparison]::OrdinalIgnoreCase)
                if (-not $withinEmulator) { continue }
            } catch {
                continue
            }

            if (Test-TPMEmulatorPresentV1 -Detector $detector -InstallDir $emulatorDirectory) { continue }

            $missing.Add([pscustomobject]@{
                EmulatorType       = $EmulatorType
                ContractId          = $contractId
                ContractDisplayName = [string]$contract.DisplayName
                ContractStatus      = [string]$contract.ContractStatus
                Confidence          = [string]$contract.EvidenceConfidence
                ContractBacked      = $true
                CapabilityId        = [string]$capability.CapabilityId
                ExpectedPath        = $expectedPath
                DetectorMethod      = [string]$detector.Method
                DetectorSource      = $relativeSource
                AffectedProfiles    = $affected
                AffectedGames       = $affected
                State               = 'Missing'
            })
        }

        return [pscustomobject]@{
            State             = if ($missing.Count -gt 0) { 'Missing' } else { 'Present' }
            Reason            = if ($missing.Count -gt 0) { 'one or more contract-declared components were absent' } else { $null }
            ContractId        = $contractId
            EmulatorDirectory = $emulatorDirectory
            Components        = $missing.ToArray()
        }
    } catch {
        $unknown.Reason = 'could not load or evaluate the ECVF contract -- ' + $_.Exception.Message
        return [pscustomobject]$unknown
    }
}

# Read-only classification of a resolved pcsx2x6 install against the ECVF
# contract's env-init EnvironmentCapability and the canonical crosshair PNG
# locations (issue #173). Never invokes InitializationAction and never
# writes anything -- this only reports state; a caller decides separately
# whether and how to repair. States:
#   NotInstalled        -- folder missing or emulator executable not found.
#   Unknown              -- the ECVF contracts framework could not be
#                           consulted; callers must treat this the same as
#                           NotInstalled for any write-adjacent decision.
#   StockUninitialized   -- present, but PCSX2.ini fails the contract's
#                           InitializedVerifier (no inis\PCSX2.ini yet, or
#                           missing required sections).
#   Incomplete           -- PCSX2.ini is initialized but one or both
#                           canonical crosshair PNGs are missing.
#   Canonical            -- PCSX2.ini is initialized and both crosshair
#                           PNGs are present at the canonical location.
function Get-Pcsx2CrosshairPrerequisiteState {
    param([Parameter(Mandatory)][string]$Pcsx2Dir)

    $result = [ordered]@{
        State                 = 'NotInstalled'
        Pcsx2Dir              = $Pcsx2Dir
        DataRoot              = $null
        IniPath               = $null
        Reason                = $null
        HasP1Png              = $false
        HasP2Png              = $false
        Contract              = $null
        EnvironmentCapability = $null
    }

    if ([string]::IsNullOrWhiteSpace($Pcsx2Dir) -or -not (Test-Path -LiteralPath $Pcsx2Dir -PathType Container)) {
        $result.Reason = "pcsx2x6 install folder not found"
        return [pscustomobject]$result
    }

    try {
        $ecvfContractsModule = Join-Path $PSScriptRoot "scripts\TPMCertification.Contracts.psm1"
        if (-not (Test-Path -LiteralPath $ecvfContractsModule -PathType Leaf)) {
            $result.State  = 'Unknown'
            $result.Reason = "the ECVF contracts framework was not available to classify this install"
            return [pscustomobject]$result
        }
        Import-Module $ecvfContractsModule -Force -ErrorAction Stop
        $loaded = Get-TPMEmulatorContractV1 -ContractId 'pcsx2x6' -ValidationMode Runtime
        $envCap = $loaded.Contract.EnvironmentCapabilities | Where-Object { $_.CapabilityId -eq 'env-init' } | Select-Object -First 1
        if (-not $envCap) {
            $result.State  = 'Unknown'
            $result.Reason = "pcsx2x6 contract has no 'env-init' EnvironmentCapability"
            return [pscustomobject]$result
        }
        $result.Contract              = $loaded.Contract
        $result.EnvironmentCapability = $envCap

        $present = Test-TPMEmulatorPresentV1 -Detector $envCap.PresenceDetector -InstallDir $Pcsx2Dir
        if (-not $present) {
            $result.Reason = "$($envCap.PresenceDetector.Source) not found under $Pcsx2Dir"
            return [pscustomobject]$result
        }

        $dataRoot = Resolve-TPMEnvironmentDataRootV1 -Resolver $envCap.DataRootResolver -InstallDir $Pcsx2Dir
        $result.DataRoot = $dataRoot
        if ($envCap.InitializedVerifier.RequiredPaths.Count -gt 0) {
            $result.IniPath = Join-Path $dataRoot $envCap.InitializedVerifier.RequiredPaths[0]
        }

        $p1Path = Join-Path $dataRoot "crosshairs\P1.png"
        $p2Path = Join-Path $dataRoot "crosshairs\P2.png"
        $result.HasP1Png = Test-Path -LiteralPath $p1Path -PathType Leaf
        $result.HasP2Png = Test-Path -LiteralPath $p2Path -PathType Leaf

        $verified = Test-TPMEnvironmentInitializedV1 -Verifier $envCap.InitializedVerifier -DataRoot $dataRoot
        if (-not $verified.Initialized) {
            $result.State  = 'StockUninitialized'
            $result.Reason = $verified.Reason
            return [pscustomobject]$result
        }

        if ($result.HasP1Png -and $result.HasP2Png) {
            $result.State = 'Canonical'
        } else {
            $result.State  = 'Incomplete'
            $result.Reason = "PCSX2.ini is initialized but one or both canonical crosshair PNGs are missing"
        }
        return [pscustomobject]$result
    } catch {
        $result.State  = 'Unknown'
        $result.Reason = "could not load or evaluate the pcsx2x6 emulator contract -- $_"
        return [pscustomobject]$result
    }
}

# Triggers the pcsx2x6 emulator's own -testconfig -portable first-run
# initialization mechanism (contract EnvironmentCapability 'env-init'),
# then re-verifies with the same read-only InitializedVerifier used for
# detection. Never hand-authors PCSX2.ini content -- CliInvocation only
# ever runs the emulator's own executable (issue #173). The caller must
# have already obtained user approval and confirmed no pcsx2x6 process is
# running; this function does not prompt and does not guard against a
# running process itself.
function Invoke-Pcsx2FirstRunSetup {
    param([Parameter(Mandatory)]$State)

    if ($State.State -ne 'StockUninitialized') {
        return [pscustomobject]@{ Success = $false; Reason = "first-run setup only applies to a StockUninitialized install (current state: $($State.State))" }
    }

    $ecvfContractsModule = Join-Path $PSScriptRoot "scripts\TPMCertification.Contracts.psm1"
    try {
        Import-Module $ecvfContractsModule -Force -ErrorAction Stop
        Invoke-TPMEnvironmentInitializationActionV1 -Action $State.EnvironmentCapability.InitializationAction -InstallDir $State.Pcsx2Dir | Out-Null
    } catch {
        Write-Log "Pcsx2FirstRunSetup: initialization action failed -- $_"
        return [pscustomobject]@{ Success = $false; Reason = "first-run initialization failed -- $_" }
    }

    $reverified = Test-TPMEnvironmentInitializedV1 -Verifier $State.EnvironmentCapability.InitializedVerifier -DataRoot $State.DataRoot
    if (-not $reverified.Initialized) {
        Write-Log "Pcsx2FirstRunSetup: post-init verification failed -- $($reverified.Reason)"
        return [pscustomobject]@{ Success = $false; Reason = "PCSX2.ini still not initialized after running first-run setup -- $($reverified.Reason)" }
    }

    Write-Log "Pcsx2FirstRunSetup: first-run initialization succeeded for $($State.Pcsx2Dir)"
    return [pscustomobject]@{ Success = $true; Reason = $null }
}

# Read-only report of the current on-disk cursor_path values for the
# emulator-owned USB1/USB2 guncon2 device (contract SettingPaths
# 'USB1.guncon2_cursor_path[jvsmode=lightgun]' /
# 'USB2.guncon2_cursor_path[jvsmode=lightgun]', Owner=Emulator,
# WritePolicy=NeverWrite). Reads the real on-disk section/key format
# confirmed in contracts\pcsx2x6\evidence.md#ev-usb-ini-contract -- [USB1]/
# [USB2] sections, guncon2_cursor_path key. Strictly read-only; TeknoParrot
# Manager never writes this value.
function Get-Pcsx2CursorPathReport {
    param([Parameter(Mandatory)][string]$IniPath)

    if (-not (Test-Path -LiteralPath $IniPath -PathType Leaf)) {
        return [pscustomobject]@{ Available = $false; USB1CursorPath = $null; USB2CursorPath = $null; Reason = "PCSX2.ini not found at $IniPath" }
    }
    try {
        $lines = [System.IO.File]::ReadAllLines($IniPath)
    } catch {
        return [pscustomobject]@{ Available = $false; USB1CursorPath = $null; USB2CursorPath = $null; Reason = "could not read PCSX2.ini -- $_" }
    }

    $values = @{ 'usb1' = $null; 'usb2' = $null }
    $sect = ''
    foreach ($ln in $lines) {
        $t = $ln.Trim()
        if ($t -match '^\[(.+)\]$') { $sect = $matches[1].ToLowerInvariant(); continue }
        if (($sect -eq 'usb1' -or $sect -eq 'usb2') -and $t -match '^guncon2_cursor_path\s*=\s*(.*)$') {
            $values[$sect] = $matches[1].Trim()
        }
    }
    return [pscustomobject]@{
        Available      = $true
        USB1CursorPath = $values['usb1']
        USB2CursorPath = $values['usb2']
        Reason         = $null
    }
}

# Crosshair setup wizard: owned preview of all crosshair PNGs, P1/P2 picker,
# deploy selected images to all registered lightgun game folders. Optionally
# hides the hardware cursor by setting HideCursor/DisableCursor=1 in every
# lightgun UserProfile (backs up profiles first).
function Read-TpmCrosshairYesNo {
    param([Parameter(Mandatory)][string]$Prompt, [string]$Default = 'Y', [object]$WorkflowContext = $null)
    do {
        if ($WorkflowContext) {
            Set-TpmWorkflowWaiting -Context $WorkflowContext -Message $Prompt -UserAction $Prompt
            Clear-TpmWorkflowFooter -Context $WorkflowContext
            $raw = Read-HostSafe $Prompt
            Clear-TpmWorkflowFooter -Context $WorkflowContext
            Resume-TpmWorkflowStatus -Context $WorkflowContext
        } else {
            $raw = Read-HostSafe $Prompt -Default $Default
        }
        if ($WorkflowContext -and $raw -eq '') { $raw = $Default }
        $answer = ([string]$raw).Trim().ToUpperInvariant()
        if ($answer -notin @('Y', 'N')) { Write-Host '  Please choose Y or N.' -ForegroundColor Yellow }
    } while ($answer -notin @('Y', 'N'))
    return $answer
}

# =============================================================================
# USE MY BEZEL FOLDER  (issue #429)
# =============================================================================
# The user points TPM at a folder of bezel images they already have. TPM matches each registered game to one image with the
# existing fuzzy title helpers, shows a preview, and only after approval copies the chosen image to
# <game folder>\reshade-shaders\Textures\bezel.png (the place the issue says ReShade reads a bezel from; NOT yet proven on real
# games, see docs\RC9-OWNER-TEST-PLAN.md). TPM never ships, downloads or points to bezels.
# Safety: nothing is written before approval; a bezel the user placed by hand is kept unless they choose to replace it (a copy is
# saved first); the copy runs as one checked file transaction; every applied file is recorded so it can be undone.
# Decisions: a folder shared by several games (for example a shared loader) is refused, because one bezel would show on all of
# them; only .png files are used, because the file is saved as bezel.png.

# Folder names are noisy: underscores, and the words "bezel" or "overlay" say nothing about the game. Region and version tags are
# removed by Get-NormalizedGameKey. Returns '' when nothing is left.
function Get-TpmBezelCleanTitle {
    param([AllowNull()][string]$Name)
    if ([string]::IsNullOrWhiteSpace($Name)) { return '' }
    return ([regex]::Replace($Name.Replace('_', ' '), '(?i)\b(bezels?|overlays?)\b', ' ')).Trim()
}

# Sequel numbers (4, IV) of a title, as one text; a Roman numeral counts as its digit, so "Soul Calibur II" and "soulclb2" agree.
# "House of the Dead 3" and "House of the Dead 4" differ by one letter and score almost 1.0 as text, so a different number must lower the confidence.
function Get-TpmBezelNumberText {
    param([AllowNull()][string]$Title)
    if ([string]::IsNullOrWhiteSpace($Title)) { return '' }
    $roman = @{ ii = '2'; iii = '3'; iv = '4'; v = '5'; vi = '6'; vii = '7'; viii = '8'; ix = '9'; x = '10' }
    $plain = [regex]::Replace($Title, '[\(\[].*?[\)\]]', ' ')
    $plain = [regex]::Replace($plain, '(?<=\p{L})(?=\d)|(?<=\d)(?=\p{L})', ' ')
    $found = @([regex]::Matches($plain.ToLowerInvariant(), '[\p{L}0-9]+') | ForEach-Object { $_.Value } |
        Where-Object { $_ -match '^\d+$' -or $roman.ContainsKey($_) } | ForEach-Object { if ($roman.ContainsKey($_)) { $roman[$_] } else { $_ } })
    return ($found -join ' ')
}

function Get-TpmBezelStatePath {
    param([string]$StateRoot = '')
    $root = if ($StateRoot) { [System.IO.Path]::GetFullPath($StateRoot) }
            elseif ($script:TpmOwnedLayout -and -not [string]::IsNullOrWhiteSpace([string]$script:TpmOwnedLayout.State)) { [System.IO.Path]::GetFullPath((Join-Path ([string]$script:TpmOwnedLayout.State) 'Bezels')) }
            else { [System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot 'Bezels\TPM-State')) }
    return [pscustomobject]@{ Root = $root; Path = (Join-Path $root 'bezels.json'); BackupRoot = (Join-Path $root 'Backups') }
}

# Saved bezel state: the folder last used, the user's picks (game -> bezel file, or '' for "no bezel for this game"), and one
# record per applied file (what undo needs). An unreadable file is set aside, never silently replaced.
function Read-TpmBezelState {
    param([string]$StateRoot = '')
    $paths = Get-TpmBezelStatePath -StateRoot $StateRoot
    $state = @{ Folder = ''; Picks = @{}; Applied = @{} }
    if (-not (Test-Path -LiteralPath $paths.Path -PathType Leaf)) { return $state }
    try {
        $saved = Get-Content -LiteralPath $paths.Path -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        if ($saved.Folder) { $state.Folder = [string]$saved.Folder }
        if ($saved.Picks) { foreach ($p in $saved.Picks.PSObject.Properties) { $state.Picks[$p.Name] = [string]$p.Value } }
        if ($saved.Applied) { foreach ($p in $saved.Applied.PSObject.Properties) { $state.Applied[$p.Name] = $p.Value } }
    } catch {
        $kept = $paths.Path + '.unreadable-' + (Get-Date).ToString('yyyyMMddHHmmss', [System.Globalization.CultureInfo]::InvariantCulture)
        try { [System.IO.File]::Copy($paths.Path, $kept, $false) } catch { Write-Log ('Bezels: the saved state could not be read and could not be set aside: {0}' -f $_.Exception.Message) }
        Write-Log ('Bezels: the saved state could not be read ({0}); starting fresh. A copy was kept as {1}.' -f $_.Exception.Message, [System.IO.Path]::GetFileName($kept))
        $state = @{ Folder = ''; Picks = @{}; Applied = @{} }
    }
    return $state
}

function Write-TpmBezelState {
    param([Parameter(Mandatory)]$State, [string]$StateRoot = '')
    $paths = Get-TpmBezelStatePath -StateRoot $StateRoot
    [void][System.IO.Directory]::CreateDirectory($paths.Root)
    $json = ([ordered]@{ Folder = [string]$State.Folder; Picks = $State.Picks; Applied = $State.Applied } | ConvertTo-Json -Depth 6)
    Write-TpmAtomicTextFile -Path $paths.Path -Text $json -Operation 'bezel state write' -Validate { param([string]$Written) $null -ne ($Written | ConvertFrom-Json -ErrorAction Stop) }
}

# The .png files of the user's folder (the folder and up to three levels below it; links are not followed). A file whose first
# bytes are not the PNG signature, or that is a .jpg (the bezel is saved as bezel.png), is counted in NotPng and not used.
function Find-TpmBezelFiles {
    param([Parameter(Mandatory)][string]$Folder)
    $root = [System.IO.Path]::GetFullPath($Folder).TrimEnd('\')
    $files = New-Object System.Collections.Generic.List[object]
    $notPng = 0
    $pending = New-Object System.Collections.Generic.Stack[object]
    $pending.Push([pscustomobject]@{ Path = $root; Depth = 0 })
    $signature = [byte[]](0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A)
    while ($pending.Count -gt 0) {
        $current = $pending.Pop()
        foreach ($entry in @(Get-ChildItem -LiteralPath $current.Path -Force -ErrorAction SilentlyContinue)) {
            if ($entry.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { continue }
            if ($entry.PSIsContainer) { if ($current.Depth -lt 3) { $pending.Push([pscustomobject]@{ Path = $entry.FullName; Depth = $current.Depth + 1 }) }; continue }
            if ($entry.Extension -ine '.png') { if ($entry.Extension -imatch '^\.jpe?g$') { $notPng++ }; continue }
            $head = New-Object byte[] 8
            try {
                $stream = [System.IO.File]::OpenRead($entry.FullName)
                try { [void]$stream.Read($head, 0, 8) } finally { $stream.Dispose() }
            } catch { $notPng++; continue }
            if (@(Compare-Object $head $signature -SyncWindow 0).Count -ne 0) { $notPng++; continue }
            $clean = Get-TpmBezelCleanTitle -Name $entry.BaseName
            $files.Add([pscustomobject]@{
                Path = $entry.FullName; Name = $entry.FullName.Substring($root.Length).TrimStart('\')
                Key = (Get-NormalizedGameKey $clean); BaseKey = (Get-TpmBaseTitleKey $clean); Numbers = (Get-TpmBezelNumberText -Title $clean)
            })
        }
    }
    return [pscustomobject]@{ Files = @($files.ToArray() | Sort-Object Name); NotPng = $notPng }
}

# One entry per registered game that has a usable game path: where its bezel would go, and whether ReShade is already there.
# Games that share one target folder are marked Shared (one bezel would show on all of them). Reads only.
function Get-TpmBezelGames {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [string[]]$ProtectedRoots = @())
    $games = New-Object System.Collections.Generic.List[object]
    $refused = 0
    foreach ($pf in @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'Bezel profile discovery' -EnumerationErrorAction SilentlyContinue | Sort-Object BaseName)) {
        try {
            $doc = Read-Xml $pf.FullName
            if ($null -eq $doc.GameProfile) { continue }
            $gpNode = $doc.GameProfile.SelectSingleNode('GamePath')
            if (-not $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { continue }
            # Real TeknoParrot profiles keep the title in GameNameInternal (some have none; TeknoParrot's Metadata file has it), never in GameName.
            $title = (Get-XmlChildText $doc.GameProfile 'GameNameInternal').Trim()
            if (-not $title) { $title = (Get-TpmTeknoParrotGameName -TpRoot (Split-Path -Parent ([System.IO.Path]::GetFullPath($UserProfilesDir).TrimEnd('\'))) -ProfileCode $pf.BaseName).Trim() }
            $name = if ($title) { $title } else { $pf.BaseName }
            $short = if ($pf.BaseName -match '^[^_]+_(.{3,})$') { $Matches[1] } else { '' }
            $check = Test-TpmGameMutationPath -GamePath $gpNode.InnerText.Trim() -RequireLeaf -ProtectedRoots $ProtectedRoots
            if (-not $check.Valid) { $refused++; Write-Log ('Bezels: {0} skipped; path reason={1}' -f $pf.BaseName, $check.ReasonCode); continue }
            $target = Get-ReShadeTargetInfo -Doc $doc -GamePath $check.CanonicalPath -ExeDir ([string]$check.GameDirectory)
            $hasReShade = (Test-Path -LiteralPath (Join-Path $target.TargetDir $target.DllName) -PathType Leaf) -and (Test-Path -LiteralPath (Join-Path $target.TargetDir 'ReShade.ini') -PathType Leaf)
            $games.Add([pscustomobject]@{
                ProfileId = [string]$pf.BaseName; Name = $name; TargetDir = [string]$target.TargetDir; HasReShade = $hasReShade; Shared = $false
                Dest = (Join-Path ([string]$target.TargetDir) 'reshade-shaders\Textures\bezel.png')
                Keys = @(@((Get-NormalizedGameKey $title), (Get-TpmBaseTitleKey $title)) | Where-Object { $_ } | Select-Object -Unique)
                # The profile code is the arcade short name ("acedriv3"); it matches only exactly, never by similarity ("daytona" is not "Daytona3").
                # A loader prefix ("teknonaomi_dybb99", "cps_wof") is not part of the short name.
                CodeKeys = @(@((Get-NormalizedGameKey $pf.BaseName), (Get-NormalizedGameKey $short)) | Where-Object { $_ } | Select-Object -Unique)
                Numbers = (Get-TpmBezelNumberText -Title ([regex]::Replace($title, '(?<=\p{Ll})(?=\p{Lu})', ' ')))
            })
        } catch { $refused++; Write-Log ('Bezels: {0} skipped: {1}' -f $pf.BaseName, $_.Exception.Message) }
    }
    foreach ($group in @($games | Group-Object { $_.TargetDir.ToLowerInvariant() })) {
        if ($group.Count -gt 1) { foreach ($shared in $group.Group) { $shared.Shared = $true } }
    }
    return [pscustomobject]@{ Games = @($games.ToArray()); Refused = $refused }
}

# The three best bezels per game (score is the best Dice score of any bezel/game name pair, or 1.0 when the file name is exactly the
# game's profile code). This is the slow step, so it runs once. Equal scores list a bezel with the right sequel number first.
function Get-TpmBezelCandidates {
    param([Parameter(Mandatory)][object[]]$Games, [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Bezels)
    $result = @{}
    foreach ($game in $Games) {
        $scored = New-Object System.Collections.Generic.List[object]
        foreach ($bezel in $Bezels) {
            $score = 0.0
            $exactCode = $false
            foreach ($bezelKey in @($bezel.Key, $bezel.BaseKey | Where-Object { $_ })) {
                if ($game.CodeKeys -contains $bezelKey) { $exactCode = $true }
                foreach ($gameKey in $game.Keys) { $s = Get-DiceSimilarity $bezelKey $gameKey; if ($s -gt $score) { $score = $s } }
            }
            if ($exactCode) { $score = 1.0 }
            $scored.Add([pscustomobject]@{ Bezel = $bezel; Score = $score; NumberMismatch = (-not $exactCode -and $bezel.Numbers -ne $game.Numbers) })
        }
        $result[$game.ProfileId] = @($scored.ToArray() | Sort-Object @{ Expression = { [math]::Round($_.Score, 3) }; Descending = $true }, @{ Expression = { $_.NumberMismatch } }, @{ Expression = { $_.Bezel.Name } } | Select-Object -First 3)
    }
    return $result
}

# One row per game: what TPM would do. Status: Apply, Same (already there), NeedsChoice, NoBezel, NeedsReShade, Shared, UserBezel
# (a bezel the user placed is there). Confidence: High (score >= 0.85 and clearly ahead of the next one), Medium (>= the registration
# threshold), Low (>= 0.5, a different sequel number, or a bezel that fits another game better), None. Two bezels that fit equally well
# are never High; the preview names the other one ("Also close").
# A remembered pick wins ('Your choice'; '' means no bezel wanted).
function New-TpmBezelPlanRows {
    param([Parameter(Mandatory)][object[]]$Games, [Parameter(Mandatory)][hashtable]$Candidates, [Parameter(Mandatory)]$State)
    $rows = New-Object System.Collections.Generic.List[object]
    $bestFit = @{}
    foreach ($list in $Candidates.Values) { foreach ($c in @($list)) { if (-not $c.NumberMismatch -and $c.Score -gt [double]$bestFit[$c.Bezel.Name]) { $bestFit[$c.Bezel.Name] = $c.Score } } }
    foreach ($game in $Games) {
        $ranked = @($Candidates[$game.ProfileId])
        $chosen = $null; $confidence = 'None'
        $pickName = if ($State.Picks.ContainsKey($game.ProfileId)) { [string]$State.Picks[$game.ProfileId] } else { $null }
        $picked = if ($pickName) { @($ranked | Where-Object { $_.Bezel.Name -ieq $pickName } | Select-Object -First 1) } else { @() }
        if ($null -ne $pickName -and $pickName -eq '') { $confidence = 'Skipped' }
        elseif ($picked.Count -gt 0) { $chosen = $picked[0].Bezel; $confidence = 'Your choice' }
        elseif ($ranked.Count -gt 0 -and $ranked[0].Score -ge 0.5) {
            $top = $ranked[0]
            $rival = @($ranked | Select-Object -Skip 1 | Where-Object { -not $_.NumberMismatch } | Select-Object -First 1)
            $gap = if ($rival.Count -gt 0) { $top.Score - $rival[0].Score } else { 1.0 }
            $confidence = if ($top.NumberMismatch -or $top.Score + 0.001 -lt $bestFit[$top.Bezel.Name]) { 'Low' }
                          elseif ($top.Score -ge 0.85 -and $gap -ge $FuzzyTieMargin) { 'High' }
                          elseif ($top.Score -ge $FuzzyAutoThreshold) { 'Medium' } else { 'Low' }
            if ($confidence -ne 'Low') { $chosen = $top.Bezel }
        }
        $status = 'NoBezel'
        if ($confidence -eq 'Skipped') { $status = 'Skipped' }
        elseif ($game.Shared -and $confidence -ne 'None') { $status = 'Shared' }
        elseif ($confidence -eq 'Low') { $status = 'NeedsChoice' }
        elseif ($chosen) {
            if (-not $game.HasReShade) { $status = 'NeedsReShade' }
            else {
                $existing = Get-TpmFileState -Path $game.Dest
                $mine = $State.Applied.ContainsKey($game.ProfileId) -and $existing.Exists -and ([string]$State.Applied[$game.ProfileId].DeployedSha256 -ieq [string]$existing.Sha256)
                $status = if (-not $existing.Exists -or $mine) { 'Apply' } else { 'UserBezel' }
                if ($existing.Exists -and $existing.Sha256 -ieq (Get-TpmFileState -Path $chosen.Path).Sha256) { $status = 'Same' }
            }
        }
        $rows.Add([pscustomobject]@{ Game = $game; Status = $status; Confidence = $confidence; Chosen = $chosen; Ranked = $ranked })
    }
    return @($rows.ToArray())
}

# Copies the chosen bezels in one checked transaction and records each one for undo. A bezel the user placed is replaced only
# with -ReplaceUserBezels, and a copy of it is saved first. Rows that are not Apply (or UserBezel when asked) are ignored.
function Invoke-TpmBezelApply {
    param([Parameter(Mandatory)][object[]]$Rows, [switch]$ReplaceUserBezels, [string]$StateRoot = '')
    $paths = Get-TpmBezelStatePath -StateRoot $StateRoot
    [void][System.IO.Directory]::CreateDirectory($paths.Root)
    $state = Read-TpmBezelState -StateRoot $StateRoot
    $stamp = (Get-Date).ToString('yyyyMMddHHmmss', [System.Globalization.CultureInfo]::InvariantCulture)
    $operations = New-Object System.Collections.Generic.List[object]
    $records = @{}
    $notSaved = New-Object System.Collections.Generic.List[string]
    foreach ($row in $Rows) {
        if (-not ($row.Status -eq 'Apply' -or ($row.Status -eq 'UserBezel' -and $ReplaceUserBezels))) { continue }
        $id = $row.Game.ProfileId
        $sourceHash = (Get-TpmFileState -Path $row.Chosen.Path).Sha256
        $existing = Get-TpmFileState -Path $row.Game.Dest
        $backupPath = ''; $backupHash = ''
        if ($state.Applied.ContainsKey($id)) { $backupPath = [string]$state.Applied[$id].BackupPath; $backupHash = [string]$state.Applied[$id].BackupSha256 }
        if ($row.Status -eq 'UserBezel') {
            # The user's own file: a verified copy is made before anything is replaced; without it this game is left alone.
            $backupPath = Join-Path $paths.BackupRoot ('{0}-{1}.png' -f ($id -replace '[^\w\.-]', '_'), $stamp)
            try {
                [void][System.IO.Directory]::CreateDirectory($paths.BackupRoot)
                [System.IO.File]::Copy($row.Game.Dest, $backupPath, $false)
                $backupHash = (Get-TpmFileState -Path $backupPath).Sha256
                if ($backupHash -ine $existing.Sha256) { throw 'The saved copy did not match.' }
            } catch {
                Write-Log ('Bezels: {0} left alone; the copy of the existing bezel could not be saved: {1}' -f $id, $_.Exception.Message)
                $notSaved.Add($row.Game.Name); continue
            }
        }
        $records[$id] = [ordered]@{ Destination = $row.Game.Dest; DeployedSha256 = $sourceHash; Source = $row.Chosen.Name; BackupPath = $backupPath; BackupSha256 = $backupHash; AppliedAt = $stamp }
        $operations.Add([pscustomobject]@{
            ItemId = ('Bezel:' + $id); Operation = $(if ($existing.Exists) { 'REPLACE' } else { 'ADD' })
            SourcePath = $row.Chosen.Path; DestinationPath = $row.Game.Dest; RootPath = $row.Game.TargetDir
            ExpectedSourceHash = $sourceHash; ExpectedFinalHash = $sourceHash
        })
    }
    if ($operations.Count -eq 0) {
        return [pscustomobject]@{ Outcome = 'NO_OP'; Applied = @(); NotSaved = $notSaved.ToArray(); Summary = 'Nothing needed to change.' }
    }
    $newState = @{ Folder = $state.Folder; Picks = $state.Picks; Applied = $state.Applied }
    foreach ($id in $records.Keys) { $newState.Applied[$id] = $records[$id] }
    $commit = { Write-TpmBezelState -State $newState -StateRoot $StateRoot }
    $verify = {
        $check = Read-TpmBezelState -StateRoot $StateRoot
        foreach ($id in $records.Keys) { if (-not $check.Applied.ContainsKey($id) -or [string]$check.Applied[$id].DeployedSha256 -ine [string]$records[$id].DeployedSha256) { throw 'The bezel record could not be read back.' } }
    }
    $batch = Invoke-TpmTransactionalFileBatch -WorkflowKey 'BezelSetup' -OperationKey 'Apply' -Operations $operations.ToArray() `
        -MetadataPaths @($paths.Path) -CommitAction $commit -PostCommitVerification $verify `
        -Summary 'The bezels were not copied.' -SuccessSummary 'The bezels were copied and checked.' -ReasonCode 'BEZEL_FILE_TRANSACTION_FAILED'
    $done = if ($batch.Outcome -in @('SUCCEEDED', 'NO_OP')) { @($records.Keys | Sort-Object) } else { @() }
    return [pscustomobject]@{ Outcome = [string]$batch.Outcome; Applied = $done; NotSaved = $notSaved.ToArray(); Summary = [string]$batch.Summary; Batch = $batch }
}

# Puts back every bezel TPM applied: the user's saved original where there was one, otherwise nothing. A file that is no longer
# exactly what TPM copied (the user changed it) is left alone and forgotten.
function Invoke-TpmBezelUndo {
    param([string]$StateRoot = '')
    $paths = Get-TpmBezelStatePath -StateRoot $StateRoot
    $state = Read-TpmBezelState -StateRoot $StateRoot
    $operations = New-Object System.Collections.Generic.List[object]
    $undone = New-Object System.Collections.Generic.List[string]
    $leftAlone = New-Object System.Collections.Generic.List[string]
    foreach ($id in @($state.Applied.Keys | Sort-Object)) {
        $record = $state.Applied[$id]
        $current = Get-TpmFileState -Path ([string]$record.Destination)
        if (-not $current.Exists) { [void]$undone.Add($id); continue }
        if ($current.Sha256 -ine [string]$record.DeployedSha256) { [void]$leftAlone.Add($id); continue }
        $backup = if ($record.BackupPath) { Get-TpmFileState -Path ([string]$record.BackupPath) } else { $null }
        $restore = ($backup -and $backup.Exists -and $backup.Sha256 -ieq [string]$record.BackupSha256)
        if ($record.BackupPath -and -not $restore) { [void]$leftAlone.Add($id); continue }
        $operations.Add([pscustomobject]@{
            ItemId = ('BezelUndo:' + $id); Operation = $(if ($restore) { 'REPLACE' } else { 'REMOVE' })
            SourcePath = $(if ($restore) { [string]$record.BackupPath } else { $null }); DestinationPath = [string]$record.Destination
            RootPath = [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetDirectoryName([System.IO.Path]::GetDirectoryName([string]$record.Destination)))
            ExpectedSourceHash = $(if ($restore) { [string]$record.BackupSha256 } else { '' }); ExpectedFinalHash = $(if ($restore) { [string]$record.BackupSha256 } else { '' })
            ExpectedDestinationHash = [string]$record.DeployedSha256
        })
        [void]$undone.Add($id)
    }
    $newState = @{ Folder = $state.Folder; Picks = $state.Picks; Applied = @{} }
    if ($operations.Count -eq 0) {
        # No file to put back (already gone, or changed by the user): only the records are cleared.
        $outcome = 'SUCCEEDED'
        try { Write-TpmBezelState -State $newState -StateRoot $StateRoot } catch { Write-Log ('Bezels: the undo records could not be cleared: {0}' -f $_.Exception.Message); $outcome = 'FAILED_BEFORE_MUTATION' }
        return [pscustomobject]@{ Outcome = $outcome; Undone = $undone.ToArray(); LeftAlone = $leftAlone.ToArray() }
    }
    $commit = { Write-TpmBezelState -State $newState -StateRoot $StateRoot }
    $verify = { if ((Read-TpmBezelState -StateRoot $StateRoot).Applied.Count -ne 0) { throw 'The bezel records were not cleared.' } }
    $batch = Invoke-TpmTransactionalFileBatch -WorkflowKey 'BezelSetup' -OperationKey 'Undo' -Operations $operations.ToArray() `
        -MetadataPaths @($paths.Path) -CommitAction $commit -PostCommitVerification $verify `
        -Summary 'The bezels were not undone.' -SuccessSummary 'The bezels were put back and checked.' -ReasonCode 'BEZEL_UNDO_FAILED'
    return [pscustomobject]@{ Outcome = [string]$batch.Outcome; Undone = $undone.ToArray(); LeftAlone = $leftAlone.ToArray(); Batch = $batch }
}

function Write-TpmBezelPreview {
    param([Parameter(Mandatory)][object[]]$Rows, [int]$BezelCount, [int]$NotPng = 0)
    Write-TpmText -Text 'Bezel preview. Nothing has been changed yet.' -Color Cyan -BlankBefore
    $skipped = if ($NotPng -gt 0) { ' {0} other image files (.jpg, or not a real PNG) were not used.' -f $NotPng } else { '' }
    Write-TpmText -Text ('Found {0} in your folder.{1}' -f (Format-TpmCountNoun -Count $BezelCount -Singular 'bezel'), $skipped) -Color DarkGray
    $number = 0
    foreach ($row in @($Rows | Where-Object { $_.Status -ne 'NoBezel' })) {
        $number++
        $shownName = if ($row.Chosen) { $row.Chosen.Name } else { $row.Ranked[0].Bezel.Name }
        $others = @($row.Ranked | Where-Object { $_.Score -ge 0.5 -and $_.Bezel.Name -ne $shownName } | ForEach-Object { $_.Bezel.Name })
        $alsoClose = if ($others.Count -gt 0) { ' Also close: {0}.' -f ($others -join ', ') } else { '' }
        $label = switch ($row.Status) {
            'Apply'        { '{0} ({1} match).{2}' -f $row.Chosen.Name, $row.Confidence, $alsoClose }
            'Same'         { 'already has this bezel ({0}).' -f $row.Chosen.Name }
            'UserBezel'    { 'has a bezel you placed. It is kept unless you choose to replace it. New one: {0} ({1} match).{2}' -f $row.Chosen.Name, $row.Confidence, $alsoClose }
            'NeedsReShade' { 'set up ReShade for this game first (bezel: {0}).' -f $row.Chosen.Name }
            'Shared'       { 'shares its folder with other games, so it is skipped.' }
            'NeedsChoice'  { 'needs your choice. Best guess: {0} (Low match).{1}' -f $row.Ranked[0].Bezel.Name, $alsoClose }
            'Skipped'      { 'you chose no bezel for this game.' }
        }
        Write-TpmText -Text ('{0,3}) {1}: {2}' -f $number, $row.Game.Name, $label) -Color $(if ($row.Status -eq 'Apply') { 'White' } else { 'Yellow' }) -HangingIndent 6
    }
    $none = @($Rows | Where-Object { $_.Status -eq 'NoBezel' }).Count
    if ($none -gt 0) { Write-TpmText -Text ('{0} had no bezel in your folder. Nothing was guessed for them.' -f (Format-TpmGameCount -Count $none)) -Color DarkGray -BlankBefore }
}

function Show-TpmBezelDetails {
    param([Parameter(Mandatory)][object[]]$Rows, [int]$NotPng)
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($row in @($Rows | Where-Object { $_.Chosen })) { [void]$lines.Add(('{0}: {1} -> {2}' -f $row.Game.ProfileId, $row.Chosen.Path, $row.Game.Dest)) }
    $match = @(
        'Names are cleaned first (underscores, the words bezel and overlay, region and version tags) and compared to each game name with the same title matching the game list uses.',
        'High means a close match that is clearly ahead of the next one. Medium means a likely match. Low, a different sequel number, or a bezel that fits another game better means you choose. Matches are never made without a preview.',
        ('Files that are not real .png images (including .jpg files) are ignored: {0}.' -f $NotPng),
        'TeknoParrot Manager puts the file where ReShade reads bezel.png. This has not been confirmed on every graphics type. Games that run in exclusive fullscreen or start through a loader may not show it.'
    )
    Show-TpmDetailBlocks -Blocks @(@{ Heading = 'Where each file goes'; Lines = $lines.ToArray() }, @{ Heading = 'How the match works'; Lines = $match })
}

# Lets the user pick one of the best bezels for a game (or none). Remembered, so the game is not asked about again.
function Read-TpmBezelPick {
    param([Parameter(Mandatory)]$Row, [Parameter(Mandatory)]$State, [string]$StateRoot = '')
    Write-TpmText -Text ('Bezel for {0}:' -f $Row.Game.Name) -Color Cyan -BlankBefore
    $i = 0
    foreach ($candidate in $Row.Ranked) { $i++; Write-TpmText -Text ('{0}) {1}' -f $i, $candidate.Bezel.Name) -Indent 4 }
    Write-TpmText -Text '0) No bezel for this game' -Indent 4
    $choice = Read-TpmChoice -Prompt '  Choice (K to keep as is, default K)' -Choices @(@('K', '0') + @(1..$Row.Ranked.Count | ForEach-Object { [string]$_ })) -Default 'K'
    if ($choice -eq 'K') { return $false }

    $State.Picks[$Row.Game.ProfileId] = $(if ($choice -eq '0') { '' } else { [string]$Row.Ranked[[int]$choice - 1].Bezel.Name })
    try { Write-TpmBezelState -State $State -StateRoot $StateRoot } catch { Write-Log ('Bezels: the pick could not be saved: {0}' -f $_.Exception.Message) }
    return $true
}

function Invoke-TpmBezelUndoMenu {
    param([string]$StateRoot = '')
    $state = Read-TpmBezelState -StateRoot $StateRoot
    if ($state.Applied.Count -eq 0) { Write-TpmText -Text 'There are no bezels from TeknoParrot Manager to undo.' -Color DarkGray -BlankBefore; return }
    Write-TpmText -Text 'Bezels TeknoParrot Manager copied:' -Color Cyan -BlankBefore
    foreach ($id in @($state.Applied.Keys | Sort-Object)) { Write-TpmText -Text ('{0}: {1}' -f $id, $state.Applied[$id].Source) -Indent 4 }
    Write-TpmText -Text 'Undo removes each one, and puts back the bezel you had before where TeknoParrot Manager saved a copy. A file you changed since is left alone.' -Color DarkGray
    if ((Read-TpmYesNo -Prompt '  Undo these bezels? (Y/N, default N)' -Default 'N') -ne 'Y') { Write-TpmText -Text 'Nothing was changed.' -Color DarkGray; return }
    $result = Invoke-TpmBezelUndo -StateRoot $StateRoot
    Write-Log ('Bezels: undo outcome={0} undone={1} leftAlone={2}' -f $result.Outcome, ($result.Undone -join ','), ($result.LeftAlone -join ','))
    if ($result.Outcome -in @('SUCCEEDED', 'NO_OP')) {
        Write-TpmText -Text ('Done. {0} put back and checked.' -f (Format-TpmCountNoun -Count $result.Undone.Count -Singular 'bezel')) -Color Green
        if ($result.LeftAlone.Count -gt 0) { Write-TpmText -Text ('{0} left alone because the file is not the one TeknoParrot Manager copied.' -f (Format-TpmGameCount -Count $result.LeftAlone.Count)) -Color Yellow }
    } else {
        Write-TpmText -Text 'The undo did not finish. Your files were put back as they were. The log says why.' -Color Yellow
    }
}

function Invoke-TpmBezelSetup {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [string[]]$ProtectedRoots = @(), [string]$StateRoot = '')
    Write-TpmText -Text 'Use my bezel folder. TeknoParrot Manager does not come with bezels. It only uses images you already have.' -Color DarkGray -BlankBefore
    Write-TpmText -Text 'F) Pick bezels from my folder    U) Undo bezels I applied    X) Back' -Color White
    $action = Read-TpmChoice -Prompt '  Action (F/U/X, default F)' -Choices @('F', 'U', 'X') -Default 'F'
    if ($action -eq 'X') { return }
    if ($action -eq 'U') { Invoke-TpmBezelUndoMenu -StateRoot $StateRoot; return }

    $state = Read-TpmBezelState -StateRoot $StateRoot
    $folder = (Read-PathWithBrowse -Prompt $(if ($state.Folder) { "  Bezel folder (Enter for $($state.Folder))" } else { '  Bezel folder' }) -Mode Folder).Trim().Trim('"')
    if (-not $folder) { $folder = $state.Folder }
    if (-not $folder -or -not (Test-Path -LiteralPath $folder -PathType Container) -or -not (Test-TpmNoReparsePath -Path $folder)) {
        Write-TpmText -Text 'That folder was not found. Nothing was changed.' -Color Yellow; return
    }
    $found = Find-TpmBezelFiles -Folder $folder
    if ($found.Files.Count -eq 0) { Write-TpmText -Text 'No .png bezel images were found in that folder. Nothing was changed.' -Color Yellow; return }
    $gameList = Get-TpmBezelGames -UserProfilesDir $UserProfilesDir -ProtectedRoots $ProtectedRoots
    if ($gameList.Games.Count -eq 0) { Write-TpmText -Text 'No registered games were found. Nothing was changed.' -Color Yellow; return }
    Write-TpmText -Text 'Matching your bezels to your games...' -Color DarkGray
    $candidates = Get-TpmBezelCandidates -Games $gameList.Games -Bezels $found.Files
    if ($state.Folder -ne [System.IO.Path]::GetFullPath($folder)) {
        $state.Folder = [System.IO.Path]::GetFullPath($folder)
        try { Write-TpmBezelState -State $state -StateRoot $StateRoot } catch { Write-Log ('Bezels: the folder could not be saved: {0}' -f $_.Exception.Message) }
    }
    Write-Log ('Bezels: folder has {0} bezels ({1} not real PNG files); {2} games checked; {3} refused' -f $found.Files.Count, $found.NotPng, $gameList.Games.Count, $gameList.Refused)
    while ($true) {
        $rows = @(New-TpmBezelPlanRows -Games $gameList.Games -Candidates $candidates -State $state)
        $shown = @($rows | Where-Object { $_.Status -ne 'NoBezel' })
        Write-TpmBezelPreview -Rows $rows -BezelCount $found.Files.Count -NotPng $found.NotPng
        Write-TpmText -Text 'A) Apply   a number) pick a different bezel for that game   D) Details   C) Cancel' -Color White -BlankBefore
        $choice = Read-TpmChoice -Prompt '  Choice (default C)' -Choices @(@('A', 'D', 'C') + @(1..[Math]::Max(1, $shown.Count) | ForEach-Object { [string]$_ })) -Default 'C'
        if ($choice -eq 'C') { Write-TpmText -Text 'Canceled. No files were changed.' -Color DarkGray; return }
        if ($choice -eq 'D') { Show-TpmBezelDetails -Rows $rows -NotPng $found.NotPng; continue }
        if ($choice -ne 'A') {
            $row = if ($shown.Count -ge [int]$choice) { $shown[[int]$choice - 1] } else { $null }
            if ($row -and $row.Ranked.Count -gt 0) { [void](Read-TpmBezelPick -Row $row -State $state -StateRoot $StateRoot) }
            continue
        }
        $replace = $false
        $mine = @($rows | Where-Object { $_.Status -eq 'UserBezel' })
        if ($mine.Count -gt 0) {
            Write-TpmText -Text ('{0} already has a bezel you placed there.' -f (Format-TpmGameCount -Count $mine.Count)) -Color Yellow -BlankBefore
            $replace = ((Read-TpmYesNo -Prompt '  Replace them? A copy of each is saved first and Undo puts it back. (Y/N, default N)' -Default 'N') -eq 'Y')
        }
        $result = Invoke-TpmBezelApply -Rows $rows -ReplaceUserBezels:$replace -StateRoot $StateRoot
        Write-Log ('Bezels: apply outcome={0} applied={1} notSaved={2}' -f $result.Outcome, ($result.Applied -join ','), ($result.NotSaved -join ','))
        if ($result.Outcome -eq 'SUCCEEDED') {
            Write-TpmText -Text ('Done. {0} copied and checked.' -f (Format-TpmCountNoun -Count $result.Applied.Count -Singular 'bezel')) -Color Green -BlankBefore
            Write-TpmText -Text 'TeknoParrot Manager put each bezel where ReShade looks for it. Whether a game shows it is not confirmed for every game. Press D at the preview for Details. You can undo this from this same menu.' -Color DarkGray
        } elseif ($result.Outcome -eq 'NO_OP') {
            Write-TpmText -Text 'Nothing needed to change.' -Color DarkGray -BlankBefore
        } else {
            Write-TpmText -Text 'The bezels were not copied and your files were put back as they were. The log says why.' -Color Yellow -BlankBefore
        }
        if ($result.NotSaved.Count -gt 0) { Write-TpmText -Text ('{0} left alone because a copy of the existing bezel could not be saved.' -f (Format-TpmGameCount -Count $result.NotSaved.Count)) -Color Yellow }
        return
    }
}

function Invoke-CrosshairSetup {
    param([string]$UserProfilesDir, [string]$TpRoot, [object]$WorkflowContext = $null, [string[]]$ProtectedRoots = @())

    $readCrosshairPrompt = {
        param([string]$Prompt)
        if ($WorkflowContext) {
            return Read-TpmWorkflowInput -Context $WorkflowContext -Prompt $Prompt
        }
        return Read-HostSafe $Prompt
    }
    $crosshairsDir = Join-Path $PSScriptRoot "Crosshairs"
    if (-not (Test-Path -LiteralPath $crosshairsDir)) {
        Write-Host "  ERROR: Crosshairs folder not found: $crosshairsDir" -ForegroundColor Red
        Write-Host "  Place PNG crosshair files in a 'Crosshairs' subfolder next to the script." -ForegroundColor Yellow
        Write-Log "Crosshairs: Crosshairs folder not found"
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $false; Deployed = 0; Skipped = 0; Errors = 1; Reason = 'CROSSHAIR_SOURCE_DIRECTORY_MISSING' }
    }

    # Keep discovery indeterminate through the unbounded filename sort. Users may
    # add any number of images, so neither discovery nor sorting has a fixed cap.
    $allFileCandidates = [System.Collections.Generic.List[System.IO.FileInfo]]::new()
    $crosshairDiscoveryStarted = Get-Date
    $crosshairDiscoveryCurrent = 0
    Write-TpmCompactExtractionProgress -Phase Checking -Label 'Crosshair PNG discovery' -Current $crosshairDiscoveryCurrent -Total 0 -StartedAt $crosshairDiscoveryStarted
    $crosshairDiscoveryCurrentCompleted = $false
    try {
        Get-ChildItem -LiteralPath $crosshairsDir -Filter "*.png" -File -ErrorAction Stop | ForEach-Object {
            [void]$allFileCandidates.Add($_)
            $crosshairDiscoveryCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'Crosshair PNG discovery' -Current $crosshairDiscoveryCurrent -Total 0 -StartedAt $crosshairDiscoveryStarted
        }
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'Crosshair PNG discovery' -Current $crosshairDiscoveryCurrent -Total 0 -StartedAt $crosshairDiscoveryStarted
        $allFiles = @($allFileCandidates.ToArray() | Sort-Object Name)
        $crosshairDiscoveryCurrentCompleted = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'Crosshair PNG discovery' -Current $crosshairDiscoveryCurrent -Total 0 -StartedAt $crosshairDiscoveryStarted -Complete -Outcome $(if ($crosshairDiscoveryCurrentCompleted) { 'Final' } else { 'Error' })
    }
    $valid   = [System.Collections.Generic.List[string]]::new()
    $invalid = [System.Collections.Generic.List[string]]::new()
    $crosshairScanStarted = Get-Date
    $crosshairScanCurrent = 0

    foreach ($f in $allFiles) {
        $crosshairScanCurrent++
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'Crosshair image validation' -Current $crosshairScanCurrent -Total $allFiles.Count -StartedAt $crosshairScanStarted
        if (Test-PngFile -Path $f.FullName) { $valid.Add($f.FullName) }
        else {
            $invalid.Add($f.Name)
            Write-Log "Crosshairs: rejected invalid PNG -- $($f.Name)"
        }
    }
    if ($allFiles.Count -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'Crosshair image validation' -Current $crosshairScanCurrent -Total $allFiles.Count -StartedAt $crosshairScanStarted -Complete }

    if ($invalid.Count -gt 0) {
        Write-Host ("  WARNING: {0} file(s) failed PNG validation and were skipped:" -f $invalid.Count) -ForegroundColor Yellow
        foreach ($n in $invalid) { Write-Host "    $n" -ForegroundColor DarkGray }
    }
    if ($valid.Count -eq 0) {
        Write-Host "  No valid PNG crosshairs found in: $crosshairsDir" -ForegroundColor Red
        Write-Log "Crosshairs: no valid PNGs found"
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $false; Deployed = 0; Skipped = 0; Errors = 1; Reason = 'NO_VALID_CROSSHAIRS' }
    }

    Write-Host ("  Found {0} valid crosshair(s). Opening the built-in preview..." -f $valid.Count) -ForegroundColor Cyan
    $previewResult = $null
    try {
        $previewResult = Show-TpmCrosshairPreviewWindow -CrosshairPaths $valid.ToArray() -TimeoutSeconds 45
    } catch {
        Write-Log "Crosshairs: owned preview launch failed -- $_"
        $previewResult = [pscustomobject]@{ Available = $false; Cancelled = $false; P1Index = $null; P2Index = $null; Reason = 'PREVIEW_WINDOW_UNAVAILABLE'; Error = $_.Exception.Message }
    }
    $previewP1Idx = if ($previewResult -and $null -ne $previewResult.P1Index) { [int]$previewResult.P1Index } else { $null }
    $previewP2Idx = if ($previewResult -and $null -ne $previewResult.P2Index) { [int]$previewResult.P2Index } else { $null }
    if (-not $previewResult -or -not $previewResult.Available) {
        Write-Host "  The built-in preview closed or could not open. Any choice already made was kept; enter each missing number in the console." -ForegroundColor Yellow
    } elseif ($previewResult.Cancelled) {
        Write-Host "  Preview closed. Any missing P1 or P2 choice can be entered in the console." -ForegroundColor DarkCyan
    } else {
        Write-Host ("  Preview choices: P1 {0}, P2 {1}." -f $previewP1Idx, $previewP2Idx) -ForegroundColor DarkCyan
    }

    # Remembers the last P1/P2 choice (by filename, not index -- indices shift
    # if PNGs are added/removed from the Crosshairs folder between runs) so a
    # re-run doesn't require re-finding/re-entering the same numbers. A saved
    # name that no longer exists in $valid is silently ignored.
    $crosshairStatePath = Join-Path $PSScriptRoot "TeknoParrot-Manager-crosshairs.json"
    $lastP1Idx = $null; $lastP2Idx = $null
    if (Test-Path -LiteralPath $crosshairStatePath) {
        try {
            $crosshairState = Get-Content -LiteralPath $crosshairStatePath -Raw -Encoding UTF8 | ConvertFrom-Json
            if ($crosshairState.P1) {
                $hit = for ($i = 0; $i -lt $valid.Count; $i++) { if ([System.IO.Path]::GetFileNameWithoutExtension($valid[$i]) -eq $crosshairState.P1) { $i; break } }
                if ($null -ne $hit) { $lastP1Idx = $hit }
            }
            if ($crosshairState.P2) {
                $hit = for ($i = 0; $i -lt $valid.Count; $i++) { if ([System.IO.Path]::GetFileNameWithoutExtension($valid[$i]) -eq $crosshairState.P2) { $i; break } }
                if ($null -ne $hit) { $lastP2Idx = $hit }
            }
        } catch { Write-Log "Crosshairs: could not read last-used state -- $_" }
    }
    # Pick P1
    $p1Idx = $previewP1Idx
    while ($null -eq $p1Idx) {
        $promptText = if ($null -ne $lastP1Idx) {
            "  P1 crosshair index (0-{0}, Enter for last used: {1} {2})" -f ($valid.Count - 1), $lastP1Idx, [System.IO.Path]::GetFileNameWithoutExtension($valid[$lastP1Idx])
        } else { "  P1 crosshair index (0-{0})" -f ($valid.Count - 1) }
        $raw = (& $readCrosshairPrompt $promptText)
        if ($raw -eq '' -and $null -ne $lastP1Idx) { $p1Idx = $lastP1Idx }
        elseif ($raw -match '^\d+$' -and $raw.Length -le 9 -and [int]$raw -lt $valid.Count) { $p1Idx = [int]$raw }
        else { Write-Host ("  Enter a number between 0 and {0}." -f ($valid.Count - 1)) -ForegroundColor Yellow }
    }
    $p2Idx = $previewP2Idx
    while ($null -eq $p2Idx) {
        $promptText = if ($null -ne $lastP2Idx) {
            "  P2 crosshair index (0-{0}, or same as P1, Enter for last used: {1} {2})" -f ($valid.Count - 1), $lastP2Idx, [System.IO.Path]::GetFileNameWithoutExtension($valid[$lastP2Idx])
        } else { "  P2 crosshair index (0-{0}, or same as P1)" -f ($valid.Count - 1) }
        $raw = (& $readCrosshairPrompt $promptText)
        if ($raw -eq '' -and $null -ne $lastP2Idx) { $p2Idx = $lastP2Idx }
        elseif ($raw -match '^\d+$' -and $raw.Length -le 9 -and [int]$raw -lt $valid.Count) { $p2Idx = [int]$raw }
        else { Write-Host ("  Enter a number between 0 and {0}." -f ($valid.Count - 1)) -ForegroundColor Yellow }
    }

    $p1Name = [System.IO.Path]::GetFileNameWithoutExtension($valid[$p1Idx])
    $p2Name = [System.IO.Path]::GetFileNameWithoutExtension($valid[$p2Idx])
    Write-Host ""
    Write-Host "  P1: $p1Name    P2: $p2Name" -ForegroundColor Green
    $crosshairConfirm = Read-TpmCrosshairYesNo -Prompt "  Apply these crosshairs? (Y/N, default Y)" -Default 'Y' -WorkflowContext $WorkflowContext
    if ($crosshairConfirm -ne 'Y') {
        Write-Host "  Crosshair setup canceled. No files were changed." -ForegroundColor Yellow
        Write-Log "Crosshairs: canceled before deployment."
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $true; Deployed = 0; Skipped = 0; Errors = 0; Reason = 'USER_CANCELLED' }
    }
    Write-Log "Crosshairs: P1=$p1Name  P2=$p2Name"


    # Locate the ElfLdr2 folder by its exact known names only; no guessing from similar names.
    $elfDir = $null
    foreach ($candidate in @("ElfLdr2","ElfLoader2","elf","elf2","ElfLdr")) {
        $try = Join-Path $TpRoot $candidate
        if (Test-Path -LiteralPath $try) { $elfDir = $try; break }
    }

    # Locate pcsx2x6 folder -- shared resolver, see Resolve-Pcsx2Directory.
    $pcsx2Dir = Resolve-Pcsx2Directory -TeknoParrotRoot $TpRoot
# Build one physical target plan for all lightgun profiles. Shared emulator
# folders are represented once; the transaction performs the P1/P2 pair
# atomically and commits last-selection state only after final verification.
    Write-Host ""
    Write-Host "  Preparing crosshair deployment..." -ForegroundColor Cyan
    $skipped = 0; $errors = 0; $deployed = 0
    $sourceFolderGames = New-Object System.Collections.Generic.List[string]
    $targetPlans = New-Object System.Collections.Generic.List[object]
    $logicalDeployments = New-Object System.Collections.Generic.List[string]
    $elfPlanned = $false; $pcsx2Planned = $false; $pcsx2SkipReason = ''; $pcsx2IniPath = $null; $pcsx2AssetDir = $null
    # FIX82: what the Details view of the result screen shows about the emulator (PCSX2) folder and settings file.
    $crosshairEmulatorNotes = New-Object System.Collections.Generic.List[string]
    $crosshairSkippedGames = New-Object System.Collections.Generic.List[string]

    $xmlFiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'Crosshair profile discovery' -EnumerationErrorAction SilentlyContinue)

    $profileScanStarted = Get-Date
    $profileScanCurrent = 0
    $profileScanTotal = $xmlFiles.Count
    foreach ($pf in $xmlFiles) {
        $profileScanCurrent++
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Crosshair profile planning' -Current $profileScanCurrent -Total $profileScanTotal -StartedAt $profileScanStarted
        try {
            $doc = Read-Xml $pf.FullName
            if ($null -eq $doc.GameProfile) { continue }
            $gameNameNode = $doc.GameProfile.SelectSingleNode('GameName')
            $gameLabel = if ($gameNameNode -and -not [string]::IsNullOrWhiteSpace($gameNameNode.InnerText)) { $gameNameNode.InnerText.Trim() } else { $pf.BaseName }
            $gunNode = $doc.GameProfile.SelectSingleNode("GunGame")
            if (-not $gunNode -or $gunNode.InnerText -ne "true") { continue }

            $emuType = ""
            $etNode = $doc.GameProfile.SelectSingleNode("EmulatorType")
            if ($etNode) { $emuType = $etNode.InnerText.Trim() }

            if ($emuType -eq "ElfLdr2") {
                if (-not $elfDir) {
                    Write-Host "    ElfLdr2: loader folder not found in TeknoParrot root -- skipped" -ForegroundColor Yellow
                    Write-Log ("Crosshairs: skipped {0}; ElfLdr2 folder not found in {1}" -f $gameLabel,$TpRoot)
                    [void]$crosshairSkippedGames.Add(('{0}: the ElfLdr2 loader folder was not found in the TeknoParrot folder, so no crosshairs were installed for it' -f $gameLabel))
                    $skipped++
                    continue
                }
                $dest = $elfDir
                if (-not $elfPlanned) {
                    [void]$targetPlans.Add([pscustomobject]@{ ItemId='ElfLdr2'; TargetDir=$dest })
                    $elfPlanned = $true
                }
                [void]$logicalDeployments.Add($gameLabel)
                continue
            }

            if ($emuType -eq "Pcsx2x6") {
                if (-not $pcsx2Planned -and -not $pcsx2SkipReason) {
                    if (-not $pcsx2Dir) {
                        Write-Host "    Pcsx2x6: emulator folder not found in TeknoParrot root -- skipped" -ForegroundColor Yellow
                        $pcsx2SkipReason = ('the Pcsx2x6 folder was not found in {0}' -f $TpRoot)
                        Write-Log ("Crosshairs: skipped {0}; PCSX2: {1}" -f $gameLabel,$pcsx2SkipReason)
                        $skipped++
                        [void]$crosshairSkippedGames.Add(('{0}: PCSX2 - {1}' -f $gameLabel,$pcsx2SkipReason))
                        continue
                    }
                    $prereqState = Get-Pcsx2CrosshairPrerequisiteState -Pcsx2Dir $pcsx2Dir
                    if ($prereqState.State -eq 'StockUninitialized') {
                        Write-Host ""
                        Write-Host "  PCSX2 Crosshair Setup Required" -ForegroundColor Cyan
                        Write-Log ("Crosshairs: PCSX2 is installed but not set up for TeknoParrot yet ({0})." -f $prereqState.Reason)
                        Write-Host "    TeknoParrot Manager found PCSX2, but it has not been set up for TeknoParrot yet." -ForegroundColor DarkGray
                        Write-Host "    TeknoParrot Manager can start PCSX2 once so it sets itself up, then add the crosshair files and check the result." -ForegroundColor DarkGray
                        $firstRunAnswer = Read-TpmYesNo -Prompt "  Configure Automatically? (Y/N)" -WorkflowContext $WorkflowContext
                        if ($firstRunAnswer -eq "Y") {
                            if (-not (Wait-TpmForProcessClose -ProcessNames @('pcsx2-qtx64') -FriendlyName 'PCSX2')) {
                                Write-Host "    PCSX2 crosshairs were skipped because PCSX2 is still open. Other crosshairs will still be installed." -ForegroundColor Yellow
                                Write-Log "Crosshairs: Pcsx2x6 first-run setup paused while process remained open"
                            } else {
                                $firstRun = Invoke-Pcsx2FirstRunSetup -State $prereqState
                                if ($firstRun.Success) {
                                    Write-Host "    PCSX2 is set up now." -ForegroundColor Green
                                    $prereqState = Get-Pcsx2CrosshairPrerequisiteState -Pcsx2Dir $pcsx2Dir
                                } else {
                                    Write-Host ("    FAILED: {0}" -f $firstRun.Reason) -ForegroundColor Red
                                    Write-Log "Crosshairs: Pcsx2x6 first-run setup failed -- $($firstRun.Reason)"
                                    $errors++
                                }
                            }
                        }
                    }
                    if ($prereqState.State -eq 'StockUninitialized') {
                        $pcsx2SkipReason = 'PCSX2 has not been set up for TeknoParrot yet and was not set up this time'
                        Write-Log ("Crosshairs: skipped {0}; PCSX2: {1}" -f $gameLabel,$pcsx2SkipReason)
                        $skipped++
                        [void]$crosshairSkippedGames.Add(('{0}: PCSX2 - {1}' -f $gameLabel,$pcsx2SkipReason))
                        continue
                    }
                    $assetCopyState = if ($prereqState.State -eq 'Unknown') { 'NotInstalled' } else { $prereqState.State }
                    if ($assetCopyState -eq 'NotInstalled') {
                        Write-Host ("    SKIPPED: Pcsx2x6 prerequisite state is {0}; no crosshair assets or cursor_path handling performed." -f $prereqState.State) -ForegroundColor Yellow
                        $pcsx2SkipReason = ('prerequisite state {0} ({1})' -f $prereqState.State,$prereqState.Reason)
                        Write-Log ("Crosshairs: skipped {0}; PCSX2: {1}" -f $gameLabel,$pcsx2SkipReason)
                        $skipped++
                        [void]$crosshairSkippedGames.Add(('{0}: PCSX2 - {1}' -f $gameLabel,$pcsx2SkipReason))
                        continue
                    }
                    $dataRoot = [string]$prereqState.DataRoot
                    if ([string]::IsNullOrWhiteSpace($dataRoot)) {
                        Write-Host ("    SKIPPED: Pcsx2x6 DataRoot could not be resolved for prerequisite state {0}; no crosshair assets or cursor_path handling performed." -f $prereqState.State) -ForegroundColor Yellow
                        $pcsx2SkipReason = ('DataRoot unavailable for prerequisite state {0}' -f $prereqState.State)
                        Write-Log ("Crosshairs: skipped {0}; PCSX2: {1}" -f $gameLabel,$pcsx2SkipReason)
                        $skipped++
                        [void]$crosshairSkippedGames.Add(('{0}: PCSX2 - {1}' -f $gameLabel,$pcsx2SkipReason))
                        continue
                    }
                    $crosshairSubDir = Join-Path $dataRoot "crosshairs"
                    [void]$targetPlans.Add([pscustomobject]@{ ItemId='Pcsx2x6'; TargetDir=$crosshairSubDir })
                    $pcsx2AssetDir = $crosshairSubDir
                    $pcsx2IniPath = $prereqState.IniPath
                    $pcsx2Planned = $true
                }
                if ($pcsx2SkipReason) {
                    Write-Log ("Crosshairs: skipped {0}; PCSX2: {1}" -f $gameLabel,$pcsx2SkipReason)
                    $skipped++
                    [void]$crosshairSkippedGames.Add(('{0}: PCSX2 - {1}' -f $gameLabel,$pcsx2SkipReason))
                    continue
                }
                [void]$logicalDeployments.Add($gameLabel)
                continue
            }

            $gpNode = $doc.GameProfile.SelectSingleNode("GamePath")
            if (-not $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { Write-Log ("Crosshairs: skipped {0}; the profile has no game path" -f $gameLabel); [void]$crosshairSkippedGames.Add(('{0}: the profile has no game path' -f $gameLabel)); $skipped++; continue }
            $gamePath = $gpNode.InnerText.Trim()
            $pathCheck = Test-TpmGameMutationPath -GamePath $gamePath -RequireLeaf -ProtectedRoots $ProtectedRoots
            if (-not $pathCheck.Valid) {
                if ($pathCheck.ReasonCode -eq 'SOURCE_COLLECTION') { [void]$sourceFolderGames.Add([string]$gameLabel) }
                else {
                    Write-Host ("    {0}: game path could not be safely verified -- skipped" -f $gameLabel) -ForegroundColor Yellow
                    [void]$crosshairSkippedGames.Add(('{0}: the saved game path could not be verified' -f $gameLabel))
                }
                Write-Log ("Crosshairs: skipped {0}; path reason={1}; detail={2}; saved path={3}" -f $pf.BaseName,$pathCheck.ReasonCode,$pathCheck.Reason,$gamePath)
                $skipped++
                continue
            }
            [void]$targetPlans.Add([pscustomobject]@{ ItemId=$pf.BaseName; TargetDir=[string]$pathCheck.GameDirectory })
            [void]$logicalDeployments.Add($gameLabel)
        } catch {
            Write-Host ("    FAILED {0}: {1}" -f $pf.BaseName,$_) -ForegroundColor Red
            Write-Log "Crosshairs: preflight error on $($pf.BaseName) -- $_"
            $errors++
        }
    }
    if ($profileScanTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Crosshair profile planning' -Current $profileScanCurrent -Total $profileScanTotal -StartedAt $profileScanStarted -Complete -Outcome $(if ($errors -eq 0) { 'Final' } else { 'Error' }) }

    # Every lightgun game was refused (source folder): nothing is left to deploy, so nothing is written. Not even the saved P1/P2 choice.
    $allGamesRefused = ($targetPlans.Count -eq 0 -and $sourceFolderGames.Count -gt 0)
    $transactionResult = if ($allGamesRefused) {
        New-TpmFileBatchResult -WorkflowKey 'CrosshairSetup' -OperationKey 'P1P2' -Outcome 'NO_OP' -ProductState 'UNCHANGED' `
            -Summary 'Every lightgun game is inside your source folder, so nothing was changed.' -ReasonCode 'SOURCE_COLLECTION' `
            -FinalAttempted $true -FinalPassed $true -FinalChecks @('Every lightgun game was checked: all are inside the source folder and were refused; no file was written.')
    } else {
        Invoke-TpmCrosshairAssetTransaction `
            -P1Source $valid[$p1Idx] -P2Source $valid[$p2Idx] `
            -Targets $targetPlans.ToArray() -StatePath $crosshairStatePath `
            -P1Name $p1Name -P2Name $p2Name
    }
    if ($transactionResult.Outcome -in @('SUCCEEDED','NO_OP')) {
        $deployed = $logicalDeployments.Count
        foreach ($target in $targetPlans) {
            Write-Log ("Crosshairs: verified P1/P2 deployment to $($target.TargetDir)")
        }
    } else {
        $errors++
        $transactionMessage = switch ([string]$transactionResult.Outcome) {
            'CLEANUP_RESIDUE' { if ([string]$transactionResult.UnderlyingOutcome -eq 'SUCCEEDED') { 'The crosshair files were installed and verified, but TeknoParrot Manager could not remove its temporary files.' } else { 'Crosshair setup did not finish. The previous files were restored and verified, but TeknoParrot Manager could not remove its temporary files.' } }
            'ACTION_REQUIRED' { 'Crosshair setup could not verify the final file state. Do not retry blindly; see TeknoParrot-Manager.log.' }
            'FAILED_BEFORE_MUTATION' { 'Crosshair setup stopped before any file was changed. See TeknoParrot-Manager.log for the reason, then retry.' }
            default { 'Crosshair setup did not complete. See TeknoParrot-Manager.log for the reason before retrying.' }
        }
        Write-Host ("  {0}" -f $transactionMessage) -ForegroundColor Yellow
        Write-Log ("Crosshairs: P1/P2 transaction outcome={0} reason={1} errors={2}" -f $transactionResult.Outcome,$transactionResult.ReasonCode,(@($transactionResult.Errors) -join ' | '))
    }

    # cursor_path remains an emulator-owned, separately-gated action. It is
    # intentionally not part of the P1/P2 file transaction.
    if ($pcsx2AssetDir -and $transactionResult.Outcome -in @('SUCCEEDED','NO_OP') -and $pcsx2IniPath -and (Test-Path -LiteralPath $pcsx2IniPath)) {
        # cursor_path is emulator-owned (contracts\pcsx2x6\contract.json, WritePolicy NeverWrite): it is reported, never written.
        Write-Host '    NOTE: The PCSX2 cursor setting was left alone because PCSX2 manages it itself. The log says why.' -ForegroundColor Yellow
        Write-Log 'Crosshairs: skipped PCSX2.ini cursor_path write -- the pcsx2x6 contract marks it emulator-owned (NeverWrite).'
        $iniStatus = 'PNGs copied; PCSX2.ini cursor_path was not changed because PCSX2 manages it'
        Write-Log ('Crosshairs: Pcsx2x6 {0} ({1})' -f $pcsx2Dir,$iniStatus)
        [void]$crosshairEmulatorNotes.Add(('PCSX2 folder: {0}' -f $pcsx2Dir))
        [void]$crosshairEmulatorNotes.Add(('PCSX2 settings: {0}' -f $iniStatus))
        $cursorReport = Get-Pcsx2CursorPathReport -IniPath $pcsx2IniPath
        if ($cursorReport.Available) {
            $usb1Display = if ($cursorReport.USB1CursorPath) { $cursorReport.USB1CursorPath } else { "(not set)" }
            $usb2Display = if ($cursorReport.USB2CursorPath) { $cursorReport.USB2CursorPath } else { "(not set)" }
            [void]$crosshairEmulatorNotes.Add(('cursor_path: USB1={0}  USB2={1}  (emulator-managed; PCSX2 clears this automatically when JVS mode is LIGHTGUN -- no action needed)' -f $usb1Display,$usb2Display))
        }
    }

    Write-Host ""
    if ($transactionResult.Outcome -notin @('SUCCEEDED','NO_OP')) {
        # The message above already says what went wrong.
    } elseif ($targetPlans.Count -eq 0) {
        if ($skipped -eq 0) { Write-TpmText -Text 'No lightgun games were found, so no crosshair files were copied.' -Color DarkGray }
    } elseif ($transactionResult.Outcome -eq 'NO_OP') {
        Write-TpmText -Text 'The crosshair files were already up to date.' -Color DarkGray
    } else {
        Write-TpmText -Text 'The crosshair files were copied and checked.' -Color Green
    }
    $otherSkipped = $skipped - $sourceFolderGames.Count
    if ($otherSkipped -gt 0) { Write-TpmText -Text ('{0} skipped. The log says why.' -f (Format-TpmGameCount -Count $otherSkipped)) -Color Yellow }
    Write-TpmSourceFolderRefusal -Count $sourceFolderGames.Count
    if ($errors -gt 0) { Write-TpmText -Text ('{0} found. The log says what happened.' -f (Format-TpmCountNoun -Count $errors -Singular 'problem')) -Color Red }
    Write-Log ("Crosshairs: transaction={0} targetFolders={1} logicalProfiles={2} skipped={3} errors={4}" -f $transactionResult.Outcome,$targetPlans.Count,$deployed,$skipped,$errors)

    $hideCursor = 'N'
    if ($allGamesRefused) {
        Write-Log 'Crosshairs: cursor-hide setup not offered because every lightgun game was refused; no profile was changed.'
    } elseif ($errors -eq 0) {
        $hideCursor = Read-TpmYesNo -Prompt "  Also hide the Windows cursor for all lightgun games? (Y/N)" -WorkflowContext $WorkflowContext
    } else {
        Write-Host '  Cursor hiding was not offered because crosshair setup needs attention. Review the failure before retrying.' -ForegroundColor Yellow
        Write-Log 'Crosshairs: cursor-hide setup not offered after an unverified deployment or cursor-path result.'
    }
    $cursorResult = $null
    $cursorSucceeded = $true
    if ($hideCursor -eq "Y") {
        Write-Host ""
        $cursorResult = Invoke-CursorHideSetup -UserProfilesDir $UserProfilesDir
        $cursorSucceeded = ($cursorResult -and $cursorResult.PSObject.Properties['Outcome'] -and $cursorResult.Outcome -in @('SUCCEEDED','NO_OP'))
        if (-not $cursorSucceeded) {
            Write-Host "  Hiding the cursor did not finish. The log says why. Try again after you have read it." -ForegroundColor Yellow
            Write-Log "Crosshairs: cursor-hide transaction did not complete; crosshair files may already have been deployed."
        }
    }
    $crosshairNoOp = ($transactionResult.Outcome -eq 'NO_OP' -and $errors -eq 0 -and $cursorSucceeded -and
        ($null -eq $cursorResult -or [string]$cursorResult.Outcome -eq 'NO_OP'))
    # A game skipped on purpose (source folder, declined PCSX2 first run, missing folder) never undoes files that were copied and checked, and the
    # all-skipped case is the deliberate no-change result. The screen already says how many were skipped and why.
    $crosshairSucceeded = ($transactionResult.Outcome -in @('SUCCEEDED','NO_OP') -and $errors -eq 0 -and $cursorSucceeded)
    $crosshairOutcome = if (-not $crosshairSucceeded) { 'ACTION_REQUIRED' } elseif ($crosshairNoOp) { 'NO_OP' } else { 'SUCCEEDED' }
    return [pscustomobject]@{
        Outcome=$crosshairOutcome
        Succeeded=$crosshairSucceeded
        NoOp=$crosshairNoOp
        NoTargets=($targetPlans.Count -eq 0)
        Deployed=$deployed
        Skipped=$skipped
        Errors=($errors + $(if($cursorSucceeded){0}else{1}))
        CursorResult=$cursorResult
        TransactionResult=$transactionResult
        DeployedGames=@($logicalDeployments.ToArray())
        P1Name=$(if ($allGamesRefused) { '' } else { $p1Name })
        P2Name=$(if ($allGamesRefused) { '' } else { $p2Name })
        TargetFolders=@($targetPlans | ForEach-Object { [pscustomobject]@{ Item=[string]$_.ItemId; Folder=[string]$_.TargetDir } })
        EmulatorNotes=@($crosshairEmulatorNotes.ToArray())
        SourceFolderGames=@($sourceFolderGames.ToArray())
        SkippedGames=@($crosshairSkippedGames.ToArray())
    }
}
# Sets the cursor-hide field (HideCursor / "Hide Cursor" / DisableCursor) to 1
# in every registered lightgun UserProfile. Backs up UserProfiles first since
# it modifies XMLs. Skips profiles that have no cursor field or are already set.
function Invoke-CursorHideSetup {
    param([string]$UserProfilesDir)

    $cursorFields = @('HideCursor','Hide Cursor','DisableCursor')
    try {
        $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'CursorHide profile discovery' -EnumerationErrorAction Stop | Sort-Object BaseName)
    } catch {
        Write-Host '  Cursor-hiding setup stopped: TeknoParrot Manager could not read the UserProfiles folder, so it could not check whether any change is needed. Nothing was changed.' -ForegroundColor Red
        Write-Log ("CursorHide: UserProfiles could not be read -- {0}" -f $_.Exception.Message)
        return (New-TpmProfileTransactionResult -WorkflowKey 'CrosshairSetup' -OperationKey 'CursorHide' -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' -Summary 'Cursor-hiding setup stopped before changing your profiles because the UserProfiles folder could not be read.' -Items @('UserProfiles') -FailedItems @('UserProfiles') -ReasonCode 'PROFILE_SCAN_INCOMPLETE' -FinalChecks @('No cursor XML write was attempted.'))
    }
    $progressStarted = Get-Date
    $profileScanCurrent = 0
    $eligible = New-Object System.Collections.Generic.List[string]
    $plans = New-Object System.Collections.Generic.List[object]
    $alreadySet = 0; $noField = 0
    $planFailed = New-Object System.Collections.Generic.List[string]
    foreach ($pf in $profiles) {
        $profileScanCurrent++
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'CursorHide profile scan' -Current $profileScanCurrent -Total $profiles.Count -StartedAt $progressStarted
        try {
            $doc = Read-Xml $pf.FullName
            $gunNode = if ($doc.GameProfile) { $doc.GameProfile.SelectSingleNode('GunGame') } else { $null }
            if (-not $gunNode -or $gunNode.InnerText -ne 'true') { continue }
            $fields = @()
            foreach ($fieldName in $cursorFields) {
                $fi = $doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral $fieldName)]")
                if ($fi) { $fv=$fi.SelectSingleNode('FieldValue'); if ($fv) { $fields += [pscustomobject]@{ Name=$fieldName; Value=$fv.InnerText } } }
            }
            if ($fields.Count -eq 0) { $noField++; continue }
            [void]$eligible.Add($pf.BaseName)
            if (@($fields | Where-Object Value -ne '1').Count -eq 0) { $alreadySet++; continue }
            [void]$plans.Add([pscustomobject]@{ ProfileId=$pf.BaseName; ProfileFile=$pf; SourceHash=(Get-FileHash -LiteralPath $pf.FullName -Algorithm SHA256 -ErrorAction Stop).Hash })
        } catch { [void]$planFailed.Add($pf.BaseName); Write-Host ("    FAILED  {0}: profile could not be inspected" -f $pf.BaseName) -ForegroundColor Red; Write-Log "CursorHide: planning failed for $($pf.BaseName) -- $_" }
    }
    # A profile that could not be inspected is a failed scan item: the scan stage must not close as done.
    if ($profiles.Count -gt 0) { Write-TpmCompactExtractionProgress -Phase Scanning -Label 'CursorHide profile scan' -Current $profileScanCurrent -Total $profiles.Count -StartedAt $progressStarted -Complete -Outcome $(if ($planFailed.Count -eq 0) { 'Final' } else { 'Error' }) }
    if ($plans.Count -eq 0 -and $planFailed.Count -gt 0) {
        Write-Host '  Cursor-hiding setup stopped: some profiles could not be inspected, so TeknoParrot Manager cannot say no change is needed. Nothing was changed.' -ForegroundColor Red
        return (New-TpmProfileTransactionResult -WorkflowKey 'CrosshairSetup' -OperationKey 'CursorHide' -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' -Summary 'Cursor-hiding setup stopped before changing your profiles because some profiles could not be inspected.' -Items (@($eligible.ToArray()) + @($planFailed.ToArray())) -FailedItems $planFailed.ToArray() -ReasonCode 'PROFILE_SCAN_INCOMPLETE' -FinalChecks @('No cursor XML write was attempted.'))
    }
    if ($plans.Count -eq 0) {
        Write-Host '  No cursor-hiding profile changes are needed. Nothing was changed.' -ForegroundColor DarkGray
        Write-Log ("CursorHide setup: NO_OP. Eligible={0} AlreadySet={1} NoField={2}" -f $eligible.Count,$alreadySet,$noField)
        return (New-TpmProfileTransactionResult -WorkflowKey 'CrosshairSetup' -OperationKey 'CursorHide' -Outcome 'NO_OP' -ProductState 'UNCHANGED' -Summary 'All eligible cursor-hiding profiles are already current.' -Items $eligible.ToArray() -ReasonCode 'NO_ELIGIBLE_CHANGES' -FinalChecks @('All candidate lightgun profiles were scanned before mutation.'))
    }

    $backup = New-TpmVerifiedUserProfilesBackup -UserProfilesDir $UserProfilesDir -Label 'CursorHide'
    if (-not $backup.Verified) {
        Write-Host '  Cursor-hiding setup stopped before changing your profiles.' -ForegroundColor Red
        Write-Host '  TeknoParrot Manager could not verify the safety backup.' -ForegroundColor Red
        Write-Host '  Nothing was changed to cursor settings.' -ForegroundColor Green
        Write-Log ("CursorHide: verified backup gate failed at {0} -- {1}" -f $backup.FailureStage,$backup.Reason)
        return (New-TpmProfileTransactionResult -WorkflowKey 'CrosshairSetup' -OperationKey 'CursorHide' -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' -Summary 'Cursor-hiding setup stopped before changing your profiles because the safety backup could not be verified.' -Items @() -Backup $backup -ReasonCode 'PROFILE_BACKUP_FAILED' -FinalChecks @('No cursor XML write was attempted.'))
    }

    $revalidationCurrent = 0
    $revalidationPassed = $false
    try {
        foreach ($plan in $plans) {
            $revalidationCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'CursorHide profile revalidation' -Current $revalidationCurrent -Total $plans.Count -StartedAt $progressStarted
            if ((Get-FileHash -LiteralPath $plan.ProfileFile.FullName -Algorithm SHA256 -ErrorAction Stop).Hash -ine [string]$plan.SourceHash) {
                return (New-TpmProfileTransactionResult -WorkflowKey 'CrosshairSetup' -OperationKey 'CursorHide' -Outcome 'ACTION_REQUIRED' -ProductState 'UNKNOWN' -Summary 'Cursor-hiding setup needs attention because a profile changed before it could be updated.' -Items @($plans | ForEach-Object ProfileId) -Backup $backup -ReasonCode 'PROFILE_CHANGED_BEFORE_WRITE' -MutationStarted $false -FinalPassed $false -FinalChecks @('Source profile revalidation failed before the first XML write.'))
            }
            $current = Read-Xml $plan.ProfileFile.FullName
            $gunNode = if ($current.GameProfile) { $current.GameProfile.SelectSingleNode('GunGame') } else { $null }
            $needs = @($cursorFields | ForEach-Object { $fi=$current.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral $_)]"); if($fi){$fv=$fi.SelectSingleNode('FieldValue'); if($fv -and $fv.InnerText -ne '1'){$true}} })
            if (-not $gunNode -or $gunNode.InnerText -ne 'true' -or $needs.Count -eq 0) {
                return (New-TpmProfileTransactionResult -WorkflowKey 'CrosshairSetup' -OperationKey 'CursorHide' -Outcome 'ACTION_REQUIRED' -ProductState 'UNKNOWN' -Summary 'Cursor-hiding setup needs attention because a profile changed before it could be updated.' -Items @($plans | ForEach-Object ProfileId) -Backup $backup -ReasonCode 'PROFILE_PLAN_CHANGED' -MutationStarted $false -FinalPassed $false -FinalChecks @('Source profile revalidation failed before the first XML write.'))
            }
        }
        $revalidationPassed = $true
    } finally {
        # The early ACTION_REQUIRED returns and any read/hash exception are revalidation failures: close Error with the
        # profiles actually revalidated, never "done" for the profile that failed.
        if ($plans.Count -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'CursorHide profile revalidation' -Current $(if ($revalidationPassed) { $revalidationCurrent } else { [Math]::Max(0, $revalidationCurrent - 1) }) -Total $plans.Count -StartedAt $progressStarted -Complete -Outcome $(if ($revalidationPassed) { 'Final' } else { 'Error' }) }
    }

    # Update and final-verification bars count profiles that were written and read back as set, not attempts, so a
    # caught per-profile failure is never counted as finished work.
    $completed = New-Object System.Collections.Generic.List[string]
    foreach ($plan in $plans) {
        Write-TpmCompactExtractionProgress -Phase Repairing -Label 'CursorHide profile update' -Current $completed.Count -Total $plans.Count -StartedAt $progressStarted -Completed
        try {
            $doc = Read-Xml $plan.ProfileFile.FullName
            foreach ($fieldName in $cursorFields) {
                $fi=$doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral $fieldName)]")
                if ($fi) { $fv=$fi.SelectSingleNode('FieldValue'); if($fv){$fv.InnerText='1'} }
            }
            Save-Xml $doc $plan.ProfileFile.FullName
            $verify=Read-Xml $plan.ProfileFile.FullName
            $remaining=@($cursorFields | ForEach-Object { $fi=$verify.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral $_)]"); if($fi){$fv=$fi.SelectSingleNode('FieldValue'); if($fv -and $fv.InnerText -ne '1'){$true}} })
            if($remaining.Count -gt 0){throw 'Cursor-hide read-back verification failed.'}
            [void]$completed.Add($plan.ProfileId)
            Write-Log ("CursorHide: updated {0}" -f $plan.ProfileId)
        } catch { Write-Host ("    FAILED  {0}: profile was not verified" -f $plan.ProfileId) -ForegroundColor Red; Write-Log "CursorHide: FAILED $($plan.ProfileId) -- $_" }
    }
    # Each update is caught per profile: the stage is done only when every profile was written and read back.
    if ($plans.Count -gt 0) {
        if ($completed.Count -lt $plans.Count) { Write-TpmCompactExtractionProgress -Phase Repairing -Label 'CursorHide profile update' -Current $completed.Count -Total $plans.Count -StartedAt $progressStarted -Completed }
        Write-TpmCompactExtractionProgress -Phase Repairing -Label 'CursorHide profile update' -Current $completed.Count -Total $plans.Count -StartedAt $progressStarted -Complete -Outcome $(if ($completed.Count -eq $plans.Count) { 'Final' } else { 'Error' })
    }
    $failed = New-Object System.Collections.Generic.List[string]
    $unknownFinal = New-Object System.Collections.Generic.List[string]
    $verifiedCount = 0
    foreach ($plan in $plans) {
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'CursorHide final verification' -Current $verifiedCount -Total $plans.Count -StartedAt $progressStarted -Completed
        try {
            $verify=Read-Xml $plan.ProfileFile.FullName
            $remaining=@($cursorFields | ForEach-Object { $fi=$verify.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral $_)]"); if($fi){$fv=$fi.SelectSingleNode('FieldValue'); if($fv -and $fv.InnerText -ne '1'){$true}} })
            if($remaining.Count -gt 0){[void]$failed.Add($plan.ProfileId)} else { $verifiedCount++; if($completed -notcontains $plan.ProfileId){[void]$completed.Add($plan.ProfileId)} }
        } catch {[void]$unknownFinal.Add($plan.ProfileId)}
    }
    # A profile still unset (failed) or unreadable (state unknown) means final verification did not pass.
    if ($plans.Count -gt 0) {
        if ($verifiedCount -lt $plans.Count) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'CursorHide final verification' -Current $verifiedCount -Total $plans.Count -StartedAt $progressStarted -Completed }
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'CursorHide final verification' -Current $verifiedCount -Total $plans.Count -StartedAt $progressStarted -Complete -Outcome $(if ($failed.Count -eq 0 -and $unknownFinal.Count -eq 0) { 'Final' } else { 'Error' })
    }
    $allIds=@($plans | ForEach-Object ProfileId)
    if($unknownFinal.Count -gt 0){$outcome='ACTION_REQUIRED';$state='UNKNOWN';$summary='Cursor-hiding setup needs attention because the final profile state could not be verified.';$passed=$false;$reason='PROFILE_FINAL_STATE_UNKNOWN'}
    elseif($failed.Count -gt 0 -or $planFailed.Count -gt 0){$outcome='PARTIAL_APPLIED';$state='PARTIAL_KNOWN';$summary='Some cursor-hiding profiles were updated, but the operation did not finish.';$passed=$true;$reason='PROFILE_SAVE_PARTIAL'}
    else{$outcome='SUCCEEDED';$state='INTENDED';$summary='Cursor-hiding profiles were updated and verified.';$passed=$true;$reason='PROFILE_UPDATES_VERIFIED'}
    if($failed.Count -gt 0){Write-Host ("  Failed   : {0} profile(s) -- review Details before retrying" -f $failed.Count) -ForegroundColor Red}
    Write-Log ("CursorHide: done. Updated={0} AlreadySet={1} NoField={2} Failed={3}" -f $completed.Count,$alreadySet,$noField,$failed.Count)
    return (New-TpmProfileTransactionResult -WorkflowKey 'CrosshairSetup' -OperationKey 'CursorHide' -Outcome $outcome -ProductState $state -Summary $summary -Items (@($eligible.ToArray()) + @($planFailed.ToArray())) -ChangedItems $allIds -CompletedItems $completed.ToArray() -FailedItems (@($failed.ToArray()) + @($planFailed.ToArray())) -UnknownItems $unknownFinal.ToArray() -MutationStarted $true -Backup $backup -FinalPassed $passed -ReasonCode $reason -FinalChecks @('Every intended cursor field was read back after its write.'))
}

# FIX82: the Crosshair result screen (menu 4). Games are listed by name only; every folder the files went to, the PCSX2 settings and the
# games whose cursor was hidden are in the Details view (key D) and the log.
function Get-TpmCrosshairResultView {
    param([Parameter(Mandatory)]$Result)
    $games = @(Get-TpmTransactionField -Object $Result -Name 'DeployedGames' -Default @() | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Sort-Object -Unique)
    $noOp = [bool](Get-TpmTransactionField -Object $Result -Name 'NoOp' -Default $false)
    $noTargets = [bool](Get-TpmTransactionField -Object $Result -Name 'NoTargets' -Default $false)
    $p1 = [string](Get-TpmTransactionField -Object $Result -Name 'P1Name' -Default '')
    $p2 = [string](Get-TpmTransactionField -Object $Result -Name 'P2Name' -Default '')
    $cursorMutation = Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'CursorResult') -Name 'Mutation'
    $hidden = @(Get-TpmTransactionField -Object $cursorMutation -Name 'CompletedItems' -Default @() | Where-Object { $_ })
    $title = ('Crosshairs are set up for {0}.' -f (Format-TpmGameCount -Count $games.Count))
    $refusedCount = @(Get-TpmTransactionField -Object $Result -Name 'SourceFolderGames' -Default @()).Count
    $otherSkipped = [int](Get-TpmTransactionField -Object $Result -Name 'Skipped' -Default 0) - $refusedCount
    if ($noTargets -and $otherSkipped -gt 0) {
        $title = if ($noOp) { 'Your lightgun games were skipped, so nothing was changed.' } else { 'Your crosshair choice was saved, but your lightgun games were skipped, so none were updated.' }
    }
    elseif ($noTargets -and $refusedCount -gt 0) { $title = 'Your lightgun games are inside your source folder, so nothing was changed.' }
    elseif ($noTargets -and $noOp) { $title = 'No lightgun games were found. Nothing was changed.' }
    elseif ($noTargets) { $title = 'Your crosshair choice was saved. No lightgun games were found to update.' }
    elseif ($noOp) { $title = 'The crosshairs were already set up. Nothing was changed.' }
    $done = New-Object System.Collections.Generic.List[string]
    if ($p1 -and $p2) { [void]$done.Add(('Player 1 uses {0}. Player 2 uses {1}.' -f $p1, $p2)) }
    if ($games.Count -gt 0 -and -not $noTargets) {
        $shown = @($games | Select-Object -First 6)
        $list = Join-TpmPostgresSetupNames -Names $shown
        if ($games.Count -gt $shown.Count) { $list = ($shown -join ', ') + (' and {0} more' -f ($games.Count - $shown.Count)) }
        [void]$done.Add('Games: ' + $list)
    }
    if ($hidden.Count -gt 0) { [void]$done.Add(('The Windows cursor is now hidden in {0}.' -f (Format-TpmGameCount -Count $hidden.Count))) }
    $next = 'Start a lightgun game to try the new crosshairs.'
    if ($noTargets -and $otherSkipped -gt 0) { $next = 'The log says why each game was skipped. Fix that, then run Crosshairs again.' }
    elseif ($noTargets -and $refusedCount -gt 0) { $next = 'Move the game out of your source folder, or fix the game folder in its profile. Then run Crosshairs again.' }
    elseif ($noTargets -or $noOp) { $next = 'Nothing else to do.' }
    $blocks = New-Object System.Collections.Generic.List[object]
    $choice = New-Object System.Collections.Generic.List[string]
    Add-TpmDetailLine -Lines $choice -Label 'Player 1' -Text $p1
    Add-TpmDetailLine -Lines $choice -Label 'Player 2' -Text $p2
    if ($choice.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Your crosshair choice'; Lines = $choice.ToArray() }) }
    if ($games.Count -gt 6) { [void]$blocks.Add(@{ Heading = ('All games ({0})' -f $games.Count); Lines = @($games -join ', ') }) }
    $folders = @(Get-TpmTransactionField -Object $Result -Name 'TargetFolders' -Default @() | Where-Object { $null -ne $_ } | ForEach-Object { '{0}: {1}' -f [string]$_.Item, [string]$_.Folder })
    if ($folders.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Where the crosshair files went'; Lines = $folders }) }
    $emulatorNotes = @(Get-TpmTransactionField -Object $Result -Name 'EmulatorNotes' -Default @() | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    if ($emulatorNotes.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'PCSX2'; Lines = $emulatorNotes }) }
    $skippedGameLines = @(Get-TpmTransactionField -Object $Result -Name 'SkippedGames' -Default @() | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    if ($skippedGameLines.Count -gt 0) { [void]$blocks.Add(@{ Heading = ('Skipped games ({0})' -f $skippedGameLines.Count); Lines = $skippedGameLines }) }
    if ($hidden.Count -gt 0) { [void]$blocks.Add(@{ Heading = ('Cursor hidden ({0})' -f $hidden.Count); Lines = @($hidden -join ', ') }) }
    return @{ Title = $title; Status = 'Ok'; Done = $done.ToArray(); Next = $next; DetailBlocks = $blocks.ToArray() }
}

function Show-TpmCrosshairResult {
    param([Parameter(Mandatory)]$Result, [switch]$Unattended)
    $view = Get-TpmCrosshairResultView -Result $Result
    Write-TpmOutcome @view -Unattended:$Unattended
}

# =============================================================================
# Validates one RAW ZIP entry name and returns its normalized relative path.
# Governing source: PKWARE APPNOTE.TXT 6.3.10 section 4.4.17.1 -- a stored
# path MUST NOT contain a drive or device letter or a leading slash. The raw
# name is checked BEFORE separator normalization, so '/x', '\x', '//server/x'
# and '\\server\x' are rejected instead of being silently re-rooted under the
# destination. Interior backslashes are still accepted as separators (real
# Windows-produced archives contain them; APPNOTE's forward-slash-only rule is
# deliberately not enforced -- see ARCHITECTURE.md). Pure: no filesystem access.
function ConvertTo-SafeZipEntryRelativePath {
    param([string]$EntryName)
    if ([string]::IsNullOrEmpty($EntryName)) { throw 'ZIP entry has an empty name.' }
    if ($EntryName[0] -eq [char]'/' -or $EntryName[0] -eq [char]'\') {
        throw "ZIP entry escapes destination folder (rooted or UNC name): $EntryName"
    }
    # A colon can only mean a drive letter, a drive-relative path (C:x), or an
    # NTFS alternate data stream (file:stream) -- never a plain file name.
    if ($EntryName.IndexOf([char]':') -ge 0) {
        throw "ZIP entry escapes destination folder (drive, device, or stream name): $EntryName"
    }
    $normalized = $EntryName.Replace('/', '\')
    $isDirectory = $normalized.EndsWith('\')
    if ($isDirectory) { $normalized = $normalized.Substring(0, $normalized.Length - 1) }
    if ($normalized.Length -eq 0) { throw "ZIP entry has an empty path: $EntryName" }
    $invalid = [System.IO.Path]::GetInvalidFileNameChars()
    foreach ($segment in $normalized.Split([char]'\')) {
        if ($segment.Length -eq 0) { throw "ZIP entry contains an empty path segment: $EntryName" }
        if ($segment -eq '.' -or $segment -eq '..') { throw "ZIP entry escapes destination folder (dot segment): $EntryName" }
        # \\?\ paths bypass Win32 normalization, so a trailing dot or space
        # would create a name ordinary Windows tools cannot open or delete.
        if ($segment.EndsWith('.') -or $segment.EndsWith(' ')) { throw "ZIP entry has a segment ending in a dot or space: $EntryName" }
        if ($segment.IndexOfAny($invalid) -ge 0) { throw "ZIP entry contains characters that are invalid in Windows file names: $EntryName" }
        # Reserved device names per Microsoft "Naming Files, Paths, and
        # Namespaces": CON, PRN, AUX, NUL, COM1-9, LPT1-9, and COM/LPT with
        # superscript 1/2/3 (U+00B9, U+00B2, U+00B3), also when followed by
        # an extension. COM0, LPT0 and COM10 are not reserved. Through \\?\
        # these would become real files ordinary tools cannot open or delete.
        if ($segment.Split([char]'.')[0] -match '^(?i:CON|PRN|AUX|NUL|COM[1-9\u00B9\u00B2\u00B3]|LPT[1-9\u00B9\u00B2\u00B3])$') { throw "ZIP entry uses a reserved Windows device name: $EntryName" }
    }
    if ([System.IO.Path]::IsPathRooted($normalized)) { throw "ZIP entry escapes destination folder: $EntryName" }
    return [pscustomobject]@{ RelativePath = $normalized; IsDirectory = $isDirectory }
}

# Extracts a ZIP to a destination directory using \\?\ extended-length paths on
# every file write, bypassing Windows' 260-character MAX_PATH limit. Replaces
# ZipFile::ExtractToDirectory which throws PathTooLongException for games with
# deeply-nested internal paths. Every entry name, archive-internal collision, and destination file/directory shape conflict is preflighted before any write. The checks are lexical and path-shape only, not a transaction or filesystem-identity guarantee.
function Import-TpmProgressModule {
    # Exactly one TpmProgress module per session. Import-Module -Force from a second path (another TPM folder, or a
    # test fixture copy) loads a second module with the same name beside the first, so a copy from any other path is
    # removed before this script's own copy is imported. The copy this function imported is kept as it is.
    $modulePath = [System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot 'scripts\TpmProgress.psm1'))
    $loaded = @(Get-Module -Name TpmProgress -All)
    $current = $false
    if ($loaded.Count -eq 1) {
        $loadedPath = [string]$loaded[0].Path
        $current = ([string]::Equals($loadedPath, $modulePath, [System.StringComparison]::OrdinalIgnoreCase) -or
            [string]::Equals($loadedPath, [string]$script:TpmProgressModuleLoadedPath, [System.StringComparison]::OrdinalIgnoreCase))
    }
    if (-not $current) {
        if ($loaded.Count -gt 0) { $loaded | Remove-Module -Force -ErrorAction Stop }
        $imported = Import-Module $modulePath -Force -PassThru -ErrorAction Stop
        $script:TpmProgressModuleLoadedPath = [string]@($imported)[0].Path
    }
    # Lets the Write-Host proxy coordinate with an open bar without a module lookup on every call.
    $script:TpmProgressModuleImported = $true
    # A drawing failure is written to this log and never reaches the work being reported on (the module disables that renderer).
    Set-TpmProgressRenderLogger -Logger { param([string]$Message) Write-Log $Message }
}

# One blocking call that reports nothing while it runs (a PostgreSQL tool, a web request, a service change): the open progress
# step reads "still working" instead of "stalled" for as long as it runs, and the count stays. Enter-TpmLongWait returns $true
# when it set the mark; the caller then calls Exit-TpmLongWait in a finally block. A display problem never stops the work
# (genuine cancellation still propagates). Callers check that Enter-TpmLongWait exists first (code that loads only some functions).
function Enter-TpmLongWait {
    # A bar exists only after the progress module is loaded, so without it there is nothing to mark.
    if (-not (Get-Command -Name Start-TpmProgressLongWait -ErrorAction SilentlyContinue)) { return $false }
    try { return [bool](Start-TpmProgressLongWait) }
    catch {
        if (Test-TpmProgressCancellationError -ErrorRecord $_) { throw }
        return $false
    }
}

function Exit-TpmLongWait {
    try { Stop-TpmProgressLongWait }
    catch { if (Test-TpmProgressCancellationError -ErrorRecord $_) { throw } }
}

# Count contract (RC8 #347): the bar and its "n/m" text always show FINISHED units, never started ones.
#   - Non-Complete call with -Total > 0: -Current is the 1-based ordinal of the item whose work is about to start
#     (the historical "$i++; render; work" loop idiom), so the displayed finished count is Current-1 (never below 0).
#     Pass -Completed when -Current already is a finished-unit count (bytes copied, items already processed).
#   - -Complete with Outcome Final and -Total > 0: -Current (when supplied) is recorded as the finished count, because
#     Final is only reached after the last item's work ran. Error/Cancelled keep the last rendered finished count.
#   - -Total 0 means the total is unknown; spinner and count only, no percent, and -Current is not interpreted.
#   - -Unit Bytes shows -Current/-Total as sizes (KB/MB/GB); the default Items shows plain counts.
#   - -LongStep marks a step that is ONE long external job with no count (an installer). While it runs the bar says
#     "still working" instead of a stall warning. The next stage update or the -Complete call ends the mark.
#   - -NotAvailable (with -Complete, inside a group) closes a step whose answer was "not found online": the group is not marked
#     failed (nothing went wrong), but the step never reads "done".
# This wrapper is the single entry point to the shared renderer (scripts\TpmProgress.psm1). A running bar never
# shows 100% (the renderer caps it at 99%); only a Final close with every unit finished does. Group-owned bars show
# each stage's own count/percent; only the owning workflow closes the group bar.
function Write-TpmCompactExtractionProgress {
    param([ValidateSet('Scanning','Extracting','Repairing','Checking','Backing up','Saving','Restoring','Promoting','Installing')][string]$Phase = 'Extracting', [string]$Label, [long]$Current, [long]$Total, [datetime]$StartedAt = (Get-Date), [int]$Width = 0, [switch]$Complete, [switch]$Substage, [ValidateSet('Final','Error','Cancelled')][string]$Outcome = 'Final', [switch]$ReturnText, [switch]$Completed, [ValidateSet('Items','Bytes')][string]$Unit = 'Items', [switch]$LongStep, [switch]$NotAvailable)
    Import-TpmProgressModule
    # A display problem never stops the work it reports on: anything but genuine cancellation is logged and dropped.
    try {
        # Users see a short plain label. The internal label goes to the log once, when the step starts.
        # The lookup is skipped when the helper is not loaded (tests that load only this function).
        # A plain label already says the action, so the phase word is not put in front of it again ("Checking: Checking ...").
        $labelIsPlain = $false
        if (-not [string]::IsNullOrEmpty($Label) -and (Test-Path -LiteralPath 'Function:\Get-TpmFriendlyProgressLabel')) {
            $internalLabel = $Label
            $Label = Get-TpmFriendlyProgressLabel -Label $internalLabel
            $labelIsPlain = ($Label -cne $internalLabel)
            if (-not $Complete -and $labelIsPlain -and -not (Get-Variable -Name TpmStartupLogFrozen -Scope Script -ValueOnly -ErrorAction SilentlyContinue)) {
                $lastLoggedLabel = Get-Variable -Name TpmLastLoggedProgressLabel -Scope Script -ValueOnly -ErrorAction SilentlyContinue
                if ($lastLoggedLabel -cne $internalLabel) {
                    Set-Variable -Name TpmLastLoggedProgressLabel -Scope Script -Value $internalLabel
                    Write-Log ('Progress step: {0} (shown as "{1}")' -f $internalLabel, $Label)
                }
            }
        }
        $unitArgs = @{}
        if ($Unit -ne 'Items') { $unitArgs['Unit'] = $Unit }
        # Only a marked long step passes -LongStep, so every other call is exactly what it was before FIX123.
        $longArgs = @{}
        if ($LongStep) { $longArgs['LongStep'] = $true }
        # These CPS3 phases are distinct measured work; retain each completed row
        # instead of restarting percentages on the workflow's shared stage.
        if ((Test-TpmProgressGroupOwned) -and $Label -in @('CPS3 extraction and verification','CPS3 source verification','CPS3 file promotion')) {
            if (-not $script:TpmIndependentProgressTasks.ContainsKey($Label)) {
                if ($Complete) { return }
                $script:TpmIndependentProgressTasks[$Label] = Add-TpmProgressTask -Description $Label -Total $Total -Unit $Unit
            }
            $taskId = $script:TpmIndependentProgressTasks[$Label]
            if ($Complete) {
                if ($Outcome -eq 'Final') {
                    Set-TpmProgressTask -Id $taskId -Current $Current -Total $Total -State Final
                } else {
                    Set-TpmProgressTask -Id $taskId -State $Outcome
                }
                $script:TpmIndependentProgressTasks.Remove($Label)
            } else {
                $finished = if (-not $Completed -and $Total -gt 0) { [Math]::Max(0, [Math]::Min($Current, $Total) - 1) } else { $Current }
                Set-TpmProgressTask -Id $taskId -Current $finished -Total $Total
            }
            return
        }
        if ($Complete) {
            if (-not (Test-TpmProgressActive)) { return }
            if (Test-TpmProgressGroupOwned) {
                # Group-owned bar: a leaf never closes it; the owning workflow closes it once.
                if ($NotAvailable) {
                    Set-TpmProgressStage -Stage ('{0}: not found online' -f $Label) -StageOnly
                    return
                }
                if ($Outcome -eq 'Final') {
                    # "<label> done" relabels the same measured work, so the stage clock is kept (-SameStage).
                    if ($Total -gt 0 -and $PSBoundParameters.ContainsKey('Current')) {
                        Set-TpmProgressStage -Stage ("$Label done") -Current ([Math]::Max(0, [Math]::Min($Current, $Total))) -Total $Total -SameStage @unitArgs
                    } else {
                        Set-TpmProgressStage -Stage ("$Label done") -StageOnly
                    }
                    return
                }
                Register-TpmProgressOutcome -State $Outcome
                $word = if ($Outcome -eq 'Cancelled') { 'canceled' } else { 'failed' }
                Set-TpmProgressStage -Stage ("$Label $word") -StageOnly
                return
            }
            if ($Outcome -ne 'Final' -or -not $Substage) {
                if ($Outcome -eq 'Final' -and $Total -gt 0 -and $PSBoundParameters.ContainsKey('Current') -and -not [string]::IsNullOrEmpty($Label)) {
                    Set-TpmProgressStage -Stage $Label -Current ([Math]::Max(0, [Math]::Min($Current, $Total))) -Total $Total -SameStage @unitArgs
                }
                Complete-TpmProgressOperation -State $Outcome
                return
            }
            Set-TpmProgressStage -Stage ("$Label done") -Current $Current -Total $Total -SameStage @unitArgs
            return
        }
        $finishedCurrent = $Current
        if (-not $Completed -and $Total -gt 0) { $finishedCurrent = [Math]::Max(0, [Math]::Min($Current, $Total) - 1) }
        $stepTitle = if ($labelIsPlain) { '' } else { $Phase }
        # A new phase replacing a stage its owner never closed: that stage has no recorded result, so it must not read as done.
        if ((Test-TpmProgressActive) -and -not (Test-TpmProgressGroupOwned) -and (Get-TpmProgressTitle) -ne $stepTitle) { Complete-TpmProgressOperation -State Final -Superseded }
        if (-not (Test-TpmProgressActive)) { Start-TpmProgressOperation -Title $stepTitle -Stage $Label -Total $Total -Width $Width @unitArgs | Out-Null }
        if (Test-TpmProgressGroupOwned) {
            Set-TpmProgressStage -Stage $(if ($stepTitle) { "$stepTitle $Label" } else { $Label }) -Current $finishedCurrent -Total $Total @longArgs @unitArgs
        } else {
            Set-TpmProgressStage -Stage $Label -Current $finishedCurrent -Total $Total @longArgs @unitArgs
        }
        if ($ReturnText) { return (Format-TpmProgressLine -Title $stepTitle -Stage $Label -Current $finishedCurrent -Total $Total -ElapsedSeconds ((Get-Date) - $StartedAt).TotalSeconds -Width (Get-TpmProgressWidth -Requested $Width) @unitArgs) }
    } catch {
        if (Test-TpmProgressCancellationError -ErrorRecord $_) { throw }
        try { Write-Log ('Progress display step failed; the work goes on: {0}' -f $_.Exception.Message) } catch {}
    }
}

function Get-TpmProgressCloseState {
    # Maps explicit result contracts to group-bar states. Missing and explicitly
    # unsuccessful results are Error; unclassified legacy objects retain Final.
    param($Result)
    if ($Result -is [array]) { $Result = if ($Result.Count -gt 0) { $Result[-1] } else { $null } }
    if ($null -eq $Result) { return 'Error' }
    if ($Result -is [bool]) { if ($Result) { return 'Final' }; return 'Error' }
    if ($Result.PSObject.Properties['Cancelled'] -and [bool]$Result.Cancelled) { return 'Cancelled' }
    if ($Result.PSObject.Properties['Outcome']) {
        $outcome = [string]$Result.Outcome
        if ($outcome -eq 'SUCCEEDED' -or $outcome -eq 'Completed') { return 'Final' }
        if ($outcome -eq 'NO_OP') { return 'No-op' }
        # FIX72: a run that only left games alone (protected, missing or unsafe) and had no error finished normally. It needs the
        # user's choice; it did not fail, so its progress row must not end as FAILED.
        if ($Result.PSObject.Properties['ReasonCode'] -and [string]$Result.ReasonCode -eq 'SOME_GAMES_NOT_CHANGED') { return 'Final' }
        # An inspection that could not read everything needs attention; it did not fail to save.
        $attentionReasons = @('BACKUP_RETAINED_NO_PROFILE_CHANGE', 'HEALTH_COVERAGE_INCOMPLETE')
        $closeReason = if ($Result.PSObject.Properties['ReasonCode']) { [string]$Result.ReasonCode } else { '' }
        if ($outcome -eq 'ACTION_REQUIRED' -and $closeReason -in $attentionReasons) { return 'Incomplete' }
        if ($outcome -eq 'Cancelled') { return 'Cancelled' }
        return 'Error'
    }
    if ($Result.PSObject.Properties['NoOp'] -and [bool]$Result.NoOp) { return 'No-op' }
    if ($Result.PSObject.Properties['Succeeded']) { if (-not [bool]$Result.Succeeded) { return 'Error' }; return 'Final' }
    return 'Final'
}

function Invoke-TpmProgressGroup {
    # Runs one top-level workflow inside a single group-owned progress bar. Leaves
    # inside the action report stage text only. The bar closes from the result,
    # or from a caught exception (Cancelled for pipeline stop, Error otherwise);
    # an uncaught host stop closes as Cancelled in finally.
    # Returns the action output unchanged. A group started inside another group only deepens it (the outermost owner
    # closes it) and must not abandon the parent in its own cleanup.
    param([Parameter(Mandatory)][string]$Title, [Parameter(Mandatory)][scriptblock]$Action)
    Import-TpmProgressModule
    $nestedInGroup = (Test-TpmProgressGroupOwned)
    if (-not $nestedInGroup) { $script:TpmIndependentProgressTasks = @{} }
    $displayTitle = $Title
    if (Test-Path -LiteralPath 'Function:\Get-TpmFriendlyProgressLabel') { $displayTitle = Get-TpmFriendlyProgressLabel -Label $Title }
    # A display problem never stops the workflow (it then simply runs without a bar); cancellation still stops it here.
    try { Start-TpmProgressOperation -Title $displayTitle -Group | Out-Null }
    catch {
        if (Test-TpmProgressCancellationError -ErrorRecord $_) { throw }
        try { Write-Log ('Progress group could not start; the work goes on without a bar: {0}' -f $_.Exception.Message) } catch {}
    }
    $closed = $false
    try {
        $result = & $Action
        $closeState = Get-TpmProgressCloseState -Result $result
        try {
            Complete-TpmProgressOperation -State $closeState
        } catch {
            # The action already returned; a terminal progress-render failure
            # must not turn its actual workflow result into a false failure.
            if (Test-TpmProgressCancellationError -ErrorRecord $_) { throw }
            try { Write-Log ("Progress group terminal close failed after state '{0}'; action result retained: {1}" -f $closeState, $_.Exception.Message) } catch {}
        }
        $closed = $true
        return $result
    } catch {
        $caughtError = $_
        $caughtException = $caughtError.Exception
        $pipelineStopped = $false
        while ($null -ne $caughtException) {
            if ($caughtException -is [System.Management.Automation.PipelineStoppedException]) { $pipelineStopped = $true; break }
            $caughtException = $caughtException.InnerException
        }
        $closeState = if ($pipelineStopped) { 'Cancelled' } else { 'Error' }
        $closeMessage = if ($pipelineStopped) { 'Canceled before completion' } else { $caughtError.Exception.Message }
        try { Complete-TpmProgressOperation -State $closeState -Message $closeMessage } catch { try { Write-Log "Progress group close failed: $_" } catch {} }
        $closed = $true
        throw
    } finally {
        # If host cancellation bypasses catch, an open operation here is still Cancelled.
        if (-not $closed -and (Test-TpmProgressActive)) {
            try { Complete-TpmProgressOperation -State Cancelled -Message 'Canceled before completion' } catch { try { Write-Log "Progress cancel close failed: $_" } catch {} }
        }
        if (-not $nestedInGroup) {
            try { Stop-TpmProgressAbandoned }
            catch {
                if (Test-TpmProgressCancellationError -ErrorRecord $_) { throw }
                try { Write-Log ('Progress group cleanup failed; the work result is kept: {0}' -f $_.Exception.Message) } catch {}
            }
        }
    }
}

# AutoSync game roots are install-root children. Keep dry-run selection and the transaction boundary on the same rule.
function Test-TpmAutoSyncDirectChildTarget {
    param([Parameter(Mandatory)][string]$TargetDir, [Parameter(Mandatory)][string]$InstallFolder)
    try {
        $targetFull = [System.IO.Path]::GetFullPath($TargetDir).TrimEnd([char[]]"\/")
        $installFull = [System.IO.Path]::GetFullPath($InstallFolder).TrimEnd([char[]]"\/")
        $parent = [System.IO.Path]::GetDirectoryName($targetFull)
        if ([string]::IsNullOrWhiteSpace($parent)) { return $false }
        return ([System.IO.Path]::GetFullPath($parent).TrimEnd([char[]]"\/") -ieq $installFull)
    } catch { return $false }
}

function Invoke-TpmAutoSyncDirectoryTransaction {
    param(
        [Parameter(Mandatory)][string]$ZipPath,
        [Parameter(Mandatory)][string]$InstallFolder,
        [Parameter(Mandatory)][string]$TargetDir,
        [Parameter(Mandatory)][string]$RawName,
        [Parameter(Mandatory)][string]$SyncStatePath,
        [Parameter(Mandatory)][hashtable]$SyncState,
        [object]$StoredState = $null,
        [string]$LegacySentinelPath = '',
        [string]$RegisteredGamePath = '',
        # First-time extraction into a new game folder: the target must be absent or an empty folder.
        [switch]$NewTarget,
        # Rebuild: keep the old folder here (a new place on the same drive) instead of deleting it, and do not copy extra files out of it.
        [string]$KeepOldTargetAt = '',
        # Rebuild: what the DAT lists for this game (Name, Size, Sha1). The ZIP must match it before anything is replaced.
        [object[]]$ExpectedDatFiles = @()
    )

    $transactionId = [guid]::NewGuid().ToString('N')
    $targetFull = $null
    $installFull = $null
    $stateFull = $null
    $sentinelFull = $null
    $txRoot = $null
    $rollbackRoot = $null
    $stageDir = $null
    $candidatePath = $null
    $oldTarget = $null
    $stateBackupPath = $null
    $sourceBefore = $null
    $targetPre = $null
    $statePre = $null
    $sentinelPre = $null
    $legacySentinelPre = $null
    $stageManifest = $null
    $candidateFileState = $null
    $stateCommitResult = $null
    $stateCommitAttempted = $false
    $sentinelCreated = $false
    $targetMovedAside = $false
    $targetPromoted = $false
    $promotionAttempted = $false
    $extraFilesNotKept = $false
    $stateChanged = $false
    $filesystemChanged = $false
    $registrationEligible = $false
    $mutationStarted = $false
    $mutationCompleted = $false
    $preStateCaptured = $false
    $backupRequired = $false
    $backupAttempted = $false
    $backupCreated = $false
    $backupVerified = $false
    $finalAttempted = $false
    $finalPassed = $false
    $rollbackAttempted = $false
    $rollbackCompleted = $false
    $rollbackVerified = $false
    $cleanupAttempted = $false
    $cleanupCompleted = $true
    $residuePresent = $false
    $requestedOutcome = 'FAILED_BEFORE_MUTATION'
    $requestedState = 'UNCHANGED'
    $requestedSummary = 'Nothing was changed because TeknoParrot Manager could not prepare a safe replacement.'
    $requestedReason = 'PREFLIGHT_FAILED'
    $underlyingOutcome = $null
    $technical = [ordered]@{
        TransactionId = $transactionId
        WorkflowKey = 'AutoSync'
        OperationKey = $RawName
        Stage = 'Preflight'
        SourcePath = $ZipPath
        TargetPath = $TargetDir
        SyncStatePath = $SyncStatePath
        StagingPath = $null
        RollbackPath = $null
        Error = $null
        RollbackError = @()
        CleanupError = $null
        ExtraFileCount = 0
        ExtraFilesSavedTo = ''
        OldFolderKeptAt = ''
        DatCheck = ''
    }
    $preStateItems = New-Object System.Collections.Generic.List[object]
    $backupItems = New-Object System.Collections.Generic.List[object]
    $changedItems = New-Object System.Collections.Generic.List[string]
    $completedItems = New-Object System.Collections.Generic.List[string]
    $failedItems = New-Object System.Collections.Generic.List[string]
    $unattemptedItems = New-Object System.Collections.Generic.List[string]
    $skippedItems = New-Object System.Collections.Generic.List[string]
    $unknownItems = New-Object System.Collections.Generic.List[string]
    $finalChecks = New-Object System.Collections.Generic.List[string]
    $finalFailedItems = New-Object System.Collections.Generic.List[string]
    $finalUnknownItems = New-Object System.Collections.Generic.List[string]
    $rollbackItems = New-Object System.Collections.Generic.List[string]
    $rollbackFailedItems = New-Object System.Collections.Generic.List[string]
    $rollbackErrors = New-Object System.Collections.Generic.List[string]
    $residuePaths = New-Object System.Collections.Generic.List[string]
    $errors = New-Object System.Collections.Generic.List[string]

    $returnResult = {
        $result = New-TpmAutoSyncDirectoryResult `
            -Outcome $requestedOutcome -ProductState $requestedState `
            -Summary $requestedSummary -RawName $RawName `
            -MutationStarted $mutationStarted -MutationCompleted $mutationCompleted `
            -ChangedItems $changedItems.ToArray() -CompletedItems $completedItems.ToArray() `
            -FailedItems $failedItems.ToArray() -UnattemptedItems $unattemptedItems.ToArray() `
            -SkippedItems $skippedItems.ToArray() -UnknownItems $unknownItems.ToArray() `
            -PreStateItems $preStateItems.ToArray() -PreStateCaptured $preStateCaptured `
            -PreStateEvidenceRoot $txRoot -BackupRequired $backupRequired `
            -BackupAttempted $backupAttempted -BackupCreated $backupCreated `
            -BackupVerified $backupVerified -BackupRootPath $rollbackRoot `
            -BackupItems $backupItems.ToArray() -FinalAttempted $finalAttempted `
            -FinalPassed $finalPassed -FinalChecks $finalChecks.ToArray() `
            -FinalFailedItems $finalFailedItems.ToArray() `
            -FinalUnknownItems $finalUnknownItems.ToArray() `
            -RollbackAttempted $rollbackAttempted -RollbackCompleted $rollbackCompleted `
            -RollbackVerified $rollbackVerified -RollbackItems $rollbackItems.ToArray() `
            -RollbackEvidenceRoot $rollbackRoot -RollbackFailedItems $rollbackFailedItems.ToArray() `
            -RollbackErrors $rollbackErrors.ToArray() -CleanupAttempted $cleanupAttempted `
            -CleanupCompleted $cleanupCompleted -ResiduePresent $residuePresent `
            -ResiduePaths $residuePaths.ToArray() -CleanupError $technical.CleanupError `
            -UnderlyingOutcome $underlyingOutcome -ReasonCode $requestedReason `
            -TechnicalDetails $technical -Errors $errors.ToArray() `
            -RecoveryActions $(if ($requestedOutcome -eq 'ACTION_REQUIRED') {
                @(@{ Id = 'Review'; Label = 'Open Details and review the preserved transaction evidence.' })
            } else { @() })
        [pscustomobject]@{
            TransactionResult = $result
            FilesystemChanged = $filesystemChanged
            StateChanged = $stateChanged
            RegistrationEligible = $registrationEligible
            TargetPath = $targetFull
            LocalPath = $targetFull
        }
    }

    try {
        $targetFull = [System.IO.Path]::GetFullPath($TargetDir)
        $installFull = [System.IO.Path]::GetFullPath($InstallFolder).TrimEnd([char[]]"\/")
        $stateFull = [System.IO.Path]::GetFullPath($SyncStatePath)
        $targetLeaf = [System.IO.Path]::GetFileName($targetFull.TrimEnd([char[]]"\/"))
        $targetParent = [System.IO.Path]::GetDirectoryName($targetFull.TrimEnd([char[]]"\/"))
        $sentinelFull = Join-Path $targetParent ($targetLeaf + '.extracting')
        $technical.TargetPath = $targetFull
        $technical.SyncStatePath = $stateFull

        if ($targetFull.TrimEnd([char[]]"\/") -ieq $installFull) {
            throw "AutoSync target cannot be the TeknoParrot install folder: $installFull"
        }
        if ([string]::IsNullOrWhiteSpace($targetLeaf)) {
            throw "AutoSync target folder name is empty: $targetFull"
        }
        if (-not (Test-PathInside -child $targetFull -parent $installFull)) {
            throw "AutoSync target escaped the install folder: $targetFull"
        }
        if (Test-PathInside -child $stateFull -parent $targetFull) {
            throw "AutoSync sync state cannot be inside the game target: $stateFull"
        }
        if (-not (Test-TpmNoReparsePath -Path $installFull)) {
            throw "AutoSync install folder failed the path safety check: $installFull"
        }
        if (-not (Test-TpmNoReparsePath -Path $targetParent)) {
            throw "AutoSync target parent failed the path safety check: $targetParent"
        }
        if (-not [string]::IsNullOrWhiteSpace($KeepOldTargetAt)) {
            if (-not (Test-TpmNoReparsePath -Path ([System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($KeepOldTargetAt))))) {
                throw "AutoSync cannot keep the old folder in an unsafe place: $KeepOldTargetAt"
            }
            if ([System.IO.Path]::GetPathRoot([System.IO.Path]::GetFullPath($KeepOldTargetAt)) -ine [System.IO.Path]::GetPathRoot($targetFull)) {
                throw "AutoSync can only keep the old folder on the same drive: $KeepOldTargetAt"
            }
            if (Test-Path -LiteralPath $KeepOldTargetAt) { throw "AutoSync cannot keep the old folder: that place is already used: $KeepOldTargetAt" }
        }

        $sourceBefore = Get-TpmAutoSyncSourceIdentity -Path $ZipPath
        if (-not $sourceBefore.Readable -or -not $sourceBefore.Exists) {
            throw "AutoSync source ZIP is unavailable: $ZipPath"
        }
        $targetPre = Get-TpmDirectoryManifest -Path $targetFull
        $statePre = Get-TpmFileState -Path $stateFull
        $sentinelPre = Get-TpmFileState -Path $sentinelFull
        if (-not [string]::IsNullOrWhiteSpace($LegacySentinelPath) -and
            [System.IO.Path]::GetFullPath($LegacySentinelPath) -ine $sentinelFull) {
            $legacySentinelPre = Get-TpmFileState -Path $LegacySentinelPath
        } else {
            $legacySentinelPre = [pscustomobject]@{
                Path = $sentinelFull
                Exists = $false
                Readable = $true
                IsDirectory = $false
                Length = $null
                Sha256 = $null
                LastWriteTimeUtc = $null
                Attributes = $null
                Error = $null
            }
        }
        if (-not $targetPre.Readable -or -not $statePre.Readable -or
            -not $sentinelPre.Readable -or -not $legacySentinelPre.Readable) {
            $unreadableParts = New-Object System.Collections.Generic.List[string]
            if (-not $targetPre.Readable) { [void]$unreadableParts.Add(('target: ' + [string]$targetPre.Error)) }
            if (-not $statePre.Readable) { [void]$unreadableParts.Add(('sync state: ' + [string]$statePre.Error)) }
            if (-not $sentinelPre.Readable) { [void]$unreadableParts.Add(('sentinel: ' + [string]$sentinelPre.Error)) }
            if (-not $legacySentinelPre.Readable) { [void]$unreadableParts.Add(('legacy sentinel: ' + [string]$legacySentinelPre.Error)) }
            Write-Log ('AutoSync pre-state capture failed for ' + $RawName + ': ' + ($unreadableParts -join '; '))
            throw ('AutoSync could not capture a readable directory, sentinel, or sync-state pre-state. ' + ($unreadableParts -join '; '))
        }
        if ($targetPre.Exists -and -not $targetPre.IsDirectory) {
            if ($NewTarget) { $requestedReason = 'AMBIGUOUS_EXTRACTION_ROOT' }
            throw "AutoSync target is a file, not a directory: $targetFull"
        }
        if ($statePre.Exists -and $statePre.IsDirectory) {
            throw "AutoSync sync state is a directory, not a file: $stateFull"
        }
        $preStateItems.Add([pscustomobject]@{
            ItemId = $RawName
            Path = $targetFull
            Exists = $targetPre.Exists
            IsDirectory = $targetPre.IsDirectory
            Length = $null
            Sha256 = $targetPre.ManifestHash
        })
        $preStateItems.Add([pscustomobject]@{
            ItemId = 'metadata:syncstate'
            Path = $stateFull
            Exists = $statePre.Exists
            IsDirectory = $statePre.IsDirectory
            Length = $statePre.Length
            Sha256 = $statePre.Sha256
        })
        $preStateItems.Add([pscustomobject]@{
            ItemId = 'metadata:sentinel'
            Path = $sentinelFull
            Exists = $sentinelPre.Exists
            IsDirectory = $sentinelPre.IsDirectory
            Length = $sentinelPre.Length
            Sha256 = $sentinelPre.Sha256
        })
        if ($legacySentinelPre.Path -ine $sentinelPre.Path) {
            $preStateItems.Add([pscustomobject]@{
                ItemId = 'metadata:legacy-sentinel'
                Path = $legacySentinelPre.Path
                Exists = $legacySentinelPre.Exists
                IsDirectory = $legacySentinelPre.IsDirectory
                Length = $legacySentinelPre.Length
                Sha256 = $legacySentinelPre.Sha256
            })
        }
        $preStateCaptured = $true
        if (-not (Test-TpmAutoSyncDirectChildTarget -TargetDir $targetFull -InstallFolder $installFull)) {
            $requestedReason = 'AMBIGUOUS_EXTRACTION_ROOT'
            throw "AutoSync refused a nested target; expected a direct child of the install folder: $targetFull"
        }
        if ($NewTarget) {
            # Never merge into or replace content that no folder or profile identity confirmed.
            if ($targetPre.Exists -and (-not $targetPre.IsDirectory -or @($targetPre.Items).Count -gt 0)) {
                $requestedReason = 'AMBIGUOUS_EXTRACTION_ROOT'
                throw "AutoSync refused to create a new game folder where content already exists: $targetFull"
            }
            # A registered executable is allowed only inside the new folder; the binding check below proves
            # the ZIP contains it at that folder-relative path.
        }
        $inventory = Get-TpmAutoSyncZipInventory -ZipPath $ZipPath -SkipHash
        if (-not [string]::IsNullOrWhiteSpace($RegisteredGamePath)) {
            # An install-root child is only a candidate. Its archive-relative
            # executable must match the registered path before replacing it.
            try {
                $registeredFull = [System.IO.Path]::GetFullPath($RegisteredGamePath)
                $rootKey = $targetFull.TrimEnd([char[]]"\/")
                if (-not (Test-PathInside -child $registeredFull -parent $rootKey)) { throw 'Registered executable is outside the candidate root.' }
                $relativeExecutable = $registeredFull.Substring($rootKey.Length).TrimStart([char[]]"\/")
                $safeExecutable = ConvertTo-SafeZipEntryRelativePath -EntryName $relativeExecutable
                $matchingEntries = @($inventory.Entries | Where-Object {
                    -not $_.IsDirectory -and [string]$_.RelativePath -ieq [string]$safeExecutable.RelativePath
                })
                if ($safeExecutable.IsDirectory -or $matchingEntries.Count -ne 1) { throw 'ZIP does not contain the registered executable at its candidate-root-relative path.' }
            } catch {
                $requestedReason = 'AMBIGUOUS_EXTRACTION_ROOT'
                throw ('AutoSync refused an unproven extraction root: {0}' -f $_.Exception.Message)
            }
        }

        if ($sentinelPre.Exists -or $legacySentinelPre.Exists) {
            $requestedOutcome = 'ACTION_REQUIRED'
            $requestedState = 'UNKNOWN'
            $requestedSummary = 'TeknoParrot Manager found an incomplete previous game operation and needs your attention. Open Details before retrying.'
            $requestedReason = 'STALE_EXTRACTION_MARKER'
            $unknownItems.Add($RawName)
            if ($sentinelPre.Exists) { $residuePaths.Add($sentinelFull) }
            if ($legacySentinelPre.Exists) { $residuePaths.Add($legacySentinelPre.Path) }
            $residuePresent = $true
            $technical.Stage = 'Preflight'
            return (& $returnResult)
        }

        $storedPath = [string](Get-TpmTransactionField -Object $StoredState -Name 'LocalPath')
        $storedHash = [string](Get-TpmTransactionField -Object $StoredState -Name 'LocalManifestHash')
        $sourceModStr = $sourceBefore.LastWriteTimeUtc.ToString('o')
        $storedSourceMatches = $false
        if ($null -ne $StoredState) {
            $storedSourceMatches = ([int64](Get-TpmTransactionField -Object $StoredState -Name 'NasSize' -Default -1) -eq $sourceBefore.Length) -and
                ((ConvertTo-TpmSyncStampText (Get-TpmTransactionField -Object $StoredState -Name 'NasLastModified')) -eq $sourceModStr)
        }
        $storedPathMatches = $false
        if (-not [string]::IsNullOrWhiteSpace($storedPath)) {
            try { $storedPathMatches = ([System.IO.Path]::GetFullPath($storedPath) -ieq $targetFull) } catch { $storedPathMatches = $false }
        }
        # The ZIP's file checksums are only needed before extraction when the folder might already match it (same names and sizes).
        # Otherwise the checksums come from the single extraction pass below, so the ZIP data is read once.
        $targetMayMatchZip = Test-TpmDirectoryAgainstZipInventory -Manifest $targetPre -Inventory $inventory -IgnoreHash
        if ($targetMayMatchZip) { $inventory = Get-TpmAutoSyncZipInventory -ZipPath $ZipPath }
        $targetMatchesZip = $targetMayMatchZip -and (Test-TpmDirectoryAgainstZipInventory -Manifest $targetPre -Inventory $inventory)
        $stateMatchesTarget = $storedSourceMatches -and $storedPathMatches -and
            -not [string]::IsNullOrWhiteSpace($storedHash) -and
            ($storedHash -ieq [string]$targetPre.ManifestHash) -and
            ([string](Get-TpmTransactionField -Object $StoredState -Name 'State') -in @('', 'Complete'))

        if ($targetMatchesZip -and $stateMatchesTarget) {
            $requestedOutcome = 'NO_OP'
            $requestedState = 'UNCHANGED'
            $requestedSummary = 'Nothing changed; the existing game folder was already verified.'
            $requestedReason = 'NO_CHANGES_NEEDED'
            $skippedItems.Add($RawName)
            $finalAttempted = $true
            $finalPassed = $true
            $finalChecks.Add('Existing directory manifest matches the ZIP inventory.')
            $finalChecks.Add('Existing sync-state entry matches the verified local manifest.')
            return (& $returnResult)
        }

        $candidateState = @{}
        foreach ($key in $SyncState.Keys) { $candidateState[$key] = $SyncState[$key] }
        $newEntry = [ordered]@{
            NasSize = [int64]$sourceBefore.Length
            NasLastModified = $sourceModStr
            LocalPath = $targetFull
            LocalManifestHash = if ($targetMatchesZip) { [string]$targetPre.ManifestHash } else { $null }
            State = 'Complete'
            SyncedAt = (Get-Date).ToUniversalTime().ToString('o')
            TransactionId = $transactionId
        }

        if ($targetMatchesZip) {
            $technical.Stage = 'StateCommit'
            $txRoot = New-TpmAutoSyncTransactionRoot -InstallFolder $installFull
            $rollbackRoot = Join-Path $txRoot 'rollback'
            $candidatePath = Join-Path $txRoot 'syncstate.candidate.json'
            $stateBackupPath = Join-Path $rollbackRoot 'syncstate.backup.json'
            [void][System.IO.Directory]::CreateDirectory($rollbackRoot)
            $candidateState[$RawName] = $newEntry
            $candidateJson = $candidateState | ConvertTo-Json -Depth 5
            [System.IO.File]::WriteAllText($candidatePath, $candidateJson, (New-Object System.Text.UTF8Encoding $false))
            $candidateFileState = Get-TpmFileState -Path $candidatePath
            if (-not $candidateFileState.Readable -or -not $candidateFileState.Exists) {
                throw 'AutoSync sync-state candidate could not be verified after writing.'
            }
            $null = Get-Content -LiteralPath $candidatePath -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json
            $technical.Stage = 'MutationBoundary'
            $stateOnlyTargetPre = Get-TpmDirectoryManifest -Path $targetFull
            $stateOnlyStatePre = Get-TpmFileState -Path $stateFull
            $stateOnlySourcePre = Get-TpmAutoSyncSourceIdentity -Path $ZipPath
            $stateOnlySentinelPre = Get-TpmFileState -Path $sentinelFull
            $stateOnlyLegacySentinelPre = $stateOnlySentinelPre
            if ($legacySentinelPre.Path -ine $sentinelPre.Path) {
                $stateOnlyLegacySentinelPre = Get-TpmFileState -Path $legacySentinelPre.Path
            }
            if (-not (Test-TpmDirectoryManifestMatch -Expected $targetPre -Actual $stateOnlyTargetPre) -or
                -not (Test-TpmFileStateMatch -Expected $statePre -Actual $stateOnlyStatePre -IgnoreMetadata) -or
                -not (Test-TpmAutoSyncSourceIdentityMatch -Expected $sourceBefore -Actual $stateOnlySourcePre) -or
                $stateOnlySentinelPre.Exists -or $stateOnlyLegacySentinelPre.Exists) {
                throw 'AutoSync pre-state changed before the sync-state mutation boundary.'
            }
            New-TpmAutoSyncLiveSentinel -Path $sentinelFull
            $sentinelCreated = $true
            $stateCommitAttempted = $true
            if ($statePre.Exists) {
                $backupRequired = $true
                $backupAttempted = $true
            }
            $stateCommitResult = Invoke-TpmAutoSyncStateCommit `
                -StatePath $stateFull -CandidatePath $candidatePath `
                -ExpectedPreState $statePre -BackupPath $stateBackupPath
            if ($statePre.Exists) {
                $backupCreated = $true
                $backupVerified = $true
                $backupItems.Add([pscustomobject]@{
                    ItemId = 'metadata:syncstate'
                    Path = $stateFull
                    BackupPath = $stateCommitResult.BackupPath
                    Sha256 = $statePre.Sha256
                })
            }
            $stateAfterObject = Get-Content -LiteralPath $stateFull -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json
            $stateAfterEntry = $stateAfterObject.PSObject.Properties[$RawName]
            if ($null -eq $stateAfterEntry -or
                [string]$stateAfterEntry.Value.LocalManifestHash -ine [string]$targetPre.ManifestHash -or
                [string]$stateAfterEntry.Value.LocalPath -ine $targetFull) {
                throw 'AutoSync sync-state selected entry failed final verification.'
            }
            $targetAfterState = Get-TpmDirectoryManifest -Path $targetFull
            if (-not (Test-TpmDirectoryManifestMatch -Expected $targetPre -Actual $targetAfterState)) {
                throw 'AutoSync existing directory changed during state commit.'
            }
            $sentinelAfterState = Get-TpmFileState -Path $sentinelFull
            $legacySentinelAfterState = $legacySentinelPre
            if ($legacySentinelPre.Path -ine $sentinelPre.Path) {
                $legacySentinelAfterState = Get-TpmFileState -Path $legacySentinelPre.Path
            }
            if (-not $sentinelAfterState.Readable -or -not $sentinelAfterState.Exists -or
                -not $legacySentinelAfterState.Readable -or $legacySentinelAfterState.Exists) {
                throw 'AutoSync extraction sentinel state changed during sync-state commit.'
            }
            $finalChecks.Add('Live extraction sentinel remained present through sync-state readback.')
            $SyncState[$RawName] = $newEntry
            $stateChanged = $true
            $mutationStarted = $true
            $changedItems.Add('syncstate:' + $RawName)
            $completedItems.Add('syncstate:' + $RawName)
            $finalAttempted = $true
            $finalPassed = $true
            $finalChecks.Add('Existing directory manifest matches the ZIP inventory.')
            $finalChecks.Add('Sync-state candidate was committed and read back successfully.')
            $mutationCompleted = $true
            $requestedOutcome = 'SUCCEEDED'
            $requestedState = 'INTENDED'
            $requestedSummary = 'The existing game folder was verified and its synchronization record was repaired.'
            $requestedReason = 'STATE_REPAIRED'
            $cleanupAttempted = $true
            try {
                Invoke-TpmAutoSyncRemovePath -Path $sentinelFull
                $sentinelCreated = $false
            } catch {
                $cleanupCompleted = $false
                $residuePresent = $true
                $technical.CleanupError = $_.Exception.Message
                $technical.Stage = 'Cleanup'
                $residuePaths.Add($sentinelFull)
                $residuePaths.Add($txRoot)
                $underlyingOutcome = 'SUCCEEDED'
                $requestedOutcome = 'CLEANUP_RESIDUE'
                $requestedSummary = 'The files are in a verified state, but TeknoParrot Manager could not finish cleanup. Review Details before retrying.'
                $requestedReason = 'CLEANUP_RESIDUE'
            }
            if (-not $residuePresent) {
                $postCleanupTarget = Get-TpmDirectoryManifest -Path $targetFull
                $postCleanupState = Get-TpmFileState -Path $stateFull
                $postCleanupSentinel = Get-TpmFileState -Path $sentinelFull
                $postCleanupLegacySentinel = $legacySentinelPre
                if ($legacySentinelPre.Path -ine $sentinelPre.Path) {
                    $postCleanupLegacySentinel = Get-TpmFileState -Path $legacySentinelPre.Path
                }
                if (-not (Test-TpmDirectoryManifestMatch -Expected $targetPre -Actual $postCleanupTarget) -or
                    -not (Test-TpmFileStateMatch -Expected $stateCommitResult.State -Actual $postCleanupState -IgnoreMetadata) -or
                    -not $postCleanupSentinel.Readable -or $postCleanupSentinel.Exists -or
                    -not $postCleanupLegacySentinel.Readable -or $postCleanupLegacySentinel.Exists) {
                    throw 'AutoSync state-only transaction failed post-cleanup verification.'
                }
            }
            if (-not $residuePresent) {
                try {
                    Invoke-TpmAutoSyncRemovePath -Path $txRoot
                } catch {
                    $cleanupCompleted = $false
                    $residuePresent = $true
                    $technical.CleanupError = $_.Exception.Message
                    $technical.Stage = 'Cleanup'
                    $residuePaths.Add($txRoot)
                    $underlyingOutcome = 'SUCCEEDED'
                    $requestedOutcome = 'CLEANUP_RESIDUE'
                    $requestedSummary = 'The files are in a verified state, but TeknoParrot Manager could not finish cleanup. Review Details before retrying.'
                    $requestedReason = 'CLEANUP_RESIDUE'
                }
            }
            return (& $returnResult)
        }

        $technical.Stage = 'Staging'
        $txRoot = New-TpmAutoSyncTransactionRoot -InstallFolder $installFull
        $rollbackRoot = Join-Path $txRoot 'rollback'
        $stageDir = Join-Path $txRoot 'payload'
        $candidatePath = Join-Path $txRoot 'syncstate.candidate.json'
        $stateBackupPath = Join-Path $rollbackRoot 'syncstate.backup.json'
        $oldTarget = Join-Path $rollbackRoot 'old-target'
        $technical.StagingPath = $stageDir
        $technical.RollbackPath = $rollbackRoot
        [void][System.IO.Directory]::CreateDirectory($rollbackRoot)
        [void][System.IO.Directory]::CreateDirectory($stageDir)
        if (-not (Test-TpmNoReparsePath -Path $stageDir) -or
            -not (Test-TpmNoReparsePath -Path $rollbackRoot)) {
            throw 'AutoSync transaction directories failed the path safety check.'
        }
        $spaceState = Get-TpmAutoSyncStagingSpaceState -Path $txRoot -RequiredBytes ([int64]$inventory.TotalBytes)
        if ($spaceState -eq 'Short') { throw 'INSUFFICIENT_STAGING_SPACE' }
        if ($spaceState -eq 'Unknown') { throw 'STAGING_SPACE_UNAVAILABLE' }
        $stageHashes = @{}
        $stageSha1 = @{}
        $expandArguments = @{ ZipPath = $ZipPath; DestDir = $stageDir; GameName = $RawName; EntryHashes = $stageHashes }
        if (@($ExpectedDatFiles).Count -gt 0) { $expandArguments['EntrySha1'] = $stageSha1 }
        Expand-ZipFileSafe @expandArguments
        # The ZIP was read once: every file's checksum was taken from the same bytes that were written to the staging folder.
        foreach ($zipRecord in @($inventory.Entries | Where-Object { -not $_.IsDirectory })) {
            $streamHash = [string]$stageHashes[([string]$zipRecord.RelativePath).ToLowerInvariant()]
            if ([string]::IsNullOrWhiteSpace($streamHash)) { throw 'AutoSync extraction did not report a checksum for every file in the ZIP.' }
            if (-not [string]::IsNullOrWhiteSpace([string]$zipRecord.Sha256) -and [string]$zipRecord.Sha256 -ine $streamHash) { throw 'AutoSync ZIP data changed while it was being read.' }
            $zipRecord.Sha256 = $streamHash
        }
        $stageManifest = Get-TpmDirectoryManifest -Path $stageDir
        if (-not (Test-TpmDirectoryAgainstZipInventory -Manifest $stageManifest -Inventory $inventory)) {
            throw 'AutoSync staged directory did not match the complete ZIP inventory.'
        }
        if (@($ExpectedDatFiles).Count -gt 0) {
            # The staged files are checked against the DAT list (size and SHA-1, taken in the same pass) before the live folder is touched.
            $datCheck = Test-TpmZipFilesAgainstDatList -DatFiles $ExpectedDatFiles -Inventory $inventory -Sha1ByPath $stageSha1
            $technical.DatCheck = $datCheck.Summary
            if (-not $datCheck.Matches) {
                $requestedReason = 'DAT_MISMATCH'
                throw ('The files in the ZIP do not match the DAT list: ' + $datCheck.Summary)
            }
        }
        $sourceAfterStage = Get-TpmAutoSyncSourceIdentity -Path $ZipPath
        if (-not (Test-TpmAutoSyncSourceIdentityMatch -Expected $sourceBefore -Actual $sourceAfterStage)) {
            throw 'AutoSync source ZIP changed while it was being staged.'
        }
        $newEntry.LocalManifestHash = $stageManifest.ManifestHash
        $candidateState[$RawName] = $newEntry
        $candidateJson = $candidateState | ConvertTo-Json -Depth 5
        [System.IO.File]::WriteAllText($candidatePath, $candidateJson, (New-Object System.Text.UTF8Encoding $false))
        $candidateFileState = Get-TpmFileState -Path $candidatePath
        if (-not $candidateFileState.Readable -or -not $candidateFileState.Exists) {
            throw 'AutoSync sync-state candidate could not be verified after writing.'
        }
        $null = Get-Content -LiteralPath $candidatePath -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json

        $technical.Stage = 'MutationBoundary'
        $currentTargetPre = Get-TpmDirectoryManifest -Path $targetFull
        $currentStatePre = Get-TpmFileState -Path $stateFull
        $currentSourcePre = Get-TpmAutoSyncSourceIdentity -Path $ZipPath
        if (-not (Test-TpmDirectoryManifestMatch -Expected $targetPre -Actual $currentTargetPre) -or
            -not (Test-TpmFileStateMatch -Expected $statePre -Actual $currentStatePre -IgnoreMetadata) -or
            -not (Test-TpmAutoSyncSourceIdentityMatch -Expected $sourceBefore -Actual $currentSourcePre)) {
            throw 'AutoSync pre-state changed before the live mutation boundary.'
        }
        New-TpmAutoSyncLiveSentinel -Path $sentinelFull
        $sentinelCreated = $true

        $technical.Stage = 'Promotion'
        if ($targetPre.Exists) {
            $backupRequired = $true
            $backupAttempted = $true
            Invoke-TpmAutoSyncMovePath -Source $targetFull -Destination $oldTarget
            $targetMovedAside = $true
            $mutationStarted = $true
            $filesystemChanged = $true
            $changedItems.Add($RawName)
            $movedManifest = Get-TpmDirectoryManifest -Path $oldTarget
            if (-not (Test-TpmDirectoryManifestMatch -Expected $targetPre -Actual $movedManifest)) {
                throw 'AutoSync moved-aside directory failed rollback-backup verification.'
            }
            $backupCreated = $true
            $backupVerified = $true
            $backupItems.Add([pscustomobject]@{
                ItemId = $RawName
                Path = $targetFull
                BackupPath = $oldTarget
                ManifestHash = $targetPre.ManifestHash
            })
        }
        if (Test-Path -LiteralPath $targetFull) {
            throw 'AutoSync target still exists at the promotion boundary.'
        }
        $promotionAttempted = $true
        try {
            Invoke-TpmAutoSyncMovePath -Source $stageDir -Destination $targetFull
            $targetPromoted = $true
            $mutationStarted = $true
            $filesystemChanged = $true
            if (-not $changedItems.Contains($RawName)) { $changedItems.Add($RawName) }
        } catch {
            $promotionError = $_
            if (Test-Path -LiteralPath $targetFull) {
                $targetPromoted = $true
                $mutationStarted = $true
                $filesystemChanged = $true
                if (-not $changedItems.Contains($RawName)) { $changedItems.Add($RawName) }
            }
            throw $promotionError
        }
        $targetAfterPromotion = Get-TpmDirectoryManifest -Path $targetFull
        if (-not (Test-TpmDirectoryManifestMatch -Expected $stageManifest -Actual $targetAfterPromotion)) {
            throw 'AutoSync promoted directory failed final tree verification.'
        }
        $finalChecks.Add('Promoted directory matches the staged manifest and ZIP inventory.')

        # Files in the old folder that the ZIP does not contain (ReShade, dgVoodoo, saves) or that differ from the ZIP copy (changed settings, saves) are copied to Backups before anything is committed.
        # If they cannot be kept, this game stops here and the catch below puts the old folder back.
        if ($targetPre.Exists -and $targetPre.IsDirectory -and [string]::IsNullOrWhiteSpace($KeepOldTargetAt)) {
            $zipHashes = @{}
            foreach ($zipEntry in @($inventory.Entries)) { if (-not $zipEntry.IsDirectory) { $zipHashes[([string]$zipEntry.RelativePath).ToLowerInvariant()] = [string]$zipEntry.Sha256 } }
            $extraFiles = @($targetPre.Items | Where-Object {
                if ($_.IsDirectory) { return $false }
                $zipSha = $zipHashes[([string]$_.RelativePath).ToLowerInvariant()]
                return (($null -eq $zipSha) -or ($zipSha -ine [string]$_.Sha256))
            })
            $technical.ExtraFileCount = $extraFiles.Count
            if ($extraFiles.Count -gt 0) {
                try {
                    if (-not ($script:TpmOwnedLayout -and $script:TpmOwnedLayout.Backups)) { throw 'No Backups folder is set up.' }
                    $extraRoot = Join-Path (Join-Path ([string]$script:TpmOwnedLayout.Backups) 'AutoSyncReplaced') ($RawName + '_' + (Get-Date).ToUniversalTime().ToString('yyyy-MM-dd_HH-mm-ss', [System.Globalization.CultureInfo]::InvariantCulture))
                    foreach ($extraFile in $extraFiles) {
                        $extraTo = ConvertTo-TpmAutoSyncLongPath -Path (Join-Path $extraRoot $extraFile.RelativePath)
                        [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($extraTo))
                        [System.IO.File]::Copy((ConvertTo-TpmAutoSyncLongPath -Path (Join-Path $oldTarget $extraFile.RelativePath)), $extraTo, $false)
                    }
                    $technical.ExtraFilesSavedTo = $extraRoot
                } catch {
                    $extraFilesNotKept = $true
                    throw ("Could not keep the files the ZIP does not contain for $RawName -- " + $_.Exception.Message)
                }
            }
        }
        $technical.Stage = 'StateCommit'
        $stateCommitAttempted = $true
        if ($statePre.Exists) {
            $backupRequired = $true
            $backupAttempted = $true
        }
        $stateCommitResult = Invoke-TpmAutoSyncStateCommit `
            -StatePath $stateFull -CandidatePath $candidatePath `
            -ExpectedPreState $statePre -BackupPath $stateBackupPath
        if ($statePre.Exists) {
            $backupCreated = $true
            $backupVerified = $true
            $backupItems.Add([pscustomobject]@{
                ItemId = 'metadata:syncstate'
                Path = $stateFull
                BackupPath = $stateCommitResult.BackupPath
                Sha256 = $statePre.Sha256
            })
        }
        $stateAfterObject = Get-Content -LiteralPath $stateFull -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json
        $stateAfterEntry = $stateAfterObject.PSObject.Properties[$RawName]
        if ($null -eq $stateAfterEntry -or
            [string]$stateAfterEntry.Value.LocalManifestHash -ine [string]$stageManifest.ManifestHash -or
            [string]$stateAfterEntry.Value.LocalPath -ine $targetFull) {
            throw 'AutoSync sync-state selected entry failed final verification.'
        }
        $finalChecks.Add('Sync-state candidate was committed and read back successfully.')
        $targetAfterState = Get-TpmDirectoryManifest -Path $targetFull
        if (-not (Test-TpmDirectoryManifestMatch -Expected $stageManifest -Actual $targetAfterState)) {
            throw 'AutoSync promoted directory changed during state commit.'
        }
        $finalChecks.Add('Promoted directory still matches after sync-state readback.')
        if (-not (Test-Path -LiteralPath $sentinelFull)) {
            throw 'AutoSync live sentinel disappeared before the transaction completed.'
        }
        $legacySentinelAfterState = $legacySentinelPre
        if ($legacySentinelPre.Path -ine $sentinelPre.Path) {
            $legacySentinelAfterState = Get-TpmFileState -Path $legacySentinelPre.Path
        }
        if (-not $legacySentinelAfterState.Readable -or $legacySentinelAfterState.Exists) {
            throw 'AutoSync legacy extraction sentinel appeared before commit completion.'
        }
        $finalChecks.Add('No legacy extraction sentinel appeared during promotion.')
        $SyncState[$RawName] = $newEntry
        $stateChanged = $true
        $mutationCompleted = $true
        $finalAttempted = $true
        $finalPassed = $true
        $completedItems.Add($RawName)

        $technical.Stage = 'Cleanup'
        $cleanupAttempted = $true
        try {
            Invoke-TpmAutoSyncRemovePath -Path $sentinelFull
            $sentinelCreated = $false
        } catch {
            $cleanupCompleted = $false
            $residuePresent = $true
            $technical.CleanupError = $_.Exception.Message
            $residuePaths.Add($sentinelFull)
            $residuePaths.Add($txRoot)
        }
        if (-not $residuePresent) {
            $postCleanupTarget = Get-TpmDirectoryManifest -Path $targetFull
            $postCleanupState = Get-TpmFileState -Path $stateFull
            $postCleanupSentinel = Get-TpmFileState -Path $sentinelFull
            $postCleanupLegacySentinel = $legacySentinelPre
            if ($legacySentinelPre.Path -ine $sentinelPre.Path) {
                $postCleanupLegacySentinel = Get-TpmFileState -Path $legacySentinelPre.Path
            }
            if (-not (Test-TpmDirectoryManifestMatch -Expected $stageManifest -Actual $postCleanupTarget) -or
                -not (Test-TpmFileStateMatch -Expected $stateCommitResult.State -Actual $postCleanupState -IgnoreMetadata) -or
                -not $postCleanupSentinel.Readable -or $postCleanupSentinel.Exists -or
                -not $postCleanupLegacySentinel.Readable -or $postCleanupLegacySentinel.Exists) {
                throw 'AutoSync transaction failed post-cleanup verification.'
            }
            $finalChecks.Add('Promoted directory and sync-state remained verified after sentinel cleanup.')
        }
        # Rebuild: the old folder is not deleted. It is renamed to its own place on the same drive (no copy) before cleanup.
        if (-not $residuePresent -and $targetMovedAside -and -not [string]::IsNullOrWhiteSpace($KeepOldTargetAt)) {
            try {
                [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($KeepOldTargetAt))
                Invoke-TpmAutoSyncMovePath -Source $oldTarget -Destination $KeepOldTargetAt
                $technical.OldFolderKeptAt = $KeepOldTargetAt
            } catch {
                $cleanupCompleted = $false
                $residuePresent = $true
                $technical.CleanupError = $_.Exception.Message
                $residuePaths.Add($txRoot)
            }
        }
        if (-not $residuePresent) {
            try {
                Invoke-TpmAutoSyncRemovePath -Path $txRoot
            } catch {
                $cleanupCompleted = $false
                $residuePresent = $true
                $technical.CleanupError = $_.Exception.Message
                $residuePaths.Add($txRoot)
            }
        }
        if ($residuePresent) {
            $underlyingOutcome = 'SUCCEEDED'
            $requestedOutcome = 'CLEANUP_RESIDUE'
            $requestedState = 'INTENDED'
            $requestedSummary = 'The files are in a verified state, but TeknoParrot Manager could not finish cleanup. Review Details before retrying.'
            $requestedReason = 'CLEANUP_RESIDUE'
        } else {
            $requestedOutcome = 'SUCCEEDED'
            $requestedState = 'INTENDED'
            $requestedSummary = if ($NewTarget) { 'The new game folder was created and checked.' } else { 'Replacement completed and checked.' }
            $requestedReason = 'COMPLETED'
        }
        $registrationEligible = $true
    } catch {
        $technical.Error = $_.Exception.Message
        $errors.Add($_.Exception.Message)
        if ($_.Exception.Message -eq 'INSUFFICIENT_STAGING_SPACE') {
            $requestedReason = 'INSUFFICIENT_STAGING_SPACE'
        }
        if ($_.Exception.Message -eq 'STAGING_SPACE_UNAVAILABLE') {
            $requestedReason = 'STAGING_SPACE_UNAVAILABLE'
        }
        $stateChangedObserved = $false
        if ($stateCommitAttempted) {
            try {
                $stateNow = Get-TpmFileState -Path $stateFull
                $stateChangedObserved = -not (Test-TpmFileStateMatch -Expected $statePre -Actual $stateNow -IgnoreMetadata)
            } catch {
                $stateChangedObserved = $true
                $rollbackErrors.Add('Sync-state state could not be read during rollback assessment.')
            }
        }
        if ($stateChangedObserved -and -not $mutationStarted) {
            $mutationStarted = $true
            $stateChanged = $true
            $changedItems.Add('syncstate:' + $RawName)
        }

        if ($mutationStarted -or $targetMovedAside -or $targetPromoted -or $stateChangedObserved) {
            $rollbackAttempted = $true
            $technical.Stage = 'Rollback'

            if ($stateCommitAttempted -and $stateChangedObserved) {
                try {
                    Restore-TpmAutoSyncState -StatePath $stateFull -ExpectedPreState $statePre `
                        -BackupPath $(if ($stateCommitResult) { $stateCommitResult.BackupPath } else { $stateBackupPath }) `
                        -ExpectedCurrentHash $(if ($candidateFileState) { $candidateFileState.Sha256 } else { '' })
                    $rollbackItems.Add('metadata:syncstate')
                } catch {
                    $rollbackErrors.Add('metadata:syncstate -- ' + $_.Exception.Message)
                    $rollbackFailedItems.Add('metadata:syncstate')
                }
            }

            try {
                if ($targetMovedAside) {
                    $currentTarget = Get-TpmDirectoryManifest -Path $targetFull
                    if ($currentTarget.Exists) {
                        if (-not (Test-TpmDirectoryManifestMatch -Expected $stageManifest -Actual $currentTarget)) {
                            if (-not (Test-TpmDirectoryManifestMatch -Expected $targetPre -Actual $currentTarget)) {
                                throw 'AutoSync rollback refused to remove an unexpected promoted directory.'
                            }
                        } else {
                            Invoke-TpmAutoSyncRemovePath -Path $targetFull
                        }
                    }
                    if (-not (Test-Path -LiteralPath $targetFull)) {
                        Invoke-TpmAutoSyncMovePath -Source $oldTarget -Destination $targetFull
                    }
                    $restoredTarget = Get-TpmDirectoryManifest -Path $targetFull
                    if (-not (Test-TpmDirectoryManifestMatch -Expected $targetPre -Actual $restoredTarget)) {
                        throw 'AutoSync rollback target manifest did not match the captured pre-state.'
                    }
                    $rollbackItems.Add($RawName)
                } elseif ($targetPromoted -or $promotionAttempted) {
                    $currentTarget = Get-TpmDirectoryManifest -Path $targetFull
                    if ($currentTarget.Exists) {
                        if (-not (Test-TpmDirectoryManifestMatch -Expected $stageManifest -Actual $currentTarget)) {
                            throw 'AutoSync rollback refused to remove an unexpected new directory.'
                        }
                        Invoke-TpmAutoSyncRemovePath -Path $targetFull
                    }
                    $restoredTarget = Get-TpmDirectoryManifest -Path $targetFull
                    if (-not (Test-TpmDirectoryManifestMatch -Expected $targetPre -Actual $restoredTarget)) {
                        throw 'AutoSync rollback did not restore target absence.'
                    }
                    $rollbackItems.Add($RawName)
                }
            } catch {
                $rollbackErrors.Add($RawName + ' -- ' + $_.Exception.Message)
                $rollbackFailedItems.Add($RawName)
            }

            if ($sentinelCreated) {
                try {
                    if (Test-Path -LiteralPath $sentinelFull) { Invoke-TpmAutoSyncRemovePath -Path $sentinelFull }
                    if (Test-Path -LiteralPath $sentinelFull) { throw 'sentinel remained after rollback cleanup' }
                    $sentinelCreated = $false
                } catch {
                    $rollbackErrors.Add('metadata:sentinel -- ' + $_.Exception.Message)
                    $rollbackFailedItems.Add('metadata:sentinel')
                }
            }
            try {
                $rollbackTargetFinal = Get-TpmDirectoryManifest -Path $targetFull
                $rollbackStateFinal = Get-TpmFileState -Path $stateFull
                $rollbackSentinelFinal = Get-TpmFileState -Path $sentinelFull
                $rollbackLegacySentinelFinal = $rollbackSentinelFinal
                if ($legacySentinelPre.Path -ine $sentinelPre.Path) {
                    $rollbackLegacySentinelFinal = Get-TpmFileState -Path $legacySentinelPre.Path
                }
                if (-not (Test-TpmFileStateMatch -Expected $sentinelPre -Actual $rollbackSentinelFinal -IgnoreMetadata) -or
                    -not (Test-TpmFileStateMatch -Expected $legacySentinelPre -Actual $rollbackLegacySentinelFinal -IgnoreMetadata)) {
                    throw 'AutoSync rollback left an extraction sentinel in place.'
                }
                if (-not (Test-TpmDirectoryManifestMatch -Expected $targetPre -Actual $rollbackTargetFinal) -or
                    -not (Test-TpmFileStateMatch -Expected $statePre -Actual $rollbackStateFinal -IgnoreMetadata)) {
                    throw 'AutoSync rollback final pre-state verification failed.'
                }
            } catch {
                $rollbackErrors.Add('metadata:final -- ' + $_.Exception.Message)
                $rollbackFailedItems.Add('metadata:final')
            }

            if ($rollbackErrors.Count -eq 0) {
                $rollbackCompleted = $true
                $rollbackVerified = $true
                $finalAttempted = $true
                $finalPassed = $true
                $finalChecks.Add('Rollback restored the captured target and sync-state pre-state.')
                $requestedOutcome = 'ROLLED_BACK_VERIFIED'
                $requestedState = 'UNCHANGED'
                $requestedSummary = if ($extraFilesNotKept) {
                    'This game was not updated. TeknoParrot Manager could not save the extra files in the old folder (for example ReShade files or saves), so it put the old folder back as it was.'
                } else {
                    'The change did not finish. TPM restored the files to how they were before. Nothing new remains.'
                }
                $requestedReason = 'ROLLED_BACK'
                $mutationCompleted = $false
            } else {
                $requestedOutcome = 'ACTION_REQUIRED'
                $requestedState = 'UNKNOWN'
                $requestedSummary = 'TPM stopped before it could verify the final state and needs your attention. Do not retry blindly. Open Details for the next safe step.'
                $requestedReason = 'ROLLBACK_UNVERIFIED'
                $finalAttempted = $true
                $finalPassed = $false
                foreach ($item in $rollbackFailedItems) { $finalUnknownItems.Add($item) }
                $technical.RollbackError = $rollbackErrors.ToArray()
                $residuePresent = $true
                if ($txRoot) { $residuePaths.Add($txRoot) }
            }
        } else {
            $sentinelCleanupFailed = $false
            if ($sentinelCreated) {
                try {
                    Invoke-TpmAutoSyncRemovePath -Path $sentinelFull
                    $sentinelCreated = $false
                } catch {
                    $sentinelCleanupFailed = $true
                    $cleanupCompleted = $false
                    $residuePresent = $true
                    $technical.CleanupError = $_.Exception.Message
                    $residuePaths.Add($sentinelFull)
                }
            }
            $preStateStillMatches = $true
            # A failure before the pre-state capture (preflight) changed nothing and left no captured state to
            # compare: comparing null states would throw and report an unknown product state for an unchanged one.
            if ($null -ne $targetPre -and $null -ne $statePre -and $null -ne $sentinelPre -and $null -ne $legacySentinelPre) {
                try {
                    $failureTargetState = Get-TpmDirectoryManifest -Path $targetFull
                    $failureSyncState = Get-TpmFileState -Path $stateFull
                    $failureSentinelState = Get-TpmFileState -Path $sentinelFull
                    $failureLegacySentinelState = $failureSentinelState
                    if ($legacySentinelPre.Path -ine $sentinelPre.Path) {
                        $failureLegacySentinelState = Get-TpmFileState -Path $legacySentinelPre.Path
                    }
                    if (-not (Test-TpmFileStateMatch -Expected $sentinelPre -Actual $failureSentinelState -IgnoreMetadata) -or
                        -not (Test-TpmFileStateMatch -Expected $legacySentinelPre -Actual $failureLegacySentinelState -IgnoreMetadata)) {
                        $preStateStillMatches = $false
                    }
                    if (-not (Test-TpmDirectoryManifestMatch -Expected $targetPre -Actual $failureTargetState) -or
                        -not (Test-TpmFileStateMatch -Expected $statePre -Actual $failureSyncState -IgnoreMetadata)) {
                        $preStateStillMatches = $false
                    }
                } catch {
                    $preStateStillMatches = $false
                }
            }
            if ($preStateStillMatches -and -not $sentinelCleanupFailed) {
                $requestedOutcome = 'FAILED_BEFORE_MUTATION'
                $requestedState = 'UNCHANGED'
                $requestedSummary = if ($requestedReason -eq 'AMBIGUOUS_EXTRACTION_ROOT') {
                    'AutoSync refused an unproven extraction root. No game files or sync state were changed.'
                } elseif ($NewTarget) {
                    'Extraction stopped before the new game folder was created. Nothing was changed.'
                } else {
                    'Extraction stopped before replacing the existing folder. Nothing was changed.'
                }
                if ($requestedReason -eq 'PREFLIGHT_FAILED') { $requestedReason = 'STAGING_FAILED' }
                $failedItems.Add($RawName)
            } else {
                $requestedOutcome = 'ACTION_REQUIRED'
                $requestedState = 'UNKNOWN'
                $requestedSummary = 'TPM stopped before it could verify the final state and needs your attention. Do not retry blindly. Open Details for the next safe step.'
                $requestedReason = if ($sentinelCleanupFailed) { 'SENTINEL_CLEANUP_FAILED' } else { 'PRESTATE_CHANGED' }
                $unknownItems.Add($RawName)
                $finalAttempted = $true
                $finalPassed = $false
                if (Test-Path -LiteralPath $targetFull) { $residuePaths.Add($targetFull) }
                if (Test-Path -LiteralPath $stateFull) { $residuePaths.Add($stateFull) }
                if (Test-Path -LiteralPath $sentinelFull) { $residuePaths.Add($sentinelFull) }
                if ($legacySentinelPre.Path -ine $sentinelPre.Path -and (Test-Path -LiteralPath $legacySentinelPre.Path)) {
                    $residuePaths.Add($legacySentinelPre.Path)
                }
                if ($txRoot) { $residuePaths.Add($txRoot) }
                $residuePresent = ($residuePaths.Count -gt 0)
            }
        }
    }

    if ($txRoot -and -not $residuePresent -and
        $requestedOutcome -notin @('CLEANUP_RESIDUE') -and
        ($requestedOutcome -in @('FAILED_BEFORE_MUTATION','ROLLED_BACK_VERIFIED'))) {
        $cleanupAttempted = $true
        try {
            Invoke-TpmAutoSyncRemovePath -Path $txRoot
        } catch {
            $cleanupCompleted = $false
            $residuePresent = $true
            $technical.CleanupError = $_.Exception.Message
            $residuePaths.Add($txRoot)
        }
    }
    if ($residuePresent -and $requestedOutcome -eq 'ROLLED_BACK_VERIFIED') {
        $underlyingOutcome = 'ROLLED_BACK_VERIFIED'
        $requestedOutcome = 'CLEANUP_RESIDUE'
        $requestedState = 'UNCHANGED'
        $requestedSummary = 'The files are in a verified state, but TeknoParrot Manager could not finish cleanup. Review Details before retrying.'
        $requestedReason = 'CLEANUP_RESIDUE'
    }
    return (& $returnResult)
}

function Expand-ZipFileSafe {
    param([string]$ZipPath, [string]$DestDir, [string]$GameName = '', [hashtable]$EntryHashes = $null, [hashtable]$EntrySha1 = $null)

    # GetFullPath on the (short) base is safe. We deliberately avoid calling
    # GetFullPath on the combined base+entry path: on .NET 4.x (PS 5.1) that
    # throws PathTooLongException before \\?\ is ever applied, defeating the
    # whole purpose of this function.
    $destFull  = [System.IO.Path]::GetFullPath($DestDir).TrimEnd('\')
    # The \\?\ long-path prefix has a different form for UNC paths
    # (\\server\share\...) than for drive-letter paths -- a naive
    # '\\?\' + $destFull concatenation produces an invalid
    # '\\?\\\server\share\...' for UNC destinations. Build the correct
    # prefix once so every long-path target below uses the right form.
    $longPrefixBase = if ($destFull -match '^\\\\[^\?]') {
        '\\?\UNC\' + $destFull.Substring(2)
    } else {
        '\\?\' + $destFull
    }
    $label     = if ($GameName) { $GameName } else { [System.IO.Path]::GetFileNameWithoutExtension($ZipPath) }
    $archive   = $null
    $progressStarted = Get-Date
    $fileCount = 0
    $current = 0
    $currentDone = $false
    try {
        $archive   = [System.IO.Compression.ZipFile]::OpenRead($ZipPath)

        # ---- Preflight: validate the whole archive before touching disk ----
        $comparer = [System.StringComparer]::OrdinalIgnoreCase
        $fileTargets = New-Object 'System.Collections.Generic.Dictionary[string,string]' ($comparer)
        $directories = New-Object 'System.Collections.Generic.Dictionary[string,string]' ($comparer)
        $plan = New-Object System.Collections.Generic.List[object]
        # get_Entries() instead of .Entries: on Windows PowerShell 5.1 the
        # .NET Framework reader throws for an entry name with characters that
        # are illegal in paths, and a PowerShell property read swallows that
        # exception and yields nothing -- the archive would "extract" zero
        # files without any error. The method call lets the exception surface.
        $entries = $archive.get_Entries()
        foreach ($entry in $entries) {
            $info = ConvertTo-SafeZipEntryRelativePath -EntryName $entry.FullName
            $rel = $info.RelativePath
            if ($info.IsDirectory) {
                if ($fileTargets.ContainsKey($rel)) { throw "ZIP entry collides with a file entry of the same path: $($entry.FullName)" }
                $directories[$rel] = $entry.FullName
            } else {
                if ($fileTargets.ContainsKey($rel)) { throw "ZIP contains duplicate file entries for the same path: $($entry.FullName)" }
                if ($directories.ContainsKey($rel)) { throw "ZIP file entry collides with a directory of the same path: $($entry.FullName)" }
                $fileTargets[$rel] = $entry.FullName
            }
            # Every ancestor of an entry is a directory and must not be a file.
            $cut = $rel.LastIndexOf([char]'\')
            while ($cut -gt 0) {
                $ancestor = $rel.Substring(0, $cut)
                if ($fileTargets.ContainsKey($ancestor)) { throw "ZIP entry is nested under a file entry: $($entry.FullName)" }
                $directories[$ancestor] = $entry.FullName
                $cut = $ancestor.LastIndexOf([char]'\')
            }
            [void]$plan.Add([pscustomobject]@{ Entry = $entry; RelativePath = $rel; IsDirectory = $info.IsDirectory })
        }
        if ([System.IO.File]::Exists($longPrefixBase)) { throw "ZIP destination is an existing file, not a folder: $destFull" }
        foreach ($dirRel in $directories.Keys) {
            if ([System.IO.File]::Exists($longPrefixBase + '\' + $dirRel)) {
                throw "ZIP needs a folder where a file already exists in the destination: $dirRel"
            }
        }
        foreach ($fileRel in $fileTargets.Keys) {
            if ([System.IO.Directory]::Exists($longPrefixBase + '\' + $fileRel)) {
                throw "ZIP needs a file where a folder already exists in the destination: $fileRel"
            }
        }

        # ---- Write phase: only reached when the whole archive is valid ----
        $fileCount = $fileTargets.Count
        $current   = 0
        $copyBuffer = $null
        foreach ($item in $plan) {
            $longTarget = $longPrefixBase + '\' + $item.RelativePath
            if ($item.IsDirectory) {
                [void][System.IO.Directory]::CreateDirectory($longTarget)
                continue
            }

            $current++
            Write-TpmCompactExtractionProgress -Phase Extracting -Label $label -Current $current -Total $fileCount -StartedAt $progressStarted

            # CreateDirectory is idempotent; no Exists check needed (also avoids TOCTOU).
            $parentCut = $item.RelativePath.LastIndexOf([char]'\')
            $parent = if ($parentCut -gt 0) { $longPrefixBase + '\' + $item.RelativePath.Substring(0, $parentCut) } else { $longPrefixBase }
            [void][System.IO.Directory]::CreateDirectory($parent)

            $src = $item.Entry.Open()
            try {
                $dst = [System.IO.File]::Open($longTarget, [System.IO.FileMode]::Create,
                           [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
                # One very large game file can take longer than the stall time to write and reports nothing while it does:
                # "still working", never "stalled". Small files are not marked (thousands of them, each over in a moment).
                $longWait = $false
                if ($item.Entry.Length -ge 67108864 -and (Test-Path -LiteralPath 'Function:\Enter-TpmLongWait')) { $longWait = Enter-TpmLongWait }
                try   {
                    if ($null -ne $EntryHashes) {
                        # Hash the file while it is written, so the ZIP data is read once (1 MB at a time) and not again just to check it.
                        $entrySha = [System.Security.Cryptography.SHA256]::Create()
                        # The DAT lists SHA-1, so it can be taken in the same pass when asked for (only together with EntryHashes).
                        # (The hasher must not be named entrySha1: PowerShell names are not case-sensitive, so that would overwrite the EntrySha1 parameter.)
                        $sha1Hasher = $null
                        if ($null -ne $EntrySha1) { $sha1Hasher = [System.Security.Cryptography.SHA1]::Create() }
                        try {
                            if ($null -eq $copyBuffer) { $copyBuffer = New-Object byte[] 1048576 }
                            while (($copyRead = $src.Read($copyBuffer, 0, $copyBuffer.Length)) -gt 0) {
                                $dst.Write($copyBuffer, 0, $copyRead)
                                [void]$entrySha.TransformBlock($copyBuffer, 0, $copyRead, $null, 0)
                                if ($null -ne $sha1Hasher) { [void]$sha1Hasher.TransformBlock($copyBuffer, 0, $copyRead, $null, 0) }
                            }
                            [void]$entrySha.TransformFinalBlock($copyBuffer, 0, 0)
                            $EntryHashes[([string]$item.RelativePath).ToLowerInvariant()] = ((-join ($entrySha.Hash | ForEach-Object { $_.ToString('x2') })).ToUpperInvariant())
                            if ($null -ne $sha1Hasher) {
                                [void]$sha1Hasher.TransformFinalBlock($copyBuffer, 0, 0)
                                $EntrySha1[([string]$item.RelativePath).ToLowerInvariant()] = ((-join ($sha1Hasher.Hash | ForEach-Object { $_.ToString('x2') })).ToUpperInvariant())
                            }
                        } finally { $entrySha.Dispose(); if ($null -ne $sha1Hasher) { $sha1Hasher.Dispose() } }
                    } else {
                        $src.CopyTo($dst, 1048576)
                    }
                }
                finally { if ($longWait) { Exit-TpmLongWait }; $dst.Dispose() }
            } finally {
                if ($src) { $src.Dispose() }
            }
        }
        $currentDone = $true
    } finally {
        if ($archive) { $archive.Dispose() }
        Write-TpmCompactExtractionProgress -Phase Extracting -Label $label -Current $(if ($currentDone) { $current } else { $current - 1 }) -Total $fileCount -StartedAt $progressStarted -Complete -Outcome $(if ($currentDone) { 'Final' } else { 'Error' })
    }
}

# Sums top-level source ZIP sizes for the AutoSync staging-space preflight.
function Get-TpmZipSourceByteTotal {
    param([string]$ZipSource)
    $totalBytes = [double]0
    $scanStarted = Get-Date
    $scanCurrent = 0
    Write-TpmCompactExtractionProgress -Phase Checking -Label 'AutoSync source ZIP size scan' -Current $scanCurrent -Total 0 -StartedAt $scanStarted
    $scanCurrentCompleted = $false
    try {
        Get-ChildItem -LiteralPath $ZipSource -Filter *.zip -ErrorAction SilentlyContinue | ForEach-Object {
            $totalBytes += [double]$_.Length
            $scanCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'AutoSync source ZIP size scan' -Current $scanCurrent -Total 0 -StartedAt $scanStarted
        }
        $scanCurrentCompleted = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'AutoSync source ZIP size scan' -Current $scanCurrent -Total 0 -StartedAt $scanStarted -Complete -Outcome $(if ($scanCurrentCompleted) { 'Final' } else { 'Error' })
    }
    return $totalBytes
}

# Distinguishes an absent AutoSync sync-state file (a genuine first run) from
# an existing file that cannot be read or is not a JSON object. Never writes.
# Status: 'Absent' (State empty), 'Valid' (State = loaded entries), or
# 'Invalid' (Reason explains; the caller must fail closed and never treat it
# as a fresh install).
function Test-TpmAutoSyncStateFile {
    param([Parameter(Mandatory)][string]$Path)
    $state = @{}
    if (-not (Test-Path -LiteralPath $Path)) {
        return [pscustomobject]@{ Status = 'Absent'; Reason = $null; State = $state }
    }
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        return [pscustomobject]@{ Status = 'Invalid'; Reason = 'The sync-state path exists but is not a file.'; State = $state }
    }
    try {
        $text = [System.IO.File]::ReadAllText($Path)
    } catch {
        return [pscustomobject]@{ Status = 'Invalid'; Reason = ('The sync-state file could not be read: ' + $_.Exception.Message); State = $state }
    }
    try {
        $loaded = $text | ConvertFrom-Json -ErrorAction Stop
    } catch {
        return [pscustomobject]@{ Status = 'Invalid'; Reason = 'The sync-state file is not valid JSON.'; State = $state }
    }
    if ($null -eq $loaded -or -not ($loaded -is [System.Management.Automation.PSCustomObject])) {
        return [pscustomobject]@{ Status = 'Invalid'; Reason = 'The sync-state file does not contain a JSON object.'; State = $state }
    }
    foreach ($prop in $loaded.PSObject.Properties) { $state[$prop.Name] = $prop.Value }
    return [pscustomobject]@{ Status = 'Valid'; Reason = $null; State = $state }
}

# Copies the exact bytes of an invalid sync-state file to a new, uniquely
# named sibling ('<name>.invalid-<timestamp>-<guid>.json', opened CreateNew so
# nothing existing is overwritten) and verifies the copy by SHA-256. The
# original is never modified or deleted here. Returns the copy path; throws
# when the copy cannot be created or verified.
function Save-TpmInvalidAutoSyncStateCopy {
    param([Parameter(Mandatory)][string]$Path)
    $full = [System.IO.Path]::GetFullPath($Path)
    $directory = [System.IO.Path]::GetDirectoryName($full)
    $copyName = [System.IO.Path]::GetFileNameWithoutExtension($full) + '.invalid-' + (Get-Date).ToString('yyyyMMdd-HHmmss', [System.Globalization.CultureInfo]::InvariantCulture) + '-' + [guid]::NewGuid().ToString('N') + '.json'
    $copyPath = Join-Path $directory $copyName
    Assert-TpmNoReparseWriteTarget -Path $copyPath -Operation 'AutoSync invalid sync-state preservation'
    $bytes = [System.IO.File]::ReadAllBytes($full)
    $created = $false
    $stream = $null
    try {
        $stream = New-Object System.IO.FileStream($copyPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        $created = $true
        $stream.Write($bytes, 0, $bytes.Length)
        $stream.Flush($true)
        $stream.Dispose()
        $stream = $null
        $sha = [System.Security.Cryptography.SHA256]::Create()
        try {
            $originalHash = [System.BitConverter]::ToString($sha.ComputeHash($bytes))
            $copyHash = [System.BitConverter]::ToString($sha.ComputeHash([System.IO.File]::ReadAllBytes($copyPath)))
        } finally { $sha.Dispose() }
        $currentHash = (Get-FileHash -LiteralPath $full -Algorithm SHA256 -ErrorAction Stop).Hash
        if ($originalHash -ne $copyHash -or ($originalHash -replace '-', '') -ne $currentHash) {
            throw 'The preserved copy of the invalid sync state did not match the original bytes.'
        }
        $created = $false
        return $copyPath
    } finally {
        if ($null -ne $stream) { $stream.Dispose() }
        # Remove only a copy this call created and could not verify.
        if ($created -and (Test-Path -LiteralPath $copyPath -PathType Leaf)) { Remove-Item -LiteralPath $copyPath -Force -ErrorAction SilentlyContinue }
    }
}

# AutoSync only unpacks .zip files (issue #301). A .7z or .rar archive in the source folder used to be skipped without a word.
# Says so once, plainly, and returns how many were skipped. Read-only: it lists the folder and changes nothing.
function Write-TpmSkippedArchiveNotice {
    param([string]$SourceFolder)
    $skipped = @(Get-ChildItem -LiteralPath $SourceFolder -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -imatch '\.(7z|rar)(\.\d{3})?$' })
    if ($skipped.Count -eq 0) { return 0 }
    Write-Host ''
    Write-Host ('  {0} archive(s) in this folder are .7z or .rar files. AutoSync cannot unpack them, so it skipped them.' -f $skipped.Count) -ForegroundColor Yellow
    Write-Host '  To use them: unpack each one into your games folder yourself,' -ForegroundColor DarkCyan
    Write-Host '  then choose Register only from the main menu.' -ForegroundColor DarkCyan
    Write-Log ('AutoSync: skipped {0} .7z/.rar archive(s) in {1} (only .zip is unpacked): {2}' -f $skipped.Count, $SourceFolder, (($skipped | Select-Object -First 20 | ForEach-Object { $_.Name }) -join ', '))
    return $skipped.Count
}

# Extracts NAS ZIPs through a verified directory transaction. Existing target
# folders are preserved until staging and pre-state verification are complete.
# ZIP base names listed in $noSync are skipped.
#
# An existing sync-state file that cannot be loaded is never treated as a
# fresh install: the run stops before any mutation with StateRefused=$true
# (Failed=1) unless the caller passes -RebuildInvalidState after the owner
# explicitly chose to rebuild AND the original bytes were preserved in
# -InvalidStatePreservedCopy (see Save-TpmInvalidAutoSyncStateCopy).
function Invoke-AutoSync {
    param([string]$zipSource, [string]$installFolder, [string]$syncStatePath,
          $noSync = @(), $onlySync = @(), [string[]]$OnlyProfileCodes = @(), [bool]$retroBat = $false, [bool]$DryRun = $false,
          [hashtable]$datIndex = $null, [string]$userProfilesDir = '',
          [bool]$RebuildInvalidState = $false, [string]$InvalidStatePreservedCopy = '')

    $syncState = @{}
    $stateCheck = Test-TpmAutoSyncStateFile -Path $syncStatePath
    if ($stateCheck.Status -eq 'Valid') {
        $syncState = $stateCheck.State
    } elseif ($stateCheck.Status -eq 'Invalid') {
        $rebuildAuthorized = ($RebuildInvalidState -and -not [string]::IsNullOrWhiteSpace($InvalidStatePreservedCopy) -and
            (Test-Path -LiteralPath $InvalidStatePreservedCopy -PathType Leaf))
        if (-not $rebuildAuthorized) {
            Write-Log "AutoSync: existing sync state is invalid ($($stateCheck.Reason)) -- stopped before any change; the file was kept as-is."
            Write-Host "  AutoSync stopped: the existing sync-state file could not be loaded, so nothing was extracted or changed." -ForegroundColor Red
            Write-Host "  The file was kept exactly as it is: $syncStatePath" -ForegroundColor Yellow
            Write-Host "  Run AutoSync interactively and choose [R] to rebuild it (TeknoParrot Manager" -ForegroundColor Yellow
            Write-Host "  keeps a copy of the original first), or restore a good copy of the file yourself." -ForegroundColor Yellow
            return @{ Synced = 0; SyncedNames = @(); UpToDate = 0; Failed = 1; Skipped = 0; UnsafePathSkipped = 0; WouldSync = 0; TransactionResults = @(); StateRefused = $true; StateReason = [string]$stateCheck.Reason }
        }
        Write-Log "AutoSync: existing sync state is invalid ($($stateCheck.Reason)); owner chose to rebuild it. Original bytes preserved at $InvalidStatePreservedCopy."
    }

    $zipFiles = @(Get-TpmTopLevelZipSourceFiles -ZipSource $zipSource -ProgressLabel 'AutoSync source ZIP discovery')
    [void](Write-TpmSkippedArchiveNotice -SourceFolder $zipSource)
    if (-not $zipFiles -or $zipFiles.Count -eq 0) {
        Write-Host "  No ZIP files found in source. Skipping extraction." -ForegroundColor Yellow
        $subdirHits = @(Get-TpmImmediateZipSubdirectorySummary -ZipSource $zipSource)
        if ($subdirHits.Count -gt 0) {
            Write-Host "  Tip: ZIPs found one level down -- point the source path at one of these directly:" -ForegroundColor Cyan
            foreach ($sd in $subdirHits) {
                Write-Host "    $($sd.Path)  ($($sd.Count) ZIPs)" -ForegroundColor DarkCyan
            }
        }
        return @{ Synced = 0; SyncedNames = @(); UpToDate = 0; Failed = 0; Skipped = 0; UnsafePathSkipped = 0; WouldSync = 0; TransactionResults = @() }
    }

    $syncedNames = New-Object System.Collections.Generic.List[string]
    $transactionResults = New-Object System.Collections.Generic.List[object]
    $synced = 0; $upToDate = 0; $failed = 0; $skipped = 0; $unsafePathSkipped = 0; $wouldSync = 0

    if ($onlySync.Count -gt 0) {
        Write-Host "  Whitelist active: only extracting $($onlySync.Count) game(s) listed in onlySync." -ForegroundColor Cyan
    }

    # Build the shared extracted-folder resolver map so AutoSync and the
    # interactive picker agree on which ZIPs are already present.
    $normalizedFolderMap = Get-StagingFolderMap $installFolder
    # Names of new game folders planned in this run: a second ZIP for the same game must not create a
    # second folder before the first one is visible in the folder map (next run).
    $claimedNewFolderKeys = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $claimedTargetFolders = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)

    # #352/#365: freeze and publish the complete selected-unit manifest before any
    # extraction can start. A refusal here leaves every game folder untouched.
    $ledgerActive = $false
    $ledgerOperationId = ''
    if (-not $DryRun -and (Test-TpmRegistrationLedgerConfigured)) {
        $selectedUnits = New-Object System.Collections.Generic.List[object]
        foreach ($candidateZip in $zipFiles) {
            $candidateName = [System.IO.Path]::GetFileNameWithoutExtension($candidateZip.Name)
            if (Test-TpmAutoSyncZipSelected -RawName $candidateName -NoSync $noSync -OnlySync $onlySync -OnlyProfileCodes $OnlyProfileCodes -DatIndex $datIndex) { [void]$selectedUnits.Add([pscustomobject]@{ Folder = $candidateName }) }
        }
        if ($selectedUnits.Count -gt 0) {
            $ledgerOpen = Open-TpmRegistrationLedgerOperation -Mode AutoSync -Units $selectedUnits.ToArray() -InstallRoot $installFolder
            if (-not $ledgerOpen.Opened) {
                Write-Host ('  ' + $ledgerOpen.Message) -ForegroundColor Red
                Write-Log ('AutoSync refused before extraction: ' + $ledgerOpen.Message)
                return @{ Synced = 0; SyncedNames = @(); UpToDate = 0; Failed = 0; Skipped = 0; UnsafePathSkipped = 0; WouldSync = 0; TransactionResults = @(); EvidenceRefused = $true; EvidenceMessage = [string]$ledgerOpen.Message }
            }
            $ledgerActive = $true
            $ledgerOperationId = [string]$ledgerOpen.OperationId
        }
    }

    foreach ($zip in $zipFiles) {
        if ($ledgerActive -and (Test-TpmRegistrationLedgerStopped)) {
            Write-Host '  Stopping: registration evidence could not be published, so no further selected extraction will start.' -ForegroundColor Yellow
            Write-Log 'AutoSync: stopped before the next selected unit because registration evidence publication failed.'
            break
        }
        $rawName    = [System.IO.Path]::GetFileNameWithoutExtension($zip.Name)
        if ($noSync -contains $rawName) {
            Write-Host "  Skipped (override) : $rawName" -ForegroundColor DarkGray
            Write-Log "AutoSync: skipped '$rawName' -- it is on your skip list."
            $skipped++; continue
        }
        # Skip collection metadata files (changelog, game notes, readme).
        # These start with "!TeknoParrot Collection" regardless of date suffix.
        if ($rawName -like '!TeknoParrot Collection*') {
            Write-Host "  Skipped (metadata)  : $rawName" -ForegroundColor DarkGray
            Write-Log "AutoSync: skipped '$rawName' -- collection information file, not a game."
            $skipped++; continue
        }
        # If a raw-name whitelist is active, skip anything not on it.
        if ($onlySync.Count -gt 0 -and $onlySync -notcontains $rawName) {
            Write-Log "AutoSync: skipped '$rawName' -- it is not on your only-these-games list."
            $skipped++
            continue
        }
        # Health Check uses profile codes, which are stable even when a ZIP
        # carries release/version metadata in its base name.
        if ($OnlyProfileCodes.Count -gt 0) {
            $datEntry = Get-DatEntryForZipName -RawZipName $rawName -DatIndex $datIndex
            $profileCode = if ($datEntry) { [string]$datEntry.ProfileCode } else { '' }
            if ($OnlyProfileCodes -notcontains $profileCode) {
                $skipped++
                continue
            }
        }
        # A ZIP base name is metadata, not proof of the installed game root.
        # The extraction target below must come from current folder/profile resolution.
        $extractFolderName = if ($retroBat) { "$rawName.teknoparrot" } else { $rawName }
        $archiveNamePath = Join-Path $installFolder $extractFolderName
        # Guard the legacy marker name; this check does not authorize it as a target.
        if (-not (Test-PathInside $archiveNamePath $installFolder)) {
            Write-Host "  TeknoParrot Manager skipped '$rawName': the archive name is unsafe." -ForegroundColor Red
            Write-Log "AutoSync: skipped '$rawName' -- archive-derived path '$archiveNamePath' is outside install folder '$installFolder'"
            [void](Update-TpmRegistrationLedgerUnit -OperationId $ledgerOperationId -SourceName $rawName -State SKIPPED -Reason 'UNSAFE_ARCHIVE_NAME' -Extraction 'REFUSED')
            $unsafePathSkipped++; $skipped++; continue
        }
        # Preserve the ZIP-name marker for recovery; the transaction also checks
        # its marker beside the resolver-confirmed target.
        $sentinel   = Join-Path $installFolder "$extractFolderName.extracting"
        $nasModStr  = $zip.LastWriteTimeUtc.ToString("o")
        $stored     = $syncState[$rawName]

        # Resolve an existing, non-empty folder using exact naming,
        # RetroBat suffixes, path-limit aliases, dat/profile identity, and a
        # conservative fuzzy metadata match. See issue #66.
        $matchedFolder = Resolve-ExtractedGameFolder -RawZipName $rawName -InstallFolder $installFolder -FolderMap $normalizedFolderMap -DatIndex $datIndex -UserProfilesDir $userProfilesDir

        $needsSync = $false
        $reason = ''
        $rootRefusalReason = ''
        $targetDir = $null
        $storedPath = [string](Get-TpmTransactionField -Object $stored -Name 'LocalPath')
        $storedPathFull = $null
        if (-not [string]::IsNullOrWhiteSpace($storedPath)) {
            try {
                $storedPathFull = [System.IO.Path]::GetFullPath($storedPath)
                if (-not (Test-PathInside $storedPathFull $installFolder)) {
                    $rootRefusalReason = 'stored LocalPath is outside the install folder'
                }
            } catch {
                $rootRefusalReason = 'stored LocalPath could not be resolved safely'
            }
        }
        $matchedFolderFull = $null
        if (-not $rootRefusalReason -and $matchedFolder) {
            try {
                $matchedFolderFull = [System.IO.Path]::GetFullPath($matchedFolder)
                if (-not (Test-PathInside $matchedFolderFull $installFolder)) {
                    $rootRefusalReason = 'resolved game folder is outside the install folder'
                }
            } catch {
                $rootRefusalReason = 'resolved game folder could not be verified safely'
            }
        }
        $newGameFolder = $false
        if (-not $rootRefusalReason) {
            if (-not $matchedFolderFull) {
                # First-time extraction: no existing folder or profile identity matches this ZIP, so plan a
                # NEW direct child of the install folder named from the ZIP. Existing unconfirmed folders,
                # ambiguous names and registered identities still refuse (Resolve-TpmAutoSyncNewGameFolder).
                try {
                    $newFolderPlan = Resolve-TpmAutoSyncNewGameFolder -RawZipName $rawName -FolderName $extractFolderName `
                        -InstallFolder $installFolder -FolderMap $normalizedFolderMap -DatIndex $datIndex -UserProfilesDir $userProfilesDir `
                        -ClaimedKeys $claimedNewFolderKeys
                } catch {
                    $newFolderPlan = [pscustomobject]@{ Path = $null; Reason = 'the new game folder could not be planned safely' }
                }
                if (-not [string]::IsNullOrWhiteSpace([string]$newFolderPlan.Reason)) {
                    $rootRefusalReason = 'no existing folder or profile identity confirms the extraction root and no new folder can be created: ' + [string]$newFolderPlan.Reason
                } elseif ($storedPathFull -and
                          $storedPathFull.TrimEnd([char[]]"\/") -ine ([string]$newFolderPlan.Path).TrimEnd([char[]]"\/")) {
                    $rootRefusalReason = 'stored LocalPath conflicts with the new game folder'
                } else {
                    $targetDir = [string]$newFolderPlan.Path
                    $newGameFolder = $true
                }
            } elseif ($storedPathFull -and
                      $storedPathFull.TrimEnd([char[]]"\/") -ine $matchedFolderFull.TrimEnd([char[]]"\/")) {
                $rootRefusalReason = 'stored LocalPath conflicts with the resolved game root'
            } else {
                $targetDir = $matchedFolderFull
            }
        }
        $registeredGamePath = ''
        $registeredEntry = Get-DatEntryForZipName -RawZipName $rawName -DatIndex $datIndex
        if (-not $rootRefusalReason -and $registeredEntry -and $registeredEntry.ProfileCode -and $userProfilesDir) {
            try {
                if ($registeredEntry.ProfileCode -notmatch '^[\w-]+$') { throw 'Registered profile identity is unsafe.' }
                $registeredProfilePath = Join-Path $userProfilesDir ($registeredEntry.ProfileCode + '.xml')
                if (Test-Path -LiteralPath $registeredProfilePath -ErrorAction Stop) {
                    $registeredDoc = Read-Xml $registeredProfilePath
                    $registeredPathNode = $registeredDoc.GameProfile.SelectSingleNode('GamePath')
                    if ($null -eq $registeredPathNode -or [string]::IsNullOrWhiteSpace($registeredPathNode.InnerText)) {
                        # The profile exists but is not linked to a game file yet (TeknoParrot keeps a profile for games that are not set up).
                        # Nothing is registered, so there is nothing to bind to the archive.
                        $registeredPathNode = $null
                    }
                    if ($null -ne $registeredPathNode) { $registeredGamePath = [System.IO.Path]::GetFullPath($registeredPathNode.InnerText.Trim()) }
                    if ($registeredGamePath -and -not (Test-Path -LiteralPath $registeredGamePath -PathType Leaf -ErrorAction Stop)) {
                        # A new game folder may restore a registered game whose folder is gone, but only when the
                        # registered executable lies inside that new folder; the transaction then binds it to the
                        # matching ZIP entry before anything is written.
                        if (-not ($newGameFolder -and (Test-PathInside -child $registeredGamePath -parent $targetDir))) {
                            if ($newGameFolder) {
                                # The saved game file is missing at an old location (for example the library moved to another drive).
                                # Nothing is installed there, so extract into the new folder; registration points the profile at it afterwards.
                                Write-Log ('AutoSync: the saved game file for ''{0}'' is missing at its old location; the game will be set up again in the new folder.' -f $rawName)
                                $registeredGamePath = ''
                            } else {
                                throw 'Registered executable path could not be verified.'
                            }
                        }
                    }
                }
            } catch {
                $rootRefusalReason = 'registered executable could not be bound to archive-root verification (' + $_.Exception.Message + ')'
            }
        }
        if (-not $rootRefusalReason -and $newGameFolder -and -not [string]::IsNullOrWhiteSpace($registeredGamePath) -and
            -not (Test-PathInside -child $registeredGamePath -parent $targetDir)) {
            # The game is already registered at an executable that is not in the new folder.
            $rootRefusalReason = 'a registered profile points to a game executable outside the new game folder'
        }
        if ($rootRefusalReason) {
            Write-Host "  TeknoParrot Manager skipped '$rawName': it could not confirm the game folder. No files or sync state for this ZIP were changed." -ForegroundColor Yellow
            Write-Log ("AutoSync: refused unproven extraction root for '{0}': {1}" -f $rawName, $rootRefusalReason)
            [void](Update-TpmRegistrationLedgerUnit -OperationId $ledgerOperationId -SourceName $rawName -State SKIPPED -Reason 'UNPROVEN_EXTRACTION_ROOT' -Extraction 'REFUSED')
            $unsafePathSkipped++; $skipped++; continue
        }
        if (-not (Test-TpmAutoSyncDirectChildTarget -TargetDir $targetDir -InstallFolder $installFolder)) {
            Write-Host "  TeknoParrot Manager skipped '$rawName': the resolved folder is not an install-root child. No files or sync state for this ZIP were changed." -ForegroundColor Yellow
            Write-Log ("AutoSync: refused a nested target for '{0}': {1}" -f $rawName, $targetDir)
            [void](Update-TpmRegistrationLedgerUnit -OperationId $ledgerOperationId -SourceName $rawName -State SKIPPED -Reason 'NESTED_TARGET_REFUSED' -Extraction 'REFUSED')
            $unsafePathSkipped++; $skipped++; continue
        }

        if ($null -eq $stored) {
            $hasContent = $matchedFolder -and (-not (Test-Path -LiteralPath $sentinel))
            if ($hasContent) {
                $needsSync = $true
                $reason = 'verify existing folder'
            } else {
                $needsSync = $true
                $reason = 'new'
            }
        } elseif ([long]$stored.NasSize -ne $zip.Length -or (ConvertTo-TpmSyncStampText $stored.NasLastModified) -ne $nasModStr) {
            $needsSync = $true
            $reason = 'changed on NAS'
        } elseif (-not (Test-Path -LiteralPath $targetDir)) {
            $needsSync = $true
            $reason = 'not extracted'
        } elseif ((Test-Path -LiteralPath $sentinel) -or
                  (Test-Path -LiteralPath ($targetDir + '.extracting'))) {
            $needsSync = $true
            $reason = 'incomplete previous extraction'
        }
        if ($newGameFolder) {
            # An empty folder with a stale sync-state entry still needs its first extraction.
            if (-not $needsSync) { $needsSync = $true; $reason = 'not extracted' }
            foreach ($claimKey in @(Get-TpmAutoSyncClaimKeys -RawZipName $rawName -DatIndex $datIndex)) { [void]$claimedNewFolderKeys.Add([string]$claimKey) }
        }

        # Two ZIPs that write to the same existing folder in one run would replace each other's files: only the first writing ZIP is processed.
        $targetClaimKey = ([string]$targetDir).TrimEnd([char[]]"\/")
        if ($needsSync -and $claimedTargetFolders.Contains($targetClaimKey)) {
            Write-Host "  TeknoParrot Manager skipped '$rawName': another ZIP in this run already updates the same game folder. No files or sync state for this ZIP were changed." -ForegroundColor Yellow
            Write-Log ("AutoSync: skipped '{0}'; target folder already claimed by another ZIP this run: {1}" -f $rawName, $targetDir)
            [void](Update-TpmRegistrationLedgerUnit -OperationId $ledgerOperationId -SourceName $rawName -State SKIPPED -Reason 'DUPLICATE_TARGET_FOLDER' -Extraction 'REFUSED')
            $skipped++; continue
        }
        # A dry run claims only for a planned write. "verify existing folder" is usually a state-only repair that writes no game files, and a real run does not claim for that.
        if ($needsSync -and $DryRun -and $reason -ne 'verify existing folder') { [void]$claimedTargetFolders.Add($targetClaimKey) }

        if ($DryRun) {
            if (-not $needsSync) {
                Write-Host "  Already extracted (dry run; no ZIP work): $rawName" -ForegroundColor DarkGray
                $upToDate++
            } else {
                Write-Host "  Would extract ($reason) : $rawName" -ForegroundColor Yellow
                Write-Log "AutoSync DryRun: would extract $rawName ($reason)"
                $wouldSync++
            }
            continue
        }

        if ($ledgerActive -and -not (Update-TpmRegistrationLedgerUnit -OperationId $ledgerOperationId -SourceName $rawName)) {
            Write-Host "  TeknoParrot Manager skipped '$rawName': it is not in the published selection manifest. No files or sync state for this ZIP were changed." -ForegroundColor Yellow
            Write-Log "AutoSync: refused '$rawName' -- not in the published selection manifest."
            $skipped++; continue
        }
        if (-not $needsSync) {
            # The ZIP is unchanged and the folder is already extracted: never swap out a folder the player may have played in.
            Write-Host "  Already extracted (ZIP unchanged): $rawName" -ForegroundColor DarkGray
            Write-Log "AutoSync: $rawName already extracted and ZIP unchanged; left alone."
            if ($ledgerActive) { [void](Update-TpmRegistrationLedgerUnit -OperationId $ledgerOperationId -SourceName $rawName -State SKIPPED -Reason 'UP_TO_DATE_NOT_REGISTERED_THIS_RUN' -Extraction 'NO_OP' -Publish:$false) }
            $upToDate++
            continue
        }
        Write-Host "  Verifying transaction ($reason) : $rawName" -ForegroundColor Yellow
        Write-Log "AutoSync: transaction $rawName ($reason)"
        $tx = Invoke-TpmAutoSyncDirectoryTransaction `
            -ZipPath $zip.FullName -InstallFolder $installFolder -TargetDir $targetDir `
            -RawName $rawName -SyncStatePath $syncStatePath -SyncState $syncState `
            -StoredState $stored -LegacySentinelPath $sentinel -RegisteredGamePath $registeredGamePath `
            -NewTarget:$newGameFolder
        $txResult = $tx.TransactionResult
        # Claim the folder only if this ZIP changed it or left it in an unknown state; a ZIP that wrote nothing must not block a later one.
        if ($tx.FilesystemChanged -or [string](Get-TpmTransactionField -Object $txResult -Name 'ProductState') -eq 'UNKNOWN') { [void]$claimedTargetFolders.Add($targetClaimKey) }
        [void]$transactionResults.Add($txResult)
        $namesBefore = $syncedNames.Count
        switch ($txResult.Outcome) {
            'NO_OP' {
                Write-Host "    Already extracted (no ZIP work; GamePath repair is separate): $rawName" -ForegroundColor DarkGray
                Write-Log "AutoSync: '$rawName' counted as already extracted; no ZIP work. Folder used: $targetDir ($reason)"
                $upToDate++
            }
            'SUCCEEDED' {
                if ($tx.RegistrationEligible -and $tx.FilesystemChanged) {
                    Write-Host "    -> $($tx.TargetPath)" -ForegroundColor Green
                    if ([int]$txResult.TechnicalDetails.ExtraFileCount -gt 0) {
                        Write-Host ("    {0} file(s) in the old folder were extra or different from the ZIP (for example saves, settings or ReShade files). Copies are in the Backups folder under AutoSyncReplaced." -f $txResult.TechnicalDetails.ExtraFileCount) -ForegroundColor Yellow
                    }
                    $synced++
                    $registrationName = [System.IO.Path]::GetFileName(([string]$tx.TargetPath).TrimEnd([char[]]"\/"))
                    if ($registrationName) { [void]$syncedNames.Add($registrationName) }
                } else {
                    Write-Host "    Existing folder verified and state repaired." -ForegroundColor DarkGray
                    $upToDate++
                }
            }
            'CLEANUP_RESIDUE' {
                if ($tx.RegistrationEligible -and $tx.FilesystemChanged -and
                    [string]$txResult.UnderlyingOutcome -eq 'SUCCEEDED') {
                    Write-Host "    -> $($tx.TargetPath) (cleanup residue preserved)" -ForegroundColor Yellow
                    $synced++
                    $registrationName = [System.IO.Path]::GetFileName(([string]$tx.TargetPath).TrimEnd([char[]]"\/"))
                    if ($registrationName) { [void]$syncedNames.Add($registrationName) }
                } else {
                    Write-Host "    CLEANUP RESIDUE -- review Details." -ForegroundColor Red
                    $failed++
                }
            }
            default {
                Write-Host "    FAILED -- $($txResult.Summary)" -ForegroundColor Red
                if ($txResult.ReasonCode -eq 'AMBIGUOUS_EXTRACTION_ROOT') { $unsafePathSkipped++ }
                $failed++
            }
        }
        if ($ledgerActive) {
            $newTarget = if ($syncedNames.Count -gt $namesBefore) { [string]$syncedNames[$syncedNames.Count - 1] } else { '' }
            $unitState = ''
            $unitReason = ''
            if (-not $newTarget) {
                if ([string]$txResult.Outcome -eq 'NO_OP') { $unitState = 'SKIPPED'; $unitReason = 'UP_TO_DATE_NOT_REGISTERED_THIS_RUN' }
                elseif ([string]$txResult.Outcome -eq 'SUCCEEDED') { $unitState = 'SKIPPED'; $unitReason = 'EXISTING_FOLDER_VERIFIED_NOT_REGISTERED_THIS_RUN' }
                elseif ([string](Get-TpmTransactionField -Object $txResult -Name 'ProductState') -eq 'UNKNOWN') { $unitState = 'WRITE_ATTEMPTED_UNVERIFIED'; $unitReason = 'EXTRACTION_' + [string]$txResult.ReasonCode }
                else { $unitState = 'FAILED_BEFORE_WRITE'; $unitReason = 'EXTRACTION_' + [string]$txResult.ReasonCode }
            }
            $rollbackFacts = Get-TpmTransactionField -Object $txResult -Name 'Rollback'
            $rollbackText = if ([bool](Get-TpmTransactionField -Object $rollbackFacts -Name 'Attempted' -Default $false)) { if ([bool](Get-TpmTransactionField -Object $rollbackFacts -Name 'Verified' -Default $false)) { 'ATTEMPTED_VERIFIED' } else { 'ATTEMPTED_UNVERIFIED' } } else { 'NOT_ATTEMPTED' }
            [void](Update-TpmRegistrationLedgerUnit -OperationId $ledgerOperationId -SourceName $rawName -State $unitState -Reason $unitReason -Extraction ([string]$txResult.Outcome) -TargetFolder $newTarget -Rollback $rollbackText -Publish:([string]$txResult.Outcome -ne 'NO_OP'))
        }
    }

    # Flush skip/up-to-date unit states that were only held in memory (a later AutoSync pass re-reads the ledger).
    if ($ledgerActive -and -not (Test-TpmRegistrationLedgerStopped)) { [void](Publish-TpmRegistrationLedgerContext) }
    return @{
        Synced = $synced
        SyncedNames = $syncedNames.ToArray()
        UpToDate = $upToDate
        Failed = $failed
        Skipped = $skipped
        UnsafePathSkipped = $unsafePathSkipped
        WouldSync = $wouldSync
        TransactionResults = $transactionResults.ToArray()
        EvidenceStopped = (Test-TpmRegistrationLedgerStopped)
    }
}


# Builds a lookup of TeknoParrot profiles keyed by their executable name(s)
# (lowercased). Each <ExecutableName> may contain multiple alternatives
# separated by ; or | -- all alternatives are indexed so any matching file
# found on disk correctly identifies the game.
function Build-ProfileIndex {
    param([string]$gameProfilesDir)
    $index = @{}
    $templates = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $gameProfilesDir -ProgressLabel 'TeknoParrot executable index discovery' -Filter '*.xml' -EnumerationErrorAction SilentlyContinue)
    $scanStarted = Get-Date
    $scanCurrent = 0
    $scanCurrentDone = $false
    try {
        foreach ($tpl in $templates) {
            $scanCurrent++
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'TeknoParrot executable index scan' -Current $scanCurrent -Total $templates.Count -StartedAt $scanStarted
            $exe = Get-PrimaryExecutableName $tpl.FullName
            if ($exe -and $exe.Trim() -ne "") {
                foreach ($alt in (Get-TpmGameFileSet -ExecutableName $exe.Trim()).Choices) {
                    $k = $alt.ToLowerInvariant()
                    if (-not $index.ContainsKey($k)) { $index[$k] = @() }
                    $index[$k] += [pscustomobject]@{
                        Code         = $tpl.BaseName
                        TemplatePath = $tpl.FullName
                        ExeName      = $exe.Trim()
                    }
                }
            }
        }
        $scanCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'GameProfiles' -Current $(if ($scanCurrentDone) { $scanCurrent } else { $scanCurrent - 1 }) -Total $templates.Count -StartedAt $scanStarted -Complete -Outcome $(if ($scanCurrentDone) { 'Final' } else { 'Error' })
    }
    return $index
}

# Streaming XmlReader parser for No-Intro Logiqx XML dat files.
# Reads <game name="..."><GameProfile>...<Executable>... without loading the
# entire document into memory -- required for the 584 MB collection dat.
# Skips <rom> nodes (hash tables) to stay fast.
# Returns normalized-name -> { ProfileCode, Executable } hashtable.
function Build-DatIndexFromStream {
    param(
        [System.IO.Stream]$stream,
        # FIX132: when given, the files (name, size, hashes) of every "[EMU]" set are also collected here,
        # game name -> list of files. The set lists are how a prerequisite file is found and checked.
        [hashtable]$EmuRomSink = $null,
        # Rebuild: names of games whose files are collected into EmuRomSink as well (exact name, any case); with StopWhenCaptured
        # the read ends as soon as all of them are collected.
        [string[]]$CaptureGameNames = @(),
        [switch]$StopWhenCaptured
    )
    $index    = @{}
    $settings = New-Object System.Xml.XmlReaderSettings
    $settings.IgnoreWhitespace = $true
    $settings.DtdProcessing    = [System.Xml.DtdProcessing]::Prohibit
    $reader = [System.Xml.XmlReader]::Create($stream, $settings)
    $progressStarted = Get-Date
    $progressCurrent = 0
    $lastProgressCurrent = 0
    $progressCurrentCompleted = $false
    try {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'DAT index parsing' -Current $progressCurrent -Total 0 -StartedAt $progressStarted
        $gameName    = ''
        $profCode    = ''
        $exePath     = ''
        # Newer dat fields (TPUISchemaVersion 1, issue #382); empty when a game does not have them.
        # Decision (issue #382): romzip and romnest (the files inside a MAME-style game's ZIP: archive, size, crc, sha1) are NOT used. The
        # Manager registers games from folders and profiles and never checks ROM contents, so verifying extracted sets would be a new
        # feature that hashes every file of every such game. Both are self-closing elements next to <rom>; they hold no text, so this
        # reader passes over them and stays streaming (the dat is about 520 MB). A dat with no TPUISchemaVersion (older files) is read silently.
        $schemaVersionText = ''
        $schemaChecked = $false
        $profCode2   = ''
        $exePath2    = ''
        $testMenuExe = ''
        $insideGame  = $false
        $captureRoms = $false
        $captureNames = $null
        if ($null -ne $EmuRomSink -and @($CaptureGameNames).Count -gt 0) {
            $captureNames = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
            foreach ($captureName in @($CaptureGameNames)) { [void]$captureNames.Add([string]$captureName) }
        }
        $currentElem = ''
        # Skip() already advances the reader onto the next sibling node (the
        # following <rom>, or the </game> EndElement if that was the last
        # one) -- it does NOT need (or want) a further Read() to get there.
        # The loop used to call Read() unconditionally every iteration, so
        # after every Skip() it silently consumed and discarded whatever
        # node Skip() had just landed on. With dozens to hundreds of <rom>
        # entries per game, that discarded one real node per skip, and once
        # the cumulative drift landed exactly on a game's own </game> node,
        # that game's EndElement (and its ProfileCode/Executable capture)
        # never fired at all. Confirmed empirically against a real
        # collection dat: this silently dropped roughly half of all <game>
        # entries (493 opened, only 236 closed) before this fix, regardless
        # of whether the game had a valid ProfileCode. See issue #12.
        $advance = $true
        while ($true) {
            if ($advance) { if (-not $reader.Read()) { break } }
            $advance = $true
            if ($reader.NodeType -eq [System.Xml.XmlNodeType]::Element) {
                $currentElem = $reader.Name
                if ($currentElem -eq 'game') {
                    # The header comes before the first game, so the format version is known here. An unknown version is only a warning
                    # (the file is still read the way version 1 is read), said once, before the long read of the games.
                    if (-not $schemaChecked) {
                        $schemaChecked = $true
                        if ($schemaVersionText -and $schemaVersionText -cne '1') {
                            Write-Log ('DAT: the file says TPUISchemaVersion {0}; this Manager knows version 1. It is read as version 1 and some games may not match.' -f $schemaVersionText)
                            Write-Host ('  This game list (DAT) uses a format this Manager does not know (version {0}; it knows version 1).' -f $schemaVersionText) -ForegroundColor Yellow
                            Write-Host '  It is still read, but some games may not match. Check for a newer Manager.' -ForegroundColor Yellow
                        }
                    }
                    $gameName    = $reader.GetAttribute('name')
                    $profCode    = ''
                    $exePath     = ''
                    $profCode2   = ''
                    $exePath2    = ''
                    $testMenuExe = ''
                    $insideGame  = $true
                    $captureRoms = $false
                    if ($null -ne $EmuRomSink -and $gameName -and $gameName.StartsWith('[EMU]', [System.StringComparison]::OrdinalIgnoreCase)) {
                        $captureRoms = $true
                        if (-not $EmuRomSink.ContainsKey($gameName)) { $EmuRomSink[$gameName] = New-Object System.Collections.Generic.List[object] }
                    }
                    elseif ($null -ne $captureNames -and $gameName -and $captureNames.Contains($gameName)) {
                        $captureRoms = $true
                        if (-not $EmuRomSink.ContainsKey($gameName)) { $EmuRomSink[$gameName] = New-Object System.Collections.Generic.List[object] }
                    }
                } elseif ($currentElem -eq 'rom' -and $insideGame) {
                    if ($captureRoms) {
                        [void]$EmuRomSink[$gameName].Add([pscustomobject]@{
                            Name   = [string]$reader.GetAttribute('name')
                            Size   = [string]$reader.GetAttribute('size')
                            Crc    = [string]$reader.GetAttribute('crc')
                            Md5    = [string]$reader.GetAttribute('md5')
                            Sha1   = [string]$reader.GetAttribute('sha1')
                            Sha256 = [string]$reader.GetAttribute('sha256')
                        })
                    }
                    $reader.Skip()   # each <game> has hundreds of <rom> hash entries; skip for perf
                    $currentElem = ''
                    $advance     = $false   # already positioned on the next node -- don't double-advance
                }
            } elseif ($reader.NodeType -eq [System.Xml.XmlNodeType]::Text -and $insideGame) {
                if     ($currentElem -eq 'GameProfile')                           { $profCode = $reader.Value }
                elseif ($currentElem -eq 'Executable' -and -not $exePath) { $exePath  = $reader.Value }
                elseif ($currentElem -eq 'GameProfile2')                    { $profCode2   = $reader.Value }
                elseif ($currentElem -eq 'Executable2' -and -not $exePath2) { $exePath2    = $reader.Value }
                elseif ($currentElem -eq 'TestMenuExecutable')              { $testMenuExe = $reader.Value }
            } elseif ($reader.NodeType -eq [System.Xml.XmlNodeType]::Text -and -not $insideGame -and $currentElem -eq 'TPUISchemaVersion') {
                $schemaVersionText = ([string]$reader.Value).Trim()
            } elseif ($reader.NodeType -eq [System.Xml.XmlNodeType]::EndElement -and $reader.Name -eq 'game') {
                $insideGame = $false
                $captureRoms = $false
                if ($profCode -and $gameName) {
                    $normName = Get-NormalizedGameKey $gameName
                    if ($normName -and $index.ContainsKey($normName)) {
                        # Another game whose name reads the same once the year and the bracket tags are removed (other hardware or version).
                        # It is kept next to the first one so a lookup by the exact name can tell them apart; the index size does not change.
                        [void]$index[$normName].Alternates.Add([pscustomobject]@{
                            ProfileCode        = $profCode.Trim()
                            Executable         = $exePath.Trim()
                            OriginalName       = $gameName.Trim()
                            ProfileCode2       = $profCode2.Trim()
                            Executable2        = $exePath2.Trim()
                            TestMenuExecutable = $testMenuExe.Trim()
                        })
                    }
                    if ($normName -and -not $index.ContainsKey($normName)) {
                        $index[$normName] = [pscustomobject]@{
                            Alternates   = (New-Object System.Collections.Generic.List[object])
                            ProfileCode  = $profCode.Trim()
                            Executable   = $exePath.Trim()
                            # Retained (not just the normalized key) so Register-Games'
                            # Pass-2 fuzzy fallback can compare meaningful title words
                            # against the folder's own name -- see issue #84.
                            OriginalName = $gameName.Trim()
                            ProfileCode2       = $profCode2.Trim()
                            Executable2        = $exePath2.Trim()
                            TestMenuExecutable = $testMenuExe.Trim()
                        }
                    }
                }
                # Rebuild: once every wanted game's files are collected there is no need to read the rest of a very large DAT.
                if ($null -ne $captureNames -and $gameName -and $captureNames.Remove($gameName) -and $StopWhenCaptured -and $captureNames.Count -eq 0) { break }
                $progressCurrent++
                if (($progressCurrent - $lastProgressCurrent) -ge 100) {
                    Write-TpmCompactExtractionProgress -Phase Scanning -Label 'DAT index parsing' -Current $progressCurrent -Total 0 -StartedAt $progressStarted
                    $lastProgressCurrent = $progressCurrent
                }
            }
        }
        $progressCurrentCompleted = $true
    } finally {
        try { $reader.Close() } finally {
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'DAT index parsing' -Current $progressCurrent -Total 0 -StartedAt $progressStarted -Complete -Outcome $(if ($progressCurrentCompleted) { 'Final' } else { 'Error' })
        }
    }
    return $index
}

# Reads the collection dat directly from inside the Eggman ZIP without extracting.
# ZipArchive is opened, the matching entry stream is passed to Build-DatIndexFromStream,
# and the archive is disposed in the finally block regardless of outcome.
function Build-DatIndexFromZip {
    param([string]$zipPath, [string]$entryPattern = '*Collection*_RomVault*.dat', [hashtable]$EmuRomSink = $null, [switch]$Quiet, [string[]]$CaptureGameNames = @(), [switch]$StopWhenCaptured)
    $za = $null
    try {
        $za    = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
        $entry = @($za.Entries | Where-Object { $_.FullName -like $entryPattern })[0]
        if (-not $entry) {
            if (-not $Quiet) { Write-Host ("  WARNING: No dat entry matching '{0}' in ZIP." -f $entryPattern) -ForegroundColor Yellow }
            Write-Log ("DatIndex (ZIP): no entry matching '{0}'." -f $entryPattern)
            return @{}
        }
        if (-not $Quiet) { Write-Host ("    Reading: {0}" -f $entry.Name) -ForegroundColor DarkGray }
        $stream = $entry.Open()
        try   { return Build-DatIndexFromStream $stream -EmuRomSink $EmuRomSink -CaptureGameNames $CaptureGameNames -StopWhenCaptured:$StopWhenCaptured }
        finally { if ($stream) { $stream.Close() } }
    } catch {
        if (-not $Quiet) { Write-Host ("  WARNING: Could not read dat from ZIP -- {0}" -f $_) -ForegroundColor Yellow }
        Write-Log "DatIndex (ZIP): parse failed -- $_"
        return @{}
    } finally {
        if ($za) { $za.Dispose() }
    }
}


# Parses a No-Intro style TeknoParrot dat file from disk using streaming XmlReader.
# Replaces the old DOM-based approach which could not handle the 584 MB collection dat.
# Returns normalized-name -> { ProfileCode, Executable } hashtable.
function Build-DatIndex {
    param([string]$datPath, [hashtable]$EmuRomSink = $null, [switch]$Quiet, [string[]]$CaptureGameNames = @(), [switch]$StopWhenCaptured)
    try {
        $fs = [System.IO.File]::OpenRead($datPath)
        try   { return Build-DatIndexFromStream $fs -EmuRomSink $EmuRomSink -CaptureGameNames $CaptureGameNames -StopWhenCaptured:$StopWhenCaptured }
        finally { if ($fs) { $fs.Close() } }
    } catch {
        if (-not $Quiet) { Write-Host ("  WARNING: Could not parse dat file -- {0}" -f $_) -ForegroundColor Yellow }
        Write-Log "DatIndex: parse failed -- $_"
        return @{}
    }
}

# Reads the plain-text game-notes file bundled in the Eggman ZIP.
# Format: sections delimited by lines of 60+ '=' chars.
# First non-blank line of each section: "Game Name (ProfileCode)"
# Remaining lines: the note body.
# Returns ProfileCode.ToLowerInvariant() -> trimmed note text hashtable.
function Build-GameNotesIndexFromStream {
    param([System.IO.Stream]$stream)
    $index   = @{}
    $reader  = New-Object System.IO.StreamReader($stream, [System.Text.Encoding]::UTF8)
    $progressStarted = Get-Date
    $progressCurrent = 0
    $lastProgressCurrent = 0
    $progressCurrentCompleted = $false
    try {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Game notes parsing' -Current $progressCurrent -Total 0 -StartedAt $progressStarted
        $code       = ''
        $noteLines  = New-Object System.Collections.Generic.List[string]
        $inSection  = $false
        $headerRead = $false

        while (-not $reader.EndOfStream) {
            $ln = $reader.ReadLine()
            $progressCurrent++
            if (($progressCurrent - $lastProgressCurrent) -ge 100) {
                Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Game notes parsing' -Current $progressCurrent -Total 0 -StartedAt $progressStarted
                $lastProgressCurrent = $progressCurrent
            }
            if ($ln -match '^={60,}') {
                if ($code -and $noteLines.Count -gt 0) {
                    $body = (($noteLines | Where-Object { $_.Trim() }) -join "`n").Trim()
                    if ($body) { $index[$code] = $body }
                }
                $code = ''; $noteLines.Clear(); $inSection = $true; $headerRead = $false
                continue
            }
            if (-not $inSection) { continue }
            if (-not $headerRead) {
                if ([string]::IsNullOrWhiteSpace($ln)) { continue }
                $m = [regex]::Match($ln, '\(([A-Za-z][A-Za-z0-9_]*)\)\s*$')
                if ($m.Success) { $code = $m.Groups[1].Value.ToLowerInvariant() }
                $headerRead = $true
            } else {
                $noteLines.Add($ln)
            }
        }
        if ($code -and $noteLines.Count -gt 0) {
            $body = (($noteLines | Where-Object { $_.Trim() }) -join "`n").Trim()
            if ($body) { $index[$code] = $body }
        }
        $progressCurrentCompleted = $true
    } finally {
        try { $reader.Close() } finally {
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Game notes parsing' -Current $progressCurrent -Total 0 -StartedAt $progressStarted -Complete -Outcome $(if ($progressCurrentCompleted) { 'Final' } else { 'Error' })
        }
    }
    return $index
}

function Build-GameNotesIndex {
    param([string]$path)
    try {
        $fs = [System.IO.File]::OpenRead($path)
        try   { return Build-GameNotesIndexFromStream $fs }
        finally { if ($fs) { $fs.Close() } }
    } catch { Write-Log "NotesIndex: parse failed -- $_"; return @{} }
}

function Build-GameNotesIndexFromZip {
    param([string]$zipPath)
    $za = $null
    try {
        $za    = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
        $entry = @($za.Entries | Where-Object { $_.Name -like '*.txt' -and $_.Name -ilike '*note*' })[0]
        if (-not $entry) { return @{} }
        Write-Host ("    Reading: {0}" -f $entry.Name) -ForegroundColor DarkGray
        $stream = $entry.Open()
        try   { return Build-GameNotesIndexFromStream $stream }
        finally { if ($stream) { $stream.Close() } }
    } catch { Write-Log "NotesIndex (ZIP): parse failed -- $_"; return @{} }
    finally  { if ($za) { $za.Dispose() } }
}

# Queries the teknogods/TeknoParrotUI GitHub repo tree for all GameProfile XML
# filenames (live identities). Falls back to the local GameProfiles folder,
# which is always the template source, when the live list is unavailable.
# As of 2026-10-31 that repository answers HTTP 404 for both the web page and
# the API (the source is no longer public; teknogods/TeknoParrot holds only a
# README), so the fallback is the normal path until it returns. A repository
# 404 skips the tree request. Records how the set was built in
# $script:TpmProfileSetSource (Source = Live / LocalTemplates / None) so the
# caller reports a successful fallback as success, not as a failure.
# Returns a HashSet[string] of profile code stems (e.g. "BladeArcus").
function Get-TeknoParrotProfileSet {
    param([string]$localGameProfilesDir = '')
    $result = New-Object 'System.Collections.Generic.HashSet[string]'([StringComparer]::OrdinalIgnoreCase)
    $profileScanStarted = Get-Date
    Write-TpmCompactExtractionProgress -Phase Checking -Label 'TeknoParrot profile list' -Current 0 -Total 0 -StartedAt $profileScanStarted
    $loaded = $false
    $repoMissing = $false
    $treeTruncated = $false
    $liveReason = $null
    $queryAttempts = 0
    # Resolve the repo's actual default branch instead of hardcoding "master" --
    # if teknogods/TeknoParrotUI ever renames its default branch, this still
    # finds it. Falls back to "master" (today's known default) on a transient
    # failure so it doesn't block profile discovery entirely.
    $branch = 'master'
    try {
        $repoResp = Invoke-TpmWebRequestSilently -Uri 'https://api.github.com/repos/teknogods/TeknoParrotUI' `
                        -UseBasicParsing -TimeoutSec 10 -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
        $defaultBranch = ($repoResp.Content | ConvertFrom-Json).default_branch
        if (-not [string]::IsNullOrWhiteSpace($defaultBranch)) { $branch = $defaultBranch }
    } catch {
        $repoStatus = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
        if ($repoStatus -eq 404) {
            $repoMissing = $true
            $liveReason = 'The teknogods/TeknoParrotUI repository is not publicly available (HTTP 404).'
            Write-Log "ProfileSet (GitHub): teknogods/TeknoParrotUI returned HTTP 404 (repository not publicly available) -- skipping the live profile list."
        } else {
            Write-Log "ProfileSet (GitHub): could not resolve default branch, falling back to 'master' -- $_"
        }
    }
    $branchEncoded = [System.Uri]::EscapeDataString($branch)
    $apiUri = "https://api.github.com/repos/teknogods/TeknoParrotUI/git/trees/${branchEncoded}?recursive=1"
    for ($attempt = 1; $attempt -le 3 -and -not $repoMissing; $attempt++) {
        $queryAttempts = $attempt
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'GitHub profile query' -Current $attempt -Total 3 -StartedAt $profileScanStarted
        try {
            $resp = Invoke-TpmWebRequestSilently -Uri $apiUri -UseBasicParsing -TimeoutSec 20 `
                        -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $parsedTree = $resp.Content | ConvertFrom-Json
            $tree   = $parsedTree.tree
            if ($parsedTree.PSObject.Properties['truncated'] -and [bool]$parsedTree.truncated) { $treeTruncated = $true }
            $prefix = 'TeknoParrotUi.Common/GameProfiles/'
            $tree = @($tree)
            $treeCurrent = 0
            foreach ($node in $tree) {
                $treeCurrent++
                Write-TpmCompactExtractionProgress -Phase Scanning -Label 'GitHub profile tree' -Current $treeCurrent -Total $tree.Count -StartedAt $profileScanStarted
                if ($node.type -eq 'blob' -and $node.path -like ($prefix + '*.xml')) {
                    $stem = [System.IO.Path]::GetFileNameWithoutExtension($node.path.Substring($prefix.Length))
                    if ($stem -match '^[\w-]+$') { [void]$result.Add($stem) }
                }
            }
            if ($result.Count -gt 0) {
                Write-Log "ProfileSet (GitHub): $($result.Count) profiles from teknogods/TeknoParrotUI."
                if ($treeTruncated) { Write-Log "ProfileSet (GitHub): the repository tree was truncated; local GameProfiles names are merged in." }
                $loaded = $true
            } else {
                $liveReason = 'The live repository listed no GameProfiles.'
                Write-Log "ProfileSet (GitHub): 0 profiles returned -- API may have changed."
            }
            break
        } catch {
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                $liveReason = "The live profile list request failed (HTTP $status)."
                Write-Log "ProfileSet (GitHub): query failed -- HTTP $status -- $_"; break
            }
            Write-Log "ProfileSet (GitHub): attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    if (-not $loaded -and $queryAttempts -gt 0) {
        # The live query has finished without a list. Close its row explicitly
        # so the local fallback below does not show it as incomplete or failed.
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'GitHub profile list unavailable; using local GameProfiles' -Current $queryAttempts -Total $queryAttempts -StartedAt $profileScanStarted -Complete
    }
    $liveCount = $result.Count
    if ((-not $loaded -or $treeTruncated) -and $localGameProfilesDir -and (Test-Path -LiteralPath $localGameProfilesDir)) {
        $localProfiles = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $localGameProfilesDir -ProgressLabel 'TeknoParrot profile list discovery' -Filter '*.xml' -EnumerationErrorAction SilentlyContinue)
        $localCurrent = 0
        foreach ($localProfileFile in $localProfiles) {
            $localCurrent++
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'TeknoParrot profile list' -Current $localCurrent -Total $localProfiles.Count -StartedAt $profileScanStarted
            $s = [System.IO.Path]::GetFileNameWithoutExtension($localProfileFile.Name)
            if ($s -match '^[\w-]+$') { [void]$result.Add($s) }
        }
        Write-Log "ProfileSet (local fallback): $($result.Count - $liveCount) profiles from $localGameProfilesDir"
    }
    $script:TpmProfileSetSource = [pscustomobject]@{
        Source = if ($loaded) { 'Live' } elseif ($result.Count -gt 0) { 'LocalTemplates' } else { 'None' }
        LiveCount = [int]$liveCount
        Count = [int]$result.Count
        LiveReason = $liveReason
    }
    Write-TpmCompactExtractionProgress -Phase Checking -Label 'TeknoParrot profile list' -Current 0 -Total 0 -StartedAt $profileScanStarted -Complete
    return $result
}

# Resolves a dat ProfileCode to the correct template filename stem.
# Priority: (1) exact local template; (2) code in GitHub profileSet; (3) fuzzy
# match against profileSet above $FuzzyAutoThreshold; (4) return original.
function Resolve-ProfileCode {
    param([string]$code, [string]$gameProfilesDir,
          [System.Collections.Generic.HashSet[string]]$profileSet = $null)
    if (-not $code) { return $code }
    if ($gameProfilesDir -and (Test-Path -LiteralPath (Join-Path $gameProfilesDir ($code + ".xml")))) {
        return $code
    }
    if ($null -eq $profileSet -or $profileSet.Count -eq 0) { return $code }
    if ($profileSet.Contains($code)) { return $code }
    $normCode  = Get-NormalizedGameKey $code
    $bestScore = 0.0
    $bestMatch = $null
    foreach ($candidate in $profileSet) {
        $score = Get-DiceSimilarity $normCode (Get-NormalizedGameKey $candidate)
        if ($score -gt $bestScore) { $bestScore = $score; $bestMatch = $candidate }
    }
    if ($bestScore -ge $FuzzyAutoThreshold -and $null -ne $bestMatch -and $bestMatch -match '^[\w-]+$') {
        Write-Log ("Resolve-ProfileCode: '{0}' -> '{1}' (score {2})" -f $code, $bestMatch, [Math]::Round($bestScore,2))
        return $bestMatch
    }
    # Below threshold -- return the original code unchanged (not $null).
    # Register-Games depends on receiving a usable string even when resolution fails.
    return $code
}

# Queries the GitHub API for the latest Eggman dat release asset.
# Eggmansworld/Datfiles posted its final release ("LAST UPDATE FROM THIS
# REPO!!") and moved the TeknoParrot dats to Eggmansworld/TeknoParrot.
# The new repo also switched from a fixed "teknoparrot" release tag to a
# date-based tag per release (e.g. "2026-06-17"), so a fixed-tag lookup
# can no longer work -- query "latest" instead. Asset naming is unchanged
# (still matches 'TeknoParrot*Collection*RomVault*.zip').
# Returns [pscustomobject]@{DownloadUrl; FileName; SizeMB} or $null on failure.
function Test-EggmanDatReleaseUrl {
    param([string]$Url)
    $parsedUri = $null
    if (-not [System.Uri]::TryCreate($Url, [System.UriKind]::Absolute, [ref]$parsedUri)) { return $false }
    if ($parsedUri.Scheme -ne 'https') { return $false }

    if ($parsedUri.Host -ine 'github.com') { return $false }
    return $parsedUri.AbsolutePath.StartsWith('/Eggmansworld/TeknoParrot/releases/download/', [System.StringComparison]::Ordinal)
}

# Returns [pscustomobject]@{DownloadUrl; FileName; SizeMB; SizeBytes}; $null when GitHub could not be reached; an object with an empty DownloadUrl when GitHub answered but offered no usable DAT file.
function Get-EggmanDatRelease {
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            $apiUri = 'https://api.github.com/repos/Eggmansworld/TeknoParrot/releases/latest'
            $resp   = Invoke-TpmWebRequestSilently -Uri $apiUri -UseBasicParsing -TimeoutSec 20 `
                          -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $rel    = $resp.Content | ConvertFrom-Json
            $asset  = @($rel.assets) | Where-Object { $_.name -like 'TeknoParrot*Collection*RomVault*.zip' } |
                          Select-Object -First 1
            if (-not $asset) { Write-Log 'EggmanDat: the release has no matching DAT ZIP.'; return [pscustomobject]@{ DownloadUrl = '' } }
            if (-not (Test-EggmanDatReleaseUrl -Url $asset.browser_download_url)) {
                Write-Log "EggmanDat: unexpected download URL format -- skipping."
                return [pscustomobject]@{ DownloadUrl = '' }
            }
            return [pscustomobject]@{
                DownloadUrl = $asset.browser_download_url
                FileName    = $asset.name
                SizeMB      = [Math]::Round($asset.size / 1MB, 1)
                SizeBytes   = [int64]$asset.size
            }
        } catch {
            $status = 0
            # Get-TpmHttpStatusCodeFromError guards the same optional
            # .Exception.Response/.StatusCode access this used to do inline
            # (unsafe under strict mode for exception types that lack either
            # property entirely -- RuntimeException from a plain "throw",
            # HttpRequestException, etc.) and additionally falls back to
            # extracting a status code embedded only in the message text.
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "EggmanDat: GitHub release query failed -- $_"; return $null
            }
            Write-Log "EggmanDat: attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    return $null
}

function Invoke-TpmDownloadHttpClient {
    param([string]$DownloadUrl, [string]$TempPath, [string]$Label = 'download')
    if (-not ('System.Net.Http.HttpClient' -as [type])) {
        Add-Type -AssemblyName System.Net.Http
    }
    $client = $null
    $response = $null
    $inputStream = $null
    $outputStream = $null
    try {
        $client = New-Object System.Net.Http.HttpClient
        $client.Timeout = [TimeSpan]::FromMinutes(30)
        # The server may take a long time to answer before the first byte: "still working", never "stalled".
        $longWait = $false
        if (Test-Path -LiteralPath 'Function:\Enter-TpmLongWait') { $longWait = Enter-TpmLongWait }
        try { $response = $client.GetAsync($DownloadUrl, [System.Net.Http.HttpCompletionOption]::ResponseHeadersRead).GetAwaiter().GetResult() }
        finally { if ($longWait) { Exit-TpmLongWait } }
        [void]$response.EnsureSuccessStatusCode()
        # PowerShell unwraps Nullable<Int64> to Int64 or null; HasValue/Value are not exposed.
        $contentLength = $response.Content.Headers.ContentLength
        $totalBytes = if ($null -ne $contentLength -and $contentLength -gt 0) { [int64]$contentLength } else { [int64]0 }
        $inputStream = $response.Content.ReadAsStreamAsync().GetAwaiter().GetResult()
        $outputStream = [System.IO.File]::Create($TempPath)
        $buffer = New-Object byte[] 1048576
        $downloadedBytes = [int64]0
        $progressWatch = [System.Diagnostics.Stopwatch]::StartNew()
        # With ResponseHeadersRead the client timeout does not cover body
        # reads, so every read gets the same 120-second no-progress window as
        # the BITS tier. On timeout the finally block disposes the stream and
        # response, and the throw hands over to the next download tier.
        $noProgressSeconds = 120
        $noProgressTimeout = [TimeSpan]::FromSeconds($noProgressSeconds)
        while ($true) {
            $readCts = New-Object System.Threading.CancellationTokenSource
            try {
                $readCts.CancelAfter($noProgressTimeout)
                $readTask = $inputStream.ReadAsync($buffer, 0, $buffer.Length, $readCts.Token)
                if ([System.Threading.Tasks.Task]::WaitAny([System.Threading.Tasks.Task[]]@($readTask), $noProgressTimeout) -lt 0) {
                    $readCts.Cancel()
                    throw "HttpClient download made no progress for $noProgressSeconds seconds."
                }
                try {
                    $read = $readTask.GetAwaiter().GetResult()
                } catch [System.OperationCanceledException] {
                    throw "HttpClient download made no progress for $noProgressSeconds seconds."
                }
            } finally {
                $readCts.Dispose()
            }
            if ($read -le 0) { break }
            $outputStream.Write($buffer, 0, $read)
            $downloadedBytes += $read
            Write-TpmDownloadProgress -Label $Label -Method 'HttpClient' -DownloadedBytes $downloadedBytes -TotalBytes $totalBytes -Elapsed $progressWatch.Elapsed
        }
        Write-TpmDownloadProgress -Label $Label -Method 'HttpClient' -DownloadedBytes $downloadedBytes -TotalBytes $totalBytes -Elapsed $progressWatch.Elapsed -Complete
    } finally {
        if ($outputStream) { $outputStream.Dispose() }
        if ($inputStream) { $inputStream.Dispose() }
        if ($response) { $response.Dispose() }
        if ($client) { $client.Dispose() }
    }
}

function Invoke-TpmDownloadWebRequest {
    param([string]$DownloadUrl, [string]$TempPath, [string]$Label = 'download')
    $progressWatch = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        Write-TpmDownloadProgress -Label $Label -Method 'Invoke-WebRequest' -DownloadedBytes 0 -TotalBytes 0 -Elapsed $progressWatch.Elapsed
        Invoke-TpmWebRequestSilently -Uri $DownloadUrl -OutFile $TempPath -UseBasicParsing -RequestErrorAction Stop
        $bytes = (Get-Item -LiteralPath $TempPath -ErrorAction Stop).Length
        Write-TpmDownloadProgress -Label $Label -Method 'Invoke-WebRequest' -DownloadedBytes $bytes -TotalBytes $bytes -Elapsed $progressWatch.Elapsed -Complete
    } finally {
        $progressWatch.Stop()
    }
}

function Test-TpmDownloadBitsAvailable {
    $bitsCommand = Get-Command Start-BitsTransfer -ErrorAction SilentlyContinue
    if (-not $bitsCommand) { return $false }
    $bitsSvc = try { Get-Service -Name BITS -ErrorAction Stop } catch { $null }
    return ($bitsSvc -ne $null -and $bitsSvc.Status -eq 'Running')
}

function Invoke-TpmDownloadBits {
    param([string]$DownloadUrl, [string]$TempPath, [string]$Label = 'download')
    $job = $null
    $progressWatch = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        $job = Start-BitsTransfer -Source $DownloadUrl -Destination $TempPath `
            -Description "TeknoParrot Manager $Label" `
            -DisplayName "Downloading $Label..." `
            -Asynchronous `
            -ErrorAction Stop
        $lastProgressBytes = [int64]-1
        $lastProgressAt = [DateTime]::UtcNow
        while ($job.JobState -in @('Connecting', 'Transferring', 'Queued', 'TransientError')) {
            # Without a bound, an offline host can sit in TransientError forever and the HttpClient/web fallbacks are never reached.
            $currentBytes = [int64]$job.BytesTransferred
            if ($currentBytes -ne $lastProgressBytes) { $lastProgressBytes = $currentBytes; $lastProgressAt = [DateTime]::UtcNow }
            elseif (([DateTime]::UtcNow - $lastProgressAt).TotalSeconds -ge 120) { throw 'BITS transfer made no progress for 120 seconds.' }
            # BITS reports an unknown total as UInt64.MaxValue, which [int64] cannot hold: treat anything above Int64.MaxValue as unknown (0).
            $rawBitsTotal = $job.BytesTotal
            $bitsTotalBytes = if ($rawBitsTotal -is [uint64]) { if ($rawBitsTotal -gt [uint64][int64]::MaxValue) { [int64]0 } else { [int64]$rawBitsTotal } } elseif ([int64]$rawBitsTotal -lt 0) { [int64]0 } else { [int64]$rawBitsTotal }
            Write-TpmDownloadProgress -Label $Label -Method 'BITS' -DownloadedBytes ([int64]$job.BytesTransferred) -TotalBytes $bitsTotalBytes -Elapsed $progressWatch.Elapsed
            Start-Sleep -Milliseconds 500
            $job = Get-BitsTransfer -JobId $job.JobId -ErrorAction Stop
        }
        if ($job.JobState -ne 'Transferred') {
            throw "BITS transfer ended with state $($job.JobState)."
        }
        Complete-BitsTransfer -BitsJob $job -ErrorAction Stop
        $bytes = (Get-Item -LiteralPath $TempPath -ErrorAction Stop).Length
        Write-TpmDownloadProgress -Label $Label -Method 'BITS' -DownloadedBytes $bytes -TotalBytes $bytes -Elapsed $progressWatch.Elapsed -Complete
    } catch {
        if ($job) {
            try { Remove-BitsTransfer -BitsJob $job -Confirm:$false -ErrorAction SilentlyContinue } catch {}
        }
        throw
    }
}

# Parses a GitHub Releases API asset "digest" field (e.g.
# "sha256:82f987...") into a bare uppercase hex hash, or $null if the field
# is absent/empty or not in the sha256: form this script verifies against.
# Shared by every release-asset fetch that wants to opt into SHA-256
# verification (currently BepInEx and dgVoodoo2) -- a generic GitHub
# Releases API feature, not specific to either project.
function Get-TpmSha256FromDigestField {
    param([string]$Digest)
    if ([string]::IsNullOrWhiteSpace($Digest)) { return $null }
    if ($Digest -match '^sha256:([0-9a-fA-F]{64})$') { return $Matches[1].ToUpperInvariant() }
    return $null
}

function Test-TpmDownloadedFile {
    param([string]$Path, [Int64]$ExpectedBytes = 0, [string]$ExpectedSha256 = '')
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $false }
    $item = Get-Item -LiteralPath $Path -ErrorAction Stop
    if ($item.Length -le 0) { return $false }
    if ($ExpectedBytes -gt 0 -and $item.Length -ne $ExpectedBytes) { return $false }
    if ($ExpectedSha256) {
        # Fail closed: any hashing error (unreadable file, etc.) is treated
        # the same as a mismatch, never as "skip the check."
        $actualHash = $null
        try { $actualHash = (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash } catch {}
        if (-not $actualHash -or $actualHash -ine $ExpectedSha256) {
            Write-Log "Test-TpmDownloadedFile: SECURITY -- SHA-256 mismatch for '$Path' (expected $ExpectedSha256, got $actualHash)."
            return $false
        }
    }
    return $true
}

function Write-TpmDownloadProgress {
    param(
        [string]$Label = 'download',
        [string]$Method,
        [Int64]$DownloadedBytes,
        [Int64]$TotalBytes = 0,
        [TimeSpan]$Elapsed,
        [switch]$Complete
    )
    # The footer says what is being downloaded in plain words; the shared label table (which also names the bar step) is used when loaded.
    $footerName = ('Downloading {0}' -f $Label)
    if (Test-Path -LiteralPath 'Function:\Get-TpmFriendlyProgressLabel') { $footerName = Get-TpmFriendlyProgressLabel -Label $footerName }
    $activeStatus = $script:ActiveTpmWorkflowStatus
    # Render-TpmWorkflowStatus draws nothing while a group owns the progress bar, so a footer-only update would show no download
    # progress at all in grouped workflows: in that case the compact renderer (the group's stage line) carries the update.
    Import-TpmProgressModule
    if ($activeStatus -and -not (Test-TpmProgressGroupOwned)) {
        $downloadStatusNow = (Get-Date).ToUniversalTime()
        if ($Complete) {
            [void](Update-TpmWorkflowActivity -Context $activeStatus -Activity ("{0}: finished" -f $footerName))
            return
        }
        if ($null -eq $activeStatus.LastDownloadStatusUtc -or ($downloadStatusNow - $activeStatus.LastDownloadStatusUtc).TotalMilliseconds -ge 500) {
            $activeStatus.LastDownloadStatusUtc = $downloadStatusNow
            # The status footer has no bar, but it must say the same thing the bar would: same percent, size, elapsed and ETA rules.
            Import-TpmProgressModule
            $footerEta = Get-TpmProgressEta -Current $DownloadedBytes -Total $TotalBytes -StartCurrent 0 -ElapsedSeconds $Elapsed.TotalSeconds -Samples ([int][Math]::Floor($Elapsed.TotalSeconds * 2))
            $footerSummary = Format-TpmProgressSummary -Current $DownloadedBytes -Total $TotalBytes -Unit Bytes -ElapsedSeconds $Elapsed.TotalSeconds -EtaSeconds $footerEta
            [void](Update-TpmWorkflowActivity -Context $activeStatus -Activity ("{0}: {1}" -f $footerName, $footerSummary))
        }
        return
    }

    $displayMethod = if ($Method -eq 'Invoke-WebRequest') { 'web fallback' } else { $Method }
    if ($Complete) {
        # The transfer finished but the file is not trusted yet: size, hash, content validation and promotion follow.
        # The bar stays open (a running bar is capped below 100%); Invoke-TpmDownload closes it only after verification succeeds.
        Write-TpmCompactExtractionProgress -Phase Checking -Label ("Verifying {0}" -f $Label) -Current $DownloadedBytes -Total $TotalBytes -StartedAt ((Get-Date).Subtract($Elapsed)) -Completed -Unit Bytes
        return
    }

    # -Completed: DownloadedBytes already is a finished-byte count. Total 0 (unknown) shows the size so far with a spinner and no percent.
    Write-TpmCompactExtractionProgress -Phase Checking -Label ("{0} via {1}" -f $Label, $displayMethod) -Current $DownloadedBytes -Total $TotalBytes -StartedAt ((Get-Date).Subtract($Elapsed)) -Completed -Unit Bytes
}

function Write-TpmDownloadMetrics {
    param([string]$Label, [string]$Method, [string]$Path, [TimeSpan]$Elapsed, [switch]$Quiet)
    $bytes = (Get-Item -LiteralPath $Path -ErrorAction Stop).Length
    $mb = [Math]::Round($bytes / 1MB, 2)
    $seconds = [Math]::Max($Elapsed.TotalSeconds, 0.001)
    $mbps = [Math]::Round(($bytes / 1MB) / $seconds, 2)
    $message = "${Label}: download method=$Method size=${mb}MB elapsed=$([Math]::Round($Elapsed.TotalSeconds, 1))s speed=${mbps}MB/s"
    Write-Log $message
    if (-not $Quiet) {
        $displayMethod = if ($Method -eq 'Invoke-WebRequest') { 'web fallback' } else { $Method }
        Write-Host ("  Downloaded with {0}: {1} MB in {2:n1}s ({3} MB/s)" -f $displayMethod, $mb, $Elapsed.TotalSeconds, $mbps) -ForegroundColor DarkGray
    }
}

# Extracts an HTTP status code from a failed download attempt's error
# record, if one is present -- a real WebException's .Response.StatusCode
# when available, otherwise a best-effort parse of the exception message
# (HttpClient's EnsureSuccessStatusCode() reports it as text, e.g.
# "... does not indicate success: 404 (Not Found)."). Returns 0 (unknown)
# rather than guessing when neither is present. Used to (a) short-circuit
# the retry loop below on a definitive 4xx rather than retrying something
# that will never succeed, and (b) let a caller like Invoke-ThumbnailDownload
# distinguish "404, not in this repo" from a real transient failure.
function Get-TpmHttpStatusCodeFromError {
    param($ErrorRecord)
    # Not every exception type this can see (RuntimeException from a plain
    # "throw '...'" in a mock, HttpRequestException from HttpClient, etc.)
    # declares a Response property at all -- unlike WebException, where it's
    # merely $null on a non-HTTP failure. Under strict mode, dot-accessing a
    # property that doesn't exist throws PropertyNotFoundException, which
    # previously crashed this function (and its caller) before it ever got a
    # chance to fall through to the message-based extraction below. Checking
    # for the property's existence via PSObject first -- rather than just its
    # truthiness -- preserves the original error path for every exception
    # type that genuinely lacks the property, instead of throwing a new,
    # unrelated one.
    $responseProperty = $ErrorRecord.Exception.PSObject.Properties['Response']
    if ($responseProperty -and $responseProperty.Value) {
        # Same existence-before-truthiness reasoning one level deeper: a
        # Response object can itself be a type (or a test double) that has
        # no StatusCode property at all, not merely a null/zero one. Dot-
        # accessing .StatusCode directly in the condition above would throw
        # under strict mode for that shape instead of falling through.
        $statusCodeProperty = $responseProperty.Value.PSObject.Properties['StatusCode']
        if ($statusCodeProperty -and $null -ne $statusCodeProperty.Value) {
            # [int] cast covers both a plain numeric StatusCode and an
            # enum-like one (e.g. [System.Net.HttpStatusCode]::NotFound) --
            # enums cast cleanly to their underlying integer value. The
            # try/catch only guards a genuinely uncastable value; it still
            # falls through to the message-based extraction below rather
            # than silently reporting a wrong code.
            try { return [int]$statusCodeProperty.Value } catch {}
        }
    }
    if ($ErrorRecord.Exception.Message -match '\((\d{3})\)') { return [int]$Matches[1] }
    if ($ErrorRecord.Exception.Message -match ':\s*(\d{3})\s') { return [int]$Matches[1] }
    return 0
}

# Downloads a live asset to a sibling partial file first, then moves it
# into place only after completion validation. Preferred order is BITS,
# HttpClient, then Invoke-WebRequest as an emergency fallback. The
# HttpClient and Invoke-WebRequest tiers each retry up to 3 times with a
# short backoff on a transient failure; a definitive 4xx response is never
# retried (retrying it cannot succeed) and falls straight through to the
# next tier / final failure. Pass -LastStatusCode ([ref]$var) to read the
# final HTTP status code (0 if unknown/not HTTP-related) after a failure.
function Invoke-TpmDownload {
    param([string]$DownloadUrl, [string]$DestinationPath, [Int64]$ExpectedBytes = 0, [string]$Label = 'Download', [string]$Version = '', [switch]$Quiet, [ref]$LastStatusCode, [string]$ExpectedSha256 = '', [scriptblock]$ValidationScript, [string]$AllowedRoot = '', [switch]$NoOverwrite)
    if ($LastStatusCode) { $LastStatusCode.Value = 0 }
    $saveDir = Split-Path -Parent $DestinationPath
    if ([string]::IsNullOrWhiteSpace($saveDir)) { $saveDir = (Get-Location).Path }
    if (-not (Test-Path -LiteralPath $saveDir -PathType Container) -and -not $AllowedRoot) {
        New-Item -ItemType Directory -Path $saveDir -Force | Out-Null
    }
    # The temp/partial download lands on local disk, not next to the final
    # destination -- $DestinationPath can be (and for several download
    # targets in this script routinely is) a network-mapped drive. A large
    # download sustained directly over that share, immediately followed by
    # a same-share Move-Item, is exactly the kind of transient network
    # flakiness this project has already hit and documented elsewhere (see
    # ARCHITECTURE.md, "Startup: network-path detection and hard timeout").
    # Move-Item works transparently across volumes (copy+delete under the
    # hood when a simple rename isn't possible), so downloading locally
    # first and moving into place at the end changes nothing about the
    # final result -- it only shrinks the window where a flaky network
    # path can make the in-progress file disappear out from under us.
    # Falls back to the destination directory for existing callers. A
    # thumbnail destination must never be used for download staging.
    $tempDir = $env:TEMP
    if ([string]::IsNullOrWhiteSpace($tempDir) -or -not (Test-Path -LiteralPath $tempDir -PathType Container)) {
        $tempDir = if ($AllowedRoot) { [System.IO.Path]::GetTempPath() } else { $saveDir }
    }
    $tempName = '.{0}.{1}.partial' -f ([System.IO.Path]::GetFileName($DestinationPath)), ([guid]::NewGuid().ToString('N'))
    $tempPath = Join-Path $tempDir $tempName
    $stopwatch = [System.Diagnostics.Stopwatch]::StartNew()
    $methodUsed = $null
    $detectedStatusCode = 0
    $definitiveStatusCode = 0
    $readyPath = $null
    $downloadCompleted = $false
    try {
        if ($AllowedRoot) {
            if (-not (Test-Path -LiteralPath $tempDir -PathType Container -ErrorAction Stop)) { throw 'A safe temporary download folder is unavailable.' }
            if (-not (Test-Path -LiteralPath $saveDir -PathType Container -ErrorAction Stop)) { throw 'The approved download destination folder is unavailable.' }
            [void](Assert-TpmThumbnailWriteTarget -Path $DestinationPath -RuntimeRoot $AllowedRoot -Operation 'download destination')
        }
        $bitsSucceeded = $false
        if (Test-TpmDownloadBitsAvailable) {
            try {
                Invoke-TpmDownloadBits -DownloadUrl $DownloadUrl -TempPath $tempPath -Label $Label
                $bitsSucceeded = $true
                $methodUsed = 'BITS'
            } catch {
                Write-Log "${Label}: BITS transfer failed (${_}), trying HttpClient."
                try { if (Test-Path -LiteralPath $tempPath) { [System.IO.File]::Delete($tempPath) } } catch {}
            }
        }
        if (-not $bitsSucceeded) {
            $httpClientSucceeded = $false
            for ($attempt = 1; $attempt -le 3; $attempt++) {
                try {
                    Invoke-TpmDownloadHttpClient -DownloadUrl $DownloadUrl -TempPath $tempPath -Label $Label
                    $methodUsed = 'HttpClient'
                    $httpClientSucceeded = $true
                    break
                } catch {
                    $detectedStatusCode = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
                    if ($detectedStatusCode -eq 404) { $definitiveStatusCode = 404 }
                    try { if (Test-Path -LiteralPath $tempPath) { [System.IO.File]::Delete($tempPath) } } catch {}
                    if ($attempt -ge 3 -or ($detectedStatusCode -ge 400 -and $detectedStatusCode -lt 500)) {
                        Write-Log "${Label}: HttpClient download failed (${_}), trying Invoke-WebRequest."
                        break
                    }
                    Write-Log "${Label}: HttpClient attempt $attempt failed -- retrying"
                    Start-Sleep -Seconds 2
                }
            }
            if (-not $httpClientSucceeded) {
                for ($attempt = 1; $attempt -le 3; $attempt++) {
                    try {
                        Invoke-TpmDownloadWebRequest -DownloadUrl $DownloadUrl -TempPath $tempPath -Label $Label
                        $methodUsed = 'Invoke-WebRequest'
                        break
                    } catch {
                        $detectedStatusCode = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
                        if ($detectedStatusCode -eq 404) { $definitiveStatusCode = 404 }
                        try { if (Test-Path -LiteralPath $tempPath) { [System.IO.File]::Delete($tempPath) } } catch {}
                        if ($attempt -ge 3 -or ($detectedStatusCode -ge 400 -and $detectedStatusCode -lt 500)) { throw }
                        Write-Log "${Label}: download attempt $attempt failed -- retrying"
                        Start-Sleep -Seconds 2
                    }
                }
            }
        }
        if (-not (Test-TpmDownloadedFile -Path $tempPath -ExpectedBytes $ExpectedBytes -ExpectedSha256 $ExpectedSha256)) {
            # Fail closed: delete the partial file (handled in the catch
            # block below via $tempPath) and surface a clear error -- this
            # covers both "incomplete/empty" and "SHA-256 verification
            # failed" (Test-TpmDownloadedFile already logged the specific
            # SECURITY reason for the latter).
            throw "Downloaded file is incomplete, empty, or failed integrity verification."
        }
        if ($ValidationScript -and -not (& $ValidationScript $tempPath)) {
            throw "Downloaded file failed the caller's content validation."
        }
        $readyPath = Join-Path $saveDir ('.{0}.{1}.ready' -f [System.IO.Path]::GetFileName($DestinationPath), [guid]::NewGuid().ToString('N'))
        if ($AllowedRoot) {
            [void](Assert-TpmThumbnailWriteTarget -Path $readyPath -RuntimeRoot $AllowedRoot -Operation 'download staging promotion')
        } else {
            Assert-TpmNoReparseWriteTarget -Path $DestinationPath -Operation 'download final promotion'
        }
        Move-Item -LiteralPath $tempPath -Destination $readyPath -Force -ErrorAction Stop
        if (-not (Test-TpmDownloadedFile -Path $readyPath -ExpectedBytes $ExpectedBytes -ExpectedSha256 $ExpectedSha256)) { throw 'The staged download failed final integrity verification.' }
        if ($NoOverwrite) {
            if (Test-Path -LiteralPath $DestinationPath -ErrorAction Stop) { throw 'The destination already exists and will not be overwritten.' }
            if ($AllowedRoot) {
                [void](Assert-TpmThumbnailWriteTarget -Path $DestinationPath -RuntimeRoot $AllowedRoot -Operation 'download final promotion')
            } else {
                Assert-TpmNoReparseWriteTarget -Path $DestinationPath -Operation 'download final promotion'
            }
            [System.IO.File]::Move($readyPath, $DestinationPath)
        } elseif (Test-Path -LiteralPath $DestinationPath) {
            if (-not (Test-Path -LiteralPath $DestinationPath -PathType Leaf)) { throw 'The download destination is occupied by a non-file item.' }
            try {
                $destinationAcl = Get-Acl -LiteralPath $DestinationPath -ErrorAction Stop
                Set-Acl -LiteralPath $readyPath -AclObject $destinationAcl -ErrorAction Stop
            } catch {
                # A file owned by someone else cannot always hand its permission list to the new copy. The update itself must still go through; File.Replace keeps the old file's permissions.
                Write-Log "${Label}: the old file's permissions could not be copied to the new file ($($_.Exception.Message)); the update continues."
                if (-not $Quiet) { Write-Host '  The old file''s permission settings could not be copied to the new file. The update continues.' -ForegroundColor Yellow }
            }
            Assert-TpmNoReparseWriteTarget -Path $DestinationPath -Operation 'download final promotion'
            try { [System.IO.File]::Replace($readyPath, $DestinationPath, [NullString]::Value) }
            catch {
                # Some network shares do not support File.Replace. The old file is still in place, so a plain overwrite move does the same job.
                Write-Log "${Label}: File.Replace failed ($($_.Exception.Message)); using a plain overwrite move instead."
                Move-Item -LiteralPath $readyPath -Destination $DestinationPath -Force -ErrorAction Stop
            }
        } else {
            Assert-TpmNoReparseWriteTarget -Path $DestinationPath -Operation 'download final promotion'
            [System.IO.File]::Move($readyPath, $DestinationPath)
        }
        $readyPath = $null
        $stopwatch.Stop()
        Write-TpmDownloadMetrics -Label $Label -Method $methodUsed -Path $DestinationPath -Elapsed $stopwatch.Elapsed -Quiet:$Quiet
        Write-DownloadAudit -Source $DownloadUrl -FileName ([System.IO.Path]::GetFileName($DestinationPath)) -Path $DestinationPath -Version $Version
        $downloadCompleted = $true
        return $true
    } catch {
        $stopwatch.Stop()
        if (-not $Quiet) { Write-Host ("  Download failed: {0}" -f $_) -ForegroundColor Red }
        Write-Log "${Label}: download failed -- $_"
        try { if (Test-Path -LiteralPath $tempPath) { [System.IO.File]::Delete($tempPath) } } catch {}
        if ($LastStatusCode) {
            $LastStatusCode.Value = if ($definitiveStatusCode -ne 0) { $definitiveStatusCode } else { $detectedStatusCode }
        }
        return $false
    } finally {
        # Every transport tier updates the shared compact progress row. This
        # unconditional final update prevents stale download text after a
        # success, definitive 404, per-tier failure, or unexpected exception.
        if ($readyPath -and (Test-Path -LiteralPath $readyPath -PathType Leaf)) {
            if ($AllowedRoot) {
                try {
                    [void](Assert-TpmThumbnailWriteTarget -Path $readyPath -RuntimeRoot $AllowedRoot -Operation 'download staging cleanup')
                    Remove-Item -LiteralPath $readyPath -Force -ErrorAction Stop
                } catch {
                    Write-Log "${Label}: staged file cleanup was skipped because its location was no longer safe."
                }
            } else {
                Remove-Item -LiteralPath $readyPath -Force -ErrorAction SilentlyContinue
            }
        }
        # The bar closes Final only when the download was verified and promoted (flag set on the success path only). Any other exit
        # closes it as Error so it can never read as finished. A definitive 404 inside a group-owned bar is the server's answer
        # (callers such as thumbnails treat it as "not available"), not a failed transfer: the group is not marked failed, but the
        # step says "not found online" and never "done".
        $downloadNotAvailable = (-not $downloadCompleted -and $definitiveStatusCode -eq 404 -and (Get-Command -Name Test-TpmProgressGroupOwned -ErrorAction SilentlyContinue) -and (Test-TpmProgressGroupOwned))
        if ($downloadNotAvailable) {
            Write-TpmCompactExtractionProgress -Phase Checking -Label ("Downloading {0}" -f $Label) -Current 0 -Total 0 -StartedAt (Get-Date) -Complete -NotAvailable
        } else {
            $downloadCloseOutcome = if ($downloadCompleted) { 'Final' } else { 'Error' }
            Write-TpmCompactExtractionProgress -Phase Checking -Label ("Downloading {0}" -f $Label) -Current 0 -Total 0 -StartedAt (Get-Date) -Complete -Outcome $downloadCloseOutcome
        }
    }
}

# Compares the local Eggman dat ZIP against the latest GitHub release. The
# release format exposes no separate version number or date, so the remote
# byte size remains the freshness signal, but a same-size file is only treated
# as current after its ZIP structure and collection DAT entry are readable.
# See issue #106: the "check for a newer release" prompt previously always
# asked to download/switch regardless of whether the remote release changed.
# Pure/read-only -- never writes or repairs the local file.
function Test-EggmanDatUpToDate {
    param(
        [string]$LocalDatPath,
        [Int64]$RemoteSizeBytes
    )
    if (-not (Test-Path -LiteralPath $LocalDatPath)) {
        return [pscustomobject]@{ Status = 'Unknown'; LocalSizeBytes = $null }
    }
    $localSizeBytes = (Get-Item -LiteralPath $LocalDatPath).Length
    if (-not (Test-EggmanDatZip -Path $LocalDatPath -ExpectedBytes $localSizeBytes)) {
        return [pscustomobject]@{ Status = 'UpdateAvailable'; LocalSizeBytes = $localSizeBytes }
    }
    $status = if ($localSizeBytes -eq $RemoteSizeBytes) { 'Current' } else { 'UpdateAvailable' }
    return [pscustomobject]@{ Status = $status; LocalSizeBytes = $localSizeBytes }
}

function Invoke-EggmanDatDownload {
    param(
        [string]$downloadUrl,
        [string]$savePath,
        [Int64]$ExpectedBytes = 0,
        [string]$ProgramDirectory = ''
    )
    if (-not (Test-EggmanDatDestinationSafe -Path $savePath -ProgramDirectory $ProgramDirectory)) {
        Write-Log "EggmanDat: SECURITY -- destination failed the immediate pre-download role check: $savePath"
        return $false
    }
    return (Invoke-TpmDownload -DownloadUrl $downloadUrl -DestinationPath $savePath -ExpectedBytes $ExpectedBytes -Label 'EggmanDat' -ValidationScript {
        param([string]$DownloadedPath)
        if (-not (Test-EggmanDatDestinationSafe -Path $savePath -ProgramDirectory $ProgramDirectory)) {
            Write-Log "EggmanDat: SECURITY -- destination failed the immediate pre-write role check: $savePath"
            return $false
        }
        return (Test-EggmanDatZip -Path $DownloadedPath -ExpectedBytes $ExpectedBytes)
    })
}

# Returns the TPM-owned per-user data root for downloaded Eggman recognition
# data. This is deliberately outside the TeknoParrot installation, the TPM
# program folder, game ZIP sources, and the game staging folder. The directory
# is not created by this read-only resolver; Invoke-TpmDownload creates it only
# when a validated download is ready to be written.
function Get-EggmanDatDataRoot {
    $localAppData = [System.Environment]::GetFolderPath([System.Environment+SpecialFolder]::LocalApplicationData)
    if ([string]::IsNullOrWhiteSpace($localAppData)) {
        $localAppData = [System.Environment]::GetEnvironmentVariable('LOCALAPPDATA')
    }
    if ([string]::IsNullOrWhiteSpace($localAppData)) { return $null }
    return (Join-Path $localAppData 'TeknoParrotManager\Eggman')
}

# Review round 3 used a script-adjacent default. That made a download write
# into the TPM package directory and made ownership ambiguous. The default is
# now a deterministic per-user TPM data location. RootPath is test-only
# injection: production callers omit it, while focused tests can remain inside
# their disposable TestDrive instead of touching the real profile.
function Get-EggmanDatDefaultSavePath {
    param([string]$FileName, [string]$RootPath = '')
    $dataRoot = if ([string]::IsNullOrWhiteSpace($RootPath)) { Get-EggmanDatDataRoot } else { $RootPath }
    if ([string]::IsNullOrWhiteSpace($dataRoot)) { return $null }
    return (Join-Path $dataRoot $FileName)
}

# FIX132: the newest valid Eggman DAT ZIP this program saved earlier in its own data folder, or $null. Used when
# GitHub cannot be reached or a download fails, so a copy the program already has is used instead of nothing.
function Find-TpmCachedEggmanDatZip {
    param([string]$RootPath = '')
    $root = if ([string]::IsNullOrWhiteSpace($RootPath)) { Get-EggmanDatDataRoot } else { $RootPath }
    if ([string]::IsNullOrWhiteSpace($root) -or -not (Test-Path -LiteralPath $root -PathType Container)) { return $null }
    foreach ($zip in @(Get-ChildItem -LiteralPath $root -Filter '*.zip' -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTimeUtc -Descending)) {
        if (Test-EggmanDatZip -Path $zip.FullName -ExpectedBytes ([int64]$zip.Length)) { return $zip.FullName }
    }
    return $null
}

# Classify Eggman paths by role instead of treating every mapped/NAS path as
# unsafe. The configured primary ZIP source may be an approved DAT destination
# when it is reachable, canonical, non-reparse, and outside protected roots.
# The supplementary source is never selected as a primary fallback.
function Get-EggmanDatPathRole {
    param(
        [string]$Path,
        [ValidateSet('Destination','PrimaryZipSource')]
        [string]$RequestedRole = 'Destination',
        [string]$ProgramDirectory = ''
    )

    $result = [ordered]@{
        Safe = $false
        CanonicalPath = $null
        Role = 'Unknown'
        ReasonCode = 'Invalid'
        Reason = 'The path is empty or cannot be canonicalized.'
        ReparseBacked = $false
    }
    if ([string]::IsNullOrWhiteSpace($Path)) { return [pscustomobject]$result }

    try {
        if (-not [System.IO.Path]::IsPathRooted($Path)) { return [pscustomobject]$result }
        $result.CanonicalPath = [System.IO.Path]::GetFullPath($Path).TrimEnd('\','/')
        if ([string]::IsNullOrWhiteSpace($result.CanonicalPath)) { return [pscustomobject]$result }
    } catch { return [pscustomobject]$result }

    $canonicalRoots = @{}
    foreach ($entry in @(
        [pscustomobject]@{ Name = 'TeknoParrotRoot'; Path = $tpRoot },
        [pscustomobject]@{ Name = 'GamesInstall'; Path = $gamesInstallFolder },
        [pscustomobject]@{ Name = 'ProgramDirectory'; Path = $ProgramDirectory },
        [pscustomobject]@{ Name = 'PrimaryZipSource'; Path = $zipSource },
        [pscustomobject]@{ Name = 'SupplementaryZipSource'; Path = $zipSourceSupplementary }
    )) {
        if ([string]::IsNullOrWhiteSpace([string]$entry.Path)) { continue }
        try {
            if (-not [System.IO.Path]::IsPathRooted([string]$entry.Path)) {
                $result.ReasonCode = 'Ambiguous'
                $result.Reason = "$($entry.Name) is not an absolute path."
                return [pscustomobject]$result
            }
            $canonicalRoots[$entry.Name] = [System.IO.Path]::GetFullPath([string]$entry.Path).TrimEnd('\','/')
        } catch {
            $result.ReasonCode = 'Ambiguous'
            $result.Reason = "$($entry.Name) cannot be canonicalized."
            return [pscustomobject]$result
        }
    }

    # The extra (supplementary) ZIP folder is never a DAT destination. When the two source folders overlap, a location inside the
    # extra folder is refused with the overlap named as the cause. Everything else is judged as usual: the usual DAT folder, and the
    # main folder when the extra folder is not around it (so the main-folder fallback still works).
    if ($canonicalRoots.ContainsKey('PrimaryZipSource') -and
        $canonicalRoots.ContainsKey('SupplementaryZipSource') -and
        (Test-TpmPathOverlap $canonicalRoots['PrimaryZipSource'] $canonicalRoots['SupplementaryZipSource']) -and
        (Test-PathInside $result.CanonicalPath $canonicalRoots['SupplementaryZipSource'])) {
        $result.ReasonCode = 'AmbiguousSourceRoles'
        $result.Reason = 'Your main ZIP folder and your extra ZIP folder overlap (one is inside the other), so it is not clear which of them this location belongs to.'
        return [pscustomobject]$result
    }

    foreach ($protectedName in @('TeknoParrotRoot','GamesInstall','ProgramDirectory')) {
        if ($canonicalRoots.ContainsKey($protectedName) -and
            (Test-TpmPathOverlap $result.CanonicalPath $canonicalRoots[$protectedName])) {
            $result.ReasonCode = switch ($protectedName) {
                'TeknoParrotRoot' { 'TeknoParrotRoot' }
                'GamesInstall' { 'ProtectedStaging' }
                default { 'ProtectedRuntime' }
            }
            $result.Role = 'Protected'
            $result.Reason = "The path overlaps the protected $protectedName root."
            return [pscustomobject]$result
        }
    }

    if (-not (Test-TpmNoReparsePath -Path $result.CanonicalPath)) {
        $result.ReasonCode = 'ReparseOrInaccessible'
        $result.Reason = 'The path or one of its existing parent components is reparse-backed or inaccessible.'
        $result.ReparseBacked = $true
        return [pscustomobject]$result
    }

    $primaryRoot = if ($canonicalRoots.ContainsKey('PrimaryZipSource')) { $canonicalRoots['PrimaryZipSource'] } else { $null }
    $supplementaryRoot = if ($canonicalRoots.ContainsKey('SupplementaryZipSource')) { $canonicalRoots['SupplementaryZipSource'] } else { $null }

    if ($RequestedRole -eq 'PrimaryZipSource') {
        if ([string]::IsNullOrWhiteSpace($primaryRoot) -or
            -not $result.CanonicalPath.Equals($primaryRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
            $result.ReasonCode = 'NotPrimarySource'
            $result.Reason = 'The path is not the configured primary ZIP/source folder.'
            return [pscustomobject]$result
        }
        if (-not (Test-Path -LiteralPath $result.CanonicalPath -PathType Container -ErrorAction SilentlyContinue)) {
            $result.ReasonCode = 'PrimarySourceUnavailable'
            $result.Reason = 'The configured primary ZIP/source folder is not a reachable directory.'
            return [pscustomobject]$result
        }
        $result.Safe = $true
        $result.Role = 'PrimaryZipSource'
        $result.ReasonCode = 'Safe'
        $result.Reason = 'The configured primary ZIP/source folder is role-safe.'
        return [pscustomobject]$result
    }

    if ($supplementaryRoot -and (Test-PathInside $result.CanonicalPath $supplementaryRoot)) {
        $result.ReasonCode = 'SupplementarySource'
        $result.Reason = 'The supplementary ZIP/source folder is not an automatic primary DAT destination.'
        return [pscustomobject]$result
    }
    if ($primaryRoot -and (Test-PathInside $result.CanonicalPath $primaryRoot)) {
        if (Test-Path -LiteralPath $result.CanonicalPath -PathType Container -ErrorAction SilentlyContinue) {
            $result.ReasonCode = 'DestinationIsFolder'
            $result.Reason = 'The destination must be a file path, not a source folder.'
            return [pscustomobject]$result
        }
        $result.Safe = $true
        $result.Role = 'EggmanDatInPrimaryZipSource'
        $result.ReasonCode = 'Safe'
        $result.Reason = 'The destination is inside the explicitly configured primary ZIP/source folder.'
        return [pscustomobject]$result
    }
    if (($primaryRoot -and (Test-TpmPathOverlap $result.CanonicalPath $primaryRoot)) -or
        ($supplementaryRoot -and (Test-TpmPathOverlap $result.CanonicalPath $supplementaryRoot))) {
        $result.ReasonCode = 'AmbiguousSourceBoundary'
        $result.Reason = 'The destination overlaps a configured source boundary without being inside an approved role.'
        return [pscustomobject]$result
    }
    if (Test-Path -LiteralPath $result.CanonicalPath -PathType Container -ErrorAction SilentlyContinue) {
        $result.ReasonCode = 'DestinationIsFolder'
        $result.Reason = 'The destination must be a file path, not a folder.'
        return [pscustomobject]$result
    }

    $result.Safe = $true
    $result.Role = 'ExternalEggmanDatDestination'
    $result.ReasonCode = 'Safe'
    $result.Reason = 'The destination is outside protected roots and source boundaries.'
    return [pscustomobject]$result
}

function Test-EggmanDatDestinationSafe {
    param(
        [string]$Path,
        [string]$ProgramDirectory = ''
    )
    return [bool](Get-EggmanDatPathRole -Path $Path -RequestedRole Destination -ProgramDirectory $ProgramDirectory).Safe
}

# Return only a reachable, non-reparse primary source folder. This is the
# deliberate fallback for a configured DAT that is readable under TeknoParrot
# but cannot be overwritten there.
function Get-EggmanDatDestinationCandidates {
    param([string]$ProgramDirectory = '')
    $candidate = Get-EggmanDatPathRole -Path $zipSource -RequestedRole PrimaryZipSource -ProgramDirectory $ProgramDirectory
    if ($candidate.Safe) {
        return @([pscustomobject]@{
            Path = $candidate.CanonicalPath
            Role = $candidate.Role
            Reason = $candidate.Reason
        })
    }
    return @()
}

# Resolve the write destination before any release query or download. The
# current DAT remains readable for comparison, but TPM never writes a
# replacement under the TeknoParrot root.
function Resolve-EggmanDatUpdateDestination {
    param(
        [string]$CurrentPath,
        [string]$ProgramDirectory = ''
    )
    $current = Get-EggmanDatPathRole -Path $CurrentPath -RequestedRole Destination -ProgramDirectory $ProgramDirectory
    if ($current.Safe) {
        return [pscustomobject]@{
            Status = 'Ready'
            DestinationPath = $current.CanonicalPath
            DestinationFolder = [System.IO.Path]::GetDirectoryName($current.CanonicalPath)
            Reason = $current.Reason
        }
    }

    $tpRootCanonical = $null
    if (-not [string]::IsNullOrWhiteSpace([string]$tpRoot)) {
        try { $tpRootCanonical = [System.IO.Path]::GetFullPath($tpRoot).TrimEnd('\','/') } catch {}
    }
    if ($tpRootCanonical -and (Test-PathInside $current.CanonicalPath $tpRootCanonical)) {
        Write-Host '  Current DAT is under the TeknoParrot root, which TeknoParrot Manager will not write to.' -ForegroundColor Yellow
        $candidates = @(Get-EggmanDatDestinationCandidates -ProgramDirectory $ProgramDirectory)
        if ($candidates.Count -gt 0) {
            $candidate = $candidates[0]
            Write-Host ("  Safe external DAT folder found: {0}" -f $candidate.Path) -ForegroundColor Green
            $choice = Read-TpmYesNo -Prompt 'Download latest DAT there? (Y/N)'
            if ($choice -eq 'Y') {
                return [pscustomobject]@{
                    Status = 'FallbackSelected'
                    DestinationPath = $null
                    DestinationFolder = $candidate.Path
                    Reason = $candidate.Reason
                }
            }
            Write-Host '  Keeping the current DAT. No download was started.' -ForegroundColor Yellow
            return [pscustomobject]@{
                Status = 'Declined'
                DestinationPath = $null
                DestinationFolder = $null
                Reason = 'The user declined the safe external destination.'
            }
        }
        Write-Host '  No safe external primary DAT folder is configured or reachable.' -ForegroundColor Yellow
        Write-Host '  Action: configure a reachable primary ZIP/source folder outside TeknoParrot' -ForegroundColor Yellow
        Write-Host '  and staging, verify its Windows share permissions, then run the update again.' -ForegroundColor Yellow
        return [pscustomobject]@{
            Status = 'NoSafeDestination'
            DestinationPath = $null
            DestinationFolder = $null
            Reason = 'No role-safe primary ZIP/source folder was available.'
        }
    }

    Write-Host '  The configured Eggman DAT destination is not safe to write.' -ForegroundColor Yellow
    Write-Host ("  Action: choose a normal folder (not a link or junction) outside TeknoParrot and your games folder; TeknoParrot Manager will not write there until it passes this check. ({0})" -f $current.Reason) -ForegroundColor Yellow
    return [pscustomobject]@{
        Status = 'Invalid'
        DestinationPath = $null
        DestinationFolder = $null
        Reason = $current.Reason
    }
}

# A matching byte count is not enough to trust a downloaded Eggman archive:
# a text file, truncated archive, or corrupt ZIP can have the expected length.
# Require a readable ZIP central directory and the collection DAT entry that
# Build-DatIndexFromZip consumes. No extraction or write occurs here.
function Test-EggmanDatZip {
    param([string]$Path, [Int64]$ExpectedBytes = 0)
    if (-not (Test-TpmDownloadedFile -Path $Path -ExpectedBytes $ExpectedBytes)) { return $false }
    $zip = $null
    try {
        $zip = [System.IO.Compression.ZipFile]::OpenRead($Path)
        $collectionEntry = @($zip.Entries | Where-Object { $_.FullName -like '*Collection*_RomVault*.dat' })[0]
        return ($null -ne $collectionEntry)
    } catch {
        Write-Log "EggmanDat: ZIP validation failed for '$Path' -- $_"
        return $false
    } finally {
        if ($zip) { $zip.Dispose() }
    }
}

# Shared download step for a resolved Eggman release. The ordinary first-run
# path uses the deterministic TPM-owned default without asking where to save.
# AllowBrowse is used only when no preferred path was supplied. The configured
# update flow supplies PreferredSavePath, so a valid configured path is reused
# without an alternate-location dialog and is still revalidated before use.
# An unsafe configured DAT under TeknoParrot may offer the role-safe primary
# source folder before any download begins.
# Returns Path/Action/NoOp on success, or $null on failure/abort.
function Invoke-EggmanDatDownloadInteractive {
    param(
        [pscustomobject]$rel,
        [switch]$AllowBrowse,
        [string]$PreferredSavePath = '',
        [string]$DefaultRoot = '',
        [string]$ProgramDirectory = ''
    )

    $safeDatFileName = [System.IO.Path]::GetFileName($rel.FileName)
    $defaultSavePath = if ([string]::IsNullOrWhiteSpace($PreferredSavePath)) {
        Get-EggmanDatDefaultSavePath -FileName $safeDatFileName -RootPath $DefaultRoot
    } else {
        $PreferredSavePath
    }
    $defaultRoot = if ([string]::IsNullOrWhiteSpace($DefaultRoot)) { Get-EggmanDatDataRoot } else { $DefaultRoot }
    $unsafeFileName  = [string]::IsNullOrWhiteSpace($safeDatFileName) -or
        [string]::IsNullOrWhiteSpace($defaultSavePath) -or
        [System.IO.Path]::GetExtension($safeDatFileName) -ne '.zip'
    if ($unsafeFileName) {
        Write-Log "EggmanDat: SECURITY -- unsafe release filename '$($rel.FileName)'"
        Write-Host "  Unexpected filename from GitHub -- skipped for safety." -ForegroundColor Red
        return $null
    }
    $defaultDestination = Get-EggmanDatPathRole -Path $defaultSavePath -RequestedRole Destination -ProgramDirectory $ProgramDirectory
    if (-not $defaultDestination.Safe) {
        $isUnderTeknoParrot = $false
        if (-not [string]::IsNullOrWhiteSpace([string]$tpRoot)) {
            try {
                $isUnderTeknoParrot = Test-PathInside $defaultDestination.CanonicalPath ([System.IO.Path]::GetFullPath($tpRoot))
            } catch {}
        }
        if ($isUnderTeknoParrot) {
            Write-Host '  Current DAT is under the TeknoParrot root, which TeknoParrot Manager will not write to.' -ForegroundColor Yellow
            $candidates = @(Get-EggmanDatDestinationCandidates -ProgramDirectory $ProgramDirectory)
            if ($candidates.Count -gt 0) {
                $candidate = $candidates[0]
                Write-Host ("  Safe external DAT folder found: {0}" -f $candidate.Path) -ForegroundColor Green
                $choice = Read-TpmYesNo -Prompt 'Download latest DAT there? (Y/N)'
                if ($choice -eq 'Y') {
                    $defaultSavePath = Join-Path $candidate.Path $safeDatFileName
                    $defaultDestination = Get-EggmanDatPathRole -Path $defaultSavePath -RequestedRole Destination -ProgramDirectory $ProgramDirectory
                } else {
                    Write-Host '  Keeping the current DAT. No download was started.' -ForegroundColor Yellow
                    return $null
                }
            } else {
                Write-Host '  No safe external primary DAT folder is configured or reachable.' -ForegroundColor Yellow
                Write-Host '  Action: configure a reachable primary ZIP/source folder outside TeknoParrot' -ForegroundColor Yellow
                Write-Host '  and staging, verify its Windows share permissions, then run the update again.' -ForegroundColor Yellow
                return $null
            }
        } else {
            Write-Log "EggmanDat: SECURITY -- default destination failed role validation: $defaultSavePath ($($defaultDestination.Reason))"
            Write-Host '  TeknoParrot Manager could not select a safe Eggman data location for this setup.' -ForegroundColor Yellow
            Write-Host '  Action: choose a regular external DAT folder, not TeknoParrot, the TeknoParrot Manager program folder, games install folders, linked folders or the supplementary ZIP folder.' -ForegroundColor Yellow
            if ($defaultDestination.ReasonCode -eq 'AmbiguousSourceRoles') { Write-Host ('  Reason: {0} Pick a location outside both folders, or change the ZIP folders so neither is inside the other.' -f $defaultDestination.Reason) -ForegroundColor Yellow }
            if (-not $AllowBrowse) { return $null }
            $defaultSavePath = $null
        }
    }
    $rawSave = $defaultSavePath
    if ($AllowBrowse -and [string]::IsNullOrWhiteSpace($PreferredSavePath)) {
        $prompt = if ($defaultSavePath) { "  Save to (Enter for default: $defaultSavePath)" } else { "  Save to (choose a safe alternate location)" }
        $initialDirectory = if ($defaultSavePath) { Split-Path -Parent $defaultSavePath } else { $defaultRoot }
        $rawSave = Read-PathWithBrowse $prompt -Mode SaveFile `
                       -FileFilter "ZIP files (*.zip)|*.zip|All files (*.*)|*.*" -DefaultFileName $safeDatFileName -InitialDirectory $initialDirectory
        if ($script:TpmPathBrowseCancelled) {
            Write-Host '  No location was chosen, so nothing was downloaded.' -ForegroundColor Yellow
            return $null
        }
        if (-not $rawSave) { $rawSave = $defaultSavePath }
    }
    if ([string]::IsNullOrWhiteSpace($rawSave)) {
        Write-Host "  No safe Eggman data destination was selected -- skipped." -ForegroundColor Yellow
        return $null
    }
    try { $rawSave = [System.IO.Path]::GetFullPath($rawSave) } catch {
        Write-Host "  The selected Eggman data destination is not a valid path -- skipped." -ForegroundColor Yellow
        Write-Host '  Action: select a ZIP filename in a reachable external folder and retry the update. Check network folders in File Explorer first.' -ForegroundColor Yellow
        return $null
    }
    $finalDestination = Get-EggmanDatPathRole -Path $rawSave -RequestedRole Destination -ProgramDirectory $ProgramDirectory
    if (-not $finalDestination.Safe) {
        Write-Host '  Refusing to write Eggman recognition data to an unsafe or ambiguous path.' -ForegroundColor Red
        Write-Host '  Action: choose a regular external DAT folder, not TeknoParrot, the TeknoParrot Manager program folder, games install folders, linked folders or the supplementary ZIP folder.' -ForegroundColor Yellow
        if ($finalDestination.ReasonCode -eq 'AmbiguousSourceRoles') { Write-Host ('  Reason: {0} Pick a location outside both folders, or change the ZIP folders so neither is inside the other.' -f $finalDestination.Reason) -ForegroundColor Yellow }
        Write-Log "EggmanDat: SECURITY -- rejected destination $rawSave ($($finalDestination.Reason))"
        return $null
    }
    $rawSave = $finalDestination.CanonicalPath
    if ($rel.SizeBytes -gt 0 -and (Test-EggmanDatZip -Path $rawSave -ExpectedBytes $rel.SizeBytes)) {
        [void](Invoke-TpmProgressGroup -Title 'Eggman DAT download' -Action {
            [pscustomobject]@{ Succeeded = $true; NoOp = $true; Reason = 'MATCHING_RELEASE_DAT_REUSED' }
        })
        Write-Host "  Existing Eggman dat ZIP already matches the release size. Reusing it." -ForegroundColor Green
        Write-Log "EggmanDat: existing ZIP matches release size; download skipped."
        return [pscustomobject]@{ Path = $rawSave; Action = 'Reused'; NoOp = $true }
    }
    Write-Host "  Downloading -- this may take a few minutes..." -ForegroundColor Cyan
    if (Invoke-TpmProgressGroup -Title 'Eggman DAT download' -Action { Invoke-EggmanDatDownload $rel.DownloadUrl $rawSave -ExpectedBytes $rel.SizeBytes -ProgramDirectory $ProgramDirectory }) {
        return [pscustomobject]@{ Path = $rawSave; Action = 'Downloaded'; NoOp = $false }
    }
    return $null
}

# =============================================================================
# POSTGRESQL INSTALL ORCHESTRATION
# =============================================================================
# Confirmed working via multiple real install attempts on a real machine
# this session (several genuine failures along the way, each root-caused
# via verbose MSI logs -- see LESSONS_LEARNED.md's PostgreSQL install notes
# for the full story). Key facts baked into the property list below:
#   - Targets postgresql-8.3-int.msi directly, NOT the postgresql-8.3.msi
#     wrapper -- the wrapper is a near-empty UI shell with no real
#     Feature/Component data of its own; under /qn it has nothing to do
#     and fails.
#   - INTERNALLAUNCH=1 satisfies the internal MSI's own LaunchCondition
#     ("INTERNALLAUNCH=1 OR Installed"), bypassing the wrapper entirely.
#   - ROOTDRIVE=C:\ is required -- without it, MSI's default drive-
#     selection heuristic can pick whatever local drive has the most free
#     space, which would not match the hardcoded
#     C:\Program Files (x86)\PostgreSQL\8.3\ path baked into every
#     GameProfile's Path field.
#   - SERVICEDOMAIN must be the real computer name, NOT the Win32 "local
#     machine" literal "." -- this custom action does its own domain\
#     username string handling and does not resolve "." correctly, which
#     manifests as "No mapping between account names and security IDs
#     was done".

# Queries the GitHub API for the Eggmansworld/tp-it-guides "universal-guide"
# release, which bundles both the PDF setup guide and the actual
# PostgreSQL 8.3 installer files. Unlike the Eggman dat repo, this repo
# hosts several distinct release tags for different purposes (a
# customization guide, a score-submission pack, an obsolete-guides
# archive) -- "latest" would return whichever was most recently published,
# not necessarily this one, so this fetches by the specific known tag.
# Returns [pscustomobject]@{DownloadUrl; FileName; SizeMB}; $null when GitHub could not be reached; an object with an empty DownloadUrl when GitHub answered but gave no usable installer.
function Get-PostgresGuideRelease {
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            $apiUri = 'https://api.github.com/repos/Eggmansworld/tp-it-guides/releases/tags/universal-guide'
            $resp   = Invoke-TpmWebRequestSilently -Uri $apiUri -UseBasicParsing -TimeoutSec 20 `
                          -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $rel    = $resp.Content | ConvertFrom-Json
            $asset  = @($rel.assets) | Where-Object { $_.name -like '*.zip' } | Select-Object -First 1
            if (-not $asset) { Write-Log 'PostgresGuide: the release has no .zip asset.'; return [pscustomobject]@{ DownloadUrl = '' } }
            if ($asset.browser_download_url -notmatch '^https://[a-zA-Z0-9._-]*(github\.com|githubusercontent\.com)/') {
                Write-Log "PostgresGuide: unexpected download URL format -- skipping."
                return [pscustomobject]@{ DownloadUrl = '' }
            }
            return [pscustomobject]@{
                DownloadUrl = $asset.browser_download_url
                FileName    = $asset.name
                SizeMB      = [Math]::Round($asset.size / 1MB, 1)
                SizeBytes   = [int64]$asset.size
            }
        } catch {
            $status = 0
            # Get-TpmHttpStatusCodeFromError guards the same optional
            # .Exception.Response/.StatusCode access this used to do inline
            # (unsafe under strict mode for exception types that lack either
            # property entirely -- RuntimeException from a plain "throw",
            # HttpRequestException, etc.) and additionally falls back to
            # extracting a status code embedded only in the message text.
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "PostgresGuide: GitHub release query failed -- $_"
                if ($status -ge 400 -and $status -lt 500) { return [pscustomobject]@{ DownloadUrl = '' } }
                return $null
            }
            Write-Log "PostgresGuide: attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    return $null
}

# Downloads the guide ZIP through the shared hardened download pipeline.
function Invoke-PostgresGuideDownload {
    param([string]$downloadUrl, [string]$savePath, [Int64]$ExpectedBytes = 0)
    return (Invoke-TpmDownload -DownloadUrl $downloadUrl -DestinationPath $savePath -ExpectedBytes $ExpectedBytes -Label 'PostgresGuide')
}

# True if the current process has Administrator privileges. Installing
# PostgreSQL as a Windows service requires this -- the first such check in
# this script, since every other write this script makes is to ordinary
# user-writable folders or files this script's own process already has
# rights to.
function Test-RunningAsAdministrator {
    $identity  = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($identity)
    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

# Explain the temporary administrator access and UAC approval before each
# PostgreSQL install or recovery handoff. Beginner output stays free of
# implementation details; the protected child resumes the operation.
function Write-PostgresAdministratorGuidance {
    param(
        [ValidateSet('Install','Recovery')]
        [string]$Operation = 'Recovery'
    )
    Write-Host '  This TeknoParrot Manager session is not running as administrator.' -ForegroundColor Yellow
    if ($Operation -eq 'Install') {
        Write-Host '  TeknoParrot Manager needs temporary administrator access to safely install the local PostgreSQL component for these games.' -ForegroundColor Yellow
    } else {
        # FIX95 (B1): no password reset runs any more; the only other elevated operation rebuilds game databases.
        Write-Host '  TeknoParrot Manager needs temporary administrator access to safely rebuild the local PostgreSQL data for these games.' -ForegroundColor Yellow
    }
    Write-Host '  Windows may show a permission window (User Account Control). Click Yes if you want this to continue.' -ForegroundColor Yellow
    Write-Host '  When Windows asks, approve it with an administrator account of this PC. Do not switch to a different account. If your Windows account is not an administrator, close TeknoParrot Manager and start it again with "Run as administrator".' -ForegroundColor Yellow
    Write-Host '  After approval, TeknoParrot Manager tries to continue automatically and reports the result; approval alone does not mean setup or repair succeeded.' -ForegroundColor Yellow
    Write-Host '  If setup stops, read the reported failure and View Log before trying option 11 again.' -ForegroundColor Yellow
    # Give the user time to read this before the Windows permission window opens on top of it (#385).
    $unattendedNow = [bool](Get-Variable -Name Unattended -Scope Script -ValueOnly -ErrorAction SilentlyContinue)
    if (Test-TpmInteractiveInput -Unattended:$unattendedNow) { [void](Read-HostSafe '  Press Enter to open the Windows permission window') }
}
function Get-PostgresRecoveryStateDirectory {
    $base = if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) { $env:LOCALAPPDATA } else { $env:TEMP }
    return (Join-Path $base 'TeknoParrotManager\Recovery')
}

function Set-PostgresRecoveryStateAcl {
    param([Parameter(Mandatory)][string]$Path, [switch]$Directory)
    $sid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value
    $permission = if ($Directory) { '(OI)(CI)(F)' } else { '(F)' }
    $rules = @(
        ('*{0}:{1}' -f $sid, $permission),
        ('*S-1-5-32-544:{0}' -f $permission),
        ('*S-1-5-18:{0}' -f $permission)
    )
    & icacls $Path /inheritance:r /grant:r @rules 1>$null 2>$null
    if ($LASTEXITCODE -ne 0) { throw 'Postgres recovery state ACL could not be verified.' }
    $allowedSids = @($sid, 'S-1-5-32-544', 'S-1-5-18')
    $acl = Get-Acl -LiteralPath $Path
    $foreign = @($acl.Access | Where-Object {
        $resolved = $null
        try { $resolved = $_.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]).Value } catch {}
        $_.IsInherited -or ($resolved -notin $allowedSids)
    })
    if ($foreign.Count -gt 0) { throw 'Postgres recovery state ACL still grants access beyond the expected principals.' }
}

function Protect-PostgresRecoveryEnvelope {
    param([Parameter(Mandatory)][string]$PlainText)
    Add-Type -AssemblyName System.Security
    $bytes = [Text.Encoding]::UTF8.GetBytes($PlainText)
    try {
        $protected = [Security.Cryptography.ProtectedData]::Protect(
            $bytes, $null, [Security.Cryptography.DataProtectionScope]::LocalMachine)
        return [Convert]::ToBase64String($protected)
    } finally {
        if ($bytes) { [Array]::Clear($bytes, 0, $bytes.Length) }
    }
}

function Unprotect-PostgresRecoveryEnvelope {
    param([Parameter(Mandatory)][string]$ProtectedText)
    Add-Type -AssemblyName System.Security
    $protected = [Convert]::FromBase64String($ProtectedText)
    $bytes = $null
    try {
        $bytes = [Security.Cryptography.ProtectedData]::Unprotect(
            $protected, $null, [Security.Cryptography.DataProtectionScope]::LocalMachine)
        return [Text.Encoding]::UTF8.GetString($bytes)
    } finally {
        if ($protected) { [Array]::Clear($protected, 0, $protected.Length) }
        if ($bytes) { [Array]::Clear($bytes, 0, $bytes.Length) }
    }
}

function Remove-PostgresRecoveryState {
    param([string]$Path, [string]$ClaimPath = '')
    $targets = @($Path, $ClaimPath) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique
    try {
        foreach ($target in $targets) {
            if (Test-Path -LiteralPath $target -PathType Leaf) {
                Remove-Item -LiteralPath $target -Force -ErrorAction Stop
            }
        }
        return (@($targets | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf }).Count -eq 0)
    } catch {
        Write-Log 'Postgres recovery: protected resume state cleanup failed.'
        return $false
    }
}

function New-PostgresRecoveryState {
    param(
        [Parameter(Mandatory)][string]$ConfigPath,
        [Parameter(Mandatory)][string]$ScriptPath,
        [Parameter(Mandatory)][string]$TpRoot,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [ValidateSet('Install','Recovery','Reinitialize')]
        [string]$Operation = 'Recovery',
        [string]$PasswordPlain = '',
        [int]$AttemptId = 1,
        [int]$ParentPid = 0,
        [Int64]$ParentStartTicks = 0,
        [string]$ParentProcessPath = '',
        [string]$ParentProcessSha256 = '',
        [string]$OriginUserSid = '',
        [string]$ExpectedScriptSha256 = '',
        [string]$ExpectedConfigSha256 = '',
        [string]$SelectionPlanJson = '',
        [string]$SelectionPlanHash = ''
    )
    if ($Operation -in @('Recovery','Reinitialize') -and [string]::IsNullOrEmpty($PasswordPlain)) {
        throw 'Postgres recovery state requires a chosen password.'
    }
    if ($Operation -eq 'Reinitialize') {
        if ([string]::IsNullOrWhiteSpace($SelectionPlanJson) -or [string]::IsNullOrWhiteSpace($SelectionPlanHash)) {
            throw 'Postgres reinitialize recovery state requires a verified selection plan.'
        }
        if ((Get-PostgresReinitializePlanHash -PlanJson $SelectionPlanJson) -ine $SelectionPlanHash) {
            throw 'Postgres reinitialize recovery state selection hash is invalid.'
        }
    }
    if ($AttemptId -lt 1 -or $AttemptId -gt 5) { throw 'Postgres recovery state attempt limit was exceeded.' }
    $stateDirectory = Get-PostgresRecoveryStateDirectory
    $issuanceId = [guid]::NewGuid().ToString('N')
    $statePath = Join-Path $stateDirectory ('.tpm-postgres-recovery-' + $issuanceId + '.json')
    $tempPath = $statePath + '.tmp'
    try {
        [void][System.IO.Directory]::CreateDirectory($stateDirectory)
        Set-PostgresRecoveryStateAcl -Path $stateDirectory -Directory
        $parent = if ($ParentPid -gt 0) { Get-Process -Id $ParentPid -ErrorAction Stop } else { Get-Process -Id $PID -ErrorAction Stop }
        if ($ParentPid -le 0) { $ParentPid = [int]$PID }
        if ($ParentStartTicks -le 0) { $ParentStartTicks = [int64]$parent.StartTime.ToUniversalTime().Ticks }
        if ([string]::IsNullOrWhiteSpace($ParentProcessPath)) { $ParentProcessPath = [string]$parent.Path }
        if ([string]::IsNullOrWhiteSpace($ParentProcessPath) -or -not (Test-Path -LiteralPath $ParentProcessPath -PathType Leaf)) { throw 'Postgres recovery parent executable could not be verified.' }
        if ([string]::IsNullOrWhiteSpace($ParentProcessSha256)) { $ParentProcessSha256 = (Get-FileHash -LiteralPath $ParentProcessPath -Algorithm SHA256 -ErrorAction Stop).Hash }
        if ([string]::IsNullOrWhiteSpace($OriginUserSid)) { $OriginUserSid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value }
        $scriptFull = [System.IO.Path]::GetFullPath($ScriptPath)
        $configFull = [System.IO.Path]::GetFullPath($ConfigPath)
        $scriptHash = (Get-FileHash -LiteralPath $scriptFull -Algorithm SHA256 -ErrorAction Stop).Hash
        $configHash = (Get-FileHash -LiteralPath $configFull -Algorithm SHA256 -ErrorAction Stop).Hash
        if ($ExpectedScriptSha256 -and $scriptHash -ne $ExpectedScriptSha256) { throw 'Postgres recovery script changed during retry.' }
        if ($ExpectedConfigSha256 -and $configHash -ne $ExpectedConfigSha256) { throw 'Postgres recovery configuration changed during retry.' }
        $created = (Get-Date).ToUniversalTime()
        $expires = $created.AddMinutes(5)
        $payload = [ordered]@{
            SchemaVersion           = 4
            Purpose                 = 'TeknoParrotManager.PostgresRecovery'
            IssuanceId              = $issuanceId
            Operation               = $Operation
            Nonce                   = [guid]::NewGuid().ToString('N')
            AttemptId               = $AttemptId
            CreatedUtc              = $created.ToString('o')
            ExpiresUtc              = $expires.ToString('o')
            ParentPid               = $ParentPid
            ParentStartTicks        = $ParentStartTicks
            ParentProcessPath       = [System.IO.Path]::GetFullPath($ParentProcessPath)
            ParentProcessSha256     = $ParentProcessSha256
            OriginUserSid           = $OriginUserSid
            MachineName             = [Environment]::MachineName
            ScriptPath              = $scriptFull
            ScriptSha256            = $scriptHash
            ConfigPath              = $configFull
            ConfigSha256            = $configHash
            TpRoot                  = [System.IO.Path]::GetFullPath($TpRoot)
            UserProfilesDir         = [System.IO.Path]::GetFullPath($UserProfilesDir)
            PasswordPlain           = $PasswordPlain
            PasswordOriginEncrypted = if ($Operation -in @('Recovery','Reinitialize')) { ConvertTo-PostgresEncryptedPassword -PlainText $PasswordPlain } else { '' }
            SelectionPlanJson       = $SelectionPlanJson
            SelectionPlanHash       = $SelectionPlanHash
        }
        $outer = [ordered]@{
            SchemaVersion = 4
            Purpose       = 'TeknoParrotManager.PostgresRecovery'
            CipherText    = Protect-PostgresRecoveryEnvelope -PlainText ($payload | ConvertTo-Json -Depth 8)
        }
        [System.IO.File]::WriteAllText($tempPath, ($outer | ConvertTo-Json -Depth 4), (New-Object System.Text.UTF8Encoding $false))
        Set-PostgresRecoveryStateAcl -Path $tempPath
        [System.IO.File]::Move($tempPath, $statePath)
        Set-PostgresRecoveryStateAcl -Path $statePath
        if (-not (Test-Path -LiteralPath $statePath -PathType Leaf)) { throw 'Protected recovery state was not created.' }
        return $statePath
    } catch {
        [void](Remove-PostgresRecoveryState -Path $statePath)
        if (Test-Path -LiteralPath $tempPath -PathType Leaf) { Remove-Item -LiteralPath $tempPath -Force -ErrorAction SilentlyContinue }
        throw 'TeknoParrot Manager could not prepare the protected PostgreSQL recovery handoff.'
    } finally {
        $PasswordPlain = $null
        [GC]::Collect()
    }
}

function New-PostgresRecoveryRetryState {
    param([Parameter(Mandatory)]$State)
    return New-PostgresRecoveryState -ConfigPath $State.ConfigPath -ScriptPath $State.ScriptPath `
        -TpRoot $State.TpRoot -UserProfilesDir $State.UserProfilesDir -Operation $State.Operation `
        -PasswordPlain $State.PasswordPlain -AttemptId ([int]$State.AttemptId + 1) `
        -ParentPid ([int]$State.ParentPid) -ParentStartTicks ([Int64]$State.ParentStartTicks) `
        -ParentProcessPath $State.ParentProcessPath -ParentProcessSha256 $State.ParentProcessSha256 `
        -OriginUserSid $State.OriginUserSid -ExpectedScriptSha256 $State.ScriptSha256 `
        -ExpectedConfigSha256 $State.ConfigSha256 -SelectionPlanJson $State.SelectionPlanJson `
        -SelectionPlanHash $State.SelectionPlanHash
}

function Find-PostgresRecoveryRetryState {
    param(
        [Parameter(Mandatory)][string]$PreviousStatePath,
        [Parameter(Mandatory)][string]$ExpectedConfigPath,
        [Parameter(Mandatory)][string]$ExpectedScriptPath,
        [Parameter(Mandatory)][string]$ExpectedTpRoot,
        [Parameter(Mandatory)][string]$ExpectedUserProfilesDir,
        [Parameter(Mandatory)][int]$ExpectedParentPid,
        [Parameter(Mandatory)][int]$PreviousAttemptId
    )
    $stateDirectory = [System.IO.Path]::GetFullPath((Get-PostgresRecoveryStateDirectory)).TrimEnd('\','/')
    $previousFull = [System.IO.Path]::GetFullPath($PreviousStatePath)
    $retryCandidates = Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $stateDirectory -ProgressLabel 'PostgreSQL recovery retry-state discovery' -Filter '.tpm-postgres-recovery-*.json' -EnumerationErrorAction SilentlyContinue
    foreach ($candidate in @($retryCandidates | Sort-Object LastWriteTimeUtc -Descending)) {
        if ($candidate.FullName -ieq $previousFull) { continue }
        try {
            $outer = Get-Content -LiteralPath $candidate.FullName -Raw -ErrorAction Stop | ConvertFrom-Json
            if ($outer.SchemaVersion -ne 4 -or $outer.Purpose -ne 'TeknoParrotManager.PostgresRecovery' -or [string]::IsNullOrWhiteSpace([string]$outer.CipherText)) { continue }
            $payload = Unprotect-PostgresRecoveryEnvelope -ProtectedText ([string]$outer.CipherText) | ConvertFrom-Json
            if ([int]$payload.ParentPid -ne $ExpectedParentPid -or [int]$payload.AttemptId -le $PreviousAttemptId) { continue }
            if ([System.IO.Path]::GetFullPath([string]$payload.ConfigPath) -ine [System.IO.Path]::GetFullPath($ExpectedConfigPath) -or
                [System.IO.Path]::GetFullPath([string]$payload.ScriptPath) -ine [System.IO.Path]::GetFullPath($ExpectedScriptPath) -or
                [System.IO.Path]::GetFullPath([string]$payload.TpRoot) -ine [System.IO.Path]::GetFullPath($ExpectedTpRoot) -or
                [System.IO.Path]::GetFullPath([string]$payload.UserProfilesDir) -ine [System.IO.Path]::GetFullPath($ExpectedUserProfilesDir)) { continue }
            return $candidate.FullName
        } catch {}
    }
    return $null
}

# Returns the saved-settings file a protected PostgreSQL resume must load: the
# one its parent recorded in the resume state, and only when that is the
# TPM-owned settings file of the recorded TeknoParrot root, or the settings file
# beside this script (the older layout many users still have), and its bytes
# still match the recorded ConfigSha256 (so a settings file changed since the
# handoff cannot point startup at another root before the full check runs).
# Read-only and does not consume the state (Read-PostgresRecoveryState validates
# and consumes it later). Returns $null otherwise, so the resume stops instead of
# guessing a root from the settings locator or auto-detection.
function Get-PostgresRecoveryResumeConfigPath {
    param([Parameter(Mandatory)][string]$StatePath, [string]$ScriptRoot = '')
    $payload = $null
    try {
        $stateDirectory = [System.IO.Path]::GetFullPath((Get-PostgresRecoveryStateDirectory)).TrimEnd('\','/')
        $fullPath = [System.IO.Path]::GetFullPath($StatePath)
        if ([System.IO.Path]::GetDirectoryName($fullPath).TrimEnd('\','/') -ine $stateDirectory -or
            [System.IO.Path]::GetFileName($fullPath) -notmatch '^\.tpm-postgres-recovery-[0-9a-f]{32}\.json$' -or
            -not (Test-Path -LiteralPath $fullPath -PathType Leaf)) { return $null }
        $outer = Get-Content -LiteralPath $fullPath -Raw -ErrorAction Stop | ConvertFrom-Json
        if ($outer.SchemaVersion -ne 4 -or $outer.Purpose -ne 'TeknoParrotManager.PostgresRecovery' -or [string]::IsNullOrWhiteSpace([string]$outer.CipherText)) { return $null }
        $payload = Unprotect-PostgresRecoveryEnvelope -ProtectedText ([string]$outer.CipherText) | ConvertFrom-Json
        if ($payload.SchemaVersion -ne 4 -or $payload.Purpose -ne 'TeknoParrotManager.PostgresRecovery') { return $null }
        $recordedConfig = [string]$payload.ConfigPath
        $ownedConfig = Get-TpmOwnedConfigPathForRoot -TeknoParrotRoot ([string]$payload.TpRoot)
        if ([string]::IsNullOrWhiteSpace($recordedConfig)) { return $null }
        $recordedFull = [System.IO.Path]::GetFullPath($recordedConfig)
        $legacyConfig = if ([string]::IsNullOrWhiteSpace($ScriptRoot)) { $null } else { Join-Path $ScriptRoot 'TeknoParrot-Manager.config.json' }
        $acceptedConfig = $null
        if ($ownedConfig -and $recordedFull -ieq [System.IO.Path]::GetFullPath($ownedConfig)) { $acceptedConfig = $ownedConfig }
        elseif ($legacyConfig -and $recordedFull -ieq [System.IO.Path]::GetFullPath($legacyConfig)) { $acceptedConfig = $legacyConfig }
        if (-not $acceptedConfig) { return $null }
        $recordedHash = [string]$payload.ConfigSha256
        if ([string]::IsNullOrWhiteSpace($recordedHash) -or -not (Test-Path -LiteralPath $acceptedConfig -PathType Leaf)) { return $null }
        if ((Get-FileHash -LiteralPath $acceptedConfig -Algorithm SHA256 -ErrorAction Stop).Hash -ine $recordedHash) { return $null }
        return $acceptedConfig
    } catch {
        return $null
    } finally {
        $payload = $null
    }
}

function Read-PostgresRecoveryState {
    param(
        [Parameter(Mandatory)][string]$StatePath,
        [Parameter(Mandatory)][string]$ExpectedConfigPath,
        [Parameter(Mandatory)][string]$ExpectedScriptPath,
        [Parameter(Mandatory)][string]$ExpectedTpRoot,
        [Parameter(Mandatory)][string]$ExpectedUserProfilesDir
    )
    $passwordPlain = $null
    $fullPath = $null
    $claimPath = $null
    $usedPath = $null
    $claimMoved = $false
    $usedCreated = $false
    try {
        $stateDirectory = [System.IO.Path]::GetFullPath((Get-PostgresRecoveryStateDirectory)).TrimEnd('\','/')
        $fullPath = [System.IO.Path]::GetFullPath($StatePath)
        $leaf = [System.IO.Path]::GetFileName($fullPath)
        $issuanceMatch = [regex]::Match($leaf, '^\.tpm-postgres-recovery-(?<id>[0-9a-f]{32})\.json$')
        if ([System.IO.Path]::GetDirectoryName($fullPath).TrimEnd('\','/') -ine $stateDirectory -or
            -not $issuanceMatch.Success -or
            -not (Test-Path -LiteralPath $fullPath -PathType Leaf)) { throw 'Recovery state path is not a TeknoParrot Manager state file.' }
        $fileIssuanceId = $issuanceMatch.Groups['id'].Value
        $claimPath = $fullPath + '.claim'
        $usedPath = $fullPath + '.used'
        if ((Test-Path -LiteralPath $usedPath -PathType Leaf) -or (Test-Path -LiteralPath $claimPath -PathType Leaf)) { throw 'Recovery state was already consumed.' }
        [System.IO.File]::Move($fullPath, $claimPath)
        $claimMoved = $true
        $markerStream = $null
        try {
            $markerStream = [System.IO.File]::Open($usedPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
            $usedCreated = $true
            $markerStream.Close()
        } finally {
            if ($markerStream) { $markerStream.Dispose() }
        }
        Set-PostgresRecoveryStateAcl -Path $usedPath
        $outer = Get-Content -LiteralPath $claimPath -Raw -ErrorAction Stop | ConvertFrom-Json
        if ($outer.SchemaVersion -ne 4 -or $outer.Purpose -ne 'TeknoParrotManager.PostgresRecovery' -or [string]::IsNullOrWhiteSpace([string]$outer.CipherText)) { throw 'Recovery state envelope is invalid.' }
        $payload = Unprotect-PostgresRecoveryEnvelope -ProtectedText ([string]$outer.CipherText) | ConvertFrom-Json
        if ($payload.SchemaVersion -ne 4 -or $payload.Purpose -ne 'TeknoParrotManager.PostgresRecovery' -or
            [string]$payload.IssuanceId -ne $fileIssuanceId -or
            $payload.Operation -notin @('Install','Recovery','Reinitialize') -or [string]::IsNullOrWhiteSpace([string]$payload.Nonce) -or
            [int]$payload.AttemptId -lt 1 -or [int]$payload.AttemptId -gt 5) { throw 'Recovery state metadata is invalid.' }
        if ($payload.Operation -eq 'Reinitialize') {
            if ([string]::IsNullOrWhiteSpace([string]$payload.SelectionPlanJson) -or [string]::IsNullOrWhiteSpace([string]$payload.SelectionPlanHash)) {
                throw 'Recovery reinitialize selection is missing.'
            }
            if ((Get-PostgresReinitializePlanHash -PlanJson ([string]$payload.SelectionPlanJson)) -ine [string]$payload.SelectionPlanHash) {
                throw 'Recovery reinitialize selection hash is invalid.'
            }
        }
        $now = (Get-Date).ToUniversalTime()
        $created = if ($payload.CreatedUtc -is [DateTime]) { ([DateTime]$payload.CreatedUtc).ToUniversalTime() } else { [DateTimeOffset]::Parse([string]$payload.CreatedUtc).UtcDateTime }
        $expires = if ($payload.ExpiresUtc -is [DateTime]) { ([DateTime]$payload.ExpiresUtc).ToUniversalTime() } else { [DateTimeOffset]::Parse([string]$payload.ExpiresUtc).UtcDateTime }
        if ($expires -le $created -or ($expires - $created) -gt [TimeSpan]::FromMinutes(5) -or $created -gt $now.AddMinutes(2) -or $expires -le $now) { throw 'Recovery state lifetime is invalid or expired.' }
        $packageIdentityDifferences = New-Object System.Collections.Generic.List[string]
        $expectedConfigFull = [System.IO.Path]::GetFullPath($ExpectedConfigPath)
        $expectedScriptFull = [System.IO.Path]::GetFullPath($ExpectedScriptPath)
        $expectedTpRootFull = [System.IO.Path]::GetFullPath($ExpectedTpRoot)
        $expectedProfilesFull = [System.IO.Path]::GetFullPath($ExpectedUserProfilesDir)
        $recordedConfigFull = [System.IO.Path]::GetFullPath([string]$payload.ConfigPath)
        $recordedScriptFull = [System.IO.Path]::GetFullPath([string]$payload.ScriptPath)
        $recordedTpRootFull = [System.IO.Path]::GetFullPath([string]$payload.TpRoot)
        $recordedProfilesFull = [System.IO.Path]::GetFullPath([string]$payload.UserProfilesDir)
        if ($recordedConfigFull -ine $expectedConfigFull) {
            [void]$packageIdentityDifferences.Add(("ConfigPath recorded='{0}' current='{1}'" -f $recordedConfigFull, $expectedConfigFull))
        }
        if ($recordedScriptFull -ine $expectedScriptFull) {
            [void]$packageIdentityDifferences.Add(("ScriptPath recorded='{0}' current='{1}'" -f $recordedScriptFull, $expectedScriptFull))
        }
        if ($recordedTpRootFull -ine $expectedTpRootFull) {
            [void]$packageIdentityDifferences.Add(("TeknoParrotRoot recorded='{0}' current='{1}'" -f $recordedTpRootFull, $expectedTpRootFull))
        }
        if ($recordedProfilesFull -ine $expectedProfilesFull) {
            [void]$packageIdentityDifferences.Add(("UserProfilesDir recorded='{0}' current='{1}'" -f $recordedProfilesFull, $expectedProfilesFull))
        }
        if ($packageIdentityDifferences.Count -gt 0) {
            throw ('Recovery package identity mismatch: ' + ($packageIdentityDifferences -join '; '))
        }
        if ([string]$payload.MachineName -ine [Environment]::MachineName -or [string]$payload.OriginUserSid -ne [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value) { throw 'Recovery state belongs to a different Windows identity.' }
        $parent = Get-Process -Id ([int]$payload.ParentPid) -ErrorAction Stop
        if ([int64]$parent.StartTime.ToUniversalTime().Ticks -ne [int64]$payload.ParentStartTicks -or
            [System.IO.Path]::GetFullPath([string]$parent.Path) -ine [System.IO.Path]::GetFullPath([string]$payload.ParentProcessPath) -or
            (Get-FileHash -LiteralPath $parent.Path -Algorithm SHA256 -ErrorAction Stop).Hash -ne [string]$payload.ParentProcessSha256) { throw 'Recovery parent identity changed.' }
        $currentScriptSha256 = $null
        $currentConfigSha256 = $null
        try {
            $currentScriptSha256 = (Get-FileHash -LiteralPath $expectedScriptFull -Algorithm SHA256 -ErrorAction Stop).Hash
        } catch {
            throw ("Recovery package identity mismatch: ScriptPath '{0}' could not be read ({1})." -f $expectedScriptFull, $_.Exception.Message)
        }
        try {
            $currentConfigSha256 = (Get-FileHash -LiteralPath $expectedConfigFull -Algorithm SHA256 -ErrorAction Stop).Hash
        } catch {
            throw ("Recovery package identity mismatch: ConfigPath '{0}' could not be read ({1})." -f $expectedConfigFull, $_.Exception.Message)
        }
        if ($currentScriptSha256 -ine [string]$payload.ScriptSha256) {
            throw ("Recovery package identity mismatch: ScriptSha256 recorded='{0}' current='{1}'." -f [string]$payload.ScriptSha256, $currentScriptSha256)
        }
        if ($currentConfigSha256 -ine [string]$payload.ConfigSha256) {
            throw ("Recovery package identity mismatch: ConfigSha256 recorded='{0}' current='{1}'." -f [string]$payload.ConfigSha256, $currentConfigSha256)
        }
        $markerText = 'TPM.PostgresRecovery.v4|' + [string]$payload.IssuanceId + '|' + [string]$payload.Nonce + '|' + [string]$payload.AttemptId
        [System.IO.File]::WriteAllText($usedPath, $markerText, (New-Object System.Text.UTF8Encoding $false))
        if ((Get-Content -LiteralPath $usedPath -Raw -ErrorAction Stop) -ne $markerText) { throw 'Recovery state consumption marker could not be verified.' }
        if ($payload.Operation -in @('Recovery','Reinitialize')) {
            $passwordPlain = [string]$payload.PasswordPlain
            if ([string]::IsNullOrEmpty($passwordPlain) -or [string]::IsNullOrEmpty([string]$payload.PasswordOriginEncrypted)) { throw 'Recovery password state is missing.' }
        } elseif (-not [string]::IsNullOrEmpty([string]$payload.PasswordPlain) -or -not [string]::IsNullOrEmpty([string]$payload.PasswordOriginEncrypted)) {
            throw 'Install state unexpectedly contains a password.'
        }
        return [pscustomobject]@{
            Path                    = $fullPath
            ClaimPath               = $claimPath
            UsedPath                = $usedPath
            IssuanceId              = [string]$payload.IssuanceId
            Nonce                   = [string]$payload.Nonce
            Operation               = [string]$payload.Operation
            AttemptId               = [int]$payload.AttemptId
            CreatedUtc              = [string]$payload.CreatedUtc
            ExpiresUtc              = [string]$payload.ExpiresUtc
            ParentPid               = [int]$payload.ParentPid
            ParentStartTicks        = [Int64]$payload.ParentStartTicks
            ParentProcessPath       = [string]$payload.ParentProcessPath
            ParentProcessSha256     = [string]$payload.ParentProcessSha256
            OriginUserSid            = [string]$payload.OriginUserSid
            ScriptPath              = [string]$payload.ScriptPath
            ScriptSha256            = [string]$payload.ScriptSha256
            ConfigPath              = [string]$payload.ConfigPath
            ConfigSha256            = [string]$payload.ConfigSha256
            TpRoot                  = [string]$payload.TpRoot
            UserProfilesDir         = [string]$payload.UserProfilesDir
            PasswordPlain           = $passwordPlain
            PasswordOriginEncrypted = [string]$payload.PasswordOriginEncrypted
            SelectionPlanJson       = [string]$payload.SelectionPlanJson
            SelectionPlanHash       = [string]$payload.SelectionPlanHash
        }
    } catch {
        $validationReason = [string]$_.Exception.Message
        $reasonCode = 'VALIDATION_FAILED'
        $reasonText = 'The saved repair record could not be validated.'
        $packageMismatchText = 'The PostgreSQL repair was created by a different TeknoParrot Manager source/configuration, or that source/configuration changed while Windows approval was open. This resume attempt stopped before changing PostgreSQL. Restart setup from the same TeknoParrot Manager copy that opened the permission prompt; the log records the specific identity mismatch.'
        # The identity-mismatch message embeds file paths, so classify it first and anchored; a path containing words such as 'expired' or 'selection' must not select another reason.
        if ($validationReason -match '^Recovery package identity mismatch') {
            $reasonCode = 'PACKAGE_MISMATCH'
            $reasonText = $packageMismatchText
        } elseif ($validationReason -match 'already consumed') {
            $reasonCode = 'RESUME_STATE_CONSUMED'
            $reasonText = 'The saved repair record was already used or is no longer available.'
        } elseif ($validationReason -match 'lifetime|expired') {
            $reasonCode = 'RESUME_EXPIRED'
            $reasonText = 'The saved repair record expired before TeknoParrot Manager could continue.'
        } elseif ($validationReason -match 'selection') {
            $reasonCode = 'SELECTION_PLAN_INVALID'
            $reasonText = 'The PostgreSQL game selection could not be validated.'
        } elseif ($validationReason -match 'Windows identity|parent identity') {
            $reasonCode = 'IDENTITY_MISMATCH'
            $reasonText = 'The saved repair record belongs to a different Windows process or user identity.'
        } elseif ($validationReason -match 'password') {
            $reasonCode = 'PASSWORD_STATE_INVALID'
            $reasonText = 'The PostgreSQL password state could not be validated.'
        } elseif ($validationReason -match 'state path|state file|envelope|metadata') {
            $reasonCode = 'RESUME_STATE_INVALID'
            $reasonText = 'The saved repair record is missing or invalid.'
        }
        Write-Log ("Postgres recovery state validation failed -- Code={0}; Detail={1}" -f $reasonCode, $validationReason)
        try {
            # Undo only what this call did: another attempt's consumption marker or claim must never be removed or restored here.
            if ($usedCreated -and $usedPath -and (Test-Path -LiteralPath $usedPath -PathType Leaf)) { Remove-Item -LiteralPath $usedPath -Force -ErrorAction Stop }
            if ($claimMoved -and $claimPath -and (Test-Path -LiteralPath $claimPath -PathType Leaf) -and -not (Test-Path -LiteralPath $fullPath -PathType Leaf)) {
                [System.IO.File]::Move($claimPath, $fullPath)
            }
        } catch { Write-Log 'Postgres recovery state validation cleanup failed; encrypted evidence was retained.' }
        throw ('TeknoParrot Manager could not safely resume the PostgreSQL setup. Reason [{0}]: {1} Details: {2}' -f $reasonCode, $reasonText, $validationReason)
    } finally {
        $passwordPlain = $null
        [GC]::Collect()
    }
}

# FIX39: the elevated protected-resume child tells the waiting original window
# what it did through one small JSON file next to its protected request
# ('<request>.result' in TeknoParrot Manager's own Recovery folder). The file
# holds no password and no path. The original window reads it only after the
# child process has exited, and uses it only to choose the one message it
# shows: it never resets, retries or saves anything because of it.
function Get-PostgresRecoveryHandoffResultPath {
    param([AllowNull()][AllowEmptyString()][string]$StatePath)
    if ([string]::IsNullOrWhiteSpace($StatePath)) { return $null }
    try {
        $stateDirectory = [System.IO.Path]::GetFullPath((Get-PostgresRecoveryStateDirectory)).TrimEnd('\','/')
        $fullPath = [System.IO.Path]::GetFullPath($StatePath)
        $issuance = [regex]::Match([System.IO.Path]::GetFileName($fullPath), '^\.tpm-postgres-recovery-(?<id>[0-9a-f]{32})\.json$')
        if (-not $issuance.Success -or [System.IO.Path]::GetDirectoryName($fullPath).TrimEnd('\','/') -ine $stateDirectory) { return $null }
        return [pscustomobject]@{ Path = ($fullPath + '.result'); IssuanceId = $issuance.Groups['id'].Value }
    } catch {
        return $null
    }
}

# Builds the child's result from what the protected resume recorded. The protected
# resume never changes the PostgreSQL password (it only checks it), so a stop is
# always "StoppedNoPasswordChange" unless an unexpected error leaves everything unknown.
function New-PostgresRecoveryHandoffResult {
    param([AllowNull()]$ResumeState, [switch]$Completed, [bool]$RetryIssued = $false, [switch]$UnexpectedError)
    $operation = ''
    $backupSucceeded = $null
    if ($ResumeState) {
        $operation = [string]$ResumeState.Operation
        $backupProperty = $ResumeState.PSObject.Properties['DatabaseBackupSucceeded']
        if ($null -ne $backupProperty -and $null -ne $backupProperty.Value) { $backupSucceeded = [bool]$backupProperty.Value }
    }
    $backupDone = ($null -ne $backupSucceeded -and $backupSucceeded)
    if ($Completed) {
        $outcome = 'Completed'
        $summary = 'PostgreSQL setup finished in the administrator window.'
    } elseif ($UnexpectedError -and $ResumeState) {
        $outcome = 'StoppedUnexpectedError'
        $summary = 'PostgreSQL setup stopped in the administrator window because of an unexpected error.'
    } else {
        $outcome = 'StoppedNoPasswordChange'
        $summary = 'PostgreSQL setup stopped in the administrator window; the database login was not changed.'
    }
    $stage = if ($Completed) { 'Completed' }
        elseif (-not $ResumeState) { 'NotStarted' }
        elseif ($backupDone) { 'DatabaseBackupDone' }
        elseif ($null -ne $backupSucceeded) { 'DatabaseBackupFailed' }
        else { 'Started' }
    # Only a password repair that stopped at or before the database backup has
    # changed nothing else: profiles and settings are written after that point,
    # and Install/Reinitialize change PostgreSQL data on their own.
    $nothingElseChanged = [bool](-not $Completed -and -not $UnexpectedError -and $operation -eq 'Recovery' -and -not $backupDone)
    return [pscustomobject]@{
        Operation          = $operation
        Outcome            = $outcome
        StageReached       = $stage
        BackupSucceeded    = $backupSucceeded
        NothingElseChanged = $nothingElseChanged
        RetryIssued        = [bool]($RetryIssued -and $outcome -eq 'StoppedNoPasswordChange')
        Summary            = $summary
    }
}

# Atomic write: a uniquely named temporary file, then a non-overwriting move,
# so the first result for a request wins and a half-written file is never read.
# Returns $true only when the final file reads back byte for byte.
function Write-PostgresRecoveryHandoffResult {
    param([AllowNull()][AllowEmptyString()][string]$StatePath, [Parameter(Mandatory)]$Result)
    $target = Get-PostgresRecoveryHandoffResultPath -StatePath $StatePath
    if (-not $target) {
        Write-Log 'Postgres recovery resume: no result was written for the original window because the protected request path is not a TeknoParrot Manager recovery path.'
        return $false
    }
    $payload = [ordered]@{
        SchemaVersion      = 1
        Purpose            = 'TeknoParrotManager.PostgresRecoveryResult'
        IssuanceId         = $target.IssuanceId
        ChildPid           = [int]$PID
        WrittenUtc         = (Get-Date).ToUniversalTime().ToString('o')
        Operation          = [string]$Result.Operation
        Outcome            = [string]$Result.Outcome
        StageReached       = [string]$Result.StageReached
        BackupSucceeded    = $Result.BackupSucceeded
        NothingElseChanged = [bool]$Result.NothingElseChanged
        RetryIssued        = [bool]$Result.RetryIssued
        Summary            = [string]$Result.Summary
    }
    $json = $payload | ConvertTo-Json -Depth 3
    $tempPath = $target.Path + '.' + [guid]::NewGuid().ToString('N') + '.tmp'
    try {
        [System.IO.File]::WriteAllText($tempPath, $json, (New-Object System.Text.UTF8Encoding $false))
        [System.IO.File]::Move($tempPath, $target.Path)
        if ([System.IO.File]::ReadAllText($target.Path) -cne $json) { throw 'The result file did not read back.' }
        Write-Log ('Postgres recovery resume: result for the original window written; Outcome={0}; Stage={1}.' -f $payload.Outcome, $payload.StageReached)
        return $true
    } catch {
        Write-Log 'Postgres recovery resume: the result for the original window could not be written and verified.'
        return $false
    } finally {
        if (Test-Path -LiteralPath $tempPath -PathType Leaf) { Remove-Item -LiteralPath $tempPath -Force -ErrorAction SilentlyContinue }
    }
}

# Returns Valid=$false with Reason Missing, Corrupt or Mismatch unless the file
# is exactly a result this request's child wrote: right purpose, schema,
# request id and child process id, and internally consistent fields.
function Read-PostgresRecoveryHandoffResult {
    param([AllowNull()][AllowEmptyString()][string]$StatePath, [int]$ChildProcessId = 0)
    $target = Get-PostgresRecoveryHandoffResultPath -StatePath $StatePath
    if (-not $target) { return [pscustomobject]@{ Valid = $false; Reason = 'Mismatch'; Result = $null } }
    if (-not (Test-Path -LiteralPath $target.Path -PathType Leaf)) { return [pscustomobject]@{ Valid = $false; Reason = 'Missing'; Result = $null } }
    $data = $null
    try {
        $item = Get-Item -LiteralPath $target.Path -Force -ErrorAction Stop
        if ($item.Length -gt 16384 -or ($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) { throw 'The result file is not a plain small file.' }
        $data = [System.IO.File]::ReadAllText($target.Path) | ConvertFrom-Json -ErrorAction Stop
    } catch {
        return [pscustomobject]@{ Valid = $false; Reason = 'Corrupt'; Result = $null }
    }
    $isBool = { param($Value) $Value -is [bool] }
    $outcomes = @('Completed', 'StoppedNoPasswordChange', 'StoppedUnexpectedError')
    $stages = @('NotStarted', 'Started', 'DatabaseBackupFailed', 'DatabaseBackupDone', 'Completed')
    try {
        $valid = ($null -ne $data -and
            [string]$data.Purpose -ceq 'TeknoParrotManager.PostgresRecoveryResult' -and
            ($data.SchemaVersion -is [int] -or $data.SchemaVersion -is [long]) -and [int]$data.SchemaVersion -eq 1 -and
            [string]$data.IssuanceId -ceq $target.IssuanceId -and
            ($ChildProcessId -le 0 -or [int]$data.ChildPid -eq $ChildProcessId) -and
            [string]$data.Operation -cin @('', 'Install', 'Recovery', 'Reinitialize') -and
            [string]$data.Outcome -cin $outcomes -and [string]$data.StageReached -cin $stages -and
            ($null -eq $data.BackupSucceeded -or (& $isBool $data.BackupSucceeded)) -and
            (& $isBool $data.NothingElseChanged) -and (& $isBool $data.RetryIssued) -and
            $data.Summary -is [string] -and -not [string]::IsNullOrWhiteSpace([string]$data.Summary) -and
            (Test-TpmTransactionUserSafeSummary -Summary ([string]$data.Summary)))
        if ($valid -and ([string]$data.Outcome -ceq 'Completed') -ne ([string]$data.StageReached -ceq 'Completed')) { $valid = $false }
        if ($valid -and $data.RetryIssued -and [string]$data.Outcome -cne 'StoppedNoPasswordChange') { $valid = $false }
    } catch {
        $valid = $false
    }
    if (-not $valid) { return [pscustomobject]@{ Valid = $false; Reason = 'Corrupt'; Result = $null } }
    return [pscustomobject]@{
        Valid  = $true
        Reason = 'Read'
        Result = [pscustomobject]@{
            Operation          = [string]$data.Operation
            Outcome            = [string]$data.Outcome
            StageReached       = [string]$data.StageReached
            BackupSucceeded    = $data.BackupSucceeded
            NothingElseChanged = [bool]$data.NothingElseChanged
            RetryIssued        = [bool]$data.RetryIssued
            Summary            = [string]$data.Summary
        }
    }
}

# Removes a result file only after Read-PostgresRecoveryHandoffResult proved it
# is this request's own result.
function Remove-PostgresRecoveryHandoffResult {
    param([AllowNull()][AllowEmptyString()][string]$StatePath)
    $target = Get-PostgresRecoveryHandoffResultPath -StatePath $StatePath
    if (-not $target) { return $false }
    try {
        if (Test-Path -LiteralPath $target.Path -PathType Leaf) { Remove-Item -LiteralPath $target.Path -Force -ErrorAction Stop }
        return $true
    } catch {
        Write-Log 'Postgres recovery: the result file from the administrator window could not be removed.'
        return $false
    }
}

# The one message the original window shows for a valid result that is not
# Completed. UnfinishedRepairDetail (this window's read-only marker check)
# replaces "Nothing else was changed" with the manual-recovery guidance.
function Get-PostgresRecoveryHandoffMessage {
    param([Parameter(Mandatory)]$Result, [string]$UnfinishedRepairDetail = '')
    $whereStopped = if ($Result.StageReached -eq 'DatabaseBackupFailed') { 'The database backup could not be completed (see View Log).' } else { 'The rest of the PostgreSQL setup did not finish (see View Log).' }
    $nothingElse = if ($Result.NothingElseChanged -and [string]::IsNullOrWhiteSpace($UnfinishedRepairDetail)) { ' Nothing else was changed.' } else { '' }
    switch ([string]$Result.Outcome) {
        'StoppedUnexpectedError' {
            if ($Result.Operation -eq 'Reinitialize') {
                $text = 'The PostgreSQL data reset stopped in the administrator window because of an unexpected error (see View Log). Some selected game databases may already be reinitialized.'
            } elseif ($Result.Operation -eq 'Install') {
                $text = 'PostgreSQL setup stopped in the administrator window because of an unexpected error (see View Log). Check View Log before you choose PostgreSQL setup again.'
            } else {
                $text = 'The administrator window stopped because of an unexpected error (see View Log). TeknoParrot Manager cannot confirm what was changed. Check View Log before you try again.'
            }
        }
        default {
            if ($Result.StageReached -eq 'NotStarted') {
                $text = 'The administrator window stopped before it started the PostgreSQL setup (see View Log). The PostgreSQL password was not changed.'
            } elseif ($Result.Operation -eq 'Install') {
                $text = 'PostgreSQL setup did not finish in the administrator window (see View Log). Check View Log before you choose PostgreSQL setup again.'
            } elseif ($Result.Operation -eq 'Reinitialize') {
                $text = 'The PostgreSQL data reset did not finish in the administrator window (see View Log). Some selected game databases may already be reinitialized. The PostgreSQL password was not changed.'
            } else {
                $text = 'The PostgreSQL password was not changed. {0}{1}' -f $whereStopped, $nothingElse
            }
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($UnfinishedRepairDetail)) { $text = $text + ' ' + $UnfinishedRepairDetail.Trim() }
    return [pscustomobject]@{ Text = $text }
}

# Best effort only: asks Windows to bring this console window back to the
# front after the administrator window closed. Windows may refuse (focus
# rules), and a Windows Terminal host may ignore it; nothing depends on it.
function Request-TpmConsoleForeground {
    try {
        if (-not ('TpmConsoleForegroundNative' -as [type])) {
            Add-Type -ErrorAction Stop -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class TpmConsoleForegroundNative {
    [DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow();
    [DllImport("user32.dll")] [return: MarshalAs(UnmanagedType.Bool)] public static extern bool IsIconic(IntPtr hWnd);
    [DllImport("user32.dll")] [return: MarshalAs(UnmanagedType.Bool)] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
    [DllImport("user32.dll")] [return: MarshalAs(UnmanagedType.Bool)] public static extern bool SetForegroundWindow(IntPtr hWnd);
}
'@
        }
        $window = [TpmConsoleForegroundNative]::GetConsoleWindow()
        if ($window -eq [IntPtr]::Zero) { return $false }
        if ([TpmConsoleForegroundNative]::IsIconic($window)) { [void][TpmConsoleForegroundNative]::ShowWindow($window, 9) }
        return [bool][TpmConsoleForegroundNative]::SetForegroundWindow($window)
    } catch {
        return $false
    }
}

function Exit-PostgresRecoveryResume {
    param([Parameter(Mandatory)][string]$Message, [int]$ExitCode = 1, [switch]$UnexpectedError)
    $retryPath = $null
    $resumeState = $script:PostgresRecoveryResumeState
    # NoRetry marks a stop that a retry cannot fix (for example profiles that
    # need the user's choice in the main menu). After an unexpected error the
    # outcome is unknown, so no retry either.
    $retryForbidden = [bool]($UnexpectedError -or ($resumeState -and [bool]$resumeState.NoRetry))
    if ($resumeState -and $resumeState.ClaimPath -and -not $retryForbidden) {
        try {
            $retryPath = New-PostgresRecoveryRetryState -State $resumeState
            if (-not (Remove-PostgresRecoveryState -Path $resumeState.Path -ClaimPath $resumeState.ClaimPath)) {
                # Do not leave a password-bearing retry file behind that no message will tell the user about.
                [void](Remove-PostgresRecoveryState -Path $retryPath)
                $retryPath = $null
            }
        } catch {
            $retryPath = $null
        }
    } elseif ($resumeState -and $retryForbidden) {
        [void](Remove-PostgresRecoveryState -Path $resumeState.Path -ClaimPath $resumeState.ClaimPath)
    }
    if ($script:PostgresRecoveryStatus) {
        try {
            $recoveryActions = if ($retryForbidden) {
                @(@{ Id = 'Stop'; Label = 'Stop here and ask for help.' })
            } else {
                @(@{ Id = 'Retry'; Label = 'Try again. You will not need to type your password again.' }; @{ Id = 'Stop'; Label = 'Stop here.' })
            }
            [void](Set-TpmWorkflowFailure -Context $script:PostgresRecoveryStatus -FailureId 'postgres-resume-failure' -Message $Message -DataSafety 'PostgreSQL setup is not finished. Open View Log to see how far it got.' -RecoveryActions $recoveryActions)
        } catch {}
    }
    Write-Host ''
    Write-Host ('  ' + $Message) -ForegroundColor Red
    Write-Host '  PostgreSQL setup did not finish. Open View Log to see how far it got.' -ForegroundColor Yellow
    if ($retryPath) {
        Write-Host '  TeknoParrot Manager kept your place. Choose PostgreSQL setup again to carry on.' -ForegroundColor Yellow
        Write-Log 'Postgres recovery resume: stopped before completion; a fresh retry record was saved.'
    } else {
        Write-Host '  TeknoParrot Manager could not keep a retry for this repair. Start PostgreSQL setup again if it is still needed.' -ForegroundColor Yellow
        Write-Log 'Postgres recovery resume: stopped before completion; no retry state was retained.'
    }
    # This function only runs inside the elevated protected-resume child.
    # Never pause for input here: the parent TPM process is waiting on this
    # child and must regain control as soon as the protected attempt ends.
    if ($script:PostgresRecoveryStatus -and $script:PostgresRecoveryStatus.Failure) {
        try {
            [void](Acknowledge-TpmWorkflowFailure -Context $script:PostgresRecoveryStatus -FailureId 'postgres-resume-failure')
            [void](Stop-TpmWorkflowStatus -Context $script:PostgresRecoveryStatus -Reason 'PostgreSQL recovery stopped')
            [void](Close-TpmWorkflowStatus -Context $script:PostgresRecoveryStatus)
        } catch {}
    }
    try {
        $loggedReason = ConvertTo-PostgresRedactedText -Text $Message -Secrets @($(if ($resumeState) { [string]$resumeState.PasswordPlain } else { '' }))
        Write-Log ('Postgres recovery resume stopped: ' + $loggedReason)
    } catch {}
    # FIX39: report the result to the original window, then close this window by
    # itself. Exit code 0 after a verified result: Windows Terminal keeps a window
    # open after a non-zero exit until a key is pressed, and the original window
    # never treats exit code 0 alone as success (it needs a Completed result).
    $resultReported = $false
    try {
        $resultStatePath = if ($resumeState -and $resumeState.Path) { [string]$resumeState.Path } else { [string]$script:PostgresRecoveryResumeToken }
        $resultRecord = New-PostgresRecoveryHandoffResult -ResumeState $resumeState -RetryIssued ([bool]$retryPath) -UnexpectedError:$UnexpectedError
        $resultReported = [bool](Write-PostgresRecoveryHandoffResult -StatePath $resultStatePath -Result $resultRecord)
    } catch {
        $resultReported = $false
    }
    if ($resultReported) {
        Write-Host '  This window closes by itself in a few seconds. The original TeknoParrot Manager window shows the result.' -ForegroundColor DarkGray
        Start-Sleep -Seconds 3
        $ExitCode = 0
    }
    exit $ExitCode
}

function Exit-PostgresRecoveryResumeSuccess {
    param([Parameter(Mandatory)]$ResumeState)
    # The repair is already finished and verified. A leftover one-shot file must not turn it into "unfinished"; the original window tries the cleanup again and tells the user.
    if (-not (Remove-PostgresRecoveryState -Path $ResumeState.Path -ClaimPath $ResumeState.ClaimPath)) {
        Write-Log 'Postgres recovery resume: setup finished and was verified, but the one-time repair file could not be deleted here.'
    }
    # FIX39: the original window claims success only from this Completed result.
    $resultReported = $false
    try {
        $resultReported = [bool](Write-PostgresRecoveryHandoffResult -StatePath ([string]$ResumeState.Path) -Result (New-PostgresRecoveryHandoffResult -ResumeState $ResumeState -Completed))
    } catch {
        $resultReported = $false
    }
    if (-not $resultReported) { Write-Log 'Postgres recovery resume: setup finished, but the original window cannot confirm it because the result could not be written.' }
    if ($ResumeState.Operation -eq 'Recovery') {
        Write-Host '  PostgreSQL is fixed.' -ForegroundColor Green
        Write-Host '  TeknoParrot Manager verified the PostgreSQL password successfully.' -ForegroundColor Green
    } else {
        Write-Host '  PostgreSQL setup is complete. TeknoParrot Manager continued the repair automatically.' -ForegroundColor Green
    }
    # Protected resume is an elevated child process. Exit immediately
    # after verified completion so its window closes automatically and
    # the original TPM process can continue.
    exit 0
}


function Start-PostgresRecoveryAsAdministrator {
    param(
        [Parameter(Mandatory)][string]$ConfigPath,
        [Parameter(Mandatory)][string]$ScriptPath,
        [Parameter(Mandatory)][string]$TpRoot,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [ValidateSet('Install','Recovery','Reinitialize')]
        [string]$Operation = 'Recovery',
        [string]$PasswordPlain = '',
        [string]$SelectionPlanJson = '',
        [string]$SelectionPlanHash = '',
        # FIX39: receives the shown result of the administrator window (Outcome,
        # Text) when that window reported one and did not complete; stays $null
        # otherwise, so callers keep their own fallback.
        [ref]$HandoffReport
    )
    $statePath = $null
    $attemptId = 1
    $makeArguments = {
        param([string]$Token)
        $items = @('-NoLogo', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $ScriptPath, '-PostgresRecoveryResumeToken', $Token)
        return (($items | ForEach-Object { ConvertTo-PostgresNativeArgument -Value ([string]$_) }) -join ' ')
    }
    try {
        $statePath = New-PostgresRecoveryState -ConfigPath $ConfigPath -ScriptPath $ScriptPath -TpRoot $TpRoot -UserProfilesDir $UserProfilesDir -Operation $Operation -PasswordPlain $PasswordPlain -SelectionPlanJson $SelectionPlanJson -SelectionPlanHash $SelectionPlanHash
        $hostName = if ($PSVersionTable.PSEdition -eq 'Core') { 'pwsh.exe' } else { 'powershell.exe' }
        $hostPath = Join-Path $PSHOME $hostName
        if (-not (Test-Path -LiteralPath $hostPath -PathType Leaf)) { throw 'PowerShell host was not found.' }
        $argumentString = & $makeArguments $statePath
        $stateIssuedAt = Get-Date
        $unusedRounds = 0
        $scriptAtIssue = ''
        try { $scriptAtIssue = (Get-FileHash -LiteralPath $ScriptPath -Algorithm SHA256 -ErrorAction Stop).Hash } catch { $scriptAtIssue = '' }
    } catch {
        Write-Host '  TeknoParrot Manager could not prepare the automatic repair. No changes were made.' -ForegroundColor Red
        Write-Log 'Postgres recovery: protected UAC handoff could not be prepared.'
        [void](Remove-PostgresRecoveryState -Path $statePath)
        return $false
    } finally {
        $PasswordPlain = $null
        [GC]::Collect()
    }

    while ($true) {
        Write-Host '  TeknoParrot Manager will ask Windows for permission, then continue this setup automatically.' -ForegroundColor Cyan
        if ($HandoffReport) { $HandoffReport.Value = $null }
        $childExit = $null
        $handoff = $null
        $lastRoundCancelled = $false
        try {
            $childRun = Invoke-TpmProgressGroup -Title 'PostgreSQL elevated setup' -Action {
                # One long silent wait: the Windows permission question, then the whole administrator window. "Still working", never "stalled".
                Write-TpmCompactExtractionProgress -Phase Installing -Label 'PostgreSQL administrator window' -Current 0 -Total 0 -LongStep
                try {
                    # FIX39: no -Wait. Start-Process -Wait also waits for every process the
                    # child started, so a leftover grandchild could keep this window waiting
                    # after the administrator window had already closed.
                    $elevatedChild = Start-Process -FilePath $hostPath -ArgumentList $argumentString -Verb RunAs -PassThru -ErrorAction Stop
                } catch {
                    $launchException = $_.Exception
                    $uacWasCancelled = $false
                    while ($null -ne $launchException) {
                        if ($launchException.HResult -eq -2147023673 -or ($launchException -is [System.ComponentModel.Win32Exception] -and $launchException.NativeErrorCode -eq 1223)) {
                            $uacWasCancelled = $true
                            break
                        }
                        $launchException = $launchException.InnerException
                    }
                    if ($uacWasCancelled) {
                        return [pscustomobject]@{ Outcome = 'Cancelled'; Succeeded = $false; Result = $null }
                    }
                    throw
                }
                if ($null -eq $elevatedChild) { throw 'The PostgreSQL administrator window could not be observed.' }
                # Waits for this one process only; short slices keep Ctrl+C working.
                while (-not $elevatedChild.WaitForExit(500)) { }
                $elevatedExitProperty = $elevatedChild.PSObject.Properties['ExitCode']
                $processSucceeded = $false
                if ($null -ne $elevatedExitProperty) {
                    if ($null -ne $elevatedExitProperty.Value) {
                        $processSucceeded = ([int]$elevatedExitProperty.Value -eq 0)
                    }
                }
                [pscustomobject]@{ Succeeded = $processSucceeded; Result = $elevatedChild }
            }
            if ([string]$childRun.Outcome -eq 'Cancelled') {
                Write-Host '  The Windows permission request was canceled. The administrator setup did not run.' -ForegroundColor Yellow
                $lastRoundCancelled = $true
                Write-Log 'Postgres recovery: user canceled the Windows elevation request.'
            } else {
                $child = $childRun.Result
                $exitCodeProperty = if ($null -ne $child) { $child.PSObject.Properties['ExitCode'] } else { $null }
                if ($null -eq $exitCodeProperty) {
                    throw 'The PostgreSQL administrator window did not return a verifiable exit code.'
                }
                $exitCode = $exitCodeProperty.Value
                if ($null -eq $exitCode) {
                    throw 'The PostgreSQL administrator window did not return a verifiable exit code.'
                }
                $childExit = [int]$exitCode
                [void](Request-TpmConsoleForeground)
                Write-Host ''
                $childProcessId = 0
                $childIdProperty = $child.PSObject.Properties['Id']
                if ($null -ne $childIdProperty -and $null -ne $childIdProperty.Value) { $childProcessId = [int]$childIdProperty.Value }
                $handoff = Read-PostgresRecoveryHandoffResult -StatePath $statePath -ChildProcessId $childProcessId
                Write-Log ('Postgres recovery: administrator window exit code {0}; result {1}{2}.' -f $childExit, $handoff.Reason, $(if ($handoff.Valid) { ('; Outcome=' + $handoff.Result.Outcome + '; Stage=' + $handoff.Result.StageReached + '; BackupSucceeded=' + [string]$handoff.Result.BackupSucceeded) } else { '' }))
                if ($childExit -eq 0 -and [bool]$childRun.Succeeded -and $handoff.Valid -and $handoff.Result.Outcome -eq 'Completed') {
                    [void](Remove-PostgresRecoveryHandoffResult -StatePath $statePath)
                    if (-not (Remove-PostgresRecoveryState -Path $statePath -ClaimPath ($statePath + '.claim'))) {
                        # Setup finished and was verified: report it as finished, with a plain note about the leftover file.
                        Write-Host '  PostgreSQL setup finished. One small temporary file could not be deleted. It is not needed any more, so you can delete it yourself:' -ForegroundColor Yellow
                        foreach ($leftoverFile in @($statePath, ($statePath + '.claim'))) { if (Test-Path -LiteralPath $leftoverFile -PathType Leaf) { Write-Host ('    ' + $leftoverFile) -ForegroundColor Yellow } }
                        Write-Log 'Postgres recovery: setup finished and was verified; the consumed one-time recovery file could not be deleted.'
                    }
                    return $true
                }
                if ($handoff.Valid -and $handoff.Result.Outcome -ne 'Completed') {
                    # FIX39: one accurate message from what the administrator window reported.
                    # Read-only: an unfinished repair (temporary trust rule or marker) means
                    # something else may still be changed; say so instead of "Nothing else".
                    $unfinishedRepairDetail = ''
                    try {
                        $markerAfterChild = Get-PostgresTrustRuleMarkerState -ReadOnly
                        if ([string]$markerAfterChild.State -ne 'None') {
                            $script:PostgresTrustRuleMarkerState = $markerAfterChild
                            $unfinishedRepairDetail = Get-PostgresManualRecoveryDetail
                            Write-Log ('Postgres recovery: ' + (Get-PostgresManualRecoveryTechnicalDetail))
                        }
                    } catch {
                        $unfinishedRepairDetail = 'TeknoParrot Manager could not check whether the PostgreSQL repair left anything unfinished; check View Log before you try again.'
                    }
                    $handoffMessage = Get-PostgresRecoveryHandoffMessage -Result $handoff.Result -UnfinishedRepairDetail $unfinishedRepairDetail
                    Write-Host ('  ' + $handoffMessage.Text) -ForegroundColor Yellow
                    if ($HandoffReport) { $HandoffReport.Value = [pscustomobject]@{ Outcome = $handoff.Result.Outcome; Text = $handoffMessage.Text } }
                    [void](Remove-PostgresRecoveryHandoffResult -StatePath $statePath)
                } elseif ($childExit -eq 0 -or $handoff.Valid) {
                    Write-Host '  The administrator window closed, but TeknoParrot Manager could not read a valid result from it, so it cannot confirm what finished. View Log shows the steps that ran.' -ForegroundColor Red
                } else {
                    Write-Host '  Windows allowed TeknoParrot Manager to continue, but PostgreSQL setup did not finish.' -ForegroundColor Red
                }
            }
        } catch {
            Write-Host '  Windows did not give TeknoParrot Manager permission to continue, or the result of the administrator window could not be checked.' -ForegroundColor Yellow
            Write-Log 'Postgres recovery: UAC approval was unavailable/declined or the child process result was unverifiable.'
        }
        $nextState = Find-PostgresRecoveryRetryState -PreviousStatePath $statePath `
            -ExpectedConfigPath $ConfigPath -ExpectedScriptPath $ScriptPath -ExpectedTpRoot $TpRoot `
            -ExpectedUserProfilesDir $UserProfilesDir -ExpectedParentPid $PID -PreviousAttemptId $attemptId
        # An unexpected error leaves the outcome unknown, so no retry is offered after it.
        if ($nextState -and $handoff -and $handoff.Valid -and $handoff.Result.Outcome -eq 'StoppedUnexpectedError') {
            [void](Remove-PostgresRecoveryState -Path $nextState)
            Write-Log 'Postgres recovery: a saved retry was found after an unexpected error; it was removed and not offered.'
            $nextState = $null
        }
        $retryPossible = $false
        if ($nextState) {
            $statePath = $nextState
            $attemptId++
            $stateIssuedAt = Get-Date
            $argumentString = & $makeArguments $statePath
            Write-Host '  TeknoParrot Manager prepared a fresh retry. Your password was not requested again.' -ForegroundColor Yellow
            $retryPossible = $true
        } elseif (Test-Path -LiteralPath $statePath -PathType Leaf) {
            $unusedRounds++
            if ($unusedRounds -ge 2) {
                # The administrator window twice left the request unread. Say why the last round ended, so the user is not blamed for a cause that did not happen.
                [void](Remove-PostgresRecoveryState -Path $statePath -ClaimPath ($statePath + '.claim'))
                $adminHint = 'If your Windows account is not an administrator, close TeknoParrot Manager and start it again with "Run as administrator".'
                if ($lastRoundCancelled) {
                    $stopCause = 'the last Windows permission box was canceled'
                    $stopText = 'PostgreSQL setup did not start because the Windows permission box was canceled. Nothing was changed. Choose PostgreSQL setup again and click Yes when Windows asks. '
                } elseif ($handoff -and $handoff.Valid -and $handoff.Result.Outcome -ne 'Completed') {
                    $stopCause = 'the administrator window reported a result and put the request back'
                    $stopText = 'PostgreSQL setup did not finish. The reason is shown above. ' + $(if ($handoff.Result.PSObject.Properties['NothingElseChanged'] -and $handoff.Result.NothingElseChanged -eq $true) { 'Nothing was changed.' } else { 'Some things may already have been changed (see View Log).' }) + ' Fix that, then choose PostgreSQL setup again. '
                } else {
                    $stopCause = 'possibly a different Windows account approved the prompt'
                    $stopText = 'PostgreSQL setup did not start. This usually happens when the Windows permission box is approved with a different account than the one running TeknoParrot Manager. Nothing was changed. Choose PostgreSQL setup again and approve the Windows box with the same account, without switching accounts. '
                }
                Write-Host ('  ' + $stopText + $adminHint) -ForegroundColor Yellow
                Write-Log ('Postgres recovery: the administrator window twice left the saved repair request unread (' + $stopCause + '); the request was removed and no further retry was offered.')
                return $false
            }
            $recordExpired = (((Get-Date) - $stateIssuedAt).TotalMinutes -ge 4.5)
            # An old request or a changed script is refused by the administrator window every time, so asking again would only repeat the Windows prompt.
            $scriptNow = ''
            try { $scriptNow = (Get-FileHash -LiteralPath $ScriptPath -Algorithm SHA256 -ErrorAction Stop).Hash } catch { $scriptNow = '' }
            $scriptChanged = (-not [string]::IsNullOrEmpty($scriptAtIssue) -and $scriptNow -ne $scriptAtIssue)
            if ($recordExpired -or $scriptChanged) {
                [void](Remove-PostgresRecoveryState -Path $statePath -ClaimPath ($statePath + '.claim'))
                Write-Host '  The saved repair request cannot be used any more. Nothing was changed. Choose PostgreSQL setup again.' -ForegroundColor Yellow
                Write-Log 'Postgres recovery: the unused repair request was expired or no longer matches this script; it was removed and no retry was offered.'
                return $false
            }
            Write-Host '  Nothing was changed by the failed automatic repair. The saved repair information is still available.' -ForegroundColor Yellow
            $retryPossible = $true
        }
        if (-not $retryPossible) {
            # FIX39: the protected request was used and no fresh one exists, so a
            # retry cannot work. Never offer "Try again" for it.
            [void](Remove-PostgresRecoveryState -Path $statePath -ClaimPath ($statePath + '.claim'))
            if (-not ($handoff -and $handoff.Valid)) {
                Write-Host '  TeknoParrot Manager used this repair request and cannot retry it. Check View Log to see which steps ran, then choose PostgreSQL setup again if it is still needed.' -ForegroundColor Yellow
            }
            Write-Log 'Postgres recovery: the repair request was used and no fresh retry exists; no retry was offered.'
            return $false
        }
        $retry = Read-TpmYesNo -Prompt '  Try again? (Y/N)'
        if ($retry -ne 'Y') {
            [void](Remove-PostgresRecoveryState -Path $statePath -ClaimPath ($statePath + '.claim'))
            return $false
        }
        if (-not (Test-Path -LiteralPath $statePath -PathType Leaf)) {
            [void](Remove-PostgresRecoveryState -Path $statePath -ClaimPath ($statePath + '.claim'))
            Write-Host '  The repair request is no longer available, so TeknoParrot Manager did not retry. Choose PostgreSQL setup again if it is still needed.' -ForegroundColor Yellow
            return $false
        }
    }
}

# Decrypts a SecureString to plaintext only as long as needed, then
# explicitly zeroes and frees the unmanaged memory holding it -- letting GC
# eventually collect a managed string isn't the same as zeroing the bytes,
# and a password is worth being careful about even briefly. Also used by
# the DPAPI-encrypted config storage below to decrypt back to plaintext
# only at the point of use.
function ConvertFrom-SecureStringPlain {
    param([System.Security.SecureString]$Secure)
    $ptr = [Runtime.InteropServices.Marshal]::SecureStringToGlobalAllocUnicode($Secure)
    try {
        return [Runtime.InteropServices.Marshal]::PtrToStringUni($ptr)
    } finally {
        [Runtime.InteropServices.Marshal]::ZeroFreeGlobalAllocUnicode($ptr)
    }
}

# Encrypts a plaintext password for storage in config.json via Windows
# DPAPI (ConvertFrom-SecureString with no -Key ties the result to the
# current Windows user + machine) -- the inverse of
# ConvertFrom-SecureStringPlain. Used to persist the Postgres superuser
# password after a successful install; nothing else in this script has
# ever needed to store a secret before this feature.
function ConvertTo-PostgresEncryptedPassword {
    param([string]$PlainText)
    $secure = ConvertTo-SecureString -String $PlainText -AsPlainText -Force
    return ($secure | ConvertFrom-SecureString)
}

# Accepts two SecureString entries and returns plaintext only to the immediate
# caller. The entries are cleared on every path; the prompt never echoes the
# approved password and no retry detail includes it. -RejectDoubleQuote asks
# again for a password containing a double quote (FIX36 S6: the PostgreSQL MSI
# property syntax would otherwise set a different password than TPM saves).
# -RequireSafeNewPassword asks again for a new password TPM cannot set safely
# (FIX36B S6, Get-PostgresNewPasswordProblem).
function Read-ConfirmedPostgresPassword {
    param([string]$WhatFor, [switch]$RejectDoubleQuote, [switch]$RequireSafeNewPassword)
    while ($true) {
        $first = $null; $second = $null; $firstPlain = $null; $secondPlain = $null
        $quoteRejected = $false
        $unsafeProblem = $null
        try {
            if ($script:ActiveTpmWorkflowStatus) { Clear-TpmWorkflowFooter -Context $script:ActiveTpmWorkflowStatus }
            if (Get-Command -Name Suspend-TpmProgressLine -ErrorAction SilentlyContinue) { Suspend-TpmProgressLine }
            $first = Read-Host "  Enter $WhatFor (or just press Enter to go back)" -AsSecureString
            $firstPlain = ConvertFrom-SecureStringPlain $first
            if ([string]::IsNullOrEmpty($firstPlain)) { return $null }
            $second = Read-Host '  Re-enter the same password to confirm' -AsSecureString
            $secondPlain = ConvertFrom-SecureStringPlain $second
            if ([string]::Equals($firstPlain, $secondPlain, [System.StringComparison]::Ordinal)) {
                if ($RequireSafeNewPassword) { $unsafeProblem = Get-PostgresNewPasswordProblem -Password $firstPlain }
                if ($RejectDoubleQuote -and $firstPlain.IndexOf([char]34) -ge 0) {
                    $quoteRejected = $true
                } elseif (-not $unsafeProblem) {
                    $approved = $firstPlain
                    return $approved
                }
            }
        } finally {
            if ($first) { $first.Dispose() }
            if ($second) { $second.Dispose() }
            $first = $null
            $second = $null
            $firstPlain = $null
            $secondPlain = $null
            if (Get-Command -Name Resume-TpmProgressLine -ErrorAction SilentlyContinue) { Resume-TpmProgressLine }
        }
        if ($quoteRejected) {
            Write-Host '  This password cannot contain a double quote ("). Please choose a password without one.' -ForegroundColor Yellow
        } elseif ($unsafeProblem) {
            Write-Host ('  TeknoParrot Manager cannot use that password. ' + $unsafeProblem + ' Please choose another one.') -ForegroundColor Yellow
        } else {
            Write-Host "  Those two entries did not match -- let's try again (or press Enter to go back)." -ForegroundColor Yellow
        }
    }
}

# FIX95 (B1, owner rule R4): TeknoParrot Manager no longer resets the postgres
# password. The old reset put "host all postgres 127.0.0.1/32 trust" into
# pg_hba.conf and started PostgreSQL; a crash, a killed window or a power cut
# could leave that rule in place, and then any program on this PC could log in
# as postgres without a password. PostgreSQL 8.3 refuses single-user mode from
# an administrator account, so no reset without that rule is possible here.
# This screen says nothing was changed and what to do; the technical reason and
# the manual steps are under Details (and in the log). EnterKey is the menu key
# that types the existing password on the calling screen (F or P).
function Show-PostgresPasswordResetUnavailable {
    param([Parameter(Mandatory)][ValidateSet('F', 'P')][string]$EnterKey)
    $hbaPath = Join-Path (Join-Path ([string]$script:PostgresInstallDir) 'data') 'pg_hba.conf'
    $psqlPath = Join-Path ([string]$script:PostgresBinDir) 'psql.exe'
    $whyBlock = @{ Heading = 'Why TeknoParrot Manager does not reset the password'; Lines = @(
        'What happened: PostgreSQL is running and it rejected the postgres password.'
        'Old method: Earlier versions added "host all postgres 127.0.0.1/32 trust" to pg_hba.conf and restarted PostgreSQL.'
        'Risk: A crash, a closed window or a power cut could leave that line in place. Then any program on this PC can log in as postgres without a password.'
        'Safer way: PostgreSQL 8.3 single-user mode refuses to run from an administrator account, so it cannot be used here.'
    ) }
    $stepsBlock = @{ Heading = 'How to reset the postgres password yourself'; Lines = @(
        ('Step 1: Stop the Windows service {0}.' -f $script:PostgresServiceName)
        ('Step 2: Copy {0} to a safe place.' -f $hbaPath)
        'Step 3: Add this line above all other lines in pg_hba.conf: host all postgres 127.0.0.1/32 trust'
        ('Step 4: Start the service. Run "{0}" -h 127.0.0.1 -p 5432 -U postgres -d postgres' -f $psqlPath)
        'Step 5: Type \password postgres and enter the new password twice. Then type \q.'
        'Step 6: Stop the service. Put your copy of pg_hba.conf back. Start the service.'
        ('Step 7: Open PostgreSQL setup again, choose {0} and type the new password.' -f $EnterKey)
        'Warning: Do step 6 straight away. While the trust line is there, any program on this PC can log in as postgres.'
    ) }
    Write-TpmOutcome -Title 'TeknoParrot Manager cannot reset the PostgreSQL password for you.' -Status Attention `
        -NotChanged 'PostgreSQL, its password and your games.' `
        -Needs @('A reset by TeknoParrot Manager could leave PostgreSQL open without a password. So it is turned off.') `
        -Next ('If you know the password, choose {0} and type it. If nobody knows it, press D to see how to reset it yourself.' -f $EnterKey) `
        -DetailBlocks @($whyBlock, $stepsBlock)
}

# Option 11 on an existing PostgreSQL install (FIX36 B1/B2/B3, FIX95 B1, owner
# rules R1-R4). Decides which postgres password setup uses and never changes
# PostgreSQL:
#  1. The saved password is checked first and used when PostgreSQL accepts it.
#  2. Otherwise the first and default offer is [F]: type the EXISTING password.
#     TPM checks it, saves it and reads it back. PostgreSQL is not changed.
#  3. [X] is offered only after PostgreSQL, verified running, positively
#     rejected a password in this run. It explains that TeknoParrot Manager
#     cannot reset the password (Show-PostgresPasswordResetUnavailable).
#  4. While PostgreSQL cannot be reached only "check again" and "back" exist.
# Returns Outcome Ready (PasswordPlain set) or Back.
function Resolve-PostgresSetupPassword {
    param(
        [Parameter(Mandatory)]$StatusContext
    )
    $savedPlain = $null
    $secure = $null
    $typedPlain = $null
    try {
        $savedState = 'Missing'
        if (-not [string]::IsNullOrWhiteSpace([string]$script:postgresSuperPasswordEncrypted)) {
            try {
                $secure = ConvertTo-SecureString -String ([string]$script:postgresSuperPasswordEncrypted)
                $savedPlain = ConvertFrom-SecureStringPlain $secure
                $savedState = if ([string]::IsNullOrEmpty($savedPlain)) { 'Unreadable' } else { 'Readable' }
            } catch {
                $savedState = 'Unreadable'
                Write-Log 'Postgres setup: the saved PostgreSQL password could not be decrypted for this Windows user; nothing was changed.'
            } finally {
                $secure = $null
            }
        }
        $lastProbe = $null
        $lastProbeOfSaved = $false
        if ($savedState -eq 'Readable') {
            $lastProbe = Invoke-PostgresPasswordProbeSafely -SuperPasswordPlain $savedPlain
            $lastProbeOfSaved = $true
            if ($lastProbe.State -eq 'Authenticated') {
                return [pscustomobject]@{ Outcome = 'Ready'; PasswordPlain = $savedPlain }
            }
            Write-Log ('Postgres setup: saved password check result={0}; reason={1}; no password decision was made from a failed check.' -f $lastProbe.State, $lastProbe.Reason)
        }
        while ($true) {
            Write-Host ''
            Write-Host '  PostgreSQL needs attention: the saved PostgreSQL password cannot be used right now.' -ForegroundColor Yellow
            $serviceStatus = Get-PostgresServiceStatusText
            if ($serviceStatus -ne 'Running') {
                $serviceProbe = [pscustomobject]@{ State = 'Unavailable'; Reason = 'ServiceNotRunning'; ServiceStatus = $serviceStatus; Detail = '' }
                Write-Host ('  ' + (Get-PostgresProbeExplanation -Probe $serviceProbe)) -ForegroundColor Yellow
                Write-Host '  TeknoParrot Manager did not change anything. Start PostgreSQL, wait a few seconds, then choose C to check again.' -ForegroundColor Yellow
                Write-Host '  [C] Check again'
                Write-Host '  [B] Back to main menu. Nothing is changed.'
                $waitChoice = Read-TpmChoice -Prompt '  Choice, default C' -Choices @('C', 'B') -Default 'C'
                if ($waitChoice -eq 'B') {
                    Write-Host '  Nothing was changed. The PostgreSQL setup was not completed.' -ForegroundColor Yellow
                    return [pscustomobject]@{ Outcome = 'Back'; PasswordPlain = $null }
                }
                if ($savedState -eq 'Readable') {
                    $lastProbe = Invoke-PostgresPasswordProbeSafely -SuperPasswordPlain $savedPlain
                    $lastProbeOfSaved = $true
                    if ($lastProbe.State -eq 'Authenticated') {
                        Write-Host '  PostgreSQL accepted the saved password.' -ForegroundColor Green
                        return [pscustomobject]@{ Outcome = 'Ready'; PasswordPlain = $savedPlain }
                    }
                } else {
                    $lastProbe = $null
                }
                continue
            }
            if ($savedState -eq 'Missing') {
                Write-Host '  TeknoParrot Manager has no saved PostgreSQL password yet.' -ForegroundColor Yellow
            } elseif ($savedState -eq 'Unreadable') {
                Write-Host '  TeknoParrot Manager could not read its saved PostgreSQL password. It may have been saved by another Windows user account.' -ForegroundColor Yellow
            } elseif ($lastProbeOfSaved -and $lastProbe -and $lastProbe.State -eq 'Rejected') {
                Write-Host '  PostgreSQL is running and it rejected the saved PostgreSQL password.' -ForegroundColor Yellow
            }
            if ($lastProbe -and $lastProbe.State -eq 'Unavailable') {
                Write-Host ('  ' + (Get-PostgresProbeExplanation -Probe $lastProbe)) -ForegroundColor Yellow
                $firstDetailLine = @(([string]$lastProbe.Detail) -split '\r?\n' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1)
                if ($firstDetailLine.Count -gt 0) {
                    Write-Host '  PostgreSQL gave a reason. The exact reply is in View Log.' -ForegroundColor DarkGray
                    Write-Log ('Postgres password check: message from PostgreSQL: ' + $firstDetailLine[0].Trim())
                }
            }
            $passwordRejected = [bool]($lastProbe -and $lastProbe.State -eq 'Rejected')
            $checkAllowed = [bool]($savedState -eq 'Readable' -and $lastProbe -and $lastProbe.State -eq 'Unavailable')
            Write-Host '  Existing PostgreSQL data is preserved in every choice below.' -ForegroundColor DarkGray
            Write-Host '  [F] Enter the existing PostgreSQL password (recommended). TeknoParrot Manager checks it and saves it. Nothing in PostgreSQL is changed.'
            if ($passwordRejected) { Write-Host '  [X] I do not know the password' }
            if ($checkAllowed) { Write-Host '  [C] Check the saved password again' }
            Write-Host '  [B] Back to main menu. Nothing is changed.'
            $menuChoices = @('F')
            if ($passwordRejected) { $menuChoices += 'X' }
            if ($checkAllowed) { $menuChoices += 'C' }
            $menuChoices += 'B'
            $choice = Read-TpmChoice -Prompt '  Choice, default F' -Choices $menuChoices -Default 'F'
            if ($choice -eq 'B') {
                Write-Host '  Nothing was changed. The PostgreSQL setup was not completed.' -ForegroundColor Yellow
                return [pscustomobject]@{ Outcome = 'Back'; PasswordPlain = $null }
            }
            if ($choice -eq 'C') {
                $lastProbe = Invoke-PostgresPasswordProbeSafely -SuperPasswordPlain $savedPlain
                $lastProbeOfSaved = $true
                if ($lastProbe.State -eq 'Authenticated') {
                    Write-Host '  PostgreSQL accepted the saved password.' -ForegroundColor Green
                    return [pscustomobject]@{ Outcome = 'Ready'; PasswordPlain = $savedPlain }
                }
                continue
            }
            if ($choice -eq 'F') {
                Write-Host '  Type the password the postgres database user has now. TeknoParrot Manager will not change it.' -ForegroundColor Cyan
                Write-Host '  The password is masked and will not be displayed, logged, or placed in command-line arguments.' -ForegroundColor DarkGray
                [void](Set-TpmWorkflowWaiting -Context $StatusContext -Message 'Enter and confirm the existing PostgreSQL password.' -UserAction 'Enter the password twice')
                try {
                    $typedPlain = Read-ConfirmedPostgresPassword 'the existing PostgreSQL password'
                } finally {
                    [void](Resume-TpmWorkflowStatus -Context $StatusContext)
                }
                if ($null -eq $typedPlain) {
                    Write-Host '  No password entered. Nothing was changed or saved.' -ForegroundColor Yellow
                    continue
                }
                $typedProbe = Invoke-PostgresPasswordProbeSafely -SuperPasswordPlain $typedPlain
                if ($typedProbe.State -eq 'Authenticated') {
                    $saveResult = Save-PostgresVerifiedCredential -PasswordPlain $typedPlain
                    if ($saveResult.Saved) {
                        Write-Host '  PostgreSQL accepted that password. TeknoParrot Manager saved it securely and checked the saved copy. Nothing in PostgreSQL was changed.' -ForegroundColor Green
                    } else {
                        Write-Host '  PostgreSQL accepted that password, but TeknoParrot Manager could not save it yet. TeknoParrot Manager tries again at the end of setup; if that fails too, TeknoParrot Manager will ask for it next time. Nothing in PostgreSQL was changed.' -ForegroundColor Yellow
                    }
                    $readyPassword = $typedPlain
                    $typedPlain = $null
                    return [pscustomobject]@{ Outcome = 'Ready'; PasswordPlain = $readyPassword }
                }
                $typedPlain = $null
                $lastProbe = $typedProbe
                $lastProbeOfSaved = $false
                if ($typedProbe.State -eq 'Rejected') {
                    Write-Host '  PostgreSQL rejected that password. Nothing was changed or saved.' -ForegroundColor Red
                } else {
                    Write-Host '  TeknoParrot Manager could not check that password. Nothing was changed or saved.' -ForegroundColor Yellow
                }
                Write-Log ('Postgres setup: typed existing password check result={0}; reason={1}; nothing was saved.' -f $typedProbe.State, $typedProbe.Reason)
                continue
            }
            # $choice is 'X': offered only after a positive rejection by a running server.
            Show-PostgresPasswordResetUnavailable -EnterKey 'F'
        }
    } finally {
        $savedPlain = $null
        $typedPlain = $null
        $secure = $null
    }
}

# Reports whether PostgreSQL's own installation registry record -- written by
# the EnterpriseDB-based installer under \Installations\<install-id> -- exists
# and whether it points somewhere other than the expected install directory.
# Get-PostgresPartialInstallInventory below lists an existing record as a
# leftover the owner must review; it is never used as ownership evidence and
# never authorizes any removal.
#
# The exact install-id subkey name under \Installations\ (the issue
# suggests "postgresql-8.3") is NOT assumed -- this dev machine has no real
# PostgreSQL install to verify that against (same constraint as the
# project's "no game data on this machine" note), so every existing
# install-id subkey is checked rather than guessing one exact name. "Base
# Directory" is the documented value name EnterpriseDB's installer writes
# there; if that's ever wrong on a real system, Get-ItemProperty simply
# returns nothing for it, which still degrades safely to "no additional
# information" rather than a false positive.
function Test-PostgresInstallationsRegistry {
    param([string]$ExpectedInstallDir)
    $expected = $ExpectedInstallDir.TrimEnd('\')
    $roots = @(
        "HKLM:\SOFTWARE\PostgreSQL\Installations\*",
        "HKLM:\SOFTWARE\WOW6432Node\PostgreSQL\Installations\*"
    )
    $entries = @(Get-ItemProperty -Path $roots -ErrorAction SilentlyContinue |
                     Where-Object { $_.'Base Directory' })
    if ($entries.Count -eq 0) {
        return [pscustomobject]@{ HasRecord = $false; Mismatch = $false }
    }
    # -ieq (case-insensitive EXACT equality), not -like -- this is a literal
    # path comparison, not a wildcard pattern match. Using -like here would
    # treat any `[`, `]`, or `*` in either path as wildcard syntax.
    $matching = @($entries | Where-Object { $_.'Base Directory'.TrimEnd('\') -ieq $expected })
    return [pscustomobject]@{ HasRecord = $true; Mismatch = ($matching.Count -eq 0) }
}

# Read-only inventory of PostgreSQL 8.3 leftovers that would collide with a
# fresh install: an installed-program entry, the pgsql service, the install
# folder, PostgreSQL's installation registration, the local 'postgres'
# account, and 'postgres' user profiles. A failed install can leave these
# behind, but so can an unrelated PostgreSQL install that uses the same names.
# TPM keeps no per-object ownership record for any of them, and a matching
# name or location is not proof that TPM created an object, so this function
# NEVER uninstalls, stops, or deletes anything. Install-Postgres83 refuses to
# install while any object is present and tells the owner what was found and
# how to review it.
function Get-PostgresPartialInstallInventory {
    $inventoryProgressStarted = Get-Date
    $inventoryProgressCurrent = 0
    $inventoryProgressLabel = 'PostgreSQL leftover check'
    $inventoryCompleted = $false
    $objects = New-Object System.Collections.Generic.List[object]
    try {
        Write-TpmCompactExtractionProgress -Phase Checking -Label $inventoryProgressLabel -Current $inventoryProgressCurrent -Total 0 -StartedAt $inventoryProgressStarted
        Write-Log "Postgres: checking for leftovers of an earlier PostgreSQL 8.3 install before a fresh attempt (read-only)."

        $uninstallKeys = @(
            "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*",
            "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*"
        )
        foreach ($entry in @(Get-ItemProperty -Path $uninstallKeys -ErrorAction SilentlyContinue)) {
            $inventoryProgressCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label $inventoryProgressLabel -Current $inventoryProgressCurrent -Total 0 -StartedAt $inventoryProgressStarted
            if ([string]$entry.DisplayName -like "PostgreSQL*8.3*") {
                $location = if ($entry.InstallLocation) { [string]$entry.InstallLocation } else { 'unknown location' }
                [void]$objects.Add([pscustomobject]@{ Kind = 'InstalledProgram'; Description = ("Installed program '{0}' ({1})" -f [string]$entry.DisplayName, $location); PlainDescription = ("The PostgreSQL program '{0}' ({1})" -f [string]$entry.DisplayName, $location) })
            }
        }

        $expectedInstallDir = $script:PostgresInstallDir.TrimEnd('\')
        $registration = Test-PostgresInstallationsRegistry -ExpectedInstallDir $expectedInstallDir
        # Only a record that points at TPM's own PostgreSQL folder is a leftover; another PostgreSQL version registers under its own folder and cannot collide.
        if ($registration.HasRecord -and -not $registration.Mismatch) {
            [void]$objects.Add([pscustomobject]@{ Kind = 'InstallationRegistration'; Description = 'PostgreSQL installation registration in the Windows registry (HKLM\SOFTWARE\PostgreSQL\Installations)'; PlainDescription = 'A PostgreSQL entry in the Windows settings' })
        }

        foreach ($svc in @(Get-Service -Name $script:PostgresServiceName -ErrorAction SilentlyContinue)) {
            $inventoryProgressCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label $inventoryProgressLabel -Current $inventoryProgressCurrent -Total 0 -StartedAt $inventoryProgressStarted
            [void]$objects.Add([pscustomobject]@{ Kind = 'Service'; Description = ("Windows service '{0}' ({1})" -f [string]$svc.Name, [string]$svc.Status); PlainDescription = ("The PostgreSQL background service (it is {0})" -f [string]$svc.Status) })
        }

        if (Test-Path -LiteralPath $script:PostgresInstallDir) {
            [void]$objects.Add([pscustomobject]@{ Kind = 'Folder'; Description = ("Folder '{0}'" -f $script:PostgresInstallDir); PlainDescription = ("The PostgreSQL folder '{0}'" -f $script:PostgresInstallDir) })
        }

        $pgUser = Get-LocalUser -Name "postgres" -ErrorAction SilentlyContinue
        if ($pgUser) {
            [void]$objects.Add([pscustomobject]@{ Kind = 'WindowsAccount'; Description = ("Windows account 'postgres' (SID {0})" -f [string]$pgUser.SID); PlainDescription = "The Windows user account named 'postgres'" })
        }

        $profileListPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList"
        $profilePaths = New-Object System.Collections.Generic.List[string]
        foreach ($profileKey in @(Get-ChildItem -Path $profileListPath -ErrorAction SilentlyContinue)) {
            $inventoryProgressCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label $inventoryProgressLabel -Current $inventoryProgressCurrent -Total 0 -StartedAt $inventoryProgressStarted
            $imagePath = (Get-ItemProperty -Path $profileKey.PSPath -Name ProfileImagePath -ErrorAction SilentlyContinue).ProfileImagePath
            if ($imagePath -and ([string]$imagePath -like "*\postgres")) {
                [void]$profilePaths.Add([string]$imagePath)
                [void]$objects.Add([pscustomobject]@{ Kind = 'UserProfile'; Description = ("User profile '{0}' (registered as {1})" -f [string]$imagePath, [string]$profileKey.PSChildName); PlainDescription = ("The Windows profile folder '{0}' of the 'postgres' user" -f [string]$imagePath) })
            }
        }
        $defaultProfileFolder = "C:\Users\postgres"
        if (-not ($profilePaths -icontains $defaultProfileFolder) -and (Test-Path -LiteralPath $defaultProfileFolder)) {
            [void]$objects.Add([pscustomobject]@{ Kind = 'ProfileFolder'; Description = ("Folder '{0}'" -f $defaultProfileFolder); PlainDescription = ("The folder '{0}' of the 'postgres' Windows user" -f $defaultProfileFolder) })
        }
        $inventoryCompleted = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Checking -Label $inventoryProgressLabel -Current $inventoryProgressCurrent -Total 0 -StartedAt $inventoryProgressStarted -Complete -Outcome $(if ($inventoryCompleted) { 'Final' } else { 'Error' })
    }
    return [pscustomobject]@{
        Found = ($objects.Count -gt 0)
        Objects = $objects.ToArray()
    }
}

# Explains a PostgreSQL leftover refusal. Nothing was removed; the owner
# decides what each object is and removes only true leftovers manually.
# FIX128: the list is in plain words (the registry path, the account SID and the service name are in the log, not on the screen).
# A listed folder can hold game databases, so the screen warns before it mentions deleting anything and never says a
# listed item is safe to delete.
function Show-PostgresPartialInstallRefusal {
    param([Parameter(Mandatory)]$Inventory)
    Write-Host ""
    Write-Host "  PostgreSQL setup stopped before installing anything." -ForegroundColor Red
    Write-Host "  These PostgreSQL items are already on this PC. TeknoParrot Manager has no record" -ForegroundColor Yellow
    Write-Host "  that it made them, so it did not remove or change any of them:" -ForegroundColor Yellow
    foreach ($object in @($Inventory.Objects)) {
        $plainProperty = $object.PSObject.Properties['PlainDescription']
        $shown = if ($plainProperty -and -not [string]::IsNullOrWhiteSpace([string]$plainProperty.Value)) { [string]$plainProperty.Value } else { [string]$object.Description }
        Write-Host ("    - {0}" -f $shown) -ForegroundColor White
    }
    Write-Host ""
    Write-Host "  Do not delete anything on this list unless you are sure what it is." -ForegroundColor Red
    Write-Host "  A PostgreSQL folder can hold game databases and saved scores. Deleting it erases them" -ForegroundColor Red
    Write-Host "  for good. Copy the folder to a safe place first. If you are not sure, ask someone" -ForegroundColor Red
    Write-Host "  who knows computers before you delete or uninstall anything." -ForegroundColor Red
    Write-Host ""
    Write-Host "  If another program uses PostgreSQL 8.3 or the 'postgres' user, leave all of it in place." -ForegroundColor DarkGray
    Write-Host "  TeknoParrot Manager cannot install its own copy next to it." -ForegroundColor DarkGray
    Write-Host "  If you are sure they are leftovers of a PostgreSQL setup that did not finish, you can" -ForegroundColor DarkGray
    Write-Host "  remove them yourself, then run PostgreSQL setup again:" -ForegroundColor DarkGray
    Write-Host "    1) Settings > Apps: uninstall PostgreSQL 8.3." -ForegroundColor DarkGray
    Write-Host "    2) Computer Management > Local Users and Groups > Users: remove the 'postgres' user." -ForegroundColor DarkGray
    Write-Host "    3) System Properties > Advanced > User Profiles: remove the 'postgres' profile." -ForegroundColor DarkGray
    Write-Host "    4) A listed folder may hold your data. Copy it to a safe place before you delete it." -ForegroundColor DarkGray
    Write-Log ("Postgres install: refused -- {0} pre-existing PostgreSQL 8.3 object(s) without TeknoParrot Manager ownership evidence; nothing removed: {1}" -f @($Inventory.Objects).Count, ((@($Inventory.Objects) | ForEach-Object { $_.Kind }) -join ', '))
    Write-Log ("Postgres install: leftover items found: {0}" -f ((@($Inventory.Objects) | ForEach-Object { $_.Description }) -join '; '))
}

# Windows Installer's Automation interface accepts the same public MSI
# properties without launching msiexec.exe. This keeps SERVICEPASSWORD and
# SUPERPASSWORD out of process argument lists while retaining the MSI's
# unattended property-driven install. No verbose installer log is requested.
function Invoke-PostgresMsiPackage {
    param(
        [Parameter(Mandatory)][string]$MsiPath,
        [Parameter(Mandatory)][string]$PropertyValues
    )
    $installer = $null
    try {
        $installer = New-Object -ComObject WindowsInstaller.Installer
        $installer.UILevel = 2
        $installer.InstallProduct($MsiPath, $PropertyValues)
        return $true
    } catch {
        Write-Log 'Postgres install: Windows Installer automation failed.'
        return $false
    } finally {
        $PropertyValues = $null
        if ($installer) {
            try { [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($installer) } catch {}
        }
        $installer = $null
        [GC]::Collect()
    }
}

# Installs PostgreSQL 8.3 silently using the confirmed-working property set
# above. Requires Administrator (creates a Windows service + a local user
# account) -- prints a clear message and returns $false rather than failing
# unhelpfully if not elevated. Returns $true on confirmed success
# (Test-PostgresInstalled checked afterward, not just the installer API return,
# since a misleading "success" with no real service was observed during
# this session's testing). The superuser password is returned via
# $OutSuperPasswordPlain so the caller can DPAPI-encrypt and save it --
# this function never persists anything itself, and always deletes its
# working folder (the ZIP and extracted MSI) in a finally block regardless of
# outcome. No verbose MSI log is requested because the PostgreSQL 8.3 MSI can
# write connection passwords into deferred custom-action logging.
function Install-Postgres83 {
    param([ref]$OutSuperPasswordPlain)
    # FIX128: set only once the Windows Installer is about to run. After that point a failed install can leave a service, the
    # 'postgres' Windows account, folders or registry entries behind (see Get-PostgresInstallFailureView).
    $script:PostgresInstallerRan = $false

    if (-not (Test-RunningAsAdministrator)) {
        Write-Host "  TeknoParrot Manager needs Windows permission before it can install PostgreSQL." -ForegroundColor Red
        Write-Host "  No changes were made. TeknoParrot Manager will request that permission from its normal setup flow." -ForegroundColor Yellow
        Write-Log "Postgres install: aborted -- not running as Administrator."
        return $false
    }

    # Refuse before asking for passwords or downloading anything when
    # PostgreSQL 8.3 objects already exist: TPM has no ownership evidence for
    # them and never removes them automatically.
    $leftovers = Get-PostgresPartialInstallInventory
    if ($leftovers.Found) {
        Show-PostgresPartialInstallRefusal -Inventory $leftovers
        return $false
    }

    Write-Host ""
    Write-Host "  PostgreSQL 8.3 is required by one or more of your registered games." -ForegroundColor Cyan
    Write-Host "  It's a small local database program that runs quietly in the" -ForegroundColor DarkGray
    Write-Host "  background and only talks to TeknoParrot -- nothing is sent over" -ForegroundColor DarkGray
    Write-Host "  the internet, and it won't interfere with anything else on your PC." -ForegroundColor DarkGray
    Write-Host ""
    Write-Host "  You'll be asked for two different passwords:" -ForegroundColor White
    Write-Host "    1) A SERVICE ACCOUNT password -- for a Windows account Windows uses" -ForegroundColor DarkGray
    Write-Host "       to run PostgreSQL in the background. You'll almost never need it again." -ForegroundColor DarkGray
    Write-Host "    2) A DATABASE password -- this is the important one. It gets saved" -ForegroundColor DarkGray
    Write-Host "       (encrypted) so every Postgres game can be configured automatically." -ForegroundColor DarkGray
    Write-Host ""

    $svcPwPlain   = Read-ConfirmedPostgresPassword "the SERVICE ACCOUNT password" -RejectDoubleQuote
    Write-Host ""
    $superPwPlain = if ($null -ne $svcPwPlain) { Read-ConfirmedPostgresPassword "the DATABASE password" -RejectDoubleQuote -RequireSafeNewPassword }
    if ($null -eq $svcPwPlain -or $null -eq $superPwPlain) {
        Write-Host '  No password entered, so PostgreSQL was not installed. Nothing was changed.' -ForegroundColor Yellow
        Write-Log 'Postgres install: stopped -- the user pressed Enter at a password prompt.'
        $svcPwPlain = $null; $superPwPlain = $null
        return $false
    }
    Write-Host ""

    Write-Host "  Checking for the PostgreSQL installer..." -ForegroundColor Cyan
    $rel = Get-PostgresGuideRelease
    if ($null -eq $rel -or [string]::IsNullOrWhiteSpace([string]$rel.DownloadUrl)) {
        if ($null -eq $rel) { Write-Host "  ERROR: Could not reach GitHub to download the installer. Check your internet, VPN, proxy or firewall." -ForegroundColor Red }
        else { Write-Host "  ERROR: GitHub answered, but it did not offer the PostgreSQL installer. It may have been moved or removed, or GitHub may be limiting requests. Nothing was changed. TeknoParrot-Manager.log has details." -ForegroundColor Red }
        Write-Log "Postgres install: aborted -- could not fetch release info."
        $svcPwPlain = $null; $superPwPlain = $null
        return $false
    }

    $workDir = Join-Path $env:TEMP ("pg83-install-" + [guid]::NewGuid().ToString("N"))
    [void][System.IO.Directory]::CreateDirectory($workDir)
    $zipPath = Join-Path $workDir "guide.zip"

    try {
        Write-Host "  Downloading installer ($($rel.SizeMB) MB, this may take a minute)..." -ForegroundColor Cyan
        if (-not (Invoke-PostgresGuideDownload $rel.DownloadUrl $zipPath -ExpectedBytes $rel.SizeBytes)) {
            Write-Host "  ERROR: Download failed." -ForegroundColor Red
            return $false
        }
        Expand-ZipFileSafe -ZipPath $zipPath -DestDir $workDir -GameName 'PostgreSQL installer files'
        $msiFile = Get-ChildItem -LiteralPath $workDir -Filter "postgresql-8.3-int.msi" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
        if (-not $msiFile) {
            Write-Host "  ERROR: Installer file not found inside the downloaded ZIP." -ForegroundColor Red
            Write-Log "Postgres install: aborted -- postgresql-8.3-int.msi not found after extraction."
            return $false
        }

        # Re-check immediately before the MSI runs; still never removes anything.
        $leftovers = Get-PostgresPartialInstallInventory
        if ($leftovers.Found) {
            Show-PostgresPartialInstallRefusal -Inventory $leftovers
            return $false
        }

        # FIX36 S6: a double quote would end the quoted MSI property value early,
        # so the server password would differ from the one TPM saves. The prompts
        # above already refuse it; this check fails closed before any install.
        if ($svcPwPlain.IndexOf([char]34) -ge 0 -or $superPwPlain.IndexOf([char]34) -ge 0) {
            Write-Host '  PostgreSQL was not installed: a password contained a double quote ("). Nothing was changed.' -ForegroundColor Red
            Write-Log 'Postgres install: refused before the installer ran because a password contained a double quote.'
            return $false
        }
        # FIX36B S6: the database password must also pass the new-password rules
        # (1 to 100 printable ASCII characters); the prompt already asks again.
        if (Get-PostgresNewPasswordProblem -Password $superPwPlain) {
            Write-Host '  PostgreSQL was not installed: the database password cannot be used safely. Nothing was changed.' -ForegroundColor Red
            Write-Log 'Postgres install: refused before the installer ran because the database password failed the new-password rules.'
            return $false
        }

        Write-Host "  Installing PostgreSQL 8.3 -- this can take a minute or two..." -ForegroundColor Cyan
        $msiPropertyValues = @(
            "INTERNALLAUNCH=1",
            "ROOTDRIVE=C:\",
            "SERVICEACCOUNT=postgres",
            "SERVICEDOMAIN=$env:COMPUTERNAME",
            "SERVICEPASSWORD=`"$svcPwPlain`"",
            "SERVICEPASSWORDV=`"$svcPwPlain`"",
            "CREATESERVICEUSER=1",
            "SUPERUSER=postgres",
            "SUPERPASSWORD=`"$superPwPlain`"",
            "LISTENPORT=5432",
            "LOCALE=C",
            "ENCODING=UTF8",
            "CLENCODE=UTF8",
            "PERMITREMOTE=0",
            "RUNSTACKBUILDER=0",
            "DOSERVICE=1",
            "DOINITDB=1"
        )
        $msiPropertyString = $msiPropertyValues -join ' '
        $script:PostgresInstallerRan = $true
        # One long Windows Installer call that reports nothing while it runs: the bar says "still working", never "stalled".
        Write-TpmCompactExtractionProgress -Phase Installing -Label 'PostgreSQL installer' -Current 0 -Total 0 -LongStep
        $msiSucceeded = Invoke-PostgresMsiPackage -MsiPath $msiFile.FullName -PropertyValues $msiPropertyString
        # The step closes only after the service check: the installer returning success is not "installed" until the service is there.
        $installVerified = ($msiSucceeded -and (Test-PostgresInstalled))
        Write-TpmCompactExtractionProgress -Phase Installing -Label 'PostgreSQL installer' -Complete -Outcome $(if ($installVerified) { 'Final' } else { 'Error' })
        $msiPropertyString = $null
        $msiPropertyValues = $null
        $svcPwPlain = $null
        [GC]::Collect()

        if (-not $installVerified) {
            Write-Log 'Postgres install: FAILED -- Windows Installer did not produce a verified PostgreSQL service. Parts of PostgreSQL may now be on this PC.'
            $superPwPlain = $null
            return $false
        }


        # FIX36B N7: say "running" only when the service was seen running.
        $installedServiceStatus = Get-PostgresServiceStatusText
        if ($installedServiceStatus -eq 'Running') {
            Write-Host "  PostgreSQL 8.3 installed and running." -ForegroundColor Green
        } else {
            $installedStatusText = if ([string]::IsNullOrWhiteSpace($installedServiceStatus)) { 'unknown' } else { $installedServiceStatus }
            Write-Host ("  PostgreSQL 8.3 was installed, but its Windows service is not running yet (state: {0}). If a later step cannot reach PostgreSQL, start the service and choose PostgreSQL setup again." -f $installedStatusText) -ForegroundColor Yellow
        }
        Write-Log "Postgres install: succeeded."
        $OutSuperPasswordPlain.Value = $superPwPlain
        return $true
    } finally {
        $svcPwPlain = $null
        $superPwPlain = $null
        [GC]::Collect()
        Remove-Item -LiteralPath $workDir -Recurse -Force -ErrorAction SilentlyContinue
    }
}

# =============================================================================
# POSTGRESQL PER-GAME SETUP  (field configuration + database creation/restore)
# =============================================================================

# The files that sit in a game's own pg_backup folder: inside the most recent YYYY-MM-DD-named subfolder that has files,
# or else directly inside pg_backup\ (ISO names sort correctly as strings; an empty dated folder hides neither an older
# backup nor the files in pg_backup\ itself). With -IncludeAlternate, a
# pg_backup\alternate backups folder (its own pg_backup folder, or files directly inside it) is looked at when nothing else holds
# a backup; only the creation of a missing database uses that switch. Returns nothing when pg_backup is missing.
function Get-PostgresBackupCandidates {
    param([string]$GameFolder, [switch]$IncludeAlternate)

    $pgBackupDir = Join-Path $GameFolder "pg_backup"
    if (-not (Test-Path -LiteralPath $pgBackupDir)) { return @() }

    $dateSubfolders = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $pgBackupDir -ProgressLabel 'PostgreSQL backup date-folder discovery' -Filter '*' -EnumerationErrorAction SilentlyContinue -DirectoriesOnly |
                            Where-Object { $_.Name -match '^\d{4}-\d{2}-\d{2}$' } | Sort-Object Name -Descending)
    foreach ($dateFolder in $dateSubfolders) {
        $dateFiles = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $dateFolder.FullName -ProgressLabel 'PostgreSQL backup file discovery' -Filter '*' -EnumerationErrorAction SilentlyContinue)
        if (@($dateFiles | Where-Object { [System.IO.Path]::GetExtension([string]$_.Name) -in @('', '.backup') }).Count -gt 0) { return $dateFiles }
    }
    $rootFiles = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $pgBackupDir -ProgressLabel 'PostgreSQL backup file discovery' -Filter '*' -EnumerationErrorAction SilentlyContinue)
    if (@($rootFiles | Where-Object { [System.IO.Path]::GetExtension([string]$_.Name) -in @('', '.backup') }).Count -gt 0) { return $rootFiles }
    if (-not $IncludeAlternate) { return @() }
    $alternateDir = Join-Path $pgBackupDir 'alternate backups'
    $nested = @(Get-PostgresBackupCandidates -GameFolder $alternateDir)
    if ($nested.Count -gt 0 -or -not (Test-Path -LiteralPath $alternateDir -PathType Container)) { return $nested }
    return @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $alternateDir -ProgressLabel 'PostgreSQL backup file discovery' -Filter '*' -EnumerationErrorAction SilentlyContinue)
}

# Can the game's own executable be used? 'Missing' = not found. 'PathTooLong' = found, but Windows PowerShell 5.1 cannot read the game folder through a plain path (over 259 characters), so its backup files cannot be read or restored. 'Available' = found and readable.
function Get-TpmGameExeAvailability {
    param([AllowEmptyString()][string]$GamePath)
    $found = $false
    # A path with characters Windows does not allow makes the long-path helper throw on Windows PowerShell 5.1; that is simply "not found".
    if (-not [string]::IsNullOrWhiteSpace($GamePath)) { try { $found = [System.IO.File]::Exists((ConvertTo-TpmAutoSyncLongPath -Path $GamePath)) } catch { $found = $false } }
    if (-not $found) { return 'Missing' }
    if (-not (Test-Path -LiteralPath $GamePath -PathType Leaf)) { return 'PathTooLong' }
    return 'Available'
}

# FIX130 (S12) / N18A / N18B: the one rule behind the backup choice, used by the rebuild, the auto-create check and the creation of a
# missing database. Newest is the game's backup file: among the candidates (already the newest date folder), the file whose name
# starts with the latest valid 24-hour time (HHmm, 0000-2359); a name without one comes last. NewestHasTime says whether the winner's
# name carries a time (when it does not, the file was picked by name only). CandidateCount is how many files compete. PathTooLong says the game
# file is there but its folder path is too long for Windows PowerShell 5.1 to read (no backup file can be listed or restored), so callers say that instead of "no backup".
function Get-PostgresBackupSelection {
    param([string]$GamePath, [switch]$IncludeAlternate)

    # The long-path check comes first (Windows PowerShell 5.1 with long paths off cannot see a game path over 259 characters through a plain path); the plain check stays second so a relative path is still judged as before.
    $availability = if ([string]::IsNullOrWhiteSpace($GamePath)) { 'Missing' } else { Get-TpmGameExeAvailability -GamePath $GamePath }
    if ($availability -eq 'PathTooLong') { return [pscustomobject]@{ Newest = $null; NewestHasTime = $false; CandidateCount = 0; PathTooLong = $true } }
    if ($availability -eq 'Missing' -and ([string]::IsNullOrWhiteSpace($GamePath) -or -not (Test-Path -LiteralPath $GamePath -PathType Leaf))) {
        return [pscustomobject]@{ Newest = $null; NewestHasTime = $false; CandidateCount = 0; PathTooLong = $false }
    }
    $timePattern = '^([01]\d|2[0-3])[0-5]\d'
    # Only real backup files compete: a '.backup' file, or a file with no extension. A note such as readme.txt is never picked and never counted.
    $candidates = @(Get-PostgresBackupCandidates -GameFolder ([System.IO.Path]::GetDirectoryName($GamePath)) -IncludeAlternate:$IncludeAlternate | Where-Object { [System.IO.Path]::GetExtension([string]$_.Name) -in @('', '.backup') })
    $newest = @($candidates | Sort-Object -Property @{ Expression = { $_.Name -match $timePattern } }, Name -Descending | Select-Object -First 1)
    return [pscustomobject]@{ Newest = $(if ($newest.Count -gt 0) { [string]$newest[0].FullName } else { $null }); NewestHasTime = [bool]($newest.Count -gt 0 -and $newest[0].Name -match $timePattern); CandidateCount = [int]$candidates.Count; PathTooLong = $false }
}

# FIX130 (S6): the one place that spells a setup database's item id. Every item list of the setup result (changed, completed,
# failed, unknown) and the rollback record use this form; the bare name stays only in the per-database receipts.
function Get-PostgresSetupDatabaseItemId {
    param([Parameter(Mandatory)][string]$DbName)
    return ('database:' + $DbName)
}

# FIX130 (S10): true when the error, or any error inside it, is a stop (Ctrl+C).
function Test-TpmErrorIsPipelineStop {
    param([Parameter(Mandatory)]$ErrorRecord)
    $exception = $ErrorRecord.Exception
    while ($null -ne $exception) {
        if ($exception -is [System.Management.Automation.PipelineStoppedException]) { return $true }
        $exception = $exception.InnerException
    }
    return $false
}

# FIX130 (S11): a small durable journal of the databases ONE setup run creates. It sits in the recovery-backup folder (the folder
# TeknoParrot Manager already locks to the current user), holds database names and a stage only (no password, no path), and is
# written to disk BEFORE createdb runs. Stage 'Creating' = createdb may have run and the restore is not verified finished, so the
# database may be half restored; stage 'Created' = the restore was verified finished. The journal is cleared on a verified success
# or a verified rollback. A later run drops a database ONLY when this journal names it with stage 'Creating'.
function Get-PostgresSetupJournalPath {
    param([AllowNull()]$RecoveryBackup = $null)
    $root = $null
    if ($null -ne $RecoveryBackup -and $RecoveryBackup.PSObject.Properties['Path'] -and -not [string]::IsNullOrWhiteSpace([string]$RecoveryBackup.Path)) {
        $root = [System.IO.Path]::GetDirectoryName(([System.IO.Path]::GetFullPath([string]$RecoveryBackup.Path)).TrimEnd('\', '/'))
    }
    if ([string]::IsNullOrWhiteSpace($root)) { $root = Get-PostgresRecoveryBackupRoot }
    return (Join-Path $root 'PostgresSetupCreatedDatabases.journal.json')
}

# Pure reader of the journal text; throws on anything it does not fully recognize (fail closed).
function ConvertFrom-PostgresSetupJournalText {
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Text)
    $journal = $Text | ConvertFrom-Json -ErrorAction Stop
    if ($null -eq $journal -or -not $journal.PSObject.Properties['Schema'] -or [string]$journal.Schema -cne 'TPM.PostgresSetupJournal.v1') { throw 'The setup journal schema is not recognized.' }
    $entries = New-Object System.Collections.Generic.List[object]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
    $rawEntries = if ($journal.PSObject.Properties['Entries']) { @($journal.Entries | Where-Object { $null -ne $_ }) } else { @() }
    foreach ($entry in $rawEntries) {
        $name = if ($entry.PSObject.Properties['Database']) { [string]$entry.Database } else { '' }
        $stage = if ($entry.PSObject.Properties['Stage']) { [string]$entry.Stage } else { '' }
        if (-not (Test-SafePostgresDbName $name)) { throw 'The setup journal holds an unsafe database name.' }
        if ($stage -cnotin @('Creating', 'Created')) { throw 'The setup journal holds an unknown stage.' }
        if (-not $seen.Add($name)) { throw 'The setup journal lists a database twice.' }
        $updated = if ($entry.PSObject.Properties['UpdatedUtc']) { [string]$entry.UpdatedUtc } else { '' }
        [void]$entries.Add([pscustomobject]@{ Database = $name; Stage = $stage; UpdatedUtc = $updated })
    }
    return @($entries.ToArray())
}

# Status: None (no journal or an empty one), Present (Entries), Unreadable (Error; nothing in the file is trusted).
function Read-PostgresSetupJournal {
    param([Parameter(Mandatory)][string]$Path)
    try {
        if ([System.IO.Directory]::Exists($Path)) { throw 'A folder sits where the setup journal belongs.' }
        if (-not [System.IO.File]::Exists($Path)) { return [pscustomobject]@{ Status = 'None'; Path = $Path; Entries = @(); Error = $null } }
        Assert-TpmNoReparseWriteTarget -Path $Path -Operation 'read PostgreSQL setup journal'
        Assert-PostgresRecoveryDirectoryAcl -Path ([System.IO.Path]::GetDirectoryName($Path))
        $text = [System.IO.File]::ReadAllText($Path, (New-Object System.Text.UTF8Encoding $false))
        $entries = @(ConvertFrom-PostgresSetupJournalText -Text $text)
        return [pscustomobject]@{ Status = $(if ($entries.Count -gt 0) { 'Present' } else { 'None' }); Path = $Path; Entries = $entries; Error = $null }
    } catch {
        return [pscustomobject]@{ Status = 'Unreadable'; Path = $Path; Entries = @(); Error = [string]$_.Exception.Message }
    }
}

# Writes the whole journal atomically and flushed to disk (Write-TpmAtomicTextFile), or removes the file when there are no entries.
# Throws when it cannot do so; the caller decides what that means (before createdb: do not create).
function Save-PostgresSetupJournal {
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][string]$RunId, [AllowEmptyCollection()][object[]]$Entries = @())
    $list = @($Entries | Where-Object { $null -ne $_ })
    if ($list.Count -eq 0) {
        if ([System.IO.File]::Exists($Path)) {
            Assert-TpmNoReparseWriteTarget -Path $Path -Operation 'remove PostgreSQL setup journal'
            Remove-Item -LiteralPath $Path -Force -ErrorAction Stop
            if ([System.IO.File]::Exists($Path)) { throw 'The setup journal is still present after removal.' }
        }
        return
    }
    $document = [ordered]@{
        Schema = 'TPM.PostgresSetupJournal.v1'
        RunId = $RunId
        Entries = @($list | ForEach-Object { [ordered]@{ Database = [string]$_.Database; Stage = [string]$_.Stage; UpdatedUtc = [string]$_.UpdatedUtc } })
    }
    $expectedCount = $list.Count
    [void](Write-TpmAtomicTextFile -Path $Path -Text ($document | ConvertTo-Json -Depth 4) -Operation 'PostgreSQL setup journal write' -Validate { param($readBack) @(ConvertFrom-PostgresSetupJournalText -Text $readBack).Count -eq $expectedCount })
}

# FIX130 (S11): puts right what an unfinished earlier setup left. ONLY a database that the journal names with stage 'Creating' is
# dropped (Restore-PostgresSetupCreatedDatabases: a verified drop, or a verified "already absent"); a 'Created' one is complete and
# kept. Entries that were put right are removed from the journal; a database whose drop could not be verified stays in it.
function Invoke-PostgresSetupJournalRecovery {
    param([Parameter(Mandatory)][string]$JournalPath, [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Entries, [AllowEmptyString()][string]$SuperPasswordPlain = '')
    $creating = @($Entries | Where-Object { [string]$_.Stage -ceq 'Creating' })
    $kept = @($Entries | Where-Object { [string]$_.Stage -ceq 'Created' } | ForEach-Object { [string]$_.Database })
    if ($creating.Count -gt 0) {
        $rollback = Restore-PostgresSetupCreatedDatabases -Databases @($creating | ForEach-Object { [pscustomobject]@{ DbName = [string]$_.Database } }) -SuperPasswordPlain $SuperPasswordPlain
    } else {
        $rollback = [pscustomobject]@{ Verified = $true; RestoredItems = @(); FailedItems = @(); Errors = @(); DatabaseReceipts = @() }
    }
    $failedNames = @($rollback.FailedItems | ForEach-Object { [string]$_ })
    $remaining = @($creating | Where-Object { $failedNames -ccontains [string]$_.Database })
    $journalCleared = $true
    try {
        Save-PostgresSetupJournal -Path $JournalPath -RunId ([guid]::NewGuid().ToString('N')) -Entries $remaining
    } catch {
        $journalCleared = $false
        $journalUpdateError = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
        Write-Log ('Postgres setup: the note from an earlier setup could not be updated: {0}' -f $journalUpdateError)
    }
    return [pscustomobject]@{
        Verified = [bool]$rollback.Verified
        RestoredNames = @($rollback.RestoredItems | ForEach-Object { [string]$_ })
        FailedNames = $failedNames
        KeptNames = $kept
        Errors = @($rollback.Errors)
        DatabaseReceipts = @($rollback.DatabaseReceipts)
        JournalCleared = $journalCleared
    }
}

# Counts the tables a bundled backup lists ("pg_restore --list" prints one "TABLE <schema> <name> <owner>" line per table; the
# "TABLE DATA" lines have more words and do not count). Pure. A table name with a space is not counted, so the count is never too high.
function Get-PostgresBackupListedTableCount {
    param([AllowNull()][AllowEmptyString()][string]$ListOutput)
    if ([string]::IsNullOrWhiteSpace($ListOutput)) { return 0 }
    return @([regex]::Matches($ListOutput, '(?m)^\s*\d+;\s+\d+\s+\d+\s+TABLE\s+\S+\s+\S+\s+\S+\s*$')).Count
}

# FIXDB27: proves a game database is ready the way the game will use it. It connects with the host, port, user, password and database
# name saved in the game's own profile and counts the tables. Ready needs at least MinTables (never less than 1). A database problem
# never throws: the answer says what failed, redacted.
function Get-PostgresGameDatabaseReadiness {
    param([Parameter(Mandatory)][System.Xml.XmlDocument]$Doc, [int]$MinTables = 1)
    $minimum = [Math]::Max(1, $MinTables)
    $dbName = [string](Get-PostgresFieldValue $Doc 'DbName')
    $user = [string](Get-PostgresFieldValue $Doc 'User')
    $address = [string](Get-PostgresFieldValue $Doc 'Address')
    $port = [string](Get-PostgresFieldValue $Doc 'Port')
    $pass = [string](Get-PostgresFieldValue $Doc 'Pass')
    $notReady = { param([string]$Why, [int]$Count) [pscustomobject]@{ Ready = $false; TableCount = $Count; Error = $Why } }
    if (-not (Test-SafePostgresDbName $dbName) -or $port -notmatch '\A\d{1,5}\z' -or $user -notmatch '\A[A-Za-z0-9_][A-Za-z0-9_.-]*\z' -or ($address -ne '::1' -and $address -notmatch '\A[A-Za-z0-9_][A-Za-z0-9_.:-]*\z')) {
        return (& $notReady 'The game profile does not hold a usable database name, user, address and port.' 0)
    }
    $countInterpreter = { param($Raw) $text = ([string]$Raw.StdOut).Trim(); if ($text -match '\A\d+\z') { [int]$text } else { $null } }
    $query = "SELECT count(*) FROM pg_tables WHERE schemaname NOT IN ('pg_catalog','information_schema')"
    try {
        $command = Invoke-Postgres83RestoreCommand -ToolName 'psql.exe' -Arguments @('-U', $user, '-h', $address, '-p', $port, '-d', $dbName, '-tAc', $query) -SuperPasswordPlain $pass -Interpret $countInterpreter
    } catch {
        return (& $notReady (ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($pass)) 0)
    }
    if (-not $command.Succeeded) {
        $why = if ([string]::IsNullOrWhiteSpace([string]$command.Output)) { 'psql could not connect and gave no reason.' } else { [string]$command.Output }
        return (& $notReady ('Could not connect with the settings saved in the game profile: ' + $why) 0)
    }
    $count = Get-TpmTransactionField -Object $command -Name 'Interpretation' -Default $null
    if ($null -eq $count) { return (& $notReady 'The table count answer could not be read.' 0) }
    if ([int]$count -lt $minimum) { return (& $notReady ('Found {0} tables, expected at least {1}.' -f [int]$count, $minimum) ([int]$count)) }
    return [pscustomobject]@{ Ready = $true; TableCount = [int]$count; Error = $null }
}

# Creates a database and restores the game's bundled backup into it. Setup always supplies a backup file: a blank BackupFile would
# make only an EMPTY database, which is never ready, so setup never asks for that. The caller owns rollback and receives the
# mutation boundary, verified state, and command receipts.
function New-PostgresDatabaseFromBackup {
    param([string]$DbName, [string]$Encoding, [string]$BackupFile, [string]$SuperPasswordPlain, [scriptblock]$BeforeCreate = $null)
    $restoreBackup = -not [string]::IsNullOrWhiteSpace($BackupFile)
    $commands = New-Object System.Collections.Generic.List[object]
    $result = [ordered]@{
        PSTypeName = 'TPM.PostgresSetupDatabaseResult.v1'
        SchemaVersion = 1
        Database = $DbName
        Mode = $(if ($restoreBackup) { 'RestoreBundledBackup' } else { 'EmptyDatabase' })
        Succeeded = $false
        MutationAttempted = $false
        DatabaseMayExist = $false
        FailureStage = $null
        PreMutationState = $null
        CaseVariantCheck = $null
        PostMutationState = $null
        FinalVerification = [pscustomobject]@{ Attempted = $false; Passed = $false; Exists = $null }
        Commands = @()
        Error = $null
    }
    $stage = 'DatabaseName'
    try {
        if (-not (Test-SafePostgresDbName $DbName)) { throw 'The PostgreSQL database name is unsafe.' }
        $stage = 'PreMutationState'
        $current = Get-PostgresDatabaseState -DbName $DbName -SuperPasswordPlain $SuperPasswordPlain
        $result.PreMutationState = $current
        if (-not $current.Verified -or $current.Exists) { throw 'The PostgreSQL database was not verified absent before creation.' }
        $stage = 'CaseVariantCheck'
        $caseState = Get-PostgresDatabaseCaseVariantState -DbName $DbName -SuperPasswordPlain $SuperPasswordPlain
        $result.CaseVariantCheck = $caseState
        if (-not $caseState.Verified) { throw 'The PostgreSQL database names could not be compared by case before creation.' }
        if (@($caseState.Variants).Count -gt 0) { throw 'A PostgreSQL database whose name differs only by case already exists, so the database was not created.' }
        if ($restoreBackup) {
            $stage = 'BackupVerification'
            if (-not (Test-Path -LiteralPath $BackupFile -PathType Leaf)) { throw 'The bundled PostgreSQL backup is unavailable.' }
            $backupState = Get-TpmFileState -Path $BackupFile
            if (-not $backupState.Readable -or -not $backupState.Exists -or $backupState.IsDirectory -or [int64]$backupState.Length -le 0) {
                throw 'The bundled PostgreSQL backup is unreadable or empty.'
            }
        }
        $stage = 'ToolsetVerification'
        $toolSet = Test-Postgres83RestoreToolSet -SuperPasswordPlain $SuperPasswordPlain
        if (-not $toolSet.Verified) { throw 'The PostgreSQL 8.3 client tool set could not be verified.' }
        if ($restoreBackup) {
            $stage = 'ArchiveValidation'
            [void](Invoke-Postgres83RestoreCommandChecked -ToolName 'pg_restore.exe' -Arguments @('--list',$BackupFile) -SuperPasswordPlain $SuperPasswordPlain -CommandLog $commands -DatabaseName $DbName)
        }
        # FIX130 (S11): the caller's journal note is written (and on disk) after the verified-absent check and BEFORE createdb runs.
        # If it cannot be written nothing was created, so this is a failure before the mutation boundary.
        if ($null -ne $BeforeCreate) {
            $stage = 'SetupJournal'
            [void](& $BeforeCreate $DbName)
        }
        $stage = 'DatabaseCreation'
        $result.MutationAttempted = $true
        $createCommand = Invoke-Postgres83RestoreCommandChecked -ToolName 'createdb.exe' -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-E',$Encoding,'-T','template0',$DbName) -SuperPasswordPlain $SuperPasswordPlain -CommandLog $commands -DatabaseName $DbName
        # FIX129 (N2): the restore below is judged with the REAL result of this createdb call (the Checked function throws when it fails).
        $createdbSucceeded = ($null -ne $createCommand -and [bool]$createCommand.Succeeded)
        $result.DatabaseMayExist = $true
        $stage = 'DatabaseCompatibility'
        [void](Invoke-Postgres83RestoreCommandChecked -ToolName 'psql.exe' -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-d',$DbName,'-c',('ALTER DATABASE "' + $DbName + '" SET standard_conforming_strings = on;')) -SuperPasswordPlain $SuperPasswordPlain -CommandLog $commands -DatabaseName $DbName)
        if ($restoreBackup) {
            $stage = 'DatabaseRestore'
            $restoreCommand = Invoke-Postgres83RestoreCommandChecked -ToolName 'pg_restore.exe' -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-d',$DbName,$BackupFile) -SuperPasswordPlain $SuperPasswordPlain -CommandLog $commands -DatabaseName $DbName -AcceptConstraintOnlyRestoreWarnings -CreatedbSucceeded $createdbSucceeded
            # FIX125: the whole text of the known harmless warnings goes to the log only (already redacted); the screens only count them.
            if ($null -ne $restoreCommand -and $null -ne $restoreCommand.PSObject.Properties['AcceptedWarningCount']) {
                Write-Log ('Postgres setup: database {0}: the bundled backup finished with {1} known harmless foreign-key warnings (pg_restore exit {2}); output: {3}' -f $DbName, $restoreCommand.AcceptedWarningCount, $restoreCommand.ExitCode, (([string]$restoreCommand.Output) -replace '\s*\r?\n\s*', ' | '))
            }
        }
        $stage = 'FinalVerification'
        $finalState = Get-PostgresDatabaseState -DbName $DbName -SuperPasswordPlain $SuperPasswordPlain
        $result.PostMutationState = $finalState
        $result.FinalVerification = [pscustomobject]@{ Attempted = $true; Passed = [bool]($finalState.Verified -and $finalState.Exists); Exists = if ($finalState.Verified) { [bool]$finalState.Exists } else { $null } }
        if (-not $finalState.Verified -or -not $finalState.Exists) { throw 'The newly created PostgreSQL database could not be verified.' }
        $result.Succeeded = $true
        $stage = 'Complete'
    } catch {
        $result.Error = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
        if ($result.MutationAttempted) {
            try {
                $result.PostMutationState = Get-PostgresDatabaseState -DbName $DbName -SuperPasswordPlain $SuperPasswordPlain
            } catch {
                $result.PostMutationState = [pscustomobject]@{ Verified = $false; Exists = $null; Error = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain) }
            }
        }
        $finalAbsentVerified = ($result.PreMutationState -and $result.PreMutationState.Verified -and -not $result.PreMutationState.Exists -and $result.PostMutationState -and $result.PostMutationState.Verified -and -not $result.PostMutationState.Exists)
        $result.FinalVerification = [pscustomobject]@{
            Attempted = [bool]$result.MutationAttempted
            Passed = [bool]$finalAbsentVerified
            Exists = if ($result.PostMutationState -and $result.PostMutationState.Verified) { [bool]$result.PostMutationState.Exists } else { $null }
        }
        $result.FailureStage = $stage
    } finally {
        $result.Commands = @($commands.ToArray())
    }
    return [pscustomobject]$result
}
# Explicit destructive recovery for a known affected database. The caller must
# obtain confirmation after showing the affected game/database list. The
# PostgreSQL 8.3 transaction engine captures and verifies the current database
# before it permits the destructive boundary, and returns the same structured
# result used by the ordinary database restore menu.
function Reset-PostgresDatabaseFromBackup {
    param(
        [Parameter(Mandatory)][string]$DbName,
        [Parameter(Mandatory)][string]$Encoding,
        [Parameter(Mandatory)][string]$BackupFile,
        [Parameter(Mandatory)][string]$SuperPasswordPlain,
        [Parameter(Mandatory)]$RecoveryBackup,
        [switch]$Confirmed
    )
    $itemId='database-reinitialize'
    $backupInfo=if($RecoveryBackup){$RecoveryBackup}else{[pscustomobject]@{Required=$true;Attempted=$false;Created=$false;Verified=$false;Path=$null;Items=@();FailureStage='RecoveryEvidence';Reason='Verified recovery evidence is unavailable.';ResiduePaths=@()}}
    $early = {
        param([string]$ReasonCode,[string]$Summary,[bool]$RecoveryBlocked)
        $tx=New-TpmProfileTransactionResult -WorkflowKey 'PostgresRestore' -OperationKey 'ReinitializeDatabase' -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' -Summary $Summary -Items @($itemId) -FailedItems @($itemId) -Backup $backupInfo -ReasonCode $ReasonCode -FinalChecks @('The reinitialize preflight stopped before the database mutation boundary.')
        foreach($pair in @(@('Succeeded',$false),@('Confirmed',[bool]$Confirmed),@('DatabaseBackup',$null),@('RestoredOriginal',$false),@('Reason',$Summary),@('RecoveryBlocked',$RecoveryBlocked))) { $tx | Add-Member -NotePropertyName $pair[0] -NotePropertyValue $pair[1] -Force }
        $tx | Add-Member -NotePropertyName TransactionResult -NotePropertyValue $tx -Force
        return $tx
    }
    if (-not $Confirmed) { return (& $early 'CONFIRMATION_REQUIRED' 'The rebuild did not start because it was not confirmed. Nothing was changed.' $false) }
    if (-not $RecoveryBackup -or -not $RecoveryBackup.Verified) { return (& $early 'RECOVERY_EVIDENCE_REQUIRED' 'The rebuild did not start because the safety copy could not be made. Nothing was changed.' $true) }
    if (-not (Test-SafePostgresDbName $DbName)) { return (& $early 'DATABASE_NAME_UNSAFE' 'The rebuild did not start because a database name was not valid. Nothing was changed.' $true) }
    if (-not (Test-Path -LiteralPath $BackupFile -PathType Leaf)) { return (& $early 'REBUILD_BACKUP_MISSING' 'The rebuild did not start because the game''s starting database file is missing. Nothing was changed.' $true) }
    try {
        $backupInput = [pscustomobject]@{ BackupFile = [System.IO.Path]::GetFullPath($BackupFile); Database = $DbName }
        $selectedRoot = [System.IO.Path]::GetDirectoryName($backupInput.BackupFile)
        $evidenceRoot = Join-Path ([System.IO.Path]::GetFullPath([string]$RecoveryBackup.Path)) 'DatabaseReinitialize'
        $transaction = Invoke-PostgresRestoreTransaction -BackupFiles @($backupInput) -SelectedBackupRoot $selectedRoot -EvidenceRoot $evidenceRoot -SuperPasswordPlain $SuperPasswordPlain -AcceptConstraintOnlyRestoreWarnings
        $currentDump = @($transaction.Backup.Items | Where-Object { $_.Kind -eq 'CurrentDatabaseRollbackDump' } | Select-Object -First 1)
        $transaction | Add-Member -NotePropertyName Confirmed -NotePropertyValue $true -Force
        $transaction | Add-Member -NotePropertyName Succeeded -NotePropertyValue ($transaction.Outcome -eq 'SUCCEEDED') -Force
        $transaction | Add-Member -NotePropertyName RestoredOriginal -NotePropertyValue ($transaction.Outcome -eq 'ROLLED_BACK_VERIFIED' -or $transaction.UnderlyingOutcome -eq 'ROLLED_BACK_VERIFIED') -Force
        $transaction | Add-Member -NotePropertyName RecoveryBlocked -NotePropertyValue ([bool]$transaction.RecoveryBlocked) -Force
        $transaction | Add-Member -NotePropertyName Reason -NotePropertyValue ([string]$transaction.Summary) -Force
        $databaseBackup = if($currentDump.Count -gt 0){$currentDump[0].Path}else{$null}
        $transaction | Add-Member -NotePropertyName DatabaseBackup -NotePropertyValue $databaseBackup -Force
        $transaction | Add-Member -NotePropertyName TransactionResult -NotePropertyValue $transaction -Force
        Write-Log ("Postgres reinitialize: outcome={0}; database={1}; rollback-verified={2}; summary={3}; errors={4}" -f $transaction.Outcome,$DbName,$transaction.RestoredOriginal,$transaction.Summary,(@($transaction.Errors) -join ' | '))
        return $transaction
    } catch {
        $redactedError = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
        Write-Log ("Postgres reinitialize blocked for {0}; transaction engine error={1}" -f $DbName,$redactedError)
        $tx=New-TpmProfileTransactionResult -WorkflowKey 'PostgresRestore' -OperationKey 'ReinitializeDatabase' -Outcome 'ACTION_REQUIRED' -ProductState 'UNKNOWN' -Summary 'The rebuild did not finish, and TeknoParrot Manager could not check that your data is back as it was. Ask for help before you try again.' -Items @($itemId) -ChangedItems @($itemId) -FailedItems @($itemId) -MutationStarted $true -Backup $backupInfo -FinalPassed $false -ReasonCode 'TRANSACTION_RESULT_UNAVAILABLE' -FinalChecks @('Technical failure evidence was redacted and retained in the recovery log.')
        foreach($pair in @(@('Succeeded',$false),@('Confirmed',$true),@('DatabaseBackup',$null),@('RestoredOriginal',$false),@('Reason','PostgreSQL reinitialize failed before a verified result was produced.'),@('RecoveryBlocked',$true))) { $tx | Add-Member -NotePropertyName $pair[0] -NotePropertyValue $pair[1] -Force }
        $tx | Add-Member -NotePropertyName TransactionResult -NotePropertyValue $tx -Force
        return $tx
    }
}

# FIX36 S4: decides whether TPM may write the local postgres password into a
# profile's Pass field. 'Same': nothing to do. 'FillBlank': Pass is blank and
# the profile uses (or leaves blank) the local postgres connection.
# 'NeedsApproval': Pass already holds a different value, or the profile names
# another database user, a non-local address or another port; TPM must list
# these profiles and the user must approve before Pass is replaced.
function Get-PostgresProfilePassDecision {
    param([Parameter(Mandatory)][System.Xml.XmlDocument]$Doc, [Parameter(Mandatory)][string]$SuperPasswordPlain)
    $pass = Get-PostgresFieldValue $Doc 'Pass'
    $passIsLocal = [string]::Equals([string]$pass, $SuperPasswordPlain, [System.StringComparison]::Ordinal)
    $reasons = New-Object System.Collections.Generic.List[string]
    $user = [string](Get-PostgresFieldValue $Doc 'User')
    $address = [string](Get-PostgresFieldValue $Doc 'Address')
    $port = [string](Get-PostgresFieldValue $Doc 'Port')
    if (-not $passIsLocal -and -not [string]::IsNullOrWhiteSpace([string]$pass)) { [void]$reasons.Add('it already has a different PostgreSQL password') }
    if (-not [string]::IsNullOrWhiteSpace($user) -and $user.Trim() -ine 'postgres') { [void]$reasons.Add(("it uses the database user '{0}'" -f $user.Trim())) }
    if (-not [string]::IsNullOrWhiteSpace($address) -and $address.Trim() -notin @('127.0.0.1', 'localhost', '::1')) { [void]$reasons.Add(("it connects to the address '{0}'" -f $address.Trim())) }
    if (-not [string]::IsNullOrWhiteSpace($port) -and $port.Trim() -ne '5432') { [void]$reasons.Add(("it uses port {0}" -f $port.Trim())) }
    if ($reasons.Count -eq 0) { return [pscustomobject]@{ Decision = $(if ($passIsLocal) { 'Same' } else { 'FillBlank' }); Reasons = @() } }
    return [pscustomobject]@{ Decision = 'NeedsApproval'; Reasons = $reasons.ToArray() }
}

# Lists registered PostgreSQL profiles whose Pass needs approval before TPM
# writes the local postgres password (see Get-PostgresProfilePassDecision).
# Read-only. Unreadable profiles are skipped here; the setup pass reports them.
function Get-PostgresProfilePassConflicts {
    param([object[]]$ProfileFiles = @(), [Parameter(Mandatory)][string]$SuperPasswordPlain)
    $conflicts = New-Object System.Collections.Generic.List[object]
    foreach ($pf in @($ProfileFiles)) {
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile -or -not (Test-GameNeedsPostgres $doc)) { continue }
            if ($null -eq (Get-PostgresFieldValue $doc 'Pass')) { continue }
            $decision = Get-PostgresProfilePassDecision -Doc $doc -SuperPasswordPlain $SuperPasswordPlain
            if ($decision.Decision -ne 'NeedsApproval') { continue }
            [void]$conflicts.Add([pscustomobject]@{
                Path = [string]$pf.FullName
                ProfileName = [string]$pf.BaseName
                Label = (Get-TpmGameDisplayLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName)
                Reasons = @($decision.Reasons)
            })
        } catch {
            continue
        }
    }
    return $conflicts.ToArray()
}

# FIX63/FIX71: the short result screen at the end of PostgreSQL setup (menu 11).
# Default view: a heading, one count line, the games grouped by what happened
# (games with the same outcome share one line), one next step, with a blank line
# between the parts. Every technical fact is in the details view
# (Write-TpmPostgresSetupDetails, key D) and in the log (Write-TpmPostgresSetupResultLog).
# All text goes through Write-TpmText, which measures the console on every call,
# so the screen reflows when the window is resized.
function Join-TpmPostgresSetupNames {
    param([string[]]$Names)
    $list = @($Names | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if ($list.Count -le 1) { return ($list -join '') }
    return ((@($list[0..($list.Count - 2)]) -join ', ') + ' and ' + $list[$list.Count - 1])
}

function Get-TpmPostgresSetupGameName {
    param([Parameter(Mandatory)]$Game)
    if ([string]::IsNullOrWhiteSpace([string]$Game.Name)) { return [string]$Game.Key }
    return [string]$Game.Name
}

# The per-game records of a setup result. A result with none (no GameOutcomes at all, or a null in the list) gives an empty
# list: @($null) would otherwise be one null "game" and crash the log and the screens.
function Get-TpmPostgresSetupGames {
    param([Parameter(Mandatory)]$Result)
    return @(@(Get-TpmTransactionField -Object $Result -Name 'GameOutcomes' -Default @()) | Where-Object { $null -ne $_ })
}

# One plain sentence for the games that share an outcome.
function Get-TpmPostgresSetupOutcomeLine {
    param([Parameter(Mandatory)][string]$Outcome, [Parameter(Mandatory)][string[]]$Names)
    $many = (@($Names).Count -gt 1)
    $list = Join-TpmPostgresSetupNames -Names $Names
    if ($Outcome -eq 'CreatedFromBackup') {
        if ($many) { return ('Ready: {0}. The databases were created from the games'' own backups and checked.' -f $list) }
        return ('Ready: {0}. The database was created from the game''s own backup and checked.' -f $list)
    }
    if ($Outcome -eq 'WaitingForFirstStart') {
        if ($many) { return ('Profile ready: {0}. TeknoParrot makes their databases itself the first time each game starts.' -f $list) }
        return ('Profile ready: {0}. TeknoParrot makes its database itself the first time the game starts.' -f $list)
    }
    if ($many) { return ('Ready: {0}. The databases were already there and were checked.' -f $list) }
    return ('Ready: {0}. The database was already there and was checked.' -f $list)
}

# FIX71: every old per-game sentence, as the details view shows it: what happened to
# the database and what that means. Same facts as the Warnings and Checks of the
# transaction result, in plain words. What is true for every game (setup only looked
# the databases up) is stated once by Write-TpmPostgresSetupDetails, not here.
function Get-TpmPostgresSetupGameDetail {
    param([Parameter(Mandatory)]$Game)
    $happened = 'The database was already there. TeknoParrot Manager left it untouched.'
    if ($Game.Outcome -eq 'CreatedFromBackup') {
        $happened = 'The database did not exist. TeknoParrot Manager created it and restored the backup that comes with the game.'
    }
    if ($Game.Outcome -eq 'WaitingForFirstStart') {
        return [pscustomobject]@{
            Happened = 'The database does not exist yet and no starting database file came with the game. TeknoParrot Manager saved the connection settings in the profile and left the database to TeknoParrot (its "Automatically create Database" option).'
            Means = 'The profile is ready. TeknoParrot creates the database the first time the game starts.'
        }
    }
    $tables = ''
    $tableProperty = $Game.PSObject.Properties['TableCount']
    if ($null -ne $tableProperty -and [int]$tableProperty.Value -gt 0) { $tables = (' and found {0}' -f (Format-TpmCountNoun -Count ([int]$tableProperty.Value) -Singular 'table' -Plural 'tables')) }
    $means = ('TeknoParrot Manager connected with the game''s own settings{0}. The game is ready.' -f $tables)
    $unknown = $false
    $property = $Game.PSObject.Properties['AutoCreateUnknown']
    if ($null -ne $property) { $unknown = [bool]$property.Value }
    if ($unknown) { $means += ' This TeknoParrot build does not say whether it creates the database automatically.' }
    return [pscustomobject]@{ Happened = $happened; Means = $means }
}

# FIX71: the default screen shows less than the old one, so the whole old content
# is also written to the log, one line per item (the transaction result already
# holds redacted text). Runs for every path that shortens the screen, including the
# protected resume child that has no Details key.
function Write-TpmPostgresSetupResultLog {
    param([Parameter(Mandatory)]$Result)
    foreach ($game in @(Get-TpmPostgresSetupGames -Result $Result)) {
        Write-Log ('Postgres setup result: {0} [{1}] ({2}): {3}.' -f (Get-TpmPostgresSetupGameName -Game $game), $game.Key, $game.DbName, $game.Outcome)
    }
    foreach ($check in @($Result.FinalVerification.Checks)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$check)) { Write-Log ('Postgres setup check: {0}' -f $check) }
    }
    foreach ($warning in @($Result.Warnings)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$warning)) { Write-Log ('Postgres setup note: {0}' -f $warning) }
    }
    foreach ($action in @($Result.RecoveryActions)) {
        if ($null -ne $action -and -not [string]::IsNullOrWhiteSpace([string]$action.Label)) { Write-Log ('Postgres setup next step: {0}' -f $action.Label) }
    }
}

# A text as paragraphs of whole sentences that each wrap to at most MaxLines lines at Width. A sentence that is longer than
# that on its own stays whole.
function Get-TpmShortParagraphs {
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Text, [Parameter(Mandatory)][int]$Width, [int]$MaxLines = 5)
    $paragraphs = New-Object System.Collections.Generic.List[string]
    $current = ''
    foreach ($sentence in @([regex]::Split($Text.Trim(), '(?<=[.!?])\s+'))) {
        $candidate = if ($current.Length -gt 0) { $current + ' ' + $sentence } else { $sentence }
        $wrapped = Split-TextForMenuWidth -Text $candidate -Width $Width
        if ($current.Length -gt 0 -and @($wrapped).Count -gt $MaxLines) {
            [void]$paragraphs.Add($current)
            $current = $sentence
        } else {
            $current = $candidate
        }
    }
    if ($current.Length -gt 0) { [void]$paragraphs.Add($current) }
    return $paragraphs.ToArray()
}

function Write-TpmPostgresSetupResult {
    param([Parameter(Mandatory)]$Result, [switch]$OfferDetails)
    Write-TpmPostgresSetupResultLog -Result $Result
    Write-Host ''
    Write-TpmText -Text 'PostgreSQL setup finished.' -Color Cyan -Indent 2 -MaxWidth 0
    Write-TpmText -Text ('Games set up: {0}. Databases created: {1}. Already set up: {2}.' -f $Result.Configured, $Result.DbCreated, $Result.AlreadyConfigured) -Color Green -Indent 2 -MaxWidth 0
    $games = @(Get-TpmPostgresSetupGames -Result $Result)
    $entries = New-Object System.Collections.Generic.List[object]
    # FIXDB27: when some games could not be made ready, first say how many are ready, then name the others (below the ready lines).
    $notReadyGames = @(Get-TpmTransactionField -Object $Result -Name 'NotReadyGames' -Default @() | Where-Object { $null -ne $_ })
    if ($notReadyGames.Count -gt 0) {
        $readyText = if ($games.Count -gt 0) { '{0} set up and checked, and ready.' -f (Format-TpmGameCount -Count $games.Count) } else { 'No game database was set up. Nothing was created.' }
        [void]$entries.Add(@{ Text = $readyText; Color = 'Green'; Indent = 4; Hanging = 2 })
    }
    foreach ($kind in @('CreatedFromBackup', 'AlreadyExisted', 'WaitingForFirstStart')) {
        $names = @($games | Where-Object { $_.Outcome -eq $kind } | ForEach-Object { Get-TpmPostgresSetupGameName -Game $_ })
        if ($names.Count -gt 0) { [void]$entries.Add(@{ Text = (Get-TpmPostgresSetupOutcomeLine -Outcome $kind -Names $names); Color = ''; Indent = 4; Hanging = 2 }) }
    }
    foreach ($sharedGame in @($games | Where-Object { $null -ne $_.PSObject.Properties['RenamedFrom'] -and -not [string]::IsNullOrWhiteSpace([string]$_.RenamedFrom) })) {
        [void]$entries.Add(@{ Text = ('Own database: {0} and {1} both used the database name {2}. They keep their saved progress in the same tables, so {0} now has its own database, {3}. Nothing was deleted or overwritten.' -f (Get-TpmPostgresSetupGameName -Game $sharedGame), $sharedGame.SharesWith, $sharedGame.RenamedFrom, $sharedGame.DbName); Color = 'Cyan'; Indent = 4; Hanging = 2 })
    }
    if ($notReadyGames.Count -gt 0) {
        $notReadyList = Join-TpmPostgresSetupNames -Names @($notReadyGames | ForEach-Object { Get-TpmPostgresSetupGameName -Game $_ })
        $notReadyReason = if ($notReadyGames.Count -gt 1) { 'No starting database file came with these games, so their databases cannot be built.' } else { 'No starting database file came with this game, so its database cannot be built.' }
        [void]$entries.Add(@{ Text = ('Could NOT be made ready: {0}. {1}' -f $notReadyList, $notReadyReason); Color = 'Yellow'; Indent = 4; Hanging = 2 })
    }
    $keptCount = @($Result.PassKeptProfiles).Count
    if ($keptCount -gt 0) {
        $keptText = if ($keptCount -eq 1) { '1 game kept its own PostgreSQL password or settings, so TeknoParrot Manager did not change it.' } else { ('{0} games kept their own PostgreSQL password or settings, so TeknoParrot Manager did not change them.' -f $keptCount) }
        $keptText += $(if ($OfferDetails) { ' Press D to see which.' } else { ' The log says which.' })
        [void]$entries.Add(@{ Text = $keptText; Color = 'Yellow'; Indent = 2; Hanging = 0 })
    }
    if ($entries.Count -gt 0) {
        Write-Host ''
        # Never more than 5 lines in a row: an entry that would wrap to more than 5 lines is split at sentence ends, and when the
        # next paragraph would make a longer block (a narrow console wraps more), a blank line goes before it.
        $maxRun = 5
        $run = 0
        foreach ($entry in $entries) {
            $entryWidth = [Math]::Max(20, (Get-TpmResetRestoreLineWidth) - $entry.Indent - $entry.Hanging - 1)
            foreach ($paragraph in @(Get-TpmShortParagraphs -Text $entry.Text -Width $entryWidth -MaxLines $maxRun)) {
                # Split-TextForMenuWidth returns its lines as one array object, so they are counted after the assignment.
                $wrapped = Split-TextForMenuWidth -Text $paragraph -Width $entryWidth
                $height = @($wrapped).Count
                if ($run -gt 0 -and ($run + $height) -gt $maxRun) { Write-Host ''; $run = 0 }
                Write-TpmText -Text $paragraph -Color $entry.Color -Indent $entry.Indent -HangingIndent $entry.Hanging -MaxWidth 0
                $run += $height
            }
        }
    }
    Write-Host ''
    if ($notReadyGames.Count -gt 0) {
        Write-TpmText -Text 'Next: put the pg_backup folder back for the games that are not ready, then run PostgreSQL setup again.' -Color DarkGray -Indent 2 -MaxWidth 0
    } elseif (@($games | Where-Object { $_.Outcome -eq 'WaitingForFirstStart' }).Count -gt 0) {
        Write-TpmText -Text 'Next: open TeknoParrot and start the game once. TeknoParrot makes the database of each profile-ready game itself.' -Color DarkGray -Indent 2 -MaxWidth 0
    } else {
        Write-TpmText -Text 'Next: open TeknoParrot and start any game. Every game database was checked and is ready.' -Color DarkGray -Indent 2 -MaxWidth 0
    }
    if ($OfferDetails) {
        Write-Host ''
        Write-TpmText -Text '[D] Show details' -Color White -Indent 2 -MaxWidth 0
    }
}

# The details view (FIX71): a common note once, then one short block per game, the
# notes that belong to no single game, what to do next, and the three counter lines
# the smoke harness reads. Wrapped to the console width.
function Write-TpmPostgresSetupDetails {
    param([Parameter(Mandatory)]$Result)
    $games = @(Get-TpmPostgresSetupGames -Result $Result)
    $blocks = New-Object System.Collections.Generic.List[object]
    if (-not [string]::IsNullOrWhiteSpace([string]$Result.Summary)) {
        [void]$blocks.Add(@{ Heading = 'Summary'; Lines = @([string]$Result.Summary) })
    }
    if ($games.Count -gt 0) {
        [void]$blocks.Add(@{ Heading = 'What setup checked'; Lines = @('Setup connected to each game''s database with the settings saved in that game''s profile and counted its tables.') })
    }
    $gamePrefixes = New-Object System.Collections.Generic.List[string]
    foreach ($game in $games) {
        $name = Get-TpmPostgresSetupGameName -Game $game
        [void]$gamePrefixes.Add(('{0} [{1}] ({2}): ' -f $name, $game.Key, $game.DbName))
        $detail = Get-TpmPostgresSetupGameDetail -Game $game
        $lines = New-Object System.Collections.Generic.List[string]
        if (-not [string]::IsNullOrWhiteSpace([string]$game.DbName)) { [void]$lines.Add(('Database: {0}' -f $game.DbName)) }
        if (-not [string]::IsNullOrWhiteSpace([string]$game.Key)) { [void]$lines.Add(('Profile: {0}' -f $game.Key)) }
        [void]$lines.Add(('What happened: {0}' -f $detail.Happened))
        [void]$lines.Add(('What it means: {0}' -f $detail.Means))
        # FIX125: a backup that ended with known foreign-key warnings is only said here (and in the log), never on the main screen. FIXDB27: the links that were not made are named.
        $warningProperty = $game.PSObject.Properties['KnownWarningCount']
        if ($null -ne $warningProperty -and [int]$warningProperty.Value -gt 0) {
            [void]$lines.Add(('Backup: The game''s backup finished with {0}.' -f (Format-TpmCountNoun -Count ([int]$warningProperty.Value) -Singular 'warning' -Plural 'warnings')))
            $namesProperty = $game.PSObject.Properties['KnownConstraintNames']
            if ($null -ne $namesProperty -and @($namesProperty.Value).Count -gt 0) { [void]$lines.Add(('Links between tables that could not be made: {0}.' -f (@($namesProperty.Value) -join ', '))) }
        }
        [void]$blocks.Add(@{ Heading = $name; Lines = $lines.ToArray() })
    }
    # Anything the result says that belongs to no single game stays visible here.
    $other = New-Object System.Collections.Generic.List[string]
    foreach ($text in (@($Result.Warnings) + @($Result.FinalVerification.Checks))) {
        $item = [string]$text
        if ([string]::IsNullOrWhiteSpace($item)) { continue }
        $forGame = $false
        foreach ($prefix in $gamePrefixes) { if ($item.StartsWith($prefix, [System.StringComparison]::Ordinal)) { $forGame = $true; break } }
        if (-not $forGame) { [void]$other.Add($item) }
    }
    if ($other.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Other notes'; Lines = $other.ToArray(); Color = 'Yellow' }) }
    $next = @(@($Result.RecoveryActions) | Where-Object { $null -ne $_ -and -not [string]::IsNullOrWhiteSpace([string]$_.Label) } | ForEach-Object { [string]$_.Label })
    if ($next.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'What to do next'; Lines = $next; Color = 'DarkGray' }) }
    Write-Host ''
    Write-TpmText -Text 'Details' -Color Cyan -Indent 2 -MaxWidth 0
    Show-TpmDetailBlocks -Blocks $blocks.ToArray() -Note 'TeknoParrot Manager checked each database by connecting to it with the game''s own settings. It did not start any game.'
    Write-TpmText -Text 'Totals' -Color Cyan -Indent 2 -MaxWidth 0
    # FIX128 (N9): the first screen says "Games set up: N". The same number is shown here under that name too. The three old lines
    # below keep their names because the smoke checks read them ("Fields updated", "Databases created", "Profiles unchanged").
    Write-Host ("    Games set up           : {0}" -f $Result.Configured) -ForegroundColor Green
    Write-Host ("    Fields updated         : {0}" -f $Result.Configured) -ForegroundColor Green
    Write-Host ("    Databases created      : {0}" -f $Result.DbCreated) -ForegroundColor Green
    Write-Host ("    Profiles unchanged     : {0}" -f $Result.AlreadyConfigured) -ForegroundColor DarkGray
    if ($Result.Errors -gt 0) { Write-TpmText -Text ('Errors: {0} (see TeknoParrot-Manager.log)' -f $Result.Errors) -Color Red -Indent 4 -MaxWidth 0 }
    Write-Host ''
}

# FIX44: one line per reason a PostgreSQL setup stopped (blocked profile, failed
# database creation). Reasons are stored in TechnicalDetails.FailureReasons,
# already redacted, so the screen and the support package show the same text.
function Get-PostgresSetupFailureReasonLines {
    param($TransactionResult)
    if ($null -eq $TransactionResult) { return @() }
    $details = $TransactionResult.TechnicalDetails
    if ($null -eq $details) { return @() }
    $property = $details.PSObject.Properties['FailureReasons']
    if ($null -eq $property -or $null -eq $property.Value) { return @() }
    return @(@($property.Value) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | ForEach-Object { [string]$_ })
}

# FIX126: the screen for a setup that did not finish. The main screen has the plain summary only (plus, for a profile-check stop, the short plain reasons). Each reason (it can hold raw tool
# text: error blocks, names, exit codes) goes to the log and to the Details view (key D). The protected resume child cannot
# prompt, so it offers no D and points to the log.
function Write-TpmPostgresSetupFailure {
    param([Parameter(Mandatory)]$Result, [switch]$OfferDetails)
    $reasons = @(Get-PostgresSetupFailureReasonLines -TransactionResult $Result)
    foreach ($reason in $reasons) { Write-Log ('Postgres setup failure reason: {0}' -f $reason) }
    Write-Log ('Postgres setup failure summary: {0}' -f $Result.Summary)
    Write-Host ("  PostgreSQL setup did not complete successfully: {0}" -f $Result.Summary) -ForegroundColor Red
    # N18A: a setup that stopped at the profile check names each blocked game and its one-line reason right here (they are short, plain
    # sentences). Raw tool text (several lines, paths, tool names) never goes on this screen; it stays in the log and in Details.
    if ([string](Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'TechnicalDetails') -Name 'Stage' -Default '') -ceq 'Preflight') {
        $blockedLines = @($reasons | Where-Object { $_ -notmatch '[\r\n]' -and (Test-TpmTransactionUserSafeSummary -Summary $_) })
        if ($blockedLines.Count -gt 0) {
            Write-Host '  These games need a fix first:' -ForegroundColor Yellow
            foreach ($blockedLine in $blockedLines) { Write-Host ('    {0}' -f $blockedLine) -ForegroundColor Yellow }
        }
    }
    if ($reasons.Count -eq 0) { return }
    if (-not $OfferDetails) {
        Write-Host '  The log says why.' -ForegroundColor DarkGray
        return
    }
    $answer = [string](Read-HostSafe '  Press D to see why, or Enter to continue')
    if ($answer.Trim().ToUpperInvariant() -ne 'D') { return }
    $blocks = New-Object System.Collections.Generic.List[object]
    $stopLines = New-Object System.Collections.Generic.List[string]
    Add-TpmDetailLine -Lines $stopLines -Label 'Result' -Text ([string](Get-TpmTransactionField -Object $Result -Name 'Summary' -Default ''))
    Add-TpmDetailLine -Lines $stopLines -Label 'Outcome' -Text ([string](Get-TpmTransactionField -Object $Result -Name 'Outcome' -Default ''))
    Add-TpmDetailLine -Lines $stopLines -Label 'Reason code' -Text ([string](Get-TpmTransactionField -Object $Result -Name 'ReasonCode' -Default ''))
    Add-TpmDetailLine -Lines $stopLines -Label 'Stage' -Text ([string](Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'TechnicalDetails') -Name 'Stage' -Default ''))
    if ($stopLines.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'What stopped it'; Lines = $stopLines.ToArray() }) }
    $reasonLines = New-Object System.Collections.Generic.List[string]
    foreach ($reason in $reasons) { foreach ($piece in @(([string]$reason) -split '\r?\n')) { if (-not [string]::IsNullOrWhiteSpace($piece)) { [void]$reasonLines.Add($piece.Trim()) } } }
    [void]$blocks.Add(@{ Heading = 'Why it stopped'; Lines = $reasonLines.ToArray(); Color = 'Yellow' })
    $next = @(@(Get-TpmTransactionField -Object $Result -Name 'RecoveryActions' -Default @()) | Where-Object { $null -ne $_ -and -not [string]::IsNullOrWhiteSpace([string](Get-TpmTransactionField -Object $_ -Name 'Label' -Default '')) } | ForEach-Object { [string](Get-TpmTransactionField -Object $_ -Name 'Label' -Default '') })
    if ($next.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'What to do next'; Lines = $next; Color = 'DarkGray' }) }
    Write-Host ''
    Write-TpmText -Text 'Details' -Color Cyan -Indent 2 -MaxWidth 0
    Show-TpmDetailBlocks -Blocks $blocks.ToArray()
}

# Main per-game Postgres setup pass. All profiles are preflighted and all
# database existence checks must be verified before any profile write. A blank
# Pass is filled with the local postgres password; a different non-blank Pass,
# or a profile that names another user, address or port, is replaced only when
# its path is in -ApprovedPassReplacements (FIX36 S4); otherwise it is kept and
# reported. The caller must supply a verified recovery backup.
# Databases created for a profile are coupled to the profile write: a later
# profile failure removes every database created by this pass before returning.
function Invoke-PostgresGameSetup {
    param([string]$UserProfilesDir, [string]$SuperPasswordPlain, $RecoveryBackup = $null, [string[]]$ApprovedPassReplacements = @())
    # Two TeknoParrot Manager windows must not set up PostgreSQL at the same time.
    $lockTaken = [bool](Enter-PostgresRecoveryLock)
    try {
        return (Invoke-PostgresGameSetupLocked -UserProfilesDir $UserProfilesDir -SuperPasswordPlain $SuperPasswordPlain -RecoveryBackup $RecoveryBackup -ApprovedPassReplacements $ApprovedPassReplacements -LockTaken $lockTaken)
    } finally {
        if ($lockTaken) { Exit-PostgresRecoveryLock }
    }
}
function Invoke-PostgresGameSetupLocked {
    param([string]$UserProfilesDir, [string]$SuperPasswordPlain, $RecoveryBackup = $null, [string[]]$ApprovedPassReplacements = @(), [bool]$LockTaken = $false)
    $results = [ordered]@{
        Configured = 0
        DbCreated = 0
        AlreadyConfigured = 0
        Errors = 0
        RecoveryBlocked = $false
        BackupPath = $null
        DatabaseRollbackVerified = $false
        ProfileRollbackVerified = $false
        PassKeptProfiles = @()
        TransactionResult = $null
    }
    $approvedPassPaths = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($approvedPath in @($ApprovedPassReplacements)) {
        if (-not [string]::IsNullOrWhiteSpace($approvedPath)) { [void]$approvedPassPaths.Add([System.IO.Path]::GetFullPath($approvedPath)) }
    }
    $passKept = New-Object System.Collections.Generic.List[string]
    # FIX130 (S11): plain notes about an unfinished earlier setup; they go to the Details of whatever result this run returns.
    $journalNotes = New-Object System.Collections.Generic.List[string]
    $finish = {
        param(
            [string]$Outcome,
            [string]$ProductState,
            [string]$Summary,
            [string[]]$Items = @(),
            [string[]]$ChangedItems = @(),
            [string[]]$CompletedItems = @(),
            [string[]]$FailedItems = @(),
            [string[]]$UnattemptedItems = @(),
            [string[]]$SkippedItems = @(),
            [string[]]$UnknownItems = @(),
            [bool]$MutationStarted = $false,
            [bool]$MutationCompleted = $false,
            $Backup = $null,
            $PreState = $null,
            [bool]$FinalAttempted = $false,
            [bool]$FinalPassed = $false,
            [object[]]$FinalChecks = @(),
            [object[]]$FinalFailedItems = @(),
            $Rollback = $null,
            $Cleanup = $null,
            [string]$ReasonCode = $null,
            $TechnicalDetails = $null,
            [string[]]$Errors = @(),
            [string[]]$Warnings = @(),
            [object[]]$RecoveryActions = @()
        )
        foreach ($journalNote in @($journalNotes)) { $Warnings += $journalNote }
        # FIX63: one record per game for the short result screen. Presentation only;
        # the Warnings, FinalChecks and RecoveryActions below are unchanged.
        $gameOutcomes = New-Object System.Collections.Generic.List[object]
        if ($Outcome -in @('SUCCEEDED','NO_OP')) {
            foreach ($plan in $preflightPlans) {
                $label = Get-TpmGameDisplayLabel -ProfilePath $plan.Profile.FullName -Fallback $plan.Profile.BaseName
                $gameOutcome = if ($plan.CreateMode -eq 'RestoreBundledBackup') { 'CreatedFromBackup' } elseif ($plan.PSObject.Properties['AwaitingFirstStart'] -and [bool]$plan.AwaitingFirstStart) { 'WaitingForFirstStart' } else { 'AlreadyExisted' }
                $tableCount = if ($plan.PSObject.Properties['VerifiedTableCount']) { [int]$plan.VerifiedTableCount } else { 0 }
                $constraintNames = if ($plan.PSObject.Properties['KnownRestoreConstraintNames']) { @($plan.KnownRestoreConstraintNames) } else { @() }
                [void]$gameOutcomes.Add([pscustomobject]@{ Key = [string]$plan.Profile.BaseName; Name = [string]$label; DbName = [string]$plan.DbName; Outcome = $gameOutcome; AutoCreateUnknown = ($null -eq $plan.AutoCreate); TableCount = $tableCount; KnownConstraintNames = $constraintNames; KnownWarningCount = $(if ($plan.PSObject.Properties['KnownRestoreWarningCount']) { [int]$plan.KnownRestoreWarningCount } else { 0 }); RenamedFrom = $(if ($plan.PSObject.Properties['SharesWithLabel'] -and $plan.SharesWithLabel) { [string]$plan.OriginalDbName } else { '' }); SharesWith = $(if ($plan.PSObject.Properties['SharesWithLabel'] -and $plan.SharesWithLabel) { [string]$plan.SharesWithLabel } else { '' }) })
                if ($plan.PSObject.Properties['SharesWithLabel'] -and $plan.SharesWithLabel) {
                    $Warnings += ('Own database for {0}: it and {1} both used the database name {2}. The two games keep their saved progress in the same tables, so one database cannot hold both. {0} now has its own database, {3}. {2} was not changed and nothing was deleted or overwritten.' -f $label, $plan.SharesWithLabel, $plan.OriginalDbName, $plan.DbName)
                }
                $capabilityNote = if ($null -eq $plan.AutoCreate) { ' This TeknoParrot build does not say whether it creates the database automatically.' } else { '' }
                if ($plan.CreateMode -eq 'RestoreBundledBackup') {
                    $limitationNote = if ($plan.PSObject.Properties['KnownRestoreLimitation']) { ' ' + [string]$plan.KnownRestoreLimitation } else { '' }
                    # N18A: several bundled backups: say which one was used (file name and its folder only, no full path).
                    if ([int]$plan.BackupCandidateCount -gt 1) {
                        $usedNote = if ($plan.BackupNewestHasTime) { 'so the newest one was used' } else { 'their names do not say which is newest, so one was picked by name' }
                        $limitationNote = (' The game came with {0} backup files, {1}: {2} (in the folder {3}).' -f [int]$plan.BackupCandidateCount, $usedNote, [System.IO.Path]::GetFileName([string]$plan.BackupFile), [System.IO.Path]::GetFileName([System.IO.Path]::GetDirectoryName([string]$plan.BackupFile))) + $limitationNote
                    }
                    $Warnings += ('{0} [{1}] ({2}): the database did not exist. TeknoParrot Manager created it and restored the backup bundled with the game.{3}{4}' -f $label, $plan.Profile.BaseName, $plan.DbName, $limitationNote, $capabilityNote)
                } elseif ($null -eq $plan.AutoCreate) {
                    $Warnings += ('{0} [{1}] ({2}): this TeknoParrot build does not say whether it creates the database automatically. The database already existed and was left untouched.' -f $label, $plan.Profile.BaseName, $plan.DbName)
                }
                if ($gameOutcome -eq 'WaitingForFirstStart') {
                    $FinalChecks += ('{0} [{1}] ({2}): profile ready. TeknoParrot makes the database the first time the game starts.' -f $label, $plan.Profile.BaseName, $plan.DbName)
                } else {
                    $FinalChecks += ('{0} [{1}] ({2}): ready. Connected with the game''s own profile settings and found {3} tables.' -f $label, $plan.Profile.BaseName, $plan.DbName, $tableCount)
                }
            }
            $waitingCount = @($gameOutcomes | Where-Object { $_.Outcome -eq 'WaitingForFirstStart' }).Count
            if ($waitingCount -gt 0) { $Summary = $Summary + (' TeknoParrot makes the database of {0} itself the first time the game starts.' -f (Format-TpmGameCount -Count $waitingCount)) }
        }
        # FIXDB27: a game that was left out of this run (no starting database file) means the run is never a clean success.
        $notReadyGames = @()
        if ($Outcome -in @('SUCCEEDED','NO_OP') -and $excludedGames.Count -gt 0) {
            $notReadyGames = @($excludedGames.ToArray())
            $excludedIds = @($notReadyGames | ForEach-Object { 'profile:' + $_.Key })
            # Plain statements on purpose (no if-expression assigned to a typed parameter, no rebuilt array): the earlier if-expression form
            # is the suspected cause of "Argument types do not match" in Windows PowerShell 5.1 (not confirmed without a run).
            $wasSucceeded = ($Outcome -eq 'SUCCEEDED')
            $Items += $excludedIds
            $SkippedItems += $excludedIds
            if ($preflightPlans.Count -gt 0) {
                $Summary = 'Some games are ready, but some could not be made ready because no starting database file came with them. Open Details to see which.'
            } else {
                $Summary = 'No game database was set up. No starting database file came with the games that need one, so nothing was created or changed. Open Details to see which.'
            }
            if ($wasSucceeded) {
                $Outcome = 'PARTIAL_APPLIED'
                $ProductState = 'PARTIAL_KNOWN'
            } else {
                $Outcome = 'ACTION_REQUIRED'
                $ProductState = 'UNCHANGED'
            }
            $ReasonCode = 'POSTGRES_SOME_GAMES_NOT_READY'
            $MutationCompleted = $false
            foreach ($notReady in $notReadyGames) {
                $Warnings += ('{0} [{1}] ({2}): not made ready. No starting database file came with this game, so its database cannot be built. Nothing was created or changed for it.' -f $notReady.Name, $notReady.Key, $notReady.DbName)
            }
            $RecoveryActions += @{ Id = 'NoStartingFile'; Label = 'For each game that was not made ready, put the game''s pg_backup folder back, then run PostgreSQL setup again.' }
        }
        if (@($results.PassKeptProfiles).Count -gt 0) {
            $Warnings += ('Kept the existing PostgreSQL password or connection settings in {0} profile(s) because replacing them was not approved: {1}.' -f @($results.PassKeptProfiles).Count, (@($results.PassKeptProfiles) -join ', '))
        }
        $tx = New-TpmProfileTransactionResult `
            -WorkflowKey 'PostgresSetup' `
            -OperationKey 'ConfigureProfilesAndCreateMissingDatabases' `
            -Outcome $Outcome `
            -ProductState $ProductState `
            -Summary $Summary `
            -Items $Items `
            -ChangedItems $ChangedItems `
            -CompletedItems $CompletedItems `
            -FailedItems $FailedItems `
            -UnattemptedItems $UnattemptedItems `
            -SkippedItems $SkippedItems `
            -UnknownItems $UnknownItems `
            -MutationStarted:$MutationStarted `
            -MutationCompleted:$MutationCompleted `
            -Backup $Backup `
            -PreState $PreState `
            -FinalAttempted:$FinalAttempted `
            -FinalPassed:$FinalPassed `
            -FinalChecks $FinalChecks `
            -FinalFailedItems $FinalFailedItems `
            -Rollback $Rollback `
            -Cleanup $Cleanup `
            -ReasonCode $ReasonCode `
            -TechnicalDetails $TechnicalDetails `
            -Errors $Errors `
            -Warnings $Warnings `
            -RecoveryActions $RecoveryActions
        foreach ($property in @('Configured','DbCreated','AlreadyConfigured','Errors','RecoveryBlocked','BackupPath','DatabaseRollbackVerified','ProfileRollbackVerified','PassKeptProfiles')) {
            $tx | Add-Member -NotePropertyName $property -NotePropertyValue $results[$property] -Force
        }
        $tx | Add-Member -NotePropertyName GameOutcomes -NotePropertyValue @($gameOutcomes.ToArray()) -Force
        $tx | Add-Member -NotePropertyName NotReadyGames -NotePropertyValue @($notReadyGames) -Force
        $tx | Add-Member -NotePropertyName TransactionResult -NotePropertyValue $tx -Force
        $results.TransactionResult = $tx
        return $tx
    }
    if (-not $LockTaken) {
        $results.Errors++
        $results.RecoveryBlocked = $true
        Write-Log 'Postgres setup: another TeknoParrot Manager window is changing PostgreSQL, so this setup did not start.'
        return (& $finish `
            -Outcome 'FAILED_BEFORE_MUTATION' `
            -ProductState 'UNCHANGED' `
            -Summary 'PostgreSQL setup did not start because another TeknoParrot Manager window is changing PostgreSQL. Wait for it to finish, then run setup again. Nothing was changed.' `
            -Items @('postgres-setup') `
            -UnattemptedItems @('postgres-setup') `
            -FinalAttempted:$false `
            -FinalPassed:$false `
            -ReasonCode 'POSTGRES_BUSY' `
            -TechnicalDetails ([pscustomobject]@{ Stage='RecoveryLock'; Error='The PostgreSQL repair lock is held by another TeknoParrot Manager window.' }))
    }
    $creationModes = @('RestoreBundledBackup')
    $preflightPlans = New-Object System.Collections.Generic.List[object]
    $excludedGames = New-Object System.Collections.Generic.List[object]
    $dbState = @{}
    $caseVariantState = @{}
    $preflightBlocked = $false
    $preflightError = $null
    $preflightReasons = New-Object System.Collections.Generic.List[object]
    # FIX44: every blocked profile is recorded with its own reason (log, screen
    # and technical details); a later profile no longer hides an earlier one.
    $addPreflightReason = {
        param([string]$ProfileName, [string]$Label, [string]$Reason)
        $safeReason = ConvertTo-PostgresRedactedText -Text $Reason -Secrets @($SuperPasswordPlain)
        $text = if ([string]::IsNullOrWhiteSpace($Label) -or $Label -eq $ProfileName) { ('{0}: {1}' -f $ProfileName, $safeReason) } else { ('{0} [{1}]: {2}' -f $Label, $ProfileName, $safeReason) }
        [void]$preflightReasons.Add([pscustomobject]@{ Profile = $ProfileName; Label = $Label; Reason = $safeReason; Text = $text })
        Write-Log ("Postgres: preflight blocked for {0}: {1} No profile write was attempted." -f $ProfileName, $safeReason)
    }
    # FIX130 (S11): a note left by an earlier setup that did not finish. This is read-only: nothing is changed before the recovery
    # backup is verified. A note that cannot be read, or databases it names that cannot be checked, stop setup before any change.
    $journalPath = Get-PostgresSetupJournalPath -RecoveryBackup $RecoveryBackup
    $journalFound = Read-PostgresSetupJournal -Path $journalPath
    $journalCreatingNames = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
    $journalExistingNames = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
    $journalPresentCreated = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
    $recoveryDroppedItems = New-Object System.Collections.Generic.List[string]
    $journalBlock = $null
    if ($journalFound.Status -eq 'Unreadable') {
        $journalBlock = [pscustomobject]@{
            Code = 'POSTGRES_SETUP_JOURNAL_UNREADABLE'
            Summary = 'PostgreSQL setup stopped before changing anything. TeknoParrot Manager found a note from an earlier setup that it cannot read, so it cannot tell what that setup left behind.'
            Reason = ('The setup journal could not be read: {0}' -f (ConvertTo-PostgresRedactedText -Text ([string]$journalFound.Error) -Secrets @($SuperPasswordPlain)))
        }
    } else {
        foreach ($journalEntry in @($journalFound.Entries)) {
            $journalState = $null
            try {
                $journalState = Get-PostgresDatabaseState -DbName ([string]$journalEntry.Database) -SuperPasswordPlain $SuperPasswordPlain
                if (-not $journalState.Verified) { throw 'The database existence result was not verified.' }
            } catch {
                $journalBlock = [pscustomobject]@{
                    Code = 'POSTGRES_SETUP_JOURNAL_STATE_UNVERIFIED'
                    Summary = 'PostgreSQL setup stopped before changing anything. A note from an earlier setup is there, and TeknoParrot Manager could not check the databases that note names.'
                    Reason = ('The state of database {0} named by the setup journal could not be verified: {1}' -f $journalEntry.Database, (ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)))
                }
                break
            }
            if ([string]$journalEntry.Stage -ceq 'Creating') {
                [void]$journalCreatingNames.Add([string]$journalEntry.Database)
                if ($journalState.Exists) { [void]$journalExistingNames.Add([string]$journalEntry.Database) }
            } elseif ($journalState.Exists) {
                [void]$journalPresentCreated.Add([string]$journalEntry.Database)
            }
        }
    }
    if ($null -ne $journalBlock) {
        $results.Errors++
        $results.RecoveryBlocked = $true
        Write-Log ('Postgres setup: stopped before any change because of the note from an earlier setup. {0}' -f $journalBlock.Reason)
        return (& $finish `
            -Outcome 'FAILED_BEFORE_MUTATION' `
            -ProductState 'UNCHANGED' `
            -Summary $journalBlock.Summary `
            -Items @() `
            -MutationStarted:$false `
            -MutationCompleted:$false `
            -FinalAttempted:$false `
            -FinalPassed:$false `
            -ReasonCode $journalBlock.Code `
            -TechnicalDetails ([pscustomobject]@{ Stage='SetupJournal'; Error=$journalBlock.Reason; JournalPath=[string]$journalFound.Path; FailureReasons=@($journalBlock.Reason) }) `
            -Errors @($journalBlock.Reason) `
            -RecoveryActions @(@{ Id='Review'; Label='Open Details. Do not change anything by hand; ask for help before you try again.' }))
    }
    if (@($journalFound.Entries).Count -gt 0) {
        $completeNoteCount = @($journalFound.Entries | Where-Object { [string]$_.Stage -ceq 'Created' }).Count
        Write-Log ('Postgres setup: an earlier setup left a journal: {0} unfinished database(s) found, {1} complete database(s) noted.' -f $journalExistingNames.Count, $completeNoteCount)
        if ($journalExistingNames.Count -gt 0) {
            $many = ($journalExistingNames.Count -gt 1)
            Write-TpmText -Text 'An earlier setup did not finish.' -Color Yellow -Indent 2
            Write-TpmText -Text ('It was building {0}. TeknoParrot Manager made {1} itself, and {2} may be only partly filled.' -f (Format-TpmCountNoun -Count $journalExistingNames.Count -Singular 'game database' -Plural 'game databases'), $(if ($many) { 'them' } else { 'it' }), $(if ($many) { 'they' } else { 'it' })) -Color Yellow -Indent 2
            Write-TpmText -Text ('TeknoParrot Manager will remove only {0} and build {1} again. Nothing else is touched.' -f $(if ($many) { 'those unfinished copies' } else { 'that unfinished copy' }), $(if ($many) { 'them' } else { 'it' })) -Color Yellow -Indent 2
        }
        if ($completeNoteCount -gt 0) {
            Write-TpmText -Text ('An earlier setup also finished building {0} completely. TeknoParrot Manager keeps {1}.' -f (Format-TpmCountNoun -Count $completeNoteCount -Singular 'game database' -Plural 'game databases'), $(if ($completeNoteCount -gt 1) { 'them' } else { 'it' })) -Color Yellow -Indent 2
        }
    }
    try {
        $profileSetupStarted = $null
        $profileSetupCurrent = 0
        $profileSetupTotal = 0
        $relBinPath = $script:PostgresBinDir.TrimEnd('\') + '\'
        $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'PostgreSQL setup profile discovery' -EnumerationErrorAction Stop | Sort-Object Name)
        $profileSetupStarted = Get-Date
        $profileSetupTotal = $profiles.Count
        $profileSetupCurrent = 0
        # Two profiles can name the same database (Golden Tee Live 2006 and Orange County Choppers Pinball both ship with one name). The two games
        # keep their saved progress in the same tables, so one database cannot hold both. The first profile (by name) keeps the name; every other
        # profile that uses it gets its own database below. Nothing is deleted from the shared one.
        $dbNameOwners = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::Ordinal)
        $usedDbNames = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
        foreach ($scanProfile in $profiles) {
            try {
                $scanDoc = Read-Xml $scanProfile.FullName
                if (-not $scanDoc.GameProfile -or -not (Test-GameNeedsPostgres $scanDoc)) { continue }
                $scanName = [string](Get-PostgresFieldValue $scanDoc 'DbName')
                if ([string]::IsNullOrWhiteSpace($scanName) -or -not (Test-SafePostgresDbName $scanName)) { continue }
                [void]$usedDbNames.Add($scanName)
                if (-not $dbNameOwners.ContainsKey($scanName)) { $dbNameOwners[$scanName] = [string]$scanProfile.BaseName }
            } catch { continue }
        }
        foreach ($pf in $profiles) {
            try {
                $profileSetupCurrent++
                Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL profile setup' -Current $profileSetupCurrent -Total $profiles.Count -StartedAt $profileSetupStarted
                $sourceHash = (Get-FileHash -LiteralPath $pf.FullName -Algorithm SHA256 -ErrorAction Stop).Hash
                $doc = Read-Xml $pf.FullName
                if (-not $doc.GameProfile -or -not (Test-GameNeedsPostgres $doc)) { continue }
                $dbName = Get-PostgresFieldValue $doc 'DbName'
                if ([string]::IsNullOrWhiteSpace($dbName) -or -not (Test-SafePostgresDbName $dbName)) { throw 'The profile has no safe PostgreSQL database name.' }
                if ($null -eq (Get-PostgresFieldValue $doc 'Pass')) { throw 'The profile has no PostgreSQL Pass field.' }
                $passDecision = Get-PostgresProfilePassDecision -Doc $doc -SuperPasswordPlain $SuperPasswordPlain
                $changed = $false
                # A profile the user chose to keep (K) is left exactly as it is: no field is filled, normalized or written.
                $keepAsIs = ($passDecision.Decision -eq 'NeedsApproval' -and -not $approvedPassPaths.Contains([System.IO.Path]::GetFullPath($pf.FullName)))
                $originalDbName = $dbName
                $sharesWithLabel = $null
                if ($dbNameOwners.ContainsKey($dbName) -and $dbNameOwners[$dbName] -cne [string]$pf.BaseName) {
                    $otherProfileName = $dbNameOwners[$dbName]
                    if ($keepAsIs) { throw ('The database name {0} is also used by the profile {1}, and this profile keeps its own PostgreSQL settings, so it cannot be given its own database. Change its database name in TeknoParrot, or let setup replace its settings.' -f $dbName, $otherProfileName) }
                    $ownDbName = $dbName + ($pf.BaseName -replace '[^A-Za-z0-9]', '')
                    if ($ownDbName.Length -gt 63) { $ownDbName = $ownDbName.Substring(0, 63) }
                    if (-not (Test-SafePostgresDbName $ownDbName) -or $usedDbNames.Contains($ownDbName)) { throw ('The database name {0} is also used by the profile {1}, and no free name could be made for this game.' -f $dbName, $otherProfileName) }
                    if (-not (Set-PostgresFieldValue $doc 'DbName' $ownDbName)) { throw 'The profile has no PostgreSQL DbName field.' }
                    $changed = $true
                    [void]$usedDbNames.Add($ownDbName)
                    $sharesWithLabel = Get-TpmGameDisplayLabel -ProfilePath (Join-Path $UserProfilesDir ($otherProfileName + '.xml')) -Fallback $otherProfileName
                    Write-Log ('Postgres setup: {0} and {1} both name the database {2}. They keep their progress in the same tables, so {0} gets its own database {3}; {2} is not changed.' -f $pf.BaseName, $otherProfileName, $dbName, $ownDbName)
                    $dbName = $ownDbName
                }
                foreach ($field in @(@('Path', $relBinPath), @('Address', '127.0.0.1'), @('Port', '5432'), @('User', 'postgres'))) {
                    if ($keepAsIs) { break }
                    # Blank fields are filled. A profile must also hold the exact local values the final verification demands (a profile with
                    # "localhost", "Postgres" or another bin folder could otherwise never finish setup). Address, Port and User of a profile
                    # the user had to decide on (NeedsApproval) are the user's own and stay.
                    $currentField = [string](Get-PostgresFieldValue $doc $field[0])
                    $differs = ($field[0] -eq 'Path' -or $passDecision.Decision -ne 'NeedsApproval') -and -not [string]::Equals($(if ($field[0] -eq 'Path') { $currentField -replace '\\{2,}', '\' } else { $currentField }), $(if ($field[0] -eq 'Path') { ([string]$field[1]) -replace '\\{2,}', '\' } else { [string]$field[1] }), [System.StringComparison]::Ordinal)
                    if ([string]::IsNullOrWhiteSpace($currentField) -or $differs) {
                        if (-not (Set-PostgresFieldValue $doc $field[0] $field[1])) { throw "The profile has no PostgreSQL $($field[0]) field." }
                        $changed = $true
                    }
                }
                $passKeptForProfile = $false
                if ($passDecision.Decision -eq 'FillBlank' -or ($passDecision.Decision -eq 'NeedsApproval' -and $approvedPassPaths.Contains([System.IO.Path]::GetFullPath($pf.FullName)))) {
                    if (-not (Set-PostgresFieldValue $doc 'Pass' $SuperPasswordPlain)) { throw 'The profile PostgreSQL Pass field could not be updated.' }
                    $changed = $true
                } elseif ($passDecision.Decision -eq 'NeedsApproval') {
                    $passKeptForProfile = $true
                    [void]$passKept.Add([string]$pf.BaseName)
                    $results.PassKeptProfiles = $passKept.ToArray()
                    Write-Log ("Postgres setup: kept the existing PostgreSQL password/connection settings in profile {0}; replacing them was not approved." -f $pf.BaseName)
                }
                if ($dbState.ContainsKey($dbName)) {
                    if ($dbState.psbase.Keys -cnotcontains $dbName) { throw 'PostgreSQL database names differing only by case cannot safely share this setup plan.' }
                    $state = $dbState[$dbName]
                }
                else {
                    $state = Get-PostgresDatabaseState -DbName $dbName -SuperPasswordPlain $SuperPasswordPlain
                    if (-not $state.Verified) { throw 'The database existence result was not verified.' }
                    $dbState[$dbName] = $state
                }
                $autoCreate = Get-PostgresAutoCreateCapability -Doc $doc
                $unfinishedOwned = [bool]($state.Exists -and $journalCreatingNames.Contains([string]$dbName))
                $backupFile = $null
                $backupCandidateCount = 0
                $backupNewestHasTime = $false
                $backupSelection = $null
                $encoding = $null
                $createMode = 'None'
                if (-not $state.Exists -or $unfinishedOwned) {
                    $gamePathNode = $doc.GameProfile.SelectSingleNode('GamePath')
                    $gamePath = if ($gamePathNode) { ([string]$gamePathNode.InnerText).Trim() } else { '' }
                    if ($autoCreate -eq $true) {
                        # FIX69 owner rule / N18B: a profile that says TeknoParrot creates the database is still created here from the game's bundled
                        # backup (the newest one when there are several; the alternate backups folder is not used here). A game in a folder path
                        # TeknoParrot Manager cannot read is not "no backup": it goes on to the path-too-long stop below.
                        $backupSelection = Get-PostgresBackupSelection -GamePath $gamePath
                        $backupFile = $backupSelection.Newest
                    }
                    if ($createMode -eq 'None') {
                        # FIX44 owner decision: a verified-absent database is created by TeknoParrot Manager from the game's bundled backup.
                        # FIXDB27: with no backup there is nothing to build the tables from, so the game cannot be made ready and setup
                        # stops with that reason (no empty database is made and nothing is left to TeknoParrot).
                        if (-not $caseVariantState.ContainsKey($dbName)) {
                            $caseVariantState[$dbName] = Get-PostgresDatabaseCaseVariantState -DbName $dbName -SuperPasswordPlain $SuperPasswordPlain
                        }
                        $caseState = $caseVariantState[$dbName]
                        if (-not $caseState.Verified) { throw ('The database {0} does not exist, but the existing database names could not be compared by case, so it cannot be created safely.' -f $dbName) }
                        if (@($caseState.Variants).Count -gt 0) { throw ('The database {0} does not exist, but a database whose name differs only by case ({1}) does. TeknoParrot Manager will not create it.' -f $dbName, (@($caseState.Variants) -join ', ')) }
                        $gameExeState = Get-TpmGameExeAvailability -GamePath $gamePath
                        if ($gameExeState -eq 'Missing') {
                            if ($autoCreate -eq $false) { throw 'The profile needs database creation but its game executable is unavailable.' }
                            throw ('The database {0} does not exist and the game executable could not be found, so TeknoParrot Manager cannot tell whether the game ships a backup for it. Connect the drive that holds the game, then run PostgreSQL setup again.' -f $dbName)
                        }
                        # Stop with a clear reason instead of creating an empty database when the backup files cannot be read.
                        if ($gameExeState -eq 'PathTooLong') {
                            throw ('The game for the database {0} is in a folder path longer than 259 characters, so TeknoParrot Manager cannot read its backup files. Move the game to a shorter folder path, then run PostgreSQL setup again.' -f $dbName)
                        }
                        if (-not $backupFile) {
                            # N18A/N18B: a game that ships several backups (identical dumps from different times) is restored from the newest one:
                            # newest date folder, then the latest valid time in the file name. Only here, for a missing database with no other
                            # backup, the alternate backups folder is also looked at. The file is named in the log and in the Details. If that
                            # restore fails the setup stops and says why; no other backup is tried.
                            $backupSelection = Get-PostgresBackupSelection -GamePath $gamePath -IncludeAlternate
                            $backupFile = $backupSelection.Newest
                        }
                        if ($backupSelection.CandidateCount -gt 1) {
                            $backupCandidateCount = [int]$backupSelection.CandidateCount
                            $backupNewestHasTime = [bool]$backupSelection.NewestHasTime
                            Write-Log ('Postgres setup: database {0}: the game has {1} backup files; {2}: {3}' -f $dbName, $backupCandidateCount, $(if ($backupNewestHasTime) { 'the newest one is used' } else { 'their names carry no time, so the one picked by name is used' }), $backupFile)
                        }
                        if (-not $backupFile) {
                            if ($unfinishedOwned) { throw ('The database {0} was left unfinished by an earlier setup and must be built again, but the game''s backup file could not be found. Nothing was removed. Connect the drive that holds the game, then run this setup again.' -f $dbName) }
                            if ($autoCreate -eq $true) {
                                # Owner rule (issue #350): TeknoParrot's own "Automatically create Database" handles a game that ships no starting database file.
                                # The profile is still set up here (connection settings and password); only the database is left for TeknoParrot to make.
                                $createMode = 'LeftToTeknoParrot'
                                Write-Log ('Postgres setup: {0} [{1}] ({2}): no starting database file came with the game; the profile is set up and TeknoParrot creates the database the first time the game starts.' -f (Get-TpmGameDisplayLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName), $pf.BaseName, $dbName)
                            } else {
                                # FIXDB27: one game with no starting file must not stop the others. It is left out of this run (nothing is created or
                                # changed for it) and reported as not ready; every other game is set up and checked as usual.
                                $excludedLabel = Get-TpmGameDisplayLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName
                                [void]$excludedGames.Add([pscustomobject]@{ Key = [string]$pf.BaseName; Name = [string]$excludedLabel; DbName = [string]$dbName; OriginalDbName = [string]$originalDbName })
                                Write-Log ('Postgres setup: {0} [{1}] ({2}) was left out: the database does not exist and no starting database file came with the game.' -f $excludedLabel, $pf.BaseName, $dbName)
                                continue
                            }
                        }
                        if ($createMode -eq 'None') {
                            $createMode = 'RestoreBundledBackup'
                            $encoding = Get-PostgresRestoreEncoding -DbName $originalDbName -BackupFile $backupFile
                        }
                    }
                }
                [void]$preflightPlans.Add([pscustomobject]@{
                    Profile = $pf
                    SourceHash = $sourceHash
                    Document = $doc
                    DbName = $dbName
                    BackupCandidateCount = $backupCandidateCount
                    BackupNewestHasTime = $backupNewestHasTime
                    # FIX130 (S11): a database the journal says an earlier unfinished run was creating is planned like a missing one;
                    # it is dropped (verified) after the recovery backup, before it is created again.
                    DbExists = ([bool]$state.Exists -and -not $unfinishedOwned)
                    JournalUnfinished = $unfinishedOwned
                    AutoCreate = $autoCreate
                    CreateMode = $createMode
                    BackupFile = $backupFile
                    Encoding = $encoding
                    OriginalDbName = $originalDbName
                    SharesWithLabel = $sharesWithLabel
                    Changed = $changed
                    # FIX36 S4: profiles the user had to decide on (NeedsApproval) are
                    # verified against their own connection values; every other profile
                    # keeps the original fixed checks below.
                    PassDecision = [string]$passDecision.Decision
                    PassKept = $passKeptForProfile
                    PlannedFields = @{
                        Path = [string](Get-PostgresFieldValue $doc 'Path')
                        Address = [string](Get-PostgresFieldValue $doc 'Address')
                        Port = [string](Get-PostgresFieldValue $doc 'Port')
                        User = [string](Get-PostgresFieldValue $doc 'User')
                        Pass = [string](Get-PostgresFieldValue $doc 'Pass')
                    }
                })
            } catch {
                $preflightBlocked = $true
                $results.Errors++
                $profileReason = [string]$_.Exception.Message
                $profileLabel = Get-TpmGameDisplayLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName
                & $addPreflightReason ([string]$pf.BaseName) ([string]$profileLabel) $profileReason
            }
        }
        # A missing database shared by several profiles is created once, and only when
        # one creation is unambiguous: every profile is created by TeknoParrot Manager
        # (none defers to TeknoParrot) and all of them resolve to the same bundled
        # backup (or all to none). Otherwise nothing is created and each profile says why.
        foreach ($group in @($preflightPlans | Group-Object -Property DbName)) {
            if ($group.Count -le 1) { continue }
            $members = @($group.Group)
            if ($members[0].DbExists) { continue }
            $sources = @($members | ForEach-Object { if ($_.BackupFile) { ([string]$_.BackupFile).ToUpperInvariant() } else { '' } } | Select-Object -Unique)
            if ($sources.Count -eq 1) { continue }
            $preflightBlocked = $true
            $profileKeys = @($members | ForEach-Object { $_.Profile.BaseName }) -join ', '
            foreach ($member in $members) {
                $results.Errors++
                $memberLabel = Get-TpmGameDisplayLabel -ProfilePath $member.Profile.FullName -Fallback $member.Profile.BaseName
                & $addPreflightReason ([string]$member.Profile.BaseName) ([string]$memberLabel) ('The database {0} does not exist yet and is shared by profiles {1}. TeknoParrot Manager cannot tell which bundled backup or tables the shared database must hold, so it will not create it.' -f $group.Name, $profileKeys)
            }
        }
        # A left-out game keeps the database name in its profile. When another game in this run uses that name, the left-out game would open (and write
        # into) the other game's database. It cannot be given its own database (it has no starting file), so setup stops here and changes nothing.
        foreach ($excludedGame in @($excludedGames.ToArray())) {
            $sharingPlans = @($preflightPlans | Where-Object { [string]$_.DbName -ceq [string]$excludedGame.OriginalDbName })
            if ($sharingPlans.Count -gt 0) {
                $preflightBlocked = $true
                $results.Errors++
                & $addPreflightReason ([string]$excludedGame.Key) ([string]$excludedGame.Name) ('The database {0} is also used by {1}, which is ready to be set up. This game has no starting database file, so TeknoParrot Manager cannot give it its own database, and it must not run on the other game''s data. Nothing was changed. Put this game''s pg_backup folder back, then run PostgreSQL setup again.' -f $excludedGame.OriginalDbName, ((@($sharingPlans | ForEach-Object { Get-TpmGameDisplayLabel -ProfilePath $_.Profile.FullName -Fallback $_.Profile.BaseName })) -join ' and '))
            }
        }
        if ($profiles.Count -gt 0) {
            # Every profile was visited, but a blocked one (its reason is recorded) means the check did not pass: never a green close.
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL profile setup' -Current $profileSetupCurrent -Total $profiles.Count -StartedAt $profileSetupStarted -Complete -Outcome $(if ($preflightBlocked) { 'Error' } else { 'Final' })
            $profileSetupStarted = $null
        }
    } catch {
        # An error that ends the check early closes the open step as failed; it never stays open or reads as done.
        if ($profileSetupStarted -and $profileSetupTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL profile setup' -Current $profileSetupCurrent -Total $profileSetupTotal -StartedAt $profileSetupStarted -Complete -Outcome Error }
        $preflightBlocked = $true
        $results.Errors++
        $enumerationReason = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
        [void]$preflightReasons.Add([pscustomobject]@{ Profile = ''; Label = ''; Reason = $enumerationReason; Text = ('Profile list: {0}' -f $enumerationReason) })
        Write-Log ("Postgres: profile enumeration or preflight failed before mutation: {0}" -f $enumerationReason)
    }
    if ($preflightBlocked) {
        $results.RecoveryBlocked = $true
        $preflightTexts = @($preflightReasons | ForEach-Object { [string]$_.Text })
        $preflightError = $preflightTexts -join ' | '
        return (& $finish `
            -Outcome 'FAILED_BEFORE_MUTATION' `
            -ProductState 'UNCHANGED' `
            -Summary 'PostgreSQL setup stopped before changing any databases or profiles.' `
            -Items @() `
            -MutationStarted:$false `
            -MutationCompleted:$false `
            -FinalAttempted:$false `
            -FinalPassed:$false `
            -ReasonCode 'POSTGRES_PREFLIGHT_FAILED' `
            -TechnicalDetails ([pscustomobject]@{ Stage='Preflight'; Error=$preflightError; BlockedProfiles=@($preflightReasons.ToArray()); FailureReasons=$preflightTexts }) `
            -Errors $preflightTexts `
            -RecoveryActions @(@{ Id='Review'; Label='Review the PostgreSQL setup details, then retry.' }))
    }
    $profileItems = @($preflightPlans | ForEach-Object { 'profile:' + $_.Profile.BaseName })
    $databaseItems = @($preflightPlans | Where-Object { -not $_.DbExists -and $creationModes -contains $_.CreateMode } | ForEach-Object { Get-PostgresSetupDatabaseItemId -DbName $_.DbName } | Select-Object -Unique)
    $items = @($profileItems + $databaseItems)
    $changedProfileItems = @($preflightPlans | Where-Object Changed | ForEach-Object { 'profile:' + $_.Profile.BaseName })
    $plannedDatabaseItems = @($databaseItems)
    $skippedItems = @($items | Where-Object { $changedProfileItems -notcontains $_ -and $plannedDatabaseItems -notcontains $_ })
    $recoveryBackupAttempted = ($null -ne $RecoveryBackup)
    if ($RecoveryBackup -and -not $RecoveryBackup.Verified) {
        $results.Errors++
        $results.RecoveryBlocked = $true
        $backupState = Get-PostgresRecoveryBackupState -RecoveryBackup $RecoveryBackup -Attempted $recoveryBackupAttempted
        $backupInfo = [pscustomobject]@{
            Required = $true
            Attempted = $backupState.Attempted
            Created = $backupState.Created
            Verified = $backupState.Verified
            RootPath = $backupState.Path
            Items = @()
            FailureStage = 'RecoveryEvidence'
            FailureCode = 'RECOVERY_EVIDENCE_REQUIRED'
        }
        return (& $finish `
            -Outcome 'FAILED_BEFORE_MUTATION' `
            -ProductState 'UNCHANGED' `
            -Summary 'PostgreSQL setup stopped before changing any databases or profiles.' `
            -Items $items `
            -UnattemptedItems $items `
            -Backup $backupInfo `
            -MutationStarted:$false `
            -MutationCompleted:$false `
            -FinalAttempted:$false `
            -FinalPassed:$false `
            -ReasonCode 'RECOVERY_EVIDENCE_REQUIRED' `
            -TechnicalDetails ([pscustomobject]@{ Stage='RecoveryEvidence'; Error='Verified recovery evidence is unavailable.' }) `
            -RecoveryActions @(@{ Id='Review'; Label='Review the protected recovery evidence, then retry.' }))
    }
    $databaseCreationReceipts = New-Object System.Collections.Generic.List[object]
    # FIXDB27: a game is ready only when its database works with the game's own saved settings. Connects as the game will, counts the
    # tables (at least the tables the bundled backup lists, when this run restored one) and keeps the count on the plan. Throws when not ready.
    $checkGameReady = {
        param($Plan)
        $profileDoc = Read-Xml $Plan.Profile.FullName
        $minTables = 1
        foreach ($receipt in @($databaseCreationReceipts | Where-Object { [string]$_.Database -ceq [string]$Plan.DbName })) {
            foreach ($listCommand in @($receipt.Commands | Where-Object { @($_.Arguments) -contains '--list' })) {
                $minTables = [Math]::Max($minTables, (Get-PostgresBackupListedTableCount -ListOutput ([string]$listCommand.Output)))
            }
        }
        $readiness = Get-PostgresGameDatabaseReadiness -Doc $profileDoc -MinTables $minTables
        if (-not $readiness.Ready) {
            # A game whose database TeknoParrot makes itself on first start (no starting file, "Automatically create Database") is waiting, not failing.
            if ($Plan.CreateMode -eq 'LeftToTeknoParrot' -and [string]$readiness.Error -match 'does not exist') {
                $Plan | Add-Member -NotePropertyName AwaitingFirstStart -NotePropertyValue $true -Force
                return
            }
            $readyLabel = Get-TpmGameDisplayLabel -ProfilePath $Plan.Profile.FullName -Fallback $Plan.Profile.BaseName
            throw ('{0} [{1}] ({2}) is not ready: {3}' -f $readyLabel, $Plan.Profile.BaseName, $Plan.DbName, $readiness.Error)
        }
        $Plan | Add-Member -NotePropertyName VerifiedTableCount -NotePropertyValue ([int]$readiness.TableCount) -Force
    }
    if ($changedProfileItems.Count -eq 0 -and $plannedDatabaseItems.Count -eq 0 -and $journalExistingNames.Count -eq 0) {
        $notReadyText = $null
        foreach ($readyPlan in $preflightPlans) {
            try { & $checkGameReady $readyPlan } catch { $notReadyText = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain); break }
        }
        if ($notReadyText) {
            $results.Errors++
            $results.RecoveryBlocked = $true
            Write-Log ('Postgres setup: a game database is not ready. {0}' -f $notReadyText)
            return (& $finish `
                -Outcome 'FAILED_BEFORE_MUTATION' `
                -ProductState 'UNCHANGED' `
                -Summary 'A game database is not ready, and TeknoParrot Manager changed nothing. Open Details to see which game and why.' `
                -Items $items `
                -FailedItems @($profileItems) `
                -MutationStarted:$false `
                -MutationCompleted:$false `
                -FinalAttempted:$true `
                -FinalPassed:$false `
                -ReasonCode 'POSTGRES_GAME_DATABASE_NOT_READY' `
                -TechnicalDetails ([pscustomobject]@{ Stage='GameReadiness'; Error=$notReadyText; FailureReasons=@($notReadyText) }) `
                -Errors @($notReadyText) `
                -RecoveryActions @(@{ Id='Review'; Label='Open Details, fix the problem it names, then run PostgreSQL setup again.' }))
        }
        # FIX130 (S11): nothing is left for the journal to guard (no unfinished database); a leftover note is cleared here.
        if (@($journalFound.Entries).Count -gt 0) {
            foreach ($keptEntry in @($journalFound.Entries)) {
                if ([string]$keptEntry.Stage -ceq 'Created' -and $journalPresentCreated.Contains([string]$keptEntry.Database)) { [void]$journalNotes.Add(('Database {0}: an earlier setup finished building it, then stopped before it was done. The database is complete and was kept.' -f $keptEntry.Database)) }
            }
            try {
                Save-PostgresSetupJournal -Path ([string]$journalFound.Path) -RunId ([guid]::NewGuid().ToString('N')) -Entries @()
            } catch {
                $journalRemoveError = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
                Write-Log ('Postgres setup: the note from an earlier setup could not be removed: {0}' -f $journalRemoveError)
                [void]$journalNotes.Add('TeknoParrot Manager could not remove its small note about the earlier setup. The note is harmless and is removed the next time setup runs.')
            }
        }
        $preState = [pscustomobject]@{
            Captured = $true
            CaptureMethod = 'Verified PostgreSQL profile and database preflight'
            Items = $items
            EvidenceRoot = $null
            CaptureError = $null
        }
        # Nothing needed changing, so every checked game whose database exists is already set up (the normal path counts them in the profile loop, which this return skips).
        $results.AlreadyConfigured = $preflightPlans.Count
        return (& $finish `
            -Outcome 'NO_OP' `
            -ProductState 'UNCHANGED' `
            -Summary 'No PostgreSQL setup changes were needed. Every game database was checked and is ready.' `
            -Items $items `
            -SkippedItems $skippedItems `
            -MutationStarted:$false `
            -MutationCompleted:$false `
            -PreState $preState `
            -FinalAttempted:$true `
            -FinalPassed:$true `
            -FinalChecks @('Profile setup comparison and local database catalog checks completed; no setup changes were required.') `
            -ReasonCode 'POSTGRES_ALREADY_CONFIGURED' `
            -TechnicalDetails ([pscustomobject]@{ Stage='Preflight'; PlanCount=$preflightPlans.Count }))
    }
    if (-not $RecoveryBackup) {
        $recoveryBackupAttempted = $true
        $RecoveryBackup = New-PostgresRecoveryBackup -UserProfilesDir $UserProfilesDir
    }
    $backupState = Get-PostgresRecoveryBackupState -RecoveryBackup $RecoveryBackup -Attempted $recoveryBackupAttempted
    if ($RecoveryBackup) { $results.BackupPath = $backupState.Path }
    $backupInfo = [pscustomobject]@{
        Required = $true
        Attempted = $backupState.Attempted
        Created = $backupState.Created
        Verified = $backupState.Verified
        RootPath = $backupState.Path
        Items = @($RecoveryBackup.ProfileBackups | ForEach-Object { $_.Source }) + @($RecoveryBackup.ConfigBackups | ForEach-Object { $_.Source })
        FailureStage = if ($backupState.Verified) { $null } else { 'RecoveryEvidence' }
        FailureCode = if ($backupState.Verified) { $null } else { 'RECOVERY_EVIDENCE_REQUIRED' }
    }
    if (-not $RecoveryBackup -or -not $RecoveryBackup.Verified) {
        $results.Errors++
        $results.RecoveryBlocked = $true
        Write-Log 'Postgres: profile setup blocked because recovery evidence was not verified.'
        return (& $finish `
            -Outcome 'FAILED_BEFORE_MUTATION' `
            -ProductState 'UNCHANGED' `
            -Summary 'PostgreSQL setup stopped before changing any databases or profiles.' `
            -Items $items `
            -UnattemptedItems $items `
            -Backup $backupInfo `
            -MutationStarted:$false `
            -MutationCompleted:$false `
            -FinalAttempted:$false `
            -FinalPassed:$false `
            -ReasonCode 'RECOVERY_EVIDENCE_REQUIRED' `
            -TechnicalDetails ([pscustomobject]@{ Stage='RecoveryEvidence'; Error='Verified recovery evidence is unavailable.' }) `
            -RecoveryActions @(@{ Id='Review'; Label='Review the protected recovery evidence, then retry.' }))
    }
    $createdDatabases = New-Object System.Collections.Generic.List[object]
    $attemptedProfileItems = New-Object System.Collections.Generic.List[string]
    $attemptedProfileSources = New-Object System.Collections.Generic.List[string]
    $completedProfileItems = New-Object System.Collections.Generic.List[string]
    $attemptedDatabaseItems = New-Object System.Collections.Generic.List[string]
    $completedDatabaseItems = New-Object System.Collections.Generic.List[string]
    $databaseProgressPlans = @($preflightPlans | Where-Object { -not $_.DbExists -and $creationModes -contains $_.CreateMode } | Sort-Object -Property DbName -Unique)
    $databaseProgressStarted = Get-Date
    $databaseProgressCurrent = 0
    $databaseProgressCurrentDone = $false
    # FIX130 (S11): the journal of the databases THIS run creates (see Get-PostgresSetupJournalPath). Held in memory and written whole.
    $journalPath = Get-PostgresSetupJournalPath -RecoveryBackup $RecoveryBackup
    $journalRunId = [guid]::NewGuid().ToString('N')
    $journalEntries = New-Object System.Collections.Generic.List[object]
    # Writes (or changes) one entry on disk first and keeps it in memory only when the write worked.
    $journalMark = {
        param([string]$Name, [string]$Stage)
        $next = @($journalEntries | Where-Object { $_.Database -cne $Name }) + @([pscustomobject]@{ Database = $Name; Stage = $Stage; UpdatedUtc = (Get-Date).ToUniversalTime().ToString('o') })
        try {
            Save-PostgresSetupJournal -Path $journalPath -RunId $journalRunId -Entries $next
        } catch {
            $journalWriteError = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
            Write-Log ('Postgres setup: the setup journal could not be written: {0}' -f $journalWriteError)
            throw 'TeknoParrot Manager could not save its safety note about this database, so it did not go on.'
        }
        $journalEntries.Clear()
        foreach ($nextEntry in $next) { [void]$journalEntries.Add($nextEntry) }
    }
    # Removes entries after a VERIFIED rollback or a verified success. A failure to remove is harmless (an old 'Creating' entry for an
    # absent database, or a 'Created' one, is cleared by the next run) and is reported as $false, never as a failed setup.
    $journalClear = {
        param([string[]]$Names)
        if (@($Names).Count -eq 0) { return $true }
        $keep = @($journalEntries | Where-Object { @($Names) -cnotcontains [string]$_.Database })
        try {
            Save-PostgresSetupJournal -Path $journalPath -RunId $journalRunId -Entries $keep
            $journalEntries.Clear()
            foreach ($keptEntry in $keep) { [void]$journalEntries.Add($keptEntry) }
            return $true
        } catch {
            $journalClearError = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
            Write-Log ('Postgres setup: the setup journal could not be cleared: {0}' -f $journalClearError)
            return $false
        }
    }
    $beforeCreate = { param([string]$Name) & $journalMark $Name 'Creating' }
    # FIX130 (S11): put right what an unfinished earlier run left, now that the recovery backup is verified. Only databases the journal
    # names with stage 'Creating' are dropped (a verified drop); a 'Created' one is complete and kept.
    $journalRecoveryItems = New-Object System.Collections.Generic.List[string]
    if (@($journalFound.Entries).Count -gt 0) {
        $journalRecovery = Invoke-PostgresSetupJournalRecovery -JournalPath ([string]$journalFound.Path) -Entries @($journalFound.Entries) -SuperPasswordPlain $SuperPasswordPlain
        $removedNames = @($journalRecovery.RestoredNames | Where-Object { $journalExistingNames.Contains([string]$_) })
        foreach ($removedName in $removedNames) {
            Write-Log ('Postgres setup: removed the unfinished database {0} that an earlier setup run left; that run''s journal named it.' -f $removedName)
            [void]$journalNotes.Add(('Database {0}: an earlier setup stopped while building it, so it may have been only partly filled. TeknoParrot Manager built it, so it removed that unfinished copy.' -f $removedName))
            $removedItem = Get-PostgresSetupDatabaseItemId -DbName ([string]$removedName)
            [void]$recoveryDroppedItems.Add($removedItem)
            if ($databaseItems -notcontains $removedItem) {
                $items = @($items + $removedItem)
                [void]$attemptedDatabaseItems.Add($removedItem)
                [void]$completedDatabaseItems.Add($removedItem)
                [void]$journalRecoveryItems.Add($removedItem)
            }
        }
        foreach ($keptName in @($journalRecovery.KeptNames | Where-Object { $journalPresentCreated.Contains([string]$_) })) {
            [void]$journalNotes.Add(('Database {0}: an earlier setup finished building it, then stopped before it was done. The database is complete and was kept.' -f $keptName))
        }
        if (-not $journalRecovery.JournalCleared) {
            [void]$journalNotes.Add('TeknoParrot Manager could not remove its small note about the earlier setup. The note is harmless and is removed the next time setup runs.')
        }
        if (-not $journalRecovery.Verified) {
            $recoveryFailedIds = @($journalRecovery.FailedNames | ForEach-Object { Get-PostgresSetupDatabaseItemId -DbName ([string]$_) })
            $recoveryAllItems = @($items + @($recoveryFailedIds | Where-Object { $items -notcontains $_ }))
            $recoveryChanged = @($recoveryDroppedItems.ToArray() + $recoveryFailedIds | Select-Object -Unique)
            $results.Errors++
            $results.RecoveryBlocked = $true
            $results.DatabaseRollbackVerified = $false
            return (& $finish `
                -Outcome 'ACTION_REQUIRED' `
                -ProductState 'UNKNOWN' `
                -Summary 'Setup stopped, and TeknoParrot Manager could not check that your data is back as it was. Ask for help before you try again.' `
                -Items $recoveryAllItems `
                -ChangedItems $recoveryChanged `
                -CompletedItems @($recoveryDroppedItems.ToArray() | Where-Object { $recoveryFailedIds -notcontains $_ }) `
                -UnattemptedItems @($recoveryAllItems | Where-Object { $recoveryChanged -notcontains $_ -and $skippedItems -notcontains $_ }) `
                -SkippedItems $skippedItems `
                -UnknownItems $recoveryFailedIds `
                -MutationStarted:$true `
                -MutationCompleted:$false `
                -Backup $backupInfo `
                -PreState ([pscustomobject]@{ Captured=$true; CaptureMethod='Verified PostgreSQL recovery evidence and database preflight'; Items=$items; EvidenceRoot=$RecoveryBackup.Path; CaptureError=$null }) `
                -FinalAttempted:$true `
                -FinalPassed:$false `
                -FinalFailedItems $recoveryFailedIds `
                -Rollback ([pscustomobject]@{ Attempted=$true; Completed=$false; Verified=$false; VerifiedUtc=$null; Items=@($recoveryDroppedItems.ToArray()); EvidenceRoot=$RecoveryBackup.Path; FailedItems=$recoveryFailedIds; Errors=@($journalRecovery.Errors); DatabaseReceipts=@($journalRecovery.DatabaseReceipts) }) `
                -ReasonCode 'POSTGRES_SETUP_JOURNAL_RECOVERY_UNVERIFIED' `
                -TechnicalDetails ([pscustomobject]@{ Stage='SetupJournalRecovery'; FailureReasons=@($journalRecovery.Errors); DatabaseRollback=$journalRecovery }) `
                -Errors @($journalRecovery.Errors) `
                -RecoveryActions @(@{ Id='Review'; Label='Open Details and review the preserved PostgreSQL setup evidence.' }))
        }
    }
    # FIX130 (S10): ONE place builds the result of a failed database creation, for the per-database catch and for the outer catch, so
    # every way the creation phase can stop (an error, a stop with Ctrl+C) ends in a verified rollback of only what this run created,
    # or in an honest "could not verify" result.
    $failDatabaseCreation = {
        param($Plan, [string]$DbItem, $CreationResult, [string]$FailureText, [bool]$Stopped, [bool]$CreationStarted)
        $results.Errors++
        $results.RecoveryBlocked = $true
        $dbName = if ($null -ne $Plan) { [string]$Plan.DbName } else { '' }
        $dbItems = @($DbItem | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
        $creationError = if ($CreationResult -and $CreationResult.Error) { [string]$CreationResult.Error } elseif (-not [string]::IsNullOrWhiteSpace($FailureText)) { $FailureText } else { 'The PostgreSQL database creation result was unavailable.' }
        $creationFailureReason = ('Database {0} could not be created: {1}' -f $dbName, $creationError)
        Write-Log ('Postgres setup: ' + $creationFailureReason)
        $preMutationState = if ($CreationResult) { $CreationResult.PreMutationState } else { $null }
        $preMutationUnknown = ($null -eq $preMutationState -or -not $preMutationState.Verified -or [bool]$preMutationState.Exists)
        # No result: the database was never touched when its creation had not started, and it may exist (the journal note is written
        # after the verified-absent check, right before createdb) when the note is there. The note is what lets a stop be rolled back.
        $journalInFlight = [bool](-not $CreationResult -and @($journalEntries | Where-Object { $_.Database -ceq $dbName -and $_.Stage -ceq 'Creating' }).Count -gt 0)
        if ($journalInFlight -or (-not $CreationResult -and -not $CreationStarted)) { $preMutationUnknown = $false }
        $creationAttemptedWithoutOwnership = [bool]($CreationResult -and $CreationResult.MutationAttempted -and -not $CreationResult.DatabaseMayExist)
        $creationAttemptedAbsenceVerified = [bool]($creationAttemptedWithoutOwnership -and $CreationResult.FinalVerification.Attempted -and $CreationResult.FinalVerification.Passed)
        if ($creationAttemptedWithoutOwnership -and -not $creationAttemptedAbsenceVerified) { $preMutationUnknown = $true }
        $failedDatabase = @($createdDatabases | Where-Object { $_.DbName -eq $dbName })
        if ((($CreationResult -and $CreationResult.DatabaseMayExist) -or $journalInFlight) -and $failedDatabase.Count -eq 0) {
            [void]$createdDatabases.Add([pscustomobject]@{ DbName = $dbName; Encoding = $Plan.Encoding; BackupFile = $Plan.BackupFile })
        }
        $rollbackCandidates = @($createdDatabases.ToArray())
        if ($rollbackCandidates.Count -eq 0 -and -not $preMutationUnknown -and -not $creationAttemptedAbsenceVerified) {
            $results.DatabaseRollbackVerified = $false
            $unattempted = @($databaseItems | Where-Object { $dbItems -notcontains $_ -and $skippedItems -notcontains $_ })
            return (& $finish `
                -Outcome 'FAILED_BEFORE_MUTATION' `
                -ProductState 'UNCHANGED' `
                -Summary 'PostgreSQL setup stopped before changing any databases or profiles.' `
                -Items $items `
                -FailedItems $dbItems `
                -UnattemptedItems $unattempted `
                -SkippedItems $skippedItems `
                -MutationStarted:$false `
                -MutationCompleted:$false `
                -Backup $backupInfo `
                -PreState ([pscustomobject]@{ Captured=$true; CaptureMethod='Verified PostgreSQL recovery evidence and mutation-boundary database query'; Items=$items; EvidenceRoot=$RecoveryBackup.Path; CaptureError=$null }) `
                -FinalAttempted:$false `
                -FinalPassed:$false `
                -Rollback ([pscustomobject]@{ Attempted=$false; Completed=$false; Verified=$false; Items=@(); FailedItems=@(); Errors=@() }) `
                -ReasonCode 'POSTGRES_DATABASE_CREATION_FAILED_BEFORE_MUTATION' `
                -TechnicalDetails ([pscustomobject]@{ Stage='DatabaseCreation'; FailedDatabase=$dbName; FailureReasons=@($creationFailureReason); DatabaseCreation=$CreationResult; DatabaseCreationReceipts=@($databaseCreationReceipts.ToArray()) }) `
                -Errors @($creationError) `
                -RecoveryActions @(@{ Id='Review'; Label='Open Details and review the PostgreSQL setup failure.' }))
        }
        if ($rollbackCandidates.Count -gt 0) {
            try {
                $dbRollback = Restore-PostgresSetupCreatedDatabases -Databases $rollbackCandidates -SuperPasswordPlain $SuperPasswordPlain
            } catch {
                # The rollback itself stopped unexpectedly: nothing is verified, and every candidate stays in the journal.
                $dbRollback = [pscustomobject]@{
                    Verified = $false
                    RestoredItems = @()
                    FailedItems = @($rollbackCandidates | ForEach-Object { [string]$_.DbName })
                    Errors = @(ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain))
                    DatabaseReceipts = @()
                }
            }
        } else {
            $dbRollback = [pscustomobject]@{
                Verified = (-not $preMutationUnknown)
                RestoredItems = @()
                FailedItems = @()
                Errors = @()
                DatabaseReceipts = @()
            }
        }
        if ($creationAttemptedAbsenceVerified) {
            $absenceReceipt = [pscustomobject]@{
                Kind = 'VerifiedAbsentAfterCreationCommandFailure'
                Database = $dbName
                BeforeState = $CreationResult.PreMutationState
                AfterState = $CreationResult.PostMutationState
                DropAttempted = $false
                Verified = $true
                Commands = @($CreationResult.Commands)
            }
            $dbRollback = [pscustomobject]@{
                Verified = [bool]$dbRollback.Verified
                RestoredItems = @($dbRollback.RestoredItems + @($dbName))
                FailedItems = @($dbRollback.FailedItems)
                Errors = @($dbRollback.Errors)
                DatabaseReceipts = @($dbRollback.DatabaseReceipts + @($absenceReceipt))
            }
        }
        # createdb said the database already exists: another window made it and this run made nothing, so the safety note must not stay (a later run would drop that database).
        if ($CreationResult -and [string]$CreationResult.FailureStage -ceq 'DatabaseCreation' -and -not $CreationResult.DatabaseMayExist -and [string]$CreationResult.Error -match 'already exists') { [void](& $journalClear @($dbName)) }
        # A database that is verified absent again is no longer a database of this run: its journal entry goes (FIX130 S11).
        [void](& $journalClear @(@($dbRollback.RestoredItems) | ForEach-Object { [string]$_ }))
        # FIX130 (S6): one id form in every list: 'database:<name>'.
        $rollbackItems = @(@($dbRollback.RestoredItems) | ForEach-Object { Get-PostgresSetupDatabaseItemId -DbName ([string]$_) })
        $rollbackFailed = @(@($dbRollback.FailedItems) | ForEach-Object { Get-PostgresSetupDatabaseItemId -DbName ([string]$_) })
        $rollbackErrors = @($dbRollback.Errors + @($creationError))
        if ($preMutationUnknown) { $rollbackErrors += 'The setup database state was not verified absent at the mutation boundary.' }
        $rollbackUnknown = @($rollbackFailed)
        if ($preMutationUnknown) { $rollbackUnknown += $dbItems }
        $rollbackUnknown = @($rollbackUnknown | Select-Object -Unique)
        $rollbackVerified = ([bool]$dbRollback.Verified -and -not $preMutationUnknown)
        $results.DatabaseRollbackVerified = $rollbackVerified
        $rollback = [pscustomobject]@{
            Attempted = ($rollbackCandidates.Count -gt 0 -or $creationAttemptedAbsenceVerified)
            Completed = $rollbackVerified
            Verified = $rollbackVerified
            VerifiedUtc = if ($rollbackVerified) { (Get-Date).ToUniversalTime().ToString('o') } else { $null }
            Items = $rollbackItems
            EvidenceRoot = $RecoveryBackup.Path
            FailedItems = $rollbackFailed
            Errors = $rollbackErrors
            DatabaseReceipts = @($dbRollback.DatabaseReceipts)
        }
        $outcome = if ($rollbackVerified) { 'ROLLED_BACK_VERIFIED' } else { 'ACTION_REQUIRED' }
        $product = if ($rollbackVerified) { 'UNCHANGED' } else { 'UNKNOWN' }
        $summary = if ($rollbackVerified) { 'Setup stopped. Everything was put back the way it was, and checked.' } else { 'Setup stopped, and TeknoParrot Manager could not check that your data is back as it was. Ask for help before you try again.' }
        $changedItems = @($rollbackCandidates | ForEach-Object { Get-PostgresSetupDatabaseItemId -DbName $_.DbName })
        foreach ($recoveredItem in @($journalRecoveryItems.ToArray())) { if ($changedItems -notcontains $recoveredItem) { $changedItems += $recoveredItem } }
        if ($CreationResult -and $CreationResult.MutationAttempted -and $dbItems.Count -gt 0 -and $changedItems -notcontains $dbItems[0]) { $changedItems += $dbItems }
        $failedTerminal = @($dbItems | Where-Object { $rollbackUnknown -notcontains $_ })
        $unattempted = @($databaseItems | Where-Object {
            $attemptedDatabaseItems -notcontains $_ -and
            $rollbackUnknown -notcontains $_ -and
            $skippedItems -notcontains $_
        })
        $failedResult = & $finish `
            -Outcome $outcome `
            -ProductState $product `
            -Summary $summary `
            -Items $items `
            -ChangedItems $changedItems `
            -CompletedItems @($completedDatabaseItems.ToArray() | Where-Object { $rollbackUnknown -notcontains $_ }) `
            -FailedItems $failedTerminal `
            -UnattemptedItems $unattempted `
            -SkippedItems @($skippedItems | Where-Object { $rollbackUnknown -notcontains $_ }) `
            -UnknownItems $rollbackUnknown `
            -MutationStarted:($changedItems.Count -gt 0 -or [bool]($CreationResult -and $CreationResult.MutationAttempted)) `
            -MutationCompleted:$false `
            -Backup $backupInfo `
            -PreState ([pscustomobject]@{ Captured=$true; CaptureMethod='Verified PostgreSQL recovery evidence and database preflight'; Items=$items; EvidenceRoot=$RecoveryBackup.Path; CaptureError=$null }) `
            -FinalAttempted:$true `
            -FinalPassed:$rollbackVerified `
            -FinalChecks $(if ($rollbackVerified) { @('Every setup database that may have changed was restored to its verified absent pre-state.') } else { @() }) `
            -FinalFailedItems $rollbackUnknown `
            -Rollback $rollback `
            -ReasonCode $(if ($rollbackVerified) { 'POSTGRES_DATABASE_ROLLBACK_VERIFIED' } elseif ($preMutationUnknown) { 'POSTGRES_DATABASE_STATE_UNKNOWN' } else { 'POSTGRES_DATABASE_ROLLBACK_UNVERIFIED' }) `
            -TechnicalDetails ([pscustomobject]@{ Stage='DatabaseCreation'; FailedDatabase=$dbName; FailureReasons=@($creationFailureReason); DatabaseCreation=$CreationResult; DatabaseCreationReceipts=@($databaseCreationReceipts.ToArray()); DatabaseRollback=$dbRollback }) `
            -Errors $rollbackErrors `
            -RecoveryActions @(@{ Id='Review'; Label='Open Details and review the preserved PostgreSQL setup evidence.' })
        # A stop (Ctrl+C) that was rolled back and verified is a cancel, like the profile phase reports it.
        if ($Stopped -and $rollbackVerified) { $failedResult | Add-Member -NotePropertyName Cancelled -NotePropertyValue $true -Force }
        return $failedResult
    }
    $currentPlan = $null
    $currentDbItem = $null
    $creationCallStarted = $false
    $creationResult = $null
    try {
        try {
            foreach ($plan in @($preflightPlans | Sort-Object { $_.Profile.Name })) {
                if ($plan.DbExists -or $creationModes -notcontains $plan.CreateMode) { continue }
                $currentPlan = $plan
                $currentDbItem = $null
                $creationCallStarted = $false
                $creationResult = $null
                $databaseProgressCurrent++
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'PostgreSQL database creation' -Current $databaseProgressCurrent -Total $databaseProgressPlans.Count -StartedAt $databaseProgressStarted
                $dbItem = Get-PostgresSetupDatabaseItemId -DbName $plan.DbName
                $currentDbItem = $dbItem
                [void]$attemptedDatabaseItems.Add($dbItem)
                try {
                    $creationResult = $null
                    $creationCallStarted = $true
                    $creationResult = New-PostgresDatabaseFromBackup -DbName $plan.DbName -Encoding $plan.Encoding -BackupFile $plan.BackupFile -SuperPasswordPlain $SuperPasswordPlain -BeforeCreate $beforeCreate
                    [void]$databaseCreationReceipts.Add($creationResult)
                    if (-not $creationResult.Succeeded) {
                        throw [System.InvalidOperationException]::new('The PostgreSQL database creation and restore did not complete.')
                    }
                    [void]$createdDatabases.Add([pscustomobject]@{ DbName = $plan.DbName; Encoding = $plan.Encoding; BackupFile = $plan.BackupFile; Mode = $plan.CreateMode })
                    # FIX130 (S11): the restore is verified finished; a crash after this point never makes a later run drop it.
                    [void](& $journalMark ([string]$plan.DbName) 'Created')
                    # FIX95 (S1): the known bundled-archive limitation is kept for the result screen's details.
                    $knownLimitation = @($creationResult.Commands | Where-Object { $_.PSObject.Properties['AcceptedWarnings'] } | ForEach-Object { [string]$_.AcceptedWarnings } | Select-Object -First 1)
                    if ($knownLimitation.Count -gt 0) { $plan | Add-Member -NotePropertyName KnownRestoreLimitation -NotePropertyValue $knownLimitation[0] -Force }
                    # FIX125: how many known harmless warnings the bundled backup ended with; the Details view says it in plain words.
                    $acceptedCounts = @($creationResult.Commands | Where-Object { $_.PSObject.Properties['AcceptedWarningCount'] } | ForEach-Object { [int]$_.AcceptedWarningCount } | Select-Object -First 1)
                    $knownWarningCount = if ($acceptedCounts.Count -gt 0) { [int]$acceptedCounts[0] } else { 0 }
                    if ($knownWarningCount -gt 0) { $plan | Add-Member -NotePropertyName KnownRestoreWarningCount -NotePropertyValue $knownWarningCount -Force }
                    $acceptedNames = @($creationResult.Commands | Where-Object { $_.PSObject.Properties['AcceptedConstraintNames'] } | ForEach-Object { @($_.AcceptedConstraintNames) })
                    if ($acceptedNames.Count -gt 0) { $plan | Add-Member -NotePropertyName KnownRestoreConstraintNames -NotePropertyValue $acceptedNames -Force }
                    foreach ($sibling in $preflightPlans) { if ([string]::Equals([string]$sibling.DbName, [string]$plan.DbName, [System.StringComparison]::OrdinalIgnoreCase)) { $sibling.DbExists = $true } }
                    $dbState[$plan.DbName] = [pscustomobject]@{ Exists = $true; Verified = $true }
                    [void]$completedDatabaseItems.Add($dbItem)
                    $results.DbCreated++
                } catch {
                    $stoppedHere = Test-TpmErrorIsPipelineStop -ErrorRecord $_
                    $afterCreationText = if ($creationResult -and $creationResult.Succeeded) { ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain) } else { '' }
                    return (& $failDatabaseCreation -Plan $plan -DbItem $dbItem -CreationResult $creationResult -FailureText $afterCreationText -Stopped $stoppedHere -CreationStarted $creationCallStarted)
                }
            }
            $databaseProgressCurrentDone = $true
        } catch {
            # FIX130 (S10): an unexpected error (or a stop) outside the per-database try. Same fail-closed result: a verified rollback
            # of only what this run created, never a silent leftover.
            $outerError = $_
            $outerStopped = Test-TpmErrorIsPipelineStop -ErrorRecord $outerError
            $outerText = ConvertTo-PostgresRedactedText -Text ([string]$outerError.Exception.Message) -Secrets @($SuperPasswordPlain)
            Write-Log ('Postgres setup: the database creation phase stopped unexpectedly: {0}' -f $outerText)
            return (& $failDatabaseCreation -Plan $currentPlan -DbItem $currentDbItem -CreationResult $creationResult -FailureText $outerText -Stopped $outerStopped -CreationStarted $creationCallStarted)
        }
    } finally {
        if ($databaseProgressPlans.Count -gt 0) {
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'PostgreSQL database creation' -Current $(if ($databaseProgressCurrentDone) { $databaseProgressCurrent } else { $databaseProgressCurrent - 1 }) -Total $databaseProgressPlans.Count -StartedAt $databaseProgressStarted -Complete -Outcome $(if ($databaseProgressCurrentDone) { 'Final' } else { 'Error' })
        }
    }
    try {
        $orderedProfilePlans = @($preflightPlans | Sort-Object { $_.Profile.Name })
        $profileUpdateStarted = Get-Date
        $profileUpdateCurrent = 0
        $profileUpdateCurrentDone = $false
        try {
            foreach ($plan in $orderedProfilePlans) {
                $profileUpdateCurrent++
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'PostgreSQL profile update' -Current $profileUpdateCurrent -Total $orderedProfilePlans.Count -StartedAt $profileUpdateStarted
                $profileItem = 'profile:' + $plan.Profile.BaseName
                if ($plan.Changed) {
                    # The setup took minutes; a profile saved by the user or TeknoParrot meanwhile must not be overwritten with the older copy read at the start.
                    if ((Get-FileHash -LiteralPath $plan.Profile.FullName -Algorithm SHA256 -ErrorAction Stop).Hash -ine [string]$plan.SourceHash) {
                        throw ('The profile {0} was changed while setup was running, so it was not overwritten. Run PostgreSQL setup again.' -f $plan.Profile.BaseName)
                    }
                    [void]$attemptedProfileItems.Add($profileItem)
                    [void]$attemptedProfileSources.Add([string]$plan.Profile.FullName)
                    Save-Xml $plan.Document $plan.Profile.FullName
                    [void]$completedProfileItems.Add($profileItem)
                    $results.Configured++
                } elseif ($plan.CreateMode -in @('None', 'LeftToTeknoParrot')) {
                    $results.AlreadyConfigured++
                }
            }
            $profileUpdateCurrentDone = $true
        } finally {
            if ($orderedProfilePlans.Count -gt 0) {
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'PostgreSQL profile update' -Current $(if ($profileUpdateCurrentDone) { $profileUpdateCurrent } else { $profileUpdateCurrent - 1 }) -Total $orderedProfilePlans.Count -StartedAt $profileUpdateStarted -Complete -Outcome $(if ($profileUpdateCurrentDone) { 'Final' } else { 'Error' })
            }
        }
        $finalChecks = New-Object System.Collections.Generic.List[string]
        $profileVerificationStarted = Get-Date
        $profileVerificationCurrent = 0
        $profileVerificationCurrentDone = $false
        try {
            foreach ($plan in $orderedProfilePlans) {
                $profileVerificationCurrent++
                Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL profile verification' -Current $profileVerificationCurrent -Total $orderedProfilePlans.Count -StartedAt $profileVerificationStarted
                $doc = Read-Xml $plan.Profile.FullName
                # FIX36 S4: Path is always the local PostgreSQL bin folder. Address, Port and
                # User must be the local postgres connection, except for a profile the user
                # had to decide on: its own values stay and are checked as planned. A kept
                # profile (K) is checked as planned in every field, Path included.
                foreach ($field in @(@('Path', $relBinPath), @('Address', '127.0.0.1'), @('Port', '5432'), @('User', 'postgres'))) {
                    $actualValue = [string](Get-PostgresFieldValue $doc $field[0])
                    $expectedValue = if ($plan.PassKept -or ($field[0] -ne 'Path' -and $plan.PassDecision -eq 'NeedsApproval')) { [string]$plan.PlannedFields[$field[0]] } else { [string]$field[1] }
                    if ($field[0] -eq 'Path') {
                        $actualValue = $actualValue -replace '\\{2,}', '\'
                        $expectedValue = $expectedValue -replace '\\{2,}', '\'
                    }
                    if (-not [string]::Equals($actualValue, $expectedValue, [System.StringComparison]::Ordinal)) { throw "PostgreSQL profile verification failed for $($plan.Profile.BaseName)." }
                }
                # Every profile not kept by the user must now hold the verified password.
                $expectedPass = if ($plan.PassKept) { [string]$plan.PlannedFields['Pass'] } else { $SuperPasswordPlain }
                if (-not [string]::Equals([string](Get-PostgresFieldValue $doc 'Pass'), $expectedPass, [System.StringComparison]::Ordinal)) { throw "PostgreSQL profile password verification failed for $($plan.Profile.BaseName)." }
                if (-not [string]::Equals([string](Get-PostgresFieldValue $doc 'DbName'), [string]$plan.DbName, [System.StringComparison]::Ordinal)) { throw "PostgreSQL profile database name verification failed for $($plan.Profile.BaseName)." }
                # FIX69: a database created by this run is verified whatever the profile's auto-create value.
                if ($plan.DbExists -and ($plan.AutoCreate -ne $true -or $creationModes -contains $plan.CreateMode)) {
                    $finalDb = Get-PostgresDatabaseState -DbName $plan.DbName -SuperPasswordPlain $SuperPasswordPlain
                    if (-not $finalDb.Verified -or -not $finalDb.Exists) { throw "PostgreSQL database verification failed for $($plan.DbName)." }
                }
                [void](& $checkGameReady $plan)
                [void]$finalChecks.Add(('Verified PostgreSQL profile settings for {0}.' -f $plan.Profile.BaseName))
            }
            $profileVerificationCurrentDone = $true
        } finally {
            if ($orderedProfilePlans.Count -gt 0) {
                Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL profile verification' -Current $(if ($profileVerificationCurrentDone) { $profileVerificationCurrent } else { $profileVerificationCurrent - 1 }) -Total $orderedProfilePlans.Count -StartedAt $profileVerificationStarted -Complete -Outcome $(if ($profileVerificationCurrentDone) { 'Final' } else { 'Error' })
            }
        }
        $changed = @($attemptedDatabaseItems.ToArray() + $attemptedProfileItems.ToArray())
        $completed = @($completedDatabaseItems.ToArray() + $completedProfileItems.ToArray())
        $successResult = & $finish `
            -Outcome 'SUCCEEDED' `
            -ProductState 'INTENDED' `
            -Summary 'PostgreSQL setup finished. Every game database was checked and is ready.' `
            -Items $items `
            -ChangedItems $changed `
            -CompletedItems $completed `
            -SkippedItems $skippedItems `
            -MutationStarted:$true `
            -MutationCompleted:$true `
            -Backup $backupInfo `
            -PreState ([pscustomobject]@{ Captured=$true; CaptureMethod='Verified PostgreSQL recovery evidence and database preflight'; Items=$items; EvidenceRoot=$RecoveryBackup.Path; CaptureError=$null }) `
            -FinalAttempted:$true `
            -FinalPassed:$true `
            -FinalChecks $finalChecks.ToArray() `
            -ReasonCode 'POSTGRES_SETUP_VERIFIED' `
            -TechnicalDetails ([pscustomobject]@{ Stage='FinalVerification'; Configured=$results.Configured; DbCreated=$results.DbCreated; AlreadyConfigured=$results.AlreadyConfigured; CreatedDatabases=@($createdDatabases.ToArray() | ForEach-Object { [pscustomobject]@{ Database=$_.DbName; Mode=$_.Mode; Encoding=$_.Encoding } }); DatabaseCreationReceipts=@($databaseCreationReceipts.ToArray()) })
        # FIX130 (S11): the setup is verified, so the journal is cleared now. If that fails it is harmless (the next run reads
        # 'Created' entries as complete databases and clears them); the result says so and is still a success.
        if (-not (& $journalClear @($journalEntries | ForEach-Object { [string]$_.Database }))) {
            $successResult | Add-Member -NotePropertyName Warnings -NotePropertyValue @(@($successResult.Warnings) + 'TeknoParrot Manager could not remove its small note about this setup. The note is harmless and is removed the next time setup runs.') -Force
        }
        return $successResult
    } catch {
        $profileCaughtError = $_
        $results.Errors++
        $results.RecoveryBlocked = $true
        $profileFailureError = ConvertTo-PostgresRedactedText -Text ([string]$profileCaughtError.Exception.Message) -Secrets @($SuperPasswordPlain)
        $pipelineStopped = Test-TpmErrorIsPipelineStop -ErrorRecord $profileCaughtError
        $profileRollbackVerified = $true
        $profileRollbackError = $null
        try {
            $profileRollbackValue = Restore-PostgresProfileBackups -RecoveryBackup $RecoveryBackup -ProfileSourcePaths $attemptedProfileSources.ToArray()
            if ($profileRollbackValue -is [bool]) { $profileRollbackVerified = [bool]$profileRollbackValue }
        } catch {
            $profileRollbackVerified = $false
            $profileRollbackError = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
        }
        $dbRollback = Restore-PostgresSetupCreatedDatabases -Databases $createdDatabases.ToArray() -SuperPasswordPlain $SuperPasswordPlain
        # Only a verified drop clears a journal entry; a database that could not be dropped stays in the journal for the next run.
        [void](& $journalClear @(@($dbRollback.RestoredItems) | ForEach-Object { [string]$_ }))
        $results.DatabaseRollbackVerified = [bool]$dbRollback.Verified
        $results.ProfileRollbackVerified = [bool]$profileRollbackVerified
        # FIX130 (S6): the database lists use the same 'database:<name>' ids as the other lists; the bare name (the old form) made a
        # failed drop show up as unknown under one id and completed under another.
        $dbRollbackRestoredIds = @(@($dbRollback.RestoredItems) | ForEach-Object { Get-PostgresSetupDatabaseItemId -DbName ([string]$_) })
        $dbRollbackFailedIds = @(@($dbRollback.FailedItems) | ForEach-Object { Get-PostgresSetupDatabaseItemId -DbName ([string]$_) })
        $combinedRollback = [pscustomobject]@{
            Verified = ($profileRollbackVerified -and $dbRollback.Verified)
            RestoredItems = @($dbRollbackRestoredIds + $(if ($profileRollbackVerified) { @($attemptedProfileItems.ToArray()) } else { @() }))
            FailedItems = @($dbRollbackFailedIds + $(if (-not $profileRollbackVerified) { @($attemptedProfileItems.ToArray()) } else { @() }))
            Errors = @($dbRollback.Errors + $(if ($profileRollbackError) { @($profileRollbackError) } else { @() }))
        }
        $changedItems = @($attemptedDatabaseItems.ToArray() + $attemptedProfileItems.ToArray())
        $unknownItems = @($combinedRollback.FailedItems)
        $completedItems = @($completedProfileItems.ToArray() + $completedDatabaseItems.ToArray() | Where-Object { $unknownItems -notcontains $_ })
        $failedItems = @($attemptedDatabaseItems.ToArray() + $attemptedProfileItems.ToArray() | Where-Object {
            $completedItems -notcontains $_ -and
            $unknownItems -notcontains $_ -and
            $skippedItems -notcontains $_
        })
        $unattemptedItems = @($items | Where-Object {
            $changedItems -notcontains $_ -and
            $unknownItems -notcontains $_ -and
            $failedItems -notcontains $_ -and
            $completedItems -notcontains $_ -and
            $skippedItems -notcontains $_
        })
        $skippedTerminalItems = @($skippedItems | Where-Object { $unknownItems -notcontains $_ })
        $rollback = [pscustomobject]@{
            Attempted = $true
            Completed = [bool]$combinedRollback.Verified
            Verified = [bool]$combinedRollback.Verified
            VerifiedUtc = (Get-Date).ToUniversalTime().ToString('o')
            Items = @($combinedRollback.RestoredItems)
            EvidenceRoot = $RecoveryBackup.Path
            FailedItems = @($combinedRollback.FailedItems)
            Errors = @($combinedRollback.Errors)
            DatabaseReceipts = @($dbRollback.DatabaseReceipts)
        }
        # A stop before any profile or database was touched (for example a profile that changed while setup ran) is not a rollback.
        $nothingChanged = ($combinedRollback.Verified -and $changedItems.Count -eq 0)
        $outcome = if ($nothingChanged) { 'FAILED_BEFORE_MUTATION' } elseif ($combinedRollback.Verified) { 'ROLLED_BACK_VERIFIED' } else { 'ACTION_REQUIRED' }
        $product = if ($combinedRollback.Verified) { 'UNCHANGED' } else { 'UNKNOWN' }
        $summary = if ($nothingChanged) { 'Setup stopped before it changed anything. Run it again when the problem in Details is fixed.' } elseif ($combinedRollback.Verified -and $profileFailureError -like '* is not ready: *') { 'A game database is not ready, so setup put everything back the way it was, and checked. Open Details to see which game and why.' } elseif ($combinedRollback.Verified) { 'Setup stopped. Everything was put back the way it was, and checked.' } else { 'Setup stopped, and TeknoParrot Manager could not check that your data is back as it was. Ask for help before you try again.' }
        $terminalResult = (& $finish `
            -Outcome $outcome `
            -ProductState $product `
            -Summary $summary `
            -Items $items `
            -ChangedItems $changedItems `
            -CompletedItems $completedItems `
            -FailedItems $failedItems `
            -UnattemptedItems $unattemptedItems `
            -SkippedItems $skippedTerminalItems `
            -UnknownItems $unknownItems `
            -MutationStarted:(-not $nothingChanged) `
            -MutationCompleted:$false `
            -Backup $backupInfo `
            -PreState ([pscustomobject]@{ Captured=$true; CaptureMethod='Verified PostgreSQL recovery evidence and database preflight'; Items=$items; EvidenceRoot=$RecoveryBackup.Path; CaptureError=$null }) `
            -FinalAttempted:$true `
            -FinalPassed:([bool]$combinedRollback.Verified) `
            -FinalChecks $(if ($combinedRollback.Verified) { @('Coupled PostgreSQL profile and database rollback was verified.') } else { @() }) `
            -FinalFailedItems @($combinedRollback.FailedItems) `
            -Rollback $rollback `
            -TechnicalDetails ([pscustomobject]@{ Stage='ProfileWriteOrFinalVerification'; Failure=$profileFailureError; FailureReasons=@(('PostgreSQL profile write or final verification failed: {0}' -f $profileFailureError)); DatabaseCreationReceipts=@($databaseCreationReceipts.ToArray()); DatabaseRollback=$dbRollback; ProfileRollbackVerified=$profileRollbackVerified }) `
            -Errors @($combinedRollback.Errors) `
            -RecoveryActions $(if ($combinedRollback.Verified) { @() } else { @(@{ Id='Review'; Label='Open Details and review the preserved recovery evidence.' }) }))
        if ($pipelineStopped -and $combinedRollback.Verified) {
            $terminalResult | Add-Member -NotePropertyName Cancelled -NotePropertyValue $true -Force
        }
        return $terminalResult
    }
}
# =============================================================================
# FFB ARCADE PLUGIN  (force feedback / rumble for arcade racers and shooters)
# =============================================================================
# Source: mightymikem/FFBArcadePlugin, an actively-maintained fork of
# Boomslangnz/FFBArcadePlugin. Deploys one compiled DLL (MAME32.dll x86 /
# MAME64.dll x64) into a game's folder, renamed to whatever DLL that
# specific game expects to load (d3d9.dll, d3d11.dll, opengl32.dll,
# xinput1_3.dll, or winmm.dll). The per-game destination filename is a
# fixed lookup tied to specific titles, not auto-detected from the exe --
# so unlike ReShade it cannot be guessed at runtime; it is read from the
# pinned revision's AutoSetup.cmd rather than a mutable branch URL, and remains
# intentionally live rather than hardcoded here.

# Fetches and parses the upstream AutoSetup.cmd to build a folder-name ->
# destination-DLL-filename map. The file has a very regular shape:
#   cd <FolderName>
#   rename dinput8.dll <destination>.dll
#   cd..
# (folder names are quoted only when they contain special characters, e.g.
# `cd "Sega Race TV"` vs `cd Afterburner Climax` -- the regex handles both).
# Returns an empty hashtable (not a hardcoded fallback list) if the fetch
# fails after retries -- there is nothing meaningful to fall back to since
# the table only exists upstream.
function Test-FFBPluginRevision {
    param([string]$Revision)
    return (-not [string]::IsNullOrWhiteSpace($Revision) -and $Revision -match '^[0-9a-fA-F]{40}$')
}

function Get-FFBPluginSourceRevision {
    try {
        $uri = 'https://api.github.com/repos/mightymikem/FFBArcadePlugin/commits/master'
        $resp = Invoke-TpmWebRequestSilently -Uri $uri -UseBasicParsing -TimeoutSec 20 -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
        $payload = [string]$resp.Content | ConvertFrom-Json
        $shaProperty = $payload.PSObject.Properties['sha']
        if (-not $shaProperty -or $null -eq $shaProperty.Value -or $shaProperty.Value -is [System.Array]) {
            throw 'FFBPlugin source response did not contain exactly one SHA.'
        }
        $sha = [string]$shaProperty.Value
        if (-not (Test-FFBPluginRevision -Revision $sha)) {
            throw 'FFBPlugin source revision was not a full commit SHA.'
        }
        return [pscustomobject]@{
            Revision = $sha.ToUpperInvariant()
            Repository = 'mightymikem/FFBArcadePlugin'
            ManifestUrl = $uri
            Trust = 'SourcePinnedAuditHash'
        }
    } catch {
        Write-Log "FFBPlugin: source revision lookup failed -- $_"
        return $null
    }
}

function Get-FFBPluginGameMap {
    param([Parameter(Mandatory)][string]$SourceRevision)
    $map = @{}
    if (-not (Test-FFBPluginRevision -Revision $SourceRevision)) {
        Write-Log 'FFBPlugin: refused support-table fetch because the source revision was not pinned.'
        return $map
    }
    $uri = "https://raw.githubusercontent.com/mightymikem/FFBArcadePlugin/$SourceRevision/AutoSetup.cmd"
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            $resp = Invoke-TpmWebRequestSilently -Uri $uri -UseBasicParsing -TimeoutSec 20 `
                        -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $ms = [regex]::Matches($resp.Content, '(?m)^cd\s+"?([^"\r\n]+?)"?\s*\r?\nrename\s+dinput8\.dll\s+(\S+)\s*\r?\ncd\.\.')
            foreach ($m in $ms) {
                $folderName = $m.Groups[1].Value.Trim()
                $destDll    = $m.Groups[2].Value.Trim()
                if ($folderName -and $destDll) { $map[$folderName] = $destDll }
            }
            if ($map.Count -gt 0) {
                Write-Log "FFBPlugin: $($map.Count) game(s) in the pinned AutoSetup.cmd table."
            } else {
                Write-Log "FFBPlugin: 0 entries parsed from pinned AutoSetup.cmd -- format may have changed."
            }
            return $map
        } catch {
            $status = 0
            # Get-TpmHttpStatusCodeFromError guards the same optional
            # .Exception.Response/.StatusCode access this used to do inline
            # (unsafe under strict mode for exception types that lack either
            # property entirely -- RuntimeException from a plain "throw",
            # HttpRequestException, etc.) and additionally falls back to
            # extracting a status code embedded only in the message text.
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "FFBPlugin: pinned AutoSetup.cmd fetch failed -- $_"
                if ($status -ge 400 -and $status -lt 500) { return @{} }
                return $null
            }
            Write-Log "FFBPlugin: attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    return @{}
}



# Downloads MAME32.dll / MAME64.dll directly from the pinned repository
# revision (plain files, not inside the release ZIP -- no extraction step).
# Returns a structured all-or-nothing result with staged paths and SHA-256
# evidence; an existing custom cache is never used as an unverified fallback.
function Invoke-FFBPluginDownload {
    param([string]$destDir, [string]$SourceRevision)
    $script:FFBDownloadEvidence = @()
    if (-not (Test-FFBPluginRevision -Revision $SourceRevision)) {
        Write-Log 'FFBPlugin: refused download because the source revision was not pinned.'
        return [pscustomobject]@{
            Succeeded = $false; Files = @{}; Evidence = @(); ResiduePaths = @()
            Reason = 'SOURCE_REVISION_UNAVAILABLE'
        }
    }
    $sourceRevision = $SourceRevision.ToUpperInvariant()
    $stagedPaths = New-Object System.Collections.Generic.List[string]
    $filePaths = [ordered]@{}
    $evidence = New-Object System.Collections.Generic.List[object]
    $residuePaths = New-Object System.Collections.Generic.List[string]
    try {
        [void][System.IO.Directory]::CreateDirectory($destDir)
        if (-not (Test-TpmNoReparsePath -Path $destDir)) {
            throw "FFBPlugin: cache staging directory is missing or reparse-backed."
        }
        foreach ($dllName in @('MAME32.dll', 'MAME64.dll')) {
            $uri = "https://raw.githubusercontent.com/mightymikem/FFBArcadePlugin/$sourceRevision/$dllName"
            $tempPath = Join-Path $destDir ('TPM-FFB-source-{0}-{1}' -f ([guid]::NewGuid().ToString('N')), $dllName)
            [void]$stagedPaths.Add($tempPath)
            if (-not (Invoke-TpmDownload -DownloadUrl $uri -DestinationPath $tempPath -Label 'FFBPlugin' -Version $sourceRevision)) {
                throw "FFBPlugin: $dllName download failed."
            }
            if (-not (Test-Path -LiteralPath $tempPath -PathType Leaf)) {
                throw "FFBPlugin: $dllName download did not produce a staged file."
            }
            $hash = (Get-FileHash -LiteralPath $tempPath -Algorithm SHA256 -ErrorAction Stop).Hash
            $filePaths[$dllName] = $tempPath
            [void]$evidence.Add([pscustomobject]@{
                FileName = $dllName
                SourceUrl = $uri
                SourceRevision = $sourceRevision
                Sha256 = $hash
                Trust = 'SourcePinnedAuditHash'
                DownloadPath = $tempPath
            })
            Write-Log "FFBPlugin: downloaded pinned $dllName revision $sourceRevision SHA256 $hash"
        }
        $script:FFBDownloadEvidence = $evidence.ToArray()
        return [pscustomobject]@{
            Succeeded = $true
            Files = $filePaths
            Evidence = $evidence.ToArray()
            ResiduePaths = @()
            Reason = $null
        }
    } catch {
        Write-Log "FFBPlugin: pinned source acquisition failed -- $_"
        foreach ($path in @($stagedPaths)) {
            try {
                if (Test-Path -LiteralPath $path -PathType Leaf) {
                    Remove-Item -LiteralPath $path -Force -ErrorAction Stop
                }
            } catch {
                [void]$residuePaths.Add($path)
                Write-Log "FFBPlugin: staged source cleanup failed -- $path -- $_"
            }
        }
        $script:FFBDownloadEvidence = @()
        return [pscustomobject]@{
            Succeeded = $false
            Files = @{}
            Evidence = @()
            ResiduePaths = $residuePaths.ToArray()
            Reason = 'DLL_ACQUISITION_FAILED'
        }
    }
}

# Deploys FFB plugin DLLs to registered games matched against the live
# AutoSetup.cmd table by fuzzy folder-name similarity. Never overwrites an
# existing file at the destination filename (ReShade or anything else
# already occupying that hook point) -- skips and reports instead.
function Get-FFBPluginOwnershipPath {
    param([Parameter(Mandatory)][string]$CacheDir)
    return (Join-Path $CacheDir 'TPM-FFB-Plugin-Ownership.json')
}

function Read-FFBPluginOwnership {
    param([Parameter(Mandatory)][string]$CacheDir)
    $path = Get-FFBPluginOwnershipPath -CacheDir $CacheDir
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return @() }
    try {
        $data = Get-Content -LiteralPath $path -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json
        return @($data.Entries)
    } catch {
        Write-Log 'FFBPlugin ownership manifest could not be read; no automatic removal was attempted.'
        return @()
    }
}

function Write-FFBPluginOwnership {
    param([Parameter(Mandatory)][string]$CacheDir, [Parameter(Mandatory)][object]$Entries)
    [void][System.IO.Directory]::CreateDirectory($CacheDir)
    $path = Get-FFBPluginOwnershipPath -CacheDir $CacheDir
    $payload = [ordered]@{ SchemaVersion = 1; Entries = @($Entries) }
    # Unique CreateNew temp + atomic replace; never a predictable '.tmp' name that a pre-existing file or link could redirect.
    Write-TpmAtomicTextFile -Path $path -Text ($payload | ConvertTo-Json -Depth 5) -Operation 'temp-then-move final write (Write-FFBPluginOwnership)' -Validate { param([string]$Written) $null = $Written | ConvertFrom-Json -ErrorAction Stop; $true }
}
function Get-FFBPluginOwnershipSnapshot {
    param([Parameter(Mandatory)][string]$CacheDir)
    $path = Get-FFBPluginOwnershipPath -CacheDir $CacheDir
    if (Test-Path -LiteralPath $path -PathType Leaf) {
        return [pscustomobject]@{
            Path = $path
            Exists = $true
            Bytes = [System.IO.File]::ReadAllBytes($path)
        }
    }
    return [pscustomobject]@{ Path = $path; Exists = $false; Bytes = $null }
}

function Restore-FFBPluginOwnershipSnapshot {
    param(
        [Parameter(Mandatory)][string]$CacheDir,
        [Parameter(Mandatory)][object]$Snapshot
    )
    $path = Get-FFBPluginOwnershipPath -CacheDir $CacheDir
    if ($Snapshot.Exists) {
        # Byte-exact rollback through a unique temp opened with CreateNew: a pre-existing file or link at a predictable
        # name is never written through. The constructor runs inside the try and ownership is recorded only after it
        # succeeds (outside a try a constructor failure is not terminating), so a failure removes only a temp this call
        # created, never a pre-existing file that made CreateNew fail.
        $temp = $path + '.' + (New-Guid).ToString('N') + '.rollback.tmp'
        $bytes = [byte[]]$Snapshot.Bytes
        $tempCreated = $false
        try {
            $stream = New-Object System.IO.FileStream($temp, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
            $tempCreated = $true
            try { $stream.Write($bytes, 0, $bytes.Length); $stream.Flush($true) } finally { $stream.Dispose() }
            Assert-TpmNoReparseWriteTarget -Path $path -Operation 'temp-then-move final write (Restore-FFBPluginOwnershipSnapshot)'
            Move-Item -LiteralPath $temp -Destination $path -Force -ErrorAction Stop
            $tempCreated = $false
        } catch {
            if ($tempCreated -and (Test-Path -LiteralPath $temp -PathType Leaf)) { Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue }
            throw
        }
    } elseif (Test-Path -LiteralPath $path -PathType Leaf) {
        Remove-Item -LiteralPath $path -Force -ErrorAction Stop
    }
}

function Write-FFBPluginEvidence {
    param(
        [Parameter(Mandatory)][string]$EvidencePath,
        [Parameter(Mandatory)][object]$Evidence
    )
    $evidenceDir = [System.IO.Path]::GetDirectoryName($EvidencePath)
    if ([string]::IsNullOrWhiteSpace($evidenceDir)) { throw 'FFB evidence path has no parent directory.' }
    [void][System.IO.Directory]::CreateDirectory($evidenceDir)
    # Unique CreateNew temp + atomic replace; never a predictable '.tmp' name that a pre-existing file or link could
    # redirect. Write-TpmAtomicTextFile removes only the temp it created and rethrows on failure.
    Write-TpmAtomicTextFile -Path $EvidencePath -Text ($Evidence | ConvertTo-Json -Depth 10) -Operation 'temp-then-move final write (Write-FFBPluginEvidence)' -Validate { param([string]$Written) $null = $Written | ConvertFrom-Json -ErrorAction Stop; $true }
}

function Restore-FFBPluginDeploymentTransaction {
    param(
        [object[]]$Entries = @(),
        [object[]]$RemovedItems = @(),
        [Parameter(Mandatory)][string]$CacheDir,
        [Parameter(Mandatory)][object]$OwnershipSnapshot,
        [string]$UserProfilesDir = '',
        [string]$OverlapBackupPath = ''
    )
    $errors = New-Object System.Collections.Generic.List[string]
    $restored = 0
    foreach ($entry in @($Entries | Sort-Object -Property CreatedUtc -Descending)) {
        $destination = [string]$entry.Destination
        try {
            if (-not (Test-Path -LiteralPath $destination -PathType Leaf)) { continue }
            $currentHash = (Get-FileHash -LiteralPath $destination -Algorithm SHA256 -ErrorAction Stop).Hash
            if ($currentHash -ine [string]$entry.DeployedSha256) {
                throw "deployed hook changed before rollback: $destination"
            }
            Remove-Item -LiteralPath $destination -Force -ErrorAction Stop
            if (Test-Path -LiteralPath $destination -PathType Leaf) {
                throw "deployed hook remained after rollback: $destination"
            }
            $restored++
        } catch {
            [void]$errors.Add([string]$_.Exception.Message)
        }
    }
    foreach ($item in @($RemovedItems)) {
        $destination = [string]$item.Destination
        try {
            if (Test-Path -LiteralPath $destination -PathType Leaf) {
                throw "native-cleanup destination was recreated before rollback: $destination"
            }
            $backup = [string]$item.Backup
            if (-not (Test-Path -LiteralPath $backup -PathType Leaf)) {
                throw "native-cleanup backup is unavailable: $backup"
            }
            Copy-Item -LiteralPath $backup -Destination $destination -Force -ErrorAction Stop
            $restoredHash = (Get-FileHash -LiteralPath $destination -Algorithm SHA256 -ErrorAction Stop).Hash
            if ($restoredHash -ine [string]$item.Hash) { throw "native-cleanup restore hash mismatch: $destination" }
            $restored++
        } catch {
            [void]$errors.Add([string]$_.Exception.Message)
        }
    }
    try {
        Restore-FFBPluginOwnershipSnapshot -CacheDir $CacheDir -Snapshot $OwnershipSnapshot
    } catch {
        [void]$errors.Add("ownership manifest rollback failed: $($_.Exception.Message)")
    }
    if (-not [string]::IsNullOrWhiteSpace($OverlapBackupPath)) {
        try {
            if (-not (Test-Path -LiteralPath $OverlapBackupPath -PathType Container)) {
                throw "overlap backup is unavailable: $OverlapBackupPath"
            }
            if ([string]::IsNullOrWhiteSpace($UserProfilesDir)) {
                throw 'overlap rollback has no UserProfiles directory.'
            }
            $rollbackItems = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $OverlapBackupPath -ProgressLabel 'FFB plugin overlap rollback discovery' -Filter '*' -EnumerationErrorAction Stop -IncludeDirectories -Force)
            $rollbackStarted = Get-Date
            $rollbackCurrent = 0
            $rollbackCurrentDone = $false
            try {
                foreach ($rollbackItem in $rollbackItems) {
                    $rollbackCurrent++
                    Write-TpmCompactExtractionProgress -Phase Repairing -Label 'FFB plugin overlap rollback' -Current $rollbackCurrent -Total $rollbackItems.Count -StartedAt $rollbackStarted
                    # The safety copy carries its own completion record; it must never be copied into the live profiles.
                    if ([string]$rollbackItem.Name -ne (Get-TpmUserProfilesBackupMarkerName)) {
                        $rollbackItem | Copy-Item -Destination $UserProfilesDir -Recurse -Force -ErrorAction Stop
                    }
                }
                $rollbackCurrentDone = $true
            } finally {
                if ($rollbackItems.Count -gt 0) {
                    Write-TpmCompactExtractionProgress -Phase Repairing -Label 'FFB plugin overlap rollback' -Current $(if ($rollbackCurrentDone) { $rollbackCurrent } else { $rollbackCurrent - 1 }) -Total $rollbackItems.Count -StartedAt $rollbackStarted -Complete -Outcome $(if ($rollbackCurrentDone) { 'Final' } else { 'Error' })
                }
            }
        } catch {
            [void]$errors.Add("native overlap rollback failed: $($_.Exception.Message)")
        }
    }
    return [pscustomobject]@{
        Succeeded = ($errors.Count -eq 0)
        Restored = $restored
        Errors = $errors.ToArray()
    }
}


function Remove-FFBPluginOwnedDeployment {
    param([Parameter(Mandatory)][string]$CacheDir, [Parameter(Mandatory)][string]$ProfileCode, [string[]]$ProtectedRoots = @())
    $entries = @(Read-FFBPluginOwnership -CacheDir $CacheDir)
    $script:FFBOwnedRemovalRecords = @()
    $remaining = New-Object System.Collections.Generic.List[object]
    $removalItems = New-Object System.Collections.Generic.List[object]
    foreach ($entry in $entries) {
        if ([string]$entry.ProfileCode -ne $ProfileCode) {
            [void]$remaining.Add($entry)
            continue
        }
        $destination = [string]$entry.Destination
        $gameRoot = [string]$entry.GameRoot
        # Owner rule R6: nothing is removed from a game folder inside the source collection. Refused before any copy or delete.
        $holdingRoot = Find-TpmProtectedSourceRoot -Path $gameRoot -ProtectedRoots $ProtectedRoots
        if ($holdingRoot) {
            Write-Log ("FFBPlugin ownership: refused removal of {0}; its game folder {1} is inside the source folder {2}" -f $destination, $gameRoot, $holdingRoot)
            throw 'Not removed: the optional plugin file is inside your source folder. TeknoParrot Manager never changes your source folder. Move the game out of it, or fix the game folder in its profile.'
        }
        if ([string]::IsNullOrWhiteSpace($gameRoot) -or
            -not (Test-Path -LiteralPath $destination -PathType Leaf) -or
            -not (Test-Path -LiteralPath $gameRoot -PathType Container) -or
            -not (Test-TpmNoReparsePath -Path $gameRoot) -or
            -not (Test-PathInside -child $destination -parent $gameRoot)) {
            [void]$remaining.Add($entry)
            continue
        }
        $current = Get-TpmFileState -Path $destination
        if (-not $current.Readable -or $current.Sha256 -ine [string]$entry.DeployedSha256) {
            Write-Host ("    Kept {0}: the hook file changed after TeknoParrot Manager installed it." -f $destination) -ForegroundColor Yellow
            Write-Log "FFBPlugin ownership: refused removal of changed file $destination"
            [void]$remaining.Add($entry)
            continue
        }
        $backupDir = Join-Path (Join-Path $gameRoot 'FullBackup') ('FFBPluginCleanup_' + (Get-Date).ToUniversalTime().ToString('yyyy-MM-dd_HH-mm-ss_fff', [System.Globalization.CultureInfo]::InvariantCulture) + '_' + [guid]::NewGuid().ToString('N'))
        [void][System.IO.Directory]::CreateDirectory($backupDir)
        $backupPath = Join-Path $backupDir ([System.IO.Path]::GetFileName($destination))
        Copy-Item -LiteralPath $destination -Destination $backupPath -Force -ErrorAction Stop
        $backupState = Get-TpmFileState -Path $backupPath
        if (-not $backupState.Readable -or -not (Test-TpmFileStateMatch -Expected $current -Actual $backupState)) {
            throw "FFBPlugin removal backup verification failed for '$destination'."
        }
        [void]$removalItems.Add([pscustomobject]@{
            ProfileCode=$entry.ProfileCode
            GameRoot=$gameRoot
            Destination=$destination
            DeployedSha256=$entry.DeployedSha256
            Backup=$backupPath
            Hash=$entry.DeployedSha256
        })
    }
    if ($removalItems.Count -eq 0) { return $false }
    $result = Invoke-TpmFfbPluginFileTransaction `
        -Removals $removalItems.ToArray() -CacheDir $CacheDir `
        -OwnershipEntries $remaining.ToArray()
    if ($result.Outcome -in @('SUCCEEDED','NO_OP')) {
        $script:FFBOwnedRemovalRecords = $removalItems.ToArray()
        return $true
    }
    if ($result.Outcome -eq 'ROLLED_BACK_VERIFIED') {
        throw 'FFBPlugin ownership manifest update failed; deletion was rolled back.'
    }
    throw 'FFBPlugin ownership manifest update failed and deletion rollback was incomplete.'
}
function Invoke-FFBPluginSetup {
    param(
        [string]$UserProfilesDir,
        [string]$CacheDir,
        [string[]]$NativeEnabledCodes = @(),
        [string]$TpRoot = '',
        [string]$EvidencePath = '',
        [string[]]$ProtectedRoots = @()
    )

    if ($null -eq $NativeEnabledCodes) { $NativeEnabledCodes = @() }
    $nativeEnabledSet = [System.Collections.Generic.HashSet[string]]::new(
        [string[]]$NativeEnabledCodes, [System.StringComparer]::OrdinalIgnoreCase)
    $ownershipSnapshot = Get-FFBPluginOwnershipSnapshot -CacheDir $CacheDir
    $ownershipEntries = @(Read-FFBPluginOwnership -CacheDir $CacheDir)
    $nativeRemovedThisRun = New-Object System.Collections.Generic.List[object]
    $deployedThisRun = New-Object System.Collections.Generic.List[object]
    $nativeSwitch = $null

    Write-Host ""
    $source = Get-FFBPluginSourceRevision
    if (-not $source -or -not (Test-FFBPluginRevision -Revision $source.Revision)) {
        Write-Host "  Could not verify the FFB plugin source revision -- no files were changed." -ForegroundColor Red
        return [pscustomobject]@{
            Succeeded = $false; Deployed = 0; Errors = 1
            MissingPath = 0; MissingDevice = 0; MissingPathGames = @(); MissingDeviceGames = @()
            Accounted = 0; Eligible = 0; AccountingComplete = $true
            Reason = 'SOURCE_REVISION_UNAVAILABLE'
        }
    }
    Write-Host "  Fetching the supported-games list..." -ForegroundColor DarkGray
    $gameMap = Get-FFBPluginGameMap -SourceRevision $source.Revision
    if (-not $gameMap -or $gameMap.Count -eq 0) {
        if ($null -eq $gameMap) { Write-Host "  Could not reach GitHub to fetch the supported FFB plugin game list -- check that this PC can reach github.com (internet, VPN, proxy or firewall), then run force-feedback setup again. No files were changed." -ForegroundColor Red }
        else { Write-Host "  GitHub answered, but it did not give a usable list of supported FFB plugin games. The list may have been moved or changed, or GitHub may be limiting requests. No files were changed. TeknoParrot-Manager.log has details." -ForegroundColor Red }
        Write-Log "FFBPlugin setup: aborted -- supported game map fetch failed."
        return [pscustomobject]@{
            Succeeded = $false; Deployed = 0; Errors = 1
            MissingPath = 0; MissingDevice = 0; MissingPathGames = @(); MissingDeviceGames = @()
            Accounted = 0; Eligible = 0; AccountingComplete = $true
            SourceRevision = $source.Revision; SourceTrust = $source.Trust
            Reason = 'GAME_MAP_FAILED'
        }
    }
    Write-Host ("  {0} game(s) in the supported-games list." -f $gameMap.Count) -ForegroundColor DarkGray

    $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'FFB plugin profile discovery' -EnumerationErrorAction SilentlyContinue)
    if ($profiles.Count -eq 0) {
        Write-Host "  No registered games found." -ForegroundColor Yellow
        Write-Log "FFBPlugin setup: aborted -- no registered profiles."
        return [pscustomobject]@{
            Succeeded = $false; Deployed = 0; Errors = 0
            MissingPath = 0; MissingDevice = 0; MissingPathGames = @(); MissingDeviceGames = @()
            Accounted = 0; Eligible = 0; AccountingComplete = $true
            SourceRevision = $source.Revision; SourceTrust = $source.Trust
            Reason = 'NO_REGISTERED_PROFILES'
        }
    }

    Write-Host "  Downloading the verified FFB plugin files..." -ForegroundColor DarkGray
    $download = Invoke-FFBPluginDownload -destDir $CacheDir -SourceRevision $source.Revision
    if (-not $download -or -not [bool]$download.Succeeded) {
        Write-Host "  Could not download and hash both verified FFB plugin DLLs -- check that this PC can reach github.com and that antivirus is not blocking the download, then run force-feedback setup again. No files were changed." -ForegroundColor Red
        Write-Log "FFBPlugin setup: aborted -- verified plugin file acquisition failed."
        return [pscustomobject]@{
            Succeeded = $false; Deployed = 0; Errors = 1
            MissingPath = 0; MissingDevice = 0; MissingPathGames = @(); MissingDeviceGames = @()
            Accounted = 0; Eligible = 0; AccountingComplete = $true
            SourceRevision = $source.Revision; SourceTrust = $source.Trust
            SourceEvidence = @($download.Evidence)
            AcquisitionResidue = @($download.ResiduePaths)
            Reason = if ($download.Reason) { $download.Reason } else { 'DLL_ACQUISITION_FAILED' }
        }
    }
    $srcDll32 = [string]$download.Files['MAME32.dll']
    $srcDll64 = [string]$download.Files['MAME64.dll']
    if ([string]::IsNullOrWhiteSpace($srcDll32) -or [string]::IsNullOrWhiteSpace($srcDll64) -or
        -not (Test-Path -LiteralPath $srcDll32 -PathType Leaf) -or
        -not (Test-Path -LiteralPath $srcDll64 -PathType Leaf)) {
        Write-Host "  Verified FFB plugin staging is incomplete -- no files were changed." -ForegroundColor Red
        Write-Log "FFBPlugin setup: aborted -- staged DLL set was incomplete."
        return [pscustomobject]@{
            Succeeded = $false; Deployed = 0; Errors = 1
            MissingPath = 0; MissingDevice = 0; MissingPathGames = @(); MissingDeviceGames = @()
            Accounted = 0; Eligible = 0; AccountingComplete = $true
            SourceRevision = $source.Revision; SourceTrust = $source.Trust
            SourceEvidence = @($download.Evidence)
            Reason = 'DLL_ACQUISITION_FAILED'
        }
    }

    $preflightEvidenceWritten = $false
    if (-not [string]::IsNullOrWhiteSpace($EvidencePath)) {
        try {
            Write-FFBPluginEvidence -EvidencePath $EvidencePath -Evidence ([ordered]@{
                SchemaVersion = 1
                Phase = 'Preflight'
                CreatedUtc = (Get-Date).ToUniversalTime().ToString('o')
                SourceRepository = $source.Repository
                SourceManifestUrl = $source.ManifestUrl
                SourceRevision = $source.Revision
                SourceTrust = $source.Trust
                SourceFiles = @($download.Evidence)
                SelectedGames = @($profiles | ForEach-Object { $_.BaseName })
                OwnershipManifest = Get-FFBPluginOwnershipPath -CacheDir $CacheDir
                Result = $null
            })
            $preflightEvidenceWritten = $true
        } catch {
            Write-Host "  Could not create the FFB evidence report -- no files were changed." -ForegroundColor Red
            Write-Log "FFBPlugin setup: aborted -- evidence preflight failed -- $_"
            return [pscustomobject]@{
                Succeeded = $false; Deployed = 0; Errors = 1
                MissingPath = 0; MissingDevice = 0; MissingPathGames = @(); MissingDeviceGames = @()
                Accounted = 0; Eligible = 0; AccountingComplete = $true
                SourceRevision = $source.Revision; SourceTrust = $source.Trust
                SourceEvidence = @($download.Evidence)
                EvidencePath = $EvidencePath
                Reason = 'EVIDENCE_PREFLIGHT_FAILED'
            }
        }
    }

    $normFfbList = @(foreach ($name in $gameMap.Keys) {
        [pscustomobject]@{ Name = $name; Norm = (Get-NormalizedGameKey $name); Dest = $gameMap[$name] }
    })
    Write-Host ""
    Write-Host ("  Matching {0} registered game(s) against the supported-games list..." -f $profiles.Count) -ForegroundColor Cyan

    $candidates = @()
    $missingPathGames = New-Object System.Collections.Generic.List[string]
    $missingDeviceGames = New-Object System.Collections.Generic.List[string]
    $pathReasonCounts = @{}
    $matchErrors = 0
    $matchStarted = Get-Date
    $matchCurrent = 0
    foreach ($pf in $profiles) {
        $matchCurrent++
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'FFB plugin profile matching' -Current $matchCurrent -Total $profiles.Count -StartedAt $matchStarted
        try {
            $doc = Read-Xml $pf.FullName
            $gamePath = ''
            if ($doc.GameProfile) {
                $gpNode = $doc.GameProfile.SelectSingleNode("GamePath")
                if ($gpNode) { $gamePath = $gpNode.InnerText.Trim() }
            }
            $pathCheck = Test-TpmGameMutationPath -GamePath $gamePath -RequireLeaf
            if (-not $pathCheck.Valid) {
                $reasonCode = [string]$pathCheck.ReasonCode
                if (-not $pathReasonCounts.ContainsKey($reasonCode)) { $pathReasonCounts[$reasonCode] = 0 }
                $pathReasonCounts[$reasonCode]++
                if ($reasonCode -eq 'DEVICE_UNAVAILABLE') {
                    [void]$missingDeviceGames.Add($pf.BaseName)
                } else {
                    [void]$missingPathGames.Add($pf.BaseName)
                }
                continue
            }
            $gamePath = [string]$pathCheck.ResolvedPath
            $exeDir = [string]$pathCheck.GameDirectory
            $folderName = Split-Path -Path $exeDir -Leaf
            $normFolder = Get-NormalizedGameKey $folderName
            $best = $null; $bestScore = 0.0
            foreach ($cand in $normFfbList) {
                $score = Get-DiceSimilarity $normFolder $cand.Norm
                if ($score -gt $bestScore) { $bestScore = $score; $best = $cand }
            }
            if ($null -eq $best -or $bestScore -lt $FuzzyAutoThreshold) { continue }
            $candidates += [pscustomobject]@{
                Profile = $pf; GamePath = $gamePath; ExeDir = $exeDir
                Match = $best; Score = $bestScore
            }
        } catch {
            Write-Host ("    ERROR {0} -- {1}" -f $pf.BaseName, $_) -ForegroundColor Red
            Write-Log "FFBPlugin: error reading $($pf.BaseName) -- $_"
            $matchErrors++
        }
    }
    if ($profiles.Count -gt 0) {
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'FFB plugin profile matching' -Current $matchCurrent -Total $profiles.Count -StartedAt $matchStarted -Complete
    }

    $overlaps = @($candidates | Where-Object { $nativeEnabledSet.Contains($_.Profile.BaseName) })
    $useNativeForOverlaps = $true
    if ($overlaps.Count -gt 0) {
        Write-Host ""
        Write-Host ("  {0} game(s) are covered by both available force-feedback options:" -f $overlaps.Count) -ForegroundColor Cyan
        foreach ($ov in $overlaps) {
            $overlapName = $ov.Profile.BaseName
            try {
                $overlapDoc = Read-Xml $ov.Profile.FullName
                if ($overlapDoc.GameProfile.GameName) { $overlapName = ([string]$overlapDoc.GameProfile.GameName).Trim() }
            } catch {}
            Write-Host ("    - {0}" -f $overlapName) -ForegroundColor DarkGray
        }
        Write-Host "  [Y] Keep native FFB Blaster (recommended)" -ForegroundColor White
        Write-Host "  [N] Use the optional plugin instead" -ForegroundColor White
        $ans = Read-TpmYesNo -Prompt '  Choose Y or N' -Default 'Y'
        $useNativeForOverlaps = ($ans -ne "N")
        if (-not $useNativeForOverlaps) {
            Write-Host "  Disabling native FFB Blaster on the overlapping profiles before plugin deployment..." -ForegroundColor Yellow
            $nativeSwitch = Disable-FFBBlasterForOverlap -UserProfilesDir $UserProfilesDir -TpRoot $TpRoot -ProfileCodes @($overlaps | ForEach-Object { $_.Profile.BaseName })
            if (-not $nativeSwitch.Succeeded) {
                Write-Host ("  ERROR: Could not switch overlapping profiles to the optional plugin -- {0}" -f $nativeSwitch.Reason) -ForegroundColor Red
                Write-Log "FFBPlugin: blocked because native overlap switch failed -- $($nativeSwitch.Reason)"
                return [pscustomobject]@{
                    Succeeded = $false; Deployed = 0; Errors = 1
                    MissingPath = $missingPathGames.Count; MissingDevice = $missingDeviceGames.Count
                    MissingPathGames = $missingPathGames.ToArray(); MissingDeviceGames = $missingDeviceGames.ToArray()
                    PathReasonCounts = $pathReasonCounts; Accounted = 0; Eligible = $candidates.Count
                    AccountingComplete = $false; SourceRevision = $source.Revision; SourceTrust = $source.Trust
                    SourceEvidence = @($download.Evidence); EvidencePath = $EvidencePath
                    Reason = 'NATIVE_OVERLAP_SWITCH_FAILED'
                }
            }
        }
    }

    $deployed = 0; $skippedNative = 0; $skippedCollision = 0
    $skippedDllMissing = 0
    $skippedMissingPath = $missingPathGames.Count
    $skippedMissingDevice = $missingDeviceGames.Count
    $sourceFolderGames = New-Object System.Collections.Generic.List[string]
    $errors = $matchErrors
    $invalidPathCount = $skippedMissingPath + $skippedMissingDevice
    $skippedNoMatch = [Math]::Max(0, $profiles.Count - $candidates.Count - $matchErrors - $invalidPathCount)

    $deploymentPlans = New-Object System.Collections.Generic.List[object]
    $planningStarted = Get-Date
    $planningCurrent = 0
    foreach ($c in $candidates) {
        $planningCurrent++
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'FFB plugin deployment planning' -Current $planningCurrent -Total $candidates.Count -StartedAt $planningStarted
        $pf = $c.Profile
        $gameLabel = $pf.BaseName
        try {
            $labelDoc = Read-Xml $pf.FullName
            if ($labelDoc.GameProfile.GameName) { $gameLabel = ([string]$labelDoc.GameProfile.GameName).Trim() }
        } catch {}
        try {
            if ($nativeEnabledSet.Contains($pf.BaseName) -and $useNativeForOverlaps) {
                [void](Remove-FFBPluginOwnedDeployment -CacheDir $CacheDir -ProfileCode $pf.BaseName -ProtectedRoots $ProtectedRoots)
                foreach ($removedItem in @($script:FFBOwnedRemovalRecords)) { [void]$nativeRemovedThisRun.Add($removedItem) }
                # The removal rewrote the manifest on disk; keep the entries already planned earlier in this run.
                $plannedDestinations = @($deploymentPlans | ForEach-Object { [string]$_.Destination })
                $ownershipEntries = @(@(Read-FFBPluginOwnership -CacheDir $CacheDir) | Where-Object { $plannedDestinations -inotcontains [string]$_.Destination }) + @($deploymentPlans.ToArray())
                $skippedNative++
                continue
            }

            $latestPathCheck = Test-TpmGameMutationPath -GamePath $c.GamePath -RequireLeaf -ProtectedRoots $ProtectedRoots
            if (-not $latestPathCheck.Valid) {
                $reasonCode = [string]$latestPathCheck.ReasonCode
                if (-not $pathReasonCounts.ContainsKey($reasonCode)) { $pathReasonCounts[$reasonCode] = 0 }
                $pathReasonCounts[$reasonCode]++
                # A game whose native FFB was just switched off must not be left with no force feedback (same rule as a file collision below).
                # It is counted once, as a failed preflight, and not also as a skip.
                $nativeLost = [bool]($nativeSwitch -and $nativeEnabledSet.Contains($pf.BaseName))
                if ($reasonCode -eq 'DEVICE_UNAVAILABLE') {
                    [void]$missingDeviceGames.Add($pf.BaseName)
                    if (-not $nativeLost) { $skippedMissingDevice++ }
                } elseif ($reasonCode -eq 'SOURCE_COLLECTION') {
                    if (-not $nativeLost) { [void]$sourceFolderGames.Add([string]$gameLabel) }
                    Write-Log ("FFBPlugin: refused {0}; path reason=SOURCE_COLLECTION; detail={1}; game path={2}" -f $pf.BaseName, $latestPathCheck.Reason, $c.GamePath)
                } else {
                    [void]$missingPathGames.Add($pf.BaseName)
                    if (-not $nativeLost) { $skippedMissingPath++ }
                }
                if ($nativeLost) { $errors++ }
                continue
            }

            $exeDir = [string]$latestPathCheck.GameDirectory
            $destDll = [string]$c.Match.Dest
            $destPath = Join-Path $exeDir $destDll
            if (-not (Test-PathInside $destPath $exeDir) -or -not (Test-TpmNoReparsePath -Path $exeDir)) {
                Write-Host ("    SKIP  {0}: the destination file is unsafe -- not deploying." -f $gameLabel) -ForegroundColor Red
                Write-Log "FFBPlugin: SECURITY -- skipped $($pf.BaseName), unsafe destination $destPath"
                $errors++
                continue
            }
            $arch = Get-ExeArchitecture -ExePath $c.GamePath
            if ($arch -ne 'x86' -and $arch -ne 'x64') {
                # A guessed 64-bit plugin in a 32-bit game never loads, and the run would still count it as installed.
                Write-Host ("    SKIP  {0}: TeknoParrot Manager could not tell whether this game is 32-bit or 64-bit, so no plugin file was placed." -f $gameLabel) -ForegroundColor Yellow
                Write-Log "FFBPlugin: skipped $($pf.BaseName) -- the game's 32-bit/64-bit type could not be read from $($c.GamePath)"
                if ($nativeSwitch -and $nativeEnabledSet.Contains($pf.BaseName)) { $errors++ } else { $skippedDllMissing++ }
                continue
            }
            $dllName = if ($arch -eq 'x86') { 'MAME32.dll' } else { 'MAME64.dll' }
            $srcDll = [string]$download.Files[$dllName]
            if ([string]::IsNullOrWhiteSpace($srcDll) -or -not (Test-Path -LiteralPath $srcDll -PathType Leaf)) {
                Write-Host ("    SKIP  {0}: the verified {1}-bit plugin file is unavailable." -f $gameLabel,$(if($arch -eq 'x86'){'32'}else{'64'})) -ForegroundColor Yellow
                if ($nativeSwitch -and $nativeEnabledSet.Contains($pf.BaseName)) { $errors++ } else { $skippedDllMissing++ }
                continue
            }
            # A hook that TeknoParrot Manager itself recorded (and that is unchanged) is replaced through the same recorded,
            # backed-up removal as the native-FFB switch. Anything else in that spot is not ours and is never touched.
            if (Test-Path -LiteralPath $destPath -PathType Leaf) {
                $ownEntry = @($ownershipEntries | Where-Object { [string]$_.Destination -ieq $destPath -and -not [string]::IsNullOrWhiteSpace([string]$_.ProfileCode) } | Select-Object -First 1)
                if ($ownEntry.Count -eq 1) {
                    [void](Remove-FFBPluginOwnedDeployment -CacheDir $CacheDir -ProfileCode ([string]$ownEntry[0].ProfileCode) -ProtectedRoots $ProtectedRoots)
                    foreach ($removedItem in @($script:FFBOwnedRemovalRecords)) { [void]$nativeRemovedThisRun.Add($removedItem) }
                    $plannedDestinations = @($deploymentPlans | ForEach-Object { [string]$_.Destination })
                    $ownershipEntries = @(@(Read-FFBPluginOwnership -CacheDir $CacheDir) | Where-Object { $plannedDestinations -inotcontains [string]$_.Destination }) + @($deploymentPlans.ToArray())
                }
            }
            if (Test-Path -LiteralPath $destPath -PathType Leaf) {
                Write-Host ("    SKIP  {0}: an existing file was found, so it was not overwritten." -f $gameLabel) -ForegroundColor Yellow
                Write-Log "FFBPlugin: skipped $($pf.BaseName) -- $destDll already occupied at $destPath"
                # A game whose native FFB was just switched off must not be left with no force feedback: count it as a failed preflight,
                # which restores native FFB for the switched profiles and installs nothing.
                if ($nativeSwitch -and $nativeEnabledSet.Contains($pf.BaseName)) { $errors++ } else { $skippedCollision++ }
                continue
            }

            $sourceHash = (Get-FileHash -LiteralPath $srcDll -Algorithm SHA256 -ErrorAction Stop).Hash
            $sourceEvidence = @($download.Evidence | Where-Object { $_.FileName -eq $dllName }) | Select-Object -First 1
            if (-not $sourceEvidence -or $sourceHash -ine [string]$sourceEvidence.Sha256) {
                throw "FFBPlugin: staged $dllName hash no longer matches acquisition evidence."
            }
            $entry = [pscustomobject]@{
                ProfileCode=$pf.BaseName
                GameRoot=$exeDir
                Destination=$destPath
                SourcePath=$srcDll
                SourceHash=$sourceHash
                SourceSha256=$sourceHash
                DeployedSha256=$sourceHash
                SourceRevision=$source.Revision
                SourceTrust=$source.Trust
                GameLabel=$gameLabel
                CreatedUtc=(Get-Date).ToUniversalTime().ToString('o')
            }
            $ownershipEntries = @($ownershipEntries | Where-Object { $_.Destination -ine $destPath })
            $ownershipEntries += $entry
            [void]$deploymentPlans.Add($entry)
        } catch {
            Write-Host ("    ERROR {0} -- {1}" -f $gameLabel,$_) -ForegroundColor Red
            Write-Log "FFBPlugin: preflight error on $($pf.BaseName) -- $_"
            $errors++
        }
    }
    if ($candidates.Count -gt 0) {
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'FFB plugin deployment planning' -Current $planningCurrent -Total $candidates.Count -StartedAt $planningStarted -Complete
    }
    if ($errors -gt 0) {
        $transactionResult = New-TpmFileBatchResult `
            -WorkflowKey 'FFBPlugin' -OperationKey 'FileDeployment' `
            -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' `
            -Summary 'The optional plugin could not complete its deployment preflight.' `
            -Items @($deploymentPlans | ForEach-Object { 'FFB:' + $_.ProfileCode }) `
            -ReasonCode 'PREFLIGHT_FAILED' `
            -TechnicalDetails ([pscustomobject]@{ Stage='Preflight'; Error='One or more selected plugin deployments failed preflight.' })
    } else {
        $transactionResult = Invoke-TpmFfbPluginFileTransaction `
            -Deployments $deploymentPlans.ToArray() -CacheDir $CacheDir `
            -OwnershipEntries $ownershipEntries
    }
    if ($transactionResult.Outcome -in @('SUCCEEDED','NO_OP')) {
        foreach ($plan in $deploymentPlans) {
            [void]$deployedThisRun.Add($plan)
            Write-Host ("    OK    {0}  (optional plugin installed)" -f $(if($plan.GameLabel){$plan.GameLabel}else{$plan.ProfileCode})) -ForegroundColor Green
            Write-Log "FFBPlugin: verified deployment of $([System.IO.Path]::GetFileName($plan.Destination)) to $($plan.GameRoot)"
            $deployed++
        }
    } else {
        if ($transactionResult.Outcome -ne 'FAILED_BEFORE_MUTATION' -or $errors -eq 0) { $errors++ }
        Write-Host $(if ($transactionResult.Outcome -eq 'FAILED_BEFORE_MUTATION') { '  The optional plugin was not installed because a safety check failed before any game file was changed. See the messages above and TeknoParrot-Manager.log.' } else { '  The optional plugin file changes did not complete and were rolled back where possible. See TeknoParrot-Manager.log.' }) -ForegroundColor Yellow
        Write-Log ("FFBPlugin: file transaction outcome={0} reason={1}" -f $transactionResult.Outcome,$transactionResult.ReasonCode)
        if ($nativeSwitch -or $nativeRemovedThisRun.Count -gt 0 -or $transactionResult.Outcome -eq 'ACTION_REQUIRED') {
            $nativeRestore = Restore-FFBPluginDeploymentTransaction `
                -Entries $deploymentPlans.ToArray() -RemovedItems $nativeRemovedThisRun.ToArray() -CacheDir $CacheDir `
                -OwnershipSnapshot $ownershipSnapshot -UserProfilesDir $UserProfilesDir `
                -OverlapBackupPath $(if ($nativeSwitch) { [string]$nativeSwitch.BackupPath } else { '' })
            if (-not $nativeRestore.Succeeded) {
                $errors++
                Write-Host ("  FFB native rollback INCOMPLETE: {0}" -f ($nativeRestore.Errors -join ' ;; ')) -ForegroundColor Red
                Write-Log ("FFBPlugin: native rollback after file transaction failure was incomplete -- {0}" -f ($nativeRestore.Errors -join ' ;; '))
            }
        }
    }

    Write-Host ""
    Write-Host ("  Installed           : {0} game(s)" -f $deployed) -ForegroundColor Green
    if ($skippedNative -gt 0) { Write-Host ("  Kept native FFB     : {0}  (native FFB Blaster is preferred)" -f $skippedNative) -ForegroundColor DarkGray }
    if ($skippedCollision -gt 0) { Write-Host ("  Skipped (file exists): {0}  (the existing file was not overwritten)" -f $skippedCollision) -ForegroundColor Yellow }
    if ($skippedNoMatch -gt 0) { Write-Host ("  Skipped (not supported): {0}  (the optional plugin does not support these games)" -f $skippedNoMatch) -ForegroundColor DarkGray }
    if ($skippedDllMissing -gt 0) { Write-Host ("  Skipped (plugin file unavailable or game type unreadable): {0}" -f $skippedDllMissing) -ForegroundColor Yellow }
    if ($skippedMissingPath -gt 0) {
        Write-Host ("  Skipped (saved path): {0} game(s)  -- repair paths in 13) Library Health Check first" -f $skippedMissingPath) -ForegroundColor Yellow
        Write-Host ("    Affected games: {0}" -f ($missingPathGames -join ', ')) -ForegroundColor DarkGray
    }
    if ($skippedMissingDevice -gt 0) {
        Write-Host ("  Skipped (device unavailable): {0} game(s)  -- reconnect the drive and retry" -f $skippedMissingDevice) -ForegroundColor Yellow
        Write-Host ("    Affected games: {0}" -f ($missingDeviceGames -join ', ')) -ForegroundColor DarkGray
    }
    Write-TpmSourceFolderRefusal -Count $sourceFolderGames.Count
    if ($errors -gt 0) { Write-Host ("  Errors             : {0}  -- see TeknoParrot-Manager.log for details" -f $errors) -ForegroundColor Red }

    $accounted = $skippedNative + $skippedCollision + $skippedNoMatch + $skippedDllMissing + $skippedMissingPath + $skippedMissingDevice + $sourceFolderGames.Count + $errors + $deployed
    $accountingComplete = ($accounted -eq $profiles.Count)
    $blockingSkips = $skippedDllMissing + $skippedMissingPath + $skippedMissingDevice + $sourceFolderGames.Count
    $succeeded = ($transactionResult.Outcome -in @('SUCCEEDED','NO_OP') -and $errors -eq 0 -and $blockingSkips -eq 0 -and $accountingComplete)
    $reason = if ($transactionResult.Outcome -notin @('SUCCEEDED','NO_OP')) { $transactionResult.ReasonCode } elseif (-not $accountingComplete) { 'ACCOUNTING_INCOMPLETE' } elseif ($errors -gt 0) { 'DEPLOYMENT_ERRORS' } elseif ($blockingSkips -gt 0) { 'BLOCKED_SKIPS' } elseif ($deployed -gt 0) { 'DEPLOYED' } elseif ($skippedNative -gt 0 -and $skippedNoMatch -eq 0) { 'NATIVE_PREFERRED' } elseif ($skippedNoMatch -gt 0 -and $skippedNative -eq 0) { 'NO_SUPPORTED_PLUGIN_TARGET' } else { 'NO_PLUGIN_CHANGES_NEEDED' }
    $rollback = $null
    if (-not [string]::IsNullOrWhiteSpace($EvidencePath)) {
        $evidence = [ordered]@{
            SchemaVersion = 1
            Phase = 'Final'
            CreatedUtc = (Get-Date).ToUniversalTime().ToString('o')
            SourceRepository = $source.Repository
            SourceManifestUrl = $source.ManifestUrl
            SourceRevision = $source.Revision
            SourceTrust = $source.Trust
            SourceFiles = @($download.Evidence)
            SelectedGames = @($profiles | ForEach-Object { $_.BaseName })
            OwnershipManifest = Get-FFBPluginOwnershipPath -CacheDir $CacheDir
            Result = [ordered]@{
                Deployed = $deployed; SkippedNative = $skippedNative; SkippedCollision = $skippedCollision
                SkippedNoMatch = $skippedNoMatch; SkippedDllMissing = $skippedDllMissing
                SkippedMissingPath = $skippedMissingPath; SkippedMissingDevice = $skippedMissingDevice; SkippedSourceFolder = $sourceFolderGames.Count
                Errors = $errors; Accounted = $accounted; Selected = $profiles.Count
            }
        }
        try {
            Write-FFBPluginEvidence -EvidencePath $EvidencePath -Evidence $evidence
        } catch {
            $attemptedDeployed = $deployed
            $rollback = Restore-FFBPluginDeploymentTransaction `
                -Entries $deployedThisRun.ToArray() `
                -RemovedItems $nativeRemovedThisRun.ToArray() `
                -CacheDir $CacheDir `
                -OwnershipSnapshot $ownershipSnapshot `
                -UserProfilesDir $UserProfilesDir `
                -OverlapBackupPath $(if ($nativeSwitch) { [string]$nativeSwitch.BackupPath } else { '' })
            $errors += $attemptedDeployed
            $deployed = 0
            $succeeded = $false
            $reason = if ($rollback.Succeeded) { 'EVIDENCE_WRITE_FAILED' } else { 'EVIDENCE_WRITE_ROLLBACK_FAILED' }
            Write-Log "FFBPlugin: final evidence write failed -- $($_.Exception.Message); rollbackSucceeded=$($rollback.Succeeded)"
        }
    }

    Write-Host ""
    Write-Host "  TeknoParrot Manager only removes optional plugin files that it recorded as its own." -ForegroundColor DarkCyan
    Write-Log 'FFBPlugin setup: technical ownership rule -- unowned FFB files are never removed automatically.'
    Write-Log ("FFBPlugin setup: deployed={0} skippedNative={1} skippedCollision={2} skippedNoMatch={3} skippedDllMissing={4} skippedMissingPath={5} skippedMissingDevice={6} errors={7} accounted={8}/{9} sourceRevision={10}" -f $deployed, $skippedNative, $skippedCollision, $skippedNoMatch, $skippedDllMissing, $skippedMissingPath, $skippedMissingDevice, $errors, $accounted, $profiles.Count, $source.Revision)
    return [pscustomobject]@{
        Reason = $reason
        Succeeded = $succeeded
        NoOp = ($succeeded -and $deployed -eq 0 -and $nativeRemovedThisRun.Count -eq 0 -and $null -eq $nativeSwitch)
        Deployed = $deployed
        Errors = $errors
        MissingPath = $skippedMissingPath
        MissingDevice = $skippedMissingDevice
        MissingPathGames = $missingPathGames.ToArray()
        MissingDeviceGames = $missingDeviceGames.ToArray()
        SourceFolderGames = $sourceFolderGames.ToArray()
        PathReasonCounts = $pathReasonCounts
        SkippedNoMatch = $skippedNoMatch
        SkippedDllMissing = $skippedDllMissing
        SkippedNative = $skippedNative
        SkippedCollision = $skippedCollision
        Accounted = $accounted
        Eligible = $candidates.Count
        AccountingComplete = $accountingComplete
        SourceRevision = $source.Revision
        SourceTrust = $source.Trust
        SourceEvidence = @($download.Evidence)
        EvidencePath = $EvidencePath
        PreflightEvidenceWritten = $preflightEvidenceWritten
        RollbackSucceeded = if ($rollback) { [bool]$rollback.Succeeded } else { $null }
        RollbackErrors = if ($rollback) { @($rollback.Errors) } else { @() }
        TransactionResult = $transactionResult
    }

}

# GameProfiles at runtime -- never hardcoded. Shared (read-only) between
# Invoke-FFBBlasterSetup and the Library health check's coverage report.
function Get-FFBBlasterFieldNames {
    param([string]$GameProfilesDir)

    $ffbFields = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    if (Test-Path -LiteralPath $GameProfilesDir) {
        $gpFiles = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $GameProfilesDir -ProgressLabel 'FFB GameProfiles discovery' -Filter '*.xml' -EnumerationErrorAction SilentlyContinue -IncludeDirectories)
        $scanStarted = Get-Date
        $scanCurrent = 0
        $scanCurrentDone = $false
        try {
            foreach ($gf in $gpFiles) {
                $scanCurrent++
                Write-TpmCompactExtractionProgress -Phase Scanning -Label 'FFB profile catalog scan' -Current $scanCurrent -Total $gpFiles.Count -StartedAt $scanStarted
            try {
                $gdoc = Read-Xml $gf.FullName
                $fnodes = $gdoc.SelectNodes("/GameProfile/ConfigValues/FieldInformation")
                foreach ($n in $fnodes) {
                    $cn = if ($n.CategoryName) { $n.CategoryName.Trim() } else { '' }
                    $fn = if ($n.FieldName)     { $n.FieldName.Trim()     } else { '' }
                    $ft = if ($n.FieldType)     { $n.FieldType.Trim()     } else { '' }
                    if ($ft -ne 'Bool') { continue }
                    if ($cn -imatch 'ffb.*blaster|blaster.*ffb') {
                        [void]$ffbFields.Add($cn)
                    } elseif ($fn -and $fn -imatch 'ffb.*blaster|blaster.*ffb') {
                        # Older TP builds that put the identifying text on
                        # FieldName instead of CategoryName -- fall back to
                        # treating the field name itself as the category key.
                        [void]$ffbFields.Add($fn)
                    }
                }
            } catch {
                Write-Log ("FFBBlaster: WARNING -- could not parse GameProfile '$($gf.BaseName)': $_")
            }
            }
            $scanCurrentDone = $true
        } finally {
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'GameProfiles' -Current $(if ($scanCurrentDone) { $scanCurrent } else { $scanCurrent - 1 }) -Total $gpFiles.Count -StartedAt $scanStarted -Complete -Outcome $(if ($scanCurrentDone) { 'Final' } else { 'Error' })
        }
    }
    return $ffbFields
}

# Pure decision function: for a given UserProfile XML and the category
# keys discovered by Get-FFBBlasterFieldNames (a CategoryName on newer TP
# builds, or a literal FieldName on older ones -- see that function's
# fallback), determines whether the profile has an FFB Blaster field at
# all (Eligible) and whether it is already set to '1' (UpToDate). Returns
# the exact node + target value for any field that needs changing,
# mirroring Test-GpuFixUpToDate.
function Test-FFBBlasterUpToDate {
    param([System.Xml.XmlDocument]$Doc, $Categories)

    $eligible = $false
    $changes  = New-Object System.Collections.Generic.List[object]

    foreach ($key in $Categories) {
        $xpLit = ConvertTo-XPathStringLiteral $key
        $fis = @($Doc.SelectNodes("/GameProfile/ConfigValues/FieldInformation[CategoryName=$xpLit]"))
        if ($fis.Count -eq 0) {
            # Fallback for older-build profiles where $key is a literal FieldName.
            $fis = @($Doc.SelectNodes("/GameProfile/ConfigValues/FieldInformation[FieldName=$xpLit]"))
        }
        foreach ($fi in $fis) {
            $ft = if ($fi.FieldType) { $fi.FieldType.Trim() } else { '' }
            if ($ft -ne 'Bool') { continue }
            $fvNode = $fi.SelectSingleNode("FieldValue")
            if ($null -eq $fvNode) { continue }
            $eligible = $true
            $fieldName = if ($fi.FieldName) { $fi.FieldName.Trim() } else { '' }
            if ($fvNode.InnerText -ne '1') {
                [void]$changes.Add([pscustomobject]@{ FieldName = $fieldName; Node = $fvNode; OldValue = $fvNode.InnerText; NewValue = '1' })
            }
        }
    }

    return [pscustomobject]@{ Eligible = $eligible; UpToDate = ($eligible -and $changes.Count -eq 0); Changes = $changes }
}

# Platforms/emulation paths on which TeknoParrot's native FFB Blaster is
# NOT currently supported, keyed by the GameProfile's own EmulationProfile
# (or EmulatorType) value -- compared case-insensitively. This is an
# explicit deny-list, not an allow-list: the script does NOT maintain a
# positive roster of every supported platform (that would go stale on every
# upstream addition and wrongly mark brand-new platforms as unsupported).
# Instead, only platforms POSITIVELY known not to support FFB Blaster are
# listed here, so a write is blocked for them even if a profile somehow
# carries an FFB-Blaster-shaped field. 'pcsx2x6' is the confirmed case
# (issue #41): TeknoParrot's PCSX2 fork does not implement FFB Blaster, and
# its profiles legitimately have no such field today -- but a future
# upstream change must never cause this script to enable it there. Add a
# platform here only after positively confirming FFB Blaster does not work
# on it; never the reverse.
$script:FFBBlasterUnsupportedPlatforms = @('pcsx2x6')

# Regex identifying any FieldInformation node (by CategoryName or FieldName)
# that LOOKS like an FFB Blaster control, regardless of whether it is a
# well-formed Bool field. Used to distinguish "this game genuinely has no
# FFB Blaster control" (Unsupported) from "something FFB-Blaster-shaped is
# here but does not match the schema we know how to write" (Unknown).
$script:FFBBlasterNamePattern = 'ffb.*blaster|blaster.*ffb'

# Pure capability/safety gate for native FFB Blaster on a single profile.
# Supersedes a bare Test-FFBBlasterUpToDate call at every decision point
# (Invoke-FFBBlasterSetup and the Library health check) so the platform
# deny-list and the unknown-field safety state are enforced in exactly one
# place. Returns a structured outcome -- this is the canonical shape the
# whole FFB Blaster feature reasons about (issue #41):
#   Status     : 'Supported' | 'Unsupported' | 'Unknown'
#   Reason     : human-readable explanation (for logs + the user summary)
#   WouldWrite : $true ONLY when Status='Supported' AND a field actually
#                needs changing -- the single signal a caller may write on.
#   Eligible   : a well-formed Bool FFB Blaster field is present
#   UpToDate   : that field is already enabled
#   Changes    : the exact node(s)+value(s) to write (from
#                Test-FFBBlasterUpToDate), empty unless Status='Supported'
#   Platform   : the EmulationProfile/EmulatorType value examined
# Decision order (deny-list first, so an unsupported platform can never be
# written even if it carries a matching field):
#   1. Platform in $FFBBlasterUnsupportedPlatforms        -> Unsupported
#   2. Well-formed Bool FFB Blaster field present         -> Supported
#   3. FFB-Blaster-shaped field present but malformed     -> Unknown
#      (drift: wrong FieldType, no FieldValue, etc.)
#   4. No FFB-Blaster-shaped field at all                 -> Unsupported
# Only case 2 ever permits a write; cases 1/3/4 always set WouldWrite=$false.
function Get-FFBBlasterSupport {
    param([System.Xml.XmlDocument]$Doc, $Categories)

    # Platform identity: prefer EmulationProfile, fall back to EmulatorType
    # (both carry 'pcsx2x6' on a real PCSX2 fork profile -- confirmed against
    # live teknogods/TeknoParrotUI GameProfiles).
    $platform = ''
    if ($Doc.GameProfile) {
        $epNode = $Doc.GameProfile.SelectSingleNode("EmulationProfile")
        if ($epNode -and $epNode.InnerText) { $platform = $epNode.InnerText.Trim() }
        if ([string]::IsNullOrWhiteSpace($platform)) {
            $etNode = $Doc.GameProfile.SelectSingleNode("EmulatorType")
            if ($etNode -and $etNode.InnerText) { $platform = $etNode.InnerText.Trim() }
        }
    }

    $emptyChanges = New-Object System.Collections.Generic.List[object]

    # 1. Deny-list gate -- always first, never overridden by field presence.
    foreach ($bad in $script:FFBBlasterUnsupportedPlatforms) {
        if ($platform -and ($platform -ieq $bad)) {
            return [pscustomobject]@{
                Status     = 'Unsupported'
                Reason     = "FFB Blaster is not supported on the '$platform' platform"
                WouldWrite = $false
                Eligible   = $false
                UpToDate   = $false
                Changes    = $emptyChanges
                Platform   = $platform
            }
        }
    }

    # 2. Well-formed Bool field present?
    $result = Test-FFBBlasterUpToDate -Doc $Doc -Categories $Categories
    if ($result.Eligible) {
        $would = ($result.Changes.Count -gt 0)
        $reason = if ($would) { "FFB Blaster field present and not yet enabled" }
                  else        { "FFB Blaster field present and already enabled" }
        return [pscustomobject]@{
            Status     = 'Supported'
            Reason     = $reason
            WouldWrite = $would
            Eligible   = $true
            UpToDate   = $result.UpToDate
            Changes    = $result.Changes
            Platform   = $platform
        }
    }

    # 3. Anything FFB-Blaster-shaped present that we could NOT treat as a
    #    writable Bool field? That is schema drift -- never write, flag for
    #    manual review.
    $shaped = $false
    if ($Doc.GameProfile) {
        $fnodes = $Doc.SelectNodes("/GameProfile/ConfigValues/FieldInformation")
        foreach ($n in $fnodes) {
            $cn = if ($n.CategoryName) { $n.CategoryName.Trim() } else { '' }
            $fn = if ($n.FieldName)     { $n.FieldName.Trim()     } else { '' }
            if (($cn -and $cn -imatch $script:FFBBlasterNamePattern) -or
                ($fn -and $fn -imatch $script:FFBBlasterNamePattern)) {
                $shaped = $true; break
            }
        }
    }
    if ($shaped) {
        return [pscustomobject]@{
            Status     = 'Unknown'
            Reason     = "An FFB Blaster-like field was found but does not match the known Bool schema -- skipped for manual review"
            WouldWrite = $false
            Eligible   = $false
            UpToDate   = $false
            Changes    = $emptyChanges
            Platform   = $platform
        }
    }

    # 4. No FFB Blaster control of any shape -- this game simply does not
    #    have the feature.
    return [pscustomobject]@{
        Status     = 'Unsupported'
        Reason     = "This game has no FFB Blaster field"
        WouldWrite = $false
        Eligible   = $false
        UpToDate   = $false
        Changes    = $emptyChanges
        Platform   = $platform
    }
}

# Returns the native FFB Blaster FieldValue nodes for one profile.
function Get-FFBBlasterFieldValueNodes {
    param([System.Xml.XmlDocument]$Doc, $Categories)
    foreach ($key in $Categories) {
        $xpLit = ConvertTo-XPathStringLiteral $key
        $fis = @($Doc.SelectNodes("/GameProfile/ConfigValues/FieldInformation[CategoryName=$xpLit]"))
        if ($fis.Count -eq 0) {
            $fis = @($Doc.SelectNodes("/GameProfile/ConfigValues/FieldInformation[FieldName=$xpLit]"))
        }
        foreach ($fi in $fis) {
            $fieldType = if ($fi.FieldType) { $fi.FieldType.Trim() } else { '' }
            if ($fieldType -ne 'Bool') { continue }
            $fvNode = $fi.SelectSingleNode("FieldValue")
            if ($fvNode) { $fvNode }
        }
    }
}

# Disable native FFB Blaster fields for profiles where the user explicitly
# chooses the third-party plugin. This runs after the native setup step, so it
# must create and verify its own backup immediately before changing profiles.
# A failed preflight or write rolls back from that backup and blocks plugin
# deployment; the workflow must never leave a selected overlap with both owners.
function Disable-FFBBlasterForOverlap {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][string]$TpRoot,
        [Parameter(Mandatory)][string[]]$ProfileCodes
    )
    $codes = [System.Collections.Generic.HashSet[string]]::new(
        [string[]]@($ProfileCodes | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }),
        [System.StringComparer]::OrdinalIgnoreCase)
    if ($codes.Count -eq 0) {
        return [pscustomobject]@{ Succeeded = $true; Disabled = 0; BackupPath = $null; Reason = $null }
    }

    $backupPath = $null
    $backupVerified = $false
    try {
        if (-not (Test-Path -LiteralPath $UserProfilesDir -PathType Container -ErrorAction Stop)) {
            throw "UserProfiles directory is unavailable: $UserProfilesDir"
        }
        $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'FFB overlap profile discovery' -EnumerationErrorAction Stop | Sort-Object BaseName)
        $targets = @($profiles | Where-Object { $codes.Contains($_.BaseName) })
        if ($targets.Count -ne $codes.Count) {
            throw 'An overlapping native FFB profile disappeared before ownership could be switched.'
        }
        $categories = @(Get-FFBBlasterFieldNames -GameProfilesDir (Join-Path $TpRoot 'GameProfiles'))
        if ($categories.Count -eq 0) {
            throw 'FFB Blaster fields could not be rediscovered before the ownership switch.'
        }
        $plans = New-Object System.Collections.Generic.List[object]
        $planStarted = Get-Date
        $planCurrent = 0
        $planCurrentDone = $false
        try {
            foreach ($profileFile in $targets) {
                $planCurrent++
                Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'FFB overlap profile preflight' -Current $planCurrent -Total $targets.Count -StartedAt $planStarted
            $doc = Read-Xml $profileFile.FullName
            $nodes = @(Get-FFBBlasterFieldValueNodes -Doc $doc -Categories $categories)
            if ($nodes.Count -eq 0) {
                throw ("Native FFB field disappeared from profile '{0}'." -f $profileFile.BaseName)
            }
            $enabledNodes = @($nodes | Where-Object { $_.InnerText -eq '1' })
            if ($enabledNodes.Count -eq 0) {
                throw ("Native FFB field is no longer enabled for profile '{0}'." -f $profileFile.BaseName)
            }
            [void]$plans.Add([pscustomobject]@{ ProfileFile = $profileFile; Document = $doc; Nodes = $nodes })
        }
        $planCurrentDone = $true
        } finally {
            Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'FFB overlap profile preflight' -Current $(if ($planCurrentDone) { $planCurrent } else { $planCurrent - 1 }) -Total $targets.Count -StartedAt $planStarted -Complete -Outcome $(if ($planCurrentDone) { 'Final' } else { 'Error' })
        }
        if ($plans.Count -eq 0) {
            return [pscustomobject]@{ Succeeded = $true; Disabled = 0; BackupPath = $null; Reason = $null }
        }

        $backupRoot = Join-Path $UserProfilesDir 'FullBackup'
        if ((Test-Path -LiteralPath $backupRoot -ErrorAction SilentlyContinue) -and
            (-not (Test-TpmNoReparsePath -Path $backupRoot))) {
            throw "FFB overlap backup path is unsafe: $backupRoot"
        }
        [void][System.IO.Directory]::CreateDirectory($backupRoot)
        # Built under an INCOMPLETE_ name and published as a restore choice only after the switch succeeded.
        $backupFinalPath = Join-Path $backupRoot ('FFBOverlapSwitch_{0}_{1}' -f (Get-Date).ToUniversalTime().ToString('yyyy-MM-dd_HH-mm-ss_fff', [System.Globalization.CultureInfo]::InvariantCulture), [guid]::NewGuid().ToString('N'))
        $backupPath = Get-TpmUserProfilesBackupStagingPath -FinalPath $backupFinalPath
        [void][System.IO.Directory]::CreateDirectory($backupPath)
        if (-not (Test-TpmNoReparsePath -Path $backupPath)) {
            throw "FFB overlap backup path is unsafe: $backupPath"
        }
        $snapshotItems = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $UserProfilesDir -ProgressLabel 'FFB overlap safety snapshot discovery' -Filter '*' -EnumerationErrorAction Stop -IncludeDirectories -Force | Where-Object { $_.Name -ne 'FullBackup' })
        $snapshotStarted = Get-Date
        $snapshotCurrent = 0
        $snapshotCurrentDone = $false
        try {
            foreach ($snapshotItem in $snapshotItems) {
                $snapshotCurrent++
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'FFB overlap safety snapshot' -Current $snapshotCurrent -Total $snapshotItems.Count -StartedAt $snapshotStarted
                $snapshotItem | Copy-Item -Destination $backupPath -Recurse -Force -ErrorAction Stop
            }
            $snapshotCurrentDone = $true
        } finally {
            if ($snapshotItems.Count -gt 0) {
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'FFB overlap safety snapshot' -Current $(if ($snapshotCurrentDone) { $snapshotCurrent } else { $snapshotCurrent - 1 }) -Total $snapshotItems.Count -StartedAt $snapshotStarted -Complete -Outcome $(if ($snapshotCurrentDone) { 'Final' } else { 'Error' })
            }
        }
        $verifyStarted = Get-Date
        $verifyCurrent = 0
        $verifyCurrentDone = $false
        try {
            foreach ($plan in $plans) {
                $verifyCurrent++
                Write-TpmCompactExtractionProgress -Phase Checking -Label 'FFB overlap backup verification' -Current $verifyCurrent -Total $plans.Count -StartedAt $verifyStarted
                $backupFile = Join-Path $backupPath $plan.ProfileFile.Name
                if (-not (Test-Path -LiteralPath $backupFile -PathType Leaf -ErrorAction Stop)) {
                    throw ("FFB overlap backup is missing profile '{0}'." -f $plan.ProfileFile.Name)
                }
                $sourceHash = (Get-FileHash -LiteralPath $plan.ProfileFile.FullName -Algorithm SHA256 -ErrorAction Stop).Hash
                $backupHash = (Get-FileHash -LiteralPath $backupFile -Algorithm SHA256 -ErrorAction Stop).Hash
                if ($sourceHash -ne $backupHash) {
                    throw ("FFB overlap backup hash verification failed for profile '{0}'." -f $plan.ProfileFile.Name)
                }
            }
            $verifyCurrentDone = $true
        } finally {
            if ($plans.Count -gt 0) {
                Write-TpmCompactExtractionProgress -Phase Checking -Label 'FFB overlap backup verification' -Current $(if ($verifyCurrentDone) { $verifyCurrent } else { $verifyCurrent - 1 }) -Total $plans.Count -StartedAt $verifyStarted -Complete -Outcome $(if ($verifyCurrentDone) { 'Final' } else { 'Error' })
            }
        }
        $backupVerified = $true

        $switchStarted = Get-Date
        $switchCurrent = 0
        $switchCurrentDone = $false
        try {
            foreach ($plan in $plans) {
                $switchCurrent++
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'FFB overlap native switch' -Current $switchCurrent -Total $plans.Count -StartedAt $switchStarted
                foreach ($node in $plan.Nodes) { $node.InnerText = '0' }
                Save-Xml $plan.Document $plan.ProfileFile.FullName
                $verifyDoc = Read-Xml $plan.ProfileFile.FullName
                $remaining = @(Get-FFBBlasterFieldValueNodes -Doc $verifyDoc -Categories $categories | Where-Object { $_.InnerText -eq '1' })
                if ($remaining.Count -gt 0) {
                    throw ("Native FFB remained enabled for profile '{0}' after the ownership switch." -f $plan.ProfileFile.BaseName)
                }
            }
            $switchCurrentDone = $true
        } finally {
            if ($plans.Count -gt 0) {
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'FFB overlap native switch' -Current $(if ($switchCurrentDone) { $switchCurrent } else { $switchCurrent - 1 }) -Total $plans.Count -StartedAt $switchStarted -Complete -Outcome $(if ($switchCurrentDone) { 'Final' } else { 'Error' })
            }
        }
        try {
            $backupPath = Complete-TpmUserProfilesBackupFolder -StagingPath $backupPath -FinalPath $backupFinalPath -Producer 'FFBOverlapSwitch'
        } catch {
            # The switch itself succeeded and was verified; only publishing its safety snapshot as a restore choice failed.
            Write-Host ("  WARNING: The FFB safety snapshot could not be marked complete; it is kept (not offered for restore) at {0}" -f $backupPath) -ForegroundColor Yellow
            Write-Log "FFB overlap backup completion failed; snapshot kept at $backupPath -- $($_.Exception.Message)"
        }
        return [pscustomobject]@{ Succeeded = $true; Disabled = $plans.Count; BackupPath = $backupPath; Reason = $null }
    } catch {
        $message = $_.Exception.Message
        $rollbackState = 'NoBackup'
        $rollbackError = $null
        $backupHasEntries = $false
        if ($backupPath -and (Test-Path -LiteralPath $backupPath -PathType Container -ErrorAction SilentlyContinue)) {
            $backupHasEntries = [bool](Get-ChildItem -LiteralPath $backupPath -Force -ErrorAction SilentlyContinue | Select-Object -First 1)
            if (-not $backupHasEntries) {
                # Nothing was snapshotted, so nothing can have been switched: remove the empty dir and report no rollback needed.
                Remove-Item -LiteralPath $backupPath -Force -ErrorAction SilentlyContinue
                Write-Log "FFB overlap snapshot failed before any copy; removed empty backup dir: $backupPath"
            }
        }
        if ($backupHasEntries -and -not $backupVerified) {
            # The failure came before the snapshot of the profiles being switched was verified, so no profile was changed and
            # nothing is copied back: a half-copied snapshot must never replace a good live profile.
            $rollbackState = 'NotNeeded'
            Write-Log "FFB overlap snapshot was not verified; no profile was changed, so nothing was rolled back: $message"
        } elseif ($backupHasEntries) {
            $rollbackState = 'RollbackFailed'
            try {
                # Only the switched profiles are put back, and only from copies that were hash-verified before the switch.
                foreach ($plan in $plans) {
                    $backupFile = Join-Path $backupPath $plan.ProfileFile.Name
                    Copy-Item -LiteralPath $backupFile -Destination $plan.ProfileFile.FullName -Force -ErrorAction Stop
                    if ((Get-FileHash -LiteralPath $plan.ProfileFile.FullName -Algorithm SHA256 -ErrorAction Stop).Hash -ne (Get-FileHash -LiteralPath $backupFile -Algorithm SHA256 -ErrorAction Stop).Hash) {
                        throw ("Profile '{0}' did not match its safety copy after it was put back." -f $plan.ProfileFile.Name)
                    }
                }
                $rollbackState = 'RolledBack'
                Write-Log "FFB overlap switch rolled back after failure: $message"
            } catch {
                $rollbackError = [string]$_.Exception.Message
                Write-Host ("  FFB overlap ROLLBACK FAILED: native FFB may still be switched. Backup kept at {0}" -f $backupPath) -ForegroundColor Red
                Write-Log "FFB overlap rollback failed after '$message': $rollbackError"
            }
        }
        $reason = if ($rollbackState -eq 'RollbackFailed') { "ROLLBACK_FAILED: $message; rollback error: $rollbackError" } else { $message }
        return [pscustomobject]@{ Succeeded = $false; Disabled = 0; BackupPath = $backupPath; Reason = $reason; RollbackState = $rollbackState; RollbackError = $rollbackError }
    }
}

# Sets up TeknoParrot's own built-in "FFB Blaster" force feedback, a
# per-game Bool field in GameProfiles -- paywalled (any paid TeknoParrot
# membership). The script cannot check subscription status, so it must
# ask before touching anything: enabling the field has no effect at all
# without a membership, so there is no point doing it on spec.
# Returns the list of profile codes successfully enabled or already
# enabled, so the third-party plugin setup can ask the user whether to
# keep native or switch to the plugin for any game covered by both.
function Invoke-FFBBlasterSetup {
    param([string]$UserProfilesDir, [string]$TpRoot)

    Write-Host ""
    Write-TpmText -Text 'Do you have a paid TeknoParrot membership?' -Color Yellow
    Write-TpmText -Text 'FFB Blaster needs one. Join at teknoparrot.com/en/Home/Subscription' -Color DarkGray
    Write-Host "  [Y] Yes -- turn on FFB Blaster" -ForegroundColor White
    Write-Host "  [N] No -- skip FFB Blaster" -ForegroundColor White
    $hasSub = Read-TpmYesNo -Prompt "  Choose Y or N" -Default 'N'
    if ($hasSub -ne "Y") {
        Write-Host "  Skipped -- no membership." -ForegroundColor DarkGray
        Write-Log "FFBBlaster setup: skipped -- user has no TeknoParrot membership."
        return (New-TpmProfileTransactionResult -WorkflowKey 'FFBSetup' -OperationKey 'FFBBlaster' -Outcome 'NO_OP' -ProductState 'UNCHANGED' -Summary 'FFB Blaster setup skipped.' -ReasonCode 'NO_MEMBERSHIP' -FinalChecks @('The user declined membership-gated FFB Blaster setup before any profile mutation or backup work.'))
    }

    Write-Host "  Scanning GameProfiles for FFB Blaster fields..." -ForegroundColor DarkGray
    $gpDir = Join-Path $TpRoot "GameProfiles"
    $ffbFields = Get-FFBBlasterFieldNames -GameProfilesDir $gpDir
    $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'FFB Blaster profile discovery' -EnumerationErrorAction SilentlyContinue | Sort-Object BaseName)
    $supportedCodes = New-Object System.Collections.Generic.List[string]
    $plans = New-Object System.Collections.Generic.List[object]
    $unknownNames = New-Object System.Collections.Generic.List[string]
    $unsupported = 0; $unknown = 0
    $profileScanStarted = Get-Date
    $profileScanCurrent = 0
    foreach ($pf in $profiles) {
        $profileScanCurrent++
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'FFB profiles' -Current $profileScanCurrent -Total $profiles.Count -StartedAt $profileScanStarted
        try {
            $doc = Read-Xml $pf.FullName
            $support = Get-FFBBlasterSupport -Doc $doc -Categories $ffbFields
            if ($support.Status -eq 'Unsupported') { $unsupported++; continue }
            if ($support.Status -eq 'Unknown') { $unknown++; [void]$unknownNames.Add($pf.BaseName); continue }
            [void]$supportedCodes.Add($pf.BaseName)
            if ($support.WouldWrite) {
                [void]$plans.Add([pscustomobject]@{ ProfileId=$pf.BaseName; ProfileFile=$pf; SourceHash=(Get-FileHash -LiteralPath $pf.FullName -Algorithm SHA256 -ErrorAction Stop).Hash })
            }
        } catch {
            $unknown++; [void]$unknownNames.Add($pf.BaseName)
            Write-Log "FFBBlaster: planning failed for $($pf.BaseName) -- $_"
        }
    }
    Write-TpmCompactExtractionProgress -Phase Checking -Label 'FFB profiles' -Current $profileScanCurrent -Total $profiles.Count -StartedAt $profileScanStarted -Complete
    if ($plans.Count -eq 0) {
        $outcome = if ($unknown -gt 0) { 'ACTION_REQUIRED' } else { 'NO_OP' }
        $state = if ($unknown -gt 0) { 'UNKNOWN' } else { 'UNCHANGED' }
        $summary = if ($unknown -gt 0) { 'Some FFB Blaster profiles need review before setup can continue.' } elseif ($supportedCodes.Count -eq 0) { 'No FFB Blaster profiles need this setting.' } else { 'All eligible FFB Blaster profiles are already current.' }
        if ($unknown -gt 0) {
            $unknownList = (@($unknownNames | Select-Object -First 10) -join ', ')
            if ($unknownNames.Count -gt 10) { $unknownList += ', ...' }
            Write-Host ("  Unknown  : {0} profile(s) need manual review and were left unchanged: {1}" -f $unknown, $unknownList) -ForegroundColor Yellow
        }
        else { Write-Host "  No FFB Blaster profile changes are needed. Nothing was changed." -ForegroundColor DarkGray }
        Write-Log ("FFBBlaster setup: {0}. Supported={1} Unsupported={2} Unknown={3}" -f $outcome,$supportedCodes.Count,$unsupported,$unknown)
        return (New-TpmProfileTransactionResult -WorkflowKey 'FFBSetup' -OperationKey 'FFBBlaster' -Outcome $outcome -ProductState $state -Summary $summary -Items $supportedCodes.ToArray() -ReasonCode $(if($unknown -gt 0){'FFB_PROFILE_REVIEW_REQUIRED'}else{'NO_ELIGIBLE_CHANGES'}) -FinalPassed ($unknown -eq 0) -FinalChecks @('All candidate profiles were scanned before mutation.'))
    }

    $backup = New-TpmVerifiedUserProfilesBackup -UserProfilesDir $UserProfilesDir -Label 'FFBBlaster'
    if (-not $backup.Verified) {
        Write-Host "  FFB Blaster setup stopped before changing your profiles." -ForegroundColor Red
        Write-Host "  TeknoParrot Manager could not verify the safety backup." -ForegroundColor Red
        Write-Host "  Nothing was changed." -ForegroundColor Green
        Write-Log ("FFBBlaster: verified backup gate failed at {0} -- {1}" -f $backup.FailureStage,$backup.Reason)
        return (New-TpmProfileTransactionResult -WorkflowKey 'FFBSetup' -OperationKey 'FFBBlaster' -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' -Summary 'FFB Blaster setup stopped before changing your profiles because the safety backup could not be verified.' -Items @() -Backup $backup -ReasonCode 'PROFILE_BACKUP_FAILED' -FinalChecks @('No XML write was attempted.'))
    }

    $revalidateStarted = Get-Date
    $revalidateCurrent = 0
    $revalidateCurrentDone = $false
    try {
        foreach ($plan in $plans) {
            $revalidateCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'FFB profile revalidation' -Current $revalidateCurrent -Total $plans.Count -StartedAt $revalidateStarted
            if ((Get-FileHash -LiteralPath $plan.ProfileFile.FullName -Algorithm SHA256 -ErrorAction Stop).Hash -ine [string]$plan.SourceHash) {
                Write-Log "FFBBlaster: source profile changed before first write: $($plan.ProfileId)"
                return (New-TpmProfileTransactionResult -WorkflowKey 'FFBSetup' -OperationKey 'FFBBlaster' -Outcome 'ACTION_REQUIRED' -ProductState 'UNKNOWN' -Summary 'FFB Blaster setup needs attention because a profile changed before it could be updated.' -Items @($plans | ForEach-Object ProfileId) -Backup $backup -MutationStarted $false -FinalPassed $false -ReasonCode 'PROFILE_CHANGED_BEFORE_WRITE' -FinalChecks @('Source profile revalidation failed before the first XML write.'))
            }
            $current = Read-Xml $plan.ProfileFile.FullName
            $currentSupport = Get-FFBBlasterSupport -Doc $current -Categories $ffbFields
            if ($currentSupport.Status -ne 'Supported' -or -not $currentSupport.WouldWrite) {
                return (New-TpmProfileTransactionResult -WorkflowKey 'FFBSetup' -OperationKey 'FFBBlaster' -Outcome 'ACTION_REQUIRED' -ProductState 'UNKNOWN' -Summary 'FFB Blaster setup needs attention because a profile changed before it could be updated.' -Items @($plans | ForEach-Object ProfileId) -Backup $backup -MutationStarted $false -FinalPassed $false -ReasonCode 'PROFILE_PLAN_CHANGED' -FinalChecks @('Source profile revalidation failed before the first XML write.'))
            }
        }
        $revalidateCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'FFB profile revalidation' -Current $(if ($revalidateCurrentDone) { $revalidateCurrent } else { $revalidateCurrent - 1 }) -Total $plans.Count -StartedAt $revalidateStarted -Complete -Outcome $(if ($revalidateCurrentDone) { 'Final' } else { 'Error' })
    }

    $completed = New-Object System.Collections.Generic.List[string]
    $saveErrors = New-Object System.Collections.Generic.List[string]
    $mutationStarted = Get-Date
    $mutationCurrent = 0
    $mutationCurrentDone = $false
    try {
        foreach ($plan in $plans) {
            $mutationCurrent++
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'FFB profile updates' -Current $mutationCurrent -Total $plans.Count -StartedAt $mutationStarted
            try {
                $doc = Read-Xml $plan.ProfileFile.FullName
                $support = Get-FFBBlasterSupport -Doc $doc -Categories $ffbFields
                foreach ($change in $support.Changes) { $change.Node.InnerText = $change.NewValue }
                Save-Xml $doc $plan.ProfileFile.FullName
                $verify = Get-FFBBlasterSupport -Doc (Read-Xml $plan.ProfileFile.FullName) -Categories $ffbFields
                if ($verify.WouldWrite) { throw 'FFB Blaster read-back verification failed.' }
                [void]$completed.Add($plan.ProfileId)
                Write-Log ("FFBBlaster: updated {0}" -f $plan.ProfileId)
            } catch {
                [void]$saveErrors.Add($plan.ProfileId)
                Write-Host ("    FAILED {0}: profile was not verified" -f $plan.ProfileId) -ForegroundColor Red
                Write-Log "FFBBlaster: FAILED $($plan.ProfileId) -- $_"
            }
        }
        $mutationCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Repairing -Label 'FFB profile updates' -Current $(if ($mutationCurrentDone) { $mutationCurrent } else { $mutationCurrent - 1 }) -Total $plans.Count -StartedAt $mutationStarted -Complete -Outcome $(if ($mutationCurrentDone -and $saveErrors.Count -eq 0) { 'Final' } else { 'Error' })
    }
    $failed = New-Object System.Collections.Generic.List[string]
    $unknownFinal = New-Object System.Collections.Generic.List[string]
    $verificationStarted = Get-Date
    $verificationCurrent = 0
    $verificationCurrentDone = $false
    try {
        foreach ($plan in $plans) {
            $verificationCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'FFB final verification' -Current $verificationCurrent -Total $plans.Count -StartedAt $verificationStarted
            try {
                $verify = Get-FFBBlasterSupport -Doc (Read-Xml $plan.ProfileFile.FullName) -Categories $ffbFields
                if ($verify.WouldWrite) { [void]$failed.Add($plan.ProfileId) }
                elseif ($completed -notcontains $plan.ProfileId) { [void]$completed.Add($plan.ProfileId) }
            } catch { [void]$unknownFinal.Add($plan.ProfileId) }
        }
        $verificationCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'FFB final verification' -Current $(if ($verificationCurrentDone) { $verificationCurrent } else { $verificationCurrent - 1 }) -Total $plans.Count -StartedAt $verificationStarted -Complete -Outcome $(if ($verificationCurrentDone -and $failed.Count -eq 0 -and $unknownFinal.Count -eq 0) { 'Final' } else { 'Error' })
    }
    $allIds=@($plans | ForEach-Object ProfileId)
    if ($unknownFinal.Count -gt 0) {
        $outcome='ACTION_REQUIRED'; $state='UNKNOWN'; $summary='FFB Blaster setup needs attention because the final profile state could not be verified.'; $passed=$false; $reason='PROFILE_FINAL_STATE_UNKNOWN'
    } elseif ($failed.Count -gt 0) {
        $outcome='PARTIAL_APPLIED'; $state='PARTIAL_KNOWN'; $summary='Some FFB Blaster profiles were updated, but the operation did not finish.'; $passed=$true; $reason='PROFILE_SAVE_PARTIAL'
    } else {
        $outcome='SUCCEEDED'; $state='INTENDED'; $summary='FFB Blaster profiles were updated and verified.'; $passed=$true; $reason='PROFILE_UPDATES_VERIFIED'
    }
    Write-Log ("FFBBlaster: updated {0} profile(s); {1} could not be updated." -f $completed.Count, $failed.Count)
    if ($failed.Count -gt 0) { Write-Host ("  {0} updated, but {1} could not be updated. The log lists them." -f (Format-TpmGameCount -Count $completed.Count), (Format-TpmGameCount -Count $failed.Count)) -ForegroundColor Red }
    return (New-TpmProfileTransactionResult -WorkflowKey 'FFBSetup' -OperationKey 'FFBBlaster' -Outcome $outcome -ProductState $state -Summary $summary -Items $supportedCodes.ToArray() -ChangedItems $allIds -CompletedItems $completed.ToArray() -FailedItems $failed.ToArray() -UnknownItems $unknownFinal.ToArray() -MutationStarted $true -Backup $backup -FinalPassed $passed -ReasonCode $reason -FinalChecks @('Every intended profile was read back after its write.'))
}

# FIX82: the Force feedback screens (menu 8). The intro is four short lines; the membership question (in Invoke-FFBBlasterSetup) is the
# only place that names the subscription page. The result of the native step is one line; the games it changed (by their internal
# names) and the safety copy folder are in the Details view (key D) and the log.
function Write-TpmFfbIntro {
    Write-Host ''
    Write-TpmText -Text 'Force feedback makes a wheel or stick push back and rumble, like in the game.' -Color Cyan
    Write-TpmText -Text 'There are two ways to get it. You can use one or both.' -Color Cyan
    Write-TpmText -Text '1) FFB Blaster is built into TeknoParrot. It needs a paid membership.' -Color Cyan -HangingIndent 3
    Write-TpmText -Text '2) The FFB plugin is a free add-on for other games. It needs no membership.' -Color Cyan -HangingIndent 3
}

function Get-TpmFfbNativeResultView {
    param([Parameter(Mandatory)]$Result)
    $done = @(Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'Mutation') -Name 'CompletedItems' -Default @() | Where-Object { $_ })
    $folder = [string](Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'Backup') -Name 'RootPath' -Default '')
    $title = 'FFB Blaster setup is finished.'
    if ($done.Count -gt 0) { $title = ('FFB Blaster is now on for {0}.' -f (Format-TpmGameCount -Count $done.Count)) }
    $blocks = New-Object System.Collections.Generic.List[object]
    if ($done.Count -gt 0) { [void]$blocks.Add(@{ Heading = ('Games where FFB Blaster was turned on ({0})' -f $done.Count); Lines = @($done -join ', ') }) }
    if (-not [string]::IsNullOrWhiteSpace($folder)) { [void]$blocks.Add(@{ Heading = 'Safety copy of your game settings'; Lines = @('Folder: ' + $folder) }) }
    return @{ Title = $title; Status = 'Ok'; Next = 'You can add the free FFB plugin for more games.'; DetailBlocks = $blocks.ToArray() }
}

function Show-TpmFfbNativeResult {
    param([Parameter(Mandatory)]$Result, [switch]$Unattended)
    $view = Get-TpmFfbNativeResultView -Result $Result
    Write-TpmOutcome @view -Unattended:$Unattended
}

# =============================================================================
# BEPINEX UPDATE CHECKER  (Unity modding/plugin framework some games need)
# =============================================================================
# BepInEx is a third-party Unity plugin/modding framework. Several
# TeknoParrot games require a community BepInEx plugin to get controls or
# fixes working (the live-fetched example list is shown in the menu --
# see Get-BepInExRequiredGames below). Mode 9 offers a user-approved install,
# update, or reset using stable x64 or x86 packages; it never applies the
# framework silently to every game.

# Fetches the live list of games known to require BepInEx, for display
# only (menu text, not used to gate actual logic -- the setup flow can offer
# install/update/reset for selected games after safety checks).
# Source: eggmansworld.github.io/TeknoParrot, the structured replacement
# for the old plain-text gamenotes doc, already used for the v0.88-v0.90
# compatibility tables. That site has no clean "requires BepInEx" tag, so
# this matches a tight phrase pattern against the free-text notes field
# instead -- verified against the live data to reproduce the same games
# this script used to hardcode here, so it tracks new additions without
# becoming stale. Returns an empty array (never a hardcoded fallback list)
# if the fetch fails -- the caller falls back to generic wording.
function Get-BepInExRequiredGames {
    $games = Get-EggmanGameData
    if (-not $games) { return ,@() }
    $pattern = '(?i)requires?\s+(the\s+)?(latest\s+)?BepInEx|must\s+use\s+(the\s+)?(latest\s+)?BepInEx'
    return @($games | Where-Object { $_.notes -and $_.notes -match $pattern } |
              Select-Object -ExpandProperty game_name)
}

# Shared fetch+parse for the eggmansworld.github.io structured compatibility
# data (the <script type="application/json" id="game-data"> block). Returns
# the full deserialized array, or $null if the fetch/parse fails. Both
# Get-BepInExRequiredGames and Get-GameSetupNotes hit the same endpoint --
# centralizing the fetch-with-retry + regex-extract logic here means there's
# only one copy that can drift out of sync with the page's actual markup.
function Get-EggmanGameData {
    param([string]$CacheRoot = '')
    $cachePath = Get-TpmEggmanGameDataCachePath -RootPath $CacheRoot
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            $resp = Invoke-TpmWebRequestSilently -Uri 'https://eggmansworld.github.io/TeknoParrot/' `
                        -UseBasicParsing -TimeoutSec 20 -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $m = [regex]::Match($resp.Content, '(?s)<script type="application/json" id="game-data">(.*?)</script>')
            if (-not $m.Success) { return (Get-TpmEggmanGameDataFallback -CachePath $cachePath -Reason 'the page no longer has the game list') }
            $games = @($m.Groups[1].Value | ConvertFrom-Json)
            Save-TpmEggmanGameDataCache -CachePath $cachePath -Json $m.Groups[1].Value
            return $games
        } catch {
            $status = 0
            # Get-TpmHttpStatusCodeFromError guards the same optional
            # .Exception.Response/.StatusCode access this used to do inline
            # (unsafe under strict mode for exception types that lack either
            # property entirely -- RuntimeException from a plain "throw",
            # HttpRequestException, etc.) and additionally falls back to
            # extracting a status code embedded only in the message text.
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "EggmanGameData: fetch failed -- $_"
                return (Get-TpmEggmanGameDataFallback -CachePath $cachePath -Reason 'the page could not be reached')
            }
            Start-Sleep -Seconds 5
        }
    }
    return (Get-TpmEggmanGameDataFallback -CachePath $cachePath -Reason 'the page could not be reached')
}

# FIX132: where the Game Notes list is saved between runs (TPM's own per-user data folder, next to the DAT copy).
function Get-TpmEggmanGameDataCachePath {
    param([string]$RootPath = '')
    $root = if ([string]::IsNullOrWhiteSpace($RootPath)) { Get-EggmanDatDataRoot } else { $RootPath }
    if ([string]::IsNullOrWhiteSpace($root)) { return '' }
    return (Join-Path $root 'game-data.json')
}

# Saves the page's game list after a good fetch. A failed save is only logged.
function Save-TpmEggmanGameDataCache {
    param([string]$CachePath, [string]$Json)
    if ([string]::IsNullOrWhiteSpace($CachePath) -or [string]::IsNullOrWhiteSpace($Json)) { return }
    $temp = $CachePath + '.tmp'
    try {
        [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($CachePath))
        [System.IO.File]::WriteAllText($temp, $Json, (New-Object System.Text.UTF8Encoding($false)))
        Move-Item -LiteralPath $temp -Destination $CachePath -Force -ErrorAction Stop
    } catch {
        Write-Log "EggmanGameData: could not save the cache copy -- $_"
        try { if (Test-Path -LiteralPath $temp) { Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue } } catch { }
    }
}

# When the Game Notes page cannot be used: the copy saved by an earlier good fetch, or $null.
# Tells the player once per run, in plain words, which of the two happened.
function Get-TpmEggmanGameDataFallback {
    param([string]$CachePath, [string]$Reason)
    $games = $null
    if (-not [string]::IsNullOrWhiteSpace($CachePath) -and (Test-Path -LiteralPath $CachePath -PathType Leaf)) {
        try {
            # The pipeline unrolls the array that Windows PowerShell 5.1 returns as one object.
            $parsed = @(@([System.IO.File]::ReadAllText($CachePath) | ConvertFrom-Json) | ForEach-Object { $_ })
            if ($parsed.Count -gt 0 -and $null -ne $parsed[0].PSObject.Properties['profile_name']) { $games = $parsed }
        } catch {
            Write-Log "EggmanGameData: the saved copy could not be read -- $_"
        }
    }
    $announced = Get-Variable -Name 'TpmGameNotesFallbackAnnounced' -Scope Script -ErrorAction SilentlyContinue
    if ($null -eq $announced -or -not $announced.Value) {
        Set-Variable -Name 'TpmGameNotesFallbackAnnounced' -Scope Script -Value $true
        if ($null -ne $games) {
            Write-Host '  The Game Notes page could not be used, so TeknoParrot Manager is using the copy it saved earlier.' -ForegroundColor Yellow
        } else {
            Write-Host '  The Game Notes page could not be used and there is no saved copy, so game notes are skipped this time.' -ForegroundColor Yellow
        }
    }
    Write-Log ("EggmanGameData: {0}; {1}." -f $Reason, $(if ($null -ne $games) { 'using the saved copy' } else { 'no saved copy' }))
    return $games
}

# Fetches the latest STABLE x64 BepInEx release info, fetch-with-retry
# shape identical to Get-EggmanDatRelease/Get-FFBPluginGameMap.
# Returns [pscustomobject]@{ Version; DownloadUrl; FileName } or $null.
function Get-BepInExLatestRelease {
    param([ValidateSet('x64','x86')][string]$Architecture = 'x64')
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            $apiUri = 'https://api.github.com/repos/BepInEx/BepInEx/releases'
            $resp   = Invoke-TpmWebRequestSilently -Uri $apiUri -UseBasicParsing -TimeoutSec 20 `
                          -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $releases = $resp.Content | ConvertFrom-Json
            # Releases are returned newest-first; prerelease=false reliably
            # distinguishes the v5-lts stable line from v6-bleeding-edge
            # pre-releases -- no tag-name parsing needed.
            $stable = @($releases | Where-Object { -not $_.prerelease }) | Select-Object -First 1
            if (-not $stable) { return $null }
            $asset = @($stable.assets | Where-Object { $_.name -like ('BepInEx_win_{0}_*.zip' -f $Architecture) }) | Select-Object -First 1
            if (-not $asset) { return $null }
            $parsedUri = $null
            $urlOk = [System.Uri]::TryCreate($asset.browser_download_url, [System.UriKind]::Absolute, [ref]$parsedUri) -and
                     $parsedUri.Scheme -eq 'https' -and
                     $parsedUri.Host -eq 'github.com' -and
                     [string]::IsNullOrEmpty($parsedUri.UserInfo) -and
                     $parsedUri.AbsolutePath.StartsWith('/BepInEx/BepInEx/releases/download/', [System.StringComparison]::Ordinal)
            if (-not $urlOk) {
                Write-Log "BepInEx: unexpected download URL format -- skipping."
                return $null
            }
            $verStr = $stable.tag_name.TrimStart('v')
            # The GitHub Releases API serves a machine-readable "digest"
            # field (sha256:<64-hex>) computed by GitHub itself from the
            # uploaded bytes, over the same allowlisted api.github.com host
            # already used to discover this download URL -- confirmed
            # present on real release assets during design. Extracted here
            # so every caller can opt into SHA-256 verification via
            # Invoke-TpmDownload -ExpectedSha256 instead of trusting size
            # alone; $null (not present/not sha256) means the caller falls
            # back to size-only validation, same as before this field existed.
            $expectedSha256 = Get-TpmSha256FromDigestField -Digest $asset.digest
            return [pscustomobject]@{
                Version = $verStr; Architecture = $Architecture; DownloadUrl = $asset.browser_download_url; FileName = $asset.name; SizeBytes = [int64]$asset.size; ExpectedSha256 = $expectedSha256
            }
        } catch {
            $status = 0
            # Get-TpmHttpStatusCodeFromError guards the same optional
            # .Exception.Response/.StatusCode access this used to do inline
            # (unsafe under strict mode for exception types that lack either
            # property entirely -- RuntimeException from a plain "throw",
            # HttpRequestException, etc.) and additionally falls back to
            # extracting a status code embedded only in the message text.
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "BepInEx: release query failed -- $_"; return $null
            }
            Write-Log "BepInEx: attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    return $null
}

# Fetches the latest dgVoodoo2 release from its official GitHub Releases
# channel (github.com/dege-diosg/dgVoodoo2). Mirrors Get-BepInExLatestRelease
# almost exactly: same URL-allowlist validation (scheme=https, host exactly
# github.com/api.github.com, no userinfo, path under the expected releases
# path), same 3-attempt retry/backoff/4xx-shortcircuit, same SHA-256 digest
# extraction. Selects the main (non-dev, non-debug) ZIP asset by name
# pattern -- dgVoodoo2 releases also ship dev/debug variant ZIPs that this
# script never wants. Returns [pscustomobject]@{ Version; DownloadUrl;
# FileName; SizeBytes; ExpectedSha256 } or $null.
function Get-DgVoodoo2LatestRelease {
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            $apiUri = 'https://api.github.com/repos/dege-diosg/dgVoodoo2/releases/latest'
            $resp   = Invoke-TpmWebRequestSilently -Uri $apiUri -UseBasicParsing -TimeoutSec 20 `
                          -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $release = $resp.Content | ConvertFrom-Json
            if (-not $release -or -not $release.assets) { return $null }
            # Main ZIP asset: named like "dgVoodoo2_87_3.zip" -- excludes any
            # asset name containing "dev" or "debug" (the dev/debug variant
            # ZIPs this project deliberately never fetches).
            $mainAsset = @($release.assets | Where-Object {
                $_.name -match '(?i)^dgVoodoo2[_0-9.]*\.zip$' -and $_.name -notmatch '(?i)dev|debug'
            }) | Select-Object -First 1
            if (-not $mainAsset) { return $null }
            $parsedUri = $null
            $urlOk = [System.Uri]::TryCreate($mainAsset.browser_download_url, [System.UriKind]::Absolute, [ref]$parsedUri) -and
                     $parsedUri.Scheme -eq 'https' -and
                     $parsedUri.Host -eq 'github.com' -and
                     [string]::IsNullOrEmpty($parsedUri.UserInfo) -and
                     $parsedUri.AbsolutePath.StartsWith('/dege-diosg/dgVoodoo2/releases/download/', [System.StringComparison]::Ordinal)
            if (-not $urlOk) {
                Write-Log "dgVoodoo2: unexpected download URL format -- skipping."
                return $null
            }
            $verStr = $release.tag_name.TrimStart('v')
            # GitHub may omit the optional digest property on an otherwise
            # valid release asset. Read it by property presence so strict
            # mode does not turn that compatibility case into a failed query.
            $digest = if ($mainAsset.PSObject.Properties.Name -contains 'digest') {
                $mainAsset.digest
            } else {
                $null
            }
            $expectedSha256 = Get-TpmSha256FromDigestField -Digest $digest
            return [pscustomobject]@{
                Version = $verStr; DownloadUrl = $mainAsset.browser_download_url; FileName = $mainAsset.name; SizeBytes = [int64]$mainAsset.size; ExpectedSha256 = $expectedSha256
            }
        } catch {
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "dgVoodoo2: release query failed -- $_"; return $null
            }
            Write-Log "dgVoodoo2: attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    return $null
}

# Extracts only the 6 known dgVoodoo2 files from a downloaded release ZIP
# into $DestDir, narrowly scoped rather than a generic "extract everything"
# -- a changed ZIP layout in a future dgVoodoo2 release is a "stop and tell
# the user" event, not a best-effort partial extraction. Each entry name is
# sanitized via [System.IO.Path]::GetFileName() and containment-checked via
# Test-PathInside before writing, same protection class SECURITY.md already
# mandates for BepInEx/FFBPlugin. Fails closed if any of the 6 expected
# entries is missing at its expected subpath within the ZIP.
#
# Transactional (P1 #1 remediation): all 6 files are extracted into an
# isolated staging directory (New-TpmStagingDirectory) and fully validated
# there first; $DestDir is never touched until the complete, valid set of 6
# exists in staging. Promotion into $DestDir goes through
# Invoke-TpmTransactionalPromote, which is itself rollback-safe -- if
# promoting any one of the 6 files fails partway through and rollback
# completes, $DestDir is restored to exactly its pre-call state (any of the
# other 5 already promoted in this same call are removed again, and any
# pre-existing files that were moved aside to make room are restored).
# On a recoverable failure (missing ZIP entry, an extraction-time error on
# any single entry, or a promotion-time error whose rollback completes),
# $DestDir ends up byte-for-byte unchanged from before this function was
# called. If an underlying filesystem mutation loses the original source
# before a valid backup is observable, exact restoration is impossible; the
# transaction instead reports an explicit ROLLBACK FAILED / INCONSISTENT
# condition and preserves recovery evidence. The staging directory is
# removed on ordinary success/failure when cleanup succeeds; it is
# preserved when transaction recovery, transaction cleanup, or ordinary
# staging cleanup fails so
# recovery evidence/residue remains available.
function Expand-DgVoodoo2Zip {
    param([string]$ZipPath, [string]$DestDir)

    # Expected subpath (inside the ZIP) -> destination file name. Verified
    # live against the real dgVoodoo2_87_3.zip release layout during this
    # feature's implementation: D3D8/DDraw/D3DImm all live under MS\x86\,
    # Glide2x/Glide3x both live under 3Dfx\x86\, and dgVoodoo.conf sits at
    # the ZIP root -- matching this script's own existing manual-install
    # instructions ("From the MS\x86\ subfolder", "From the 3Dfx\x86\
    # subfolder", "From the root of the ZIP").
    $expectedEntries = [ordered]@{
        'MS\x86\D3D8.dll'      = 'D3D8.dll'
        'MS\x86\DDraw.dll'     = 'DDraw.dll'
        'MS\x86\D3DImm.dll'    = 'D3DImm.dll'
        '3Dfx\x86\Glide2x.dll' = 'Glide2x.dll'
        '3Dfx\x86\Glide3x.dll' = 'Glide3x.dll'
        'dgVoodoo.conf'        = 'dgVoodoo.conf'
    }

    $stagingDir = New-TpmStagingDirectory -Label 'dgVoodoo2'
    $rollbackFailurePreserved = $false
    $operationError = $null
    try {
        $archive = $null
        try {
            $archive = [System.IO.Compression.ZipFile]::OpenRead($ZipPath)
            # Build a lookup of normalized (backslash, no leading slash) ZIP
            # entry paths -> ZipArchiveEntry, so each expected subpath can be
            # matched exactly regardless of the ZIP's own separator style.
            $byPath = @{}
            $zipScanStarted = Get-Date
            $zipScanCurrent = 0
            $zipScanTotal = $archive.Entries.Count
            $zipScanCurrentDone = $false
            try {
                foreach ($entry in $archive.Entries) {
                    $zipScanCurrent++
                    Write-TpmCompactExtractionProgress -Phase 'Scanning' -Label 'dgVoodoo2 ZIP entry scan' -Current $zipScanCurrent -Total $zipScanTotal -StartedAt $zipScanStarted
                    $norm = $entry.FullName.Replace('/', '\').TrimStart('\')
                    $byPath[$norm] = $entry
                }
                $zipScanCurrentDone = $true
            } finally {
                Write-TpmCompactExtractionProgress -Phase 'Scanning' -Label 'dgVoodoo2 ZIP entry scan' -Current $(if ($zipScanCurrentDone) { $zipScanCurrent } else { $zipScanCurrent - 1 }) -Total $zipScanTotal -StartedAt $zipScanStarted -Complete -Outcome $(if ($zipScanCurrentDone) { 'Final' } else { 'Error' })
            }

            $missing = @($expectedEntries.Keys | Where-Object { -not $byPath.ContainsKey($_) })
            if ($missing.Count -gt 0) {
                throw "dgVoodoo2 release ZIP layout has changed -- missing expected file(s): $($missing -join ', ')"
            }

            # Phase 1: extract all 6 files into the STAGING directory only.
            # $DestDir is not touched at all in this phase.
            foreach ($subPath in $expectedEntries.Keys) {
                $destName = $expectedEntries[$subPath]
                # Sanitize: strip to a bare file name (defense in depth even
                # though $destName is a fixed literal above, not ZIP-derived)
                # and verify the resolved staging path stays inside
                # $stagingDir before ever opening a write handle.
                $safeName  = [System.IO.Path]::GetFileName($destName)
                $stagePath = Join-Path $stagingDir $safeName
                if ([string]::IsNullOrWhiteSpace($safeName) -or -not (Test-PathInside $stagePath $stagingDir)) {
                    throw "SECURITY: refused to stage dgVoodoo2 entry outside staging folder ($destName)."
                }
                Copy-TpmZipEntryToFile -Entry $byPath[$subPath] -DestPath $stagePath
            }
        } finally {
            if ($archive) { $archive.Dispose() }
        }

        # Final validation of the staged set before promotion: all 6 files
        # must actually exist in staging with non-zero length.
        $requiredNames = @($expectedEntries.Values)
        foreach ($name in $requiredNames) {
            $stagePath = Join-Path $stagingDir $name
            if (-not (Test-Path -LiteralPath $stagePath -PathType Leaf) -or (Get-Item -LiteralPath $stagePath).Length -le 0) {
                throw "dgVoodoo2: staged entry '$name' is missing or empty after extraction -- aborting before any destination change."
            }
        }

        # Only now, with a complete and valid staged set of 6, touch the
        # real destination -- rollback-safe promotion.
        [void](Invoke-TpmTransactionalPromote -StagingDir $stagingDir -DestDir $DestDir -FileNames $requiredNames)
    } catch {
        $operationError = $_
        # Same reasoning as Expand-ReShadeSelfExtractingArchive: if
        # Invoke-TpmTransactionalPromote reports a rollback or cleanup
        # failure, its backup copies under
        # $stagingDir\.tpm-rollback-backup are the remaining route to
        # manual recovery -- do not delete them here.
        if ($_.Exception.Message -match 'ROLLBACK FAILED|CLEANUP FAILED') {
            $rollbackFailurePreserved = $true
            Write-Log "Expand-DgVoodoo2Zip: staging directory '$stagingDir' preserved for manual recovery after a transaction recovery failure."
        }
        throw
    } finally {
        if (-not $rollbackFailurePreserved -and (Test-Path -LiteralPath $stagingDir)) {
            try {
                Remove-Item -LiteralPath $stagingDir -Recurse -Force -ErrorAction Stop
            } catch {
                $cleanupMessage = "TPM STAGING CLEANUP FAILED$(if (-not $operationError) { ' AFTER VERIFIED PROMOTION' }) for '$stagingDir' -- destination state was left valid or restored, but ordinary staging cleanup failed; residue remains at '$stagingDir'. Cleanup error: $($_.Exception.Message)"
                if ($operationError) {
                    $cleanupMessage += " Original operation error: $($operationError.Exception.Message)"
                }
                Write-Log $cleanupMessage
                throw $cleanupMessage
            }
        }
    }
}

# Returns the installed BepInEx version string for a game's exe folder, or
# $null if BepInEx is not installed there. BepInEx\core\BepInEx.dll's own
# FileVersion is the only reliable version source -- .doorstop_version is
# the unrelated Doorstop bootstrap version, not BepInEx's.
function Get-BepInExInstalledVersion {
    param([string]$ExeDir)
    $dllPath = Join-Path $ExeDir 'BepInEx\core\BepInEx.dll'
    if (-not [System.IO.File]::Exists((ConvertTo-TpmAutoSyncLongPath -Path $dllPath))) { return $null }
    try {
        $vi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo((ConvertTo-TpmAutoSyncLongPath -Path $dllPath))
        if ([string]::IsNullOrWhiteSpace($vi.FileVersion)) { return $null }
        return $vi.FileVersion
    } catch { return $null }
}

# Returns 'x64', 'x86', or $null for an installed BepInEx's architecture.
# BepInEx's own managed DLLs are AnyCPU/MSIL in BOTH the win_x64 and win_x86
# zips, so they cannot reveal which build is installed -- only the native
# Doorstop winhttp.dll shim's PE machine type can.
function Get-BepInExInstalledArch {
    param([string]$ExeDir)
    $whPath = Join-Path $ExeDir 'winhttp.dll'
    if (-not (Test-Path -LiteralPath $whPath)) { return $null }
    return Get-ExeArchitecture -ExePath $whPath
}

function Get-BepInExPeArchitectureEvidence {
    param([Parameter(Mandatory)][string]$Path)
    $result=[pscustomobject]@{ State='UNKNOWN'; Architecture=$null; Machine=$null; Reason='PE architecture is unavailable or unreadable.' }
    $stream=$null
    try {
        if (-not (Test-Path -LiteralPath $Path -PathType Leaf -ErrorAction SilentlyContinue)) {
            $result.State='UNREADABLE'
            $result.Reason='The executable is missing or unreadable.'
            return $result
        }
        $stream=[System.IO.File]::OpenRead($Path)
        if ($stream.Length -lt 64) {
            $result.Reason='The executable header is incomplete.'
            return $result
        }
        $dosHeader=New-Object byte[] 64
        $read=0
        while ($read -lt $dosHeader.Length) {
            $count=$stream.Read($dosHeader,$read,$dosHeader.Length-$read)
            if ($count -eq 0) { break }
            $read+=$count
        }
        if ($read -ne $dosHeader.Length -or $dosHeader[0] -ne 0x4D -or $dosHeader[1] -ne 0x5A) {
            $result.Reason='The file does not contain a complete DOS executable header.'
            return $result
        }
        $peOffset=[System.BitConverter]::ToInt32($dosHeader,0x3C)
        if ($peOffset -lt 64 -or $peOffset -gt ($stream.Length - 6)) {
            $result.Reason='The PE architecture header is outside the file or incomplete.'
            return $result
        }
        [void]$stream.Seek($peOffset,[System.IO.SeekOrigin]::Begin)
        $peHeader=New-Object byte[] 6
        $read=0
        while ($read -lt $peHeader.Length) {
            $count=$stream.Read($peHeader,$read,$peHeader.Length-$read)
            if ($count -eq 0) { break }
            $read+=$count
        }
        if ($read -ne $peHeader.Length -or $peHeader[0] -ne 0x50 -or $peHeader[1] -ne 0x45 -or $peHeader[2] -ne 0 -or $peHeader[3] -ne 0) {
            $result.Reason='The file does not contain a complete PE signature and machine field.'
            return $result
        }
        $machine=[System.BitConverter]::ToUInt16($peHeader,4)
        if ($machine -eq 0) {
            $result.Reason='The PE machine field is empty.'
            return $result
        }
        if ($machine -eq 0x014C) { return [pscustomobject]@{ State='SUPPORTED'; Architecture='x86'; Machine=$machine; Reason='The PE machine type is supported.' } }
        if ($machine -eq 0x8664) { return [pscustomobject]@{ State='SUPPORTED'; Architecture='x64'; Machine=$machine; Reason='The PE machine type is supported.' } }
        return [pscustomobject]@{ State='UNSUPPORTED'; Architecture=$null; Machine=$machine; Reason='The valid PE machine type is not supported by the available x86/x64 packages.' }
    } catch {
        $result.State='UNREADABLE'
        $result.Reason='The executable architecture could not be read.'
        return $result
    } finally {
        if ($stream) { $stream.Dispose() }
    }
}

function Test-BepInExNoReparsePath {
    param([Parameter(Mandatory)][string]$Root, [Parameter(Mandatory)][string]$Path)
    try {
        if ([string]::IsNullOrWhiteSpace($Root) -or [string]::IsNullOrWhiteSpace($Path)) { return $false }
        if (-not (Test-PathInside -child $Path -parent $Root)) { return $false }
        if (-not (Test-Path -LiteralPath $Root -PathType Container -ErrorAction SilentlyContinue)) { return $false }
        return (Test-TpmNoReparsePath -Path $Path)
    } catch { return $false }
}

function Test-BepInExGameRootSafe {
    param([Parameter(Mandatory)][string]$GameRoot, [Parameter(Mandatory)][string]$ApprovedRoot)
    if (-not (Test-Path -LiteralPath $GameRoot -PathType Container -ErrorAction SilentlyContinue)) { return $false }
    return (Test-BepInExNoReparsePath -Root $ApprovedRoot -Path $GameRoot)
}
function Test-BepInExPackagePathSafe {
    param(
        [Parameter(Mandatory)][string]$PackagePath,
        [Parameter(Mandatory)][string]$CacheRoot
    )
    if ([string]::IsNullOrWhiteSpace($PackagePath) -or
        -not (Test-PathInside -child $PackagePath -parent $CacheRoot) -or
        -not (Test-Path -LiteralPath $PackagePath -PathType Leaf -ErrorAction SilentlyContinue)) { return $false }
    if (-not (Test-TpmNoReparsePath -Path $PackagePath)) { return $false }
    try {
        return ([int64](Get-Item -LiteralPath $PackagePath -Force -ErrorAction Stop).Length -gt 0)
    } catch { return $false }
}

function Get-BepInExGameLabel {
    param(
        [Parameter(Mandatory)][string]$ProfilePath,
        [Parameter(Mandatory)][string]$Fallback
    )
    try {
        $doc = Read-Xml $ProfilePath
        $name = if ($doc.GameProfile -and $doc.GameProfile.GameName) { ([string]$doc.GameProfile.GameName).Trim() } else { '' }
        if (-not [string]::IsNullOrWhiteSpace($name)) { return $name }
    } catch {}
    return $Fallback
}

function Write-BepInExUnsafeRootGuidance {
    param(
        [Parameter(Mandatory)][string]$GameCode,
        [string]$ApprovedRoot = '',
        [string]$Reason = 'the game folder is outside the approved root or contains a reparse-backed path',
        [string]$GameLabel = ''
    )
    $label = if ([string]::IsNullOrWhiteSpace($GameLabel)) { $GameCode } else { $GameLabel }
    Write-Host ("  TeknoParrot Manager could not safely update BepInEx for {0}." -f $label) -ForegroundColor Red
    Write-Host '  The game folder is not a normal folder inside your chosen Games folder.' -ForegroundColor Yellow
    Write-Host "  Check this game's path in TeknoParrot, then move or correct it inside the chosen Games folder." -ForegroundColor Yellow
    Write-Host '  TeknoParrot Manager did not download or change anything.' -ForegroundColor Yellow
    Write-Host '  Fix the path, then run BepInEx setup again. Choose Back to leave this setup unchanged.' -ForegroundColor Yellow
    Write-Log "BepInEx update check: blocked on unsafe game root for $GameCode. Technical reason: $Reason. Action required: verify the game is inside the approved non-reparse root."
}

function Get-BepInExInspectionFailure {
    param(
        [Parameter(Mandatory)][object]$ErrorRecord,
        [ValidateSet('UNKNOWN','UNSUPPORTED','UNREADABLE')][string]$ArchitectureState=''
    )
    $detail = [string]$ErrorRecord
    $exceptionMessage = if ($ErrorRecord -is [System.Management.Automation.ErrorRecord]) {
        [string]$ErrorRecord.Exception.Message
    } elseif ($ErrorRecord -is [System.Exception]) {
        [string]$ErrorRecord.Message
    } else {
        $detail
    }
    $code = 'INSPECTION_FAILED'
    $summary = 'TeknoParrot Manager could not inspect this game safely.'
    $nextAction = 'Open Details or the support log before choosing another action.'
    if ($ArchitectureState -eq 'UNSUPPORTED' -or $exceptionMessage -match '(?i)\bunsupported architecture\b') {
        $code = 'UNSUPPORTED_ARCHITECTURE'
        $summary = 'This game uses an architecture that TeknoParrot Manager cannot update automatically.'
        $nextAction = 'Use a BepInEx package that supports this game architecture, or verify the game executable with its vendor.'
    } elseif ($ArchitectureState -eq 'UNREADABLE') {
        $code = 'UNREADABLE_FILE'
        $summary = 'TeknoParrot Manager could not read the game file.'
        $nextAction = 'Check that the game file is there and can be opened, then run setup again.'
    } elseif ($ArchitectureState -eq 'UNKNOWN' -or $detail -match '(?i)architecture|x86|x64|native bootstrap') {
        $code = 'UNKNOWN_ARCHITECTURE'
        $summary = 'TeknoParrot Manager could not read this game architecture safely.'
        $nextAction = 'Verify the game executable and its BepInEx architecture, then run setup again.'
    } elseif ($detail -match '(?i)not applicable|no applicable|requiresbepinex') {
        $code = 'NOT_APPLICABLE'
        $summary = 'BepInEx is not applicable to this game.'
        $nextAction = 'No BepInEx change is needed for this game.'
    } elseif ($detail -match '(?i)not installed|missing BepInEx') {
        $code = 'NOT_INSTALLED'
        $summary = 'BepInEx is not installed for this game.'
        $nextAction = 'Choose Install/update if this game requires BepInEx.'
    }
    return [pscustomobject]@{ Code=$code; Summary=$summary; NextAction=$nextAction; Technical=$exceptionMessage }
}

# FIX82: the BepInEx result screen (menu 9). The default view is one status line, one line per kind of problem and one next step.
# The path check line, the counters, the reason codes and one block per game are in the Details view (key D) and in the log.
# All text goes through Write-TpmOutcome and Show-TpmDetailBlocks, so it is wrapped to the console width on every call.

# The path check line. The update check writes it to the log; the Details view builds it again from the result.
function Format-TpmBepInExPreflightText {
    param([int]$Eligible, [int]$MissingDevice, [int]$MissingPath, [int]$Protected, [int]$Other)
    return ('Path preflight: {0} eligible game(s), {1} unavailable-device skip(s), {2} missing-path skip(s), {3} protected/reparse skip(s), {4} other skip(s).' -f $Eligible, $MissingDevice, $MissingPath, $Protected, $Other)
}

# The plain words for one reason code: @(text for one game, text for several games). The code itself is shown in the Details view.
function Get-TpmBepInExSkipWords {
    param([Parameter(Mandatory)][string]$Code)
    $words = @{
        'UNKNOWN_ARCHITECTURE' = @('Could not tell if this game is 32-bit or 64-bit', 'Could not tell if these games are 32-bit or 64-bit')
        'UNREADABLE_FILE' = @('Could not read the game file', 'Could not read these game files')
        'UNSUPPORTED_ARCHITECTURE' = @('BepInEx cannot be set up automatically for this kind of game', 'BepInEx cannot be set up automatically for these kinds of games')
        'DEVICE_UNAVAILABLE' = @('The drive for this game is not connected', 'The drives for these games are not connected')
        'GAME_PATH_MISSING' = @('The game file was not found', 'The game files were not found')
        'PROTECTED_OR_REPARSE_ROOT' = @('This game is not in a normal folder inside your Games folder', 'These games are not in normal folders inside your Games folder')
        'ROLLBACK_FAILED' = @('A failed update could not be undone safely', 'Failed updates could not be undone safely')
        'MUTATION_BOUNDARY_FAILED' = @('The game folder changed while BepInEx was being added', 'The game folders changed while BepInEx was being added')
        'SOURCE_COLLECTION' = @('This game is inside your source folder, so TeknoParrot Manager left it alone', 'These games are inside your source folder, so TeknoParrot Manager left them alone')
    }
    if ($words.ContainsKey($Code)) { return $words[$Code] }
    return @('This game could not be finished', 'These games could not be finished')
}

function Get-TpmBepInExSkipText {
    param([Parameter(Mandatory)][string]$Code, [int]$Count)
    $words = Get-TpmBepInExSkipWords -Code $Code
    $text = if ($Count -eq 1) { $words[0] } else { $words[1] }
    return ('{0} ({1}).' -f $text, (Format-TpmGameCount -Count $Count))
}

# The one long sentence of counters the old screen printed. It is in the Details view and in the log, not on the default screen.
function Get-TpmBepInExCountsText {
    param($Result)
    if ($null -eq $Result) { return 'BepInEx did not return a result. No success was claimed.' }
    $mutation = Get-TpmTransactionField -Object $Result -Name 'Mutation'
    $failed = [int](Get-TpmTransactionField -Object $mutation -Name 'FailedItemCount' -Default 0)
    $unattempted = [int](Get-TpmTransactionField -Object $mutation -Name 'UnattemptedItemCount' -Default 0)
    $n = @{}
    foreach ($name in @('Updated', 'Skipped', 'Protected', 'MissingDevice', 'MissingPath', 'UnsupportedArchitecture', 'UnknownArchitecture', 'Errors')) { $n[$name] = [int](Get-TpmTransactionField -Object $Result -Name $name -Default 0) }
    $other = [Math]::Max(0, $n.Skipped - $n.Protected - $n.MissingDevice - $n.MissingPath - $n.UnsupportedArchitecture - $n.UnknownArchitecture)
    return ('BepInEx did not complete safely. Updated cleanly: {0}; failed: {1}; not attempted: {2}; skipped: {3} (protected: {4}, missing device: {5}, missing path: {6}, unsupported architecture: {7}, unreadable or unknown architecture: {8}, other: {9}); errors: {10}.' -f $n.Updated, $failed, $unattempted, $n.Skipped, $n.Protected, $n.MissingDevice, $n.MissingPath, $n.UnsupportedArchitecture, $n.UnknownArchitecture, $other, $n.Errors)
}

# One details block for one game that was left alone or failed.
function ConvertTo-TpmBepInExFailureBlock {
    param([Parameter(Mandatory)]$Record)
    $label = [string](Get-TpmTransactionField -Object $Record -Name 'GameLabel' -Default '')
    if ([string]::IsNullOrWhiteSpace($label)) { $label = [string](Get-TpmTransactionField -Object $Record -Name 'Game' -Default '') }
    $code = ([string](Get-TpmTransactionField -Object $Record -Name 'ReasonKey' -Default '') -split '\|')[0]
    $lines = New-Object System.Collections.Generic.List[string]
    Add-TpmDetailLine -Lines $lines -Label 'Reason' -Text $code
    if ($code) { Add-TpmDetailLine -Lines $lines -Label 'What it means' -Text ((Get-TpmBepInExSkipWords -Code $code)[0] + '.') }
    foreach ($field in @(@('Root', 'GameRoot'), @('Staging', 'StagingPath'), @('Backup', 'BackupPath'), @('Operation', 'Operation'), @('Exception', 'Exception'), @('Evidence preserved', 'EvidencePreserved'), @('Next action', 'NextAction'))) {
        Add-TpmDetailLine -Lines $lines -Label $field[0] -Text ([string](Get-TpmTransactionField -Object $Record -Name $field[1] -Default ''))
    }
    return @{ Heading = $label; Color = 'Yellow'; Lines = $lines.ToArray() }
}

# Every fact the old screen showed: the path check line (built again from the result), the counters sentence, the reason codes, the log
# file and one block per game.
function Get-TpmBepInExDetailBlocks {
    param([Parameter(Mandatory)]$Result, [string]$LogPath = '')
    $records = @(Get-TpmTransactionField -Object $Result -Name 'FailureRecords' -Default @() | Where-Object { $null -ne $_ })
    $counts = Get-TpmTransactionField -Object $Result -Name 'PathReasonCounts' -Default @{}
    $device = [int](Get-TpmTransactionField -Object $Result -Name 'MissingDevice' -Default 0)
    $path = [int](Get-TpmTransactionField -Object $Result -Name 'MissingPath' -Default 0)
    $protected = [int](Get-TpmTransactionField -Object $Result -Name 'Protected' -Default 0)
    $selected = @(Get-TpmTransactionField -Object $Result -Name 'SelectedItems' -Default @()).Count
    $preflightSkips = @($records | Where-Object { [string](Get-TpmTransactionField -Object $_ -Name 'Operation' -Default '') -in @('path preflight', 'root safety preflight') }).Count
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add((Format-TpmBepInExPreflightText -Eligible ([Math]::Max(0, $selected - $preflightSkips)) -MissingDevice $device -MissingPath $path -Protected $protected -Other ([Math]::Max(0, $preflightSkips - $device - $path - $protected))))
    [void]$lines.Add('Totals: ' + (Get-TpmBepInExCountsText -Result $Result))
    Add-TpmDetailLine -Lines $lines -Label 'Result code' -Text ([string](Get-TpmTransactionField -Object $Result -Name 'ReasonCode' -Default ''))
    foreach ($code in @($counts.Keys | Sort-Object)) { [void]$lines.Add(('Reason code: {0} ({1})' -f $code, (Format-TpmGameCount -Count ([int]$counts[$code])))) }
    Add-TpmDetailLine -Lines $lines -Label 'Technical log' -Text $LogPath
    $blocks = New-Object System.Collections.Generic.List[object]
    [void]$blocks.Add(@{ Heading = 'What was counted'; Lines = $lines.ToArray() })
    foreach ($record in $records) { [void]$blocks.Add((ConvertTo-TpmBepInExFailureBlock -Record $record)) }
    return $blocks.ToArray()
}

# The lines every BepInEx result shows: how the selected games came out, and where a kept backup is.
function Get-TpmBepInExDoneLines {
    param($Result)
    $lines = New-Object System.Collections.Generic.List[string]
    $counts = Get-TpmResultCountsLine -Result $Result -Picked @(Get-TpmTransactionField -Object $Result -Name 'PickedItems' -Default @())
    if ($counts) { [void]$lines.Add($counts) }
    $kept = @(Get-TpmTransactionField -Object $Result -Name 'FailureRecords' -Default @() | ForEach-Object { [string](Get-TpmTransactionField -Object $_ -Name 'BackupPath' -Default '') } | Where-Object { $_ })
    $backup = Get-TpmBackupFolderLine -Result $Result -ExtraPaths $kept -What 'the game files'
    if ($backup) { [void]$lines.Add($backup) }
    # Eggman guide (BepInEx section): a BepInEx game must be started and restarted twice the first time so the framework can finish setting up.
    if ([int](Get-TpmTransactionField -Object $Result -Name 'Updated' -Default 0) -gt 0) {
        [void]$lines.Add('The first time you start a BepInEx game, start it and close it twice so BepInEx can finish setting itself up. To reset BepInEx, delete only its cache and config folders.')
    }
    return $lines.ToArray()
}

# The screen as data: the parameters of Write-TpmOutcome. A missing result is shown honestly, never as success.
function Get-TpmBepInExFailureView {
    param($Result, [string]$LogPath = '')
    $note = 'TeknoParrot Manager does not count a failed or unchecked update as done.'
    if ($null -eq $Result) {
        return @{
            Title = 'BepInEx did not give a result. Nothing is counted as done.'
            Status = 'Problem'
            Next = 'Press R to try again, or B to go back.'
            DetailBlocks = @(@{ Heading = 'What was counted'; Lines = @('Totals: ' + (Get-TpmBepInExCountsText -Result $null)) })
            DetailsNote = $note
        }
    }
    $mutation = Get-TpmTransactionField -Object $Result -Name 'Mutation'
    $updated = [int](Get-TpmTransactionField -Object $Result -Name 'Updated' -Default 0)
    $errors = [int](Get-TpmTransactionField -Object $Result -Name 'Errors' -Default 0)
    $failed = [int](Get-TpmTransactionField -Object $mutation -Name 'FailedItemCount' -Default 0)
    $unattempted = [int](Get-TpmTransactionField -Object $mutation -Name 'UnattemptedItemCount' -Default 0)
    $counts = Get-TpmTransactionField -Object $Result -Name 'PathReasonCounts' -Default @{}
    $rollbackIssue = ($null -ne $counts -and $counts.ContainsKey('ROLLBACK_FAILED'))
    $pathIssue = ([int](Get-TpmTransactionField -Object $Result -Name 'MissingPath' -Default 0) -gt 0)
    $driveIssue = ([int](Get-TpmTransactionField -Object $Result -Name 'MissingDevice' -Default 0) -gt 0)
    $needs = New-Object System.Collections.Generic.List[string]
    foreach ($code in @($counts.Keys | Sort-Object)) { [void]$needs.Add((Get-TpmBepInExSkipText -Code ([string]$code) -Count ([int]$counts[$code]))) }
    if ($failed -gt 0) { [void]$needs.Add(('{0} could not be updated.' -f (Format-TpmGameCount -Count $failed))) }
    if ($unattempted -gt 0) { [void]$needs.Add(('{0} not tried, because an earlier step stopped.' -f (Format-TpmGameCount -Count $unattempted))) }
    if ($needs.Count -eq 0) { Add-TpmPlainReasonLine -Lines $needs -Code ([string](Get-TpmTransactionField -Object $Result -Name 'ReasonCode' -Default '')) }
    $next = 'Press D to see why, or R to try again.'
    if ($rollbackIssue) { $next = 'Do not try again yet. Press D for details, or O for help.' }
    elseif ($pathIssue) { $next = 'Press H to fix the saved game paths, then press R to try again.' }
    elseif ($driveIssue) { $next = 'Plug in the drive for the game, then press R to try again. Or choose 13 (Library health check) in the main menu to repair these games.' }
    elseif ($counts.ContainsKey('SOURCE_COLLECTION')) { $next = 'Move the game out of your source folder, or fix the game folder in its profile. Then run BepInEx setup again.' }
    $view = @{
        Title = 'BepInEx could not finish for every game.'
        Status = $(if ($rollbackIssue -or $failed -gt 0 -or $errors -gt 0) { 'Problem' } else { 'Attention' })
        Needs = $needs.ToArray()
        Next = $next
        DetailBlocks = @(Get-TpmBepInExDetailBlocks -Result $Result -LogPath $LogPath)
        DetailsNote = $note
    }
    if ($updated -gt 0) { $view.Done = @(('BepInEx was set up for {0}.' -f (Format-TpmGameCount -Count $updated))) }
    $doneLines = @(Get-TpmBepInExDoneLines -Result $Result)
    if ($doneLines.Count -gt 0) { $view.Done = @(@($view['Done']) + $doneLines | Where-Object { $_ }) }
    # Every game the user picked worked. What is left over are games they did not pick (a drive that is not connected, a game this setup cannot read), so this is not a failure.
    if ($updated -gt 0 -and $failed -eq 0 -and $unattempted -eq 0 -and -not $rollbackIssue) {
        $view.Title = ('BepInEx is set up for {0} you picked. Other games in your library were left alone.' -f (Format-TpmGameCount -Count $updated))
        $view.Status = 'Attention'
    }
    return $view
}

function Show-TpmBepInExFailureSummary {
    param($Result)
    $view = Get-TpmBepInExFailureView -Result $Result
    # The menu under this screen has its own [D] Details key, so Write-TpmOutcome asks no Details question of its own.
    Write-TpmOutcome @view -Unattended
}


function Get-BepInExInstallationHealth {
    param([Parameter(Mandatory)][string]$ExeDir)
    $result = [ordered]@{ Installed = $false; Complete = $false; Version = $null; Architecture = $null; Reason = 'Not installed' }
    $dllPath = Join-Path $ExeDir 'BepInEx\core\BepInEx.dll'
    if (-not (Test-Path -LiteralPath $dllPath -PathType Leaf)) { return [pscustomobject]$result }
    $result.Installed = $true
    $result.Version = Get-BepInExInstalledVersion -ExeDir $ExeDir
    $result.Architecture = Get-BepInExInstalledArch -ExeDir $ExeDir
    $required = @('BepInEx\core\BepInEx.dll', 'winhttp.dll', 'doorstop_config.ini', '.doorstop_version')
    foreach ($relative in $required) {
        $path = Join-Path $ExeDir $relative
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            $result.Reason = 'Missing ' + $relative
            return [pscustomobject]$result
        }
        if (-not (Test-BepInExNoReparsePath -Root $ExeDir -Path $path)) {
            $result.Reason = 'Unsafe ' + $relative
            return [pscustomobject]$result
        }
    }
    if ([string]::IsNullOrWhiteSpace([string]$result.Version)) { $result.Reason = 'BepInEx version is unreadable'; return [pscustomobject]$result }
    if ($result.Architecture -notin @('x64','x86')) { $result.Reason = 'BepInEx native bootstrap architecture is unreadable'; return [pscustomobject]$result }
    $result.Complete = $true
    $result.Reason = 'Complete'
    return [pscustomobject]$result
}

function Get-BepInExEnumeratedItems {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$Label,
        [switch]$FilesOnly
    )
    $started = Get-Date
    $current = 0
    $currentCompleted = $false
    try {
        if ($FilesOnly) {
            Get-ChildItem -LiteralPath $Path -File -Recurse -ErrorAction Stop | ForEach-Object {
                $current++
                Write-TpmCompactExtractionProgress -Phase 'Checking' -Label $Label -Current $current -Total 0 -StartedAt $started
                $_
            }
        } else {
            Get-ChildItem -LiteralPath $Path -Force -Recurse -ErrorAction Stop | ForEach-Object {
                $current++
                Write-TpmCompactExtractionProgress -Phase 'Checking' -Label $Label -Current $current -Total 0 -StartedAt $started
                $_
            }
        }
        $currentCompleted = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label $Label -Current $current -Total 0 -StartedAt $started -Complete -Outcome $(if ($currentCompleted) { 'Final' } else { 'Error' })
    }
}

function Test-BepInExExistingTreeSafe {
    param([Parameter(Mandatory)][string]$GameRoot)
    foreach ($name in @('BepInEx', 'doorstop_config.ini', 'winhttp.dll', '.doorstop_version', 'changelog.txt')) {
        $path = Join-Path $GameRoot $name
        if (-not (Test-Path -LiteralPath $path)) { continue }
        if (-not (Test-BepInExNoReparsePath -Root $GameRoot -Path $path)) { return $false }
        try {
            $item = Get-Item -LiteralPath $path -Force -ErrorAction Stop
            if ($item.PSIsContainer) {
                Get-BepInExEnumeratedItems -Path $path -Label 'BepInEx installed-tree safety scan' | ForEach-Object {
                    if (($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'BepInEx installed tree contains a reparse point.' }
                }
            }
        } catch { return $false }
    }
    return $true
}

function Get-BepInExStagedFiles {
    param([Parameter(Mandatory)][string]$StagingDir, [Parameter(Mandatory)][string]$DestDir)
    if (-not (Test-Path -LiteralPath $StagingDir -PathType Container)) { throw 'BepInEx staging directory is missing.' }
    Get-BepInExEnumeratedItems -Path $StagingDir -Label 'BepInEx staged-tree safety scan' | ForEach-Object {
        if (($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'BepInEx staging contains a reparse point.' }
    }
    $stageFull = [System.IO.Path]::GetFullPath($StagingDir).TrimEnd('\','/')
    $files = @(Get-BepInExEnumeratedItems -Path $StagingDir -Label 'BepInEx staged-file discovery' -FilesOnly | Sort-Object FullName)
    $result = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    $fileStarted = Get-Date
    $fileCurrent = 0
    $fileCurrentDone = $false
    try {
        foreach ($file in $files) {
            $fileCurrent++
            Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'BepInEx staged-file classification' -Current $fileCurrent -Total $files.Count -StartedAt $fileStarted
            $relative = $file.FullName.Substring($stageFull.Length).TrimStart('\','/')
            if ([string]::IsNullOrWhiteSpace($relative) -or [System.IO.Path]::IsPathRooted($relative) -or $relative -match '(^|[\/])\.\.([\/]|$)') { throw 'BepInEx staging contains an unsafe relative path.' }
            $destPath = Join-Path $DestDir $relative
            if (-not (Test-PathInside -child $file.FullName -parent $StagingDir) -or -not (Test-PathInside -child $destPath -parent $DestDir)) { throw 'BepInEx staging path escaped its approved directory.' }
            $key = $relative.ToLowerInvariant()
            if ($seen.ContainsKey($key)) { throw 'BepInEx staging contains duplicate file names.' }
            $seen[$key] = $true
            [void]$result.Add($relative)
        }
        $fileCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'BepInEx staged-file classification' -Current $(if ($fileCurrentDone) { $fileCurrent } else { $fileCurrent - 1 }) -Total $files.Count -StartedAt $fileStarted -Complete -Outcome $(if ($fileCurrentDone) { 'Final' } else { 'Error' })
    }
    if ($result.Count -eq 0) { throw 'BepInEx ZIP contained no files to promote.' }
    return @($result)
}

# Removes only a TPM-created BepInEx staging directory under the controlled
# temporary root. The complete path and every existing descendant are checked
# again immediately before recursive deletion so cleanup cannot follow a
# replaced reparse point or delete an unrelated path.
function Remove-BepInExStagingDirectory {
    param([Parameter(Mandatory)][string]$StagingDir)
    if ([string]::IsNullOrWhiteSpace($StagingDir) -or $StagingDir -match '[\r\n]') {
        throw 'TPM BEPINEX STAGING CLEANUP REFUSED because the staging path was empty or malformed.'
    }
    try {
        $stagingRoot = [System.IO.Path]::GetFullPath((Join-Path $env:TEMP 'TeknoParrotManagerStaging')).TrimEnd('\','/')
        $stagingFull = [System.IO.Path]::GetFullPath($StagingDir).TrimEnd('\','/')
    } catch {
        throw 'TPM BEPINEX STAGING CLEANUP REFUSED because the staging path could not be canonicalized.'
    }
    $leaf = [System.IO.Path]::GetFileName($stagingFull)
    if ([string]::IsNullOrWhiteSpace($leaf) -or $leaf -notlike 'BepInEx-*' -or
        -not (Test-PathInside -child $stagingFull -parent $stagingRoot)) {
        throw "TPM BEPINEX STAGING CLEANUP REFUSED for '$stagingFull' because it is not a TPM BepInEx directory under the controlled staging root."
    }
    if (-not (Test-Path -LiteralPath $stagingFull)) { return $true }
    if (-not (Test-BepInExNoReparsePath -Root $stagingRoot -Path $stagingFull)) {
        throw "TPM BEPINEX STAGING CLEANUP REFUSED for '$stagingFull' because its path is reparse-backed or otherwise unsafe."
    }
    try {
        $pending = New-Object 'System.Collections.Generic.Stack[string]'
        $files = New-Object 'System.Collections.Generic.List[string]'
        $directories = New-Object 'System.Collections.Generic.List[string]'
        $pending.Push($stagingFull)
        $scanStarted = Get-Date
        $scanCurrent = 0
        $scanCurrentCompleted = $false
        try {
            while ($pending.Count -gt 0) {
                $current = $pending.Pop()
                if (-not (Test-PathInside -child $current -parent $stagingRoot) -or
                    -not (Test-BepInExNoReparsePath -Root $stagingRoot -Path $current)) {
                    throw "staging directory is outside the controlled root or reparse-backed: $current"
                }
                [void]$directories.Add($current)
                Get-ChildItem -LiteralPath $current -Force -ErrorAction Stop | ForEach-Object {
                    $scanCurrent++
                    Write-TpmCompactExtractionProgress -Phase Checking -Label 'BepInEx staging cleanup safety scan' -Current $scanCurrent -Total 0 -StartedAt $scanStarted
                    $childFull = [System.IO.Path]::GetFullPath($_.FullName)
                    if (-not (Test-PathInside -child $childFull -parent $stagingFull)) {
                        throw "staging descendant escaped the validated directory: $childFull"
                    }
                    if (($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) {
                        throw "staging descendant is reparse-backed: $childFull"
                    }
                    if ($_.PSIsContainer) { $pending.Push($childFull) } else { [void]$files.Add($childFull) }
                }
            }
            $scanCurrentCompleted = $true
        } finally {
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'BepInEx staging cleanup safety scan' -Current $scanCurrent -Total 0 -StartedAt $scanStarted -Complete -Outcome $(if ($scanCurrentCompleted) { 'Final' } else { 'Error' })
        }
        $fileStarted = Get-Date
        $fileCurrent = 0
        $fileCurrentDone = $false
        try {
            foreach ($file in $files) {
                $fileCurrent++
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'BepInEx staging cleanup files' -Current $fileCurrent -Total $files.Count -StartedAt $fileStarted
                if (-not (Test-Path -LiteralPath $file)) { continue }
                if (-not (Test-PathInside -child $file -parent $stagingFull) -or
                    -not (Test-BepInExNoReparsePath -Root $stagingRoot -Path $file)) {
                    throw "staging file changed to an unsafe path before cleanup: $file"
                }
                Remove-Item -LiteralPath $file -Force -ErrorAction Stop
            }
            $fileCurrentDone = $true
        } finally {
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'BepInEx staging cleanup files' -Current $(if ($fileCurrentDone) { $fileCurrent } else { $fileCurrent - 1 }) -Total $files.Count -StartedAt $fileStarted -Complete -Outcome $(if ($fileCurrentDone) { 'Final' } else { 'Error' })
        }
        $directoryStarted = Get-Date
        $directoryCurrent = 0
        $directoryCurrentDone = $false
        try {
            for ($i = $directories.Count - 1; $i -ge 0; $i--) {
                $directoryCurrent++
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'BepInEx staging cleanup directories' -Current $directoryCurrent -Total $directories.Count -StartedAt $directoryStarted
                $directory = $directories[$i]
                if (-not (Test-Path -LiteralPath $directory)) { continue }
                if (-not (Test-PathInside -child $directory -parent $stagingRoot) -or
                    -not (Test-BepInExNoReparsePath -Root $stagingRoot -Path $directory)) {
                    throw "staging directory changed to an unsafe path before cleanup: $directory"
                }
                Remove-Item -LiteralPath $directory -Force -ErrorAction Stop
            }
            $directoryCurrentDone = $true
        } finally {
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'BepInEx staging cleanup directories' -Current $(if ($directoryCurrentDone) { $directoryCurrent } else { $directoryCurrent - 1 }) -Total $directories.Count -StartedAt $directoryStarted -Complete -Outcome $(if ($directoryCurrentDone) { 'Final' } else { 'Error' })
        }
        if (Test-Path -LiteralPath $stagingFull) { throw 'staging directory remains after removal' }
    } catch {
        throw "TPM BEPINEX STAGING CLEANUP FAILED for '$stagingFull' -- residue remains at '$stagingFull'. Cleanup error: $($_.Exception.Message)"
    }
    return $true
}

function Test-BepInExFileMatch {
    param([Parameter(Mandatory)][string]$Source, [Parameter(Mandatory)][string]$Destination)
    if (-not (Test-Path -LiteralPath $Source -PathType Leaf) -or -not (Test-Path -LiteralPath $Destination -PathType Leaf)) { return $false }
    try {
        $sourceItem = Get-Item -LiteralPath $Source -Force -ErrorAction Stop
        $destItem = Get-Item -LiteralPath $Destination -Force -ErrorAction Stop
        if ($sourceItem.Length -ne $destItem.Length) { return $false }
        $sourceHash = (Get-FileHash -LiteralPath $Source -Algorithm SHA256 -ErrorAction Stop).Hash
        $destHash = (Get-FileHash -LiteralPath $Destination -Algorithm SHA256 -ErrorAction Stop).Hash
        return [string]::Equals([string]$sourceHash, [string]$destHash, [System.StringComparison]::OrdinalIgnoreCase)
    } catch { return $false }
}

# Recovery uses pinned directory chains and read-only file streams. No recovery
# operation deletes an occupied destination, even when its bytes match a package.
function Add-BepInExRecoveryDirectoryLock {
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][AllowEmptyCollection()]$Locks)
    $null = Get-TpmSupportNativeType
    $full = [System.IO.Path]::GetFullPath($Path)
    $root = [System.IO.Path]::GetPathRoot($full)
    $cursor = $root
    $paths = @($root)
    foreach ($part in ($full.Substring($root.Length) -split '[\\/]')) {
        if ($part) { $cursor = Join-Path $cursor $part; $paths += $cursor }
    }
    foreach ($directory in $paths) {
        $handle = [TpmSupportNativeMethods]::CreateFile($directory, [TpmSupportNativeMethods]::FileReadAttributes, [TpmSupportNativeMethods]::ShareRead, [IntPtr]::Zero, [TpmSupportNativeMethods]::OpenExisting, ([TpmSupportNativeMethods]::FileFlagBackupSemantics -bor [TpmSupportNativeMethods]::FileFlagOpenReparsePoint), [IntPtr]::Zero)
        if ($handle.IsInvalid) { $handle.Dispose(); throw "BepInEx recovery cannot pin directory '$directory'." }
        [void]$Locks.Add($handle)
        $attributes = [TpmSupportNativeMethods]::PatchAttributes($handle)
        $final = Get-TpmSupportFinalPathFromHandle -Handle $handle
        if (($attributes -band 0x410) -ne 0x10 -or $final.TrimEnd('\','/') -ine (Resolve-TpmSupportExpectedFinalPath -Path $directory).TrimEnd('\','/')) {
            throw "BepInEx recovery refused a reparse or changed directory '$directory'."
        }
    }
    return $handle
}

# Read-only diagnostics for the recovery directory guards. A broken guard always
# fails closed; these helpers only say WHICH directory changed and what its
# enumeration-visible metadata looked like, so a refused backup is explainable.
function Get-BepInExRecoveryListing {
    param([Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Children)
    return @($Children | Sort-Object Name | ForEach-Object {
        '{0}|{1}|{2}|w{3}|a{4}' -f $_.Name, $(if ($_.PSIsContainer) { 'dir' } else { $_.Length }), [int]$_.Attributes, $_.LastWriteTimeUtc.Ticks, $_.LastAccessTimeUtc.Ticks
    })
}

function Get-BepInExRecoveryMembershipKeys {
    param([Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Listing)
    # Name + file/directory kind only. The size, attributes, write and access times
    # that a parent listing reports for a child are duplicated, lazily refreshed
    # index metadata: they move when TPM itself opens, reads or closes that child.
    # Content is proven separately by the held, hashed streams.
    return @($Listing | ForEach-Object { $parts = $_ -split '\|', 3; $parts[0] + '|' + $(if ($parts[1] -ceq 'dir') { 'dir' } else { 'file' }) })
}

function Assert-BepInExRecoveryGuards {
    param([Parameter(Mandatory)][AllowEmptyCollection()][object[]]$GuardDetails, [Parameter(Mandatory)][string]$Stage)
    foreach ($detail in @($GuardDetails | Where-Object { $null -ne $_ })) {
        try { $detail.Guard.AssertUnchanged() }
        catch {
            $guardMessage = if ($_.Exception.InnerException) { [string]$_.Exception.InnerException.Message } else { [string]$_.Exception.Message }
            $observed = ''
            try {
                $now = @(Get-BepInExRecoveryListing -Children @(Get-ChildItem -LiteralPath $detail.Path -Force -ErrorAction Stop))
                $was = @($detail.Baseline)
                $changes = @(@($was | Where-Object { $_ -notin $now } | ForEach-Object { 'was ' + $_ }) + @($now | Where-Object { $_ -notin $was } | ForEach-Object { 'now ' + $_ }))
                $observed = if ($changes.Count -gt 0) { ' Listing difference: ' + (@($changes | Select-Object -First 6) -join '; ') + '.' } else { ' No listing difference was visible afterwards.' }
            } catch { $observed = ' The directory could not be listed afterwards.' }
            throw "BepInEx recovery directory changed during $Stage ('$($detail.Path)'). $guardMessage$observed"
        }
    }
}

function Get-BepInExRecoveryInventory {
    param([Parameter(Mandatory)][string]$Root, [Parameter(Mandatory)][AllowEmptyCollection()]$Locks, [hashtable]$OwnedStreams=@{}, [string]$ProgressLabel='BepInEx recovery inventory')
    $null = Add-BepInExRecoveryDirectoryLock -Path $Root -Locks $Locks
    $guards = New-Object System.Collections.Generic.List[object]
    $guardDetails = New-Object System.Collections.Generic.List[object]
    # Membership guards are armed only after TPM's own scan, deepest directory first.
    # Opening, enumerating and hashing a child makes the filesystem refresh that child's
    # duplicated entry in its parent; with the parent already guarded, TPM's own scan
    # broke its own guard (observed on a test PC). Each guard is armed, then membership is
    # re-listed and must equal what the scan saw, so a break afterwards is still fatal.
    $scanDirectories = New-Object System.Collections.Generic.List[object]
    [void]$scanDirectories.Add([pscustomobject]@{ Path=$Root; Listing=@(Get-BepInExRecoveryListing -Children @(Get-ChildItem -LiteralPath $Root -Force -ErrorAction Stop)) })
    $records = New-Object System.Collections.Generic.List[object]
    $streams = @{}
    $pending = New-Object System.Collections.Generic.Queue[string]
    foreach ($name in @('BepInEx','doorstop_config.ini','winhttp.dll','.doorstop_version','changelog.txt')) { $pending.Enqueue($name) }
    $scanStarted = Get-Date
    $scanCurrent = 0
    try {
        while ($pending.Count -gt 0) {
            $relative = $pending.Dequeue()
            $scanCurrent++
            Write-TpmCompactExtractionProgress -Phase 'Checking' -Label $ProgressLabel -Current $scanCurrent -Total 0 -StartedAt $scanStarted
            $path = [System.IO.Path]::GetFullPath((Join-Path $Root $relative))
            $item = $null
            # A missing path inside a bracketed game folder ("[TP]") is not reported as missing by Get-Item in
            # Windows PowerShell 5.1, so ask .NET first (GetAttributes still sees a dangling link).
            $pathMissing = $false
            try { [void][System.IO.File]::GetAttributes($path) }
            catch [System.IO.FileNotFoundException], [System.IO.DirectoryNotFoundException] { $pathMissing = $true }
            catch { }
            try {
                if ($pathMissing) { throw (New-Object System.IO.FileNotFoundException) }
                $item = Get-Item -LiteralPath $path -Force -ErrorAction Stop
            }
            catch {
                if ($_.Exception -isnot [System.Management.Automation.ItemNotFoundException] -and $_.Exception -isnot [System.IO.FileNotFoundException] -and $_.Exception -isnot [System.IO.DirectoryNotFoundException]) { throw }
                if ($relative -match '[\\/]') { throw "BepInEx inventory changed at '$relative'." }
            }
            if ($null -eq $item) {
                [void]$records.Add([pscustomobject]@{ RelativePath=$relative; Kind='Absent'; Attributes=0; OriginalAttributes=0; Length=$null; Sha256=$null; Identity=$null })
                continue
            }
            if (($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { throw "BepInEx inventory refused reparse entry '$relative'." }
            if ($item.PSIsContainer) {
                $directory = Add-BepInExRecoveryDirectoryLock -Path $path -Locks $Locks
                $attributes = [int][TpmSupportNativeMethods]::PatchAttributes($directory)
                [void]$records.Add([pscustomobject]@{ RelativePath=$relative; Kind='Directory'; Attributes=($attributes -band 0x37); OriginalAttributes=$attributes; Length=$null; Sha256=$null; Identity=$null })
                $children = @(Get-ChildItem -LiteralPath $path -Force -ErrorAction Stop)
                [void]$scanDirectories.Add([pscustomobject]@{ Path=$path; Listing=@(Get-BepInExRecoveryListing -Children $children) })
                foreach ($child in $children) { $pending.Enqueue($relative + '\' + $child.Name) }
            } else {
                if ($OwnedStreams.ContainsKey($path)) { $stream = $OwnedStreams[$path] }
                else {
                    $stream = New-Object System.IO.FileStream($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
                    [void]$Locks.Add($stream)
                }
                $final = Get-TpmSupportFinalPathFromHandle -Handle $stream.SafeFileHandle
                if ($final -ine (Resolve-TpmSupportExpectedFinalPath -Path $path)) { throw "BepInEx inventory file identity changed at '$relative'." }
                $identity = [TpmSupportNativeMethods]::PatchFileIdentity($stream.SafeFileHandle)
                $stream.Position = 0
                $hash = (Get-FileHash -InputStream $stream -Algorithm SHA256 -ErrorAction Stop).Hash
                $stream.Position = 0
                $streams[$relative] = $stream
                $attributes = [int][TpmSupportNativeMethods]::PatchAttributes($stream.SafeFileHandle)
                [void]$records.Add([pscustomobject]@{ RelativePath=$relative; Kind='File'; Attributes=($attributes -band 0x37); OriginalAttributes=$attributes; Length=$stream.Length; Sha256=$hash; Identity=$identity })
            }
        }
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label $ProgressLabel -Current $scanCurrent -Total 0 -StartedAt $scanStarted -Complete
    } catch {
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label $ProgressLabel -Current $scanCurrent -Total 0 -StartedAt $scanStarted -Complete -Outcome Error
        throw
    }
    foreach ($scanned in @($scanDirectories.ToArray() | Sort-Object { $_.Path.Length } -Descending)) {
        $guard = New-Object 'TpmSupportNativeMethods+RecoveryMembershipGuard' $scanned.Path
        [void]$Locks.Add($guard); [void]$guards.Add($guard)
        $armedListing = @(Get-BepInExRecoveryListing -Children @(Get-ChildItem -LiteralPath $scanned.Path -Force -ErrorAction Stop))
        if ((@(Get-BepInExRecoveryMembershipKeys -Listing $armedListing) -join "`n") -cne (@(Get-BepInExRecoveryMembershipKeys -Listing @($scanned.Listing)) -join "`n")) {
            throw "BepInEx recovery directory changed during inventory capture ('$($scanned.Path)'). Membership differed when the directory guard was armed."
        }
        [void]$guardDetails.Add([pscustomobject]@{ Path=$scanned.Path; Guard=$guard; Baseline=$armedListing })
    }
    $items = @($records | Sort-Object RelativePath)
    # Exact paths/types/bytes and ordinary flags are restorable. Filesystem
    # storage flags (compression/encryption/sparse) remain original evidence,
    # not a claim that a byte-identical copy has the same physical storage.
    $content = @($items | Select-Object RelativePath,Kind,Attributes,Length,Sha256)
    $hash = Get-TpmAutoSyncTextSha256 -Text (ConvertTo-Json -InputObject $content -Depth 5 -Compress)
    Assert-BepInExRecoveryGuards -GuardDetails $guardDetails.ToArray() -Stage 'inventory capture'
    return [pscustomobject]@{ Items=$items; Streams=$streams; Guards=$guards; GuardDetails=$guardDetails; InventoryHash=$hash }
}

function Copy-BepInExRecoveryInventory {
    param(
        [Parameter(Mandatory)]$Inventory, [Parameter(Mandatory)][string]$Destination,
        [Parameter(Mandatory)][AllowEmptyCollection()]$Locks,
        [Parameter(Mandatory)][AllowEmptyCollection()][hashtable]$OwnedStreams,
        [string]$ProgressLabel='BepInEx backup copy',
        [ValidateSet('Checking','Repairing')][string]$ProgressPhase='Checking'
    )
    $entries = @($Inventory.Items | Where-Object { ($_.RelativePath -split '[\\/]',2)[0] -in @('BepInEx','doorstop_config.ini','winhttp.dll','.doorstop_version','changelog.txt') })
    $directoryEntries = @($entries | Where-Object Kind -eq 'Directory' | Sort-Object { $_.RelativePath.Length })
    $fileEntries = @($entries | Where-Object Kind -eq 'File')
    $copyTotal = $directoryEntries.Count + $fileEntries.Count
    $copyStarted = Get-Date
    $copyCurrent = 0
    $directories = @{}
    try {
        foreach ($entry in $directoryEntries) {
            $copyCurrent++
            Write-TpmCompactExtractionProgress -Phase $ProgressPhase -Label $ProgressLabel -Current $copyCurrent -Total $copyTotal -StartedAt $copyStarted
            $path = [System.IO.Path]::GetFullPath((Join-Path $Destination $entry.RelativePath))
            $parent = Add-BepInExRecoveryDirectoryLock -Path ([System.IO.Path]::GetDirectoryName($path)) -Locks $Locks
            $directory = [TpmSupportNativeMethods]::RecoveryCreateDirectory($parent, [System.IO.Path]::GetFileName($path))
            [void]$Locks.Add($directory)
            $directories[$entry.RelativePath] = $directory
        }
        foreach ($entry in $fileEntries) {
            $copyCurrent++
            Write-TpmCompactExtractionProgress -Phase $ProgressPhase -Label $ProgressLabel -Current $copyCurrent -Total $copyTotal -StartedAt $copyStarted
            $path = [System.IO.Path]::GetFullPath((Join-Path $Destination $entry.RelativePath))
            $null = Add-BepInExRecoveryDirectoryLock -Path ([System.IO.Path]::GetDirectoryName($path)) -Locks $Locks
            $output = New-Object System.IO.FileStream($path, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Read)
            [void]$Locks.Add($output)
            $OwnedStreams[$path] = $output
            $source = $Inventory.Streams[$entry.RelativePath]
            $source.Position = 0
            $source.CopyTo($output)
            $output.Flush($true)
            [TpmSupportNativeMethods]::RecoverySetAttributes($output.SafeFileHandle, [uint32]$entry.Attributes)
        }
        foreach ($entry in @($directoryEntries | Sort-Object { $_.RelativePath.Length } -Descending)) {
            [TpmSupportNativeMethods]::RecoverySetAttributes($directories[$entry.RelativePath], [uint32]$entry.Attributes)
        }
        if ($copyTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase $ProgressPhase -Label $ProgressLabel -Current $copyCurrent -Total $copyTotal -StartedAt $copyStarted -Complete }
    } catch {
        if ($copyCurrent -gt 0) { Write-TpmCompactExtractionProgress -Phase $ProgressPhase -Label $ProgressLabel -Current $copyCurrent -Total $copyTotal -StartedAt $copyStarted -Complete -Outcome Error }
        throw
    }
}

function Read-BepInExRecoveryReceipt {
    param([Parameter(Mandatory)][System.IO.Stream]$Stream)
    $Stream.Position = 0
    $reader = New-Object System.IO.StreamReader($Stream, (New-Object System.Text.UTF8Encoding($false,$true)), $true, 1024, $true)
    try { return ($reader.ReadToEnd() | ConvertFrom-Json -ErrorAction Stop) }
    finally { $reader.Dispose() }
}

function New-BepInExUpdateBackup {
    param([Parameter(Mandatory)][string]$GameRoot)
    $locks = New-Object System.Collections.Generic.List[System.IDisposable]
    $ownedStreams = @{}
    $backupPath = $null
    try {
        $game = Add-BepInExRecoveryDirectoryLock -Path $GameRoot -Locks $locks
        $backupName = 'BepInEx_Backup_' + [guid]::NewGuid().ToString('N')
        $backupPath = Join-Path $GameRoot $backupName
        $container = [TpmSupportNativeMethods]::RecoveryCreateDirectory($game, $backupName)
        [void]$locks.Add($container)
        Lock-PostgresRecoveryDirectory -Path $backupPath
        $payload = Join-Path $backupPath 'payload'
        $payloadHandle = [TpmSupportNativeMethods]::RecoveryCreateDirectory($container, 'payload')
        [void]$locks.Add($payloadHandle)
        $before = Get-BepInExRecoveryInventory -Root $GameRoot -Locks $locks -ProgressLabel 'BepInEx backup source inventory'
        Copy-BepInExRecoveryInventory -Inventory $before -Destination $payload -Locks $locks -OwnedStreams $ownedStreams
        $backup = Get-BepInExRecoveryInventory -Root $payload -Locks $locks -OwnedStreams $ownedStreams -ProgressLabel 'BepInEx backup verification'
        if ($before.InventoryHash -ine $backup.InventoryHash) { throw 'BepInEx backup inventory/byte verification failed.' }
        $receipt = [pscustomobject]@{ SchemaVersion=1; GameRoot=[System.IO.Path]::GetFullPath($GameRoot); InventoryHash=$before.InventoryHash; Items=$before.Items }
        $receiptPath = Join-Path $backupPath 'inventory.json'
        $receiptStream = New-Object System.IO.FileStream($receiptPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Read)
        [void]$locks.Add($receiptStream)
        $writer = New-Object System.IO.StreamWriter($receiptStream, (New-Object System.Text.UTF8Encoding($false)), 1024, $true)
        try { $writer.Write((ConvertTo-Json -InputObject $receipt -Depth 8)); $writer.Flush(); $receiptStream.Flush($true) } finally { $writer.Dispose() }
        Lock-PostgresRecoveryFile -Path $receiptPath
        $saved = Read-BepInExRecoveryReceipt -Stream $receiptStream
        if ($saved.SchemaVersion -ne 1 -or [string]$saved.GameRoot -cne [string]$receipt.GameRoot -or $saved.InventoryHash -ine $before.InventoryHash -or (ConvertTo-Json -InputObject @($saved.Items) -Depth 5 -Compress) -cne (ConvertTo-Json -InputObject @($before.Items) -Depth 5 -Compress)) { throw 'BepInEx inventory persistence verification failed.' }
        # Receipt creation changes the game-root enumeration. Certify a fresh
        # pre-mutation snapshot only after all backup/receipt writes finish.
        $after = Get-BepInExRecoveryInventory -Root $GameRoot -Locks $locks -ProgressLabel 'BepInEx backup source recheck'
        if ($after.InventoryHash -ine $before.InventoryHash) { throw 'BepInEx source inventory changed during backup.' }
        # [object[]] cast, not @(): @() over a New-Object List[object] throws "Argument types do not match" (PowerShell #27558).
        Assert-BepInExRecoveryGuards -GuardDetails ([object[]]$backup.GuardDetails) -Stage 'backup payload verification'
        Assert-BepInExRecoveryGuards -GuardDetails ([object[]]$after.GuardDetails) -Stage 'backup source recheck'
        return $backupPath
    } catch {
        throw "BepInEx backup failed; no reset was authorized; evidence remains at '$backupPath'. Detail: $($_.Exception.Message)"
    } finally {
        for ($i=$locks.Count-1; $i -ge 0; $i--) { $locks[$i].Dispose() }
    }
}

# Transaction-output ownership. A path is altered or removed only while its live
# identity (volume/file index) and bytes still match this transaction's journal;
# anything else is preserved as evidence and reported as an unverified rollback.
function Get-TpmTreeFileState {
    param([Parameter(Mandatory)][string]$Path)
    $null = Get-TpmSupportNativeType
    $state = [pscustomobject]@{ Kind='Absent'; Identity=$null; Sha256=$null; Length=$null; Attributes=0; Reason='' }
    $share = [TpmSupportNativeMethods]::ShareRead -bor [TpmSupportNativeMethods]::ShareWrite -bor [TpmSupportNativeMethods]::ShareDelete
    $handle = [TpmSupportNativeMethods]::CreateFile($Path, [TpmSupportNativeMethods]::GenericRead, $share, [IntPtr]::Zero, [TpmSupportNativeMethods]::OpenExisting, [TpmSupportNativeMethods]::FileFlagOpenReparsePoint, [IntPtr]::Zero)
    if ($handle.IsInvalid) {
        $handle.Dispose()
        # Windows PowerShell 5.1 Get-Item does not report a MISSING path inside a bracketed folder
        # (every game folder ends in "[TP]") as missing, so ask .NET first. GetAttributes still sees a
        # dangling link, so an unsafe link is never mistaken for an absent file.
        try { [void][System.IO.File]::GetAttributes($Path) }
        catch [System.IO.FileNotFoundException], [System.IO.DirectoryNotFoundException] { return $state }
        catch { }
        try {
            $existing = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
            $state.Kind = 'Other'
            $state.Reason = if ($existing.PSIsContainer) { 'it is a folder, not a file' } else { 'it exists but Windows would not let the Manager read it (it may be in use or protected)' }
        }
        catch [System.Management.Automation.ItemNotFoundException] { }
        catch { $state.Kind = 'Other'; $state.Reason = 'it could not be checked: ' + $_.Exception.Message }
        return $state
    }
    $stream = $null
    try {
        $attributes = [int][TpmSupportNativeMethods]::PatchAttributes($handle)
        if (($attributes -band 0x400) -ne 0) { $state.Kind = 'Other'; $state.Reason = 'it is a shortcut or link to somewhere else'; return $state }
        if (($attributes -band 0x10) -ne 0) { $state.Kind = 'Other'; $state.Reason = 'it is a folder, not a file'; return $state }
        $identity = [TpmSupportNativeMethods]::PatchFileIdentity($handle)
        $stream = New-Object System.IO.FileStream($handle, [System.IO.FileAccess]::Read)
        $state.Attributes = $attributes -band 0x27
        $state.Length = $stream.Length
        $state.Sha256 = (Get-FileHash -InputStream $stream -Algorithm SHA256 -ErrorAction Stop).Hash
        $state.Identity = $identity
        $state.Kind = 'File'
    } catch {
        $state.Kind = 'Other'; $state.Identity = $null; $state.Sha256 = $null
        if ($_.Exception.Message -like '*without hard links*') { $state.Reason = 'the same file is shared with another folder (a hard link), so changing it here would also change the other copy' }
        else { $state.Reason = 'it could not be read safely: ' + $_.Exception.Message }
    } finally {
        if ($null -ne $stream) { $stream.Dispose() } else { $handle.Dispose() }
    }
    return $state
}

# Handle-bound removal: identity, last write time (when supplied) and bytes are verified on the same handle that
# receives the delete disposition, and writers are excluded while it is open. A rewrite in place keeps the file ID
# and can keep the bytes, so the write time recorded at promotion is what shows another writer touched the file.
function Remove-TpmTreeOwnedFile {
    param([Parameter(Mandatory)][string]$Path, [string]$ExpectedIdentity, [string]$ExpectedSha256, [Nullable[datetime]]$ExpectedLastWriteTimeUtc = $null)
    $null = Get-TpmSupportNativeType
    if ([string]::IsNullOrWhiteSpace($ExpectedIdentity)) { throw 'no creation identity was recorded for this output' }
    $share = [TpmSupportNativeMethods]::ShareRead -bor [TpmSupportNativeMethods]::ShareDelete
    $access = [TpmSupportNativeMethods]::GenericRead -bor [TpmSupportNativeMethods]::Delete
    $handle = [TpmSupportNativeMethods]::CreateFile($Path, $access, $share, [IntPtr]::Zero, [TpmSupportNativeMethods]::OpenExisting, [TpmSupportNativeMethods]::FileFlagOpenReparsePoint, [IntPtr]::Zero)
    if ($handle.IsInvalid) {
        $handle.Dispose()
        # Same bracketed-path hazard as Get-TpmTreeFileState: ask .NET first whether the path is missing.
        try { [void][System.IO.File]::GetAttributes($Path) }
        catch [System.IO.FileNotFoundException], [System.IO.DirectoryNotFoundException] { return 'Absent' }
        catch { }
        try { $null = Get-Item -LiteralPath $Path -Force -ErrorAction Stop }
        catch [System.Management.Automation.ItemNotFoundException] { return 'Absent' }
        catch { }
        throw 'the path is held open or inaccessible'
    }
    $stream = $null
    try {
        $stream = New-Object System.IO.FileStream($handle, [System.IO.FileAccess]::Read)
        if ([TpmSupportNativeMethods]::PatchFileIdentity($handle) -cne $ExpectedIdentity) { throw 'the path now holds a different file' }
        if ($null -ne $ExpectedLastWriteTimeUtc -and [TpmSupportNativeMethods]::PatchWriteTimeUtc($handle) -ne ([datetime]$ExpectedLastWriteTimeUtc).ToFileTimeUtc()) { throw 'the file was rewritten after promotion' }
        if (-not [string]::IsNullOrWhiteSpace($ExpectedSha256) -and (Get-FileHash -InputStream $stream -Algorithm SHA256 -ErrorAction Stop).Hash -ine $ExpectedSha256) { throw 'the file changed after promotion' }
        Remove-TpmSupportHandle -Handle $handle
    } finally {
        if ($null -ne $stream) { $stream.Dispose() } else { $handle.Dispose() }
    }
    return 'Removed'
}

function Remove-TpmTreeOwnedDirectory {
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][string]$ExpectedRoot, [string]$ExpectedIdentity)
    if (-not (Test-Path -LiteralPath $Path)) { return 'Absent' }
    $opened = Open-TpmSupportOwnedHandle -Path $Path -ExpectedRoot $ExpectedRoot
    try {
        if (-not $opened.IsDirectory) { throw 'the path now holds a file' }
        if ([string]::IsNullOrWhiteSpace($ExpectedIdentity) -or [TpmSupportNativeMethods]::PatchDirectoryIdentity($opened.Handle) -cne $ExpectedIdentity) { throw 'the directory is not the one this transaction created' }
        if ($null -ne (Get-ChildItem -LiteralPath $Path -Force -ErrorAction Stop | Select-Object -First 1)) { throw 'the directory contains entries this transaction did not create' }
        Remove-TpmSupportHandle -Handle $opened.Handle
    } finally { $opened.Handle.Dispose() }
    return 'Removed'
}

function Clear-TpmTreeReadOnly {
    param([Parameter(Mandatory)][string]$Path)
    $attributes = [int][System.IO.File]::GetAttributes($Path)
    if (($attributes -band 1) -eq 0) { return }
    $cleared = $attributes -band (-bnot 1)
    if ($cleared -eq 0) { $cleared = 0x80 }
    [System.IO.File]::SetAttributes($Path, [System.IO.FileAttributes]$cleared)
}

function Set-TpmTreeFileMetadata {
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][int]$Attributes, [Parameter(Mandatory)][datetime]$LastWriteUtc)
    Clear-TpmTreeReadOnly -Path $Path
    [System.IO.File]::SetLastWriteTimeUtc($Path, $LastWriteUtc)
    [System.IO.File]::SetAttributes($Path, $(if ($Attributes -eq 0) { [System.IO.FileAttributes]::Normal } else { [System.IO.FileAttributes]$Attributes }))
}

# Create (exclusive) or Replace (identity- and content-bound) one file. OnOwned
# runs once ownership is proven and before any byte of the destination changes.
# If a write fails after ownership, OnPartial receives the SHA-256 of whatever the
# still-exclusive handle holds (or $null if unreadable) before the handle is released.
function Write-TpmTreeFile {
    param(
        [Parameter(Mandatory)][string]$Source, [Parameter(Mandatory)][string]$Destination,
        [Parameter(Mandatory)][ValidateSet('Create','Replace')][string]$Mode,
        [string]$ExpectedIdentity, [string[]]$AllowedSha256 = @(), [scriptblock]$OnOwned, [scriptblock]$OnPartial
    )
    $null = Get-TpmSupportNativeType
    $sourceStream = $null; $targetStream = $null
    try {
        $sourceStream = New-Object System.IO.FileStream($Source, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
        $sourceSha = (Get-FileHash -InputStream $sourceStream -Algorithm SHA256 -ErrorAction Stop).Hash
        $sourceStream.Position = 0
        if ($Mode -eq 'Create') {
            $targetStream = New-Object System.IO.FileStream($Destination, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)
            $identity = [TpmSupportNativeMethods]::PatchFileIdentity($targetStream.SafeFileHandle)
        } else {
            $targetStream = New-Object System.IO.FileStream($Destination, [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)
            $identity = [TpmSupportNativeMethods]::PatchFileIdentity($targetStream.SafeFileHandle)
            if ($identity -cne $ExpectedIdentity) { throw "destination is no longer the recorded file and was not overwritten: $Destination" }
            $liveSha = (Get-FileHash -InputStream $targetStream -Algorithm SHA256 -ErrorAction Stop).Hash
            $targetStream.Position = 0
            if ($AllowedSha256 -notcontains $liveSha) { throw "destination bytes changed concurrently and were not overwritten: $Destination" }
        }
        try {
            if ($null -ne $OnOwned) { & $OnOwned $identity }
            if ($Mode -eq 'Replace') { $targetStream.SetLength(0) }
            $sourceStream.CopyTo($targetStream)
            $targetStream.Flush($true)
            $targetStream.Position = 0
            if ((Get-FileHash -InputStream $targetStream -Algorithm SHA256 -ErrorAction Stop).Hash -ine $sourceSha) { throw "written bytes failed verification: $Destination" }
        } catch {
            $writeFailure = $_
            $partialSha = $null
            try { $targetStream.Flush($true); $targetStream.Position = 0; $partialSha = (Get-FileHash -InputStream $targetStream -Algorithm SHA256 -ErrorAction Stop).Hash } catch { $partialSha = $null }
            if ($null -ne $OnPartial) { try { & $OnPartial $partialSha } catch { } }
            throw $writeFailure
        }
        return [pscustomobject]@{ Identity = $identity; Sha256 = $sourceSha }
    } finally {
        if ($null -ne $targetStream) { $targetStream.Dispose() }
        if ($null -ne $sourceStream) { $sourceStream.Dispose() }
    }
}

function Invoke-TpmTransactionalTreePromote {
    param(
        [Parameter(Mandatory)][string]$StagingDir,
        [Parameter(Mandatory)][string]$DestDir,
        [Parameter(Mandatory)][string[]]$RelativeFiles,
        [scriptblock]$ValidationScript = $null
    )
    $rollbackDir = Join-Path $StagingDir '.tpm-rollback-backup'
    $originals = New-Object System.Collections.Generic.List[object]
    $originalMap = @{}
    $promoted = New-Object System.Collections.Generic.List[string]
    $journal = @{}
    $createdDirs = New-Object System.Collections.Generic.List[object]
    $orderedRelativeFiles = @($RelativeFiles | Sort-Object)
    $progressStarted = Get-Date
    $activeProgressPhase = 'Checking'
    $activeProgressLabel = $null
    $activeProgressCurrent = 0
    $activeProgressTotal = 0
    $destFull = [System.IO.Path]::GetFullPath($DestDir).TrimEnd('\','/')
    try {
        if (-not (Test-Path -LiteralPath $DestDir -PathType Container)) { throw 'BepInEx destination directory is missing.' }
        [void][System.IO.Directory]::CreateDirectory($rollbackDir)
        $seen = @{}
        $activeProgressPhase = 'Checking'
        $activeProgressLabel = 'BepInEx destination preflight'
        $activeProgressCurrent = 0
        $activeProgressTotal = $orderedRelativeFiles.Count
        foreach ($relative in $orderedRelativeFiles) {
            $activeProgressCurrent++
            Write-TpmCompactExtractionProgress -Phase $activeProgressPhase -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $progressStarted
            if ([string]::IsNullOrWhiteSpace($relative) -or [System.IO.Path]::IsPathRooted($relative) -or $relative -match '(^|[\/])\.\.([\/]|$)') { throw 'BepInEx transaction received an unsafe relative path.' }
            $source = Join-Path $StagingDir $relative
            $destination = Join-Path $DestDir $relative
            if (-not (Test-PathInside -child $source -parent $StagingDir) -or -not (Test-PathInside -child $destination -parent $DestDir)) { throw 'BepInEx transaction path escaped its approved directory.' }
            if (-not (Test-Path -LiteralPath $source -PathType Leaf)) { throw "BepInEx staged file is missing: $relative" }
            $key = $relative.ToLowerInvariant()
            if ($seen.ContainsKey($key)) { throw 'BepInEx transaction received duplicate paths.' }
            $seen[$key] = $true
            if (-not (Test-BepInExNoReparsePath -Root $DestDir -Path $destination)) { throw "BepInEx destination path is unsafe: $relative" }
            $destinationState = Get-TpmTreeFileState -Path $destination
            if ($destinationState.Kind -eq 'Other') { throw "BepInEx was not installed because '$relative' already exists in the game folder and cannot be replaced safely: $($destinationState.Reason)." }
            if ($destinationState.Kind -eq 'File') {
                $rollbackFile = Join-Path $rollbackDir $relative
                [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($rollbackFile))
                Copy-Item -LiteralPath $destination -Destination $rollbackFile -Force -ErrorAction Stop
                $backupState = Get-TpmTreeFileState -Path $rollbackFile
                if ($backupState.Kind -ne 'File' -or $backupState.Sha256 -ine $destinationState.Sha256) { throw "BepInEx rollback capture failed: $relative" }
                $original = [pscustomobject]@{ Relative = $relative; Backup = $rollbackFile; Identity = $destinationState.Identity; Sha256 = $destinationState.Sha256; Attributes = [int]$destinationState.Attributes; LastWriteUtc = (Get-Item -LiteralPath $destination -Force -ErrorAction Stop).LastWriteTimeUtc }
                [void]$originals.Add($original)
                $originalMap[$key] = $original
            }
        }
        if ($activeProgressTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase $activeProgressPhase -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $progressStarted -Complete }
        $activeProgressLabel = $null
        $activeProgressPhase = 'Repairing'
        $activeProgressLabel = 'BepInEx file promotion'
        $activeProgressCurrent = 0
        $activeProgressTotal = $orderedRelativeFiles.Count
        Write-Log "BepInEx destination resolution: game root '$DestDir' resolved to '$destFull'."
        foreach ($relative in $orderedRelativeFiles) {
            $activeProgressCurrent++
            Write-TpmCompactExtractionProgress -Phase $activeProgressPhase -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $progressStarted
            $source = Join-Path $StagingDir $relative
            $destination = Join-Path $DestDir $relative
            $parent = [System.IO.Path]::GetDirectoryName($destination)
            $resolvedParent = [System.IO.Path]::GetFullPath($parent)
            Write-Log "BepInEx destination verification: '$relative' parent '$parent' resolved to '$resolvedParent'."
            if (-not (Test-PathInside -child $resolvedParent -parent $destFull)) {
                throw "BepInEx destination resolution/verification failed: resolved destination parent '$resolvedParent' is outside resolved game root '$destFull' for '$relative'."
            }
            $missing = New-Object System.Collections.Generic.List[string]
            $cursor = $resolvedParent
            while ($cursor -and $cursor -ine $destFull -and -not (Test-Path -LiteralPath $cursor -PathType Container)) {
                [void]$missing.Add($cursor)
                $cursor = [System.IO.Path]::GetDirectoryName($cursor)
            }
            if (-not $cursor -or -not (Test-PathInside -child $cursor -parent $destFull)) {
                throw "BepInEx destination resolution/verification failed: existing ancestor for '$relative' is outside resolved game root '$destFull'."
            }
            # Exclusive creation: an existing or concurrently created directory is never adopted.
            for ($i = $missing.Count - 1; $i -ge 0; $i--) {
                $dirLocks = New-Object System.Collections.Generic.List[System.IDisposable]
                try {
                    $parentHandle = Add-BepInExRecoveryDirectoryLock -Path ([System.IO.Path]::GetDirectoryName($missing[$i])) -Locks $dirLocks
                    $dirHandle = [TpmSupportNativeMethods]::RecoveryCreateDirectory($parentHandle, [System.IO.Path]::GetFileName($missing[$i]))
                    [void]$dirLocks.Add($dirHandle)
                    [void]$createdDirs.Add([pscustomobject]@{ Path = $missing[$i]; Identity = [TpmSupportNativeMethods]::PatchDirectoryIdentity($dirHandle) })
                } finally {
                    for ($d = $dirLocks.Count - 1; $d -ge 0; $d--) { $dirLocks[$d].Dispose() }
                }
            }
            $key = $relative.ToLowerInvariant()
            $entry = [pscustomobject]@{ Relative = $relative; Path = $destination; Replaced = $originalMap.ContainsKey($key); Identity = $null; ExpectedSha256 = $null; PartialSha256 = $null; InFlight = $true }
            $onOwned = { param($identity) $entry.Identity = $identity; $journal[$relative] = $entry; [void]$promoted.Add($relative) }.GetNewClosure()
            $onPartial = { param($partialSha) $entry.PartialSha256 = $partialSha }.GetNewClosure()
            if ($entry.Replaced) {
                $original = $originalMap[$key]
                Clear-TpmTreeReadOnly -Path $destination
                $written = Write-TpmTreeFile -Source $source -Destination $destination -Mode Replace -ExpectedIdentity $original.Identity -AllowedSha256 @($original.Sha256) -OnOwned $onOwned -OnPartial $onPartial
            } else {
                $written = Write-TpmTreeFile -Source $source -Destination $destination -Mode Create -OnOwned $onOwned -OnPartial $onPartial
            }
            $entry.ExpectedSha256 = $written.Sha256
            $entry.InFlight = $false
            if (-not (Test-BepInExFileMatch -Source $source -Destination $destination)) { throw "BepInEx promoted file verification failed: $relative" }
        }
        if ($activeProgressTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase $activeProgressPhase -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $progressStarted -Complete }
        $activeProgressLabel = $null
        if ($ValidationScript) {
            # Post-promotion validation is its own final stage; the promotion stage above does not imply the install was verified.
            $activeProgressPhase = 'Checking'
            $activeProgressLabel = 'BepInEx post-promotion validation'
            $activeProgressCurrent = 1
            $activeProgressTotal = 1
            Write-TpmCompactExtractionProgress -Phase $activeProgressPhase -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $progressStarted
            if (-not [bool](& $ValidationScript)) { throw 'BepInEx post-promotion validation failed.' }
            Write-TpmCompactExtractionProgress -Phase $activeProgressPhase -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $progressStarted -Complete
            $activeProgressLabel = $null
        }
    } catch {
        if ($activeProgressLabel) {
            Write-TpmCompactExtractionProgress -Phase $activeProgressPhase -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $progressStarted -Complete -Outcome Error
            $activeProgressLabel = $null
        }
        $promotionError = $_
        $rollbackErrors = New-Object System.Collections.Generic.List[string]
        $activeProgressPhase = 'Repairing'
        $activeProgressLabel = 'BepInEx promoted-file rollback'
        $activeProgressCurrent = 0
        $activeProgressTotal = $promoted.Count
        # Reconcile against the journal: remove only outputs that are provably this
        # transaction's (identity and bytes); replaced originals are restored below.
        for ($i = $promoted.Count - 1; $i -ge 0; $i--) {
            $activeProgressCurrent++
            Write-TpmCompactExtractionProgress -Phase $activeProgressPhase -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $progressStarted
            $entry = $journal[$promoted[$i]]
            if ($entry.Replaced) { continue }
            try {
                $expectedOutputSha = if ($entry.InFlight) { [string]$entry.PartialSha256 } else { [string]$entry.ExpectedSha256 }
                if ([string]::IsNullOrWhiteSpace($expectedOutputSha)) { throw 'the bytes written before the failure were not recorded, so ownership of them is unproven' }
                [void](Remove-TpmTreeOwnedFile -Path $entry.Path -ExpectedIdentity $entry.Identity -ExpectedSha256 $expectedOutputSha)
            } catch { [void]$rollbackErrors.Add(("preserved '{0}' (not removed) -- {1}" -f $entry.Path, $_.Exception.Message)) }
        }
        if ($activeProgressTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase $activeProgressPhase -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $progressStarted -Complete -Outcome Error }
        $activeProgressLabel = 'BepInEx original-file restoration'
        $activeProgressCurrent = 0
        $activeProgressTotal = $originals.Count
        for ($i = $originals.Count - 1; $i -ge 0; $i--) {
            $activeProgressCurrent++
            Write-TpmCompactExtractionProgress -Phase $activeProgressPhase -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $progressStarted
            $original = $originals[$i]; $destination = Join-Path $DestDir $original.Relative
            try {
                $live = Get-TpmTreeFileState -Path $destination
                $ourEntry = $journal[$original.Relative]
                if ($live.Kind -eq 'File' -and $live.Sha256 -ieq $original.Sha256) {
                    # Pre-state bytes are present; only ordinary attributes may need repair.
                    if ($live.Identity -ceq $original.Identity -and [int]$live.Attributes -ne [int]$original.Attributes) {
                        Set-TpmTreeFileMetadata -Path $destination -Attributes $original.Attributes -LastWriteUtc $original.LastWriteUtc
                    }
                } elseif ($live.Kind -eq 'File' -and $null -ne $ourEntry -and $live.Identity -ceq $original.Identity -and $live.Sha256 -ieq $(if ($ourEntry.InFlight) { [string]$ourEntry.PartialSha256 } else { [string]$ourEntry.ExpectedSha256 })) {
                    [void](Write-TpmTreeFile -Source $original.Backup -Destination $destination -Mode Replace -ExpectedIdentity $original.Identity -AllowedSha256 @($live.Sha256))
                    Set-TpmTreeFileMetadata -Path $destination -Attributes $original.Attributes -LastWriteUtc $original.LastWriteUtc
                } elseif ($live.Kind -eq 'Absent') {
                    [void](Write-TpmTreeFile -Source $original.Backup -Destination $destination -Mode Create)
                    Set-TpmTreeFileMetadata -Path $destination -Attributes $original.Attributes -LastWriteUtc $original.LastWriteUtc
                } else {
                    throw 'the live file is neither the recorded original nor this transaction''s verified output; it was preserved'
                }
                if (-not (Test-BepInExFileMatch -Source $original.Backup -Destination $destination)) { throw 'restored hash mismatch' }
            } catch { [void]$rollbackErrors.Add(("restore '{0}' -- {1}: {2}" -f $destination, $_.Exception.GetType().FullName, $_.Exception.Message)) }
        }
        if ($activeProgressTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase $activeProgressPhase -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $progressStarted -Complete -Outcome Error }
        $activeProgressLabel = 'BepInEx created-directory rollback'
        $activeProgressCurrent = 0
        $activeProgressTotal = $createdDirs.Count
        for ($i = $createdDirs.Count - 1; $i -ge 0; $i--) {
            $activeProgressCurrent++
            Write-TpmCompactExtractionProgress -Phase $activeProgressPhase -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $progressStarted
            try {
                [void](Remove-TpmTreeOwnedDirectory -Path $createdDirs[$i].Path -ExpectedRoot $destFull -ExpectedIdentity $createdDirs[$i].Identity)
            } catch { [void]$rollbackErrors.Add(("preserved created directory '{0}' (not removed) -- {1}" -f $createdDirs[$i].Path, $_.Exception.Message)) }
        }
        if ($activeProgressTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase $activeProgressPhase -Label $activeProgressLabel -Current $activeProgressCurrent -Total $activeProgressTotal -StartedAt $progressStarted -Complete -Outcome Error }
        $activeProgressLabel = $null
        if ($rollbackErrors.Count -eq 0) {
            # Verified only when every recorded original matches and every transaction-created path is gone.
            foreach ($original in $originals) {
                $live = Get-TpmTreeFileState -Path (Join-Path $DestDir $original.Relative)
                if ($live.Kind -ne 'File' -or $live.Sha256 -ine $original.Sha256 -or [int]$live.Attributes -ne [int]$original.Attributes) { [void]$rollbackErrors.Add(("post-rollback verification failed for '{0}'" -f $original.Relative)) }
            }
            foreach ($entry in @($journal.Values)) {
                if (-not $entry.Replaced -and (Get-TpmTreeFileState -Path $entry.Path).Kind -ne 'Absent') { [void]$rollbackErrors.Add(("post-rollback verification failed: transaction-created '{0}' remains" -f $entry.Path)) }
            }
            foreach ($createdDir in $createdDirs) {
                if (Test-Path -LiteralPath $createdDir.Path) { [void]$rollbackErrors.Add(("post-rollback verification failed: transaction-created directory '{0}' remains" -f $createdDir.Path)) }
            }
        }
        if ($rollbackErrors.Count -gt 0) {
            $message = "TPM TRANSACTION ROLLBACK FAILED for '$DestDir'; evidence remains at '$rollbackDir'. Original error: $($promotionError.Exception.Message) | Preserved or unverified: $($rollbackErrors -join ' ;; ')"
            Write-Log "BepInEx: $message"
            throw $message
        }
        try { if (Test-Path -LiteralPath $rollbackDir) { Remove-Item -LiteralPath $rollbackDir -Recurse -Force -ErrorAction Stop } } catch {
            $message = "TPM TRANSACTION CLEANUP FAILED for '$DestDir'; evidence remains at '$rollbackDir'."
            Write-Log "BepInEx: $message"
            throw $message
        }
        Write-Log "BepInEx: rollback completed for '$DestDir'."
        throw $promotionError
    }
    try { if (Test-Path -LiteralPath $rollbackDir) { Remove-Item -LiteralPath $rollbackDir -Recurse -Force -ErrorAction Stop } } catch {
        $message = "TPM TRANSACTION CLEANUP FAILED AFTER VERIFIED PROMOTION for '$DestDir'; evidence remains at '$rollbackDir'."
        Write-Log "BepInEx: $message"
        throw $message
    }
    return $true
}

# Validates every inspectable game root before release query, prompt, download,
# backup, extraction, or promotion. Fresh installs and existing updates use
# stable x64 or x86 releases selected from the executable/installed shim.
function Get-BepInExRollbackReasonKey {
    param([Parameter(Mandatory)][string]$Operation, [Parameter(Mandatory)][string]$ExceptionType)
    return ('ROLLBACK_FAILED|{0}|{1}' -f $Operation, $ExceptionType)
}

function Test-BepInExRollbackBatchStop {
    param([object[]]$FailureRecords)
    $seen = @{}
    foreach ($record in @($FailureRecords)) {
        $key = [string]$record.ReasonKey
        # Only repeated ROLLBACK failures stop the batch; other repeated reasons (for example a missing game folder) do not.
        if ($key -notlike 'ROLLBACK_FAILED|*') { continue }
        if ($key -and $seen.ContainsKey($key)) { return $true }
        if ($key) { $seen[$key] = $true }
    }
    return $false
}

function Invoke-BepInExUpdateCheck {
    param([string]$UserProfilesDir,[string]$CacheDir,[string]$ApprovedGamesRoot='',[string[]]$ProtectedRoots=@())
    $pickedOut = New-Object System.Collections.Generic.List[string]
    $legacy=Invoke-BepInExUpdateCheckLegacy -UserProfilesDir $UserProfilesDir -CacheDir $CacheDir -ApprovedGamesRoot $ApprovedGamesRoot -ProtectedRoots $ProtectedRoots -PickedOut $pickedOut
    $items=@(Get-TpmTransactionField -Object $legacy -Name 'SelectedItems' -Default @())
    $changed=@(Get-TpmTransactionField -Object $legacy -Name 'ChangedItems' -Default @() | Where-Object { $_ -in $items } | Select-Object -Unique)
    $legacyReason=Get-TpmTransactionField -Object $legacy -Name 'Reason' -Default $null
    $failed=@(Get-TpmTransactionField -Object $legacy -Name 'FailedItems' -Default @() | Where-Object { $_ -in $items -and $_ -notin $changed } | Select-Object -Unique)
    $skipped=@(Get-TpmTransactionField -Object $legacy -Name 'SkippedItems' -Default @() | Where-Object { $_ -in $items -and $_ -notin $changed -and $_ -notin $failed } | Select-Object -Unique)
    $unattempted=@(Get-TpmTransactionField -Object $legacy -Name 'UnattemptedItems' -Default @() | Where-Object { $_ -in $items -and $_ -notin $changed -and $_ -notin $failed -and $_ -notin $skipped } | Select-Object -Unique)
    $completed=@(Get-TpmTransactionField -Object $legacy -Name 'CompletedItems' -Default @())
$completed=@(@($completed)+@($changed) | Where-Object { $_ -in $items -and $_ -notin $failed -and $_ -notin $skipped } | Select-Object -Unique)
    $rollbackUncertain=(@((Get-TpmTransactionField -Object $legacy -Name 'FailureRecords' -Default @()) | Where-Object { ([string](Get-TpmTransactionField -Object $_ -Name 'ReasonKey' -Default '')) -like 'ROLLBACK_FAILED|*' }).Count -gt 0)
    $cleanupRecords=@(
        (Get-TpmTransactionField -Object $legacy -Name 'FailureRecords' -Default @()) |
            Where-Object {
                (Get-TpmTransactionField -Object $_ -Name 'Operation' -Default '') -eq 'staging cleanup' -and
                [bool](Get-TpmTransactionField -Object $_ -Name 'EvidencePreserved' -Default $false)
            }
    )
    $cleanupPaths=@(
        $cleanupRecords |
            ForEach-Object { [string](Get-TpmTransactionField -Object $_ -Name 'StagingPath' -Default '') } |
            Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
            Select-Object -Unique
    )
    $cleanup=if($cleanupPaths.Count -gt 0) {
        [pscustomobject]@{ Attempted=$true; Completed=$false; ResiduePresent=$true; ResiduePaths=$cleanupPaths; ResidueItems=@(); Error='BepInEx staging cleanup failed.' }
    } else { $null }
    $cancelled=($legacyReason -eq 'DECLINED')
    $actionableSkip=($skipped.Count -gt 0 -and -not $cancelled)
    $outcome=if($rollbackUncertain){'ACTION_REQUIRED'}elseif($changed.Count -gt 0 -and ($failed.Count -gt 0 -or $actionableSkip -or $unattempted.Count -gt 0)){'PARTIAL_APPLIED'}elseif($changed.Count -gt 0){'SUCCEEDED'}elseif($failed.Count -gt 0){'FAILED_BEFORE_MUTATION'}elseif($actionableSkip){'ACTION_REQUIRED'}else{'NO_OP'}
    $productState=if($rollbackUncertain){'UNKNOWN'}else{switch($outcome){'SUCCEEDED'{'INTENDED'}'PARTIAL_APPLIED'{'PARTIAL_KNOWN'}default{'UNCHANGED'}}}
    $reasonCode=if($rollbackUncertain){'ROLLBACK_UNVERIFIED'}elseif($cleanupPaths.Count -gt 0){'CLEANUP_RESIDUE'}elseif($cancelled){'USER_CANCELLED'}elseif($outcome -eq 'ACTION_REQUIRED' -and $legacyReason){$legacyReason}elseif($outcome -eq 'ACTION_REQUIRED'){'SKIPPED_GAMES_REQUIRE_REVIEW'}elseif($outcome -eq 'NO_OP' -and $legacyReason){$legacyReason}elseif($outcome -eq 'NO_OP'){'NO_CHANGES_NEEDED'}elseif($outcome -eq 'FAILED_BEFORE_MUTATION' -and $legacyReason){$legacyReason}elseif($outcome -eq 'PARTIAL_APPLIED'){'PARTIAL_UPDATE'}elseif($outcome -eq 'FAILED_BEFORE_MUTATION'){'UPDATE_FAILED'}else{'UPDATES_PROCESSED'}
    $summary=if($cancelled){'BepInEx setup was canceled before any update was applied.'}elseif($rollbackUncertain){'BepInEx could not verify that a failed update was rolled back; game files may be inconsistent and need manual inspection.'}elseif($cleanupPaths.Count -gt 0){'BepInEx update processing completed with staging cleanup residue requiring attention.'}elseif($outcome -eq 'ACTION_REQUIRED'){'BepInEx left skipped games unchanged; review their reasons and next actions.'}elseif($outcome -eq 'NO_OP' -and $items.Count -eq 0){'No eligible BepInEx profiles were available; no files were changed.'}elseif($outcome -eq 'NO_OP'){'No BepInEx updates were needed for eligible profiles.'}elseif($outcome -eq 'PARTIAL_APPLIED'){'BepInEx was updated for some games; others were skipped, failed, or not attempted. Review the per-game reasons.'}elseif($outcome -eq 'FAILED_BEFORE_MUTATION'){'BepInEx could not be applied to the selected games; review the per-game reasons.'}else{'BepInEx updates were processed with a verified transaction result.'}
    $tx=ConvertTo-TpmLegacyTransactionResult -Legacy $legacy -WorkflowKey 'BepInEx' -OperationKey 'InstallOrUpdate' -Items $items -ChangedItems $changed -CompletedItems $completed -FailedItems $failed -SkippedItems $skipped -UnattemptedItems $unattempted -Summary $summary -ReasonCode $reasonCode -Outcome $outcome -ProductState $productState -Cleanup $cleanup -MutationStarted ($changed.Count -gt 0 -or $rollbackUncertain) -FinalPassed (-not $rollbackUncertain)
    if ($cancelled) { $tx | Add-Member -NotePropertyName Cancelled -NotePropertyValue $true -Force }
    if ($tx.PSObject.Properties.Name -notcontains 'Updated') { $tx | Add-Member -NotePropertyName Updated -NotePropertyValue 0 -Force }
    $tx | Add-Member -NotePropertyName Errors -NotePropertyValue ([int](Get-TpmTransactionField -Object $legacy -Name 'Errors' -Default 0)) -Force
    $tx | Add-Member -NotePropertyName PickedItems -NotePropertyValue @($pickedOut.ToArray()) -Force
    return $tx
}
function Invoke-BepInExUpdateCheckLegacy {
    # Owner rule R6: ProtectedRoots are the configured source collection folders; a game folder inside one is refused before anything is staged, backed up or written.
    param([string]$UserProfilesDir, [string]$CacheDir, [string]$ApprovedGamesRoot = '', [string[]]$ProtectedRoots = @(), [System.Collections.Generic.List[string]]$PickedOut = $null)
    if ([string]::IsNullOrWhiteSpace($ApprovedGamesRoot)) { $ApprovedGamesRoot = $gamesInstallFolder }
    $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'BepInEx profile discovery' -EnumerationErrorAction SilentlyContinue | Sort-Object Name)
    if ($profiles.Count -eq 0) { Write-Host '  No registered games found.' -ForegroundColor Yellow; Write-Log 'BepInEx update check: aborted -- no registered profiles.'; return [pscustomobject]@{ Succeeded=$true; Reason='NO_REGISTERED_GAMES'; Updated=0; Errors=0; MissingDevice=0; MissingPath=0; Protected=0; Skipped=0; UnsupportedArchitecture=0; UnknownArchitecture=0; PathReasonCounts=@{}; FailureRecords=@(); SelectedItems=@(); ChangedItems=@(); CompletedItems=@(); FailedItems=@(); SkippedItems=@(); UnattemptedItems=@(); BatchStopped=$false } }
    if (-not (Test-Path -LiteralPath $ApprovedGamesRoot -PathType Container -ErrorAction SilentlyContinue)) { Write-Host '  The configured games root could not be verified -- no BepInEx changes made.' -ForegroundColor Red; Write-Log "BepInEx update check: blocked because approved root is unavailable: $ApprovedGamesRoot"; $rootItems = @($profiles | ForEach-Object { [string]$_.BaseName }); $rootRecords = @($profiles | ForEach-Object { [pscustomobject]@{ Game=[string]$_.BaseName; GameLabel=[string]$_.BaseName; GameRoot='<unresolved>'; StagingPath=$null; BackupPath=$null; Operation='root safety preflight'; ReasonKey='APPROVED_ROOT_UNAVAILABLE'; Exception='The configured games root could not be verified.'; EvidencePreserved=$false; NextAction='Reconnect the games drive or correct the games folder setting, then run BepInEx setup again.' } }); return [pscustomobject]@{ Succeeded=$false; Reason='APPROVED_ROOT_UNAVAILABLE'; Updated=0; Errors=0; MissingDevice=0; MissingPath=0; Protected=0; Skipped=$rootItems.Count; UnsupportedArchitecture=0; UnknownArchitecture=0; PathReasonCounts=@{ 'APPROVED_ROOT_UNAVAILABLE' = $rootItems.Count }; FailureRecords=$rootRecords; SelectedItems=$rootItems; ChangedItems=@(); CompletedItems=@(); FailedItems=@(); SkippedItems=$rootItems; UnattemptedItems=@(); BatchStopped=$false } }
    $candidates = New-Object System.Collections.Generic.List[object]
    $failureRecords = New-Object System.Collections.Generic.List[object]
    $selectedItems = New-Object System.Collections.Generic.List[string]
    $changedItems = New-Object System.Collections.Generic.List[string]
    $failedItems = New-Object System.Collections.Generic.List[string]
    $skippedItems = New-Object System.Collections.Generic.List[string]
    $safetyBlocked = $false
    $missingDevice = 0
    $missingPath = 0
    $protected = 0
    $pathReasonCounts = @{}
    $sourceFolderRefused = 0
    $pathProgressStarted = Get-Date
    $pathProgressCurrent = 0
    $pathProgressTotal = $profiles.Count
    foreach ($pf in $profiles) {
        $pathProgressCurrent++
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'BepInEx path preflight' -Current $pathProgressCurrent -Total $pathProgressTotal -StartedAt $pathProgressStarted
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) { continue }
            $gamePathNode = $doc.GameProfile.SelectSingleNode('GamePath')
            if (-not $gamePathNode -or [string]::IsNullOrWhiteSpace($gamePathNode.InnerText)) { continue }
            [void]$selectedItems.Add($pf.BaseName)
            $gamePath = $gamePathNode.InnerText.Trim()
            $pathCheck = Test-TpmGameMutationPath -GamePath $gamePath -RequireLeaf -ProtectedRoots $ProtectedRoots
            if (-not $pathCheck.Valid) {
                $reasonCode = [string]$pathCheck.ReasonCode
                if (-not $pathReasonCounts.ContainsKey($reasonCode)) { $pathReasonCounts[$reasonCode] = 0 }
                $pathReasonCounts[$reasonCode]++
                if ($reasonCode -eq 'DEVICE_UNAVAILABLE') { $missingDevice++ }
                if ($reasonCode -eq 'GAME_PATH_MISSING') { $missingPath++ }
                if ($reasonCode -eq 'SOURCE_COLLECTION') { $sourceFolderRefused++ }
                [void]$skippedItems.Add($pf.BaseName)
                $label = Get-BepInExGameLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName
                [void]$failureRecords.Add([pscustomobject]@{
                    Game = $pf.BaseName
                    GameLabel = $label
                    GameRoot = if ($pathCheck.GameDirectory) { [string]$pathCheck.GameDirectory } else { '<unresolved>' }
                    StagingPath = $null
                    BackupPath = $null
                    Operation = 'path preflight'
                    ReasonKey = $reasonCode
                    Exception = [string]$pathCheck.Reason
                    EvidencePreserved = $false
                    NextAction = if ($reasonCode -eq 'DEVICE_UNAVAILABLE') { 'Reconnect the drive or device, then run BepInEx setup again.' } elseif ($reasonCode -eq 'SOURCE_COLLECTION') { 'Move the game out of your source folder, or fix the game folder in its profile.' } else { 'Return to the main menu and choose 13) Library Health Check to repair saved game paths.' }
                })
                Write-Log ("BepInEx: skipped {0} during path preflight; reason={1}; detail={2}" -f $pf.BaseName, $reasonCode, $pathCheck.Reason)
                continue
            }
            $gamePath = [string]$pathCheck.ResolvedPath
            $exeDir = [string]$pathCheck.GameDirectory
            $label = Get-BepInExGameLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName
            if (-not (Test-BepInExGameRootSafe -GameRoot $exeDir -ApprovedRoot $ApprovedGamesRoot) -or -not (Test-BepInExNoReparsePath -Root $exeDir -Path $gamePath)) {
                $protected++
                if (-not $pathReasonCounts.ContainsKey('PROTECTED_OR_REPARSE_ROOT')) { $pathReasonCounts['PROTECTED_OR_REPARSE_ROOT'] = 0 }
                $pathReasonCounts['PROTECTED_OR_REPARSE_ROOT']++
                [void]$skippedItems.Add($pf.BaseName)
                Write-BepInExUnsafeRootGuidance -GameCode $pf.BaseName -GameLabel $label -ApprovedRoot $ApprovedGamesRoot
                [void]$failureRecords.Add([pscustomobject]@{
                    Game = $pf.BaseName
                    GameLabel = $label
                    GameRoot = $exeDir
                    StagingPath = $null
                    BackupPath = $null
                    Operation = 'root safety preflight'
                    ReasonKey = 'PROTECTED_OR_REPARSE_ROOT'
                    Exception = 'The resolved game root or an existing path component could not be verified as safe.'
                    EvidencePreserved = $false
                    NextAction = 'Move the game under the approved games root or remove the unsafe path condition, then run BepInEx setup again.'
                })
                continue
            }
            [void]$candidates.Add([pscustomobject]@{ Code = $pf.BaseName; Label = $label; ExeDir = $exeDir; GamePath = $gamePath; ProfilePath = $pf.FullName })
        } catch {
            $safetyBlocked = $true
            [void]$skippedItems.Add($pf.BaseName)
            $label = Get-BepInExGameLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName
            Write-BepInExUnsafeRootGuidance -GameCode $pf.BaseName -GameLabel $label -ApprovedRoot $ApprovedGamesRoot -Reason 'the game root could not be verified'
            [void]$failureRecords.Add([pscustomobject]@{
                Game = $pf.BaseName
                GameLabel = $label
                GameRoot = '<unresolved>'
                StagingPath = $null
                BackupPath = $null
                Operation = 'root safety preflight'
                ReasonKey = 'ROOT_VERIFICATION_FAILED'
                Exception = $_.Exception.Message
                EvidencePreserved = $false
                NextAction = 'Verify the saved game path and approved games root, then run BepInEx setup again.'
            })
        }
    }
    if ($pathProgressTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'BepInEx path preflight' -Current $pathProgressCurrent -Total $pathProgressTotal -StartedAt $pathProgressStarted -Complete }
    Write-TpmSourceFolderRefusal -Count $sourceFolderRefused
    Write-Log ('BepInEx ' + (Format-TpmBepInExPreflightText -Eligible $candidates.Count -MissingDevice $missingDevice -MissingPath $missingPath -Protected $protected -Other ([Math]::Max(0, $skippedItems.Count - $missingDevice - $missingPath - $protected))))
    if ($candidates.Count -eq 0) {
        Write-Host '  No eligible BepInEx game folders remain. Nothing was changed.' -ForegroundColor Yellow
        return [pscustomobject]@{ Succeeded = ($missingDevice -eq 0 -and $missingPath -eq 0 -and $protected -eq 0 -and $skippedItems.Count -eq 0 -and -not $safetyBlocked); Updated = 0; Errors = 0; MissingDevice = $missingDevice; MissingPath = $missingPath; Protected = $protected; Skipped=$skippedItems.Count; UnsupportedArchitecture=0; UnknownArchitecture=0; Reason = 'NO_ELIGIBLE_GAMES'; PathReasonCounts = $pathReasonCounts; FailureRecords = @($failureRecords.ToArray()); SelectedItems = @($selectedItems.ToArray()); ChangedItems = @(); CompletedItems=@(); FailedItems = @($failedItems.ToArray()); SkippedItems = @($skippedItems.ToArray()); UnattemptedItems=@(); BatchStopped = $false }
    }

    Write-Host ''
    Write-Host '  Checking stable BepInEx releases for the detected game architectures...' -ForegroundColor DarkGray
    $latestByArch = @{}
    $requiredArchitectureByCode = @{}
    $architectureEvidenceByCode = @{}
    $unsupportedArchitecture = 0
    $unknownArchitecture = 0
    $requiredArchitectures = @($candidates | ForEach-Object {
        $exeEvidence = Get-BepInExPeArchitectureEvidence -Path $_.GamePath
        if ($exeEvidence.State -eq 'UNSUPPORTED') {
            $architectureEvidenceByCode[[string]$_.Code] = [pscustomobject]@{ ExeEvidence=$exeEvidence; InstalledEvidence=$null; ArchitectureHint=$null }
            $null
        } else {
            $installedEvidence = Get-BepInExPeArchitectureEvidence -Path (Join-Path $_.ExeDir 'winhttp.dll')
            $installedArch = [string]$installedEvidence.Architecture
            $exeArch = [string]$exeEvidence.Architecture
            $architectureHint = if ($installedArch -in @('x64','x86') -and ($exeArch -notin @('x64','x86') -or $exeArch -eq $installedArch)) { $installedArch } else { $exeArch }
            $architectureEvidenceByCode[[string]$_.Code] = [pscustomobject]@{ ExeEvidence=$exeEvidence; InstalledEvidence=$installedEvidence; ArchitectureHint=$architectureHint }
            if ($architectureHint -in @('x64','x86')) { $requiredArchitectureByCode[[string]$_.Code] = $architectureHint; $architectureHint } else { $null }
        }
    } | Where-Object { $_ -in @('x64','x86') } | Sort-Object -Unique)
    foreach ($architecture in $requiredArchitectures) {
        $latestByArch[$architecture] = Get-BepInExLatestRelease -Architecture $architecture
        if (-not $latestByArch[$architecture]) {
            $affected = @($candidates | Where-Object { $requiredArchitectureByCode[[string]$_.Code] -eq $architecture })
            foreach ($candidate in $affected) {
                if ($candidate.Code -notin $failedItems) { [void]$failedItems.Add([string]$candidate.Code) }
                [void]$failureRecords.Add([pscustomobject]@{ Game=$candidate.Code; GameLabel=$candidate.Label; GameRoot=$candidate.ExeDir; StagingPath=$null; BackupPath=$null; Operation='release query'; ReasonKey='RELEASE_QUERY_FAILED'; Exception="The stable $architecture BepInEx release could not be reached."; EvidencePreserved=$false; NextAction='Check the connection, then run BepInEx setup again when GitHub is available.' })
            }
            foreach ($candidate in @($candidates | Where-Object { -not $requiredArchitectureByCode.ContainsKey([string]$_.Code) })) {
                $evidence = $architectureEvidenceByCode[[string]$candidate.Code]
                $architectureState = if ($evidence.ExeEvidence.State -eq 'UNSUPPORTED') { 'UNSUPPORTED' } elseif ($evidence.ExeEvidence.State -eq 'UNREADABLE') { 'UNREADABLE' } else { 'UNKNOWN' }
                $classification = Get-BepInExInspectionFailure -ErrorRecord ([System.Exception]::new([string]$evidence.ExeEvidence.Reason)) -ArchitectureState $architectureState
                if ($architectureState -eq 'UNSUPPORTED') { $unsupportedArchitecture++ } else { $unknownArchitecture++ }
                if ($candidate.Code -notin $skippedItems) { [void]$skippedItems.Add([string]$candidate.Code) }
                if (-not $pathReasonCounts.ContainsKey($classification.Code)) { $pathReasonCounts[$classification.Code] = 0 }
                $pathReasonCounts[$classification.Code]++
                [void]$failureRecords.Add([pscustomobject]@{ Game=$candidate.Code; GameLabel=$candidate.Label; GameRoot=$candidate.ExeDir; StagingPath=$null; BackupPath=$null; Operation='inspection'; ReasonKey=$classification.Code; Exception=$classification.Technical; EvidencePreserved=$false; NextAction=$classification.NextAction })
                Write-Log ("BepInEx update check: architecture could not be selected for {0}; reason={1}; detail={2}" -f $candidate.Code, $classification.Code, $classification.Technical)
            }
            Write-Host ("  TeknoParrot Manager could not reach GitHub for the stable {0} BepInEx release. Nothing was changed." -f $architecture) -ForegroundColor Red
            Write-Host '  Check the connection, then choose Back or run this setup again when the connection is available.' -ForegroundColor Yellow
            Write-Log "BepInEx update check: release query failed for $architecture."
            $unattempted = @($candidates | Where-Object { $_.Code -notin $failedItems -and $_.Code -notin $skippedItems } | ForEach-Object { [string]$_.Code })
            return [pscustomobject]@{ Succeeded = $false; Reason = 'RELEASE_QUERY_FAILED'; Errors=1; MissingDevice=$missingDevice; MissingPath=$missingPath; Protected=$protected; Skipped=$skippedItems.Count; UnsupportedArchitecture=$unsupportedArchitecture; UnknownArchitecture=$unknownArchitecture; PathReasonCounts=$pathReasonCounts; FailureRecords=@($failureRecords.ToArray()); SelectedItems=@($selectedItems.ToArray()); ChangedItems=@(); CompletedItems=@(); FailedItems=@($failedItems.ToArray()); SkippedItems=@($skippedItems.ToArray()); UnattemptedItems=$unattempted; BatchStopped=$false }
        }
    }
    $outdated = New-Object System.Collections.Generic.List[object]
    $upToDate = 0; $upToDateItems = New-Object System.Collections.Generic.List[string]; $errors = 0
    $inspectionProgressStarted = Get-Date
    $inspectionProgressCurrent = 0
    $inspectionProgressTotal = $candidates.Count
    foreach ($candidate in $candidates) {
        $inspectionProgressCurrent++
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'BepInEx installation inspection' -Current $inspectionProgressCurrent -Total $inspectionProgressTotal -StartedAt $inspectionProgressStarted
        try {
            $health = Get-BepInExInstallationHealth -ExeDir $candidate.ExeDir
            $installedVer = $health.Version
            $exeEvidence = Get-BepInExPeArchitectureEvidence -Path $candidate.GamePath
            $installedEvidence = Get-BepInExPeArchitectureEvidence -Path (Join-Path $candidate.ExeDir 'winhttp.dll')
            $installedArch = [string]$installedEvidence.Architecture
            $exeArch = [string]$exeEvidence.Architecture
            if ($exeEvidence.State -eq 'UNSUPPORTED') {
                $classification = Get-BepInExInspectionFailure -ErrorRecord ([System.Exception]::new($exeEvidence.Reason)) -ArchitectureState 'UNSUPPORTED'
                $unsupportedArchitecture++
                [void]$skippedItems.Add($candidate.Code)
                if (-not $pathReasonCounts.ContainsKey($classification.Code)) { $pathReasonCounts[$classification.Code] = 0 }
                $pathReasonCounts[$classification.Code]++
                [void]$failureRecords.Add([pscustomobject]@{ Game=$candidate.Code; GameLabel=$candidate.Label; GameRoot=$candidate.ExeDir; Operation='inspection'; ReasonKey=$classification.Code; Exception=$classification.Technical; EvidencePreserved=$false; NextAction=$classification.NextAction })
                Write-Log ("BepInEx update check: inspection skipped for {0}; reason={1}; detail={2}" -f $candidate.Code, $classification.Code, $classification.Technical)
                continue
            }
            if ($exeArch -in @('x64','x86') -and $installedArch -in @('x64','x86') -and $installedArch -ne $exeArch) {
                [void]$outdated.Add([pscustomobject]@{ Code = $candidate.Code; Label = $candidate.Label; ExeDir = $candidate.ExeDir; GamePath = $candidate.GamePath; Installed = $installedVer; Architecture = $exeArch; Latest = $latestByArch[$exeArch] })
                continue
            }
            $arch = if ($installedArch -in @('x64','x86') -and ($exeArch -notin @('x64','x86') -or $exeArch -eq $installedArch)) { $installedArch } else { $exeArch }
            if ($arch -notin @('x64','x86')) {
                $classification = Get-BepInExInspectionFailure -ErrorRecord ([System.Exception]::new($exeEvidence.Reason)) -ArchitectureState $(if ($exeEvidence.State -eq 'UNREADABLE') { 'UNREADABLE' } else { 'UNKNOWN' })
                $unknownArchitecture++
                [void]$skippedItems.Add($candidate.Code)
                if (-not $pathReasonCounts.ContainsKey($classification.Code)) { $pathReasonCounts[$classification.Code] = 0 }
                $pathReasonCounts[$classification.Code]++
                [void]$failureRecords.Add([pscustomobject]@{ Game=$candidate.Code; GameLabel=$candidate.Label; GameRoot=$candidate.ExeDir; Operation='inspection'; ReasonKey=$classification.Code; Exception=$classification.Technical; EvidencePreserved=$false; NextAction=$classification.NextAction })
                Write-Log ("BepInEx update check: inspection skipped for {0}; reason={1}; detail={2}" -f $candidate.Code, $classification.Code, $classification.Technical)
                continue
            }
            $latest = $latestByArch[$arch]
            if (-not $latest) { continue }
            if (-not $health.Installed) {
                [void]$outdated.Add([pscustomobject]@{ Code = $candidate.Code; Label = $candidate.Label; ExeDir = $candidate.ExeDir; GamePath = $candidate.GamePath; Installed = 'Not installed'; Architecture = $arch; Latest = $latest })
                continue
            }
            if (-not $health.Complete) {
                [void]$outdated.Add([pscustomobject]@{ Code = $candidate.Code; Label = $candidate.Label; ExeDir = $candidate.ExeDir; GamePath = $candidate.GamePath; Installed = 'Broken (' + $health.Reason + ')'; Architecture = $arch; Latest = $latest })
                continue
            }
            $instParsed = $null; $latestParsed = $null
            if (-not [version]::TryParse($installedVer, [ref]$instParsed) -or -not [version]::TryParse($latest.Version, [ref]$latestParsed)) {
                throw "BepInEx version could not be parsed (installed='$installedVer', latest='$($latest.Version)')."
            }
            if ($instParsed -lt $latestParsed) {
                [void]$outdated.Add([pscustomobject]@{ Code = $candidate.Code; Label = $candidate.Label; ExeDir = $candidate.ExeDir; GamePath = $candidate.GamePath; Installed = $installedVer; Architecture = $arch; Latest = $latest })
            } else { $upToDate++; [void]$upToDateItems.Add([string]$candidate.Code) }
        } catch {
            $classification = Get-BepInExInspectionFailure -ErrorRecord $_
            $errors++
            [void]$failedItems.Add($candidate.Code)
            if (-not $pathReasonCounts.ContainsKey($classification.Code)) { $pathReasonCounts[$classification.Code] = 0 }
            $pathReasonCounts[$classification.Code]++
            [void]$failureRecords.Add([pscustomobject]@{ Game=$candidate.Code; GameLabel=$candidate.Label; GameRoot=$candidate.ExeDir; Operation='inspection'; ReasonKey=$classification.Code; Exception=$classification.Technical; EvidencePreserved=$false; NextAction=$classification.NextAction })
            Write-Host ("  ERROR {0} -- {1}" -f $candidate.Label, $classification.Summary) -ForegroundColor Red
            Write-Host ("          Next safe action: {0}" -f $classification.NextAction) -ForegroundColor Yellow
            Write-Log ("BepInEx update check: inspection failed for {0}; reason={1}; detail={2}" -f $candidate.Code, $classification.Code, $classification.Technical)
        }
    }
    if ($inspectionProgressTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'BepInEx installation inspection' -Current $inspectionProgressCurrent -Total $inspectionProgressTotal -StartedAt $inspectionProgressStarted -Complete }
    # Only a few games need BepInEx. A game that has none is never offered in the bulk question below; the user has to pick it.
    $offeredCount = $outdated.Count
    $freshGames = @($outdated | Where-Object { [string]$_.Installed -eq 'Not installed' })
    $bulkOfferedCount = $outdated.Count - $freshGames.Count
    if ($freshGames.Count -gt 0) {
        foreach ($freshGame in $freshGames) { [void]$outdated.Remove($freshGame) }
        Write-Host ("  {0} game(s) do not have BepInEx. Only a few games need it, so they are left alone unless you pick them." -f $freshGames.Count) -ForegroundColor Cyan
        $freshSorted = @($freshGames | Sort-Object Label)
        $freshRows = @($freshSorted | ForEach-Object { '{0} ({1})' -f $_.Label, $_.Architecture })
        foreach ($freshIndex in @(Read-TpmMultiGameChoice -Rows $freshRows -Heading 'Games without BepInEx:' -Prompt '  Type the numbers of the games to add BepInEx to (like 1,3,6 or 1-8), A for all, or B for none')) {
            [void]$outdated.Add($freshSorted[[int]$freshIndex])
            Write-Log ("BepInEx update check: the user chose to install BepInEx for {0}." -f $freshSorted[[int]$freshIndex].Code)
        }
    }
    if ($null -ne $PickedOut) { foreach ($selectedGame in $outdated) { [void]$PickedOut.Add([string]$selectedGame.Code) } }
    if ($outdated.Count -eq 0) {
        Write-Host ("  Up to date: {0} game(s)" -f $upToDate) -ForegroundColor Green
        if ($unsupportedArchitecture -gt 0) { Write-Host ("  Unsupported architecture: {0} game(s) -- left unchanged" -f $unsupportedArchitecture) -ForegroundColor Yellow }
        if ($unknownArchitecture -gt 0) { Write-Host ("  Unknown or unreadable architecture: {0} game(s) -- left unchanged" -f $unknownArchitecture) -ForegroundColor Yellow }
        if ($skippedItems.Count -gt 0) { Write-Host ("  Skipped: {0} game(s) -- review Details and next actions" -f $skippedItems.Count) -ForegroundColor Yellow }
        if ($errors -gt 0) { Write-Host ("  Inspection issues: {0} -- see Details or the support log" -f $errors) -ForegroundColor Red }
        return [pscustomobject]@{ Succeeded = ($errors -eq 0 -and $skippedItems.Count -eq 0); Reason = if ($errors) { 'INSPECTION_FAILED' } elseif ($skippedItems.Count -gt 0) { 'ACTION_REQUIRED' } else { $null }; Errors=$errors; MissingDevice=$missingDevice; MissingPath=$missingPath; FailureRecords = @($failureRecords.ToArray()); PathReasonCounts = $pathReasonCounts; Protected=$protected; Skipped=$skippedItems.Count; UnsupportedArchitecture = $unsupportedArchitecture; UnknownArchitecture=$unknownArchitecture; SelectedItems = @($selectedItems.ToArray()); ChangedItems = @(); CompletedItems=@($upToDateItems.ToArray()); FailedItems = @($failedItems.ToArray()); SkippedItems = @($skippedItems.ToArray()); UnattemptedItems=@(); BatchStopped = $false }
    }
    Write-Host ("  Selected: {0} of {1} games to install or update BepInEx:" -f $outdated.Count, $offeredCount) -ForegroundColor Cyan
    foreach ($o in @($outdated | Sort-Object Label)) { Write-Host ("    - {0}: {1} -> {2} ({3})" -f $o.Label, $o.Installed, $o.Latest.Version, $o.Architecture) -ForegroundColor DarkGray }
    # FIX110 (S-10): repair-reset is not offered; it was always refused after the download and staging.
    # Games the user picked by number were already approved by that pick; the question is asked only when out-of-date games were offered in bulk.
    $installChoice = if ($bulkOfferedCount -gt 0) { Read-TpmChoice -Prompt ("  [Y] Install/update  [B] Back  [N] Cancel  -- {0} game(s)" -f $outdated.Count) -Choices @('Y', 'B', 'N') -Default 'B' } else { 'Y' }
    if ($installChoice -ne 'Y') {
        Write-Log 'BepInEx update check: user selected Back or canceled installation/update.'
        return [pscustomobject]@{ Succeeded = $false; Reason = 'DECLINED'; Errors=$errors; MissingDevice=$missingDevice; MissingPath=$missingPath; Protected=$protected; Skipped=$skippedItems.Count; UnsupportedArchitecture=$unsupportedArchitecture; UnknownArchitecture=$unknownArchitecture; PathReasonCounts=$pathReasonCounts; SelectedItems = @($selectedItems.ToArray()); ChangedItems = @(); CompletedItems=@($upToDateItems.ToArray()); FailedItems = @($failedItems.ToArray()); SkippedItems = @($skippedItems.ToArray()); UnattemptedItems=@($outdated | ForEach-Object { [string]$_.Code }); FailureRecords = @($failureRecords.ToArray()); BatchStopped = $false }
    }
    [void][System.IO.Directory]::CreateDirectory($CacheDir)
    $zipByArch = @{}
    foreach ($architecture in @($outdated | Select-Object -ExpandProperty Architecture -Unique)) {
        $latest = $latestByArch[$architecture]
        $safeFileName = [System.IO.Path]::GetFileName($latest.FileName)
        $zipPath = Join-Path $CacheDir $safeFileName
        if ([string]::IsNullOrWhiteSpace($safeFileName) -or -not (Test-PathInside $zipPath $CacheDir)) {
            Write-Log "BepInEx update check: blocked on unsafe $architecture release filename."
            $errors++
            $affectedOutdated = @($outdated | Where-Object { $_.Architecture -eq $architecture })
            foreach ($game in $affectedOutdated) {
                if ($game.Code -notin $failedItems) { [void]$failedItems.Add([string]$game.Code) }
                [void]$failureRecords.Add([pscustomobject]@{ Game=$game.Code; GameLabel=$game.Label; GameRoot=$game.ExeDir; StagingPath=$null; BackupPath=$null; Operation='release filename validation'; ReasonKey='UNSAFE_RELEASE_FILENAME'; Exception='The stable release filename could not be safely used within the package cache.'; EvidencePreserved=$false; NextAction='Review the trusted release metadata and run BepInEx setup again after it is corrected.' })
            }
            $itemsForUpdate = @($candidates | ForEach-Object { [string]$_.Code })
            $unattempted = @($itemsForUpdate | Where-Object { $_ -notin $failedItems -and $_ -notin $skippedItems -and $_ -notin $upToDateItems })
            return [pscustomobject]@{ Succeeded = $false; Reason = 'UNSAFE_RELEASE_FILENAME'; Errors=$errors; MissingDevice=$missingDevice; MissingPath=$missingPath; Protected=$protected; Skipped=$skippedItems.Count; UnsupportedArchitecture=$unsupportedArchitecture; UnknownArchitecture=$unknownArchitecture; PathReasonCounts=$pathReasonCounts; FailureRecords=@($failureRecords.ToArray()); SelectedItems = @($selectedItems.ToArray()); ChangedItems = @(); CompletedItems=@($upToDateItems.ToArray()); FailedItems = @($failedItems.ToArray()); SkippedItems = @($skippedItems.ToArray()); UnattemptedItems=$unattempted; BatchStopped = $false }
        }
        if (-not (Invoke-TpmDownload -DownloadUrl $latest.DownloadUrl -DestinationPath $zipPath -ExpectedBytes $latest.SizeBytes -Label 'BepInEx' -Version $latest.Version -ExpectedSha256 $latest.ExpectedSha256)) {
            Write-Host ("  BepInEx {0}-bit download failed. Nothing was changed." -f ($(if ($architecture -eq 'x86') { '32' } else { '64' }))) -ForegroundColor Red
            Write-Host '  Choose this setup again to retry automatically, or cancel without changing the game.' -ForegroundColor Yellow
            Write-Log "BepInEx update check: download or digest verification failed for $architecture."
            $errors++
            $affectedOutdated = @($outdated | Where-Object { $_.Architecture -eq $architecture })
            foreach ($game in $affectedOutdated) {
                if ($game.Code -notin $failedItems) { [void]$failedItems.Add([string]$game.Code) }
                [void]$failureRecords.Add([pscustomobject]@{ Game=$game.Code; GameLabel=$game.Label; GameRoot=$game.ExeDir; StagingPath=$null; BackupPath=$null; Operation='package download'; ReasonKey='DOWNLOAD_FAILED'; Exception="The verified stable $architecture BepInEx package could not be acquired."; EvidencePreserved=$false; NextAction='Choose BepInEx setup again to retry the download, or return to the menu without changing the game.' })
            }
            $itemsForUpdate = @($candidates | ForEach-Object { [string]$_.Code })
            $unattempted = @($itemsForUpdate | Where-Object { $_ -notin $failedItems -and $_ -notin $skippedItems -and $_ -notin $upToDateItems })
            return [pscustomobject]@{ Succeeded = $false; Reason = 'DOWNLOAD_FAILED'; Errors=$errors; MissingDevice=$missingDevice; MissingPath=$missingPath; Protected=$protected; Skipped=$skippedItems.Count; UnsupportedArchitecture=$unsupportedArchitecture; UnknownArchitecture=$unknownArchitecture; PathReasonCounts=$pathReasonCounts; SelectedItems = @($selectedItems.ToArray()); ChangedItems = @(); CompletedItems=@($upToDateItems.ToArray()); FailedItems = @($failedItems.ToArray()); SkippedItems = @($skippedItems.ToArray()); UnattemptedItems=$unattempted; FailureRecords = @($failureRecords.ToArray()); BatchStopped = $false }
        }
        $zipByArch[$architecture] = $zipPath
    }
    $updated = 0; $updatedWithCleanupFailure = 0; $updateErrors = 0; $cleanupErrors = 0
    $batchStopped = $false
    $updateProgressStarted = Get-Date
    $updateProgressCurrent = 0
    $updateProgressTotal = $outdated.Count
    foreach ($o in @($outdated | Sort-Object Code)) {
        if ($batchStopped) { break }
        $updateProgressCurrent++
        Write-TpmCompactExtractionProgress -Phase Repairing -Label 'BepInEx game updates' -Current $updateProgressCurrent -Total $updateProgressTotal -StartedAt $updateProgressStarted
        $stagingDir = $null; $preserveStaging = $false; $promotionSucceeded = $false; $rollbackFailure = $false; $cleanupFailure = $false
        $backupPath = $null
        try {
            $boundaryCheck = Test-TpmGameMutationPath -GamePath $o.GamePath -RequireLeaf -ProtectedRoots $ProtectedRoots
            if (-not $boundaryCheck.Valid -or [string]$boundaryCheck.ResolvedPath -ine [string]$o.GamePath -or [string]$boundaryCheck.GameDirectory -ine [string]$o.ExeDir) { throw 'BepInEx mutation-boundary path identity changed before staging.' }
            if (-not (Test-BepInExGameRootSafe -GameRoot $o.ExeDir -ApprovedRoot $ApprovedGamesRoot) -or -not (Test-BepInExExistingTreeSafe -GameRoot $o.ExeDir)) { throw 'BepInEx final root safety check failed.' }
            $zipPathForGame = [string]$zipByArch[[string]$o.Architecture]
            if (-not (Test-BepInExPackagePathSafe -PackagePath $zipPathForGame -CacheRoot $CacheDir)) { throw 'BepInEx package path could not be safely resolved for this game architecture.' }
            $stagingDir = New-TpmStagingDirectory -Label 'BepInEx'
            Expand-ZipFileSafe -ZipPath $zipPathForGame -DestDir $stagingDir -GameName $o.Label
            $relativeFiles = @(Get-BepInExStagedFiles -StagingDir $stagingDir -DestDir $o.ExeDir)
            $boundaryCheck = Test-TpmGameMutationPath -GamePath $o.GamePath -RequireLeaf -ProtectedRoots $ProtectedRoots
            if (-not $boundaryCheck.Valid -or [string]$boundaryCheck.ResolvedPath -ine [string]$o.GamePath -or [string]$boundaryCheck.GameDirectory -ine [string]$o.ExeDir) { throw 'BepInEx mutation-boundary path identity changed before backup.' }
            if (-not (Test-BepInExGameRootSafe -GameRoot $o.ExeDir -ApprovedRoot $ApprovedGamesRoot) -or -not (Test-BepInExExistingTreeSafe -GameRoot $o.ExeDir)) { throw 'BepInEx root changed before backup.' }
            $backupPath = New-BepInExUpdateBackup -GameRoot $o.ExeDir
            if (-not (Test-BepInExGameRootSafe -GameRoot $o.ExeDir -ApprovedRoot $ApprovedGamesRoot) -or -not (Test-BepInExExistingTreeSafe -GameRoot $o.ExeDir)) { throw 'BepInEx root failed after backup.' }
            $boundaryCheck = Test-TpmGameMutationPath -GamePath $o.GamePath -RequireLeaf -ProtectedRoots $ProtectedRoots
            if (-not $boundaryCheck.Valid -or [string]$boundaryCheck.ResolvedPath -ine [string]$o.GamePath -or [string]$boundaryCheck.GameDirectory -ine [string]$o.ExeDir) { throw 'BepInEx mutation-boundary path identity changed before promotion.' }
            $validation = { $instNow = $null; $latestNow = $null; return ([version]::TryParse([string](Get-BepInExInstalledVersion -ExeDir $o.ExeDir), [ref]$instNow) -and [version]::TryParse([string]$o.Latest.Version, [ref]$latestNow) -and $instNow -ge $latestNow) }
            [void](Invoke-TpmTransactionalTreePromote -StagingDir $stagingDir -DestDir $o.ExeDir -RelativeFiles $relativeFiles -ValidationScript $validation)
            $promotionSucceeded = $true
            [void](Remove-BepInExStagingDirectory -StagingDir $stagingDir)
            # The update is verified, so the safety copy TPM made for this one update is no longer needed; a failure to remove it only costs disk space.
            if ($backupPath -and (Split-Path -Leaf $backupPath) -like 'BepInEx_Backup_*' -and (Split-Path -Parent $backupPath) -ieq [string]$o.ExeDir.TrimEnd('\','/')) {
                try { Remove-Item -LiteralPath $backupPath -Recurse -Force -ErrorAction Stop; $backupPath = $null } catch { Write-Log "BepInEx: could not remove the update safety copy $backupPath -- $($_.Exception.Message)" }
            }
            [void]$changedItems.Add($o.Code)
            Write-Host ("    OK    {0}  ({1} -> {2})" -f $o.Label, $o.Installed, $o.Latest.Version) -ForegroundColor Green
            Write-Log "BepInEx: updated $($o.Code) from $($o.Installed) to $($o.Latest.Version); safety copy: $(if ($backupPath) { $backupPath } else { 'removed after the update was verified' })"
            $updated++
        } catch {
            if ($promotionSucceeded -and $_.Exception.Message -match '^TPM BEPINEX STAGING CLEANUP (FAILED|REFUSED)') {
                [void]$changedItems.Add($o.Code)
                $preserveStaging = $true
                Write-Host ("    WARNING {0} -- update applied, but staging cleanup failed" -f $o.Label) -ForegroundColor Yellow
                Write-Host '            ACTION REQUIRED: inspect the preserved staging evidence before retrying.' -ForegroundColor Yellow
                Write-Log "BepInEx: update applied for $($o.Code), but staging cleanup failed; action required; residue=$stagingDir; backup=$backupPath"
                [void]$failureRecords.Add([pscustomobject]@{
                    Game = $o.Code
                    GameLabel = $o.Label
                    GameRoot = $o.ExeDir
                    StagingPath = $stagingDir
                    BackupPath = $backupPath
                    Operation = 'staging cleanup'
                    ReasonKey = 'CLEANUP_FAILED'
                    Exception = $_.Exception.Message
                    EvidencePreserved = $true
                    NextAction = 'Close TeknoParrot and remove the validated staging residue after confirming the game files are intact.'
                })
                $updatedWithCleanupFailure++
                $cleanupErrors++
            } else {
                $failureMessage = [string]$_.Exception.Message
                $failureCode = Get-TpmGameMutationFailureCode -ErrorRecord $_
                $rollbackFailure = $rollbackFailure -or ($failureMessage -match 'ROLLBACK FAILED')
                if ($rollbackFailure) {
                    $preserveStaging = $true
                    [void]$failedItems.Add($o.Code)
                    if (-not $pathReasonCounts.ContainsKey('ROLLBACK_FAILED')) { $pathReasonCounts['ROLLBACK_FAILED'] = 0 }
                    $pathReasonCounts['ROLLBACK_FAILED']++
                    $rollbackReasonKey = Get-BepInExRollbackReasonKey -Operation 'transaction rollback' -ExceptionType $_.Exception.GetType().FullName
                    [void]$failureRecords.Add([pscustomobject]@{
                        Game = $o.Code
                        GameRoot = $o.ExeDir
                        StagingPath = $stagingDir
                        BackupPath = $backupPath
                        Operation = 'transaction rollback'
                        ReasonKey = $rollbackReasonKey
                        Exception = $failureMessage
                        EvidencePreserved = $preserveStaging
                        NextAction = 'Do not retry blindly. Close TeknoParrot, preserve the backup/evidence paths, and have the game files manually inspected before any repair attempt.'
                    })
                    if (Test-BepInExRollbackBatchStop -FailureRecords $failureRecords.ToArray()) {
                        $batchStopped = $true
                        Write-Host '  Several games failed for the same safety reason, so TeknoParrot Manager stopped the batch.' -ForegroundColor Yellow
                    }
                    Write-Host ("    ERROR {0} -- transaction rollback could not be verified; preserved evidence requires manual inspection" -f $o.Label) -ForegroundColor Red
                    Write-Log "BepInEx: rollback failed for $($o.Code); backup=$backupPath; detail=$failureMessage"
                    $updateErrors++
                } elseif ($failureMessage -match 'CLEANUP FAILED') {
                    $cleanupFailure = $true
                    $preserveStaging = $true
                    if ($promotionSucceeded -or $failureMessage -match 'CLEANUP FAILED AFTER VERIFIED PROMOTION') {
                        [void]$changedItems.Add($o.Code)
                        $updatedWithCleanupFailure++
                    } else {
                        [void]$failedItems.Add($o.Code)
                    }
                    [void]$failureRecords.Add([pscustomobject]@{
                        Game = $o.Code
                        GameRoot = $o.ExeDir
                        StagingPath = $stagingDir
                        BackupPath = $backupPath
                        Operation = 'staging cleanup'
                        ReasonKey = 'CLEANUP_FAILED'
                        Exception = $failureMessage
                        EvidencePreserved = $true
                        NextAction = 'Close TeknoParrot and remove the validated staging residue after confirming the game files are intact.'
                    })
                    Write-Host ("    ERROR {0} -- {1}; review Details before retrying" -f $o.Label, $(if ($promotionSucceeded -or $failureMessage -match 'CLEANUP FAILED AFTER VERIFIED PROMOTION') { 'update applied, but cleanup was not completed' } else { 'update was rolled back, but cleanup was not completed' })) -ForegroundColor Red
                    $cleanupErrors++
                    Write-Log "BepInEx: cleanup failed for $($o.Code); residue=$stagingDir; detail=$failureMessage"
                } elseif ($failureCode -eq 'DEVICE_UNAVAILABLE' -or $failureCode -eq 'GAME_PATH_MISSING') {
                    if (-not $pathReasonCounts.ContainsKey($failureCode)) { $pathReasonCounts[$failureCode] = 0 }
                    $pathReasonCounts[$failureCode]++
                    if ($failureCode -eq 'DEVICE_UNAVAILABLE') { $missingDevice++ } else { $missingPath++ }
                    [void]$skippedItems.Add($o.Code)
                    [void]$failureRecords.Add([pscustomobject]@{
                        Game = $o.Code
                        GameRoot = $o.ExeDir
                        StagingPath = $stagingDir
                        BackupPath = $backupPath
                        Operation = 'mutation boundary'
                        ReasonKey = $failureCode
                        Exception = $failureMessage
                        EvidencePreserved = $false
                        NextAction = 'Reconnect the game drive or repair the saved executable path, then run BepInEx setup again.'
                    })
                    Write-Host ("    Unchanged {0} -- the game path became unavailable; nothing was changed" -f $o.Label) -ForegroundColor Yellow
                    Write-Log "BepInEx: mutation-boundary path failure for $($o.Code); reason=$failureCode; detail=$failureMessage"
                } elseif ($failureMessage -match 'mutation-boundary|destination resolution/verification failed') {
                    [void]$skippedItems.Add($o.Code)
                    if (-not $pathReasonCounts.ContainsKey('MUTATION_BOUNDARY_FAILED')) { $pathReasonCounts['MUTATION_BOUNDARY_FAILED'] = 0 }
                    $pathReasonCounts['MUTATION_BOUNDARY_FAILED']++
                    [void]$failureRecords.Add([pscustomobject]@{
                        Game = $o.Code
                        GameRoot = $o.ExeDir
                        StagingPath = $stagingDir
                        BackupPath = $backupPath
                        Operation = 'destination resolution/verification'
                        ReasonKey = 'MUTATION_BOUNDARY_FAILED'
                        Exception = $failureMessage
                        EvidencePreserved = $false
                        NextAction = 'Verify the canonical game root and destination path, then run BepInEx setup again.'
                    })
                    Write-Host ("    Unchanged {0} -- the game path changed or became unavailable; nothing was changed" -f $o.Label) -ForegroundColor Yellow
                    Write-Log "BepInEx: mutation-boundary verification failed for $($o.Code); detail=$failureMessage"
                } else {
                    [void]$failedItems.Add($o.Code)
                    [void]$failureRecords.Add([pscustomobject]@{
                        Game = $o.Code
                        GameRoot = $o.ExeDir
                        StagingPath = $stagingDir
                        BackupPath = $backupPath
                        Operation = 'BepInEx update'
                        ReasonKey = 'UPDATE_FAILED|' + $_.Exception.GetType().FullName
                        Exception = $failureMessage
                        EvidencePreserved = [bool]$preserveStaging
                        NextAction = 'Close TeknoParrot and inspect the log and preserved backup/evidence before trying again.'
                    })
                    Write-Host ("    ERROR {0} -- the verified BepInEx package was downloaded, but this game's installation was not completed" -f $o.Label) -ForegroundColor Red
                    Write-Log "BepInEx: update blocked for $($o.Code); detail=$failureMessage; evidence and backups were preserved where available."
                }
                if (-not $rollbackFailure -and -not $cleanupFailure -and $failureCode -ne 'DEVICE_UNAVAILABLE' -and $failureCode -ne 'GAME_PATH_MISSING') { $updateErrors++ }
            }
        } finally {
            if ($stagingDir -and -not $preserveStaging) {
                try {
                    [void](Remove-BepInExStagingDirectory -StagingDir $stagingDir)
                    $stagingDir = $null
                } catch {
                    $preserveStaging = $true
                    [void]$failedItems.Add($o.Code)
                    [void]$failureRecords.Add([pscustomobject]@{
                        Game = $o.Code
                        GameRoot = $o.ExeDir
                        StagingPath = $stagingDir
                        BackupPath = $backupPath
                        Operation = 'staging cleanup'
                        ReasonKey = 'CLEANUP_FAILED'
                        Exception = $_.Exception.Message
                        EvidencePreserved = $true
                        NextAction = 'Close TeknoParrot and remove the validated staging residue after confirming the game files are intact.'
                    })
                    Write-Host ("    ACTION REQUIRED {0} -- staging cleanup failed; review Details before retrying" -f $o.Label) -ForegroundColor Yellow
                    Write-Log "BepInEx: staging cleanup failed for blocked update $($o.Code); action required; residue=$stagingDir"
                    $cleanupErrors++
                }
            }
        }
    }
    if ($updateProgressTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase Repairing -Label 'BepInEx game updates' -Current $updateProgressCurrent -Total $updateProgressTotal -StartedAt $updateProgressStarted -Complete }
    Write-Host ("  Updated cleanly: {0} game(s)" -f $updated) -ForegroundColor Green
    if ($updatedWithCleanupFailure -gt 0) { Write-Host ("  Updated with cleanup failure: {0} -- ACTION REQUIRED" -f $updatedWithCleanupFailure) -ForegroundColor Yellow }
    if ($cleanupErrors -gt 0) { Write-Host ("  Cleanup failures: {0} -- see log for residue path(s)" -f $cleanupErrors) -ForegroundColor Yellow }
    Write-Log "BepInEx update check: updatedCleanly=$updated updatedWithCleanupFailure=$updatedWithCleanupFailure skippedMissingDevice=$missingDevice skippedMissingPath=$missingPath skippedProtected=$protected skippedUnsupportedArchitecture=$unsupportedArchitecture skippedUnknownArchitecture=$unknownArchitecture errors=$updateErrors cleanupFailures=$cleanupErrors"
    $completedItems = @($upToDateItems.ToArray())
    $terminalItems = @($changedItems.ToArray()) + @($completedItems) + @($failedItems.ToArray()) + @($skippedItems.ToArray())
    $unattemptedItems = @($selectedItems.ToArray() | Where-Object { $_ -notin $terminalItems })
    return [pscustomobject]@{ Succeeded = ($errors -eq 0 -and $failedItems.Count -eq 0 -and $updateErrors -eq 0 -and $cleanupErrors -eq 0 -and $updatedWithCleanupFailure -eq 0 -and $missingDevice -eq 0 -and $missingPath -eq 0 -and $protected -eq 0 -and $skippedItems.Count -eq 0); Updated = $updated; UpdatedWithCleanupFailure = $updatedWithCleanupFailure; MissingDevice = $missingDevice; MissingPath = $missingPath; Protected = $protected; Skipped=$skippedItems.Count; UnsupportedArchitecture=$unsupportedArchitecture; UnknownArchitecture=$unknownArchitecture; Errors = $errors + $updateErrors + $cleanupErrors; PathReasonCounts = $pathReasonCounts; FailureRecords = @($failureRecords.ToArray()); SelectedItems = @($selectedItems.ToArray()); ChangedItems = @($changedItems.ToArray()); CompletedItems=$completedItems; FailedItems = @($failedItems.ToArray()); SkippedItems = @($skippedItems.ToArray()); UnattemptedItems=$unattemptedItems; BatchStopped = $batchStopped }
}
# =============================================================================
# CHECK FOR UPDATES -- manual, backup-first self-update for this script
# =============================================================================
# See docs/AUTO_UPDATE.md for the full design. This mirrors the standalone
# tools/Invoke-TpmAutoUpdate.ps1 helper's logic (same release asset pattern,
# same content-validation checks, same read-only pre-check) but inlined here
# as plain functions driven by the interactive Y/N confirmation flow the menu
# requires instead of -CheckOnly/-Apply switches. TPM is NOT a single-file
# runtime: it ships required modules under scripts\ plus tools and data, so
# a multi-file release package (see Test-ManagerUpdatePackageIsSingleScript)
# is installed whole, with a verified backup and a rollback, while a ZIP that
# holds only the script replaces just that script.
# TLS 1.2 is already forced globally near the top of this script, so no
# separate per-call TLS setup is needed here.

function Get-ManagerVersionIdentity {
    param(
        [Parameter(Mandatory)][string]$ScriptVersion,
        [AllowEmptyString()][string]$ReleaseCandidateLabel = ''
    )
    $base = $ScriptVersion.Trim()
    if ([string]::IsNullOrWhiteSpace($base)) {
        throw 'The manager version is empty.'
    }
    $label = $ReleaseCandidateLabel.Trim()
    if ($label -and $label -notmatch '^(?i:RC)[1-9][0-9]*(?:\.[0-9]+)?$') {
        throw "Release-candidate label '$ReleaseCandidateLabel' is invalid."
    }
    $identity = if ($label) { "$base-$($label.ToUpperInvariant())" } else { $base }
    [void](Get-ManagerVersionParts -VersionText $identity)
    return $identity
}

function Get-ManagerIdentityWriteTargetInfo {
    param(
        [Parameter(Mandatory)]
        [System.Management.Automation.Language.ExpressionAst]$Target,
        [bool]$WasWrapped = $false,
        [bool]$IsMemberOrIndex = $false,
        [bool]$IsDestructuring = $false
    )

    $pendingTargets = [System.Collections.Stack]::new()
    $targetInfos = [System.Collections.ArrayList]::new()
    $pendingTargets.Push([pscustomobject]@{
            Target = $Target
            WasWrapped = $WasWrapped
            IsMemberOrIndex = $IsMemberOrIndex
            IsDestructuring = $IsDestructuring
        })
    while ($pendingTargets.Count -gt 0) {
        $pendingTarget = $pendingTargets.Pop()
        $currentTarget = $pendingTarget.Target
        $wasWrapped = [bool]$pendingTarget.WasWrapped
        $isMemberOrIndex = [bool]$pendingTarget.IsMemberOrIndex
        $isDestructuring = [bool]$pendingTarget.IsDestructuring
        while ($null -ne $currentTarget) {
            if ($currentTarget -is [System.Management.Automation.Language.AttributedExpressionAst]) {
                $currentTarget = $currentTarget.Child
                $wasWrapped = $true
                continue
            }
            if ($currentTarget -is [System.Management.Automation.Language.ParenExpressionAst]) {
                $pipeline = $currentTarget.Pipeline
                if ($pipeline -isnot [System.Management.Automation.Language.PipelineAst] -or
                    $pipeline.PipelineElements.Count -ne 1 -or
                    $pipeline.PipelineElements[0] -isnot [System.Management.Automation.Language.CommandExpressionAst]) {
                    break
                }
                $currentTarget = $pipeline.PipelineElements[0].Expression
                $wasWrapped = $true
                continue
            }
            if ($currentTarget -is [System.Management.Automation.Language.ArrayLiteralAst]) {
                for ($index = $currentTarget.Elements.Count - 1; $index -ge 0; $index--) {
                    $pendingTargets.Push([pscustomobject]@{
                            Target = $currentTarget.Elements[$index]
                            WasWrapped = $wasWrapped
                            IsMemberOrIndex = $isMemberOrIndex
                            IsDestructuring = $true
                        })
                }
                break
            }
            if ($currentTarget -is [System.Management.Automation.Language.MemberExpressionAst]) {
                $currentTarget = $currentTarget.Expression
                $isMemberOrIndex = $true
                continue
            }
            if ($currentTarget -is [System.Management.Automation.Language.IndexExpressionAst]) {
                $currentTarget = $currentTarget.Target
                $isMemberOrIndex = $true
                continue
            }
            if ($currentTarget -is [System.Management.Automation.Language.VariableExpressionAst]) {
                [void]$targetInfos.Add([pscustomobject]@{
                        Variable = $currentTarget
                        WasWrapped = $wasWrapped
                        IsMemberOrIndex = $isMemberOrIndex
                        IsDestructuring = $isDestructuring
                    })
            }
            break
        }
    }
    return $targetInfos.ToArray()
}

function Get-ManagerIdentityTargetName {
    param([AllowEmptyString()][string]$Path)

    $scopeSeparator = $Path.LastIndexOf(':')
    if ($scopeSeparator -ge 0) {
        return $Path.Substring($scopeSeparator + 1)
    }
    return $Path
}

function Get-ManagerScriptVersionIdentityFromContent {
    param([AllowEmptyString()][string]$Content)

    # Parse only. Candidate content is never executed to determine its identity.
    $tokens = $null
    $parseErrors = $null
    $scriptAst = [System.Management.Automation.Language.Parser]::ParseInput($Content, [ref]$tokens, [ref]$parseErrors)
    if (@($parseErrors).Count -gt 0) {
        throw "Candidate script cannot be parsed to verify its version identity."
    }

    $assignmentStatements = @($scriptAst.FindAll({
                param($node)
                $node -is [System.Management.Automation.Language.AssignmentStatementAst]
            }, $true))
    $identityAssignments = @(
        foreach ($assignment in $assignmentStatements) {
            foreach ($target in $assignment.GetAssignmentTargets()) {
                $targetInfos = @(Get-ManagerIdentityWriteTargetInfo -Target $target)
                foreach ($targetInfo in $targetInfos) {
                    $targetVariable = $targetInfo.Variable
                    $targetPath = [string]$targetVariable.VariablePath.UserPath
                    $targetName = Get-ManagerIdentityTargetName -Path $targetPath
                    if ($targetName -ieq 'ScriptVersion' -or $targetName -ieq 'ReleaseCandidateLabel') {
                        if ($assignment.Left -isnot [System.Management.Automation.Language.VariableExpressionAst] -or
                            $targetInfo.WasWrapped -or
                            $targetInfo.IsMemberOrIndex -or
                            $targetInfo.IsDestructuring) {
                            throw "Candidate script identity assignments must target a bare variable, not a wrapper, destructuring, member, or index."
                        }
                        [pscustomobject]@{
                            Assignment = $assignment
                            Name = $targetName
                            Path = $targetPath
                        }
                    }
                }
            }
        }
    )

    $identityUnaryOperators = @(
        [System.Management.Automation.Language.TokenKind]::PlusPlus
        [System.Management.Automation.Language.TokenKind]::PostfixPlusPlus
        [System.Management.Automation.Language.TokenKind]::MinusMinus
        [System.Management.Automation.Language.TokenKind]::PostfixMinusMinus
    )
    $unaryExpressions = @($scriptAst.FindAll({
                param($node)
                $node -is [System.Management.Automation.Language.UnaryExpressionAst]
            }, $true))
    foreach ($unaryExpression in $unaryExpressions) {
        if ($identityUnaryOperators -notcontains $unaryExpression.TokenKind) {
            continue
        }
        foreach ($targetInfo in @(Get-ManagerIdentityWriteTargetInfo -Target $unaryExpression.Child)) {
            $targetPath = [string]$targetInfo.Variable.VariablePath.UserPath
            $targetName = Get-ManagerIdentityTargetName -Path $targetPath
            if ($targetName -ieq 'ScriptVersion' -or $targetName -ieq 'ReleaseCandidateLabel') {
                throw "Candidate script identity variables cannot be incremented or decremented."
            }
        }
    }

    foreach ($forEachStatement in @($scriptAst.FindAll({
                param($node)
                $node -is [System.Management.Automation.Language.ForEachStatementAst]
            }, $true))) {
        $targetPath = [string]$forEachStatement.Variable.VariablePath.UserPath
        $targetName = Get-ManagerIdentityTargetName -Path $targetPath
        if ($targetName -ieq 'ScriptVersion' -or $targetName -ieq 'ReleaseCandidateLabel') {
            throw "Candidate script identity variables cannot be foreach loop variables."
        }
    }

    if ($null -ne $scriptAst.ParamBlock) {
        foreach ($parameter in $scriptAst.ParamBlock.Parameters) {
            $targetPath = [string]$parameter.Name.VariablePath.UserPath
            $targetName = Get-ManagerIdentityTargetName -Path $targetPath
            if ($targetName -ieq 'ScriptVersion' -or $targetName -ieq 'ReleaseCandidateLabel') {
                throw "Candidate script identity variables cannot be root script parameters."
            }
        }
    }

    foreach ($dataStatement in @($scriptAst.FindAll({
                param($node)
                $node -is [System.Management.Automation.Language.DataStatementAst]
            }, $true))) {
        if ($null -eq $dataStatement.Variable) {
            continue
        }
        $targetName = Get-ManagerIdentityTargetName -Path ([string]$dataStatement.Variable)
        if ($targetName -ieq 'ScriptVersion' -or $targetName -ieq 'ReleaseCandidateLabel') {
            throw "Candidate script identity variables cannot be data-statement variables."
        }
    }

    $versionAssignments = @($identityAssignments | Where-Object { $_.Name -ieq 'ScriptVersion' })
    $labelAssignments = @($identityAssignments | Where-Object { $_.Name -ieq 'ReleaseCandidateLabel' })
    if ($versionAssignments.Count -gt 1 -or $labelAssignments.Count -gt 1) {
        throw "Candidate script contains duplicate version identity assignments."
    }

    foreach ($identityAssignment in $identityAssignments) {
        $assignment = $identityAssignment.Assignment
        if (-not [object]::ReferenceEquals($assignment.Parent, $scriptAst.EndBlock) -or
            $identityAssignment.Path -ine $identityAssignment.Name) {
            throw "Candidate version identity assignments must be direct, unscoped top-level declarations."
        }
        if ($assignment.Operator -ne [System.Management.Automation.Language.TokenKind]::Equals -or
            $assignment.Right -isnot [System.Management.Automation.Language.CommandExpressionAst] -or
            $assignment.Right.Expression -isnot [System.Management.Automation.Language.StringConstantExpressionAst]) {
            throw "Candidate version identity assignments must use constant string literals."
        }
    }

    if ($versionAssignments.Count -eq 0) {
        return $null
    }
    $version = $versionAssignments[0].Assignment.Right.Expression.Value
    $label = if ($labelAssignments.Count -eq 1) {
        $labelAssignments[0].Assignment.Right.Expression.Value
    } else {
        ''
    }
    return Get-ManagerVersionIdentity -ScriptVersion $version -ReleaseCandidateLabel $label
}

function Get-ManagerVersionParts {
    param([Parameter(Mandatory)][string]$VersionText)
    $match = [regex]::Match($VersionText.Trim(), '^(?i:v)?(?<base>[0-9]+(?:\.[0-9]+){1,3})(?:-(?i:RC)(?<candidate>[1-9][0-9]*)(?:\.(?<minor>[0-9]+))?)?$')
    if (-not $match.Success) {
        throw "Version '$VersionText' is not a supported manager version identity."
    }
    try {
        $baseVersion = [version]::Parse($match.Groups['base'].Value)
        $candidateNumber = if ($match.Groups['candidate'].Success) { [int64]::Parse($match.Groups['candidate'].Value) } else { $null }
        $candidateMinor = if ($match.Groups['minor'].Success) { [int64]::Parse($match.Groups['minor'].Value) } else { [int64]0 }
    } catch {
        throw "Version '$VersionText' is not a supported manager version identity."
    }
    return [pscustomobject]@{
        BaseVersion = $baseVersion
        CandidateNumber = $candidateNumber
        CandidateMinor = $candidateMinor
    }
}

function Compare-ManagerVersionText {
    param(
        [Parameter(Mandatory)][string]$VersionTextA,
        [Parameter(Mandatory)][string]$VersionTextB
    )
    $a = Get-ManagerVersionParts -VersionText $VersionTextA
    $b = Get-ManagerVersionParts -VersionText $VersionTextB
    $baseComparison = $a.BaseVersion.CompareTo($b.BaseVersion)
    if ($baseComparison -ne 0) {
        return $baseComparison
    }
    if ($null -eq $a.CandidateNumber -and $null -eq $b.CandidateNumber) {
        return 0
    }
    if ($null -eq $a.CandidateNumber) {
        return 1
    }
    if ($null -eq $b.CandidateNumber) {
        return -1
    }
    $candidateComparison = [int]$a.CandidateNumber.CompareTo($b.CandidateNumber)
    if ($candidateComparison -ne 0) {
        return $candidateComparison
    }
    # A dotted label such as RC8.1 is a later build of RC8 (no minor part counts as .0).
    return [int]$a.CandidateMinor.CompareTo($b.CandidateMinor)
}

# Converts a raw GitHub release tag (e.g. "v1.0-RC2", "v0.99.44") into this
# script's own canonical display shape: "v<version> <LABEL>" with a space,
# the same shape $DisplayVersion already uses for the running script
# ("v1.0 RC2") -- never the dash-separated git tag form. Without this, the
# "Current version" line (built from $DisplayVersion/$ScriptVersion) and
# the "Latest version" line (previously the raw tag) could show the same
# release two different ways side by side, e.g. "v1.0" vs "v1.0-RC2" --
# where the RC tag is a distinct, earlier release identity. See issue #134.
# The formatter keeps the canonical space-separated display shape.
function ConvertTo-ManagerDisplayVersionFromTag {
    param([Parameter(Mandatory)][string]$VersionText)
    $normalized = ($VersionText -replace '^v', '').Trim()
    $parts = $normalized -split '-', 2
    if ($parts.Count -gt 1 -and $parts[1]) {
        return "v{0} {1}" -f $parts[0], $parts[1]
    }
    return "v$($parts[0])"
}

function Get-ManagerUpdateRelease {
    # Same retry/backoff shape as Get-BepInExLatestRelease / Get-EggmanDatRelease,
    # but MaxAttempts/TimeoutSec are tunable: the menu-triggered check can afford
    # to retry patiently since the user explicitly asked, but the quiet startup
    # check (Invoke-StartupUpdateCheck) uses a single short-timeout attempt so an
    # unreachable GitHub cannot noticeably delay launching the script.
    param(
        [int]$MaxAttempts = 3,
        [int]$TimeoutSec = 20
    )

    for ($attempt = 1; $attempt -le $MaxAttempts; $attempt++) {
        try {
            $apiUri = 'https://api.github.com/repos/Jumpstile/teknoparrot-manager/releases/latest'
            $resp    = Invoke-TpmWebRequestSilently -Uri $apiUri -UseBasicParsing -TimeoutSec $TimeoutSec `
                           -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $release = $resp.Content | ConvertFrom-Json
            $asset   = @($release.assets | Where-Object { $_.name -match '^TeknoParrot\.Manager\.v.*\.zip$' }) | Select-Object -First 1
            if (-not $asset) {
                Write-Log "CheckForUpdates: latest release $($release.tag_name) has no matching asset."
                return $null
            }
            # URI-parsed validation (not -like/regex prefix matching) so the
            # host check inspects the actual parsed authority -- rejects
            # userinfo tricks and lookalike hosts a naive prefix check could
            # be fooled by. Same approach as the standalone updater tool.
            $parsedUri = $null
            $urlOk = [System.Uri]::TryCreate($asset.browser_download_url, [System.UriKind]::Absolute, [ref]$parsedUri) -and
                     $parsedUri.Scheme -eq 'https' -and
                     $parsedUri.Host -eq 'github.com' -and
                     [string]::IsNullOrEmpty($parsedUri.UserInfo) -and
                     $parsedUri.AbsolutePath.StartsWith('/Jumpstile/teknoparrot-manager/releases/download/', [System.StringComparison]::Ordinal)
            if (-not $urlOk) {
                Write-Log "CheckForUpdates: refusing non-release GitHub asset URL: $($asset.browser_download_url)"
                return $null
            }
            return [pscustomobject]@{
                TagName     = $release.tag_name
                Name        = $release.name
                Body        = $release.body
                AssetName   = $asset.name
                DownloadUrl = $asset.browser_download_url
                SizeBytes   = [int64]$asset.size
                Digest      = if ($asset.PSObject.Properties['digest']) { [string]$asset.digest } else { '' }
            }
        } catch {
            $status = 0
            # Get-TpmHttpStatusCodeFromError guards the same optional
            # .Exception.Response/.StatusCode access this used to do inline
            # (unsafe under strict mode for exception types that lack either
            # property entirely -- RuntimeException from a plain "throw",
            # HttpRequestException, etc.) and additionally falls back to
            # extracting a status code embedded only in the message text.
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge $MaxAttempts -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "CheckForUpdates: release query failed -- $_"; return $null
            }
            Write-Log "CheckForUpdates: attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    return $null
}

# First non-blank line of a release's markdown body, trimmed of the most
# common markdown decoration and clamped to a short length -- a "brief
# summary" for the startup notice, not a full changelog rendering.
function Get-ManagerUpdateReleaseSummary {
    param([string]$Body)

    if ([string]::IsNullOrWhiteSpace($Body)) { return $null }

    $firstLine = ($Body -split "`r?`n" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1)
    if (-not $firstLine) { return $null }

    $firstLine = $firstLine.Trim() -replace '^#+\s*', '' -replace '^[-*]\s*', ''
    if ($firstLine.Length -gt 150) {
        $firstLine = $firstLine.Substring(0, 150).TrimEnd() + "..."
    }
    return $firstLine
}

function Assert-ManagerUpdateTargetWritable {
    param([Parameter(Mandatory)][string]$Path)

    # An explicitly approved update may clear only the target script's
    # ReadOnly attribute. The installer transaction records that fact and
    # reapplies it to the replacement or original file in finally.
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $false }
    $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    if ($item.IsReadOnly) {
        Set-ItemProperty -LiteralPath $Path -Name IsReadOnly -Value $false -ErrorAction Stop
        return $true
    }
    return $false
}

function New-ManagerUpdateBackup {
    param([Parameter(Mandatory)][string]$Path)

    # Derived from $Path itself (not $PSScriptRoot) so the backup always
    # lands next to the actual target file regardless of caller context --
    # matches the standalone tools/TpmAutoUpdate.Core.psm1 module's
    # New-TpmUpdateBackup, and avoids relying on $PSScriptRoot, which is an
    # automatic variable reset per function invocation rather than an
    # ordinary dynamically-scoped one (a caller cannot override it).
    #
    # Each backup run gets its own newly created folder. An occupied folder or
    # file name is a collision, never reusable backup storage, so earlier
    # recovery history is never overwritten. The first choice is
    # TeknoParrotManager_<timestamp>; a same-second collision takes the next
    # free numbered name (_2, _3, ...). No random suffix: the required-patch
    # engine nests this folder deep inside its recovery run, and unless Windows
    # long-path support is enabled (off by default) Windows PowerShell 5.1
    # cannot create or copy to paths longer than MAX_PATH; a 33-character GUID
    # suffix pushed real required-patch backups past that limit.
    # Resolve against the PowerShell location: [IO.File]::Copy below would
    # otherwise resolve a relative path against the process directory.
    $Path       = Convert-Path -LiteralPath $Path -ErrorAction Stop
    $repoRoot   = Split-Path -Parent $Path
    $backupRoot = Join-Path $repoRoot "UpdateBackups"
    $timestamp  = (Get-Date).ToString("yyyy-MM-dd_HH-mm-ss", [System.Globalization.CultureInfo]::InvariantCulture)
    Assert-TpmNoReparseWriteTarget -Path $backupRoot -Operation 'Manager update backup root'
    [void][System.IO.Directory]::CreateDirectory($backupRoot)
    $backupDir = $null
    for ($attempt = 1; $attempt -le 100 -and -not $backupDir; $attempt++) {
        $folderName = "TeknoParrotManager_" + $timestamp
        if ($attempt -gt 1) { $folderName += "_" + $attempt }
        $candidate = Join-Path $backupRoot $folderName
        Assert-TpmNoReparseWriteTarget -Path $candidate -Operation 'Manager update backup'
        # An existing folder belongs to an earlier backup: never reuse it.
        if (Test-Path -LiteralPath $candidate) { continue }
        try {
            # No -Force: New-Item fails instead of accepting an existing folder.
            New-Item -ItemType Directory -Path $candidate -ErrorAction Stop | Out-Null
        } catch {
            # Another writer created this name first: take the next one.
            # Any other failure (access, path length, disk) stops the backup.
            if (Test-Path -LiteralPath $candidate) { continue }
            throw
        }
        $backupDir = $candidate
    }
    if (-not $backupDir) {
        throw "Backup folder names for $timestamp are all in use under $backupRoot; refusing to reuse one."
    }
    $backupPath = Join-Path $backupDir (Split-Path -Leaf $Path)
    Assert-TpmNoReparseWriteTarget -Path $backupPath -Operation 'Manager update backup copy'
    # overwrite = $false: an existing file at the destination is a collision.
    [System.IO.File]::Copy($Path, $backupPath, $false)

    if (-not (Test-Path -LiteralPath $backupPath -PathType Leaf)) {
        throw "Backup creation failed: $backupPath"
    }
    $sourceHash = (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash
    $backupHash = (Get-FileHash -LiteralPath $backupPath -Algorithm SHA256 -ErrorAction Stop).Hash
    if ($sourceHash -ine $backupHash) {
        throw "Backup verification failed (hash mismatch): $backupPath"
    }
    return $backupPath
}

function Expand-ManagerUpdateAsset {
    param(
        [Parameter(Mandatory)][string]$ZipPath,
        [Parameter(Mandatory)][string]$EntryName,
        [Parameter(Mandatory)][string]$DestinationPath
    )

    if (-not (Test-Path -LiteralPath $ZipPath -PathType Leaf)) {
        throw "Downloaded release asset not found: $ZipPath"
    }

    Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
    $zip = [System.IO.Compression.ZipFile]::OpenRead($ZipPath)
    try {
        $entry = $zip.Entries | Where-Object { $_.FullName -eq $EntryName } | Select-Object -First 1
        if (-not $entry) {
            throw "Release asset does not contain the expected entry '$EntryName'."
        }
        [System.IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $DestinationPath, $true)
    } finally {
        $zip.Dispose()
    }
    return $DestinationPath
}

# RC8 and later are multi-file products: the main script requires shipped
# modules (scripts\TpmRequiredPatchEngine.ps1, scripts\TpmProgress.psm1, the
# certification modules) plus tools and packaged data. A release ZIP that
# carries any file besides one root TeknoParrot-Manager.ps1 is installed whole
# by Invoke-ManagerUpdateInstall; only a ZIP with that one script takes the
# single-file path. Directory entries are ignored; every file entry
# other than one root TeknoParrot-Manager.ps1 counts as extra, including a
# second entry with exactly that name. Throws when the ZIP cannot be read so
# the caller fails closed.
function Test-ManagerUpdatePackageIsSingleScript {
    param([Parameter(Mandatory)][string]$ZipPath)

    if (-not (Test-Path -LiteralPath $ZipPath -PathType Leaf)) {
        throw "Downloaded release asset not found: $ZipPath"
    }
    Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
    $extra = New-Object System.Collections.Generic.List[string]
    $scriptEntrySeen = $false
    $zip = [System.IO.Compression.ZipFile]::OpenRead($ZipPath)
    try {
        foreach ($entry in @($zip.Entries)) {
            $entryName = [string]$entry.FullName
            if ([string]::IsNullOrEmpty([string]$entry.Name) -and ($entryName.EndsWith('/') -or $entryName.EndsWith('\'))) { continue }
            if (-not $scriptEntrySeen -and $entryName -ceq 'TeknoParrot-Manager.ps1') { $scriptEntrySeen = $true; continue }
            [void]$extra.Add($entryName)
        }
    } finally {
        $zip.Dispose()
    }
    return [pscustomobject]@{
        SingleScript = ($scriptEntrySeen -and $extra.Count -eq 0)
        ScriptEntrySeen = [bool]$scriptEntrySeen
        ExtraEntryCount = [int]$extra.Count
        ExtraEntrySample = [string[]]@($extra | Select-Object -First 5)
    }
}

function Test-ManagerUpdateExtractedScript {
    param([Parameter(Mandatory)][string]$Path)

    # Defense-in-depth before the extracted file ever replaces the live
    # script: exists, non-empty, is not the raw zip container (would happen
    # if extraction were ever skipped or broken upstream), and looks like
    # TeknoParrot-Manager.ps1 rather than an unrelated or truncated file.
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        throw "Extracted script not found: $Path"
    }
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    if ($bytes.Length -eq 0) {
        throw "Extracted script is empty: $Path"
    }
    if ($bytes.Length -ge 2 -and $bytes[0] -eq 0x50 -and $bytes[1] -eq 0x4B) {
        throw "Extracted script begins with a zip signature (PK) -- refusing to install: $Path"
    }
    # Windows PowerShell 5.1 interprets BOM-less script bytes as Windows-1252.
    # Require ASCII so AST validation and installed-source interpretation agree.
    foreach ($byte in $bytes) {
        if ($byte -gt 0x7F) {
            throw "Extracted script contains non-ASCII bytes -- refusing to install: $Path"
        }
    }

    $content = [System.Text.Encoding]::UTF8.GetString($bytes)
    if ($content -notmatch 'TeknoParrot Manager') {
        throw "Extracted script does not contain the expected 'TeknoParrot Manager' marker: $Path"
    }
    $identity = Get-ManagerScriptVersionIdentityFromContent -Content $content
    if (-not $identity) {
        throw "Extracted script does not contain a valid top-level `$ScriptVersion assignment: $Path"
    }
    return $true
}

# Every file a multi-file release ZIP would write, checked before anything is extracted. Reuses the shared entry-name rules
# (no rooted or drive names, no '..', no reserved names). Names that differ only by letter case count as the same name.
# Returns Path (relative, backslashes) and Length (unpacked bytes). Throws on the first unsafe entry.
function Get-ManagerUpdatePackageFiles {
    param([Parameter(Mandatory)][string]$ZipPath)
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $files = New-Object System.Collections.Generic.List[object]
    $zip = [System.IO.Compression.ZipFile]::OpenRead($ZipPath)
    try {
        foreach ($entry in $zip.get_Entries()) {
            $info = ConvertTo-SafeZipEntryRelativePath -EntryName $entry.FullName
            if ($info.IsDirectory) { continue }
            if (-not $seen.Add($info.RelativePath)) { throw "The ZIP lists '$($info.RelativePath)' more than once (names that differ only by letter case are the same name)." }
            [void]$files.Add([pscustomobject]@{ Path = $info.RelativePath; Length = [int64]$entry.Length })
        }
    } finally {
        $zip.Dispose()
    }
    return $files.ToArray()
}

# Compares the unpacked package with the installed files. Install lists the files to write (Kind New or Changed, with the
# SHA-256 of the installed copy and of the new one) in install order: the main script is last. Identical files are only counted.
function Get-ManagerUpdateInstallPlan {
    param(
        [Parameter(Mandatory)][string]$ProgramDir,
        [Parameter(Mandatory)][string]$StagingDir,
        [Parameter(Mandatory)][object[]]$Files
    )

    $install = New-Object System.Collections.Generic.List[object]
    $identical = 0
    foreach ($file in $Files) {
        $installed = Join-Path $ProgramDir $file.Path
        if (Test-Path -LiteralPath $installed -PathType Container) { throw "The update needs a file at '$($file.Path)', but a folder is there." }
        $newHash = (Get-FileHash -LiteralPath (Join-Path $StagingDir $file.Path) -Algorithm SHA256 -ErrorAction Stop).Hash
        $oldHash = $null
        if (Test-Path -LiteralPath $installed -PathType Leaf) {
            $oldHash = (Get-FileHash -LiteralPath $installed -Algorithm SHA256 -ErrorAction Stop).Hash
            if ($oldHash -ieq $newHash) { $identical++; continue }
        }
        [void]$install.Add([pscustomobject]@{ Path = $file.Path; Kind = $(if ($null -eq $oldHash) { 'New' } else { 'Changed' }); OldHash = $oldHash; NewHash = $newHash })
    }
    $ordered = @($install | Where-Object { $_.Path -ine 'TeknoParrot-Manager.ps1' }) + @($install | Where-Object { $_.Path -ieq 'TeknoParrot-Manager.ps1' })
    return [pscustomobject]@{ Install = $ordered; IdenticalCount = $identical }
}

# After a failed install: the files from the plan that are not back in their original state (a replaced file whose bytes
# differ from the original, or an added file that is still there). Empty means everything is back as it was.
function Get-ManagerUpdateUnrestoredFiles {
    param([Parameter(Mandatory)][string]$ProgramDir, [Parameter(Mandatory)][object[]]$Install)

    foreach ($item in $Install) {
        $path = Join-Path $ProgramDir $item.Path
        $unrestored = $false
        try {
            if ($item.Kind -eq 'New') {
                $unrestored = [bool](Test-Path -LiteralPath $path)
            } else {
                $unrestored = (-not (Test-Path -LiteralPath $path -PathType Leaf)) -or ((Get-FileHash -LiteralPath $path -Algorithm SHA256 -ErrorAction Stop).Hash -ine $item.OldHash)
            }
        } catch {
            $unrestored = $true
        }
        if ($unrestored) { $item.Path }
    }
}

# Installed files, inside folders the new package also uses, that the new package no longer has. The update never deletes
# them; they are listed in Details so the user can decide.
function Get-ManagerUpdateLeftInPlace {
    param([Parameter(Mandatory)][string]$ProgramDir, [Parameter(Mandatory)][object[]]$Files)

    $known = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($file in $Files) { [void]$known.Add($file.Path) }
    $folders = @($Files | Where-Object { $_.Path.Contains('\') } | ForEach-Object { $_.Path.Substring(0, $_.Path.IndexOf('\')) } | Sort-Object -Unique)
    $baseLength = $ProgramDir.TrimEnd('\').Length + 1
    foreach ($folder in $folders) {
        $folderPath = Join-Path $ProgramDir $folder
        if (-not (Test-Path -LiteralPath $folderPath -PathType Container)) { continue }
        foreach ($found in @(Get-ChildItem -LiteralPath $folderPath -Recurse -File -Force -ErrorAction SilentlyContinue)) {
            $relative = $found.FullName.Substring($baseLength)
            if (-not $known.Contains($relative)) { $relative }
        }
    }
}

# Staging folders of updates that did not finish. A running update holds a marker file open inside its folder, so a folder whose
# marker can be opened (or that has no marker and is more than a minute old) belongs to an update that was cut off.
function Get-TpmInterruptedUpdateFolders {
    param([Parameter(Mandatory)][string]$ProgramDir)
    foreach ($folder in @(Get-ChildItem -LiteralPath $ProgramDir -Directory -Filter 'tpm-update-staging-*' -Force -ErrorAction SilentlyContinue)) {
        $marker = Join-Path $folder.FullName '.tpm-update-running'
        $running = $false
        if (Test-Path -LiteralPath $marker -PathType Leaf) {
            $handle = $null
            try { $handle = [System.IO.File]::Open($marker, [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None) }
            catch [System.IO.IOException] { $running = $true }
            catch { }
            finally { if ($handle) { $handle.Dispose() } }
        } elseif ($folder.CreationTimeUtc -gt (Get-Date).ToUniversalTime().AddMinutes(-1)) {
            $running = $true
        }
        if (-not $running) { $folder.FullName }
    }
}

# At start: one short notice when an earlier update was cut off. Notice only: the folder is never removed here, because it can hold
# the only copy of files that were moved aside. The log names the folders and the newest backup.
function Write-TpmInterruptedUpdateNotice {
    param([Parameter(Mandatory)][string]$ProgramDir)
    $folders = @(Get-TpmInterruptedUpdateFolders -ProgramDir $ProgramDir)
    if ($folders.Count -eq 0) { return }
    $newest = @(Get-ChildItem -LiteralPath (Join-Path $ProgramDir 'UpdateBackups') -Directory -Filter 'TeknoParrotManager_*' -ErrorAction SilentlyContinue | Sort-Object -Property Name -Descending | Select-Object -First 1)
    $newestPath = if ($newest.Count -gt 0) { [string]$newest[0].FullName } else { '' }
    Write-Log ("Interrupted update: found {0} unfinished update folder(s): {1}. Newest backup: {2}" -f $folders.Count, ($folders -join '; '), $(if ($newestPath) { $newestPath } else { 'none' }))
    if ($Unattended) { return }
    Write-Host ''
    Write-Host '  An earlier update of TeknoParrot Manager did not finish.' -ForegroundColor Yellow
    Write-Host '  Some files may be a mix of old and new versions.' -ForegroundColor Yellow
    Write-Host '  If the program works, you can keep using it.' -ForegroundColor Yellow
    Write-Host '  To go back to the old files: open the UpdateBackups folder next to this' -ForegroundColor Cyan
    Write-Host '  program, open the newest TeknoParrotManager_ folder, and copy its files' -ForegroundColor Cyan
    Write-Host '  back over the program folder (same folder names).' -ForegroundColor Cyan
    if ($newestPath) { Write-Host ('  Newest backup: {0}' -f $newestPath) -ForegroundColor DarkGray }
    Write-Host '  Or run the update again: choose 15 (Check for Updates).' -ForegroundColor Cyan
    Write-Host ('  TeknoParrot Manager keeps the folder {0} on purpose and never deletes it: it can hold your old files.' -f (Split-Path -Leaf $folders[0])) -ForegroundColor DarkGray
    Write-Host '  After you have put the old files back (or are sure you do not need them),' -ForegroundColor DarkGray
    Write-Host '  you can delete that folder yourself. This notice then stops.' -ForegroundColor DarkGray
}

function Get-ManagerUpdatePreState {
    param([Parameter(Mandatory)][string]$Path)
    try {
        if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
            return [pscustomobject]@{
                Captured = $false
                CaptureMethod = 'Target script is unavailable.'
                CapturedUtc = (Get-Date).ToUniversalTime().ToString('o')
                Items = @('manager-script')
                EvidenceRoot = $null
                CaptureError = 'Target script is unavailable.'
                Path = $Path
                Sha256 = $null
                Length = 0
                Version = $null
                IsReadOnly = $false
            }
        }
        $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        $bytes = [System.IO.File]::ReadAllBytes($Path)
        $content = [System.Text.Encoding]::UTF8.GetString($bytes)
        $version = Get-ManagerScriptVersionIdentityFromContent -Content $content
        return [pscustomobject]@{
            Captured = $true
            CaptureMethod = 'Read and hashed the current manager script before replacement.'
            CapturedUtc = (Get-Date).ToUniversalTime().ToString('o')
            Items = @('manager-script')
            EvidenceRoot = $null
            CaptureError = $null
            Path = $Path
            Sha256 = (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash
            Length = [int64]$bytes.Length
            Version = $version
            IsReadOnly = [bool]$item.IsReadOnly
        }
    } catch {
        return [pscustomobject]@{
            Captured = $false
            CaptureMethod = 'Manager script pre-state capture failed.'
            CapturedUtc = (Get-Date).ToUniversalTime().ToString('o')
            Items = @('manager-script')
            EvidenceRoot = $null
            CaptureError = [string]$_.Exception.Message
            Path = $Path
            Sha256 = $null
            Length = 0
            Version = $null
            IsReadOnly = $false
        }
    }
}

function New-TpmManagerUpdateTransactionResult {
    param(
        [Parameter(Mandatory)][string]$Outcome,
        [Parameter(Mandatory)][string]$ProductState,
        [Parameter(Mandatory)][string]$Summary,
        [object]$PreState = $null,
        [object]$Backup = $null,
        [object]$Rollback = $null,
        [object]$Cleanup = $null,
        [bool]$MutationStarted = $false,
        [bool]$MutationCompleted = $false,
        [bool]$FinalAttempted = $false,
        [bool]$FinalPassed = $false,
        [object[]]$FinalChecks = @(),
        [object[]]$FinalFailedItems = @(),
        [string]$ReasonCode = $null,
        [object]$TechnicalDetails = $null,
        [string[]]$Errors = @(),
        [string[]]$Warnings = @(),
        [object[]]$RecoveryActions = @()
    )
    $tx = New-TpmProfileTransactionResult `
        -WorkflowKey 'ManagerUpdate' `
        -OperationKey 'CheckAndInstallRelease' `
        -Outcome $Outcome `
        -ProductState $ProductState `
        -Summary $Summary `
        -Items @('manager-script') `
        -ChangedItems $(if ($MutationStarted) { @('manager-script') } else { @() }) `
        -CompletedItems $(if ($Outcome -eq 'SUCCEEDED') { @('manager-script') } else { @() }) `
        -FailedItems $(if ($Outcome -eq 'PARTIAL_APPLIED') { @('manager-script') } else { @() }) `
        -UnknownItems $(if ($ProductState -eq 'UNKNOWN') { @('manager-script') } else { @() }) `
        -SkippedItems $(if ($Outcome -eq 'NO_OP') { @('manager-script') } else { @() }) `
        -MutationStarted:$MutationStarted `
        -MutationCompleted:$MutationCompleted `
        -Backup $Backup `
        -PreState $PreState `
        -FinalAttempted:$FinalAttempted `
        -FinalPassed:$FinalPassed `
        -FinalChecks $FinalChecks `
        -FinalFailedItems $FinalFailedItems `
        -Rollback $Rollback `
        -Cleanup $Cleanup `
        -ReasonCode $ReasonCode `
        -TechnicalDetails $TechnicalDetails `
        -Errors $Errors `
        -Warnings $Warnings `
        -RecoveryActions $RecoveryActions
    # The new manager file is on disk whenever the product state is INTENDED, even if cleanup afterwards needed attention.
    $tx | Add-Member -NotePropertyName Installed -NotePropertyValue ($ProductState -eq 'INTENDED') -Force
    $tx | Add-Member -NotePropertyName UpdateInstalled -NotePropertyValue ($ProductState -eq 'INTENDED') -Force
    return $tx
}

# Performs the shared backup/download/extract/validate/replace transaction for
# an already approved release. Returns TPM.TransactionResult.v1 for every
# outcome; callers must restart only after validating Outcome SUCCEEDED because
# the in-memory code is stale after a verified replacement.
#
# This function never prompts. Invoke-CheckForUpdates and
# Invoke-StartupUpdateCheck own their distinct confirmation flows.
function Invoke-ManagerUpdateInstall {
    param(
        [Parameter(Mandatory)][string]$ScriptPath,
        [Parameter(Mandatory)][pscustomobject]$Release
    )
    $preState = Get-ManagerUpdatePreState -Path $ScriptPath
    $backupPath = $null
    $downloadedZipPath = $null
    $extractedScriptPath = $null
    $candidateHash = $null
    $readOnlyCleared = $false
    $multiFile = $false
    $programDir = $null
    $plan = $null
    $stagingDir = $null
    $stagingCreated = $false
    $stagingLock = $null
    $stagingPreserved = $false
    $promoteCalled = $false
    $backupDir = $null
    $multiDetails = $null
    $readOnlyPaths = New-Object System.Collections.Generic.List[string]
    $mutationStarted = $false
    $mutationAttempted = $false
    $outcome = 'FAILED_BEFORE_MUTATION'
    $productState = 'UNCHANGED'
    $reasonCode = 'UPDATE_PREPARATION_FAILED'
    $summary = 'The update was not installed. Your current TeknoParrot Manager was not changed.'
    $finalAttempted = $false
    $finalPassed = $false
    $finalChecks = @()
    $errors = New-Object System.Collections.Generic.List[string]
    $warnings = New-Object System.Collections.Generic.List[string]
    $rollback = $null
    $backupInfo = [pscustomobject]@{
        Required = $true
        Attempted = $false
        Created = $false
        Verified = $false
        RootPath = $null
        Items = @('manager-script')
        FailureStage = 'Backup'
        FailureCode = 'UPDATE_BACKUP_NOT_ATTEMPTED'
    }
    $cleanupResidue = New-Object System.Collections.Generic.List[string]
    $cleanupErrors = New-Object System.Collections.Generic.List[string]
    try {
        if (-not $preState.Captured) { throw 'The current manager script could not be read and hashed before the update.' }
        # The digest is required for this updater, even when GitHub omits it.
        # Snapshot it before downloading so an asset change cannot change our expectation.
        $digest = if ($Release.PSObject.Properties['Digest']) { [string]$Release.Digest } else { '' }
        $expectedSha256 = Get-TpmSha256FromDigestField -Digest $digest
        if ($digest.Length -ne 71 -or -not $expectedSha256) {
            $reasonCode = 'UPDATE_DIGEST_UNAVAILABLE'
            throw 'The update has no valid SHA-256 check from GitHub. Nothing was installed. Download the ZIP manually from https://github.com/Jumpstile/teknoparrot-manager/releases.'
        }

        $downloadedZipPath = Join-Path ([System.IO.Path]::GetTempPath()) ("tpm-update-" + [guid]::NewGuid().ToString('N') + '.zip')
        if (-not (Invoke-TpmDownload -DownloadUrl $Release.DownloadUrl -DestinationPath $downloadedZipPath -ExpectedBytes $Release.SizeBytes -Label 'CheckForUpdates' -Version $Release.TagName)) {
            $reasonCode = 'UPDATE_DOWNLOAD_FAILED'
            throw 'The approved update package could not be downloaded and verified.'
        }
        # Get-FileHash reads a stream, not a package-sized byte array. Compare all
        # 64 hex characters before opening the ZIP or changing the installed copy.
        $actualSha256 = (Get-FileHash -LiteralPath $downloadedZipPath -Algorithm SHA256 -ErrorAction Stop).Hash
        if (-not [string]::Equals($expectedSha256, $actualSha256, [System.StringComparison]::OrdinalIgnoreCase)) {
            $reasonCode = 'UPDATE_DIGEST_MISMATCH'
            throw ("The update SHA-256 check failed (expected {0}, got {1}). Nothing was installed. Download the ZIP manually from https://github.com/Jumpstile/teknoparrot-manager/releases." -f $expectedSha256.Substring(0, 12), $actualSha256.Substring(0, 12))
        }
        # A single-script package replaces only the main script. A multi-file package (RC8 and later) is installed whole.
        $packageComposition = Test-ManagerUpdatePackageIsSingleScript -ZipPath $downloadedZipPath
        if (-not $packageComposition.ScriptEntrySeen) {
            $reasonCode = 'UPDATE_PACKAGE_HAS_NO_SCRIPT'
            Write-Log ("CheckForUpdates: release {0} has no TeknoParrot-Manager.ps1 in its ZIP ({1} other file(s)); update refused before extraction." -f $Release.TagName, $packageComposition.ExtraEntryCount)
            Write-Host ''
            Write-Host '  There is no script in this release, so nothing was installed and your' -ForegroundColor Yellow
            Write-Host '  current copy is unchanged. Try again later, or download the latest' -ForegroundColor Yellow
            Write-Host '  release ZIP from' -ForegroundColor Yellow
            Write-Host '    https://github.com/Jumpstile/teknoparrot-manager/releases' -ForegroundColor Cyan
            throw 'The release ZIP does not contain TeknoParrot-Manager.ps1; nothing was installed.'
        }
        $multiFile = -not $packageComposition.SingleScript
        if ($multiFile) {
            # Everything below is checked and staged before the installed program is touched.
            $programDir = [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($ScriptPath))
            if ([System.IO.Path]::GetFileName($ScriptPath) -ine 'TeknoParrot-Manager.ps1') {
                throw 'The running script is not named TeknoParrot-Manager.ps1, so the update cannot tell where its files belong.'
            }
            $reasonCode = 'UPDATE_PACKAGE_BAD_ENTRY'
            try {
                $packageFiles = @(Get-ManagerUpdatePackageFiles -ZipPath $downloadedZipPath)
            } catch {
                Write-Log ("CheckForUpdates: release {0} refused before extraction -- {1}" -f $Release.TagName, $_.Exception.Message)
                throw 'The update package has a file name that is not safe. Nothing was installed. See https://github.com/Jumpstile/teknoparrot-manager/releases.'
            }
            $unpackedBytes = [int64](($packageFiles | Measure-Object -Property Length -Sum).Sum)
            $reasonCode = 'UPDATE_NOT_ENOUGH_DISK_SPACE'
            $freeBytes = Get-TpmCps3FreeBytes -Path $programDir
            if ($null -ne $freeBytes -and $freeBytes -lt (2 * $unpackedBytes)) {
                throw ('There is not enough free space for the update ({0} MB free, about {1} MB needed). Nothing was installed.' -f [int64]($freeBytes / 1MB), [int64]((2 * $unpackedBytes) / 1MB))
            }
            $reasonCode = 'UPDATE_PREPARATION_FAILED'
            $stagingDir = Join-Path $programDir ('tpm-update-staging-' + [guid]::NewGuid().ToString('N'))
            Assert-TpmNoReparseWriteTarget -Path $stagingDir -Operation 'manager update staging'
            [void][System.IO.Directory]::CreateDirectory($stagingDir)
            $stagingCreated = $true
            # While this update runs, the staging folder holds this marker open. A second window or the next start can then tell
            # a running update from one that was cut off (the marker of a cut-off update is no longer held open).
            $stagingLock = [System.IO.File]::Open((Join-Path $stagingDir '.tpm-update-running'), [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)
            $entryHashes = @{}
            Expand-ZipFileSafe -ZipPath $downloadedZipPath -DestDir $stagingDir -GameName 'TeknoParrot Manager update' -EntryHashes $entryHashes
            foreach ($packageFile in $packageFiles) {
                $stagedFile = Join-Path $stagingDir $packageFile.Path
                if (-not (Test-Path -LiteralPath $stagedFile -PathType Leaf) -or (Get-Item -LiteralPath $stagedFile -Force).Length -ne $packageFile.Length) {
                    throw "The unpacked file '$($packageFile.Path)' is missing or the wrong size."
                }
            }
            $stagedScript = Join-Path $stagingDir 'TeknoParrot-Manager.ps1'
            Test-ManagerUpdateExtractedScript -Path $stagedScript | Out-Null
            $candidateVersion = Get-ManagerScriptVersionIdentityFromContent -Content ([System.Text.Encoding]::UTF8.GetString([System.IO.File]::ReadAllBytes($stagedScript)))
            if ([string]::IsNullOrWhiteSpace([string]$candidateVersion)) {
                $reasonCode = 'UPDATE_VERSION_MISSING'
                throw 'The approved update did not contain a readable version.'
            }
            if ((Compare-ManagerVersionText -VersionTextA $candidateVersion -VersionTextB ([string]$Release.TagName)) -ne 0) {
                $reasonCode = 'UPDATE_VERSION_MISMATCH'
                throw 'The approved update version did not match the release being installed.'
            }
            if ((Compare-ManagerVersionText -VersionTextA $candidateVersion -VersionTextB ([string]$preState.Version)) -le 0) {
                $reasonCode = 'UPDATE_VERSION_NOT_NEWER'
                throw 'The approved update is not newer than the installed version.'
            }
            $plan = Get-ManagerUpdateInstallPlan -ProgramDir $programDir -StagingDir $stagingDir -Files $packageFiles
            Assert-TpmWritePathsShortEnough -Paths @($plan.Install | ForEach-Object { Join-Path $programDir $_.Path })
            # The checksums taken while each file was written to staging must equal the staged files: a file damaged on its way to
            # disk (a bad write, a scanner touching it) is never installed.
            foreach ($planned in $plan.Install) {
                $readHash = [string]$entryHashes[([string]$planned.Path).ToLowerInvariant()]
                if ([string]::IsNullOrEmpty($readHash) -or $readHash -ine [string]$planned.NewHash) {
                    throw "The unpacked file '$($planned.Path)' is not the same as the data read from the update."
                }
            }
            $candidateHash = @($plan.Install | Where-Object { $_.Path -ieq 'TeknoParrot-Manager.ps1' })[0].NewHash
            $leftInPlace = @(Get-ManagerUpdateLeftInPlace -ProgramDir $programDir -Files $packageFiles)
            $multiDetails = [pscustomobject]@{
                PackageFileCount = $packageFiles.Count
                NewFiles = @($plan.Install | Where-Object { $_.Kind -eq 'New' } | ForEach-Object { $_.Path })
                ReplacedFiles = @($plan.Install | Where-Object { $_.Kind -eq 'Changed' } | ForEach-Object { $_.Path })
                IdenticalFileCount = $plan.IdenticalCount
                LeftInPlace = $leftInPlace
                BackupFolder = $null
            }
            if ($leftInPlace.Count -gt 0) {
                Write-Log ("CheckForUpdates: {0} older file(s) are not in the new package and were left in place: {1}" -f $leftInPlace.Count, ($leftInPlace -join ', '))
                Write-Host ("  {0} older file(s) are not part of this release. They are left where they are." -f $leftInPlace.Count) -ForegroundColor DarkGray
            }
        }
        try {
            $readOnlyCleared = [bool](Assert-ManagerUpdateTargetWritable -Path $ScriptPath)
        } catch {
            $reasonCode = 'UPDATE_TARGET_NOT_WRITABLE'
            throw 'The manager script could not be prepared safely for the approved update.'
        }
        if ($readOnlyCleared) {
            Write-Host '  TeknoParrot Manager temporarily cleared file protection for this approved update.' -ForegroundColor DarkGray
        }
        $backupPath = New-ManagerUpdateBackup -Path $ScriptPath
        $backupInfo = [pscustomobject]@{
            Required = $true
            Attempted = $true
            Created = [bool](Test-Path -LiteralPath $backupPath -PathType Leaf)
            Verified = $false
            RootPath = $backupPath
            Items = @('manager-script')
            FailureStage = 'BackupVerification'
            FailureCode = 'UPDATE_BACKUP_HASH_MISMATCH'
        }
        if (-not $backupInfo.Created) { throw 'The manager script backup could not be verified.' }
        $backupHash = (Get-FileHash -LiteralPath $backupPath -Algorithm SHA256 -ErrorAction Stop).Hash
        if ($backupHash -ine [string]$preState.Sha256) { throw 'The manager script backup hash did not match the captured pre-state.' }
        $backupInfo.Verified = $true
        $backupInfo.FailureStage = $null
        $backupInfo.FailureCode = $null
        Write-Log "CheckForUpdates: verified manager-script backup at $backupPath"
        if ($multiFile) {
            $backupDir = [System.IO.Path]::GetDirectoryName($backupPath)
            $multiDetails.BackupFolder = $backupDir
            # New-ManagerUpdateBackup saved the main script; every other file the update replaces goes into the same folder.
            foreach ($changed in @($plan.Install | Where-Object { $_.Kind -eq 'Changed' -and $_.Path -ine 'TeknoParrot-Manager.ps1' })) {
                $installedFile = Join-Path $programDir $changed.Path
                $backupFile = Join-Path $backupDir $changed.Path
                Assert-TpmNoReparseWriteTarget -Path $backupFile -Operation 'Manager update backup copy'
                [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($backupFile))
                [System.IO.File]::Copy($installedFile, $backupFile, $false)
                if ((Get-FileHash -LiteralPath $backupFile -Algorithm SHA256 -ErrorAction Stop).Hash -ine $changed.OldHash) {
                    throw "Backup verification failed (hash mismatch): $backupFile"
                }
                if ([bool](Assert-ManagerUpdateTargetWritable -Path $installedFile)) { [void]$readOnlyPaths.Add($installedFile) }
            }
            Write-Log ("CheckForUpdates: verified backup of {0} replaced file(s) at {1}" -f @($plan.Install | Where-Object { $_.Kind -eq 'Changed' }).Count, $backupDir)
            Write-Host ("  Backed up {0} file(s) to {1}" -f @($plan.Install | Where-Object { $_.Kind -eq 'Changed' }).Count, $backupDir) -ForegroundColor DarkGray
            $installNames = @($plan.Install | ForEach-Object { $_.Path })
            # Runs inside the promotion: a thrown error here rolls every file back.
            $commitCheck = {
                foreach ($installedItem in $plan.Install) {
                    $installedHash = (Get-FileHash -LiteralPath (Join-Path $programDir $installedItem.Path) -Algorithm SHA256 -ErrorAction Stop).Hash
                    if ($installedHash -ine $installedItem.NewHash) { throw "The installed file '$($installedItem.Path)' does not match the update." }
                }
                $installedState = Get-ManagerUpdatePreState -Path $ScriptPath
                if (-not $installedState.Captured -or (Compare-ManagerVersionText -VersionTextA ([string]$installedState.Version) -VersionTextB ([string]$Release.TagName)) -ne 0) {
                    throw 'The installed manager script version did not match the approved release.'
                }
            }
            $promoteCalled = $true
            try {
                [void](Invoke-TpmTransactionalPromote -StagingDir $stagingDir -DestDir $programDir -FileNames $installNames -CommitAction $commitCheck)
            } catch {
                # Everything is installed and checked; only the helper's own scratch folder could not be removed. The
                # staging folder removal in finally tries again and reports what is left.
                if ($_.Exception.Message -cnotmatch 'CLEANUP FAILED AFTER VERIFIED PROMOTION') { throw }
                Write-Log ("CheckForUpdates: {0}" -f $_.Exception.Message)
            }
            $mutationStarted = $true
            $finalChecks = @('Every installed file matches the update.', 'Installed manager script version matches the approved release.')
        } else {
            # Stage beside the script (same volume) so the final Move-Item is one rename, never a copy-then-delete that a crash could leave half written.
            $extractedScriptPath = Join-Path ([System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($ScriptPath))) ("tpm-update-extracted-" + [guid]::NewGuid().ToString('N') + '.ps1')
            Expand-ManagerUpdateAsset -ZipPath $downloadedZipPath -EntryName 'TeknoParrot-Manager.ps1' -DestinationPath $extractedScriptPath | Out-Null
            Test-ManagerUpdateExtractedScript -Path $extractedScriptPath | Out-Null
            $candidateBytes = [System.IO.File]::ReadAllBytes($extractedScriptPath)
            $candidateContent = [System.Text.Encoding]::UTF8.GetString($candidateBytes)
            $candidateVersion = Get-ManagerScriptVersionIdentityFromContent -Content $candidateContent
            if ([string]::IsNullOrWhiteSpace([string]$candidateVersion)) {
                $reasonCode = 'UPDATE_VERSION_MISSING'
                throw 'The approved update did not contain a readable version.'
            }
            if ((Compare-ManagerVersionText -VersionTextA $candidateVersion -VersionTextB ([string]$Release.TagName)) -ne 0) {
                $reasonCode = 'UPDATE_VERSION_MISMATCH'
                throw 'The approved update version did not match the release being installed.'
            }
            $candidateHash = (Get-FileHash -LiteralPath $extractedScriptPath -Algorithm SHA256 -ErrorAction Stop).Hash
            $mutationAttempted = $true
            Assert-TpmNoReparseWriteTarget -Path $ScriptPath -Operation 'temp-then-move final write (Invoke-ManagerUpdateInstall)'
            Move-Item -LiteralPath $extractedScriptPath -Destination $ScriptPath -Force -ErrorAction Stop
            $mutationStarted = $true
            $extractedScriptPath = $null
            $installedState = Get-ManagerUpdatePreState -Path $ScriptPath
            if (-not $installedState.Captured -or $installedState.Sha256 -ine $candidateHash) {
                $reasonCode = 'UPDATE_FINAL_HASH_MISMATCH'
                throw 'The installed manager script did not match the validated update.'
            }
            if ((Compare-ManagerVersionText -VersionTextA ([string]$installedState.Version) -VersionTextB ([string]$Release.TagName)) -ne 0) {
                $reasonCode = 'UPDATE_FINAL_VERSION_MISMATCH'
                throw 'The installed manager script version did not match the approved release.'
            }
            $finalChecks = @('Installed manager script exists.', 'Installed manager script hash matches the validated update.', 'Installed manager script version matches the approved release.')
        }
        $finalAttempted = $true
        $finalPassed = $true
        $outcome = 'SUCCEEDED'
        $productState = 'INTENDED'
        $reasonCode = 'UPDATE_INSTALLED_VERIFIED'
        $summary = 'The update was installed and verified. Restart TeknoParrot Manager to use it.'
        Write-Host '  Update installed and verified. Restart TeknoParrot Manager to use it.' -ForegroundColor Green
        Write-Log "CheckForUpdates: verified update installation for $($Release.TagName)."
    } catch {
        $redactedError = [string]$_.Exception.Message
        [void]$errors.Add($redactedError)
        Write-Log "CheckForUpdates: update transaction stopped -- $redactedError. Backup: $(if ($backupPath) { $backupPath } else { 'none' })"
        if ($mutationAttempted) {
            $currentState = Get-ManagerUpdatePreState -Path $ScriptPath
            if (-not $currentState.Captured -or $currentState.Sha256 -ne [string]$preState.Sha256) { $mutationStarted = $true }
        }
        if ($promoteCalled) {
            # Invoke-TpmTransactionalPromote restores every file itself; here the result is only checked against the plan.
            $mutationStarted = $true
            if ($redactedError -cmatch 'ROLLBACK FAILED') { $stagingPreserved = $true }
            $unrestored = if ($stagingPreserved) { @('see the rollback error') } else { @(Get-ManagerUpdateUnrestoredFiles -ProgramDir $programDir -Install $plan.Install) }
            if ($unrestored.Count -eq 0) {
                $rollback = [pscustomobject]@{
                    Attempted = $true; Completed = $true; Verified = $true
                    VerifiedUtc = (Get-Date).ToUniversalTime().ToString('o')
                    Items = @('manager-script'); EvidenceRoot = $backupDir; FailedItems = @(); Errors = @()
                }
                $outcome = 'ROLLED_BACK_VERIFIED'
                $productState = 'UNCHANGED'
                $reasonCode = 'UPDATE_ROLLBACK_VERIFIED'
                $summary = 'The update was not installed. TeknoParrot Manager put every file back the way it was.'
                $finalAttempted = $true
                $finalPassed = $true
                $finalChecks = @('Every replaced file matches its backup and every added file was removed again.')
            } else {
                $rollback = [pscustomobject]@{
                    Attempted = $true; Completed = $false; Verified = $false
                    VerifiedUtc = (Get-Date).ToUniversalTime().ToString('o')
                    Items = @('manager-script'); EvidenceRoot = $backupDir; FailedItems = @('manager-script'); Errors = @($unrestored | Select-Object -First 20)
                }
                $outcome = 'ACTION_REQUIRED'
                $productState = 'UNKNOWN'
                $reasonCode = 'UPDATE_ROLLBACK_UNVERIFIED'
                $summary = 'The update needs attention because TeknoParrot Manager could not confirm that every file was put back. Your backup is in the UpdateBackups folder next to TeknoParrot Manager. Details shows the exact folder.'
            }
        } elseif ($mutationStarted -and $backupInfo.Verified) {
            try {
                Assert-TpmNoReparseWriteTarget -Path $ScriptPath -Operation 'manager update rollback restore'
                Copy-Item -LiteralPath $backupPath -Destination $ScriptPath -Force -ErrorAction Stop
                if ($preState.IsReadOnly) { Set-ItemProperty -LiteralPath $ScriptPath -Name IsReadOnly -Value $true -ErrorAction Stop }
                $restoredState = Get-ManagerUpdatePreState -Path $ScriptPath
                if (-not $restoredState.Captured -or $restoredState.Sha256 -ne [string]$preState.Sha256 -or [bool]$restoredState.IsReadOnly -ne [bool]$preState.IsReadOnly) {
                    throw 'The original manager script could not be verified after rollback.'
                }
                $rollback = [pscustomobject]@{
                    Attempted = $true
                    Completed = $true
                    Verified = $true
                    VerifiedUtc = (Get-Date).ToUniversalTime().ToString('o')
                    Items = @('manager-script')
                    EvidenceRoot = $backupPath
                    FailedItems = @()
                    Errors = @()
                }
                $outcome = 'ROLLED_BACK_VERIFIED'
                $productState = 'UNCHANGED'
                $reasonCode = 'UPDATE_ROLLBACK_VERIFIED'
                $summary = 'The update was not installed. TeknoParrot Manager restored the previous manager file.'
                $finalAttempted = $true
                $finalPassed = $true
                $finalChecks = @('The original manager script hash and file-protection state were restored.')
            } catch {
                [void]$errors.Add([string]$_.Exception.Message)
                $rollback = [pscustomobject]@{
                    Attempted = $true
                    Completed = $false
                    Verified = $false
                    VerifiedUtc = (Get-Date).ToUniversalTime().ToString('o')
                    Items = @('manager-script')
                    EvidenceRoot = $backupPath
                    FailedItems = @('manager-script')
                    Errors = @([string]$_.Exception.Message)
                }
                $outcome = 'ACTION_REQUIRED'
                $productState = 'UNKNOWN'
                $reasonCode = 'UPDATE_ROLLBACK_UNVERIFIED'
                $summary = 'The update needs attention because TeknoParrot Manager could not verify which manager file is active.'
            }
        } elseif ($mutationStarted) {
            $outcome = 'ACTION_REQUIRED'
            $productState = 'UNKNOWN'
            $reasonCode = 'UPDATE_POST_MUTATION_UNVERIFIED'
            $summary = 'The update needs attention because TeknoParrot Manager could not verify which manager file is active.'
        } else {
            $outcome = 'FAILED_BEFORE_MUTATION'
            $productState = 'UNCHANGED'
            if ($reasonCode -eq 'UPDATE_PACKAGE_HAS_NO_SCRIPT') {
                $summary = 'The update was not installed because there is no script in this release. Your current TeknoParrot Manager was not changed. Try again later, or download the latest release ZIP from the TeknoParrot Manager GitHub releases page.'
            } elseif ($reasonCode -eq 'UPDATE_PACKAGE_BAD_ENTRY') {
                $summary = 'The update was not installed because the downloaded package has a file name that is not safe. Your current TeknoParrot Manager was not changed. Try again later. If it keeps happening, see the TeknoParrot Manager GitHub releases page.'
            } elseif ($reasonCode -eq 'UPDATE_NOT_ENOUGH_DISK_SPACE') {
                $summary = 'The update was not installed because there is not enough free space on this drive. Free up some space and try again. Your current TeknoParrot Manager was not changed.'
            } elseif ($reasonCode -eq 'UPDATE_VERSION_NOT_NEWER') {
                $summary = 'The update was not installed because the downloaded release is not newer than the version you have. Your current TeknoParrot Manager was not changed.'
            } elseif ($reasonCode -eq 'UPDATE_DIGEST_UNAVAILABLE') {
                $summary = 'The update was not installed because TeknoParrot Manager could not check it against the published file. Your current TeknoParrot Manager was not changed. Try again later, or download the latest release ZIP manually from the TeknoParrot Manager GitHub releases page.'
            } elseif ($reasonCode -eq 'UPDATE_DIGEST_MISMATCH') {
                $summary = 'The update was not installed because the downloaded file is not the same as the published file. It may be damaged. Your current TeknoParrot Manager was not changed. Try again, or download the latest release ZIP manually from the TeknoParrot Manager GitHub releases page.'
            } else {
                $summary = 'The update was not installed. Your current TeknoParrot Manager was not changed.'
            }
        }
    } finally {
        if ($downloadedZipPath -and (Test-Path -LiteralPath $downloadedZipPath -PathType Leaf)) {
            try { Remove-Item -LiteralPath $downloadedZipPath -Force -ErrorAction Stop } catch {
                [void]$cleanupResidue.Add($downloadedZipPath)
                [void]$cleanupErrors.Add([string]$_.Exception.Message)
            }
        }
        if ($extractedScriptPath -and (Test-Path -LiteralPath $extractedScriptPath -PathType Leaf)) {
            try { Remove-Item -LiteralPath $extractedScriptPath -Force -ErrorAction Stop } catch {
                [void]$cleanupResidue.Add($extractedScriptPath)
                [void]$cleanupErrors.Add([string]$_.Exception.Message)
            }
        }
        # Let go of the "update is running" marker first: a folder whose marker is still held open would not be removed.
        if ($stagingLock) { try { $stagingLock.Dispose() } catch { } }
        # The staging folder is this run's own (unique name, created above). It holds the only copy of the original
        # files when a rollback failed, so it stays then and is listed as residue.
        if ($stagingCreated -and (Test-Path -LiteralPath $stagingDir)) {
            if ($stagingPreserved) {
                [void]$cleanupResidue.Add($stagingDir)
            } else {
                try { Remove-Item -LiteralPath $stagingDir -Recurse -Force -ErrorAction Stop } catch {
                    [void]$cleanupResidue.Add($stagingDir)
                    [void]$cleanupErrors.Add([string]$_.Exception.Message)
                }
            }
        }
        foreach ($readOnlyPath in $readOnlyPaths) {
            if (Test-Path -LiteralPath $readOnlyPath -PathType Leaf) {
                try { Set-ItemProperty -LiteralPath $readOnlyPath -Name IsReadOnly -Value $true -ErrorAction Stop } catch {
                    [void]$cleanupErrors.Add([string]$_.Exception.Message)
                }
            }
        }
        if ($readOnlyCleared -and (Test-Path -LiteralPath $ScriptPath -PathType Leaf)) {
            try { Set-ItemProperty -LiteralPath $ScriptPath -Name IsReadOnly -Value ([bool]$preState.IsReadOnly) -ErrorAction Stop } catch {
                [void]$cleanupErrors.Add([string]$_.Exception.Message)
            }
        }
    }
    $cleanup = [pscustomobject]@{
        Attempted = $true
        Completed = ($cleanupResidue.Count -eq 0 -and $cleanupErrors.Count -eq 0)
        ResiduePresent = ($cleanupResidue.Count -gt 0)
        ResiduePaths = $cleanupResidue.ToArray()
        ResidueItems = $cleanupResidue.ToArray()
        Error = if ($cleanupErrors.Count -gt 0) { $cleanupErrors -join '; ' } else { $null }
    }
    if ($cleanupResidue.Count -gt 0 -and $outcome -eq 'SUCCEEDED') {
        $summary = 'The update was installed and verified, but temporary update evidence remains.'
    } elseif ($cleanupErrors.Count -gt 0 -and $outcome -eq 'SUCCEEDED') {
        # Cleanup could not be completed, so the result cannot be SUCCEEDED; ProductState stays INTENDED because the new file is installed, and callers restart on that.
        $outcome = 'ACTION_REQUIRED'
        $summary = 'The update was installed and verified, but TeknoParrot Manager could not complete all cleanup checks. Restart TeknoParrot Manager to run the new version.'
        [void]$warnings.Add('Manager update cleanup or file-protection restoration requires attention.')
    }
    $technical = [pscustomobject]@{
        ReleaseTag = [string]$Release.TagName
        AssetName = [string]$Release.AssetName
        BackupPath = $backupPath
        PreState = $preState
        CandidateHash = $candidateHash
        MultiFile = $multiDetails
        CleanupErrors = $cleanupErrors.ToArray()
    }
    return New-TpmManagerUpdateTransactionResult `
        -Outcome $outcome `
        -ProductState $productState `
        -Summary $summary `
        -PreState $preState `
        -Backup $backupInfo `
        -Rollback $rollback `
        -Cleanup $cleanup `
        -MutationStarted:$mutationStarted `
        -MutationCompleted:($productState -eq 'INTENDED') `
        -FinalAttempted:$finalAttempted `
        -FinalPassed:$finalPassed `
        -FinalChecks $finalChecks `
        -ReasonCode $reasonCode `
        -TechnicalDetails $technical `
        -Errors $errors.ToArray() `
        -Warnings $warnings.ToArray()
}

# The "Updating will:" list shown before the user confirms an update (menu and startup check).
function Write-ManagerUpdatePlan {
    Write-Host "  Updating will:" -ForegroundColor Cyan
    Write-Host "    1) Download the update and check that it is the real file"
    Write-Host "    2) Check what is inside it"
    Write-Host "    3) Back up every file it replaces"
    Write-Host "    4) Install it and check it. Then you restart TeknoParrot Manager yourself"
}

# The "no update" answer of Check for Updates in plain words. Equal versions: one sentence. A version newer than the
# latest public release says so, instead of two version rows that seem to contradict each other.
function Write-TpmUpToDateNotice {
    param([Parameter(Mandatory)][string]$CurrentDisplay, [Parameter(Mandatory)][string]$LatestDisplay, [Parameter(Mandatory)][int]$Comparison)
    Write-TpmText -Text ('You have the newest version ({0}).' -f $CurrentDisplay) -Color Green
    Write-TpmText -Text 'No update needed.' -Color Green
    if ($Comparison -gt 0) { Write-TpmText -Text ('The latest public release is {0}, which is older.' -f $LatestDisplay) -Color DarkGray }
}

# Compares $ScriptVersion against the latest GitHub release and, if a newer
# one exists, prints it and explains what updating will do before asking for
# explicit Y/N confirmation. Returns TPM.TransactionResult.v1 for every
# outcome; callers decide whether a restart is safe from the validated Outcome.
function Invoke-CheckForUpdates {
    param([Parameter(Mandatory)][string]$ScriptPath)
    $preState = Get-ManagerUpdatePreState -Path $ScriptPath
    Write-Host ""
    Write-Host "  Checking for updates..." -ForegroundColor DarkGray
    Write-Log "CheckForUpdates: checking current v$ScriptVersion against latest GitHub release."
    try {
        $localVersion = Get-ManagerVersionIdentity -ScriptVersion $ScriptVersion -ReleaseCandidateLabel $ReleaseCandidateLabel
    } catch {
        return New-TpmManagerUpdateTransactionResult `
            -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' `
            -Summary 'The update check could not verify the current manager version. No update was installed.' `
            -PreState $preState -ReasonCode 'UPDATE_CURRENT_VERSION_INVALID' `
            -TechnicalDetails ([pscustomobject]@{ Stage='CurrentVersion'; Error=[string]$_.Exception.Message })
    }
    $release = Get-ManagerUpdateRelease
    if (-not $release) {
        Write-Host "  Could not check for updates (GitHub was unreachable or returned no usable release). Whether a newer version exists is unknown; your current copy is unchanged." -ForegroundColor Yellow
        return New-TpmManagerUpdateTransactionResult `
            -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' `
            -Summary 'TeknoParrot Manager could not check for updates, so it is unknown whether a newer version exists. Your current TeknoParrot Manager is unchanged.' `
            -PreState $preState -ReasonCode 'UPDATE_RELEASE_UNAVAILABLE' `
            -TechnicalDetails ([pscustomobject]@{ Stage='ReleaseQuery' })
    }
    try {
        $versionComparison = Compare-ManagerVersionText -VersionTextA $localVersion -VersionTextB ([string]$release.TagName)
    } catch {
        return New-TpmManagerUpdateTransactionResult `
            -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' `
            -Summary 'The available update could not be verified. Your current TeknoParrot Manager is unchanged.' `
            -PreState $preState -ReasonCode 'UPDATE_RELEASE_VERSION_INVALID' `
            -TechnicalDetails ([pscustomobject]@{ Stage='ReleaseVersion'; Error=[string]$_.Exception.Message })
    }
    $latestDisplay = ConvertTo-ManagerDisplayVersionFromTag -VersionText $release.TagName
    Write-Log ("CheckForUpdates: current {0}, latest {1}, comparison {2}." -f (Get-ManagerDisplayVersion), $latestDisplay, $versionComparison)
    Write-Host ""
    if ($versionComparison -ge 0) {
        Write-TpmUpToDateNotice -CurrentDisplay (Get-ManagerDisplayVersion) -LatestDisplay $latestDisplay -Comparison $versionComparison
        return New-TpmManagerUpdateTransactionResult `
            -Outcome 'NO_OP' -ProductState 'UNCHANGED' `
            -Summary 'Your current TeknoParrot Manager is already up to date. Nothing needed changing.' `
            -PreState $preState -FinalAttempted:$true -FinalPassed:$true `
            -FinalChecks @('The current manager script was read and hashed before the update check.') `
            -ReasonCode 'UPDATE_ALREADY_CURRENT' `
            -TechnicalDetails ([pscustomobject]@{ Stage='ReleaseComparison'; CurrentVersion=$localVersion; LatestVersion=$release.TagName })
    }
    Write-Host ("  An update is available: $(Get-ManagerDisplayVersion) -> $latestDisplay") -ForegroundColor Yellow
    Write-Host ""
    Write-ManagerUpdatePlan
    Write-Host ""
    $ans = Read-TpmYesNo -Prompt "  Update to $latestDisplay now? (Y/N)"
    if ($ans -ne "Y") {
        Write-Host "  Skipped -- no changes made." -ForegroundColor DarkGray
        return New-TpmManagerUpdateTransactionResult `
            -Outcome 'NO_OP' -ProductState 'UNCHANGED' `
            -Summary 'No update was installed. Your current TeknoParrot Manager is unchanged.' `
            -PreState $preState -FinalAttempted:$true -FinalPassed:$true `
            -FinalChecks @('The current manager script remained unchanged after the declined update.') `
            -ReasonCode 'UPDATE_DECLINED' `
            -TechnicalDetails ([pscustomobject]@{ Stage='Confirmation'; ReleaseTag=$release.TagName })
    }
    return Invoke-TpmProgressGroup -Title 'Manager update install' -Action { Invoke-ManagerUpdateInstall -ScriptPath $ScriptPath -Release $release }
}

# Quiet, opt-in (CheckForUpdatesOnStartup, default true) startup update
# check. Uses a single short-timeout attempt (Get-ManagerUpdateRelease
# -MaxAttempts 1 -TimeoutSec 5) so an unreachable GitHub cannot noticeably
# delay launching the script -- unlike the menu option, nobody explicitly
# asked for this check, so it must not be allowed to hang. Never prompts,
# logs, or writes anything when already current. When a newer release
# exists, shows current/latest/a one-line release summary and offers
# Y (update now) / N (remind me later) / V (view full release notes, then
# re-prompt). Shares Invoke-ManagerUpdateInstall with the menu option for
# the actual backup-first install; never calls exit itself for the same
# testability reason documented there -- the caller (top-level script code)
# decides whether to exit after a successful install.
function Invoke-StartupUpdateCheck {
    param([Parameter(Mandatory)][string]$ScriptPath)
    $preState = Get-ManagerUpdatePreState -Path $ScriptPath
    try {
        $localVersion = Get-ManagerVersionIdentity -ScriptVersion $ScriptVersion -ReleaseCandidateLabel $ReleaseCandidateLabel
    } catch {
        return New-TpmManagerUpdateTransactionResult `
            -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' `
            -Summary 'The startup update check could not verify the current manager version. No update was installed.' `
            -PreState $preState -ReasonCode 'UPDATE_CURRENT_VERSION_INVALID' `
            -TechnicalDetails ([pscustomobject]@{ Stage='StartupCurrentVersion'; Error=[string]$_.Exception.Message })
    }
    $release = Get-ManagerUpdateRelease -MaxAttempts 1 -TimeoutSec 5
    if (-not $release) {
        return New-TpmManagerUpdateTransactionResult `
            -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' `
            -Summary 'TeknoParrot Manager could not check for updates, so it is unknown whether a newer version exists. Your current TeknoParrot Manager is unchanged.' `
            -PreState $preState -ReasonCode 'UPDATE_RELEASE_UNAVAILABLE' `
            -TechnicalDetails ([pscustomobject]@{ Stage='StartupReleaseQuery' })
    }
    try {
        $versionComparison = Compare-ManagerVersionText -VersionTextA $localVersion -VersionTextB ([string]$release.TagName)
    } catch {
        return New-TpmManagerUpdateTransactionResult `
            -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' `
            -Summary 'The available update could not be verified. Your current TeknoParrot Manager is unchanged.' `
            -PreState $preState -ReasonCode 'UPDATE_RELEASE_VERSION_INVALID' `
            -TechnicalDetails ([pscustomobject]@{ Stage='StartupReleaseVersion'; Error=[string]$_.Exception.Message })
    }
    if ($versionComparison -ge 0) {
        Write-Log "StartupUpdateCheck: already current (v$ScriptVersion)."
        return New-TpmManagerUpdateTransactionResult `
            -Outcome 'NO_OP' -ProductState 'UNCHANGED' `
            -Summary 'Your current TeknoParrot Manager is already up to date. Nothing needed changing.' `
            -PreState $preState -FinalAttempted:$true -FinalPassed:$true `
            -FinalChecks @('The current manager script was read and hashed before the startup update check.') `
            -ReasonCode 'UPDATE_ALREADY_CURRENT' `
            -TechnicalDetails ([pscustomobject]@{ Stage='StartupReleaseComparison'; CurrentVersion=$localVersion; LatestVersion=$release.TagName })
    }
    $latestDisplay = ConvertTo-ManagerDisplayVersionFromTag -VersionText $release.TagName
    Write-Host ""
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Write-Host " Update Available" -ForegroundColor Cyan
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Write-Host ("  Current version : {0}" -f (Get-ManagerDisplayVersion)) -ForegroundColor Cyan
    Write-Host ("  Latest version  : {0}" -f $latestDisplay) -ForegroundColor Cyan
    if ($release.Name) { Write-Host ("  Release         : {0}" -f $release.Name) -ForegroundColor Cyan }
    $releaseSummary = Get-ManagerUpdateReleaseSummary -Body $release.Body
    if ($releaseSummary) {
        Write-Host ""
        Write-Host "  $releaseSummary" -ForegroundColor DarkGray
    }
    Write-Log "StartupUpdateCheck: update available (v$ScriptVersion -> $($release.TagName))."
    Write-Host ""
    Write-ManagerUpdatePlan
    Write-Host ""
    Write-Host "  Y = Update now (starts right away)" -ForegroundColor Cyan
    Write-Host "  N = Remind me later (keep this version for now)" -ForegroundColor Cyan
    Write-Host "  V = View release notes (see what changed, then choose again)" -ForegroundColor Cyan
    while ($true) {
        $ans = Read-TpmChoice -Prompt "  Your choice (Y/N/V)" -Choices @('Y', 'N', 'V') -Default 'N'
        if ($ans -eq 'V') {
            Write-Host ""
            if ($release.Body) { Write-Host $release.Body -ForegroundColor DarkGray } else { Write-Host '  No release notes were provided for this release.' -ForegroundColor DarkGray }
            Write-Host ""
            continue
        }
        if ($ans -eq 'Y') {
            return Invoke-TpmProgressGroup -Title 'Manager update install' -Action { Invoke-ManagerUpdateInstall -ScriptPath $ScriptPath -Release $release }
        }
        if ($ans -eq 'N') {
            Write-Host '  Continuing -- you can check again any time from the menu.' -ForegroundColor DarkGray
            return New-TpmManagerUpdateTransactionResult `
                -Outcome 'NO_OP' -ProductState 'UNCHANGED' `
                -Summary 'No update was installed. Your current TeknoParrot Manager is unchanged.' `
                -PreState $preState -FinalAttempted:$true -FinalPassed:$true `
                -FinalChecks @('The current manager script remained unchanged after the startup reminder choice.') `
                -ReasonCode 'UPDATE_REMIND_LATER' `
                -TechnicalDetails ([pscustomobject]@{ Stage='StartupChoice'; ReleaseTag=$release.TagName })
        }
        Write-Host '  Invalid choice. Enter Y, N, or V.' -ForegroundColor Yellow
    }
}

# =============================================================================
# DURABLE REGISTRATION LEDGER, RUNTIME IDENTITY AND SUPPORT EVIDENCE (#352/#365)
# One workflow-local JSON ledger under the managed State folder; no database,
# worker or event framework. A selected extraction/registration mutation may
# start only after the complete intended manifest is published and read back.
# An unreadable, corrupt, unsafe, oversized or unpublishable ledger refuses new
# mutations and leaves the previous file untouched. The one deliberate trim: a
# full ledger drops its oldest COMPLETED runs (never unfinished or current ones)
# and counts them in TrimmedOperations, so the loss is visible in the file.
# Timestamps use a compact UTC form
# (yyyyMMddTHHmmss.fffZ) so ConvertFrom-Json never rewrites them as dates.
# =============================================================================
function Get-TpmLedgerTimestamp {
    return (Get-Date).ToUniversalTime().ToString("yyyyMMdd'T'HHmmss.fff'Z'", [System.Globalization.CultureInfo]::InvariantCulture)
}

function Get-TpmLedgerText {
    param([AllowNull()][string]$Text, [int]$Maximum = 240)
    $safe = (Redact-TpmSupportText -Text ([string]$Text)).Text
    if ($safe.Length -gt $Maximum) { $safe = $safe.Substring(0, $Maximum) + '...' }
    return $safe
}

function Set-TpmLedgerField {
    param([Parameter(Mandatory)]$Object, [Parameter(Mandatory)][string]$Name, [AllowNull()]$Value)
    if ($Object.PSObject.Properties[$Name]) { $Object.$Name = $Value }
    else { Add-Member -InputObject $Object -NotePropertyName $Name -NotePropertyValue $Value -Force }
}

function Get-TpmRegistrationLedgerPath {
    if ($script:TpmOwnedLayout -and $script:TpmOwnedLayout.State) { return (Join-Path ([string]$script:TpmOwnedLayout.State) 'TPM-RegistrationLedger.json') }
    return ''
}

function New-TpmRegistrationLedgerDocument {
    return [pscustomobject][ordered]@{ SchemaVersion = 1; Sequence = [int64]0; UpdatedUtc = ''; Operations = @(); Fatals = @() }
}

function Get-TpmLedgerRelativePath {
    param([string]$Path, [string]$Root)
    if ([string]::IsNullOrWhiteSpace($Path)) { return [pscustomobject]@{ Base = 'None'; Path = '' } }
    try {
        $full = [System.IO.Path]::GetFullPath($Path)
        if (-not [string]::IsNullOrWhiteSpace($Root)) {
            $rootFull = [System.IO.Path]::GetFullPath($Root).TrimEnd('\', '/')
            if ($full.StartsWith($rootFull + '\', [System.StringComparison]::OrdinalIgnoreCase)) {
                return [pscustomobject]@{ Base = 'InstallRoot'; Path = $full.Substring($rootFull.Length + 1) }
            }
        }
        return [pscustomobject]@{ Base = 'Absolute'; Path = $full }
    } catch { return [pscustomobject]@{ Base = 'Absolute'; Path = [string]$Path } }
}

function Get-TpmRegistrationLedgerRefusal {
    param([string]$Status, [string]$Path, [string]$Detail, [switch]$ForSummary)
    # A transaction Summary must not carry a filesystem path; the console/log message keeps the location.
    $where = if ($Path -and -not $ForSummary) { ConvertTo-TpmDisplayPath $Path } else { 'the managed State folder' }
    # The summary variant keeps the status word (callers and users need it) but drops a detail that
    # carries a path or other technical text; the console/log message keeps the full detail.
    $detailText = $Detail
    if ($ForSummary -and -not [string]::IsNullOrWhiteSpace($Detail) -and -not (Test-TpmTransactionUserSafeSummary -Summary $Detail)) { $detailText = 'details are in the log' }
    return ('Action required: the registration evidence ledger is {0} ({1}) at {2}. No game extraction or registration was started, and the existing ledger was not changed. TeknoParrot Manager does not delete or change a ledger it cannot use: keep that file as it is, create a support package, and ask for help before running again.' -f $Status.ToLowerInvariant(), $detailText, $where)
}

# Returns Status = Missing | Ok | Unreadable | Corrupt | Unsafe | Oversized.
function Read-TpmRegistrationLedger {
    param([Parameter(Mandatory)][string]$Path, [int]$MaximumBytes = 1048576)
    $read = [pscustomobject]@{ Status = 'Missing'; Document = $null; Message = ''; Bytes = [int64]0; Sha256 = '' }
    $bytes = $null
    try {
        if (-not (Test-TpmNoReparsePath -Path $Path)) { $read.Status = 'Unsafe'; $read.Message = 'the ledger path is reparse-backed or unsafe'; return $read }
        if (-not (Test-Path -LiteralPath $Path -ErrorAction Stop)) { return $read }
        $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        if ($item.PSIsContainer) { $read.Status = 'Unsafe'; $read.Message = 'the ledger path is a directory'; return $read }
        $read.Bytes = [int64]$item.Length
        if ($item.Length -gt $MaximumBytes) { $read.Status = 'Oversized'; $read.Message = ('{0} bytes exceeds the {1}-byte limit' -f $item.Length, $MaximumBytes); return $read }
        $bytes = [System.IO.File]::ReadAllBytes($Path)
    } catch {
        $read.Status = 'Unreadable'; $read.Message = (Get-TpmLedgerText $_.Exception.Message 160); return $read
    }
    try {
        $sha = [System.Security.Cryptography.SHA256]::Create()
        try { $read.Sha256 = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-', '') } finally { $sha.Dispose() }
        $text = (New-Object System.Text.UTF8Encoding($false, $true)).GetString($bytes).TrimStart([char]0xFEFF)
        $doc = $text | ConvertFrom-Json -ErrorAction Stop
        $shapeOk = ($null -ne $doc -and $null -ne $doc.PSObject.Properties['SchemaVersion'] -and [int]$doc.SchemaVersion -eq 1 -and
            $null -ne $doc.PSObject.Properties['Sequence'] -and $null -ne $doc.PSObject.Properties['Operations'] -and $null -ne $doc.PSObject.Properties['Fatals'] -and
            $null -ne $doc.Operations -and $null -ne $doc.Fatals)
        if (-not $shapeOk) { throw 'the document is not a version 1 registration ledger' }
        $doc.Operations = @($doc.Operations | Where-Object { $null -ne $_ })
        $doc.Fatals = @($doc.Fatals | Where-Object { $null -ne $_ })
        foreach ($op in $doc.Operations) {
            if ($null -eq $op.PSObject.Properties['OperationId'] -or $null -eq $op.PSObject.Properties['Units'] -or $null -eq $op.PSObject.Properties['Mappings'] -or $null -eq $op.Units -or $null -eq $op.Mappings) { throw 'an operation record is incomplete' }
            $op.Units = @($op.Units | Where-Object { $null -ne $_ })
            $op.Mappings = @($op.Mappings | Where-Object { $null -ne $_ })
        }
        $read.Document = $doc
        $read.Status = 'Ok'
    } catch {
        $read.Status = 'Corrupt'; $read.Message = (Get-TpmLedgerText $_.Exception.Message 160)
    }
    return $read
}

# Atomic same-directory publish: projected-size check, temp write + flush,
# Replace/Move, then length + SHA-256 read-back. Never deletes the prior file.
function Publish-TpmRegistrationLedgerDocument {
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)]$Document, [int]$MaximumBytes = 1048576)
    $outcome = [pscustomobject]@{ Published = $false; Reason = ''; Bytes = 0 }
    $tmp = $null
    try {
        $Document.Sequence = [int64]$Document.Sequence + 1
        $Document.UpdatedUtc = Get-TpmLedgerTimestamp
        $bytes = (New-Object System.Text.UTF8Encoding($false)).GetBytes((($Document | ConvertTo-Json -Depth 10 -Compress)) + "`r`n")
        # A full ledger drops its oldest finished runs, then its oldest interrupted runs, instead of refusing every later run. Runs still in progress in this session and current runs are kept. Each drop is counted in TrimmedOperations.
        $activeIds = if ($script:TpmRegistrationLedger) { @($script:TpmRegistrationLedger.ActiveIds) } else { @() }
        $trimmedCount = if ($Document.PSObject.Properties['TrimmedOperations']) { [int64]$Document.TrimmedOperations } else { [int64]0 }
        while ($bytes.Length -gt $MaximumBytes) {
            $oldest = @($Document.Operations | Where-Object { [string]$_.State -eq 'COMPLETED' -and $activeIds -notcontains [string]$_.OperationId } | Select-Object -First 1)
            # Only when no finished run is left does the oldest interrupted run go, so a full ledger can never refuse every later run.
            if ($oldest.Count -eq 0) { $oldest = @($Document.Operations | Where-Object { [string]$_.State -eq 'INTERRUPTED_UNKNOWN' -and $activeIds -notcontains [string]$_.OperationId } | Select-Object -First 1) }
            if ($oldest.Count -eq 0) { break }
            $Document.Operations = @($Document.Operations | Where-Object { -not [object]::ReferenceEquals($_, $oldest[0]) })
            $trimmedCount++
            Set-TpmLedgerField -Object $Document -Name 'TrimmedOperations' -Value $trimmedCount
            Write-Log ("Registration ledger is full: dropped the oldest finished run '{0}' ({1} dropped so far)." -f [string]$oldest[0].OperationId, $trimmedCount)
            $bytes = (New-Object System.Text.UTF8Encoding($false)).GetBytes((($Document | ConvertTo-Json -Depth 10 -Compress)) + "`r`n")
        }
        $outcome.Bytes = $bytes.Length
        if ($bytes.Length -gt $MaximumBytes) { $outcome.Reason = ('projected ledger is {0} bytes, over the {1}-byte limit; nothing was written' -f $bytes.Length, $MaximumBytes); return $outcome }
        $parent = [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($Path))
        if (-not (Test-Path -LiteralPath $parent -PathType Container)) { [void][System.IO.Directory]::CreateDirectory($parent) }
        Assert-TpmNoReparseWriteTarget -Path $Path -Operation 'registration ledger publication'
        $tmp = $Path + '.' + [guid]::NewGuid().ToString('N') + '.tmp'
        $stream = New-Object System.IO.FileStream($tmp, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        try { $stream.Write($bytes, 0, $bytes.Length); $stream.Flush($true) } finally { $stream.Dispose() }
        if (Test-Path -LiteralPath $Path -PathType Leaf) { [System.IO.File]::Replace($tmp, $Path, [NullString]::Value) } else { [System.IO.File]::Move($tmp, $Path) }
        $tmp = $null
        $back = [System.IO.File]::ReadAllBytes($Path)
        $same = ($back.Length -eq $bytes.Length)
        if ($same) {
            $sha = [System.Security.Cryptography.SHA256]::Create()
            try {
                $expectedHash = [BitConverter]::ToString($sha.ComputeHash($bytes))
                $actualHash = [BitConverter]::ToString($sha.ComputeHash($back))
                $same = ($expectedHash -ceq $actualHash)
            } finally { $sha.Dispose() }
        }
        if (-not $same) { $outcome.Reason = 'read-back did not match the published bytes'; return $outcome }
        $outcome.Published = $true
    } catch {
        $outcome.Reason = (Get-TpmLedgerText $_.Exception.Message 160)
    } finally {
        if ($tmp -and (Test-Path -LiteralPath $tmp -PathType Leaf)) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
    }
    return $outcome
}

function Publish-TpmRegistrationLedgerContext {
    $ctx = $script:TpmRegistrationLedger
    if ($null -eq $ctx) { return $false }
    # A second TPM window may have written to the ledger since this one read it: keep that window's runs, and let this window's own current runs win.
    $onDisk = Read-TpmRegistrationLedger -Path $ctx.Path -MaximumBytes $ctx.MaximumBytes
    if ($onDisk.Status -eq 'Ok') {
        $mine = @($ctx.Document.Operations)
        $merged = New-Object System.Collections.Generic.List[object]
        foreach ($diskOp in @($onDisk.Document.Operations)) {
            $ownOp = @($mine | Where-Object { [string]$_.OperationId -eq [string]$diskOp.OperationId -and $ctx.ActiveIds -contains [string]$_.OperationId } | Select-Object -First 1)
            [void]$merged.Add($(if ($ownOp.Count -gt 0) { $ownOp[0] } else { $diskOp }))
        }
        foreach ($ownOp in $mine) {
            $mergedIds = @($merged | ForEach-Object { [string]$_.OperationId })
            if ($mergedIds -notcontains [string]$ownOp.OperationId -and $ctx.ActiveIds -contains [string]$ownOp.OperationId) { [void]$merged.Add($ownOp) }
        }
        $ctx.Document.Operations = $merged.ToArray()
        # Crash records and the trimmed-run count written by another window must survive this window's publish.
        $fatalIds = @(@($onDisk.Document.Fatals) | ForEach-Object { [string]$_.FatalId })
        $ctx.Document.Fatals = @(@($onDisk.Document.Fatals) + @(@($ctx.Document.Fatals) | Where-Object { $fatalIds -notcontains [string]$_.FatalId }))
        $diskTrimmed = if ($onDisk.Document.PSObject.Properties['TrimmedOperations']) { [int64]$onDisk.Document.TrimmedOperations } else { [int64]0 }
        $ownTrimmed = if ($ctx.Document.PSObject.Properties['TrimmedOperations']) { [int64]$ctx.Document.TrimmedOperations } else { [int64]0 }
        if ($diskTrimmed -gt $ownTrimmed) { Set-TpmLedgerField -Object $ctx.Document -Name 'TrimmedOperations' -Value $diskTrimmed }
        if ([int64]$onDisk.Document.Sequence -gt [int64]$ctx.Document.Sequence) { $ctx.Document.Sequence = [int64]$onDisk.Document.Sequence }
    }
    # A ledger that cannot be read is never replaced: this window's own evidence stays in memory and the log, and the stop notice below is shown.
    $published = if ($onDisk.Status -in @('Ok', 'Missing')) {
        Publish-TpmRegistrationLedgerDocument -Path $ctx.Path -Document $ctx.Document -MaximumBytes $ctx.MaximumBytes
    } else {
        [pscustomobject]@{ Published = $false; Reason = ('the existing ledger file is {0} ({1}) and TeknoParrot Manager does not change a ledger it cannot use' -f ([string]$onDisk.Status).ToLowerInvariant(), [string]$onDisk.Message) }
    }
    if ($published.Published) { return $true }
    if (-not $ctx.Uncertain) {
        $ctx.Uncertain = $true
        $ctx.Stopped = $true
        $ctx.Message = ('Registration evidence could not be published ({0}). Results already known stay in this session and its log but are not durable. No further selected extraction or registration will start; nothing was rolled back or retried.' -f $published.Reason)
        $script:TpmRegistrationLedgerStopLatch = [string]$ctx.Message
        Write-Host ('  ' + $ctx.Message) -ForegroundColor Yellow
        Write-Log ('Registration ledger publication FAILED: ' + $published.Reason)
    }
    foreach ($op in @($ctx.Document.Operations | Where-Object { $ctx.ActiveIds -contains [string]$_.OperationId })) { Set-TpmLedgerField -Object $op -Name 'EvidenceStatus' -Value 'UNCERTAIN' }
    return $false
}

function Test-TpmRegistrationLedgerStopped {
    $ctx = $script:TpmRegistrationLedger
    return [bool]($script:TpmRegistrationLedgerStopLatch -or ($ctx -and $ctx.Stopped))
}

# Workflow-scoped latch: Close clears the ledger context, but a publication failure must keep
# refusing manual/duplicate/supplementary follow-ups until the next menu workflow starts.
function Reset-TpmRegistrationLedgerStopLatch {
    $script:TpmRegistrationLedgerStopLatch = $null
}

function Find-TpmLedgerUnit {
    param([Parameter(Mandatory)]$Context, [string]$Folder, $Operation = $null, [switch]$SourceNameOnly)
    if ([string]::IsNullOrWhiteSpace($Folder)) { return $null }
    $ops = if ($Operation) { @($Operation) } else { @($Context.Document.Operations | Where-Object { $Context.ActiveIds -contains [string]$_.OperationId }) }
    $passes = if ($SourceNameOnly) { @(2) } else { @(1, 2) }
    foreach ($pass in $passes) {
        foreach ($op in $ops) {
            foreach ($unit in @($op.Units)) {
                $name = if ($pass -eq 1) { [string]$unit.TargetFolder } else { [string]$unit.Folder }
                if ($name -and $name -ieq $Folder) { return [pscustomobject]@{ Operation = $op; Unit = $unit } }
            }
        }
    }
    return $null
}

function Get-TpmLedgerDerivedUnitState {
    param([object[]]$Mappings)
    $states = @($Mappings | ForEach-Object { [string]$_.State })
    if ($states.Count -eq 0) { return 'PENDING' }
    if ($states -contains 'WRITE_ATTEMPTED_UNVERIFIED') { return 'WRITE_ATTEMPTED_UNVERIFIED' }
    $verified = @($states | Where-Object { $_ -eq 'VERIFIED' }).Count
    if ($verified -eq $states.Count) { return 'VERIFIED' }
    if ($verified -gt 0) { return 'PARTIAL' }
    if ($states -contains 'FAILED_BEFORE_WRITE') { return 'FAILED_BEFORE_WRITE' }
    return 'SKIPPED'
}

# Gate + manifest freeze. Refuses (Opened = $false) without changing anything
# unless the ledger is readable/safe and the complete manifest, with prior
# open operations marked INTERRUPTED_UNKNOWN, publishes and reads back.
function Open-TpmRegistrationLedgerOperation {
    param(
        [Parameter(Mandatory)][ValidateSet('AutoSync', 'RegisterOnly', 'ManualChoice')][string]$Mode,
        [AllowEmptyCollection()][object[]]$Units = @(),
        [string]$InstallRoot = '', [string]$Path = '', [int]$MaximumBytes = 1048576
    )
    $opened = [pscustomobject]@{ Opened = $false; OperationId = ''; Status = ''; Message = ''; Summary = '' }
    $existing = $script:TpmRegistrationLedger
    if ($script:TpmRegistrationLedgerStopLatch) { $opened.Status = 'Stopped'; $opened.Message = [string]$script:TpmRegistrationLedgerStopLatch; return $opened }
    if ($existing -and $existing.Stopped) { $opened.Status = 'Stopped'; $opened.Message = [string]$existing.Message; return $opened }
    if ([string]::IsNullOrWhiteSpace($Path)) { $Path = Get-TpmRegistrationLedgerPath }
    if ([string]::IsNullOrWhiteSpace($Path)) {
        $opened.Status = 'Unavailable'
        $opened.Message = Get-TpmRegistrationLedgerRefusal -Status 'unavailable' -Path '' -Detail 'the managed State folder is not available'
        return $opened
    }
    $read = Read-TpmRegistrationLedger -Path $Path -MaximumBytes $MaximumBytes
    if ($read.Status -notin @('Ok', 'Missing')) {
        $opened.Status = [string]$read.Status
        $opened.Message = Get-TpmRegistrationLedgerRefusal -Status $read.Status -Path $Path -Detail $read.Message
        $opened.Summary = Get-TpmRegistrationLedgerRefusal -Status $read.Status -Path $Path -Detail $read.Message -ForSummary
        return $opened
    }
    $document = if ($read.Status -eq 'Ok') { $read.Document } else { New-TpmRegistrationLedgerDocument }
    $activeIds = New-Object System.Collections.Generic.List[string]
    if ($existing) { foreach ($id in @($existing.ActiveIds)) { [void]$activeIds.Add([string]$id) } }
    $now = Get-TpmLedgerTimestamp
    foreach ($prior in @($document.Operations)) {
        if ([string]$prior.State -eq 'PENDING' -and $activeIds -notcontains [string]$prior.OperationId) {
            $prior.State = 'INTERRUPTED_UNKNOWN'
            Set-TpmLedgerField -Object $prior -Name 'InterruptedUtc' -Value $now
            foreach ($priorUnit in @($prior.Units)) {
                if ([string]$priorUnit.State -in @('PENDING', 'WRITE_ATTEMPTED_UNVERIFIED')) { $priorUnit.State = 'INTERRUPTED_UNKNOWN' }
            }
        }
    }
    $unitRows = New-Object System.Collections.Generic.List[object]
    $index = 0
    foreach ($unit in @($Units)) {
        $index++
        [void]$unitRows.Add([pscustomobject][ordered]@{ UnitId = ('U{0:D4}' -f $index); Folder = [string]$unit.Folder; State = 'PENDING' })
    }
    $scriptDigest = if ($script:TpmStartupIdentity -and $script:TpmStartupIdentity.ScriptSha256) { [string]$script:TpmStartupIdentity.ScriptSha256 } else { 'unavailable' }
    $op = [pscustomobject][ordered]@{
        OperationId = [guid]::NewGuid().ToString('N'); RunId = (Get-TpmSessionRunId); Mode = $Mode
        State = 'PENDING'; EvidenceStatus = 'CURRENT'; StartedUtc = $now; CompletedUtc = ''
        Source = [pscustomobject][ordered]@{ ManagerVersion = [string](Get-ManagerDisplayVersion); ScriptSha256 = $scriptDigest }
        InstallRoot = [string]$InstallRoot
        Units = $unitRows.ToArray(); Mappings = @(); Transaction = $null
    }
    $document.Operations = @($document.Operations) + $op
    $published = Publish-TpmRegistrationLedgerDocument -Path $Path -Document $document -MaximumBytes $MaximumBytes
    if (-not $published.Published) {
        $opened.Status = 'PublishFailed'
        $opened.Message = Get-TpmRegistrationLedgerRefusal -Status 'not publishable' -Path $Path -Detail $published.Reason
        $opened.Summary = Get-TpmRegistrationLedgerRefusal -Status 'not publishable' -Path $Path -Detail $published.Reason -ForSummary
        return $opened
    }
    [void]$activeIds.Add([string]$op.OperationId)
    $script:TpmRegistrationLedger = [pscustomobject]@{ Path = $Path; Document = $document; ActiveIds = $activeIds; Stopped = $false; Uncertain = $false; Message = ''; MaximumBytes = $MaximumBytes }
    $opened.Opened = $true
    $opened.OperationId = [string]$op.OperationId
    $opened.Status = 'Ok'
    return $opened
}

# The ledger lives in the managed State folder. Production initializes that layout
# before any workflow runs; without a layout (isolated function calls) there is no
# State folder to gate on, so selected workflows run ungated and nothing is recorded.
function Test-TpmRegistrationLedgerConfigured {
    return (-not [string]::IsNullOrWhiteSpace((Get-TpmRegistrationLedgerPath)))
}

function Test-TpmRegistrationLedgerReady {
    param([bool]$AdoptActive = $false, [string]$Path = '', [int]$MaximumBytes = 1048576)
    $ctx = $script:TpmRegistrationLedger
    if ($script:TpmRegistrationLedgerStopLatch) { return [pscustomobject]@{ Ready = $false; Message = [string]$script:TpmRegistrationLedgerStopLatch } }
    if ($ctx -and $AdoptActive -and $ctx.ActiveIds.Count -gt 0) {
        if ($ctx.Stopped) { return [pscustomobject]@{ Ready = $false; Message = [string]$ctx.Message } }
        return [pscustomobject]@{ Ready = $true; Message = '' }
    }
    if ($ctx) { $script:TpmRegistrationLedger = $null }   # abandoned earlier context; its operations stay PENDING on disk
    if ([string]::IsNullOrWhiteSpace($Path)) { $Path = Get-TpmRegistrationLedgerPath }
    if ([string]::IsNullOrWhiteSpace($Path)) { return [pscustomobject]@{ Ready = $true; Message = ''; NotConfigured = $true } }   # no managed layout: production always initializes one before any workflow
    $read = Read-TpmRegistrationLedger -Path $Path -MaximumBytes $MaximumBytes
    if ($read.Status -in @('Ok', 'Missing')) { return [pscustomobject]@{ Ready = $true; Message = '' } }
    return [pscustomobject]@{ Ready = $false; Message = (Get-TpmRegistrationLedgerRefusal -Status $read.Status -Path $Path -Detail $read.Message); Summary = (Get-TpmRegistrationLedgerRefusal -Status $read.Status -Path $Path -Detail $read.Message -ForSummary) }
}

function Test-TpmAutoSyncZipSelected {
    # Mirrors the filters at the top of Invoke-AutoSync's ZIP loop so the manifest
    # covers exactly the ZIPs that loop can act on.
    param([string]$RawName, $NoSync = @(), $OnlySync = @(), [string[]]$OnlyProfileCodes = @(), $DatIndex = $null)
    if (@($NoSync) -contains $RawName) { return $false }
    if ($RawName -like '!TeknoParrot Collection*') { return $false }
    if (@($OnlySync).Count -gt 0 -and @($OnlySync) -notcontains $RawName) { return $false }
    if ($OnlyProfileCodes.Count -gt 0) {
        $entry = Get-DatEntryForZipName -RawZipName $RawName -DatIndex $DatIndex
        $code = if ($entry) { [string]$entry.ProfileCode } else { '' }
        if ($OnlyProfileCodes -notcontains $code) { return $false }
    }
    return $true
}

function Update-TpmRegistrationLedgerUnit {
    param([Parameter(Mandatory)][AllowEmptyString()][string]$OperationId, [Parameter(Mandatory)][string]$SourceName, [string]$State = '', [string]$Reason = '', [string]$Extraction = '', [string]$TargetFolder = '', [string]$Rollback = '', [switch]$Publish)
    $ctx = $script:TpmRegistrationLedger
    if ($null -eq $ctx -or [string]::IsNullOrWhiteSpace($OperationId) -or $ctx.ActiveIds -notcontains $OperationId) { return $false }
    $operation = @($ctx.Document.Operations | Where-Object { [string]$_.OperationId -eq $OperationId })[0]
    if ($null -eq $operation) { return $false }
    $found = Find-TpmLedgerUnit -Context $ctx -Folder $SourceName -Operation $operation -SourceNameOnly
    if ($null -eq $found) { return $false }
    if ($State) { $found.Unit.State = $State }
    if ($Reason) { Set-TpmLedgerField -Object $found.Unit -Name 'Reason' -Value (Get-TpmLedgerText $Reason) }
    if ($Extraction) { Set-TpmLedgerField -Object $found.Unit -Name 'Extraction' -Value (Get-TpmLedgerText $Extraction 80) }
    if ($TargetFolder) { Set-TpmLedgerField -Object $found.Unit -Name 'TargetFolder' -Value $TargetFolder }
    if ($Rollback) { Set-TpmLedgerField -Object $found.Unit -Name 'Rollback' -Value (Get-TpmLedgerText $Rollback 80) }
    if ($Publish) { [void](Publish-TpmRegistrationLedgerContext) }
    return $true
}

function New-TpmLedgerMapping {
    param([string]$Folder, [string]$Code, [string]$Match, [string]$IntendedPath, [string]$TemplatePath, [string]$State, [string]$Reason = '', $Operation = $null)
    $ctx = $script:TpmRegistrationLedger
    $found = Find-TpmLedgerUnit -Context $ctx -Folder $Folder -Operation $Operation
    $op = if ($found) { $found.Operation } elseif ($Operation) { $Operation } else { @($ctx.Document.Operations | Where-Object { $ctx.ActiveIds -contains [string]$_.OperationId })[0] }
    $rel = Get-TpmLedgerRelativePath -Path $IntendedPath -Root ([string]$op.InstallRoot)
    $mapping = [pscustomobject][ordered]@{
        MappingId = [guid]::NewGuid().ToString('N').Substring(0, 12)
        UnitId = $(if ($found) { [string]$found.Unit.UnitId } else { '' })
        Code = (Get-TpmLedgerText $Code 200)
        Template = $(if ($TemplatePath) { [System.IO.Path]::GetFileName($TemplatePath) } else { '' })
        Match = $Match; PathBase = $rel.Base; IntendedPath = $rel.Path
        State = $State; Reason = (Get-TpmLedgerText $Reason); Readback = $false; AttemptUtc = (Get-TpmLedgerTimestamp)
    }
    $op.Mappings = @($op.Mappings) + $mapping
    if ($found -and $State -eq 'WRITE_ATTEMPTED_UNVERIFIED') { $found.Unit.State = 'WRITE_ATTEMPTED_UNVERIFIED' }
    return [pscustomobject]@{ Operation = $op; Mapping = $mapping }
}

# Publishes the attempt BEFORE the profile write. Throws (write not attempted)
# when that evidence cannot be published; returns $null when no ledger is active.
function Start-TpmRegistrationMapping {
    param([string]$Folder, [string]$Code, [string]$Match, [string]$IntendedPath, [string]$TemplatePath, [bool]$DryRun = $false)
    $ctx = $script:TpmRegistrationLedger
    if (-not $DryRun -and $script:TpmRegistrationLedgerStopLatch) { throw 'Registration evidence could not be published earlier in this workflow, so this profile write was not attempted.' }
    if ($DryRun -or $null -eq $ctx -or $ctx.ActiveIds.Count -eq 0) { return $null }
    if ($ctx.Stopped) { throw 'Registration evidence could not be published earlier in this run, so this profile write was not attempted.' }
    $entry = New-TpmLedgerMapping -Folder $Folder -Code $Code -Match $Match -IntendedPath $IntendedPath -TemplatePath $TemplatePath -State 'WRITE_ATTEMPTED_UNVERIFIED' -Reason 'Published before the profile write; no saved-profile readback yet.'
    if (-not (Publish-TpmRegistrationLedgerContext)) {
        $entry.Mapping.State = 'FAILED_BEFORE_WRITE'
        $entry.Mapping.Reason = 'The pre-write evidence record could not be published; the profile write was not attempted.'
        throw 'Registration evidence could not be published before the profile write; the write was not attempted.'
    }
    return [string]$entry.Mapping.MappingId
}

# Never throws: a publication failure here must not turn a known product
# result into a failure. It marks evidence uncertain and stops later units.
function Complete-TpmRegistrationMapping {
    param([AllowNull()][AllowEmptyString()][string]$MappingId, [Parameter(Mandatory)][ValidateSet('VERIFIED', 'FAILED')][string]$Outcome, [bool]$WriteAttempted = $false, [string]$Reason = '')
    $ctx = $script:TpmRegistrationLedger
    if ($null -eq $ctx -or [string]::IsNullOrWhiteSpace($MappingId)) { return }
    foreach ($op in @($ctx.Document.Operations)) {
        $mapping = @($op.Mappings | Where-Object { [string]$_.MappingId -eq $MappingId })[0]
        if ($null -eq $mapping) { continue }
        if ($Outcome -eq 'FAILED' -and [string]$mapping.State -eq 'VERIFIED') { return }   # a proven read-back is never downgraded by a later error
        $mapping.State = if ($Outcome -eq 'VERIFIED') { 'VERIFIED' } elseif ($WriteAttempted) { 'WRITE_ATTEMPTED_UNVERIFIED' } else { 'FAILED_BEFORE_WRITE' }
        $mapping.Readback = ($Outcome -eq 'VERIFIED')
        $mapping.Reason = if ($Outcome -eq 'VERIFIED') { 'Saved profile GamePath and executable were read back and matched the intended mapping.' } else { Get-TpmLedgerText $Reason }
        $unit = @($op.Units | Where-Object { [string]$_.UnitId -eq [string]$mapping.UnitId })[0]
        if ($unit) { $unit.State = Get-TpmLedgerDerivedUnitState -Mappings @($op.Mappings | Where-Object { [string]$_.UnitId -eq [string]$unit.UnitId }) }
        break
    }
    [void](Publish-TpmRegistrationLedgerContext)
}

# Records a pre-write refusal (missing template/executable) for a unit.
function Add-TpmRegistrationMappingFailure {
    param([string]$Folder, [string]$Code, [string]$Match, [string]$Reason, [string]$TemplatePath = '', [bool]$DryRun = $false)
    $ctx = $script:TpmRegistrationLedger
    if ($DryRun -or $null -eq $ctx -or $ctx.ActiveIds.Count -eq 0) { return }
    $entry = New-TpmLedgerMapping -Folder $Folder -Code $Code -Match $Match -IntendedPath '' -TemplatePath $TemplatePath -State 'FAILED_BEFORE_WRITE' -Reason $Reason
    $unit = @($entry.Operation.Units | Where-Object { [string]$_.UnitId -eq [string]$entry.Mapping.UnitId })[0]
    if ($unit) { $unit.State = Get-TpmLedgerDerivedUnitState -Mappings @($entry.Operation.Mappings | Where-Object { [string]$_.UnitId -eq [string]$unit.UnitId }) }
    [void](Publish-TpmRegistrationLedgerContext)
}

# Final per-unit outcomes and transaction facts for every active operation.
# Units with no mapping stay explicit SKIPPED (existing-profile presence is not verification).
function Close-TpmRegistrationLedgerOperations {
    param([AllowNull()][object]$Legacy = $null, [AllowNull()][object]$Result = $null, [string]$Reason = 'REGISTRATION_NOT_ATTEMPTED', [string]$InstallBase = '')
    $ctx = $script:TpmRegistrationLedger
    $evidence = [pscustomobject]@{ Status = 'NOT_RECORDED'; Message = ''; OperationIds = @(); Stopped = $false }
    if ($null -eq $ctx -or $ctx.ActiveIds.Count -eq 0) { return $evidence }
    $now = Get-TpmLedgerTimestamp
    $activeOps = @($ctx.Document.Operations | Where-Object { $ctx.ActiveIds -contains [string]$_.OperationId })
    foreach ($op in $activeOps) {
        $base = if ($op.InstallRoot) { ([string]$op.InstallRoot).TrimEnd('\') } else { $InstallBase.TrimEnd('\') }
        if ($Legacy) {
            foreach ($amb in @($Legacy.Ambiguous)) {
                $exePath = [string]$amb.Exe
                $folder = if ($base -and $exePath.StartsWith($base + '\', [System.StringComparison]::OrdinalIgnoreCase)) { ($exePath.Substring($base.Length + 1) -split '\\')[0] } else { '' }
                $found = if ($folder) { Find-TpmLedgerUnit -Context $ctx -Folder $folder -Operation $op } else { $null }
                if ($null -eq $found) { continue }
                $kind = if ([string]$amb.Reason -eq 'duplicate') { 'DUPLICATE_PROFILE_CLAIM' } else { 'SHARED_EXECUTABLE_AMBIGUOUS' }
                [void](New-TpmLedgerMapping -Folder $folder -Code ([string]$amb.Codes) -Match 'ambiguous' -IntendedPath $exePath -TemplatePath '' -State 'SKIPPED' -Reason ('{0}; best guess {1}; score {2}' -f $kind, $amb.BestGuess, $amb.BestScore) -Operation $op)
            }
        }
        $unmatchedKeys = @(if ($Legacy) { $Legacy.Unmatched })
        foreach ($unit in @($op.Units)) {
            $unitMappings = @($op.Mappings | Where-Object { [string]$_.UnitId -eq [string]$unit.UnitId })
            if ($unitMappings.Count -gt 0) { $unit.State = Get-TpmLedgerDerivedUnitState -Mappings $unitMappings; continue }
            if ([string]$unit.State -ne 'PENDING') { continue }
            $unit.State = 'SKIPPED'
            $key = ([string]$unit.Folder) -replace '\.(teknoparrot|parrot|game)$', ''
            $unitReason = if ($ctx.Stopped) { 'STOPPED_AFTER_EVIDENCE_PUBLICATION_FAILURE' }
                elseif ($null -eq $Legacy) { $Reason }
                elseif ([string]$op.Mode -eq 'AutoSync' -and -not $unit.PSObject.Properties['TargetFolder']) { 'NO_VERIFIED_EXTRACTION_TARGET' }
                elseif ($unmatchedKeys -contains $key) { 'NO_PROFILE_MATCH' }
                else { 'NO_PROFILE_WRITE_EXISTING_PROFILE_OR_UNRESOLVED' }
            Set-TpmLedgerField -Object $unit -Name 'Reason' -Value $unitReason
        }
        if ($Result) {
            $backup = Get-TpmTransactionField -Object $Result -Name 'Backup'
            $rollback = Get-TpmTransactionField -Object $Result -Name 'Rollback'
            Set-TpmLedgerField -Object $op -Name 'Transaction' -Value ([pscustomobject][ordered]@{
                Outcome = [string](Get-TpmTransactionField -Object $Result -Name 'Outcome'); ProductState = [string](Get-TpmTransactionField -Object $Result -Name 'ProductState')
                ReasonCode = [string](Get-TpmTransactionField -Object $Result -Name 'ReasonCode')
                BackupVerified = [bool](Get-TpmTransactionField -Object $backup -Name 'Verified' -Default $false)
                RollbackAttempted = [bool](Get-TpmTransactionField -Object $rollback -Name 'Attempted' -Default $false)
            })
        }
        $op.State = 'COMPLETED'
        $op.CompletedUtc = $now
    }
    [void](Publish-TpmRegistrationLedgerContext)
    $evidence.Status = if ($ctx.Uncertain) { 'UNCERTAIN' } else { 'CURRENT' }
    $evidence.Message = [string]$ctx.Message
    $evidence.OperationIds = @($activeOps | ForEach-Object { [string]$_.OperationId })
    $evidence.Stopped = [bool]$ctx.Stopped
    $script:TpmRegistrationLedger = $null
    return $evidence
}

# Fatal evidence is separate from per-game outcomes. It appends a bounded,
# redacted record to a readable ledger and never overwrites an unusable one;
# an abrupt exit without this write leaves the prior PENDING records intact.
function Add-TpmRegistrationLedgerFatal {
    param([string]$Message, [string]$ExceptionType = '', [string]$Path = '', [int]$MaximumBytes = 1048576)
    try {
        if ([string]::IsNullOrWhiteSpace($Path)) { $Path = Get-TpmRegistrationLedgerPath }
        if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
        $read = Read-TpmRegistrationLedger -Path $Path -MaximumBytes $MaximumBytes
        if ($read.Status -notin @('Ok', 'Missing')) { return $false }
        $document = if ($read.Status -eq 'Ok') { $read.Document } else { New-TpmRegistrationLedgerDocument }
        $runId = Get-TpmSessionRunId
        $safe = (Redact-TpmSupportText -Text $Message).Text
        $truncated = ($safe.Length -gt 500)
        if ($truncated) { $safe = $safe.Substring(0, 500) }
        $record = [pscustomobject][ordered]@{
            FatalId = [guid]::NewGuid().ToString('N'); RunId = $runId; TimeUtc = (Get-TpmLedgerTimestamp)
            ExceptionType = (Get-TpmLedgerText $ExceptionType 120); Message = $safe; MessageTruncated = $truncated
            OpenOperationIds = @($document.Operations | Where-Object { [string]$_.State -eq 'PENDING' -and [string]$_.RunId -eq $runId } | ForEach-Object { [string]$_.OperationId })
        }
        $document.Fatals = @($document.Fatals) + $record
        return [bool](Publish-TpmRegistrationLedgerDocument -Path $Path -Document $document -MaximumBytes $MaximumBytes).Published
    } catch { return $false }
}

# Exact runtime artifact identity from the script path captured at startup.
# Package/commit fields come only from TPM-PackageIdentity.json beside the
# script; otherwise they stay 'unavailable' (a version label is not identity).
function Get-TpmRuntimeArtifactIdentity {
    param([AllowEmptyString()][string]$ScriptPath = '')
    $identity = [pscustomobject][ordered]@{
        CapturedUtc = (Get-TpmLedgerTimestamp); ScriptPath = ''; ScriptStatus = 'unavailable'; ScriptLength = $null; ScriptSha256 = 'unavailable'
        ManagerVersionLabel = [string](Get-ManagerDisplayVersion)
        PowerShellVersion = $PSVersionTable.PSVersion.ToString(); PowerShellEdition = [string]$PSVersionTable.PSEdition
        OperatingSystem = [string][Environment]::OSVersion.VersionString; ProcessArchitecture = [string]$env:PROCESSOR_ARCHITECTURE
        Is64BitOperatingSystem = [Environment]::Is64BitOperatingSystem; Is64BitProcess = [Environment]::Is64BitProcess
        PackageManifestStatus = 'unavailable'; PackageManifestSha256 = 'unavailable'; PackageId = 'unavailable'; SourceCommit = 'unavailable'
        PackageNote = 'No package identity manifest was found beside the running script; the version label is not a package hash or source commit.'
    }
    if ([string]::IsNullOrWhiteSpace($ScriptPath)) { $identity.ScriptStatus = 'unavailable: no startup script path'; return $identity }
    try {
        $full = [System.IO.Path]::GetFullPath($ScriptPath)
        $identity.ScriptPath = $full
        $stream = New-Object System.IO.FileStream($full, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        try {
            $identity.ScriptLength = [int64]$stream.Length
            $sha = [System.Security.Cryptography.SHA256]::Create()
            try { $identity.ScriptSha256 = [BitConverter]::ToString($sha.ComputeHash($stream)).Replace('-', '') } finally { $sha.Dispose() }
        } finally { $stream.Dispose() }
        $identity.ScriptStatus = 'captured'
    } catch {
        $identity.ScriptStatus = 'unavailable: ' + (Get-TpmLedgerText $_.Exception.Message 160)
        return $identity
    }
    try {
        $manifestPath = Join-Path ([System.IO.Path]::GetDirectoryName($identity.ScriptPath)) 'TPM-PackageIdentity.json'
        if (Test-Path -LiteralPath $manifestPath -PathType Leaf) {
            $manifestItem = Get-Item -LiteralPath $manifestPath -Force -ErrorAction Stop
            if ($manifestItem.Length -gt 65536) { $identity.PackageManifestStatus = 'unavailable: identity manifest exceeds 64 KiB' }
            elseif (-not (Test-TpmNoReparsePath -Path $manifestPath)) { $identity.PackageManifestStatus = 'unavailable: identity manifest path is reparse-backed' }
            else {
                $manifestBytes = [System.IO.File]::ReadAllBytes($manifestPath)
                $sha = [System.Security.Cryptography.SHA256]::Create()
                try { $manifestHash = [BitConverter]::ToString($sha.ComputeHash($manifestBytes)).Replace('-', '') } finally { $sha.Dispose() }
                $manifest = (New-Object System.Text.UTF8Encoding($false, $true)).GetString($manifestBytes).TrimStart([char]0xFEFF) | ConvertFrom-Json -ErrorAction Stop
                $packageId = [string]$manifest.PackageId
                $commit = [string]$manifest.SourceCommit
                if ($packageId -match '^[A-Za-z0-9._-]{1,128}$') {
                    $identity.PackageId = $packageId; $identity.PackageManifestSha256 = $manifestHash; $identity.PackageManifestStatus = 'present'
                    $identity.PackageNote = 'PackageId and SourceCommit are declared by TPM-PackageIdentity.json; PackageManifestSha256 is computed from that file''s bytes.'
                } else { $identity.PackageManifestStatus = 'unavailable: PackageId is missing or invalid' }
                if ($identity.PackageManifestStatus -eq 'present' -and $commit -match '^[0-9a-fA-F]{40}$') { $identity.SourceCommit = $commit.ToLowerInvariant() }
            }
        }
    } catch { $identity.PackageManifestStatus = 'unavailable: ' + (Get-TpmLedgerText $_.Exception.Message 160) }
    return $identity
}

function Get-TpmSupportIdentityProjection {
    param([Parameter(Mandatory)]$Identity)
    $path = [string]$Identity.ScriptPath
    return [ordered]@{
        SchemaVersion = 1
        ScriptStartupPath = $(if ($path) { [System.IO.Path]::GetFileName($path) } else { 'unavailable' })
        ScriptStatus = [string]$Identity.ScriptStatus; ScriptLength = $Identity.ScriptLength; ScriptSha256 = [string]$Identity.ScriptSha256
        ManagerVersionLabel = [string]$Identity.ManagerVersionLabel; VersionLabelNote = 'A version label is not a source commit or package hash.'
        PowerShellVersion = [string]$Identity.PowerShellVersion; PowerShellEdition = [string]$Identity.PowerShellEdition
        OperatingSystem = [string]$Identity.OperatingSystem; ProcessArchitecture = [string]$Identity.ProcessArchitecture
        Is64BitOperatingSystem = $Identity.Is64BitOperatingSystem; Is64BitProcess = $Identity.Is64BitProcess
        PackageManifestStatus = [string]$Identity.PackageManifestStatus; PackageManifestSha256 = [string]$Identity.PackageManifestSha256
        PackageId = [string]$Identity.PackageId; SourceCommit = [string]$Identity.SourceCommit; PackageNote = [string]$Identity.PackageNote
    }
}

# One terminating pass; enumeration failures are returned, never swallowed.
function Get-TpmSupportProfileFiles {
    param([Parameter(Mandatory)][string]$Directory)
    $files = New-Object System.Collections.Generic.List[System.IO.FileInfo]
    $failure = ''
    try {
        $info = New-Object System.IO.DirectoryInfo $Directory
        foreach ($file in $info.EnumerateFiles('*.xml', [System.IO.SearchOption]::TopDirectoryOnly)) {
            if ($file.Extension -ieq '.xml') { [void]$files.Add($file) }
        }
    } catch { $failure = (Redact-TpmSupportText -Text $_.Exception.Message).Text }
    return [pscustomobject]@{ Files = $files.ToArray(); EnumerationFailure = $failure }
}

function Get-TpmSupportSavedMappingCheck {
    param([string]$UserProfilesDir, [string]$Code, [string]$ExpectedPath)
    if ([string]::IsNullOrWhiteSpace($UserProfilesDir) -or $Code -notmatch '^[\w-]+$' -or [string]::IsNullOrWhiteSpace($ExpectedPath)) { return 'NOT_CHECKED' }
    try {
        $profilePath = Join-Path $UserProfilesDir ($Code + '.xml')
        if (-not (Test-Path -LiteralPath $profilePath -PathType Leaf)) { return 'PROFILE_MISSING' }
        $opened = Open-TpmSupportSafeFileStream -SourcePath $profilePath -AllowedRoot $UserProfilesDir -MaximumBytes 16777216
        try {
            $doc = New-Object System.Xml.XmlDocument
            $doc.XmlResolver = $null
            $doc.Load($opened.Stream)
        } finally { $opened.Stream.Dispose() }
        $node = $doc.SelectSingleNode('/GameProfile/GamePath')
        if ($null -eq $node -or [string]::IsNullOrWhiteSpace($node.InnerText)) { return 'GAMEPATH_MISSING' }
        if ([System.IO.Path]::GetFullPath($node.InnerText.Trim()) -ieq [System.IO.Path]::GetFullPath($ExpectedPath)) { return 'MATCHES_INTENT' }
        return 'DIFFERS_FROM_INTENT'
    } catch { return 'UNREADABLE' }
}

# Allowlisted, redacted projection of the durable ledger for support export.
# Open work from an earlier run is shown as INTERRUPTED_UNKNOWN (derived), never as success.
function Get-TpmSupportLedgerProjection {
    param([Parameter(Mandatory)]$Read, [string]$RunId = '', [string]$UserProfilesDir = '')
    $affected = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $codeStates = [System.Collections.Generic.Dictionary[string, string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $operations = New-Object System.Collections.Generic.List[object]
    $transactions = New-Object System.Collections.Generic.List[object]
    $fatals = New-Object System.Collections.Generic.List[object]
    $lines = New-Object System.Collections.Generic.List[string]
    $sequence = $null
    if ([string]$Read.Status -eq 'Ok') {
        $sequence = $Read.Document.Sequence
        foreach ($op in @($Read.Document.Operations)) {
            $stored = [string]$op.State
            $older = ($stored -eq 'PENDING' -and [string]$op.RunId -ne $RunId)
            $state = if ($older) { 'INTERRUPTED_UNKNOWN (derived: an earlier run never closed this operation)' } elseif ($stored -eq 'PENDING') { 'INCOMPLETE (not closed)' } else { $stored }
            $unitRows = New-Object System.Collections.Generic.List[object]
            foreach ($unit in @($op.Units)) {
                $unitState = [string]$unit.State
                if ($older -and $unitState -in @('PENDING', 'WRITE_ATTEMPTED_UNVERIFIED')) { $unitState = 'INTERRUPTED_UNKNOWN (derived)' }
                [void]$unitRows.Add([ordered]@{
                    UnitId = [string]$unit.UnitId; Folder = (Redact-TpmSupportText -Text ([string]$unit.Folder)).Text; State = $unitState
                    TargetFolder = (Redact-TpmSupportText -Text ([string]$unit.TargetFolder)).Text; Reason = (Redact-TpmSupportText -Text ([string]$unit.Reason)).Text
                    Extraction = [string]$unit.Extraction; Rollback = [string]$unit.Rollback
                })
            }
            $mappingRows = New-Object System.Collections.Generic.List[object]
            foreach ($mapping in @($op.Mappings)) {
                $code = [string]$mapping.Code
                $expected = if ([string]$mapping.PathBase -eq 'InstallRoot' -and $op.InstallRoot) { Join-Path ([string]$op.InstallRoot) ([string]$mapping.IntendedPath) } elseif ([string]$mapping.PathBase -eq 'Absolute') { [string]$mapping.IntendedPath } else { '' }
                $check = if ([string]$mapping.State -in @('VERIFIED', 'WRITE_ATTEMPTED_UNVERIFIED')) { Get-TpmSupportSavedMappingCheck -UserProfilesDir $UserProfilesDir -Code $code -ExpectedPath $expected } else { 'NOT_CHECKED' }
                $shownPath = if ([string]$mapping.PathBase -eq 'Absolute') { '<absolute>\' + [System.IO.Path]::GetFileName([string]$mapping.IntendedPath) } else { [string]$mapping.IntendedPath }
                [void]$mappingRows.Add([ordered]@{
                    MappingId = [string]$mapping.MappingId; UnitId = [string]$mapping.UnitId; Code = (Redact-TpmSupportText -Text $code).Text
                    Template = [string]$mapping.Template; Match = [string]$mapping.Match; PathBase = [string]$mapping.PathBase; IntendedPath = (Redact-TpmSupportText -Text $shownPath).Text
                    State = [string]$mapping.State; Reason = (Redact-TpmSupportText -Text ([string]$mapping.Reason)).Text; Readback = [bool]$mapping.Readback
                    AttemptUtc = [string]$mapping.AttemptUtc; SavedProfileCheck = $check
                })
                if ($code -match '^[\w-]+$') {
                    [void]$affected.Add($code)
                    $entry = ('{0}/{1}' -f $mapping.State, $check)
                    $codeStates[$code] = $(if ($codeStates.ContainsKey($code)) { $codeStates[$code] + '; ' + $entry } else { $entry })
                }
            }
            [void]$operations.Add([ordered]@{
                OperationId = [string]$op.OperationId; RunId = [string]$op.RunId; Mode = [string]$op.Mode; State = $state; StoredState = $stored
                EvidenceStatus = [string]$op.EvidenceStatus; StartedUtc = [string]$op.StartedUtc; CompletedUtc = [string]$op.CompletedUtc
                ManagerVersion = [string]$op.Source.ManagerVersion; ScriptSha256 = [string]$op.Source.ScriptSha256
                InstallRoot = '<install-root>'; Units = $unitRows.ToArray(); Mappings = $mappingRows.ToArray()
            })
            [void]$transactions.Add([ordered]@{
                OperationId = [string]$op.OperationId; RunId = [string]$op.RunId; Mode = [string]$op.Mode; State = $state
                Transaction = $op.Transaction
                ExtractionFacts = @($op.Units | Where-Object { $_.PSObject.Properties['Extraction'] -or $_.PSObject.Properties['Rollback'] } | ForEach-Object { [ordered]@{ UnitId = [string]$_.UnitId; Extraction = [string]$_.Extraction; Rollback = [string]$_.Rollback } })
            })
            $stateCounts = (@($unitRows | ForEach-Object { $_.State } | Group-Object | Sort-Object Name | ForEach-Object { '{0}={1}' -f $_.Name, $_.Count }) -join ', ')
            [void]$lines.Add(('Ledger operation {0}: mode={1}; state={2}; evidence={3}; units={4} ({5})' -f ([string]$op.OperationId).Substring(0, [Math]::Min(8, ([string]$op.OperationId).Length)), $op.Mode, $state, $op.EvidenceStatus, $unitRows.Count, $stateCounts))
        }
        foreach ($fatal in @($Read.Document.Fatals)) {
            [void]$fatals.Add([ordered]@{
                FatalId = [string]$fatal.FatalId; RunId = [string]$fatal.RunId; CurrentRun = ([string]$fatal.RunId -eq $RunId); TimeUtc = [string]$fatal.TimeUtc
                ExceptionType = [string]$fatal.ExceptionType; Message = (Redact-TpmSupportText -Text ([string]$fatal.Message)).Text; MessageTruncated = [bool]$fatal.MessageTruncated
                OpenOperationIds = @($fatal.OpenOperationIds)
            })
        }
    }
    [void]$lines.Insert(0, ('Registration ledger: status={0}; sequence={1}; bytes={2}; operations={3}; fatal records={4}' -f $Read.Status, $(if ($null -ne $sequence) { $sequence } else { 'n/a' }), $Read.Bytes, $operations.Count, $fatals.Count))
    return [pscustomobject]@{
        AffectedCodes = $affected; CodeStates = $codeStates; Lines = $lines.ToArray()
        Ledger = [ordered]@{ SchemaVersion = 1; Status = [string]$Read.Status; Message = (Redact-TpmSupportText -Text ([string]$Read.Message)).Text; Bytes = $Read.Bytes; Sha256 = [string]$Read.Sha256; Sequence = $sequence; Operations = $operations.ToArray() }
        Fatal = [ordered]@{ SchemaVersion = 1; Status = [string]$Read.Status; Fatals = $fatals.ToArray() }
        Transactions = [ordered]@{ SchemaVersion = 1; Status = [string]$Read.Status; Operations = $transactions.ToArray() }
    }
}

function Write-TpmSupportMetadataJson {
    param([Parameter(Mandatory)][string]$StageDirectory, [Parameter(Mandatory)][string]$Name, [Parameter(Mandatory)]$Object, [int]$MaximumBytes = 4194304)
    $text = ($Object | ConvertTo-Json -Depth 10) + "`r`n"
    if ($text.Length -gt $MaximumBytes) { throw ('{0} exceeded the {1}-byte support metadata limit and was not written.' -f $Name, $MaximumBytes) }
    [System.IO.File]::WriteAllText((Join-Path (Join-Path $StageDirectory 'metadata') $Name), $text, (New-Object System.Text.UTF8Encoding($false)))
}

function Assert-TpmRegisteredGamePath {
    param([string]$ProfilePath, [string]$ExpectedGamePath, [string]$ExpectedSecondaryPath = '', [object]$RegistrationState = $null)
    $saved = Read-Xml $ProfilePath
    $paths = @($saved.SelectNodes('/GameProfile/GamePath'))
    if ($paths.Count -ne 1 -or [string]::IsNullOrWhiteSpace($paths[0].InnerText) -or
        [System.IO.Path]::GetFullPath($paths[0].InnerText) -ine [System.IO.Path]::GetFullPath($ExpectedGamePath) -or
        -not (Test-Path -LiteralPath $ExpectedGamePath -PathType Leaf -ErrorAction Stop)) {
        throw 'The saved registration did not verify the intended executable mapping.'
    }
    if ($ExpectedSecondaryPath) {
        $secondary = @($saved.SelectNodes('/GameProfile/GamePath2'))
        if ($secondary.Count -ne 1 -or [string]$secondary[0].InnerText -ine $ExpectedSecondaryPath) {
            throw 'The saved secondary executable mapping could not be verified.'
        }
    }
    if ($RegistrationState) {
        $code = [System.IO.Path]::GetFileNameWithoutExtension($ProfilePath)
        foreach ($failure in @($RegistrationState.Failures | Where-Object { $_.Code -ieq $code })) {
            $failure | Add-Member -NotePropertyName ResolvedByVerifiedMapping -NotePropertyValue $true -Force
        }
    }
}

function ConvertTo-TpmRegistrationResult {
    param([Parameter(Mandatory)]$Legacy, [object]$Backup, [bool]$DryRun)
    $registered = @($Legacy.Registered | ForEach-Object Code | Select-Object -Unique)
    $changed = @()
    if (-not $DryRun) { $changed = @($registered + @($Legacy.MutationRecords.Changed) | Select-Object -Unique) }
    $unknown = @($Legacy.MutationRecords.Failures | Where-Object { $_.WriteAttempted -and -not (Get-TpmTransactionField -Object $_ -Name 'ResolvedByVerifiedMapping' -Default $false) } | ForEach-Object Code | Select-Object -Unique)
    $failed = @($Legacy.MutationRecords.Failures | Where-Object { -not $_.WriteAttempted -and $_.Code -notin $unknown -and -not (Get-TpmTransactionField -Object $_ -Name 'ResolvedByVerifiedMapping' -Default $false) } | ForEach-Object Code | Select-Object -Unique)
    $unresolved = @($Legacy.Ambiguous | ForEach-Object { 'review:' + [string]$_.Codes })
    $decisions = @($Legacy.Decisions | Where-Object { $_.Outcome -notin @('REGISTERED','PREVIEW') -and -not (Get-TpmTransactionField -Object $_ -Name 'ResolvedByVerifiedMapping' -Default $false) } | ForEach-Object { 'manual:' + [string]$_.Game })
    $evidenceStopped = (-not $DryRun -and ([bool](Get-TpmTransactionField -Object $Legacy -Name 'EvidenceStopped' -Default $false) -or (Test-TpmRegistrationLedgerStopped)))
    $unattempted = @(Get-TpmTransactionField -Object $Legacy -Name 'UnattemptedFolders' -Default @())
    $unattemptedKeys = @($unattempted | ForEach-Object { ([string]$_) -replace '\.(teknoparrot|parrot|game)$', '' })
    $skipped = @($unresolved + @($Legacy.Unmatched) + $decisions | Where-Object { $_ -notin $changed -and $_ -notin $failed -and $_ -notin $unknown -and $_ -notin $unattemptedKeys } | Select-Object -Unique)
    $items = @($registered + $changed + @($Legacy.Already) + $unknown + $failed + $skipped + $unattempted | Select-Object -Unique)
    $backupTouched = [bool](Get-TpmTransactionField -Object $Backup -Name 'Attempted' -Default $false) -or [bool](Get-TpmTransactionField -Object $Backup -Name 'Created' -Default $false)
    $outcome = if ($DryRun) { 'NO_OP' } elseif ($unknown.Count -gt 0) { 'ACTION_REQUIRED' } elseif ($evidenceStopped) { if ($changed.Count -gt 0) { 'PARTIAL_APPLIED' } else { 'ACTION_REQUIRED' } } elseif ($changed.Count -gt 0 -and ($failed.Count -gt 0 -or $skipped.Count -gt 0)) { 'PARTIAL_APPLIED' } elseif ($changed.Count -gt 0) { 'SUCCEEDED' } elseif ($failed.Count -gt 0) { 'FAILED_BEFORE_MUTATION' } elseif ($skipped.Count -gt 0 -or $backupTouched) { 'ACTION_REQUIRED' } else { 'NO_OP' }
    $state = if ($unknown.Count -gt 0) { 'UNKNOWN' } elseif ($outcome -eq 'SUCCEEDED') { 'INTENDED' } elseif ($outcome -eq 'PARTIAL_APPLIED') { 'PARTIAL_KNOWN' } else { 'UNCHANGED' }
    $summary = if ($DryRun) { 'Registration preview made no profile changes.' } elseif ($evidenceStopped) { 'Registration stopped because its evidence could not be published. Known verified mappings are retained; review the unattempted folders and create a support package before running again.' } elseif ($unknown.Count -gt 0) { 'Registration needs attention because a saved profile could not be verified.' } elseif ($outcome -eq 'SUCCEEDED') { 'New or changed registration mappings were saved and read back; launch and controls were not verified.' } elseif ($outcome -eq 'PARTIAL_APPLIED') { 'Some registration mappings were verified; other games remain unresolved.' } elseif ($failed.Count -gt 0) { 'Registration failed before a profile write; review the retained failure reasons.' } elseif ($skipped.Count -gt 0) { 'Registration choices or prerequisites remain unresolved; no registration success was claimed.' } elseif ($outcome -eq 'NO_OP' -and @($Legacy.Already).Count -gt 0) { 'All selected games were already registered. No profile change was needed.' } elseif ($outcome -eq 'NO_OP') { 'No registration profile change was needed.' } else { 'No registration profile change was recorded; any created safety backup was retained. Existing mappings were not reverified.' }
    $reason = if ($DryRun) { 'DRY_RUN' } elseif ($evidenceStopped) { 'REGISTRATION_EVIDENCE_PUBLICATION_FAILED' } elseif ($unknown.Count -gt 0) { 'PROFILE_STATE_UNVERIFIED' } elseif ($failed.Count -gt 0 -or $skipped.Count -gt 0) { 'REGISTRATION_INCOMPLETE' } elseif ($changed.Count -gt 0) { 'REGISTRATION_MAPPING_VERIFIED' } elseif ($backupTouched) { 'BACKUP_RETAINED_NO_PROFILE_CHANGE' } else { 'NO_PROFILE_CHANGE' }
    $completed = @($changed | Where-Object { $_ -notin $unknown -and $_ -notin $failed })
    $tx = New-TpmProfileTransactionResult -WorkflowKey 'GameRegistration' -OperationKey 'RegisterProfiles' -Outcome $outcome -ProductState $state -Summary $summary -Items $items -ChangedItems $changed -CompletedItems $completed -FailedItems $failed -UnattemptedItems $unattempted -SkippedItems $skipped -UnknownItems $unknown -MutationStarted ($changed.Count -gt 0 -or $unknown.Count -gt 0) -MutationCompleted:($outcome -eq 'SUCCEEDED') -Backup $Backup -FinalPassed ($unknown.Count -eq 0) -ReasonCode $reason -FinalChecks @('Only saved mappings read back against the intended executable are counted as changed registration results; existing profile presence is not exact selected-game verification.') -TechnicalDetails $Legacy
    foreach ($name in @('Registered','Already','Ambiguous','Unmatched')) {
        $tx | Add-Member -NotePropertyName $name -NotePropertyValue $Legacy.$name -Force
    }
    $currentRegistered = New-Object System.Collections.ArrayList
    foreach ($entry in @($Legacy.Registered | Where-Object { $_.Code -notin $unknown -and $_.Code -notin $failed })) { [void]$currentRegistered.Add($entry) }
    $tx.Registered = $currentRegistered
    return $tx
}

# Registration creates its UserProfiles safety backup lazily, immediately
# before the first real profile write (same pattern as control propagation),
# so a run that changes nothing -- every candidate already registered --
# never creates or reports a backup and is an honest NO_OP. The state
# hashtable (Backup / Done / Error) travels with the legacy result as
# SafetyBackupState so later duplicate-switch and manual-registration writes
# in the same run reuse the same backup. A failed backup is sticky: every
# later write is refused, so nothing is written without a verified backup.
# Every non-preview profile write calls this; a missing state is a hard
# failure, never a write without a backup.
function Confirm-TpmRegistrationSafetyBackup {
    param([Parameter(Mandatory)][AllowNull()][hashtable]$State, [Parameter(Mandatory)][string]$UserProfilesDir)
    if ($null -eq $State) { throw 'A verified profile backup is required before registration writes a profile, but no backup state was provided.' }
    if ($null -ne $State['Error']) { throw $State['Error'] }
    if (-not [bool]$State['Done']) {
        try {
            $State['Backup'] = New-TpmVerifiedUserProfilesBackup -UserProfilesDir $UserProfilesDir -Label 'RegisterGames'
            if (-not [bool](Get-TpmTransactionField -Object $State['Backup'] -Name 'Verified' -Default $false)) {
                throw 'Game registration stopped before changing profiles because its safety backup could not be verified.'
            }
        } catch {
            $State['Error'] = [string]$_.Exception.Message
            throw
        }
        $State['Done'] = $true
    }
    return $State['Backup']
}

# Backup evidence to report for a registration result: the lazily created
# backup when this run tracked one (or $null when no write needed it),
# otherwise whatever the result already carried.
function Get-TpmRegistrationBackupEvidence {
    param([Parameter(Mandatory)]$Result)
    $state = Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'TechnicalDetails') -Name 'SafetyBackupState'
    if ($state -is [hashtable]) { return $state['Backup'] }
    return (Get-TpmTransactionField -Object $Result -Name 'Backup')
}

# Region choice. Each profile lists the regions it allows in its own dropdown(s), so no region list is kept here.
# Handled: a Dropdown named Region; or, when there is none, the Dropdowns PcbRegion and DongleRegion, which are one choice
# and are always written together. Not handled: ExportRegion (a true/false field) and a Region that is free text.
# The "automatic" choice is the profile's own Auto or Default option; a list with neither has no automatic choice.
# The helpers below serve both the question after registration (Invoke-TpmRegionChoice) and the Region setup menu item
# (Invoke-TpmRegionSetup).
function Get-TpmProfileRegionFields {
    param([Parameter(Mandatory)]$Doc)
    $found = @{}
    foreach ($name in @('Region', 'PcbRegion', 'DongleRegion')) {
        $fi = $Doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName='$name' and FieldType='Dropdown']")
        if ($null -eq $fi) { continue }
        $fv = $fi.SelectSingleNode('FieldValue')
        if ($null -eq $fv) { continue }
        $options = @($fi.SelectNodes('FieldOptions/string') | ForEach-Object { [string]$_.InnerText } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
        $found[$name] = [pscustomobject]@{ Name = $name; Value = ([string]$fv.InnerText).Trim(); Options = $options }
    }
    if ($found.ContainsKey('Region')) { return @($found['Region']) }
    return @(@('PcbRegion', 'DongleRegion') | Where-Object { $found.ContainsKey($_) } | ForEach-Object { $found[$_] })
}

# The first Auto or Default option of a list (letter case ignored), or $null when the list has neither.
function Get-TpmRegionNeutralText {
    param([AllowEmptyCollection()][string[]]$Options)
    $hit = @($Options | Where-Object { $_ -ieq 'Auto' -or $_ -ieq 'Default' } | Select-Object -First 1)
    if ($hit.Count -eq 0) { return $null }
    return [string]$hit[0]
}

# True when every field of the game already holds the value in $Match (see Get-TpmRegionOptionText).
function Test-TpmRegionHeld {
    param([Parameter(Mandatory)]$Game, [Parameter(Mandatory)]$Match)
    for ($i = 0; $i -lt $Game.Fields.Count; $i++) {
        if ($Game.Fields[$i].Value -ine $Match.Writes[$i].Text) { return $false }
    }
    return $true
}

# One object per profile file that has a region choice: Code, Path, Label (the game name), Fields, current Value (first field),
# Options (only what EVERY field offers), Neutral (the automatic choice, or $null) and IsNeutral.
function Get-TpmRegionGames {
    param([Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Paths)
    $games = New-Object System.Collections.Generic.List[object]
    foreach ($path in $Paths) {
        $code = [System.IO.Path]::GetFileNameWithoutExtension($path)
        try { $doc = Read-Xml $path } catch { Write-Log ('Region: could not read {0}: {1}' -f $code, $_.Exception.Message); continue }
        $fields = @(Get-TpmProfileRegionFields -Doc $doc)
        if ($fields.Count -eq 0) { continue }
        $options = @($fields[0].Options | Where-Object { $o = $_; @($fields | Where-Object { @($_.Options | Where-Object { $_ -ieq $o }).Count -gt 0 }).Count -eq $fields.Count })
        $neutralWrites = New-Object System.Collections.Generic.List[object]
        foreach ($f in $fields) {
            $text = Get-TpmRegionNeutralText -Options $f.Options
            if ($null -eq $text) { break }
            [void]$neutralWrites.Add([pscustomobject]@{ Name = $f.Name; Text = $text })
        }
        $neutral = if ($neutralWrites.Count -eq $fields.Count) { [pscustomobject]@{ Text = $neutralWrites[0].Text; Writes = $neutralWrites.ToArray() } } else { $null }
        $game = [pscustomobject]@{ Code = $code; Path = $path; Label = (Get-TpmGameDisplayLabel -ProfilePath $path -Fallback $code); Fields = $fields; Value = $fields[0].Value; Options = $options; Neutral = $neutral; IsNeutral = $false }
        $game.IsNeutral = ($null -ne $neutral -and (Test-TpmRegionHeld -Game $game -Match $neutral))
        [void]$games.Add($game)
    }
    return $games.ToArray()
}

# What to write to make a game hold a region (letter case ignored, the profile's own spelling kept): Text (first field) and
# Writes (Name and Text for every field). $null when any of the game's fields does not offer it. -Neutral asks for the automatic choice.
function Get-TpmRegionOptionText {
    param([Parameter(Mandatory)]$Game, [string]$Region = '', [switch]$Neutral)
    if ($Neutral) { return $Game.Neutral }
    $writes = New-Object System.Collections.Generic.List[object]
    foreach ($f in $Game.Fields) {
        $hit = @($f.Options | Where-Object { $_ -ieq $Region } | Select-Object -First 1)
        if ($hit.Count -eq 0) { return $null }
        [void]$writes.Add([pscustomobject]@{ Name = $f.Name; Text = [string]$hit[0] })
    }
    return [pscustomobject]@{ Text = $writes[0].Text; Writes = $writes.ToArray() }
}

# The regions other than Auto and Default that these games offer, with how many games offer each; most offered first.
function Get-TpmRegionOffers {
    param([Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Games)
    $count = @{}
    $names = New-Object System.Collections.Generic.List[string]
    foreach ($g in $Games) {
        foreach ($o in $g.Options) {
            if ($o -ieq 'Auto' -or $o -ieq 'Default') { continue }
            if (-not $count.ContainsKey($o)) { $count[$o] = 0; [void]$names.Add($o) }
            $count[$o] = [int]$count[$o] + 1
        }
    }
    return @($names | Sort-Object @{ Expression = { $count[$_] }; Descending = $true }, @{ Expression = { $_ } } | ForEach-Object { [pscustomobject]@{ Name = $_; Count = [int]$count[$_] } })
}

# Shows the regions as a numbered list. Returns Back (0 was chosen), Neutral (A was chosen, only with -OfferNeutral) and Region.
function Read-TpmRegionChoice {
    param([Parameter(Mandatory)][object[]]$Offers, [Parameter(Mandatory)][string]$ZeroText, [switch]$OfferNeutral)
    Write-Host ''
    Write-TpmText -Text 'Which country do you want your games to start in?' -Color Cyan -Indent 2
    Write-TpmText -Text 'Some games can start in a country you pick. It changes things like the language. Games left on Auto or Default usually start as Japan.' -Color DarkCyan -Indent 2
    Write-Host ''
    Write-Host ('    0) ' + $ZeroText) -ForegroundColor DarkCyan
    for ($i = 0; $i -lt $Offers.Count; $i++) { Write-Host ('    {0}) {1} ({2})' -f ($i + 1), $Offers[$i].Name, (Format-TpmGameCount -Count ([int]$Offers[$i].Count))) -ForegroundColor DarkCyan }
    $choices = @(0..$Offers.Count | ForEach-Object { [string]$_ })
    if ($OfferNeutral) { Write-Host '    A) Back to automatic (Auto or Default: the games go back to their normal setting)' -ForegroundColor DarkCyan; $choices += 'A' }
    $answer = Read-TpmChoice -Prompt ('  Choice (0 = {0})' -f $ZeroText.ToLowerInvariant()) -Choices $choices -Default '0'
    if ($answer -eq '0') { return [pscustomobject]@{ Back = $true; Neutral = $false; Region = '' } }
    if ($answer -eq 'A') { return [pscustomobject]@{ Back = $false; Neutral = $true; Region = '' } }
    return [pscustomobject]@{ Back = $false; Neutral = $false; Region = [string]$Offers[[int]$answer - 1].Name }
}

# Sets the region on each item (Path, Label, Was, Writes). Each profile is read again right before its write, every field must
# still offer its value, all fields are changed in ONE atomic save and every field is read back. With -BackupError nothing is
# written and every game is reported as failed.
function Set-TpmProfileRegions {
    param([Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Items, [string]$BackupError = '')
    $changed = New-Object System.Collections.Generic.List[string]
    $failed = New-Object System.Collections.Generic.List[string]
    foreach ($item in $Items) {
        if ($BackupError) { [void]$failed.Add(('{0}: {1}' -f $item.Label, $BackupError)); continue }
        $pre = Get-TpmProfileWriteFingerprint -Path $item.Path
        $attempted = $false
        try {
            $doc = Read-Xml $item.Path
            $fields = @(Get-TpmProfileRegionFields -Doc $doc)
            foreach ($w in $item.Writes) {
                $field = @($fields | Where-Object { $_.Name -ceq $w.Name })
                if ($field.Count -eq 0 -or @($field[0].Options | Where-Object { $_ -ceq $w.Text }).Count -eq 0) { throw 'The game no longer offers this region.' }
            }
            foreach ($w in $item.Writes) {
                if (-not (Set-ConfigField $doc $w.Name $w.Text)) { throw ('The {0} setting could not be changed.' -f $w.Name) }
            }
            $attempted = $true
            Save-Xml $doc $item.Path
            $saved = @(Get-TpmProfileRegionFields -Doc (Read-Xml $item.Path))
            foreach ($w in $item.Writes) {
                $field = @($saved | Where-Object { $_.Name -ceq $w.Name })
                if ($field.Count -eq 0 -or $field[0].Value -cne $w.Text.Trim()) { throw ('The saved {0} value did not read back.' -f $w.Name) }
            }
            [void]$changed.Add(('{0} ({1} -> {2})' -f $item.Label, $item.Was, $item.Writes[0].Text))
        } catch {
            $failure = Resolve-TpmRegistrationSaveFailure -WriteAttempted $attempted -PreState $pre -Message $_.Exception.Message
            [void]$failed.Add(('{0}: {1}' -f $item.Label, $failure.Reason))
        }
    }
    return [pscustomobject]@{ Changed = $changed.ToArray(); Failed = $failed.ToArray() }
}

# One plain result line plus game-by-game Details (also logged). -Neutral words it for "back to the automatic choice".
function Write-TpmRegionResult {
    param(
        [string]$Region = '',
        [string[]]$Changed = @(), [string[]]$Failed = @(), [string[]]$NotOffered = @(), [string[]]$Kept = @(), [string[]]$AlreadyHave = @(),
        [switch]$Neutral, [switch]$Unattended, [switch]$DeferDetails
    )
    $title = if ($Neutral) {
        if ($Changed.Count -gt 0) { 'Region put back to the automatic choice for {0}.' -f (Format-TpmGameCount -Count $Changed.Count) }
        elseif ($Failed.Count -gt 0) { 'Region was not put back to the automatic choice for any game.' }
        else { 'No game was changed.' }
    } else {
        if ($Changed.Count -gt 0) { 'Region set to {0} for {1}.' -f $Region, (Format-TpmGameCount -Count $Changed.Count) }
        elseif ($Failed.Count -gt 0) { 'Region was not set to {0} for any game.' -f $Region }
        else { 'No game was set to {0}.' -f $Region }
    }
    if ($NotOffered.Count -gt 0) {
        $verb = if ($Neutral) { @('has no automatic choice', 'have no automatic choice') } else { @('does not offer it', 'do not offer it') }
        $title += if ($NotOffered.Count -eq 1) { ' 1 game {0} and stays as it is.' -f $verb[0] } else { ' {0} {1} and stay as they are.' -f (Format-TpmGameCount -Count $NotOffered.Count), $verb[1] }
    }
    $blocks = New-Object System.Collections.Generic.List[object]
    $doneHeading = if ($Neutral) { 'Put back to the automatic choice' } else { 'Region set to {0}' -f $Region }
    $notHeading = if ($Neutral) { 'Have no automatic choice (stay as they are)' } else { 'Do not offer this region (stay as they are)' }
    $haveHeading = if ($Neutral) { 'Already on the automatic choice' } else { 'Already set to {0}' -f $Region }
    if ($Changed.Count -gt 0) { [void]$blocks.Add(@{ Heading = $doneHeading; Lines = $Changed }) }
    if ($NotOffered.Count -gt 0) { [void]$blocks.Add(@{ Heading = $notHeading; Lines = $NotOffered }) }
    if ($AlreadyHave.Count -gt 0) { [void]$blocks.Add(@{ Heading = $haveHeading; Lines = $AlreadyHave }) }
    if ($Kept.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Already had a region chosen (kept)'; Lines = $Kept }) }
    if ($Failed.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Could not be changed'; Lines = $Failed }) }
    $needs = if ($Failed.Count -gt 0) { @('{0} could not be changed. See Details.' -f (Format-TpmGameCount -Count $Failed.Count)) } else { @() }
    $status = if ($Failed.Count -eq 0) { 'Ok' } elseif ($Changed.Count -eq 0) { 'Problem' } else { 'Attention' }
    Write-TpmOutcome -Title $title -Status $status -Needs $needs -DetailBlocks $blocks.ToArray() -DetailsNote 'Region choice.' -Unattended:$Unattended -DeferDetails:$DeferDetails
}

# Asks once which region the user wants, then sets it on every newly registered profile that offers it.
# Only a game that is on its automatic choice is changed. A game on another region keeps it. A game with no automatic choice
# (its list is only countries) already holds its stock default and is never changed here. A game that does not offer the region stays.
# Writes use the registration safety backup and are read back. Nothing is asked in an unattended run or a preview.
function Invoke-TpmRegionChoice {
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Codes,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)]$Result,
        [bool]$DryRun = $false,
        [switch]$Unattended
    )
    if ($DryRun -or $Codes.Count -eq 0) { return }
    if (-not (Test-TpmInteractiveInput -Unattended:$Unattended)) {
        Write-Log 'Region choice: skipped because nobody can answer (unattended run); every game stays as it is.'
        return
    }
    $games = @(Get-TpmRegionGames -Paths @($Codes | ForEach-Object { Join-Path $UserProfilesDir ($_ + '.xml') }))
    $offers = @(Get-TpmRegionOffers -Games @($games | Where-Object { $_.IsNeutral }))
    if ($offers.Count -eq 0) { Write-Log 'Region choice: skipped because no new game offers a region.'; return }
    $choice = Read-TpmRegionChoice -Offers $offers -ZeroText 'Leave as is'
    if ($choice.Back) { Write-Log 'Region choice: the user left every game as it is.'; return }
    $region = $choice.Region
    Write-Log ('Region choice: the user chose {0} for {1} new game(s) that have a Region setting.' -f $region, $games.Count)

    $toSet = New-Object System.Collections.Generic.List[object]
    $notOffered = New-Object System.Collections.Generic.List[string]
    $kept = New-Object System.Collections.Generic.List[string]
    foreach ($g in $games) {
        if ($null -eq $g.Neutral) { Write-Log ('Region choice: {0} has no automatic choice and was left as it is.' -f $g.Code); continue }
        if (-not $g.IsNeutral) { [void]$kept.Add(('{0}: {1}' -f $g.Label, $g.Value)); continue }
        $match = Get-TpmRegionOptionText -Game $g -Region $region
        if ($null -eq $match) { [void]$notOffered.Add($g.Label); continue }
        [void]$toSet.Add([pscustomobject]@{ Path = $g.Path; Label = $g.Label; Was = $g.Value; Writes = $match.Writes })
    }
    $backupError = ''
    if ($toSet.Count -gt 0) {
        try {
            $state = Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'TechnicalDetails') -Name 'SafetyBackupState'
            if (-not ($state -is [hashtable])) { throw 'A verified profile backup is required before setting the region.' }
            [void](Confirm-TpmRegistrationSafetyBackup -State $state -UserProfilesDir $UserProfilesDir)
        } catch { $backupError = $_.Exception.Message }
    }
    $written = Set-TpmProfileRegions -Items $toSet.ToArray() -BackupError $backupError
    Write-TpmRegionResult -Region $region -Changed $written.Changed -Failed $written.Failed -NotOffered $notOffered.ToArray() -Kept $kept.ToArray() -Unattended:$Unattended -DeferDetails
}

# The Region setup menu item: the user picks a region (or Back to automatic), sees the games that offer it with their current
# region, picks all or some of them, confirms how many will change, then the change is made after a verified backup.
# Unlike the question after registration, this may replace a region the user chose earlier: the user asked for it here.
function Invoke-TpmRegionSetup {
    param([Parameter(Mandatory)][string]$UserProfilesDir)
    try {
        $files = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'Region setup profile discovery' -EnumerationErrorAction Stop | Sort-Object BaseName)
    } catch {
        Write-Host '  TeknoParrot Manager could not read your game settings folder. Nothing was changed.' -ForegroundColor Red
        Write-Log ('Region setup: UserProfiles could not be read -- {0}' -f $_.Exception.Message)
        return
    }
    $games = @(Get-TpmRegionGames -Paths @($files | ForEach-Object { $_.FullName }))
    $offers = @(Get-TpmRegionOffers -Games $games)
    $canNeutral = (@($games | Where-Object { $null -ne $_.Neutral -and -not $_.IsNeutral }).Count -gt 0)
    if ($offers.Count -eq 0 -and -not $canNeutral) {
        Write-Host '  None of your games has a region you can pick. Nothing was changed.' -ForegroundColor Yellow
        Write-Log 'Region setup: no registered game has a Region setting to change.'
        return
    }
    $choice = Read-TpmRegionChoice -Offers $offers -ZeroText 'Go back (change nothing)' -OfferNeutral:$canNeutral
    if ($choice.Back) { Write-Host '  Nothing was changed.' -ForegroundColor DarkGray; Write-Log 'Region setup: the user went back.'; return }
    $toNeutral = [bool]$choice.Neutral
    $region = $choice.Region
    $target = if ($toNeutral) { 'the automatic choice' } else { $region }

    $eligible = @{}
    $notOffered = New-Object System.Collections.Generic.List[string]
    $alreadyHave = New-Object System.Collections.Generic.List[string]
    foreach ($g in $games) {
        $match = if ($toNeutral) { Get-TpmRegionOptionText -Game $g -Neutral } else { Get-TpmRegionOptionText -Game $g -Region $region }
        if ($null -eq $match) { [void]$notOffered.Add($g.Label); continue }
        $g | Add-Member -NotePropertyName Match -NotePropertyValue $match -Force
        $held = Test-TpmRegionHeld -Game $g -Match $match
        if ($held) { [void]$alreadyHave.Add($g.Label) }
        # Back to automatic lists only games that are not on it yet.
        if (-not $toNeutral -or -not $held) { $eligible[$g.Path] = $g }
    }
    if ($eligible.Count -eq 0) { Write-Host ('  Every game that offers {0} already has it. Nothing was changed.' -f $target) -ForegroundColor DarkGray; return }
    $eligibleFiles = @($files | Where-Object { $eligible.ContainsKey($_.FullName) })
    $suffix = @{}
    foreach ($path in $eligible.Keys) { $suffix[$path] = ' (now: {0})' -f $eligible[$path].Value }
    Write-Host ''
    Write-TpmText -Text ('These games can be set to {0}. Choose which ones to change.' -f $target) -Color Cyan -Indent 2
    $picked = @(Select-RegisteredGamesInteractive -UserProfilesDir $UserProfilesDir -Profiles $eligibleFiles -LabelSuffix $suffix -DefaultAll)

    $plan = New-Object System.Collections.Generic.List[object]
    foreach ($file in $picked) {
        $g = $eligible[$file.FullName]
        if (-not (Test-TpmRegionHeld -Game $g -Match $g.Match)) { [void]$plan.Add([pscustomobject]@{ Path = $g.Path; Label = $g.Label; Was = $g.Value; Writes = $g.Match.Writes }) }
    }
    if ($plan.Count -eq 0) {
        Write-Host '  Nothing to change: no game was picked, or the picked games already have it. Nothing was changed.' -ForegroundColor DarkGray
        Write-Log 'Region setup: nothing to change after the selection.'
        return
    }
    Write-Host ''
    $whyNot = if ($toNeutral) { 'have no automatic choice' } else { 'do not offer it' }
    Write-TpmText -Text ('{0} will be changed to {1}. Games that {2} stay as they are: {3}. Games that already have it: {4}.' -f (Format-TpmGameCount -Count $plan.Count), $target, $whyNot, $notOffered.Count, $alreadyHave.Count) -Color Yellow -Indent 2
    if ((Read-TpmYesNo -Prompt '  Change them now? (Y/N)' -Default 'N') -ne 'Y') {
        Write-Host '  Nothing was changed.' -ForegroundColor DarkGray
        Write-Log 'Region setup: the user declined the change.'
        return
    }
    $backupError = ''
    try {
        $backup = New-TpmVerifiedUserProfilesBackup -UserProfilesDir $UserProfilesDir -Label 'RegionSetup'
        if (-not [bool](Get-TpmTransactionField -Object $backup -Name 'Verified' -Default $false)) { $backupError = 'The safety backup could not be verified.' }
    } catch { $backupError = $_.Exception.Message }
    $written = Set-TpmProfileRegions -Items $plan.ToArray() -BackupError $backupError
    Write-TpmRegionResult -Region $region -Changed $written.Changed -Failed $written.Failed -NotOffered $notOffered.ToArray() -AlreadyHave $alreadyHave.ToArray() -Neutral:$toNeutral
}

# Scans the install folder for executables and registers matching TeknoParrot
# profiles by setting <GamePath> in a copy written to UserProfiles. Three passes:
#   1 -- exe filename -> profile index (built from <ExecutableName> in GameProfile XMLs)
#   2 -- dat lookup for folders whose exe name is not in any profile
#   3 -- Dice-match normalized folder name against profile code names, resolving
#        games with empty <ExecutableName> (BladeStrangers, LuigisMansion, etc.)
# Existing UserProfiles are never overwritten.
# A profile code can only be claimed once per run (TeknoParrot allows exactly
# one GamePath per profile). Folders that resolve to a code already claimed by
# an earlier folder (e.g. several ROM revisions sharing one generic exe name
# and one profile, like multiple Virtua Fighter 5 Lindbergh dumps) remain unresolved choices.
function Register-Games {
    param([string]$userProfilesDir,[string]$installFolder,[hashtable]$profileIndex,[string]$gameProfilesDir='', [hashtable]$datIndex=$null,[System.Collections.Generic.HashSet[string]]$profileSet=$null,[bool]$DryRun=$false,[string]$tpRootDir='', [hashtable]$subFolderMap=$null,[string[]]$GameFolders=$null)
    $backup=$null
    # The safety backup is made lazily before the first real profile write
    # (Confirm-TpmRegistrationSafetyBackup); a run that writes nothing makes none.
    $backupState = @{ Backup = $null; Done = $false; Error = $null }
    if (-not $DryRun) {
        $ledgerReady = Test-TpmRegistrationLedgerReady -AdoptActive:($null -ne $GameFolders -and $GameFolders.Count -gt 0)
        if (-not $ledgerReady.Ready) {
            Write-Host ('  ' + $ledgerReady.Message) -ForegroundColor Red
            Write-Log ('Register-Games refused before any write: ' + $ledgerReady.Message)
            [void](Close-TpmRegistrationLedgerOperations -Reason 'EVIDENCE_GATE_REFUSED')
            $refusalSummary = if ($ledgerReady.PSObject.Properties['Summary'] -and -not [string]::IsNullOrWhiteSpace([string]$ledgerReady.Summary)) { [string]$ledgerReady.Summary } else { [string]$ledgerReady.Message }
            if (-not (Test-TpmTransactionUserSafeSummary -Summary $refusalSummary)) { $refusalSummary = 'Action required: the registration evidence ledger is unavailable. No game extraction or registration was started, and the existing ledger was not changed. Keep the ledger file as it is, create a support package, and ask for help before running again.' }
            return (New-TpmProfileTransactionResult -WorkflowKey 'GameRegistration' -OperationKey 'RegisterProfiles' -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' -Summary $refusalSummary -Items @() -ReasonCode 'REGISTRATION_EVIDENCE_UNAVAILABLE' -FinalChecks @('No game profile write was attempted.'))
        }
    }
    try {
        $legacy=Register-GamesLegacy -userProfilesDir $userProfilesDir -installFolder $installFolder -profileIndex $profileIndex -gameProfilesDir $gameProfilesDir -datIndex $datIndex -profileSet $profileSet -DryRun $DryRun -tpRootDir $tpRootDir -subFolderMap $subFolderMap -GameFolders $GameFolders -BackupState $backupState
    } catch {
        $script:TpmRegistrationLedger = $null   # open operations stay PENDING on disk and are reported INTERRUPTED_UNKNOWN
        throw
    }
    Set-TpmLedgerField -Object $legacy -Name 'SafetyBackupState' -Value $backupState
    $backup = $backupState['Backup']
    if ($legacy.LedgerRefusal) {
        $ledgerRefusalSummary = if ($legacy.PSObject.Properties['LedgerRefusalSummary'] -and -not [string]::IsNullOrWhiteSpace([string]$legacy.LedgerRefusalSummary)) { [string]$legacy.LedgerRefusalSummary } else { [string]$legacy.LedgerRefusal }
        if (-not (Test-TpmTransactionUserSafeSummary -Summary $ledgerRefusalSummary)) { $ledgerRefusalSummary = 'Action required: the registration evidence ledger is unavailable. No game extraction or registration was started, and the existing ledger was not changed. Keep the ledger file as it is, create a support package, and ask for help before running again.' }
        return (New-TpmProfileTransactionResult -WorkflowKey 'GameRegistration' -OperationKey 'RegisterProfiles' -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' -Summary $ledgerRefusalSummary -Items @() -Backup $backup -ReasonCode 'REGISTRATION_EVIDENCE_UNAVAILABLE' -FinalChecks @('No game profile write was attempted.'))
    }
    $registrationResult = ConvertTo-TpmRegistrationResult -Legacy $legacy -Backup $backup -DryRun $DryRun
    if (-not $DryRun) {
        $ledgerEvidence = Close-TpmRegistrationLedgerOperations -Legacy $legacy -Result $registrationResult -InstallBase $installFolder
        if ($ledgerEvidence.Stopped) {
            # Close itself can be the failing boundary. Preserve this fact in Legacy
            # too, because manual/duplicate reporting may rebuild the result later.
            Set-TpmLedgerField -Object $legacy -Name 'EvidenceStopped' -Value $true
            $registrationResult = ConvertTo-TpmRegistrationResult -Legacy $legacy -Backup $backup -DryRun $false
        }
        $registrationResult | Add-Member -NotePropertyName LedgerEvidence -NotePropertyValue $ledgerEvidence -Force
        if ($ledgerEvidence.Status -eq 'UNCERTAIN' -and $registrationResult.PSObject.Properties['Warnings']) { $registrationResult.Warnings = @($registrationResult.Warnings) + [string]$ledgerEvidence.Message }
    }
    return $registrationResult
}
# Writes one game's GamePath (and secondary exe) into its profile and reads it back. A verified backup comes first, the
# before-state is recorded for failure reporting, and the saved path is verified after the save.
function Set-TpmRegistrationGamePath {
    param([string]$TemplatePath, [string]$ExePath, [string]$UserProfile, $DryRun, $BackupState, [string]$UserProfilesDir, $MutationRecords, [ref]$PreWriteState, [ref]$WriteAttempted)
    $tpl = Read-Xml $TemplatePath
    # SelectSingleNode returns the node if it exists (even when empty)
    # and $null only when truly absent. This avoids creating a second
    # GamePath element, which would make the value assignment ambiguous.
    $gp = $tpl.GameProfile.SelectSingleNode("GamePath")
    if ($null -eq $gp) {
        $gp = $tpl.CreateElement("GamePath")
        [void]$tpl.GameProfile.PrependChild($gp)
    }
    $gp.InnerText = $ExePath
    [void](Set-SecondaryExecutablePath $tpl $ExePath -ProfileCode ([System.IO.Path]::GetFileNameWithoutExtension($TemplatePath)))
    if (-not $DryRun) { [void](Confirm-TpmRegistrationSafetyBackup -State $BackupState -UserProfilesDir $UserProfilesDir) }
    if (-not $DryRun) { $PreWriteState.Value = Get-TpmProfileWriteFingerprint -Path $UserProfile }
    $WriteAttempted.Value = -not $DryRun
    Save-XmlMaybe $tpl $UserProfile $DryRun
    if (-not $DryRun) { Assert-TpmRegisteredGamePath -ProfilePath $UserProfile -ExpectedGamePath $ExePath -RegistrationState $MutationRecords }
}

function Register-GamesLegacy {
    param([string]$userProfilesDir, [string]$installFolder, [hashtable]$profileIndex,
          [string]$gameProfilesDir = '', [hashtable]$datIndex = $null,
          [System.Collections.Generic.HashSet[string]]$profileSet = $null,
          [bool]$DryRun = $false,
          [string]$tpRootDir = '', [hashtable]$subFolderMap = $null,
          [string[]]$GameFolders = $null, [hashtable]$BackupState = $null)
    if ($null -eq $datIndex) { $datIndex = @{} }
    $gameFileExtensions = @(Get-TpmProfileFileExtensions -ProfileIndex $profileIndex)

    $discoveryStarted = Get-Date
    $discoveryWatch = [System.Diagnostics.Stopwatch]::StartNew()
    $discoveryState = [pscustomobject]@{ Current = 0; RootOffset = 0; RootSeen = 0; LastReportMilliseconds = -5000 }
    $discoveryProgress = {
        param($file, $seen)
        $discoveryState.RootSeen = [int]$seen
        $discoveryState.Current = [int]($discoveryState.RootOffset + [int]$seen)
        $elapsedMilliseconds = $discoveryWatch.ElapsedMilliseconds
        if (($elapsedMilliseconds - $discoveryState.LastReportMilliseconds) -ge 5000) {
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Game-file discovery' -Current $discoveryState.Current -Total 0 -StartedAt $discoveryStarted
            $discoveryState.LastReportMilliseconds = $elapsedMilliseconds
        }
    }
    Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Game-file discovery' -Current 0 -Total 0 -StartedAt $discoveryStarted
    $discoveryCompleted = $false
    try {
        if ($null -eq $GameFolders -or $GameFolders.Count -eq 0) {
            $exeFiles = @(Get-GameFiles $installFolder -ProgressScript $discoveryProgress -ExtraExtensions $gameFileExtensions)
            $discoveryState.Current = [int]($discoveryState.RootOffset + $discoveryState.RootSeen)
        } else {
            $installRoot = [System.IO.Path]::GetFullPath($installFolder).TrimEnd('\')
            $scanRoots = New-Object System.Collections.Generic.List[string]
            foreach ($folder in $GameFolders) {
                $child = [System.IO.Path]::GetFullPath((Join-Path $installRoot ([string]$folder))).TrimEnd('\')
                if (-not (Test-PathInside $child $installRoot) -or -not (Test-Path -LiteralPath $child -PathType Container)) {
                    Write-Log "Register-Games: rejected unsafe or missing filtered game folder '$folder'."
                    continue
                }
                [void]$scanRoots.Add($child)
            }
            $exeFileCandidates = New-Object System.Collections.Generic.List[object]
            foreach ($scanRoot in $scanRoots) {
                $discoveryState.RootSeen = 0
                $rootCandidates = @(Get-GameFiles $scanRoot -ProgressScript $discoveryProgress -ExtraExtensions $gameFileExtensions)
                foreach ($candidate in $rootCandidates) { [void]$exeFileCandidates.Add($candidate) }
                $discoveryState.RootOffset += [int]$discoveryState.RootSeen
                $discoveryState.Current = [int]$discoveryState.RootOffset
            }
            $exeFiles = $exeFileCandidates.ToArray()
        }
        $discoveryCompleted = $true
    } finally {
        if ($discoveryCompleted) {
            Write-Host ("Game-file discovery: ended; candidates={0}; visited={1}." -f $exeFiles.Count, $discoveryState.Current) -ForegroundColor Green
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Game-file discovery' -Current $discoveryState.Current -Total 0 -StartedAt $discoveryStarted -Complete
        } else {
            Write-Host ("Game-file discovery: interrupted; last-reported-visited={0}." -f $discoveryState.Current) -ForegroundColor Yellow
            Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Game-file discovery' -Current $discoveryState.Current -Total 0 -StartedAt $discoveryStarted -Complete -Outcome Error
        }
    }
    # #352/#365: freeze and publish the candidate manifest before the first profile write.
    # AutoSync registration adopts the units Invoke-AutoSync already published; a RegisterOnly
    # scan freezes the folders just discovered. Preview runs never touch the ledger.
    if (-not $DryRun -and (Test-TpmRegistrationLedgerConfigured)) {
        $adoptLedger = ($null -ne $GameFolders -and $GameFolders.Count -gt 0 -and $script:TpmRegistrationLedger -and $script:TpmRegistrationLedger.ActiveIds.Count -gt 0)
        if (-not $adoptLedger) {
            $script:TpmRegistrationLedger = $null
            $ledgerBase = $installFolder.TrimEnd('\')
            $ledgerFolders = @($exeFiles | ForEach-Object { ($_.FullName.Substring($ledgerBase.Length).TrimStart('\') -split '\\')[0] } | Sort-Object -Unique)
            $ledgerOpen = Open-TpmRegistrationLedgerOperation -Mode RegisterOnly -Units @($ledgerFolders | ForEach-Object { [pscustomobject]@{ Folder = [string]$_ } }) -InstallRoot $installFolder
            if (-not $ledgerOpen.Opened) {
                Write-Host ('  ' + $ledgerOpen.Message) -ForegroundColor Red
                Write-Log ('Register-Games refused before any write: ' + $ledgerOpen.Message)
                return [pscustomobject]@{ Registered = (New-Object System.Collections.ArrayList); Already = (New-Object System.Collections.ArrayList); Ambiguous = @(); Unmatched = @(); MutationRecords = [pscustomobject]@{ Changed = (New-Object System.Collections.ArrayList); Failures = (New-Object System.Collections.ArrayList) }; Decisions = (New-Object System.Collections.ArrayList); LedgerRefusal = [string]$ledgerOpen.Message; LedgerRefusalSummary = [string]$ledgerOpen.Summary }
            }
        }
    }
    $registered     = New-Object System.Collections.ArrayList
    $already        = New-Object System.Collections.ArrayList
    $ambiguous      = New-Object System.Collections.ArrayList
    $mutationRecords = [pscustomobject]@{ Changed = (New-Object System.Collections.ArrayList); Failures = (New-Object System.Collections.ArrayList) }
    $decisions = New-Object System.Collections.ArrayList
    $seenCodes      = @{}

    $codeClaimedBy  = @{}   # profile code -> folder name that already claimed it this run
    # Snapshot of codes that already had a UserProfile BEFORE this run started.
    # Needed to tell apart two genuinely different situations that both make
    # $seenCodes.ContainsKey($code) true: (1) the code was already registered
    # (by TeknoParrotUI or an earlier run) before this run touched anything --
    # not a conflict, just report "Already"; vs (2) two folders THIS run both
    # resolved to the SAME unclaimed code -- a real conflict between two
    # fresh candidates. Without this distinction, a folder whose own exe
    # happens to share a name with dozens of other titles (e.g. NESiCAxLive's
    # game.exe) gets falsely flagged as "duplicate" every time an unrelated
    # already-registered sibling from that same shared-exe pool is scanned
    # first and incidentally marks this folder's own code as "seen".
    $preExistingCodes = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $preExistingFiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $userProfilesDir -ProgressLabel 'Existing profile index discovery' -EnumerationErrorAction SilentlyContinue)
    $profileScanStarted = Get-Date
    $profileScanCurrent = 0
    $profileScanCurrentDone = $false
    try {
        foreach ($existingProfile in $preExistingFiles) {
            $profileScanCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'Existing profile index' -Current $profileScanCurrent -Total $preExistingFiles.Count -StartedAt $profileScanStarted
            [void]$preExistingCodes.Add($existingProfile.BaseName)
        }
        $profileScanCurrentDone = $true
    } finally {
        if ($preExistingFiles.Count -gt 0) {
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'Existing profile index' -Current $(if ($profileScanCurrentDone) { $profileScanCurrent } else { $profileScanCurrent - 1 }) -Total $preExistingFiles.Count -StartedAt $profileScanStarted -Complete -Outcome $(if ($profileScanCurrentDone) { 'Final' } else { 'Error' })
        }
    }
    # Maps an exe's exact full path to the profile code already pointing at it
    # (if any). This is a stronger, name-independent signal than fuzzy-matching
    # the folder name against candidate profile codes: it catches a folder
    # whose correct profile is already configured even when that profile's own
    # code never scores high enough against the folder name to be picked
    # automatically (e.g. a generic/typo'd code like "Primevil" for "Primeval
    # Hunt"), and even when the correct profile was never a fuzzy-match
    # candidate at all because its own ExecutableName differs from this exe's
    # filename (e.g. "Nosferatu" not appearing among the "main.exe" candidates
    # for Nosferatu Lilinor). See issue #9.
    $gamePathIndex = [System.Collections.Generic.Dictionary[string,string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $gamePathProfiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $userProfilesDir -ProgressLabel 'Existing GamePath index discovery' -EnumerationErrorAction SilentlyContinue)
    $gamePathScanStarted = Get-Date
    $gamePathScanCurrent = 0
    $gamePathScanCurrentDone = $false
    try {
        foreach ($existingProfile in $gamePathProfiles) {
            $gamePathScanCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'Existing GamePath index' -Current $gamePathScanCurrent -Total $gamePathProfiles.Count -StartedAt $gamePathScanStarted
            try {
                $existingDoc = Read-Xml $existingProfile.FullName
                $gpNode = $existingDoc.GameProfile.SelectSingleNode("GamePath")
                if ($null -ne $gpNode -and $gpNode.InnerText) {
                    # Trim() first: a GamePath written by a tool other than this
                    # script's own Save-Xml could carry incidental leading/trailing
                    # whitespace, which would otherwise make this key never match
                    # $exe.FullName (a clean FileInfo path) even when they refer to
                    # the same file. See issue #9.
                    $gamePathIndex[$gpNode.InnerText.Trim().TrimEnd('\')] = $existingProfile.BaseName
                }
            } catch {
                Write-Log ("Register-Games: WARNING -- could not parse existing UserProfile '$($existingProfile.BaseName)' while building GamePath index: $_")
            }
        }
        $gamePathScanCurrentDone = $true
    } finally {
        if ($gamePathProfiles.Count -gt 0) {
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'Existing GamePath index' -Current $(if ($gamePathScanCurrentDone) { $gamePathScanCurrent } else { $gamePathScanCurrent - 1 }) -Total $gamePathProfiles.Count -StartedAt $gamePathScanStarted -Complete -Outcome $(if ($gamePathScanCurrentDone) { 'Final' } else { 'Error' })
        }
    }
    $installBase    = $installFolder.TrimEnd('\')
    $matchedFolders = @{}
    $allExeFolders  = @{}
    $_regTotal = $exeFiles.Count
    $_regI     = 0
    $_regStopped = $false

    foreach ($exe in $exeFiles) {
        if (Test-TpmRegistrationLedgerStopped) { $_regStopped = $true; break }
        $_regI++
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Registration executable discovery' -Current $_regI -Total $_regTotal
        $relPath    = $exe.FullName.Substring($installBase.Length).TrimStart('\')
        $folderName = ($relPath -split '\\')[0]
        $folderKey  = $folderName -replace '\.(teknoparrot|parrot|game)$', ''   # strip suffix for matching/tracking
        $allExeFolders[$folderKey] = $folderName   # store original name (with any suffix) for path resolution

        $key = $exe.Name.ToLowerInvariant()
        if (-not $profileIndex.ContainsKey($key)) { continue }

        # A game that names a set of ZIPs ("child.zip;parent.zip") only counts when the other ZIPs are beside the file that was found.
        $matchList = @($profileIndex[$key] | Where-Object { @(Get-TpmMissingGameSetFiles -GamePath $exe.FullName -ExecutableName ([string]$_.ExeName)).Count -eq 0 })
        if ($matchList.Count -eq 0) { Write-Log ("Registration: {0} was left alone because the other ZIP its profile names is not beside it." -f $exe.FullName); continue }

        # Same executable name maps to more than one profile.
        # Attempt folder-name fuzzy matching before giving up.
        if ($matchList.Count -gt 1) {
            # $matchedFolders is set per conclusive outcome below, NOT
            # unconditionally just because this exe's filename happened to
            # appear in $profileIndex. A folder can contain more than one
            # exe-like file (an installer, an uninstaller, a redistributable
            # stub, the real launcher); if an unrelated one of those happens
            # to collide with some other profile's <ExecutableName>, marking
            # the whole folder "matched" on that collision alone would
            # permanently block Pass 2/3 below from ever getting a chance to
            # resolve the folder's REAL exe via the dat -- even though this
            # specific exe was never actually identified. $resolved tracks
            # whether THIS exe's own outcome was conclusive; it defaults true
            # and is only flipped false at the genuinely-unresolved "shared"
            # ambiguous outcomes further down. See issue #10.
            $resolved = $true

            # Exact-path check first, ahead of any fuzzy-name matching: if an
            # existing UserProfile already points its GamePath at this exact
            # exe, this folder is fully handled regardless of whether that
            # profile's own code name fuzzy-matches the folder name at all, or
            # was even among $matchList's candidates. See issue #9.
            if ($gamePathIndex.ContainsKey($exe.FullName)) {
                $existingCode = $gamePathIndex[$exe.FullName]
                if (-not $seenCodes.ContainsKey($existingCode)) {
                    if ($already -notcontains $existingCode) { [void]$already.Add($existingCode) }
                    $seenCodes[$existingCode] = $true
                    $codeClaimedBy[$existingCode] = "(already registered in TeknoParrotUI)"
                    Backfill-SecondaryExecutablePath (Join-Path $userProfilesDir ($existingCode + ".xml")) $DryRun -RegistrationState $mutationRecords -BackupState $BackupState -UserProfilesDir $userProfilesDir -Folder $folderName
                }
                $matchedFolders[$folderKey] = $true
                continue
            }

            # $folderKey has the RetroBat suffix stripped, ready to normalize.
            # The $RawThrillsPathLimits alias fallback (e.g. NicktoonsNitro -> NTN,
            # for a folder renamed to this script's own PATH TOO LONG suggestion --
            # see issue #13) is handled inside Resolve-BestFuzzyMatch.
            $normFolder  = Get-NormalizedGameKey $folderKey

            $fuzzyResult    = Resolve-BestFuzzyMatch -NormFolder $normFolder -MatchList $matchList -RawThrillsAliases $RawThrillsPathLimits -NormBaseTitle (Get-TpmBaseTitleKey $folderKey)
            # A game that has no entry in the DAT (for example the newest Golden Tee years) can only be told apart by name. Where the profile code alone is
            # not enough, TeknoParrot's own game name for each candidate ("Golden Tee Live 2023-2024") is tried as a second name, under the same rules.
            if (-not $fuzzyResult.IsConfidentMatch -and $gameProfilesDir) {
                $tpNames = Get-TpmTeknoParrotNamesForCodes -GameProfilesDir $gameProfilesDir -Codes @($matchList | ForEach-Object { [string]$_.Code })
                if ($tpNames.Count -gt 0) {
                    $namedResult = Resolve-BestFuzzyMatch -NormFolder $normFolder -MatchList $matchList -RawThrillsAliases $RawThrillsPathLimits -NormBaseTitle (Get-TpmBaseTitleKey $folderKey) -AlternateNames $tpNames
                    if ($namedResult.IsConfidentMatch) { $fuzzyResult = $namedResult }
                }
            }
            $bestFuzzy      = $fuzzyResult.Best
            $bestFuzzyScore = $fuzzyResult.BestScore

            # The Eggman list names this folder's own game. Among profiles that share one file name the name match is only a guess, so
            # when the list names a different profile for the folder (The King of Fighters XII against XIV read almost the same), the
            # list wins: nothing is claimed here and the list pass below registers the folder.
            $datNamedCodes = @(Get-TpmDatNamedProfileCodes -FolderKey $folderKey -DatIndex $datIndex -GameProfilesDir $gameProfilesDir -ProfileSet $profileSet)
            if ($fuzzyResult.IsConfidentMatch -and $datNamedCodes.Count -gt 0 -and $datNamedCodes -notcontains $bestFuzzy.Code) {
                Write-Log ("DatIndex (shared exe name): did not claim {0} for folder '{1}' -- the dat names profile {2} for this folder" -f $bestFuzzy.Code, $folderName, ($datNamedCodes -join ' or '))
                $resolved = $false
            } elseif ($fuzzyResult.IsConfidentMatch) {
                # High-confidence fuzzy match: register automatically.
                $code = $bestFuzzy.Code
                if ($seenCodes.ContainsKey($code)) {
                    if ($preExistingCodes.Contains($code)) {
                        # Already registered before this run started (TeknoParrotUI
                        # or an earlier run) -- not a conflict from this run's
                        # perspective, just confirm it's set and move on. (Guard
                        # against a duplicate "Already" entry: an earlier folder's
                        # alreadyReg scan may have already recorded this same code.)
                        if ($already -notcontains $code) { [void]$already.Add($code) }
                    } else {
                        # Another folder already claimed this profile code THIS run --
                        # TeknoParrot can only point one profile at one executable, so
                        # this is a real conflict, not a silent duplicate to drop.
                        [void]$ambiguous.Add([pscustomobject]@{
                            Exe        = $exe.FullName
                            Codes      = $code
                            BestGuess  = $code
                            BestScore  = 1.0
                            Reason     = "duplicate"
                            ClaimedBy  = $codeClaimedBy[$code]
                        })
                    }
                    continue
                }
                $userProfile = Join-Path $userProfilesDir ($code + ".xml")
                if (Test-Path -LiteralPath $userProfile) {
                    [void]$already.Add($code); $seenCodes[$code] = $true; $codeClaimedBy[$code] = $folderName
                    Backfill-SecondaryExecutablePath $userProfile $DryRun -RegistrationState $mutationRecords -BackupState $BackupState -UserProfilesDir $userProfilesDir -Folder $folderName
                } else {
                    # Mark seen before the file operation so that if Save throws,
                    # a second exe match for the same code doesn't cause a duplicate
                    # attempt (and duplicate error output) within the same run.
                    $seenCodes[$code] = $true
                    $codeClaimedBy[$code] = $folderName
                    $registrationWriteAttempted = $false; $ledgerMapping = $null; $preWriteState = $null
                    try {
                        $ledgerMapping = Start-TpmRegistrationMapping -Folder $folderName -Code $code -Match 'exe-fuzzy' -IntendedPath $exe.FullName -TemplatePath $bestFuzzy.TemplatePath -DryRun $DryRun
                        Set-TpmRegistrationGamePath -TemplatePath $bestFuzzy.TemplatePath -ExePath $exe.FullName -UserProfile $userProfile -DryRun $DryRun -BackupState $BackupState -UserProfilesDir $userProfilesDir -MutationRecords $mutationRecords -PreWriteState ([ref]$preWriteState) -WriteAttempted ([ref]$registrationWriteAttempted)
                        Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome VERIFIED
                        [void]$registered.Add([pscustomobject]@{
                            Code        = $code
                            GamePath    = $exe.FullName
                            FuzzyScore  = [Math]::Round($bestFuzzyScore, 2)
                            FuzzyFolder = $folderName
                        })
                        Write-Log "Registered (fuzzy $([Math]::Round($bestFuzzyScore,2))) $code -> $($exe.FullName)  [folder: $folderName]"
                    } catch {
                        $saveFailure = Resolve-TpmRegistrationSaveFailure -WriteAttempted $registrationWriteAttempted -PreState $preWriteState -Message $_.Exception.Message
                        Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome FAILED -WriteAttempted $saveFailure.WriteAttempted -Reason $saveFailure.Reason
                        if ($registered.Code -notcontains $code) { [void]$mutationRecords.Failures.Add([pscustomobject]@{ Code=$code; WriteAttempted=$saveFailure.WriteAttempted; Reason='REGISTRATION_NOT_VERIFIED' }) }
                        Write-Host "  FAILED to register $code : $_" -ForegroundColor Red
                        Write-Log "Register (fuzzy) FAILED $code -- $_"
                    }
                }
            } else {
                # Bug fix: check if any candidate is already registered (UserProfile
                # exists) before flagging as ACTION REQUIRED. A game registered via
                # TeknoParrotUI would have a .xml file even though the fuzzy score is
                # below the auto-register threshold.
                # Only a profile that existed BEFORE this run counts here. A profile written for an earlier folder of this same run is not
                # proof that this folder is handled; counting it made the second version of a game vanish without a word.
                $alreadyReg = @($matchList | Where-Object { $preExistingCodes.Contains($_.Code) })
                foreach ($ar in $alreadyReg) {
                    if (-not $seenCodes.ContainsKey($ar.Code)) {
                        if ($already -notcontains $ar.Code) { [void]$already.Add($ar.Code) }
                        $seenCodes[$ar.Code] = $true
                        $codeClaimedBy[$ar.Code] = "(already registered in TeknoParrotUI)"
                        Backfill-SecondaryExecutablePath (Join-Path $userProfilesDir ($ar.Code + ".xml")) $DryRun -RegistrationState $mutationRecords -BackupState $BackupState -UserProfilesDir $userProfilesDir -Folder $folderName
                    }
                }

                # A sibling sharing this exe name being already registered does NOT
                # mean THIS folder's own game is handled -- e.g. H2Overdrive already
                # having a profile says nothing about whether X-Games Snowboarder
                # (a different game sharing the same generic sdaemon.exe loader)
                # does. Only skip this folder if its OWN best-guess candidate
                # specifically is among the already-registered set; otherwise it
                # still needs the dat lookup / manual-registration fallback below,
                # even though some unrelated sibling is already fine.
                $ownAlreadyRegistered = ($null -ne $bestFuzzy) -and
                    (@($alreadyReg | Where-Object { $_.Code -eq $bestFuzzy.Code }).Count -gt 0)

                if (-not $ownAlreadyRegistered) {
                    # Dat-based disambiguation: look up the normalized folder name in the
                    # dat index. The dat's <GameProfile> is authoritative, so if a match is
                    # found we use it directly instead of falling through to ambiguous.
                    $datEntry = if ($datIndex.Count -gt 0) { (Get-DatEntryForZipName -RawZipName $folderKey -DatIndex $datIndex) } else { $null }
                    if ($null -ne $datEntry) {
                        $datCode = $datEntry.ProfileCode
                        # Profile codes are purely alphanumeric; reject anything else to
                        # prevent path traversal via a crafted dat file.
                        if ($datCode -match '^[\w-]+$') {
                            if ($gameProfilesDir) {
                                $datCode = Resolve-ProfileCode $datCode $gameProfilesDir $profileSet
                            }
                            $userProfile = Join-Path $userProfilesDir ($datCode + ".xml")
                            if ($seenCodes.ContainsKey($datCode)) {
                                if ($preExistingCodes.Contains($datCode)) {
                                    if ($already -notcontains $datCode) { [void]$already.Add($datCode) }
                                } else {
                                    [void]$ambiguous.Add([pscustomobject]@{
                                        Exe        = $exe.FullName
                                        Codes      = $datCode
                                        BestGuess  = $datCode
                                        BestScore  = 1.0
                                        Reason     = "duplicate"
                                        ClaimedBy  = $codeClaimedBy[$datCode]
                                    })
                                }
                            } else {
                                $seenCodes[$datCode] = $true
                                $codeClaimedBy[$datCode] = $folderName
                                if (Test-Path -LiteralPath $userProfile) {
                                    [void]$already.Add($datCode)
                                    Backfill-SecondaryExecutablePath $userProfile $DryRun -RegistrationState $mutationRecords -BackupState $BackupState -UserProfilesDir $userProfilesDir -Folder $folderName
                                } else {
                                    $templatePath = Join-Path $gameProfilesDir ($datCode + ".xml")
                                    $exeToUse     = $exe.FullName
                                    if (-not [string]::IsNullOrWhiteSpace($datEntry.Executable)) {
                                        $relExe     = $datEntry.Executable.TrimStart('\', '/')
                                        # Guard: a bare backslash/slash normalizes to an empty
                                        # string; using it as a path component would match the
                                        # game folder itself rather than an executable.
                                        if ($relExe) {
                                            $folderFull = Join-Path $installBase $folderName
                                            $datExe     = Join-Path $folderFull $relExe
                                            # Security: dat-supplied path must stay inside the game folder.
                                            if (Test-PathInside $datExe $folderFull) {
                                                if     (Test-Path -LiteralPath $datExe -PathType Leaf) { $exeToUse = $datExe }
                                                elseif (Test-Path -LiteralPath ($datExe + ".exe")) { $exeToUse = $datExe + ".exe" }
                                                elseif (Test-Path -LiteralPath ($datExe + ".elf")) { $exeToUse = $datExe + ".elf" }
                                            }
                                        }
                                    }
                                    if (Test-Path -LiteralPath $templatePath) {
                                        $registrationWriteAttempted = $false; $ledgerMapping = $null; $preWriteState = $null
                                        try {
                                            $ledgerMapping = Start-TpmRegistrationMapping -Folder $folderName -Code $datCode -Match 'dat-exact' -IntendedPath $exeToUse -TemplatePath $templatePath -DryRun $DryRun
                                            Set-TpmRegistrationGamePath -TemplatePath $templatePath -ExePath $exeToUse -UserProfile $userProfile -DryRun $DryRun -BackupState $BackupState -UserProfilesDir $userProfilesDir -MutationRecords $mutationRecords -PreWriteState ([ref]$preWriteState) -WriteAttempted ([ref]$registrationWriteAttempted)
                                            Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome VERIFIED
                                            [void]$registered.Add([pscustomobject]@{
                                                Code     = $datCode
                                                GamePath = $exeToUse
                                                DatMatch = $true
                                            })
                                            Write-Log "Registered (dat/exact) $datCode -> $exeToUse"
                                        } catch {
                                            $saveFailure = Resolve-TpmRegistrationSaveFailure -WriteAttempted $registrationWriteAttempted -PreState $preWriteState -Message $_.Exception.Message
                                            Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome FAILED -WriteAttempted $saveFailure.WriteAttempted -Reason $saveFailure.Reason
                                            if ($registered.Code -notcontains $datCode) { [void]$mutationRecords.Failures.Add([pscustomobject]@{ Code=$datCode; WriteAttempted=$saveFailure.WriteAttempted; Reason='REGISTRATION_NOT_VERIFIED' }) }
                                            Write-Host "  FAILED to register $datCode : $_" -ForegroundColor Red
                                            Write-Log "Register (dat) FAILED $datCode -- $_"
                                        }
                                    } else {
                                        Write-Log ("DatIndex: template '{0}.xml' not in GameProfiles -- flagging as ambiguous." -f $datCode)
                                        [void]$ambiguous.Add([pscustomobject]@{
                                            Exe       = $exe.FullName
                                            Codes     = ($matchList | ForEach-Object { $_.Code }) -join ", "
                                            BestGuess = $datCode
                                            BestScore = 1.0
                                            Reason    = "shared"
                                        })
                                        $resolved = $false
                                    }
                                }
                            }
                        } else {
                            Write-Log ("DatIndex: invalid ProfileCode '{0}' -- skipped." -f $datCode)
                            [void]$ambiguous.Add([pscustomobject]@{
                                Exe       = $exe.FullName
                                Codes     = ($matchList | ForEach-Object { $_.Code }) -join ", "
                                BestGuess = if ($null -ne $bestFuzzy) { $bestFuzzy.Code } else { $null }
                                BestScore = [Math]::Round($bestFuzzyScore, 2)
                                Reason    = "shared"
                            })
                            $resolved = $false
                        }
                    } else {
                        # Below threshold with no dat entry: flag for manual registration.
                        [void]$ambiguous.Add([pscustomobject]@{
                            Exe       = $exe.FullName
                            Codes     = ($matchList | ForEach-Object { $_.Code }) -join ", "
                            BestGuess = if ($null -ne $bestFuzzy) { $bestFuzzy.Code } else { $null }
                            BestScore = [Math]::Round($bestFuzzyScore, 2)
                            Reason    = "shared"
                        })
                        $resolved = $false
                    }
                }
            }
            # Only mark the folder as accounted for if this exe's own outcome
            # was conclusive (registered/already/duplicate-conflict) -- not
            # when it fell through to a genuinely-unresolved "shared"
            # ambiguous entry. An unresolved exe leaves the folder eligible
            # for Pass 2/3 below, in case a DIFFERENT exe in this same folder
            # (or the folder's name itself) resolves cleanly via the dat or a
            # profile-code fuzzy match. See issue #10.
            if ($resolved) { $matchedFolders[$folderKey] = $true }
            continue
        }

        $match = $matchList[0]
        $code  = $match.Code

        # A file name that only ONE profile lists can still be a file that many games share
        # (for example the NAOMI GD-ROM support file naomigd.zip, which is in 71 DAT game sets).
        # The dat names each game's own profile. When it names a DIFFERENT profile for this
        # folder, this file is not the game: do not claim the profile from it. The folder's own
        # game file registers on its own turn, or the dat pass below registers the folder. See issue #404.
        if ($datIndex.Count -gt 0) {
            $ownDatEntry = (Get-DatEntryForZipName -RawZipName $folderKey -DatIndex $datIndex)
            if ($null -ne $ownDatEntry -and [string]$ownDatEntry.ProfileCode -match '^[\w-]+$') {
                $ownDatCode = [string]$ownDatEntry.ProfileCode
                if ($gameProfilesDir) { $ownDatCode = Resolve-ProfileCode $ownDatCode $gameProfilesDir $profileSet }
                if ($ownDatCode -ine $code) {
                    Write-Log ("DatIndex (single exe name): did not claim {0} for folder '{1}' -- the dat names profile {2} for this folder" -f $code, $folderName, $ownDatCode)
                    continue
                }
            }
        }

        # A shared .zip (such as naomigd.zip) that another folder already claimed this run is not
        # proof of a second copy of the same game. Do not ask a keep/switch question about it and do
        # not mark the folder done: the folder-name passes below can still match the folder's own
        # game, and if none does the folder is listed as one we could not identify. See issue #404.
        if ($exe.Extension -ieq '.zip' -and $seenCodes.ContainsKey($code) -and -not $preExistingCodes.Contains($code)) {
            Write-Log ("Shared file name: '{0}' in folder '{1}' did not claim {2} again -- folder '{3}' already has it; matching '{1}' by its name instead" -f $exe.Name, $folderName, $code, $codeClaimedBy[$code])
            continue
        }

        # Otherwise a single candidate for this exe name is a confident,
        # unambiguous identification (unlike the $matchList.Count -gt 1
        # branch above, this never falls through to an unresolved "shared"
        # outcome) -- safe to mark the folder accounted for unconditionally.
        $matchedFolders[$folderKey] = $true
        if ($seenCodes.ContainsKey($code)) {
            if ($preExistingCodes.Contains($code)) {
                if ($already -notcontains $code) { [void]$already.Add($code) }
            } else {
                # Another folder already claimed this profile code THIS run. Most
                # often this is multiple ROM revisions of the same game sharing one
                # generic exe name and one TeknoParrot profile (e.g. several Virtua
                # Fighter 5 Lindbergh revisions). TeknoParrot can only point that
                # profile at one executable, so surface it instead of dropping it.
                [void]$ambiguous.Add([pscustomobject]@{
                    Exe        = $exe.FullName
                    Codes      = $code
                    BestGuess  = $code
                    BestScore  = 1.0
                    Reason     = "duplicate"
                    ClaimedBy  = $codeClaimedBy[$code]
                })
            }
            continue
        }

        $userProfile = Join-Path $userProfilesDir ($code + ".xml")
        if (Test-Path -LiteralPath $userProfile) {
            [void]$already.Add($code)
            $seenCodes[$code] = $true
            $codeClaimedBy[$code] = $folderName
            Backfill-SecondaryExecutablePath $userProfile $DryRun -RegistrationState $mutationRecords -BackupState $BackupState -UserProfilesDir $userProfilesDir -Folder $folderName
            continue
        }

        # Mark seen before the file operation for the same reason as the fuzzy
        # path: prevents a duplicate attempt if a second matching exe is found.
        $seenCodes[$code] = $true
        $codeClaimedBy[$code] = $folderName
        $registrationWriteAttempted = $false; $ledgerMapping = $null; $preWriteState = $null
        try {
            $ledgerMapping = Start-TpmRegistrationMapping -Folder $folderName -Code $code -Match 'exe-single' -IntendedPath $exe.FullName -TemplatePath $match.TemplatePath -DryRun $DryRun
            Set-TpmRegistrationGamePath -TemplatePath $match.TemplatePath -ExePath $exe.FullName -UserProfile $userProfile -DryRun $DryRun -BackupState $BackupState -UserProfilesDir $userProfilesDir -MutationRecords $mutationRecords -PreWriteState ([ref]$preWriteState) -WriteAttempted ([ref]$registrationWriteAttempted)
            Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome VERIFIED
            [void]$registered.Add([pscustomobject]@{ Code = $code; GamePath = $exe.FullName })
            Write-Log "Registered $code -> $($exe.FullName)"
        } catch {
            $saveFailure = Resolve-TpmRegistrationSaveFailure -WriteAttempted $registrationWriteAttempted -PreState $preWriteState -Message $_.Exception.Message
            Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome FAILED -WriteAttempted $saveFailure.WriteAttempted -Reason $saveFailure.Reason
            if ($registered.Code -notcontains $code) { [void]$mutationRecords.Failures.Add([pscustomobject]@{ Code=$code; WriteAttempted=$saveFailure.WriteAttempted; Reason='REGISTRATION_NOT_VERIFIED' }) }
            Write-Host "  FAILED to register $code : $_" -ForegroundColor Red
            Write-Log "Register FAILED $code -- $_"
        }
    }
    # A stopped registration ledger or any unverified registration means this stage did not finish successfully.
    Write-TpmCompactExtractionProgress -Phase Scanning -Label 'game library' -Current $_regI -Total $_regTotal -Complete -Outcome $(if (-not $_regStopped -and $mutationRecords.Failures.Count -eq 0) { 'Final' } else { 'Error' })

    # Second pass: folders that had recognizable executables but none of them were
    # in $profileIndex (no exe->profile mapping). These are typically games whose
    # executable name is not listed in any GameProfile XML -- common with pcsx2x6,
    # ELF-based Lindbergh games, or custom loaders. Try the dat index: first an
    # exact normalized-name lookup, then a fuzzy scan of all dat keys.
    if ($datIndex.Count -gt 0 -and $gameProfilesDir) {
        foreach ($folderKey in @($allExeFolders.Keys | Where-Object { -not $matchedFolders.ContainsKey($_) })) {
            if (Test-TpmRegistrationLedgerStopped) { break }
            $origName   = $allExeFolders[$folderKey]
            $normFolder = Get-NormalizedGameKey $folderKey
            $datEntry   = (Get-DatEntryForZipName -RawZipName $folderKey -DatIndex $datIndex)
            $datScore   = 1.0

            # Fuzzy dat scan when no exact name match (handles slightly misnamed folders)
            if ($null -eq $datEntry) {
                $bestScore = 0.0
                $bestKey   = $null
                foreach ($dk in $datIndex.Keys) {
                    $score = Get-DiceSimilarity $normFolder $dk
                    if ($score -gt $bestScore) { $bestScore = $score; $bestKey = $dk }
                }
                if ($bestScore -ge $FuzzyAutoThreshold -and $null -ne $bestKey) {
                    # Issue #84: reject a fuzzy dat-name candidate that introduces
                    # extra meaningful title words the folder doesn't have -- e.g.
                    # a "Zoids Infinity" folder must not silently register against
                    # "Zoids Infinity EX Plus" just because the bigram score alone
                    # clears $FuzzyAutoThreshold. A hard block (folder stays
                    # unmatched, same as "no dat entry found"), not a score
                    # penalty or a higher threshold -- see #84's design.
                    $candidateName   = $datIndex[$bestKey].OriginalName
                    $candidateTokens = Get-MeaningfulTitleTokens $candidateName
                    $folderTokens    = Get-MeaningfulTitleTokens $origName
                    $extraTokens     = @($candidateTokens | Where-Object { -not $folderTokens.Contains($_) })
                    if ($extraTokens.Count -gt 0) {
                        Write-Log ("DatIndex (pass2): rejected fuzzy candidate '{0}' for folder '{1}' -- extra title token(s): {2} (score {3:F2})" -f $candidateName, $origName, ($extraTokens -join ', '), $bestScore)
                    } else {
                        $datEntry = $datIndex[$bestKey]
                        $datScore = $bestScore
                    }
                }
            }

            if ($null -eq $datEntry) { continue }

            $datCode = $datEntry.ProfileCode
            if ($datCode -notmatch '^[\w-]+$') {
                Write-Log ("DatIndex (pass2): invalid ProfileCode '{0}' -- skipped folder {1}" -f $datCode, $folderKey)
                continue
            }
            if ($gameProfilesDir) {
                $datCode = Resolve-ProfileCode $datCode $gameProfilesDir $profileSet
            }

            $matchedFolders[$folderKey] = $true   # prevents folder appearing in $unmatched

            if ($seenCodes.ContainsKey($datCode)) {
                if ($preExistingCodes.Contains($datCode)) {
                    if ($already -notcontains $datCode) { [void]$already.Add($datCode) }
                } else {
                    $dupFolderFull = Join-Path $installBase $origName
                    $dupExe = @($exeFiles | Where-Object {
                        $_.FullName.Length -gt $dupFolderFull.Length -and
                        $_.FullName.StartsWith($dupFolderFull + '\')
                    })[0]
                    [void]$ambiguous.Add([pscustomobject]@{
                        Exe        = if ($dupExe) { $dupExe.FullName } else { $dupFolderFull }
                        Codes      = $datCode
                        BestGuess  = $datCode
                        BestScore  = 1.0
                        Reason     = "duplicate"
                        ClaimedBy  = $codeClaimedBy[$datCode]
                    })
                }
                continue
            }
            $seenCodes[$datCode] = $true
            $codeClaimedBy[$datCode] = $origName

            $userProfile = Join-Path $userProfilesDir ($datCode + ".xml")
            if (Test-Path -LiteralPath $userProfile) {
                [void]$already.Add($datCode)
                Backfill-SecondaryExecutablePath $userProfile $DryRun -RegistrationState $mutationRecords -BackupState $BackupState -UserProfilesDir $userProfilesDir -Folder $origName
                continue
            }

            $templatePath = Join-Path $gameProfilesDir ($datCode + ".xml")
            if (-not (Test-Path -LiteralPath $templatePath)) {
                # The list names a game TeknoParrot has no profile for (extra archives the guide marks unsupported). That is not a
                # failure of the Manager: the folder is "not in TeknoParrot", so it stays out of the matched folders and is listed so.
                Write-Log ("DatIndex (pass2): TeknoParrot has no game profile named '{0}' -- folder {1} is not in TeknoParrot" -f $datCode, $folderKey)
                [void]$matchedFolders.Remove($folderKey)
                continue
            }

            # Resolve the exe: dat's Executable path first, then any file in the folder.
            $folderFull = Join-Path $installBase $origName
            $exeToUse   = $null
            if (-not [string]::IsNullOrWhiteSpace($datEntry.Executable)) {
                $relExe = $datEntry.Executable.TrimStart('\', '/')
                if ($relExe) {
                    $datExe = Join-Path $folderFull $relExe
                    if (Test-PathInside $datExe $folderFull) {
                        if     (Test-Path -LiteralPath $datExe              -PathType Leaf) { $exeToUse = $datExe }
                        elseif (Test-Path -LiteralPath ($datExe + ".exe") -PathType Leaf) { $exeToUse = $datExe + ".exe" }
                        elseif (Test-Path -LiteralPath ($datExe + ".elf") -PathType Leaf) { $exeToUse = $datExe + ".elf" }
                    }
                }
            }
            # A file the list itself names for this profile is the game file, so the other ZIP a profile name may list ("child;parent":
            # a merged ROM set holds the child inside the parent) is not needed beside it.
            $exeFromDat = ($null -ne $exeToUse)
            if (-not $exeToUse) {
                # Fallback: pick the first matching file already found for this folder
                $first = @($exeFiles | Where-Object {
                    $_.FullName.Length -gt $folderFull.Length -and
                    $_.FullName.StartsWith($folderFull + '\')
                })[0]
                if ($first) { $exeToUse = $first.FullName }
            }
            if (-not $exeToUse) {
                Write-Log ("DatIndex (pass2): no exe found for '{0}' in folder {1}" -f $datCode, $folderKey)
                Add-TpmRegistrationMappingFailure -Folder $origName -Code $datCode -Match 'dat-pass2' -Reason 'EXECUTABLE_MISSING' -TemplatePath $templatePath -DryRun $DryRun
                [void]$mutationRecords.Failures.Add([pscustomobject]@{ Code=$datCode; WriteAttempted=$false; Reason='EXECUTABLE_MISSING' })
                continue
            }
            if (-not $exeFromDat -and @(Get-TpmMissingGameSetFiles -GamePath $exeToUse -ExecutableName ([string](Get-PrimaryExecutableName $templatePath))).Count -gt 0) {
                Write-Log ("DatIndex (pass2): {0} was left alone because the other ZIP its profile names is not in folder {1}" -f $datCode, $folderKey)
                continue
            }

            $registrationWriteAttempted = $false; $ledgerMapping = $null; $preWriteState = $null
            try {
                $ledgerMapping = Start-TpmRegistrationMapping -Folder $origName -Code $datCode -Match 'dat-pass2' -IntendedPath $exeToUse -TemplatePath $templatePath -DryRun $DryRun
                Set-TpmRegistrationGamePath -TemplatePath $templatePath -ExePath $exeToUse -UserProfile $userProfile -DryRun $DryRun -BackupState $BackupState -UserProfilesDir $userProfilesDir -MutationRecords $mutationRecords -PreWriteState ([ref]$preWriteState) -WriteAttempted ([ref]$registrationWriteAttempted)
                Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome VERIFIED
                $label = if ($datScore -lt 1.0) { "dat/fuzzy $([Math]::Round($datScore,2))" } else { "dat/exact" }
                [void]$registered.Add([pscustomobject]@{
                    Code        = $datCode
                    GamePath    = $exeToUse
                    DatMatch    = $true
                    FuzzyScore  = if ($datScore -lt 1.0) { [Math]::Round($datScore, 2) } else { $null }
                    FuzzyFolder = if ($datScore -lt 1.0) { $origName } else { $null }
                })
                Write-Log "Registered ($label) $datCode -> $exeToUse"
            } catch {
                $saveFailure = Resolve-TpmRegistrationSaveFailure -WriteAttempted $registrationWriteAttempted -PreState $preWriteState -Message $_.Exception.Message
                Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome FAILED -WriteAttempted $saveFailure.WriteAttempted -Reason $saveFailure.Reason
                if ($registered.Code -notcontains $datCode) { [void]$mutationRecords.Failures.Add([pscustomobject]@{ Code=$datCode; WriteAttempted=$saveFailure.WriteAttempted; Reason='REGISTRATION_NOT_VERIFIED' }) }
                Write-Host "  FAILED to register $datCode : $_" -ForegroundColor Red
                Write-Log "Register (dat pass2) FAILED $datCode -- $_"
            }
        }
    }

    # Third pass: folders still unmatched -- Dice-compare normalized folder name
    # against normalized profile code names. Targets games whose GameProfile has
    # an empty <ExecutableName> (BladeStrangers, LuigisMansion, PokkenTournament,
    # etc.) that never entered $profileIndex and have no dat entry.
    if ($gameProfilesDir -and $profileSet -and $profileSet.Count -gt 0) {
        $normCodeList = @(foreach ($code in $profileSet) {
            $n = Get-NormalizedGameKey $code
            if ($n) { [pscustomobject]@{ Code = $code; Norm = $n } }
        })

        foreach ($folderKey in @($allExeFolders.Keys | Where-Object { -not $matchedFolders.ContainsKey($_) })) {
            if (Test-TpmRegistrationLedgerStopped) { break }
            $origName   = $allExeFolders[$folderKey]
            $normFolder = Get-NormalizedGameKey $folderKey
            if (-not $normFolder) { continue }

            $bestScore = 0.0
            $secondScore = 0.0
            $bestCode  = $null
            $bestViaBaseTitle = $false
            # Notes in parentheses after the title ("(Landscape,Bezel)", "(fixed video)") are not part of the game's name; the title alone is scored too.
            $normBaseTitle = Get-TpmBaseTitleKey $folderKey
            foreach ($nc in $normCodeList) {
                $score = Get-DiceSimilarity $normFolder $nc.Norm
                $viaBase = $false
                if ($normBaseTitle) {
                    $baseScore = Get-DiceSimilarity $normBaseTitle $nc.Norm
                    if ($baseScore -gt $score) { $score = $baseScore; $viaBase = $true }
                }
                if ($score -gt $bestScore) { $secondScore = $bestScore; $bestScore = $score; $bestCode = $nc.Code; $bestViaBaseTitle = $viaBase }
                elseif ($score -gt $secondScore) { $secondScore = $score }
            }
            if ($bestScore -lt $FuzzyAutoThreshold -or -not $bestCode) { continue }
            # A match that only exists because of the title-only score must be clearly ahead of the next profile, the same rule the shared-name matcher uses.
            # Otherwise the folder is left for the user to choose, never guessed.
            if ($bestViaBaseTitle -and (($bestScore - $secondScore) -lt $FuzzyTieMargin)) { continue }

            $matchedFolders[$folderKey] = $true

            if ($seenCodes.ContainsKey($bestCode)) {
                if ($preExistingCodes.Contains($bestCode)) {
                    if ($already -notcontains $bestCode) { [void]$already.Add($bestCode) }
                } else {
                    $dupFolderFull = Join-Path $installBase $origName
                    $dupExe = @($exeFiles | Where-Object {
                        $_.FullName.Length -gt $dupFolderFull.Length -and
                        $_.FullName.StartsWith($dupFolderFull + '\')
                    })[0]
                    [void]$ambiguous.Add([pscustomobject]@{
                        Exe        = if ($dupExe) { $dupExe.FullName } else { $dupFolderFull }
                        Codes      = $bestCode
                        BestGuess  = $bestCode
                        BestScore  = 1.0
                        Reason     = "duplicate"
                        ClaimedBy  = $codeClaimedBy[$bestCode]
                    })
                }
                continue
            }
            $seenCodes[$bestCode] = $true
            $codeClaimedBy[$bestCode] = $origName

            $userProfile = Join-Path $userProfilesDir ($bestCode + ".xml")
            if (Test-Path -LiteralPath $userProfile) {
                [void]$already.Add($bestCode)
                Backfill-SecondaryExecutablePath $userProfile $DryRun -RegistrationState $mutationRecords -BackupState $BackupState -UserProfilesDir $userProfilesDir -Folder $origName
                continue
            }

            $templatePath = Join-Path $gameProfilesDir ($bestCode + ".xml")
            if (-not (Test-Path -LiteralPath $templatePath)) {
                Write-Log ("ProfileCode (pass3): no template for '{0}' -- skipping {1}" -f $bestCode, $folderKey)
                Add-TpmRegistrationMappingFailure -Folder $origName -Code $bestCode -Match 'code-pass3' -Reason 'TEMPLATE_MISSING' -TemplatePath $templatePath -DryRun $DryRun
                [void]$mutationRecords.Failures.Add([pscustomobject]@{ Code=$bestCode; WriteAttempted=$false; Reason='TEMPLATE_MISSING' })
                continue
            }

            # Prefer .exe > .elf > extension-less > .xbe > .dll when GameProfile
            # has no ExecutableName to guide us.
            $folderFull = Join-Path $installBase $origName
            $candidates = @($exeFiles | Where-Object {
                $_.FullName.Length -gt $folderFull.Length -and
                $_.FullName.StartsWith($folderFull + '\')
            })
            $exeToUse = $null
            foreach ($prio in @('.exe', '.elf', '', '.xbe', '.dll')) {
                $hit = @($candidates | Where-Object { $_.Extension.ToLowerInvariant() -eq $prio })[0]
                if ($hit) { $exeToUse = $hit.FullName; break }
            }
            if (-not $exeToUse -and $candidates.Count -gt 0) { $exeToUse = $candidates[0].FullName }
            if (-not $exeToUse) {
                Write-Log ("ProfileCode (pass3): no exe found for '{0}' in folder {1}" -f $bestCode, $folderKey)
                Add-TpmRegistrationMappingFailure -Folder $origName -Code $bestCode -Match 'code-pass3' -Reason 'EXECUTABLE_MISSING' -TemplatePath $templatePath -DryRun $DryRun
                [void]$mutationRecords.Failures.Add([pscustomobject]@{ Code=$bestCode; WriteAttempted=$false; Reason='EXECUTABLE_MISSING' })
                continue
            }
            if (@(Get-TpmMissingGameSetFiles -GamePath $exeToUse -ExecutableName ([string](Get-PrimaryExecutableName $templatePath))).Count -gt 0) {
                Write-Log ("ProfileCode (pass3): {0} was left alone because the other ZIP its profile names is not in folder {1}" -f $bestCode, $folderKey)
                continue
            }

            $registrationWriteAttempted = $false; $ledgerMapping = $null; $preWriteState = $null
            try {
                $ledgerMapping = Start-TpmRegistrationMapping -Folder $origName -Code $bestCode -Match 'code-pass3' -IntendedPath $exeToUse -TemplatePath $templatePath -DryRun $DryRun
                Set-TpmRegistrationGamePath -TemplatePath $templatePath -ExePath $exeToUse -UserProfile $userProfile -DryRun $DryRun -BackupState $BackupState -UserProfilesDir $userProfilesDir -MutationRecords $mutationRecords -PreWriteState ([ref]$preWriteState) -WriteAttempted ([ref]$registrationWriteAttempted)
                Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome VERIFIED
                [void]$registered.Add([pscustomobject]@{
                    Code        = $bestCode
                    GamePath    = $exeToUse
                    DatMatch    = $false
                    FuzzyScore  = [Math]::Round($bestScore, 2)
                    FuzzyFolder = $origName
                })
                Write-Log ("Registered (code/fuzzy {0}) {1} -> {2}" -f [Math]::Round($bestScore,2), $bestCode, $exeToUse)
            } catch {
                $saveFailure = Resolve-TpmRegistrationSaveFailure -WriteAttempted $registrationWriteAttempted -PreState $preWriteState -Message $_.Exception.Message
                Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome FAILED -WriteAttempted $saveFailure.WriteAttempted -Reason $saveFailure.Reason
                if ($registered.Code -notcontains $bestCode) { [void]$mutationRecords.Failures.Add([pscustomobject]@{ Code=$bestCode; WriteAttempted=$saveFailure.WriteAttempted; Reason='REGISTRATION_NOT_VERIFIED' }) }
                Write-Host "  FAILED to register $bestCode : $_" -ForegroundColor Red
                Write-Log "Register (pass3) FAILED $bestCode -- $_"
            }
        }
    }

    # A folder can contain more than one exe-like file -- e.g. a dedicated
    # launcher (already cleanly matched to its own profile elsewhere in this
    # loop) sitting alongside an unrelated generic/shared stub (which only
    # collided with OTHER profiles' ExecutableName and was reported above as
    # "shared"/ambiguous). $matchedFolders already tracks every folder that
    # got a conclusive match from ANY of its exes; $unmatched below already
    # filters against it, but $ambiguous never did, so a folder whose real
    # game was already correctly registered via one exe could still show up
    # in the "needs manual registration" report because of a second,
    # unrelated exe in the same folder. Drop any ambiguous entry whose
    # folder is in $matchedFolders by now -- the folder is accounted for
    # Pass 4: subFolderMap -- profile codes whose executable lives in a known
    # subfolder of the TeknoParrot root rather than in the staging folder.
    # Example: CrediarDolphin titles whose game files must live at
    # TeknoParrot\CrediarDolphin\User\Wii\. Configured in overrides.json:
    # { "subFolderMap": { "TatsunokoCap": "CrediarDolphin\\User\\Wii" } }
    if (($null -eq $GameFolders -or $GameFolders.Count -eq 0) -and
        $subFolderMap -and $subFolderMap.Count -gt 0 -and $gameProfilesDir -and
        $tpRootDir -and (Test-Path -LiteralPath $tpRootDir)) {
        foreach ($sfCode in @($subFolderMap.Keys)) {
            if (Test-TpmRegistrationLedgerStopped) { break }
            $sfCode = [string]$sfCode
            if ($sfCode -notmatch '^[\w-]+$') {
                Write-Log "Register-Games: subFolderMap key '$sfCode' contains invalid characters -- skipped."
                continue
            }
            if ($preExistingCodes.Contains($sfCode) -or $seenCodes.ContainsKey($sfCode)) { continue }
            $sfSubPath = [string]$subFolderMap[$sfCode]
            $sfScanDir = Join-Path $tpRootDir $sfSubPath
            if (-not (Test-Path -LiteralPath $sfScanDir)) { continue }
            $sfTplPath = Join-Path $gameProfilesDir "$sfCode.xml"
            if (-not (Test-Path -LiteralPath $sfTplPath)) { continue }
            $sfExeName = Get-PrimaryExecutableName $sfTplPath
            if (-not $sfExeName) { continue }
            $sfExePath = Join-Path $sfScanDir $sfExeName
            if (-not (Test-Path -LiteralPath $sfExePath -PathType Leaf)) { continue }
            $sfUserProfile = Join-Path $userProfilesDir "$sfCode.xml"
            if (Test-Path -LiteralPath $sfUserProfile) {
                [void]$already.Add($sfCode)
                $seenCodes[$sfCode] = $true
                Backfill-SecondaryExecutablePath $sfUserProfile $DryRun -RegistrationState $mutationRecords -BackupState $BackupState -UserProfilesDir $userProfilesDir
                continue
            }
            $seenCodes[$sfCode] = $true
            $registrationWriteAttempted = $false; $ledgerMapping = $null; $preWriteState = $null
            try {
                $ledgerMapping = Start-TpmRegistrationMapping -Folder '' -Code $sfCode -Match 'subfolder-map' -IntendedPath $sfExePath -TemplatePath $sfTplPath -DryRun $DryRun
                $sfTpl = Read-Xml $sfTplPath
                $sfGp  = $sfTpl.GameProfile.SelectSingleNode("GamePath")
                if ($null -eq $sfGp) {
                    $sfGp = $sfTpl.CreateElement("GamePath")
                    [void]$sfTpl.GameProfile.PrependChild($sfGp)
                }
                $sfGp.InnerText = $sfExePath
                [void](Set-SecondaryExecutablePath $sfTpl $sfExePath -ProfileCode ([string]$sfCode))
                if (-not $DryRun) { [void](Confirm-TpmRegistrationSafetyBackup -State $BackupState -UserProfilesDir $userProfilesDir) }
                if (-not $DryRun) { $preWriteState = Get-TpmProfileWriteFingerprint -Path $sfUserProfile }
                $registrationWriteAttempted = -not $DryRun
                Save-XmlMaybe $sfTpl $sfUserProfile $DryRun
                if (-not $DryRun) { Assert-TpmRegisteredGamePath -ProfilePath $sfUserProfile -ExpectedGamePath $sfExePath -RegistrationState $mutationRecords }
                Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome VERIFIED
                [void]$registered.Add([pscustomobject]@{ Code = $sfCode; GamePath = $sfExePath; SubFolderMatch = $true })
                Write-Log "Registered (subFolderMap) $sfCode -> $sfExePath"
            } catch {
                $saveFailure = Resolve-TpmRegistrationSaveFailure -WriteAttempted $registrationWriteAttempted -PreState $preWriteState -Message $_.Exception.Message
                Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome FAILED -WriteAttempted $saveFailure.WriteAttempted -Reason $saveFailure.Reason
                if ($registered.Code -notcontains $sfCode) { [void]$mutationRecords.Failures.Add([pscustomobject]@{ Code=$sfCode; WriteAttempted=$saveFailure.WriteAttempted; Reason='REGISTRATION_NOT_VERIFIED' }) }
                Write-Host "  FAILED to register $sfCode (subFolderMap) : $_" -ForegroundColor Red
                Write-Log "Register FAILED $sfCode (subFolderMap) -- $_"
            }
        }
    }

    # regardless of what this particular exe resolved to. See issue #9
    # (Nosferatu Lilinor: NLAM.exe cleanly registers the real profile, but a
    # generic "main" stub in the same folder collides with WMMT3/WMMT3DXP
    # and was being reported as still needing registration).
    $ambiguous = @($ambiguous | Where-Object {
        $rel        = if ($_.Exe.Length -gt $installBase.Length) { $_.Exe.Substring($installBase.Length).TrimStart('\') } else { $_.Exe }
        $folderName = ($rel -split '\\')[0]
        $folderKey  = $folderName -replace '\.(teknoparrot|parrot|game)$', ''
        $claimKey = ([string]$_.ClaimedBy) -replace '\.(teknoparrot|parrot|game)$', ''
        if ($_.Reason -eq 'duplicate') { $claimKey -ine $folderKey } else { -not $matchedFolders.ContainsKey($folderKey) }
    })

    # The second profile the list names for a folder (GameProfile2), after the first one is registered or found.
    if ($datIndex.Count -gt 0 -and $gameProfilesDir -and -not (Test-TpmRegistrationLedgerStopped)) {
        Register-TpmDatSecondProfiles -Registered $registered -Already $already -SeenCodes $seenCodes -ClaimedBy $codeClaimedBy -ExeFiles $exeFiles -InstallBase $installBase -DatIndex $datIndex -GameProfilesDir $gameProfilesDir -ProfileSet $profileSet -UserProfilesDir $userProfilesDir -DryRun $DryRun -MutationRecords $mutationRecords -BackupState $BackupState
    }
    $unmatched = @($allExeFolders.Keys | Where-Object { -not $matchedFolders.ContainsKey($_) } | Sort-Object)
    $evidenceStopped = (-not $DryRun -and (Test-TpmRegistrationLedgerStopped))
    $unattemptedFolders = @()
    if ($evidenceStopped) {
        # Include candidates beyond the interrupted first pass, which never entered
        # allExeFolders, as well as folders still awaiting a later matching pass.
        $unattemptedFolders = @($exeFiles | ForEach-Object {
            $candidateFolder = ($_.FullName.Substring($installBase.Length).TrimStart('\') -split '\\')[0]
            $candidateKey = $candidateFolder -replace '\.(teknoparrot|parrot|game)$', ''
            if (-not $matchedFolders.ContainsKey($candidateKey)) { $candidateFolder }
        } | Sort-Object -Unique)
    }
    return [pscustomobject]@{ Registered = $registered; Already = $already; Ambiguous = $ambiguous; Unmatched = $unmatched; MutationRecords = $mutationRecords; Decisions = $decisions; EvidenceStopped = $evidenceStopped; UnattemptedFolders = $unattemptedFolders }
}

function Invoke-ManualRegistrationChoices {
    param(
        [Parameter(Mandatory)][hashtable]$ManualRegData,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][string]$GameProfilesDir,
        [Parameter(Mandatory)][string]$InstallFolder,
        [Parameter(Mandatory)]$Result,
        [bool]$DryRun = $false
    )
    $legacy = $Result.TechnicalDetails
    $manualLedger = $null
    if (-not $DryRun -and $ManualRegData.Count -gt 0 -and (Test-TpmRegistrationLedgerConfigured)) {
        $manualLedger = Open-TpmRegistrationLedgerOperation -Mode ManualChoice -Units @($ManualRegData.Keys | Sort-Object | ForEach-Object { [pscustomobject]@{ Folder = [string]$_ } }) -InstallRoot $InstallFolder
        if (-not $manualLedger.Opened) {
            Write-Host ('  ' + $manualLedger.Message) -ForegroundColor Red
            Write-Log ('Manual registration refused before any write: ' + $manualLedger.Message)
            return $Result
        }
    }
    foreach ($folderName in @($ManualRegData.Keys | Sort-Object)) {
        $info = $ManualRegData[$folderName]
        $decision = [pscustomobject]@{ Game=$folderName; Code=('manual:' + $folderName); Outcome='SKIPPED'; Reason='USER_LEFT_UNRESOLVED'; WriteAttempted=$false }
        $ledgerMapping = $null; $preWriteState = $null
        try {
            $candidates = @($info.Profiles -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -match '^[\w-]+$' })
            if ($candidates.Count -eq 0) { $decision.Reason='NO_VALID_CANDIDATE'; continue }
            Write-Host ""
            Write-Host ("  Ambiguous registration: {0}" -f $folderName) -ForegroundColor Yellow
            Write-Host ("  Executable: {0}" -f $info.Exe) -ForegroundColor DarkGray
            for ($i = 0; $i -lt $candidates.Count; $i++) { Write-Host ("    {0}) {1}" -f ($i + 1), $candidates[$i]) -ForegroundColor DarkCyan }
            $choice = (Read-HostSafe "  Pick a profile number, or press Enter to leave unresolved").Trim()
            if ([string]::IsNullOrWhiteSpace($choice)) { continue }
            $choiceNumber = 0
            if (-not [int]::TryParse($choice, [ref]$choiceNumber) -or $choiceNumber -lt 1 -or $choiceNumber -gt $candidates.Count) {
                $decision.Reason='INVALID_CHOICE'
                Write-Host "  Invalid choice -- no profile was changed." -ForegroundColor Yellow
                continue
            }
            $code = $candidates[$choiceNumber - 1]
            $decision.Code = $code
            $templatePath = Join-Path $GameProfilesDir ($code + ".xml")
            $userProfilePath = Join-Path $UserProfilesDir ($code + ".xml")
            if (-not (Test-Path -LiteralPath $templatePath -PathType Leaf)) { $decision.Reason='TEMPLATE_MISSING'; continue }
            if (Test-Path -LiteralPath $userProfilePath -PathType Leaf) {
                $decision.Reason='EXISTING_PROFILE_PRESERVED'
                Write-Host ("  UserProfile {0}.xml already exists -- it was not overwritten." -f $code) -ForegroundColor Yellow
                continue
            }
            if (-not $DryRun) {
                # Same lazily created registration safety backup as Register-Games.
                $manualBackupState = Get-TpmTransactionField -Object $legacy -Name 'SafetyBackupState'
                if (-not ($manualBackupState -is [hashtable])) { throw 'A verified profile backup is required before manual registration.' }
                [void](Confirm-TpmRegistrationSafetyBackup -State $manualBackupState -UserProfilesDir $UserProfilesDir)
            }
            $installRoot = [System.IO.Path]::GetFullPath($InstallFolder).TrimEnd('\')
            $exeFullPath = [System.IO.Path]::GetFullPath($info.Exe)
            if (-not $exeFullPath.StartsWith($installRoot + '\', [System.StringComparison]::OrdinalIgnoreCase) -or
                -not (Test-Path -LiteralPath $exeFullPath -PathType Leaf) -or
                -not (Test-BepInExNoReparsePath -Root $installRoot -Path $exeFullPath)) { throw 'The selected executable could not be safely verified inside the game folder.' }
            $template = Read-Xml $templatePath
            $gamePath = $template.GameProfile.SelectSingleNode("GamePath")
            if ($null -eq $gamePath) { $gamePath = $template.CreateElement("GamePath"); [void]$template.GameProfile.PrependChild($gamePath) }
            $gamePath.InnerText = $exeFullPath
            [void](Set-SecondaryExecutablePath $template $exeFullPath -ProfileCode ([string]$code))
            $ledgerMapping = Start-TpmRegistrationMapping -Folder $folderName -Code $code -Match 'manual-choice' -IntendedPath $exeFullPath -TemplatePath $templatePath -DryRun $DryRun
            if (-not $DryRun) { $preWriteState = Get-TpmProfileWriteFingerprint -Path $userProfilePath }
            $decision.WriteAttempted = -not $DryRun
            Save-XmlMaybe $template $userProfilePath $DryRun
            if ($DryRun) { $decision.Outcome='PREVIEW'; $decision.Reason='DRY_RUN'; continue }
            Assert-TpmRegisteredGamePath -ProfilePath $userProfilePath -ExpectedGamePath $exeFullPath -RegistrationState $legacy.MutationRecords
            Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome VERIFIED
            [void]$legacy.Registered.Add([pscustomobject]@{ Code=$code; GamePath=$exeFullPath; ManualChoice=$true })
            $decision.Outcome='REGISTERED'
            $decision.Reason='SAVED_MAPPING_VERIFIED'
            $resolvedFolder = (Join-Path $installRoot $folderName).TrimEnd('\')
            $legacy.Ambiguous = @($legacy.Ambiguous | Where-Object {
                $candidateExe = [string]$_.Exe
                $candidateExe -ine $resolvedFolder -and -not $candidateExe.StartsWith($resolvedFolder + '\', [System.StringComparison]::OrdinalIgnoreCase)
            })
            $resolvedKey = $folderName -replace '\.(teknoparrot|parrot|game)$', ''
            $legacy.Unmatched = @($legacy.Unmatched | Where-Object { $_ -ine $folderName -and $_ -ine $resolvedKey })
            foreach ($priorDecision in @($legacy.Decisions | Where-Object { $_.Game -ieq $folderName })) {
                $priorDecision | Add-Member -NotePropertyName ResolvedByVerifiedMapping -NotePropertyValue $true -Force
            }
            [void]$ManualRegData.Remove($folderName)
            Write-Host ("  Registered {0} -> {1}" -f $code, $exeFullPath) -ForegroundColor Green
        } catch {
            $saveFailure = Resolve-TpmRegistrationSaveFailure -WriteAttempted $decision.WriteAttempted -PreState $preWriteState -Message $_.Exception.Message
            Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome FAILED -WriteAttempted $saveFailure.WriteAttempted -Reason $saveFailure.Reason
            if ($decision.Outcome -ne 'REGISTERED') {
                $decision.Outcome = if ($saveFailure.WriteAttempted) { 'UNKNOWN' } else { 'FAILED' }
                $decision.Reason='REGISTRATION_NOT_VERIFIED'
                [void]$legacy.MutationRecords.Failures.Add([pscustomobject]@{ Code=$decision.Code; WriteAttempted=$saveFailure.WriteAttempted; Reason=$decision.Reason })
                Write-Host '  Registration was not verified; the game remains unresolved. Review the preserved profile and backup before retrying.' -ForegroundColor Red
            }
        } finally {
            [void]$legacy.Decisions.Add($decision)
            Write-Log ('Manual registration result: ' + ($decision | ConvertTo-Json -Compress))
        }
    }
    [void](Close-TpmRegistrationLedgerOperations -Reason 'MANUAL_CHOICE_NOT_COMPLETED')
    return (ConvertTo-TpmRegistrationResult -Legacy $legacy -Backup (Get-TpmRegistrationBackupEvidence -Result $Result) -DryRun $DryRun)
}

function ConvertTo-TpmDisplayPath {
    param([AllowEmptyString()][string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return '<empty>' }
    $safePath = [string]$Path
    $userRoot = [Environment]::GetFolderPath('UserProfile')
    if (-not [string]::IsNullOrWhiteSpace($userRoot)) {
        $userRoot = $userRoot.TrimEnd('\')
        if ($safePath.StartsWith($userRoot + '\', [System.StringComparison]::OrdinalIgnoreCase)) {
            return '<user>' + $safePath.Substring($userRoot.Length)
        }
    }
    if ($safePath -imatch '^([A-Z]:\\Users\\)[^\\]+(\\.*)?$') {
        return $matches[1] + '<user>' + $matches[2]
    }
    return $safePath
}

function Write-LibraryHealthRepairResults {
    param([object[]]$Reports = @())

    $fixed = @($Reports | Where-Object { $_.Status -eq 'fixed' })
    $candidates = @($Reports | Where-Object { $_.Status -eq 'candidate' })
    $stillBroken = @($Reports | Where-Object { $_.Status -ne 'fixed' -and $_.Status -ne 'candidate' })
    foreach ($report in @($fixed + $candidates + $stillBroken)) {
        $before = ConvertTo-TpmDisplayPath $report.PreviousPath
        $newPath = Get-TpmTransactionField -Object $report -Name 'NewPath' -Default $null
        $after = if ($newPath) { ConvertTo-TpmDisplayPath ([string]$newPath) } else { '<not saved>' }
        if ($report.Status -eq 'fixed') {
            Write-Host ("  FIXED: {0}" -f $report.Code) -ForegroundColor Green
            Write-Host ("    GamePath before: {0}" -f $before) -ForegroundColor DarkGray
            Write-Host ("    GamePath after : {0}" -f $after) -ForegroundColor DarkGray
        } elseif ($report.Status -eq 'candidate') {
            Write-Host ("  CANDIDATE: {0}" -f $report.Code) -ForegroundColor Cyan
            Write-Host ("    GamePath before: {0}" -f $before) -ForegroundColor DarkGray
            Write-Host ("    GamePath after : {0}" -f $after) -ForegroundColor DarkGray
        } else {
            $reason = if ($report.Reason) { [string]$report.Reason } else { [string]$report.Status }
            Write-Host ("  STILL BROKEN: {0} ({1})" -f $report.Code, $reason) -ForegroundColor Yellow
            Write-Host ("    GamePath before: {0}" -f $before) -ForegroundColor DarkGray
            Write-Host ("    GamePath after : {0}" -f $after) -ForegroundColor DarkGray
        }
    }
    $total = $fixed.Count + $candidates.Count + $stillBroken.Count
    Write-Host ("  Repair accounting: {0} reviewed = {1} fixed + {2} candidates + {3} still broken." -f $total, $fixed.Count, $candidates.Count, $stillBroken.Count) -ForegroundColor DarkCyan
    return [pscustomobject]@{ Total = $total; Fixed = $fixed.Count; Candidates = $candidates.Count; StillBroken = $stillBroken.Count }
}


# Checks every UserProfile's GamePath and re-points broken ones (empty path or
# missing file). Locates the game's executable by name in the install folder.
# An exe name is only used to auto-fix a path when it belongs to exactly ONE
# profile in the TeknoParrot library AND exactly ONE file is found on disk.
# If the exe name is shared by multiple profiles (e.g. sdaemon.exe, game.exe)
# it is always flagged as ambiguous -- even if only one file exists on disk --
# because there is no safe way to know which game the file belongs to.
# Profiles with a valid, working path are left untouched.
function Repair-GamePaths {
    param([string]$userProfilesDir,[string]$installFolder,[hashtable]$profileIndex,[bool]$DryRun=$false,[object[]]$ReviewedCandidates=@(),[string[]]$OnlyGames=@())
    $attachReports = {
        param([object]$Transaction,[object[]]$Reports)
        $stillBroken=@($Reports | Where-Object { $_.Status -ne 'fixed' -and $_.Status -ne 'candidate' })
        $Transaction | Add-Member -NotePropertyName Reports -NotePropertyValue $Reports -Force
        $Transaction | Add-Member -NotePropertyName Total -NotePropertyValue @($Reports).Count -Force
        $Transaction | Add-Member -NotePropertyName Fixed -NotePropertyValue @($Reports | Where-Object Status -eq 'fixed').Count -Force
        $Transaction | Add-Member -NotePropertyName Candidates -NotePropertyValue @($Reports | Where-Object Status -eq 'candidate').Count -Force
        $Transaction | Add-Member -NotePropertyName StillBroken -NotePropertyValue $stillBroken.Count -Force
        $Transaction.Succeeded = ($Transaction.Outcome -eq 'SUCCEEDED')
        return $Transaction
    }
    if ($DryRun) {
        $legacyReports=Repair-GamePathsLegacy -userProfilesDir $userProfilesDir -installFolder $installFolder -profileIndex $profileIndex -DryRun:$true -ReviewedCandidates $ReviewedCandidates -OnlyGames $OnlyGames
        $reports=@($legacyReports)
        $items=@($reports | ForEach-Object Code)
        $skipped=@($reports | Where-Object { $_.Status -in @('candidate','ambiguous','not-reviewed') } | ForEach-Object Code)
        $failed=@($reports | Where-Object { $_.Status -notin @('fixed','candidate','ambiguous','not-reviewed') } | ForEach-Object Code)
        $tx=New-TpmProfileTransactionResult -WorkflowKey 'LibraryHealth' -OperationKey 'AutoRepairPaths' -Outcome 'NO_OP' -ProductState 'UNCHANGED' -Summary 'Library Health repair planning made no profile changes.' -Items $items -FailedItems $failed -SkippedItems $skipped -ReasonCode 'REPAIR_PLAN_ONLY' -FinalChecks @('The repair plan was read without writing profile or backup data.')
        return (& $attachReports $tx $reports)
    }
    $legacyPlan=Repair-GamePathsLegacy -userProfilesDir $userProfilesDir -installFolder $installFolder -profileIndex $profileIndex -DryRun:$true -ReviewedCandidates $ReviewedCandidates -OnlyGames $OnlyGames
    $plan=@($legacyPlan)
    if ($plan.Count -eq 0) {
        $tx=New-TpmProfileTransactionResult -WorkflowKey 'LibraryHealth' -OperationKey 'AutoRepairPaths' -Outcome 'NO_OP' -ProductState 'UNCHANGED' -Summary 'All selected profile paths are already valid.' -ReasonCode 'NO_CHANGES_NEEDED' -FinalChecks @('A read-only candidate scan found no profile requiring a path repair.')
        $reports=@()
        return (& $attachReports $tx $reports)
    }
    $planCandidates=@($plan | Where-Object Status -eq 'candidate')
    if ($planCandidates.Count -eq 0) {
        $items=@($plan | ForEach-Object Code)
        $skipped=@($plan | Where-Object { $_.Status -in @('candidate','ambiguous','not-reviewed') } | ForEach-Object Code)
        $failed=@($plan | Where-Object { $_.Status -notin @('candidate','ambiguous','not-reviewed') } | ForEach-Object Code)
        $tx=New-TpmProfileTransactionResult -WorkflowKey 'LibraryHealth' -OperationKey 'AutoRepairPaths' -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' -Summary 'Library Health repair found no safe reviewed path candidate; no profile was changed.' -Items $items -FailedItems $failed -SkippedItems $skipped -ReasonCode 'NO_REPAIR_CANDIDATE' -FinalChecks @('Every affected profile was left unchanged because no safe candidate was available.')
        return (& $attachReports $tx $plan)
    }
    $backup=New-TpmVerifiedUserProfilesBackup -UserProfilesDir $userProfilesDir -Label 'LibraryHealthAuto'
    if (-not $backup.Verified) {
        $items=@($plan | ForEach-Object Code)
        $tx=New-TpmProfileTransactionResult -WorkflowKey 'LibraryHealth' -OperationKey 'AutoRepairPaths' -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' -Summary 'Library Health repair stopped before changing profiles because its safety backup could not be verified.' -Items $items -FailedItems @($planCandidates | ForEach-Object Code) -Backup $backup -ReasonCode 'PROFILE_BACKUP_FAILED' -FinalChecks @('No automatic path repair was attempted.')
        return (& $attachReports $tx $plan)
    }
    $legacy=Repair-GamePathsLegacy -userProfilesDir $userProfilesDir -installFolder $installFolder -profileIndex $profileIndex -DryRun:$false -ReviewedCandidates $ReviewedCandidates -OnlyGames $OnlyGames
    $reports=@($legacy)
    $items=@($reports | ForEach-Object Code)
    $changed=@($reports | Where-Object Status -eq 'fixed' | ForEach-Object Code)
    $unknown=@($reports | Where-Object { $_.Status -in @('save-failed','still-broken') } | ForEach-Object Code)
    $skipped=@($reports | Where-Object { $_.Status -in @('candidate','ambiguous','not-reviewed') } | ForEach-Object Code)
    $failed=@($reports | Where-Object { $_.Status -notin @('fixed','save-failed','still-broken','candidate','ambiguous','not-reviewed') } | ForEach-Object Code)
    if ($unknown.Count -gt 0) {
        $outcome='ACTION_REQUIRED'
        $productState='UNKNOWN'
        $reasonCode='PROFILE_STATE_UNVERIFIED'
        $summary='Library Health repair needs attention because one or more profile writes could not be verified.'
        $finalPassed=$false
    } elseif ($changed.Count -gt 0 -and ($failed.Count -gt 0 -or $skipped.Count -gt 0)) {
        $outcome='PARTIAL_APPLIED'
        $productState='PARTIAL_KNOWN'
        $reasonCode='PARTIAL_PATH_REPAIR'
        $summary='Library Health repair fixed some profiles but left other reports unresolved.'
        $finalPassed=$true
    } elseif ($changed.Count -gt 0 -and $changed.Count -eq $reports.Count -and $failed.Count -eq 0 -and $skipped.Count -eq 0 -and $unknown.Count -eq 0) {
        $outcome='SUCCEEDED'
        $productState='INTENDED'
        $reasonCode='PATHS_REPAIRED'
        $summary='Library Health repaired and verified every reported profile path.'
        $finalPassed=$true
    } else {
        $outcome='FAILED_BEFORE_MUTATION'
        $productState='UNCHANGED'
        $reasonCode=if($reports.Count -eq 0){'PROFILE_STATE_CHANGED_DURING_PLANNING'}else{'NO_PROFILE_PATH_REPAIRED'}
        $summary='Library Health repair did not verify a profile path change.'
        $finalPassed=$true
    }
    $tx=New-TpmProfileTransactionResult -WorkflowKey 'LibraryHealth' -OperationKey 'AutoRepairPaths' -Outcome $outcome -ProductState $productState -Summary $summary -Items $items -ChangedItems $changed -CompletedItems $changed -FailedItems $failed -SkippedItems $skipped -UnknownItems $unknown -MutationStarted ($changed.Count -gt 0 -or $unknown.Count -gt 0) -MutationCompleted ($outcome -eq 'SUCCEEDED') -Backup $backup -FinalPassed $finalPassed -FinalFailedItems $unknown -ReasonCode $reasonCode -FinalChecks @('Every reported profile status was classified; fixed paths were re-read and validated.')
    return (& $attachReports $tx $reports)
}
function Repair-GamePathsLegacy {
    param([string]$userProfilesDir, [string]$installFolder, [hashtable]$profileIndex, [bool]$DryRun = $false, [object[]]$ReviewedCandidates = @(), [string[]]$OnlyGames = @())

    # Map filename (lowercased) -> list of full paths found on disk.
    # Uses Get-GameFiles so .xbe, .dll, ELF, disc images, and extension-less
    # binaries are all included alongside Windows EXE files.
    $exeMap = @{}
    $repairStarted = Get-Date
    $scanProgress = {
        param($file, $current)
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'Game-file discovery' -Current $current -Total 0 -StartedAt $repairStarted
    }
    foreach ($file in (Get-GameFiles $installFolder -ProgressScript $scanProgress -ExtraExtensions (Get-TpmProfileFileExtensions -ProfileIndex $profileIndex))) {
        $k = $file.Name.ToLowerInvariant()
        if (-not $exeMap.ContainsKey($k)) { $exeMap[$k] = New-Object System.Collections.ArrayList }
        [void]$exeMap[$k].Add($file.FullName)
    }
    Write-TpmCompactExtractionProgress -Phase Scanning -Label 'game files' -Current 0 -Total 0 -StartedAt $repairStarted -Complete

    $reports = New-Object System.Collections.ArrayList
    $files = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $userProfilesDir -ProgressLabel 'Game path repair profile discovery' -EnumerationErrorAction SilentlyContinue)
    if (@($OnlyGames).Count -gt 0) {
        $allowedGames = @($OnlyGames | ForEach-Object { [string]$_ } | Where-Object { $_ } | ForEach-Object { $_.ToLowerInvariant() })
        $files = @($files | Where-Object { $allowedGames -contains $_.BaseName.ToLowerInvariant() })
    }
    $repairIndex = 0
    foreach ($f in $files) {
        $repairIndex++
        Write-TpmCompactExtractionProgress -Phase Repairing -Label 'Game path repair profile scan' -Current $repairIndex -Total $files.Count -StartedAt $repairStarted
        try {
            $doc = Read-Xml $f.FullName
        } catch {
            Write-Log "Repair-GamePaths: could not parse $($f.Name) -- $_"
            [void]$reports.Add([pscustomobject]@{
                Code = $f.BaseName; Status = 'parse-failed'; Outcome = 'STILL BROKEN'
                PreviousPath = '<could not read profile>'; Reason = 'profile could not be read'
            })
            continue
        }
        if ($null -eq $doc.GameProfile) {
            [void]$reports.Add([pscustomobject]@{
                Code = $f.BaseName; Status = 'malformed-profile'; Outcome = 'STILL BROKEN'
                PreviousPath = '<missing GameProfile>'; Reason = 'profile has no GameProfile element'
            })
            continue
        }

        $gpNode  = $doc.GameProfile.SelectSingleNode("GamePath")
        $curPath = if ($gpNode) { $gpNode.InnerText } else { "" }
        $exeName = [string]$doc.GameProfile.ExecutableName

        $driveGone = $false
        if ($curPath) {
            $currentPathCheck = Test-TpmGameMutationPath -GamePath $curPath -RequireLeaf
            if ($currentPathCheck.Valid) { continue }   # path is valid and safe
            # The saved drive is not connected: a game that is not found must not be reported as "extract this game first".
            $driveGone = ([string]$currentPathCheck.ReasonCode -eq 'DEVICE_UNAVAILABLE')
        }

        if ([string]::IsNullOrWhiteSpace($exeName)) {
            [void]$reports.Add([pscustomobject]@{
                Code = $f.BaseName; Status = "no-exe-name"; Outcome = 'STILL BROKEN'
                PreviousPath = $curPath; Reason = 'profile has no executable name'
            })
            continue
        }
        # If this exe name maps to more than one profile in the library it is
        # inherently ambiguous -- never auto-assign it regardless of what is on disk.
        $alts         = @((Get-TpmGameFileSet -ExecutableName $exeName.Trim()).Choices)
        $profileCount = ($alts | ForEach-Object {
            $ak = $_.ToLowerInvariant()
            if ($profileIndex.ContainsKey($ak)) { $profileIndex[$ak].Count } else { 0 }
        } | Measure-Object -Maximum).Maximum
        if (-not $profileCount) { $profileCount = 0 }
        if ($profileCount -gt 1) {
            [void]$reports.Add([pscustomobject]@{
                Code = $f.BaseName; Status = "ambiguous"; Outcome = 'STILL BROKEN'
                Exe = $exeName; PreviousPath = $curPath; Reason = 'executable name maps to multiple profiles'
            })
            continue
        }

        $matchingReviewed = @($ReviewedCandidates | Where-Object { [string]$_.Code -ieq $f.BaseName })
        if ($ReviewedCandidates.Count -gt 0 -and $matchingReviewed.Count -eq 0) {
            [void]$reports.Add([pscustomobject]@{
                Code = $f.BaseName; Status = 'not-reviewed'; Outcome = 'STILL BROKEN'
                Exe = $exeName; PreviousPath = $curPath; Reason = 'candidate was not explicitly reviewed'
            })
            continue
        }
        $reviewed = if ($matchingReviewed.Count -gt 0) { $matchingReviewed[0] } else { $null }
        $key = $null
        $newPath = $null
        if ($reviewed) {
            $newPath = [string]$reviewed.NewPath
        } else {
            # Try each alternative name in the on-disk map.
            foreach ($alt in $alts) {
                $ak = $alt.ToLowerInvariant()
                if ($exeMap.ContainsKey($ak)) { $key = $ak; break }
            }
            if ($null -eq $key) {
                [void]$reports.Add([pscustomobject]@{
                    Code = $f.BaseName; Status = $(if ($driveGone) { 'drive-unavailable' } else { 'not-found' }); Outcome = 'STILL BROKEN'
                    Exe = $exeName; PreviousPath = $curPath; Reason = $(if ($driveGone) { 'the saved drive is not connected and the game was not found in the folder searched' } else { 'matching executable was not found' })
                })
                continue
            }
            if ($exeMap[$key].Count -gt 1) {
                [void]$reports.Add([pscustomobject]@{
                    Code = $f.BaseName; Status = "ambiguous"; Outcome = 'STILL BROKEN'
                    Exe = $exeName; PreviousPath = $curPath; Reason = 'multiple matching executables were found'
                })
                continue
            }
            $newPath = [string]$exeMap[$key][0]
        }
        $repairPathCheck = Test-TpmGameMutationPath -GamePath $newPath -RequireLeaf
        if (-not $repairPathCheck.Valid -or
            -not (Test-PathInside -child $newPath -parent $installFolder) -or
            -not (Test-TpmNoReparsePath -Path $newPath) -or
            [string]$repairPathCheck.ResolvedPath -ine [string]$newPath) {
            $repairReason = if ($repairPathCheck.Reason) { $repairPathCheck.Reason } else { 'candidate is outside the configured games root or uses an unsafe reparse path' }
            [void]$reports.Add([pscustomobject]@{
                Code = $f.BaseName; Status = "path-unsafe"; Outcome = 'STILL BROKEN'
                Exe = $exeName; PreviousPath = $curPath; Reason = $repairReason
            })
            continue
        }
        $newPath = [string]$repairPathCheck.ResolvedPath
        if ($DryRun) {
            [void]$reports.Add([pscustomobject]@{
                Code = $f.BaseName
                Status = 'candidate'
                Outcome = 'CANDIDATE'
                Exe = $exeName
                PreviousPath = $curPath
                CandidatePaths = @($newPath)
                NewPath = $newPath
            })
            Write-Log "Repair-GamePaths: candidate for $($f.BaseName) -> $newPath"
            continue
        }
        try {
            if ($null -eq $gpNode) {
                $gpNode = $doc.CreateElement("GamePath")
                [void]$doc.GameProfile.PrependChild($gpNode)
            }
            $gpNode.InnerText = $newPath
            [void](Set-SecondaryExecutablePath $doc $newPath -ProfileCode ([string]$f.BaseName))
            Save-XmlMaybe $doc $f.FullName $DryRun

            $verifiedDoc = Read-Xml $f.FullName
            $verifiedNode = $verifiedDoc.GameProfile.SelectSingleNode("GamePath")
            $verifiedPath = if ($verifiedNode) { [string]$verifiedNode.InnerText } else { '' }
            $verifiedCheck = if ($verifiedPath) {
                Test-TpmGameMutationPath -GamePath $verifiedPath -RequireLeaf
            } else {
                $null
            }
            if ($verifiedPath -eq $newPath -and $verifiedCheck -and $verifiedCheck.Valid -and
                [string]$verifiedCheck.ResolvedPath -ieq $newPath) {
                [void]$reports.Add([pscustomobject]@{
                    Code = $f.BaseName; Status = "fixed"; Outcome = 'FIXED'
                    Exe = $exeName; PreviousPath = $curPath; NewPath = $newPath; Verified = $true
                })
                Write-Log "Repair: fixed and verified $($f.BaseName) -> $newPath"
            } else {
                $verifyReason = if (-not $verifiedPath) { 'saved profile has an empty GamePath' }
                    elseif ($verifiedPath -ine $newPath) { 'saved profile GamePath did not match the reviewed candidate' }
                    elseif ($verifiedCheck -and $verifiedCheck.Reason) { [string]$verifiedCheck.Reason }
                    else { 'saved GamePath could not be revalidated' }
                [void]$reports.Add([pscustomobject]@{
                    Code = $f.BaseName; Status = "still-broken"; Outcome = 'STILL BROKEN'
                    Exe = $exeName; PreviousPath = $curPath; NewPath = $verifiedPath; Reason = $verifyReason; Verified = $false
                })
                Write-Log "Repair: save verification failed for $($f.BaseName) -- $verifyReason"
            }
        } catch {
            Write-Log "Repair-GamePaths: FAILED to save or verify $($f.Name) -- $_"
            $keptCopy = Get-TpmKeptSaveCopyPath -Text $_.Exception.Message
            $saveFailReason = if ($keptCopy) { 'the old profile was removed while saving; a copy of the new settings was kept at ' + $keptCopy } else { 'profile save or verification failed' }
            [void]$reports.Add([pscustomobject]@{
                Code = $f.BaseName; Status = "save-failed"; Outcome = 'STILL BROKEN'
                Exe = $exeName; PreviousPath = $curPath; NewPath = $newPath; Reason = $saveFailReason; Verified = $false
            })
        }
    }
    Write-TpmCompactExtractionProgress -Phase Repairing -Label 'game paths' -Current $repairIndex -Total $files.Count -StartedAt $repairStarted -Complete
    # Review round 2 (Luna Max): "return $reports" lets the output stream
    # enumerate the ArrayList -- with exactly one report, that unwraps to
    # the single pscustomobject itself rather than a one-element collection.
    # This was masked on pwsh only because PowerShell 6+ added a synthetic
    # .Count/.Length property to every object (scalars included), so
    # $reports.Count still happened to read 1 there; Windows PowerShell 5.1
    # has no such synthetic property, so the exact same unwrap left
    # $reports.Count genuinely absent (Should -Be 1 saw $null). The leading
    # comma prevents the unwrap and returns the real ArrayList -- reliably
    # array-shaped with zero, one, or many reports, on both engines.
    return ,$reports
}

# Save-Xml keeps the new copy and says where when the replace failed after the old file was removed.
function Get-TpmKeptSaveCopyPath {
    param([string]$Text)
    if ($Text -match "was kept at '([^']+)'") { return $Matches[1] }
    return $null
}

# Guided, explicit repair for broken Health Check paths. The user selects each
# executable rather than having TPM infer a folder or executable. No profile is
# saved until the user confirms the complete selection and the backup succeeds.
function Invoke-LibraryHealthManualPathRepair {
    param([Parameter(Mandatory)][string]$UserProfilesDir,[Parameter(Mandatory)][string]$GamesInstallFolder,[Parameter(Mandatory)][string[]]$BrokenGames)
    $legacy=Invoke-LibraryHealthManualPathRepairLegacy -UserProfilesDir $UserProfilesDir -GamesInstallFolder $GamesInstallFolder -BrokenGames $BrokenGames
    $items=@($BrokenGames)
    $changed=@(Get-TpmTransactionField -Object $legacy -Name 'SavedCodes' -Default @())
    $failed=@($legacy.Errors)
    $skipped=@($legacy.Skipped)
    $backup=if($legacy.BackupPath){[pscustomobject]@{Required=$true;Attempted=$true;Created=$true;Verified=$true;RootPath=$legacy.BackupPath;Path=$legacy.BackupPath;Items=$items;ResiduePaths=@()}}else{$null}
    $retained=@(Get-TpmTransactionField -Object $legacy -Name 'RetainedCopies' -Default @())
    $outcome=if($retained.Count -gt 0){'ACTION_REQUIRED'}elseif($changed.Count -gt 0 -and $failed.Count -gt 0){'PARTIAL_APPLIED'}elseif($changed.Count -gt 0){'SUCCEEDED'}elseif($failed.Count -gt 0){'FAILED_BEFORE_MUTATION'}else{'NO_OP'}
    $summary=if($retained.Count -gt 0){'A game profile was removed while it was being saved and could not be put back. A copy of its new settings was kept; press D to see where, or restore the safety backup.'}elseif($outcome -eq 'FAILED_BEFORE_MUTATION'){'Library Health manual path repair did not save any profile. No profile was changed.'}elseif($outcome -eq 'NO_OP'){'Nothing was saved. No profile was changed.'}else{'Library Health manual path repair completed with a verified transaction result.'}
    $tx=ConvertTo-TpmLegacyTransactionResult -Legacy $legacy -WorkflowKey 'LibraryHealth' -OperationKey 'ManualRepairPaths' -Items $items -ChangedItems $changed -CompletedItems $changed -FailedItems $failed -SkippedItems $skipped -Summary $summary -ReasonCode $(if($retained.Count -gt 0){'PROFILE_FILE_REMOVED'}elseif($outcome -eq 'NO_OP'){'NO_CHANGES_NEEDED'}elseif($outcome -eq 'FAILED_BEFORE_MUTATION'){'MANUAL_REPAIR_FAILED'}else{'PATHS_PROCESSED'}) -Backup $backup -Outcome $outcome -ProductState $(if($retained.Count -gt 0){'UNKNOWN'}elseif($outcome -eq 'SUCCEEDED'){'INTENDED'}elseif($outcome -eq 'PARTIAL_APPLIED'){'PARTIAL_KNOWN'}else{'UNCHANGED'}) -MutationStarted ($changed.Count -gt 0 -or $retained.Count -gt 0) -FinalPassed ($retained.Count -eq 0)
    return $tx
}
function Invoke-LibraryHealthManualPathRepairLegacy {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][string]$GamesInstallFolder,
        [Parameter(Mandatory)][string[]]$BrokenGames
    )

    $plans = New-Object System.Collections.Generic.List[object]
    $skipped = New-Object System.Collections.Generic.List[string]
    $errors = New-Object System.Collections.Generic.List[string]
    foreach ($code in @($BrokenGames)) {
        $profilePath = Join-Path $UserProfilesDir ($code + '.xml')
        try {
            $fingerprint = Get-TpmProfileWriteFingerprint -Path $profilePath
            $doc = Read-Xml -Path $profilePath
            if (-not $doc.GameProfile) { throw 'profile has no GameProfile node' }
            $exeNode = $doc.GameProfile.SelectSingleNode('ExecutableName')
            $exeName = if ($exeNode) { $exeNode.InnerText.Trim() } else { '' }
            $exeAlternatives = @((Get-TpmGameFileSet -ExecutableName $exeName).Choices)
            $expectedDisplay = ($exeAlternatives -join ' or ')

            Write-Host ""
            Write-Host $(if ($exeName) { ("  Select the correct executable for {0} (expected: {1})." -f $code, $expectedDisplay) } else { ("  Select the correct executable for {0}. No executable name is recorded, so the file you pick inside your games folder is used." -f $code) }) -ForegroundColor Cyan
            Write-Host "  Browse to the file inside the correct game folder. TeknoParrot Manager will not guess." -ForegroundColor DarkGray
            $selected = Read-PathWithBrowse -Prompt ("  Executable for {0}; press Enter to leave unchanged" -f $code) `
                -Mode File -FileFilter 'All files (*.*)|*.*' -InitialDirectory $GamesInstallFolder
            if ([string]::IsNullOrWhiteSpace($selected)) {
                [void]$skipped.Add($code)
                continue
            }
            # The leaf check (long-path aware, same as Repair-GamePaths) happens in Test-TpmGameMutationPath below.
            if (-not [string]::IsNullOrWhiteSpace($exeName) -and (@($exeAlternatives | Where-Object { $_ -ieq [System.IO.Path]::GetFileName($selected) })).Count -eq 0) {
                Write-Host ("  {0}: selected file is not one of '{1}'; left unchanged." -f $code, $expectedDisplay) -ForegroundColor Yellow
                [void]$errors.Add($code)
                continue
            }
            $pathCheck = Test-TpmGameMutationPath -GamePath $selected -RequireLeaf
            if (-not $pathCheck.Valid -or
                -not (Test-PathInside -child $pathCheck.ResolvedPath -parent $GamesInstallFolder) -or
                -not (Test-TpmNoReparsePath -Path $pathCheck.ResolvedPath)) {
                $reason = if ($pathCheck.Reason) { $pathCheck.Reason } else { 'the selected path is outside the configured games root or uses an unsafe reparse path' }
                Write-Host ("  {0}: TeknoParrot Manager rejected this path ({1}); left unchanged." -f $code, $reason) -ForegroundColor Yellow
                [void]$errors.Add($code)
                continue
            }
            [void]$plans.Add([pscustomobject]@{
                Code = $code
                ProfilePath = $profilePath
                Document = $doc
                Fingerprint = $fingerprint
                GamePathNode = $doc.GameProfile.SelectSingleNode('GamePath')
                SelectedPath = $pathCheck.ResolvedPath
            })
        } catch {
            Write-Host ("  {0}: could not prepare a manual repair; left unchanged." -f $code) -ForegroundColor Yellow
            Write-Log "HealthCheck manual repair: could not prepare $code -- $_"
            [void]$errors.Add($code)
        }
    }

    if ($plans.Count -eq 0) {
        return [pscustomobject]@{ Updated = 0; Skipped = @($skipped); Errors = @($errors); BackupPath = $null }
    }
    Write-Host ""
    Write-Host "TeknoParrot Manager will save only the explicitly selected paths after making a safety backup." -ForegroundColor Yellow
    $confirm = Read-TpmYesNo -Prompt '  Save these path repairs? (Y/N)' -Default 'N'
    if ($confirm -ne 'Y') {
        foreach ($plan in $plans) { [void]$skipped.Add($plan.Code) }
        Write-Host "  Manual path repair canceled. Nothing was changed." -ForegroundColor DarkGray
        return [pscustomobject]@{ Updated = 0; Skipped = @($skipped); Errors = @($errors); BackupPath = $null }
    }

    $backup = $null
    try {
        $backup = New-TpmVerifiedUserProfilesBackup -UserProfilesDir $UserProfilesDir -Label 'HealthCheck'
        if (-not $backup.Verified) { throw ('The safety backup of your game settings could not be checked: {0}' -f [string]$backup.Reason) }
    } catch {
        Write-Host ("  {0}" -f $_.Exception.Message) -ForegroundColor Red
        Write-Host "  No manual path repairs were saved." -ForegroundColor Red
        return [pscustomobject]@{ Updated = 0; Skipped = @($skipped); Errors = @($errors) + @($plans | ForEach-Object { $_.Code }); BackupPath = $null }
    }

    $savedCodes = New-Object System.Collections.Generic.List[string]
    $retained = New-Object System.Collections.Generic.List[string]
    foreach ($plan in $plans) {
        try {
            $profileNow = Get-TpmProfileWriteFingerprint -Path $plan.ProfilePath
            if (-not $plan.Fingerprint.Known -or -not $profileNow.Known -or [bool]$profileNow.Exists -ne [bool]$plan.Fingerprint.Exists -or [string]$profileNow.Sha256 -ne [string]$plan.Fingerprint.Sha256) {
                Write-Host ("  {0}: this profile was changed by something else after it was read (TeknoParrot may have saved it); left unchanged. Run the path repair again." -f $plan.Code) -ForegroundColor Yellow
                [void]$errors.Add($plan.Code)
                continue
            }
            $savePathCheck = Test-TpmGameMutationPath -GamePath $plan.SelectedPath -RequireLeaf
            if (-not $savePathCheck.Valid -or
                -not (Test-PathInside -child $plan.SelectedPath -parent $GamesInstallFolder) -or
                -not (Test-TpmNoReparsePath -Path $plan.SelectedPath) -or
                [string]$savePathCheck.ResolvedPath -ine [string]$plan.SelectedPath) {
                $saveReason = if ($savePathCheck.Reason) { $savePathCheck.Reason } else { 'the selected path became unavailable or unsafe before saving' }
                Write-Host ("  {0}: path changed before save ({1}); left unchanged." -f $plan.Code, $saveReason) -ForegroundColor Yellow
                [void]$errors.Add($plan.Code)
                continue
            }
            $plan.SelectedPath = [string]$savePathCheck.ResolvedPath
            if ($null -eq $plan.GamePathNode) {
                $plan.GamePathNode = $plan.Document.CreateElement('GamePath')
                [void]$plan.Document.GameProfile.AppendChild($plan.GamePathNode)
            }
            $plan.GamePathNode.InnerText = $plan.SelectedPath
            [void](Set-SecondaryExecutablePath $plan.Document $plan.SelectedPath -ProfileCode ([string]$plan.Code))
            Save-Xml -doc $plan.Document -path $plan.ProfilePath
            [void]$savedCodes.Add([string]$plan.Code)
        } catch {
            $keptCopy = Get-TpmKeptSaveCopyPath -Text $_.Exception.Message
            if ($keptCopy) {
                [void]$retained.Add($keptCopy)
                Write-Host ("  {0}: the old profile was removed while saving and could not be put back. A copy of the new settings was kept." -f $plan.Code) -ForegroundColor Red
            } else {
                Write-Host ("  {0}: save failed; review backup {1}." -f $plan.Code, $backup.Path) -ForegroundColor Red
            }
            Write-Log "HealthCheck manual repair: save failed for $($plan.Code) -- $_"
            [void]$errors.Add($plan.Code)
        }
    }
    return [pscustomobject]@{
        Updated = $savedCodes.Count
        SavedCodes = @($savedCodes)
        Skipped = @($skipped)
        Errors = @($errors)
        RetainedCopies = @($retained)
        BackupPath = $backup.Path
    }
}

# Read-only library status: classifies every UserProfile's GamePath as
# valid / broken / empty, but reports only -- it never writes profile or game
# state and never starts a setup/download workflow. Saved paths may be on a
# configured local or NAS drive, so their existence checks can access that
# configured path. Safe to run any time as a fast health check.
function Invoke-LibraryHealthCheck {
    param([string]$UserProfilesDir, [string]$LogPath, [string]$TpRoot)

    $discoveryFailed = $false
    $profileDiscoveryError = $null
    try {
        $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'Library Health profile discovery' -EnumerationErrorAction Stop | Sort-Object BaseName)
    } catch {
        $discoveryFailed = $true
        $profileDiscoveryError = [string]$_.Exception.Message
        $profiles = @()
        Write-Log "HealthCheck: profile discovery failed -- $_"
    }
    $postgresInventoryStatus = if ($discoveryFailed) { 'Error' } else { 'Complete' }
    $postgresInventoryErrors = New-Object System.Collections.Generic.List[string]
    if ($profileDiscoveryError) { [void]$postgresInventoryErrors.Add($profileDiscoveryError) }

    $valid = New-Object System.Collections.ArrayList
    $broken = New-Object System.Collections.ArrayList
    $driveUnavailable = New-Object System.Collections.ArrayList
    $empty = New-Object System.Collections.ArrayList
    $unreadable = New-Object System.Collections.ArrayList
    $postgresNeeded = New-Object System.Collections.ArrayList
    $postgresConfigured = 0
    $postgresNeededLabels = New-Object System.Collections.Generic.List[string]
    $postgresConfiguredLabels = New-Object System.Collections.Generic.List[string]
    $postgresAutoCreateLabels = New-Object System.Collections.Generic.List[string]
    $internalDatabaseLabels = New-Object System.Collections.Generic.List[string]
    $postgresConfiguredChecks = New-Object System.Collections.Generic.List[object]
    $postgresDbUsers = New-Object System.Collections.Generic.List[object]

    $profileCurrent = 0
    $profileStarted = Get-Date
    foreach ($pf in $profiles) {
        $profileCurrent++
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Library Health profile scan' -Current $profileCurrent -Total $profiles.Count -StartedAt $profileStarted
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) {
                [void]$unreadable.Add($pf.BaseName)
                if ($postgresInventoryStatus -eq 'Complete') { $postgresInventoryStatus = 'Unknown' }
                [void]$postgresInventoryErrors.Add(('Profile {0} has no GameProfile document element.' -f $pf.BaseName))
                continue
            }
            try {
                if ((Get-TpmGameDatabaseStorage -Doc $doc) -eq 'Internal') { [void]$internalDatabaseLabels.Add((Get-TpmGameDisplayLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName)) }
                if (Test-GameNeedsPostgres $doc) {
                    $label = Get-TpmGameDisplayLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName
                    [void]$postgresDbUsers.Add([pscustomobject]@{ Label = $label; DbName = [string](Get-PostgresFieldValue $doc 'DbName'); Key = ('{0}|{1}|{2}' -f ([string](Get-PostgresFieldValue $doc 'Address')).Trim(), ([string](Get-PostgresFieldValue $doc 'Port')).Trim(), [string](Get-PostgresFieldValue $doc 'DbName')) })
                    $configurationComplete = Test-TpmPostgresSettingsComplete -Doc $doc
                    if (-not $configurationComplete) {
                        [void]$postgresNeeded.Add($pf.BaseName)
                        [void]$postgresNeededLabels.Add($label)
                    } else {
                        $postgresConfigured++
                        [void]$postgresConfiguredLabels.Add($label)
                        [void]$postgresConfiguredChecks.Add([pscustomobject]@{ Label = $label; Doc = $doc })
                        # Only an explicit upstream 1 counts as "TeknoParrot creates the database"; a missing or odd field stays unknown.
                        if ((Get-PostgresAutoCreateCapability -Doc $doc) -eq $true) {
                            # FIX69 / N18B: setup creates the database itself when the game ships a backup (the newest one); only the other games are left to TeknoParrot.
                            $healthGamePathNode = $doc.GameProfile.SelectSingleNode('GamePath')
                            $healthGamePath = if ($healthGamePathNode) { ([string]$healthGamePathNode.InnerText).Trim() } else { '' }
                            if (-not (Get-PostgresBackupSelection -GamePath $healthGamePath).Newest) { [void]$postgresAutoCreateLabels.Add($label) }
                        }
                    }
                }
            } catch {
                if ($postgresInventoryStatus -eq 'Complete') { $postgresInventoryStatus = 'Unknown' }
                [void]$postgresInventoryErrors.Add(('Profile {0} PostgreSQL fields could not be classified: {1}' -f $pf.BaseName, $_.Exception.Message))
                Write-Log "HealthCheck: PostgreSQL profile classification failed for $($pf.Name) -- $_"
            }
            $gpNode = $doc.GameProfile.SelectSingleNode('GamePath')
            $curPath = if ($gpNode) { $gpNode.InnerText.Trim() } else { '' }
            if ([string]::IsNullOrWhiteSpace($curPath)) {
                [void]$empty.Add($pf.BaseName)
            } else {
                $pathCheck = Test-TpmGameMutationPath -GamePath $curPath -RequireLeaf
                if ($pathCheck.Valid) { [void]$valid.Add($pf.BaseName) }
                elseif ([string]$pathCheck.ReasonCode -eq 'DEVICE_UNAVAILABLE') { [void]$driveUnavailable.Add($pf.BaseName) }
                else { [void]$broken.Add($pf.BaseName) }
            }
        } catch {
            [void]$unreadable.Add($pf.BaseName)
            if ($postgresInventoryStatus -eq 'Complete') { $postgresInventoryStatus = 'Unknown' }
            [void]$postgresInventoryErrors.Add(('Profile {0} could not be classified: {1}' -f $pf.BaseName, $_.Exception.Message))
            Write-Log "HealthCheck: could not parse $($pf.Name) -- $_"
        }
    }

    Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Library Health profile scan' -Current $profiles.Count -Total $profiles.Count -StartedAt $profileStarted -Complete

    # -- Optional-setup coverage: GPU fix + FFB Blaster -------------------------
    # Read-only -- mirrors Invoke-GpuFixSetup and Invoke-FFBBlasterSetup's
    # detection via shared helpers, but never writes anything. Third-party FFB
    # plugin coverage is deliberately NOT checked here because it requires a
    # live fetch of the AutoSetup.cmd table; the optional setup workflow can
    # check it later when the user chooses Force Feedback.
    $gpuFixNeeded     = New-Object System.Collections.ArrayList
    $ffbBlasterNeeded = New-Object System.Collections.ArrayList
    $dgVoodoo2Needed  = New-Object System.Collections.ArrayList
    $reShadeCount     = 0
    $bepInExCount     = 0
    $bepInExNeeded    = New-Object System.Collections.ArrayList
    $detected         = Get-DetectedGpuVendor
    $optionalCoverageError = ''
    try {
        $combinedFields = Get-GpuAndFfbFieldNames -TpRoot $TpRoot
        $gpuFields = $combinedFields.Gpu
        $ffbFields = $combinedFields.Ffb
    } catch {
        # Fail closed for this read-only check: report coverage as unavailable, never as clean.
        $optionalCoverageError = [string]$_.Exception.Message
        Write-Log ("HealthCheck: optional GPU/FFB coverage could not be read -- {0}" -f $optionalCoverageError)
        $gpuFields = $null
        $ffbFields = $null
    }

    $coverageStarted = Get-Date
    $coverageCurrent = 0
    $optionalCheckFailed = 0
    $optionalCoverageUnavailable = ($null -eq $gpuFields -or $null -eq $ffbFields)
    foreach ($pf in $profiles) {
        if ($null -eq $gpuFields -or $null -eq $ffbFields) { break }
        $coverageCurrent++
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Library Health optional coverage scan' -Current $coverageCurrent -Total $profiles.Count -StartedAt $coverageStarted
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) { continue }
            if ($detected.Vendor) {
                $gpuResult = Test-GpuFixUpToDate -Doc $doc -BoolFields $gpuFields.BoolFields -DropdownFields $gpuFields.DropdownFields -Vendor $detected.Vendor
                if ($gpuResult.Eligible -and -not $gpuResult.UpToDate) { [void]$gpuFixNeeded.Add($pf.BaseName) }
            }
            # Use the same structured gate the setup flow uses (issue #41) so
            # the health check agrees exactly with what Invoke-FFBBlasterSetup
            # would actually do: only a 'Supported' profile that still needs a
            # write is reported as needing the fix. An unsupported platform
            # (e.g. pcsx2x6) or an unrecognized/drifted field is never flagged
            # here as "not applied" -- it cannot and should not be applied.
            $ffbSupport = Get-FFBBlasterSupport -Doc $doc -Categories $ffbFields
            if ($ffbSupport.Status -eq 'Supported' -and $ffbSupport.WouldWrite) { [void]$ffbBlasterNeeded.Add($pf.BaseName) }


            # dgVoodoo2 / ReShade / BepInEx all need a resolved, existing exe
            # path -- skip silently for broken/empty profiles (already
            # reported above).
            $gpNode   = $doc.GameProfile.SelectSingleNode("GamePath")
            $gamePath = if ($gpNode) { $gpNode.InnerText.Trim() } else { "" }
            if ([string]::IsNullOrWhiteSpace($gamePath) -or -not [System.IO.File]::Exists((ConvertTo-TpmAutoSyncLongPath -Path $gamePath))) { continue }
            $exeDir = [System.IO.Path]::GetDirectoryName($gamePath)
            if ([string]::IsNullOrWhiteSpace($exeDir)) { continue }

            $apis = @(Get-GameLegacyApi -ExePath $gamePath)
            $dgResult = Test-DgVoodoo2UpToDate -Apis $apis -ExeDir $exeDir
            if ($dgResult.Eligible -and -not $dgResult.UpToDate) { [void]$dgVoodoo2Needed.Add($pf.BaseName) }

            $rsInfo = Get-ReShadeTargetInfo -Doc $doc -GamePath $gamePath -ExeDir $exeDir
            if ([System.IO.File]::Exists((ConvertTo-TpmAutoSyncLongPath -Path (Join-Path $rsInfo.TargetDir $rsInfo.DllName)))) { $reShadeCount++ }

            if (Get-BepInExInstalledVersion -ExeDir $exeDir) { $bepInExCount++ }
            else {
                # A game whose profile says it needs BepInEx and has none: listed by its plain game name.
                $bepNeedNode = $doc.GameProfile.SelectSingleNode('RequiresBepInEx')
                if ($bepNeedNode -and $bepNeedNode.InnerText.Trim() -ieq 'true') { [void]$bepInExNeeded.Add((Get-TpmGameDisplayLabel -ProfilePath $pf.FullName -Fallback $pf.BaseName)) }
            }
        } catch {
            $optionalCheckFailed++
        Write-Log "HealthCheck: coverage check could not parse $($pf.Name) -- $_"
        }
    }
    Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Library Health optional coverage scan' -Current $coverageCurrent -Total $profiles.Count -StartedAt $coverageStarted -Complete
    # FIX132: game startup files (firmware) that the games' emulators need. Read-only, like the rest of this check.
    $prerequisiteMissing = @()
    $prerequisiteCheckFailed = $false
    $prerequisiteNotChecked = New-Object System.Collections.ArrayList
    if (-not $discoveryFailed -and -not [string]::IsNullOrWhiteSpace($TpRoot)) {
        try {
            $prerequisiteMissing = @(Get-TpmMissingPrerequisites -Profiles $profiles -TeknoParrotRoot $TpRoot -NotChecked $prerequisiteNotChecked)
        } catch {
            $prerequisiteCheckFailed = $true
            Write-Log ("HealthCheck: the game startup files could not be checked -- {0}" -f $_)
        }
    }
    # Game types: unknown types, development-only games, a missing emulator folder, games that need a hand-picked file, System 11 saved files.
    $gameTypeReport = $null
    if (-not $discoveryFailed) {
        try { $gameTypeReport = Get-TpmGameTypeReport -Profiles $profiles -TeknoParrotRoot $TpRoot }
        catch { Write-Log ("HealthCheck: the game types could not be checked -- {0}" -f $_) }
    }
    # Controls: which games have every control the game lists set up. Read-only; it never says a game is ready.
    $controlsAudit = $null
    if (-not $discoveryFailed -and -not [string]::IsNullOrWhiteSpace($TpRoot) -and (Test-Path -LiteralPath (Join-Path $TpRoot 'GameProfiles') -PathType Container)) {
        try { $controlsAudit = Get-TpmControlCoverageAudit -Profiles $profiles -GameProfilesDir (Join-Path $TpRoot 'GameProfiles') }
        catch { Write-Log ("HealthCheck: the controls could not be checked -- {0}" -f $_) }
    }
    $postgresStatus = 'Unknown'; $postgresPsqlExists = $false; $postgresPsqlStatus = 'Unknown'; $postgresServiceExists = $null
    try {
        $postgresService = Get-Service -Name $script:PostgresServiceName -ErrorAction Stop
        $postgresServiceExists = $true
        $postgresStatus = [string]$postgresService.Status
    } catch {
        if ([string]$_.FullyQualifiedErrorId -like 'NoServiceFoundForGivenName,*') {
            $postgresServiceExists = $false
            $postgresStatus = 'NotInstalled'
        } else {
            Write-Log "Health Check: PostgreSQL service existence/status could not be verified -- $_"
        }
    }
    if ($postgresServiceExists -eq $true) {
        try {
            $postgresPsqlExists = Test-Path -LiteralPath (Join-Path $script:PostgresBinDir 'psql.exe') -ErrorAction Stop
            $postgresPsqlStatus = if ($postgresPsqlExists) { 'Found' } else { 'NotFound' }
        } catch {
            Write-Log "Health Check: PostgreSQL client executable could not be verified -- $_"
        }
    }
    # FIXDB27: read-only database check. A game's database is a PROBLEM when it is missing, cannot be opened with the game's own
    # profile settings, or has no tables. Same check as PostgreSQL setup (menu 11). Skipped, with the reason, when PostgreSQL is not there.
    $postgresDatabaseCheck = 'NotNeeded'
    $postgresDatabaseProblems = New-Object System.Collections.Generic.List[string]
    $postgresDatabaseSkipped = New-Object System.Collections.Generic.List[string]
    $postgresAwaitingFirstStart = New-Object System.Collections.Generic.List[string]
    if ($postgresConfiguredChecks.Count -gt 0) {
        if ($postgresServiceExists -eq $false) { $postgresDatabaseCheck = 'SkippedNotInstalled' }
        elseif ($postgresStatus -ne 'Running') { $postgresDatabaseCheck = 'SkippedNotRunning' }
        elseif ($postgresPsqlStatus -ne 'Found') { $postgresDatabaseCheck = 'SkippedNoClient' }
        else {
            $postgresDatabaseCheck = 'Done'
            $checkedDatabases = @{}
            foreach ($databaseCheck in $postgresConfiguredChecks) {
                # A profile that points at another computer is not opened here (it could wait a long time); the log says it was skipped.
                $checkAddress = ([string](Get-PostgresFieldValue $databaseCheck.Doc 'Address')).Trim()
                if ($checkAddress -notin @('127.0.0.1', 'localhost', '::1')) { [void]$postgresDatabaseSkipped.Add([string]$databaseCheck.Label); Write-Log ('HealthCheck: database of {0} not checked here: the profile points at another address.' -f $databaseCheck.Label); continue }
                $checkKey = ('{0}|{1}|{2}' -f $checkAddress, (Get-PostgresFieldValue $databaseCheck.Doc 'Port'), (Get-PostgresFieldValue $databaseCheck.Doc 'DbName'))
                if (-not $checkedDatabases.ContainsKey($checkKey)) { $checkedDatabases[$checkKey] = (Get-PostgresGameDatabaseReadiness -Doc $databaseCheck.Doc) }
                $readiness = $checkedDatabases[$checkKey]
                if ($readiness.Ready) { continue }
                # A missing database of a game that has TeknoParrot's own "Automatically create Database" option and no starting file with the game (the games in
                # $postgresAutoCreateLabels) is not a problem Postgres setup could fix: TeknoParrot makes it the first time the game starts, so it is waiting, not failing.
                # A game that ships a starting file stays a problem (menu 11 makes it), and a database that cannot be opened is still a problem.
                if ([string]$readiness.Error -match 'does not exist' -and $postgresAutoCreateLabels.Contains([string]$databaseCheck.Label)) {
                    [void]$postgresAwaitingFirstStart.Add([string]$databaseCheck.Label)
                    Write-Log ('HealthCheck: database of {0} is not made yet; TeknoParrot creates it the first time the game starts.' -f $databaseCheck.Label)
                    continue
                }
                $why = if ([string]$readiness.Error -match 'does not exist') { 'its database is missing' } elseif ([string]$readiness.Error -match '^Found 0 tables') { 'its database has no tables' } else { 'the game cannot connect to its database with its own settings' }
                [void]$postgresDatabaseProblems.Add(('{0}: {1}' -f $databaseCheck.Label, $why))
                Write-Log ('HealthCheck: database problem for {0}: {1}' -f $databaseCheck.Label, $readiness.Error)
            }
        }
    }
    if ($postgresInventoryStatus -ne 'Complete') {
        foreach ($inventoryError in $postgresInventoryErrors) {
            Write-Log ("HealthCheck: PostgreSQL inventory {0}: {1}" -f $postgresInventoryStatus, $inventoryError)
        }
    }
    $lastFullRun = ''
    if ($LogPath -and (Test-Path -LiteralPath $LogPath)) {
        try {
            $lastRun = Get-Content -LiteralPath $LogPath -ErrorAction Stop | Select-String "^\[.*\] Completed\. " | Select-Object -Last 1
            if ($lastRun) { $lastFullRun = [string]$lastRun.Line }
        } catch {
            Write-Log "HealthCheck: the last full run could not be read from the log -- $_"
        }
    }

    $optionalCoverageComplete = (-not $optionalCoverageUnavailable -and $optionalCheckFailed -eq 0)
    $postgresInventoryComplete = ($postgresInventoryStatus -eq 'Complete')
    $postgresServiceUnverified = ($postgresInventoryComplete -and $postgresConfigured -gt 0 -and $null -eq $postgresServiceExists)
    $gameTypeFailed = ($null -ne $gameTypeReport -and [int]$gameTypeReport.Failed -gt 0)
    # Two games that name the same database keep their saved progress in the same tables; one database cannot hold both (Postgres setup gives each its own).
    $postgresSharedDatabases = New-Object System.Collections.Generic.List[string]
    foreach ($sharedGroup in @($postgresDbUsers | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.DbName) } | Group-Object -Property Key | Where-Object { $_.Count -gt 1 })) {
        [void]$postgresSharedDatabases.Add(('{0} use the same database, {1}' -f (@($sharedGroup.Group | ForEach-Object { [string]$_.Label }) -join ' and '), [string]$sharedGroup.Group[0].DbName))
        Write-Log ('HealthCheck: {0} use the same database {1}; Postgres setup (menu 11) gives each its own.' -f (@($sharedGroup.Group | ForEach-Object { [string]$_.Label }) -join ' and '), [string]$sharedGroup.Group[0].DbName)
    }
    $healthOutcome = if ($discoveryFailed -or -not $optionalCoverageComplete -or -not $postgresInventoryComplete -or $postgresServiceUnverified -or $postgresDatabaseProblems.Count -gt 0 -or $postgresSharedDatabases.Count -gt 0 -or $postgresDatabaseSkipped.Count -gt 0 -or $postgresDatabaseCheck -eq 'SkippedNoClient' -or $prerequisiteCheckFailed -or $gameTypeFailed -or [string]::IsNullOrWhiteSpace([string]$detected.Vendor)) { 'ACTION_REQUIRED' } else { 'SUCCEEDED' }
    $postgresDatabaseProblemsResult = @()
    $postgresNeededResult = @()
    $postgresNeededLabelsResult = @()
    $postgresConfiguredResult = 0
    $postgresConfiguredLabelsResult = @()
    $postgresAutoCreateResult = @()
    $postgresAwaitingFirstStartResult = @()
    if ($postgresInventoryComplete) {
        $postgresNeededResult = @($postgresNeeded.ToArray())
        $postgresNeededLabelsResult = @($postgresNeededLabels.ToArray())
        $postgresConfiguredResult = $postgresConfigured
        $postgresConfiguredLabelsResult = @($postgresConfiguredLabels.ToArray())
        $postgresAutoCreateResult = @($postgresAutoCreateLabels.ToArray())
        $postgresAwaitingFirstStartResult = @($postgresAwaitingFirstStart.ToArray())
        $postgresDatabaseProblemsResult = @($postgresDatabaseProblems.ToArray())
    }
    Write-Log ("HealthCheck: inventory={0} total={1} valid={2} broken={3} empty={4} gpuFixNeeded={5} ffbBlasterNeeded={6} dgVoodoo2Needed={7} reShadeCount={8} bepInExCount={9}" -f `
        $postgresInventoryStatus, $profiles.Count, $valid.Count, $broken.Count, $empty.Count, $gpuFixNeeded.Count, $ffbBlasterNeeded.Count, $dgVoodoo2Needed.Count, $reShadeCount, $bepInExCount)
    # Game support view (issues #351 and #389): read-only, offline (saved guide copy only); a failure leaves it out, never the check.
    $gameSupport = $null
    if (-not $discoveryFailed -and $profiles.Count -gt 0) {
        try { $gameSupport = Get-TpmGameSupportSummary -ProfileFiles $profiles -ValidCodes @($valid.ToArray()) -PostgresNeededCodes @($postgresNeeded.ToArray()) -GuideRows (Read-TpmSavedGuideRows) }
        catch { Write-Log "HealthCheck: the game support view could not be made -- $_" }
    }
    $result = [pscustomobject]@{
        Outcome = $healthOutcome
        ReasonCode = $(if ($healthOutcome -eq 'ACTION_REQUIRED') { 'HEALTH_COVERAGE_INCOMPLETE' } else { 'HEALTH_CHECK_COMPLETED' })
        DiscoveryComplete = (-not $discoveryFailed)
        OptionalCoverageComplete = $optionalCoverageComplete
        OptionalCheckFailed = $optionalCheckFailed
        PostgresInventoryStatus = $postgresInventoryStatus
        PostgresInventoryErrors = @($postgresInventoryErrors.ToArray())
        ReadOnly = $true
        Registered = $profiles.Count
        Valid = @($valid.ToArray())
        Broken = @($broken.ToArray())
        DriveUnavailable = @($driveUnavailable.ToArray())
        Empty = @($empty.ToArray())
        Unreadable = @($unreadable.ToArray())
        GpuFixNeeded = @($gpuFixNeeded.ToArray())
        FfbBlasterNeeded = @($ffbBlasterNeeded.ToArray())
        DgVoodoo2Needed = @($dgVoodoo2Needed.ToArray())
        PostgresNeeded = $postgresNeededResult
        PostgresConfigured = $postgresConfiguredResult
        PostgresAutoCreateProfiles = $postgresAutoCreateResult
        PostgresAwaitingFirstStart = $postgresAwaitingFirstStartResult
        PostgresSharedDatabases = @($postgresSharedDatabases.ToArray())
        InternalDatabaseLabels = @($internalDatabaseLabels.ToArray())
        PostgresDatabaseProblems = $postgresDatabaseProblemsResult
        PostgresDatabaseCheck = $postgresDatabaseCheck
        PostgresDatabaseNotChecked = @($postgresDatabaseSkipped.ToArray())
        PostgresServiceExists = $postgresServiceExists
        PostgresServiceUnverified = $postgresServiceUnverified
        PostgresServiceStatus = $postgresStatus
        ReShadeCount = $reShadeCount
        BepInExCount = $bepInExCount
        BepInExNeeded = @($bepInExNeeded.ToArray())
        DetectedGpuVendor = $detected.Vendor
        PostgresNeededLabels = $postgresNeededLabelsResult
        PostgresConfiguredLabels = $postgresConfiguredLabelsResult
        PostgresPsqlStatus = $postgresPsqlStatus
        OptionalCoverageUnavailable = $optionalCoverageUnavailable
        OptionalCoverageError = $optionalCoverageError
        PrerequisiteChecked = (-not $discoveryFailed -and -not [string]::IsNullOrWhiteSpace($TpRoot))
        PrerequisiteMissing = @($prerequisiteMissing)
        PrerequisiteNotChecked = @($prerequisiteNotChecked.ToArray())
        PrerequisiteCheckFailed = $prerequisiteCheckFailed
        GameTypes = $gameTypeReport
        ControlCoverage = $controlsAudit
        LastFullRun = $lastFullRun
        LogPath = $LogPath
        GameSupport = $gameSupport
    }
    Write-TpmLibraryHealthReport -Result $result
    return $result
}

# =============================================================================
# LIBRARY HEALTH CHECK SCREENS (FIX83)
# =============================================================================
# Default view: one short status per area. Everything else is in the details (Get-TpmLibraryHealthDetailBlocks, the
# D key of Show-LibraryHealthNextActions) and in the log (Write-TpmLibraryHealthReport logs every detail line).

function New-TpmLibraryHealthRow {
    param([Parameter(Mandatory)][string]$Area, [Parameter(Mandatory)][string]$Text, [Parameter(Mandatory)][string]$Color)
    return [pscustomobject]@{ Area = $Area; Text = $Text; Color = $Color }
}

# The status rows of the default view. Text starts with OK, Needs attention, Not checked or Could not check. Only a problem
# says how many games. An area that does not apply (PostgreSQL when no game uses a database) has no row.
function Get-TpmLibraryHealthRows {
    param([Parameter(Mandatory)]$Result)
    $rows = New-Object System.Collections.Generic.List[object]
    if (-not [bool]$Result.DiscoveryComplete) {
        [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Game paths' -Text 'Could not check' -Color 'Red'))
        [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Setup checks' -Text 'Could not check' -Color 'Yellow'))
        return $rows.ToArray()
    }
    $needsPath = @($Result.Broken).Count + @($Result.Empty).Count
    $driveCount = @(Get-TpmTransactionField -Object $Result -Name 'DriveUnavailable' -Default @()).Count
    if ($driveCount -gt 0) {
        [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Game drive' -Text ('Needs attention - {0} {1} on a drive that is not connected. Reconnect the drive. Or choose a new folder for {2} with R or S' -f (Format-TpmGameCount -Count $driveCount), $(if ($driveCount -eq 1) { 'is' } else { 'are' }), $(if ($driveCount -eq 1) { 'it' } else { 'them' })) -Color 'Yellow'))
    }
    if ([int]$Result.Registered -eq 0) {
        [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Game paths' -Text 'No games found' -Color 'Yellow'))
    } elseif ($needsPath -gt 0) {
        [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Game paths' -Text ('Needs attention - {0} {1} a new path' -f (Format-TpmGameCount -Count $needsPath), $(if ($needsPath -eq 1) { 'needs' } else { 'need' })) -Color 'Yellow'))
    } elseif (@($Result.Valid).Count -eq 0) {
        if ($driveCount -eq 0) { [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Game paths' -Text 'Could not check - no game profile could be read' -Color 'Red')) }
    } else {
        [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Game paths' -Text ('OK - {0}' -f (Format-TpmGameCount -Count @($Result.Valid).Count)) -Color 'Green'))
    }
    if (@(Get-TpmTransactionField -Object $Result -Name 'Unreadable' -Default @()).Count -gt 0) { [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Profile files' -Text ('Needs attention - {0} could not be read' -f (Format-TpmGameCount -Count @(Get-TpmTransactionField -Object $Result -Name 'Unreadable' -Default @()).Count)) -Color 'Yellow')) }
    $unavailable = [bool](Get-TpmTransactionField -Object $Result -Name 'OptionalCoverageUnavailable' -Default $false)
    $checkFailed = [int](Get-TpmTransactionField -Object $Result -Name 'OptionalCheckFailed' -Default 0)
    $vendor = [string](Get-TpmTransactionField -Object $Result -Name 'DetectedGpuVendor' -Default '')
    foreach ($area in @(
            @{ Area = 'GPU fix'; Needed = @($Result.GpuFixNeeded); NeedsVendor = $true },
            @{ Area = 'Force feedback'; Needed = @($Result.FfbBlasterNeeded); NeedsVendor = $false },
            @{ Area = 'dgVoodoo2'; Needed = @($Result.DgVoodoo2Needed); NeedsVendor = $false })) {
        if ($unavailable) {
            $row = New-TpmLibraryHealthRow -Area $area.Area -Text 'Could not check' -Color 'Yellow'
        } elseif ($area.NeedsVendor -and [string]::IsNullOrWhiteSpace($vendor)) {
            $row = New-TpmLibraryHealthRow -Area $area.Area -Text 'Not checked - GPU not detected' -Color 'DarkGray'
        } elseif ($area.Needed.Count -gt 0) {
            $row = New-TpmLibraryHealthRow -Area $area.Area -Text ('Needs attention - {0}' -f (Format-TpmGameCount -Count $area.Needed.Count)) -Color 'Yellow'
        } elseif ($checkFailed -gt 0) {
            $row = New-TpmLibraryHealthRow -Area $area.Area -Text ('Could not check {0}' -f (Format-TpmGameCount -Count $checkFailed)) -Color 'Yellow'
        } elseif ($area.Area -eq 'Force feedback') {
            # The game profiles are fine, but the force feedback plugin itself is never looked at here (it needs network access).
            $row = New-TpmLibraryHealthRow -Area $area.Area -Text 'Not checked - profiles fine, plugin not looked at' -Color 'DarkGray'
        } else {
            $row = New-TpmLibraryHealthRow -Area $area.Area -Text 'OK' -Color 'Green'
        }
        [void]$rows.Add($row)
    }
    $bepNeeded = @(Get-TpmTransactionField -Object $Result -Name 'BepInExNeeded' -Default @())
    if (-not $unavailable -and $bepNeeded.Count -gt 0) {
        [void]$rows.Add((New-TpmLibraryHealthRow -Area 'BepInEx' -Text ('Needs attention - {0} {1} BepInEx and {2} no BepInEx set up. Run BepInEx setup (menu 9)' -f (Format-TpmGameCount -Count $bepNeeded.Count), $(if ($bepNeeded.Count -eq 1) { 'needs' } else { 'need' }), $(if ($bepNeeded.Count -eq 1) { 'has' } else { 'have' })) -Color 'Yellow'))
    }
    $postgresRow = Get-TpmLibraryHealthPostgresRow -Result $Result
    if ($null -ne $postgresRow) { [void]$rows.Add($postgresRow) }
    $internalCount = @(Get-TpmTransactionField -Object $Result -Name 'InternalDatabaseLabels' -Default @()).Count
    if ($internalCount -gt 0) { [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Game database' -Text ('OK - {0} {1} Internal storage, so no database install is needed. Start each game once so it creates its own database' -f (Format-TpmGameCount -Count $internalCount), $(if ($internalCount -eq 1) { 'uses' } else { 'use' })) -Color 'Green')) }
    foreach ($gameTypeRow in @(if ($null -ne (Get-TpmTransactionField -Object $Result -Name 'GameTypes' -Default $null)) { Get-TpmGameTypeRows -Report $Result.GameTypes })) { [void]$rows.Add($gameTypeRow) }
    $controlCoverageRow = Get-TpmTransactionField -Object $Result -Name 'ControlCoverage' -Default $null
    if ($null -ne $controlCoverageRow -and [int]$controlCoverageRow.Total -gt 0) {
        $notSet = [int]$controlCoverageRow.Partial + [int]$controlCoverageRow.Missing
        $cannotCheck = [int]$controlCoverageRow.Unknown + [int]$controlCoverageRow.Unsupported
        $coverageText = 'Note - {0} of {1} games have every control the game lists set up (not tested in a game)' -f $controlCoverageRow.Complete, $controlCoverageRow.Total
        if ($notSet -gt 0) { $coverageText += '; {0} {1} some or all missing' -f (Format-TpmGameCount -Count $notSet), $(if ($notSet -eq 1) { 'has' } else { 'have' }) }
        if ($cannotCheck -gt 0) { $coverageText += '; TPM cannot check {0}' -f (Format-TpmGameCount -Count $cannotCheck) }
        [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Controls' -Text ($coverageText + '. Choose D for the list') -Color $(if ($notSet -gt 0) { 'Yellow' } else { 'DarkGray' })))
    }
    $prerequisiteRow = Get-TpmLibraryHealthPrerequisiteRow -Result $Result
    if ($null -ne $prerequisiteRow) { [void]$rows.Add($prerequisiteRow) }
    $gameSupport = Get-TpmTransactionField -Object $Result -Name 'GameSupport' -Default $null
    if ($null -ne $gameSupport -and [int]$Result.Registered -gt 0) {
        $needsYou = @($gameSupport.NeedsYouNames).Count
        if ($needsYou -gt 0) {
            [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Game support' -Text ('Needs attention - {0} {1} you. Choose D for the list' -f (Format-TpmGameCount -Count $needsYou), $(if ($needsYou -eq 1) { 'needs' } else { 'need' })) -Color 'Yellow'))
        } else {
            [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Game support' -Text ('OK - nothing is missing for {0}' -f (Format-TpmGameCount -Count ([int]$Result.Registered))) -Color 'Green'))
        }
    }
    return $rows.ToArray()
}

# FIX132: the game startup files (firmware) row, or $null when the check did not run for this result.
function Get-TpmLibraryHealthPrerequisiteRow {
    param([Parameter(Mandatory)]$Result)
    if (-not [bool](Get-TpmTransactionField -Object $Result -Name 'PrerequisiteChecked' -Default $false)) { return $null }
    if ([bool](Get-TpmTransactionField -Object $Result -Name 'PrerequisiteCheckFailed' -Default $false)) {
        return (New-TpmLibraryHealthRow -Area 'Game startup files' -Text 'Could not check' -Color 'Yellow')
    }
    $games = @(@(Get-TpmTransactionField -Object $Result -Name 'PrerequisiteMissing' -Default @()) | ForEach-Object { @($_.AffectedGames) } | Select-Object -Unique)
    if ($games.Count -gt 0) {
        return (New-TpmLibraryHealthRow -Area 'Game startup files' -Text ('Needs attention - {0} {1} missing files' -f (Format-TpmGameCount -Count $games.Count), $(if ($games.Count -eq 1) { 'has' } else { 'have' })) -Color 'Yellow')
    }
    $notChecked = @(Get-TpmTransactionField -Object $Result -Name 'PrerequisiteNotChecked' -Default @())
    if ($notChecked.Count -gt 0) {
        return (New-TpmLibraryHealthRow -Area 'Game startup files' -Text ('Not checked - {0} {1} not set up yet, so its startup files could not be looked at' -f $notChecked.Count, $(if ($notChecked.Count -eq 1) { 'emulator is' } else { 'emulators are' })) -Color 'DarkGray')
    }
    return (New-TpmLibraryHealthRow -Area 'Game startup files' -Text 'OK' -Color 'Green')
}

# The PostgreSQL row, or $null when no game uses a database and nothing about PostgreSQL is wrong.
function Get-TpmLibraryHealthPostgresRow {
    param([Parameter(Mandatory)]$Result)
    $neededCount = @($Result.PostgresNeeded).Count
    $configured = [int]$Result.PostgresConfigured
    if ([string]$Result.PostgresInventoryStatus -ne 'Complete') { return (New-TpmLibraryHealthRow -Area 'PostgreSQL' -Text 'Could not check' -Color 'Yellow') }
    if ($neededCount -gt 0) {
        return (New-TpmLibraryHealthRow -Area 'PostgreSQL' -Text ('Needs attention - {0} {1} setup' -f (Format-TpmGameCount -Count $neededCount), $(if ($neededCount -eq 1) { 'needs' } else { 'need' })) -Color 'Yellow')
    }
    if (@(Get-TpmTransactionField -Object $Result -Name 'PostgresDatabaseProblems' -Default @()).Count -gt 0) {
        $problemCount = @($Result.PostgresDatabaseProblems).Count
        return (New-TpmLibraryHealthRow -Area 'PostgreSQL' -Text ('Problem - {0} {1} database that is not ready. Run Postgres setup (menu 11)' -f (Format-TpmGameCount -Count $problemCount), $(if ($problemCount -eq 1) { 'has a' } else { 'have a' })) -Color 'Yellow')
    }
    if (@(Get-TpmTransactionField -Object $Result -Name 'PostgresSharedDatabases' -Default @()).Count -gt 0) {
        return (New-TpmLibraryHealthRow -Area 'PostgreSQL' -Text 'Needs attention - some games use the same database. Run Postgres setup (menu 11)' -Color 'Yellow')
    }
    if ($configured -le 0) { return $null }
    if ([bool](Get-TpmTransactionField -Object $Result -Name 'PostgresServiceUnverified' -Default $false)) { return (New-TpmLibraryHealthRow -Area 'PostgreSQL' -Text 'Could not check' -Color 'Yellow') }
    if ($Result.PostgresServiceExists -eq $false) { return (New-TpmLibraryHealthRow -Area 'PostgreSQL' -Text 'Needs attention - PostgreSQL is not installed' -Color 'Yellow') }
    if ([string]$Result.PostgresServiceStatus -eq 'Stopped') { return (New-TpmLibraryHealthRow -Area 'PostgreSQL' -Text 'Needs attention - PostgreSQL is stopped' -Color 'Yellow') }
    if (@(Get-TpmTransactionField -Object $Result -Name 'PostgresDatabaseNotChecked' -Default @()).Count -gt 0) { return (New-TpmLibraryHealthRow -Area 'PostgreSQL' -Text 'Needs attention - some game databases could not be checked because they point at another computer' -Color 'Yellow') }
    if ([string](Get-TpmTransactionField -Object $Result -Name 'PostgresDatabaseCheck' -Default '') -eq 'SkippedNoClient') { return (New-TpmLibraryHealthRow -Area 'PostgreSQL' -Text 'Needs attention - the game databases could not be checked because psql.exe was not found. Run Postgres setup (menu 11)' -Color 'Yellow') }
    if (@(Get-TpmTransactionField -Object $Result -Name 'PostgresAwaitingFirstStart' -Default @()).Count -gt 0) { return (New-TpmLibraryHealthRow -Area 'PostgreSQL' -Text 'OK - profile ready; a game database is created the first time the game starts' -Color 'Green') }
    return (New-TpmLibraryHealthRow -Area 'PostgreSQL' -Text 'OK' -Color 'Green')
}

# The lines under the rows: the overall verdict and the pointer to the details. Never an all-clear while a check could not finish.
function Get-TpmLibraryHealthSummaryLines {
    param([Parameter(Mandatory)]$Result, [Parameter(Mandatory)][object[]]$Rows)
    if (-not [bool]$Result.DiscoveryComplete) {
        return @(
            @{ Text = 'TeknoParrot Manager could not read your list of games.'; Color = 'Red' },
            @{ Text = 'No counts are shown. Details are in the log.'; Color = 'DarkGray' }
        )
    }
    if ([int]$Result.Registered -eq 0) {
        return @(@{ Text = 'No registered games were found, so no game path was checked.'; Color = 'Yellow' })
    }
    $incomplete = ([bool](Get-TpmTransactionField -Object $Result -Name 'OptionalCoverageUnavailable' -Default $false)) -or
        ([int](Get-TpmTransactionField -Object $Result -Name 'OptionalCheckFailed' -Default 0) -gt 0) -or
        ([bool](Get-TpmTransactionField -Object $Result -Name 'PrerequisiteCheckFailed' -Default $false)) -or
        ($null -ne (Get-TpmTransactionField -Object $Result -Name 'GameTypes' -Default $null) -and [int](Get-TpmTransactionField -Object $Result.GameTypes -Name 'Failed' -Default 0) -gt 0) -or
        ([string]$Result.PostgresInventoryStatus -ne 'Complete') -or
        ([bool](Get-TpmTransactionField -Object $Result -Name 'PostgresServiceUnverified' -Default $false)) -or
        [string]::IsNullOrWhiteSpace([string](Get-TpmTransactionField -Object $Result -Name 'DetectedGpuVendor' -Default ''))
    $attention = (@($Rows | Where-Object { ([string]$_.Text).StartsWith('Needs attention') -or ([string]$_.Text).StartsWith('Problem') }).Count -gt 0)
    $lines = New-Object System.Collections.Generic.List[object]
    if ($attention) {
        [void]$lines.Add(@{ Text = 'Some things need attention.'; Color = 'Yellow' })
    } elseif (-not $incomplete) {
        [void]$lines.Add(@{ Text = 'Everything looks fine.'; Color = 'Green' })
    }
    if ($incomplete) { [void]$lines.Add(@{ Text = 'Some checks could not finish, so this is not an all-clear.'; Color = 'Yellow' }) }
    [void]$lines.Add(@{ Text = 'Choose D below to see every detail.'; Color = 'DarkGray' })
    return $lines.ToArray()
}

# The process exit code of an unattended health check. A check that finished is 0 even when it found problems in the library;
# a check that could not look at everything is 2, so a scheduler never reads it as a clean pass.
function Get-TpmHealthCheckExitCode {
    param($Result)
    if ($null -ne $Result -and [string]$Result.Outcome -eq 'SUCCEEDED') { return 0 }
    return 2
}

# Every fact of the check, one short block per area. Shown by the D key and written to the log.
function Get-TpmLibraryHealthDetailBlocks {
    param([Parameter(Mandatory)]$Result)
    $blocks = New-Object System.Collections.Generic.List[object]
    $complete = [bool]$Result.DiscoveryComplete
    $unavailable = [bool](Get-TpmTransactionField -Object $Result -Name 'OptionalCoverageUnavailable' -Default $false)
    $vendor = [string](Get-TpmTransactionField -Object $Result -Name 'DetectedGpuVendor' -Default '')
    $notAssessed = 'Status: Not assessed because the game list could not be read.'
    $brokenNames = @($Result.Broken)
    $emptyNames = @($Result.Empty)

    $lines = New-Object System.Collections.Generic.List[string]
    if ($complete) {
        [void]$lines.Add(('Registered games: {0}' -f $Result.Registered))
        [void]$lines.Add(('Valid paths: {0}' -f @($Result.Valid).Count))
        [void]$lines.Add(('Broken paths: {0}{1}' -f $brokenNames.Count, $(if ($brokenNames.Count -gt 0) { ' - ' + (Format-TpmNameList -Names $brokenNames -Max 1000) } else { '' })))
        $driveNames = @(Get-TpmTransactionField -Object $Result -Name 'DriveUnavailable' -Default @())
        if ($driveNames.Count -gt 0) { [void]$lines.Add(('Drive or device not available: {0} - {1}. Reconnect the drive, or choose R or S to point these games at a new folder; the saved paths were not judged.' -f $driveNames.Count, (Format-TpmNameList -Names $driveNames -Max 1000))) }
        [void]$lines.Add(('Empty paths: {0}{1}' -f $emptyNames.Count, $(if ($emptyNames.Count -gt 0) { ' - ' + (Format-TpmNameList -Names $emptyNames -Max 1000) } else { '' })))
        $unreadableNames = @(Get-TpmTransactionField -Object $Result -Name 'Unreadable' -Default @())
        if ($unreadableNames.Count -gt 0) { [void]$lines.Add(('Unreadable profile files: {0} - {1}' -f $unreadableNames.Count, (Format-TpmNameList -Names $unreadableNames -Max 1000))) }
        [void]$lines.Add('What it means: A broken path points to a file Windows cannot find. An empty path means no game path is saved yet. An unreadable profile file is damaged, locked or half-saved, so its path was not checked.')
        if (($brokenNames.Count + $emptyNames.Count) -gt 0) { [void]$lines.Add('Repairs: TeknoParrot Manager only reported these paths. It did not repair or save anything during this check.') }
    } else {
        [void]$lines.Add('Game list: Error - the registered game and path counts are withheld.')
        foreach ($inventoryError in @($Result.PostgresInventoryErrors)) { [void]$lines.Add(('Problem: {0}' -f $inventoryError)) }
    }
    [void]$blocks.Add(@{ Heading = 'Game paths'; Lines = $lines.ToArray() })

    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add(('Detected GPU: {0}' -f $(if ($vendor) { $vendor } else { 'not detected' })))
    if (-not $complete) {
        [void]$lines.Add($notAssessed)
    } elseif ($unavailable) {
        [void]$lines.Add('Status: Unavailable - the GPU field definitions could not be read. This is NOT a clean result.')
    } elseif (-not $vendor) {
        [void]$lines.Add('Status: Could not be assessed because TeknoParrot Manager could not detect the GPU vendor.')
    } else {
        [void]$lines.Add(('Still needs the fix: {0}' -f (Format-TpmNameList -Names @($Result.GpuFixNeeded) -Max 1000 -WhenEmpty 'none')))
    }
    [void]$blocks.Add(@{ Heading = 'GPU fix'; Lines = $lines.ToArray() })

    $lines = New-Object System.Collections.Generic.List[string]
    if (-not $complete) {
        [void]$lines.Add($notAssessed)
    } elseif ($unavailable) {
        [void]$lines.Add('Status: Unavailable - the FFB field definitions could not be read. This is NOT a clean result.')
    } else {
        [void]$lines.Add(('Profile support still needed: {0}' -f (Format-TpmNameList -Names @($Result.FfbBlasterNeeded) -Max 1000 -WhenEmpty 'none')))
    }
    [void]$lines.Add('Force feedback plugin was not checked because network access is needed.')
    [void]$blocks.Add(@{ Heading = 'Force feedback'; Lines = $lines.ToArray() })

    $lines = New-Object System.Collections.Generic.List[string]
    if (-not $complete) {
        [void]$lines.Add($notAssessed)
    } elseif ($unavailable) {
        [void]$lines.Add('Status: Not checked because the GPU and FFB field definitions could not be read.')
    } else {
        [void]$lines.Add(('Still needed: {0}' -f (Format-TpmNameList -Names @($Result.DgVoodoo2Needed) -Max 1000 -WhenEmpty 'none')))
    }
    [void]$blocks.Add(@{ Heading = 'dgVoodoo2 (older DirectX and Glide games)'; Lines = $lines.ToArray() })

    $serviceExists = $Result.PostgresServiceExists
    $serviceStatus = [string]$Result.PostgresServiceStatus
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add(('Service exists: {0}' -f $(if ($serviceExists -eq $true) { 'found' } elseif ($serviceExists -eq $false) { 'not found' } else { 'unknown' })))
    [void]$lines.Add(('Service state: {0}' -f $(if ($serviceStatus -eq 'Running') { 'running' } elseif ($serviceStatus -eq 'Stopped') { 'stopped' } elseif ($serviceStatus -eq 'NotInstalled') { 'not available' } else { 'unknown' })))
    [void]$lines.Add(('Client psql.exe: {0}' -f (Get-TpmTransactionField -Object $Result -Name 'PostgresPsqlStatus' -Default 'Unknown')))
    [void]$lines.Add(('Profile inventory: {0}' -f $Result.PostgresInventoryStatus))
    if ([string]$Result.PostgresInventoryStatus -eq 'Complete') {
        $neededCount = @($Result.PostgresNeeded).Count
        $neededLabels = @(Get-TpmTransactionField -Object $Result -Name 'PostgresNeededLabels' -Default @($Result.PostgresNeeded))
        $configuredLabels = @(Get-TpmTransactionField -Object $Result -Name 'PostgresConfiguredLabels' -Default @())
        $autoCreate = @(Get-TpmTransactionField -Object $Result -Name 'PostgresAutoCreateProfiles' -Default @())
        $awaitingFirstStart = @(Get-TpmTransactionField -Object $Result -Name 'PostgresAwaitingFirstStart' -Default @())
        [void]$lines.Add(('Setup needed for: {0}' -f (Format-TpmNameList -Names $neededLabels -Max 1000 -WhenEmpty 'none')))
        [void]$lines.Add(('Fields filled in for: {0}' -f (Format-TpmNameList -Names $configuredLabels -Max 1000 -WhenEmpty 'none')))
        if ($neededCount -gt 0) {
            [void]$lines.Add('Review PostgreSQL setup; TeknoParrot Manager will make a safety backup before changes.')
        } elseif ([int]$Result.PostgresConfigured -gt 0) {
            $databaseCheck = [string](Get-TpmTransactionField -Object $Result -Name 'PostgresDatabaseCheck' -Default 'NotNeeded')
            $databaseProblems = @(Get-TpmTransactionField -Object $Result -Name 'PostgresDatabaseProblems' -Default @())
            $databaseSkipped = @(Get-TpmTransactionField -Object $Result -Name 'PostgresDatabaseNotChecked' -Default @())
            if ($databaseCheck -eq 'Done' -and $databaseProblems.Count -eq 0 -and $databaseSkipped.Count -eq 0 -and $awaitingFirstStart.Count -eq 0) { [void]$lines.Add('Database check: every game database is there, opens with the game''s own settings and has tables.') }
            elseif ($databaseCheck -eq 'Done' -and $databaseProblems.Count -eq 0) { [void]$lines.Add('Database check: the databases that could be checked are there, open with the game''s own settings and have tables.') }
            elseif ($databaseCheck -eq 'Done') {
                foreach ($databaseProblem in $databaseProblems) { [void]$lines.Add(('Problem - {0}' -f $databaseProblem)) }
                [void]$lines.Add('Postgres setup (menu 11) creates and checks these databases. This scan only looked and changed nothing.')
            }
            elseif ($databaseCheck -eq 'SkippedNotInstalled') { [void]$lines.Add('Database check: skipped, because PostgreSQL is not installed. Run Postgres setup (menu 11).') }
            elseif ($databaseCheck -eq 'SkippedNotRunning') { [void]$lines.Add('Database check: skipped, because PostgreSQL is not running.') }
            elseif ($databaseCheck -eq 'SkippedNoClient') { [void]$lines.Add('Database check: skipped, because the PostgreSQL client (psql.exe) was not found. Run Postgres setup (menu 11).') }
            if ($databaseSkipped.Count -gt 0) { [void]$lines.Add(('Not checked here: {0} (their profile points at another computer).' -f (Format-TpmNameList -Names $databaseSkipped -Max 1000))) }
        } else {
            [void]$lines.Add('No PostgreSQL database profiles were found.')
        }
        if ($autoCreate.Count -gt 0) {
            [void]$lines.Add(('Games with no starting database file: {0}' -f (Format-TpmNameList -Names $autoCreate -Max 1000)))
            if ($awaitingFirstStart.Count -gt 0) { [void]$lines.Add(('Profile ready; the database is created the first time the game starts: {0}' -f (Format-TpmNameList -Names $awaitingFirstStart -Max 1000))) }
            [void]$lines.Add('These games make their own database (TeknoParrot''s "Automatically create Database" option). Nothing is wrong and nothing needs to be done. If you put the game''s pg_backup folder back, PostgreSQL setup (menu 11) can make it now.')
        }
    } else {
        [void]$lines.Add('Setup needs: Not reported - the game check was incomplete, so setup needs and filled-in counts are withheld.')
    }
    $internalDatabaseLabels = @(Get-TpmTransactionField -Object $Result -Name 'InternalDatabaseLabels' -Default @())
    if ($internalDatabaseLabels.Count -gt 0) {
        [void]$lines.Add(('Games using Internal storage (no PostgreSQL needed): {0}' -f (Format-TpmNameList -Names $internalDatabaseLabels -Max 1000)))
        foreach ($choiceLine in (Get-TpmDatabaseChoiceLines)) { [void]$lines.Add($choiceLine) }
    }
    foreach ($sharedText in @(Get-TpmTransactionField -Object $Result -Name 'PostgresSharedDatabases' -Default @())) {
        [void]$lines.Add(('Problem - {0}. Two games keep their saved progress in the same tables, so one database cannot hold both.' -f $sharedText))
        [void]$lines.Add('Postgres setup (menu 11) gives each game its own database. It deletes nothing and keeps both sets of progress.')
    }
    [void]$blocks.Add(@{ Heading = 'PostgreSQL'; Lines = $lines.ToArray() })

    if ([bool](Get-TpmTransactionField -Object $Result -Name 'PrerequisiteChecked' -Default $false)) {
        $lines = New-Object System.Collections.Generic.List[string]
        if ([bool](Get-TpmTransactionField -Object $Result -Name 'PrerequisiteCheckFailed' -Default $false)) {
            [void]$lines.Add('Status: Could not be checked. This is NOT a clean result. The log says why.')
        } elseif (@(Get-TpmTransactionField -Object $Result -Name 'PrerequisiteMissing' -Default @()).Count -eq 0) {
            [void]$lines.Add('No missing startup files were found. An emulator that is not installed yet is not checked (existence check only).')
        } else {
            foreach ($prerequisite in @(Get-TpmTransactionField -Object $Result -Name 'PrerequisiteMissing' -Default @())) {
                $prerequisiteScreen = Get-TpmPrerequisiteScreenLines -Warning $prerequisite
                foreach ($prerequisiteLine in @($prerequisiteScreen.Plain)) { [void]$lines.Add($prerequisiteLine) }
                foreach ($prerequisiteLine in @($prerequisiteScreen.Details)) { [void]$lines.Add($prerequisiteLine) }
            }
        }
        [void]$blocks.Add(@{ Heading = 'Game startup files (firmware)'; Lines = $lines.ToArray() })
    }

    $gameTypeReport = Get-TpmTransactionField -Object $Result -Name 'GameTypes' -Default $null
    if ($null -ne $gameTypeReport) { foreach ($gameTypeBlock in @(Get-TpmGameTypeDetailBlocks -Report $gameTypeReport)) { [void]$blocks.Add($gameTypeBlock) } }
    $controlCoverage = Get-TpmTransactionField -Object $Result -Name 'ControlCoverage' -Default $null
    if ($null -ne $controlCoverage -and [int]$controlCoverage.Total -gt 0) {
        $coverageSummary = Get-TpmControlCoverageAuditSummary -Audit $controlCoverage
        foreach ($coverageBlock in @($coverageSummary.Blocks)) { [void]$blocks.Add(@{ Heading = ('Controls: ' + $coverageBlock.Heading); Lines = @($coverageBlock.Lines) }) }
        [void]$blocks.Add(@{ Heading = 'Controls: what this means'; Lines = @($coverageSummary.Note) })
    }

    $lines = New-Object System.Collections.Generic.List[string]
    if ($complete) {
        if ([bool](Get-TpmTransactionField -Object $Result -Name 'OptionalCoverageUnavailable' -Default $false)) {
            [void]$lines.Add('ReShade installed: not checked')
            [void]$lines.Add('BepInEx installed: not checked')
        } else {
            [void]$lines.Add(('ReShade installed: {0} of {1} valid games' -f $Result.ReShadeCount, @($Result.Valid).Count))
            [void]$lines.Add(('BepInEx installed: {0} of {1} valid games' -f $Result.BepInExCount, @($Result.Valid).Count))
            $bepNeededNames = @(Get-TpmTransactionField -Object $Result -Name 'BepInExNeeded' -Default @())
            if ($bepNeededNames.Count -gt 0) { [void]$lines.Add(('Games that need BepInEx and do not have it set up: {0}' -f (Format-TpmNameList -Names $bepNeededNames -Max 1000))) }
        }
        [void]$lines.Add('Note: ReShade is your choice for each game, so it is not flagged. BepInEx is flagged only for games whose profile says they need it.')
    } else {
        [void]$lines.Add('Status: Not assessed.')
    }
    [void]$blocks.Add(@{ Heading = 'ReShade and BepInEx'; Lines = $lines.ToArray() })

    $gameSupport = Get-TpmTransactionField -Object $Result -Name 'GameSupport' -Default $null
    if ($null -ne $gameSupport) { [void]$blocks.Add(@{ Heading = 'Game support by emulator'; Lines = @(Get-TpmGameSupportLines -Summary $gameSupport) }) }

    $lines = New-Object System.Collections.Generic.List[string]
    $failedGames = [int](Get-TpmTransactionField -Object $Result -Name 'OptionalCheckFailed' -Default 0)
    $coverageError = [string](Get-TpmTransactionField -Object $Result -Name 'OptionalCoverageError' -Default '')
    if ($failedGames -gt 0) { [void]$lines.Add(('Games that could not be fully checked: {0}. GPU, FFB and other optional setup status is incomplete. The log says why.' -f $failedGames)) }
    if ($coverageError) { [void]$lines.Add(('Field definitions: Could not be read - {0}' -f $coverageError)) }
    if ($lines.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Checks that could not finish'; Lines = $lines.ToArray() }) }

    $lines = New-Object System.Collections.Generic.List[string]
    $lastRun = [string](Get-TpmTransactionField -Object $Result -Name 'LastFullRun' -Default '')
    $logPath = [string](Get-TpmTransactionField -Object $Result -Name 'LogPath' -Default '')
    if ($lastRun) { [void]$lines.Add(('Last full run: {0}' -f $lastRun)) }
    if ($logPath) { [void]$lines.Add(('Technical log: {0}' -f $logPath)) }
    if ($lines.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Log'; Lines = $lines.ToArray() }) }
    return $blocks.ToArray()
}

# The default view of the check: what it did, one row per area, the verdict. Writes every detail line to the log first.
function Write-TpmLibraryHealthReport {
    param([Parameter(Mandatory)]$Result)
    Write-TpmDetailBlocksLog -Blocks @(Get-TpmLibraryHealthDetailBlocks -Result $Result) -Prefix 'Library health detail'
    $rows = @(Get-TpmLibraryHealthRows -Result $Result)
    $labelWidth = [int](($rows | ForEach-Object { ([string]$_.Area).Length } | Measure-Object -Maximum).Maximum) + 2
    Write-Host ''
    Write-TpmText -Text 'TeknoParrot Manager checked your setup and did not change anything.' -Color Cyan
    Write-Host ''
    foreach ($row in $rows) {
        Write-TpmLabelValue -Prefix (([string]$row.Area + ':').PadRight($labelWidth)) -Text ([string]$row.Text) -Indent 2 -Color ([string]$row.Color)
    }
    Write-Host ''
    foreach ($line in @(Get-TpmLibraryHealthSummaryLines -Result $Result -Rows $rows)) { Write-TpmText -Text ([string]$line.Text) -Color ([string]$line.Color) }
}

# Games saved on a drive that is not connected: says plainly what R and S do for them, before anything changes.
function Write-TpmLibraryHealthDriveNotice {
    param([Parameter(Mandatory)]$Result, [switch]$OfferChoices)
    $driveNames = @(Get-TpmTransactionField -Object $Result -Name 'DriveUnavailable' -Default @())
    if ($driveNames.Count -eq 0) { return }
    Write-Host ''
    Write-TpmText -Text ('{0} {1} on a drive that is not connected: {2}.' -f (Format-TpmGameCount -Count $driveNames.Count), $(if ($driveNames.Count -eq 1) { 'is' } else { 'are' }), (Format-TpmNameList -Names $driveNames -Max 5)) -Color Yellow
    Write-TpmText -Text 'If the drive is only unplugged, connect it and choose B. Nothing is changed.' -Color DarkGray
    Write-TpmText -Text 'If you moved them to another folder, choose R or S. A game is pointed at the new folder only if its game file is found there. You see a preview, answer Y, and a safety backup is made before anything is saved.' -Color DarkGray
    if ($OfferChoices) {
        Write-Host ''
        Write-TpmText -Text '[R] Search the game folder for these games' -Color White -HangingIndent 4
        Write-TpmText -Text '[S] Search another game folder' -Color White -HangingIndent 4
    }
}

function Write-TpmLibraryHealthBrokenMenu {
    param([Parameter(Mandatory)]$Result)
    Write-Host ''
    Write-TpmText -Text 'Broken saved paths need repair before optional setup.' -Color Yellow
    Write-TpmText -Text ('{0} cannot be found at the saved path: {1}.' -f (Format-TpmGameCount -Count @($Result.Broken).Count), (Format-TpmNameList -Names @($Result.Broken) -Max 5)) -Color Yellow
    if (@(Get-TpmTransactionField -Object $Result -Name 'DriveUnavailable' -Default @()).Count -gt 0) { Write-TpmLibraryHealthDriveNotice -Result $Result }
    Write-Host ''
    Write-TpmText -Text '[R] Try automatic path repair' -Color White -HangingIndent 4
    Write-TpmText -Text '[M] Let me pick the correct executable manually' -Color White -HangingIndent 4
    Write-TpmText -Text '[S] Search another game folder' -Color White -HangingIndent 4
    Write-TpmText -Text 'Search checks only known game folders and never changes a valid path.' -Color DarkGray
    Write-Host ''
    Write-TpmText -Text '[D] Details' -Color White
    Write-TpmText -Text '[B] Back to main menu' -Color White
}

function Write-TpmLibraryHealthActionMenu {
    param([Parameter(Mandatory)]$Result)
    Write-Host ''
    if (-not [bool]$Result.DiscoveryComplete) {
        Write-TpmText -Text 'Your game list could not be read, so the setup choices are hidden.' -Color Yellow
    } else {
        $emptyCount = @($Result.Empty).Count
        if ($emptyCount -gt 0) {
            Write-TpmText -Text ('{0} {1} no saved path yet. Use Register to choose one.' -f (Format-TpmGameCount -Count $emptyCount), $(if ($emptyCount -eq 1) { 'has' } else { 'have' })) -Color Yellow
        } elseif (@(Get-TpmTransactionField -Object $Result -Name 'DriveUnavailable' -Default @()).Count -gt 0) {
            Write-TpmLibraryHealthDriveNotice -Result $Result -OfferChoices
        } else {
            Write-TpmText -Text 'No broken saved paths were found.' -Color Green
        }
        $unreadableNames = @(Get-TpmTransactionField -Object $Result -Name 'Unreadable' -Default @())
        if ($unreadableNames.Count -gt 0) {
            Write-TpmText -Text ('{0} could not be read, so it was not checked: {1}. Path repair cannot fix this. Open Details for the reason.' -f (Format-TpmGameCount -Count $unreadableNames.Count), (Format-TpmNameList -Names $unreadableNames -Max 5)) -Color Yellow
        }
        $databaseProblemNames = @(Get-TpmTransactionField -Object $Result -Name 'PostgresDatabaseProblems' -Default @())
        if ($databaseProblemNames.Count -gt 0 -and @($Result.PostgresNeeded).Count -eq 0) {
            Write-Host ''
            Write-TpmText -Text ('{0} {1} a database that is not ready: {2}.' -f (Format-TpmGameCount -Count $databaseProblemNames.Count), $(if ($databaseProblemNames.Count -eq 1) { 'has' } else { 'have' }), (Format-TpmNameList -Names $databaseProblemNames -Max 5)) -Color Yellow
            Write-TpmText -Text 'Postgres setup (menu 11) creates and checks it.' -Color DarkGray
            Write-TpmText -Text '[P] Set up PostgreSQL for these games' -Color White -HangingIndent 4
        }
        $postgresCount = @($Result.PostgresNeeded).Count
        if ($postgresCount -gt 0) {
            $postgresNames = @(Get-TpmTransactionField -Object $Result -Name 'PostgresNeededLabels' -Default @($Result.PostgresNeeded))
            Write-Host ''
            Write-TpmText -Text ('{0} still {1} PostgreSQL set up: {2}.' -f (Format-TpmGameCount -Count $postgresCount), $(if ($postgresCount -eq 1) { 'needs' } else { 'need' }), (Format-TpmNameList -Names $postgresNames -Max 5)) -Color Yellow
            Write-TpmText -Text 'TeknoParrot Manager will make a safety backup before changing PostgreSQL or these game profiles.' -Color DarkGray
            Write-TpmText -Text '[P] Set up PostgreSQL for these games' -Color White -HangingIndent 4
        }
        $prerequisiteMissingCount = @(@(Get-TpmTransactionField -Object $Result -Name 'PrerequisiteMissing' -Default @()) | ForEach-Object { @($_.AffectedGames) } | Select-Object -Unique).Count
        if ($prerequisiteMissingCount -gt 0) {
            Write-Host ''
            Write-TpmText -Text ('{0} {1} missing startup files (firmware).' -f (Format-TpmGameCount -Count $prerequisiteMissingCount), $(if ($prerequisiteMissingCount -eq 1) { 'has' } else { 'have' })) -Color Yellow
            Write-TpmText -Text '[F] Fix the missing startup files (shows what it found and asks before copying)' -Color White -HangingIndent 4
        }
        $validCount = @($Result.Valid).Count
        $dgCount = @($Result.DgVoodoo2Needed).Count
        $gpuCount = @($Result.GpuFixNeeded).Count
        $coverageMissing = [bool](Get-TpmTransactionField -Object $Result -Name 'OptionalCoverageUnavailable' -Default $false)
        $reShadeText = if ($validCount -gt 0 -and -not $coverageMissing) { ' ({0} of {1} have it)' -f $Result.ReShadeCount, (Format-TpmGameCount -Count $validCount) } else { '' }
        $bepNeededCount = @(Get-TpmTransactionField -Object $Result -Name 'BepInExNeeded' -Default @()).Count
        $bepInExText = if ($validCount -gt 0 -and -not $coverageMissing) { ' ({0} of {1} have it)' -f $Result.BepInExCount, (Format-TpmGameCount -Count $validCount) } else { '' }
        if ($bepNeededCount -gt 0 -and -not $coverageMissing) { $bepInExText += (' ({0} still {1} it)' -f (Format-TpmGameCount -Count $bepNeededCount), $(if ($bepNeededCount -eq 1) { 'needs' } else { 'need' })) }
        $dgText = if ($dgCount -gt 0) { ' ({0} still {1} it)' -f (Format-TpmGameCount -Count $dgCount), $(if ($dgCount -eq 1) { 'needs' } else { 'need' }) } else { '' }
        $gpuText = if ($gpuCount -gt 0) { ' ({0} still {1} it)' -f (Format-TpmGameCount -Count $gpuCount), $(if ($gpuCount -eq 1) { 'needs' } else { 'need' }) } else { '' }
        Write-Host ''
        Write-TpmText -Text ('[5] ReShade{0}' -f $reShadeText) -Color White -HangingIndent 4
        Write-TpmText -Text ('[6] dgVoodoo2{0}' -f $dgText) -Color White -HangingIndent 4
        Write-TpmText -Text ('[7] GPU Fix{0}' -f $gpuText) -Color White -HangingIndent 4
        Write-TpmText -Text '[8] Force Feedback' -Color White -HangingIndent 4
        Write-TpmText -Text ('[9] BepInEx{0}' -f $bepInExText) -Color White -HangingIndent 4
    }
    Write-Host ''
    Write-TpmText -Text '[D] Details' -Color White
    Write-TpmText -Text '[B] Back to main menu' -Color White
}

# Presents plain-language actions after the read-only Health Check report.
function Show-LibraryHealthNextActions {
    param([Parameter(Mandatory)]$Result)
    $hasBroken = (@($Result.Broken).Count -gt 0)
    $driveGames = @(Get-TpmTransactionField -Object $Result -Name 'DriveUnavailable' -Default @())
    # Games on a drive that is not connected can be pointed at a new folder with R or S (when no game needs a path first).
    $offerDriveRepair = ($Result.DiscoveryComplete -and -not $hasBroken -and $driveGames.Count -gt 0 -and @($Result.Empty).Count -eq 0)
    $allowedChoices = if ($Result.DiscoveryComplete) { @('5', '6', '7', '8', '9', 'D', 'B') } else { @('D', 'B') }
    if ($Result.PostgresInventoryStatus -eq 'Complete' -and (@($Result.PostgresNeeded).Count -gt 0 -or @(Get-TpmTransactionField -Object $Result -Name 'PostgresDatabaseProblems' -Default @()).Count -gt 0)) { $allowedChoices += 'P' }
    if ($Result.DiscoveryComplete -and -not $hasBroken -and @(Get-TpmTransactionField -Object $Result -Name 'PrerequisiteMissing' -Default @()).Count -gt 0) { $allowedChoices += 'F' }
    if ($offerDriveRepair) { $allowedChoices += @('R', 'S') }

    if ($Result.PostgresInventoryStatus -ne 'Complete') {
        Write-TpmText -Text 'PostgreSQL setup choices are hidden because the game check was incomplete.' -Color Yellow
    }
    $detailBlocks = @(Get-TpmLibraryHealthDetailBlocks -Result $Result)
    do {
        if ($hasBroken) { Write-TpmLibraryHealthBrokenMenu -Result $Result } else { Write-TpmLibraryHealthActionMenu -Result $Result }
        $choice = if ($hasBroken) {
            Read-TpmChoice -Prompt '  Choose R, M, S, D, or B' -Choices @('R', 'M', 'S', 'D', 'B') -Default 'B'
        } else {
            Read-TpmChoice -Prompt '  Choose an action' -Choices $allowedChoices -Default 'B'
        }
        if ($choice -eq 'D') { Show-TpmDetailBlocks -Blocks $detailBlocks -Note 'The health check only looked. It did not change anything.' }
    } while ($choice -eq 'D')
    return $choice
}

# =============================================================================
# COMPATIBILITY WARNINGS  (Raw Thrills path-length + iDmacDrv32 version pins)
# =============================================================================
# Static, empirically-documented facts about specific old game builds --
# not something that changes upstream, so hardcoded here rather than
# live-fetched (unlike the FFB table, which tracks a live upstream project).

# Standard CRC-32 (IEEE 802.3 polynomial), table-driven. .NET has no
# built-in CRC32 type, so this is a small self-contained implementation.
function Get-Crc32 {
    param([string]$Path)
    # PowerShell parses 0xFFFFFFFF / 0xEDB88320 as negative Int32 literals
    # (they exceed Int32.MaxValue), which breaks casting/bxor against
    # [uint32] values -- use the decimal equivalents instead so they
    # promote to Int64 and cast to UInt32 cleanly.
    $poly    = 3988292384  # 0xEDB88320
    $allOnes = 4294967295  # 0xFFFFFFFF
    $crcTable = New-Object 'System.UInt32[]' 256
    for ($i = 0; $i -lt 256; $i++) {
        $c = [uint32]$i
        for ($j = 0; $j -lt 8; $j++) {
            if (($c -band 1) -ne 0) { $c = [uint32]($poly -bxor ($c -shr 1)) }
            else { $c = [uint32]($c -shr 1) }
        }
        $crcTable[$i] = $c
    }
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    $crc = [uint32]$allOnes
    foreach ($b in $bytes) {
        $crc = [uint32]($crcTable[($crc -bxor $b) -band 0xFF] -bxor ($crc -shr 8))
    }
    return ('{0:X8}' -f [uint32]($crc -bxor $allOnes))
}

# Raw Thrills used three engine generations with different hard-coded
# install-path length limits. Exceeding the limit causes the game to fail
# to launch. Value = @{ Limit; Suggested } -- Suggested is the short
# folder rename the community has settled on for that title.
$RawThrillsPathLimits = @{
    # ~64-char limit (old engine, strictest)
    'BBHPro'           = @{ Limit = 64; Suggested = 'BBHP'   }
    'BBHHome'          = @{ Limit = 64; Suggested = 'BBHPH'  }
    'FNF'              = @{ Limit = 64; Suggested = 'FNF'    }
    'FNFSB'            = @{ Limit = 64; Suggested = 'FNFSB'  }
    'GHA'              = @{ Limit = 64; Suggested = 'GHA'    }
    'NicktoonsNitro'   = @{ Limit = 64; Suggested = 'NTN'    }
    'Terminator'       = @{ Limit = 64; Suggested = 'TERM'   }
    'TargetTerrorGold' = @{ Limit = 64; Suggested = 'TTG'    }
    # ~96-char limit (mid-era engine)
    'AliensArmageddon' = @{ Limit = 96; Suggested = 'ALIENS' }
    'BBHWorld'         = @{ Limit = 96; Suggested = 'BBHW'   }
    'Cars'             = @{ Limit = 96; Suggested = 'CARS'   }
    'DirtyDrivin'      = @{ Limit = 96; Suggested = 'DRTYDR' }
    'FNFSB2'           = @{ Limit = 96; Suggested = 'FNFSB2' }
    'Frogger'          = @{ Limit = 96; Suggested = 'FROGGR' }
    'H2Overdrive'      = @{ Limit = 96; Suggested = 'H2OVER' }
    'JurassicPark'     = @{ Limit = 96; Suggested = 'JURASS' }
    'SnoCross'         = @{ Limit = 96; Suggested = 'WXGSNO' }
    # Standalone case, not a Raw Thrills title but the same kind of
    # hard-coded limit -- TPUI itself shows a warning dialog for this one.
    'YugiohDT6U'       = @{ Limit = 64; Suggested = 'YUGIOH' }
}

# Builds the normalized folder-name -> path map used by the extraction
# pickers (Select-GamesInteractive, Select-GamesInteractiveCombined) and
# Invoke-AutoSync to decide whether a ZIP's game is already extracted.
# Normalization strips the .teknoparrot/.parrot/.game suffix and removes a
# space immediately before ( or [ so old- and new-convention folder names
# for the same game map to the same key (see callers' original comments).
#
# Also registers each PATH TOO LONG entry's profile Code under its Suggested
# short name's existing folder. The shared resolver can then use the DAT
# ProfileCode to recognize short-name folders such as ALIENS.teknoparrot.
function Get-StagingFolderMap {
    param([string]$installFolder)
    $map = @{}
    foreach ($dir in (Get-ChildItem -LiteralPath $installFolder -Directory -ErrorAction SilentlyContinue)) {
        $baseName = $dir.Name -replace '\.(teknoparrot|parrot|game)$', ''
        $keys = @(
            $dir.Name,
            $baseName,
            ($baseName -replace ' (?=[\[\(])', ''),
            (Get-NormalizedGameKey $baseName)
        ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
        foreach ($key in $keys) {
            if (-not $map.ContainsKey($key)) {
                $map[$key] = $dir.FullName
            } elseif ([string]$map[$key] -ine [string]$dir.FullName) {
                # A shared alias is not enough evidence to choose one game folder.
                $map[$key] = $null
            }
        }
    }
    if ($RawThrillsPathLimits) {
        foreach ($code in $RawThrillsPathLimits.Keys) {
            $suggested = $RawThrillsPathLimits[$code].Suggested
            if ($map.ContainsKey($suggested) -and -not $map.ContainsKey($code)) {
                $map[$code] = $map[$suggested]
            }
        }
    }
    return $map
}

function Test-ExtractedFolderHasContent {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    if (-not (Test-Path -LiteralPath $Path -PathType Container)) { return $false }
    $firstChild = Get-ChildItem -LiteralPath $Path -Force -ErrorAction SilentlyContinue | Select-Object -First 1
    return ($null -ne $firstChild)
}

# A ZIP name without its .teknoparrot, .parrot or .game suffix. One shared helper so every
# lookup strips the suffix the same way.
function Get-TpmZipBaseName {
    param([string]$RawZipName)
    return ($RawZipName -replace '\.(teknoparrot|parrot|game)$', '')
}

# Exact-key lookup only (no fuzzy/Dice fallback): the dat's own game names
# already normalize identically to well-formed ZIP names in practice (both
# follow the same RomVault/Eggman convention), which is why
# Resolve-RegisteredGameFolder's original exact-match design already worked
# for issue #13. A Dice-similarity fallback here was found to add no
# matching power for any confirmed case while being unable to distinguish
# two different profile codes whose normalized names happen to score high
# against the same ZIP name -- removed rather than tuned. See issue #66
# review notes.
function Get-DatEntryForZipName {
    param([string]$RawZipName, [hashtable]$DatIndex)
    if (-not $DatIndex -or $DatIndex.Count -eq 0) { return $null }
    $normZip = Get-NormalizedGameKey $RawZipName
    if (-not $DatIndex.ContainsKey($normZip)) { return $null }
    $primary = $DatIndex[$normZip]
    # Games whose names differ only by year or bracket tags share one key. The one whose full name equals the ZIP name wins.
    $alternatesProperty = $primary.PSObject.Properties['Alternates']
    if ($null -ne $alternatesProperty -and $null -ne $alternatesProperty.Value -and $alternatesProperty.Value.Count -gt 0) {
        $baseName = Get-TpmZipBaseName $RawZipName
        if ([string]$primary.OriginalName -ieq $baseName) { return $primary }
        foreach ($alternate in $alternatesProperty.Value) {
            if ([string]$alternate.OriginalName -ieq $baseName) { return $alternate }
        }
    }
    return $primary
}

# The profile codes the Eggman list names for one game folder (exact name match): the first profile, then the second one (for a
# Lindbergh game the ElfLdr2 profile that replaces the retired Lindbergh loader; for Raiden III, Raiden IV and Densha de GO the other
# profile of the same files). Only safe names are returned, resolved the way registration resolves them. Empty when the list does not
# know the folder.
function Get-TpmDatNamedProfileCodes {
    param([string]$FolderKey, [hashtable]$DatIndex, [string]$GameProfilesDir = '', [System.Collections.Generic.HashSet[string]]$ProfileSet = $null)
    if (-not $DatIndex -or $DatIndex.Count -eq 0) { return @() }
    $entry = Get-DatEntryForZipName -RawZipName $FolderKey -DatIndex $DatIndex
    if ($null -eq $entry) { return @() }
    $codes = New-Object System.Collections.Generic.List[string]
    foreach ($propertyName in @('ProfileCode', 'ProfileCode2')) {
        $property = $entry.PSObject.Properties[$propertyName]
        if ($null -eq $property -or $null -eq $property.Value) { continue }
        $code = ([string]$property.Value).Trim()
        if ($code -notmatch '^[\w-]+$') { continue }
        if ($GameProfilesDir) { $code = Resolve-ProfileCode $code $GameProfilesDir $ProfileSet }
        if (-not $codes.Contains($code)) { [void]$codes.Add($code) }
    }
    return $codes.ToArray()
}

# The file types the TeknoParrot profiles name for their game file (".exec", ".chd", ".1" and so on), read from the executable
# index, so game discovery needs no change when a new game uses a new kind of file.
function Get-TpmProfileFileExtensions {
    param([hashtable]$ProfileIndex = $null)
    $extensions = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    if ($null -ne $ProfileIndex) {
        foreach ($name in $ProfileIndex.Keys) {
            $extension = ''
            try { $extension = [System.IO.Path]::GetExtension([string]$name) } catch { $extension = '' }
            if ($extension -and $extension.Length -gt 1) { [void]$extensions.Add($extension.ToLowerInvariant()) }
        }
    }
    return @($extensions)
}

# Registers the SECOND profile the Eggman list names for a game folder (GameProfile2), once the folder's first profile was registered
# or found, but only when TeknoParrot has retired the first profile (IsDeprecated): then a Lindbergh game got only the retired Lindbergh
# profile and never its ElfLdr2 one. For other games the meaning of a second profile is not documented, so none is written. The game
# file is one of the file names the second profile itself lists (or, when it lists none, the file the list names); when neither is in
# the folder nothing is guessed and the log says so.
function Register-TpmDatSecondProfiles {
    param(
        [Parameter(Mandatory)]$Registered, [Parameter(Mandatory)]$Already, [Parameter(Mandatory)][hashtable]$SeenCodes, [Parameter(Mandatory)][hashtable]$ClaimedBy,
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$ExeFiles, [Parameter(Mandatory)][string]$InstallBase,
        [Parameter(Mandatory)][hashtable]$DatIndex, [Parameter(Mandatory)][string]$GameProfilesDir,
        [System.Collections.Generic.HashSet[string]]$ProfileSet = $null, [Parameter(Mandatory)][string]$UserProfilesDir,
        [bool]$DryRun = $false, [Parameter(Mandatory)]$MutationRecords, $BackupState = $null
    )
    $folderNames = New-Object System.Collections.Generic.List[string]
    foreach ($exeFile in $ExeFiles) {
        $relative = ([string]$exeFile.FullName).Substring($InstallBase.Length).TrimStart('\')
        $folderName = ($relative -split '\\')[0]
        if ($folderName -and -not $folderNames.Contains($folderName)) { [void]$folderNames.Add($folderName) }
    }
    foreach ($folderName in $folderNames) {
        if (Test-TpmRegistrationLedgerStopped) { break }
        $folderKey = $folderName -replace '\.(teknoparrot|parrot|game)$', ''
        $codes = @(Get-TpmDatNamedProfileCodes -FolderKey $folderKey -DatIndex $DatIndex -GameProfilesDir $GameProfilesDir -ProfileSet $ProfileSet)
        if ($codes.Count -lt 2) { continue }
        $first = [string]$codes[0]
        $second = [string]$codes[1]
        if ($second -ieq $first -or -not $SeenCodes.ContainsKey($first) -or $SeenCodes.ContainsKey($second)) { continue }
        if ([string]$ClaimedBy[$first] -ine $folderName) { continue }
        $firstTemplate = Join-Path $GameProfilesDir ($first + '.xml')
        $retired = $false
        try {
            $retiredNode = (Read-Xml $firstTemplate).GameProfile.SelectSingleNode('IsDeprecated')
            $retired = ($null -ne $retiredNode -and $retiredNode.InnerText.Trim() -ieq 'true')
        } catch { $retired = $false }
        if (-not $retired) { continue }
        $templatePath = Join-Path $GameProfilesDir ($second + '.xml')
        if (-not (Test-Path -LiteralPath $templatePath -PathType Leaf)) { Write-Log ("DatIndex (second profile): no GameProfiles template for '{0}' -- folder {1}" -f $second, $folderKey); continue }
        $folderFull = Join-Path $InstallBase $folderName
        $inFolder = @($ExeFiles | Where-Object { ([string]$_.FullName).StartsWith($folderFull + '\', [System.StringComparison]::OrdinalIgnoreCase) })
        $names = @((Get-TpmGameFileSet -ExecutableName ([string](Get-PrimaryExecutableName $templatePath))).Choices)
        $gameFile = ''
        if ($names.Count -gt 0) {
            foreach ($name in $names) {
                $hit = @($inFolder | Where-Object { $_.Name -ieq $name } | Sort-Object { ([string]$_.FullName).Length } | Select-Object -First 1)
                if ($hit.Count -gt 0) { $gameFile = [string]$hit[0].FullName; break }
            }
        } else {
            $datEntry = Get-DatEntryForZipName -RawZipName $folderKey -DatIndex $DatIndex
            $relativeExe = if ($null -ne $datEntry) { ([string]$datEntry.Executable).Trim().TrimStart('\', '/') } else { '' }
            if ($relativeExe) {
                $candidate = Join-Path $folderFull $relativeExe
                if ((Test-PathInside $candidate $folderFull) -and (Test-Path -LiteralPath $candidate -PathType Leaf)) { $gameFile = $candidate }
            }
        }
        if (-not $gameFile) { Write-Log ("DatIndex (second profile): {0} was left alone because none of its game files is in folder {1}" -f $second, $folderKey); continue }
        $SeenCodes[$second] = $true
        $ClaimedBy[$second] = $folderName
        $userProfile = Join-Path $UserProfilesDir ($second + '.xml')
        if (Test-Path -LiteralPath $userProfile) {
            if ($Already -notcontains $second) { [void]$Already.Add($second) }
            Backfill-SecondaryExecutablePath $userProfile $DryRun -RegistrationState $MutationRecords -BackupState $BackupState -UserProfilesDir $UserProfilesDir -Folder $folderName
            continue
        }
        $writeAttempted = $false; $ledgerMapping = $null; $preWriteState = $null
        try {
            $ledgerMapping = Start-TpmRegistrationMapping -Folder $folderName -Code $second -Match 'dat-second-profile' -IntendedPath $gameFile -TemplatePath $templatePath -DryRun $DryRun
            Set-TpmRegistrationGamePath -TemplatePath $templatePath -ExePath $gameFile -UserProfile $userProfile -DryRun $DryRun -BackupState $BackupState -UserProfilesDir $UserProfilesDir -MutationRecords $MutationRecords -PreWriteState ([ref]$preWriteState) -WriteAttempted ([ref]$writeAttempted)
            Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome VERIFIED
            [void]$Registered.Add([pscustomobject]@{ Code = $second; GamePath = $gameFile; DatMatch = $true; SecondProfile = $true })
            Write-Log "Registered (dat/second profile) $second -> $gameFile"
        } catch {
            $saveFailure = Resolve-TpmRegistrationSaveFailure -WriteAttempted $writeAttempted -PreState $preWriteState -Message $_.Exception.Message
            Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome FAILED -WriteAttempted $saveFailure.WriteAttempted -Reason $saveFailure.Reason
            if ($Registered.Code -notcontains $second) { [void]$MutationRecords.Failures.Add([pscustomobject]@{ Code = $second; WriteAttempted = $saveFailure.WriteAttempted; Reason = 'REGISTRATION_NOT_VERIFIED' }) }
            Write-Host "  FAILED to register $second : $_" -ForegroundColor Red
            Write-Log "Register (dat second profile) FAILED $second -- $_"
        }
    }
}

# The names one ZIP claims for its NEW folder in a run. Two ZIPs of the same game (same profile code) must not both create
# a folder. Two games that only read the same after the year and tags are removed (other hardware or version) each have
# their own profile code, so only the profile code is claimed when the ZIP name picks out exactly one of them.
function Get-TpmAutoSyncClaimKeys {
    param([string]$RawZipName, [hashtable]$DatIndex = $null)
    if ($DatIndex -and $DatIndex.Count -gt 0 -and -not [string]::IsNullOrWhiteSpace($RawZipName)) {
        $primary = $null
        $normZip = Get-NormalizedGameKey $RawZipName
        if ($DatIndex.ContainsKey($normZip)) { $primary = $DatIndex[$normZip] }
        $alternatesProperty = if ($null -ne $primary) { $primary.PSObject.Properties['Alternates'] } else { $null }
        if ($null -ne $alternatesProperty -and $null -ne $alternatesProperty.Value -and $alternatesProperty.Value.Count -gt 0) {
            $entry = Get-DatEntryForZipName -RawZipName $RawZipName -DatIndex $DatIndex
            $baseName = Get-TpmZipBaseName $RawZipName
            if ($entry -and [string]$entry.OriginalName -ieq $baseName -and [string]$entry.ProfileCode -match '^[\w-]+$') {
                return @([string]$entry.ProfileCode, (Get-NormalizedGameKey ([string]$entry.ProfileCode)))
            }
        }
    }
    return @(Get-TpmExtractedGameFolderCandidateKeys -RawZipName $RawZipName -DatIndex $DatIndex)
}

# Folder-map keys that identify a ZIP's game folder: the ZIP name, the name
# without a RetroBat suffix, the name without a space before ( or [, the
# normalized key, and the DAT profile code (plus its Raw Thrills short name).
# Shared by Resolve-ExtractedGameFolder and Resolve-TpmAutoSyncNewGameFolder so
# "existing folder" and "new folder" decisions use the same names.
function Get-TpmExtractedGameFolderCandidateKeys {
    param([string]$RawZipName, [hashtable]$DatIndex = $null)
    $candidateKeys = New-Object System.Collections.Generic.List[string]
    if ([string]::IsNullOrWhiteSpace($RawZipName)) { return @() }
    $baseName = Get-TpmZipBaseName $RawZipName
    foreach ($key in @(
        $RawZipName,
        $baseName,
        ($baseName -replace ' (?=[\[\(])'),
        (Get-NormalizedGameKey $baseName)
    )) {
        if (-not [string]::IsNullOrWhiteSpace($key) -and -not $candidateKeys.Contains($key)) { [void]$candidateKeys.Add($key) }
    }

    $datEntry = Get-DatEntryForZipName -RawZipName $RawZipName -DatIndex $DatIndex
    if ($datEntry -and $datEntry.ProfileCode -and $datEntry.ProfileCode -match '^[\w-]+$') {
        $profileCode = [string]$datEntry.ProfileCode
        foreach ($key in @($profileCode, (Get-NormalizedGameKey $profileCode))) {
            if (-not [string]::IsNullOrWhiteSpace($key) -and -not $candidateKeys.Contains($key)) { [void]$candidateKeys.Add($key) }
        }
        if ($RawThrillsPathLimits -and $RawThrillsPathLimits.ContainsKey($profileCode)) {
            $suggested = [string]$RawThrillsPathLimits[$profileCode].Suggested
            foreach ($key in @($suggested, (Get-NormalizedGameKey $suggested))) {
                if (-not [string]::IsNullOrWhiteSpace($key) -and -not $candidateKeys.Contains($key)) { [void]$candidateKeys.Add($key) }
            }
        }
    }
    return $candidateKeys.ToArray()
}

function Resolve-ExtractedGameFolder {
    param(
        [string]$RawZipName,
        [string]$InstallFolder,
        [hashtable]$FolderMap = $null,
        [hashtable]$DatIndex = $null,
        [string]$UserProfilesDir = ''
    )

    if ([string]::IsNullOrWhiteSpace($RawZipName) -or [string]::IsNullOrWhiteSpace($InstallFolder)) { return $null }
    if (-not $FolderMap) { $FolderMap = Get-StagingFolderMap $InstallFolder }

    $candidateKeys = @(Get-TpmExtractedGameFolderCandidateKeys -RawZipName $RawZipName -DatIndex $DatIndex)

    $folderMapMatch = $null
    foreach ($key in $candidateKeys) {
        if ($FolderMap.ContainsKey($key) -and (Test-ExtractedFolderHasContent $FolderMap[$key])) {
            $folderMapMatch = [string]$FolderMap[$key]
            break
        }
    }

    $registeredFolder = Resolve-RegisteredGameFolder -RawZipName $RawZipName -DatIndex $DatIndex -UserProfilesDir $UserProfilesDir -InstallFolder $InstallFolder
    $registeredFolderMatch = if (Test-ExtractedFolderHasContent $registeredFolder) { [string]$registeredFolder } else { $null }
    if ($folderMapMatch -and $registeredFolderMatch) {
        try {
            $folderMapFull = [System.IO.Path]::GetFullPath($folderMapMatch).TrimEnd([char[]]"\/")
            $registeredFolderFull = [System.IO.Path]::GetFullPath($registeredFolderMatch).TrimEnd([char[]]"\/")
            if ($folderMapFull -ine $registeredFolderFull) { return $null }
            return $registeredFolderMatch
        } catch { return $null }
    }
    if ($registeredFolderMatch) { return $registeredFolderMatch }
    if ($folderMapMatch) { return $folderMapMatch }

    # No Dice-similarity folder scan here (removed -- see issue #66 review
    # notes). The date/version/region-stripped normalized key
    # (Get-NormalizedGameKey) is already one of $candidateKeys checked
    # against $FolderMap above -- $FolderMap is keyed by that same
    # normalized form for every on-disk folder (Get-StagingFolderMap), so
    # the "harmless metadata difference" case (e.g. Battle Gear 3's
    # differing release date) is already resolved via that O(1) lookup
    # without ever reaching this point. A similarity-scored scan added no
    # matching power beyond that exact-key tier for any confirmed case,
    # while being unable to reliably distinguish two different games with a
    # long shared title prefix (e.g. numbered sequels): a real ZIP for one
    # game was found to resolve to a different, similarly-named game's
    # folder at the 0.95 threshold this used, which would have silently
    # skipped extracting the correct game. Removed rather than re-tuned.
    return $null
}

# A new game folder is named from the ZIP base name, so it must be one plain
# Windows name segment that the next run's resolver finds again unchanged. The
# same rules as for ZIP entry names apply (ConvertTo-SafeZipEntryRelativePath):
# no separators, dot segments, invalid characters, trailing dot or space, or
# reserved device names.
function Test-TpmAutoSyncNewFolderName {
    param([string]$Name)
    if ([string]::IsNullOrWhiteSpace($Name) -or $Name.IndexOfAny([char[]]'\/') -ge 0) { return $false }
    try { $safe = ConvertTo-SafeZipEntryRelativePath -EntryName $Name } catch { return $false }
    return ([string]$safe.RelativePath -ceq $Name -and -not [bool]$safe.IsDirectory)
}

# Plans first-time AutoSync extraction of a ZIP that no existing folder or
# profile identity matches. The target is a NEW direct child of the install
# folder named from the ZIP base name (plus the RetroBat suffix the caller
# passes in FolderName), the same name Resolve-ExtractedGameFolder finds on the
# next run. The ZIP's own top-level folder is deliberately not used as the
# name: the extracted tree keeps the ZIP-relative layout that the transaction
# verifies, and a name not derived from the ZIP would not be recognized again.
# Refuses (Reason set, Path $null) when any existing folder already answers to
# one of the ZIP's names, when a registered profile points at a folder in the
# install root, or when the target exists and is not an empty, non-link folder.
# Read-only; the directory transaction re-checks the target before any write.
function Resolve-TpmAutoSyncNewGameFolder {
    param(
        [Parameter(Mandatory)][string]$RawZipName,
        [Parameter(Mandatory)][string]$FolderName,
        [Parameter(Mandatory)][string]$InstallFolder,
        [hashtable]$FolderMap = $null,
        [hashtable]$DatIndex = $null,
        [string]$UserProfilesDir = '',
        # Names already claimed by a new folder planned earlier in the same run (same game, other ZIP).
        [System.Collections.Generic.HashSet[string]]$ClaimedKeys = $null
    )
    $refuse = { param([string]$Why) [pscustomobject]@{ Path = $null; Reason = $Why } }
    if (-not (Test-TpmAutoSyncNewFolderName -Name $FolderName)) {
        return (& $refuse 'the ZIP name cannot be used safely as a folder name')
    }
    try {
        $installFull = [System.IO.Path]::GetFullPath($InstallFolder).TrimEnd([char[]]"\/")
        $targetFull = [System.IO.Path]::GetFullPath((Join-Path $installFull $FolderName))
    } catch {
        return (& $refuse 'the new game folder path could not be resolved safely')
    }
    if (-not (Test-TpmAutoSyncDirectChildTarget -TargetDir $targetFull -InstallFolder $installFull) -or
        [System.IO.Path]::GetFileName($targetFull) -cne $FolderName) {
        return (& $refuse 'the new game folder would not be a direct child of the install folder')
    }
    if (-not (Test-TpmNoReparsePath -Path $targetFull)) {
        return (& $refuse 'the install folder or the new game folder failed the path safety check')
    }
    if (-not $FolderMap) { $FolderMap = Get-StagingFolderMap $installFull }
    $candidateKeys = @(Get-TpmExtractedGameFolderCandidateKeys -RawZipName $RawZipName -DatIndex $DatIndex)
    if ($ClaimedKeys) {
        foreach ($key in @(Get-TpmAutoSyncClaimKeys -RawZipName $RawZipName -DatIndex $DatIndex)) {
            if ($ClaimedKeys.Contains([string]$key)) {
                return (& $refuse 'another ZIP in this run already created a new folder for the same game')
            }
        }
    }
    foreach ($key in $candidateKeys) {
        if (-not $FolderMap.ContainsKey($key)) { continue }
        $mapped = [string]$FolderMap[$key]
        if ([string]::IsNullOrWhiteSpace($mapped)) {
            return (& $refuse 'several existing folders answer to this game name')
        }
        try { $mappedFull = [System.IO.Path]::GetFullPath($mapped).TrimEnd([char[]]"\/") } catch { $mappedFull = '' }
        if ($mappedFull -ine $targetFull.TrimEnd([char[]]"\/")) {
            return (& $refuse 'an existing folder with a matching name was not confirmed as this game')
        }
    }
    if (Resolve-RegisteredGameFolder -rawZipName $RawZipName -datIndex $DatIndex -userProfilesDir $UserProfilesDir -InstallFolder $installFull) {
        return (& $refuse 'a registered profile points to a game folder that was not confirmed')
    }
    try {
        if ([System.IO.File]::Exists($targetFull)) {
            return (& $refuse 'a file already uses the new game folder name')
        }
        if ([System.IO.Directory]::Exists($targetFull)) {
            $enumerator = [System.IO.Directory]::EnumerateFileSystemEntries($targetFull).GetEnumerator()
            try { $hasEntries = $enumerator.MoveNext() } finally { $enumerator.Dispose() }
            if ($hasEntries) {
                return (& $refuse 'an existing folder with the new game name is not empty and was not confirmed as this game')
            }
        }
    } catch {
        return (& $refuse 'the new game folder could not be checked safely')
    }
    return [pscustomobject]@{ Path = $targetFull; Reason = '' }
}

# Folder-name matching (Get-StagingFolderMap above) cannot recognize a
# folder that was renamed to anything other than a name the script itself
# would derive from the ZIP -- a hand-picked short name, a reorganized
# subfolder, anything. A registered GamePath may point to a nested executable.
# Return the containing direct child only as a candidate; ancestry alone does
# not prove archive-root alignment (a child may contain several game folders).
# AutoSync must bind the registered executable to that candidate's ZIP-relative
# path before the transaction may replace it. Paths outside or directly in the
# install root remain ambiguous and return $null.
function Resolve-RegisteredGameFolder {
    param([string]$rawZipName, [hashtable]$datIndex, [string]$userProfilesDir, [string]$InstallFolder)
    if (-not $datIndex -or $datIndex.Count -eq 0 -or -not $userProfilesDir -or [string]::IsNullOrWhiteSpace($InstallFolder)) { return $null }
    $datEntry = Get-DatEntryForZipName -RawZipName $rawZipName -DatIndex $datIndex
    if (-not $datEntry -or -not $datEntry.ProfileCode) { return $null }
    # Profile codes are purely alphanumeric; reject anything else before joining
    # into a path -- the dat is externally-sourced, untrusted input, same as the
    # ProfileCode check in Register-Games (see SECURITY.md).
    if ($datEntry.ProfileCode -notmatch '^[\w-]+$') { return $null }
    $profilePath = Join-Path $userProfilesDir "$($datEntry.ProfileCode).xml"
    if (-not (Test-Path -LiteralPath $profilePath)) { return $null }
    try {
        $doc = Read-Xml $profilePath
        $gpNode = $doc.GameProfile.SelectSingleNode("GamePath")
        if ($null -eq $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { return $null }
        $gamePath = [System.IO.Path]::GetFullPath($gpNode.InnerText.Trim())
        if (-not (Test-Path -LiteralPath $gamePath)) { return $null }
        $installRoot = [System.IO.Path]::GetFullPath($InstallFolder)
        $installRootKey = $installRoot.TrimEnd([char[]]"\/")
        if (-not (Test-PathInside -child $gamePath -parent $installRoot)) { return $null }
        $candidatePath = if (Test-Path -LiteralPath $gamePath -PathType Container) {
            $gamePath
        } else {
            [System.IO.Path]::GetDirectoryName($gamePath)
        }
        while (-not [string]::IsNullOrWhiteSpace($candidatePath)) {
            $candidatePath = [System.IO.Path]::GetFullPath($candidatePath)
            $candidateKey = $candidatePath.TrimEnd([char[]]"\/")
            if ($candidateKey -ieq $installRootKey -or
                -not (Test-PathInside -child $candidatePath -parent $installRoot)) { return $null }
            $parentPath = [System.IO.Path]::GetDirectoryName($candidatePath)
            if ([string]::IsNullOrWhiteSpace($parentPath)) { return $null }
            if ($parentPath.TrimEnd([char[]]"\/") -ieq $installRootKey) { return $candidatePath }
            $candidatePath = $parentPath
        }
        return $null
    } catch { return $null }
}

# Specific games need a SPECIFIC OLD CRC of a specific file -- a newer
# version causes a coin error or other failure. This is the opposite of
# the usual "stale dll" case TPUI already self-heals (deploying its own
# current copy), so it is never auto-fixed here -- only flagged, since
# "fixing" it in the wrong direction breaks the game.
$FileVersionPins = @{
    'BBCF'                    = @{ FileName = 'iDmacDrv32.dll'; RequiredCrc = 'F1FF8CC9' }
    'BBCP'                    = @{ FileName = 'iDmacDrv32.dll'; RequiredCrc = 'F1FF8CC9' }
