# The table above, or an empty table when a caller (a test) has not defined it.
function Get-TpmPrerequisiteTable {
    $variable = Get-Variable -Name 'EmulatorBiosRequirements' -ErrorAction SilentlyContinue
    if ($null -eq $variable -or $null -eq $variable.Value) { return @{} }
    return $variable.Value
}

# The files one table entry needs: @{ Name; RelativeDir } for each.
function Get-TpmPrerequisiteFileSpecs {
    param([Parameter(Mandatory)]$Requirement)
    $specs = New-Object System.Collections.Generic.List[object]
    if ($Requirement.Contains('Files')) {
        foreach ($file in @($Requirement['Files'])) {
            [void]$specs.Add([pscustomobject]@{ Name = [string]$file['Name']; RelativeDir = [string]$file['RelativeDir'] })
        }
    } elseif ($Requirement.Contains('RequiredFiles')) {
        foreach ($name in @($Requirement['RequiredFiles'])) {
            [void]$specs.Add([pscustomobject]@{ Name = [string]$name; RelativeDir = [string]$Requirement['RelativeDir'] })
        }
    }
    return $specs.ToArray()
}

# True when a table entry names startup files (fixed files, one file per game, or firmware the emulator unpacks). The other
# entries only say where the emulator runs from, or carry optional saved data, and are never reported as missing files.
function Test-TpmPrerequisiteNeedsFiles {
    param([Parameter(Mandatory)]$Requirement)
    return ($Requirement.Contains('Files') -or $Requirement.Contains('RequiredFiles') -or $Requirement.Contains('FilesFromProfile') -or $Requirement.Contains('InstallVia'))
}

# The emulator folder under a TeknoParrot root, or $null when that emulator is not installed there.
function Resolve-TpmPrerequisiteEmulatorDir {
    param(
        [Parameter(Mandatory)][string]$EmulatorType,
        [Parameter(Mandatory)]$Requirement,
        [Parameter(Mandatory)][string]$TeknoParrotRoot
    )
    if ($EmulatorType -ieq 'Pcsx2x6') { return (Resolve-Pcsx2Directory -TeknoParrotRoot $TeknoParrotRoot) }
    if ($Requirement.Contains('EmulatorFolders')) {
        foreach ($folder in @($Requirement['EmulatorFolders'])) {
            $candidate = Join-Path $TeknoParrotRoot ([string]$folder)
            if (Test-Path -LiteralPath $candidate -PathType Container) { return $candidate }
        }
    }
    return $null
}

# Existence-only check: the files of one table entry that are not in place under the emulator folder.
function Get-TpmMissingPrerequisiteFiles {
    param([Parameter(Mandatory)]$Requirement, [Parameter(Mandatory)][string]$EmulatorDir)
    $missing = New-Object System.Collections.Generic.List[object]
    foreach ($spec in @(Get-TpmPrerequisiteFileSpecs -Requirement $Requirement)) {
        $directory = if ([string]::IsNullOrEmpty($spec.RelativeDir)) { $EmulatorDir } else { Join-Path $EmulatorDir $spec.RelativeDir }
        $path = Join-Path $directory $spec.Name
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            [void]$missing.Add([pscustomobject]@{ Name = $spec.Name; RelativeDir = $spec.RelativeDir; Directory = $directory; Path = $path })
        }
    }
    return $missing.ToArray()
}

# EmulatorType -> list of profile codes that use it, from the registered profile files.
function Get-TpmEmulatorGameMap {
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Profiles,
        [string]$ProgressLabel = 'Compatibility BIOS profile scan'
    )
    $emulatorGames = @{}
    $scanStarted = Get-Date
    $scanCurrent = 0
    foreach ($pf in $Profiles) {
        $scanCurrent++
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label $ProgressLabel -Current $scanCurrent -Total $Profiles.Count -StartedAt $scanStarted
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) { continue }
            $etNode = $doc.GameProfile.SelectSingleNode("EmulatorType")
            if (-not $etNode) { continue }
            $emuType = $etNode.InnerText.Trim()
            if ([string]::IsNullOrWhiteSpace($emuType)) { continue }
            if (-not $emulatorGames.ContainsKey($emuType)) { $emulatorGames[$emuType] = [System.Collections.Generic.List[string]]::new() }
            $emulatorGames[$emuType].Add($pf.BaseName)
        } catch {
            Write-Log "CompatibilityWarnings: could not parse $($pf.Name) for BIOS check -- $_"
        }
    }
    Write-TpmCompactExtractionProgress -Phase 'Checking' -Label $ProgressLabel -Current $scanCurrent -Total $Profiles.Count -StartedAt $scanStarted -Complete
    return $emulatorGames
}

# One finding for one emulator, or $null when its files are all in place (or the emulator is not installed).
# Profiles (the registered profile files) are only read for a FilesFromProfile entry, to learn which files its games need.
function Get-TpmPrerequisiteWarning {
    param(
        [Parameter(Mandatory)][string]$EmulatorType,
        [Parameter(Mandatory)]$Requirement,
        [Parameter(Mandatory)][string]$TeknoParrotRoot,
        [string[]]$AffectedGames = @(),
        [object[]]$Profiles = @()
    )
    $emulatorDir = Resolve-TpmPrerequisiteEmulatorDir -EmulatorType $EmulatorType -Requirement $Requirement -TeknoParrotRoot $TeknoParrotRoot
    if (-not $emulatorDir) { return $null }  # emulator folder itself not present -- nothing to check yet
    $gameFiles = $null
    if ($Requirement.Contains('FilesFromProfile')) {
        # Only plain .zip names count: a name with a folder, a separator or another extension is not one file to copy.
        $from = $Requirement['FilesFromProfile']
        $names = New-Object System.Collections.Generic.List[string]
        $gameFiles = @{}
        foreach ($gameProfileFile in @($Profiles | Where-Object { $AffectedGames -contains $_.BaseName })) {
            try {
                $doc = Read-Xml $gameProfileFile.FullName
                $node = if ($doc.GameProfile) { $doc.GameProfile.SelectSingleNode([string]$from['Element']) } else { $null }
                $name = if ($node) { $node.InnerText.Trim() } else { '' }
                $zipName = [regex]::Match($name, '^([A-Za-z0-9_.\-]+)\.zip$')
                $fileName = if ($zipName.Success) { $zipName.Groups[1].Value.ToLowerInvariant() + [string]$from['FileSuffix'] } else { '' }
                if ($fileName -and -not ($names -contains $fileName)) { [void]$names.Add($fileName) }
                if ($fileName) { $gameFiles[[string]$gameProfileFile.BaseName] = $fileName }
            } catch { Write-Log ("Prerequisites: could not read '{0}' for its game file -- {1}" -f $gameProfileFile.Name, $_.Exception.Message) }
        }
        $Requirement = $Requirement.Clone()
        $Requirement['Files'] = @($names | Sort-Object | ForEach-Object { @{ Name = $_; RelativeDir = [string]$from['RelativeDir'] } })
    }
    $missing = @(Get-TpmMissingPrerequisiteFiles -Requirement $Requirement -EmulatorDir $emulatorDir)
    if ($missing.Count -eq 0) { return $null }
    if ($null -ne $gameFiles) {
        # Only the games whose own file is missing are affected; the others start fine.
        $missingNames = @($missing | ForEach-Object { [string]$_.Name })
        $AffectedGames = @($gameFiles.Keys | Where-Object { $missingNames -contains $gameFiles[$_] })
    }
    $label = if ($Requirement.Contains('Label')) { [string]$Requirement['Label'] } else { '' }
    if ([string]::IsNullOrWhiteSpace($label)) { $label = ('{0} firmware' -f $EmulatorType) }
    return [pscustomobject]@{
        EmulatorType  = $EmulatorType
        Label         = $label
        EmulatorDir   = $emulatorDir
        ExpectedDir   = [string]$missing[0].Directory
        MissingFiles  = @($missing | ForEach-Object { [string]$_.Name })
        MissingItems  = $missing
        AffectedGames = @($AffectedGames | Sort-Object)
        Requirement   = $Requirement
    }
}

# Library-wide check for the health report: every table entry that has missing files.
function Get-TpmMissingPrerequisites {
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Profiles,
        [Parameter(Mandatory)][string]$TeknoParrotRoot,
        [System.Collections.IList]$NotChecked = $null
    )
    $table = Get-TpmPrerequisiteTable
    $found = New-Object System.Collections.Generic.List[object]
    if ($table.Count -eq 0) { return @() }
    $map = Get-TpmEmulatorGameMap -Profiles $Profiles -ProgressLabel 'Game files profile scan'
    foreach ($emuType in @($map.Keys | Sort-Object)) {
        if (-not $table.ContainsKey($emuType) -or -not (Test-TpmPrerequisiteNeedsFiles -Requirement $table[$emuType])) { continue }
        # An emulator whose folder is not there yet cannot be checked; say so instead of letting it read as OK.
        if ($null -ne $NotChecked -and -not (Resolve-TpmPrerequisiteEmulatorDir -EmulatorType $emuType -Requirement $table[$emuType] -TeknoParrotRoot $TeknoParrotRoot)) { [void]$NotChecked.Add($emuType); continue }
        $entry = Get-TpmPrerequisiteWarning -EmulatorType $emuType -Requirement $table[$emuType] -TeknoParrotRoot $TeknoParrotRoot -AffectedGames @($map[$emuType]) -Profiles $Profiles
        if ($entry) { [void]$found.Add($entry) }
    }
    return $found.ToArray()
}

# FIX132: one plain "what this game needs" line for a registered game, from its own profile and the
# prerequisite table, or '' when nothing is known. Uses only facts proven by the profile (emulator,
# RequiresBepInEx, RequiresAdmin) and the table; never from free text.
function Get-TpmGameNeedsLine {
    param([Parameter(Mandatory)][string]$ProfilePath, [string]$SetupExe = '')
    $needs = New-Object System.Collections.Generic.List[string]
    try {
        $doc = Read-Xml $ProfilePath
        if ($doc.GameProfile) {
            $emulatorNode = $doc.GameProfile.SelectSingleNode('EmulatorType')
            $table = Get-TpmPrerequisiteTable
            if ($emulatorNode -and $table.ContainsKey($emulatorNode.InnerText.Trim()) -and (Test-TpmPrerequisiteNeedsFiles -Requirement $table[$emulatorNode.InnerText.Trim()])) {
                $requirement = $table[$emulatorNode.InnerText.Trim()]
                $count = @(Get-TpmPrerequisiteFileSpecs -Requirement $requirement).Count
                $label = if ($requirement.Contains('Label')) { [string]$requirement['Label'] } else { 'startup files' }
                if ($requirement.Contains('InstallVia') -or $requirement.Contains('FilesFromProfile')) { [void]$needs.Add($label) }
                else { [void]$needs.Add(('{0} ({1} {2})' -f $label, $count, $(if ($count -eq 1) { 'file' } else { 'files' }))) }
            }
            $bepNode = $doc.GameProfile.SelectSingleNode('RequiresBepInEx')
            if ($bepNode -and $bepNode.InnerText.Trim() -ieq 'true') { [void]$needs.Add('BepInEx installed in the game folder') }
            $adminNode = $doc.GameProfile.SelectSingleNode('RequiresAdmin')
            if ($adminNode -and $adminNode.InnerText.Trim() -ieq 'true') { [void]$needs.Add('TeknoParrotUI run as administrator') }
        }
    } catch {
        Write-Log ("Prerequisites: could not read '{0}' for its needs line -- {1}" -f $ProfilePath, $_.Exception.Message)
    }
    if (-not [string]::IsNullOrWhiteSpace($SetupExe)) { [void]$needs.Add('its own setup program run once (see Run below)') }
    if ($needs.Count -eq 0) { return '' }
    return ('What this game needs: ' + ($needs -join '; ') + '.')
}

# --- FIX132: finding and copying the missing files from the player's own collection ---------------
# The files come only from things the player already owns: the "[EMU]" archive in the Supplementary
# (or main) collection, or another TeknoParrot copy. The Eggman DAT lists each file of that archive
# with its size and hashes, so it is the proof that a found file is the right one. Nothing is
# downloaded, and a file the DAT does not list is never copied (the check cannot vouch for it).

# The "[EMU]" sets of the Eggman DAT: game name -> files (Name, Size, Crc, Md5, Sha1, Sha256).
# Reads the DAT through the existing DAT readers (the same ZIP/.dat sources the DAT index uses).
# The Supplementary DAT is read first; the large collection DAT only when that has no "[EMU]" set.
function Get-TpmEmuDatRomSets {
    param([string]$EggmanDatZip = '', [string]$DatFilePath = '', [string]$SupplementaryDatPath = '')
    $games = @{}
    try {
        if ($SupplementaryDatPath -and (Test-Path -LiteralPath $SupplementaryDatPath -PathType Leaf)) {
            [void](Build-DatIndex $SupplementaryDatPath -EmuRomSink $games -Quiet)
        }
        if ($games.Count -eq 0 -and $EggmanDatZip -and (Test-Path -LiteralPath $EggmanDatZip -PathType Leaf)) {
            [void](Build-DatIndexFromZip $EggmanDatZip '*Supplementary*_RomVault*.dat' -EmuRomSink $games -Quiet)
        }
        if ($games.Count -eq 0 -and $DatFilePath -and (Test-Path -LiteralPath $DatFilePath -PathType Leaf)) {
            [void](Build-DatIndex $DatFilePath -EmuRomSink $games -Quiet)
        }
        if ($games.Count -eq 0 -and $EggmanDatZip -and (Test-Path -LiteralPath $EggmanDatZip -PathType Leaf)) {
            [void](Build-DatIndexFromZip $EggmanDatZip '*Collection*_RomVault*.dat' -EmuRomSink $games -Quiet)
        }
    } catch {
        Write-Log "Prerequisites: the DAT could not be read for the [EMU] sets -- $_"
    }
    return [pscustomobject]@{ Games = $games; Available = ($games.Count -gt 0) }
}

# What the DAT says about one file of an "[EMU]" set: size and every listed hash.
# Found is true only when exactly one distinct description exists and it has a size and at least one hash.
function Get-TpmDatFileExpectation {
    param($DatRoms, [Parameter(Mandatory)][string]$FileName, [string]$GameName = '', [string]$GamePattern = '')
    $none = [pscustomobject]@{ Found = $false; Reason = 'The DAT does not list this file.'; GameName = ''; Length = [int64]-1; Crc = ''; Md5 = ''; Sha1 = ''; Sha256 = '' }
    if ($null -eq $DatRoms -or $null -eq $DatRoms.Games -or $DatRoms.Games.Count -eq 0) {
        $none.Reason = 'No DAT list with the [EMU] sets is loaded.'
        return $none
    }
    $candidates = @()
    if ($GameName -and $DatRoms.Games.ContainsKey($GameName)) { $candidates = @($GameName) }
    elseif ($GamePattern) { $candidates = @($DatRoms.Games.Keys | Where-Object { [string]$_ -match $GamePattern }) }
    $hits = New-Object System.Collections.Generic.List[object]
    foreach ($candidate in $candidates) {
        # foreach, not @(): on Windows PowerShell 5.1 @() around a generic List read from a hashtable throws.
        foreach ($rom in $DatRoms.Games[$candidate]) {
            $leaf = [string]$rom.Name
            $slash = $leaf.LastIndexOfAny([char[]]@('\', '/'))
            if ($slash -ge 0) { $leaf = $leaf.Substring($slash + 1) }
            if ($leaf -ieq $FileName) { [void]$hits.Add([pscustomobject]@{ Game = [string]$candidate; Rom = $rom }) }
        }
    }
    if ($hits.Count -eq 0) { return $none }
    $distinct = @($hits | ForEach-Object { ('{0}|{1}|{2}|{3}|{4}' -f $_.Rom.Size, $_.Rom.Crc, $_.Rom.Md5, $_.Rom.Sha1, $_.Rom.Sha256).ToLowerInvariant() } | Select-Object -Unique)
    if ($distinct.Count -gt 1) {
        $none.Reason = 'The DAT describes this file in more than one way.'
        return $none
    }
    $rom = $hits[0].Rom
    [int64]$length = -1
    if (-not [int64]::TryParse(([string]$rom.Size), [ref]$length)) { $length = -1 }
    $hasHash = (-not [string]::IsNullOrWhiteSpace([string]$rom.Crc)) -or (-not [string]::IsNullOrWhiteSpace([string]$rom.Md5)) -or
        (-not [string]::IsNullOrWhiteSpace([string]$rom.Sha1)) -or (-not [string]::IsNullOrWhiteSpace([string]$rom.Sha256))
    if ($length -lt 0 -or -not $hasHash) {
        $none.GameName = [string]$hits[0].Game
        $none.Reason = 'The DAT lists this file without a size or a hash.'
        return $none
    }
    return [pscustomobject]@{
        Found = $true; Reason = ''; GameName = [string]$hits[0].Game; Length = $length
        Crc = ([string]$rom.Crc).Trim(); Md5 = ([string]$rom.Md5).Trim(); Sha1 = ([string]$rom.Sha1).Trim(); Sha256 = ([string]$rom.Sha256).Trim()
    }
}

# True only when the file has exactly the size and EVERY hash the DAT lists for it.
function Test-TpmPrerequisiteFileAgainstDat {
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)]$Expectation)
    $result = [pscustomobject]@{ Matches = $false; Reason = ''; Checked = @() }
    if (-not $Expectation.Found) { $result.Reason = [string]$Expectation.Reason; return $result }
    $checked = New-Object System.Collections.Generic.List[string]
    try {
        $length = [int64](Get-Item -LiteralPath $Path -Force -ErrorAction Stop).Length
        if ($length -ne [int64]$Expectation.Length) { $result.Reason = ('size {0} does not match the DAT size {1}' -f $length, $Expectation.Length); return $result }
        [void]$checked.Add('size')
        if (-not [string]::IsNullOrWhiteSpace([string]$Expectation.Crc)) {
            $crc = (Get-Crc32 -Path $Path).PadLeft(8, '0')
            if ($crc -ine ([string]$Expectation.Crc).PadLeft(8, '0')) { $result.Reason = 'CRC32 does not match the DAT'; return $result }
            [void]$checked.Add('crc')
        }
        $hashChecks = @(
            [pscustomobject]@{ Key = 'md5'; Algorithm = 'MD5'; Expected = [string]$Expectation.Md5 }
            [pscustomobject]@{ Key = 'sha1'; Algorithm = 'SHA1'; Expected = [string]$Expectation.Sha1 }
            [pscustomobject]@{ Key = 'sha256'; Algorithm = 'SHA256'; Expected = [string]$Expectation.Sha256 }
        )
        foreach ($hashCheck in $hashChecks) {
            if ([string]::IsNullOrWhiteSpace($hashCheck.Expected)) { continue }
            $actual = (Get-FileHash -LiteralPath $Path -Algorithm $hashCheck.Algorithm -ErrorAction Stop).Hash
            if ($actual -ine $hashCheck.Expected.Trim()) { $result.Reason = ('{0} does not match the DAT' -f $hashCheck.Algorithm); return $result }
            [void]$checked.Add($hashCheck.Key)
        }
    } catch {
        $result.Reason = ('the file could not be read: {0}' -f $_.Exception.Message)
        return $result
    }
    $result.Matches = $true
    $result.Checked = $checked.ToArray()
    return $result
}

# The "[EMU]" archives of the player's own collection that hold a table entry's files.
# Looks at the top of each folder, then one folder level down when nothing was found there.
function Find-TpmPrerequisiteSourceZips {
    param([Parameter(Mandatory)][string]$Pattern, [string[]]$SearchFolders = @())
    $found = New-Object System.Collections.Generic.List[object]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($folder in @($SearchFolders | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique)) {
        if (-not (Test-Path -LiteralPath $folder -PathType Container)) { continue }
        $before = $found.Count
        try {
            foreach ($zip in @(Get-ChildItem -LiteralPath $folder -Filter '*.zip' -File -ErrorAction Stop)) {
                if ($zip.BaseName -match $Pattern -and $seen.Add($zip.FullName)) { [void]$found.Add($zip) }
            }
            if ($found.Count -eq $before) {
                foreach ($sub in @(Get-ChildItem -LiteralPath $folder -Directory -ErrorAction Stop | Select-Object -First 100)) {
                    foreach ($zip in @(Get-ChildItem -LiteralPath $sub.FullName -Filter '*.zip' -File -ErrorAction SilentlyContinue)) {
                        if ($zip.BaseName -match $Pattern -and $seen.Add($zip.FullName)) { [void]$found.Add($zip) }
                    }
                }
            }
        } catch {
            Write-Log ("Prerequisites: could not look in '{0}' -- {1}" -f $folder, $_.Exception.Message)
        }
    }
    return $found.ToArray()
}

# file leaf (lower case) -> entries of one ZIP. A member whose stored name could escape its folder is left out.
function Get-TpmZipFileEntryMap {
    param([Parameter(Mandatory)][string]$ZipPath)
    # System.IO.Compression.FileSystem is loaded once at start-up (top of this script).
    $map = @{}
    $zip = [System.IO.Compression.ZipFile]::OpenRead($ZipPath)
    try {
        # get_Entries(): the property read hides a bad member name on Windows PowerShell 5.1.
        foreach ($entry in $zip.get_Entries()) {
            if ([string]::IsNullOrEmpty($entry.Name)) { continue }
            if (Test-TpmCps3UnsafeMemberName -Name ([string]$entry.FullName)) {
                Write-Log ("Prerequisites: ignored an unsafe member name in '{0}'." -f $ZipPath)
                continue
            }
            $key = ([string]$entry.Name).ToLowerInvariant()
            if (-not $map.ContainsKey($key)) { $map[$key] = New-Object System.Collections.Generic.List[object] }
            [void]$map[$key].Add([pscustomobject]@{ FullName = [string]$entry.FullName; Length = [int64]$entry.Length })
        }
    } finally { $zip.Dispose() }
    $final = @{}
    foreach ($key in @($map.Keys)) { $final[$key] = $map[$key].ToArray() }
    return $final
}

# Read-only plan for one finding: where each missing file can come from, and what the DAT says about it.
# An item is Installable only when a source was found AND the DAT describes the file (size and a hash).
function Get-TpmPrerequisiteFixPlan {
    param(
        [Parameter(Mandatory)]$Warning,
        [string[]]$SearchFolders = @(),
        $DatRoms = $null,
        [string]$TeknoParrotRoot = '',
        [scriptblock]$OtherRootsProvider = $null
    )
    $requirement = $Warning.Requirement
    $pattern = if ($requirement -and $requirement.Contains('SourceZipPattern')) { [string]$requirement['SourceZipPattern'] } else { '' }
    $zips = @()
    if ($pattern) { $zips = @(Find-TpmPrerequisiteSourceZips -Pattern $pattern -SearchFolders $SearchFolders) }
    $zipMaps = New-Object System.Collections.Generic.List[object]
    foreach ($zip in $zips) {
        try { [void]$zipMaps.Add([pscustomobject]@{ Zip = $zip; Map = (Get-TpmZipFileEntryMap -ZipPath $zip.FullName) }) }
        catch { Write-Log ("Prerequisites: could not read '{0}' -- {1}" -f $zip.FullName, $_.Exception.Message) }
    }
    if ($requirement -and $requirement.Contains('InstallVia')) {
        # One firmware file that the emulator unpacks itself (see InstallVia in the table). The only thing to find and
        # check is that file; the marker file named under Files is what the unpacking leaves behind, not a source.
        $viaName = [string]$requirement['InstallVia']['ArchiveFileName']
        $viaItem = [pscustomobject]@{
            Name = $viaName; Destination = (Join-Path ([string]$Warning.EmulatorDir) 'dev_flash'); Source = 'None'; SourcePath = ''; EntryName = ''
            GameName = ''; Expectation = $null; Problem = ''; Installable = $false; WrongExisting = $false
        }
        foreach ($candidate in $zipMaps) {
            $viaKey = $viaName.ToLowerInvariant()
            $viaEntries = @(if ($candidate.Map.ContainsKey($viaKey)) { $candidate.Map[$viaKey] })
            if ($viaEntries.Count -eq 1) {
                $viaItem.Source = 'Archive'; $viaItem.SourcePath = [string]$candidate.Zip.FullName; $viaItem.EntryName = [string]$viaEntries[0].FullName
                $viaItem.GameName = [System.IO.Path]::GetFileNameWithoutExtension([string]$candidate.Zip.Name)
                break
            } elseif ($viaEntries.Count -gt 1) {
                $viaItem.Problem = 'More than one file with this name is inside the archive.'
                break
            }
        }
        if ($viaItem.Source -ne 'None') {
            $viaExpectation = Get-TpmDatFileExpectation -DatRoms $DatRoms -FileName $viaItem.Name -GameName $viaItem.GameName -GamePattern $pattern
            $viaItem.Expectation = $viaExpectation
            if ($viaExpectation.Found) { $viaItem.Installable = $true } else { $viaItem.Problem = [string]$viaExpectation.Reason }
        } elseif (-not $viaItem.Problem) {
            $viaItem.Problem = 'No source for this file was found.'
        }
        return [pscustomobject]@{
            Warning = $Warning
            Items = @($viaItem)
            Archives = @($zips | ForEach-Object { [string]$_.FullName })
            AnySource = ($viaItem.Source -ne 'None')
            AllInstallable = [bool]$viaItem.Installable
        }
    }
    $otherRoots = $null
    # What to put in place: every missing file, plus any file that IS there but is not the file the DAT describes
    # (only when the DAT lists it). A wrong file is never overwritten without the player's say-so (see the install).
    $targets = New-Object System.Collections.Generic.List[object]
    foreach ($missing in @($Warning.MissingItems)) {
        [void]$targets.Add([pscustomobject]@{ Name = [string]$missing.Name; RelativeDir = [string]$missing.RelativeDir; Path = [string]$missing.Path; WrongExisting = $false })
    }
    if ($requirement -and $Warning.PSObject.Properties['EmulatorDir'] -and $null -ne $DatRoms -and $DatRoms.Available) {
        $missingNames = @($Warning.MissingItems | ForEach-Object { ([string]$_.Name).ToLowerInvariant() })
        foreach ($spec in @(Get-TpmPrerequisiteFileSpecs -Requirement $requirement)) {
            if ($missingNames -contains $spec.Name.ToLowerInvariant()) { continue }
            $directory = if ([string]::IsNullOrEmpty($spec.RelativeDir)) { [string]$Warning.EmulatorDir } else { Join-Path ([string]$Warning.EmulatorDir) $spec.RelativeDir }
            $existingPath = Join-Path $directory $spec.Name
            if (-not (Test-Path -LiteralPath $existingPath -PathType Leaf)) { continue }
            $existingExpectation = Get-TpmDatFileExpectation -DatRoms $DatRoms -FileName $spec.Name -GamePattern $pattern
            if (-not $existingExpectation.Found -or [int64]$existingExpectation.Length -gt [int64]256MB) { continue }
            if (-not (Test-TpmPrerequisiteFileAgainstDat -Path $existingPath -Expectation $existingExpectation).Matches) {
                [void]$targets.Add([pscustomobject]@{ Name = [string]$spec.Name; RelativeDir = [string]$spec.RelativeDir; Path = $existingPath; WrongExisting = $true })
            }
        }
    }
    $items = New-Object System.Collections.Generic.List[object]
    foreach ($missing in $targets.ToArray()) {
        $item = [pscustomobject]@{
            Name = [string]$missing.Name; Destination = [string]$missing.Path; Source = 'None'; SourcePath = ''; EntryName = ''
            GameName = ''; Expectation = $null; Problem = ''; Installable = $false; WrongExisting = [bool]$missing.WrongExisting
        }
        foreach ($candidate in $zipMaps) {
            $entryKey = $item.Name.ToLowerInvariant()
            $entries = @(if ($candidate.Map.ContainsKey($entryKey)) { $candidate.Map[$entryKey] })
            if ($entries.Count -eq 1) {
                $item.Source = 'Archive'; $item.SourcePath = [string]$candidate.Zip.FullName; $item.EntryName = [string]$entries[0].FullName
                $item.GameName = [System.IO.Path]::GetFileNameWithoutExtension([string]$candidate.Zip.Name)
                break
            } elseif ($entries.Count -gt 1) {
                $item.Problem = 'More than one file with this name is inside the archive.'
                break
            }
        }
        if ($item.Source -eq 'None' -and -not $item.Problem -and $null -ne $OtherRootsProvider -and $requirement) {
            if ($null -eq $otherRoots) { $otherRoots = @(& $OtherRootsProvider) }
            $ownRoot = if ($TeknoParrotRoot) { [System.IO.Path]::GetFullPath($TeknoParrotRoot).TrimEnd('\', '/') } else { '' }
            foreach ($root in $otherRoots) {
                if ([string]::IsNullOrWhiteSpace([string]$root)) { continue }
                if ($ownRoot -and ([System.IO.Path]::GetFullPath([string]$root).TrimEnd('\', '/') -ieq $ownRoot)) { continue }
                $otherDir = Resolve-TpmPrerequisiteEmulatorDir -EmulatorType ([string]$Warning.EmulatorType) -Requirement $requirement -TeknoParrotRoot ([string]$root)
                if (-not $otherDir) { continue }
                $otherPath = if ([string]::IsNullOrEmpty([string]$missing.RelativeDir)) { Join-Path $otherDir $item.Name } else { Join-Path (Join-Path $otherDir ([string]$missing.RelativeDir)) $item.Name }
                if (-not (Test-Path -LiteralPath $otherPath -PathType Leaf)) { continue }
                if (-not (Test-TpmNoReparsePath -Path $otherPath)) { continue }
                $item.Source = 'OtherInstall'; $item.SourcePath = $otherPath
                break
            }
        }
        if ($item.Source -ne 'None') {
            $expectation = Get-TpmDatFileExpectation -DatRoms $DatRoms -FileName $item.Name -GameName $item.GameName -GamePattern $pattern
            $item.Expectation = $expectation
            if ($expectation.Found) { $item.Installable = $true } else { $item.Problem = [string]$expectation.Reason }
        } elseif (-not $item.Problem) {
            $item.Problem = 'No source for this file was found.'
        }
        [void]$items.Add($item)
    }
    $itemArray = $items.ToArray()
    return [pscustomobject]@{
        Warning = $Warning
        Items = $itemArray
        Archives = @($zips | ForEach-Object { [string]$_.FullName })
        AnySource = (@($itemArray | Where-Object { $_.Source -ne 'None' }).Count -gt 0)
        AllInstallable = ($itemArray.Count -gt 0 -and @($itemArray | Where-Object { -not $_.Installable }).Count -eq 0)
    }
}

# The files under a folder (0 when the folder is not there). Used to tell when the emulator has finished unpacking.
function Get-TpmFolderFileCount {
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Container)) { return 0 }
    return @(Get-ChildItem -LiteralPath $Path -Recurse -File -Force -ErrorAction SilentlyContinue).Count
}

# Firmware that the emulator unpacks itself (table entry with InstallVia): the player's own firmware file is taken
# from the collection, proven against the DAT, and handed to "<emulator> <arguments> <file>", which opens no window.
# Success is the marker file plus a file count, never the exit code (RPCS3 crashes as it closes). A half-written
# firmware folder that this run created is removed; one that was already there is never deleted.
function Invoke-TpmPrerequisiteInstallViaEmulator {
    param(
        [Parameter(Mandatory)]$Plan,
        [Parameter(Mandatory)][string]$TpRoot
    )
    $via = $Plan.Warning.Requirement['InstallVia']
    $installed = New-Object System.Collections.Generic.List[string]
    $failed = New-Object System.Collections.Generic.List[string]
    $refused = New-Object System.Collections.Generic.List[string]
    $reasons = New-Object System.Collections.Generic.List[string]
    $finish = {
        param([string]$Outcome, [string]$Reason, [string]$Summary)
        $result = [pscustomobject]@{
            PSTypeName = 'TPM.PrerequisiteInstallResult.v1'; Outcome = $Outcome; ReasonCode = $Reason; Summary = $Summary; Transaction = $null
            Installed = @($installed.ToArray()); Replaced = @(); AlreadyPresent = @(); KeptExisting = @(); Refused = @($refused.ToArray()); Failed = @($failed.ToArray())
            Reasons = @($reasons.ToArray()); BackupFolder = ''
            Complete = ($Outcome -in @('SUCCEEDED', 'NO_OP') -and $refused.Count -eq 0 -and $failed.Count -eq 0)
        }
        try { Write-Log ("Prerequisites: outcome={0} reason={1} installed={2} refused={3} failed={4}" -f $Outcome, $Reason, $installed.Count, $refused.Count, $failed.Count) } catch { }
        foreach ($line in $reasons) { try { Write-Log "Prerequisites: $line" } catch { } }
        return $result
    }
    $item = @($Plan.Items)[0]
    $flashExisted = $true
    $flash = ''
    $extractDir = ''
    $stageBase = ''
    try {
        if ([string]::IsNullOrWhiteSpace($TpRoot) -or -not (Test-Path -LiteralPath $TpRoot -PathType Container)) {
            return (& $finish 'FAILED_BEFORE_MUTATION' 'TP_ROOT_INVALID' 'The TeknoParrot folder was not found. Nothing was changed.')
        }
        $tpFull = Get-TpmFullFolderPath -Path $TpRoot
        if (-not (Test-TpmNoReparsePath -Path $tpFull)) {
            return (& $finish 'FAILED_BEFORE_MUTATION' 'TP_ROOT_UNSAFE' 'The TeknoParrot folder path is not safe to write to. Nothing was changed.')
        }
        if ($null -eq $item -or -not $item.Installable) {
            if ($item) { [void]$refused.Add($item.Name); [void]$reasons.Add(('{0}: not installed - {1}' -f $item.Name, $item.Problem)) }
            return (& $finish 'FAILED_BEFORE_MUTATION' 'NOTHING_COULD_BE_COPIED' 'The firmware file could not be checked. Nothing was changed.')
        }
        $emulatorDir = [System.IO.Path]::GetFullPath([string]$Plan.Warning.EmulatorDir)
        if (-not (Test-PathInside -child $emulatorDir -parent $tpFull) -or -not (Test-TpmNoReparsePath -Path $emulatorDir)) {
            [void]$failed.Add($item.Name); [void]$reasons.Add(('{0}: the emulator folder is outside the TeknoParrot folder or not a plain folder ({1})' -f $item.Name, $emulatorDir))
            return (& $finish 'FAILED_BEFORE_MUTATION' 'EMULATOR_FOLDER_UNSAFE' 'The emulator folder is not safe to write to. Nothing was changed.')
        }
        $program = Join-Path $emulatorDir ([string]$via['ProgramName'])
        $programInfo = if (Test-Path -LiteralPath $program -PathType Leaf) { Get-Item -LiteralPath $program -Force -ErrorAction SilentlyContinue } else { $null }
        if ($null -eq $programInfo -or (($programInfo.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0)) {
            [void]$failed.Add($item.Name); [void]$reasons.Add(('{0}: the program {1} was not found in {2}' -f $item.Name, [string]$via['ProgramName'], $emulatorDir))
            return (& $finish 'FAILED_BEFORE_MUTATION' 'PROGRAM_NOT_FOUND' 'The emulator program was not found in its folder. Nothing was changed.')
        }
        $processName = [System.IO.Path]::GetFileNameWithoutExtension([string]$via['ProgramName'])
        $running = @(Get-Process -Name $processName -ErrorAction SilentlyContinue | Where-Object { try { $_.Path -and (Test-PathInside -child ([string]$_.Path) -parent $emulatorDir) } catch { $false } })
        if ($running.Count -gt 0) {
            [void]$failed.Add($item.Name); [void]$reasons.Add(('{0}: {1} is open from {2}' -f $item.Name, $processName, $emulatorDir))
            return (& $finish 'FAILED_BEFORE_MUTATION' 'PROGRAM_RUNNING' 'The emulator is open. Close it and try again. Nothing was changed.')
        }
        $expectation = $item.Expectation
        if ([int64]$expectation.Length -gt [int64]$via['MaxArchiveBytes']) {
            [void]$refused.Add($item.Name); [void]$reasons.Add(('{0}: not installed - the DAT size {1} is unexpectedly large' -f $item.Name, $expectation.Length))
            return (& $finish 'FAILED_BEFORE_MUTATION' 'NOTHING_COULD_BE_COPIED' 'The firmware file is not the size expected. Nothing was changed.')
        }
        $layout = Get-TpmOwnedLayout -TeknoParrotRoot $tpFull
        $stageBase = Join-Path $layout.Temp 'prerequisite-stage'
        if (-not (Test-TpmNoReparsePath -Path $stageBase)) {
            return (& $finish 'FAILED_BEFORE_MUTATION' 'STAGING_UNSAFE' 'The staging folder path is not safe to write to. Nothing was changed.')
        }
        # Room for the staged copy and for the unpacked files (about the same size again). Skipped when Windows cannot say.
        foreach ($spaceCheck in @(@{ Path = $stageBase; Name = 'staging' }, @{ Path = $emulatorDir; Name = 'emulator' })) {
            try {
                $driveFree = (New-Object System.IO.DriveInfo ([System.IO.Path]::GetPathRoot([System.IO.Path]::GetFullPath([string]$spaceCheck.Path)))).AvailableFreeSpace
                if ($driveFree -lt (2 * [int64]$expectation.Length)) {
                    [void]$failed.Add($item.Name); [void]$reasons.Add(('{0}: not enough free space on the {1} drive ({2} bytes free)' -f $item.Name, $spaceCheck.Name, $driveFree))
                    return (& $finish 'FAILED_BEFORE_MUTATION' 'NOT_ENOUGH_SPACE' 'There is not enough free space on the drive. Nothing was changed.')
                }
            } catch { }
        }
        $extractDir = Join-Path $stageBase ('extract-' + [guid]::NewGuid().ToString('N'))
        [void][System.IO.Directory]::CreateDirectory($extractDir)
        $stagePath = Join-Path $extractDir ([string]$via['ArchiveFileName'])
        $zip = [System.IO.Compression.ZipFile]::OpenRead($item.SourcePath)
        try {
            $entry = $zip.GetEntry([string]$item.EntryName)
            if ($null -eq $entry -or [int64]$entry.Length -ne [int64]$expectation.Length) {
                [void]$refused.Add($item.Name); [void]$reasons.Add(('{0}: not installed - the file inside {1} is not the size the DAT lists' -f $item.Name, $item.SourcePath))
                return (& $finish 'FAILED_BEFORE_MUTATION' 'NOTHING_COULD_BE_COPIED' 'The firmware file is not the file expected. Nothing was changed.')
            }
            $in = $entry.Open()
            $out = $null
            try {
                $out = New-Object System.IO.FileStream($stagePath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None, 65536)
                $buffer = New-Object byte[] 65536
                [int64]$total = 0
                while (($read = $in.Read($buffer, 0, $buffer.Length)) -gt 0) {
                    $total += $read
                    if ($total -gt [int64]$expectation.Length) { break }
                    $out.Write($buffer, 0, $read)
                }
            } finally { if ($out) { $out.Dispose() }; $in.Dispose() }
        } finally { $zip.Dispose() }
        $check = Test-TpmPrerequisiteFileAgainstDat -Path $stagePath -Expectation $expectation
        if (-not $check.Matches) {
            [void]$refused.Add($item.Name); [void]$reasons.Add(('{0}: not installed - the file from {1} is not the file the DAT lists ({2})' -f $item.Name, $item.SourcePath, $check.Reason))
            return (& $finish 'FAILED_BEFORE_MUTATION' 'NOTHING_COULD_BE_COPIED' 'The firmware file is not the file expected. Nothing was changed.')
        }
        $flash = Join-Path $emulatorDir 'dev_flash'
        $flashExisted = Test-Path -LiteralPath $flash
        if ($flashExisted -and -not (Test-TpmNoReparsePath -Path $flash)) {
            [void]$failed.Add($item.Name); [void]$reasons.Add(('{0}: {1} is not a plain folder' -f $item.Name, $flash))
            return (& $finish 'FAILED_BEFORE_MUTATION' 'EMULATOR_FOLDER_UNSAFE' 'The firmware folder is not safe to write to. Nothing was changed.')
        }
        $markerSpec = @(Get-TpmPrerequisiteFileSpecs -Requirement $Plan.Warning.Requirement)[0]
        $marker = Join-Path (Join-Path $emulatorDir $markerSpec.RelativeDir) $markerSpec.Name
        $arguments = @($via['ProgramArguments']) + @(('"{0}"' -f $stagePath))
        Write-Log ("Prerequisites: starting {0} {1}" -f $programInfo.FullName, ($arguments -join ' '))
        $started = Get-Date
        $process = Start-Process -FilePath $programInfo.FullName -ArgumentList $arguments -WorkingDirectory $emulatorDir -WindowStyle Hidden -PassThru
        $minFiles = [int]$via['MinFileCount']
        $deadline = $started.AddMinutes([double]$via['MaxMinutes'])
        $lastCount = -1
        $stable = 0
        $count = 0
        while ((Get-Date) -lt $deadline) {
            Start-Sleep -Milliseconds 1500
            $count = Get-TpmFolderFileCount -Path $flash
            $markerThere = Test-Path -LiteralPath $marker -PathType Leaf
            $exited = $process.HasExited
            if ($markerThere -and $count -ge $minFiles) {
                if ($count -eq $lastCount) { $stable++ } else { $stable = 0 }
                if ($stable -ge 2 -or $exited) { break }
            } elseif ($exited) { break }
            $lastCount = $count
        }
        $timedOut = -not $process.HasExited
        if ($timedOut) { try { Stop-Process -Id $process.Id -Force -ErrorAction Stop } catch { } }
        else { try { Write-Log ("Prerequisites: {0} closed with code {1} (a crash on close is known and does not matter)" -f $processName, $process.ExitCode) } catch { } }
        $count = Get-TpmFolderFileCount -Path $flash
        if ((Test-Path -LiteralPath $marker -PathType Leaf) -and $count -ge $minFiles) {
            [void]$installed.Add($item.Name)
            [void]$reasons.Add(('{0}: unpacked {1} files in {2} s' -f $item.Name, $count, [math]::Round(((Get-Date) - $started).TotalSeconds, 1)))
            return (& $finish 'SUCCEEDED' 'FIRMWARE_INSTALLED' 'The firmware was installed and checked.')
        }
        [void]$failed.Add($item.Name)
        [void]$reasons.Add(('{0}: the emulator {1}; marker present: {2}; files found: {3} (at least {4} needed)' -f $item.Name, $(if ($timedOut) { 'did not finish in time' } else { 'stopped early' }), (Test-Path -LiteralPath $marker -PathType Leaf), $count, $minFiles))
        if (-not $flashExisted -and (Test-Path -LiteralPath $flash)) {
            try { Remove-Item -LiteralPath $flash -Recurse -Force -ErrorAction Stop; [void]$reasons.Add('The half-finished firmware folder that this run created was removed.') }
            catch { [void]$reasons.Add(('The half-finished firmware folder could not be removed: {0}' -f $_.Exception.Message)) }
        } elseif ($flashExisted) { [void]$reasons.Add('The firmware folder was already there, so it was left as it is.') }
        return (& $finish 'FAILED_AFTER_MUTATION' 'FIRMWARE_INSTALL_INCOMPLETE' 'The firmware did not finish installing.')
    } catch {
        [void]$failed.Add([string]$item.Name)
        [void]$reasons.Add(('install stopped -- {0}' -f $_.Exception.Message))
        if (-not $flashExisted -and $flash -and (Test-Path -LiteralPath $flash)) { try { Remove-Item -LiteralPath $flash -Recurse -Force -ErrorAction Stop } catch { } }
        return (& $finish 'FAILED_BEFORE_MUTATION' 'PREREQUISITE_INSTALL_ERROR' 'The firmware could not be installed.')
    } finally {
        try {
            if ($extractDir -and (Test-Path -LiteralPath $extractDir)) { Remove-Item -LiteralPath $extractDir -Recurse -Force -ErrorAction Stop }
            if ($stageBase -and (Test-Path -LiteralPath $stageBase) -and @(Get-ChildItem -LiteralPath $stageBase -Force -ErrorAction Stop).Count -eq 0) { Remove-Item -LiteralPath $stageBase -Force -ErrorAction Stop }
        } catch {
            try { Write-Log ("Prerequisites: staging cleanup incomplete: {0}" -f $_.Exception.Message) } catch { }
        }
    }
}

# Copies the files of a plan into place. Every file is staged, checked against the DAT (size and every
# listed hash) and only then promoted through the shared file transaction (which keeps a recovery copy and
# puts everything back if a step fails). A different file already in the way is kept unless its name is in
# ReplaceNames; a replaced file is first copied to <TeknoParrot root>\TeknoParrotManager\Backups\Prerequisites.
function Invoke-TpmPrerequisiteInstall {
    param(
        [Parameter(Mandatory)]$Plan,
        [Parameter(Mandatory)][string]$TpRoot,
        [string[]]$ReplaceNames = @()
    )
    if ($Plan.Warning -and $Plan.Warning.Requirement -and $Plan.Warning.Requirement.Contains('InstallVia')) {
        return (Invoke-TpmPrerequisiteInstallViaEmulator -Plan $Plan -TpRoot $TpRoot)
    }
    $lists = [ordered]@{
        Installed = New-Object System.Collections.Generic.List[string]
        Replaced = New-Object System.Collections.Generic.List[string]
        AlreadyPresent = New-Object System.Collections.Generic.List[string]
        KeptExisting = New-Object System.Collections.Generic.List[string]
        Refused = New-Object System.Collections.Generic.List[string]
        Failed = New-Object System.Collections.Generic.List[string]
    }
    $reasons = New-Object System.Collections.Generic.List[string]
    $finish = {
        param([string]$Outcome, [string]$Reason, [string]$Summary, $Transaction = $null)
        $out = [ordered]@{ PSTypeName = 'TPM.PrerequisiteInstallResult.v1'; Outcome = $Outcome; ReasonCode = $Reason; Summary = $Summary; Transaction = $Transaction }
        foreach ($key in $lists.Keys) { $out[$key] = @($lists[$key].ToArray()) }
        $out['Reasons'] = @($reasons.ToArray())
        $out['BackupFolder'] = $backupFolderUsed
        $out['Complete'] = ($Outcome -in @('SUCCEEDED', 'NO_OP') -and $lists.Refused.Count -eq 0 -and $lists.Failed.Count -eq 0 -and $lists.KeptExisting.Count -eq 0)
        $counts = (@($lists.Keys | ForEach-Object { '{0}={1}' -f $_.ToLowerInvariant(), $lists[$_].Count }) -join ' ')
        try { Write-Log "Prerequisites: outcome=$Outcome reason=$Reason $counts" } catch { }
        foreach ($line in $reasons) { try { Write-Log "Prerequisites: $line" } catch { } }
        return [pscustomobject]$out
    }
    $backupFolderUsed = ''
    if ([string]::IsNullOrWhiteSpace($TpRoot) -or -not (Test-Path -LiteralPath $TpRoot -PathType Container)) {
        return (& $finish 'FAILED_BEFORE_MUTATION' 'TP_ROOT_INVALID' 'The TeknoParrot folder was not found. Nothing was changed.')
    }
    $tpFull = Get-TpmFullFolderPath -Path $TpRoot
    if (-not (Test-TpmNoReparsePath -Path $tpFull)) {
        return (& $finish 'FAILED_BEFORE_MUTATION' 'TP_ROOT_UNSAFE' 'The TeknoParrot folder path is not safe to write to. Nothing was changed.')
    }
    $layout = Get-TpmOwnedLayout -TeknoParrotRoot $tpFull
    $stageBase = Join-Path $layout.Temp 'prerequisite-stage'
    if (-not (Test-TpmNoReparsePath -Path $stageBase)) {
        return (& $finish 'FAILED_BEFORE_MUTATION' 'STAGING_UNSAFE' 'The staging folder path is not safe to write to. Nothing was changed.')
    }
    $maxBytes = [int64]256MB
    $extractDir = Join-Path $stageBase ('extract-' + [guid]::NewGuid().ToString('N'))
    $openZips = @{}
    try {
        [void][System.IO.Directory]::CreateDirectory($extractDir)
        $operations = New-Object System.Collections.Generic.List[object]
        $index = 0
        foreach ($item in @($Plan.Items)) {
            $index++
            if (-not $item.Installable) {
                [void]$lists.Refused.Add($item.Name); [void]$reasons.Add(('{0}: not copied - {1}' -f $item.Name, $item.Problem))
                continue
            }
            $expectation = $item.Expectation
            $destination = [System.IO.Path]::GetFullPath([string]$item.Destination)
            if (-not (Test-PathInside -child $destination -parent $tpFull)) {
                [void]$lists.Refused.Add($item.Name); [void]$reasons.Add(('{0}: not copied - the destination is outside the TeknoParrot folder ({1})' -f $item.Name, $destination))
                continue
            }
            if ([int64]$expectation.Length -gt $maxBytes) {
                [void]$lists.Refused.Add($item.Name); [void]$reasons.Add(('{0}: not copied - the DAT size {1} is unexpectedly large for a startup file' -f $item.Name, $expectation.Length))
                continue
            }
            $existing = $null
            if (Test-Path -LiteralPath $destination) {
                try { $existing = Get-Item -LiteralPath $destination -Force -ErrorAction Stop } catch { $existing = $null }
                if ($null -eq $existing -or $existing.PSIsContainer -or (($existing.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0)) {
                    [void]$lists.Failed.Add($item.Name); [void]$reasons.Add(('{0}: not copied - something that is not a plain file is at {1}' -f $item.Name, $destination))
                    continue
                }
            }
            $stagePath = Join-Path $extractDir ('{0:0000}.bin' -f $index)
            try {
                if ($item.Source -eq 'Archive') {
                    if (-not $openZips.ContainsKey($item.SourcePath)) { $openZips[$item.SourcePath] = [System.IO.Compression.ZipFile]::OpenRead($item.SourcePath) }
                    $entry = $openZips[$item.SourcePath].GetEntry([string]$item.EntryName)
                    if ($null -eq $entry -or [int64]$entry.Length -ne [int64]$expectation.Length) {
                        [void]$lists.Refused.Add($item.Name); [void]$reasons.Add(('{0}: not copied - the file inside {1} is not the size the DAT lists' -f $item.Name, $item.SourcePath))
                        continue
                    }
                    $in = $entry.Open()
                    $out = $null
                    try {
                        $out = New-Object System.IO.FileStream($stagePath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None, 65536)
                        $buffer = New-Object byte[] 65536
                        [int64]$total = 0
                        while (($read = $in.Read($buffer, 0, $buffer.Length)) -gt 0) {
                            $total += $read
                            if ($total -gt [int64]$expectation.Length) { break }
                            $out.Write($buffer, 0, $read)
                        }
                    } finally { if ($out) { $out.Dispose() }; $in.Dispose() }
                } else {
                    $sourceInfo = Get-Item -LiteralPath $item.SourcePath -Force -ErrorAction Stop
                    if ($sourceInfo.PSIsContainer -or (($sourceInfo.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) -or [int64]$sourceInfo.Length -ne [int64]$expectation.Length) {
                        [void]$lists.Refused.Add($item.Name); [void]$reasons.Add(('{0}: not copied - {1} is not the size the DAT lists' -f $item.Name, $item.SourcePath))
                        continue
                    }
                    Copy-Item -LiteralPath $item.SourcePath -Destination $stagePath -ErrorAction Stop
                }
            } catch {
                [void]$lists.Failed.Add($item.Name); [void]$reasons.Add(('{0}: could not be read from {1} - {2}' -f $item.Name, $item.SourcePath, $_.Exception.Message))
                continue
            }
            $check = Test-TpmPrerequisiteFileAgainstDat -Path $stagePath -Expectation $expectation
            if (-not $check.Matches) {
                Remove-Item -LiteralPath $stagePath -Force -ErrorAction SilentlyContinue
                [void]$lists.Refused.Add($item.Name); [void]$reasons.Add(('{0}: not copied - the file from {1} is not the file the DAT lists ({2})' -f $item.Name, $item.SourcePath, $check.Reason))
                continue
            }
            $sha = Get-TpmAutoSyncSha256 -Path $stagePath
            $kind = 'ADD'
            $existingHash = $null
            if ($existing) {
                $existingHash = Get-TpmAutoSyncSha256 -Path $existing.FullName
                if ($existingHash -ieq $sha) { [void]$lists.AlreadyPresent.Add($item.Name); continue }
                if (@($ReplaceNames | Where-Object { $_ -ieq $item.Name }).Count -eq 0) {
                    [void]$lists.KeptExisting.Add($item.Name); [void]$reasons.Add(('{0}: a different file is already at {1}; it was kept' -f $item.Name, $destination))
                    continue
                }
                if (-not $backupFolderUsed) {
                    $backupParent = Join-Path (Join-Path $layout.Backups 'Prerequisites') ((Get-Date).ToString('yyyy-MM-dd_HH-mm-ss_fff', [System.Globalization.CultureInfo]::InvariantCulture) + '_' + [guid]::NewGuid().ToString('N').Substring(0, 8))
                    if (-not (Test-TpmNoReparsePath -Path $backupParent)) {
                        [void]$lists.Failed.Add($item.Name); [void]$reasons.Add(('{0}: no safe place for a backup copy, so the existing file was kept' -f $item.Name))
                        continue
                    }
                    [void][System.IO.Directory]::CreateDirectory($backupParent)
                    $backupFolderUsed = $backupParent
                }
                $backupPath = Join-Path $backupFolderUsed ('{0:0000}-{1}' -f $index, $item.Name)
                Copy-Item -LiteralPath $existing.FullName -Destination $backupPath -ErrorAction Stop
                if ((Get-TpmAutoSyncSha256 -Path $backupPath) -ine $existingHash) {
                    [void]$lists.Failed.Add($item.Name); [void]$reasons.Add(('{0}: the backup copy could not be verified, so the existing file was kept' -f $item.Name))
                    continue
                }
                $kind = 'REPLACE'
            }
            $operation = [ordered]@{ ItemId = $item.Name; Operation = $kind; SourcePath = $stagePath; DestinationPath = $destination; RootPath = $tpFull; ExpectedSourceHash = $sha; ExpectedFinalHash = $sha }
            if ($kind -eq 'REPLACE') { $operation['ExpectedDestinationHash'] = $existingHash }
            [void]$operations.Add([pscustomobject]$operation)
        }
        if ($operations.Count -eq 0) {
            $onlyPresent = ($lists.AlreadyPresent.Count -gt 0 -and $lists.Refused.Count -eq 0 -and $lists.Failed.Count -eq 0 -and $lists.KeptExisting.Count -eq 0)
            if ($onlyPresent) { return (& $finish 'NO_OP' 'NO_CHANGES_NEEDED' 'The files were already in place. Nothing was changed.') }
            $why = if ($lists.KeptExisting.Count -gt 0) { 'DIFFERENT_FILE_EXISTS' } else { 'NOTHING_COULD_BE_COPIED' }
            return (& $finish 'FAILED_BEFORE_MUTATION' $why 'No file was copied. Nothing was changed.')
        }
        [void][System.IO.Directory]::CreateDirectory($stageBase)
        $transaction = Invoke-TpmTransactionalFileBatch `
            -WorkflowKey 'Prerequisites' -OperationKey 'InstallStartupFiles' `
            -Operations $operations.ToArray() -StagingDir $stageBase `
            -Summary 'The startup files were not copied.' `
            -SuccessSummary 'The startup files were copied and checked.' `
            -NoOpSummary 'Everything already matches. Nothing was changed.' `
            -ReasonCode 'PREREQUISITE_FILE_TRANSACTION_FAILED'
        if ([string]$transaction.Outcome -eq 'SUCCEEDED') {
            foreach ($operation in $operations) {
                if ($operation.Operation -eq 'ADD') { [void]$lists.Installed.Add($operation.ItemId) } else { [void]$lists.Replaced.Add($operation.ItemId) }
            }
        }
        return (& $finish ([string]$transaction.Outcome) ([string]$transaction.ReasonCode) ([string]$transaction.Summary) $transaction)
    } catch {
        try { Write-Log ("Prerequisites: install stopped -- {0}" -f $_.Exception.Message) } catch { }
        return (& $finish 'FAILED_BEFORE_MUTATION' 'PREREQUISITE_INSTALL_ERROR' 'The files could not be copied. Nothing was changed.')
    } finally {
        foreach ($z in @($openZips.Values)) { try { $z.Dispose() } catch { } }
        try {
            if (Test-Path -LiteralPath $extractDir) { Remove-Item -LiteralPath $extractDir -Recurse -Force -ErrorAction Stop }
            if ((Test-Path -LiteralPath $stageBase) -and @(Get-ChildItem -LiteralPath $stageBase -Force -ErrorAction Stop).Count -eq 0) { Remove-Item -LiteralPath $stageBase -Force -ErrorAction Stop }
        } catch {
            try { Write-Log ("Prerequisites: staging cleanup incomplete: {0}" -f $_.Exception.Message) } catch { }
        }
    }
}

# --- FIX132: what the player sees -----------------------------------------------------------------
# Plain words on the screen (no file names, paths, hashes or archive names); the same facts, with the
# names and paths, are the Details lines and always go to the log.

# The folder the Open folder button opens: the expected folder, or the nearest folder above it that exists.
function Get-TpmPrerequisiteOpenFolder {
    param([Parameter(Mandatory)]$Warning)
    $candidate = [string]$Warning.ExpectedDir
    while (-not [string]::IsNullOrWhiteSpace($candidate) -and -not (Test-Path -LiteralPath $candidate -PathType Container)) {
        $parent = Split-Path -Parent $candidate
        if ([string]::IsNullOrWhiteSpace($parent) -or $parent -eq $candidate) { return '' }
        $candidate = $parent
    }
    return $candidate
}

# @{ Heading; Plain; Details } for one finding. Plan is optional (the saved action report has none).
function Get-TpmPrerequisiteScreenLines {
    param([Parameter(Mandatory)]$Warning, $Plan = $null)
    $label = if ($Warning.PSObject.Properties['Label'] -and -not [string]::IsNullOrWhiteSpace([string]$Warning.Label)) { [string]$Warning.Label } else { ('{0} firmware' -f [string]$Warning.EmulatorType) }
    $games = @($Warning.AffectedGames)
    $fileCount = @($Warning.MissingFiles).Count
    $plain = New-Object System.Collections.Generic.List[string]
    $details = New-Object System.Collections.Generic.List[string]
    [void]$plain.Add(('{0} is missing, so {1} will not start: {2}.' -f $label, $(if ($games.Count -eq 1) { 'this game' } else { 'these games' }), (Format-TpmNameList -Names $games -Limit 5)))
    if ($null -ne $Plan -and @($Plan.Items | Where-Object { $_.WrongExisting }).Count -gt 0) {
        [void]$plain.Add('A file that is already in the folder is not the file the list of known files describes. TeknoParrot Manager will only replace it if you say so, and it saves a backup copy first.')
    }
    $viaEmulator = ($null -ne $Plan -and $Warning.PSObject.Properties['Requirement'] -and $Warning.Requirement -and $Warning.Requirement.Contains('InstallVia'))
    if ($viaEmulator -and $Plan.AllInstallable) {
        [void]$plain.Add('TeknoParrot Manager found your firmware file in your own game collection.')
        [void]$plain.Add('Next step: answer Y to install it. This takes about a minute and no window opens. TeknoParrot Manager checks the file against the list of known files first, and checks the result afterward.')
    } elseif ($null -ne $Plan -and $Plan.AllInstallable) {
        [void]$plain.Add('TeknoParrot Manager found the missing files in your own game collection.')
        [void]$plain.Add('Next step: answer Y to copy them into place. TeknoParrot Manager checks every file against the list of known files first.')
    } elseif ($null -ne $Plan -and $Plan.AnySource) {
        $noDatList = @($Plan.Items | Where-Object { $_.Source -ne 'None' -and -not $_.Installable -and [string]$_.Problem -like 'No DAT list*' }).Count
        $notFound = @($Plan.Items | Where-Object { $_.Source -eq 'None' }).Count
        if ($noDatList -gt 0) {
            [void]$plain.Add('TeknoParrot Manager found some of the files, but it cannot prove they are the right ones, so it will not copy them.')
            [void]$plain.Add('Next step: start TeknoParrot Manager again and let it get the DAT list (the list of known files) when it asks.')
        } elseif ($notFound -gt 0) {
            [void]$plain.Add('TeknoParrot Manager found some of the files, but not all of them, so it will not copy any yet.')
            [void]$plain.Add($(if ($viaEmulator) { 'Next step: put the PlayStation 3 firmware archive in your own game collection (the Supplementary or main ZIP folder), then run TeknoParrot Manager again.' } else { 'Next step: press O to open the folder, then put the missing files in your game collection or in that folder, and run TeknoParrot Manager again.' }))
        } else {
            [void]$plain.Add('TeknoParrot Manager found the files, but the list of known files does not describe them well enough to check them, so it will not copy them.')
            [void]$plain.Add('Next step: press D to see what is wrong with each file.')
        }
    } elseif ($null -eq $Plan) {
        [void]$plain.Add($(if ($viaEmulator) { 'Next step: run TeknoParrot Manager again. If it cannot find the PlayStation 3 firmware archive, put it in your own game collection (the Supplementary or main ZIP folder). TeknoParrot Manager never downloads firmware.' } elseif ($Warning.PSObject.Properties['Requirement'] -and $Warning.Requirement -and $Warning.Requirement.Contains('FilesFromProfile')) { 'Next step: run TeknoParrot Manager again and answer Y when it offers to copy the files. If it cannot find them, put the "[EMU] Play! working arcadedefs" archive in your own game collection (the Supplementary or main ZIP folder). TeknoParrot Manager never downloads these files.' } else { 'Next step: run TeknoParrot Manager again and answer Y when it offers to copy the files from your own game collection. If it cannot find them, put them in the folder named under Details. TeknoParrot Manager never downloads firmware.' }))
    } else {
        [void]$plain.Add(('TeknoParrot Manager did not find {0} in your game collection.' -f $(if ($fileCount -eq 1) { 'the file ' + [string]@($Warning.MissingFiles)[0] } else { 'the files' })))
        [void]$plain.Add($(if ($viaEmulator) { 'Next step: put the PlayStation 3 firmware archive (the "[EMU] Sony PlayStation 3 Firmware" ZIP) in your own game collection (the Supplementary or main ZIP folder), then run TeknoParrot Manager again. It comes from your own copy. TeknoParrot Manager never downloads firmware.' } elseif ($Warning.PSObject.Properties['Requirement'] -and $Warning.Requirement -and $Warning.Requirement.Contains('FilesFromProfile')) { 'Next step: put the "[EMU] Play! working arcadedefs" archive in your own game collection (the Supplementary or main ZIP folder), then run TeknoParrot Manager again. TeknoParrot Manager never downloads these files.' } else { 'Next step: press O to open the folder, then put the missing files in it. They come from your own copy (the TeknoParrot Supplementary collection, or a dump of a console you own). TeknoParrot Manager never downloads firmware.' }))
    }
    [void]$details.Add(('Emulator: {0}' -f [string]$Warning.EmulatorType))
    [void]$details.Add(('Games: {0}' -f ($games -join ', ')))
    if ($Warning.PSObject.Properties['MissingItems']) {
        foreach ($missing in @($Warning.MissingItems)) { [void]$details.Add(('Missing file: {0} (expected at {1})' -f $missing.Name, $missing.Path)) }
    } else {
        [void]$details.Add(('Expected folder: {0}' -f [string]$Warning.ExpectedDir))
        [void]$details.Add(('Missing files: {0}' -f (@($Warning.MissingFiles) -join ', ')))
    }
    if ($null -ne $Plan) {
        foreach ($archive in @($Plan.Archives)) { [void]$details.Add(('Archive in your collection: {0}' -f $archive)) }
        foreach ($item in @($Plan.Items)) {
            if ($item.Installable) {
                [void]$details.Add(('{0}: {1}found in {2} ({3}); size {4}; the DAT lists it, so it can be checked' -f $item.Name, $(if ($item.WrongExisting) { 'the file already there does not match the DAT; a matching copy was ' } else { '' }), $item.SourcePath, $item.Source, $item.Expectation.Length))
            } else {
                [void]$details.Add(('{0}: {1}' -f $item.Name, $item.Problem))
            }
        }
    }
    return [pscustomobject]@{ Heading = ('{0} IS MISSING' -f $label.ToUpperInvariant()); Plain = $plain.ToArray(); Details = $details.ToArray() }
}

# Asks ONCE for the player's Supplementary game collection folder when no folder that works is saved, and saves the answer
# (the same saved setting the AutoSync step uses), so it is never asked again. Returns the folder, or '' when nothing was asked or
# the player skipped. A skip is only remembered for this run. Nothing is downloaded and nothing is changed by this question.
function Request-TpmSupplementaryFolder {
    $saved = [string]$script:zipSourceSupplementary
    if (-not [string]::IsNullOrWhiteSpace($saved) -and (Test-Path -LiteralPath $saved -PathType Container)) { return '' }
    if ($script:TpmSupplementaryFolderAsked) { return '' }
    $script:TpmSupplementaryFolderAsked = $true
    Write-Host ''
    Write-Host '  WHERE ARE YOUR STARTUP FILES?' -ForegroundColor Cyan
    Write-Host '  ----------------------------------------------------------' -ForegroundColor DarkGray
    if (-not [string]::IsNullOrWhiteSpace($saved)) { Write-TpmText -Text ('Your saved Supplementary folder was not found: {0}' -f $saved) -Color Yellow -Indent 2 }
    Write-TpmText -Text 'Some games need startup files (firmware) that TeknoParrot Manager did not find in your saved folders.' -Color DarkCyan -Indent 2
    Write-TpmText -Text 'If you have your own Supplementary game collection, choose that folder now. TeknoParrot Manager looks through it, checks every file against the list of known files, and asks before it installs anything. It never downloads anything.' -Color DarkCyan -Indent 2
    Write-TpmText -Text 'The folder is saved, so you are not asked again. No folder? Press Enter to skip.' -Color DarkCyan -Indent 2
    $answer = ([string](Read-PathWithBrowse -Prompt '  Supplementary folder (or press Enter to skip)' -Mode Folder)).Trim().Trim('"')
    if ([string]::IsNullOrWhiteSpace($answer)) {
        Write-Host '  Skipped. Nothing was changed.' -ForegroundColor DarkGray
        Write-Log 'Prerequisites: no Supplementary folder chosen.'
        return ''
    }
    if (-not (Test-Path -LiteralPath $answer -PathType Container)) {
        Write-Host '  That folder was not found, so it was skipped. Nothing was changed.' -ForegroundColor Yellow
        Write-Log ('Prerequisites: the Supplementary folder was not found at {0}; skipped.' -f $answer)
        return ''
    }
    $script:zipSourceSupplementary = $answer
    Write-Log ('Config: supplementary ZIP source set to {0} (asked for startup files).' -f $answer)
    if (-not (Save-Config)) {
        Write-Host '  The folder could not be saved, so TeknoParrot Manager may ask again' -ForegroundColor Yellow
        Write-Host '  next time.' -ForegroundColor Yellow
    }
    return $answer
}

# The per-package report lines for one finding: which folders were searched, then what was found, what is missing (exact names and
# where each belongs) and what cannot be checked. With an Install result it reports what happened instead: installed, already
# matching, kept (a different file of the player's), invalid (not the file the DAT lists) and not finished.
function Get-TpmPrerequisiteReportLines {
    param([Parameter(Mandatory)]$Warning, [Parameter(Mandatory)]$Plan, [string[]]$SearchFolders = @(), $Install = $null)
    $lines = New-Object System.Collections.Generic.List[string]
    if ($null -eq $Install) {
        $searched = @($SearchFolders | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique | ForEach-Object { if (Test-Path -LiteralPath $_ -PathType Container) { [string]$_ } else { ('{0} (folder not found)' -f $_) } })
        [void]$lines.Add($(if ($searched.Count -gt 0) { 'Folders searched: ' + ($searched -join '; ') } else { 'Folders searched: none. No collection folder is saved.' }))
        $items = @($Plan.Items)
        $ready = @($items | Where-Object { $_.Installable -and -not $_.WrongExisting } | ForEach-Object { [string]$_.Name })
        $differs = @($items | Where-Object { $_.Installable -and $_.WrongExisting } | ForEach-Object { [string]$_.Name })
        $takenNames = @($items | ForEach-Object { ([string]$_.Name).ToLowerInvariant() }) + @($Warning.MissingFiles | ForEach-Object { ([string]$_).ToLowerInvariant() })
        $inPlace = @(Get-TpmPrerequisiteFileSpecs -Requirement $Warning.Requirement | Where-Object { $takenNames -notcontains $_.Name.ToLowerInvariant() } | ForEach-Object { [string]$_.Name })
        if ($ready.Count -gt 0) { [void]$lines.Add(('Found in your collection, ready to install: {0}' -f ($ready -join ', '))) }
        if ($differs.Count -gt 0) { [void]$lines.Add(('Found in your collection, but a different file of yours is already in place: {0}' -f ($differs -join ', '))) }
        if ($inPlace.Count -gt 0) { [void]$lines.Add(('Already in place: {0}' -f ($inPlace -join ', '))) }
        foreach ($item in @($items | Where-Object { $_.Source -eq 'None' })) {
            $where = if ($Warning.Requirement.Contains('InstallVia')) { [string]$item.Destination } else { Split-Path -Parent ([string]$item.Destination) }
            [void]$lines.Add(('Missing: {0} (not found in those folders; goes in {1})' -f $item.Name, $where))
        }
        foreach ($item in @($items | Where-Object { $_.Source -ne 'None' -and -not $_.Installable })) {
            [void]$lines.Add(('Cannot be checked: {0} ({1})' -f $item.Name, $item.Problem))
        }
    } else {
        $done = @(@($Install.Installed) + @($Install.Replaced) | Where-Object { $_ })
        $rows = @(
            @('Installed', $done), @('Already matching', @($Install.AlreadyPresent)),
            @('Kept (your own file differs)', @($Install.KeptExisting)),
            @('Invalid (not the file the list of known files describes)', @($Install.Refused)),
            @('Not finished', @($Install.Failed))
        )
        foreach ($row in $rows) { if (@($row[1]).Count -gt 0) { [void]$lines.Add(('{0}: {1}' -f $row[0], (@($row[1]) -join ', '))) } }
        if ($Install.BackupFolder) { [void]$lines.Add(('Backup of any file that was replaced: {0}' -f $Install.BackupFolder)) }
    }
    return @($lines.ToArray())
}

# Shows each finding, and (Interactive only) offers the install, the details and the Open folder button.
# Never prompts when Interactive is not set. Interactive: when a package is not found and no collection folder that works is saved,
# the player is asked ONCE for the Supplementary folder (see Request-TpmSupplementaryFolder) and the search runs again. One Y then
# installs everything that was found and checked; only replacing a different file of the player's is asked separately (with a backup).
# Returns what was shown and what was copied.
function Invoke-TpmPrerequisiteReview {
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Warnings,
        [Parameter(Mandatory)][string]$TpRoot,
        [string[]]$SearchFolders = @(),
        [string]$EggmanDatZip = '',
        [string]$DatFilePath = '',
        [string]$SupplementaryDatPath = '',
        [switch]$Interactive,
        [scriptblock]$OtherRootsProvider = $null
    )
    $reviewable = @($Warnings | Where-Object { $_ -and $_.PSObject.Properties['MissingItems'] })
    $datRoms = $null
    if ($reviewable.Count -gt 0) {
        $datRoms = Get-TpmEmuDatRomSets -EggmanDatZip $EggmanDatZip -DatFilePath $DatFilePath -SupplementaryDatPath $SupplementaryDatPath
        if (-not $datRoms.Available) { Write-Log 'Prerequisites: no DAT list with [EMU] sets is available; found files cannot be checked, so none will be copied.' }
    }
    $makePlan = {
        param($Finding)
        if ($Finding.PSObject.Properties['MissingItems']) {
            return (Get-TpmPrerequisiteFixPlan -Warning $Finding -SearchFolders $SearchFolders -DatRoms $datRoms -TeknoParrotRoot $TpRoot -OtherRootsProvider $OtherRootsProvider)
        }
        return $null
    }
    $outcomes = New-Object System.Collections.Generic.List[object]
    foreach ($warning in @($Warnings)) {
        if ($null -eq $warning) { continue }
        [void]$outcomes.Add([pscustomobject]@{ Warning = $warning; Plan = (& $makePlan $warning); Install = $null; CopiedEarlier = 0; Screen = $null })
    }
    if ($Interactive) {
        $notFound = @($outcomes | Where-Object { $_.Plan -and $_.Warning.Requirement -and $_.Warning.Requirement.Contains('SourceZipPattern') -and @($_.Plan.Items | Where-Object { $_.Source -eq 'None' }).Count -gt 0 })
        if ($notFound.Count -gt 0) {
            $picked = Request-TpmSupplementaryFolder
            if ($picked) {
                $SearchFolders = @($picked) + @($SearchFolders)
                foreach ($outcome in $outcomes) { $outcome.Plan = & $makePlan $outcome.Warning }
            }
        }
    }
    foreach ($outcome in $outcomes) {
        $warning = $outcome.Warning
        $plan = $outcome.Plan
        $screen = Get-TpmPrerequisiteScreenLines -Warning $warning -Plan $plan
        $outcome.Screen = $screen
        foreach ($line in @($screen.Details)) { Write-Log ('Prerequisites: {0}: {1}' -f $warning.EmulatorType, $line) }
        Write-Host ''
        Write-Host ('  ' + $screen.Heading) -ForegroundColor Yellow
        Write-Host '  ----------------------------------------------------------' -ForegroundColor DarkGray
        foreach ($line in @($screen.Plain)) { Write-TpmText -Text $line -Color DarkCyan -Indent 2 }
        if ($null -ne $plan) {
            foreach ($line in @(Get-TpmPrerequisiteReportLines -Warning $warning -Plan $plan -SearchFolders $SearchFolders)) {
                Write-Log ('Prerequisites: {0}: {1}' -f $warning.EmulatorType, $line)
                Write-TpmText -Text $line -Color DarkGray -Indent 4 -HangingIndent 2
            }
        }
    }
    $withPlan = @($outcomes | Where-Object { $null -ne $_.Plan })
    if ($Interactive -and $withPlan.Count -gt 0) {
        $fixable = @($withPlan | Where-Object { $_.Plan.AllInstallable })
        $choices = if ($fixable.Count -gt 0) { @('Y', 'N', 'D', 'O') } else { @('N', 'D', 'O') }
        $prompt = if ($fixable.Count -gt 0) { '  Y = install what was found, N = not now, D = details, O = open the folder' } else { '  N = continue, D = details, O = open the folder' }
        do {
            Write-Host ''
            $choice = Read-TpmChoice -Prompt $prompt -Choices $choices -Default 'N'
            if ($choice -eq 'D') {
                Show-TpmDetailBlocks -Blocks @($withPlan | ForEach-Object { @{ Heading = [string]$_.Warning.Label; Lines = @($_.Screen.Details) } }) -Note 'Nothing was changed.'
            } elseif ($choice -eq 'O') {
                $folders = @($withPlan | ForEach-Object { Get-TpmPrerequisiteOpenFolder -Warning $_.Warning } | Where-Object { $_ } | Select-Object -Unique)
                $opened = $null
                foreach ($folder in $folders) { $opened = Open-TpmOwnedFolder -Path $folder -Label 'game startup files' }
                if ($folders.Count -eq 0 -or $null -eq $opened -or -not $opened.Succeeded) { Write-Host '  The folder could not be opened. The folder is named under Details (D).' -ForegroundColor Yellow }
            }
        } while ($choice -in @('D', 'O'))
        if ($choice -eq 'Y') {
            foreach ($outcome in $fixable) {
                $warning = $outcome.Warning
                $viaEmulator = [bool]($warning.Requirement -and $warning.Requirement.Contains('InstallVia'))
                Write-Host ''
                Write-Host ('  {0}' -f [string]$warning.Label) -ForegroundColor Cyan
                $install = Invoke-TpmPrerequisiteInstall -Plan $outcome.Plan -TpRoot $TpRoot
                if (@($install.KeptExisting).Count -gt 0) {
                    Write-Host ''
                    Write-Host '  A different file with the same name is already in the folder.' -ForegroundColor Yellow
                    Write-Host '  TeknoParrot Manager can replace it. It saves a backup copy of your file first.' -ForegroundColor DarkCyan
                    if ((Read-TpmYesNo -Prompt '  Replace it? Y = replace, N = keep mine' -Default 'N') -eq 'Y') {
                        # Files the first pass already copied still count; the second pass only reports its own.
                        $outcome.CopiedEarlier = @($install.Installed).Count + @($install.Replaced).Count
                        $install = Invoke-TpmPrerequisiteInstall -Plan $outcome.Plan -TpRoot $TpRoot -ReplaceNames @($install.KeptExisting)
                    }
                }
                $outcome.Install = $install
                $copied = $outcome.CopiedEarlier + @($install.Installed).Count + @($install.Replaced).Count
                if ($viaEmulator -and $install.Complete -and $copied -gt 0) {
                    Write-Host '  Done. The firmware was installed and checked. These games can start now.' -ForegroundColor Green
                } elseif ($viaEmulator -and -not $install.Complete) {
                    Write-Host ('  The firmware was not installed. {0}' -f [string]$install.Summary) -ForegroundColor Yellow
                    Write-Host '  Next step: open View Log from the main menu to see what stopped it.' -ForegroundColor DarkCyan
                } elseif ($install.Complete -and $copied -gt 0) {
                    Write-Host ('  Done. {0} {1} copied and checked. These games can start now.' -f $copied, $(if ($copied -eq 1) { 'file was' } else { 'files were' })) -ForegroundColor Green
                } elseif ($install.Complete) {
                    Write-Host '  The files were already in place. Nothing was changed.' -ForegroundColor Green
                } elseif (@($install.KeptExisting).Count -gt 0 -and @($install.Refused).Count -eq 0 -and @($install.Failed).Count -eq 0 -and ([string]$install.Outcome -in @('SUCCEEDED', 'NO_OP') -or [string]$install.ReasonCode -eq 'DIFFERENT_FILE_EXISTS')) {
                    # The only thing left is the file the player chose to keep.
                    if ($copied -gt 0) {
                        Write-Host ('  {0} {1} copied and checked. Your own file with the same name was kept, as you chose.' -f $copied, $(if ($copied -eq 1) { 'file was' } else { 'files were' })) -ForegroundColor Green
                    } else {
                        Write-Host '  Your own file with the same name was kept, as you chose. Nothing was changed.' -ForegroundColor Green
                    }
                    Write-Host '  The game may not start until that file is the right one. Run this step again and answer Y to replace it.' -ForegroundColor DarkCyan
                } else {
                    Write-Host ('  The files were not all copied. {0}' -f [string]$install.Summary) -ForegroundColor Yellow
                    Write-Host '  Next step: open View Log from the main menu to see what stopped it.' -ForegroundColor DarkCyan
                }
                foreach ($line in @(Get-TpmPrerequisiteReportLines -Warning $warning -Plan $outcome.Plan -SearchFolders $SearchFolders -Install $install)) {
                    Write-Log ('Prerequisites: {0}: {1}' -f $warning.EmulatorType, $line)
                    Write-TpmText -Text $line -Color DarkGray -Indent 4 -HangingIndent 2
                }
            }
        }
    }
    $installed = @($outcomes | Where-Object { $_.Install -and $_.Install.Complete -and ($_.CopiedEarlier + @($_.Install.Installed).Count + @($_.Install.Replaced).Count) -gt 0 })
    return [pscustomobject]@{ Reviewed = $outcomes.Count; FixedAny = ($installed.Count -gt 0); Outcomes = $outcomes.ToArray() }
}

# =============================================================================
# GAME TYPES (module-ready section)
# =============================================================================
# BEGIN GameTypes. Everything down to END GameTypes belongs together and can move into its own module after 1.0.
# The ONE table is $EmulatorBiosRequirements (above): game type -> emulator folder -> startup files, firmware or saved data -> where they
# go -> how they are checked (Get-TpmPrerequisiteWarning) and installed (Invoke-TpmPrerequisiteInstall, Invoke-TpmS11PreinstallInstall).
# This section adds: which game types are known, game files named as a set (System 11), the second game file found by a pattern (the
# System 11 disc image), and the saved System 11 files. It uses only helpers defined elsewhere in this script: Read-Xml, Write-Log,
# Get-ExeAlternatives, Get-TpmPrerequisiteTable, Resolve-TpmPrerequisiteEmulatorDir, Get-TpmEmulatorGameMap, Get-TpmOwnedLayout,
# Get-TpmFullFolderPath, Test-TpmNoReparsePath, Test-PathInside, Test-TpmCps3UnsafeMemberName, Get-TpmCps3FreeBytes,
# Get-TpmAutoSyncSha256, Invoke-TpmTransactionalFileBatch, Find-TpmPrerequisiteSourceZips, Format-TpmGameCount, New-TpmLibraryHealthRow.

# A profile's ExecutableName is a list of alternatives ("a.elf;b.elf" or "a|b": any one will do) or, when it is only .zip names
# separated by ";", a SET ("child.zip;parent.zip": the first is the game and the others must sit beside it). 25 real profiles are sets.
function Get-TpmGameFileSet {
    param([string]$ExecutableName)
    $text = ([string]$ExecutableName).Trim()
    $parts = @($text -split ';' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' })
    $isSet = ($parts.Count -ge 2 -and $text -notmatch '\|' -and @($parts | Where-Object { $_ -notmatch '\.zip$' }).Count -eq 0)
    if ($isSet) { return [pscustomobject]@{ IsSet = $true; Choices = @($parts[0]); Partners = @($parts | Select-Object -Skip 1) } }
    return [pscustomobject]@{ IsSet = $false; Choices = @(Get-ExeAlternatives $text); Partners = @() }
}

# The ZIPs of a set that are not beside the game file (an empty list when all are there, or when the name is not a set). When the file
# given is not the set's own game ZIP (for example its parent ZIP), the game ZIP is what is missing.
function Get-TpmMissingGameSetFiles {
    param([string]$GamePath, [string]$ExecutableName)
    $set = Get-TpmGameFileSet -ExecutableName $ExecutableName
    if (-not $set.IsSet -or [string]::IsNullOrWhiteSpace($GamePath)) { return @() }
    try { $folder = [System.IO.Path]::GetDirectoryName($GamePath.Trim()); $leaf = [System.IO.Path]::GetFileName($GamePath.Trim()) } catch { return @() }
    if ([string]::IsNullOrEmpty($folder)) { return @() }
    if (@($set.Choices | Where-Object { $_ -ieq $leaf }).Count -eq 0) { return @($set.Choices) }
    return @($set.Partners | Where-Object { -not (Test-Path -LiteralPath ([System.IO.Path]::Combine($folder, $_)) -PathType Leaf -ErrorAction SilentlyContinue) })
}

# The second game file of a profile whose ExecutableName2 is a pattern (System 11: "*.chd", the game disc image). It is looked for beside
# the first game file and in a folder there that is named after one of the game's files or after the game itself (the "game disc
# directory"). Exactly one match is used; none, or several, return '' so nothing is guessed (the player picks the disc image).
function Find-TpmSecondFileByPattern {
    param([string]$PrimaryExePath, [string]$Pattern, [string]$ExecutableName = '', [string]$ProfileCode = '')
    if ($Pattern -notmatch '^[\w*?. \-]+$') { return '' }
    try { $folder = [System.IO.Path]::GetDirectoryName($PrimaryExePath) } catch { return '' }
    if ([string]::IsNullOrEmpty($folder) -or -not (Test-Path -LiteralPath $folder -PathType Container -ErrorAction SilentlyContinue)) { return '' }
    $folders = New-Object System.Collections.Generic.List[string]
    $seenFolders = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    [void]$seenFolders.Add($folder)
    [void]$folders.Add($folder)
    $stems = @(@(Get-ExeAlternatives $ExecutableName | ForEach-Object { [System.IO.Path]::GetFileNameWithoutExtension($_) }) + @($ProfileCode) | Where-Object { $_ -match '^[\w. \-]+$' })
    foreach ($stem in $stems) {
        $sub = [System.IO.Path]::Combine($folder, $stem)
        if ((Test-Path -LiteralPath $sub -PathType Container -ErrorAction SilentlyContinue) -and $seenFolders.Add($sub)) { [void]$folders.Add($sub) }
    }
    $found = New-Object System.Collections.Generic.List[string]
    foreach ($candidateFolder in $folders) {
        foreach ($file in @(Get-ChildItem -LiteralPath $candidateFolder -Filter $Pattern -File -ErrorAction SilentlyContinue)) {
            if (($file.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -eq 0) { [void]$found.Add($file.FullName) }
        }
    }
    if ($found.Count -eq 1) { return $found[0] }
    return ''
}

# The Preinstall part of the System 11 table row, or $null when the table has none (a test that has not defined the table).
function Get-TpmS11PreinstallSetting {
    $table = Get-TpmPrerequisiteTable
    if ($table.ContainsKey('TeknoS11') -and $table['TeknoS11'].Contains('Preinstall')) { return $table['TeknoS11']['Preinstall'] }
    return $null
}

# <TeknoParrot root>\TeknoS11\state\<game>\cabinet-1, where System 11 keeps a game's saved flash and EEPROM files. '' without the table row.
function Get-TpmS11SavedFilesDir {
    param([Parameter(Mandatory)][string]$TeknoParrotRoot, [Parameter(Mandatory)][string]$Code)
    $setting = Get-TpmS11PreinstallSetting
    if ($null -eq $setting) { return '' }
    return [System.IO.Path]::Combine($TeknoParrotRoot, [string]$setting['StateDir'], $Code, [string]$setting['CabinetDir'])
}

function Test-TpmS11SavedFilesPresent {
    param([Parameter(Mandatory)][string]$TeknoParrotRoot, [Parameter(Mandatory)][string]$Code)
    $folder = Get-TpmS11SavedFilesDir -TeknoParrotRoot $TeknoParrotRoot -Code $Code
    if (-not $folder -or -not (Test-Path -LiteralPath $folder -PathType Container -ErrorAction SilentlyContinue)) { return $false }
    return (@(Get-ChildItem -LiteralPath $folder -File -Force -ErrorAction SilentlyContinue).Count -gt 0)
}

# Read-only look at the registered profiles for the Library health check. One read per profile.
#   Unknown          game types that are not in the table (one entry per type, with its games): flagged, never ignored
#   NotAvailable     games the profile marks DevOnly (development only): TeknoParrot has not released them yet
#   EmulatorMissing  games whose type is known but whose emulator folder is not in the TeknoParrot folder (looked for on disk)
#   NeedsManualExe   games with no executable name, no setup file and no game path: the player must pick the game file
#   S11Games / S11NoSavedFiles  System 11 games, and those with no saved files yet
function Get-TpmGameTypeReport {
    param([Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Profiles, [string]$TeknoParrotRoot = '')
    $table = Get-TpmPrerequisiteTable
    $unknown = @{}
    $emulatorMissing = @{}
    $folderChecked = @{}
    $notAvailable = New-Object System.Collections.Generic.List[string]
    $manualExe = New-Object System.Collections.Generic.List[string]
    $s11NoSaved = New-Object System.Collections.Generic.List[string]
    $s11Games = 0
    $failed = 0
    foreach ($pf in $Profiles) {
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) { continue }
            $profileNode = $doc.GameProfile
            $code = [string]$pf.BaseName
            $nameNode = $profileNode.SelectSingleNode('GameName')
            $label = if ($nameNode -and -not [string]::IsNullOrWhiteSpace($nameNode.InnerText)) { $nameNode.InnerText.Trim() } else { $code }
            $typeNode = $profileNode.SelectSingleNode('EmulatorType')
            $type = if ($typeNode) { $typeNode.InnerText.Trim() } else { '' }
            $devNode = $profileNode.SelectSingleNode('DevOnly')
            $devOnly = [bool]($devNode -and $devNode.InnerText.Trim() -ieq 'true')
            if ($table.Count -gt 0 -and $type) {
                if (-not $table.ContainsKey($type)) {
                    if (-not $unknown.ContainsKey($type)) { $unknown[$type] = New-Object System.Collections.Generic.List[string] }
                    [void]$unknown[$type].Add($label)
                    Write-Log ("GameTypes: {0} has the game type '{1}', which TeknoParrot Manager does not know." -f $code, $type)
                } elseif ($devOnly) {
                    [void]$notAvailable.Add($label)
                    Write-Log ("GameTypes: {0} ({1}) is marked development only, so it is not available yet." -f $code, $type)
                } elseif ($TeknoParrotRoot -and ($table[$type].Contains('EmulatorFolders') -or $type -ieq 'Pcsx2x6')) {
                    if (-not $folderChecked.ContainsKey($type)) { $folderChecked[$type] = [bool](Resolve-TpmPrerequisiteEmulatorDir -EmulatorType $type -Requirement $table[$type] -TeknoParrotRoot $TeknoParrotRoot) }
                    if (-not $folderChecked[$type]) {
                        if (-not $emulatorMissing.ContainsKey($type)) { $emulatorMissing[$type] = New-Object System.Collections.Generic.List[string] }
                        [void]$emulatorMissing[$type].Add($label)
                    }
                }
            }
            if ($devOnly) { continue }
            $exeNode = $profileNode.SelectSingleNode('ExecutableName')
            if ($TeknoParrotRoot -and (-not $exeNode -or [string]::IsNullOrWhiteSpace($exeNode.InnerText))) {
                $pathNode = $profileNode.SelectSingleNode('GamePath')
                $pathText = if ($pathNode) { $pathNode.InnerText.Trim() } else { '' }
                $hasPath = ($pathText -and (Test-Path -LiteralPath $pathText -PathType Leaf -ErrorAction SilentlyContinue))
                $hasSetup = Test-Path -LiteralPath (Join-Path (Join-Path $TeknoParrotRoot 'GameSetup') ($code + '.xml')) -PathType Leaf -ErrorAction SilentlyContinue
                if (-not $hasPath -and -not $hasSetup) { [void]$manualExe.Add($label) }
            }
            if ($type -ieq 'TeknoS11') {
                $s11Games++
                if ($TeknoParrotRoot -and (Get-TpmS11SavedFilesDir -TeknoParrotRoot $TeknoParrotRoot -Code $code) -and -not (Test-TpmS11SavedFilesPresent -TeknoParrotRoot $TeknoParrotRoot -Code $code)) { [void]$s11NoSaved.Add($label) }
            }
        } catch {
            $failed++
            Write-Log ("GameTypes: could not read {0} -- {1}" -f $pf.Name, $_.Exception.Message)
        }
    }
    return [pscustomobject]@{
        Checked         = ($table.Count -gt 0)
        Failed          = $failed
        Unknown         = @($unknown.Keys | Sort-Object | ForEach-Object { [pscustomobject]@{ Type = [string]$_; Games = @($unknown[$_].ToArray()) } })
        NotAvailable    = @($notAvailable.ToArray())
        EmulatorMissing = @($emulatorMissing.Keys | Sort-Object | ForEach-Object { [pscustomobject]@{ Type = [string]$_; Games = @($emulatorMissing[$_].ToArray()) } })
        NeedsManualExe  = @($manualExe.ToArray())
        S11Games        = $s11Games
        S11NoSavedFiles = @($s11NoSaved.ToArray())
    }
}

# The Library health rows for a game type report: 'Game types', 'Game files' and 'System 11'. Short plain wording; the names are in the details.
function Get-TpmGameTypeRows {
    param([Parameter(Mandatory)]$Report)
    $rows = New-Object System.Collections.Generic.List[object]
    if (-not [bool]$Report.Checked) { return @() }
    if ([int]$Report.Failed -gt 0) { return @(New-TpmLibraryHealthRow -Area 'Game types' -Text 'Could not check' -Color 'Yellow') }
    $unknownCount = @($Report.Unknown | ForEach-Object { @($_.Games) }).Count
    $missingCount = @($Report.EmulatorMissing | ForEach-Object { @($_.Games) }).Count
    $notAvailableCount = @($Report.NotAvailable).Count
    $parts = New-Object System.Collections.Generic.List[string]
    if ($unknownCount -gt 0) { [void]$parts.Add(('{0} {1} a game type that TeknoParrot Manager does not know' -f (Format-TpmGameCount -Count $unknownCount), $(if ($unknownCount -eq 1) { 'has' } else { 'have' }))) }
    if ($notAvailableCount -gt 0) { [void]$parts.Add(('{0} {1} not available yet' -f (Format-TpmGameCount -Count $notAvailableCount), $(if ($notAvailableCount -eq 1) { 'is' } else { 'are' }))) }
    if ($missingCount -gt 0) { [void]$parts.Add(('the emulator for {0} is not in your TeknoParrot folder' -f (Format-TpmGameCount -Count $missingCount))) }
    if ($parts.Count -gt 0) {
        [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Game types' -Text ('Needs attention - {0}. Choose D for the list' -f ($parts -join '; ')) -Color 'Yellow'))
    } else {
        [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Game types' -Text 'OK' -Color 'Green'))
    }
    $manualCount = @($Report.NeedsManualExe).Count
    if ($manualCount -gt 0) {
        [void]$rows.Add((New-TpmLibraryHealthRow -Area 'Game files' -Text ('Needs attention - {0} {1} you to pick the game file by hand. Choose D for the list' -f (Format-TpmGameCount -Count $manualCount), $(if ($manualCount -eq 1) { 'needs' } else { 'need' })) -Color 'Yellow'))
    }
    $noSavedCount = @($Report.S11NoSavedFiles).Count
    if ($noSavedCount -gt 0) {
        [void]$rows.Add((New-TpmLibraryHealthRow -Area 'System 11' -Text ('Note - {0} of {1} System 11 {2} no saved setup files yet. If you already have the System 11 saved-files set, the main run can copy it' -f $noSavedCount, [int]$Report.S11Games, $(if ([int]$Report.S11Games -eq 1) { 'game has' } else { 'games have' })) -Color 'DarkGray'))
    }
    return $rows.ToArray()
}

# The detail block for the same report: every name, and what to do about it.
function Get-TpmGameTypeDetailBlocks {
    param([Parameter(Mandatory)]$Report)
    if (-not [bool]$Report.Checked) { return @() }
    $lines = New-Object System.Collections.Generic.List[string]
    if ([int]$Report.Failed -gt 0) {
        [void]$lines.Add(('Status: {0} game profile(s) could not be read, so this check is not complete. The log says why.' -f $Report.Failed))
    }
    foreach ($entry in @($Report.Unknown)) {
        [void]$lines.Add(('Unknown game type {0}: {1}' -f $entry.Type, (Format-TpmNameList -Names @($entry.Games) -Max 1000)))
    }
    if (@($Report.Unknown).Count -gt 0) { [void]$lines.Add('TeknoParrot Manager does not know these types yet, so it cannot check their files. The games may still run.') }
    if (@($Report.NotAvailable).Count -gt 0) {
        [void]$lines.Add(('Not available yet: {0}' -f (Format-TpmNameList -Names @($Report.NotAvailable) -Max 1000)))
        [void]$lines.Add('TeknoParrot lists these as development only, so they cannot be played yet.')
    }
    foreach ($entry in @($Report.EmulatorMissing)) {
        [void]$lines.Add(('Emulator for type {0} is not in your TeknoParrot folder: {1}' -f $entry.Type, (Format-TpmNameList -Names @($entry.Games) -Max 1000)))
    }
    if (@($Report.NeedsManualExe).Count -gt 0) {
        [void]$lines.Add(('Pick the game file by hand: {0}' -f (Format-TpmNameList -Names @($Report.NeedsManualExe) -Max 1000)))
        [void]$lines.Add('Their profile names no game file and TeknoParrot has no setup file for them, so TeknoParrot Manager cannot find them. Set the game file in TeknoParrotUI.')
    }
    if (@($Report.S11NoSavedFiles).Count -gt 0) {
        [void]$lines.Add(('System 11 games with no saved setup files: {0}' -f (Format-TpmNameList -Names @($Report.S11NoSavedFiles) -Max 1000)))
        [void]$lines.Add('The saved-files set holds files for about two thirds of the System 11 games. A game it has no files for starts without them.')
    }
    if ($lines.Count -eq 0) { [void]$lines.Add('Every registered game has a known game type, and its emulator is in your TeknoParrot folder.') }
    return @(@{ Heading = 'Game types'; Lines = $lines.ToArray() })
}

# --- System 11 saved files: copied from the player's own set, never replacing a file ---------------------------------------------------
# The set ("[NVRAM] TeknoS11 preinstalled game files for System 11") holds TeknoS11\state\<game>\cabinet-1\<file> for 150 games. Its README
# says to copy the state folder, "overwrite files at your own risk". TeknoParrot Manager only ADDS: a file that is already there is kept.
# Nothing is downloaded and nothing is pointed to; the player's own ZIP (found in the collection folders) or a folder the player picks.

# A chosen ZIP or folder: @{ Valid; Kind = Archive|Folder; Path; Error }. A folder may hold TeknoS11\state, or be the state folder.
function Resolve-TpmS11PreinstallSource {
    param([AllowEmptyString()][AllowNull()][string]$Path)
    $result = [pscustomobject]@{ Valid = $false; Kind = ''; Path = ''; Error = '' }
    $text = ([string]$Path).Trim().Trim('"')
    if ([string]::IsNullOrWhiteSpace($text)) { $result.Error = 'No location was chosen.'; return $result }
    try { $full = [System.IO.Path]::GetFullPath($text) } catch { $result.Error = 'That is not a valid path.'; return $result }
    if (Test-Path -LiteralPath $full -PathType Leaf) {
        if ([System.IO.Path]::GetExtension($full) -ine '.zip') { $result.Error = 'Choose a folder or a .zip archive.'; return $result }
        $result.Valid = $true; $result.Kind = 'Archive'; $result.Path = $full
        return $result
    }
    if (-not (Test-Path -LiteralPath $full -PathType Container)) { $result.Error = 'That location was not found.'; return $result }
    $candidates = @((Join-Path $full 'TeknoS11\state'), (Join-Path $full 'state'))
    if ((Split-Path -Leaf $full) -ieq 'state') { $candidates += $full }
    foreach ($candidate in $candidates) {
        if (Test-Path -LiteralPath $candidate -PathType Container) { $result.Valid = $true; $result.Kind = 'Folder'; $result.Path = $candidate; return $result }
    }
    $result.Error = 'That folder has no state folder inside it.'
    return $result
}

# Every <game>\cabinet-1\<file> of a source: @{ Code; Name; Length; EntryName; FilePath }. An unsafe or odd name is left out (and logged).
function Get-TpmS11PreinstallMembers {
    param([Parameter(Mandatory)]$Source)
    $setting = Get-TpmS11PreinstallSetting
    $cabinet = if ($setting) { [string]$setting['CabinetDir'] } else { 'cabinet-1' }
    $stateRelative = if ($setting) { ([string]$setting['StateDir']).Replace('\', '/') } else { 'TeknoS11/state' }
    $stateLeaf = $stateRelative.Split('/')[-1]
    $statePrefix = $stateRelative.Substring(0, $stateRelative.Length - $stateLeaf.Length)
    $pattern = '^(?:' + [regex]::Escape($statePrefix) + ')?' + [regex]::Escape($stateLeaf) + '/([^/]+)/' + [regex]::Escape($cabinet) + '/([^/]+)$'
    $members = New-Object System.Collections.Generic.List[object]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $left = @{ Out = 0 }
    $add = {
        param([string]$Code, [string]$Name, [int64]$Length, [string]$EntryName, [string]$FilePath)
        if ($Code -notmatch '^[A-Za-z0-9_\-]+$' -or $Name -notmatch '^[A-Za-z0-9_.\-]+$' -or -not $seen.Add($Code + '/' + $Name)) { $left.Out++; return }
        [void]$members.Add([pscustomobject]@{ Code = $Code; Name = $Name; Length = $Length; EntryName = $EntryName; FilePath = $FilePath })
    }
    if ($Source.Kind -eq 'Archive') {
        $zip = [System.IO.Compression.ZipFile]::OpenRead($Source.Path)
        try {
            # get_Entries(): the property read hides a bad member name on Windows PowerShell 5.1.
            foreach ($entry in $zip.get_Entries()) {
                if ([string]::IsNullOrEmpty($entry.Name)) { continue }
                $name = [string]$entry.FullName
                if (Test-TpmCps3UnsafeMemberName -Name $name) { $left.Out++; continue }
                $match = [regex]::Match($name, $pattern, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
                if (-not $match.Success) { continue }
                & $add $match.Groups[1].Value $match.Groups[2].Value ([int64]$entry.Length) $name ''
            }
        } finally { $zip.Dispose() }
    } else {
        foreach ($codeDir in @(Get-ChildItem -LiteralPath $Source.Path -Directory -Force -ErrorAction Stop)) {
            if (($codeDir.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { $left.Out++; continue }
            $cabinetDir = Join-Path $codeDir.FullName $cabinet
            if (-not (Test-Path -LiteralPath $cabinetDir -PathType Container)) { continue }
            if (([System.IO.File]::GetAttributes($cabinetDir) -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { $left.Out++; continue }
            foreach ($file in @(Get-ChildItem -LiteralPath $cabinetDir -File -Force -ErrorAction Stop)) {
                if (($file.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { $left.Out++; continue }
                & $add $codeDir.Name $file.Name ([int64]$file.Length) '' $file.FullName
            }
        }
    }
    if ($left.Out -gt 0) { Write-Log ("System 11 saved files: {0} item(s) in the source were left out (odd or unsafe name, or a duplicate)." -f $left.Out) }
    return $members.ToArray()
}

# Read-only plan: for each registered System 11 game, which saved files the source has and which are already in place.
#   Items         one per file: Code, Name, Length, EntryName/FilePath, Destination, Exists
#   NewGames      games that get at least one file
#   NoFileGames   games the source holds no file for (said plainly: they start without)
#   AlreadyHave   games whose files are all in place already
function Get-TpmS11PreinstallPlan {
    param([Parameter(Mandatory)][string]$SourcePath, [Parameter(Mandatory)][string]$TeknoParrotRoot, [Parameter(Mandatory)][string[]]$GameCodes)
    $plan = [pscustomobject]@{ Valid = $false; Error = ''; Source = $null; Items = @(); NoFileGames = @(); AlreadyHave = @(); NewGames = @() }
    $source = Resolve-TpmS11PreinstallSource -Path $SourcePath
    if (-not $source.Valid) { $plan.Error = [string]$source.Error; return $plan }
    try { $members = @(Get-TpmS11PreinstallMembers -Source $source) }
    catch {
        Write-Log ("System 11 saved files: the source could not be read -- {0}" -f $_.Exception.Message)
        $plan.Error = 'The chosen location could not be read.'
        return $plan
    }
    $items = New-Object System.Collections.Generic.List[object]
    $noFile = New-Object System.Collections.Generic.List[string]
    $already = New-Object System.Collections.Generic.List[string]
    $newGames = New-Object System.Collections.Generic.List[string]
    foreach ($code in @($GameCodes | Sort-Object -Unique)) {
        $mine = @($members | Where-Object { $_.Code -ieq $code })
        if ($mine.Count -eq 0) { [void]$noFile.Add($code); continue }
        $folder = Get-TpmS11SavedFilesDir -TeknoParrotRoot $TeknoParrotRoot -Code $code
        $anyNew = $false
        foreach ($member in $mine) {
            $destination = [System.IO.Path]::Combine($folder, $member.Name)
            $exists = [bool](Test-Path -LiteralPath $destination -ErrorAction SilentlyContinue)
            if (-not $exists) { $anyNew = $true }
            [void]$items.Add([pscustomobject]@{ Code = $code; Name = $member.Name; Length = $member.Length; EntryName = $member.EntryName; FilePath = $member.FilePath; Destination = $destination; Exists = $exists })
        }
        if ($anyNew) { [void]$newGames.Add($code) } else { [void]$already.Add($code) }
    }
    $plan.Valid = $true
    $plan.Source = $source
    $plan.Items = $items.ToArray()
    $plan.NoFileGames = $noFile.ToArray()
    $plan.AlreadyHave = $already.ToArray()
    $plan.NewGames = $newGames.ToArray()
    return $plan
}

# Copies the files of a plan that are not in place yet. Every file is staged and its size checked, then all are added through the shared
# file transaction (a recovery copy is kept and everything is put back if a step fails). An existing file is never replaced.
function Invoke-TpmS11PreinstallInstall {
    param([Parameter(Mandatory)]$Plan, [Parameter(Mandatory)][string]$TpRoot)
    $installed = New-Object System.Collections.Generic.List[string]
    $failed = New-Object System.Collections.Generic.List[string]
    $kept = New-Object System.Collections.Generic.List[string]
    $finish = {
        param([string]$Outcome, [string]$Reason, [string]$Summary, $Transaction = $null)
        try { Write-Log ("System 11 saved files: outcome={0} reason={1} installed={2} kept={3} failed={4}" -f $Outcome, $Reason, $installed.Count, $kept.Count, $failed.Count) } catch { }
        return [pscustomobject]@{
            Outcome = $Outcome; ReasonCode = $Reason; Summary = $Summary; Transaction = $Transaction
            Installed = @($installed.ToArray()); Kept = @($kept.ToArray()); Failed = @($failed.ToArray())
            Complete = ($Outcome -in @('SUCCEEDED', 'NO_OP') -and $failed.Count -eq 0)
        }
    }
    if ([string]::IsNullOrWhiteSpace($TpRoot) -or -not (Test-Path -LiteralPath $TpRoot -PathType Container)) {
        return (& $finish 'FAILED_BEFORE_MUTATION' 'TP_ROOT_INVALID' 'The TeknoParrot folder was not found. Nothing was changed.')
    }
    $tpFull = Get-TpmFullFolderPath -Path $TpRoot
    if (-not (Test-TpmNoReparsePath -Path $tpFull)) {
        return (& $finish 'FAILED_BEFORE_MUTATION' 'TP_ROOT_UNSAFE' 'The TeknoParrot folder path is not safe to write to. Nothing was changed.')
    }
    if (-not $Plan.Valid) { return (& $finish 'FAILED_BEFORE_MUTATION' 'SOURCE_UNUSABLE' ([string]$Plan.Error + ' Nothing was changed.')) }
    foreach ($item in @($Plan.Items | Where-Object { $_.Exists })) { [void]$kept.Add(('{0}\{1}' -f $item.Code, $item.Name)) }
    $todo = @($Plan.Items | Where-Object { -not $_.Exists })
    if ($todo.Count -eq 0) { return (& $finish 'NO_OP' 'NO_CHANGES_NEEDED' 'Every saved file was already in place. Nothing was changed.') }
    foreach ($item in $todo) {
        $destination = [System.IO.Path]::GetFullPath([string]$item.Destination)
        if (-not (Test-PathInside -child $destination -parent $tpFull) -or -not (Test-TpmNoReparsePath -Path $destination)) {
            return (& $finish 'FAILED_BEFORE_MUTATION' 'DESTINATION_UNSAFE' 'A saved-files folder is not safe to write to. Nothing was changed.')
        }
    }
    [int64]$needed = 64MB
    foreach ($item in $todo) { $needed += 2 * [int64]$item.Length }
    $free = Get-TpmCps3FreeBytes -Path $tpFull
    if ($null -ne $free -and $free -lt $needed) {
        return (& $finish 'FAILED_BEFORE_MUTATION' 'INSUFFICIENT_SPACE' ('There is not enough free space on the TeknoParrot drive: about {0} MB needed, {1} MB free. Nothing was changed.' -f [Math]::Ceiling($needed / 1MB), [Math]::Floor($free / 1MB)))
    }
    $layout = Get-TpmOwnedLayout -TeknoParrotRoot $tpFull
    $stageBase = Join-Path $layout.Temp 's11-stage'
    if (-not (Test-TpmNoReparsePath -Path $stageBase)) {
        return (& $finish 'FAILED_BEFORE_MUTATION' 'STAGING_UNSAFE' 'The staging folder path is not safe to write to. Nothing was changed.')
    }
    $extractDir = Join-Path $stageBase ('extract-' + [guid]::NewGuid().ToString('N'))
    $zip = $null
    try {
        [void][System.IO.Directory]::CreateDirectory($extractDir)
        if ($Plan.Source.Kind -eq 'Archive') { $zip = [System.IO.Compression.ZipFile]::OpenRead([string]$Plan.Source.Path) }
        $operations = New-Object System.Collections.Generic.List[object]
        $index = 0
        $started = Get-Date
        foreach ($item in $todo) {
            $index++
            Write-TpmCompactExtractionProgress -Phase 'Extracting' -Label 'System 11 saved files' -Current $index -Total $todo.Count -StartedAt $started
            $stagePath = Join-Path $extractDir ('{0:0000}.bin' -f $index)
            $label = '{0}\{1}' -f $item.Code, $item.Name
            try {
                if ($zip) {
                    $entry = $zip.GetEntry([string]$item.EntryName)
                    if ($null -eq $entry -or [int64]$entry.Length -ne [int64]$item.Length) { [void]$failed.Add($label); Write-Log ("System 11 saved files: {0} is not the size the source listed; skipped." -f $label); continue }
                    $in = $entry.Open()
                    $out = $null
                    try {
                        $out = New-Object System.IO.FileStream($stagePath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None, 65536)
                        $in.CopyTo($out)
                    } finally { if ($out) { $out.Dispose() }; $in.Dispose() }
                } else {
                    $sourceInfo = Get-Item -LiteralPath ([string]$item.FilePath) -Force -ErrorAction Stop
                    if ($sourceInfo.PSIsContainer -or (($sourceInfo.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) -or [int64]$sourceInfo.Length -ne [int64]$item.Length) { [void]$failed.Add($label); Write-Log ("System 11 saved files: {0} changed since it was listed; skipped." -f $label); continue }
                    Copy-Item -LiteralPath ([string]$item.FilePath) -Destination $stagePath -ErrorAction Stop
                }
                if ((Get-Item -LiteralPath $stagePath -Force).Length -ne [int64]$item.Length) { [void]$failed.Add($label); Write-Log ("System 11 saved files: {0} was not copied completely; skipped." -f $label); continue }
                $sha = Get-TpmAutoSyncSha256 -Path $stagePath
                [void]$operations.Add([pscustomobject][ordered]@{ ItemId = $label; Operation = 'ADD'; SourcePath = $stagePath; DestinationPath = [System.IO.Path]::GetFullPath([string]$item.Destination); RootPath = $tpFull; ExpectedSourceHash = $sha; ExpectedFinalHash = $sha })
            } catch {
                [void]$failed.Add($label)
                Write-Log ("System 11 saved files: {0} could not be read -- {1}" -f $label, $_.Exception.Message)
            }
        }
        Write-TpmCompactExtractionProgress -Phase 'Extracting' -Label 'System 11 saved files' -Current $todo.Count -Total $todo.Count -StartedAt $started -Complete
        if ($failed.Count -gt 0) {
            # One file that cannot be read means the set cannot be trusted: nothing is added.
            return (& $finish 'FAILED_BEFORE_MUTATION' 'SOURCE_FILE_UNUSABLE' 'Some saved files could not be read from your set. Nothing was changed.')
        }
        $transaction = Invoke-TpmTransactionalFileBatch `
            -WorkflowKey 'S11Preinstall' -OperationKey 'InstallSavedFiles' `
            -Operations $operations.ToArray() -StagingDir $stageBase `
            -Summary 'The System 11 saved files were not copied.' `
            -SuccessSummary 'The System 11 saved files were copied and checked.' `
            -NoOpSummary 'Everything is already in place. Nothing was changed.' `
            -ReasonCode 'S11_FILE_TRANSACTION_FAILED'
        if ([string]$transaction.Outcome -eq 'SUCCEEDED') { foreach ($operation in $operations) { [void]$installed.Add([string]$operation.ItemId) } }
        return (& $finish ([string]$transaction.Outcome) ([string]$transaction.ReasonCode) ([string]$transaction.Summary) $transaction)
    } catch {
        try { Write-Log ("System 11 saved files: install stopped -- {0}" -f $_.Exception.Message) } catch { }
        return (& $finish 'FAILED_BEFORE_MUTATION' 'S11_INSTALL_ERROR' 'The saved files could not be copied. Nothing was changed.')
    } finally {
        if ($zip) { $zip.Dispose() }
        try {
            if (Test-Path -LiteralPath $extractDir) { Remove-Item -LiteralPath $extractDir -Recurse -Force -ErrorAction Stop }
            if ((Test-Path -LiteralPath $stageBase) -and @(Get-ChildItem -LiteralPath $stageBase -Force -ErrorAction Stop).Count -eq 0) { Remove-Item -LiteralPath $stageBase -Force -ErrorAction Stop }
        } catch {
            try { Write-Log ("System 11 saved files: staging cleanup incomplete: {0}" -f $_.Exception.Message) } catch { }
        }
    }
}

# Interactive optional step. Offered only when a registered System 11 game has no saved files yet. Looks for the player's own set in the
# collection folders first; otherwise asks whether the player has it somewhere else. Says plainly which games the set has no files for.
function Invoke-TpmS11PreinstallOffer {
    param(
        [Parameter(Mandatory)][string]$TpRoot,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [string[]]$SearchFolders = @()
    )
    $setting = Get-TpmS11PreinstallSetting
    if ($null -eq $setting -or -not (Test-Path -LiteralPath $UserProfilesDir -PathType Container)) { return $null }
    $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'System 11 profile discovery' -EnumerationErrorAction SilentlyContinue)
    $map = Get-TpmEmulatorGameMap -Profiles $profiles -ProgressLabel 'System 11 profile scan'
    if (-not $map.ContainsKey('TeknoS11')) { return $null }
    $without = @($map['TeknoS11'] | Where-Object { -not (Test-TpmS11SavedFilesPresent -TeknoParrotRoot $TpRoot -Code $_) })
    if ($without.Count -eq 0) { return $null }
    $zips = @(Find-TpmPrerequisiteSourceZips -Pattern ([string]$setting['SourceZipPattern']) -SearchFolders $SearchFolders)
    $plan = $null
    if ($zips.Count -gt 0) {
        $plan = Get-TpmS11PreinstallPlan -SourcePath ([string]$zips[0].FullName) -TeknoParrotRoot $TpRoot -GameCodes @($map['TeknoS11'])
        if ($plan.Valid -and @($plan.NewGames).Count -eq 0) {
            # The set in the collection has nothing more for these games, so the player is not asked again on every run.
            Write-Log 'System 11 saved files: the set in the collection has nothing new for the registered games.'
            return $null
        }
    }
    Write-Host ""
    Write-Host "============================================" -ForegroundColor DarkCyan
    Write-Host "   OPTIONAL: System 11 saved game files" -ForegroundColor DarkCyan
    Write-Host "============================================" -ForegroundColor DarkCyan
    Write-Host ""
    Write-TpmText -Text ('{0} registered System 11 {1} no saved setup files yet. Without them a game sets itself up from scratch, which can take hours.' -f $without.Count, $(if ($without.Count -eq 1) { 'game has' } else { 'games have' })) -Indent 2
    Write-TpmText -Text 'If you already have the System 11 saved-files set, TeknoParrot Manager can copy the files into your TeknoParrot folder. It does not provide or download them, and it never replaces a file that is already there.' -Indent 2
    Write-Host ""
    if ($null -ne $plan -and $plan.Valid) {
        Write-TpmText -Text 'TeknoParrot Manager found the set in your own game collection.' -Indent 2 -Color DarkCyan
        if ((Read-TpmYesNo -Prompt '  Copy the saved files for your System 11 games? (Y/N, default Y)' -Default 'Y') -ne 'Y') {
            Write-Host "  Skipped. Nothing was changed." -ForegroundColor DarkGray
            Write-Log 'System 11 saved files: offer declined.'
            return $null
        }
    } elseif ($null -eq $plan) {
        $chosen = ''
        if ((Read-TpmYesNo -Prompt '  Do you have the saved-files set? (Y/N, default N)' -Default 'N') -ne 'Y') {
            Write-Host "  Skipped. Nothing was changed." -ForegroundColor DarkGray
            Write-Log 'System 11 saved files: offer declined (no set in the collection folders).'
            return $null
        }
        $where = Read-TpmChoice -Prompt '  Is it F) a folder, Z) a .zip archive, or C) cancel? Choose F, Z, or C' -Choices @('F', 'Z', 'C') -Default 'C'
        if ($where -eq 'F') { $chosen = Read-PathWithBrowse -Prompt '  Folder that holds the TeknoS11 folder (or the state folder)' -Mode Folder }
        elseif ($where -eq 'Z') { $chosen = Read-PathWithBrowse -Prompt '  Path to the .zip archive' -Mode File -FileFilter 'Zip archives (*.zip)|*.zip|All files (*.*)|*.*' }
        if ([string]::IsNullOrWhiteSpace($chosen)) {
            Write-Host "  No location chosen. Nothing was changed." -ForegroundColor DarkGray
            Write-Log 'System 11 saved files: no source chosen.'
            return $null
        }
        $plan = Get-TpmS11PreinstallPlan -SourcePath $chosen -TeknoParrotRoot $TpRoot -GameCodes @($map['TeknoS11'])
    }
    if (-not $plan.Valid) {
        Write-Host ("  {0} Nothing was changed." -f $plan.Error) -ForegroundColor Yellow
        return $plan
    }
    foreach ($code in @($plan.NoFileGames)) { Write-Log ("System 11 saved files: the set has no files for {0}." -f $code) }
    if (@($plan.NoFileGames).Count -gt 0) {
        Write-TpmText -Text ('Your set has no saved files for {0}. {1} without them.' -f (Format-TpmNameList -Names @($plan.NoFileGames) -Max 5), $(if (@($plan.NoFileGames).Count -eq 1) { 'That game starts' } else { 'Those games start' })) -Indent 2 -Color Yellow
    }
    if (@($plan.NewGames).Count -eq 0) {
        Write-Host "  Your set has nothing new for your games. Nothing was changed." -ForegroundColor DarkGray
        return $plan
    }
    $result = $null
    try {
        $result = Invoke-TpmProgressGroup -Title 'System 11 saved files' -Action { Invoke-TpmS11PreinstallInstall -Plan $plan -TpRoot $TpRoot }
    } catch {
        Write-Host ("  The System 11 step could not finish: {0}" -f $_.Exception.Message) -ForegroundColor Red
        Write-Log ("System 11 saved files: failed: {0}" -f $_.Exception.Message)
        return $null
    }
    Write-Host ""
    if ($result.Outcome -eq 'SUCCEEDED') {
        Write-Host ("  Copied and checked {0} file(s) for {1}." -f @($result.Installed).Count, (Format-TpmGameCount -Count @($plan.NewGames).Count)) -ForegroundColor Green
        if (@($result.Kept).Count -gt 0) { Write-Host ("  {0} file(s) that were already there were kept." -f @($result.Kept).Count) -ForegroundColor DarkGray }
    } elseif ($result.Outcome -eq 'NO_OP') {
        Write-Host ("  {0}" -f $result.Summary) -ForegroundColor DarkGray
    } else {
        Write-Host ("  The saved files were not all copied. {0}" -f $result.Summary) -ForegroundColor Yellow
        Write-Host "  Next step: open View Log from the main menu to see what stopped it." -ForegroundColor DarkCyan
    }
    return $result
}
# END GameTypes

# Word-wraps free text (e.g. a community notes field) to a fixed width,
# returning one string per output line, each pre-fixed with Indent. Existing
# line breaks in the input (paragraph breaks, blank separator lines) are
# preserved as their own wrap groups rather than being collapsed -- notes
# pulled from eggmansworld.github.io are often multi-paragraph and lose all
# readability if reflowed into one block.
function Format-NoteLines {
    param([string]$Text, [int]$Width = 74, [string]$Indent = "    ")
    $out = [System.Collections.Generic.List[string]]::new()
    foreach ($rawLine in ($Text -split "`r?`n")) {
        if ([string]::IsNullOrWhiteSpace($rawLine)) { $out.Add(""); continue }
        $cur = ""
        foreach ($word in ($rawLine -split '\s+')) {
            if ($cur -eq "") { $cur = $word }
            elseif (($cur.Length + 1 + $word.Length) -le $Width) { $cur += " $word" }
            else { $out.Add("$Indent$cur"); $cur = $word }
        }
        if ($cur -ne "") { $out.Add("$Indent$cur") }
    }
    return $out
}

# One guide text field as a trimmed string ('' when the field is missing or empty).
function Get-TpmGuideText {
    param([object]$Row, [string]$Name)
    if ($null -eq $Row -or -not $Row.PSObject.Properties[$Name] -or $null -eq $Row.$Name) { return '' }
    return ([string]$Row.$Name).Trim()
}

# The guide's graphics-card notes for one game, as plain lines ("AMD (does not work): ..."). Empty when the guide says nothing.
function Get-TpmGuideGpuLines {
    param([object]$Source)
    $gpuLines = New-Object System.Collections.Generic.List[string]
    foreach ($vendor in @(@{ Key = 'amd'; Label = 'AMD' }, @{ Key = 'nvidia'; Label = 'NVIDIA' }, @{ Key = 'intel'; Label = 'Intel' })) {
        $issue = Get-TpmGuideText -Row $Source -Name ($vendor.Key + '_issues')
        $status = (Get-TpmGuideText -Row $Source -Name ($vendor.Key + '_status')).ToUpperInvariant()
        $statusText = switch ($status) { 'NO' { 'does not work' } 'WITH_FIX' { 'works with a fix' } default { '' } }
        if (-not $issue -and -not $statusText) { continue }
        $label = if ($statusText) { '{0} ({1})' -f $vendor.Label, $statusText } else { $vendor.Label }
        [void]$gpuLines.Add($(if ($issue) { '{0}: {1}' -f $label, $issue } else { '{0}.' -f $label }))
    }
    return ,$gpuLines
}

# Returns per-game guide text for every CURRENTLY REGISTERED profile (or registered variant) of the
# eggmansworld.github.io guide that has something to show: notes, general_issues (setup steps), graphics
# card notes, a second game file or a test program. Joined on profile_name == ProfileCode (the profile XML's
# own basename), the same key that drives the hardcoded compatibility tables above. A variant also shows its
# base game's general_issues and graphics notes, labeled as such (information only; nothing is applied from
# them). Network fetch, same convention as Get-BepInExRequiredGames: returns an empty array (never a
# hardcoded fallback) if the fetch fails, caller just sees nothing to report.
function Get-GameSetupNotes {
    param([string]$UserProfilesDir)

    $games = Get-EggmanGameData
    if (-not $games) { return ,@() }

    $registeredCodes = Get-TpmRegisteredProfileCodes -UserProfilesDir $UserProfilesDir -ProgressLabel 'Game setup notes profile-code scan'

    $entries = New-Object System.Collections.Generic.List[object]
    foreach ($game in @($games)) {
        [void]$entries.Add([pscustomobject]@{ Row = $game; Parent = $null })
        if ($game.PSObject.Properties['variants']) {
            foreach ($variant in @($game.variants)) { if ($variant) { [void]$entries.Add([pscustomobject]@{ Row = $variant; Parent = $game }) } }
        }
    }
    # Guide name for each profile, to name a linked profile.
    $gameNameByCode = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($entry in $entries) {
        $entryCode = Get-TpmGuideText -Row $entry.Row -Name 'profile_name'
        if ($entryCode) { $gameNameByCode[$entryCode] = Get-TpmGuideText -Row $entry.Row -Name 'game_name' }
    }
    $found = New-Object System.Collections.Generic.List[object]
    foreach ($entry in $entries) {
        $row = $entry.Row
        $code = Get-TpmGuideText -Row $row -Name 'profile_name'
        if (-not $code -or -not $registeredCodes.Contains($code)) { continue }
        # A version shares its base game's steps. They are listed once under the base game when that is registered too.
        $source = if ($entry.Parent) { $entry.Parent } else { $row }
        $baseListed = ($entry.Parent -and $registeredCodes.Contains((Get-TpmGuideText -Row $entry.Parent -Name 'profile_name')))
        if ($baseListed) { $source = $null }
        $notes = Get-TpmGuideText -Row $row -Name 'notes'
        $general = Get-TpmGuideText -Row $source -Name 'general_issues'
        $gpuLines = Get-TpmGuideGpuLines -Source $source
        $secondFile = Get-TpmGuideText -Row $row -Name 'setup_exe2'
        $testProgram = Get-TpmGuideText -Row $row -Name 'test_exe'
        # Archives the player must already own (the guide names them; TeknoParrot Manager never downloads them) and a linked profile (the same game with another setup).
        $extraArchives = @(foreach ($archiveField in @('supp_archives', 'additional_archives')) {
            foreach ($archiveName in @((Get-TpmGuideText -Row $row -Name $archiveField) -split ';')) { if ($archiveName.Trim()) { $archiveName.Trim() } }
        })
        $linkedText = ''
        $linkedCode = Get-TpmGuideText -Row $row -Name 'linked_profile'
        if ($linkedCode) {
            $linkedName = if ($gameNameByCode.ContainsKey($linkedCode) -and $gameNameByCode[$linkedCode]) { $gameNameByCode[$linkedCode] } else { $linkedCode }
            $linkedText = '{0} ({1}), {2}' -f $linkedName, $linkedCode, $(if ($registeredCodes.Contains($linkedCode)) { 'registered here' } else { 'not registered here' })
        }
        # A game the guide lists as broken, partly working or untested is named, not hidden.
        $guideStatus = switch ((Get-TpmGuideText -Row $row -Name 'status').ToUpperInvariant()) {
            'BROKEN'   { 'Broken. It does not work yet.' }
            'PARTIAL'  { 'Partial. It works only in part.' }
            'UNTESTED' { 'Untested. Nobody has confirmed that it works.' }
            default    { '' }
        }
        if (-not $notes -and -not $general -and $gpuLines.Count -eq 0 -and -not $secondFile -and -not $testProgram -and $extraArchives.Count -eq 0 -and -not $linkedText -and -not $guideStatus) { continue }
        # The run-once setup program line only fits games that have source notes; a ROM-based game's first file is a game archive.
        $setupExe = if ($notes) { Get-TpmGuideText -Row $row -Name 'setup_exe' } else { '' }
        [void]$found.Add([pscustomobject]@{
            Code          = $code
            GameName      = Get-TpmGuideText -Row $row -Name 'game_name'
            SetupExe      = $setupExe
            Notes         = $notes
            Needs         = (Get-TpmGameNeedsLine -ProfilePath (Join-Path $UserProfilesDir ($code + '.xml')) -SetupExe $setupExe)
            GeneralIssues = $general
            GpuIssues     = @($gpuLines)
            SecondFile    = $secondFile
            TestProgram   = $testProgram
            ExtraArchives = @($extraArchives)
            LinkedProfile = $linkedText
            GuideStatus   = $guideStatus
            BaseGame      = $(if ($entry.Parent) { Get-TpmGuideText -Row $entry.Parent -Name 'game_name' } else { '' })
        })
    }
    return $found.ToArray()
}

# The saved copy of the guide's game list, or $null when there is none. Never uses the network, so Library Health stays offline.
function Read-TpmSavedGuideRows {
    $path = Get-TpmEggmanGameDataCachePath
    if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path -PathType Leaf)) { return $null }
    try {
        $parsed = @(@([System.IO.File]::ReadAllText($path) | ConvertFrom-Json) | ForEach-Object { $_ })
        if ($parsed.Count -gt 0 -and $null -ne $parsed[0].PSObject.Properties['profile_name']) { return $parsed }
    } catch { Write-Log "GameSupport: the saved Game Notes copy could not be read -- $_" }
    return $null
}

# Library Health "Game support" (issues #351 and #389). Per emulator: how many registered games there are, how many have their
# game file, how many have setup steps in the Game Notes file, and how many need the player (game file missing, a second game
# file that is not chosen, or PostgreSQL settings missing). Read-only. GuideRows is the saved guide copy, or $null.
function Get-TpmGameSupportSummary {
    param([object[]]$ProfileFiles = @(), [string[]]$ValidCodes = @(), [string[]]$PostgresNeededCodes = @(), [object[]]$GuideRows = $null)
    $steps = @{}
    foreach ($game in @($GuideRows)) {
        if ($null -eq $game) { continue }
        $entries = New-Object System.Collections.Generic.List[object]
        [void]$entries.Add(@{ Row = $game; Parent = $null })
        if ($game.PSObject.Properties['variants']) {
            foreach ($variant in @($game.variants)) { if ($variant) { [void]$entries.Add(@{ Row = $variant; Parent = $game }) } }
        }
        foreach ($entry in $entries) {
            $code = Get-TpmGuideText -Row $entry.Row -Name 'profile_name'
            if (-not $code) { continue }
            $source = if ($entry.Parent) { $entry.Parent } else { $entry.Row }
            if ((Get-TpmGuideText -Row $entry.Row -Name 'notes') -or (Get-TpmGuideText -Row $source -Name 'general_issues') -or
                (Get-TpmGuideGpuLines -Source $source).Count -gt 0 -or (Get-TpmGuideText -Row $entry.Row -Name 'setup_exe2') -or
                (Get-TpmGuideText -Row $entry.Row -Name 'test_exe')) { $steps[$code] = $true }
        }
    }
    $emulators = @{}
    $needsYou = New-Object System.Collections.Generic.List[string]
    foreach ($pf in @($ProfileFiles)) {
        try { $doc = Read-Xml $pf.FullName } catch { continue }
        if (-not $doc.GameProfile) { continue }
        $code = $pf.BaseName
        $emulatorNode = $doc.GameProfile.SelectSingleNode('EmulatorType')
        $emulator = $(if ($null -ne $emulatorNode) { $emulatorNode.InnerText.Trim() } else { '' })
        if (-not $emulator) { $emulator = 'Unknown' }
        if (-not $emulators.ContainsKey($emulator)) { $emulators[$emulator] = [pscustomobject]@{ Emulator = $emulator; Registered = 0; FilesFound = 0; StepsShown = 0; NeedsYou = 0 } }
        $row = $emulators[$emulator]
        $row.Registered++
        $fileFound = ($ValidCodes -contains $code)
        if ($fileFound) { $row.FilesFound++ }
        if ($steps.ContainsKey($code)) { $row.StepsShown++ }
        $secondMissing = $false
        $twoNode = $doc.GameProfile.SelectSingleNode('HasTwoExecutables')
        if ($fileFound -and $null -ne $twoNode -and $twoNode.InnerText.Trim() -eq 'true') {
            $secondNode = $doc.GameProfile.SelectSingleNode('GamePath2')
            $secondPath = $(if ($null -ne $secondNode) { $secondNode.InnerText.Trim() } else { '' })
            $secondMissing = ([string]::IsNullOrWhiteSpace($secondPath) -or -not (Test-Path -LiteralPath $secondPath -PathType Leaf))
        }
        $setMissing = $false
        if ($fileFound) {
            $gamePathNode = $doc.GameProfile.SelectSingleNode('GamePath')
            $exeNameNode = $doc.GameProfile.SelectSingleNode('ExecutableName')
            $setMissing = (@(Get-TpmMissingGameSetFiles -GamePath $(if ($null -ne $gamePathNode) { $gamePathNode.InnerText.Trim() } else { '' }) -ExecutableName $(if ($null -ne $exeNameNode) { $exeNameNode.InnerText.Trim() } else { '' })).Count -gt 0)
        }
        if (-not $fileFound -or $secondMissing -or $setMissing -or ($PostgresNeededCodes -contains $code)) {
            $row.NeedsYou++
            [void]$needsYou.Add((Get-TpmGameDisplayLabel -ProfilePath $pf.FullName -Fallback $code))
        }
    }
    return [pscustomobject]@{ GuideAvailable = ($null -ne $GuideRows); Rows = @($emulators.Values | Sort-Object Emulator); NeedsYouNames = @($needsYou.ToArray()) }
}

# The Details lines for the Game support view (beginner words; the numbers are per emulator).
function Get-TpmGameSupportLines {
    param([Parameter(Mandatory)]$Summary)
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add('Per emulator: registered games / game file found / setup steps in the Game Notes file / games that need you.')
    foreach ($row in @($Summary.Rows)) {
        [void]$lines.Add(('{0}: {1} / {2} / {3} / {4}' -f $row.Emulator, $row.Registered, $row.FilesFound, $row.StepsShown, $row.NeedsYou))
    }
    [void]$lines.Add(('Needs you: {0}' -f (Format-TpmNameList -Names @($Summary.NeedsYouNames) -Max 1000 -WhenEmpty 'none')))
    [void]$lines.Add('A game needs you when its game file is missing, a second ZIP its profile names is not beside it, its second game file is not chosen, or it still needs PostgreSQL settings.')
    if (-not [bool]$Summary.GuideAvailable) {
        [void]$lines.Add('Setup steps were not counted: there is no saved copy of the Game Notes page yet. Run AutoSync or Register once with an internet connection to save one.')
    }
    return $lines.ToArray()
}

# The games TeknoParrot's own metadata says do not work on one graphics card maker ("amd" or "intel" is "NO" in Metadata.catalog.json in the
# TeknoParrot folder). Read-only. An empty list when the file is missing or cannot be read, so the fixed table below still applies.
function Get-TpmMetadataGpuIncompatibleCodes {
    param([string]$TeknoParrotRoot, [string]$Vendor)
    $field = switch ($Vendor) { 'AMD' { 'amd' } 'Intel' { 'intel' } default { '' } }
    if (-not $field -or [string]::IsNullOrWhiteSpace($TeknoParrotRoot)) { return @() }
    $path = Join-Path $TeknoParrotRoot 'Metadata.catalog.json'
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return @() }
    try {
        $catalog = [System.IO.File]::ReadAllText($path) | ConvertFrom-Json
        return @($catalog.PSObject.Properties | Where-Object { $_.Name -match '^[\w-]+$' -and $null -ne $_.Value -and $null -ne $_.Value.PSObject.Properties[$field] -and [string]$_.Value.$field -eq 'NO' } | ForEach-Object { [string]$_.Name })
    } catch {
        Write-Log ("GpuCheck: the TeknoParrot game metadata could not be read -- {0}" -f $_.Exception.Message)
        return @()
    }
}


# Read-only scan for all compatibility checks above. Returns
# [pscustomobject]@{ PathTooLong = @(...); DllMismatch = @(...); GpuIncompatible = @(...); BiosMissing = @(...); ExeMissing = @(...) }.
# Each PathTooLong entry: @{ Code; Length; Limit; Suggested }.
# Each DllMismatch entry: @{ Code; FileName; Found; Required }.
# Each GpuIncompatible entry: @{ Code; Vendor }.
# Each BiosMissing entry: @{ EmulatorType; ExpectedDir; MissingFiles; AffectedGames }.
# Each ExeMissing/ComponentMissing entry: @{ EmulatorType; ContractId;
# ContractStatus; Confidence; ContractBacked; CapabilityId; ExpectedPath;
# DetectorMethod; DetectorSource; AffectedProfiles; AffectedGames }.
function Get-CompatibilityWarnings {
    param([string]$UserProfilesDir, [string]$TeknoParrotRoot = '')

    $pathTooLong  = @()
    $dllMismatch  = @()
    $gpuIncompatible = @()
    $biosMissing  = @()
    $exeMissing   = @()

    # Best-effort, silent GPU detection -- never prompts. If undetected
    # (or vendor is NVIDIA, which has no known-broken titles here), the
    # GPU-incompatibility check is simply skipped for this run.
    $detectedVendor = (Get-DetectedGpuVendor).Vendor
    $gpuList = if ($detectedVendor -and $GpuIncompatibleGames.ContainsKey($detectedVendor)) {
        [System.Collections.Generic.HashSet[string]]::new(
            [string[]]$GpuIncompatibleGames[$detectedVendor], [System.StringComparer]::OrdinalIgnoreCase)
    } else { $null }
    # TeknoParrot's own game metadata also names the games that do not work on this card maker, so a new game is covered without a new Manager version.
    if ($null -ne $gpuList) { foreach ($metadataCode in @(Get-TpmMetadataGpuIncompatibleCodes -TeknoParrotRoot $TeknoParrotRoot -Vendor $detectedVendor)) { [void]$gpuList.Add($metadataCode) } }

    $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'Compatibility warning profile discovery' -EnumerationErrorAction SilentlyContinue)

    $profileScanStarted = Get-Date
    $profileScanCurrent = 0
    $profileScanCurrentDone = $false
    try {
    foreach ($pf in $profiles) {
        $profileScanCurrent++
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Compatibility warning profile scan' -Current $profileScanCurrent -Total $profiles.Count -StartedAt $profileScanStarted
        $code = $pf.BaseName
        $relevant = $RawThrillsPathLimits.ContainsKey($code) -or $FileVersionPins.ContainsKey($code) -or
                    ($gpuList -and $gpuList.Contains($code))
        if (-not $relevant) { continue }
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) { continue }
            $gpNode = $doc.GameProfile.SelectSingleNode("GamePath")
            if (-not $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { continue }
            $curPath = $gpNode.InnerText.Trim()
            if (-not (Test-Path -LiteralPath $curPath)) { continue }

            if ($RawThrillsPathLimits.ContainsKey($code)) {
                $info = $RawThrillsPathLimits[$code]
                if ($curPath.Length -gt $info.Limit) {
                    $pathTooLong += [pscustomobject]@{
                        Code = $code; Length = $curPath.Length
                        Limit = $info.Limit; Suggested = $info.Suggested
                    }
                }
            }

            if ($FileVersionPins.ContainsKey($code)) {
                $pin     = $FileVersionPins[$code]
                $exeDir  = [System.IO.Path]::GetDirectoryName($curPath)
                $dllPath = Join-Path $exeDir $pin.FileName
                if (Test-Path -LiteralPath $dllPath) {
                    try {
                        $foundCrc = Get-Crc32 -Path $dllPath
                        if ($foundCrc -ne $pin.RequiredCrc) {
                            $dllMismatch += [pscustomobject]@{
                                Code = $code; FileName = $pin.FileName
                                Found = $foundCrc; Required = $pin.RequiredCrc
                            }
                        }
                    } catch {
                        Write-Log "CompatibilityWarnings: could not CRC $($pin.FileName) for $code -- $_"
                    }
                }
                # File simply missing: not flagged. TPUI deploys its own
                # current copy at first launch -- nothing to warn about yet.
            }

            if ($gpuList -and $gpuList.Contains($code)) {
                $gpuIncompatible += [pscustomobject]@{ Code = $code; Vendor = $detectedVendor }
            }
        } catch {
            Write-Log "CompatibilityWarnings: could not parse $($pf.Name) -- $_"
        }
    }
    $profileScanCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Compatibility warning profile scan' -Current $(if ($profileScanCurrentDone) { $profileScanCurrent } else { $profileScanCurrent - 1 }) -Total $profiles.Count -StartedAt $profileScanStarted -Complete -Outcome $(if ($profileScanCurrentDone) { 'Final' } else { 'Error' })
    }

    # Issue #85 Tier 1: known per-emulator firmware/BIOS prerequisites.
    # Existence-only check (Test-Path), never reads file content -- TPM
    # never downloads, links, or redistributes these files. Skipped
    # entirely if -TeknoParrotRoot wasn't supplied (backward compatible
    # with existing callers). BIOS checks still require a confirmed
    # requirement, but the pcsx2x6 component check below is independent of
    # that firmware table.
    # One entry per (EmulatorType, missing-file-set), not per game -- every
    # game sharing that emulator would otherwise produce an identical
    # duplicate warning.
    if ($TeknoParrotRoot) {
        $prerequisiteTable = Get-TpmPrerequisiteTable
        $emulatorGames = Get-TpmEmulatorGameMap -Profiles $profiles

        foreach ($emuType in $emulatorGames.Keys) {
            $hasBiosRequirement = $prerequisiteTable.ContainsKey($emuType)

            # Issue #254/#268: inspect only a positively matched ECVF
            # contract. Missing or ambiguous contracts, unsupported detector
            # methods, and absent emulator folders remain unclassified rather
            # than becoming speculative component warnings.
            $componentState = Get-ContractBackedMissingComponents `
                -EmulatorType $emuType `
                -TeknoParrotRoot $TeknoParrotRoot `
                -AffectedProfiles @($emulatorGames[$emuType])
            if (@($componentState.Components).Count -gt 0) {
                $exeMissing += @($componentState.Components)
                continue  # do not report secondary BIOS noise when a required component is absent
            }

            if (-not $hasBiosRequirement) { continue }  # no confirmed BIOS requirement for this emulator

            $biosWarning = Get-TpmPrerequisiteWarning -EmulatorType $emuType -Requirement $prerequisiteTable[$emuType] -TeknoParrotRoot $TeknoParrotRoot -AffectedGames @($emulatorGames[$emuType]) -Profiles $profiles
            if ($biosWarning) { $biosMissing += $biosWarning }
        }
    }

    # ExeMissing is retained as the compatibility-warning field name for the
    # #254 callers/tests; its entries now represent any contract-declared
    # required component, not only an executable. ComponentMissing is the
    # general semantic alias for new callers.
    return [pscustomobject]@{ PathTooLong = $pathTooLong; DllMismatch = $dllMismatch; GpuIncompatible = $gpuIncompatible; BiosMissing = $biosMissing; ExeMissing = $exeMissing; ComponentMissing = $exeMissing }
}

# =============================================================================
# CONTROL PROPAGATION HELPERS
# =============================================================================
#
# Profiles have no default XML namespace, so plain XPath works. The button
# layout is /GameProfile/JoystickButtons/JoystickButtons (an outer wrapper
# element containing one inner element per button).

# True if a button node already carries any input binding child.
function Test-ButtonIsBound {
    param($btn)
    return ($null -ne $btn.SelectSingleNode("RawInputButton")) -or
           ($null -ne $btn.SelectSingleNode("DirectInputButton")) -or
           ($null -ne $btn.SelectSingleNode("XInputButton"))
}

# Returns the inner button nodes of a profile [xml] document.
function Get-ButtonNodes {
    param($doc)
    return $doc.SelectNodes("/GameProfile/JoystickButtons/JoystickButtons")
}

# Composite match key for a button: "InputMapping|AnalogType".
# Returns $true if a JoystickButtons ButtonName refers to a pure directional
# control (Up/Down/Left/Right joystick axis) rather than an action button.
# After stripping a leading player-number prefix (P1/P2/Player 1/Player 2),
# the remaining label must consist ONLY of direction words. Any additional
# qualifier (Punch, Kick, Shoulder, Fire, etc.) means the slot is an action
# button that happens to use a direction word as a positional modifier (e.g.
# "Left Punch", "Left Shoulder") -- not a joystick axis.
# Used by Invoke-ControlPropagation to guard against copying e.g. SF3's D-pad
# Up binding into a target game's "Left Punch" slot when both share the same
# InputMapping key (P1ButtonUp) but mean completely different physical controls.
function Test-ButtonNameDirectional {
    param([string]$name)
    $n = $name.Trim() -replace '(?i)^\s*(player\s*[12]|p[12])\s+', ''
    $words = @($n -split '\s+' | Where-Object { $_ -ne '' })
    if ($words.Count -eq 0) { return $false }
    $dirWords = @('up','down','left','right','north','south','east','west')
    foreach ($w in $words) {
        if ($dirWords -notcontains $w.ToLowerInvariant()) { return $false }
    }
    return $true
}

# AnalogType is absent on many template buttons; it defaults to None on both
# sides so a minimal template button still matches a bound archetype button.
function Get-ButtonKey {
    param($btn)
    $imNode = $btn.SelectSingleNode("InputMapping")
    if ($null -eq $imNode -or [string]::IsNullOrWhiteSpace($imNode.InnerText)) { return $null }
    $im = $imNode.InnerText.Trim()
    $atNode = $btn.SelectSingleNode("AnalogType")
    if ($atNode -and -not [string]::IsNullOrWhiteSpace($atNode.InnerText)) {
        $at = $atNode.InnerText.Trim()
    } else {
        $at = "None"
    }
    return "$im|$at"
}

# Classifies a profile's control family from its button set. This is what
# keeps bindings from crossing between game types (a wheel binding can never
# land on a gun, because driving and lightgun are different classes).
# Infers the control family from a profile's AnalogType values.
# NOTE: "spinner" cannot be auto-detected from AnalogType alone -- spinner
# games must be assigned via familyOverride in overrides.json.
function Get-ProfileFamily {
    param($doc)
    $hasWheel = $false; $hasGun = $false; $hasTrackball = $false; $hasOtherAxis = $false
    foreach ($btn in (Get-ButtonNodes $doc)) {
        $imNode = $btn.SelectSingleNode("InputMapping")
        $im = if ($imNode) { $imNode.InnerText.Trim() } else { "" }
        $atNode = $btn.SelectSingleNode("AnalogType")
        $at = if ($atNode -and -not [string]::IsNullOrWhiteSpace($atNode.InnerText)) { $atNode.InnerText.Trim() } else { "None" }
        if ($im -eq "P1Trackball" -or $im -eq "P2Trackball") { $hasTrackball = $true }
        switch ($at) {
            "Wheel"                 { $hasWheel = $true }
            "Gas"                   { $hasWheel = $true }
            "Brake"                 { $hasWheel = $true }
            "AnalogJoystick"        { $hasGun = $true }   # TeknoParrot uses analog joystick axes to represent lightgun aim
            "AnalogJoystickReverse" { $hasGun = $true }
            "None"                  { }
            default                 { $hasOtherAxis = $true }
        }
    }
    if ($hasWheel)     { return "driving"   }
    if ($hasGun)       { return "lightgun"  }
    if ($hasTrackball) { return "trackball" }
    if ($hasOtherAxis) { return "analog"    }
    return "button"
}

# Reads the "Input API" FieldValue, or $null if the profile has no such field.
function Get-ProfileInputApi {
    param($doc)
    $f = $doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral 'Input API')]")
    if ($null -eq $f) { return $null }
    $v = $f.SelectSingleNode("FieldValue")
    if ($null -eq $v) { return $null }
    return $v.InnerText.Trim()
}

# What a profile itself says about RawInput (issue #42). Read-only; nothing is ever written from this.
# RawInput: Supported = a button already has a RawInput binding or the Input API field lists RawInput; Unsupported = the
# Input API field lists other options only; Unknown = the profile says nothing about it.
# RawInputTrackball: Supported only when the profile names RawInputTrackball exactly (as an element, a field name or an option);
# Unsupported when RawInput itself is Unsupported; anything else is Unknown. Unfamiliar names are never treated as support.
function Get-ProfileRawInputCapability {
    param($Doc)
    $raw = 'Unknown'
    $trackball = 'Unknown'
    if ($null -ne $Doc -and $null -ne $Doc.SelectSingleNode('/GameProfile')) {
        $hasBinding = $false
        foreach ($button in @(Get-ButtonNodes $Doc)) {
            if ($null -ne $button.SelectSingleNode('RawInputButton')) { $hasBinding = $true; break }
        }
        $apiField = $Doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral 'Input API')]")
        $options = @()
        if ($null -ne $apiField) { $options = @($apiField.SelectNodes('FieldOptions/string') | ForEach-Object { $_.InnerText.Trim() }) }
        if ($hasBinding -or $options -contains 'RawInput') { $raw = 'Supported' }
        elseif ($options.Count -gt 0) { $raw = 'Unsupported' }
        $namesTrackball = ($null -ne $Doc.SelectSingleNode('//RawInputTrackball')) -or
            ($null -ne $Doc.SelectSingleNode("//FieldName[normalize-space(.)='RawInputTrackball']")) -or
            ($null -ne $Doc.SelectSingleNode("//FieldOptions/string[normalize-space(.)='RawInputTrackball']"))
        if ($namesTrackball) { $trackball = 'Supported' }
        elseif ($raw -eq 'Unsupported') { $trackball = 'Unsupported' }
    }
    return [pscustomobject]@{ RawInput = $raw; RawInputTrackball = $trackball }
}

# Sets the "Input API" FieldValue, but only if the field exists AND lists the
# requested API among its options. Returns $true on success. This matters
# because a RawInput binding will not work if the profile's API says XInput.
# Sets the "Input API" FieldValue. Normally only succeeds if the profile's
# FieldOptions already lists the requested API -- this matters because a
# RawInput binding will not work if the profile's API says XInput. The one
# exception is "MergedInput": TeknoParrot's own UI has been confirmed
# (issue #1) to dynamically materialize "MergedInput" into a legacy
# profile's on-disk FieldOptions the first time it's selected there, so an
# absent FieldOptions entry for that specific value does not mean the
# profile can't actually use it -- it just hasn't been touched in the TP
# UI yet. Mirror that behavior here so a propagated XInput-style binding
# is actually visible/usable without requiring the user to manually
# re-toggle every target game in the TeknoParrot UI first.
function Set-ProfileInputApi {
    param($doc, [string]$api)
    $f = $doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral 'Input API')]")
    if ($null -eq $f) { return $false }
    $optsNode = $f.SelectSingleNode("FieldOptions")
    $opts = if ($optsNode) { @($optsNode.SelectNodes("string") | ForEach-Object { $_.InnerText.Trim() }) } else { @() }
    if ($opts -notcontains $api) {
        if ($api -ne 'MergedInput' -or $null -eq $optsNode) { return $false }
        $newOpt = $doc.CreateElement("string")
        $newOpt.InnerText = $api
        [void]$optsNode.AppendChild($newOpt)
    }
    $v = $f.SelectSingleNode("FieldValue")
    if ($null -eq $v) { return $false }
    $v.InnerText = $api
    return $true
}

# ===== TpmController: controller layout and safe apply (player 1) =====
# The user picks one controller layout (Xbox, PlayStation, Nintendo or arcade stick) once; TPM keeps it in its own small file.
# The layout is then written into the XInput slots of a game, but only for controls that the game's own contract lists
# (Get-TpmGameControlContract), only when the game file is the revision that contract was read from, and never over an
# Xbox binding that is already there. Keyboard, arcade-encoder and other bindings are never touched. Test and Service stay
# empty unless the user gave them a button. Every write has a verified backup first, is read back and compared, and is put
# back byte for byte if the check fails.
# The codes are the standard Microsoft XInput button flags. Triggers and analog axes are not written: TPM does not guess them.

# The pad buttons TPM can write and their XInput codes.
function Get-TpmPadButtons {
    return [ordered]@{
        'A' = 0x1000; 'B' = 0x2000; 'X' = 0x4000; 'Y' = 0x8000; 'LB' = 0x0100; 'RB' = 0x0200
        'Back' = 0x0020; 'Start' = 0x0010; 'L3' = 0x0040; 'R3' = 0x0080
        'D-pad Up' = 0x0001; 'D-pad Down' = 0x0002; 'D-pad Left' = 0x0004; 'D-pad Right' = 0x0008
    }
}

# The game controls a layout can fill, in screen order, with their plain names.
function Get-TpmBaselineSlots {
    return [ordered]@{
        'Coin1' = 'Coin'; 'P1ButtonStart' = 'Start'; 'P1ButtonUp' = 'Up'; 'P1ButtonDown' = 'Down'; 'P1ButtonLeft' = 'Left'; 'P1ButtonRight' = 'Right'
        'P1Button1' = 'Button 1'; 'P1Button2' = 'Button 2'; 'P1Button3' = 'Button 3'; 'P1Button4' = 'Button 4'; 'P1Button5' = 'Button 5'; 'P1Button6' = 'Button 6'
        'Test' = 'Test'; 'Service1' = 'Service'
    }
}

# The four built-in starting layouts. Names changes only what the screen calls a pad button; the codes are the same.
# PlayStation and Nintendo pads need something that shows them to Windows as an Xbox (XInput) controller; the buttons are
# matched by position (the bottom face button is Button 1). An arcade stick must be switched to its Xbox (XInput) mode.
function Get-TpmBaselinePresets {
    $shared = [ordered]@{ Coin1 = 'Back'; P1ButtonStart = 'Start'; P1ButtonUp = 'D-pad Up'; P1ButtonDown = 'D-pad Down'; P1ButtonLeft = 'D-pad Left'; P1ButtonRight = 'D-pad Right' }
    $pad = [ordered]@{ P1Button1 = 'A'; P1Button2 = 'B'; P1Button3 = 'Y'; P1Button4 = 'X'; P1Button5 = 'LB'; P1Button6 = 'RB' }
    $stick = [ordered]@{ P1Button1 = 'X'; P1Button2 = 'Y'; P1Button3 = 'RB'; P1Button4 = 'A'; P1Button5 = 'B'; P1Button6 = 'LB' }
    $none = [ordered]@{ Test = ''; Service1 = '' }
    $build = {
        param($Buttons)
        $slots = [ordered]@{}
        foreach ($part in @($shared, $Buttons, $none)) { foreach ($key in $part.Keys) { $slots[$key] = [string]$part[$key] } }
        return $slots
    }
    return [ordered]@{
        Xbox        = [pscustomobject]@{ Title = 'Xbox controller'; Names = @{}; Slots = (& $build $pad) }
        PlayStation = [pscustomobject]@{ Title = 'PlayStation controller'; Names = @{ A = 'Cross'; B = 'Circle'; X = 'Square'; Y = 'Triangle'; LB = 'L1'; RB = 'R1'; Back = 'Share'; Start = 'Options' }; Slots = (& $build $pad) }
        Nintendo    = [pscustomobject]@{ Title = 'Nintendo controller'; Names = @{ A = 'B'; B = 'A'; X = 'Y'; Y = 'X'; LB = 'L'; RB = 'R'; Back = 'Minus'; Start = 'Plus' }; Slots = (& $build $pad) }
        ArcadeStick = [pscustomobject]@{ Title = 'Arcade stick (set to Xbox mode)'; Names = @{}; Slots = (& $build $stick) }
    }
}

# A new layout from one of the presets. SelectionSource is always UserSelected: TPM only ever suggests a preset.
function New-TpmBaseline {
    param([Parameter(Mandatory)][string]$Preset)
    $presets = Get-TpmBaselinePresets
    if (-not $presets.Contains($Preset)) { throw "Unknown controller layout '$Preset'." }
    return [pscustomobject]@{ Schema = 'TpmControllerBaseline/v1'; Preset = $Preset; SelectionSource = 'UserSelected'; Slots = $presets[$Preset].Slots }
}

# Plain-word problems with a layout; an empty list means it can be used. A pad button may serve only one game control.
function Test-TpmBaseline {
    param($Baseline)
    $problems = New-Object System.Collections.Generic.List[string]
    if ($null -eq $Baseline -or [string]$Baseline.Schema -ne 'TpmControllerBaseline/v1') { return @('The layout file is not one TPM wrote.') }
    if (-not (Get-TpmBaselinePresets).Contains([string]$Baseline.Preset)) { [void]$problems.Add('The layout names a starting layout TPM does not know.') }
    $buttons = Get-TpmPadButtons
    $slots = Get-TpmBaselineSlots
    $used = @{}
    foreach ($key in @($Baseline.Slots.Keys)) {
        $value = [string]$Baseline.Slots[$key]
        if (-not $slots.Contains($key)) { [void]$problems.Add("The layout has a control TPM does not know: $key."); continue }
        if ($value -eq '') { continue }
        if (-not $buttons.Contains($value)) { [void]$problems.Add("The layout uses a pad button TPM does not know: $value."); continue }
        if ($used.ContainsKey($value)) { [void]$problems.Add(('{0} is used for both {1} and {2}.' -f $value, $used[$value], $slots[$key])) } else { $used[$value] = $slots[$key] }
    }
    return @($problems)
}

function Get-TpmBaselinePath { param([Parameter(Mandatory)][string]$StateDir) return (Join-Path $StateDir 'ControllerBaseline.json') }

# The saved layout, or $null when none is saved or the file is not usable (the user is then asked to choose again).
function Read-TpmBaseline {
    param([Parameter(Mandatory)][string]$StateDir)
    $path = Get-TpmBaselinePath -StateDir $StateDir
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return $null }
    try {
        $raw = [System.IO.File]::ReadAllText($path) | ConvertFrom-Json -ErrorAction Stop
        $slots = [ordered]@{}
        foreach ($property in $raw.Slots.PSObject.Properties) { $slots[$property.Name] = [string]$property.Value }
        $baseline = [pscustomobject]@{ Schema = [string]$raw.Schema; Preset = [string]$raw.Preset; SelectionSource = [string]$raw.SelectionSource; Slots = $slots }
    } catch { Write-Log ('Baseline: the saved controller layout could not be read -- ' + $_.Exception.Message); return $null }
    $problems = @(Test-TpmBaseline -Baseline $baseline)
    if ($problems.Count -gt 0) { Write-Log ('Baseline: the saved controller layout is not usable: ' + ($problems -join ' ')); return $null }
    return $baseline
}

function Save-TpmBaseline {
    param([Parameter(Mandatory)][string]$StateDir, [Parameter(Mandatory)]$Baseline)
    $problems = @(Test-TpmBaseline -Baseline $Baseline)
    if ($problems.Count -gt 0) { throw ('The layout was not saved: ' + ($problems -join ' ')) }
    [void][System.IO.Directory]::CreateDirectory($StateDir)
    Write-TpmAtomicTextFile -Path (Get-TpmBaselinePath -StateDir $StateDir) -Text ($Baseline | ConvertTo-Json -Depth 4) -Operation 'controller layout file'
}

# The layout as rows, one per control that has a pad button. Label is what the user's own controller calls that button.
function Get-TpmBaselineLayout {
    param([Parameter(Mandatory)]$Baseline)
    $buttons = Get-TpmPadButtons
    $slots = Get-TpmBaselineSlots
    $names = @{}
    $presets = Get-TpmBaselinePresets
    if ($presets.Contains([string]$Baseline.Preset)) { $names = $presets[[string]$Baseline.Preset].Names }
    foreach ($mapping in $slots.Keys) {
        $padName = [string]$Baseline.Slots[$mapping]
        if ([string]::IsNullOrEmpty($padName) -or -not $buttons.Contains($padName)) { continue }
        [pscustomobject]@{ Mapping = $mapping; Slot = $slots[$mapping]; Pad = $padName; Code = [int]$buttons[$padName]; Label = $(if ($names.ContainsKey($padName)) { [string]$names[$padName] } else { $padName }) }
    }
}

# Plain lines that show a layout on screen.
function Get-TpmBaselineSummaryLines {
    param([Parameter(Mandatory)]$Baseline)
    $title = (Get-TpmBaselinePresets)[[string]$Baseline.Preset].Title
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add('Your controller layout: ' + $title)
    $layout = @(Get-TpmBaselineLayout -Baseline $Baseline)
    foreach ($row in $layout) { [void]$lines.Add(('{0}  ->  {1}' -f $row.Slot, $row.Label)) }
    $empty = @((Get-TpmBaselineSlots).Keys | Where-Object { [string]::IsNullOrEmpty([string]$Baseline.Slots[$_]) } | ForEach-Object { (Get-TpmBaselineSlots)[$_] })
    if ($empty.Count -gt 0) { [void]$lines.Add('Left empty on purpose: ' + ($empty -join ', ') + '. A stick click should not open a test menu.') }
    return @($lines)
}

# Where the layout comes from, in plain words. Shown behind Details and written to the log.
function Get-TpmBaselineLayoutSource {
    return 'The Manager''s built-in layouts (Xbox, PlayStation, Nintendo, arcade stick) with any change you made. Buttons use the standard Xbox button codes. Coin on Back, Start on Start, and the six action buttons follow the common arcade-to-gamepad layout used by public emulator guides. No data was copied from another program.'
}

# Plain words for each reason a game is left alone.
function Get-TpmBaselineReasonText {
    param([string]$ReasonCode)
    switch ($ReasonCode) {
        'NoTemplate'   { return 'TPM could not find TeknoParrot''s own file for this game, so it cannot tell which controls the game needs.' }
        'Stale'        { return 'This game''s saved settings are for a different version of the game file than TeknoParrot has now. Open the game once in TeknoParrotUI, then try again.' }
        'InputApi'     { return 'This game''s input type setting does not match what the game offers.' }
        'FieldMissing' { return 'A control the game needs is missing from its saved settings. Open the game once in TeknoParrotUI, then try again.' }
        'Collision'    { return 'An Xbox button the layout wants is already used by another control in this game.' }
        'Changed'      { return 'The game''s files changed after the preview, so nothing was saved. Run it again.' }
        'NoXbox'       { return 'This game does not have an Xbox controller setting.' }
        'Unreadable'   { return 'The settings file for this game could not be read.' }
        'NoControls'   { return 'TPM does not recognize the names this game uses for its player 1 controls, so it cannot tell which controls the game needs.' }
        default        { return '' }
    }
}

# True when a game's name for a direction slot is a plain direction: "Player 1 Up", "P1 Left (Digital)", "Pad Right", "Down".
function Test-TpmDirectionName {
    param([string]$Name)
    $plain = ($Name -replace '(?i)\(digital\)', '') -replace '(?i)\b(d-?pad|pad)\b', ''
    return (Test-ButtonNameDirectional $plain)
}

# Read-only. Says what the layout would do to one game, bound to the game's own contract.
# Status: Ready, NoChange, Unsupported (no Xbox setting), Refused (see ReasonCode), Unreadable.
# Row actions: Add (the slot is free), Keep (an Xbox binding is already there), NotInGame (the contract does not list the control).
function Get-TpmBaselineGamePlan {
    param([Parameter(Mandatory)][string]$ProfilePath, [Parameter(Mandatory)][string]$GameProfilesDir, [Parameter(Mandatory)]$Layout)
    $code = [System.IO.Path]::GetFileNameWithoutExtension($ProfilePath)
    $plan = [pscustomobject]@{
        Code = $code; Title = $code; Status = 'Unreadable'; ReasonCode = 'Unreadable'; Reason = (Get-TpmBaselineReasonText 'Unreadable'); Rows = @(); AddCount = 0; KeepCount = 0; NotInGameCount = 0
        StillNeeds = @(); CurrentApi = ''; NeedsApiChange = $false; Source = ''; Signature = ''; Doc = $null; TemplateSha256 = ''; TemplatePath = ''
    }
    $refuse = { param($Status, $ReasonCode) $plan.Status = $Status; $plan.ReasonCode = $ReasonCode; $plan.Reason = Get-TpmBaselineReasonText $ReasonCode; return $plan }
    try { $doc = Read-Xml $ProfilePath; if ($null -eq $doc.GameProfile) { return $plan } } catch { return $plan }
    $plan.Doc = $doc
    try { $plan.Title = Get-TpmProfileFriendlyTitle -Doc $doc -BaseName $code } catch { $plan.Title = $code }
    $template = Read-TpmGameTemplate -Code $code -GameProfilesDir $GameProfilesDir
    if ($null -eq $template) { return (& $refuse 'Refused' 'NoTemplate') }
    $plan.TemplateSha256 = $template.Sha256; $plan.TemplatePath = $template.Path
    $resolved = Get-TpmGameControlContract -Code $code -UserDoc $doc -Template $template
    if ($null -eq $resolved.Contract) { return (& $refuse 'Refused' $(if ($resolved.Why -eq 'NoControls') { 'NoControls' } else { 'NoTemplate' })) }
    $plan.Source = $resolved.Source
    if ($resolved.Facts.Fit -eq 'Unknown') { return (& $refuse 'Refused' 'Stale') }
    if ($resolved.Facts.Fit -eq 'Unsupported') { return (& $refuse 'Refused' 'InputApi') }

    $apiField = $doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral 'Input API')]")
    $apiOptions = @()
    if ($null -ne $apiField) { $apiOptions = @($apiField.SelectNodes('FieldOptions/string') | ForEach-Object { $_.InnerText.Trim() }) }
    $plan.CurrentApi = [string](Get-ProfileInputApi $doc)
    # A game the user already put on MergedInput keeps it: that choice is theirs, and only free Xbox slots are filled.
    $plan.NeedsApiChange = ($plan.CurrentApi -ne 'XInput' -and $plan.CurrentApi -ne 'MergedInput')
    if ($plan.NeedsApiChange -and $apiOptions -notcontains 'XInput') { return (& $refuse 'Unsupported' 'NoXbox') }

    $nodes = @(Get-ButtonNodes $doc)
    $byMapping = @{}
    foreach ($node in $nodes) {
        $key = Get-ButtonKey $node
        if ($key -and $key -like '*|None' -and -not $byMapping.ContainsKey($key)) { $byMapping[$key] = $node }
    }
    $used = @{}
    foreach ($node in $nodes) {
        $xi = $node.SelectSingleNode('XInputButton')
        if ($null -eq $xi) { continue }
        $isButton = $xi.SelectSingleNode('IsButton'); $buttonCode = $xi.SelectSingleNode('ButtonCode')
        if ($null -ne $isButton -and $null -ne $buttonCode -and $isButton.InnerText.Trim() -ieq 'true') { $used[$buttonCode.InnerText.Trim()] = $true }
    }
    $controls = @{}
    foreach ($control in @($resolved.Contract.SemanticControls)) { $controls[[string]$control.ControlId] = $control }

    $rows = New-Object System.Collections.ArrayList
    $problem = ''
    foreach ($item in @($Layout)) {
        $control = $controls[$item.Mapping]
        $action = 'NotInGame'; $node = $null; $index = -1
        if ($null -ne $control -and $control.Kind -eq 'Button') {
            $node = $byMapping[($item.Mapping + '|None')]
            if ($null -eq $node) { $problem = 'FieldMissing'; continue }
            $index = [array]::IndexOf($nodes, $node)
            if ($item.Mapping -match '^P1Button(Up|Down|Left|Right)$' -and -not (Test-TpmDirectionName -Name ([string]$control.Meaning))) {
                # The game names this slot something other than a plain direction (for example "Menu Up"): a D-pad button is a guess.
                $node = $null; $index = -1; $action = 'Ambiguous'
            } else {
                $action = if ($null -ne $node.SelectSingleNode('XInputButton')) { 'Keep' } else { 'Add' }
                if ($action -eq 'Add' -and $used.ContainsKey([string]$item.Code)) { if (-not $problem) { $problem = 'Collision' } }
            }
        }
        $meaning = if ($null -ne $control) { [string]$control.Meaning } else { [string]$item.Slot }
        [void]$rows.Add([pscustomobject]@{ Mapping = $item.Mapping; Meaning = $meaning; Label = $item.Label; Code = $item.Code; Action = $action; Node = $node; Index = $index })
    }
    $plan.Rows = @($rows)
    $plan.AddCount = @($rows | Where-Object Action -eq 'Add').Count
    $plan.KeepCount = @($rows | Where-Object Action -eq 'Keep').Count
    $plan.NotInGameCount = @($rows | Where-Object Action -eq 'NotInGame').Count
    # Required controls that are not set up and that the layout will not fill: the player does these in TeknoParrotUI.
    $filled = @($rows | Where-Object Action -eq 'Add' | ForEach-Object { $_.Mapping })
    $plan.StillNeeds = @($resolved.Contract.SemanticControls | Where-Object { $_.Requirement -eq 'Required' -and @($resolved.Facts.UsableControlIds) -notcontains $_.ControlId -and $filled -notcontains $_.ControlId } | ForEach-Object { [string]$_.Meaning })
    if ($problem) { return (& $refuse 'Refused' $problem) }
    $plan.Status = if ($plan.AddCount -eq 0 -and -not $plan.NeedsApiChange) { 'NoChange' } else { 'Ready' }
    $plan.ReasonCode = ''; $plan.Reason = ''
    $userSha = (Get-FileHash -LiteralPath $ProfilePath -Algorithm SHA256).Hash
    $plan.Signature = '{0}|{1}|{2}|{3}' -f $userSha, $template.Sha256, (@($rows | Where-Object Action -eq 'Add' | ForEach-Object { '{0}={1}' -f $_.Mapping, $_.Code }) -join ','), $plan.NeedsApiChange
    return $plan
}

# Plain lines for one plan: what will be set, what stays, and what the player still does in TeknoParrotUI.
function Get-TpmBaselinePlanLines {
    param([Parameter(Mandatory)]$Plan)
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($row in @($Plan.Rows | Where-Object Action -eq 'Add')) { [void]$lines.Add(('{0}  ->  {1}' -f $row.Meaning, $row.Label)) }
    if ($Plan.KeepCount -gt 0) { [void]$lines.Add(('{0} buttons already had an Xbox setting and stay as they are.' -f $Plan.KeepCount)) }
    $ambiguous = @($Plan.Rows | Where-Object Action -eq 'Ambiguous' | ForEach-Object { $_.Meaning })
    if ($ambiguous.Count -gt 0) { [void]$lines.Add('Not set, because the game does not call them a plain direction (TPM does not guess): ' + ($ambiguous -join ', ') + '.') }
    if ($Plan.NeedsApiChange) { [void]$lines.Add('The game''s input type is switched to Xbox (XInput). It may stop using an arcade encoder.') }
    if (@($Plan.StillNeeds).Count -gt 0) { [void]$lines.Add('Still needs you in TeknoParrotUI (TPM does not guess these): ' + (@($Plan.StillNeeds) -join ', ') + '.') }
    return @($lines)
}

# Adds one Xbox binding to a button node, in the order TeknoParrot writes its children.
function Add-TpmXInputBinding {
    param([Parameter(Mandatory)]$Doc, [Parameter(Mandatory)]$ButtonNode, [Parameter(Mandatory)][int]$Code)
    $xi = $Doc.CreateElement('XInputButton')
    foreach ($pair in @(
        @('IsLeftThumbX','false'), @('IsRightThumbX','false'), @('IsLeftThumbY','false'), @('IsRightThumbY','false'),
        @('IsAxisMinus','false'), @('IsLeftTrigger','false'), @('IsRightTrigger','false'),
        @('ButtonCode',[string]$Code), @('IsButton','true'), @('ButtonIndex','0'), @('XInputIndex','0'))) {
        $e = $Doc.CreateElement($pair[0]); $e.InnerText = $pair[1]; [void]$xi.AppendChild($e)
    }
    $raw = $ButtonNode.SelectSingleNode('RawInputButton')
    $dir = $ButtonNode.SelectSingleNode('DirectInputButton')
    if ($null -ne $raw) { [void]$ButtonNode.InsertBefore($xi, $raw) }
    elseif ($null -ne $dir) { [void]$ButtonNode.InsertAfter($xi, $dir) }
    else { [void]$ButtonNode.InsertAfter($xi, $ButtonNode.SelectSingleNode('ButtonName')) }
}

# Compares a saved profile with what the plan promised. Returns '' when it matches, otherwise the problem in plain words.
# Every button the plan did not touch must be exactly as it was; every added button must read back with its code.
function Test-TpmBaselineWritten {
    param([Parameter(Mandatory)]$Doc, [Parameter(Mandatory)]$Plan, [Parameter(Mandatory)][string[]]$BeforeXml)
    $nodes = @(Get-ButtonNodes $Doc)
    if ($nodes.Count -ne $BeforeXml.Count) { return 'The saved profile has a different number of buttons.' }
    $added = @{}
    foreach ($row in @($Plan.Rows | Where-Object Action -eq 'Add')) { $added[$row.Index] = $row }
    for ($i = 0; $i -lt $nodes.Count; $i++) {
        if (-not $added.ContainsKey($i)) {
            if ($nodes[$i].OuterXml -ne $BeforeXml[$i]) { return 'A button that should not change was changed.' }
            continue
        }
        $xi = $nodes[$i].SelectSingleNode('XInputButton')
        if ($null -eq $xi -or $xi.SelectSingleNode('ButtonCode').InnerText.Trim() -ne [string]$added[$i].Code -or $xi.SelectSingleNode('XInputIndex').InnerText.Trim() -ne '0') { return ('{0} did not read back as saved.' -f $added[$i].Meaning) }
        $copy = $nodes[$i].CloneNode($true)
        [void]$copy.RemoveChild($copy.SelectSingleNode('XInputButton'))
        if ($copy.OuterXml -ne $BeforeXml[$i]) { return ('{0} changed more than its Xbox setting.' -f $added[$i].Meaning) }
    }
    if ($Plan.NeedsApiChange -and (Get-ProfileInputApi $Doc) -ne 'XInput') { return 'The input type did not read back as Xbox (XInput).' }
    return ''
}

# Applies the layout to one profile file. With -DryRun nothing is written. ExpectedSignature is the Signature of the preview
# the user approved; when the game's files are not the same any more nothing is written.
# Order: read, plan, verified backup, write, read back and compare, put the old bytes back if the check fails.
function Invoke-TpmBaselineApply {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$ProfilePath, [Parameter(Mandatory)][string]$GameProfilesDir,
        [Parameter(Mandatory)]$Layout, [bool]$DryRun = $true, [hashtable]$BackupState = $null, [string]$ExpectedSignature = ''
    )
    $plan = Get-TpmBaselineGamePlan -ProfilePath $ProfilePath -GameProfilesDir $GameProfilesDir -Layout $Layout
    $result = [pscustomobject]@{
        Path = $ProfilePath; Code = $plan.Code; Title = $plan.Title; Status = $plan.Status; Added = 0; Kept = $plan.KeepCount; NotInGame = $plan.NotInGameCount; ApiChanged = $false
        Backup = $null; Reason = $plan.Reason; ReasonCode = $plan.ReasonCode; Verified = $false; StillNeeds = @($plan.StillNeeds); Signature = $plan.Signature; Plan = $plan
    }
    if ($plan.Status -ne 'Ready') { return $result }
    if (-not $DryRun -and $ExpectedSignature -and $ExpectedSignature -ne $plan.Signature) {
        $result.Status = 'Refused'; $result.ReasonCode = 'Changed'; $result.Reason = Get-TpmBaselineReasonText 'Changed'
        return $result
    }
    $result.Added = $plan.AddCount
    $result.ApiChanged = $plan.NeedsApiChange
    if ($DryRun) { $result.Status = 'WouldChange'; return $result }
    $original = [System.IO.File]::ReadAllBytes($ProfilePath)
    $doc = $plan.Doc
    try {
        # One backup covers a whole batch: the first write makes it, later writes reuse it.
        if ($null -ne $BackupState -and $null -ne $BackupState.Backup) { $result.Backup = $BackupState.Backup }
        else {
            $result.Backup = New-TpmVerifiedUserProfilesBackup -UserProfilesDir $UserProfilesDir -Label 'ControllerLayout'
            if ($null -ne $BackupState) { $BackupState.Backup = $result.Backup }
        }
        if (-not $result.Backup.Verified) { throw 'The safety backup could not be verified.' }
        $beforeXml = @(Get-ButtonNodes $doc | ForEach-Object { $_.OuterXml })
        foreach ($row in @($plan.Rows | Where-Object Action -eq 'Add')) { Add-TpmXInputBinding -Doc $doc -ButtonNode $row.Node -Code $row.Code }
        if ($plan.NeedsApiChange -and -not (Set-ProfileInputApi $doc 'XInput')) { throw 'The Input API could not be set.' }
        Save-XmlMaybe $doc $ProfilePath $false
        $problem = Test-TpmBaselineWritten -Doc (Read-Xml $ProfilePath) -Plan $plan -BeforeXml $beforeXml
        if (-not $problem -and (Get-FileHash -LiteralPath $plan.TemplatePath -Algorithm SHA256).Hash.ToLowerInvariant() -ne $plan.TemplateSha256) { $problem = 'TeknoParrot''s game file changed while TPM was working.' }
        if ($problem) { throw ('The saved profile did not read back correctly. ' + $problem) }
        $result.Status = 'Changed'; $result.Verified = $true
    } catch {
        [System.IO.File]::WriteAllBytes($ProfilePath, $original)
        $result.Status = 'Failed'; $result.Reason = $_.Exception.Message; $result.Added = 0; $result.ApiChanged = $false
        $restored = [System.IO.File]::ReadAllBytes($ProfilePath)
        if ($restored.Length -ne $original.Length -or [System.Convert]::ToBase64String($restored) -ne [System.Convert]::ToBase64String($original)) { $result.Reason += ' The original file could not be put back exactly. Use Restore backup in the main menu.' }
    }
    return $result
}

# Applies the layout to many profile files with ONE backup. A failed backup stops every later write.
# Signatures maps a profile path to the Signature its approved preview had.
function Invoke-TpmBaselineBatch {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string[]]$ProfilePaths, [Parameter(Mandatory)][string]$GameProfilesDir,
        [Parameter(Mandatory)]$Layout, [bool]$DryRun = $true, [hashtable]$Signatures = @{}, [hashtable]$BackupState = $null
    )
    $state = if ($null -ne $BackupState) { $BackupState } else { @{ Backup = $null } }
    $results = New-Object System.Collections.ArrayList
    foreach ($p in $ProfilePaths) {
        if (-not $DryRun -and $null -ne $state.Backup -and -not $state.Backup.Verified) {
            [void]$results.Add([pscustomobject]@{ Path = $p; Code = [System.IO.Path]::GetFileNameWithoutExtension($p); Title = [System.IO.Path]::GetFileNameWithoutExtension($p); Status = 'Failed'; Added = 0; Kept = 0; NotInGame = 0; ApiChanged = $false; Backup = $state.Backup; Reason = 'The safety backup could not be verified.'; ReasonCode = ''; Verified = $false; StillNeeds = @(); Signature = ''; Plan = $null })
            continue
        }
        [void]$results.Add((Invoke-TpmBaselineApply -UserProfilesDir $UserProfilesDir -ProfilePath $p -GameProfilesDir $GameProfilesDir -Layout $Layout -DryRun $DryRun -BackupState $state -ExpectedSignature ([string]$Signatures[$p])))
    }
    $all = @($results)
    return [pscustomobject]@{
        Results     = $all
        Changed     = @($all | Where-Object Status -in @('Changed', 'WouldChange')).Count
        Unchanged   = @($all | Where-Object Status -eq 'NoChange').Count
        Unsupported = @($all | Where-Object Status -eq 'Unsupported').Count
        Refused     = @($all | Where-Object Status -eq 'Refused').Count
        Failed      = @($all | Where-Object Status -in @('Failed', 'Unreadable')).Count
        Backup      = $state.Backup
    }
}

# Plain lines that sum up a batch: what was (or would be) set up and why the rest was left alone.
function Get-TpmBaselineBatchLines {
    param([Parameter(Mandatory)]$Batch, [bool]$DryRun = $true)
    $lines = New-Object System.Collections.Generic.List[string]
    $buttons = (@($Batch.Results | Where-Object { $_.Status -in @('Changed', 'WouldChange') } | ForEach-Object { $_.Added }) | Measure-Object -Sum).Sum
    if ($Batch.Changed -gt 0) { [void]$lines.Add((($(if ($DryRun) { 'Ready to set up {0} ({1} buttons).' } else { 'Set up {0} ({1} buttons).' })) -f (Format-TpmGameCount -Count $Batch.Changed), [int]$buttons)) }
    if ($Batch.Unchanged -gt 0) { [void]$lines.Add(('Already set up: {0}.' -f (Format-TpmGameCount -Count $Batch.Unchanged))) }
    $left = @($Batch.Results | Where-Object { $_.Status -in @('Refused', 'Unsupported', 'Unreadable', 'Failed') })
    if ($left.Count -gt 0) {
        [void]$lines.Add(('Left alone: {0}.' -f (Format-TpmGameCount -Count $left.Count)))
        foreach ($group in @($left | Group-Object { if ($_.Status -eq 'Unsupported') { 'NoXbox' } elseif ($_.ReasonCode) { $_.ReasonCode } else { $_.Status } } | Sort-Object Name)) {
            $text = Get-TpmBaselineReasonText $group.Name
            if (-not $text) { $text = [string]$group.Group[0].Reason }
            [void]$lines.Add(('  {0}: {1}' -f (Format-TpmGameCount -Count $group.Count), $text))
        }
    }
    return @($lines)
}

# Plain words shown before any layout is applied or tested. Data only; the screen prints it.
function Get-TpmControllerPowerReminder {
    return @(
        'Before you start, turn on your controllers.'
        'Wireless controllers and any other controller that needs power must be on and connected now.'
        'If a controller is off, it cannot be found and its buttons cannot be tested.'
        'Wired controllers only need to be plugged in.'
    )
}

# Finds profile files whose name contains the typed words (spaces and case ignored). Core, no screen output.
function Find-TpmBaselineProfiles {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$Text, [int]$Max = 8)
    $needle = ([regex]::Replace($Text, '\s+', '')).ToLowerInvariant()
    if ($needle.Length -lt 2) { return @() }
    $files = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'Game search' -EnumerationErrorAction SilentlyContinue)
    return @($files | Where-Object { $_.BaseName.ToLowerInvariant().Contains($needle) } | Sort-Object BaseName | Select-Object -First $Max)
}

# Asks once for the layout, shows it, and lets the user change single buttons. Saves it and returns it, or $null when the
# user goes back. A connected Xbox-style controller only pre-selects the Xbox choice; the answer is always the user's.
function Invoke-TpmBaselineChooseScreen {
    param([Parameter(Mandatory)][string]$StateDir, $Current = $null)
    Write-Host ''
    Write-TpmText -Text 'Choose your controller layout' -Color Cyan
    Write-TpmText -Text 'You choose this once. TPM uses it for every game you set up, and you can change it at any time. Nothing in your games changes now.' -Color DarkCyan
    $presets = Get-TpmBaselinePresets
    $keys = @($presets.Keys)
    $default = '1'
    try {
        $evidence = Get-TpmControllerEvidence
        if (@($evidence.DeviceObservations | Where-Object { $_.DeviceClass -eq 'XboxStylePad' -and $_.Confidence -eq 'High' }).Count -gt 0) { Write-TpmText -Text 'Found: an Xbox-style controller.' -Color Green }
    } catch { Write-Log ('Baseline: the controller check could not run -- ' + $_.Exception.Message) }
    if ($null -ne $Current) { $default = [string]([array]::IndexOf($keys, [string]$Current.Preset) + 1) }
    Write-Host ''
    for ($i = 0; $i -lt $keys.Count; $i++) { Write-TpmText -Text ('{0} = {1}' -f ($i + 1), $presets[$keys[$i]].Title) -Indent 4 }
    Write-TpmText -Text 'PlayStation and Nintendo controllers work here only when something shows them to Windows as an Xbox controller. An arcade stick must be switched to its Xbox mode.' -Color DarkGray
    $pick = Read-TpmChoice -Prompt ('  Choose 1 to {0}, or B to go back' -f $keys.Count) -Choices (@('B') + @(1..$keys.Count | ForEach-Object { [string]$_ })) -Default $default
    if ($pick -eq 'B') { return $null }
    $baseline = New-TpmBaseline -Preset $keys[[int]$pick - 1]
    if ($null -ne $Current -and [string]$Current.Preset -eq $baseline.Preset) { $baseline = $Current }
    $slots = Get-TpmBaselineSlots
    $buttons = Get-TpmPadButtons
    while ($true) {
        Write-Host ''
        foreach ($line in (Get-TpmBaselineSummaryLines -Baseline $baseline)) { Write-TpmText -Text $line -Indent 4 }
        Write-Host ''
        if ((Read-TpmChoice -Prompt '  K = keep this layout, C = change one button' -Choices @('K', 'C') -Default 'K') -eq 'K') { break }
        $slotKeys = @($slots.Keys)
        $slotRows = @($slotKeys | ForEach-Object { '{0}: {1}' -f $slots[$_], $(if ([string]::IsNullOrEmpty([string]$baseline.Slots[$_])) { 'empty' } else { [string]$baseline.Slots[$_] }) })
        $slotIndex = Read-TpmNumberedListChoice -Rows $slotRows -Prompt '  Which game control? (number, or B to go back)' -Heading 'Game controls:' -Visible $slotRows.Count
        if ($slotIndex -lt 0) { continue }
        $padRows = @(@($buttons.Keys) + @('Empty (no button)'))
        $padIndex = Read-TpmNumberedListChoice -Rows $padRows -Prompt ('  Which pad button for {0}? (number, or B to go back)' -f $slots[$slotKeys[$slotIndex]]) -Heading 'Pad buttons:' -Visible $padRows.Count
        if ($padIndex -lt 0) { continue }
        $chosen = if ($padIndex -ge $buttons.Count) { '' } else { [string]@($buttons.Keys)[$padIndex] }
        $trial = [pscustomobject]@{ Schema = $baseline.Schema; Preset = $baseline.Preset; SelectionSource = 'UserSelected'; Slots = [ordered]@{} }
        foreach ($key in $baseline.Slots.Keys) { $trial.Slots[$key] = [string]$baseline.Slots[$key] }
        $trial.Slots[$slotKeys[$slotIndex]] = $chosen
        $problems = @(Test-TpmBaseline -Baseline $trial)
        if ($problems.Count -gt 0) { Write-TpmText -Text ($problems -join ' ') -Color Yellow; Write-TpmText -Text 'Pick a different button, or change the other control first. Nothing was changed.' -Color Yellow; continue }
        $baseline = $trial
    }
    Save-TpmBaseline -StateDir $StateDir -Baseline $baseline
    Write-Log ('Baseline: layout saved: {0}. {1}' -f $baseline.Preset, (Get-TpmBaselineLayoutSource))
    Write-TpmText -Text 'Layout saved.' -Color Green
    return $baseline
}

# One undo question for a whole run: puts every game's settings back from the backup made before the first change.
function Invoke-TpmBaselineUndoPrompt {
    param([Parameter(Mandatory)][string]$UserProfilesDir, $Backup)
    $undoFolder = if ($null -ne $Backup) { [string]$Backup.Path } else { '' }
    if (-not $undoFolder -or (Read-TpmYesNo -Prompt '  Undo this and put your game settings back as they were? (Y/N)' -Default 'N') -ne 'Y') { return }
    $undo = Invoke-TpmProgressGroup -Title 'Undo controller change' -Action { Invoke-RestoreBackup -userProfilesDir $UserProfilesDir -SelectedBackupPath $undoFolder -AlreadyConfirmed }
    Write-Log ('Baseline: undo requested; restore reported {0}' -f [string]$undo.Outcome)
    Write-TpmText -Text ([string]$undo.Summary) -Color $(if ($undo.Outcome -eq 'SUCCEEDED') { 'Green' } else { 'Yellow' })
}

# Writes the preview for a batch: the plain summary, and the per-game list behind Details.
function Write-TpmBaselineBatchPreview {
    param([Parameter(Mandatory)]$Batch)
    foreach ($line in (Get-TpmBaselineBatchLines -Batch $Batch -DryRun $true)) { Write-TpmText -Text $line -Color DarkCyan }
    foreach ($r in @($Batch.Results)) {
        Write-Log ('Baseline preview: {0}: status={1} add={2} keep={3} reason={4}' -f $r.Code, $r.Status, $r.Added, $r.Kept, $r.ReasonCode)
    }
}

# The details list for a batch preview: one block per game that would change.
function Get-TpmBaselineBatchDetailBlocks {
    param([Parameter(Mandatory)]$Batch)
    $blocks = New-Object System.Collections.Generic.List[object]
    foreach ($r in @($Batch.Results | Where-Object Status -eq 'WouldChange')) { [void]$blocks.Add(@{ Heading = $r.Title; Lines = @(Get-TpmBaselinePlanLines -Plan $r.Plan) }) }
    $left = @($Batch.Results | Where-Object { $_.Status -in @('Refused', 'Unsupported', 'Unreadable') })
    if ($left.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Games left alone'; Lines = @($left | ForEach-Object { '{0}: {1}' -f $_.Title, $(if ($_.Reason) { $_.Reason } else { $_.Status }) }) }) }
    return $blocks.ToArray()
}

# The screen for "set up games with my layout": one game, all games with one approval, or game by game.
function Invoke-TpmBaselineScreen {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$GameProfilesDir, [Parameter(Mandatory)][string]$StateDir)
    Write-Host ''
    Write-TpmText -Text 'Set up games with my controller layout' -Color Cyan
    foreach ($line in (Get-TpmControllerPowerReminder)) { Write-TpmText -Text $line -Color DarkCyan }
    $baseline = Read-TpmBaseline -StateDir $StateDir
    if ($null -eq $baseline) {
        Write-TpmText -Text 'You have not chosen a controller layout yet.' -Color DarkCyan
        $baseline = Invoke-TpmBaselineChooseScreen -StateDir $StateDir
        if ($null -eq $baseline) { return }
    }
    $layout = @(Get-TpmBaselineLayout -Baseline $baseline)
    $presetTitle = (Get-TpmBaselinePresets)[$baseline.Preset].Title
    Write-Host ''
    Write-TpmText -Text ('Your layout: {0}. (Choose 3 in the Propagate Controls menu to change it.)' -f $presetTitle) -Color DarkCyan
    Write-TpmText -Text '1 = one game' -Indent 4
    Write-TpmText -Text '2 = all my games at once (you see a preview and approve once)' -Indent 4
    Write-TpmText -Text '3 = game by game (you confirm each one)' -Indent 4
    $mode = Read-TpmChoice -Prompt '  Choose 1, 2 or 3' -Choices @('1', '2', '3') -Default '1'
    $backupState = @{ Backup = $null }
    if ($mode -eq '1') {
        $typed = [string](Read-HostSafe '  Type part of the game name (or press Enter to go back)')
        if ([string]::IsNullOrWhiteSpace($typed)) { return }
        $found = @(Find-TpmBaselineProfiles -UserProfilesDir $UserProfilesDir -Text $typed)
        if ($found.Count -eq 0) { Write-TpmText -Text 'No game matched that. Try fewer letters.' -Color Yellow; return }
        $titles = @($found | ForEach-Object { try { Get-TpmProfileFriendlyTitle -Doc (Read-Xml $_.FullName) -BaseName $_.BaseName } catch { $_.BaseName } })
        $index = Read-TpmNumberedListChoice -Rows $titles -Prompt '  Which game? (number, or B to go back)' -Heading 'These games matched:'
        if ($index -lt 0) { return }
        $title = $titles[$index]
        # What TPM knows about this game's controls right now (read-only), in plain words.
        try {
            $coverage = Get-TpmControlCoverage -Code $found[$index].BaseName -UserProfilesDir $UserProfilesDir -GameProfilesDir $GameProfilesDir
            if ($null -ne $coverage) { Write-Host ''; foreach ($line in (Get-TpmControlCoverageLines -Inventory $coverage)) { Write-TpmText -Text $line -Color DarkCyan } }
        } catch { Write-Log ('Baseline: the controls of {0} could not be read -- {1}' -f $title, $_.Exception.Message) }
        Write-Host ''
        Write-TpmText -Text ('How will you play {0}?' -f $title) -Color Cyan
        Write-TpmText -Text 'A = arcade controls (nothing changes)' -Indent 4
        Write-TpmText -Text ('X = my layout, {0} (this game may stop using the arcade encoder)' -f $presetTitle) -Indent 4
        if ((Read-TpmChoice -Prompt '  Choose A or X' -Choices @('A', 'X') -Default 'A') -ne 'X') {
            Write-TpmText -Text 'Nothing changed. This game keeps its arcade controls.' -Color Green
            Write-Log ('Baseline: {0}: arcade chosen, no change.' -f $title)
            return
        }
        $batchArgs = @{ UserProfilesDir = $UserProfilesDir; ProfilePaths = @($found[$index].FullName); GameProfilesDir = $GameProfilesDir; Layout = $layout }
        $preview = Invoke-TpmBaselineBatch @batchArgs -DryRun $true
        $r = $preview.Results[0]
        Write-Log ('Baseline preview: {0}: status={1} add={2} keep={3} reason={4}' -f $title, $r.Status, $r.Added, $r.Kept, $r.ReasonCode)
        if ($r.Status -eq 'Unreadable' -or $r.Status -eq 'Unsupported' -or $r.Status -eq 'Refused') { Write-TpmText -Text ($r.Reason + ' Nothing was changed.') -Color Yellow; return }
        if ($r.Status -eq 'NoChange') { Write-TpmText -Text 'This game is already set up with your layout.' -Color Green; return }
        Write-TpmText -Text ('Ready to set up {0} buttons.' -f $r.Added) -Color DarkCyan
        foreach ($line in (Get-TpmBaselinePlanLines -Plan $r.Plan)) { Write-TpmText -Text $line -Indent 4 }
        Write-TpmText -Text 'A saved copy of your game settings is made first.' -Color DarkCyan
        if ((Read-TpmYesNo -Prompt '  Set this up now? (Y/N)' -Default 'N') -ne 'Y') { Write-TpmText -Text 'Skipped. Nothing changed.' -Color DarkGray; return }
        $done = Invoke-TpmBaselineBatch @batchArgs -DryRun $false -Signatures @{ $found[$index].FullName = $r.Signature } -BackupState $backupState
        $d = $done.Results[0]
        Write-Log ('Baseline: {0}: status={1} add={2} api={3} verified={4} backup={5}' -f $title, $d.Status, $d.Added, $d.ApiChanged, $d.Verified, [string]$done.Backup.Path)
        Write-Log ('Baseline: layout source: ' + (Get-TpmBaselineLayoutSource))
        if ($d.Status -ne 'Changed') { Write-TpmText -Text ('The change was not made, so your game settings were left as they were. ' + $d.Reason) -Color Yellow; return }
        Write-TpmText -Text ('Done. {0} is set up with your layout and was read back to check it. Next: make sure the controller is on, then start the game.' -f $title) -Color Green
        Invoke-TpmBaselineUndoPrompt -UserProfilesDir $UserProfilesDir -Backup $done.Backup
        return
    }

    $files = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'Controller layout game list' -EnumerationErrorAction SilentlyContinue | Sort-Object BaseName)
    if ($files.Count -eq 0) { Write-TpmText -Text 'No registered games were found.' -Color Yellow; return }
    $paths = @($files | ForEach-Object { $_.FullName })
    $batchArgs = @{ UserProfilesDir = $UserProfilesDir; ProfilePaths = $paths; GameProfilesDir = $GameProfilesDir; Layout = $layout }
    $preview = Invoke-TpmProgressGroup -Title 'Controller layout preview' -Action { Invoke-TpmBaselineBatch @batchArgs -DryRun $true }
    Write-Host ''
    Write-TpmText -Text 'Preview. Nothing has been changed yet.' -Color Cyan
    Write-TpmBaselineBatchPreview -Batch $preview
    if ($preview.Changed -eq 0) { Write-TpmText -Text 'No game needs your layout right now.' -Color Green; return }
    Write-TpmText -Text 'Games you play with an arcade encoder may stop using it. Choose game by game if you are not sure.' -Color Yellow
    $signatures = @{}
    foreach ($r in @($preview.Results | Where-Object Status -eq 'WouldChange')) { $signatures[$r.Path] = $r.Signature }
    $detailBlocks = @(Get-TpmBaselineBatchDetailBlocks -Batch $preview)
    if ($mode -eq '2') {
        Write-TpmText -Text 'A saved copy of your game settings is made first.' -Color DarkCyan
        $go = Read-TpmYesNo -Prompt ('  Set up {0} now? (Y/N, D = details)' -f (Format-TpmGameCount -Count $preview.Changed)) -Default 'N' -DetailsAction { Show-TpmDetailBlocks -Blocks $detailBlocks }
        if ($go -ne 'Y') { Write-TpmText -Text 'Skipped. Nothing changed.' -Color DarkGray; return }
        $done = Invoke-TpmProgressGroup -Title 'Controller layout' -Action { Invoke-TpmBaselineBatch @batchArgs -DryRun $false -Signatures $signatures -BackupState $backupState }
    } else {
        $approved = New-Object System.Collections.ArrayList
        foreach ($r in @($preview.Results | Where-Object Status -eq 'WouldChange')) {
            Write-Host ''
            Write-TpmText -Text $r.Title -Color Cyan
            foreach ($line in (Get-TpmBaselinePlanLines -Plan $r.Plan)) { Write-TpmText -Text $line -Indent 4 }
            $answer = Read-TpmChoice -Prompt '  Set this game up? Y = yes, N = skip, S = stop' -Choices @('Y', 'N', 'S') -Default 'N'
            if ($answer -eq 'S') { break }
            if ($answer -eq 'Y') { [void]$approved.Add($r.Path) }
        }
        if ($approved.Count -eq 0) { Write-TpmText -Text 'Nothing was approved. Nothing changed.' -Color DarkGray; return }
        $batchArgs['ProfilePaths'] = @($approved)
        $done = Invoke-TpmProgressGroup -Title 'Controller layout' -Action { Invoke-TpmBaselineBatch @batchArgs -DryRun $false -Signatures $signatures -BackupState $backupState }
    }
    Write-Host ''
    foreach ($line in (Get-TpmBaselineBatchLines -Batch $done -DryRun $false)) { Write-TpmText -Text $line -Color Green }
    foreach ($r in @($done.Results | Where-Object { $_.Status -in @('Failed', 'Refused') })) { Write-TpmText -Text ('{0}: left as it was. {1}' -f $r.Title, $r.Reason) -Color Yellow }
    foreach ($r in @($done.Results)) { Write-Log ('Baseline: {0}: status={1} add={2} api={3} verified={4}' -f $r.Code, $r.Status, $r.Added, $r.ApiChanged, $r.Verified) }
    Write-Log ('Baseline: backup={0}. Layout source: {1}' -f [string]$done.Backup.Path, (Get-TpmBaselineLayoutSource))
    if ($done.Changed -gt 0) {
        Write-TpmText -Text 'Each changed game was read back and checked. TPM has not tested any game with a real controller.' -Color DarkCyan
        Invoke-TpmBaselineUndoPrompt -UserProfilesDir $UserProfilesDir -Backup $done.Backup
    }
}
# ===== end TpmController =====

# Longest common prefix of a list of strings. Used to turn a device's bind
# names into a single device name. Returns "" for an empty list.
function Get-LongestCommonPrefix {
    param($strings)
    $arr = @($strings)
    if ($arr.Count -eq 0) { return "" }
    $prefix = [string]$arr[0]
    foreach ($s in $arr) {
        $max = [Math]::Min($prefix.Length, $s.Length)
        $i = 0
        while ($i -lt $max -and $prefix[$i] -eq $s[$i]) { $i++ }
        $prefix = $prefix.Substring(0, $i)
        if ($prefix.Length -eq 0) { break }
    }
    return $prefix
}

# Returns the distinct device names a profile is bound to. Buttons are grouped
# by their device path, and each device's name is the longest common prefix of
# its bind names (e.g. "Ultimarc I-PAC A" + "Ultimarc I-PAC F" -> "Ultimarc
# I-PAC"). This lets you confirm each game type uses the device you intend
# before copying its controls to other games.
function Get-ProfileDevices {
    param($doc)
    $byPath = @{}
    $tagOf  = @{}
    foreach ($btn in (Get-ButtonNodes $doc)) {
        foreach ($tag in @("RawInputButton","DirectInputButton","XInputButton")) {
            $bind = $btn.SelectSingleNode($tag)
            if ($null -ne $bind) {
                $dp      = $bind.SelectSingleNode("DevicePath")
                $pathKey = if ($dp) { $dp.InnerText } else { $tag }
                $bnNode  = $btn.SelectSingleNode("BindName")
                $bn      = if ($bnNode) { $bnNode.InnerText } else { "" }
                if (-not $byPath.ContainsKey($pathKey)) {
                    $byPath[$pathKey] = New-Object System.Collections.ArrayList
                    $tagOf[$pathKey]  = $tag
                }
                if ($bn -and $bn -ne 'None') { [void]$byPath[$pathKey].Add($bn) }
                break
            }
        }
    }
    $names = New-Object System.Collections.ArrayList
    foreach ($pathKey in $byPath.Keys) {
        # The API comes from the binding element type, not a guess -- a gamepad
        # read via RawInput is labeled RawInput, not XInput.
        switch ($tagOf[$pathKey]) {
            "XInputButton"      { $api = "XInput"      }
            "DirectInputButton" { $api = "DirectInput" }
            default             { $api = "RawInput"    }
        }
        $name = (Get-LongestCommonPrefix $byPath[$pathKey]).Trim()
        if ([string]::IsNullOrWhiteSpace($name)) {
            # No usable bind names: fall back to a friendly device path (e.g.
            # "Windows Mouse Cursor"), but not a raw HID path.
            if ($pathKey -and -not $pathKey.StartsWith('\\?\')) { $name = $pathKey }
            else { $name = "(unnamed device)" }
        }
        # Replace TeknoParrot's generic "Input Device N" label with the actual
        # API so the report is accurate and readable (e.g. "XInput Device 0").
        if     ($name -match '^Input Device (\d+)') { $name = "$api Device $($Matches[1])" }
        elseif ($name -match '^Input Device')       { $name = "$api Device" }
        if ($names -notcontains $name) { [void]$names.Add($name) }
    }
    return $names
}


# Config fields that describe INPUT behavior (aim mode, sensitivity, axis
# handling). These are safe to copy between same-type games so a propagated
# game reproduces the reference game's feel. A field is copied only when the target
# also defines it, so nothing is ever invented. Verified present in real
# lightgun profiles (e.g. "Use Relative Input", relative sensitivity, cursor).
# Copying is only as correct as the reference game's own values -- the
# pre-propagation summary (Section 10) prints these before the user confirms,
# so a wrong value on the reference (e.g. an axis mode left over from
# testing with a keyboard instead of a real wheel) is caught before it
# fans out to every other game of that type.
$InputConfigFields = @(
    "Use Relative Input",
    "Player 1 Relative Sensitivity",
    "Player 2 Relative Sensitivity",
    "HideCursor",
    "Reverse Y Axis",
    "Reverse Throttle Axis",
    "Use Keyboard/Button For Axis",
    "Keyboard/Button Axis X/Y Sensitivity",
    "Keyboard/Button Axis Throttle Sensitivity"
)

# Known carried-setting values that usually mean the reference game was bound
# with a substitute device (keyboard, mouse) instead of its real hardware --
# the same root cause as "Use Keyboard/Button For Axis" left True on a wheel
# game. Each entry: the family this applies to, the carried field name, the
# value that triggers the warning, and why it matters.
$ConfigCarryWarnings = @(
    @{ Family = "driving";  Field = "Use Keyboard/Button For Axis"; Value = "True"
       Message = "wheel/pedal axes will be read as digital keyboard/button input, not analog -- should be False if you bind with a real wheel." },
    @{ Family = "lightgun"; Field = "Use Relative Input"; Value = "True"
       Message = "gun aim will be read as relative mouse-style movement, not absolute screen position -- should usually be False for a real lightgun that reports absolute coordinates." }
)

# Returns warning strings for a family's carried config values: known
# device-mismatch combos (see $ConfigCarryWarnings) plus any "...Sensitivity"
# field carried as literal 0, which would silently disable aiming/axis
# response on every propagated game of that type.
function Get-ConfigCarryFlags {
    param([string]$family, $configCarry)
    $flags = New-Object System.Collections.ArrayList
    foreach ($rule in $ConfigCarryWarnings) {
        if ($rule.Family -eq $family -and $configCarry.ContainsKey($rule.Field) -and $configCarry[$rule.Field] -eq $rule.Value) {
            [void]$flags.Add("$($rule.Field)=$($rule.Value) -- $($rule.Message)")
        }
    }
    foreach ($key in $configCarry.Keys) {
        if ($key -match 'Sensitivity$' -and $configCarry[$key].Trim() -eq "0") {
            [void]$flags.Add("$key=0 -- this disables aiming/axis response entirely.")
        }
    }
    return $flags
}

# Returns a hashtable { FieldName = FieldValue } for those of $names that the
# profile's ConfigValues actually contains.
function Get-ConfigFieldMap {
    param($doc, $names)
    $out = @{}
    foreach ($fi in $doc.SelectNodes("/GameProfile/ConfigValues/FieldInformation")) {
        $fn = $fi.SelectSingleNode("FieldName")
        if ($null -eq $fn) { continue }
        $name = $fn.InnerText.Trim()
        if ($names -contains $name) {
            $fv = $fi.SelectSingleNode("FieldValue")
            if ($null -ne $fv) { $out[$name] = $fv.InnerText }
        }
    }
    return $out
}

# Sets a ConfigValues field's value if the field exists in the profile.
# Returns $true if it was set. (Field names are a fixed internal whitelist,
# so the XPath literal below is not built from external input.)
function Set-ConfigField {
    param($doc, [string]$name, [string]$value)
    $fi = $doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral $name)]")
    if ($null -eq $fi) { return $false }
    $fv = $fi.SelectSingleNode("FieldValue")
    if ($null -eq $fv) { return $false }
    $fv.InnerText = $value
    return $true
}

# Scans UserProfiles and returns the bound-game pool: every profile that the
# user has bound to a meaningful degree (>= $minBound bound buttons). Each
# entry carries its family (the user's familyOverride wins over auto-detection,
# the same as for the games being filled in), Input API, and a map of
# (key -> bound button node) used as the source of truth for copying. Includes
# previously-propagated profiles intentionally: on re-runs they act as
# archetypes for any newly registered games.
function Build-ArchetypePool {
    param([string]$userProfilesDir, [int]$minBound, $familyOverride = @{})
    $pool  = New-Object System.Collections.ArrayList
    $files = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $userProfilesDir -ProgressLabel 'Control propagation archetype discovery' -EnumerationErrorAction SilentlyContinue)
    $poolProgressStarted = Get-Date
    $poolProgressCurrent = 0
    $poolProgressCurrentDone = $false
    try {
        foreach ($f in $files) {
        $poolProgressCurrent++
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'Control propagation archetype scan' -Current $poolProgressCurrent -Total $files.Count -StartedAt $poolProgressStarted
        try { $doc = Read-Xml $f.FullName }
        catch { Write-Log "Pool scan: could not parse $($f.Name)"; continue }
        if ($null -eq $doc.GameProfile) { continue }
        $map = @{}; $boundCount = 0
        foreach ($btn in (Get-ButtonNodes $doc)) {
            if (Test-ButtonIsBound $btn) {
                $key = Get-ButtonKey $btn
                if ($key) { $map[$key] = $btn; $boundCount++ }
            }
        }
        if ($boundCount -ge $minBound) {
            [void]$pool.Add([pscustomobject]@{
                Code        = $f.BaseName
                Path        = $f.FullName
                Family      = $(if ($familyOverride.ContainsKey($f.BaseName)) { $familyOverride[$f.BaseName] } else { Get-ProfileFamily $doc })
                InputApi    = (Get-ProfileInputApi $doc)
                Devices     = (Get-ProfileDevices $doc)
                ConfigCarry = (Get-ConfigFieldMap $doc $InputConfigFields)
                Map         = $map
                BoundCount  = $boundCount
            })
        }
        }
        $poolProgressCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'Control propagation archetype scan' -Current $(if ($poolProgressCurrentDone) { $poolProgressCurrent } else { $poolProgressCurrent - 1 }) -Total $files.Count -StartedAt $poolProgressStarted -Complete -Outcome $(if ($poolProgressCurrentDone) { 'Final' } else { 'Error' })
    }
    return $pool
}

# For each UNbound (or barely-bound) profile, choose the best same-family
# reference game by key overlap, copy its bindings into matching unbound
# buttons, carry its Input API, and record what was bound vs left manual.
# Reference games are never modified. Returns a list of per-game report objects.
function Invoke-ControlPropagation {
    param([string]$userProfilesDir,$pool,[int]$minBound,$noPropagate=@(),$forceArchetype=@{},$familyOverride=@{},$canonicalArchetype=@{},[bool]$DryRun=$false)
    # Lazy safety backup state, filled by Invoke-ControlPropagationLegacy immediately before its first real save.
    # A plain hashtable, not a GetNewClosure() callback: a closure runs in a dynamic module that cannot see this
    # script's functions, so the backup command was "not recognized" and every real write was refused.
    $backupState=if($DryRun){$null}else{@{ Backup=$null }}
    $legacy=Invoke-ControlPropagationLegacy -userProfilesDir $userProfilesDir -pool $pool -minBound $minBound -noPropagate $noPropagate -forceArchetype $forceArchetype -familyOverride $familyOverride -canonicalArchetype $canonicalArchetype -DryRun $DryRun -BackupState $backupState
    $backup=if($null -ne $backupState){$backupState.Backup}else{$null}
    $legacyReports=@($legacy)
    $items=@($legacyReports | ForEach-Object Code)
    $changed=@($legacyReports | Where-Object { $_.Status -in @('bound','api-fixed','api-fixed-canonical') } | ForEach-Object Code)
    $written=@($legacyReports | Where-Object { $_.Status -in @('bound','api-fixed','api-fixed-canonical','settings-only') } | ForEach-Object Code)
    # An unreadable profile was neither changed nor checked: it is an unfinished item, not a quiet omission.
    $unreadable=@($legacyReports | Where-Object Status -eq 'unreadable' | ForEach-Object Code)
    $failed=@($legacyReports | Where-Object { $_.Status -in @('save-failed','unreadable') } | ForEach-Object Code)
    $skipped=@($legacyReports | Where-Object { $_.Status -like 'skipped-*' } | ForEach-Object Code)
    # No usable family reference is a design skip, not an unfinished or failed write.
    $retained=@($legacyReports | Where-Object { [string](Get-TpmTransactionField -Object $_ -Name 'KeptCopy' -Default '') } | ForEach-Object { [string]$_.KeptCopy })
    $outcome=if($DryRun){'NO_OP'}elseif($retained.Count -gt 0){'ACTION_REQUIRED'}elseif($written.Count -gt 0 -and $failed.Count -gt 0){'PARTIAL_APPLIED'}elseif($written.Count -gt 0){'SUCCEEDED'}elseif($failed.Count -gt 0){'FAILED_BEFORE_MUTATION'}else{'NO_OP'}
    $presentation = Get-TpmControlPropagationSummary -Reports $legacyReports -DryRun $DryRun -Outcome $outcome
    $resultSummary = ($presentation.Title + ' ' + $presentation.NotChanged).Trim()
    $tx=ConvertTo-TpmLegacyTransactionResult -Legacy ([pscustomobject]@{ Reports=$legacyReports; BoundCount=$changed.Count; FailedCount=$failed.Count; SkippedCount=$skipped.Count; RetainedCopies=$retained }) -WorkflowKey 'ControlPropagation' -OperationKey 'PropagateProfileSettings' -Items $items -ChangedItems $(if($DryRun){@()}else{$written}) -CompletedItems $written -FailedItems $failed -SkippedItems $skipped -Summary $resultSummary -ReasonCode $(if($backup -and -not $backup.Verified){'PROFILE_BACKUP_FAILED'}elseif($retained.Count -gt 0){'PROFILE_FILE_REMOVED'}elseif($failed.Count -gt $unreadable.Count){'PROFILE_SAVE_FAILED'}elseif($unreadable.Count -gt 0){'PROFILE_UNREADABLE'}elseif($outcome -eq 'NO_OP'){'NO_CHANGES_NEEDED'}elseif($backup -and $written.Count -eq 0){'PROFILE_BACKUP_COMPLETED_NO_WRITE'}else{'CONTROLS_PROCESSED'}) -Outcome $outcome -ProductState $(if($retained.Count -gt 0){'UNKNOWN'}elseif($outcome -eq 'SUCCEEDED'){'INTENDED'}elseif($outcome -eq 'PARTIAL_APPLIED'){'PARTIAL_KNOWN'}else{'UNCHANGED'}) -MutationStarted (-not $DryRun -and ($written.Count -gt 0 -or $retained.Count -gt 0)) -FinalPassed ($retained.Count -eq 0) -Backup $backup
    $tx | Add-Member -NotePropertyName Reports -NotePropertyValue $legacyReports -Force
    return $tx
}
function Invoke-ControlPropagationLegacy {
    param([string]$userProfilesDir, $pool, [int]$minBound, $noPropagate = @(), $forceArchetype = @{}, $familyOverride = @{}, $canonicalArchetype = @{}, [bool]$DryRun = $false, [hashtable]$BackupState = $null)
    # The safety backup is created lazily, immediately before the first real profile save, so a
    # call that changes nothing never creates (or reports) a backup. A failed backup is sticky:
    # every later save is refused too, so nothing is written without a verified backup.
    $writeGate = @{ Done = $false; Error = $null }
    $saveGuarded = {
        param($doc, $path)
        if (-not $DryRun) {
            if ($null -eq $BackupState) { throw 'A verified profile backup is required before saving control changes, but no backup state was provided.' }
            if ($null -ne $writeGate.Error) { throw $writeGate.Error }
            if (-not $writeGate.Done) {
                try {
                    $BackupState.Backup = New-TpmVerifiedUserProfilesBackup -UserProfilesDir $userProfilesDir -Label 'PropagateControls'
                    if (-not $BackupState.Backup.Verified) { throw 'The safety backup could not be verified.' }
                } catch { $writeGate.Error = $_.Exception; throw }
                $writeGate.Done = $true
            }
        }
        Save-XmlMaybe $doc $path $DryRun
    }
    $reports     = New-Object System.Collections.ArrayList
    $files = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $userProfilesDir -ProgressLabel 'Control propagation profile discovery' -EnumerationErrorAction SilentlyContinue)
    $sourcePaths = @{}
    foreach ($s in $pool) { $sourcePaths[$s.Path] = $true }

    $propagationProgressStarted = Get-Date
    $propagationProgressCurrent = 0
    $propagationProgressCurrentDone = $false
    try {
    foreach ($f in $files) {
        $propagationProgressCurrent++
        Write-TpmCompactExtractionProgress -Phase Repairing -Label 'Control propagation profile scan' -Current $propagationProgressCurrent -Total $files.Count -StartedAt $propagationProgressStarted
        # An archetype's BINDINGS are never modified, full stop. Its own
        # Input API may only be corrected against a family's user-
        # designated canonical archetype (canonicalArchetype in
        # overrides.json) -- never a heuristic guess. v0.99.12 tried
        # guessing via best non-self button overlap, reasoning that an
        # archetype can itself be sitting on a stale API, and actively
        # broke a real tester's library: almost every well-bound
        # button-family profile is simultaneously a pool member (the same
        # $minBound threshold drives both), so the "best overlap" heuristic
        # -- which is fine for deciding what bindings to COPY -- ended up
        # cross-correcting unrelated, independently-correct archetypes
        # against each other with no actual signal for which one is right.
        # Confirmed in a real run: StreetFighterIII3rdStrike, the tester's
        # own deliberately-configured MergedInput reference, got silently
        # flipped to DirectInput because a different archetype (BBCF) won
        # the overlap comparison. Reverted in v0.99.14. canonicalArchetype
        # (v0.99.17) sidesteps that exact problem: correction only ever
        # runs when the user has explicitly named the one correct archetype
        # for that family, and only ever pulls from that one designated
        # source -- never a guess. See issue #1.
        if ($sourcePaths.ContainsKey($f.FullName)) {
            $selfEntry = $null
            foreach ($s in $pool) { if ($s.Path -eq $f.FullName) { $selfEntry = $s; break } }
            # An excluded profile is never mutated, not even by canonical Input API correction (issue #333).
            if ($selfEntry -and $noPropagate -notcontains $f.BaseName -and $canonicalArchetype.ContainsKey($selfEntry.Family)) {
                $canonCode = [string]$canonicalArchetype[$selfEntry.Family]
                if ($selfEntry.Code -ne $canonCode) {
                    $canon = $null
                    foreach ($s in $pool) { if ($s.Code -eq $canonCode) { $canon = $s; break } }
                    if ($canon -and $canon.InputApi -and $canon.InputApi -ne $selfEntry.InputApi) {
                        try { $canonDoc = Read-Xml $f.FullName }
                        catch { Write-Log "Propagation: could not parse $($f.Name) for canonical Input API check"; [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "unreadable"; Archetype = $canon.Code }); continue }
                        if ($null -ne $canonDoc.GameProfile -and (Set-ProfileInputApi $canonDoc $canon.InputApi)) {
                            try {
                                & $saveGuarded $canonDoc $f.FullName
                                # Update the in-memory pool entry too, not just the file on disk --
                                # $selfEntry is the same object instance referenced by $pool, so this
                                # is visible to every later iteration of this same loop. Without this,
                                # a non-archetype profile that propagates from $selfEntry later in this
                                # very run (e.g. a target alphabetically after this archetype) would
                                # still copy the now-stale pre-correction InputApi, since $best.InputApi
                                # below is read from this same pool snapshot. Confirmed on a real
                                # tester's log: BBCF's correction and ChronoRegalia/dbzenkai/
                                # PokkenTournament/PPQ propagating FROM BBCF with the old DirectInput
                                # value happened in the same second of the same run. See issue #1.
                                $selfEntry.InputApi = $canon.InputApi
                                [void]$reports.Add([pscustomobject]@{
                                    Code = $f.BaseName; Status = "api-fixed-canonical"
                                    Archetype = $canon.Code; ArchetypeApi = $canon.InputApi
                                })
                                Write-Log "Propagation: $($f.BaseName) (archetype) Input API corrected to $($canon.InputApi) to match user-designated canonical archetype $($canon.Code) for family $($selfEntry.Family)"
                            } catch {
                                Write-Log "Propagation: FAILED to save canonical Input API fix for $($f.Name) -- $_"
                                [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "save-failed"; Archetype = $canon.Code; KeptCopy = (Get-TpmKeptSaveCopyPath -Text $_.Exception.Message) })
                            }
                        }
                    }
                }
            }
            continue
        }
        if ($noPropagate -contains $f.BaseName) {
            [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "skipped-override" })
            continue
        }

        try { $doc = Read-Xml $f.FullName }
        catch { Write-Log "Propagation: could not parse $($f.Name)"; [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "unreadable" }); continue }
        if ($null -eq $doc.GameProfile) { continue }

        $btns = Get-ButtonNodes $doc
        if ($null -eq $btns -or $btns.Count -eq 0) { continue }

        $alreadyBound = 0
        foreach ($b in $btns) { if (Test-ButtonIsBound $b) { $alreadyBound++ } }
        $buttonsAlreadyBound = ($alreadyBound -ge $minBound)

        $targetFamily = if ($familyOverride.ContainsKey($f.BaseName)) {
            $familyOverride[$f.BaseName]
        } else {
            Get-ProfileFamily $doc
        }

        # If this game is pinned to a specific archetype via overrides, use it
        # (this is an explicit user choice, so family is not enforced here).
        $best = $null; $bestOverlap = 0; $forced = $false
        if ($forceArchetype.ContainsKey($f.BaseName)) {
            $wantCode = [string]$forceArchetype[$f.BaseName]
            foreach ($s in $pool) { if ($s.Code -eq $wantCode) { $best = $s; $forced = $true; break } }
            if ($null -eq $best) {
                Write-Log "Propagation: pinned archetype '$wantCode' for $($f.BaseName) not found; using best match."
            }
        }

        # Otherwise pick the best same-family archetype by how many of this
        # game's keys it can supply. Ties go to the more completely-bound one.
        # Computed even when this profile's buttons are already bound (below)
        # -- needed there too, to check whether the archetype's Input API can
        # be retroactively applied without touching any button binding.
        if ($null -eq $best) {
            foreach ($s in $pool) {
                if ($s.Family -ne $targetFamily) { continue }
                $ov = 0
                foreach ($b in $btns) { $k = Get-ButtonKey $b; if ($k -and $s.Map.ContainsKey($k)) { $ov++ } }
                if ($ov -gt $bestOverlap -or ($ov -eq $bestOverlap -and $null -ne $best -and $s.BoundCount -gt $best.BoundCount)) {
                    $best = $s; $bestOverlap = $ov
                }
            }
            if ($null -eq $best -or $bestOverlap -eq 0) {
                if ($buttonsAlreadyBound) {
                    [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "skipped-bound" })
                } else {
                    [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = 'skipped-no-reference'; ReasonCode = 'NO_USABLE_FAMILY_REFERENCE'; Family = $targetFamily })
                }
                continue
            }
        }

        # A profile whose buttons are already configured is never re-bound
        # (this loop never touches a working binding), but the Input API
        # fix from issue #1 only runs from inside this same per-profile pass
        # -- without this branch it could never reach an already-bound
        # profile on any later run, even after the fix shipped, since this
        # function would always continue past it above. Checking and
        # correcting just the Input API field here, independent of button
        # binding, lets that fix apply retroactively. See issue #1.
        if ($buttonsAlreadyBound) {
            $currentApi = Get-ProfileInputApi $doc
            $apiSet = $false
            if ($best.InputApi -and $best.InputApi -ne $currentApi) {
                $apiSet = Set-ProfileInputApi $doc $best.InputApi
            }

            # Report-only: scan bound slots for directional/action classification
            # mismatch vs the archetype. Never rewrites -- only flags for ACTION
            # REQUIRED output so the user knows which slots need a manual rebind
            # in TeknoParrot's own UI. Same Test-ButtonNameDirectional logic the
            # non-bound copy path uses to PREVENT these mismatches going forward.
            # See issue #17.
            $mismatchSlots = New-Object System.Collections.ArrayList
            foreach ($b in $btns) {
                if (-not (Test-ButtonIsBound $b)) { continue }
                $k = Get-ButtonKey $b
                if (-not $k -or -not $best.Map.ContainsKey($k)) { continue }
                $srcNameNode = $best.Map[$k].SelectSingleNode("ButtonName")
                $srcName = if ($srcNameNode) { $srcNameNode.InnerText } else { "" }
                $nameNode = $b.SelectSingleNode("ButtonName")
                $btnName = if ($nameNode) { $nameNode.InnerText } else { "" }
                if ((Test-ButtonNameDirectional $srcName) -ne (Test-ButtonNameDirectional $btnName)) {
                    [void]$mismatchSlots.Add($btnName)
                }
            }
            $mismatchStr = if ($mismatchSlots.Count -gt 0) { $mismatchSlots -join ', ' } else { $null }

            if ($apiSet) {
                try {
                    & $saveGuarded $doc $f.FullName
                    [void]$reports.Add([pscustomobject]@{
                        Code = $f.BaseName; Status = "api-fixed"
                        Archetype = $best.Code; ArchetypeApi = $best.InputApi
                        MismatchSlots = $mismatchStr
                    })
                    Write-Log "Propagation: $($f.BaseName) already bound -- updated Input API to $($best.InputApi) to match archetype $($best.Code)"
                } catch {
                    Write-Log "Propagation: FAILED to save Input API fix for $($f.Name) -- $_"
                    [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "save-failed"; Archetype = $best.Code; KeptCopy = (Get-TpmKeptSaveCopyPath -Text $_.Exception.Message) })
                }
            } else {
                [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "skipped-bound"; MismatchSlots = $mismatchStr })
            }
            if ($mismatchStr) {
                Write-Log "Propagation: $($f.BaseName) already bound -- $($mismatchSlots.Count) slot(s) have directional/action mismatch vs archetype $($best.Code): $mismatchStr -- rebind in TeknoParrot UI"
            }
            continue
        }

        $boundNow = 0
        $manual   = New-Object System.Collections.ArrayList
        $usedKeys = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
        foreach ($b in @($btns)) {                     # @() snapshots before tree edits
            if (Test-ButtonIsBound $b) { continue }
            $k        = Get-ButtonKey $b
            $nameNode = $b.SelectSingleNode("ButtonName")
            $btnName  = if ($nameNode) { $nameNode.InnerText } else { "" }
            if ($k -and $best.Map.ContainsKey($k)) {
                if ($usedKeys.Contains($k)) {
                    if ($btnName) { [void]$manual.Add($btnName) }
                    continue
                }

                # Guard: skip the copy if source and target disagree on whether
                # this slot is a joystick direction vs an action button. Some
                # game profiles reuse the same InputMapping enum value (e.g.
                # P1ButtonUp, P1Button1) for completely different physical
                # controls across titles. Example: P1ButtonUp is the Up
                # direction in SF3 but "Left Punch" in Tekken 6; P1Button1 is
                # LP in SF3 but the UP direction in Rampage. Copying across
                # that semantic boundary bakes in wrong, non-fixable bindings
                # (the profile then counts as REFERENCE and is never revisited).
                # Test-ButtonNameDirectional classifies a slot as directional
                # only when its label, after stripping the player-number prefix,
                # consists exclusively of direction words. A mismatch (one side
                # directional, other side not) is treated as manual. See #17.
                $srcNameNode = $best.Map[$k].SelectSingleNode("ButtonName")
                $srcName = if ($srcNameNode) { $srcNameNode.InnerText } else { "" }
                if ((Test-ButtonNameDirectional $srcName) -ne (Test-ButtonNameDirectional $btnName)) {
                    if ($btnName) { [void]$manual.Add($btnName) }
                    continue
                }
                # Clone the archetype's whole bound node (preserving the exact
                # element order TeknoParrot writes), then restore THIS game's
                # own display name. The clone carries the real device + key.
                $imported = $doc.ImportNode($best.Map[$k], $true)
                $impName  = $imported.SelectSingleNode("ButtonName")
                if ($impName -and $nameNode) { $impName.InnerText = $btnName }
                [void]$b.ParentNode.ReplaceChild($imported, $b)
                [void]$usedKeys.Add($k)
                $boundNow++
            } elseif ($btnName) {
                [void]$manual.Add($btnName)
            }
        }

        # Setters report supported fields, not whether their values changed.
        $settingsBefore = if ($boundNow -eq 0) { $doc.OuterXml } else { $null }
        $apiSet = $false
        if ($best.InputApi) { $apiSet = Set-ProfileInputApi $doc $best.InputApi }

        # Carry input-behavior config (aim mode, sensitivity, axis handling)
        # from the archetype, but only fields this target also defines.
        $cfgCarried = New-Object System.Collections.ArrayList
        foreach ($cf in $best.ConfigCarry.Keys) {
            if (Set-ConfigField $doc $cf $best.ConfigCarry[$cf]) { [void]$cfgCarried.Add($cf) }
        }
        if ($boundNow -eq 0 -and [string]::Equals($doc.OuterXml, $settingsBefore, [System.StringComparison]::Ordinal)) {
            [void]$reports.Add([pscustomobject]@{
                Code = $f.BaseName; Status = "skipped-unchanged"; Family = $targetFamily
                Archetype = $best.Code; Manual = $manual
            })
            Write-Log "Propagation: $($f.BaseName) -- no binding or settings changes; profile not saved."
            continue
        }

        try {
            & $saveGuarded $doc $f.FullName
            $reportStatus = if ($boundNow -gt 0) { "bound" } else { "settings-only" }
            [void]$reports.Add([pscustomobject]@{
                Code = $f.BaseName; Status = $reportStatus; Family = $targetFamily
                Archetype = $best.Code; ArchetypeApi = $best.InputApi; ApiSet = $apiSet
                Bound = $boundNow; Manual = $manual; ConfigCarried = $cfgCarried; Forced = $forced
            })
            Write-Log "Propagated $($f.BaseName): family=$targetFamily src=$($best.Code) bound=$boundNow api=$($best.InputApi)/set=$apiSet config=$($cfgCarried -join ';')"
        } catch {
            Write-Log "Propagation: FAILED to save $($f.Name) -- $_"
            [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "save-failed"; Archetype = $best.Code; KeptCopy = (Get-TpmKeptSaveCopyPath -Text $_.Exception.Message) })
        }
    }
    $propagationProgressCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Repairing -Label 'Control propagation profile scan' -Current $(if ($propagationProgressCurrentDone) { $propagationProgressCurrent } else { $propagationProgressCurrent - 1 }) -Total $files.Count -StartedAt $propagationProgressStarted -Complete -Outcome $(if ($propagationProgressCurrentDone -and @($reports | Where-Object { $_.Status -eq 'save-failed' }).Count -eq 0) { 'Final' } else { 'Error' })
    }
    return $reports
}


# =============================================================================
# PROPAGATE CONTROLS SCREENS (FIX81)
# =============================================================================
# Used by both entry points (the Propagate Controls menu and the AutoSync/Register-only flow), so they never drift apart.
# Default view: how many games have their controls set up, one question, one short result. The technical rows (Input API,
# devices, copied settings, per-game results, counts, the hardware advice) are behind the Details key and in the log.

# Details of the example games, and the advice that applies to every game the settings are copied to.
function Get-TpmControlSourceBlocks {
    param([object[]]$Pool = @(), [string]$BackupNote = '')
    $about = @(
        'Your example games are the source. Their controls are copied to your other games of the same control type.',
        'Buttons that are already set up are kept.',
        'TeknoParrot Manager may correct an Input API setting without setting buttons again.',
        'Controls that an example game does not have stay for you to set up and test in TeknoParrotUI.',
        'The settings listed below are copied to EVERY other game of that type. Check them against your real hardware first.',
        'For example, "Use Keyboard/Button For Axis" should be False if you set up a real wheel.',
        '"Use Relative Input" should match how your lightgun reports position.',
        'If anything looks wrong, answer N, fix that game in TeknoParrotUI, then run this again.'
    )
    if (-not [string]::IsNullOrWhiteSpace($BackupNote)) { $about += $BackupNote }
    $blocks = New-Object System.Collections.Generic.List[object]
    [void]$blocks.Add(@{ Heading = 'What this does'; Lines = $about })
    foreach ($source in @($Pool)) {
        $api = if ($source.InputApi) { [string]$source.InputApi } else { 'not set' }
        $devices = if (@($source.Devices).Count -gt 0) { (@($source.Devices) -join ', ') } else { 'not known' }
        $lines = New-Object System.Collections.Generic.List[string]
        [void]$lines.Add('Control type: ' + $source.Family)
        [void]$lines.Add('Buttons set up: ' + $source.BoundCount)
        [void]$lines.Add('Input API: ' + $api)
        [void]$lines.Add('Devices: ' + $devices)
        $flags = @()
        if ($source.ConfigCarry -and $source.ConfigCarry.Count -gt 0) {
            [void]$lines.Add('Settings copied: ' + ((@($source.ConfigCarry.GetEnumerator() | ForEach-Object { '{0}={1}' -f $_.Key, $_.Value })) -join ', '))
            $flags = @(Get-ConfigCarryFlags $source.Family $source.ConfigCarry)
            foreach ($flag in $flags) { [void]$lines.Add('Warning: ' + $flag) }
        }
        $block = @{ Heading = [string]$source.Code; Lines = $lines.ToArray() }
        if ($flags.Count -gt 0) { $block.Color = 'Yellow' }
        [void]$blocks.Add($block)
    }
    return $blocks.ToArray()
}

# The default view of the example games: one line, and a warning line only when a copied setting looks wrong.
function Write-TpmControlSourceSummary {
    param([object[]]$Pool = @())
    $poolList = @($Pool)
    $text = if ($poolList.Count -eq 1) { 'You have {0} with its controls set up.' } else { 'You have {0} with their controls set up.' }
    Write-TpmText -Text ($text -f (Format-TpmGameCount -Count $poolList.Count)) -Color Green
    $flagged = @($poolList | Where-Object { $_.ConfigCarry -and $_.ConfigCarry.Count -gt 0 -and @(Get-ConfigCarryFlags $_.Family $_.ConfigCarry).Count -gt 0 })
    if ($flagged.Count -gt 0) {
        Write-TpmText -Text ('Check first: {0} may have settings that do not match your real controller. Press D to see them.' -f (Format-TpmGameCount -Count $flagged.Count)) -Color Yellow -BlankBefore
    }
}

# The question before anything is copied. D shows the details and asks again; Y and N work as they always did.
function Read-TpmControlCopyApproval {
    param([Parameter(Mandatory)][object[]]$Pool, [string]$BackupNote = '')
    $blocks = @(Get-TpmControlSourceBlocks -Pool $Pool -BackupNote $BackupNote)
    $prompt = '  Copy controls from {0} to your other games of the same type? (Y/N, D = details)' -f (Format-TpmGameCount -Count @($Pool).Count)
    return (Read-TpmYesNo -Prompt $prompt -DetailsAction { Show-TpmDetailBlocks -Blocks $blocks })
}

# One plain sentence about what happened to one game (the Details view uses it).
function Get-TpmControlPropagationReportLine {
    param($Report, [bool]$DryRun = $false)
    $status = [string](Get-TpmTransactionField -Object $Report -Name 'Status' -Default '')
    $archetype = [string](Get-TpmTransactionField -Object $Report -Name 'Archetype' -Default '')
    $family = [string](Get-TpmTransactionField -Object $Report -Name 'Family' -Default '')
    $api = [string](Get-TpmTransactionField -Object $Report -Name 'ArchetypeApi' -Default '')
    $count = Format-TpmCountNoun -Count ([int](Get-TpmTransactionField -Object $Report -Name 'Bound' -Default 0)) -Singular 'control'
    switch ($status) {
        'bound' {
            if ($DryRun) { return ('Would copy the controls of {0} ({1}). {2} would be set.' -f $archetype, $family, $count) }
            return ('Copied the controls of {0} ({1}). {2} set.' -f $archetype, $family, $count)
        }
        'settings-only' {
            if ($DryRun) { return 'Only the settings would be copied. The controls would still need to be set up by hand.' }
            return 'Only the settings were copied. The controls still need to be set up by hand.'
        }
        'skipped-no-reference' { return ("Skipped by design: no usable reference game for the '{0}' family. Add one game of this family with your own controls, then run this again." -f $family) }
        'api-fixed' {
            if ($DryRun) { return ("Already had controls. The Input API would be corrected to '{0}' (matched from {1})." -f $api, $archetype) }
            return ("Already had controls. The Input API was corrected to '{0}' (matched from {1})." -f $api, $archetype)
        }
        'api-fixed-canonical' {
            if ($DryRun) { return ("This is an example game. Its Input API would be corrected to '{0}' (matched from the main example {1})." -f $api, $archetype) }
            return ("This is an example game. Its Input API was corrected to '{0}' (matched from the main example {1})." -f $api, $archetype)
        }
        'skipped-bound' { return 'Already had controls. Left as it is.' }
        'skipped-override' { return 'Skipped because of one of your own rules.' }
        'skipped-unchanged' { return 'Nothing needed to change. Left as it is.' }
        'save-failed' {
            if ([string](Get-TpmTransactionField -Object $Report -Name 'KeptCopy' -Default '')) { return 'The old profile was removed while saving and could not be put back. A copy of the new settings was kept.' }
            return 'Could not be saved. See TeknoParrot-Manager.log.'
        }
        'unreadable' { return 'Could not be read, so it was left as it is. See TeknoParrot-Manager.log.' }
    }
    return ''
}

# Turns the reports of Invoke-ControlPropagation into the result screen (title, short lines, details) and the counts.
# Decides only; prints nothing.
function Get-TpmControlPropagationSummary {
    param($Reports, [bool]$DryRun = $false, [string]$Outcome = '', [string]$BackupPath = '')
    $rowList = New-Object System.Collections.Generic.List[object]
    foreach ($report in @($Reports)) {
        [void]$rowList.Add([pscustomobject]@{
            Report = $report
            Code = [string](Get-TpmTransactionField -Object $report -Name 'Code' -Default '')
            Status = [string](Get-TpmTransactionField -Object $report -Name 'Status' -Default '')
            Family = [string](Get-TpmTransactionField -Object $report -Name 'Family' -Default '')
            Manual = @(Get-TpmTransactionField -Object $report -Name 'Manual' -Default @())
            Carried = @(Get-TpmTransactionField -Object $report -Name 'ConfigCarried' -Default @())
            Forced = [bool](Get-TpmTransactionField -Object $report -Name 'Forced' -Default $false)
            Mismatch = [string](Get-TpmTransactionField -Object $report -Name 'MismatchSlots' -Default '')
        })
    }
    $rows = $rowList.ToArray()
    $copied = @($rows | Where-Object { $_.Status -eq 'bound' })
    $settingsOnly = @($rows | Where-Object { $_.Status -eq 'settings-only' })
    $apiFixed = @($rows | Where-Object { $_.Status -in @('api-fixed', 'api-fixed-canonical') })
    $skipped = @($rows | Where-Object { $_.Status -like 'skipped-*' })
    $failed = @($rows | Where-Object { $_.Status -eq 'save-failed' })
    $unreadable = @($rows | Where-Object { $_.Status -eq 'unreadable' })
    $designSkipped = @($rows | Where-Object { $_.Status -eq 'skipped-no-reference' })
    $needManual = @($rows | Where-Object { $_.Status -eq 'settings-only' -or ($_.Status -in @('bound', 'skipped-unchanged') -and $_.Manual.Count -gt 0) })
    $mismatched = @($rows | Where-Object { $_.Mismatch })
    $updated = $copied.Count + $apiFixed.Count + $settingsOnly.Count

    $done = New-Object System.Collections.Generic.List[string]
    if ($copied.Count -gt 0) { [void]$done.Add(($(if ($DryRun) { 'Would copy controls to {0}.' } else { 'Controls copied to {0}.' }) -f (Format-TpmGameCount -Count $copied.Count))) }
    if ($apiFixed.Count -gt 0) { [void]$done.Add(($(if ($DryRun) { 'Would correct the Input API of {0}.' } else { 'Input API corrected for {0}.' }) -f (Format-TpmGameCount -Count $apiFixed.Count))) }
    $ordinarySkipped = $skipped.Count - $designSkipped.Count
    $notChangedParts = New-Object System.Collections.Generic.List[string]
    $alreadySet = @($rows | Where-Object { $_.Status -in @('skipped-bound', 'skipped-unchanged') })
    $byRules = @($rows | Where-Object { $_.Status -eq 'skipped-override' })
    $otherLeft = $ordinarySkipped - $alreadySet.Count - $byRules.Count
    if ($alreadySet.Count -gt 0) { [void]$notChangedParts.Add(('{0} already set up.' -f (Format-TpmGameCount -Count $alreadySet.Count))) }
    if ($byRules.Count -gt 0) { [void]$notChangedParts.Add(('{0} skipped by your own rules.' -f (Format-TpmGameCount -Count $byRules.Count))) }
    if ($otherLeft -gt 0) { [void]$notChangedParts.Add(('{0} left as they were.' -f (Format-TpmGameCount -Count $otherLeft))) }
    if ($designSkipped.Count -gt 0) {
        $noRefFamilies = @($designSkipped | ForEach-Object { $_.Family } | Where-Object { $_ } | Sort-Object -Unique)
        $familyText = if ($noRefFamilies.Count -gt 0) { ' ({0}).' -f ($noRefFamilies -join ', ') } else { '' }
        [void]$notChangedParts.Add(('{0} skipped: no game of their family has your controls yet{1}' -f (Format-TpmGameCount -Count $designSkipped.Count), $familyText))
    }
    $notChanged = $notChangedParts -join ' '

    $needs = New-Object System.Collections.Generic.List[string]
    if ($needManual.Count -gt 0) { [void]$needs.Add(('{0}: set up the controls yourself in TeknoParrotUI.' -f (Format-TpmNameList -Limit 8 -Names @($needManual | ForEach-Object { $_.Code })))) }
    if ($mismatched.Count -gt 0) { [void]$needs.Add(('{0}: some buttons do the wrong thing. Set them again in TeknoParrotUI.' -f (Format-TpmNameList -Limit 3 -Names @($mismatched | ForEach-Object { $_.Code })))) }
    if ($failed.Count -gt 0) { [void]$needs.Add(('{0}: could not be saved. See the log.' -f (Format-TpmNameList -Limit 3 -Names @($failed | ForEach-Object { $_.Code })))) }
    if ($unreadable.Count -gt 0) { [void]$needs.Add(('{0}: could not be read, so it was left as it is. See the log.' -f (Format-TpmNameList -Limit 3 -Names @($unreadable | ForEach-Object { $_.Code })))) }
    if ($Outcome -and $Outcome -notin @('SUCCEEDED', 'NO_OP', 'PARTIAL_APPLIED', 'ACTION_REQUIRED', 'FAILED_BEFORE_MUTATION')) { [void]$needs.Add('The result could not be fully checked. See the log.') }

    if ($DryRun) { $title = 'Preview only. Nothing was saved.'; $status = 'Ok' }
    elseif ($failed.Count -gt 0 -and $updated -eq 0) { $title = '{0} could not be saved.' -f (Format-TpmGameCount -Count $failed.Count); $status = 'Problem' }
    elseif ($failed.Count -gt 0) { $title = '{0} updated. {1} could not be saved.' -f (Format-TpmGameCount -Count $updated), (Format-TpmGameCount -Count $failed.Count); $status = 'Attention' }
    elseif ($updated -gt 0) { $title = '{0} updated.' -f (Format-TpmGameCount -Count $updated); $status = if ($needs.Count -gt 0) { 'Attention' } else { 'Ok' } }
    elseif ($needs.Count -gt 0) { $title = 'No game was changed.'; $status = 'Attention' }
    elseif ($designSkipped.Count -gt 0) { $title = 'No game was changed.'; $status = 'Ok' }
    else { $title = 'No game needed a change.'; $status = 'Ok' }
    $next = ''
    if (-not $DryRun -and $updated -gt 0) { $next = 'Start one updated game in TeknoParrotUI and test its controls. If something is wrong, use Restore backup.' }
    elseif (-not $DryRun -and $unreadable.Count -gt 0 -and $needManual.Count -eq 0 -and $mismatched.Count -eq 0 -and $failed.Count -eq 0) { $next = 'Check the game that could not be read in TeknoParrotUI, or use Restore backup, then run this again.' }
    elseif (-not $DryRun -and $needs.Count -gt 0) { $next = 'Set up the controls above in TeknoParrotUI, then run this again.' }
    $suggest = @()
    if (-not $DryRun -and $designSkipped.Count -gt 0) {
        # Name one real game per family to set up, so the user is not left guessing which game to open in TeknoParrotUI.
        $suggest = @($designSkipped | Where-Object { $_.Family -and $_.Code } | Sort-Object Family, Code | Group-Object Family | ForEach-Object { '{0}: {1}' -f $_.Name, $_.Group[0].Code })
        if (-not $next) { $next = 'In TeknoParrotUI, set up the controls of one game of each type listed above{0}. Then run Propagate Controls (menu 3) again.' -f $(if ($suggest.Count -gt 0) { ' (for example ' + ($suggest -join '; ') + ')' } else { '' }) }
    }

    $blocks = New-Object System.Collections.Generic.List[object]
    $leftAlone = New-Object System.Collections.Generic.List[string]
    foreach ($row in $rows) {
        $sentence = Get-TpmControlPropagationReportLine -Report $row.Report -DryRun $DryRun
        if ($row.Status -like 'skipped-*' -and $row.Status -ne 'skipped-no-reference' -and $row.Manual.Count -eq 0 -and -not $row.Mismatch) { [void]$leftAlone.Add(($row.Code + ': ' + $sentence)); continue }
        $lines = New-Object System.Collections.Generic.List[string]
        [void]$lines.Add('What happened: ' + $sentence)
        if ($row.Status -eq 'skipped-no-reference') { [void]$lines.Add('Reason: ' + [string](Get-TpmTransactionField -Object $row.Report -Name 'ReasonCode' -Default 'NO_USABLE_FAMILY_REFERENCE')) }
        if ($row.Forced) { [void]$lines.Add('Pinned: you chose its example game') }
        $keptCopyForRow = [string](Get-TpmTransactionField -Object $row.Report -Name 'KeptCopy' -Default '')
        if ($keptCopyForRow) { [void]$lines.Add('Kept copy of the new settings: ' + $keptCopyForRow); [void]$lines.Add('What to do: restore the saved copy of your game settings, or rename that file back to the profile name.') }
        if ($row.Carried.Count -gt 0) { [void]$lines.Add($(if ($DryRun) { 'Settings that would be copied: ' } else { 'Settings copied: ' }) + ($row.Carried -join ', ')) }
        if ($row.Manual.Count -gt 0) { [void]$lines.Add('Still manual: ' + ($row.Manual -join ', ')) }
        if ($row.Mismatch) {
            [void]$lines.Add('Needs attention: directional/action mismatch in ' + $row.Mismatch)
            [void]$lines.Add('What to do: set these slots again by hand in TeknoParrot''s own UI.')
        }
        [void]$blocks.Add(@{ Heading = $row.Code; Lines = $lines.ToArray() })
    }
    if ($leftAlone.Count -gt 0) { [void]$blocks.Add(@{ Heading = ('Left as they are ({0})' -f $leftAlone.Count); Lines = $leftAlone.ToArray() }) }
    if ($suggest.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Games to set up first'; Lines = @(@($suggest | ForEach-Object { 'Set up one game in TeknoParrotUI: ' + $_ }) + @('Then run Propagate Controls (menu 3). The other games of that type get its controls.', 'Choosing a device in the binding plan does not set up a game.')) }) }
    [void]$blocks.Add(@{ Heading = 'Counts'; Lines = @(
        ('{0}: {1}' -f $(if ($DryRun) { 'Games with proposed control copies' } else { 'Games with controls copied' }), $copied.Count),
        ('{0}: {1}' -f $(if ($DryRun) { 'Proposed settings-only changes' } else { 'Settings carried only' }), $settingsOnly.Count),
        ('Games still needing manual setup: {0}' -f $needManual.Count),
        ('Games skipped: {0}' -f $skipped.Count),
        ('Games failed: {0}' -f $failed.Count),
        ('{0}: {1}' -f $(if ($DryRun) { 'Settings/API fixes proposed' } else { 'Settings/API corrected only' }), $apiFixed.Count),
        'Verified physical bindings: 0 (TeknoParrot Manager does not launch games or test device input).'
    ) })
    if ($BackupPath) { [void]$blocks.Add(@{ Heading = 'Saved copy of your game settings'; Lines = @(('Folder: ' + $BackupPath), 'To go back: use Restore backup in the main menu.') }) }
    $note = if ($DryRun) { 'These counts describe proposed settings. No game was saved. Physical device bindings are not verified. Test each game in TeknoParrotUI.' } else { 'These counts describe saved settings, not a verified physical device binding. Test each game in TeknoParrotUI.' }

    $counts = [pscustomobject]@{
        BoundCount = ($copied.Count + $apiFixed.Count); ControlsCopiedCount = $copied.Count; SettingsOnlyCount = $settingsOnly.Count
        ApiFixedCount = $apiFixed.Count; ManualCount = $needManual.Count; SkippedCount = $skipped.Count; FailedCount = $failed.Count
        VerifiedPhysicalBindingsCount = 0; DesignSkippedItems = @($designSkipped | ForEach-Object { $_.Report })
    }
    return [pscustomobject]@{ Title = $title; Status = $status; Done = $done.ToArray(); NotChanged = $notChanged; Needs = $needs.ToArray(); Next = $next; Blocks = $blocks.ToArray(); Note = $note; Counts = $counts }
}

# Prints Invoke-ControlPropagation's $reports as the short result screen used by both the AutoSync/Register-only flow
# and the standalone "Propagate Controls" menu option, so the two entry points never drift out of sync with each other.
# Outcome and BackupPath add the saved-copy folder to the details. Returns updated/skipped counts
# and design-skipped games for informational downstream reporting, never as unfinished work.
function Write-ControlPropagationResults {
    param($Reports, [bool]$DryRun = $false, [string]$Outcome = '', [string]$BackupPath = '', [switch]$Unattended, [switch]$DeferDetails)
    $summary = Get-TpmControlPropagationSummary -Reports $Reports -DryRun $DryRun -Outcome $Outcome -BackupPath $BackupPath
    Write-TpmOutcome -Title $summary.Title -Status $summary.Status -Done $summary.Done -NotChanged $summary.NotChanged -Needs $summary.Needs -Next $summary.Next -DetailBlocks $summary.Blocks -DetailsNote $summary.Note -Unattended:$Unattended -Spaced -DeferDetails:$DeferDetails
    foreach ($report in @($summary.Counts.DesignSkippedItems)) {
        Write-Log ('Control propagation: {0}: {1}' -f $report.Code, (Get-TpmControlPropagationReportLine -Report $report -DryRun $DryRun))
    }
    if ($summary.NotChanged) { Write-Log ('Control propagation: ' + $summary.NotChanged) }
    return $summary.Counts
}

# Asks the user which control devices they have and want to use, then prints a
# tailored plan of which game to bind with which device. This is guidance
# only: it changes no game file. The answers are kept in the Manager's own
# controls file (Read-TpmCabinetState) so the same question is never asked
# twice. The actual copying happens later, after the user binds those games
# and re-runs.
function Invoke-DeviceSurvey {
    param([string]$StateRoot = '')

    # Scriptblock instead of a nested function: PowerShell nested functions
    # escape into session scope after the first call, polluting the environment
    # for the rest of the session. A scriptblock stays local to this function.
    # What is connected right now (read-only). A clear match becomes the default answer; the user can always change it.
    $evidence = Get-TpmControllerEvidence -Salt (Get-TpmControllerSalt -StateRoot $StateRoot)
    # What the player said before. A saved answer is the default, and the questions are skipped when the player keeps them.
    $cabinet = Read-TpmCabinetState -StateRoot $StateRoot
    $questions = @(Get-TpmDeviceQuestions)
    $readYesNo = {
        param([string]$q, [string]$class = '')
        $match = @($evidence.DeviceObservations | Where-Object { $class -and $_.DeviceClass -eq $class } | Select-Object -First 1)
        $saved = Get-TpmCabinetDeviceAnswer -State $cabinet -Class $class
        $default = ''
        $note = ''
        if ($match.Count -and $match[0].Confidence -eq 'High') { $default = 'Y'; $note = ' - one is connected, press Enter for Y' }
        elseif ($match.Count) { $note = ' - may be connected' }
        if ($default -eq '' -and $null -ne $saved) {
            $default = $(if ($saved) { 'Y' } else { 'N' })
            $note += $(if ($saved) { ' - you said yes last time' } else { ' - you said no last time' })
        }
        return ((Read-TpmYesNo -Prompt "   $q$note (Y/N)" -Default $default) -eq "Y")
    }

    Write-Host ""
    Write-Host " Which controls do you have and want to use?" -ForegroundColor Cyan
    Write-TpmText -Text '(Answer Y or N. This prints a plan and changes no game file. Your answers are saved so you are not asked again.)' -Color DarkCyan -Indent 1
    $setNotice = Get-TpmControllerSetNotice -Cabinet $cabinet -Evidence $evidence
    if ($setNotice.Text) { Write-TpmText -Text $setNotice.Text -Color $setNotice.Color -Indent 1 }
    Write-Host ""

    $sure = @($evidence.DeviceObservations | Where-Object { $_.Confidence -eq 'High' } | ForEach-Object { $_.DeviceClass })
    $answers = @{}
    foreach ($item in $questions) { $answers[$item.Class] = $false }
    $toSave = @($questions | ForEach-Object { $_.Class })
    $kept = $false
    $quick = $false
    # All seven answers saved: show them and ask once. A new controller of a kind the player said no to means the answers may be out of date.
    if (@($questions | Where-Object { $null -eq (Get-TpmCabinetDeviceAnswer -State $cabinet -Class $_.Class) }).Count -eq 0) {
        $newlyFound = @($questions | Where-Object { $sure -contains $_.Class -and (Get-TpmCabinetDeviceAnswer -State $cabinet -Class $_.Class) -eq $false })
        if ($newlyFound.Count -gt 0) {
            Write-TpmText -Text ' A controller was found that you said you do not have, so TPM asks again.' -Color Yellow
        } else {
            Write-TpmText -Text ' You answered these before:' -Color DarkCyan
            foreach ($item in $questions) {
                Write-TpmText -Text ('   {0}  {1}' -f $item.Question, $(if (Get-TpmCabinetDeviceAnswer -State $cabinet -Class $item.Class) { 'Yes' } else { 'No' })) -Color DarkGray
            }
            if ((Read-TpmYesNo -Prompt '   Keep these answers? (Y = yes, N = answer again)' -Default 'Y') -eq 'Y') {
                foreach ($item in $questions) { $answers[$item.Class] = [bool](Get-TpmCabinetDeviceAnswer -State $cabinet -Class $item.Class) }
                $kept = $true
                $toSave = @()
            }
        }
    }

    # One-screen shortcut: when a controller is clearly connected (High confidence),
    # offer to use just that, so the user answers one question instead of seven.
    if (-not $kept -and $sure -contains 'XboxStylePad') {
        Write-Host " Found: an Xbox-style controller." -ForegroundColor Green
        $quick = ((Read-TpmYesNo -Prompt "   Use the Xbox controller for all games? (Y = yes, N = answer the questions)" -Default 'Y') -eq 'Y')
        if ($quick) { $answers['XboxStylePad'] = $true; $toSave = @('XboxStylePad') }
    }
    if (-not $kept -and -not $quick) {
        # An arcade keyboard encoder looks like a keyboard to Windows, so say what we found and let the player confirm below.
        if (@($evidence.DeviceObservations | Where-Object { $_.DeviceClass -eq 'ArcadeEncoder' }).Count) {
            Write-TpmText ' Found: what looks like an arcade keyboard encoder (the box your arcade buttons plug into).' -Color Green
            $keyMap = Get-TpmLedBlinkyKeyMap
            if ($keyMap.Found -and @($keyMap.Controls).Count) {
                Write-TpmText "   Your lighting setup lists $(@($keyMap.Controls).Count) controls with their keys. You can confirm below." -Color DarkCyan
            }
        }
        foreach ($item in $questions) { $answers[$item.Class] = & $readYesNo $item.Question $item.Class }
    }
    if ($toSave.Count -gt 0) {
        try {
            foreach ($class in $toSave) { Set-TpmCabinetDevice -State $cabinet -Class $class -Has ([bool]$answers[$class]) -Source 'Asked' }
            Save-TpmCabinetState -State $cabinet -StateRoot $StateRoot
        } catch {
            Write-Log ('Device survey: the answers could not be saved: {0}' -f $_.Exception.Message)
            Write-TpmText -Text ' Your answers could not be saved this time. The plan below is still right.' -Color Yellow
        }
    }
    $hasXbox = $answers['XboxStylePad']; $hasArcade = $answers['ArcadeEncoder']; $hasTrackball = $answers['PointerOrTrackball']
    $hasSpinner = $answers['Spinner']; $hasWheel = $answers['Wheel']; $hasGun = $answers['LightGun']; $hasKeyboard = $answers['Keyboard']

    # Resolve one device per game family from what the user has, preferring the
    # purpose-built control and falling back to the most versatile available.
    $plan = [ordered]@{}

    if ($hasTrackball) { $plan["Trackball games (Golden Tee, Silver Strike)"] = "your trackball" }

    if     ($hasArcade)   { $plan["Fighting / classic arcade"] = "your arcade stick + buttons" }
    elseif ($hasXbox)     { $plan["Fighting / classic arcade"] = "your Xbox pad" }
    elseif ($hasKeyboard) { $plan["Fighting / classic arcade"] = "your keyboard" }

    if     ($hasWheel)   { $plan["Driving games"] = "your wheel + pedals" }
    elseif ($hasXbox)    { $plan["Driving games"] = "your Xbox pad (analog steering, triggers, gears)" }
    elseif ($hasSpinner) { $plan["Driving games"] = "your spinner for steering, buttons for gas/brake" }

    if ($hasGun) {
        $plan["Lightgun games"] = "your lightgun"
    } else {
        # No gun: trackball (relative/mouse aim) is the suggested fallback, with
        # the Xbox right stick as the alternative. Ask only if both are present.
        if ($hasTrackball -and $hasXbox) {
            Write-Host ""
            Write-Host "   No lightgun. For gun games, aim with:" -ForegroundColor Yellow
            Write-Host "     1) Trackball       (precise, but no fixed center; you roll to aim)"
            Write-Host "     2) Xbox right stick (smooth and self-centering)"
            if ((Read-TpmChoice -Prompt "   Choose 1 or 2" -Choices @('1', '2')) -eq "2") {
                $plan["Lightgun games (no gun)"] = "your Xbox right stick (analog aim)"
            } else {
                $plan["Lightgun games (no gun)"] = "your trackball (relative/mouse aim)"
            }
        }
        elseif ($hasTrackball) { $plan["Lightgun games (no gun)"] = "your trackball (relative/mouse aim)" }
        elseif ($hasXbox)      { $plan["Lightgun games (no gun)"] = "your Xbox right stick (analog aim)" }
    }

    if     ($hasXbox)     { $plan["All other games"] = "your Xbox pad" }
    elseif ($hasArcade)   { $plan["All other games"] = "your arcade stick + buttons" }
    elseif ($hasKeyboard) { $plan["All other games"] = "your keyboard" }

    Write-Host ""
    Write-Host " ----------------------------------------------------------" -ForegroundColor Cyan
    Write-Host " YOUR BINDING PLAN" -ForegroundColor Cyan
    Write-Host " ----------------------------------------------------------" -ForegroundColor Cyan
    if ($plan.Count -eq 0) {
        Write-Host "  No devices selected -- nothing to plan." -ForegroundColor Yellow
        Write-Log "Device survey: no devices selected."
        return
    }
    Write-Host " In TeknoParrotUi.exe, bind ONE game of each type below using the"
    Write-Host " device shown, then re-run this script and choose Propagate:"
    Write-Host ""
    foreach ($k in $plan.Keys) {
        Write-Host ("   - {0}" -f $k) -ForegroundColor Green
        Write-Host ("       bind with: {0}" -f $plan[$k]) -ForegroundColor DarkGray
    }
    Write-Host ""
    Write-Host " Bind each one completely, including Test, Service, Coin, Start." -ForegroundColor DarkCyan
    if (-not $hasGun -and (@($plan.Keys) -match "Lightgun")) {
        Write-Host ""
        Write-Host " Gun games without a gun aim with mouse/cursor or stick input." -ForegroundColor Yellow
        Write-Host " Propagation now also carries the aim-mode settings (relative" -ForegroundColor Yellow
        Write-Host " input, sensitivity, hide-cursor) between gun games, so they" -ForegroundColor Yellow
        Write-Host " match your bound game's settings. If one still aims oddly, check that" -ForegroundColor Yellow
        Write-Host " game's own settings in the TeknoParrot UI." -ForegroundColor Yellow
    }
    Write-Log ("Device survey: detected classes={0} status={1}" -f ((@($evidence.DeviceObservations | ForEach-Object { "$($_.DeviceClass)/$($_.Confidence)" })) -join ","), $evidence.EvidenceStatus)
    Write-Log "Device survey: plan=$($plan.Count) items; xbox=$hasXbox arcade=$hasArcade trackball=$hasTrackball spinner=$hasSpinner wheel=$hasWheel gun=$hasGun keyboard=$hasKeyboard"
}

# =============================================================================
# CONTROLLER LEARNING, EVIDENCE AND GUIDES (issues #201, #307, #267)
# =============================================================================
# Three things live here, all kept in the Manager's own controls folder (State\Controls) and never in a game file:
#   - the cabinet file (cabinet.json): which kinds of controller the player has, how many players and buttons, and which key
#     each arcade control sends (learned by pressing it, or proposed from LEDBlinky's own key map);
#   - the evidence file (control-evidence.json): when the player said a game's controls worked, which profile revision and
#     controls it was for, and whether a first-run Test/Service step or a calibration is still to do;
#   - control guides: a plain per-game list of controls, shown on screen or saved as a page that can be printed.
# Reading is separate from writing. A file that cannot be read is set aside, never overwritten unseen, and every save keeps
# the previous file as a .bak copy. Nothing here writes a TeknoParrot profile. See docs/architecture/CONTROLLER_VERIFICATION_STORE.md.

function Get-TpmControlStatePath {
    param([string]$StateRoot = '')
    $root = if ($StateRoot) { [System.IO.Path]::GetFullPath($StateRoot) }
            elseif ($script:TpmOwnedLayout -and -not [string]::IsNullOrWhiteSpace([string]$script:TpmOwnedLayout.State)) { [System.IO.Path]::GetFullPath((Join-Path ([string]$script:TpmOwnedLayout.State) 'Controls')) }
            else { [System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot 'Controls\TPM-State')) }
    return [pscustomobject]@{ Root = $root; Cabinet = (Join-Path $root 'cabinet.json'); Evidence = (Join-Path $root 'control-evidence.json'); Salt = (Join-Path $root 'controller-salt.txt') }
}

# Read-only. Status is Missing, Ok or Unreadable; Data is the parsed JSON when Ok.
function Read-TpmControlStateFile {
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return [pscustomobject]@{ Status = 'Missing'; Data = $null } }
    try {
        $data = Get-Content -LiteralPath $Path -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        if ($null -eq $data) { throw 'The file is empty.' }
        return [pscustomobject]@{ Status = 'Ok'; Data = $data }
    } catch {
        return [pscustomobject]@{ Status = 'Unreadable'; Data = $null }
    }
}

# Saves one of the two files. An unreadable file is copied aside first (and the save stops if that copy fails); a readable one
# is kept as <name>.bak. The new text is checked before it replaces anything.
function Save-TpmControlStateFile {
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)]$Data)
    $current = Read-TpmControlStateFile -Path $Path
    [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($Path))
    if ($current.Status -eq 'Unreadable') {
        $kept = $Path + '.unreadable-' + (Get-Date).ToString('yyyyMMddHHmmss', [System.Globalization.CultureInfo]::InvariantCulture)
        [System.IO.File]::Copy($Path, $kept, $false)
        Write-Log ('Controls file: {0} could not be read; a copy was kept as {1}.' -f [System.IO.Path]::GetFileName($Path), [System.IO.Path]::GetFileName($kept))
    }
    $copy = $(if ($current.Status -eq 'Ok') { $Path + '.bak' } else { '' })
    Write-TpmAtomicTextFile -Path $Path -Text (ConvertTo-Json -InputObject $Data -Depth 8) -Operation 'controls file write' -ReplacedCopyPath $copy -Validate { param([string]$Written) $null -ne ($Written | ConvertFrom-Json -ErrorAction Stop) }
}

# The seven questions of the Device Survey, in order. Class is the evidence class, or a plain name when detection cannot tell.
function Get-TpmDeviceQuestions {
    return @(
        [pscustomobject]@{ Class = 'XboxStylePad'; Question = 'Xbox / XInput controller?'; Label = 'an Xbox controller' }
        [pscustomobject]@{ Class = 'ArcadeEncoder'; Question = 'Arcade joystick + buttons?'; Label = 'arcade joystick and buttons' }
        [pscustomobject]@{ Class = 'PointerOrTrackball'; Question = 'Trackball?'; Label = 'a trackball' }
        [pscustomobject]@{ Class = 'Spinner'; Question = 'Spinner (single-axis dial)?'; Label = 'a spinner' }
        [pscustomobject]@{ Class = 'Wheel'; Question = 'Steering wheel + pedals?'; Label = 'a steering wheel and pedals' }
        [pscustomobject]@{ Class = 'LightGun'; Question = 'Lightgun?'; Label = 'a light gun' }
        [pscustomobject]@{ Class = 'Keyboard'; Question = 'Keyboard (no game controller)?'; Label = 'a keyboard' }
    )
}

# The cabinet file with every field filled in. FileStatus says whether the file was Missing, Ok or Unreadable. Read-only.
function Read-TpmCabinetState {
    param([string]$StateRoot = '')
    $file = Read-TpmControlStateFile -Path (Get-TpmControlStatePath -StateRoot $StateRoot).Cabinet
    $state = [pscustomobject]@{ Version = 1; Devices = [pscustomobject]@{}; Players = 0; ButtonsPerPlayer = 0; EncodersWhenLearned = -1; EncoderFingerprints = $null; Keys = [pscustomobject]@{}; FileStatus = $file.Status }
    if ($file.Status -eq 'Ok') {
        foreach ($name in @('Devices', 'Keys')) {
            $property = $file.Data.PSObject.Properties[$name]
            if ($property -and $property.Value -is [System.Management.Automation.PSCustomObject]) { $state.$name = $property.Value }
        }
        foreach ($name in @('Players', 'ButtonsPerPlayer', 'EncodersWhenLearned')) {
            $property = $file.Data.PSObject.Properties[$name]
            $number = 0
            if ($property -and [int]::TryParse([string]$property.Value, [ref]$number)) { $state.$name = $number }
        }
        # $null means the keys were saved before fingerprints existed (or detection could not look); an empty list means no encoder was recognized.
        $saved = $file.Data.PSObject.Properties['EncoderFingerprints']
        if ($saved -and $null -ne $saved.Value) {
            $state.EncoderFingerprints = @(@($saved.Value) | Where-Object { $_ -and [string]$_.Fingerprint -match '^[0-9a-f]{64}$' } | ForEach-Object { [pscustomobject]@{ DeviceClass = 'ArcadeEncoder'; Fingerprint = [string]$_.Fingerprint } })
        }
    }
    return $state
}

function Save-TpmCabinetState {
    param([Parameter(Mandatory)]$State, [string]$StateRoot = '')
    $data = [pscustomobject]@{ Version = 1; Devices = $State.Devices; Players = [int]$State.Players; ButtonsPerPlayer = [int]$State.ButtonsPerPlayer; EncodersWhenLearned = [int]$State.EncodersWhenLearned; EncoderFingerprints = $State.EncoderFingerprints; Keys = $State.Keys }
    Save-TpmControlStateFile -Path (Get-TpmControlStatePath -StateRoot $StateRoot).Cabinet -Data $data
}

# $true or $false when the player answered for this kind of device, $null when never asked.
function Get-TpmCabinetDeviceAnswer {
    param([Parameter(Mandatory)]$State, [Parameter(Mandatory)][string]$Class)
    $record = $State.Devices.PSObject.Properties[$Class]
    if ($null -eq $record -or $null -eq $record.Value.PSObject.Properties['Has']) { return $null }
    return [bool]$record.Value.Has
}

function Set-TpmCabinetDevice {
    param([Parameter(Mandatory)]$State, [Parameter(Mandatory)][string]$Class, [Parameter(Mandatory)][bool]$Has, [string]$Source = 'Asked')
    $record = [pscustomobject]@{ Has = $Has; Source = $Source; AnsweredUtc = (Get-Date).ToUniversalTime().ToString('o') }
    Add-Member -InputObject $State.Devices -NotePropertyName $Class -NotePropertyValue $record -Force
}

# Keys: control id -> @{ Key; Source }. Controls not in $Keys keep what was saved before.
function Set-TpmCabinetKeys {
    param([Parameter(Mandatory)]$State, [Parameter(Mandatory)]$Keys, [int]$Players = 0, [int]$ButtonsPerPlayer = 0)
    foreach ($control in @($Keys.Keys)) {
        $record = [pscustomobject]@{ Key = [string]$Keys[$control].Key; Source = [string]$Keys[$control].Source; LearnedUtc = (Get-Date).ToUniversalTime().ToString('o') }
        Add-Member -InputObject $State.Keys -NotePropertyName ([string]$control) -NotePropertyValue $record -Force
    }
    if ($Players -gt 0) { $State.Players = $Players }
    if ($ButtonsPerPlayer -gt 0) { $State.ButtonsPerPlayer = $ButtonsPerPlayer }
}

function Get-TpmCabinetKey {
    param([Parameter(Mandatory)]$State, [Parameter(Mandatory)][string]$Control)
    $record = $State.Keys.PSObject.Properties[$Control]
    if ($null -eq $record) { return '' }
    return [string]$record.Value.Key
}

# Plain display name for a key. From Console is a .NET ConsoleKey name; from Mame is a MAME key code as LEDBlinky lists it.
# An unknown MAME code gives '' so the player is asked instead of TPM guessing.
function ConvertTo-TpmKeyName {
    param([Parameter(Mandatory)][string]$Name, [ValidateSet('Console', 'Mame')][string]$From = 'Console')
    $n = $Name.Trim()
    if ($From -eq 'Mame') {
        $n = $n -replace '^KEYCODE_', ''
        $mame = @{ LCONTROL = 'Left Ctrl'; RCONTROL = 'Right Ctrl'; LALT = 'Left Alt'; RALT = 'Right Alt'; LSHIFT = 'Left Shift'; RSHIFT = 'Right Shift'
                   SPACE = 'Space'; ENTER = 'Enter'; ESC = 'Escape'; TAB = 'Tab'; UP = 'Up arrow'; DOWN = 'Down arrow'; LEFT = 'Left arrow'; RIGHT = 'Right arrow' }
        if ($mame.ContainsKey($n)) { return $mame[$n] }
        if ($n -match '^[0-9A-Z]$' -or $n -match '^F\d{1,2}$') { return $n }
        return ''
    }
    $console = @{ Spacebar = 'Space'; LeftArrow = 'Left arrow'; RightArrow = 'Right arrow'; UpArrow = 'Up arrow'; DownArrow = 'Down arrow' }
    if ($console.ContainsKey($n)) { return $console[$n] }
    if ($n -match '^D(\d)$') { return $Matches[1] }
    if ($n -match '^NumPad(\d)$') { return ('Numpad ' + $Matches[1]) }
    return $n
}

# The controls TPM asks about, as TeknoParrot names them (Coin1, P1ButtonStart, P1ButtonUp, P1Button1, Test, Service).
function Get-TpmCabinetControlList {
    param([ValidateRange(1, 4)][int]$Players = 2, [ValidateRange(1, 8)][int]$Buttons = 6)
    $list = New-Object System.Collections.Generic.List[object]
    for ($p = 1; $p -le $Players; $p++) {
        [void]$list.Add([pscustomobject]@{ Control = "Coin$p"; Label = "Player $p Coin" })
        [void]$list.Add([pscustomobject]@{ Control = "P${p}ButtonStart"; Label = "Player $p Start" })
        foreach ($direction in @('Up', 'Down', 'Left', 'Right')) { [void]$list.Add([pscustomobject]@{ Control = "P${p}Button$direction"; Label = "Player $p joystick $direction" }) }
        for ($b = 1; $b -le $Buttons; $b++) { [void]$list.Add([pscustomobject]@{ Control = "P${p}Button$b"; Label = "Player $p button $b" }) }
    }
    [void]$list.Add([pscustomobject]@{ Control = 'Test'; Label = 'the Test button' })
    [void]$list.Add([pscustomobject]@{ Control = 'Service'; Label = 'the Service button' })
    return @($list.ToArray())
}

# Proposals from LEDBlinky's own key map (Get-TpmLedBlinkyKeyMap): control id -> key name, only for the controls asked about and
# only for LED labels TPM recognizes. Anything else is left for the player to press.
function Get-TpmKeysFromLedBlinkyMap {
    param($KeyMap, [Parameter(Mandatory)][object[]]$Controls)
    $found = [ordered]@{}
    if ($null -eq $KeyMap -or -not [bool]$KeyMap.Found) { return $found }
    $wanted = @{}
    foreach ($control in $Controls) { $wanted[[string]$control.Control] = $true }
    foreach ($led in @($KeyMap.Controls)) {
        $label = ([string]$led.Control).ToUpperInvariant() -replace '[_\s]', ''
        $id = ''
        if ($label -match '^P(\d)B(?:UTTON)?(\d+)$') { $id = 'P{0}Button{1}' -f $Matches[1], [int]$Matches[2] }
        elseif ($label -match '^P(\d)START$') { $id = 'P{0}ButtonStart' -f $Matches[1] }
        elseif ($label -match '^START(\d)$') { $id = 'P{0}ButtonStart' -f $Matches[1] }
        elseif ($label -match '^COIN(\d)$') { $id = 'Coin{0}' -f $Matches[1] }
        elseif ($label -match '^P(\d)(?:JOYSTICK|JOY|STICK)?(UP|DOWN|LEFT|RIGHT)$') { $id = 'P{0}Button{1}{2}' -f $Matches[1], $Matches[2].Substring(0, 1), $Matches[2].Substring(1).ToLowerInvariant() }
        if (-not $id -or -not $wanted.ContainsKey($id) -or $found.Contains($id)) { continue }
        $code = @($led.InputCodes | Where-Object { ([string]$_) -like 'KEYCODE_*' } | Select-Object -First 1)
        if ($code.Count -eq 0) { continue }
        $name = ConvertTo-TpmKeyName -Name ([string]$code[0]) -From Mame
        if ($name) { $found[$id] = $name }
    }
    return $found
}

function Test-TpmKeyPressAvailable { return (-not [Console]::IsInputRedirected) }

function Initialize-TpmKeyProbe {
    if (-not ('TpmKeyProbe' -as [type])) {
        Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public static class TpmKeyProbe { [DllImport("user32.dll")] static extern short GetAsyncKeyState(int k); public static bool Down(int k) { return (GetAsyncKeyState(k) & 0x8000) != 0; } public static int Modifier() { int[] keys = { 0xA0, 0xA1, 0xA2, 0xA3, 0xA4, 0xA5 }; foreach (int k in keys) { if (Down(k)) return k; } return 0; } }'
    }
}

# Windows virtual-key codes of the six Shift, Ctrl and Alt keys, with the plain names TPM shows.
function Get-TpmModifierNames { return @{ 160 = 'Left Shift'; 161 = 'Right Shift'; 162 = 'Left Ctrl'; 163 = 'Right Ctrl'; 164 = 'Left Alt'; 165 = 'Right Alt' } }

# The key name inside what a key reader returned: a plain name, or an object with Key.
function Get-TpmPressKey {
    param($Press)
    if ($null -eq $Press) { return '' }
    if ($Press -is [string]) { return $Press }
    return [string]$Press.Key
}

# Waits for one key press. Returns '' when nothing was pressed in time, otherwise { Key; Also; Held }:
#   Key   the plain name ('Escape' for Esc). Ctrl, Alt and Shift do not reach the console on their own, so Windows' key state is watched too.
#   Also  other keys that arrived within 80 ms of it (a button that sends two keys, or two buttons on one wire).
#   Held  the key was still down 3 seconds later (a stuck or jammed button).
function Read-TpmLearnKey {
    param([int]$TimeoutSeconds = 30)
    Initialize-TpmKeyProbe
    $modifierNames = Get-TpmModifierNames
    while ([Console]::KeyAvailable) { [void][Console]::ReadKey($true) }
    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
    while ((Get-Date) -lt $deadline) {
        $first = ''; $firstCode = 0
        if ([Console]::KeyAvailable) { $info = [Console]::ReadKey($true); $first = ConvertTo-TpmKeyName -Name $info.Key.ToString(); $firstCode = [int]$info.Key }
        else { $modifier = [TpmKeyProbe]::Modifier(); if ($modifier -ne 0) { $first = [string]$modifierNames[[int]$modifier]; $firstCode = $modifier } }
        if ($first) {
            Start-Sleep -Milliseconds 80
            $also = New-Object System.Collections.Generic.List[string]
            while ([Console]::KeyAvailable) { $name = ConvertTo-TpmKeyName -Name ([Console]::ReadKey($true).Key.ToString()); if ($name -ne $first -and -not $also.Contains($name)) { [void]$also.Add($name) } }
            foreach ($code in 160..165) { $name = [string]$modifierNames[$code]; if ($code -ne $firstCode -and $name -ne $first -and [TpmKeyProbe]::Down($code) -and -not $also.Contains($name)) { [void]$also.Add($name) } }
            $stopWaiting = (Get-Date).AddSeconds(3)
            while ([TpmKeyProbe]::Down($firstCode) -and (Get-Date) -lt $stopWaiting) { Start-Sleep -Milliseconds 20 }
            $held = [TpmKeyProbe]::Down($firstCode)
            while ([Console]::KeyAvailable) { [void][Console]::ReadKey($true) }
            return [pscustomobject]@{ Key = $first; Also = @($also.ToArray()); Held = $held }
        }
        Start-Sleep -Milliseconds 25
    }
    return ''
}

# Watches the keyboard while nobody should be touching the cabinet. Returns the names of keys that were pressed or kept arriving
# on their own (a button stuck down, a wire shorted): empty when all stayed quiet.
function Get-TpmKeysPressedOnTheirOwn {
    param([int]$Seconds = 2)
    Initialize-TpmKeyProbe
    $modifierNames = Get-TpmModifierNames
    $names = New-Object System.Collections.Generic.List[string]
    Start-Sleep -Milliseconds 400
    while ([Console]::KeyAvailable) { [void][Console]::ReadKey($true) }
    $deadline = (Get-Date).AddSeconds($Seconds)
    while ((Get-Date) -lt $deadline) {
        while ([Console]::KeyAvailable) { $name = ConvertTo-TpmKeyName -Name ([Console]::ReadKey($true).Key.ToString()); if (-not $names.Contains($name)) { [void]$names.Add($name) } }
        foreach ($code in 160..165) { if ([TpmKeyProbe]::Down($code) -and -not $names.Contains([string]$modifierNames[$code])) { [void]$names.Add([string]$modifierNames[$code]) } }
        Start-Sleep -Milliseconds 25
    }
    return @($names.ToArray())
}

# Asks for each control in turn ("Press Player 1 Start") and records the key. -ReadKey is the key reader (a script block, so tests
# need no keyboard); it returns a key name or an object with Key, Also and Held (see Read-TpmLearnKey). Esc skips a control, a key
# already given to another control is refused, and nothing pressed asks whether to stop. -Known holds keys already given
# (control id -> key name) so they count for the duplicate check.
# Two things are only reported, never decided: a press that also sent another key (Together), and a button still down after
# 3 seconds (Held). The first key is kept either way. Together lists, per control, the other keys that came with it.
function Invoke-TpmLearnKeys {
    param([Parameter(Mandatory)][object[]]$Controls, [Parameter(Mandatory)][scriptblock]$ReadKey, [System.Collections.IDictionary]$Known = $null)
    $learned = [ordered]@{}
    $skipped = New-Object System.Collections.Generic.List[string]
    $held = New-Object System.Collections.Generic.List[string]
    $together = [ordered]@{}
    $stopped = $false
    $number = 0
    foreach ($control in $Controls) {
        $number++
        while ($true) {
            Write-TpmText -Text ('({0} of {1}) Press {2}   (Esc = skip)' -f $number, $Controls.Count, $control.Label) -Color Cyan
            $press = & $ReadKey
            $key = Get-TpmPressKey -Press $press
            if ($key -eq '') {
                if ((Read-TpmYesNo -Prompt '  Nothing was pressed. Stop learning here? (Y/N)' -Default 'N') -eq 'Y') { $stopped = $true; break }
                continue
            }
            if ($key -eq 'Escape') { [void]$skipped.Add([string]$control.Label); break }
            $owner = ''
            foreach ($name in @($learned.Keys)) { if ($learned[$name] -eq $key) { $owner = $name } }
            if ($null -ne $Known) { foreach ($name in @($Known.Keys)) { if ([string]$Known[$name] -eq $key -and -not $owner) { $owner = $name } } }
            if ($owner) {
                $ownerLabel = @($Controls | Where-Object { $_.Control -eq $owner } | ForEach-Object { $_.Label } | Select-Object -First 1)
                Write-TpmText -Text ('That key ({0}) is already used for {1}. Press a different control, or Esc to skip.' -f $key, $(if ($ownerLabel.Count) { $ownerLabel[0] } else { $owner })) -Color Yellow
                continue
            }
            $learned[[string]$control.Control] = $key
            Write-TpmText -Text ('Got it: {0}' -f $key) -Color Green -Indent 4
            $also = @(); $isHeld = $false
            if ($press -isnot [string] -and $null -ne $press) { $also = @($press.Also | Where-Object { $_ }); $isHeld = [bool]$press.Held }
            if ($also.Count -gt 0) {
                $together[[string]$control.Control] = $also
                Write-TpmText -Text ('Pressing this also sent {0}. TPM kept {1}. Some encoders do this on purpose. Two buttons on one wire can do it too.' -f ($also -join ' and '), $key) -Color Yellow -Indent 4
            }
            if ($isHeld) {
                [void]$held.Add([string]$control.Label)
                Write-TpmText -Text 'This button was still down after 3 seconds. It may be stuck. Check it before you rely on it.' -Color Yellow -Indent 4
            }
            break
        }
        if ($stopped) { break }
    }
    # The same extra key arriving with two or more different controls is the clear sign of something wired together or stuck.
    $labels = @{}
    foreach ($control in $Controls) { $labels[[string]$control.Control] = [string]$control.Label }
    $byKey = @{}
    foreach ($id in $together.Keys) { foreach ($extra in $together[$id]) { if (-not $byKey.ContainsKey($extra)) { $byKey[$extra] = New-Object System.Collections.Generic.List[string] }; [void]$byKey[$extra].Add($labels[$id]) } }
    foreach ($extra in @($byKey.Keys | Sort-Object)) {
        if ($byKey[$extra].Count -ge 2) { Write-TpmText -Text ('{0} came along with {1} different controls ({2}). Something may be wired together, or stuck.' -f $extra, $byKey[$extra].Count, ($byKey[$extra] -join ', ')) -Color Yellow }
    }
    return [pscustomobject]@{ Keys = $learned; Skipped = @($skipped.ToArray()); Stopped = $stopped; Together = $together; Held = @($held.ToArray()) }
}

# Plain lines about what the cabinet file holds. Used by the My controls screen and the printable cabinet page.
function Get-TpmCabinetSummaryLines {
    param([Parameter(Mandatory)]$State)
    $lines = New-Object System.Collections.Generic.List[string]
    $have = @(Get-TpmDeviceQuestions | Where-Object { (Get-TpmCabinetDeviceAnswer -State $State -Class $_.Class) -eq $true } | ForEach-Object { $_.Label })
    $answered = @(Get-TpmDeviceQuestions | Where-Object { $null -ne (Get-TpmCabinetDeviceAnswer -State $State -Class $_.Class) }).Count
    if ($answered -eq 0) { [void]$lines.Add('You have not told TPM which controls you have yet.') }
    elseif ($have.Count -eq 0) { [void]$lines.Add('You told TPM you have none of the listed controls.') }
    else { [void]$lines.Add('You told TPM you have: ' + ($have -join ', ') + '.') }
    $keyCount = @($State.Keys.PSObject.Properties).Count
    if ($keyCount -gt 0) {
        $text = ('TPM knows the key for {0} of your arcade controls' -f $keyCount)
        if ($State.Players -gt 0) { $text += (' ({0} {1}, {2} {3} each)' -f $State.Players, $(if ($State.Players -eq 1) { 'player' } else { 'players' }), $State.ButtonsPerPlayer, $(if ($State.ButtonsPerPlayer -eq 1) { 'button' } else { 'buttons' })) }
        [void]$lines.Add($text + '.')
    } else {
        [void]$lines.Add('TPM has not learned which key each arcade control sends.')
    }
    return @($lines.ToArray())
}

# The key layout that MAME and Ultimarc I-PAC boards both ship with (control id -> key name). Sources: MAME's default keys page
# (docs.mamedev.org/usingmame/defaultkeys.html) and Ultimarc's "Default Keycode Table" (ultimarc.com/control-interfaces/i-pacs/i-pac2/).
# Only controls where the two lists agree are here. They differ for player 2 buttons 5 to 8 and for player 4, and neither
# lists Test or Service, so those are left out. An encoder can be changed, so these keys are only used after a check.
function Get-TpmStandardArcadeKeys {
    $keys = [ordered]@{}
    $coin = @('5', '6', '7', '8'); $start = @('1', '2', '3', '4')
    for ($p = 1; $p -le 4; $p++) { $keys["Coin$p"] = $coin[$p - 1]; $keys["P${p}ButtonStart"] = $start[$p - 1] }
    $sticks = @{ 1 = @('Up arrow', 'Down arrow', 'Left arrow', 'Right arrow'); 2 = @('R', 'F', 'D', 'G'); 3 = @('I', 'K', 'J', 'L') }
    $buttons = @{ 1 = @('Left Ctrl', 'Left Alt', 'Space', 'Left Shift', 'Z', 'X', 'C', 'V'); 2 = @('A', 'S', 'Q', 'W'); 3 = @('Right Ctrl', 'Right Shift', 'Enter') }
    foreach ($p in 1..3) {
        $i = 0
        foreach ($direction in @('Up', 'Down', 'Left', 'Right')) { $keys["P${p}Button$direction"] = $sticks[$p][$i]; $i++ }
        $n = 0
        foreach ($key in $buttons[$p]) { $n++; $keys["P${p}Button$n"] = $key }
    }
    return $keys
}

# Asks the player to press player 1 Start and player 1 button 1, and passes only when both send the key the standard layout says.
# A guess about the layout is never kept on its own: a changed encoder fails this check. Reason: NoCheck, NothingPressed or Different.
function Test-TpmStandardKeysSpotCheck {
    param([Parameter(Mandatory)]$Proposed, [Parameter(Mandatory)][object[]]$Controls, [Parameter(Mandatory)][scriptblock]$ReadKey)
    $checks = @($Controls | Where-Object { $_.Control -in @('P1ButtonStart', 'P1Button1') -and $Proposed.Contains([string]$_.Control) })
    if ($checks.Count -eq 0) { return [pscustomobject]@{ Passed = $false; Reason = 'NoCheck'; Got = '' } }
    foreach ($check in $checks) {
        Write-TpmText -Text ('To check, press {0}.' -f $check.Label) -Color Cyan
        $key = Get-TpmPressKey -Press (& $ReadKey)
        if ($key -eq '' -or $key -eq 'Escape') { return [pscustomobject]@{ Passed = $false; Reason = 'NothingPressed'; Got = '' } }
        if ($key -ne [string]$Proposed[[string]$check.Control]) { return [pscustomobject]@{ Passed = $false; Reason = 'Different'; Got = $key } }
    }
    return [pscustomobject]@{ Passed = $true; Reason = ''; Got = '' }
}

# How many arcade encoders detection can see right now at Medium or High confidence; -1 when detection could not look.
function Get-TpmEncoderCount {
    param($Evidence)
    if ($null -eq $Evidence -or [string]$Evidence.EvidenceStatus -ne 'Observed') { return -1 }
    return [int](@($Evidence.DeviceObservations | Where-Object { $_.DeviceClass -eq 'ArcadeEncoder' -and $_.Confidence -in @('High', 'Medium') } | Measure-Object -Property Count -Sum).Sum)
}

# A hint, never a decision: the number of encoders TPM could see when the buttons were learned differs from now. The count is a
# note about the past. It is not evidence about the present, and no vendor or product number is involved.
function Get-TpmEncoderChangeNotice {
    param([Parameter(Mandatory)]$Cabinet, [Parameter(Mandatory)][int]$EncodersNow)
    $then = [int]$Cabinet.EncodersWhenLearned
    if (@($Cabinet.Keys.PSObject.Properties).Count -eq 0 -or $then -lt 0 -or $EncodersNow -lt 0 -or $then -eq $EncodersNow) { return '' }
    return ('When you taught TPM your buttons it could see {0} arcade encoder{1}. Now it sees {2}. If you changed your encoder, learn your buttons again.' -f $then, $(if ($then -eq 1) { '' } else { 's' }), $EncodersNow)
}

# The one-way salt for controller fingerprints. It lives in the Controls state folder, is made once, and never leaves the PC.
# Reading never writes. With -Create a missing (or damaged) salt is made. Returns '' when there is none or it could not be made.
function Get-TpmControllerSalt {
    param([string]$StateRoot = '', [switch]$Create)
    try {
        $path = (Get-TpmControlStatePath -StateRoot $StateRoot).Salt
        if (Test-Path -LiteralPath $path -PathType Leaf) {
            $text = (Get-Content -LiteralPath $path -Raw -Encoding UTF8 -ErrorAction Stop).Trim()
            if ($text -match '^[0-9a-f]{32}$') { return $text }
        }
        if (-not $Create) { return '' }
        $bytes = New-Object byte[] 16
        $random = [System.Security.Cryptography.RandomNumberGenerator]::Create()
        try { $random.GetBytes($bytes) } finally { $random.Dispose() }
        $salt = (@($bytes | ForEach-Object { $_.ToString('x2') }) -join '')
        [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($path))
        Write-TpmAtomicTextFile -Path $path -Text $salt -Operation 'controller key write' -Validate { param([string]$Written) $Written.Trim() -match '^[0-9a-f]{32}$' }
        return $salt
    } catch {
        Write-Log 'Controls: the key used to recognize your controllers could not be read or made.'
        return ''
    }
}

# The fingerprints of the arcade encoders in an evidence object. $null when there is nothing to compare (detection could not look,
# or no salt was given); an empty list when it looked and recognized none. They are one-way hashes, never shown as a device name.
function Get-TpmEncoderFingerprints {
    param($Evidence)
    if ($null -eq $Evidence -or [string]$Evidence.EvidenceStatus -ne 'Observed') { return $null }
    $property = $Evidence.PSObject.Properties['DeviceFingerprints']
    if ($null -eq $property -or $null -eq $property.Value) { return $null }
    return , @(@($property.Value) | Where-Object { $_.DeviceClass -eq 'ArcadeEncoder' } | ForEach-Object { [pscustomobject]@{ DeviceClass = 'ArcadeEncoder'; Fingerprint = [string]$_.Fingerprint } })
}

# One plain sentence about whether the controllers are the same as when the player taught TPM the keys. A HINT only: it never
# changes a saved key and never marks anything Verified. State is NoKeys, Same, Added, Removed, Changed, CouldNotCheck or NoNote
# (keys saved before fingerprints existed, and the count did not change). Only makers TPM recognizes can be compared.
function Get-TpmControllerSetNotice {
    param([Parameter(Mandatory)]$Cabinet, $Evidence)
    $result = { param($State, $Text, $Color) [pscustomobject]@{ State = $State; Text = $Text; Color = $Color } }
    if (@($Cabinet.Keys.PSObject.Properties).Count -eq 0) { return & $result 'NoKeys' '' 'DarkGray' }
    $cannot = 'TPM could not look at your controllers, so it cannot tell if they changed since you taught it your keys.'
    if ($null -eq $Evidence -or [string]$Evidence.EvidenceStatus -ne 'Observed') { return & $result 'CouldNotCheck' $cannot 'DarkGray' }
    $then = $Cabinet.EncoderFingerprints
    if ($null -eq $then) {
        $countNotice = Get-TpmEncoderChangeNotice -Cabinet $Cabinet -EncodersNow (Get-TpmEncoderCount -Evidence $Evidence)
        return & $result $(if ($countNotice) { 'Changed' } else { 'NoNote' }) $countNotice 'Yellow'
    }
    $now = Get-TpmEncoderFingerprints -Evidence $Evidence
    if ($null -eq $now) { return & $result 'CouldNotCheck' $cannot 'DarkGray' }
    $thenIds = @($then | ForEach-Object { [string]$_.Fingerprint })
    $nowIds = @($now | ForEach-Object { [string]$_.Fingerprint })
    if ($thenIds.Count -eq 0 -and $nowIds.Count -eq 0) { return & $result 'CouldNotCheck' 'TPM does not recognize your arcade encoder by itself, so it cannot tell if you changed it.' 'DarkGray' }
    $added = @($nowIds | Where-Object { $thenIds -notcontains $_ })
    $removed = @($thenIds | Where-Object { $nowIds -notcontains $_ })
    $learnAgain = ' If you changed your controller, learn your buttons again. Your saved keys were not changed.'
    if ($added.Count -eq 0 -and $removed.Count -eq 0) {
        return & $result 'Same' ('TPM sees the same arcade encoder{0} as when you taught it your keys.' -f $(if ($nowIds.Count -eq 1) { '' } else { 's' })) 'Green'
    }
    if ($removed.Count -eq 0) { return & $result 'Added' ('A new arcade encoder is plugged in that was not there when you taught TPM your keys.' + $learnAgain) 'Yellow' }
    if ($added.Count -eq 0) { return & $result 'Removed' ('An arcade encoder that was plugged in when you taught TPM your keys is not plugged in now.' + $learnAgain) 'Yellow' }
    return & $result 'Changed' ('Your arcade encoders are different from when you taught TPM your keys.' + $learnAgain) 'Yellow'
}

# The screen that learns the arcade buttons. Nothing is saved until the player says Y at the end.
function Invoke-TpmButtonLearning {
    param([string]$StateRoot = '')
    Write-Host ''
    Write-TpmText -Text 'Learn my arcade buttons' -Color Cyan
    Write-TpmText -Text 'TPM asks you to press each control on your cabinet and remembers the key it sends. No game file is changed.' -Color DarkCyan
    if (-not (Test-TpmKeyPressAvailable)) {
        Write-TpmText -Text 'This needs a normal console window where TPM can see key presses, so it cannot run here.' -Color Yellow
        return
    }
    $cabinet = Read-TpmCabinetState -StateRoot $StateRoot
    $players = [int](Read-TpmChoice -Prompt '  How many players does your cabinet have? (1-4)' -Choices @('1', '2', '3', '4') -Default $(if ($cabinet.Players -ge 1 -and $cabinet.Players -le 4) { [string]$cabinet.Players } else { '2' }))
    $buttons = [int](Read-TpmChoice -Prompt '  How many action buttons does each player have? (1-8)' -Choices @('1', '2', '3', '4', '5', '6', '7', '8') -Default $(if ($cabinet.ButtonsPerPlayer -ge 1 -and $cabinet.ButtonsPerPlayer -le 8) { [string]$cabinet.ButtonsPerPlayer } else { '6' }))
    $controls = @(Get-TpmCabinetControlList -Players $players -Buttons $buttons)
    $keys = [ordered]@{}
    $labels = @{}
    foreach ($control in $controls) { $labels[[string]$control.Control] = [string]$control.Label }

    # Before anything is pressed: is a button already stuck down, or are keys arriving on their own?
    Write-TpmText -Text 'First TPM checks that no button is stuck. Keep your hands off the cabinet for 2 seconds.' -Color DarkCyan -BlankBefore
    $onTheirOwn = @(Get-TpmKeysPressedOnTheirOwn)
    if ($onTheirOwn.Count -gt 0) {
        Write-TpmText -Text ('Keys are arriving with nobody pressing a button: ' + ($onTheirOwn -join ', ') + '. A button may be stuck down, or two wires may touch.') -Color Yellow
        if ((Read-TpmYesNo -Prompt '  Continue anyway? The keys below may be learned wrong. (Y/N)' -Default 'N') -ne 'Y') { Write-TpmText -Text 'Stopped. Nothing was saved.' -Color DarkGray; return }
    }

    # LEDBlinky keeps its own list of which key each control sends. Offer it first so only the rest has to be pressed.
    $ledRoot = [string](Get-Variable -Name ledBlinkyRoot -Scope Script -ValueOnly -ErrorAction SilentlyContinue)
    $proposed = Get-TpmKeysFromLedBlinkyMap -KeyMap (Get-TpmLedBlinkyKeyMap -Root @($ledRoot)) -Controls $controls
    if ($proposed.Count -gt 0) {
        Write-TpmText -Text ('Your LEDBlinky setup lists the key for {0} of these {1} controls:' -f $proposed.Count, $controls.Count) -Color DarkCyan -BlankBefore
        foreach ($id in $proposed.Keys) { Write-TpmText -Text ('{0} = {1}' -f $labels[$id], $proposed[$id]) -Color DarkGray -Indent 4 }
        if ((Read-TpmYesNo -Prompt '  Use these keys? (Y = yes, N = I will press them myself)' -Default 'Y') -eq 'Y') {
            foreach ($id in $proposed.Keys) { $keys[$id] = @{ Key = $proposed[$id]; Source = 'LedBlinkyKeyMap' } }
        }
    }
    # The standard arcade keys (MAME and Ultimarc I-PAC ship with them) for the controls still open. Used only after the player
    # says the encoder was never changed and a button press on the cabinet agrees.
    $standard = Get-TpmStandardArcadeKeys
    $standardOffer = [ordered]@{}
    $taken = @($keys.Values | ForEach-Object { $_.Key })
    foreach ($control in $controls) {
        $id = [string]$control.Control
        if (-not $keys.Contains($id) -and $standard.Contains($id) -and $taken -notcontains $standard[$id]) { $standardOffer[$id] = $standard[$id] }
    }
    if ($standardOffer.Count -gt 0) {
        Write-TpmText -Text ('Many arcade encoders ship with the standard arcade keys that MAME and Ultimarc I-PAC boards use. If yours was never changed, TPM can use them for {0} controls.' -f $standardOffer.Count) -Color DarkCyan -BlankBefore
        $showStandard = { foreach ($id in $standardOffer.Keys) { Write-TpmText -Text ('{0} = {1}' -f $labels[$id], $standardOffer[$id]) -Color DarkGray -Indent 4 } }
        if ((Read-TpmYesNo -Prompt '  Try the standard keys? TPM checks two buttons first. (Y/N, D = show the keys)' -Default 'N' -DetailsAction $showStandard) -eq 'Y') {
            $check = Test-TpmStandardKeysSpotCheck -Proposed $standardOffer -Controls $controls -ReadKey { Read-TpmLearnKey }
            if ($check.Passed) {
                foreach ($id in $standardOffer.Keys) { $keys[$id] = @{ Key = $standardOffer[$id]; Source = 'StandardArcadeKeys' } }
                Write-TpmText -Text 'Both buttons sent the standard keys, so TPM will use them.' -Color Green
            } elseif ($check.Reason -eq 'Different') {
                Write-TpmText -Text ('That button sent {0}, not the standard key. Your encoder is not set to the standard keys, so you will press each control yourself.' -f $check.Got) -Color Yellow
            } else {
                Write-TpmText -Text 'TPM did not see the check button, so it will not use the standard keys. You will press each control yourself.' -Color Yellow
            }
        }
    }
    $known = [ordered]@{}
    foreach ($id in $keys.Keys) { $known[$id] = $keys[$id].Key }
    $remaining = @($controls | Where-Object { -not $keys.Contains([string]$_.Control) })
    $skipped = @()
    if ($remaining.Count -gt 0) {
        Write-TpmText -Text 'Turn your cabinet on. When TPM names a control, press it once. Press Esc to skip one that your cabinet does not have.' -Color DarkCyan -BlankBefore
        $result = Invoke-TpmLearnKeys -Controls $remaining -ReadKey { Read-TpmLearnKey } -Known $known
        foreach ($id in $result.Keys.Keys) { $keys[$id] = @{ Key = $result.Keys[$id]; Source = 'PressedByPlayer' } }
        $skipped = @($result.Skipped)
    }
    Write-Host ''
    if ($keys.Count -eq 0) { Write-TpmText -Text 'No key was learned, so nothing was saved.' -Color Yellow; return }
    Write-TpmText -Text ('TPM learned the key for {0} of {1} controls.' -f $keys.Count, $controls.Count) -Color Green
    if ($skipped.Count -gt 0) { Write-TpmText -Text ('Skipped: ' + ($skipped -join ', ') + '.') -Color DarkGray }
    if ((Read-TpmYesNo -Prompt '  Save this? (Keys you saved before for these controls are replaced. A copy of the old file is kept.) (Y/N)' -Default 'Y') -ne 'Y') {
        Write-TpmText -Text 'Not saved.' -Color DarkGray
        return
    }
    try {
        Set-TpmCabinetKeys -State $cabinet -Keys $keys -Players $players -ButtonsPerPlayer $buttons
        $seen = Get-TpmControllerEvidence -Salt (Get-TpmControllerSalt -StateRoot $StateRoot -Create)
        $cabinet.EncodersWhenLearned = (Get-TpmEncoderCount -Evidence $seen)
        $cabinet.EncoderFingerprints = (Get-TpmEncoderFingerprints -Evidence $seen)
        Save-TpmCabinetState -State $cabinet -StateRoot $StateRoot
        Write-Log ('Controls: learned {0} of {1} arcade controls ({2} players, {3} buttons each).' -f $keys.Count, $controls.Count, $players, $buttons)
        Write-TpmText -Text 'Saved. TPM will not ask you to press these again.' -Color Green
    } catch {
        Write-Log ('Controls: the learned keys could not be saved: {0}' -f $_.Exception.Message)
        Write-TpmText -Text 'The keys could not be saved, so TPM will ask again next time.' -Color Yellow
    }
}

# --- Gameplay verification evidence (#307) ----------------------------------
# Who a profile is for the purpose of verification: its revision and a hash of its control bindings plus its Input API. When
# either changes, earlier evidence no longer describes the game and is treated as stale.
function Get-TpmControlProfileIdentity {
    param([Parameter(Mandatory)]$Doc)
    $revisionNode = $Doc.SelectSingleNode('/GameProfile/GameProfileRevision')
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($button in @(Get-ButtonNodes $Doc)) {
        $mapping = $button.SelectSingleNode('InputMapping')
        $bindings = @(@('XInputButton', 'DirectInputButton', 'RawInputButton') | ForEach-Object { $node = $button.SelectSingleNode($_); if ($node) { $node.OuterXml } })
        [void]$lines.Add(('{0}|{1}' -f $(if ($mapping) { $mapping.InnerText.Trim() } else { '' }), ($bindings -join '')))
    }
    $api = Get-ProfileInputApi $Doc
    $canonical = ((@($lines.ToArray() | Sort-Object)) -join "`n") + "`napi=" + [string]$api
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { $hash = (@($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($canonical)) | ForEach-Object { $_.ToString('x2') }) -join '') } finally { $sha.Dispose() }
    return [pscustomobject]@{ Revision = $(if ($revisionNode) { $revisionNode.InnerText.Trim() } else { '' }); Hash = $hash; InputApi = [string]$api; Family = (Get-ProfileFamily $Doc) }
}

# Finds the record of one game and applies $Change to it, then saves the evidence file. A new record starts with every step Unknown.
function Update-TpmGameEvidence {
    param([Parameter(Mandatory)][string]$Code, [Parameter(Mandatory)][scriptblock]$Change, [string]$StateRoot = '')
    $path = (Get-TpmControlStatePath -StateRoot $StateRoot).Evidence
    $file = Read-TpmControlStateFile -Path $path
    $games = @()
    if ($file.Status -eq 'Ok' -and $file.Data.PSObject.Properties['Games']) { $games = @($file.Data.Games) }
    $record = @($games | Where-Object { $_.Code -ieq $Code } | Select-Object -First 1)
    if ($record.Count -eq 0) {
        $record = @([pscustomobject]@{ Code = $Code; Title = ''; Verification = $null; FirstRun = 'Unknown'; FirstRunAt = ''; Calibration = 'Unknown'; CalibrationAt = ''; CalibrationHash = '' })
        $games = @($games) + $record
    }
    & $Change $record[0]
    Save-TpmControlStateFile -Path $path -Data ([pscustomobject]@{ Version = 1; Games = @($games) })
}

# Records that the player played the game and its controls worked. This is the only way a game becomes Verified.
function Save-TpmGameVerification {
    param([Parameter(Mandatory)][string]$Code, [Parameter(Mandatory)][string]$Title, [Parameter(Mandatory)]$Doc, [string]$StateRoot = '')
    $identity = Get-TpmControlProfileIdentity -Doc $Doc
    Update-TpmGameEvidence -Code $Code -StateRoot $StateRoot -Change {
        param($record)
        $record.Title = $Title
        $record.Verification = [pscustomobject]@{ Method = 'PlayerReportedPlayTest'; ObservedAt = (Get-Date).ToUniversalTime().ToString('o'); Game = $Title; ProfileRevision = $identity.Revision; ProfileHash = $identity.Hash; ControllerContext = $identity.InputApi }
    }
}

# Forgets the verification of one game (the player says it does not work).
function Remove-TpmGameVerification {
    param([Parameter(Mandatory)][string]$Code, [string]$StateRoot = '')
    Update-TpmGameEvidence -Code $Code -StateRoot $StateRoot -Change { param($record) $record.Verification = $null }
}

# Step is FirstRun (the first-run Test or Service menu step) or Calibration. State is Done, NotNeeded or Needed.
function Set-TpmGameSetupStep {
    param([Parameter(Mandatory)][string]$Code, [Parameter(Mandatory)][ValidateSet('FirstRun', 'Calibration')][string]$Step, [Parameter(Mandatory)][ValidateSet('Done', 'NotNeeded', 'Needed')][string]$State, [Parameter(Mandatory)]$Doc, [string]$StateRoot = '')
    $identity = Get-TpmControlProfileIdentity -Doc $Doc
    Update-TpmGameEvidence -Code $Code -StateRoot $StateRoot -Change {
        param($record)
        $record.$Step = $State
        $record."${Step}At" = (Get-Date).ToUniversalTime().ToString('o')
        if ($Step -eq 'Calibration') { $record.CalibrationHash = $identity.Hash }
    }
}

# Reads the evidence for one game and compares it with the profile as it is now. Read-only.
#   Status: None (no record), Current (the profile is what the player tested), Stale (it changed since), Unreadable (the file is damaged).
#   Calibration: NotRequired, Needed, Done or NotNeeded. Wheel, gun, trackball and other analog games need it until the player says Done
#     for the current controls; a calibration done before the controls changed counts as Needed again.
#   FirstRun: Unknown, Needed, Done or NotNeeded. Unknown does not block anything, because no source says which games need it.
#   Outstanding: the steps that are Needed. A game with any is not Verified, even when the controls were tested.
function Get-TpmControlVerificationState {
    param([Parameter(Mandatory)][string]$Code, $Doc = $null, [string]$StateRoot = '')
    $result = [pscustomobject]@{ Status = 'None'; Evidence = $null; Reason = ''; FirstRun = 'Unknown'; Calibration = 'Unknown'; Outstanding = @() }
    if ($Code -notmatch '^[\w-]+$' -or $null -eq $Doc -or $null -eq $Doc.SelectSingleNode('/GameProfile')) { return $result }
    $identity = Get-TpmControlProfileIdentity -Doc $Doc
    $file = Read-TpmControlStateFile -Path (Get-TpmControlStatePath -StateRoot $StateRoot).Evidence
    $record = $null
    if ($file.Status -eq 'Unreadable') { $result.Status = 'Unreadable' }
    elseif ($file.Status -eq 'Ok' -and $file.Data.PSObject.Properties['Games']) { $record = @($file.Data.Games | Where-Object { $_.Code -ieq $Code } | Select-Object -First 1)[0] }
    $needsCalibration = ($identity.Family -ne 'button')
    $stored = $(if ($record) { [string]$record.Calibration } else { '' })
    $result.Calibration = 'NotRequired'
    if ($stored -eq 'NotNeeded') { $result.Calibration = 'NotNeeded' }
    elseif ($stored -eq 'Done' -and [string]$record.CalibrationHash -eq $identity.Hash) { $result.Calibration = 'Done' }
    elseif ($needsCalibration -or $stored -eq 'Needed') { $result.Calibration = 'Needed' }
    if ($record -and [string]$record.FirstRun -in @('Needed', 'Done', 'NotNeeded')) { $result.FirstRun = [string]$record.FirstRun }
    $result.Outstanding = @(@('Calibration', 'FirstRun') | Where-Object { $result.$_ -eq 'Needed' })
    if ($null -eq $record -or $null -eq $record.Verification) { return $result }
    $evidence = $record.Verification
    if ([string]::IsNullOrWhiteSpace([string]$evidence.Method) -or [string]::IsNullOrWhiteSpace([string]$evidence.ObservedAt)) { return $result }
    if ([string]$evidence.ProfileRevision -ne $identity.Revision -or [string]$evidence.ProfileHash -ne $identity.Hash) {
        $result.Status = 'Stale'
        $result.Reason = $(if ([string]$evidence.ProfileRevision -ne $identity.Revision) { 'The game settings were updated after you tested it.' } else { 'The controls of this game changed after you tested it.' })
        return $result
    }
    $result.Status = 'Current'
    $result.Evidence = $evidence
    return $result
}

# Plain lines for one verification state: what TPM knows, and what is still to do.
function Get-TpmVerificationLines {
    param([Parameter(Mandatory)]$Verification)
    $lines = New-Object System.Collections.Generic.List[string]
    switch ([string]$Verification.Status) {
        'Current' {
            $when = [datetime]::MinValue
            $text = $(if ([datetime]::TryParse([string]$Verification.Evidence.ObservedAt, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::RoundtripKind, [ref]$when)) { ' on ' + (Format-TpmFriendlyTime -WhenUtc $when.ToUniversalTime()) } else { '' })
            [void]$lines.Add('You told TPM' + $text + ' that you played this game and its controls worked.')
        }
        'Stale' { [void]$lines.Add(([string]$Verification.Reason + ' Play it again to be sure, then tell TPM.')) }
        'Unreadable' { [void]$lines.Add('TPM could not read its saved test records, so it cannot say if this game was tested.') }
        default { [void]$lines.Add('TPM has no record that you played this game with these controls.') }
    }
    if ($Verification.Calibration -eq 'Needed') { [void]$lines.Add('Still to do: calibrate the wheel, gun or other analog controls for this game.') }
    if ($Verification.FirstRun -eq 'Needed') { [void]$lines.Add('Still to do: the first-run Test or Service menu step for this game.') }
    elseif ($Verification.FirstRun -eq 'Unknown') { [void]$lines.Add('TPM does not know if this game needs a first-run Test or Service menu step.') }
    return @($lines.ToArray())
}

# --- Cabinet inventory and control guides (#267) ----------------------------
# What to suggest for one control of a game. State: Suggested (the player taught TPM a key for it), NotLearned (TPM knows which
# control it is, but not its key) or NotSure. TPM only names a key for a standard arcade control: coin, start, test, service,
# a numbered button, or a direction the game plainly calls a direction. A direction the game calls something else ("Menu Up",
# "Volume Down") and any control TPM has no rule for are NotSure. TPM never guesses.
function Get-TpmGameKeyChoice {
    param([Parameter(Mandatory)]$Control, [Parameter(Mandatory)]$Cabinet)
    $id = switch ($Control.Kind) {
        'Button' { [string]$Control.Mapping }
        'Direction' { [string]$Control.Mapping }
        'Start' { 'P{0}ButtonStart' -f $Control.Player }
        'Coin' { 'Coin{0}' -f $Control.Player }
        'Service' { 'Service' }
        'Test' { 'Test' }
        default { '' }
    }
    if (-not $id) { return [pscustomobject]@{ State = 'NotSure'; Text = 'I''m not sure' } }
    if ($Control.Kind -eq 'Direction' -and -not (Test-TpmDirectionName -Name ([string]$Control.Label))) {
        return [pscustomobject]@{ State = 'NotSure'; Text = ('I''m not sure (the game calls this "{0}")' -f $Control.Label) }
    }
    $key = Get-TpmCabinetKey -State $Cabinet -Control $id
    if ($key) { return [pscustomobject]@{ State = 'Suggested'; Text = ('Key: ' + $key) } }
    return [pscustomobject]@{ State = 'NotLearned'; Text = 'Not learned yet' }
}

# The colors the player's own LEDBlinky file gives to the controls of one game (LED control name -> color), read from the
# TeknoParrot group of that game first, then the TeknoParrot defaults. Read-only. A missing or unreadable file gives no colors.
function Get-TpmLedControlColors {
    param([string]$Root = '', [Parameter(Mandatory)][string]$Code)
    $colors = @{}
    try {
        if ((Get-TpmLedBlinkyFolderProblem -Path $Root) -ne '') { return $colors }
        $doc = New-Object System.Xml.XmlDocument
        $doc.XmlResolver = $null
        $doc.LoadXml([System.IO.File]::ReadAllText((Join-Path $Root 'LEDBlinkyControls.xml')))
        $groups = @($doc.SelectNodes('/dat/emulator[@emuname="TeknoParrot"]/controlGroup'))
        $own = @($groups | Where-Object { $_.GetAttribute('groupName') -ieq $Code })
        $defaults = @($groups | Where-Object { $_.GetAttribute('groupName') -eq 'DEFAULT' })
        foreach ($group in (@($own) + @($defaults))) {
            foreach ($node in @($group.SelectNodes('player/control[@color]'))) {
                $name = $node.GetAttribute('name')
                if ($name -and $node.GetAttribute('color') -and -not $colors.ContainsKey($name)) { $colors[$name] = $node.GetAttribute('color') }
            }
        }
    } catch { return @{} }
    return $colors
}

# Plain guide for one game: each control the game lists, what it does, which key TPM suggests, and whether the game has it
# set up. The keys come from the cabinet file, so a guide is only as good as what the player taught TPM. -LedColors (from
# Get-TpmLedControlColors) adds a Light column.
function Get-TpmGameControlGuide {
    param([Parameter(Mandatory)]$Doc, [Parameter(Mandatory)][string]$Title, [Parameter(Mandatory)]$Cabinet, $Verification = $null, [hashtable]$LedColors = $null)
    $bound = @{}
    foreach ($button in @(Get-ButtonNodes $Doc)) {
        $mapping = $button.SelectSingleNode('InputMapping')
        if ($mapping -and -not $bound.ContainsKey($mapping.InnerText.Trim())) { $bound[$mapping.InnerText.Trim()] = (Test-ButtonIsBound $button) }
    }
    $profileControls = Get-TpmLedProfileControls -Doc $Doc
    $deviceFor = @{ Trackball = 'PointerOrTrackball'; Spinner = 'Spinner'; Pedal = 'Wheel' }
    $showLight = ($null -ne $LedColors -and $LedColors.Count -gt 0)
    $rows = New-Object System.Collections.Generic.List[object]
    $suggested = 0
    $notSure = New-Object System.Collections.Generic.List[string]
    foreach ($control in @($profileControls.Controls)) {
        if ($deviceFor.ContainsKey([string]$control.Kind)) {
            $answer = Get-TpmCabinetDeviceAnswer -State $Cabinet -Class $deviceFor[[string]$control.Kind]
            $yours = $(if ($answer -eq $true) { 'Your ' + (@(Get-TpmDeviceQuestions | Where-Object { $_.Class -eq $deviceFor[[string]$control.Kind] })[0].Label -replace '^an? ', '') } elseif ($answer -eq $false) { 'You said you do not have one' } else { 'Not answered yet' })
        } else {
            $choice = Get-TpmGameKeyChoice -Control $control -Cabinet $Cabinet
            $yours = $choice.Text
            if ($choice.State -eq 'Suggested') { $suggested++ } elseif ($choice.State -eq 'NotSure') { [void]$notSure.Add([string]$control.Label) }
        }
        $inGame = $(if ($bound.ContainsKey([string]$control.Mapping) -and $bound[[string]$control.Mapping]) { 'Set up' } else { 'Not set up yet' })
        $cells = @([string]$control.Label, $yours, $inGame, [string]$control.Mapping)
        if ($showLight) {
            $color = $(if ($control.Exact) { [string]$LedColors[[string]$control.Exact] } else { '' })
            $cells += $(if (-not $color) { '' } elseif ($color -match '^[A-Za-z ]+$') { $color } else { 'a custom color' })
        }
        [void]$rows.Add([pscustomobject]@{ Cells = $cells })
    }
    $lines = New-Object System.Collections.Generic.List[string]
    $needs = switch ([string]$profileControls.Family) {
        'driving' { 'This game needs a steering wheel and pedals (or a pad that can steer).' }
        'lightgun' { 'This game is aimed with a light gun (or a mouse or stick).' }
        'trackball' { 'This game uses a trackball.' }
        'analog' { 'This game uses analog controls such as a dial or throttle.' }
        default { '' }
    }
    if ($needs) { [void]$lines.Add($needs) }
    if ($rows.Count -eq 0) { [void]$lines.Add('This game does not list any controls TPM can read.') }
    elseif ($suggested -gt 0) { [void]$lines.Add(('TPM can suggest a key for {0} of the {1} controls below.' -f $suggested, $rows.Count)) }
    if ($notSure.Count -gt 0) { [void]$lines.Add('TPM is not sure what to suggest for: ' + (@($notSure | Select-Object -First 6) -join ', ') + $(if ($notSure.Count -gt 6) { (' and {0} more' -f ($notSure.Count - 6)) } else { '' }) + '.') }
    if ($null -ne $Verification) { foreach ($line in @(Get-TpmVerificationLines -Verification $Verification)) { [void]$lines.Add($line) } }
    [void]$lines.Add('"Key" is what you taught TPM. "Set up" means the game has a setting for it. TPM has not pressed any of them for you.')
    if ($showLight) { [void]$lines.Add('"Light" is the color your own LEDBlinky file gives that control. TPM does not change any lights.') }
    $columns = @('What it does', 'Your control', 'In the game', 'TeknoParrot name')
    if ($showLight) { $columns += 'Light' }
    return [pscustomobject]@{ Title = ('Controls for ' + $Title); Lines = @($lines.ToArray()); Columns = $columns; Rows = @($rows.ToArray()) }
}

# The cabinet as a page: one row per control TPM knows a key for.
function Get-TpmCabinetGuide {
    param([Parameter(Mandatory)]$Cabinet)
    $rows = New-Object System.Collections.Generic.List[object]
    $labels = @{}
    foreach ($control in @(Get-TpmCabinetControlList -Players 4 -Buttons 8)) { $labels[[string]$control.Control] = [string]$control.Label }
    foreach ($property in @($Cabinet.Keys.PSObject.Properties)) {
        [void]$rows.Add([pscustomobject]@{ Cells = @($(if ($labels.ContainsKey($property.Name)) { $labels[$property.Name] } else { $property.Name }), [string]$property.Value.Key) })
    }
    return [pscustomobject]@{ Title = 'My cabinet controls'; Lines = @(Get-TpmCabinetSummaryLines -State $Cabinet); Columns = @('Control', 'Key it sends'); Rows = @($rows.ToArray()) }
}

function ConvertTo-TpmGuideHtml {
    param([Parameter(Mandatory)]$Guide)
    $encode = { param($text) [System.Net.WebUtility]::HtmlEncode([string]$text) }
    $html = New-Object System.Text.StringBuilder
    [void]$html.AppendLine('<!DOCTYPE html>')
    [void]$html.AppendLine('<html lang="en"><head><meta charset="utf-8"><title>' + (& $encode $Guide.Title) + '</title>')
    [void]$html.AppendLine('<style>body{font-family:Segoe UI,Arial,sans-serif;margin:2em;color:#000}table{border-collapse:collapse;margin-top:1em}th,td{border:1px solid #444;padding:6px 12px;text-align:left}th{background:#e8e8e8}@media print{body{margin:0.5in}}</style></head><body>')
    [void]$html.AppendLine('<h1>' + (& $encode $Guide.Title) + '</h1>')
    foreach ($line in @($Guide.Lines)) { [void]$html.AppendLine('<p>' + (& $encode $line) + '</p>') }
    if (@($Guide.Rows).Count -gt 0) {
        [void]$html.AppendLine('<table><tr>' + ((@($Guide.Columns) | ForEach-Object { '<th>' + (& $encode $_) + '</th>' }) -join '') + '</tr>')
        foreach ($row in @($Guide.Rows)) { [void]$html.AppendLine('<tr>' + ((@($row.Cells) | ForEach-Object { '<td>' + (& $encode $_) + '</td>' }) -join '') + '</tr>') }
        [void]$html.AppendLine('</table>')
    }
    [void]$html.AppendLine('</body></html>')
    return $html.ToString()
}

function Write-TpmGuideOnScreen {
    param([Parameter(Mandatory)]$Guide)
    Write-Host ''
    Write-TpmText -Text $Guide.Title -Color Cyan
    foreach ($line in @($Guide.Lines)) { Write-TpmText -Text $line -Color DarkCyan }
    foreach ($row in @($Guide.Rows)) {
        $cells = @($row.Cells)
        Write-TpmText -Text ('{0}: {1}' -f $cells[0], (($cells | Select-Object -Skip 1 | Where-Object { $_ }) -join '  |  ')) -HangingIndent 4
    }
}

# Saves a guide as a web page in the Manager's own Reports\Control Guides folder and returns the path. Only a page TPM made
# earlier for the same name is replaced.
function Save-TpmControlGuideFile {
    param([Parameter(Mandatory)]$Guide, [Parameter(Mandatory)][string]$FileName, [string]$GuideRoot = '')
    $root = $(if ($GuideRoot) { $GuideRoot }
              elseif ($script:TpmOwnedLayout -and -not [string]::IsNullOrWhiteSpace([string]$script:TpmOwnedLayout.Reports)) { Join-Path ([string]$script:TpmOwnedLayout.Reports) 'Control Guides' }
              else { Join-Path $PSScriptRoot 'Control Guides' })
    [void][System.IO.Directory]::CreateDirectory($root)
    $path = Join-Path $root $FileName
    Write-TpmAtomicTextFile -Path $path -Text (ConvertTo-TpmGuideHtml -Guide $Guide) -Operation 'control guide write'
    return $path
}

# Shows a guide, then (one Y/N) saves it as a page and opens it so it can be printed.
function Invoke-TpmGuideOffer {
    param([Parameter(Mandatory)]$Guide, [Parameter(Mandatory)][string]$FileName)
    Write-TpmGuideOnScreen -Guide $Guide
    if ((Read-TpmYesNo -Prompt '  Save this as a page you can print, and open it? (Y/N)' -Default 'N') -ne 'Y') { return }
    try {
        $path = Save-TpmControlGuideFile -Guide $Guide -FileName $FileName
        Write-Log ('Controls: saved the guide {0}.' -f $path)
        Write-TpmText -Text ('Saved: ' + $path) -Color Green
        try { Start-Process -FilePath $path -ErrorAction Stop | Out-Null } catch { Write-TpmText -Text 'Windows could not open it. Open that file yourself to print it.' -Color Yellow }
    } catch {
        Write-Log ('Controls: the guide could not be saved: {0}' -f $_.Exception.Message)
        Write-TpmText -Text 'The page could not be saved.' -Color Yellow
    }
}

# Asks for part of a game name and returns the chosen registered game ({ Code; Title; Doc }), or $null to go back.
function Read-TpmControlsGamePick {
    param([Parameter(Mandatory)][string]$UserProfilesDir)
    $typed = [string](Read-HostSafe '  Type part of the game name (or press Enter to go back)')
    $needle = ([regex]::Replace($typed, '\s+', '')).ToLowerInvariant()
    if ($needle.Length -lt 2) { return $null }
    $found = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'Game search' -EnumerationErrorAction SilentlyContinue | Where-Object { $_.BaseName.ToLowerInvariant().Contains($needle) } | Sort-Object BaseName | Select-Object -First 8)
    if ($found.Count -eq 0) { Write-TpmText -Text 'No game matched that. Try fewer letters.' -Color Yellow; return $null }
    $games = @($found | ForEach-Object {
        try { $doc = Read-Xml $_.FullName; [pscustomobject]@{ Code = $_.BaseName; Doc = $doc; Title = (Get-TpmProfileFriendlyTitle -Doc $doc -BaseName $_.BaseName) } } catch { $null }
    } | Where-Object { $_ })
    if ($games.Count -eq 0) { Write-TpmText -Text 'The settings file for that game could not be read.' -Color Yellow; return $null }
    $index = Read-TpmNumberedListChoice -Rows @($games | ForEach-Object { $_.Title }) -Prompt '  Which game? (number, or B to go back)' -Heading 'These games matched:'
    if ($index -lt 0) { return $null }
    return $games[$index]
}

# "I played it": the one place a player tells TPM a game's controls worked, or that a setup step is done.
function Invoke-TpmGameCheckScreen {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [string]$StateRoot = '')
    Write-Host ''
    Write-TpmText -Text 'Tell TPM how a game played' -Color Cyan
    Write-TpmText -Text 'TPM cannot press your buttons. Only you can say a game worked, and TPM keeps that until the game''s controls change.' -Color DarkCyan
    $game = Read-TpmControlsGamePick -UserProfilesDir $UserProfilesDir
    if ($null -eq $game) { return }
    $state = Get-TpmControlVerificationState -Code $game.Code -Doc $game.Doc -StateRoot $StateRoot
    Write-Host ''
    Write-TpmText -Text $game.Title -Color Cyan
    foreach ($line in @(Get-TpmVerificationLines -Verification $state)) { Write-TpmText -Text $line -Color DarkCyan }
    Write-Host ''
    Write-TpmText -Text 'W = It worked: I played it and every control I tried reacted correctly' -Indent 4
    Write-TpmText -Text 'N = Something did not work (TPM forgets that it worked)' -Indent 4
    Write-TpmText -Text 'S = Record a setup step: the first-run Test or Service menu, or calibration' -Indent 4
    Write-TpmText -Text 'B = Back' -Indent 4
    $choice = Read-TpmChoice -Prompt '  Choose W, N, S or B' -Choices @('W', 'N', 'S', 'B') -Default 'B'
    try {
        switch ($choice) {
            'W' {
                Save-TpmGameVerification -Code $game.Code -Title $game.Title -Doc $game.Doc -StateRoot $StateRoot
                Write-Log ('Controls: {0}: the player recorded that the controls worked (profile revision {1}).' -f $game.Code, (Get-TpmControlProfileIdentity -Doc $game.Doc).Revision)
                $after = Get-TpmControlVerificationState -Code $game.Code -Doc $game.Doc -StateRoot $StateRoot
                if (@($after.Outstanding).Count -gt 0) {
                    Write-TpmText -Text 'Saved. TPM still does not call this game verified, because a setup step is left:' -Color Yellow
                    foreach ($line in @(Get-TpmVerificationLines -Verification $after | Where-Object { $_ -like 'Still to do*' })) { Write-TpmText -Text $line -Color Yellow -Indent 4 }
                } else {
                    Write-TpmText -Text 'Saved. TPM counts this game''s controls as verified until you change them.' -Color Green
                }
            }
            'N' {
                if ($state.Status -in @('Current', 'Stale')) {
                    Remove-TpmGameVerification -Code $game.Code -StateRoot $StateRoot
                    Write-Log ('Controls: {0}: the player revoked the verification.' -f $game.Code)
                    Write-TpmText -Text 'TPM forgot that this game worked. Open TeknoParrot to check its controls.' -Color Green
                } else {
                    Write-TpmText -Text 'TPM did not count this game as verified, so nothing changed. Open TeknoParrot to check its controls.' -Color Green
                }
            }
            'S' {
                Write-TpmText -Text '1 = The first-run Test or Service menu step' -Indent 4
                Write-TpmText -Text '2 = Calibration (wheel, gun or other analog controls)' -Indent 4
                $step = $(if ((Read-TpmChoice -Prompt '  Which step? (1 or 2)' -Choices @('1', '2') -Default '1') -eq '1') { 'FirstRun' } else { 'Calibration' })
                Write-TpmText -Text 'D = I did it' -Indent 4
                Write-TpmText -Text 'N = This game does not need it' -Indent 4
                Write-TpmText -Text 'R = It is still to do' -Indent 4
                $answer = Read-TpmChoice -Prompt '  Choose D, N or R' -Choices @('D', 'N', 'R') -Default 'D'
                $new = @{ D = 'Done'; N = 'NotNeeded'; R = 'Needed' }[$answer]
                Set-TpmGameSetupStep -Code $game.Code -Step $step -State $new -Doc $game.Doc -StateRoot $StateRoot
                Write-Log ('Controls: {0}: {1} marked {2}.' -f $game.Code, $step, $new)
                Write-TpmText -Text 'Saved.' -Color Green
            }
        }
    } catch {
        Write-Log ('Controls: the answer could not be saved: {0}' -f $_.Exception.Message)
        Write-TpmText -Text 'Your answer could not be saved, so nothing changed.' -Color Yellow
    }
}

# The My controls screen: what TPM knows about the player's controls, and the four things to do about it.
function Invoke-TpmControlsScreen {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [string]$StateRoot = '')
    $look = { Get-TpmControllerEvidence -Salt (Get-TpmControllerSalt -StateRoot $StateRoot) }
    $evidence = & $look
    while ($true) {
        $cabinet = Read-TpmCabinetState -StateRoot $StateRoot
        Write-Host ''
        Write-TpmText -Text 'My controls' -Color Cyan
        foreach ($line in @(Get-TpmCabinetSummaryLines -State $cabinet)) { Write-TpmText -Text $line -Color DarkCyan }
        $setNotice = Get-TpmControllerSetNotice -Cabinet $cabinet -Evidence $evidence
        if ($setNotice.Text) { Write-TpmText -Text $setNotice.Text -Color $setNotice.Color }
        if ($cabinet.FileStatus -eq 'Unreadable') { Write-TpmText -Text 'TPM could not read its saved answers. A copy is kept before anything new is saved.' -Color Yellow }
        Write-Host ''
        Write-TpmText -Text '1 = Tell TPM which controls I have' -Indent 4
        Write-TpmText -Text '2 = Learn my arcade buttons (I press each one)' -Indent 4
        Write-TpmText -Text '3 = Show or print the controls of one game' -Indent 4
        Write-TpmText -Text '4 = Tell TPM how a game played' -Indent 4
        Write-TpmText -Text '5 = Show or print my cabinet controls' -Indent 4
        Write-TpmText -Text 'B = Back' -Indent 4
        switch (Read-TpmChoice -Prompt '  Choose 1, 2, 3, 4, 5 or B' -Choices @('1', '2', '3', '4', '5', 'B') -Default 'B') {
            '1' { Invoke-DeviceSurvey -StateRoot $StateRoot }
            '2' { Invoke-TpmButtonLearning -StateRoot $StateRoot; $evidence = & $look }
            '3' {
                $game = Read-TpmControlsGamePick -UserProfilesDir $UserProfilesDir
                if ($game) {
                    $verification = Get-TpmControlVerificationState -Code $game.Code -Doc $game.Doc -StateRoot $StateRoot
                    $colors = Get-TpmLedControlColors -Root ([string](Get-Variable -Name ledBlinkyRoot -Scope Script -ValueOnly -ErrorAction SilentlyContinue)) -Code $game.Code
                    Invoke-TpmGuideOffer -Guide (Get-TpmGameControlGuide -Doc $game.Doc -Title $game.Title -Cabinet $cabinet -Verification $verification -LedColors $colors) -FileName ($game.Code + '-controls.html')
                }
            }
            '4' { Invoke-TpmGameCheckScreen -UserProfilesDir $UserProfilesDir -StateRoot $StateRoot }
            '5' { Invoke-TpmGuideOffer -Guide (Get-TpmCabinetGuide -Cabinet $cabinet) -FileName 'my-cabinet-controls.html' }
            default { return }
        }
    }
}

# =============================================================================
# RESTORE FROM BACKUP
# =============================================================================
# Lists all timestamped backups in UserProfiles\FullBackup, lets the user pick
# one, confirms, then copies it back to UserProfiles -- overwriting current files.
# The FullBackup subfolder itself is never touched during the restore.
function New-TpmRestoreBackupLegacyResult {
    param(
        [Parameter(Mandatory)][ValidateSet('NO_OP','FAILED_BEFORE_MUTATION','SUCCEEDED','ROLLED_BACK_VERIFIED','ACTION_REQUIRED')][string]$Outcome,
        [Parameter(Mandatory)][string]$ReasonCode,
        [Parameter(Mandatory)][string]$Summary,
        [Parameter(Mandatory)][string]$FinalCheck,
        [string]$Name = $null,
        [int]$ErrorCount = 0,
        [string]$RollbackPath = $null,
        [object]$Backup = $null,
        [switch]$Cancelled
    )
    $productState = switch ($Outcome) {
        'SUCCEEDED' { 'INTENDED' }
        'ACTION_REQUIRED' { 'UNKNOWN' }
        default { 'UNCHANGED' }
    }
    return [pscustomobject]@{
        PSTypeName = 'TPM.RestoreBackupLegacyResult.v1'
        Outcome = $Outcome
        ProductState = $productState
        MutationStarted = ($Outcome -in @('SUCCEEDED','ROLLED_BACK_VERIFIED','ACTION_REQUIRED'))
        Succeeded = ($Outcome -eq 'SUCCEEDED')
        Name = $Name
        ErrorCount = $ErrorCount
        ReasonCode = $ReasonCode
        Summary = $Summary
        FinalCheck = $FinalCheck
        RollbackPath = $RollbackPath
        Backup = $Backup
        Cancelled = [bool]$Cancelled
    }
}

# Plain words for the kind of a saved copy of the game settings: the first part of the folder name of a backup and
# the kind of a restore point. An unknown kind is still called a saved copy.
function Get-TpmSavedCopyKindText {
    param([AllowEmptyString()][string]$Kind)
    $words = @{
        Baseline = 'First saved copy'
        Startup = 'Saved at start-up'
        BeforeReset = 'Saved before a reset or restore'
        PropagateControls = 'Before Propagate Controls'
        GpuFix = 'Before the GPU fix'
        FFBBlaster = 'Before Force feedback setup'
        CursorHide = 'Before hiding the cursor'
        RegisterGames = 'Before registering games'
        LibraryHealthAuto = 'Before fixing game paths'
        ReShadeNativeCrt = 'Before turning off the CRT look'
        AutoSync = 'Before syncing games'
        FFBOverlapSwitch = 'Before the force feedback switch'
    }
    if (-not [string]::IsNullOrWhiteSpace($Kind) -and $words.ContainsKey($Kind)) { return [string]$words[$Kind] }
    return 'Saved copy'
}

# A moment in everyday words: "today 10:00", "yesterday 22:15", "3 Nov 10:00" (with the year when it is not this year).
function Format-TpmFriendlyTime {
    param([Parameter(Mandatory)][datetime]$WhenUtc, [datetime]$Now = (Get-Date))
    $culture = [System.Globalization.CultureInfo]::InvariantCulture
    $local = $WhenUtc.ToLocalTime()
    $clock = $local.ToString('HH:mm', $culture)
    $daysAgo = ($Now.Date - $local.Date).Days
    if ($daysAgo -eq 0) { return ('today {0}' -f $clock) }
    if ($daysAgo -eq 1) { return ('yesterday {0}' -f $clock) }
    if ($local.Year -eq $Now.Year) { return ('{0} {1}' -f $local.ToString('d MMM', $culture), $clock) }
    return ('{0} {1}' -f $local.ToString('d MMM yyyy', $culture), $clock)
}

# What a backup folder of the game settings is, from its name: <Kind>_<yyyy-MM-dd>_<HH-mm-ss>[_<fff>][_<8 hex>] (UTC).
# Text is the one plain row label ("Before Propagate Controls, today 10:00"). WhenUtc is $null when the name has no
# readable time, so such a folder sorts last.
function Get-TpmUserProfilesBackupInfo {
    param([Parameter(Mandatory)][string]$Name, [datetime]$Now = (Get-Date))
    $match = [regex]::Match($Name, '^(?<kind>.+?)_(?<date>\d{4}-\d{2}-\d{2})_(?<time>\d{2}-\d{2}-\d{2})(?:_(?<ms>\d{3}))?(?:_[0-9A-Fa-f]{8}|_[0-9A-Fa-f]{32})?$')
    $kind = if ($match.Success) { $match.Groups['kind'].Value } else { $Name }
    $whenUtc = $null
    if ($match.Success) {
        $parsed = [datetime]::MinValue
        $styles = [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal
        if ([datetime]::TryParseExact(($match.Groups['date'].Value + '_' + $match.Groups['time'].Value), 'yyyy-MM-dd_HH-mm-ss', [System.Globalization.CultureInfo]::InvariantCulture, $styles, [ref]$parsed)) {
            $whenUtc = $parsed
            if ($match.Groups['ms'].Success) { $whenUtc = $whenUtc.AddMilliseconds([double]$match.Groups['ms'].Value) }
        }
    }
    $text = Get-TpmSavedCopyKindText -Kind $kind
    if ($null -ne $whenUtc) { $text = ('{0}, {1}' -f $text, (Format-TpmFriendlyTime -WhenUtc $whenUtc -Now $Now)) }
    return [pscustomobject]@{ Name = $Name; WhenUtc = $whenUtc; Text = $text }
}

# The details of one backup for the Details key: its folder name, size, and whether it can be checked.
function Get-TpmUserProfilesBackupDetailBlock {
    param([Parameter(Mandatory)]$Info, [Parameter(Mandatory)][int]$FileCount, [Parameter(Mandatory)][bool]$HasCompletionRecord, [int]$GameCount = -1)
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add(('Folder: {0}' -f $Info.Name))
    [void]$lines.Add(('Files: {0}' -f $FileCount))
    if ($GameCount -ge 0) { [void]$lines.Add(('Games: {0}' -f $GameCount)) }
    if ($HasCompletionRecord) {
        [void]$lines.Add('Check: This copy was finished and can be checked.')
    } else {
        [void]$lines.Add('Check: It has no completion record. It was made by an older version of TeknoParrot Manager or by another tool, so TeknoParrot Manager cannot prove it is complete.')
    }
    return @{ Heading = [string]$Info.Text; Lines = $lines.ToArray() }
}

function Invoke-RestoreBackup {
    param([string]$userProfilesDir, [string]$SelectedBackupPath = '', [switch]$AlreadyConfirmed)
    $legacy = Invoke-RestoreBackupLegacy -userProfilesDir $userProfilesDir -SelectedBackupPath $SelectedBackupPath -AlreadyConfirmed:$AlreadyConfirmed
    $items = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $userProfilesDir -ProgressLabel 'UserProfiles restore result discovery' -EnumerationErrorAction SilentlyContinue | ForEach-Object BaseName)
    if ($null -eq $legacy) {
        $legacy = New-TpmRestoreBackupLegacyResult -Outcome 'NO_OP' -ReasonCode 'RESTORE_NOT_PERFORMED' -Summary 'Restore was not performed; no profile changes were made.' -FinalCheck 'The legacy restore returned before the profile mutation boundary.'
    }

    $outcome = [string]$legacy.Outcome
    $changed = @()
    if ([bool]$legacy.MutationStarted) { $changed = @($items) }

    $rollback = $null
    if ($outcome -eq 'ROLLED_BACK_VERIFIED') {
        $rollback = [pscustomobject]@{
            Attempted = $true
            Completed = $true
            Verified = $true
            Items = @($changed)
            EvidenceRoot = $legacy.RollbackPath
            FailedItems = @()
            Errors = @()
        }
    }
    $finalPassed = $outcome -ne 'ACTION_REQUIRED'
    $finalChecks = @([string]$legacy.FinalCheck)
    $unattempted = @()
    if ($outcome -eq 'FAILED_BEFORE_MUTATION') { $unattempted = @($items) }
    $skipped = @()
    if ($outcome -eq 'NO_OP') { $skipped = @($items) }
    $unknown = @()
    if ($outcome -eq 'ACTION_REQUIRED') { $unknown = @($items) }
    $completed = @()
    if ($outcome -in @('SUCCEEDED','ROLLED_BACK_VERIFIED')) { $completed = @($changed) }

    $tx = New-TpmProfileTransactionResult `
        -WorkflowKey 'UserProfiles' -OperationKey 'RestoreBackup' `
        -Outcome $outcome -ProductState ([string]$legacy.ProductState) `
        -Summary ([string]$legacy.Summary) -ReasonCode ([string]$legacy.ReasonCode) `
        -Items $items -ChangedItems $changed -CompletedItems $completed `
        -UnattemptedItems $unattempted -SkippedItems $skipped -UnknownItems $unknown `
        -MutationStarted ([bool]$legacy.MutationStarted) `
        -MutationCompleted ($outcome -eq 'SUCCEEDED') `
        -Backup $legacy.Backup -FinalAttempted:$true -FinalPassed:$finalPassed `
        -FinalChecks $finalChecks -Rollback $rollback `
        -Errors $(if ($legacy.ErrorCount -gt 0) { @([string]$legacy.ReasonCode) } else { @() }) `
        -TechnicalDetails $legacy
    if ([bool]$legacy.Cancelled) { $tx | Add-Member -NotePropertyName Cancelled -NotePropertyValue $true -Force }
    return $tx
}

function Restore-TpmLegacyUserProfilesSnapshot {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][string]$RollbackDir
    )
    # Enumerate the rollback source BEFORE removing live entries: if it cannot be read, nothing has been deleted.
    # A locked entry must not stop the copy-back; callers compare the result with the snapshot (Test-TpmUserProfilesMatchInventory) and decide.
    $rollbackItems = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $RollbackDir -ProgressLabel 'UserProfiles rollback restore discovery' -Filter '*' -EnumerationErrorAction Stop -IncludeDirectories -Force)
    $removeItems = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $UserProfilesDir -ProgressLabel 'UserProfiles rollback removal discovery' -Filter '*' -EnumerationErrorAction Stop -IncludeDirectories -Force | Where-Object { $_.Name -ne 'FullBackup' })
    $removeStarted = Get-Date
    $removeCurrent = 0
    $removeCurrentDone = $false
    try {
        foreach ($removeItem in $removeItems) {
            $removeCurrent++
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'UserProfiles rollback removal' -Current $removeCurrent -Total $removeItems.Count -StartedAt $removeStarted
            $removeItem | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
        }
        $removeCurrentDone = $true
    } finally {
        if ($removeItems.Count -gt 0) {
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'UserProfiles rollback removal' -Current $(if ($removeCurrentDone) { $removeCurrent } else { $removeCurrent - 1 }) -Total $removeItems.Count -StartedAt $removeStarted -Complete -Outcome $(if ($removeCurrentDone) { 'Final' } else { 'Error' })
        }
    }

    $rollbackStarted = Get-Date
    $rollbackCurrent = 0
    $rollbackCurrentDone = $false
    try {
        foreach ($rollbackItem in $rollbackItems) {
            $rollbackCurrent++
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'UserProfiles rollback restore' -Current $rollbackCurrent -Total $rollbackItems.Count -StartedAt $rollbackStarted
            try { $rollbackItem | Copy-Item -Destination $UserProfilesDir -Recurse -Force -ErrorAction Stop } catch { Write-Log "Restore rollback: could not copy back $($rollbackItem.Name) -- $($_.Exception.Message)" }
        }
        $rollbackCurrentDone = $true
    } finally {
        if ($rollbackItems.Count -gt 0) {
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'UserProfiles rollback restore' -Current $(if ($rollbackCurrentDone) { $rollbackCurrent } else { $rollbackCurrent - 1 }) -Total $rollbackItems.Count -StartedAt $rollbackStarted -Complete -Outcome $(if ($rollbackCurrentDone) { 'Final' } else { 'Error' })
        }
    }
}


function Invoke-RestoreBackupLegacy {
    # -SelectedBackupPath/-AlreadyConfirmed: used by Reset and Restore (FIX58), which lists, previews and confirms itself.
    param([string]$userProfilesDir, [string]$SelectedBackupPath = '', [switch]$AlreadyConfirmed)

    $backupRoot = Join-Path $userProfilesDir "FullBackup"
    if (-not (Test-Path -LiteralPath $backupRoot)) {
        Write-TpmRestoreStatusLine -Text "  No backups found in: $backupRoot" -Color Yellow -Wrap:$AlreadyConfirmed
        return (New-TpmRestoreBackupLegacyResult -Outcome 'NO_OP' -ReasonCode 'NO_BACKUPS_FOUND' -Summary 'No restore backups were found. Nothing was changed.' -FinalCheck 'Backup enumeration found no restore candidate before the profile mutation boundary.')
    }

    $backupFolderCandidates = New-Object System.Collections.Generic.List[object]
    # INCOMPLETE_ folders are interrupted or failed TPM backups: kept as evidence, never offered.
    $stagingPrefix = Get-TpmUserProfilesBackupStagingPrefix
    $markerName = Get-TpmUserProfilesBackupMarkerName
    $incompleteCount = 0
    $folderDiscoveryStarted = Get-Date
    $folderDiscoveryCurrent = 0
    Write-TpmCompactExtractionProgress -Phase Checking -Label 'UserProfiles backup folder discovery' -Current $folderDiscoveryCurrent -Total 0 -StartedAt $folderDiscoveryStarted
    $folderDiscoveryCurrentCompleted = $false
    try {
        Get-ChildItem -LiteralPath $backupRoot -Directory -ErrorAction SilentlyContinue -ErrorVariable backupEnumerationErrors | ForEach-Object {
            # ReShadeRemoval_* folders hold removed ReShade files, not game profiles: they are never a restore choice.
            if ($_.Name.StartsWith($stagingPrefix, [System.StringComparison]::OrdinalIgnoreCase)) { $incompleteCount++ } elseif (-not $_.Name.StartsWith('ReShadeRemoval_', [System.StringComparison]::OrdinalIgnoreCase)) { [void]$backupFolderCandidates.Add($_) }
            $folderDiscoveryCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'UserProfiles backup folder discovery' -Current $folderDiscoveryCurrent -Total 0 -StartedAt $folderDiscoveryStarted
        }
        $folderDiscoveryCurrentCompleted = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'UserProfiles backup folder discovery' -Current $folderDiscoveryCurrent -Total 0 -StartedAt $folderDiscoveryStarted -Complete -Outcome $(if ($folderDiscoveryCurrentCompleted) { 'Final' } else { 'Error' })
    }
    $backups = @($backupFolderCandidates | Sort-Object -Property @{ Expression = { $sortInfo = Get-TpmUserProfilesBackupInfo -Name $_.Name; if ($null -eq $sortInfo.WhenUtc) { [datetime]::MinValue } else { $sortInfo.WhenUtc } }; Descending = $true }, @{ Expression = { $_.Name }; Descending = $true })
    if ($incompleteCount -gt 0) {
        Write-Log ("Restore: {0} incomplete backup folder(s) named {1}* were skipped: they are kept as evidence and cannot be restored." -f $incompleteCount, $stagingPrefix)
        $skippedText = if ($incompleteCount -eq 1) { '1 unfinished saved copy was skipped. It is kept as evidence and cannot be restored.' } else { ('{0} unfinished saved copies were skipped. They are kept as evidence and cannot be restored.' -f $incompleteCount) }
        Write-TpmResetRestoreText -Text $skippedText -Color DarkGray
    }
    if ($backups.Count -eq 0 -and @($backupEnumerationErrors).Count -gt 0) {
        Write-TpmRestoreStatusLine -Text "  The backup folder could not be read, so no backups can be listed." -Color Yellow -Wrap:$AlreadyConfirmed
        return (New-TpmRestoreBackupLegacyResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'BACKUP_UNREADABLE' -Summary 'Restore stopped because the backup folder could not be read. Nothing was changed.' -FinalCheck 'Backup enumeration failed before any restore candidate was listed.')
    }
    if ($backups.Count -eq 0) {
        Write-TpmRestoreStatusLine -Text "  No backup folders found." -Color Yellow -Wrap:$AlreadyConfirmed
        return (New-TpmRestoreBackupLegacyResult -Outcome 'NO_OP' -ReasonCode 'NO_BACKUPS_FOUND' -Summary 'No restore backups were found. Nothing was changed.' -FinalCheck 'Backup enumeration found no restore candidate before the profile mutation boundary.')
    }

    if (-not [string]::IsNullOrWhiteSpace($SelectedBackupPath)) {
        # Reset and Restore (FIX58) already chose and checked the backup; it must still be one of the listed, finished backups.
        $selectedFull = [System.IO.Path]::GetFullPath($SelectedBackupPath).TrimEnd('\','/')
        $selected = @($backups | Where-Object { $_.FullName.TrimEnd('\','/') -ieq $selectedFull }) | Select-Object -First 1
        if ($null -eq $selected -or -not (Test-TpmNoReparsePath -Path $selected.FullName)) {
            Write-TpmRestoreStatusLine -Text '  ERROR: The chosen backup is not available -- restore aborted. Nothing was changed.' -Color Red -Wrap:$AlreadyConfirmed
            Write-Log 'Restore: aborted -- the preselected backup is not one of the finished backups in FullBackup.'
            return (New-TpmRestoreBackupLegacyResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'BACKUP_UNAVAILABLE' -Summary 'Restore stopped because the chosen backup is not available. No profiles were changed.' -FinalCheck 'The preselected backup was checked before the profile mutation boundary.')
        }
    } else {
        $menuRows = New-Object System.Collections.Generic.List[string]
        $menuBlocks = New-Object System.Collections.Generic.List[object]
        $menuStarted = Get-Date
        $menuCurrent = 0
        $menuCurrentDone = $false
        try {
            for ($i = 0; $i -lt $backups.Count; $i++) {
                $menuCurrent = $i + 1
                Write-TpmCompactExtractionProgress -Phase Checking -Label 'UserProfiles backup menu indexing' -Current $menuCurrent -Total $backups.Count -StartedAt $menuStarted
                $b = $backups[$i]
                $fileCount = 0
                $backupHasCompletionRecord = Test-Path -LiteralPath (Join-Path $b.FullName $markerName) -PathType Leaf
                $fileDiscoveryStarted = Get-Date
                $fileDiscoveryCurrent = 0
                Write-TpmCompactExtractionProgress -Phase Checking -Label 'UserProfiles backup file-count discovery' -Current $fileDiscoveryCurrent -Total 0 -StartedAt $fileDiscoveryStarted
                $fileDiscoveryCurrentCompleted = $false
                try {
                    Get-ChildItem -LiteralPath $b.FullName -File -ErrorAction SilentlyContinue | ForEach-Object {
                        if ($_.Name -ine $markerName) { $fileCount++ }
                        $fileDiscoveryCurrent++
                        Write-TpmCompactExtractionProgress -Phase Checking -Label 'UserProfiles backup file-count discovery' -Current $fileDiscoveryCurrent -Total 0 -StartedAt $fileDiscoveryStarted
                    }
                    $fileDiscoveryCurrentCompleted = $true
                } finally {
                    Write-TpmCompactExtractionProgress -Phase Checking -Label 'UserProfiles backup file-count discovery' -Current $fileDiscoveryCurrent -Total 0 -StartedAt $fileDiscoveryStarted -Complete -Outcome $(if ($fileDiscoveryCurrentCompleted) { 'Final' } else { 'Error' })
                }
                $backupInfo = Get-TpmUserProfilesBackupInfo -Name $b.Name
                [void]$menuRows.Add(('{0} - {1}{2}' -f $backupInfo.Text, (Format-TpmCountNoun -Count $fileCount -Singular 'file'), $(if ($backupHasCompletionRecord) { '' } else { ' - older copy, cannot be fully checked' })))
                [void]$menuBlocks.Add((Get-TpmUserProfilesBackupDetailBlock -Info $backupInfo -FileCount $fileCount -HasCompletionRecord $backupHasCompletionRecord))
            }
            $menuCurrentDone = $true
        } finally {
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'UserProfiles backup menu indexing' -Current $(if ($menuCurrentDone) { $menuCurrent } else { $menuCurrent - 1 }) -Total $backups.Count -StartedAt $menuStarted -Complete -Outcome $(if ($menuCurrentDone) { 'Final' } else { 'Error' })
        }
        if ($incompleteCount -gt 0) {
            [void]$menuBlocks.Add(@{ Heading = 'Unfinished saved copies'; Lines = @(('Skipped: {0}' -f $incompleteCount), ('Folder names start with: {0}' -f $stagingPrefix), 'What it means: They are kept as evidence and cannot be restored.') })
        }
        Write-TpmDetailBlocksLog -Blocks $menuBlocks.ToArray() -Prefix 'Restore backup list'
        $picked = Read-TpmNumberedListChoice -Rows $menuRows.ToArray() -Prompt '  Enter number to restore, or Enter to cancel' -Heading 'Saved copies of your game settings, newest first:' -DetailBlocks $menuBlocks.ToArray()
        if ($picked -lt 0) {
            Write-Host "  Restore canceled." -ForegroundColor DarkGray
            Write-Log "Restore: canceled by user."
            return (New-TpmRestoreBackupLegacyResult -Outcome 'NO_OP' -ReasonCode 'USER_CANCELLED' -Summary 'Restore was canceled at backup selection. No profiles were changed.' -FinalCheck 'The selection prompt was canceled before the profile mutation boundary.' -Cancelled)
        }
        $selected = $backups[$picked]
    }
    $selectedHasCompletionRecord = Test-Path -LiteralPath (Join-Path $selected.FullName $markerName) -PathType Leaf

    $backupXmlCandidates = New-Object System.Collections.Generic.List[object]
    $restoreSourceStarted = Get-Date
    $restoreSourceCurrent = 0
    Write-TpmCompactExtractionProgress -Phase Checking -Label 'UserProfiles restore source discovery' -Current $restoreSourceCurrent -Total 0 -StartedAt $restoreSourceStarted
    $restoreSourceCurrentCompleted = $false
    try {
        Get-ChildItem -LiteralPath $selected.FullName -Filter "*.xml" -File -ErrorAction SilentlyContinue | ForEach-Object {
            [void]$backupXmlCandidates.Add($_)
            $restoreSourceCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'UserProfiles restore source discovery' -Current $restoreSourceCurrent -Total 0 -StartedAt $restoreSourceStarted
        }
        $restoreSourceCurrentCompleted = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'UserProfiles restore source discovery' -Current $restoreSourceCurrent -Total 0 -StartedAt $restoreSourceStarted -Complete -Outcome $(if ($restoreSourceCurrentCompleted) { 'Final' } else { 'Error' })
    }
    $backupXmls = $backupXmlCandidates.ToArray()
    if ($backupXmls.Count -eq 0) {
        Write-TpmRestoreStatusLine -Text ("  ERROR: Selected backup '{0}' contains no XML profiles -- restore aborted." -f $selected.Name) -Color Red -Wrap:$AlreadyConfirmed
        Write-Log "Restore: aborted -- backup '$($selected.Name)' contains no XML files."
        return (New-TpmRestoreBackupLegacyResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'BACKUP_EMPTY' -Summary 'Restore stopped because the selected backup contained no profiles. No profiles were changed.' -FinalCheck 'The selected backup was checked before the profile mutation boundary.' -Name $selected.Name)
    }

    # The complete content inventory of the selected backup, taken before anything is changed. A backup with a
    # completion record must still match it exactly; the restored profiles are later verified against this inventory.
    try {
        $sourceInventory = @(Get-TpmUserProfilesBackupInventory -BackupPath $selected.FullName -ProgressLabel 'UserProfiles restore source inventory')
    } catch {
        Write-TpmRestoreStatusLine -Text ("  ERROR: Selected backup '{0}' could not be read completely -- restore aborted. Nothing was changed." -f $selected.Name) -Color Red -Wrap:$AlreadyConfirmed
        Write-Log "Restore: aborted -- backup '$($selected.Name)' could not be inventoried -- $_"
        return (New-TpmRestoreBackupLegacyResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'BACKUP_UNREADABLE' -Summary 'Restore stopped because the selected backup could not be read completely. No profiles were changed.' -FinalCheck 'The selected backup inventory failed before the profile mutation boundary.' -Name $selected.Name)
    }
    if ($selectedHasCompletionRecord) {
        $completion = Test-TpmUserProfilesBackupCompletion -BackupPath $selected.FullName -Inventory $sourceInventory
        if (-not $completion.Valid) {
            $completionFlag = $completion.PSObject.Properties['CouldNotCheck']
            $completionCouldNotCheck = ($null -ne $completionFlag -and [bool]$completionFlag.Value)
            if ($completionCouldNotCheck) {
                Write-TpmRestoreStatusLine -Text ("  ERROR: Selected backup '{0}' could not be checked right now -- restore aborted. Nothing was changed." -f $selected.Name) -Color Red -Wrap:$AlreadyConfirmed
                Write-TpmRestoreStatusLine -Text '  Close any program that may be using it, then try again.' -Color Yellow -Wrap:$AlreadyConfirmed
            } else {
                Write-TpmRestoreStatusLine -Text ("  ERROR: Selected backup '{0}' failed its completeness check -- restore aborted. Nothing was changed." -f $selected.Name) -Color Red -Wrap:$AlreadyConfirmed
            }
            Write-TpmRestoreStatusLine -Text ("  {0}" -f $completion.Reason) -Color Yellow -Wrap:$AlreadyConfirmed
            Write-Log "Restore: aborted -- backup '$($selected.Name)' failed its completion check -- $($completion.Reason)"
            $completionSummary = if ($completionCouldNotCheck) { 'Restore stopped because the selected backup could not be checked right now. No profiles were changed.' } else { 'Restore stopped because the selected backup does not match its completion record. No profiles were changed.' }
            return (New-TpmRestoreBackupLegacyResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'BACKUP_VERIFICATION_FAILED' -Summary $completionSummary -FinalCheck 'The selected backup failed its completeness check before the profile mutation boundary.' -Name $selected.Name)
        }
    }

    $selectedInfo = Get-TpmUserProfilesBackupInfo -Name $selected.Name
    $sourceFileCount = @($sourceInventory | Where-Object { -not $_.IsDirectory }).Count
    $selectedBlock = Get-TpmUserProfilesBackupDetailBlock -Info $selectedInfo -FileCount $sourceFileCount -HasCompletionRecord $selectedHasCompletionRecord -GameCount $backupXmls.Count
    Write-Log ("Restore: selected backup {0} ({1} profile(s), {2} file(s) in total)." -f $selected.Name, $backupXmls.Count, $sourceFileCount)
    if (-not $AlreadyConfirmed) {
        Write-Host ''
        Write-TpmResetRestoreText -Text ('You chose: {0}.' -f $selectedInfo.Text) -Color Yellow
        Write-TpmResetRestoreText -Text ('It has {0}.' -f (Format-TpmGameCount -Count $backupXmls.Count))
    }
    if (-not $selectedHasCompletionRecord) {
        Write-Host ''
        Write-TpmResetRestoreText -Text 'This copy cannot be checked. TeknoParrot Manager cannot be sure it is complete.' -Color Yellow
        Write-TpmResetRestoreText -Text 'Games that are missing from it will be removed.' -Color Yellow
        if (-not $AlreadyConfirmed) { Write-TpmResetRestoreText -Text 'Warning: this replaces ALL your current game settings with this saved copy.' -Color Yellow }
        Write-Host ''
        $unverifiedConfirm = Read-TpmResetRestoreAnswer -Prompt 'Type UNVERIFIED to use this copy anyway' -DetailBlocks @($selectedBlock)
        if ($unverifiedConfirm.ToUpperInvariant() -ne 'UNVERIFIED') {
            Write-Host "  Restore canceled." -ForegroundColor DarkGray
            Write-Log "Restore: user did not accept the unverified backup '$($selected.Name)'."
            return (New-TpmRestoreBackupLegacyResult -Outcome 'NO_OP' -ReasonCode 'USER_DECLINED' -Summary 'Restore was declined. No profiles were changed.' -FinalCheck 'The unverified-backup confirmation was declined before the profile mutation boundary.' -Name $selected.Name -Cancelled)
        }
    }
    # A copy that cannot be checked is approved once, by its own typed word above, which also carries the replace-everything warning.
    if (-not $AlreadyConfirmed -and $selectedHasCompletionRecord) {
        Write-Host ''
        Write-TpmResetRestoreText -Text 'Warning: this replaces ALL your current game settings with this saved copy.' -Color Yellow
        Write-Host ''
        $confirm = Read-TpmResetRestoreAnswer -Prompt 'Type YES to confirm' -DetailBlocks @($selectedBlock)
        if ($confirm.ToUpperInvariant() -ne "YES") {
            Write-Host "  Restore canceled." -ForegroundColor DarkGray
            Write-Log "Restore: user did not confirm."
            return (New-TpmRestoreBackupLegacyResult -Outcome 'NO_OP' -ReasonCode 'USER_DECLINED' -Summary 'Restore was declined. No profiles were changed.' -FinalCheck 'Confirmation was declined before the profile mutation boundary.' -Name $selected.Name -Cancelled)
        }
    }

    # TeknoParrot must be fully closed before files can be safely replaced.
    # If it is running, profile files it has open cannot be deleted, which
    # would leave the UserProfiles directory in a mixed old/new state.
    if (-not (Wait-TpmForProcessClose -ProcessNames @('TeknoParrotUi') -FriendlyName 'TeknoParrot')) {
        Write-TpmRestoreStatusLine -Text '  Restore stopped safely because TeknoParrot is still running. Your selected backup is unchanged.' -Color Yellow -Wrap:$AlreadyConfirmed
        Write-Log 'Restore: stopped because TeknoParrot could not be confirmed closed before mutation.'
        return (New-TpmRestoreBackupLegacyResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'APPLICATION_RUNNING' -Summary 'Restore stopped because TeknoParrot was still running. No profiles were changed.' -FinalCheck 'The running-application check stopped restore before the profile mutation boundary.' -Name $selected.Name)
    }

    # FIX110A S-25: the snapshot copy and the removal below follow and delete top-level entries, so a link (junction or symlink) inside
    # UserProfiles is refused first. This is the same refusal Reset and Restore uses, and it runs for every caller of this worker.
    $footprintLinks = @()
    try { $footprintLinks = @((Get-TpmUserProfilesFootprint -UserProfilesDir $userProfilesDir).ReparsePoints) }
    catch {
        Write-TpmRestoreStatusLine -Text '  ERROR: The game settings folder could not be checked for links -- restore aborted. Nothing was changed.' -Color Red -Wrap:$AlreadyConfirmed
        Write-Log "Restore: aborted -- the link check of UserProfiles failed -- $_"
        return (New-TpmRestoreBackupLegacyResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'CANNOT_READ_SETTINGS' -Summary (Get-TpmUnreadableFileSummary -Message $_.Exception.Message) -FinalCheck 'The link check of UserProfiles failed before the profile mutation boundary.' -Name $selected.Name)
    }
    if ($footprintLinks.Count -gt 0) {
        $linkBlocked = New-TpmLinkBlockedResult -Links $footprintLinks
        Write-TpmRestoreStatusLine -Text '  ERROR: A link (shortcut) was found inside the game settings folder -- restore aborted. Nothing was changed.' -Color Red -Wrap:$AlreadyConfirmed
        Write-Log ('Restore: aborted -- UserProfiles contains {0} link(s): {1}' -f $footprintLinks.Count, ($footprintLinks -join ', '))
        return (New-TpmRestoreBackupLegacyResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'LINK_INSIDE_USERPROFILES' -Summary ([string]$linkBlocked.Summary) -FinalCheck 'The link check of UserProfiles stopped restore before the profile mutation boundary.' -Name $selected.Name)
    }

    # Snapshot the live profiles before deletion so a partial copy failure can
    # roll the live directory back without touching historical FullBackup data.
    $rollbackDir = Join-Path ([System.IO.Path]::GetTempPath()) ('tpm-restore-rollback-' + [guid]::NewGuid().ToString('N'))
    try {
        [void][System.IO.Directory]::CreateDirectory($rollbackDir)
        $snapshotItems = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $userProfilesDir -ProgressLabel 'UserProfiles rollback snapshot discovery' -Filter '*' -EnumerationErrorAction Stop -IncludeDirectories -Force | Where-Object { $_.Name -ne 'FullBackup' })
        $snapshotStarted = Get-Date
        $snapshotCurrent = 0
        $snapshotCurrentDone = $false
        try {
            foreach ($snapshotItem in $snapshotItems) {
                $snapshotCurrent++
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'UserProfiles rollback snapshot' -Current $snapshotCurrent -Total $snapshotItems.Count -StartedAt $snapshotStarted
                $snapshotItem | Copy-Item -Destination $rollbackDir -Recurse -Force -ErrorAction Stop
            }
            $snapshotCurrentDone = $true
        } finally {
            if ($snapshotItems.Count -gt 0) {
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'UserProfiles rollback snapshot' -Current $(if ($snapshotCurrentDone) { $snapshotCurrent } else { $snapshotCurrent - 1 }) -Total $snapshotItems.Count -StartedAt $snapshotStarted -Complete -Outcome $(if ($snapshotCurrentDone) { 'Final' } else { 'Error' })
            }
        }
        # The snapshot is the only route back: it must equal the live profiles before anything is removed.
        $snapshotInventory = @(Get-TpmUserProfilesBackupManifest -UserProfilesDir $rollbackDir -ProgressLabel 'UserProfiles rollback snapshot verification')
        if (-not (Test-TpmUserProfilesMatchInventory -UserProfilesDir $userProfilesDir -Expected $snapshotInventory -ProgressLabel 'UserProfiles pre-restore verification')) { throw 'The pre-restore snapshot does not match the current profiles.' }
    } catch {
        Write-TpmRestoreStatusLine -Text '  ERROR: Could not snapshot current profiles before restore; nothing was changed.' -Color Red -Wrap:$AlreadyConfirmed
        Write-Log "Restore: rollback snapshot failed -- $_"
        if (Test-Path -LiteralPath $rollbackDir) { Remove-Item -LiteralPath $rollbackDir -Recurse -Force -ErrorAction SilentlyContinue }
        $backupEvidence = [pscustomobject]@{ Required=$true; Attempted=$true; Created=$false; Verified=$false; RootPath=$null; Path=$null; Items=@(); FailureStage='RollbackSnapshot'; FailureCode='ROLLBACK_SNAPSHOT_FAILED'; Reason='The pre-restore rollback snapshot could not be created.'; ResiduePaths=@() }
        return (New-TpmRestoreBackupLegacyResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'ROLLBACK_SNAPSHOT_FAILED' -Summary 'Restore stopped because the pre-restore safety snapshot could not be created. No profiles were changed.' -FinalCheck 'Snapshot creation failed before any UserProfiles content was removed.' -Name $selected.Name -ErrorCount 1 -Backup $backupEvidence)
    }

    # Remove current UserProfiles content, keeping FullBackup intact.
    # Use Where-Object instead of -Exclude for reliable PS 5.1 behavior.
    # Treat any deletion failures as fatal: a partial delete followed by a
    # partial copy would leave UserProfiles in an undefined mixed state.
    $deleteErrs = @()
    # Preserve FileInfo/DirectoryInfo pipeline binding for literal filenames.
    $deleteItems = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $userProfilesDir -ProgressLabel 'UserProfiles removal discovery' -Filter '*' -EnumerationErrorAction Continue -IncludeDirectories -Force | Where-Object { $_.Name -ne 'FullBackup' })
    $deleteStarted = Get-Date
    $deleteCurrent = 0
    $deleteCurrentDone = $false
    try {
        foreach ($deleteItem in $deleteItems) {
            $deleteCurrent++
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'UserProfiles removal' -Current $deleteCurrent -Total $deleteItems.Count -StartedAt $deleteStarted
            $deleteItem | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue -ErrorVariable +deleteErrs
        }
        $deleteCurrentDone = $true
    } finally {
        if ($deleteItems.Count -gt 0) {
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'UserProfiles removal' -Current $(if ($deleteCurrentDone) { $deleteCurrent } else { $deleteCurrent - 1 }) -Total $deleteItems.Count -StartedAt $deleteStarted -Complete -Outcome $(if ($deleteCurrentDone -and @($deleteErrs).Count -eq 0) { 'Final' } else { 'Error' })
        }
    }
    if ($deleteErrs.Count -gt 0) {
        Write-TpmRestoreStatusLine -Text ("  ERROR: {0} file(s) could not be removed. The restore was not completed." -f $deleteErrs.Count) -Color Red -Wrap:$AlreadyConfirmed
        Write-TpmRestoreStatusLine -Text "  TeknoParrot Manager will keep the selected backup and attempt to restore the previous live profiles." -Color Yellow -Wrap:$AlreadyConfirmed
        Write-Log "Restore: FAILED -- $($deleteErrs.Count) file(s) could not be removed."
        try {
            Restore-TpmLegacyUserProfilesSnapshot -UserProfilesDir $userProfilesDir -RollbackDir $rollbackDir
            if (-not (Test-TpmUserProfilesMatchInventory -UserProfilesDir $userProfilesDir -Expected $snapshotInventory -ProgressLabel 'UserProfiles rollback verification')) { throw 'The restored previous profiles do not match the pre-restore snapshot.' }
            Remove-Item -LiteralPath $rollbackDir -Recurse -Force -ErrorAction SilentlyContinue
            return (New-TpmRestoreBackupLegacyResult -Outcome 'ROLLED_BACK_VERIFIED' -ReasonCode 'RESTORE_DELETE_FAILED_ROLLED_BACK' -Summary 'Restore stopped and the previous profile state was restored.' -FinalCheck 'The previous profiles were restored and matched the pre-restore snapshot before the result was returned.' -Name $selected.Name -ErrorCount $deleteErrs.Count)
        } catch {
            Write-Log "Restore: rollback after delete failure failed -- $_"
            Write-TpmRestoreStatusLine -Text ("  Your profiles from before the restore were kept at: {0}" -f $rollbackDir) -Color Yellow -Wrap:$AlreadyConfirmed
            return (New-TpmRestoreBackupLegacyResult -Outcome 'ACTION_REQUIRED' -ReasonCode 'RESTORE_DELETE_ROLLBACK_FAILED' -Summary 'Restore stopped and the final profile state needs attention.' -FinalCheck 'The rollback operation failed; the final profile state was not verified.' -Name $selected.Name -ErrorCount $deleteErrs.Count -RollbackPath $rollbackDir)
        }
    }

    # Copy backup into UserProfiles. Copy-Item receives FileInfo/DirectoryInfo
    # objects from the pipeline (not path strings), so pipeline binding
    # already bypasses wildcard expansion -- safe even with [, ], $ in game
    # folder names. If this source is ever changed to raw path strings, add
    # -LiteralPath there.
    $restoreErrs = @()
    # The completion record is backup metadata, never restored as a profile.
    $restoreItems = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $selected.FullName -ProgressLabel 'UserProfiles restore item discovery' -Filter '*' -EnumerationErrorAction Continue -IncludeDirectories -Force | Where-Object { $_.PSIsContainer -or $_.Name -ine $markerName })
    $restoreStarted = Get-Date
    $restoreCurrent = 0
    $restoreCurrentDone = $false
    try {
        foreach ($bf in $restoreItems) {
            $restoreCurrent++
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'UserProfiles restore' -Current $restoreCurrent -Total $restoreItems.Count -StartedAt $restoreStarted
            $bf | Copy-Item -Destination $userProfilesDir -Recurse -Force `
                            -ErrorAction SilentlyContinue -ErrorVariable +restoreErrs
        }
        $restoreCurrentDone = $true
    } finally {
        if ($restoreItems.Count -gt 0) {
            Write-TpmCompactExtractionProgress -Phase Repairing -Label 'UserProfiles restore' -Current $(if ($restoreCurrentDone) { $restoreCurrent } else { $restoreCurrent - 1 }) -Total $restoreItems.Count -StartedAt $restoreStarted -Complete -Outcome $(if ($restoreCurrentDone -and @($restoreErrs).Count -eq 0) { 'Final' } else { 'Error' })
        }
    }
    $errCount = $restoreErrs.Count

    if ($errCount -gt 0) {
        Write-TpmRestoreStatusLine -Text ("  ERROR: {0} file(s) could not be restored. The restore was not completed." -f $errCount) -Color Red -Wrap:$AlreadyConfirmed
        Write-TpmRestoreStatusLine -Text '  TeknoParrot Manager will attempt to restore the previous live profiles from its rollback snapshot.' -Color Yellow -Wrap:$AlreadyConfirmed
        Write-Log "Restore: failed with $errCount error(s) from $($selected.Name)"
        try {
            Restore-TpmLegacyUserProfilesSnapshot -UserProfilesDir $userProfilesDir -RollbackDir $rollbackDir
            if (-not (Test-TpmUserProfilesMatchInventory -UserProfilesDir $userProfilesDir -Expected $snapshotInventory -ProgressLabel 'UserProfiles rollback verification')) { throw 'The restored previous profiles do not match the pre-restore snapshot.' }
            Remove-Item -LiteralPath $rollbackDir -Recurse -Force -ErrorAction SilentlyContinue
            return (New-TpmRestoreBackupLegacyResult -Outcome 'ROLLED_BACK_VERIFIED' -ReasonCode 'RESTORE_COPY_FAILED_ROLLED_BACK' -Summary 'Restore stopped and the previous profile state was restored.' -FinalCheck 'The previous profiles were restored and matched the pre-restore snapshot before the result was returned.' -Name $selected.Name -ErrorCount $errCount)
        } catch {
            Write-Log "Restore: rollback after copy failure failed -- $_"
            Write-TpmRestoreStatusLine -Text ("  Your profiles from before the restore were kept at: {0}" -f $rollbackDir) -Color Yellow -Wrap:$AlreadyConfirmed
            return (New-TpmRestoreBackupLegacyResult -Outcome 'ACTION_REQUIRED' -ReasonCode 'RESTORE_COPY_ROLLBACK_FAILED' -Summary 'Restore stopped and the final profile state needs attention.' -FinalCheck 'The rollback operation failed; the final profile state was not verified.' -Name $selected.Name -ErrorCount $errCount -RollbackPath $rollbackDir)
        }
    }
    # The pre-restore snapshot is retired only when the restored profiles equal the selected backup exactly.
    if (-not (Test-TpmUserProfilesMatchInventory -UserProfilesDir $userProfilesDir -Expected $sourceInventory -ProgressLabel 'UserProfiles restore verification')) {
        Write-TpmRestoreStatusLine -Text '  ERROR: The restored profiles do not match the selected backup. The restore is NOT verified.' -Color Red -Wrap:$AlreadyConfirmed
        Write-TpmRestoreStatusLine -Text '  Your profiles from before the restore were kept at:' -Color Yellow -Wrap:$AlreadyConfirmed
        Write-TpmRestoreStatusLine -Text ("  {0}" -f $rollbackDir) -Color Cyan -Wrap:$AlreadyConfirmed
        Write-TpmRestoreStatusLine -Text '  Keep that folder. Ask for help before changing UserProfiles by hand.' -Color Yellow -Wrap:$AlreadyConfirmed
        Write-Log "Restore: verification FAILED after copying from $($selected.Name); pre-restore snapshot kept at $rollbackDir"
        return (New-TpmRestoreBackupLegacyResult -Outcome 'ACTION_REQUIRED' -ReasonCode 'RESTORE_VERIFICATION_FAILED' -Summary 'Restore copied the backup, but the restored profiles do not match it. The previous profiles were kept for recovery.' -FinalCheck 'The restored UserProfiles inventory differs from the selected backup; the pre-restore snapshot was kept.' -Name $selected.Name -RollbackPath $rollbackDir)
    }
    Remove-Item -LiteralPath $rollbackDir -Recurse -Force -ErrorAction SilentlyContinue
    Write-Log "Restore: completed from $($selected.Name), no errors."
    return (New-TpmRestoreBackupLegacyResult -Outcome 'SUCCEEDED' -ReasonCode 'RESTORED' -Summary 'UserProfiles restore completed successfully.' -FinalCheck 'The restored UserProfiles inventory matched the selected backup before the pre-restore snapshot was removed.' -Name $selected.Name)
}

# Console width helpers. They are defined here, above the start-up code that
# prints restore point messages, because PowerShell does not hoist functions:
# a call made before the definition has run fails with "not recognized".
function Get-ConsoleContentWidth {
    try {
        $width = [int]$Host.UI.RawUI.WindowSize.Width
        if ($width -gt 0) {
            # Windows Terminal can expose the backing buffer width (for
            # example 1904 columns) even when the visible window is the
            # normal default size. Treat that value as a host-reporting
            # anomaly rather than selecting the giant framed layout.
            if ($width -gt 240) { return 110 }
            return $width
        }
    } catch {}
    try {
        $width = [int]$Host.UI.RawUI.BufferSize.Width
        if ($width -gt 0) {
            if ($width -gt 240) { return 110 }
            return $width
        }
    } catch {}
    try {
        $width = [int][Console]::WindowWidth
        if ($width -gt 0) {
            if ($width -gt 240) { return 110 }
            return $width
        }
    } catch {}
    return 80
}

function Split-TextForMenuWidth {
    param(
        [string]$Text,
        [int]$Width
    )

    if ([string]::IsNullOrWhiteSpace($Text)) { return @() }
    if ($Width -lt 20) { $Width = 20 }

    $words = @($Text -split '\s+' | Where-Object { $_ })
    $lines = New-Object System.Collections.Generic.List[string]
    $current = ''
    foreach ($word in $words) {
        if ($current.Length -eq 0) {
            $current = $word
            continue
        }
        if (($current.Length + 1 + $word.Length) -le $Width) {
            $current = "$current $word"
        } else {
            [void]$lines.Add($current)
            $current = $word
        }
    }
    if ($current.Length -gt 0) { [void]$lines.Add($current) }
    return ,@($lines)
}

# =============================================================================
# RESET AND RESTORE -- verified restore points (FIX58, issue #348)
# =============================================================================
# A restore point is a verified copy of the game settings (UserProfiles) plus
# TeknoParrot Manager's own settings file, made at start-up before the start-up
# settings save. The game settings copy is an ordinary verified UserProfiles
# backup (FullBackup\<Kind>_<time>_<8 hex>, with its completion record), so the
# existing restore list can use it too. The restore point record
# (Backups\RestorePoints\RP_<time>_<8 hex>\restore-point.json) lists every file
# with its length and SHA-256, and the settings file's hash or its absence.
# A new start-up restore point is made only when something changed since the
# newest one; the first one (Baseline) is never replaced; nothing is ever
# removed automatically (older ones are removed only on request).
function Get-TpmRestorePointsRoot {
    if (-not $script:TpmOwnedLayout) { throw 'The TeknoParrot Manager data folder is not ready, so restore points are not available.' }
    return (Join-Path ([string]$script:TpmOwnedLayout.Backups) 'RestorePoints')
}

function Get-TpmRestorePointRecordName { return 'restore-point.json' }
function Get-TpmRestorePointSettingsCopyName { return 'settings.json' }
# Restore points kept by "Remove older restore points" besides the first one.
function Get-TpmRestorePointKeepCount { return 10 }

# A file path must be shorter than 260 characters and a folder path shorter
# than 248 for the .NET Framework calls that Windows PowerShell 5.1 makes.
function Test-TpmPathLengthAllowed {
    param([Parameter(Mandatory)][int]$Length, [switch]$Directory)
    if ($Directory) { return ($Length -le 247) }
    return ($Length -le 259)
}

# An error raised before anything was changed. Code says why, so a caller can
# report "nothing was changed" instead of undoing work it never did.
function New-TpmNoChangeException {
    param([Parameter(Mandatory)][string]$Message, [Parameter(Mandatory)][string]$Code)
    $exception = New-Object System.InvalidOperationException $Message
    $exception.Data['TpmNoChange'] = $Code
    return $exception
}

# Present/Length/SHA-256 of one file; absence is a valid, recorded state.
function Get-TpmRestorePointFileState {
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)) {
        return [pscustomobject]@{ Present = $false; Length = $null; Sha256 = $null }
    }
    if (Test-Path -LiteralPath $Path -PathType Container) { throw ("A folder is in the place of the file '{0}'." -f [System.IO.Path]::GetFileName($Path)) }
    $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    $hash = (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash.ToUpperInvariant()
    return [pscustomobject]@{ Present = $true; Length = [int64]$item.Length; Sha256 = $hash }
}

# Free bytes on the drive that holds Path, or $null when Windows cannot say (for example a network share).
function Get-TpmRestorePointFreeBytes {
    param([Parameter(Mandatory)][string]$Path)
    try {
        $root = [System.IO.Path]::GetPathRoot([System.IO.Path]::GetFullPath($Path))
        if ([string]::IsNullOrWhiteSpace($root) -or $root.StartsWith('\\')) { return $null }
        $drive = New-Object System.IO.DriveInfo($root)
        return [int64]$drive.AvailableFreeSpace
    } catch {
        return $null
    }
}

# One walk over UserProfiles (FullBackup left out): total bytes, the longest
# relative file and folder path, and every link (junction or symlink). A link is
# listed but never followed, so a link to a huge or looping folder cannot stall it.
function Get-TpmUserProfilesFootprint {
    param([Parameter(Mandatory)][string]$UserProfilesDir)
    $root = [System.IO.Path]::GetFullPath($UserProfilesDir).TrimEnd('\','/')
    $bytes = [int64]0
    $longestFile = 0
    $longestDirectory = 0
    $links = New-Object System.Collections.Generic.List[string]
    $pending = New-Object System.Collections.Generic.Stack[object]
    foreach ($top in @(Get-ChildItem -LiteralPath $root -Force -ErrorAction Stop | Where-Object { $_.Name -ne 'FullBackup' })) { $pending.Push($top) }
    while ($pending.Count -gt 0) {
        $item = $pending.Pop()
        $relative = $item.FullName.Substring($root.Length).TrimStart('\','/')
        $isLink = (($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0)
        if ($isLink) { [void]$links.Add($relative) }
        if ($item.PSIsContainer) {
            if ($relative.Length -gt $longestDirectory) { $longestDirectory = $relative.Length }
            if (-not $isLink) {
                foreach ($child in @(Get-ChildItem -LiteralPath $item.FullName -Force -ErrorAction Stop)) { $pending.Push($child) }
            }
        } else {
            $bytes += [int64]$item.Length
            if ($relative.Length -gt $longestFile) { $longestFile = $relative.Length }
        }
    }
    return [pscustomobject]@{ Bytes = $bytes; LongestFileLength = $longestFile; LongestDirectoryLength = $longestDirectory; ReparsePoints = @($links | Sort-Object) }
}

# Splits restore points by the TeknoParrot folder they were made for. Only the
# ones for this UserProfiles folder are ever offered, counted or removed; the
# rest are shown as a read-only note. A damaged record names no folder.
function Select-TpmRestorePointsForFolder {
    param([object[]]$RestorePoints = @(), [Parameter(Mandatory)][string]$UserProfilesDir)
    $profilesFull = [System.IO.Path]::GetFullPath($UserProfilesDir).TrimEnd('\','/')
    $current = New-Object System.Collections.Generic.List[object]
    $other = New-Object System.Collections.Generic.List[object]
    $damaged = New-Object System.Collections.Generic.List[object]
    foreach ($point in @($RestorePoints)) {
        if ($null -eq $point) { continue }
        if (-not [bool]$point.Readable) {
            [void]$damaged.Add($point)
        } elseif (([string]$point.Record.UserProfilesDir).TrimEnd('\','/') -ieq $profilesFull) {
            [void]$current.Add($point)
        } else {
            [void]$other.Add($point)
        }
    }
    return [pscustomobject]@{ Current = $current.ToArray(); OtherFolder = $other.ToArray(); Damaged = $damaged.ToArray() }
}

# One comparable text for "the game settings plus the settings file", used to
# skip a start-up restore point when nothing changed and to detect changes
# made between the preview and the restore.
function Get-TpmResetRestoreProfilesKey {
    param([object[]]$Entries = @())
    return ((@(Get-TpmUserProfilesBackupInventoryKeys -Inventory @($Entries)) -join "`n"))
}

function Get-TpmResetRestoreStateKey {
    param([object[]]$Entries = @(), [AllowNull()][AllowEmptyString()][string]$ConfigSha256 = '')
    $configText = if ([string]::IsNullOrWhiteSpace($ConfigSha256)) { 'ABSENT' } else { $ConfigSha256.ToUpperInvariant() }
    return ((Get-TpmResetRestoreProfilesKey -Entries $Entries) + "`nSETTINGS|" + $configText)
}

# Producer written into a UserProfiles backup completion record, or $null.
function Get-TpmUserProfilesBackupProducer {
    param([Parameter(Mandatory)][string]$BackupPath)
    try {
        $record = [System.IO.File]::ReadAllText((Join-Path $BackupPath (Get-TpmUserProfilesBackupMarkerName)), (New-Object System.Text.UTF8Encoding $false)) | ConvertFrom-Json -ErrorAction Stop
        return [string]$record.Producer
    } catch {
        return $null
    }
}

# Makes one verified restore point. Never throws: Succeeded is false with a
# plain Reason, and only the folders this call created are removed again.
function New-TpmRestorePoint {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][AllowEmptyString()][string]$ConfigPath,
        [Parameter(Mandatory)][ValidateSet('Baseline','Startup','BeforeReset')][string]$Kind,
        [string]$RestorePointsRoot = ''
    )
    $id = $null
    $stagingPath = $null
    $finalPath = $null
    $published = $false
    $profilesBackupPath = $null
    try {
        if ([string]::IsNullOrWhiteSpace($RestorePointsRoot)) { $RestorePointsRoot = Get-TpmRestorePointsRoot }
        $RestorePointsRoot = [System.IO.Path]::GetFullPath($RestorePointsRoot).TrimEnd('\','/')
        $profilesFull = [System.IO.Path]::GetFullPath($UserProfilesDir).TrimEnd('\','/')
        if (-not (Test-Path -LiteralPath $profilesFull -PathType Container)) { throw 'The game settings folder (UserProfiles) is missing.' }
        if (-not (Test-TpmNoReparsePath -Path $profilesFull)) { throw 'The game settings folder (UserProfiles) failed the safety check.' }
        if (-not [string]::IsNullOrWhiteSpace($ConfigPath) -and (Test-Path -LiteralPath $ConfigPath) -and -not (Test-TpmNoReparsePath -Path $ConfigPath)) {
            throw 'The TeknoParrot Manager settings file failed the safety check.'
        }
        $configBefore = Get-TpmRestorePointFileState -Path $ConfigPath

        # Space and path-length checks before anything is written. .NET Framework refuses a file path of 260
        # or more characters and a folder path of 248 or more.
        $footprint = Get-TpmUserProfilesFootprint -UserProfilesDir $profilesFull
        $needed = [int64]16MB + [int64]$footprint.Bytes
        if ($configBefore.Present) { $needed += [int64]$configBefore.Length }
        $backupDirLength = (Join-Path (Join-Path $profilesFull 'FullBackup') ((Get-TpmUserProfilesBackupStagingPrefix) + $Kind + '_yyyy-MM-dd_HH-mm-ss_fff_12345678')).Length
        $backupTooLong = (-not (Test-TpmPathLengthAllowed -Length $backupDirLength -Directory)) -or
            (-not (Test-TpmPathLengthAllowed -Length ($backupDirLength + 1 + (Get-TpmUserProfilesBackupMarkerName).Length))) -or
            ($footprint.LongestDirectoryLength -gt 0 -and -not (Test-TpmPathLengthAllowed -Length ($backupDirLength + 1 + $footprint.LongestDirectoryLength) -Directory)) -or
            ($footprint.LongestFileLength -gt 0 -and -not (Test-TpmPathLengthAllowed -Length ($backupDirLength + 1 + $footprint.LongestFileLength)))
        if ($backupTooLong) {
            throw 'A game settings file has a path that would be too long for Windows inside the backup folder. Move TeknoParrot to a folder with a shorter path.'
        }
        $id = 'RP_{0}_{1}' -f (Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss', [System.Globalization.CultureInfo]::InvariantCulture), [guid]::NewGuid().ToString('N').Substring(0,8)
        $finalPath = Join-Path $RestorePointsRoot $id
        $stagingPath = Join-Path $RestorePointsRoot ((Get-TpmUserProfilesBackupStagingPrefix) + $id)
        # The record is written through a temporary name that is 37 characters longer (Write-TpmAtomicTextFile).
        if (-not (Test-TpmPathLengthAllowed -Length $stagingPath.Length -Directory) -or -not (Test-TpmPathLengthAllowed -Length ((Join-Path $stagingPath (Get-TpmRestorePointRecordName)).Length + 37))) {
            throw 'The restore point folder path would be too long for Windows. Move TeknoParrot to a folder with a shorter path.'
        }
        foreach ($probe in @($profilesFull, $RestorePointsRoot)) {
            $free = Get-TpmRestorePointFreeBytes -Path $probe
            if ($null -ne $free -and $free -lt $needed) {
                throw ('There is not enough free disk space for a restore point (about {0:N0} MB is needed).' -f [Math]::Ceiling($needed / 1MB))
            }
        }

        [void][System.IO.Directory]::CreateDirectory($RestorePointsRoot)
        if (-not (Test-TpmNoReparsePath -Path $RestorePointsRoot)) { throw 'The restore point folder failed the safety check.' }

        $profilesBackup = New-TpmVerifiedUserProfilesBackup -UserProfilesDir $profilesFull -Label $Kind
        if (-not [bool]$profilesBackup.Verified) { throw ('The copy of the game settings could not be made and checked. {0}' -f [string]$profilesBackup.Reason) }
        $profilesBackupPath = [string]$profilesBackup.Path

        [void][System.IO.Directory]::CreateDirectory($stagingPath)
        if (-not (Test-TpmNoReparsePath -Path $stagingPath)) { throw 'The restore point folder failed the safety check.' }
        $configRecord = [ordered]@{ SourcePath = $(if ([string]::IsNullOrWhiteSpace($ConfigPath)) { '' } else { [System.IO.Path]::GetFullPath($ConfigPath) }); Present = [bool]$configBefore.Present; Length = $configBefore.Length; Sha256 = $configBefore.Sha256; StoredName = $null }
        if ($configBefore.Present) {
            $settingsCopy = Join-Path $stagingPath (Get-TpmRestorePointSettingsCopyName)
            [System.IO.File]::Copy($ConfigPath, $settingsCopy, $false)
            $copyState = Get-TpmRestorePointFileState -Path $settingsCopy
            if ($copyState.Sha256 -ne $configBefore.Sha256 -or $copyState.Length -ne $configBefore.Length) { throw 'The copy of the TeknoParrot Manager settings file did not match the original.' }
            $configRecord.StoredName = Get-TpmRestorePointSettingsCopyName
        }
        $configAfter = Get-TpmRestorePointFileState -Path $ConfigPath
        if ([bool]$configAfter.Present -ne [bool]$configBefore.Present -or [string]$configAfter.Sha256 -ne [string]$configBefore.Sha256) {
            throw 'The TeknoParrot Manager settings file changed while the restore point was being made.'
        }

        $entries = @(@($profilesBackup.Manifest) | Where-Object { $null -ne $_ } | Sort-Object { [string]$_.RelativePath } | ForEach-Object {
            $isDirectory = [bool]$_.IsDirectory
            [pscustomobject][ordered]@{ RelativePath = [string]$_.RelativePath; IsDirectory = $isDirectory; Length = $(if ($isDirectory) { $null } else { [int64]$_.Length }); Sha256 = $(if ($isDirectory) { $null } else { ([string]$_.Sha256).ToUpperInvariant() }) }
        })
        $record = [pscustomobject][ordered]@{
            Schema = 'TPM.RestorePoint.v1'
            Id = $id
            Kind = $Kind
            CreatedUtc = (Get-Date).ToUniversalTime().ToString('o')
            UserProfilesDir = $profilesFull
            UserProfilesBackup = [System.IO.Path]::GetFileName($profilesBackupPath)
            FileCount = @($entries | Where-Object { -not $_.IsDirectory }).Count
            DirectoryCount = @($entries | Where-Object { $_.IsDirectory }).Count
            ReparsePoints = @($footprint.ReparsePoints)
            Entries = $entries
            Config = [pscustomobject]$configRecord
        }
        Write-TpmAtomicTextFile -Path (Join-Path $stagingPath (Get-TpmRestorePointRecordName)) -Text ($record | ConvertTo-Json -Depth 6) -Operation 'restore point record' -Validate {
            param([string]$Written)
            $parsed = $Written | ConvertFrom-Json -ErrorAction Stop
            return ($null -ne $parsed -and [string]$parsed.Schema -eq 'TPM.RestorePoint.v1')
        }
        if (Test-Path -LiteralPath $finalPath) { throw 'The restore point name is already in use.' }
        Move-TpmDirectoryWithRetry -Source $stagingPath -Destination $finalPath
        $published = $true
        $point = Read-TpmRestorePoint -Path $finalPath
        $check = Test-TpmRestorePoint -RestorePoint $point -UserProfilesDir $profilesFull
        if (-not $check.Valid) { throw ('The new restore point did not pass its check. {0}' -f $check.Reason) }
        Write-Log ("Restore point: {0} ({1}) saved and verified; {2} file(s); settings file {3}." -f $id, $Kind, $record.FileCount, $(if ($configBefore.Present) { 'included' } else { 'absent' }))
        return [pscustomobject]@{ Succeeded = $true; Verified = $true; Id = $id; Kind = $Kind; Path = $finalPath; RestorePoint = $point; ProfilesBackupPath = $profilesBackupPath; Reason = $null; ResiduePaths = @() }
    } catch {
        $reason = $_.Exception.Message
        $residue = @()
        # Only folders this call created: the staged record, the published record and the game settings copy made for it.
        foreach ($candidate in @($stagingPath, $(if ($published) { $finalPath } else { $null }), $profilesBackupPath)) {
            if (-not [string]::IsNullOrWhiteSpace($candidate) -and (Test-Path -LiteralPath $candidate -PathType Container)) {
                try { Remove-Item -LiteralPath $candidate -Recurse -Force -ErrorAction Stop } catch { $residue += $candidate }
            }
        }
        Write-Log ("Restore point: {0} could not be saved and verified -- {1}" -f $Kind, $reason)
        return [pscustomobject]@{ Succeeded = $false; Verified = $false; Id = $id; Kind = $Kind; Path = $null; RestorePoint = $null; ProfilesBackupPath = $null; Reason = $reason; ResiduePaths = $residue }
    }
}

# Reads one restore point record. Never throws: Readable is false with a plain Reason.
function Read-TpmRestorePoint {
    param([Parameter(Mandatory)][string]$Path)
    $id = [System.IO.Path]::GetFileName($Path.TrimEnd('\','/'))
    try {
        $record = [System.IO.File]::ReadAllText((Join-Path $Path (Get-TpmRestorePointRecordName)), (New-Object System.Text.UTF8Encoding $false)) | ConvertFrom-Json -ErrorAction Stop
        if ($null -eq $record -or [string]$record.Schema -ne 'TPM.RestorePoint.v1') { throw 'unknown record format' }
        if ([string]$record.Id -cne $id) { throw 'the record belongs to a different folder' }
        if ([string]$record.Kind -notin @('Baseline','Startup','BeforeReset')) { throw 'unknown restore point kind' }
        if ($null -eq $record.Config) { throw 'the settings file entry is missing' }
        # PowerShell 7 turns ISO dates into DateTime values while reading JSON; Windows PowerShell keeps the text.
        $created = if ($record.CreatedUtc -is [datetime]) {
            $value = [datetime]$record.CreatedUtc
            if ($value.Kind -eq [System.DateTimeKind]::Unspecified) { [datetime]::SpecifyKind($value, [System.DateTimeKind]::Utc) } else { $value.ToUniversalTime() }
        } else {
            [datetime]::Parse([string]$record.CreatedUtc, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime()
        }
        return [pscustomobject]@{ Id = $id; Path = $Path; Readable = $true; Kind = [string]$record.Kind; CreatedUtc = $created; Record = $record; Reason = $null }
    } catch {
        return [pscustomobject]@{ Id = $id; Path = $Path; Readable = $false; Kind = $null; CreatedUtc = $null; Record = $null; Reason = 'The restore point record is missing or damaged.' }
    }
}

# All restore points, newest first; damaged records are listed last (Readable = $false). INCOMPLETE_ folders are never listed.
function Get-TpmRestorePoints {
    param([string]$RestorePointsRoot = '')
    if ([string]::IsNullOrWhiteSpace($RestorePointsRoot)) { $RestorePointsRoot = Get-TpmRestorePointsRoot }
    if (-not (Test-Path -LiteralPath $RestorePointsRoot -PathType Container)) { return @() }
    $prefix = Get-TpmUserProfilesBackupStagingPrefix
    $points = @(Get-ChildItem -LiteralPath $RestorePointsRoot -Directory -Force -ErrorAction Stop | Where-Object { -not $_.Name.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase) } | ForEach-Object { Read-TpmRestorePoint -Path $_.FullName })
    $readable = @($points | Where-Object { $_.Readable } | Sort-Object -Property @{ Expression = { $_.CreatedUtc }; Descending = $true }, @{ Expression = { $_.Id }; Descending = $true })
    $damaged = @($points | Where-Object { -not $_.Readable } | Sort-Object -Property Id -Descending)
    return @($readable + $damaged)
}

# CouldNotCheck marks a failure that is not proof of damage: a file could not be
# read right now (for example it is in use by another program).
function New-TpmRestorePointCheckFailure {
    param([Parameter(Mandatory)][string]$Reason, [switch]$CouldNotCheck)
    return [pscustomobject]@{ Valid = $false; Reason = $Reason; BackupPath = $null; CouldNotCheck = [bool]$CouldNotCheck }
}

# Full check of one restore point against its record: the game settings copy
# (completion record, every file's length and SHA-256) and the settings file
# copy. Never throws; Valid is false with a plain Reason.
function Test-TpmRestorePoint {
    param([Parameter(Mandatory)]$RestorePoint, [Parameter(Mandatory)][string]$UserProfilesDir)
    try {
        if (-not [bool]$RestorePoint.Readable -or $null -eq $RestorePoint.Record) { return (New-TpmRestorePointCheckFailure -Reason 'The restore point record is missing or damaged.') }
        $record = $RestorePoint.Record
        $profilesFull = [System.IO.Path]::GetFullPath($UserProfilesDir).TrimEnd('\','/')
        if (([string]$record.UserProfilesDir).TrimEnd('\','/') -ine $profilesFull) { return (New-TpmRestorePointCheckFailure -Reason 'This restore point was made for a different TeknoParrot folder.') }
        if (-not (Test-TpmNoReparsePath -Path ([string]$RestorePoint.Path))) { return (New-TpmRestorePointCheckFailure -Reason 'The restore point folder failed the safety check.') }
        $leaf = [string]$record.UserProfilesBackup
        if ([string]::IsNullOrWhiteSpace($leaf) -or $leaf -ne [System.IO.Path]::GetFileName($leaf) -or $leaf -match '\.\.' -or -not $leaf.StartsWith(([string]$record.Kind + '_'), [System.StringComparison]::Ordinal)) {
            return (New-TpmRestorePointCheckFailure -Reason 'The restore point record names an unexpected backup folder.')
        }
        $backupPath = Join-Path (Join-Path $profilesFull 'FullBackup') $leaf
        if (-not (Test-Path -LiteralPath $backupPath -PathType Container)) { return (New-TpmRestorePointCheckFailure -Reason 'The copy of the game settings for this restore point is missing.') }
        if (-not (Test-TpmNoReparsePath -Path $backupPath)) { return (New-TpmRestorePointCheckFailure -Reason 'The copy of the game settings failed the safety check.') }
        $expected = @($record.Entries | Where-Object { $null -ne $_ })
        if ([int]$record.FileCount -ne @($expected | Where-Object { -not [bool]$_.IsDirectory }).Count) { return (New-TpmRestorePointCheckFailure -Reason 'The restore point record is inconsistent.') }
        $inventory = @(Get-TpmUserProfilesBackupInventory -BackupPath $backupPath -ProgressLabel 'Restore point check')
        $completion = Test-TpmUserProfilesBackupCompletion -BackupPath $backupPath -Inventory $inventory
        if (-not $completion.Valid) {
            $completionFlag = $completion.PSObject.Properties['CouldNotCheck']
            return (New-TpmRestorePointCheckFailure -Reason ('The copy of the game settings failed its check. {0}' -f $completion.Reason) -CouldNotCheck:($null -ne $completionFlag -and [bool]$completionFlag.Value))
        }
        if (((Get-TpmUserProfilesBackupInventoryKeys -Inventory $expected) -join "`n") -ne ((Get-TpmUserProfilesBackupInventoryKeys -Inventory $inventory) -join "`n")) {
            return (New-TpmRestorePointCheckFailure -Reason 'The copy of the game settings no longer matches the restore point record: files are missing, extra, or changed.')
        }
        $config = $record.Config
        if ([bool]$config.Present) {
            if ([string]$config.StoredName -cne (Get-TpmRestorePointSettingsCopyName)) { return (New-TpmRestorePointCheckFailure -Reason 'The restore point record names an unexpected settings copy.') }
            $stored = Get-TpmRestorePointFileState -Path (Join-Path ([string]$RestorePoint.Path) (Get-TpmRestorePointSettingsCopyName))
            if (-not $stored.Present -or [int64]$stored.Length -ne [int64]$config.Length -or $stored.Sha256 -ne ([string]$config.Sha256).ToUpperInvariant()) {
                return (New-TpmRestorePointCheckFailure -Reason 'The saved copy of the TeknoParrot Manager settings is missing or changed.')
            }
        }
        return [pscustomobject]@{ Valid = $true; Reason = $null; BackupPath = $backupPath }
    } catch {
        return (New-TpmRestorePointCheckFailure -Reason ('The restore point could not be read completely. {0}' -f $_.Exception.Message) -CouldNotCheck:(Test-TpmFileAccessException -Exception $_.Exception -ErrorRecord $_))
    }
}

# Exactly what a restore from this restore point would change, per file:
# Replace (changed since), PutBack (removed since), Remove (added since; only a
# full restore removes it). Game profiles are top-level *.xml files.
function Get-TpmRestorePointChangePlan {
    param([Parameter(Mandatory)]$RestorePoint, [Parameter(Mandatory)][string]$UserProfilesDir, [AllowEmptyString()][string]$ConfigPath = '')
    $current = @(Get-TpmUserProfilesBackupManifest -UserProfilesDir $UserProfilesDir -ProgressLabel 'Reset and Restore comparison')
    $then = @($RestorePoint.Record.Entries | Where-Object { $null -ne $_ })
    $currentFiles = @{}
    $thenFiles = @{}
    foreach ($entry in $current) { if (-not [bool]$entry.IsDirectory) { $currentFiles[[string]$entry.RelativePath] = $entry } }
    foreach ($entry in $then) { if (-not [bool]$entry.IsDirectory) { $thenFiles[[string]$entry.RelativePath] = $entry } }
    $changes = New-Object System.Collections.Generic.List[object]
    foreach ($key in @(@($thenFiles.Keys) + @($currentFiles.Keys) | Sort-Object -Unique)) {
        $old = $thenFiles[$key]
        $now = $currentFiles[$key]
        if ($old -and $now) {
            if (([string]$old.Sha256).ToUpperInvariant() -eq ([string]$now.Sha256).ToUpperInvariant() -and [int64]$old.Length -eq [int64]$now.Length) { continue }
            $change = 'Replace'
        } elseif ($old) {
            $change = 'PutBack'
        } else {
            $change = 'Remove'
        }
        $isGame = ($key -notmatch '[\\/]') -and $key.EndsWith('.xml', [System.StringComparison]::OrdinalIgnoreCase)
        [void]$changes.Add([pscustomobject]@{
            RelativePath = [string]$key
            IsGameProfile = $isGame
            GameCode = $(if ($isGame) { [System.IO.Path]::GetFileNameWithoutExtension($key) } else { $null })
            Change = $change
            CurrentSha256 = $(if ($now) { ([string]$now.Sha256).ToUpperInvariant() } else { '' })
            RestoreSha256 = $(if ($old) { ([string]$old.Sha256).ToUpperInvariant() } else { '' })
        })
    }
    $currentDirs = @($current | Where-Object { [bool]$_.IsDirectory } | ForEach-Object { [string]$_.RelativePath })
    $thenDirs = @($then | Where-Object { [bool]$_.IsDirectory } | ForEach-Object { [string]$_.RelativePath })
    $foldersRemoved = @($currentDirs | Where-Object { $thenDirs -notcontains $_ })
    $foldersPutBack = @($thenDirs | Where-Object { $currentDirs -notcontains $_ })

    $configNow = Get-TpmRestorePointFileState -Path $ConfigPath
    $config = $RestorePoint.Record.Config
    $configChange = if ([string]::IsNullOrWhiteSpace($ConfigPath) -or -not [bool]$config.Present) {
        'NotInRestorePoint'
    } elseif ($configNow.Present -and $configNow.Sha256 -eq ([string]$config.Sha256).ToUpperInvariant()) {
        'Same'
    } else {
        'Replace'
    }
    return [pscustomobject]@{
        Changes = $changes.ToArray()
        FoldersRemoved = $foldersRemoved
        FoldersPutBack = $foldersPutBack
        ConfigChange = $configChange
        CurrentStateKey = (Get-TpmResetRestoreStateKey -Entries $current -ConfigSha256 ([string]$configNow.Sha256))
    }
}

# The staged copy sits next to the target under a name 21 characters longer.
function New-TpmVerifiedFileSwapStagePath {
    param([Parameter(Mandatory)][string]$TargetPath)
    return ('{0}.{1}.tpm-restore' -f [System.IO.Path]::GetFullPath($TargetPath), [guid]::NewGuid().ToString('N').Substring(0,8))
}

# Puts one file in place from a verified source: stage a copy next to the
# target, check its SHA-256, swap it in with File.Replace (or a non-overwriting
# move when the target is absent), then check the bytes again. With
# -ExpectedCurrentSha256 the target is hashed again right before the swap (any
# earlier check can be seconds old) and nothing is replaced when it differs;
# empty means the target must be absent. Throws on any failure; the staged copy
# is always removed and the source is never changed. A failure that changed
# nothing carries a TpmNoChange code (see New-TpmNoChangeException).
# FIX110A S-3: the replace keeps the bytes it removes, and they are compared with the
# bytes that were checked; a save made in between is put back (or kept in a named file
# when it cannot be put back, error data TpmNewerKept) and never lost. With
# -PlacedFile (a hashtable) the staged file's identity and write time are recorded, so
# a later undo can delete exactly this file and nothing else.
function Invoke-TpmVerifiedFileSwap {
    param(
        [Parameter(Mandatory)][string]$SourcePath,
        [Parameter(Mandatory)][string]$TargetPath,
        [Parameter(Mandatory)][string]$ExpectedSha256,
        [Parameter(Mandatory)][int64]$ExpectedLength,
        [AllowEmptyString()][string]$ExpectedCurrentSha256 = '',
        [System.Collections.IDictionary]$PlacedFile = $null
    )
    $expected = $ExpectedSha256.ToUpperInvariant()
    $sourceState = Get-TpmRestorePointFileState -Path $SourcePath
    if (-not $sourceState.Present -or $sourceState.Sha256 -ne $expected -or [int64]$sourceState.Length -ne $ExpectedLength) { throw 'The saved copy no longer matches its record.' }
    $target = [System.IO.Path]::GetFullPath($TargetPath)
    Assert-TpmNoReparseWriteTarget -Path $target -Operation 'Reset and Restore'
    $stage = New-TpmVerifiedFileSwapStagePath -TargetPath $target
    if (-not (Test-TpmPathLengthAllowed -Length $stage.Length)) {
        throw (New-TpmNoChangeException -Message 'The file path would be too long for Windows. Move TeknoParrot to a folder with a shorter path.' -Code 'PATH_TOO_LONG')
    }
    $displaced = $null
    $keepDisplaced = $false
    try {
        [System.IO.File]::Copy($SourcePath, $stage, $false)
        $stageState = Get-TpmRestorePointFileState -Path $stage
        if ($stageState.Sha256 -ne $expected -or [int64]$stageState.Length -ne $ExpectedLength) { throw 'The staged copy did not match the saved copy.' }
        Assert-TpmNoReparseWriteTarget -Path $target -Operation 'Reset and Restore'
        if ($PSBoundParameters.ContainsKey('ExpectedCurrentSha256')) {
            $liveNow = Get-TpmRestorePointFileState -Path $target
            $liveSha = if ($liveNow.Present) { [string]$liveNow.Sha256 } else { '' }
            if ($liveSha -ne $ExpectedCurrentSha256.ToUpperInvariant()) {
                throw (New-TpmNoChangeException -Message 'The file changed while TeknoParrot Manager was preparing, so it was not replaced.' -Code 'CHANGED_SINCE_PREVIEW')
            }
        }
        if ($null -ne $PlacedFile) {
            # The staged file keeps its identity and write time when it is moved into place.
            $PlacedFile['Identity'] = [string](Get-TpmFileIdentityString -Path $stage)
            $PlacedFile['LastWriteTimeUtc'] = [System.IO.File]::GetLastWriteTimeUtc($stage)
        }
        if (Test-Path -LiteralPath $target -PathType Leaf) {
            # Same length as the stage name, so the path-length check above covers it. Until the replace has finished, these may be the only copy of the old bytes.
            $displaced = [System.IO.Path]::ChangeExtension($stage, '.tpm-replace')
            $keepDisplaced = $true
            Assert-TpmNoReparseWriteTarget -Path $displaced -Operation 'Reset and Restore'
            Invoke-TpmAtomicFileReplace -Source $stage -Destination $target -Backup $displaced
            if ($PSBoundParameters.ContainsKey('ExpectedCurrentSha256')) {
                # keepDisplaced stays set while the displaced bytes are read and compared: if that read throws, they may be the only copy.
                $replacedState = Get-TpmRestorePointFileState -Path $displaced
                if (-not $replacedState.Present -or [string]$replacedState.Sha256 -ne $ExpectedCurrentSha256.ToUpperInvariant()) {
                    # Another program saved between the check and the replace: its bytes are the newest. Put them back.
                    $putBack = $replacedState.Present -and (Restore-TpmLaunchBoxDisplacedFile -Path $target -DisplacedPath $displaced -WrittenHash $expected)
                    if ($putBack) {
                        $keepDisplaced = $false
                        throw (New-TpmNoChangeException -Message 'The file changed while TeknoParrot Manager was replacing it, so the newer file was kept.' -Code 'CHANGED_SINCE_PREVIEW')
                    }
                    $newerKept = New-Object System.InvalidOperationException ('The file changed while TeknoParrot Manager was replacing it, and the newer file could not be put back. The newer file is kept at {0}.' -f $displaced)
                    $newerKept.Data['TpmNewerKept'] = $displaced
                    throw $newerKept
                }
            }
            $keepDisplaced = $false
        } else {
            [System.IO.File]::Move($stage, $target)
        }
        $after = Get-TpmRestorePointFileState -Path $target
        if (-not $after.Present -or $after.Sha256 -ne $expected -or [int64]$after.Length -ne $ExpectedLength) { throw 'The file did not match the saved copy after it was put back.' }
    } finally {
        if (Test-Path -LiteralPath $stage -PathType Leaf) { Remove-Item -LiteralPath $stage -Force -ErrorAction SilentlyContinue }
        if ($null -ne $displaced -and -not $keepDisplaced -and (Test-Path -LiteralPath $displaced -PathType Leaf)) { Remove-Item -LiteralPath $displaced -Force -ErrorAction SilentlyContinue }
    }
}

function New-TpmResetRestoreResult {
    param(
        [Parameter(Mandatory)][ValidateSet('NO_OP','FAILED_BEFORE_MUTATION','SUCCEEDED','ROLLED_BACK_VERIFIED','ACTION_REQUIRED')][string]$Outcome,
        [Parameter(Mandatory)][string]$ReasonCode,
        [Parameter(Mandatory)][string]$Summary,
        [string[]]$ChangedItems = @(),
        [AllowNull()][AllowEmptyString()][string]$SafetyRestorePoint = $null,
        [bool]$RestartRequired = $false
    )
    return [pscustomobject]@{
        PSTypeName = 'TPM.ResetRestoreResult.v1'
        Outcome = $Outcome
        ReasonCode = $ReasonCode
        Summary = $Summary
        Succeeded = ($Outcome -eq 'SUCCEEDED')
        ChangedItems = @($ChangedItems | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
        SafetyRestorePoint = $SafetyRestorePoint
        RestartRequired = $RestartRequired
    }
}

# "Nothing was changed" result for a failure that carries a TpmNoChange code.
function New-TpmNoChangeResult {
    param([Parameter(Mandatory)]$Exception, [AllowEmptyString()][string]$SafetyRestorePoint = '')
    $code = [string]$Exception.Data['TpmNoChange']
    $tail = if ($code -eq 'CHANGED_SINCE_PREVIEW') { ' Open Reset and Restore again to see the new preview.' } else { '' }
    return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode $code -Summary ('Nothing was changed. {0}{1}' -f $Exception.Message, $tail) -SafetyRestorePoint $SafetyRestorePoint)
}

# Plain message for a settings file that cannot be read (for example because
# another program has it open). Names the file when the error message does.
function Get-TpmUnreadableFileSummary {
    param([AllowEmptyString()][string]$Message)
    $quoted = [regex]::Match([string]$Message, "'(?<path>[^']+)'")
    if ($quoted.Success) {
        $leaf = @($quoted.Groups['path'].Value -split '[\\/]')[-1]
        if (-not [string]::IsNullOrWhiteSpace($leaf)) {
            return ("Nothing was changed. TeknoParrot Manager could not read '{0}'. Another program may have it open. Close that program and try again." -f $leaf)
        }
    }
    return 'Nothing was changed. TeknoParrot Manager could not read one of your settings files. Another program may have it open. Close that program and try again.'
}

# Puts back one game's settings file from a restore point. A verified
# BeforeReset restore point of the current state is made first and kept, the
# file is swapped in and checked, and a failure puts the previous file back
# and checks it. A game the restore point does not have is never deleted.
function Restore-TpmRestorePointGame {
    param(
        [Parameter(Mandatory)]$RestorePoint,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][string]$RelativePath,
        [AllowEmptyString()][string]$ExpectedCurrentSha256 = '',
        [AllowEmptyString()][string]$ConfigPath = '',
        [string]$RestorePointsRoot = ''
    )
    $profilesFull = [System.IO.Path]::GetFullPath($UserProfilesDir).TrimEnd('\','/')
    if ($RelativePath -match '[\\/]' -or $RelativePath -match '\.\.' -or -not $RelativePath.EndsWith('.xml', [System.StringComparison]::OrdinalIgnoreCase)) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'NOT_A_GAME_PROFILE' -Summary 'Nothing was changed. Only a single game settings file can be put back on its own.')
    }
    $check = Test-TpmRestorePoint -RestorePoint $RestorePoint -UserProfilesDir $profilesFull
    if (-not $check.Valid) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'RESTORE_POINT_DAMAGED' -Summary ('Nothing was changed. This restore point cannot be used: {0}' -f $check.Reason))
    }
    $entry = @($RestorePoint.Record.Entries | Where-Object { $null -ne $_ -and -not [bool]$_.IsDirectory -and [string]$_.RelativePath -ieq $RelativePath }) | Select-Object -First 1
    if ($null -eq $entry) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'NOT_IN_RESTORE_POINT' -Summary 'Nothing was changed. This game had no settings file when that restore point was made, so there is nothing to put back. TeknoParrot Manager does not delete game settings.')
    }
    $expectedSha = ([string]$entry.Sha256).ToUpperInvariant()
    $target = Join-Path $profilesFull ([string]$entry.RelativePath)
    $source = Join-Path $check.BackupPath ([string]$entry.RelativePath)
    $before = Get-TpmRestorePointFileState -Path $target
    if ($before.Present -and $before.Sha256 -eq $expectedSha) {
        return (New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'ALREADY_MATCHES' -Summary 'Nothing was changed. This game already matches the restore point.')
    }
    if ($PSBoundParameters.ContainsKey('ExpectedCurrentSha256')) {
        $nowSha = if ($before.Present) { [string]$before.Sha256 } else { '' }
        if ($nowSha -ne $ExpectedCurrentSha256.ToUpperInvariant()) {
            return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'CHANGED_SINCE_PREVIEW' -Summary 'Nothing was changed. This game''s settings changed after the preview was shown. Open Reset and Restore again to see the new preview.')
        }
    }
    $stageProbe = New-TpmVerifiedFileSwapStagePath -TargetPath $target
    if (-not (Test-TpmPathLengthAllowed -Length $stageProbe.Length)) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'PATH_TOO_LONG' -Summary 'Nothing was changed. This game''s settings file has a path that would be too long for Windows. Move TeknoParrot to a folder with a shorter path.')
    }
    if (-not (Wait-TpmForProcessClose -ProcessNames @('TeknoParrotUi') -FriendlyName 'TeknoParrot')) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'APPLICATION_RUNNING' -Summary 'Nothing was changed because TeknoParrot is still open.')
    }
    $safety = New-TpmRestorePoint -UserProfilesDir $profilesFull -ConfigPath $ConfigPath -Kind 'BeforeReset' -RestorePointsRoot $RestorePointsRoot
    if (-not $safety.Succeeded) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'SAFETY_RESTORE_POINT_FAILED' -Summary ('Nothing was changed. TeknoParrot Manager could not first save a verified copy of your current game settings. {0}' -f $safety.Reason))
    }
    $safetyEntry = @($safety.RestorePoint.Record.Entries | Where-Object { $null -ne $_ -and -not [bool]$_.IsDirectory -and [string]$_.RelativePath -ieq $RelativePath }) | Select-Object -First 1
    $safetySha = if ($safetyEntry) { ([string]$safetyEntry.Sha256).ToUpperInvariant() } else { '' }
    $beforeSha = if ($before.Present) { [string]$before.Sha256 } else { '' }
    if ($safetySha -ne $beforeSha) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'CHANGED_SINCE_PREVIEW' -Summary 'Nothing was changed. This game''s settings changed while TeknoParrot Manager was preparing. Try again.' -SafetyRestorePoint $safety.Path)
    }
    $placed = @{}
    try {
        Invoke-TpmVerifiedFileSwap -SourcePath $source -TargetPath $target -ExpectedSha256 $expectedSha -ExpectedLength ([int64]$entry.Length) -ExpectedCurrentSha256 $beforeSha -PlacedFile $placed
        Write-Log ("Reset and Restore: {0} put back from restore point {1}; previous state kept in {2}." -f $entry.RelativePath, $RestorePoint.Id, $safety.Id)
        return (New-TpmResetRestoreResult -Outcome 'SUCCEEDED' -ReasonCode 'RESTORED' -Summary 'The game settings were put back and checked byte for byte.' -ChangedItems @([string]$entry.RelativePath) -SafetyRestorePoint $safety.Path)
    } catch {
        $failure = $_.Exception.Message
        if ($_.Exception.Data.Contains('TpmNoChange')) {
            Write-Log ("Reset and Restore: {0} was left as it was -- {1}" -f $entry.RelativePath, $failure)
            return (New-TpmNoChangeResult -Exception $_.Exception -SafetyRestorePoint $safety.Path)
        }
        if ($_.Exception.Data.Contains('TpmNewerKept')) {
            # A newer save is only in a named file, so nothing is undone over it.
            Write-Log ("Reset and Restore: {0} changed while it was being put back -- {1}" -f $entry.RelativePath, $failure)
            return (New-TpmResetRestoreResult -Outcome 'ACTION_REQUIRED' -ReasonCode 'CHANGED_DURING_RESTORE' -Summary ('A game settings file changed while TeknoParrot Manager was putting your old one back. Your newer file could not be put back, so it was kept as a separate file: {0} Copy it over the game file if you want to keep the newer settings. A checked copy of your game settings from just before is kept in: {1}' -f [string]$_.Exception.Data['TpmNewerKept'], $safety.ProfilesBackupPath) -SafetyRestorePoint $safety.Path)
        }
        Write-Log ("Reset and Restore: putting back {0} failed -- {1}" -f $entry.RelativePath, $failure)
        try {
            if ($before.Present) {
                # The file is replaced only while it still holds the bytes just read.
                $nowState = Get-TpmRestorePointFileState -Path $target
                $nowSha = if ($nowState.Present) { [string]$nowState.Sha256 } else { '' }
                Invoke-TpmVerifiedFileSwap -SourcePath (Join-Path $safety.ProfilesBackupPath ([string]$entry.RelativePath)) -TargetPath $target -ExpectedSha256 $beforeSha -ExpectedLength ([int64]$before.Length) -ExpectedCurrentSha256 $nowSha
            } else {
                $leftover = Get-TpmRestorePointFileState -Path $target
                if ($leftover.Present) {
                    # Only the exact file this attempt put there may be removed again: identity, write time and bytes are checked on the same open file that is deleted.
                    if ($leftover.Sha256 -ne $expectedSha) { throw 'An unexpected file is now in place; it was left untouched.' }
                    Assert-TpmNoReparseWriteTarget -Path $target -Operation 'Reset and Restore'
                    [void](Remove-TpmTreeOwnedFile -Path $target -ExpectedIdentity ([string]$placed['Identity']) -ExpectedSha256 $expectedSha -ExpectedLastWriteTimeUtc $placed['LastWriteTimeUtc'])
                }
            }
            return (New-TpmResetRestoreResult -Outcome 'ROLLED_BACK_VERIFIED' -ReasonCode 'RESTORE_FAILED_ROLLED_BACK' -Summary ('The game settings could not be put back ({0}). The settings the game had just before were put back and checked.' -f $failure) -SafetyRestorePoint $safety.Path)
        } catch {
            Write-Log ("Reset and Restore: undoing the failed attempt for {0} also failed -- {1}" -f $entry.RelativePath, $_.Exception.Message)
            return (New-TpmResetRestoreResult -Outcome 'ACTION_REQUIRED' -ReasonCode 'RESTORE_ROLLBACK_FAILED' -Summary ('The game settings could not be put back, and undoing the attempt also failed. A checked copy of your game settings from just before is kept in: {0}' -f $safety.ProfilesBackupPath) -SafetyRestorePoint $safety.Path)
        }
    }
}

# Puts the TeknoParrot Manager settings file back from a restore point's verified copy.
function Restore-TpmRestorePointSettingsFile {
    param([Parameter(Mandatory)]$SourceRestorePoint, [Parameter(Mandatory)][string]$ConfigPath, [AllowEmptyString()][string]$ExpectedCurrentSha256 = '', [System.Collections.IDictionary]$PlacedFile = $null)
    $config = $SourceRestorePoint.Record.Config
    if (-not [bool]$config.Present) { throw 'That restore point has no settings file.' }
    $swap = @{
        SourcePath = (Join-Path ([string]$SourceRestorePoint.Path) (Get-TpmRestorePointSettingsCopyName))
        TargetPath = $ConfigPath
        ExpectedSha256 = [string]$config.Sha256
        ExpectedLength = [int64]$config.Length
    }
    if ($PSBoundParameters.ContainsKey('ExpectedCurrentSha256')) { $swap.ExpectedCurrentSha256 = $ExpectedCurrentSha256 }
    Invoke-TpmVerifiedFileSwap @swap -PlacedFile $PlacedFile
}

# Returns the settings file to the state kept in the BeforeReset restore point:
# its saved bytes, or, when there was no settings file then, removes only the
# exact file this restore wrote. Throws when that cannot be done.
function Undo-TpmRestorePointSettingsFile {
    param([Parameter(Mandatory)]$SafetyRestorePoint, [Parameter(Mandatory)]$WrittenRestorePoint, [Parameter(Mandatory)][string]$ConfigPath, [System.Collections.IDictionary]$PlacedFile = $null)
    $now = Get-TpmRestorePointFileState -Path $ConfigPath
    if ([bool]$SafetyRestorePoint.Record.Config.Present) {
        # The file is replaced only while it still holds the bytes just read.
        Restore-TpmRestorePointSettingsFile -SourceRestorePoint $SafetyRestorePoint -ConfigPath $ConfigPath -ExpectedCurrentSha256 $(if ($now.Present) { [string]$now.Sha256 } else { '' })
        return
    }
    if (-not $now.Present) { return }
    if ($null -eq $PlacedFile) { $PlacedFile = @{} }
    if ($now.Sha256 -ne ([string]$WrittenRestorePoint.Record.Config.Sha256).ToUpperInvariant()) { throw 'An unexpected settings file is in place; it was left untouched.' }
    # Identity, write time and bytes are checked on the same open file that is deleted, so a newer save is never deleted.
    Assert-TpmNoReparseWriteTarget -Path $ConfigPath -Operation 'Reset and Restore'
    [void](Remove-TpmTreeOwnedFile -Path $ConfigPath -ExpectedIdentity ([string]$PlacedFile['Identity']) -ExpectedSha256 ([string]$WrittenRestorePoint.Record.Config.Sha256) -ExpectedLastWriteTimeUtc $PlacedFile['LastWriteTimeUtc'])
}

# Result for links (junctions or symlinks) found inside UserProfiles.
function New-TpmLinkBlockedResult {
    param([Parameter(Mandatory)][string[]]$Links)
    $shown = (@($Links | Select-Object -First 3 | ForEach-Object { "'{0}'" -f $_ })) -join ', '
    $more = if (@($Links).Count -gt 3) { ' (and {0} more)' -f (@($Links).Count - 3) } else { '' }
    return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'LINK_INSIDE_USERPROFILES' -Summary ('Nothing was changed. UserProfiles contains a link (a shortcut to another folder or file): {0}{1}. Putting everything back would delete the link and leave an ordinary empty folder in its place. Remove or move the link yourself, then try again.' -f $shown, $more))
}

# Length of the temporary snapshot folder the UserProfiles restore makes in the
# temp folder (Invoke-RestoreBackupLegacy).
function Get-TpmLegacyRestoreRollbackPathLength {
    return (Join-Path ([System.IO.Path]::GetTempPath()) ('tpm-restore-rollback-' + ('0' * 32))).Length
}

# True when a restore point's record lists at least one game settings file
# (a top-level *.xml). Reads the record only, never the disk.
function Test-TpmRestorePointRecordHasGames {
    param([Parameter(Mandatory)]$RestorePoint)
    if (-not [bool]$RestorePoint.Readable -or $null -eq $RestorePoint.Record) { return $false }
    return (@($RestorePoint.Record.Entries | Where-Object {
                $null -ne $_ -and -not [bool]$_.IsDirectory -and ([string]$_.RelativePath) -notmatch '[\\/]' -and ([string]$_.RelativePath).EndsWith('.xml', [System.StringComparison]::OrdinalIgnoreCase)
            }).Count -gt 0)
}

# Number of top-level *.xml files (the game settings files) in a folder, counted
# with the same filter the UserProfiles restore uses. Throws when the folder
# cannot be read.
function Get-TpmTopLevelGameFileCount {
    param([Parameter(Mandatory)][string]$Path)
    return @(Get-ChildItem -LiteralPath $Path -Filter '*.xml' -File -ErrorAction Stop).Count
}

# Result for a restore point that was saved when there were no game settings
# files yet.
function New-TpmNoGamesResult {
    return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'RESTORE_POINT_HAS_NO_GAMES' -Summary 'Nothing was changed. This restore point was saved when there were no game settings files yet, so it has no games to put back. TeknoParrot Manager does not delete game settings. Choose a later restore point instead.')
}

# Plain "nothing was changed" results for the reasons Restore all must not
# start. Returns $null when none applies, and when only the settings file would
# change. Finding them changes nothing and makes no restore point.
function Get-TpmRestoreAllBlocker {
    param(
        [Parameter(Mandatory)]$Plan,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][string]$BackupPath
    )
    try {
        if ((@($Plan.Changes).Count + @($Plan.FoldersRemoved).Count + @($Plan.FoldersPutBack).Count) -eq 0) { return $null }
        $profilesFull = [System.IO.Path]::GetFullPath($UserProfilesDir).TrimEnd('\','/')
        # The UserProfiles restore stops for a copy without a top-level *.xml (BACKUP_EMPTY), after the settings file was already changed.
        if ((Get-TpmTopLevelGameFileCount -Path $BackupPath) -eq 0) { return (New-TpmNoGamesResult) }
        $footprint = Get-TpmUserProfilesFootprint -UserProfilesDir $profilesFull
        $links = @($footprint.ReparsePoints)
        if ($links.Count -gt 0) { return (New-TpmLinkBlockedResult -Links $links) }
        # The UserProfiles restore first copies the current content into a temporary folder.
        $rollbackLength = Get-TpmLegacyRestoreRollbackPathLength
        $tooLong = (-not (Test-TpmPathLengthAllowed -Length $rollbackLength -Directory)) -or
            ($footprint.LongestDirectoryLength -gt 0 -and -not (Test-TpmPathLengthAllowed -Length ($rollbackLength + 1 + $footprint.LongestDirectoryLength) -Directory)) -or
            ($footprint.LongestFileLength -gt 0 -and -not (Test-TpmPathLengthAllowed -Length ($rollbackLength + 1 + $footprint.LongestFileLength)))
        if ($tooLong) {
            return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'PATH_TOO_LONG' -Summary 'Nothing was changed. A path inside UserProfiles would be too long for the temporary safety copy that the restore needs. Move TeknoParrot to a folder with a shorter path.')
        }
    } catch {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'CANNOT_READ_SETTINGS' -Summary (Get-TpmUnreadableFileSummary -Message $_.Exception.Message))
    }
    return $null
}

# Checked right before the UserProfiles restore starts. The safety copy takes
# time, so confirm once more that the game settings are still what it saved and
# that no link has appeared. Returns $null when all is well.
function Get-TpmRestoreAllLastMinuteProblem {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)]$SafetyRestorePoint)
    try {
        $now = @(Get-TpmUserProfilesBackupManifest -UserProfilesDir $UserProfilesDir -ProgressLabel 'Reset and Restore final check')
        if ((Get-TpmResetRestoreProfilesKey -Entries $now) -ne (Get-TpmResetRestoreProfilesKey -Entries @($SafetyRestorePoint.Record.Entries))) {
            return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'CHANGED_SINCE_PREVIEW' -Summary 'Your game settings changed while TeknoParrot Manager was preparing.')
        }
        $links = @((Get-TpmUserProfilesFootprint -UserProfilesDir $UserProfilesDir).ReparsePoints)
        if ($links.Count -gt 0) { return (New-TpmLinkBlockedResult -Links $links) }
    } catch {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'CANNOT_READ_SETTINGS' -Summary (Get-TpmUnreadableFileSummary -Message $_.Exception.Message))
    }
    return $null
}

# Puts back all game settings (and, when it differs, the TeknoParrot Manager
# settings file) from a restore point. The game settings use the existing
# verified UserProfiles restore transaction (rollback snapshot, byte check).
# A BeforeReset restore point is made first and kept. When the settings file
# was put back, TeknoParrot Manager must restart: Save-Config refuses to write
# the stale values it still holds in memory.
function Restore-TpmRestorePointAll {
    param(
        [Parameter(Mandatory)]$RestorePoint,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)]$Plan,
        [AllowEmptyString()][string]$ConfigPath = '',
        [string]$RestorePointsRoot = ''
    )
    $profilesFull = [System.IO.Path]::GetFullPath($UserProfilesDir).TrimEnd('\','/')
    $check = Test-TpmRestorePoint -RestorePoint $RestorePoint -UserProfilesDir $profilesFull
    if (-not $check.Valid) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'RESTORE_POINT_DAMAGED' -Summary ('Nothing was changed. This restore point cannot be used: {0}' -f $check.Reason))
    }
    $profilesChange = (@($Plan.Changes).Count + @($Plan.FoldersRemoved).Count + @($Plan.FoldersPutBack).Count) -gt 0
    $configChange = [string]$Plan.ConfigChange -eq 'Replace'
    if (-not $profilesChange -and -not $configChange) {
        return (New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'ALREADY_MATCHES' -Summary 'Nothing was changed. Everything already matches the restore point.')
    }
    $blocked = Get-TpmRestoreAllBlocker -Plan $Plan -UserProfilesDir $profilesFull -BackupPath $check.BackupPath
    if ($null -ne $blocked) { return $blocked }
    if (-not (Wait-TpmForProcessClose -ProcessNames @('TeknoParrotUi') -FriendlyName 'TeknoParrot')) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'APPLICATION_RUNNING' -Summary 'Nothing was changed because TeknoParrot is still open.')
    }
    $safety = New-TpmRestorePoint -UserProfilesDir $profilesFull -ConfigPath $ConfigPath -Kind 'BeforeReset' -RestorePointsRoot $RestorePointsRoot
    if (-not $safety.Succeeded) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'SAFETY_RESTORE_POINT_FAILED' -Summary ('Nothing was changed. TeknoParrot Manager could not first save a verified copy of your current settings. {0}' -f $safety.Reason))
    }
    $safetyKey = Get-TpmResetRestoreStateKey -Entries @($safety.RestorePoint.Record.Entries) -ConfigSha256 ([string]$safety.RestorePoint.Record.Config.Sha256)
    if ($safetyKey -ne [string]$Plan.CurrentStateKey) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'CHANGED_SINCE_PREVIEW' -Summary 'Nothing was changed. Your settings changed after the preview was shown. Open Reset and Restore again to see the new preview.' -SafetyRestorePoint $safety.Path)
    }
    if ($profilesChange) {
        # Checked before the settings file is touched: a game that changed while the safety copy was made must leave everything as it was.
        $early = Get-TpmRestoreAllLastMinuteProblem -UserProfilesDir $profilesFull -SafetyRestorePoint $safety.RestorePoint
        if ($null -ne $early) {
            $earlyCode = [string]$early.ReasonCode
            Write-Log ("Reset and Restore: stopped before anything was changed -- {0}" -f $earlyCode)
            $earlyText = [string]$early.Summary
            if (-not $earlyText.StartsWith('Nothing was changed.', [System.StringComparison]::Ordinal)) { $earlyText = 'Nothing was changed. ' + $earlyText }
            if ($earlyCode -eq 'CHANGED_SINCE_PREVIEW') { $earlyText += ' Open Reset and Restore again to see the new preview.' }
            return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode $earlyCode -Summary $earlyText -SafetyRestorePoint $safety.Path)
        }
    }

    $configReplaced = $false
    $placedConfig = @{}
    if ($configChange) {
        try {
            Restore-TpmRestorePointSettingsFile -SourceRestorePoint $RestorePoint -ConfigPath $ConfigPath -ExpectedCurrentSha256 ([string]$safety.RestorePoint.Record.Config.Sha256) -PlacedFile $placedConfig
            $configReplaced = $true
        } catch {
            $failure = $_.Exception.Message
            if ($_.Exception.Data.Contains('TpmNoChange')) {
                Write-Log ("Reset and Restore: the settings file was left as it was -- {0}" -f $failure)
                return (New-TpmNoChangeResult -Exception $_.Exception -SafetyRestorePoint $safety.Path)
            }
            if ($_.Exception.Data.Contains('TpmNewerKept')) {
                # A newer save is only in a named file, so nothing is undone over it.
                Write-Log ("Reset and Restore: the settings file changed while it was being put back -- {0}" -f $failure)
                $script:TpmConfigRestoreRestartRequired = $true
                return (New-TpmResetRestoreResult -Outcome 'ACTION_REQUIRED' -ReasonCode 'CHANGED_DURING_RESTORE' -Summary ('The TeknoParrot Manager settings file changed while TeknoParrot Manager was putting your old one back. Your newer file could not be put back, so it was kept as a separate file: {0} Copy it over the settings file if you want to keep the newer settings. A checked copy from just before is kept in: {1}' -f [string]$_.Exception.Data['TpmNewerKept'], $safety.Path) -SafetyRestorePoint $safety.Path -RestartRequired $true)
            }
            Write-Log ("Reset and Restore: putting back the settings file failed -- {0}" -f $failure)
            try {
                Undo-TpmRestorePointSettingsFile -SafetyRestorePoint $safety.RestorePoint -WrittenRestorePoint $RestorePoint -ConfigPath $ConfigPath -PlacedFile $placedConfig
                return (New-TpmResetRestoreResult -Outcome 'ROLLED_BACK_VERIFIED' -ReasonCode 'SETTINGS_RESTORE_FAILED_ROLLED_BACK' -Summary ('The TeknoParrot Manager settings could not be put back ({0}). They were returned to how they were just before and checked. Game settings were not changed.' -f $failure) -SafetyRestorePoint $safety.Path)
            } catch {
                $script:TpmConfigRestoreRestartRequired = $true
                return (New-TpmResetRestoreResult -Outcome 'ACTION_REQUIRED' -ReasonCode 'SETTINGS_ROLLBACK_FAILED' -Summary ('The TeknoParrot Manager settings could not be put back, and undoing the attempt also failed. A checked copy from just before is kept in: {0}' -f $safety.Path) -SafetyRestorePoint $safety.Path -RestartRequired $true)
            }
        }
    }

    if ($profilesChange) {
        # The settings file swap and the checks above take time: confirm once more, right before the restore, that nothing changed meanwhile.
        $profilesResult = Get-TpmRestoreAllLastMinuteProblem -UserProfilesDir $profilesFull -SafetyRestorePoint $safety.RestorePoint
        if ($null -eq $profilesResult) {
            $profilesResult = Invoke-RestoreBackup -userProfilesDir $profilesFull -SelectedBackupPath $check.BackupPath -AlreadyConfirmed
        }
        $profilesOutcome = [string]$profilesResult.Outcome
        if ($profilesOutcome -ne 'SUCCEEDED') {
            Write-Log ("Reset and Restore: the game settings restore reported {0} ({1})." -f $profilesOutcome, [string]$profilesResult.ReasonCode)
            $settingsBack = $true
            if ($configReplaced) {
                try { Undo-TpmRestorePointSettingsFile -SafetyRestorePoint $safety.RestorePoint -WrittenRestorePoint $RestorePoint -ConfigPath $ConfigPath -PlacedFile $placedConfig } catch { $settingsBack = $false }
            }
            if ($profilesOutcome -in @('FAILED_BEFORE_MUTATION','NO_OP','ROLLED_BACK_VERIFIED') -and $settingsBack) {
                $undoneOutcome = if ($configReplaced -or $profilesOutcome -eq 'ROLLED_BACK_VERIFIED') { 'ROLLED_BACK_VERIFIED' } else { 'FAILED_BEFORE_MUTATION' }
                return (New-TpmResetRestoreResult -Outcome $undoneOutcome -ReasonCode $(if ([string]$profilesResult.ReasonCode -in @('CHANGED_SINCE_PREVIEW','LINK_INSIDE_USERPROFILES','CANNOT_READ_SETTINGS')) { [string]$profilesResult.ReasonCode } else { 'PROFILES_RESTORE_NOT_COMPLETED' }) -Summary ('The game settings could not be put back: {0} Everything was left as it was just before.' -f [string]$profilesResult.Summary) -SafetyRestorePoint $safety.Path)
            }
            if ($configReplaced -and -not $settingsBack) { $script:TpmConfigRestoreRestartRequired = $true }
            return (New-TpmResetRestoreResult -Outcome 'ACTION_REQUIRED' -ReasonCode 'PROFILES_RESTORE_NEEDS_ATTENTION' -Summary ('The restore did not finish cleanly: {0} A checked copy of your game settings from just before is kept in: {1}' -f [string]$profilesResult.Summary, $safety.ProfilesBackupPath) -SafetyRestorePoint $safety.Path -RestartRequired ($configReplaced -and -not $settingsBack))
        }
    }
    if ($configReplaced) { $script:TpmConfigRestoreRestartRequired = $true }
    $changed = @(@($Plan.Changes) | ForEach-Object { [string]$_.RelativePath })
    if ($configReplaced) { $changed += 'TeknoParrot Manager settings' }
    Write-Log ("Reset and Restore: everything put back from restore point {0}; previous state kept in {1}." -f $RestorePoint.Id, $safety.Id)
    return (New-TpmResetRestoreResult -Outcome 'SUCCEEDED' -ReasonCode 'RESTORED' -Summary 'Everything was put back and checked byte for byte.' -ChangedItems $changed -SafetyRestorePoint $safety.Path -RestartRequired $configReplaced)
}

# Restore points that "Remove older restore points" may remove: never the
# first one (Baseline), never the newest KeepCount, never a damaged record. The
# one exception is a first restore point that was saved before any game existed
# (no games in it) once another first restore point with games exists: it is
# then an ordinary restore point.
function Get-TpmRestorePointRemovalCandidates {
    param([object[]]$RestorePoints = @(), [int]$KeepCount = (Get-TpmRestorePointKeepCount), [string]$UserProfilesDir = '')
    $pool = @($RestorePoints)
    # With a folder given, only restore points made for that folder can be candidates (and count toward KeepCount).
    if (-not [string]::IsNullOrWhiteSpace($UserProfilesDir)) { $pool = @((Select-TpmRestorePointsForFolder -RestorePoints $pool -UserProfilesDir $UserProfilesDir).Current) }
    $readable = @($pool | Where-Object { $null -ne $_ -and [bool]$_.Readable })
    $gamesBaselineExists = @($readable | Where-Object { [string]$_.Kind -eq 'Baseline' -and (Test-TpmRestorePointRecordHasGames -RestorePoint $_) }).Count -gt 0
    $others = @($readable | Where-Object { [string]$_.Kind -ne 'Baseline' -or ($gamesBaselineExists -and -not (Test-TpmRestorePointRecordHasGames -RestorePoint $_)) } | Sort-Object -Property @{ Expression = { $_.CreatedUtc }; Descending = $true })
    if ($others.Count -le $KeepCount) { return @() }
    return @($others | Select-Object -Skip $KeepCount)
}

# Removes one restore point and its game settings copy, only with proof that
# TeknoParrot Manager made them for it (record, folder name, completion record).
function Remove-TpmRestorePoint {
    param([Parameter(Mandatory)]$RestorePoint, [Parameter(Mandatory)][string]$UserProfilesDir, [switch]$AllowEmptyBaseline)
    # A first restore point is kept. With -AllowEmptyBaseline (the caller has seen another first restore point with games) one without any game may go.
    if (-not [bool]$RestorePoint.Readable -or ([string]$RestorePoint.Kind -eq 'Baseline' -and (-not $AllowEmptyBaseline -or (Test-TpmRestorePointRecordHasGames -RestorePoint $RestorePoint)))) { return [pscustomobject]@{ Removed = $false; Reason = 'This restore point is kept.' } }
    $record = $RestorePoint.Record
    $profilesFull = [System.IO.Path]::GetFullPath($UserProfilesDir).TrimEnd('\','/')
    if (([string]$record.UserProfilesDir).TrimEnd('\','/') -ine $profilesFull) { return [pscustomobject]@{ Removed = $false; Reason = 'It belongs to a different TeknoParrot folder.' } }
    $leaf = [string]$record.UserProfilesBackup
    if ([string]::IsNullOrWhiteSpace($leaf) -or $leaf -ne [System.IO.Path]::GetFileName($leaf) -or $leaf -match '\.\.' -or -not $leaf.StartsWith(([string]$record.Kind + '_'), [System.StringComparison]::Ordinal)) {
        return [pscustomobject]@{ Removed = $false; Reason = 'Its record names an unexpected backup folder.' }
    }
    $backupPath = Join-Path (Join-Path $profilesFull 'FullBackup') $leaf
    $backupExists = Test-Path -LiteralPath $backupPath -PathType Container
    if ($backupExists) {
        if (-not (Test-TpmNoReparsePath -Path $backupPath)) { return [pscustomobject]@{ Removed = $false; Reason = 'Its backup folder failed the safety check.' } }
        if ((Get-TpmUserProfilesBackupProducer -BackupPath $backupPath) -cne [string]$record.Kind) { return [pscustomobject]@{ Removed = $false; Reason = 'Its backup folder was not made for this restore point.' } }
    }
    if (-not (Test-TpmNoReparsePath -Path ([string]$RestorePoint.Path))) { return [pscustomobject]@{ Removed = $false; Reason = 'Its folder failed the safety check.' } }
    try {
        # The backup goes first: the record is what lists the restore point, so it is never removed while its backup may still be there.
        if ($backupExists) { Remove-Item -LiteralPath $backupPath -Recurse -Force -ErrorAction Stop }
        Remove-Item -LiteralPath ([string]$RestorePoint.Path) -Recurse -Force -ErrorAction Stop
        Write-Log ("Reset and Restore: removed older restore point {0} on request." -f $RestorePoint.Id)
        return [pscustomobject]@{ Removed = $true; Reason = $null }
    } catch {
        Write-Log ("Reset and Restore: removing restore point {0} did not finish -- {1}" -f $RestorePoint.Id, $_.Exception.Message)
        return [pscustomobject]@{ Removed = $false; Reason = 'Some of its files could not be removed.' }
    }
}

# Start-up restore point: reuse the newest one when nothing changed since
# (after checking it), otherwise make a new one. Only restore points made for
# this UserProfiles folder count; those made for another folder are left alone.
# The first one is the Baseline. It counts only while its saved copy passes its
# check and has at least one game settings file (top-level *.xml): otherwise a
# new Baseline is made (an empty one once games exist) and the old record is
# kept as an ordinary restore point. A copy that cannot be read right now (in
# use by another program) proves nothing: no new Baseline is made for it and
# start-up goes on. Never prompts and never throws.
function Invoke-TpmStartupRestorePoint {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][AllowEmptyString()][string]$ConfigPath,
        [string]$RestorePointsRoot = ''
    )
    try {
        if ([string]::IsNullOrWhiteSpace($RestorePointsRoot)) { $RestorePointsRoot = Get-TpmRestorePointsRoot }
        $profilesFull = [System.IO.Path]::GetFullPath($UserProfilesDir).TrimEnd('\','/')
        $sets = Select-TpmRestorePointsForFolder -RestorePoints @(Get-TpmRestorePoints -RestorePointsRoot $RestorePointsRoot) -UserProfilesDir $profilesFull
        $usable = @($sets.Current)
        $verdicts = @{}
        $hasBaseline = $false
        $emptyBaseline = $false
        $baselineUnchecked = $false
        foreach ($candidate in @($usable | Where-Object { [string]$_.Kind -eq 'Baseline' } | Sort-Object -Property CreatedUtc)) {
            $verdict = Test-TpmRestorePoint -RestorePoint $candidate -UserProfilesDir $profilesFull
            $verdicts[[string]$candidate.Path] = $verdict
            if ($verdict.Valid) {
                if ((Get-TpmTopLevelGameFileCount -Path ([string]$verdict.BackupPath)) -gt 0) { $hasBaseline = $true; break }
                $emptyBaseline = $true
                Write-Log ("Restore point: the first restore point {0} has no game settings files; it is kept as an ordinary restore point." -f $candidate.Id)
                continue
            }
            if ([bool]$verdict.CouldNotCheck) {
                $baselineUnchecked = $true
                Write-Log ("Restore point: the first restore point {0} could not be checked right now ({1}); no new first restore point is made." -f $candidate.Id, $verdict.Reason)
                continue
            }
            Write-Log ("Restore point: the first restore point {0} cannot be used ({1}); a new first restore point is made." -f $candidate.Id, $verdict.Reason)
        }
        if (-not $hasBaseline) {
            if ($baselineUnchecked) {
                # It may be the good one: never replace what could not be checked.
                $hasBaseline = $true
            } elseif ($emptyBaseline -and (Get-TpmTopLevelGameFileCount -Path $profilesFull) -eq 0) {
                # Nothing to save yet: a new first restore point would be empty too.
                $hasBaseline = $true
            }
        }
        $result = $null
        if ($hasBaseline) {
            $newest = $usable[0]
            $current = @(Get-TpmUserProfilesBackupManifest -UserProfilesDir $profilesFull -ProgressLabel 'Start-up restore point check')
            $configNow = Get-TpmRestorePointFileState -Path $ConfigPath
            $sameConfigPath = [string]::IsNullOrWhiteSpace($ConfigPath) -or ([string]$newest.Record.Config.SourcePath) -ieq [System.IO.Path]::GetFullPath($ConfigPath)
            $currentKey = Get-TpmResetRestoreStateKey -Entries $current -ConfigSha256 ([string]$configNow.Sha256)
            $newestKey = Get-TpmResetRestoreStateKey -Entries @($newest.Record.Entries) -ConfigSha256 ([string]$newest.Record.Config.Sha256)
            if ($sameConfigPath -and $currentKey -eq $newestKey) {
                $newestCheck = if ($verdicts.ContainsKey([string]$newest.Path)) { $verdicts[[string]$newest.Path] } else { Test-TpmRestorePoint -RestorePoint $newest -UserProfilesDir $profilesFull }
                if ($newestCheck.Valid) {
                    Write-Log ("Restore point: nothing changed since {0}; it was checked and is reused." -f $newest.Id)
                    $result = [pscustomobject]@{ Succeeded = $true; Created = $false; Reused = $true; Kind = [string]$newest.Kind; Path = [string]$newest.Path; Reason = $null; RemovableCount = 0 }
                } else {
                    Write-Log ("Restore point: {0} failed its check ({1}); a new one is made." -f $newest.Id, $newestCheck.Reason)
                }
            }
        }
        if ($null -eq $result) {
            $kind = if ($hasBaseline) { 'Startup' } else { 'Baseline' }
            $created = New-TpmRestorePoint -UserProfilesDir $profilesFull -ConfigPath $ConfigPath -Kind $kind -RestorePointsRoot $RestorePointsRoot
            if (-not $created.Succeeded) {
                return [pscustomobject]@{ Succeeded = $false; Created = $false; Reused = $false; Kind = $kind; Path = $null; Reason = [string]$created.Reason; RemovableCount = 0 }
            }
            $result = [pscustomobject]@{ Succeeded = $true; Created = $true; Reused = $false; Kind = $kind; Path = [string]$created.Path; Reason = $null; RemovableCount = 0 }
        }
        try {
            $afterSets = Select-TpmRestorePointsForFolder -RestorePoints @(Get-TpmRestorePoints -RestorePointsRoot $RestorePointsRoot) -UserProfilesDir $profilesFull
            $result.RemovableCount = @(Get-TpmRestorePointRemovalCandidates -RestorePoints @($afterSets.Current)).Count
        } catch {
            $result.RemovableCount = 0
        }
        return $result
    } catch {
        Write-Log ("Restore point: the start-up restore point could not be made -- {0}" -f $_.Exception.Message)
        return [pscustomobject]@{ Succeeded = $false; Created = $false; Reused = $false; Kind = $null; Path = $null; Reason = $_.Exception.Message; RemovableCount = 0 }
    }
}

# Console width for the restore point text. Falls back to 80 when the width
# helper is not available, so a message is never lost to a missing helper.
function Get-TpmResetRestoreLineWidth {
    $width = 80
    if (Get-Command -Name Get-ConsoleContentWidth -CommandType Function -ErrorAction SilentlyContinue) {
        try { $width = [int](Get-ConsoleContentWidth) } catch { $width = 80 }
    }
    return [Math]::Max(20, $width)
}

# =============================================================================
# SHARED READABILITY HELPERS (FIX66)
# =============================================================================
# One way to write a short, plain screen. Default view = short summary; every
# technical fact stays reachable through the Details key and stays in the log.
# All text is wrapped to the current console width (re-measured on every call,
# so text printed after a resize uses the new width) and is ASCII only.
#
# Write-TpmText: wrapped paragraph. A wrapped line continues under HangingIndent
# extra spaces (and under Prefix, when one is given), so list items and
# "Label : value" rows keep their alignment. MaxWidth caps the line width (0 = no
# cap, the console width is used). BreakLongWords cuts a word that is wider than
# the line (a long path) instead of letting it run past the edge. When the wrapping
# helper is missing the text is written as it is.
function Write-TpmText {
    param(
        [AllowEmptyString()][string]$Text,
        [string]$Color = '',
        [int]$Indent = 2,
        [int]$HangingIndent = 0,
        [string]$Prefix = '',
        [switch]$BlankBefore,
        [switch]$BlankAfter,
        [int]$MaxWidth = 100,
        [switch]$BreakLongWords
    )
    # An unknown color name is not an error: the line is written in the default color.
    $Color = [string](@([System.Enum]::GetNames([System.ConsoleColor])) | Where-Object { $_ -ieq $Color.Trim() } | Select-Object -First 1)
    $pad = ' ' * [Math]::Max(0, $Indent)
    $hang = ' ' * [Math]::Max(0, $HangingIndent)
    $consoleWidth = Get-TpmResetRestoreLineWidth
    $cap = if ($MaxWidth -gt 0) { [Math]::Min($consoleWidth, $MaxWidth) } else { $consoleWidth }
    $textWidth = [Math]::Max(20, $cap - $pad.Length - $hang.Length - $Prefix.Length - 1)
    $lines = if ([string]::IsNullOrWhiteSpace($Text)) { @() } else { @($Text) }
    if (Get-Command -Name Split-TextForMenuWidth -CommandType Function -ErrorAction SilentlyContinue) {
        $lines = Split-TextForMenuWidth -Text $Text -Width $textWidth
    }
    if ($BreakLongWords) {
        $broken = New-Object System.Collections.Generic.List[string]
        foreach ($line in $lines) {
            $rest = [string]$line
            while ($rest.Length -gt $textWidth) {
                # A path is cut after its last folder separator in the second half of the line, otherwise at the line end.
                $cut = $textWidth
                $slash = [Math]::Max($rest.LastIndexOf('\', $textWidth - 1, $textWidth), $rest.LastIndexOf('/', $textWidth - 1, $textWidth))
                if ($slash -ge [int]($textWidth / 2)) { $cut = $slash + 1 }
                [void]$broken.Add($rest.Substring(0, $cut))
                $rest = $rest.Substring($cut)
            }
            if ($rest.Length -gt 0) { [void]$broken.Add($rest) }
        }
        $lines = $broken.ToArray()
    }
    if (@($lines).Count -eq 0 -and $Prefix.Trim().Length -gt 0) { $lines = @('') }
    if ($BlankBefore) { Write-Host '' }
    $prefixPad = ' ' * $Prefix.Length
    $first = $true
    foreach ($line in $lines) {
        $out = if ($first) { $pad + $Prefix + $line } else { $pad + $hang + $prefixPad + $line }
        $out = $out.TrimEnd()
        $first = $false
        if ($Color) { Write-Host $out -ForegroundColor $Color } else { Write-Host $out }
    }
    if ($BlankAfter) { Write-Host '' }
}

# The Reset and Restore text writer. It is the general writer with the console
# width as its only cap, exactly as before.
# Differs from Write-TpmText only in the width cap: Write-TpmText stops at 100 columns, this one at the console width.
function Write-TpmResetRestoreText {
    param([AllowEmptyString()][string]$Text, [string]$Color = '', [int]$Indent = 2, [int]$HangingIndent = 0)
    Write-TpmText -Text $Text -Color $Color -Indent $Indent -HangingIndent $HangingIndent -MaxWidth 0
}

# False when nobody can answer a question: an unattended run, or input that is
# redirected (piped answers must not be used up by an optional Details question).
function Test-TpmInteractiveInput {
    param([switch]$Unattended)
    if ($Unattended) { return $false }
    try { return (-not [Console]::IsInputRedirected) } catch { return $false }
}

# "1 patch" / "3 patches": a count with the right singular or plural noun. Plural defaults to the singular plus "s"
# ("es" after s, x, z, ch and sh). Modifier is a word between the number and the noun: "3 more games".
function Format-TpmCountNoun {
    param([int]$Count, [Parameter(Mandatory)][string]$Singular, [string]$Plural = '', [string]$Modifier = '')
    $number = if ($Modifier) { '{0} {1}' -f $Count, $Modifier } else { '{0}' -f $Count }
    if ($Count -eq 1) { return ('{0} {1}' -f $number, $Singular) }
    $word = if ($Plural) { $Plural } elseif ($Singular -match '(s|x|z|ch|sh)$') { $Singular + 'es' } else { $Singular + 's' }
    return ('{0} {1}' -f $number, $word)
}

# Names for one screen line: "A, B and C", or "A, B, C and 4 more" when there are more than Limit names (Limit is 5 unless
# the caller says otherwise; -Max is the same parameter). The whole list belongs in the details. WhenEmpty is returned for an empty list.
function Format-TpmNameList {
    param([string[]]$Names, [Alias('Max')][int]$Limit = 5, [string]$WhenEmpty = '')
    $list = @($Names | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if ($list.Count -eq 0) { return $WhenEmpty }
    # "and 1 more" saves no space and hides a game, so one extra name is shown.
    if ($list.Count -le ($Limit + 1)) { return (Join-TpmPostgresSetupNames -Names $list) }
    return ('{0} and {1} more' -f (@($list | Select-Object -First $Limit) -join ', '), ($list.Count - $Limit))
}

# One "Label : value" row. The value wraps under itself (a long path is cut at the line end). On a console too
# narrow to leave room for the value beside the label, the label goes on its own line and the value is
# indented below it, so no line is ever wider than the console.
function Write-TpmLabelValue {
    param([Parameter(Mandatory)][string]$Prefix, [AllowEmptyString()][string]$Text, [int]$Indent = 4, [string]$Color = '')
    $room = [Math]::Min((Get-TpmResetRestoreLineWidth), 100) - $Indent - $Prefix.Length - 1
    if ($room -ge 20) {
        Write-TpmText -Text $Text -Prefix $Prefix -Indent $Indent -Color $Color -BreakLongWords
        return
    }
    Write-TpmText -Text $Prefix.Trim() -Indent $Indent -Color $Color
    Write-TpmText -Text $Text -Indent ($Indent + 2) -Color $Color -BreakLongWords
}

# Details view: one short block per item. A block is @{ Heading = 'text'; Lines = @('Label: text', ...) }
# with an optional Color. "Label: text" lines are aligned in columns inside a block and wrap under
# their text. Note is a common sentence that is stated once, at the top.
function Show-TpmDetailBlocks {
    param([object[]]$Blocks = @(), [string]$Note = '', [string]$HeadingColor = 'Cyan')
    if (-not [string]::IsNullOrWhiteSpace($Note)) {
        Write-Host ''
        Write-TpmText -Text $Note -Color DarkGray -Indent 2
    }
    foreach ($block in @($Blocks)) {
        if ($null -eq $block) { continue }
        $heading = [string](Get-TpmTransactionField -Object $block -Name 'Heading' -Default '')
        $color = [string](Get-TpmTransactionField -Object $block -Name 'Color' -Default '')
        $parsed = New-Object System.Collections.Generic.List[object]
        foreach ($line in @(Get-TpmTransactionField -Object $block -Name 'Lines' -Default @())) {
            $lineText = [string]$line
            if ([string]::IsNullOrWhiteSpace($lineText)) { continue }
            $match = [regex]::Match($lineText, '^([A-Za-z][A-Za-z0-9 /()'']{0,28}):\s+(\S.*)$')
            if ($match.Success) {
                [void]$parsed.Add([pscustomobject]@{ Label = $match.Groups[1].Value; Text = $match.Groups[2].Value })
            } else {
                [void]$parsed.Add([pscustomobject]@{ Label = ''; Text = $lineText })
            }
        }
        $labelWidth = 0
        foreach ($item in $parsed) { if ($item.Label.Length -gt $labelWidth) { $labelWidth = [Math]::Min(24, $item.Label.Length) } }
        Write-Host ''
        if ($heading) { Write-TpmText -Text $heading -Color $HeadingColor -Indent 2 }
        foreach ($item in $parsed) {
            if ($item.Label) {
                # The space after the colon is part of the padded text, so a label wider than the column is still followed by a space.
                Write-TpmLabelValue -Prefix (($item.Label + ': ').PadRight($labelWidth + 2)) -Text $item.Text -Indent 4 -Color $color
            } else {
                Write-TpmText -Text $item.Text -Indent 4 -HangingIndent 2 -Color $color -BreakLongWords
            }
        }
    }
    Write-Host ''
}

# One "Label: text" line for a details block. It is left out when there is no text, so a block never shows an empty label.
function Add-TpmDetailLine {
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][System.Collections.Generic.List[string]]$Lines,
        [Parameter(Mandatory)][string]$Label,
        [AllowNull()][AllowEmptyString()][string]$Text
    )
    if ([string]::IsNullOrWhiteSpace($Text)) { return }
    [void]$Lines.Add(('{0}: {1}' -f $Label, $Text.Trim()))
}

# The plain sentence for a result's reason code, added to a list of "needs your attention" lines. It is added when the code is known
# (the cause is worth saying), or when nothing else explains the problem. The code itself stays in the Details view and the log.
function Add-TpmPlainReasonLine {
    param([Parameter(Mandatory)][AllowEmptyCollection()][System.Collections.Generic.List[string]]$Lines, [AllowNull()][AllowEmptyString()][string]$Code)
    $reason = Get-TpmPlainReason -Code $Code
    if ($reason.Known -or $Lines.Count -eq 0) { [void]$Lines.Add($reason.Text) }
}

# End-of-step result lines that every setup step shares (patches, dgVoodoo2, BepInEx, GPU fix).
# "You selected 4 games: 3 changed, 1 skipped." Only the counts that apply are shown. A game that is in none of the counts is
# shown as "not finished", so the parts always add up to the games selected.
function Get-TpmStepCountsLine {
    param([int]$Picked, [int]$Changed = 0, [int]$AlreadySetUp = 0, [int]$Skipped = 0, [int]$Failed = 0, [string]$ChangedWord = 'changed', [string]$AlreadyWord = 'already set up')
    if ($Picked -le 0) { return '' }
    $parts = New-Object System.Collections.Generic.List[string]
    if ($Changed -gt 0) { [void]$parts.Add(('{0} {1}' -f $Changed, $ChangedWord)) }
    if ($AlreadySetUp -gt 0) { [void]$parts.Add(('{0} {1}' -f $AlreadySetUp, $AlreadyWord)) }
    if ($Skipped -gt 0) { [void]$parts.Add(('{0} skipped' -f $Skipped)) }
    if ($Failed -gt 0) { [void]$parts.Add(('{0} failed' -f $Failed)) }
    $left = $Picked - $Changed - $AlreadySetUp - $Skipped - $Failed
    if ($left -gt 0) { [void]$parts.Add(('{0} not finished' -f $left)) }
    return ('You selected {0}: {1}.' -f (Format-TpmGameCount -Count $Picked), ($parts -join ', '))
}

# The same line, counted from the item lists of a step result. Each selected game is counted once: changed, then skipped, then failed
# (a game whose state could not be checked counts as failed), then already set up.
function Get-TpmResultCountsLine {
    param($Result, [string[]]$Picked = @(), [string]$ChangedWord = 'changed', [string]$AlreadyWord = 'already set up')
    $pickedList = @($Picked | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique)
    if ($pickedList.Count -eq 0) { return '' }
    $take = {
        param([string]$Name, [string[]]$Exclude)
        @(Get-TpmTransactionField -Object $Result -Name $Name -Default @() | Where-Object { $_ -in $pickedList -and $_ -notin $Exclude } | Select-Object -Unique)
    }
    $changed = @(& $take 'ChangedItems' @())
    $skipped = @(& $take 'SkippedItems' $changed)
    $failed = @(& $take 'FailedItems' (@($changed) + @($skipped)))
    $failed = @($failed) + @(& $take 'UnknownItems' (@($changed) + @($skipped) + @($failed)))
    $already = @(& $take 'CompletedItems' (@($changed) + @($skipped) + @($failed)))
    return (Get-TpmStepCountsLine -Picked $pickedList.Count -Changed $changed.Count -AlreadySetUp $already.Count -Skipped $skipped.Count -Failed $failed.Count -ChangedWord $ChangedWord -AlreadyWord $AlreadyWord)
}

# Where the backup of a step is: the full path of the folder, in plain words. The backup folder of a transaction result is read from it;
# folders a step knows about itself are added with -ExtraPaths. Returns '' when the step made no backup (nothing is claimed then).
function Get-TpmBackupFolderLine {
    param($Result = $null, [string[]]$ExtraPaths = @(), [string]$What = 'your files')
    $paths = New-Object System.Collections.Generic.List[string]
    $own = [string](Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'Backup') -Name 'RootPath' -Default '')
    $nested = [string](Get-TpmTransactionField -Object (Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $Result -Name 'TransactionResult') -Name 'Backup') -Name 'RootPath' -Default '')
    foreach ($candidate in (@($own, $nested) + @($ExtraPaths))) {
        if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
        if (-not $paths.Contains($candidate.Trim())) { [void]$paths.Add($candidate.Trim()) }
    }
    if ($paths.Count -eq 0) { return '' }
    if ($paths.Count -eq 1) { return ('A backup of {0} is saved in this folder: {1}' -f $What, $paths[0]) }
    return ('Backups of {0} are saved in these folders: {1}' -f $What, (Format-TpmNameList -Names $paths.ToArray() -Limit 3))
}

# The one plain line at the end of a step that skipped games because their drive is not connected.
function Get-TpmDriveSkipNext {
    return 'Connect the drive, or choose 13 (Library health check) in the main menu to repair these games.'
}

# Which games from a numbered list: typed numbers (1,3,6), ranges (1-8) or A for all of them. Returns the chosen 0-based row numbers, or
# nothing for B or Enter. An answer that cannot be read is told so and asked again.
function Read-TpmMultiGameChoice {
    param([Parameter(Mandatory)][string[]]$Rows, [string]$Heading = '', [string]$Prompt = '  Type numbers like 1,3,6 or a range like 1-8, A for all, or B for none')
    $rowList = @($Rows)
    if ($rowList.Count -eq 0) { return @() }
    Write-Host ''
    if ($Heading) { Write-TpmText -Text $Heading -Color Cyan }
    for ($index = 0; $index -lt $rowList.Count; $index++) {
        $prefix = '{0}) ' -f ($index + 1)
        Write-TpmText -Text ($prefix + $rowList[$index]) -Indent 4 -HangingIndent $prefix.Length
    }
    while ($true) {
        $answer = ([string](Read-HostSafe $Prompt)).Trim().ToUpperInvariant()
        if ($answer -eq '' -or $answer -eq 'B') { return @() }
        if ($answer -eq 'A') { return @(0..($rowList.Count - 1)) }
        # Expand-NumberList returns its list as one array object; it is read without @() so an empty answer counts as no numbers.
        $numbers = Expand-NumberList -str $answer -max $rowList.Count
        if ($numbers.Count -gt 0) { return @($numbers | Sort-Object -Unique | ForEach-Object { $_ - 1 }) }
        Write-TpmText -Text 'That is not a number in the list.' -Color Yellow
    }
}

# The Action Required follow-up lines of a run, put under one short heading per feature, so a long list is not one mixed pile.
# A line that starts with a feature name opens that feature's group; any other line (for example the steps of a numbered list) stays with the line before it.
function Get-TpmActionRequiredGroups {
    param([string[]]$Lines = @())
    $features = @(
        @('Drive not connected', '^Drive not connected'),
        @('Registration and unpacking', '^(Registration|AutoSync)\b'),
        @('Patches', '^(Patch|Patches|Required patch|Required patches)\b'),
        @('BepInEx', '^BepInEx\b'),
        @('dgVoodoo2', '^dgVoodoo2\b'),
        @('ReShade', '^ReShade\b'),
        @('Crosshairs', '^Crosshairs?\b'),
        @('GPU fix', '^GPU\b'),
        @('TeknoParrot first-time setup', '^TeknoParrot has its own first-time setup')
    )
    $buckets = [ordered]@{}
    foreach ($feature in $features) { $buckets[[string]$feature[0]] = New-Object System.Collections.Generic.List[string] }
    $buckets['Other'] = New-Object System.Collections.Generic.List[string]
    $current = ''
    foreach ($line in @($Lines)) {
        if ([string]::IsNullOrWhiteSpace($line)) { continue }
        foreach ($feature in $features) {
            if ([regex]::IsMatch($line, [string]$feature[1])) { $current = [string]$feature[0]; break }
        }
        if ($current -eq '') { $current = 'Other' }
        [void]$buckets[$current].Add($line)
    }
    $groups = New-Object System.Collections.Generic.List[object]
    foreach ($heading in $buckets.Keys) {
        if ($buckets[$heading].Count -gt 0) { [void]$groups.Add([pscustomobject]@{ Heading = [string]$heading; Lines = $buckets[$heading].ToArray() }) }
    }
    return $groups.ToArray()
}


# One question with a Details key. D shows the detail blocks and asks again; any other answer is returned
# trimmed and in upper case. With no blocks a D is an ordinary answer. The question is always asked (one
# Read-HostSafe call), so piped answers are used up exactly as they were before a Details key existed.
# The loop only repeats after a typed D; an empty or missing answer (input that has ended) is returned as '' and never repeats.
# Differs from Read-TpmResetRestoreAnswer: no intro text, the prompt is used as given, and the answer comes back trimmed and in upper case.
function Read-TpmAnswerWithDetails {
    param([Parameter(Mandatory)][string]$Prompt, [object[]]$DetailBlocks = @(), [string]$DetailsNote = '')
    while ($true) {
        $answer = ([string](Read-HostSafe $Prompt)).Trim().ToUpperInvariant()
        if ($answer -cne 'D' -or @($DetailBlocks).Count -eq 0) { return $answer }
        Show-TpmDetailBlocks -Blocks $DetailBlocks -Note $DetailsNote
    }
}

# The detail blocks of a screen as log lines, one line per detail line, so the log holds everything the screen hides.
function Write-TpmDetailBlocksLog {
    param([object[]]$Blocks = @(), [Parameter(Mandatory)][string]$Prefix)
    foreach ($block in @($Blocks)) {
        if ($null -eq $block) { continue }
        $heading = [string](Get-TpmTransactionField -Object $block -Name 'Heading' -Default '')
        foreach ($line in @(Get-TpmTransactionField -Object $block -Name 'Lines' -Default @())) {
            if (-not [string]::IsNullOrWhiteSpace([string]$line)) { Write-Log ('{0} [{1}]: {2}' -f $Prefix, $heading, [string]$line) }
        }
    }
}

# One "choose a number" question over a list of rows. The first Visible rows are shown; M shows the rest and D shows
# the detail blocks (when there are any). Returns the 0-based index of the chosen row, or -1 for back (B or Enter).
# Row numbers never change when more rows are shown. The prompt is the caller's own short line.
# Differs from Show-TpmReShadeUndoMenu and Read-TpmRequiredPatchGameChoice: it only picks a row and returns its index, and it pages with M.
function Read-TpmNumberedListChoice {
    param(
        [Parameter(Mandatory)][string[]]$Rows,
        [Parameter(Mandatory)][string]$Prompt,
        [string]$Heading = '',
        [object[]]$DetailBlocks = @(),
        [string]$DetailsNote = '',
        [int]$Visible = 5
    )
    $rowList = @($Rows)
    $hasDetails = (@($DetailBlocks | Where-Object { $null -ne $_ }).Count -gt 0)
    $showAll = $false
    while ($true) {
        $shown = if ($showAll) { $rowList.Count } else { [Math]::Min([Math]::Max(1, $Visible), $rowList.Count) }
        Write-Host ''
        if ($Heading) {
            Write-TpmResetRestoreText -Text $Heading -Color Cyan
            Write-Host ''
        }
        for ($index = 0; $index -lt $shown; $index++) {
            $prefix = '{0}) ' -f ($index + 1)
            Write-TpmResetRestoreText -Text ($prefix + $rowList[$index]) -Indent 4 -HangingIndent $prefix.Length
        }
        $choices = New-Object System.Collections.Generic.List[string]
        [void]$choices.Add('B')
        for ($index = 1; $index -le $shown; $index++) { [void]$choices.Add([string]$index) }
        $moreRows = ($shown -lt $rowList.Count)
        if ($moreRows -or $hasDetails) { Write-Host '' }
        if ($moreRows) {
            Write-TpmResetRestoreText -Text ('M) Show {0} more' -f ($rowList.Count - $shown)) -Indent 4 -HangingIndent 3
            [void]$choices.Add('M')
        }
        if ($hasDetails) {
            Write-TpmResetRestoreText -Text 'D) Details' -Indent 4 -HangingIndent 3
            [void]$choices.Add('D')
        }
        $choice = Read-TpmChoice -Prompt $Prompt -Choices $choices.ToArray() -Default 'B'
        if ($choice -eq 'D') { Show-TpmDetailBlocks -Blocks $DetailBlocks -Note $DetailsNote; continue }
        if ($choice -eq 'M') { $showAll = $true; continue }
        if ($choice -eq 'B') { return -1 }
        return ([int]$choice - 1)
    }
}


# FIX98: a run that goes straight on from one screen to the next (registration) does not stop at every screen to ask for Details.
# Write-TpmOutcome -DeferDetails keeps each screen's detail blocks here (interactive runs only); the run's own final
# "return to menu" prompt offers them once, through Read-TpmReturnToMenu. The log already has every block.

# The kept screens as a flat list. Get-Variable hands an array back as ONE object, so reading it straight into @() made an
# empty list count as one entry and two screens read as one; returning the value from a function unrolls it correctly.
function Get-TpmDeferredDetails {
    $kept = Get-Variable -Name TpmDeferredDetails -Scope Script -ValueOnly -ErrorAction SilentlyContinue
    if ($null -eq $kept) { return @() }
    return @($kept)
}

function Add-TpmDeferredDetails {
    param([object[]]$Blocks = @(), [string]$Note = '')
    $script:TpmDeferredDetails = @(Get-TpmDeferredDetails) + @([pscustomobject]@{ Blocks = @($Blocks); Note = $Note })
}

function Clear-TpmDeferredDetails {
    $script:TpmDeferredDetails = @()
}

# FIX110 (S-11): shows kept screen details (the entries Get-TpmDeferredDetails returned) one after the other and forgets them,
# so the same details are not offered a second time at the final return prompt.
function Show-TpmDeferredDetails {
    param([object[]]$Entries = @())
    Clear-TpmDeferredDetails
    foreach ($entry in @($Entries)) { Show-TpmDetailBlocks -Blocks @($entry.Blocks) -Note ([string]$entry.Note) }
}

# The final prompt of a run: Enter returns to the menu. When screens kept their details, D shows them first (once).
function Read-TpmReturnToMenu {
    $pending = @(Get-TpmDeferredDetails)
    Clear-TpmDeferredDetails
    if ($pending.Count -eq 0) { [void](Read-HostSafe '  Press Enter to return to menu'); return }
    $answer = [string](Read-HostSafe '  [D] Details, or press Enter to return to menu')
    if ($answer.Trim() -ine 'D') { return }
    Show-TpmDeferredDetails -Entries $pending
    [void](Read-HostSafe '  Press Enter to return to menu')
}

# The shared result screen. Prints at most: a blank line, the status line, up to 3
# bullets (more collapse into "... and N more"), one "Not changed" line, the items
# that need attention (only when there are some, at most 5, after a blank line), a blank line, the
# Next line, a blank line and the Details question. The full text, including
# every detail line, is ALWAYS written to the log. Details (DetailsKey, one
# keypress and Enter) shows the detail blocks; bullets or attention items that
# were collapsed are added to the details automatically. With -Unattended or
# redirected input nothing is asked and the details are only logged. With -DeferDetails an interactive run asks
# nothing here either: the details wait for Read-TpmReturnToMenu at the end of the run.
# Status: Ok = green, Attention = yellow, Problem = red. An empty Title prints no
# status line. Nothing is returned unless -PassThru is given; then the result is
# @{ DetailsAvailable; DetailsShown }, so the object never leaks into the caller's output.
function Write-TpmOutcome {
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Title,
        [ValidateSet('Ok', 'Attention', 'Problem')][string]$Status = 'Ok',
        [string[]]$Done = @(),
        [string]$NotChanged = '',
        [string[]]$Needs = @(),
        [string]$Next = '',
        [object[]]$DetailBlocks = @(),
        [string]$DetailsKey = 'D',
        [string]$DetailsNote = '',
        [switch]$Unattended,
        [switch]$PassThru,
        [switch]$Spaced,
        [switch]$DeferDetails
    )
    $maxDone = 3
    $maxNeeds = 5
    $doneItems = @(@($Done) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    $needItems = @(@($Needs) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    $blocks = New-Object System.Collections.Generic.List[object]
    if ($doneItems.Count -gt $maxDone) { [void]$blocks.Add(@{ Heading = 'Everything that was done'; Lines = @($doneItems) }) }
    if ($needItems.Count -gt $maxNeeds) { [void]$blocks.Add(@{ Heading = 'Everything that needs your attention'; Lines = @($needItems) }) }
    foreach ($block in @($DetailBlocks)) { if ($null -ne $block) { [void]$blocks.Add($block) } }

    # The log always gets the whole text, whether or not the details are opened.
    $hasTitle = -not [string]::IsNullOrWhiteSpace($Title)
    if ($hasTitle) { Write-Log ('Result [{0}]: {1}' -f $Status, $Title) }
    foreach ($item in $doneItems) { Write-Log ('Result done: {0}' -f $item) }
    if (-not [string]::IsNullOrWhiteSpace($NotChanged)) { Write-Log ('Result not changed: {0}' -f $NotChanged) }
    foreach ($item in $needItems) { Write-Log ('Result needs attention: {0}' -f $item) }
    if (-not [string]::IsNullOrWhiteSpace($Next)) { Write-Log ('Result next: {0}' -f $Next) }
    Write-TpmDetailBlocksLog -Blocks $blocks.ToArray() -Prefix 'Result detail'

    $statusColor = switch ($Status) { 'Ok' { 'Green' } 'Attention' { 'Yellow' } default { 'Red' } }
    Write-Host ''
    if ($hasTitle) { Write-TpmText -Text $Title -Color $statusColor -Indent 2 }
    # Spaced puts a blank line before every item, so no run of text lines is longer than one item (also on a narrow console).
    foreach ($item in @($doneItems | Select-Object -First $maxDone)) { Write-TpmText -Text ('- ' + $item) -Indent 4 -HangingIndent 2 -BlankBefore:$Spaced -BreakLongWords }
    if ($doneItems.Count -gt $maxDone) { Write-TpmText -Text ('... and {0} more' -f ($doneItems.Count - $maxDone)) -Indent 4 -Color DarkGray -BlankBefore:$Spaced }
    if (-not [string]::IsNullOrWhiteSpace($NotChanged)) { Write-TpmText -Text ('Not changed: ' + $NotChanged) -Indent 2 -HangingIndent 4 -Color DarkGray -BlankBefore:$Spaced }
    if ($needItems.Count -gt 0) {
        if ($hasTitle -or $doneItems.Count -gt 0 -or -not [string]::IsNullOrWhiteSpace($NotChanged)) { Write-Host '' }
        Write-TpmText -Text 'Needs your attention:' -Indent 2 -Color Yellow -BlankBefore:$Spaced
        foreach ($item in @($needItems | Select-Object -First $maxNeeds)) { Write-TpmText -Text ('- ' + $item) -Indent 4 -HangingIndent 2 -Color Yellow -BlankBefore:$Spaced -BreakLongWords }
        if ($needItems.Count -gt $maxNeeds) { Write-TpmText -Text ('... and {0} more' -f ($needItems.Count - $maxNeeds)) -Indent 4 -Color DarkGray -BlankBefore:$Spaced }
    }
    if (-not [string]::IsNullOrWhiteSpace($Next)) {
        Write-Host ''
        Write-TpmText -Text ('Next: ' + $Next) -Indent 2 -HangingIndent 6
    }
    $shown = $false
    $available = ($blocks.Count -gt 0)
    $canAsk = ($available -and (Test-TpmInteractiveInput -Unattended:$Unattended))
    if ($canAsk -and $DeferDetails) {
        Add-TpmDeferredDetails -Blocks $blocks.ToArray() -Note $DetailsNote
        $canAsk = $false
    }
    if ($canAsk) {
        Write-Host ''
        $answer = [string](Read-HostSafe ('  [{0}] Details, or press Enter to continue' -f $DetailsKey.ToUpperInvariant()))
        if ($answer.Trim() -ieq $DetailsKey) {
            Show-TpmDetailBlocks -Blocks ($blocks.ToArray()) -Note $DetailsNote
            $shown = $true
        }
    } else {
        Write-Host ''
    }
    if ($PassThru) { return [pscustomobject]@{ DetailsAvailable = $available; DetailsShown = $shown } }
}

# Reason codes in plain words. The table is data: code -> ONE short sentence for
# the default view. Callers show the sentence and put the code (returned
# separately) in the Details view and the log.
function Get-TpmPlainReasonTable {
    $cached = Get-Variable -Name TpmPlainReasonTable -Scope Script -ValueOnly -ErrorAction SilentlyContinue
    if ($null -ne $cached) { return $cached }
    $table = @{
        'ALREADY_APPLIED' = 'This was already set up, so nothing needed to change.'
        'ALREADY_MATCHES' = 'This already matches the restore point, so nothing needed to change.'
        'UNKNOWN_ARCHITECTURE' = 'TeknoParrot Manager could not tell if this game is 32-bit or 64-bit.'
        'UNREADABLE_FILE' = 'TeknoParrot Manager could not read this game file.'
        'UNSUPPORTED_ARCHITECTURE' = 'This step does not support this kind of game.'
        'CHANGED_SINCE_PREVIEW' = 'Your game settings changed after the preview, so nothing was changed.'
        'FAILED_BEFORE_MUTATION' = 'Something stopped this before any change was made.'
        'RESTORE_POINT_HAS_NO_GAMES' = 'This restore point has no game settings in it, so there is nothing to restore for games.'
        'PATH_TOO_LONG' = 'A file path is too long for Windows to use, so nothing was changed.'
        'CANNOT_READ_SETTINGS' = 'A settings file could not be read, so nothing was changed.'
        'REBUILD_BACKUP_MISSING' = 'The backup needed to rebuild the database was not found, so nothing was changed.'
        'POSTGRES_PREFLIGHT_FAILED' = 'PostgreSQL was not ready for this change, so nothing was changed.'
        'POSTGRES_GAME_DATABASE_NOT_READY' = 'A game database could not be opened with the game''s own settings, so nothing was changed.'
        'POSTGRES_SOME_GAMES_NOT_READY' = 'Some games could not be made ready because no starting database file came with them.'
        'POSTGRES_DATABASE_ROLLBACK_VERIFIED' = 'A database step failed, but everything was put back and checked.'
        'POSTGRES_DATABASE_ROLLBACK_UNVERIFIED' = 'A database step failed and TeknoParrot Manager could not confirm that everything was put back.'
        'POSTGRES_DATABASE_STATE_UNKNOWN' = 'A database step failed and the state of the database could not be confirmed.'
        'NO_BACKUPS_FOUND' = 'No backups were found.'
        'BACKUP_UNAVAILABLE' = 'The chosen backup could not be found.'
        'BACKUP_EMPTY' = 'The chosen backup is empty, so nothing was restored.'
        'BACKUP_UNREADABLE' = 'The chosen backup could not be read, so nothing was restored.'
        'BACKUP_VERIFICATION_FAILED' = 'The chosen backup did not pass its check, so nothing was restored.'
        'BACKUP_FAILED' = 'A safety backup could not be made, so nothing was changed.'
        'USER_CANCELLED' = 'You canceled, so nothing was changed.'
        'USER_DECLINED' = 'You chose not to continue, so nothing was changed.'
        'DECLINED' = 'You chose not to continue, so nothing was changed.'
        'APPLICATION_RUNNING' = 'TeknoParrot is still running. Close it and try again.'
        'ROLLBACK_SNAPSHOT_FAILED' = 'A safety copy of your current settings could not be made, so nothing was changed.'
        'RESTORE_DELETE_FAILED_ROLLED_BACK' = 'The restore could not finish, so your earlier settings were put back.'
        'RESTORE_DELETE_ROLLBACK_FAILED' = 'The restore could not finish and your earlier settings could not be fully put back.'
        'RESTORE_COPY_FAILED_ROLLED_BACK' = 'The restore could not finish, so your earlier settings were put back.'
        'RESTORE_COPY_ROLLBACK_FAILED' = 'The restore could not finish and your earlier settings could not be fully put back.'
        'RESTORE_FAILED_ROLLED_BACK' = 'The restore could not finish, so your earlier settings were put back.'
        'RESTORE_ROLLBACK_FAILED' = 'The restore could not finish and your earlier settings could not be fully put back.'
        'RESTORE_VERIFICATION_FAILED' = 'The restored settings did not match the backup. Your earlier settings were kept for recovery.'
        'RESTORE_NOT_PERFORMED' = 'The restore was not done, so nothing was changed.'
        'RESTORED' = 'The settings were restored and checked.'
        'NOT_A_GAME_PROFILE' = 'That item is not a game settings file.'
        'NOT_IN_RESTORE_POINT' = 'That game is not in the restore point.'
        'RESTORE_POINT_DAMAGED' = 'This restore point is damaged and cannot be used.'
