        'STAGING_SPACE_UNAVAILABLE' = 'Free space could not be checked, so nothing was changed.'
    }
    Set-Variable -Name TpmPlainReasonTable -Scope Script -Value $table
    return $table
}

# Returns @{ Code; Text; Known }. Code is the internal code (for Details and the
# log); Text is the one plain sentence for the default view. An unknown or empty
# code gets a safe generic sentence.
function Get-TpmPlainReason {
    param([AllowNull()][AllowEmptyString()][string]$Code)
    $key = if ($null -eq $Code) { '' } else { $Code.Trim().ToUpperInvariant() }
    $table = Get-TpmPlainReasonTable
    if ($key -and $table.ContainsKey($key)) {
        return [pscustomobject]@{ Code = $key; Text = [string]$table[$key]; Known = $true }
    }
    return [pscustomobject]@{ Code = $key; Text = 'This could not be completed. Details have the technical reason.'; Known = $false }
}

