        foreach ($plain in $groups.Keys) {
            foreach ($internal in $groups[$plain]) { $lookup[[string]$internal] = [string]$plain }
        }
        Set-Variable -Name TpmFriendlyProgressLabelLookup -Scope Script -Value $lookup
    }
    if ($lookup.ContainsKey($Label)) { return [string]$lookup[$Label] }
    # Download steps carry the name of what is being downloaded: "<name> via <method>" while it transfers, "Verifying <name>" while
    # the file is checked and "Downloading <name>" when the step closes. The screen says what happens to what; the method (BITS,
    # HttpClient, web fallback) stays in the log (the "Progress step" line and the download metrics line).
    $download = [regex]::Match($Label, '^(?:(?<transfer>.+) via (?:BITS|HttpClient|web fallback)|Verifying (?<check>.+)|Downloading (?<named>.+))$')
    if ($download.Success) {
        $downloadNames = @{
            'PostgresGuide' = 'the PostgreSQL installer'
            'EggmanDat' = 'the DAT index'
            'FFBPlugin' = 'the force feedback plugin'
            'CheckForUpdates' = 'the TeknoParrot Manager update'
            'ReShadeSetup' = 'the ReShade installer'
            'download' = 'the file'
        }
        $downloadWhat = if ($download.Groups['check'].Success) { $download.Groups['check'].Value } elseif ($download.Groups['transfer'].Success) { $download.Groups['transfer'].Value } else { $download.Groups['named'].Value }
        if ($downloadNames.ContainsKey($downloadWhat)) { $downloadWhat = [string]$downloadNames[$downloadWhat] }
        if ($download.Groups['check'].Success) { return ('Checking {0}' -f $downloadWhat) }
        return ('Downloading {0}' -f $downloadWhat)
    }
    return $Label
}

# Start-up summary rows ("Label : value"). New-TpmStartupRow makes one row.
function New-TpmStartupRow {
    param([Parameter(Mandatory)][string]$Label, [AllowNull()][AllowEmptyString()][string]$Value = '', [string]$Color = '')
    return [pscustomobject]@{ Label = $Label; Value = [string]$Value; Color = $Color }
}

# True when the saved-settings step has just ended with a blank line and nothing was printed after it, so the
# next start-up block must not add a second blank line. Reads its two start-up variables undefined-safe
# (an unset variable means "no blank line yet"), so it also works in strict mode and in extracted test runs.
function Test-TpmStartupBlankLineAlreadyWritten {
    $accepted = [bool](Get-Variable -Name configAccepted -ValueOnly -ErrorAction SilentlyContinue)
    $printed = [bool](Get-Variable -Name tpmPrintedAfterSavedSettings -ValueOnly -ErrorAction SilentlyContinue)
    return ($accepted -and -not $printed)
}

# Start-up settings summary. The rows always go to the log. Mode LogOnly (the
# default) shows nothing; Plain shows the title and one "Label : value" line per row
# exactly as the old start-up screen did (kept for unattended runs, whose console
# log is read by the smoke harness); Details shows the same rows wrapped to the
# console width, for the Details key at the saved-settings question.
function Show-TpmStartupSummary {
    param(
        [Parameter(Mandatory)][string]$Title,
        [AllowEmptyCollection()][object[]]$Rows = @(),
        [ValidateSet('LogOnly', 'Plain', 'Details')][string]$Mode = 'LogOnly',
        [string]$TitleColor = 'Cyan'
    )
    if ($Mode -ne 'Details') {
        Write-Log ('Startup settings - {0}' -f $Title.TrimEnd(':'))
        foreach ($row in @($Rows)) { Write-Log ('Startup settings -   {0} : {1}' -f $row.Label, $row.Value) }
    }
    if ($Mode -eq 'Plain') {
        Write-Host $Title -ForegroundColor $TitleColor
        foreach ($row in @($Rows)) {
            $rowText = '  {0,-20} : {1}' -f $row.Label, $row.Value
            if ($row.Color) { Write-Host $rowText -ForegroundColor $row.Color } else { Write-Host $rowText }
        }
    } elseif ($Mode -eq 'Details') {
        Write-Host ''
        Write-TpmText -Text $Title -Color $TitleColor -Indent 2
        foreach ($row in @($Rows)) {
            Write-TpmLabelValue -Prefix ('{0,-20} : ' -f $row.Label) -Text ([string]$row.Value) -Indent 4 -Color ([string]$row.Color)
        }
        Write-Host ''
    }
}

# Title between two rules, as wide as the console allows (at most 44).
function Write-TpmResetRestoreHeader {
    param([Parameter(Mandatory)][string]$Title)
    $rule = '-' * [Math]::Max(8, [Math]::Min(44, (Get-TpmResetRestoreLineWidth) - 1))
    Write-Host ''
    Write-Host $rule -ForegroundColor Cyan
    Write-TpmResetRestoreText -Text $Title -Color Cyan -Indent 1
    Write-Host $rule -ForegroundColor Cyan
}

# Explains a question in wrapped lines, then asks it with a short prompt that
# fits even a narrow console. With DetailBlocks the person may answer D to read the
# details first (shown once per D); every other answer is returned as it was typed.
# Differs from Read-TpmAnswerWithDetails: it explains the question first, indents the prompt, and returns the answer as it was typed.
function Read-TpmResetRestoreAnswer {
    param([AllowEmptyString()][string]$Intro = '', [Parameter(Mandatory)][string]$Prompt, [object[]]$DetailBlocks = @(), [string]$DetailsNote = '')
    if (-not [string]::IsNullOrWhiteSpace($Intro)) { Write-TpmResetRestoreText -Text $Intro }
    $hasDetails = (@($DetailBlocks | Where-Object { $null -ne $_ }).Count -gt 0)
    if ($hasDetails) { Write-TpmResetRestoreText -Text 'Press D to see the details first.' -Color DarkGray }
    while ($true) {
        $answer = [string](Read-HostSafe ('  ' + $Prompt))
        if (-not $hasDetails -or $answer.Trim().ToUpperInvariant() -ne 'D') { return $answer }
        Show-TpmDetailBlocks -Blocks $DetailBlocks -Note $DetailsNote
    }
}

# One console line of the UserProfiles restore. With Wrap (Reset and Restore)
# it is wrapped to the console width and keeps its own indent; without Wrap it
# is written exactly as before.
function Write-TpmRestoreStatusLine {
    param([AllowEmptyString()][string]$Text, [string]$Color = '', [switch]$Wrap)
    if ($Wrap) {
        $indent = ([regex]::Match($Text, '^ *')).Value.Length
        Write-TpmResetRestoreText -Text $Text.Trim() -Color $Color -Indent $indent
        return
    }
    if ($Color) { Write-Host $Text -ForegroundColor $Color } else { Write-Host $Text }
}

# Restore points made for another TeknoParrot folder (moved, renamed or on
# another drive letter). Read-only note: never offered, never removed. The
# folders they were made for are in the details (Get-TpmRestorePointOtherFolderBlocks).
function Write-TpmRestorePointOtherFolderNote {
    param([Parameter(Mandatory)][object[]]$RestorePoints)
    Write-Host ''
    Write-TpmResetRestoreText -Text ('{0} made for another TeknoParrot folder, not used here.' -f (Format-TpmCountNoun -Count @($RestorePoints).Count -Singular 'restore point')) -Color DarkGray
    Write-TpmResetRestoreText -Text 'TeknoParrot Manager never uses or removes restore points of another folder.' -Color DarkGray
}

function Get-TpmRestorePointOtherFolderBlocks {
    param([Parameter(Mandatory)][object[]]$RestorePoints)
    $blocks = New-Object System.Collections.Generic.List[object]
    foreach ($point in @($RestorePoints)) {
        [void]$blocks.Add(@{ Heading = (Format-TpmRestorePointLabel -RestorePoint $point); Lines = @(('Made for: {0}' -f [string]$point.Record.UserProfilesDir)) })
    }
    return $blocks.ToArray()
}

# One restore point as one short row: when it was made, what kind of copy it is, how many files it holds.
function Format-TpmRestorePointLabel {
    param([Parameter(Mandatory)]$RestorePoint)
    $when = ([datetime]$RestorePoint.CreatedUtc).ToLocalTime().ToString('yyyy-MM-dd HH:mm', [System.Globalization.CultureInfo]::InvariantCulture)
    $files = Format-TpmCountNoun -Count ([int]$RestorePoint.Record.FileCount) -Singular 'file'
    $gamesText = if (Test-TpmRestorePointRecordHasGames -RestorePoint $RestorePoint) { '' } else { ' - no games in it' }
    return ('{0} - {1} - {2}{3}' -f $when, (Get-TpmSavedCopyKindText -Kind ([string]$RestorePoint.Kind)), $files, $gamesText)
}

function Get-TpmResetRestoreGameLabel {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$BackupPath, [Parameter(Mandatory)][string]$RelativePath)
    $code = [System.IO.Path]::GetFileNameWithoutExtension($RelativePath)
    # A label is only decoration: an unreadable profile must never stop the menu.
    try {
        $live = Join-Path $UserProfilesDir $RelativePath
        $probe = if (Test-Path -LiteralPath $live -PathType Leaf) { $live } else { Join-Path $BackupPath $RelativePath }
        $name = Get-TpmGameDisplayLabel -ProfilePath $probe -Fallback $code
    } catch {
        return $code
    }
    if ($name -ieq $code) { return $code }
    return [string]$name
}

# The names of a list of games for a screen. Two games with the same name get their file name added so they can be told apart.
function Get-TpmResetRestoreGameLabels {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$BackupPath, [Parameter(Mandatory)][string[]]$RelativePaths)
    $names = @($RelativePaths | ForEach-Object { Get-TpmResetRestoreGameLabel -UserProfilesDir $UserProfilesDir -BackupPath $BackupPath -RelativePath $_ })
    $labels = New-Object System.Collections.Generic.List[string]
    for ($index = 0; $index -lt $names.Count; $index++) {
        $sameName = @($names | Where-Object { $_ -ieq $names[$index] }).Count
        if ($sameName -gt 1) {
            [void]$labels.Add(('{0} ({1})' -f $names[$index], [System.IO.Path]::GetFileNameWithoutExtension($RelativePaths[$index])))
        } else {
            [void]$labels.Add([string]$names[$index])
        }
    }
    return $labels.ToArray()
}

function Select-TpmRestorePoint {
    param([Parameter(Mandatory)][object[]]$RestorePoints)
    $rows = @($RestorePoints | ForEach-Object { Format-TpmRestorePointLabel -RestorePoint $_ })
    $picked = Read-TpmNumberedListChoice -Rows $rows -Prompt '  Choose a number, or B to go back' -Heading 'Restore points, newest first:'
    if ($picked -lt 0) { return $null }
    return $RestorePoints[$picked]
}

function Write-TpmResetRestoreResult {
    param([Parameter(Mandatory)]$Result)
    $color = switch ([string]$Result.Outcome) { 'SUCCEEDED' { 'Green' } 'NO_OP' { 'DarkGray' } 'ACTION_REQUIRED' { 'Red' } default { 'Yellow' } }
    Write-Host ''
    Write-TpmResetRestoreText -Text ([string]$Result.Summary) -Color $color
    if (-not [string]::IsNullOrWhiteSpace([string]$Result.SafetyRestorePoint) -and [string]$Result.Outcome -in @('SUCCEEDED','ROLLED_BACK_VERIFIED','ACTION_REQUIRED')) {
        Write-TpmResetRestoreText -Text 'The restore point made just before this change is listed in Reset and Restore, so this change can be undone there.' -Color DarkGray
    }
    Write-Log ("Reset and Restore: outcome {0} ({1})." -f $Result.Outcome, $Result.ReasonCode)
}

function Invoke-TpmResetRestoreOneGame {
    param([Parameter(Mandatory)]$RestorePoint, [Parameter(Mandatory)]$Plan, [Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$BackupPath, [AllowEmptyString()][string]$ConfigPath = '', [string]$RestorePointsRoot = '')
    $when = ([datetime]$RestorePoint.CreatedUtc).ToLocalTime().ToString('yyyy-MM-dd HH:mm', [System.Globalization.CultureInfo]::InvariantCulture)
    $games = @(@($Plan.Changes) | Where-Object { [bool]$_.IsGameProfile -and [string]$_.Change -in @('Replace','PutBack') })
    $added = @(@($Plan.Changes) | Where-Object { [bool]$_.IsGameProfile -and [string]$_.Change -eq 'Remove' })
    if ($added.Count -gt 0) {
        $addedText = if ($added.Count -eq 1) { '1 game was added after this restore point. It is not listed and stays as it is.' } else { ('{0} games were added after this restore point. They are not listed and stay as they are.' -f $added.Count) }
        Write-TpmResetRestoreText -Text $addedText -Color DarkGray
    }
    if ($games.Count -eq 0) {
        # A restore point saved before any game existed has nothing to put back; saying "already matches" would be wrong.
        $noGames = $false
        try { $noGames = ((Get-TpmTopLevelGameFileCount -Path $BackupPath) -eq 0) } catch { Write-Log ("Reset and Restore: the games in the restore point could not be counted -- {0}" -f $_.Exception.Message) }
        if ($noGames) { return (New-TpmNoGamesResult) }
        return (New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'ALREADY_MATCHES' -Summary 'Nothing was changed. Every game in this restore point already matches it.')
    }
    $labels = @(Get-TpmResetRestoreGameLabels -UserProfilesDir $UserProfilesDir -BackupPath $BackupPath -RelativePaths @($games | ForEach-Object { [string]$_.RelativePath }))
    $rows = New-Object System.Collections.Generic.List[string]
    $blocks = New-Object System.Collections.Generic.List[object]
    for ($index = 0; $index -lt $games.Count; $index++) {
        $putBack = ([string]$games[$index].Change -eq 'PutBack')
        [void]$rows.Add($(if ($putBack) { ('{0} (its settings file was removed since then)' -f $labels[$index]) } else { [string]$labels[$index] }))
        [void]$blocks.Add(@{ Heading = [string]$labels[$index]; Lines = @(('File: UserProfiles\{0}' -f $games[$index].RelativePath), $(if ($putBack) { 'What changed: Its settings file was removed since then.' } else { 'What changed: Its settings changed since then.' })) })
    }
    $picked = Read-TpmNumberedListChoice -Rows $rows.ToArray() -Prompt '  Choose a number, or B to go back' -Heading ('Games whose settings differ from {0}:' -f $when) -DetailBlocks $blocks.ToArray()
    if ($picked -lt 0) { return (New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'USER_CANCELLED' -Summary 'Canceled. Nothing was changed.') }
    $game = $games[$picked]
    $changeText = if ([string]$game.Change -eq 'PutBack') {
        ('Its settings file was removed after {0}. It will be put back exactly as it was then.' -f $when)
    } else {
        ('Its whole settings file goes back to how it was on {0}. That includes the game path, controls and every other setting. Changes you made yourself since then are lost.' -f $when)
    }
    Write-Host ''
    Write-TpmResetRestoreText -Text ('Game: {0}' -f $labels[$picked]) -Color Yellow
    Write-Host ''
    Write-TpmResetRestoreText -Text $changeText
    Write-Host ''
    Write-TpmResetRestoreText -Text 'Not changed: other games, TeknoParrot Manager''s own settings, game files, saves and databases.'
    Write-TpmResetRestoreText -Text 'Before anything changes, TeknoParrot Manager saves and checks a new restore point of your current settings. You can undo this here.' -Color DarkGray
    Write-Host ''
    $confirm = Read-TpmResetRestoreAnswer -Intro 'Any answer other than YES cancels, and nothing is changed.' -Prompt 'Type YES to put this game back' -DetailBlocks @($blocks[$picked])
    if ($confirm.Trim().ToUpperInvariant() -ne 'YES') { return (New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'USER_DECLINED' -Summary 'Canceled. Nothing was changed.') }
    return (Restore-TpmRestorePointGame -RestorePoint $RestorePoint -UserProfilesDir $UserProfilesDir -RelativePath ([string]$game.RelativePath) -ExpectedCurrentSha256 ([string]$game.CurrentSha256) -ConfigPath $ConfigPath -RestorePointsRoot $RestorePointsRoot)
}

# The preview of "Restore all": what goes back, in counts (the names are in the details). Returns the detail
# blocks (one per group) for the question that follows. The settings files and folders are counted exactly as
# Invoke-TpmResetRestoreAllGames counts them for its second question.
function Show-TpmResetRestoreAllPreview {
    param([Parameter(Mandatory)]$Plan, [Parameter(Mandatory)][string]$When, [Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$BackupPath)
    $changes = @($Plan.Changes)
    $folderCount = @($Plan.FoldersRemoved).Count + @($Plan.FoldersPutBack).Count
    $blocks = New-Object System.Collections.Generic.List[object]
    Write-Host ''
    Write-TpmResetRestoreText -Text ('Everything goes back to how it was on {0}:' -f $When) -Color Cyan
    Write-Host ''
    foreach ($group in @(
            @{ Change = 'Replace'; Heading = 'Settings files that go back to how they were then'; One = '1 settings file goes back to how it was then.'; Many = '{0} settings files go back to how they were then.'; Color = '' },
            @{ Change = 'PutBack'; Heading = 'Settings files that were removed since then and are put back'; One = '1 settings file was removed since then and is put back.'; Many = '{0} settings files were removed since then and are put back.'; Color = '' },
            @{ Change = 'Remove'; Heading = 'Files added after that restore point that are REMOVED from UserProfiles'; One = '1 file was added after that restore point and is REMOVED from UserProfiles. The restore point made first keeps a copy.'; Many = '{0} files were added after that restore point and are REMOVED from UserProfiles. The restore point made first keeps a copy.'; Color = 'Yellow' })) {
        $members = @($changes | Where-Object { [string]$_.Change -eq $group.Change })
        if ($members.Count -eq 0) { continue }
        $labels = New-Object System.Collections.Generic.List[string]
        $gamePaths = @($members | Where-Object { [bool]$_.IsGameProfile } | ForEach-Object { [string]$_.RelativePath })
        if ($gamePaths.Count -gt 0) {
            foreach ($label in @(Get-TpmResetRestoreGameLabels -UserProfilesDir $UserProfilesDir -BackupPath $BackupPath -RelativePaths $gamePaths)) { [void]$labels.Add([string]$label) }
        }
        foreach ($member in @($members | Where-Object { -not [bool]$_.IsGameProfile })) { [void]$labels.Add('UserProfiles\' + [string]$member.RelativePath) }
        [void]$blocks.Add(@{ Heading = $group.Heading; Lines = $labels.ToArray() })
        $text = if ($members.Count -eq 1) { [string]$group.One } else { ([string]$group.Many -f $members.Count) }
        Write-TpmResetRestoreText -Text ('- ' + $text) -Indent 4 -HangingIndent 2 -Color $group.Color
    }
    if ($folderCount -gt 0) {
        $folderText = if ($folderCount -eq 1) { '- 1 folder inside UserProfiles is also put back or removed to match.' } else { ('- {0} folders inside UserProfiles are also put back or removed to match.' -f $folderCount) }
        Write-TpmResetRestoreText -Text $folderText -Indent 4 -HangingIndent 2 -Color Yellow
    }
    switch ([string]$Plan.ConfigChange) {
        'Replace' { Write-TpmResetRestoreText -Text '- TeknoParrot Manager''s own settings also go back to how they were then. TeknoParrot Manager closes afterwards; start it again so it loads them.' -Indent 4 -HangingIndent 2 -Color Yellow }
        'Same' { Write-TpmResetRestoreText -Text '- TeknoParrot Manager''s own settings already match and are not changed.' -Indent 4 -HangingIndent 2 }
        default { Write-TpmResetRestoreText -Text '- TeknoParrot Manager''s own settings were not saved in this restore point and are not changed.' -Indent 4 -HangingIndent 2 }
    }
    Write-Host ''
    Write-TpmResetRestoreText -Text 'Not changed: game files, saves, databases and LaunchBox.'
    Write-TpmResetRestoreText -Text 'Before anything changes, TeknoParrot Manager saves and checks a new restore point of your current settings. You can undo this here.' -Color DarkGray
    Write-Host ''
    return $blocks.ToArray()
}

function Invoke-TpmResetRestoreAllGames {
    param([Parameter(Mandatory)]$RestorePoint, [Parameter(Mandatory)]$Plan, [Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$BackupPath, [AllowEmptyString()][string]$ConfigPath = '', [string]$RestorePointsRoot = '')
    $when = ([datetime]$RestorePoint.CreatedUtc).ToLocalTime().ToString('yyyy-MM-dd HH:mm', [System.Globalization.CultureInfo]::InvariantCulture)
    $changes = @($Plan.Changes)
    $folderCount = @($Plan.FoldersRemoved).Count + @($Plan.FoldersPutBack).Count
    if (($changes.Count + $folderCount) -eq 0 -and [string]$Plan.ConfigChange -ne 'Replace') {
        return (New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'ALREADY_MATCHES' -Summary 'Nothing was changed. Everything already matches this restore point.')
    }
    # Refuse up front, before any preview or question, when Restore all cannot run safely (nothing is changed).
    $blocked = Get-TpmRestoreAllBlocker -Plan $Plan -UserProfilesDir $UserProfilesDir -BackupPath $BackupPath
    if ($null -ne $blocked) { return $blocked }
    $blocks = @(Show-TpmResetRestoreAllPreview -Plan $Plan -When $when -UserProfilesDir $UserProfilesDir -BackupPath $BackupPath)
    # Everything that changes: settings files, folders and, when it differs, TeknoParrot Manager's own settings file. One typed YES approves it all.
    $totalItems = $changes.Count + $folderCount + $(if ([string]$Plan.ConfigChange -eq 'Replace') { 1 } else { 0 })
    $totalWhat = if ([string]$Plan.ConfigChange -eq 'Replace') { 'game settings files, folders and TeknoParrot Manager''s own settings' } else { 'game settings files and folders' }
    $confirmIntro = 'This changes {0} in total: {1}. Any answer other than YES cancels, and nothing is changed.' -f (Format-TpmCountNoun -Count $totalItems -Singular 'item'), $totalWhat
    $confirm = Read-TpmResetRestoreAnswer -Intro $confirmIntro -Prompt 'Type YES to put everything back' -DetailBlocks $blocks
    if ($confirm.Trim().ToUpperInvariant() -ne 'YES') { return (New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'USER_DECLINED' -Summary 'Canceled. Nothing was changed.') }
    return (Restore-TpmRestorePointAll -RestorePoint $RestorePoint -UserProfilesDir $UserProfilesDir -Plan $Plan -ConfigPath $ConfigPath -RestorePointsRoot $RestorePointsRoot)
}

function Invoke-TpmRestorePointCleanup {
    param([Parameter(Mandatory)][object[]]$RestorePoints, [Parameter(Mandatory)][string]$UserProfilesDir)
    # Only restore points made for this TeknoParrot folder are counted or can be removed.
    $RestorePoints = @((Select-TpmRestorePointsForFolder -RestorePoints @($RestorePoints) -UserProfilesDir $UserProfilesDir).Current)
    $keep = Get-TpmRestorePointKeepCount
    $candidates = @(Get-TpmRestorePointRemovalCandidates -RestorePoints $RestorePoints -KeepCount $keep)
    $bytes = [int64]0
    foreach ($point in @($RestorePoints | Where-Object { [bool]$_.Readable })) {
        foreach ($entry in @($point.Record.Entries | Where-Object { $null -ne $_ -and -not [bool]$_.IsDirectory })) { $bytes += [int64]$entry.Length }
        if ([bool]$point.Record.Config.Present) { $bytes += [int64]$point.Record.Config.Length }
    }
    Write-Host ''
    Write-TpmResetRestoreText -Text ('You have {0} for this TeknoParrot folder, using about {1:N1} MB.' -f (Format-TpmCountNoun -Count @($RestorePoints).Count -Singular 'restore point'), ($bytes / 1MB))
    Write-TpmResetRestoreText -Text 'TeknoParrot Manager never removes restore points by itself.'
    Write-TpmResetRestoreText -Text ('This option keeps the first restore point and the newest {0}.' -f $keep)
    if ($candidates.Count -eq 0) {
        return (New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'NOTHING_TO_REMOVE' -Summary 'Nothing was removed. There are no older restore points to remove.')
    }
    $labels = @($candidates | ForEach-Object { Format-TpmRestorePointLabel -RestorePoint $_ })
    $listed = 5
    $listHeading = if ($labels.Count -gt $listed) { ('Older restore points that would be removed (first {0} of {1}):' -f $listed, $labels.Count) } else { 'Older restore points that would be removed:' }
    Write-Host ''
    Write-TpmResetRestoreText -Text $listHeading -Color Yellow
    Write-Host ''
    foreach ($label in @($labels | Select-Object -First $listed)) { Write-TpmResetRestoreText -Text ('- ' + $label) -Indent 4 -HangingIndent 2 }
    $blocks = @()
    if ($labels.Count -gt $listed) {
        $blocks = @(@{ Heading = 'All the restore points that would be removed'; Lines = $labels })
    }
    Write-Host ''
    $confirm = Read-TpmResetRestoreAnswer -Intro 'Any answer other than YES cancels, and nothing is removed.' -Prompt 'Type YES to remove them' -DetailBlocks $blocks
    if ($confirm.Trim().ToUpperInvariant() -ne 'YES') { return (New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'USER_DECLINED' -Summary 'Canceled. Nothing was removed.') }
    $removed = 0
    $kept = New-Object System.Collections.Generic.List[string]
    foreach ($point in $candidates) {
        $removal = Remove-TpmRestorePoint -RestorePoint $point -UserProfilesDir $UserProfilesDir -AllowEmptyBaseline
        if ($removal.Removed) { $removed++ } else { [void]$kept.Add(('{0}: {1}' -f (Format-TpmRestorePointLabel -RestorePoint $point), $removal.Reason)) }
    }
    foreach ($line in $kept) { Write-TpmResetRestoreText -Text ('Kept ' + $line) -Color Yellow -HangingIndent 2 }
    $removedText = if ($removed -eq 1) { '1 older restore point was removed' } else { ('{0} older restore points were removed' -f $removed) }
    if ($kept.Count -eq 0) {
        return (New-TpmResetRestoreResult -Outcome 'SUCCEEDED' -ReasonCode 'REMOVED' -Summary ($removedText + '.'))
    }
    $keptText = if ($kept.Count -eq 1) { '1 could not be removed and was kept' } else { ('{0} could not be removed and were kept' -f $kept.Count) }
    return (New-TpmResetRestoreResult -Outcome 'ACTION_REQUIRED' -ReasonCode 'PARTLY_REMOVED' -Summary ('{0}; {1}.' -f $removedText, $keptText))
}

# Reset and Restore menu (Restore backup, option 4). Returns RestartRequired
# when TeknoParrot Manager's own settings file was put back. Only restore points
# made for this UserProfiles folder are offered; the rest are listed read-only.
# A file that cannot be read ends the action with a plain message, never the menu.
function Invoke-TpmResetRestoreMenu {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [AllowEmptyString()][string]$ConfigPath = '', [string]$RestorePointsRoot = '')
    $menuResult = [pscustomobject]@{ RestartRequired = $false; Result = $null }
    $profilesFull = [System.IO.Path]::GetFullPath($UserProfilesDir).TrimEnd('\','/')
    Write-TpmResetRestoreHeader -Title 'Reset and Restore'
    Write-Host ''
    Write-TpmResetRestoreText -Text 'When it starts, TeknoParrot Manager saves a checked restore point of your game settings, if they changed.'
    Write-TpmResetRestoreText -Text 'It also saves its own settings. The first restore point that has your games in it is always kept.'
    Write-TpmResetRestoreText -Text 'Game files, saves and databases are not part of a restore point.'
    try {
        $sets = Select-TpmRestorePointsForFolder -RestorePoints @(Get-TpmRestorePoints -RestorePointsRoot $RestorePointsRoot) -UserProfilesDir $profilesFull
    } catch {
        Write-TpmResetRestoreText -Text ('The restore points could not be read, so nothing can be changed here. {0}' -f $_.Exception.Message) -Color Red
        return $menuResult
    }
    $usable = @($sets.Current)
    $damaged = @($sets.Damaged).Count
    if ($damaged -gt 0) {
        $damagedText = if ($damaged -eq 1) { '1 restore point is damaged and is not offered.' } else { ('{0} restore points are damaged and are not offered.' -f $damaged) }
        Write-TpmResetRestoreText -Text $damagedText -Color Yellow
    }
    $otherBlocks = @()
    if (@($sets.OtherFolder).Count -gt 0) {
        Write-TpmRestorePointOtherFolderNote -RestorePoints @($sets.OtherFolder)
        $otherBlocks = @(Get-TpmRestorePointOtherFolderBlocks -RestorePoints @($sets.OtherFolder))
    }
    if ($usable.Count -eq 0) {
        Write-TpmResetRestoreText -Text 'There are no restore points for this TeknoParrot folder yet. TeknoParrot Manager makes one the next time it starts.' -Color Yellow
        return $menuResult
    }
    # The first restore point(s) are checked now, so a damaged one is marked unusable in this note.
    $baselineVerdicts = @{}
    foreach ($candidate in @($usable | Where-Object { [string]$_.Kind -eq 'Baseline' } | Sort-Object -Property CreatedUtc)) {
        $verdict = Test-TpmRestorePoint -RestorePoint $candidate -UserProfilesDir $profilesFull
        $baselineVerdicts[[string]$candidate.Path] = $verdict
        if (-not $verdict.Valid) {
            Write-TpmResetRestoreText -Text ('The first restore point from {0} cannot be used (it is kept, but not offered for Reset): {1}' -f ([datetime]$candidate.CreatedUtc).ToLocalTime().ToString('yyyy-MM-dd HH:mm', [System.Globalization.CultureInfo]::InvariantCulture), $verdict.Reason) -Color Yellow
        }
    }
    $point = $null
    $check = $null
    # A dead end (no usable first restore point, or B in the list) shows the menu again instead of closing Reset and Restore.
    while ($null -eq $point) {
        Write-Host ''
        Write-TpmResetRestoreText -Text '1) Reset one game (back to the first restore point)' -HangingIndent 3
        Write-TpmResetRestoreText -Text '2) Restore one game (choose a restore point)' -HangingIndent 3
        Write-TpmResetRestoreText -Text '3) Reset all games (back to the first restore point)' -HangingIndent 3
        Write-TpmResetRestoreText -Text '4) Restore all games (choose a restore point)' -HangingIndent 3
        Write-TpmResetRestoreText -Text '5) Remove older restore points' -HangingIndent 3
        Write-Host ''
        Write-TpmResetRestoreText -Text 'B) Back' -HangingIndent 3
        $menuChoices = @('1','2','3','4','5','B')
        if ($otherBlocks.Count -gt 0) {
            Write-TpmResetRestoreText -Text 'D) Details about the restore points made for another folder' -HangingIndent 3
            $menuChoices += 'D'
        }
        do {
            $choice = Read-TpmChoice -Prompt '  Choose 1-5, or B to go back' -Choices $menuChoices -Default 'B'
            if ($choice -eq 'D') { Show-TpmDetailBlocks -Blocks $otherBlocks }
        } while ($choice -eq 'D')
        if ($choice -eq 'B') { return $menuResult }
        if ($choice -eq '5') {
            $menuResult.Result = Invoke-TpmRestorePointCleanup -RestorePoints $usable -UserProfilesDir $profilesFull
            Write-TpmResetRestoreResult -Result $menuResult.Result
            return $menuResult
        }
        $check = $null
        if ($choice -in @('1','3')) {
            # The oldest first restore point that passed the check above and has games; one without games only when no other passes.
            $emptyPoint = $null
            foreach ($candidate in @($usable | Where-Object { [string]$_.Kind -eq 'Baseline' } | Sort-Object -Property CreatedUtc)) {
                $candidateVerdict = $baselineVerdicts[[string]$candidate.Path]
                if (-not $candidateVerdict.Valid) { continue }
                $hasGames = $true
                try { $hasGames = ((Get-TpmTopLevelGameFileCount -Path ([string]$candidateVerdict.BackupPath)) -gt 0) } catch { Write-Log ("Reset and Restore: the games in the first restore point could not be counted -- {0}" -f $_.Exception.Message) }
                if ($hasGames) { $point = $candidate; $check = $candidateVerdict; break }
                if ($null -eq $emptyPoint) { $emptyPoint = $candidate }
            }
            if ($null -eq $point -and $null -ne $emptyPoint) { $point = $emptyPoint; $check = $baselineVerdicts[[string]$emptyPoint.Path] }
            if ($null -eq $point) {
                Write-TpmResetRestoreText -Text 'There is no usable first restore point to reset to. Choose a restore point instead (option 2 or 4).' -Color Yellow
                continue
            }
            Write-TpmResetRestoreText -Text ('Using: {0}' -f (Format-TpmRestorePointLabel -RestorePoint $point)) -Color Cyan
        } else {
            $point = Select-TpmRestorePoint -RestorePoints $usable
        }
    }
    if ($null -eq $check) { $check = Test-TpmRestorePoint -RestorePoint $point -UserProfilesDir $profilesFull }
    if (-not $check.Valid) {
        $menuResult.Result = New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'RESTORE_POINT_DAMAGED' -Summary ('Nothing was changed. This restore point cannot be used: {0}' -f $check.Reason)
        Write-TpmResetRestoreResult -Result $menuResult.Result
        return $menuResult
    }
    try {
        $plan = Get-TpmRestorePointChangePlan -RestorePoint $point -UserProfilesDir $profilesFull -ConfigPath $ConfigPath
    } catch {
        Write-Log ("Reset and Restore: the comparison could not be made -- {0}" -f $_.Exception.Message)
        $menuResult.Result = New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'CANNOT_READ_SETTINGS' -Summary (Get-TpmUnreadableFileSummary -Message $_.Exception.Message)
        Write-TpmResetRestoreResult -Result $menuResult.Result
        return $menuResult
    }
    try {
        if ($choice -in @('1','2')) {
            $menuResult.Result = Invoke-TpmResetRestoreOneGame -RestorePoint $point -Plan $plan -UserProfilesDir $profilesFull -BackupPath $check.BackupPath -ConfigPath $ConfigPath -RestorePointsRoot $RestorePointsRoot
        } else {
            $menuResult.Result = Invoke-TpmResetRestoreAllGames -RestorePoint $point -Plan $plan -UserProfilesDir $profilesFull -BackupPath $check.BackupPath -ConfigPath $ConfigPath -RestorePointsRoot $RestorePointsRoot
        }
    } catch {
        $failure = $_.Exception.Message
        Write-Log ("Reset and Restore: stopped unexpectedly -- {0}" -f $failure)
        $menuResult.Result = New-TpmResetRestoreResult -Outcome 'ACTION_REQUIRED' -ReasonCode 'STOPPED_UNEXPECTEDLY' -Summary ('Reset and Restore stopped unexpectedly: {0} TeknoParrot Manager cannot tell whether anything was changed. If a restore point made just before a reset or restore was saved, it is listed in Reset and Restore. Check your settings before you continue.' -f $failure)
        $menuResult.RestartRequired = [bool](Get-Variable -Name TpmConfigRestoreRestartRequired -Scope Script -ValueOnly -ErrorAction SilentlyContinue)
        Write-TpmResetRestoreResult -Result $menuResult.Result
        return $menuResult
    }
    Write-TpmResetRestoreResult -Result $menuResult.Result
    $menuResult.RestartRequired = [bool]$menuResult.Result.RestartRequired
    return $menuResult
}

# =============================================================================
# REBUILD ONE GAME FROM ITS ZIP  (#348)
# =============================================================================
# Puts one game folder back to exactly what its own ZIP holds. The ZIP is unpacked and checked in a staging folder on
# the same drive (Invoke-TpmAutoSyncDirectoryTransaction); the old folder is never deleted: it is RENAMED to a kept place
# on the same drive (no copy) and stays there until the player puts it back or deletes it. The TeknoParrot profile is
# not touched: the game folder keeps its name and the transaction proves the ZIP holds the registered program.

function Format-TpmRebuildSize {
    param([int64]$Bytes)
    $invariant = [System.Globalization.CultureInfo]::InvariantCulture
    if ($Bytes -ge 1073741824) { return ((([double]$Bytes) / 1073741824).ToString('N1', $invariant) + ' GB') }
    if ($Bytes -ge 1048576) { return ((([double]$Bytes) / 1048576).ToString('N0', $invariant) + ' MB') }
    return (([Math]::Max([double]1, [Math]::Ceiling(([double]$Bytes) / 1024))).ToString('N0', $invariant) + ' KB')
}

# Where old game folders are kept: beside the games folder, so a rename stays on the same drive.
function Get-TpmRebuildKeptRoot {
    param([Parameter(Mandatory)][string]$InstallFolder)
    $root = [System.IO.Path]::GetFullPath($InstallFolder).TrimEnd([char[]]"\/")
    $parent = [System.IO.Path]::GetDirectoryName($root)
    if ([string]::IsNullOrWhiteSpace($parent)) { $parent = $root }
    return (Join-Path $parent 'TPM-old-game-folders')
}

function Test-TpmSameFolderPath {
    param([string]$First, [string]$Second)
    try { return ([System.IO.Path]::GetFullPath($First).TrimEnd([char[]]"\/") -ieq [System.IO.Path]::GetFullPath($Second).TrimEnd([char[]]"\/")) } catch { return $false }
}

# Names of programs running from inside a folder (a game that is open keeps its files locked).
function Get-TpmFolderProcesses {
    param([Parameter(Mandatory)][string]$Folder)
    $found = New-Object System.Collections.Generic.List[string]
    try {
        foreach ($process in @(Get-Process -ErrorAction Stop)) {
            try { if ($process.Path -and (Test-PathInside -child ([string]$process.Path) -parent $Folder)) { [void]$found.Add([string]$process.ProcessName) } } catch { }
        }
    } catch { Write-Log ('Rebuild: the running programs could not be listed -- ' + $_.Exception.Message) }
    return $found.ToArray()
}

# Registered games whose program lives in a folder directly inside the games folder.
function Get-TpmRebuildGames {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$InstallFolder)
    $games = New-Object System.Collections.Generic.List[object]
    $installFull = [System.IO.Path]::GetFullPath($InstallFolder).TrimEnd([char[]]"\/")
    foreach ($file in @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter '*.xml' -File -ErrorAction SilentlyContinue)) {
        try {
            $doc = Read-Xml $file.FullName
            $pathNode = if ($doc.GameProfile) { $doc.GameProfile.SelectSingleNode('GamePath') } else { $null }
            if ($null -eq $pathNode -or [string]::IsNullOrWhiteSpace($pathNode.InnerText)) { continue }
            $gamePath = [System.IO.Path]::GetFullPath($pathNode.InnerText.Trim())
            if (-not (Test-PathInside -child $gamePath -parent $installFull)) { continue }
            $relative = $gamePath.Substring($installFull.Length).TrimStart([char[]]"\/")
            if ($relative -notmatch '[\\/]') { continue }
            $firstPart = ($relative -split '[\\/]')[0]
            $folder = Join-Path $installFull $firstPart
            if (-not (Test-Path -LiteralPath $folder -PathType Container)) { continue }
            [void]$games.Add([pscustomobject]@{
                Code = $file.BaseName
                Name = (Get-TpmGameDisplayLabel -ProfilePath $file.FullName -Fallback $file.BaseName)
                Folder = $folder
                GamePath = $gamePath
            })
        } catch { Write-Log ('Rebuild: a game settings file could not be read ({0}) -- {1}' -f $file.Name, $_.Exception.Message) }
    }
    return @($games | Sort-Object -Property Name, Code)
}

# The ZIPs of the player's own ZIP folders that belong to this game folder, found the way AutoSync finds the folder of a ZIP.
function Find-TpmRebuildZips {
    param([Parameter(Mandatory)][string]$GameFolder, [Parameter(Mandatory)][string]$InstallFolder, [string[]]$ZipSources = @(), [hashtable]$DatIndex = $null, [string]$UserProfilesDir = '')
    $found = New-Object System.Collections.Generic.List[object]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $folderMap = Get-StagingFolderMap $InstallFolder
    foreach ($source in @($ZipSources | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique)) {
        if (-not (Test-Path -LiteralPath $source -PathType Container)) { continue }
        foreach ($zip in @(Get-TpmTopLevelZipSourceFiles -ZipSource $source -ProgressLabel 'Rebuild ZIP search')) {
            $rawName = [System.IO.Path]::GetFileNameWithoutExtension($zip.Name)
            if ($rawName -like '!TeknoParrot Collection*') { continue }
            $resolved = Resolve-ExtractedGameFolder -RawZipName $rawName -InstallFolder $InstallFolder -FolderMap $folderMap -DatIndex $DatIndex -UserProfilesDir $UserProfilesDir
            if ($resolved -and (Test-TpmSameFolderPath -First $resolved -Second $GameFolder) -and $seen.Add([string]$zip.FullName)) { [void]$found.Add($zip) }
        }
    }
    return $found.ToArray()
}

# What the DAT lists for one game (named like its ZIP): file name, size and hashes. $null when no DAT can be read or the
# game is not in it; the DAT check is then skipped and the screen says so.
function Get-TpmDatFilesForGame {
    param([Parameter(Mandatory)][string]$GameName, [string]$EggmanDatZip = '', [string]$DatFilePath = '', [string]$SupplementaryDatPath = '')
    $sources = @(
        @{ Kind = 'File'; Path = $DatFilePath }
        @{ Kind = 'Zip'; Path = $EggmanDatZip; Pattern = '*Collection*_RomVault*.dat' }
        @{ Kind = 'File'; Path = $SupplementaryDatPath }
        @{ Kind = 'Zip'; Path = $EggmanDatZip; Pattern = '*Supplementary*_RomVault*.dat' }
    )
    foreach ($source in $sources) {
        if ([string]::IsNullOrWhiteSpace([string]$source.Path) -or -not (Test-Path -LiteralPath ([string]$source.Path) -PathType Leaf)) { continue }
        $sink = @{}
        try {
            if ($source.Kind -eq 'File') { [void](Build-DatIndex ([string]$source.Path) -EmuRomSink $sink -Quiet -CaptureGameNames @($GameName) -StopWhenCaptured) }
            else { [void](Build-DatIndexFromZip ([string]$source.Path) ([string]$source.Pattern) -EmuRomSink $sink -Quiet -CaptureGameNames @($GameName) -StopWhenCaptured) }
        } catch { Write-Log ('Rebuild: the DAT could not be read -- ' + $_.Exception.Message) }
        foreach ($key in @($sink.Keys)) {
            if ([string]$key -ieq $GameName) { return ,($sink[$key].ToArray()) }
        }
    }
    return $null
}

# Read-only look at what a rebuild would do. Never hashes the game folder (it can be many gigabytes).
function Get-TpmRebuildPreview {
    param([Parameter(Mandatory)][string]$ZipPath, [Parameter(Mandatory)][string]$GameFolder, [Parameter(Mandatory)][string]$InstallFolder, [object[]]$DatFiles = @())
    $inventory = Get-TpmAutoSyncZipInventory -ZipPath $ZipPath -SkipHash
    $zipFiles = @{}
    foreach ($entry in @($inventory.Entries)) {
        if (-not [bool](Get-TpmTransactionField -Object $entry -Name 'IsDirectory')) { $zipFiles[([string]$entry.RelativePath).ToLowerInvariant()] = [int64]$entry.Length }
    }
    $folderFull = [System.IO.Path]::GetFullPath($GameFolder).TrimEnd([char[]]"\/")
    $sameCount = 0; $differentCount = 0; $extraCount = 0; $folderCount = 0
    $folderKeys = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($file in @(Get-ChildItem -LiteralPath $folderFull -Recurse -File -Force -ErrorAction SilentlyContinue)) {
        $folderCount++
        $key = $file.FullName.Substring($folderFull.Length).TrimStart([char[]]"\/").ToLowerInvariant()
        [void]$folderKeys.Add($key)
        if (-not $zipFiles.ContainsKey($key)) { $extraCount++ }
        elseif ([int64]$zipFiles[$key] -eq [int64]$file.Length) { $sameCount++ }
        else { $differentCount++ }
    }
    $missingCount = @($zipFiles.Keys | Where-Object { -not $folderKeys.Contains([string]$_) }).Count
    $keptRoot = Get-TpmRebuildKeptRoot -InstallFolder $InstallFolder
    $transactionParent = [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($InstallFolder).TrimEnd([char[]]"\/"))
    if ([string]::IsNullOrWhiteSpace($transactionParent)) { $transactionParent = [System.IO.Path]::GetFullPath($InstallFolder) }
    $datState = 'NotChecked'
    $datSummary = 'The DAT list was not used (it is not loaded, or it does not list this game).'
    if (@($DatFiles).Count -gt 0) {
        $datCheck = Test-TpmZipFilesAgainstDatList -DatFiles $DatFiles -Inventory $inventory
        $datState = if ($datCheck.Matches) { 'Match' } else { 'Mismatch' }
        $datSummary = [string]$datCheck.Summary
    }
    return [pscustomobject]@{
        ZipFileCount = [int]$inventory.FileCount
        ZipBytes = [int64]$inventory.TotalBytes
        FolderFileCount = $folderCount
        SameCount = $sameCount
        DifferentCount = $differentCount
        MissingCount = $missingCount
        ExtraCount = $extraCount
        KeptRoot = $keptRoot
        SpaceState = (Get-TpmAutoSyncStagingSpaceState -Path $transactionParent -RequiredBytes ([int64]$inventory.TotalBytes))
        DatState = $datState
        DatSummary = $datSummary
    }
}

# The checked rebuild itself (no questions). One transaction: stage and check the ZIP, rename the old folder to a kept
# place, rename the new one into its place, commit the AutoSync record, verify. Any failure puts the old folder back.
function Invoke-TpmRebuildGame {
    param(
        [Parameter(Mandatory)]$Game,
        [Parameter(Mandatory)][string]$ZipPath,
        [Parameter(Mandatory)][string]$InstallFolder,
        [Parameter(Mandatory)][string]$SyncStatePath,
        [object[]]$DatFiles = @()
    )
    $rawName = [System.IO.Path]::GetFileNameWithoutExtension($ZipPath)
    $stateCheck = Test-TpmAutoSyncStateFile -Path $SyncStatePath
    if ($stateCheck.Status -eq 'Invalid') {
        Write-Log ('Rebuild: stopped before any change; the AutoSync record is unusable -- ' + [string]$stateCheck.Reason)
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'SYNC_STATE_UNUSABLE' -Summary 'Nothing was changed. The file where AutoSync keeps its records could not be read. Run AutoSync once from the main menu, and it will tell you what to do.')
    }
    $syncState = $stateCheck.State
    $stamp = (Get-Date).ToString('yyyy-MM-dd_HH-mm-ss', [System.Globalization.CultureInfo]::InvariantCulture)
    $keptRoot = Get-TpmRebuildKeptRoot -InstallFolder $InstallFolder
    $keptPath = Join-Path $keptRoot ([System.IO.Path]::GetFileName(([string]$Game.Folder).TrimEnd([char[]]"\/")) + '_' + $stamp)
    Write-Log ('Rebuild: starting for {0} ({1}) from {2}; the old folder will be kept at {3}.' -f $Game.Name, $Game.Code, $ZipPath, $keptPath)
    $tx = Invoke-TpmAutoSyncDirectoryTransaction -ZipPath $ZipPath -InstallFolder $InstallFolder -TargetDir ([string]$Game.Folder) `
        -RawName $rawName -SyncStatePath $SyncStatePath -SyncState $syncState -StoredState $syncState[$rawName] `
        -RegisteredGamePath ([string]$Game.GamePath) -KeepOldTargetAt $keptPath -ExpectedDatFiles $DatFiles
    $txResult = $tx.TransactionResult
    $details = Get-TpmTransactionField -Object $txResult -Name 'TechnicalDetails'
    $keptAt = [string](Get-TpmTransactionField -Object $details -Name 'OldFolderKeptAt' -Default '')
    $outcome = [string]$txResult.Outcome
    $reason = [string]$txResult.ReasonCode
    Write-Log ('Rebuild: {0} finished with {1} ({2}). Old folder kept at: {3}. DAT check: {4}.' -f $Game.Name, $outcome, $reason, $(if ($keptAt) { $keptAt } else { 'not kept' }), [string](Get-TpmTransactionField -Object $details -Name 'DatCheck' -Default 'not used'))
    # A finished transaction whose cleanup left something behind still decided the files: judge it by what it decided.
    $effective = $outcome
    if ($outcome -eq 'CLEANUP_RESIDUE') {
        $underlying = [string](Get-TpmTransactionField -Object $txResult -Name 'UnderlyingOutcome' -Default '')
        if ($underlying) { $effective = $underlying }
    }
    if ($effective -in @('SUCCEEDED', 'NO_OP') -and -not [bool]$tx.FilesystemChanged) {
        return (New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'ALREADY_MATCHES' -Summary 'Nothing was changed. The game folder already has exactly the files that are in the ZIP.')
    }
    if ($effective -eq 'SUCCEEDED') {
        if ($keptAt) {
            try {
                $record = [ordered]@{ SchemaVersion = 1; CreatedUtc = (Get-Date).ToUniversalTime().ToString('o'); GameFolder = [string]$Game.Folder; KeptFolder = $keptAt; Code = [string]$Game.Code; Name = [string]$Game.Name; Zip = $ZipPath }
                Write-TpmAtomicTextFile -Path ($keptAt + '.tpm.json') -Text (($record | ConvertTo-Json -Depth 4) + "`r`n") -Operation 'rebuild record write'
            } catch { Write-Log ('Rebuild: the record of the kept folder could not be saved (the folder is still there) -- ' + $_.Exception.Message) }
        } else {
            # The rename to the kept place did not finish; the old folder is still inside the transaction folder.
            $residue = Get-TpmTransactionField -Object $txResult -Name 'Cleanup'
            $residuePaths = @(Get-TpmTransactionField -Object $residue -Name 'ResiduePaths' -Default @())
            if ($residuePaths.Count -gt 0 -and $residuePaths[0]) { $keptAt = Join-Path ([string]$residuePaths[0]) 'rollback\old-target' }
        }
        return (New-TpmResetRestoreResult -Outcome 'SUCCEEDED' -ReasonCode 'REBUILT' -Summary ('Done. {0} was rebuilt from its ZIP and checked. Your old folder was not deleted. It is kept here: {1}' -f $Game.Name, $keptAt) -ChangedItems @([string]$Game.Folder))
    }
    if ($effective -eq 'ROLLED_BACK_VERIFIED') {
        return (New-TpmResetRestoreResult -Outcome 'ROLLED_BACK_VERIFIED' -ReasonCode 'ROLLED_BACK' -Summary 'The rebuild did not finish. Your old folder was put back exactly as it was.')
    }
    if ($effective -eq 'FAILED_BEFORE_MUTATION') {
        $plain = switch ($reason) {
            'INSUFFICIENT_STAGING_SPACE' { 'There is not enough free space for the rebuild. Free some space on the drive of your games folder and try again. Nothing was changed.' }
            'STAGING_SPACE_UNAVAILABLE' { 'TeknoParrot Manager could not tell how much free space there is, so it did not start. Nothing was changed.' }
            'DAT_MISMATCH' { 'This ZIP does not match the DAT list, so it may be damaged or a different version. Nothing was changed.' }
            'AMBIGUOUS_EXTRACTION_ROOT' { 'This ZIP does not hold the game program that TeknoParrot has for this game, so it was not used. Nothing was changed.' }
            default { 'The rebuild stopped before anything was replaced. Nothing was changed.' }
        }
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode $(if ($reason) { $reason } else { 'STOPPED_BEFORE_CHANGE' }) -Summary $plain)
    }
    return (New-TpmResetRestoreResult -Outcome 'ACTION_REQUIRED' -ReasonCode $(if ($reason) { $reason } else { 'NEEDS_ATTENTION' }) -Summary 'The rebuild stopped and TeknoParrot Manager could not prove the final state. Do not run it again yet. Open the log from the main menu (L) and see Details.')
}

# Old folders kept by rebuilds (the folders in the kept place, with the record of each rebuild when there is one).
function Get-TpmRebuildKeptFolders {
    param([Parameter(Mandatory)][string]$InstallFolder)
    $keptRoot = Get-TpmRebuildKeptRoot -InstallFolder $InstallFolder
    $kept = New-Object System.Collections.Generic.List[object]
    if (-not (Test-Path -LiteralPath $keptRoot -PathType Container)) { return @() }
    foreach ($dir in @(Get-ChildItem -LiteralPath $keptRoot -Directory -ErrorAction SilentlyContinue | Sort-Object -Property LastWriteTime -Descending)) {
        $recordPath = $dir.FullName + '.tpm.json'
        $record = $null
        if (Test-Path -LiteralPath $recordPath -PathType Leaf) {
            try { $record = [System.IO.File]::ReadAllText($recordPath) | ConvertFrom-Json -ErrorAction Stop } catch { $record = $null }
        }
        # Only a folder TeknoParrot Manager can show it kept (its own record names this exact folder) is offered.
        if ($null -eq $record -or -not $record.PSObject.Properties['KeptFolder'] -or -not (Test-TpmSameFolderPath -First ([string]$record.KeptFolder) -Second $dir.FullName)) { continue }
        [void]$kept.Add([pscustomobject]@{ Name = [string]$dir.Name; Path = [string]$dir.FullName; RecordPath = $recordPath; Record = $record })
    }
    return $kept.ToArray()
}

# Undo: the rebuilt folder is renamed aside (kept too) and the old folder is renamed back. No copying. If the second
# rename fails, the first is undone, so the game folder is never left missing.
function Restore-TpmRebuildKeptFolder {
    param([Parameter(Mandatory)]$Kept, [Parameter(Mandatory)][string]$InstallFolder)
    $record = $Kept.Record
    $gameFolder = if ($null -ne $record -and $record.PSObject.Properties['GameFolder']) { [string]$record.GameFolder } else { '' }
    if ([string]::IsNullOrWhiteSpace($gameFolder) -or -not (Test-TpmAutoSyncDirectChildTarget -TargetDir $gameFolder -InstallFolder $InstallFolder)) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'NO_RECORD' -Summary 'Nothing was changed. TeknoParrot Manager does not know which game this old folder belongs to, so it cannot put it back. You can move it back yourself.')
    }
    if (-not (Test-TpmNoReparsePath -Path $gameFolder) -or -not (Test-TpmNoReparsePath -Path ([string]$Kept.Path))) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'UNSAFE_PATH' -Summary 'Nothing was changed. One of the folders is a link, which is not safe to swap.')
    }
    $running = @(Get-TpmFolderProcesses -Folder $gameFolder)
    if ($running.Count -gt 0) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'GAME_RUNNING' -Summary 'Nothing was changed. The game is running. Close it and try again.')
    }
    $keptRoot = Get-TpmRebuildKeptRoot -InstallFolder $InstallFolder
    $aside = Join-Path $keptRoot (([System.IO.Path]::GetFileName($gameFolder.TrimEnd([char[]]"\/"))) + '_rebuilt_' + (Get-Date).ToString('yyyy-MM-dd_HH-mm-ss', [System.Globalization.CultureInfo]::InvariantCulture))
    $movedAside = $false
    try {
        if (Test-Path -LiteralPath $gameFolder) {
            Invoke-TpmAutoSyncMovePath -Source $gameFolder -Destination $aside
            $movedAside = $true
        }
        Invoke-TpmAutoSyncMovePath -Source ([string]$Kept.Path) -Destination $gameFolder
    } catch {
        Write-Log ('Rebuild undo: failed -- ' + $_.Exception.Message)
        if ($movedAside -and -not (Test-Path -LiteralPath $gameFolder)) {
            try { Invoke-TpmAutoSyncMovePath -Source $aside -Destination $gameFolder }
            catch { return (New-TpmResetRestoreResult -Outcome 'ACTION_REQUIRED' -ReasonCode 'UNDO_UNVERIFIED' -Summary ('The undo stopped and the game folder could not be put back. The files are safe in: {0} and {1}' -f $aside, [string]$Kept.Path)) }
        }
        return (New-TpmResetRestoreResult -Outcome 'ROLLED_BACK_VERIFIED' -ReasonCode 'UNDO_ROLLED_BACK' -Summary 'The undo did not finish. The game folder is as it was before.')
    }
    try { if (Test-Path -LiteralPath ([string]$Kept.RecordPath)) { Remove-Item -LiteralPath ([string]$Kept.RecordPath) -Force -ErrorAction Stop } } catch { Write-Log ('Rebuild undo: the record could not be removed -- ' + $_.Exception.Message) }
    # The rebuilt folder is kept now, with its own record, so it can be put back or deleted later like any other kept folder.
    try {
        $asideRecord = [ordered]@{ SchemaVersion = 1; CreatedUtc = (Get-Date).ToUniversalTime().ToString('o'); GameFolder = $gameFolder; KeptFolder = $aside; Code = [string]$record.Code; Name = ([string]$record.Name + ' (rebuilt copy)'); Zip = [string]$record.Zip }
        if ($movedAside) { Write-TpmAtomicTextFile -Path ($aside + '.tpm.json') -Text (($asideRecord | ConvertTo-Json -Depth 4) + "`r`n") -Operation 'rebuild record write' }
    } catch { Write-Log ('Rebuild undo: the record of the kept rebuilt folder could not be saved -- ' + $_.Exception.Message) }
    Write-Log ('Rebuild undo: {0} was put back from {1}; the rebuilt folder is kept at {2}.' -f $gameFolder, $Kept.Path, $aside)
    return (New-TpmResetRestoreResult -Outcome 'SUCCEEDED' -ReasonCode 'UNDONE' -Summary ('Your old folder is back. The rebuilt folder was not deleted. It is kept here: {0}' -f $aside) -ChangedItems @($gameFolder))
}

# The player's decision to throw an old folder away (only ever called after YES).
function Remove-TpmRebuildKeptFolder {
    param([Parameter(Mandatory)]$Kept, [Parameter(Mandatory)][string]$InstallFolder)
    $keptRoot = Get-TpmRebuildKeptRoot -InstallFolder $InstallFolder
    if ($null -eq $Kept.Record -or -not (Test-PathInside -child ([string]$Kept.Path) -parent $keptRoot) -or (Test-TpmSameFolderPath -First ([string]$Kept.Path) -Second $keptRoot)) {
        return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'NOT_A_KEPT_FOLDER' -Summary 'Nothing was deleted. TeknoParrot Manager cannot show that it kept that folder.')
    }
    try {
        Invoke-TpmAutoSyncRemovePath -Path ([string]$Kept.Path)
        if (Test-Path -LiteralPath ([string]$Kept.RecordPath)) { Remove-Item -LiteralPath ([string]$Kept.RecordPath) -Force -ErrorAction SilentlyContinue }
    } catch {
        Write-Log ('Rebuild: deleting a kept folder failed -- ' + $_.Exception.Message)
        return (New-TpmResetRestoreResult -Outcome 'ACTION_REQUIRED' -ReasonCode 'DELETE_INCOMPLETE' -Summary ('The old folder could not be deleted completely. You can delete it yourself: {0}' -f [string]$Kept.Path))
    }
    Write-Log ('Rebuild: the kept old folder {0} was deleted at the player''s request.' -f $Kept.Path)
    return (New-TpmResetRestoreResult -Outcome 'SUCCEEDED' -ReasonCode 'KEPT_FOLDER_DELETED' -Summary 'The old folder was deleted.')
}

# Rebuild one chosen game: find the ZIP, show what will happen, ask, then rebuild.
function Invoke-TpmRebuildOneGame {
    param(
        [Parameter(Mandatory)]$Game,
        [Parameter(Mandatory)][string]$InstallFolder,
        [string[]]$ZipSources = @(),
        [Parameter(Mandatory)][string]$SyncStatePath,
        [hashtable]$DatIndex = $null,
        [string]$UserProfilesDir = '',
        [string]$EggmanDatZip = '',
        [string]$DatFilePath = '',
        [string]$SupplementaryDatPath = ''
    )
    $nothingChanged = { param($Reason, $Text) return (New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode $Reason -Summary $Text) }
    $running = @(Get-TpmFolderProcesses -Folder ([string]$Game.Folder))
    if ($running.Count -gt 0) {
        return (& $nothingChanged 'GAME_RUNNING' ('{0} is running. Close it and try again. Nothing was changed.' -f $Game.Name))
    }
    $zips = @(Find-TpmRebuildZips -GameFolder ([string]$Game.Folder) -InstallFolder $InstallFolder -ZipSources $ZipSources -DatIndex $DatIndex -UserProfilesDir $UserProfilesDir)
    if ($zips.Count -eq 0) {
        Write-Log ('Rebuild: no ZIP found for {0} ({1}) in: {2}' -f $Game.Name, $Game.Code, (@($ZipSources | Where-Object { $_ }) -join '; '))
        return (& $nothingChanged 'ZIP_NOT_FOUND' ('TeknoParrot Manager could not find the ZIP for {0}. Nothing was changed. Put the game''s ZIP in the ZIP folder you use for AutoSync, then try again.' -f $Game.Name))
    }
    $zip = $zips[0]
    if ($zips.Count -gt 1) {
        $rows = @($zips | ForEach-Object { '{0} ({1})' -f $_.Name, (Format-TpmRebuildSize -Bytes ([int64]$_.Length)) })
        $picked = Read-TpmNumberedListChoice -Rows $rows -Prompt '  Choose a number, or B to go back' -Heading 'More than one ZIP fits this game. Which one do you want to use?'
        if ($picked -lt 0) { return (New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'USER_CANCELLED' -Summary 'Canceled. Nothing was changed.') }
        $zip = $zips[$picked]
    }
    $rawName = [System.IO.Path]::GetFileNameWithoutExtension([string]$zip.Name)
    Write-TpmResetRestoreText -Text 'Looking at the ZIP...' -Color DarkGray
    $datFiles = Get-TpmDatFilesForGame -GameName $rawName -EggmanDatZip $EggmanDatZip -DatFilePath $DatFilePath -SupplementaryDatPath $SupplementaryDatPath
    if ($null -eq $datFiles) { $datFiles = @() } else { $datFiles = @($datFiles) }
    try {
        $preview = Get-TpmRebuildPreview -ZipPath ([string]$zip.FullName) -GameFolder ([string]$Game.Folder) -InstallFolder $InstallFolder -DatFiles $datFiles
    } catch {
        Write-Log ('Rebuild: the ZIP could not be read -- ' + $_.Exception.Message)
        return (& $nothingChanged 'ZIP_UNREADABLE' ('The ZIP for {0} could not be read, so it was not used. Nothing was changed.' -f $Game.Name))
    }
    if ($preview.SpaceState -eq 'Short') {
        return (& $nothingChanged 'INSUFFICIENT_STAGING_SPACE' ('There is not enough free space for the rebuild. It needs about {0} free on the drive of your games folder. Free some space and try again. Nothing was changed.' -f (Format-TpmRebuildSize -Bytes $preview.ZipBytes)))
    }
    if ($preview.DatState -eq 'Mismatch') {
        Write-Log ('Rebuild: the ZIP does not match the DAT list -- ' + $preview.DatSummary)
        return (& $nothingChanged 'DAT_MISMATCH' 'This ZIP does not match the DAT list, so it may be damaged or a different version. Nothing was changed.')
    }
    Write-Host ''
    Write-TpmResetRestoreText -Text ('Game: {0}' -f $Game.Name) -Color Yellow
    Write-TpmResetRestoreText -Text ('ZIP: {0}' -f $zip.Name)
    Write-Host ''
    Write-TpmResetRestoreText -Text ('The new folder will hold exactly the {0} in the ZIP ({1}).' -f (Format-TpmCountNoun -Count $preview.ZipFileCount -Singular 'file'), (Format-TpmRebuildSize -Bytes $preview.ZipBytes))
    if ($preview.ExtraCount -gt 0) {
        Write-TpmResetRestoreText -Text ('{0} in your current folder are not in the ZIP (for example saves or your own settings). They stay in the old folder, which is kept.' -f (Format-TpmCountNoun -Count $preview.ExtraCount -Singular 'file'))
    }
    Write-Host ''
    Write-TpmResetRestoreText -Text 'What happens:'
    Write-TpmResetRestoreText -Text '1. The ZIP is unpacked and checked in a temporary folder on the same drive.' -Indent 4 -HangingIndent 3
    Write-TpmResetRestoreText -Text '2. Your current folder is renamed and kept. Nothing is copied or deleted.' -Indent 4 -HangingIndent 3
    Write-TpmResetRestoreText -Text '3. The new folder takes its place.' -Indent 4 -HangingIndent 3
    Write-TpmResetRestoreText -Text ('Your old folder will be kept in: {0}' -f $preview.KeptRoot)
    Write-TpmResetRestoreText -Text 'If anything goes wrong, your old folder is put back. The TeknoParrot settings for this game are not changed.' -Color DarkGray
    $datLine = if ($preview.DatState -eq 'Match') { 'The ZIP matches the DAT list.' } else { 'The DAT list does not cover this game, so the ZIP was checked against itself only.' }
    Write-TpmResetRestoreText -Text $datLine -Color DarkGray
    $blocks = @(@{ Heading = 'Technical details'; Lines = @(
        ('ZIP: {0}' -f $zip.FullName),
        ('Game folder: {0}' -f $Game.Folder),
        ('Profile: {0}' -f $Game.Code),
        ('Files in your folder: {0} ({1} look the same, {2} differ, {3} are not in the ZIP)' -f $preview.FolderFileCount, $preview.SameCount, $preview.DifferentCount, $preview.ExtraCount),
        ('Files in the ZIP that are missing in your folder: {0}' -f $preview.MissingCount),
        ('DAT: {0}' -f $preview.DatSummary),
        ('Old folder will be kept in: {0}' -f $preview.KeptRoot)
    ) })
    Write-Host ''
    $confirm = Read-TpmResetRestoreAnswer -Intro 'Any answer other than YES cancels, and nothing is changed.' -Prompt 'Type YES to rebuild this game' -DetailBlocks $blocks
    if ($confirm.Trim().ToUpperInvariant() -ne 'YES') { return (New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'USER_DECLINED' -Summary 'Canceled. Nothing was changed.') }
    return (Invoke-TpmRebuildGame -Game $Game -ZipPath ([string]$zip.FullName) -InstallFolder $InstallFolder -SyncStatePath $SyncStatePath -DatFiles $datFiles)
}

# The menu: rebuild one game, put an old folder back, or delete a kept old folder.
function Invoke-TpmRebuildMenu {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [AllowEmptyString()][string]$InstallFolder = '',
        [string[]]$ZipSources = @(),
        [hashtable]$DatIndex = $null,
        [string]$EggmanDatZip = '',
        [string]$DatFilePath = '',
        [string]$SupplementaryDatPath = ''
    )
    Write-TpmResetRestoreHeader -Title 'Rebuild a game from its ZIP'
    Write-Host ''
    Write-TpmResetRestoreText -Text 'This puts one game folder back to exactly what is in its original ZIP. Use it when a game is broken and you do not know why.'
    Write-TpmResetRestoreText -Text 'Your old folder is not deleted. It is kept aside, so you can put it back.'
    if ([string]::IsNullOrWhiteSpace($InstallFolder) -or -not (Test-Path -LiteralPath $InstallFolder -PathType Container)) {
        Write-TpmResetRestoreText -Text 'There is no games folder set up yet, so there is nothing to rebuild. Run AutoSync or Register only once from the main menu first.' -Color Yellow
        return
    }
    $syncStatePath = Join-Path $InstallFolder 'TeknoParrot-Manager.syncstate.json'
    while ($true) {
        Write-Host ''
        Write-TpmResetRestoreText -Text '1) Rebuild one game from its ZIP' -HangingIndent 3
        Write-TpmResetRestoreText -Text '2) Put an old folder back (undo a rebuild)' -HangingIndent 3
        Write-TpmResetRestoreText -Text '3) Delete an old folder I no longer need' -HangingIndent 3
        Write-Host ''
        Write-TpmResetRestoreText -Text 'B) Back' -HangingIndent 3
        $choice = Read-TpmChoice -Prompt '  Choose 1-3, or B to go back' -Choices @('1', '2', '3', 'B') -Default 'B'
        if ($choice -eq 'B') { return }
        $result = $null
        try {
            if ($choice -eq '1') {
                if (@($ZipSources | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }).Count -eq 0) {
                    $result = New-TpmResetRestoreResult -Outcome 'FAILED_BEFORE_MUTATION' -ReasonCode 'NO_ZIP_FOLDER' -Summary 'There is no ZIP folder set up, so there is no ZIP to rebuild from. Nothing was changed. Run AutoSync once from the main menu and choose your ZIP folder.'
                } else {
                    $games = @(Get-TpmRebuildGames -UserProfilesDir $UserProfilesDir -InstallFolder $InstallFolder)
                    if ($games.Count -eq 0) {
                        $result = New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'NO_GAMES' -Summary 'No registered game was found in your games folder. Nothing was changed.'
                    } else {
                        $rows = @($games | ForEach-Object { $name = $_.Name; if (@($games | Where-Object { $_.Name -ieq $name }).Count -gt 1) { '{0} ({1})' -f $name, [System.IO.Path]::GetFileName([string]$_.Folder) } else { [string]$name } })
                        $picked = Read-TpmNumberedListChoice -Rows $rows -Prompt '  Choose a number, or B to go back' -Heading 'Which game do you want to rebuild?'
                        if ($picked -ge 0) {
                            $result = Invoke-TpmRebuildOneGame -Game $games[$picked] -InstallFolder $InstallFolder -ZipSources $ZipSources -SyncStatePath $syncStatePath -DatIndex $DatIndex -UserProfilesDir $UserProfilesDir -EggmanDatZip $EggmanDatZip -DatFilePath $DatFilePath -SupplementaryDatPath $SupplementaryDatPath
                        }
                    }
                }
            } else {
                $keptList = @(Get-TpmRebuildKeptFolders -InstallFolder $InstallFolder)
                if ($keptList.Count -eq 0) {
                    $result = New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'NOTHING_KEPT' -Summary 'There are no old folders kept from a rebuild.'
                } else {
                    $rows = @($keptList | ForEach-Object {
                        $label = if ($null -ne $_.Record -and $_.Record.PSObject.Properties['Name']) { [string]$_.Record.Name } else { [string]$_.Name }
                        '{0} - {1}' -f $label, $_.Name
                    })
                    $picked = Read-TpmNumberedListChoice -Rows $rows -Prompt '  Choose a number, or B to go back' -Heading 'Old folders that were kept:'
                    if ($picked -ge 0) {
                        $kept = $keptList[$picked]
                        Write-Host ''
                        Write-TpmResetRestoreText -Text ('Folder: {0}' -f $kept.Path) -Color Yellow
                        $confirm = Read-TpmResetRestoreAnswer -Intro 'Any answer other than YES cancels, and nothing is changed.' -Prompt ('Type YES to {0}' -f $(if ($choice -eq '2') { 'put it back' } else { 'delete it for good' }))
                        if ($confirm.Trim().ToUpperInvariant() -ne 'YES') {
                            $result = New-TpmResetRestoreResult -Outcome 'NO_OP' -ReasonCode 'USER_DECLINED' -Summary 'Canceled. Nothing was changed.'
                        } elseif ($choice -eq '2') {
                            $result = Restore-TpmRebuildKeptFolder -Kept $kept -InstallFolder $InstallFolder
                        } else {
                            $result = Remove-TpmRebuildKeptFolder -Kept $kept -InstallFolder $InstallFolder
                        }
                    }
                }
            }
        } catch {
            Write-Log ('Rebuild: stopped unexpectedly -- ' + $_.Exception.Message)
            $result = New-TpmResetRestoreResult -Outcome 'ACTION_REQUIRED' -ReasonCode 'STOPPED_UNEXPECTEDLY' -Summary 'The rebuild stopped unexpectedly. Open the log from the main menu (L) to see why. Check your game folder before you try again.'
        }
        if ($null -ne $result) { Write-TpmResetRestoreResult -Result $result }
    }
}

# PS5.1-compatible relative paths; retain an absolute path across volumes.
# Plain path parts, not System.Uri: on PowerShell 7 a folder named save%41 came back as saveA.
function Get-RelativePath {
    param([string]$basePath, [string]$targetPath)
    $baseFull = [System.IO.Path]::GetFullPath($basePath)
    $targetFull = [System.IO.Path]::GetFullPath($targetPath)
    $baseParts = @($baseFull.Split('\', [System.StringSplitOptions]::RemoveEmptyEntries))
    $targetParts = @($targetFull.Split('\', [System.StringSplitOptions]::RemoveEmptyEntries))
    $common = 0
    while ($common -lt $baseParts.Count -and $common -lt $targetParts.Count -and [string]::Equals($baseParts[$common], $targetParts[$common], [System.StringComparison]::OrdinalIgnoreCase)) { $common++ }
    # A UNC share (\\server\share) is the root: two shares on one server share nothing, and ".." cannot climb out of a share.
    $rootParts = if ($baseFull.StartsWith('\\')) { 2 } else { 1 }
    if ($common -lt $rootParts) { return $targetFull }
    $steps = @('..') * ($baseParts.Count - $common) + @($targetParts | Select-Object -Skip $common)
    return ($steps -join '\')
}

# LaunchBox: verified backup, staged per-file commit, compensating rollback.
# Process checks reduce but cannot eliminate the owner-accepted reopen race.
function Test-LaunchBoxRunning {
    try {
        return [bool](@(Get-Process -ErrorAction Stop | Where-Object { $_.ProcessName -in @('LaunchBox','BigBox') }).Count)
    } catch {
        # Windows refused to list every process: look only for the two names. If even that fails, assume LaunchBox may be open (never write then).
        try {
            return [bool](@([System.Diagnostics.Process]::GetProcessesByName('LaunchBox')).Count + @([System.Diagnostics.Process]::GetProcessesByName('BigBox')).Count)
        } catch {
            Write-Log ("LaunchBox running check failed, assuming it may be open: {0}" -f $_.Exception.Message)
            return $true
        }
    }
}

function Get-SafeLaunchBoxPlatformFileName {
    param([string]$platformName)
    $clean = [regex]::Replace($platformName, '[\\/:*?"<>|]', '').Trim()
    if ([string]::IsNullOrWhiteSpace($clean)) { $clean = 'TeknoParrot' }
    return $clean
}

function Get-XmlChildText {
    param([System.Xml.XmlNode]$node, [string]$childName)
    $child = $node.SelectSingleNode($childName)
    if ($null -eq $child) { return '' }
    return $child.InnerText
}

function Set-XmlChildText {
    param([System.Xml.XmlNode]$node, [string]$childName, [string]$value)
    $child = $node.SelectSingleNode($childName)
    if ($null -eq $child) { $child = $node.OwnerDocument.CreateElement($childName); [void]$node.AppendChild($child) }
    $child.InnerText = $value
}

# Canonical absolute LaunchBox root, resolved once against the PowerShell location so validation and writes agree.
# A pasted path may carry quotes (Explorer "Copy as path"), so they are removed first; Get-TpmFullFolderPath finishes the path.
function Resolve-TpmLaunchBoxRoot {
    param([string]$Root)
    $text = ([string]$Root).Trim().Trim('"').Trim()
    if ([string]::IsNullOrWhiteSpace($text)) { throw 'Choose a safe existing LaunchBox root.' }
    return (Get-TpmFullFolderPath $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($text))
}

# Path equality for values stored in LaunchBox XML, which may be relative, quoted, URLs, or otherwise not valid file paths.
function Test-TpmLaunchBoxSamePath {
    param([string]$Root, [string]$Left, [string]$Right)
    if ($Left -ieq $Right) { return $true }
    try {
        $leftFull = if ([System.IO.Path]::IsPathRooted($Left)) { $Left } else { Join-Path $Root $Left }
        $rightFull = if ([System.IO.Path]::IsPathRooted($Right)) { $Right } else { Join-Path $Root $Right }
        return ([System.IO.Path]::GetFullPath($leftFull) -ieq [System.IO.Path]::GetFullPath($rightFull))
    } catch { return $false }
}

function Get-TpmLaunchBoxPath {
    param([string]$Root, [string]$RelativePath)
    if ([string]::IsNullOrWhiteSpace($Root)) { throw 'A LaunchBox root is required.' }
    if ($RelativePath -notmatch '^Data\\(?:Emulators\.xml|Platforms\.xml|(?:Platforms|Playlists)\\[^\\/:*?"<>|]+\.xml)$' -or
        @($RelativePath -split '\\' | Where-Object { $_ -in @('.','..') -or $_.EndsWith('.') -or $_.EndsWith(' ') }).Count) { throw 'Invalid LaunchBox library member path.' }
    if ([System.IO.Path]::GetFileName($RelativePath) -match '^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\..*)?$') { throw 'Reserved LaunchBox member filename.' }
    $full = [System.IO.Path]::GetFullPath((Join-Path $Root $RelativePath))
    if (-not (Test-PathInside -child $full -parent $Root) -or -not (Test-TpmNoReparsePath -Path $full)) { throw 'Unsafe LaunchBox library path.' }
    Assert-TpmNoReparseWriteTarget -Path $full -Operation 'LaunchBox file access'
    return $full
}

function Get-TpmLaunchBoxFileState {
    param([string]$Path)
    Assert-TpmNoReparseWriteTarget -Path $Path -Operation 'LaunchBox inventory'
    $exists = Test-Path -LiteralPath $Path -ErrorAction Stop
    if (-not $exists) { return [pscustomobject]@{ Exists=$false; Hash=$null; Length=0 } }
    $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    if ($item.PSIsContainer) { throw 'A LaunchBox file path is occupied by a directory.' }
    return [pscustomobject]@{ Exists=$true; Hash=(Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash; Length=$item.Length }
}

function Assert-TpmLaunchBoxState {
    param([string]$Path, $Expected)
    $actual = Get-TpmLaunchBoxFileState -Path $Path
    if ($actual.Exists -ne $Expected.Exists -or ($actual.Exists -and ($actual.Hash -ne $Expected.Hash -or $actual.Length -ne $Expected.Length))) { throw 'A LaunchBox target changed after inventory; refusing to overwrite it.' }
}

function Read-TpmLaunchBoxXml {
    param([string]$Path)
    # Whitespace is preserved so the readback comparison and the added entries see the same document the file contains.
    $doc = New-Object System.Xml.XmlDocument
    $doc.PreserveWhitespace = $true
    $doc.XmlResolver = $null
    $doc.Load($Path)
    if ($null -eq $doc.DocumentElement -or $doc.DocumentElement.Name -ne 'LaunchBox' -or $doc.DocumentElement.NamespaceURI -or $doc.DocumentType) { throw 'Unsupported LaunchBox XML root, namespace, or DTD.' }
    return $doc
}

# Per-user folder for LaunchBox safety backups that cannot be kept in TeknoParrot's own backup folder.
function Get-TpmLaunchBoxLocalBackupsRoot {
    $localAppData = [System.Environment]::GetFolderPath([System.Environment+SpecialFolder]::LocalApplicationData)
    if ([string]::IsNullOrWhiteSpace($localAppData)) { throw 'The per-user local data folder is not available, so LaunchBox safety backups cannot be kept outside the library.' }
    return (Join-Path (Join-Path $localAppData 'TeknoParrotManager') 'LaunchBoxBackups')
}

# One folder per library so two LaunchBox libraries never share a backup history: the first 16 hex characters of the
# SHA-256 of the lower-cased canonical library root.
function Get-TpmLaunchBoxFallbackBackupRoot {
    param([Parameter(Mandatory)][string]$LaunchBoxRoot)
    $canonical = [System.IO.Path]::GetFullPath($LaunchBoxRoot).TrimEnd('\','/').ToLowerInvariant()
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { $digest = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($canonical)) } finally { $sha.Dispose() }
    $key = [System.BitConverter]::ToString($digest).Replace('-','').Substring(0,16).ToLowerInvariant()
    return (Join-Path (Get-TpmLaunchBoxLocalBackupsRoot) $key)
}

# Where LaunchBox safety backups are kept. An explicit BackupRoot is used as given (Backup-LaunchBoxFiles still refuses
# one inside the library). Otherwise TeknoParrot's own backup folder is used, unless it is inside the library root
# (TeknoParrot installed under <LaunchBox>\Emulators); then the per-library folder under the user's local data is used.
# OwnedPath is TeknoParrot's own folder, so a restore can still list snapshots kept there.
function Resolve-TpmLaunchBoxBackupLocation {
    param([string]$BackupRoot, [string]$LaunchBoxRoot)
    $ownedPath = $null
    $usesFallback = $false
    if ($BackupRoot) {
        $selected = $BackupRoot
    } else {
        $ownedPath = [System.IO.Path]::GetFullPath((Join-Path (Get-TpmOwnedBackupsRoot -BackupName 'LaunchBoxBackups') 'LaunchBoxBackups'))
        $selected = $ownedPath
        if ($LaunchBoxRoot -and (Test-PathInside -child $ownedPath -parent $LaunchBoxRoot)) {
            $selected = Get-TpmLaunchBoxFallbackBackupRoot -LaunchBoxRoot $LaunchBoxRoot
            if (Test-PathInside -child $selected -parent $LaunchBoxRoot) { throw 'The per-user LaunchBox backup folder is inside the LaunchBox library; TPM will not keep safety backups there.' }
            $usesFallback = $true
        }
    }
    $full = [System.IO.Path]::GetFullPath($selected)
    if (-not (Test-TpmNoReparsePath -Path $full)) { throw 'Unsafe LaunchBox backup root.' }
    if ((Test-Path -LiteralPath $full -ErrorAction Stop) -and -not (Test-Path -LiteralPath $full -PathType Container -ErrorAction Stop)) { throw 'LaunchBox backup root is not a directory.' }
    return [pscustomobject]@{ Path=$full; UsesFallback=$usesFallback; OwnedPath=$ownedPath }
}

function Get-TpmLaunchBoxBackupRoot {
    param([string]$BackupRoot, [string]$LaunchBoxRoot)
    return (Resolve-TpmLaunchBoxBackupLocation -BackupRoot $BackupRoot -LaunchBoxRoot $LaunchBoxRoot).Path
}

function Backup-LaunchBoxFiles {
    param([string]$lbRoot, [object[]]$Items, [string]$BackupRoot, [ValidateSet('write','restore-safety')][string]$Operation = 'write')
    if (Test-LaunchBoxRunning) { throw 'Close LaunchBox and BigBox before backup; neither app will be force-closed.' }
    if (@($Items).Count -eq 0) { throw 'Cannot back up an empty LaunchBox target inventory.' }
    $backupBase = Get-TpmLaunchBoxBackupRoot -BackupRoot $BackupRoot -LaunchBoxRoot $lbRoot
    if (Test-PathInside -child $backupBase -parent $lbRoot) { throw 'LaunchBox safety backups must be outside the library root.' }
    $id = (Get-Date).ToString('yyyy-MM-dd_HH-mm-ss', [System.Globalization.CultureInfo]::InvariantCulture) + '-' + [guid]::NewGuid().ToString('N')
    $incompleteParent = Join-Path $backupBase '.tpm-incomplete'
    $incomplete = Join-Path $incompleteParent $id
    Assert-TpmNoReparseWriteTarget -Path $incomplete -Operation 'LaunchBox backup staging'
    # Remember whether this run creates the staging parent so a successful
    # publish can remove it again (only if it is then empty).
    $incompleteParentCreated = -not (Test-Path -LiteralPath $incompleteParent)
    [void][System.IO.Directory]::CreateDirectory($incomplete)
    $records = @()
    $seen = @{}
    $backupTotal = @($Items).Count
    $backupStarted = Get-Date
    $backupCurrent = 0
    $backupOutcome = 'Error'
    try {
        foreach ($item in $Items) {
            $backupCurrent++
            Write-TpmCompactExtractionProgress -Phase 'Backing up' -Label 'LaunchBox backup' -Current $backupCurrent -Total $backupTotal -StartedAt $backupStarted
            $src = Get-TpmLaunchBoxPath -Root $lbRoot -RelativePath $item.RelativePath
            if ($seen.ContainsKey($item.RelativePath)) { throw 'Duplicate LaunchBox backup member.' }
            $seen[$item.RelativePath] = $true
            Assert-TpmLaunchBoxState -Path $src -Expected $item.Before
            if ($item.Before.Exists) {
                $dst = Get-TpmLaunchBoxPath -Root $incomplete -RelativePath $item.RelativePath
                [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($dst))
                Assert-TpmNoReparseWriteTarget -Path $dst -Operation 'LaunchBox backup copy'
                Copy-Item -LiteralPath $src -Destination $dst -ErrorAction Stop
                Assert-TpmLaunchBoxState -Path $dst -Expected $item.Before
            }
            $records += [pscustomobject]@{ RelativePath=$item.RelativePath; Exists=[bool]$item.Before.Exists; Hash=$item.Before.Hash; Length=$item.Before.Length; CreatedHash=$item.AfterHash }
        }
        foreach ($item in $Items) { Assert-TpmLaunchBoxState -Path (Get-TpmLaunchBoxPath $lbRoot $item.RelativePath) -Expected $item.Before }
        $manifestPath = Join-Path $incomplete 'manifest.json'
        $text = [pscustomobject]@{ Schema=2; LaunchBoxRoot=$lbRoot; Operation=$Operation; Items=@($records) } | ConvertTo-Json -Depth 5
        $bytes = (New-Object System.Text.UTF8Encoding $false).GetBytes($text)
        $stream = [System.IO.File]::Open($manifestPath,[System.IO.FileMode]::CreateNew,[System.IO.FileAccess]::Write,[System.IO.FileShare]::None)
        try { $stream.Write($bytes,0,$bytes.Length); $stream.Flush($true) } finally { $stream.Dispose() }
        if ([System.IO.File]::ReadAllText($manifestPath) -cne $text) { throw 'LaunchBox backup manifest readback failed.' }
        foreach ($record in $records) {
            if ($record.Exists) { Assert-TpmLaunchBoxState (Get-TpmLaunchBoxPath $incomplete $record.RelativePath) $record }
        }
        $published = Join-Path $backupBase $id
        Assert-TpmNoReparseWriteTarget -Path $published -Operation 'LaunchBox backup publication'
        Move-TpmDirectoryWithRetry -Source $incomplete -Destination $published
        # Final is reported only once the verified snapshot is published; every earlier failure leaves the Error outcome.
        $backupOutcome = 'Final'
        # The per-run staging folder was moved out, which leaves the shared
        # '.tpm-incomplete' parent behind. Remove it only when this run created
        # it and it is now empty (non-recursive delete fails otherwise, e.g.
        # when another attempt is staging or a failed attempt left evidence).
        if ($incompleteParentCreated) {
            try {
                if (@(Get-ChildItem -LiteralPath $incompleteParent -Force -ErrorAction Stop).Count -eq 0) {
                    [System.IO.Directory]::Delete($incompleteParent, $false)
                }
            } catch {
                Write-Log "LaunchBox backup: left the empty staging folder '$incompleteParent' in place -- $($_.Exception.Message)"
            }
        }
        return [pscustomobject]@{ Path=$published; Verified=$true; Items=@($records) }
    } finally {
        Write-TpmCompactExtractionProgress -Phase 'Backing up' -Label 'LaunchBox backup' -Current $backupCurrent -Total $backupTotal -StartedAt $backupStarted -Complete -Outcome $backupOutcome
    }
}

# Builds the new bytes for an existing library file by inserting only the entries added to the root element into the
# original bytes. Everything else (BOM, declaration, line endings, indentation, whitespace-only values, character
# references, entry order) stays byte-identical, which re-serializing the DOM cannot guarantee.
function Get-TpmLaunchBoxSplicedBytes {
    param([string]$OriginalPath, [string]$OriginalHash, [System.Xml.XmlDocument]$Document, [int]$BaseChildCount)
    $bytes = [System.IO.File]::ReadAllBytes($OriginalPath)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { $actualHash = [System.BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-','') } finally { $sha.Dispose() }
    if ($OriginalHash -and $actualHash -ine $OriginalHash) { throw 'A LaunchBox target changed after inventory; refusing to stage it.' }
    $bomLength = 0
    if ($bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191) {
        $bomLength = 3; $encoding = New-Object System.Text.UTF8Encoding -ArgumentList @($false,$true)
    } elseif ($bytes.Length -ge 2 -and $bytes[0] -eq 255 -and $bytes[1] -eq 254) {
        $bomLength = 2; $encoding = New-Object System.Text.UnicodeEncoding -ArgumentList @($false,$false,$true)
    } elseif ($bytes.Length -ge 2 -and $bytes[0] -eq 254 -and $bytes[1] -eq 255) {
        $bomLength = 2; $encoding = New-Object System.Text.UnicodeEncoding -ArgumentList @($true,$false,$true)
    } else {
        $encoding = New-Object System.Text.UTF8Encoding -ArgumentList @($false,$true)
    }
    try { $text = $encoding.GetString($bytes,$bomLength,$bytes.Length - $bomLength) }
    catch { throw 'This LaunchBox XML file is not valid UTF-8/UTF-16 text; TPM will not edit it because that could change existing bytes.' }
    $children = $Document.DocumentElement.ChildNodes
    if ($BaseChildCount -lt 0 -or $children.Count -le $BaseChildCount) { throw 'No added LaunchBox entries were found to stage.' }
    $added = New-Object System.Text.StringBuilder
    for ($i = $BaseChildCount; $i -lt $children.Count; $i++) { [void]$added.Append($children.Item($i).OuterXml) }
    $endTag = '</LaunchBox>'
    $end = $text.LastIndexOf($endTag,[System.StringComparison]::Ordinal)
    if ($end -ge 0) {
        if ($text.Substring($end + $endTag.Length).Trim().Length -ne 0) { throw 'Unsupported content follows the LaunchBox root element.' }
        $replaceStart = $end; $replaceEnd = $end; $replacement = $added.ToString()
    } else {
        $selfClosed = [regex]::Match($text,'<LaunchBox(?:\s[^<>]*?)??(?<close>\s*/>)\s*$')
        if (-not $selfClosed.Success) { throw 'Unsupported LaunchBox root element layout.' }
        $close = $selfClosed.Groups['close']
        $replaceStart = $close.Index; $replaceEnd = $close.Index + $close.Length
        $replacement = '>' + $added.ToString() + $endTag
    }
    $startByte = $bomLength + $encoding.GetByteCount($text.Substring(0,$replaceStart))
    $endByte = $bomLength + $encoding.GetByteCount($text.Substring(0,$replaceEnd))
    $replacementBytes = $encoding.GetBytes($replacement)
    $output = New-Object System.IO.MemoryStream
    try {
        $output.Write($bytes,0,$startByte)
        $output.Write($replacementBytes,0,$replacementBytes.Length)
        $output.Write($bytes,$endByte,$bytes.Length - $endByte)
        return ,$output.ToArray()
    } finally { $output.Dispose() }
}

function New-TpmLaunchBoxStage {
    param([string]$Path, [System.Xml.XmlDocument]$Document, [string]$Source, [bool]$VerifyXml = $true, [string]$OriginalPath, [string]$OriginalHash, [int]$BaseChildCount, [switch]$FullRewrite)
    Assert-TpmNoReparseWriteTarget -Path $Path -Operation 'LaunchBox staging'
    $stream = [System.IO.File]::Open($Path,[System.IO.FileMode]::CreateNew,[System.IO.FileAccess]::Write,[System.IO.FileShare]::None)
    try {
        if ($Source) {
            $inputStream = [System.IO.File]::OpenRead($Source)
            try { $inputStream.CopyTo($stream) } finally { $inputStream.Dispose() }
        } elseif ($OriginalPath -and -not $FullRewrite) {
            $spliced = Get-TpmLaunchBoxSplicedBytes -OriginalPath $OriginalPath -OriginalHash $OriginalHash -Document $Document -BaseChildCount $BaseChildCount
            $stream.Write($spliced,0,$spliced.Length)
        } else {
            # A brand-new library file has no existing bytes to preserve.
            $settings = New-Object System.Xml.XmlWriterSettings
            $settings.Encoding = New-Object System.Text.UTF8Encoding $false
            $settings.Indent = $false
            $settings.NewLineHandling = [System.Xml.NewLineHandling]::Entitize
            $settings.CloseOutput = $false
            # Line breaks outside the root element (after the XML declaration) would be written as &#xD; and make the file unreadable, so drop them first.
            foreach ($top in @($Document.ChildNodes)) { if ($top.NodeType -in @([System.Xml.XmlNodeType]::Whitespace, [System.Xml.XmlNodeType]::SignificantWhitespace)) { [void]$Document.RemoveChild($top) } }
            $writer = [System.Xml.XmlWriter]::Create($stream,$settings)
            try { $Document.Save($writer); $writer.Flush() } finally { $writer.Dispose() }
        }
        $stream.Flush($true)
    } finally { $stream.Dispose() }
    if ($VerifyXml) {
        $readback = Read-TpmLaunchBoxXml -Path $Path
        if ($Document -and $readback.DocumentElement.OuterXml -cne $Document.DocumentElement.OuterXml) { throw 'LaunchBox staged XML readback differs from the proposed document.' }
    }
}

# Moves the original bytes aside under a name TPM owns when ReplaceFile fails after it has renamed the target.
function Restore-TpmLaunchBoxReplacedFile {
    param([string]$Path, [string]$ReplacedPath)
    if ([System.IO.File]::Exists($Path) -or -not [System.IO.File]::Exists($ReplacedPath)) { return $false }
    [System.IO.File]::Move($ReplacedPath,$Path)
    return $true
}

# Swaps the staged file in for the library file. Returns the path where File.Replace kept the bytes it replaced.
# A unique same-directory name keeps those bytes recoverable when ReplaceFile fails after renaming the target.
function Invoke-TpmLaunchBoxReplace {
    param([string]$StagePath, [string]$Path)
    $replaced = $Path + '.' + [guid]::NewGuid().ToString('N') + '.replaced'
    Assert-TpmNoReparseWriteTarget -Path $replaced -Operation 'LaunchBox commit'
    try { [System.IO.File]::Replace($StagePath,$Path,$replaced) }
    catch {
        $replaceError = $_
        try { [void](Restore-TpmLaunchBoxReplacedFile -Path $Path -ReplacedPath $replaced) }
        catch { throw ('LaunchBox commit failed ({0}) and the replaced file could not be put back; its bytes are retained at {1}: {2}' -f $replaceError.Exception.Message,$replaced,$_.Exception.Message) }
        throw $replaceError
    }
    return $replaced
}

# After File.Replace put this run's bytes over a newer save, puts the newer bytes back as the library file.
# The retained copy of them stays as evidence. Returns $true only when the bytes taken out again are exactly the ones put in.
function Restore-TpmLaunchBoxDisplacedFile {
    param([string]$Path, [string]$DisplacedPath, [string]$WrittenHash)
    $putBack = $Path + '.' + [guid]::NewGuid().ToString('N') + '.tmp'
    try {
        Assert-TpmNoReparseWriteTarget -Path $putBack -Operation 'LaunchBox put-back'
        [System.IO.File]::Copy($DisplacedPath,$putBack)
        $taken = Invoke-TpmLaunchBoxReplace -StagePath $putBack -Path $Path
        if ((Get-FileHash -LiteralPath $taken -Algorithm SHA256 -ErrorAction Stop).Hash -ne $WrittenHash) {
            Write-Log ('LaunchBox put-back: the library changed again; the bytes taken out are retained at {0}.' -f $taken)
            return $false
        }
        try { [System.IO.File]::Delete($taken) }
        catch { Write-Log ('LaunchBox put-back: could not remove the replaced-file copy {0}; it was retained.' -f $taken) }
        return $true
    } catch {
        Write-Log ('LaunchBox put-back failed: {0}' -f $_.Exception.Message)
        return $false
    } finally {
        try { if ([System.IO.File]::Exists($putBack)) { [System.IO.File]::Delete($putBack) } }
        catch { Write-Log ('LaunchBox put-back: could not remove the temporary copy {0}.' -f $putBack) }
    }
}

function Set-TpmLaunchBoxFile {
    param([string]$StagePath, [string]$Path, [bool]$Exists, [string]$ExpectedOriginalHash = '')
    Assert-TpmNoReparseWriteTarget -Path $Path -Operation 'LaunchBox commit'
    if (-not $Exists) { [System.IO.File]::Move($StagePath,$Path); return }
    # File.Replace does not verify what it replaced, so a caller that checked the file passes the hash it saw.
    $writtenHash = if ($ExpectedOriginalHash) { (Get-FileHash -LiteralPath $StagePath -Algorithm SHA256 -ErrorAction Stop).Hash } else { '' }
    $replaced = Invoke-TpmLaunchBoxReplace -StagePath $StagePath -Path $Path
    if ($ExpectedOriginalHash) {
        $replacedHash = (Get-FileHash -LiteralPath $replaced -Algorithm SHA256 -ErrorAction Stop).Hash
        if ($replacedHash -ne $ExpectedOriginalHash) {
            # Another program saved between the caller's check and the replace. Its bytes are the newest ones: put them back, keep the copy, and fail.
            $putBack = Restore-TpmLaunchBoxDisplacedFile -Path $Path -DisplacedPath $replaced -WrittenHash $writtenHash
            $changed = New-Object System.InvalidOperationException ('LaunchBox changed while it was being replaced; the bytes that were replaced are retained at {0}. {1}' -f $replaced,$(if ($putBack) { 'They were put back as the current file.' } else { 'They could not be put back.' }))
            $changed.Data['TpmLaunchBoxKeptCopy'] = $replaced
            $changed.Data['TpmLaunchBoxPutBack'] = $putBack
            throw $changed
        }
    }
    try { [System.IO.File]::Delete($replaced) }
    catch { Write-Log ('LaunchBox commit: could not remove the replaced-file copy {0}; it was retained.' -f $replaced) }
}

function New-TpmLaunchBoxResult {
    param([ValidateSet('SAVED','PARTIAL','FAILED','NO_CHANGES')][string]$Outcome, [string]$Summary)
    return [pscustomobject]@{
        Outcome=$Outcome; Summary=$Summary; Succeeded=($Outcome -in @('SAVED','NO_CHANGES'))
        Cancelled=$false; NoOp=($Outcome -eq 'NO_CHANGES'); BackupPath=$null; BackupVerified=$false; RollbackVerified=$false
        AttemptedPaths=@(); ChangedPaths=@(); UnrecoveredPaths=@(); FailedPaths=@(); UnattemptedPaths=@(); KeptFiles=@()
        Errors=@(); Results=@{}; FinalVerified=$false; LegacySnapshot=$false; Reason=''; ChangedByOther=@()
    }
}

# Records that another program changed a library file while this run worked on it, from the error Set-TpmLaunchBoxFile threw.
# Any other error is ignored here.
function Add-TpmLaunchBoxChangedByOther {
    param([Parameter(Mandatory)]$Result, [string]$RelativePath, [Parameter(Mandatory)]$ErrorRecord)
    $data = $ErrorRecord.Exception.Data
    if (-not $data.Contains('TpmLaunchBoxKeptCopy')) { return }
    $Result.ChangedByOther += [pscustomobject]@{ Path = $RelativePath; SavedCopy = [string]$data['TpmLaunchBoxKeptCopy']; PutBack = [bool]$data['TpmLaunchBoxPutBack'] }
}

function Invoke-TpmLaunchBoxFileTransaction {
    param([string]$lbRoot, [object[]]$Plans, [string]$BackupRoot, [ValidateSet('write','restore-safety')][string]$Operation = 'write')
    $result = New-TpmLaunchBoxResult FAILED 'LaunchBox operation refused before library writes.'
    $attempted = New-Object System.Collections.ArrayList
    $stages = @{}
    $createdIdentity = @{}
    $createdWriteTime = @{}
    $deleteIdentity = @{}
    $deleteWriteTime = @{}
    $backup = $null
    $activeMember = $null
    $commitLabel = if ($Operation -eq 'restore-safety') { 'LaunchBox restore' } else { 'LaunchBox save' }
    $commitPhase = if ($Operation -eq 'restore-safety') { 'Restoring' } else { 'Saving' }
    $commitStarted = Get-Date
    $commitCurrent = 0
    $commitProgressOpen = $false
    try {
        $changes = @($Plans | Where-Object { $_.Changed })
        if ($changes.Count -eq 0) { return (New-TpmLaunchBoxResult NO_CHANGES 'No LaunchBox library writes were needed.') }
        # Check both apps before anything, including staging files, is written next to the library.
        if (Test-LaunchBoxRunning) { throw 'Close LaunchBox and BigBox before changing the library; neither app will be force-closed.' }
        foreach ($plan in $Plans) {
            $path = Get-TpmLaunchBoxPath $lbRoot $plan.RelativePath
            Assert-TpmLaunchBoxState $path $plan.Before
            if (-not $plan.Changed) { continue }
            if ($plan.Delete) {
                # A forward deletion removes only the file that was inventoried: its identity and write time are recorded here, its bytes were just checked against the inventory.
                $deleteIdentity[$plan.RelativePath] = [string](Get-TpmFileIdentityString -Path $path)
                $deleteWriteTime[$plan.RelativePath] = [System.IO.File]::GetLastWriteTimeUtc($path)
                continue
            }
            $stage = $path + '.' + [guid]::NewGuid().ToString('N') + '.tmp'
            $originalPath = if ($plan.Before.Exists) { $path } else { $null }
            New-TpmLaunchBoxStage -Path $stage -Document $plan.Document -Source $plan.Source -OriginalPath $originalPath -OriginalHash $plan.Before.Hash -BaseChildCount $plan.BaseChildCount -FullRewrite:([bool]($plan.PSObject.Properties['FullRewrite'] -and $plan.FullRewrite))
            $stages[$plan.RelativePath] = $stage
            $state = Get-TpmLaunchBoxFileState $stage
            if ($plan.SourceHash -and $state.Hash -ne $plan.SourceHash) { throw 'LaunchBox restore source changed during staging.' }
            $plan.AfterHash = $state.Hash
            # A file this run creates keeps the identity and the write time of its staged file when it is moved into place; a rollback deletes only that file,
            # and only while it is unrewritten (a newer in-place save with the same bytes keeps identity and hash, but not the write time).
            if (-not $plan.Before.Exists) {
                $createdIdentity[$plan.RelativePath] = [string](Get-TpmFileIdentityString -Path $stage)
                $createdWriteTime[$plan.RelativePath] = [System.IO.File]::GetLastWriteTimeUtc($stage)
            }
        }
        $backup = Backup-LaunchBoxFiles -lbRoot $lbRoot -Items $Plans -BackupRoot $BackupRoot -Operation $Operation
        $result.BackupPath = $backup.Path; $result.BackupVerified = $backup.Verified
        if (-not $backup.Verified) { throw 'LaunchBox backup was not verified.' }
        if (Test-LaunchBoxRunning) { throw 'LaunchBox or BigBox opened before commit. Close both apps and retry.' }
        foreach ($plan in $Plans) { Assert-TpmLaunchBoxState (Get-TpmLaunchBoxPath $lbRoot $plan.RelativePath) $plan.Before }
        foreach ($plan in $changes) {
            $commitCurrent++
            $commitProgressOpen = $true
            Write-TpmCompactExtractionProgress -Phase $commitPhase -Label $commitLabel -Current $commitCurrent -Total $changes.Count -StartedAt $commitStarted
            $activeMember = $plan.RelativePath
            $path = Get-TpmLaunchBoxPath $lbRoot $plan.RelativePath
            Assert-TpmLaunchBoxState $path $plan.Before
            if (-not $plan.Delete -and (Get-TpmLaunchBoxFileState $stages[$plan.RelativePath]).Hash -ne $plan.AfterHash) { throw 'LaunchBox staged bytes changed.' }
            [void]$attempted.Add($plan)
            if ($plan.Delete) {
                # Identity, write time and bytes are checked on the same open file that is deleted, so a save that arrived after the inventory is never deleted.
                Assert-TpmNoReparseWriteTarget -Path $path -Operation 'LaunchBox restore deletion'
                if ([string]::IsNullOrWhiteSpace([string]$deleteIdentity[$plan.RelativePath])) { throw 'LaunchBox restore could not prove which file it inventoried, so TeknoParrot Manager left it as it is.' }
                try { [void](Remove-TpmTreeOwnedFile -Path $path -ExpectedIdentity ([string]$deleteIdentity[$plan.RelativePath]) -ExpectedSha256 ([string]$plan.Before.Hash) -ExpectedLastWriteTimeUtc $deleteWriteTime[$plan.RelativePath]) }
                catch { throw ('LaunchBox restore left a file as it is because it is no longer the file that was inventoried: {0}.' -f $_.Exception.Message) }
            }
            else { Set-TpmLaunchBoxFile -StagePath $stages[$plan.RelativePath] -Path $path -Exists $plan.Before.Exists -ExpectedOriginalHash ([string]$plan.Before.Hash) }
            $actual = Get-TpmLaunchBoxFileState $path
            if (($plan.Delete -and $actual.Exists) -or (-not $plan.Delete -and (-not $actual.Exists -or $actual.Hash -ne $plan.AfterHash))) { throw 'LaunchBox commit readback failed.' }
        }
        foreach ($plan in $Plans) {
            $activeMember = $plan.RelativePath
            $actual = Get-TpmLaunchBoxFileState (Get-TpmLaunchBoxPath $lbRoot $plan.RelativePath)
            $expectedHash = if ($plan.Changed) { $plan.AfterHash } else { $plan.Before.Hash }
            $expectedExists = if ($plan.Changed) { -not $plan.Delete } else { $plan.Before.Exists }
            if ($actual.Exists -ne $expectedExists -or ($expectedExists -and $actual.Hash -ne $expectedHash)) { throw 'LaunchBox final inventory verification failed.' }
        }
        $result.Outcome = 'SAVED'; $result.Succeeded = $true; $result.FinalVerified = $true
        $result.Summary = 'LaunchBox files were saved and every target was read back and verified.'
        $result.ChangedPaths = @($changes | ForEach-Object { $_.RelativePath })
    } catch {
        $result.Errors += [string]$_.Exception.Message
        if ($activeMember) { $result.FailedPaths += $activeMember }
        if ($activeMember) { Add-TpmLaunchBoxChangedByOther -Result $result -RelativePath $activeMember -ErrorRecord $_ }
        # A file another program saved is never restored over: the older saved copy would discard that newer save.
        $changedByOther = @($result.ChangedByOther | ForEach-Object { $_.Path })
        $rollbackOk = $true
        for ($i=$attempted.Count-1; $i -ge 0; $i--) {
            $plan = $attempted[$i]
            try {
                if ($plan.RelativePath -in $changedByOther) { throw 'LaunchBox was changed by another program, so TeknoParrot Manager left this file as it is.' }
                $path = Get-TpmLaunchBoxPath $lbRoot $plan.RelativePath
                $actual = Get-TpmLaunchBoxFileState $path
                if ($actual.Exists -eq $plan.Before.Exists -and (-not $actual.Exists -or $actual.Hash -eq $plan.Before.Hash)) { continue }
                # A target that is absent although it existed before is owned too (a failed replace can remove it); it is restored from the verified snapshot with a no-clobber move.
                $owned = if ($plan.Delete) { -not $actual.Exists } else { ($actual.Exists -and $actual.Hash -eq $plan.AfterHash) -or (-not $actual.Exists -and $plan.Before.Exists) }
                if (-not $owned) { throw 'Rollback refused to overwrite changed or unknown LaunchBox bytes.' }
                if ($plan.Before.Exists) {
                    $source = Get-TpmLaunchBoxPath $backup.Path $plan.RelativePath
                    Assert-TpmLaunchBoxState $source $plan.Before
                    $stage = $path + '.' + [guid]::NewGuid().ToString('N') + '.tmp'
                    $stages['rollback-' + $plan.RelativePath] = $stage
                    New-TpmLaunchBoxStage -Path $stage -Source $source -VerifyXml $false
                    if ((Get-TpmLaunchBoxFileState $stage).Hash -ne $plan.Before.Hash) { throw 'Rollback staging verification failed.' }
                    $current = Get-TpmLaunchBoxFileState $path
                    if ($current.Exists -ne $actual.Exists -or $current.Hash -ne $actual.Hash) { throw 'LaunchBox changed during rollback.' }
                    Set-TpmLaunchBoxFile -StagePath $stage -Path $path -Exists $current.Exists -ExpectedOriginalHash ([string]$current.Hash)
                } else {
                    # The file was created by this run. Its identity and bytes are checked on the same handle that deletes it, so a newer save that replaced it is never deleted.
                    Assert-TpmNoReparseWriteTarget -Path $path -Operation 'LaunchBox rollback deletion'
                    if ([string]::IsNullOrWhiteSpace([string]$createdIdentity[$plan.RelativePath])) { throw 'LaunchBox rollback could not prove which file this run created, so TeknoParrot Manager left it as it is.' }
                    try { [void](Remove-TpmTreeOwnedFile -Path $path -ExpectedIdentity ([string]$createdIdentity[$plan.RelativePath]) -ExpectedSha256 ([string]$plan.AfterHash) -ExpectedLastWriteTimeUtc $createdWriteTime[$plan.RelativePath]) }
                    catch { throw ('LaunchBox rollback left the file this run created as it is: {0}.' -f $_.Exception.Message) }
                }
                Assert-TpmLaunchBoxState $path $plan.Before
            } catch {
                $rollbackOk = $false; $result.FailedPaths += $plan.RelativePath; $result.UnrecoveredPaths += $plan.RelativePath
                $result.Errors += [string]$_.Exception.Message
                Add-TpmLaunchBoxChangedByOther -Result $result -RelativePath $plan.RelativePath -ErrorRecord $_
            }
        }
        # Verify all attempted pre-states again, not just each at its own undo.
        foreach ($plan in $attempted) {
            try { Assert-TpmLaunchBoxState (Get-TpmLaunchBoxPath $lbRoot $plan.RelativePath) $plan.Before }
            catch {
                $rollbackOk = $false
                if ($plan.RelativePath -notin $result.UnrecoveredPaths) { $result.UnrecoveredPaths += $plan.RelativePath }
                $result.Errors += 'LaunchBox rollback final readback failed.'
            }
        }
        if ($attempted.Count -gt 0) {
            $result.RollbackVerified = $rollbackOk
            $isRestore = ($Operation -eq 'restore-safety')
            if ($rollbackOk) { $result.Summary = if ($isRestore) { 'LaunchBox restore failed; every attempted target was verified against its pre-restore state after compensation.' } else { 'LaunchBox save failed; every attempted target was verified against its pre-write state after compensation.' } }
            else {
                $result.Outcome = 'PARTIAL'
                $result.Summary = if (@($result.ChangedByOther).Count -gt 0) { 'LaunchBox was changed by another program while TeknoParrot Manager was {0}. Its newer version was kept. Close LaunchBox and BigBox, then try again.' -f $(if ($isRestore) { 'restoring' } else { 'saving' }) }
                else { 'LaunchBox recovery is incomplete; changed or unverified files remain. Preserve the backup and review Details before retrying.' }
            }
        }
    } finally {
        if ($commitProgressOpen) {
            Write-TpmCompactExtractionProgress -Phase $commitPhase -Label $commitLabel -Current $commitCurrent -Total $changes.Count -StartedAt $commitStarted -Complete -Outcome $(if ($result.Succeeded) { 'Final' } else { 'Error' })
        }
        $result.AttemptedPaths = @($attempted | ForEach-Object { $_.RelativePath })
        $result.UnattemptedPaths = @($Plans | Where-Object { $_.Changed -and $_.RelativePath -notin $result.AttemptedPaths } | ForEach-Object { $_.RelativePath })
        foreach ($stage in $stages.Values) {
            try {
                if (Test-Path -LiteralPath $stage -ErrorAction Stop) {
                    Assert-TpmNoReparseWriteTarget -Path $stage -Operation 'LaunchBox staging cleanup'
                    Remove-Item -LiteralPath $stage -ErrorAction Stop
                }
            } catch { $result.Errors += 'LaunchBox staging cleanup failed; temporary evidence was retained.' }
        }
    }
    return $result
}

# =============================================================================
# TPM GAME MATCHING ENGINE  (module-ready block; issues #376 and #420 to #427)
# -----------------------------------------------------------------------------
# THE ONE PLACE that decides "which game is this" for TeknoParrot Manager. Every feature that has to match a game (titles, Games Database
# IDs, year and developer, playlists, grouping, pictures) calls it; do not write a second matcher.
#
# It uses all sources of truth together: the Eggman DAT list, the game folder name (only when the DAT confirms the folder), TeknoParrot's
# metadata and profile, and the LaunchBox Games Database (names, year, developer). It looks one level at a time and stops at the first
# level that is certain:
#   level 1  the same name (accents, capitals, punctuation and release tags such as region, version and board code ignored)
#   level 2  the same name spelled a little differently (Roman numerals, "the", "Ver.", "Arcade" tails)
#   level 3  a name worked out from the given one (a note, "A / B" sides, first of a series, an extra name); needs a second source,
#            the hardware maker or the year to back it up
#   level 4  only a close name: never certain, a suggestion for the user
# A different year or number is a different game. The emulator named in a title ("ElfLoader 2") is never part of the game name.
# Outcomes: Certain, Ambiguous (the user decides), NoMatch, NotGame (firmware updaters, drive checkers, boards: never added).
#
# Public functions (read-only, no screens, no script-level variables; state goes in and out as parameters):
#   Get-TpmGamesDbPath / Initialize-TpmGamesDbReader / Get-TpmGamesDbIndex   open the LaunchBox Games Database (read-only) as an index
#   ConvertFrom-TpmDatGameName   what an Eggman game name says: title, other names, year, hardware, maker
#   Get-TpmDatEntriesByCode      the Eggman list entries by profile code
#   Get-TpmProfileMatchSubject   reads one profile, TeknoParrot's metadata and the Eggman list into a subject (names plus facts)
#   New-TpmMatchSubject          the same from plain values (no files)
#   Resolve-TpmGameMatch         THE DECISION for one subject: Status, Level, Match, Options, Reason, Evidence, Facts, Title
# Depends on (existing in this script): Get-NormalizedGameKey, Get-DiceSimilarity, Get-MeaningfulTitleTokens, Read-Xml, Get-XmlChildText,
#   Get-DatEntryForZipName, Write-Log.
# Also: Windows PowerShell 5.1 and winsqlite3.dll (ships with Windows 10 and later).
# To lift it into a .psm1, move this block with those helpers and export the names above.
# The reader opens the database with the read-only flag and has no write call. Nothing is downloaded or copied.
# Evidence: scripts\Invoke-TpmMatchEvidence.ps1 runs the engine over every TeknoParrot profile and writes a report.
# =============================================================================
function Initialize-TpmGamesDbReader {
    [CmdletBinding()] param()
    if ('TpmGamesDbSql' -as [type]) { return }
    $source = @'
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;
public static class TpmGamesDbSql {
    [DllImport("winsqlite3.dll", CallingConvention = CallingConvention.Cdecl)] static extern int sqlite3_open_v2(byte[] file, out IntPtr db, int flags, IntPtr vfs);
    [DllImport("winsqlite3.dll", CallingConvention = CallingConvention.Cdecl)] static extern int sqlite3_close(IntPtr db);
    [DllImport("winsqlite3.dll", CallingConvention = CallingConvention.Cdecl)] static extern int sqlite3_prepare_v2(IntPtr db, byte[] sql, int n, out IntPtr st, IntPtr tail);
    [DllImport("winsqlite3.dll", CallingConvention = CallingConvention.Cdecl)] static extern int sqlite3_step(IntPtr st);
    [DllImport("winsqlite3.dll", CallingConvention = CallingConvention.Cdecl)] static extern int sqlite3_finalize(IntPtr st);
    [DllImport("winsqlite3.dll", CallingConvention = CallingConvention.Cdecl)] static extern int sqlite3_column_count(IntPtr st);
    [DllImport("winsqlite3.dll", CallingConvention = CallingConvention.Cdecl)] static extern IntPtr sqlite3_column_text(IntPtr st, int i);
    [DllImport("winsqlite3.dll", CallingConvention = CallingConvention.Cdecl)] static extern int sqlite3_column_bytes(IntPtr st, int i);
    [DllImport("winsqlite3.dll", CallingConvention = CallingConvention.Cdecl)] static extern IntPtr sqlite3_errmsg(IntPtr db);
    static byte[] Utf8(string s) { return Encoding.UTF8.GetBytes(s + "\0"); }
    // Opens the file read-only (flag 1), runs one SELECT, returns every row as text, closes the file.
    public static List<string[]> Query(string path, string sql) {
        IntPtr db;
        if (sqlite3_open_v2(Utf8(path), out db, 1, IntPtr.Zero) != 0) { if (db != IntPtr.Zero) sqlite3_close(db); throw new InvalidOperationException("The game database could not be opened."); }
        try {
            IntPtr st;
            if (sqlite3_prepare_v2(db, Utf8(sql), -1, out st, IntPtr.Zero) != 0) throw new InvalidOperationException("The game database could not be read: " + Marshal.PtrToStringAnsi(sqlite3_errmsg(db)));
            try {
                var rows = new List<string[]>();
                int n = sqlite3_column_count(st);
                while (sqlite3_step(st) == 100) {
                    var row = new string[n];
                    for (int i = 0; i < n; i++) {
                        IntPtr p = sqlite3_column_text(st, i);
                        if (p == IntPtr.Zero) continue;
                        byte[] buf = new byte[sqlite3_column_bytes(st, i)];
                        Marshal.Copy(p, buf, 0, buf.Length);
                        row[i] = Encoding.UTF8.GetString(buf);
                    }
                    rows.Add(row);
                }
                return rows;
            } finally { sqlite3_finalize(st); }
        } finally { sqlite3_close(db); }
    }
}
'@
    Add-Type -TypeDefinition $source -ErrorAction Stop
}

function Get-TpmGamesDbPath {
    [CmdletBinding()] param([Parameter(Mandatory)][string]$LaunchBoxRoot)
    return (Join-Path (Join-Path $LaunchBoxRoot 'Metadata') 'LaunchBox.Metadata.db')
}

# Accents removed, then the script's existing name normalizer (years, versions and brackets dropped, lowercase letters and digits only).
function ConvertTo-TpmGamesDbKey {
    [CmdletBinding()] [OutputType([string])] param([string]$Title)
    if ([string]::IsNullOrWhiteSpace($Title)) { return '' }
    $plain = New-Object System.Text.StringBuilder
    foreach ($ch in $Title.Normalize([System.Text.NormalizationForm]::FormD).ToCharArray()) {
        if ([System.Globalization.CharUnicodeInfo]::GetUnicodeCategory($ch) -ne [System.Globalization.UnicodeCategory]::NonSpacingMark) { [void]$plain.Append($ch) }
    }
    return (Get-NormalizedGameKey $plain.ToString())
}

# Reads the games of the searched platforms once (TeknoParrot games are listed in the database as arcade games).
# Platforms are searched in the order given: the first one is preferred. Throws when the file cannot be read.
function Get-TpmGamesDbIndex {
    [CmdletBinding()] param([Parameter(Mandatory)][string]$DbPath, [string[]]$Platforms = @('Arcade', 'Taito Type X'))
    Initialize-TpmGamesDbReader
    $platformList = "'" + (($Platforms | ForEach-Object { $_ -replace "'", "''" }) -join "','") + "'"
    $index = @{ ByName = @{}; ByAlternate = @{}; ByWord = @{}; ById = @{}; Platforms = @($Platforms) }
    $gameRows = $null; $hasFacts = $true
    try { $gameRows = @([TpmGamesDbSql]::Query($DbPath, "SELECT DatabaseID, Name, Platform, COALESCE(ReleaseYear, CAST(substr(ReleaseDate, 1, 4) AS INTEGER)), Developer, Publisher FROM Games WHERE Platform IN ($platformList)")) }
    catch { $hasFacts = $false }
    if (-not $hasFacts) { $gameRows = @([TpmGamesDbSql]::Query($DbPath, "SELECT DatabaseID, Name, Platform FROM Games WHERE Platform IN ($platformList)")) }
    foreach ($row in $gameRows) {
        $key = ConvertTo-TpmGamesDbKey $row[1]
        if (-not $key) { continue }
        if (-not $index.ByName.ContainsKey($key)) {
            $index.ByName[$key] = New-Object System.Collections.Generic.List[object]
            foreach ($word in (Get-MeaningfulTitleTokens $row[1])) {
                if (-not $index.ByWord.ContainsKey($word)) { $index.ByWord[$word] = New-Object System.Collections.Generic.List[string] }
                [void]$index.ByWord[$word].Add($key)
            }
        }
        $year = 0
        if ($hasFacts) { [void][int]::TryParse([string]$row[3], [ref]$year) }
        $entry = [pscustomobject]@{ Id = [string]$row[0]; Name = [string]$row[1]; Platform = [string]$row[2]; Year = $year; Developer = $(if ($hasFacts) { [string]$row[4] } else { '' }); Publisher = $(if ($hasFacts) { [string]$row[5] } else { '' }) }
        [void]$index.ByName[$key].Add($entry)
        if (-not $index.ById.ContainsKey($entry.Id)) { $index.ById[$entry.Id] = $entry }
    }
    foreach ($row in [TpmGamesDbSql]::Query($DbPath, "SELECT g.DatabaseID, g.Name, g.Platform, a.AlternateName FROM GameAlternateTitles a JOIN Games g ON g.DatabaseID = a.DatabaseID WHERE g.Platform IN ($platformList)")) {
        $key = ConvertTo-TpmGamesDbKey $row[3]
        if (-not $key) { continue }
        if (-not $index.ByAlternate.ContainsKey($key)) { $index.ByAlternate[$key] = New-Object System.Collections.Generic.List[object] }
        [void]$index.ByAlternate[$key].Add([pscustomobject]@{ Id = [string]$row[0]; Name = [string]$row[1]; Platform = [string]$row[2] })
    }
    if ($index.ByName.Count -eq 0) { throw 'The game database has no arcade games, so it cannot be used.' }
    return $index
}

# Suggestions only, never a match: names that share a meaningful word with the title, ranked by the script's Dice similarity.
function Find-TpmGamesDbCandidate {
    [CmdletBinding()] [OutputType([object[]])] param([Parameter(Mandatory)]$Index, [string]$Title, [int]$Top = 3, [double]$MinimumScore = 0.6)
    $titleKey = ConvertTo-TpmGamesDbKey $Title
    if (-not $titleKey) { return @() }
    $keys = New-Object System.Collections.Generic.HashSet[string]
    foreach ($word in (Get-MeaningfulTitleTokens $Title)) {
        if (-not $Index.ByWord.ContainsKey($word) -or $Index.ByWord[$word].Count -gt 200) { continue }
        foreach ($k in $Index.ByWord[$word]) { [void]$keys.Add($k) }
    }
    $scored = New-Object System.Collections.Generic.List[object]
    foreach ($k in $keys) {
        $score = Get-DiceSimilarity $titleKey $k
        if ($score -ge $MinimumScore) { [void]$scored.Add([pscustomobject]@{ Key = $k; Score = $score }) }
    }
    $best = @($scored | Sort-Object Score -Descending | Select-Object -First $Top)
    return @($best | ForEach-Object { $first = $Index.ByName.Item($_.Key)[0]; [pscustomobject]@{ Id = $first.Id; Name = $first.Name; Platform = $first.Platform; Year = [int]$first.Year; Developer = [string]$first.Developer; Publisher = [string]$first.Publisher; Score = [math]::Round($_.Score, 2) } })
}

# The company named at the start of a hardware label such as [Namco Super System 23]: a known maker, else the first word when it looks
# like a company name (not "PC", "Linux" and the like). '' when the label names none.
function Get-TpmMatchMaker {
    [CmdletBinding()] [OutputType([string])] param([string]$Text)
    $label = ([string]$Text).Trim()
    if (-not $label) { return '' }
    foreach ($maker in @('Bandai Namco', 'Raw Thrills', 'Incredible Technologies', 'Play Mechanix', 'Global VR', 'American Laser Games', 'Namco', 'Sega', 'Taito', 'Konami', 'Capcom', 'Examu', 'Atari', 'Midway', 'SNK', 'Tecmo', 'Gaelco', 'Sammy', 'Sony', 'Cave', 'Arika', 'IT')) {
        if ($label -match ('(?i)^' + [regex]::Escape($maker) + '\b')) { return $(if ($maker -eq 'IT') { 'Incredible Technologies' } else { $maker }) }
    }
    $first = ($label -split '\s+')[0]
    if ($first -match "^[A-Za-z][A-Za-z0-9&'-]{2,}$" -and $first -inotin @('PC', 'Linux', 'Windows', 'System', 'Arcade', 'Game', 'Based', 'Console', 'Unknown')) { return $first }
    return ''
}

# The arcade hardware family of a hardware label: the versions of one board are one family ("Sega Lindbergh Red" and "SEGA Lindbergh
# Yellow" are "Sega Lindbergh"; every Taito Type X is "Taito Type X"), and the maker is spelled one way. '' for an empty label.
function Get-TpmHardwareFamily {
    [CmdletBinding()] [OutputType([string])] param([string]$Label)
    $text = ([regex]::Replace(([string]$Label).Trim(), '\s+', ' '))
    if (-not $text) { return '' }
    $text = [regex]::Replace($text, '^(?i:sega)\b', 'Sega')
    foreach ($family in @('Sega Lindbergh', 'Sega RingEdge', 'Taito Type X', 'Taito NESiCAxLive')) {
        if ($text -match ('(?i)^' + [regex]::Escape($family) + '(?![A-Za-z])')) { return $family }
    }
    return $text
}

# True when a bracketed note is a release tag: the same game, only another year, version, region, revision, cabinet or board code.
function Test-TpmDatReleaseTag {
    [CmdletBinding()] [OutputType([bool])] param([string]$Group)
    $g = ([string]$Group).Trim()
    if (-not $g) { return $true }
    if ($g -match '^(?:19|20)\d{2}(?:-\d{2}-\d{2})?$') { return $true }
    if ($g -match '^v?\d+(?:[.,]\d+)*[A-Za-z]?(?:\s|,|$)') { return $true }
    if ($g -match '(?i)\b(?:ver|version|rev|set)\b\.?\s*[\w.]+|\b(?:offline|online|landscape|portrait|bezel|terminal|vending|revision|license)\b') { return $true }
    if ($g -match '\b\d{5,6}\b') { return $true }
    if ($g -cmatch '^[A-Z][A-Z0-9]{1,5}$') { return $true }
    if ($g -cmatch '^[A-Z0-9][A-Z0-9 ._,/-]{0,30}$' -and $g -match '\d') { return $true }
    if ($g -match '^[a-z]+(?:,[a-z]+)+$') { return $true }
    if ($g -match '(?i)^(?:world|japan|usa|us|uk|asia|europe|euro|export|exp|korea|china|taiwan|jpn)(?:[\s,/]+\S.*)?$') { return $true }
    return $false
}

# True when a bracketed note in an Eggman game name is a technical tag and not another name of the game: a release tag, or a note that says
# it is a variant (bootleg, hack, prototype, demo).
function Test-TpmDatTagGroup {
    [CmdletBinding()] [OutputType([bool])] param([string]$Group)
    if (Test-TpmDatReleaseTag $Group) { return $true }
    return [bool]($Group -match '(?i)\b(?:prototype|proto|bootleg|hack|demo|beta|decrypted|phoenix)\b')
}

# The title without trailing release tags: "Ninja Assault (Asia, NJA4 Ver.A)" and "Brave Blade (VER 1.40G)" are "Ninja Assault" and
# "Brave Blade". A trailing note that says bootleg, hack or prototype is kept: that is a different release, not the same one.
function Get-TpmTitleWithoutReleaseTags {
    [CmdletBinding()] [OutputType([string])] param([string]$Title)
    $text = Remove-TpmEmulatorName $Title
    while ($true) {
        $note = [regex]::Match($text, '^(.*?)\s*\(([^()]*)\)\s*$')
        if (-not $note.Success -or -not $note.Groups[1].Value.Trim() -or -not (Test-TpmDatReleaseTag $note.Groups[2].Value)) { break }
        $text = $note.Groups[1].Value.Trim()
    }
    return $text.Trim()
}

# What one Eggman game name says. Eggman names every game "Title (version)(date)(region)[hardware][TP]". A bracketed note that is not
# a technical tag is another name of the game (for example "Aero Fighters 2 (Sonic Wings 2)"). Year is 0 when the name has none.
# Pure text work: nothing is read from disk.
function ConvertFrom-TpmDatGameName {
    [CmdletBinding()] param([string]$Name)
    $result = [pscustomobject]@{ Title = ''; AltTitles = @(); Year = 0; Hardware = ''; Maker = ''; IsListed = $false }
    if ([string]::IsNullOrWhiteSpace($Name)) { return $result }
    $text = ([string]$Name).Trim() -replace '(?i)\.zip$', ''
    $result.IsListed = [bool]($text -match '\[TP\]\s*$')
    $labels = @([regex]::Matches($text, '\[([^\]]+)\]') | ForEach-Object { $_.Groups[1].Value.Trim() } | Where-Object { $_ -and $_ -ine 'TP' })
    if ($labels.Count -gt 0) { $result.Hardware = [string]$labels[0]; $result.Maker = Get-TpmMatchMaker $result.Hardware }
    $head = ($text -split '\[', 2)[0].Trim()
    $firstParen = $head.IndexOf('(')
    if ($firstParen -lt 0) { $result.Title = $head; return $result }
    $result.Title = $head.Substring(0, $firstParen).Trim()
    $groups = @([regex]::Matches($head, '\(([^()]*)\)') | ForEach-Object { $_.Groups[1].Value.Trim() })
    foreach ($group in $groups) {
        if ($result.Year -eq 0 -and $group -match '^((?:19|20)\d{2})(?:-\d{2}-\d{2})?$') { $result.Year = [int]$Matches[1] }
    }
    $result.AltTitles = @($groups | Where-Object { -not (Test-TpmDatTagGroup $_) })
    return $result
}

# TeknoParrot's own facts for a profile code (Metadata\<code>.json): game name, release year, hardware text and genre.
# Every value is empty (year 0) for a missing or unreadable file or an unsafe code. The code becomes part of a file name,
# so only plain file-name characters are allowed.
function Get-TpmTeknoParrotMetadataFacts {
    [CmdletBinding()] param([Parameter(Mandatory)][string]$TpRoot, [Parameter(Mandatory)][string]$ProfileCode)
    $facts = [pscustomobject]@{ Name = ''; Year = 0; Platform = ''; Genre = '' }
    if ($ProfileCode -notmatch '^[A-Za-z0-9_.\-]+$' -or $ProfileCode -match '^\.+$') { return $facts }
    $path = Join-Path (Join-Path $TpRoot 'Metadata') ($ProfileCode + '.json')
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return $facts }
    try {
        $data = [System.IO.File]::ReadAllText($path) | ConvertFrom-Json -ErrorAction Stop
        if ($null -eq $data) { return $facts }
        if ($data.PSObject.Properties['game_name']) { $facts.Name = ([string]$data.game_name).Trim() }
        if ($data.PSObject.Properties['platform']) { $facts.Platform = ([string]$data.platform).Trim() }
        if ($data.PSObject.Properties['game_genre']) { $facts.Genre = ([string]$data.game_genre).Trim() }
        $year = 0
        if ($data.PSObject.Properties['release_year'] -and [int]::TryParse([string]$data.release_year, [ref]$year) -and $year -gt 1900) { $facts.Year = $year }
    } catch { Write-Log ('Game matching: could not read the TeknoParrot facts for {0}: {1}' -f $ProfileCode, $_.Exception.Message) }
    return $facts
}

function Get-TpmTeknoParrotGameName {
    [CmdletBinding()] [OutputType([string])] param([Parameter(Mandatory)][string]$TpRoot, [Parameter(Mandatory)][string]$ProfileCode)
    return [string](Get-TpmTeknoParrotMetadataFacts -TpRoot $TpRoot -ProfileCode $ProfileCode).Name
}

# Suggestion for a name written as one run-together word ("PowerPuttLive"), which shares no whole word with the list's name
# ("PowerPutt Home Edition"): list names that start with the same first letters, ranked by the script's Dice similarity.
function Find-TpmLaunchBoxIdLinkPrefixCandidate {
    [CmdletBinding()] [OutputType([object[]])] param([Parameter(Mandatory)]$Index, [string]$Title, [double]$MinimumScore = 0.4)
    $titleKey = ConvertTo-TpmGamesDbKey $Title
    if ($titleKey.Length -lt 6) { return @() }
    $start = $titleKey.Substring(0, 6)
    $best = $null; $bestScore = 0.0
    foreach ($k in $Index.ByName.Keys) {
        if (-not $k.StartsWith($start, [System.StringComparison]::Ordinal)) { continue }
        $score = Get-DiceSimilarity $titleKey $k
        if ($score -ge $MinimumScore -and $score -gt $bestScore) { $best = $k; $bestScore = $score }
    }
    if ($null -eq $best) { return @() }
    $first = $Index.ByName.Item($best)[0]
    return @([pscustomobject]@{ Id = $first.Id; Name = $first.Name; Platform = $first.Platform; Score = [math]::Round($bestScore, 2) })
}

# ---- Layered matching of one TeknoParrot game to the LaunchBox game list ----
# Every source the Manager already has is used as a hint, and each one is named in the result:
#   TeknoParrot's own metadata (name, year, hardware), the Eggman list name (only when the game folder is confirmed by the list),
#   the MAME romset name, and the title in LaunchBox. An exact name wins over a close one. Two sources that point to different
#   games are never settled by guessing: the user decides. Pure functions: nothing here writes anything.

# The emulator that runs the game is not part of the game: "ElfLoader 2", "Elfloader2", "(ElfLdr2)", with or without brackets.
function Remove-TpmEmulatorName {
    [CmdletBinding()] [OutputType([string])] param([string]$Title)
    if ([string]::IsNullOrWhiteSpace($Title)) { return '' }
    $named = [regex]::Replace($Title, '\s*\(?\s*elf\s*(loader|ldr)\s*\d*\s*\)?', ' ', 'IgnoreCase')
    return ([regex]::Replace($named, '\s+', ' ').Trim())
}

# Removes what is not part of a title: the emulator, a trailing "(...)" note, a trailing version, and "for NESiCAxLive".
function Get-TpmMatchCleanTitle {
    [CmdletBinding()] [OutputType([string])] param([string]$Title)
    if ([string]::IsNullOrWhiteSpace($Title)) { return '' }
    $named = Remove-TpmEmulatorName $Title
    $clean = [regex]::Replace($named, '(\s*\([^()]*\))+\s*$', '')
    $clean = [regex]::Replace($clean, '\s+(v|ver\.?|version)\s*\d[\d\.]*(\s*/\s*\d[\d\.]*)*\s*$', '', 'IgnoreCase')
    $clean = [regex]::Replace($clean, '\s+for\s+NESiCAxLive\s*$', '', 'IgnoreCase')
    # A version is not part of the game, anywhere in the name: "Ver. 2", "Version 3".
    $clean = [regex]::Replace($clean, '\s+(ver\.?|version)\s*\d[\d\.]*(\s*/\s*\d[\d\.]*)*(?=\s|$)', '', 'IgnoreCase')
    # A dotted number at the end ("... DX 1.18") is a version when at least three words come before it and the last of them is not a number ("Tekken 5.1" is not).
    $dotted = [regex]::Match($clean, '^(.+?)\s+\d+\.\d+(\.\d+)*$')
    if ($dotted.Success) {
        $before = @($dotted.Groups[1].Value -split '\s+')
        if ($before.Count -ge 3 -and $before[-1] -notmatch '^\d+$') { $clean = $dotted.Groups[1].Value }
    }
    return $clean.Trim()
}

# Lowercase words of a title. Numbers count (a different number is a different game); Roman numerals become numbers.
function Get-TpmMatchWords {
    [CmdletBinding()] [OutputType([string[]])] param([string]$Title)
    $roman = @{ ii = '2'; iii = '3'; iv = '4'; v = '5'; vi = '6'; vii = '7'; viii = '8'; ix = '9'; x = '10' }
    $skip = @('the', 'of', 'a', 'an', 'and', 'for', 'in', 'to', 'de', 'no')
    $words = @([regex]::Matches(([string]$Title).ToLowerInvariant().Replace("'", ''), '[a-z0-9]+') | ForEach-Object { $_.Value })
    return @($words | Where-Object { $_ -notin $skip } | ForEach-Object { if ($roman.ContainsKey($_)) { $roman[$_] } else { $_ } })
}

# True for items that appear as TeknoParrot profiles but are not games: firmware updaters, drive checkers, controllers and
# test boards. They are never added to LaunchBox and never matched. A game that runs on a development board ("Dragon's Heaven
# (development board)") is still a game.
function Test-TpmNonGameTitle {
    [CmdletBinding()] [OutputType([bool])] param([string]$Title)
    if ([string]::IsNullOrWhiteSpace($Title)) { return $false }
    return [bool]($Title -match '(?i)firmware\s+updat|DIMM\s+FIRM|drive\s+checker|^AS-1\s+Controller|Hopper\s+Board|^MVS-TEMP\b')
}

# A looser spelling of a title, for comparing with the game list: no accents, "&" as "and", Roman numerals as numbers,
# no "the / of / and ...", no "Ver." / "Version", and long vowels folded ("Gouketsuji" and "Goketsuji" with a long o become one word).
function Get-TpmMatchCanonKey {
    [CmdletBinding()] [OutputType([string])] param([string]$Title)
    if ([string]::IsNullOrWhiteSpace($Title)) { return '' }
    $plain = New-Object System.Text.StringBuilder
    foreach ($ch in $Title.Normalize([System.Text.NormalizationForm]::FormD).ToCharArray()) {
        if ([System.Globalization.CharUnicodeInfo]::GetUnicodeCategory($ch) -ne [System.Globalization.UnicodeCategory]::NonSpacingMark) { [void]$plain.Append($ch) }
    }
    $roman = @{ ii = '2'; iii = '3'; iv = '4'; v = '5'; vi = '6'; vii = '7'; viii = '8'; ix = '9' }
    $skip = @('the', 'of', 'a', 'an', 'and', 'for', 'in', 'to', 'de', 'no', 'ver', 'version')
    $text = $plain.ToString().ToLowerInvariant().Replace('&', ' and ').Replace('+', ' plus ').Replace("'", '')
    $text = [regex]::Replace($text, '\bvs\b', ' versus ')
    # A version is not part of the game: "Ver. 2", "Version 2006".
    $text = [regex]::Replace($text, '\b(ver|version)\.?\s*\d[\d\.]*', ' ')
    $kept = New-Object System.Collections.Generic.List[string]
    foreach ($found in [regex]::Matches($text, '[a-z0-9]+')) {
        $word = $found.Value
        if ($skip -contains $word) { continue }
        if ($roman.ContainsKey($word)) { $word = $roman[$word] } else { $word = $word.Replace('ou', 'o').Replace('oo', 'o').Replace('uu', 'u') }
        [void]$kept.Add($word)
    }
    return ($kept -join '')
}

# The game list keyed by the looser spelling. Built once per list and kept on it.
function Get-TpmGamesDbCanonMap {
    [CmdletBinding()] param([Parameter(Mandatory)]$Index)
    if ($Index.ContainsKey('ByCanon')) { return $Index['ByCanon'] }
    $map = @{}
    foreach ($key in $Index.ByName.Keys) {
        foreach ($entry in $Index.ByName[$key]) {
            $canon = Get-TpmMatchCanonKey ([string]$entry.Name)
            if (-not $canon) { continue }
            if (-not $map.ContainsKey($canon)) { $map[$canon] = New-Object System.Collections.Generic.List[object] }
            [void]$map[$canon].Add($entry)
        }
    }
    $Index['ByCanon'] = $map
    return $map
}

# Games whose title is another game's title plus a qualifier in brackets ("Frogger (Raw Thrills)" next to "Frogger"), by the key of the
# plain title. Built once per list and kept on it.
function Get-TpmGamesDbQualifiedMap {
    [CmdletBinding()] param([Parameter(Mandatory)]$Index)
    if ($Index.ContainsKey('ByQualified')) { return $Index['ByQualified'] }
    $map = @{}
    foreach ($entry in $Index.ById.Values) {
        $plain = [regex]::Replace([string]$entry.Name, '\s*\([^()]*\)\s*$', '')
        if ($plain -ceq [string]$entry.Name) { continue }
        $key = ConvertTo-TpmGamesDbKey $plain
        if (-not $key) { continue }
        if (-not $map.ContainsKey($key)) { $map[$key] = New-Object System.Collections.Generic.List[object] }
        [void]$map[$key].Add($entry)
    }
    $Index['ByQualified'] = $map
    return $map
}

# One entry out of the games that share a name, or $null when it cannot be told. Every searched platform counts. Games with one name are
# told apart by a "(year)" in the list's own title, the same release year, a release year within one year (when only one is that close),
# the hardware maker (when only one fits), then the platform order (the first searched platform that has exactly one) and exact spelling.
function Select-TpmGamesDbHit {
    [CmdletBinding()] param([Parameter(Mandatory)]$Index, [object[]]$Hits = @(), [string]$Title, [int]$Year = 0, [string]$Maker = '')
    $pool = @($Hits | Where-Object { $_.Platform -in $Index.Platforms } | ForEach-Object { if ($Index.ById.ContainsKey([string]$_.Id)) { $Index.ById[[string]$_.Id] } else { $_ } })
    if ($pool.Count -eq 0) { return $null }
    $single = { param($list) $groups = @($list | Group-Object Id); if ($groups.Count -eq 1) { $groups[0].Group[0] } else { $null } }
    $found = & $single $pool
    if ($found) { return $found }
    if ($Year -gt 0) {
        $found = & $single @($pool | Where-Object { $_.Name -ieq ('{0} ({1})' -f $Title, $Year) })
        if ($found) { return $found }
        $found = & $single @($pool | Where-Object { $_.PSObject.Properties['Year'] -and [int]$_.Year -eq $Year })
        if ($found) { return $found }
        $found = & $single @($pool | Where-Object { $_.PSObject.Properties['Year'] -and [int]$_.Year -gt 0 -and [Math]::Abs([int]$_.Year - $Year) -le 1 })
        if ($found) { return $found }
    }
    if ($Maker) {
        $found = & $single @($pool | Where-Object { Test-TpmMakerFits -Maker $Maker -Game $_ })
        if ($found) { return $found }
    }
    foreach ($platformName in $Index.Platforms) {
        $found = & $single @($pool | Where-Object { $_.Platform -eq $platformName })
        if ($found) { return $found }
        if (@($pool | Where-Object { $_.Platform -eq $platformName }).Count -gt 0) { break }
    }
    return (& $single @($pool | Where-Object { $_.Name -ieq $Title }))
}

# A copy of a list entry that says at which level of the layered match it was found.
function Add-TpmMatchLevel {
    [CmdletBinding()] param($Hit, [int]$Level)
    if ($null -eq $Hit) { return $null }
    $copy = $Hit.PSObject.Copy()
    Add-Member -InputObject $copy -NotePropertyName MatchLevel -NotePropertyValue $Level -Force
    return $copy
}

# The one game that has this name, or $null. Level 1: the same name (accents, capitals, punctuation and "&" are ignored). Level 2:
# the same name spelled a little differently (Roman numerals, "the", "Ver."), see Get-TpmMatchCanonKey.
function Find-TpmGamesDbExact {
    [CmdletBinding()] param([Parameter(Mandatory)]$Index, [string]$Title, [int]$Year = 0, [string]$Maker = '', [ValidateRange(1, 2)][int]$MaxLevel = 2)
    $key = ConvertTo-TpmGamesDbKey $Title
    if (-not $key) { return $null }
    foreach ($mapName in @('ByName', 'ByAlternate')) {
        if (-not $Index[$mapName].ContainsKey($key)) { continue }
        $hit = Select-TpmGamesDbHit -Index $Index -Hits $Index[$mapName][$key].ToArray() -Title $Title -Year $Year -Maker $Maker
        if ($hit) { return (Add-TpmMatchLevel -Hit $hit -Level 1) }
    }
    if ($MaxLevel -lt 2) { return $null }
    $canon = Get-TpmMatchCanonKey $Title
    if ($canon) {
        $map = Get-TpmGamesDbCanonMap -Index $Index
        if ($map.ContainsKey($canon)) { return (Add-TpmMatchLevel -Hit (Select-TpmGamesDbHit -Index $Index -Hits $map[$canon].ToArray() -Title $Title -Year $Year -Maker $Maker) -Level 2) }
        # The list often adds "Arcade" / "Arcade Edition" / "Edition" to a title; one side may have it and the other not.
        foreach ($tail in @('arcadeedition', 'arcadegame', 'arcade', 'edition')) {
            $longer = $canon + $tail
            if ($map.ContainsKey($longer)) { $hit = Select-TpmGamesDbHit -Index $Index -Hits $map[$longer].ToArray() -Title $Title -Year $Year -Maker $Maker; if ($hit) { return (Add-TpmMatchLevel -Hit $hit -Level 2) } }
            if ($canon.Length -gt ($tail.Length + 3) -and $canon.EndsWith($tail)) {
                $shorter = $canon.Substring(0, $canon.Length - $tail.Length)
                if ($map.ContainsKey($shorter)) { $hit = Select-TpmGamesDbHit -Index $Index -Hits $map[$shorter].ToArray() -Title $Title -Year $Year -Maker $Maker; if ($hit) { return (Add-TpmMatchLevel -Hit $hit -Level 2) } }
            }
        }
    }
    return $null
}

# One name against the game list, one level at a time. Kind is Exact, NearSure, NearAsk or None.
#   Level 1  the same name (accents, capitals, punctuation and "&" ignored)
#   Level 2  the same name spelled a little differently (Roman numerals, "the", "Ver.", "Arcade" tails)
#   Level 3  a name worked out from the given one: release note, version, emulator, region word, "A / B" sides, first of a series
#   Level 4  no exact name. Close names only, scored on how many words differ, the year and the maker. Never a sure match.
# MaxLevel stops the search early: a caller that already has a sure answer never pays for the deeper levels.
# A number, year or version in the name is part of the game, so a close name whose numbers differ is dropped.
function Get-TpmGamesDbPickByScore {
    [CmdletBinding()] param([Parameter(Mandatory)]$Index, [string]$Title, [int]$Year = 0, [string]$Maker = '', [ValidateRange(1, 4)][int]$MaxLevel = 4)
    $none = [pscustomobject]@{ Kind = 'None'; Id = ''; Name = ''; Platform = ''; Score = 0.0; Gap = 0.0; QueryName = $Title; Level = 0 }
    $clean = Get-TpmMatchCleanTitle $Title
    if (-not $clean) { return $none }
    $exact = Find-TpmGamesDbExact -Index $Index -Title $Title -Year $Year -Maker $Maker -MaxLevel ([Math]::Min($MaxLevel, 2))
    if (-not $exact) {
        # Release tags (region, version, board code) are not part of the name: the same game, so the same level.
        $plain = Get-TpmTitleWithoutReleaseTags $Title
        if ($plain -and $plain -cne $Title) { $exact = Find-TpmGamesDbExact -Index $Index -Title $plain -Year $Year -Maker $Maker -MaxLevel ([Math]::Min($MaxLevel, 2)) }
    }
    $level = if ($exact) { [int]$exact.MatchLevel } else { 0 }
    if (-not $exact -and $MaxLevel -ge 3) {
        # The list may name the version as its own game ("Initial D Arcade Stage Ver. 2"): the name as written, without its release note, wins
        # before a version is ignored.
        $noNote = [regex]::Replace($Title, '(\s*\([^()]*\))+\s*$', '').Trim()
        if ($noNote -and $noNote -ne $Title) { $exact = Find-TpmGamesDbExact -Index $Index -Title $noNote -Year $Year -Maker $Maker }
        if (-not $exact -and $clean -ne $Title) { $exact = Find-TpmGamesDbExact -Index $Index -Title $clean -Year $Year -Maker $Maker }
        if (-not $exact) {
            $alternates = New-Object System.Collections.Generic.List[string]
            $codeMatch = [regex]::Match($clean, '^([A-Za-z0-9]{2,6})\s*[:\-]\s+(.+)$')
            if ($codeMatch.Success -and $codeMatch.Groups[1].Value -match '\d' -and $codeMatch.Groups[1].Value -match '[A-Za-z]') { [void]$alternates.Add($codeMatch.Groups[2].Value) }
            # One side of "A / B" counts only when it has two or more words: a single word ("Hero") is too easy to match to another game.
            if ($clean -match '\s/\s') { foreach ($side in ($clean -split '\s/\s')) { if (@($side.Trim() -split '\s+').Count -ge 2) { [void]$alternates.Add($side.Trim()) } } }
            # In a ROM-set name, a region just before the release note ("Cobra: The Arcade World (CBR2 Ver. B)") is not part of the game's
            # name. A plain "Big Buck Hunter World" has no release note and is a game of its own.
            $regionTail = [regex]::Match($clean, '^(.+?)\s+(World|Japan|USA|Asia|Export|Korea|Europe|Euro|China|Taiwan)$', 'IgnoreCase')
            if ($regionTail.Success -and $clean -ne $Title -and @($regionTail.Groups[1].Value -split '\s+').Count -ge 2) { [void]$alternates.Add($regionTail.Groups[1].Value.Trim()) }
            # A trailing "1" is the first game of a series ("Quiz Magic Academy 1" is "Quiz Magic Academy"), and a point revision is a version of
            # the game before it ("Tekken 5.1" is "Tekken 5"). The name as written is tried first, so a list that has its own "... 1" or "... 5.1" wins.
            $firstOfSeries = [regex]::Match($clean, '^(.+?)\s+1$')
            if ($firstOfSeries.Success -and @($firstOfSeries.Groups[1].Value -split '\s+').Count -ge 2) { [void]$alternates.Add($firstOfSeries.Groups[1].Value.Trim()) }
            $pointRevision = [regex]::Match($clean, '^(.+\s\d+)\.\d+$')
            if ($pointRevision.Success -and @($pointRevision.Groups[1].Value -split '\s+').Count -ge 2) { [void]$alternates.Add($pointRevision.Groups[1].Value.Trim()) }
            # Well-known regional names of one game: Capcom's "Street Fighter Zero" is the first "Street Fighter Alpha".
            $regional = @{ 'streetfighterzero' = "Street Fighter Alpha: Warriors' Dreams" }
            $regionalKey = Get-TpmMatchCanonKey $clean
            if ($regional.ContainsKey($regionalKey)) { [void]$alternates.Add([string]$regional[$regionalKey]) }
            $sideHits = New-Object System.Collections.Generic.List[object]
            foreach ($alternate in $alternates) { $hit = Find-TpmGamesDbExact -Index $Index -Title $alternate -Year $Year -Maker $Maker; if ($hit) { [void]$sideHits.Add($hit) } }
            # "A / B" where both sides are different games in the list is a question for the user, not an exact match.
            if (@($sideHits | ForEach-Object { [string]$_.Id } | Select-Object -Unique).Count -gt 1) {
                return [pscustomobject]@{ Kind = 'NearAsk'; Id = [string]$sideHits[0].Id; Name = [string]$sideHits[0].Name; Platform = [string]$sideHits[0].Platform; Score = 0.8; Gap = 0.0; QueryName = $Title; Level = 4 }
            }
            if ($sideHits.Count -gt 0) { $exact = $sideHits[0] }
        }
        if ($exact) { $level = 3 }
    }
    if ($exact) { return [pscustomobject]@{ Kind = 'Exact'; Id = [string]$exact.Id; Name = [string]$exact.Name; Platform = [string]$exact.Platform; Score = 1.0; Gap = 1.0; QueryName = $Title; Level = $level } }
    if ($MaxLevel -lt 4) { return $none }
    $queryWords = @(Get-TpmMatchWords $clean)
    $queryNumbers = (@($queryWords | Where-Object { $_ -match '^\d+$' } | Sort-Object)) -join ','
    $cands = @(Find-TpmGamesDbCandidate -Index $Index -Title $clean -Top 8 -MinimumScore 0.5)
    if ($cands.Count -eq 0) {
        # A name written as one run-together word shares no whole word with the list's name.
        $prefix = @(Find-TpmLaunchBoxIdLinkPrefixCandidate -Index $Index -Title $clean)
        if ($prefix.Count -eq 0) { return $none }
        return [pscustomobject]@{ Kind = 'NearAsk'; Id = [string]$prefix[0].Id; Name = [string]$prefix[0].Name; Platform = [string]$prefix[0].Platform; Score = [double]$prefix[0].Score; Gap = 0.0; QueryName = $Title; Level = 4 }
    }
    $scored = @(foreach ($cand in $cands) {
        $candWords = @(Get-TpmMatchWords (Get-TpmMatchCleanTitle ([string]$cand.Name)))
        $extra = @($queryWords | Where-Object { $_ -notin $candWords }).Count
        $missing = @($candWords | Where-Object { $_ -notin $queryWords }).Count
        $adjust = -0.25 * ($extra + $missing)
        $candYear = [int]$cand.Year
        if ($Year -gt 0 -and $candYear -gt 0) {
            $apart = [Math]::Abs($Year - $candYear)
            if ($apart -eq 0) { $adjust += 0.3 } elseif ($apart -eq 1) { $adjust += 0.15 } elseif ($apart -ge 3) { $adjust -= 0.3 }
        }
        if ($Maker) {
            foreach ($company in @([string]$cand.Developer, [string]$cand.Publisher)) {
                if ($company.Length -ge 4 -and $Maker.IndexOf($company, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { $adjust += 0.1; break }
            }
        }
        $candNumbers = (@($candWords | Where-Object { $_ -match '^\d+$' } | Sort-Object)) -join ','
        [pscustomobject]@{ Cand = $cand; Score = ([double]$cand.Score + $adjust); Miss = ($extra + $missing); Subset = (($extra -eq 0) -or ($missing -eq 0)); YearEq = ($Year -gt 0 -and $candYear -eq $Year); SameNumbers = ($candNumbers -eq $queryNumbers) }
    })
    $scored = @($scored | Where-Object { $_.SameNumbers } | Sort-Object Score -Descending)
    if ($scored.Count -eq 0) { return $none }
    $top = $scored[0]
    if ([double]$top.Cand.Score -lt 0.7 -and $top.Score -lt 0.5) { return $none }
    $gap = if ($scored.Count -gt 1) { $top.Score - $scored[1].Score } else { 1.0 }
    $firm = $top.SameNumbers -and (($top.Score -ge 0.9 -and $top.Miss -eq 0 -and $gap -ge 0.15) -or ($top.Subset -and $top.YearEq -and $gap -ge 0.15))
    return [pscustomobject]@{ Kind = $(if ($firm) { 'NearSure' } else { 'NearAsk' }); Id = [string]$top.Cand.Id; Name = [string]$top.Cand.Name; Platform = [string]$top.Cand.Platform; Score = [Math]::Round($top.Score, 2); Gap = [Math]::Round($gap, 2); QueryName = $Title; Level = 4 }
}

# A name that contains the other one word for word: the list has "Dino King Battle" and the game is "Dino King Battle: King of
# Jurassic" (or the other way round). Only whole words count, in the same order, with the same numbers; one name has to be the
# other's start (two or more words) or share three or more words with it in order. It must be one game on the first platform
# that has any. The result is only ever a question for the user, never an automatic match.
function Find-TpmGamesDbContained {
    [CmdletBinding()] param([Parameter(Mandatory)]$Index, [string]$Title)
    $fix = { param($w) @($w | ForEach-Object { if ($_ -eq 'vs') { 'versus' } else { $_ } }) }
    $queryWords = @(& $fix @(Get-TpmMatchWords (Get-TpmMatchCleanTitle $Title)))
    if ($queryWords.Count -lt 2) { return $null }
    $queryNumbers = (@($queryWords | Where-Object { $_ -match '^\d+$' } | Sort-Object)) -join ','
    # Only names that share a meaningful word with the title can contain it, so only those are looked at.
    $keys = New-Object System.Collections.Generic.HashSet[string]
    foreach ($token in (Get-MeaningfulTitleTokens $Title)) {
        if (-not $Index.ByWord.ContainsKey($token) -or $Index.ByWord[$token].Count -gt 3000) { continue }
        foreach ($k in $Index.ByWord[$token]) { [void]$keys.Add($k) }
    }
    foreach ($platformName in $Index.Platforms) {
        $found = @{}
        foreach ($key in $keys) {
            $list = $Index.ByName[$key]
            foreach ($entry in $list) {
                if ([string]$entry.Platform -ne $platformName) { continue }
                $entryWords = @(& $fix @(Get-TpmMatchWords (Get-TpmMatchCleanTitle ([string]$entry.Name))))
                if ($entryWords.Count -lt 2 -or $entryWords.Count -eq $queryWords.Count) { continue }
                if ((@($entryWords | Where-Object { $_ -match '^\d+$' } | Sort-Object)) -join ',' -ne $queryNumbers) { continue }
                if ($entryWords.Count -lt $queryWords.Count) { $short = $entryWords; $long = $queryWords } else { $short = $queryWords; $long = $entryWords }
                if (($long.Count - $short.Count) -gt 4) { continue }
                $isStart = $true
                for ($i = 0; $i -lt $short.Count; $i++) { if ($short[$i] -ne $long[$i]) { $isStart = $false; break } }
                $at = 0; $inOrder = $true
                foreach ($word in $short) { $hit = [Array]::IndexOf($long, $word, $at); if ($hit -lt 0) { $inOrder = $false; break }; $at = $hit + 1 }
                if (($isStart -and $short.Count -ge 2) -or ($inOrder -and $short.Count -ge 3)) { $found[[string]$entry.Id] = [pscustomobject]@{ Entry = $entry; Extra = ($long.Count - $short.Count) } }
            }
        }
        if ($found.Count -eq 0) { continue }
        $best = @($found.Values | Sort-Object Extra)
        if ($best.Count -gt 1 -and $best[0].Extra -eq $best[1].Extra) { return $null }
        return $best[0].Entry
    }
    return $null
}

# True when two titles are the same except for one brand word in the middle ("Golden Tee Live 2020" and "Golden Tee 2020").
# Only the word "Live" counts, only in the middle, and only when the title has a number (a year or an edition) that matches.
function Test-TpmMatchOnlyFillerDiffers {
    [CmdletBinding()] [OutputType([bool])] param([string]$Title, [string]$Other)
    $a = @(Get-TpmMatchWords (Get-TpmMatchCleanTitle $Title))
    $b = @(Get-TpmMatchWords (Get-TpmMatchCleanTitle $Other))
    if ($a.Count -eq $b.Count) { return $false }
    if ($a.Count -gt $b.Count) { $long = $a; $short = $b } else { $long = $b; $short = $a }
    if (($long.Count - $short.Count) -ne 1 -or $short.Count -lt 3) { return $false }
    if (@($short | Where-Object { $_ -match '^\d+$' }).Count -eq 0) { return $false }
    for ($i = 1; $i -lt ($long.Count - 1); $i++) {
        if ($long[$i] -ne 'live') { continue }
        $rest = @($long[0..($i - 1)]) + @($long[($i + 1)..($long.Count - 1)])
        if (($rest -join ' ') -eq ($short -join ' ')) { return $true }
    }
    return $false
}

# One name against the game list, by exact name, close name, or one name containing the other. See Get-TpmGamesDbPickByScore for the
# levels. Level 3 also covers a name that differs only by the brand word "Live" ("Golden Tee Live 2020" and "Golden Tee 2020"); a
# different year or number is never ignored. A name that contains the other one is only ever a close name (level 4).
function Get-TpmGamesDbPick {
    [CmdletBinding()] param([Parameter(Mandatory)]$Index, [string]$Title, [int]$Year = 0, [string]$Maker = '', [ValidateRange(1, 4)][int]$MaxLevel = 4)
    $pick = Get-TpmGamesDbPickByScore -Index $Index -Title $Title -Year $Year -Maker $Maker -MaxLevel $MaxLevel
    if ($pick.Kind -eq 'Exact' -or $MaxLevel -lt 3) { return $pick }
    $contained = Find-TpmGamesDbContained -Index $Index -Title $Title
    if ($contained -and (Test-TpmMatchOnlyFillerDiffers -Title $Title -Other ([string]$contained.Name))) {
        return [pscustomobject]@{ Kind = 'Exact'; Id = [string]$contained.Id; Name = [string]$contained.Name; Platform = [string]$contained.Platform; Score = 1.0; Gap = 0.0; QueryName = $Title; Level = 3 }
    }
    if ($MaxLevel -lt 4 -or $pick.Kind -eq 'NearSure') { return $pick }
    if ($contained -and [string]$contained.Id -ne [string]$pick.Id) {
        return [pscustomobject]@{ Kind = 'NearAsk'; Id = [string]$contained.Id; Name = [string]$contained.Name; Platform = [string]$contained.Platform; Score = 0.85; Gap = 0.0; QueryName = $Title; Level = 4 }
    }
    return $pick
}

# True when the developer or publisher of a list game fits the hardware maker of a profile ("Namco" fits "Bandai Namco Entertainment").
function Test-TpmMakerFits {
    [CmdletBinding()] [OutputType([bool])] param([string]$Maker, $Game)
    $maker = ([string]$Maker).Trim().ToLowerInvariant()
    if ($maker.Length -lt 3 -or $null -eq $Game) { return $false }
    foreach ($company in @([string]$Game.Developer, [string]$Game.Publisher)) {
        $name = $company.Trim().ToLowerInvariant()
        if ($name.Length -ge 3 -and ($name.Contains($maker) -or $maker.Contains($name))) { return $true }
    }
    return $false
}

# A clean, readable title for a name with no list match: no emulator name, no trailing technical notes (version, region, board code).
function Get-TpmDisplayTitle {
    [CmdletBinding()] [OutputType([string])] param([string]$Name)
    $title = Remove-TpmEmulatorName $Name
    while ($true) {
        $note = [regex]::Match($title, '^(.*?)\s*\(([^()]*)\)\s*$')
        if (-not $note.Success -or -not $note.Groups[1].Value.Trim() -or -not (Test-TpmDatTagGroup $note.Groups[2].Value)) { break }
        $title = $note.Groups[1].Value.Trim()
    }
    $title = [regex]::Replace($title, '\s+(?:v|ver\.?|version)\s*\d[\d.]*(?:\s*/\s*\d[\d.]*)*\s*$', '', 'IgnoreCase')
    return $title.Trim()
}

# Everything the sources say about one profile: the names to look up and the facts to check them with. Pure: values in, object out.
#   Eggman list    the list's game names for the profile code. A game folder counts only when the list confirms it
#                  (ConfirmedDatName): then only that one list game is used.
#   TeknoParrot    the game name in TeknoParrot's metadata, and the name in the profile when it differs
#   LaunchBox      the title already in LaunchBox (HintName), a weak name: used only when nothing else matches
# Another name in brackets in a list name ("Aero Fighters 2 (Sonic Wings 2)") is a weak name too.
# NotGame is set for firmware updaters, drive checkers, controllers and boards; they are never matched or added.
function New-TpmMatchSubject {
    [CmdletBinding()] param(
        [string]$Code = '', [string]$ProfileName = '', [string]$MetadataName = '', [int]$MetadataYear = 0, [string]$MetadataPlatform = '', [string]$MetadataGenre = '',
        [string[]]$DatNames = @(), [string]$ConfirmedDatName = '', [string]$HintName = ''
    )
    $names = New-Object System.Collections.Generic.List[object]
    $seen = New-Object System.Collections.Generic.HashSet[string]
    $addName = {
        param([string]$Source, [string]$Name, [bool]$Weak)
        $clean = Remove-TpmEmulatorName $Name
        $key = '{0}|{1}|{2}' -f $Source, [int]$Weak, (ConvertTo-TpmGamesDbKey $clean)
        if ($clean -and $seen.Add($key)) { [void]$names.Add([pscustomobject]@{ Source = $Source; Name = $clean; Fallback = $Weak }) }
    }
    $datYear = 0; $hardware = ''; $maker = ''
    $datTitles = New-Object System.Collections.Generic.List[string]
    $datUsed = if ($ConfirmedDatName) { @($ConfirmedDatName) } else { @($DatNames | Where-Object { $_ }) }
    $datSource = if ($ConfirmedDatName) { 'Eggman list (game folder confirmed)' } else { 'Eggman list' }
    foreach ($datName in $datUsed) {
        $parsed = ConvertFrom-TpmDatGameName $datName
        & $addName $datSource $parsed.Title $false
        foreach ($alt in $parsed.AltTitles) { & $addName $datSource $alt $true }
        if ($datYear -eq 0 -and $parsed.Year -gt 0) { $datYear = $parsed.Year }
        if (-not $hardware -and $parsed.Hardware) { $hardware = $parsed.Hardware; $maker = $parsed.Maker }
        if ($parsed.Title) { [void]$datTitles.Add($parsed.Title) }
    }
    & $addName 'TeknoParrot' $MetadataName $false
    if ($ProfileName -and (ConvertTo-TpmGamesDbKey (Remove-TpmEmulatorName $ProfileName)) -ne (ConvertTo-TpmGamesDbKey (Remove-TpmEmulatorName $MetadataName))) { & $addName 'TeknoParrot profile' $ProfileName $false }
    & $addName 'LaunchBox title' $HintName $true
    if (-not $hardware -and $MetadataPlatform) { $hardware = $MetadataPlatform; $maker = Get-TpmMatchMaker $MetadataPlatform }
    $notGame = ''
    if ($MetadataGenre -match '(?i)^utility\b') { $notGame = 'TeknoParrot lists it as a utility, not a game.' }
    else {
        foreach ($candidate in @($MetadataName, $ProfileName) + @($datTitles)) {
            if (Test-TpmNonGameTitle -Title $candidate) { $notGame = 'It is a firmware updater, drive checker, controller or board, not a game.'; break }
        }
    }
    $display = Get-TpmDisplayTitle $(if ($MetadataName) { $MetadataName } elseif ($datTitles.Count -gt 0) { $datTitles[0] } elseif ($ProfileName) { $ProfileName } else { $Code })
    # The titles the Manager itself has used or would use. A LaunchBox title that is one of these was not typed by the owner.
    $known = @(@($Code, $ProfileName, $MetadataName, $display) + @($datTitles) | Where-Object { $_ } | Select-Object -Unique)
    # The bracketed notes of every raw name, for the region ("(JPN)", "(Japan, GDS-0026)"): only notes, so a title that says Japan stays a title.
    $regionText = (@(@($MetadataName, $ProfileName) + @($datUsed) | ForEach-Object { [regex]::Matches([string]$_, '\(([^()]*)\)') | ForEach-Object { $_.Groups[1].Value } }) -join ' ')
    return [pscustomobject]@{
        Code = $Code; Names = $names.ToArray(); Year = $(if ($MetadataYear -gt 0) { $MetadataYear } else { $datYear }); Hardware = $hardware; Maker = $maker
        NotGame = [bool]$notGame; NotGameReason = $notGame; DisplayTitle = $display; FolderConfirmed = [bool]$ConfirmedDatName
        ProfileName = $ProfileName; KnownTitles = $known; RegionText = $regionText
    }
}

# Eggman list entries by profile code (lower case): code -> list of entries. A game with two profiles is listed under both codes, and
# games whose names read the same once the year and tags are removed are all there (not only the first). Built once per plan.
function Get-TpmDatEntriesByCode {
    [CmdletBinding()] param([hashtable]$DatIndex = $null)
    $byCode = @{}
    if ($null -eq $DatIndex) { return $byCode }
    foreach ($primary in @($DatIndex.Values)) {
        $entries = New-Object System.Collections.Generic.List[object]
        [void]$entries.Add($primary)
        $alternates = $primary.PSObject.Properties['Alternates']
        if ($null -ne $alternates -and $null -ne $alternates.Value) { foreach ($alternate in $alternates.Value) { [void]$entries.Add($alternate) } }
        foreach ($entry in $entries) {
            foreach ($code in @([string]$entry.ProfileCode, [string]$entry.ProfileCode2)) {
                $key = $code.Trim().ToLowerInvariant()
                if (-not $key) { continue }
                if (-not $byCode.ContainsKey($key)) { $byCode[$key] = New-Object System.Collections.Generic.List[object] }
                [void]$byCode[$key].Add($entry)
            }
        }
    }
    return $byCode
}

# The name of the game folder that ends in [TP]: the folder of the game file or the first one above it. '' when there is none.
function Get-TpmGameFolderName {
    [CmdletBinding()] [OutputType([string])] param([string]$GamePath)
    try {
        $dir = [System.IO.Path]::GetDirectoryName($GamePath)
        while ($dir) {
            $leaf = [System.IO.Path]::GetFileName($dir)
            if ($leaf -match '\[TP\]\s*$') { return $leaf }
            $dir = [System.IO.Path]::GetDirectoryName($dir)
        }
    } catch { return '' }
    return ''
}

# The Eggman game name of the game folder in a game path, only when the list confirms the folder: the folder name is exactly the name of
# a list game for this profile code, and the file the profile starts is the file the list names inside that folder. '' otherwise.
function Get-TpmConfirmedDatName {
    [CmdletBinding()] [OutputType([string])] param([string]$Code, [string]$GamePath, [hashtable]$DatIndex = $null)
    if ([string]::IsNullOrWhiteSpace($GamePath) -or $null -eq $DatIndex -or $DatIndex.Count -eq 0) { return '' }
    $folder = Get-TpmGameFolderName -GamePath $GamePath
    if (-not $folder) { return '' }
    $entry = Get-DatEntryForZipName -RawZipName $folder -DatIndex $DatIndex
    if ($null -eq $entry -or ([string]$entry.OriginalName) -ine $folder) { return '' }
    if (([string]$entry.ProfileCode).Trim() -ine $Code -and ([string]$entry.ProfileCode2).Trim() -ine $Code) { return '' }
    $exe = ([string]$entry.Executable).Trim().Replace('/', '\').TrimStart('\')
    if ($exe -and -not $GamePath.Replace('/', '\').EndsWith(('\' + $folder + '\' + $exe), [System.StringComparison]::OrdinalIgnoreCase)) { return '' }
    return [string]$entry.OriginalName
}

# The subject of one profile, read from the files: the profile (its own name and game path), TeknoParrot's metadata and the Eggman list.
# A GamePath given by the caller (for example the path stored in a LaunchBox game) is used instead of the one in the profile.
function Get-TpmProfileMatchSubject {
    [CmdletBinding()] param(
        [Parameter(Mandatory)][string]$Code, [string]$ProfilePath = '', [string]$TpRoot = '', [string]$HintName = '', [string]$GamePath = '',
        [hashtable]$DatIndex = $null, [hashtable]$DatByCode = $null
    )
    $profileName = ''
    if ($ProfilePath -and (Test-Path -LiteralPath $ProfilePath -PathType Leaf)) {
        try {
            $doc = Read-Xml $ProfilePath
            if ($null -ne $doc.GameProfile) {
                $profileName = (Get-XmlChildText $doc.GameProfile 'GameNameInternal').Trim()
                if (-not $profileName) { $profileName = (Get-XmlChildText $doc.GameProfile 'Description').Trim() }
                if (-not $GamePath) { $GamePath = (Get-XmlChildText $doc.GameProfile 'GamePath').Trim() }
            }
        } catch { Write-Log ('Game matching: could not read the profile {0}: {1}' -f $ProfilePath, $_.Exception.Message) }
    }
    $meta = if ($TpRoot) { Get-TpmTeknoParrotMetadataFacts -TpRoot $TpRoot -ProfileCode $Code } else { [pscustomobject]@{ Name = ''; Year = 0; Platform = ''; Genre = '' } }
    $datNames = @()
    if ($null -ne $DatByCode -and $DatByCode.ContainsKey($Code.ToLowerInvariant())) { $datNames = @($DatByCode[$Code.ToLowerInvariant()] | ForEach-Object { [string]$_.OriginalName }) }
    $confirmed = Get-TpmConfirmedDatName -Code $Code -GamePath $GamePath -DatIndex $DatIndex
    return (New-TpmMatchSubject -Code $Code -ProfileName $profileName -MetadataName $meta.Name -MetadataYear $meta.Year -MetadataPlatform $meta.Platform -MetadataGenre $meta.Genre -DatNames $datNames -ConfirmedDatName $confirmed -HintName $HintName)
}

# THE DECISION. Looks the names of a subject up in the game list one level at a time and stops at the first level that is certain.
#   Certain    one game, found by the names of the sources, with nothing pointing elsewhere. A name that had to be worked out (level 3)
#              or only an extra name (weak) must also be backed up by a second source, the hardware maker or the year.
#   Ambiguous  something is there but it is not certain: the sources name different games, a worked-out name stands alone, or only a close
#              name exists. Options holds the games; Match is the best one. Nothing is ever applied for the user.
#   NoMatch    no name in the list is close enough.
#   NotGame    a firmware updater, drive checker, controller or board.
# Reason is plain words for the screen; Evidence is the technical trail for Details and the log. Facts are the year, developer and hardware
# to fill in: the list's own year and developer when the match is certain, otherwise what the Eggman list and TeknoParrot say.
function Resolve-TpmGameMatch {
    [CmdletBinding()] param([Parameter(Mandatory)]$Index, [Parameter(Mandatory)]$Subject)
    $facts = [pscustomobject]@{ Year = [int]$Subject.Year; Developer = [string]$Subject.Maker; Hardware = [string]$Subject.Hardware }
    $result = [pscustomobject]@{ Status = 'NoMatch'; Reason = 'No game with this name is in the LaunchBox list.'; Level = 0; Match = $null; Options = @(); Evidence = ''; Title = [string]$Subject.DisplayTitle; Facts = $facts }
    if ($Subject.NotGame) { $result.Status = 'NotGame'; $result.Reason = [string]$Subject.NotGameReason; return $result }
    $names = @($Subject.Names | Where-Object { $_.Name -notmatch '^\s*(World|Japan|USA|Asia|Export|Korea|Europe|Euro|China|Taiwan)\s*$' })
    $year = [int]$Subject.Year; $maker = [string]$Subject.Maker
    $strong = @($names | Where-Object { -not $_.Fallback })
    $weak = @($names | Where-Object { $_.Fallback })
    $toOption = { param($pick) [pscustomobject]@{ Id = [string]$pick.Id; Name = [string]$pick.Name; Platform = [string]$pick.Platform; Score = [double]$pick.Score } }
    foreach ($poolNumber in 0, 1) {
        $pool = if ($poolNumber -eq 0) { $strong } else { $weak }
        if ($pool.Count -eq 0) { continue }
        for ($level = 1; $level -le 3; $level++) {
            $picks = New-Object System.Collections.Generic.List[object]
            foreach ($entry in $pool) {
                $pick = Get-TpmGamesDbPick -Index $Index -Title ([string]$entry.Name) -Year $year -Maker $maker -MaxLevel $level
                if ($pick.Kind -ne 'Exact') { continue }
                $pick | Add-Member -NotePropertyName Source -NotePropertyValue ([string]$entry.Source) -Force
                [void]$picks.Add($pick)
            }
            if ($picks.Count -eq 0) { continue }
            # The names that found nothing at this level may still point at a game, at a deeper level. They agree or they argue.
            $hitNames = @($picks | ForEach-Object { [string]$_.QueryName })
            foreach ($entry in @($pool | Where-Object { $hitNames -notcontains [string]$_.Name })) {
                $pick = Get-TpmGamesDbPick -Index $Index -Title ([string]$entry.Name) -Year $year -Maker $maker -MaxLevel 3
                if ($pick.Kind -ne 'Exact') { continue }
                $pick | Add-Member -NotePropertyName Source -NotePropertyValue ([string]$entry.Source) -Force
                [void]$picks.Add($pick)
            }
            $ids = @($picks | ForEach-Object { [string]$_.Id } | Select-Object -Unique)
            $trail = 'Level {0}: {1}' -f $level, ((@($picks | ForEach-Object { '{0} "{1}" -> {2} (level {3})' -f $_.Source, $_.QueryName, $_.Name, $_.Level })) -join '; ')
            $result.Level = $level; $result.Evidence = $trail
            if ($ids.Count -gt 1) {
                # Hardware that says NESiCAxLive and a list game that says "for NESiCAxLive" are the same release; the plain game is the original.
                $nesica = @($ids | Where-Object { [string]$Index.ById[$_].Name -match '(?i)\sfor\s+NESiCAxLive$' })
                if ($nesica.Count -eq 1 -and [string]$Subject.Hardware -match '(?i)nesica') { $ids = @($nesica[0]); $trail += ' The hardware is NESiCAxLive, so the NESiCAxLive game was chosen.'; $result.Evidence = $trail }
                else {
                    $result.Status = 'Ambiguous'; $result.Reason = 'The sources name different games.'
                    $result.Options = @($picks | Group-Object Id | ForEach-Object { & $toOption $_.Group[0] })
                    $result.Match = $result.Options[0]
                    return $result
                }
            }
            $game = $Index.ById[$ids[0]]
            # Games that share this name apart from a bracketed qualifier ("Frogger" and "Frogger (Raw Thrills)"): the developer has to tell them apart.
            $plainKey = ConvertTo-TpmGamesDbKey ([regex]::Replace([string]$game.Name, '\s*\([^()]*\)\s*$', ''))
            $family = New-Object System.Collections.Generic.List[object]
            [void]$family.Add($game)
            $qualified = Get-TpmGamesDbQualifiedMap -Index $Index
            if ($qualified.ContainsKey($plainKey)) { foreach ($sibling in $qualified[$plainKey]) { [void]$family.Add($sibling) } }
            if ($plainKey -cne (ConvertTo-TpmGamesDbKey ([string]$game.Name)) -and $Index.ByName.ContainsKey($plainKey)) { foreach ($sibling in $Index.ByName[$plainKey]) { [void]$family.Add($Index.ById[[string]$sibling.Id]) } }
            $family = @($family.ToArray() | Group-Object Id | ForEach-Object { $_.Group[0] })
            if ($family.Count -gt 1 -and $maker -and [string]$Subject.Hardware -notmatch '(?i)nesica|g-?net' -and -not (Test-TpmMakerFits -Maker $maker -Game $game)) {
                $fitting = @($family | Where-Object { Test-TpmMakerFits -Maker $maker -Game $_ })
                if ($fitting.Count -eq 1) { $game = $fitting[0]; $trail += (' Several games share this name; the developer fits only {0}.' -f $game.Name); $result.Evidence = $trail }
                else {
                    $result.Status = 'Ambiguous'; $result.Reason = 'Several games have this name and the developer does not tell them apart.'
                    $result.Options = @($family | ForEach-Object { [pscustomobject]@{ Id = [string]$_.Id; Name = [string]$_.Name; Platform = [string]$_.Platform; Score = 0.0 } })
                    $result.Match = $result.Options[0]
                    return $result
                }
            }
            $agreeing = @($picks | Where-Object { [string]$_.Id -eq $ids[0] } | ForEach-Object { $_.Source } | Select-Object -Unique)
            $needsBackup = ($level -ge 3) -or ($poolNumber -eq 1)
            $backedUp = ($agreeing.Count -ge 2) -or (Test-TpmMakerFits -Maker $maker -Game $game) -or ($year -gt 0 -and [int]$game.Year -gt 0 -and [Math]::Abs($year - [int]$game.Year) -le 1)
            $result.Match = [pscustomobject]@{ Id = [string]$game.Id; Name = [string]$game.Name; Platform = [string]$game.Platform; Year = [int]$game.Year; Developer = [string]$game.Developer; Publisher = [string]$game.Publisher }
            if ($needsBackup -and -not $backedUp) {
                $result.Status = 'Ambiguous'; $result.Reason = 'Only one name points to it, and that name had to be adjusted.'
                $result.Options = @($result.Match)
                return $result
            }
            # The same name with years far apart, or a developer that does not fit, may be another game that shares the name. A port to a
            # re-release platform (NESiCAxLive, G-NET) explains the gap, so it does not count.
            $gap = if ($year -gt 0 -and [int]$game.Year -gt 0) { [Math]::Abs($year - [int]$game.Year) } else { 0 }
            $makerClash = $maker -and ([string]$game.Developer -or [string]$game.Publisher) -and -not (Test-TpmMakerFits -Maker $maker -Game $game)
            if ([string]$Subject.Hardware -notmatch '(?i)nesica|g-?net' -and ($gap -ge 10 -or ($gap -ge 5 -and $makerClash))) {
                $result.Status = 'Ambiguous'; $result.Reason = ('The years ({0} and {1}) are far apart, so it may be another game with the same name.' -f $year, $game.Year)
                $result.Options = @($result.Match)
                return $result
            }
            $result.Status = 'Certain'
            $result.Reason = if ($agreeing.Count -ge 2) { 'The names from {0} sources point to this game.' -f $agreeing.Count } else { 'The name matches this game.' }
            if ([int]$game.Year -gt 0) { $facts.Year = [int]$game.Year }
            if ([string]$game.Developer) { $facts.Developer = [string]$game.Developer }
            return $result
        }
    }
    # Nothing exact: close names are suggestions, never a match.
    $near = New-Object System.Collections.Generic.List[object]
    foreach ($entry in $strong) {
        $pick = Get-TpmGamesDbPick -Index $Index -Title ([string]$entry.Name) -Year $year -Maker $maker -MaxLevel 4
        if ($pick.Id -and -not @($near | Where-Object { $_.Id -eq [string]$pick.Id }).Count) { [void]$near.Add((& $toOption $pick)) }
    }
    if ($near.Count -gt 0) {
        $result.Status = 'Ambiguous'; $result.Reason = 'Only a close name was found.'; $result.Level = 4
        $result.Options = @($near.ToArray() | Sort-Object Score -Descending | Select-Object -First 3)
        $result.Match = $result.Options[0]
        $result.Evidence = 'Level 4: ' + ((@($result.Options | ForEach-Object { '{0} (score {1})' -f $_.Name, $_.Score })) -join '; ')
    }
    return $result
}

# ===== end of TPM GAME TITLE MATCHING (module-ready block) =====


function Get-OrCreateLaunchBoxEmulator {
    param([System.Xml.XmlDocument]$emulatorsDoc, [string]$tpRoot, [string]$lbRoot)
    $emulatorMatches = @($emulatorsDoc.SelectNodes('/LaunchBox/Emulator') | Where-Object { (Get-XmlChildText $_ 'Title') -eq 'TeknoParrot' })
    if ($emulatorMatches.Count -gt 1) { throw 'Multiple TeknoParrot emulator entries require manual resolution in LaunchBox.' }
    if ($emulatorMatches.Count -eq 1) {
        $id = Get-XmlChildText $emulatorMatches[0] 'ID'
        $guid = [guid]::Empty
        if (-not [guid]::TryParse($id,[ref]$guid) -or $guid -eq [guid]::Empty) { throw 'Existing TeknoParrot emulator identity is invalid; TPM will not edit it.' }
        if (@($emulatorsDoc.SelectNodes('/LaunchBox/Emulator') | Where-Object { (Get-XmlChildText $_ 'ID') -eq $id }).Count -ne 1) { throw 'Duplicate LaunchBox emulator identity requires manual resolution.' }
        $existingPath = Get-XmlChildText $emulatorMatches[0] 'ApplicationPath'
        if (-not $existingPath -or -not (Test-TpmLaunchBoxSamePath -Root $lbRoot -Left $existingPath -Right (Join-Path $tpRoot 'TeknoParrotUi.exe'))) { throw 'Existing TeknoParrot emulator points elsewhere; change it in LaunchBox, not TPM.' }
        return $id
    }
    $id = [guid]::NewGuid().ToString()
    $node = $emulatorsDoc.CreateElement('Emulator')
    foreach ($field in ([ordered]@{ ID=$id; Title='TeknoParrot'; ApplicationPath=(Get-RelativePath $lbRoot (Join-Path $tpRoot 'TeknoParrotUi.exe')); CommandLine='--profile=%romfile%.xml'; NoQuotes='true'; NoSpace='true'; FileNameWithoutExtensionAndPath='true' }).GetEnumerator()) { Set-XmlChildText $node $field.Key $field.Value }
    [void]$emulatorsDoc.DocumentElement.AppendChild($node)
    return $id
}

function Get-OrCreateLaunchBoxPlatform {
    param([System.Xml.XmlDocument]$platformsListDoc, [string]$platformName, [string]$tpRoot, [string]$lbRoot)
    $platformMatches = @($platformsListDoc.SelectNodes('/LaunchBox/Platform') | Where-Object { (Get-XmlChildText $_ 'Name') -eq $platformName })
    if ($platformMatches.Count -gt 1) { throw 'Duplicate LaunchBox platform names require manual resolution.' }
    if ($platformMatches.Count -eq 1) { return $false }
    $node = $platformsListDoc.CreateElement('Platform')
    foreach ($field in ([ordered]@{ Name=$platformName; Folder=(Get-RelativePath $lbRoot (Join-Path $tpRoot 'GameProfiles')); ScrapeAs='Arcade'; DisableAutoImport='true' }).GetEnumerator()) { Set-XmlChildText $node $field.Key $field.Value }
    [void]$platformsListDoc.DocumentElement.AppendChild($node)
    return $true
}

function Add-LaunchBoxEmulatorPlatformLink {
    param([System.Xml.XmlDocument]$emulatorsDoc, [string]$emulatorId, [string]$platformName, [bool]$isNewPlatform)
    if (@($emulatorsDoc.SelectNodes('/LaunchBox/EmulatorPlatform') | Where-Object { (Get-XmlChildText $_ 'Emulator') -eq $emulatorId -and (Get-XmlChildText $_ 'Platform') -eq $platformName }).Count) { return }
    $node = $emulatorsDoc.CreateElement('EmulatorPlatform')
    foreach ($field in ([ordered]@{ Emulator=$emulatorId; Platform=$platformName; CommandLine=''; Default=([string]$isNewPlatform).ToLowerInvariant() }).GetEnumerator()) { Set-XmlChildText $node $field.Key $field.Value }
    [void]$emulatorsDoc.DocumentElement.AppendChild($node)
}

$script:LaunchBoxGameSkeletonFields = [ordered]@{
    ID=''; Title=''; Platform=''; Emulator=''; ApplicationPath=''; CommandLine=''
    DateAdded=''; DateModified=''; Favorite='false'; Completed='false'; Hide='false'
    PlayCount='0'; PlayTime='0'; Notes=''
}
$script:LaunchBoxGameIdentityFields = @('ID','Title','Platform','Emulator','ApplicationPath','CommandLine','DateAdded','DateModified')

function New-LaunchBoxGameEntry {
    param([System.Xml.XmlDocument]$platformGamesDoc, [string]$relProfilePath, [string]$title, [string]$platformName, [string]$emulatorId, [string]$lbRoot, $GamesDbMatch = $null, $Facts = $null)
    # Versions grouped into one game (AdditionalApplication) count as already added, so adding games never splits a group again.
    foreach ($existing in @($platformGamesDoc.SelectNodes('/LaunchBox/Game | /LaunchBox/AdditionalApplication'))) {
        $existingPath = Get-XmlChildText $existing 'ApplicationPath'
        if ($existingPath -and (Test-TpmLaunchBoxSamePath -Root $lbRoot -Left $existingPath -Right $relProfilePath)) { return $false }
    }
    $node = $platformGamesDoc.CreateElement('Game')
    foreach ($field in $script:LaunchBoxGameSkeletonFields.GetEnumerator()) { Set-XmlChildText $node $field.Key $field.Value }
    $now = (Get-Date).ToString('o')
    $identity = @{ ID=[guid]::NewGuid().ToString(); Title=$title; Platform=$platformName; Emulator=$emulatorId; ApplicationPath=$relProfilePath; CommandLine=''; DateAdded=$now; DateModified=$now }
    foreach ($field in $script:LaunchBoxGameIdentityFields) { Set-XmlChildText $node $field $identity[$field] }
    # A sure Games Database match gives the official title and the Games Database ID, so LaunchBox can fetch information and artwork.
    if ($GamesDbMatch) { Set-XmlChildText $node 'Title' ([string]$GamesDbMatch.Name); Set-XmlChildText $node 'DatabaseID' ([string]$GamesDbMatch.Id) }
    # The release year and developer, when the sources know them (never for a field the new entry already has).
    if ($Facts) {
        if ([int]$Facts.Year -gt 0) { [void](Set-TpmLaunchBoxFieldIfEmpty -Node $node -Field 'ReleaseDate' -Value ('{0}-01-01' -f $Facts.Year)) }
        [void](Set-TpmLaunchBoxFieldIfEmpty -Node $node -Field 'Developer' -Value ([string]$Facts.Developer))
    }
    [void]$platformGamesDoc.DocumentElement.AppendChild($node)
    return $true
}

# Opens the LaunchBox Games Database for one LaunchBox folder. State: Used, Missing (no file) or Failed (could not be read).
function Get-TpmGamesDbForLaunchBox {
    param([Parameter(Mandatory)][string]$LaunchBoxRoot)
    $dbPath = Get-TpmGamesDbPath -LaunchBoxRoot $LaunchBoxRoot
    if (-not (Test-Path -LiteralPath $dbPath -PathType Leaf)) { return [pscustomobject]@{ State = 'Missing'; Index = $null; Error = 'No LaunchBox.Metadata.db was found in the LaunchBox Metadata folder.' } }
    try { return [pscustomobject]@{ State = 'Used'; Index = (Get-TpmGamesDbIndex -DbPath $dbPath); Error = '' } }
    catch {
        Write-Log ('LaunchBox game database could not be used: {0}' -f $_.Exception.Message)
        return [pscustomobject]@{ State = 'Failed'; Index = $null; Error = [string]$_.Exception.Message }
    }
}

# A game the Manager already added: give it the clean or official title, the Games Database ID when the match is certain, and the release
# year and developer when those boxes are empty. Leaves it alone when it is not the Manager's entry (other emulator), already has an ID,
# or its title is not one of the titles the Manager itself uses (KnownTitles, compared by letters and digits only): such a title was
# typed by the owner. Returns the change, or $null when nothing was changed.
function Update-TpmLaunchBoxGameTitle {
    param([System.Xml.XmlDocument]$platformGamesDoc, [string]$relProfilePath, [string[]]$KnownTitles, [string]$NewTitle, [string]$emulatorId, [string]$lbRoot, $GamesDbMatch = $null, $Facts = $null)
    $knownKeys = @(@($KnownTitles) + @($NewTitle) | ForEach-Object { ConvertTo-TpmGamesDbKey $_ } | Where-Object { $_ })
    foreach ($existing in @($platformGamesDoc.SelectNodes('/LaunchBox/Game'))) {
        $existingPath = Get-XmlChildText $existing 'ApplicationPath'
        if (-not $existingPath -or -not (Test-TpmLaunchBoxSamePath -Root $lbRoot -Left $existingPath -Right $relProfilePath)) { continue }
        if ((Get-XmlChildText $existing 'Emulator') -ne $emulatorId) { return $null }
        $currentId = (Get-XmlChildText $existing 'DatabaseID').Trim()
        if ($currentId -and $currentId -ne '0') { return $null }
        $currentTitle = Get-XmlChildText $existing 'Title'
        $currentKey = ConvertTo-TpmGamesDbKey $currentTitle
        if ($currentKey -and $knownKeys -notcontains $currentKey) { return $null }
        $titleChanges = ($GamesDbMatch -or $currentTitle -cne $NewTitle)
        if ($titleChanges) {
            Set-XmlChildText $existing 'Title' $NewTitle
            if ($GamesDbMatch) { Set-XmlChildText $existing 'DatabaseID' ([string]$GamesDbMatch.Id) }
        }
        $filled = New-Object System.Collections.Generic.List[string]
        if ($Facts) {
            if ([int]$Facts.Year -gt 0 -and (Set-TpmLaunchBoxFieldIfEmpty -Node $existing -Field 'ReleaseDate' -Value ('{0}-01-01' -f $Facts.Year))) { [void]$filled.Add('year ' + $Facts.Year) }
            if (Set-TpmLaunchBoxFieldIfEmpty -Node $existing -Field 'Developer' -Value ([string]$Facts.Developer)) { [void]$filled.Add('developer ' + $Facts.Developer) }
        }
        if (-not $titleChanges -and $filled.Count -eq 0) { return $null }
        Set-XmlChildText $existing 'DateModified' (Get-Date).ToString('o')
        return [pscustomobject]@{ Old = $currentTitle; New = $NewTitle; Id = $(if ($GamesDbMatch) { [string]$GamesDbMatch.Id } else { '' }); Kind = 'Existing'; Filled = ($filled -join ', ') }
    }
    return $null
}

function Invoke-LaunchBoxDirectWrite {
    param([string]$userProfilesDir, [string]$tpRoot, [string]$lbRoot, [string[]]$platformNames, [string]$BackupRoot, [switch]$PlanOnly, [switch]$UseGamesDb, [switch]$IncludeExisting, [hashtable]$GamesDbChoices = @{}, [hashtable]$DatIndex = $null)
    try {
        $lbRoot = Resolve-TpmLaunchBoxRoot $lbRoot
        if (-not (Test-Path -LiteralPath $lbRoot -PathType Container -ErrorAction Stop) -or -not (Test-TpmNoReparsePath $lbRoot)) { throw 'Choose a safe existing LaunchBox root.' }
        if (@($platformNames).Count -eq 0) { throw 'Choose at least one LaunchBox platform.' }
        # Guided wait instead of a 'close the app and rerun' dead end. This runs before any file inventory so LaunchBox's own save-on-exit cannot invalidate the hashes taken below; the transaction keeps its own final process check.
        if (-not $PlanOnly -and -not (Wait-TpmForProcessClose -ProcessNames @('LaunchBox','BigBox') -FriendlyName 'LaunchBox or BigBox')) {
            $stillOpen = New-TpmLaunchBoxResult NO_CHANGES 'LaunchBox or BigBox is still open and the operation was canceled. No library writes were attempted.'
            $stillOpen.Cancelled = $true; $stillOpen.Reason = 'APPLICATION_RUNNING'
            return $stillOpen
        }
        $docs = [ordered]@{}
        $originals = @{}
        foreach ($rel in @('Data\Emulators.xml','Data\Platforms.xml')) {
            $path = Get-TpmLaunchBoxPath $lbRoot $rel
            $originals[$rel] = Get-TpmLaunchBoxFileState $path
            if (-not $originals[$rel].Exists) { throw ("LaunchBox has not made {0} yet. Open LaunchBox once, close it, then try again. Nothing was changed." -f $rel) }
            $docs[$rel] = Read-TpmLaunchBoxXml $path
            Assert-TpmLaunchBoxState $path $originals[$rel]
        }
        $platformFiles = [ordered]@{}
        foreach ($name in $platformNames) {
            $safe = Get-SafeLaunchBoxPlatformFileName $name
            if ($safe -cne $name -or $name -in @('.','..')) { throw 'Platform name must be a safe, unambiguous filename.' }
            $rel = "Data\Platforms\$safe.xml"
            if ($platformFiles.Contains($rel)) { throw 'Duplicate LaunchBox platform destination.' }
            $path = Get-TpmLaunchBoxPath $lbRoot $rel
            if (-not (Test-Path -LiteralPath ([System.IO.Path]::GetDirectoryName($path)) -PathType Container -ErrorAction Stop)) { throw 'LaunchBox Data\Platforms must already exist.' }
            $platformFiles[$rel] = $name
            $originals[$rel] = Get-TpmLaunchBoxFileState $path
            $docs[$rel] = if ($originals[$rel].Exists) { Read-TpmLaunchBoxXml $path } else { [xml]'<LaunchBox />' }
            Assert-TpmLaunchBoxState $path $originals[$rel]
        }
        $plans = @()
        foreach ($rel in $docs.Keys) {
            $plans += [pscustomobject]@{ RelativePath=$rel; Before=$originals[$rel]; Document=$docs[$rel]; OriginalXml=$docs[$rel].OuterXml; BaseChildCount=$docs[$rel].DocumentElement.ChildNodes.Count; Source=$null; SourceHash=$null; Changed=$false; Delete=$false; AfterHash=$null }
        }
        $emulatorId = Get-OrCreateLaunchBoxEmulator $docs['Data\Emulators.xml'] $tpRoot $lbRoot
        # Every game gets a clean title. When LaunchBox's own game list is there (read only), a certain match gives the official title and the
        # Games Database ID. Any problem with the list means games keep the clean title, with a plain note.
        $gamesDb = $null
        $titleChanges = New-Object System.Collections.Generic.List[object]
        $titleReview = New-Object System.Collections.Generic.List[object]
        $resolvedByFile = @{}
        $datByCode = Get-TpmDatEntriesByCode -DatIndex $DatIndex
        if ($UseGamesDb) { $gamesDb = Get-TpmGamesDbForLaunchBox -LaunchBoxRoot $lbRoot }
        $counts = @{}
        $skippedMissingGame = 0
        $skippedUnreadable = New-Object System.Collections.Generic.List[string]
        $skippedBadPath = New-Object System.Collections.Generic.List[string]
        $profiles = @(Get-ChildItem -LiteralPath $userProfilesDir -Filter '*.xml' -File -ErrorAction Stop)
        foreach ($rel in $platformFiles.Keys) {
            $name = $platformFiles[$rel]
            $created = Get-OrCreateLaunchBoxPlatform $docs['Data\Platforms.xml'] $name $tpRoot $lbRoot
            Add-LaunchBoxEmulatorPlatformLink $docs['Data\Emulators.xml'] $emulatorId $name $created
            $counts[$name] = 0
            $scanTotal = $profiles.Count
            $scanStarted = Get-Date
            $scanCurrent = 0
            $scanOutcome = 'Error'
            try {
                foreach ($file in $profiles) {
                    $scanCurrent++
                    Write-TpmCompactExtractionProgress -Phase Scanning -Label 'LaunchBox direct-write profile scan' -Current $scanCurrent -Total $scanTotal -StartedAt $scanStarted
                    try {
                        $profileDoc = Read-Xml $file.FullName
                        if ($null -eq $profileDoc.GameProfile) { throw 'This is not a TeknoParrot game profile.' }
                        $gamePath = (Get-XmlChildText $profileDoc.GameProfile 'GamePath').Trim()
                        $gameFileFound = $false
                        $gamePathIllegal = $false
                        if ($gamePath) {
                            try { $gameFileFound = [System.IO.File]::Exists((ConvertTo-TpmAutoSyncLongPath -Path $gamePath)) -or [bool](Test-Path -LiteralPath $gamePath -PathType Leaf -ErrorAction Stop) }
                            catch { $gamePathIllegal = $true; $gamePathProblem = $_.Exception.Message }
                        }
                    } catch {
                        if ($name -eq @($platformFiles.Values)[0]) {
                            [void]$skippedUnreadable.Add([string]$file.Name)
                            Write-Log ('LaunchBox: skipped the profile file {0} because it could not be read: {1}' -f $file.FullName, $_.Exception.Message)
                        }
                        continue
                    }
                    if ($gamePathIllegal) {
                        if ($name -eq @($platformFiles.Values)[0]) {
                            [void]$skippedBadPath.Add([string]$file.Name)
                            Write-Log ('LaunchBox: skipped the profile file {0} because its saved game path is not a valid path: {1}' -f $file.FullName, $gamePathProblem)
                        }
                        continue
                    }
                    if (-not $gameFileFound) { if ($name -eq @($platformFiles.Values)[0]) { $skippedMissingGame++ }; continue }
                    if (-not $resolvedByFile.ContainsKey($file.Name)) {
                        $subject = Get-TpmProfileMatchSubject -Code $file.BaseName -ProfilePath $file.FullName -TpRoot $tpRoot -GamePath $gamePath -DatIndex $DatIndex -DatByCode $datByCode
                        $found = if (-not $subject.NotGame -and $gamesDb -and $gamesDb.State -eq 'Used') { Resolve-TpmGameMatch -Index $gamesDb.Index -Subject $subject } else { $null }
                        $resolvedByFile[$file.Name] = [pscustomobject]@{ Subject = $subject; Match = $found }
                        if ($found) { Write-Log ('LaunchBox match: {0} -> {1}. {2} {3}' -f $file.BaseName, $found.Status, $found.Reason, $found.Evidence) }
                    }
                    $subject = $resolvedByFile[$file.Name].Subject
                    $resolution = $resolvedByFile[$file.Name].Match
                    if ($subject.NotGame) {
                        if ($name -eq @($platformFiles.Values)[0]) { Write-Log ('LaunchBox: skipped {0} because it is not a game: {1}' -f $subject.DisplayTitle, $subject.NotGameReason) }
                        continue
                    }
                    $dbMatch = $null
                    $byChoice = $false
                    if ($resolution -and $resolution.Status -eq 'Certain') { $dbMatch = $resolution.Match }
                    elseif ($resolution -and $GamesDbChoices.ContainsKey($file.Name)) { $dbMatch = $GamesDbChoices[$file.Name]; $byChoice = $true }
                    $title = if ($dbMatch) { [string]$dbMatch.Name } else { [string]$subject.DisplayTitle }
                    # The year and developer to fill in: the game list's own when the match is certain, otherwise what the Eggman list and TeknoParrot say.
                    $facts = if ($resolution) { $resolution.Facts } else { [pscustomobject]@{ Year = [int]$subject.Year; Developer = [string]$subject.Maker } }
                    $relProfile = Get-RelativePath $lbRoot $file.FullName
                    $addedNow = New-LaunchBoxGameEntry $docs[$rel] $relProfile $title $name $emulatorId $lbRoot -GamesDbMatch $dbMatch -Facts $facts
                    if ($addedNow) {
                        $counts[$name]++
                        $oldTitle = if ($subject.ProfileName) { [string]$subject.ProfileName } else { [string]$file.BaseName }
                        $filledText = (@($(if ([int]$facts.Year -gt 0) { 'year ' + $facts.Year }), $(if ([string]$facts.Developer) { 'developer ' + $facts.Developer })) | Where-Object { $_ }) -join ', '
                        if ($dbMatch -or $title -cne $oldTitle -or $filledText) { [void]$titleChanges.Add([pscustomobject]@{ Old = $oldTitle; New = $title; Id = $(if ($dbMatch) { [string]$dbMatch.Id } else { '' }); Kind = 'New'; Choice = $byChoice; Filled = $filledText }) }
                    } elseif ($IncludeExisting) {
                        $existingChange = Update-TpmLaunchBoxGameTitle -platformGamesDoc $docs[$rel] -relProfilePath $relProfile -KnownTitles $subject.KnownTitles -NewTitle $title -emulatorId $emulatorId -lbRoot $lbRoot -GamesDbMatch $dbMatch -Facts $facts
                        if ($existingChange) {
                            $existingChange | Add-Member -NotePropertyName Choice -NotePropertyValue $byChoice -Force
                            [void]$titleChanges.Add($existingChange)
                        }
                    }
                    if ($resolution -and -not $dbMatch -and ($addedNow -or $IncludeExisting) -and -not $resolvedByFile.ContainsKey('seen:' + $file.Name)) {
                        $resolvedByFile['seen:' + $file.Name] = $true
                        [void]$titleReview.Add([pscustomobject]@{ File = $file.Name; Title = $title; Status = [string]$resolution.Status; Reason = [string]$resolution.Reason; Options = @($resolution.Options) })
                    }
                }
                $scanOutcome = 'Final'
            } finally {
                if ($scanTotal -gt 0) {
                    Write-TpmCompactExtractionProgress -Phase Scanning -Label 'LaunchBox direct-write profile scan' -Current $scanCurrent -Total $scanTotal -StartedAt $scanStarted -Complete -Outcome $scanOutcome
                }
            }
        }
        foreach ($plan in $plans) { $plan.Changed = $plan.OriginalXml -cne $plan.Document.OuterXml }
        # What the title step did, for the result screens: state, every old/new title with its ID, and the games that need a choice.
        $addTitleInfo = {
            param($target)
            $state = if ($gamesDb) { [string]$gamesDb.State } else { 'Off' }
            $target | Add-Member -NotePropertyName GamesDbState -NotePropertyValue $state -Force
            $target | Add-Member -NotePropertyName GamesDbError -NotePropertyValue $(if ($gamesDb) { [string]$gamesDb.Error } else { '' }) -Force
            $target | Add-Member -NotePropertyName TitleChanges -NotePropertyValue @($titleChanges.ToArray()) -Force
            $target | Add-Member -NotePropertyName TitleReview -NotePropertyValue @($titleReview.ToArray()) -Force
        }
        if ($PlanOnly) {
            # Read-only preview: nothing was staged, backed up, or written.
            $changedFiles = @($plans | Where-Object { $_.Changed } | ForEach-Object { $_.RelativePath })
            $addedEntries = 0; foreach ($countValue in @($counts.Values)) { $addedEntries += [int]$countValue }
            $previewSummary = if ($changedFiles.Count -eq 0) { 'Preview only: LaunchBox already has every eligible game; nothing would be written.' } else { 'Preview only, nothing was written. A write would add {0} game entries and change {1} file(s): {2}.' -f $addedEntries, $changedFiles.Count, ($changedFiles -join ', ') }
            $preview = New-TpmLaunchBoxResult NO_CHANGES $previewSummary
            $preview.Results = $counts; $preview.Reason = 'PREVIEW'
            & $addTitleInfo $preview
            $preview | Add-Member -NotePropertyName WouldChangeFiles -NotePropertyValue $changedFiles.Count -Force
            $preview | Add-Member -NotePropertyName SkippedMissingGame -NotePropertyValue $skippedMissingGame -Force
            $preview | Add-Member -NotePropertyName SkippedUnreadable -NotePropertyValue @($skippedUnreadable.ToArray()) -Force
            $preview | Add-Member -NotePropertyName SkippedBadPath -NotePropertyValue @($skippedBadPath.ToArray()) -Force
            if ($changedFiles.Count -gt 0) {
                # Name the backup folder when it is not TeknoParrot's own one, so the owner can find the snapshots later.
                $backupNote = $null
                $backupFolderPath = $null
                try {
                    $backupLocation = Resolve-TpmLaunchBoxBackupLocation -BackupRoot $BackupRoot -LaunchBoxRoot $lbRoot
                    if ($backupLocation.UsesFallback) {
                        $backupNote = 'TeknoParrot''s own backup folder is inside this LaunchBox folder, so the safety backups for this library are kept outside it, in: ' + $backupLocation.Path
                        $backupFolderPath = [string]$backupLocation.Path
                    }
                } catch { $backupNote = 'The LaunchBox safety-backup folder could not be checked; a write would stop before changing the library. Details: ' + $_.Exception.Message }
                if ($backupNote) { $preview | Add-Member -NotePropertyName BackupLocationNote -NotePropertyValue $backupNote -Force }
                if ($backupFolderPath) { $preview | Add-Member -NotePropertyName BackupLocationPath -NotePropertyValue $backupFolderPath -Force }
            }
            return $preview
        }
        $result = Invoke-TpmLaunchBoxFileTransaction -lbRoot $lbRoot -Plans $plans -BackupRoot $BackupRoot
        if ($result.Outcome -eq 'SAVED') { $result.Results = $counts }
        & $addTitleInfo $result
        $result | Add-Member -NotePropertyName SkippedMissingGame -NotePropertyValue $skippedMissingGame -Force
        $result | Add-Member -NotePropertyName SkippedUnreadable -NotePropertyValue @($skippedUnreadable.ToArray()) -Force
        $result | Add-Member -NotePropertyName SkippedBadPath -NotePropertyValue @($skippedBadPath.ToArray()) -Force
        return $result
    } catch {
        $result = New-TpmLaunchBoxResult FAILED 'LaunchBox setup was refused before library writes.'
        $result.Errors = @([string]$_.Exception.Message)
        return $result
    }
}

# =============================================================================
# LAUNCHBOX GAME DETAILS, PLAYLISTS AND "NEEDS SETUP"  (issues #420, #421 and #425)
# =============================================================================
# MODULE-READY SECTION. Everything between the START and END markers can be lifted into a .psm1 as it is.
#
# What it does: fills EMPTY release-year and developer fields from the shared matching engine (the LaunchBox game list when the match is
# certain, otherwise the Eggman list and TeknoParrot), keeps the Manager's playlists (one per hardware family, plus Light gun games,
# Driving games and Needs setup) and puts a plain "Needs setup" note on a game that cannot start yet. The note goes away by itself when
# the problem is fixed. A field that already has a value is never changed. A playlist is only touched when it carries the marker note;
# the user's own playlists are never edited. The note is a marked block inside the game's Notes: what the user wrote around it stays.
# Backup, read-back and rollback come from the existing LaunchBox file transaction; Restore is the undo.
#
# Public functions
#   Data layer (no screens, no prompts, no console output):
#     Get-TpmProfileGameKind             light gun and driving, from what the profile says
#     Get-TpmSetupProblems               what stops each game from starting, in plain words (reads files only)
#     Update-TpmLaunchBoxSetupNote       puts or removes the Needs setup block in a game's Notes
#     Set-TpmLaunchBoxFieldIfEmpty       sets a LaunchBox field only when it is empty
#     Update-TpmLaunchBoxPlaylistDocument  makes or updates one Manager playlist document
#     New-TpmLaunchBoxEnrichPlan         reads everything and builds the planned changes (writes nothing)
#     Invoke-TpmLaunchBoxEnrich          preview (-PlanOnly) or write, through the file transaction
#   Text layer (pure: objects in, strings out):
#     Format-TpmLaunchBoxEnrichLine      the preview lines (Details view and log)
#     Format-TpmLaunchBoxEnrichTitle     the one plain title line
# Screen layer (not part of the module, listed after the END marker): Invoke-TpmLaunchBoxEnrichStep
#
# Depends on (existing script functions): the matching engine, Read-Xml, Get-XmlChildText, Set-XmlChildText, Get-ProfileFamily,
#   Get-TpmMissingPrerequisites, Get-BepInExInstalledVersion, ConvertTo-TpmAutoSyncLongPath, Resolve-TpmLaunchBoxRoot,
#   Test-TpmNoReparsePath, Get-TpmLaunchBoxPath, Get-TpmLaunchBoxFileState, Assert-TpmLaunchBoxState, Read-TpmLaunchBoxXml,
#   Get-SafeLaunchBoxPlatformFileName, New-TpmLaunchBoxResult, Invoke-TpmLaunchBoxFileTransaction, Format-TpmGameCount, Write-Log.
# State: none. No script-level variables; everything is passed in parameters or returned in objects.
# START MODULE-READY SECTION: LaunchBox game details and playlists

# The note that marks a playlist as the Manager's own.
function Get-TpmLaunchBoxPlaylistMarker {
    return 'Made by TeknoParrot Manager. It keeps this playlist up to date. Your own playlists are never changed.'
}

# Light gun and driving, only from what the profile already says: GunGame, and wheel buttons.
function Get-TpmProfileGameKind {
    param([string]$ProfilePath)
    $kind = [pscustomobject]@{ LightGun = $false; Driving = $false }
    if (-not $ProfilePath -or -not (Test-Path -LiteralPath $ProfilePath -PathType Leaf)) { return $kind }
    try {
        $doc = Read-Xml $ProfilePath
        if ($null -ne $doc.GameProfile) {
            $kind.LightGun = ((Get-XmlChildText $doc.GameProfile 'GunGame').Trim() -ieq 'true')
            $kind.Driving = ((Get-ProfileFamily $doc) -eq 'driving')
        }
    } catch { Write-Log ('LaunchBox details: could not read the profile {0}: {1}' -f $ProfilePath, $_.Exception.Message) }
    return $kind
}

# What stops each game from starting, in plain words with the next step: a game file that is not found, startup files (firmware) that
# are missing, BepInEx that the profile needs and the game folder does not have. Profile code (lower case) -> list of lines. Reads files
# only: nothing is run and no database is contacted. A game whose profile cannot be read is left out, not called broken.
function Get-TpmSetupProblems {
    [CmdletBinding()] param([Parameter(Mandatory)][AllowEmptyCollection()][object[]]$ProfileFiles, [string]$TpRoot = '')
    $problems = @{}
    $add = {
        param([string]$Code, [string]$Line)
        $key = $Code.ToLowerInvariant()
        if (-not $problems.ContainsKey($key)) { $problems[$key] = New-Object System.Collections.Generic.List[string] }
        [void]$problems[$key].Add($Line)
    }
    foreach ($file in $ProfileFiles) {
        try {
            $doc = Read-Xml $file.FullName
            if ($null -eq $doc.GameProfile) { continue }
            $gamePath = (Get-XmlChildText $doc.GameProfile 'GamePath').Trim()
            if (-not $gamePath -or -not [System.IO.File]::Exists((ConvertTo-TpmAutoSyncLongPath -Path $gamePath))) {
                & $add $file.BaseName 'The game file was not found. Run Library health check (menu 13) to repair its path.'
            } elseif ((Get-XmlChildText $doc.GameProfile 'RequiresBepInEx').Trim() -ieq 'true' -and -not (Get-BepInExInstalledVersion -ExeDir ([System.IO.Path]::GetDirectoryName($gamePath)))) {
                & $add $file.BaseName 'Needs BepInEx in the game folder. Use the BepInEx step in TeknoParrot Manager.'
            }
        } catch { Write-Log ('LaunchBox setup check: could not read the profile {0}: {1}' -f $file.Name, $_.Exception.Message) }
    }
    if ($TpRoot -and @($ProfileFiles).Count -gt 0) {
        try {
            foreach ($entry in @(Get-TpmMissingPrerequisites -Profiles $ProfileFiles -TeknoParrotRoot $TpRoot)) {
                foreach ($code in @($entry.AffectedGames)) { & $add ([string]$code) ('Needs {0}: {1} is missing. Library health check (menu 13) shows where it goes.' -f $entry.Label, (@($entry.MissingFiles) -join ', ')) }
            }
        } catch { Write-Log ('LaunchBox setup check: the startup files could not be checked: {0}' -f $_.Exception.Message) }
    }
    $result = @{}
    foreach ($key in $problems.Keys) { $result[$key] = $problems[$key].ToArray() }
    return $result
}

# Puts the Needs setup block into a game's Notes, or takes it out when there are no problems. What the user wrote around the block stays.
# Returns Flagged, Cleared, or '' when nothing changed.
function Update-TpmLaunchBoxSetupNote {
    param([Parameter(Mandatory)][System.Xml.XmlNode]$Node, [AllowEmptyCollection()][string[]]$Problems = @())
    $start = '[TeknoParrot Manager: needs setup]'
    $end = '[end of TeknoParrot Manager note]'
    $notes = Get-XmlChildText $Node 'Notes'
    $without = ([regex]::Replace($notes, '(?s)(\r?\n)*' + [regex]::Escape($start) + '.*?' + [regex]::Escape($end), '')).TrimEnd()
    $new = $without
    if (@($Problems).Count -gt 0) {
        $block = $start + "`n" + 'This game is not ready to play yet:' + "`n" + ((@($Problems) | ForEach-Object { '- ' + $_ }) -join "`n") + "`n" + $end
        $new = ($without + "`n`n" + $block).TrimStart()
    }
    if ($new -ceq $notes) { return '' }
    Set-XmlChildText $Node 'Notes' $new
    return $(if (@($Problems).Count -gt 0) { 'Flagged' } else { 'Cleared' })
}

# Sets a LaunchBox field only when it is empty. Returns true when it set it.
function Set-TpmLaunchBoxFieldIfEmpty {
    param([System.Xml.XmlNode]$Node, [string]$Field, [string]$Value)
    if ([string]::IsNullOrWhiteSpace($Value)) { return $false }
    $current = (Get-XmlChildText $Node $Field).Trim()
    if ($current -ne '' -and $current -ne '0') { return $false }
    Set-XmlChildText $Node $Field $Value
    return $true
}

# Makes or updates one Manager playlist document in the format LaunchBox itself writes for a manual playlist (checked against
# real LaunchBox playlist files): one Playlist element, then one PlaylistGame element per game as its sibling (not inside it).
# Returns Skipped (a playlist of the user's with this name), New and Changed.
function Update-TpmLaunchBoxPlaylistDocument {
    param([System.Xml.XmlDocument]$Doc, [string]$Name, [object[]]$Games, [bool]$Exists)
    $marker = Get-TpmLaunchBoxPlaylistMarker
    $node = $Doc.SelectSingleNode('/LaunchBox/Playlist')
    $before = $Doc.OuterXml
    if ($Exists -and ($null -eq $node -or (Get-XmlChildText $node 'Notes') -cne $marker)) { return [pscustomobject]@{ Skipped = $true; New = $false; Changed = $false } }
    if (-not $Exists) {
        $node = $Doc.CreateElement('Playlist')
        [void]$Doc.DocumentElement.AppendChild($node)
    }
    # Every field LaunchBox writes for a manual playlist. A field that is already there is left as it is.
    $defaults = [ordered]@{
        PlaylistId = [guid]::NewGuid().ToString(); Name = $Name; NestedName = $Name; SortBy = 'Default'; Notes = $marker; VideoPath = ''
        ImageType = 'Boxes'; Category = ''; LastGameId = ''; BigBoxView = ''; BigBoxTheme = ''; IncludeWithPlatforms = 'false'
        AutoPopulate = 'false'; SortTitle = ''; IsAutogenerated = 'false'; LastSelectedChild = ''
    }
    foreach ($field in $defaults.GetEnumerator()) {
        if ($null -eq $node.SelectSingleNode($field.Key)) { Set-XmlChildText $node $field.Key $field.Value }
    }
    # An older Manager wrote the games inside the Playlist element, where LaunchBox does not look for them. Move them out.
    $legacy = @($node.SelectNodes('PlaylistGame'))
    foreach ($old in $legacy) { [void]$node.RemoveChild($old) }
    $have = @($Doc.SelectNodes('/LaunchBox/PlaylistGame') | ForEach-Object { Get-XmlChildText $_ 'GameId' } | Sort-Object)
    $want = @($Games | ForEach-Object { [string]$_.Id } | Sort-Object)
    if ($legacy.Count -gt 0 -or -not $Exists -or ($have -join '|') -cne ($want -join '|')) {
        foreach ($old in @($Doc.SelectNodes('/LaunchBox/PlaylistGame'))) { [void]$Doc.DocumentElement.RemoveChild($old) }
        $order = 0
        foreach ($game in $Games) {
            $entry = $Doc.CreateElement('PlaylistGame')
            $fields = [ordered]@{ GameId = [string]$game.Id; GameTitle = [string]$game.Title; GameFileName = [string]$game.FileName; GamePlatform = [string]$game.Platform; ManualOrder = [string]$order }
            if (-not [string]::IsNullOrWhiteSpace([string]$game.DbId)) { $fields['LaunchBoxDbId'] = [string]$game.DbId }
            foreach ($field in $fields.GetEnumerator()) { Set-XmlChildText $entry $field.Key $field.Value }
            [void]$Doc.DocumentElement.AppendChild($entry)
            $order++
        }
    }
    return [pscustomobject]@{ Skipped = $false; New = (-not $Exists); Changed = ((-not $Exists) -or ($before -cne $Doc.OuterXml)) }
}

# Reads the LaunchBox library, the profiles and the shared matching engine and builds the planned changes. Writes nothing.
# Index is the LaunchBox game list index (or $null when the list is not there: the year and developer then come from the Eggman list and
# TeknoParrot). SetupProblems is code (lower case) -> lines from Get-TpmSetupProblems; $null means "not checked", and then no note is
# put on or taken off any game.
# Returns Plans (file plans for the file transaction), Changes and the counts.
function New-TpmLaunchBoxEnrichPlan {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$LbRoot, [Parameter(Mandatory)][string]$EmulatorId,
        [Parameter(Mandatory)][string[]]$PlatformNames, [string]$TpRoot = '', [hashtable]$DatIndex = $null, $Index = $null,
        [hashtable]$SetupProblems = $null, [switch]$SkipDetails, [switch]$SkipPlaylists
    )
    $plans = New-Object System.Collections.Generic.List[object]
    $changes = New-Object System.Collections.Generic.List[object]
    $groups = [ordered]@{}
    $infoCache = @{}
    $datByCode = Get-TpmDatEntriesByCode -DatIndex $DatIndex
    $filledGames = 0; $flagged = 0; $cleared = 0
    if ($null -ne $SetupProblems) { $groups['Needs setup'] = New-Object System.Collections.Generic.List[object] }
    foreach ($name in $PlatformNames) {
        $safe = Get-SafeLaunchBoxPlatformFileName $name
        if ($safe -cne $name -or $name -in @('.', '..')) { throw 'Platform name must be a safe, unambiguous filename.' }
        $rel = "Data\Platforms\$safe.xml"
        $path = Get-TpmLaunchBoxPath $LbRoot $rel
        $state = Get-TpmLaunchBoxFileState $path
        if (-not $state.Exists) { continue }
        $doc = Read-TpmLaunchBoxXml $path
        Assert-TpmLaunchBoxState $path $state
        $filePlan = [pscustomobject]@{ RelativePath = $rel; Before = $state; Document = $doc; OriginalXml = $doc.OuterXml; BaseChildCount = $doc.DocumentElement.ChildNodes.Count; Source = $null; SourceHash = $null; Changed = $false; Delete = $false; AfterHash = $null; FullRewrite = $true }
        foreach ($game in @($doc.SelectNodes('/LaunchBox/Game'))) {
            if ((Get-XmlChildText $game 'Emulator') -ne $EmulatorId) { continue }
            $fileName = [System.IO.Path]::GetFileName((Get-XmlChildText $game 'ApplicationPath'))
            $code = [System.IO.Path]::GetFileNameWithoutExtension($fileName)
            $gameId = Get-XmlChildText $game 'ID'
            $title = Get-XmlChildText $game 'Title'
            $profilePath = Join-Path $UserProfilesDir $fileName
            $key = $code.ToLowerInvariant()
            if (-not $infoCache.ContainsKey($key)) {
                $exists = [bool](Test-Path -LiteralPath $profilePath -PathType Leaf)
                $subject = Get-TpmProfileMatchSubject -Code $code -ProfilePath $(if ($exists) { $profilePath } else { '' }) -TpRoot $TpRoot -HintName $title -DatIndex $DatIndex -DatByCode $datByCode
                $facts = [pscustomobject]@{ Year = [int]$subject.Year; Developer = [string]$subject.Maker; Hardware = [string]$subject.Hardware }
                if ($null -ne $Index -and -not $subject.NotGame) { $facts = (Resolve-TpmGameMatch -Index $Index -Subject $subject).Facts }
                $infoCache[$key] = [pscustomobject]@{ Exists = $exists; Subject = $subject; Facts = $facts; Kind = (Get-TpmProfileGameKind -ProfilePath $(if ($exists) { $profilePath } else { '' })) }
            }
            $info = $infoCache[$key]
            if ($info.Subject.NotGame) { continue }
            if (-not $SkipDetails) {
                $set = New-Object System.Collections.Generic.List[object]
                if ([int]$info.Facts.Year -gt 0 -and (Set-TpmLaunchBoxFieldIfEmpty -Node $game -Field 'ReleaseDate' -Value ('{0}-01-01' -f $info.Facts.Year))) { [void]$set.Add([pscustomobject]@{ Field = 'ReleaseDate'; Value = ('{0}-01-01' -f $info.Facts.Year) }) }
                if (Set-TpmLaunchBoxFieldIfEmpty -Node $game -Field 'Developer' -Value ([string]$info.Facts.Developer)) { [void]$set.Add([pscustomobject]@{ Field = 'Developer'; Value = [string]$info.Facts.Developer }) }
                if ($set.Count -gt 0) { $filledGames++; [void]$changes.Add([pscustomobject]@{ Kind = 'Fields'; Title = $title; Name = ''; Count = 0; Fields = $set.ToArray() }) }
            }
            $problems = @()
            if ($null -ne $SetupProblems) {
                if (-not $info.Exists) { $problems = @('The TeknoParrot profile for this game is missing. Register the game again.') }
                elseif ($SetupProblems.ContainsKey($key)) { $problems = @($SetupProblems[$key]) }
                $noteChange = Update-TpmLaunchBoxSetupNote -Node $game -Problems $problems
                if ($noteChange -eq 'Flagged') { $flagged++; [void]$changes.Add([pscustomobject]@{ Kind = 'SetupFlag'; Title = $title; Name = ''; Count = 0; Fields = @($problems) }) }
                elseif ($noteChange -eq 'Cleared') { $cleared++; [void]$changes.Add([pscustomobject]@{ Kind = 'SetupCleared'; Title = $title; Name = ''; Count = 0; Fields = @() }) }
            }
            $entry = [pscustomobject]@{ Id = $gameId; Title = $title; Platform = (Get-XmlChildText $game 'Platform'); FileName = $fileName; DbId = (Get-XmlChildText $game 'DatabaseID') }
            $listNames = @()
            $family = Get-TpmHardwareFamily ([string]$info.Facts.Hardware)
            if ($family) { $listNames += $family }
            if ($info.Kind.LightGun) { $listNames += 'Light gun games' }
            if ($info.Kind.Driving) { $listNames += 'Driving games' }
            if ($problems.Count -gt 0) { $listNames += 'Needs setup' }
            foreach ($listName in $listNames) {
                if (-not $groups.Contains($listName)) { $groups[$listName] = New-Object System.Collections.Generic.List[object] }
                [void]$groups[$listName].Add($entry)
            }
        }
        $filePlan.Changed = $filePlan.OriginalXml -cne $filePlan.Document.OuterXml
        [void]$plans.Add($filePlan)
    }
    $playlistsNew = 0; $playlistsUpdated = 0
    if (-not $SkipPlaylists) {
        foreach ($listName in @($groups.Keys)) {
            $safe = (Get-SafeLaunchBoxPlatformFileName $listName).TrimEnd('.', ' ')
            $rel = "Data\Playlists\$safe.xml"
            $path = Get-TpmLaunchBoxPath $LbRoot $rel
            $state = Get-TpmLaunchBoxFileState $path
            # A playlist that nothing needs and that was never made stays unmade.
            if (-not $state.Exists -and $groups[$listName].Count -eq 0) { continue }
            # Plain assignments: an if-expression would unroll the XML document into its child nodes.
            if ($state.Exists) { $doc = Read-TpmLaunchBoxXml $path; Assert-TpmLaunchBoxState $path $state } else { $doc = New-Object System.Xml.XmlDocument; $doc.LoadXml('<LaunchBox />') }
            $filePlan = [pscustomobject]@{ RelativePath = $rel; Before = $state; Document = $doc; OriginalXml = $doc.OuterXml; BaseChildCount = $doc.DocumentElement.ChildNodes.Count; Source = $null; SourceHash = $null; Changed = $false; Delete = $false; AfterHash = $null; FullRewrite = $true }
            $outcome = Update-TpmLaunchBoxPlaylistDocument -Doc $doc -Name $listName -Games $groups[$listName].ToArray() -Exists $state.Exists
            if ($outcome.Skipped) { [void]$changes.Add([pscustomobject]@{ Kind = 'PlaylistSkipped'; Title = ''; Name = $listName; Count = $groups[$listName].Count; Fields = @() }); continue }
            $filePlan.Changed = $filePlan.OriginalXml -cne $filePlan.Document.OuterXml
            if ($filePlan.Changed) {
                if ($outcome.New) { $playlistsNew++ } else { $playlistsUpdated++ }
                [void]$changes.Add([pscustomobject]@{ Kind = $(if ($outcome.New) { 'PlaylistNew' } else { 'PlaylistUpdated' }); Title = ''; Name = $listName; Count = $groups[$listName].Count; Fields = @() })
            }
            [void]$plans.Add($filePlan)
        }
    }
    return [pscustomobject]@{
        Plans = $plans.ToArray(); Changes = $changes.ToArray()
        FilledGames = $filledGames; PlaylistsNew = $playlistsNew; PlaylistsUpdated = $playlistsUpdated; SetupFlagged = $flagged; SetupCleared = $cleared
    }
}

# The preview lines for the Details view and the log. Pure: plan in, strings out.
function Format-TpmLaunchBoxEnrichLine {
    param([Parameter(Mandatory)]$Plan)
    $words = @{ ReleaseDate = 'year'; Developer = 'developer' }
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($change in @($Plan.Changes)) {
        switch ($change.Kind) {
            'Fields' { [void]$lines.Add(('{0}: will fill in {1}' -f $change.Title, ((@($change.Fields) | ForEach-Object { '{0} {1}' -f $words[$_.Field], $(if ($_.Field -eq 'ReleaseDate') { ([string]$_.Value).Substring(0, 4) } else { $_.Value }) }) -join ', '))) }
            'SetupFlag' { [void]$lines.Add(('{0}: will be marked Needs setup. {1}' -f $change.Title, (@($change.Fields) -join ' '))) }
            'SetupCleared' { [void]$lines.Add(('{0}: is ready now, so its Needs setup note will be removed' -f $change.Title)) }
            'PlaylistNew' { [void]$lines.Add(('Playlist {0}: will be made with {1}' -f $change.Name, (Format-TpmGameCount -Count ([int]$change.Count)))) }
            'PlaylistUpdated' { [void]$lines.Add(('Playlist {0}: will be updated to {1}' -f $change.Name, (Format-TpmGameCount -Count ([int]$change.Count)))) }
            'PlaylistSkipped' { [void]$lines.Add(('Playlist {0}: left alone, because it is not one TeknoParrot Manager made' -f $change.Name)) }
        }
    }
    return $lines.ToArray()
}

# The one plain title line. -Preview words it as a preview; otherwise it says what was filled in.
function Format-TpmLaunchBoxEnrichTitle {
    param([Parameter(Mandatory)]$Plan, [switch]$Preview)
    $parts = New-Object System.Collections.Generic.List[string]
    if ($Plan.FilledGames -gt 0) { [void]$parts.Add(('details for {0}' -f (Format-TpmGameCount -Count ([int]$Plan.FilledGames)))) }
    $playlistTotal = [int]$Plan.PlaylistsNew + [int]$Plan.PlaylistsUpdated
    if ($playlistTotal -gt 0) { [void]$parts.Add(('{0} {1}' -f $playlistTotal, $(if ($playlistTotal -eq 1) { 'playlist' } else { 'playlists' }))) }
    if ([int]$Plan.SetupFlagged -gt 0) { [void]$parts.Add(('{0} marked Needs setup' -f (Format-TpmGameCount -Count ([int]$Plan.SetupFlagged)))) }
    if ([int]$Plan.SetupCleared -gt 0) { [void]$parts.Add(('{0} ready again' -f (Format-TpmGameCount -Count ([int]$Plan.SetupCleared)))) }
    if ($Preview) {
        if ($parts.Count -eq 0) { return 'Preview: nothing to fill in or update. Nothing would change.' }
        return ('Preview: LaunchBox would get {0}. Nothing was changed.' -f ($parts -join ' and '))
    }
    if ($parts.Count -eq 0) { return 'Nothing to fill in or update.' }
    return ('Filled in {0}.' -f ($parts -join ' and '))
}

# Fills empty year and developer fields, keeps the Manager's playlists and the Needs setup notes. -PlanOnly reads everything and changes nothing.
# Returns the same kind of result as Invoke-LaunchBoxDirectWrite plus EnrichPlan (the plan this run used).
# The caller makes sure LaunchBox and BigBox are closed before a write; the transaction also checks and refuses while they run.
function Invoke-TpmLaunchBoxEnrich {
    param(
        [string]$UserProfilesDir, [string]$LbRoot, [string[]]$PlatformNames, [string]$BackupRoot, [string]$TpRoot = '', [hashtable]$DatIndex = $null,
        [switch]$PlanOnly, [switch]$SkipDetails, [switch]$SkipPlaylists
    )
    try {
        $root = Resolve-TpmLaunchBoxRoot $LbRoot
        if (-not (Test-Path -LiteralPath $root -PathType Container -ErrorAction Stop) -or -not (Test-TpmNoReparsePath $root)) { throw 'Choose a safe existing LaunchBox root.' }
        if (@($PlatformNames).Count -eq 0) { throw 'Choose at least one LaunchBox platform.' }
        $emulatorsPath = Get-TpmLaunchBoxPath $root 'Data\Emulators.xml'
        $emulatorsState = Get-TpmLaunchBoxFileState $emulatorsPath
        if (-not $emulatorsState.Exists) { throw 'LaunchBox has not made Data\Emulators.xml yet. Open LaunchBox once, close it, then try again. Nothing was changed.' }
        $emulatorsDoc = Read-TpmLaunchBoxXml $emulatorsPath
        $emulatorNode = @($emulatorsDoc.SelectNodes('/LaunchBox/Emulator') | Where-Object { (Get-XmlChildText $_ 'Title') -eq 'TeknoParrot' } | Select-Object -First 1)
        if ($emulatorNode.Count -eq 0) {
            $none = New-TpmLaunchBoxResult NO_CHANGES 'No TeknoParrot games are in LaunchBox yet. Add them first.'
            if ($PlanOnly) { $none.Reason = 'PREVIEW' }
            return $none
        }
        $gamesDb = Get-TpmGamesDbForLaunchBox -LaunchBoxRoot $root
        $setup = $null
        if ($UserProfilesDir -and (Test-Path -LiteralPath $UserProfilesDir -PathType Container)) { $setup = Get-TpmSetupProblems -ProfileFiles @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter '*.xml' -File -ErrorAction Stop) -TpRoot $TpRoot }
        $plan = New-TpmLaunchBoxEnrichPlan -UserProfilesDir $UserProfilesDir -LbRoot $root -EmulatorId (Get-XmlChildText $emulatorNode[0] 'ID') -PlatformNames $PlatformNames -TpRoot $TpRoot -DatIndex $DatIndex -Index $gamesDb.Index -SetupProblems $setup -SkipDetails:$SkipDetails -SkipPlaylists:$SkipPlaylists
        foreach ($line in (Format-TpmLaunchBoxEnrichLine -Plan $plan)) { Write-Log ('LaunchBox details and playlists: ' + $line) }
        $changedPlans = @($plan.Plans | Where-Object { $_.Changed })
        if ($PlanOnly) {
            $preview = New-TpmLaunchBoxResult NO_CHANGES ('Preview only, nothing was written. A write would change {0} file(s).' -f $changedPlans.Count)
            $preview.Reason = 'PREVIEW'
            $preview | Add-Member -NotePropertyName WouldChangeFiles -NotePropertyValue $changedPlans.Count -Force
            $preview | Add-Member -NotePropertyName EnrichPlan -NotePropertyValue $plan -Force
            return $preview
        }
        if (@($changedPlans | Where-Object { $_.RelativePath -like 'Data\Playlists\*' }).Count -gt 0) {
            $playlistFolder = Join-Path $root 'Data\Playlists'
            if (-not (Test-TpmNoReparsePath $playlistFolder)) { throw 'The LaunchBox Playlists folder is not a normal folder.' }
            [void][System.IO.Directory]::CreateDirectory($playlistFolder)
        }
        $result = Invoke-TpmLaunchBoxFileTransaction -lbRoot $root -Plans $plan.Plans -BackupRoot $BackupRoot
        $result | Add-Member -NotePropertyName EnrichPlan -NotePropertyValue $plan -Force
        return $result
    } catch {
        $result = New-TpmLaunchBoxResult FAILED 'LaunchBox details and playlists were refused before library writes.'
        $result.Errors = @([string]$_.Exception.Message)
        return $result
    }
}
# END MODULE-READY SECTION: LaunchBox game details and playlists

# BEGIN MODULE-READY SECTION: LaunchBox Games Database links for TeknoParrot games
# Links LaunchBox games that have no Games Database ID to their entry in LaunchBox's own game list, so LaunchBox finds the right
# art and details. The game name comes from TeknoParrot's own metadata for the game (Metadata\<profile>.json), so it works for games
# that have no user profile yet. An exact name match is "Sure". A close but not exact match is "Check" and is applied only when the
# caller lists that game as approved. Titles a user changed by hand are kept. Prefix: TpmLaunchBoxIdLink / TpmTeknoParrotGameName.
# Needs from the rest of the script: the Games Database functions above, the LaunchBox XML/file helpers and Invoke-TpmLaunchBoxFileTransaction.
# This section has no script-level variables and no screens; the screen step is below.
function New-TpmLaunchBoxIdLinkPlan {
    param(
        [Parameter(Mandatory)][string]$LbRoot, [Parameter(Mandatory)][string]$TpRoot, [Parameter(Mandatory)][string]$EmulatorId,
        [Parameter(Mandatory)][string[]]$PlatformNames, [Parameter(Mandatory)]$Index, [hashtable]$Choices = @{}, [hashtable]$DatIndex = $null
    )
    $plans = New-Object System.Collections.Generic.List[object]
    $items = New-Object System.Collections.Generic.List[object]
    $datByCode = Get-TpmDatEntriesByCode -DatIndex $DatIndex
    foreach ($name in $PlatformNames) {
        $safe = Get-SafeLaunchBoxPlatformFileName $name
        if ($safe -cne $name -or $name -in @('.', '..')) { throw 'Platform name must be a safe, unambiguous filename.' }
        $rel = "Data\Platforms\$safe.xml"
        $path = Get-TpmLaunchBoxPath $LbRoot $rel
        $state = Get-TpmLaunchBoxFileState $path
        if (-not $state.Exists) { continue }
        $doc = Read-TpmLaunchBoxXml $path
        Assert-TpmLaunchBoxState $path $state
        $filePlan = [pscustomobject]@{ RelativePath = $rel; Before = $state; Document = $doc; OriginalXml = $doc.OuterXml; BaseChildCount = $doc.DocumentElement.ChildNodes.Count; Source = $null; SourceHash = $null; Changed = $false; Delete = $false; AfterHash = $null; FullRewrite = $true }
        foreach ($game in @($doc.SelectNodes('/LaunchBox/Game'))) {
            if ((Get-XmlChildText $game 'Emulator') -ne $EmulatorId) { continue }
            $currentId = (Get-XmlChildText $game 'DatabaseID').Trim()
            if ($currentId -and $currentId -ne '0') { continue }
            $gameId = Get-XmlChildText $game 'ID'
            $title = Get-XmlChildText $game 'Title'
            $code = [System.IO.Path]::GetFileNameWithoutExtension((Get-XmlChildText $game 'ApplicationPath'))
            $profilePath = ''
            if ($code -match '^[A-Za-z0-9_.\-]+$' -and $code -notmatch '^\.+$') {
                $profilePath = Join-Path (Join-Path $TpRoot 'UserProfiles') ($code + '.xml')
                if (-not (Test-Path -LiteralPath $profilePath -PathType Leaf)) { $profilePath = Join-Path (Join-Path $TpRoot 'GameProfiles') ($code + '.xml') }
            }
            $subject = Get-TpmProfileMatchSubject -Code $code -ProfilePath $profilePath -TpRoot $TpRoot -HintName $title -DatIndex $DatIndex -DatByCode $datByCode
            $resolved = Resolve-TpmGameMatch -Index $Index -Subject $subject
            $apply = $null
            if ($resolved.Status -eq 'Certain') { $apply = $resolved.Match }
            elseif ($resolved.Status -eq 'Ambiguous' -and $Choices.ContainsKey($gameId)) { $apply = @($resolved.Options | Where-Object { [string]$_.Id -eq [string]$Choices[$gameId] })[0] }
            $applied = $false; $titleChanged = $false
            if ($apply) {
                Set-XmlChildText $game 'DatabaseID' ([string]$apply.Id)
                # Only a title that is empty or one of the titles the Manager itself uses (also when only capitals, spaces or punctuation
                # differ) is replaced; any other name, such as one the user typed, stays.
                $titleKey = ConvertTo-TpmGamesDbKey $title
                $known = @(@($subject.KnownTitles) + @([string]$apply.Name) | ForEach-Object { ConvertTo-TpmGamesDbKey $_ })
                if (-not $titleKey -or $known -contains $titleKey) {
                    if ($title -cne [string]$apply.Name) { Set-XmlChildText $game 'Title' ([string]$apply.Name); $titleChanged = $true }
                }
                Set-XmlChildText $game 'DateModified' (Get-Date).ToString('o')
                $applied = $true
            }
            $best = if ($apply) { $apply } else { $resolved.Match }
            [void]$items.Add([pscustomobject]@{ GameId = $gameId; Title = $title; Code = $code; Status = [string]$resolved.Status; Reason = [string]$resolved.Reason; Options = @($resolved.Options); MatchName = $(if ($best) { [string]$best.Name } else { '' }); MatchId = $(if ($best) { [string]$best.Id } else { '' }); Applied = $applied; TitleChanged = $titleChanged; Level = $resolved.Level; Evidence = $resolved.Evidence })
        }
        $filePlan.Changed = $filePlan.OriginalXml -cne $filePlan.Document.OuterXml
        [void]$plans.Add($filePlan)
    }
    return [pscustomobject]@{ Plans = $plans.ToArray(); Items = $items.ToArray() }
}

# Plain preview lines. Pure: plan in, strings out.
function Format-TpmLaunchBoxIdLinkLine {
    param([Parameter(Mandatory)]$Plan)
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($item in @($Plan.Items)) {
        switch ($item.Status) {
            'Certain' {
                $keepNote = if (-not $item.TitleChanged -and $item.Title -cne $item.MatchName) { ' The name in LaunchBox stays as it is.' } else { '' }
                [void]$lines.Add(('{0}: will be linked to {1}.{2}' -f $item.Title, $item.MatchName, $keepNote))
            }
            'Ambiguous' { [void]$lines.Add(('{0}: not sure. {1} Best guess: {2}. {3}' -f $item.Title, $item.Reason, $item.MatchName, $(if ($item.Applied) { 'You chose it.' } else { 'Waiting for your choice.' }))) }
            'NotGame' { [void]$lines.Add(('{0}: not a game. Left alone.' -f $item.Title)) }
            default { [void]$lines.Add(('{0}: no match found in the LaunchBox game list. Left alone.' -f $item.Title)) }
        }
    }
    return $lines.ToArray()
}

function Format-TpmLaunchBoxIdLinkTitle {
    param([Parameter(Mandatory)]$Plan, [switch]$Preview)
    $items = @($Plan.Items)
    $certain = @($items | Where-Object { $_.Status -eq 'Certain' }).Count
    $unsure = @($items | Where-Object { $_.Status -eq 'Ambiguous' }).Count
    $chosen = @($items | Where-Object { $_.Status -eq 'Ambiguous' -and $_.Applied }).Count
    $none = @($items | Where-Object { $_.Status -eq 'NoMatch' }).Count
    if ($items.Count -eq 0) { return 'Every TeknoParrot game in LaunchBox already has a Games Database ID. Nothing to do.' }
    $parts = New-Object System.Collections.Generic.List[string]
    if ($certain -gt 0) { [void]$parts.Add(('{0} sure {1}' -f $certain, $(if ($certain -eq 1) { 'match' } else { 'matches' }))) }
    if ($unsure -gt 0) { [void]$parts.Add(('{0} not sure, for you to choose' -f $unsure)) }
    if ($none -gt 0) { [void]$parts.Add(('{0} with no match' -f $none)) }
    if ($Preview) { return ('Preview: {0}. Nothing was changed.' -f ($parts -join ', ')) }
    return ('Linked {0} {1} to the LaunchBox game list.' -f ($certain + $chosen), $(if (($certain + $chosen) -eq 1) { 'game' } else { 'games' }))
}

# -PlanOnly reads everything and changes nothing. Choices maps a game id to the Games Database id the user picked for a game that was not sure.
# The caller makes sure LaunchBox and BigBox are closed before a write; the transaction also checks and refuses while they run.
function Invoke-TpmLaunchBoxIdLink {
    param([string]$LbRoot, [string]$TpRoot, [string[]]$PlatformNames = @('TeknoParrot'), [string]$BackupRoot, [hashtable]$Choices = @{}, [hashtable]$DatIndex = $null, [switch]$PlanOnly)
    try {
        $root = Resolve-TpmLaunchBoxRoot $LbRoot
        if (-not (Test-Path -LiteralPath $root -PathType Container -ErrorAction Stop) -or -not (Test-TpmNoReparsePath $root)) { throw 'Choose a safe existing LaunchBox root.' }
        $dbPath = Get-TpmGamesDbPath -LaunchBoxRoot $root
        if (-not (Test-Path -LiteralPath $dbPath -PathType Leaf)) { throw 'The LaunchBox game list was not found, so nothing can be linked. Nothing was changed.' }
        $emulatorsPath = Get-TpmLaunchBoxPath $root 'Data\Emulators.xml'
        if (-not (Get-TpmLaunchBoxFileState $emulatorsPath).Exists) { throw 'LaunchBox has not made Data\Emulators.xml yet. Open LaunchBox once, close it, then try again. Nothing was changed.' }
        $emulatorsDoc = Read-TpmLaunchBoxXml $emulatorsPath
        $emulatorNode = @($emulatorsDoc.SelectNodes('/LaunchBox/Emulator') | Where-Object { (Get-XmlChildText $_ 'Title') -eq 'TeknoParrot' } | Select-Object -First 1)
        if ($emulatorNode.Count -eq 0) {
            $none = New-TpmLaunchBoxResult NO_CHANGES 'No TeknoParrot games are in LaunchBox yet. Add them first.'
            if ($PlanOnly) { $none.Reason = 'PREVIEW' }
            return $none
        }
        $index = Get-TpmGamesDbIndex -DbPath $dbPath
        $plan = New-TpmLaunchBoxIdLinkPlan -LbRoot $root -TpRoot $TpRoot -EmulatorId (Get-XmlChildText $emulatorNode[0] 'ID') -PlatformNames $PlatformNames -Index $index -Choices $Choices -DatIndex $DatIndex
        foreach ($line in (Format-TpmLaunchBoxIdLinkLine -Plan $plan)) { Write-Log ('LaunchBox links: ' + $line) }
        foreach ($item in @($plan.Items)) { if ($item.Evidence) { Write-Log ('LaunchBox links: {0} -> {1}. {2}' -f $item.Code, $item.MatchName, $item.Evidence) } }
        $changedPlans = @($plan.Plans | Where-Object { $_.Changed })
        if ($PlanOnly) {
            $preview = New-TpmLaunchBoxResult NO_CHANGES ('Preview only, nothing was written. A write would change {0} file(s).' -f $changedPlans.Count)
            $preview.Reason = 'PREVIEW'
            $preview | Add-Member -NotePropertyName WouldChangeFiles -NotePropertyValue $changedPlans.Count -Force
            $preview | Add-Member -NotePropertyName LinkPlan -NotePropertyValue $plan -Force
            return $preview
        }
        $result = Invoke-TpmLaunchBoxFileTransaction -lbRoot $root -Plans $plan.Plans -BackupRoot $BackupRoot
        $result | Add-Member -NotePropertyName LinkPlan -NotePropertyValue $plan -Force
        return $result
    } catch {
        $result = New-TpmLaunchBoxResult FAILED 'LaunchBox game links were refused before library writes.'
        $result.Errors = @([string]$_.Exception.Message)
        return $result
    }
}
# END MODULE-READY SECTION: LaunchBox Games Database links for TeknoParrot games

# BEGIN MODULE-READY SECTION: LaunchBox game versions and keeping in step (issues #422 and #423)
# Versions: several regions or versions of one game become ONE LaunchBox game with a version picker. LaunchBox keeps the extra versions as
# AdditionalApplication entries of the game (the "Play ... version" choices). Two games are the same game only when they have the same
# Games Database ID: the ID LaunchBox already holds for the entry, or a certain match of the shared matching engine. The default version
# follows the region the user chose in Region setup. Keeping in step: entries whose profile is gone are removed, moved ones get their new
# path, old Manager titles are made clean. Both touch only games the Manager added (the TeknoParrot emulator). Backup, read-back and
# rollback come from the existing LaunchBox file transaction; Restore is the undo.
# Public functions: ConvertTo-TpmRegionKey, Get-TpmPreferredRegion, New-TpmLaunchBoxGroupPlan, Format-TpmLaunchBoxGroupLine,
#   Format-TpmLaunchBoxGroupTitle, New-TpmLaunchBoxSyncPlan, Format-TpmLaunchBoxSyncLine, Format-TpmLaunchBoxSyncTitle,
#   Invoke-TpmLaunchBoxLibraryChange. Screen layer after the END marker: Invoke-TpmLaunchBoxChangeStep.
# Depends on: the matching engine, Get-TpmRegionGames, the LaunchBox file helpers listed for the details section.

# One word for a region note: Japan, USA, Europe, Asia, Korea, Export (also World), or '' when there is none.
function ConvertTo-TpmRegionKey {
    [CmdletBinding()] [OutputType([string])] param([string]$Text)
    $note = [string]$Text
    if ($note -match '(?i)\b(?:jpn|japan|japanese|jp)\b') { return 'Japan' }
    if ($note -match '(?i)\b(?:usa|us|america)\b') { return 'USA' }
    if ($note -match '(?i)\b(?:europe|euro|eur|uk)\b') { return 'Europe' }
    if ($note -match '(?i)\basia\b') { return 'Asia' }
    if ($note -match '(?i)\b(?:korea|kor)\b') { return 'Korea' }
    if ($note -match '(?i)\b(?:export|exp|world|international)\b') { return 'Export' }
    return ''
}

# The region the user chose in Region setup: the most common region among the profiles set to a region (Auto and Default do not count).
function Get-TpmPreferredRegion {
    [CmdletBinding()] [OutputType([string])] param([AllowEmptyCollection()][string[]]$ProfilePaths = @())
    $count = @{}
    foreach ($game in @(Get-TpmRegionGames -Paths @($ProfilePaths))) {
        if ($game.IsNeutral) { continue }
        $key = ConvertTo-TpmRegionKey $game.Value
        if ($key) { $count[$key] = [int]$count[$key] + 1 }
    }
    if ($count.Count -eq 0) { return '' }
    return [string]@($count.GetEnumerator() | Sort-Object @{ Expression = 'Value'; Descending = $true }, @{ Expression = 'Key' })[0].Key
}

# Reads the LaunchBox library and builds the planned groups. Writes nothing. Index is the game list index (or $null: only entries that
# already have a Games Database ID can be grouped). Returns Plans (for the file transaction), Groups and the counts.
function New-TpmLaunchBoxGroupPlan {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$LbRoot, [Parameter(Mandatory)][string]$EmulatorId,
        [Parameter(Mandatory)][string[]]$PlatformNames, [string]$TpRoot = '', [hashtable]$DatIndex = $null, $Index = $null, [string]$PreferredRegion = ''
    )
    $plans = New-Object System.Collections.Generic.List[object]
    $groupsOut = New-Object System.Collections.Generic.List[object]
    $datByCode = Get-TpmDatEntriesByCode -DatIndex $DatIndex
    $versionsMade = 0
    foreach ($name in $PlatformNames) {
        $safe = Get-SafeLaunchBoxPlatformFileName $name
        if ($safe -cne $name -or $name -in @('.', '..')) { throw 'Platform name must be a safe, unambiguous filename.' }
        $rel = "Data\Platforms\$safe.xml"
        $path = Get-TpmLaunchBoxPath $LbRoot $rel
        $state = Get-TpmLaunchBoxFileState $path
        if (-not $state.Exists) { continue }
        $doc = Read-TpmLaunchBoxXml $path
        Assert-TpmLaunchBoxState $path $state
        $filePlan = [pscustomobject]@{ RelativePath = $rel; Before = $state; Document = $doc; OriginalXml = $doc.OuterXml; BaseChildCount = $doc.DocumentElement.ChildNodes.Count; Source = $null; SourceHash = $null; Changed = $false; Delete = $false; AfterHash = $null; FullRewrite = $true }
        $members = @{}
        foreach ($game in @($doc.SelectNodes('/LaunchBox/Game'))) {
            if ((Get-XmlChildText $game 'Emulator') -ne $EmulatorId) { continue }
            $fileName = [System.IO.Path]::GetFileName((Get-XmlChildText $game 'ApplicationPath'))
            $code = [System.IO.Path]::GetFileNameWithoutExtension($fileName)
            $profilePath = Join-Path $UserProfilesDir $fileName
            if (-not (Test-Path -LiteralPath $profilePath -PathType Leaf)) { continue }
            $title = Get-XmlChildText $game 'Title'
            $subject = Get-TpmProfileMatchSubject -Code $code -ProfilePath $profilePath -TpRoot $TpRoot -HintName $title -DatIndex $DatIndex -DatByCode $datByCode
            if ($subject.NotGame) { continue }
            $key = (Get-XmlChildText $game 'DatabaseID').Trim()
            if (-not $key -or $key -eq '0') {
                $key = ''
                if ($null -ne $Index) { $found = Resolve-TpmGameMatch -Index $Index -Subject $subject; if ($found.Status -eq 'Certain') { $key = [string]$found.Match.Id } }
            }
            if (-not $key) { continue }
            if (-not $members.ContainsKey($key)) { $members[$key] = New-Object System.Collections.Generic.List[object] }
            [void]$members[$key].Add([pscustomobject]@{ Node = $game; Code = $code; Title = $title; Id = (Get-XmlChildText $game 'ID'); Region = (ConvertTo-TpmRegionKey $subject.RegionText) })
        }
        foreach ($key in @($members.Keys)) {
            if ($members[$key].Count -lt 2) { continue }
            # The default version: the region the user chose, then a world or unmarked release, then any other region but Japan, then the rest.
            $ordered = @($members[$key].ToArray() | Sort-Object @{ Expression = { if ($PreferredRegion -and $_.Region -eq $PreferredRegion) { 0 } elseif ($_.Region -in @('', 'Export')) { 1 } elseif ($_.Region -ne 'Japan') { 2 } else { 3 } } }, @{ Expression = { $_.Code } })
            $default = $ordered[0]
            $others = @($ordered | Select-Object -Skip 1)
            $priority = 1
            foreach ($other in $others) {
                $priority++
                $versionName = if ($other.Region) { '{0} ({1})' -f $other.Title, $other.Region } else { '{0} ({1})' -f $other.Title, $other.Code }
                $app = $doc.CreateElement('AdditionalApplication')
                $fields = [ordered]@{
                    Id = [guid]::NewGuid().ToString(); PlayCount = (Get-XmlChildText $other.Node 'PlayCount'); PlayTime = (Get-XmlChildText $other.Node 'PlayTime'); GameID = $default.Id
                    ApplicationPath = (Get-XmlChildText $other.Node 'ApplicationPath'); AutoRunAfter = 'false'; AutoRunBefore = 'false'; CommandLine = (Get-XmlChildText $other.Node 'CommandLine')
                    Name = $versionName; UseDosBox = 'false'; UseEmulator = 'true'; WaitForExit = 'false'; ReleaseDate = (Get-XmlChildText $other.Node 'ReleaseDate')
                    Developer = (Get-XmlChildText $other.Node 'Developer'); Publisher = (Get-XmlChildText $other.Node 'Publisher'); Region = $other.Region; Version = $other.Code
                    Status = ''; Section = ''; EmulatorId = $EmulatorId; SideA = 'false'; SideB = 'false'; Priority = [string]$priority
                }
                foreach ($field in $fields.GetEnumerator()) { Set-XmlChildText $app $field.Key ([string]$field.Value) }
                # Versions the other entry already had move to the default game; the entry itself becomes a version.
                foreach ($old in @($doc.SelectNodes('/LaunchBox/AdditionalApplication') | Where-Object { (Get-XmlChildText $_ 'GameID') -eq $other.Id })) { Set-XmlChildText $old 'GameID' $default.Id }
                [void]$doc.DocumentElement.AppendChild($app)
                [void]$doc.DocumentElement.RemoveChild($other.Node)
                $versionsMade++
            }
            [void]$groupsOut.Add([pscustomobject]@{ Title = $default.Title; Default = $default.Code; DefaultRegion = $default.Region; Versions = @($others | ForEach-Object { $_.Code }); Count = $ordered.Count })
        }
        $filePlan.Changed = $filePlan.OriginalXml -cne $filePlan.Document.OuterXml
        [void]$plans.Add($filePlan)
    }
    return [pscustomobject]@{ Plans = $plans.ToArray(); Groups = $groupsOut.ToArray(); VersionsMade = $versionsMade; PreferredRegion = $PreferredRegion }
}

# The preview lines for the Details view and the log. Pure: plan in, strings out.
function Format-TpmLaunchBoxGroupLine {
    param([Parameter(Mandatory)]$Plan)
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($group in @($Plan.Groups)) {
        $region = if ($group.DefaultRegion) { ' (' + $group.DefaultRegion + ')' } else { '' }
        [void]$lines.Add(('{0}: {1} entries become one game. The default version is {2}{3}; the other versions are {4}.' -f $group.Title, $group.Count, $group.Default, $region, (@($group.Versions) -join ', ')))
    }
    return $lines.ToArray()
}

# The one plain title line.
function Format-TpmLaunchBoxGroupTitle {
    param([Parameter(Mandatory)]$Plan, [switch]$Preview)
    $groups = @($Plan.Groups).Count
    if ($groups -eq 0) { return 'No game has more than one version in LaunchBox. Nothing to group.' }
    $note = if ($Plan.PreferredRegion) { ' The default version follows your region choice: ' + $Plan.PreferredRegion + '.' } else { '' }
    if ($Preview) { return ('Preview: {0} would become one game with versions.{1} Nothing was changed.' -f (Format-TpmGameCount -Count $groups), $note) }
    return ('Grouped the versions of {0}.{1}' -f (Format-TpmGameCount -Count $groups), $note)
}

# Issue #423: keep LaunchBox in step with the library. Looks only at games the Manager added. Reads the LaunchBox library and the
# TeknoParrot profiles and plans: remove entries whose profile is gone (never for a missing game file: that is a disconnected drive),
# fix the profile path of entries whose TeknoParrot folder moved, and give back the clean title where the title is still one of the
# Manager's own earlier names. A title the owner typed, or one that carries a Games Database ID, is never touched. Writes nothing.
function New-TpmLaunchBoxSyncPlan {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$LbRoot, [Parameter(Mandatory)][string]$EmulatorId,
        [Parameter(Mandatory)][string[]]$PlatformNames, [string]$TpRoot = '', [hashtable]$DatIndex = $null
    )
    $profileFiles = @{}
    foreach ($file in @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter '*.xml' -File -ErrorAction Stop)) { $profileFiles[$file.Name.ToLowerInvariant()] = $file.FullName }
    if ($profileFiles.Count -eq 0) { throw 'No game profiles were found in the TeknoParrot folder, so nothing can be compared. Nothing was changed.' }
    $plans = New-Object System.Collections.Generic.List[object]
    $removed = New-Object System.Collections.Generic.List[object]
    $moved = New-Object System.Collections.Generic.List[object]
    $renamed = New-Object System.Collections.Generic.List[object]
    $blocked = ''
    $datByCode = Get-TpmDatEntriesByCode -DatIndex $DatIndex
    foreach ($name in $PlatformNames) {
        $safe = Get-SafeLaunchBoxPlatformFileName $name
        if ($safe -cne $name -or $name -in @('.', '..')) { throw 'Platform name must be a safe, unambiguous filename.' }
        $rel = "Data\Platforms\$safe.xml"
        $path = Get-TpmLaunchBoxPath $LbRoot $rel
        $state = Get-TpmLaunchBoxFileState $path
        if (-not $state.Exists) { continue }
        $doc = Read-TpmLaunchBoxXml $path
        Assert-TpmLaunchBoxState $path $state
        $filePlan = [pscustomobject]@{ RelativePath = $rel; Before = $state; Document = $doc; OriginalXml = $doc.OuterXml; BaseChildCount = $doc.DocumentElement.ChildNodes.Count; Source = $null; SourceHash = $null; Changed = $false; Delete = $false; AfterHash = $null; FullRewrite = $true }
        $managed = @($doc.SelectNodes('/LaunchBox/Game') | Where-Object { (Get-XmlChildText $_ 'Emulator') -eq $EmulatorId })
        $goneGames = New-Object System.Collections.Generic.List[object]
        # Most games with no profile at all looks like a wrong or half-restored folder. Then nothing in this file is touched (no removal,
        # no moved path, no rename), because every comparison would be against the wrong folder.
        $missingProfile = @($managed | Where-Object { $f = [System.IO.Path]::GetFileName((Get-XmlChildText $_ 'ApplicationPath')); $f -and $f -like '*.xml' -and -not $profileFiles.ContainsKey($f.ToLowerInvariant()) })
        if ($missingProfile.Count -gt 0 -and $managed.Count -ge 6 -and ($missingProfile.Count * 2) -gt $managed.Count) {
            $blocked = 'Most of the games in LaunchBox have no profile in this TeknoParrot folder. That looks like the wrong folder, so nothing was changed.'
            [void]$plans.Add($filePlan)
            continue
        }
        foreach ($game in $managed) {
            $application = Get-XmlChildText $game 'ApplicationPath'
            $fileName = [System.IO.Path]::GetFileName($application)
            if (-not $fileName -or $fileName -notlike '*.xml') { continue }
            $title = Get-XmlChildText $game 'Title'
            $profileFile = $profileFiles[$fileName.ToLowerInvariant()]
            if (-not $profileFile) { [void]$goneGames.Add($game); continue }
            $expected = Get-RelativePath $LbRoot $profileFile
            if (-not (Test-TpmLaunchBoxSamePath -Root $LbRoot -Left $application -Right $expected)) {
                Set-XmlChildText $game 'ApplicationPath' $expected
                Set-XmlChildText $game 'DateModified' (Get-Date).ToString('o')
                [void]$moved.Add([pscustomobject]@{ Title = $title; Old = $application; New = $expected })
            }
            $databaseId = (Get-XmlChildText $game 'DatabaseID').Trim()
            if ($databaseId -and $databaseId -ne '0') { continue }
            $code = [System.IO.Path]::GetFileNameWithoutExtension($fileName)
            $subject = Get-TpmProfileMatchSubject -Code $code -ProfilePath $profileFile -TpRoot $TpRoot -HintName $title -DatIndex $DatIndex -DatByCode $datByCode
            if ($subject.NotGame) { continue }
            $currentKey = ConvertTo-TpmGamesDbKey $title
            $knownKeys = @($subject.KnownTitles | ForEach-Object { ConvertTo-TpmGamesDbKey $_ })
            if ($currentKey -and ($knownKeys -contains $currentKey) -and $title -cne $subject.DisplayTitle) {
                Set-XmlChildText $game 'Title' $subject.DisplayTitle
                Set-XmlChildText $game 'DateModified' (Get-Date).ToString('o')
                [void]$renamed.Add([pscustomobject]@{ Old = $title; New = $subject.DisplayTitle })
            }
        }
        # Versions of grouped games: a version whose profile is gone is removed; one whose folder moved gets its path fixed.
        foreach ($app in @($doc.SelectNodes('/LaunchBox/AdditionalApplication') | Where-Object { (Get-XmlChildText $_ 'EmulatorId') -eq $EmulatorId })) {
            $application = Get-XmlChildText $app 'ApplicationPath'
            $fileName = [System.IO.Path]::GetFileName($application)
            if (-not $fileName -or $fileName -notlike '*.xml') { continue }
            $profileFile = $profileFiles[$fileName.ToLowerInvariant()]
            if (-not $profileFile) {
                [void]$removed.Add([pscustomobject]@{ Title = (Get-XmlChildText $app 'Name'); Kind = 'Version' })
                [void]$doc.DocumentElement.RemoveChild($app)
                continue
            }
            $expected = Get-RelativePath $LbRoot $profileFile
            if (-not (Test-TpmLaunchBoxSamePath -Root $LbRoot -Left $application -Right $expected)) {
                Set-XmlChildText $app 'ApplicationPath' $expected
                [void]$moved.Add([pscustomobject]@{ Title = (Get-XmlChildText $app 'Name'); Old = $application; New = $expected })
            }
        }
        # A game whose profile is gone is removed, unless it still has working versions.
        foreach ($game in $goneGames) {
            $id = Get-XmlChildText $game 'ID'
            if (@($doc.SelectNodes('/LaunchBox/AdditionalApplication') | Where-Object { (Get-XmlChildText $_ 'GameID') -eq $id }).Count -gt 0) { continue }
            [void]$removed.Add([pscustomobject]@{ Title = (Get-XmlChildText $game 'Title'); Kind = 'Game' })
            [void]$doc.DocumentElement.RemoveChild($game)
        }
        $filePlan.Changed = $filePlan.OriginalXml -cne $filePlan.Document.OuterXml
        [void]$plans.Add($filePlan)
    }
    return [pscustomobject]@{ Plans = $plans.ToArray(); Removed = $removed.ToArray(); Moved = $moved.ToArray(); Renamed = $renamed.ToArray(); Blocked = $blocked }
}

# The preview lines for the Details view and the log. Pure: plan in, strings out.
function Format-TpmLaunchBoxSyncLine {
    param([Parameter(Mandatory)]$Plan)
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($item in @($Plan.Removed)) { [void]$lines.Add(('Remove {0}: its TeknoParrot profile is gone.' -f $item.Title)) }
    foreach ($item in @($Plan.Moved)) { [void]$lines.Add(('Move {0}: the profile is now at {1}.' -f $item.Title, $item.New)) }
    foreach ($item in @($Plan.Renamed)) { [void]$lines.Add(('Rename {0} to {1}.' -f $item.Old, $item.New)) }
    if ($Plan.Blocked) { [void]$lines.Add([string]$Plan.Blocked) }
    return $lines.ToArray()
}

# The one plain title line.
function Format-TpmLaunchBoxSyncTitle {
    param([Parameter(Mandatory)]$Plan, [switch]$Preview)
    $removed = @($Plan.Removed).Count; $moved = @($Plan.Moved).Count; $renamed = @($Plan.Renamed).Count
    $held = if ($Plan.Blocked) { ' ' + $Plan.Blocked } else { '' }
    if (($removed + $moved + $renamed) -eq 0) { return ('LaunchBox already matches your library. Nothing to change.' + $held) }
    $parts = '{0} removed, {1} moved, {2} renamed' -f $removed, $moved, $renamed
    if ($Preview) { return ('Preview: {0}. Nothing was changed.{1}' -f $parts, $held) }
    return ('LaunchBox now matches your library: {0}.{1}' -f $parts, $held)
}

# One run of a library change ('Group' or 'Sync'): -PlanOnly reads everything and changes nothing; otherwise the files are written
# through the LaunchBox file transaction (verified backup, read-back, rollback). Returns the same kind of result as
# Invoke-LaunchBoxDirectWrite plus ChangePlan. The caller makes sure LaunchBox and BigBox are closed before a write.
function Invoke-TpmLaunchBoxLibraryChange {
    param([Parameter(Mandatory)][ValidateSet('Group', 'Sync')][string]$Kind, [string]$UserProfilesDir, [string]$LbRoot, [string[]]$PlatformNames, [string]$BackupRoot, [string]$TpRoot = '', [hashtable]$DatIndex = $null, [switch]$PlanOnly)
    try {
        $root = Resolve-TpmLaunchBoxRoot $LbRoot
        if (-not (Test-Path -LiteralPath $root -PathType Container -ErrorAction Stop) -or -not (Test-TpmNoReparsePath $root)) { throw 'Choose a safe existing LaunchBox root.' }
        if (@($PlatformNames).Count -eq 0) { throw 'Choose at least one LaunchBox platform.' }
        $emulatorsPath = Get-TpmLaunchBoxPath $root 'Data\Emulators.xml'
        if (-not (Get-TpmLaunchBoxFileState $emulatorsPath).Exists) { throw 'LaunchBox has not made Data\Emulators.xml yet. Open LaunchBox once, close it, then try again. Nothing was changed.' }
        $emulatorNode = @((Read-TpmLaunchBoxXml $emulatorsPath).SelectNodes('/LaunchBox/Emulator') | Where-Object { (Get-XmlChildText $_ 'Title') -eq 'TeknoParrot' } | Select-Object -First 1)
        if ($emulatorNode.Count -eq 0) {
            $none = New-TpmLaunchBoxResult NO_CHANGES 'No TeknoParrot games are in LaunchBox yet. Add them first.'
            if ($PlanOnly) { $none.Reason = 'PREVIEW' }
            return $none
        }
        $emulatorId = Get-XmlChildText $emulatorNode[0] 'ID'
        if ($Kind -eq 'Group') {
            $gamesDb = Get-TpmGamesDbForLaunchBox -LaunchBoxRoot $root
            $preferred = Get-TpmPreferredRegion -ProfilePaths @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter '*.xml' -File -ErrorAction Stop | ForEach-Object { $_.FullName })
            $plan = New-TpmLaunchBoxGroupPlan -UserProfilesDir $UserProfilesDir -LbRoot $root -EmulatorId $emulatorId -PlatformNames $PlatformNames -TpRoot $TpRoot -DatIndex $DatIndex -Index $gamesDb.Index -PreferredRegion $preferred
            $lines = @(Format-TpmLaunchBoxGroupLine -Plan $plan)
        } else {
            $plan = New-TpmLaunchBoxSyncPlan -UserProfilesDir $UserProfilesDir -LbRoot $root -EmulatorId $emulatorId -PlatformNames $PlatformNames -TpRoot $TpRoot -DatIndex $DatIndex
            $lines = @(Format-TpmLaunchBoxSyncLine -Plan $plan)
        }
        foreach ($line in $lines) { Write-Log ('LaunchBox {0}: {1}' -f $Kind.ToLowerInvariant(), $line) }
        $changedPlans = @($plan.Plans | Where-Object { $_.Changed })
        if ($PlanOnly) {
            $preview = New-TpmLaunchBoxResult NO_CHANGES ('Preview only, nothing was written. A write would change {0} file(s).' -f $changedPlans.Count)
            $preview.Reason = 'PREVIEW'
            $preview | Add-Member -NotePropertyName WouldChangeFiles -NotePropertyValue $changedPlans.Count -Force
            $preview | Add-Member -NotePropertyName ChangePlan -NotePropertyValue $plan -Force
            return $preview
        }
        $result = Invoke-TpmLaunchBoxFileTransaction -lbRoot $root -Plans $plan.Plans -BackupRoot $BackupRoot
        $result | Add-Member -NotePropertyName ChangePlan -NotePropertyValue $plan -Force
        return $result
    } catch {
        $result = New-TpmLaunchBoxResult FAILED 'The LaunchBox change was refused before library writes.'
        $result.Errors = @([string]$_.Exception.Message)
        return $result
    }
}
# END MODULE-READY SECTION: LaunchBox game versions and keeping in step

# Screen layer for the section above (not part of the module): preview, ask, then write. Kind is 'Group' or 'Sync'.
function Invoke-TpmLaunchBoxChangeStep {
    param([Parameter(Mandatory)][ValidateSet('Group', 'Sync')][string]$Kind, [string]$UserProfilesDir, [string]$LbRoot, [string]$TpRoot = '', [hashtable]$DatIndex = $null)
    $root = $LbRoot
    if (-not $root) { $root = Read-HostSafe '  LaunchBox install folder (Enter to go back)' }
    if (-not $root) { return }
    $platformChoice = Read-TpmChoice -Prompt '  Platform: 1 Arcade, 2 TeknoParrot, 3 Both, B back' -Choices @('1', '2', '3', 'B') -Default '2'
    if ($platformChoice -eq 'B') { return }
    $platforms = switch ($platformChoice) { '1' { @('Arcade') } '2' { @('TeknoParrot') } '3' { @('Arcade', 'TeknoParrot') } }
    $intro = if ($Kind -eq 'Group') { 'Regions and versions of the same game become one game with a version picker. The default version follows the region you chose in Region setup.' } else { 'Games you removed from TeknoParrot are removed from LaunchBox, moved games get their new location, and old Manager names are made clean. A game whose game file is only missing (for example an unplugged drive) is never removed.' }
    Write-TpmText -Text ('First TeknoParrot Manager only reads your LaunchBox files. ' + $intro) -Color DarkCyan
    $plan = Invoke-TpmLaunchBoxLibraryChange -Kind $Kind -UserProfilesDir $UserProfilesDir -LbRoot $root -PlatformNames $platforms -TpRoot $TpRoot -DatIndex $DatIndex -PlanOnly
    $show = {
        param($result, [bool]$preview)
        if ($result.PSObject.Properties['ChangePlan']) {
            $title = if ($Kind -eq 'Group') { Format-TpmLaunchBoxGroupTitle -Plan $result.ChangePlan -Preview:$preview } else { Format-TpmLaunchBoxSyncTitle -Plan $result.ChangePlan -Preview:$preview }
            $lines = if ($Kind -eq 'Group') { @(Format-TpmLaunchBoxGroupLine -Plan $result.ChangePlan) } else { @(Format-TpmLaunchBoxSyncLine -Plan $result.ChangePlan) }
            $result | Add-Member -NotePropertyName PlainTitle -NotePropertyValue $title -Force
            $result | Add-Member -NotePropertyName EnrichLines -NotePropertyValue $lines -Force
        }
        Write-TpmLaunchBoxResult -Result $result
    }
    & $show $plan $true
    if ($plan.Reason -ne 'PREVIEW' -or [int]$plan.WouldChangeFiles -eq 0) { return }
    Write-TpmLaunchBoxWriteNotice
    $notice = Get-TpmLaunchBoxWriteNoticeBlocks
    if ((Read-TpmYesNo -Prompt 'Make exactly these changes after a verified backup? (Y/N, D = about the risks)' -Default 'N' -DetailsAction { Show-TpmDetailBlocks -Blocks $notice }) -ne 'Y') {
        Write-Host '  LaunchBox write canceled; nothing was changed.' -ForegroundColor DarkGray
        return
    }
    if (-not (Wait-TpmForProcessClose -ProcessNames @('LaunchBox', 'BigBox') -FriendlyName 'LaunchBox or BigBox')) {
        Write-Host '  LaunchBox or BigBox is still open, so nothing was changed.' -ForegroundColor DarkGray
        return
    }
    $written = Invoke-TpmLaunchBoxLibraryChange -Kind $Kind -UserProfilesDir $UserProfilesDir -LbRoot $root -PlatformNames $platforms -TpRoot $TpRoot -DatIndex $DatIndex
    & $show $written $false
    if ($written.BackupPath) { Write-TpmText -Text 'To undo this, open Restore in the main menu and choose the LaunchBox backup.' -Color DarkCyan }
}

# Screen layer for the section above (not part of the module): asks, shows, calls the functions above.
# The screens print the text the Format functions return and hand every decision to the data layer through parameters.
function Write-TpmLaunchBoxEnrichResult {
    param([Parameter(Mandatory)]$Result, [switch]$Preview)
    if ($Result.PSObject.Properties['EnrichPlan']) {
        $Result | Add-Member -NotePropertyName PlainTitle -NotePropertyValue (Format-TpmLaunchBoxEnrichTitle -Plan $Result.EnrichPlan -Preview:$Preview) -Force
        $Result | Add-Member -NotePropertyName EnrichLines -NotePropertyValue @(Format-TpmLaunchBoxEnrichLine -Plan $Result.EnrichPlan) -Force
    }
    Write-TpmLaunchBoxResult -Result $Result
}

# The menu step: preview, ask, then write.
function Invoke-TpmLaunchBoxEnrichStep {
    param([string]$UserProfilesDir, [string]$LbRoot, [string]$TpRoot = '', [hashtable]$DatIndex = $null)
    $root = $LbRoot
    if (-not $root) { $root = Read-HostSafe '  LaunchBox install folder (Enter to go back)' }
    if (-not $root) { return }
    $platformChoice = Read-TpmChoice -Prompt '  Platform: 1 Arcade, 2 TeknoParrot, 3 Both, B back' -Choices @('1', '2', '3', 'B') -Default '2'
    if ($platformChoice -eq 'B') { return }
    $platforms = switch ($platformChoice) { '1' { @('Arcade') } '2' { @('TeknoParrot') } '3' { @('Arcade', 'TeknoParrot') } }
    Write-TpmText -Text 'First TeknoParrot Manager only reads your LaunchBox files. Empty year and developer boxes get filled in from the LaunchBox game list, the Eggman list and TeknoParrot. Boxes you filled in are never changed. It keeps playlists by hardware, light gun and driving games, and marks games that cannot start yet with a Needs setup note and playlist.' -Color DarkCyan
    $plan = Invoke-TpmLaunchBoxEnrich -UserProfilesDir $UserProfilesDir -LbRoot $root -PlatformNames $platforms -TpRoot $TpRoot -DatIndex $DatIndex -PlanOnly
    Write-TpmLaunchBoxEnrichResult -Result $plan -Preview
    if ($plan.Reason -ne 'PREVIEW' -or [int]$plan.WouldChangeFiles -eq 0) { return }
    Write-TpmLaunchBoxWriteNotice
    $notice = Get-TpmLaunchBoxWriteNoticeBlocks
    if ((Read-TpmYesNo -Prompt 'Make exactly these changes after a verified backup? (Y/N, D = about the risks)' -Default 'N' -DetailsAction { Show-TpmDetailBlocks -Blocks $notice }) -ne 'Y') {
        Write-Host '  LaunchBox write canceled; nothing was changed.' -ForegroundColor DarkGray
        return
    }
    if (-not (Wait-TpmForProcessClose -ProcessNames @('LaunchBox', 'BigBox') -FriendlyName 'LaunchBox or BigBox')) {
        Write-Host '  LaunchBox or BigBox is still open, so nothing was changed.' -ForegroundColor DarkGray
        return
    }
    $written = Invoke-TpmLaunchBoxEnrich -UserProfilesDir $UserProfilesDir -LbRoot $root -PlatformNames $platforms -TpRoot $TpRoot -DatIndex $DatIndex
    Write-TpmLaunchBoxEnrichResult -Result $written
    if ($written.BackupPath) { Write-TpmText -Text 'To undo, open Restore in the main menu and choose the LaunchBox backup.' -Color DarkCyan }
}

# Screen for the Games Database links section: preview, ask about each close match, ask, then write.
function Write-TpmLaunchBoxIdLinkResult {
    param([Parameter(Mandatory)]$Result, [switch]$Preview)
    if ($Result.PSObject.Properties['LinkPlan']) {
        $Result | Add-Member -NotePropertyName PlainTitle -NotePropertyValue (Format-TpmLaunchBoxIdLinkTitle -Plan $Result.LinkPlan -Preview:$Preview) -Force
        $Result | Add-Member -NotePropertyName EnrichLines -NotePropertyValue @(Format-TpmLaunchBoxIdLinkLine -Plan $Result.LinkPlan) -Force
    }
    Write-TpmLaunchBoxResult -Result $Result
}

function Invoke-TpmLaunchBoxIdLinkStep {
    param([string]$LbRoot, [string]$TpRoot, [hashtable]$DatIndex = $null)
    $root = $LbRoot
    if (-not $root) { $root = Read-HostSafe '  LaunchBox install folder (Enter to go back)' }
    if (-not $root) { return }
    Write-TpmText -Text 'First TeknoParrot Manager only reads your LaunchBox files. Games with no Games Database ID are matched to LaunchBox''s own game list, so LaunchBox finds the right art and details. Names you typed yourself are kept.' -Color DarkCyan
    $plan = Invoke-TpmLaunchBoxIdLink -LbRoot $root -TpRoot $TpRoot -DatIndex $DatIndex -PlanOnly
    Write-TpmLaunchBoxIdLinkResult -Result $plan -Preview
    if (-not $plan.PSObject.Properties['LinkPlan']) { return }
    $choices = @{}
    $unsure = @($plan.LinkPlan.Items | Where-Object { $_.Status -eq 'Ambiguous' -and @($_.Options).Count -gt 0 })
    if ($unsure.Count -gt 0) {
        Write-TpmText -Text ('{0} could not be matched for sure. You decide each one; Enter skips it.' -f (Format-TpmGameCount -Count $unsure.Count)) -Color Yellow -BlankBefore
        foreach ($item in $unsure) {
            Write-TpmText -Text ('{0}: {1}' -f $item.Title, $item.Reason) -Color White
            $options = @($item.Options)
            for ($i = 0; $i -lt $options.Count; $i++) { Write-TpmText -Text ('[{0}] {1} (ID {2})' -f ($i + 1), $options[$i].Name, $options[$i].Id) -Color White }
            $pick = Read-TpmChoice -Prompt '  Your choice' -Choices (@('S') + @(1..$options.Count | ForEach-Object { [string]$_ })) -Default 'S'
            if ($pick -ne 'S') { $choices[[string]$item.GameId] = [string]$options[[int]$pick - 1].Id }
        }
        $plan = Invoke-TpmLaunchBoxIdLink -LbRoot $root -TpRoot $TpRoot -DatIndex $DatIndex -Choices $choices -PlanOnly
        Write-TpmLaunchBoxIdLinkResult -Result $plan -Preview
    }
    if ($plan.Reason -ne 'PREVIEW' -or [int]$plan.WouldChangeFiles -eq 0) { return }
    Write-TpmLaunchBoxWriteNotice
    $notice = Get-TpmLaunchBoxWriteNoticeBlocks
    if ((Read-TpmYesNo -Prompt 'Make exactly these changes after a verified backup? (Y/N, D = about the risks)' -Default 'N' -DetailsAction { Show-TpmDetailBlocks -Blocks $notice }) -ne 'Y') {
        Write-Host '  LaunchBox write canceled; nothing was changed.' -ForegroundColor DarkGray
        return
    }
    if (-not (Wait-TpmForProcessClose -ProcessNames @('LaunchBox', 'BigBox') -FriendlyName 'LaunchBox or BigBox')) {
        Write-Host '  LaunchBox or BigBox is still open, so nothing was changed.' -ForegroundColor DarkGray
        return
    }
    $written = Invoke-TpmLaunchBoxIdLink -LbRoot $root -TpRoot $TpRoot -DatIndex $DatIndex -Choices $choices
    Write-TpmLaunchBoxIdLinkResult -Result $written
    if ($written.BackupPath) { Write-TpmText -Text 'To undo, open Restore in the main menu and choose the LaunchBox backup.' -Color DarkCyan }
}

function Get-TpmLaunchBoxSnapshot {
    param([string]$SnapshotPath)
    if (-not (Test-Path -LiteralPath $SnapshotPath -PathType Container -ErrorAction Stop) -or -not (Test-TpmNoReparsePath $SnapshotPath)) { throw 'Unsafe or missing LaunchBox snapshot.' }
    $files = @()
    $pending = New-Object System.Collections.Stack
    $pending.Push($SnapshotPath)
    while ($pending.Count) {
        $directory = [string]$pending.Pop()
        foreach ($entry in @(Get-ChildItem -LiteralPath $directory -Force -ErrorAction Stop)) {
            if (-not (Test-TpmNoReparsePath $entry.FullName)) { throw 'Reparse or inaccessible backup entry refused.' }
            if ($entry.PSIsContainer) { $pending.Push($entry.FullName) } else { $files += $entry.FullName }
        }
    }
    $manifestPath = Join-Path $SnapshotPath 'manifest.json'
    $legacy = $manifestPath -notin $files
    $records = @()
    $snapshotRoot = $null
    $snapshotOperation = 'legacy'
    if (-not $legacy) {
        $manifest = [System.IO.File]::ReadAllText($manifestPath) | ConvertFrom-Json -ErrorAction Stop
        if ($manifest.Schema -ne 2 -or @($manifest.Items).Count -eq 0 -or $manifest.Operation -notin @('write','restore-safety') -or [string]::IsNullOrWhiteSpace([string]$manifest.LaunchBoxRoot)) { throw 'Invalid LaunchBox snapshot manifest.' }
        $records = @($manifest.Items)
        $snapshotRoot = [string]$manifest.LaunchBoxRoot
        $snapshotOperation = [string]$manifest.Operation
    } else {
        foreach ($file in $files) {
            $rel = Get-RelativePath $SnapshotPath $file
            $state = Get-TpmLaunchBoxFileState (Get-TpmLaunchBoxPath $SnapshotPath $rel)
            $records += [pscustomobject]@{ RelativePath=$rel; Exists=$true; Hash=$state.Hash; Length=$state.Length; CreatedHash=$null }
        }
    }
    if ($records.Count -eq 0) { throw 'Empty LaunchBox snapshot refused.' }
    $seen = @{}
    $expectedFiles = @()
    foreach ($record in $records) {
        $src = Get-TpmLaunchBoxPath $SnapshotPath $record.RelativePath
        if ($seen.ContainsKey($record.RelativePath) -or $record.Exists -isnot [bool]) { throw 'Invalid or duplicate snapshot member.' }
        $seen[$record.RelativePath] = $true
        if ($record.Exists) {
            if ($record.Hash -notmatch '^[A-Fa-f0-9]{64}$') { throw 'Invalid snapshot hash.' }
            Assert-TpmLaunchBoxState $src $record
            [void](Read-TpmLaunchBoxXml $src)
            $expectedFiles += $src
        } elseif (Test-Path -LiteralPath $src -ErrorAction Stop) { throw 'Snapshot presence conflicts with its manifest.' }
    }
    if (-not $legacy) { $expectedFiles += $manifestPath }
    if ($files.Count -ne $expectedFiles.Count -or @($files | Where-Object { $_ -notin $expectedFiles }).Count) { throw 'Unexpected or incomplete snapshot inventory.' }
    return [pscustomobject]@{ Items=@($records); Legacy=$legacy; Root=$snapshotRoot; Operation=$snapshotOperation }
}

# One-line description of a snapshot for the restore list: operation kind and the library it was taken from.
function Get-TpmLaunchBoxSnapshotLabel {
    param([string]$SnapshotPath)
    $manifestPath = Join-Path $SnapshotPath 'manifest.json'
    try {
        if (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf -ErrorAction Stop)) { return '[legacy snapshot; source library unknown]' }
        $manifest = [System.IO.File]::ReadAllText($manifestPath) | ConvertFrom-Json -ErrorAction Stop
        if ($manifest.Schema -ne 2 -or -not $manifest.LaunchBoxRoot -or $manifest.Operation -notin @('write','restore-safety')) { return '[unreadable manifest; restore will be refused]' }
        $kind = if ($manifest.Operation -eq 'restore-safety') { 'safety snapshot taken before a restore' } else { 'taken before a write' }
        return ('[{0}] library: {1}' -f $kind,$manifest.LaunchBoxRoot)
    } catch { return '[unreadable manifest; restore will be refused]' }
}

function Invoke-RestoreLaunchBoxBackup {
    param([string]$lbRoot, [string]$BackupRoot)
    try {
        $lbRoot = Resolve-TpmLaunchBoxRoot $lbRoot
        if (-not (Test-Path -LiteralPath $lbRoot -PathType Container -ErrorAction Stop) -or -not (Test-TpmNoReparsePath $lbRoot)) { throw 'Choose a safe existing LaunchBox root.' }
        $location = Resolve-TpmLaunchBoxBackupLocation -BackupRoot $BackupRoot -LaunchBoxRoot $lbRoot
        $base = $location.Path
        $listRoots = @($base)
        if ($location.UsesFallback -and (Test-Path -LiteralPath $location.OwnedPath -ErrorAction Stop)) {
            # Snapshots already kept in TeknoParrot's own folder stay listed; new safety snapshots go to $base.
            if (-not (Test-Path -LiteralPath $location.OwnedPath -PathType Container -ErrorAction Stop) -or -not (Test-TpmNoReparsePath -Path $location.OwnedPath)) { throw 'The LaunchBox backup folder under TeknoParrot could not be safely verified.' }
            $listRoots += $location.OwnedPath
        }
        $found = @(foreach ($listRoot in $listRoots) {
            if (Test-Path -LiteralPath $listRoot -ErrorAction Stop) { Get-ChildItem -LiteralPath $listRoot -Directory -Force -ErrorAction Stop | Where-Object { $_.Name -ne '.tpm-incomplete' } }
        })
        $backups = @($found | Sort-Object Name -Descending)
        if ($backups.Count -eq 0) { return (New-TpmLaunchBoxResult NO_CHANGES 'No LaunchBox backup is available; no library writes were attempted.') }
        if ($location.UsesFallback) {
            Write-Host ('  LaunchBox backups for this library are kept outside it, in: ' + $base) -ForegroundColor DarkCyan
            if ($listRoots.Count -gt 1) { Write-Host ('  Older snapshots are also listed from: ' + $location.OwnedPath) -ForegroundColor DarkCyan }
        }
        $menuStarted = Get-Date
        $menuCurrent = 0
        $menuOutcome = 'Error'
        try {
            for ($i=0; $i -lt $backups.Count; $i++) {
                $menuCurrent = $i + 1
                Write-TpmCompactExtractionProgress -Phase Checking -Label 'LaunchBox backup menu indexing' -Current $menuCurrent -Total $backups.Count -StartedAt $menuStarted
                Write-Host ("  {0}) {1}  {2}" -f ($i+1),$backups[$i].Name,(Get-TpmLaunchBoxSnapshotLabel $backups[$i].FullName))
            }
            $menuOutcome = 'Final'
        } finally {
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'LaunchBox backup menu indexing' -Current $menuCurrent -Total $backups.Count -StartedAt $menuStarted -Complete -Outcome $menuOutcome
        }
        $choice = Read-TpmChoice -Prompt 'Choose a LaunchBox backup, or press Enter (or B) to cancel' -Choices (@('B') + @(1..$backups.Count | ForEach-Object { [string]$_ })) -Default 'B'
        if ($choice -eq 'B') { $cancel = New-TpmLaunchBoxResult NO_CHANGES 'LaunchBox restore canceled before library writes.'; $cancel.Cancelled=$true; return $cancel }
        $selected = $backups[[int]$choice-1].FullName
        $snapshot = Get-TpmLaunchBoxSnapshot $selected
        $snapshotRootText = if ($snapshot.Root) { $snapshot.Root } else { 'unknown (legacy snapshot)' }
        Write-Host ('  Target LaunchBox folder : ' + $lbRoot) -ForegroundColor Cyan
        Write-Host ('  Snapshot taken from     : ' + $snapshotRootText + ' [' + $snapshot.Operation + ']') -ForegroundColor Cyan
        foreach ($record in $snapshot.Items) {
            $memberAction = if ($record.Exists) { 'restore the snapshot copy over the current file' } else { 'remove the file only if TeknoParrot Manager made it and it has not changed (asked separately); otherwise it is kept and the result says so' }
            Write-Host ('    {0}: {1}' -f $record.RelativePath,$memberAction)
        }
        Write-Host '  Close LaunchBox and BigBox and keep them closed. TeknoParrot Manager never force-closes them.' -ForegroundColor Yellow
        Write-Host '  If either app opens again while this runs, start the restore again.' -ForegroundColor Yellow; Write-Log 'LaunchBox restore: either app can reopen after the process check; multi-file recovery is not atomic; a changed or declined created file makes the result PARTIAL.'
        Write-Host '  Any LaunchBox changes made to the files above since this snapshot will be replaced; a verified snapshot of their current state is taken first.' -ForegroundColor Yellow
        if ($snapshot.Legacy) { Write-Host '  Old backup: it does not say which library it came from. Only the files listed above are restored, and nothing else is deleted.' -ForegroundColor Yellow; Write-Log 'LaunchBox restore: legacy snapshot; only inventoried files can be restored; original completeness unknown; absent members never imply deletion.' }
        $restoreIntoOther = [bool]($snapshot.Root -and $snapshot.Root -ine $lbRoot)
        if ($restoreIntoOther) { Write-Host '  WARNING: this snapshot was taken from a different LaunchBox folder than the restore target.' -ForegroundColor Red }
        # One question only: when the snapshot came from another folder, the question says so; otherwise the normal one.
        $restorePrompt = if ($restoreIntoOther) { 'This snapshot belongs to a different LaunchBox folder. Restore it into the target folder anyway, after a verified backup of its current state? (Y/N)' } else { 'Restore these files into {0} after a verified backup of their current state? (Y/N)' -f $lbRoot }
        if ((Read-TpmYesNo -Prompt $restorePrompt -Default 'N') -ne 'Y') {
            $cancel = New-TpmLaunchBoxResult NO_CHANGES 'LaunchBox restore canceled before library writes.'; $cancel.Cancelled=$true; return $cancel
        }
        if (-not (Wait-TpmForProcessClose -ProcessNames @('LaunchBox','BigBox') -FriendlyName 'LaunchBox or BigBox')) {
            $cancel = New-TpmLaunchBoxResult NO_CHANGES 'LaunchBox or BigBox is still open and the restore was canceled. No library writes were attempted.'
            $cancel.Cancelled = $true; $cancel.Reason = 'APPLICATION_RUNNING'; return $cancel
        }
        $plans = @()
        $kept = @()
        foreach ($record in $snapshot.Items) {
            $dst = Get-TpmLaunchBoxPath $lbRoot $record.RelativePath
            $before = Get-TpmLaunchBoxFileState $dst
            $delete = -not $record.Exists -and $before.Exists
            if ($delete) {
                # A file TPM created is removed only while its bytes still match what TPM wrote and the user agrees. Otherwise it stays untouched and is reported; the other members are still restored.
                if ($record.CreatedHash -notmatch '^[A-Fa-f0-9]{64}$' -or $before.Hash -ne $record.CreatedHash) {
                    $kept += [pscustomobject]@{ Path=$record.RelativePath; Reason='it changed after TPM created it (LaunchBox or the user modified it); TPM never deletes a changed file' }
                    continue
                }
                if ((Read-TpmYesNo -Prompt ("Remove the file {0}? TeknoParrot Manager added it earlier and you have not changed it. (Y/N)" -f $record.RelativePath) -Default 'N') -ne 'Y') {
                    $kept += [pscustomobject]@{ Path=$record.RelativePath; Reason='its removal was declined' }
                    continue
                }
            }
            $source = if ($record.Exists) { Get-TpmLaunchBoxPath $selected $record.RelativePath } else { $null }
            $plans += [pscustomobject]@{ RelativePath=$record.RelativePath; Before=$before; Document=$null; Source=$source; SourceHash=$record.Hash; Changed=($before.Exists -ne $record.Exists -or ($record.Exists -and $before.Hash -ne $record.Hash)); Delete=$delete; AfterHash=$null; BaseChildCount=0 }
        }
        # Kept files are not plan members: they are neither backed up nor touched by this restore.
        $result = Invoke-TpmLaunchBoxFileTransaction -lbRoot $lbRoot -Plans $plans -BackupRoot $base -Operation 'restore-safety'
        $result.LegacySnapshot = $snapshot.Legacy
        if ($result.Outcome -eq 'SAVED') { $result.Summary = if ($snapshot.Legacy) { 'Every inventoried legacy backup file was restored and read back; original backup completeness remains unknown.' } else { 'LaunchBox snapshot targets were restored and every target was read back and verified.' } }
        if ($kept.Count -and $result.Outcome -in @('SAVED','NO_CHANGES','PARTIAL')) {
            $result.KeptFiles = @($kept)
            foreach ($file in $kept) { if ($file.Path -notin $result.UnrecoveredPaths) { $result.UnrecoveredPaths += $file.Path } }
            if ($result.Outcome -eq 'SAVED') {
                $result.Summary = 'LaunchBox restore is PARTIAL: {0} snapshot member(s) were restored and read back, but {1} TPM-created file(s) were left in place and need review.' -f @($result.ChangedPaths).Count,$kept.Count
            } elseif ($result.Outcome -eq 'NO_CHANGES') {
                $result.Summary = 'LaunchBox restore is PARTIAL: no other snapshot member needed restoring, and {0} TPM-created file(s) were left in place and need review.' -f $kept.Count
            }
            if ($result.Outcome -ne 'PARTIAL') { $result.Outcome = 'PARTIAL'; $result.Succeeded = $false; $result.NoOp = $false }
        }
        return $result
    } catch {
        $result = New-TpmLaunchBoxResult FAILED 'LaunchBox restore was refused before library writes.'
        $result.Errors = @([string]$_.Exception.Message)
        return $result
    }
}

# Number of game entries a LaunchBox result added (or would add, for a preview).
function Get-TpmLaunchBoxAddedCount {
    param([Parameter(Mandatory)]$Result)
    $added = 0
    if ($Result.Results -is [hashtable]) { foreach ($countValue in @($Result.Results.Values)) { $added += [int]$countValue } }
    return $added
}

# The unrecovered paths that are not already reported as a kept file.
function Get-TpmLaunchBoxUnverifiedPaths {
    param([Parameter(Mandatory)]$Result)
    $keptPaths = @($Result.KeptFiles | ForEach-Object { $_.Path })
    return ,@(@($Result.UnrecoveredPaths) | Where-Object { $_ -and $_ -notin $keptPaths })
}

# One plain line for a LaunchBox result. A preview and a save have everyday wording; any other
# result (restore, failure) shows its own summary.
function Get-TpmLaunchBoxPlainTitle {
    param([Parameter(Mandatory)]$Result)
    if ($Result.PSObject.Properties['PlainTitle'] -and $Result.PlainTitle -and [string]$Result.Outcome -in @('SAVED','NO_CHANGES')) { return [string]$Result.PlainTitle }
    $added = Get-TpmLaunchBoxAddedCount -Result $Result
    if ([string]$Result.Reason -eq 'PREVIEW') {
        if ($Result.PSObject.Properties['WouldChangeFiles'] -and [int]$Result.WouldChangeFiles -eq 0) { return 'Preview: LaunchBox already has all your games. Nothing would change.' }
        if ($added -eq 0) { return 'Preview: LaunchBox files would be updated. Nothing was changed.' }
        return ('Preview: LaunchBox would get {0}. Nothing was changed.' -f (Format-TpmGameCount -Count $added))
    }
    if ([string]$Result.Outcome -eq 'SAVED' -and $added -gt 0) { return ('Added {0} to LaunchBox.' -f (Format-TpmGameCount -Count $added)) }
    return [string]$Result.Summary
}

# Details view of a LaunchBox result: every fact the old screen printed, as labeled lines in one block.
function Get-TpmLaunchBoxDetailBlocks {
    param([Parameter(Mandatory)]$Result)
    $lines = New-Object System.Collections.Generic.List[string]
    if ($Result.Summary) { [void]$lines.Add(('What happened: {0}' -f $Result.Summary)) }
    if ($Result.Results -is [hashtable]) {
        $addedWord = if ([string]$Result.Outcome -eq 'SAVED') { 'Added to' } else { 'Would add to' }
        foreach ($platformName in @($Result.Results.Keys)) { [void]$lines.Add(('{0} {1}: {2}' -f $addedWord, $platformName, (Format-TpmGameCount -Count ([int]$Result.Results[$platformName])))) }
    }
    if ($Result.PSObject.Properties['SkippedMissingGame'] -and [int]$Result.SkippedMissingGame -gt 0) { [void]$lines.Add(('Not added: {0} (game file not found, not an error)' -f (Format-TpmGameCount -Count ([int]$Result.SkippedMissingGame)))) }
    if ($Result.PSObject.Properties['SkippedUnreadable']) { foreach ($unreadableName in @($Result.SkippedUnreadable)) { [void]$lines.Add(('Not added: the profile file {0} could not be read' -f $unreadableName)) } }
    if ($Result.PSObject.Properties['SkippedBadPath']) { foreach ($badPathName in @($Result.SkippedBadPath)) { [void]$lines.Add(('Not added: the saved game path in {0} is not a valid path' -f $badPathName)) } }
    if ($Result.PSObject.Properties['EnrichLines']) { foreach ($enrichLine in @($Result.EnrichLines)) { [void]$lines.Add([string]$enrichLine) } }
    if ($Result.BackupPath) { [void]$lines.Add(('Verified safety backup: {0}' -f $Result.BackupPath)) }
    if ($Result.PSObject.Properties['BackupLocationNote'] -and $Result.BackupLocationNote) { [void]$lines.Add(('Backup folder: {0}' -f $Result.BackupLocationNote)) }
    foreach ($errorText in @($Result.Errors)) { [void]$lines.Add(('Reason: {0}' -f $errorText)) }
    $unverified = Get-TpmLaunchBoxUnverifiedPaths -Result $Result
    if ($unverified.Count -gt 0) { [void]$lines.Add(('Needs review: {0} (not verified back to its pre-write state)' -f ($unverified -join ', '))) }
    foreach ($file in @($Result.KeptFiles)) { [void]$lines.Add(('Needs review: {0} was left in place because {1}. Compare it with the restored snapshot and remove or keep it yourself.' -f $file.Path, $file.Reason)) }
    if ($Result.PSObject.Properties['ChangedByOther']) {
        foreach ($change in @($Result.ChangedByOther)) {
            [void]$lines.Add(('Changed by another program: {0}' -f $change.Path))
            [void]$lines.Add(('Newer copy kept at: {0}' -f $change.SavedCopy))
            [void]$lines.Add($(if ($change.PutBack) { 'The newer version was put back as the current file.' } else { 'The newer version could not be put back, so it is only in the kept copy. Compare it with the current file.' }))
        }
    }
    $blocks = New-Object System.Collections.Generic.List[object]
    if ($lines.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'LaunchBox details'; Lines = $lines.ToArray() }) }
    $nameBlock = Get-TpmLaunchBoxTitleDetailBlock -Result $Result
    if ($nameBlock) { [void]$blocks.Add($nameBlock) }
    return ,@($blocks.ToArray())
}

# Details of the game-name step: every old name, new name and Games Database ID, the games that need a choice,
# and why the game list was not used when it was not. $null when the step had nothing to say.
function Get-TpmLaunchBoxTitleDetailBlock {
    param([Parameter(Mandatory)]$Result)
    if (-not $Result.PSObject.Properties['GamesDbState']) { return $null }
    $lines = New-Object System.Collections.Generic.List[string]
    if ([string]$Result.GamesDbState -notin @('Used', 'Off')) { [void]$lines.Add(('Games Database not used: {0}' -f $Result.GamesDbError)) }
    foreach ($change in @($Result.TitleChanges)) {
        $where = if ($change.Kind -eq 'Existing') { ' (game already in LaunchBox)' } else { '' }
        $how = if ($change.PSObject.Properties['Choice'] -and $change.Choice) { ' (your choice)' } else { '' }
        $idText = if ($change.Id) { ', ID ' + $change.Id } else { '' }
        if ($change.PSObject.Properties['Filled'] -and $change.Filled) { $how += ' (fills in ' + $change.Filled + ')' }
        if ($change.Old -ceq $change.New) { [void]$lines.Add(('Same name {0}{1}{2}{3}' -f $change.New, $idText, $where, $how)) }
        else { [void]$lines.Add(('{0}  ->  {1}{2}{3}{4}' -f $change.Old, $change.New, $idText, $where, $how)) }
    }
    foreach ($item in @($Result.TitleReview)) {
        $options = @($item.Options | ForEach-Object { '{0} (ID {1})' -f $_.Name, $_.Id }) -join ' / '
        switch ([string]$item.Status) {
            'Ambiguous' { [void]$lines.Add(('Needs your choice: {0}. {1} Possible games: {2}.' -f $item.Title, $item.Reason, $options)) }
            default { [void]$lines.Add(('No match found: {0}. {1} It keeps its clean name.' -f $item.Title, $item.Reason)) }
        }
    }
    if ($lines.Count -eq 0) { return $null }
    return @{ Heading = 'Game names'; Lines = $lines.ToArray() }
}

# Plain lines for the result screen: what matched, what was left alone, and how to undo.
function Get-TpmLaunchBoxTitleSummary {
    param([Parameter(Mandatory)]$Result)
    $summary = @{ Done = @(); NotChanged = '' }
    if (-not $Result.PSObject.Properties['GamesDbState']) { return $summary }
    $preview = ([string]$Result.Reason -eq 'PREVIEW')
    $official = @(@($Result.TitleChanges) | Where-Object { $_.Id }).Count
    $clean = @(@($Result.TitleChanges) | Where-Object { -not $_.Id -and $_.Old -cne $_.New }).Count
    $filled = @(@($Result.TitleChanges) | Where-Object { $_.PSObject.Properties['Filled'] -and $_.Filled }).Count
    $review = @($Result.TitleReview).Count
    if ($official -gt 0) {
        $line = if ($preview) { '{0} would get the official name and Games Database ID, so LaunchBox can find info and artwork.' } else { '{0} got the official name and Games Database ID, so LaunchBox can find info and artwork.' }
        $summary.Done += ($line -f (Format-TpmGameCount -Count $official))
    }
    if ($clean -gt 0) {
        $line = if ($preview) { '{0} would get a clean game name instead of a file name.' } else { '{0} got a clean game name instead of a file name.' }
        $summary.Done += ($line -f (Format-TpmGameCount -Count $clean))
    }
    if ($filled -gt 0) {
        $line = if ($preview) { '{0} would get the release year and developer filled in.' } else { '{0} got the release year and developer filled in.' }
        $summary.Done += ($line -f (Format-TpmGameCount -Count $filled))
    }
    if (@($summary.Done).Count -gt 0 -and -not $preview -and [string]$Result.Outcome -eq 'SAVED') { $summary.Done += 'To undo, use Restore backup in the main menu.' }
    switch ([string]$Result.GamesDbState) {
        'Missing' { $summary.NotChanged = 'The LaunchBox game list was not found, so no Games Database ID was added.' }
        'Failed' { $summary.NotChanged = 'The LaunchBox game list could not be read, so no Games Database ID was added. Press D to see why.' }
        default { if ($review -gt 0) { $summary.NotChanged = ('{0} got no Games Database ID: no sure match. Press D to see the closest names.' -f (Format-TpmGameCount -Count $review)) } }
    }
    return $summary
}

# The LaunchBox result screen: a plain title, a few short lines, the folder NAME of a saved copy (never its path)
# and D for the details. The full outcome line is always logged.
function Write-TpmLaunchBoxResult {
    param($Result, [switch]$Unattended)
    Write-Log ('LaunchBox outcome={0}; attempted={1}; changed={2}; unrecovered={3}; backup={4}; errors={5}' -f $Result.Outcome,($Result.AttemptedPaths -join ','),($Result.ChangedPaths -join ','),($Result.UnrecoveredPaths -join ','),$Result.BackupPath,($Result.Errors -join '; '))
    $status = switch ([string]$Result.Outcome) { 'FAILED' { 'Problem' } 'PARTIAL' { 'Attention' } default { 'Ok' } }
    $done = New-Object System.Collections.Generic.List[string]
    if ($Result.BackupPath) { [void]$done.Add(('A saved copy of your LaunchBox files was made first: {0}' -f [System.IO.Path]::GetFileName(([string]$Result.BackupPath).TrimEnd('\', '/')))) }
    $hasBackupFolder = $Result.PSObject.Properties['BackupLocationPath'] -and $Result.BackupLocationPath
    if ($hasBackupFolder) { [void]$done.Add(('Saved copies are kept outside LaunchBox, in the folder {0}.' -f [System.IO.Path]::GetFileName(([string]$Result.BackupLocationPath).TrimEnd('\', '/')))) }
    $notChanged = ''
    $skipped = if ($Result.PSObject.Properties['SkippedMissingGame']) { [int]$Result.SkippedMissingGame } else { 0 }
    if ($skipped -gt 0) { $notChanged = ('{0} {1} not added because the game file was not found. This is not an error.' -f (Format-TpmGameCount -Count $skipped), $(if ($skipped -eq 1) { 'was' } else { 'were' })) }
    if ($Result.PSObject.Properties['SkippedUnreadable'] -and @($Result.SkippedUnreadable).Count -gt 0) { $notChanged = ($notChanged + ' These profile files could not be read, so their games were left out: ' + (@($Result.SkippedUnreadable) -join ', ') + '.').Trim() }
    if ($Result.PSObject.Properties['SkippedBadPath'] -and @($Result.SkippedBadPath).Count -gt 0) { $notChanged = ($notChanged + ' These games were left out because the game file path saved in the profile is not a valid path: ' + (@($Result.SkippedBadPath) -join ', ') + '.').Trim() }
    $needs = New-Object System.Collections.Generic.List[string]
    if ($Result.PSObject.Properties['BackupLocationNote'] -and $Result.BackupLocationNote -and -not $hasBackupFolder) { [void]$needs.Add('The folder for saved copies could not be checked, so a save would stop. Press D to see why.') }
    $reviewCount = (Get-TpmLaunchBoxUnverifiedPaths -Result $Result).Count + @($Result.KeptFiles).Count
    if ($reviewCount -gt 0) { [void]$needs.Add($(if ($reviewCount -eq 1) { '1 LaunchBox file needs a check.' } else { ('{0} LaunchBox files need a check.' -f $reviewCount) })) }
    $blocks = Get-TpmLaunchBoxDetailBlocks -Result $Result
    $titleSummary = Get-TpmLaunchBoxTitleSummary -Result $Result
    foreach ($titleLine in @($titleSummary.Done)) { [void]$done.Add($titleLine) }
    if ($titleSummary.NotChanged) { $notChanged = ($notChanged + ' ' + $titleSummary.NotChanged).Trim() }
    $next = if ($status -ne 'Ok' -and $blocks.Count -gt 0) { 'Press D to see what happened.' } else { '' }
    Write-TpmOutcome -Title (Get-TpmLaunchBoxPlainTitle -Result $Result) -Status $status -Done $done.ToArray() -NotChanged $notChanged -Needs $needs.ToArray() -Next $next -DetailBlocks $blocks -Unattended:$Unattended
}

# The plan the user is asked to approve. The same preview is not printed twice: when it is the one that was
# just shown, one short line says so (the plan is logged either way).
function Write-TpmLaunchBoxPlan {
    param([Parameter(Mandatory)]$Result, [string]$AlreadyShownSummary = '', [switch]$Unattended)
    if ($AlreadyShownSummary -and [string]$Result.Summary -ceq $AlreadyShownSummary) {
        Write-Log ('LaunchBox plan is the same preview that was shown before: {0}' -f $Result.Summary)
        Write-TpmText -Text 'This is the same preview you just saw.' -Color DarkGray -BlankBefore
        return
    }
    Write-TpmLaunchBoxResult -Result $Result -Unattended:$Unattended
}

# Games whose name has no sure match: the user may pick one of the listed names for each game, or skip it (Enter).
# Returns profile file name -> the chosen database game. Picking is always the user's choice; nothing is guessed.
function Read-TpmLaunchBoxTitleChoices {
    param([Parameter(Mandatory)][object[]]$Review)
    $choices = @{}
    $withOptions = @($Review | Where-Object { @($_.Options).Count -gt 0 })
    if ($withOptions.Count -eq 0) { return $choices }
    Write-TpmText -Text ('{0} could not be matched for sure.' -f (Format-TpmGameCount -Count $withOptions.Count)) -Color Yellow -BlankBefore
    if ((Read-TpmYesNo -Prompt 'Look at them one by one and pick a name for each? (Y/N)' -Default 'N') -ne 'Y') { return $choices }
    foreach ($item in $withOptions) {
        Write-TpmText -Text $item.Title -Color Cyan -BlankBefore
        $options = @($item.Options)
        Write-TpmText -Text ($item.Reason + ' Pick one, or Enter to skip.') -Color DarkGray
        for ($i = 0; $i -lt $options.Count; $i++) { Write-TpmText -Text ('[{0}] {1} (ID {2})' -f ($i + 1), $options[$i].Name, $options[$i].Id) -Color White }
        $pick = Read-TpmChoice -Prompt '  Your choice' -Choices (@('S') + @(1..$options.Count | ForEach-Object { [string]$_ })) -Default 'S'
        if ($pick -ne 'S') { $choices[[string]$item.File] = $options[[int]$pick - 1] }
    }
    return $choices
}

# The optional LaunchBox step after registration, as four short choices. P, A, F and B keep their meaning.
function Write-TpmLaunchBoxOffer {
    Write-TpmText -Text 'TeknoParrot registration is finished.' -Color Cyan
    Write-TpmText -Text 'Optional: add games to LaunchBox.' -Color Cyan -BlankBefore
    Write-TpmText -Text '[P] Preview first. No changes.' -Color White
    Write-TpmText -Text '[A] Add missing games (backed up).' -Color White
    Write-TpmText -Text '[G] Fill in game details and make playlists (backed up).' -Color White -BlankBefore
    Write-TpmText -Text '[V] Group regions and versions of a game into one (backed up).' -Color White
    Write-TpmText -Text '[S] Keep LaunchBox in step with TeknoParrot: removed, moved, renamed games (backed up).' -Color White -BlankBefore
    Write-TpmText -Text '[L] Link games for art and details (backed up).' -Color White
    Write-TpmText -Text '[F] Import file only. No changes.' -Color White -BlankBefore
    Write-TpmText -Text '[B] Skip this step.' -Color White
}

# The whole optional LaunchBox step (offer, preview, add games, or save a reference file).
# It is used after the whole-library checks and after "New game only".
function Invoke-TpmLaunchBoxStep {
    Write-Host ""
    $doLB = "N"
    $lbChoice = $null
    if ($dryRunActive) {
        Write-Log "PreviewMode: LaunchBox reference export skipped."
    } elseif ($Unattended) {
        Write-Log "Unattended: LaunchBox reference export skipped."
    } else {
        Write-TpmLaunchBoxOffer
        # Answers given for [P] Preview become the defaults for [A] (Enter
        # reuses them); [A] still plans read-only and asks before any write.
        $lbPreviewRoot = $null
        $lbPreviewChoice = $null
        $lbPreviewShownSummary = ''
        do {
            $lbChoice = Read-TpmChoice -Prompt '  Choice, default P' -Choices @('P', 'A', 'G', 'V', 'S', 'L', 'F', 'B') -Default 'P'
            if ($lbChoice -eq 'P') {
                Write-TpmText -Text 'Preview: TeknoParrot Manager only reads your LaunchBox files.' -Color DarkCyan
                $previewRoot = $lbRoot
                if (-not $previewRoot) { $previewRoot = Read-HostSafe '  LaunchBox install folder (Enter to go back)' }
                if ($previewRoot) {
                    $previewChoice = Read-TpmChoice -Prompt '  Platform: 1 Arcade, 2 TeknoParrot, 3 Both, B back' -Choices @('1','2','3','B') -Default '2'
                    if ($previewChoice -ne 'B') {
                        $lbPreviewRoot = $previewRoot
                        $lbPreviewChoice = $previewChoice
                        $previewPlatforms = switch ($previewChoice) { '1' { @('Arcade') } '2' { @('TeknoParrot') } '3' { @('Arcade','TeknoParrot') } }
                        $lbPreviewResult = Invoke-LaunchBoxDirectWrite -userProfilesDir $userProfilesDir -tpRoot $tpRoot -lbRoot $previewRoot -platformNames $previewPlatforms -PlanOnly -UseGamesDb -DatIndex $datIndex
                        Write-TpmLaunchBoxResult -Result $lbPreviewResult -Unattended:$Unattended
                        $lbPreviewShownSummary = [string]$lbPreviewResult.Summary
                    }
                }
            }
        } while ($lbChoice -eq 'P')
        if ($lbChoice -eq 'A') {
            Write-TpmLaunchBoxWriteNotice
            $lbWriteNoticeBlocks = Get-TpmLaunchBoxWriteNoticeBlocks
            $writeRoot = $lbRoot
            if (-not $writeRoot) {
                if ($lbPreviewRoot) {
                    $writeRoot = Read-HostSafe ("  LaunchBox install folder (Enter = previewed folder {0})" -f $lbPreviewRoot) -Default $lbPreviewRoot
                } else {
                    $writeRoot = Read-HostSafe '  LaunchBox install folder'
                }
            }
            $platformDefault = if ($lbPreviewChoice -in @('1','2','3')) { [string]$lbPreviewChoice } else { '2' }
            $platformPrompt = if ($lbPreviewChoice -in @('1','2','3')) { "  Platform: 1 Arcade, 2 TeknoParrot, 3 Both, 4 Custom, B cancel (Enter = previewed choice $platformDefault)" } else { '  Platform: 1 Arcade, 2 TeknoParrot, 3 Both, 4 Custom, B cancel' }
            $platformChoice = Read-TpmChoice -Prompt $platformPrompt -Choices @('1','2','3','4','B') -Default $platformDefault
            if ($platformChoice -ne 'B') {
                $targetPlatforms = switch ($platformChoice) {
                    '1' { @('Arcade') }
                    '2' { @('TeknoParrot') }
                    '3' { @('Arcade','TeknoParrot') }
                    '4' { @(Read-HostSafe '  Custom platform name (must be a safe filename)') }
                }
                # Show exactly what would change, then ask for consent to that plan (read-only preview first).
                # Official names and Games Database IDs from LaunchBox's own game list (read only). Asked only when the list is there;
                # when it is not, the plan says so in plain words and games keep today's names.
                $lbTitleParams = @{ UseGamesDb = $true; DatIndex = $datIndex }
                if ($writeRoot -and (Test-Path -LiteralPath (Get-TpmGamesDbPath -LaunchBoxRoot $writeRoot) -PathType Leaf)) {
                    $lbTitleChoice = Read-TpmChoice -Prompt '  Use official game names so LaunchBox finds info and artwork? 1 new games, 2 new and games already added, N no' -Choices @('1', '2', 'N') -Default '1'
                    if ($lbTitleChoice -eq 'N') { $lbTitleParams = @{ DatIndex = $datIndex } } elseif ($lbTitleChoice -eq '2') { $lbTitleParams.IncludeExisting = $true }
                }
                $lbPlanResult = Invoke-LaunchBoxDirectWrite -userProfilesDir $userProfilesDir -tpRoot $tpRoot -lbRoot $writeRoot -platformNames $targetPlatforms -PlanOnly @lbTitleParams
                $lbShownBefore = $lbPreviewShownSummary
                if ($lbPlanResult.PSObject.Properties['TitleReview'] -and @($lbPlanResult.TitleReview).Count -gt 0) {
                    $lbTitleParams.GamesDbChoices = Read-TpmLaunchBoxTitleChoices -Review @($lbPlanResult.TitleReview)
                    if ($lbTitleParams.GamesDbChoices.Count -gt 0) { $lbPlanResult = Invoke-LaunchBoxDirectWrite -userProfilesDir $userProfilesDir -tpRoot $tpRoot -lbRoot $writeRoot -platformNames $targetPlatforms -PlanOnly @lbTitleParams }
                }
                if ($lbTitleParams.ContainsKey('UseGamesDb')) { $lbShownBefore = '' }
                Write-TpmLaunchBoxPlan -Result $lbPlanResult -AlreadyShownSummary $lbShownBefore -Unattended:$Unattended
                if ($lbPlanResult.Reason -eq 'PREVIEW' -and [int]$lbPlanResult.WouldChangeFiles -gt 0) {
                    if ((Read-TpmYesNo -Prompt 'Write exactly these changes after a verified backup? (Y/N, D = about the risks)' -Default 'N' -DetailsAction { Show-TpmDetailBlocks -Blocks $lbWriteNoticeBlocks }) -eq 'Y') {
                        $lbWriteResult = Invoke-LaunchBoxDirectWrite -userProfilesDir $userProfilesDir -tpRoot $tpRoot -lbRoot $writeRoot -platformNames $targetPlatforms @lbTitleParams
                        Write-TpmLaunchBoxResult -Result $lbWriteResult
                    } else {
                        Write-Host '  LaunchBox write canceled; nothing was changed.' -ForegroundColor DarkGray
                    }
                }
            }
        } elseif ($lbChoice -eq 'G') {
            Invoke-TpmLaunchBoxEnrichStep -UserProfilesDir $userProfilesDir -LbRoot $lbRoot -TpRoot $tpRoot -DatIndex $datIndex
        } elseif ($lbChoice -eq 'V') {
            Invoke-TpmLaunchBoxChangeStep -Kind Group -UserProfilesDir $userProfilesDir -LbRoot $lbRoot -TpRoot $tpRoot -DatIndex $datIndex
        } elseif ($lbChoice -eq 'S') {
            Invoke-TpmLaunchBoxChangeStep -Kind Sync -UserProfilesDir $userProfilesDir -LbRoot $lbRoot -TpRoot $tpRoot -DatIndex $datIndex
        } elseif ($lbChoice -eq 'L') {
            Invoke-TpmLaunchBoxIdLinkStep -LbRoot $lbRoot -TpRoot $tpRoot -DatIndex $datIndex
        } elseif ($lbChoice -eq 'F') {
            $doLB = "Y"
        }
        if ($lbChoice -ne 'B') { Invoke-TpmLaunchBoxMediaStep -lbRoot $lbRoot -userProfilesDir $userProfilesDir -Unattended:$Unattended -DryRun:$dryRunActive -TpRoot $tpRoot -DatIndex $datIndex }
    }


    if ($doLB -eq "Y") {
        $lbPath  = Join-Path $script:TpmOwnedLayout.Reports "TeknoParrot-LaunchBox-Import.xml"
        $lbCount = Export-LaunchBoxXml -userProfilesDir $userProfilesDir -outputPath $lbPath
        if ($lbCount -eq -2) {
            Write-Host "  Existing LaunchBox reference was preserved; TeknoParrot Manager did not overwrite it." -ForegroundColor Yellow
            Write-Host ("  Existing file: {0}" -f $lbPath) -ForegroundColor DarkCyan
            Write-Host "  No new reference was exported. Keep this file, or move it after making a copy before exporting again." -ForegroundColor DarkGray
        } elseif ($lbCount -lt 0) {
            Write-Host "  LaunchBox reference export failed; existing files are never overwritten. See TeknoParrot-Manager.log." -ForegroundColor Red
        } elseif ($lbCount -eq 0) {
            # An empty reference would block the next export (existing files are never overwritten), so remove the one this call just created.
            try { if (Test-Path -LiteralPath $lbPath -PathType Leaf) { Remove-Item -LiteralPath $lbPath -Force -ErrorAction Stop } } catch { Write-Log "LaunchBox export: could not remove the empty reference -- $_" }
            Write-Host "  No reference file was kept: none of the registered profiles has an existing game path." -ForegroundColor Yellow
            Write-Host "  Register games first (or repair their saved paths in Library Health Check), then export again." -ForegroundColor DarkGray
        } else {
            Write-Host ("  Exported : {0} game(s)" -f $lbCount) -ForegroundColor Green
            Write-Host "  File     : $lbPath" -ForegroundColor DarkCyan
            Write-Host ""
            Write-Host "  HOW TO IMPORT INTO LAUNCHBOX" -ForegroundColor Cyan
            Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
            Write-Host "  Important: LaunchBox must be fully CLOSED before importing." -ForegroundColor Yellow
            Write-Host ""
            Write-Host "  Step 1.  Close LaunchBox completely." -ForegroundColor White
            Write-Host "  Step 2.  Open LaunchBox." -ForegroundColor White
            Write-Host "  Step 3.  Go to  Tools -> Import -> Emulated Games." -ForegroundColor White
            Write-Host "  Step 4.  On the first screen:" -ForegroundColor White
            Write-Host "             - Emulator: select TeknoParrot (or add it first -- see below)." -ForegroundColor DarkGray
            Write-Host "             - Import type: 'Import ROM files'." -ForegroundColor DarkGray
            Write-Host ("             - Folder: {0}" -f (Join-Path $tpRoot "UserProfiles")) -ForegroundColor DarkGray
            Write-Host "             - File types: *.xml  (import the profile files themselves," -ForegroundColor DarkGray
            Write-Host "               not the game executables -- TeknoParrot launches games" -ForegroundColor DarkGray
            Write-Host "               by profile, so the profile XML is what LaunchBox treats" -ForegroundColor DarkGray
            Write-Host "               as the 'rom' for each game)." -ForegroundColor DarkGray
            Write-Host "  Step 5.  Follow the wizard. LaunchBox will assign game names," -ForegroundColor White
            Write-Host "             metadata, and box art automatically." -ForegroundColor DarkGray
            Write-Host ""
            Write-Host "  If TeknoParrot is not yet in LaunchBox's emulator list:" -ForegroundColor Cyan
            Write-Host "    a. Go to  Tools -> Manage -> Emulators -> Add." -ForegroundColor DarkGray
            Write-Host "    b. Name: TeknoParrot" -ForegroundColor DarkGray
            Write-Host ("    c. Emulator path: {0}" -f (Join-Path $tpRoot "TeknoParrotUi.exe")) -ForegroundColor DarkGray
            Write-Host "    d. Command-line parameters: --profile=%romfile%.xml" -ForegroundColor DarkGray
            Write-Host "    e. Exit Script tab: add a script so Escape cleanly quits" -ForegroundColor DarkGray
            Write-Host "       TeknoParrot back to LaunchBox (without one, Escape may not" -ForegroundColor DarkGray
            Write-Host "       exit the game properly)." -ForegroundColor DarkGray
            Write-Host "    f. Save, then re-run the import wizard." -ForegroundColor DarkGray
            Write-Host ""
            Write-Host "  Seeing full-screen issues only when launching through LaunchBox?" -ForegroundColor Cyan
            Write-Host "    Go to  Tools -> Manage -> Emulators -> TeknoParrot -> Edit ->" -ForegroundColor DarkGray
            Write-Host "    Startup Screen tab, and disable 'Enable Game Startup Screen'." -ForegroundColor DarkGray
            Write-Host ""
            Write-Host "  The exported XML file ($lbPath)" -ForegroundColor DarkCyan
            Write-Host "  is a reference showing all registered games, their profile codes," -ForegroundColor DarkCyan
            Write-Host "  and executable paths. You do not need to import it directly." -ForegroundColor DarkCyan
            Write-Log "LaunchBox export: exported $lbCount games to $lbPath"
        }
    }
}

# Before a LaunchBox write: two short lines. The small risk that an app can reopen is the Details view.
function Write-TpmLaunchBoxWriteNotice {
    Write-TpmText -Text 'Close LaunchBox and BigBox first. TeknoParrot Manager will not close them for you.' -Color Yellow -BlankBefore
    Write-TpmText -Text 'Only missing games are added. Your own entries are kept.' -Color DarkCyan
}

function Get-TpmLaunchBoxWriteNoticeBlocks {
    return ,@(@{ Heading = 'Before the LaunchBox write'; Lines = @(
        'Keep closed: Close LaunchBox and BigBox and keep them closed. TeknoParrot Manager never force-closes either app.',
        'Small risk: An app can reopen after a process check. Multi-file saves are not atomic.',
        'Kept: Existing entries/identities are preserved; only missing entries are added.',
        'Saved copy: A verified saved copy of your LaunchBox files is made before anything is written.'
    ) })
}

# =============================================================================
# LAUNCHBOX XML EXPORT  (standalone file only -- no direct LaunchBox writes)
# =============================================================================
# A separate reference file, not a direct library write. The direct writer above
# enforces backup/readback and preserves existing identities. This export is
# useful when the user prefers LaunchBox's own import wizard instead.
#
# Returns the exported game count, -2 when the destination already exists, or
# -1 when publication fails.
#
# <ApplicationPath> identifies the UserProfile XML itself, not the game
# executable: TeknoParrot uses the profile as its LaunchBox ROM through the
# --profile=%romfile%.xml template. The reference uses absolute profile paths.
function Export-LaunchBoxXml {
    param([string]$userProfilesDir, [string]$outputPath)

    $files = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $userProfilesDir -ProgressLabel 'LaunchBox profile export discovery' -EnumerationErrorAction SilentlyContinue)

    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine('<?xml version="1.0" encoding="utf-8"?>')
    [void]$sb.AppendLine('<LaunchBox>')

    $exportStarted = Get-Date
    $exportCurrent = 0
    $count = 0
    foreach ($f in $files) {
        $exportCurrent++
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'LaunchBox profile export' -Current $exportCurrent -Total $files.Count -StartedAt $exportStarted
        try {
            $doc = Read-Xml $f.FullName
            if ($null -eq $doc.GameProfile) { continue }

            $gpNode   = $doc.GameProfile.SelectSingleNode("GamePath")
            $gamePath = if ($gpNode) { $gpNode.InnerText } else { "" }
            if (-not $gamePath -or -not ([System.IO.File]::Exists((ConvertTo-TpmAutoSyncLongPath -Path $gamePath)) -or [System.IO.Directory]::Exists((ConvertTo-TpmAutoSyncLongPath -Path $gamePath)))) { continue }

            $title = Get-TpmProfileFriendlyTitle -Doc $doc -BaseName $f.BaseName

            $appPath = $f.FullName

            $esc = [System.Security.SecurityElement]
            [void]$sb.AppendLine('  <Game>')
            [void]$sb.AppendLine("    <Title>$($esc::Escape($title))</Title>")
            [void]$sb.AppendLine("    <Platform>Arcade</Platform>")
            [void]$sb.AppendLine("    <ApplicationPath>$($esc::Escape($appPath))</ApplicationPath>")
            [void]$sb.AppendLine("    <CommandLine />")
            [void]$sb.AppendLine("    <RomPath>$($esc::Escape($gamePath))</RomPath>")
            [void]$sb.AppendLine("    <Favorite>false</Favorite>")
            [void]$sb.AppendLine("    <Completed>false</Completed>")
            [void]$sb.AppendLine("    <Hidden>false</Hidden>")
            [void]$sb.AppendLine("    <Enabled>true</Enabled>")
            [void]$sb.AppendLine("    <Notes>Exported by TeknoParrot Manager</Notes>")
            [void]$sb.AppendLine('  </Game>')
            $count++
        } catch {
            Write-Log "LaunchBox export: skipped $($f.Name) -- $_"
        }
    }
    if ($files.Count -gt 0) {
        Write-TpmCompactExtractionProgress -Phase Scanning -Label 'LaunchBox profile export' -Current $exportCurrent -Total $files.Count -StartedAt $exportStarted -Complete
    }

    [void]$sb.AppendLine('</LaunchBox>')

    # Publish only a complete new reference. CreateNew and the no-overwrite
    # move preserve any existing file, including a file created after the
    # initial existence check.
    if ([System.IO.File]::Exists($outputPath)) {
        Write-Log "LaunchBox export: refused to overwrite existing file $outputPath"
        return -2
    }
    $tempPath = '{0}.{1}.tmp' -f $outputPath, [guid]::NewGuid().ToString('N')
    $tempCreated = $false
    $stream = $null
    try {
        Assert-TpmNoReparseWriteTarget -Path $outputPath -Operation 'LaunchBox reference export'
        Assert-TpmNoReparseWriteTarget -Path $tempPath -Operation 'LaunchBox reference export'
        $stream = [System.IO.File]::Open($tempPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        $tempCreated = $true
        $bytes = (New-Object System.Text.UTF8Encoding $false).GetBytes($sb.ToString())
        $stream.Write($bytes, 0, $bytes.Length)
        $stream.Flush($true)
        $stream.Dispose()
        $stream = $null
        [System.IO.File]::Move($tempPath, $outputPath)
        $tempCreated = $false
        return $count
    } catch {
        if ($null -ne $stream) { try { $stream.Dispose() } catch {} }
        if ($tempCreated -and [System.IO.File]::Exists($tempPath)) {
            try { [System.IO.File]::Delete($tempPath) }
            catch { Write-Log "LaunchBox export: temporary reference cleanup failed at $tempPath -- $_" }
        }
        Write-Log "LaunchBox export: FAILED to publish reference at $outputPath -- $_"
        return -1
    }
}


# =============================================================================
# POSTGRESQL DATABASE BACKUP/RESTORE
# =============================================================================

# Backs up every verified, existing Postgres database used by a registered
# profile. A query failure is not treated as an absent database. The result
# is explicit so the caller cannot proceed to profile writes after a partial
# backup.
# Tells whether every data file inside a TAR-format game backup is valid UTF-8: $true yes, $false some bytes are not (a UTF8 database
# would refuse that table and it would come back empty), $null the file is not a readable TAR backup so nothing is known.
# Only reads the file.
function Test-PostgresBackupDataIsUtf8 {
    param([Parameter(Mandatory)][string]$BackupFile)
    $stream = $null
    try {
        $stream = [System.IO.File]::OpenRead($BackupFile)
        $strict = New-Object System.Text.UTF8Encoding($false, $true)
        $header = New-Object byte[] 512
        $buffer = New-Object byte[] 1048576
        $firstBlock = $true
        while ($stream.Read($header, 0, 512) -eq 512) {
            if ($firstBlock) {
                if ([System.Text.Encoding]::ASCII.GetString($header, 257, 5) -cne 'ustar') { return $null }
                $firstBlock = $false
            }
            if ($header[0] -eq 0) { break }
            $entryName = [System.Text.Encoding]::ASCII.GetString($header, 0, 100).TrimEnd([char]0)
            $size = [Convert]::ToInt64([System.Text.Encoding]::ASCII.GetString($header, 124, 12).Trim([char]0, ' '), 8)
            $isData = ($entryName -like '*.dat' -and $entryName -ne 'toc.dat')
            $decoder = $strict.GetDecoder()
            $left = $size
            while ($left -gt 0) {
                $read = $stream.Read($buffer, 0, [int][Math]::Min($left, $buffer.Length))
                if ($read -le 0) { return $null }
                if ($isData) { [void]$decoder.GetCharCount($buffer, 0, $read, $false) }
                $left -= $read
            }
            if ($isData) { [void]$decoder.GetCharCount($buffer, 0, 0, $true) }
            $padding = (512 - ($size % 512)) % 512
            if ($padding -gt 0) { [void]$stream.Seek($padding, [System.IO.SeekOrigin]::Current) }
        }
        if ($firstBlock) { return $null }
        return $true
    } catch [System.Text.DecoderFallbackException] {
        return $false
    } catch {
        return $null
    } finally {
        if ($null -ne $stream) { $stream.Dispose() }
    }
}

# Returns the encoding used by the shipped PostgreSQL game backups. The
# PostgreSQL restore contract is deliberately limited to the installed 8.3
# client tools; no newer client or compatibility path is accepted.
# A caller that knows the backup file passes it: for the one UTF8 database, a backup whose data is not valid UTF-8 is restored into
# SQL_ASCII (which keeps every byte as it is) so that no table comes back empty. Without the file the rule is by name only.
function Get-PostgresRestoreEncoding {
    param([Parameter(Mandatory)][string]$DbName, [string]$BackupFile = '')
    if ($DbName -ieq 'GameDB06') {
        if (-not [string]::IsNullOrWhiteSpace($BackupFile) -and ((Test-PostgresBackupDataIsUtf8 -BackupFile $BackupFile) -eq $false)) { return 'SQL_ASCII' }
        return 'UTF8'
    }
    return 'SQL_ASCII'
}

function Get-Postgres83RestoreToolNames {
    return @('psql.exe','pg_dump.exe','dropdb.exe','createdb.exe','pg_restore.exe')
}

# Runs one PostgreSQL 8.3 client command. The password reaches the tool only
# through Invoke-PostgresNativeCommand -PasswordPlain (PGPASSWORD for that one
# call, FIX95 S5); version checks pass no password. The Output is redacted ONCE, inside
# Invoke-PostgresNativeCommand (FIX129: a second pass over the finished text could rewrite the "[REDACTED]" marker itself for a
# short password). A caller that must decide from the tool's text passes -Interpret (see Invoke-PostgresNativeCommand): the answer
# comes back as Interpretation, the raw text never does. TimedOut is set when the call was stopped at its time limit; such a
# command never Succeeded.
function Invoke-Postgres83RestoreCommand {
    param(
        [Parameter(Mandatory)][ValidateSet('psql.exe','pg_dump.exe','dropdb.exe','createdb.exe','pg_restore.exe')][string]$ToolName,
        [string[]]$Arguments = @(),
        [AllowEmptyString()][string]$SuperPasswordPlain = '',
        [scriptblock]$Interpret = $null,
        [object]$InterpretContext = $null
    )
    $executable = Join-Path $script:PostgresBinDir $ToolName
    if (-not (Test-Path -LiteralPath $executable -PathType Leaf)) {
        throw ("PostgreSQL 8.3 tool could not be verified: {0}" -f $executable)
    }
    $nativeParameters = @{ FilePath = $executable; Arguments = @($Arguments); Secrets = @($SuperPasswordPlain); PasswordPlain = $SuperPasswordPlain }
    if ($null -ne $Interpret) { $nativeParameters['Interpret'] = $Interpret; $nativeParameters['InterpretContext'] = $InterpretContext }
    $nativeResult = Invoke-PostgresNativeCommand @nativeParameters
    $exitCode = [int]$nativeResult.ExitCode
    $timedOut = [bool](Get-TpmTransactionField -Object $nativeResult -Name 'TimedOut' -Default $false)
    return [pscustomobject]@{
        Tool = $ToolName
        Executable = $executable
        Arguments = @($Arguments)
        ExitCode = $exitCode
        Succeeded = ($exitCode -eq 0 -and -not $timedOut)
        TimedOut = $timedOut
        Output = [string]$nativeResult.Output
        Interpretation = (Get-TpmTransactionField -Object $nativeResult -Name 'Interpretation' -Default $null)
    }
}

# The real name of a PostgreSQL identifier as it is printed in SQL or in a pg_restore line: a double-quoted identifier loses its
# quotes and its doubled quotes ("My ""odd"" name" -> My "odd" name); anything else is returned as it is. Pure.
function ConvertFrom-PostgresQuotedIdentifier {
    param([AllowNull()][AllowEmptyString()][string]$Text)
    $value = ([string]$Text).Trim()
    if ($value.Length -ge 2 -and $value.StartsWith('"') -and $value.EndsWith('"')) { return $value.Substring(1, $value.Length - 2).Replace('""', '"') }
    return $value
}

# FIX95 (S1) / FIX125 / FIX129: the only pg_restore exit 1 that counts as finished is the known problem of the bundled game archives.
# PostgreSQL 8.3 restores every table and row but cannot create some foreign keys because the archive pairs a numeric
# column with an integer one. The output must be exactly that: every "Error from TOC entry" is a CONSTRAINT or FK CONSTRAINT
# entry, its one error is 'foreign key constraint "<the same name>" cannot be implemented', followed by the DETAIL line that
# names numeric and integer key columns, followed by the "Command was:" text of an ALTER TABLE ... ADD CONSTRAINT <the same
# name> FOREIGN KEY statement; nothing else is reported, and the number of entries equals "errors ignored on restore". Any
# other, incomplete or empty output returns no names, so the caller keeps the failure. A primary key or unique entry is also a
# "CONSTRAINT" entry, but its error text is different, so it never matches. Returns the accepted constraint names.
# FIX129: the "Command was:" text is SQL and can run over several lines. It is read as one statement: lines are added to it
# until the statement ends with ";" (or with "...": PostgreSQL 8.3 shortens a long statement that way), and then it must be the whole ALTER TABLE ... ADD CONSTRAINT <name> FOREIGN KEY statement. A
# line inside it is only refused when it starts like a tool or server message (pg_restore:, ERROR:, WARNING:, DETAIL:, ...,
# "could not"), so a table or column that is called detail, error or warning is no problem, and any real extra message after the
# ";" still ends the parse with no names. Names may be double-quoted identifiers (spaces, capitals, doubled quotes).
function Get-PostgresKnownConstraintRestoreWarnings {
    param([AllowNull()][AllowEmptyString()][string]$Output)
    if ([string]::IsNullOrWhiteSpace($Output)) { return @() }
    $identifier = '(?:"(?:[^"]|"")+"|[^\s".;()]+)'
    $statementPattern = '^(?i:ALTER\s+TABLE)\s+(?:(?i:ONLY)\s+)?' + $identifier + '(?:\.' + $identifier + ')?\s+(?i:ADD\s+CONSTRAINT)\s+(' + $identifier + ')\s+(?i:FOREIGN\s+KEY)\b[^;]*(?:;|\.\.\.)$'
    $messagePrefixPattern = '^(?:(?:pg_restore|pg_dump|psql):|(?:ERROR|FATAL|PANIC|WARNING|NOTICE|INFO|LOG|DEBUG\d?|DETAIL|HINT|CONTEXT|STATEMENT|LOCATION|QUERY):)|^(?i:could not\s)'
    $names = New-Object System.Collections.Generic.List[string]
    $reported = -1
    $pendingName = $null
    $commandText = ''
    $statementIsComplete = {
        $statement = [regex]::Match($commandText, $statementPattern)
        return ($statement.Success -and (ConvertFrom-PostgresQuotedIdentifier -Text $statement.Groups[1].Value) -ceq $pendingName)
    }
    # Start: before the first entry. Entry: waiting for that entry's error. Error: its known error was seen, its
    # numeric/integer DETAIL is still missing. Detail: the DETAIL was seen, the "Command was:" text is still missing.
    # Command: inside the "Command was:" text that pg_restore prints after the DETAIL (it can span lines). Only Start and a
    # Command whose text is the ALTER TABLE ... ADD CONSTRAINT <name> FOREIGN KEY statement of the entry are complete states.
    $state = 'Start'
    foreach ($rawLine in @($Output -split '\r?\n')) {
        $line = $rawLine.Trim()
        if ($line -eq '') { continue }
        $complete = ($state -eq 'Start' -or ($state -eq 'Command' -and (& $statementIsComplete)))
        $entry = [regex]::Match($line, '^(?:pg_restore: \[archiver \(db\)\] )?Error from TOC entry \d+;\s*\d+\s+\d+\s+(?:FK )?CONSTRAINT\s+(.+)\s+(\S+)$')
        $knownError = [regex]::Match($line, '^(?:pg_restore: \[archiver \(db\)\] )?could not execute query: ERROR:\s+foreign key constraint "(.+)" cannot be implemented$')
        $ignored = [regex]::Match($line, '^(?:pg_restore: )?WARNING: errors ignored on restore: (\d+)$')
        if ($entry.Success) {
            if (-not $complete -or $reported -ge 0) { return @() }
            $pendingName = ConvertFrom-PostgresQuotedIdentifier -Text $entry.Groups[1].Value
            $commandText = ''
            $state = 'Entry'
        } elseif ($knownError.Success) {
            if ($state -ne 'Entry' -or $knownError.Groups[1].Value -cne $pendingName) { return @() }
            $state = 'Error'
        } elseif ($line -match '^DETAIL:\s+Key columns ".+" and ".+" are of incompatible types: numeric and integer\.$') {
            if ($state -ne 'Error') { return @() }
            [void]$names.Add($pendingName)
            $state = 'Detail'
        } elseif ($line -match '^Command was: ') {
            if ($state -ne 'Detail') { return @() }
            $commandText = $line.Substring(13).Trim()
            $state = 'Command'
        } elseif ($ignored.Success) {
            if (-not $complete -or $reported -ge 0) { return @() }
            $reported = [int]$ignored.Groups[1].Value
            $state = 'Start'
        } elseif ($line -match '^(?:pg_restore: \[archiver \(db\)\] )?Error while PROCESSING TOC:$') {
            if (-not $complete) { return @() }
        } elseif ($state -ne 'Command' -or $commandText.EndsWith(';') -or $commandText.EndsWith('...') -or $line -cmatch $messagePrefixPattern) {
            return @()
        } else {
            $commandText += ' ' + $line
        }
    }
    if (-not ($state -eq 'Start' -or ($state -eq 'Command' -and (& $statementIsComplete))) -or $names.Count -eq 0 -or $reported -ne $names.Count) { return @() }
    return $names.ToArray()
}

# FIX125: the ONE judgment of a pg_restore result for a database that TeknoParrot Manager has just created from a game's
# bundled backup. Pure function: no I/O, no logging. Accepted is true only when
#   - the process did not time out, and
#   - the exit code is 0 (plain success, KnownWarningCount 0), or
#   - createdb succeeded, the exit code is 1, and Get-PostgresKnownConstraintRestoreWarnings accepts the whole output: every
#     error block is the numeric-vs-integer foreign-key error of an ALTER TABLE ... ADD CONSTRAINT ... FOREIGN KEY statement
#     and their number equals "errors ignored on restore: N" (KnownWarningCount = N, ConstraintNames = their names).
# Any other exit code, any other error text, a count mismatch, empty output with exit 1, a timeout, or a database that was
# not created is Accepted = $false, so the caller fails and rolls back exactly as for any other failed restore.
# FIX129: Output is the RAW standard-error text of pg_restore (Invoke-Postgres83RestoreCommandChecked passes it in memory through
# -Interpret): pg_restore reports every error on standard error, so text on standard output is never part of the judgment and
# can never make a restore look finished. The redacted text must never be judged. There is no database-name input and there
# must never be one.
function Get-PostgresRestoreJudgement {
    param(
        [int]$ExitCode,
        [AllowNull()][AllowEmptyString()][string]$Output = '',
        [bool]$CreatedbSucceeded = $false,
        [bool]$TimedOut = $false
    )
    $rejected = { param([string]$Reason) [pscustomobject]@{ Accepted = $false; Reason = $Reason; KnownWarningCount = 0; ConstraintNames = @() } }
    if ($TimedOut) { return (& $rejected 'TimedOut') }
    if ($ExitCode -eq 0) { return [pscustomobject]@{ Accepted = $true; Reason = 'ExitZero'; KnownWarningCount = 0; ConstraintNames = @() } }
    if ($ExitCode -ne 1) { return (& $rejected 'ExitCodeNotOne') }
    if (-not $CreatedbSucceeded) { return (& $rejected 'DatabaseNotCreated') }
    $names = @(Get-PostgresKnownConstraintRestoreWarnings -Output $Output)
    if ($names.Count -eq 0) { return (& $rejected 'NotOnlyKnownWarnings') }
    return [pscustomobject]@{ Accepted = $true; Reason = 'KnownWarningsOnly'; KnownWarningCount = $names.Count; ConstraintNames = $names }
}

# FIX129 (N2): CreatedbSucceeded is the REAL result of the createdb call that came before (the callers pass what they saw), and it
# defaults to $false: a caller that opts in but does not say createdb succeeded gets the strict failure (DatabaseNotCreated).
function Invoke-Postgres83RestoreCommandChecked {
    param(
        [Parameter(Mandatory)][string]$ToolName,
        [string[]]$Arguments = @(),
        [AllowEmptyString()][string]$SuperPasswordPlain = '',
        [Parameter(Mandatory)][object]$CommandLog,
        [string]$DatabaseName = '',
        [switch]$AcceptConstraintOnlyRestoreWarnings,
        [bool]$CreatedbSucceeded = $false
    )
    # FIX125: only the restore of a game's bundled archive into the database this run has just created (fresh setup and the
    # guided rebuild, which call this after createdb succeeded) opts in. Restores of the user's own backups, the rollback dump
    # and every other tool stay strict. Get-PostgresRestoreJudgement decides.
    # FIX129: it decides on the RAW standard-error text, in memory, through -Interpret; only the redacted text and the small
    # judgment (names redacted too) are kept in the command that goes to the log and the receipts.
    $judgeRestore = ($AcceptConstraintOnlyRestoreWarnings -and $ToolName -eq 'pg_restore.exe')
    $commandParameters = @{ ToolName = $ToolName; Arguments = @($Arguments); SuperPasswordPlain = $SuperPasswordPlain }
    if ($judgeRestore) {
        $commandParameters['Interpret'] = {
            param($Raw, $Context)
            $decision = Get-PostgresRestoreJudgement -ExitCode ([int]$Raw.ExitCode) -Output ([string]$Raw.StdErr) -CreatedbSucceeded ([bool]$Context.CreatedbSucceeded) -TimedOut ([bool]$Raw.TimedOut)
            [pscustomobject]@{
                Accepted = [bool]$decision.Accepted
                Reason = [string]$decision.Reason
                KnownWarningCount = [int]$decision.KnownWarningCount
                ConstraintNames = @(@($decision.ConstraintNames) | ForEach-Object { ConvertTo-PostgresRedactedText -Text ([string]$_) -Secrets @([string]$Context.Secret) })
            }
        }
        $commandParameters['InterpretContext'] = [pscustomobject]@{ CreatedbSucceeded = $CreatedbSucceeded; Secret = $SuperPasswordPlain }
    }
    $command = Invoke-Postgres83RestoreCommand @commandParameters
    if ($judgeRestore -and -not $command.Succeeded) {
        $judgment = Get-TpmTransactionField -Object $command -Name 'Interpretation' -Default $null
        if ($null -ne $judgment -and $judgment.Accepted -and $judgment.KnownWarningCount -gt 0) {
            $command | Add-Member -NotePropertyName Succeeded -NotePropertyValue $true -Force
            # FIX130 (N6): only what was checked is claimed. The restore tool reported no other error; the tables and rows are not counted here.
            $command | Add-Member -NotePropertyName AcceptedWarnings -NotePropertyValue ('Finished with a known limitation: {0} in the game''s own backup could not be made. This is a known problem with that backup. The restore tool reported no other problem.' -f (Format-TpmCountNoun -Count $judgment.KnownWarningCount -Singular 'link between tables' -Plural 'links between tables')) -Force
            $command | Add-Member -NotePropertyName AcceptedWarningCount -NotePropertyValue ([int]$judgment.KnownWarningCount) -Force
            $command | Add-Member -NotePropertyName AcceptedConstraintNames -NotePropertyValue @($judgment.ConstraintNames) -Force
        }
    }
    [void]$CommandLog.Add($command)
    if (-not $command.Succeeded) {
        $subject = if ([string]::IsNullOrWhiteSpace($DatabaseName)) { $ToolName } else { "$ToolName for database $DatabaseName" }
        $detail = if ([string]::IsNullOrWhiteSpace([string]$command.Output)) { 'no diagnostic text' } else { [string]$command.Output }
        $timeoutText = if ([bool](Get-TpmTransactionField -Object $command -Name 'TimedOut' -Default $false)) { ' (timed out)' } else { '' }
        throw ("PostgreSQL 8.3 {0} failed with exit code {1}{2}: {3}" -f $subject, $command.ExitCode, $timeoutText, $detail)
    }
    return $command
}

# PostgreSQL 8.3 has no dropdb --if-exists option. Recheck immediately before
# the command, skip when verified absent, then verify the absent post-state.
function Invoke-Postgres83DropDatabaseVerified {
    param(
        [Parameter(Mandatory)][string]$DbName,
        [AllowEmptyString()][string]$SuperPasswordPlain = '',
        [Parameter(Mandatory)][object]$CommandLog,
        [switch]$RequirePresent,
        [bool]$AllowExistingDrop = $false
    )
    $commands = New-Object System.Collections.Generic.List[object]
    $before = $null
    $after = $null
    $dropAttempted = $false
    $dropCommand = $null
    $verified = $false
    $failureStage = 'PreDropState'
    $errorText = $null
    try {
        if (-not (Test-SafePostgresDbName $DbName)) { throw 'The PostgreSQL database name is unsafe.' }
        $before = Get-PostgresDatabaseState -DbName $DbName -SuperPasswordPlain $SuperPasswordPlain
        if (-not $before.Verified) { throw 'The PostgreSQL database state was not verified before drop.' }
        if ($RequirePresent -and -not $before.Exists) { throw 'The PostgreSQL database was unexpectedly absent before drop.' }
        if ($before.Exists -and -not $AllowExistingDrop) {
            throw 'The PostgreSQL database is present but rollback ownership was not established.'
        }
        if ($before.Exists) {
            $failureStage = 'Drop'
            $dropAttempted = $true
            $dropCommand = Invoke-Postgres83RestoreCommandChecked -ToolName 'dropdb.exe' -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432',$DbName) -SuperPasswordPlain $SuperPasswordPlain -CommandLog $commands -DatabaseName $DbName
        }
        $failureStage = 'PostDropVerification'
        $after = Get-PostgresDatabaseState -DbName $DbName -SuperPasswordPlain $SuperPasswordPlain
        if (-not $after.Verified -or $after.Exists) { throw 'The PostgreSQL database was not verified absent after drop.' }
        $verified = $true
        $failureStage = $null
    } catch {
        $errorText = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
    }
    foreach ($command in $commands) { [void]$CommandLog.Add($command) }
    return [pscustomobject]@{
        PSTypeName = 'TPM.PostgresDropReceipt.v1'
        SchemaVersion = 1
        Database = $DbName
        BeforeState = $before
        DropAttempted = $dropAttempted
        DropCommand = $dropCommand
        AfterState = $after
        Verified = $verified
        FailureStage = $failureStage
        Error = $errorText
        Commands = @($commands.ToArray())
    }
}

# All five commands are checked before any database state is queried for a
# mutation. A version string must explicitly identify PostgreSQL 8.3; a
# PostgreSQL 12 or otherwise ambiguous client set is not a supported target.
function Test-Postgres83RestoreToolSet {
    param([AllowEmptyString()][string]$SuperPasswordPlain = '')
    $records = New-Object System.Collections.Generic.List[object]
    foreach ($toolName in @(Get-Postgres83RestoreToolNames)) {
        $path = Join-Path $script:PostgresBinDir $toolName
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            [void]$records.Add([pscustomobject]@{
                Name = $toolName
                Path = $path
                Verified = $false
                Version = $null
                Detail = 'The PostgreSQL 8.3 client tool is missing.'
            })
            continue
        }
        try {
            # Version checks need no password: none is set, and none is redacted from the version text that is judged below.
            $version = Invoke-Postgres83RestoreCommand -ToolName $toolName -Arguments @('--version')
            $versionText = [string]$version.Output
            $is83 = $version.Succeeded -and $versionText -match '(?i)\bPostgreSQL\b.*\b8\.3(?:\.\d+)?\b'
            [void]$records.Add([pscustomobject]@{
                Name = $toolName
                Path = $path
                Verified = [bool]$is83
                Version = if ($version.Succeeded) { $versionText } else { $null }
                Detail = if ($is83) { $versionText } elseif ($version.Succeeded) { 'The client did not report PostgreSQL 8.3.' } else { $versionText }
            })
        } catch {
            [void]$records.Add([pscustomobject]@{
                Name = $toolName
                Path = $path
                Verified = $false
                Version = $null
                Detail = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
            })
        }
    }
    $failed = @($records | Where-Object { -not $_.Verified })
    return [pscustomobject]@{
        Verified = ($failed.Count -eq 0)
        Tools = @($records.ToArray())
        FailedTools = @($failed | ForEach-Object { $_.Name })
        FailureCode = if ($failed.Count -gt 0) { 'POSTGRES83_TOOLSET_UNVERIFIED' } else { $null }
        Reason = if ($failed.Count -gt 0) { 'The PostgreSQL 8.3 client tool set could not be verified.' } else { $null }
    }
}

# Converts the selected .backup files into a deterministic, hash-backed plan.
# Database names may come from a FileInfo-like object or from an explicit
# Database property used by the guided reinitialize path.
function Get-PostgresRestoreBackupPlan {
    param(
        [Parameter(Mandatory)][object[]]$BackupFiles,
        [string]$SelectedBackupRoot = ''
    )
    $failure = {
        param([string]$Reason, [string]$Code = 'POSTGRES_BACKUP_PREFLIGHT_FAILED')
        return [pscustomobject]@{
            Valid = $false
            SelectedBackupRoot = $SelectedBackupRoot
            Items = @()
            FailureCode = $Code
            Reason = $Reason
        }
    }
    if (@($BackupFiles).Count -eq 0) {
        return (& $failure 'The selected PostgreSQL backup contains no database backups.')
    }
    try {
        $root = if ([string]::IsNullOrWhiteSpace($SelectedBackupRoot)) {
            $first = $BackupFiles[0]
            $firstPath = if ($first -is [string]) { [string]$first } elseif ($first.PSObject.Properties['BackupFile']) { [string]$first.BackupFile } else { [string]$first.FullName }
            [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($firstPath))
        } else {
            [System.IO.Path]::GetFullPath($SelectedBackupRoot)
        }
        if (-not (Test-Path -LiteralPath $root -PathType Container) -or -not (Test-TpmNoReparsePath -Path $root)) {
            return (& $failure 'The selected PostgreSQL backup folder could not be safely verified.' 'POSTGRES_BACKUP_ROOT_UNSAFE')
        }
        $items = New-Object System.Collections.Generic.List[object]
        $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($raw in @($BackupFiles)) {
            $path = if ($raw -is [string]) {
                [string]$raw
            } elseif ($raw.PSObject.Properties['BackupFile']) {
                [string]$raw.BackupFile
            } else {
                [string]$raw.FullName
            }
            if ([string]::IsNullOrWhiteSpace($path)) {
                return (& $failure 'A selected PostgreSQL backup file path was blank.')
            }
            $fullPath = [System.IO.Path]::GetFullPath($path)
            # A game's own starting database file may have no extension; that is accepted only when the caller names the database (the rebuild does, as setup does).
            $fileExtension = [System.IO.Path]::GetExtension($fullPath)
            $callerNamesDatabase = ($raw.PSObject.Properties['Database'] -and -not [string]::IsNullOrWhiteSpace([string]$raw.Database))
            if (-not ([string]::Equals($fileExtension, '.backup', [System.StringComparison]::OrdinalIgnoreCase) -or ($callerNamesDatabase -and $fileExtension -eq ''))) {
                return (& $failure 'A selected PostgreSQL backup file had an unexpected file type.')
            }
            if (-not [string]::Equals([System.IO.Path]::GetDirectoryName($fullPath), $root, [System.StringComparison]::OrdinalIgnoreCase)) {
                return (& $failure 'A selected PostgreSQL backup file was outside the selected backup folder.')
            }
            if (-not (Test-Path -LiteralPath $fullPath -PathType Leaf) -or -not (Test-TpmNoReparsePath -Path $fullPath)) {
                return (& $failure 'A selected PostgreSQL backup file could not be safely verified.')
            }
            $state = Get-TpmFileState -Path $fullPath
            if (-not $state.Readable -or -not $state.Exists -or $state.IsDirectory -or [int64]$state.Length -le 0) {
                return (& $failure 'A selected PostgreSQL backup file was missing, unreadable, or empty.')
            }
            $explicitDb = if ($raw.PSObject.Properties['Database']) { [string]$raw.Database } else { '' }
            $dbName = if ([string]::IsNullOrWhiteSpace($explicitDb)) {
                [System.IO.Path]::GetFileNameWithoutExtension($fullPath)
            } else {
                $explicitDb
            }
            if (-not (Test-SafePostgresDbName $dbName)) {
                return (& $failure 'A selected PostgreSQL backup contains an unsafe database name.' 'UNSAFE_POSTGRES_DATABASE_NAME')
            }
            if (-not $seen.Add($dbName)) {
                return (& $failure 'The selected PostgreSQL backup contains duplicate database names.' 'DUPLICATE_POSTGRES_DATABASE')
            }
            [void]$items.Add([pscustomobject]@{
                ItemId = $dbName
                Database = $dbName
                BackupFile = $fullPath
                BackupLength = [int64]$state.Length
                BackupSha256 = [string]$state.Sha256
                Encoding = Get-PostgresRestoreEncoding -DbName $dbName
            })
        }
        $ordered = @($items | Sort-Object @{ Expression = { $_.Database.ToUpperInvariant() } }, @{ Expression = { $_.BackupFile.ToUpperInvariant() } })
        return [pscustomobject]@{
            Valid = $true
            SelectedBackupRoot = $root
            Items = $ordered
            FailureCode = $null
            Reason = $null
        }
    } catch {
        return (& $failure (ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message)))
    }
}

# Creates the protected, transaction-local root used for current database
# dumps and receipts. The root is preserved when rollback or cleanup cannot
# be verified, so it remains recovery evidence rather than disposable temp.
function New-PostgresRestoreEvidenceRoot {
    param([string]$EvidenceRoot = '')
    $base = if ([string]::IsNullOrWhiteSpace($EvidenceRoot)) {
        Join-Path (Get-TpmOwnedBackupsRoot -BackupName 'PostgresRecoveryBackups') 'PostgresRecoveryBackups'
    } else {
        [System.IO.Path]::GetFullPath($EvidenceRoot)
    }
    $createdRoot = $null
    try {
        $baseParent = [System.IO.Path]::GetDirectoryName($base)
        if (-not (Test-TpmNoReparsePath -Path $baseParent)) {
            throw 'The PostgreSQL restore evidence parent failed the path safety check.'
        }
        [void][System.IO.Directory]::CreateDirectory($base)
        if (-not (Test-TpmNoReparsePath -Path $base)) {
            throw 'The PostgreSQL restore evidence root failed the path safety check.'
        }
        $createdRoot = Join-Path $base ('Restore-' + (Get-Date).ToUniversalTime().ToString('yyyy-MM-dd_HH-mm-ss_fff', [System.Globalization.CultureInfo]::InvariantCulture) + '-' + [guid]::NewGuid().ToString('N'))
        [void][System.IO.Directory]::CreateDirectory($createdRoot)
        if (-not (Test-TpmNoReparsePath -Path $createdRoot)) {
            throw 'The PostgreSQL restore transaction root failed the path safety check.'
        }
        Lock-PostgresRecoveryDirectory -Path $createdRoot
        return $createdRoot
    } catch {
        if ($createdRoot -and (Test-Path -LiteralPath $createdRoot)) {
            try { Remove-Item -LiteralPath $createdRoot -Recurse -Force -ErrorAction SilentlyContinue } catch {}
        }
        throw
    }
}

# FIX110 (S-7): the known vendor-backup limitations that a restore accepted (pg_restore exit 1 with only the known
# foreign-key errors). Read from the command receipts, never from output text.
function Get-PostgresAcceptedRestoreLimitations {
    param([AllowNull()][object[]]$Receipts = @())
    $records = New-Object System.Collections.Generic.List[object]
    foreach ($receipt in @($Receipts)) {
        if ($null -eq $receipt) { continue }
        foreach ($command in @($receipt.Commands)) {
            if ($null -eq $command -or -not $command.PSObject.Properties['AcceptedWarnings']) { continue }
            $names = if ($command.PSObject.Properties['AcceptedConstraintNames']) { @($command.AcceptedConstraintNames | ForEach-Object { [string]$_ }) } else { @() }
            [void]$records.Add([pscustomobject]@{ Database = [string]$receipt.Database; Message = [string]$command.AcceptedWarnings; ConstraintNames = $names })
        }
    }
    return @($records.ToArray())
}

function Write-PostgresRestoreReceiptFile {
    param(
        [Parameter(Mandatory)][string]$EvidenceRoot,
        [Parameter(Mandatory)][object[]]$Receipts
    )
    $path = Join-Path $EvidenceRoot 'database-receipts.json'
    $rows = @($Receipts | Sort-Object @{ Expression = { $_.Database.ToUpperInvariant() } } | ForEach-Object {
        [ordered]@{
            ItemId = [string]$_.ItemId
            Database = [string]$_.Database
            BackupFile = [string]$_.BackupFile
            RollbackDumpPath = [string]$_.RollbackDumpPath
            PreStateExists = [bool]$_.PreStateExists
            MutationAttempted = [bool]$_.MutationAttempted
            CreateOwnedForRollback = [bool]$_.CreateOwnedForRollback
            Changed = [bool]$_.Changed
            Succeeded = [bool]$_.Succeeded
            FailureStage = [string]$_.FailureStage
            Error = [string]$_.Error
            RollbackAttempted = [bool]$_.RollbackAttempted
            RollbackVerified = [bool]$_.RollbackVerified
            RollbackError = [string]$_.RollbackError
            AcceptedLimitations = @(Get-PostgresAcceptedRestoreLimitations -Receipts @($_))
            DropReceipt = $_.DropReceipt
            RollbackDropReceipt = $_.RollbackDropReceipt
            Commands = @($_.Commands | ForEach-Object {
                [ordered]@{
                    Tool = [string]$_.Tool
                    Arguments = @($_.Arguments)
                    ExitCode = [int]$_.ExitCode
                    Succeeded = [bool]$_.Succeeded
                    Output = [string]$_.Output
                }
            })
            RollbackCommands = @($_.RollbackCommands | ForEach-Object {
                [ordered]@{
                    Tool = [string]$_.Tool
                    Arguments = @($_.Arguments)
                    ExitCode = [int]$_.ExitCode
                    Succeeded = [bool]$_.Succeeded
                    Output = [string]$_.Output
                }
            })
        }
    })
    [System.IO.File]::WriteAllText($path, ($rows | ConvertTo-Json -Depth 12), (New-Object System.Text.UTF8Encoding $false))
    return $path
}

function Invoke-Postgres83RestoreDatabase {
    param(
        [Parameter(Mandatory)]$Item,
        [Parameter(Mandatory)]$PreState,
        [AllowEmptyString()][string]$SuperPasswordPlain = '',
        [switch]$AcceptConstraintOnlyRestoreWarnings
    )
    $commands = New-Object System.Collections.Generic.List[object]
    $receipt = [pscustomobject]@{
        PSTypeName = 'TPM.PostgresMutationReceipt.v1'
        SchemaVersion = 1
        ReceiptId = [guid]::NewGuid().ToString('N')
        ItemId = [string]$Item.ItemId
        Database = [string]$Item.Database
        BackupFile = [string]$Item.BackupFile
        BackupSha256 = [string]$Item.BackupSha256
        RollbackDumpPath = [string]$PreState.RollbackDumpPath
        RollbackDumpSha256 = [string]$PreState.RollbackDumpSha256
        PreStateExists = [bool]$PreState.Exists
        # A restore recreates the database with the encoding it has now, when that is known; the guess is only for an unknown one.
        Encoding = $(if ($PreState.Exists -and -not [string]::IsNullOrWhiteSpace([string](Get-TpmTransactionField -Object $PreState -Name 'OriginalEncoding' -Default ''))) { [string]$PreState.OriginalEncoding } else { [string]$Item.Encoding })
        RollbackEncoding = [string](Get-TpmTransactionField -Object $PreState -Name 'OriginalEncoding' -Default '')
        MutationAttempted = $false
        CreateOwnedForRollback = $false
        Changed = $false
        Succeeded = $false
        FailureStage = $null
        Error = $null
        PostFailureState = $null
        FinalVerification = $null
        Commands = @()
        DropReceipt = $null
        RollbackAttempted = $false
        RollbackVerified = $false
        RollbackError = $null
        RollbackCommands = @()
        RollbackDropReceipt = $null
    }
    $stage = 'MutationBoundary'
    try {
        if ($PreState.Exists) {
            $stage = 'Drop'
            $receipt.MutationAttempted = $true
            $receipt.DropReceipt = Invoke-Postgres83DropDatabaseVerified -DbName $Item.Database -SuperPasswordPlain $SuperPasswordPlain -CommandLog $commands -RequirePresent -AllowExistingDrop $true
            # A dropdb that failed on an intact database changed nothing; the post-failure state check below decides whether it did.
            if (-not $receipt.DropReceipt.Verified) {
                throw [System.InvalidOperationException]::new([string]$receipt.DropReceipt.Error)
            }
            $receipt.Changed = $true
        }
        $stage = 'Create'
        $receipt.MutationAttempted = $true
        $createCommand = Invoke-Postgres83RestoreCommandChecked -ToolName 'createdb.exe' -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-E',$receipt.Encoding,'-T','template0',$Item.Database) -SuperPasswordPlain $SuperPasswordPlain -CommandLog $commands -DatabaseName $Item.Database
        # FIX129 (N2): the restore below is judged with the REAL result of this createdb call (the Checked function throws when it fails).
        $createdbSucceeded = ($null -ne $createCommand -and [bool]$createCommand.Succeeded)
        $receipt.CreateOwnedForRollback = $true
        $afterCreate = Get-PostgresDatabaseState -DbName $Item.Database -SuperPasswordPlain $SuperPasswordPlain
        if (-not $afterCreate.Verified -or -not $afterCreate.Exists) {
            $receipt.Changed = $true
            throw 'The PostgreSQL database was not verified after creation.'
        }
        $receipt.Changed = $true
        $stage = 'DatabaseCompatibility'
        $sql = 'ALTER DATABASE "' + $Item.Database + '" SET standard_conforming_strings = on;'
        [void](Invoke-Postgres83RestoreCommandChecked -ToolName 'psql.exe' -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-d',$Item.Database,'-c',$sql) -SuperPasswordPlain $SuperPasswordPlain -CommandLog $commands -DatabaseName $Item.Database)
        $stage = 'Restore'
        [void](Invoke-Postgres83RestoreCommandChecked -ToolName 'pg_restore.exe' -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-d',$Item.Database,$Item.BackupFile) -AcceptConstraintOnlyRestoreWarnings:$AcceptConstraintOnlyRestoreWarnings -CreatedbSucceeded $createdbSucceeded -SuperPasswordPlain $SuperPasswordPlain -CommandLog $commands -DatabaseName $Item.Database)
        $stage = 'FinalVerification'
        $finalState = Get-PostgresDatabaseState -DbName $Item.Database -SuperPasswordPlain $SuperPasswordPlain
        if (-not $finalState.Verified -or -not $finalState.Exists) {
            $receipt.Changed = $true
            throw 'The restored PostgreSQL database could not be verified.'
        }
        $receipt.FinalVerification = [pscustomobject]@{ Attempted = $true; Passed = $true; Exists = $true }
        $receipt.Succeeded = $true
    } catch {
        $receipt.FailureStage = $stage
        $receipt.Error = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
        try {
            $postFailure = Get-PostgresDatabaseState -DbName $Item.Database -SuperPasswordPlain $SuperPasswordPlain
            $receipt.PostFailureState = $postFailure
            if (-not $postFailure.Verified -or [bool]$postFailure.Exists -ne [bool]$PreState.Exists) {
                $receipt.Changed = $true
            }
        } catch {
            $receipt.PostFailureState = [pscustomobject]@{ Verified = $false; Exists = $null; Error = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain) }
            $receipt.Changed = $true
        }
    }
    $receipt.Commands = @($commands.ToArray())
    return $receipt
}

function Restore-Postgres83DatabaseFromReceipt {
    param(
        [Parameter(Mandatory)]$Receipt,
        [AllowEmptyString()][string]$SuperPasswordPlain = ''
    )
    $rollbackCommands = New-Object System.Collections.Generic.List[object]
    $Receipt.RollbackAttempted = $true
    try {
        if ($Receipt.PreStateExists) {
            $dumpState = Get-TpmFileState -Path $Receipt.RollbackDumpPath
            if (-not $dumpState.Readable -or -not $dumpState.Exists -or $dumpState.IsDirectory -or $dumpState.Sha256 -ine $Receipt.RollbackDumpSha256) {
                throw 'The verified PostgreSQL rollback dump is unavailable or changed.'
            }
        }
        $Receipt.RollbackDropReceipt = Invoke-Postgres83DropDatabaseVerified -DbName $Receipt.Database -SuperPasswordPlain $SuperPasswordPlain -CommandLog $rollbackCommands -AllowExistingDrop ([bool]$Receipt.CreateOwnedForRollback)
        if (-not $Receipt.RollbackDropReceipt.Verified) {
            throw [System.InvalidOperationException]::new([string]$Receipt.RollbackDropReceipt.Error)
        }
        if ($Receipt.PreStateExists) {
            $rollbackEncoding = [string](Get-TpmTransactionField -Object $Receipt -Name 'RollbackEncoding' -Default '')
            if ([string]::IsNullOrWhiteSpace($rollbackEncoding)) {
                $rollbackEncoding = [string]$Receipt.Encoding
                Write-Log ('Postgres restore rollback: the original encoding of {0} was not recorded, so it is recreated with the encoding the restore uses.' -f $Receipt.Database)
            }
            [void](Invoke-Postgres83RestoreCommandChecked -ToolName 'createdb.exe' -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-E',$rollbackEncoding,'-T','template0',$Receipt.Database) -SuperPasswordPlain $SuperPasswordPlain -CommandLog $rollbackCommands -DatabaseName $Receipt.Database)
            $afterCreate = Get-PostgresDatabaseState -DbName $Receipt.Database -SuperPasswordPlain $SuperPasswordPlain
            if (-not $afterCreate.Verified -or -not $afterCreate.Exists) {
                throw 'The PostgreSQL database was not verified after rollback creation.'
            }
            $rollbackSql = 'ALTER DATABASE "' + $Receipt.Database + '" SET standard_conforming_strings = on;'
            [void](Invoke-Postgres83RestoreCommandChecked -ToolName 'psql.exe' -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-d',$Receipt.Database,'-c',$rollbackSql) -SuperPasswordPlain $SuperPasswordPlain -CommandLog $rollbackCommands -DatabaseName $Receipt.Database)
            [void](Invoke-Postgres83RestoreCommandChecked -ToolName 'pg_restore.exe' -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-d',$Receipt.Database,$Receipt.RollbackDumpPath) -SuperPasswordPlain $SuperPasswordPlain -CommandLog $rollbackCommands -DatabaseName $Receipt.Database)
            $afterRestore = Get-PostgresDatabaseState -DbName $Receipt.Database -SuperPasswordPlain $SuperPasswordPlain
            if (-not $afterRestore.Verified -or -not $afterRestore.Exists) {
                throw 'The original PostgreSQL database was not verified after rollback.'
            }
        }
        $Receipt.RollbackVerified = $true
    } catch {
        $Receipt.RollbackVerified = $false
        $Receipt.RollbackError = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
    }
    $Receipt.RollbackCommands = @($rollbackCommands.ToArray())
    return $Receipt
}

function New-PostgresRestoreTransactionResult {
    param(
        [Parameter(Mandatory)][string]$Outcome,
        [Parameter(Mandatory)][string]$ProductState,
        [Parameter(Mandatory)][string]$Summary,
        [object[]]$Items = @(),
        [object[]]$ChangedItems = @(),
        [object[]]$CompletedItems = @(),
        [object[]]$FailedItems = @(),
        [object[]]$UnattemptedItems = @(),
        [object[]]$SkippedItems = @(),
        [object[]]$UnknownItems = @(),
        [bool]$MutationStarted = $false,
        [bool]$MutationCompleted = $false,
        [object[]]$PreStateItems = @(),
        [bool]$PreStateCaptured = $false,
        [string]$PreStateEvidenceRoot = $null,
        [bool]$BackupAttempted = $false,
        [bool]$BackupCreated = $false,
        [bool]$BackupVerified = $false,
        [string]$BackupRootPath = $null,
        [object[]]$BackupItems = @(),
        [string]$BackupFailureStage = $null,
        [string]$BackupFailureCode = $null,
        [bool]$FinalAttempted = $false,
        [bool]$FinalPassed = $false,
        [object[]]$FinalChecks = @(),
        [object[]]$FinalFailedItems = @(),
        [object[]]$FinalUnknownItems = @(),
        [bool]$RollbackAttempted = $false,
        [bool]$RollbackCompleted = $false,
        [bool]$RollbackVerified = $false,
        [object[]]$RollbackItems = @(),
        [string]$RollbackEvidenceRoot = $null,
        [object[]]$RollbackFailedItems = @(),
        [object[]]$RollbackErrors = @(),
        [bool]$CleanupAttempted = $false,
        [bool]$CleanupCompleted = $true,
        [bool]$ResiduePresent = $false,
        [string[]]$ResiduePaths = @(),
        [object[]]$ResidueItems = @(),
        [string]$CleanupError = $null,
        [string]$UnderlyingOutcome = $null,
        [string]$ReasonCode = $null,
        [object]$TechnicalDetails = $null,
        [string[]]$Errors = @(),
        [string[]]$Warnings = @(),
        [object[]]$RecoveryActions = @(),
        [object[]]$DatabaseReceipts = @()
    )
    $mutation = [pscustomobject]@{
        Started = $MutationStarted
        Completed = $MutationCompleted
        SelectedItemCount = @($Items).Count
        AttemptedItemCount = @($CompletedItems).Count + @($FailedItems).Count + @($SkippedItems).Count
        MutatedItemCount = @($ChangedItems).Count
        AffectedItemCount = @($ChangedItems).Count
        CompletedItemCount = @($CompletedItems).Count
        FailedItemCount = @($FailedItems).Count
        UnattemptedItemCount = @($UnattemptedItems).Count
        SkippedItemCount = @($SkippedItems).Count
        UnknownItemCount = @($UnknownItems).Count
        ChangedItems = @($ChangedItems)
        AffectedItems = @($ChangedItems)
        CompletedItems = @($CompletedItems)
        FailedItems = @($FailedItems)
        UnattemptedItems = @($UnattemptedItems)
        SkippedItems = @($SkippedItems)
        UnknownItems = @($UnknownItems)
        FailureStage = Get-TpmTransactionField -Object $TechnicalDetails -Name 'Stage'
    }
    $preState = [pscustomobject]@{
        Captured = $PreStateCaptured
        CaptureMethod = 'PostgreSQLDatabaseStateAndVerifiedDump'
        CapturedUtc = (Get-Date).ToUniversalTime().ToString('o')
        Items = @($PreStateItems)
        EvidenceRoot = $PreStateEvidenceRoot
        CaptureError = Get-TpmTransactionField -Object $TechnicalDetails -Name 'PreStateError'
    }
    $backup = [pscustomobject]@{
        Required = $true
        Attempted = $BackupAttempted
        Created = $BackupCreated
        Verified = $BackupVerified
        RootPath = $BackupRootPath
        Items = @($BackupItems)
        FailureStage = $BackupFailureStage
        FailureCode = $BackupFailureCode
    }
    $final = [pscustomobject]@{
        Attempted = $FinalAttempted
        Passed = $FinalPassed
        VerifiedUtc = (Get-Date).ToUniversalTime().ToString('o')
        Checks = @($FinalChecks)
        FailedItems = @($FinalFailedItems)
        UnknownItems = @($FinalUnknownItems)
    }
    $rollback = [pscustomobject]@{
        Attempted = $RollbackAttempted
        Completed = $RollbackCompleted
        Verified = $RollbackVerified
        VerifiedUtc = if ($RollbackVerified) { (Get-Date).ToUniversalTime().ToString('o') } else { $null }
        Items = @($RollbackItems)
        EvidenceRoot = $RollbackEvidenceRoot
        FailedItems = @($RollbackFailedItems)
        Errors = @($RollbackErrors)
    }
    $cleanup = [pscustomobject]@{
        Attempted = $CleanupAttempted
        Completed = $CleanupCompleted
        ResiduePresent = $ResiduePresent
        ResiduePaths = @($ResiduePaths)
        ResidueItems = @($ResidueItems)
        Error = $CleanupError
    }
    $result = New-TpmTransactionResult `
        -WorkflowKey 'PostgresRestore' -OperationKey 'DatabaseRestore' `
        -Outcome $Outcome -UnderlyingOutcome $UnderlyingOutcome `
        -ProductState $ProductState -Summary $Summary `
        -Items @($Items) -Mutation $mutation -PreState $preState `
        -Backup $backup -FinalVerification $final -Rollback $rollback `
        -Cleanup $cleanup -ReasonCode $ReasonCode `
        -TechnicalDetails $TechnicalDetails -Errors $Errors `
        -Warnings $Warnings -RecoveryActions $RecoveryActions
    $result | Add-Member -NotePropertyName Succeeded -NotePropertyValue ($Outcome -in @('SUCCEEDED','NO_OP')) -Force
    $result | Add-Member -NotePropertyName ErrorCount -NotePropertyValue @($Errors).Count -Force
    $result | Add-Member -NotePropertyName RecoveryBlocked -NotePropertyValue ($Outcome -notin @('SUCCEEDED','NO_OP')) -Force
    $result | Add-Member -NotePropertyName DatabaseReceipts -NotePropertyValue @($DatabaseReceipts) -Force
    $result | Add-Member -NotePropertyName MutationReceipts -NotePropertyValue @($DatabaseReceipts) -Force
    return $result
}

function Invoke-PostgresRestoreTransaction {
    param(
        [Parameter(Mandatory)][object[]]$BackupFiles,
        [Parameter(Mandatory)][AllowEmptyString()][string]$SuperPasswordPlain,
        [string]$SelectedBackupRoot = '',
        [string]$EvidenceRoot = '',
        # FIX95 (S1): only the guided rebuild from a game's bundled archive sets this; a restore of the user's own
        # backups stays strict.
        [switch]$AcceptConstraintOnlyRestoreWarnings
    )
    $transactionId = [guid]::NewGuid().ToString('N')
    $technical = [ordered]@{
        TransactionId = $transactionId
        Stage = 'SelectionPreflight'
        SelectedBackupRoot = $SelectedBackupRoot
        EvidenceRoot = $null
        ToolChecks = @()
        SourceChecks = @()
        DatabaseReceipts = @()
        ReceiptPath = $null
        AcceptedRestoreLimitations = @()
        Error = $null
        PreStateError = $null
        KeptDatabaseBackups = @()
    }
    $items = @()
    $preStateRecords = New-Object System.Collections.Generic.List[object]
    $backupItems = New-Object System.Collections.Generic.List[object]
    $sourceChecks = New-Object System.Collections.Generic.List[object]
    $receipts = New-Object System.Collections.Generic.List[object]
    $changedItems = New-Object System.Collections.Generic.List[string]
    $completedItems = New-Object System.Collections.Generic.List[string]
    $failedItems = New-Object System.Collections.Generic.List[string]
    $unattemptedItems = New-Object System.Collections.Generic.List[string]
    $unknownItems = New-Object System.Collections.Generic.List[string]
    $finalChecks = New-Object System.Collections.Generic.List[string]
    $finalFailedItems = New-Object System.Collections.Generic.List[string]
    $finalUnknownItems = New-Object System.Collections.Generic.List[string]
    $rollbackItems = New-Object System.Collections.Generic.List[string]
    $rollbackFailedItems = New-Object System.Collections.Generic.List[string]
    $rollbackErrors = New-Object System.Collections.Generic.List[string]
    $commandLog = New-Object System.Collections.Generic.List[object]
    $transactionRoot = $null
    $mutationStarted = $false
    $receiptRefreshRequired = $false
    $receiptPersistenceFailed = $false
    $mutationCompleted = $false
    $preStateCaptured = $false
    $backupAttempted = $false
    $backupCreated = $false
    $backupVerified = $false
    $finalAttempted = $false
    $finalPassed = $false
    $rollbackAttempted = $false
    $rollbackCompleted = $false
    $rollbackVerified = $false
    $cleanupAttempted = $false
    $cleanupCompleted = $true
    $residuePaths = New-Object System.Collections.Generic.List[string]
    $cleanupError = $null
    $outcome = 'FAILED_BEFORE_MUTATION'
    $productState = 'UNCHANGED'
    $underlyingOutcome = $null
    $reasonCode = 'PREFLIGHT_FAILED'
    $summary = 'PostgreSQL restore stopped before changing any databases. Nothing was changed.'
    $errors = New-Object System.Collections.Generic.List[string]
    $stage = 'SelectionPreflight'
    $plan = $null
    $lockTaken = $false
    try {
        $lockTaken = [bool](Enter-PostgresRecoveryLock)
        if (-not $lockTaken) { throw [System.InvalidOperationException]::new('Another TeknoParrot Manager window is changing PostgreSQL right now. Wait for it to finish, then try again.') }
        $plan = Get-PostgresRestoreBackupPlan -BackupFiles $BackupFiles -SelectedBackupRoot $SelectedBackupRoot
        if (-not $plan.Valid) { throw [System.InvalidOperationException]::new([string]$plan.Reason) }
        $items = @($plan.Items)
        $technical.SelectedBackupRoot = $plan.SelectedBackupRoot
        $stage = 'ToolPreflight'
        $toolSet = Test-Postgres83RestoreToolSet -SuperPasswordPlain $SuperPasswordPlain
        $technical.ToolChecks = @($toolSet.Tools)
        if (-not $toolSet.Verified) { throw [System.InvalidOperationException]::new([string]$toolSet.Reason) }
        $stage = 'CredentialPreflight'
        if ([string]::IsNullOrEmpty($SuperPasswordPlain) -or -not (Test-PostgresPassword -SuperPasswordPlain $SuperPasswordPlain)) {
            throw [System.InvalidOperationException]::new('The PostgreSQL password could not be verified.')
        }
        $stage = 'SelectedBackupPreflight'
        foreach ($item in $items) {
            $sourceState = Get-TpmFileState -Path $item.BackupFile
            if (-not $sourceState.Readable -or -not $sourceState.Exists -or $sourceState.Sha256 -ine $item.BackupSha256 -or [int64]$sourceState.Length -ne [int64]$item.BackupLength) {
                throw [System.InvalidOperationException]::new("The selected PostgreSQL backup changed before restore: $($item.Database).")
            }
            $listCommand = Invoke-Postgres83RestoreCommandChecked -ToolName 'pg_restore.exe' -Arguments @('--list',$item.BackupFile) -SuperPasswordPlain $SuperPasswordPlain -CommandLog $commandLog -DatabaseName $item.Database
            [void]$sourceChecks.Add([pscustomobject]@{ Database = $item.Database; BackupFile = $item.BackupFile; Sha256 = $item.BackupSha256; Length = $item.BackupLength; ArchiveVerified = $true; ListExitCode = $listCommand.ExitCode })
        }
        $stage = 'EvidenceRoot'
        $transactionRoot = New-PostgresRestoreEvidenceRoot -EvidenceRoot $EvidenceRoot
        $technical.EvidenceRoot = $transactionRoot
        $stage = 'PreStateCapture'
        foreach ($item in $items) {
            $state = Get-PostgresDatabaseState -DbName $item.Database -SuperPasswordPlain $SuperPasswordPlain
            if (-not $state.Verified) { throw [System.InvalidOperationException]::new("The current state of PostgreSQL database $($item.Database) could not be verified.") }
            $record = [pscustomobject]@{
                ItemId = $item.ItemId
                Database = $item.Database
                Exists = [bool]$state.Exists
                Encoding = $item.Encoding
                OriginalEncoding = [string](Get-TpmTransactionField -Object $state -Name 'Encoding' -Default '')
                RollbackDumpPath = $null
                RollbackDumpLength = $null
                RollbackDumpSha256 = $null
            }
            [void]$preStateRecords.Add($record)
        }
        $preStateCaptured = $true
        $stage = 'CurrentDatabaseBackup'
        $backupAttempted = $true
        $rollbackDumpRoot = Join-Path $transactionRoot 'CurrentDatabases'
        [void][System.IO.Directory]::CreateDirectory($rollbackDumpRoot)
        foreach ($record in @($preStateRecords.ToArray() | Sort-Object @{ Expression = { $_.Database.ToUpperInvariant() } })) {
            if ($record.Exists) {
                $dumpPath = Join-Path $rollbackDumpRoot ($record.Database + '.current.backup')
                $null = Invoke-Postgres83RestoreCommandChecked -ToolName 'pg_dump.exe' -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-F','c','-f',$dumpPath,$record.Database) -SuperPasswordPlain $SuperPasswordPlain -CommandLog $commandLog -DatabaseName $record.Database
                $dumpState = Get-TpmFileState -Path $dumpPath
                if (-not $dumpState.Readable -or -not $dumpState.Exists -or $dumpState.IsDirectory -or [int64]$dumpState.Length -le 0) {
                    throw [System.InvalidOperationException]::new("The current PostgreSQL database backup could not be verified for $($record.Database).")
                }
                [void](Invoke-Postgres83RestoreCommandChecked -ToolName 'pg_restore.exe' -Arguments @('--list',$dumpPath) -SuperPasswordPlain $SuperPasswordPlain -CommandLog $commandLog -DatabaseName $record.Database)
                $record.RollbackDumpPath = $dumpPath
                $record.RollbackDumpLength = [int64]$dumpState.Length
                $record.RollbackDumpSha256 = [string]$dumpState.Sha256
                [void]$backupItems.Add([pscustomobject]@{ ItemId = $record.ItemId; Database = $record.Database; Path = $dumpPath; Length = $record.RollbackDumpLength; Sha256 = $record.RollbackDumpSha256; Kind = 'CurrentDatabaseRollbackDump' })
            } else {
                [void]$backupItems.Add([pscustomobject]@{ ItemId = $record.ItemId; Database = $record.Database; Path = $null; Length = $null; Sha256 = $null; Kind = 'VerifiedDatabaseAbsent' })
            }
        }
        $backupCreated = $true
        $backupVerified = $true
        $stage = 'MutationBoundaryRecheck'
        foreach ($record in @($preStateRecords.ToArray() | Sort-Object @{ Expression = { $_.Database.ToUpperInvariant() } })) {
            $stateNow = Get-PostgresDatabaseState -DbName $record.Database -SuperPasswordPlain $SuperPasswordPlain
            if (-not $stateNow.Verified -or [bool]$stateNow.Exists -ne [bool]$record.Exists) {
                $technical.PreStateError = "The PostgreSQL database state changed before the restore mutation boundary: $($record.Database)."
                throw [System.InvalidOperationException]::new($technical.PreStateError)
            }
        }
        foreach ($item in $items) {
            $sourceStateNow = Get-TpmFileState -Path $item.BackupFile
            if (-not $sourceStateNow.Readable -or -not $sourceStateNow.Exists -or $sourceStateNow.Sha256 -ine $item.BackupSha256 -or [int64]$sourceStateNow.Length -ne [int64]$item.BackupLength) {
                throw [System.InvalidOperationException]::new("The selected PostgreSQL backup changed at the mutation boundary: $($item.Database).")
            }
        }
        $stage = 'DatabaseMutation'
        for ($itemIndex = 0; $itemIndex -lt $items.Count; $itemIndex++) {
            $item = $items[$itemIndex]
            $pre = @($preStateRecords | Where-Object { $_.ItemId -eq $item.ItemId })[0]
            $receipt = Invoke-Postgres83RestoreDatabase -Item $item -PreState $pre -SuperPasswordPlain $SuperPasswordPlain -AcceptConstraintOnlyRestoreWarnings:$AcceptConstraintOnlyRestoreWarnings
            [void]$receipts.Add($receipt)
            if ($receipt.Changed) {
                $mutationStarted = $true
                [void]$changedItems.Add($receipt.ItemId)
            }
            if ($receipt.Succeeded) {
                [void]$completedItems.Add($receipt.ItemId)
            } else {
                [void]$failedItems.Add($receipt.ItemId)
                $stage = [string]$receipt.FailureStage
                foreach ($remaining in @($items | Select-Object -Skip ($itemIndex + 1))) {
                    [void]$unattemptedItems.Add($remaining.ItemId)
                }
                throw [System.InvalidOperationException]::new(("PostgreSQL restore failed for {0} during {1}." -f $receipt.Database,$receipt.FailureStage))
            }
            $technical.DatabaseReceipts = @($receipts.ToArray())
            $technical.ReceiptPath = Write-PostgresRestoreReceiptFile -EvidenceRoot $transactionRoot -Receipts $receipts.ToArray()
        }
        $stage = 'FinalVerification'
        $finalAttempted = $true
        foreach ($receipt in @($receipts.ToArray() | Sort-Object @{ Expression = { $_.Database.ToUpperInvariant() } })) {
            $finalState = Get-PostgresDatabaseState -DbName $receipt.Database -SuperPasswordPlain $SuperPasswordPlain
            if (-not $finalState.Verified -or -not $finalState.Exists) {
                [void]$finalFailedItems.Add($receipt.ItemId)
                throw [System.InvalidOperationException]::new("The restored PostgreSQL database could not be verified: $($receipt.Database).")
            }
            [void]$finalChecks.Add(("Verified restored database {0}." -f $receipt.Database))
        }
        $finalPassed = $true
        $mutationCompleted = $true
        $outcome = 'SUCCEEDED'
        $productState = 'INTENDED'
        $reasonCode = 'COMPLETED'
        $summary = 'PostgreSQL restore finished and was verified.'
    } catch {
        $safeError = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
        $technical.Stage = $stage
        $technical.Error = $safeError
        [void]$errors.Add($safeError)
        if ($mutationStarted) {
            $receiptRefreshRequired = $true
            $rollbackReceipts = @($receipts.ToArray() | Where-Object { $_.Changed -and ($_.PreStateExists -or $_.CreateOwnedForRollback) } | Sort-Object @{ Expression = { $_.Database.ToUpperInvariant() } } -Descending)
            foreach ($receipt in @($receipts.ToArray() | Where-Object { $_.Changed -and -not $_.PreStateExists -and -not $_.CreateOwnedForRollback })) {
                [void]$failedItems.Remove($receipt.ItemId)
                [void]$rollbackFailedItems.Add($receipt.ItemId)
                [void]$unknownItems.Add($receipt.ItemId)
                [void]$rollbackErrors.Add(("{0}: createdb did not establish rollback ownership; the observed database was not dropped." -f $receipt.Database))
            }
            if ($rollbackReceipts.Count -gt 0) {
                $rollbackAttempted = $true
                $stage = 'Rollback'
                foreach ($receipt in $rollbackReceipts) {
                    $rolled = Restore-Postgres83DatabaseFromReceipt -Receipt $receipt -SuperPasswordPlain $SuperPasswordPlain
                    if ($rolled.RollbackVerified) {
                        [void]$rollbackItems.Add($rolled.ItemId)
                    } else {
                        [void]$failedItems.Remove($rolled.ItemId)
                        [void]$completedItems.Remove($rolled.ItemId)
                        [void]$rollbackFailedItems.Add($rolled.ItemId)
                        [void]$unknownItems.Add($rolled.ItemId)
                        [void]$rollbackErrors.Add(("{0}: {1}" -f $rolled.Database,$rolled.RollbackError))
                    }
                }
            }
            $rollbackCompleted = ($rollbackErrors.Count -eq 0)
            $rollbackVerified = $rollbackCompleted
            $finalAttempted = $true
            if ($rollbackVerified) {
                $outcome = 'ROLLED_BACK_VERIFIED'
                $productState = 'UNCHANGED'
                $reasonCode = 'ROLLED_BACK_VERIFIED'
                $summary = 'The restore did not finish. Your old data was put back and checked.'
                [void]$finalChecks.Add('Every changed PostgreSQL database was restored to its captured pre-state.')
                $finalPassed = $true
            } else {
                $outcome = 'ACTION_REQUIRED'
                $productState = 'UNKNOWN'
                $reasonCode = 'ROLLBACK_UNVERIFIED'
                $summary = 'The restore did not finish, and TeknoParrot Manager could not check that your data is back as it was. Ask for help before you try again.'
                foreach ($item in @($rollbackFailedItems)) { [void]$finalUnknownItems.Add($item) }
                $finalPassed = $false
                $technical.RollbackError = $rollbackErrors.ToArray()
            }
        } else {
            $outcome = 'FAILED_BEFORE_MUTATION'
            $productState = 'UNCHANGED'
            $reasonCode = if ($plan -and $plan.FailureCode) { [string]$plan.FailureCode } elseif ($technical.PreStateError) { 'PRESTATE_CHANGED_BEFORE_MUTATION' } else { 'PREFLIGHT_FAILED' }
            $summary = 'PostgreSQL restore stopped before changing any databases. Nothing was changed.'
            $finalAttempted = $false
            $finalPassed = $false
            foreach ($item in @($items)) {
                if ($failedItems -notcontains $item.ItemId -and $unattemptedItems -notcontains $item.ItemId) { [void]$unattemptedItems.Add($item.ItemId) }
            }
        }
    } finally {
        if ($lockTaken) { Exit-PostgresRecoveryLock }
    }
    if ($transactionRoot -and $receipts.Count -gt 0 -and (-not $technical.ReceiptPath -or $receiptRefreshRequired)) {
        try {
            $technical.ReceiptPath = Write-PostgresRestoreReceiptFile -EvidenceRoot $transactionRoot -Receipts $receipts.ToArray()
        } catch {
            $receiptError = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
            $technical.ReceiptPath = $null
            $receiptPersistenceFailed = $true
            $technical.ReceiptError = $receiptError
            [void]$errors.Add($receiptError)
        }
    }
    $technical.Stage = $stage
    $technical.DatabaseReceipts = @($receipts.ToArray())
    $technical.SourceChecks = @($sourceChecks.ToArray())
    $acceptedLimitations = @(Get-PostgresAcceptedRestoreLimitations -Receipts $receipts.ToArray())
    $technical.AcceptedRestoreLimitations = $acceptedLimitations
    foreach ($limitation in $acceptedLimitations) {
        Write-Log ('Postgres restore: accepted a known limitation for database {0} (constraints: {1}): {2}' -f $limitation.Database, ($limitation.ConstraintNames -join ', '), $limitation.Message)
    }
    if ($transactionRoot) {
        $cleanupAttempted = $true
        # A good restore replaces the data in each database, so the dump of what was there before is the only copy of it. It stays in this
        # TeknoParrot Manager recovery folder. A failed or rolled-back run removes it, because the original data is back in place.
        $keptDumps = @($backupItems.ToArray() | Where-Object { $_.Kind -eq 'CurrentDatabaseRollbackDump' -and -not [string]::IsNullOrWhiteSpace([string]$_.Path) -and (Test-Path -LiteralPath ([string]$_.Path) -PathType Leaf) })
        if ($outcome -eq 'ACTION_REQUIRED' -or $receiptPersistenceFailed) {
            $cleanupCompleted = $false
            if ($receiptPersistenceFailed) { $cleanupError = [string]$technical.ReceiptError }
            [void]$residuePaths.Add($transactionRoot)
        } elseif ($outcome -eq 'SUCCEEDED' -and $keptDumps.Count -gt 0) {
            $technical.KeptDatabaseBackups = @($keptDumps | ForEach-Object { [string]$_.Path })
            Write-Log ('Postgres restore: kept the saved copy of the replaced data for {0} database(s) in {1}. TeknoParrot Manager does not delete it; the user may delete that folder.' -f $keptDumps.Count, $transactionRoot)
        } else {
            try {
                if (Test-Path -LiteralPath $transactionRoot) { Remove-Item -LiteralPath $transactionRoot -Recurse -Force -ErrorAction Stop }
            } catch {
                $cleanupCompleted = $false
                $cleanupError = ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain)
                [void]$residuePaths.Add($transactionRoot)
            }
        }
    }
    if ($residuePaths.Count -gt 0 -and $outcome -in @('SUCCEEDED','ROLLED_BACK_VERIFIED')) {
        $underlyingOutcome = $outcome
        $outcome = 'CLEANUP_RESIDUE'
        $reasonCode = 'CLEANUP_RESIDUE'
        $summary = 'The restore ended in a checked state, but some leftover files need cleaning up.'
    } elseif ($residuePaths.Count -gt 0 -and $outcome -eq 'FAILED_BEFORE_MUTATION') {
        $outcome = 'ACTION_REQUIRED'
        $productState = 'UNCHANGED'
        $reasonCode = 'PREFLIGHT_EVIDENCE_CLEANUP_FAILED'
        $summary = 'The restore did not start, and no database was changed. Some temporary files were left behind.'
    }
    # The limitation only describes the final state when the restored database is the final state (not after a rollback).
    $limitationWarnings = @(if ($outcome -eq 'SUCCEEDED' -or $underlyingOutcome -eq 'SUCCEEDED') {
        $acceptedLimitations | ForEach-Object { '{0}: {1}' -f $_.Database, $_.Message }
    })
    return (New-PostgresRestoreTransactionResult `
        -Outcome $outcome -ProductState $productState -Summary $summary `
        -Items $items -ChangedItems $changedItems.ToArray() -CompletedItems $completedItems.ToArray() `
        -FailedItems $failedItems.ToArray() -UnattemptedItems $unattemptedItems.ToArray() `
        -SkippedItems @() -UnknownItems $unknownItems.ToArray() -MutationStarted $mutationStarted `
        -MutationCompleted $mutationCompleted -PreStateItems $preStateRecords.ToArray() `
        -PreStateCaptured $preStateCaptured -PreStateEvidenceRoot $transactionRoot `
        -BackupAttempted $backupAttempted -BackupCreated $backupCreated -BackupVerified $backupVerified `
        -BackupRootPath $transactionRoot -BackupItems $backupItems.ToArray() `
        -BackupFailureStage $(if ($backupAttempted -and -not $backupVerified) { $stage } else { $null }) `
        -BackupFailureCode $(if ($backupAttempted -and -not $backupVerified) { 'CURRENT_DATABASE_BACKUP_UNVERIFIED' } else { $null }) `
        -FinalAttempted $finalAttempted -FinalPassed $finalPassed -FinalChecks $finalChecks.ToArray() `
        -FinalFailedItems $finalFailedItems.ToArray() -FinalUnknownItems $finalUnknownItems.ToArray() `
        -RollbackAttempted $rollbackAttempted -RollbackCompleted $rollbackCompleted `
        -RollbackVerified $rollbackVerified -RollbackItems $rollbackItems.ToArray() `
        -RollbackEvidenceRoot $transactionRoot -RollbackFailedItems $rollbackFailedItems.ToArray() `
        -RollbackErrors $rollbackErrors.ToArray() -CleanupAttempted $cleanupAttempted `
        -CleanupCompleted $cleanupCompleted -ResiduePresent ($residuePaths.Count -gt 0) `
        -ResiduePaths $residuePaths.ToArray() -CleanupError $cleanupError `
        -UnderlyingOutcome $underlyingOutcome -ReasonCode $reasonCode `
        -TechnicalDetails ([pscustomobject]$technical) -Errors $errors.ToArray() -Warnings $limitationWarnings `
        -RecoveryActions $(if ($outcome -eq 'ACTION_REQUIRED') {
            @(
                @{ Id = 'Review'; Label = 'Open Details and review the preserved PostgreSQL recovery evidence.' }
                @{ Id = 'Help'; Label = 'Get manual help before retrying the restore.' }
            )
        } else { @() }) -DatabaseReceipts $receipts.ToArray())
}

# PostgreSQL setup can create databases before it writes the corresponding
# UserProfile XML. If a later profile write fails, restore the absent
# pre-state for every database created by that setup pass.
function Restore-PostgresSetupCreatedDatabases {
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Databases,
        [AllowEmptyString()][string]$SuperPasswordPlain = ''
    )
    $restored = New-Object System.Collections.Generic.List[string]
    $failed = New-Object System.Collections.Generic.List[string]
    $errors = New-Object System.Collections.Generic.List[string]
    $receipts = New-Object System.Collections.Generic.List[object]
    $databaseItems = @($Databases | Sort-Object @{ Expression = { $_.DbName.ToUpperInvariant() } } -Descending)
    $started = Get-Date
    $current = 0
    foreach ($database in $databaseItems) {
        $current++
        Write-TpmCompactExtractionProgress -Phase Repairing -Label 'PostgreSQL database rollback' -Current $current -Total $databaseItems.Count -StartedAt $started
        try {
            $log = New-Object System.Collections.Generic.List[object]
            $dropReceipt = Invoke-Postgres83DropDatabaseVerified -DbName $database.DbName -SuperPasswordPlain $SuperPasswordPlain -CommandLog $log -AllowExistingDrop $true
            [void]$receipts.Add($dropReceipt)
            if (-not $dropReceipt.Verified) { throw [System.InvalidOperationException]::new([string]$dropReceipt.Error) }
            [void]$restored.Add($database.DbName)
        } catch {
            [void]$failed.Add($database.DbName)
            [void]$errors.Add(("{0}: {1}" -f $database.DbName,(ConvertTo-PostgresRedactedText -Text ([string]$_.Exception.Message) -Secrets @($SuperPasswordPlain))))
        }
    }
    if ($databaseItems.Count -gt 0) {
        Write-TpmCompactExtractionProgress -Phase Repairing -Label 'PostgreSQL database rollback' -Current $current -Total $databaseItems.Count -StartedAt $started -Complete -Outcome $(if ($failed.Count -eq 0) { 'Final' } else { 'Error' })
    }
    return [pscustomobject]@{
        Verified = ($failed.Count -eq 0)
        RestoredItems = @($restored.ToArray())
        FailedItems = @($failed.ToArray())
        Errors = @($errors.ToArray())
        DatabaseReceipts = @($receipts.ToArray())
    }
}

# FIX36B: a dated PostgreSQL backup folder whose backup did not
# finish gets this label file, so the restore menu never offers it as a normal
# backup. Its partial dump files stay as evidence.
function Get-PostgresIncompleteBackupMarkerPath {
    param([Parameter(Mandatory)][string]$BackupFolder)
    return (Join-Path $BackupFolder 'TPM-BACKUP-INCOMPLETE.txt')
}

function Backup-PostgresDatabases {
    param([string]$UserProfilesDir, [string]$SuperPasswordPlain)
    $failedDatabases = New-Object System.Collections.Generic.List[string]
    $failureDetails = New-Object System.Collections.Generic.List[string]
    $failureDiagnoses = New-Object System.Collections.Generic.List[object]
    $result = [ordered]@{
        Path = $null
        Succeeded = $true
        NoOp = $false
        ExistingDatabaseCount = 0
        FailedDatabaseCount = 0
        FailedDatabases = @()
        FailureDetails = @()
        FailureDiagnoses = @()
    }
    if (-not (Test-PostgresInstalled)) {
        $result.NoOp = $true
        return [pscustomobject]$result
    }
    $names = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
    $databaseGameMetadata = @{}
    try {
        $profileScanStarted = $null
        $profileScanCurrent = 0
        $profileScanTotal = 0
        $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'PostgreSQL backup profile discovery' -EnumerationErrorAction Stop | Sort-Object Name)
        $profileScanStarted = Get-Date
        $profileScanTotal = $profiles.Count
        $profileScanCurrent = 0
        foreach ($pf in $profiles) {
            $profileScanCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL backup profile scan' -Current $profileScanCurrent -Total $profiles.Count -StartedAt $profileScanStarted
            $dbName = ''
            $profileMetadata = Get-PostgresProfileDisplayMetadata -ProfilePath $pf.FullName
            $gameLabel = $profileMetadata.DisplayName
            try {
                $doc = Read-Xml $pf.FullName
                if (-not $doc.GameProfile -or -not (Test-GameNeedsPostgres $doc)) { continue }
                $dbName = Get-PostgresFieldValue $doc 'DbName'
                $dbNameProblem = Get-PostgresDatabaseNameProblem -DbName $dbName
                if ($dbNameProblem) {
                    [void]$failureDiagnoses.Add((New-PostgresInvalidDatabaseNameDiagnosis -GameLabel $gameLabel -ProfileKey $profileMetadata.ProfileKey -Problem $dbNameProblem))
                    [void]$failedDatabases.Add(('{0} / {1}' -f $gameLabel, $pf.BaseName))
                    [void]$failureDetails.Add(('{0} [{1}]: {2}' -f $gameLabel, $profileMetadata.ProfileKey, $dbNameProblem))
                    Write-Log ('Postgres backup: game profile {0} [{1}] cannot be used for PostgreSQL setup: {2} Nothing was changed.' -f $gameLabel, $profileMetadata.ProfileKey, $dbNameProblem)
                    continue
                }
                if ($databaseGameMetadata.ContainsKey($dbName)) {
                    if ($databaseGameMetadata.psbase.Keys -cnotcontains $dbName) { throw 'PostgreSQL database names differing only by case cannot safely share a backup filename.' }
                } else {
                    $databaseGameMetadata[$dbName] = New-Object System.Collections.Generic.List[object]
                }
                [void]$databaseGameMetadata[$dbName].Add($profileMetadata)
                $state = Get-PostgresDatabaseState -DbName $dbName -SuperPasswordPlain $SuperPasswordPlain
                if ($state.Exists) { [void]$names.Add($dbName) }
            } catch {
                $detail = [string]$_.Exception.Message
                $diagnosis = Get-PostgresFailureDiagnosis -GameLabel $gameLabel -ProfileKey $profileMetadata.ProfileKey -DbName $dbName -Detail $detail
                [void]$failureDiagnoses.Add($diagnosis)
                [void]$failedDatabases.Add(('{0} / {1}' -f $gameLabel, $dbName))
                [void]$failureDetails.Add(('{0} / {1}: {2} ({3}) Next action: {4}' -f $gameLabel, $dbName, $detail, $diagnosis.Category, $diagnosis.NextAction))
            }
        }
        if ($profiles.Count -gt 0) {
            # A profile that could not be checked leaves its database out of the backup: a partial scan is never a green close.
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL backup profile scan' -Current $profileScanCurrent -Total $profiles.Count -StartedAt $profileScanStarted -Complete -Outcome $(if ($failedDatabases.Count -eq 0) { 'Final' } else { 'Error' })
            $profileScanStarted = $null
        }
    } catch {
        # An error that ends the scan early closes the open step as failed; it never stays open or reads as done.
        if ($profileScanStarted -and $profileScanTotal -gt 0) { Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL backup profile scan' -Current $profileScanCurrent -Total $profileScanTotal -StartedAt $profileScanStarted -Complete -Outcome Error }
        [void]$failedDatabases.Add('UserProfiles enumeration')
        [void]$failureDetails.Add(('Could not enumerate game profiles: {0}' -f $_.Exception.Message))
    }

    if ($names.Count -eq 0) {
        $result.Succeeded = ($failedDatabases.Count -eq 0)
        $result.NoOp = $result.Succeeded
        $result.FailedDatabaseCount = $failedDatabases.Count
        $result.FailedDatabases = @($failedDatabases.ToArray())
        $result.FailureDetails = @($failureDetails.ToArray())
        $result.FailureDiagnoses = @($failureDiagnoses.ToArray())
        if (-not $result.Succeeded) { Write-Log ("Postgres backup incomplete. FailedDatabases={0}; FailureDetails={1}" -f ($result.FailedDatabases -join '|'), ($result.FailureDetails -join '|')) }
        return [pscustomobject]$result
    }
    if ($failedDatabases.Count -gt 0) { $result.Succeeded = $false }
    $result.ExistingDatabaseCount = $names.Count
    $backupFolderName = '{0}_{1}' -f (Get-Date).ToString('yyyy-MM-dd_HH-mm-ss_fff', [System.Globalization.CultureInfo]::InvariantCulture), [guid]::NewGuid().ToString('N')
    try {
        $result.Path = Join-Path (Join-Path (Get-TpmOwnedBackupsRoot -BackupName 'PostgresBackups') 'PostgresBackups') $backupFolderName
        Assert-TpmNoReparseWriteTarget -Path $result.Path -Operation 'PostgreSQL backup'
        [void][System.IO.Directory]::CreateDirectory($result.Path)
        # The "did not finish" label goes down FIRST and is removed only after every database is backed up, so a kill or a
        # failed label write can never leave a half-written backup that looks complete.
        [System.IO.File]::WriteAllText((Get-PostgresIncompleteBackupMarkerPath -BackupFolder $result.Path), ('This PostgreSQL backup did not finish, so TeknoParrot Manager will not restore from it.' + [Environment]::NewLine), (New-Object System.Text.UTF8Encoding $false))
    } catch {
        $result.Succeeded = $false
        [void]$failedDatabases.Add('backup folder')
        [void]$failureDetails.Add(('Could not create backup folder: {0}' -f $_.Exception.Message))
        $result.FailedDatabaseCount = $failedDatabases.Count
        $result.FailedDatabases = @($failedDatabases.ToArray())
        $result.FailureDetails = @($failureDetails.ToArray())
        $result.FailureDiagnoses = @($failureDiagnoses.ToArray())
        return [pscustomobject]$result
    }
    $pgDumpExe = Join-Path $script:PostgresBinDir 'pg_dump.exe'
    $backupNames = @($names | Sort-Object)
    if (-not (Test-Path -LiteralPath $pgDumpExe -PathType Leaf)) {
        $result.Succeeded = $false
        $databaseBackupStarted = Get-Date
        $databaseBackupCurrent = 0
        $databaseBackupCurrentDone = $false
        try {
            foreach ($dbName in $backupNames) {
                $databaseBackupCurrent++
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'PostgreSQL database backup' -Current $databaseBackupCurrent -Total $backupNames.Count -StartedAt $databaseBackupStarted
                $metadataItems = $databaseGameMetadata[$dbName]
                $label = @($metadataItems | ForEach-Object { '{0} [{1}]' -f $_.DisplayName, $_.ProfileKey }) -join ', '
                $detail = 'pg_dump.exe was not found at {0}.' -f $pgDumpExe
                foreach ($metadata in $metadataItems) {
                    $diagnosis = Get-PostgresFailureDiagnosis -GameLabel ([string]$metadata.DisplayName) -ProfileKey ([string]$metadata.ProfileKey) -DbName $dbName -Detail $detail
                    [void]$failureDiagnoses.Add($diagnosis)
                }
                [void]$failedDatabases.Add(('{0} / {1}' -f $label, $dbName))
                [void]$failureDetails.Add(('{0}: {1}' -f $dbName, $detail))
            }
            $databaseBackupCurrentDone = $true
        } finally {
            if ($backupNames.Count -gt 0) {
                Write-TpmCompactExtractionProgress -Phase Repairing -Label 'PostgreSQL database backup' -Current $(if ($databaseBackupCurrentDone) { $databaseBackupCurrent } else { $databaseBackupCurrent - 1 }) -Total $backupNames.Count -StartedAt $databaseBackupStarted -Complete -Outcome $(if ($databaseBackupCurrentDone -and $failedDatabases.Count -eq 0) { 'Final' } else { 'Error' })
            }
        }
    } else {
        try {
            $databaseBackupStarted = Get-Date
            $databaseBackupCurrent = 0
            $databaseBackupCurrentDone = $false
            try {
                foreach ($dbName in $backupNames) {
                    $databaseBackupCurrent++
                    Write-TpmCompactExtractionProgress -Phase Repairing -Label 'PostgreSQL database backup' -Current $databaseBackupCurrent -Total $backupNames.Count -StartedAt $databaseBackupStarted
                    $destFile = Join-Path $result.Path ($dbName + '.backup')
                    $dumpResult = Invoke-PostgresNativeCommand -FilePath $pgDumpExe -Arguments @('-U','postgres','-h','127.0.0.1','-p','5432','-F','c','-f',$destFile,$dbName) -Secrets @($SuperPasswordPlain) -PasswordPlain $SuperPasswordPlain
                    $dumpOutput = [string]$dumpResult.Output
                    $exitCode = [int]$dumpResult.ExitCode
                    if ($exitCode -ne 0 -or -not (Test-Path -LiteralPath $destFile -PathType Leaf) -or (Get-Item -LiteralPath $destFile).Length -eq 0) {
                        $result.Succeeded = $false
                        $metadataItems = $databaseGameMetadata[$dbName]
                        $label = @($metadataItems | ForEach-Object { '{0} [{1}]' -f $_.DisplayName, $_.ProfileKey }) -join ', '
                        $detail = if ($dumpOutput) { ConvertTo-PostgresRedactedText -Text $dumpOutput -Secrets @($SuperPasswordPlain) } else { 'pg_dump returned no diagnostic text.' }
                        foreach ($metadata in $metadataItems) {
                            $diagnosis = Get-PostgresFailureDiagnosis -GameLabel ([string]$metadata.DisplayName) -ProfileKey ([string]$metadata.ProfileKey) -DbName $dbName -Detail $detail -ExitCode $exitCode
                            [void]$failureDiagnoses.Add($diagnosis)
                        }
                        [void]$failedDatabases.Add(('{0} / {1}' -f $label, $dbName))
                        [void]$failureDetails.Add(('{0}: pg_dump exit code {1}. {2} ({3}) Next action: {4}' -f $dbName, $exitCode, $detail, $diagnosis.Category, $diagnosis.NextAction))
                    } else {
                        Write-Log "Postgres backup: verified database backup for $dbName at $($result.Path)."
                    }
                }
                $databaseBackupCurrentDone = $true
            } finally {
                if ($backupNames.Count -gt 0) {
                    Write-TpmCompactExtractionProgress -Phase Repairing -Label 'PostgreSQL database backup' -Current $(if ($databaseBackupCurrentDone) { $databaseBackupCurrent } else { $databaseBackupCurrent - 1 }) -Total $backupNames.Count -StartedAt $databaseBackupStarted -Complete -Outcome $(if ($databaseBackupCurrentDone -and $failedDatabases.Count -eq 0) { 'Final' } else { 'Error' })
                }
            }
        } catch {
            $result.Succeeded = $false
            [void]$failureDetails.Add(('Backup execution failed: {0}' -f $_.Exception.Message))
        }
    }
    $result.FailedDatabaseCount = $failedDatabases.Count
    $result.FailedDatabases = @($failedDatabases.ToArray())
    $result.FailureDetails = @($failureDetails.ToArray())
    $result.FailureDiagnoses = @($failureDiagnoses.ToArray())
    if (-not $result.Succeeded) { Write-Log ("Postgres backup incomplete. FailedDatabases={0}; FailureDetails={1}" -f ($result.FailedDatabases -join '|'), ($result.FailureDetails -join '|')) }
    if (-not $result.Succeeded -and $result.Path -and (Test-Path -LiteralPath $result.Path -PathType Container)) {
        try {
            $incompleteText = 'This PostgreSQL backup did not finish, so TeknoParrot Manager will not restore from it. Not backed up: ' + ($result.FailedDatabases -join ', ') + [Environment]::NewLine
            [System.IO.File]::WriteAllText((Get-PostgresIncompleteBackupMarkerPath -BackupFolder $result.Path), $incompleteText, (New-Object System.Text.UTF8Encoding $false))
        } catch {
            Write-Log 'Postgres backup: the incomplete-backup label could not be written.'
        }
    } elseif ($result.Path -and (Test-Path -LiteralPath $result.Path -PathType Container)) {
        try {
            Remove-Item -LiteralPath (Get-PostgresIncompleteBackupMarkerPath -BackupFolder $result.Path) -Force -ErrorAction Stop
        } catch {
            # Without removing the label the folder stays unrestorable, so this is not a finished backup.
            $result.Succeeded = $false
            [void]$failedDatabases.Add('backup label')
            [void]$failureDetails.Add(('Could not mark the backup as finished: {0}' -f $_.Exception.Message))
            $result.FailedDatabaseCount = $failedDatabases.Count
            $result.FailedDatabases = @($failedDatabases.ToArray())
            $result.FailureDetails = @($failureDetails.ToArray())
            Write-Log 'Postgres backup: the incomplete-backup label could not be removed; the backup is not counted as finished.'
        }
    }
    return [pscustomobject]$result
}

# Restores a previous Postgres database backup using the same beginner-facing
# selection and confirmation pattern as UserProfiles restore.
# Both available restore flows under the Restore backup menu use that pattern.
# Necessarily destructive to each restored database's CURRENT content --
# warned clearly before proceeding. Requires PostgreSQL to already be
# installed and running (it always will be if there's anything to
# restore).
# Interactive wrapper for the PostgreSQL 8.3 transaction engine. This layer
# shows only beginner-safe status; paths, command exits, hashes, and rollback
# receipts stay in the log or behind the explicit technical-details prompt.
function Invoke-RestorePostgresBackup {
    param([string]$BackupRoot = '')
    if (Test-PostgresManualRecoveryRequired) {
        Write-Host ('  PostgreSQL restore is stopped. ' + (Get-PostgresManualRecoveryDetail)) -ForegroundColor Red
        Write-Log ('Postgres restore: stopped. ' + (Get-PostgresManualRecoveryTechnicalDetail))
        return (New-TpmProfileTransactionResult -WorkflowKey 'PostgresRestore' -OperationKey 'DatabaseRestore' -Outcome 'ACTION_REQUIRED' -ProductState 'UNKNOWN' -Summary 'PostgreSQL restore is stopped until the authentication policy is restored manually.' -Items @('postgres-restore') -FailedItems @('postgres-restore') -MutationStarted $false -FinalPassed $false -ReasonCode 'MANUAL_RECOVERY_REQUIRED' -FinalChecks @('No database operation was attempted.'))
    }
    try {
        if (-not $PSBoundParameters.ContainsKey('BackupRoot')) {
            $BackupRoot = Join-Path (Get-TpmOwnedBackupsRoot -BackupName 'PostgresBackups') 'PostgresBackups'
        }
    } catch {
        Write-Host '  PostgreSQL restore is stopped because the backup folder could not be safely selected.' -ForegroundColor Red
        Write-Log ('Postgres restore: backup root selection failed: ' + $_.Exception.Message)
        return (New-TpmProfileTransactionResult -WorkflowKey 'PostgresRestore' -OperationKey 'DatabaseRestore' -Outcome 'FAILED_BEFORE_MUTATION' -ProductState 'UNCHANGED' -Summary 'PostgreSQL restore stopped because its backup folder could not be safely selected.' -Items @('postgres-restore') -FailedItems @('postgres-restore') -MutationStarted $false -ReasonCode 'BACKUP_ROOT_UNVERIFIED' -FinalChecks @('No database operation was attempted.'))
    }
    $backupRoot = $BackupRoot
    if (-not (Test-Path -LiteralPath $backupRoot)) {
        Write-Host "  No Postgres database backups found in: $backupRoot" -ForegroundColor Yellow
        return [pscustomobject]@{ Succeeded = $true; Cancelled = $false; NoOp = $true; Reason = 'NO_POSTGRES_BACKUPS' }
    }
    $backupFolderCandidates = New-Object System.Collections.Generic.List[object]
    $folderDiscoveryStarted = Get-Date
    $folderDiscoveryCurrent = 0
    Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL backup folder discovery' -Current $folderDiscoveryCurrent -Total 0 -StartedAt $folderDiscoveryStarted
    $folderDiscoveryCurrentCompleted = $false
    try {
        Get-ChildItem -LiteralPath $backupRoot -Directory -ErrorAction Stop | ForEach-Object {
            [void]$backupFolderCandidates.Add($_)
            $folderDiscoveryCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL backup folder discovery' -Current $folderDiscoveryCurrent -Total 0 -StartedAt $folderDiscoveryStarted
        }
        $folderDiscoveryCurrentCompleted = $true
    } catch {
        Write-Host '  The Postgres backup folder could not be read, so nothing was restored. Close any program using it and try again.' -ForegroundColor Red
        Write-Log ('Postgres restore: backup folder listing failed: ' + $_.Exception.Message)
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $false; NoOp = $false; Reason = 'POSTGRES_BACKUP_UNREADABLE' }
    } finally {
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL backup folder discovery' -Current $folderDiscoveryCurrent -Total 0 -StartedAt $folderDiscoveryStarted -Complete -Outcome $(if ($folderDiscoveryCurrentCompleted) { 'Final' } else { 'Error' })
    }
    $backups = @($backupFolderCandidates | Sort-Object @{ Expression = { $_.LastWriteTime }; Descending = $true }, @{ Expression = { $_.Name } })
    if ($backups.Count -eq 0) {
        Write-Host '  No Postgres backup folders found.' -ForegroundColor Yellow
        return [pscustomobject]@{ Succeeded = $true; Cancelled = $false; NoOp = $true; Reason = 'NO_POSTGRES_BACKUPS' }
    }
    Write-Host ''
    Write-Host '  Available Postgres database backups (most recent first):' -ForegroundColor Cyan
    $menuStarted = Get-Date
    $menuCurrent = 0
    $menuCurrentDone = $false
    try {
        for ($i = 0; $i -lt $backups.Count; $i++) {
            $menuCurrent = $i + 1
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL backup menu indexing' -Current $menuCurrent -Total $backups.Count -StartedAt $menuStarted
            $b = $backups[$i]
            $dbFileCandidates = New-Object System.Collections.Generic.List[object]
            $fileDiscoveryStarted = Get-Date
            $fileDiscoveryCurrent = 0
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL backup file-count discovery' -Current $fileDiscoveryCurrent -Total 0 -StartedAt $fileDiscoveryStarted
            $fileDiscoveryCurrentCompleted = $false
            try {
                Get-ChildItem -LiteralPath $b.FullName -Filter '*.backup' -File -ErrorAction SilentlyContinue | ForEach-Object {
                    [void]$dbFileCandidates.Add($_)
                    $fileDiscoveryCurrent++
                    Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL backup file-count discovery' -Current $fileDiscoveryCurrent -Total 0 -StartedAt $fileDiscoveryStarted
                }
                $fileDiscoveryCurrentCompleted = $true
            } finally {
                Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL backup file-count discovery' -Current $fileDiscoveryCurrent -Total 0 -StartedAt $fileDiscoveryStarted -Complete -Outcome $(if ($fileDiscoveryCurrentCompleted) { 'Final' } else { 'Error' })
            }
            $dbFiles = @($dbFileCandidates | Sort-Object BaseName, Name)
            $names = ($dbFiles | ForEach-Object { $_.BaseName }) -join ', '
            $incompleteLabel = if (Test-Path -LiteralPath (Get-PostgresIncompleteBackupMarkerPath -BackupFolder $b.FullName) -PathType Leaf) { '   [INCOMPLETE - cannot be restored]' } else { '' }
            Write-Host (('    {0,3})  {1}   ({2} database(s): {3})' -f ($i + 1), $b.Name, $dbFiles.Count, $names) + $incompleteLabel)
        }
        $menuCurrentDone = $true
    } finally {
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL backup menu indexing' -Current $(if ($menuCurrentDone) { $menuCurrent } else { $menuCurrent - 1 }) -Total $backups.Count -StartedAt $menuStarted -Complete -Outcome $(if ($menuCurrentDone) { 'Final' } else { 'Error' })
    }
    Write-Host ''
    $restoreChoices = @('B') + @((1..$backups.Count) | ForEach-Object { [string]$_ })
    $choice = Read-TpmChoice -Prompt '  Enter number to restore, or Enter to cancel' -Choices $restoreChoices -Default 'B'
    if ($choice -eq 'B') {
        Write-Host '  Restore canceled.' -ForegroundColor DarkGray
        Write-Log 'Postgres restore: canceled by user.'
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $true; NoOp = $false; Reason = 'USER_CANCELLED' }
    }
    $selected = $backups[[int]$choice - 1]
    # FIX36B: a backup that did not finish is never restored.
    if (Test-Path -LiteralPath (Get-PostgresIncompleteBackupMarkerPath -BackupFolder $selected.FullName) -PathType Leaf) {
        Write-Host '  This backup did not finish when TeknoParrot Manager made it, so it cannot be restored. Nothing was changed.' -ForegroundColor Red
        Write-Log 'Postgres restore: refused a backup folder labeled incomplete.'
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $false; NoOp = $false; Reason = 'INCOMPLETE_POSTGRES_BACKUP' }
    }
    $backupFileCandidates = New-Object System.Collections.Generic.List[object]
    $restoreSourceStarted = Get-Date
    $restoreSourceCurrent = 0
    Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL restore source discovery' -Current $restoreSourceCurrent -Total 0 -StartedAt $restoreSourceStarted
    $restoreSourceCurrentCompleted = $false
    try {
        Get-ChildItem -LiteralPath $selected.FullName -Filter '*.backup' -File -ErrorAction Stop | ForEach-Object {
            [void]$backupFileCandidates.Add($_)
            $restoreSourceCurrent++
            Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL restore source discovery' -Current $restoreSourceCurrent -Total 0 -StartedAt $restoreSourceStarted
        }
        $restoreSourceCurrentCompleted = $true
    } catch {
        Write-Host '  That backup could not be read, so nothing was restored. Close any program using it and try again.' -ForegroundColor Red
        Write-Log ('Postgres restore: backup file listing failed: ' + $_.Exception.Message)
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $false; NoOp = $false; Reason = 'POSTGRES_BACKUP_UNREADABLE' }
    } finally {
        Write-TpmCompactExtractionProgress -Phase Checking -Label 'PostgreSQL restore source discovery' -Current $restoreSourceCurrent -Total 0 -StartedAt $restoreSourceStarted -Complete -Outcome $(if ($restoreSourceCurrentCompleted) { 'Final' } else { 'Error' })
    }
    $backupFiles = @($backupFileCandidates | Sort-Object BaseName, Name)
    if ($backupFiles.Count -eq 0) {
        Write-Log 'Postgres restore: the selected backup folder contains no .backup files; the restore was stopped.'
        Write-Host '  That backup has no database files in it, so nothing was restored.' -ForegroundColor Red
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $false; NoOp = $false; Reason = 'EMPTY_POSTGRES_BACKUP' }
    }
    Write-Host ''
    Write-Host ('  Selected : {0}  ({1} database(s))' -f $selected.Name, $backupFiles.Count) -ForegroundColor Yellow
    Write-Host '  WARNING  : This will REPLACE the current content of each database' -ForegroundColor Yellow
    Write-Host '             listed above with this backup snapshot.' -ForegroundColor Yellow
    Write-Host '             TeknoParrot Manager first saves a copy of what is there now,' -ForegroundColor Yellow
    Write-Host '             and keeps that copy after a good restore.' -ForegroundColor Yellow
    $confirm = Read-HostSafe '  Type YES to confirm'
    if ([string]$confirm -notmatch '^(?i:yes)$') {
        Write-Host '  Restore canceled.' -ForegroundColor DarkGray
        Write-Log 'Postgres restore: user did not confirm.'
        return [pscustomobject]@{ Succeeded = $false; Cancelled = $true; NoOp = $false; Reason = 'USER_CANCELLED' }
    }
    $superPwPlain = $null
    $savedPwPlain = $null
    $typedPwPlain = $null
    $secure = $null
    $superPwSecure = $null
    try {
        if ((Test-PostgresInstalled) -and $postgresSuperPasswordEncrypted) {
            try {
                $secure = ConvertTo-SecureString -String $postgresSuperPasswordEncrypted
                $savedPwPlain = ConvertFrom-SecureStringPlain $secure
                if (Test-PostgresPassword -SuperPasswordPlain $savedPwPlain) { $superPwPlain = $savedPwPlain }
            } catch {
                Write-Log 'Postgres restore: saved password could not be used; prompting for a password.'
            }
        }
        if ((Test-PostgresInstalled) -and -not $superPwPlain) {
            try {
                if (Get-Command -Name Suspend-TpmProgressLine -ErrorAction SilentlyContinue) { Suspend-TpmProgressLine }
                $superPwSecure = Read-Host '  Enter your PostgreSQL database password' -AsSecureString
            } finally {
                if (Get-Command -Name Resume-TpmProgressLine -ErrorAction SilentlyContinue) { Resume-TpmProgressLine }
            }
            $typedPwPlain = ConvertFrom-SecureStringPlain $superPwSecure
            $superPwPlain = $typedPwPlain
        }
        if ($null -eq $superPwPlain) { $superPwPlain = '' }
        $transaction = Invoke-PostgresRestoreTransaction -BackupFiles $backupFiles -SelectedBackupRoot $selected.FullName -SuperPasswordPlain $superPwPlain
        Write-Log ('Postgres restore transaction: outcome={0}; reason={1}; evidence={2}' -f $transaction.Outcome,$transaction.ReasonCode,$transaction.TechnicalDetails.EvidenceRoot)
        switch ($transaction.Outcome) {
            'SUCCEEDED' {
                Write-Host '  The restore finished and was checked.' -ForegroundColor Green
                Write-PostgresKeptDatabaseBackupNotice -Paths @($transaction.TechnicalDetails.KeptDatabaseBackups)
            }
            'NO_OP' {
                Write-Host '  Nothing needed to be restored.' -ForegroundColor DarkGray
            }
            'ROLLED_BACK_VERIFIED' {
                Write-Host ('  The restore did not finish. ' + (Get-TpmPostgresDataSafetyText -Result $transaction)) -ForegroundColor Yellow
            }
            'CLEANUP_RESIDUE' {
                if ([string]$transaction.UnderlyingOutcome -eq 'ROLLED_BACK_VERIFIED') {
                    Write-Host '  The restore did not finish. Your data is back the way it was, and TeknoParrot Manager checked it. Some leftover files need cleaning up. Open View Log.' -ForegroundColor Yellow
                } else {
                    Write-Host ('  ' + (Get-TpmPostgresDataSafetyText -Result $transaction)) -ForegroundColor Yellow
                }
            }
            'ACTION_REQUIRED' {
                Write-Host ('  The restore did not finish. ' + (Get-TpmPostgresDataSafetyText -Result $transaction)) -ForegroundColor Red
            }
            default {
                Write-Host '  Restore stopped before changing any databases. Nothing was changed.' -ForegroundColor Yellow
            }
        }
        if ($transaction.Outcome -notin @('SUCCEEDED','NO_OP')) {
            $detailChoice = Read-HostSafe '  Press D for details, or Enter to continue'
            if ([string]$detailChoice -match '^(?i:d)$') {
                $detailBlocks = New-Object System.Collections.Generic.List[object]
                $resultLines = New-Object System.Collections.Generic.List[string]
                Add-TpmDetailLine -Lines $resultLines -Label 'Outcome' -Text ([string]$transaction.Outcome)
                Add-TpmDetailLine -Lines $resultLines -Label 'Reason code' -Text ([string]$transaction.ReasonCode)
                if (-not [string]::IsNullOrWhiteSpace([string]$transaction.TechnicalDetails.EvidenceRoot) -and (Test-Path -LiteralPath ([string]$transaction.TechnicalDetails.EvidenceRoot))) {
                    Add-TpmDetailLine -Lines $resultLines -Label 'Saved evidence' -Text ([string]$transaction.TechnicalDetails.EvidenceRoot)
                }
                [void]$detailBlocks.Add(@{ Heading = 'Result'; Lines = $resultLines.ToArray() })
                foreach ($receipt in @($transaction.DatabaseReceipts | Sort-Object Database)) {
                    $receiptLines = New-Object System.Collections.Generic.List[string]
                    Add-TpmDetailLine -Lines $receiptLines -Label 'Restore' -Text $(if ($receipt.Succeeded) { 'worked' } else { 'did not work' })
                    Add-TpmDetailLine -Lines $receiptLines -Label 'Undone' -Text $(if ($receipt.RollbackVerified) { 'yes, and checked' } else { 'no, or not checked' })
                    Add-TpmDetailLine -Lines $receiptLines -Label 'Stopped at' -Text ([string]$receipt.FailureStage)
                    Add-TpmDetailLine -Lines $receiptLines -Label 'Error' -Text ([string]$receipt.Error)
                    Add-TpmDetailLine -Lines $receiptLines -Label 'Undo error' -Text ([string]$receipt.RollbackError)
                    [void]$detailBlocks.Add(@{ Heading = [string]$receipt.Database; Lines = $receiptLines.ToArray(); Color = $(if ($receipt.Succeeded) { '' } else { 'Yellow' }) })
                }
                Write-Host ''
                Write-TpmText -Text 'Details' -Color Cyan -Indent 2 -MaxWidth 0
                Show-TpmDetailBlocks -Blocks $detailBlocks.ToArray()
            }
        }
        return $transaction
    } finally {
        $superPwPlain = $null
        $savedPwPlain = $null
        $typedPwPlain = $null
        $secure = $null
        $superPwSecure = $null
        [GC]::Collect()
    }
}



# =============================================================================
# THUMBNAIL DOWNLOAD  (optional, fetches game icons from GitHub)
# =============================================================================
# Downloads ProfileCode.png from the TeknoParrotUIThumbnails repository into
# <TeknoParrotRoot>\Icons\ -- the exact path TeknoParrotUI reads at startup.
# Only fetches icons that are absent; never overwrites existing files.
# Source: https://github.com/teknogods/TeknoParrotUIThumbnails
function Invoke-ThumbnailDownload {
    param([string]$userProfilesDir, [string]$tpRoot)

    if (-not (Test-Path -LiteralPath $tpRoot -PathType Container) -or
        -not (Test-TpmNoReparsePath -Path $tpRoot)) {
        Write-Host "  ERROR: TeknoParrot Manager could not verify the selected runtime folder. No icons were written. Check that it is accessible and is not a junction or shortcut, then retry." -ForegroundColor Red
        Write-Log "Thumbnails: selected TeknoParrot root failed the path-chain safety check; no Icons folder or thumbnails were written."
        return [pscustomobject]@{ Succeeded = $false; NoOp = $false; Reason = 'TP_ROOT_UNSAFE' }
    }

    $iconsDir = Join-Path $tpRoot "Icons"
    try {
        # Check the existing parent chain before CreateDirectory can follow a
        # junction and create Icons outside the selected runtime.
        [void](Assert-TpmThumbnailWriteTarget -Path $iconsDir -RuntimeRoot $tpRoot -Operation 'create thumbnail Icons directory')
    } catch {
        Write-Host "  ERROR: TeknoParrot Manager could not safely use the runtime's Icons folder. It must be a normal folder, not a junction or shortcut; no icons were written." -ForegroundColor Red
        Write-Log "Thumbnails: Icons path failed the pre-create safety check; no folder or thumbnails were written -- $_"
        return [pscustomobject]@{ Succeeded = $false; NoOp = $false; Reason = 'ICONS_DIRECTORY_UNSAFE' }
    }
    $iconsAttributes = $null
    try {
        $iconsAttributes = [System.IO.File]::GetAttributes($iconsDir)
    } catch [System.IO.FileNotFoundException] {
    } catch [System.IO.DirectoryNotFoundException] {
    } catch {
        Write-Host "  ERROR: TeknoParrot Manager could not check the runtime's Icons folder safely. No icons were written; check the folder and try again." -ForegroundColor Red
        Write-Log "Thumbnails: Icons entry inspection failed closed -- $_"
        return [pscustomobject]@{ Succeeded = $false; NoOp = $false; Reason = 'ICONS_DIRECTORY_UNSAFE' }
    }
    if ($null -ne $iconsAttributes -and
        (($iconsAttributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0 -or
         ($iconsAttributes -band [System.IO.FileAttributes]::Directory) -eq 0)) {
        Write-Host "  ERROR: TeknoParrot Manager found that the runtime's Icons entry is not a normal folder. No icons were written; check the folder and try again." -ForegroundColor Red
        Write-Log "Thumbnails: Icons entry is reparse-backed or not a directory; no thumbnails written."
        return [pscustomobject]@{ Succeeded = $false; NoOp = $false; Reason = 'ICONS_DIRECTORY_UNSAFE' }
    }
    if ($null -eq $iconsAttributes) {
        try {
            [void](Assert-TpmThumbnailWriteTarget -Path $iconsDir -RuntimeRoot $tpRoot -Operation 'create thumbnail Icons directory')
            [void][System.IO.Directory]::CreateDirectory($iconsDir)
            Write-Log "Thumbnails: created Icons folder at $iconsDir"
        } catch {
            Write-Host "  ERROR: TeknoParrot Manager could not safely create the selected runtime's Icons folder. Check that it is a normal folder, then try again." -ForegroundColor Red
            Write-Log "Thumbnails: could not safely create Icons folder -- $_"
            return [pscustomobject]@{ Succeeded = $false; NoOp = $false; Reason = 'ICONS_DIRECTORY_CREATE_FAILED' }
        }
    }
    try {
        $iconsAttributes = [System.IO.File]::GetAttributes($iconsDir)
    } catch {
        Write-Host "  ERROR: TeknoParrot Manager could not verify the runtime's Icons folder after creation. No icons were written; check the folder and try again." -ForegroundColor Red
        Write-Log "Thumbnails: Icons folder post-create inspection failed closed -- $_"
        return [pscustomobject]@{ Succeeded = $false; NoOp = $false; Reason = 'ICONS_DIRECTORY_UNSAFE' }
    }
    if (($iconsAttributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0 -or
        ($iconsAttributes -band [System.IO.FileAttributes]::Directory) -eq 0 -or
        -not (Test-TpmNoReparsePath -Path $iconsDir)) {
        Write-Host "  ERROR: TeknoParrot Manager found an unsafe runtime Icons path. No icons were written; use a normal folder, not a junction or shortcut." -ForegroundColor Red
        Write-Log "Thumbnails: Icons folder failed the post-create path-chain safety check; no thumbnails written."
        return [pscustomobject]@{ Succeeded = $false; NoOp = $false; Reason = 'ICONS_DIRECTORY_UNSAFE' }
    }

    # Load registered profiles first -- needed for custom thumbnail validation below.
    $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $userProfilesDir -ProgressLabel 'Thumbnail profile discovery' -EnumerationErrorAction SilentlyContinue)

    if ($profiles.Count -eq 0) {
        Write-Host "  No registered profiles found." -ForegroundColor DarkGray
        if (Test-Path -LiteralPath $(if($script:TpmOwnedLayout){Join-Path $script:TpmOwnedLayout.Assets 'CustomThumbnails'}else{Join-Path $PSScriptRoot "CustomThumbnails"})) {
            Write-Host "  (Custom thumbnails in CustomThumbnails\ will be processed once games are registered.)" -ForegroundColor DarkGray
        }
        Write-Log "Thumbnails: no registered profiles -- custom copy and download skipped."
        return [pscustomobject]@{ Succeeded = $true; NoOp = $true; Reason = 'NO_REGISTERED_PROFILES' }
    }

    # Build a case-insensitive lookup of all registered profile codes.
    $knownCodes = [System.Collections.Generic.HashSet[string]]::new(
        [System.StringComparer]::OrdinalIgnoreCase)
    $profileCodeStarted = Get-Date
    $profileCodeCurrent = 0
    foreach ($p in $profiles) {
        $profileCodeCurrent++
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Thumbnail profile-code index' -Current $profileCodeCurrent -Total $profiles.Count -StartedAt $profileCodeStarted
        [void]$knownCodes.Add($p.BaseName)
    }
    Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Thumbnail profile-code index' -Current $profiles.Count -Total $profiles.Count -StartedAt $profileCodeStarted -Complete

    # Copy custom thumbnails from the managed Assets\CustomThumbnails\ folder into the Icons folder.
    # Each file is validated against the registered profile codes first.
    $custCopied = 0
    $custFailed = 0
    $custFailedFiles = New-Object System.Collections.Generic.List[string]
    $customThumbDir = if($script:TpmOwnedLayout){Join-Path $script:TpmOwnedLayout.Assets 'CustomThumbnails'}else{Join-Path $PSScriptRoot "CustomThumbnails"}
    if (Test-Path -LiteralPath $customThumbDir) {
        $customFiles = @(Get-TpmDirectoryEntriesWithDiscoveryProgress -DirectoryPath $customThumbDir -ProgressLabel 'Thumbnail custom-image discovery' -Filter '*.png' -EnumerationErrorAction SilentlyContinue)
        if ($customFiles.Count -gt 0) {
            Write-Host ("  Found {0} of your own icon(s) in CustomThumbnails\." -f $customFiles.Count) -ForegroundColor Cyan
            $custSkipped = 0
            $custBadName = 0

            $customStarted = Get-Date
            $customCurrent = 0
            foreach ($cf in $customFiles) {
                $customCurrent++
                Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Thumbnail custom-image processing' -Current $customCurrent -Total $customFiles.Count -StartedAt $customStarted
                $code = [System.IO.Path]::GetFileNameWithoutExtension($cf.Name)
                if (-not $knownCodes.Contains($code)) {
                    Write-Host ("  SKIPPED: CustomThumbnails\{0}" -f $cf.Name) -ForegroundColor Yellow
                    Write-Host ("           '{0}' doesn't match any of your registered games (profile code)." -f $code) -ForegroundColor Yellow
                    Write-Host "           Check TeknoParrot-Manager-controls.txt for the exact file name" -ForegroundColor Yellow
                    Write-Host "           to use, rename this PNG to match, then run this again." -ForegroundColor Yellow
                    Write-Log "Thumbnails: custom $($cf.Name) -- no matching profile code, skipped."
                    $custBadName++
                    continue
                }
                $dest = Join-Path $iconsDir $cf.Name
                if (Test-Path -LiteralPath $dest) {
                    $custSkipped++
                } else {
                    try {
                        [void](Assert-TpmThumbnailWriteTarget -Path $dest -RuntimeRoot $tpRoot -Operation 'custom thumbnail copy')
                        [System.IO.File]::Copy($cf.FullName, $dest, $false)
                        Write-Log "Thumbnails: copied custom $($cf.Name)"
                        $custCopied++
                    } catch {
                        Write-Host "  ERROR: TeknoParrot Manager could not safely save this icon inside the selected runtime. Existing icons are never replaced; check that the runtime's Icons folder is a normal folder, then retry." -ForegroundColor Yellow
                        $custFailed++
                        [void]$custFailedFiles.Add($cf.Name)
                        Write-Log "Thumbnails: failed to safely copy custom $($cf.Name) -- $_"
                    }
                }
            }
            Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Thumbnail custom-image processing' -Current $customCurrent -Total $customFiles.Count -StartedAt $customStarted -Complete -Outcome $(if ($custFailed -eq 0) { 'Final' } else { 'Error' })
            if ($custCopied -gt 0) { Write-Host ("  Added   : {0} of your own icon(s)." -f $custCopied) -ForegroundColor Green }
            if ($custSkipped -gt 0) { Write-Host ("  Skipped : {0} -- that game already has an icon." -f $custSkipped) -ForegroundColor DarkGray }
            if ($custBadName -gt 0) { Write-Host ("  Skipped : {0} -- file name didn't match a game (see above)." -f $custBadName) -ForegroundColor Yellow }
            Write-Log ("Thumbnails: custom copied={0} skipped={1} badName={2} failed={3}" -f $custCopied, $custSkipped, $custBadName, $custFailed)
            if ($custFailed -gt 0) {
                Write-Host ("  Custom thumbnail copy failures: {0}." -f ($custFailedFiles -join ', ')) -ForegroundColor Red
            }
        }
    }

    $missing = New-Object System.Collections.Generic.List[string]
    $alreadyCount = 0
    $iconScanStarted = Get-Date
    $iconScanCurrent = 0
    foreach ($f in $profiles) {
        $iconScanCurrent++
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Thumbnail missing-icon classification' -Current $iconScanCurrent -Total $profiles.Count -StartedAt $iconScanStarted
        if (Test-Path -LiteralPath (Join-Path $iconsDir ($f.BaseName + ".png"))) {
            $alreadyCount++
        } else {
            [void]$missing.Add($f.BaseName)
        }
    }
    Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Thumbnail missing-icon classification' -Current $profiles.Count -Total $profiles.Count -StartedAt $iconScanStarted -Complete
    if ($missing.Count -eq 0) {
        Write-Host "  All registered games have an icon after custom-image processing." -ForegroundColor Green
        Write-Log ("Thumbnails: no missing icons after custom processing; copied={0} failed={1}." -f $custCopied, $custFailed)
        $customCopyReason = if ($custFailed -gt 0) { 'CUSTOM_COPY_FAILURES' } elseif ($custCopied -gt 0) { 'CUSTOM_COPY_COMPLETE' } else { 'ALL_ICONS_PRESENT' }
        return [pscustomobject]@{
            Succeeded = ($custFailed -eq 0)
            NoOp = ($custCopied -eq 0 -and $custFailed -eq 0)
            Reason = $customCopyReason
            Downloaded = 0
            AlreadyPresent = $alreadyCount
            NotAvailable = 0
            DownloadFailed = 0
            CustomCopied = $custCopied
            CustomCopyFailed = $custFailed
            Failed = $custFailed
        }
    }

    $baseUrl = "https://raw.githubusercontent.com/teknogods/TeknoParrotUIThumbnails/master/Icons/"
    $fetched  = 0
    $notAvail = 0
    $failed   = 0
    $i        = 0
    $total    = $missing.Count
    $missingNoIcon = New-Object System.Collections.Generic.List[string]
    $failedCodes = New-Object System.Collections.Generic.List[string]
    $thumbnailStarted = Get-Date
    foreach ($code in $missing) {
        $i++
        $destPath = Join-Path $iconsDir ($code + ".png")
        $url      = $baseUrl + [Uri]::EscapeDataString($code + ".png")
        $thumbnailLabel = "Thumbnail {0} [{1}/{2}]" -f $code, $i, $total
        Write-TpmCompactExtractionProgress -Phase Checking -Label $thumbnailLabel -Current $i -Total $total -StartedAt $thumbnailStarted
        $statusCode = 0
        if (Invoke-TpmDownload -DownloadUrl $url -DestinationPath $destPath -Label $thumbnailLabel -Quiet -LastStatusCode ([ref]$statusCode) -AllowedRoot $tpRoot -NoOverwrite) {
            Write-Log "Thumbnails: downloaded $code"
            $fetched++
        } elseif ($statusCode -eq 404) {
            [void]$missingNoIcon.Add($code)
            Write-Log "Thumbnails: not in repo $code"
            $notAvail++
        } else {
            [void]$failedCodes.Add($code)
            Write-Log "Thumbnails: FAILED $code"
            $failed++
        }
    }
    # A 404 (no icon in the online pack) is a normal answer; any other download/check failure fails this stage.
    Write-TpmCompactExtractionProgress -Phase Checking -Label 'Thumbnails' -Current $total -Total $total -StartedAt $thumbnailStarted -Complete -Outcome $(if ($failed -eq 0) { 'Final' } else { 'Error' })

    $thumbnailFailureCount = $failed + $custFailed
    $failSuffix = if ($thumbnailFailureCount -gt 0) { ", $failed download/check failures, $custFailed custom-copy failures" } else { "" }
    $summaryColor = if ($thumbnailFailureCount -gt 0) { 'Yellow' } else { 'Green' }
    Write-Host ("  Thumbnails: {0} downloaded, {1} already had one, {2} have no icon in the online pack{3}." -f `
        $fetched, $alreadyCount, $notAvail, $failSuffix) -ForegroundColor $summaryColor
    Write-Log "Thumbnails: fetched=$fetched alreadyPresent=$alreadyCount notAvail=$notAvail downloadFailed=$failed customCopyFailed=$custFailed"

    if ($notAvail -gt 0) {
        Write-Host ("  No icon in online pack: {0}." -f ($missingNoIcon -join ', ')) -ForegroundColor Yellow
        Write-Host "  This does not mean the games are unsupported." -ForegroundColor Yellow
        Write-Host "  Add your own PNGs under CustomThumbnails\ using the exact profile code." -ForegroundColor Yellow
        Write-Log "Thumbnails: $notAvail game(s) had no upstream icon; this is not a support check."
    }
    if ($fetched -eq 0 -and $failed -eq 0 -and $notAvail -eq $total -and $total -gt 0) {
        Write-Log "Thumbnails: all $total missing icon(s) were 404 -- likely no upstream icon for these specific games, not a download failure."
    }
    if ($failed -gt 0) {
        Write-Host ("  Thumbnail download/check failures: {0}." -f ($failedCodes -join ', ')) -ForegroundColor Red
        Write-Host "  TeknoParrot Manager could not safely finish some icon downloads or placements. Existing icons were not overwritten." -ForegroundColor Yellow
        Write-Host "  Check the connection and that the selected runtime's Icons folder is a normal folder, then retry." -ForegroundColor Yellow
    }
    $thumbnailFailureReason = if ($failed -gt 0 -and $custFailed -gt 0) { 'DOWNLOAD_AND_CUSTOM_COPY_FAILURES' } elseif ($failed -gt 0) { 'DOWNLOAD_FAILURES' } elseif ($custFailed -gt 0) { 'CUSTOM_COPY_FAILURES' } else { 'COMPLETE' }
    return [pscustomobject]@{ Succeeded = ($thumbnailFailureCount -eq 0); NoOp = $false; Reason = $thumbnailFailureReason; Downloaded = $fetched; AlreadyPresent = $alreadyCount; NotAvailable = $notAvail; DownloadFailed = $failed; CustomCopyFailed = $custFailed; Failed = $thumbnailFailureCount }
}

# The plain words around the Action Required list, in one place: the block on screen, the line before the Save window
# and the header of the saved file. Short everyday sentences; the technical detail stays behind Details and in the log.
function Get-TpmActionRequiredPlainLines {
    param([Parameter(Mandatory)][ValidateSet('Screen', 'SaveWindow', 'File')][string]$For, [string]$SavePath = '', [switch]$Preview)
    switch ($For) {
        'Screen' {
            $savedLine = if ($Preview) { 'This is only a preview, so the list was not saved. Run it for real to save the list.' } elseif ([string]::IsNullOrWhiteSpace($SavePath)) { 'If anything is left on this list at the end, it is saved as a text file, so you can come back to it.' } else { 'If anything is left on this list at the end, it is saved as a text file, so you can come back to it: {0}' -f $SavePath }
            return @(
                'What this is: a short to-do list of things the tool could not fix by itself.'
                'Why you see it: some games or files need something from you first, like a game to add by hand, a missing file, or controls to set up.'
                'What to do: read each item below, fix it, then run this step again.'
                $savedLine
                'Nothing is wrong with the tool. This is normal.'
            )
        }
        'SaveWindow' {
            return @('A window will open so you can choose where to save this list. Just press Save (or Cancel to use the usual place). It is saved either way.')
        }
        'File' {
            return @(
                ''
                'WHAT THIS LIST IS'
                'A short to-do list of things TeknoParrot Manager could not fix by itself.'
                ''
                'WHY IT EXISTS'
                'Some games or files need something from you before they will work.'
                ''
                'WHAT TO DO'
                'Read each item below, fix it, then run the same step in TeknoParrot Manager again.'
                'This file is saved so you can come back to it. Nothing is wrong with the tool.'
                ''
                'NEED HELP?'
                'In TeknoParrot Manager, choose "Create a support package" from the main menu, then send the ZIP file when you ask for help.'
                ''
                '============================================================'
            )
        }
    }
}

function New-TpmActionRequiredReportText {
    param(
        [hashtable]$ManualRegData = @{},
        [object[]]$AmbiguousPaths = @(),
        [object[]]$NotFound = @(),
        [object[]]$DesignSkippedItems = @(),
        [object]$Result,
        [object]$CompatibilityWarnings,
        [object[]]$ControlReadinessItems = @(),
        [string]$GameNotesPath = '',
        [string]$RunId = '',
        [switch]$DesignOnly,
        [string[]]$OnboardingFollowUp = @()
    )
    $unmatched = @()
    if ($Result -and $Result.PSObject.Properties['Unmatched']) { $unmatched = @($Result.Unmatched) }
    $pathTooLong = @()
    $dllMismatch = @()
    $gpuIncompatible = @()
    $biosMissing = @()
    $exeMissing = @()
    if ($CompatibilityWarnings) {
        $pathTooLong = @($CompatibilityWarnings.PathTooLong)
        $dllMismatch = @($CompatibilityWarnings.DllMismatch)
        $gpuIncompatible = @($CompatibilityWarnings.GpuIncompatible)
        $biosMissing = @($CompatibilityWarnings.BiosMissing)
        $exeMissing = @($CompatibilityWarnings.ExeMissing)
    }
    $builder = New-Object System.Text.StringBuilder
    [void]$builder.AppendLine($(if ($DesignOnly) { 'TeknoParrot Manager - Controls: One More Step' } else { 'TeknoParrot Manager - Action Required' }))
    [void]$builder.AppendLine("Generated: $((Get-Date).ToString('yyyy-MM-dd HH:mm:ss', [System.Globalization.CultureInfo]::InvariantCulture))")
    [void]$builder.AppendLine("Run ID: $(if ([string]::IsNullOrWhiteSpace($RunId)) { Get-TpmSessionRunId } else { $RunId })")
    [void]$builder.AppendLine("============================================================")
    if ($DesignOnly) {
        foreach ($plainLine in @('', 'WHAT THIS IS', 'Nothing failed. Some games were skipped on purpose, because no game of their control type has controls you set yourself yet. The next step is listed below.')) { [void]$builder.AppendLine($plainLine) }
    } else {
        foreach ($plainLine in @(Get-TpmActionRequiredPlainLines -For File)) { [void]$builder.AppendLine($plainLine) }
    }
    if (@($OnboardingFollowUp).Count -gt 0) {
        foreach ($group in @(Get-TpmActionRequiredGroups -Lines @($OnboardingFollowUp))) {
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine($group.Heading.ToUpperInvariant())
            foreach ($followUp in $group.Lines) { [void]$builder.AppendLine("  $followUp") }
        }
    }
    if ($ManualRegData.Count -gt 0) {
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("REGISTER THESE GAMES IN TEKNOPARROTUI")
        [void]$builder.AppendLine("----------------------------------------------------------")
        [void]$builder.AppendLine("Add each game yourself in TeknoParrotUI: choose the matching profile and the executable shown below.")
        foreach ($fn in ($ManualRegData.Keys | Sort-Object)) {
            $ai = $ManualRegData[$fn]
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine("  Game     : $fn")
            [void]$builder.AppendLine("  Run      : $($ai.ExeName)")
            if ($ai.Reason -eq "duplicate") {
                $claimedBy = if ($ai.ClaimedBy) { $ai.ClaimedBy } else { "another folder" }
                [void]$builder.AppendLine("  Note     : profile '$($ai.Profiles)' is already used by: $claimedBy")
                [void]$builder.AppendLine("             TeknoParrot can only point one profile at one executable -- this copy")
                [void]$builder.AppendLine("             needs its own profile, or you must choose which copy to use.")
                continue
            }
            if ($ai.BestGuess -and $ai.BestScore -ge 0.40) {
                [void]$builder.AppendLine(("  Best guess: {0}  (similarity {1})" -f $ai.BestGuess, $ai.BestScore))
            }
            if ($ai.ProfileCount -le 15) {
                [void]$builder.AppendLine("  Profiles ($($ai.ProfileCount)): $($ai.Profiles)")
            } else {
                [void]$builder.AppendLine("  Profiles : shared by $($ai.ProfileCount) games -- search by name in TeknoParrotUI")
            }
        }
    }
    if (@($AmbiguousPaths).Count -gt 0) {
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("FIX THESE GAME PATHS IN TEKNOPARROTUI")
        [void]$builder.AppendLine("----------------------------------------------------------")
        $byExe = @{}
        foreach ($r in @($AmbiguousPaths)) {
            if (-not $byExe.ContainsKey($r.Exe)) { $byExe[$r.Exe] = [System.Collections.Generic.List[string]]::new() }
            $byExe[$r.Exe].Add($r.Code)
        }
        foreach ($exePath in ($byExe.Keys | Sort-Object)) {
            $codes = ($byExe[$exePath] | Sort-Object) -join " and "
            $exeName = Get-TpmExecutableDisplayName -Name $exePath -Codes $codes
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine(("  {0} needs a corrected game folder." -f $codes))
            [void]$builder.AppendLine(("  TeknoParrot Manager could not find: {0}" -f $exeName))
            [void]$builder.AppendLine(("  Open TeknoParrotUI and point each game to the folder containing {0}." -f $exeName))
        }
    }
    if (@($NotFound).Count -gt 0) {
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("EXTRACT THESE GAMES FIRST, THEN RE-RUN REPAIR")
        [void]$builder.AppendLine("----------------------------------------------------------")
        foreach ($item in (@($NotFound) | Sort-Object Code | ForEach-Object { $_.Code })) { [void]$builder.AppendLine("  $item") }
    }
    if (@($DesignSkippedItems).Count -gt 0) {
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("CONTROLS SKIPPED BY DESIGN (informational; not a failed save)")
        [void]$builder.AppendLine("----------------------------------------------------------")
        foreach ($r in @($DesignSkippedItems | Sort-Object Family, Code)) {
            [void]$builder.AppendLine(('  {0}: {1}' -f $r.Code, (Get-TpmControlPropagationReportLine -Report $r)))
        }
    }
    if (@($unmatched).Count -gt 0) {
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("GAME FOLDERS NOT MATCHED TO A TEKNOPARROT PROFILE (not registered)")
        [void]$builder.AppendLine("Make sure TeknoParrot is up to date and TeknoParrotUI has been opened once (TPM does not update or open it), then run Register only again.")
        [void]$builder.AppendLine("If they still do not match, they may be games TeknoParrot does not support yet, utilities/launchers, or games whose main file is named differently from what TeknoParrot expects.")
        [void]$builder.AppendLine("If you are sure TeknoParrot supports a game, add it in TeknoParrotUI yourself.")
        [void]$builder.AppendLine("----------------------------------------------------------")
        foreach ($folder in ($unmatched | Sort-Object)) { [void]$builder.AppendLine("  $folder") }
    }
    if (@($pathTooLong).Count -gt 0) {
        [void]$builder.AppendLine("These games may fail to launch because their folder paths are too long.")
        [void]$builder.AppendLine("TeknoParrot Manager cannot safely rename folders and update profiles automatically here.")
        [void]$builder.AppendLine("Manual safe repair: back up each UserProfile XML, close TeknoParrotUI,")
        [void]$builder.AppendLine("rename the game folder to the suggested short name and shorten parent folders if needed,")
        [void]$builder.AppendLine("update the saved GamePath in TeknoParrotUI, then run the script again, answer Y to the path repair question and test the game.")
        foreach ($w in ($pathTooLong | Sort-Object Code)) {
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine("  Game        : $($w.Code)")
            [void]$builder.AppendLine("  Current path: $($w.Length) characters (limit ~$($w.Limit))")
            [void]$builder.AppendLine("  Rename to   : $($w.Suggested)")
        }
    }
    if (@($dllMismatch).Count -gt 0) {
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("FILE VERSION MISMATCH -- THESE GAMES NEED A SPECIFIC OLDER FILE")
        [void]$builder.AppendLine("----------------------------------------------------------")
        [void]$builder.AppendLine("How to fix: join the TeknoParrot Discord (linked from teknoparrot.com),")
        [void]$builder.AppendLine("ask in #fixes for the file named below matching the required CRC32, and")
        [void]$builder.AppendLine("replace that file in the game's own folder. Do NOT let TeknoParrot")
        [void]$builder.AppendLine("redeploy its current copy here -- that makes it worse, not better.")
        foreach ($w in ($dllMismatch | Sort-Object Code)) {
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine("  Game           : $($w.Code)")
            [void]$builder.AppendLine("  File           : $($w.FileName)")
            [void]$builder.AppendLine("  Current CRC32  : $($w.Found)")
            [void]$builder.AppendLine("  Required CRC32 : $($w.Required)")
        }
    }
    if (@($gpuIncompatible).Count -gt 0) {
        $vendor = $gpuIncompatible[0].Vendor
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("KNOWN $($vendor.ToUpperInvariant()) GPU INCOMPATIBILITY -- NO FIX AVAILABLE (informational)")
        [void]$builder.AppendLine("----------------------------------------------------------")
        [void]$builder.AppendLine("These games are confirmed not to work on $vendor GPUs. Known")
        [void]$builder.AppendLine("limitation, not a setup mistake -- there is no fix to apply.")
        foreach ($w in ($gpuIncompatible | Sort-Object Code)) { [void]$builder.AppendLine("  $($w.Code)") }
    }
    if (@($biosMissing).Count -gt 0) {
        foreach ($b in $biosMissing) {
            $biosScreen = Get-TpmPrerequisiteScreenLines -Warning $b
            [void]$builder.AppendLine(""); [void]$builder.AppendLine("$($b.EmulatorType.ToUpperInvariant()) FIRMWARE NOT INSTALLED")
            [void]$builder.AppendLine("----------------------------------------------------------")
            foreach ($biosLine in @($biosScreen.Plain)) { [void]$builder.AppendLine($biosLine) }
            [void]$builder.AppendLine("Details:")
            foreach ($biosLine in @($biosScreen.Details)) { [void]$builder.AppendLine("  $biosLine") }
        }
    }
    if (@($exeMissing).Count -gt 0) {
        foreach ($e in $exeMissing) {
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine("$($e.EmulatorType.ToUpperInvariant()) EMULATOR COMPONENT NOT FOUND")
            [void]$builder.AppendLine("----------------------------------------------------------")
            [void]$builder.AppendLine("A registered game uses this emulator, but the component declared")
            [void]$builder.AppendLine("by its ECVF contract was not found at the expected path below.")
            [void]$builder.AppendLine("TeknoParrot Manager only checked the contract-declared path; it did not determine why")
            [void]$builder.AppendLine("the file is missing.")
            [void]$builder.AppendLine("  Contract : $($e.ContractId) ($($e.ContractStatus))")
            [void]$builder.AppendLine("  Detector : $($e.DetectorMethod) / $($e.DetectorSource)")
            [void]$builder.AppendLine("  Evidence : contract-backed; confidence $($e.Confidence)")
            [void]$builder.AppendLine("  Expected : $($e.ExpectedPath)")
            [void]$builder.AppendLine("  Affected : $($e.AffectedGames -join ', ')")
            [void]$builder.AppendLine("  Action   : Use TeknoParrotUI's own update/repair screen, then review this")
            [void]$builder.AppendLine("             health check again. TeknoParrot Manager does not replace emulator files.")
        }
    }
    if (@($ControlReadinessItems).Count -gt 0) {
        foreach ($item in @($ControlReadinessItems)) {
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine("CONTROLS NOT READY : $($item.Code)")
            [void]$builder.AppendLine("----------------------------------------------------------")
            [void]$builder.AppendLine("Registration, launch success, and TeknoParrot wizard completion")
            [void]$builder.AppendLine("are reported separately and do not prove that controls work.")
            foreach ($line in $item.SummaryLines) { [void]$builder.AppendLine([string]$line) }
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($GameNotesPath)) {
        [void]$builder.AppendLine("")
        [void]$builder.AppendLine("Additional informational game notes were written separately to:")
        [void]$builder.AppendLine(("  {0}" -f $GameNotesPath))
    }
    return $builder.ToString()
}
function Write-TpmActionRequiredReport {
    param(
        [string]$ActionPath,
        [hashtable]$ManualRegData = @{},
        [object[]]$AmbiguousPaths = @(),
        [object[]]$NotFound = @(),
        [object[]]$DesignSkippedItems = @(),
        [object]$Result,
        [object]$CompatibilityWarnings,
        [object[]]$ControlReadinessItems = @(),
        [string]$GameNotesPath = '',
        [string]$RunId = '',
        [switch]$Quiet,
        [switch]$DesignOnly,
        [string[]]$OnboardingFollowUp = @()
    )
    try {
        $text = New-TpmActionRequiredReportText -ManualRegData $ManualRegData -AmbiguousPaths $AmbiguousPaths -NotFound $NotFound -DesignSkippedItems $DesignSkippedItems -Result $Result -CompatibilityWarnings $CompatibilityWarnings -ControlReadinessItems $ControlReadinessItems -GameNotesPath $GameNotesPath -RunId $RunId -OnboardingFollowUp $OnboardingFollowUp -DesignOnly:$DesignOnly
        # Same-folder unique temp + flush + replace: a failed or interrupted write leaves the previous report intact.
        Write-TpmAtomicTextFile -Path $ActionPath -Text $text -Operation 'ACTION REQUIRED report write'
        if (-not $Quiet) {
            Write-Host ""
            Write-Host $(if ($DesignOnly) { '  Notes saved to:' } else { '  Action items saved to:' }) -ForegroundColor Green
            Write-Host "  $ActionPath" -ForegroundColor Cyan
            Write-Host $(if ($DesignOnly) { '  Nothing failed. Open that file if you want to read the notes.' } else { '  Open that file to review everything you need to do manually.' }) -ForegroundColor DarkCyan
            Write-Log "Action items written to $ActionPath"
        }
        return $true
    } catch {
        Write-Log "Action items: could not write file -- $_"
        if (-not $Quiet) {
            Write-Host ''
            Write-Host '  The to-do list could not be saved, so it is not in a file.' -ForegroundColor Yellow
            Write-Host "  Wanted to save it here: $ActionPath" -ForegroundColor Yellow
            Write-Host '  Run again and pick a folder you can save to, or write the list down from this screen.' -ForegroundColor Yellow
        }
        return $false
    }
}

# =============================================================================
# END-OF-RUN RECAP, NEXT STEPS AND OPTIONAL FOLLOW-UP QUESTIONS  (FIX80)
# =============================================================================
# Default view = a few short plain lines. Counts, paths and the scope reminder are the Details view
# (Write-TpmOutcome, D) and are always in the log. Nothing here decides what the run does: every input
# is a value the run already had.

# The recap after registration: a title, up to three short facts, the items that need attention (only when there
# are some) and the Details blocks. Returns @{ Title; Status; Done; Needs; DetailBlocks }.
function Get-TpmRegistrationRecap {
    param(
        [bool]$AutoSyncRan,
        [int]$ZipsExtracted = 0,
        [int]$NewlyRegistered = 0,
        [int]$AlreadyPresent = 0,
        [ValidateSet('Downloaded', 'Updated', 'Reused', 'NotConfigured')]
        [string]$DatAction = 'NotConfigured',
        [bool]$ThumbnailsRequested,
        [bool]$ThumbnailsFailed = $false,
        [int]$ManualNeeded = 0,
        [int]$ExtractionProblems = 0,
        [string[]]$RunProblems = @(),
        [int]$NotInTeknoParrot = 0,
        [int]$ControlsNeedAttention = 0,
        [bool]$Preview = $false,
        [bool]$ControlsStatusFailed = $false,
        [string]$BackupPath = '',
        [string]$LogPath = '',
        [string]$ControlsStatusPath = ''
    )
    $title = if ($Preview) {
        if ($NewlyRegistered -gt 0) { ('Preview: {0} would be registered.' -f (Format-TpmGameCount -Count $NewlyRegistered)) } else { 'Preview: no new games would be registered.' }
    } else {
        if ($NewlyRegistered -gt 0) { ('Registered {0}.' -f (Format-TpmGameCount -Count $NewlyRegistered)) } else { 'No new games were registered.' }
    }
    $done = New-Object System.Collections.Generic.List[string]
    if ($AutoSyncRan) { [void]$done.Add(('{0} unpacked.' -f (Format-TpmCountNoun -Count $ZipsExtracted -Singular 'ZIP file'))) }
    if ($AlreadyPresent -gt 0) { [void]$done.Add(('{0} {1} already set up.' -f (Format-TpmGameCount -Count $AlreadyPresent), $(if ($AlreadyPresent -eq 1) { 'was' } else { 'were' }))) }
    if (-not $Preview -and $BackupPath) { [void]$done.Add('A saved copy was made first.') }
    $needs = New-Object System.Collections.Generic.List[string]
    if ($ExtractionProblems -gt 0) { [void]$needs.Add(('{0} could not be unpacked, so those games are not set up. The log has the reason.' -f (Format-TpmCountNoun -Count $ExtractionProblems -Singular 'ZIP file'))) }
    foreach ($runProblem in $RunProblems) { [void]$needs.Add($runProblem) }
    if ($ManualNeeded -gt 0) { [void]$needs.Add(('{0} {1} to be added by hand in TeknoParrotUI.' -f (Format-TpmGameCount -Count $ManualNeeded), $(if ($ManualNeeded -eq 1) { 'needs' } else { 'need' }))) }
    if ($NotInTeknoParrot -gt 0) { [void]$needs.Add($(if ($NotInTeknoParrot -eq 1) { '1 game folder was not recognized by TeknoParrot.' } else { ('{0} game folders were not recognized by TeknoParrot.' -f $NotInTeknoParrot) })) }
    if ($ControlsNeedAttention -gt 0) { [void]$needs.Add(('{0} still {1} set up.' -f (Format-TpmGameCount -Count $ControlsNeedAttention), $(if ($ControlsNeedAttention -eq 1) { 'needs its controls' } else { 'need their controls' }))) }
    $listedBelow = $needs.Count
    if ($ControlsStatusFailed) { [void]$needs.Add('The controls status file could not be saved. The log has the reason.') }

    $didLines = New-Object System.Collections.Generic.List[string]
    if ($AutoSyncRan) { [void]$didLines.Add(('Unpacked: {0} from your source folder into the staging folder.' -f (Format-TpmCountNoun -Count $ZipsExtracted -Singular 'ZIP file'))) }
    if ($Preview) {
        [void]$didLines.Add(('Would register: {0} (nothing was changed).' -f (Format-TpmGameCount -Count $NewlyRegistered)))
    } else {
        [void]$didLines.Add(('Registered: {0} read back after saving.' -f (Format-TpmGameCount -Count $NewlyRegistered)))
    }
    [void]$didLines.Add(('Already set up: {0} existing game file(s) found. Their presence does not confirm the selected new games.' -f $AlreadyPresent))
    [void]$didLines.Add($(switch ($DatAction) {
        'Downloaded' { "Game list (DAT): Downloaded Eggman's TeknoParrot DAT file (an index used to match games -- not a game download)." }
        'Updated'    { "Game list (DAT): Updated Eggman's TeknoParrot DAT file to the latest release." }
        'Reused'     { "Game list (DAT): Reused an already-present Eggman's TeknoParrot DAT file (no download this run)." }
        default      { "Game list (DAT): No Eggman's TeknoParrot DAT file configured -- some games may need manual registration." }
    }))
    if (-not $Preview) {
        [void]$didLines.Add($(if ($ThumbnailsRequested -and $ThumbnailsFailed) { 'Game pictures: Some game icons could not be downloaded. The log has the reason.' } elseif ($ThumbnailsRequested) { 'Game pictures: Downloaded missing game icons (small box-art images, not game data).' } else { 'Game pictures: Skipped game icon download.' }))
    }
    $blocks = New-Object System.Collections.Generic.List[object]
    [void]$blocks.Add(@{ Heading = 'What TeknoParrot Manager did'; Lines = $didLines.ToArray() })
    if ($listedBelow -gt 0) { [void]$blocks.Add(@{ Heading = 'Items that need attention'; Lines = @('More: The full list is under ACTION REQUIRED below.') }) }
    [void]$blocks.Add(@{ Heading = 'Good to know'; Lines = @(
        'Scope: TeknoParrot Manager organizes, extracts, registers, and exports your games.',
        'It does not provide games, install TeknoParrot itself, or guarantee that a game will boot or run fullscreen.',
        'If a game crashes or opens in a window, that is usually a TeknoParrot, game, or runtime setting. TeknoParrot Manager changed it only if this run said so.',
        'Counts: This recap does not verify registration failures or later optional steps. Read their own results and ACTION REQUIRED.'
    ) })
    $whereLines = New-Object System.Collections.Generic.List[string]
    if (-not $Preview -and $BackupPath) { [void]$whereLines.Add(('Saved copy: {0}' -f $BackupPath)) }
    if ($LogPath) { [void]$whereLines.Add(('Log: {0}' -f $LogPath)) }
    if (-not $Preview -and $ControlsStatusPath) { [void]$whereLines.Add(('Controls file: {0}' -f $ControlsStatusPath)) }
    if ($whereLines.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Where things are saved'; Lines = $whereLines.ToArray() }) }
    return [pscustomobject]@{
        Title = $title
        Status = $(if ($needs.Count -gt 0) { 'Attention' } else { 'Ok' })
        Done = $done.ToArray()
        Needs = $needs.ToArray()
        DetailBlocks = $blocks.ToArray()
    }
}

# The last screen of a registration run: one short Next line. The long list, and the hints for the optional
# steps that were set up, are the Details view. Step 2 is only mentioned when ACTION REQUIRED has items.
function Get-TpmRegistrationNextSteps {
    param([bool]$HasActionRequired, [bool]$ReShadeDone, [bool]$DgVoodoo2Done, [string]$CrosshairsFolder = '')
    $next = 'Open TeknoParrotUI and check that your games appear.'
    $next += $(if ($HasActionRequired) { ' Then fix the items under ACTION REQUIRED above.' } else { ' Then try one game.' })
    $stepLines = New-Object System.Collections.Generic.List[string]
    [void]$stepLines.Add('Step 1: Open TeknoParrotUi.exe and confirm the expected games appear. Extraction alone is not registration; review ACTION REQUIRED before treating games or controls as ready.')
    $stepNumber = 2
    if ($HasActionRequired) { [void]$stepLines.Add(('Step {0}: Work through the ACTION REQUIRED items above.' -f $stepNumber)); $stepNumber++ }
    [void]$stepLines.Add(('Step {0}: Bind one game of each control type, then re-run and propagate.' -f $stepNumber)); $stepNumber++
    [void]$stepLines.Add(('Step {0}: Test one propagated game before trusting the rest.' -f $stepNumber))
    $blocks = New-Object System.Collections.Generic.List[object]
    [void]$blocks.Add(@{ Heading = 'All the next steps'; Lines = $stepLines.ToArray() })
    if ($ReShadeDone) {
        [void]$blocks.Add(@{ Heading = 'ReShade'; Lines = @(
            'Launch: any game that had ReShade installed.',
            'Overlay: Press the Home key to open the effects overlay.',
            'Effects: Tick the effects you want and adjust with the sliders.',
            'Saved: Settings save automatically -- you only need to do this once per game.',
            'Note: TeknoParrot Manager does not remove unowned ReShade hooks automatically. If you want them gone, remove those files by hand.'
        ) })
    }
    if ($DgVoodoo2Done) {
        [void]$blocks.Add(@{ Heading = 'dgVoodoo2'; Lines = @(
            'Test: Launch each game that had dgVoodoo2 installed and test it.',
            'If a game crashes: If a game now crashes that worked before, do not delete DLLs blindly. Remove only DLLs confirmed as added by this setup.',
            'Other files: Existing files and any replaced dgVoodoo.conf need separate recovery review.',
            'Game file: The game executable is unchanged. Create a support package with the log.'
        ) })
    }
    $crosshairLines = New-Object System.Collections.Generic.List[string]
    if ($CrosshairsFolder) { [void]$crosshairLines.Add(('Folder: Custom crosshair images are in {0}' -f $CrosshairsFolder)) }
    [void]$crosshairLines.Add('Add your own: You can add your own PNG images to that folder at any time.')
    [void]$crosshairLines.Add('Deploy: Run mode 4 (Crosshair setup) to preview and deploy them to lightgun games.')
    [void]$blocks.Add(@{ Heading = 'Crosshairs'; Lines = $crosshairLines.ToArray() })
    return [pscustomobject]@{ Next = $next; DetailBlocks = $blocks.ToArray() }
}

# Short name of an optional follow-up step, for its question and for the "not offered" line.
function Get-TpmOptionalStepName {
    param([Parameter(Mandatory)][ValidateSet('ReShade', 'DgVoodoo2', 'GpuFix')][string]$Step)
    switch ($Step) {
        'ReShade'   { return 'ReShade visuals' }
        'DgVoodoo2' { return 'dgVoodoo2 for old games' }
        default     { return 'graphics card fixes' }
    }
}

# What an optional follow-up step is: the text the old full-page panels held, as short labeled blocks.
function Get-TpmOptionalStepHelpBlocks {
    param([Parameter(Mandatory)][ValidateSet('ReShade', 'DgVoodoo2', 'GpuFix')][string]$Step)
    switch ($Step) {
        'ReShade' {
            return @(
                @{ Heading = 'What ReShade is'; Lines = @('ReShade is a free tool that can make your arcade games look better on modern screens.', 'It works by applying real-time visual effects on top of the game.') },
                @{ Heading = 'What setup changes'; Lines = @('Setup adds ReShade files (a DLL, ReShade.ini and effect files) to each game folder you choose.', 'Files already there are not replaced unless you approve it.') },
                @{ Heading = 'Popular effects'; Lines = @('Sharpening: removes the blurry look of upscaled games', 'CRT scanlines: makes games look like an authentic arcade monitor', 'Color boost: makes older games more vivid and punchy', 'Borders: adds decorative bezel artwork around the game') },
                @{ Heading = 'Good to know'; Lines = @('ReShade is optional -- games do not need it to run.', 'To remove it later, use ReShade setup again. It removes only the files TeknoParrot Manager added.', 'In the game, press Home to open the ReShade overlay and pick effects.', 'Later: You can turn this on later from the main menu''s ReShade setup option, which can also download ReShade for you automatically.') }
            )
        }
        'DgVoodoo2' {
            return @(
                @{ Heading = 'What dgVoodoo2 is'; Lines = @('Some older arcade games use DirectX 8, DirectDraw, or the Glide API from 3dfx.', 'On modern PCs these can cause crashes, black screens, or missing graphics.', 'dgVoodoo2 is a free compatibility layer that translates those old graphics calls into modern DirectX 11/12.') },
                @{ Heading = 'What setup changes'; Lines = @('It works by placing small DLL files in the game folder; it may also add or replace dgVoodoo.conf.', 'The game executable itself is not modified.') },
                @{ Heading = 'Good to know'; Lines = @('Only run this for games that crash or show black screens on first launch. Games that run fine do not need it.', 'Later: You can turn this on later from the main menu''s dgVoodoo2 setup option, which can also download dgVoodoo2 for you automatically.') }
            )
        }
        default {
            return @(
                @{ Heading = 'What the graphics card fixes are'; Lines = @('Some games include settings that fix graphical issues specific to AMD, NVIDIA, or Intel graphics cards.', 'This step auto-detects your GPU and applies the right fix to every registered game that has one.') },
                @{ Heading = 'Good to know'; Lines = @('Safe to run any time -- re-run if you change or update your GPU.') }
            )
        }
    }
}

# The one-line question for an optional follow-up step. Y and N keep their meaning; D shows what the step is and
# asks again. Returns 'Y' or 'N'.
function Read-TpmOptionalStepChoice {
    param([Parameter(Mandatory)][ValidateSet('ReShade', 'DgVoodoo2', 'GpuFix')][string]$Step, [string]$Default = 'N', [switch]$AllowBack)
    $helpBlocks = Get-TpmOptionalStepHelpBlocks -Step $Step
    $verb = if ($Step -eq 'GpuFix') { 'Apply now?' } else { 'Set up now?' }
    $defaultText = if ($Default) { (', default {0}' -f $Default) } else { '' }
    Write-Host ''
    if ($AllowBack) {
        # B goes back to the step before this one, so a step that was skipped by accident can be done after all. Returns 'Y', 'N' or 'B'.
        $backPrompt = 'Optional: {0}. {1} (Y/N, B = go back one step, D = what is this{2})' -f (Get-TpmOptionalStepName -Step $Step), $verb, $defaultText
        while ($true) {
            $backAnswer = ([string](Read-HostSafe $backPrompt -Default $Default)).Trim().ToUpperInvariant()
            if ($backAnswer -eq 'D') { Show-TpmDetailBlocks -Blocks $helpBlocks; continue }
            if ($backAnswer -in @('Y', 'N', 'B')) { return $backAnswer }
            Write-Host '  Please choose Y, N or B.' -ForegroundColor Yellow
        }
    }
    return (Read-TpmYesNo -Prompt ('Optional: {0}. {1} (Y/N, D = what is this{2})' -f (Get-TpmOptionalStepName -Step $Step), $verb, $defaultText) -Default $Default -DetailsAction { Show-TpmDetailBlocks -Blocks $helpBlocks })
}

# Said instead of the question when an earlier step did not finish.
function Write-TpmOptionalStepBlocked {
    param([Parameter(Mandatory)][ValidateSet('ReShade', 'DgVoodoo2', 'GpuFix')][string]$Step)
    Write-TpmText -Text ('Not offered: {0}. Crosshair setup did not finish. Fix that first.' -f (Get-TpmOptionalStepName -Step $Step)) -Color Yellow -BlankBefore
}

# The game pictures question: one sentence before the Y/N, the "use your own pictures" tip is the D view.
function Get-TpmThumbnailHelpBlocks {
    $customThumbDir = if ($script:TpmOwnedLayout) { Join-Path $script:TpmOwnedLayout.Assets 'CustomThumbnails' } else { Join-Path $PSScriptRoot 'CustomThumbnails' }
    return @(
        @{ Heading = 'What this does'; Lines = @('This downloads small box-art icons only, never the games themselves -- it just gives each registered game a picture in TeknoParrot''s game list.') },
        @{ Heading = 'Use your own pictures instead'; Lines = @(
            ('Step 1: Open this folder (make it if it is missing): {0}' -f $customThumbDir),
            'Step 2: Put PNG images in it. Name each PNG the same as that game''s file in the UserProfiles\ folder (called the profile code), but ending in .png instead of .xml.',
            'Not sure: TeknoParrot-Manager-controls.txt lists every game''s file name.'
        ) }
    )
}

# =============================================================================
# CONTROLS STATUS REPORT
# =============================================================================
# Writes a snapshot of every registered game's control state to a persistent
# text file. Groups by control family, shows propagation source and any
# buttons still left manual. Overwrites the previous file on every call --
# it is a current-state view, not an append log.
# Returns the number of games written, or -1 on write failure.
function Write-ControlsStatus {
    param([string]$userProfilesDir, $pool, $propagationReports, [string]$outputPath, [string]$RunId = '')
    $effectiveRunId = if ([string]::IsNullOrWhiteSpace($RunId)) { Get-TpmSessionRunId } else { $RunId }

    $poolCodes = @{}
    if ($null -ne $pool) { foreach ($s in $pool) { $poolCodes[$s.Code] = $true } }

    $reportMap = @{}
    if ($null -ne $propagationReports) {
        foreach ($r in $propagationReports) { $reportMap[$r.Code] = $r }
    }

    $files = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $userProfilesDir -ProgressLabel 'Controls status profile discovery' -EnumerationErrorAction SilentlyContinue | Sort-Object BaseName)

    $rows = New-Object System.Collections.ArrayList
    $profileIndex = 0
    $profileTotal = $files.Count
    $scanStarted = Get-Date
    foreach ($f in $files) {
        $profileIndex++
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Controls status profile scan' -Current $profileIndex -Total $profileTotal -StartedAt $scanStarted
        try { $doc = Read-Xml $f.FullName } catch { Write-Log "Write-ControlsStatus: could not parse $($f.Name) -- $_"; continue }
        if ($null -eq $doc.GameProfile) { continue }

        $family = Get-ProfileFamily $doc
        $btns   = @(Get-ButtonNodes $doc)
        $bound  = 0
        $manual = New-Object System.Collections.ArrayList
        foreach ($b in $btns) {
            if (Test-ButtonIsBound $b) {
                $bound++
            } else {
                $n = $b.SelectSingleNode("ButtonName")
                if ($n -and -not [string]::IsNullOrWhiteSpace($n.InnerText)) {
                    [void]$manual.Add($n.InnerText.Trim())
                }
            }
        }

        $status = ""; $reference = ""
        if ($poolCodes.ContainsKey($f.BaseName)) {
            $status = "REFERENCE"
            if ($reportMap.ContainsKey($f.BaseName) -and $reportMap[$f.BaseName].Status -eq "api-fixed-canonical") {
                $r = $reportMap[$f.BaseName]
                $status = "REFERENCE (Input API corrected)"; $reference = $r.Archetype
            }
        }
        elseif ($reportMap.ContainsKey($f.BaseName)) {
            $r = $reportMap[$f.BaseName]
            switch ($r.Status) {
                "bound"            {
                    if ([int]$r.Bound -gt 0) { $status = "propagated"; $reference = $r.Archetype }
                    else { $status = "settings carried only (manual controls required)"; $reference = $r.Archetype }
                }
                "api-fixed"        { $status = "already bound (Input API corrected)"; $reference = $r.Archetype }
                "skipped-bound"    { $status = "already bound" }
                "skipped-override" { $status = "skipped (override)" }
                "skipped-unchanged" { $status = "unchanged"; $reference = $r.Archetype }
                "skipped-no-reference" { $status = Get-TpmControlPropagationReportLine -Report $r }
                "save-failed"      { $status = "save failed" }
                "unreadable"       { $status = "could not be read" }
                default            { $status = $r.Status }
            }
        }
        elseif ($bound -ge 5) { $status = "bound" }
        elseif ($bound -gt 0) { $status = "partial" }
        else                  { $status = "no controls" }

        # If the propagation run flagged directionally-mismatched slots on this
        # already-bound profile, surface them distinctly so they appear in the
        # controls-status output. The profile's bindings were never changed --
        # these slots need manual attention in TeknoParrot's own UI. See #17.
        $mismatch = New-Object System.Collections.ArrayList
        if ($reportMap.ContainsKey($f.BaseName) -and $reportMap[$f.BaseName].MismatchSlots) {
            foreach ($slot in ($reportMap[$f.BaseName].MismatchSlots -split ', ')) {
                [void]$mismatch.Add($slot)
            }
        }

        [void]$rows.Add([pscustomobject]@{
            Code = $f.BaseName; Family = $family
            Bound = $bound; Total = $btns.Count
            Manual = $manual; Mismatch = $mismatch; Status = $status; Reference = $reference
        })
    }

    Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Controls status profile scan' -Current $profileTotal -Total $profileTotal -Complete
    $knownFamilies = @('button','driving','lightgun','trackball','analog','spinner')
    $extraFamilies = @($rows | ForEach-Object { $_.Family } | Sort-Object -Unique |
                       Where-Object { $knownFamilies -notcontains $_ })
    $allFamilies   = $knownFamilies + $extraFamilies

    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine("TeknoParrot Manager -- Controls Status")
    [void]$sb.AppendLine("Generated : $((Get-Date).ToString('yyyy-MM-dd HH:mm:ss', [System.Globalization.CultureInfo]::InvariantCulture))")
    [void]$sb.AppendLine("Profiles  : $($rows.Count)")
    [void]$sb.AppendLine("Run ID    : $effectiveRunId")
    [void]$sb.AppendLine(("=" * 80))

    foreach ($fam in $allFamilies) {
        $group = @($rows | Where-Object { $_.Family -eq $fam } | Sort-Object Code)
        if ($group.Count -eq 0) { continue }
        [void]$sb.AppendLine("")
        [void]$sb.AppendLine("[$fam]")
        foreach ($row in $group) {
            $boundLabel = "{0}/{1} bound" -f $row.Bound, $row.Total
            $refPart    = if ($row.Reference) { "  <- $($row.Reference)" } else { "" }
            [void]$sb.AppendLine(("  {0,-44} {1,-12}  {2}{3}" -f $row.Code, $boundLabel, $row.Status, $refPart))
            if ($row.Manual.Count -gt 0) {
                [void]$sb.AppendLine("    manual: $($row.Manual -join ', ')")
            }
            if ($row.Mismatch.Count -gt 0) {
                [void]$sb.AppendLine("    mismatch (rebind in TeknoParrot UI): $($row.Mismatch -join ', ')")
            }
        }
    }
    [void]$sb.AppendLine("")
    [void]$sb.AppendLine(("=" * 80))

    try {
        [System.IO.File]::WriteAllText($outputPath, $sb.ToString(), (New-Object System.Text.UTF8Encoding $false))
        return $rows.Count
    } catch {
        Write-Log "Controls status: FAILED to write -- $_"
        return -1
    }
}

# =============================================================================
# CONTROL READINESS ENGINE (issue #255)
# =============================================================================
# Read-only assessment of a single profile code across three independent
# dimensions: Registration, Controls, and Launch observation. Issue #255's
# evidence session showed a registration/launch-success path can coexist
# with controls that were skipped or never verified, and TeknoParrotUI's own
# first-run wizard let its "Controls configuration completed" checkbox
# become checked with no mapping screen ever opened (issue #253). Collapsing
# these into a single "Ready" boolean would hide exactly that failure mode,
# so each dimension is reported on its own and never combined.
#
# Hard constraints (do not weaken without a corresponding
# ARCHITECTURE.md update and explicit sign-off -- see issue #255):
#   - Never writes a UserProfile or GameProfiles XML file.
#   - Never runs control propagation (Invoke-ControlPropagation) or invokes
#     TeknoParrotUI's controls wizard.
#   - Never infers a mapping that is not already present on disk.
#   - "Verified" is never assigned by this engine. Confirming a control
#     actually works requires real evidence (an observed successful test),
#     which this static, read-only pass cannot manufacture. Registration,
#     wizard completion, a selected Input API, or a profile's mere existence
#     are explicitly NOT allowed to imply Verified (issue #255).
#
# Precise I/O surface (do not describe this more broadly than it actually
# is): the control-readiness XML assessment reads `<code>.xml` under the
# caller-supplied UserProfilesDir/GameProfilesDir only. Separately,
# Get-ControlReadinessRegistrationState performs a read-only Test-Path
# existence check against the registered profile's GamePath (an arbitrary
# game executable location, not a UserProfiles/GameProfiles path) to
# distinguish 'Registered' from 'Broken'. Neither of these, nor any other
# function in this section, calls or reaches a write-capable path.

# Classifies registration state for one profile code from UserProfiles alone.
# Returns 'Registered', 'Unregistered', or 'Broken'. Never touches GameProfiles
# templates -- registration is strictly about what TeknoParrot has on record.
function Get-ControlReadinessRegistrationState {
    param([Parameter(Mandatory)][string]$Code, [Parameter(Mandatory)][string]$UserProfilesDir)

    # Profile codes are purely alphanumeric (same invariant as
    # Resolve-RegisteredGameFolder); a $Code sourced from an externally-fetched
    # dat index is untrusted input, so reject anything else before it is ever
    # joined into a path rather than let a traversal sequence reach Join-Path.
    if ($Code -notmatch '^[\w-]+$') { return 'Unregistered' }

    $path = Join-Path $UserProfilesDir "$Code.xml"
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return 'Unregistered' }

    try {
        $doc = Read-Xml $path
    } catch {
        return 'Broken'
    }
    if ($null -eq $doc.GameProfile) { return 'Broken' }

    $gpNode = $doc.GameProfile.SelectSingleNode('GamePath')
    if ($null -eq $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { return 'Broken' }

    $gamePath = $gpNode.InnerText.Trim().TrimEnd('\')
    if (-not [System.IO.File]::Exists((ConvertTo-TpmAutoSyncLongPath -Path $gamePath))) { return 'Broken' }

    return 'Registered'
}

# Returns the authoritative required-control specification for one profile
# code, or $null when this engine has no such specification. This is a
# deliberately tiny, hand-curated catalog -- issue #255's own investigation
# (After Burner Climax / abc, upstream teknogods/TeknoParrotUI GameProfiles
# revision 22) is the only source of truth populated so far. A profile code
# with no entry here returns $null on purpose: Get-ControlReadinessControlsState
# must not infer requiredness from whatever nodes happen to be present in an
# arbitrary document, so an unrecognized code always falls through to
# 'Unknown' rather than guessing from structure. Built inline (not as a
# top-level script variable) so the Pester harness's function-body AST
# extraction picks it up automatically.
function Get-ControlReadinessKnownRequirements {
    param([string]$Code)

    if ([string]::IsNullOrWhiteSpace($Code)) { return $null }

    $catalog = @{
        'abc' = [pscustomobject]@{
            # Provenance: teknogods/TeknoParrotUI, GameProfiles/abc.xml,
            # GameProfileRevision 22 -- captured during issue #255's evidence
            # session. This entry is valid ONLY for that exact captured
            # identity/revision. Cross-checked against the document before
            # requirements are trusted (see the "ambiguous contract" branch
            # below): ExecutableName, EmulationProfile, AND
            # GameProfileRevision must all match, or the document is treated
            # as Unknown. A code match alone is not enough, and a later
            # upstream revision of abc.xml is not assumed to share these
            # requirements -- if teknogods ever ships a revision 23+ with
            # different required controls, this entry must not silently keep
            # classifying it against stale requirements; it will instead
            # read as Unknown until a reviewer adds a matching contract.
            ExpectedExecutableName   = 'abc'
            ExpectedEmulationProfile = 'AfterBurnerClimax'
            ExpectedGameProfileRevision = 22
            # InputMapping values for Start, Gun Trigger, Missile Trigger,
            # Climax Switch -- the confirmed required digital controls from
            # the published abc.xml revision 22.
            RequiredButtons = @('P1ButtonStart', 'P1Button1', 'P1Button2', 'P1Button3')
            # InputMapping values for Joystick Analog X/Y and Throttle Lever.
            RequiredAnalogs = @('Analog0', 'Analog2', 'Analog4')
            # Plain names for each control, in the order the entry above lists them (Joystick X, Joystick Y, Throttle Lever).
            ControlMeanings = @{
                'P1ButtonStart' = 'Start button'
                'P1Button1'     = 'Gun trigger'
                'P1Button2'     = 'Missile trigger'
                'P1Button3'     = 'Climax switch'
                'Analog0'       = 'Joystick left and right'
                'Analog2'       = 'Joystick up and down'
                'Analog4'       = 'Throttle lever'
            }
        }
    }

    $key = $Code.ToLowerInvariant()
    if ($catalog.ContainsKey($key)) { return $catalog[$key] }
    return $null
}

# Classifies controls state from an already-loaded profile [xml] document
# (either a real UserProfile or a read-only GameProfiles template), using
# the authoritative requirements for $Code. Returns 'Missing', 'Unsupported',
# 'NotVerified', or 'Unknown'. 'Verified' is intentionally unreachable here
# -- see the section header above.
#
# This deliberately does NOT use raw structural presence as evidence:
#   - "button nodes exist" does not mean the profile is supported;
#   - "no button nodes" does not mean the profile is unsupported;
#   - "some/all buttons bound" does not mean requirements are met or that
#     controls were ever tested.
# Every branch below requires either a positive match against the known
# requirements catalog (Missing/NotVerified) or positive evidence drawn
# from the document's own declared contract (Unsupported -- a selected
# Input API that isn't among the profile's own FieldOptions). Without a
# catalog entry, or without the document matching that entry's expected
# shape, the honest answer is 'Unknown', not a guess.
# Test-ButtonIsBound (shared with Write-ControlsStatus/Invoke-ControlPropagation)
# only checks whether a RawInputButton/DirectInputButton/XInputButton node
# exists -- an empty element (`<DirectInputButton></DirectInputButton>`)
# still counts as "bound" for its purposes. That is too permissive for
# readiness classification: an empty binding element is not a usable
# binding, so this local wrapper adds a non-empty-content requirement on
# top of Test-ButtonIsBound rather than weakening the shared helper (which
# other, unrelated callers may depend on).
function Test-ControlReadinessButtonBindingUsable {
    param($btn)
    if (-not (Test-ButtonIsBound $btn)) { return $false }
    foreach ($nodeName in @('RawInputButton', 'DirectInputButton', 'XInputButton')) {
        $n = $btn.SelectSingleNode($nodeName)
        if ($n -and -not [string]::IsNullOrWhiteSpace($n.InnerText)) { return $true }
    }
    return $false
}

# An analog InputMapping slot is only a structurally complete mapping when
# it also declares a non-empty AnalogType -- a slot with the mapping name
# present but AnalogType missing or blank is malformed/incomplete, not a
# real analog binding, and must not count toward a required analog control.
function Test-ControlReadinessAnalogMappingUsable {
    param($btn)
    $atNode = $btn.SelectSingleNode('AnalogType')
    return ($null -ne $atNode) -and -not [string]::IsNullOrWhiteSpace($atNode.InnerText)
}

# Checks that a loaded profile document really is the one a requirements entry describes, and that it does not
# select an Input API its own options rule out. Returns 'Ok', 'Unknown' (identity cannot be confirmed) or 'Unsupported'.
# Read-only. Shared by the controls state check and the controls coverage inventory.
function Get-ControlReadinessDocumentFit {
    param($Doc, $Requirements)

    $doc = $Doc
    $requirements = $Requirements
    if ($null -eq $doc -or $null -eq $doc.GameProfile) { return 'Unknown' }

    # Ambiguous/unverifiable profile contract: the code matched the catalog,
    # but the document's own declared identity does not match what that
    # catalog entry describes -- including GameProfileRevision, since a
    # later upstream revision is not assumed to share the same required
    # controls. The requirements might not even apply to this document, so
    # nothing below can be trusted as authoritative.
    $execNode     = $doc.GameProfile.SelectSingleNode('ExecutableName')
    $emuNode      = $doc.GameProfile.SelectSingleNode('EmulationProfile')
    $revisionNode = $doc.GameProfile.SelectSingleNode('GameProfileRevision')
    $execName = if ($execNode) { $execNode.InnerText.Trim() } else { '' }
    $emuName  = if ($emuNode) { $emuNode.InnerText.Trim() } else { '' }
    $revision = $null
    if ($revisionNode -and -not [string]::IsNullOrWhiteSpace($revisionNode.InnerText)) {
        [void][int]::TryParse($revisionNode.InnerText.Trim(), [ref]$revision)
    }
    if ($execName -ne $requirements.ExpectedExecutableName -or
        $emuName  -ne $requirements.ExpectedEmulationProfile -or
        $null -eq $revision -or $revision -ne $requirements.ExpectedGameProfileRevision) {
        return 'Unknown'
    }

    # Positive unsupported evidence: the profile's own ConfigValues declare
    # which Input API values it supports (FieldOptions); a selected
    # FieldValue outside that set is a real, document-declared contract
    # violation -- not a heuristic guess about what "should" be supported.
    $inputApiField = $doc.GameProfile.SelectSingleNode("ConfigValues/FieldInformation[FieldName='Input API']")
    if ($inputApiField) {
        $selected = $inputApiField.SelectSingleNode('FieldValue')
        $optionsNode = $inputApiField.SelectSingleNode('FieldOptions')
        if ($selected -and -not [string]::IsNullOrWhiteSpace($selected.InnerText) -and $optionsNode) {
            $options = @($optionsNode.SelectNodes('string') | ForEach-Object { $_.InnerText.Trim() })
            if ($options.Count -gt 0 -and ($options -notcontains $selected.InnerText.Trim())) {
                return 'Unsupported'
            }
        }
    }

    return 'Ok'
}

function Get-ControlReadinessControlsState {
    param(
        [Parameter(Position = 0)]$doc = $null,
        [Parameter(Position = 1)][string]$Code = ''
    )

    # Every outcome comes from the controls coverage inventory. Complete structure is still only 'NotVerified':
    # no threshold of bound buttons promotes it to Verified.
    $contract = Get-TpmControlCoverageContract -Code $Code
    if ($null -eq $contract -or $null -eq $doc -or $null -eq $doc.GameProfile) { return 'Unknown' }
    $inventory = Get-TpmControlCoverageInventory -Contract $contract -Facts (Get-TpmControlBindingFacts -Doc $doc -Contract $contract -Code $Code)
    switch ($inventory.Structural) {
        'Unknown'     { return 'Unknown' }
        'Unsupported' { return 'Unsupported' }
        'Complete'    { return 'NotVerified' }
        default       { return 'Missing' }
    }
}

# Classifies launch-observation state for one profile code. TPM does not
# launch games itself and has no launch-outcome log to read (TeknoParrotUI
# and BudgieLoader own the launch path), so this dimension is 'NotTestedByTpm'
# unless the player told TPM they played the game and its controls worked
# (Get-TpmControlVerificationState says that record is still Current). Then it
# is 'ObservedSuccess', observed by the player. 'ObservedFailure' stays a
# named state for a future real evidence source -- never synthesize either one
# from registration, controls state, or any other proxy.
function Get-ControlReadinessLaunchState {
    param([string]$Code, [string]$VerificationStatus = '')
    if ($VerificationStatus -eq 'Current') { return 'ObservedSuccess' }
    return 'NotTestedByTpm'
}

# Reads the profile document for one code: the real UserProfile when there is one, otherwise the GameProfiles
# template. Returns $null when neither exists, the code is not a safe name, or the file cannot be read. Never writes.
function Read-ControlReadinessProfileDocument {
    param(
        [Parameter(Mandatory)][string]$Code,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [string]$GameProfilesDir = ''
    )

    # Same code-shape guard as Get-ControlReadinessRegistrationState -- do not
    # join an unvalidated $Code into either directory's path.
    $sourcePath = $null
    if ($Code -match '^[\w-]+$') {
        $userProfilePath = Join-Path $UserProfilesDir "$Code.xml"
        $templatePath    = if ($GameProfilesDir) { Join-Path $GameProfilesDir "$Code.xml" } else { '' }
        $sourcePath =
            if (Test-Path -LiteralPath $userProfilePath -PathType Leaf) { $userProfilePath }
            elseif ($templatePath -and (Test-Path -LiteralPath $templatePath -PathType Leaf)) { $templatePath }
            else { $null }
    }

    $doc = $null
    if ($sourcePath) {
        try { $doc = Read-Xml $sourcePath } catch { $doc = $null }
    }

    return $doc
}

# Combines the three independent dimensions for one profile code into a
# single read-only report row. Controls are read from whichever profile
# document actually exists on disk: the real UserProfile when registered,
# otherwise the GameProfiles template (unregistered games have no real
# bindings, so falling back to the template's unbound buttons correctly
# yields 'Missing' rather than 'Unknown'). $GameProfilesDir is optional --
# omit it to assess registration/controls from UserProfiles only.
function Get-ControlReadinessAssessment {
    param(
        [Parameter(Mandatory)][string]$Code,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [string]$GameProfilesDir = '',
        [string]$StateRoot = ''
    )

    $registration = Get-ControlReadinessRegistrationState -Code $Code -UserProfilesDir $UserProfilesDir

    $doc = Read-ControlReadinessProfileDocument -Code $Code -UserProfilesDir $UserProfilesDir -GameProfilesDir $GameProfilesDir

    # Verified needs the player's own record of a play test that still matches the game's controls (issue #307) and no
    # first-run or calibration step left to do. A reviewed contract that says controls are Missing or Unsupported is not overridden.
    $verification = Get-TpmControlVerificationState -Code $Code -Doc $doc -StateRoot $StateRoot
    $controls = Get-ControlReadinessControlsState $doc $Code
    $earned = ($verification.Status -eq 'Current' -and @($verification.Outstanding).Count -eq 0 -and $controls -in @('NotVerified', 'Unknown'))
    if ($earned) { $controls = 'Verified' }

    $row = [pscustomobject]@{
        Code               = $Code
        Registration       = $registration
        Controls           = $controls
        Launch             = Get-ControlReadinessLaunchState -Code $Code -VerificationStatus $verification.Status
        VerificationStatus = $verification.Status
        SetupOutstanding   = @($verification.Outstanding)
    }
    if ($earned) { Add-Member -InputObject $row -NotePropertyName VerificationEvidence -NotePropertyValue $verification.Evidence }
    return $row
}

# Returns $true only when $Assessment carries a structured VerificationEvidence
# record that can actually justify Controls = 'Verified'. Get-ControlReadinessAssessment
# sets Controls to 'Verified' only from the player's own saved play-test record
# (Get-TpmControlVerificationState) and attaches that record as VerificationEvidence,
# so nothing else reaches 'Verified'. The same gap is closed for a caller constructing an
# assessment object by hand. Issue #255 is explicit that registration, wizard
# completion, a selected Input API, or a profile's mere existence must never
# imply Verified; this closes the same gap for any externally-built
# assessment object, not only for this engine's own output. A well-formed
# record needs a non-empty Method (what test was performed, e.g. "manual
# play-test") and a non-empty ObservedAt (when it happened) -- both are
# cheap to fake, but the point is structural: nothing accidentally reaches
# 'Verified' just by echoing a Controls string back.
function Test-ControlReadinessVerificationEvidence {
    param($Assessment)

    if ($null -eq $Assessment) { return $false }
    $evidenceProp = $Assessment.PSObject.Properties['VerificationEvidence']
    if ($null -eq $evidenceProp) { return $false }

    $evidence = $evidenceProp.Value
    if ($null -eq $evidence) { return $false }
    if ($evidence -isnot [System.Management.Automation.PSCustomObject]) { return $false }

    $methodProp = $evidence.PSObject.Properties['Method']
    $observedAtProp = $evidence.PSObject.Properties['ObservedAt']
    if ($null -eq $methodProp -or [string]::IsNullOrWhiteSpace([string]$methodProp.Value)) { return $false }
    if ($null -eq $observedAtProp -or [string]::IsNullOrWhiteSpace([string]$observedAtProp.Value)) { return $false }

    return $true
}

# =============================================================================
# TEKNOPARROT WIZARD READINESS DETECTOR (issue #253)
# =============================================================================
# Read-only detection of TeknoParrotUI's own first-run wizard state, so TPM
# can tell a user what TeknoParrot may still ask them to do without ever
# touching TeknoParrot-owned state itself. Per issue #253's own investigation
# of the upstream TeknoParrotUI source: MainWindow.xaml.cs shows the wizard
# is shown/skipped based on Lazydata.ParrotData.FirstTimeSetupComplete;
# JoystickHelper.cs serializes/deserializes ParrotData.xml in the
# TeknoParrotUI working directory; ParrotData.cs defines that flag alongside
# DatXmlLocation. This detector does not have a real, hardware-verified copy
# of ParrotData.xml to confirm the exact root element name against -- so it
# deliberately locates the FirstTimeSetupComplete and DatXmlLocation
# elements via the XPath queries `//FirstTimeSetupComplete` and
# `//DatXmlLocation` (each matches that element name anywhere in the
# document, regardless of the document's actual root element) rather than
# assuming a specific root, and returns 'Unknown' whenever the expected
# field cannot be found at all -- or is found more than once with
# conflicting values (see below) -- instead of guessing a schema. This
# assumption should be confirmed against a real installed ParrotData.xml
# before this detector is relied upon for anything beyond onboarding text.
#
# Hard constraints (same standing as the issue #255 control readiness
# engine above -- do not weaken without an ARCHITECTURE.md
# update and explicit sign-off):
#   - Never creates, writes, repairs, rewrites, or normalizes ParrotData.xml
#     or any other TeknoParrot-owned file.
#   - Never invokes TeknoParrotUI's setup wizard.
#   - A missing file, unparseable XML, and a parseable-but-unrecognized
#     schema are three different facts and are classified distinctly
#     ('Missing', 'Malformed', 'Unknown') rather than folded into one
#     generic failure state.

# Classifies TeknoParrotUI's first-run wizard state from its own
# ParrotData.xml, read-only. Returns a [pscustomobject] with:
#   State          -- 'Complete', 'Incomplete', 'Missing', 'Malformed', or
#                      'Unknown' (present but FirstTimeSetupComplete could
#                      not be confidently read as a boolean, or appears more
#                      than once).
#   DatXmlLocation -- the DAT/XML path TeknoParrotUI has on record, if the
#                      field is present and non-empty; otherwise $null.
#                      Informational only -- never used to influence State.
#
# Exactly one unambiguous FirstTimeSetupComplete element is required to
# classify Complete/Incomplete. A document with more than one such element
# anywhere -- whether the values agree or conflict -- is not the schema
# shape this detector has any confirmed contract for (see the section
# header above: the exact upstream schema is unverified), so it always
# reads as 'Unknown' rather than picking one occurrence and hoping it is
# authoritative. This is the deliberately conservative rule; see
# Tests\TeknoParrot-Manager.Tests.ps1 for both the duplicate-agreeing-value
# and duplicate-conflicting-value cases.
function Get-TeknoParrotWizardState {
    param([Parameter(Mandatory)][string]$TeknoParrotRoot)

    $path = Join-Path $TeknoParrotRoot 'ParrotData.xml'
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
        return [pscustomobject]@{ State = 'Missing'; DatXmlLocation = $null }
    }

    $doc = $null
    try {
        $doc = Read-Xml $path
    } catch {
        return [pscustomobject]@{ State = 'Malformed'; DatXmlLocation = $null }
    }
    if ($null -eq $doc -or $null -eq $doc.DocumentElement) {
        return [pscustomobject]@{ State = 'Malformed'; DatXmlLocation = $null }
    }

    $datNode = $doc.SelectSingleNode('//DatXmlLocation')
    $datXmlLocation = if ($datNode -and -not [string]::IsNullOrWhiteSpace($datNode.InnerText)) {
        $datNode.InnerText.Trim()
    } else {
        $null
    }

    $completeNodes = @($doc.SelectNodes('//FirstTimeSetupComplete'))
    if ($completeNodes.Count -ne 1) {
        return [pscustomobject]@{ State = 'Unknown'; DatXmlLocation = $datXmlLocation }
    }
    $completeNode = $completeNodes[0]
    if ([string]::IsNullOrWhiteSpace($completeNode.InnerText)) {
        return [pscustomobject]@{ State = 'Unknown'; DatXmlLocation = $datXmlLocation }
    }

    $state = switch ($completeNode.InnerText.Trim().ToLowerInvariant()) {
        'true'  { 'Complete' }
        'false' { 'Incomplete' }
        default { 'Unknown' }
    }
    return [pscustomobject]@{ State = $state; DatXmlLocation = $datXmlLocation }
}

# Combines the issue #255 control-readiness assessment with the issue #253
# TeknoParrotUI wizard state into the onboarding handoff text a user sees
# after registration/AutoSync. Four dimensions -- Registration, Controls,
# Launch, and TeknoParrotUI wizard state -- are reported independently and
# combined ONLY here, as display text; there is still no combined "Ready"
# boolean anywhere. Pure string formatting: never prompts, never triggers a
# configure/test/wizard action itself.
#
# Fails closed on a caller-
# supplied Controls = 'Verified' is only trusted when
# Test-ControlReadinessVerificationEvidence confirms real evidence backs
# it, so this formatter cannot be tricked into claiming controls are ready
# by a hand-built assessment object either.
function Get-OnboardingHandoffSummaryLines {
    param(
        [Parameter(Mandatory)]$Assessment,
        [Parameter(Mandatory)]$WizardState
    )

    $controlsState = $Assessment.Controls
    if ($controlsState -eq 'Verified' -and -not (Test-ControlReadinessVerificationEvidence -Assessment $Assessment)) {
        $controlsState = 'NotVerified'
    }

    $registrationText = switch ($Assessment.Registration) {
        'Registered'   { 'Game registered successfully' }
        'Unregistered' { 'Game is not registered' }
        'Broken'       { 'Game registration is broken' }
        default        { "Game registration: $($Assessment.Registration)" }
    }

    $launchText = switch ($Assessment.Launch) {
        'NotTestedByTpm'  { 'Launch status: Not tested by TeknoParrot Manager' }
        'ObservedSuccess' { 'Launch status: Explicitly observed (success)' }
        'ObservedFailure' { 'Launch status: Explicitly observed (failure)' }
        default           { "Launch status: $($Assessment.Launch)" }
    }

    # TPM cannot prove TeknoParrot's own setup wizard is done, so only
    # 'Complete' (FirstTimeSetupComplete read as true) is reported as complete.
    # What the user should do about it is said once per run by
    # Get-TeknoParrotWizardAdviceLines, not repeated for every game.
    $wizardText = switch ($WizardState.State) {
        'Complete'   { 'TeknoParrot first-run setup: Complete' }
        'Incomplete' { 'TeknoParrot first-run setup: Not yet complete' }
        'Missing'    { 'TeknoParrot first-run setup: Unknown (no ParrotData.xml found yet)' }
        'Malformed'  { 'TeknoParrot first-run setup: Could not be read (its ParrotData.xml appears damaged)' }
        'Unknown'    { 'TeknoParrot first-run setup: Unknown (unrecognized ParrotData.xml layout)' }
        default      { "TeknoParrot first-run setup: $($WizardState.State)" }
    }

    $controlsText = switch ($controlsState) {
        'Verified'    { 'Controls: Verified' }
        'NotVerified' { 'Controls: Not verified' }
        'Missing'     { 'Controls: Missing' }
        'Unsupported' { 'Controls: Unsupported' }
        'Unknown'     { 'Controls: Unknown' }
        default       { "Controls: $controlsState" }
    }

    $lines = @(
        $registrationText,
        $launchText,
        $wizardText,
        $controlsText,
        '',
        "This game is registered. TeknoParrotUI still owns the game setup wizard and controls configuration."
    )

    # Only offer a direct
    # TeknoParrot map/test instruction when there is something left to verify.
    if ($controlsState -in @('NotVerified', 'Missing', 'Unknown')) {
        $lines += ''
        $lines += 'Open TeknoParrot controls configuration and map/test controls before treating this game as ready.'
    }
    $outstanding = @()
    if ($Assessment.PSObject.Properties['SetupOutstanding']) { $outstanding = @($Assessment.SetupOutstanding) }
    if ($outstanding -contains 'Calibration') { $lines += 'Calibrate the wheel, gun or other analog controls for this game before treating it as ready.' }
    if ($outstanding -contains 'FirstRun') { $lines += 'Do the first-run Test or Service menu step for this game before treating it as ready.' }

    return $lines
}

# The one plain-language advisory about TeknoParrot's own first-time setup
# (issue #260), shown once per run after TPM's own steps and whether or not
# any game has a controls catalog entry. Pure text formatting over the
# Get-TeknoParrotWizardState result: it never reads or writes a file itself.
# Returns no lines when TeknoParrot reports its setup as complete.
function Get-TeknoParrotWizardAdviceLines {
    param(
        [Parameter(Mandatory)]$WizardState,
        [Parameter(Mandatory)][string]$TeknoParrotRoot
    )

    $state = [string]$WizardState.State
    if ($state -eq 'Complete') { return @() }
    Write-Log "TeknoParrot first-run setup state is '$state' (ParrotData.xml in $TeknoParrotRoot); first-time setup steps were shown."

    $opening = if ($state -eq 'Incomplete') {
        'TeknoParrot has its own first-time setup, and it is not finished yet.'
    } else {
        'TeknoParrot has its own first-time setup, and TPM cannot tell if it is finished.'
    }
    return @(
        $opening,
        'Before you start a game, open TeknoParrot and finish it:',
        ('  1. Open this file: ' + (Join-Path $TeknoParrotRoot 'TeknoParrotUi.exe')),
        '  2. Choose your DAT file (the list of games) when it asks.',
        '  3. Let it scan for your games.',
        '  4. Set up your controls when it asks.'
    )
}

# Builds the read-only controls handoff items shown in ACTION REQUIRED after
# registration. Only profile codes with an authoritative requirements catalog
# entry are surfaced here: an uncataloged profile remains Unknown in a direct
# assessment rather than being classified from structure or silently treated
# as ready. A catalog-backed profile whose identity is ambiguous is surfaced
# as Unknown, so stale or mismatched requirements cannot disappear from the
# user-facing readiness report.
function Get-ControlReadinessActionItems {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [string]$GameProfilesDir = '',
        [string]$TeknoParrotRoot = ''
    )

    $items = New-Object System.Collections.ArrayList
    if (-not (Test-Path -LiteralPath $UserProfilesDir -PathType Container)) {
        return @()
    }

    $wizardState = Get-TeknoParrotWizardState -TeknoParrotRoot $TeknoParrotRoot

    $profiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'Control readiness profile discovery' -EnumerationErrorAction SilentlyContinue | Sort-Object BaseName)

    $profileIndex = 0
    $profileTotal = $profiles.Count
    $scanStarted = Get-Date
    foreach ($profileFile in $profiles) {
        $profileIndex++
        Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Control readiness profile scan' -Current $profileIndex -Total $profileTotal -StartedAt $scanStarted
        $code = $profileFile.BaseName
        if ($null -eq (Get-ControlReadinessKnownRequirements -Code $code)) { continue }

        $assessment = Get-ControlReadinessAssessment -Code $code `
            -UserProfilesDir $UserProfilesDir -GameProfilesDir $GameProfilesDir
        if ($assessment.Registration -ne 'Registered') { continue }

        $displayControls = $assessment.Controls
        if ($displayControls -eq 'Verified' -and
            -not (Test-ControlReadinessVerificationEvidence -Assessment $assessment)) {
            $displayControls = 'NotVerified'
        }
        if ($displayControls -eq 'Verified') { continue }

        $summaryLines = Get-OnboardingHandoffSummaryLines -Assessment $assessment -WizardState $wizardState

        [void]$items.Add([pscustomobject]@{
            Code         = $code
            Assessment   = $assessment
            SummaryLines = @($summaryLines)
        })
    }

    Write-TpmCompactExtractionProgress -Phase 'Checking' -Label 'Control readiness profile scan' -Current $profileTotal -Total $profileTotal -Complete
    return @($items)
}

# =============================================================================
# BEGIN MODULE-READY SECTION: Controls coverage inventory
# =============================================================================
# Read-only inventory of which controls a game needs and which of them TPM can see as usable (issue #305).
# It reads facts about a profile and reports. It never writes a profile, never starts a game, and never says "ready".
# Structural completeness is kept apart from verification: nothing in this section can produce Verified.
# The contract it follows is shaped like docs/architecture/CONTROLLER_CAPABILITY_CONTRACT.md (issue #303). Reading the
# profile file is a separate step (Get-TpmControlBindingFacts) from deciding what the facts mean (Get-TpmControlCoverageInventory),
# so another device or storage layout only needs a new fact reader.
# Every game gets a contract: the reviewed one when the saved profile is the reviewed revision, otherwise one read from TeknoParrot's
# own game file (Get-TpmDerivedControlContract), marked as not reviewed. The audit functions at the end sort every registered game.
# Depends on: Get-ControlReadinessKnownRequirements, Get-ControlReadinessDocumentFit, Read-ControlReadinessProfileDocument,
# Get-ButtonNodes, Test-ControlReadinessButtonBindingUsable, Test-ControlReadinessAnalogMappingUsable, Test-TpmMappingInPlayerOneScope,
# Get-TpmProfileFriendlyTitle, Get-TpmRegisteredProfileFilesWithDiscoveryProgress, Invoke-TpmProgressGroup, Write-TpmOutcome.

# Builds the reviewed controls contract for one profile code from the known-requirements list. Returns $null for a code
# that has no reviewed entry, so an unknown game is never described from a guess.
function Get-TpmControlCoverageContract {
    param([string]$Code)

    if ([string]::IsNullOrWhiteSpace($Code) -or $Code -notmatch '^[\w-]+$') { return $null }
    $requirements = Get-ControlReadinessKnownRequirements -Code $Code
    if ($null -eq $requirements) { return $null }

    $controls = New-Object System.Collections.ArrayList
    foreach ($entry in @(
            @($requirements.RequiredButtons | ForEach-Object { [pscustomobject]@{ Id = $_; Kind = 'Button' } }),
            @($requirements.RequiredAnalogs | ForEach-Object { [pscustomobject]@{ Id = $_; Kind = 'Axis' } })
        )) {
        foreach ($item in @($entry)) {
            $meaning = [string]$requirements.ControlMeanings[$item.Id]
            if ([string]::IsNullOrWhiteSpace($meaning)) { $meaning = [string]$item.Id }
            [void]$controls.Add([pscustomobject]@{
                ControlId   = [string]$item.Id
                Kind        = $item.Kind
                Meaning     = $meaning
                Requirement = 'Required'
                Bindable    = $true
                Scope       = 'Player'
            })
        }
    }

    return [pscustomobject]@{
        ContractVersion   = 'TpmControllerCapability/v1'
        MinReaderVersion  = 1
        ProfileId         = ($Code.ToLowerInvariant() + '-reviewed')
        ProfileRevision   = 1
        ControllerContext = [pscustomobject]@{ DeviceClass = 'Unknown'; PlayerSlot = 'P1'; SelectionSource = 'Unset' }
        SemanticControls  = @($controls)
        Evidence          = [pscustomobject]@{ Origin = 'TpmReviewed'; ReviewState = 'Reviewed'; ReviewedUtc = $null }
        GameContracts     = @()
    }
}

# Reads one loaded profile document and reports, for the controls in the contract, which ones have a usable binding.
# Fit is 'Ok', 'Unknown' (the document is not the one the contract describes) or 'Unsupported' (the document's own
# Input API options rule it out). Read-only.
function Get-TpmControlBindingFacts {
    param(
        $Doc,
        [Parameter(Mandatory)]$Contract,
        [Parameter(Mandatory)][string]$Code,
        # Set for a contract read from the game's own file: the identity the saved profile must match, and the stricter binding rule.
        $Identity = $null
    )

    $strict = ($null -ne $Identity)
    $requirements = if ($strict) { $Identity } else { Get-ControlReadinessKnownRequirements -Code $Code }
    if ($null -eq $requirements) { return [pscustomobject]@{ Fit = 'Unknown'; Why = 'NoContract'; UsableControlIds = @() } }
    if ($null -eq $Doc -or $null -eq $Doc.GameProfile) { return [pscustomobject]@{ Fit = 'Unknown'; Why = 'NoProfile'; UsableControlIds = @() } }
    $fit = Get-ControlReadinessDocumentFit -Doc $Doc -Requirements $requirements
    if ($fit -ne 'Ok') { return [pscustomobject]@{ Fit = $fit; Why = $(if ($fit -eq 'Unknown') { 'DifferentVersion' } else { '' }); UsableControlIds = @() } }

    $byMapping = @{}
    foreach ($button in @(Get-ButtonNodes $Doc)) {
        $mappingNode = $button.SelectSingleNode('InputMapping')
        if ($mappingNode -and -not [string]::IsNullOrWhiteSpace($mappingNode.InnerText)) {
            $key = $mappingNode.InnerText.Trim()
            if (-not $byMapping.ContainsKey($key)) { $byMapping[$key] = New-Object System.Collections.ArrayList }
            [void]$byMapping[$key].Add($button)
        }
    }

    $usable = New-Object System.Collections.ArrayList
    foreach ($control in @($Contract.SemanticControls)) {
        if (-not $byMapping.ContainsKey($control.ControlId)) { continue }
        $nodes = @($byMapping[$control.ControlId])
        if ($strict) {
            # A game file often shows one control as several buttons (for example an axis and its keyboard halves): one usable binding is enough,
            # and an axis also needs a declared type.
            $isUsable = (@($nodes | Where-Object { Test-ControlReadinessButtonBindingUsable $_ }).Count -gt 0) -and ($control.Kind -ne 'Axis' -or @($nodes | Where-Object { Test-ControlReadinessAnalogMappingUsable $_ }).Count -gt 0)
        } else {
            $node = $nodes[$nodes.Count - 1]
            $isUsable = if ($control.Kind -eq 'Axis') { Test-ControlReadinessAnalogMappingUsable $node } else { Test-ControlReadinessButtonBindingUsable $node }
        }
        if ($isUsable) { [void]$usable.Add([string]$control.ControlId) }
    }
    return [pscustomobject]@{ Fit = 'Ok'; Why = ''; UsableControlIds = @($usable) }
}

# Turns a contract and the facts about one profile into one row per control plus an overall state. Pure: the same inputs
# always give the same output, in the contract's order. Verification is always NotVerified here, because this section has
# no gameplay evidence and a launch, a registration or a bound-button count is never evidence.
function Get-TpmControlCoverageInventory {
    param(
        [Parameter(Mandatory)]$Contract,
        [Parameter(Mandatory)]$Facts
    )

    $fit = [string]$Facts.Fit
    $usable = @($Facts.UsableControlIds)
    $rows = New-Object System.Collections.ArrayList
    foreach ($control in @($Contract.SemanticControls)) {
        $structural = 'Unknown'
        if ($fit -eq 'Ok') { $structural = if ($usable -contains $control.ControlId) { 'Complete' } else { 'Missing' } }
        elseif ($fit -eq 'Unsupported') { $structural = 'Unsupported' }

        $setup = 'Unknown'
        $setupProperty = $control.PSObject.Properties['SetupRequirement']
        if ($setupProperty -and -not [string]::IsNullOrWhiteSpace([string]$setupProperty.Value)) { $setup = [string]$setupProperty.Value }

        [void]$rows.Add([pscustomobject]@{
            ControlId    = [string]$control.ControlId
            Meaning      = [string]$control.Meaning
            Requirement  = [string]$control.Requirement
            Scope        = [string]$control.Scope
            Structural   = $structural
            Setup        = $setup
            Verification = 'NotVerified'
        })
    }

    $required = @($rows | Where-Object { $_.Requirement -eq 'Required' })
    $completeRequired = @($required | Where-Object { $_.Structural -eq 'Complete' })
    $overall = 'Unknown'
    if ($fit -eq 'Unsupported') { $overall = 'Unsupported' }
    elseif ($fit -eq 'Ok' -and $required.Count -gt 0) {
        if ($completeRequired.Count -eq $required.Count) { $overall = 'Complete' }
        elseif ($completeRequired.Count -eq 0) { $overall = 'Missing' }
        else { $overall = 'Partial' }
    }

    $setupOverall = 'Unknown'
    if (@($rows | Where-Object { $_.Setup -eq 'CalibrationRequired' }).Count -gt 0) { $setupOverall = 'CalibrationRequired' }
    elseif (@($rows | Where-Object { $_.Setup -eq 'FirstRunRequired' }).Count -gt 0) { $setupOverall = 'FirstRunRequired' }
    elseif ($rows.Count -gt 0 -and @($rows | Where-Object { $_.Setup -ne 'NotRequired' }).Count -eq 0) { $setupOverall = 'NotRequired' }

    return [pscustomobject]@{
        ProfileId       = [string]$Contract.ProfileId
        Structural      = $overall
        Setup           = $setupOverall
        Verification    = 'NotVerified'
        # High only for a contract a person reviewed. A contract read from the game's own file is Medium: not reviewed.
        Confidence      = $(if ([string]$Contract.Evidence.ReviewState -eq 'Reviewed') { 'High' } else { 'Medium' })
        Why             = $(if ($overall -ne 'Unknown') { '' } elseif ([string]$Facts.Why) { [string]$Facts.Why } elseif ($fit -eq 'Ok') { 'NoControls' } else { '' })
        Controls        = @($rows)
        MissingControls = @($required | Where-Object { $_.Structural -eq 'Missing' } | ForEach-Object { $_.Meaning })
        # Controls the game lists but TPM cannot say it needs (Test, Service, Coin, and ones shown only after another setting).
        OptionalMissingControls = @($rows | Where-Object { $_.Requirement -eq 'Optional' -and $_.Structural -eq 'Missing' } | ForEach-Object { $_.Meaning })
        ReadOnly        = $true
    }
}

# Why TPM cannot tell what a game needs, in plain words (a phrase that continues "TPM cannot tell which controls this game needs").
function Get-TpmControlCoverageWhyText {
    param([string]$Why)
    switch ($Why) {
        'NoGameFile'       { return 'TeknoParrot''s own file for this game was not found' }
        'NoControls'       { return 'TPM does not recognize the names this game uses for its player 1 controls' }
        'DifferentVersion' { return 'its saved settings are for a different version of the game file than TeknoParrot has now. Open it once in TeknoParrotUI' }
        'Unreadable'       { return 'its settings file could not be read' }
        'NoProfile'        { return 'it has no settings file yet' }
        default            { return '' }
    }
}

# Plain-language lines for one inventory. Names the controls that are still needed and never calls the game ready.
function Get-TpmControlCoverageLines {
    param([Parameter(Mandatory)]$Inventory)

    $lines = New-Object System.Collections.ArrayList
    switch ([string]$Inventory.Structural) {
        'Complete'    { [void]$lines.Add('Every control this game needs is set up.') }
        'Partial'     { [void]$lines.Add('Some controls this game needs are not set up yet.') }
        'Missing'     { [void]$lines.Add('The controls this game needs are not set up yet.') }
        'Unsupported' { [void]$lines.Add('This game uses an input type TPM cannot check.') }
        default {
            $whyText = Get-TpmControlCoverageWhyText -Why ([string]$Inventory.Why)
            [void]$lines.Add($(if ($whyText) { 'TPM cannot tell which controls this game needs: ' + $whyText + '.' } else { 'TPM cannot tell which controls this game needs.' }))
        }
    }
    $missing = @($Inventory.MissingControls)
    if ($missing.Count -gt 0) { [void]$lines.Add('Still needed: ' + ($missing -join ', ') + '.') }
    $optional = @($Inventory.OptionalMissingControls)
    if ($optional.Count -gt 0) { [void]$lines.Add('Not set up, and TPM cannot tell if the game needs them: ' + ($optional -join ', ') + '.') }
    if ([string]$Inventory.Confidence -eq 'Medium') { [void]$lines.Add('TPM read this list from TeknoParrot''s own file for the game. A person has not checked it.') }
    [void]$lines.Add('TPM has not tested them in a game, so it cannot say the game is ready.')
    return @($lines)
}

# Reads TeknoParrot's own game file (GameProfiles) for one code. Returns $null when it is missing or cannot be read.
# Sha256 is lower-case hex, the identity a contract derived from this file is bound to.
function Read-TpmGameTemplate {
    param([Parameter(Mandatory)][string]$Code, [string]$GameProfilesDir = '')
    if ([string]::IsNullOrWhiteSpace($GameProfilesDir) -or $Code -ne [System.IO.Path]::GetFileName($Code) -or $Code -match '[:*?"<>|]') { return $null }
    $path = Join-Path $GameProfilesDir "$Code.xml"
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return $null }
    try {
        $doc = Read-Xml $path
        if ($null -eq $doc.GameProfile) { return $null }
        return [pscustomobject]@{ Doc = $doc; Path = $path; Sha256 = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant() }
    } catch { return $null }
}

# What the game file says about itself. A saved game profile is only compared with it when all three agree.
function Get-TpmTemplateIdentity {
    param([Parameter(Mandatory)]$TemplateDoc)
    $text = { param($Name) $n = $TemplateDoc.GameProfile.SelectSingleNode($Name); if ($n) { $n.InnerText.Trim() } else { '' } }
    $revision = $null
    $revisionText = & $text 'GameProfileRevision'
    if ($revisionText) { [void][int]::TryParse($revisionText, [ref]$revision) }
    return [pscustomobject]@{ ExpectedExecutableName = (& $text 'ExecutableName'); ExpectedEmulationProfile = (& $text 'EmulationProfile'); ExpectedGameProfileRevision = $revision }
}

# Builds a contract from TeknoParrot's own game file: the controls the game lists for player 1 and the cabinet, named by
# the game's own button names. Nobody has reviewed it, so Evidence says PendingReview; the revision and hash tie it to this file.
# Required = a player control the game always shows. Optional = Test, Service, Coin, and controls the game shows only when
# another setting asks for them: TPM cannot tell whether the game needs those. Returns $null when the file lists no such control.
function Get-TpmDerivedControlContract {
    param([Parameter(Mandatory)][string]$Code, [Parameter(Mandatory)]$TemplateDoc, [Parameter(Mandatory)][string]$TemplateSha256)

    $groups = [ordered]@{}
    foreach ($node in @(Get-ButtonNodes $TemplateDoc)) {
        $mappingNode = $node.SelectSingleNode('InputMapping')
        if ($null -eq $mappingNode -or [string]::IsNullOrWhiteSpace($mappingNode.InnerText)) { continue }
        $mapping = $mappingNode.InnerText.Trim()
        if (-not $groups.Contains($mapping)) { $groups[$mapping] = New-Object System.Collections.ArrayList }
        [void]$groups[$mapping].Add($node)
    }
    $controls = New-Object System.Collections.ArrayList
    foreach ($mapping in $groups.Keys) {
        $nodes = @($groups[$mapping])
        $nameNode = $nodes[0].SelectSingleNode('ButtonName')
        $label = if ($nameNode -and -not [string]::IsNullOrWhiteSpace($nameNode.InnerText)) { $nameNode.InnerText.Trim() } else { $mapping }
        if (-not (Test-TpmMappingInPlayerOneScope -Mapping $mapping -Label $label)) { continue }
        $isAxis = @($nodes | Where-Object { $a = $_.SelectSingleNode('AnalogType'); $a -and -not [string]::IsNullOrWhiteSpace($a.InnerText) -and $a.InnerText.Trim() -ne 'None' }).Count -gt 0
        $onlyWhenAsked = @($nodes | Where-Object { $v = $_.SelectSingleNode('VisibleWhen'); $v -and -not [string]::IsNullOrWhiteSpace($v.InnerText) }).Count -eq $nodes.Count
        $isCabinet = ($mapping -match '^(Test|Service\d*|Coin\d+)$')
        [void]$controls.Add([pscustomobject]@{
            ControlId   = $mapping
            Kind        = $(if ($isAxis) { 'Axis' } else { 'Button' })
            Meaning     = $label
            Requirement = $(if ($isCabinet -or $onlyWhenAsked) { 'Optional' } else { 'Required' })
            Bindable    = $true
            Scope       = $(if ($isCabinet) { 'Cabinet' } else { 'Player' })
        })
    }
    if ($controls.Count -eq 0) { return $null }

    $identity = Get-TpmTemplateIdentity -TemplateDoc $TemplateDoc
    $id = $Code.ToLowerInvariant()
    if ($id.Length -gt 50) { $id = $id.Substring(0, 50) }
    return [pscustomobject]@{
        ContractVersion   = 'TpmControllerCapability/v1'
        MinReaderVersion  = 1
        ProfileId         = ($id + '-derived')
        ProfileRevision   = 1
        ControllerContext = [pscustomobject]@{ DeviceClass = 'Unknown'; PlayerSlot = 'P1'; SelectionSource = 'Unset' }
        SemanticControls  = @($controls)
        Evidence          = [pscustomobject]@{ Origin = 'UserProvided'; ReviewState = 'PendingReview'; ReviewedUtc = $null; SourceNote = 'Read from the game file TeknoParrot ships; no person has reviewed it.' }
        # For a derived contract the contract revision is the game file's own revision.
        GameContracts     = @([pscustomobject]@{ GameProfileId = $Code; GameProfileHash = $TemplateSha256; ContractRevision = $(if ($null -ne $identity.ExpectedGameProfileRevision -and $identity.ExpectedGameProfileRevision -ge 1) { [int]$identity.ExpectedGameProfileRevision } else { 1 }) })
    }
}

# Picks the contract for one game and reads the facts against it. The reviewed contract wins when the saved profile is the
# reviewed revision; otherwise the contract comes from TeknoParrot's own game file. Contract is $null, with Why, when
# neither exists. Read-only.
function Get-TpmGameControlContract {
    param([Parameter(Mandatory)][string]$Code, $UserDoc = $null, $Template = $null)

    $reviewed = Get-TpmControlCoverageContract -Code $Code
    $reviewedFacts = $null
    if ($null -ne $reviewed) {
        $reviewedFacts = Get-TpmControlBindingFacts -Doc $UserDoc -Contract $reviewed -Code $Code
        if ($reviewedFacts.Fit -ne 'Unknown') { return [pscustomobject]@{ Contract = $reviewed; Facts = $reviewedFacts; Source = 'Reviewed'; Why = '' } }
    }
    if ($null -ne $Template) {
        $derived = Get-TpmDerivedControlContract -Code $Code -TemplateDoc $Template.Doc -TemplateSha256 $Template.Sha256
        if ($null -eq $derived) { return [pscustomobject]@{ Contract = $null; Facts = $null; Source = 'None'; Why = 'NoControls' } }
        $facts = Get-TpmControlBindingFacts -Doc $UserDoc -Contract $derived -Code $Code -Identity (Get-TpmTemplateIdentity -TemplateDoc $Template.Doc)
        return [pscustomobject]@{ Contract = $derived; Facts = $facts; Source = 'Derived'; Why = '' }
    }
    if ($null -ne $reviewed) { return [pscustomobject]@{ Contract = $reviewed; Facts = $reviewedFacts; Source = 'Reviewed'; Why = '' } }
    return [pscustomobject]@{ Contract = $null; Facts = $null; Source = 'None'; Why = 'NoGameFile' }
}

# Reads the profile for one code (the real UserProfile, otherwise the GameProfiles template) and returns its inventory,
# or $null when there is neither a reviewed contract nor a game file to read one from. Read-only.
function Get-TpmControlCoverage {
    param(
        [Parameter(Mandatory)][string]$Code,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [string]$GameProfilesDir = ''
    )

    $doc = Read-ControlReadinessProfileDocument -Code $Code -UserProfilesDir $UserProfilesDir -GameProfilesDir $GameProfilesDir
    $resolved = Get-TpmGameControlContract -Code $Code -UserDoc $doc -Template (Read-TpmGameTemplate -Code $Code -GameProfilesDir $GameProfilesDir)
    if ($null -eq $resolved.Contract) { return $null }
    return Get-TpmControlCoverageInventory -Contract $resolved.Contract -Facts $resolved.Facts
}

# The audit of many games: one row per registered game, and the counts. Profiles are the registered UserProfile files.
# A game TPM cannot read a contract for is Unknown with the reason; nothing is guessed. Read-only.
function Get-TpmControlCoverageAudit {
    param([Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Profiles, [string]$GameProfilesDir = '')

    $rows = New-Object System.Collections.ArrayList
    foreach ($file in @($Profiles)) {
        $code = [string]$file.BaseName
        $row = [pscustomobject]@{ Code = $code; Title = $code; Structural = 'Unknown'; Confidence = 'None'; Why = ''; Missing = @(); OptionalMissing = @() }
        try { $doc = Read-Xml $file.FullName; if ($null -eq $doc.GameProfile) { throw 'no profile' } } catch { $row.Why = 'Unreadable'; [void]$rows.Add($row); continue }
        try { $row.Title = Get-TpmProfileFriendlyTitle -Doc $doc -BaseName $code } catch { $row.Title = $code }
        $resolved = Get-TpmGameControlContract -Code $code -UserDoc $doc -Template (Read-TpmGameTemplate -Code $code -GameProfilesDir $GameProfilesDir)
        if ($null -eq $resolved.Contract) { $row.Why = $resolved.Why; [void]$rows.Add($row); continue }
        $inventory = Get-TpmControlCoverageInventory -Contract $resolved.Contract -Facts $resolved.Facts
        $row.Structural = $inventory.Structural; $row.Confidence = $inventory.Confidence; $row.Why = $inventory.Why
        $row.Missing = @($inventory.MissingControls); $row.OptionalMissing = @($inventory.OptionalMissingControls)
        [void]$rows.Add($row)
    }
    $all = @($rows)
    $count = { param($State) @($all | Where-Object Structural -eq $State).Count }
    return [pscustomobject]@{
        Total = $all.Count; Complete = (& $count 'Complete'); Partial = (& $count 'Partial'); Missing = (& $count 'Missing'); Unknown = (& $count 'Unknown'); Unsupported = (& $count 'Unsupported')
        Rows = $all; ReadOnly = $true
    }
}

# The plain screen for an audit: counts first, game names behind Details. Used by the Propagate Controls check and the Library health check.
function Get-TpmControlCoverageAuditSummary {
    param([Parameter(Mandatory)]$Audit)

    $done = New-Object System.Collections.Generic.List[string]
    [void]$done.Add(('Games with every control the game lists set up: {0} of {1}.' -f $Audit.Complete, $Audit.Total))
    if ($Audit.Partial -gt 0) { [void]$done.Add(('Games with some of their controls set up: {0}.' -f $Audit.Partial)) }
    if ($Audit.Missing -gt 0) { [void]$done.Add(('Games with none of their controls set up: {0}.' -f $Audit.Missing)) }
    $needs = New-Object System.Collections.Generic.List[string]
    if ($Audit.Unknown -gt 0) { [void]$needs.Add(('Games TPM cannot check: {0}. Details say why for each one.' -f $Audit.Unknown)) }
    if ($Audit.Unsupported -gt 0) { [void]$needs.Add(('Games that use an input type TPM cannot check: {0}.' -f $Audit.Unsupported)) }

    $blocks = New-Object System.Collections.Generic.List[object]
    $listOf = {
        param($State, $Heading, $Format)
        $set = @($Audit.Rows | Where-Object Structural -eq $State | Sort-Object Title)
        if ($set.Count -gt 0) { [void]$blocks.Add(@{ Heading = ('{0} ({1})' -f $Heading, $set.Count); Lines = @($set | ForEach-Object { & $Format $_ }) }) }
    }
    & $listOf 'Partial' 'Some controls missing' { param($r) '{0}: still needed: {1}.' -f $r.Title, ($r.Missing -join ', ') }
    & $listOf 'Missing' 'No controls set up' { param($r) '{0}: still needed: {1}.' -f $r.Title, ($r.Missing -join ', ') }
    & $listOf 'Unknown' 'TPM cannot tell' { param($r) $w = Get-TpmControlCoverageWhyText -Why $r.Why; '{0}: {1}.' -f $r.Title, $(if ($w) { $w } else { 'no information' }) }
    & $listOf 'Unsupported' 'Input type TPM cannot check' { param($r) $r.Title }
    $note = 'TPM has not tested any game with a real controller. "Set up" means the buttons the game lists have a setting. It does not mean the game works. For most games the list of controls comes from TeknoParrot''s own game file, and a person has not checked it.'
    $attention = ($Audit.Partial + $Audit.Missing + $Audit.Unknown + $Audit.Unsupported) -gt 0
    return [pscustomobject]@{
        Title = 'Controls check. Nothing was changed.'; Status = $(if ($attention) { 'Attention' } else { 'Ok' }); Done = $done.ToArray(); Needs = $needs.ToArray()
        Next = 'Choose 2 in the Propagate Controls menu to set up games with your controller layout.'; Blocks = $blocks.ToArray(); Note = $note
    }
}

# The screen for the controls check (Propagate Controls choice 4).
function Invoke-TpmControlAuditScreen {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$GameProfilesDir)
    $files = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'Controls check game list' -EnumerationErrorAction SilentlyContinue | Sort-Object BaseName)
    if ($files.Count -eq 0) { Write-TpmText -Text 'No registered games were found.' -Color Yellow; return }
    $audit = Invoke-TpmProgressGroup -Title 'Controls check' -Action { Get-TpmControlCoverageAudit -Profiles $files -GameProfilesDir $GameProfilesDir }
    $summary = Get-TpmControlCoverageAuditSummary -Audit $audit
    Write-Log ('ControlsCheck: total={0} complete={1} partial={2} missing={3} unknown={4} unsupported={5}' -f $audit.Total, $audit.Complete, $audit.Partial, $audit.Missing, $audit.Unknown, $audit.Unsupported)
    Write-TpmOutcome -Title $summary.Title -Status $summary.Status -Done $summary.Done -Needs $summary.Needs -Next $summary.Next -DetailBlocks $summary.Blocks -DetailsNote $summary.Note
}
# =============================================================================
# END MODULE-READY SECTION: Controls coverage inventory
# =============================================================================

# =============================================================================
# BEGIN MODULE-READY SECTION: Outside mapping evidence review
# =============================================================================
# Read-only check of an outside per-game controller list (a RetroBat-style teknoparrot.yml the user already has; issue #304).
# The list is evidence for a person to review. Nothing here trusts it, applies it, bundles it or changes a profile. The only
# file this section can write is the details file the caller names. A game is held back, with a plain reason, when the list
# names it twice, names a game that is not installed, names a control the game does not have, uses a button name TPM does
# not know, or puts two game actions on one controller button. Every entry keeps its source line and original value, and
# is bound to the installed profile's name, revision and SHA-256, because the outside list itself has no revision.
# Depends on: Read-Xml, Write-TpmAtomicTextFile.

# Controller button names the outside list may use, and the five spelling mistakes known to be in it (looked up, never guessed).
function Get-TpmMappingPadTargets {
    return @('r3', 'l3', 'select', 'start', 'righttrigger', 'lefttrigger', 'rightshoulder', 'leftshoulder', 'south', 'east', 'west', 'north',
        'up', 'down', 'left', 'right', 'leftstickleft', 'leftstickright', 'leftstickup', 'leftstickdown',
        'rightstickleft', 'rightstickright', 'rightstickup', 'rightstickdown')
}

function ConvertTo-TpmMappingTarget {
    param([string]$Value)
    $text = ([string]$Value).Trim().Trim('"', "'")
    $result = [pscustomobject]@{ Target = $text; Valid = $false; Normalized = $false }
    if ($text -eq '') { return $result }
    $typos = @{ 'rigthstickup' = 'rightstickup'; 'rigthstickdown' = 'rightstickdown'; 'leftttrigger' = 'lefttrigger'; 'lefttshoulder' = 'leftshoulder'; 'righttickleft' = 'rightstickleft' }
    $lower = $text.ToLowerInvariant()
    if ($text -match '^kb_[A-Za-z0-9]+$') { $result.Valid = $true; return $result }
    if ($typos.ContainsKey($lower)) { $result.Target = $typos[$lower]; $result.Valid = $true; $result.Normalized = $true; return $result }
    if ((Get-TpmMappingPadTargets) -contains $lower) { $result.Target = $lower; $result.Valid = $true }
    return $result
}

# Reads the outside list. It is a plain two-level text file: a game name at the left edge, then indented "Control: button # label"
# lines. Anything else is counted as an unread line, never guessed at.
function Read-TpmMappingEvidenceFile {
    param([Parameter(Mandatory)][string]$Path)
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { $hash = ([System.BitConverter]::ToString($sha.ComputeHash($bytes)) -replace '-', '') } finally { $sha.Dispose() }
    $text = (New-Object System.Text.UTF8Encoding $false).GetString($bytes).TrimStart([char]0xFEFF)
    $entries = New-Object System.Collections.ArrayList
    $unread = New-Object System.Collections.ArrayList
    $current = $null
    $lineNumber = 0
    $allLines = @($text -split "\r?\n")
    foreach ($line in $allLines) {
        $lineNumber++
        if ([string]::IsNullOrWhiteSpace($line) -or $line.TrimStart().StartsWith('#')) { continue }
        if ($line -match '^([^\s#:][^:#]*):\s*(#.*)?$') {
            $current = [pscustomobject]@{ Name = $Matches[1].Trim().Trim('"', "'"); Line = $lineNumber; Fields = (New-Object System.Collections.ArrayList); Players = $null }
            [void]$entries.Add($current)
        } elseif ($null -ne $current -and $line -match '^\s+([A-Za-z0-9_]+):[ \t]*([^\s#]*)[ \t]*(?:#[ \t]*(.*))?$') {
            $label = if ($Matches.ContainsKey(3)) { [string]$Matches[3] } else { '' }
            if ($Matches[1] -eq 'Players') { $current.Players = $Matches[2]; continue }
            [void]$current.Fields.Add([pscustomobject]@{ Key = $Matches[1]; Value = $Matches[2]; Label = $label.Trim(); Line = $lineNumber })
        } else {
            [void]$unread.Add($lineNumber)
        }
    }
    return [pscustomobject]@{ FileName = [System.IO.Path]::GetFileName($Path); Sha256 = $hash; LineCount = $allLines.Count; Entries = @($entries); UnreadLines = @($unread) }
}

# True for the controls one player and the cabinet need on the first controller: Test, Service, Coin 1, player 1 buttons and
# the analog axes. An axis whose own label names another player is not counted.
function Test-TpmMappingInPlayerOneScope {
    param([string]$Mapping, [string]$Label = '')
    if ($Mapping -notmatch '^(Test|Service\d*|Coin1|P1\w*|JvsTwoP1\w*|Analog\d+)$') { return $false }
    if ($Mapping -like 'Analog*' -and $Label -match '\b(P|Player\s*)[2-6]\b') { return $false }
    return $true
}

function Get-TpmMappingEvidenceReview {
    param([Parameter(Mandatory)]$Evidence, [Parameter(Mandatory)][string]$GameProfilesDir)
    $profiles = @{}
    foreach ($file in @(Get-ChildItem -LiteralPath $GameProfilesDir -Filter '*.xml' -File -ErrorAction SilentlyContinue)) { $profiles[$file.BaseName.ToLowerInvariant()] = $file }
    $nameCounts = @{}
    foreach ($entry in @($Evidence.Entries)) { $k = $entry.Name.ToLowerInvariant(); $nameCounts[$k] = 1 + [int]$nameCounts[$k] }
    $mouseKey = '^(mouseleft|mouseright|mousemiddle|button4|button5)(_\d+)?$'

    $results = New-Object System.Collections.ArrayList
    foreach ($entry in @($Evidence.Entries | Sort-Object { $_.Name.ToLowerInvariant() }, Line)) {
        $name = $entry.Name.ToLowerInvariant()
        $profileKey = $name
        $variant = ''
        if (-not $profiles.ContainsKey($name)) {
            $cut = $name.LastIndexOf('_')
            if ($cut -gt 0 -and $profiles.ContainsKey($name.Substring(0, $cut))) { $profileKey = $name.Substring(0, $cut); $variant = $name.Substring($cut + 1) }
        }
        $problems = New-Object System.Collections.ArrayList
        $addProblem = { param($Code, $Field) [void]$problems.Add([pscustomobject]@{ Code = $Code; Field = $Field }) }
        if ($nameCounts[$name] -gt 1) { & $addProblem 'DuplicateEntry' $entry.Name }

        $gameFile = $profiles[$profileKey]
        $identity = $null
        $gameMappings = @{}
        if ($null -eq $gameFile) {
            & $addProblem 'NotInstalled' $entry.Name
        } else {
            try {
                $doc = Read-Xml $gameFile.FullName
                foreach ($node in @($doc.SelectNodes('/GameProfile/JoystickButtons/JoystickButtons'))) {
                    $mapNode = $node.SelectSingleNode('InputMapping')
                    if ($null -eq $mapNode -or [string]::IsNullOrWhiteSpace($mapNode.InnerText)) { continue }
                    $buttonName = $node.SelectSingleNode('ButtonName')
                    $gameMappings[$mapNode.InnerText.Trim()] = $(if ($buttonName) { $buttonName.InnerText } else { '' })
                }
                $revNode = $doc.SelectSingleNode('/GameProfile/GameProfileRevision')
                $identity = [ordered]@{ GameProfileFile = $gameFile.Name; GameProfileRevision = $(if ($revNode) { $revNode.InnerText.Trim() } else { '' }); GameProfileSha256 = (Get-FileHash -LiteralPath $gameFile.FullName -Algorithm SHA256).Hash }
            } catch {
                & $addProblem 'ProfileUnreadable' $gameFile.Name
            }
        }

        $proposals = New-Object System.Collections.ArrayList
        $normalized = New-Object System.Collections.ArrayList
        $seen = @{}
        $unmapped = 0
        foreach ($field in @($entry.Fields)) {
            $isMouse = $field.Key -match $mouseKey
            $mapping = if ($isMouse) { $field.Value } else { $field.Key }
            $rawTarget = if ($isMouse) { $field.Key } else { $field.Value }
            if ([string]::IsNullOrWhiteSpace($mapping) -or [string]::IsNullOrWhiteSpace($rawTarget)) { $unmapped++; continue }
            $seenKey = $field.Key.ToLowerInvariant()
            if ($seen.ContainsKey($seenKey)) { & $addProblem 'DuplicateField' $field.Key; continue }
            $seen[$seenKey] = $true
            $target = if ($isMouse) { [pscustomobject]@{ Target = $rawTarget.ToLowerInvariant(); Valid = $true; Normalized = $false } } else { ConvertTo-TpmMappingTarget $rawTarget }
            if (-not $target.Valid) { & $addProblem 'UnknownTarget' $field.Key; continue }
            if ($null -ne $identity -and -not $gameMappings.ContainsKey($mapping)) { & $addProblem 'FieldNotInGame' $mapping }
            if ($target.Normalized) { [void]$normalized.Add([pscustomobject]@{ Field = $mapping; Written = $rawTarget; Used = $target.Target }) }
            [void]$proposals.Add([pscustomobject]([ordered]@{ Mapping = $mapping; Target = $target.Target; SourceValue = $rawTarget; Label = $field.Label; SourceLine = $field.Line }))
        }

        # Two different game actions on one controller button, inside the first-controller controls only.
        $groups = @{}
        foreach ($p in $proposals) {
            if (-not (Test-TpmMappingInPlayerOneScope -Mapping $p.Mapping -Label $p.Label)) { continue }
            if (-not $groups.ContainsKey($p.Target)) { $groups[$p.Target] = New-Object System.Collections.ArrayList }
            [void]$groups[$p.Target].Add($p.Mapping)
        }
        foreach ($target in @($groups.Keys | Sort-Object)) {
            $actions = @($groups[$target] | Sort-Object -Unique)
            if ($actions.Count -gt 1) { & $addProblem 'Collision' ($actions -join ' + ') }
        }

        # Game controls the list says nothing usable about (only judged for a whole-game entry, not a gun or pad variant).
        $missing = @()
        if ($variant -eq '' -and $null -ne $identity) {
            $covered = @{}
            foreach ($p in $proposals) { $covered[$p.Mapping] = $true }
            $missing = @($gameMappings.Keys | Where-Object { (Test-TpmMappingInPlayerOneScope -Mapping $_ -Label $gameMappings[$_]) -and -not $covered.ContainsKey($_) } | Sort-Object)
        }

        $reasons = @($problems | ForEach-Object { $_.Code } | Sort-Object -Unique)
        $status = if ($reasons.Count -gt 0) { 'Withheld' } elseif ($missing.Count -gt 0) { 'Partial' } else { 'ReadyForReview' }
        [void]$results.Add([pscustomobject]([ordered]@{
            Name = $entry.Name; Profile = $(if ($null -ne $gameFile) { $gameFile.BaseName } else { '' }); Variant = $variant; SourceLine = $entry.Line
            Status = $status; Reasons = $reasons; Problems = @($problems); Identity = $identity
            Proposals = @($proposals); Normalized = @($normalized); MissingFromList = $missing; UnmappedInSource = $unmapped
        }))
    }

    $all = @($results)
    $byReason = [ordered]@{}
    foreach ($code in @($all | ForEach-Object { $_.Reasons } | Sort-Object -Unique)) { $byReason[$code] = @($all | Where-Object { $_.Reasons -contains $code }).Count }
    return [pscustomobject]([ordered]@{
        Schema = 'TPM.MappingEvidenceReview.v1'
        Trust = 'NonAuthoritative'
        ReadOnly = $true
        Source = [ordered]@{ FileName = $Evidence.FileName; Sha256 = $Evidence.Sha256; LineCount = $Evidence.LineCount; UnreadLines = @($Evidence.UnreadLines) }
        Summary = [ordered]@{
            EntriesInList = $all.Count
            Installed = @($all | Where-Object { $_.Reasons -notcontains 'NotInstalled' }).Count
            ReadyForReview = @($all | Where-Object Status -eq 'ReadyForReview').Count
            Partial = @($all | Where-Object Status -eq 'Partial').Count
            Withheld = @($all | Where-Object Status -eq 'Withheld').Count
            WithheldByReason = $byReason
            ButtonsProposed = (@($all | ForEach-Object { $_.Proposals.Count }) | Measure-Object -Sum).Sum
            SpellingFixed = (@($all | ForEach-Object { $_.Normalized.Count }) | Measure-Object -Sum).Sum
        }
        Entries = $all
    })
}

function Get-TpmMappingEvidenceReviewLines {
    param([Parameter(Mandatory)]$Review)
    $s = $Review.Summary
    $lines = New-Object System.Collections.ArrayList
    [void]$lines.Add('Outside controller list check. Nothing was changed.')
    [void]$lines.Add(('File: {0}' -f $Review.Source.FileName))
    [void]$lines.Add(('Games in the list: {0}. Found in your TeknoParrot: {1}.' -f $s.EntriesInList, $s.Installed))
    [void]$lines.Add(('Ready for a person to review: {0}. Some controls missing from the list: {1}. Held back: {2}.' -f $s.ReadyForReview, $s.Partial, $s.Withheld))
    $words = [ordered]@{
        NotInstalled     = 'the game is not in your TeknoParrot'
        DuplicateEntry   = 'the list names the game twice'
        DuplicateField   = 'the list sets one control twice'
        FieldNotInGame   = 'the list sets a control the game does not have'
        UnknownTarget    = 'the list uses a button name TPM does not know'
        Collision        = 'two game actions share one controller button'
        ProfileUnreadable = 'the game file could not be read'
    }
    foreach ($code in $words.Keys) {
        if ($s.WithheldByReason.Contains($code)) { [void]$lines.Add(('  Held back, {0}: {1}' -f $words[$code], $s.WithheldByReason[$code])) }
    }
    if ($s.SpellingFixed -gt 0) { [void]$lines.Add(('Spelling mistakes in the list that TPM corrected: {0}.' -f $s.SpellingFixed)) }
    if (@($Review.Source.UnreadLines).Count -gt 0) { [void]$lines.Add(('Lines in the list TPM could not read: {0}.' -f @($Review.Source.UnreadLines).Count)) }
    [void]$lines.Add('This list comes from outside. TPM does not trust it, has not tested it, and has not used it in any game.')
    return @($lines)
}

# Command-line entry (-MappingEvidenceFile). Prints the plain lines and, when asked, writes the details file. Returns 0, or 1 when
# the check itself could not run.
function Invoke-TpmMappingEvidenceReport {
    param([Parameter(Mandatory)][string]$EvidencePath, [string]$TeknoParrotRoot = '', [string]$JsonPath = '')
    $script:TpmValidationReportActive = $true   # Write-Log writes nothing while this is set
    try {
        if (-not (Test-Path -LiteralPath $EvidencePath -PathType Leaf)) { throw 'The list file was not found.' }
        $profilesDir = Join-Path $TeknoParrotRoot 'GameProfiles'
        if ([string]::IsNullOrWhiteSpace($TeknoParrotRoot) -or -not (Test-Path -LiteralPath $profilesDir -PathType Container)) { throw 'Give the TeknoParrot folder (the one that holds GameProfiles) with -ValidationRoot.' }
        if ($JsonPath -and (Test-Path -LiteralPath $JsonPath -PathType Leaf) -and ((Get-Content -LiteralPath $JsonPath -Raw -ErrorAction Stop) -notmatch 'TPM\.MappingEvidenceReview\.v1')) { throw 'The details file already exists and is not one of these reports; it was left unchanged.' }
        $review = Get-TpmMappingEvidenceReview -Evidence (Read-TpmMappingEvidenceFile -Path $EvidencePath) -GameProfilesDir $profilesDir
        if ($JsonPath) { Write-TpmAtomicTextFile -Path $JsonPath -Text ($review | ConvertTo-Json -Depth 8) -Operation 'mapping evidence details file' }
        foreach ($line in @(Get-TpmMappingEvidenceReviewLines -Review $review)) { Write-Host $line }
        if ($JsonPath) { Write-Host ('Details file: ' + $JsonPath) }
        return 0
    } catch {
        Write-Host ('The outside list check could not run: ' + $_.Exception.Message) -ForegroundColor Red
        return 1
    }
}
# =============================================================================
# END MODULE-READY SECTION: Outside mapping evidence review
# =============================================================================

# =============================================================================
# VALIDATION REPORT (read-only, no questions; issue #276)
# =============================================================================
# -ValidationReport prints what a release or arcade test needs to know about this copy and one TeknoParrot folder. It never
# asks a question and never changes TeknoParrot, game profiles, saved settings or the log. The only file it can write is the
# JSON file the caller names with -ValidationJsonPath. Exit code: 0 pass, 3 action required, 4 validation failed, 1 the report
# itself could not be made.

function Get-TpmValidationShippedFiles {
    param([Parameter(Mandatory)][string]$ScriptRoot)
    $names = @('scripts\TpmProgress.psm1', 'scripts\TpmRequiredPatchEngine.ps1', 'scripts\TpmRequiredPatchRecipes.json', 'tools\TpmAutoUpdate.Core.psm1', 'tools\Invoke-TpmAutoUpdate.ps1', 'TeknoParrot-Manager-CHANGELOG.txt', 'TeknoParrot-Manager-README.txt', 'TeknoParrot-Manager-QuickStart.txt')
    $missing = @($names | Where-Object { -not (Test-Path -LiteralPath (Join-Path $ScriptRoot $_) -PathType Leaf) })
    return [pscustomobject]@{ Checked = $names.Count; Missing = $missing }
}

function Get-TpmValidationReport {
    param(
        [Parameter(Mandatory)][string]$ScriptPath,
        [Parameter(Mandatory)][string]$ScriptRoot,
        [string]$TeknoParrotRoot = '',
        [string]$JsonPath = ''
    )
    $failures = New-Object System.Collections.Generic.List[string]
    $actions = New-Object System.Collections.Generic.List[string]

    $scriptHash = ''
    try { $scriptHash = (Get-FileHash -LiteralPath $ScriptPath -Algorithm SHA256 -ErrorAction Stop).Hash } catch { [void]$actions.Add('This script file could not be hashed.') }

    # Saved settings: read only. The saved PostgreSQL password is reported as yes or no, never shown.
    $configPath = ''
    $configState = 'None'
    $savedConfig = $null
    try {
        $configPath = [string](Get-TpmOwnedConfigPathForRoot -TeknoParrotRoot $TeknoParrotRoot)
        if (-not $configPath -or -not (Test-Path -LiteralPath $configPath -PathType Leaf)) { $configPath = [string](Find-TpmSavedConfigPath -ScriptRoot $ScriptRoot) }
        if ($configPath -and (Test-Path -LiteralPath $configPath -PathType Leaf)) {
            try {
                $savedConfig = Get-Content -LiteralPath $configPath -Raw -Encoding UTF8 | ConvertFrom-Json
                $configState = if ($null -eq $savedConfig) { 'Unreadable' } else { 'Readable' }
            } catch { $configState = 'Unreadable' }
        }
    } catch { $configState = 'Unreadable' }
    if ($configState -eq 'Unreadable') { [void]$actions.Add('The saved settings file could not be read.') }
    elseif ($configState -eq 'None') { [void]$actions.Add('No saved settings file was found; unattended runs need one.') }
    $hasSavedPassword = ($configState -eq 'Readable' -and $null -ne $savedConfig.PSObject.Properties['PostgresSuperPasswordEncrypted'] -and -not [string]::IsNullOrWhiteSpace([string]$savedConfig.PostgresSuperPasswordEncrypted))

    $root = $TeknoParrotRoot
    $rootSource = 'Parameter'
    if ([string]::IsNullOrWhiteSpace($root)) {
        $rootSource = 'None'
        if ($configState -eq 'Readable' -and $savedConfig.TeknoParrotRoot) {
            $root = if ($savedConfig.TeknoParrotRoot -is [array]) { [string]$savedConfig.TeknoParrotRoot[0] } else { [string]$savedConfig.TeknoParrotRoot }
            $rootSource = 'Saved settings'
        }
    }
    $rootProblem = Get-TpmTeknoParrotRootProblem -Path $root
    if ($rootProblem -eq 'NoFolder') { [void]$failures.Add($(if ($rootSource -eq 'None') { 'No TeknoParrot folder was given and none is saved. Use -ValidationRoot.' } else { 'The TeknoParrot folder was not found: ' + $root })) }
    elseif ($rootProblem -eq 'NoExe') { [void]$failures.Add('TeknoParrotUi.exe is not in the TeknoParrot folder: ' + $root) }

    $shipped = Get-TpmValidationShippedFiles -ScriptRoot $ScriptRoot
    foreach ($missingName in @($shipped.Missing)) { [void]$failures.Add('A file that ships with TeknoParrot Manager is missing: ' + $missingName) }
    $crosshairDir = Join-Path $ScriptRoot 'Crosshairs'
    $crosshairCount = if (Test-Path -LiteralPath $crosshairDir -PathType Container) { @(Get-ChildItem -LiteralPath $crosshairDir -Filter '*.png' -File -ErrorAction SilentlyContinue).Count } else { 0 }

    $templateCount = 0; $registered = 0; $unreadable = 0; $emptyPath = 0; $missingPath = 0
    $itGames = 0; $itNotSetUp = 0
    $rawInput = [ordered]@{ Supported = 0; Unsupported = 0; Unknown = 0 }
    $rawTrackball = [ordered]@{ Supported = 0; Unsupported = 0; Unknown = 0 }
    $wizardState = 'NotChecked'
    $warnings = $null
    if ($rootProblem -eq '') {
        $gameProfilesDir = Join-Path $root 'GameProfiles'
        $userProfilesDir = Join-Path $root 'UserProfiles'
        if (Test-Path -LiteralPath $gameProfilesDir -PathType Container) {
            $templateCount = @(Get-ChildItem -LiteralPath $gameProfilesDir -Filter '*.xml' -File -ErrorAction SilentlyContinue).Count
        } else { [void]$failures.Add('The GameProfiles folder is missing from the TeknoParrot folder.') }
        $wizardState = [string](Get-TeknoParrotWizardState -TeknoParrotRoot $root).State
        if ($wizardState -ne 'Complete') { [void]$actions.Add('TeknoParrot first-time setup is not marked complete (' + $wizardState + ').') }
        if (Test-Path -LiteralPath $userProfilesDir -PathType Container) {
            foreach ($pf in @(Get-ChildItem -LiteralPath $userProfilesDir -Filter '*.xml' -File -ErrorAction SilentlyContinue)) {
                $registered++
                try {
                    $doc = Read-Xml $pf.FullName
                    if (-not $doc.GameProfile) { $unreadable++; continue }
                } catch { $unreadable++; continue }
                $gamePathNode = $doc.GameProfile.SelectSingleNode('GamePath')
                $gamePath = if ($gamePathNode) { ([string]$gamePathNode.InnerText).Trim() } else { '' }
                if ([string]::IsNullOrWhiteSpace($gamePath)) { $emptyPath++ }
                elseif (-not (Test-Path -LiteralPath $gamePath -PathType Leaf)) { $missingPath++ }
                if (Test-GameNeedsPostgres $doc) {
                    $itGames++
                    if (-not (Test-TpmPostgresSettingsComplete -Doc $doc)) { $itNotSetUp++ }
                }
                $capability = Get-ProfileRawInputCapability -Doc $doc
                $rawInput[[string]$capability.RawInput]++
                $rawTrackball[[string]$capability.RawInputTrackball]++
            }
            try { $warnings = Get-CompatibilityWarnings -UserProfilesDir $userProfilesDir -TeknoParrotRoot $root }
            catch { [void]$actions.Add('The compatibility check could not finish: ' + $_.Exception.Message) }
        }
        if ($unreadable -gt 0) { [void]$actions.Add(('{0} registered profile(s) could not be read.' -f $unreadable)) }
        if ($emptyPath + $missingPath -gt 0) { [void]$actions.Add(('{0} registered game(s) have no game file at the saved path.' -f ($emptyPath + $missingPath))) }
        if ($itNotSetUp -gt 0) { [void]$actions.Add(('{0} game(s) still need PostgreSQL settings.' -f $itNotSetUp)) }
    }
    $warningCounts = [ordered]@{ PathTooLong = 0; DllMismatch = 0; GpuIncompatible = 0; BiosMissing = 0; ComponentMissing = 0 }
    if ($null -ne $warnings) {
        $warningCounts.PathTooLong = @($warnings.PathTooLong).Count
        $warningCounts.DllMismatch = @($warnings.DllMismatch).Count
        $warningCounts.GpuIncompatible = @($warnings.GpuIncompatible).Count
        $warningCounts.BiosMissing = @($warnings.BiosMissing).Count
        $warningCounts.ComponentMissing = @($warnings.ExeMissing).Count
        $warningTotal = $warningCounts.PathTooLong + $warningCounts.DllMismatch + $warningCounts.GpuIncompatible + $warningCounts.BiosMissing + $warningCounts.ComponentMissing
        if ($warningTotal -gt 0) { [void]$actions.Add(('{0} compatibility warning(s) were found.' -f $warningTotal)) }
    }

    $status = if ($failures.Count -gt 0) { 'Failed' } elseif ($actions.Count -gt 0) { 'ActionRequired' } else { 'Pass' }
    $exitCode = switch ($status) { 'Failed' { 4 } 'ActionRequired' { 3 } default { 0 } }
    return [ordered]@{
        Schema = 'TPM.ValidationReport.v1'
        GeneratedUtc = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ', [System.Globalization.CultureInfo]::InvariantCulture)
        Result = $status
        ExitCode = $exitCode
        Manager = [ordered]@{ Version = $ScriptVersion; Label = $ReleaseCandidateLabel; Display = (Get-ManagerDisplayVersion); ScriptSha256 = $scriptHash }
        Environment = [ordered]@{ PowerShell = $PSVersionTable.PSVersion.ToString(); Edition = [string]$PSVersionTable.PSEdition; Os = [System.Environment]::OSVersion.VersionString; Administrator = [bool](Test-RunningAsAdministrator) }
        TeknoParrot = [ordered]@{ Root = $root; RootSource = $rootSource; RootProblem = $rootProblem; WizardState = $wizardState; GameTemplates = $templateCount }
        Settings = [ordered]@{ Path = $configPath; State = $configState; SavedPostgresPassword = $hasSavedPassword }
        Package = [ordered]@{ ShippedFilesChecked = $shipped.Checked; ShippedFilesMissing = @($shipped.Missing); Crosshairs = $crosshairCount }
        Library = [ordered]@{ Registered = $registered; Unreadable = $unreadable; NoGameFile = ($emptyPath + $missingPath); PostgresGames = $itGames; PostgresNotSetUp = $itNotSetUp }
        RawInput = [ordered]@{ RawInput = $rawInput; RawInputTrackball = $rawTrackball }
        CompatibilityWarnings = $warningCounts
        ActionRequired = @($actions)
        Failures = @($failures)
        FilesWritten = @(if ($JsonPath) { $JsonPath })
    }
}

function Format-TpmValidationReportText {
    param([Parameter(Mandatory)]$Report)
    $label = switch ([string]$Report.Result) { 'Pass' { 'PASS' } 'ActionRequired' { 'ACTION REQUIRED' } default { 'FAILED' } }
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add('TeknoParrot Manager validation report')
    [void]$lines.Add(('Result: {0} (exit code {1})' -f $label, $Report.ExitCode))
    [void]$lines.Add(('Version: {0}   Script SHA-256: {1}' -f $Report.Manager.Display, $Report.Manager.ScriptSha256))
    [void]$lines.Add(('PowerShell {0} ({1}) on {2}; administrator: {3}' -f $Report.Environment.PowerShell, $Report.Environment.Edition, $Report.Environment.Os, $(if ($Report.Environment.Administrator) { 'yes' } else { 'no' })))
    [void]$lines.Add(('TeknoParrot folder: {0} (from {1}){2}' -f $Report.TeknoParrot.Root, $Report.TeknoParrot.RootSource, $(if ($Report.TeknoParrot.RootProblem) { ' - problem: ' + $Report.TeknoParrot.RootProblem } else { '' })))
    [void]$lines.Add(('Saved settings: {0} ({1}); saved PostgreSQL password: {2}' -f $Report.Settings.Path, $Report.Settings.State, $(if ($Report.Settings.SavedPostgresPassword) { 'yes' } else { 'no' })))
    [void]$lines.Add(('TeknoParrot first-time setup: {0}; game templates: {1}' -f $Report.TeknoParrot.WizardState, $Report.TeknoParrot.GameTemplates))
    [void]$lines.Add(('Registered games: {0}; unreadable: {1}; no game file: {2}; PostgreSQL games: {3} ({4} not set up)' -f $Report.Library.Registered, $Report.Library.Unreadable, $Report.Library.NoGameFile, $Report.Library.PostgresGames, $Report.Library.PostgresNotSetUp))
    [void]$lines.Add(('RawInput: {0} supported, {1} unsupported, {2} unknown. RawInputTrackball: {3} supported, {4} unsupported, {5} unknown.' -f $Report.RawInput.RawInput.Supported, $Report.RawInput.RawInput.Unsupported, $Report.RawInput.RawInput.Unknown, $Report.RawInput.RawInputTrackball.Supported, $Report.RawInput.RawInputTrackball.Unsupported, $Report.RawInput.RawInputTrackball.Unknown))
    [void]$lines.Add(('Shipped files checked: {0}; missing: {1}; crosshair images: {2}' -f $Report.Package.ShippedFilesChecked, @($Report.Package.ShippedFilesMissing).Count, $Report.Package.Crosshairs))
    $warn = $Report.CompatibilityWarnings
    [void]$lines.Add(('Compatibility warnings: path too long {0}, wrong DLL {1}, graphics card {2}, missing BIOS {3}, missing component {4}' -f $warn.PathTooLong, $warn.DllMismatch, $warn.GpuIncompatible, $warn.BiosMissing, $warn.ComponentMissing))
    foreach ($item in @($Report.Failures)) { [void]$lines.Add('FAILED: ' + $item) }
    foreach ($item in @($Report.ActionRequired)) { [void]$lines.Add('Action required: ' + $item) }
    [void]$lines.Add($(if (@($Report.FilesWritten).Count -gt 0) { 'Files written by this report: ' + (@($Report.FilesWritten) -join ', ') } else { 'Files written by this report: none' }))
    return @($lines)
}

function Invoke-TpmValidationReport {
    param(
        [Parameter(Mandatory)][string]$ScriptPath,
        [Parameter(Mandatory)][string]$ScriptRoot,
        [string]$TeknoParrotRoot = '',
        [string]$JsonPath = ''
    )
    $script:TpmValidationReportActive = $true   # Write-Log writes nothing while this is set
    try {
        if ($JsonPath) {
            # Only a new file or an older copy of this report may be replaced, and the folder must already exist.
            if (-not (Test-Path -LiteralPath (Split-Path -Parent ([System.IO.Path]::GetFullPath($JsonPath))) -PathType Container)) { throw 'The folder for -ValidationJsonPath does not exist.' }
            if ((Test-Path -LiteralPath $JsonPath) -and ((Get-Content -LiteralPath $JsonPath -Raw -ErrorAction Stop) -notmatch 'TPM\.ValidationReport\.v1')) { throw 'The -ValidationJsonPath file already exists and is not a validation report; it was left unchanged.' }
        }
        $report = @(Get-TpmValidationReport -ScriptPath $ScriptPath -ScriptRoot $ScriptRoot -TeknoParrotRoot $TeknoParrotRoot -JsonPath $JsonPath)[-1]
        if ($JsonPath) { [System.IO.File]::WriteAllText($JsonPath, ($report | ConvertTo-Json -Depth 8), (New-Object System.Text.UTF8Encoding $false)) }
        foreach ($line in @(Format-TpmValidationReportText -Report $report)) { Write-Host $line }
        return [int]$report.ExitCode
    } catch {
        Write-Host ('The validation report could not be made: ' + $_.Exception.Message) -ForegroundColor Red
        return 1
    }
}

if ($ValidationReport) {
    exit (Invoke-TpmValidationReport -ScriptPath $PSCommandPath -ScriptRoot $PSScriptRoot -TeknoParrotRoot $ValidationRoot -JsonPath $ValidationJsonPath)
}

if ($MappingEvidenceFile) {
    exit (Invoke-TpmMappingEvidenceReport -EvidencePath $MappingEvidenceFile -TeknoParrotRoot $ValidationRoot -JsonPath $ValidationJsonPath)
}

$script:ActiveTpmWorkflowStatus = $null
$script:TpmWorkflowRendering = $false
Write-Log "Script started (v$ScriptVersion$(if ($Unattended) { ' [Unattended]' }))."

# =============================================================================
# SECTION 1 -- Load or prompt for configuration
# =============================================================================

# Script-folder config, then (interactive runs only) the root remembered by
# the settings locator, then auto-detected TeknoParrot roots. A protected
# PostgreSQL resume loads only the settings its parent recorded, or stops.
$isPostgresRecoveryResume = -not [string]::IsNullOrWhiteSpace($PostgresRecoveryResumeToken)
$configPath         = Resolve-TpmStartupConfigPath -ScriptRoot $PSScriptRoot -PostgresRecoveryResumeToken $PostgresRecoveryResumeToken
if ($isPostgresRecoveryResume -and -not $configPath) {
    Write-Log 'Postgres recovery: the saved settings recorded for this protected resume were not found or could not be read; nothing was resumed.'
    Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not find the saved settings this PostgreSQL repair was started from, so nothing was resumed.'
}
$tpRoot             = $null
$mode               = $null   # "AutoSync", "RegisterOnly", "CrosshairSetup", "ReShadeSetup", "DgVoodoo2Setup", "GpuFixSetup", "FFBSetup", "BepInExUpdate", "RegionSetup", "Restore", or "HealthCheck"
$pendingApplyMode   = $null   # mode to enter without showing the menu again
$pendingApplyForce  = $false  # true only for preview re-entry
$pendingReShadeAction = 'Select'  # the action a Health Check hand-off starts with; the S/R/U chooser is skipped for it
$reShadeActionPending = $false
$pendingAutoSyncGames = $null  # broken profile codes handed off by Health Check
$pendingAutoSyncSelection = $null  # the Main/Supplementary choice of a preview, carried into its "apply for real" re-entry
$forceRealApply     = $false  # consumed once, right after a forced re-entry,
                              # to disable preview without prompting again.
$menuNotice         = ''
$zipSource               = $null   # AutoSync only (main collection)
$zipSourceSupplementary  = $null   # AutoSync supplementary source (optional, separate library); $null or ''=not configured
$gamesInstallFolder = $null   # always (the extracted-games root to register)
$retroBat           = $false  # true = extracted folders named GameName.teknoparrot (RetroBat/Batocera)
$rsSourceDll        = $null   # ReShade 64-bit DLL (bundled at ReShade\ReShade64.dll or user-provided)
$dgSourceDir        = $null   # dgVoodoo2 DLL folder (bundled at dgVoodoo2\ or user-provided)
$datFilePath          = ''      # optional collection .dat file path (overrides ZIP)
$eggmanDatZip         = ''      # path to Eggman ZIP (contains both dats + notes)
$supplementaryDatPath = ''      # supplementary .dat path (when using separate files)
$includeSupplementary = $false  # whether to build the supplementary index
$lbRoot                     = $null   # LaunchBox install root (containing LaunchBox.exe), if found/entered
$ledBlinkyRoot              = ''      # LEDBlinky folder the user chose (holds LEDBlinkyControls.xml); empty = not chosen
$postgresSuperPasswordEncrypted = $null   # DPAPI-encrypted (ConvertFrom-SecureString, current user+machine) Postgres superuser password
$checkForUpdatesOnStartup = $true   # default true; independent of $configAccepted below -- read even if the
                                     # rest of a saved config is otherwise treated as corrupt/incomplete
$configAccepted       = $false  # true when the user accepted a saved config this run
$unattendedModeSaved = $null         # UnattendedMode selector from the saved config (only HealthCheck is acted on); Save-Config preserves it

if ($Unattended -and -not (Test-Path -LiteralPath $configPath)) {
    Write-Host ""
    Write-Host "ERROR: Unattended mode requires saved settings." -ForegroundColor Red
    Write-Host "Run the script once interactively to save your configuration, then retry with -Unattended." -ForegroundColor Yellow
    Write-Log "ERROR: Unattended mode -- no saved config at $configPath"; exit 1
}

# First-run scope framing: shown exactly once, before the setup wizard below
# ever asks a question, only when no saved config exists yet (a returning
# user with a config skips straight to "Saved configuration found:"). Sets
# expectations before anything else so a beginner isn't left guessing what
# TPM is responsible for versus what TeknoParrot/the game itself is
# responsible for. Rephrases the existing ownership disclaimer already
# shipped in TeknoParrot-Manager-README.txt ("WHAT IT DOES NOT DO") rather
# than introducing new legal wording.
if (-not (Test-Path -LiteralPath $configPath) -and -not $Unattended -and -not $isPostgresRecoveryResume) {
    Write-Host ""
    Write-Host "============================================" -ForegroundColor Cyan
    Write-Host "   Welcome to TeknoParrot Manager" -ForegroundColor Cyan
    Write-Host "============================================" -ForegroundColor Cyan
    Write-Host ""
    Write-Host "  TeknoParrot Manager extracts your game ZIPs, registers the games" -ForegroundColor DarkCyan
    Write-Host "  in TeknoParrot, copies controls between games, and can export them to" -ForegroundColor DarkCyan
    Write-Host "  LaunchBox. It does not provide game files -- you must own or otherwise" -ForegroundColor DarkCyan
    Write-Host "  have lawful rights to any ROM/game data you use." -ForegroundColor DarkCyan
    Write-Host ""
    Write-Host "  You need TeknoParrot installed first (the folder with TeknoParrotUi.exe)." -ForegroundColor DarkCyan
    Write-Host "  TeknoParrot Manager does not install or configure TeknoParrot itself," -ForegroundColor DarkCyan
    Write-Host "  and it cannot guarantee that any individual game will boot or run fullscreen." -ForegroundColor DarkCyan
    Write-Host "  If a game crashes or opens in a window, that is usually a TeknoParrot," -ForegroundColor DarkCyan
    Write-Host "  game, or Windows runtime setting to fix in TeknoParrotUI or the game --" -ForegroundColor DarkCyan
    Write-Host "  not something TeknoParrot Manager changed, unless it touched a related file" -ForegroundColor DarkCyan
    Write-Host "  (it always tells you when it does)." -ForegroundColor DarkCyan
    Write-Host ""
    [void](Read-HostSafe "  Press Enter to continue")
}

# Read before the saved-settings question so the update check can run first. An unreadable file keeps the default (true).
if (Test-Path -LiteralPath $configPath) {
    try {
        $earlyCfg = Get-Content -LiteralPath $configPath -Raw -Encoding UTF8 | ConvertFrom-Json
        if ($null -ne $earlyCfg -and $null -ne $earlyCfg.CheckForUpdatesOnStartup) { $checkForUpdatesOnStartup = [bool]$earlyCfg.CheckForUpdatesOnStartup }
    } catch { Write-Log "Config: could not read the update-check preference -- $_" }
}

# Quiet, opt-out startup update check (CheckForUpdatesOnStartup, default
# true). Never runs in -Unattended mode -- there is no way to show an
# interactive Y/N/V prompt there, and Unattended is meant to be fast and
# non-interactive. See Invoke-StartupUpdateCheck's own comment for how it
# stays from meaningfully delaying startup when GitHub is unreachable.
if ($checkForUpdatesOnStartup -and -not $Unattended -and -not $isPostgresRecoveryResume) {
    $scriptSelfPathForStartupCheck = Join-Path $PSScriptRoot "TeknoParrot-Manager.ps1"
    $startupUpdateResult = Invoke-StartupUpdateCheck -ScriptPath $scriptSelfPathForStartupCheck
    if (-not (Test-TpmTransactionResult -Result $startupUpdateResult)) {
        Write-Log 'StartupUpdateCheck: update flow did not return a valid transaction result; continuing without restart.'
    } elseif ($startupUpdateResult.Outcome -eq 'SUCCEEDED' -or [bool](Get-TpmTransactionField -Object $startupUpdateResult -Name 'UpdateInstalled' -Default $false)) {
        Write-Host ""
        if ($startupUpdateResult.Outcome -ne 'SUCCEEDED') { Write-Host ("  {0}" -f $startupUpdateResult.Summary) -ForegroundColor Yellow }
        Write-Host "  Restart TeknoParrot Manager now to run the verified update." -ForegroundColor Yellow
        [void](Read-HostSafe "  Press Enter to exit")
        Write-Log "StartupUpdateCheck: exiting after verified update -- not continuing in this session."
        exit 0
    } elseif ($startupUpdateResult.Outcome -eq 'ROLLED_BACK_VERIFIED') {
        Write-Host "  The update did not install. Your old version of TeknoParrot Manager is still in place and is starting now. You can try again later with 'Check for Updates' in the menu." -ForegroundColor Yellow
        Write-Log "StartupUpdateCheck: update was not installed and the old manager file was restored and verified; reason=$($startupUpdateResult.ReasonCode)"
    } elseif ($startupUpdateResult.Outcome -ne 'NO_OP') {
        Write-Host ("  {0}" -f $startupUpdateResult.Summary) -ForegroundColor Yellow
        Write-Log "StartupUpdateCheck: transaction outcome=$($startupUpdateResult.Outcome); reason=$($startupUpdateResult.ReasonCode)"
    }
    if ([string](Get-TpmTransactionField -Object $startupUpdateResult -Name 'ReasonCode' -Default '') -ne 'UPDATE_ALREADY_CURRENT') { Write-Host "" }
}

# True first run only: no saved config.json existed at all before this
# wizard run started. Used once, below, to look for a settings file already
# saved for the chosen TeknoParrot folder and offer it.
$isTrueFirstRun = -not (Test-Path -LiteralPath $configPath)
# True once something was printed after the saved-settings step, which itself ends with a blank line.
$tpmPrintedAfterSavedSettings = $false

# Dot-sourced so it runs in script scope; it is offered again below once the
# TeknoParrot root is known if no saved settings were found up front.
$tpmOfferSavedConfig = {
if (Test-Path -LiteralPath $configPath) {
    try {
        $cfg = Get-Content -LiteralPath $configPath -Raw -Encoding UTF8 | ConvertFrom-Json
        if ($null -eq $cfg) { throw "Config file parsed as null -- file may be empty or corrupt." }
        # CheckForUpdatesOnStartup was already read before the update check (it ran ahead of this question).
        $cfgUnattendedModeLoad = $cfg.PSObject.Properties['UnattendedMode']
        if ($cfgUnattendedModeLoad -and -not [string]::IsNullOrWhiteSpace([string]$cfgUnattendedModeLoad.Value)) { $unattendedModeSaved = [string]$cfgUnattendedModeLoad.Value }
        # The encrypted PostgreSQL credential belongs to this PC's PostgreSQL
        # server, not to the folder settings below. Load it before the corrupt
        # check and the Y/N question so that answering N (or an incomplete
        # config) never erases it at the next Save-Config. Nothing here clears it.
        $cfgPostgresCredentialLoad = $cfg.PSObject.Properties['PostgresSuperPasswordEncrypted']
        if ($cfgPostgresCredentialLoad -and -not [string]::IsNullOrWhiteSpace([string]$cfgPostgresCredentialLoad.Value)) { $postgresSuperPasswordEncrypted = [string]$cfgPostgresCredentialLoad.Value }
        if ([string]::IsNullOrWhiteSpace($cfg.TeknoParrotRoot) -or
            [string]::IsNullOrWhiteSpace($cfg.GamesInstallFolder)) {
            throw "Config is missing TeknoParrotRoot or GamesInstallFolder -- treating as corrupt."
        }
        # The settings are listed in the log, and on screen only through the Details key.
        $savedRows = New-Object System.Collections.Generic.List[object]
        [void]$savedRows.Add((New-TpmStartupRow -Label 'TeknoParrot root' -Value ([string]$cfg.TeknoParrotRoot)))
        if ($cfg.ZipSourceFolder)              { [void]$savedRows.Add((New-TpmStartupRow -Label 'ZIP source folder' -Value ([string]$cfg.ZipSourceFolder))) }
        if ($cfg.ZipSourceSupplementaryFolder) { [void]$savedRows.Add((New-TpmStartupRow -Label 'ZIP supplementary' -Value ([string]$cfg.ZipSourceSupplementaryFolder))) }
        [void]$savedRows.Add((New-TpmStartupRow -Label 'Games install folder' -Value ([string]$cfg.GamesInstallFolder)))
        if ($cfg.RetroBat)         { [void]$savedRows.Add((New-TpmStartupRow -Label 'RetroBat mode' -Value 'Yes')) }
        if ($cfg.ReShadeSourceDll)   { [void]$savedRows.Add((New-TpmStartupRow -Label 'ReShade DLL (64-bit)' -Value ([string]$cfg.ReShadeSourceDll))) }
        if ($cfg.DgVoodoo2SourceDir) { [void]$savedRows.Add((New-TpmStartupRow -Label 'dgVoodoo2 folder' -Value ([string]$cfg.DgVoodoo2SourceDir))) }
        if ($cfg.EggmanDatZip)          { [void]$savedRows.Add((New-TpmStartupRow -Label 'Eggman dat ZIP' -Value ([string]$cfg.EggmanDatZip))) }
        if ($cfg.DatFilePath)           { [void]$savedRows.Add((New-TpmStartupRow -Label 'Collection dat' -Value ([string]$cfg.DatFilePath))) }
        if ($cfg.SupplementaryDatPath)  { [void]$savedRows.Add((New-TpmStartupRow -Label 'Supplementary dat' -Value ([string]$cfg.SupplementaryDatPath))) }
        if ($cfg.IncludeSupplementary)  { [void]$savedRows.Add((New-TpmStartupRow -Label 'Supplementary index' -Value 'Yes')) }
        if ($cfg.LaunchBoxRoot)         { [void]$savedRows.Add((New-TpmStartupRow -Label 'LaunchBox root' -Value ([string]$cfg.LaunchBoxRoot))) }
        $cfgUnattendedModeProp = $cfg.PSObject.Properties['UnattendedMode']
        if ($cfgUnattendedModeProp -and $cfgUnattendedModeProp.Value) { [void]$savedRows.Add((New-TpmStartupRow -Label 'Unattended mode' -Value ([string]$cfgUnattendedModeProp.Value))) }
        if ($null -ne $cfg.CheckForUpdatesOnStartup -and -not $cfg.CheckForUpdatesOnStartup) {
            [void]$savedRows.Add((New-TpmStartupRow -Label 'Check for updates on startup' -Value 'Disabled'))
        }
        Show-TpmStartupSummary -Title 'Saved configuration found:' -Rows ($savedRows.ToArray())
        Write-TpmText -Text 'TeknoParrot Manager found your saved settings.' -Color Cyan -Indent 0
        if ($isPostgresRecoveryResume) {
            Write-Host "  [Automatic repair] Continuing the PostgreSQL setup." -ForegroundColor DarkCyan
            Write-Log "Postgres recovery: auto-accepted saved settings for the protected resume."
            $use = "Y"
        } elseif ($Unattended) {
            Write-Host "  [Unattended] Using saved settings." -ForegroundColor DarkCyan
            Write-Log "Unattended: auto-accepted saved settings."
            $use = "Y"
        } else {
            $use = Read-TpmYesNo -Prompt 'Use these settings? (Y/N, D = show them)' -DetailsAction { Show-TpmStartupSummary -Title 'Saved configuration found:' -Rows ($savedRows.ToArray()) -Mode Details }
            if ($use -eq 'Y') { Write-Host 'Using your saved settings.' -ForegroundColor DarkCyan }
        }
        if ($use.ToUpperInvariant() -eq "Y") {
            # A config saved by an older script version could have
            # TeknoParrotRoot stored as a JSON array instead of a plain
            # string (confirmed from a real tester's config.json) --
            # coerce to a scalar defensively so a stale file from before
            # this fix doesn't keep propagating the wrong type forever
            # (Save-Config below would otherwise just re-save whatever
            # type $tpRoot currently holds).
            $tpRoot             = if ($cfg.TeknoParrotRoot -is [array]) { [string]$cfg.TeknoParrotRoot[0] } else { [string]$cfg.TeknoParrotRoot }
            $zipSource          = $cfg.ZipSourceFolder
            if ($null -ne $cfg.ZipSourceSupplementaryFolder) { $zipSourceSupplementary = "$($cfg.ZipSourceSupplementaryFolder)" }
            $gamesInstallFolder = $cfg.GamesInstallFolder
            if ($null -ne $cfg.RetroBat) { $retroBat = [bool]$cfg.RetroBat }
            if ($cfg.ReShadeSourceDll)   { $rsSourceDll   = $cfg.ReShadeSourceDll   }
            if ($cfg.DgVoodoo2SourceDir) { $dgSourceDir   = $cfg.DgVoodoo2SourceDir }
            if ($cfg.EggmanDatZip)         { $eggmanDatZip         = $cfg.EggmanDatZip         }
            if ($cfg.DatFilePath)          { $datFilePath           = $cfg.DatFilePath           }
            if ($cfg.SupplementaryDatPath) { $supplementaryDatPath  = $cfg.SupplementaryDatPath  }
            if ($null -ne $cfg.IncludeSupplementary) { $includeSupplementary = [bool]$cfg.IncludeSupplementary }
            if ($cfg.LaunchBoxRoot)               { $lbRoot               = $cfg.LaunchBoxRoot }
            # LedBlinkyRoot is newer than older saved files, so read it only if present (a missing field must not trip a strict caller).
            $cfgLedBlinkyRootProp = $cfg.PSObject.Properties['LedBlinkyRoot']
            if ($cfgLedBlinkyRootProp -and $cfgLedBlinkyRootProp.Value) { $ledBlinkyRoot = [string]$cfgLedBlinkyRootProp.Value }
            # -Unattended has no CLI or config mechanism to pick which mode to
            # run automatically -- every mode's own body already auto-answers
            # its internal prompts under -Unattended (see the many
            # "if ($Unattended) { ... }" blocks throughout this script), but
            # the INITIAL mode choice itself was only ever reachable through
            # the interactive menu or a same-session preview "Apply for real
            # now?" re-entry. A real -Unattended launch as a fresh process
            # therefore always reached the menu loop with no mode chosen and
            # exited 1 at "Mode must be set before starting." -- confirmed by
            # direct reproduction, not assumed. UnattendedMode is an optional
            # saved-config field read ONLY when -Unattended is set (an
            # interactive run always chooses its mode from the menu,
            # regardless of whether this field is present). This RC ships
            # support for only the audited HealthCheck unattended path --
            # a general config-driven selector across all modes is out of
            # scope for the feature freeze, so any other value (including
            # every other real mode name) is rejected the same as garbage.
            $cfgUnattendedModePropForSelect = $cfg.PSObject.Properties['UnattendedMode']
            if ($Unattended -and $cfgUnattendedModePropForSelect -and $cfgUnattendedModePropForSelect.Value) {
                $validUnattendedModes = @('HealthCheck')
                $requestedUnattendedMode = [string]$cfgUnattendedModePropForSelect.Value
                if ($validUnattendedModes -contains $requestedUnattendedMode) {
                    $pendingApplyMode = $requestedUnattendedMode
                    Write-Log "Unattended: initial mode from saved config = $requestedUnattendedMode"
                } else {
                    Write-Log "WARNING: Unattended: config UnattendedMode '$requestedUnattendedMode' is not a recognized mode -- ignoring, menu loop will report the missing-mode error."
                }
            }
            if ($isPostgresRecoveryResume) {
                $pendingApplyMode = 'PostgresSetup'
                $pendingApplyForce = $true
                Write-Log 'Postgres recovery: protected resume will enter option 11 automatically.'
            }
            $configAccepted = $true
        }
        Write-Host ""
    } catch {
        Write-Host "WARNING: Saved configuration could not be read (file may be corrupt)." -ForegroundColor Yellow
        Write-Host "         Falling through to manual prompts." -ForegroundColor DarkCyan
        Write-Log "Config: could not parse config.json -- $_"
        Write-Host ""
    }
}
}
$cfg = $null   # the settings file as read (if any) is baseline for detecting another window's later save
. $tpmOfferSavedConfig
Set-TpmConfigBaseline -Path ([string]$configPath) -OnDisk $cfg -Document (Get-TpmConfigDocument)
# An update that was cut off (power loss, window closed) leaves its staging folder here: say so once, in plain words.
if (-not $isPostgresRecoveryResume) { Write-TpmInterruptedUpdateNotice -ProgramDir $PSScriptRoot }

if (-not $tpRoot) {
    $detected = Find-TeknoParrotRoot
    if ($Unattended) {
        if ($detected.Count -ge 1) {
            $tpRoot = $detected[0]
            Write-Host "  [Unattended] TeknoParrot auto-detected at: $tpRoot" -ForegroundColor DarkCyan
            Write-Log "Unattended: TeknoParrot auto-detected at $tpRoot"
        } else {
            Write-Host "ERROR: Unattended mode -- could not auto-detect TeknoParrot and no saved path." -ForegroundColor Red
            Write-Log "ERROR: Unattended mode -- TeknoParrot root not found."; exit 1
        }
    } elseif ($detected.Count -eq 1) {
        Write-Host ""
        Write-Host "  Auto-detected TeknoParrot at: $($detected[0])" -ForegroundColor Cyan
        $useIt = Read-TpmYesNo -Prompt "  Use this path? (Y/N)"
        if ($useIt -eq "Y") { $tpRoot = $detected[0] }
    } elseif ($detected.Count -gt 1) {
        Write-Host ""
        Write-Host "  Found TeknoParrot in multiple locations:" -ForegroundColor Cyan
        for ($i = 0; $i -lt $detected.Count; $i++) {
            Write-Host ("    {0}) {1}" -f ($i + 1), $detected[$i])
        }
        $rootChoices = @('N') + @($detected | ForEach-Object { [array]::IndexOf($detected, $_) + 1 } | ForEach-Object { [string]$_ })
        $pick = Read-TpmChoice -Prompt "  Enter number to use one, or N to type the path manually" -Choices $rootChoices -Default 'N'
        if ($pick -match '^\d+$') {
            $idx = [int]$pick - 1
            $tpRoot = $detected[$idx]
        }
    }
    if (-not $tpRoot) {
        $tpRoot = Read-TpmTeknoParrotRoot
    }
}

# No saved settings were found up front, but the TeknoParrot root the user
# just chose may already hold them (for example a root outside the folders
# Find-TeknoParrotRoot scans). Offer them with the same Y/N prompt; nothing is
# reused without a Y.
if ($isTrueFirstRun -and -not $configAccepted -and -not $Unattended -and -not $isPostgresRecoveryResume -and $tpRoot) {
    $chosenRootConfig = Get-TpmOwnedConfigPathForRoot -TeknoParrotRoot ([string]$tpRoot)
    if ($chosenRootConfig -and (Test-Path -LiteralPath $chosenRootConfig -PathType Leaf)) {
        $configPath = $chosenRootConfig
        $isTrueFirstRun = $false
        Write-Host ""
        $cfg = $null
        . $tpmOfferSavedConfig
        Set-TpmConfigBaseline -Path ([string]$configPath) -OnDisk $cfg -Document (Get-TpmConfigDocument)
        $tpmPrintedAfterSavedSettings = $false
    }
}

if (-not $gamesInstallFolder) {
    if ($Unattended) {
        Write-Host "ERROR: Unattended mode -- games install folder not in saved settings." -ForegroundColor Red
        Write-Log "ERROR: Unattended mode -- gamesInstallFolder not set."; exit 1
    }
    Write-Host ""
    Write-Host "  Games folder (also called the staging folder)" -ForegroundColor Cyan
    Write-Host "  AutoSync extracts your games into this folder, one folder per game. Your original ZIPs stay where they are." -ForegroundColor DarkCyan
    Write-Host "  Register only looks in this folder for games you already extracted." -ForegroundColor DarkCyan
    Write-Host "  If the folder does not exist yet, AutoSync creates it when it first extracts a game." -ForegroundColor DarkCyan
    Write-Host "  Register only does not create it: it registers games already in an existing folder." -ForegroundColor DarkCyan
    $recommendedStagingFolder = Get-TpmSafeStagingFolderDefault `
        -TeknoParrotRoot $tpRoot -ZipSource $zipSource `
        -ZipSourceSupplementary $zipSourceSupplementary -ProgramDirectory $PSScriptRoot
    if ($recommendedStagingFolder) {
        Write-Host ("  TeknoParrot Manager recommends: {0}" -f $recommendedStagingFolder) -ForegroundColor Cyan
        Write-Host "  Press Enter to use this location, or B to choose another." -ForegroundColor DarkCyan
    } else {
        Write-Host "  TeknoParrot Manager could not derive a safe default from this installation path." -ForegroundColor Yellow
        Write-Host "  Type a folder or B to browse; it must be outside TeknoParrot, TeknoParrot Manager, and your ZIP folders." -ForegroundColor DarkCyan
    }
    $gamesInstallFolder = Read-TpmStagingFolder -RecommendedPath $recommendedStagingFolder `
        -TeknoParrotRoot $tpRoot -ZipSource $zipSource `
        -ZipSourceSupplementary $zipSourceSupplementary -ProgramDirectory $PSScriptRoot
}

if (-not $configAccepted -and -not $Unattended) {
    Write-Host ""
    Write-Host "  Folder naming mode" -ForegroundColor Cyan
    Write-Host "  This sets how new game folders are named. If unsure, press Enter (N)." -ForegroundColor DarkCyan
    Write-Host "  N = Standard style: GameName  (used by LaunchBox and most other frontends)" -ForegroundColor DarkCyan
    Write-Host "  Y = RetroBat/Batocera style: GameName.teknoparrot" -ForegroundColor DarkCyan
    $rbChoice = Read-TpmYesNo -Prompt "  Use RetroBat folder naming? (Y/N, default N)" -Default 'N'
    $retroBat = ($rbChoice -eq "Y")
    if ($retroBat) { Write-Log "RetroBat mode enabled by user." }
}

# A dat file set only in the overrides file counts as configured. It must be known before the questions below,
# otherwise the start-up question is asked every run and the recap says no DAT is set up.
if (-not $datFilePath) {
    try {
        $earlyOverrides = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'TeknoParrot-Manager.overrides.json') -Raw -Encoding UTF8 -ErrorAction Stop | ConvertFrom-Json
        if ($earlyOverrides.datFile -and -not [string]::IsNullOrWhiteSpace([string]$earlyOverrides.datFile) -and (Test-Path -LiteralPath ([string]$earlyOverrides.datFile))) { $datFilePath = [string]$earlyOverrides.datFile }
    } catch { }
}

if ((($eggmanDatZip -and -not (Test-Path -LiteralPath $eggmanDatZip)) -or ($datFilePath -and -not (Test-Path -LiteralPath $datFilePath))) -and -not $Unattended -and -not $isPostgresRecoveryResume) {
    $eggmanZipMissing = [bool]($eggmanDatZip -and -not (Test-Path -LiteralPath $eggmanDatZip))
    $datFileMissing = [bool]($datFilePath -and -not (Test-Path -LiteralPath $datFilePath))
    # The configured dat file/ZIP no longer exists on disk (moved, renamed,
    # deleted, or replaced by an external tool like RomVault with a
    # different filename convention) -- previously this fell straight
    # through to the "already configured" branch below, which showed a
    # confusing phantom "Currently using ... (0 MB)" entry for a file that
    # was never actually there. Only the missing value is cleared; one that
    # still exists is kept and saved. When both are gone, this same if/elseif
    # chain naturally re-runs the first-run setup wizard instead of
    # duplicating its D/Z/F/N logic a second time.
    if (-not (Test-TpmStartupBlankLineAlreadyWritten)) { Write-Host "" }
    if ($eggmanZipMissing) {
        Write-Host "  Saved Eggman DAT ZIP was not found." -ForegroundColor Yellow
        Write-Log "EggmanDat: configured ZIP no longer exists ($eggmanDatZip) -- cleared."
        $eggmanDatZip = ''
    }
    if ($datFileMissing) {
        Write-Host "  Saved DAT file was not found." -ForegroundColor Yellow
        Write-Log "EggmanDat: configured DAT file no longer exists ($datFilePath) -- cleared."
        $datFilePath = ''
    }
    if (-not $eggmanDatZip -and -not $datFilePath) {
        Write-Host "  TeknoParrot Manager can download a fresh copy of Eggman's TeknoParrot DAT file." -ForegroundColor Yellow
    } else {
        Write-Host "  The other saved DAT setting still exists and was kept." -ForegroundColor Yellow
    }
    $tpmPrintedAfterSavedSettings = $true
}

$eggmanDatActionThisRun = if ($eggmanDatZip -or $datFilePath) { 'Reused' } else { 'NotConfigured' }

if (-not $eggmanDatZip -and -not $datFilePath -and -not $Unattended -and -not $isPostgresRecoveryResume) {
    $eggmanDefaultRoot = Get-EggmanDatDataRoot
    # A blank line before the question, unless the saved-settings step just ended with one (never two in a row).
    $datBlankBefore = -not (Test-TpmStartupBlankLineAlreadyWritten)
    # Three short lines (question, default, skip). The explanation stays in the log.
    Write-Log "EggmanDat: start-up question shown. The DAT index is Eggman's TeknoParrot DAT file, a list of game names that helps recognize renamed or oddly named games. It contains no games; TeknoParrot Manager never downloads any game data."
    Write-TpmText -Text 'Optional: download the DAT index (a list of game names, no games)?' -Color Cyan -Indent 2 -BlankBefore:$datBlankBefore
    Write-TpmText -Text 'D = download it (default), or B = browse for a DAT file I already have' -Indent 4
    Write-TpmText -Text 'N = skip for now (it asks again next time)' -Indent 4 -BlankAfter
    $datChoice = Read-TpmChoice -Prompt "  Choice (D/B/N, default D)" -Choices @('D', 'B', 'N') -Default 'D'
    $raw = ''   # shared path variable for B and the download-fallback path

    if ($datChoice -eq 'D') {
        # The default destination is deterministic even before the release
        # filename is known. Validate a probe path first so no release query
        # or download starts before a safe destination has been selected.
        $firstRunProbe = if ($eggmanDefaultRoot) { Join-Path $eggmanDefaultRoot 'Eggman-destination-probe.zip' } else { $null }
        $firstRunDestination = Get-EggmanDatPathRole -Path $firstRunProbe -RequestedRole Destination -ProgramDirectory $PSScriptRoot
        if ($firstRunDestination.Safe) {
            Write-Host "  Checking Eggman's download page (GitHub) for the newest DAT index..." -ForegroundColor Cyan
            $rel = Get-EggmanDatRelease
        } else {
            Write-Host "  TeknoParrot Manager could not safely use its usual DAT folder, so it did not download." -ForegroundColor Yellow
            Write-Host "  You can use a DAT index ZIP or .dat file you already have instead (next question)." -ForegroundColor Yellow
            Write-Log "EggmanDat: first-run download skipped before release query because the default destination was unsafe: $($firstRunDestination.Reason)"
            $rel = $null
        }
        if ($null -ne $rel -and -not [string]::IsNullOrWhiteSpace([string]$rel.DownloadUrl)) {
            Write-Host ("  Found: {0}  ({1} MB)" -f $rel.FileName, $rel.SizeMB) -ForegroundColor Cyan
            $datDownloadResult = Invoke-EggmanDatDownloadInteractive $rel -ProgramDirectory $PSScriptRoot
            if ($datDownloadResult) {
                $savedPath = [string]$datDownloadResult.Path
                $eggmanDatZip = $savedPath
                $eggmanDatActionThisRun = [string]$datDownloadResult.Action
                if ($eggmanDatActionThisRun -eq 'Reused') {
                    Write-Host "  Reusing existing: $savedPath" -ForegroundColor Green
                    Write-Log "EggmanDat: reused existing DAT at $savedPath"
                } else {
                    Write-Host "  Saved: $savedPath" -ForegroundColor Green
                    Write-Log "EggmanDat: downloaded to $savedPath"
                }
            } else {
                $cachedDatZip = Find-TpmCachedEggmanDatZip -RootPath $eggmanDefaultRoot
                if ($cachedDatZip) {
                    $eggmanDatZip = $cachedDatZip
                    $eggmanDatActionThisRun = 'Reused'
                    $datChoice = 'CACHED'
                    Write-Host "  The download did not finish, so TeknoParrot Manager is using the DAT list it saved earlier." -ForegroundColor Yellow
                    Write-Log "EggmanDat: the download failed; using the saved copy at $cachedDatZip"
                } else {
                    Write-Host "  Enter path to existing ZIP or .dat file, or press Enter to skip:" -ForegroundColor Yellow
                    $raw      = Read-PathWithBrowse "  Path" -Mode File -FileFilter "ZIP/dat files (*.zip;*.dat)|*.zip;*.dat|All files (*.*)|*.*"
                    $datChoice = 'BROWSE'
                }
            }
        } elseif (-not $firstRunDestination.Safe) {
            Write-Host "  Automatic download was not started. Enter an existing ZIP or .dat file, or press Enter to skip:" -ForegroundColor Yellow
            $raw      = Read-PathWithBrowse "  Path" -Mode File -FileFilter "ZIP/dat files (*.zip;*.dat)|*.zip;*.dat|All files (*.*)|*.*"
            $datChoice = 'BROWSE'
        } else {
            $datPageProblem = if ($null -ne $rel) { "Eggman's download page does not list a DAT index file right now" } else { "Could not reach Eggman's download page" }
            $cachedDatZip = Find-TpmCachedEggmanDatZip -RootPath $eggmanDefaultRoot
            if ($cachedDatZip) {
                $eggmanDatZip = $cachedDatZip
                $eggmanDatActionThisRun = 'Reused'
                $datChoice = 'CACHED'
                Write-Host "  $datPageProblem, so TeknoParrot Manager is using the DAT list it saved earlier." -ForegroundColor Yellow
                Write-Log "EggmanDat: $datPageProblem; using the saved copy at $cachedDatZip"
            } else {
                Write-Host "  $datPageProblem. Type the path of a DAT index ZIP or .dat file you already have, or press Enter to skip:" -ForegroundColor Yellow
                $raw      = Read-PathWithBrowse "  Path" -Mode File -FileFilter "ZIP/dat files (*.zip;*.dat)|*.zip;*.dat|All files (*.*)|*.*"
                $datChoice = 'BROWSE'
            }
        }
    }

    if ($datChoice -eq 'B' -or $datChoice -eq 'BROWSE') {
        if ($datChoice -eq 'B') { $raw = Read-PathWithBrowse "  Path to ZIP or dat file" -Mode File -FileFilter "ZIP/dat files (*.zip;*.dat)|*.zip;*.dat|All files (*.*)|*.*" }
        if ($raw) {
            if (Test-Path -LiteralPath $raw) {
                $ext = [System.IO.Path]::GetExtension($raw).ToLowerInvariant()
                if ($ext -eq '.zip') {
                    if (Test-EggmanDatZip -Path $raw) {
                        $eggmanDatZip = $raw
                        $eggmanDatActionThisRun = 'Reused'
                        Write-Log "EggmanDat: ZIP configured at $raw"
                    } else {
                        Write-Host "  WARNING: ZIP is not a readable Eggman archive with a collection DAT -- dat skipped." -ForegroundColor Yellow
                        Write-Log "EggmanDat: ZIP validation failed at $raw -- skipped."
                    }
                } elseif ($ext -eq '.dat') {
                    $datFilePath = $raw
                    $eggmanDatActionThisRun = 'Reused'
                    Write-Log "Config: datFilePath set to $raw"
                } else {
                    Write-Host "  WARNING: Expected .zip or .dat file -- dat skipped." -ForegroundColor Yellow
                    Write-Log ("EggmanDat: unrecognized file type '{0}' at {1} -- skipped." -f $ext, $raw)
                }
            } else {
                Write-Host "  WARNING: File not found -- dat skipped." -ForegroundColor Yellow
                Write-Log "EggmanDat: file not found at $raw -- skipped."
            }
        }
    }

    # Issue #120: tell the user immediately what they selected and, when
    # there's enough information to know, whether it's the latest available
    # version -- rather than silently accepting the selection and leaving
    # freshness unstated. ZIP mode can genuinely be compared (same file-size
    # proxy as Test-EggmanDatUpToDate/#106); direct .dat mode has no release
    # to compare against at all, so it says that plainly instead of staying
    # silent or implying a check that can't happen.
    if ($eggmanDatZip) {
        Write-Host ""
        Write-Host ("  Selected: {0}" -f (Split-Path -Leaf $eggmanDatZip)) -ForegroundColor Cyan
        # Reuse $rel from the D) download branch above when it already ran
        # (avoids a redundant second GitHub call right after downloading);
        # falls back to a fresh lookup for the B) browse path, which never
        # queried the release API at all.
        $latestRel = if ($null -ne $rel) { $rel } else { Get-EggmanDatRelease }
        if ($null -eq $latestRel) {
            Write-Host "  Could not reach Eggman's download page to check whether this is the newest version." -ForegroundColor Yellow
        } elseif ([string]::IsNullOrWhiteSpace([string]$latestRel.DownloadUrl)) {
            Write-Host "  Eggman's download page does not list a DAT index file right now, so this cannot be checked against the newest version." -ForegroundColor Yellow
        } else {
            $freshness = Test-EggmanDatUpToDate -LocalDatPath $eggmanDatZip -RemoteSizeBytes $latestRel.SizeBytes
            if ($freshness.Status -eq 'Current') {
                Write-Host "  This is the latest available version." -ForegroundColor Green
            } elseif ($freshness.Status -eq 'UpdateAvailable') {
                Write-Host ("  A newer version is available: {0}  ({1} MB)" -f $latestRel.FileName, $latestRel.SizeMB) -ForegroundColor Yellow
            } else {
                Write-Host "  Could not determine whether this is the latest version." -ForegroundColor Yellow
            }
        }
    } elseif ($datFilePath) {
        Write-Host ""
        Write-Host ("  Selected: {0}" -f (Split-Path -Leaf $datFilePath)) -ForegroundColor Cyan
        Write-Host "  Cannot check whether this is the latest version -- a standalone dat" -ForegroundColor Yellow
        Write-Host "  file has no release to compare it against." -ForegroundColor Yellow
    }

    # Extra version-info file (supplementary dat) follow-up: deferred out of
    # this initial wizard rather than asked here. Checked, not assumed: a
    # supplementary dat only adds alternate/regional version info for games
    # the main Eggman dat already recognizes -- it does not gate whether a
    # game is recognized/registered at all, so deferring it does not reduce
    # baseline recognition quality for a normal first build. Enabling it
    # later and re-running "Register only" (games already extracted -- just
    # register) is the existing supported path for applying it retroactively.
    # Instead of a blocking Y/N here, TPM watches this run's actual match
    # results and, if any game had an uncertain match, prints a targeted
    # recommendation to set this up afterward -- see the post-run summary.
    if ($eggmanDatZip -or $datFilePath) {
        Write-Host "  An extra version-info file (supplementary dat) can be added later if" -ForegroundColor DarkCyan
        Write-Host "  any games end up with an uncertain match -- TeknoParrot Manager will recommend it then." -ForegroundColor DarkCyan
    }
} elseif ($eggmanDatZip -and -not $Unattended -and -not $isPostgresRecoveryResume) {
    # A dat ZIP is already configured -- offer a lightweight check for a
    # newer release instead of silently reusing the same file forever.
    # Direct .dat file mode ($datFilePath) has no GitHub release counterpart
    # to check against, so this only applies to ZIP mode.
    Write-Host ""
    # Show what's already configured before asking whether to check for a
    # newer one -- this is local, immediate info (no network call), so it's
    # shown regardless of whether the user says Y or N to the check itself.
    # The "latest available" side of this can only be known after querying
    # GitHub, which is exactly the network call this Y/N gate exists to make
    # optional -- so only "currently using" appears here.
    $currentSizeMBPreCheck = if (Test-Path -LiteralPath $eggmanDatZip) { [Math]::Round((Get-Item -LiteralPath $eggmanDatZip).Length / 1MB, 1) } else { 0 }
    Write-Host ("  Currently using  : {0}  ({1} MB)" -f (Split-Path -Leaf $eggmanDatZip), $currentSizeMBPreCheck) -ForegroundColor Cyan
    $checkUpdate = Read-TpmYesNo -Prompt "Check for a newer Eggman dat release? (Y/N)"
    if ($checkUpdate -eq 'Y') {
        # Select and revalidate the destination before contacting GitHub.
        # Reading the current DAT for comparison is allowed; writing a
        # replacement under TeknoParrot is not.
        $updateDestination = Resolve-EggmanDatUpdateDestination -CurrentPath $eggmanDatZip -ProgramDirectory $PSScriptRoot
        if ($updateDestination.Status -notin @('Ready','FallbackSelected')) {
            Write-Log "EggmanDat: update skipped before network work because destination status was $($updateDestination.Status)."
        } else {
            Write-Host "  Checking GitHub for latest Eggman dat release..." -ForegroundColor Cyan
            $rel = Get-EggmanDatRelease
            if ($null -eq $rel) {
                Write-Host "  Could not reach GitHub -- keeping your current dat file." -ForegroundColor Yellow
            } elseif ([string]::IsNullOrWhiteSpace([string]$rel.DownloadUrl)) {
                Write-Host "  GitHub answered, but Eggman's release does not list a DAT index file right now -- keeping your current dat file." -ForegroundColor Yellow
            } else {
                $upToDate = Test-EggmanDatUpToDate -LocalDatPath $eggmanDatZip -RemoteSizeBytes $rel.SizeBytes
                $currentSizeMB = if ($null -ne $upToDate.LocalSizeBytes) { [Math]::Round($upToDate.LocalSizeBytes / 1MB, 1) } else { 0 }
                Write-Host ("  Latest available : {0}  ({1} MB)" -f $rel.FileName, $rel.SizeMB) -ForegroundColor Cyan
                Write-Host ("  Currently using  : {0}  ({1} MB)" -f (Split-Path -Leaf $eggmanDatZip), $currentSizeMB) -ForegroundColor Cyan
                if ($upToDate.Status -eq 'Current') {
                    Write-Host "  Your dat file is already current -- no download needed." -ForegroundColor Green
                    Write-Log "EggmanDat: local file already matches the latest release size -- skipped prompt."
                } else {
                    if ($upToDate.Status -eq 'Unknown') {
                        Write-Host "  Could not determine your current dat file's size -- offering the download anyway." -ForegroundColor Yellow
                    }
                    $doUpdate = if ($updateDestination.Status -eq 'FallbackSelected') {
                        'Y'
                    } else {
                        Read-TpmYesNo -Prompt "  Download and switch to the latest release? (Y/N)"
                    }
                    if ($doUpdate -eq 'Y') {
                        $preferredUpdatePath = Join-Path ([System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($eggmanDatZip))) ([System.IO.Path]::GetFileName($rel.FileName))
                        if ($updateDestination.Status -eq 'FallbackSelected') {
                            $preferredUpdatePath = Join-Path $updateDestination.DestinationFolder ([System.IO.Path]::GetFileName($rel.FileName))
                        }
                        $datUpdateResult = Invoke-EggmanDatDownloadInteractive $rel -AllowBrowse -PreferredSavePath $preferredUpdatePath -ProgramDirectory $PSScriptRoot
                        if ($datUpdateResult) {
                            $eggmanDatZip = [System.IO.Path]::GetFullPath([string]$datUpdateResult.Path)
                            $datFilePath = ''
                            if ([string]$datUpdateResult.Action -eq 'Reused') {
                                $eggmanDatActionThisRun = 'Reused'
                                Write-Host ("  Latest release already present: {0}" -f $eggmanDatZip) -ForegroundColor Green
                                Write-Log "EggmanDat: latest release already present at $eggmanDatZip; no download performed."
                            } else {
                                $eggmanDatActionThisRun = 'Updated'
                                Write-Host ("  Updated: {0}" -f $eggmanDatZip) -ForegroundColor Green
                                Write-Log "EggmanDat: updated to $eggmanDatZip"
                            }
                            [void](Save-Config)
                        } else {
                            Write-Host "  Download failed -- keeping your current dat file." -ForegroundColor Yellow
                        }
                    }
                }
            }
        }
    }
}

# =============================================================================
# SECTION 2 -- Validate TeknoParrot root, locate GameProfiles and UserProfiles
# =============================================================================

$tpRootProblem = Get-TpmTeknoParrotRootProblem -Path $tpRoot
if ($tpRootProblem -eq 'NoFolder') {
    Write-Host ""; Write-Host "ERROR: TeknoParrot root folder not found: $tpRoot" -ForegroundColor Red
    Write-Log "ERROR: TeknoParrot root not found."; exit 1
}

# TeknoParrot's launcher is TeknoParrotUi.exe (Windows path checks are
# case-insensitive, so this also matches TeknoParrotUI.exe).
$tpExe = Join-Path $tpRoot "TeknoParrotUi.exe"
if ($tpRootProblem -eq 'NoExe') {
    Write-Host ""; Write-Host "ERROR: TeknoParrotUi.exe not found in: $tpRoot" -ForegroundColor Red
    Write-Host "Make sure the path points to the TeknoParrot root folder." -ForegroundColor Yellow
    Write-Log "ERROR: TeknoParrotUi.exe not found."; exit 1
}

$script:TpmOwnedLayout = Initialize-TpmOwnedLayout -Layout (Get-TpmOwnedLayout -TeknoParrotRoot $tpRoot)
try { $script:TpmStartupIdentity = Get-TpmRuntimeArtifactIdentity -ScriptPath $PSCommandPath } catch { $script:TpmStartupIdentity = $null }
try {
    $migration = Invoke-TpmProgressGroup -Title 'Owned-state migration' -Action { Invoke-TpmOwnedMigration -ScriptRoot $PSScriptRoot -Layout $script:TpmOwnedLayout -Unattended:$Unattended }
} catch {
    # A throw can occur after partial migration work; report state as unknown so the startup gate stops.
    Write-Log ('ERROR: owned-state migration threw: {0}' -f $_.Exception.Message)
    $migration = New-TpmProfileTransactionResult -WorkflowKey 'OwnedMigration' -OperationKey 'Migrate' -Outcome 'ACTION_REQUIRED' -ProductState 'UNKNOWN' -Summary 'Owned-state migration threw before completing.' -Items @() -FailedItems @() -MutationStarted $true -FinalPassed $false -ReasonCode 'MIGRATION_THREW' -FinalChecks @(('Migration error: {0}' -f $_.Exception.Message))
}
if (-not (Test-TpmOwnedMigrationStartupAllowed -MigrationResult $migration)) {
    Write-Host '  Startup stopped because owned-state migration needs review before normal workflows can continue.' -ForegroundColor Red
    $migrationPreState = Get-TpmTransactionField -Object $migration -Name 'PreState' -Default $null
    $migrationBackup = Get-TpmTransactionField -Object $migration -Name 'Backup' -Default $null
    $migrationRollback = Get-TpmTransactionField -Object $migration -Name 'Rollback' -Default $null
    $migrationCleanup = Get-TpmTransactionField -Object $migration -Name 'Cleanup' -Default $null
    $migrationEvidencePaths = @(
        (Get-TpmTransactionField -Object $migrationPreState -Name 'EvidenceRoot')
        (Get-TpmTransactionField -Object $migrationBackup -Name 'RootPath')
        (Get-TpmTransactionField -Object $migrationRollback -Name 'EvidenceRoot')
    ) + @(Get-TpmTransactionField -Object $migrationCleanup -Name 'ResiduePaths' -Default @())
    $migrationEvidencePaths = @($migrationEvidencePaths | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Select-Object -Unique)
    if ($migrationEvidencePaths.Count -gt 0) {
        Write-Host '  Preserve these evidence/residue paths for manual recovery:' -ForegroundColor Yellow
        foreach ($evidencePath in $migrationEvidencePaths) { Write-Host ('    {0}' -f $evidencePath) -ForegroundColor DarkGray }
    }
    foreach ($reviewLine in @(Get-TpmOwnedMigrationDestinationReviewLines -MigrationResult $migration)) { Write-Host $reviewLine -ForegroundColor Yellow }
    Write-Host '  Do not delete or overwrite migration evidence or residue before review.' -ForegroundColor Yellow
    exit 1
}
if ($migration.Outcome -eq 'FAILED_BEFORE_MUTATION') {
    $migrationBackupDetail = ([string](Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $migration -Name 'Backup' -Default $null) -Name 'FailureCode' -Default '')).Trim()
    Write-Log ('Owned-state migration did not complete before any managed move; normal startup is continuing. Reason: ' + ([string]$migration.ReasonCode + ' ' + $migrationBackupDetail).Trim())
    Write-TpmText -Text 'TeknoParrot Manager could not move its own files yet. Nothing was changed, and it is starting normally.' -Color Yellow
    if ([string]$migration.ReasonCode -eq 'BACKUP_FAILED') {
        Write-TpmText -Text 'It could not make a safety copy of them first. Close programs that may be using those files (for example a virus scanner), then start TeknoParrot Manager again and answer Y to "Tidy up now?".' -Color Yellow
        foreach ($leftoverCopy in @(Get-TpmTransactionField -Object (Get-TpmTransactionField -Object $migration -Name 'Cleanup' -Default $null) -Name 'ResiduePaths' -Default @())) { Write-TpmText -Text ('An unfinished safety copy was left here. You can delete it: ' + $leftoverCopy) -Color DarkGray }
    }
} elseif ($migration.Outcome -eq 'SUCCEEDED') {
    Write-Log 'TeknoParrot Manager-owned state migration completed.'
} elseif ($migration.Outcome -eq 'ROLLED_BACK_VERIFIED') {
    Write-Log 'State migration was rolled back and no managed state was changed.'
    Write-TpmText -Text 'TeknoParrot Manager could not finish moving its own files, so it undid the change. Nothing was changed.' -Color Yellow
}
# Fold this launch's script-folder startup log into the managed log before switching to it (Merge-TpmLegacyStartupLog).
$startupLogMerge = Merge-TpmLegacyStartupLog -LegacyLogPath $logPath -Layout $script:TpmOwnedLayout
$logPath = $script:TpmOwnedLayout.LogPath
switch ([string]$startupLogMerge.Outcome) {
    'Appended' { Write-Log ("Startup log: appended {0} bytes from {1} to the managed log; read-back verified." -f $startupLogMerge.Bytes,$startupLogMerge.Source) }
    'EmptyRemoved' {
        if ($startupLogMerge.SourceRemoved) { Write-Log ("Startup log: {0} was empty and was removed; nothing was archived." -f $startupLogMerge.Source) }
        else { Write-Log ("Startup log: {0} was empty; it is still present and will be merged when it next has content. {1}" -f $startupLogMerge.Source,$startupLogMerge.Error) }
    }
    'Preserved' {
        Write-Log ("Startup log: {0} was not TPM log text of at most 1 MiB; kept it unchanged as {1}; read-back verified." -f $startupLogMerge.Source,$startupLogMerge.Destination)
    }
    'Failed' {
        Write-Host ("  The script-folder log was left in place; TeknoParrot Manager will try again next launch: {0}" -f $startupLogMerge.Source) -ForegroundColor Yellow
        Write-Host ("  Detail: {0}" -f $startupLogMerge.Error) -ForegroundColor DarkGray
        Write-Log ("Startup log: merge into the managed log failed; {0} was left in place. {1}" -f $startupLogMerge.Source,$startupLogMerge.Error)
    }
}
if ([string]$startupLogMerge.Outcome -in @('Appended','Preserved') -and -not $startupLogMerge.SourceRemoved) {
    Write-Host ("  The script-folder log was copied and verified but is still present; remove it after review so it is not merged again: {0}" -f $startupLogMerge.Source) -ForegroundColor Yellow
    Write-Log ("Startup log: {0}" -f $startupLogMerge.Error)
}
$configPath = Get-TpmConfigPathAfterMigration -CurrentPath ([string]$configPath) -ScriptRoot $PSScriptRoot -Layout $script:TpmOwnedLayout
# The baseline now describes the settings file that is in use (the managed one once the settings moved).
if ($null -ne (Get-Variable -Name TpmConfigBaseline -Scope Script -ValueOnly -ErrorAction SilentlyContinue)) { $script:TpmConfigBaseline.Path = [string]$configPath }
# Remember which TeknoParrot root holds these settings so the next launch can
# offer to reuse them even when that root is not auto-detected.
[void](Write-TpmConfigLocator -TeknoParrotRoot ([string]$tpRoot))
if ($rsSourceDll -and -not (Test-Path -LiteralPath $rsSourceDll -PathType Leaf)) {
    $candidate = Join-Path $script:TpmOwnedLayout.Assets ('ReShade\' + [System.IO.Path]::GetFileName($rsSourceDll))
    if (Test-Path -LiteralPath $candidate -PathType Leaf) { $rsSourceDll = $candidate }
}

$gameProfilesDir = Join-Path $tpRoot "GameProfiles"

$userProfilesDir = Join-Path $tpRoot "UserProfiles"
if (-not (Test-Path -LiteralPath $userProfilesDir)) {
    try {
        [void][System.IO.Directory]::CreateDirectory($userProfilesDir)
    } catch {
        Write-Host ""; Write-Host "ERROR: Could not create UserProfiles folder: $_" -ForegroundColor Red
        Write-Log "ERROR: Could not create UserProfiles folder -- $_"; exit 1
    }
}

Write-Log "Validated. tpRoot=$tpRoot install=$gamesInstallFolder"

# =============================================================================
# SECTION 4 -- Save configuration
# =============================================================================

# FIX58 (#348): a checked restore point of the game settings (UserProfiles) and
# of the TeknoParrot Manager settings file is made before the start-up settings
# save. Unattended runs and the protected PostgreSQL resume keep their earlier
# behavior (no restore point, no new prompt). If the restore point cannot be
# made and checked, the start-up settings save that depends on it is skipped
# and the reason is shown; nothing waits for input.
$startupRestorePointFailed = $false
if (-not $Unattended -and -not $isPostgresRecoveryResume) {
    $startupRestorePoint = Invoke-TpmStartupRestorePoint -UserProfilesDir $userProfilesDir -ConfigPath ([string]$configPath)
    if (-not $startupRestorePoint.Succeeded) {
        $startupRestorePointFailed = $true
        Write-Host ''
        Write-TpmResetRestoreText -Text 'TeknoParrot Manager could not save a checked restore point of your game settings and its own settings, so it did not save its settings at start-up.' -Color Yellow
        Write-TpmResetRestoreText -Text ('Reason: {0}' -f [string]$startupRestorePoint.Reason) -Color Yellow
        Write-TpmResetRestoreText -Text 'Each repair still makes its own safety copy before it changes anything. Reset and Restore (Restore backup, option 4) can only offer restore points that were saved earlier.' -Color DarkGray
    } elseif ($startupRestorePoint.Created) {
        Write-TpmResetRestoreText -Text 'Restore point saved and checked (game settings and TeknoParrot Manager settings).' -Color DarkGray
    }
    if ([int]$startupRestorePoint.RemovableCount -gt 0) {
        Write-TpmResetRestoreText -Text ('You have {0} older restore point(s) beyond the newest {1}. Nothing is removed automatically; you can remove them in Restore backup, option 4.' -f [int]$startupRestorePoint.RemovableCount, (Get-TpmRestorePointKeepCount)) -Color DarkGray
    }
}

if ($startupRestorePointFailed) {
    Write-TpmResetRestoreText -Text 'Your settings were not saved at start-up; settings you change later in this session are still saved.' -Color Yellow
    Write-Log 'Startup: settings save skipped because the start-up restore point could not be made and checked.'
} elseif (-not (Save-Config)) {
    Write-Host "  WARNING: Could not save configuration -- settings will not be remembered." -ForegroundColor Yellow
}

# FIX36 B4: tell the user at startup, read-only, when an earlier PostgreSQL
# password repair did not finish (its temporary trust rule may still be in
# pg_hba.conf). The protected child skips this: option 11 runs the full check.
if (-not $isPostgresRecoveryResume) {
    $startupTrustWarned = $false
    try { $startupTrustWarned = [bool](Write-PostgresTrustRuleStartupWarning) } catch { Write-Log 'Postgres startup check: the recovery-marker check could not run.' }
    if ($startupTrustWarned -and -not $Unattended) {
        [void](Read-HostSafe '  Press Enter to continue')
    }
    # FIX110A B-1: look for temporary PostgreSQL password files that an older
    # TeknoParrot Manager left in the temp folder. They are only reported, never
    # opened or deleted: nothing proves who made a file in the shared temp folder.
    try {
        $pgPassFound = Get-PostgresLeftoverPgPassFiles
        if ($pgPassFound.Found -gt 0) {
            Write-Host ("  TeknoParrot Manager found {0} old temporary PostgreSQL password file(s) in {1}." -f $pgPassFound.Found, $pgPassFound.Directory) -ForegroundColor Yellow
            Write-Host '  An older version may have left them behind. TeknoParrot Manager did not open or delete them.' -ForegroundColor Yellow
            $pgPassFileName = 'tpm-pgpass-*.conf'
            Write-Host ("  Next step: if you are sure they are old, delete the files named {0} in that folder yourself." -f $pgPassFileName) -ForegroundColor Yellow
            Write-Host ''
        }
    } catch { Write-Log 'Postgres startup check: the temporary credential check could not run.' }
}

# The settings in use go to the log. An unattended run keeps printing them (its console log is read
# by the smoke harness); an interactive run has no second settings block on screen.
$configRows = New-Object System.Collections.Generic.List[object]
[void]$configRows.Add((New-TpmStartupRow -Label 'TeknoParrot root' -Value ([string]$tpRoot)))
if ($zipSource)               { [void]$configRows.Add((New-TpmStartupRow -Label 'ZIP source folder' -Value ([string]$zipSource))) }
if ($zipSourceSupplementary)  { [void]$configRows.Add((New-TpmStartupRow -Label 'ZIP supplementary' -Value ([string]$zipSourceSupplementary))) }
[void]$configRows.Add((New-TpmStartupRow -Label 'Games install folder' -Value ([string]$gamesInstallFolder)))
if ($retroBat)             { [void]$configRows.Add((New-TpmStartupRow -Label 'RetroBat mode' -Value 'Yes (*.teknoparrot / *.parrot / *.game recognized)' -Color 'Cyan')) }
if ($eggmanDatZip)         { [void]$configRows.Add((New-TpmStartupRow -Label 'Eggman dat ZIP' -Value ([string]$eggmanDatZip))) }
elseif ($datFilePath)      { [void]$configRows.Add((New-TpmStartupRow -Label 'Collection dat' -Value ([string]$datFilePath))) }
if ($supplementaryDatPath) { [void]$configRows.Add((New-TpmStartupRow -Label 'Supplementary dat' -Value ([string]$supplementaryDatPath))) }
elseif ($includeSupplementary -and $eggmanDatZip) { [void]$configRows.Add((New-TpmStartupRow -Label 'Supplementary index' -Value 'Yes (from ZIP)')) }
if ($Unattended) {
    Write-Host ""
    Show-TpmStartupSummary -Title 'Configuration:' -Rows ($configRows.ToArray()) -Mode Plain -TitleColor Green
} else {
    Show-TpmStartupSummary -Title 'Configuration:' -Rows ($configRows.ToArray())
}

# =============================================================================
# CUSTOM RULES NOTICE (FIX81)
# =============================================================================
# When TeknoParrot-Manager.overrides.json holds rules, start-up says so in one line and asks nothing, so start-up never
# waits for a key. What each rule does (and how many there are) is written to the log, and the counts are also logged
# (see SECTION 4b below). Nothing is shown when the file holds no rules.

# One block per kind of rule that has entries: what it is called in the file, how many, what it does.
function Get-TpmOverridesDetailBlocks {
    param([Parameter(Mandatory)][System.Collections.IDictionary]$Counts, [string]$FilePath = '')
    $kinds = @(
        @('noSync', 'ZIP files that are never extracted', 'These games are skipped when TeknoParrot Manager extracts ZIP files.'),
        @('onlySync', 'Only these ZIP files are extracted', 'Every other ZIP file is skipped.'),
        @('noPropagate', 'Games that never get copied controls', 'Controls are not copied to these games.'),
        @('forceArchetype', 'Games pinned to one example game', 'Controls for these games are always copied from the example game you chose.'),
        @('familyOverride', 'Games with a control type you chose', 'These games use the control type you set, not the automatic guess.'),
        @('canonicalArchetype', 'Main example game of a control type', 'The input method of this example game is treated as correct for its control type.'),
        @('subFolderMap', 'Games with their own folder', 'These games are placed in the folder you chose.')
    )
    $blocks = New-Object System.Collections.Generic.List[object]
    if (-not [string]::IsNullOrWhiteSpace($FilePath)) {
        [void]$blocks.Add(@{ Heading = 'The file'; Lines = @('Name: TeknoParrot-Manager.overrides.json', ('Path: ' + $FilePath)) })
    }
    foreach ($kind in $kinds) {
        $count = if ($Counts.Contains($kind[0])) { [int]$Counts[$kind[0]] } else { 0 }
        if ($count -lt 1) { continue }
        [void]$blocks.Add(@{ Heading = $kind[1]; Lines = @(('Setting: ' + $kind[0]), ('How many: ' + $count), ('What it does: ' + $kind[2])) })
    }
    return $blocks.ToArray()
}

function Show-TpmOverridesNotice {
    param([Parameter(Mandatory)][System.Collections.IDictionary]$Counts, [string]$FilePath = '')
    $total = 0
    foreach ($key in $Counts.Keys) { $total += [int]$Counts[$key] }
    if ($total -lt 1) { return }
    Write-TpmText -Text 'You have custom rules in TeknoParrot-Manager.overrides.json. The full list is in the log.' -Color DarkCyan -BlankBefore
    Write-Log 'Custom rules note: If you did not make this file yourself, there is nothing to do. If a rule looks wrong, change or remove it in that file and start again.'
    Write-TpmDetailBlocksLog -Blocks @(Get-TpmOverridesDetailBlocks -Counts $Counts -FilePath $FilePath) -Prefix 'Custom rules'
}

# =============================================================================
# SECTION 4b -- Per-game overrides  (TeknoParrot-Manager.overrides.json)
# =============================================================================
# Created empty on first run. Edit with any text editor to fine-tune behavior:
#   noSync         : ZIP base names to always skip during extraction.
#   onlySync       : Whitelist -- if non-empty, only these ZIPs are extracted
#                    (bypasses the interactive picker; useful for scripted runs).
#   noPropagate    : Profile codes to leave untouched during propagation.
#   forceArchetype : { "ProfileCode": "ArchetypeCode" } -- pin a game to a
#                    specific archetype instead of the automatic best match.
#   familyOverride : { "ProfileCode": "family" } -- override the auto-detected
#                    control family. Valid values: button, driving, lightgun,
#                    trackball, analog, spinner. Fixes mis-classified titles
#                    (e.g. FamilyGuyBowling detected as lightgun; set "trackball").
#   canonicalArchetype : { "family": "ProfileCode" } -- the one archetype in
#                    that family whose Input API is treated as correct. An
#                    archetype is otherwise never modified (see issue #1);
#                    this is the one explicit, user-chosen exception -- every
#                    OTHER archetype in that same family gets its own Input
#                    API corrected to match the designated one, if different.
#                    Deliberately NOT a heuristic guess (v0.99.12 tried
#                    guessing via best button-overlap and broke a real
#                    tester's library by cross-correcting independently
#                    correct archetypes against each other -- reverted in
#                    v0.99.14). Leave unset for a family to never correct
#                    any archetype in it.

$overridesPath         = Join-Path $PSScriptRoot "TeknoParrot-Manager.overrides.json"
$noSyncList            = @()
$onlySyncList          = @()
$noPropagateList       = @()
$forceArchetypeMap     = @{}
$familyOverrideMap     = @{}
$canonicalArchetypeMap = @{}
$subFolderMap          = @{}
$validFamilies         = @('button','driving','lightgun','trackball','analog','spinner')

if (-not (Test-Path -LiteralPath $overridesPath)) {
    $ovTemplate = [ordered]@{
        _comment           = "noSync/onlySync/noPropagate: lists of ZIP base names (without .zip). onlySync acts as a whitelist -- only listed games are extracted. forceArchetype: { GameCode: ArchetypeCode } pins a game to a specific reference game. familyOverride: { GameCode: 'button'|'driving'|'lightgun'|'trackball'|'analog' } overrides the auto-detected control family (fixes mis-classified games like FamilyGuyBowling). canonicalArchetype: { family: ArchetypeCode } the one archetype per family whose Input API is treated as correct -- every other archetype in that family gets its Input API corrected to match it. subFolderMap: { ProfileCode: 'relative\\subpath' } for games whose executable lives in a specific subfolder of the TeknoParrot root rather than in the staging folder (e.g. CrediarDolphin titles). datFile: full path to a No-Intro TeknoParrot dat file; when set the script uses it to auto-register games with shared executable names (like game.exe) without needing fuzzy matching."
        noSync             = @()
        onlySync           = @()
        noPropagate        = @()
        forceArchetype     = [ordered]@{}
        familyOverride     = [ordered]@{}
        canonicalArchetype = [ordered]@{}
        subFolderMap       = [ordered]@{}
        datFile            = ""
    }
    try { [System.IO.File]::WriteAllText($overridesPath, ($ovTemplate | ConvertTo-Json -Depth 10), (New-Object System.Text.UTF8Encoding $false)) }
    catch { Write-Log "Overrides: could not create template -- $_" }
}

if (Test-Path -LiteralPath $overridesPath) {
    try {
        $ov = Get-Content -LiteralPath $overridesPath -Raw -Encoding UTF8 | ConvertFrom-Json
        if ($ov.noSync)      { $noSyncList      = @($ov.noSync) }
        if ($ov.onlySync)    { $onlySyncList    = @($ov.onlySync) }
        if ($ov.noPropagate) { $noPropagateList = @($ov.noPropagate) }
        if ($ov.forceArchetype) {
            foreach ($p in $ov.forceArchetype.PSObject.Properties) { $forceArchetypeMap[$p.Name] = [string]$p.Value }
        }
        if ($ov.familyOverride) {
            foreach ($p in $ov.familyOverride.PSObject.Properties) {
                $fv = [string]$p.Value
                if ($validFamilies -contains $fv) {
                    $familyOverrideMap[$p.Name] = $fv
                } else {
                    Write-Host '  A controls override names an unknown game family and was ignored. Check the log before changing it.' -ForegroundColor Yellow
                    Write-Log "Overrides: familyOverride '$($p.Name)' has unknown value '$fv' -- ignored."
                }
            }
        }
        if ($ov.canonicalArchetype) {
            foreach ($p in $ov.canonicalArchetype.PSObject.Properties) {
                $fam = $p.Name
                if ($validFamilies -contains $fam) {
                    $canonicalArchetypeMap[$fam] = [string]$p.Value
                } else {
                    Write-Host '  A controls override names an unknown game family and was ignored. Check the log before changing it.' -ForegroundColor Yellow
                    Write-Log "Overrides: canonicalArchetype has unknown family '$fam' -- ignored."
                }
            }
        }
        if ($ov.subFolderMap) {
            foreach ($p in $ov.subFolderMap.PSObject.Properties) { $subFolderMap[$p.Name] = [string]$p.Value }
        }
        # A dat file that is not there is not applied: the start-up question already dealt with it, and it must not replace a dat the user just chose.
        if ($ov.datFile -and -not [string]::IsNullOrWhiteSpace([string]$ov.datFile) -and (Test-Path -LiteralPath ([string]$ov.datFile))) {
            $datFilePath = [string]$ov.datFile
        }
        # Issue #119: this used to also show whenever a dat file was
        # configured ("datFile=yes"), even with every other count at zero --
        # a dat file is a normal, common setting (already shown plainly in
        # the Configuration summary above), not an advanced override, so
        # showing this diagnostic-looking line just because one was
        # configured made ordinary setups look like they had unexplained
        # internal state. Now only shown when an actual override
        # (noSync/onlySync/noPropagate/pinned/familyOverride/
        # canonicalArchetype/subFolderMap) is configured in
        # TeknoParrot-Manager.overrides.json.
        $ovCounts = [ordered]@{
            noSync = $noSyncList.Count; onlySync = $onlySyncList.Count; noPropagate = $noPropagateList.Count
            forceArchetype = $forceArchetypeMap.Count; familyOverride = $familyOverrideMap.Count
            canonicalArchetype = $canonicalArchetypeMap.Count; subFolderMap = $subFolderMap.Count
        }
        Show-TpmOverridesNotice -Counts $ovCounts -FilePath $overridesPath
        Write-Log "Overrides: noSync=$($noSyncList.Count) onlySync=$($onlySyncList.Count) noPropagate=$($noPropagateList.Count) pinned=$($forceArchetypeMap.Count) familyOverride=$($familyOverrideMap.Count) canonicalArchetype=$($canonicalArchetypeMap.Count) subFolderMap=$($subFolderMap.Count) datFile=$datFilePath"
    } catch {
        Write-Host "WARNING: could not read TeknoParrot-Manager.overrides.json; ignoring overrides." -ForegroundColor Yellow
        Write-Log "Overrides: parse error -- ignoring."
    }
}
$configuredOnlySyncList = @($onlySyncList)  # the whitelist from the overrides file; every ordinary AutoSync run starts from it

# =============================================================================
# DAT FILE INDEX  (loaded once before the menu loop; reused each run)
# Priority: EggmanDatZip (ZIP mode) > DatFilePath (direct file mode)
# =============================================================================

$datIndex   = @{}
$suppIndex  = @{}   # supplementary dat index: normalizedName -> {ProfileCode, Executable}
$suppCodes  = New-Object 'System.Collections.Generic.HashSet[string]'([StringComparer]::OrdinalIgnoreCase)
$notesIndex = @{}   # game notes index: ProfileCode.ToLowerInvariant() -> notes text string

if ($eggmanDatZip) {
    if (Test-Path -LiteralPath $eggmanDatZip) {
        Write-Host ""
        Write-Host "Loading collection dat from ZIP..." -ForegroundColor DarkGray
        $datIndex = Build-DatIndexFromZip $eggmanDatZip
        if ($datIndex.Count -gt 0) {
            Write-Host ("  Collection dat: {0} games indexed." -f $datIndex.Count) -ForegroundColor DarkGray
            Write-Log "DatIndex (ZIP): $($datIndex.Count) entries from $eggmanDatZip"
        } else {
            Write-Host "  Collection dat: no entries found -- check ZIP contains a *Collection*_RomVault*.dat entry." -ForegroundColor Yellow
            Write-Log "DatIndex (ZIP): 0 entries from $eggmanDatZip."
        }
        if ($includeSupplementary) {
            Write-Host "  Loading supplementary dat from ZIP..." -ForegroundColor DarkGray
            $suppIndex = Build-DatIndexFromZip $eggmanDatZip '*Supplementary*_RomVault*.dat'
            if ($suppIndex.Count -gt 0) {
                Write-Host ("  Supplementary dat: {0} entries indexed (override collection)." -f $suppIndex.Count) -ForegroundColor DarkGray
                Write-Log "SuppIndex (ZIP): $($suppIndex.Count) entries from $eggmanDatZip"
            } else {
                Write-Host "  Supplementary dat: no entries found." -ForegroundColor Yellow
                Write-Log "SuppIndex (ZIP): 0 entries from $eggmanDatZip."
            }
        }
        Write-Host "  Loading game notes from ZIP..." -ForegroundColor DarkGray
        $notesIndex = Build-GameNotesIndexFromZip $eggmanDatZip
        if ($notesIndex.Count -gt 0) {
            Write-Host ("  Game notes: {0} entries indexed." -f $notesIndex.Count) -ForegroundColor DarkGray
            Write-Log "NotesIndex (ZIP): $($notesIndex.Count) entries from $eggmanDatZip"
        }
    } else {
        Write-Host ("  WARNING: Eggman dat ZIP not found at: {0}" -f $eggmanDatZip) -ForegroundColor Yellow
        Write-Log "DatIndex (ZIP): file not found at $eggmanDatZip -- skipping."
    }
} elseif ($datFilePath) {
    if (Test-Path -LiteralPath $datFilePath) {
        Write-Host ""
        Write-Host "Loading collection dat..." -ForegroundColor DarkGray
        $datIndex = Build-DatIndex $datFilePath
        if ($datIndex.Count -gt 0) {
            Write-Host ("  Collection dat: {0} games indexed." -f $datIndex.Count) -ForegroundColor DarkGray
            Write-Log "DatIndex: $($datIndex.Count) entries from $datFilePath"
        } else {
            Write-Host "  Collection dat: no entries found -- check that the file has <GameProfile> elements." -ForegroundColor Yellow
            Write-Log "DatIndex: 0 entries from $datFilePath -- file parsed but no valid game entries found."
        }
        if ($supplementaryDatPath) {
            if (Test-Path -LiteralPath $supplementaryDatPath) {
                Write-Host "  Loading supplementary dat..." -ForegroundColor DarkGray
                $suppIndex = Build-DatIndex $supplementaryDatPath
                if ($suppIndex.Count -gt 0) {
                    Write-Host ("  Supplementary dat: {0} entries indexed (override collection)." -f $suppIndex.Count) -ForegroundColor DarkGray
                    Write-Log "SuppIndex: $($suppIndex.Count) entries from $supplementaryDatPath"
                } else {
                    Write-Host "  Supplementary dat: no entries found." -ForegroundColor Yellow
                    Write-Log "SuppIndex: 0 entries from $supplementaryDatPath."
                }
            } else {
                Write-Host ("  WARNING: Supplementary dat not found at: {0}" -f $supplementaryDatPath) -ForegroundColor Yellow
                Write-Log "SuppIndex: file not found at $supplementaryDatPath -- skipping."
            }
        }
        # Look for a notes text file alongside the dat (e.g. extracted from the ZIP)
        $notesCandidate = Get-ChildItem -LiteralPath ([System.IO.Path]::GetDirectoryName($datFilePath)) `
                              -Filter '*.txt' -File -ErrorAction SilentlyContinue |
                          Where-Object { $_.Name -ilike '*note*' } |
                          Select-Object -First 1 -ExpandProperty FullName
        if ($notesCandidate) {
            Write-Host "  Loading game notes..." -ForegroundColor DarkGray
            $notesIndex = Build-GameNotesIndex $notesCandidate
            if ($notesIndex.Count -gt 0) {
                Write-Host ("  Game notes: {0} entries indexed." -f $notesIndex.Count) -ForegroundColor DarkGray
                Write-Log "NotesIndex: $($notesIndex.Count) entries from $notesCandidate"
            }
        }
    } else {
        Write-Host ("  WARNING: Collection dat not found at: {0}" -f $datFilePath) -ForegroundColor Yellow
        Write-Log "DatIndex: file not found at $datFilePath -- skipping."
    }
}

# Merge supplementary overrides into the collection index.
# Supplementary entries take precedence for the same normalized game name,
# so the alternate version from the supplementary dat is used instead of
# the collection version (only one version can be installed at a time).
if ($suppIndex.Count -gt 0) {
    foreach ($k in $suppIndex.Keys) {
        $datIndex[$k] = $suppIndex[$k]
        [void]$suppCodes.Add($suppIndex[$k].ProfileCode)
    }
    Write-Log "DatIndex: merged $($suppIndex.Count) supplementary overrides ($($suppCodes.Count) profile codes)."
}

# =============================================================================
# PROFILE SET  (fetched once; used by Resolve-ProfileCode during registration)
# =============================================================================
$profileSet = $null
if ($datIndex.Count -gt 0 -and $gameProfilesDir) {
    Write-Host ""
    Write-Host "Loading TeknoParrot GameProfiles list..." -ForegroundColor DarkGray
    $script:TpmProfileSetSource = $null
    $profileSet = Get-TeknoParrotProfileSet $gameProfilesDir
    $profileSetSource = if ($script:TpmProfileSetSource) { [string]$script:TpmProfileSetSource.Source } else { '' }
    if ($profileSet.Count -gt 0 -and $profileSetSource -eq 'Live') {
        Write-Host ("  Profile set: {0} profiles from the live TeknoParrot list (used for dat code resolution)." -f $profileSet.Count) -ForegroundColor DarkGray
    } elseif ($profileSet.Count -gt 0) {
        # Successful fallback: local GameProfiles are the templates and the
        # Eggman DAT already identifies the games.
        Write-Host ("  Profile set: {0} local GameProfiles templates; Eggman's DAT ({1} games) identifies games." -f $profileSet.Count, $datIndex.Count) -ForegroundColor DarkGray
        Write-Host "  (The live TeknoParrot profile list is not available, so the local list is used.)" -ForegroundColor DarkGray
    } else {
        Write-Host "  Profile set: no local GameProfiles templates were found and the live TeknoParrot list is not available." -ForegroundColor Yellow
        Write-Host "  Eggman's DAT still identifies games; profile codes are used exactly as the DAT lists them." -ForegroundColor DarkGray
    }
}

# =============================================================================
# ADAPTIVE MAIN MENU (issue #104) -- one compact default with an explicitly
# safe wide tier for genuinely large viewports.
#
# Normal Windows Terminal/PowerShell launches must not choose a two-column
# presentation merely because the host reports spare horizontal space. The
# wide tier is enabled only when both dimensions clear the conservative
# thresholds returned by Get-MainMenuWideLayoutPolicy. All other viewports use
# the compact one-column presentation; short-height fallback remains inside
# that presentation.
# =============================================================================

function Get-MainMenuWideLayoutPolicy {
    return [pscustomobject]@{
        MinimumWidth  = 200
        MinimumHeight = 50
    }
}

# Pure/testable: chooses the production default menu tier. The compact tier is
# intentionally the default even when width is available. Two columns require
# both conservative width and height margins so descriptions remain single
# line and the complete menu remains visible.
function Get-ConsoleLayoutTier {
    param(
        [int]$Width,
        [int]$Height
    )
    $widePolicy = Get-MainMenuWideLayoutPolicy
    if ($Width -ge $widePolicy.MinimumWidth -and $Height -ge $widePolicy.MinimumHeight) {
        return 'Ultra'
    }
    return 'Compact'
}

# Single source of truth for every menu item's number, mode string, section,
# and description -- ShortDesc (one line) and FullDesc (an array of lines).
# Adding, renumbering, or re-sectioning a menu item only ever needs to change
# this array -- every rendering tier and the "Enter 1-N" prompt derive from
# it. Different tiers show different levels of detail derived from these two
# fields (or neither, for Standard/Compact's labels-only rendering) -- see
# "Description text sourcing varies by tier" in ARCHITECTURE.md for exactly
# which tier uses which field. A function (not a plain script-scope
# variable) so it is picked up by the test suite's AST-based function
# extraction like every other testable helper in this script -- see the
# "Main menu source-level drift check" Describe block in
# Tests/TeknoParrot-Manager.Tests.ps1.
function Get-MainMenuSections {
    return @(
    [pscustomobject]@{
        Header = 'Library Management'
        Column = 'Left'
        Items  = @(
            [pscustomobject]@{ Number = 1; Mode = 'AutoSync'; Label = 'AutoSync'; ShortDesc = 'Extract your game ZIPs, then register the games.'; FullDesc = @('Extract your game ZIPs into your games', 'folder, then register the games.') }
            [pscustomobject]@{ Number = 2; Mode = 'RegisterOnly'; Label = 'Register only'; ShortDesc = 'Register games you already extracted.'; FullDesc = @('Register games already in the games folder.') }
            [pscustomobject]@{ Number = 3; Mode = 'PropagateControls'; Label = 'Propagate Controls'; ShortDesc = 'Copy controls from a set-up game to others.'; FullDesc = @('Copy controls from a game you set up', 'to games of the same type, without', 'going through AutoSync/Register first.') }
        )
    }
    [pscustomobject]@{
        Header = 'Game Enhancements (optional -- not every game needs them)'
        Column = 'Left'
        Items  = @(
            [pscustomobject]@{ Number = 4; Mode = 'CrosshairSetup'; Label = 'Crosshair setup'; ShortDesc = 'Deploy custom crosshairs to lightgun games.'; FullDesc = @('Pick and deploy custom crosshairs to all', 'registered lightgun games.') }
            [pscustomobject]@{ Number = 5; Mode = 'ReShadeSetup'; Label = 'ReShade setup'; ShortDesc = 'Visual filters: sharper image, CRT-style scanlines, borders.'; FullDesc = @('ReShade adds post-processing filters on top of', 'the game -- sharper image, better colors,', 'CRT-style scanlines, and screen borders, for a', 'more authentic arcade-cabinet look.') }
            [pscustomobject]@{ Number = 6; Mode = 'DgVoodoo2Setup'; Label = 'dgVoodoo2 setup'; ShortDesc = 'Fix some old DX8/Glide game crashes.'; FullDesc = @('Fix some old DX8, DirectDraw, and Glide game', 'crashes or black screens.') }
            [pscustomobject]@{ Number = 7; Mode = 'GpuFixSetup'; Label = 'GPU fix setup'; ShortDesc = 'Auto-detect GPU, apply matching compatibility fix.'; FullDesc = @('Auto-detect your GPU (AMD / NVIDIA / Intel) and', 'apply the matching compatibility fix to every', 'registered game that has one.') }
            [pscustomobject]@{ Number = 8; Mode = 'FFBSetup'; Label = 'Force feedback (FFB) setup'; ShortDesc = 'Wheel/stick rumble and force feedback.'; FullDesc = @('Wheel/stick rumble and force feedback.', "Covers TeknoParrot's built-in FFB Blaster (needs a", 'paid membership) and a free third-party plugin.') }
            [pscustomobject]@{ Number = 9; Mode = 'BepInExUpdate'; Label = 'BepInEx setup'; ShortDesc = 'Install or update BepInEx (a game modding framework).'; FullDesc = @('BepInEx is a modding framework some games use', 'for extra features and fixes. TPM can install or', 'update it after you approve; repair-reset is', 'unavailable. Unsafe folders and failed downloads', 'make no changes.') }
            [pscustomobject]@{ Number = 10; Mode = 'RegionSetup'; Label = 'Region setup'; ShortDesc = 'Choose the country your games start in.'; FullDesc = @('Pick a country (like USA or Europe) and set it', 'on the games that offer it. You can pick which', 'games, and go back to Auto at any time.') }
        )
    }
    [pscustomobject]@{
        Header = 'Game Requirements (only for some games)'
        Column = 'Right'
        Items  = @(
            [pscustomobject]@{ Number = 11; Mode = 'PostgresSetup'; Label = 'Postgres setup'; ShortDesc = 'PostgreSQL for games set to Existing PostgreSQL.'; FullDesc = @('For games set to Existing PostgreSQL.', 'Installs/configures local PostgreSQL 8.3 for', 'every Golden Tee Live and PGA Tour game,', 'Power Putt Live, Silver Strike Bowling Live,', 'Target Toss Pro and Orange County Choppers.', 'Games on Internal storage (the new default)', 'need no database install and are skipped.', 'A missing game database is made from the', 'game''s own backup. A game that ships none is', 'left to TeknoParrot to make on first start.', "Administrator is required if PostgreSQL isn't", 'installed yet.') }
            [pscustomobject]@{ Number = 12; Mode = 'RequiredPatch'; Label = 'Required game patches'; ShortDesc = 'Find and safely install supported required fixes from your local ZIPs.'; FullDesc = @('Find required patches for supported exact', 'game builds using your local Main or', 'Supplementary ZIP files. TPM validates the', 'game, backs up, applies, and verifies files.', 'A verified patch is not gameplay proof.') }
        )
    }
    [pscustomobject]@{
        Header = 'Maintenance and Recovery'
        Column = 'Right'
        Items  = @(
            [pscustomobject]@{ Number = 13; Mode = 'HealthCheck'; Label = 'Library health check'; ShortDesc = 'Check your library without changing it.'; FullDesc = @('Reports registered/broken/unregistered games', 'plus GPU fix / FFB Blaster / dgVoodoo2 and', 'ReShade/BepInEx counts, without changing', 'anything. Any repair it suggests is a separate', 'choice that you confirm first.') }
            [pscustomobject]@{ Number = 14; Mode = 'Restore'; Label = 'Restore backup'; ShortDesc = 'Restore UserProfiles, PostgreSQL, or LaunchBox snapshots.'; FullDesc = @('Restore selected backup files with verification.', 'LaunchBox recovery first backs up current targets;', 'keep LaunchBox and BigBox closed throughout.') }
        )
    }
    [pscustomobject]@{
        Header = 'Application'
        Column = 'Right'
        Items  = @(
            [pscustomobject]@{ Number = 15; Mode = 'CheckForUpdates'; Label = 'Check for Updates'; ShortDesc = 'Manual check against the latest GitHub release.'; FullDesc = @('Manual check against the latest', 'GitHub release. Nothing is downloaded or changed', 'without your explicit confirmation.') }
            [pscustomobject]@{ Number = 16; Mode = 'Support'; Label = 'Create Support Package'; ShortDesc = 'Gather safe logs and reports into one ZIP.'; FullDesc = @('Gather safe TPM, TeknoParrot, and game diagnostics', 'into one ZIP you can send when asking for help.') }
            [pscustomobject]@{ Number = 17; Mode = 'Exit'; Label = 'Exit'; ShortDesc = ''; FullDesc = @() }
        )
    }
    )
}

# Flat, number-ordered view of every item across all sections -- used to
# derive the highest option number (the "Enter 1-N" prompt) and to look an
# item up by number without every caller re-flattening the section list.
function Get-MainMenuItems {
    return @(Get-MainMenuSections | ForEach-Object { $_.Items })
}

function New-ConsoleRenderRow {
    param(
        [string]$Text = '',
        [string]$Color = 'White'
    )
    return [pscustomobject]@{ Text = $Text; Color = $Color; Segments = $null }
}

function New-ConsoleRenderSegmentRow {
    param([object[]]$Segments)
    $text = (($Segments | ForEach-Object { $_.Text }) -join '')
    return [pscustomobject]@{ Text = $text; Color = 'White'; Segments = $Segments }
}

function New-ConsoleRenderSegment {
    param(
        [string]$Text = '',
        [string]$Color = 'White'
    )
    return [pscustomobject]@{ Text = $Text; Color = $Color }
}

function Get-MainMenuSectionColor {
    param([string]$Header)
    if ($Header -like 'Library Management*') { return 'Cyan' }
    if ($Header -like 'Game *') { return 'Green' }
    if ($Header -like 'Maintenance*') { return 'Magenta' }
    if ($Header -like 'Application*') { return 'Yellow' }
    return 'White'
}

function Get-MainMenuGeometry {
    param(
        [ValidateSet('Ultra', 'Compact')][string]$Tier,
        [int]$ViewportWidth,
        [int]$ViewportHeight
    )

    $safeWidth = [Math]::Max(40, $ViewportWidth)
    $safeHeight = [Math]::Max(10, $ViewportHeight)
    $contentWidth = [Math]::Max(38, $safeWidth - 2)
    $layout = 'Compact'
    $columnCount = 1
    $gutterWidth = 0
    $menuWidth = [Math]::Min($contentWidth, 88)
    $columnWidth = $menuWidth
    $rightColumnWidth = $columnWidth
    $footerWidth = $menuWidth
    $wrapWidth = [Math]::Max(24, $columnWidth - 8)
    $frameEnabled = $false

    if ($Tier -eq 'Ultra') {
        $layout = 'UltraTwoColumn'
        $columnCount = 2
        $gutterWidth = 3
        $menuWidth = $contentWidth
        $frameEnabled = $true
        $columnWidth = [Math]::Floor(($menuWidth - 4 - $gutterWidth) / 2)
        $rightColumnWidth = $menuWidth - 4 - $gutterWidth - $columnWidth
        $footerWidth = $menuWidth
        $wrapWidth = [Math]::Max(42, $columnWidth - 8)
    }

    $leftPadding = [Math]::Max(0, [Math]::Floor(($safeWidth - $menuWidth) / 2))
    return [pscustomobject]@{
        ViewportWidth = $safeWidth
        ViewportHeight = $safeHeight
        Tier = $Tier
        Layout = $layout
        MenuWidth = $menuWidth
        ColumnCount = $columnCount
        ColumnWidth = $columnWidth
        RightColumnWidth = $rightColumnWidth
        GutterWidth = $gutterWidth
        FooterWidth = $footerWidth
        WrapWidth = $wrapWidth
        LeftPadding = $leftPadding
        FrameEnabled = $frameEnabled
    }
}

function Get-ConsoleContentHeight {
    try {
        $height = [int]$Host.UI.RawUI.WindowSize.Height
        if ($height -gt 0) { return $height }
    } catch {}
    try {
        $height = [int][Console]::WindowHeight
        if ($height -gt 0) { return $height }
    } catch {}
    try {
        $height = [int]$Host.UI.RawUI.BufferSize.Height
        if ($height -gt 0) { return $height }
    } catch {}
    return 25
}

function Get-PaddedMainMenuRows {
    param(
        [object[]]$Rows,
        [int]$Padding
    )
    if ($Padding -le 0) { return @($Rows) }
    $prefix = ' ' * $Padding
    return @($Rows | ForEach-Object {
        if ($_.Segments) {
            New-ConsoleRenderSegmentRow -Segments (@((New-ConsoleRenderSegment -Text $prefix -Color 'White')) + $_.Segments)
        } else {
            New-ConsoleRenderRow -Text ($prefix + $_.Text) -Color $_.Color
        }
    })
}

function Get-MainMenuBannerRows {
    param([object]$Geometry)
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($row in (Get-ManagerBannerRows -Width $Geometry.MenuWidth)) {
        if ($row.Segments) {
            $segments = @($row.Segments | ForEach-Object { New-ConsoleRenderSegment -Text $_.Text -Color $_.Color })
            [void]$rows.Add((New-ConsoleRenderSegmentRow -Segments $segments))
        } else {
            [void]$rows.Add((New-ConsoleRenderRow -Text $row.Text -Color $row.Color))
        }
    }
    [void]$rows.Add((New-ConsoleRenderRow))
    return @(Get-PaddedMainMenuRows -Rows $rows.ToArray() -Padding $Geometry.LeftPadding)
}

function Get-MainMenuFooterRows {
    param(
        [object]$Geometry,
        [string]$Notice = ''
    )
    $rows = New-Object System.Collections.Generic.List[object]
    $footer = 'Enter number and press Enter | H = Help | L = View Log | Q = Quit'
    if ($footer.Length -gt $Geometry.FooterWidth) { $footer = 'Enter number | H=Help | L=Log | Q=Quit' }
    if ($footer.Length -gt $Geometry.FooterWidth) { $footer = 'Enter number | H=Help | Q=Quit' }
    if ($Geometry.FrameEnabled) { [void]$rows.Add((New-ConsoleRenderRow -Text ('+' + ('-' * ($Geometry.FooterWidth - 2)) + '+') -Color 'DarkCyan')) }
    if (-not [string]::IsNullOrWhiteSpace($Notice)) {
        foreach ($line in (Split-TextForMenuWidth -Text $Notice -Width ([Math]::Max(20, $Geometry.FooterWidth - 4)))) {
            [void]$rows.Add((New-ConsoleRenderRow -Text ('  ' + $line) -Color 'Yellow'))
        }
    }
    foreach ($line in (Split-TextForMenuWidth -Text $footer -Width $Geometry.FooterWidth)) {
        $pad = [Math]::Max(0, [Math]::Floor(($Geometry.FooterWidth - $line.Length) / 2))
        [void]$rows.Add((New-ConsoleRenderRow -Text ((' ' * $pad) + $line) -Color 'White'))
    }
    if ($Geometry.FrameEnabled) { [void]$rows.Add((New-ConsoleRenderRow -Text ('+' + ('-' * ($Geometry.FooterWidth - 2)) + '+') -Color 'DarkCyan')) }
    return @(Get-PaddedMainMenuRows -Rows $rows.ToArray() -Padding $Geometry.LeftPadding)
}

function Get-MainMenuSectionRows {
    param(
        [object]$Section,
        [object]$Geometry,
        [ValidateSet('Full', 'Short', 'Labels')][string]$Detail = 'Full'
    )

    $rows = New-Object System.Collections.Generic.List[object]
    $color = Get-MainMenuSectionColor -Header $Section.Header
    $sectionHeader = $Section.Header
    $header = (' {0} ' -f $sectionHeader.ToUpperInvariant())
    $ruleCount = [Math]::Max(4, $Geometry.ColumnWidth - $header.Length)
    [void]$rows.Add((New-ConsoleRenderRow -Text (($header + ('-' * $ruleCount)).Substring(0, [Math]::Min($Geometry.ColumnWidth, $header.Length + $ruleCount))) -Color $color))

    foreach ($item in $Section.Items) {
        [void]$rows.Add((New-ConsoleRenderRow -Text ('  {0}) {1}' -f $item.Number, $item.Label) -Color $color))
        if ($Detail -ne 'Labels') {
            $descText = if ($Detail -eq 'Short') { $item.ShortDesc } else { ($item.FullDesc -join ' ') }
            foreach ($line in (Split-TextForMenuWidth -Text $descText -Width $Geometry.WrapWidth)) {
                [void]$rows.Add((New-ConsoleRenderRow -Text ('      {0}' -f $line) -Color 'White'))
            }
        }
        if ($Geometry.ColumnCount -ne 2 -and $Detail -ne 'Labels') {
            [void]$rows.Add((New-ConsoleRenderRow))
        }
    }
    return $rows.ToArray()
}

function Join-MainMenuRenderColumns {
    param(
        [object[]]$LeftRows,
        [object[]]$RightRows,
        [object]$Geometry
    )

    $rows = New-Object System.Collections.Generic.List[object]
    $count = [Math]::Max($LeftRows.Count, $RightRows.Count)
    for ($i = 0; $i -lt $count; $i++) {
        $left = if ($i -lt $LeftRows.Count) { $LeftRows[$i] } else { New-ConsoleRenderRow }
        $right = if ($i -lt $RightRows.Count) { $RightRows[$i] } else { New-ConsoleRenderRow }
        $segments = @()
        if ($Geometry.FrameEnabled) {
            $segments += New-ConsoleRenderSegment -Text '| ' -Color 'DarkCyan'
        }
        $segments += New-ConsoleRenderSegment -Text ($left.Text.PadRight($Geometry.ColumnWidth)) -Color $left.Color
        $segments += New-ConsoleRenderSegment -Text ((' ' * [Math]::Max(0, [Math]::Floor(($Geometry.GutterWidth - 1) / 2))) + '|' + (' ' * [Math]::Max(0, $Geometry.GutterWidth - 1 - [Math]::Floor(($Geometry.GutterWidth - 1) / 2)))) -Color 'DarkCyan'
        $segments += New-ConsoleRenderSegment -Text ($right.Text.PadRight($Geometry.RightColumnWidth)) -Color $right.Color
        if ($Geometry.FrameEnabled) {
            $segments += New-ConsoleRenderSegment -Text ' |' -Color 'DarkCyan'
        }
        [void]$rows.Add((New-ConsoleRenderSegmentRow -Segments $segments))
    }
    return @(Get-PaddedMainMenuRows -Rows $rows.ToArray() -Padding $Geometry.LeftPadding)
}

function Get-MainMenuBodyRows {
    param(
        [object[]]$Sections,
        [object]$Geometry
    )

    $detail = 'Full'
    if ($Geometry.Tier -eq 'Compact') { $detail = 'Labels' }
    if ($Geometry.ColumnCount -eq 2) { $detail = 'Short' }

    if ($Geometry.ColumnCount -eq 2) {
        $leftRows = @()
        $rightRows = @()
        for ($i = 0; $i -lt $Sections.Count; $i++) {
            $section = $Sections[$i]
            $goesLeft = if ($section.PSObject.Properties['Column']) { [string]$section.Column -eq 'Left' } else { ($i % 2) -eq 0 }
            if ($goesLeft) {
                $leftRows += Get-MainMenuSectionRows -Section $section -Geometry $Geometry -Detail $detail
            } else {
                $rightRows += Get-MainMenuSectionRows -Section $section -Geometry $Geometry -Detail $detail
            }
        }
        return @(Join-MainMenuRenderColumns -LeftRows $leftRows -RightRows $rightRows -Geometry $Geometry)
    }

    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($section in $Sections) {
        foreach ($row in (Get-MainMenuSectionRows -Section $section -Geometry $Geometry -Detail $detail)) {
            [void]$rows.Add($row)
        }
    }
    return @(Get-PaddedMainMenuRows -Rows $rows.ToArray() -Padding $Geometry.LeftPadding)
}

function Limit-MainMenuRowsToViewport {
    param(
        [object[]]$Rows,
        [int]$ViewportHeight
    )

    $maxRows = [Math]::Max(5, $ViewportHeight - 2)
    if ($Rows.Count -le $maxRows) { return @($Rows) }
    return @($Rows | Select-Object -First $maxRows)
}

# Truncates BODY rows only (never the banner or footer) while preserving
# actionable menu rows and their descriptions as atomic display units.
# Two-column streams are trimmed only at numbered-row boundaries, preventing
# a visible description from outliving its heading.
function Limit-MainMenuBodyRowsToBudget {
    param(
        [object[]]$BodyRows,
        [int]$BodyBudget
    )

    if ($BodyBudget -le 0) { return @() }
    if ($BodyRows.Count -le $BodyBudget) { return @($BodyRows) }

    $start = $BodyRows.Count - $BodyBudget
    $isColumnar = @($BodyRows | Where-Object { $_.Segments }).Count -gt 0
    if ($isColumnar) {
        while ($start -lt $BodyRows.Count) {
            $text = [string]$BodyRows[$start].Text
            if ($text -match '^\s+\d+\)\s+') { break }
            $start++
        }
    }
    if ($start -ge $BodyRows.Count) { return @() }
    return @($BodyRows[$start..($BodyRows.Count - 1)])
}

# Single-line banner ("TeknoParrot Manager v1.0 RC9") with no frame and no
# blank separator, for viewports too short for the normal framed banner (5-6
# rows) to leave any room for menu content -- see
# Get-MainMenuEmergencyCompactRows.
function Get-MainMenuMinimalBannerRows {
    param([object]$Geometry)
    $text = "TeknoParrot Manager {0}" -f (Get-ManagerVersionLine)
    $text = $text -replace '^TeknoParrot Manager Version ', 'TeknoParrot Manager v'
    if ($text.Length -gt $Geometry.MenuWidth -and $Geometry.MenuWidth -gt 3) {
        $text = $text.Substring(0, $Geometry.MenuWidth)
    }
    return @(Get-PaddedMainMenuRows -Rows @((New-ConsoleRenderRow -Text $text -Color 'Cyan')) -Padding $Geometry.LeftPadding)
}

# Single-line footer with no frame/rule, for the same reason as
# Get-MainMenuMinimalBannerRows above.
function Get-MainMenuMinimalFooterRows {
    param(
        [object]$Geometry,
        [string]$Notice = ''
    )
    $rows = New-Object System.Collections.Generic.List[object]
    $footer = 'Enter number | H=Help | L=Log | Q=Quit'
    if ($footer.Length -gt $Geometry.FooterWidth) { $footer = 'Enter number | H=Help | Q=Quit' }
    if ($footer.Length -gt $Geometry.FooterWidth) { $footer = 'Enter number | Q=Quit' }
    if ($footer.Length -gt $Geometry.FooterWidth) { $footer = 'N | Q' }
    if (-not [string]::IsNullOrWhiteSpace($Notice)) {
        foreach ($line in (Split-TextForMenuWidth -Text $Notice -Width ([Math]::Max(20, $Geometry.FooterWidth - 2)))) {
            [void]$rows.Add((New-ConsoleRenderRow -Text $line -Color 'Yellow'))
        }
    }
    [void]$rows.Add((New-ConsoleRenderRow -Text $footer -Color 'White'))
    return @(Get-PaddedMainMenuRows -Rows $rows.ToArray() -Padding $Geometry.LeftPadding)
}

# Packs each menu item's number and label into rows for very short viewports.
# At sizes where the categorized layout cannot show every option, section
# headings are dropped and all numbered options remain visible.
function Get-MainMenuFlowPackedItemRows {
    param(
        [int]$Width,
        [object]$Geometry
    )
    $tokens = @((Get-MainMenuItems) | ForEach-Object { '{0}) {1}' -f $_.Number, $_.Label })
    $wrapWidth = [Math]::Max(20, $Width)

    # Packs whole "N) Label" tokens greedily, never splitting one across two
    # lines -- unlike a generic word-wrap (e.g. Split-TextForMenuWidth),
    # which treats "4)" and "Crosshair" as separate words and can break an
    # option's number from its own label at a line boundary. A single
    # option's number and name staying on one line matters more here than
    # tight packing, since this is the presentation a very-short-viewport
    # user reads to figure out what to type.
    $lines = New-Object System.Collections.Generic.List[string]
    $current = ''
    foreach ($token in $tokens) {
        if ($current.Length -eq 0) {
            $current = $token
        } elseif (($current.Length + 2 + $token.Length) -le $wrapWidth) {
            $current = "$current  $token"
        } else {
            [void]$lines.Add($current)
            $current = $token
        }
    }
    if ($current.Length -gt 0) { [void]$lines.Add($current) }

    $rows = @($lines | ForEach-Object { New-ConsoleRenderRow -Text $_ -Color 'White' })
    return @(Get-PaddedMainMenuRows -Rows $rows -Padding $Geometry.LeftPadding)
}

# Emergency compact presentation for viewports too short to show all numbered options
function Get-MainMenuEmergencyCompactRows {
    param(
        [object]$Geometry,
        # Real terminal row budget (Max(5, real Height - 2)) -- when the
        # flow-packed item rows don't all fit alongside the minimal banner
        # and footer, those two are still NEVER dropped; item rows are
        # trimmed from the front instead (keeping the tail), so the last
        # item line -- which always ends with "17) Exit" -- and the footer
        # both survive even at a viewport too short to show every earlier
        # option. Below the documented 60x10 minimum this can still mean an
        # early option's line goes missing, but the footer and Exit itself
        # are the two guarantees that must never break.
        [int]$MaxRows = 0,
        [string]$Notice = ''
    )
    $bannerRows = @(Get-MainMenuMinimalBannerRows -Geometry $Geometry)
    $footerRows = @(Get-MainMenuMinimalFooterRows -Geometry $Geometry -Notice $Notice)
    $itemRows = @(Get-MainMenuFlowPackedItemRows -Width ([Math]::Max(20, $Geometry.MenuWidth - $Geometry.LeftPadding)) -Geometry $Geometry)

    if ($MaxRows -gt 0) {
        $itemBudget = [Math]::Max(0, $MaxRows - $bannerRows.Count - $footerRows.Count)
        if ($itemRows.Count -gt $itemBudget) {
            # At the minimum supported viewport, retain every actionable
            # number even when labels cannot fit. Number-only packing is a
            # deliberate last resort; silently dropping choices is not.
            $lastMenuItem = @((Get-MainMenuItems))[-1]
            $tokens = @((Get-MainMenuItems) | ForEach-Object {
                if ($_.Number -eq $lastMenuItem.Number) { '{0}) {1}' -f $_.Number, $_.Label } else { '{0})' -f $_.Number }
            })
            $packed = New-Object System.Collections.Generic.List[string]
            $current = ''
            foreach ($token in $tokens) {
                if ($current.Length -eq 0) { $current = $token }
                elseif (($current.Length + 1 + $token.Length) -le $Geometry.MenuWidth) { $current = "$current $token" }
                else { [void]$packed.Add($current); $current = $token }
            }
            if ($current.Length -gt 0) { [void]$packed.Add($current) }
            $itemRows = @($packed | ForEach-Object { New-ConsoleRenderRow -Text $_ -Color 'White' })
        }
        $itemRows = Limit-MainMenuBodyRowsToBudget -BodyRows $itemRows -BodyBudget $itemBudget
    }

    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($row in $bannerRows) { [void]$rows.Add($row) }
    foreach ($row in $itemRows) { [void]$rows.Add($row) }
    foreach ($row in $footerRows) { [void]$rows.Add($row) }
    return @($rows.ToArray())
}

function Get-MainMenuVisibleOptionNumbers {
    param([object[]]$Rows)
    $numbers = New-Object System.Collections.Generic.List[int]
    foreach ($row in @($Rows)) {
        foreach ($match in [regex]::Matches([string]$row.Text, '(?<!\d)(\d{1,2})\)(?=\s|$)')) {
            $number = [int]$match.Groups[1].Value
            if (-not $numbers.Contains($number)) { [void]$numbers.Add($number) }
        }
    }
    return @($numbers | Sort-Object)
}
function New-MainMenuScreenResult {
    param(
        [Parameter(Mandatory)]$Geometry,
        [Parameter(Mandatory)][object[]]$Rows,
        [int]$ViewportHeight = 0,
        [string]$Notice = ''
    )
    if ($ViewportHeight -le 0) { $ViewportHeight = $Geometry.ViewportHeight }
    $expected = @((Get-MainMenuItems | ForEach-Object { [int]$_.Number }))
    $visible = @(Get-MainMenuVisibleOptionNumbers -Rows $Rows)
    $missing = @($expected | Where-Object { $visible -notcontains $_ })
    $allowed = ($ViewportHeight -ge 10 -and $expected.Count -gt 0 -and $missing.Count -eq 0)
    if (-not $allowed) {
        $fallbackRows = @()
        if ($ViewportHeight -ge 20) {
            $fallbackRows = @((Get-MainMenuBannerRows -Geometry $Geometry); (Get-MainMenuFlowPackedItemRows -Width ([Math]::Max(20, $Geometry.MenuWidth - $Geometry.LeftPadding)) -Geometry $Geometry); (Get-MainMenuFooterRows -Geometry $Geometry -Notice $Notice))
        } else {
            $fallbackRows = @(Get-MainMenuEmergencyCompactRows -Geometry $Geometry -MaxRows $ViewportHeight -Notice $Notice)
        }
        $fallbackVisible = @(Get-MainMenuVisibleOptionNumbers -Rows $fallbackRows)
        # Below 10 rows the packed layout is accepted only when every option keeps its name, so the user never sees a bare list of numbers.
        $fallbackText = (@($fallbackRows | ForEach-Object { [string]$_.Text }) -join "`n")
        $fallbackNamed = ($ViewportHeight -ge 10) -or (@(Get-MainMenuItems | Where-Object { $fallbackText.IndexOf(('{0}) {1}' -f $_.Number, $_.Label), [System.StringComparison]::Ordinal) -lt 0 }).Count -eq 0)
        if ($fallbackNamed -and @($expected | Where-Object { $fallbackVisible -notcontains $_ }).Count -eq 0 -and $fallbackRows.Count -le ($ViewportHeight - 2)) {
            $Rows = $fallbackRows
            $visible = $fallbackVisible
            $missing = @()
            $allowed = $true
        } else {
            $Rows = @((Get-MainMenuMinimalBannerRows -Geometry $Geometry); (New-ConsoleRenderRow -Text '  The menu options do not fit in this window.' -Color 'Yellow'); (New-ConsoleRenderRow -Text '  Resize the PowerShell window and press Enter to redraw, or type Q to quit.'))
        }
    }
    return [pscustomobject]@{ Geometry = $Geometry; Rows = @($Rows); VisibleOptionNumbers = $visible; MissingOptionNumbers = $missing; AllOptionsVisible = $allowed; PromptAllowed = $allowed }
}

function Render-MainMenuScreen {
    param(
        [ValidateSet('Ultra', 'Compact')][string]$Tier,
        [int]$Width,
        [int]$Height,
        [string]$Notice = ''
    )

    $geometry = Get-MainMenuGeometry -Tier $Tier -ViewportWidth $Width -ViewportHeight $Height
    $sections = @(Get-MainMenuSections)
    $bannerRows = @(Get-MainMenuBannerRows -Geometry $geometry)
    $footerRows = @(Get-MainMenuFooterRows -Geometry $geometry -Notice $Notice)
    $bodyRows = @(Get-MainMenuBodyRows -Sections $sections -Geometry $geometry)

    # Uses the caller's real requested $Height here, NOT $geometry.ViewportHeight
    # -- Get-MainMenuGeometry internally clamps ViewportHeight to a floor of 10
    # for its own column/description-width math, which is correct for that
    # purpose but would silently let more rows render than an actually-shorter
    # real terminal (e.g. height 8 or 9) can show without scrolling if reused
    # here for the row-count budget/cap.
    $maxTotalRows = [Math]::Max(5, $Height - 2)
    $reserved = $bannerRows.Count + $footerRows.Count
    $bodyBudget = [Math]::Max(0, $maxTotalRows - $reserved)

    # If the normal (one item per row) body can't fit every option even
    # after trimming, switch to the emergency flow-packed presentation
    # instead of silently dropping options -- see
    # Get-MainMenuEmergencyCompactRows. $totalItemCount is the number of
    # individual item rows the normal Labels-detail body needs at minimum
    # (ignoring section headers/blank lines, which are the first things
    # trimmed); if the budget can't even hold that many rows, some options
    # would be dropped, not just descriptions.
    $totalItemCount = (Get-MainMenuItems).Count
    if ($bodyBudget -lt $totalItemCount) {
        # $maxTotalRows (real Height - 2, not the geometry-clamped height)
        # is passed straight through as the row budget -- NOT run back
        # through Limit-MainMenuRowsToViewport's generic front-truncation,
        # which would cut off the LAST rows (the footer) once content
        # overflowed. Get-MainMenuEmergencyCompactRows reserves the banner
        # and footer unconditionally and only trims item rows if needed.
        $rows = Get-MainMenuEmergencyCompactRows -Geometry $geometry -MaxRows $maxTotalRows -Notice $Notice
        return New-MainMenuScreenResult -Geometry $geometry -Rows $rows -ViewportHeight $Height -Notice $Notice
    }

    $bodyRows = Limit-MainMenuBodyRowsToBudget -BodyRows $bodyRows -BodyBudget $bodyBudget

    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($row in $bannerRows) { [void]$rows.Add($row) }
    foreach ($row in $bodyRows) { [void]$rows.Add($row) }
    foreach ($row in $footerRows) { [void]$rows.Add($row) }
    return New-MainMenuScreenResult -Geometry $geometry -Rows (Limit-MainMenuRowsToViewport -Rows $rows.ToArray() -ViewportHeight $Height) -ViewportHeight $Height -Notice $Notice
}

function Write-ConsoleRenderRows {
    param([object[]]$Rows)
    foreach ($row in $Rows) {
        if ($row.Segments) {
            foreach ($segment in $row.Segments) {
                $segmentColor = if ($segment.Color) { $segment.Color } else { 'White' }
                Write-Host $segment.Text -ForegroundColor $segmentColor -NoNewline
            }
            Write-Host ''
            continue
        }
        $color = if ($row.Color) { $row.Color } else { 'White' }
        Write-Host $row.Text -ForegroundColor $color
    }
}

function Clear-ConsoleForFreshRender {
    Set-ConsoleRenderOrigin
    try {
        Clear-Host
        Set-ConsoleRenderOrigin
        return
    } catch {}

    try {
        [Console]::Clear()
        Set-ConsoleRenderOrigin
        return
    } catch {}

    Set-ConsoleRenderOrigin
    Write-Host ''
}

function Set-ConsoleRenderOrigin {
    try {
        $rawUi = $Host.UI.RawUI
        $zero = [System.Management.Automation.Host.Coordinates]::new(0, 0)
        $rawUi.CursorPosition = $zero
        $rawUi.WindowPosition = $zero
    } catch {}

    try {
        [Console]::SetCursorPosition(0, 0)
    } catch {}
}

# Seam (FIX52, issue #384): the window class of this process's console window, or $null when it cannot be read.
# Classic conhost answers 'ConsoleWindowClass'; a pseudo console (ConPTY) hosted by a terminal such as Windows Terminal
# answers 'PseudoConsoleWindow'. Never throws.
function Get-TpmConsoleWindowClass {
    try {
        if (-not ('TpmConsoleHostNative' -as [type])) {
            Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
using System.Text;
public static class TpmConsoleHostNative {
    [DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow();
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern int GetClassName(IntPtr hWnd, StringBuilder name, int count);
}
'@
        }
        $handle = [TpmConsoleHostNative]::GetConsoleWindow()
        if ($handle -eq [IntPtr]::Zero) { return $null }
        $name = New-Object System.Text.StringBuilder 256
        if ([TpmConsoleHostNative]::GetClassName($handle, $name, $name.Capacity) -le 0) { return $null }
        return $name.ToString()
    } catch {
        return $null
    }
}

# FIX52 (issue #384): $true when a terminal emulator owns this console's window size, so TeknoParrot Manager must never
# resize it. Windows Terminal does not set WT_SESSION when Windows hands it a console started by double-clicking a .bat
# (default-terminal hand-off, microsoft/terminal#13006); the console window is then a 'PseudoConsoleWindow'. Resizing such
# a console made it report 1904 columns inside a 120-column window (measured on a test PC), so every row composed to the
# reported width wrapped. Markers, any one is enough:
#   - WT_SESSION or WT_PROFILE_ID (set by Windows Terminal for its own tabs);
#   - TERM_PROGRAM (set by terminal emulators such as VS Code's; classic conhost never sets it);
#   - a console window class other than 'ConsoleWindowClass' (classic conhost), including 'PseudoConsoleWindow'.
# A class that cannot be read counts as terminal-hosted: not resizing is the safe answer.
function Test-TpmConsoleTerminalHosted {
    foreach ($name in @('WT_SESSION', 'WT_PROFILE_ID', 'TERM_PROGRAM')) {
        if (-not [string]::IsNullOrWhiteSpace([Environment]::GetEnvironmentVariable($name))) { return $true }
    }
    $windowClass = Get-TpmConsoleWindowClass
    return (-not [string]::Equals([string]$windowClass, 'ConsoleWindowClass', [System.StringComparison]::Ordinal))
}

# Best-effort console maximize -- many hosts (redirected output, ISE, some
# CI/test runners) don't support resizing the window at all; this must never
# throw or block startup over a cosmetic nicety. Called once, not on every
# menu redraw -- unlike layout-tier detection, which does run every redraw
# so a user resizing mid-session still gets the right tier next time the
# menu draws. Only a classic conhost window is maximized; a console hosted by
# a terminal (Test-TpmConsoleTerminalHosted) keeps the size its terminal gave it.
function Set-ConsoleMaximizedIfSupported {
    param([object]$RawUi = $null, [Nullable[bool]]$TerminalManaged = $null)
    if ($script:TpmConsoleResizeAttempted) { return }
    $script:TpmConsoleResizeAttempted = $true
    try {
        # Redirected output cannot be resized: decided before the window-class read, which compiles a small native helper.
        if ($null -eq $RawUi) {
            try {
                if ([Console]::IsInputRedirected -or [Console]::IsOutputRedirected) { return }
            } catch {}
        }
        if ($null -eq $TerminalManaged) {
            $TerminalManaged = Test-TpmConsoleTerminalHosted
        }
        # A terminal owns its viewport; its hardware maximum is not the
        # current character-cell geometry and must not drive cosmetic resizing.
        if ($TerminalManaged) {
            Write-Log 'Set-ConsoleMaximizedIfSupported: console is hosted by a terminal (or its window class could not be read); size left unchanged.'
            return
        }
        if ($null -eq $RawUi) { $RawUi = $Host.UI.RawUI }
        $maxSize = $RawUi.MaxPhysicalWindowSize
        if ($maxSize.Width -gt 0 -and $maxSize.Height -gt 0) {
            $currentBuffer = $RawUi.BufferSize
            $targetWidth = [Math]::Max(1, $maxSize.Width)
            $targetHeight = [Math]::Max(1, $maxSize.Height)
            if ($currentBuffer.Width -lt $targetWidth -or $currentBuffer.Height -lt $targetHeight) {
                $bufferWidth = [Math]::Max($currentBuffer.Width, $targetWidth)
                $bufferHeight = [Math]::Max($currentBuffer.Height, $targetHeight)
                $RawUi.BufferSize = [System.Management.Automation.Host.Size]::new($bufferWidth, $bufferHeight)
            }
            $RawUi.WindowSize = [System.Management.Automation.Host.Size]::new([Math]::Min($targetWidth, $RawUi.BufferSize.Width), [Math]::Min($targetHeight, $RawUi.BufferSize.Height))
        }
    } catch {
        Write-Log "Set-ConsoleMaximizedIfSupported: could not resize console -- $_"
    }
}

# Renders the main menu at the given tier. Pure display -- never reads input,
# never touches $mode; the caller's existing Read-Host/switch dispatch is
# completely unchanged by this function or by which tier is chosen.
function Show-MainMenu {
    param(
        [ValidateSet('Ultra', 'Compact')][string]$Tier,
        [int]$Width = (Get-ConsoleContentWidth),
        [int]$Height = (Get-ConsoleContentHeight),
        [string]$Notice = '',
        [switch]$ReturnScreen
    )
    $screen = Render-MainMenuScreen -Tier $Tier -Width $Width -Height $Height -Notice $Notice
    Clear-ConsoleForFreshRender
    Write-ConsoleRenderRows -Rows $screen.Rows
    if ($ReturnScreen) { return $screen }
}

function Resolve-MainMenuCommand {
    param([AllowEmptyString()][string]$InputText, [Parameter(Mandatory)][int]$MaxNumber)
    $choice = if ($null -eq $InputText) { '' } else { $InputText.Trim() }
    if ($choice -match '^\d+$') {
        $number = 0
        if ([int]::TryParse($choice, [ref]$number) -and $choice -eq [string]$number -and $number -ge 1 -and $number -le $MaxNumber) { return $choice }
        return $null
    }
    switch ($choice.ToUpperInvariant()) {
        'H' { return 'H' }
        'L' { return 'L' }
        'Q' { return 'Q' }
        default { return $null }
    }
}


# Pure: the numbered Help lines. Every option number is looked up by mode in Get-MainMenuItems (the same model the
# menu renders and its dispatch is drift-checked against), so Help cannot quote a stale number again.
function Get-MainMenuHelpLines {
    $number = @{}
    foreach ($item in @(Get-MainMenuItems)) { $number[[string]$item.Mode] = [int]$item.Number }
    return @(
        '  Set up your games:'
        ('  {0} AutoSync: extract your game ZIPs, then register the games.' -f $number['AutoSync'])
        ('  {0} Register only: register games already in your games folder.' -f $number['RegisterOnly'])
        ('  {0}-{1} Copy controls, game extras, PostgreSQL setup and repair, and required game patches.' -f $number['PropagateControls'], $number['RequiredPatch'])
        ''
        '  Check and fix:'
        ('  {0} Library health check: see your library status without changing it.' -f $number['HealthCheck'])
        ('  {0} Restore from a trusted backup.' -f $number['Restore'])
        ''
        ('  About option {0}, PostgreSQL setup:' -f $number['PostgresSetup'])
        '     Administrator approval lets setup try to continue.'
        '     It does not mean the setup worked.'
        ('     If setup stops, read its message and View Log before trying option {0} again.' -f $number['PostgresSetup'])
        ''
        '  Other:'
        ('  {0} Check for updates.' -f $number['CheckForUpdates'])
        ('  {0} Create a support package.' -f $number['Support'])
        ('  {0} Exit.' -f $number['Exit'])
    )
}

# Prints the Help lines wrapped to the console width. A numbered line keeps its text under its own text when it
# wraps; a heading (a line that ends with a colon) is cyan; an empty line is a blank line.
function Show-MainMenuHelp {
    Clear-ConsoleForFreshRender
    Write-Host 'TeknoParrot Manager Help' -ForegroundColor Cyan
    Write-Host '========================' -ForegroundColor Cyan
    Write-Host ''
    foreach ($helpLine in @(Get-MainMenuHelpLines)) {
        if ([string]::IsNullOrWhiteSpace($helpLine)) { Write-Host ''; continue }
        $indent = $helpLine.Length - $helpLine.TrimStart().Length
        $numbered = [regex]::Match($helpLine.Trim(), '^(?<number>\d+(?:-\d+)?) (?<text>.+)$')
        if ($numbered.Success) {
            Write-TpmText -Text $numbered.Groups['text'].Value -Prefix ($numbered.Groups['number'].Value + ' ') -Indent $indent
            continue
        }
        Write-TpmText -Text $helpLine.Trim() -Indent $indent -Color $(if ($helpLine.Trim().EndsWith(':')) { 'Cyan' } else { '' })
    }
    Write-Host ''
    Write-TpmText -Text 'These never change your games: Help, View Log, the health check, and previews.'
    Write-TpmText -Text 'These can change files: AutoSync, Register, setup, restore, and updates.'
    Write-Host ''
    Write-TpmText -Text 'Enter a number only when it is shown in the main menu.'
    Write-Host ''
    [void](Read-HostSafe '  Press Enter to return')
}

function Read-MainMenuChoiceResponsive {
    param(
        [string]$Prompt,
        [int]$InitialWidth,
        [int]$InitialHeight
    )

    $readHostPrompt = $Prompt.TrimEnd()
    if ($readHostPrompt.EndsWith(':')) {
        $readHostPrompt = $readHostPrompt.Substring(0, $readHostPrompt.Length - 1)
    }
    if ([string]::IsNullOrWhiteSpace($readHostPrompt)) { $readHostPrompt = 'Enter choice' }

    try {
        if ([Console]::IsInputRedirected) {
            # Redirected/piped stdin: never enter the keyboard-polling loop
            # below -- [Console]::KeyAvailable cannot see piped input, and
            # polling it here is exactly the 40-second hang from issue #135.
            # Read-HostSafe exits cleanly with a nonzero code the moment
            # stdin is exhausted, instead of looping forever re-reading an
            # already-closed stream.
            return [pscustomobject]@{ Redraw = $false; Value = (Read-HostSafe $readHostPrompt) }
        }
    } catch {
        # [Console]::IsInputRedirected itself threw (unusual host) -- log it
        # rather than silently swallowing (issue #135) and fall through to
        # the keyboard-polling loop, which has its own KeyAvailable-throws
        # fallback to Read-HostSafe below if a real keyboard also isn't
        # available.
        Write-Log "Read-MainMenuChoiceResponsive: [Console]::IsInputRedirected threw -- $_"
    }

    $value = ''

    Write-Host $Prompt -NoNewline
    while ($true) {
        $currentWidth = Get-ConsoleContentWidth
        $currentHeight = Get-ConsoleContentHeight
        if ($currentWidth -ne $InitialWidth -or $currentHeight -ne $InitialHeight) {
            return [pscustomobject]@{ Redraw = $true; Value = '' }
        }
        try {
            if ([Console]::KeyAvailable) {
                $key = [Console]::ReadKey($true)
                if ($key.Key -eq 'Enter') {
                    Write-Host ''
                    return [pscustomobject]@{ Redraw = $false; Value = $value }
                }
                if ($key.Key -eq 'Backspace') {
                    if ($value.Length -gt 0) {
                        $value = $value.Substring(0, $value.Length - 1)
                        Write-Host "`b `b" -NoNewline
                    }
                    continue
                }
                if ($key.KeyChar -and -not [char]::IsControl($key.KeyChar)) {
                    $value += [string]$key.KeyChar
                    Write-Host $key.KeyChar -NoNewline
                }
            } else {
                Start-Sleep -Milliseconds 80
            }
        } catch {
            # [Console]::KeyAvailable/ReadKey threw -- no real keyboard
            # available either. Log it (issue #135: never silently swallow
            # an input-detection failure) and fall back to Read-HostSafe,
            # which exits cleanly if stdin turns out to be exhausted too.
            Write-Log "Read-MainMenuChoiceResponsive: keyboard polling threw -- $_"
            Write-Host ''
            return [pscustomobject]@{ Redraw = $false; Value = (Read-HostSafe $readHostPrompt) }
        }
    }
}

# =============================================================================
# MAIN MENU LOOP
# =============================================================================
# $MinBoundForArchetype must be set before the loop starts, not only in
# SECTION 10 below -- the standalone "Propagate Controls" menu handler
# (PropagateControls mode) runs entirely inside this loop and returns via
# `continue` without ever reaching SECTION 10. Before this fix, running
# Propagate Controls as the first action of a session left the variable
# $null, which [int]$minBound coerced to 0 in Build-ArchetypePool -- every
# profile (including fully unbound ones) then qualified as an archetype,
# every UserProfiles file was treated as a pool source, and propagation
# silently produced "Games updated: 0" with no per-game report lines. See
# issue #139 and LESSONS_LEARNED.md.
$MinBoundForArchetype = 5
try {
Set-ConsoleMaximizedIfSupported
function Invoke-TpmFfbSetupMode {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$TpRoot, [string]$ScriptRoot = $PSScriptRoot, [scriptblock]$EventSink = $null)
    if ([string]::IsNullOrWhiteSpace($ScriptRoot)) { $ScriptRoot = if ($PSScriptRoot) { $PSScriptRoot } else { (Get-Location).Path } }
    Write-TpmFfbIntro
    $status = New-TpmWorkflowStatusContext -WorkflowKey 'FFBSetup' -Title 'Force feedback setup' -EventSink $EventSink -Steps @(
        @{ Id = 'inspect'; Label = 'Check available force-feedback options' }
        @{ Id = 'native'; Label = 'Apply the approved native option' }
        @{ Id = 'plugin'; Label = 'Download and apply the optional plugin' }
        @{ Id = 'verify'; Label = 'Verify force-feedback results' }
    )
    [void](Start-TpmWorkflowStatus -Context $status)
    [void](Start-TpmWorkflowStep -Context $status -StepId 'inspect' -Activity 'Checking force-feedback options')
    [void](Complete-TpmWorkflowStep -Context $status -Summary 'Force-feedback options checked' -NextStep 'Apply the approved native option')
    [void](Start-TpmWorkflowStep -Context $status -StepId 'native' -Activity 'Applying the native option')
    [void](Clear-TpmWorkflowFooter -Context $status)
    $nativeResult = Invoke-TpmProgressGroup -Title 'Force feedback native setup' -Action { Invoke-FFBBlasterSetup -UserProfilesDir $UserProfilesDir -TpRoot $TpRoot }
    $nativeHasContract = ($null -ne $nativeResult -and $null -ne $nativeResult.PSObject.Properties['EnabledCodes'])
    $nativeCodes = if ($nativeHasContract) { @($nativeResult.EnabledCodes) } elseif ($null -eq $nativeResult) { @() } else { @($nativeResult) }
    if ($nativeHasContract -and -not [bool]$nativeResult.Succeeded) {
        $nativeBackupInfo = Get-TpmTransactionField -Object $nativeResult -Name 'Backup'
        $nativeFailureMessage = if ([bool](Get-TpmTransactionField -Object $nativeBackupInfo -Name 'Attempted' -Default $false) -and -not [bool](Get-TpmTransactionField -Object $nativeBackupInfo -Name 'Verified' -Default $false)) {
            'The native force-feedback setup was blocked because its profile backup failed.'
        } elseif ([string]$nativeResult.Reason -ceq 'FFB_PROFILE_REVIEW_REQUIRED') {
            'The native force-feedback setup stopped because some game profiles could not be read. Nothing was changed.'
        } else {
            'The native force-feedback setup did not complete successfully.'
        }
        [void](Set-TpmWorkflowFailure -Context $status -FailureId 'ffb-native-failed' -Message $nativeFailureMessage -DataSafety 'TeknoParrot Manager did not claim a complete native force-feedback setup or proceed to the optional plugin.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
        [void](Read-HostSafe 'Press Enter to acknowledge the force-feedback result')
        [void](Acknowledge-TpmWorkflowFailure -Context $status -FailureId 'ffb-native-failed')
        [void](Stop-TpmWorkflowStatus -Context $status -Reason 'Force-feedback setup stopped')
        [void](Close-TpmWorkflowStatus -Context $status)
        return [pscustomobject]@{
            Completed = $false
            Context = $status
            NativeSucceeded = $false
            MissingPath = 0
            MissingDevice = 0
            MissingPathGames = @()
            MissingDeviceGames = @()
            PathReasonCounts = @{}
        }
    }
    $nativeNoOp = ($nativeHasContract -and [string]$nativeResult.Outcome -eq 'NO_OP')
    if ($nativeNoOp) {
        [void](Complete-TpmWorkflowStep -Context $status -Outcome Skipped -Summary ([string]$nativeResult.Summary) -NextStep 'Choose whether to add the optional plugin')
    } else {
        [void](Complete-TpmWorkflowStep -Context $status -Summary 'Native force feedback step finished' -NextStep 'Choose whether to add the optional plugin')
    }
    if ($nativeHasContract -and [string]$nativeResult.Outcome -eq 'SUCCEEDED') { Show-TpmFfbNativeResult -Result $nativeResult -Unattended:$Unattended }
    [void](Set-TpmWorkflowWaiting -Context $status -Message 'TeknoParrot Manager can add the optional third-party force-feedback plugin.' -UserAction 'Answer Y or N')
    Write-Host '  [Y] Set up the free third-party FFB plugin' -ForegroundColor White
    Write-Host '  [N] Skip the optional plugin' -ForegroundColor White
    $choice = Read-TpmYesNo -Prompt '  Choose Y or N' -Default 'N'
    [void](Resume-TpmWorkflowStatus -Context $status)
    $plugin = $null
    if ($choice -eq 'Y') {
        [void](Start-TpmWorkflowStep -Context $status -StepId 'plugin' -Activity 'Downloading and applying the optional plugin')
        $ffbCacheRoot = if ($script:TpmOwnedLayout) { Join-Path $script:TpmOwnedLayout.Cache 'FFBPlugin' } else { Join-Path $ScriptRoot 'FFBPlugin' }
        $evidencePath = if ($script:TpmOwnedLayout) { Join-Path $script:TpmOwnedLayout.Reports 'TPM-FFB-Plugin-Evidence.json' } else { '' }
        [void](Clear-TpmWorkflowFooter -Context $status)
        $plugin = Invoke-TpmProgressGroup -Title 'Force feedback plugin setup' -Action { Invoke-FFBPluginSetup -UserProfilesDir $UserProfilesDir -CacheDir $ffbCacheRoot -NativeEnabledCodes $nativeCodes -TpRoot $TpRoot -EvidencePath $evidencePath -ProtectedRoots @($zipSource, $zipSourceSupplementary) }
        if (-not ($plugin -and $plugin.Succeeded)) {
            [void](Set-TpmWorkflowFailure -Context $status -FailureId 'ffb-plugin-failed' -Message 'The optional force-feedback plugin could not complete safely.' -DataSafety 'TeknoParrot Manager reported an error or incomplete accounting while handling the optional plugin.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
            [void](Read-HostSafe 'Press Enter to acknowledge the force-feedback result')
            [void](Acknowledge-TpmWorkflowFailure -Context $status -FailureId 'ffb-plugin-failed')
            [void](Stop-TpmWorkflowStatus -Context $status -Reason 'Force-feedback setup stopped')
            [void](Close-TpmWorkflowStatus -Context $status)
            return [pscustomobject]@{
                Completed = $false
                Context = $status
                NativeSucceeded = $true
                MissingPath = if ($plugin) { [int]$plugin.MissingPath } else { 0 }
                MissingDevice = if ($plugin) { [int]$plugin.MissingDevice } else { 0 }
                MissingPathGames = if ($plugin) { @($plugin.MissingPathGames) } else { @() }
                MissingDeviceGames = if ($plugin) { @($plugin.MissingDeviceGames) } else { @() }
                PathReasonCounts = if ($plugin) { $plugin.PathReasonCounts } else { @{} }
            }
        }
        if ($plugin.NoOp) {
            [void](Complete-TpmWorkflowStep -Context $status -Outcome Skipped -Summary 'Optional plugin setup needed no file changes' -NextStep 'Verify force-feedback results')
        } else {
            [void](Complete-TpmWorkflowStep -Context $status -Outcome Fixed -Summary 'Optional plugin result recorded' -NextStep 'Verify force-feedback results')
        }
    } else {
        [void](Start-TpmWorkflowStep -Context $status -StepId 'plugin' -Activity 'Optional plugin skipped by user choice')
        [void](Complete-TpmWorkflowStep -Context $status -Outcome Skipped -Summary 'Optional plugin skipped')
        Write-Log 'FFBPlugin setup: skipped by user choice.'
    }
    [void](Start-TpmWorkflowStep -Context $status -StepId 'verify' -Activity 'Verifying force-feedback results')
    [void](Complete-TpmWorkflowStep -Context $status -Summary 'Force-feedback results recorded')
    [void](Complete-TpmWorkflowStatus -Context $status -Summary 'Force-feedback setup finished')
    [void](Close-TpmWorkflowStatus -Context $status)
    return [pscustomobject]@{
        Completed = $true
        Context = $status
        NativeSucceeded = $true
        MissingPath = if ($plugin) { [int]$plugin.MissingPath } else { 0 }
        MissingDevice = if ($plugin) { [int]$plugin.MissingDevice } else { 0 }
        MissingPathGames = if ($plugin) { @($plugin.MissingPathGames) } else { @() }
        MissingDeviceGames = if ($plugin) { @($plugin.MissingDeviceGames) } else { @() }
        PathReasonCounts = if ($plugin) { $plugin.PathReasonCounts } else { @{} }
    }
}

$requiredPatchEnginePath = Join-Path $PSScriptRoot 'scripts\TpmRequiredPatchEngine.ps1'
if (-not (Test-Path -LiteralPath $requiredPatchEnginePath -PathType Leaf) -or
    -not (Test-TpmNoReparsePath -Path $requiredPatchEnginePath)) {
    throw 'The required-patch engine file is missing or unsafe.'
}
. $requiredPatchEnginePath

while ($true) {
    # Refresh the drive-info snapshot at the start of each menu iteration so
    # any drive changes since the last pass (USB ejected, network share
    # reconnected to a different letter) are picked up rather than using
    # stale cached data from the previous mode's run.
    Clear-LocalDriveInfoCache
    Write-TpmUnhandledErrorsToLog -Where 'back at the main menu'
    Reset-TpmRegistrationLedgerStopLatch
$mode = $null

    # A pending mode either came from a preview/recovery re-entry or from a
    # read-only Health Check action. Only the latter carries an AutoSync target list.
    $autoSyncTargetGames = $null
    $autoSyncSelection = $null
    # AutoSync results belong to one pass only; a later Register only pass must not reuse them.
    $sync = $null
    $syncSupp = $null
    $reShadeAction = 'Select'
    $reShadeActionPending = $false
    if ($pendingApplyMode) {
        $mode = $pendingApplyMode
        $autoSyncTargetGames = if ($pendingApplyMode -eq 'AutoSync' -and $pendingAutoSyncGames) { @($pendingAutoSyncGames) } else { $null }
        $autoSyncSelection = if ($pendingApplyMode -eq 'AutoSync') { $pendingAutoSyncSelection } else { $null }
        $pendingAutoSyncSelection = $null
        $reShadeAction = $pendingReShadeAction
        $reShadeActionPending = ($pendingApplyMode -eq 'ReShadeSetup')
        $pendingReShadeAction = 'Select'
        $pendingAutoSyncGames = $null
        $pendingApplyMode = $null
        $forceRealApply = [bool]$pendingApplyForce
        $pendingApplyForce = $false
    }
    # A pending mode skips the menu and falls through to the mode body below.
    if (-not $mode) {
    # The elevated protected-resume child must never reach the interactive menu: reaching it means the protected PostgreSQL setup was not entered, and exiting 0 from here would be mistaken for completion.
    if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not start the PostgreSQL setup in this window, so nothing was resumed.' }
    # Show-MainMenu (issue #104): renders from Get-MainMenuSections at
    # whichever layout tier fits the current console window. Detected fresh
    # every redraw so a mid-session resize picks the right tier next time,
    # not just at startup.
    $menuMaxNumber = (Get-MainMenuItems | Measure-Object -Property Number -Maximum).Maximum
    $consoleWidth  = Get-ConsoleContentWidth
    $consoleHeight = Get-ConsoleContentHeight
    $menuTier = Get-ConsoleLayoutTier -Width $consoleWidth -Height $consoleHeight
    if ($Unattended) {
        Write-Host "  [Unattended] Mode must be set before starting." -ForegroundColor Red
        Write-Log "ERROR: Unattended mode -- reached menu loop."; exit 1
    }
    $screen = Show-MainMenu -Tier $menuTier -Width $consoleWidth -Height $consoleHeight -Notice $menuNotice -ReturnScreen
    if (-not $screen.PromptAllowed) {
        # FIX52 (#384): redraw by itself as soon as the window size changes, like the menu prompt; Enter still redraws.
        $tinyChoice = Read-MainMenuChoiceResponsive -Prompt '  Resize the window and press Enter, or type Q to quit: ' -InitialWidth $consoleWidth -InitialHeight $consoleHeight
        if (-not $tinyChoice.Redraw -and (Resolve-MainMenuCommand -InputText $tinyChoice.Value -MaxNumber $menuMaxNumber) -eq 'Q') { break }
        continue
    }
    $menuNotice = ''
    $choiceResult = Read-MainMenuChoiceResponsive -Prompt ("Enter 1-{0}: " -f $menuMaxNumber) -InitialWidth $consoleWidth -InitialHeight $consoleHeight
    if ($choiceResult.Redraw) { continue }
    $modeChoice = Resolve-MainMenuCommand -InputText $choiceResult.Value -MaxNumber $menuMaxNumber
    if ($null -eq $modeChoice) {
        $menuNotice = "Invalid choice. Enter 1-$menuMaxNumber. Commands: H = Help, L = View Log, Q = Quit."
        continue
    }
    if ($modeChoice -eq 'H') {
        Show-MainMenuHelp
        continue
    }
    if ($modeChoice -eq 'L') {
        $logResult = Open-TpmLogsAndReports -LogsPath $script:TpmOwnedLayout.Logs -ReportsPath $script:TpmOwnedLayout.Reports
        if ($logResult.Succeeded) {
            Write-Host ("  Opened: {0}" -f $logResult.Path) -ForegroundColor Green
        } else {
            Write-Host ("  Could not open the logs and reports folders: {0}" -f $logResult.Error) -ForegroundColor Yellow
        }
        [void](Read-HostSafe '  Press Enter to return to the main menu')
        continue
    }
    if ($modeChoice -eq 'Q') { break }
    switch ($modeChoice) {
        "1"     { $mode = "AutoSync"       }
        "2"     { $mode = "RegisterOnly"   }
        "3"     { $mode = "PropagateControls" }
        "4"     { $mode = "CrosshairSetup" }
        "5"     { $mode = "ReShadeSetup"   }
        "6"     { $mode = "DgVoodoo2Setup" }
        "7"     { $mode = "GpuFixSetup"    }
        "8"     { $mode = "FFBSetup"       }
        "9"     { $mode = "BepInExUpdate"  }
        "10"    { $mode = "RegionSetup" }
        "12"    { $mode = "RequiredPatch" }
        "13"    { $mode = "HealthCheck"    }
        "14"    { $mode = "Restore"        }
        "11"    { $mode = "PostgresSetup"  }
        "15"    { $mode = "CheckForUpdates" }
        "16"    { $mode = "Support" }
    }
    if ($modeChoice -eq "17") { break }
    }
    Clear-ConsoleForFreshRender
    if ($mode -eq 'RequiredPatch') {
        Invoke-TpmRequiredPatchMenu -TpRoot $tpRoot -UserProfilesDir $userProfilesDir -ManagerRoot $PSScriptRoot -ProgramRoot $PSScriptRoot -MainSource $zipSource -SupplementarySource $zipSourceSupplementary
        continue
    }

    if ($mode -eq 'RegionSetup') {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Region Setup" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Invoke-TpmRegionSetup -UserProfilesDir $userProfilesDir
        [void](Read-HostSafe '  Press Enter to return to menu')
        continue
    }

    if ($mode -eq "Restore") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Restore from Backup" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host "  1) TeknoParrot UserProfiles backup"
        Write-Host "  2) Postgres database backup (only relevant if you've used the"
        Write-Host "     Postgres setup mode)"
        Write-Host "  3) LaunchBox library backup (verified current-state backup first)"
        Write-Host "  4) Reset and Restore: put back one game or all games from a"
        Write-Host "     restore point saved when TeknoParrot Manager started"
        Write-Host "  5) Rebuild one game from its ZIP: put one game folder back to"
        Write-Host "     exactly what its ZIP holds (your old folder is kept)"
        $restoreStatus = New-TpmWorkflowStatusContext -WorkflowKey 'Restore' -Title 'Restore from backup' -Steps @(
            @{ Id = 'select'; Label = 'Select the backup to restore' }
        )
        [void](Start-TpmWorkflowStatus -Context $restoreStatus)
        [void](Start-TpmWorkflowStep -Context $restoreStatus -StepId 'select' -Activity 'Choosing a backup')
        [void](Set-TpmWorkflowWaiting -Context $restoreStatus -Message 'Choose which backup to restore.' -UserAction 'Enter a backup choice')
        $restoreChoice = Read-TpmChoice -Prompt "  Enter 1-5" -Choices @('1', '2', '3', '4', '5')
        $restoreResult = $null
        [void](Clear-TpmWorkflowFooter -Context $restoreStatus)
        if ($restoreChoice -eq '5') {
            # #348: rebuild one game from its ZIP shows its own preview, confirmation and result.
            [void](Stop-TpmWorkflowStatus -Context $restoreStatus -Reason 'Rebuild opened')
            [void](Close-TpmWorkflowStatus -Context $restoreStatus)
            Invoke-TpmRebuildMenu -UserProfilesDir $userProfilesDir -InstallFolder ([string]$gamesInstallFolder) -ZipSources @([string]$zipSource, [string]$zipSourceSupplementary) -DatIndex $datIndex -EggmanDatZip ([string]$eggmanDatZip) -DatFilePath ([string]$datFilePath) -SupplementaryDatPath ([string]$supplementaryDatPath)
            [void](Read-HostSafe '  Press Enter to return to menu')
            continue
        }
        if ($restoreChoice -eq '4') {
            # FIX58 (#348): Reset and Restore shows its own preview, confirmation and result.
            [void](Stop-TpmWorkflowStatus -Context $restoreStatus -Reason 'Reset and Restore opened')
            [void](Close-TpmWorkflowStatus -Context $restoreStatus)
            $resetRestore = Invoke-TpmResetRestoreMenu -UserProfilesDir $userProfilesDir -ConfigPath ([string]$configPath)
            if ($resetRestore -and [bool]$resetRestore.RestartRequired) {
                Write-Host ''
                Write-TpmResetRestoreText -Text 'TeknoParrot Manager''s own settings were put back. TeknoParrot Manager now closes so it cannot overwrite them with the settings it still has in memory. Start TeknoParrot Manager again to use the restored settings.' -Color Yellow
                Write-Log 'Reset and Restore: the settings file was put back; closing so the restored settings are loaded on the next start.'
                [void](Read-HostSafe '  Press Enter to close TeknoParrot Manager')
                Exit-TpmProcess -Code 0
            }
            [void](Read-HostSafe '  Press Enter to return to menu')
            continue
        }
        if ($restoreChoice -eq "2") {
            $restoreResult = Invoke-TpmProgressGroup -Title 'Restore PostgreSQL backup' -Action { Invoke-RestorePostgresBackup }
        } elseif ($restoreChoice -eq '3') {
            $restoreRoot = $lbRoot
            if (-not $restoreRoot) { $restoreRoot = Read-HostSafe '  LaunchBox install folder' }
            $restoreResult = Invoke-RestoreLaunchBoxBackup -lbRoot $restoreRoot
            Write-TpmLaunchBoxResult -Result $restoreResult
        } else {
            $restoreResult = Invoke-TpmProgressGroup -Title 'Restore backup' -Action { Invoke-RestoreBackup -userProfilesDir $userProfilesDir }
        }
        [void](Resume-TpmWorkflowStatus -Context $restoreStatus)
        $restoreTransaction = $null
        if ($restoreResult -and @($restoreResult.PSTypeNames) -contains 'TPM.TransactionResult.v1') { $restoreTransaction = $restoreResult }
        $restoreCancelled = $restoreResult -and $restoreResult.PSObject.Properties['Cancelled'] -and [bool]$restoreResult.Cancelled
        $restoreNoOp = ($restoreResult -and $restoreResult.PSObject.Properties['NoOp'] -and [bool]$restoreResult.NoOp) -or ($restoreTransaction -and $restoreTransaction.Outcome -eq 'NO_OP')
        $restoreNoOpSummary = if ($restoreChoice -eq '3') { [string]$restoreResult.Summary } elseif ($restoreTransaction -and $restoreTransaction.Outcome -eq 'NO_OP') { [string]$restoreTransaction.Summary } elseif ($restoreResult -and $restoreResult.Reason -eq 'NO_POSTGRES_BACKUPS') { 'No PostgreSQL backup was available; no files were changed' } else { 'No backup was available; no files were changed' }
        $restoreSucceeded = if ($restoreCancelled) { $false } elseif ($restoreNoOp) { $true } elseif ($restoreTransaction) { $restoreTransaction.Outcome -eq 'SUCCEEDED' } else { [bool]($restoreResult -and $restoreResult.Succeeded) }
        $restoreResultDetail = if ($restoreChoice -eq '3') { [string]$restoreResult.Summary } elseif ($restoreTransaction) { 'restore transaction reported ' + [string]$restoreTransaction.Outcome } elseif ($restoreNoOp) { 'no backup was available; no files were changed' } else { 'the selected restore operation reported success' }
        $restoreDoneSummary = if ($restoreChoice -eq '3') { 'Restore completed; outcome: ' + $restoreResultDetail } else { 'Restore complete.' }
        if ($restoreCancelled) {
            [void](Stop-TpmWorkflowStatus -Context $restoreStatus -Reason 'Restore canceled; no success claimed')
            [void](Close-TpmWorkflowStatus -Context $restoreStatus)
        } elseif ($restoreNoOp) {
            [void](Complete-TpmWorkflowStep -Context $restoreStatus -Outcome Skipped -Summary $restoreNoOpSummary)
            [void](Complete-TpmWorkflowStatus -Context $restoreStatus -Summary $restoreNoOpSummary)
            [void](Close-TpmWorkflowStatus -Context $restoreStatus)
        } elseif ($restoreSucceeded) {
            [void](Complete-TpmWorkflowStep -Context $restoreStatus -Outcome Fixed -Summary $restoreDoneSummary)
            [void](Complete-TpmWorkflowStatus -Context $restoreStatus -Summary $restoreDoneSummary)
            [void](Close-TpmWorkflowStatus -Context $restoreStatus)
        } else {
            $failureMessage = if ($restoreChoice -eq '3') { [string]$restoreResult.Summary } elseif ($restoreTransaction) { [string]$restoreTransaction.Summary } else { 'The restore was not completed.' }
            $dataSafety = if ($restoreTransaction) { Get-TpmPostgresDataSafetyText -Result $restoreTransaction } else { 'The restore is not finished. Open View Log before you try again.' }
            $failureActions = if ($restoreTransaction -and @($restoreTransaction.RecoveryActions).Count -gt 0) {
                @($restoreTransaction.RecoveryActions)
            } else {
                @(@{ Id = 'Acknowledge'; Label = 'Return to menu' })
            }
            [void](Set-TpmWorkflowFailure -Context $restoreStatus -FailureId 'restore-failed' -Message $failureMessage -DataSafety $dataSafety -RecoveryActions $failureActions)
        }
        Write-Host ""
        Write-Host "============================================" -ForegroundColor Cyan
        if ($restoreCancelled) {
            Write-Host '   Restore canceled; no files were changed by this operation.' -ForegroundColor DarkGray
            Write-Log 'Restore canceled; no files were changed by this operation.'
        } elseif ($restoreNoOp) {
            # The LaunchBox result printer already showed the summary; do not print it twice or append a second period.
            $restoreNoOpLine = if ($restoreChoice -eq '3') { 'LaunchBox restore outcome: ' + [string]$restoreResult.Outcome } else { ([string]$restoreNoOpSummary).TrimEnd('.') + '.' }
            Write-Host ('   ' + $restoreNoOpLine) -ForegroundColor DarkGray
            Write-Log $restoreNoOpSummary
        } elseif ($restoreSucceeded) {
            $restoreDoneLine = if ($restoreChoice -eq '3') { 'LaunchBox restore outcome: ' + [string]$restoreResult.Outcome } else { $restoreDoneSummary }
            Write-Host ('   ' + $restoreDoneLine) -ForegroundColor Green
            Write-Log ('Restore completed; outcome: ' + $restoreResultDetail + '.')
        } elseif ($restoreTransaction) {
            Write-Host ("   {0}" -f $restoreTransaction.Summary) -ForegroundColor Yellow
            Write-Log ("Restore did not complete; outcome={0}; no success was claimed." -f $restoreTransaction.Outcome)
        } else {
            Write-Host "   The restore was not completed. Read the message above." -ForegroundColor Yellow
            Write-Log "Restore did not complete; no success was claimed."
        }
        Write-Host "============================================" -ForegroundColor Cyan
        if (-not $restoreSucceeded -and -not $restoreCancelled) {
            [void](Read-HostSafe '  Press Enter to acknowledge the restore result')
            [void](Acknowledge-TpmWorkflowFailure -Context $restoreStatus -FailureId 'restore-failed')
            [void](Stop-TpmWorkflowStatus -Context $restoreStatus -Reason 'Restore stopped')
            [void](Close-TpmWorkflowStatus -Context $restoreStatus)
        }
        [void](Read-HostSafe "  Press Enter to return to menu")
        continue
    }

    if ($mode -eq "HealthCheck") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Library Health Check (read-only)" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        $healthStatus = New-TpmWorkflowStatusContext -WorkflowKey 'HealthCheck' -Title 'Library health check' -Steps @(
            @{ Id = 'inspect'; Label = 'Check library and emulator state' }
            @{ Id = 'report'; Label = 'Show action items and controls readiness' }
        )
        [void](Start-TpmWorkflowStatus -Context $healthStatus)
        [void](Start-TpmWorkflowStep -Context $healthStatus -StepId 'inspect' -Activity 'Checking library and emulator state')
        [void](Clear-TpmWorkflowFooter -Context $healthStatus)
        $healthResult = Invoke-TpmProgressGroup -Title 'Library health check' -Action { Invoke-LibraryHealthCheck -UserProfilesDir $userProfilesDir -LogPath $logPath -TpRoot $tpRoot }
        $healthCompletionSummary = if ([string]$healthResult.Outcome -eq 'ACTION_REQUIRED') { 'Library report prepared with incomplete coverage' } else { 'Health check finished' }
        [void](Complete-TpmWorkflowStep -Context $healthStatus -Summary $healthCompletionSummary -NextStep 'Review the action items')
        [void](Start-TpmWorkflowStep -Context $healthStatus -StepId 'report' -Activity 'Preparing the read-only summary')
        [void](Complete-TpmWorkflowStep -Context $healthStatus -Summary 'Read-only action items prepared')
        [void](Complete-TpmWorkflowStatus -Context $healthStatus -Summary $healthCompletionSummary)
        [void](Close-TpmWorkflowStatus -Context $healthStatus)
        Write-Host ""
        Write-Host "============================================" -ForegroundColor Cyan
        $healthExitCode = Get-TpmHealthCheckExitCode -Result $healthResult
        $healthFooter = if ($healthExitCode -eq 0) { '   Read-only report complete.' } else { '   Report finished. Some checks could not finish.' }
        Write-Host $healthFooter -ForegroundColor $(if ($healthExitCode -eq 0) { 'Cyan' } else { 'Yellow' })
        Write-Host "============================================" -ForegroundColor Cyan
        Write-Log $(if ($healthExitCode -eq 0) { 'Health check complete.' } else { 'Health check finished, but some checks could not finish (incomplete coverage).' })
        if ($Unattended) {
            # Unattended HealthCheck is deliberately bounded at the report.
            # It must never prompt or start a repair/setup workflow.
            Write-Log ("Unattended: health check {0} -- exiting with code {1}." -f $(if ($healthExitCode -eq 0) { 'complete' } else { 'incomplete' }), $healthExitCode)
            exit $healthExitCode
        }
        $searchRoot = $gamesInstallFolder
        $healthChoice = Show-LibraryHealthNextActions -Result $healthResult
        # Games whose saved path cannot be found, plus games on a drive that is not connected: the repair choices work on both.
        $healthRepairGames = @(@($healthResult.Broken) + @(Get-TpmTransactionField -Object $healthResult -Name 'DriveUnavailable' -Default @()) | Select-Object -Unique)
        if ($healthChoice -eq 'F') {
            # Interactive only (an unattended health check exits above). Shows what was found and asks before any copy.
            [void](Invoke-TpmPrerequisiteReview -Warnings @($healthResult.PrerequisiteMissing) -TpRoot $tpRoot `
                -SearchFolders @($zipSourceSupplementary, $zipSource) -EggmanDatZip ([string]$eggmanDatZip) -DatFilePath ([string]$datFilePath) -SupplementaryDatPath ([string]$supplementaryDatPath) `
                -Interactive -OtherRootsProvider { @(Get-TpmDetectedRootList) })
            [void](Read-HostSafe '  Press Enter to return to the main menu')
            continue
        }
        if ($healthChoice -in @('R', 'S') -and $healthRepairGames.Count -gt 0) {
            if ($healthChoice -eq 'S') {
                $searchRoot = Read-PathWithBrowse -Prompt '  Choose another game folder to search' -Mode Folder -InitialDirectory $gamesInstallFolder
            }
            $searchRootCheck = Test-TpmRepairSearchRoot `
                -Candidate $searchRoot -TeknoParrotRoot $tpRoot -ProgramDirectory $PSScriptRoot `
                -ZipSource $zipSource -ZipSourceSupplementary $zipSourceSupplementary
            if (-not $searchRootCheck.Valid) {
                Write-Host ("  Search folder rejected: {0}. Nothing was changed." -f $searchRootCheck.Reason) -ForegroundColor Yellow
                [void](Read-HostSafe '  Press Enter to return to the main menu')
                continue
            }
            $searchRoot = $searchRootCheck.CanonicalPath
            $repairSearchAgain = $false
            $repairReCopyRequested = $false
            do {
                Write-Host ("  TeknoParrot Manager will search {0} for matching executables." -f $searchRoot) -ForegroundColor Cyan
                try {
                    Write-Host ("  Scoped repair: searching only {0} affected profile(s)." -f $healthRepairGames.Count) -ForegroundColor Cyan
                    if (@(Get-TpmTransactionField -Object $healthResult -Name 'DriveUnavailable' -Default @()).Count -gt 0) {
                        Write-Host '  Games on a drive that is not connected are included. A game is pointed at the new folder only if its game file is found there. The others stay as they are.' -ForegroundColor Yellow
                    }
                    $repairIndex = Build-ProfileIndex -gameProfilesDir $gameProfilesDir
                    $repairSearchGroup = Invoke-TpmProgressGroup -Title 'Health repair search' -Action {
                        $repairPlan = Repair-GamePaths -userProfilesDir $userProfilesDir -installFolder $searchRoot -profileIndex $repairIndex -DryRun:$true -OnlyGames ([string[]]$healthRepairGames)
                        [pscustomobject]@{ Outcome = $repairPlan.Outcome; Succeeded = ($repairPlan.Outcome -in @('SUCCEEDED','NO_OP')); Reports = @($repairPlan.Reports) }
                    }
                    $repairReports = @($repairSearchGroup.Reports)
                    $repairCandidates = @($repairReports | Where-Object { $_.Status -eq 'candidate' })
                    if ($repairCandidates.Count -gt 0) {
                        Write-Host '  Candidate paths found (no profile changes made):' -ForegroundColor Cyan
                        foreach ($candidate in $repairCandidates) {
                            Write-Host ("    {0}  before: {1}" -f $candidate.Code, (ConvertTo-TpmDisplayPath $candidate.PreviousPath)) -ForegroundColor DarkGray
                            Write-Host ("          after : {0}" -f (ConvertTo-TpmDisplayPath $candidate.NewPath)) -ForegroundColor White
                        }
                        $driveCodes = @(Get-TpmTransactionField -Object $healthResult -Name 'DriveUnavailable' -Default @())
                        if (@($repairCandidates | Where-Object { $driveCodes -contains [string]$_.Code }).Count -gt 0) {
                            Write-Host '  A game that was on a drive that is not connected will be pointed at the new path shown above. A safety backup of its profile is made first.' -ForegroundColor Yellow
                        }
                        Write-Host '  [Y] Apply only these reviewed candidates' -ForegroundColor White
                        Write-Host '  [N] Leave them unchanged' -ForegroundColor White
                        $applyChoice = Read-TpmYesNo -Prompt '  Choose Y or N' -Default 'N'
                        if ($applyChoice -eq 'Y') {
                            $repairTransaction = Invoke-TpmProgressGroup -Title 'Health repair apply' -Action { Repair-GamePaths -userProfilesDir $userProfilesDir -installFolder $searchRoot -profileIndex $repairIndex -DryRun:$false -ReviewedCandidates $repairCandidates -OnlyGames ([string[]]$healthRepairGames) }
                            $repairReports = @($repairTransaction.Reports)
                            $repairSummary = Write-LibraryHealthRepairResults -Reports $repairReports
                            if ($repairTransaction.Outcome -eq 'SUCCEEDED') {
                                Write-Host ("  Repair result: {0} FIXED, {1} STILL BROKEN." -f $repairSummary.Fixed, $repairSummary.StillBroken) -ForegroundColor $(if ($repairSummary.StillBroken -gt 0) { 'Yellow' } else { 'Green' })
                            } else {
                                Write-Host ("  {0} Fixed: {1}; not fixed or unverified: {2}." -f $repairTransaction.Summary, $repairSummary.Fixed, $repairSummary.StillBroken) -ForegroundColor Yellow
                            }
                            if ($repairTransaction.Backup.RootPath) { Write-Host ("  Safety backup: {0}" -f $repairTransaction.Backup.RootPath) -ForegroundColor DarkGray }
                        } else {
                            Write-Host '  Candidates were reviewed but not applied. Nothing was changed.' -ForegroundColor DarkGray
                        }
                        $repairSearchAgain = $false
                    } else {
                        Write-Host '  No safe automatic candidates were found in this folder. Nothing was changed.' -ForegroundColor Yellow
                        Write-Host ("  Searched folder: {0}" -f (ConvertTo-TpmDisplayPath $searchRoot)) -ForegroundColor DarkGray
                        Write-Host '  Affected profile evidence:' -ForegroundColor Cyan
                        Write-LibraryHealthRepairResults -Reports $repairReports | Out-Null
                        foreach ($brokenCode in $healthRepairGames) {
                            $brokenProfilePath = Join-Path $userProfilesDir ($brokenCode + '.xml')
                            $savedExecutable = ''
                            try {
                                $brokenDoc = Read-Xml -Path $brokenProfilePath
                                $savedExeNode = $brokenDoc.GameProfile.SelectSingleNode('ExecutableName')
                                if ($savedExeNode) { $savedExecutable = [string]$savedExeNode.InnerText }
                            } catch {
                                $savedExecutable = '<could not read profile>'
                            }
                            Write-Host ("    {0}: expected executable {1}" -f $brokenCode, $(if ($savedExecutable) { $savedExecutable } else { '<not recorded>' })) -ForegroundColor DarkGray
                        }
                        $reCopySources = @($zipSource, $zipSourceSupplementary | Where-Object { $_ -and (Test-Path -LiteralPath $_ -PathType Container) })
                        if ($reCopySources.Count -gt 0) {
                            Write-Host '  [C] Re-copy/re-extract only these affected games from the configured source' -ForegroundColor White
                            Write-Host ("      Configured source: {0}" -f ($reCopySources -join '; ')) -ForegroundColor DarkCyan
                        } else {
                            Write-Host '  No configured ZIP source is available for scoped re-copy/re-extract.' -ForegroundColor DarkGray
                        }
                        Write-Host '  [S] Search another game folder' -ForegroundColor White
                        Write-Host '  [B] Back to the main menu' -ForegroundColor White
                        $repairReCopyRequested = $false
                        $repairChoices = if ($reCopySources.Count -gt 0) { @('S', 'B', 'C') } else { @('S', 'B') }
                        $searchAgainChoice = Read-TpmChoice -Prompt ('  Choose {0}' -f ($repairChoices -join ' or ')) -Choices $repairChoices -Default 'B'
                        if ($searchAgainChoice -eq 'C') {
                            $pendingApplyMode = 'AutoSync'
                            $pendingAutoSyncGames = @($healthRepairGames)
                            $pendingApplyForce = $false
                            $repairReCopyRequested = $true
                            $repairSearchAgain = $false
                        } elseif ($searchAgainChoice -eq 'S') {
                            $selectedSearchRoot = Read-PathWithBrowse -Prompt '  Choose another game folder to search' -Mode Folder -InitialDirectory $searchRoot
                            $searchRootCheck = Test-TpmRepairSearchRoot `
                                -Candidate $selectedSearchRoot -TeknoParrotRoot $tpRoot -ProgramDirectory $PSScriptRoot `
                                -ZipSource $zipSource -ZipSourceSupplementary $zipSourceSupplementary
                            $repairSearchAgain = $searchRootCheck.Valid
                            if ($repairSearchAgain) {
                                $searchRoot = $searchRootCheck.CanonicalPath
                            } else {
                                Write-Host ("  Search folder rejected: {0}. Nothing was changed." -f $searchRootCheck.Reason) -ForegroundColor Yellow
                            }
                        } elseif ($searchAgainChoice -eq 'B') {
                            $repairSearchAgain = $false
                            Write-Log 'HealthCheck: user selected Back after no automatic repair candidates; no additional search was started.'
                        }
                    }
                } catch {
                    Write-Host ("  Automatic path repair was not saved: {0}" -f $_.Exception.Message) -ForegroundColor Red
                    Write-Host '  No repair is claimed. Review the existing profiles and backup state before retrying.' -ForegroundColor Yellow
                    $repairSearchAgain = $false
                }
            } while ($repairSearchAgain)
            if ($repairReCopyRequested) { continue }
            [void](Read-HostSafe '  Press Enter to return to the main menu')
            continue
        }
        if ($healthChoice -eq 'M' -and @($healthResult.Broken).Count -gt 0) {
            $manualRepair = Invoke-LibraryHealthManualPathRepair -UserProfilesDir $userProfilesDir `
                -GamesInstallFolder $gamesInstallFolder -BrokenGames ([string[]]@($healthResult.Broken))
            Write-Host ("  Manual path repair outcome: {0}" -f $manualRepair.Outcome) -ForegroundColor $(if ($manualRepair.Outcome -eq 'SUCCEEDED') { 'Green' } elseif ($manualRepair.Outcome -eq 'NO_OP') { 'DarkGray' } else { 'Yellow' })
            Write-Host ("  Manual path repair saved {0} profile(s)." -f @($manualRepair.ChangedItems).Count) -ForegroundColor $(if ($manualRepair.Outcome -eq 'SUCCEEDED') { 'Green' } else { 'DarkGray' })
            if ($manualRepair.Backup.RootPath) { Write-Host ("  Safety backup: {0}" -f $manualRepair.Backup.RootPath) -ForegroundColor DarkGray }
            if (@($manualRepair.SkippedItems).Count -gt 0) { Write-Host ("  Left unchanged: {0}" -f (@($manualRepair.SkippedItems) -join ', ')) -ForegroundColor DarkGray }
            if (@($manualRepair.FailedItems).Count -gt 0) { Write-Host ("  Could not save: {0}" -f (@($manualRepair.FailedItems) -join ', ')) -ForegroundColor Yellow }
            foreach ($keptCopyPath in @(Get-TpmTransactionField -Object $manualRepair -Name 'RetainedCopies' -Default @())) { Write-Host ("  A profile was removed while saving. A copy of its new settings is kept in {0}. Restore the safety backup, or rename that file back to the profile name." -f $keptCopyPath) -ForegroundColor Red }
            [void](Read-HostSafe '  Press Enter to return to the main menu')
            continue
        }
        if ($healthChoice -eq 'P' -and $healthResult.PostgresInventoryStatus -eq 'Complete' -and (@($healthResult.PostgresNeeded).Count -gt 0 -or @(Get-TpmTransactionField -Object $healthResult -Name 'PostgresDatabaseProblems' -Default @()).Count -gt 0)) {
            $pendingApplyMode = 'PostgresSetup'
            $pendingApplyForce = $false
            continue
        }
        if ($healthChoice -eq '5') { $pendingApplyMode = 'ReShadeSetup'; $pendingApplyForce = $false; continue }
        if ($healthChoice -eq '6') { $pendingApplyMode = 'DgVoodoo2Setup'; $pendingApplyForce = $false; continue }
        if ($healthChoice -eq '7') { $pendingApplyMode = 'GpuFixSetup'; $pendingApplyForce = $false; continue }
        if ($healthChoice -eq '8') { $pendingApplyMode = 'FFBSetup'; $pendingApplyForce = $false; continue }
        if ($healthChoice -eq '9') { $pendingApplyMode = 'BepInExUpdate'; $pendingApplyForce = $false; continue }
        continue
    }

    if ($mode -eq "PostgresSetup") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " PostgreSQL Setup (Incredible Technologies games)" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host "  Each game has one database. A game on Internal storage makes its own," -ForegroundColor DarkGray
        Write-Host "  so it is skipped here." -ForegroundColor DarkGray
        Write-Host "  For every game that uses PostgreSQL, this step makes that game's database" -ForegroundColor DarkGray
        Write-Host "  from the game's own backup when it is missing, then tests it with the game's" -ForegroundColor DarkGray
        Write-Host "  own settings before setup says it is ready." -ForegroundColor DarkGray
        Write-Host "  Every Golden Tee Live and PGA Tour game is covered, as are the other IT" -ForegroundColor DarkGray
        Write-Host "  games with a database." -ForegroundColor DarkGray
        Write-Host "  A game with no backup makes its own database the first time it starts" -ForegroundColor DarkGray
        Write-Host "  (TeknoParrot does this)." -ForegroundColor DarkGray
        foreach ($choiceLine in (Get-TpmDatabaseChoiceLines)) { Write-Host ('  ' + $choiceLine) -ForegroundColor DarkGray }
        $postgresStatus = New-TpmWorkflowStatusContext -WorkflowKey 'PostgresSetup' -Title 'PostgreSQL setup' -Steps @(
            @{ Id = 'scan'; Label = 'Check which games need PostgreSQL' }
            @{ Id = 'database'; Label = 'Back up existing databases' }
            @{ Id = 'save'; Label = 'Save the repaired settings' }
            @{ Id = 'profiles'; Label = 'Finish game database setup' }
        )
        $script:PostgresRecoveryStatus = $postgresStatus
        [void](Start-TpmWorkflowStatus -Context $postgresStatus)
        [void](Start-TpmWorkflowStep -Context $postgresStatus -StepId 'scan' -Activity 'Checking registered games')
        $postgresResumeState = $null
        $postgresSetupDetailsResult = $null
        if ($isPostgresRecoveryResume) {
            try {
                $postgresResumeState = Read-PostgresRecoveryState -StatePath $PostgresRecoveryResumeToken -ExpectedConfigPath $configPath -ExpectedScriptPath (Join-Path $PSScriptRoot 'TeknoParrot-Manager.ps1') -ExpectedTpRoot $tpRoot -ExpectedUserProfilesDir (Join-Path $tpRoot 'UserProfiles')
            } catch {
                $resumeFailure = [string]$_.Exception.Message
                if ($resumeFailure -match 'Reason \[PACKAGE_MISMATCH\]') {
                    $resumeFailureMessage = 'This PostgreSQL step was started by a different TeknoParrot Manager copy, or that copy changed while Windows approval was open. TeknoParrot Manager stopped before changing anything. Restart setup from the same TeknoParrot Manager copy that opened the permission prompt. The log records which identity differed.'
                } else {
                    $resumeFailureMessage = 'TeknoParrot Manager could not safely continue the PostgreSQL setup. Review its log for the failure reason before trying again.'
                }
                Exit-PostgresRecoveryResume -Message $resumeFailureMessage
            }
            $script:PostgresRecoveryResumeState = $postgresResumeState
            if (-not (Test-RunningAsAdministrator)) {
                Exit-PostgresRecoveryResume -Message 'Windows did not give TeknoParrot Manager the permission needed to continue the PostgreSQL setup.'
            }
            Write-Host '  TeknoParrot Manager is continuing the PostgreSQL setup automatically.' -ForegroundColor Cyan
        }
        Write-Host "  Scanning registered games for Postgres requirements..." -ForegroundColor DarkGray
        $pgProfiles = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $userProfilesDir -ProgressLabel 'PostgreSQL requirement profile discovery' -EnumerationErrorAction SilentlyContinue | Sort-Object Name)
        $requirementScan = Get-TpmPostgresRequirementScan -ProfileFiles $pgProfiles
        $needCount = [int]$requirementScan.NeedCount
        $scanBlocked = [bool]$requirementScan.ScanBlocked
        if ($scanBlocked) {
            Write-Host "  Could not safely scan every registered profile -- no changes made." -ForegroundColor Red
            if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not safely read every registered game profile.' }
            [void](Set-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-scan' -Message 'TeknoParrot Manager could not safely check every registered game.' -DataSafety 'No PostgreSQL or profile changes were made.' -RecoveryActions (Get-PostgresRecoveryActions -FailureId 'postgres-scan'))
            [void](Read-HostSafe '  Press Enter to acknowledge this message')
            [void](Acknowledge-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-scan')
            [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL scan stopped')
            [void](Close-TpmWorkflowStatus -Context $postgresStatus)
            [void](Read-HostSafe "  Press Enter to return to menu")
            continue
        }
        if ($isPostgresRecoveryResume -and $postgresResumeState.Operation -eq 'Reinitialize' -and [string]::IsNullOrWhiteSpace($postgresResumeState.SelectionPlanJson)) {
            Exit-PostgresRecoveryResume -Message 'The list of PostgreSQL databases to rebuild is missing.'
        }
        if ($isPostgresRecoveryResume -and $postgresResumeState.SelectionPlanJson) {
            try {
                $resumePlans = @(($postgresResumeState.SelectionPlanJson | ConvertFrom-Json))
                $resumeDbNames = @($resumePlans | ForEach-Object { [string]$_.Database } | Where-Object { $_ } | Sort-Object -Unique)
                $currentResumePlans = @(Get-PostgresReinitializePlansFromProfiles -UserProfilesDir $userProfilesDir -OnlyDatabases $resumeDbNames)
                if (-not (Test-PostgresReinitializePlan -ExpectedPlanJson $postgresResumeState.SelectionPlanJson -ExpectedPlanHash $postgresResumeState.SelectionPlanHash -CurrentPlans $currentResumePlans)) {
                    Exit-PostgresRecoveryResume -Message 'The list of PostgreSQL databases to rebuild changed; no database changes were made.'
                }
            } catch {
                Exit-PostgresRecoveryResume -Message 'The list of PostgreSQL databases to rebuild could not be checked.'
            }
        }
        [void](Complete-TpmWorkflowStep -Context $postgresStatus -Outcome Succeeded -Summary 'Game requirements checked' -NextStep 'Back up existing databases')
        if ($needCount -eq 0) {
            Write-Host "  No registered game needs PostgreSQL -- nothing to do." -ForegroundColor Green
            if ([int]$requirementScan.InternalCount -gt 0) {
                Write-Host ("  {0} game(s) use Internal storage. No database install is needed." -f [int]$requirementScan.InternalCount) -ForegroundColor Green
                Write-Host "  Start each game once so it creates its own database." -ForegroundColor Green
            }
            Write-Log ("Postgres setup: no game is set to Existing PostgreSQL; {0} game(s) use Internal storage." -f [int]$requirementScan.InternalCount)
            [void](Start-TpmWorkflowStep -Context $postgresStatus -StepId 'database' -Activity 'No PostgreSQL repair is needed')
            [void](Complete-TpmWorkflowStep -Context $postgresStatus -Outcome Skipped -Summary 'No registered game needs PostgreSQL')
            [void](Complete-TpmWorkflowStatus -Context $postgresStatus -Summary 'No action needed')
            [void](Close-TpmWorkflowStatus -Context $postgresStatus)
            if ($isPostgresRecoveryResume) {
                Exit-PostgresRecoveryResumeSuccess -ResumeState $postgresResumeState
            }
            [void](Read-HostSafe "  Press Enter to return to menu")
            continue
        }
        Write-Host ("  {0} registered game(s) need PostgreSQL." -f $needCount) -ForegroundColor Cyan
        if ([int]$requirementScan.InternalCount -gt 0) { Write-Host ("  {0} other game(s) use Internal storage. They need no database install and are skipped." -f [int]$requirementScan.InternalCount) -ForegroundColor DarkGray }
        if (-not (Test-PostgresInstalled) -and -not (Test-RunningAsAdministrator)) {
            # The leftover check is read-only: show its refusal here, because the administrator window closes by itself.
            $leftoversBeforeHandoff = Get-PostgresPartialInstallInventory
            if ($leftoversBeforeHandoff.Found) {
                Show-PostgresPartialInstallRefusal -Inventory $leftoversBeforeHandoff
                [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL installation stopped')
                [void](Close-TpmWorkflowStatus -Context $postgresStatus)
                [void](Read-HostSafe "  Press Enter to return to menu")
                continue
            }
            $handoffReport = $null
            [void](Set-TpmWorkflowWaiting -Context $postgresStatus -Message 'Windows needs permission to install PostgreSQL.' -UserAction 'Approve the Windows permission box')
            Write-PostgresAdministratorGuidance -Operation Install
            $elevated = Start-PostgresRecoveryAsAdministrator -ConfigPath $configPath -ScriptPath (Join-Path $PSScriptRoot 'TeknoParrot-Manager.ps1') -TpRoot $tpRoot -UserProfilesDir $userProfilesDir -Operation Install -HandoffReport ([ref]$handoffReport)
            # The elevated child may have saved a credential; never write an older one back later.
            [void](Sync-PostgresSavedCredentialFromConfig)
            if ($elevated) {
                [void](Complete-TpmWorkflowStep -Context $postgresStatus -Outcome Fixed -Summary 'PostgreSQL installation continued automatically')
                [void](Complete-TpmWorkflowStatus -Context $postgresStatus -Summary 'PostgreSQL installation finished')
                [void](Close-TpmWorkflowStatus -Context $postgresStatus)
                exit 0
            }
            Write-Log 'Postgres setup: automatic installation handoff did not complete.'
            # FIX39: a reported result was already shown; keep one prompt before the main menu.
            if (-not $handoffReport) {
                [void](Set-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-install-handoff' -Message 'Install not verified; see View Log.' -DataSafety 'Install not verified; changes may exist. View Log before retry.' -RecoveryActions (Get-PostgresRecoveryActions -FailureId 'postgres-install-handoff'))
                [void](Read-HostSafe '  Press Enter to acknowledge this message')
                [void](Acknowledge-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-install-handoff')
            }
            [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL installation stopped')
            [void](Close-TpmWorkflowStatus -Context $postgresStatus)
            [void](Read-HostSafe "  Press Enter to return to menu")
            continue
        }
        if ($isPostgresRecoveryResume -and $postgresResumeState.Operation -in @('Recovery','Reinitialize') -and -not (Test-PostgresInstalled)) {
            Exit-PostgresRecoveryResume -Message 'The PostgreSQL installation was not available when TeknoParrot Manager resumed the repair.'
        }
        if (Test-PostgresManualRecoveryRequired) {
            $manualRecoveryDetail = Get-PostgresManualRecoveryDetail
            Write-Host ('  PostgreSQL setup is stopped. ' + $manualRecoveryDetail) -ForegroundColor Red
            Write-Log ('Postgres setup: stopped before any service or password operation. ' + (Get-PostgresManualRecoveryTechnicalDetail))
            if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message ('PostgreSQL setup is stopped. ' + $manualRecoveryDetail) }
            [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-manual-recovery' -Message 'PostgreSQL setup is stopped until the authentication policy is restored manually.' -DataSafety 'No PostgreSQL or profile changes were made.' -RecoveryActions (Get-PostgresRecoveryActions -FailureId 'postgres-manual-recovery') -Acknowledge)
            continue
        }
        $postgresServiceWasRunning = $null
        $postgresServiceRestoreFailed = $false
        $postgresSetupBodyDone = $false
        $postgresChangedThisRun = $false
        $script:PostgresServiceStartRefusedByMarker = $false
        if (Test-PostgresInstalled) {
            try {
                $serviceBeforeRecovery = Get-Service -Name $script:PostgresServiceName -ErrorAction Stop
                $postgresServiceWasRunning = ([string]$serviceBeforeRecovery.Status -ne 'Stopped')
            } catch {
                Write-Host '  TeknoParrot Manager could not verify PostgreSQL service state. No changes were made.' -ForegroundColor Red
                Write-Log 'Postgres setup: service state could not be verified before the transaction.'
                if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not verify the PostgreSQL service state before continuing.' }
                [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-service-state' -Message 'PostgreSQL service state could not be verified.' -DataSafety 'No PostgreSQL or profile changes were made.' -RecoveryActions (Get-PostgresRecoveryActions -FailureId 'postgres-service-state') -Acknowledge)
                continue
            }
        }

        $superPwPlain = $null
        $recoveryBackup = $null
        $outPw = $null
        try {
            if (Test-PostgresInstalled) {
                Write-Host "  PostgreSQL is already installed -- existing data will be preserved." -ForegroundColor Green
                if ($isPostgresRecoveryResume -and $postgresResumeState.Operation -in @('Recovery','Reinitialize')) {
                    $typedPwPlain = $postgresResumeState.PasswordPlain
                    $resumeProbe = Invoke-PostgresPasswordProbeSafely -SuperPasswordPlain $typedPwPlain
                    if ($resumeProbe.State -eq 'Authenticated') {
                        $superPwPlain = $typedPwPlain
                        $postgresSuperPasswordEncrypted = $postgresResumeState.PasswordOriginEncrypted
                    } else {
                        # FIX36 B1/S2, FIX95 B1: TeknoParrot Manager never resets the password. A
                        # Recovery handoff (only an older window still starts one) and
                        # Reinitialize both stop here when the password does not log in.
                        Write-Log ('Postgres recovery resume: password check result={0}; reason={1}; operation={2}; no password reset was attempted.' -f $resumeProbe.State, $resumeProbe.Reason, $postgresResumeState.Operation)
                        Exit-PostgresRecoveryResume -Message ('TeknoParrot Manager could not log in to PostgreSQL. ' + (Get-PostgresProbeExplanation -Probe $resumeProbe) + ' TeknoParrot Manager did not change the PostgreSQL password.')
                    }
                } else {
                    $credentialEntry = Resolve-PostgresSetupPassword -StatusContext $postgresStatus
                    if ($credentialEntry.Outcome -ne 'Ready') {
                        [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL repair stopped')
                        [void](Close-TpmWorkflowStatus -Context $postgresStatus)
                        [void](Read-HostSafe '  Press Enter to return to menu')
                        continue
                    }
                    $superPwPlain = $credentialEntry.PasswordPlain
                    $credentialEntry = $null
                    # The user may have started PostgreSQL while TPM waited ("check again").
                    # Treat it as originally running so the final restore does not stop it (R1).
                    if ($postgresServiceWasRunning -eq $false -and (Get-PostgresServiceStatusText) -eq 'Running') {
                        $postgresServiceWasRunning = $true
                        Write-Log 'Postgres setup: PostgreSQL was started during the password check; TeknoParrot Manager will leave it running.'
                    }
                }
            } else {
                $outPw = [ref]$null
                [void](Clear-TpmWorkflowFooter -Context $postgresStatus)
                if (-not (Invoke-TpmProgressGroup -Title 'PostgreSQL install' -Action { Install-Postgres83 -OutSuperPasswordPlain $outPw })) {
                    $installFailure = Get-PostgresInstallFailureView -InstallerRan ([bool]$script:PostgresInstallerRan)
                    Write-Host ('  ' + $installFailure.Screen) -ForegroundColor Red
                    Write-Host ('  ' + $installFailure.Next) -ForegroundColor Yellow
                    Write-Log ('Postgres setup: the install did not complete; the installer ran: {0}.' -f [bool]$script:PostgresInstallerRan)
                    if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message $installFailure.ResumeMessage }
                    $installFailureBlocks = @(@{ Heading = 'What happened'; Lines = @(('Installer ran: {0}' -f $(if ($script:PostgresInstallerRan) { 'yes' } else { 'no' })), $(if ($script:PostgresInstallerRan) { 'Reason: The Windows installer did not leave a working PostgreSQL service.' } else { 'Reason: An earlier check or download stopped setup (see the message above).' }), 'Log: TeknoParrot-Manager.log lists each step that ran.') })
                    [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-install-failed' -Message $installFailure.Message -DataSafety $installFailure.DataSafety -RecoveryActions (Get-PostgresRecoveryActions -FailureId 'postgres-install-failed') -DetailBlocks $installFailureBlocks -Acknowledge)
                    continue
                }
                $superPwPlain = $outPw.Value
                $postgresChangedThisRun = $true
            }

            if (-not $recoveryBackup) { $recoveryBackup = New-PostgresRecoveryBackup -UserProfilesDir $userProfilesDir }
            $recoveryEvidenceUnavailable = (-not $recoveryBackup -or $recoveryBackup.Verified -ne $true)
            if ($isPostgresRecoveryResume -and $recoveryEvidenceUnavailable) {
                Write-Host '  TeknoParrot Manager could not make a checked safety copy first, so it stopped. No profile changes were made.' -ForegroundColor Red
                Write-Log ('Postgres setup: the recovery evidence that could not be verified is at {0}.' -f $recoveryBackup.Path)
                Write-Log 'Postgres setup: verified recovery evidence was unavailable before configuration changes.'
                Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not verify the safety copy before continuing PostgreSQL setup.'
            }
            if ($isPostgresRecoveryResume -and $postgresResumeState.Operation -eq 'Reinitialize') {
                try {
                    [void](Clear-TpmWorkflowFooter -Context $postgresStatus)
                    $reinitResult = Invoke-TpmProgressGroup -Title 'PostgreSQL reinitialize' -Action { Invoke-PostgresReinitializePlan -PlanJson $postgresResumeState.SelectionPlanJson -PlanHash $postgresResumeState.SelectionPlanHash -UserProfilesDir $userProfilesDir -SuperPasswordPlain $superPwPlain -RecoveryBackup $recoveryBackup }
                    if ($reinitResult.Outcome -ne 'SUCCEEDED' -and -not ($reinitResult.Outcome -eq 'CLEANUP_RESIDUE' -and [string]$reinitResult.UnderlyingOutcome -eq 'SUCCEEDED')) { throw ([string]$reinitResult.Summary) }
                    Write-PostgresReinitializeSuccess -Result $reinitResult
                } catch {
                    Exit-PostgresRecoveryResume -Message $_.Exception.Message
                }
            }
            [void](Start-TpmWorkflowStep -Context $postgresStatus -StepId 'database' -Activity 'Backing up existing databases')
            Write-Host "  Backing up existing Postgres databases..." -ForegroundColor Cyan
            [void](Clear-TpmWorkflowFooter -Context $postgresStatus)
            $pgBackup = Invoke-TpmProgressGroup -Title 'PostgreSQL backup' -Action { Backup-PostgresDatabases -UserProfilesDir $userProfilesDir -SuperPasswordPlain $superPwPlain }
            # FIX39: the result for the original window says whether this backup worked.
            if ($isPostgresRecoveryResume -and $postgresResumeState) { $postgresResumeState | Add-Member -NotePropertyName DatabaseBackupSucceeded -NotePropertyValue ([bool]$pgBackup.Succeeded) -Force }
            if ($isPostgresRecoveryResume -and -not $pgBackup.Succeeded) {
                Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not finish the PostgreSQL database backup.'
            }
            if ($recoveryEvidenceUnavailable -and $pgBackup.Succeeded) {
                Write-Host '  TeknoParrot Manager could not make a checked safety copy first, so it stopped. No profile changes were made.' -ForegroundColor Red
                Write-Log ('Postgres setup: the recovery evidence that could not be verified is at {0}.' -f $recoveryBackup.Path)
                Write-Log 'Postgres setup: verified recovery evidence was unavailable before configuration changes.'
                if ($isPostgresRecoveryResume) {
                    Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not verify the safety copy before continuing PostgreSQL setup.'
                }
                [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-backup-unverified' -Message 'The safety copy could not be made, so TeknoParrot Manager stopped.' -DataSafety (Get-TpmPostgresNothingChangedText -PostgresChanged $postgresChangedThisRun -Unchanged 'No PostgreSQL or game-profile changes were made.') -RecoveryActions (Get-PostgresRecoveryActions -FailureId 'postgres-backup-unverified') -Acknowledge)
                continue
            }
            $returnToMainMenu = $false
            $postgresHandoffReported = $false
            while (-not $pgBackup.Succeeded) {
                [void](Set-TpmWorkflowWaiting -Context $postgresStatus -Message 'PostgreSQL needs attention before TeknoParrot Manager can make a safety backup.' -UserAction 'Choose a PostgreSQL recovery option')
                $authFailure = @($pgBackup.FailureDiagnoses | Where-Object { $_.Category -eq 'PasswordAuthenticationFailed' }).Count -gt 0
                # FIX36 B1/R2: the backup classifier only saw the word "password". The
                # password help (FIX95 B1: no automatic reset) is offered only when a
                # fresh check shows PostgreSQL running and positively rejecting the saved password.
                $passwordRejected = $false
                if ($authFailure -and -not [string]::IsNullOrEmpty([string]$superPwPlain)) {
                    $passwordRejected = ((Invoke-PostgresPasswordProbeSafely -SuperPasswordPlain $superPwPlain).State -eq 'Rejected')
                }
                Write-Host "  PostgreSQL setup stopped because the database backup did not complete." -ForegroundColor Red
                Write-Host ('  ' + (Get-TpmPostgresNothingChangedText -PostgresChanged $postgresChangedThisRun -Unchanged 'No PostgreSQL database or game-profile changes were made.')) -ForegroundColor Green
                Write-Host "  What happened"
                Write-Host "  Your games were not changed"
                Write-PostgresBackupFailureAffectedGames -Diagnoses $pgBackup.FailureDiagnoses
                Write-Host "  What TeknoParrot Manager can do next" -ForegroundColor Cyan
                if ($authFailure) {
                    Write-Host "  PostgreSQL password did not work." -ForegroundColor Yellow
                    if ($passwordRejected) {
                        Write-Host "  TeknoParrot Manager could not make a safety backup because PostgreSQL rejected the saved postgres password." -ForegroundColor Yellow
                    } else {
                        Write-Host "  TeknoParrot Manager could not make a safety backup, and the error mentions the password. A fresh check did not confirm that PostgreSQL rejects the saved password." -ForegroundColor Yellow
                    }
                    Write-Host ('  ' + (Get-TpmPostgresNothingChangedText -PostgresChanged $postgresChangedThisRun -Unchanged 'Your games and databases were not changed.')) -ForegroundColor Green
                }
                $backupMenu = Get-TpmPostgresBackupFailureChoices -AuthFailure $authFailure -PasswordRejected $passwordRejected -EvidenceUnavailable $recoveryEvidenceUnavailable
                if ($backupMenu.Notice) { Write-Host ('  ' + $backupMenu.Notice) -ForegroundColor Yellow }
                foreach ($backupMenuLine in $backupMenu.Lines) { Write-Host ('  ' + $backupMenuLine) }
                $backupChoice = Read-TpmChoice -Prompt $backupMenu.Prompt -Choices $backupMenu.Choices -Default $backupMenu.Default
                [void](Resume-TpmWorkflowStatus -Context $postgresStatus)
                if ($backupChoice -eq 'I') {
                    [void](Clear-TpmWorkflowFooter -Context $postgresStatus)
                    $choiceResult = Invoke-PostgresReinitializeChoice -FailureDiagnoses $pgBackup.FailureDiagnoses `
                        -UserProfilesDir $userProfilesDir -ConfigPath $configPath `
                        -ScriptPath (Join-Path $PSScriptRoot 'TeknoParrot-Manager.ps1') -TpRoot $tpRoot `
                        -SuperPasswordPlain $superPwPlain -RecoveryBackup $recoveryBackup
                    if ($choiceResult.Outcome -in @('Completed', 'Stopped') -or [bool](Get-TpmTransactionField -Object $choiceResult -Name 'DatabaseMayHaveChanged' -Default $false)) { $postgresChangedThisRun = $true }
                    if ($choiceResult.Outcome -eq 'Elevated') { exit 0 }
                    if ($choiceResult.Outcome -eq 'Stopped') {
                        # FIX39: the administrator window's result was shown; return to the main menu.
                        $postgresHandoffReported = $true
                        $returnToMainMenu = $true
                        break
                    }
                    if ($choiceResult.Outcome -eq 'Completed') {
                        [void](Clear-TpmWorkflowFooter -Context $postgresStatus)
                        $pgBackup = Invoke-TpmProgressGroup -Title 'PostgreSQL backup retry' -Action { Backup-PostgresDatabases -UserProfilesDir $userProfilesDir -SuperPasswordPlain $superPwPlain }
                    }
                    continue
                }
                if ($authFailure -and $backupChoice -eq 'P') {
                    [void](Update-TpmWorkflowActivity -Context $postgresStatus -Activity 'Checking the PostgreSQL password')
                    [void](Set-TpmWorkflowWaiting -Context $postgresStatus -Message 'Enter and confirm the working PostgreSQL password.' -UserAction 'Enter the password twice')
                    try {
                        $candidatePassword = Read-ConfirmedPostgresPassword 'the working PostgreSQL password'
                    } finally {
                        [void](Resume-TpmWorkflowStatus -Context $postgresStatus)
                    }
                    if ($null -eq $candidatePassword) {
                        Write-Host '  No password entered. Nothing was changed or saved.' -ForegroundColor Yellow
                        continue
                    }
                    try {
                        $candidateProbe = Invoke-PostgresPasswordProbeSafely -SuperPasswordPlain $candidatePassword
                        if ($candidateProbe.State -eq 'Authenticated') {
                            # Save, then read the settings file back from disk (FIX36 B3).
                            $candidateSave = Save-PostgresVerifiedCredential -PasswordPlain $candidatePassword
                            if (-not $candidateSave.Saved) {
                                Write-Host ('  PostgreSQL login succeeded, but TeknoParrot Manager could not save the new credential and read it back. ' + (Get-TpmPostgresNothingChangedText -PostgresChanged $postgresChangedThisRun -Unchanged 'No database or game-profile changes were made.')) -ForegroundColor Red
                                Write-Log 'Postgres setup: validated replacement password failed save or read-after-write verification.'
                                continue
                            }
                            $superPwPlain = $candidatePassword
                            Write-Host "  PostgreSQL password validated and saved securely." -ForegroundColor Green
                            Write-Host "  TeknoParrot Manager will now retry the safety backup automatically." -ForegroundColor Cyan
                            Write-Log 'Postgres setup: replacement password validated, read back, and saved without logging the password.'
                            [void](Clear-TpmWorkflowFooter -Context $postgresStatus)
                            $pgBackup = Invoke-TpmProgressGroup -Title 'PostgreSQL backup retry' -Action { Backup-PostgresDatabases -UserProfilesDir $userProfilesDir -SuperPasswordPlain $superPwPlain }
                        } elseif ($candidateProbe.State -eq 'Rejected') {
                            Write-Host "  PostgreSQL rejected that password. Nothing was saved." -ForegroundColor Red
                            Write-Log 'Postgres setup: replacement password validation failed; nothing was saved.'
                        } else {
                            Write-Host ("  TeknoParrot Manager could not check that password. {0} Nothing was saved." -f (Get-PostgresProbeExplanation -Probe $candidateProbe)) -ForegroundColor Yellow
                            Write-Log ('Postgres setup: replacement password could not be checked (reason={0}); nothing was saved.' -f $candidateProbe.Reason)
                        }
                    } finally { $candidatePassword = $null }
                    continue
                }
                if ($authFailure -and $backupChoice -eq 'X') {
                    Show-PostgresPasswordResetUnavailable -EnterKey 'P'
                    continue
                }
                if ($backupChoice -eq 'O') {
                    $supportRoot = [string]$script:TpmOwnedLayout.SupportPackages
                    Write-Host ("  TeknoParrot Manager log: {0}" -f $logPath) -ForegroundColor Cyan
                    Write-Host ("  Support package folder: {0}" -f $supportRoot) -ForegroundColor Cyan
                    Write-Host "  This recovery action did not create or open a support ZIP." -ForegroundColor DarkGray
                    foreach ($group in @(@($pgBackup.FailureDiagnoses) | Group-Object -Property Category | Sort-Object Name)) {
                        $affectedGames = @(@($group.Group) | ForEach-Object { [string]$_.GameLabel } | Where-Object { $_ } | Sort-Object -Unique)
                        Write-Host ("  Problem: {0}" -f (Get-PostgresDiagnosisPlainProblem -Category ([string]$group.Name))) -ForegroundColor Yellow
                        if ($affectedGames.Count -gt 0) { Write-Host ("  Games affected: {0}" -f ($affectedGames -join ', ')) -ForegroundColor Yellow }
                    }
                    Write-Host "  Choose [D] to see the technical details." -ForegroundColor DarkGray
                    foreach ($diagnosis in @($pgBackup.FailureDiagnoses)) {
                        $safeDetail = ConvertTo-PostgresRedactedText -Text ([string]$diagnosis.Detail) -Secrets @($superPwPlain)
                        Write-Log ("Postgres support diagnosis: ProfileKey={0}; Database={1}; Category={2}; Detail={3}" -f [string]$diagnosis.ProfileKey, [string]$diagnosis.Database, [string]$diagnosis.Category, $safeDetail)
                    }
                    Write-Log ("Postgres support guidance shown. LogPath={0}; SupportPackageRoot={1}" -f $logPath, $supportRoot)
                    continue
                }
                if ($backupChoice -eq 'D') {
                    Write-Host "  PostgreSQL backup details" -ForegroundColor Cyan
                    if ($pgBackup.Path) { Write-Host ("    Backup evidence: {0}" -f $pgBackup.Path) -ForegroundColor DarkGray }
                    foreach ($check in @((Get-PostgresBackupRepairDiagnosis -BackupResult $pgBackup).NormalChecks)) {
                        Write-Host ("    {0}: {1}" -f $check.Name, $check.Status) -ForegroundColor DarkGray
                    }
                    $diagnoses = @($pgBackup.FailureDiagnoses)
                    if ($diagnoses.Count -gt 0) {
                        foreach ($group in @($diagnoses | Group-Object -Property Category | Sort-Object Name)) {
                            $first = $group.Group | Select-Object -First 1
                            $affected = @(Get-PostgresDiagnosisAffectedPairs -Diagnoses $group.Group)
                            Write-Host ("    Cause: {0}" -f $group.Name) -ForegroundColor Yellow
                            Write-Host "    Affected databases:" -ForegroundColor Yellow
                            foreach ($entry in $affected) { Write-Host ("      - {0}" -f $entry) -ForegroundColor DarkGray }
                            foreach ($diagnosis in @($group.Group)) {
                                Write-Host ("      Profile key: {0}" -f [string]$diagnosis.ProfileKey) -ForegroundColor DarkGray
                                Write-Host ("      Database: {0}" -f [string]$diagnosis.Database) -ForegroundColor DarkGray
                                $safeDetail = ConvertTo-PostgresRedactedText -Text ([string]$diagnosis.Detail) -Secrets @($superPwPlain)
                                Write-Host ("      Detail: {0}" -f $safeDetail) -ForegroundColor DarkGray
                            }
                            Write-Host ("    Next action: {0}" -f $first.NextAction) -ForegroundColor DarkGray
                        }
                    } else {
                        Write-Host "    No grouped diagnosis was available. Review the support package for details." -ForegroundColor Yellow
                    }
                    Write-Log ("Postgres backup details shown. FailedDatabases={0}; FailureDetails={1}" -f (@($pgBackup.FailedDatabases) -join '|'), (@($pgBackup.FailureDetails) -join '|'))
                    continue
                }
                if ($backupChoice -eq 'R') {
                    $diagnosisReport = Get-PostgresBackupRepairDiagnosis -BackupResult $pgBackup
                    Write-Host ("  TeknoParrot Manager looked at PostgreSQL and changed nothing. {0}" -f $diagnosisReport.Summary) -ForegroundColor Yellow
                    Write-Host "  Choose [D] to see each check." -ForegroundColor DarkGray
                    Write-Log ("Postgres read-only diagnosis before retry: {0}" -f $diagnosisReport.Summary)
                    foreach ($check in @($diagnosisReport.TechnicalChecks)) {
                        Write-Log ("Postgres read-only diagnosis detail: {0}={1}; {2}" -f $check.Name, $check.Status, $check.Detail)
                    }
                    [void](Clear-TpmWorkflowFooter -Context $postgresStatus)
                    $pgBackup = Invoke-TpmProgressGroup -Title 'PostgreSQL backup retry' -Action { Backup-PostgresDatabases -UserProfilesDir $userProfilesDir -SuperPasswordPlain $superPwPlain }
                    continue
                }
                if ($backupChoice -eq 'B') {
                    Write-Host ('  Returning to the main menu. ' + (Get-TpmPostgresNothingChangedText -PostgresChanged $postgresChangedThisRun)) -ForegroundColor DarkGray
                    $returnToMainMenu = $true
                    break
                }
            }
            if ($returnToMainMenu) {
                if ($postgresHandoffReported) {
                    [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL repair stopped in the administrator window')
                } else {
                    Write-Log 'Postgres setup: user selected Back; no backup retry or profile mutation was attempted.'
                    [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL setup left by user')
                }
                [void](Close-TpmWorkflowStatus -Context $postgresStatus)
                if ($postgresHandoffReported -and -not $isPostgresRecoveryResume) {
                    [void](Read-HostSafe '  Press Enter to return to menu')
                }
                continue
            }
            if ($isPostgresRecoveryResume -and (-not $pgBackup.Succeeded)) { Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not finish the PostgreSQL database backup.' }
            if (-not $pgBackup.Succeeded) { continue }
            if ($recoveryEvidenceUnavailable) {
                Write-Host '  TeknoParrot Manager could not make a checked safety copy first, so it stopped. No profile changes were made.' -ForegroundColor Red
                Write-Log ('Postgres setup: the recovery evidence that could not be verified is at {0}.' -f $recoveryBackup.Path)
                Write-Log 'Postgres setup: verified recovery evidence was unavailable before configuration changes.'
                if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not verify the safety copy before continuing PostgreSQL setup.' }
                [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-backup-unverified' -Message 'The safety copy could not be made, so TeknoParrot Manager stopped.' -DataSafety (Get-TpmPostgresNothingChangedText -PostgresChanged $postgresChangedThisRun -Unchanged 'No PostgreSQL or game-profile changes were made.') -RecoveryActions (Get-PostgresRecoveryActions -FailureId 'postgres-backup-unverified') -Acknowledge)
                continue
            }
            if ($pgBackup.Path) { Write-Host ("  Database backup saved: {0}" -f $pgBackup.Path) -ForegroundColor DarkCyan }
            else { Write-Host "  No existing databases needed backup." -ForegroundColor DarkGray }
            $backupStepOutcome = if ([bool]$pgBackup.NoOp) { 'Skipped' } else { 'Succeeded' }
            $backupStepSummary = if ([bool]$pgBackup.NoOp) { 'No existing databases required backup' } else { 'Existing database backups completed' }
            [void](Complete-TpmWorkflowStep -Context $postgresStatus -Outcome $backupStepOutcome -Summary $backupStepSummary -NextStep 'Save the repaired settings')
            [void](Start-TpmWorkflowStep -Context $postgresStatus -StepId 'save' -Activity 'Saving the repaired settings')
            if (-not $isPostgresRecoveryResume -or ($outPw -and $outPw.Value)) { $postgresSuperPasswordEncrypted = ConvertTo-PostgresEncryptedPassword $superPwPlain }
            if (-not (Save-Config)) {
                Write-Host "  PostgreSQL setup stopped because the repaired settings could not be saved." -ForegroundColor Red
                Write-Log 'Postgres setup: encrypted password configuration save failed after database backup.'
                if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not save the PostgreSQL password settings.' }
                [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL setup stopped')
                [void](Close-TpmWorkflowStatus -Context $postgresStatus)
                if (-not $isPostgresRecoveryResume) { [void](Read-HostSafe '  Press Enter to return to menu') }
                continue
            }
            [void](Complete-TpmWorkflowStep -Context $postgresStatus -Outcome Succeeded -Summary 'Repaired settings saved' -NextStep 'Finish game database setup')



            # FIX36 S4: list profiles that already have their own password or connection
            # settings and ask before TPM writes the local postgres password into them.
            # The protected child never prompts: it stops before profile setup instead of
            # silently leaving games on another password.
            $passReplacementApprovals = @()
            $passConflicts = @(Get-PostgresProfilePassConflicts -ProfileFiles $pgProfiles -SuperPasswordPlain $superPwPlain)
            if ($passConflicts.Count -gt 0) {
                Write-Host '  These game profiles already have their own PostgreSQL password or connection settings:' -ForegroundColor Yellow
                foreach ($passConflict in $passConflicts) {
                    Write-Host ("    {0} [{1}]: {2}" -f $passConflict.Label, $passConflict.ProfileName, (@($passConflict.Reasons) -join '; ')) -ForegroundColor Yellow
                }
                if ($isPostgresRecoveryResume) {
                    # A retry cannot answer this question, so the child keeps no retry.
                    $postgresResumeState | Add-Member -NotePropertyName NoRetry -NotePropertyValue $true -Force
                    Exit-PostgresRecoveryResume -Message ('{0} game profile(s) already have their own PostgreSQL password or connection settings. TeknoParrot Manager did not change them. Choose PostgreSQL setup again from the main menu to decide whether to replace them.' -f $passConflicts.Count)
                } else {
                    Write-Host '  TeknoParrot Manager can write the local postgres password into these profiles. Do this only if these games use the PostgreSQL server on this PC as the postgres user.' -ForegroundColor Yellow
                    Write-Host '  If the PostgreSQL password was changed recently, a profile that still has the old password needs R, or that game cannot connect.' -ForegroundColor Yellow
                    Write-Host '  [R] Replace the password in these profiles'
                    Write-Host '  [K] Keep their current settings (default)'
                    $passChoice = Read-TpmChoice -Prompt '  Choice, default K' -Choices @('R', 'K') -Default 'K'
                    if ($passChoice -eq 'R') {
                        $passReplacementApprovals = @($passConflicts | ForEach-Object { [string]$_.Path })
                    } else {
                        Write-Host '  TeknoParrot Manager keeps the current settings in these profiles.' -ForegroundColor DarkGray
                    }
                }
            }
            [void](Start-TpmWorkflowStep -Context $postgresStatus -StepId 'profiles' -Activity 'Finishing game database setup')
            Write-Host "  Configuring games and creating only missing databases..." -ForegroundColor Cyan
            [void](Clear-TpmWorkflowFooter -Context $postgresStatus)
            $pgResults = Invoke-TpmProgressGroup -Title 'PostgreSQL game setup' -Action { Invoke-PostgresGameSetup -UserProfilesDir $userProfilesDir -SuperPasswordPlain $superPwPlain -RecoveryBackup $recoveryBackup -ApprovedPassReplacements $passReplacementApprovals }
            if (-not (Test-TpmTransactionResult -Result $pgResults)) {
                Write-Host '  PostgreSQL setup stopped in an unexpected way, and TeknoParrot Manager cannot tell what was done. Open View Log.' -ForegroundColor Red
                Write-Log 'Postgres setup: invalid transaction result.'
                if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not verify the PostgreSQL setup transaction result.' }
                [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-transaction-result' -Message 'PostgreSQL setup stopped in an unexpected way.' -DataSafety 'TeknoParrot Manager cannot tell what was changed. Open View Log, and ask for help before you try again.' -RecoveryActions (Get-PostgresRecoveryActions -FailureId 'postgres-transaction-result') -DetailBlocks @(@{ Heading = 'What happened'; Lines = @('Reason: The setup did not return a result that passed its own result check.', 'Log: TeknoParrot-Manager.log has the steps that ran.') }) -Acknowledge)
                continue
            }
            if ($pgResults.Outcome -notin @('SUCCEEDED','NO_OP') -and [string]$pgResults.ReasonCode -cne 'POSTGRES_SOME_GAMES_NOT_READY') {
                Write-TpmPostgresSetupFailure -Result $pgResults -OfferDetails:(-not $isPostgresRecoveryResume)
                Write-Log "Postgres setup: transaction outcome=$($pgResults.Outcome); reason=$($pgResults.ReasonCode)"
                if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not safely finish configuring the PostgreSQL game profiles.' }
                [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-transaction-failed' -Message $pgResults.Summary -DataSafety (Get-TpmPostgresDataSafetyText -Result $pgResults) -RecoveryActions (Get-PostgresRecoveryActions -FailureId 'postgres-transaction-failed') -Acknowledge)
                continue
            }
            if ($pgResults.RecoveryBlocked) {
                Write-Host '  PostgreSQL setup did not finish.' -ForegroundColor Red
                Write-Log ('Postgres setup: the recovery evidence is at {0}.' -f $pgResults.BackupPath)
                Write-Log 'Postgres setup: profile population was recovery-blocked.'
                if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not safely finish configuring the PostgreSQL game profiles.' }
                [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-profile-recovery' -Message 'Setting up the game databases did not finish.' -DataSafety (Get-TpmPostgresDataSafetyText -Result $null) -RecoveryActions (Get-PostgresRecoveryActions -FailureId 'postgres-profile-recovery') -Acknowledge)
                continue
            }
            if ([int]$pgResults.Errors -gt 0) {
                Write-Host ("  PostgreSQL setup had {0} problem(s) and did not finish." -f $pgResults.Errors) -ForegroundColor Red
                Write-Log 'Postgres setup: errors were reported; completion was not claimed.'
                if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not verify a clean PostgreSQL setup result.' }
                [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-profile-errors' -Message 'PostgreSQL setup had problems and did not finish.' -DataSafety (Get-TpmPostgresDataSafetyText -Result $null) -RecoveryActions (Get-PostgresRecoveryActions -FailureId 'postgres-profile-errors') -Acknowledge)
                continue
            }
            [void](Complete-TpmWorkflowStep -Context $postgresStatus -Outcome Succeeded -Summary $pgResults.Summary)
            # FIX63: short plain result screen; the technical sentences are behind D.
            # The protected child cannot prompt, so it offers no D.
            Write-TpmPostgresSetupResult -Result $pgResults -OfferDetails:(-not $isPostgresRecoveryResume)
            if (-not $isPostgresRecoveryResume) { $postgresSetupDetailsResult = $pgResults }
            Write-Log ("Postgres setup: complete. Configured={0} DbCreated={1} AlreadyConfigured={2} Errors={3}" -f $pgResults.Configured, $pgResults.DbCreated, $pgResults.AlreadyConfigured, $pgResults.Errors)
            $postgresSetupBodyDone = $true
        } finally {
            # FIX95 (B1): no TeknoParrot Manager step changes the authentication policy any more, so the
            # service is always put back as it was; Restore-PostgresServiceState still refuses a start
            # while an older build's trust-rule marker needs recovery.
            if ($null -ne $postgresServiceWasRunning -and -not (Restore-PostgresServiceState -WasRunning $postgresServiceWasRunning)) {
                $postgresServiceRestoreFailed = $true
            }
            if ($postgresServiceRestoreFailed -and -not $postgresSetupBodyDone) {
                # Setup left through an earlier `continue`, which skips the screen after this try: say it here instead.
                Write-Host '  PostgreSQL setup did not finish, because TeknoParrot Manager could not put PostgreSQL back to running or stopped the way it was.' -ForegroundColor Red
                if ($script:PostgresServiceStartRefusedByMarker) {
                    Write-Host ('  TeknoParrot Manager did not start PostgreSQL because an unfinished password repair may have left its temporary trust rule in place. ' + (Get-PostgresManualRecoveryDetail)) -ForegroundColor Red
                    Write-Log ('Postgres setup: service left stopped. ' + (Get-PostgresManualRecoveryTechnicalDetail))
                }
                Write-Log 'Postgres setup: original service state restoration failed after an earlier stop; completion was not claimed.'
                if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not restore the original PostgreSQL service state.' }
                [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-service-restore' -Message 'PostgreSQL could not be put back to running or stopped the way it was.' -DataSafety 'PostgreSQL setup is not finished. Open View Log to see what was done.' -RecoveryActions (Get-PostgresRecoveryActions -FailureId 'postgres-service-restore') -Acknowledge)
            }
            if ($outPw) { $outPw.Value = $null }
            $outPw = $null
            $secure = $null
            $superPwSecure = $null
            $savedPwPlain = $null
            $typedPwPlain = $null
            $superPwPlain = $null
            [GC]::Collect()
        }
        if ($postgresServiceRestoreFailed) {
            Write-Host '  PostgreSQL setup did not finish, because TeknoParrot Manager could not put PostgreSQL back to running or stopped the way it was.' -ForegroundColor Red
            if ($script:PostgresServiceStartRefusedByMarker) {
                # FIX36 B4: the service was left stopped on purpose.
                Write-Host ('  TeknoParrot Manager did not start PostgreSQL because an unfinished password repair may have left its temporary trust rule in place. ' + (Get-PostgresManualRecoveryDetail)) -ForegroundColor Red
                Write-Log ('Postgres setup: service left stopped. ' + (Get-PostgresManualRecoveryTechnicalDetail))
            }
            Write-Log 'Postgres setup: original service state restoration failed; completion was not claimed.'
            if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager could not restore the original PostgreSQL service state.' }
            $serviceRestoreBlocks = @(@{ Heading = 'What happened'; Lines = @(('Earlier state: {0}' -f $(if ($postgresServiceWasRunning) { 'running' } else { 'stopped' })), 'Reason: PostgreSQL could not be put back to that state.', $(if ($script:PostgresServiceStartRefusedByMarker) { 'Start refused: an unfinished older password repair may have left a temporary login rule, so PostgreSQL was left stopped on purpose.' } else { 'Start refused: no' }), 'Log: TeknoParrot-Manager.log has the steps that ran.') })
            [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-service-restore' -Message 'PostgreSQL could not be put back to running or stopped the way it was.' -DataSafety 'PostgreSQL setup is not finished. Open View Log to see what was done.' -RecoveryActions (Get-PostgresRecoveryActions -FailureId 'postgres-service-restore') -DetailBlocks $serviceRestoreBlocks -Acknowledge)
            continue
        }
        if ($isPostgresRecoveryResume) {
            Exit-PostgresRecoveryResumeSuccess -ResumeState $postgresResumeState
        }
        [void](Complete-TpmWorkflowStatus -Context $postgresStatus -Summary $pgResults.Summary)
        [void](Close-TpmWorkflowStatus -Context $postgresStatus)
        if ($postgresSetupDetailsResult) {
            $postgresDetailsAnswer = [string](Read-HostSafe '  Press Enter to return to menu, or D for details')
            if ($postgresDetailsAnswer.Trim().ToUpperInvariant() -eq 'D') {
                Write-TpmPostgresSetupDetails -Result $postgresSetupDetailsResult
                [void](Read-HostSafe "  Press Enter to return to menu.")
            }
            $postgresSetupDetailsResult = $null
        } else {
            [void](Read-HostSafe "  Press Enter to return to menu")
        }
        continue
    }
    if ($mode -eq "CheckForUpdates") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Check for Updates" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        $updateStatus = New-TpmWorkflowStatusContext -WorkflowKey 'CheckForUpdates' -Title 'Update check' -Steps @(
            @{ Id = 'query'; Label = 'Check for a newer TPM release' }
            @{ Id = 'apply'; Label = 'Back up, download, and validate the update' }
            @{ Id = 'verify'; Label = 'Verify the installed update' }
        )
        [void](Start-TpmWorkflowStatus -Context $updateStatus)
        [void](Start-TpmWorkflowStep -Context $updateStatus -StepId 'query' -Activity 'Checking for a newer release')
        [void](Complete-TpmWorkflowStep -Context $updateStatus -Summary 'Release check finished' -NextStep 'Apply only after approval')
        $scriptSelfPath = Join-Path $PSScriptRoot "TeknoParrot-Manager.ps1"
        $updateResult = Invoke-CheckForUpdates -ScriptPath $scriptSelfPath
        if (-not (Test-TpmTransactionResult -Result $updateResult)) {
            [void](Start-TpmWorkflowStep -Context $updateStatus -StepId 'apply' -Activity 'Handling the update result')
            [void](Complete-TpmWorkflowStep -Context $updateStatus -Outcome Skipped -Summary 'The update check did not return a valid verified result')
            [void](Complete-TpmWorkflowStatus -Context $updateStatus -Summary 'The update was not installed because its result could not be verified')
            [void](Close-TpmWorkflowStatus -Context $updateStatus)
            Write-Log 'CheckForUpdates: invalid transaction result; no restart.'
        } elseif ($updateResult.Outcome -eq 'SUCCEEDED' -or [bool](Get-TpmTransactionField -Object $updateResult -Name 'UpdateInstalled' -Default $false)) {
            [void](Start-TpmWorkflowStep -Context $updateStatus -StepId 'apply' -Activity 'Applying the approved update')
            [void](Complete-TpmWorkflowStep -Context $updateStatus -Outcome Fixed -Summary 'Update installed and verified' -NextStep 'Restart TPM')
            [void](Start-TpmWorkflowStep -Context $updateStatus -StepId 'verify' -Activity 'Verifying the installed update')
            [void](Complete-TpmWorkflowStep -Context $updateStatus -Summary 'Update verified')
            [void](Complete-TpmWorkflowStatus -Context $updateStatus -Summary 'Update installed and verified')
            [void](Close-TpmWorkflowStatus -Context $updateStatus)
        } else {
            [void](Start-TpmWorkflowStep -Context $updateStatus -StepId 'apply' -Activity 'Handling the update result')
            $updateSummary = if ($updateResult.Summary) { [string]$updateResult.Summary } else { 'No update was installed.' }
            [void](Complete-TpmWorkflowStep -Context $updateStatus -Outcome Skipped -Summary $updateSummary)
            [void](Complete-TpmWorkflowStatus -Context $updateStatus -Summary $updateSummary)
            [void](Close-TpmWorkflowStatus -Context $updateStatus)
        }
        if ($updateResult -and ($updateResult.Outcome -eq 'SUCCEEDED' -or [bool](Get-TpmTransactionField -Object $updateResult -Name 'UpdateInstalled' -Default $false))) {
            Write-Host ""
            if ($updateResult.Outcome -ne 'SUCCEEDED') { Write-Host ("  {0}" -f $updateResult.Summary) -ForegroundColor Yellow }
            Write-Host "  Restart TeknoParrot Manager now to run the verified update." -ForegroundColor Yellow
            [void](Read-HostSafe "  Press Enter to exit")
            Write-Log "CheckForUpdates: exiting after verified update -- not continuing in this session."
            exit 0
        }
        Write-Log "CheckForUpdates: complete, no restart needed."
        [void](Read-HostSafe "  Press Enter to return to menu")
        continue
    }

    if ($mode -eq "Support") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Create Support Package" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-TpmSupportPackageIntro
        $supportChoice = Read-TpmSupportMenuChoice -ReportsFolder ([string]$script:TpmOwnedLayout.Reports)
        if ($supportChoice -eq '2') {
            $openResult = Open-TpmLogsAndReports -LogsPath $script:TpmOwnedLayout.Logs -ReportsPath $script:TpmOwnedLayout.Reports
            if ($openResult.Succeeded) {
                Write-Host ("  Opened: {0}" -f $openResult.Path) -ForegroundColor Green
            } else {
                Write-Host ("  TeknoParrot Manager logs and reports could not be opened: {0}" -f $openResult.Error) -ForegroundColor Yellow
                Write-Host ("  Folder: {0}" -f $openResult.Path) -ForegroundColor DarkGray
            }
            continue
        }
        if ($supportChoice -eq '1') {
            Write-TpmUnhandledErrorsToLog -Where 'before the support package'
            $supportResult = Invoke-TpmProgressGroup -Title 'Support package' -Action { New-TpmSupportPackage -ScriptRoot $script:TpmOwnedLayout.Root -TeknoParrotRoot $tpRoot -UserProfilesDir $userProfilesDir -ApprovedGamesRoot $gamesInstallFolder }
            Write-TpmSupportPackageResult -Result $supportResult -Unattended:$Unattended
            if ($supportResult.PackagePath) {
                [void](Invoke-TpmSupportPackageFollowUp -PackagePath $supportResult.PackagePath -SupportPackagesRoot $script:TpmOwnedLayout.SupportPackages)
            }
        }
        continue
    }

    if ($mode -eq "PropagateControls") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Propagate Controls" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-TpmText -Text 'This copies the controls of games you already set up to your other games of the same type.' -Color DarkCyan
        Write-TpmText -Text 'This screen never registers or unpacks games.' -Color DarkCyan
        if (-not $Unattended) {
            Write-Host ''
            Write-TpmText -Text '1 = copy controls to games of the same type' -Indent 4
            Write-TpmText -Text '2 = set up games with my controller layout (Xbox, PlayStation, Nintendo or arcade stick)' -Indent 4
            Write-TpmText -Text '3 = choose or change my controller layout' -Indent 4
            Write-TpmText -Text '4 = check which games have all their controls (changes nothing)' -Indent 4
            Write-TpmText -Text '5 = my controls: learn my buttons, print a control guide, tell TPM a game worked' -Indent 4
            $controlsChoice = Read-TpmChoice -Prompt '  Choose 1, 2, 3, 4 or 5' -Choices @('1', '2', '3', '4', '5') -Default '1'
            if ($controlsChoice -eq '5') {
                Invoke-TpmControlsScreen -UserProfilesDir $userProfilesDir
                [void](Read-HostSafe "  Press Enter to return to menu")
                continue
            }
            if ($controlsChoice -ne '1') {
                $baselineStateDir = [string]$script:TpmOwnedLayout.State
                if ($controlsChoice -eq '2') { Invoke-TpmBaselineScreen -UserProfilesDir $userProfilesDir -GameProfilesDir $gameProfilesDir -StateDir $baselineStateDir }
                elseif ($controlsChoice -eq '3') { [void](Invoke-TpmBaselineChooseScreen -StateDir $baselineStateDir -Current (Read-TpmBaseline -StateDir $baselineStateDir)) }
                else { Invoke-TpmControlAuditScreen -UserProfilesDir $userProfilesDir -GameProfilesDir $gameProfilesDir }
                [void](Read-HostSafe "  Press Enter to return to menu")
                continue
            }
        }

        # Invoke-ControlPropagation owns the verified backup and returns the
        # authoritative transaction result. No backup is created before the
        # user confirms the proposed propagation.

        Write-Host ""
        $pool = Build-ArchetypePool -userProfilesDir $userProfilesDir -minBound $MinBoundForArchetype -familyOverride $familyOverrideMap
        if ($pool.Count -eq 0) {
            $propTransaction = Invoke-TpmProgressGroup -Title 'Control propagation' -Action { Invoke-ControlPropagation -userProfilesDir $userProfilesDir -pool @() -minBound $MinBoundForArchetype -noPropagate $noPropagateList -forceArchetype $forceArchetypeMap -familyOverride $familyOverrideMap -canonicalArchetype $canonicalArchetypeMap -DryRun $false }
            $null = Write-ControlPropagationResults -Reports @($propTransaction.Reports) -Outcome ([string]$propTransaction.Outcome) -Unattended:$Unattended
            [void](Read-HostSafe "  Press Enter to return to menu")
            continue
        }

        Write-TpmControlSourceSummary -Pool $pool
        Write-Host ""
        if ($Unattended) {
            Write-Host "  [Unattended] Propagating controls." -ForegroundColor DarkCyan
            Write-Log "PropagateControls: unattended -- propagation = Y."
            $goCtl = "Y"
        } else {
            # Show exactly what would change first (same code as the real run, nothing saved), then ask.
            $previewTx = Invoke-TpmProgressGroup -Title 'Control propagation preview' -Action { Invoke-ControlPropagation -userProfilesDir $userProfilesDir -pool $pool -minBound $MinBoundForArchetype -noPropagate $noPropagateList -forceArchetype $forceArchetypeMap -familyOverride $familyOverrideMap -canonicalArchetype $canonicalArchetypeMap -DryRun $true }
            $previewCounts = Write-ControlPropagationResults -Reports @($previewTx.Reports) -DryRun $true -Outcome ([string]$previewTx.Outcome)
            Write-Log ("PropagateControls: preview shown. controls={0} api={1} settings-only={2}" -f $previewCounts.ControlsCopiedCount, $previewCounts.ApiFixedCount, $previewCounts.SettingsOnlyCount)
            if (($previewCounts.ControlsCopiedCount + $previewCounts.ApiFixedCount + $previewCounts.SettingsOnlyCount) -eq 0) {
                $goCtl = 'N'
            } else {
                $goCtl = Read-TpmControlCopyApproval -Pool @($pool) -BackupNote 'A saved copy of your game settings is made when you approve. Its folder is shown afterwards.'
            }
        }
        if ($goCtl.ToUpperInvariant() -eq "Y") {
            $propTransaction = Invoke-TpmProgressGroup -Title 'Control propagation' -Action { Invoke-ControlPropagation -userProfilesDir $userProfilesDir -pool $pool -minBound $MinBoundForArchetype -noPropagate $noPropagateList -forceArchetype $forceArchetypeMap -familyOverride $familyOverrideMap -canonicalArchetype $canonicalArchetypeMap -DryRun $false }
            $propResult = Write-ControlPropagationResults -Reports @($propTransaction.Reports) -Outcome ([string]$propTransaction.Outcome) -BackupPath ([string]$propTransaction.Backup.RootPath) -Unattended:$Unattended
            if ($propTransaction.Outcome -eq 'SUCCEEDED') {
                Write-Log "PropagateControls: completed. Controls/API corrected=$($propResult.BoundCount); settings-only=$($propResult.SettingsOnlyCount)"
            } elseif ($propTransaction.Outcome -eq 'NO_OP') {
                Write-Log "PropagateControls: no profile writes were applied."
            }
            # One-step undo: the saved copy was made just before the first change, so it can be put back right here.
            $undoFolder = [string]$propTransaction.Backup.RootPath
            if (-not $Unattended -and $propTransaction.Outcome -in @('SUCCEEDED','PARTIAL_APPLIED') -and $undoFolder) {
                Write-Host ""
                if ((Read-TpmYesNo -Prompt "  Undo these changes and put your game settings back as they were? (Y/N)" -Default 'N') -eq 'Y') {
                    $undoResult = Invoke-TpmProgressGroup -Title 'Undo control changes' -Action { Invoke-RestoreBackup -userProfilesDir $userProfilesDir -SelectedBackupPath $undoFolder -AlreadyConfirmed }
                    Write-Log ("PropagateControls: undo requested; restore reported {0} ({1})" -f [string]$undoResult.Outcome, [string]$undoResult.ReasonCode)
                    $undoColor = if ($undoResult.Outcome -eq 'SUCCEEDED') { 'Green' } else { 'Yellow' }
                    Write-Host ("  " + [string]$undoResult.Summary) -ForegroundColor $undoColor
                }
            }
        } else {
            Write-Host " Skipped control propagation." -ForegroundColor DarkGray
            Write-Log "Propagation: user declined."
        }

        [void](Read-HostSafe "  Press Enter to return to menu")
        continue
    }

    if ($mode -eq "CrosshairSetup") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Crosshair Setup" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        $crosshairStatus = New-TpmWorkflowStatusContext -WorkflowKey 'CrosshairSetup' -Title 'Crosshair setup' -Steps @(
            @{ Id = 'inspect'; Label = 'Check the emulator and game folders' }
            @{ Id = 'choose'; Label = 'Choose the P1 and P2 crosshairs' }
            @{ Id = 'apply'; Label = 'Install and verify the crosshair files' }
        )
        [void](Start-TpmWorkflowStatus -Context $crosshairStatus)
        [void](Start-TpmWorkflowStep -Context $crosshairStatus -StepId 'inspect' -Activity 'Checking crosshair prerequisites')
        [void](Complete-TpmWorkflowStep -Context $crosshairStatus -Summary 'Prerequisites checked' -NextStep 'Choose the P1 and P2 crosshairs')
        [void](Start-TpmWorkflowStep -Context $crosshairStatus -StepId 'choose' -Activity 'Waiting for your crosshair choices')
        [void](Set-TpmWorkflowWaiting -Context $crosshairStatus -Message 'Choose the crosshair images to use.' -UserAction 'Enter the P1 and P2 image numbers')
        [void](Resume-TpmWorkflowStatus -Context $crosshairStatus)
        [void](Complete-TpmWorkflowStep -Context $crosshairStatus -Summary 'Crosshair choices recorded' -NextStep 'Install and verify the files')
        [void](Start-TpmWorkflowStep -Context $crosshairStatus -StepId 'apply' -Activity 'Installing crosshair files')
        [void](Clear-TpmWorkflowFooter -Context $crosshairStatus)
        $crosshairResult = Invoke-TpmProgressGroup -Title 'Crosshair setup' -Action { Invoke-CrosshairSetup -UserProfilesDir $userProfilesDir `
                              -TpRoot $tpRoot `
                              -WorkflowContext $crosshairStatus -ProtectedRoots @($zipSource, $zipSourceSupplementary) }
        if ($crosshairResult -and $crosshairResult.Succeeded) {
            $crosshairNoOp = ([string]$crosshairResult.Outcome -eq 'NO_OP')
            $crosshairNoTargets = [bool]$crosshairResult.NoTargets
            $crosshairSummary = if ($crosshairNoTargets) {
                if ($crosshairNoOp) { 'No eligible lightgun folders; no changes were needed' } else { 'P1/P2 selection saved; no eligible folders were available for file deployment' }
            } elseif ($crosshairNoOp) { 'Crosshair files and settings already match; no changes were needed' } else { 'Crosshair setup finished' }
            $stepOutcome = if ($crosshairNoOp -or $crosshairNoTargets) { 'Succeeded' } else { 'Fixed' }
            [void](Complete-TpmWorkflowStep -Context $crosshairStatus -Outcome $stepOutcome -Summary $crosshairSummary)
            [void](Complete-TpmWorkflowStatus -Context $crosshairStatus -Summary $crosshairSummary)
            [void](Close-TpmWorkflowStatus -Context $crosshairStatus)
            if ($crosshairNoOp) {
                Write-Log "Crosshair setup no-op; existing file and cursor settings remain unchanged."
            } elseif ($crosshairNoTargets) {
                Write-Log ("Crosshair setup completed without game deployment: transaction={0}; no eligible target folders." -f $crosshairResult.TransactionResult.Outcome)
            } else {
                Write-Log "Crosshair setup complete."
            }
            Show-TpmCrosshairResult -Result $crosshairResult -Unattended:$Unattended
        } elseif ($crosshairResult -and $crosshairResult.Cancelled) {
            [void](Stop-TpmWorkflowStatus -Context $crosshairStatus -Reason 'Crosshair setup canceled; no changes made')
            [void](Close-TpmWorkflowStatus -Context $crosshairStatus)
            Write-Host ""
            Write-Host "Crosshair setup canceled. No files were changed." -ForegroundColor DarkGray
            Write-Log "Crosshair setup canceled; no files were changed."
        } else {
            [void](Set-TpmWorkflowFailure -Context $crosshairStatus -FailureId 'crosshair-incomplete' -Message 'Crosshair setup was not completed.' -DataSafety 'TeknoParrot Manager did not claim a complete crosshair deployment.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
            Write-Host ""
            Write-Host "Crosshair setup was not completed. The message above is the authoritative result." -ForegroundColor Yellow
            [void](Read-HostSafe '  Press Enter to acknowledge the crosshair result')
            [void](Acknowledge-TpmWorkflowFailure -Context $crosshairStatus -FailureId 'crosshair-incomplete')
            [void](Stop-TpmWorkflowStatus -Context $crosshairStatus -Reason 'Crosshair setup stopped')
            [void](Close-TpmWorkflowStatus -Context $crosshairStatus)
            Write-Log "Crosshair setup did not complete; no success was claimed."
        }
        [void](Read-HostSafe "  Press Enter to return to menu")
        continue
    }

    if ($mode -eq "ReShadeSetup") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " ReShade Visual Enhancements Setup" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host ''
        if (-not $reShadeActionPending) {
            Write-Host '  S) Set up ReShade visual enhancements' -ForegroundColor White
            Write-Host '  R) Remove verified TeknoParrot Manager-managed ReShade files' -ForegroundColor White
            Write-Host '  U) Undo ReShade changes' -ForegroundColor White
            Write-Host '  B) Use my bezel folder (bezels you already have)' -ForegroundColor White
            $reShadeAction = Read-TpmChoice -Prompt '  Action (S/R/U/B, default S)' -Choices @('S', 'R', 'U', 'B') -Default 'S'
            if ($reShadeAction -eq 'S') { $reShadeAction = 'Select' }
        }
        if ($reShadeAction -eq 'B') {
            Invoke-TpmBezelSetup -UserProfilesDir $userProfilesDir -ProtectedRoots @($zipSource, $zipSourceSupplementary)
            [void](Read-HostSafe '  Press Enter to return to menu')
            continue
        }
        if ($reShadeAction -eq 'U') {
            Show-TpmReShadeUndoMenu -ProtectedRoots @($zipSource, $zipSourceSupplementary)
            continue
        }
        if ($reShadeAction -eq 'R') {
            $null = Invoke-TpmProgressGroup -Title 'ReShade removal' -Action { Invoke-TpmReShadeRemoval -UserProfilesDir $userProfilesDir -BackupRoot (Join-Path $userProfilesDir 'FullBackup') -ProtectedRoots @($zipSource, $zipSourceSupplementary) }
            [void](Read-HostSafe '  Press Enter to return to menu')
            continue
        }
        if ($reShadeAction -ne 'Select' -and $reShadeAction -ne 'Adopt') {
            Write-Host '  ReShade setup canceled. No files were changed.' -ForegroundColor Yellow
            [void](Read-HostSafe '  Press Enter to return to menu')
            continue
        }
        $reShadeStatus = New-TpmWorkflowStatusContext -WorkflowKey 'ReShadeSetup' -Title 'ReShade setup' -Steps @(
            @{ Id = 'inspect'; Label = 'Check the ReShade source' }
            @{ Id = 'acquire'; Label = 'Download and verify the official installer' }
            @{ Id = 'apply'; Label = 'Install the selected visual enhancement' }
            @{ Id = 'verify'; Label = 'Verify the result' }
        )
        $script:TpmReShadeInstallerEvidence = $null
        [void](Start-TpmWorkflowStatus -Context $reShadeStatus)
        [void](Start-TpmWorkflowStep -Context $reShadeStatus -StepId 'inspect' -Activity 'Checking ReShade files')
        $bundledDll   = Get-TpmUserReShadeDll -FileName 'ReShade64.dll'
        if (-not $rsSourceDll -or -not (Test-Path -LiteralPath $rsSourceDll)) {
            if ($bundledDll) {
                $rsSourceDll = $bundledDll
            } else {
                Write-Host ""
                [void](Complete-TpmWorkflowStep -Context $reShadeStatus -Summary 'ReShade source check complete; acquisition may be required' -NextStep 'Download and verify the official installer')
                [void](Start-TpmWorkflowStep -Context $reShadeStatus -StepId 'acquire' -Activity 'Preparing automatic download')
                $rsAcq = Request-TpmReShadeSourceDll
                if ($rsAcq.State -eq 'Invalid') {
                    if ($rsAcq.Reason -eq 'FileType') {
                        [void](Resolve-TpmWorkflowFailure -Context $reShadeStatus -FailureId 'reshade-file-type' -Message 'The selected ReShade file is not a DLL.' -DataSafety 'No ReShade file was deployed.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }) -Acknowledge)
                    } else {
                        [void](Resolve-TpmWorkflowFailure -Context $reShadeStatus -FailureId 'reshade-file-missing' -Message 'The selected ReShade file was not found.' -DataSafety 'No ReShade file was deployed.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }) -Acknowledge)
                    }
                    continue
                }
                if ($rsAcq.State -eq 'Acquired') {
                    $rsSourceDll = $rsAcq.Path
                } else {
                    [void](Set-TpmWorkflowFailure -Context $reShadeStatus -FailureId 'reshade-acquisition-canceled' -Message 'ReShade setup was canceled.' -DataSafety 'No unverified ReShade file was used.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
                    Write-Host '  ReShade setup canceled. No unverified DLL was used.' -ForegroundColor Yellow
                    Write-Log 'ReShade setup: canceled after automatic acquisition failed.'
                    [void](Read-HostSafe '  Press Enter to acknowledge the ReShade result')
                    [void](Acknowledge-TpmWorkflowFailure -Context $reShadeStatus -FailureId 'reshade-acquisition-canceled')
                    [void](Stop-TpmWorkflowStatus -Context $reShadeStatus -Reason 'ReShade setup stopped')
                    [void](Close-TpmWorkflowStatus -Context $reShadeStatus)
                    [void](Read-HostSafe '  Press Enter to return to menu')
                    continue
                }
            }
        }
        Add-TpmMissingReShade32FromSavedSetup -SourceDll $rsSourceDll
        try {
            [void](Clear-TpmWorkflowFooter -Context $reShadeStatus)
            $reShadeResult = Invoke-TpmProgressGroup -Title 'ReShade setup' -Action { Invoke-ReShadeSetup -UserProfilesDir $userProfilesDir `
                                -Action $reShadeAction `
                                -SourceDll $rsSourceDll `
                                -ConfigPath $configPath `
                                -TpRoot $tpRoot `
                                -Mode $mode `
                                -ZipSource $zipSource `
                                -GamesInstallFolder $gamesInstallFolder `
                                -RetroBat $retroBat -ZipSourceSupplementary $zipSourceSupplementary }
        } catch {
            $message = "ReShade setup stopped safely during profile selection or setup: $($_.Exception.Message)"
            Write-Host ("  {0}" -f $message) -ForegroundColor Red
            Write-Log $message
            [void](Resolve-TpmWorkflowFailure -Context $reShadeStatus -FailureId 'reshade-unhandled' -Message 'ReShade setup stopped safely after an unexpected error.' -DataSafety 'No unverified ReShade deployment was reported as complete.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }) -Acknowledge)
            [void](Stop-TpmWorkflowStatus -Context $reShadeStatus -Reason 'ReShade setup stopped after an unexpected error')
            [void](Close-TpmWorkflowStatus -Context $reShadeStatus)
            continue
        }
        if ($reShadeResult -and [bool]$reShadeResult.Cancelled) {
            Write-Log 'ReShade setup: canceled before deployment; no files were changed.'
            [void](Stop-TpmWorkflowStatus -Context $reShadeStatus -Reason 'ReShade setup canceled before deployment')
            [void](Close-TpmWorkflowStatus -Context $reShadeStatus)
            continue
        } elseif ($reShadeResult -and $reShadeResult.Succeeded) {
            if ($rsSourceDll -and (Test-Path -LiteralPath $rsSourceDll -PathType Leaf)) {
                if (Save-Config) {
                    Write-Log "Config: saved ReShadeSourceDll = $rsSourceDll after successful deployment"
                } else {
                    Write-Log "Config: could not save ReShadeSourceDll after successful deployment"
                }
            }
            [void](Complete-TpmWorkflowStep -Context $reShadeStatus -Outcome Fixed -Summary 'ReShade source verified' -NextStep 'Install into selected games')
            [void](Start-TpmWorkflowStep -Context $reShadeStatus -StepId 'apply' -Activity 'Installing ReShade into selected games')
            [void](Complete-TpmWorkflowStep -Context $reShadeStatus -Outcome Fixed -Summary 'ReShade files installed' -NextStep 'Verify the result')
            [void](Start-TpmWorkflowStep -Context $reShadeStatus -StepId 'verify' -Activity 'Verifying ReShade setup')
            [void](Complete-TpmWorkflowStep -Context $reShadeStatus -Summary 'ReShade setup finished')
            [void](Complete-TpmWorkflowStatus -Context $reShadeStatus -Summary 'ReShade setup finished')
            [void](Close-TpmWorkflowStatus -Context $reShadeStatus)
        } else {
            # FIX72: a run that only left games alone (protected, missing or unsafe) and had no error is a normal result that needs the
            # user's choice, not a failure: the workflow finishes normally and the screen says what happened and what to do. A real
            # error or an unverified deployment still raises the failure.
            $reShadeResultSummary = Get-TpmReShadeResultSummaryText -Result $reShadeResult
            $reShadeNothingFailed = Set-TpmReShadeSetupWorkflowEnd -Context $reShadeStatus -Result $reShadeResult -Summary $reShadeResultSummary
            if ($reShadeNothingFailed) { [void](Close-TpmWorkflowStatus -Context $reShadeStatus) }
            $reShadeScreen = Show-TpmReShadeSetupResult -Result $reShadeResult
            if ($reShadeScreen.PendingApplyMode) {
                $pendingApplyMode = $reShadeScreen.PendingApplyMode
                $pendingApplyForce = $false
                if ($reShadeScreen.PendingReShadeAction) { $pendingReShadeAction = $reShadeScreen.PendingReShadeAction }
            }
            if (-not $reShadeNothingFailed) {
                [void](Acknowledge-TpmWorkflowFailure -Context $reShadeStatus -FailureId 'reshade-incomplete')
                [void](Stop-TpmWorkflowStatus -Context $reShadeStatus -Reason 'ReShade setup completed with skips or errors')
                [void](Close-TpmWorkflowStatus -Context $reShadeStatus)
            }
            continue
        }
        $reShadeScreen = Show-TpmReShadeSetupResult -Result $reShadeResult
        Write-Log "ReShade setup complete."
        continue
    }

    if ($mode -eq "DgVoodoo2Setup") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " dgVoodoo2 Legacy Compatibility Setup" -ForegroundColor Cyan
        $dgStatus = New-TpmWorkflowStatusContext -WorkflowKey 'DgVoodoo2Setup' -Title 'dgVoodoo2 setup' -Steps @(
            @{ Id = 'inspect'; Label = 'Check legacy game requirements' }
            @{ Id = 'verify'; Label = 'Verify the result' }
        )
        [void](Start-TpmWorkflowStatus -Context $dgStatus)
        [void](Start-TpmWorkflowStep -Context $dgStatus -StepId 'inspect' -Activity 'Checking legacy game requirements')
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        $bundledDg = Get-TpmBundledDgVoodoo2Folder
        if (-not (Test-TpmDgVoodoo2SourceFolder -Path $dgSourceDir)) {
            if (Test-TpmDgVoodoo2SourceFolder -Path $bundledDg) {
                $dgSourceDir = $bundledDg
            } else {
                Write-Host ""
                $dgAcq = Request-TpmDgVoodoo2SourceDir
                if ($dgAcq.State -eq 'Acquired') {
                    $dgSourceDir = $dgAcq.Path
                } elseif ($dgAcq.State -eq 'CancelledAtFolder') {
                    Write-Host '  dgVoodoo2 setup canceled. No files were changed.' -ForegroundColor Yellow
                    Write-Log 'dgVoodoo2 setup: canceled at the folder prompt.'
                    [void](Stop-TpmWorkflowStatus -Context $dgStatus -Reason 'dgVoodoo2 setup canceled before deployment')
                    [void](Close-TpmWorkflowStatus -Context $dgStatus)
                    continue
                } else {
                    [void](Set-TpmWorkflowFailure -Context $dgStatus -FailureId 'dgv-acquisition-canceled' -Message 'dgVoodoo2 setup was canceled.' -DataSafety 'No unverified dgVoodoo2 files were used.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
                    Write-Host '  dgVoodoo2 setup canceled. No unverified files were used.' -ForegroundColor Yellow
                    Write-Log 'dgVoodoo2 setup: canceled after automatic acquisition failed.'
                    [void](Read-HostSafe '  Press Enter to acknowledge the dgVoodoo2 result')
                    [void](Acknowledge-TpmWorkflowFailure -Context $dgStatus -FailureId 'dgv-acquisition-canceled')
                    [void](Stop-TpmWorkflowStatus -Context $dgStatus -Reason 'dgVoodoo2 setup stopped')
                    [void](Close-TpmWorkflowStatus -Context $dgStatus)
                    [void](Read-HostSafe '  Press Enter to return to menu')
                    continue
                }
            }
            if (Save-Config) {
                Write-Log "Config: saved DgVoodoo2SourceDir = $dgSourceDir"
            } else {
                Write-Log "Config: could not save DgVoodoo2SourceDir"
            }
        }
        [void](Clear-TpmWorkflowFooter -Context $dgStatus)
        $dgResult = Invoke-TpmProgressGroup -Title 'dgVoodoo2 setup' -Action { Invoke-DgVoodoo2Setup -UserProfilesDir $userProfilesDir `
                              -SourceDir $dgSourceDir `
                              -ProtectedRoots @($zipSource, $zipSourceSupplementary) }
        if ($dgResult -and [bool]$dgResult.Cancelled) {
            [void](Stop-TpmWorkflowStatus -Context $dgStatus -Reason 'dgVoodoo2 setup canceled before deployment')
            [void](Close-TpmWorkflowStatus -Context $dgStatus)
            continue
        }
        if (-not ($dgResult -and $dgResult.Succeeded)) {
            $dgSummary = if ($dgResult) {
                "dgVoodoo2 setup was partial or blocked: {0} deployed, {1} skipped, {2} unavailable-device skip(s), {3} missing-path skip(s), {4} error(s)." -f $dgResult.Deployed, $dgResult.Skipped, $dgResult.MissingDevice, $dgResult.MissingPath, $dgResult.Errors
            } else {
                'dgVoodoo2 setup did not return a verified result.'
            }
            [void](Set-TpmWorkflowFailure -Context $dgStatus -FailureId 'dgv-deployment-failed' -Message $dgSummary -DataSafety 'TPM did not claim a complete dgVoodoo2 deployment. Review the transaction result and log before retrying; do not assume failed operations were rolled back.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
            $dgGuidance = Get-DgVoodoo2FailureGuidance -Result $dgResult
            if ($dgResult -and $dgResult.PSObject.Properties['PickedGames']) {
                # The result screen names every game that was selected and how it came out; the technical lines go to the log.
                Write-Log ('dgVoodoo2 result: {0} Reason: {1}' -f $dgSummary, $dgResult.Reason)
                $dgFailureView = Get-TpmDgVoodoo2ResultView -Result $dgResult
                Write-TpmOutcome @dgFailureView
            } else {
                Write-Host ("  {0}" -f $dgSummary) -ForegroundColor Yellow
                if ($dgResult) { Write-Host ("  Reason: {0}" -f $dgResult.Reason) -ForegroundColor Yellow }
                if ($dgResult -and $dgResult.TransactionResult) {
                    Write-Host ("  Transaction: {0}; state: {1}. {2}" -f $dgResult.TransactionResult.Outcome, $dgResult.TransactionResult.ProductState, $dgResult.TransactionResult.Summary) -ForegroundColor Yellow
                }
                if ($dgGuidance.DeviceMessage) {
                    Write-Host ("  {0}" -f $dgGuidance.DeviceMessage) -ForegroundColor Yellow
                }
                if ($dgGuidance.MissingPathMessage) {
                    Write-Host ("  {0}" -f $dgGuidance.MissingPathMessage) -ForegroundColor Yellow
                }
            }
            if ($dgGuidance.OfferHealthCheck) {
                Write-Host "  [H] Open 13) Library Health Check for missing paths" -ForegroundColor White
                Write-Host "  [B] Back to main menu" -ForegroundColor White
                $dgFailureChoice = Read-TpmChoice -Prompt '  Choose H or B' -Choices @('H', 'B') -Default 'B'
                if ($dgFailureChoice -eq 'H') {
                    $pendingApplyMode = 'HealthCheck'
                    $pendingApplyForce = $false
                }
            } else {
                [void](Read-HostSafe '  Press Enter to acknowledge the dgVoodoo2 result')
            }
            [void](Acknowledge-TpmWorkflowFailure -Context $dgStatus -FailureId 'dgv-deployment-failed')
            [void](Stop-TpmWorkflowStatus -Context $dgStatus -Reason 'dgVoodoo2 setup completed with skips or errors')
            [void](Close-TpmWorkflowStatus -Context $dgStatus)
            continue
        }
        $dgNoOp = [bool]$dgResult.NoOp
        $dgCompletionSummary = if ($dgNoOp) { 'No dgVoodoo2 changes were needed' } else { 'dgVoodoo2 setup finished' }
        $dgStepOutcome = if ($dgNoOp) { 'Succeeded' } else { 'Fixed' }
        [void](Complete-TpmWorkflowStep -Context $dgStatus -Outcome $dgStepOutcome -Summary $dgCompletionSummary -NextStep 'Verify the result')
        [void](Start-TpmWorkflowStep -Context $dgStatus -StepId 'verify' -Activity 'Verifying dgVoodoo2 setup')
        [void](Complete-TpmWorkflowStep -Context $dgStatus -Summary $dgCompletionSummary)
        [void](Complete-TpmWorkflowStatus -Context $dgStatus -Summary $dgCompletionSummary)
        [void](Close-TpmWorkflowStatus -Context $dgStatus)
        Show-TpmDgVoodoo2Result -Result $dgResult
        $dgChoices = @('D', 'O', 'B')
        do {
            Write-Host "  [D] Details   [O] Open support/log guidance" -ForegroundColor White
            Write-Host "  [B] Back to main menu" -ForegroundColor White
            $dgPromptChoices = $dgChoices -join ', '
            $dgResultChoice = Read-TpmChoice -Prompt ("  Choose {0}" -f $dgPromptChoices) -Choices $dgChoices -Default 'B'
            if ($dgResultChoice -eq 'D') {
                $dgView = Get-TpmDgVoodoo2ResultView -Result $dgResult
                Show-TpmDetailBlocks -Blocks $dgView.DetailBlocks
            } elseif ($dgResultChoice -eq 'O') {
                Write-Host ("  Support package folder: {0}" -f $script:TpmOwnedLayout.SupportPackages) -ForegroundColor Cyan
                Write-Host ("  Technical log: {0}" -f $logPath) -ForegroundColor Cyan
                Write-Host "  This screen does not create or open a support ZIP." -ForegroundColor DarkGray
            }
        } while ($dgResultChoice -in @('D', 'O'))
        Write-Log "dgVoodoo2 setup complete."
        continue
    }

    if ($mode -eq "GpuFixSetup") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " GPU Compatibility Fix Setup" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host ""
        Write-TpmText -Text 'This checks your games and applies the right graphics card fix to each game that has one.' -BlankBefore
        Write-TpmText -Text 'It is safe to run again, for example after you change your graphics card or driver.'
        $gpuResult = Invoke-TpmProgressGroup -Title 'GPU compatibility fix' -Action { Invoke-GpuFixSetup -UserProfilesDir $userProfilesDir `
                           -TpRoot $tpRoot }
        if ($null -eq $gpuResult -or @($gpuResult.PSTypeNames) -notcontains 'TPM.TransactionResult.v1') {
            Write-Host "GPU Compatibility Fix did not return a result. No success was claimed." -ForegroundColor Yellow
            [void](Read-HostSafe 'Press Enter to return to the main menu')
            continue
        }
        $gpuShowSummary = $true
        do {
            if ($gpuShowSummary) {
                Show-TpmGpuFixResult -Result $gpuResult
                $gpuShowSummary = $false
            }
            Write-Host "  [D] Details" -ForegroundColor White
            Write-Host "  [O] Open support/log guidance" -ForegroundColor White
            $gpuHasPathIssue = ([int]$gpuResult.MissingPath -gt 0 -or [int]$gpuResult.MissingDevice -gt 0)
            if ($gpuHasPathIssue) { Write-Host "  [H] Open 13) Library Health Check for missing paths" -ForegroundColor White }
            Write-Host "  [R] Run GPU Fix again" -ForegroundColor White
            Write-Host "  [B] Back to main menu" -ForegroundColor White
            $gpuChoices = @('D', 'O', 'R', 'B')
            if ($gpuHasPathIssue) { $gpuChoices = @('D', 'O', 'H', 'R', 'B') }
            $gpuPromptChoices = $gpuChoices -join ', '
            $gpuResultChoice = Read-TpmChoice -Prompt ("  Choose {0}" -f $gpuPromptChoices) -Choices $gpuChoices -Default 'B'
            if ($gpuResultChoice -eq 'D') {
                $gpuView = Get-TpmGpuFixResultView -Result $gpuResult
                Show-TpmDetailBlocks -Blocks $gpuView.DetailBlocks -Note $gpuView.DetailsNote
            } elseif ($gpuResultChoice -eq 'O') {
                Write-Host "  Open the support package or TeknoParrot-Manager.log for the recorded technical details." -ForegroundColor DarkGray
            } elseif ($gpuResultChoice -eq 'H') {
                $pendingApplyMode = 'HealthCheck'
                $pendingApplyForce = $false
                $gpuResultChoice = 'B'
            } elseif ($gpuResultChoice -eq 'R') {
                $gpuResult = Invoke-TpmProgressGroup -Title 'GPU compatibility fix (retry)' -Action { Invoke-GpuFixSetup -UserProfilesDir $userProfilesDir -TpRoot $tpRoot }
                if ($null -eq $gpuResult -or @($gpuResult.PSTypeNames) -notcontains 'TPM.TransactionResult.v1') {
                    Write-Host "GPU Compatibility Fix did not return a result. No success was claimed." -ForegroundColor Yellow
                    [void](Read-HostSafe 'Press Enter to return to the main menu')
                    $gpuResultChoice = 'B'
                } else {
                    $gpuShowSummary = $true
                }
            }
        } while ($gpuResultChoice -in @('D', 'O', 'R'))
        continue
    }

    if ($mode -eq "FFBSetup") {
        $ffbModeResult = Invoke-TpmFfbSetupMode -UserProfilesDir $userProfilesDir -TpRoot $tpRoot -ScriptRoot $script:TpmOwnedLayout.Root
        $ffbHasPathIssue = ($ffbModeResult -and ($ffbModeResult.MissingPath -gt 0 -or $ffbModeResult.MissingDevice -gt 0))
        if ($ffbHasPathIssue) {
            Write-Host ""
            if ($ffbModeResult.MissingPath -gt 0) {
                Write-Host ("  FFB skipped {0} game(s) because their saved paths are unavailable." -f $ffbModeResult.MissingPath) -ForegroundColor Yellow
                Write-Host ("    Affected games: {0}" -f (@($ffbModeResult.MissingPathGames) -join ', ')) -ForegroundColor DarkGray
            }
            if ($ffbModeResult.MissingDevice -gt 0) {
                Write-Host ("  FFB skipped {0} game(s) because their saved devices are unavailable." -f $ffbModeResult.MissingDevice) -ForegroundColor Yellow
                Write-Host ("    Affected games: {0}" -f (@($ffbModeResult.MissingDeviceGames) -join ', ')) -ForegroundColor DarkGray
            }
            Write-Host "  [H] Open 13) Library Health Check to repair saved paths" -ForegroundColor White
            Write-Host "  [B] Back to main menu" -ForegroundColor White
            $ffbPathChoice = Read-TpmChoice -Prompt '  Choose H or B' -Choices @('H', 'B') -Default 'B'
            if ($ffbPathChoice -eq 'H') {
                $pendingApplyMode = 'HealthCheck'
                $pendingApplyForce = $false
            } else {
                [void](Read-HostSafe "  Press Enter to return to menu")
            }
        } elseif ($ffbModeResult.Completed) {
            Write-Host "Done." -ForegroundColor Green
            Write-Log "FFB setup complete."
            [void](Read-HostSafe "  Press Enter to return to menu")
        }
        continue
    }

    if ($mode -eq "BepInExUpdate") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " BepInEx Update Check" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host ""
        Write-Host "  BepInEx is a third-party Unity plugin/modding framework. Some"
        Write-Host "  TeknoParrot games need it for controls or fixes to work via a"
        Write-Host "  community plugin." -NoNewline
        $requiredGames = Get-BepInExRequiredGames
        if ($requiredGames.Count -gt 0) {
            Write-Host " Known examples:"
            $lineLen = 70; $line = "    "; $firstR = $true
            foreach ($g in $requiredGames) {
                $add = if ($firstR) { $g } else { ", $g" }
                if (($line + $add).Length -gt $lineLen) {
                    Write-Host $line -ForegroundColor White
                    $line = "    $g"; $firstR = $false
                } else { $line += $add; $firstR = $false }
            }
            if ($line.Trim()) { Write-Host $line -ForegroundColor White }
        } else {
            Write-Host ""
        }
        Write-Host ""
        Write-Host "  TeknoParrot Manager can install or update BepInEx for selected games." -ForegroundColor DarkCyan
        Write-Host "  It chooses the stable package matching each game's 32-bit or 64-bit executable." -ForegroundColor DarkCyan
        Write-Host "  Nothing is changed until you approve the listed games." -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host "  Troubleshooting: https://docs.bepinex.dev/articles/user_guide/troubleshooting.html"
        $bepInExCacheDir = Join-Path $PSScriptRoot "BepInExCache"
        $bepStatus = New-TpmWorkflowStatusContext -WorkflowKey 'BepInEx' -Title 'BepInEx setup' -Steps @(
            @{ Id = 'inspect'; Label = 'Check eligible game folders' }
            @{ Id = 'apply'; Label = 'Back up and apply the selected change' }
            @{ Id = 'verify'; Label = 'Verify the result' }
        )
        [void](Start-TpmWorkflowStatus -Context $bepStatus)
        [void](Start-TpmWorkflowStep -Context $bepStatus -StepId 'inspect' -Activity 'Checking game folders')
        [void](Complete-TpmWorkflowStep -Context $bepStatus -Summary 'Game folders checked' -NextStep 'Back up and apply the selected change')
        [void](Clear-TpmWorkflowFooter -Context $bepStatus)
        $bepResult = Invoke-TpmProgressGroup -Title 'BepInEx update check' -Action { Invoke-BepInExUpdateCheck -UserProfilesDir $userProfilesDir -CacheDir $bepInExCacheDir -ApprovedGamesRoot $gamesInstallFolder -ProtectedRoots @($zipSource, $zipSourceSupplementary) }
        Write-Host ""
        if ($bepResult -and [bool]$bepResult.Cancelled) {
            Write-Host 'BepInEx setup canceled before applying updates. No files were changed.' -ForegroundColor DarkGray
            [void](Stop-TpmWorkflowStatus -Context $bepStatus -Reason 'BepInEx setup canceled before deployment')
            [void](Close-TpmWorkflowStatus -Context $bepStatus)
            continue
        } elseif ($bepResult -and $bepResult.Outcome -eq 'NO_OP') {
            [void](Start-TpmWorkflowStep -Context $bepStatus -StepId 'apply' -Activity 'Checking whether an update is needed')
            [void](Complete-TpmWorkflowStep -Context $bepStatus -Outcome Skipped -Summary ([string]$bepResult.Summary))
            [void](Complete-TpmWorkflowStatus -Context $bepStatus -Summary ([string]$bepResult.Summary))
            [void](Close-TpmWorkflowStatus -Context $bepStatus)
            Write-Host ("{0}" -f [string]$bepResult.Summary) -ForegroundColor DarkGray
            Write-Log 'BepInEx update check: no files changed.'
            [void](Read-HostSafe '  Press Enter to return to menu')
            continue
        } elseif ($bepResult -and ($bepResult.Outcome -eq 'SUCCEEDED' -or ($bepResult.Outcome -eq 'CLEANUP_RESIDUE' -and [string]$bepResult.UnderlyingOutcome -eq 'SUCCEEDED'))) {
            [void](Start-TpmWorkflowStep -Context $bepStatus -StepId 'apply' -Activity 'Applying the selected BepInEx change')
            [void](Complete-TpmWorkflowStep -Context $bepStatus -Outcome Fixed -Summary 'BepInEx change applied' -NextStep 'Verify the result')
            [void](Start-TpmWorkflowStep -Context $bepStatus -StepId 'verify' -Activity 'Verifying the result')
            [void](Complete-TpmWorkflowStep -Context $bepStatus -Summary 'BepInEx setup finished and was verified')
            [void](Complete-TpmWorkflowStatus -Context $bepStatus -Summary 'BepInEx setup finished')
            [void](Close-TpmWorkflowStatus -Context $bepStatus)
            Write-Host "BepInEx setup finished and was verified." -ForegroundColor Green
            foreach ($bepDoneLine in @(Get-TpmBepInExDoneLines -Result $bepResult)) { Write-TpmText -Text $bepDoneLine -Indent 2 }
            if ($bepResult.Outcome -eq 'CLEANUP_RESIDUE') { Write-Host '  Your games are updated. TeknoParrot Manager could not remove its temporary files; open View Log to see where they are.' -ForegroundColor Yellow }
            Write-Log "BepInEx update check complete."
            [void](Read-HostSafe '  Press Enter to return to menu')
        } else {
            $bepView = Get-TpmBepInExFailureView -Result $bepResult
            [void](Set-TpmWorkflowFailure -Context $bepStatus -FailureId 'bepinex-failed' -Message ([string]$bepView.Title) -DataSafety 'TeknoParrot Manager did not claim success for blocked or failed games; no unverified change was reported as complete.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
            Show-TpmBepInExFailureSummary -Result $bepResult
            $bepPathIssue = $bepResult -and ($bepResult.MissingPath -gt 0 -or $bepResult.MissingDevice -gt 0)
            $bepRecovered = $false
            $bepRollbackIssue = $bepResult -and $bepResult.PathReasonCounts -and $bepResult.PathReasonCounts.ContainsKey('ROLLBACK_FAILED')
            $bepChoices = if ($bepRollbackIssue) { @('D', 'O', 'B') } else { @('R', 'D', 'O', 'B') }
            if ($bepPathIssue) { $bepChoices += 'H' }
            do {
                if ($bepRollbackIssue) {
                    Write-Host "  Rollback could not be verified. Do not retry until the preserved backup/evidence has been inspected." -ForegroundColor Red
                }
                if (-not $bepRollbackIssue) { Write-Host "  [R] Try BepInEx setup again" -ForegroundColor White }
                Write-Host "  [D] Show details" -ForegroundColor White
                Write-Host "  [O] Open support/log guidance" -ForegroundColor White
                Write-Host "  [B] Back to main menu" -ForegroundColor White
                if ($bepPathIssue) { Write-Host "  [H] Open 13) Library Health Check for missing paths" -ForegroundColor White }
                $bepPromptChoices = $bepChoices -join ', '
                $bepChoice = Read-TpmChoice -Prompt ("  Choose {0}" -f $bepPromptChoices) -Choices $bepChoices -Default 'B'
                if ($bepChoice -eq 'R') {
                    Write-Host "  Starting BepInEx setup again. No success is claimed until verification completes." -ForegroundColor Cyan
                    [void](Clear-TpmWorkflowFooter -Context $bepStatus)
                    $previousBepResult = $bepResult
                    $bepResult = Invoke-TpmProgressGroup -Title 'BepInEx setup (retry)' -Action {
                        $bepRaw = Invoke-BepInExUpdateCheck -UserProfilesDir $userProfilesDir -CacheDir $bepInExCacheDir -ApprovedGamesRoot $gamesInstallFolder -ProtectedRoots @($zipSource, $zipSourceSupplementary)
                        if ($null -eq $bepRaw -or @($bepRaw.PSTypeNames) -notcontains 'TPM.TransactionResult.v1') {
                            $bepRaw = New-TpmProfileTransactionResult -WorkflowKey 'BepInEx' -OperationKey 'UpdateProfiles' -Outcome 'ACTION_REQUIRED' -ProductState 'UNKNOWN' -Summary 'BepInEx setup did not return a verified transaction result.' -Items @('bepinex-update') -FailedItems @('bepinex-update') -MutationStarted $false -FinalPassed $false -ReasonCode 'RESULT_UNAVAILABLE' -FinalChecks @('The caller received no authoritative transaction result.')
                            $bepRaw | Add-Member -NotePropertyName Updated -NotePropertyValue 0 -Force
                            $bepRaw | Add-Member -NotePropertyName MissingDevice -NotePropertyValue 0 -Force
                            $bepRaw | Add-Member -NotePropertyName MissingPath -NotePropertyValue 0 -Force
                            $bepRaw | Add-Member -NotePropertyName Errors -NotePropertyValue 1 -Force
                            $bepRaw | Add-Member -NotePropertyName PathReasonCounts -NotePropertyValue @{ 'RERUN_NO_RESULT' = 1 } -Force
                        }
                        $bepRaw
                    }
                    if ($bepResult -and [bool]$bepResult.Cancelled) {
                        Write-Host '  BepInEx retry canceled; the previous unsuccessful result remains unresolved.' -ForegroundColor Yellow
                        $bepResult = $previousBepResult
                        $bepChoice = 'B'
                    }
                    if ($bepResult.ReasonCode -eq 'RESULT_UNAVAILABLE') {
                        Write-Host "  BepInEx setup could not complete. No success was claimed." -ForegroundColor Yellow
                    }
                    $bepPathIssue = $bepResult -and ($bepResult.MissingPath -gt 0 -or $bepResult.MissingDevice -gt 0)
                    $bepRollbackIssue = $bepResult -and $bepResult.PathReasonCounts -and $bepResult.PathReasonCounts.ContainsKey('ROLLBACK_FAILED')
                    $bepChoices = if ($bepRollbackIssue) { @('D', 'O', 'B') } else { @('R', 'D', 'O', 'B') }
                    if ($bepPathIssue) { $bepChoices += 'H' }
                    if ($bepResult -and ($bepResult.Outcome -eq 'SUCCEEDED' -or ($bepResult.Outcome -eq 'CLEANUP_RESIDUE' -and [string]$bepResult.UnderlyingOutcome -eq 'SUCCEEDED'))) {
                        $bepRecovered = $true
                        Write-Host "  BepInEx setup completed and was verified. Returning to the menu." -ForegroundColor Green
                        $bepChoice = 'B'
                    }
                    if (-not $bepRecovered) { Show-TpmBepInExFailureSummary -Result $bepResult }
                } elseif ($bepChoice -eq 'H') {
                    $pendingApplyMode = 'HealthCheck'
                    $pendingApplyForce = $false
                    $bepChoice = 'B'
                } elseif ($bepChoice -eq 'D') {
                    $bepView = Get-TpmBepInExFailureView -Result $bepResult -LogPath $logPath
                    Show-TpmDetailBlocks -Blocks $bepView.DetailBlocks -Note $bepView.DetailsNote
                } elseif ($bepChoice -eq 'O') {
                    Write-Host ("  Support package folder: {0}" -f $script:TpmOwnedLayout.SupportPackages) -ForegroundColor Cyan
                    Write-Host ("  Technical log: {0}" -f $logPath) -ForegroundColor Cyan
                    Write-Host "  This screen does not create or open a support ZIP." -ForegroundColor DarkGray
                }
            } while ($bepChoice -in @('R', 'D', 'O'))
            if ($bepRecovered) {
                [void](Acknowledge-TpmWorkflowFailure -Context $bepStatus -FailureId 'bepinex-failed')
                [void](Start-TpmWorkflowStep -Context $bepStatus -StepId 'apply' -Activity 'Applying the BepInEx change')
                [void](Complete-TpmWorkflowStep -Context $bepStatus -Outcome Fixed -Summary 'BepInEx change applied' -NextStep 'Verify the result')
                [void](Start-TpmWorkflowStep -Context $bepStatus -StepId 'verify' -Activity 'Verifying the result')
                [void](Complete-TpmWorkflowStep -Context $bepStatus -Summary 'BepInEx setup finished and was verified')
                [void](Complete-TpmWorkflowStatus -Context $bepStatus -Summary 'BepInEx setup finished')
                [void](Close-TpmWorkflowStatus -Context $bepStatus)
                [void](Read-HostSafe '  Press Enter to return to menu')
            } else {
                [void](Acknowledge-TpmWorkflowFailure -Context $bepStatus -FailureId 'bepinex-failed')
                [void](Stop-TpmWorkflowStatus -Context $bepStatus -Reason 'BepInEx setup completed with skips or errors')
                [void](Close-TpmWorkflowStatus -Context $bepStatus)
            }
        }
        continue
    }

    # Decide Preview/Run/Back before any AutoSync/Register input, config write,
    # network probe, benchmark, or staging operation.
    if ($forceRealApply) {
        $dryRunActive   = $false
        $forceRealApply = $false
    } else {
        $dryRunActive = [bool]$DryRun
        if (-not $Unattended -and -not $dryRunActive) {
            Write-Host ""
                Write-Host '  [P] Preview (default) -- show what would change; no game or profile changes'
                Write-Host '  [R] Run now -- back up UserProfiles first, then make the changes'
                Write-Host '  [B] Back'
                $previewChoice = Read-TpmChoice -Prompt '  Choice, default P' -Choices @('P', 'R', 'B') -Default 'P'
            if ($previewChoice -eq 'B') { continue }
            $dryRunActive = ($previewChoice -eq 'P')
        }
    }
    if ($dryRunActive) { Write-Log "PREVIEW MODE active for this run -- no changes will be written." }

    $zipPathsJustCaptured = $false
    Clear-TpmDeferredDetails
    if ($mode -eq "AutoSync" -and -not $zipSource) {
        Write-Host ""
        Write-Host "  Game ZIP folder (your own game .zip files)" -ForegroundColor Cyan
        Write-Host "  Choose the folder directly containing your original .zip files, not a folder above it." -ForegroundColor DarkCyan
        Write-Host ("  This must be DIFFERENT from your games folder (staging folder): {0}" -f $gamesInstallFolder) -ForegroundColor Yellow
        Write-Host "  Example: <ROM folder>\TeknoParrot Collection" -ForegroundColor DarkCyan
        # Ask again after a closed browse window, an empty answer or a folder that does not exist; Q goes back to the menu.
        $zipSource = ''
        while ($true) {
            $zipAnswer = ([string](Read-PathWithBrowse "  Path (Q to go back)")).Trim().Trim('"')
            if ($zipAnswer.ToUpperInvariant() -eq 'Q') { break }
            if ($zipAnswer -eq '') {
                Write-TpmText 'No folder was chosen. Type the path again, type B to browse again, or Q to go back.' -Color Yellow
                Write-Log ('AutoSync: no ZIP folder chosen (browse canceled: {0}); asking again.' -f [bool]$script:TpmPathBrowseCancelled)
                if ($Unattended) { break }
                continue
            }
            if (-not (Test-Path -LiteralPath $zipAnswer -PathType Container)) {
                Write-TpmText 'That folder was not found. Check the spelling, type B to browse, or Q to go back.' -Color Yellow
                Write-Log "AutoSync: ZIP folder not found: $zipAnswer; asking again."
                if ($Unattended) { break }
                continue
            }
            $zipSource = $zipAnswer
            break
        }
        if ([string]::IsNullOrWhiteSpace($zipSource)) {
            Write-Host "  No ZIP folder chosen. Nothing was changed." -ForegroundColor Yellow
            Write-Log "AutoSync: no ZIP folder chosen; returned to menu."; if (-not $Unattended) { [void](Read-HostSafe "  Press Enter to return to menu") }; continue
        }
        $zipPathsJustCaptured = $true
    }
    if ($mode -eq "AutoSync" -and ($null -eq $zipSourceSupplementary -or $zipSourceSupplementary -eq '') -and -not $Unattended) {
        Write-Host ""
        Write-Host "  Supplementary game collection folder (optional)" -ForegroundColor Cyan
        Write-Host "  A second folder of your own game .zip files, if you keep some apart from the first." -ForegroundColor DarkCyan
        Write-Host "  (This is not the Supplementary DAT. No second folder? Press Enter to skip.)" -ForegroundColor DarkCyan
        Write-Host "  Example: <ROM folder>\TeknoParrot Supplementary" -ForegroundColor DarkCyan
        $rawSupp = Read-PathWithBrowse "  Path (or press Enter to skip)"
        if ($rawSupp -and (Test-Path -LiteralPath $rawSupp)) {
            $zipSourceSupplementary = $rawSupp
            Write-Log "Config: supplementary ZIP source set to $rawSupp"
        } elseif ($rawSupp) {
            Write-Host "  Folder not found -- supplementary source skipped." -ForegroundColor Yellow
            Write-Log "Config: supplementary ZIP source not found at $rawSupp -- skipped."
        } else {
            $zipSourceSupplementary = ''
            Write-Log "Config: supplementary ZIP source skipped by user."
        }
        $zipPathsJustCaptured = $true
    }
    if ($zipPathsJustCaptured) {
        if (Save-Config) {
            Write-Log "Config: saved ZIP source path(s)."
        } else {
            Write-Log "Config: could not re-save after ZIP source prompt."
        }
    }

    if ($mode -eq "AutoSync") {
        if (-not (Test-Path -LiteralPath $zipSource)) {
            Write-Host ""; Write-Host "ERROR: ZIP source folder not found: $zipSource" -ForegroundColor Red
            Write-Log "ERROR: ZIP source not found."; if (-not $Unattended) { [void](Read-HostSafe "  Press Enter to return to menu") }; continue
        }
        # Reject every protected-path overlap before any network classification
        # or throughput probe can touch the proposed staging location.
        $earlyStagingCandidate = Test-TpmStagingFolderCandidate `
            -Candidate $gamesInstallFolder -TeknoParrotRoot $tpRoot `
            -ZipSource $zipSource -ZipSourceSupplementary $zipSourceSupplementary `
            -ProgramDirectory $PSScriptRoot
        if (-not $earlyStagingCandidate.Valid) {
            Write-Host ""; Write-Host "ERROR: The staging folder is not safe to use." -ForegroundColor Red
            Write-Host ("    Staging folder : {0}" -f $gamesInstallFolder) -ForegroundColor Yellow
            Write-Host ("    Reason         : {0}" -f $earlyStagingCandidate.Reason) -ForegroundColor Yellow
            Write-Host "Choose a folder outside TeknoParrot, TeknoParrot Manager, and every ZIP source folder." -ForegroundColor Yellow
            if ($Unattended) {
                Write-Log ("ERROR: unsafe staging folder -- {0}" -f $earlyStagingCandidate.Reason)
                continue
            }
            $gamesInstallFolder = Read-TpmStagingFolderWithRecommendation -TeknoParrotRoot $tpRoot -ZipSource $zipSource -ZipSourceSupplementary $zipSourceSupplementary
            if (Save-Config) { Write-Log "Config: staging folder updated after early unsafe-path rejection" }
            # The folder just chosen was already checked by the prompt; check it again here and carry on with this run.
            $earlyStagingCandidate = Test-TpmStagingFolderCandidate `
                -Candidate $gamesInstallFolder -TeknoParrotRoot $tpRoot `
                -ZipSource $zipSource -ZipSourceSupplementary $zipSourceSupplementary `
                -ProgramDirectory $PSScriptRoot
            if (-not $earlyStagingCandidate.Valid) { continue }
        }
        $gamesInstallFolder = $earlyStagingCandidate.CanonicalPath
        $autoSyncDriveInfo = Get-LocalDriveInfoSafe
        $stagingIsNetwork = Test-IsNetworkPath $gamesInstallFolder -Drives $autoSyncDriveInfo
        if ($null -eq $stagingIsNetwork) {
            Write-Host ""
            Write-Host "  TeknoParrot Manager could not check whether the staging folder is on a network drive." -ForegroundColor Yellow
            Write-Host "  If it is, extracting and playing games from it can be slow." -ForegroundColor Yellow
            Write-Log "Network check unknown for staging folder: $gamesInstallFolder"
        }
        if ($stagingIsNetwork) {
            Write-Host ""
            Write-Host "  WARNING: The staging folder is on a network path." -ForegroundColor Yellow
            Write-Host "  Games will be extracted to -- and played from -- the network drive." -ForegroundColor Yellow
            Write-Host "  A local drive (e.g. D:\TeknoParrotGames) is faster and recommended." -ForegroundColor Yellow
            if ($dryRunActive) {
                Write-Host "  Preview: the write-speed test is skipped, so nothing is written to the staging drive." -ForegroundColor DarkGray
                $stagingMbps = $null
            } else {
                Write-Host "  Measuring write speed to the staging drive..." -ForegroundColor Cyan
                $stagingMbps = Measure-PathWriteThroughput $gamesInstallFolder
            }
            if ($stagingMbps) {
                if ($stagingMbps -ge 500) {
                    Write-Host ("  Write speed: {0} MB/s -- fast enough for smooth extraction and gameplay." -f $stagingMbps) -ForegroundColor Green
                } elseif ($stagingMbps -ge 150) {
                    Write-Host ("  Write speed: {0} MB/s -- extraction will work but games may stutter during play." -f $stagingMbps) -ForegroundColor Yellow
                } else {
                    Write-Host ("  Write speed: {0} MB/s -- too slow for reliable extraction or play. Local drive strongly recommended." -f $stagingMbps) -ForegroundColor Red
                }
                Write-Log "Network staging benchmark: $stagingMbps MB/s"
            } else {
                Write-Host "  Write speed could not be measured (staging folder may not exist yet or is read-only)." -ForegroundColor DarkCyan
                Write-Log "Network staging benchmark: skipped (folder not found or write failed)"
            }
            if ($Unattended) {
                Write-Host "  [Unattended] Continuing with network staging folder." -ForegroundColor Yellow
                Write-Log "Unattended: network staging folder -- continuing."
            } else {
                $contNet = Read-TpmYesNo -Prompt "  Continue with network staging folder? (Y/N)"
                if ($contNet.ToUpperInvariant() -ne "Y") {
                    Write-Host "Aborted." -ForegroundColor Yellow
                    Write-Log "Aborted: user declined network staging folder."
                    [void](Read-HostSafe "  Press Enter to return to menu"); continue
                }
            }
            Write-Log "Network staging folder accepted: $gamesInstallFolder"
        }
        try {
            $zipBytes = Get-TpmZipSourceByteTotal -ZipSource $zipSource
            if (-not $zipBytes) { $zipBytes = 0 }
            $root      = [System.IO.Path]::GetPathRoot([System.IO.Path]::GetFullPath($gamesInstallFolder))
            $drive     = New-Object System.IO.DriveInfo($root)
            $freeBytes = $drive.AvailableFreeSpace
            Write-Host ("  Staging drive {0} free: {1} GB; ZIPs total ~{2} GB (need ~{3} GB extracted)." -f `
                $root, [Math]::Round($freeBytes/1GB,1), [Math]::Round($zipBytes/1GB,1), [Math]::Round(($zipBytes*1.5)/1GB,1)) -ForegroundColor DarkCyan
            if ($freeBytes -lt ($zipBytes * 1.5)) {
                if ($Unattended) {
                    Write-Host "  WARNING: free space on the staging drive may be insufficient." -ForegroundColor Yellow
                    Write-Host "  [Unattended] Continuing despite low free space." -ForegroundColor Yellow
                    Write-Log "Unattended: low disk space warning -- continuing."
                } else {
                    # The numbers above cover the WHOLE ZIP folder. The user may only pick a few games next, and each game
                    # is checked for space again right before it is extracted, so low space here must not stop the run.
                    Write-Host ""
                    Write-Host "  Heads-up: all the ZIPs together are bigger than your free space." -ForegroundColor Yellow
                    Write-Host "  That is OK. You do not have to extract everything at once." -ForegroundColor Yellow
                    Write-Host "  On the next screen, pick only some games (for example 20)." -ForegroundColor Yellow
                    Write-Host "  Run AutoSync again later for more, after you free up space." -ForegroundColor Yellow
                    Write-Host "  If space runs out, that game is skipped and nothing is changed for it." -ForegroundColor DarkCyan
                    Write-Log "AutoSync: all ZIPs together are bigger than free space; continuing to the game picker so fewer games can be chosen."
                }
            }
            Write-Log "Space check: free=$([Math]::Round($freeBytes/1GB,1))GB zips=$([Math]::Round($zipBytes/1GB,1))GB"
        } catch { Write-Log "Space check skipped: $_" }

        if (Test-IsNetworkPath $zipSource -Drives $autoSyncDriveInfo) {
            Write-Host ""
            Write-Host "Your game ZIP folder is on a network drive: $zipSource" -ForegroundColor Yellow
            Write-Host "Checking how fast it can be read..." -ForegroundColor Cyan
            $mbps = Measure-PathThroughput $zipSource
            if ($mbps) {
                if     ($mbps -ge 500) { $rating = "Excellent" }
                elseif ($mbps -ge 250) { $rating = "Good"      }
                elseif ($mbps -ge 150) { $rating = "Adequate"  }
                else                   { $rating = "Poor"       }
                Write-Host "  Read speed : $mbps MB/s  [$rating]" -ForegroundColor Cyan
                Write-Host "  (This only affects how long extraction takes. Games are" -ForegroundColor DarkCyan
                Write-Host "   played from your games folder, not from this ZIP folder.)" -ForegroundColor DarkCyan
                Write-Log "NAS benchmark: $mbps MB/s ($rating)"
            } else {
                Write-Host "  Speed check skipped (no ZIPs found yet, or they could not be read)." -ForegroundColor DarkCyan
            }
        }
    } else {
        # Register only never creates the staging folder (an empty new folder
        # has nothing to register). Explain and offer to choose an existing one.
        $registerFolderReady = $true
        while (-not (Test-Path -LiteralPath $gamesInstallFolder -PathType Container)) {
            Write-Host ""; Write-Host "The games folder TeknoParrot Manager recommended does not exist yet."
            Write-Host "  Register only registers games that are already in this folder; it does not create it." -ForegroundColor Yellow
            Write-Host "  AutoSync creates the folder the first time it extracts a game." -ForegroundColor DarkCyan
            Write-Log "ERROR: install folder not found."
            if ($Unattended) { $registerFolderReady = $false; break }
            Write-Host ""; Write-Host "    R) Choose an existing games folder" -ForegroundColor Cyan
            Write-Host "    Q) Return to menu" -ForegroundColor Cyan
            $fix = Read-TpmChoice -Prompt "  Choice" -Choices @('R', 'Q')
            if ($fix -ne 'R') { $registerFolderReady = $false; break }
            $gamesInstallFolder = Read-TpmStagingFolder -RecommendedPath '' `
                -TeknoParrotRoot $tpRoot -ZipSource $zipSource `
                -ZipSourceSupplementary $zipSourceSupplementary -ProgramDirectory $PSScriptRoot
            if (Test-Path -LiteralPath $gamesInstallFolder -PathType Container) {
                if (Save-Config) { Write-Log "Config: staging folder updated to $gamesInstallFolder for Register only" }
            }
        }
        if (-not $registerFolderReady) {
            if (-not $Unattended) { [void](Read-HostSafe "  Press Enter to return to menu") }; continue
        }
    }

    Write-Log "Mode=$mode install=$gamesInstallFolder"


    # Creating the destination is itself a write. Keep it after the preview
    # decision so Preview/Dry Run never creates a staging directory.
    if ($mode -eq "AutoSync" -and -not $dryRunActive -and
        -not (Test-Path -LiteralPath $gamesInstallFolder)) {
        try {
            [void][System.IO.Directory]::CreateDirectory($gamesInstallFolder)
            Write-Host "Created staging folder: $gamesInstallFolder" -ForegroundColor Green
        } catch {
            Write-Host ""; Write-Host "ERROR: Could not create staging folder: $_" -ForegroundColor Red
            Write-Log "ERROR: Could not create staging folder -- $_"; if (-not $Unattended) { [void](Read-HostSafe "  Press Enter to return to menu") }; continue
        }
    }

    $backupRoot = Join-Path $userProfilesDir "FullBackup"
    $timestamp  = (Get-Date).ToUniversalTime().ToString("yyyy-MM-dd_HH-mm-ss_fff", [System.Globalization.CultureInfo]::InvariantCulture)
    # Built under an INCOMPLETE_ name; published as a restore choice only after the copy finished.
    $backupFinalPath = Join-Path $backupRoot ('AutoSync_{0}_{1}' -f $timestamp, [guid]::NewGuid().ToString('N').Substring(0,8))
    $backupPath = Get-TpmUserProfilesBackupStagingPath -FinalPath $backupFinalPath

    Write-Host ""
    if ($dryRunActive) {
        Write-Host "PREVIEW -- no backup needed (games and profiles will not be changed)." -ForegroundColor Yellow
    } else {
        Write-Host "Backing up UserProfiles..." -ForegroundColor Cyan

        # A backup failure blocks the entire destructive AutoSync operation.
        # Do not offer an interactive or unattended override:
        # extracting games without a complete restore point violates the
        # backup-before-destructive-work invariant.
        try {
            [void][System.IO.Directory]::CreateDirectory($backupRoot)
            [void][System.IO.Directory]::CreateDirectory($backupPath)
        } catch {
            Write-Host "  ERROR: Could not create backup folder: $_" -ForegroundColor Red
            Write-Host "  The script will not continue without a successful backup." -ForegroundColor Red
            Write-Log "Backup FAILED: could not create backup folder -- $_"
            if (-not $Unattended) { [void](Read-HostSafe '  Press Enter to return to menu') }
            continue
        }

        # The helper preserves the legacy top-level recursive copy and reports
        # one known-total progress item per UserProfiles entry.
        try {
            $profileBackupResult = Invoke-TpmProgressGroup -Title 'AutoSync UserProfiles backup' -Action { Copy-TpmAutoSyncUserProfilesBackup -UserProfilesDir $userProfilesDir -BackupPath $backupPath }
            if ($null -eq $profileBackupResult -or -not [bool]$profileBackupResult.Succeeded) { throw 'The profile backup did not return a successful result.' }
            $backupPath = Complete-TpmAutoSyncUserProfilesBackup -UserProfilesDir $userProfilesDir -StagingPath $backupPath -FinalPath $backupFinalPath
        } catch {
            Write-Host "  ERROR: UserProfiles backup failed: $_" -ForegroundColor Red
            Write-Host "  The script will not continue without a complete backup." -ForegroundColor Red
            Write-Log "Backup FAILED: profile copy did not complete; the incomplete folder (never offered for restore) is $backupPath -- $_"
            if (-not $Unattended) { [void](Read-HostSafe '  Press Enter to return to menu') }
            continue
        }
        if ([bool]$profileBackupResult.NoOp) {
            Write-Host "No UserProfiles entries were present to back up; empty backup directory: $backupPath" -ForegroundColor DarkGray
            Write-Log "Backup not needed: no UserProfiles entries were available; empty folder at $backupPath"
        } else {
            Write-Host "Backup saved to: $backupPath" -ForegroundColor Green
            Write-Log "Backup created at $backupPath"
        }
    }

# =============================================================================
# SECTION 6 -- AutoSync: game selection and extraction
# =============================================================================

if ($mode -eq "AutoSync") {
    Write-Host ""
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Write-Host " AutoSync: Extracting Games" -ForegroundColor Cyan
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Write-Host " New and changed games are extracted; unchanged games skipped." -ForegroundColor DarkCyan
    Write-Host " Local games are never deleted automatically." -ForegroundColor DarkCyan
    if ($retroBat) { Write-Host " RetroBat mode: folders extracted as GameName.teknoparrot" -ForegroundColor Cyan }
    Write-Host ""

    # Pre-validate the supplementary source now so we can decide whether to use the
    # combined picker. If invalid, errors are shown here before the picker runs.
    $onlySyncListSupp = $null
    $suppValid        = $false
    if ($zipSourceSupplementary) {
        if (-not (Test-Path -LiteralPath $zipSourceSupplementary)) {
            Write-Host "  WARNING: Supplementary ZIP folder not found: $zipSourceSupplementary -- skipped." -ForegroundColor Yellow
            Write-Log "AutoSync: supplementary ZIP source not found -- skipped."
        } elseif ((Test-PathInside $gamesInstallFolder $zipSourceSupplementary) -or
                  (Test-PathInside $zipSourceSupplementary $gamesInstallFolder)) {
            Write-Host "  ERROR: Supplementary ZIP folder overlaps the staging folder -- skipped." -ForegroundColor Red
            Write-Log "AutoSync: supplementary ZIP source overlaps staging folder -- skipped."
        } elseif (Test-PathInside $zipSourceSupplementary $tpRoot) {
            Write-Host "  ERROR: Supplementary ZIP folder is inside the TeknoParrot folder -- skipped." -ForegroundColor Red
            Write-Log "AutoSync: supplementary ZIP source is inside TeknoParrot root -- skipped."
        } else {
            $suppValid = $true
        }
    }

    # FIX110 (S-11): the real run that follows a preview uses what the preview used (Main and Supplementary choice together,
    # and the Health Check repair scope). Every other run starts from the overrides whitelist and asks again, so a choice made
    # in an earlier run never silently decides this one.
    if ($autoSyncSelection) {
        $onlySyncList = $autoSyncSelection.Main
        $onlySyncListSupp = if ($suppValid) { $autoSyncSelection.Supp } else { $null }
        Write-Log 'AutoSync: the real run uses the game selection of the preview.'
    } else {
        $onlySyncList = $configuredOnlySyncList
    }

    # Picker return conventions (also used by overrides and unattended paths):
    #   $null   = skip this source entirely (nothing left to extract, or D pressed with nothing selected)
    #   @(...)  = whitelist; extract only the named games (A and unattended runs: every unextracted game)
    #   @()     = no filter; only the Health Check repair scope and the overrides default use it
    #
    # If onlySync is already populated from the overrides file, use it directly.
    # Otherwise run the interactive picker. When the supplementary source is valid,
    # both libraries are presented in a single combined list (Select-GamesInteractiveCombined).
    $combinedPickerRan = $false
    if ($null -ne $autoSyncTargetGames -and @($autoSyncTargetGames).Count -gt 0) {
        $onlySyncList = @()
        $onlySyncListSupp = if ($suppValid) { @() } else { $null }
        Write-Host ("  Health Check repair scope: affected profile codes only ({0})." -f (@($autoSyncTargetGames) -join ', ')) -ForegroundColor Cyan
        Write-Log "AutoSync: Health Check re-entry restricted to affected profile codes."
    }
    $scopedHealthRepair = ($null -ne $autoSyncTargetGames -and @($autoSyncTargetGames).Count -gt 0)
    if ($onlySyncList.Count -eq 0 -and -not $scopedHealthRepair -and -not $autoSyncSelection) {
        if ($Unattended) {
            Write-Host "  [Unattended] Game selection: all unextracted games." -ForegroundColor DarkCyan
            Write-Log "Unattended: game selection = all unextracted."
        }
        if ($suppValid) {
            # Combined picker: both collection and supplementary shown in one sorted list.
            $combined          = Select-GamesInteractiveCombined -zipSourceMain $zipSource `
                                     -zipSourceSupp $zipSourceSupplementary -installFolder $gamesInstallFolder `
                                     -datIndex $datIndex -userProfilesDir $userProfilesDir -SelectAll:$Unattended
            $onlySyncList      = $combined.Main
            $onlySyncListSupp  = $combined.Supp
            $combinedPickerRan = $true
        } else {
            $onlySyncList = Select-GamesInteractive -zipSource $zipSource -installFolder $gamesInstallFolder -datIndex $datIndex -userProfilesDir $userProfilesDir -SelectAll:$Unattended
            # $null means nothing to extract or D with nothing selected -- leave as $null (skip).
            # Otherwise the explicit list of games to extract.
        }
    }
    # When the combined picker did not run (overrides pre-set the main list), the supplementary folder follows the same
    # onlySync list: only the listed ZIPs are extracted there too. An empty list means no filter (all supplementary ZIPs).
    # When the picker ran, $onlySyncListSupp is already set by the picker ($null = skip, @(...) = the games to extract).
    if ($suppValid -and -not $combinedPickerRan -and -not $autoSyncSelection -and $null -eq $onlySyncListSupp) {
        $onlySyncListSupp = @($onlySyncList)
    }

    $syncStatePath = Join-Path $gamesInstallFolder "TeknoParrot-Manager.syncstate.json"

    # An existing but unreadable sync-state file is never silently replaced
    # by a partial fresh ledger. Ask before any progress display starts;
    # unattended runs and previews do not prompt and Invoke-AutoSync stops
    # them before any change.
    $autoSyncRebuildInvalidState = $false
    $autoSyncInvalidStateCopy = ''
    $autoSyncStateCheck = Test-TpmAutoSyncStateFile -Path $syncStatePath
    if ($autoSyncStateCheck.Status -eq 'Invalid' -and -not $Unattended -and -not $dryRunActive) {
        Write-Host ""
        Write-Host "  The AutoSync sync-state file exists but could not be loaded:" -ForegroundColor Yellow
        Write-Host "    $syncStatePath" -ForegroundColor White
        Write-Host "    $($autoSyncStateCheck.Reason)" -ForegroundColor DarkGray
        Write-Host "  It records which game ZIPs were already extracted. Choose what to do:" -ForegroundColor Yellow
        Write-Host "    [K] Keep the file unchanged and stop AutoSync now (default)" -ForegroundColor White
        Write-Host "    [R] Rebuild it: TeknoParrot Manager first saves an exact copy of the current" -ForegroundColor White
        Write-Host "        file next to it, then starts a new sync state; games extracted before" -ForegroundColor White
        Write-Host "        may be re-checked" -ForegroundColor White
        $stateChoice = Read-TpmChoice -Prompt '  Choice [K/R]' -Choices @('K', 'R') -Default 'K'
        if ($stateChoice -eq 'R') {
            try {
                $autoSyncInvalidStateCopy = Save-TpmInvalidAutoSyncStateCopy -Path $syncStatePath
                $autoSyncRebuildInvalidState = $true
                Write-Host "  Saved an exact copy of the original file: $autoSyncInvalidStateCopy" -ForegroundColor Green
                Write-Log "AutoSync: owner chose to rebuild invalid sync state; original preserved at $autoSyncInvalidStateCopy."
            } catch {
                Write-Host "  Could not save a verified copy of the original file, so it will not be rebuilt. Nothing was changed." -ForegroundColor Red
                Write-Log "AutoSync: invalid sync-state preservation failed -- $($_.Exception.Message)"
            }
        } else {
            Write-Log "AutoSync: owner kept the invalid sync-state file; AutoSync will stop before any change."
        }
    }

    $syncGroup = $null
    $sync = $null
    if ($null -ne $onlySyncList) {
        $syncGroup = Invoke-TpmProgressGroup -Title 'AutoSync extraction' -Action {
            $autoSyncRun = Invoke-AutoSync -zipSource $zipSource -installFolder $gamesInstallFolder `
                    -syncStatePath $syncStatePath -noSync $noSyncList -onlySync $onlySyncList -OnlyProfileCodes ([string[]]$autoSyncTargetGames) -retroBat $retroBat -DryRun $dryRunActive `
                    -datIndex $datIndex -userProfilesDir $userProfilesDir `
                    -RebuildInvalidState $autoSyncRebuildInvalidState -InvalidStatePreservedCopy $autoSyncInvalidStateCopy
            # Failed extractions close the bar as Error, not Final.
            $syncOutcome = if ($null -eq $autoSyncRun -or [int]$autoSyncRun.Failed -gt 0 -or [int]$autoSyncRun.UnsafePathSkipped -gt 0 -or [bool]$autoSyncRun.EvidenceRefused -or [bool]$autoSyncRun.EvidenceStopped) { 'ACTION_REQUIRED' } elseif ([int]$autoSyncRun.Synced -gt 0 -or ($dryRunActive -and [int]$autoSyncRun.WouldSync -gt 0)) { 'SUCCEEDED' } else { 'NO_OP' }
            [pscustomobject]@{ Outcome = $syncOutcome; Succeeded = ($null -ne $autoSyncRun -and [int]$autoSyncRun.Failed -eq 0 -and [int]$autoSyncRun.UnsafePathSkipped -eq 0 -and -not [bool]$autoSyncRun.EvidenceRefused -and -not [bool]$autoSyncRun.EvidenceStopped); Result = $autoSyncRun }
        }
        $sync = $syncGroup.Result
    } else {
        Write-Host "  No games selected -- skipping main extraction." -ForegroundColor Yellow
        Write-Log "AutoSync: main extraction skipped -- no games selected."
    }

    # Supplementary extraction pass -- selection was already resolved above.
    $suppGroup = $null
    $syncSupp = $null
    if ($suppValid) {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " AutoSync: Supplementary Games" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Supplementary source: $zipSourceSupplementary" -ForegroundColor DarkCyan
        Write-Host ""
        if ($null -ne $onlySyncListSupp) {
            if ($Unattended) {
                Write-Host "  [Unattended] Game selection: all unextracted supplementary games." -ForegroundColor DarkCyan
                Write-Log "Unattended: supplementary game selection = all."
            }
            $suppGroup = Invoke-TpmProgressGroup -Title 'AutoSync supplementary extraction' -Action {
                $suppRun = Invoke-AutoSync -zipSource $zipSourceSupplementary -installFolder $gamesInstallFolder `
                            -syncStatePath $syncStatePath -noSync $noSyncList -onlySync $onlySyncListSupp -OnlyProfileCodes ([string[]]$autoSyncTargetGames) -retroBat $retroBat -DryRun $dryRunActive `
                            -datIndex $datIndex -userProfilesDir $userProfilesDir `
                            -RebuildInvalidState $autoSyncRebuildInvalidState -InvalidStatePreservedCopy $autoSyncInvalidStateCopy
                # Failed extractions close the bar as Error, not Final.
                $suppOutcome = if ($null -eq $suppRun -or [int]$suppRun.Failed -gt 0 -or [int]$suppRun.UnsafePathSkipped -gt 0 -or [bool]$suppRun.EvidenceRefused -or [bool]$suppRun.EvidenceStopped) { 'ACTION_REQUIRED' } elseif ([int]$suppRun.Synced -gt 0 -or ($dryRunActive -and [int]$suppRun.WouldSync -gt 0)) { 'SUCCEEDED' } else { 'NO_OP' }
                [pscustomobject]@{ Outcome = $suppOutcome; Succeeded = ($null -ne $suppRun -and [int]$suppRun.Failed -eq 0 -and [int]$suppRun.UnsafePathSkipped -eq 0 -and -not [bool]$suppRun.EvidenceRefused -and -not [bool]$suppRun.EvidenceStopped); Result = $suppRun }
            }
            $syncSupp = $suppGroup.Result
        } else {
            Write-Host "  No supplementary games selected -- skipping." -ForegroundColor Yellow
            Write-Log "AutoSync: supplementary extraction skipped -- no games selected."
        }
    }

    Write-Host ""
    Write-Host "Extraction summary:" -ForegroundColor Green
    if ($sync -and $syncSupp) { Write-Host "  Collection:" -ForegroundColor Cyan }
    if ($sync) {
        Write-Host "  Extracted  : $($sync.Synced)"   -ForegroundColor Green
        Write-Host "  Up to date : $($sync.UpToDate)"  -ForegroundColor DarkGray
        if ($sync.WouldSync -gt 0) { Write-Host "  Would extract : $($sync.WouldSync)  (preview -- nothing written yet)" -ForegroundColor Yellow }
        if ($sync.Skipped -gt 0) { Write-Host "  Skipped    : $($sync.Skipped)  (filtered or refused; see per-item messages)" -ForegroundColor DarkGray }
        if ([int]$sync.UnsafePathSkipped -gt 0) { Write-Host "  Unsafe path refusals : $($sync.UnsafePathSkipped)  (affected ZIPs refused before extraction)" -ForegroundColor Red }
        if ($sync.Failed -gt 0) { Write-Host "  Failed     : $($sync.Failed)  (see TeknoParrot-Manager.log)" -ForegroundColor Red }
    } elseif ($null -ne $syncGroup) {
        Write-Host "  Collection : result unavailable; see TeknoParrot-Manager.log" -ForegroundColor Red
    } else {
        Write-Host "  Collection : skipped (no games selected)" -ForegroundColor DarkGray
    }
    if ($syncSupp) {
        Write-Host "  Supplementary:" -ForegroundColor Cyan
        Write-Host "  Extracted  : $($syncSupp.Synced)"   -ForegroundColor Green
        Write-Host "  Up to date : $($syncSupp.UpToDate)"  -ForegroundColor DarkGray
        if ($syncSupp.WouldSync -gt 0) { Write-Host "  Would extract : $($syncSupp.WouldSync)  (preview -- nothing written yet)" -ForegroundColor Yellow }
        if ($syncSupp.Skipped -gt 0) { Write-Host "  Skipped    : $($syncSupp.Skipped)  (filtered or refused; see per-item messages)" -ForegroundColor DarkGray }
        if ([int]$syncSupp.UnsafePathSkipped -gt 0) { Write-Host "  Unsafe path refusals : $($syncSupp.UnsafePathSkipped)  (affected ZIPs refused before extraction)" -ForegroundColor Red }
        if ($syncSupp.Failed -gt 0) { Write-Host "  Failed     : $($syncSupp.Failed)  (see TeknoParrot-Manager.log)" -ForegroundColor Red }
    } elseif ($null -ne $suppGroup) {
        Write-Host "  Supplementary: result unavailable; see TeknoParrot-Manager.log" -ForegroundColor Red
    } elseif ($suppValid) {
        Write-Host "  Supplementary: skipped (no games selected)" -ForegroundColor DarkGray
    }
}

# =============================================================================
# SECTION 7 -- Build profile index from GameProfiles
# =============================================================================

$registrationFolders = @()
if ($sync -and $sync.SyncedNames) { $registrationFolders += @($sync.SyncedNames) }
if ($syncSupp -and $syncSupp.SyncedNames) { $registrationFolders += @($syncSupp.SyncedNames) }
# Only an AutoSync operation may suppress its own post-sync registration scan.
# A later RegisterOnly menu action must not inherit stale AutoSync refusal state.
$skipAutoSyncRegistration = [bool]($mode -eq 'AutoSync' -and $registrationFolders.Count -eq 0)
Write-Host ""
if ($registrationFolders.Count -gt 0) {
    Write-Host "Checking your TeknoParrot folder so the new game is registered correctly." -ForegroundColor Cyan
    Write-Host "This checks the selected new game folder; only changed or new games will be written." -ForegroundColor DarkCyan
    Write-Log "Registration check: checking selected new game folders; only changed or new games will be written."
} elseif ($skipAutoSyncRegistration -and $dryRunActive) {
    Write-Host 'Preview: registration is checked after a real AutoSync run has extracted and checked the game folders.' -ForegroundColor Yellow
    Write-Log 'Registration scan skipped in preview: AutoSync preview extracts nothing, so there are no verified registration targets.'
} elseif ($skipAutoSyncRegistration) {
    Write-Host 'Nothing new was extracted, so registration was skipped.' -ForegroundColor DarkCyan
    Write-Host 'To register games already extracted, choose Register only.' -ForegroundColor DarkCyan
    Write-Log 'Registration scan skipped: no verified AutoSync registration targets; existing-only fallback refused.'
} else {
    Write-Host "Checking existing TeknoParrot games for registration changes." -ForegroundColor Cyan
    Write-Host "Only changed or new games will be written." -ForegroundColor DarkCyan
}
Write-Host ""
Write-Host "Indexing TeknoParrot game profiles..." -ForegroundColor Cyan
$profileIndex = Build-ProfileIndex $gameProfilesDir
Write-Host "  Indexed $($profileIndex.Keys.Count) executable names across the profile set." -ForegroundColor DarkCyan
Write-Log "Profile index built: $($profileIndex.Keys.Count) executable keys."

if ($profileIndex.Keys.Count -eq 0) {
    Write-Host ""
    Write-Host "ERROR: No usable profiles found in GameProfiles." -ForegroundColor Red
    Write-Host "Check that this is the folder where the TeknoParrot installer put TeknoParrotUi.exe. Its GameProfiles come with TeknoParrotUI: install it with the official TeknoParrot installer (TeknoParrotUI [REQUIRED], Download Selected), then retry." -ForegroundColor Yellow
    Write-Log "ERROR: empty profile index."
    [void](Close-TpmRegistrationLedgerOperations -Reason 'PROFILE_INDEX_EMPTY')
    [void](Read-HostSafe "  Press Enter to return to menu")
    continue
}

# =============================================================================
# SECTION 8 -- Register games
# =============================================================================

Write-Host ""
Write-Host "--------------------------------------------" -ForegroundColor Cyan
Write-Host " Registering Games" -ForegroundColor Cyan
Write-Host "--------------------------------------------" -ForegroundColor Cyan
Write-Host " Scanning: $gamesInstallFolder" -ForegroundColor DarkCyan
Write-Host ""

if ($skipAutoSyncRegistration) {
    if ($dryRunActive) {
        # A preview never extracts anything, so there is nothing to register and nothing for the user to act on.
        $result = New-TpmProfileTransactionResult -WorkflowKey 'GameRegistration' -OperationKey 'RegisterProfiles' -Outcome 'NO_OP' -ProductState 'UNCHANGED' -Summary 'Preview: registration is checked after a real AutoSync run. Nothing was changed.' -ReasonCode 'PREVIEW_NO_REGISTRATION' -FinalChecks @('A preview does not register games.')
        $ledgerCloseReason = 'PREVIEW_NO_REGISTRATION'
    } else {
        $result = New-TpmProfileTransactionResult -WorkflowKey 'GameRegistration' -OperationKey 'RegisterProfiles' -Outcome 'NO_OP' -ProductState 'UNCHANGED' -Summary 'Nothing new was extracted, so registration was skipped. To register games already extracted, choose Register only.' -ReasonCode 'NEW_REGISTRATION_TARGETS_UNVERIFIED' -FinalChecks @('No replacement existing-only registration scan was performed.')
        $ledgerCloseReason = 'NEW_REGISTRATION_TARGETS_UNVERIFIED'
    }
    foreach ($name in @('Registered','Already','Ambiguous','Unmatched')) { $result | Add-Member -NotePropertyName $name -NotePropertyValue @() -Force }
    [void](Close-TpmRegistrationLedgerOperations -Reason $ledgerCloseReason)
} else {
    $result = Invoke-TpmProgressGroup -Title 'Register games' -Action { Register-Games -userProfilesDir $userProfilesDir -installFolder $gamesInstallFolder -profileIndex $profileIndex -gameProfilesDir $gameProfilesDir -datIndex $datIndex -profileSet $profileSet -DryRun $dryRunActive -tpRootDir $tpRoot -subFolderMap $subFolderMap -GameFolders $registrationFolders }
}
Write-TpmUnavailableDriveSummary

foreach ($r in $result.Registered) {
    if ($dryRunActive) { Write-Host ('  [Preview] Would register: ' + $r.Code) -ForegroundColor DarkCyan; continue }
    if ($r.DatMatch) {
        Write-Host ("  Registered (dat)       : {0}" -f $r.Code) -ForegroundColor Green
    } elseif ($r.FuzzyScore) {
        Write-Host ("  Registered (fuzzy {0}) : {1}" -f $r.FuzzyScore, $r.Code) -ForegroundColor Cyan
        Write-Host ("               folder  : {0}" -f $r.FuzzyFolder) -ForegroundColor DarkGray
    } elseif ($r.SubFolderMatch) {
        Write-Host ("  Registered (tp-root)   : {0}" -f $r.Code) -ForegroundColor Green
    } else {
        Write-Host ("  Registered             : {0}" -f $r.Code) -ForegroundColor Green
    }
    Write-Host "               $($r.GamePath)" -ForegroundColor DarkGray
}
if ($result.Already.Count -gt 0) {
    Write-Host ("  Existing profile files: {0}. Their saved mappings are not exact selected-game verification; see the registration result for any backfill changes." -f $result.Already.Count) -ForegroundColor DarkGray
}

# Collect unique game folders that need manual registration, keeping the most
# useful executable per folder (fewest profile matches = most specific hint).
# Multiple ambiguous files in the same folder collapse to one entry.
$manualRegData = @{}   # folderName -> @{ ExeName; ProfileCount; Profiles }
if ($result.Ambiguous.Count -gt 0) {
    $installBase = $gamesInstallFolder.TrimEnd('\')
    foreach ($amb in $result.Ambiguous) {
        $rel        = if ($amb.Exe.Length -gt $installBase.Length) { $amb.Exe.Substring($installBase.Length).TrimStart('\') } else { $amb.Exe }
        $folderName = $rel.Split('\')[0]
        $exeName    = [System.IO.Path]::GetFileName($amb.Exe)
        $count      = @($amb.Codes.Split(',')).Count
        if (-not $manualRegData.ContainsKey($folderName) -or $count -lt $manualRegData[$folderName].ProfileCount) {
            $manualRegData[$folderName] = @{
                Exe          = $amb.Exe
                ExeName      = $exeName
                ProfileCount = $count
                Profiles     = $amb.Codes
                BestGuess    = $amb.BestGuess
                BestScore    = $amb.BestScore
                Reason       = $amb.Reason
                ClaimedBy    = $amb.ClaimedBy
            }
        }
    }
}

# Duplicate profile codes (Reason="duplicate": exactly one profile code,
# contested by exactly one other folder) are resolvable in-script -- unlike
# "shared" conflicts (one exe name maps to several different games' profile
# codes), there's no ambiguity about WHICH profile is in play, only which
# folder it should point at. Offer to fix these now instead of sending the
# user to TeknoParrotUI for something this script can do directly.
$duplicateConflicts = @($manualRegData.GetEnumerator() | Where-Object { $_.Value.Reason -eq "duplicate" })
if ($duplicateConflicts.Count -gt 0 -and $dryRunActive) {
    Write-Host ("  [Preview] {0} duplicate profile conflict(s) found (one profile code claimed by two folders). Nothing is written in preview; run registration for real to choose which folder keeps each profile." -f $duplicateConflicts.Count) -ForegroundColor DarkCyan
} elseif ($duplicateConflicts.Count -gt 0 -and -not $Unattended) {
    Write-Host ""
    Write-Host ("  {0} duplicate profile conflict(s) found (one profile code claimed by two folders)." -f $duplicateConflicts.Count) -ForegroundColor Yellow
    Write-Host "  Tip: using the latest DAT can resolve these. Download it when AutoSync offers it, then register again." -ForegroundColor DarkCyan
    $resolveChoice = Read-TpmYesNo -Prompt "  Resolve them now by picking which folder keeps the profile? (Y/N)"
    if ($resolveChoice -eq "Y") {
        $dupLedger = $null
        if (-not $dryRunActive -and (Test-TpmRegistrationLedgerConfigured)) {
            $dupLedger = Open-TpmRegistrationLedgerOperation -Mode ManualChoice -Units @($duplicateConflicts | ForEach-Object { [pscustomobject]@{ Folder = [string]$_.Key } }) -InstallRoot $gamesInstallFolder
            if (-not $dupLedger.Opened) {
                Write-Host ('  ' + $dupLedger.Message) -ForegroundColor Red
                Write-Log ('Duplicate resolution refused before any write: ' + $dupLedger.Message)
                $duplicateConflicts = @()
            }
        }
        foreach ($entry in $duplicateConflicts) {
            $folderName = $entry.Key
            $info       = $entry.Value
            $code       = $info.Profiles   # single code for a "duplicate" entry
            $userProfilePath = Join-Path $userProfilesDir ($code + ".xml")
            $currentExe = $null
            try {
                $curDoc = Read-Xml $userProfilePath
                $curGp  = $curDoc.GameProfile.SelectSingleNode("GamePath")
                if ($curGp) { $currentExe = $curGp.InnerText.Trim() }
            } catch {
                Write-Log "Duplicate resolution: could not read current GamePath for $code -- $_"
            }
            Write-Host ""
            Write-Host ("  Profile          : {0}" -f $code) -ForegroundColor Yellow
            Write-Host ("  Currently set to : {0}" -f $currentExe) -ForegroundColor DarkGray
            Write-Host ("  Conflicting copy : {0}" -f $info.Exe) -ForegroundColor DarkGray
            $pick = Read-TpmChoice -Prompt "  [K]eep current / [S]witch to conflicting copy / [Q]uit resolving" -Choices @('K', 'S', 'Q')
            if ($pick -eq 'Q') {
                [void]$result.TechnicalDetails.Decisions.Add([pscustomobject]@{ Game=$folderName; Code=$code; Outcome='SKIPPED'; Reason='USER_QUIT_DUPLICATE_RESOLUTION'; WriteAttempted=$false })
                break
            }
            if ($pick -eq "S") {
                $switchWriteAttempted = $false; $ledgerMapping = $null; $preWriteState = $null
                $switchVerified = $false
                try {
                    if (-not $dryRunActive) {
                        # Same lazily created registration safety backup as Register-Games.
                        $switchBackupState = Get-TpmTransactionField -Object $result.TechnicalDetails -Name 'SafetyBackupState'
                        if (-not ($switchBackupState -is [hashtable])) { throw 'A verified profile backup is required before switching registration.' }
                        [void](Confirm-TpmRegistrationSafetyBackup -State $switchBackupState -UserProfilesDir $userProfilesDir)
                    }
                    $switchRoot = [System.IO.Path]::GetFullPath($gamesInstallFolder).TrimEnd('\')
                    $switchExe = [System.IO.Path]::GetFullPath($info.Exe)
                    if (-not (Test-PathInside $switchExe $switchRoot) -or -not (Test-Path -LiteralPath $switchExe -PathType Leaf) -or
                        -not (Test-BepInExNoReparsePath -Root $switchRoot -Path $switchExe)) { throw 'The conflicting executable could not be safely verified.' }
                    $swDoc = Read-Xml $userProfilePath
                    $swGp  = $swDoc.GameProfile.SelectSingleNode("GamePath")
                    if ($null -eq $swGp) {
                        $swGp = $swDoc.CreateElement("GamePath")
                        [void]$swDoc.GameProfile.PrependChild($swGp)
                    }
                    $swGp.InnerText = $info.Exe
                    $ledgerMapping = Start-TpmRegistrationMapping -Folder $folderName -Code $code -Match 'duplicate-switch' -IntendedPath $info.Exe -TemplatePath '' -DryRun $dryRunActive
                    [void](Set-SecondaryExecutablePath $swDoc $info.Exe -ProfileCode $code)
                    if (-not $dryRunActive) { $preWriteState = Get-TpmProfileWriteFingerprint -Path $userProfilePath }
                    $switchWriteAttempted = -not $dryRunActive
                    Save-XmlMaybe $swDoc $userProfilePath $dryRunActive
                    if (-not $dryRunActive) {
                        Assert-TpmRegisteredGamePath -ProfilePath $userProfilePath -ExpectedGamePath $info.Exe -RegistrationState $result.TechnicalDetails.MutationRecords
                        Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome VERIFIED
                        $switchVerified = $true
                        if ($result.TechnicalDetails.MutationRecords.Changed -notcontains $code) { [void]$result.TechnicalDetails.MutationRecords.Changed.Add($code) }
                        $resolvedFolder = (Join-Path $switchRoot $folderName).TrimEnd('\')
                        $result.TechnicalDetails.Ambiguous = @($result.TechnicalDetails.Ambiguous | Where-Object {
                            $candidateExe = [string]$_.Exe
                            $candidateExe -ine $resolvedFolder -and -not $candidateExe.StartsWith($resolvedFolder + '\', [System.StringComparison]::OrdinalIgnoreCase)
                        })
                        $resolvedKey = $folderName -replace '\.(teknoparrot|parrot|game)$', ''
                        $result.TechnicalDetails.Unmatched = @($result.TechnicalDetails.Unmatched | Where-Object { $_ -ine $folderName -and $_ -ine $resolvedKey })
                        foreach ($priorDecision in @($result.TechnicalDetails.Decisions | Where-Object { $_.Game -ieq $folderName })) {
                            $priorDecision | Add-Member -NotePropertyName ResolvedByVerifiedMapping -NotePropertyValue $true -Force
                        }
                    }
                    if (-not $dryRunActive) {
                        foreach ($registeredEntry in @($result.TechnicalDetails.Registered | Where-Object { $_.Code -ieq $code })) { $registeredEntry.GamePath = $info.Exe }
                    }
                    $manualRegData.Remove($folderName)
                    $switchMsg = if ($dryRunActive) { "[Preview] Would switch." } else { "Switched." }
                    Write-Host "  $switchMsg" -ForegroundColor $(if ($dryRunActive) { "DarkCyan" } else { "Green" })
                    Write-Log "Duplicate resolution: $code switched to $($info.Exe) (was $currentExe)"
                } catch {
                    $saveFailure = Resolve-TpmRegistrationSaveFailure -WriteAttempted $switchWriteAttempted -PreState $preWriteState -Message $_.Exception.Message
                    Complete-TpmRegistrationMapping -MappingId $ledgerMapping -Outcome FAILED -WriteAttempted $saveFailure.WriteAttempted -Reason $saveFailure.Reason
                    if (-not $switchVerified) {
                        [void]$result.TechnicalDetails.MutationRecords.Failures.Add([pscustomobject]@{ Code=$code; WriteAttempted=$saveFailure.WriteAttempted; Reason='DUPLICATE_SWITCH_NOT_VERIFIED' })
                        Write-Host "  FAILED to switch: $_" -ForegroundColor Red
                        Write-Log "Duplicate resolution FAILED for $code -- $_"
                    } else {
                        Write-Log 'Duplicate resolution: output failed after the saved mapping was verified; the verified registration result was retained.'
                    }
                }
            } else {
                [void]$result.TechnicalDetails.Decisions.Add([pscustomobject]@{ Game=$folderName; Code=$code; Outcome='SKIPPED'; Reason='USER_KEPT_CURRENT'; WriteAttempted=$false })
                Write-Host "  Kept current. Still listed in ACTION REQUIRED." -ForegroundColor DarkGray
            }
        }
        [void](Close-TpmRegistrationLedgerOperations -Reason 'DUPLICATE_RESOLUTION_NOT_COMPLETED')
    }
}
if ($result.TechnicalDetails -and $result.TechnicalDetails.PSObject.Properties['MutationRecords']) {
    $result = ConvertTo-TpmRegistrationResult -Legacy $result.TechnicalDetails -Backup (Get-TpmRegistrationBackupEvidence -Result $result) -DryRun $dryRunActive
}

if ($manualRegData.Count -gt 0 -and -not $Unattended -and -not $dryRunActive) {
    $result = Invoke-ManualRegistrationChoices -ManualRegData $manualRegData -UserProfilesDir $userProfilesDir `
        -GameProfilesDir $gameProfilesDir -InstallFolder $gamesInstallFolder -Result $result -DryRun $dryRunActive
}
Invoke-TpmRegionChoice -Codes @($result.Registered | ForEach-Object { [string]$_.Code } | Select-Object -Unique) -UserProfilesDir $userProfilesDir -Result $result -DryRun $dryRunActive -Unattended:$Unattended
$registrationFollowUp = New-Object System.Collections.Generic.List[string]
if (@($result.PSTypeNames) -contains 'TPM.TransactionResult.v1' -and $result.Outcome -notin @('SUCCEEDED','NO_OP')) {
    $registrationMessage = 'Registration: ' + $result.Summary
    [void]$registrationFollowUp.Add($registrationMessage)
    Write-Host $registrationMessage -ForegroundColor Yellow
    Write-Log $registrationMessage
}
# A ZIP that failed or was refused is never a green run: it goes into the same ACTION REQUIRED list and the recap.
$extractionProblems = 0
$syncStateStopped = $false
$evidenceRefused = $false
$evidenceStopped = $false
foreach ($autoSyncRun in @($sync, $syncSupp)) {
    if ($autoSyncRun) {
        # A refused sync-state file returns Failed=1 for the whole run, and the evidence flags are run-level too: none of them is a ZIP that failed to unpack.
        $runStateStopped = [bool]$autoSyncRun.StateRefused
        if ($runStateStopped) { $syncStateStopped = $true }
        if ([bool]$autoSyncRun.EvidenceRefused) { $evidenceRefused = $true }
        if ([bool]$autoSyncRun.EvidenceStopped) { $evidenceStopped = $true }
        $extractionProblems += [int]$autoSyncRun.Failed - [int]$runStateStopped + [int]$autoSyncRun.UnsafePathSkipped
    }
}
if ($mode -eq 'AutoSync') {
    if ($null -ne $syncGroup -and -not $sync) { $extractionProblems++ }
    if ($null -ne $suppGroup -and -not $syncSupp) { $extractionProblems++ }
}
$runStopMessages = New-Object System.Collections.Generic.List[string]
if ($syncStateStopped) {
    $stateStopText = if ($dryRunActive) { 'AutoSync preview: the sync-state file could not be read, so no preview was made.' } else { 'AutoSync: the sync-state file could not be read, so nothing was unpacked.' }
    [void]$runStopMessages.Add($stateStopText + ' Run AutoSync and choose [R] to rebuild it (a copy of the old file is kept), or put back a good copy of the file. The log has the reason.')
}
if ($evidenceRefused) { [void]$runStopMessages.Add('AutoSync: TeknoParrot Manager could not start its registration record, so nothing was unpacked. The log has the reason.') }
elseif ($evidenceStopped) { [void]$runStopMessages.Add('AutoSync: TeknoParrot Manager could not finish saving its registration record, so some games may not be fully recorded. The log has the reason.') }
$runLevelMessages = New-Object System.Collections.Generic.List[string]
$runLevelMessages.AddRange($runStopMessages)
if ($extractionProblems -gt 0) {
    $unpackMessage = if ($dryRunActive) { 'AutoSync preview: {0} could not be checked, so the preview is incomplete. Open the log to see why, then run the preview again.' } else { 'AutoSync: {0} could not be unpacked, so those games are not set up. Open the log to see why, then run AutoSync again.' }
    [void]$runLevelMessages.Add(($unpackMessage -f (Format-TpmCountNoun -Count $extractionProblems -Singular 'ZIP file')))
}
foreach ($registrationMessage in $runLevelMessages) {
    [void]$registrationFollowUp.Add($registrationMessage)
    Write-Host $registrationMessage -ForegroundColor Yellow
    Write-Log $registrationMessage
}
$actionListNote = if ($dryRunActive) { 'this is a preview, so no list was saved; run it for real to save one' } else { 'see the ACTION REQUIRED list saved below' }
if ($manualRegData.Count -gt 0) {
    Write-Host ""
    Write-Host ("  {0} game(s) still need registration -- {1}." -f $manualRegData.Count, $actionListNote) -ForegroundColor Yellow
}
if ($result.Unmatched.Count -gt 0) {
    Write-Host ("  {0} game folder(s) not matched to a TeknoParrot profile -- {1}." -f $result.Unmatched.Count, $actionListNote) -ForegroundColor Yellow
}

if (-not $dryRunActive -and ($registrationFollowUp.Count -gt 0 -or $manualRegData.Count -gt 0 -or $result.Unmatched.Count -gt 0)) {
    Write-Host '  ACTION REQUIRED: some games need your attention. The list is being saved now, before you go on.' -ForegroundColor Yellow
    $registrationActionPath = [string]$script:TpmOwnedLayout.RegistrationItemsPath
    $registrationReportSaved = Write-TpmActionRequiredReport -ActionPath $registrationActionPath -ManualRegData $manualRegData -Result $result -OnboardingFollowUp $registrationFollowUp.ToArray() -RunId (Get-TpmSessionRunId)
    if (-not $registrationReportSaved) { Write-Host '  Registration followup could not be saved. Keep the result above and review the log before retrying; no durable report was claimed.' -ForegroundColor Yellow }
}
if ($registrationFolders.Count -gt 0 -and -not $dryRunActive) {
    $extractedText = if ($registrationFolders.Count -eq 1) { ('{0} was extracted.' -f [System.IO.Path]::GetFileName($registrationFolders[0])) } else { ('{0} games were extracted.' -f $registrationFolders.Count) }
    Write-Host ""
    $registeredCleanly = ($result.Outcome -in @('SUCCEEDED','NO_OP')) -and $registrationFollowUp.Count -eq 0 -and $manualRegData.Count -eq 0 -and $result.Unmatched.Count -eq 0
    if ($registeredCleanly) {
        $registeredText = if ($registrationFolders.Count -eq 1) { ('{0} was extracted and registered in TeknoParrot.' -f [System.IO.Path]::GetFileName($registrationFolders[0])) } else { ('{0} games were extracted and registered in TeknoParrot.' -f $registrationFolders.Count) }
        Write-Host ("{0} See the Registered lines above." -f $registeredText) -ForegroundColor DarkCyan
    }
    else {
        Write-Host ("{0} That only means the files were unpacked. At least one game still needs your attention. Check the registration result above." -f $extractedText) -ForegroundColor Yellow
    }
    Write-Host "  What should I do next?" -ForegroundColor Cyan
    Write-Host "  [N] New game only (default) -- stop here, skip the rest of your games" -ForegroundColor Cyan
    Write-Host "  [A] Check all games -- also repair your whole library, then set up controls" -ForegroundColor Cyan
    Write-Host "  [B] Back" -ForegroundColor Cyan
    $maintenanceChoice = Read-TpmChoice -Prompt "  Choice (N/A/B)" -Choices @('N', 'A', 'B') -Default 'N'
    if ($maintenanceChoice -eq 'N') {
        Write-Log "AutoSync: one-game maintenance scope = New game only."
        Write-Host "  Only the games extracted in this run were checked. The whole-library checks were skipped." -ForegroundColor Green
        Write-Host ('  Registration result: ' + $result.Summary) -ForegroundColor $(if ($result.Outcome -in @('SUCCEEDED','NO_OP')) { 'DarkGray' } else { 'Yellow' })
        Invoke-TpmLaunchBoxStep
        if (-not $Unattended) { [void](Read-HostSafe "  Press Enter to return to the menu") }
        continue
    }
    if ($maintenanceChoice -eq 'B') {
        Write-Log "AutoSync: maintenance scope selection backed out."
        continue
    }
    Write-Log "AutoSync: maintenance scope = all games."
}


# =============================================================================
# SECTION 9  -- Game repair: fix broken GamePaths
# =============================================================================

Write-Host ""
if ($Unattended) {
    Write-Host "  [Unattended] Running repair." -ForegroundColor DarkCyan
    Write-Log "Unattended: repair = Y."
    $doRepair = "Y"
} else {
    $doRepair = Read-TpmYesNo -Prompt "Check for and repair broken game paths now? (Y/N)"
}
$nf   = @(); $amb2 = @()   # initialize so the final summary can reference them safely
if ($doRepair.Trim().ToUpperInvariant() -eq "Y") {
    Write-Host ""
    Write-Host "Repairing game paths..." -ForegroundColor Cyan
    $repairGroup = Invoke-TpmProgressGroup -Title 'Game path repair' -Action {
        $repairPlan = Repair-GamePaths -userProfilesDir $userProfilesDir -installFolder $gamesInstallFolder -profileIndex $profileIndex -DryRun $dryRunActive
        [pscustomobject]@{ Outcome = $repairPlan.Outcome; Succeeded = ($repairPlan.Outcome -in @('SUCCEEDED','NO_OP')); Reports = @($repairPlan.Reports) }
    }
    $repair = @($repairGroup.Reports)
    $fixed = @($repair | Where-Object { $_.Status -eq "fixed" })
    $nf    = @($repair | Where-Object { $_.Status -eq "not-found" })
    $amb2  = @($repair | Where-Object { $_.Status -in @("ambiguous", "path-unsafe", "not-reviewed", "still-broken") })
    $noex  = @($repair | Where-Object { $_.Status -eq "no-exe-name" })
    $sf    = @($repair | Where-Object { $_.Status -in @("save-failed", "parse-failed", "malformed-profile") })
    if ($repair.Count -eq 0 -and $repairGroup.Outcome -notin @('SUCCEEDED','NO_OP')) {
        Write-Host "  Repair could not be verified; no profile was changed. See the log." -ForegroundColor Yellow
    } elseif ($repair.Count -eq 0) {
        Write-Host "  All game paths are valid. Nothing to repair." -ForegroundColor Green
    } else {
        $repairSummary = Write-LibraryHealthRepairResults -Reports $repair
        Write-Host ("  Repair result: {0} FIXED, {1} STILL BROKEN, {2} CANDIDATE." -f $repairSummary.Fixed, $repairSummary.StillBroken, $repairSummary.Candidates) -ForegroundColor $(if ($repairSummary.StillBroken -gt 0) { 'Yellow' } else { 'Green' })
    }
    Write-Log "Repair: fixed=$($fixed.Count) notfound=$($nf.Count) manualreg=$($amb2.Count) noexe=$($noex.Count) savefail=$($sf.Count)"
    # A game on a drive that is not connected is not an "extract this game first" case: it is named once, in plain words.
    foreach ($driveGone in @($repair | Where-Object { $_.Status -eq 'drive-unavailable' })) { Add-TpmUnavailableDriveGame -Code ([string]$driveGone.Code) -Path ([string]$driveGone.PreviousPath) }
    Write-TpmUnavailableDriveSummary
}


# =============================================================================
# SECTION 9b -- Download game thumbnails (optional)
# =============================================================================

Write-Host ""
$thumbnailsFailed = $false
if ($dryRunActive) {
    Write-Log "PreviewMode: thumbnail download skipped."
    $doThumb = "N"
} elseif ($Unattended) {
    Write-Host "  [Unattended] Downloading missing thumbnails." -ForegroundColor DarkCyan
    Write-Log "Unattended: thumbnail download = Y."
    $doThumb = "Y"
} else {
    $thumbnailHelpBlocks = Get-TpmThumbnailHelpBlocks
    Write-TpmText -Text 'TeknoParrot Manager can download small pictures for your games. It never downloads the games.' -Color DarkCyan
    $doThumb = Read-TpmYesNo -Prompt "Download the missing game pictures? (Y/N, D = use your own pictures)" -DetailsAction { Show-TpmDetailBlocks -Blocks $thumbnailHelpBlocks }
}
if ($doThumb -eq "Y") {
    Write-Host ""
    Write-Host "Downloading thumbnails from TeknoParrotUIThumbnails..." -ForegroundColor Cyan
    Write-Host " Source: https://github.com/teknogods/TeknoParrotUIThumbnails" -ForegroundColor DarkCyan
    Write-Host ""
    $thumbnailResult = @(Invoke-TpmProgressGroup -Title 'Thumbnail download' -Action { Invoke-ThumbnailDownload -userProfilesDir $userProfilesDir -tpRoot $tpRoot }) | Select-Object -Last 1
    $thumbnailsFailed = -not ($thumbnailResult -and [bool]$thumbnailResult.Succeeded)
}
# =============================================================================
# SECTION 10 -- Control propagation
# =============================================================================

$designSkippedItems   = @()   # informational only; does not trigger ACTION REQUIRED
$reports              = $null  # populated if propagation runs; used by Write-ControlsStatus

Write-Host ""
Write-Host "--------------------------------------------" -ForegroundColor Cyan
Write-Host " Copy Controls (Control Propagation)" -ForegroundColor Cyan
Write-Host "--------------------------------------------" -ForegroundColor Cyan

$pool = Build-ArchetypePool -userProfilesDir $userProfilesDir -minBound $MinBoundForArchetype -familyOverride $familyOverrideMap

if ($pool.Count -eq 0) {
    # No reference means a normal no-op with per-game design skips, not an incomplete run.
    $propTransaction = Invoke-TpmProgressGroup -Title 'Control propagation' -Action { Invoke-ControlPropagation -userProfilesDir $userProfilesDir -pool @() -minBound $MinBoundForArchetype -noPropagate $noPropagateList -forceArchetype $forceArchetypeMap -familyOverride $familyOverrideMap -canonicalArchetype $canonicalArchetypeMap -DryRun $dryRunActive }
    $reports = @($propTransaction.Reports)
    $propResult = Write-ControlPropagationResults -Reports $reports -DryRun $dryRunActive -Outcome ([string]$propTransaction.Outcome) -Unattended:$Unattended -DeferDetails
    $designSkippedItems = @($propResult.DesignSkippedItems)
    if (-not $Unattended) { Invoke-DeviceSurvey }
} else {
    $propBackupNote = if ($dryRunActive) { 'Preview mode: no UserProfiles backup was made because nothing is changed.' } else { 'Your UserProfiles were backed up at the start of this run.' }
    Write-TpmControlSourceSummary -Pool $pool
    Write-Host ""
    $controlSourceBlocks = @(Get-TpmControlSourceBlocks -Pool @($pool) -BackupNote $propBackupNote)
    if (-not $Unattended -and (Read-TpmYesNo -Prompt " Want a recommended binding plan for more control types first? (Y/N, D = details of the games to copy from)" -DetailsAction { Show-TpmDetailBlocks -Blocks $controlSourceBlocks }) -eq "Y") {
        Invoke-DeviceSurvey
        Write-Host ""
    }
    if ($Unattended) {
        Write-Host "  [Unattended] Propagating controls." -ForegroundColor DarkCyan
        Write-Log "Unattended: propagation = Y."
        $goCtl = "Y"
    } else {
        $goCtl = Read-TpmControlCopyApproval -Pool @($pool) -BackupNote $propBackupNote
    }
    if ($goCtl.ToUpperInvariant() -eq "Y") {
        $propTransaction = Invoke-TpmProgressGroup -Title 'Control propagation' -Action { Invoke-ControlPropagation -userProfilesDir $userProfilesDir -pool $pool -minBound $MinBoundForArchetype -noPropagate $noPropagateList -forceArchetype $forceArchetypeMap -familyOverride $familyOverrideMap -canonicalArchetype $canonicalArchetypeMap -DryRun $dryRunActive }
        $reports = @($propTransaction.Reports)
        # Part of the registration run, which goes straight on: the details wait for the run's final return prompt (and are logged).
        $propResult = Write-ControlPropagationResults -Reports $reports -DryRun $dryRunActive -Outcome ([string]$propTransaction.Outcome) -BackupPath ([string]$propTransaction.Backup.RootPath) -Unattended:$Unattended -DeferDetails
        $designSkippedItems = @($propResult.DesignSkippedItems)
        if ($propTransaction.Outcome -eq 'SUCCEEDED') {
            Write-Log "Propagation: completed. Controls/API corrected=$($propResult.BoundCount); settings-only=$($propResult.SettingsOnlyCount)"
        } elseif ($propTransaction.Outcome -eq 'NO_OP') {
            Write-Log "Propagation: no profile writes were applied."
        }
    } else {
        Write-Host " Skipped control propagation." -ForegroundColor DarkGray
        Write-Log "Propagation: user declined."
    }
}

# =============================================================================
# Done
# =============================================================================

Write-Host ""
Write-Host "============================================" -ForegroundColor Cyan
if ($dryRunActive) {
    Write-Host "   PREVIEW -- no games or profiles were changed." -ForegroundColor Yellow
    Write-Host "============================================" -ForegroundColor Cyan
    Write-Host ""
    Write-Host "  You'll be asked below whether to apply these changes for real." -ForegroundColor Yellow
} else {
    Write-Host "   Registration run finished." -ForegroundColor Cyan
    Write-Host "============================================" -ForegroundColor Cyan
}
# Read-only bridge from the #258/#262 evidence model into the end-of-run
# handoff. This deliberately runs before the recap so the recap can count
# controls that still need attention, and the same snapshot is then rendered
# in ACTION REQUIRED below without re-reading or modifying any profile.
$controlReadinessItems = @(Get-ControlReadinessActionItems -UserProfilesDir $userProfilesDir `
    -GameProfilesDir $gameProfilesDir -TeknoParrotRoot $tpRoot)

# The controls status file is written before the recap so the recap can say whether it was saved.
$csStatusPath = Join-Path $script:TpmOwnedLayout.Reports "TeknoParrot-Manager-controls.txt"
$csFailed = $false
if ($dryRunActive) {
    Write-Log 'Controls status: preview run; the controls status file was not updated.'
} else {
    $csCount = Write-ControlsStatus -userProfilesDir $userProfilesDir -pool $pool -propagationReports $reports -outputPath $csStatusPath -RunId (Get-TpmSessionRunId)
    if ($csCount -ge 0) {
        Write-Log "Controls status: wrote $csCount games to $csStatusPath"
    } else {
        $csFailed = $true
        Write-Log 'Controls status: the controls status file could not be written; see the log. No controls status was saved.'
    }
}

$registrationRecap = Get-TpmRegistrationRecap -AutoSyncRan ($mode -eq "AutoSync") -ZipsExtracted ([int]$(if ($sync) { $sync.Synced } else { 0 }) + [int]$(if ($syncSupp) { $syncSupp.Synced } else { 0 })) `
    -NewlyRegistered $result.Registered.Count -AlreadyPresent $result.Already.Count -DatAction $eggmanDatActionThisRun `
    -ThumbnailsRequested ($doThumb -eq "Y") -ThumbnailsFailed $thumbnailsFailed -ManualNeeded $manualRegData.Count -ExtractionProblems $extractionProblems -NotInTeknoParrot $result.Unmatched.Count `
    -ControlsNeedAttention $controlReadinessItems.Count -Preview $dryRunActive -ControlsStatusFailed $csFailed -RunProblems $runStopMessages.ToArray() `
    -BackupPath $(if ($dryRunActive) { '' } else { [string]$backupPath }) -LogPath ([string]$logPath) `
    -ControlsStatusPath $(if ($dryRunActive -or $csFailed) { '' } else { $csStatusPath })
# The run ends with its own return prompt (Read-TpmReturnToMenu), which offers these details once; no Details question here.
Write-TpmOutcome -Title $registrationRecap.Title -Status $registrationRecap.Status -Done $registrationRecap.Done -Needs $registrationRecap.Needs -DetailBlocks $registrationRecap.DetailBlocks -Unattended:$Unattended -DeferDetails

# Targeted, context-aware recommendation for the extra version-info file
# (supplementary dat) -- deferred out of the initial wizard (see the
# Eggman-dat setup block above). Only shown when this run actually had an
# uncertain match AND a supplementary dat isn't already configured; a clean
# run with no ambiguous matches sees no extra prompt at all.
if (-not $dryRunActive -and -not $Unattended -and -not $includeSupplementary -and
    ($eggmanDatZip -or $datFilePath) -and $result.Ambiguous.Count -gt 0) {
    Write-Host ""
    Write-Host ("  {0} game(s) had an uncertain match this run. An extra version-info" -f $result.Ambiguous.Count) -ForegroundColor Yellow
    Write-Host "  file (supplementary DAT) may help. Choose Y only if you already have that .dat file." -ForegroundColor Yellow
    $askSuppNow = Read-TpmYesNo -Prompt "  Add a supplementary DAT file now? (Y/N, default N)" -Default 'N'
    if ($askSuppNow -eq 'Y') {
        $rawSuppNow = Read-PathWithBrowse "  Path to supplementary dat file" -Mode File -FileFilter "dat files (*.dat)|*.dat|All files (*.*)|*.*"
        if ($rawSuppNow -and (Test-Path -LiteralPath $rawSuppNow)) {
            $supplementaryDatPath = $rawSuppNow
            $includeSupplementary = $true
            if (Save-Config) {
                Write-Log "Config: supplementaryDatPath set to $rawSuppNow (post-run recommendation)."
                Write-Host "  Saved. Run 'Register only' (games already extracted -- just register)" -ForegroundColor Green
                Write-Host "  from the main menu to apply it to games already registered this run." -ForegroundColor Green
            } else {
                Write-Host "  WARNING: Your settings could not be saved, so this file will not be remembered." -ForegroundColor Yellow
                Write-Host "  Check that the settings file is not read-only, then try again from the main menu." -ForegroundColor Yellow
                Write-Log "Config: supplementaryDatPath could not be saved (post-run recommendation)."
            }
        } elseif ($rawSuppNow) {
            Write-Host "  WARNING: File not found -- skipped." -ForegroundColor Yellow
            Write-Log "Config: post-run supplementary dat not found at $rawSuppNow -- skipped."
        }
    }
}

Write-Log "Completed. Registered=$($result.Registered.Count) Already=$($result.Already.Count) ManualReg=$($result.Ambiguous.Count) Unmatched=$($result.Unmatched.Count)"

# =============================================================================
# GAME INFO -- source tag and notes for newly registered games
# =============================================================================

if ($result.Registered.Count -gt 0 -and $notesIndex.Count -gt 0) {
    $infoItems = @($result.Registered | Where-Object { $notesIndex.ContainsKey($_.Code.ToLowerInvariant()) })
    if ($infoItems.Count -gt 0) {
        Write-Host ""
        Write-Host "============================================" -ForegroundColor Cyan
        Write-Host "   Game Info (from dat)" -ForegroundColor Cyan
        Write-Host "============================================" -ForegroundColor Cyan
        foreach ($r in $infoItems) {
            $key = $r.Code.ToLowerInvariant()
            Write-Host ""
            Write-Host ("  {0}" -f $r.Code) -ForegroundColor Yellow
            if ($suppCodes.Contains($r.Code)) {
                Write-Host "  Source: supplementary dat (alternate version used instead of collection)" -ForegroundColor DarkCyan
            }
            if ($notesIndex.ContainsKey($key)) {
                Write-Host "  Notes:" -ForegroundColor Cyan
                $noteLines = ($notesIndex[$key] -split "`n") | Where-Object { $_.Trim() } | Select-Object -First 4
                foreach ($nl in $noteLines) {
                    Write-Host ("    {0}" -f $nl.Trim()) -ForegroundColor DarkGray
                }
            }
        }
        Write-Host ""
    }
}

function Get-TpmProfileFriendlyTitle {
    param([Parameter(Mandatory)]$Doc, [Parameter(Mandatory)][string]$BaseName)
    $descNode = $Doc.GameProfile.SelectSingleNode('Description')
    if ($descNode -and -not [string]::IsNullOrWhiteSpace($descNode.InnerText)) { return $descNode.InnerText.Trim() }
    return [regex]::Replace($BaseName, '(?<=[a-z])(?=[A-Z])', ' ')
}

# =============================================================================
# TpmLed MODULE SECTION: LEDBlinky lighting export  (optional; only offered when LEDBlinky is found)
# =============================================================================
# Written so it can be lifted into a .psm1 after 1.0. Everything between this header and the "END TpmLed" marker
# belongs to it. It holds no script-level variables: all state travels in parameters and returned objects.
#
# Public functions (the only ones other code or tests may call):
#   Core, no screen output:  Get-TpmLedBlinkyCandidateFolders, Get-TpmLedBlinkyFolderProblem, Find-TpmLedBlinky,
#                            Test-TpmLedBlinkyRunning, Get-TpmLedCabinet, Get-TpmLedControlPairing,
#                            Get-TpmLedExportPlan, New-TpmLedPreviewFile,
#                            Invoke-TpmLedBlinkyAdd, Invoke-TpmLedBlinkyUndo
#   Screens:                 Write-TpmLedPreview, Get-TpmLedPlanDetailBlocks, Invoke-TpmLedBlinkyLocate, Read-TpmLedBlinkyFolder, Get-TpmLedLocalDriveRoots,
#                            Invoke-TpmLedBlinkyStep
# Everything else in the section (Get-TpmLed*, New-TpmLedGroupText, Read-TpmLedControlsText, ConvertTo-TpmLedXmlText,
# Write-TpmLedResult) is private.
#
# Dependencies outside the section (must travel with it or be provided):
#   Core:    Get-TpmLedBlinkyKeyMap (the existing LED key map reader), Get-TpmProfileFriendlyTitle (defined just above, also used by the LaunchBox export), Get-ButtonNodes,
#            Get-ProfileFamily, Read-Xml, Get-TpmRegisteredProfileFilesWithDiscoveryProgress, Get-TpmAutoSyncSha256,
#            Write-TpmAtomicTextFile, Test-TpmNoReparsePath, Write-Log
#   Screens: Write-TpmOutcome, Write-TpmText, Read-TpmChoice, Read-TpmYesNo, Format-TpmGameCount, Get-TpmControllerEvidence (the existing
#            device check), Read-PathWithBrowse (the
#            folder picker), Get-LocalDriveInfoSafe, Test-IsNetworkPath (local drive check)
# The folder the user chose is kept by the caller in the Manager settings file (LedBlinkyRoot); the section only receives it
# as a parameter and reports a changed choice through the State object it is given.
#
# What it does: adds one lighting entry per registered game to LEDBlinky's own control file (LEDBlinkyControls.xml),
# under the "TeknoParrot" emulator group that LEDBlinky already has. Safety rules, all enforced below:
#   - LEDBlinky is only ever read until the user answers Yes to an exact preview.
#   - Nothing is written while LEDBlinky or its editor is open, or if the file changed after the preview.
#   - A verified copy of the file is saved first, and every add can be undone.
#   - Only entries this tool adds are ever removed. Entries LEDBlinky or the user made are never touched.
#   - TeknoParrot profiles are only read. LEDs are never driven. Nothing is downloaded.
# Game key: the profile file name without ".xml". That is the ROM name LaunchBox hands to LEDBlinky for a TeknoParrot
# game (the profile is the "ROM"). The controls are the ones each profile lists, not a verified requirement list.

# Pure: the usual places LEDBlinky lives, in the order to look. Nothing is touched.
function Get-TpmLedBlinkyCandidateFolders {
    param([string]$SavedFolder = '', [string]$LaunchBoxRoot = '', [string[]]$DriveRoots = @(), [string[]]$ProgramFilesFolders = @())
    $list = New-Object System.Collections.Generic.List[string]
    if ($SavedFolder) { [void]$list.Add($SavedFolder) }
    if ($LaunchBoxRoot) {
        $beside = Split-Path -Parent ($LaunchBoxRoot.TrimEnd('\', '/'))
        if ($beside) { [void]$list.Add((Join-Path $beside 'LEDBlinky')) }
    }
    foreach ($root in @($DriveRoots | Where-Object { $_ })) { [void]$list.Add($root.TrimEnd('\') + '\LEDBlinky') }
    foreach ($folder in @($ProgramFilesFolders | Where-Object { $_ })) { [void]$list.Add((Join-Path $folder 'LEDBlinky')) }
    return ,@($list | Select-Object -Unique)
}

# The one rule for "this is the LEDBlinky folder": it exists and holds LEDBlinkyControls.xml.
# Returns '' when fine, 'NoFolder' or 'NoControls' otherwise.
function Get-TpmLedBlinkyFolderProblem {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path -PathType Container)) { return 'NoFolder' }
    if (-not (Test-Path -LiteralPath (Join-Path $Path 'LEDBlinkyControls.xml') -PathType Leaf)) { return 'NoControls' }
    return ''
}

# Read-only: the first candidate folder that is a real LEDBlinky folder, or $null when none is.
function Find-TpmLedBlinky {
    param([string[]]$Candidates = @())
    foreach ($folder in @($Candidates | Where-Object { $_ })) {
        if ((Get-TpmLedBlinkyFolderProblem -Path $folder) -eq '') { return [pscustomobject]@{ Root = $folder; ControlsPath = (Join-Path $folder 'LEDBlinkyControls.xml') } }
    }
    return $null
}
function Test-TpmLedBlinkyRunning {
    return (@(Get-Process -Name 'LEDBlinky', 'LEDBlinkyControlsEditor', 'LEDBlinkyConfig' -ErrorAction SilentlyContinue).Count -gt 0)
}

# Text safe inside an XML attribute and plain ASCII (the control file may be read as ANSI by LEDBlinky).
function ConvertTo-TpmLedXmlText {
    param([AllowEmptyString()][string]$Text)
    $escaped = [System.Security.SecurityElement]::Escape(($Text -replace '[\x00-\x1F]', ' '))
    $builder = New-Object System.Text.StringBuilder
    for ($i = 0; $i -lt $escaped.Length; $i++) {
        $c = $escaped[$i]
        if ([int]$c -lt 128) { [void]$builder.Append($c) }
        elseif ([char]::IsHighSurrogate($c) -and ($i + 1) -lt $escaped.Length -and [char]::IsLowSurrogate($escaped[$i + 1])) {
            [void]$builder.Append(('&#{0};' -f [char]::ConvertToUtf32($c, $escaped[$i + 1]))); $i++
        } else { [void]$builder.Append(('&#{0};' -f [int]$c)) }
    }
    return $builder.ToString()
}

# --- Profile side (read-only): the controls a TeknoParrot profile lists, sorted by what they are.
# Exact is the LEDBlinky name for the standard controls (buttons, directions, Start, Coin). Everything else is matched
# against the user's own setup by Kind (see Get-TpmLedGameMatch). Analog axes (wheel, gun aim) have no LED and are skipped.
function Get-TpmLedProfileControls {
    param([Parameter(Mandatory)]$Doc)
    $seen = @{}
    $controls = New-Object System.Collections.Generic.List[object]
    foreach ($button in @(Get-ButtonNodes $Doc)) {
        $mappingNode = $button.SelectSingleNode('InputMapping')
        if ($null -eq $mappingNode) { continue }
        $mapping = $mappingNode.InnerText.Trim()
        if (-not $mapping -or $seen.ContainsKey($mapping)) { continue }
        $seen[$mapping] = $true
        $labelNode = $button.SelectSingleNode('ButtonName')
        $label = if ($labelNode) { $labelNode.InnerText.Trim() } else { '' }
        $analogNode = $button.SelectSingleNode('AnalogType')
        $analog = if ($analogNode -and $analogNode.InnerText.Trim()) { $analogNode.InnerText.Trim() } else { 'None' }
        $player = 0
        if ($mapping -match '^P(\d)') { $player = [int]$Matches[1] }
        $control = [pscustomobject]@{ Mapping = $mapping; Label = $(if ($label) { $label } else { $mapping }); Voice = ''; Player = $player; Kind = 'Other'; Number = 0; Exact = '' }
        if ($mapping -match '(?i)trackball') { $control.Kind = 'Trackball' }
        elseif ($mapping -match '(?i)spinner|dial' -or $label -match '(?i)spinner') { $control.Kind = 'Spinner' }
        elseif ($analog -in @('Gas', 'Brake')) { $control.Kind = 'Pedal' }
        elseif ($analog -ne 'None') { continue }
        elseif ($mapping -match '^P(\d)Button(\d+)$') {
            $control.Kind = 'Button'; $control.Number = [int]$Matches[2]; $control.Exact = ('P{0}_BUTTON{1}' -f $Matches[1], [int]$Matches[2])
            if ($label -and $label.Length -le 30 -and $label -notmatch '(?i)^(p\d\s*)?button\s*\d+$') { $control.Voice = $label }
        }
        elseif ($mapping -match '^P(\d)Button(Up|Down|Left|Right)$') { $control.Kind = 'Direction'; $control.Exact = ('P{0}_JOYSTICK_{1}' -f $Matches[1], $Matches[2].ToUpperInvariant()) }
        elseif ($mapping -match '^P(\d)ButtonStart$' -or $mapping -match '^Start(\d)$') { $control.Kind = 'Start'; $control.Player = [int]$Matches[1]; $control.Exact = ('START{0}' -f $Matches[1]) }
        elseif ($mapping -match '^(?:P(\d))?Coin(\d)?$') {
            $n = if ($Matches[1]) { [int]$Matches[1] } elseif ($Matches[2]) { [int]$Matches[2] } else { 1 }
            $control.Kind = 'Coin'; $control.Player = $n; $control.Exact = ('COIN{0}' -f $n)
        }
        elseif ($mapping -match '(?i)service') { $control.Kind = 'Service' }
        elseif ($mapping -match '(?i)^(p\d)?test') { $control.Kind = 'Test' }
        [void]$controls.Add($control)
    }
    return [pscustomobject]@{ Controls = @($controls | Sort-Object Player, Kind, Number); Family = (Get-ProfileFamily $Doc) }
}

# --- Cabinet side (read-only): what the user's own LEDBlinky setup defines.
# The controls the user's LEDBlinky knows, read from LEDBlinkyControls.xml text: the TeknoParrot default group first, then
# the TeknoParrot games, and the other emulators' default groups only when TeknoParrot has no default group of its own.
# Names are taken exactly as written (any name the user's file uses is kept). Controls that name a main control
# (CONTROL_...) are IsPrimary.
function Get-TpmLedCabinet {
    param([Parameter(Mandatory)][string]$ControlsText)
    $doc = New-Object System.Xml.XmlDocument
    $doc.XmlResolver = $null
    try { $doc.LoadXml($ControlsText) } catch { throw 'The LEDBlinky control file could not be read as XML, so it was left alone.' }
    $teknoGroups = @($doc.SelectNodes('/dat/emulator[@emuname="TeknoParrot"]/controlGroup'))
    $defaults = @($teknoGroups | Where-Object { $_.GetAttribute('groupName') -eq 'DEFAULT' })
    $source = 'the TeknoParrot defaults'
    if ($defaults.Count -eq 0) { $defaults = @($doc.SelectNodes('/dat/emulator/controlGroup[@groupName="DEFAULT"]')); $source = 'the defaults of your other emulators' }
    $others = @($teknoGroups | Where-Object { $_.GetAttribute('groupName') -ne 'DEFAULT' })
    $controls = @{}   # a hashtable literal ignores letter case in its keys, as control names need
    $names = New-Object System.Collections.Generic.List[string]
    foreach ($group in (@($defaults) + @($others))) {
        foreach ($playerNode in @($group.SelectNodes('player'))) {
            $player = 0
            [void][int]::TryParse($playerNode.GetAttribute('number'), [ref]$player)
            foreach ($node in @($playerNode.SelectNodes('control'))) {
                $name = $node.GetAttribute('name')
                if (-not $name -or $controls.ContainsKey($name)) { continue }
                $controls[$name] = [pscustomobject]@{
                    Name = $name; Player = $player; Voice = $node.GetAttribute('voice')
                    IsPrimary = (($name -like 'CONTROL_*') -or ($node.GetAttribute('primaryControl') -eq '1'))
                    InputCodes = $(if ($node.HasAttribute('inputCodes')) { $node.GetAttribute('inputCodes') } else { $null })
                    Color = $(if ($node.HasAttribute('color')) { $node.GetAttribute('color') } else { $null })
                }
                [void]$names.Add($name)
            }
        }
    }
    $players = @($names | ForEach-Object { $controls[$_].Player } | Where-Object { $_ -gt 0 } | Sort-Object -Unique)
    return [pscustomobject]@{ Controls = $controls; Names = $names.ToArray(); Players = $players; Source = $source; Held = @() }
}

# Pure pairing of the cabinet's controls with LEDs. Inputs: the cabinet (Get-TpmLedCabinet), the LED key map
# (Get-TpmLedBlinkyKeyMap, existing reader of LEDBlinkyInputMap.xml; $null or Found=$false means it was not available) and
# the controller evidence (Get-TpmControllerEvidence, TpmControllerEvidence/v1; $null or not 'Observed' means no device check).
# A control is paired when its input codes match exactly one LED label in the key map. Nothing is guessed:
#   - no LED matches, or more than one fits -> the control is held back (Held) and shown as needing the user's choice;
#   - a LED no control uses -> LedsWithoutControl;
#   - a kind of control the devices show but LEDBlinky does not have, or the other way round -> Families (held back too).
# The device check only looks at the families named below (the evidence today says which kinds of device are connected,
# not button counts), so richer evidence can be added there later without changing the callers.
# Returns Usable (a cabinet holding only the controls that may be written, plus Held) and the lists above.
function Get-TpmLedControlPairing {
    param([Parameter(Mandatory)]$Cabinet, $KeyMap = $null, $Evidence = $null)
    $keyMapFound = ($null -ne $KeyMap -and [bool]$KeyMap.Found)
    $labelsByCode = @{}   # a hashtable literal ignores letter case in its keys, as input codes need
    $allLabels = New-Object System.Collections.Generic.List[string]
    if ($keyMapFound) {
        foreach ($led in @($KeyMap.Controls)) {
            [void]$allLabels.Add([string]$led.Control)
            foreach ($code in @($led.InputCodes)) {
                if (-not $labelsByCode.ContainsKey($code)) { $labelsByCode[$code] = New-Object System.Collections.Generic.List[string] }
                if (-not $labelsByCode[$code].Contains([string]$led.Control)) { [void]$labelsByCode[$code].Add([string]$led.Control) }
            }
        }
    }
    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $keep = New-Object System.Collections.Generic.List[string]
    $held = New-Object System.Collections.Generic.List[object]
    $pairs = New-Object System.Collections.Generic.List[object]
    foreach ($name in @($Cabinet.Names)) {
        $cab = $Cabinet.Controls[$name]
        $status = 'Unchecked'; $labels = @()
        if ($keyMapFound) {
            if ($cab.IsPrimary) {
                $suffix = $name -replace '^CONTROL_', ''
                $labels = @($KeyMap.Controls | Where-Object { $_.Control -ieq $suffix -or @($_.InputCodes) -contains $suffix } | ForEach-Object { [string]$_.Control })
                $status = 'Primary'
            } else {
                $codes = @(([string]$cab.InputCodes).Split('|') | ForEach-Object { $_.Trim() } | Where-Object { $_ })
                if ($codes.Count -eq 0) { $status = 'NoInputCode' }
                else {
                    $labels = @($codes | ForEach-Object { if ($labelsByCode.ContainsKey($_)) { $labelsByCode[$_] } } | ForEach-Object { $_ } | Select-Object -Unique)
                    if ($labels.Count -eq 1) { $status = 'Paired' }
                    elseif ($labels.Count -eq 0) { $status = 'NoLed' }
                    else { $status = 'Several' }
                }
            }
        }
        foreach ($label in $labels) { [void]$used.Add($label) }
        [void]$pairs.Add([pscustomobject]@{ Name = $name; Status = $status; Leds = @($labels) })
        if ($status -in @('NoLed', 'Several')) { [void]$held.Add([pscustomobject]@{ Name = $name; Reason = $status; Candidates = @($labels) }) }
        else { [void]$keep.Add($name) }
    }
    $ledsWithoutControl = @($allLabels | Where-Object { -not $used.Contains($_) })
    $families = New-Object System.Collections.Generic.List[object]
    if ($null -ne $Evidence -and [string]$Evidence.EvidenceStatus -eq 'Observed') {
        $kinds = @(
            @{ Name = 'Trackball or spinner'; Classes = @('PointerOrTrackball'); Pattern = '(?i)TRACKBALL|DIAL|SPINNER' },
            @{ Name = 'Light gun'; Classes = @('LightGun'); Pattern = '(?i)LIGHTGUN' },
            @{ Name = 'Wheel or pedals'; Classes = @('Wheel'); Pattern = '(?i)WHEEL|PEDAL' }
        )
        foreach ($kind in $kinds) {
            $detected = [int](@($Evidence.DeviceObservations | Where-Object { $_.DeviceClass -in $kind.Classes } | Measure-Object -Property Count -Sum).Sum)
            $mine = @($keep | Where-Object { $_ -match $kind.Pattern })
            if ($detected -gt 0 -and $mine.Count -eq 0) { [void]$families.Add([pscustomobject]@{ Family = $kind.Name; Status = 'DetectedNoControl'; Controls = @() }) }
            elseif ($detected -eq 0 -and $mine.Count -gt 0) {
                [void]$families.Add([pscustomobject]@{ Family = $kind.Name; Status = 'ControlNotDetected'; Controls = $mine })
                foreach ($m in $mine) { [void]$held.Add([pscustomobject]@{ Name = $m; Reason = 'NotDetected'; Candidates = @() }); [void]$keep.Remove($m) }
            }
        }
    }
    $usableControls = @{}
    # Rgb says whether the paired light can show colors: $true, $false (single-color light), or $null when unknown (no map).
    $rgbByLabel = @{}
    if ($keyMapFound) { foreach ($led in @($KeyMap.Controls)) { $rgbByLabel[[string]$led.Control] = if ($led.PSObject.Properties['IsRgb']) { [bool]$led.IsRgb } else { $null } } }
    foreach ($name in $keep) {
        $copy = $Cabinet.Controls[$name] | Select-Object *
        $pairLeds = @(($pairs | Where-Object { $_.Name -eq $name } | Select-Object -First 1).Leds)
        $rgb = $null
        if ($pairLeds.Count -gt 0 -and @($pairLeds | Where-Object { $null -eq $rgbByLabel[[string]$_] }).Count -eq 0) {
            $rgb = (@($pairLeds | Where-Object { -not $rgbByLabel[[string]$_] }).Count -eq 0)
        }
        Add-Member -InputObject $copy -NotePropertyName Rgb -NotePropertyValue $rgb -Force
        $usableControls[$name] = $copy
    }
    $usable = [pscustomobject]@{ Controls = $usableControls; Names = $keep.ToArray(); Players = $Cabinet.Players; Source = $Cabinet.Source; Held = $held.ToArray(); LightIsRgb = $rgbByLabel }
    return [pscustomobject]@{ Usable = $usable; Pairs = $pairs.ToArray(); Held = $held.ToArray(); LedsWithoutControl = $ledsWithoutControl; Families = $families.ToArray(); KeyMapFound = $keyMapFound; DevicesChecked = ($families.Count -gt 0 -or ($null -ne $Evidence -and [string]$Evidence.EvidenceStatus -eq 'Observed')) }
}

# Matches one profile's controls against the usable cabinet. Only controls that are on the cabinet are written. A control
# the cabinet does not have is NotOnCabinet. A control that cannot be matched with confidence (several possible cabinet
# controls, a cabinet control held back by the pairing, or no known kind) is NeedsChoice and is not written.
function Get-TpmLedGameMatch {
    param([Parameter(Mandatory)]$ProfileControls, [Parameter(Mandatory)]$Cabinet)
    $written = New-Object System.Collections.Generic.List[object]
    $notOn = New-Object System.Collections.Generic.List[string]
    $choice = New-Object System.Collections.Generic.List[object]
    $heldNames = @($Cabinet.Held | ForEach-Object { $_.Name })
    $alias = @{ Service = '(?i)SERVICE'; Test = '(?i)(^|_)TEST'; Spinner = '(?i)DIAL|SPINNER'; Pedal = '(?i)PEDAL|GAS|BRAKE|ACCEL'; Trackball = '(?i)TRACKBALL' }
    $add = {
        param($name, $voice, $cab)
        $use = if ($null -ne $cab) { $cab } else { $Cabinet.Controls[$name] }
        if (@($written | Where-Object { $_.Cab.Name -eq $name }).Count -eq 0) { [void]$written.Add([pscustomobject]@{ Cab = $use; Voice = $voice }) }
    }
    foreach ($control in @($ProfileControls.Controls)) {
        if ($control.Exact) {
            if ($Cabinet.Controls.ContainsKey($control.Exact)) { & $add $control.Exact $control.Voice }
            elseif ($heldNames -contains $control.Exact) { [void]$choice.Add([pscustomobject]@{ Label = $control.Label; Candidates = @($control.Exact) }) }
            else { [void]$notOn.Add($control.Label) }
            continue
        }
        if ($alias.ContainsKey($control.Kind)) {
            $candidates = @($Cabinet.Names | Where-Object { $_ -match $alias[$control.Kind] })
            if ($control.Player -gt 0) {
                $mine = @($candidates | Where-Object { $_ -like ('P{0}_*' -f $control.Player) })
                if ($mine.Count -gt 0) { $candidates = $mine }
            }
            if ($candidates.Count -eq 0) {
                $heldHere = @($heldNames | Where-Object { $_ -match $alias[$control.Kind] })
                if ($heldHere.Count -gt 0) { [void]$choice.Add([pscustomobject]@{ Label = $control.Label; Candidates = $heldHere }) }
                elseif ($control.Kind -eq 'Trackball') {
                    # The cabinet's trackball has a light, but the user's default entry does not list it. Add the standard trackball control.
                    # Rgb stays unknown ($null) when the LED map has no trackball light; a single-color trackball light gets no color.
                    $trackRgb = $null
                    if ($Cabinet.PSObject.Properties['LightIsRgb'] -and $Cabinet.LightIsRgb.ContainsKey('TRACKBALL')) { $trackRgb = $Cabinet.LightIsRgb['TRACKBALL'] }
                    & $add 'CONTROL_TRACKBALL' 'Trackball' ([pscustomobject]@{ Name = 'CONTROL_TRACKBALL'; Voice = 'Trackball'; IsPrimary = $true; Color = 'White'; InputCodes = $null; Player = 0; Rgb = $trackRgb })
                }
                else { [void]$notOn.Add($control.Label) }
            }
            elseif ($candidates.Count -eq 1) { & $add $candidates[0] '' }
            else { [void]$choice.Add([pscustomobject]@{ Label = $control.Label; Candidates = $candidates }) }
            continue
        }
        [void]$choice.Add([pscustomobject]@{ Label = $control.Label; Candidates = @() })
    }
    if ($ProfileControls.Family -eq 'lightgun') {
        if ($Cabinet.Controls.ContainsKey('CONTROL_LIGHTGUN')) { & $add 'CONTROL_LIGHTGUN' '' }
        elseif ($heldNames -contains 'CONTROL_LIGHTGUN') { [void]$choice.Add([pscustomobject]@{ Label = 'Light gun'; Candidates = @('CONTROL_LIGHTGUN') }) }
        else { [void]$notOn.Add('Light gun') }
    } elseif (@($ProfileControls.Controls | Where-Object { $_.Kind -eq 'Direction' }).Count -gt 0) {
        $joystick = @($Cabinet.Names | Where-Object { $_ -match '^CONTROL_(DOUBLE|V)?(JOY|STICK)' }) | Select-Object -First 1
        if ($joystick) { & $add $joystick '' }
    }
    return [pscustomobject]@{ Written = $written.ToArray(); NotOnCabinet = $notOn.ToArray(); NeedsChoice = $choice.ToArray() }
}

# The usual arcade button colors, as already used across the user's LEDBlinky games: buttons 1 to 4 are red, yellow, green
# and blue; other buttons, Start, Coin and the trackball are white. Returns nothing for any other control (keeps its own color).
function Get-TpmLedSchemeColor {
    param([Parameter(Mandatory)][string]$Name)
    if ($Name -match '^P[1-4]_BUTTON([1-7])$') { return @('Red', 'Yellow', 'Green', 'Blue', 'White', 'White', 'White')[[int]$Matches[1] - 1] }
    if ($Name -match '^(START|COIN)[1-4]$' -or $Name -eq 'CONTROL_TRACKBALL') { return 'White' }
    return $null
}

# The main color of one picture, as the closest LEDBlinky color name. Grays, near-black and near-white pictures give White.
function Get-TpmLedColorNameFromImage {
    param([Parameter(Mandatory)][string]$Path)
    Add-Type -AssemblyName System.Drawing
    $stream = $null; $image = $null; $small = $null
    try {
        $stream = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        $image = [System.Drawing.Image]::FromStream($stream)
        $small = New-Object System.Drawing.Bitmap $image, 24, 24
        $weights = @{}
        $total = 0.0
        foreach ($x in 0..23) {
            foreach ($y in 0..23) {
                $pixel = $small.GetPixel($x, $y)
                $sat = [double]$pixel.GetSaturation(); $light = [double]$pixel.GetBrightness()
                if ($sat -lt 0.35 -or $light -lt 0.2 -or $light -gt 0.9) { continue }
                $hue = [double]$pixel.GetHue()
                $name = if ($hue -lt 15 -or $hue -ge 345) { 'Red' } elseif ($hue -lt 40) { 'Orange' } elseif ($hue -lt 70) { 'Yellow' } elseif ($hue -lt 100) { 'Lime' } elseif ($hue -lt 170) { 'Green' } elseif ($hue -lt 200) { 'Cyan' } elseif ($hue -lt 260) { 'Blue' } elseif ($hue -lt 300) { 'Purple' } else { 'Magenta' }
                $weights[$name] = [double]$weights[$name] + $sat
                $total += $sat
            }
        }
        if ($total -lt 20) { return 'White' }
        return (@($weights.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 1)[0].Key)
    } finally {
        if ($small) { $small.Dispose() }
        if ($image) { $image.Dispose() }
        if ($stream) { $stream.Dispose() }
    }
}

# The main color of a game's picture in the user's LaunchBox pictures (marquee first). Pictures are only read, never changed
# or downloaded. Returns nothing when no picture matches the game's name closely enough.
function Get-TpmLedArtworkColor {
    param([string[]]$ImageFolders = @(), [Parameter(Mandatory)][string]$Title)
    $wanted = ConvertTo-TpmLbMediaKey -Text $Title
    if (-not $wanted) { return $null }
    foreach ($type in @('Arcade - Marquee', 'Box - Front', 'Screenshot - Game Title', 'Fanart - Background')) {
        foreach ($folder in $ImageFolders) {
            $dir = Join-Path $folder $type
            if (-not (Test-Path -LiteralPath $dir -PathType Container)) { continue }
            $best = $null; $bestScore = 0.0
            foreach ($file in @(Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -match '^\.(png|jpe?g)$' })) {
                $score = Get-TpmLbMediaSimilarity -Left $wanted -Right (ConvertTo-TpmLbMediaKey -Text $file.BaseName)
                if ($score -gt $bestScore) { $bestScore = $score; $best = $file }
            }
            if ($best -and $bestScore -ge 0.9) {
                try { return (Get-TpmLedColorNameFromImage -Path $best.FullName) } catch { Write-Log "LEDBlinky: could not read the picture $($best.Name) -- $_" }
            }
        }
    }
    return $null
}

# One game's entry, built only from cabinet controls (name and input codes are the user's own; color follows the usual
# arcade scheme above). The game's own label is used as the spoken word for a button when it has one.
function New-TpmLedGroupText {
    param([Parameter(Mandatory)][string]$Key, [Parameter(Mandatory)][string]$Title, [Parameter(Mandatory)][object[]]$Written, [Parameter(Mandatory)][string]$Newline, [switch]$KeepOwnColors)
    $line = {
        param($entry)
        $voice = if ($entry.Voice) { $entry.Voice } else { $entry.Cab.Voice }
        $text = '        <control name="{0}" voice="{1}"' -f (ConvertTo-TpmLedXmlText $entry.Cab.Name), (ConvertTo-TpmLedXmlText $voice)
        if ($entry.Cab.IsPrimary) { $text += ' primaryControl="1"' }
        # With KeepOwnColors the user's own colors are written as they are (no usual scheme, no picture color).
        $schemeColor = if ($KeepOwnColors) { $null } else { Get-TpmLedSchemeColor -Name ([string]$entry.Cab.Name) }
        $artColor = if (-not $KeepOwnColors -and $entry.PSObject.Properties['Color']) { [string]$entry.Color } else { '' }
        $useColor = if ($artColor) { $artColor } elseif ($schemeColor) { $schemeColor } else { $entry.Cab.Color }
        # A single-color light cannot show a color, so none is written for it.
        $singleColor = ($entry.Cab.PSObject.Properties['Rgb'] -and $entry.Cab.Rgb -eq $false)
        if ($null -ne $useColor -and -not $singleColor) { $text += (' color="{0}"' -f (ConvertTo-TpmLedXmlText $useColor)) }
        if ($null -ne $entry.Cab.InputCodes) { $text += (' inputCodes="{0}"' -f (ConvertTo-TpmLedXmlText $entry.Cab.InputCodes)) }
        return ($text + ' />')
    }
    $primaries = @($Written | Where-Object { $_.Cab.IsPrimary })
    $normal = @($Written | Where-Object { -not $_.Cab.IsPrimary } | Sort-Object { $_.Cab.Player })
    $maxPlayer = [Math]::Max(1, [int](@($normal | ForEach-Object { $_.Cab.Player } | Measure-Object -Maximum).Maximum))
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add(('    <controlGroup groupName="{0}" voice="{1}" numPlayers="{2}" alternating="0" jukebox="0">' -f (ConvertTo-TpmLedXmlText $Key), (ConvertTo-TpmLedXmlText $Title), $maxPlayer))
    if ($primaries.Count -gt 0) {
        [void]$lines.Add('      <player number="0">')
        foreach ($entry in $primaries) { [void]$lines.Add((& $line $entry)) }
        [void]$lines.Add('      </player>')
    }
    foreach ($player in @($normal | ForEach-Object { $_.Cab.Player } | Sort-Object -Unique)) {
        [void]$lines.Add(('      <player number="{0}">' -f $player))
        foreach ($entry in @($normal | Where-Object { $_.Cab.Player -eq $player })) { [void]$lines.Add((& $line $entry)) }
        [void]$lines.Add('      </player>')
    }
    [void]$lines.Add('    </controlGroup>')
    return ($lines -join $Newline)
}

# Reads LEDBlinky's control file as text. Refuses a file that would not survive a text round trip byte for byte.
function Read-TpmLedControlsText {
    param([Parameter(Mandatory)][string]$Path)
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) { throw 'The LEDBlinky control file starts with a byte-order mark, so it was left alone.' }
    $strict = New-Object System.Text.UTF8Encoding($false, $true)
    try { return $strict.GetString($bytes) } catch { throw 'The LEDBlinky control file is not plain UTF-8 text, so it was left alone.' }
}

# Where the TeknoParrot emulator group ends inside the control file text. $null when LEDBlinky has no such group.
function Get-TpmLedEmulatorSpan {
    param([Parameter(Mandatory)][string]$Text, [string]$Name = 'TeknoParrot')
    $m = [regex]::Match($Text, ('(?s)<emulator\s+emuname="{0}"[^>/]*>(?<body>.*?)</emulator>' -f [regex]::Escape($Name)))
    if (-not $m.Success) { return $null }
    return [pscustomobject]@{ InsertAt = $m.Groups['body'].Index + $m.Groups['body'].Length; Body = $m.Groups['body'].Value }
}

# Read-only plan: which games would get a new entry, and the exact text that would be added. The entries are built only
# from controls that the profile uses and the user's own LEDBlinky setup has (and can pair with an LED).
# Evidence: the controller evidence object (Get-TpmControllerEvidence), or $null when no device check is wanted.
function Get-TpmLedExportPlan {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$ControlsPath, $Evidence = $null, [string[]]$ImageFolders = @(), [switch]$KeepOwnColors)
    $text = Read-TpmLedControlsText -Path $ControlsPath
    $newline = if ($text.Contains("`r`n")) { "`r`n" } else { "`n" }
    $plan = [pscustomobject]@{
        HasEmulator = $false; HasCabinet = $false; Cabinet = $null; Pairing = $null; Newline = $newline; InsertAt = 0
        SourceHash = (Get-TpmAutoSyncSha256 -Path $ControlsPath)
        Groups = (New-Object System.Collections.Generic.List[object]); SkippedExisting = (New-Object System.Collections.Generic.List[string])
        SkippedNoControls = (New-Object System.Collections.Generic.List[string]); Unreadable = (New-Object System.Collections.Generic.List[string]); BlockText = ''
    }
    $span = Get-TpmLedEmulatorSpan -Text $text
    if ($null -eq $span) { return $plan }
    $plan.HasEmulator = $true
    $plan.InsertAt = $span.InsertAt
    $folder = Split-Path -Parent $ControlsPath
    $keyMap = if (Test-Path -LiteralPath (Join-Path $folder 'LEDBlinkyInputMap.xml') -PathType Leaf) { Get-TpmLedBlinkyKeyMap -Root @($folder) } else { $null }
    $plan.Cabinet = Get-TpmLedCabinet -ControlsText $text
    $plan.Pairing = Get-TpmLedControlPairing -Cabinet $plan.Cabinet -KeyMap $keyMap -Evidence $Evidence
    if ($plan.Pairing.Usable.Names.Count -eq 0) { return $plan }
    $plan.HasCabinet = $true
    $existing = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($m in [regex]::Matches($span.Body, '<controlGroup\s+groupName="([^"]*)"')) { [void]$existing.Add([System.Net.WebUtility]::HtmlDecode($m.Groups[1].Value)) }
    $files = @(Get-TpmRegisteredProfileFilesWithDiscoveryProgress -UserProfilesDir $UserProfilesDir -ProgressLabel 'LEDBlinky preview' -EnumerationErrorAction SilentlyContinue | Sort-Object Name)
    $blocks = New-Object System.Collections.Generic.List[string]
    foreach ($file in $files) {
        try {
            $doc = Read-Xml $file.FullName
            if ($null -eq $doc.GameProfile) { continue }
            if ($existing.Contains($file.BaseName) -or $file.BaseName -ieq 'DEFAULT') { [void]$plan.SkippedExisting.Add($file.BaseName); continue }
            $match = Get-TpmLedGameMatch -ProfileControls (Get-TpmLedProfileControls -Doc $doc) -Cabinet $plan.Pairing.Usable
            if ($match.Written.Count -eq 0) { [void]$plan.SkippedNoControls.Add($file.BaseName); continue }
            $title = Get-TpmProfileFriendlyTitle -Doc $doc -BaseName $file.BaseName
            # A trackball light takes the main color of the game's own picture, when the user's LaunchBox has one.
            if ($ImageFolders.Count -gt 0 -and -not $KeepOwnColors) {
                $trackball = @($match.Written | Where-Object { $_.Cab.Name -eq 'CONTROL_TRACKBALL' })
                if ($trackball.Count -gt 0) {
                    $artColor = Get-TpmLedArtworkColor -ImageFolders $ImageFolders -Title $title
                    if ($artColor) { foreach ($t in $trackball) { Add-Member -InputObject $t -NotePropertyName Color -NotePropertyValue $artColor -Force } }
                }
            }
            [void]$blocks.Add((New-TpmLedGroupText -Key $file.BaseName -Title $title -Written $match.Written -Newline $newline -KeepOwnColors:$KeepOwnColors))
            $primary = @($match.Written | Where-Object { $_.Cab.IsPrimary } | ForEach-Object { $_.Cab.Name } | Select-Object -First 1)
            [void]$plan.Groups.Add([pscustomobject]@{ Key = $file.BaseName; Title = $title; Buttons = @($match.Written | Where-Object { -not $_.Cab.IsPrimary }).Count; Primary = ($primary -join ''); NotOnCabinet = $match.NotOnCabinet; NeedsChoice = $match.NeedsChoice })
        } catch {
            [void]$plan.Unreadable.Add($file.BaseName)
            Write-Log "LEDBlinky plan: skipped $($file.Name) -- $_"
        }
    }
    if ($blocks.Count -gt 0) { $plan.BlockText = $newline + ($blocks -join $newline) }
    return $plan
}

# Adds the planned entries. Read first, exact plan checked against the file, verified copy, validated atomic write, undo receipt.
function Invoke-TpmLedBlinkyAdd {
    param([Parameter(Mandatory)]$Install, [Parameter(Mandatory)]$Plan, [Parameter(Mandatory)]$Layout)
    $fail = { param($reason) [pscustomobject]@{ Outcome = 'FAILED'; Added = 0; Summary = $reason; BackupPath = ''; ReceiptPath = '' } }
    try {
        if (-not $Plan.HasEmulator -or $Plan.Groups.Count -eq 0) { return (& $fail 'There is nothing to add.') }
        if (Test-TpmLedBlinkyRunning) { return (& $fail 'LEDBlinky is open. Close LEDBlinky and its editor, then try again. Nothing was changed.') }
        $path = $Install.ControlsPath
        if ((Get-TpmAutoSyncSha256 -Path $path) -ne $Plan.SourceHash) { return (& $fail 'The LEDBlinky file changed after the preview. Run the preview again. Nothing was changed.') }
        $original = Read-TpmLedControlsText -Path $path
        $backupDir = Join-Path $Layout.Backups ('LEDBlinky-{0}' -f (Get-Date -Format 'yyyyMMdd-HHmmss-fff'))
        [void][System.IO.Directory]::CreateDirectory($backupDir)
        if (-not (Test-TpmNoReparsePath -Path $backupDir)) { return (& $fail 'The backup folder is not safe to use. Nothing was changed.') }
        $backupPath = Join-Path $backupDir 'LEDBlinkyControls.xml'
        [System.IO.File]::Copy($path, $backupPath, $false)
        if ((Get-TpmAutoSyncSha256 -Path $backupPath) -ne $Plan.SourceHash) { return (& $fail 'The saved copy could not be verified. Nothing was changed.') }
        $newText = $original.Insert($Plan.InsertAt, $Plan.BlockText)
        $insertAt = $Plan.InsertAt; $blockText = $Plan.BlockText
        $validate = {
            param($written)
            $check = New-Object System.Xml.XmlDocument
            $check.XmlResolver = $null
            $check.LoadXml($written)
            return ($written.Length -eq ($original.Length + $blockText.Length) -and $written.Remove($insertAt, $blockText.Length) -ceq $original)
        }.GetNewClosure()
        Write-TpmAtomicTextFile -Path $path -Text $newText -Validate $validate -Operation 'LEDBlinky control file write'
        $afterHash = Get-TpmAutoSyncSha256 -Path $path
        $receiptPath = Join-Path $Layout.State ('LEDBlinky-Undo-{0}.json' -f (Get-Date -Format 'yyyyMMdd-HHmmss-fff'))
        $receipt = [ordered]@{ Path = $path; BackupPath = $backupPath; BeforeSha256 = $Plan.SourceHash; AfterSha256 = $afterHash; Keys = @($Plan.Groups | ForEach-Object { $_.Key }); Inserted = $blockText }
        Write-TpmAtomicTextFile -Path $receiptPath -Text ($receipt | ConvertTo-Json -Depth 4) -Operation 'LEDBlinky undo record'
        Write-Log ('LEDBlinky add: added={0}; backup={1}; receipt={2}' -f $Plan.Groups.Count, $backupPath, $receiptPath)
        return [pscustomobject]@{ Outcome = 'SAVED'; Added = $Plan.Groups.Count; Summary = ('Added lighting info for {0} to LEDBlinky.' -f (Format-TpmGameCount -Count $Plan.Groups.Count)); BackupPath = $backupPath; ReceiptPath = $receiptPath }
    } catch {
        Write-Log "LEDBlinky add failed -- $_"
        return (& $fail ('The add stopped and LEDBlinky was left as it was. ' + $_.Exception.Message))
    }
}

# Undo: removes exactly the text the last add inserted (and nothing else), after saving the current file.
function Invoke-TpmLedBlinkyUndo {
    param([Parameter(Mandatory)]$Install, [Parameter(Mandatory)]$Layout)
    $result = { param($outcome, $summary) [pscustomobject]@{ Outcome = $outcome; Summary = $summary } }
    try {
        $receiptFile = @(Get-ChildItem -LiteralPath $Layout.State -Filter 'LEDBlinky-Undo-*.json' -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -notlike '*.undone.json' } | Sort-Object Name -Descending | Select-Object -First 1)
        if ($receiptFile.Count -eq 0) { return (& $result 'NONE' 'There is nothing to undo.') }
        if (Test-TpmLedBlinkyRunning) { return (& $result 'FAILED' 'LEDBlinky is open. Close LEDBlinky and its editor, then try again. Nothing was changed.') }
        $receipt = [System.IO.File]::ReadAllText($receiptFile[0].FullName) | ConvertFrom-Json
        $path = $Install.ControlsPath
        $current = Read-TpmLedControlsText -Path $path
        $inserted = [string]$receipt.Inserted
        $at = $current.IndexOf($inserted, [System.StringComparison]::Ordinal)
        if ($at -lt 0 -or $current.IndexOf($inserted, $at + 1, [System.StringComparison]::Ordinal) -ge 0) { return (& $result 'FAILED' 'The entries this tool added are no longer there as one block, so nothing was removed.') }
        $restored = $current.Remove($at, $inserted.Length)
        $beforeUndo = Join-Path (Split-Path -Parent ([string]$receipt.BackupPath)) 'LEDBlinkyControls.before-undo.xml'
        [System.IO.File]::Copy($path, $beforeUndo, $true)
        $validate = { param($written) $check = New-Object System.Xml.XmlDocument; $check.XmlResolver = $null; $check.LoadXml($written); return ($written -ceq $restored) }.GetNewClosure()
        Write-TpmAtomicTextFile -Path $path -Text $restored -Validate $validate -Operation 'LEDBlinky undo'
        Move-Item -LiteralPath $receiptFile[0].FullName -Destination ($receiptFile[0].FullName -replace '\.json$', '.undone.json')
        Write-Log ('LEDBlinky undo: removed {0} entries' -f @($receipt.Keys).Count)
        return (& $result 'SAVED' ('Removed the {0} LEDBlinky entries this tool added. Everything else was kept.' -f @($receipt.Keys).Count))
    } catch {
        Write-Log "LEDBlinky undo failed -- $_"
        return (& $result 'FAILED' ('The undo stopped and LEDBlinky was left as it was. ' + $_.Exception.Message))
    }
}

# Saves the exact new entries as a separate preview file (never overwrites, never touches LEDBlinky).
# Returns the file path, or '' when it could not be saved.
function New-TpmLedPreviewFile {
    param([Parameter(Mandatory)]$Plan, [Parameter(Mandatory)][string]$ReportsFolder)
    $reportPath = Join-Path $ReportsFolder ('TeknoParrot-LEDBlinky-Preview-{0}.xml' -f (Get-Date -Format 'yyyyMMdd-HHmmss'))
    try {
        $body = '<?xml version="1.0"?>' + $Plan.Newline + '<dat>' + $Plan.Newline + '  <emulator emuname="TeknoParrot" emuDesc="">' + $Plan.BlockText + $Plan.Newline + '  </emulator>' + $Plan.Newline + '</dat>' + $Plan.Newline
        Write-TpmAtomicTextFile -Path $reportPath -Text $body -Operation 'LEDBlinky preview file'
        return $reportPath
    } catch { Write-Log "LEDBlinky preview file not saved -- $_"; return '' }
}
# --- Screens: everything below prints or asks; the core above never does. ---

function Get-TpmLedNeedsChoiceCount {
    param([Parameter(Mandatory)]$Plan)
    $total = 0
    if ($null -ne $Plan.Pairing) { $total += @($Plan.Pairing.Held).Count + @($Plan.Pairing.LedsWithoutControl).Count + @($Plan.Pairing.Families).Count }
    foreach ($group in $Plan.Groups) { $total += ([object[]]@($group.NeedsChoice)).Length }
    return $total
}

function Get-TpmLedPlanDetailBlocks {
    param([Parameter(Mandatory)]$Plan)
    $blocks = New-Object System.Collections.Generic.List[object]
    if ($Plan.Pairing) {
        $pairing = $Plan.Pairing
        $paired = @($pairing.Pairs | Where-Object { $_.Status -in @('Paired', 'Primary') }).Count
        $cabinetLines = @(
            ('Controls found in your LEDBlinky setup: {0} (from {1}).' -f @($Plan.Cabinet.Names).Count, $Plan.Cabinet.Source),
            $(if ($pairing.KeyMapFound) { ('LED map: found. Controls paired to an LED: {0}.' -f $paired) } else { 'LED map: not found, so controls were not checked against your LEDs.' }),
            $(if ($pairing.DevicesChecked) { 'Controller check: done (it tells the kinds of devices, not button counts).' } else { 'Controller check: not available, so controls were not checked against your devices.' })
        )
        [void]$blocks.Add(@{ Heading = 'Your cabinet'; Lines = $cabinetLines })
        $choiceLines = New-Object System.Collections.Generic.List[string]
        foreach ($held in @($pairing.Held)) {
            $why = switch ($held.Reason) {
                'NoLed' { 'no LED in your LED map uses it' }
                'Several' { 'more than one LED fits (' + (@($held.Candidates) -join ', ') + ')' }
                default { 'no matching controller was found' }
            }
            [void]$choiceLines.Add(('{0}: {1}. Not written.' -f $held.Name, $why))
        }
        foreach ($label in @($pairing.LedsWithoutControl)) { [void]$choiceLines.Add(('LED {0}: no control in your LEDBlinky setup uses it.' -f $label)) }
        foreach ($family in @($pairing.Families | Where-Object { $_.Status -eq 'DetectedNoControl' })) { [void]$choiceLines.Add(('{0}: a controller was found, but LEDBlinky has no matching control.' -f $family.Family)) }
        if ($choiceLines.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Needs your choice (cabinet)'; Lines = $choiceLines.ToArray() }) }
    }
    [void]$blocks.Add(@{ Heading = 'What gets added'; Lines = @(
        'Where: the TeknoParrot group in LEDBlinkyControls.xml.',
        'Each game gets one entry named after its profile file. It lists only controls the game uses that your LEDBlinky setup has.',
        'Names, colors and input codes are copied from your own setup. Nothing is lit by this tool.') })
    $games = @($Plan.Groups | Select-Object -First 40 | ForEach-Object { '{0} ({1}): {2} lit controls{3}' -f $_.Title, $_.Key, $_.Buttons, $(if ($_.Primary) { ', ' + $_.Primary } else { '' }) })
    if ($Plan.Groups.Count -gt 40) { $games += ('... and {0} more' -f ($Plan.Groups.Count - 40)) }
    if ($games.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Games'; Lines = $games }) }
    $gameChoice = @($Plan.Groups | ForEach-Object { $g = $_; @($g.NeedsChoice) | ForEach-Object { if (@($_.Candidates).Count -gt 0) { '{0}: {1} (could be {2})' -f $g.Title, $_.Label, (@($_.Candidates) -join ', ') } else { '{0}: {1} (no known match)' -f $g.Title, $_.Label } } } | Select-Object -First 40)
    if ($gameChoice.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Needs your choice (games)'; Lines = $gameChoice }) }
    $notOn = @($Plan.Groups | ForEach-Object { @($_.NotOnCabinet) } | Group-Object | Sort-Object Count -Descending | Select-Object -First 30 | ForEach-Object { '{0} ({1})' -f $_.Name, (Format-TpmGameCount -Count $_.Count) })
    if ($notOn.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Not on your cabinet (not written)'; Lines = $notOn }) }
    $skipLines = @()
    if ($Plan.SkippedExisting.Count -gt 0) { $skipLines += ('Already in LEDBlinky, left alone: ' + ($Plan.SkippedExisting -join ', ')) }
    if ($Plan.SkippedNoControls.Count -gt 0) { $skipLines += ('No control on your cabinet matched: ' + ($Plan.SkippedNoControls -join ', ')) }
    if ($Plan.Unreadable.Count -gt 0) { $skipLines += ('Profile could not be read: ' + ($Plan.Unreadable -join ', ')) }
    if ($skipLines.Count -gt 0) { [void]$blocks.Add(@{ Heading = 'Left out'; Lines = $skipLines }) }
    [void]$blocks.Add(@{ Heading = 'What is not proven'; Lines = @(
        'The controls are the ones each profile lists, not a checked list of what the game needs.',
        'The game key matches what LaunchBox passes for TeknoParrot games; it has not been tried with a live LEDBlinky.') })
    return ,@($blocks.ToArray())
}

# Preview: no write to LEDBlinky. Saves the exact new entries as a separate file (never overwrites) and shows the result.
function Write-TpmLedPreview {
    param([Parameter(Mandatory)]$Plan, [Parameter(Mandatory)]$Layout, [switch]$Unattended)
    Write-Log ('LEDBlinky preview: games={0}; existing={1}; noControls={2}; unreadable={3}' -f $Plan.Groups.Count, $Plan.SkippedExisting.Count, $Plan.SkippedNoControls.Count, $Plan.Unreadable.Count)
    $done = New-Object System.Collections.Generic.List[string]
    $needs = New-Object System.Collections.Generic.List[string]
    if (-not $Plan.HasEmulator) {
        [void]$needs.Add('LEDBlinky has no TeknoParrot group yet. Open the LEDBlinky Controls Editor, add TeknoParrot as an emulator, then try again.')
        Write-TpmOutcome -Title 'LEDBlinky is not ready for TeknoParrot yet. Nothing was changed.' -Status Attention -Needs $needs.ToArray() -Unattended:$Unattended
        return
    }
    if (-not $Plan.HasCabinet) {
        [void]$needs.Add('None of your LEDBlinky controls could be matched yet. Press D to see why. You may need to set up your controls in the LEDBlinky Controls Editor.')
        Write-TpmOutcome -Title 'LEDBlinky has no controls to match yet. Nothing was changed.' -Status Attention -Needs $needs.ToArray() -DetailBlocks (Get-TpmLedPlanDetailBlocks -Plan $Plan) -Unattended:$Unattended
        return
    }
    if ($Plan.Groups.Count -gt 0) {
        $reportPath = New-TpmLedPreviewFile -Plan $Plan -ReportsFolder $Layout.Reports
        if ($reportPath) { [void]$done.Add(('A copy of the new entries was saved: {0}' -f [System.IO.Path]::GetFileName($reportPath))) }
        else { [void]$needs.Add('The preview file could not be saved. The preview is still correct.') }
    }
    if ($Plan.SkippedExisting.Count -gt 0) { [void]$done.Add(('{0} already in LEDBlinky and left alone.' -f (Format-TpmGameCount -Count $Plan.SkippedExisting.Count))) }
    $choiceCount = Get-TpmLedNeedsChoiceCount -Plan $Plan
    if ($choiceCount -gt 0) { [void]$needs.Add($(if ($choiceCount -eq 1) { '1 item needs your choice and was not written. Press D to see it.' } else { ('{0} items need your choice and were not written. Press D to see them.' -f $choiceCount) })) }
    $title = if ($Plan.Groups.Count -eq 0) { 'Preview: LEDBlinky already has everything. Nothing would change.' } else { ('Preview: LEDBlinky would get lighting info for {0}. Nothing was changed.' -f (Format-TpmGameCount -Count $Plan.Groups.Count)) }
    $next = if ($Plan.Groups.Count -gt 0) { 'Choose A to add them, or press D first to see the games.' } else { '' }
    Write-TpmOutcome -Title $title -Status Ok -Done $done.ToArray() -NotChanged 'Your LEDBlinky files were not touched.' -Needs $needs.ToArray() -Next $next -DetailBlocks (Get-TpmLedPlanDetailBlocks -Plan $Plan) -Unattended:$Unattended
}

function Write-TpmLedResult {
    param([Parameter(Mandatory)]$Result, [switch]$Unattended)
    $status = if ($Result.Outcome -eq 'FAILED') { 'Problem' } else { 'Ok' }
    $done = @()
    if ($Result.PSObject.Properties['BackupPath'] -and $Result.BackupPath) { $done += ('A saved copy of the LEDBlinky file was made first: {0}' -f (Split-Path -Leaf (Split-Path -Parent $Result.BackupPath))) }
    $next = if ($Result.Outcome -eq 'SAVED' -and $Result.PSObject.Properties['Added']) { 'To go back, run this step again and choose U.' } else { '' }
    Write-TpmOutcome -Title $Result.Summary -Status $status -Done $done -Next $next -Unattended:$Unattended
}

# Local drive roots such as "C:" and "E:" (network drives are left out), using the Manager's existing drive check.
function Get-TpmLedLocalDriveRoots {
    $info = Get-LocalDriveInfoSafe
    if ($null -eq $info) { return @() }
    return @(Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue |
        Where-Object { $_.Root -and (Test-IsNetworkPath $_.Root -Drives $info) -eq $false -and (Test-Path -LiteralPath $_.Root) } |
        ForEach-Object { $_.Root.TrimEnd('\') })
}

# Asks for the LEDBlinky folder (typed, pasted, or B to browse) until it is a real one. Empty answer or closed browser = skip.
function Read-TpmLedBlinkyFolder {
    while ($true) {
        $answer = ([string](Read-PathWithBrowse -Prompt '  LEDBlinky folder (Enter to skip)' -Mode Folder)).Trim().Trim('"')
        if (-not $answer) { return $null }
        $problem = Get-TpmLedBlinkyFolderProblem -Path $answer
        if (-not $problem) { return (Find-TpmLedBlinky -Candidates @($answer)) }
        if ($problem -eq 'NoFolder') { Write-TpmText -Text 'That folder was not found. Check the path and try again.' -Color Yellow }
        else { Write-TpmText -Text 'That folder does not have the LEDBlinky control file (LEDBlinkyControls.xml). Pick the folder where LEDBlinky is installed.' -Color Yellow }
    }
}

# Finds LEDBlinky quietly in the usual places. If it is not there, asks once in plain words. Returns the install or $null.
function Invoke-TpmLedBlinkyLocate {
    param([string]$SavedFolder = '', [string]$LaunchBoxRoot = '')
    Write-TpmText -Text 'Optional: lighting for your arcade buttons.' -Color Cyan -BlankBefore
    $candidates = Get-TpmLedBlinkyCandidateFolders -SavedFolder $SavedFolder -LaunchBoxRoot $LaunchBoxRoot -DriveRoots @(Get-TpmLedLocalDriveRoots) -ProgramFilesFolders @($env:ProgramFiles, ${env:ProgramFiles(x86)})
    $found = Find-TpmLedBlinky -Candidates $candidates
    if ($found) { return $found }
    Write-TpmText -Text 'Do you use LEDBlinky? Show me where it is.' -Color White
    Write-TpmText -Text '[F] Show the LEDBlinky folder.' -Color White
    Write-TpmText -Text '[S] Skip this step.' -Color White
    if ((Read-TpmChoice -Prompt '  Choice, default S' -Choices @('F', 'S') -Default 'S') -eq 'S') { return $null }
    return (Read-TpmLedBlinkyFolder)
}
# The optional step shown after LaunchBox: short choices, preview first.
function Invoke-TpmLedBlinkyStep {
    param([Parameter(Mandatory)]$Install, [Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)]$Layout, $State = $null, [string[]]$ImageFolders = @())
    $evidence = $null
    try { $evidence = Get-TpmControllerEvidence } catch { Write-Log "LEDBlinky: the controller check could not run -- $_" }
    Write-TpmText -Text 'LEDBlinky was found on this PC.' -Color White
    Write-TpmText -Text '[P] Preview first. No changes.' -Color White
    Write-TpmText -Text '[A] Add lighting info to LEDBlinky (backed up, can be undone).' -Color White
    Write-TpmText -Text '[U] Undo the last add.' -Color White
    Write-TpmText -Text '[C] Use a different LEDBlinky folder.' -Color White
    Write-TpmText -Text '[O] Switch between the usual arcade colors and your own colors. Now: the usual arcade colors.' -Color White
    Write-TpmText -Text '[B] Skip this step.' -Color White
    $plan = $null
    $keepOwnColors = $false
    do {
        $choice = Read-TpmChoice -Prompt '  Choice, default P' -Choices @('P', 'A', 'U', 'C', 'O', 'B') -Default 'P'
        if ($choice -eq 'O') {
            $keepOwnColors = -not $keepOwnColors
            Write-TpmText -Text $(if ($keepOwnColors) { 'Now using your own colors.' } else { 'Now using the usual arcade colors.' }) -Color DarkCyan
        }
        if ($choice -eq 'P') {
            try { $plan = Get-TpmLedExportPlan -UserProfilesDir $UserProfilesDir -ControlsPath $Install.ControlsPath -Evidence $evidence -ImageFolders $ImageFolders -KeepOwnColors:$keepOwnColors; Write-TpmLedPreview -Plan $plan -Layout $Layout }
            catch { Write-Log "LEDBlinky preview failed -- $_"; Write-TpmText -Text ('LEDBlinky preview stopped. Nothing was changed. {0}' -f $_.Exception.Message) -Color Yellow }
        }
        if ($choice -eq 'C') {
            $newInstall = Read-TpmLedBlinkyFolder
            if ($newInstall) {
                $Install = $newInstall
                if ($null -ne $State) { $State.Folder = $newInstall.Root }
                Write-TpmText -Text 'Now using that LEDBlinky folder.' -Color DarkCyan
            }
        }
    } while ($choice -in @('P', 'C', 'O'))
    if ($choice -eq 'A') {
        try { $plan = Get-TpmLedExportPlan -UserProfilesDir $UserProfilesDir -ControlsPath $Install.ControlsPath -Evidence $evidence -ImageFolders $ImageFolders -KeepOwnColors:$keepOwnColors } catch { Write-Log "LEDBlinky plan failed -- $_"; Write-TpmText -Text ('LEDBlinky could not be read. Nothing was changed. {0}' -f $_.Exception.Message) -Color Yellow; return }
        Write-TpmLedPreview -Plan $plan -Layout $Layout
        if ($plan.HasEmulator -and $plan.Groups.Count -gt 0) {
            Write-TpmText -Text 'Close LEDBlinky and its editor first. TeknoParrot Manager will not close them for you.' -Color Yellow -BlankBefore
            if ((Read-TpmYesNo -Prompt 'Add exactly these entries after saving a copy? (Y/N)' -Default 'N') -eq 'Y') {
                Write-TpmLedResult -Result (Invoke-TpmLedBlinkyAdd -Install $Install -Plan $plan -Layout $Layout)
            } else { Write-TpmText -Text 'Nothing was changed.' -Color DarkGray }
        }
    } elseif ($choice -eq 'U') {
        if ((Read-TpmYesNo -Prompt 'Remove the entries this tool added to LEDBlinky last time? (Y/N)' -Default 'N') -eq 'Y') {
            Write-TpmLedResult -Result (Invoke-TpmLedBlinkyUndo -Install $Install -Layout $Layout)
        } else { Write-TpmText -Text 'Nothing was changed.' -Color DarkGray }
    }
}

# END TpmLed MODULE SECTION

# =============================================================================
# LAUNCHBOX IMAGE IMPORT  (clear logos / box art from a folder the user picks)
# =============================================================================
# Nothing is downloaded: every picture comes from a folder the user chooses. Only games the Manager added are
# considered (their emulator is the TeknoParrot emulator and their profile is in the user profiles folder).
# Pictures are copied to <LaunchBox>\Images\<Platform>\<Clear Logo | Box - Front>\<Title>-01.<ext>.
# A picture that is already there is kept unless the user chooses to replace it (the old one is saved first).
# Every import writes a small record outside the library so Undo can remove exactly what was added.
#
# MODULE-READY SECTION (meant to be lifted into a .psm1 after 1.0; nothing outside this section calls its private helpers).
#   Public, pure data/logic (no prompts, no screen output; only Write-Log for the log file):
#     Get-TpmLaunchBoxMediaPlan       read-only preview: exact matches, near matches, games with no picture, games kept
#     Invoke-TpmLaunchBoxMediaImport  the only writer: copies the selected pictures and writes the undo record
#     Invoke-TpmLaunchBoxMediaUndo    removes exactly what one import added (restores replaced pictures)
#   Public, screen (calls only the three functions above plus the shared prompt/screen helpers):
#     Invoke-TpmLaunchBoxMediaStep    the optional step shown after the LaunchBox choices
#   Private helpers: Get-TpmLbMedia*, ConvertTo-TpmLbMediaKey, Undo-TpmLbMediaRecords, Write-TpmLbMediaOutcome
#   Depends on (outside this section): Resolve-TpmLaunchBoxRoot, Read-TpmLaunchBoxXml, Get-TpmLaunchBoxPath,
#     Get-SafeLaunchBoxPlatformFileName, Get-TpmLaunchBoxBackupRoot, Get-XmlChildText, Get-RelativePath, Test-PathInside,
#     Test-TpmNoReparsePath, Assert-TpmNoReparseWriteTarget, Get-NormalizedGameKey (same name clean-up the DAT matching uses),
#     Write-Log; screen only: Read-TpmChoice, Read-TpmYesNo, Read-HostSafe, Write-TpmText, Write-TpmOutcome,
#     Show-TpmDetailBlocks, Format-TpmGameCount.
#   No script-level variables are used: all state goes through parameters and returned objects.
#   The Eggman DAT lists game folder names, not pictures, so it has no media data; its name clean-up is reused for file names.

function Get-TpmLbMediaFolderName {
    param([string]$Kind)
    switch ($Kind) {
        'ClearLogo' { return 'Clear Logo' }
        'BoxFront' { return 'Box - Front' }
        default { throw 'Unknown picture type.' }
    }
}

# File-name form of a game title (characters Windows does not allow become underscores).
function Get-TpmLbMediaSafeName {
    param([string]$Title)
    $name = [string]$Title
    foreach ($ch in @([System.IO.Path]::GetInvalidFileNameChars() + [char]"'")) { $name = $name.Replace([string]$ch, '_') }
    return $name.TrimEnd('.', ' ')
}

# Lower-case words without accents or punctuation; a trailing LaunchBox "-01" counter is dropped.
function ConvertTo-TpmLbMediaKey {
    param([string]$Text)
    $t = [regex]::Replace([string]$Text, '-\d{2}$', '')
    # Same clean-up the DAT matching uses: drops [tags], (World)/(JPN) style region marks and version notes.
    $t = Get-NormalizedGameKey $t
    $decomposed = $t.Normalize([System.Text.NormalizationForm]::FormD)
    $sb = New-Object System.Text.StringBuilder
    foreach ($c in $decomposed.ToCharArray()) {
        if ([System.Globalization.CharUnicodeInfo]::GetUnicodeCategory($c) -ne [System.Globalization.UnicodeCategory]::NonSpacingMark) { [void]$sb.Append($c) }
    }
    $t = $sb.ToString().ToLowerInvariant().Replace('&', ' and ')
    return ([regex]::Replace($t, '[^a-z0-9]+', ' ').Trim())
}

function Get-TpmLbMediaLooseKey {
    param([string]$Key)
    $words = @(([string]$Key -split ' ') | Where-Object { $_ -and $_ -notin @('the', 'a', 'an', 'and') })
    return ($words -join '')
}

function Get-TpmLbMediaSimilarity {
    param([string]$Left, [string]$Right)
    $max = [Math]::Max($Left.Length, $Right.Length)
    if ($max -eq 0) { return 0.0 }
    $prev = New-Object 'int[]' ($Right.Length + 1)
    for ($j = 0; $j -le $Right.Length; $j++) { $prev[$j] = $j }
    for ($i = 1; $i -le $Left.Length; $i++) {
        $cur = New-Object 'int[]' ($Right.Length + 1)
        $cur[0] = $i
        for ($j = 1; $j -le $Right.Length; $j++) {
            $cost = if ($Left[$i - 1] -ceq $Right[$j - 1]) { 0 } else { 1 }
            $cur[$j] = [Math]::Min([Math]::Min($cur[$j - 1] + 1, $prev[$j] + 1), $prev[$j - 1] + $cost)
        }
        $prev = $cur
    }
    return (1.0 - ($prev[$Right.Length] / $max))
}

# Games the Manager added to LaunchBox: emulator is TeknoParrot's and the profile lives in the user profiles folder.
function Get-TpmLbMediaGames {
    param([string]$lbRoot, [string]$userProfilesDir, [string[]]$platformNames)
    $emulatorsDoc = Read-TpmLaunchBoxXml (Get-TpmLaunchBoxPath $lbRoot 'Data\Emulators.xml')
    $emulatorIds = @($emulatorsDoc.SelectNodes('/LaunchBox/Emulator') | Where-Object { (Get-XmlChildText $_ 'Title') -eq 'TeknoParrot' } | ForEach-Object { Get-XmlChildText $_ 'ID' })
    $games = New-Object System.Collections.Generic.List[object]
    if ($emulatorIds.Count -eq 0) { return ,@() }
    foreach ($name in $platformNames) {
        $safe = Get-SafeLaunchBoxPlatformFileName $name
        if ($safe -cne $name -or $name -in @('.', '..')) { throw 'Platform name must be a safe, unambiguous filename.' }
        $path = Get-TpmLaunchBoxPath $lbRoot ("Data\Platforms\$safe.xml")
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { continue }
        $doc = Read-TpmLaunchBoxXml $path
        foreach ($node in @($doc.SelectNodes('/LaunchBox/Game'))) {
            if ((Get-XmlChildText $node 'Emulator') -notin $emulatorIds) { continue }
            $appPath = Get-XmlChildText $node 'ApplicationPath'
            $title = Get-XmlChildText $node 'Title'
            if (-not $appPath -or -not $title) { continue }
            $full = if ([System.IO.Path]::IsPathRooted($appPath)) { $appPath } else { Join-Path $lbRoot $appPath }
            if (-not (Test-PathInside -child $full -parent $userProfilesDir)) { continue }
            [void]$games.Add([pscustomobject]@{ Platform = $name; Title = $title; Code = [System.IO.Path]::GetFileNameWithoutExtension($full); ProfilePath = $full; DatabaseId = (Get-XmlChildText $node 'DatabaseID').Trim() })
        }
    }
    return ,@($games.ToArray())
}

# READ-ONLY preview. Exact = the same game, one picture only. The same game means: the same name (ignoring case, accents, spaces and
# punctuation) or, when the game list is given, one of the official or other names of the game's Games Database ID. A picture whose
# name the shared matching engine reads as a different game (a different ID) is never used. Near = a close name, or several pictures
# for the game; the user must confirm each one.
function Get-TpmLaunchBoxMediaPlan {
    param([string]$lbRoot, [string]$userProfilesDir, [string]$imageFolder, [string[]]$platformNames, [ValidateSet('ClearLogo', 'BoxFront')][string]$Kind = 'ClearLogo', [switch]$ReplaceExisting, [string]$TpRoot = '', [hashtable]$DatIndex = $null, $GameList = $null)
    $lbRoot = Resolve-TpmLaunchBoxRoot $lbRoot
    if (-not (Test-Path -LiteralPath $lbRoot -PathType Container) -or -not (Test-TpmNoReparsePath $lbRoot)) { throw 'Choose a safe existing LaunchBox folder.' }
    if ([string]::IsNullOrWhiteSpace($imageFolder) -or -not (Test-Path -LiteralPath $imageFolder -PathType Container) -or -not (Test-TpmNoReparsePath $imageFolder)) { throw 'Choose a folder that exists and holds your pictures.' }
    if (@($platformNames).Count -eq 0) { throw 'Choose at least one LaunchBox platform.' }
    $kindFolder = Get-TpmLbMediaFolderName $Kind
    $index = @(Get-ChildItem -LiteralPath $imageFolder -Recurse -File -ErrorAction Stop |
        Where-Object { @('.png', '.jpg', '.jpeg') -contains $_.Extension.ToLowerInvariant() -and -not ($_.Attributes -band [System.IO.FileAttributes]::ReparsePoint) } |
        Sort-Object FullName | ForEach-Object {
            $key = ConvertTo-TpmLbMediaKey ([System.IO.Path]::GetFileNameWithoutExtension($_.Name))
            [pscustomobject]@{ File = $_; Compact = $key.Replace(' ', ''); Loose = (Get-TpmLbMediaLooseKey $key) }
        })
    $exact = New-Object System.Collections.Generic.List[object]
    $near = New-Object System.Collections.Generic.List[object]
    $noImage = New-Object System.Collections.Generic.List[object]
    $existing = New-Object System.Collections.Generic.List[object]
    $games = Get-TpmLbMediaGames -lbRoot $lbRoot -userProfilesDir $userProfilesDir -platformNames $platformNames
    # With the game list: the ID of each game (the one LaunchBox holds, else a certain engine match) and of each picture name, and every
    # name a game ID is known by. Without it the plan works by name only.
    $datByCode = if ($null -ne $GameList) { Get-TpmDatEntriesByCode -DatIndex $DatIndex } else { $null }
    $altNames = @{}
    if ($null -ne $GameList) {
        foreach ($altKey in $GameList.ByAlternate.Keys) {
            foreach ($entry in $GameList.ByAlternate[$altKey]) {
                if (-not $altNames.ContainsKey($entry.Id)) { $altNames[$entry.Id] = New-Object System.Collections.Generic.List[string] }
                [void]$altNames[$entry.Id].Add(([regex]::Replace([string]$altKey, '[^a-z0-9]', '')))
            }
        }
    }
    $imageIds = @{}
    $getImageId = {
        param($item)
        if ($null -eq $GameList) { return '' }
        if (-not $imageIds.ContainsKey($item.File.FullName)) {
            $base = [regex]::Replace([System.IO.Path]::GetFileNameWithoutExtension($item.File.Name), '-\d{2}$', '')
            $found = Resolve-TpmGameMatch -Index $GameList -Subject (New-TpmMatchSubject -MetadataName $base)
            $imageIds[$item.File.FullName] = $(if ($found.Status -eq 'Certain') { [string]$found.Match.Id } else { '' })
        }
        return $imageIds[$item.File.FullName]
    }
    foreach ($game in $games) {
        $safe = Get-TpmLbMediaSafeName $game.Title
        $destDir = Join-Path (Join-Path (Join-Path $lbRoot 'Images') $game.Platform) $kindFolder
        $have = @()
        if (Test-Path -LiteralPath $destDir -PathType Container) { $have = @(Get-ChildItem -LiteralPath $destDir -File -Filter ($safe + '-01.*') -ErrorAction Stop) }
        if ($have.Count -gt 0 -and -not $ReplaceExisting) { [void]$existing.Add([pscustomobject]@{ Game = $game; Existing = $have[0].FullName }); continue }
        $key = ConvertTo-TpmLbMediaKey $game.Title
        $compact = $key.Replace(' ', ''); $loose = Get-TpmLbMediaLooseKey $key
        $gameId = ''
        if ($null -ne $GameList) {
            $gameId = [string]$game.DatabaseId
            if (-not $gameId -or $gameId -eq '0') {
                $gameId = ''
                $subject = if (Test-Path -LiteralPath $game.ProfilePath -PathType Leaf) { Get-TpmProfileMatchSubject -Code $game.Code -ProfilePath $game.ProfilePath -TpRoot $TpRoot -HintName $game.Title -DatIndex $DatIndex -DatByCode $datByCode } else { New-TpmMatchSubject -Code $game.Code -HintName $game.Title }
                if (-not $subject.NotGame) { $found = Resolve-TpmGameMatch -Index $GameList -Subject $subject; if ($found.Status -eq 'Certain') { $gameId = [string]$found.Match.Id } }
            }
        }
        # Names of this game's ID, and the pictures that are not a different game.
        $nameKeys = New-Object System.Collections.Generic.List[string]
        if ($compact) { [void]$nameKeys.Add($compact) }
        if ($gameId -and $GameList.ById.ContainsKey($gameId)) { [void]$nameKeys.Add((ConvertTo-TpmLbMediaKey $GameList.ById[$gameId].Name).Replace(' ', '')) }
        if ($gameId -and $altNames.ContainsKey($gameId)) { foreach ($altCompact in $altNames[$gameId]) { [void]$nameKeys.Add($altCompact) } }
        $notOther = { param($item) if (-not $gameId) { return $true }; $imageId = & $getImageId $item; return (-not $imageId -or $imageId -eq $gameId) }
        $same = @(); $close = @()
        if ($compact) {
            $same = @($index | Where-Object { $nameKeys -ccontains $_.Compact } | Where-Object { & $notOther $_ })
            if ($same.Count -eq 0) {
                $close = @($index | ForEach-Object {
                    $sim = Get-TpmLbMediaSimilarity $compact $_.Compact
                    if ($_.Loose -ceq $loose -or ($compact.Length -ge 6 -and $sim -ge 0.9)) { [pscustomobject]@{ Item = $_; Sim = $sim } }
                } | Where-Object { & $notOther $_.Item } | Sort-Object @{ Expression = 'Sim'; Descending = $true } | Select-Object -First 3)
            }
        }
        $replaces = if ($have.Count -gt 0) { $have[0].FullName } else { $null }
        if ($same.Count -eq 1) {
            $dest = Join-Path $destDir ($safe + '-01' + $same[0].File.Extension.ToLowerInvariant())
            [void]$exact.Add([pscustomobject]@{ Game = $game; Image = $same[0].File.FullName; Dest = $dest; Replaces = $replaces })
        } elseif ($same.Count -gt 1 -or $close.Count -gt 0) {
            $cands = if ($same.Count -gt 1) { @($same | ForEach-Object { $_.File }) } else { @($close | ForEach-Object { $_.Item.File }) }
            $why = if ($same.Count -gt 1) { 'More than one picture has this name.' } else { 'The name is close, not the same.' }
            [void]$near.Add([pscustomobject]@{ Game = $game; Candidates = @($cands | ForEach-Object { [pscustomobject]@{ Image = $_.FullName; Dest = (Join-Path $destDir ($safe + '-01' + $_.Extension.ToLowerInvariant())) } }); Reason = $why; Replaces = $replaces })
        } else {
            [void]$noImage.Add([pscustomobject]@{ Game = $game })
        }
    }
    return [pscustomobject]@{ LaunchBoxRoot = $lbRoot; ImageFolder = $imageFolder; Kind = $Kind; KindFolder = $kindFolder; ImageCount = $index.Count; GameCount = @($games).Count
        Exact = @($exact.ToArray()); Near = @($near.ToArray()); NoImage = @($noImage.ToArray()); Existing = @($existing.ToArray()); ReplaceExisting = [bool]$ReplaceExisting }
}

function Get-TpmLbMediaImportsRoot {
    param([string]$lbRoot, [string]$BackupRoot)
    $base = Get-TpmLaunchBoxBackupRoot -BackupRoot $BackupRoot -LaunchBoxRoot $lbRoot
    $root = Join-Path (Split-Path -Parent $base) 'LaunchBoxMediaImports'
    if (Test-PathInside -child $root -parent $lbRoot) { throw 'Picture import records must be kept outside the LaunchBox folder.' }
    return $root
}

# Full path of a recorded picture; refuses anything that is not a picture path inside <LaunchBox>\Images.
function Get-TpmLbMediaRecordedPath {
    param([string]$lbRoot, [string]$RelativePath)
    if ($RelativePath -notmatch '^Images\\[^\\/:*?"<>|]+\\(?:Clear Logo|Box - Front)\\[^\\/:*?"<>|]+$' -or $RelativePath -match '(^|\\)\.\.(\\|$)') { throw 'Invalid recorded picture path.' }
    $full = [System.IO.Path]::GetFullPath((Join-Path $lbRoot $RelativePath))
    if (-not (Test-PathInside -child $full -parent (Join-Path $lbRoot 'Images')) -or -not (Test-TpmNoReparsePath -Path $full)) { throw 'Unsafe picture path.' }
    return $full
}

function Undo-TpmLbMediaRecords {
    param([string]$lbRoot, [object[]]$Added, [object[]]$Replaced, [string[]]$CreatedDirs, [string]$ImportDir)
    $kept = New-Object System.Collections.Generic.List[string]
    $removed = 0; $restored = 0
    foreach ($a in @($Added)) {
        $full = Get-TpmLbMediaRecordedPath $lbRoot $a.Path
        if (-not [System.IO.File]::Exists($full)) { continue }
        if ((Get-FileHash -LiteralPath $full -Algorithm SHA256).Hash -ne $a.Hash) { [void]$kept.Add([string]$a.Path); continue }
        [System.IO.File]::Delete($full); $removed++
    }
    foreach ($r in @($Replaced)) {
        $full = Get-TpmLbMediaRecordedPath $lbRoot $r.Path
        $saved = Join-Path $ImportDir $r.Saved
        if ([System.IO.File]::Exists($full)) { [void]$kept.Add([string]$r.Path); continue }
        if (-not [System.IO.File]::Exists($saved)) { [void]$kept.Add([string]$r.Path); continue }
        [System.IO.File]::Move($saved, $full); $restored++
    }
    foreach ($d in @($CreatedDirs | Sort-Object { $_.Length } -Descending)) {
        try {
            $full = [System.IO.Path]::GetFullPath((Join-Path $lbRoot $d))
            if ((Test-PathInside -child $full -parent (Join-Path $lbRoot 'Images')) -and (Test-Path -LiteralPath $full -PathType Container) -and @(Get-ChildItem -LiteralPath $full -Force).Count -eq 0) { [System.IO.Directory]::Delete($full, $false) }
        } catch { Write-Log ('LaunchBox pictures: could not remove the empty folder {0}: {1}' -f $d, $_.Exception.Message) }
    }
    return [pscustomobject]@{ Removed = $removed; Restored = $restored; Kept = @($kept.ToArray()) }
}

# WRITES. $Selected = items with Game, Image, Dest, Replaces (exact matches plus the near matches the user confirmed).
function Invoke-TpmLaunchBoxMediaImport {
    param([string]$lbRoot, [object[]]$Selected, [string]$BackupRoot, [switch]$ReplaceExisting)
    $result = [pscustomobject]@{ Outcome = 'FAILED'; Summary = 'No pictures were copied.'; AddedCount = 0; ReplacedCount = 0; SkippedCount = 0; ImportPath = $null; Errors = @() }
    $added = New-Object System.Collections.Generic.List[object]
    $replaced = New-Object System.Collections.Generic.List[object]
    $createdDirs = New-Object System.Collections.Generic.List[string]
    $importDir = $null
    try {
        $lbRoot = Resolve-TpmLaunchBoxRoot $lbRoot
        if (@($Selected).Count -eq 0) { $result.Outcome = 'NO_CHANGES'; $result.Summary = 'There was nothing to copy.'; return $result }
        $importsRoot = Get-TpmLbMediaImportsRoot -lbRoot $lbRoot -BackupRoot $BackupRoot
        $importDir = Join-Path $importsRoot ((Get-Date).ToString('yyyy-MM-dd_HH-mm-ss', [System.Globalization.CultureInfo]::InvariantCulture) + '-' + [guid]::NewGuid().ToString('N'))
        Assert-TpmNoReparseWriteTarget -Path $importDir -Operation 'LaunchBox picture record'
        [void][System.IO.Directory]::CreateDirectory($importDir)
        $result.ImportPath = $importDir
        $n = 0
        foreach ($item in $Selected) {
            $rel = Get-RelativePath $lbRoot $item.Dest
            $dest = Get-TpmLbMediaRecordedPath $lbRoot $rel
            if (-not (Test-Path -LiteralPath $item.Image -PathType Leaf) -or -not (Test-TpmNoReparsePath -Path $item.Image)) { throw ('The picture is gone or not safe to read: ' + $item.Image) }
            $dir = [System.IO.Path]::GetDirectoryName($dest)
            $walk = $dir; $toMake = @()
            while (-not (Test-Path -LiteralPath $walk)) { $toMake = @($walk) + $toMake; $walk = [System.IO.Path]::GetDirectoryName($walk) }
            foreach ($m in $toMake) { Assert-TpmNoReparseWriteTarget -Path $m -Operation 'LaunchBox picture folder'; [void][System.IO.Directory]::CreateDirectory($m); [void]$createdDirs.Add((Get-RelativePath $lbRoot $m)) }
            $safe = [System.IO.Path]::GetFileNameWithoutExtension($dest)
            $current = @(Get-ChildItem -LiteralPath $dir -File -Filter ($safe + '.*') -ErrorAction Stop)
            if ($current.Count -gt 0) {
                if (-not $ReplaceExisting) { $result.SkippedCount++; continue }
                foreach ($old in $current) {
                    $n++
                    $savedName = ('replaced-{0}.bin' -f $n)
                    $oldHash = (Get-FileHash -LiteralPath $old.FullName -Algorithm SHA256).Hash
                    Copy-Item -LiteralPath $old.FullName -Destination (Join-Path $importDir $savedName) -ErrorAction Stop
                    if ((Get-FileHash -LiteralPath (Join-Path $importDir $savedName) -Algorithm SHA256).Hash -ne $oldHash) { throw 'The saved copy of an old picture could not be verified.' }
                    [void]$replaced.Add([pscustomobject]@{ Path = (Get-RelativePath $lbRoot $old.FullName); Saved = $savedName; Hash = $oldHash })
                    [System.IO.File]::Delete($old.FullName)
                }
            }
            Assert-TpmNoReparseWriteTarget -Path $dest -Operation 'LaunchBox picture copy'
            $tmp = $dest + '.' + [guid]::NewGuid().ToString('N') + '.tmp'
            Copy-Item -LiteralPath $item.Image -Destination $tmp -ErrorAction Stop
            $srcHash = (Get-FileHash -LiteralPath $item.Image -Algorithm SHA256).Hash
            if ((Get-FileHash -LiteralPath $tmp -Algorithm SHA256).Hash -ne $srcHash) { [System.IO.File]::Delete($tmp); throw 'A copied picture did not match its source.' }
            [System.IO.File]::Move($tmp, $dest)
            [void]$added.Add([pscustomobject]@{ Path = $rel; Hash = $srcHash })
        }
        $manifestPath = Join-Path $importDir 'manifest.json'
        $text = [pscustomobject]@{ Schema = 1; LaunchBoxRoot = $lbRoot; Added = @($added.ToArray()); Replaced = @($replaced.ToArray()); CreatedDirs = @($createdDirs.ToArray()) } | ConvertTo-Json -Depth 5
        [System.IO.File]::WriteAllText($manifestPath, $text, (New-Object System.Text.UTF8Encoding $false))
        if ([System.IO.File]::ReadAllText($manifestPath) -cne $text) { throw 'The undo record could not be verified.' }
        $result.AddedCount = $added.Count; $result.ReplacedCount = $replaced.Count
        if ($added.Count -eq 0) {
            [System.IO.Directory]::Delete($importDir, $true); $result.ImportPath = $null
            $result.Outcome = 'NO_CHANGES'; $result.Summary = 'Nothing was copied.'
        } else {
            $result.Outcome = 'SAVED'; $result.Summary = 'Copied {0} picture(s).' -f $added.Count
        }
        Write-Log ('LaunchBox pictures: outcome={0}; added={1}; replaced={2}; record={3}' -f $result.Outcome, $result.AddedCount, $result.ReplacedCount, $result.ImportPath)
    } catch {
        $result.Errors += [string]$_.Exception.Message
        Write-Log ('LaunchBox pictures: failed, undoing what was copied -- {0}' -f $_.Exception.Message)
        try {
            if ($importDir) {
                $undo = Undo-TpmLbMediaRecords -lbRoot $lbRoot -Added @($added.ToArray()) -Replaced @($replaced.ToArray()) -CreatedDirs @($createdDirs.ToArray()) -ImportDir $importDir
                if ($undo.Kept.Count -eq 0) { [System.IO.Directory]::Delete($importDir, $true); $result.ImportPath = $null; $result.Summary = 'Something went wrong. Everything that was copied has been removed again.' }
                else { $result.Outcome = 'PARTIAL'; $result.Summary = 'Something went wrong and some pictures could not be removed again.'; $result.Errors += ('Left in place: ' + ($undo.Kept -join ', ')) }
            }
        } catch { $result.Outcome = 'PARTIAL'; $result.Errors += ('Undo after the failure also failed: ' + $_.Exception.Message) }
        $result.AddedCount = 0
    }
    return $result
}

# Undo the newest picture import (or the one at ImportPath). Removes only files whose bytes are still the ones that were added.
function Invoke-TpmLaunchBoxMediaUndo {
    param([string]$lbRoot, [string]$BackupRoot, [string]$ImportPath)
    $result = [pscustomobject]@{ Outcome = 'FAILED'; Summary = ''; Removed = 0; Restored = 0; Kept = @(); Errors = @() }
    try {
        $lbRoot = Resolve-TpmLaunchBoxRoot $lbRoot
        if (-not $ImportPath) {
            $importsRoot = Get-TpmLbMediaImportsRoot -lbRoot $lbRoot -BackupRoot $BackupRoot
            $latest = $null
            if (Test-Path -LiteralPath $importsRoot -PathType Container) {
                $latest = @(Get-ChildItem -LiteralPath $importsRoot -Directory -ErrorAction Stop | Where-Object { Test-Path -LiteralPath (Join-Path $_.FullName 'manifest.json') } | Sort-Object Name -Descending) | Select-Object -First 1
            }
            if (-not $latest) { $result.Outcome = 'NO_CHANGES'; $result.Summary = 'There is no picture import to undo.'; return $result }
            $ImportPath = $latest.FullName
        }
        $manifest = [System.IO.File]::ReadAllText((Join-Path $ImportPath 'manifest.json')) | ConvertFrom-Json -ErrorAction Stop
        if ($manifest.Schema -ne 1 -or [string]$manifest.LaunchBoxRoot -ine $lbRoot) { throw 'This import record belongs to a different LaunchBox folder, so it was not used.' }
        $undo = Undo-TpmLbMediaRecords -lbRoot $lbRoot -Added @($manifest.Added) -Replaced @($manifest.Replaced) -CreatedDirs @($manifest.CreatedDirs) -ImportDir $ImportPath
        $result.Removed = $undo.Removed; $result.Restored = $undo.Restored; $result.Kept = @($undo.Kept)
        if ($undo.Kept.Count -eq 0) {
            [System.IO.Directory]::Delete($ImportPath, $true)
            $result.Outcome = 'SAVED'; $result.Summary = 'Removed {0} picture(s) that were added.' -f $undo.Removed
        } else {
            $result.Outcome = 'PARTIAL'; $result.Summary = 'Removed {0} picture(s). {1} could not be removed because they changed after the import.' -f $undo.Removed, $undo.Kept.Count
        }
        Write-Log ('LaunchBox pictures undo: outcome={0}; removed={1}; restored={2}; kept={3}' -f $result.Outcome, $undo.Removed, $undo.Restored, ($undo.Kept -join ','))
    } catch {
        $result.Errors += [string]$_.Exception.Message
        $result.Summary = 'The undo was stopped before anything else was changed.'
    }
    return $result
}

function Write-TpmLbMediaOutcome {
    param($Result, [string]$Title)
    $status = switch ([string]$Result.Outcome) { 'FAILED' { 'Problem' } 'PARTIAL' { 'Attention' } default { 'Ok' } }
    $lines = @($Result.Errors | ForEach-Object { 'Reason: ' + $_ })
    if ($Result.PSObject.Properties['Kept'] -and @($Result.Kept).Count -gt 0) { $lines += @($Result.Kept | ForEach-Object { 'Left in place: ' + $_ }) }
    $blocks = if ($lines.Count -gt 0) { @(@{ Heading = 'Picture details'; Lines = $lines }) } else { @() }
    $next = if ($lines.Count -gt 0) { 'Press D to see what happened.' } else { '' }
    Write-TpmOutcome -Title $Title -Status $status -Next $next -DetailBlocks $blocks
}

# The optional step shown after the LaunchBox choices. Skipped in Unattended and preview runs.
function Invoke-TpmLaunchBoxMediaStep {
    param([string]$lbRoot, [string]$userProfilesDir, [switch]$Unattended, [switch]$DryRun, [string]$TpRoot = '', [hashtable]$DatIndex = $null)
    if ($DryRun) { Write-Log 'PreviewMode: LaunchBox picture import skipped.'; return }
    if ($Unattended) { Write-Log 'Unattended: LaunchBox picture import skipped.'; return }
    Write-TpmText -Text 'Optional: add logos or box art to LaunchBox from a folder you pick.' -Color Cyan -BlankBefore
    Write-TpmText -Text '[I] Add pictures from a folder. You see a preview first.' -Color White
    Write-TpmText -Text '[U] Undo the last picture import.' -Color White
    Write-TpmText -Text '[S] Skip this step.' -Color White
    $choice = Read-TpmChoice -Prompt '  Choice, default S' -Choices @('I', 'U', 'S') -Default 'S'
    if ($choice -eq 'S') { return }
    $root = $lbRoot
    if (-not $root) { $root = Read-HostSafe '  LaunchBox install folder (Enter to go back)' }
    if (-not $root) { return }
    if ($choice -eq 'U') {
        $undoResult = Invoke-TpmLaunchBoxMediaUndo -lbRoot $root
        Write-TpmLbMediaOutcome -Result $undoResult -Title $undoResult.Summary
        return
    }
    Write-TpmText -Text 'Nothing is downloaded. Pictures are only copied from the folder you pick.' -Color DarkCyan
    $folder = Read-HostSafe '  Folder with your pictures (Enter to go back)'
    if (-not $folder) { return }
    $kindChoice = Read-TpmChoice -Prompt '  Picture type: 1 Clear logos, 2 Box front, B back' -Choices @('1', '2', 'B') -Default '1'
    if ($kindChoice -eq 'B') { return }
    $kind = if ($kindChoice -eq '2') { 'BoxFront' } else { 'ClearLogo' }
    $platChoice = Read-TpmChoice -Prompt '  Platform: 1 TeknoParrot, 2 Arcade, 3 Both, B back' -Choices @('1', '2', '3', 'B') -Default '1'
    if ($platChoice -eq 'B') { return }
    $platforms = switch ($platChoice) { '1' { @('TeknoParrot') } '2' { @('Arcade') } '3' { @('Arcade', 'TeknoParrot') } }
    try {
        # The game list (when LaunchBox has it) lets the shared matching engine tell games apart by ID; without it, names alone are used.
        $gamesDb = Get-TpmGamesDbForLaunchBox -LaunchBoxRoot $root
        $engine = @{ TpRoot = $TpRoot; DatIndex = $DatIndex; GameList = $gamesDb.Index }
        $plan = Get-TpmLaunchBoxMediaPlan -lbRoot $root -userProfilesDir $userProfilesDir -imageFolder $folder -platformNames $platforms -Kind $kind @engine
        $replace = $false
        if ($plan.Existing.Count -gt 0) {
            Write-TpmText -Text ('{0} already have a picture.' -f (Format-TpmGameCount -Count $plan.Existing.Count)) -Color Yellow -BlankBefore
            if ((Read-TpmYesNo -Prompt 'Keep the pictures you already have? (Y = keep, N = replace them; old ones are saved so Undo can bring them back)' -Default 'Y') -eq 'N') {
                $replace = $true
                $plan = Get-TpmLaunchBoxMediaPlan -lbRoot $root -userProfilesDir $userProfilesDir -imageFolder $folder -platformNames $platforms -Kind $kind -ReplaceExisting @engine
            }
        }
        $detailLines = New-Object System.Collections.Generic.List[string]
        foreach ($m in $plan.Exact) { [void]$detailLines.Add(('Match: {0} [{1}] <- {2}' -f $m.Game.Title, $m.Game.Platform, $m.Image)) }
        foreach ($m in $plan.Near) { [void]$detailLines.Add(('Close match to check: {0} [{1}] ({2})' -f $m.Game.Title, $m.Game.Platform, $m.Reason)) }
        foreach ($m in $plan.NoImage) { [void]$detailLines.Add(('No picture: {0} [{1}]' -f $m.Game.Title, $m.Game.Platform)) }
        foreach ($m in $plan.Existing) { [void]$detailLines.Add(('Kept, already has one: {0} [{1}]' -f $m.Game.Title, $m.Game.Platform)) }
        $detailBlocks = @(@{ Heading = 'Picture preview details'; Lines = @($detailLines.ToArray()) })
        Write-Log ('LaunchBox pictures plan: images={0}; games={1}; exact={2}; near={3}; none={4}; existing={5}' -f $plan.ImageCount, $plan.GameCount, $plan.Exact.Count, $plan.Near.Count, $plan.NoImage.Count, $plan.Existing.Count)
        foreach ($l in $detailLines) { Write-Log ('LaunchBox pictures plan: ' + $l) }
        Write-TpmText -Text 'Preview. Nothing has been changed yet.' -Color Cyan -BlankBefore
        Write-TpmText -Text ('Sure matches: {0}' -f $plan.Exact.Count) -Color White
        Write-TpmText -Text ('Close matches to check: {0}' -f $plan.Near.Count) -Color White
        Write-TpmText -Text ('Games with no picture: {0}' -f $plan.NoImage.Count) -Color White
        if ($plan.Existing.Count -gt 0) { Write-TpmText -Text ('Games kept as they are: {0}' -f $plan.Existing.Count) -Color White }
        $selected = New-Object System.Collections.Generic.List[object]
        foreach ($m in $plan.Exact) { [void]$selected.Add($m) }
        foreach ($m in $plan.Near) {
            foreach ($cand in $m.Candidates) {
                Write-TpmText -Text ('Game: {0}' -f $m.Game.Title) -Color White -BlankBefore
                Write-TpmText -Text ('Picture: {0}' -f [System.IO.Path]::GetFileName($cand.Image)) -Color White
                Write-TpmText -Text $m.Reason -Color DarkGray
                if ((Read-TpmYesNo -Prompt 'Is this the right picture for this game? (Y/N, D = details)' -Default 'N' -DetailsAction { Show-TpmDetailBlocks -Blocks $detailBlocks }) -eq 'Y') {
                    [void]$selected.Add([pscustomobject]@{ Game = $m.Game; Image = $cand.Image; Dest = $cand.Dest; Replaces = $m.Replaces })
                    break
                }
            }
        }
        if ($selected.Count -eq 0) { Write-TpmText -Text 'No pictures to copy. Nothing was changed.' -Color DarkGray -BlankBefore; return }
        Write-TpmText -Text ('Ready to copy {0} picture(s) into LaunchBox.' -f $selected.Count) -Color Cyan -BlankBefore
        if ((Read-TpmYesNo -Prompt 'Copy exactly these pictures now? (Y/N, D = details)' -Default 'N' -DetailsAction { Show-TpmDetailBlocks -Blocks $detailBlocks }) -ne 'Y') {
            Write-TpmText -Text 'Canceled. Nothing was changed.' -Color DarkGray; return
        }
        $importResult = Invoke-TpmLaunchBoxMediaImport -lbRoot $root -Selected @($selected.ToArray()) -ReplaceExisting:$replace
        $title = if ($importResult.Outcome -eq 'SAVED') { 'Copied {0} picture(s) into LaunchBox. Use the Undo choice here to remove them.' -f $importResult.AddedCount } else { $importResult.Summary }
        Write-TpmLbMediaOutcome -Result $importResult -Title $title
    } catch {
        Write-Log ('LaunchBox pictures: stopped before any change -- {0}' -f $_.Exception.Message)
        Write-TpmText -Text 'The picture import was stopped. Nothing was changed.' -Color Yellow -BlankBefore
        Write-TpmText -Text ('Reason: ' + $_.Exception.Message) -Color DarkGray
    }
}

# =============================================================================
# OPTIONAL LAUNCHBOX INTEGRATION OR SEPARATE REFERENCE EXPORT
# =============================================================================

Invoke-TpmLaunchBoxStep

# =============================================================================
# OPTIONAL LEDBLINKY LIGHTING  (only when LEDBlinky is found; read-only until the user agrees)
# =============================================================================
if ($dryRunActive) {
    Write-Log "PreviewMode: LEDBlinky step skipped."
} elseif ($Unattended) {
    Write-Log "Unattended: LEDBlinky step skipped."
} else {
    $ledState = [pscustomobject]@{ Folder = [string]$ledBlinkyRoot }
    $ledInstall = Invoke-TpmLedBlinkyLocate -SavedFolder $ledState.Folder -LaunchBoxRoot $lbRoot
    if ($ledInstall) {
        $ledState.Folder = $ledInstall.Root
        $ledImageFolders = @()
        if ($lbRoot) { $ledImageFolders = @('TeknoParrot', 'Arcade') | ForEach-Object { Join-Path (Join-Path $lbRoot 'Images') $_ } }
        Invoke-TpmLedBlinkyStep -Install $ledInstall -UserProfilesDir $userProfilesDir -Layout $script:TpmOwnedLayout -State $ledState -ImageFolders $ledImageFolders
    } else { Write-Log "LEDBlinky not found or skipped; the lighting step was not run." }
    if ([string]$ledState.Folder -cne [string]$ledBlinkyRoot) {
        $ledBlinkyRoot = [string]$ledState.Folder
        if (-not (Save-Config)) { Write-Log "LEDBlinky folder choice could not be saved to the settings file." }
    }
}
# =============================================================================
# CROSSHAIR SETUP  (optional)
# =============================================================================
$onboardingSummaries = New-Object System.Collections.Generic.List[string]
$onboardingFollowUp = New-Object System.Collections.Generic.List[string]
foreach ($registrationMessage in $registrationFollowUp) { [void]$onboardingFollowUp.Add($registrationMessage) }
$normalCrosshairResult = $null
$crosshairBlocksLaterSetup = $false
Write-Host ""
if ($dryRunActive) {
    $doCrosshairs = "N"
    Write-Log "PreviewMode: crosshair setup offer skipped."
} elseif ($Unattended) {
    $doCrosshairs = "N"
    Write-Log "Unattended: crosshair setup skipped."
} else {
    $doCrosshairs = Read-TpmYesNo -Prompt "Configure custom crosshairs for lightgun games? (Y/N)"
}
if ($doCrosshairs -eq "Y") {
    Write-Host ""
    Write-Host "Crosshair Setup" -ForegroundColor Cyan
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    $normalCrosshairResult = Invoke-TpmProgressGroup -Title 'Crosshair setup' -Action { Invoke-CrosshairSetup -UserProfilesDir $userProfilesDir `
                          -TpRoot $tpRoot `
                          -WorkflowContext $null -ProtectedRoots @($zipSource, $zipSourceSupplementary) }
}
if ($doCrosshairs -ne 'Y') {
    $onboardingCrosshairSummary = 'Crosshairs: skipped by choice, preview, or unattended mode; no deployment was verified by this step.'
} elseif ($normalCrosshairResult -and $normalCrosshairResult.Cancelled) {
    $onboardingCrosshairSummary = 'Crosshairs: canceled before deployment; no success was claimed. Run Crosshair setup from the menu if still wanted.'
    [void]$onboardingFollowUp.Add($onboardingCrosshairSummary)
} elseif (-not $normalCrosshairResult -or -not $normalCrosshairResult.Succeeded) {
    $crosshairBlocksLaterSetup = $true
    $crosshairTx = if ($normalCrosshairResult -and $normalCrosshairResult.PSObject.Properties['TransactionResult']) { $normalCrosshairResult.TransactionResult } else { $null }
    $onboardingCrosshairSummary = if ($null -eq $crosshairTx -or [string]$crosshairTx.Outcome -eq 'FAILED_BEFORE_MUTATION') { 'Crosshairs: nothing was changed and no success was claimed. Fix the reported issue, then run Crosshair setup from the menu.' } else { 'Crosshairs: did not finish as a verified success. Some files may already have changed; review the crosshair result and preserved evidence before retrying.' }
    [void]$onboardingFollowUp.Add($onboardingCrosshairSummary)
} elseif ($normalCrosshairResult.NoTargets) {
    $onboardingCrosshairSummary = 'Crosshairs: selection checked or saved; no eligible game folders were available for deployment.'
} elseif ($normalCrosshairResult.NoOp) {
    $onboardingCrosshairSummary = 'Crosshairs: selected files already match; no deployment changes were needed.'
} else {
    $onboardingCrosshairSummary = 'Crosshairs: selected assets were deployed and checked. Game launch and controls were not verified.'
}
[void]$onboardingSummaries.Add($onboardingCrosshairSummary)

# =============================================================================
# RESHADE SETUP  (optional, runs after crosshair setup)
# =============================================================================

# The three optional questions (ReShade, dgVoodoo2, graphics card fixes) can be walked back with B, so a step skipped by accident can still be done.
# $optionalStepFrom is the first step to ask on this pass: 1 = ReShade, 2 = dgVoodoo2.
$optionalStepFrom = 1
$optionalMarkReShade = @($onboardingSummaries.Count, $onboardingFollowUp.Count)
$optionalMarkDgVoodoo = $optionalMarkReShade
$rsSetupDone = $false
$dgSetupDone = $false
do {
$optionalGoBack = $false
if ($optionalStepFrom -gt 1) {
    $doReShade = "N"
} elseif ($dryRunActive) {
    $doReShade = "N"
    Write-Log "PreviewMode: ReShade setup offer skipped."
} elseif ($Unattended) {
    $doReShade = "N"
    Write-Log "Unattended: ReShade setup skipped."
} elseif ($crosshairBlocksLaterSetup) {
    $doReShade = "N"
    Write-TpmOptionalStepBlocked -Step ReShade
    Write-Log 'ReShade offer suppressed: crosshair setup did not finish.'
} else {
    $doReShade = Read-TpmOptionalStepChoice -Step ReShade -Default 'N'
}
if ($optionalStepFrom -le 1) { $rsSetupDone = $false }
if ($doReShade -eq "Y") {
    # Locate the 64-bit DLL: bundled copy first, then config. If this PC has none yet, run the same
    # download-or-use-my-copy step as the main-menu "ReShade setup" right here (Request-TpmReShadeSourceDll),
    # so answering Yes never ends in "go to the menu".
    $bundledDll2   = Get-TpmUserReShadeDll -FileName 'ReShade64.dll'
    if (-not $rsSourceDll -or -not (Test-Path -LiteralPath $rsSourceDll)) {
        if ($bundledDll2) {
            $rsSourceDll = $bundledDll2
        } else {
            Write-Host ""
            $rsFirstRunAcq = Request-TpmReShadeSourceDll
            if ($rsFirstRunAcq.State -eq 'Acquired') {
                $rsSourceDll = $rsFirstRunAcq.Path
            } else {
                Write-Host "  ReShade was not set up. Nothing was changed." -ForegroundColor Yellow
                Write-Host "  To try again, choose 'ReShade setup' from the main menu." -ForegroundColor Cyan
                Write-Log ("ReShade post-run: skipped -- no DLL acquired ({0})." -f $rsFirstRunAcq.State)
                $doReShade = "N"
            }
        }
    }
    if ($doReShade -eq "Y") {
        Add-TpmMissingReShade32FromSavedSetup -SourceDll $rsSourceDll
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " ReShade Visual Enhancements Setup" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        $normalReShadeResult = Invoke-TpmProgressGroup -Title 'ReShade setup' -Action { Invoke-ReShadeSetup -UserProfilesDir $userProfilesDir `
                            -SourceDll $rsSourceDll `
                            -ConfigPath $configPath `
                            -TpRoot $tpRoot `
                            -Mode $mode `
                            -ZipSource $zipSource `
                            -GamesInstallFolder $gamesInstallFolder `
                            -RetroBat $retroBat -ZipSourceSupplementary $zipSourceSupplementary }
        Write-Host ""
        Write-Host "  ReShade result -- review before continuing to dgVoodoo2:" -ForegroundColor Cyan
        if ($normalReShadeResult -and @($normalReShadeResult.PSTypeNames) -contains 'TPM.TransactionResult.v1') {
            $normalReShadePresentation = ConvertTo-TpmTransactionPresentation -TransactionResult $normalReShadeResult
            # FIX52 (#384): composed for the window as it is now (minus the 4-space indent), not a fixed 80 columns.
            foreach ($row in @(Format-TpmTransactionPresentationRows -Presentation $normalReShadePresentation -Width ((Get-ConsoleContentWidth) - 4))) {
                Write-Host ("    {0}" -f $row) -ForegroundColor $(if ($normalReShadePresentation.RequiresAttention) { 'Yellow' } else { 'DarkGray' })
            }
            foreach ($detailRow in @(Format-TpmReShadeSummaryDetailRows -Result $normalReShadeResult)) {
                Write-Host ("    {0}" -f $detailRow) -ForegroundColor Yellow
            }
        } else {
            Write-Host '    ReShade setup did not return an authoritative transaction result; no verified deployment was claimed.' -ForegroundColor Yellow
        }
        [void](Read-HostSafe '  Press Enter to review the ReShade result before dgVoodoo2')
        $rsOutcome = Get-TpmOptionalStepOutcome -Step ReShade -Result $normalReShadeResult
        $rsSetupDone = $rsOutcome.Done
        if ($rsOutcome.FollowUp) {
            [void]$onboardingSummaries.Add($rsOutcome.FollowUp)
            [void]$onboardingFollowUp.Add($rsOutcome.FollowUp)
        }
    }
}
# =============================================================================
# DGVOODOO2 SETUP  (optional, runs after ReShade setup)
# =============================================================================
$optionalMarkDgVoodoo = @($onboardingSummaries.Count, $onboardingFollowUp.Count)
if ($dryRunActive) {
    $doDgVoodoo = "N"
    Write-Log "PreviewMode: dgVoodoo2 setup offer skipped."
} elseif ($Unattended) {
    $doDgVoodoo = "N"
    Write-Log "Unattended: dgVoodoo2 setup skipped."
} elseif ($crosshairBlocksLaterSetup) {
    $doDgVoodoo = "N"
    Write-TpmOptionalStepBlocked -Step DgVoodoo2
    Write-Log 'dgVoodoo2 offer suppressed: crosshair setup did not finish.'
} else {
    $doDgVoodoo = Read-TpmOptionalStepChoice -Step DgVoodoo2 -Default 'N' -AllowBack
    if ($doDgVoodoo -eq 'B') {
        # Back to the ReShade question: drop what this pass added to the summaries, then ask again from ReShade.
        Write-Log 'Optional setup: the user went back from the dgVoodoo2 question to the ReShade question.'
        if ($onboardingSummaries.Count -gt $optionalMarkReShade[0]) { $onboardingSummaries.RemoveRange($optionalMarkReShade[0], $onboardingSummaries.Count - $optionalMarkReShade[0]) }
        if ($onboardingFollowUp.Count -gt $optionalMarkReShade[1]) { $onboardingFollowUp.RemoveRange($optionalMarkReShade[1], $onboardingFollowUp.Count - $optionalMarkReShade[1]) }
        $rsSetupDone = $false
        $optionalStepFrom = 1
        $optionalGoBack = $true
        continue
    }
}
if ($doDgVoodoo -eq "Y") {
    # Nothing on this PC yet: the same download-or-use-my-folder step as the main-menu "dgVoodoo2 setup" runs right here,
    # so answering Yes never ends in "go to the menu".
    $bundledDg2 = Get-TpmBundledDgVoodoo2Folder
    if (-not (Test-TpmDgVoodoo2SourceFolder -Path $dgSourceDir)) {
        if (Test-TpmDgVoodoo2SourceFolder -Path $bundledDg2) {
            $dgSourceDir = $bundledDg2
        } else {
            Write-Host ""
            $dgFirstRunAcq = Request-TpmDgVoodoo2SourceDir
            if ($dgFirstRunAcq.State -eq 'Acquired') {
                $dgSourceDir = $dgFirstRunAcq.Path
            } else {
                Write-Host "  dgVoodoo2 was not set up. Nothing was changed." -ForegroundColor Yellow
                Write-Host "  To try again, choose 'dgVoodoo2 setup' from the main menu." -ForegroundColor Cyan
                Write-Log ("dgVoodoo2 post-run: skipped -- no DLL folder acquired ({0})." -f $dgFirstRunAcq.State)
                $doDgVoodoo = "N"
            }
        }
    }
}
$dgSetupDone = $false
if ($doDgVoodoo -eq "Y") {
    Write-Host ""
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Write-Host " dgVoodoo2 Legacy Compatibility Setup" -ForegroundColor Cyan
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    $postDgResult = Invoke-TpmProgressGroup -Title 'dgVoodoo2 setup' -Action { Invoke-DgVoodoo2Setup -UserProfilesDir $userProfilesDir `
                          -SourceDir $dgSourceDir `
                          -ProtectedRoots @($zipSource, $zipSourceSupplementary) }
    $dgOutcome = Get-TpmOptionalStepOutcome -Step DgVoodoo2 -Result $postDgResult
    $dgSetupDone = $dgOutcome.Done
    Write-Host ""
    if ($postDgResult -and [bool]$postDgResult.Cancelled) { Write-Host '  dgVoodoo2 setup was canceled. No files were changed.' -ForegroundColor Yellow }
    elseif ($postDgResult -and [bool]$postDgResult.Succeeded) { Write-Host $(if ([bool]$postDgResult.NoOp) { '  No dgVoodoo2 changes were needed.' } else { '  dgVoodoo2 setup finished.' }) -ForegroundColor Green }
    else {
        Write-Host "  dgVoodoo2 setup did not finish cleanly. Run 'dgVoodoo2 setup' from the main menu for details and a guided retry." -ForegroundColor Yellow
    }
    if ($dgOutcome.FollowUp) {
        [void]$onboardingSummaries.Add($dgOutcome.FollowUp)
        [void]$onboardingFollowUp.Add($dgOutcome.FollowUp)
    }
    if ($postDgResult -and [int](Get-TpmTransactionField -Object $postDgResult -Name 'MissingDevice' -Default 0) -gt 0) {
        [void]$onboardingFollowUp.Add('Drive not connected: dgVoodoo2 skipped games on a drive that is not connected. ' + (Get-TpmDriveSkipNext))
    }
}
# =============================================================================
# CPS3 SUPPLEMENTARY FILES  (optional, only when CPS3 games are registered)
# =============================================================================
if ($dryRunActive) {
    Write-Log "PreviewMode: CPS3 supplementary file offer skipped."
} elseif ($Unattended) {
    Write-Log "Unattended: CPS3 supplementary file offer skipped."
} else {
    [void](Invoke-TpmCps3SupplementaryOffer -TpRoot $tpRoot -UserProfilesDir $userProfilesDir)
}
# =============================================================================
# SYSTEM 11 SAVED FILES  (optional, only when System 11 games are registered and some have no saved files)
# =============================================================================
if ($dryRunActive) {
    Write-Log "PreviewMode: System 11 saved files offer skipped."
} elseif ($Unattended) {
    Write-Log "Unattended: System 11 saved files offer skipped."
} else {
    [void](Invoke-TpmS11PreinstallOffer -TpRoot $tpRoot -UserProfilesDir $userProfilesDir -SearchFolders @($zipSourceSupplementary, $zipSource))
}
# =============================================================================
# GPU FIX SETUP  (optional, runs after dgVoodoo2 setup)
# =============================================================================

if ($dryRunActive) {
    $doGpuFix = "N"
    Write-Log "PreviewMode: GPU fix setup offer skipped."
} elseif ($Unattended) {
    $doGpuFix = "N"
    Write-Log "Unattended: GPU fix setup skipped."
} elseif ($crosshairBlocksLaterSetup) {
    $doGpuFix = "N"
    Write-TpmOptionalStepBlocked -Step GpuFix
    Write-Log 'GPU fix offer suppressed: crosshair setup did not finish.'
} else {
    $doGpuFix = Read-TpmOptionalStepChoice -Step GpuFix -Default '' -AllowBack
    if ($doGpuFix -eq 'B') {
        # Back to the dgVoodoo2 question (the crosshair-or-CPS3 offer in between is asked again too).
        Write-Log 'Optional setup: the user went back from the graphics card fixes question to the dgVoodoo2 question.'
        if ($onboardingSummaries.Count -gt $optionalMarkDgVoodoo[0]) { $onboardingSummaries.RemoveRange($optionalMarkDgVoodoo[0], $onboardingSummaries.Count - $optionalMarkDgVoodoo[0]) }
        if ($onboardingFollowUp.Count -gt $optionalMarkDgVoodoo[1]) { $onboardingFollowUp.RemoveRange($optionalMarkDgVoodoo[1], $onboardingFollowUp.Count - $optionalMarkDgVoodoo[1]) }
        $dgSetupDone = $false
        $optionalStepFrom = 2
        $optionalGoBack = $true
        continue
    }
}
$autoGpuResult = $null
if ($doGpuFix -eq "Y") {
    Write-Host ""
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Write-Host " GPU Compatibility Fix Setup" -ForegroundColor Cyan
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    $autoGpuResult = Invoke-TpmProgressGroup -Title 'GPU compatibility fix' -Action { Invoke-GpuFixSetup -UserProfilesDir $userProfilesDir `
                       -TpRoot $tpRoot }
    if ($null -eq $autoGpuResult -or @($autoGpuResult.PSTypeNames) -notcontains 'TPM.TransactionResult.v1') {
        Write-Host "GPU Compatibility Fix did not return a result. No success was claimed." -ForegroundColor Yellow
    } elseif ([bool]$autoGpuResult.Cancelled) {
        Write-Host "GPU Compatibility Fix canceled before profile changes; no success was claimed." -ForegroundColor DarkGray
    } elseif ($autoGpuResult.Outcome -notin @('SUCCEEDED', 'NO_OP')) {
        # The same result screen the menu uses: the counts (selected, changed, skipped, failed), the drive letter, and D for details.
        $autoGpuView = Get-TpmGpuFixResultView -Result $autoGpuResult
        $autoGpuView.Next = if ([int](Get-TpmTransactionField -Object $autoGpuResult -Name 'MissingDevice' -Default 0) -gt 0 -or [int](Get-TpmTransactionField -Object $autoGpuResult -Name 'MissingPath' -Default 0) -gt 0) {
            (Get-TpmDriveSkipNext) + ' Then run GPU Compatibility Fix again from the main menu.'
        } else { 'Run GPU Compatibility Fix again from the main menu if you want to retry.' }
        Write-TpmOutcome @autoGpuView
        if ([int](Get-TpmTransactionField -Object $autoGpuResult -Name 'MissingDevice' -Default 0) -gt 0) {
            [void]$onboardingFollowUp.Add('Drive not connected: the GPU fix skipped games on a drive that is not connected. ' + (Get-TpmDriveSkipNext))
        }
    }
}
if ($doGpuFix -ne 'Y') {
    $onboardingGpuSummary = if ($crosshairBlocksLaterSetup) { 'GPU compatibility: not offered because Crosshair setup did not finish; no profile fields were changed by this step.' } else { 'GPU compatibility: skipped by choice, preview or unattended mode; no profile fields were changed by this step.' }
} elseif ($autoGpuResult -and $autoGpuResult.Cancelled) {
    $onboardingGpuSummary = 'GPU compatibility: canceled before profile changes; no success was claimed. Run GPU Compatibility Fix from the menu if still wanted.'
    [void]$onboardingFollowUp.Add($onboardingGpuSummary)
} elseif (-not $autoGpuResult -or @($autoGpuResult.PSTypeNames) -notcontains 'TPM.TransactionResult.v1' -or $autoGpuResult.Outcome -notin @('SUCCEEDED','NO_OP')) {
    $gpuCountsLine = if ($autoGpuResult) { Get-TpmResultCountsLine -Result $autoGpuResult -Picked @(Get-TpmTransactionField -Object $autoGpuResult -Name 'SelectedItems' -Default @()) -AlreadyWord 'already set up or needed no fix' } else { '' }
    $onboardingGpuSummary = if ($gpuCountsLine) { 'GPU compatibility: ' + $gpuCountsLine + ' Game launch and display result were not verified.' } else { 'GPU compatibility: did not finish as a verified success. Review the per-profile result and preserved backup before retrying; no game launch or display result was verified.' }
    [void]$onboardingFollowUp.Add($onboardingGpuSummary)
} elseif ($autoGpuResult.Outcome -eq 'NO_OP') {
    $onboardingGpuSummary = 'GPU compatibility: scanned profile fields needed no changes. Game launch and display output were not verified.'
} else {
    $onboardingGpuSummary = 'GPU compatibility: profile writes were reported complete. Saved fields were not independently read back by this step; game launch and display output were not verified.'
}
[void]$onboardingSummaries.Add($onboardingGpuSummary)
} while ($optionalGoBack)
Write-Host ''
Write-Host '  Optional setup results:' -ForegroundColor Cyan
foreach ($onboardingSummary in $onboardingSummaries) {
    Write-Host ('    ' + $onboardingSummary) -ForegroundColor $(if ($onboardingFollowUp.Contains($onboardingSummary)) { 'Yellow' } else { 'DarkGray' })
    Write-Log $onboardingSummary
}

# TeknoParrot's own first-time setup is separate from TPM's work. Say once what is left to do (issue #260).
foreach ($wizardAdviceLine in @(Get-TeknoParrotWizardAdviceLines -WizardState (Get-TeknoParrotWizardState -TeknoParrotRoot $tpRoot) -TeknoParrotRoot $tpRoot)) { [void]$onboardingFollowUp.Add($wizardAdviceLine) }

# =============================================================================
# ACTION REQUIRED -- collects everything the user must do manually
# =============================================================================

# The file name to show for an executable name saved in a profile. Profile text can hold characters Windows file names do not allow
# (quotes, pipes, angle brackets, several names in one field); [System.IO.Path]::GetFileName throws on those in Windows PowerShell 5.1
# and used to stop the whole run at the Action Required screen. Plain text work never throws: the last name is cut off by hand,
# odd text is shown as written, and one short log line names the game(s).
function Get-TpmExecutableDisplayName {
    param([AllowNull()][string]$Name, [string]$Codes = '')
    if ([string]::IsNullOrEmpty($Name)) { return '' }
    # A fixed list (the characters Windows 5.1 refuses), because GetInvalidPathChars() lists fewer on PowerShell 7 and the log line must not depend on the runtime.
    if ([regex]::IsMatch($Name, '["<>|\x00-\x1F]')) {
        Write-Log ("Action required: the executable name saved for {0} has characters Windows file names do not allow; it is shown as written." -f $Codes)
    }
    return @($Name.TrimEnd('\', '/').Split([char[]]@('\', '/')))[-1]
}

function New-TpmGameNotesReportText {
    param([object[]]$SetupNotes = @())
    $builder = New-Object System.Text.StringBuilder
    [void]$builder.AppendLine("TeknoParrot Manager - Game Notes")
    [void]$builder.AppendLine("These imported notes are informational; complete required actions in the separate Action Required report.")
    $writeSection = {
        param([string]$Heading, [string]$Text)
        if ([string]::IsNullOrWhiteSpace($Text)) { return }
        [void]$builder.AppendLine($Heading)
        foreach ($line in (Format-NoteLines -Text $Text)) {
            $safeLine = $line -replace '(?i)fuck\w*', '[language removed]' -replace '(?i)\bsucks?\b', '[insult removed]' -replace '(?i)\b(useless users|sensitive snowflake)\b', '[insult removed]'
            [void]$builder.AppendLine($safeLine)
        }
    }
    $textOf = { param($Item, [string]$Name) if ($Item.PSObject.Properties[$Name] -and $Item.$Name) { [string]$Item.$Name } else { '' } }
    foreach ($sn in @($SetupNotes | Sort-Object Code)) {
        [void]$builder.AppendLine("")
        [void]$builder.AppendLine(("Game: {0} ({1})" -f $sn.Code, $sn.GameName))
        $baseGame = & $textOf $sn 'BaseGame'
        if ($baseGame) { [void]$builder.AppendLine(("This is a version of: {0}. Notes for the base game are marked." -f $baseGame)) }
        $guideStatus = & $textOf $sn 'GuideStatus'
        if ($guideStatus) { [void]$builder.AppendLine(("Guide status: {0}" -f $guideStatus)) }
        if ($sn.PSObject.Properties['Needs'] -and $sn.Needs) { [void]$builder.AppendLine([string]$sn.Needs) }
        if ($sn.SetupExe) { [void]$builder.AppendLine(("Run: {0}" -f $sn.SetupExe)) }
        $secondFile = & $textOf $sn 'SecondFile'
        if ($secondFile) { [void]$builder.AppendLine(("Second file: {0}" -f $secondFile)) }
        $testProgram = & $textOf $sn 'TestProgram'
        if ($testProgram) { [void]$builder.AppendLine(("Test program: {0}" -f $testProgram)) }
        & $writeSection 'Source notes:' ([string]$sn.Notes)
        & $writeSection $(if ($baseGame) { 'Setup steps and known issues (base game):' } else { 'Setup steps and known issues:' }) (& $textOf $sn 'GeneralIssues')
        $gpuLines = @(); if ($sn.PSObject.Properties['GpuIssues']) { $gpuLines = @($sn.GpuIssues) }
        if ($gpuLines.Count -gt 0) { & $writeSection 'Graphics card notes:' ($gpuLines -join "`n") }
        $linkedProfile = & $textOf $sn 'LinkedProfile'
        if ($linkedProfile) { [void]$builder.AppendLine(("Linked profile (the same game with another setup): {0}." -f $linkedProfile)) }
        $extraArchives = @(); if ($sn.PSObject.Properties['ExtraArchives']) { $extraArchives = @($sn.ExtraArchives) }
        if ($extraArchives.Count -gt 0) { & $writeSection 'Extra archives you need. Use your own copy; none is downloaded for you:' ($extraArchives -join "`n") }
    }
    return $builder.ToString()
}

function Write-TpmGameNotesReport {
    param([object[]]$SetupNotes = @(), [string]$NotesPath, [switch]$Quiet)
    if (@($SetupNotes).Count -eq 0) { return $false }
    try {
        [System.IO.File]::WriteAllText($NotesPath, (New-TpmGameNotesReportText -SetupNotes $SetupNotes), (New-Object System.Text.UTF8Encoding $false))
        if (-not $Quiet) {
            Write-Host ("  Informational game notes saved separately: {0}" -f $NotesPath) -ForegroundColor DarkCyan
            Write-Log "Game notes report written to $NotesPath"
        }
        return $true
    } catch {
        Write-Log "Game notes report could not be written -- $_"
        Write-Host '  The extra game notes could not be saved, so they are not in the report. The program folder may be read-only.' -ForegroundColor Yellow
        return $false
    }
}


function Write-TpmActionRequiredReports {
    param(
        [bool]$HasAnyAction,
        [string]$ActionPath = '',
        [hashtable]$ManualRegData = @{},
        [object[]]$AmbiguousPaths = @(),
        [object[]]$NotFound = @(),
        [object[]]$DesignSkippedItems = @(),
        [object]$Result,
        [object]$CompatibilityWarnings,
        [object[]]$ControlReadinessItems = @(),
        [string]$GameNotesPath = '',
        [string]$RunId = '',
        [string[]]$OnboardingFollowUp = @()
    )
    if (-not $HasAnyAction -and @($DesignSkippedItems).Count -eq 0) { return $false }
    return (Write-TpmActionRequiredReport `
        -ActionPath $ActionPath `
        -ManualRegData $ManualRegData `
        -AmbiguousPaths $AmbiguousPaths `
        -NotFound $NotFound `
        -DesignSkippedItems $DesignSkippedItems `
        -Result $Result `
        -CompatibilityWarnings $CompatibilityWarnings `
        -ControlReadinessItems $ControlReadinessItems `
        -GameNotesPath $GameNotesPath `
        -OnboardingFollowUp $OnboardingFollowUp `
        -DesignOnly:(-not $HasAnyAction) `
        -RunId $RunId)
}

$compatWarnings = Get-CompatibilityWarnings -UserProfilesDir $userProfilesDir -TeknoParrotRoot $tpRoot
$setupNotes     = Get-GameSetupNotes -UserProfilesDir $userProfilesDir

# Re-run after the firmware copy below, which can clear the only item.
$testAnyAction = {
    ($manualRegData.Count -gt 0) -or ($amb2.Count -gt 0) -or
    ($nf.Count -gt 0) -or
    ($result.Unmatched.Count -gt 0) -or
    ($onboardingFollowUp.Count -gt 0) -or
    ($controlReadinessItems.Count -gt 0) -or
    ($compatWarnings.PathTooLong.Count -gt 0) -or
    ($compatWarnings.DllMismatch.Count -gt 0) -or
    ($compatWarnings.GpuIncompatible.Count -gt 0) -or
    ($compatWarnings.BiosMissing.Count -gt 0) -or
    ($compatWarnings.ExeMissing.Count -gt 0)
}
$hasAnyAction = [bool](& $testAnyAction)

$notesPath = Join-Path $script:TpmOwnedLayout.Reports "TeknoParrot-Manager-game-notes.txt"
$gameNotesWritten = $false
if (-not $dryRunActive) { $gameNotesWritten = Write-TpmGameNotesReport -SetupNotes $setupNotes -NotesPath $notesPath -Quiet }
# A control family with no reference game is only informational ("skipped by design"), so it never turns on ACTION REQUIRED. But when it is
# the only open item its hint is still shown and saved, so the next step is not lost.
if ($hasAnyAction -or $designSkippedItems.Count -gt 0) {
    Write-Host ""
    Write-Host "============================================" -ForegroundColor Yellow
    Write-Host $(if ($hasAnyAction) { '   ACTION REQUIRED' } else { '   CONTROLS: ONE MORE STEP' }) -ForegroundColor Yellow
    Write-Host "============================================" -ForegroundColor Yellow
    if ($hasAnyAction) {
        foreach ($plainLine in @(Get-TpmActionRequiredPlainLines -For Screen -SavePath ([string]$script:TpmOwnedLayout.ActionItemsPath) -Preview:$dryRunActive)) { Write-TpmText -Text $plainLine -Color Cyan -BreakLongWords }
    } else {
        Write-TpmText -Text 'Nothing failed. Some games were skipped on purpose, because no game of their control type has controls you set yourself yet. The next step is listed below.' -Color Cyan -BreakLongWords
    }
    Write-Host ""
    foreach ($actionGroup in @(Get-TpmActionRequiredGroups -Lines $onboardingFollowUp.ToArray())) {
        Write-Host ('  ' + $actionGroup.Heading) -ForegroundColor Cyan
        foreach ($followUp in $actionGroup.Lines) { Write-Host ('    ' + $followUp) -ForegroundColor Yellow }
    }

    # -- 1. Games needing manual registration ---------------------------------
    if ($manualRegData.Count -gt 0) {
        Write-Host ""
        Write-Host "  REGISTER THESE GAMES IN TEKNOPARROTUI" -ForegroundColor Yellow
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host "  The script found these games on disk but cannot register them" -ForegroundColor DarkCyan
        Write-Host "  automatically. Either the name of the executable file is shared" -ForegroundColor DarkCyan
        Write-Host "  by multiple TeknoParrot profiles, or the one profile it matches" -ForegroundColor DarkCyan
        Write-Host "  is already pointed at a different copy of this game." -ForegroundColor DarkCyan
        Write-Host "  Add each one yourself in TeknoParrotUI: choose the matching profile" -ForegroundColor DarkCyan
        Write-Host "  and the executable shown below." -ForegroundColor DarkCyan
        Write-Host ""
        foreach ($folderName in ($manualRegData.Keys | Sort-Object)) {
            $info    = $manualRegData[$folderName]
            $count   = $info.ProfileCount
            $exeName = $info.ExeName
            Write-Host "  Game   : $folderName" -ForegroundColor Yellow
            Write-Host "  Run    : $exeName" -ForegroundColor DarkGray
            if ($info.Reason -eq "duplicate") {
                $claimedBy = if ($info.ClaimedBy) { $info.ClaimedBy } else { "another folder" }
                Write-Host ("  Note   : profile '{0}' is already used by: {1}" -f $info.Profiles, $claimedBy) -ForegroundColor Cyan
                Write-Host "           TeknoParrot can only point one profile at one executable -- this" -ForegroundColor DarkCyan
                Write-Host "           copy needs its own profile, or you must choose which copy to use." -ForegroundColor DarkCyan
                Write-Host ""
                continue
            }
            if ($info.BestGuess -and $info.BestScore -ge 0.40) {
                Write-Host ("  Best guess : {0}  (similarity {1} -- below auto-register threshold {2})" -f `
                    $info.BestGuess, $info.BestScore, $FuzzyAutoThreshold) -ForegroundColor Cyan
            }
            if ($count -le 15) {
                Write-Host "  Profiles ($count) : $($info.Profiles)" -ForegroundColor DarkCyan
            } else {
                Write-Host "  Profiles : shared by $count games -- search by game name in TeknoParrotUI" -ForegroundColor DarkCyan
            }
            Write-Host ""
        }
    }

    # -- 2. Repair: broken paths that could not be auto-fixed -----------------
    if ($amb2.Count -gt 0) {
        $byExe = @{}
        foreach ($r in $amb2) {
            $k = $r.Exe
            if (-not $byExe.ContainsKey($k)) { $byExe[$k] = [System.Collections.Generic.List[string]]::new() }
            $byExe[$k].Add($r.Code)
        }
        Write-Host "  FIX THESE GAME PATHS IN TEKNOPARROTUI" -ForegroundColor Yellow
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        foreach ($exePath in ($byExe.Keys | Sort-Object)) {
            $codes = ($byExe[$exePath] | Sort-Object) -join " and "
            $exeName = Get-TpmExecutableDisplayName -Name $exePath -Codes $codes
            Write-Host ("  {0} needs a corrected game folder." -f $codes) -ForegroundColor Yellow
            Write-Host ("  TeknoParrot Manager could not find: {0}" -f $exeName) -ForegroundColor DarkGray
            Write-Host ("  Open TeknoParrotUI and point each game to the folder containing {0}." -f $exeName) -ForegroundColor DarkCyan
            Write-Host ""
        }
    }

    # -- 3. Games not yet extracted (informational) ---------------------------
    if ($nf.Count -gt 0) {
        Write-Host "  EXTRACT THESE GAMES FIRST, THEN RE-RUN REPAIR" -ForegroundColor DarkCyan
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host "  These profiles exist but their game has not been extracted to" -ForegroundColor DarkCyan
        Write-Host "  your staging folder yet. No action needed now -- use AutoSync" -ForegroundColor DarkCyan
        Write-Host "  to extract the game, then run the script again and answer Y to the repair question." -ForegroundColor DarkCyan
        Write-Host ""
        $lineLen = 70; $line = "  "; $first = $true
        foreach ($item in ($nf | Sort-Object Code | ForEach-Object { $_.Code })) {
            $add = if ($first) { $item } else { ", $item" }
            if (($line + $add).Length -gt $lineLen) {
                Write-Host $line -ForegroundColor DarkGray
                $line = "  $item"; $first = $false
            } else { $line += $add; $first = $false }
        }
        if ($line.Trim()) { Write-Host $line -ForegroundColor DarkGray }
        Write-Host ""
    }

    # -- 4. Control design skips are informational, not required repairs ------
    if ($designSkippedItems.Count -gt 0) {
        Write-Host ""
        Write-Host "  CONTROLS SKIPPED BY DESIGN (informational; not a failed save)" -ForegroundColor DarkCyan
        foreach ($r in @($designSkippedItems | Sort-Object Family, Code)) {
            Write-Host ('  {0}: {1}' -f $r.Code, (Get-TpmControlPropagationReportLine -Report $r)) -ForegroundColor DarkGray
        }
    }

    # -- 5. Game folders not recognized by TeknoParrot ------------------------
    if ($result.Unmatched.Count -gt 0) {
        Write-Host ""
        Write-Host "  GAME FOLDERS NOT MATCHED TO A TEKNOPARROT PROFILE" -ForegroundColor Yellow
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host "  These folders contain game files, but none of their executables" -ForegroundColor DarkCyan
        Write-Host "  matched a profile in your TeknoParrot GameProfiles folder, so they" -ForegroundColor DarkCyan
        Write-Host "  were not registered. First make sure TeknoParrot is up to date and" -ForegroundColor DarkCyan
        Write-Host "  TeknoParrotUI has been opened once (this tool does not do that for you)," -ForegroundColor DarkCyan
        Write-Host "  then run Register only again. If they still do not match, they may be" -ForegroundColor DarkCyan
        Write-Host "  games TeknoParrot does not support yet, utilities/launchers, or games whose" -ForegroundColor DarkCyan
        Write-Host "  main file is named differently from what TeknoParrot expects. If you are" -ForegroundColor DarkCyan
        Write-Host "  sure TeknoParrot supports a game, add it in TeknoParrotUI yourself." -ForegroundColor DarkCyan
        Write-Host ""
        $lineLen = 70; $line = "  "; $firstU = $true
        foreach ($folder in $result.Unmatched) {
            $add = if ($firstU) { $folder } else { ", $folder" }
            if (($line + $add).Length -gt $lineLen) {
                Write-Host $line -ForegroundColor DarkGray
                $line = "  $folder"; $firstU = $false
            } else { $line += $add; $firstU = $false }
        }
        if ($line.Trim()) { Write-Host $line -ForegroundColor DarkGray }
        Write-Host ""
    }

    # -- 6. Raw Thrills games whose install path is too long ------------------
    if ($compatWarnings.PathTooLong.Count -gt 0) {
        Write-Host ""
        Write-Host "  PATH TOO LONG -- THESE GAMES MAY FAIL TO LAUNCH" -ForegroundColor Yellow
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host "  This game may fail to launch because its folder path is too long." -ForegroundColor DarkCyan
        Write-Host "  TeknoParrot Manager cannot safely rename folders and update profiles automatically" -ForegroundColor DarkCyan
        Write-Host "  in this report, so use the manual steps below." -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host "  MANUAL SAFE REPAIR:" -ForegroundColor DarkCyan
        Write-Host "    1. Back up the affected UserProfile XML before changing anything." -ForegroundColor DarkCyan
        Write-Host "    2. Close TeknoParrotUI, then rename the game folder to the suggested short name." -ForegroundColor DarkCyan
        Write-Host "    3. Shorten parent folders too if needed, such as D:\TPGames\<name>." -ForegroundColor DarkCyan
        Write-Host "    4. Update the saved GamePath in TeknoParrotUI." -ForegroundColor DarkCyan
        Write-Host "    5. Run the script again, answer Y to the repair question and test the game." -ForegroundColor DarkCyan
        Write-Host ""
        foreach ($w in ($compatWarnings.PathTooLong | Sort-Object Code)) {
            Write-Host ("  Game        : {0}" -f $w.Code) -ForegroundColor Yellow
            Write-Host ("  Current path: {0} characters (limit ~{1})" -f $w.Length, $w.Limit) -ForegroundColor DarkGray
            Write-Host ("  Rename to   : {0}" -f $w.Suggested) -ForegroundColor Cyan
            Write-Host ""
        }
    }

    # -- 7. iDmacDrv32.dll version pins (BlazBlue-series) ----------------------
    if ($compatWarnings.DllMismatch.Count -gt 0) {
        Write-Host ""
        Write-Host "  FILE VERSION MISMATCH -- THESE GAMES NEED A SPECIFIC OLDER FILE" -ForegroundColor Yellow
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host "  These games require a SPECIFIC OLDER version of a particular file." -ForegroundColor DarkCyan
        Write-Host "  A newer version causes errors (e.g. a coin error) and the game will" -ForegroundColor DarkCyan
        Write-Host "  not start correctly. This is the opposite of the usual fix -- do NOT" -ForegroundColor DarkCyan
        Write-Host "  let TeknoParrot redeploy its current copy here, that makes it worse." -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host "  HOW TO FIX:" -ForegroundColor DarkCyan
        Write-Host "    1. Join the TeknoParrot Discord (linked from teknoparrot.com)." -ForegroundColor DarkCyan
        Write-Host "    2. In the #fixes channel, ask for or search for the file named" -ForegroundColor DarkCyan
        Write-Host "       below, matching the required CRC32 shown for your game." -ForegroundColor DarkCyan
        Write-Host "    3. Replace that file in the game's own folder with the one you got." -ForegroundColor DarkCyan
        Write-Host ""
        foreach ($w in ($compatWarnings.DllMismatch | Sort-Object Code)) {
            Write-Host ("  Game           : {0}" -f $w.Code) -ForegroundColor Yellow
            Write-Host ("  File           : {0}" -f $w.FileName) -ForegroundColor DarkGray
            Write-Host ("  Current CRC32  : {0}" -f $w.Found) -ForegroundColor DarkGray
            Write-Host ("  Required CRC32 : {0}" -f $w.Required) -ForegroundColor Cyan
            Write-Host ""
        }
    }

    # -- 8. Games known not to work on the detected GPU vendor (informational) -
    if ($compatWarnings.GpuIncompatible.Count -gt 0) {
        $gpuVendorSeen = $compatWarnings.GpuIncompatible[0].Vendor
        Write-Host ""
        Write-Host ("  KNOWN {0} GPU INCOMPATIBILITY -- NO FIX AVAILABLE" -f $gpuVendorSeen.ToUpperInvariant()) -ForegroundColor Yellow
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host ("  These registered games are confirmed NOT to work on {0} GPUs." -f $gpuVendorSeen) -ForegroundColor DarkCyan
        Write-Host "  This is a known limitation of the game/emulation layer, not a setup" -ForegroundColor DarkCyan
        Write-Host "  mistake on your end -- there is no fix to apply. Informational only." -ForegroundColor DarkCyan
        Write-Host ""
        $lineLen = 70; $line = "  "; $firstG = $true
        foreach ($w in ($compatWarnings.GpuIncompatible | Sort-Object Code | ForEach-Object { $_.Code })) {
            $add = if ($firstG) { $w } else { ", $w" }
            if (($line + $add).Length -gt $lineLen) {
                Write-Host $line -ForegroundColor DarkGray
                $line = "  $w"; $firstG = $false
            } else { $line += $add; $firstG = $false }
        }
        if ($line.Trim()) { Write-Host $line -ForegroundColor DarkGray }
        Write-Host ""
    }

    # -- 8b. Missing emulator firmware/BIOS prerequisites (issue #85, FIX132) --
    # Plain screen with one next step per finding. Only an interactive, non-preview run may offer the
    # copy; an unattended or preview run only reports. The files and paths are in Details and the log.
    if ($compatWarnings.BiosMissing.Count -gt 0) {
        $prerequisiteReview = Invoke-TpmPrerequisiteReview -Warnings @($compatWarnings.BiosMissing) -TpRoot $tpRoot `
            -SearchFolders @($zipSourceSupplementary, $zipSource) -EggmanDatZip ([string]$eggmanDatZip) -DatFilePath ([string]$datFilePath) -SupplementaryDatPath ([string]$supplementaryDatPath) `
            -Interactive:(-not $Unattended -and -not $dryRunActive) -OtherRootsProvider { @(Get-TpmDetectedRootList) }
        if ($prerequisiteReview.FixedAny) {
            # The saved action report must not list files that were just put in place.
            $compatWarnings = Get-CompatibilityWarnings -UserProfilesDir $userProfilesDir -TeknoParrotRoot $tpRoot
            $hasAnyAction = [bool](& $testAnyAction)
            if (-not $hasAnyAction -and $designSkippedItems.Count -eq 0) { Write-TpmText -Text 'Nothing is left on this list now, so no list was saved.' -Color Green -BlankBefore }
        }
        Write-Host ""
    }

    # -- 8a. Missing emulator component (issue #254) --------------------------
    if ($compatWarnings.ExeMissing.Count -gt 0) {
        foreach ($e in $compatWarnings.ExeMissing) {
            Write-Host ""
            Write-Host ("  {0} EMULATOR COMPONENT NOT FOUND" -f $e.EmulatorType.ToUpperInvariant()) -ForegroundColor Yellow
            Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
            Write-Host "  A registered game uses this emulator, but the component declared" -ForegroundColor DarkCyan
            Write-Host "  by its ECVF contract was not found at the expected path below." -ForegroundColor DarkCyan
            Write-Host "  TeknoParrot Manager only checked the contract-declared path; it did not determine why" -ForegroundColor DarkCyan
            Write-Host "  the file is missing." -ForegroundColor DarkCyan
            Write-Host ""
            Write-Host ("  Contract : {0} ({1})" -f $e.ContractId, $e.ContractStatus) -ForegroundColor DarkGray
            Write-Host ("  Detector : {0} / {1}" -f $e.DetectorMethod, $e.DetectorSource) -ForegroundColor DarkGray
            Write-Host ("  Evidence : contract-backed; confidence {0}" -f $e.Confidence) -ForegroundColor DarkGray
            Write-Host ("  Expected : {0}" -f $e.ExpectedPath) -ForegroundColor Cyan
            Write-Host ("  Affected : {0}" -f ($e.AffectedGames -join ', ')) -ForegroundColor DarkGray
            Write-Host "  TeknoParrot is missing a component. Use TeknoParrotUI's own update/repair screen." -ForegroundColor DarkCyan
            Write-Host "  Verify or restore this component through your normal TeknoParrot installation/update process using TeknoParrotUI." -ForegroundColor DarkGray
            Write-Host "  TeknoParrot Manager will not invent or replace emulator files; this health result remains visible for review." -ForegroundColor DarkCyan
            Write-Host ""
        }
    }

    # -- 8b. Controls readiness (issues #255/#253) ----------------------------
    if ($controlReadinessItems.Count -gt 0) {
        foreach ($item in $controlReadinessItems) {
            Write-Host ""
            Write-Host ("  CONTROLS NOT READY : {0}" -f $item.Code) -ForegroundColor Yellow
            Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
            Write-Host "  Registration, launch success, and TeknoParrot wizard completion" -ForegroundColor DarkCyan
            Write-Host "  are reported separately and do not prove that controls work." -ForegroundColor DarkCyan
            foreach ($line in $item.SummaryLines) {
                if ([string]::IsNullOrEmpty([string]$line)) {
                    Write-Host ""
                } else {
                    Write-Host ("  {0}" -f $line) -ForegroundColor DarkCyan
                }
            }
        }
    }



    Write-Host "============================================" -ForegroundColor Yellow

    $defaultActionPath = [string]$script:TpmOwnedLayout.ActionItemsPath
    $actionPath = $defaultActionPath
    if (-not $Unattended -and -not $dryRunActive -and $hasAnyAction) {
        foreach ($plainLine in @(Get-TpmActionRequiredPlainLines -For SaveWindow)) { Write-TpmText -Text $plainLine -Color Cyan -BlankBefore }
        try {
            Add-Type -AssemblyName System.Windows.Forms
            $saveDialog = New-Object System.Windows.Forms.SaveFileDialog
            $saveDialog.Title            = "Save Action Required summary"
            $saveDialog.InitialDirectory = [string]$script:TpmOwnedLayout.Reports
            $saveDialog.FileName         = "TeknoParrot-Manager-ActionItems.txt"
            $saveDialog.Filter           = "Text files (*.txt)|*.txt|All files (*.*)|*.*"
            $saveDialog.OverwritePrompt  = $true
            if ($saveDialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
                $actionPath = $saveDialog.FileName
            } else {
                Write-Log "Action items: save dialog canceled, using default path."
            }
        } catch {
            Write-Log "Action items: save dialog failed, using default path -- $_"
        }
    }
    $gameNotesPathForReport = if ($gameNotesWritten) { $notesPath } else { '' }
    # Preview must not replace the saved Action Items report of the last real run.
    if (-not $dryRunActive) {
        $null = Write-TpmActionRequiredReports `
            -HasAnyAction:$hasAnyAction `
            -ActionPath $actionPath `
            -ManualRegData $manualRegData `
            -AmbiguousPaths $amb2 `
            -NotFound $nf `
            -DesignSkippedItems $designSkippedItems `
            -Result $result `
            -CompatibilityWarnings $compatWarnings `
            -ControlReadinessItems $controlReadinessItems `
            -GameNotesPath $gameNotesPathForReport `
            -OnboardingFollowUp $onboardingFollowUp.ToArray() `
            -RunId (Get-TpmSessionRunId)
    }
}

$registrationNextSteps = Get-TpmRegistrationNextSteps -HasActionRequired ([bool]$hasAnyAction) -ReShadeDone ([bool]$rsSetupDone) -DgVoodoo2Done ([bool]$dgSetupDone) -CrosshairsFolder (Join-Path $PSScriptRoot "Crosshairs\")
Write-TpmOutcome -Title '' -Next $registrationNextSteps.Next -DetailBlocks $registrationNextSteps.DetailBlocks -DetailsNote 'More help for the next steps.' -Unattended:$Unattended -DeferDetails

    # A newly registered Incredible Technologies game has no PostgreSQL settings yet: offer the existing PostgreSQL setup (issue #131).
    if (Invoke-TpmPostgresRegistrationOffer -UserProfilesDir $userProfilesDir -RegisteredCodes @($result.Registered | ForEach-Object { [string]$_.Code }) -Unattended:$Unattended -DryRun:$dryRunActive) {
        $pendingApplyMode = 'PostgresSetup'
        $pendingApplyForce = $false
        continue
    }

    if ($dryRunActive -and -not $Unattended) {
        Write-Host "  Preview finished. Read the results above, including any unresolved games." -ForegroundColor DarkCyan
        Write-Host "  No proposed game or profile changes have been applied." -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host "  Do you want to make these changes for real now?" -ForegroundColor Cyan
        Write-Host "  TeknoParrot Manager will perform a fresh scan before making any changes, to ensure" -ForegroundColor DarkCyan
        Write-Host "  nothing has changed since the preview." -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host "  [Y] Yes -- scan again, then apply the changes" -ForegroundColor Cyan
        Write-Host "  [N] No -- return to the main menu (nothing is changed)" -ForegroundColor Cyan
        # FIX110 (S-11): the preview's details are offered before the user authorizes real changes; the real run starts clean.
        $previewDetails = @(Get-TpmDeferredDetails)
        $applyChoices = @('Y', 'N')
        if ($previewDetails.Count -gt 0) {
            Write-Host "  [D] Details -- show what this preview found, then choose" -ForegroundColor Cyan
            $applyChoices += 'D'
        }
        $applyNow = Read-TpmChoice -Prompt "  Your choice" -Choices $applyChoices
        if ($applyNow -eq 'D') {
            Show-TpmDeferredDetails -Entries $previewDetails
            Write-Host ""
            Write-Host "  [Y] Yes -- scan again, then apply the changes" -ForegroundColor Cyan
            Write-Host "  [N] No -- return to the main menu (nothing is changed)" -ForegroundColor Cyan
            $applyNow = Read-TpmChoice -Prompt "  Your choice" -Choices @('Y', 'N')
        }
        if ($applyNow -eq "Y") {
            $pendingApplyMode = $mode
            $pendingApplyForce = $true
            if ($mode -eq 'AutoSync') {
                $pendingAutoSyncGames = $autoSyncTargetGames
                $pendingAutoSyncSelection = [pscustomobject]@{ Main = $onlySyncList; Supp = $onlySyncListSupp }
            }
            Write-Log "PreviewMode: user chose to apply for real -- re-entering $mode."
            continue
        }
    }

    Write-TpmUnhandledErrorsToLog -Where 'end of this run'
    Read-TpmReturnToMenu
} # end while ($true)
} catch {
    $errMsg  = $_.Exception.Message
    $errFull = "FATAL ERROR -- script aborted (unhandled): $($_.Exception)`nStack: $($_.ScriptStackTrace)"
    $errType = $_.Exception.GetType().FullName
    Write-Host ""
    Write-Host "============================================" -ForegroundColor Red
    Write-Host "  TeknoParrot Manager stopped unexpectedly" -ForegroundColor Red
    Write-Host "============================================" -ForegroundColor Red
    Write-Host "  Something happened that the program did not expect, so it stopped." -ForegroundColor Yellow
    Write-Host "  Everything it finished before this point is kept. The step that was" -ForegroundColor Yellow
    Write-Host "  running may not be finished. The log lists what it did." -ForegroundColor Yellow
    Write-Host ""
    Write-Host "  What to do: press Enter to close this window, then start" -ForegroundColor Cyan
    Write-Host "  TeknoParrot Manager again. You will be back at the menu." -ForegroundColor Cyan
    Write-Host "  If it happens again, send the log file to support." -ForegroundColor Cyan
    Write-Host ""
    Write-Host "  Details:" -ForegroundColor DarkGray
    Write-Host ("    {0}" -f $errMsg) -ForegroundColor DarkGray
    Write-Host ("    Log file: {0}" -f $logPath) -ForegroundColor DarkGray
    try { Write-Log $errFull } catch {}
    try { Write-TpmUnhandledErrorsToLog -Where 'unexpected stop' } catch {}
    try { [void](Add-TpmRegistrationLedgerFatal -Message $errMsg -ExceptionType $errType) } catch {}
    if ($isPostgresRecoveryResume) {
        # FIX39: the elevated child never waits for a key press. It reports to the
        # original window (change unknown unless recorded) and closes by itself.
        Exit-PostgresRecoveryResume -Message 'TeknoParrot Manager stopped the PostgreSQL setup because of an unexpected error.' -UnexpectedError
    }
    if (-not $Unattended) { [void](Read-Host "  Press Enter to exit") }
    exit 1
}
finally {
    try { Write-TpmUnhandledErrorsToLog -Where 'exit' } catch {}
    # FIX43: every way out of the main block (Q at the menu, an exit statement, a fatal error, Ctrl+C) stops the live
    # progress writer. A writer left running kept powershell.exe -File alive after Q in a real console window. Earlier
    # exits (before this block) are covered by the module's own PowerShell.Exiting handler and its daemon writer thread.
    # Import-TpmProgressModule imports inside a function, so the module's commands may not be visible at script scope:
    # the call goes through the module object itself, never through a command name resolved here.
    if ($script:TpmProgressModuleImported) {
        try {
            foreach ($progressModule in @(Get-Module -Name TpmProgress)) {
                & $progressModule { Close-TpmProgressSession -WaitMs 5000 }
            }
        } catch {
            try { Write-Log ('Progress shutdown at exit failed: {0}' -f $_.Exception.Message) } catch {}
        }
    }
}
